INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Au commencement Dieu créa les cieux et la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Et la terre était le désert et le vide, et il y avait des ténèbres à la surface de l\'abîme, mais l\'Esprit de Dieu posait couvant à la surface des eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Et Dieu dit: Que la lumière soit! Et la lumière fut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Et Dieu vit que la lumière était bonne. Et Dieu sépara la lumière et les ténèbres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Et Dieu nomma la lumière jour, et nomma les ténèbres nuit. Et il y eut soir, et il y eut matin: premier jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Puis Dieu dit: Qu\'il y ait un firmament entre les eaux, et qu\'il sépare les eaux les unes des autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Et Dieu fit le firmament, et sépara les eaux qui sont au-dessous du firmament, des eaux qui sont au-dessus du firmament. Et ainsi fut. Et Dieu nomma le firmament cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Et il y eut soir, et il y eut matin: second jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Puis Dieu dit: Que les eaux se rassemblent sous les cieux en un lieu unique, et que le sec apparaisse. Et ainsi fut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Et Dieu nomma le sec terre, et nomma l\'amas des eaux mer. Et Dieu vit que cela était bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Puis Dieu dit: Que la terre fasse germer la verdure, la plante portant graine, l\'arbre fruitier donnant selon son espèce un fruit qui ait en lui sa graine, au-dessus de la terre. Et ainsi fut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Et la terre produisit verdure, plante portant graine selon son espèce, et arbre donnant du fruit ayant en lui sa graine selon son espèce. Et Dieu vit que cela était bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Et il y eut soir, et il y eut matin: troisième jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Puis Dieu dit: Qu\'il y ait des luminaires au firmament des cieux pour séparer le jour et la nuit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'et qu\'ils servent pour signes, et époques, et jours et années, et soient pour luminaires au firmament des cieux pour luire sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Et ainsi fut. Et Dieu fit les deux grands luminaires, le grand luminaire pour présider au jour et le petit luminaire pour présider à la nuit, et les étoiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Et Dieu les plaça au firmament des cieux pour luire sur la terre');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'et présider au jour et à la nuit et pour séparer la lumière et les ténèbres. Et Dieu vit que cela était bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Et il y eut soir, et il y eut matin: quatrième jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Puis Dieu dit: Que les eaux fourmillent d\'une multitude d\'animaux vivants, et que les volatiles volent au-dessus de la terre au firmament des cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Et Dieu créa les grands poissons de mer et tous les animaux vivants qui se meuvent, dont les eaux fourmillent, selon leurs espèces, et tous les volatiles à ailes selon leurs espèces. Et Dieu vit que cela était bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Et Dieu les bénit en disant: Soyez féconds, et vous multipliez, et remplissez les eaux dans les mers et que les volatiles multiplient sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Et il y eut soir et il y eut matin: cinquième jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Puis Dieu dit: Que la terre produise des animaux vivants selon leurs espèces, des bestiaux et des reptiles, et des bêtes terrestres selon leurs espèces. Et ainsi fut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Et Dieu fit les animaux terrestres selon leurs espèces et les bestiaux selon leurs espèces et tous les reptiles du sol selon leurs espèces. Et Dieu vit que cela était bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Puis Dieu dit: Faisons l\'homme à notre image, à notre ressemblance, et qu\'ils dominent sur les poissons de la mer et sur les oiseaux des cieux et sur les bestiaux et sur toute la terre et sur tous les reptiles qui se meuvent sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Et Dieu créa l\'homme à son image: à l\'image de Dieu Il le créa! Il les créa mâle et femelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Et Dieu les bénit, et Dieu leur dit: Soyez féconds et vous multipliez, et remplissez la terre et vous la soumettez, et dominez sur les poissons de la mer et sur les oiseaux des cieux et sur tous les animaux qui se meuvent sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Et Dieu dit: Voici, je vous donne toute plante portant graine, qui se trouve à la surface de toute la terre, et tout arbre ayant un fruit qui porte graine: ils vous serviront d\'aliment;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'et à tous les animaux de la terre, et à tous les oiseaux des cieux, et à tout ce qui se meut sur la terre ayant âme vivante, [je donne] toute la verdure des plantes pour aliment. Et ainsi fut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Et Dieu vit tout ce qu\'il avait fait; et voici, cela était très bon. Et il y eut soir et il y eut matin: sixième jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Et ainsi furent achevés les cieux et la terre et toute leur armée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Et Dieu acheva le septième jour son œuvre qu\'il avait faite, et Il se reposa le septième jour de toute son œuvre qu\'Il avait faite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Et Dieu bénit le septième jour et le consacra, parce que ce jour-là Il se reposa de toute son œuvre qu\'il avait créée en agissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'C\'est ici l\'histoire des cieux et de la terre lors de leur création, lorsque l\'Éternel Dieu fit les cieux et la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Or, tous les arbustes des champs n\'étaient point encore sur la terre, et toutes les plantes des champs n\'avaient pas germé; car l\'Éternel Dieu n\'avait pas encore fait pleuvoir sur la terre; et il n\'existait point d\'homme pour travailler le sol.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Mais un brouillard s\'élevait de la terre et imbibait toute la surface du sol.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Alors l\'Éternel Dieu forma l\'homme de la poudre de la terre, et Il souffla dans ses narines l\'haleine de la vie, et l\'homme devint une personne vivante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Et l\'Éternel Dieu planta un jardin en Eden vers l\'Orient, et Il y établit l\'homme qu\'il avait formé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Et l\'Éternel Dieu fit germer du sol toutes sortes d\'arbres agréables à la vue et bons pour la nourriture, et l\'arbre de la vie au milieu du jardin et l\'arbre de la connaissance du bien et du mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Et un fleuve sortait d\'Eden pour arroser le jardin; et depuis là il se divisait et formait quatre bras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Le nom du premier est Pison: il entoure tout le pays de Havila, où est l\'or;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'et l\'or de ce pays-là est bon: là se trouve le bdellium et la pierre d\'onyx.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Et le nom du second fleuve est Gihon: il entoure tout le pays de Cus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Et le nom du troisième fleuve est Hiddekel; il coule à l\'orient d\'Assur. Et le quatrième fleuve c\'est le Phrath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Et l\'Éternel Dieu prit l\'homme, et l\'établit dans le jardin d\'Eden pour le cultiver et pour le garder.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Et l\'Éternel Dieu imposa un commandement à l\'homme en ces termes: Tu peux manger de tous les arbres du jardin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'mais de l\'arbre de la connaissance du bien et du mal, tu n\'en mangeras pas, car le jour où tu en mangeras, de mort tu mourras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Et l\'Éternel Dieu dit: Il n\'est pas bon que l\'homme soit seul; je lui ferai une aide qui lui corresponde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Puis l\'Éternel Dieu forma de la terre tous les animaux des champs et tous les oiseaux des cieux, et Il les amena à l\'homme pour voir quel nom il leur donnerait, et tous les noms que l\'homme leur donnerait, aux animaux vivants, devaient rester leurs noms.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Et l\'homme nomma de noms tous les bestiaux et tous les oiseaux des cieux, et toutes les bêtes des champs; mais pour l\'homme il ne trouva pas d\'aide qui lui correspondît.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Alors l\'Éternel Dieu fit tomber un profond sommeil sur l\'homme, qui s\'endormit; et Il prit l\'une de ses côtes, et referma les chairs en son lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Et l\'Etemel Dieu bâtit en femme la côte qu\'il avait prise de l\'homme, et Il l\'amena à l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Alors l\'homme dit: Cette fois, c\'est os de mes os, chair de ma chair! On l\'appellera femme-d\'homme, parce qu\'elle a été prise de l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'C\'est pourquoi un homme quittera son père et sa mère pour s\'attacher à sa femme, et ils formeront une seule chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Et ils étaient les deux nus, l\'homme et sa femme, et ils n\'en avaient point de honte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Or le serpent était plus rusé que tous les animaux des champs qu\'avait faits l\'Éternel Dieu; et il dit à la femme: Dieu serait allé jusqu\'à dire: Vous ne mangerez d\'aucun des arbres du jardin!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Et la femme dit au serpent: Nous mangeons du fruit des arbres du jardin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'mais du fruit de l\'arbre qui est au milieu du jardin, Dieu a dit: vous n\'en mangerez pas et n\'y toucherez pas, de peur que vous ne mouriez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Alors le serpent dit à la femme: Non, non, vous ne mourrez point;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'mais Dieu sait que du jour où vous en mangerez vos yeux seront ouverts et vous serez comme des dieux connaissant le bien et le mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Et la femme vit que l\'arbre était bon à manger et qu\'il avait des appas pour les yeux et qu\'il était délicieux à contempler; puis elle prit de son fruit, et en mangea et en donna aussi à son mari qui en mangea.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Alors les yeux de l\'un et de l\'autre furent ouverts, et ils s\'aperçurent qu\'ils étaient nus, et ils cousirent des feuilles de figuier pour se faire des ceintures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Et ils entendirent la voix de l\'Éternel Dieu qui parcourait le jardin au moment du vent du jour, et l\'homme et sa femme se cachèrent devant l\'Éternel Dieu parmi les arbres du jardin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Mais l\'Éternel Dieu appela l\'homme et lui dit: Où es-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Et il répondit: J\'ai entendu ta voix dans le jardin, et j\'ai eu peur, parce que je suis nu, et je me suis caché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Et Il dit: Qui t\'a découvert que tu es nu? As-tu mangé de l\'arbre dont je t\'avais défendu de manger?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Et l\'homme répondit: La femme que tu m\'as donnée pour compagne, c\'est elle qui m\'a donné [du fruit] de l\'arbre, et j\'ai mangé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Alors l\'Éternel Dieu dit à la femme: Qu\'as-tu fait-là? Et la femme répondit: Le serpent m\'a séduite, et j\'ai mangé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Alors l\'Éternel Dieu dit au serpent: Puisque tu as fait cela, sois maudit de tous les animaux et de toutes les bêtes des champs; tu marcheras sur ton ventre et tu te nourriras de la poussière tout le temps de ta vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Et je mets l\'inimitié entre toi et la femme, et entre ta postérité et sa postérité; celle-ci s\'attaquera à ta tête, et tu t\'attaqueras à son talon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'A la femme Il dit: Je rendrai tes grossesses grandement pénibles; c\'est en travail que tu enfanteras des enfants; et tes désirs tendront vers ton mari et il te tiendra sous sa dépendance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Et Il dit à Adam: Parce que tu as prêté l\'oreille à la voix de ta femme, et que tu as mangé de l\'arbre au sujet duquel je t\'avais donné cet ordre: Tu n\'en mangeras point! le sol sera maudit à cause de toi; c\'est avec labeur que tu en tireras ta nourriture tout le temps de ta vie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'et il te produira des ronces et des chardons, et tu mangeras les plantes des champs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'tu mangeras ton pain à la sueur de ton front, jusqu\'à ce que tu sois rendu à la terre; car c\'est d\'elle que tu as été tiré; car tu es poudre et tu seras rendu à la poudre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Et Adam nomma sa femme Ève; car elle fut la mère de tous les vivants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Et l\'Éternel Dieu fit pour Adam et pour sa femme des tuniques de fourrure et Il les en vêtit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Et l\'Éternel Dieu dit: Voici, l\'homme est devenu comme l\'un de nous pour la connaissance du bien et du mal, mais maintenant, de peur qu\'il n\'étende la main et ne prenne aussi de l\'arbre de la vie et qu\'il n\'en mange et ne vive éternellement...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Alors l\'Éternel Dieu l\'envoya loin du jardin d\'Eden travailler le sol d\'où il avait été tiré,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'et Il bannit l\'homme et posta à l\'orient du jardin d\'Eden les Chérubins armés de la flamme de l\'épée agitée pour garder le chemin de l\'arbre de vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Et Adam connut Ève, sa femme, et elle conçut et enfanta Caïn, et elle dit: J\'ai gagné un homme avec l\'aide de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Puis elle enfanta encore son frère Abel. Et Abel fut pasteur de brebis, et Caïn agriculteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Et au bout d\'un certain temps Caïn offrit à l\'Éternel une oblation de fruits de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Et Abel offrit lui aussi des premiers-nés de ses troupeaux et de leur graisse. Et l\'Éternel arrêta ses regards sur Abel et sur son offrande;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'mais il n\'arrêta point ses regards sur Caïn et son offrande. Et Caïn fut très irrité, et il avait le visage abattu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Alors l\'Éternel dit à Caïn: Pourquoi t\'irrites-tu et as-tu le visage abattu? N\'est-ce pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Si tu fais bien, tu as la tête levée, mais si tu ne fais pas bien, le péché se rase à la porte, et ses désirs sont tendus vers toi; mais tu dois le dominer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Et Caïn parla à son frère Abel, et il arriva que, comme ils étaient aux champs, Caïn se dressa contre son frère Abel et le tua.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Alors l\'Éternel dit à Caïn: Où est Abel, ton frère? Et il répondit: Je ne sais pas: suis-je le gardien de mon frère?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Et Dieu: Qu\'as-tu fait? La voix du sang de ton frère crie de la terre jusqu\'à moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Dès-là sois maudit de la terre qui a ouvert sa bouche pour recevoir de ta main le sang de ton frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Quand tu travailleras le sol, il ne t\'accordera plus sa vertu; tu seras errant et vagabond sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Et Caïn dit à l\'Éternel: Ma peine est trop grande pour la supporter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Voici, tu m\'as banni en ce jour de la contrée, et loin de ta face il faut me cacher, et je me trouve errant et vagabond sur la terre, et quiconque me trouvera me tuera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Et l\'Éternel lui dit: Aussi, qui que ce soit qui tue Caïn, il sera vengé sept fois. Et l\'Éternel assura Caïn par un signe que quiconque le trouverait, ne le tuerait point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Et Caïn sortit de la présence de l\'Éternel et séjourna dans la région de Nod (exil) à l\'orient d\'Eden.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Et Caïn connut sa femme, et elle devint enceinte et enfanta Henoch. Et il bâtit une ville qu\'il nomma du nom de son fils Henoch.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Et à Henoch naquit Hirad, et Hirad engendra Mahujaël, et Mahujaël engendra Methusaël, et Methusaël engendra Lémech.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Et Lémech prit deux femmes: le nom de l\'une était Hada et le nom de l\'autre Tsilla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Et Hada enfanta Jabal: c\'est lui qui fut le père de ceux qui vivent sous des tentes et avec des troupeaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Et le nom de son frère était Jubal: c\'est lui qui fut le père de tous ceux qui jouent du luth et de la cornemuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Et Tsilla de son côté enfanta Thubal-Caïn qui forgeait tous les instruments d\'airain et de fer. Et la sœur de Thubal-Caïn était Nahuma.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Et Lémech dit à ses femmes: Hada et Tsilla, entendez ma voix, Femmes de Lémech, écoutez ma parole! C\'est que je tue l\'homme qui me fait une blessure, Et le jeune homme qui me fait une piqûre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'C\'est que, sept fois Caïn a-t-il été vengé, Soixante-dix-sept fois Lémech saura l\'être.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Et Adam connut encore sa femme, et elle enfanta un fils, et elle lui donna le nom de Seth (remplaçant) « car Dieu m\'a constitué une autre postérité en place d\'Abel, parce que Caïn lui a donné la mort. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Et il naquit aussi un fils à Seth, et il l\'appela du nom de Enos. C\'est alors que l\'on commença à invoquer le nom de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'C\'est ici le livre de l\'histoire d\'Adam. Lorsque Dieu créa l\'homme, Il le fit ressemblant à Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Il les créa mâle et femelle, et les bénit et leur donna le nom a d\'homme lors de leur création.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Et Adam ayant vécu cent trente ans engendra [un fils] de sa ressemblance, à son image, et lui donna le nom de Seth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Et les jours d\'Adam après la naissance de Seth, furent de huit cents ans; et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Et tout le temps que vécut Adam fut de neuf cent trente ans, puis il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Et Seth ayant vécu cent cinq ans engendra Enos.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Et après la naissance d\'Enos, Seth vécut huit cent-sept ans; et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Et tous les jours de Seth furent neuf cent douze ans, puis il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Et Enos ayant vécu quatre-vingt-dix ans engendra Keinan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Et après la naissance de Keinan, Enos vécut huit cent quinze ans; et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Et tous les jours d\'Enos furent neuf cent-cinq ans; puis il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Et Keinan ayant vécu soixante-dix ans engendra Mahalaleël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Et après la naissance de Mahalaleël, Keinan vécut huit cent quarante ans, et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Et tous les jours de Keinan furent neuf cent-dix ans, puis il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Et Mahalaleël ayant vécu soixante-cinq ans engendra Jared.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Et après la naissance de Jared, Mahalaleël vécut huit cent trente ans, et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Et tous les jours de Mahalaleël furent huit cent quatre-vingt-quinze ans, puis il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Et Jared ayant vécu cent soixante-deux ans engendra Henoch.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Et après la naissance de Henoch, Jared vécut huit cents ans, et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Et tous les jours de Jared furent neuf cent soixante-deux ans, puis il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Et Henoch ayant vécu soixante-cinq ans engendra Methusalah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Et après la naissance de Methusalah, Henoch marcha avec Dieu trois cents ans, et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Et tous les jours de Henoch furent trois cent soixante-cinq ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Et Henoch marcha avec Dieu, et il disparut, parce que Dieu le prit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Et Methusalah ayant vécu cent quatre-vingt-sept ans engendra Lémech, et après la naissance de Lémech,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Methusalah vécut sept cent quatre-vingt-deux ans, et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Et tous les jours de Methusalah furent neuf cent soixante-neuf ans, puis il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Et Lémech ayant vécu cent quatre-vingt-deux ans engendra un fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Et il lui donna le nom de Noé en disant: Celui-ci nous consolera du pénible labeur de nos mains, qui procède de la terre que l\'Éternel a maudite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Et après la naissance de Noé, Lémech vécut cinq cent quatre-vingt-quinze ans, et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Et tous les jours de Lémech furent sept cent soixante-dix-sept ans, puis il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Et Noé étant âgé de cinq cents ans engendra Sem, Cham et Japheth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Et lorsque les hommes eurent commencé à se multiplier sur la face de la terre, et que des filles leur furent nées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'les fils de Dieu virent que les filles de l\'homme étaient belles, et ils en prirent pour femmes parmi celles qu\'ils préféraient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Alors l\'Éternel dit: Mon Esprit ne régira pas éternellement l\'intérieur de l\'homme; par suite de son égarement il [n\'] est [plus que] chair; et sa vie sera de cent vingt ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Les géants existaient sur la terre en ce temps-là; et aussi, après que les fils de Dieu se furent approchés des filles des hommes, celles-ci leur donnèrent des fils qui sont ces héros fameux dès l\'antiquité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Et l\'Éternel vit que la méchanceté des hommes était grande et générale sur la terre, et que toutes les pensées formées par leur cœur n\'étaient toujours que pure malice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Et l\'Éternel se repentit d\'avoir fait l\'homme sur la terre, et Il en ressentait de la douleur en son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Alors l\'Éternel dit: Je ferai disparaître de la face de la terre l\'homme que j\'ai créé, à partir de l\'homme jusqu\'au bétail et aux reptiles et aux oiseaux des cieux; car je me repens de les avoir faits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Mais Noé trouva grâce aux yeux de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'C\'est ici l\'histoire de Noé. Noé était un homme juste, accompli parmi les hommes de son temps. Noé marchait avec Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Et Noé engendra trois fils, Sem, Cham et Japheth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Et la terre se corrompait à la face de Dieu, et la terre se remplissait de crimes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Et Dieu regarda la terre, et voici, elle était corrompue, toute chair avait corrompu ses voies sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Alors Dieu dit à Noé: La fin de toute chair est arrêtée par devers moi, car la terre est remplie de crimes par eux, et voici je vais les détruire avec la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Fais-toi une arche de bois résineux; tu feras l\'arche par compartiments, et tu l\'enduiras en dedans et en dehors de résine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Et voici comment tu la feras: elle aura trois cents coudées de longueur, cinquante coudées de largeur et trente coudées de hauteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Tu y pratiqueras un jour auquel tu donneras une coudée à partir d\'en-haut, et tu établiras une porte au côté de l\'arche; tu la composeras d\'un bas, d\'un second et d\'un troisième étage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Car, voici, je vais faire arriver sur la terre le déluge d\'eaux pour détruire toute chair ayant souffle de vie sous le ciel; tout ce qui est sur la terre périra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Mais je dresse mon alliance avec toi, et tu entreras dans l\'arche, toi et tes fils et ta femme et les femmes de tes fils avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Et de tout ce qui vit, de toute chair, tu introduiras avec toi dans l\'arche une paire de tous, pour les conserver en vie avec toi; ce sera un mâle et une femelle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'des oiseaux selon leurs espèces, et des bestiaux selon leurs espèces et de tous les reptiles de la terre selon leurs espèces, une paire de chacun d\'eux se retirera vers toi pour être conservés en vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Cependant munis-toi de tout aliment qui se mange, et fais tes provisions, afin qu\'il y ait nourriture pour toi et pour eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Et Noé exécuta tous les ordres que Dieu lui donna; ainsi fit-il.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Et l\'Éternel dit à Noé: Entre dans l\'arche, toi et toute ta maison; car je t\'ai vu juste devant moi dans cette génération.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'De tous les animaux purs tu en prendras par groupes de sept, un mâle et sa femelle; et des animaux qui ne sont pas purs, par paire, un mâle et sa femelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'et des oiseaux des deux aussi par groupes de sept, mâle et femelle, afin de faire revivre la race sur la face de toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Car encore sept jours, et je ferai pleuvoir sur la terre quarante jours et quarante nuits et j\'exterminerai tous les êtres que j\'ai faits, de la face de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Et Noé exécuta tous les ordres que l\'Éternel lui donna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Or Noé était âgé de six cents ans, quand le déluge d\'eaux fut sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Alors Noé et ses fils et sa femme et les femmes de ses fils avec lui entrèrent dans l\'arche en face des eaux du déluge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Des animaux purs et des animaux qui ne sont pas purs, et des oiseaux et de tout ce qui se meut sur la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'il entra paire par paire auprès de Noé dans l\'arche, un mâle et une femelle conformément à l\'ordre que Dieu avait donné à Noé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Et sept jours après les eaux du déluge couvraient la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'La six centième année de la vie de Noé, le second mois, le dix-septième jour du mois, en ce jour-là toutes les sources du grand abîme firent éruption, et les écluses des cieux s\'ouvrirent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'et il y eut pluie sur la terre quarante jours et quarante nuits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Ce jour-là même Noé et Sem et Cham et Japheth, fils de Noé, et la femme de Noé, et les trois femmes de ses fils avec eux entrèrent dans l\'arche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'eux et tous les animaux selon leurs espèces, et tous les bestiaux selon leurs espèces, et tous les reptiles qui rampent sur la terre selon leurs espèces, et tous les volatiles selon leurs espèces, tout oiseau, tout ce qui est ailé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Et de toute chair ayant esprit de vie il en vint paire par paire auprès de Noé dans l\'arche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'et ceux qui entraient étaient mâle et femelle de toute chair selon l\'ordre que Dieu lui avait donné, et l\'Éternel ferma sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Et le déluge se forma pendant quarante jours et quarante nuits, et les eaux crûrent et soulevèrent l\'arche qui se trouva élevée au-dessus de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Et les eaux devinrent très grosses et très grandes sur la terre, et l\'arche voguait à la surface des eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Et les eaux grossirent de plus en plus sur la terre et recouvrirent toutes les hautes montagnes qui sont sous le ciel entier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Jusqu\'à quinze coudées au-dessus les eaux montèrent et les montagnes furent couvertes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Alors périt toute chair, tout ce qui se meut sur la terre en oiseaux, en bétail et en animaux et en reptiles rampant sur la terre et tous les hommes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'tout ce qui avait dans ses narine un souffle d\'esprit de vie, tout ce qui était sur la terre sèche, mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Et ainsi furent détruits tous les êtres qui étaient sur la face de la terre, de l\'homme aux animaux, aux reptiles et aux oiseaux des cieux; et ils furent exterminés de la terre. Et il ne survécut que Noé et ce qui était avec lui dans l\'arche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Et la hauteur des eaux se maintint sur la terre pendant cent cinquante jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Et Dieu se souvint de Noé et de tous les animaux et de tout le bétail qui était avec lui dans l\'arche, et Dieu fit passer un vent sur la terre et les eaux s\'affaissèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Et les sources de l\'abîme et les écluses des cieux se fermèrent, et la pluie fut arrêtée dans les cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Et les eaux quittaient la terre s\'en allant et se retirant et les eaux diminuèrent au bout de cent cinquante jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Et le septième mois, le dix-septième jour du mois l\'arche s\'arrêta sur les monts Ararat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Et les eaux s\'en allèrent et décrurent jusqu\'au dixième mois; le dixième mois, le premier jour du mois, les cimes des monts furent visibles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Et au bout de quarante jours Noé ouvrit la fenêtre de l\'arche qu\'il avait faite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Et il mit en liberté le corbeau, lequel sortit, partant et revenant jusqu\'à ce que les eaux eussent tari sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Et il mit en liberté la colombe pour voir si les eaux étaient disparues de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Mais la colombe ne trouva pas une place où poser la plante de son pied, et elle revint à lui dans l\'arche, parce que les eaux couvraient toute la face de la terre; et il étendit la main et la prit et la retira à lui dans l\'arche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Et il attendit encore sept autres jours, et de nouveau il laissa la colombe s\'envoler de l\'arche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Alors la colombe revint à lui au temps du soir; et voilà qu\'une feuille fraîche d\'olivier était dans son bec! et Noé comprit que les eaux étaient disparues de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Puis il attendit encore sept autres jours, et il donna la liberté à la colombe; mais elle ne revint plus à lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Et l\'année six cent et un, le premier mois, le premier jour du mois les eaux avaient laissé la terre à sec, et Noé enleva la couverture de l\'arche, et il regarda, et voici, la face du sol se desséchait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Et le second mois, le dix-septième jour du mois, la terre était sèche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Et Dieu parla à Noé en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Sors de l\'arche, toi et ta femme et tes fils et les femmes de tes fils avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Tous les animaux de toute chair qui sont avec toi, oiseaux, bétail et tout reptile rampant sur la terre, fais-les sortir avec toi, et qu\'ils pullulent sur la terre et soient féconds et se multiplient sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Et Noé sortit, et ses fils et sa femme et les femmes de ses fils avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Tous les animaux, tous les reptiles et tous les oiseaux, tout ce qui se meut sur la terre, selon leurs familles sortirent de l\'arche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Alors Noé édifia un autel à l\'Éternel, et il prit de tous les animaux purs et de tous les oiseaux purs et offrit des holocaustes sur l\'autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Et l\'Éternel odora le parfum suave, et l\'Éternel dit en son cœur: Désormais je ne maudirai plus la terre à cause de l\'homme; car les imaginations du cœur de l\'homme sont mauvaises dès sa jeunesse; et désormais je ne frapperai plus tous les vivants comme j\'ai fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'A l\'avenir, tant que la terre sera, les semailles et la moisson, la froidure et la chaleur, l\'été et l\'hiver, le jour et la nuit ne chômeront point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Alors Dieu bénit Noé et ses fils, et leur dit: Soyez féconds et vous multipliez et remplissez la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Et soyez craints et redoutés de tous les animaux de la terre et de tous les oiseaux des cieux, de tout ce qui rampe sur le sol et de tous les poissons de la mer: ils sont mis dans vos mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Tout ce qui se meut ayant vie, vous servira d\'aliment; aussi bien que la verdure des plantes, je vous donne tout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Ce n\'est que la chair dans son âme, son sang, que vous ne mangerez point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Et c\'est votre sang seul qu\'en faveur de votre vie je redemanderai; je le redemanderai à tous les animaux, et je redemanderai la vie de l\'homme à l\'homme, à son frère, quel qu\'il soit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Quiconque versera le sang de l\'homme, par l\'homme son sang sera versé, car Dieu a fait l\'homme à son image.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Pour vous, soyez féconds et vous multipliez, et pullulez sur la terre et vous y multipliez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Et Dieu dit à Noé et à ses fils avec lui:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Pour moi, voici, j\'érige mon alliance avec vous et avec votre race après vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'et avec tous les êtres vivants qui sont à vos côtés, oiseaux, bétail et toute bête de la terre qui est à vos côtés, tous ceux qui sont sortis de l\'arche avec vous, de tous les animaux de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'J\'érige donc mon alliance avec vous à cet effet que dorénavant toute chair ne sera point exterminée par les eaux du déluge et que dorénavant il n\'y aura plus de déluge pour détruire la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Et Dieu dit: Voici le signe de l\'alliance que j\'institue entre moi et vous et tous les êtres vivants qui sont à vos côtés, pour la suite des âges à jamais:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'je place mon arc dans la nuée pour qu\'il devienne un signe d\'alliance entre moi et la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Et lorsque je ferai surgir les nuées sur la terre, et que mon arc apparaîtra dans la nuée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'alors je me rappellerai l\'alliance qui existe entre moi et vous et tous les êtres vivant en toute chair, et [qui stipule] que les eaux ne deviendront plus un déluge pour détruire toute chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Et l\'arc étant dans la nuée, je le regarderai pour me rappeler l\'alliance éternelle qui existe entre Dieu et tout être vivant en toute chair qui se trouve sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Et Dieu dit à Noé: Tel est le signe de l\'alliance que j\'érige entre moi et toute chair qui se trouve sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Et les fils de Noé qui sortirent de l\'arche étaient Sem, Cham et Japheth; or Cham était le père de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Ce sont là les trois fils de Noé, et c\'est d\'eux qu\'est issue la population répandue sur toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Et Noé commença à être agriculteur et il planta de la vigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Et il but du vin, et il se trouva ivre et il se découvrit au milieu de sa tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Et Cham, père de Canaan, vit la nudité de son père, et le redit à ses deux frères dehors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Alors Sem et Japheth prirent le manteau et le mirent les deux sur leurs épaules, et marchèrent à reculons et couvrirent la nudité de leur père; mais leur visage était tourné, et ils ne virent point la nudité de leur père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Et lorsque Noé se réveilla de son ivresse, il apprit ce que lui avait fait son fils cadet;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'alors il dit: Maudit soit Canaan, Serviteur des serviteurs qu\'il soit pour ses frères!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Puis il dit: Béni soit l\'Éternel, Dieu de Sem, et que Canaan soit son serviteur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Que Dieu donne de l\'extension à Japheth, et qu\'il habite dans les tentes de Sem, et que Canaan devienne leur serviteur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Et après le déluge Noé vécut trois cent cinquante ans;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'et la totalité des jours de Noé fut neuf cent cinquante ans, puis il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Et c\'est ici l\'histoire des fils de Noé, Sem, Cham et Japheth. Et il leur naquit des fils après le déluge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Les fils de Japheth sont: Gomer et Magog et Madai et Javan et Thubal et Mésech et Thiras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Et les fils de Gomer: Askénas et Riphat et Thogarma.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Et les fils de Javan: Elisah et Tharsis, et Dodanim:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'd\'eux sont issus ceux qui se sont répandus sur les terres maritimes des nations dans les pays qu\'ils occupent, chacun selon sa langue, sa filiation, sa nationalité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Et les fils de Cham: Cus et Mistraïm et Phut et Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Et les fils de Cus: Saba et Havila et Sabtha et Rahema et Sabtcha. Et les fils de Rahemah: Séba et Dedan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Cus engendra Nemrod; c\'est lui qui commença à être un potentat sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'C\'est lui qui devint un puissant chasseur à la face de l\'Éternel; c\'est pourquoi il se dit: Comme Nemrod, puissant chasseur à la face de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Et le commencement de son empire fut Babel et Erech et Accad et Chalneh au pays de Sinear.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'De ce pays-là il marcha sur Assur, et bâtit Ninive et Rechoboth-Hir et Calah');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'et Resen entre Ninive et Calah; c\'est la grande ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Et Mitsraïm engendra les Ludim et les Hanamin et les Lehabim et les Naphthaïm');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'et les Pathrusim et les Casluhim, d\'où sont sortis les Philistim et les Caphthorim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Et Canaan engendra Sidon, son premier-né, et Heth');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'et Jebusi et Amori et Gergesi');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'et Hivi et Arki et Sini');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'et Arvadi et Tsemari et Hamathi, et ensuite les familles des Cananéens s\'étendirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Et les limites des Cananéens furent de Sidon du côté de Gérar à Gaza, du côté de Sodome et de Gomorrhe et d\'Adama et de Tseboïm à Lasah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Tels sont les fils de Cham selon leurs familles, selon leurs langues, dans leurs pays, dans leurs peuplades.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Et il naquit aussi des fils à Sem, père de tous les fils de Héber, frère aîné de Japheth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Les fils de Sem: Heilam et Assur et Arphachsad et Lud et Aram.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Et les fils de Aram: Uz et Hul et Gether et Mas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Et Arphachsad engendra Sélach, et Sélach engendra Héber.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Et à Héber il naquit deux fils: le nom de l\'un était Péleg, parce que de son temps la terre fut partagée, et le nom de son frère était Joctan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Et Joctan engendra Almodad et Séleph et Hatsarmaveth, et Jerach');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'et Adoram et Uzal et Dicla');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'et Hobal et Abimaël et Séba');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'et Ophir et Havila et Jobab, tous ceux-ci fils de Joctan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Et leur habitation était depuis Mesa du côté de Sephar, la montagne de l\'orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Ce sont là les fils de Sem selon leurs familles, selon leurs langues, dans leurs pays, selon leurs tribus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Telles sont les familles des fils de Noé selon leurs familles, dans leurs tribus; et d\'eux sont sortis les peuples qui se sont répandus sur la terre après le déluge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Et une seule langue et un seul langage existait sur toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Et il arriva que dans leurs migrations à l\'Orient ils rencontrèrent une plaine au pays de Sinear, et ils s\'y fixèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Et ils se dirent l\'un à l\'autre: Allons! fabriquons des briques, et nous les ferons cuire. Et les briques leur tinrent lieu de pierres, et l\'asphalte leur tint lieu de mortier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Et ils dirent: Allons! bâtissons-nous une ville et une tour dont la cime touche au ciel, et faisons-nous un nom, afin que nous ne soyons pas dispersés sur la face de toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Alors l\'Éternel descendit pour voir la ville et la tour que bâtissaient les fils des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Et l\' Éternel dit: Voici, c\'est un seul peuple et une seule langue pour eux tous, et c\'est le commencement de leur entreprise, et maintenant ils ne seraient entravés dans rien de ce qu\'ils projettent d\'exécuter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Allons! descendons et confondons là leur langage, afin que l\'un n\'entende plus le langage de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Et l\'Éternel les dispersa ainsi de là sur la face de toute la terre, et ils discontinuèrent de bâtir la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'C\'est pour cela qu\'on l\'appela du nom de Babel; car c\'est là que l\'Éternel confondit le langage de toute la terre, et c\'est de là que l\'Éternel les dispersa sur la face de toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'C\'est ici l\'histoire de Sem. – Sem était âgé de cent ans lorsqu\'il engendra Arphachsad, deux ans après le déluge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Et après la naissance d\'Arphachsad, Sem vécut cinq cents ans et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Et Arphachsad avait trente-cinq ans de vie lorsqu\'il engendra Sélach.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Et après la naissance de Sélach, Arphachsad vécut quatre cent-trois ans, et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Et Selach avait trente ans de vie lorsqu\'il engendra Héber.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Et après la naissance de Héber, Sélach vécut quatre cent-trois ans, et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Et Héber vécut trente-quatre ans, puis il engendra Péleg.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Et après la naissance de Péleg, Héber vécut quatre cent trente ans, et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Et Péleg vécut trente ans, puis il engendra Régu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Et après la naissance de Régu, Péleg vécut deux cent-neuf ans, et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Et Régu vécut trente-deux ans, puis il engendra Sérug.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Et après la naissance de Sérug, Régu vécut deux cent-sept ans, et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Et Sérug vécut trente ans, puis il engendra Nachor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Et après la naissance de Nachor, Sérug vécut deux cents ans, et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Et Nachor vécut vingt-neuf ans, puis il engendra Thérach.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Et après la naissance de Thérach, Nachor vécut cent dix-neuf ans, et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Et Thérach ayant soixante-dix ans de vie engendra Abram, Nachor et Haran.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Et c\'est ici l\'histoire de Thérach. – Thérach engendra Abram, Nachor et Haran, et Haran engendra Lot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Et Haran mourut avant Thérach, son père, au pays de sa naissance, à Ur en Chaldée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Et Abram et Nachor prirent femme: le nom de la femme d\'Abram était Saraï, et le nom de la femme de Nachor, Milcah, fille de Haran, père de Milcah, et père de Jiscah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Or Saraï était stérile, elle était sans enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Alors Thérach prit Abram, son fils, et Lot, fils de Haran, fils de son fils, et Saraï, sa bru, femme d\'Abram, son fils, et ils émigrèrent l\'un avec l\'autre d\'Ur en Chaldée pour gagner le pays de Canaan; et ils atteignirent Charan, et ils s\'y fixèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Et les jours de Thérach furent deux cent-cinq ans, et Thérach mourut à Charan. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Et l\'Éternel dit à Abram: Quitte ton pays et ta patrie et la maison de ton père pour aller au pays que je te montrerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Et je te ferai devenir un grand peuple et je te bénirai et te donnerai un grand nom et tu seras une bénédiction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Et je bénirai qui te bénira, et qui te maudira je le maudirai, et c\'est en toi que toutes les familles de la terre seront bénies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Alors Abram s\'achemina conformément à ce que lui avait dit l\'Éternel, et Lot s\'achemina avec lui. Or Abram avait soixante-quinze ans à son départ de Charan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Et Abram prit Saraï, sa femme, et Lot, fils de son frère, et tout le bien qu\'ils avaient acquis et le personnel qu\'ils s\'étaient fait à Charan, et ils partirent pour gagner le pays de Canaan et ils entrèrent au pays de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Et Abram pénétra dans le pays jusqu\'au lieu [nommé] Sichem, jusqu\'à la chênaie de Moreh. Or les Cananéens étaient alors dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Alors l\'Éternel apparut à Abram et dit: Je donnerai ce pays à ta postérité. Et il bâtit là un autel à l\'Éternel qui lui était apparu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Et il se transporta de là vers la montagne à l\'orient de Béthel, et tendit sa tente, ayant Béthel à l\'occident et Aï à l\'orient, et bâtit là un autel à l\'Éternel, et invoqua le nom de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Et de station en station Abram s\'avançait vers le Midi. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Et il y eut famine dans le pays: alors Abram descendit en Egypte pour y séjourner, car la famine pesait sur le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Et comme il était près d\'entrer en Egypte, il dit à Saraï, sa femme: Eh bien! voici, je sais que tu es une femme belle de figure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Et il arrivera que lorsque les Egyptiens te verront, ils diront: C\'est sa femme! et ils me tueront, mais à toi ils laisseront la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Dis donc que tu es ma sœur, afin que l\'on me traite bien pour l\'amour de toi, et que mon âme vive grâce à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Et lorsque Abram fut arrivé en Egypte, les Égyptiens virent que c\'était une femme d\'une très grande beauté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Et les Grands de Pharaon la virent et la vantèrent à Pharaon; et la femme fut enlevée et menée dans la demeure de Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Et pour l\'amour d\'elle il traita bien Abram, qui eut des brebis et des bœufs et des ânes et des serviteurs et des servantes et des ânesses et des chameaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Mais l\'Éternel frappa Pharaon de grandes plaies ainsi que sa maison, au sujet de Saraï, femme d\'Abram.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Alors Pharaon manda Abram et lui dit: Pourquoi en as-tu agi de la sorte envers moi? pourquoi ne pas m\'avouer que c\'est ta femme?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Pourquoi dire: C\'est ma sœur; aussi me suis-je emparé d\'elle pour en faire ma femme? Eh bien! voici, puisque c\'est ta femme, prends-la et t\'en va.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Et Pharaon lui assigna des gens, qui l\'escortèrent lui et sa femme et tout ce qu\'il avait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Et Abram remonta de l\'Egypte, lui et sa femme et tout ce qu\'il avait, et Lot avec lui, dans le Midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Or Abram était fort riche en troupeaux, en argent et en or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Et il s\'avança par stations du Midi jusqu\'à Béthel, au lieu où avait été sa tente dans l\'origine, entre Béthel et Aï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'à l\'emplacement de l\'autel qu\'il avait fait au début. Et là Abram invoqua le nom de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Et Lot aussi, qui voyageait avec Abram, avait des brebis et des bœufs et des tentes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Mais la contrée ne leur suffisait pas pour y demeurer ensemble; car leurs biens étaient considérables, et ils ne pouvaient demeurer réunis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Et il y eut rixe entre les bergers des troupeaux d\'Abram et les bergers des troupeaux de Lot. Or les Cananéens et les Phérésiens étaient alors établis dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Et Abram dit à Lot: Il ne faut pas qu\'il y ait de rixe entre moi et toi, et entre mes bergers et tes bergers; car nous sommes des frères!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'N\'as-tu pas tout le pays devant toi? Sépare-toi donc de moi! Prends-tu la gauche, je prendrai la droite, prends-tu la droite, je prendrai la gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Alors Lot leva les yeux et distingua tout le cercle du Jourdain, qui dans sa totalité était arrosé, avant que l\'Éternel eût détruit Sodome et Gomorrhe, comme un jardin de l\'Éternel, comme la terre d\'Egypte du côté de Tsohar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Et Lot choisit pour lui tout le cercle du Jourdain et Lot se transporta à l\'Orient; et ils se séparèrent l\'un de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram habita le pays de Canaan, et Lot habita les villes du cercle du Jourdain, et il dressa ses tentes jusqu\'à Sodome.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Or les hommes de Sodome étaient méchants et excessivement pécheurs contre l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Et l\'Éternel dit à Abram, après que Lot se fut séparé de lui: Lève donc les yeux, et du lieu où tu es, regarde au septentrion et au midi et à l\'orient et à l\'occident.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Car tout le pays que tu vois, je veux te le donner, à toi et à ta postérité, pour l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Et je rendrai ta postérité égale à la poussière de la terre, de telle sorte que s\'il est possible de compter les grains de la poussière de la terre, ta postérité sera aussi comptée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Va et parcours le pays dans sa longueur et dans sa largeur, car je veux te le donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Et Abram dressa ses tentes et fit son entrée et habita sous les chênes de Mamré, qui sont près de Hébron, et là il bâtit un autel à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Et il arriva dans le temps de Amraphel, roi de Sinear, de Arioch, roi d\'Elassar, de Kedorlahomer, roi d\'Elam, et de Thideal, roi des Gentils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'qu\'ils firent la guerre à Berah, roi de Sodome, et à Birsah, roi de Gomorrhe, à Sineab, roi d\'Adamah, et à Seméber, roi de Tseboïm, et au roi de Béla, c\'est-à-dire de Tsohar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Tous ils se réunirent dans la vallée de Siddim (qui est la mer Salée).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Douze ans ils avaient été asservis à Kedorlahomer, et la treizième année ils se révoltèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Et la quatorzième année Kedorlahomer et les rois ses alliés vinrent et défirent les Rephaïms à Astaroth-Karnaïm et les Zuzites à Ham et les Emim à Save-Kiriathaïm');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'et les Horites sur leur montagne de Seïr jusqu\'au chêne de Paran qui confine au désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Puis faisant volte-face ils se portèrent sur la Fontaine-du-Jugement qui est Kadès et mirent en déroute toute la contrée des Amalécites, et aussi les Amoréens établis à Hatsatson-Thamar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Alors se mirent en campagne le roi de Sodome et le roi de Gomorrhe et le roi d\'Adamah et le roi de Tseboïm et le roi de Béla (c\'est-à-dire de Tsohar) et ils se rangèrent en bataille contre eux dans la vallée de Siddim,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'contre Kedorlahomer, roi d\'Elam, et Thideal, roi des Gentils, et Amraphel, roi de Sinear, et Arioch, roi d\'Elassar, quatre rois contre cinq.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Or dans la vallée de Siddim il y avait force puits de bitume; et le roi de Sodome et celui de Gomorrhe prirent la fuite et y tombèrent, et les survivants s\'enfuirent dans la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Alors ils prirent toute la richesse de Sodome et de Gomorrhe et toutes leurs provisions de bouche et partirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Et ils prirent Lot et sa richesse, le fils du frère d\'Abram, et partirent; or il habitait Sodome.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Alors arriva un fugitif qui informa Abram l\'hébreu; or il habitait sous les chênes de Mamré, l\'Amoréen, frère d\'Eskol et de Aner, qui étaient les alliés d\'Abram.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Et Abram apprenant que son frère avait été emmené captif, mit en campagne ses gens éprouvés, serfs nés dans sa maison, au nombre de trois cent-dix-huit, et il poussa la poursuite jusqu\'à Dan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Et ayant formé ses divisions, il les attaqua de nuit, lui et ses serviteurs, et les défit et les poursuivit jusqu\'à Chobah, située à gauche de Damas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Et il ramena toute la richesse, et aussi Lot, son frère, et sa richesse, et aussi les femmes et le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Alors le roi de Sodome sortit à sa rencontre, quand après avoir défait Kedorlahomer et les rois ses auxiliaires il fut de retour dans la vallée de Save, qui est la vallée royale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Et Melchisédek, roi de Salem, apporta du pain et du vin; (or il était prêtre de Dieu le Très-Haut;)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'et il le bénit et dit: Qu\'Abram soit béni de Dieu le Très-Haut, maître des cieux et de la terre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Et béni soit Dieu le Très-Haut qui a mis tes ennemis entre tes mains! Et il lui donna la dîme de tout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Et le roi de Sodome dit à Abram: Donne-moi les personnes et prends pour toi les richesses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Mais Abram répondit au roi de Sodome: La main levée vers l\'Éternel, Dieu très-haut, Maître des cieux et de la terre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'non, du brin de fil à la courroie de la chaussure, je n\'accepterai rien de ce qui t\'appartient, afin que tu ne dises pas: J\'ai enrichi Abram;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'j\'excepte uniquement ce qu\'ont mangé mes gens, la portion des hommes qui ont marché avec moi, d\'Aner, d\'Eskol et de Mamré: pour eux, qu\'ils prennent leur part!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Après ces choses la parole de l\'Éternel fut adressée à Abram dans la vision, en ces termes: Sois sans crainte, Abram. Je suis un bouclier pour toi, ta rémunération immense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Et Abram dit: Seigneur, Éternel, que me donneras-tu, tandis que je m\'en vais sans enfants, et que l\'héritier de ma maison est Eliézer de Damas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Et Abram dit: Voici, tune m\'as pas donné de postérité, et mon domestique recueillera ma succession.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Mais voilà que la parole de l\'Éternel lui fut adressée en ces termes: Ce n\'est pas lui qui recueillera ta succession, mais celui qui sortira de tes entrailles, c\'est lui qui la recueillera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Puis Il le conduisit dehors et dit: Regarde donc les cieux, et compte les étoiles, si tu peux les compter. Et Il lui dit: Telle sera ta postérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Et il eut confiance dans l\'Éternel, qui le lui imputa à justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Puis Il lui dit: Je suis l\'Éternel qui t\'ai fait sortir d\'Ur en Chaldée pour te donner ce pays-ci en propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Et il dit: Seigneur Éternel, à quoi reconnaîtrai-je que je le posséderai?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Et Il lui dit: Amène-moi une génisse de trois ans et une chèvre de trois ans et un bélier de trois ans et une tourterelle et une colombe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Et il Lui amena tous ces [animaux], et il les coupa par le milieu, et plaça chacune des moitiés vis-à-vis de l\'autre; mais il ne coupa point les oiseaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Et les oiseaux de proie s\'abattirent sur les moitiés, mais Abram leur donna la chasse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Et comme le soleil était près de se coucher, un profond sommeil assaillit Abram, et voici, une terreur, une obscurité profonde fondit sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Et Il dit à Abram: Il faut que tu saches que ta postérité séjournera dans un pays qui ne sera pas le sien, et auquel elle sera asservie et qui l\'opprimera durant quatre cents ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Mais je jugerai aussi la nation à qui elle sera asservie, et après cela elle sortira avec une richesse considérable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Mais toi, tu rejoindras tes pères en paix; tu seras porté au tombeau dans une belle vieillesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Et à la quatrième génération ils reviendront ici, car jusque-là l\'iniquité des Amoréens ne sera pas à son comble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Et quand le soleil fut couché et qu\'il fit sombre, voici, il y eut une fournaise fumante et une torche enflammée qui passèrent entre ces quartiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'En ce jour-là l\'Éternel conclut une alliance avec Abram et dit: Je donne ce pays à ta postérité depuis le fleuve d\'Egypte jusqu\'au grand fleuve, le fleuve Le Phrath,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'le pays des Kénites, et des Kénisites et des Cadmonites,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'et des Héthiens et des Phérisiens et des Rephaïms');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'et des Amorites et des Cananéens et des Gergésiens et des Jébusites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Et Saraï, femme d\'Abram, ne lui donnait point d\'enfants; mais elle avait une servante Egyptienne dont le nom était Agar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Et Saraï dit à Abram: Voici, l\'Éternel met donc obstacle à ce que j\'aie des enfants: approche-toi donc de ma servante, peut-être par elle fonderai-je ma maison. Et Abram prêta l\'oreille à la voix de Saraï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Alors Saraï, femme d\'Abram, prit l\'Egyptienne Agar, sa servante, au bout de dix ans de séjour d\'Abram dans le pays de Canaan, et la donna à Abram, son mari, pour femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Et il s\'approcha d\'Agar qui devint enceinte, et quand elle se vit enceinte, sa maîtresse fut déconsidérée à ses yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Et Saraï dit à Abram: L\'outrage que je reçois retombe sur toi! J\'ai mis ma servante entre tes bras, et comme elle se voit enceinte, je suis déconsidérée à ses yeux: que l\'Éternel soit juge entre moi et toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Et Abram dit à Saraï: Voici, ta servante est en ton pouvoir, traite-la comme tu le trouveras bon. Alors Saraï lui fit des avanies, et Agar s\'enfuit loin de sa présence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Et l\'Ange de l\'Éternel la trouva près de la source d\'eau dans le désert, près de la source qui est sur le chemin de Sur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Et il dit: Agar, servante de Saraï, d\'où viens-tu et où vas-tu? Et elle dit: Loin de la présence de Saraï, ma maîtresse, je fuis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Et l\'Ange de l\'Éternel lui dit: Retourne chez ta maîtresse et laisse-toi humilier sous sa main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Et l\'Ange de l\'Éternel lui dit: Je multiplierai ta postérité tellement qu\'on ne pourra la compter, tant elle sera nombreuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Et l\'Ange de l\'Éternel lui dit: Voici, tu es enceinte, et tu enfanteras un fils, et tu le nommeras Ismaël, car Dieu a ouï ton affliction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Et il sera un onagre en fait d\'homme, opposant sa main à tous et ayant contre lui la main de tous, et à l\'orient de tous ses frères il habitera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Et elle appela l\'Éternel qui avait parlé avec elle du nom de: Tu es le Dieu qui voit! Car elle disait: Et ici n\'ai-je pas aussi vu après avoir été vue?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'C\'est pourquoi l\'on a appelé ce puits: Le Puits du Vivant qui me Voit; voici, il est entre Kadès et Bered.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Et Agar enfanta un fils à Abram, et Abram appela son fils, que Agar lui avait enfanté, du nom d\'Ismaël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Or, Abram avait quatre-vingt-six ans, lorsque Agar enfanta Ismaël à Abram.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Et lorsque Abram eut quatre-vingt-dix-neuf ans, l\'Éternel apparut à Abram et lui dit: Je suis Dieu, le Tout-puissant, marche en ma présence et sois irréprochable,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'et j\'établirai mon alliance entre moi et toi, et je te donnerai un accroissement de plus en plus grand.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Alors Abram tomba la face contre terre et Dieu lui parla en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Pour moi, voici, je tiens mon alliance avec toi, et tu deviendras père d\'une multitude de peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Et désormais on ne t\'appellera plus de ton nom d\'Abram, mais ton nom sera Abraham, car je te constitue père d\'une multitude de peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Et je te rendrai de plus en plus fécond, et je ferai de toi une souche de peuples et des rois proviendront de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Et j\'érige mon alliance entre moi et toi et tes descendants après toi pour toutes leurs générations en alliance éternelle, savoir que je serai ton Dieu à toi et à ta postérité après toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Et je te donne et à ta postérité après toi le pays de tes pèlerinages, le pays de Canaan, en propriété éternelle, et je serai leur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Et Dieu dit à Abraham: Pour toi, tu garderas mon alliance, toi et tes descendants après toi dans toutes leurs générations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Voici l\'alliance que vous observerez entre moi et vous, et ta postérité après toi, c\'est que tous vos mâles seront circoncis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'vous vous circoncirez la chair de votre prépuce, et ce sera un signe d\'alliance entre moi et vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Tout mâle sera circoncis par vous à l\'âge de huit jours dans vos générations, le serf soit né à la maison, soit acquis à prix d\'argent, chacun des fils de l\'étranger qui ne sera pas de ta race;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'vous aurez à circoncire le serf soit né à la maison, soit acquis à prix d\'argent, et ainsi vous porterez en votre chair mon alliance, en alliance éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Quant au mâle incirconcis dont la chair du prépuce n\'aura pas subi la circoncision, un tel individu sera exterminé du milieu de son peuple; il aura violé mon alliance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Et Dieu dit à Abraham: Saraï, ta femme, ne sera plus le appelée du nom de Saraï, mais son nom sera Sarah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Et je la bénis, et je te ferai aussi naître d\'elle un fils; je la bénis et elle deviendra une souche de peuples, et des rois proviendront d\'elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Alors Abraham tomba la face contre terre, et il rit et dit en son cœur: A un centenaire naîtrait-il un fils, et Sarah, nonagénaire, enfanterait-elle?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Et Abraham dit à Dieu: Puisse Ismaël vivre sous ton regard!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Et Dieu dit: Ce n\'est pas cela! Sarah, ta femme, t\'enfantera un fils, et tu l\'appelleras du nom d\'Isaac; et j\'érigerai mon alliance avec lui en alliance éternelle pour sa postérité après lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Et je t\'exauce quant à Ismaël: voici je le bénirai et le rendrai fécond, et lui donnerai un grand accroissement; il engendrera douze princes et je le ferai devenir un grand peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Et je dresserai mon alliance avec Isaac que Sarah t\'enfantera à pareille époque l\'année prochaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Et lorsqu\'il eut achevé de parler avec lui, Dieu s\'éleva quittant Abraham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Alors Abraham prit Ismaël, son fils et tous les serfs nés dans sa maison et tous les serfs achetés à prix d\'argent, tous les mâles de la maison d\'Abraham et il circoncit la chair de leur prépuce ce jour-là même selon ce que Dieu lui avait dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Or Abraham avait quatre-vingt-dix-neuf ans lorsqu\'il fut circoncis en la chair de son prépuce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Et Ismaël, son fils, avait treize ans lorsqu\'il fut circoncis en la chair de son prépuce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'C\'est en ce jour même que furent circoncis Abraham et Ismaël, son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Et tous les hommes de sa maison, serfs nés dans la maison et serfs acquis à prix d\'argent d\'entre les fils de l\'étranger, furent circoncis avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Et l\'Éternel lui apparut sous les chênes de Mamré, comme il était assis à la porte de sa tente au temps chaud de la journée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Et ayant levé les yeux il regarda, et voici, trois hommes étaient debout devant lui. Et les ayant vus, il courut à leur rencontre depuis l\'entrée de sa tente, et il s\'inclina jusqu\'à terre');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'et dit: Seigneur, si je peux trouver grâce à tes yeux, ne passe donc pas outre devant ton serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Permets qu\'on apporte un peu d\'eau pour laver vos pieds, et reposez-vous sous cet arbre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Et j\'irai chercher un morceau de pain pour vous refaire le cœur; après cela vous pourrez passer plus loin; car c\'est pour cela que vous passez près de votre serviteur. Et ils répondirent: Ainsi fais, comme tu as dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Et vite Abraham entra dans la tente vers Sarah et dit: Prends vite trois mesures de fleur de farine que tu pétriras pour en faire des galettes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Puis Abraham courut à l\'étable et prit un veau délicat et bon et le donna au valet qui se hâta de l\'apprêter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Et il prit de la crème et du lait et le veau qu\'il avait apprêté et il le leur servit; mais il se tenait debout devant eux sous l\'arbre, et ils mangèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Alors ils lui dirent: Où est Sarah, ta femme? Et il répondit: La voici dans la tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Et il dit: Je reviendrai chez toi à la renaissance de l\'année; et voici, Sarah, ta femme, aura un fils. Et Sarah était aux écoutes à l\'entrée de la tente qui était derrière lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Or Abraham et Sarah étaient vieux, avancés en âge; et il y avait chez Sarah suppression de ce qui survient aux femmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Et Sarah rit intérieurement disant: Maintenant que je suis passée, y aurait-il pour moi volupté? et mon seigneur est vieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Alors l\'Éternel dit à Abraham: Pourquoi donc Sarah a-t-elle ri, et dit-elle: Est-ce en vérité que j\'enfanterais toute vieille que je suis?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Pour l\'Éternel est-il rien d\'impossible? A pareille époque je reviendrai chez toi à la renaissance de l\'année, et Sarah aura un fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Et Sarah nia et dit: Je n\'ai pas ri; car elle avait peur. Et il dit: Non! tu as ri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Alors ces hommes se levèrent et partirent de là et se dirigèrent du côté de Sodome; or Abraham s\'achemina avec eux pour les accompagner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Et l\'Éternel dit: Cèlerais-je à Abraham ce que je veux faire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Mais Abraham deviendra un peuple grand et fort, et tous les peuples de la terre auront en lui leur bénédiction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Car je l\'ai distingué, afin qu\'il prescrive à ses fils et à sa maison après lui de garder la voie de l\'Éternel pour pratiquer le droit et la justice, afin que l\'Éternel dispense à Abraham ce qu\'il lui a promis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Et l\'Éternel dit: Il est de fait que le décri de Sodome et de Gomorrhe est bien grand, et de fait que leur péché est très grave.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Il faut donc que je descende et que je voie s\'ils ont mis le comble à leur forfait d\'accord avec le cri venu jusqu\'à moi, et je veux savoir si ce n\'est pas le cas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Alors les hommes partirent de là et prirent leur chemin vers Sodome; mais Abraham resta encore en la présence de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Et Abraham s\'approcha et dit: Irais-tu jusqu\'à emporter le juste avec l\'impie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Peut-être y a-t-il cinquante justes dans la ville; veux-tu les emporter aussi et ne pardonneras-tu pas à ce lieu en considération des cinquante justes qui s\'y trouvent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Loin de toi la pensée d\'agir ainsi et de donner la mort au juste en même temps qu\'à l\'impie, pour qu\'il en soit du juste comme de l\'impie! loin de toi cette pensée! Le Juge de la terre ne rendrait-Il pas justice?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Et l\'Éternel dit: Si à Sodome je trouve cinquante justes dans la ville, je pardonnerai au lieu entier en considération d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Et Abraham reprit et dit: Ah! voici, je m\'enhardis avec le Seigneur, tout poudre et cendre que je suis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Peut-être des cinquante justes il en manquera cinq: pour cinq détruiras-tu la ville entière? Et Il dit: Je ne la détruirai pas, si j\'y en trouve quarante-cinq.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Et il continua encore l\'entretien avec Lui et dit: Peut-être s\'y en trouvera-t-il quarante. Et Il dit: En considération des quarante je m\'abstiendrai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Et il dit: Ah! que le Seigneur ne s\'irrite pas si je parle! Peut-être s\'y en trouvera-t-il trente. Et Il dit: Je m\'abstiendrai, si j\'y en trouve trente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Et il dit: Ah! voici, je m\'enhardis à parler avec le Seigneur! Peut-être s\'y en trouvera-t-il vingt. Et Il dit: En considération des vingt je ne détruirai pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Et il dit: Ah! que le Seigneur ne s\'irrite pas si je parle cette fois encore! Peut-être s\'y en trouvera-t-il dix. Et Il dit: En considération des dix je ne détruirai pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Et l\'Éternel se retira lorsqu Il eut fini son entretien avec Abraham, et Abraham regagna son lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Et les deux anges arrivèrent à Sodome le soir; or Lot était assis à la porte de Sodome. Et les ayant vus, Lot se leva, alla au devant d\'eux et se prosterna la face contre terre');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'et dit: Oh! je vous prie, mes seigneurs, descendez à la maison de votre serviteur et passez-y la nuit, et baignez vos pieds: puis vous vous lèverez le matin et continuerez votre route. Et ils dirent: Non, mais nous voulons passer la nuit dans la place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Et il insista fort auprès d\'eux, et ils descendirent chez lui et entrèrent dans sa maison. Et il leur prépara un repas et fit cuire des galettes azymes, et ils mangèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Ils n\'étaient pas encore couchés que les hommes de la ville, les hommes de Sodome, cernèrent la maison, depuis l\'enfant au vieillard, tout le peuple en masse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Et ils appelèrent Lot et lui dirent: Où sont les hommes arrivés chez toi cette nuit? Amène-nous-les dehors, afin que nous les connaissions!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Et Lot sortit vers eux devant la porte qu\'il referma derrière lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'et il dit: Oh! mes frères, ne commettez pas le crime!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Eh bien! voici, j\'ai deux filles qui n\'ont point encore connu d\'homme; je vais donc vous les amener dehors, et vous en userez avec elles à votre gré; seulement ne faites rien à ces hommes; car c\'est dans cette supposition qu\'ils sont entrés à l\'ombre de mon toit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Et ils dirent: Avance davantage. Et ils dirent: L\'individu est venu en hôte, et il veut faire le juge! Eh bien! nous te ferons pis qu\'à eux. Et ils pressèrent fortement l\'homme, Lot, et ils approchaient pour enfoncer la porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Alors les deux hommes étendirent et retirèrent Lot vers eux dans la maison et fermèrent la porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Quant aux gens qui se tenaient devant la porte de la maison, ils les frappèrent de cécité depuis le plus petit au plus grand; et ceci se tourmentèrent à trouver la porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Et les hommes dirent à Lot: Tous ceux que tu as encore ici, tes gendres et tes fils et tes filles, et tous ceux qui tiennent à toi dans la ville, fais-les sortir de ce lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Car nous allons détruire ce lieu-ci, parce que ces gens sont grandement décriés devant l\'Éternel, et l\'Éternel nous a envoyés pour détruire la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Alors Lot sortit et parla à ses gendres qui prétendaient à ses filles et dit: Mettez-vous en devoir de sortir de ce lieu-ci, car l\'Éternel va détruire la ville. Mais il eut, aux yeux de ses gendres, l\'air de plaisanter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Et au lever de l\'aurore, les anges insistèrent auprès de Lot et dirent: Lève-toi, prends ta femme et tes deux filles qui se trouvent-là, de peur que tu ne périsses par suite du crime de cette ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Et comme il tardait, les hommes le prirent sa main et la main de sa femme et la main de ses deux filles, parce que l\'Éternel voulait l\'épargner, et ils le firent sortir, et le laissèrent en dehors de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Et après les avoir fait sortir, l\'un [d\'eux] dit: Sauve-loi, au nom de ta vie, ne regarde pas derrière toi, et ne t\'arrête pas dans tout le district! Sauve-toi sur la montagne pour ne pas périr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Et Lot leur dit: Oh! non! Seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'vois donc! ton serviteur a trouvé grâce à tes yeux, et grand a été l\'amour que tu m\'as témoigné pour me conserver la vie; mais je ne puis me sauver sur la montagne, le désastre pourrait m\'atteindre et je périrais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Vois donc! Cette ville-là est à portée pour y fuir, et elle est petite: c\'est là que je voudrais me réfugier (n\'est-elle pas petite?) afin que mon âme vive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Et Il lui dit: Voici, je veux aussi te satisfaire en ce point, en ne bouleversant pas la ville dont tu parles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Hâte-toi de t\'y réfugier, car je ne puis rien faire que tu n\'y sois arrivé. – C\'est pourquoi l\'on donne à cette ville le nom de Tsohar (petite).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Le soleil se levait sur la terre, lorsque Lot entra dans Tsohar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Et l\'Éternel fit tomber sur Sodome et sur Gomorrhe une pluie de soufre et de feu, de par l\'Éternel depuis le ciel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'et Il bouleversa ces villes et toute la contrée, et la population des villes et les productions du sol.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Mais sa femme regarda derrière elle, et elle devint statue de sel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Et Abraham se leva le matin et gagna le lieu où il s\'était tenu en la présence de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'et porta ses regards à ses pieds sur Sodome et Gomorrhe et toute la contrée du district, et il vit, et voilà qu\'une fumée s\'élevait de la terre, comme la fumée d\'une fournaise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Et quand Dieu détruisit les villes du district, Dieu se souvint d\'Abraham et fit échapper Lot du milieu du bouleversement, lorsqu\'il bouleversa les villes où habitait Lot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Et de Tsohar Lot gagna la hauteur, et il se fixa sur la montagne, et il avait ses deux filles avec lui, car il redoutait de demeurer à Tsohar. Et il habitait une grotte, lui et ses deux filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Alors L\'aînée dit à la cadette: Notre père est vieux, et il n\'y a plus d\'homme sur la terre pour s\'approcher de nous selon l\'usage de tout le monde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'viens! faisons prendre du vin à notre père et couchons avec lui, et ainsi nous donnerons la vie à une lignée par notre père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Elles firent donc boire du vin à leur père cette nuit-là, et l\'aînée s\'introduisit et coucha avec son père, qui ne s\'aperçut ni quand elle se coucha, ni quand elle se leva.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Et le lendemain l\'aînée dit à la cadette: Voici, j\'ai couché la nuit dernière avec mon père: faisons-lui encore boire du vin cette nuit, et introduis-toi et couche avec lui et nous donnerons vie à une lignée par notre père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Elles firent donc encore cette nuit boire du vin à leur père. Et la cadette se leva et coucha avec lui, et il ne s\'aperçut ni quand elle se coucha ni quand elle se leva.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Et les deux filles de Lot devinrent enceintes du fait de leur père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Et l\'aînée enfanta un fils et elle l\'appela du nom de Moab (issu du père); c\'est le père des Moabites jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Et la cadette aussi enfanta un fils et elle l\'appela du nom de Ben Ammi (fils de mon peuple); c\'est le père des fils d\'Ammon, jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Et Abraham se transporta de là dans la région du Midi, et se fixa entre Kadès et Sur, et fit un séjour à Gérar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Et Abraham disait de Sarah, sa femme: C\'est ma sœur. Alors Abimélech, roi de Gérar, envoya enlever Sarah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Mais Dieu descendit vers Abimélech dans un songe de la nuit, et lui dit: Voici, tu vas mourir à cause de la femme que tu as enlevée et qui est mariée à un mari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Cependant Abimélech ne s\'était point approché d\'elle. Et il dit: Seigneur, veux-tu faire périr un peuple, même innocent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Ne m\'a-t-il pas dit: C\'est ma sœur, et elle, elle-même a dit: Il est mon frère? C\'est dans l\'innocence de mon cœur et la pureté de mes mains que je l\'ai fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Et Dieu lui dit en songe: Je sais aussi que tu l\'as fait dans l\'innocence de ton cœur, et aussi t\'ai-je empoché de pécher contre moi; c\'est pourquoi je n\'ai pas permis que tu la touchasses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Maintenant donc rends la femme à son mari, car il est prophète et il intercédera pour toi, afin que tu vives; mais si tu ne la rends pas, sache que tu mourras, toi et tout ce qui t\'appartient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Alors Abimélech se leva le matin, et manda tous ses serviteurs, et redit toutes ces choses à leurs oreilles, et ces hommes furent très effrayés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Et Abimélech fit appeler a Abraham et lui dit: Qu\'est-ce que tu nous as fait, et en quoi ai-je manqué à ton égard que tu aies attiré sur moi et sur mon royaume une si grande culpabilité? Tu t\'es porté envers moi à des actions qu\'on ne fait pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Et Abimélech dit à Abraham: Qu\'avais-tu en vue pour en agir ainsi avec moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Et Abraham dit: C\'est que je me disais: assurément il n\'y a aucune crainte de Dieu dans ce lieu, et ils me tueront à cause de ma femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Aussi bien elle est vraiment ma sœur, fille de mon père, seulement n\'est-elle pas fille de ma mère, et elle est devenue ma femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Et lorsque Dieu me fit quitter, pour voyager, la maison de mon père, je lui dis: Fais-moi cette grâce: dans quelque lieu que nous allions, dis de moi: C\'est mon frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Alors Abimélech prit des brebis et des bœufs et des serviteurs et des servantes, et en fit un don à Abraham et lui rendit Sarah, sa femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Et Abimélech dit: Tu as tout mon pays devant toi; établis-toi où il le plaira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Et à Sarah il dit: Voici, j\'ai donné mille sicles d\'argent à ton frère: eh bien! que ce soit une réparation auprès de tous tes entours, et auprès de tous le voilà justifiée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Alors Abraham intercéda auprès de Dieu, et Dieu guérit Abimélech et sa femme et ses servantes, et elles purent enfanter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Car l\'Éternel avait frappé de stérilité toutes les femmes de la maison d\'Abimélech, à cause de Sarah, femme d\'Abraham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Et l\'Éternel intervint chez Sarah comme Il avait dit, et l\'Éternel opéra pour Sarah ce qu\'il avait promis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Et Sarah devint enceinte et enfanta à Abraham un fils dans ses vieux jours à l\'époque que Dieu avait indiquée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Et Abraham appela son fils qui lui était né, que lui avait enfanté Sarah, du nom d\'Isaac.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Et Abraham circoncit Isaac, son fils, quand il eut huit jours, ainsi que Dieu lui en avait donné l\'ordre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Or Abraham était âgé de cent ans, lorsque lui naquit Isaac, son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Et Sarah dit: Dieu m\'a mise à même de rire, et quiconque l\'ouïra me sourira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Et elle dit: Qui eût pu faire cette prédiction à Abraham: Sarah allaitera des fils? Cependant je lui ai enfanté un fils dans sa vieillesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Et l\'enfant grandit et fut sevré, et Abraham fit un grand festin le jour où Isaac fut sevré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Alors Sarah vit le fils d\'Agar l\'Egyptienne, que celle-ci avait enfanté à Abraham, qui jouait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'et elle dit à Abraham: Chasse cette servante-là et son fils, car le fils de cette servante ne doit pas hériter avec mon fils, avec Isaac.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Mais cette parole déplut fort à Abraham à cause de son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Alors Dieu dit à Abraham: N\'aie aucun déplaisir à l\'occasion de l\'enfant et de ta servante: dans tout ce que Sarah dira, défère à sa voix, car c\'est par Isaac qu\'il sera fait mention pour toi d\'une postérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'D\'ailleurs du fils de la servante je ferai aussi un peuple, car c\'est ta progéniture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Alors Abraham se leva le matin, et il prit un pain et une outre d\'eau, et les remit à Agar les posant sur son épaule, et l\'enfant aussi, puis il la congédia. Et elle partit et erra dans le désert de Beerséba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Et quand l\'eau fut épuisée dans l\'outre, elle jeta l\'enfant sous l\'un des buissons,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'et s\'en alla s\'asseoir vis-à-vis à la distance d\'une portée d\'arc; car elle disait: Je ne veux pas être témoin de la mort de l\'enfant. Et elle était assise vis-à-vis, et elle élevait la voix et pleurait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Alors Dieu entendit la voix de l\'enfant, et l\'ange de Dieu appela Agar du ciel et lui dit: Qu\'as-tu Agar? Ne t\'alarme point, car Dieu a écouté la voix de l\'enfant, du lieu où Il est.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Lève-toi, relève l\'enfant et le prends par la main; car je ferai de lui un grand peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Et Dieu ouvrit les yeux à Agar, et elle aperçut une fontaine, et elle alla et emplit l\'outre d\'eau et donna à boire à l\'enfant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Et Dieu fut avec l\'enfant, et il grandit, et il demeura dans le désert, et adulte il fut tireur d\'arc.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Et il habita le désert de si Paran, et sa mère lui choisit une femme au pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Et dans ce même temps Abimélech et Phichol, son général d\'armée, s\'adressèrent à Abraham en ces termes: Dieu est avec toi dans tout ce que tu fais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Or maintenant jure-moi ici au nom de Dieu que tu ne tromperas ni moi, ni mes enfants, ni mes petits-enfants; tu useras envers moi et le pays où tu séjournes, de la même bienveillance dont j\'ai usé envers toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Et Abraham dit: Je le jurerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Mais Abraham fit des réclamations à Abimélech au sujet d\'un puits dont s\'étaient emparés les serviteurs d\'Abimélech.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Sur quoi Abimélech dit: J\'ignore qui l\'a fait, et je n\'ai été ni informé par toi, ni instruit de cela sinon aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Et Abraham prit des brebis et des bœufs et les donna à Abimélech, et tous deux ils firent alliance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Et Abraham mit à part sept agneaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Et Abimélech dit à Abraham: Qu\'est-ce que ces sept agneaux que tu as mis à part?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Et il répondit: C\'est pour que tu les acceptes de ma main, afin que ce me soit un témoignage que c\'est moi qui ai creusé ce puits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'C\'est pourquoi on appelle ce lieu Beerséba à cause du serment qu\'ils y firent l\'un et l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'C\'est ainsi qu\'ils traitèrent alliance à Beerséba. Et Abimélech se leva ainsi que Phichol, son général d\'armée, et ils regagnèrent le pays des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Et Abraham planta des tamariscs à Beerséba et y invoqua le nom de l\'Éternel, Dieu éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Et Abraham fit un long séjour dans le pays des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Et après ces choses il arriva que Dieu mit Abraham à l\'épreuve; et Il lui dit: Abraham! Et il répondit: Me voici!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Et Il dit: Eh bien! prends ton fils, ton unique, que tu aimes, Isaac, et va-t\'en au pays de Moriah, et là offre-le en holocauste sur l\'une des montagnes que je te dirai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Et Abraham se leva Je matin et bâta son âne, et prit deux de ses valets avec lui, et Isaac, son fils, et il fendit du bois pour l\'holocauste, et il se leva et prit son chemin vers le lieu que Dieu lui avait indiqué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Le troisième jour Abraham, levant les yeux, aperçut le lieu de loin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Alors Abraham dit à ses valets: Restez ici avec l\'âne, et moi et l\'enfant nous irons jusque-là, et nous adorerons, puis nous vous rejoindrons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Puis Abraham prit le bois de l\'holocauste, et en chargea Isaac, son fils, et il prit en sa main le feu et le couteau; et ils s\'acheminèrent les deux ensemble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Et Isaac parla à Abraham, son père, et dit: Mon père! Et il répondit: Me voici, mon fils. Et il dit: Voici bien le feu et le bois; mais où est la victime pour l\'holocauste?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Et Abraham répondit: Dieu verra à se trouver la victime pour l\'holocauste, mon fils. Puis ils cheminèrent les deux ensemble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Et ils arrivèrent au lieu que Dieu lui avait dit, et Abraham y éleva l\'autel, et disposa le bûcher, et lia Isaac, son fils, et le plaça sur l\'autel par dessus le bûcher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Et Abraham étendit la main et prit le couteau pour immoler son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Alors l\'ange de l\'Éternel l\'appela des cieux et dit: Abraham! Abraham! Et il répondit: Me voici!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Et il dit: Ne porte pas la main sur l\'enfant, et ne lui fais rien; car maintenant je sais que tu crains Dieu, et tu ne m\'as pas refusé ton fils, ton unique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Alors Abraham leva les yeux et regarda, et voilà que derrière lui un bélier était pris par les cornes dans le hallier, et Abraham alla prendre le bélier, et il l\'offrit en holocauste à la place de son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Et Abraham donna à ce lieu le nom de: L\'Éternel verra; d\'où vient l\'expression d\'aujourd\'hui: A la montagne de l\'Éternel Il se rendra visible.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Et l\'ange de l\'Éternel appela une seconde fois Abraham des cieux');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'et dit: Je jure par moi-même, déclare l\'Éternel, que parce que tu as accompli cet acte, et n\'as point refusé ton fils, ton unique,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'je te bénirai et multiplierai ta postérité comme les étoiles du ciel et comme le sable qui est sur le bord de la mer; et ta postérité sera maîtresse de la porte de ses ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Et toutes les nations de la terre chercheront leur bénédiction dans ta postérité par la raison que tu as obéi à ma voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Et Abraham rejoignit ses valets; puis ils se levèrent, et gagnèrent ensemble Beerséba, et Abraham demeura à Beerséba. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Et sur ces entrefaites Abraham reçut un renseignement conçu en ces termes: Voici, Milca a aussi enfanté des fils à Nachor, ton frère:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Uts, son premier-né, et Buz, son frère, et Kemuel, père d\'Aram,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'et Chésed et Hazo et Pila:das et Jidlaph et Bethuel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Et Bethuel a engendré Rebecca: Ce sont là les huit enfants que Milca a enfantés à Nachor, frère d\'Abraham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Et sa concubine, nommée Reumah, a aussi enfanté Tebach et Gaham et Thachas et Maacha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Et la vie de Sarah fut de cent vingt-sept ans, années de vie de Sarah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Et Sarah mourut à Kiriafh-Arba (qui est Hébron)au pays de Canaan, et Abraham vint pour le deuil de Sarah et pour la pleurer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Et Abraham se leva de devant son cadavre, et il s\'adressa aux fils de Heth en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Je suis un hôte et un étranger chez vous: accordez-moi une propriété sépulcrale chez vous, afin que je puisse donner la sépulture à mon cadavre et l\'éloigner de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Sur quoi les fils de Heth répondirent à Abraham en lui disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Oh, écoute-nous, mon seigneur: Tu es un prince de Dieu au milieu de nous, donne la sépulture à ton cadavre dans le meilleur de nos tombeaux; aucun de nous ne te refusera son tombeau pour y donner la sépulture à ton cadavre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Alors Abraham se leva et s\'inclina devant le peuple du pays, devant les fils de Heth, et leur parla en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Si c\'est votre sentiment que je donne la sépulture à mon cadavre et que je l\'éloigne de moi, écoutez-moi et intercédez pour moi auprès de Ephron, fils de Tsohar,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'pour qu\'il me cède la grotte de Macpéla qui lui appartient et qui est à l\'extrémité de son champ; qu\'il me la cède contre paiement en plein au milieu de vous comme propriété sépulcrale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Or Ephron demeurait parmi les fils de Heth. Alors Ephron, le Héthien, répondit à Abraham aux oreilles des fils de Heth, de tous ceux qui passaient par la porte de sa ville, et il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Non pas! mon seigneur, écoule-moi! Je te fais don du champ et de la grotte qui y est; je t\'en fais don; c\'est aux yeux des fils de Heth que j\'en fais don à toi: donne la sépulture à ton cadavre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Alors Abraham s\'inclina devant le peuple du pays;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'et s\'adressant à Ephron aux oreilles du peuple du pays il dit: Si seulement tu voulais m\'écouter! Je paierai le prix du champ et j\'y donnerai la sépulture à mon cadavre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Sur cela Ephron répondit à Abraham en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Mon seigneur, écoute-moi! un terrain de quatre cents sicles d\'argent, qu\'est-ce que cela entre moi et toi? Donne donc la sépulture à ton cadavre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Et Abraham entendit Ephron. Et Abraham pesa à Ephron l\'argent qu\'il avait indiqué aux oreilles des fils de Heth, quatre cents sicles d\'argent ayant cours chez le marchand.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Et ainsi fut constitué le champ d\'Ephron à Macpéla à l\'orient de Mamré (le champ et la grotte y comprise et tous les arbres qui étaient dans le champ et se trouvaient entre toutes ses limites dans son enceinte)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'à Abraham comme propriété aux yeux des fils de Heth, en présence de tous ceux qui passaient par la porte de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Et après cela Abraham donna la sépulture à Sarah, sa femme, dans la grotte du champ de Macpéla à l\'orient de Mamré, c\'est-à-dire Hébron, au pays de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Ainsi le champ et la grotte y comprise furent constitués à Abraham comme propriété sépulcrale par les fils de Heth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Et Abraham était vieux, avancé en âge, et l\'Éternel avait béni Abraham en toute chose.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Alors Abraham dit à son serviteur, le plus ancien de sa maison, qui avait le gouvernement de tout ce qui lui appartenait: Pose ta main sous ma hanche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'afin que je t\'adjure au nom de l\'Éternel, Dieu des cieux et Dieu de la terre, de ne choisir pour la femme de mon fils aucune des filles des Cananéens au milieu desquels je demeure,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'mais d\'aller dans mon pays et dans ma patrie choisir une femme pour mon fils Isaac.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Alors le serviteur lui dit: Peut-être la femme ne voudra-t-elle pas me suivre dans ce pays-ci: dois-je pour lors reconduire ton fils dans le pays d\'où tu es sorti?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Et Abraham lui dit: Garde-toi d\'y reconduire mon fils!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'L\'Éternel, Dieu du ciel, qui m\'a tiré de la maison de mon père, et de ma patrie et qui m\'a fait cette promesse et ce serment: Je donnerai ce pays-ci à ta postérité, Lui-même enverra son ange pour te précéder, afin que tu ramènes de là une femme pour mon fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Que si la femme ne voulait pas te suivre, alors tu seras libéré de ce serment que je t\'impose; seulement ne dois-tu pas reconduire mon fils là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Le serviteur posa donc la main sous la hanche d\'Abraham, son seigneur, et lui prêta le serment dans ce sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Alors le serviteur prit dix chameaux parmi les chameaux de son maître, et il partit chargé de toutes sortes de beaux dons de son seigneur, et il se mit en route et gagna la Mésopotamie, la ville de Nachor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Et il agenouilla les chameaux en dehors de la ville près d\'une fontaine au temps de la soirée, au temps où sortent celles qui puisent l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Et il dit: Éternel, Dieu de mon seigneur Abraham, daigne me faire rencontrer aujourd\'hui, et use de bienveillance envers mon seigneur Abraham!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Voici je reste posté près de la fontaine, et les filles des hommes de la ville sortent pour puiser de l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Or, qu\'il se fasse que la jeune fille à qui je dirai: Penche donc ta cruche, afin que je boive, et qui dira: Bois! et j\'abreuverai aussi tes chameaux, se trouve être celle que tu as destinée à ton serviteur Isaac; et à cela je reconnaîtrai que tu uses de bienveillance envers mon seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Et il n\'avait pas encore achevé de parler que voici venir Rebecca, qui était née à Béthuel, fils de Milca, femme de Nachor, frère d\'Abraham, sa cruche sur son épaule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Or la jeune fille était très belle de figure, encore vierge, et nul homme ne l\'avait connue. Et elle descendit à la fontaine, et emplit sa cruche et remonta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Alors le serviteur courut au-devant d\'elle, et dit: Laisse-moi donc boire un peu d\'eau de ta cruche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Et elle répondit: Bois, mon seigneur! et vite elle abaissa sa cruche sur sa main et lui donna à boire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Et après l\'avoir entièrement désaltéré, elle dit: Je puiserai aussi pour tes chameaux jusqu\'à ce qu\'ils soient entièrement abreuvés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Et vite elle vida sa cruche dans l\'auge, et courut encore à la fontaine pour puiser, et elle puisa pour tous ses chameaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Et l\'homme la contemplait en silence pour voir si l\'Éternel donnerait ou non du succès à son voyage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Et lorsque les chameaux eurent fini de s\'abreuver, l\'homme prit un anneau d\'or, pesant un demi-sicle, et deux bracelets pour ses poignets, du poids de dix sicles d\'or,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'et dit: De qui es-tu fille? Indique-le moi donc! Y a-t-il pour nous dans la maison de ton père une place où passer la nuit?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Et elle lui répondit: Je suis fille de Béthuel, fils de Milca, que celle-ci a enfanté à Nachor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Et elle lui dit: Et paille et fourrage sont en abondance chez nous, et il y a gîte aussi pour passer la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Alors l\'homme s\'inclina et se prosterna devant l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'et dit: Béni soit l\'Éternel, Dieu de mon seigneur Abraham, qui ne s\'est pas départi de son amour et de sa fidélité envers mon seigneur! Pour moi, l\'Éternel m\'a guidé sur la route de la maison des frères de mon seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Et la jeune fille courut informer de ces choses la maison de sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Or Rebecca avait un frère, dont le nom était Laban. Et Laban accourut vers l\'homme dehors à la fontaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Et ayant vu l\'anneau et les bracelets aux mains de sa sœur, et entendu les discours de Rebecca, sa sœur, qui disait: Ainsi m\'a parlé cet homme, il vint auprès de l\'homme; et voici, il se tenait près de ses chameaux à la fontaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Et il dit: Entre, béni de l\'Éternel! pourquoi te tiens-tu dehors? J\'ai disposé la maison, et il y a place pour les chameaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Et l\'homme entra dans la maison; et [Laban] débâta les chameaux, et donna de la paille et du fourrage pour les chameaux, et de l\'eau pour laver ses pieds et les pieds des gens de sa suite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Et on lui servit à manger. Mais il dit: Je ne mangerai point que je n\'aie dit ce que j\'ai à dire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Et [Laban] répondit: Parle! Et il dit: Je suis serviteur d\'Abraham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Et l\'Éternel a grandement béni mon seigneur qui a est un homme considérable, et auquel Il a donné des brebis et des bœufs et de l\'argent et de l\'or et des serviteurs et des servantes, et des chameaux et des ânes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Et Sarah, femme d\'Abraham, mon seigneur, a dans sa vieillesse enfanté un fils à mon seigneur, et il lui a donné tout ce qu\'il possède.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Et mon seigneur m\'a adjuré en ces termes: Tu ne choisiras pour femme de mon fils aucune des filles des Cananéens dont j\'habite le pays;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'mais tu te rendras dans la maison de mon père et dans ma famille, et tu y choisiras une femme pour mon fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Et je dis à mon seigneur: Peut-être la femme ne voudra-t-elle pas me suivre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Et il me dit: L\'Éternel en la présence de qui j\'ai marché, enverra son ange avec toi, et fera réussir ton voyage, et tu prendras une femme pour mon fils dans ma famille et dans la maison de mon père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Alors tu seras libéré du serment que tu me fais, si tu vas t\'adresser à ma famille; et si on ne te l\'accorde pas, tu seras libéré du serment que tu me fais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Et en arrivant aujourd\'hui à la fontaine, j\'ai dit: Éternel, Dieu de mon seigneur Abraham, si tu daignes faire réussir mon voyage que je fais:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'voici, je me tiendrai près de la fontaine; et qu\'il se fasse que la jeune fille sortant pour puiser de l\'eau, à qui je dirai: Laisse-moi donc boire un peu d\'eau de ta cruche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'et qui me répondra: Bois toi-même, et je puiserai aussi pour tes chameaux, se trouve être la femme que l\'Éternel a destinée au fils de mon seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Je n\'avais pas encore fini de parler en mon cœur que voilà que Rebecca sort, la cruche sur l\'épaule, et descend à la fontaine et puise; et je lui dis: Donne-moi donc à boire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Et vite elle abaissa sa cruche de dessus son épaule et dit: Bois, et j\'abreuverai aussi tes chameaux, et je bus et elle abreuva aussi les chameaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Puis je lui fis cette question: De qui es-tu fille? Et elle répondit: De Béthuel, fils de Nachor à qui Milca l\'a enfanté. Et je mis l\'anneau à sa narine, et les bracelets à ses poignets.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Et je m\'inclinai et me prosternai devant l\'Éternel, et je bénis l\'Éternel, Dieu de mon seigneur Abraham, qui m\'a guidé dans la vraie voie pour marier la fille du frère de mon seigneur à son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Et maintenant, si votre intention est de témoigner à mon seigneur bienveillance et fidélité, déclarez-le-moi; dans le cas contraire, déclarez-le-moi, afin que je me tourne à droite ou à gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Alors Laban et Béthuel répondirent et dirent: Ceci procède de l\'Éternel; nous ne pouvons rien te dire ni en mal, ni en bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Voilà Rebecca devant toi; prends-la et t\'en va, et qu\'elle devienne la femme du fils de ton seigneur, ainsi qu\'a prononcé l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Et lorsque le serviteur d\'Abraham entendit leur discours, il se prosterna contre terre devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Et le serviteur sortit des joyaux d\'argent et des joyaux d\'or, et des habillements, et les donna à Rebecca, et il donna des objets de prix à son frère et à sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Alors ils mangèrent et burent, lui et les gens de sa suite, et passèrent la nuit. Et le matin ils se levèrent, et il dit: Laissez-moi retourner vers mon seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Et le frère et la mère de Rebecca dirent: Que la jeune fille reste avec nous quelques jours, soit dix jours; ensuite tu partiras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Mais il leur dit: Ne me retardez pas! L\'Éternel a fait réussir mon voyage, laissez-moi partir, afin que je retourne chez mon seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Et ils dirent: Nous appellerons la jeune fille et nous lui demanderons de se prononcer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Et ils appelèrent Rebecca et lui dirent: Vas-tu avec cet homme? Et elle répondit: Je vais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Sur quoi ils laissèrent partir Rebecca, leur sœur, et sa nourrice et le serviteur d\'Abraham et son monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Et ils bénirent Rebecca et lui dirent: O toi, notre sœur! deviens des milliers de myriades, Et que ta race occupe la porte de tes ennemis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Alors Rebecca et ses femmes se levèrent, et se placèrent sur les chameaux, et suivirent l\'homme; et le serviteur ayant pris Rebecca se mit en route.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Cependant Isaac était revenu de la fontaine du Vivant-qui-voit, car il habitait le Midi du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Et Isaac était sorti pour se livrer à ses pensées dans les champs à l\'approche du soir; et il leva les yeux et regarda, et voilà que des chameaux arrivaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Et Rebecca levant les yeux aperçut Isaac, et elle descendit de son chameau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Et elle dit au serviteur: Qui est cet homme qui s\'avance par les champs à notre rencontre? Et le serviteur dit: C\'est mon seigneur. Alors elle prit son voile et s\'en couvrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Et le serviteur raconta à Isaac toutes les choses qu\'il avait faites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Et Isaac introduisit Rebecca dans la tente de Sarah, sa mère, et il prit Rebecca, et elle devint sa femme et il l\'aima; et Isaac se consola après le deuil de sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Et Abraham prit une seconde femme, et son nom était Ketura.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Et elle lui enfanta Zimran et Jocsan et Medan et Midian et Jisbac et Suah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Et Jocsan engendra Séba et Dedan; et les fils de Dedan furent les Assurim et les Letusim et les Leummim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Et les fils de Midian: Epha et Epher et Henoch et Abida et Eldaah: tout autant de fils de Ketura.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Et Abraham donna tout ce qu\'il avait à Isaac;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'quant aux fils des concubines qu\'eut Abraham, il leur donna leur dot, et encore de son vivant il les envoya à distance d\'Isaac, son fils, vers l\'orient, au pays d\'Orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Et voici les jours des années de vie que vécut Abraham: cent soixante-quinze ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Et Abraham expira et il mourut dans une belle vieillesse, âgé et rassasié de jours, et il fut recueilli auprès de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Et Isaac et Ismaël, ses fils, lui donnèrent la sépulture dans la grotte de Macpéla, dans le champ de Ephron, fils de Tsohar, le Héthien, qui est à l\'orient de Mamré,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'champ qu\'Abraham avait acquis des fils de Heth; c\'est là qu\'Abraham reçut la sépulture, ainsi que Sarah sa femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Et après la mort d\'Abraham Dieu bénit Isaac, son fils, et Isaac demeura près de la fontaine du Vivant-qui-voit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Et c\'est ici l\'histoire d\'Ismaël, fils d\'Abraham, qu\'enfanta Agar, l\'Egyptienne, servante de Sarah, à Abraham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Et ce sont ici les noms des fils d\'Ismaël, nominativement, selon leurs familles: le premier né d\'Ismaël Nebaioth, et Cedar et Adbeel et Mibsam');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'et Misma, et Duma et Massa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadar et Theima, Jetur-Naphis et Kedma.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Tels sont les fils d\'Ismaël et ce sont là leurs noms selon leurs parcs et leurs campements, douze princes de leurs tribus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Et ce sont ici les années de vie d\'Ismaël: cent trente-sept ans; et il expira et mourut et fut recueilli auprès de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Et ils habitèrent de Havila à Sur qui est à l\'orient de l\'Egypte du côté d\'Assur; c\'est à l\'orient de tous ses frères qu\'il s\'établit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Et c\'est ici l\'histoire d\'Isaac, fils d\'Abraham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Abraham engendra Isaac. Et Isaac avait quarante ans lorsqu\'il prit pour femme Rebecca, fille de Béthuel, l\'Araméen, de Mésopotamie, sœur de Laban, l\'Araméen.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Et Isaac éleva sa prière à l\'Éternel au regard de sa femme, car elle était stérile. Et l\'Éternel se laissa fléchir par lui, et Rebecca, sa femme, devint enceinte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Et les enfants s\'entrechoquaient dans son sein. Alors elle dit: Si c\'est ainsi, pourquoi existé-je? Et elle alla consulter l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Et l\'Éternel lui dit: Deux nations sont dans tes flancs, Et deux peuples se dédoubleront au sortir de ton sein, Et l\'un sera plus fort que l\'autre, Et le grand sera sujet du petit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Et le moment de sa délivrance étant arrivé, voici, deux jumeaux étaient dans son sein;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'et le premier vint, tout fauve comme un manteau de fourrure, et on lui donna le nom d\'Esaü (velu).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Et ensuite son frère sortit et sa main tenait le talon de son frère, et on lui donna le nom de Jacob (supplanteur). Or Isaac avait soixante ans lorsqu\'ils naquirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Et les enfants devinrent grands, et Esaü devint habile à la chasse, et fut un homme des champs; mais Jacob fut un homme rangé qui se tenait dans les tentes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Et Isaac aimait Esaü, parce que Isaac était friand de venaison, tandis que Rebecca aimait Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Et [un jour] Jacob faisait cuire un potage, et Esaü revenait des champs, et il était rendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Et Esaü dit à Jacob: Régale-moi donc de roux, de ce roux-là, car je suis rendu. C\'est pour cela qu\'il reçut le nom de Edom (le roux).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Et Jacob dit: Vends-moi d\'abord ton droit d\'aînesse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Et Esaü dit: Voici, je vais à la mort, à quoi me sert mon droit d\'aînesse?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Et Jacob dit: Fais-moi d\'abord serment. Et il lui fit serment et vendit son droit d\'aînesse à Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Et Jacob donna à Esaü du pain et un potage de lentilles; et celui-ci mangea et but, et se leva et partit. C\'est ainsi qu\'Esaü méprisa son droit d\'aînesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Et il y eut une famine dans le pays, outre la première famine qui eut lieu au temps d\'Abraham; et Isaac alla a chez Abimélech, roi des Philistins, à Gérar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Et l\'Éternel lui apparut et dit: Ne descends point en Egypte, reste dans le pays que je t\'indique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Séjourne dans ce pays-ci, et je serai avec toi et te bénirai, car je veux te donner à toi et à ta postérité toutes ces contrées, et je maintiens le serment que j\'ai fait à Abraham, ton père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Et je rendrai ta postérité nombreuse comme les étoiles du ciel, et je donnerai à ta postérité toutes ces contrées-ci, et toutes les nations de la terre chercheront leur bénédiction dans ta postérité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'par la raison qu\'Abraham a écouté ma voix et observé mes observances, mes commandements, mes statuts et mes lois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Isaac resta donc à Gérar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Et lorsque les gens du lieu s\'informaient de sa femme, il disait: C\'est ma sœur, car il craignait de dire: c\'est ma femme, ayant peur que les gens du lieu ne le fissent mourir à cause de Rebecca, car elle était belle de figure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Et comme son séjour s\'y était prolongé, il arriva qu\'Abimélech, roi des Philistins, regardant par la fenêtre, aperçut Isaac qui faisait des caresses à Rebecca, sa femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Alors Abimélech manda Isaac et dit: Voici, c\'est assurément ta femme; et comment as-tu pu dire: C\'est ma sœur? Et Isaac lui dit: Je pensais recevoir la mort à cause d\'elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Et Abimélech dit: Pourquoi nous as-tu fait cela? peu s\'en est fallu que quelqu\'un de ce peuple n\'ait habité avec ta femme, et tu nous aurais chargés d\'un crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Alors Abimélech donna cet ordre à tout le peuple: Qui touchera à cet homme ou à sa femme, sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Et Isaac fit les semailles dans ce pays, et il obtint cette année-là le centuple; car l\'Éternel le bénissait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Et il s\'accrut et alla en s\'accroissant et en augmentant jusqu\'à devenir très considérable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Et il avait des troupeaux de menu bétail et des troupeaux de gros bétail, et un nombreux domestique, et les Philistins lui portèrent envie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Et tous les puits qu\'avaient creusés les serviteurs de son père au temps d\'Abraham, les Philistins les obstruèrent et les comblèrent avec de l\'arène.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Et Abimélech dit à Isaac: Va-t-en de chez nous, car tu es devenu trop puissant pour nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Alors Isaac partit de là et campa dans le ravin de Gérar, et il y demeura.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Et Isaac recreusa les puits qui avaient été creusés au temps d\'Abraham, son père, et qu\'avaient obstrués les Philistins après la mort d\'Abraham, et il les appela des mêmes noms dont son père les avait appelés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Et les serviteurs d\'Isaac creusèrent dans le ravin et y trouvèrent une fontaine d\'eau vive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Et les bergers de Gérar cherchèrent querelle aux bergers d\'Isaac, disant: Cette eau est à nous. Et il donna à la fontaine le nom de Esec (querelle), parce qu\'ils lui avaient cherché querelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Et ils creusèrent un autre puits, et on lui chercha encore querelle pour celui-ci, et il l\'appela du nom de Sitna hostilité).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Et il partit de là, et il creusa un autre puits, et pour celui-ci on ne lui chercha pas querelle et il l\'appela du nom de Rechoboth (le large) et dit: Maintenant l\'Éternel nous a donné du large, et nous nous propageons dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Et de là il si remonta à Beersébah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Alors l\'Éternel lui apparut cette nuit même et dit: Je suis le Dieu d\'Abraham, ton père: sois sans peur, car je suis avec toi, et je bénirai et multiplierai ta postérité en considération d\'Abraham, mon serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Et il éleva là un autel, et invoqua le nom de l\'Éternel, et il y dressa sa tente, et les serviteurs d\'Isaac y creusèrent un puits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Et Abimélech vint le trouver depuis Gérar avec Achuzath, son ami, et Phichol, son général d\'armée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Et Isaac leur dit: Pourquoi venez-vous chez moi, puisque vous me haïssez et m\'avez renvoyé de chez vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Et ils répondirent: Nous voyons bien que l\'Éternel est avec toi! c\'est pourquoi nous disons: Il faut qu\'un serment intervienne entre nous, entre nous et toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'et nous voulons stipuler avec toi par une alliance que tu ne nous feras aucun mal, de même que nous ne t\'avons point porté atteinte, et de même que nous n\'avons eu pour toi que de bons procédés et que nous t\'avons laissé partir sain et sauf. Tu es toujours béni de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Alors il leur fil un festin, et ils mangèrent et burent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Et ils se levèrent le matin, et ils se firent serment l\'un à l\'autre, et Isaac les congédia et ils le quittèrent en paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Et le même jour il arriva que des serviteurs d\'Isaac vinrent le renseigner sur le puits qu\'ils creusaient et lui dirent: Nous avons trouvé de l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Et il l\'appela Siba (sept); c\'est pourquoi la ville a porté jusqu\'aujourd\'hui le nom de Beersébah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Et Esaü étant âgé de quarante ans, prit pour femmes Judith, fille de Beeri, Héthien, et Bosemath, fille de Elon, Héthien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Et elles furent un chagrin de cœur pour Isaac et Rebecca.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Et Isaac devenu vieux et ayant les yeux faibles à ne plus voir, appela son fils aîné et lui dit: Mon fils! Et il lui répondit: Me voici!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Et Isaac dit: Me voici donc vieux, et j\'ignore le jour de ma mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Prends donc à présent ton attirail de chasse, ton carquois et ton arc, et va dans les champs à la chasse d\'un gibier pour moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'et fais-m\'en un mets appétissant comme j\'aime, et apporte-le-moi, afin que j\'en mange pour que mon âme te bénisse avant ma mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Or Rebecca avait écouté l\'entretien d\'Isaac avec Esaü, son fils. Et Esaü s\'en alla dans les champs pour chasser un gibier et le rapporter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Mais Rebecca parla à Jacob, son fils, en ces termes: J\'ai ouï ton père parler à Esaü, ton frère, et lui dire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Apporte-moi un gibier et fais-m\'en un mets appétissant, et j\'en mangerai, et je te bénirai devant l\'Éternel avant de mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Dès lors, mon fils, sois docile à ma voix pour ce que je vais te prescrire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Va-t\'en au bercail, et m\'y choisis deux bons chevreaux, et j\'en ferai un mets appétissant pour ton père comme il aime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Et tu le serviras à ton père, pour qu\'il en mange, pour qu\'il te bénisse avant de mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Et Jacob dit à Rebecca, sa mère: Voici, Esaü, mon frère, est velu, et j\'ai le corps lisse:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'peut-être mon père voudra-t-il me palper, et alors j\'aurais à ses yeux l\'air de le jouer et j\'attirerais sur moi une malédiction et non une bénédiction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Et sa mère lui dit: Je me charge de la malédiction que tu recevrais, mon fils! Sois seulement docile à ma voix, et va me les chercher?...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Alors il alla les chercher, et il les apporta à sa mère qui en fit un mets appétissant, comme aimait son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Et Rebecca prit les habits d\'Esaü, son fils aîné, ses habits de prix qu\'elle avait chez elle dans la maison, et elle en revêtit Jacob, son fils cadet,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'et avec les peaux des chevreaux elle recouvrit ses mains, et la partie lisse de son col.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Et elle mit dans la main de Jacob, son fils, le mets appétissant et le pain qu\'elle avait préparés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Alors il entra chez son père et dit: Mon père! Et il répondit: Me voici! qui es-tu, mon fils?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Et Jacob dit à son père: Je suis Esaü, ton premier-né, j\'ai fait ce que tu m\'as dit. Lève-toi donc, mets-toi sur ton séant et mange de mon gibier afin que ton âme me bénisse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Et Isaac dit à son fils: Comme tu as promptement trouvé, mon fils! Et celui-ci dit: L\'Éternel, ton Dieu, l\'a fait venir au-devant de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Et Isaac dit à Jacob: Approche donc, mon fils, pour que je sente au toucher si c\'est toi qui es mon fils Esaü, ou non.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Et Jacob s\'approcha d\'Isaac, qui le palpa, puis dit: La voix est la voix de Jacob, et les mains sont les mains d\'Esaü.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Et il ne le reconnut pas, parce que ses mains étaient, comme les mains d\'Esaü, velues; et il le bénit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Et il dit: C\'est toi présent qui es mon fils Esaü? Et Jacob répondit: Je le suis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Et [Isaac] dit: Sers-moi et je mangerai de ton gibier, mon fils, afin que mon âme te bénisse. Et Jacob le servit, et il mangea; et il lui présenta du vin se et il but.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Et Isaac, son père, lui dit: Approche donc, et embrasse-moi, mon fils!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Et il s\'approcha et l\'embrassa. Alors il sentit l\'odeur de ses habits et il le bénit et dit: Voyez! le parfum de mon fils est le parfum d\'un champ que l\'Éternel a béni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Que Dieu te donne de la rosée des cieux et les lieux les plus gras de la terre, et abondance de blé et de moût!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Que des peuples te soient asservis et que des nations te rendent leur hommage! Aie la suprématie sur tes frères et que les fils de ta mère s\'inclinent devant toi. Maudits soient ceux qui te maudiront, et bénis soient ceux qui te béniront!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Et lorsque Isaac eut terminé la bénédiction de Jacob, et comme Jacob ne faisait que sortir de la présence d\'Isaac, son père, Esaü, son frère, arriva de la chasse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Et il apprêta aussi un mets appétissant, et il le servit à son père et lui dit: Que mon père se lève et mange du gibier de son fils, afin que ton âme me bénisse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Et Isaac, son père, lui dit: Qui es-tu? Et il répondit: Je suis ton fils premier-né, Esaü.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Alors la consternation d\'Isaac fut grande, il fut profondément consterné et dit: Qui était-ce donc qui a chassé du gibier et me l\'a apporté? et j\'ai mangé de tout avant que tu vinsses, et je l\'ai béni, et béni il sera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'A l\'ouïe des paroles de son père, Esaü se récria grandement et avec amertume et il dit à son père: Bénis-moi, moi aussi, mon père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Et il dit: Ton frère est venu par surprise et a enlevé la bénédiction qui était à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Et il dit: Ne l\'a-t-on pas appelé du nom de Jacob (supplanteur)? Et voici deux fois qu\'il me supplante: il m\'a enlevé mon droit d\'aînesse, et voilà que maintenant il m\'enlève ma bénédiction! Et il dit: Ne m\'as-tu point réservé de bénédiction?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Et Isaac répondit et dit à Esaü: Voici, je lui ai donné la suprématie sur toi et j\'ai constitué tous ses frères ses serviteurs, et je l\'ai pourvu de blé et de moût: que pourrais-je donc faire pour toi, mon fils?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Et Esaü dit à son père: Est-ce là ton unique bénédiction, mon père? Bénis-moi, moi aussi, mon père! Et Esaü éleva sa voix et pleura.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Alors Isaac, son père, répondit et lui dit: Vois! des fertiles terrains seront ton séjour, et d\'en haut tu auras de la rosée des cieux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Et tu vivras de ton épée, et à ton frère tu seras asservi; mais il arrivera que, mobile comme tu l\'es, brisant son joug tu le secoueras de ton col.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Et Esaü devint hostile à Jacob ensuite de la bénédiction dont son père l\'avait béni. Et Esaü dit en son cœur: Les jours du deuil de mon père approchent, alors je tuerai Jacob, mon frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Et l\'on rapporta à Rebecca les propos d\'Esaü, son fils aîné; et elle envoya chercher Jacob, son fils cadet, et lui dit: Voici, Esaü, ton frère, va tirer vengeance de toi en te tuant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Dès lors, mon fils, sois docile à ma voix: lève-toi et t\'enfuis chez Laban, mon frère, à Charan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'et reste auprès de lui quelque temps');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'jusqu\'à ce que l\'animosité de ton frère se calme, que la colère de ton frère cesse à ton égard et qu\'il oublie ce que tu lui as fait: alors je te ferai rechercher. Pourquoi vous perdrais-je les deux en un jour?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Et Rebecca dit à Isaac: Je suis dégoûtée de la vie à cause des filles de Heth; si Jacob prend parmi les filles de Heth, parmi les filles du pays, une femme pareille à celles-là, que sera pour moi la vie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Alors Isaac fit venir Jacob et le bénit, et il lui donna ses ordres en ces termes: Tu ne prendras point de femme parmi les filles de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Lève-toi et t\'en va en Mésopotamie dans la maison de Béthuel, père de ta mère, et là choisis-toi une femme parmi les filles de Laban, frère de ta mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Et que Dieu, le Tout-Puissant, te bénisse et te rende fécond et te multiplie, afin que tu deviennes une multitude de peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Et qu\'il te confère la bénédiction d\'Abraham, à toi et à ta postérité avec toi, afin que tu possèdes le pays de tes pèlerinages, que Dieu a donné à Abraham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Et Isaac congédia Jacob, qui prit son chemin vers la Mésopotamie, vers Laban, fils de Bcthuel, l\'Araméen, frère de Rebecca, mère de Jacob et d\'Esaü.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Et Esaü voyant qu\'Isaac avait béni Jacob et l\'avait envoyé en Mésopotamie pour s\'y choisir une femme, en le bénissant et lui donnant cet ordre: Tu ne prendras point de femme parmi les filles de Canaan;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'et que Jacob avait obéi à son père et à sa mère et était parti pour la Mésopotamie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Esaü vit alors que les filles de Canaan déplaisaient à son père Isaac,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'et Esaü alla chez Ismaël, et en sus des femmes qu\'il avait, il épousa Mahalath, fille d\'Ismaël, fils d\'Abraham, sœur de Nebaioth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Ainsi Jacob partit de Beersébah et gagna Charan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Et étant arrivé en un certain lieu, il y passa la nuit, car le soleil était couché. Et prenant une des pierres de l\'endroit il en fit son chevet, et il coucha dans ce lieu-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Alors il eut un songe, et voici, une échelle était dressée sur la terre, et son sommet touchait au ciel, et voici, les anges de Dieu la montaient et la descendaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Et voici, l\'Éternel se tenait au-dessus d\'elle et disait: Je suis l\'Éternel, Dieu d\'Abraham, ton père, et Dieu d\'Isaac. Cette terre où tu es couché, je te la donnerai à toi et à ta postérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Et ta postérité deviendra comme la poussière de la terre, et tu t\'étendras à l\'occident et à l\'orient et au septentrion et au midi, et toutes les races de la terre auront leur bénédiction dans toi et dans ta postérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Et voici, je suis avec toi pour te garder partout où tu iras, et te ramener dans ce pays; car je ne te quitterai point que je n\'aie exécuté ce que je t\'ai promis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Alors Jacob se réveilla de son sommeil et dit: En vérité, l\'Éternel est en ce lieu, et je ne le savais pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Et il eut crainte et dit: Que ce lieu est redoutable! Ce n\'est autre chose que la maison de Dieu, et c\'est la porte des cieux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Et Jacob se leva le matin, et prit la pierre dont il avait fait son chevet, et l\'érigea en monument et versa de l\'huile sur sa cime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Et il donna à ce lieu le nom de Béthel (maison de Dieu); or dans l\'origine Luz était le nom de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Et Jacob prononça un vœu en ces termes: Si Dieu est avec moi et me garde pendant le voyage que je fais maintenant, et me donne du pain pour me nourrir et des habits pour me vêtir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'et si je reviens sain et sauf dans la maison de mon père, l\'Éternel sera mon Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'et cette pierre que j\'ai dressée comme monument, deviendra une maison de Dieu, et je Te paierai la dîme de tout ce que Tu me donneras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Et levant les pieds, Jacob s\'en alla au pays des enfants de l\'orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Et il regarda, et voici, c\'était une fontaine dans la campagne, et voici, là à côté reposaient trois troupeaux de brebis; car c\'est à cette fontaine qu\'on abreuvait les troupeaux, et grande était la pierre qui en fermait l\'ouverture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Et tous les troupeaux y étaient ramassés, puis les bergers écartaient la pierre de l\'ouverture de la fontaine, et abreuvaient leurs troupeaux, et ramenaient la pierre sur l\'ouverture de la fontaine à sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Alors Jacob leur dit: Mes frères, d\'où êtes-vous? Et ils répondirent: Nous sommes de Charan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Et il leur dit: Connaissez-vous Laban, fils de Nachor? Et ils répondirent: Nous le connaissons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Et il leur dit: Tout va-t-il bien pour lui? Et ils répondirent: Bien; et voici venir Rachel, sa fille, avec son troupeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Et il dit: Voici, il est encore grand jour; et il n\'est pas temps de réunir les troupeaux; abreuvez les brebis, puis allez, faites-les paître!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Et ils répondirent: Nous ne le pouvons pas que tous les troupeaux ne soient ramassés; c\'est alors qu\'on écarte la pierre de l\'ouverture de la fontaine, et nous abreuvons les brebis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Il s\'entretenait encore avec eux, lorsque Rachel arriva avec le troupeau de son père, car elle était bergère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Et lorsque Jacob vit Rachel, fille de Laban, frère de sa mère, et le troupeau de Laban, frère de sa mère, il s\'approcha, et écarta la pierre de l\'ouverture de la fontaine, et abreuva le troupeau de Laban, frère de sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Et Jacob embrassa Rachel, et éleva sa voix et pleura.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Et Jacob découvrit à Rachel qu\'il était parent de son père, et qu\'il était fils de Rebecca; et elle courut en donner avis à son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Et lorsque Laban ouït parler de Jacob, fils de sa sœur, il accourut au devant de lui, et l\'étreignit et l\'embrassa, et l\'amena dans sa maison; et il raconta à Laban tous ces détails.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Alors Laban lui dit: Oui, tu es ma chair et mes os! Et il demeura chez lui un mois de temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Alors Laban dit à Jacob: Mais n\'es-tu pas mon parent, et me servirais-tu gratuitement? Dis-moi quel doit être ton salaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Or Laban avait deux filles, l\'aînée s\'appelait Léa et la cadette, Rachel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'et Léa avait les yeux délicats, mais Rachel était belle de taille et belle de figure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Et Jacob aimait Rachel et dit: Je te servirai sept ans pour Rachel, ta fille cadette.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Et Laban dit: J\'aime mieux te la donner que de la donner à un autre homme: reste avec moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Et Jacob servit sept années pour Rachel, et elles lui semblèrent comme quelques jours, parce qu\'il l\'aimait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Et Jacob dit à Laban: Donne-moi ma femme, car mon temps est accompli, afin que j\'habite avec elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Alors Laban rassembla tous les gens du lieu, et fit un festin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Et le soir il prit Léa, sa fille, et la lui amena, et il s\'approcha d\'elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Et Laban donna à Léa, sa fille, pour servante, Zilpa sa servante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Et le matin, voilà que c\'était Léa! Et il dit à Laban: Pourquoi en as-tu agi ainsi avec moi? N\'est-ce pas pour, Rachel que je t\'ai servi? et pourquoi m\'as-tu trompé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Et Laban dit: Ce n\'est pas la pratique de ce lieu de placer la cadette avant l\'aînée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Passe la semaine [de noces] de celle-ci, puis nous te donnerons aussi l\'autre pour le service que tu feras chez moi sept nouvelles années encore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Et ainsi fit Jacob, qui accomplit la semaine de Léa; puis il lui donna sa fille Rachel pour femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Et Laban donna pour servante à Rachel, sa fille, Bilha, sa servante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Et il habita aussi avec Rachel et il aima aussi Rachel plus que Léa; et il le servit sept nouvelles années encore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Et l\'Éternel voyant que Léa n\'était pas aimée, la rendit féconde, tandis que Rachel était stérile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Et Léa devint enceinte, et enfanta un fils, et elle l\'appela du nom de Ruben (voyez un fils); car elle dit: L\'Éternel a vu ma misère; et maintenant mon mari m\'aimera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Et elle devint encore enceinte et enfanta un fils et dit: L\'Éternel a ouï que je ne suis pas aimée, et Il m\'a accordé aussi celui-ci. Et elle l\'appela du nom de Siméon (exaucement).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Et elle devint encore enceinte, et enfanta un fils et dit: Pour cette fois mon mari s\'attachera à moi, car je lui ai enfanté trois fils; c\'est pourquoi on l\'appela du nom de Lévi (attachement).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Et elle devint encore enceinte et enfanta un fils et dit: Cette fois je louerai l\'Éternel; c\'est pourquoi elle l\'appela du nom de Juda (louange de Dieu). Et elle cessa d\'enfanter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Et Rachel voyant qu\'elle ne donnait point d\'enfants à Jacob, elle fut jalouse de sa sœur, et elle dit à Jacob: Procure-moi des enfants! sinon, je meurs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Et Jacob s\'irrita contre Rachel et dit: Ne suis-je pas aussi sous la dépendance de Dieu qui t\'a refusé le fruit d\'un sein fécond?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Et elle dit: Voici ma servante Bilha, habite avec elle afin que je reçoive sur mes genoux ce qui naîtra d\'elle, et que par elle moi aussi je me fasse une maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Et elle lui donna Bilha, sa servante, pour femme, et Jacob habita avec elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Et Bilha devint enceinte et enfanta à Jacob un fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Alors Rachel dit: Dieu a été mon arbitre et a aussi écouté ma voix et m\'a donné un fils. C\'est pourquoi elle l\'appela du nom de Dan (arbitre).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Et Bilha, servante de Rachel, devint encore enceinte et enfanta à Jacob un second fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Alors Rachel dit: J\'ai soutenu avec ma sœur des luttes de Dieu, et je l\'ai emporté. Et elle l\'appela du nom de Nephthali (ma lutte).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Et Léa, voyant qu\'elle cessait d\'avoir des enfants, prit Zilpa, sa servante, et la donna à Jacob pour femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Et Zilpa, servante de Léa, enfanta à Jacob un fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Alors Léa dit: Avec bonheur! Et elle l\'appela du nom de Gad (bonne étoile).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Et Zilpa, servante de Léa, enfanta à Jacob un second fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Alors Léa dit: A ma félicité! Car les filles des hommes me féliciteront. Et elle l\'appela du nom d\'Asser (l\'heureux).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Et Ruben sortit au temps de la moisson des blés, et trouva des mandragores dans les champs, et il les apporta à Léa, sa mère. Alors Rachel dit à Léa: Donne-moi donc des mandragores de ton fils!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Et Léa lui répondit: Est-ce si peu de m\'avoir pris mon mari, que tu veux aussi prendre les mandragores de mon fils? Et Rachel dit: Eh bien! il couchera avec toi cette nuit pour les mandragores de ton fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Et comme Jacob revenait des champs le soir, Léa sortit à sa rencontre et lui dit: Tu t\'approcheras de moi, car je t\'ai retenu en cédant les mandragores de mon fils. Et il coucha avec elle cette nuit-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Et Dieu exauça Léa, et elle devint enceinte, et enfanta à Jacob un cinquième fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Alors Léa dit: Dieu ma donné mon salaire, pour avoir donné ma servante à mon mari. Et elle l\'appela du nom de Issaschar (c\'est le salaire).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Et Léa devint encore enceinte et enfanta à Jacob un sixième fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Alors Léa dit: Dieu m\'a fait un beau don; maintenant mon mari demeurera avec moi, puisque je lui ai enfanté six fils. Et elle l\'appela du nom de Zabulon (demeure).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Et ensuite elle enfanta une fille et l\'appela du nom de Dina.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Et Dieu se souvint de Rachel et l\'exauça et la rendit féconde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Et elle devint enceinte et enfanta un fils et dit: Dieu a enlevé mon opprobre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Et elle l\'appela du nom de Joseph (il enlève) et dit: Que Dieu ajoute en ma faveur un autre fils!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Et lorsque Rachel eut enfanté Joseph, Jacob dit à Laban: Donne-moi mon congé, pour que je puisse m\'en aller chez moi et dans mon pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Donne-moi mes femmes et mes enfants pour lesquels je t\'ai servi, afin que je parte; car tu connais mon service que j\'ai accompli pour toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Laban lui dit: Ah! si j\'avais trouvé grâce à tes yeux... J\'avais bien auguré que l\'Éternel me bénirait par ton moyen.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Et il dit: Fixe le salaire que je te devrai, et je te le paierai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Et [Jacob] lui dit: Tu sais comment je t\'ai servi, et ce que ton troupeau est devenu avec moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Car ce que tu avais avant moi était peu de chose, et il y a eu accroissement considérable, et l\'Éternel envoyait chez toi la bénédiction sur mes pas; et maintenant, quand travaillerai-je aussi pour ma maison?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Et [Laban] dit: Que dois-je te donner? Et Jacob répondit: Tu ne me donneras rien; mais si tu veux me traiter à ces conditions-ci, je reprendrai la conduite et la garde de tes brebis:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'aujourd\'hui je parcourrai tout ton troupeau, mettant à part parmi les brebis toutes les pièces marquetées et tachetées, et toutes les brunes, et parmi les chèvres toutes celles qui sont tachetées et marquetées; et ce sera là mon salaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Et ma droiture répondra pour moi demain, quand tu en viendras à mon salaire: toutes les chèvres qui ne seront pas tachetées et marquetées, et toutes les brebis qui ne seront pas brunes, seront un vol chez moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Et Laban dit: Eh bien! qu\'il en soit comme tu le dis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Et le jour même il mit à part les boucs bigarrés et tachetés, et toutes les chèvres marquetées et tachetées, toutes celles où il y avait du blanc, et tout ce qu\'il y avait de brebis noires, et il les remit aux soins de ses fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Et il mit un espace de trois journées de marche entre lui et Jacob, et Jacob eut la conduite du reste du troupeau de Laban.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Alors Jacob se pourvut de baguettes fraîches de peuplier blanc, d\'amandier et d\'érable, et il y pela des bandes blanches, en mettant à nu le blanc du bois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Puis il plaça les verges qu\'il avait ainsi écorcées, dans les auges, les abreuvoirs où les brebis venaient boire les unes vis-à-vis des autres. Et elles s\'accouplaient lorsqu\'elles venaient boire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Et les brebis s\'accouplaient tournées vers les baguettes, et elles mettaient bas des portées bigarrées, tachetées et marquetées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Et Jacob mettait à part les agneaux bigarrés, et il faisait que les brebis eussent en vue les bigarrées et toutes les brunes appartenant au troupeau de Laban, et il se formait des troupeaux séparés qu\'il ne joignait point au troupeau de Laban.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Et toutes les fois que les moutons vigoureux s\'accouplaient, Jacob plaçait les verges devant les yeux des brebis dans les auges, pour que l\'accouplement se fit en face des baguettes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'mais quand les brebis étaient débiles, il ne les plaçait pas; et ainsi les débiles allaient à Laban et les vigoureuses à Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Et Jacob s\'accrut de plus en plus, et il acquit un grand nombre de brebis et de servantes et de serviteurs et de chameaux et d\'ânes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Et il entendit les propos des fils de Laban qui disaient: Jacob s\'est emparé de tout ce qui était à notre père, et c\'est de ce qui était à notre père qu\'il a formé toute cette opulence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Et Jacob remarqua l\'air de Laban, et voici, il n\'était plus envers lui comme ci-devant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Et l\'Éternel dit à Jacob: Retourne au pays de tes pères et au lieu de ta naissance, et je serai avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Alors Jacob dépêcha auprès de Rachel et de Léa pour les faire venir aux champs vers son troupeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Et il leur dit: Je vois que votre père n\'a plus pour moi le même air que ci-devant; mais le Dieu de mon père a été avec moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Vous-mêmes vous savez que j\'ai servi votre père de tout mon pouvoir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'mais votre père m\'a trompé et a changé mon salaire dix fois, mais Dieu ne lui a pas permis de me nuire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Quand il parlait ainsi: Tu auras pour ton salaire les tachetées, toutes les brebis mettaient bas des agneaux tachetés; et quand il disait: Tu auras pour salaire les bigarrées, tout le troupeau mettait bas des portées bigarrées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'C\'est ainsi que Dieu a retiré le troupeau de votre père et me l\'a donné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Et il arriva à l\'époque de l\'accouplement des brebis que je levai les yeux, et eus une vue en songe; et voilà que les béliers qui saillissaient les brebis, étaient bigarrés, tachetés et marquetés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Et l\'ange de Dieu me dit dans le songe: Jacob! Et je dis: Me voici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Et il dit: Lève donc les yeux et regarde! tous les béliers qui saillissent les brebis, sont bigarrés, tachetés et marquetés; car j\'ai vu tout ce que te fait Laban.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Je suis le Dieu de Beth-El où tu as oint un monument et où tu m\'as fait un vœu. Or lève-toi, quitte ce pays, et retourne au pays de ta naissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Alors Rachel et Léa répondirent et lui dirent: Avons-nous encore une part et un héritage dans la maison de notre père?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'N\'avons-nous pas été regardées par lui comme des étrangères? car il nous a vendues, et a aussi mangé l\'argent payé pour nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Toute la richesse que Dieu a retirée à notre père, est à nous et à nos enfants: dès lors fais tout ce que Dieu t\'a dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Sur quoi Jacob se mit en devoir et fit monter ses fils et ses femmes sur les chameaux');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'et emmena tout son bétail et tous ses biens qu\'il avait acquis, le bétail qui était sa propriété acquise en Mésopotamie, pour venir joindre son père Isaac au pays de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Cependant Laban était allé faire la tonte de ses brebis. Et Rachel déroba les Théraphims de son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Et Jacob trompa le cœur de Laban, l\'Araméen, en ne le prévenant pas de sa fuite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Il prit donc la fuite avec tout ce qui lui appartenait, et il se mit en route et passa le fleuve, et prit la direction de la montagne de Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Et le troisième jour Laban eut avis de la fuite de Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Alors il prit ses frères avec lui, et le poursuivit sept journées de marche et il l\'atteignit à la montagne de Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Mais Dieu vint trouver Laban, l\'Araméen, dans un songe de la nuit et lui dit: Garde-toi de rien dire à Jacob, ni en bien, ni en mal!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Laban atteignit donc Jacob. Or Jacob avait dressé sa tente sur la montagne, et Laban la dressa aussi avec ses frères sur la montagne de Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Alors Laban dit à Jacob: Qu\'as-tu fait d\'avoir trompé mon cœur et emmené mes filles comme des captives prises avec l\'épée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Pourquoi fuir clandestinement, et me tromper et ne pas m\'informer? et je t\'aurais accompagné joyeusement, au son des chants, de la cymbale et du luth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Et pourquoi ne m\'as-tu pas laissé donner le baiser à mes fils et à mes filles? Dès lors tu as follement agi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'J\'ai la force en main pour vous faire du mal, mais le Dieu de votre père m\'a parlé hier et m\'a dit: Garde-toi de rien dire à Jacob, ni en bien, ni en mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Eh bien! tu es parti parce que tu languissais après la maison de ton père; mais pourquoi m\'as-tu dérobé mes dieux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Alors Jacob répondit et dit à Laban: J\'étais en crainte pensant que tu me soustrairais tes filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Mais celui chez qui tu trouveras tes dieux, ne restera pas en vie! En présence de nos frères fouille ce qui m\'appartient, et reprends-les. Or Jacob ignorait que Rachel les avait dérobés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Puis Laban entra dans la tente de Jacob et dans la tente de Léa et dans la tente des deux servantes, et ne trouva rien; et il sortit de la tente de Léa et entra dans la tente de Rachel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Or Rachel avait pris les Théraphims et les avait mis dans le bât d\'un chameau et s\'était assise dessus. Et Laban fouilla toute la tente et ne trouva rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Et elle dit à son père: Que mon seigneur ne s\'irrite pas de ce que je ne puis me lever devant toi, car j\'ai ce qui survient aux femmes. Et il chercha et ne trouva point les Théraphims.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Alors Jacob s\'irrita et querella Laban; et prenant la parole Jacob dit à Laban: Quel est mon crime, quel est mon péché');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'pour que tu m\'aies poursuivi, pour que tu aies fouillé tous mes bagages? Lequel de tous les meubles de ta maison as-tu trouvé? Produis-le ici devant mes frères et tes frères, et qu\'ils soient arbitres entre nous deux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Voici vingt ans que j\'ai passés avec toi; tes brebis et tes chèvres n\'ont point avorté, et je n\'ai pas mangé les béliers de ton troupeau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'je ne t\'apportais point les bêtes déchirées, j\'en supportais la perte, et tu me réclamais ce qui m\'était volé de jour et ce qui m\'était volé de nuit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'de jour j\'étais dévoré par le chaud, et de nuit par la froidure, et le sommeil fuyait mes paupières.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Me voici avec vingt ans passés à te servir dans ta maison, quatorze ans pour tes deux filles et six ans pour ton troupeau; et dix fois tu as changé mon salaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Si le Dieu de mon père et le Dieu d\'Abraham et Celui qu\'Isaac redoute n\'eût été avec moi, tu m\'aurais laissé partir sans rien. Dieu a eu égard à ma misère et au labeur de mes mains, et la nuit dernière Il a jugé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Alors Laban répondit et dit à Jacob: Ces filles sont mes filles, et ces fils, mes fils, et ce troupeau, mon troupeau, et tout ce que tu vois, est à moi; et pour mes filles que puis-je faire aujourd\'hui, et pour leurs fils qu\'elles ont enfantés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Eh bien donc! faisons un pacte moi et toi et qu\'il soit témoin entre moi et toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Alors Jacob prit une pierre, et l\'érigea en monument.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Et Jacob dit à ses frères: Ramassez des pierres; et ils prirent des pierres et en firent une pile, et ils mangèrent là sur la pile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Et Laban l\'appela du nom de Jegar Sahadutha; mais Jacob l\'appela Galed (pile du témoignage).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Et Laban dit: Que cette pile soit aujourd\'hui témoin entre moi et toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'C\'est pourquoi on l\'appelle du nom de Galed et de Mitspa (vedette) parce qu\'il dit: Que l\'Éternel veille entre toi et moi, quand nous ne serons plus en vue l\'un de l\'autre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'à ce que tu ne rendes pas mes filles malheureuses, et que tu n\'associes pas d\'autres femmes à mes filles. Personne n\'est avec nous, vois, Dieu est témoin entre moi et toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Et Laban dit à Jacob: Voici cette pile, et voici ce monument que j\'ai élevé entre toi et moi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'qu\'elle soit témoin cette pile, qu\'il soit témoin ce monument, que pour nous nuire l\'un à l\'autre nous ne nous avancerons point au-delà de ce monument, ni moi de ton côté, ni toi de mon côté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Que le Dieu d\'Abraham et le Dieu de Nachor soit soit juge entre nous, le Dieu de leurs pères. Alors Jacob jura par Celui qu\'Isaac, son père, redoutait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Et Jacob offrit un sacrifice sur la montagne, et il invita ses frères à manger le pain, et ils mangèrent le pain et passèrent la nuit sur la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Et Laban se leva le matin, et donna le baiser à ses fils et à ses filles, et les bénit et partit, et Laban retourna chez lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Jacob de son côté poursuivit sa route, et il eut la rencontre d\'anges de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Et il dit en les voyant: C\'est le camp de Dieu! Et il donna à ce lieu le nom de Mahanaïm (double camp).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Et Jacob envoya devant lui des messagers à Esaü, son frère, dans le pays de Seïr, dans le pays d\'Edom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'et il leur donna ses instructions en ces termes: Ainsi vous parlerez à mon seigneur Esaü: Ainsi parle ton serviteur Jacob: J\'ai séjourné chez Laban et y suis resté jusqu\'à présent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'et j\'ai acquis des bœufs et des ânes, des brebis, et des serviteurs et des servantes, et j\'en fais donner avis à mon seigneur, pour trouver grâce à tes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Et les messagers revinrent auprès de Jacob en disant: Nous nous sommes rendus chez ton frère, chez Esaü; et de plus il est en marche à ta rencontre et a quatre cents hommes avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Alors Jacob craignit fort et fut dans la détresse, et il partagea le monde qui était avec lui, et le menu et le gros bétail et les chameaux, en deux camps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Et il dit: Si Esaü fond sur l\'un des camps et le met en déroute, le camp qui restera pourra se sauver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Et Jacob dit: Dieu de mon père Abraham, et Dieu de mon père Isaac, Éternel, qui m\'as dit: Retourne dans ton pays et dans ta patrie, je veux être ton bienfaiteur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'je Suis trop petit pour toutes les grâces et pour toute la fidélité que tu as montrée à ton serviteur; car avec mon bâton j\'ai passé ce Jourdain, et maintenant je forme deux caravanes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Ah! sauve-moi de la main de mon frère, de la main d\'Esaü, car je le redoute, je crains qu\'il ne vienne et ne me fasse tomber sous ses coups, la mère sur les enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Aussi bien tu as dit: Je veux être ton bienfaiteur, et rendre ta postérité égale au sable de la mer, qu\'on ne peut compter tant il est immense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Et il passa cette nuit en ce lieu, et il prit dans ce qu\'il transportait avec lui un présent pour Esaü, son frère,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'deux cents chèvres, vingt boucs, deux cents brebis et vingt béliers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'trente chamelles mères avec leurs petits, quarante vaches et dix taureaux, vingt ânesses et dix ânes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Et il les remit à ses serviteurs, chaque troupeau séparément, et il dit à ses serviteurs: Précédez-moi, et laissez une distance entre un troupeau et l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Et il donna cet ordre au premier: Si Esaü, mon frère, te rencontre et te fait cette question: A qui es-tu? et où vas-tu? et à qui est ce troupeau qui est devant toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'tu répondras: A ton serviteur Jacob; c\'est un présent envoyé à mon seigneur Esaü, et voici, il vient lui-même après nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Et il donna aussi ses ordres et au second, et au troisième, et à tous ceux qui marchaient derrière les troupeaux, en ces termes: C\'est en ces termes que vous parlerez à Esaü, quand vous le trouverez,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'et vous direz: Voici, ton serviteur Jacob vient aussi après nous. Car il se disait: Je veux l\'apaiser au moyen du présent qui me précède, et ensuite je le verrai; peut-être me fera-t-il bon accueil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Et ainsi le présent prenait l\'avance sur lui; et il passa cette nuit au camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Et il se leva la même nuit et prit ses deux femmes et ses deux servantes et ses onze enfants, et passa le gué du Jabok,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'et les prit et leur fit passer la rivière, et il transporta tout ce qu\'il avait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Et Jacob resta ainsi seul. Alors un homme lutta avec lui jusqu\'au lever de l\'aurore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Et voyant qu\'il ne pouvait le vaincre, il le frappa à l\'articulation de la hanche, et l\'articulation de la hanche de Jacob fut luxée pendant qu\'il luttait avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Et il dit: Laisse-moi aller, car l\'aurore se lève. Et il dit: Je ne te laisse point aller que tu ne m\'aies béni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Et il lui dit: Quel est ton nom? Et il répondit: Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Et il dit: Jacob ne sera plus le nom dont on t\'appellera, mais Israël, car tu as lutté avec Dieu et avec des hommes et tu l\'as emporté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Et Jacob l\'interrogeant lui dit: Découvre-moi donc ton nom. Et il dit: Pourquoi me demandes-tu donc mon nom? Et Il le bénit là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Et Jacob appela ce lieu du nom de Pniel (face de Dieu); « car j\'ai vu Dieu face à face et mon âme a été sauvée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Et le soleil se levait comme il passait à Pniel; mais il boitait de sa hanche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'C\'est pourquoi les enfants d\'Israël ne mangent point jusqu\'aujourd\'hui le tendon qui est à l\'articulation de la hanche, parce qu\'il avait frappé l\'articulation de la hanche de Jacob, le tendon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Et Jacob leva les yeux et regarda, et voilà qu\'Esaü arrivait, et avec lui quatre cents hommes. Alors il distribua les enfants à Léa et Rachel, et aux deux servantes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'et il plaça les servantes et leurs enfants en tête et Léa et ses enfants ensuite et Rachel et Joseph à l\'arrière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Lui-même marchait devant eux, et il s\'inclina sept fois contre terre jusqu\'à ce qu\'il fût près de son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Alors Esaü courut à sa rencontre, et l\'étreignit et se jeta à son cou et l\'embrassa; et ils pleurèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Et levant les yeux il aperçut les femmes et les enfants et il dit: Qui as-tu là? Et il répondit: Les enfants dont Dieu a gratifié ton serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Alors les servantes s\'avancèrent avec leurs enfants et se prosternèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Et Léa s\'avança aussi avec ses enfants et ils se prosternèrent; puis Joseph s\'avança et Rachel, et ils se prosternèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Et il dit: Que te proposes-tu avec toute cette caravane que j\'ai rencontrée? Et il répondit: De trouver grâce aux yeux de mon seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Et Esaü dit: Je suis dans l\'abondance, mon frère! garde ce que tu as!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Et Jacob dit: Mais non! si j\'ai pu trouver grâce à tes yeux, tu accepteras mon présent de ma main; c\'est pourquoi j\'ai regardé ta face comme on regarde la face de Dieu, et tu m\'as fait un gracieux accueil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Accepte donc mon présent qui t\'a été offert; car Dieu m\'a été propice et le tout m\'appartient. Et il le pressa, et il accepta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Et Esaü dit: Partons et mettons-nous en route, et je te précéderai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Et Jacob dit: Mon seigneur sait que les enfants sont délicats et que j\'ai des brebis et des vaches qui allaitent; et si on leur faisait hâter le pas un seul jour, tout le troupeau périrait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Que mon seigneur prenne l\'avance sur son serviteur, et moi je pourrai cheminer à mon aise en suivant le pas des troupeaux qui me précéderont, et le pas des enfants jusqu\'à ce que j\'arrive chez mon seigneur à Seïr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Et Esaü dit: Je te laisserai une escorte des gens qui sont avec moi. Et il répondit: Pourquoi donc? que je trouve seulement grâce aux yeux de mon seigneur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Et ce jour-là Esaü prit son chemin vers Séïr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Jacob de son côté se transporta à Succoth et il bâtit une maison pour lui, et pour ses troupeaux il fit des huttes; c\'est pourquoi on appelle ce lieu du nom de Succoth (huttes).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Et Jacob arriva sain et sauf à la ville de Sichem située dans le pays de Canaan, lors de son retour de Mésopotamie, et il campa devant la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Et il acheta la portion de terrain où il avait dressé sa tente, des fils de Hémor, père de Sichem, pour le prix de cent kesitas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Et là il érigea un autel qu\'il nomma [Autel] de Dieu, du Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Et Dina, fille de Léa de qui elle était née à Jacob, sortit pour visiter les filles du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Et elle fut aperçue de Sichem, fils de Hémor, le Hévite, prince du pays, qui l\'enleva et coucha avec elle et la déshonora.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Et son cœur était épris de Dina, fille de Jacob, et il aimait la jeune fille, et lui parlait à toucher son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Et Sichem s\'adressa à Hémor, son père, et dit: Procure-moi cette jeune fille pour femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Et Jacob apprit qu\'il avait déshonoré Dina, sa fille; or ses fils étaient aux champs avec ses troupeaux, et Jacob se tut jusqu\'à leur retour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Alors Hémor, père de Sichem, se rendit chez Jacob pour lui parler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Et aussitôt informés, les fils de Jacob revinrent des champs; et ces hommes furent chagrinés et fort irrités de ce qu\'il eût commis en Israël une infamie en couchant avec la fille de Jacob, ce qui ne devait pas se faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Alors Hémor leur parla en ces termes: Le cœur de Sichem, mon fils, s\'est attaché à votre fille: accordez-la-lui pour femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Et alliez-vous avec nous, donnez-nous vos filles et épousez les nôtres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'et demeurez avec nous; le pays vous étant ouvert, fixez-vous-y, et y faites vos affaires et y devenez propriétaires!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Et Sichem dit au père et aux frères de Dina: Que je trouve grâce à vos yeux, et ce que vous me direz je le donnerai:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'imposez-moi fortement pour la dot et le présent nuptial, et je paierai ainsi que vous fixerez; mais accordez-moi la jeune fille pour femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Alors les fils de Jacob dans leur réponse à Sichem et à Hémor, son père, usèrent de supercherie, ainsi que dans leurs discours, parce qu\'il avait déshonoré Dina leur sœur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'et leur dirent: Nous ne saurions faire ceci que de donner notre sœur à un incirconcis, car ce serait un opprobre pour nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Nous ne consentirons à votre demande que sous une condition, c\'est que vous vous assimiliez à nous en circoncisant tous vos mâles:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'pour lors nous vous donnerons nos filles, nous prendrons vos filles et nous demeurerons avec vous et formerons un seul peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Que si vous refusez de nous écouter et de vous faire circoncire, nous prendrons notre fille et nous en irons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Et ces propositions agréèrent à Hémor et à Sichem, fils de Hémor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Et le jeune homme ne balança pas à s\'exécuter parce qu\'il avait de l\'inclination pour la fille de Jacob; et il était plus honoré que personne dans la maison de son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Alors Hémor et Sichem, son fils, se rendirent à la porte de leur ville et parlèrent aux hommes de leur ville en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Ces hommes se montrent bien en tout avec nous; il faut donc les laisser habiter le pays et y faire leurs affaires, et voici, le pays, vaste dans les deux sens, leur est ouvert, nous prendrons leurs filles pour femmes et nous sa leur marierons nos filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Mais ces hommes ne consentiront à demeurer avec nous pour former un seul peuple qu\'autant que tous nos mâles seront circoncis, comme ils sont eux-mêmes circoncis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Leurs troupeaux et leurs biens et tout leur bétail ne seront-ils pas à nous? Seulement acceptons leur condition, afin qu\'ils restent chez nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Et tous ceux qui parurent à la porte de la ville écoutèrent Hémor et Sichem, son fils, et se firent circoncire, tous les mâles qui parurent à la porte de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Et le troisième jour, comme ils ressentaient les douleurs, les deux fils de Jacob, Siméon et Lévi, frères de Dina, prirent chacun son épée et attaquèrent la ville en sécurité et égorgèrent tous les mâles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'et ils passèrent aussi au fil de l\'épée Hémor et Sichem, son fils, et retirèrent Dina de la maison de Sichem et partirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Cependant les fils de Jacob se jetèrent sur les blessés et pillèrent la ville à cause du déshonneur fait à leur sœur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'et ils enlevèrent le gros et le menu bétail, et leurs ânes et ce qui était dans la ville, et ce qui était dans les champs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'et ils emmenèrent comme butin toutes leurs richesses et tous leurs enfants et leurs femmes, et pillèrent tout ce qui était dans les maisons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Alors Jacob dit à Siméon et à Lévi: Vous me perdez en me mettant en mauvaise odeur auprès des habitants du pays des Cananéens et des Phériziens. Or je ne forme qu\'une poignée d\'hommes, et ils se ligueront contre moi, et ils me mettront en déroute, et je serai exterminé moi et ma maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Et ils dirent: Fallait-il traiter notre sœur comme une prostituée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Et Dieu dit à Jacob: Lève-toi, monte à Béthel et y demeure et fais-y un autel au Dieu qui t\'est apparu quand tu fuyais devant Esaü, ton frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Alors Jacob dit à sa maison a et à tous ceux qui étaient avec lui: Éloignez les dieux étrangers qui sont parmi vous, et purifiez-vous et changez vos habits,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'puis nous partirons et monterons à Béthel, et là je ferai un autel au Dieu qui m\'a exaucé au jour de ma détresse et a été avec moi durant le voyage que j\'ai accompli.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Alors ils livrèrent à Jacob tous les dieux étrangers qu\'ils retenaient, et les boucles qui étaient à leurs oreilles, et Jacob les enfouit sous le chêne qui se trouvait près de Sichem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Et ils se mirent en marche. Et la terreur de Dieu gagna toutes les villes de leurs alentours, tellement qu\'on ne poursuivit point les fils de Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Et Jacob parvint à Luz, situé dans le pays de Canaan (c\'est Béthel) lui et tout le monde qui était avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Et là il édifia un autel et donna à l\'endroit le nom de [Autel] du Dieu de Béthel, parce que c\'était là que Dieu s\'était révélé à lui, quand il fuyait devant son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Et alors mourut Debora, nourrice de Rebecca, et elle reçut la sépulture au-dessous de Béthel sous le chêne, auquel il donna le nom de Allon-Bachuth (chêne des pleurs).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Et Dieu apparut encore à Jacob après son retour de Mésopotamie, et le bénit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Et Dieu lui dit: Ton nom est Jacob; désormais ton nom ne sera plus Jacob, mais Israël sera ton nom. Et Il lui donna le nom d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Et Dieu lui dit: Je suis Dieu, le Tout-Puissant. Sois fécond et te multiplie; un peuple et une masse de peuples naîtront de toi et des rois sortiront de tes reins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Et le pays que j\'ai donné à Abraham et à Isaac, je veux te le donner et le donner à ta postérité après toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Et Dieu remontant le quitta au lieu où Il avait parlé avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Alors Jacob érigea un monument dans le lieu où Il avait parlé avec lui, un monument en pierre et y fit une libation et y versa de l\'huile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Et Jacob donna au lieu où Dieu avait parlé avec lui le nom de Beth-El (maison de Dieu).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Et ils partirent de Béthel. Et on avait encore à franchir une traite jusqu\'à Ephrata, lorsque Rachel enfanta, et elle eut un enfantement laborieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Et comme l\'enfantement était laborieux, la sage-femme lui dit: Ne t\'alarme pas, car c\'est encore un fils qui te vient!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Et lorsque rendant l\'âme, elle se mourait, elle nomma son nom Ben-Oni (mon fils de douleur); mais son père l\'appela Benjamin (fils de la droite).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Ainsi mourut Rachel, et elle reçut la sépulture sur le chemin d\'Ephrata, qui est Bethléhem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Et Jacob érigea un cippe sur son tombeau, c\'est le cippe de Rachel qu\'on voit encore aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Et Israël partit et dressa sa tente au-delà de la Tour-aux-Troupeaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Et pendant qu\'Israël habitait cette contrée, Ruben prit son chemin, et coucha avec Bilha, concubine de son père. El Israël l\'apprit. Et les fils de Jacob étaient au nombre de douze.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Fils de Léa: le premier-né de Jacob, Ruben, et Siméon et Lévi, et Juda et Issaschar et Zabulon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Fils de Rachel: Joseph et Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Fils de Bilha, servante de Rachel: Dan et Nephthali.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Fils de Zilpa, servante de Léa: Gad et Asser. Tels sont les fils de Jacob, qui lui naquirent en Mésopotamie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Et Jacob arriva chez Isaac, son père, à Mamré, Kiriath-Arba, qui est Hébron, où Abraham et Isaac avaient séjourné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Et les jours d\'Isaac furent cent quatre-vingts ans;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'alors Isaac expira et mourut, et il fut recueilli auprès de son peuple, vieux et rassasié de jours. Et Esaü et Jacob, ses fils, lui donnèrent la sépulture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Et c\'est ici l\'histoire d\'Esaü, qui est Edom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esaü prit ses femmes parmi les filles de Canaan: Ada, fille d\'Elon, le Héthicn, et Oholibama, fille d\'Ana, fille de Tsibéon, le Hévite, et');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'Bosmath, fille d\'Ismaël, sœur de Nebaioth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Et Ada enfanta à Esaü Eliphaz, et Bosmath enfanta Reguel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Et Oholibama enfanta Jeüs et Jaelam et Corah. Tels sont les fils d\'Esaü, qui lui naquirent dans le pays de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Et Esaü prit ses femmes et ses fils et ses filles et toutes les personnes de sa maison, et ses troupeaux et tout son bétail et tout son bien qu\'il avait acquis au pays de Canaan, et se transporta dans un [autre] pays à distance de Jacob, son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Car leurs biens étaient trop considérables pour qu\'ils restassent ensemble, et le pays de leur séjour ne suffisait pas pour les contenir à cause de leurs troupeaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Et Esaü s\'était établi dans la montagne de Séïr. Esaü est Edom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Et c\'est ici l\'histoire d\'Esaü, père des Edomites dans la montagne de Séïr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Voici les noms des fils d\'Esaü: Eliphaz, fils d\'Ada, femme d\'Esaü, Reguel, fils de Bosmath, femme d\'Esaü.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Et les fils d\'Eliphaz furent: Therman, Omar, Tsepho, et Gaetham et Kenaz.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Et Thimna était la concubine d\'Eliphaz, fils d\'Esaü, et elle enfanta Amalek à Eliphaz. Tels sont les fils d\'Ada, femme d\'Esaü.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Et voici les fils de Reguel: Nahath et Zerah, Samma et Mizza. Tels furent les fils de Bosmath, femme d\'Esaü.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Et voici les fils d\'Oholibama, fille d\'Ana, fille de Tsibéon, femme d\'Esaü: elle enfanta à Esaü Jehus et Jaelam et Corah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Voici les chefs des fils d\'Esaü: des fils d\'Eliphaz, premier-né d\'Esaü: le chef de Theiman, le chef d\'Omar, le chef de Tsepho,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'le chef de Kenaz, le chef de Corah, le chef de Gaetham, le chef d\'Amalek. Tels sont les chefs d\'Eliphaz au pays d\'Edom, tels les fils de Ada.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Et voici les fils de Reguel, fils d\'Esaü: le chef de Nahath, le chef de Zerah, le chef de Samma, le chef de Mizza. Tels sont les chefs de Reguel au pays d\'Edom, tels les fils de Bosmath, femme d\'Esaü.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Et voici les fils d\'Oholibama, femme d\'Esaü: le chef de Jehus, le chef de Jaelam, le chef de Corah. Tels sont les fils d\'Oholibama, fille de Ana, femme d\'Esaü.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Tels sont les fils d\'Esaü, tels leurs chefs; il est le même que Edom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Voici les fils de Séir, le Horite, habitants du pays: Lotan et Sobal et Tsibéon, et Ana');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'et Dison et Etser et Disan. Tels sont les chefs des Horites, des fils de Séir au pays d\'Edom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Et les fils de Lotan furent: Hori et Heimam, et la sœur de Lotan était Thimna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Et voici les fils de Sobal: Alvan et Manahath, et Eibal, Sepho et Onam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Et voici les fils de Tsibéon: Aja et Ana; c\'est cet Ana qui trouva les sources chaudes dans le désert en gardant les ânes de Tsibeon, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Et voici les fils d\'Ana: Dison et Oholibama, fille d\'Ana.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Et voici les fils de Dison: Hemdan et Esban et Jithran et Chran.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Voici les fils de Etser: Bilhan et Zahvan et Acan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Voici les fils de Disan: Uz et Aran.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Voici les chefs des Horites: le chef de Lotan, le chef de Sobal, le chef de Tsibéon, le chef de Ana,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'le chef de Dison, le chef de Etser, le chef de Disan. Tels sont les chefs des Horites, leurs chefs au pays de Séir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Et voici les rois qui régnèrent au pays d\'Edom, avant que des rois régnassent sur les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Et Béla, fils de Beor, régna en Edom; et le nom de sa ville était Dinaba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Et Béla mourut, et il fut remplacé comme roi par Jobab, fils de Zerah, de Botsra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Et Jobab mourut, et il fut remplacé comme roi par Husani du pays des Theimanites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Et Husam mourut et il fut remplacé comme roi par Hadad, fils de Bedad, qui défit les Madianites dans les campagnes de Moab; et le nom de sa ville était Havith.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Et Hadad mourut, et il fut remplacé comme roi par Samla de Masréca.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Et Samla mourut, et il fut remplacé comme roi par Saul, de Rechoboth sur le fleuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Et Saul mourut, et il fut remplacé comme roi par Baal-Hanan, fils de Achbor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Et Baal-Hanan, fils de Achbor, mourut, et il fut remplacé comme roi par Hadar; et le nom de sa ville était Pagu, et le nom de sa femme Mehetabeel, fille de Matred, fille de Mezaab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Et voici les noms des chefs d\'Esaü, selon leurs tribus, leurs territoires, leurs noms: le chef de Thimna, le chef de Alva, le chef de Jétheth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'le chef de Oholibama, le chef d\'Ela, le chef de Pinon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'le chef de Kenaz, le chef de Theiman, le chef de Mibtsar,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'le chef de Magdiel, le chef de Iram. Tels sont les chefs d\'Edom selon leurs territoires dans le pays de leur propriété. Tel est Esaü, père des Ëdomites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Cependant Jacob habitait la contrée où séjournait son père, le pays de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'C\'est ici l\'histoire de Jacob. Joseph avait dix-sept ans lorsqu\'il faisait avec ses frères paître les brebis; or il était comme jeune garçon auprès des fils de Bilha et des fils de Zilpa, femmes de son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Et Joseph rapportait à son père le mal qu\'on disait d\'eux. Or Israël préférait Joseph à tous ses autres fils, parce qu\'il était le fils de ses vieux jours; et il lui fit une tunique longue à manches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Et lorsque ses frères virent que le père le préférait à tous ses frères, ils le prirent en haine et ils ne pouvaient lui parler amicalement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Et Joseph eut un songe, et il le raconta à ses frères, et ils le prirent encore plus en haine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Et il leur dit: Ecoutez donc ce songe que j\'ai eu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Voici, nous étions dans le champ à lier des gerbes; et voilà que ma gerbe se dressa et resta debout; et voilà que vos gerbes entourèrent ma gerbe et s\'inclinèrent devant elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Alors ses frères lui dirent: Prétends-tu régner sur nous, et prétends-tu exercer l\'empire sur nous? Et ils le haïrent encore davantage à cause de ses songes et de ses discours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Ensuite il eut encore un autre songe: Et voici, le soleil et la lune et onze étoiles s\'inclinaient devant moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Et il le raconta à son père et à ses frères; alors son père le tança et lui dit: Qu\'est-ce que ce songe que tu as eu? Faut-il que moi et ta mère et tes frères nous venions nous prosterner contre terre devant toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Et ses frères furent jaloux de lui, mais son père garda la chose par devers lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Et ses frères partirent pour mener paître les troupeaux de leur père à Sichem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Alors Israël dit à Joseph: Tes frères ne sont-ils pas au pâturage à Sichem? Viens, je veux t\'envoyer vers eux. Et il lui répondit: Me voici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Et il lui dit: Va donc et vois dans quel état sont tes frères et les troupeaux, et rapporte-m\'en des nouvelles. Il l\'envoya ainsi de la vallée de Hébron, et il se rendit à Sichem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Et un homme le trouva errant dans la campagne; et l\'homme l\'interrogeant lui dit: Que cherches-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Et il répondit: Je suis à la recherche de mes frères: indique-moi donc le pâturage où ils sont.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Et l\'homme dit: Ils sont partis d\'ici, car j\'ai entendu qu\'ils disaient: Allons à Dothan! Alors Joseph se mit sur les traces de ses frères, et les trouva à Dothan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Et ils l\'aperçurent de loin; et avant qu\'il fût près d\'eux, ils complotèrent de le faire mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Et ils se disaient l\'un à l\'autre: Voici l\'homme aux songes, le personnage arrive!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Eh bien! allons! tuons-le, et nous le jetterons dans une de ces citernes, puis nous dirons: Une bête féroce l\'a dévoré; et nous verrons ce qu\'il en sera de ses songes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Et Ruben entendit, et il le sauva de leurs mains et dit: N\'attentons pas à sa vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Et Ruben leur dit: Ne versez point de sang, jetez-le dans cette citerne-ci au désert, mais ne portez point la main sur lui! Son but était de le sauver de leurs mains pour le rendre à son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Et lorsque Joseph fut arrivé auprès de ses frères, ils le dépouillèrent de sa tunique, de cette tunique longue qu\'il portait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'et ils le prirent et le jetèrent dans la citerne; or la citerne était vide; il n\'y avait point d\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Et ils s\'assirent pour manger le pain; alors ils levèrent les yeux et regardèrent, et voilà que c\'était une caravane d\'Ismaélites arrivant de Galaad; et leurs chameaux étaient chargés d\'aromates, de baume et de ladanum; ils étaient en route pour les transporter en Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Alors Juda dit à ses frères: A quoi bon tuer notre frère et cacher son sang?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Venez, vendons-le aux Ismaélites, et ne portons pas la main sur lui; car c\'est notre frère, notre chair. Et ses frères l\'écoutèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Et il passait des Madianites, marchands; alors ils retirèrent Joseph de la citerne et vendirent Joseph aux Ismaélites pour vingt sicles d\'argent, et ceux-ci emmenèrent Joseph en Egygte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Et lorsque Ruben revint à la citerne, voilà que Joseph n\'était plus dans la citerne! et il déchira ses vêtements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Et il rejoignit ses frères et dit: L\'enfant n\'y est plus, et moi, où irai-je?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Et ils prirent la tunique de Joseph, et ayant tué un bouc ils plongèrent la tunique dans son sang,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'et ils envoyèrent porter la tunique longue à leur père avec ces paroles: Voici ce que nous avons trouvé, reconnais si c\'est ou non la tunique de ton fils!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Et il la reconnut et dit: La tunique de mon fils! une bête féroce l\'a dévoré: Joseph déchiré, déchiré!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Et Jacob déchira ses habits, et entoura ses reins d\'un cilice, et garda longtemps le deuil de son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Et tous ses fils et toutes ses filles s\'approchèrent pour le consoler, mais il ne voulut accepter aucune consolation et dit: Je veux descendre avec mon deuil vers mon fils aux Enfers! et son père le pleurait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Cependant les Madianites le vendirent en Égypte à Potiphar eunuque de Pharaon, chef des satellites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Et il arriva dans ce temps-là que Juda alla se fixer plus bas que ses frères, et se tourna vers un homme d\'Adullam nommé Hirah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Et là Juda vit la fille d\'un Cananéen nommé Suah, et il l\'épousa, et habita avec elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Et elle devint enceinte et enfanta un fils, qu\'il appela du nom de Ger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Et elle devint encore enceinte et enfanta un fils qu\'elle appela du nom d\'Onan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Et derechef elle enfanta un fils qu\'elle appela du nom de Sélah; or Juda était à Chesib, quand elle l\'enfanta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Et Juda choisit une femme à Ger, son premier-né, et Thamar était son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Et Ger, premier-né de Juda, était méchant aux yeux de l\'Éternel, et l\'Éternel le fit mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Alors Juda dit à Onan: Approche-toi de la femme de ton frère, et remplis à son égard le devoir du beau-frère, et suscite une postérité à ton frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Mais Onan savait que cette postérité ne serait pas pour lui; et lorsqu\'il s\'approchait de la femme de son frère, il polluait le sol, afin de ne pas donner de postérité à son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Et le procédé d\'Onan déplut à l\'Éternel qui le fit aussi mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Alors Juda dit à Thamar, sa bru: Demeure veuve dans la maison de ton père, jusqu\'à ce que Sélah, mon fils, soit adulte. Car il pensait empêcher que celui-ci ne mourût comme ses frères. Thamar s\'en alla donc, et elle demeura dans la maison de son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Et il se passa longtemps, et la fille de Suah, femme de Juda, mourut; et lorsque Juda fut consolé, il monta à Thimna vers les tondeurs de ses brebis, lui et Hirah d\'Adullam, son ami.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Et avis en fut donné à Thamar en ces termes: Voilà que ton beau-père monte à Thimna pour la tonte de ses brebis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Alors elle ôta ses habits de veuve, et se couvrit du voile, et ainsi enveloppée elle s\'assit à la porte d\'Enaïm qui est sur la route de Thimna. Car elle voyait que Sélah était adulte et qu\'on ne la mariait point avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Et Juda la vit et la prit pour une prostituée, parce qu\'elle avait caché son visage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Et tirant de côté il l\'accosta sur le chemin et lui dit: Allons! livre-toi, je veux m\'approcher de toi. Car il ignorait que ce fût sa bru.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Et elle dit: Que me donneras-tu pour ton approche? Et il dit: Je t\'enverrai un chevreau de mon troupeau. Et elle dit: A condition que tu me donnes un gage en attendant ton envoi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Et il dit: Quel gage me faut-il te donner? Et elle dit: Ton sceau et ton cordon et le bâton que tu as à la main. Alors il lui remit ces objets, et il s\'approcha d\'elle, et elle devint enceinte de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Alors elle se leva et s\'en alla, et ôta son voile et reprit son costume de veuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Et Juda envoya le chevreau par son ami d\'Adullam, afin de retirer le gage des mains de la femme; mais il ne la trouva point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Et il interrogea les gens du lieu où elle était, disant: Où est cette courtisane qui était à Enaïm sur la route? Et ils répondirent: Il n\'y a pas eu ici de courtisane.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Et il retourna auprès de Juda et dit: Je ne l\'ai point trouvée et même les gens du lieu m\'ont dit: Il n\'y a pas eu ici de courtisane.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Alors Juda dit: Qu\'elle garde! craignons de nous faire honnir. Ah bah! j\'ai envoyé ce chevreau; et tu ne l\'as pas trouvée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Et il arriva environ trois mois après que Juda reçut cet avis: Thamar, ta bru, s\'est prostituée, et même la voilà enceinte ensuite de sa prostitution. Alors Juda dit: Amenez-la dehors et qu\'elle soit brûlée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Comme on l\'amenait, elle dépêcha auprès de son beau-père en lui faisant dire: C\'est de l\'homme auquel sont ces objets que je suis enceinte; et ajoutant: Reconnais donc à qui est ce sceau, ce cordon et ce bâton!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Alors Juda les reconnut, et dit: Elle est plus innocente que moi, parce que je ne l\'ai pas donnée à mon fils Sélah. Et dès lors il ne la connut plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Et à l\'époque où elle devait accoucher, voici, elle portait deux jumeaux dans son sein.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Et pendant l\'enfantement l\'un des deux présenta la main, et la sage-femme la prit et y attacha un fil de pourpre en disant: Celui-ci a paru le premier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Et celui-ci ayant retiré sa main, son frère parut, et elle dit: Comme tu t\'es ouvert la brèche! Et on l\'appela du nom de Pérets (ouverture de brèche).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Et ensuite parut son frère qui avait à la main le fil de pourpre, et on l\'appela du nom de Zérah (point du jour).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Cependant Joseph fut emmené en Égypte, et Potiphar, eunuque de Pharaon, chef des satellites, Egyptien, l\'acheta des Ismaélites qui l\'avaient amené.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Et l\'Éternel fut avec Joseph, et il fut un homme qui réussit étant dans la maison de son maître, l\'Egyptien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Et son maître voyant que l\'Éternel était avec lui et faisait réussir entre ses mains tout ce qu\'il entreprenait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Joseph trouva grâce à ses yeux, et fut à son service personnel, et son maître le fit intendant de sa maison et lui remit en main tout ce qu\'il avait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Et dès qu\'il lui eut confié l\'intendance de sa maison et de tout ce qu\'il avait, l\'Éternel bénit la maison de l\'Egyptien pour l\'amour de Joseph, et il y eut bénédiction de l\'Éternel sur tout ce qui lui appartenait au dedans et au dehors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Et il abandonna à Joseph le maniement de tout ce qu\'il avait, et avec lui, il ne prenait plus souci de rien, sinon des aliments dont il se nourrissait. Or Joseph avait une belle taille et une belle figure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Et sur ces entrefaites il advint que la femme de son maître porta ses regards sur Joseph, et lui dit: Couche avec moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Et il s\'y refusa et dit à la femme de son maître: Voici, mon maître ne revoit après moi quoi que ce soit dans la maison, et il m\'a donné le maniement de tout ce qu\'il a;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'il n\'a pas dans cette maison une plus haute position que moi, et il ne me tient à distance de rien, que de toi, parce que tu es sa femme: comment donc pour-rais-je commettre ce grand crime et pécher contre Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Et quoiqu\'elle parlât à Joseph tous les jours, il ne voulait point l\'écouter, pour coucher auprès d\'elle et avoir commerce avec elle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'et il lui arriva dans ce temps, d\'entrer dans la maison pour vaquer à son occupation, dans un moment où aucun des gens de la maison n\'était au logis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'alors elle le saisit par son vêtement en disant: Couche avec moi! Et il laissa son vêtement dans sa main, et s\'enfuit et courut dehors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Et quand elle vit qu\'il lui avait laissé son vêtement dans la main, et s\'était enfui dehors,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'elle appela les gens de sa maison et leur dit: Voyez, il nous a amené un homme hébreu pour se jouer de nous. Il est entré chez moi pour coucher avec moi; alors j\'ai appelé à haute voix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'et quand il m\'a entendu élever la voix et appeler, il a laissé son vêtement à mes côtés et s\'est enfui et a couru dehors;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'et elle posa le vêtement à côté d\'elle en attendant le retour de son seigneur au logis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Et elle lui parla dans ce sens en ces termes: L\'esclave hébreu que tu nous as amené est entré chez moi pour se jouer de moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'puis quand j\'ai élevé la voix et appelé, il a laissé son vêtement à côté de moi et s\'est enfui dehors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Et à l\'ouïe des discours de sa femme qui lui avait parlé en ces termes: Ton esclave m\'a traitée de la sorte, le maître de Joseph fut enflammé de colère,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'et il le prit et le mit dans la maison de force, dans le lieu où les prisonniers du roi étaient détenus; et il fut là dans la maison de force.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Mais l\'Éternel fut avec Joseph et lui concilia de la bienveillance et lui fit trouver grâce aux yeux du commandant de la maison de force.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Et le commandant de la maison de force plaça sous l\'autorité de Joseph tous les prisonniers qui étaient dans la maison de force; et tout ce qui s\'y faisait se faisait par lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Le commandant de la maison de force ne contrôlait rien de ce qu\'il avait à manier, parce que l\'Éternel était avec lui; et l\'Éternel faisait réussir ce qu\'il entreprenait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Et il arriva après ces choses que l\'échanson du roi d\'Égypte et le panetier faillirent envers leur seigneur, le roi d\'Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Et Pharaon se courrouça contre ses deux eunuques, le grand échanson et le grand panetier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Et il les incarcéra dans la maison du chef des satellites, dans la maison de force, lieu où Joseph était détenu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Et le chef des satellites plaça Joseph auprès d\'eux, et il les servait, et ils furent quelque temps en prison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Alors ils eurent tous les deux un songe; chacun le sien, dans une seule nuit, chacun avec un sens attaché à son songe, l\'échanson et le panetier du roi d\'Égypte détenus dans la maison de force.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Et Joseph entrant chez eux le matin les regarda, et voici, ils étaient sombres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Et Joseph questionna les deux eunuques de Pharaon détenus avec lui dans la maison de son maître et leur dit: Pourquoi avez-vous un air triste aujourd\'hui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Et ils lui répondirent: Nous avons eu un songe, et il n\'y a personne pour l\'interpréter. Alors Joseph leur dit: N\'est-ce pas à Dieu qu\'appartiennent les interprétations?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Faites-m\'en donc le récit! Alors le grand échanson raconta à Joseph le songe qu\'il avait eu, et lui dit: En songeant voilà que j\'avais un cep devant moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Et le cep avait trois pampres; et après avoir jeté ses bourgeons, il épanouit ses fleurs et les grappes donnèrent des raisins mûrs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Or j\'avais dans ma main la coupe de Pharaon; alors je pris les raisins, et en exprimai le jus dans la coupe de Pharaon, et je mis la coupe dans la main de Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Alors Joseph lui dit: En voici l\'interprétation: Les trois pampres sont trois jours;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'encore trois jours et Pharaon te relèvera la tête et te rétablira dans ton poste, et tu mettras la coupe dans la main de Pharaon l\'usage de ci-devant, quand tu étais son échanson.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Mais garde par devers toi le souvenir de moi, quand tu seras en bon point, et montre-moi de la bonté, et fais mention de moi auprès de Pharaon et tire-moi de cette maison!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Car j\'ai été ravi du pays des Hébreux, et ici je n\'ai rien fait non plus pour être mis en prison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Et le grand panetier voyant qu\'il interprétait en bien, dit à Joseph: Dans le songe que j\'ai fait, voici, j\'avais trois corbeilles de pain blanc sur la tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Et la corbeille supérieure contenait de tous les aliments préparés pour Pharaon en boulangerie, et les oiseaux les mangeaient dans la corbeille que je portais sur la tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Alors Joseph répondit et dit: En voici l\'interprétation: les trois corbeilles sont trois jours;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'encore trois jours et Pharaon t\'élèvera la tête, et te pendra à un arbre, et les oiseaux mangeront ta chair sur toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Et le troisième jour, jour de naissance de Pharaon, il se fit un festin à tous ses serviteurs, et il éleva la tête du grand échanson et la tête du grand panetier parmi ses serviteurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'en rétablissant le grand échanson dans son office d\'échanson, pour qu\'il mît la coupe dans la main de Pharaon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'et en faisant pendre le grand panetier, conformément à l\'interprétation que Joseph leur avait donnée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Mais le grand échanson ne pensa point à Joseph qu\'il oublia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Et au bout de deux ans Pharaon eut un songe, et voici, il se tenait près du Nil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Et voilà que du Nil surgirent sept vaches de belle apparence et au corps bien nourri, et elles se mirent à brouter parmi les roseaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'et voilà que sept autres vaches surgirent après elles du fleuve, de chétive apparence et au corps maigre, et elles se mirent à côté des vaches qui étaient sur la rive du fleuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Et les vaches de chétive apparence et au corps maigre mangèrent les sept vaches de belle apparence et bien nourries. Puis Pharaon s\'éveilla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Et il se rendormit et fit un deuxième songe, et voici, sept épis croissaient sur une seule tige, bien fournis et beaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Et voilà que sept épis maigres et brûlés par le vent d\'Est poussèrent après les premiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Et les épis maigres engloutirent les épis bien fournis et pleins. Puis Pharaon se réveilla, et voilà que c\'était un songe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Et le matin son esprit était agité, et il fit mander tous les hiérogrammates de l\'Égypte et tous ses sages, et Pharaon leur raconta le songe qu\'il avait eu; mais aucun d\'eux ne sut lui en donner l\'interprétation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Alors le grand échanson s\'adressa à Pharaon en ces termes: Je me rappelle aujourd\'hui mes manquements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Pharaon s\'était courroucé contre ses serviteurs, et m\'avait incarcéré dans la maison du chef des satellites, moi et le grand panetier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Et dans une même nuit nous eûmes l\'un et l\'autre un songe, et le songe que chacun de nous avait, était en rapport avec sa signification.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Et il y avait là avec nous un jeune Hébreu, esclave du chef des satellites, et nous lui racontâmes et il nous interpréta nos songes; il nous donna à chacun une interprétation en rapport avec le songe qu\'il avait eu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Et il est arrivé que l\'événement a correspondu à l\'interprétation qu\'il nous avait donnée: Pharaon me rétablit dans mon office et fit pendre le grand panetier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Alors Pharaon fit mander Joseph, qu\'on se hâta de tirer de la prison; et il se rasa et changea d\'habits et il se présenta devant Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Et Pharaon dit à Joseph: J\'ai fait un songe, et il n\'y a personne pour l\'interpréter; et j\'ai appris qu\'ayant entendu]e récit d\'un songe tu l\'interprètes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Alors Joseph répondit à Pharaon et dit: Je n\'y suis pour rien. C\'est Dieu qui donnera une réponse favorable à Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Et Pharaon dit à Joseph: Pendant que je songeais, voici, je me tenais sur le bord du Nil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Et voilà que du fleuve surgirent sept vaches au corps bien nourri et de belle apparence, et elles se mirent à brouter parmi les roseaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Et voilà que sept autres vaches surgirent après elles, d\'une très chétive et très grêle apparence et au corps maigre; je n\'en avais jamais vu de si chétives dans tout le pays d\'Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Et les vaches maigres et chétives mangèrent les sept premières qui étaient bien nourries;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'et celles-ci passèrent dans leur panse, et l\'on ne pouvait se douter qu\'elles eussent passé dans leur panse; et leur apparence était aussi chétive qu\'auparavant. Alors je m\'éveillai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Et pendant le songe je regardais, et voici, sept épis croissaient sur une seule tige, pleins et beaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Et voilà que sept épis stériles, maigres, brûlés par le vent d\'Est poussèrent après les premiers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'et les épis maigres engloutirent les sept beaux épis. Et c\'est ce que j\'ai raconté aux hiérogrammates, mais aucun n\'a pu me donner d\'explication.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Alors Joseph dit à Pharaon: C\'est un songe unique qu\'a eu Pharaon; Dieu a indiqué à Pharaon ce qu\'il veut faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Les sept belles vaches sont sept années, et les sept beaux épis sont sept années; c\'est un seul songe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Et les sept vaches maigres et hideuses qui surgirent après les premières sont sept années, et les sept épis vides, brûlés par le vent d\'Est, seront sept années de famine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'C\'est le sens de ce que j\'ai dit à Pharaon en ces termes: Dieu a montré à Pharaon ce qu\'il veut faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Voici, sept années viennent de grande abondance pour tout le pays d\'Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Et elles seront suivies de sept années de famine, qui feront oublier toute abondance au pays d\'Égypte, et la famine consumera le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Et l\'on ne saura plus ce que c\'est que l\'abondance dans le pays en face de cette famine-là qui suivra, car elle sera très intense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Que si Pharaon a vu le songe se répéter deux fois, c\'est que la chose est arrêtée par devers Dieu et que Dieu va se hâter de la mettre à exécution.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Maintenant donc, que Pharaon voie à se trouver un homme entendu et sage et qu\'il le prépose sur le pays d\'Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Il s\'agit pour Pharaon d\'établir des inspecteurs sur le pays et de prélever un cinquième dans le pays d\'Égypte, pendant les sept années d\'abondance. Et qu\'ils recueillent toutes les subsistances de ces bonnes années qui viennent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'et que, sous la main de Pharaon, ils amassent du blé dans les villes pour la subsistance, et le mettent en réserve,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'afin que ces denrées soient une ressource pour le pays dans les sept années de famine qu\'il y aura dans le pays d\'Égypte, afin que le pays ne succombe pas à la famine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Et ce discours agréa à Pharaon et à tous ses serviteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Et Pharaon dit à ses serviteurs: Pourrions-nous trouver un homme tel que celui-ci, ayant en lui l\'esprit de Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Et Pharaon dit à Joseph: Puisque Dieu t\'a donné la connaissance de tout cela, nul n\'est entendu et sage comme toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'C\'est toi qui seras préposé sur ma maison, et tout mon peuple se conformera aux paroles de ta bouche, ce n\'est que par le trône que je serai supérieur à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Et Pharaon dit à Joseph: Voici, je te prépose sur tout le pays d\'Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Et Pharaon ôta son anneau de son doigt et le mit au doigt de Joseph, et il le revêtit d\'habits de lin et lui passa une chaîne d\'or au col.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Et il le fit monter sur le second de ses chars, et l\'on criait devant lui: Inclinez-vous! car il l\'a préposé sur tout le pays d\'Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Et Pharaon dit à Joseph: Je suis Pharaon! et sans ton ordre nul ne lèvera la main ni le pied dans tout le pays d\'Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Et Pharaon appela Joseph du nom de Tsaphnath-Phaheneach (sauveur du monde) et lui donna pour femme Asnath, fille de Potiphar, prêtre de On. Et Joseph inspecta le pays d\'Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Or Joseph avait l\'âge de trente ans lorsqu\'il parut devant Pharaon, roi d\'Égypte. Et Joseph se retira de devant Pharaon, et fit la tournée de tout le pays d\'Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Et pendant les sept années d\'abondance la terre produisit à foison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Alors il recueillit toutes les denrées des sept bonnes années qu\'il y eut au pays d\'Égypte, et déposa les denrées dans les villes, mettant dans chaque ville les denrées du territoire qui l\'entourait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Et Joseph amassa le blé, comme le sable de la mer, en quantité immense, jusqu\'à ce qu\'on dut cesser de compter, car c\'était incalculable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Cependant avant qu\'arrivât l\'année de la famine, il naquit à Joseph deux fils que lui enfanta Asnath, fille de Potiphar, prêtre de On.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Et Joseph appela le premier-né du nom de Manassé: « car Dieu m\'a fait oublier toute ma peine, et toute la maison de mon père. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Et il appela le second du nom de Ephraïm: « car Dieu m\'a rendu fécond dans le pays de ma tribulation. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Et les sept années d\'abondance qu\'il y eut au pays d\'Egypte s\'écoulèrent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'puis commencèrent à venir les sept années de famine, ainsi que Joseph l\'avait annoncé, et il y avait famine dans toutes les contrées, mais dans tout le pays d\'Égypte il y avait du pain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Et quand tout le pays fut affamé et que le peuple éleva ses cris vers Pharaon pour avoir du pain, Pharaon dit à tous les Egyptiens: Allez à Joseph! faites ce qu\'il vous dira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Et la famine régnait sur toute la face de la terre, et Joseph ouvrit tous les lieux où il y avait du blé, et en vendit aux Egyptiens, et la famine était forte dans le pays d\'Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Et tous les pays arrivaient en Égypte pour acheter du blé auprès de Joseph, car la famine était forte dans tous les pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Et lorsque Jacob vit qu\'il y avait du blé en Égypte, il dit à ses fils: Pourquoi vous entre-regardez-vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Et il dit: Voici, j\'ai appris qu\'il y a du blé en Égypte: descendez-y et y faites des achats pour nous, afin que nous vivions et ne mourions pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Alors les dix frères de Joseph descendirent en Égypte pour y acheter du blé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Mais quant à Benjamin, frère de Joseph, Jacob ne l\'envoya point avec ses frères, car il disait: Je ne veux pas que malheur lui arrive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Les fils d\'Israël vinrent donc pour acheter du blé, parmi ceux qui venaient d\'ailleurs; car la famine était dans le pays de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Or Joseph avait le pouvoir dans le pays; c\'est lui qui vendait du blé à tout le peuple du pays. Et les frères de Joseph vinrent, et ils s\'inclinèrent devant lui la face contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Et à la vue de ses frères, Joseph les reconnut, mais il ne se fit pas connaître à eux, et il prit avec eux un langage dur et leur dit: D\'où venez-vous? Et ils répondirent: Du pays de Canaan pour acheter des subsistances.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Et Joseph reconnaissait ses frères, mais eux ne le reconnaissaient pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Et Joseph se rappela les songes qu\'il avait faits sur eux, et il leur dit: Vous êtes des espions; c\'est pour observer les endroits faibles du pays que vous êtes venus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Et ils lui répondirent: Non, monseigneur, et tes serviteurs sont venus pour acheter des subsistances.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Tous nous sommes fils d\'un seul homme; nous sommes honnêtes; tes serviteurs ne sont point des espions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Et il leur dit: Non, car vous êtes venus pour observer les endroits faibles du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Et ils répondirent: Nous, tes serviteurs, sommes douze frères, fils d\'un seul homme au pays de Canaan; et voici, le cadet est maintenant auprès de notre père, et l\'un n\'est plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Et Joseph leur dit: C\'est ce que je vous disais: Vous êtes des espions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Voici l\'épreuve que vous subirez: par la vie de Pharaon! vous ne sortirez pas d\'ici que votre frère cadet n\'y vienne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Envoyez l\'un de vous chercher votre frère; quant à vous, restez prisonniers, pour montrer par cette épreuve s\'il y a chez vous vérité ou non. Par la vie de Pharaon! vous êtes des espions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Et il les mit ensemble en prison pendant trois jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Et le troisième jour Joseph leur dit: Faites ceci et vous vivrez; je crains Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Si vous êtes honnêtes, que l\'un de vos frères reste prisonnier dans le lieu de votre détention, et vous, partez pour porter les subsistances nécessaires à vos maisons,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'et ramenez-moi votre frère cadet; ainsi, vos discours seront vérifiés, et vous ne mourrez pas. Et c\'est ce qu\'ils firent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Alors ils se dirent l\'un à l\'autre: Certainement nous fûmes coupables envers notre frère, lorsque témoins de l\'angoisse de son âme nous ne voulûmes point l\'écouter quand il nous suppliait; c\'est pour cela que cette détresse nous est survenue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Et Ruben leur répondit en disant: Ne vous ai-je pas dit: Ne commettez pas un péché sur cet enfant? mais vous n\'avez pas écouté; et son sang, voici, il est redemandé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Or ils ne se doutaient pas que Joseph comprenait; car ils communiquaient par un interprète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Alors Joseph se tira à l\'écart et pleura. Et revenant auprès d\'eux il leur parla, et choisit parmi eux Siméon, qu\'il lia sous leurs yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Et Joseph fit remplir leurs sacs de blé, et remettre leur argent, à chacun dans son sac, et leur fit donner des vivres pour la route. Et c\'est ce qui fut fait pour eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Et ils chargèrent leur denrée sur leurs ânes, et partirent de là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Et l\'un d\'eux ouvrit son sac pour donner du fourrage à son âne, dans le caravansérail, et il vit son argent, et voilà qu\'il était à l\'ouverture de son sac!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Et il dit à ses frères: Mon argent a été rendu, et le voici dans mon sac! Alors le cœur leur manqua; et se regardant l\'un l\'autre avec effroi ils disaient: Pourquoi Dieu nous a-t-il fait cela?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Cependant ils arrivèrent chez Jacob, leur père, au pays de Canaan, et ils lui racontèrent tout ce qui leur était survenu et dirent:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'L\'homme qui est le seigneur du pays nous a tenu un langage dur et nous a traités comme si nous venions épier le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Et nous lui avons dit: Nous sommes honnêtes, ne sommes point des espions;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'nous sommes douze frères, fils de notre père; l\'un n\'est plus, et le cadet est maintenant avec notre père au pays de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Alors l\'homme qui est le seigneur du pays, nous a dit: Voici ce qui me prouvera que vous êtes honnêtes: laissez chez moi l\'un de vos frères, et emportez le nécessaire de vos maisons et partez; mais ramenez-moi votre frère cadet,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'pour que j\'aie la preuve que vous n\'êtes pas des espions, que vous êtes honnêtes, puis je vous rendrai votre frère et vous pourrez faire vos affaires dans le pays. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Et lorsqu\'il vidèrent leurs sacs, voici, chacun d\'eux avait sa bourse d\'argent dans son sac; et à la vue de leur bourse d\'argent ils furent effrayés, eux et leur père. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Et Jacob, leur père, leur dit: Vous m\'ôtez mes enfants! Joseph n\'est plus et Siméon n\'est plus, et vous voulez prendre Benjamin! tout tombe sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Et Ruben dit à son père: Tu peux faire mourir mes deux fils, si je ne te le ramène pas. Remets-le entre mes mains et je te le rendrai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Et il dit: Mon fils ne descendra pas avec vous; car son frère est mort et lui seul survit, et s\'il lui arrivait malheur sur la route que vous suivrez, vous feriez descendre mes cheveux blancs douloureusement aux Enfers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Cependant la famine pesait sur le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Et lorsqu\'ils eurent entièrement consommé le blé qu\'ils avaient apporté d\'Égypte, leur père leur dit: Allez nous acheter encore quelques subsistances.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Et Juda lui répondit en disant: L\'homme nous a fait cette protestation: Vous ne serez point admis en ma présence à moins que votre frère ne soit avec vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Si tu veux laisser venir notre frère avec nous, nous irons t\'acheter des subsistances;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'mais si tu ne veux pas le laisser venir, nous n\'irons pas, car l\'homme nous a dit: Vous ne serez point admis en ma présence, à moins que votre frère ne soit avec vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Et Israël dit: Pourquoi en avez-vous si mal agi envers moi que de découvrir à cet homme, si vous aviez encore un frère?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Et ils répondirent: Il nous a questionnés sur nous et notre famille en disant: Votre père vit-il encore? avez-vous encore un frère? Et nous nous sommes expliqués aux termes de ces questions-là. Pouvions-nous nous douter qu\'il dirait: Allez chercher votre frère?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Et Juda dit à Israël, son père: Laisse l\'enfant venir avec nous, et nous nous lèverons et nous partirons, et nous vivrons et nous ne mourrons pas, ni nous, ni toi, ni nos enfants!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Je réponds de lui, tu le réclameras de ma main; si je ne te le ramène pas et ne te le représente pas, je me constitue coupable envers toi pour toute ma vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Car si nous n\'avions pas tardé, nous serions déjà revenus deux fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Alors Israël, leur père, leur dit: S\'il faut qu\'il en soit ainsi, faites ceci: Prenez dans vos valises des produits les plus vantés du pays, et portez-les à cet homme comme une offrande, un peu de baume et un peu de miel [de raisin], d\'aromates et de ladanum, de pistaches et d\'amandes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Et prenez d\'autre argent dans vos mains, et reprenez l\'argent qui a été remis à l\'entrée de vos sacs: peut-être y a-t-il eu méprise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Et prenez votre frère, et mettez-vous en marche et retournez vers cet homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Et que Dieu, le Tout-Puissant, vous fasse trouver miséricorde devant l\'homme, afin qu\'il vous relâche votre autre frère et Benjamin! Pour moi, comme j\'ai perdu mes enfants, je les perds encore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Et ces hommes prirent ce présent, et ils prirent d\'autre argent dans leurs mains, et Benjamin, et ils partirent et descendirent en Égypte, et se présentèrent devant Joseph.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Et lorsque Joseph vit Benjamin avec eux, il dit à l\'intendant de sa maison: Conduis ces hommes à la maison, et égorge des bêtes de boucherie, et apprête-les; car ces hommes mangeront avec moi à midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Et l\'intendant exécuta ce que lui disait Joseph, et conduisit ces hommes à la maison de Joseph.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Et ces hommes eurent peur quand ils se virent menés à la maison de Joseph, et ils dirent: C\'est au sujet de l\'argent qui s\'est retrouvé dans nos sacs, qu\'on nous y mène pour nous assaillir et tomber sur nous et nous prendre comme esclaves avec nos ânes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Alors ils abordèrent l\'intendant de la maison de Joseph, et lui parlèrent à la porte de la maison, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'Nous t\'en conjurons, monseigneur! Nous sommes d\'abord descendus ici pour acheter des substances.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Puis quand nous fûmes arrivés à l\'hôtellerie, et que nous eûmes ouvert nos sacs, voilà que l\'argent de chacun de nous s\'est trouvé en haut de son sac, notre argent avec tout son poids, et nous l\'avons rapporté dans nos mains;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'et nous apportons d\'autre argent pour acheter des subsistances. Nous ignorons qui a mis notre argent dans nos sacs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Et il répondit: Vous resterez sains et saufs! Soyez sans crainte! Votre Dieu et le Dieu de votre père a déposé pour vous un trésor dans vos sacs, votre argent m\'est parvenu. Et il leur amena Siméon élargi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Et l\'intendant les introduisit dans la maison de Joseph, et donna de l\'eau pour baigner leurs pieds, et il donna du fourrage pour leurs ânes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Et ils préparèrent le présent en attendant que Joseph vînt à midi; car ils avaient appris qu\'ils mangeraient le pain en ce lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Et Joseph étant arrivé au logis, ils lui apportèrent dans la maison le présent qu\'ils avaient entre les mains, et ils s\'inclinèrent devant lui contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Et il leur demanda de leurs nouvelles et dit: Est-il en santé votre père, ce vieillard dont vous m\'avez parlé? vit-il encore?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Et ils répondirent: Ton serviteur, notre père, est en santé, il vil encore. Et ils s\'inclinèrent et se prosternèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Alors levant les yeux il aperçut Benjamin, son frère, fils de sa mère, et dit: Est-ce là votre frère cadet dont vous m\'avez parlé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Et il dit: Que Dieu te soit propice, mon fils! Et Joseph avait hâte, car son cœur s\'embrasait pour son frère et il cherchait où pleurer, et il entra dans l\'intérieur, et il pleura.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Puis s\'étant lavé le visage, il sortit, et il se contenait et dit: Servez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Et on le servit à part, et eux à part, et les Égyptiens qui mangeaient avec lui, à part; car les Egyptiens n\'osent pas manger le pain avec les Hébreux, parce que c\'est une abomination pour les Egyptiens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Et ils se trouvaient assis devant lui, le premier-né selon son rang de primogéniture, et le cadet à son rang de cadet; et ces hommes s\'entre-regardaient stupéfaits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Et Joseph leur faisait porter des portions des mets qui lui étaient servis, et la portion de Benjamin était cinq fois plus grande que les portions d\'eux tous. Et ils burent, et firent gaie chère avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Et Joseph donna cet ordre à l\'intendant de sa maison: Remplis les sacs de ces hommes de denrées, autant qu\'ils en pourront emporter, et mets l\'argent de chacun à l\'entrée de son sac,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'et ma coupe, la coupe d\'argent, mets-la à l\'entrée du sac du plus jeune ainsi que l\'argent payé pour son blé. Et il exécuta l\'ordre de Joseph tel qu\'il le lui avait donné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'A l\'aube du matin ces hommes furent congédiés, eux et leurs ânes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Ils étaient sortis de la ville et n\'étaient pas loin, quand Joseph dit à l\'intendant de sa maison: Lève-toi, poursuis ces gens, et les ayant atteints dis-leur: Pourquoi avez-vous rendu le mal pour le bien?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'N\'est-ce pas ce dont mon seigneur se sert pour boire et pour tirer des présages? Ce que vous avez fait est mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Et il les atteignit et il leur tint ce langage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Et ils lui répondirent: Pourquoi? monseigneur tient-il ce langage? Il serait odieux pour tes serviteurs d\'avoir agi de la sorte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Voici, l\'argent que nous avions trouvé à l\'entrée de nos sacs, nous te l\'avons rapporté du pays de Canaan; comment donc aurions-nous dérobé dans la maison de ton maître argent ou or?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Qu\'il meure celui de tes serviteurs sur lequel l\'objet se trouvera; et nous, nous serons les esclaves de notre seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Et il dit: Eh bien! soit comme vous le dites: celui sur qui l\'objet se trouvera, sera mon esclave, et vous, vous serez quittes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Alors ils se hâtèrent de décharger leurs sacs à terre, et chacun ouvrit son sac.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Et il fouilla commençant par l\'aîné, et finissant par le cadet, et la coupe se trouva dans le sac de Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Alors ils déchirèrent leurs vêtements, et ils rechargèrent chacun son âne et regagnèrent la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Et Juda avec ses frères se rendit à la maison de Joseph, qui y était encore; et ils tombèrent devant lui la face contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Alors Joseph leur dit: Quelle est l\'action que vous avez faite? Ne saviez-vous pas qu\'un homme tel que moi, sait deviner?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Et Juda dit: Que dirons-nous à notre seigneur? quel langage employer, et comment nous justifier? Dieu a trouvé le crime de tes serviteurs: voici, nous sommes les esclaves de monseigneur, et nous et celui dans la main duquel la coupe s\'est trouvée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Et il reprit: Loin de moi la pensée d\'agir de la sorte! L\'homme dans la main duquel la coupe s\'est trouvée, sera, lui, mon esclave; mais vous, retournez en paix chez votre père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Alors Juda s\'avança vers lui et dit: Je t\'en conjure, mon seigneur! que ton serviteur puisse dire une parole aux oreilles de mon seigneur, et que ta colère ne s\'enflamme pas contre ton serviteur, car tu es l\'égal de Pharaon!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mon seigneur a adressé cette question à ses serviteurs: Avez-vous un père ou quelque frère?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Et nous répondîmes à monseigneur: Nous avons un père âgé et un cadet, enfant de sa vieillesse, et son frère étant mort, il lui est resté seul de sa mère, et son père l\'aime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Et tu dis à tes serviteurs: Amenez-le moi, afin que je le voie de mes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Et nous dîmes à monseigneur: Le jeune homme ne saurait quitter son père; s\'il quitte son père, celui-ci mourra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Et tu dis à tes serviteurs: Si votre frère cadet ne vient avec vous, vous ne serez plus admis en ma présence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Et étant retournés auprès de ton serviteur, mon père, nous lui avons rapporté les paroles de monseigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Et notre père dit: Allez nous acheter encore un peu de blé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Et nous répondîmes: Il nous est impossible d\'aller; si notre frère cadet nous accompagne, pour lors nous irons, car nous ne saurions être admis en présence de l\'homme, si notre frère cadet n\'est pas avec nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Et ton serviteur, notre père, nous dit: Vous savez que ma femme m\'a enfanté deux fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Et l\'un a été séparé de moi, et je me dis: Certainement il a été dévoré, et je ne l\'ai plus revu jusqu\'à présent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Si vous m\'enlevez encore celui-ci, et qu\'il lui arrive malheur, vous ferez descendre douloureusement mes cheveux blancs aux Enfers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Or si je reviens auprès de ton serviteur, mon père, sans avoir avec nous l\'enfant à l\'âme duquel son âme est attachée, quand il verra que l\'enfant n\'est pas avec nous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'il mourra, et tes serviteurs auront fait descendre douloureusement les cheveux blancs de ton serviteur, notre père, aux Enfers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Car ton serviteur a répondu du jeune homme à mon père: Si, lui ai-je dit, je ne te le ramène pas, je serai un coupable envers mon père toute ma vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Maintenant donc permets que ton serviteur demeure comme esclave de monseigneur à la place du jeune homme, et que le jeune homme retourne avec ses frères;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'car comment retournerais-je chez mon père sans avoir le jeune homme avec moi? Ah! fais que je n\'aie pas à être témoin du chagrin qui affligerait mon père!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Et Joseph ne pouvait plus se contenir devant tous ceux qui l\'entouraient, et il s\'écria: Faites retirer toute ma cour. Et il ne restait personne auprès de lui, lorsqu\'il se fit connaître à ses frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Alors il fit entendre sa voix mêlée de larmes, à être entendu des Egyptiens, et à être entendu de la maison de Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Et Joseph dit à ses frères Je suis Joseph! mon père vit-il encore? Et ses frères ne pouvaient lui répondre, car ils étaient consternés devant lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Joseph dit à ses frères: Approchez donc! Et ils s\'approchèrent. Et il dit: Je suis Joseph, votre frère, que vous avez vendu en Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Or ne vous chagrinez pas et ne vous irritez pas contre vous-mêmes de m\'avoir amené ici en me vendant; car c\'est dans des vues de salut que Dieu m\'a envoyé ici avant vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Car voici deux ans qu\'il y a famine dans le pays, et pendant cinq ans encore il n\'y aura ni labour ni moisson.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Or Dieu m\'a envoyé avant vous afin de vous faire survivre sur la terre et de vous conserver pour une grande délivrance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Ce n\'est donc pas vous qui m\'avez envoyé ici, mais c\'est Dieu, qui de même m\'a fait servir de père à Pharaon et m\'a établi seigneur de toute sa maison et gouverneur de tout le pays d\'Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Hâtez-vous de retourner auprès de mon père pour lui dire: Ainsi parle ton fils Joseph: Dieu m\'a établi seigneur de toute l\'Égypte descends auprès de moi, ne tarde pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Et tu habiteras le pays de Gosen, et tu seras près de moi, toi et tes fils et les fils de tes fils, et tes brebis et tes bœufs et tout ce qui tient à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Et je t\'y entretiendrai, car il y aura encore cinq années de famine, afin que tu ne t\'appauvrisses pas ni toi, ni ta maison, ni rien de ce qui tient à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Voici, vous voyez de vos yeux, et mon frère Benjamin voit de ses yeux que c\'est ma bouche qui vous parle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Et informez mon père de ma glorieuse condition en Égypte et de tout ce que vous avez vu, et hâtez-vous d\'amener mon père ici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Et il se jeta au cou de son frère Benjamin et il pleura, et Benjamin pleura à son cou.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Et il embrassa tous ses frères et pleura dans leurs bras, et ensuite ses frères s\'entretinrent avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Et le bruit en vint jusqu\'à la maison de Pharaon où l\'on disait: Les frères de Joseph sont arrivés. Et cela fut agréable à Pharaon et à ses serviteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Et Pharaon dit à Joseph: Dis à tes frères: Faites ceci: chargez vos bêtes de somme, et allez, rendez-vous au pays de Canaan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'et prenez votre père et vos maisons, et venez chez moi, et je vous donnerai ce qu\'il y a de mieux au pays d\'Égypte et vous vous nourrirez de la graisse du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Et tu es autorisé; faites ceci: prenez dans le pays d\'Égypte des chariots pour vos enfants et vos femmes, et amenez votre père et venez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'ne plaignez pas vos bagages, puisque vous aurez, tout ce qu\'il y a de mieux dans tout le pays d\'Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Et ainsi firent les fils d\'Israël, et Joseph leur fournit des chariots selon l\'ordre de Pharaon, et les fournit de vivres pour la route.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Et il leur donna à tous pour chacun d\'eux des vêtements de rechange; mais à Benjamin il donna trois cents sicles d\'argent et cinq habits de rechange.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Et à son père il envoya dix ânes chargés des meilleures denrées du pays, et dix ânesses chargées de blé et de pain et de vivres pour l\'usage de son père pendant le trajet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Puis il congédia ses frères qui partirent, et il leur dit: Ne vous irritez point entre vous pendant le voyage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Et ils quittèrent l\'Égypte et arrivèrent au pays de Canaan auprès de Jacob, leur père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Et ils lui rendirent compte en ces termes: Joseph vit encore, et, bien plus, il est gouverneur de tout le pays d\'Égypte. Mais son cœur demeurait froid, parce qu\'il ne les croyait pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Et ils lui rapportèrent toutes les paroles que Joseph leur avait dites, et il vit les chariots que Joseph avait envoyés pour le transporter; alors l\'âme de Jacob, leur père, se ranima.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Et Israël dit: C\'est assez! Joseph, mon fils, vit encore. Je veux partir et le voir avant de mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Et Israël partit avec tout ce qui lui appartenait; et arrivé à Beersébah il offrit des sacrifices au Dieu de son père Isaac.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Et Dieu parla à Israël dans une vision de la nuit et dit: Jacob! Jacob! Et il répondit. Me voici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Et Il dit: Je suis Dieu, le Dieu de ton père: ne crains pas de descendre en Égypte, car là je te ferai devenir une grande nation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Moi-même je descendrai avec toi en Égypte, et je t\'en ramènerai, et Joseph te fermera les yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Alors Jacob quitta Beersébah, et les fils d\'Israël transportèrent Jacob, leur père, et leurs enfants et leurs femmes sur les chariots que Pharaon avait envoyés pour les transporter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Et ils prirent leurs troupeaux et leurs biens acquis dans le pays de Canaan, et vinrent en Égypte, Jacob et toute sa lignée avec lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'il amena en Égypte les fils et les fils de ses fils avec lui, ses filles et les filles de ses fils et toute sa lignée avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Et voici les noms des fils d\'Israël qui vinrent en Égypte:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Jacob et ses fils: le premier-né de ses fils, Ruben. Et les fils de Ruben: Hanoch et Phallu et Hestrom et Charmi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Et les fils de Siméon: Jemuel et Jamin et Ohad et Jachin et Tsohar et Saul, fils de la Cananéenne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Et les fils de Lévi: Gerson, Kahath et Merari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Et les fils de Juda: Ger et Onan et Sélah et Pérets et Zarah; mais Ger et Onan moururent dans le pays de Canaan. Et les fils de Pérets furent: Hetsron et Hamul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Et les fils d\'Issaschar: Thola et Phuva et Job et Simron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Et les fils de Zabulon: Sered et Elon et Jahléel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Tels sont les fils de Léa, qu\'elle enfanta à Jacob en Mésopotamie, de même que Dina sa fille. Ses fils et ses filles étaient au nombre de trente-trois âmes en tout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Et les fils de Gad: Tsiphjon et Haggi, Suni et Etsbon, Eri et Arodi et Areli.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Et les fils d\'Asser: Jimna et Jisva et Jisvi et Bria, et Sérah, leur sœur. Et les fils de Bria: Héber et Malchiel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Tels sont les fils de Zilpa que Laban donna à Léa, sa fille, et elle les enfanta à Jacob, seize âmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Les fils de Rachel, femme de Jacob: Joseph et Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Et les enfants qu\'eut Joseph au pays d\'Égypte, de Asnath, fille de Potiphar, prêtre de On: Manassé et Ephraïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Et les fils de Benjamin: Bela et Becher et Asbel, Géra et Naaman, Echi et Ros, Muppim et Huppim et Ard.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Tels sont les fils de Rachel qui naquirent à Jacob, ensemble quatorze âmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Et les fils de Dan: Husim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Et les fils de Nephthali: Jatseel et Guni et Jetser et Sillem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Tels sont les fils de Bilha que Laban donna à Rachel, sa fille, et elle les enfanta à Jacob, ensemble sept âmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Le nombre total des personnes qui vinrent avec Jacob en Égypte et étaient issues de ses reins, était, sans compter les femmes des fils de Jacob, de soixante-six âmes en tout;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'et les fils de Joseph qui lui naquirent en Égypte étaient deux. Toutes les personnes de la maison de Jacob qui vinrent en Égypte formaient ensemble soixante-dix personnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Cependant il dépêcha Juda en avant vers Joseph, pour que celui-ci, avant son arrivée, dirigeât Juda sur Gosen; et ils arrivèrent dans la contrée de Gosen.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Aussitôt Joseph attela son char et s\'avança à la rencontre de son père jusqu\'à Gosen. Et quand il fut en sa présence, il se jeta à son cou et pleura longtemps sur le cou de son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Et Israël dit à Joseph: Je puis mourir maintenant, puisque j\'ai vu ton visage et que je te vois en vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Et Joseph dit à ses frères et à la maison de son père: Je vais retourner pour informer Pharaon et lui dire: Mes frères et la maison de mon père qui étaient au pays de Canaan, sont arrivés auprès de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Et ces hommes sont pasteurs, car ils s\'adonnent au soin des troupeaux, et ils ont amené avec eux leur menu et leur gros bétail, et tout ce qui est à eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'S\'il arrive donc que Pharaon vous interpelle et vous dise:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Quelle est votre occupation? vous répondrez: Tes serviteurs s\'adonnent au soin des troupeaux depuis leur jeunesse jusqu\'à maintenant, nous aussi bien que nos pères; et cela afin que vous puissiez habiter la contrée de Gosen. Car tous les pasteurs de brebis sont l\'abomination des Egyptiens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Joseph vint donc informer Pharaon et lui dit: Mon père et mes frères sont arrivés du pays de Canaan avec leur menu et leur gros bétail et tout ce qui leur appartient, et voici, ils sont dans la contrée de Gosen.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Et dans le nombre de ses frères il choisit cinq hommes et il les présenta à Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Et Pharaon dit aux frères de Joseph: Quelle est votre occupation? Et ils répondirent à Pharaon: Tes serviteurs sont pasteurs de brebis, nous aussi bien que nos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Et ils dirent à Pharaon: Nous sommes venus pour séjourner dans le pays, car il n\'y a plus de pâture pour les brebis que possèdent tes serviteurs, parce que la famine pèse sur le pays de Canaan; maintenant donc permets à tes serviteurs de s\'établir dans la contrée de Gosen.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Pharaon dit à Joseph: Ton père et tes frères sont venus te joindre:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'tu as devant toi tout le pays d\'Égypte; établis ton père et tes frères dans la meilleure partie du pays. Qu\'ils s\'établissent dans la contrée de Gosen; et si tu connais parmi eux des hommes de ressource, fais-les inspecteurs des troupeaux que j\'ai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Et Joseph introduisit Jacob, son père, et le présenta à Pharaon. Et Jacob bénit Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Et Pharaon dit à Jacob: Combien as-tu d\'années de vie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Et Jacob dit à Pharaon: Mon pèlerinage est de cent trente ans; les jours de ma vie ont été courts et mauvais, et n\'atteignent pas à la durée de la vie de mes pères dans leur pèlerinage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Et Jacob bénit Pharaon et se retira de devant Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Et Joseph établit son père et ses frères, et leur donna une propriété dans le pays d\'Égypte, dans la meilleure partie du pays, dans la contrée de Ramsès, conformément à l\'ordre de Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Et Joseph fournit de pain son père et ses frères et toute la maison de son père, en raison du nombre d\'enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Et dans tout le pays il n\'y avait point de pain, car la famine était très intense, et le pays d\'Égypte et le pays de Canaan languissaient de faim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Et Joseph recueillit tout l\'argent qui se trouva au pays d\'Égypte et au pays de Canaan pour les achats de blé, et Joseph fit entrer tout cet argent dans la maison de Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Et lorsque l\'argent fut disparu du pays d\'Égypte et du pays de Canaan, tous les Egyptiens vinrent à Joseph en disant: Donne-nous du pain? pourquoi faut-il donc que nous mourions sous tes yeux? car l\'argent manque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Et Joseph dit: Amenez votre bétail et pour votre bétail je vous en donnerai, si l\'argent manque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Alors ils amenèrent leur bétail à Joseph, et il leur donna du pain en échange des chevaux, du menu et du gros bétail et des ânes, et il les fournit de pain cette année-là en échange de tout leur bétail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Et cette année-là s\'étant écoulée, ils vinrent à lui l\'année suivante disant: Nous ne pouvons dissimuler à monseigneur que l\'argent étant épuisé, et notre bétail dévolu à monseigneur, il ne nous reste plus en face de monseigneur que nos corps et notre sol.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Pourquoi nous faudrait-il périr sous tes yeux, nous aussi bien que notre sol? Achète-nous, nous et notre sol pour du pain, et nous deviendrons avec notre sol les serfs de Pharaon, et donne-nous de quoi faire les semailles afin que nous vivions et ne mourions pas, et que notre sol ne soit pas un désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Alors Joseph acheta tout le sol de l\'Égypte pour Pharaon; car les Egyptiens vendirent chacun son champ parce que la famine les pressait. Et le pays fut ainsi dévolu à Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Quant au peuple, il le fit passer dans les villes d\'un bout à l\'autre du territoire de l\'Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Les terres des prêtres furent les seules qu\'il n\'acheta point; car les prêtres recevant un fixe de Pharaon et se nourrissant de leur fixe que Pharaon leur payait, purent pour cette raison ne point vendre leurs terres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Alors Joseph dit au peuple: Voici, j\'ai acheté aujourd\'hui pour Pharaon vos personnes et vos terres; voici des semences pour vous, ensemencez le sol.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Et au temps des récoltes vous donnerez un cinquième à Pharaon et les quatre autres parties vous resteront pour ensemencer le sol et pour vous nourrir vous et ceux qui sont dans vos maisons, et pour nourrir vos enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Et ils dirent: Tu nous sauves la vie! puissions-nous trouver grâce aux yeux de notre seigneur, et nous serons les serfs de Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Et c\'est ce que Joseph établit comme une règle perpétuée jusqu\'à ce jour, savoir que sur le sol de l\'Égypte Pharaon prélèverait un cinquième; les terres des prêtres seuls ne furent pas dévolues à Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Et Israël habita au pays d\'Égypte la contrée de Gosen, et ils y possédèrent, et ils furent féconds et ils y devinrent très nombreux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Et Jacob vécut dix-sept ans au pays d\'Égypte, et les années de la vie de Jacob étaient cent quarante-sept années.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Et lorsque les jours de Jacob approchèrent de leur terme, il manda son fils Joseph et lui dit: Si j\'ai trouvé grâce à tes yeux, veuille mettre la main sous ma hanche, et me montrer amour et fidélité: ne me donne point la sépulture en Égypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'je veux reposer avec mes pères, et tu me transporteras hors de l\'Égypte, et tu me déposeras dans leur tombeau. Et il répondit: Je me conformerai à ton ordre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Et il dit: Jure-le-moi! et il le lui jura, et Israël adora à la tête du lit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Et après ces choses il arriva que l\'on dit à Joseph: Voilà ton père malade. Et il prit avec lui ses deux fils, Manassé et Ephraïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Et on l\'annonça à Jacob en ces termes: Voici que ton fils Joseph arrive chez toi. Et Jacob recueillit ses forces et s\'assit au lit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Et Jacob dit à Joseph: Dieu, le Tout-Puissant, m\'est apparu à Luz au pays de Canaan, et m\'a béni');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'et m\'a dit: Voici, je veux te rendre fécond et te multiplier et te faire devenir une masse de peuples, et je donnerai ce pays-ci à ta postérité après toi en propriété éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Et maintenant tes deux fils qui te sont nés au pays d\'Égypte avant mon arrivée chez toi au pays d\'Égypte, seront miens; Ephraïm et Manassé seront miens à l\'égal de Ruben et Siméon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Mais tes enfants que tu engendreras après eux, seront tiens; ils seront compris sous le nom de leurs frères dans le lot de ceux-ci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Et quand je revenais de Mésopotamie, à mes côtés mourut Rachel dans le pays de Canaan, en route, à quelque distance d\'Ephrata; et c\'est là que je lui donnai la sépulture sur le chemin d\'Ephrata, c\'est-à-dire Bethléhem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Alors Israël vit les deux fils de Joseph et dit: Qui sont-ils?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Et Joseph dit à son père: Ce sont mes fils que Dieu m\'a donnés ici. Et il dit: Eh bien! amène-les-moi afin que je les bénisse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Or les yeux d\'Israël étaient accablés par l\'âge et il ne pouvait plus voir. Et il les fit approcher de lui, et il les embrassa et les étreignit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Et Israël dit à Joseph: Je ne pensais pas revoir ton visage et voilà que Dieu m\'a accordé de voir aussi ta postérité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Et Joseph les éloigna de ses genoux et se prosterna la face contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Puis Joseph les prit les deux, Ephraïm à sa droite, à la gauche d\'Israël, et Manassé à sa gauche, à la droite d\'Israël, et il les fit approcher de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Mais Israël étendit sa main droite et la posa sur la tête d\'Ephraïm qui était pourtant le cadet, et il posa sa main gauche sur la tête de Manassé; ce fut sciemment qu\'il posa ainsi sa main, car Manassé était le premier-né.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Et il bénit Joseph et dit: Dieu en la présence duquel ont marché mes pères, Abraham et Isaac, le Dieu qui a été mon berger depuis que j\'existe jusqu\'à ce jour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'l\'Ange qui m\'a délivré de tous les maux, bénisse ces enfants; que mon nom et le nom de mes pères, Abraham et Isaac, soient portés par eux, et qu\'ils multiplient abondamment dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Mais Joseph ayant vu que son père posait sa main droite sur la tête d\'Ephraïm en eut du déplaisir, et il prit la main de son père pour la transférer de la tête d\'Ephraïm sur la tête de Manassé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Et Joseph dit à son père: Non pas ainsi, mon père, car celui-ci est le premier-né, pose ta main droite sur sa tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Mais son père refusa et dit: Je le sais, mon fils, je le sais! lui aussi il deviendra un peuple, lui aussi il grandira; mais son frère cadet sera plus grand que lui, et sa postérité sera une multitude de peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Il les bénit donc ainsi ce jour-là et il dit: Israël bénira par toi et dira: Que Dieu te traite comme Ephraïm et comme Manassé! et il mit ainsi Ephraïm avant Manassé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Et Israël dit à Joseph: Voici, je meurs, et Dieu sera avec vous et vous ramènera au pays de vos pères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'je te donne de plus qu\'à tes frères une portion que j\'ai conquise sur les Amoréens avec mon épée et mon arc.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Et Jacob fit venir ses fils et dit: Rassemblez-vous, je vais vous découvrir ce qui vous arrivera dans les temps à venir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Réunissez-vous, et écoutez, fils de Jacob, écoutez Israël, votre père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, tu es mon premier-né, ma vigueur, et les prémices de ma virilité; tu as la prééminence du rang, la prééminence de la force.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Toi qui bous comme les eaux, tu perdras ton rang! car tu es monté au lit de ton père, tu l\'as profané!... c\'est dans ma couche qu\'il est monté!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Siméon et Lévi sont des frères; leurs glaives furent instruments de violence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Que mon âme n\'entre point en leur conseil, que ma personne ne se joigne point à leur ligue! Dans leur courroux ils ont tué des hommes, et dans leur passion coupé les nerfs des taureaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Maudit soit leur courroux, car il fut violent, et leur fureur, car elle fut cruelle! Je les distribuerai dans Jacob et les disséminerai dans Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juda, c\'est toi que tes frères loueront; ta main saisit le col de tes ennemis, les fils de ton père s\'inclineront devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Juda est un jeune lion, après la capture, tu reviens, mon fils! il se replie, il se rase comme le lion, comme la lionne, qui le fera lever?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Le sceptre ne se retire point de Juda, ni le bâton de l\'empire d\'entre ses pieds, jusqu\'à ce qu\'il entre à Silo, et que les peuples lui rendent obéissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Il attache son âne à la vigne, et au noble cep le poulain de son ânesse; il baigne son habit dans le vin, et son manteau dans le sang du raisin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'le vin fait étinceler ses yeux, et le lait blanchit ses dents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zabulon habite la plage de la mer, il habite la plage des navires, et ses confins atteignent à Sidon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issaschar, âne robuste, repose entre les parcs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'et voyant la beauté de son lieu de son repos, et les agréments de la contrée, il présente son épaule au fardeau, et fait le service des corvées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan juge son peuple, comme chacune des tribus d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan est un serpent sur le chemin, un céraste sur le sentier, il mord les pâturons des chevaux, et le cavalier tombe à la renverse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'C\'est ton salut que j\'attends, Éternel!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad est assailli par des escadrons, mais il assaille l\'arrière-garde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'D\'Asser sort le pain savoureux, il fournit les friandises des rois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Nephthali est une biche élancée: il prononce des discours élégants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Joseph est le rameau d\'un arbre fécond, le rameau d\'un arbre fécond près d\'une source, ses jets franchissent la muraille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'On le provoque, on tire, et les archers le poursuivent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'mais son arc reste ferme et ses mains ont force et souplesse. Que la main du Héros de Jacob, du lieu où réside le Berger et le Rocher d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'la main du Dieu de ton père, qui fut ton aide, du Tout-Puissant qui t\'a béni, répande les bénédictions du ciel exhaussé, les bénédictions des ondes de la couche inférieure, les bénédictions des mamelles et de la maternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'La bénédiction de ton père est supérieure à la bénédiction des monts élevés, aux attraits des coteaux éternels: qu\'elle repose sur la tête de Joseph, sur le front du prince de ses frères!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin est le loup qui déchire; le matin il dévore une proie, et le soir il partage le butin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Tels sont tous ceux qui forment les tribus d\'Israël, douze en nombre, et telles sont les paroles que leur adressa leur père; et c\'est ainsi qu\'il les bénit, leur donnant à chacun une bénédiction particulière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Et il leur laissa ses instructions en ces termes: Je vais être recueilli auprès de mon peuple; vous me donnerez la sépulture à côté de mes pères dans la grotte du champ de Ephron le Héthien,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'dans la grotte du champ de Macpéla à l\'orient de Mamré au pays de Canaan, qu\'Abraham a achetée de Ephron le Héthien, avec le champ comme propriété sépulcrale;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'c\'est là qu\'ont reçu la sépulture Abraham et Sarah, sa femme; c\'est là qu\'ont reçu la sépulture Isaac et Rebecca, sa femme, et c\'est là que j\'ai donné la sépulture à Léa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'dans le champ acheté des enfants de Heth, et dans la grotte qui s\'y trouve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Et lorsque Jacob eut achevé de donner ses ordres à ses fils, il assembla ses pieds sur le lit, et il expira et fut recueilli auprès de ses pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Alors Joseph se jeta sur le visage de son père, et penché sur lui il pleura et l\'embrassa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Et Joseph ordonna à ses serviteurs, les médecins, d\'embaumer son père. Et les médecins embaumèrent Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Et quarante jours y furent employés car c\'est le nombre de jours qu\'on emploie pour embaumer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Et les Egyptiens le pleurèrent soixante-dix jours. Et quand les jours où on le pleura, furent passés, Joseph s\'adressa à la maison de Pharaon en ces termes: Si j\'ai trouvé grâce à vos yeux, veuillez redire aux oreilles de Pharaon ces paroles:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mon père m\'a adjuré et m\'a dit: Voici, je me meurs; c\'est dans mon tombeau que je me suis acheté au pays de Canaan, que tu me donneras la sépulture Permets-moi donc d\'aller donner la sépulture à mon père, après quoi je reviendrai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Et Pharaon dit: Va donner la sépulture à ton père selon le serment qu\'il t\'a fait prêter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Alors Joseph partit pour la sépulture de son père et il fut accompagné par tous les serviteurs de Pharaon, les Anciens de sa maison et tous les Anciens du pays d\'Égypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'et par toute la maison de Joseph et par ses frères et la maison de son père; et ce ne fut que leurs enfants et leurs brebis et leurs bestiaux qu\'ils laissèrent dans la contrée de Gosen,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'et il avait une escorte de chars et de cavaliers, de sorte que la caravane était très considérable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Et arrivés à l\'aire d\'Atad située au-delà du Jourdain, ils y firent une très grande et très plaintive lamentation funèbre, et il célébra en l\'honneur de son père un deuil de sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Et les habitants du pays, les Cananéens, témoins de la lamentation près de l\'aire d\'Atad, dirent: C\'est un grand deuil des Egyptiens. C\'est pourquoi on a donné à l\'aire située au-delà du Jourdain le nom de Abel-Mistraim (deuil des Egyptiens).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Et les fils de Jacob exécutèrent à son égard les ordres qu\'il leur avait donnés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Et ses fils le transportèrent au pays de Canaan, et lui donnèrent la sépulture dans la grotte du champ de Macpéla, qu\'Abraham avait achetée avec le champ comme propriété sépulcrale, de Ephron, le Héthien, à l\'orient de Mamré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Et Joseph regagna l\'Égypte, lui et ses frères et tous ceux qui l\'avaient accompagné aux funérailles de son père après qu\'il eut donné la sépulture à son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Et les frères de Joseph voyant leur père mort se dirent: Et si Joseph conservait de la haine contre nous et nous rendait tout le mal que nous lui avons fait?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Et ils firent faire à Joseph ce message: Ton père avant de mourir nous a donné cet ordre:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Ainsi vous parlerez à Joseph: Oh! pardonne le crime de tes frères, et le péché qu\'ils ont commis en te faisant du mal! A présent pardonne donc le péché des serviteurs du Dieu de ton père! Et Joseph pleura à l\'ouïe de leur message.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Et ses frères vinrent eux-mêmes et se prosternèrent devant lui et dirent: Voici, nous sommes tes esclaves.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Alors Joseph leur dit: Soyez sans crainte! Usurperais-je la place de Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Vous aviez pensé à me faire du mal, mais Dieu a pensé à opérer du bien, afin d\'exécuter ce qui arrive aujourd\'hui, de sauver la vie à un peuple nombreux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Soyez donc sans crainte, je vous entretiendrai vous et vos enfants. Et il les consola et parla à leur cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Ainsi Joseph demeura en Égypte, lui et la maison de son père, et Joseph vécut cent-dix ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Et Joseph vit les fils d\'Ephraïm jusqu\'à la troisième génération, et les fils de Machir, fils de Manassé, furent aussi reçus à leur naissance sur les genoux de Joseph.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Et Joseph dit à ses frères: Je vais mourir et Dieu prendra soin de vous, et vous fera remonter de ce pays-ci au pays qu\'il a promis par serment à Abraham, à Isaac et à Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Et Joseph fit prêter ce serment aux fils d\'Israël: Quand Dieu vous visitera, vous emmènerez mes os d\'ici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Et Joseph mourut âgé de cent-dix ans, et ils l\'embaumèrent, et on le mit dans un cercueil en Égypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Et voici les noms des fils d\'Israël venus en Egypte avec Jacob; ils vinrent chacun avec sa maison:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Siméon, Lévi et Juda;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issaschar, Zabulon et Benjamin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan et Nephthali; Gad et Asser;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'et toutes les personnes issues des entrailles de Jacob étaient au nombre de soixante-dix âmes; or Joseph était en Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Et Joseph mourut ainsi que tous ses frères et toute cette génération-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Et les enfants d\'Israël furent féconds et pullulèrent et se multiplièrent et s\'accrurent de plus en plus, et ils remplirent le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Alors il s\'éleva un nouveau roi sur l\'Egypte, qui ne connaissait point Joseph.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Et il dit à son peuple: Voilà que le peuple des enfants d\'Israël est plus grand et plus fort que nous:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'eh bien! opposons-lui la prudence afin qu\'il n\'augmente pas, et que, le cas échéant d\'une guerre, il ne se joigne pas à nos ennemis pour nous combattre, puis partir du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Et l\'on préposa sur lui des chefs de corvée dans le but de l\'accabler sous leur faix; et il bâtit pour Pharaon des villes de dépôt, Pithom et Ramsès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Mais plus on l\'accablait, plus il multipliait et se propageait; et ils prirent peur des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Et les Égyptiens firent peser sur les enfants d\'Israël une servitude oppressive,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'et par de rudes travaux en argile et en briques, et par tous les travaux de la campagne ils empoisonnaient leur vie, par tout l\'ouvrage auquel ils les employaient tyranniquement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Et le roi d\'Egypte parla aux sages-femmes des Hébreux, parmi lesquelles une se nommait Siphra, et une autre Puha,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'et dit: Lorsque vous accoucherez les femmes des Hébreux, et que pendant le travail vous verrez que c\'est un fils, tuez-le; mais si c\'est une fille, laissez-la vivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Mais les sages-femmes craignirent Dieu et ne se conformèrent point à l\'ordre du roi d\'Egypte, et elles laissèrent vivre les enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Alors le roi d\'Egypte manda les sages-femmes et leur dit: Pourquoi avez-vous agi de la sorte et laissé vivre les enfants?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Et les sages-femmes répondirent à Pharaon: C\'est que les femmes des Hébreux ne sont pas comme les Egyptiennes, car elles sont vigoureuses, et, avant l\'arrivée de la sage-femme, elles ont déjà enfanté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Et Dieu fit du bien aux sages-femmes, et le peuple se multiplia et s\'accrut beaucoup.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Et parce que les sages femmes avaient eu la crainte de Dieu, Dieu leur éleva des maisons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Alors Pharaon prescrivit cet ordre à tout son peuple: Vous jetterez au Nil tous les fils qui naîtront, mais vous laisserez vivre les filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Et un homme de la maison de Lévi était allé se marier avec une fille de la maison de Lévi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Et cette femme devint enceinte, et eut un fils; et voyant qu\'il était beau, elle le cacha pendant trois mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Mais ne pouvant le tenir caché plus longtemps elle prit un batelet de jonc qu\'elle enduisit de poix et de résine et elle y plaça l\'enfant et elle l\'exposa dans les roseaux au bord du Nil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Et la sœur de l\'enfant se posta à distance pour observer ce qui lui arriverait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Et la fille de Pharaon descendit pour se baigner dans le Nil. Or ses femmes marchaient le long du fleuve; et elle aperçut le batelet au milieu des roseaux, et elle envoya sa suivante pour le prendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Et l\'ayant découvert elle vit un enfant, et voici, c\'était un petit garçon qui pleurait; et elle eut pitié de lui et dit: C\'est l\'un des enfants des Hébreux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Alors la sœur dit à la fille de Pharaon: Irai-je te chercher une nourrice parmi les femmes des Hébreux pour allaiter l\'enfant?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Et la fille de Pharaon lui dit: Va. Et la jeune fille alla chercher la mère de l\'enfant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Et la fille de Pharaon lui dit: Emporte cet enfant, et allaite-le pour moi, et je te donnerai ton salaire. Alors la femme emporta l\'enfant et l\'allaita.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Et lorsque l\'enfant eut grandi, elle l\'amena à la fille de Pharaon, et il fut pour elle un fils, et elle lui donna le nom de Moïse, et dit: C\'est que je l\'ai retiré des eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Et à cette époque-là, comme Moïse était adulte, il alla visiter ses frères, et fut témoin de leurs charges, et il vit un Égyptien battre un Hébreu, l\'un de ses frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Et il regarda de côté et d\'autre, et voyant qu\'il n\'y avait personne, il fit tomber sous ses coups l\'Égyptien et l\'enfouit dans le sable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Et le lendemain il sortit, et voilà que deux Hébreux se querellaient, et il dit à celui qui avait tort: Pourquoi frappes-tu ton prochain?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Et il répondit: Qui t\'a préposé sur nous comme supérieur et juge? Penses-tu à me tuer, comme tu as tué l\'Égyptien? Alors Moïse eut peur et dit: Certainement le fait est connu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Et Pharaon ouït parler du fait, et il cherchait à faire mourir Moïse. Mais Moïse s\'enfuit de devant Pharaon, et il se fixa au pays de Madian, demeurant près de la fontaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Or le prêtre de Madian avait sept filles, et elles venaient puiser de l\'eau et emplir les auges pour abreuver les brebis de leur père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Et les bergers arrivèrent et les chassèrent; mais Moïse se leva, et leur prêta secours et abreuva leurs brebis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Et quand elles furent de retour auprès de Reguel, leur père, il leur demanda: Pourquoi venez-vous si tôt aujourd\'hui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Et elles répondirent: Un Égyptien nous a sauvées des mains des bergers, et même il a puisé l\'eau pour nous, et abreuvé les brebis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Et il dit à ses filles: Mais où est-il? Pourquoi avez-vous laissé là cet homme? Invitez-le à manger le pain!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Et Moïse consentit à demeurer chez cet homme, qui lui donna Tsippora, sa fille, en mariage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Et elle enfanta un fils, et il l\'appela du nom de Gersom (hôte), car il dit: Je suis hôte en pays étranger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Et longtemps après, le roi d\'Egypte mourut, et les enfants d\'Israël gémissaient sous la servitude et poussaient des cris, et leurs cris, excités par la servitude, arrivèrent jusqu\'à Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Et Dieu écouta leurs gémissements et se rappela son alliance avec Abraham, avec Isaac et avec Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Et Dieu voyait les enfants d\'Israël et Il était sachant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Or Moïse faisait paître les brebis de Jéthro, son beau-père, prêtre de Madian, et il conduisit le troupeau derrière le désert et gagna la montagne de Dieu en Horeb.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Et l\'ange de l\'Éternel lui apparut dans une flamme de feu du milieu du buisson; et il regarda, et voilà que le buisson était enflammé et que le buisson n\'était point consumé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Et Moïse dit: Il faut que je tire de côté pour voir cette grande vision, pourquoi le buisson ne brûle pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Et lorsque l\'Éternel vit qu\'il tirait de côté pour voir, Dieu l\'appela du milieu du buisson et dit: Moïse! Moïse! Et il répondit: Me voici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Et Il dit: Ne t\'approche pas d\'ici, ôte tes sandales de tes pieds, car le lieu où tu te tiens, est une terre sainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Et Il dit: Je suis le Dieu de ton père, le Dieu d\'Abraham, le Dieu d\'Isaac, et le Dieu de Jacob. Alors Moïse se couvrit le visage, car il craignait de fixer ses regards sur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Et l\'Éternel dit: J\'ai vu, j\'ai vu la misère de mon peuple qui est en Egypte, et j\'ai entendu les cris que lui arrachent ses exacteurs, car je connais ses douleurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Et je suis descendu pour le délivrer de la main des Égyptiens, et le ramener de ce pays-ci dans un pays excellent et spacieux, dans un pays découlant de lait et de miel, dans le séjour des Cananéens et des Héthiens, et des Amoréens et des Phérisiens et des Hévites et des Jébusites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Et maintenant, voici, les cris des enfants d\'Israël sont parvenus jusqu\'à moi, et j\'ai vu aussi l\'oppression dont les Égyptiens les accablent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Va donc, je vais te déléguer auprès de Pharaon, et fais sortir d\'Egypte mon peuple, les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Et Moïse dit à Dieu: Qui suis-je pour aborder Pharaon et pour faire sortir d\'Egypte les enfants d\'Israël?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Et Il dit: C\'est que je serai avec toi; voici qui sera pour toi un signe de la mission que je te donne: quand tu feras sortir le peuple de l\'Egypte, vous servirez Dieu sur cette montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Et Moïse dit à Dieu: Voici, quand je serai venu auprès des enfants d\'Israël et que je leur dirai: Le Dieu de vos pères m\'envoie à vous; et qu\'ils me diront: Quel est son nom? que leur répondrai-je?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Et Dieu dit à Moïse: Je suis celui qui suis. Et Il dit: Ainsi parleras-tu aux enfants d\'Israël: Je suis m\'envoie à vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Et Dieu dit encore à Moïse: Ainsi parleras-tu aux enfants d\'Israël: L\'Éternel, Dieu de vos pères, Dieu d\'Abraham, Dieu d\'Isaac et Dieu de Jacob, m\'envoie à vous; c\'est là mon nom pour l\'éternité, c\'est ma dénomination pour tous les âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Va et assemble les Anciens d\'Israël et dis-leur: L\'Éternel, Dieu de vos pères, m\'est apparu, le Dieu d\'Abraham, d\'Isaac et de Jacob, et m\'a dit: J\'ai arrêté mes regards sur vous et sur ce qu\'on vous fait en Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'et j\'ai dit: Je vous retirerai des misères de l\'Egypte pour vous amener dans le pays des Cananéens et des Héthiens et des Amoréens et des Phérisiens et des Hévites et des Jébusites, dans un pays découlant de lait et de miel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Et ils prêteront l\'oreille à ta voix, et tu te rendras, toi et les Anciens d\'Israël, auprès du roi d\'Egypte et vous lui direz: L\'Éternel, Dieu des Hébreux, nous est apparu; ainsi, permets-nous maintenant de nous avancer à trois journées de marche dans le désert, et de faire des sacrifices à l\'Éternel, notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Or je sais que le roi d\'Egypte ne vous permettra point de partir, sinon par la force.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Et j\'étendrai ma main et frapperai l\'Egypte au moyen de tous mes miracles que je ferai dans son sein; après quoi il renverra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Et je ferai trouver grâce à ce peuple aux yeux des Égyptiens, et quand vous partirez, vous ne partirez pas à vide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Et chaque femme demandera à sa voisine et à son hôtesse de la vaisselle d\'argent et de la vaisselle d\'or, et des vêtements que vous mettrez à vos fils et à vos filles, et ainsi vous dépouillerez les Égyptiens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Alors Moïse répondit et dit: Mais voici, ils ne me croiront pas et n\'écouteront point ma voix, car ils diront: L\'Éternel ne t\'est point apparu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Et l\'Éternel lui dit: Qu\'as-tu dans la main? Et il répondit: Un bâton.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Et Il dit: Jette-le par terre. Et il le jeta par terre, et le bâton devint serpent, et Moïse s\'enfuit à son aspect.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Et l\'Éternel dit à Moïse: Étends la main et saisis-le par la queue. Et il étendit la main et le saisit, et le serpent redevint bâton dans sa main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, '« C\'est afin qu\'ils croient que l\'Éternel, Dieu de leurs pères, t\'est apparu, le Dieu d\'Abraham, le Dieu d\'Isaac et le Dieu de Jacob. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Et l\'Éternel lui dit encore: Ramène donc ta main dans ton sein. Et il ramena sa main dans son sein, puis il l\'en retira et voilà que sa main était couverte d\'une lèpre pareille à la neige.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Et Il dit: Ramène ta main dans ton sein. Et il ramena sa main dans son sein, puis il l\'en retira, et voilà qu\'elle était redevenue pareille à sa chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, '« Que s\'ils ne te croient pas et n\'écoutent pas le langage du premier signe, ils croiront au langage du second signe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Que s\'ils ne se rendent pas même à ces deux signes, et n\'écoutent pas ta voix, prends de l\'eau du Nil, et répands-la sur la terre sèche; l\'eau que tu auras prise dans le fleuve, deviendra sang sur la terre sèche. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Et Moïse dit à l\'Éternel: Je t\'en conjure, Seigneur! Ni d\'hier ni d\'avant-hier je ne fus un homme disert, pas même depuis que tu parles à ton serviteur, car j\'ai la bouche pesante et la langue pesante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Et l\'Éternel lui dit: Qui a formé à l\'homme une bouche, ou qui rend muet ou sourd, voyant ou aveugle? n\'est-ce pas moi l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Ainsi va, et moi-même je serai en aide à ta bouche, et je t\'enseignerai ce que tu auras à dire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Et il dit: Je t\'en conjure, Seigneur! oh! envoie qui il te plaira d\'envoyer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Alors la colère de l\'Éternel s\'enflamma contre Moïse, et Il dit: N\'as-tu pas pour frère Aaron, le Lévite? je sais qu\'il est capable de parler, et même le voici qui vient au-devant de toi, et te voyant il se réjouira dans son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Et tu lui parleras, et tu lui mettras les paroles dans la bouche, et je serai en aide à ta bouche et à sa bouche, et je vous montrerai ce que vous aurez à faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Et il parlera pour toi au peuple et il sera une bouche pour toi et tu seras Dieu pour lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Et prends dans ta main ce bâton-là avec lequel tu opéreras les signes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Alors Moïse s\'en alla et revint chez son beau-père Jéthro, et lui dit: Laisse-moi partir et rejoindre mes frères qui sont en Egypte, afin que je voie s\'ils sont encore en vie. Et Jéthro dit à Moïse: Va en paix!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Et l\'Éternel dit à Moïse en Madian: Va, retourne en Egypte, car tous les hommes qui en voulaient à ta vie sont morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Alors Moïse prit sa femme et ses fils et leur donna des ânes pour monture et revint au pays d\'Egypte. Et Moïse prit, le bâton de Dieu dans sa main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Et l\'Éternel dit à Moïse: En cheminant pour retourner en Egypte, considère tous les miracles que j\'ai mis en ton pouvoir, et tu les opéreras devant Pharaon; mais moi, j\'endurcirai son cœur, en sorte qu\'il ne laissera point aller le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Et tu diras à Pharaon: Ainsi parle l\'Éternel: Israël est mon fils premier-né,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'et je te dis: Laisse aller mon fils me servir; et si tu refuses de le laisser aller, voici, je ferai mourir ton fils premier-né.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Et il arriva pendant le voyage, dans l\'hôtellerie, que l\'Éternel se trouva devant lui, et Il voulait le faire mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Alors Tsippora prit un caillou et trancha le prépuce de son fils, et le jeta à ses pieds, en disant: Tu es pour moi un époux sanguinaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Et Il cessa de le prendre à partie. C\'est alors qu\'elle dit: Tu es un époux sanguinaire eu égard à la circoncision.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Et l\'Éternel dit à Aaron: Va à la rencontre de Moïse dans le désert. Et il partit et le rencontra sur la montagne de Dieu, et il l\'embrassa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Alors Moïse rapporta à Aaron toutes les paroles de l\'Éternel qui l\'envoyait et tous les signes dont Il lui avait donné l\'ordre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Puis Moïse se mit en route avec Aaron; et ils assemblèrent tous les Anciens des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Et Aaron leur transmit toutes les paroles que l\'Éternel avait dites à Moïse; et il opéra les signes devant le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Et le peuple crut, et quand ils apprirent que l\'Éternel avait souci des enfants d\'Israël, et qu\'il considérait leur misère, ils se prosternèrent et adorèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Et après cela parurent Moïse et Aaron, et ils dirent à Pharaon: Ainsi parle l\'Éternel, Dieu d\'Israël: Laisse mon peuple aller célébrer une fête en mon honneur au désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Et Pharaon dit: Qui est l\'Éternel pour que j\'obéisse à sa voix en laissant partir Israël? Je ne connais point l\'Éternel et ne laisserai pas non plus partir Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Et ils dirent: Le Dieu des Hébreux nous est apparu, permets-nous donc de nous avancer à trois jours de marche dans le désert, et d\'offrir un sacrifice à l\'Éternel, notre Dieu, afin qu\'il ne nous assaille pas avec la peste ou avec l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Et le roi d\'Egypte leur dit: Pourquoi, Moïse et Aaron, voulez-vous distraire le peuple de ses travaux? Allez à vos corvées!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Et Pharaon dit: Voici, le peuple est déjà nombreux, et vous voulez encore lui faire suspendre ses corvées!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Et ce jour-là même Pharaon donna cet ordre aux exacteurs du peuple et à ses préposés:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Désormais ne fournissez plus de paille au peuple pour faire des briques, comme ci-devant; qu\'ils aillent eux-mêmes se ramasser de la paille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Mais vous leur imposerez la même quantité de briques qu\'ils faisaient ci-devant; vous n\'en rabattrez rien, car ils se relâchent; c\'est pourquoi ils crient et disent: Nous voudrions aller offrir un sacrifice à notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Que l\'ouvrage pèse sur ces hommes et les occupe, afin qu\'ils ne se mettent pas en quête de propos mensongers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Sur cela les exacteurs du peuple et ses préposés sortirent et parlèrent au peuple en ces termes: Ainsi parle Pharaon: Je ne vous donne plus de paille,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'allez vous-mêmes vous procurer de la paille où vous en trouverez, car on ne rabat rien de la prestation que vous devez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Alors le peuple se répandit dans tout le pays d\'Egypte afin de ramasser du chaume pour paille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Et les exacteurs pressaient et disaient: Achevez votre besogne, la tâche quotidienne, comme quand il y avait de la paille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Et l\'on battait les préposés des enfants d\'Israël établis sur eux par les exacteurs de Pharaon, en disant: Pourquoi n\'avez-vous pas achevé hier et aujourd\'hui, comme ci-devant, le nombre fixé de briques?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Alors les préposés des enfants d\'Israël vinrent jeter des cris auprès de Pharaon, disant: Pourquoi traites-tu ainsi tes serviteurs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'On ne fournit point de paille à tes serviteurs; et, faites des briques! nous dit-on; et voici tes serviteurs reçoivent des coups; ton peuple pèche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Et il dit: Tous vous relâchez! vous vous relâchez! c\'est pourquoi vous dites: nous voulons aller offrir un sacrifice à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Allez donc! travaillez! et l\'on ne vous fournira point de paille, mais vous livrerez la même quantité de briques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Alors les préposés des enfants d\'Israël se virent dans le fâcheux cas de dire: Vous ne rabattrez rien du nombre quotidien de vos briques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Et ayant abordé Moïse et Aaron qui se tenaient là pour les rencontrer quand ils sortiraient de chez Pharaon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'ils leur dirent: Que l\'Éternel ait l\'œil sur vous et juge, car vous nous avez mis en mauvaise odeur auprès de Pharaon et auprès de ses serviteurs, armant leurs mains de l\'épée pour nous tuer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Alors Moïse s\'adressa de nouveau à l\'Éternel et dit: Seigneur, pourquoi as-tu si fort maltraité ce peuple? pourquoi donc m\'as-tu envoyé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Car depuis que je me suis présenté à Pharaon pour lui parler en ton nom, il fait pis à ce peuple et tu n\'as point délivré ton peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Et l\'Éternel dit à Moïse: Maintenant tu vas voir ce que je ferai à Pharaon; car c\'est sous une main forte qu\'il les laissera partir, et c\'est sous une main forte qu\'il les chassera de son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Et Dieu parla à Moïse et lui dit: Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Et je suis apparu à Abraham, à Isaac et à Jacob, comme Dieu, le Tout-Puissant, mais je ne fus pas connu d\'eux par mon nom d\' Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'J\'ai aussi arrêté avec eux mon alliance pour leur donner le pays de Canaan, le pays de leurs pèlerinages, où ils ont séjourné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'J\'ai aussi entendu les gémissements des enfants d\'Israël asservis par les Égyptiens, et me suis souvenu de mon alliance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'En conséquence dis aux enfants d\'Israël: Je suis l\'Éternel, et je vous soustrairai aux corvées de l\'Egypte et vous délivrerai de leur servitude, et vous sauverai avec un bras étendu et de grands jugements,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'et je vous adopterai comme mon peuple et je serai votre Dieu, et vous sentirez que je suis l\'Éternel, votre Dieu, qui vous délivrera des fardeaux de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Et je vous introduirai dans le pays, dont j\'ai, la main levée, fait don à Abraham, Isaac et Jacob, et je vous le donnerai en propriété, moi l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Et Moïse parla ainsi aux enfants d\'Israël, mais ils n\'écoutèrent point Moïse par l\'effet de leur impatience et de la dure servitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Et l\'Éternel parla à Moïse et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Va annoncer à Pharaon, roi d\'Egypte, qu\'il ait à laisser les enfants d\'Israël partir de son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Et Moïse parla en la présence de l\'Éternel et dit: Voici, les enfants d\'Israël ne m\'ont pas écouté, et comment Pharaon m\'écouterait-il? Et j\'ai des lèvres incirconcises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'C\'est ainsi que parla l\'Éternel à Moïse et à Aaron et qu\'il les délégua auprès des enfants d\'Israël et de Pharaon, roi d\'Egypte, pour retirer du pays d\'Egypte les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Voici les chefs de leurs maisons patriarcales. Fils de Ruben, premier-né d\'Israël: Henoch et Phallu, Hetsron et Charmi; telles sont les familles de Ruben.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Et les fils de Siméon: Jemuel et Jamin et Ohad et Jachin et Tsohar, et Saul, fils de la Cananéenne; telles sont les familles de Siméon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Et voici les noms des fils de Lévi selon leurs souches: Gerson et Kahath et Merari. Or les années de la vie de Lévi furent au nombre de cent trente-sept ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Les fils de Gerson: Libni et Siméi selon leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Et les fils de Kahath: Amram et Jitsear et Hébron et Uziel. Or les années de la vie de Kahath furent au nombre de cent trente-trois années.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Et les fils de Merari: Maheli et Musi; telles sont les familles de Lévi selon leurs souches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Et Amram prit Jochbed, sa tante, pour femme, et elle lui enfanta Aaron et Moïse. Or les années de la vie d\'Amram furent au nombre de cent trente-sept années.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Et les fils de Jitsear: Coré et Nepheg et Zichri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Et les fils d\'Uziel: Misael et Eltsaphan et Sithri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Et Aaron prit pour femme Eliseba, fille de Amminadab, sœur de Nahson, et elle lui enfanta Nadab et Abihu, Eléazar et Ithamar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Et les fils de Coré: Assir et Elkana et Abiasaph; telles sont les familles des Coraïtes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Et Eléazar, fils d\'Aaron, se choisit une femme parmi les filles de Putiel et elle lui enfanta Phinées. Tels sont les chefs des maisons patriarcales des Lévites selon leurs origines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'C\'est cet Aaron et ce Moïse à qui l\'Éternel dit: Faites sortir du pays d\'Egypte les enfants d\'Israël selon leurs divisions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Ce sont eux qui s\'adressèrent à Pharaon, roi d\'Egypte, pour faire sortir de l\'Egypte les enfants d\'Israël; c\'est ce même Moïse et ce même Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Et il arriva que dans le temps où l\'Éternel adressa la parole à Moïse dans le pays d\'Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'l\'Éternel dit à Moïse ces paroles: Je suis l\'Éternel. Dis à Pharaon, roi d\'Egypte, tout ce que je te dis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Et Moïse dit en la présence de l\'Éternel: Voici, j\'ai des lèvres incirconcises, comment donc Pharaon m\'écouterait-il?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Et l\'Éternel dit à Moïse: Vois, je te fais Dieu pour Pharaon, et Aaron, ton frère, sera ton prophète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Tu diras tout ce que je te prescris, et Aaron, ton frère, le redira à Pharaon, afin qu\'il laisse sortir de son pays les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Et moi, j\'endurcirai le cœur de Pharaon et je multiplierai mes signes et mes miracles dans le pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Et Pharaon ne vous écoutera pas; et je mettrai la main sur l\'Egypte, et je ferai par de grands jugements sortir du pays d\'Egypte ma milice, mon peuple, les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Et les Égyptiens sentiront que je suis l\'Éternel, lorsque j\'étendrai ma main sur l\'Egypte et que je tirerai du milieu d\'eux les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Et Moïse et Aaron firent ainsi que l\'Éternel le leur ordonnait; ainsi firent-ils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Or Moïse était âgé de quatre-vingts ans, et Aaron de quatre-vingt-trois ans, lorsqu\'ils s\'adressèrent à Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Et l\'Éternel parla à Moïse et à Aaron en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Si Pharaon vous parle et vous dit: Opérez un miracle, dis à Aaron: Prends ton bâton et le jette devant Pharaon; qu\'il devienne serpent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Et Moïse et Aaron étant venus chez Pharaon firent ce que l\'Éternel avait ordonné; et Aaron jeta son bâton devant Pharaon et devant ses serviteurs, et il devint serpent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Et Pharaon de son côté manda les sages et les enchanteurs, et eux aussi, les hiérogrammates de l\'Egypte, en firent autant par leurs charmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Et ils jetèrent chacun son bâton, et les bâtons devinrent des serpents; mais le bâton d\'Aaron engloutit les leurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Et le cœur de Pharaon s\'endurcit, et il ne les écouta point, ainsi que l\'avait annoncé l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Alors l\'Éternel dit à Moïse: Le cœur de Pharaon s\'obstine, il refuse de laisser partir le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Va trouver Pharaon le matin; voici, il ira à la rivière, et présente-toi à sa rencontre sur le bord du Nil; et prends en ta main le bâton qui a été changé en serpent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'et dis-lui: L\'Éternel, Dieu des Hébreux, m\'a envoyé auprès de toi pour te dire: Laisse partir mon peuple pour me servir dans le désert; mais voici, jusqu\'à présent tu n\'as point écouté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Ainsi parle l\'Éternel: A ceci tu connaîtras que je suis]\'Éternel: voici, du bâton qui est dans ma main, je vais frapper les eaux du Nil et elles seront changées en sang;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'et les poissons qui sont dans le Nil périront; et le Nil sera fétide, et les Égyptiens auront peine à boire l\'eau du Nil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Et l\'Éternel dit à Moïse: Dis à Aaron: Prends ton bâton et étends ta main sur les eaux de l\'Egypte, sur ses courants, sur ses canaux et sur ses lacs et sur tous ses amas d\'eaux; et qu\'elles deviennent du sang; et il y aura du sang dans tout le pays d\'Egypte, dans le bois et dans la pierre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Et Moïse et Aaron exécutèrent ce que leur commandait l\'Éternel; et il leva son bâton et frappa les eaux du Nil sous les yeux de Pharaon et sous les yeux de ses serviteurs, et toute l\'eau du fleuve fut changée en sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Et les poissons du Nil périrent, et le Nil devint fétide, et les Égyptiens ne pouvaient plus boire l\'eau du Nil, et il y eut du sang dans tout le pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Mais les hiérogrammates d\'Egypte en firent autant par leurs charmes; et le cœur de Pharaon s\'endurcit, et il ne les écouta point, ainsi que l\'Éternel l\'avait annoncé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Et Pharaon se tourna et rentra dans sa demeure et cela même ne le fit point réfléchir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Et tous les Égyptiens creusaient aux alentours du fleuve pour trouver de l\'eau à boire; car ils ne pouvaient boire, l\'eau du Nil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Et sept jours s\'écoulèrent après que l\'Éternel eut frappé le fleuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Et l\'Éternel dit à Moïse: Dis à Aaron: Étends ta main avec ton bâton sur les eaux courantes, sur les canaux et sur les lacs, et fais monter les grenouilles sur la terre d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Et Aaron étendit sa main sur les eaux de l\'Egypte, et les grenouilles s\'avancèrent et couvrirent la terre d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Mais les hiérogrammates en firent autant par leurs charmes et attirèrent les grenouilles sur la terre d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Alors Pharaon manda Moïse et Aaron et dit: Intercédez auprès de l\'Éternel, afin qu\'il éloigne les grenouilles de moi et de mon peuple, et je laisserai le peuple aller offrir un sacrifice à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Et Moïse dit à Pharaon: Fixe-moi le temps où je dois intercéder pour toi et tes serviteurs et ton peuple, afin d\'exterminer les grenouilles de chez toi et de tes maisons; il n\'en restera que dans le Nil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Et il dit: Demain. Et Moïse dit: Comme tu le dis! afin que tu saches qu\'il n\'y a point de Dieu, comme l\'Éternel, notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Et les grenouilles seront éloignées de toi et de tes maisons et de tes serviteurs et de ton peuple; il n\'en restera que dans le Nil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Alors Moïse et Aaron sortirent de chez Pharaon, et Moïse éleva ses cris à l\'Éternel au sujet des grenouilles dont Il avait affligé Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Et l\'Éternel opéra ce que demandait Moïse, et les grenouilles périrent et disparurent des maisons, des cours et des champs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Et on les réunit par monceaux, et le pays fut infecté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Mais quand Pharaon se sentit reprendre haleine, il endurcit son cœur, et il ne les écouta point, ainsi que l\'Éternel l\'avait annoncé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Alors l\'Éternel dit à Moïse: Dis à Aaron: Étends ton bâton et frappe la poussière de la terre, afin qu\'elle se change en moustiques dans tout le pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Et ils le firent, et Aaron étendit sa main avec son bâton et frappa la poussière de la terre; et il y eut des moustiques sur les hommes et sur le bétail, toute la poussière de la terre fut changée en moustiques dans tout le pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Et les hiérogrammates entreprirent aussi par le moyen de leurs charmes de produire les moustiques, mais ils n\'y parvinrent pas, et il y eut des moustiques sur l\'homme et sur le bétail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Alors les hiérogrammates dirent à Pharaon: C\'est le doigt de Dieu! Mais le cœur de Pharaon s\'endurcit et il ne les écouta pas, ainsi que l\'avait annoncé l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Alors l\'Éternel dit à Moïse: Lève-toi le matin et te présente devant Pharaon; voici, il ira vers le fleuve et tu lui diras: Ainsi parle l\'Éternel: Laisse partir mon peuple afin qu\'il me serve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Car si tu ne laisses pas mon peuple partir, voici, j\'enverrai contre toi et contre tes serviteurs et contre ton peuple et contre tes maisons les moucherons, et les maisons des Égyptiens se rempliront de moucherons, de même que le sol sur lequel ils sont.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Et dans cette journée-là j\'excepterai la contrée de Gosen où habite mon peuple, en sorte que là il n\'y aura point de moucherons, afin que tu comprennes que moi, l\'Éternel, je suis ici dans le pays;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'et je ferai une différence entre mon peuple et ton peuple, demain ce signe aura lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Et ainsi fit l\'Éternel; et les moucherons pénétrèrent en masse dans la demeure de Pharaon et dans la demeure de ses serviteurs, et dans tout le pays d\'Egypte; le pays fut infesté par les moucherons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Alors Pharaon manda Moïse et Aaron et dit: Allez! offrez le sacrifice à votre Dieu dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Et Moïse dit: C\'est ce qu\'il ne convient point de faire; car nous offririons à l\'Éternel, notre Dieu, un sacrifice qui est l\'abomination des Égyptiens. Si nous offrions un sacrifice qui est l\'abomination des Égyptiens, sous leurs yeux, ne nous lapideraient-ils pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Nous nous avancerons dans le désert à trois jours de marche, et nous offrirons à l\'Éternel, notre Dieu, le sacrifice tel qu\'il nous le prescrira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Et Pharaon dit: Je vous laisserai aller offrir à l\'Éternel, votre Dieu, un sacrifice dans le désert, seulement n\'allez pas à une grande distance; intercédez pour moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Et Moïse dit: Voici, je sors de chez toi, et j\'intercéderai auprès de l\'Éternel, et demain les moucherons se retireront loin de Pharaon, de ses serviteurs et de son peuple. Seulement que Pharaon ne persiste pas à tromper en ne permettant pas au peuple d\'aller offrir un sacrifice à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Puis Moïse sortit de chez Pharaon et intercéda auprès de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Et l\'Éternel fit comme Moïse avait dit, et les moucherons se retirèrent loin de Pharaon, de ses serviteurs et de son peuple; il n\'en resta pas un.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Mais Pharaon endurcit son cœur cette fois-ci encore, et ne laissa point partir le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Et Moïse lui dit: Quand je retournerai à la ville, j\'élèverai mes mains vers l\'Éternel; les tonnerres cesseront, et il n\'y aura plus de grêle, afin que tu reconnaisses que la terre est à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Mais ni toi ni tes serviteurs, je le sais, n\'aurez encore crainte de l\'Éternel Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, '(Or le lin et l\'orge furent frappés, car l\'orge était en épis, et le lin en fleur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Mais le froment et l\'épeautre ne furent point frappés, car ils sont tardifs.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Alors l\'Éternel dit à Moïse: Aborde Pharaon et lui dis: Ainsi parle l\'Éternel, Dieu des Hébreux: Permets à mon peuple d\'aller me servir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'car si tu refuses de le laisser aller et si tu le retiens encore,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'l\'Éternel fera main basse sur tes troupeaux qui sont dans les champs, chevaux, ânes, chameaux, bœufs et brebis, il y aura mortalité très grande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Et l\'Éternel fera une distinction entre les troupeaux d\'Israël et les troupeaux des Égyptiens, et il ne périra rien de ce qui est aux enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Et l\'Éternel fixa le moment et dit: Demain l\'Éternel exécutera cette menace dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Et ainsi fit l\'Éternel le lendemain, et tous les troupeaux des Égyptiens périrent, et des troupeaux des enfants d\'Israël il ne périt rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Et Pharaon fit prendre des informations, et voici, des troupeaux d\'Israël rien n\'avait péri, pas un individu. Mais Pharaon endurcit son cœur et ne laissa point partir le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Alors l\'Éternel dit à Moïse et à Aaron: Prenez vos mains pleines de suie de fournaise, et que Moïse la répande en l\'air aux yeux de Pharaon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'et elle se changera en une poussière qui couvrira tout le pays d\'Egypte, et produira sur les hommes et les bestiaux des ulcères avec éruption de pustules dans tout le pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Et ils prirent, de la suie de fournaise, et se présentèrent devant Pharaon, et Moïse la répandit en l\'air, et elle produisit sur les hommes et les bestiaux une éruption d\'ulcères avec des pustules.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Et les hiérogrammates ne purent plus tenir tête à Moïse à cause des ulcères, car les hiérogrammates et tous les Égyptiens étaient couverts d\'ulcères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Mais l\'Éternel endurcit le cœur de Pharaon, et il ne les écouta point, ainsi que l\'Éternel l\'avait annoncé à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Alors l\'Éternel dit à Moïse: Lève-toi le matin et présente-toi devant Pharaon et dis-lui: Ainsi parle l\'Éternel, Dieu des Hébreux: Permets à mon peuple d\'aller me servir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Car cette fois je veux envoyer toutes mes plaies contre ta personne et sur tes serviteurs et sur ton peuple, afin que tu saches que sur toute la terre nul n\'est mon égal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Car maintenant j\'aurais étendu ma main et frappé et toi et ton peuple de la peste à l\'exterminer de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'mais si je t\'ai laissé debout, c\'est pour te rendre témoin de ma puissance, et afin que l\'on redise mon nom par toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Si tu te roidis encore contre mon peuple pour l\'empêcher d\'aller,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'voici, demain j\'enverrai une très forte pluie de grêle, telle qu\'il n\'y en aura jamais eu de pareille en Egypte depuis le jour de sa création jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Maintenant donc dépêche des messagers et mets en sûreté tes troupeaux et tout ce qui t\'appartient dans les champs. Tous les hommes et tous les bestiaux qui se trouveront dans les champs, et n\'auront pas été recueillis au gîte, s\'ils sont atteints par la grêle, périront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Ceux d\'entre les serviteurs de Pharaon qui craignirent la menace de l\'Éternel, mirent en hâte à l\'abri leurs serviteurs et leurs troupeaux dans les maisons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Mais ceux qui ne tinrent pas compte de la menace de l\'Éternel, laissèrent leurs serviteurs et leurs troupeaux dans les champs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Alors l\'Éternel dit à Moïse: Étends ta main vers le ciel, et qu\'il tombe de la grêle sur tout le pays d\'Egypte, sur les hommes et sur les bestiaux et sur toutes les plantes des champs au pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Et Moïse étendit son bâton vers le ciel, et l\'Éternel détacha tonnerres et grêles, et le feu courut sur la terre, et l\'Éternel fit tomber une pluie de grêle sur le pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Et c\'était une grêle mêlée à un feu continu, tellement forte qu\'on n\'en avait jamais vu de pareille dans tout le pays d\'Egypte depuis qu\'il formait un peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Et la grêle frappa dans tout le pays d\'Egypte tout ce qui était dans les champs, depuis l\'homme aux bestiaux, et la grêle frappa toutes les plantes des champs et brisa tous les arbres des champs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Il n\'y eut que la contrée de Gosen où étaient les enfants d\'Israël, qui n\'eut point de grêle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Alors Pharaon envoya appeler Moïse et Aaron et il leur dit: Cette fois j\'ai péché, l\'Éternel est le juste, et moi et mon peuple les coupables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Intercédez auprès de l\'Éternel! Assez de tonnerres de Dieu et de grêle! et je vous laisserai partir et vous ne serez plus retenus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Et Moïse lui dit: Quand je retournerai à la ville, j\'élèverai mes mains vers l\'Éternel; les tonnerres cesseront, et il n\'y aura plus de grêle, afin que tu reconnaisses que la terre est à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Mais ni toi ni tes serviteurs, je le sais, n\'aurez encore crainte de l\'Éternel Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, '(Or le lin et l\'orge furent frappés, car l\'orge était en épis, et le lin en fleur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Mais le froment et l\'épeautre ne furent point frappés, car ils sont tardifs.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Moïse ayant donc quitté Pharaon se rendait à la ville. Et il étendit ses mains vers l\'Éternel, et les tonnerres et la grêle cessèrent, et la pluie ne tomba plus sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Et Pharaon voyant que la pluie avait cessé avec la grêle et les tonnerres, persista à pécher et il endurcit son cœur, lui et ses serviteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Et le cœur de Pharaon s\'obstina, et il ne laissa point partir les enfants d\'Israël, ainsi que l\'Éternel l\'avait annoncé par l\'organe de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Alors l\'Éternel dit à Moïse: Va auprès de Pharaon, car j\'ai endurci son cœur et le cœur de ses serviteurs, afin d\'opérer mes signes, là au milieu d\'eux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'et afin que tu racontes aux oreilles de ton fils et du fils de ton fils les faits que j\'ai accomplis en Egypte et mes signes que j\'y opère, afin que vous reconnaissiez en moi l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Et Moïse et Aaron se rendirent auprès de Pharaon, et lui dirent: Ainsi parle l\'Éternel, Dieu des Hébreux: Jusques à quand refuseras-tu de t\'humilier devant moi? laisse partir mon peuple pour qu\'il me serve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Car si tu refuses de laisser partir mon peuple, voici, demain j\'amènerai des sauterelles sur ton territoire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'et elles couvriront la face du pays à empêcher d\'apercevoir le sol, et elles dévoreront le reste échappé que vous a laissé la grêle, et elles dévoreront tous les arbres qui vous croissent dans les champs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'et elles rempliront tes maisons et les maisons de tous tes serviteurs, et les maisons de tous les Égyptiens; rien de pareil n\'aura été vu par tes pères ni par les pères de tes pères, depuis qu\'ils sont dans le pays jusqu\'aujourd\'hui. Et se tournant, il sortit de chez Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Alors les serviteurs de Pharaon lui dirent: Jusques à quand cet homme sera-t-il pour nous un piège? Permets à ces gens d\'aller servir l\'Éternel, leur Dieu. Ne comprends-tu pas encore que l\'Egypte se ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Et l\'on ramena Moïse et Aaron auprès de Pharaon, et il leur dit: Allez rendre votre culte à l\'Éternel, votre Dieu! Quels sont tous ceux qui iront?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Et Moïse répondit: Nous irons avec nos jeunes gens et nos vieillards, nous irons avec nos fils et nos filles, avec nos brebis et nos bœufs; car il s\'agit pour nous de la fête de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Et il leur dit: Ainsi soit l\'Éternel avec vous, comme je vais vous laisser partir avec vos enfants!? voyez vous-mêmes que vous avez du mal en vue!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Pas ainsi! Partez, vous les hommes, pour rendre votre culte à l\'Éternel, car c\'est là ce que vous avez demandé. Puis on les chassa de la présence de Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Alors l\'Éternel dit à Moïse: Étends ta main sur le pays d\'Egypte, pour faire venir les sauterelles sur le pays d\'Egypte, afin qu\'elles dévorent toutes les plantes de la terre, tout ce que la grêle a laissé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Et Moïse étendit son bâton sur le pays d\'Egypte, et l\'Éternel dirigea un vent d\'Est sur le pays pendant toute cette journée et toute la nuit; et le matin étant venu, le vent d\'Est apporta les sauterelles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Et les sauterelles envahirent tout le pays d\'Egypte, et s\'établirent dans tout le territoire de l\'Egypte en légions immenses; avant elles il n\'y avait pas eu de sauterelles comme celles-là, et après elles il n\'y en aura plus de pareilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Et elles couvrirent la face de tout le pays, et tout le pays en fut obscurci, et elles dévorèrent toutes les plantes du sol, et tous les fruits des arbres que la grêle avait épargnés, et il ne resta aucune verdure aux arbres ni aux plantes des champs dans tout le pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Alors Pharaon fit en hâte appeler Moïse et Aaron, et il dit: J\'ai péché contre l\'Éternel, votre Dieu, et contre vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Et maintenant pardonne-moi mon péché cette fois seulement et intercédez auprès de l\'Éternel, votre Dieu, afin qu\'il éloigne de moi cette mortalité seulement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Et il sortit de chez Pharaon et intercéda auprès de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Alors l\'Éternel fit souffler à l\'opposite un très fort vent d\'Ouest qui entraîna les sauterelles et les refoula dans la Mer aux algues, et il ne resta pas une seule sauterelle dans tout le territoire de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Mais l\'Éternel endurcit le cœur de Pharaon et il ne laissa point partir les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Alors l\'Éternel dit à Moïse: Étends ta main vers le ciel, pour que des ténèbres couvrent le pays d\'Egypte, des ténèbres palpables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Et Moïse étendit sa main vers le ciel, et il y eut pendant trois jours d\'épaisses ténèbres dans tout le pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'On ne s\'apercevait pas les uns les autres et personne ne se leva de son séant pendant trois jours; mais tous les enfants d\'Israël avaient la lumière dans les lieux où ils habitaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Alors Pharaon manda Moïse et dit: Partez, rendez votre culte à l\'Éternel! on ne retiendra que vos brebis et vos bœufs; vos enfants peuvent aussi vous accompagner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Et Moïse dit: Il faut aussi que tu nous donnes les victimes et les holocaustes que nous sacrifierons à l\'Éternel, notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Et nos troupeaux aussi nous accompagneront; il ne restera ici pas même un sabot, car c\'est là que nous prendrons les victimes que nous offrirons à l\'Éternel, notre Dieu; et nous ignorons quels sacrifices nous aurons à faire jusqu\'à ce que nous soyons arrivés là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Mais l\'Éternel endurcit le cœur de Pharaon, et il ne voulut point les laisser partir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Et Pharaon lui dit: Sors de chez moi, prends garde à toi, et ne reparais pas en ma présence, car le jour où tu paraîtras en ma présence, tu mourras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Et Moïse reprit: Tu as bien dit! je ne reparaîtrai plus en ta présence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, '(Et l\'Éternel dit à Moïse: J\'infligerai encore une plaie à Pharaon et à l\'Egypte; après quoi il vous laissera partir d\'ici; quand il vous laissera partir, ce sera en vous chassant entièrement d\'ici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Dis donc aux oreilles du peuple qu\'on ait à demander, chacun à son voisin, et chacune à sa voisine, de la vaisselle d\'argent et de la vaisselle d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Et l\'Éternel concilia au peuple les bonnes grâces des Égyptiens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Et Moïse était aussi un personnage très considérable dans le pays d\'Egypte aux yeux des serviteurs de Pharaon et aux yeux du peuple.) Et Moïse dit: Ainsi parle l\'Éternel: A minuit je traverserai l\'Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'et tous les premiers-nés du pays d\'Egypte, depuis le premier-né de Pharaon assis sur son trône jusqu\'au premier-né de la servante qui tourne la meule, mourront ainsi que les premiers-nés des bestiaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Et il y aura un grand gémissement dans tout le pays d\'Egypte, tel qu\'il n\'y en a point eu et tel qu\'il n\'y en aura plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Mais tous les enfants d\'Israël, depuis les hommes aux bestiaux, ne verront pas même le bout de la langue d\'un chien, afin que vous sentiez la différence que l\'Éternel fait entre les Égyptiens et Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Et tous ces tiens serviteurs descendront vers moi et s\'inclineront devant moi et diront: Pars, toi et tout le peuple qui te suit; après quoi je partirai. Et enflammé de colère il quitta Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Et l\'Éternel dit à Moïse: Pharaon ne vous écoute pas, afin que mes miracles se multiplient dans le pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Et Moïse et Aaron opérèrent tous ces miracles sous les yeux de Pharaon, mais l\'Éternel endurcit le cœur de Pharaon, et il ne laissa point sortir de son pays les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Et l\'Éternel parla à Moïse et à Aaron dans le pays d\'Egypte en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Ce mois-ci sera pour vous le premier mois; qu\'il soit en tête des mois de votre année.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Parlez et dites à toute l\'assemblée d\'Israël: Le dixième jour de ce mois ils auront à se pourvoir chacun d\'un agneau par maison patriarcale, d\'un agneau par maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Et si la maison est trop peu nombreuse pour un agneau, on s\'associera au voisin le plus rapproché de sa maison pour le prendre selon le nombre des personnes, et pour choisir l\'agneau vous tiendrez compte de chacun en raison de ce qu\'il mange.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Ce sera un agneau sans défaut, mâle et âgé d\'un an; vous le choisirez parmi les brebis ou les chèvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Et vous le garderez jusqu\'au quatorzième jour de ce mois-ci, et toute la générale assemblée d\'Israël l\'immolera dans la soirée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Et ils prendront de son sang et en mettront sur les deux jambages et la traverse supérieure de la porte des maisons où ils le mangeront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Et ils mangeront pendant cette nuit la chair rôtie au feu et des azymes; ils le mangeront avec des herbes amères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Vous ne le mangerez ni mi-cuit, ni bouilli à l\'eau, mais rôti au feu, tête, jarrets et intérieur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Et vous n\'en laisserez rien pour le matin, et vous brûlerez au feu ce qui en resterait le matin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Et voici comment vous le mangerez: vous aurez les reins ceints, les pieds chaussés, et votre bâton à la main, et vous le mangerez précipitamment: c\'est la Pâque de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Et cette nuit je traverserai le pays d\'Egypte et frapperai tous les premiers-nés au pays d\'Egypte, depuis l\'homme aux bestiaux, et j\'exercerai des jugements sur tous les dieux de l\'Egypte, moi l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Et le sang vous servira de signe aux maisons où vous êtes; et je verrai le sang et passerai outre, et vous ne serez pas atteints par le fléau destructeur, quand je porterai mes coups au pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Et ce jour restera dans votre mémoire pour le célébrer comme une fête en l\'honneur de l\'Éternel; dans les âges futurs vous le célébrerez comme institution perpétuelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Durant sept jours vous mangerez des azymes; dès le premier jour vous ferez disparaître tout ferment de vos maisons, car toute personne qui mangera d\'un aliment fermenté, sera extirpée d\'Israël du premier au septième jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Et le premier jour vous aurez convocation sainte, et le septième jour convocation sainte; et en ces jours aucun travail; préparer la ration de chaque personne, tel sera votre soin unique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Ainsi vous garderez l\'usage des azymes; car c\'est à pareil jour que j\'aurai fait sortir vos divisions du pays d\'Egypte, et vous observerez ce jour dans vos âges futurs comme institution perpétuelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Le premier mois, le quatorzième jour du mois, le soir, vous mangerez des azymes jusqu\'au vingt-unième jour du mois au soir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Sept jours durant il ne doit pas se trouver de levain dans vos maisons, car toute personne qui mangera d\'un aliment fermenté, sera éliminée de l\'assemblée d\'Israël, que ce soit un étranger ou un indigène.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Vous ne mangerez rien de fermenté, dans toutes vos demeures vous mangerez des azymes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Alors Moïse convoqua tous les Anciens d\'Israël, et leur dit: Prenez et choisissez-vous des brebis pour vos familles et immolez la Pâque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Et prenez un bouquet d\'hysope et plongez-le dans le sang contenu dans le bassin, et touchez-en la traverse supérieure et les deux jambages de la porte, avec le sang contenu dans le bassin, et que nul de vous ne passe la porte de sa maison jusqu\'au matin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Car l\'Éternel parcourra l\'Egypte pour la frapper, et à la vue du sang qui teindra la traverse supérieure et les deux jambages de la porte, l\'Éternel passera devant la porte et ne permettra pas au destructeur de pénétrer dans vos maisons pour frapper.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Et vous garderez cette parole comme un statut pour vous et vos enfants à perpétuité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Et lorsque vous serez entrés dans le pays que l\'Éternel vous donnera selon sa promesse, vous observerez cette pratique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Et lorsque vos enfants vous diront: Quel sens attachez-vous à cette pratique?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'vous leur direz: C\'est le sacrifice pascal fait à l\'Éternel qui est passé devant les maisons des enfants d\'Israël en Egypte, lorsqu\'il frappait l\'Egypte, et Il a préservé nos maisons. Et le peuple se prosterna et adora.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Et les enfants d\'Israël s\'en allèrent et se conformèrent; ils se conformèrent à l\'ordre donné par l\'Éternel à Moïse et Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Et à minuit il arriva que l\'Éternel frappa tous les premiers-nés au pays d\'Egypte, depuis le premier-né de Pharaon assis sur son trône jusqu\'au premier-né du captif détenu en prison et tous les premiers-nés des bestiaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Et Pharaon se leva de nuit, lui et tous ses serviteurs et tous les Égyptiens, et ce fut une immense lamentation en Egypte, parce qu\'il n\'y avait point de maison où ne fût un mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Et il manda de nuit Moïse et Aaron et dit: Partez, sortez du milieu de mon peuple, et vous et les enfants d\'Israël, et allez servir l\'Éternel selon votre demande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Prenez aussi et vos brebis et vos bœufs selon votre demande, et partez, et me bénissez aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Et les Égyptiens pressaient le peuple, pour le renvoyer en hâte du pays, car ils disaient: Nous nous mourons tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Et le peuple emporta sa pâte avant qu\'elle eût fermenté, leurs huches serrées dans leurs manteaux sur leurs épaules.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Et les enfants d\'Israël se conformèrent à la parole de Moïse et demandèrent aux Égyptiens de la vaisselle d\'argent et de la vaisselle d\'or et des vêtements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Et l\'Éternel concilia au peuple les bonnes grâces des Égyptiens qui leur accordèrent ce qu\'ils demandaient, et ils dépouillèrent ainsi les Egyptiens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Et les enfants d\'Israël se transportèrent de Ramsès à Succoth au nombre de six cent mille hommes de pied, sans les enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Une multitude d\'étrangers les accompagnèrent aussi, et leurs troupeaux de gros et de menu bétail en nombre très considérable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Et ils boulangèrent la pâte qu\'ils avaient emportée d\'Egypte, en galettes non levées; car elle n\'avait pas fermenté; car ils avaient été chassés de l\'Egypte, et ils ne pouvaient différer, n\'ayant d\'ailleurs point préparé d\'aliments.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Or le temps du séjour des enfants d\'Israël en Egypte fut de quatre cent trente ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Et au terme de quatre cent trente ans, il arriva que, en ce jour même, toute la milice de l\'Éternel sortit du pays d\'Egypte. C\'est une nuit solennisée en l\'honneur de l\'Éternel pour les avoir retirés du pays d\'Egypte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'c\'est une nuit que les enfants d\'Israël doivent solenniser en l\'honneur de l\'Éternel dans la suite de leurs âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Et l\'Éternel dit a Moïse et Aaron: Voici l\'ordonnance de la Pâque: Aucun étranger n\'y participera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Et tu circonciras tout esclave acheté à prix d\'argent, et ainsi il pourra en manger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Le domicilié et le mercenaire n\'en mangeront pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Elle sera mangée dans la maison uniquement; vous ne porterez de la maison dans la rue aucune partie de la chair, et vous n\'en romprez pas un os.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Toute l\'assemblée d\'Israël fera la Pâque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Et si des étrangers séjournent chez toi, et veulent faire la Pâque de l\'Éternel, tous leurs mâles devront être circoncis, et ainsi ils seront admis à la célébrer et assimilés aux indigènes; mais aucun incirconcis ne prendra part à ce repas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'à la même loi obéiront les indigènes et les étrangers en séjour parmi vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Et tous les enfants d\'Israël se conformèrent, ils se conformèrent à l\'ordre donné par l\'Éternel à Moïse et Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Et il arriva dans ce jour même que l\'Éternel fit sortir du pays d\'Egypte les enfants d\'Israël selon leurs divisions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Consacre-moi tous les premiers-nés, les prémices de toute maternité, parmi les fils d\'Israël, et chez les hommes et chez les animaux: ce sera ma propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Et Moïse dit au peuple: Souvenez-vous de cette journée, où vous êtes sortis de l\'Egypte, de la maison de servitude, car l\'Éternel vous en a retirés par la force de [sa] main. [Souvenez-vous-en] pour vous abstenir d\'aliments fermentés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'C\'est dans cette journée que vous êtes sortis au mois des épis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Et lorsque l\'Éternel t\'aura introduit dans le pays des Cananéens et des Héthiens et des Amoréens, des Hévites et des Jébusites, qu\'il a juré à tes pères de te donner, pays découlant de lait et de miel, tu célébreras ce service dans ce mois-ci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Sept jours tu mangeras des pains sans levain, et le septième sera une solennité en l\'honneur de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Pendant sept jours on usera de pains sans levain, et qu\'il ne se voie chez toi rien de fermenté, et qu\'il ne se voie chez toi aucun levain dans tout ton territoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Et ce jour-là tu informeras ton fils en disant: C\'est à cause de ce que l\'Éternel a fait pour moi, quand je suis sorti d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Et que ceci devienne pour toi un signe sur ta main et un mémorial entre tes yeux, afin que la loi de l\'Éternel soit dans ta bouche, car c\'est par la force de sa main que l\'Éternel t\'a retiré d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Et tu observeras cette règle à son époque fixe d\'année en année.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Et lorsque l\'Éternel t\'aura introduit dans le pays des Cananéens selon le serment qu\'il a fait à toi et à tes pères, et qu\'il te l\'aura donné,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'tu transféreras à l\'Éternel toutes les prémices de la maternité et tous les premiers-nés des animaux que tu auras, les mâles, à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Mais tu rachèteras tous les premiers-nés de l\'âne au moyen d\'un mouton, et si tu ne les rachètes pas, tu leur rompras la nuque; et tu rachèteras tous les premiers-nés de l\'homme par tes fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Et si à l\'avenir ton fils t\'interroge en ces termes: Qu\'est ceci? dis-lui: Par la force de [sa] main l\'Éternel nous a retirés de l\'Egypte, de la maison de servitude,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'et il est arrivé que, comme Pharaon s\'obstinait à ne pas nous laisser partir, l\'Éternel a mis à mort tous les premiers-nés au pays d\'Egypte, depuis le premier-né de l\'homme au premier-né de l\'animal; c\'est pourquoi je fais à l\'Éternel le sacrifice de toutes les prémices de la maternité, des mâles, et je rachète tous mes fils premiers-nés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Et que ceci devienne pour toi un signe sur ta main et un frontal entre tes yeux, car c\'est par la force de [sa main] que l\'Éternel nous a retirés de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Et lorsque Pharaon eut laissé partir le peuple, Dieu ne les conduisit pas par le chemin du pays des Philistins, parce que c\'était le plus direct; car Dieu dit: Le peuple pourrait avoir du regret à la vue du combat et retourner en Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Et Dieu fit faire au peuple un détour par le chemin du désert de la Mer aux algues; or les enfants d\'Israël quittèrent l\'Egypte armés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Et Moïse emporta avec lui les os de Joseph; car celui-ci avait adjuré les enfants d\'Israël en ces termes: Dieu vous visitera; alors emmenez d\'ici mes os avec vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Et ils partirent de Succoth, et vinrent camper à Etham à l\'extrémité du désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Et l\'Éternel marchait à leur tête; de jour dans une colonne de nuée pour les guider dans le trajet, et de nuit dans une colonne de feu, pour leur éclairer, afin qu\'ils pussent cheminer jour et nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Et le peuple ne cessait d\'avoir en vue, de jour la colonne de nuée, et de nuit la colonne de feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Dis aux enfants d\'Israël qu\'ils se replient et campent devant Pihachiroth entre Migdol et la mer, devant Baal-Tsephon; c\'est vis-à-vis que vous camperez près de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Et Pharaon pensera des enfants d\'Israël: Ils se sont perdus dans le pays; le désert les enferme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Et j\'endurcirai le cœur de Pharaon, afin qu\'il les poursuive, et je serai glorifié dans Pharaon et dans toute son armée, et les Égyptiens comprendront que je suis l\'Éternel. Et ils firent ainsi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Et lorsque le roi d\'Egypte fut informé de la fuite du peuple, les sentiments de Pharaon et de ses serviteurs changèrent à l\'égard du peuple et ils dirent: Qu\'avons-nous fait de laisser Israël quitter notre service?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Alors il attela son char et prit son peuple avec lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'et il prit six cents chars d\'élite et tout ce qu\'il y avait de chars en Egypte, tous montés de guerriers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Et l\'Éternel endurcit le cœur de Pharaon, roi d\'Egypte, et il se mit à la poursuite des enfants d\'Israël. Car les enfants d\'Israël étaient partis haut la main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Les Égyptiens les poursuivirent donc et les atteignirent avec tous les chevaux et chars de Pharaon, et sa cavalerie et son armée, dans leur campement près de la mer, à Pihachiroth vis-à-vis de Baal-Tsephon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Et Pharaon s\'approcha et les enfants d\'Israël levèrent les yeux, et voilà que les Égyptiens arrivaient sur eux par derrière, et les enfants d\'Israël furent très effrayés et crièrent à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Et ils dirent à Moïse: Est-ce faute de tombeaux en Egypte que tu nous as amenés mourir dans le désert? Que nous as-tu fait en nous tirant de l\'Egypte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'N\'est-ce pas ce que nous te disions en Egypte: Ne t\'occupe pas de nous, nous voulons servir les Égyptiens: car nous aimons mieux servir les Égyptiens que de mourir dans le désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Alors Moïse dit au peuple: Ne vous effrayez pas! restez en place et contemplez la délivrance que l\'Éternel va opérer aujourd\'hui pour vous; car si vous voyez aujourd\'hui les Égyptiens, désormais vous ne les reverrez plus jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'L\'Éternel combattra pour vous; et vous, soyez tranquilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Et l\'Éternel dit à Moïse: Pourquoi pousses-tu tes cris vers moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Dis aux enfants d\'Israël qu\'ils lèvent le camp. Et toi, lève ton bâton, et étends ta main sur la mer, et fends-la, et les enfants d\'Israël traverseront le milieu de la mer à sec.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Et moi, voici, j\'endurcirai le cœur des Égyptiens, et ils vous suivront, et je serai glorifié dans Pharaon et dans toute son armée, ses chars et sa cavalerie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Et les Égyptiens sauront que je suis l\'Éternel, quand je serai glorifié dans Pharaon, ses chars et sa cavalerie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Alors l\'ange de l\'Éternel, qui marchait en tête de l\'armée d\'Israël, quitta sa place et marcha derrière, et la colonne de nuée qui la précédait quitta sa place et se posa derrière eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Et elle vint entre l\'armée d\'Egypte et l\'armée d\'Israël; et d\'un côté c\'était nuée et obscurité, et de l\'autre elle illuminait la nuit; et ils ne s\'approchèrent pas les uns des autres durant toute la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Et Moïse étendit sa main sur la mer, et l\'Éternel refoula la mer par un fort vent d\'est toute la nuit et changea la mer en terre sèche, et les eaux se fendirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Et les enfants d\'Israël traversèrent le milieu de la mer à sec, et les eaux furent pour eux une muraille à droite et à gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Et les Égyptiens chargèrent, et entrèrent dans la mer après eux avec tous les chevaux de Pharaon, ses chars et sa cavalerie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Et vers la veille du matin, l\'Éternel porta ses regards de la colonne de feu et de nuée sur les Égyptiens, et Il mit en déroute l\'armée d\'Egypte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'et Il disloqua les roues de leurs chars et rendit leur marche difficile. Alors les Égyptiens dirent: Fuyons devant Israël, car l\'Éternel combat pour lui contre l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Et l\'Éternel dit à Moïse: Étends ta main sur la mer, afin que les eaux reviennent couvrir les Égyptiens, leurs chars et leur cavalerie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Et Moïse étendit sa main sur la mer, et vers le matin la mer revint à son niveau ordinaire, et les Égyptiens fuirent à son approche, et l\'Éternel précipita les Égyptiens au milieu de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Et les eaux en revenant couvrirent les chars et la cavalerie de toute l\'armée de Pharaon, entrés à leur suite dans la mer: il n\'en survécut pas un seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Mais les enfants d\'Israël passèrent à sec par le milieu de la mer, et les eaux étaient pour eux une muraille à leur droite et à leur gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'C\'est ainsi que dans cette journée, l\'Éternel sauva Israël des mains des Égyptiens, et Israël vit les Égyptiens morts sur le rivage de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Et Israël fut témoin du grand coup dont l\'Éternel frappa l\'Egypte, et le peuple craignit l\'Éternel et eut foi dans l\'Éternel et dans Moïse, son serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Alors Moïse et les enfants d\'Israël chantèrent un hymne à l\'Éternel et ils dirent: Je chante l\'Éternel qui a paru dans sa grandeur; Il a jeté dans la mer le cheval et son cavalier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Que l\'Éternel soit ma gloire et l\'objet de mes chants, car Il a été mon sauveur. C\'est lui qui est mon Dieu, je le célèbre, le Dieu de mon père, je l\'exalte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'L\'Éternel est un guerrier, son nom est l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Il a jeté dans la mer les chars de Pharaon, et son armée; ses champions d\'élite sont plongés dans la Mer des algues;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'les flots les ont couverts: ils ont enfoncé dans l\'abîme comme la pierre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Ta droite, O Éternel, que la puissance illustre, ta droite, ô Éternel, met tes ennemis en pièces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Par ta souveraine majesté tu abats ceux qui te résistent, tu donnes cours à ta colère; et elle les consume comme la balle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Au souffle de tes narines les eaux s\'accumulèrent, comme une digue les courants s\'arrêtèrent, les flots se contractèrent au sein de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'L\'ennemi disait: Je vais poursuivre, atteindre, partager le butin, mon âme s\'assouvira sur eux, je tirerai l\'épée, ma main les détruira;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'tu exhalas ton souffle, la mer les couvrit, comme le plomb ils s\'abîmèrent dans les ondes puissantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Qui t\'égale parmi les dieux, Éternel? Lequel est comme toi illustre en sainteté, auguste en gloire, auteur de merveilles?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Tu étendis ta main, la terre les engloutit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Tu conduis par ta grâce le peuple que tu as sauvé, tu le mènes par ta puissance au séjour de ta sainteté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'A cette nouvelle les peuples tremblent, l\'effroi saisit les habitants de la Philistie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'alors les princes d\'Édom sont éperdus, la terreur s\'empare des héros de Moab, les habitants de Canaan s\'épouvantent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'la frayeur et l\'alarme fond sur eux, la grandeur de ton bras les rend muets comme la pierre, jusqu\'à ce que ton peuple soit passé, Éternel, jusqu\'à ce que soit passé le peuple que tu t\'es acquis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Tu les fais arriver et tu les plantes sur la montagne qui est ton héritage, dans le séjour dont tu as fait ta résidence, Éternel, dans le sanctuaire, Seigneur, qu\'ont préparé tes mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'L\'Éternel est roi, éternellement, à jamais;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'car les coursiers de Pharaon avec ses chars et sa cavalerie s\'avancèrent dans la mer, et l\'Éternel ramena sur eux les flots de la mer, et les enfants d\'Israël passèrent à sec au milieu de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Alors Marie, la prophétesse, sœur d\'Aaron, prit dans sa main le tambourin, et toutes les femmes sortirent à sa suite avec des tambourins et en formant des chœurs. Et Marie leur répondait:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Chantez l\'Éternel, car Il a montré sa grandeur, Il a jeté dans la mer les chevaux et les chars.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Et Moïse fit partir les Israélites de la Mer aux algues, et ils s\'avancèrent dans le désert de Sur et ils marchèrent trois journées dans le désert sans trouver d\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Et ils parvinrent à Mara, mais ils ne purent boire les eaux de Mara, car elles étaient amères; c\'est pourquoi on appelle ce lieu Mara (amertume).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Alors le peuple murmura contre Moïse et dit: Que boirons-nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Et il éleva ses cris vers l\'Éternel, et l\'Éternel lui indiqua un bois qu\'il jeta dans l\'eau; et l\'eau devint douce. Là Il leur prescrivit des statuts et des lois, et là Il les mit à l\'épreuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Et Il dit: Si tu es docile à la voix de l\'Éternel, ton Dieu, et que tu fasses ce qui est droit à ses yeux, et que tu écoutes ses ordres, et que tu observes tous ses statuts, je ne te ferai subir aucune des maladies que j\'ai fait subir aux Égyptiens; car je suis l\'Éternel, ton médecin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Et ils arrivèrent à Elim, et là il y avait douze fontaines et soixante-dix palmiers, et ils y campèrent près des eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Et ils partirent d\'Elim, et toute l\'assemblée des enfants d\'Israël arriva au désert de Sin qui est entre Elim et Sinaï, le quinzième jour du second mois depuis leur sortie du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Et toute l\'assemblée des enfants d\'Israël murmura contre Moïse et Aaron dans le désert,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'et les enfants d\'Israël leur dirent: Que n\'avons-nous péri sous la main de l\'Éternel au pays d\'Egypte, quand nous étions assis à côté des marmites de viande, quand nous mangions du pain à rassasiement? car vous nous avez entraînés dans ce désert pour faire mourir de faim toute cette assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Alors l\'Éternel dit à Moïse: Voici, je vais vous envoyer du ciel une pluie de pain, et le peuple sortira et en recueillera chaque jour l\'ordinaire du jour, afin que j\'éprouve s\'il suit ou non ma loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Et le sixième jour ils serreront ce qu\'ils rapporteront et il y aura le double de la récolte quotidienne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Et Moïse et Aaron dirent à tous les enfants d\'Israël: Ce soir vous comprendrez que c\'est l\'Éternel qui vous a fait sortir du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Et au matin vous verrez la gloire de l\'Éternel parce qu\'il a entendu vos murmures contre l\'Éternel; car que sommes-nous pour que vous murmuriez contre nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Et Moïse dit: En effet, ce soir l\'Éternel vous fournira de la chair pour nourriture et au matin du pain à rassasiement, l\'Éternel qui a entendu les murmures que vous élevez contre lui; car nous-mêmes que sommes-nous? C\'est non pas à nous que s\'adressent vos murmures, mais à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Et Moïse dit à Aaron: Dis à toute l\'assemblée des enfants d\'Israël: Présentez-vous devant l\'Éternel, car Il a entendu vos murmures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Et comme Aaron parlait à toute l\'assemblée des enfants d\'Israël, ils se tournèrent du côté du désert, et voici la gloire de l\'Éternel apparut dans la nue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Et l\'Éternel parlant à Moïse dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'J\'ai entendu les murmures des enfants d\'Israël; parle-leur en ces termes: Dans la soirée vous mangerez de la chair, et au matin vous vous rassasierez de pain, et vous comprendrez que je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Et le soir il surgit un vol de cailles qui couvrirent le camp, et le matin il y eut une couche de rosée autour du camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Et quand la couche de rosée eut disparu, il y avait à la superficie du désert une matière menue, en forme d\'écailles, menue comme le givre qui couvre la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Et à cette vue les enfants d\'Israël se dirent l\'un à l\'autre: Qu\'est-ce? Car ils ne savaient pas ce que c\'était. Et Moïse leur dit: C\'est le pain que l\'Éternel vous donne pour nourriture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'C\'est à ce propos que l\'Éternel vous a donné cet ordre: Recueillez-en chacun à proportion de ce qu\'il mange, un homer par tête, selon le nombre de vos gens; et prenez-en chacun pour les personnes de sa tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Et ainsi firent les enfants d\'Israël; ils ramassèrent les uns plus, les autres moins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Et ils mesurèrent au homer de sorte que celui qui avait beaucoup ramassé, n\'eut pas trop, et celui qui avait peu ramassé, pas trop peu; chacun prit à proportion de ce qu\'il mangeait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Et Moïse leur dit: Que personne n\'en garde des restes pour le lendemain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Mais ils n\'écoutèrent point Moïse, et il y en eut qui gardèrent des restes jusqu\'au lendemain; et des vers y parurent, puis une odeur fétide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Et Moïse se courrouça contre eux. Et tous les matins ils faisaient cette récolte proportionnée à ce que chacun mangeait; car le soleil devenu chaud, cela fondait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Et le sixième jour ils ramassèrent une double quantité de cet aliment, deux homers par personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Alors tous les princes de l\'assemblée vinrent en informer Moïse. Et il leur dit: C\'est ce qu\'a prononcé l\'Éternel: C\'est demain le jour du repos, le saint sabbat de l\'Éternel: boulangez ce que vous avez à boulanger, et cuisez ce que vous avez à cuire, et mettez tout le surplus en réserve jusqu\'au lendemain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Et ils le gardèrent jusqu\'au lendemain conformément à l\'ordre de Moïse, et il n\'y eut ni fétidité, ni vers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Et Moïse dit: Mangez-le aujourd\'hui, car ce jour est le sabbat de l\'Éternel; aujourd\'hui vous n\'en trouverez point dans la campagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Six jours vous ferez votre récolte, mais le septième jour est le sabbat, et il n\'y aura rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Et il arriva le septième jour que quelques-uns du peuple sortirent pour faire la récolte, et ne trouvèrent rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Alors l\'Éternel dit à Moïse: Jusques à quand refuserez-vous d\'observer mes ordres et mes lois?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Voyez, puisque l\'Éternel vous accorde le jour du repos, Il vous accorde aussi au sixième jour la ration de deux jours. Restez donc chacun en place, que personne ne sorte de chez lui le septième jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Le peuple chôma donc le septième jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Et la maison d\'Israël donna à cet aliment le nom de manne; or elle était comme la graine blanche de coriandre, et avait la douceur de gâteaux de miel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Et Moïse dit: Voici l\'ordre qu\'a donné l\'Éternel: Qu\'un homer plein en soit conservé pour vos générations futures, afin qu\'elles voient l\'aliment dont je vous nourris dans le désert, quand je vous retirai du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Et Moïse dit à Aaron: Prends un vase et y mets un homer plein de manne, et dépose-le devant l\'Éternel où il sera conservé pour vos races futures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Ainsi que l\'Éternel l\'ordonnait à Moïse, Aaron le déposa devant le Témoignage pour être conservé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Cependant les enfants d\'Israël mangèrent de la manne pendant quarante ans, jusqu\'à leur arrivée dans le pays habité; ils mangèrent la manne jusqu\'à leur arrivée à la frontière du pays de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Or le homer est la dixième partie de l\'épha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Et toute l\'assemblée des enfants d\'Israël partit du désert de Sin, faisant leurs stations selon l\'ordre de l\'Éternel, et ils vinrent camper à Raphidim; et il n\'y avait point d\'eau à boire pour le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Alors le peuple querella Moïse et dit: Donnez -nous de l\'eau à boire! Et Moïse leur dit: Pourquoi me querellez-vous? Pourquoi tentez-vous l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Et là le peuple avait soif d\'eau et murmurait contre Moïse et disait: Pourquoi nous as-tu amenés ici de l\'Egypte pour me faire mourir, moi et mes fils et mes troupeaux, de soif!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Alors Moïse éleva ses cris vers l\'Éternel et dit: Comment m\'y prendrai-je avec ce peuple? peu s\'en faut qu\'on ne me lapide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Et l\'Éternel dit à Moïse: Passe devant le peuple, et prends avec toi des Anciens d\'Israël, et prends en ta main le bâton dont tu as frappé le Nil, puis va.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Voici, je me tiendrai devant toi là sur un rocher d\'Horeb, et tu frapperas le rocher, et il en sortira de l\'eau, et le peuple boira. Et c\'est ce que Moïse exécuta en présence des Anciens d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Et l\'on donna à ce lieu le nom de Massa et Mériba (tentation et querelle), à cause de la querelle faite par les enfants d\'Israël, et parce qu\'ils avaient tenté l\'Éternel en disant: L\'Éternel est-Il ou non au milieu de nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Et Amalek vint attaquer Israël à Raphidim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Alors Moïse dit à Josué: Choisis-nous des hommes, et pars et combats Amalek; demain je me tiendrai sur le sommet de la colline, le bâton de Dieu à la main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Et Josué se conforma à l\'ordre que lui donnait Moïse de combattre Amalek. Et Moïse, Aaron et Hur montèrent au sommet de la colline.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Et il arrivait que quand Moïse avait la main élevée, Israël l\'emportait, et que dès qu\'il baissait la main, Amalek l\'emportait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Mais les mains de Moïse se fatiguèrent; alors ils prirent une pierre qu\'ils mirent sous lui, et il s\'assit dessus, et Aaron et Hur soutinrent ses mains, l\'un par-ci, l\'autre par-là, et ainsi, ses mains tinrent ferme jusqu\'au coucher du soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Et Josué fit tomber Amalek et son peuple sous le tranchant de l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Alors l\'Éternel dit à Moïse: Écris ceci en souvenir dans le livre, et confie aux oreilles de Josué que j\'effacerai la mémoire d\'Amalek sous le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Et Moïse bâtit un autel auquel il donna le nom de Éternel ma bannière,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'et dit: La main à la bannière de l\'Éternel! guerre de l\'Éternel avec Amalek d\'âge en âge!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Et Jéthro, prêtre de Madian, beau-père de Moïse, apprit tout ce que Dieu avait fait pour Moïse et pour Israël, son peuple, en retirant Israël d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Alors Jéthro, beau-père de Moïse, prit Tsippora, femme de Moïse, après son renvoi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'et ses deux fils dont l\'un se nommait Gerson, car il avait dit: Je suis hôte dans un pays étranger;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'et le nom de l\'autre était Éliézer (Dieu est en aide), « car le Dieu de mon père me fut en aide et me déroba au glaive de Pharaon. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Jéthro donc, beau-père de Moïse, et ses fils et sa femme arrivèrent vers Moïse au désert où il campait, à la montagne de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Et il avisa Moïse: Moi, ton beau-père Jéthro, j\'arrive chez toi, ainsi que ta femme et ses deux fils avec elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Alors Moïse sortit à la rencontre de son beau-père, et il s\'inclina et l\'embrassa, et ils se demandèrent mutuellement de leurs nouvelles, puis ils entrèrent dans la tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Et Moïse fit à son beau-père le récit de tout ce que l\'Éternel avait fait à Pharaon et à l\'Egypte pour l\'amour d\'Israël, de toutes les tribulations qui leur étaient survenues en route, et dont l\'Éternel les avait délivrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Et Jéthro se réjouit de tout le bien que l\'Éternel avait fait à Israël, en le sauvant de la main des Égyptiens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Et Jéthro dit: Béni soit l\'Éternel qui vous a sauvés de la main des Égyptiens et de la main de Pharaon, qui a sauvé le peuple de la main des Égyptiens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Maintenant je reconnais que l\'Éternel est plus grand que tous les dieux, et qu\'il l\'a été par le moyen même que l\'orgueil des Égyptiens avait employé contre eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Et Jéthro, beau-père de Moïse, prit un holocauste et des victimes pour les offrir à Dieu; et Aaron et tous les Anciens d\'Israël vinrent manger le pain avec le beau-père de Moïse en la présence de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Et le lendemain Moïse siégeait pour rendre la justice au peuple, et le peuple entourait Moïse du matin au soir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Et le beau-père de Moïse voyant tout ce qu\'il avait à faire pour le peuple, dit: Quelle fonction remplis-tu là auprès du peuple? Pourquoi es-tu seul à siéger, et tout le peuple est-il à ton audience du matin au soir?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Et Moïse dit à son beau-père: C\'est que le peuple vient à moi pour consulter Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Quand ils ont une affaire, ils viennent à moi et je suis arbitre entre une partie et l\'autre, et je leur fais connaître les statuts de Dieu et ses lois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Et le beau-père de Moïse lui dit: La manière dont tu t\'y prends, n\'est pas bonne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Tu t\'épuises ainsi que ce peuple qui t\'entoure; car la chose est trop forte pour toi, tu ne saurais en venir à bout seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Or sois docile à ma voix, je vais te donner un conseil, et que Dieu soit avec toi! Sois auprès de Dieu le représentant du peuple, et porte les affaires devant Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'et enseigne-leur les statuts et les lois, et montre-leur la voie qu\'ils ont à suivre, et la conduite qu\'ils ont à tenir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Et toi cherche parmi tout le peuple des hommes capables, craignant Dieu, des hommes sûrs, ennemis de la cupidité, et prépose-les sur eux comme chefs de mille, chefs de cent, chefs de cinquante et chefs de dix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Et ils rendront la justice au peuple en tout temps, et ils porteront devant toi toutes les grandes affaires, et ils jugeront eux-mêmes les petites causes; ainsi, ils t\'allégeront le fardeau et ils le soutiendront avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Si tu t\'y prends de cette sorte et que Dieu t\'y autorise, tu pourras y tenir, et tout ce peuple aussi arrivera en bon point à sa destination.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Et Moïse fut docile à la voix de son beau-père, et fit tout ce qu\'il avait dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Et Moïse choisit des hommes capables parmi tout Israël, et les mit à la tête du peuple, comme chefs de mille, chefs de cent, chefs de cinquante, et chefs de dix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Et ils rendirent la justice au peuple en tout temps: ils portaient devant Moïse les causes difficiles, et ils jugeaient eux-mêmes les petites causes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Et Moïse prit congé de son beau-père, qui regagna son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'A la troisième nouvelle lune après leur sortie du pays d\'Egypte, ce jour-là les enfants d\'Israël entrèrent dans le désert de Sinaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Étant donc partis de Raphidim, ils arrivèrent au désert de Sinaï et campèrent dans le désert, et Israël y campa en face de la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Or Moïse était monté vers Dieu: et l\'Éternel l\'appela de la montagne et dit: Adresse ces paroles à la maison de Jacob, et cette déclaration aux enfants d\'Israël:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Vous avez vu ce que j\'ai fait à l\'Egypte, et comment je vous ai portés sur les ailes de l\'aigle et amenés vers moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Eh bien! si vous êtes dociles à ma voix et gardez mon alliance, vous serez ma propriété de préférence à tous les peuples, car toute la terre est à moi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'et vous serez pour moi un royaume de sacrificateurs et un peuple saint. Telles sont les paroles que tu adresseras aux enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Moïse vint donc et convoqua les Anciens du peuple, et il mit sous leurs yeux toutes les choses dont l\'Éternel l\'avait chargé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Et tout le peuple répondit unanimement en ces termes: Nous ferons tout ce qu\'a dit l\'Éternel. Et Moïse rapporta à l\'Éternel les paroles du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Puis l\'Éternel dit à Moïse: Voici, je viendrai à toi dans un nuage épais, afin que le peuple entende quand je parlerai avec toi, et qu\'il ait en toi une confiance éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Et Moïse exposa à l\'Éternel les paroles du peuple. Et l\'Éternel dit à Moïse: Va vers le peuple et sanctifie-les aujourd\'hui et demain; et qu\'ils lavent leurs manteaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Et qu\'ils se tiennent prêts pour le troisième jour; car le troisième jour l\'Éternel descendra à la vue de tout le peuple sur le mont de Sinaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Et tu parqueras le peuple de tous côtés, et tu diras: Prenez garde de monter à la montagne, et d\'en toucher la limite; quiconque touchera la montagne sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Nulle main ne la touchera sous peine d\'être lapidé ou passé par les armes, et pour l\'animal et pour l\'homme il y va de sa vie. Dès que la trompette sonnera, ils monteront à la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Et Moïse redescendit de la montagne vers le peuple, et il sanctifia le peuple et ils lavèrent leurs manteaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Et il dit au peuple: Soyez prêts pour le troisième jour, et abstenez-vous de femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Et le troisième jour au matin il y eut des tonnerres et des éclairs, et un nuage épais couvrait la montagne, et la trompette sonnait avec une grande force, et tout le peuple qui était dans le camp trembla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Et Moïse conduisit le peuple hors du camp à la rencontre de Dieu, et ils prirent place au pied de la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Or tout le mont de Sinaï se couvrit de fumée en face de l\'Éternel qui y descendait au milieu du feu; et la fumée s\'en élevait comme une fumée de fournaise, et toute la montagne branlait fortement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Et la trompette allait sonnant en éclats plus bruyants; Moïse parlait et Dieu lui répondait dans le tonnerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Et l\'Éternel descendit sur le mont de Sinaï, sur la cime de la montagne, et l\'Éternel appela Moïse sur la cime de la montagne et Moïse monta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Alors l\'Éternel dit à Moïse: Descends, [et somme le peuple de ne pas percer jusqu\'à l\'Éternel pour voir;] ce qui en ferait tomber un grand nombre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Que de même les prêtres qui ont accès auprès de l\'Éternel, se sanctifient, de peur que l\'Éternel n\'exerce des ravages parmi eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Et Moïse dit à l\'Éternel: Le peuple ne saurait monter à la montagne de Sinaï, car tu nous as fait cette sommation: Parque la montagne et la sanctifie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Et l\'Éternel lui dit: Va, descends, puis remonte, toi et Aaron qui t\'accompagne; mais les prêtres et le peuple ne s\'ouvriront pas un passage pour monter vers l\'Éternel, de peur qu\'il n\'exerce des ravages parmi eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Et Moïse descendit auprès du peuple, à qui il parla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Alors Dieu prononça toutes ces paroles et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Je suis l\'Éternel, ton Dieu, qui t\'ai retiré du pays d\'Egypte, de la maison de servitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Tu n\'auras point d\'autres dieux a ma face.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'tu ne te feras point d\'idoles, ni aucune image, de rien de ce qui est en haut dans les cieux, ni en bas sur la terre, et dans les eaux au-dessous de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Tu ne les adoreras point, et ne les serviras point, car moi, l\'Éternel, ton Dieu, je suis un Dieu jaloux qui punis le crime des pères sur les enfants à la troisième et quatrième génération de ceux qui me haïssent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'mais qui fais miséricorde jusqu\'à la millième génération à ceux qui m\'aiment et gardent mes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Tu ne proféreras point le nom de l\'Éternel, ton Dieu, légèrement, car l\'Éternel ne laissera pas impuni celui qui proférera son nom légèrement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Souviens-toi du jour du repos pour le sanctifier;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'six jours tu travailleras et feras toutes tes affaires;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'mais le septième jour est le jour du repos de l\'Éternel, ton Dieu, tu ne l\'emploieras à aucune affaire, ni toi, ni ton fils, ni ta fille, ni ton serviteur, ni ta servante, ni ton bétail, ni ton étranger qui est dans tes portes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Car en six jours l\'éternel a fait les cieux et la terre et la mer et tout ce qui y est, et Il s\'est reposé le septième jour; c\'est pourquoi l\'Éternel a béni le jour du repos, et l\'a consacré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Honore ton père et ta mère, afin que tes jours se prolongent au pays que l\'Éternel, ton Dieu, te donne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Tu ne seras point meurtrier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Tu ne seras point adultère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Tu ne seras point larron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Tu ne seras point faux témoin contre ton prochain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Tu ne convoiteras point la maison de ton prochain; tu ne convoiteras point la femme de ton prochain, ni son serviteur, ni sa servante, ni son bœuf, ni son âne, ni rien de ce qui est à ton prochain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Et tout le peuple fut témoin des tonnerres, et des flammes et du bruit des trompettes et de la fumée qui sortait de la montagne, et à cet aspect le peuple s\'enfuit et se tint à distance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'et il dit à Moïse: Parle-nous, toi, et nous écouterons; mais que Dieu ne nous parle pas, de peur que nous ne mourions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Alors Moïse dit au peuple: Ne vous effrayez pas! car c\'est pour vous mettre à l\'épreuve que Dieu est venu, et c\'est pour que vous ayez sa crainte devant les yeux, afin que vous ne péchiez point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Le peuple se tint donc à distance, et Moïse s\'approcha de la sombre nuée où était Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Alors l\'Éternel dit à Moïse: Ainsi parleras-tu aux enfants d\'Israël: Vous avez vu que je vous ai parlé depuis le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Vous ne vous ferez point de dieux d\'argent pour me les associer, et vous ne vous ferez point de dieux d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Tu me dresseras un autel de terre, et tu y sacrifieras tes holocaustes et tes hosties pacifiques, tes brebis et tes bœufs; partout où je mettrai la mémoire de mon nom, je viendrai à toi et te bénirai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Que si tu me dresses un autel de pierres, bâtis-le de pierres non taillées, car en faisant passer le fer sur elles, tu les profanerais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Tu ne monteras point à mon autel par des degrés, de peur que tu n\'y découvres ta nudité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Ce sont ici les lois que tu leur reproduiras:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Si tu achètes un esclave hébreu, six années il servira, et la septième il sortira libre gratuitement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'S\'il entre de sa personne seule, il sortira de sa personne seule; s\'il a une femme, sa femme sortira avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Si son maître lui donne une femme et qu\'il ait d\'elle des fils ou des filles, la femme et ses enfants seront au maître, et il sortira de sa personne seule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Mais si le serviteur dit: J\'aime mon maître, ma femme et mes fils, je ne veux pas sortir libre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'alors que son maître l\'amène devant Dieu, puis l\'approche de la porte ou du jambage, et que son maître lui perce l\'oreille avec une alène, et il restera à son service à perpétuité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Mais si quelqu\'un vend sa fille pour être servante, elle ne sortira point de la même manière que les serviteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Si elle déplaît au maître qui se l\'était destinée, il moyennera son rachat; il n\'est point autorisé à la vendre chez un peuple étranger, ce qui serait la trahir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Que s\'il l\'a destinée à son fils, il la traitera d\'après le droit des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Si en outre il en prend une autre, il ne lui retranchera rien, ni de ses aliments, ni de son habillement, ni de ses droits de femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Et s\'il ne la satisfait pas à ces trois égards, elle pourra sortir gratuitement, sans rançon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Qui portera à un homme un coup dont celui-ci mourra, sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Mais s\'il n\'y a pas eu guet-apens, et si c\'est Dieu qui l\'a fait se rencontrer sous ses coups, je te fixerai un lieu où il pourra se réfugier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Mais celui qui aura prémédité de tuer son prochain par surprise, tu l\'arracheras de mon autel même pour le mener à la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Et quiconque frappera son père et sa mère, sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Celui qui fait rapt d\'un homme et le vend ou le retient en sa puissance, sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Et qui maudira son père et sa mère sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Si des individus ont une rixe dans laquelle l\'un porte à l\'autre avec une pierre ou le poing des coups qui, sans causer sa mort, l\'étendent sur son lit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'dans le cas où celui-ci pourra se lever et sortir en s\'aidant de son bâton, celui qui aura frappé ne subira point de peine; seulement il lui paiera son séjour au lit et pourvoira à son rétablissement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Si quelqu\'un frappe son serviteur ou sa servante avec le bâton, dans le cas où ils mourraient sous ses coups, il y aura vindicte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'seulement dans le cas d\'un jour ou plusieurs de survie, la vindicte ne s\'exercera pas; car c\'est son argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Si des individus ont une rixe et portent à une femme enceinte des coups qui ont pour effet un avortement sans qu\'il y ait d\'autre dommage, ils paieront une amende telle que la leur imposera le mari de la femme, et ils s\'en acquitteront devant des arbitres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Mais, s\'il y a d\'ailleurs dommage, tu rendras vie pour vie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'œil pour œil, dent pour dent, main pour main, pied pour pied,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'brûlure pour brûlure, plaie pour plaie, contusion pour contusion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Et si quelqu\'un frappe son serviteur ou sa servante à l\'œil, et le leur fait perdre, il les affranchira, pour l\'œil qu\'ils auront perdu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Et s\'il fait sauter une dent à son serviteur ou à sa servante, il les affranchira pour la dent qu\'ils n\'ont plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Et si un bœuf heurte un homme ou une femme et que la mort s\'en suive, le bœuf sera lapidé, et on n\'en mangera pas la chair, mais le maître du bœuf ne sera point puni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Que si le bœuf était précédemment sujet à heurter, et si malgré les avertissements donnés à son maître, celui-ci ne l\'a point surveillé, et que le bœuf ait causé la mort d\'un homme ou d\'une femme, le bœuf sera lapidé et son maître aussi sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Dans le cas où une indemnité lui serait infligée, il paiera en rançon de sa vie la totalité de la somme qui lui sera imposée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Que ce soit un fils ou une fille qui ait été heurté, on lui fera l\'application de cette loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Si c\'est un serviteur ou une servante que le bœuf a heurté, trente sicles d\'argent seront payés à leur maître, et le bœuf sera lapidé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Quelqu\'un ayant ouvert un fossé ou creusé un puits, et ne l\'ayant pas recouvert, si un bœuf ou un âne y tombe,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'le propriétaire du puits paiera à leur maître l\'équivalent en argent, mais la bête morte lui reviendra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Si le bœuf de l\'un frappe de la corne le bœuf de l\'autre à le tuer, ils vendront le bœuf vivant et s\'en partageront le prix, comme ils se partageront aussi le bœuf mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Ou s\'il est notoire que précédemment ce bœuf était sujet à frapper et que son maître ne l\'a pas surveillé, ce maître rendra bœuf pour bœuf, et le bœuf mort lui reviendra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Lorsque quelqu\'un aura volé un bœuf ou un mouton, soit pour l\'égorger, soit pour le vendre, il restituera cinq bœufs pour un bœuf et quatre moutons pour un mouton.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Si le voleur est surpris faisant effraction et qu\'il reçoive des coups dont il meure, il n\'y a pas meurtre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'mais si le soleil l\'a éclairé, il y aura meurtre. Il restituera; s\'il n\'a rien, il sera vendu pour la valeur de son vol.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Si la chose volée, bœuf, âne ou mouton vivant, est trouvée entre ses mains, il restituera le double.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Lorsque quelqu\'un aura fait brouter un champ ou une vigne par son bétail qu\'il aura introduit et laissé pâturer dans le champ d\'autrui, il donnera pour le dommage le meilleur produit de son champ et de sa vigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Lorsque du feu échappé atteindra des épines et qu\'une pile de gerbes, où une moisson, ou une plantation en sera ravagée, le dommage sera réparé par celui qui a été l\'occasion de l\'incendie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Lorsque quelqu\'un aura commis de l\'argent ou de la vaisselle à la garde de son prochain de la maison duquel ce dépôt sera enlevé, si le voleur est découvert, il restituera le double.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Si le voleur ne se découvre pas, le maître de la maison paraîtra devant Dieu pour dire s\'il n\'a point mis la main sur la propriété de son prochain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Pour tous les cas de fraude au sujet d\'un bœuf, d\'un âne, d\'un mouton, d\'un manteau et de tout objet perdu, duquel on dit: ce l\'est, les deux parties porteront l\'affaire devant Dieu; celui que Dieu condamnera restituera le double à son prochain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Lorsque quelqu\'un aura commis à la garde de son prochain un âne ou un bœuf ou une brebis ou une pièce de bétail quelconque, qui périsse, se fracture ou soit enlevée en l\'absence de témoins,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'le serment à l\'Éternel interviendra entre les deux parties pour constater s\'il n\'a point mis la main sur la propriété de son prochain, et le propriétaire l\'acceptera et le [dépositaire] ne paiera rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Que si l\'animal a été volé dans la maison du dépositaire, le propriétaire sera dédommagé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 's\'il a été déchiré, il sera produit en preuve; ce qui a été déchiré ne sera point restitué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Lorsque quelqu\'un aura emprunté de son prochain [une bête de somme], si elle se fracture ou périt n\'étant pas accompagnée de son maître, c\'est le cas de dédommager.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Si son maître l\'accompagne, il n\'y a pas lieu de dédommager; si elle a été prise à louage, cela rentre dans son prix de louage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Si un homme séduit une vierge qui n\'est pas fiancée, et qu\'il habite avec elle, il la prendra pour femme en payant le prix de l\'épouse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Si le père refuse de la lui accorder, il paiera un prix égal au prix des vierges [qu\'on marie].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Tu ne laisseras point la vie à la magicienne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Quiconque se livre à la bestialité sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Celui qui sacrifie aux dieux et non à l\'Éternel seul, sera frappé d\'anathème.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Tu ne maltraiteras point l\'étranger et ne l\'opprimeras point; car vous fûtes étrangers dans le pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Tu n\'affligeras point la veuve et l\'orphelin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Si tu les affliges, sache que s\'ils élèvent vers moi leurs cris, j\'écouterai, écouterai leurs cris,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'et ma colère s\'allumera, et je vous ferai périr par l\'épée, et vos femmes deviendront veuves et vos fils orphelins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Si tu prêtes de l\'argent à mon peuple, au pauvre qui vit avec toi, ne sois point pour lui un usurier; tu ne lui imposeras point d\'intérêts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Si tu prends comme gage le manteau de ton prochain, tu le lui rendras avant le coucher du soleil;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'car c\'est sa seule couverture, le manteau qu\'il a pour son corps; sur quoi coucherait-il? Que s\'il élève vers moi ses cris, j\'écouterai, car je suis miséricordieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Tu ne parleras point de Dieu avec mépris, ni avec des malédictions d\'un prince de ton peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Offre sans délai les prémices de ton aire, et de la liqueur de ton pressoir. Tu me donneras tes fils premiers-nés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Ainsi tu feras pour ton gros bétail et ton menu bétail; sept jours il restera auprès de sa mère, et le huitième tu m\'en feras don.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Et soyez pour moi des hommes saints; et ne mangez point la chair déchirée dans les champs; c\'est aux chiens que vous la jetterez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Tu ne répéteras pas de faux bruits; tu ne donneras point la main à l\'impie pour être témoin inique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Tu ne suivras point la foule dans le mal, et dans un procès tu ne déposeras point en déviant à la suite de la foule pour faire fléchir [la loi].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Pour le pauvre même tu ne seras point partial, quand il est en cause.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Si tu rencontres le bœuf de ton ennemi ou son âne égaré, ramène-le-lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Si tu vois l\'âne de ton ennemi succombant sous le faix et que tu répugnes à l\'en dégager, joins-toi à lui pour le dégager.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Ne fais pas plier le droit de ton indigent quand il plaide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Tiens-toi loin d\'une cause inique, et ne sois le meurtrier ni de l\'innocent ni du juste; car je n\'absous point l\'impie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'N\'accepte pas de présent; car les présents aveuglent les clairvoyants et ruinent la cause des justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'N\'opprime pas l\'étranger, car vous savez ce que l\'étranger a dans l\'âme, ayant été vous-mêmes étrangers dans le pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Six années tu ensemenceras ton sol, et en récolteras le produit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'mais la septième, tu le laisseras en repos et en jachère, afin que les indigents de ton peuple en jouissent, et ce qu\'ils laisseront servira de pâturage aux bêtes des champs. Ainsi feras-tu avec tes vignes et tes olivaies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Pendant six jours tu vaqueras à tes affaires, et le septième, tu chômeras afin que ton bœuf et ton âne aient du relâche et que le fils de ta servante et l\'étranger puissent respirer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Et vous prendrez, garde à tout ce que je vous ai dit, et vous ne mentionnerez pas le nom d\'autres dieux, qu\'on ne l\'entende pas sortir de votre bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Trois fois dans l\'année tu célébreras une fête en mon honneur:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Tu observeras la fête des azymes; sept jours tu mangeras des pains non levés, ainsi que je te l\'ai commandé, à l\'époque du mois des épis; car c\'est alors que tu es sorti d\'Egypte; et tu ne te présenteras pas devant moi les mains vides;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'et la fête de la moisson, des prémices de tes cultures, de ce que tu auras semé dans les champs; et la fête de la rentrée des fruits vers la fin de l\'année, quand tu fais rentrer des champs tes récoltes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Trois fois l\'année tous tes mâles se présenteront devant le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Tu n\'offriras pas sur du levain le sacrifice du sang de ma victime; et la graisse de ma fête ne sera pas gardée jusqu\'au lendemain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Tu apporteras à la maison de l\'Éternel, ton Dieu, la fleur des prémices de ton sol. Ne fais point cuire un chevreau au lait de sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Voici, j\'envoie un ange devant toi pour te garder en chemin et t\'amener au lieu que j\'ai préparé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'prends garde à toi devant lui et écoute sa voix, et ne lui résiste pas, car il ne pardonnera point vos désobéissances, parce que mon nom est en lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Car si tu es docile à sa voix, et si tu fais tout ce que je prescris, je serai l\'ennemi de tes ennemis et l\'adversaire de tes adversaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Car mon ange te précédera et t\'introduira chez les Amoréens et les Héthiens et les Phérisiens et les Cananéens et les Hévites et les Jébusites, et je les exterminerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Tu n\'adoreras point leurs dieux et ne te laisseras point aller à les servir, tu n\'imiteras pas non plus leur conduite, mais tu les détruiras et mettras leurs statues en pièces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Et vous servirez l\'Éternel, votre Dieu, qui alors bénira ton pain et ton eau, et je bannirai les maladies du milieu de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Dans ton pays il n\'y aura ni femme qui enfante avant terme, ni épouse stérile, et je te laisserai accomplir le nombre de tes jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Je te ferai précéder par ma terreur, et je troublerai tous les peuples chez qui tu pénétreras, et je te montrerai le dos de tes ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Et je te ferai précéder par les frelons qui chasseront devant toi les Hévites et les Cananéens et les Héthiens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Je ne les chasserai pas devant toi en une seule année, de peur que le pays ne devienne inculte et que tu n\'aies contre toi les bêtes des champs multipliées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Je les chasserai peu à peu devant toi jusqu\'à ce que tu te sois propagé et rendu maître du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Et je fixe tes limites de la Mer aux algues à la mer de Philistie, et du désert au Fleuve, car je veux livrer entre vos mains les habitants du pays, et tu les chasseras devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Tu ne leur accorderas point d\'alliance, ni à eux ni à leurs dieux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'ils ne demeureront point dans ton pays de peur qu\'ils ne te portent à pécher contre moi, car le culte que tu rendrais à leurs dieux te tournerait à piège.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Et Il dit à Moïse: Monte vers l\'Éternel, toi et Aaron, Nadab et Abihu et soixante-dix des Anciens d\'Israël, et adorez à distance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Et que Moïse s\'approche seul de l\'Éternel, mais qu\'eux ne s\'approchent pas et que le peuple ne monte pas avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Moïse vint donc exposer au peuple toutes les paroles de l\'Éternel et toutes les lois, et d\'une voix tout le peuple répondit et dit: Nous exécuterons tous les ordres qu\'a prescrits l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Alors Moïse mit par écrit toutes les paroles de l\'Éternel; puis, s\'étant levé le matin, il dressa un autel au pied de la montagne et douze cippes pour les douze tribus d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Et il délégua les jeunes hommes des enfants d\'Israël pour offrir des holocaustes et sacrifier à l\'Éternel des taureaux en hosties pacifiques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Et Moïse prit une moitié du sang qu\'il mit dans des bassins, et avec l\'autre moitié il aspergea l\'autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Et il prit l\'acte de l\'alliance et le lut aux oreilles du peuple, et ils dirent: Tout ce qu\'a prononcé l\'Éternel, nous le ferons et nous obéirons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Et Moïse prit le sang et en aspergea le peuple, et il dit: Voici le sang de l\'alliance que l\'Éternel traite avec vous pour toutes ces lois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Alors Moïse monta, ainsi que Aaron, Nadab et Abihu et soixante-dix des Anciens d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Et ils virent le Dieu d\'Israël, et sous ses pieds c\'était comme un travail de saphir transparent et pareil au ciel même en pureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Mais Il ne porta pas la main sur les nobles d\'Israël, et ils eurent la vue de Dieu; et ils mangèrent et burent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Et l\'Éternel dit à Moïse: Monte vers moi sur la montagne et tiens-t\'y, et je te donnerai les Tables de pierre et la Loi et l\'ordonnance que j\'ai écrites, afin de les inculquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Alors Moïse se leva ainsi que Josué qui le servait, et Moïse monta sur la montagne de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Et il dit aux Anciens: Attendez-nous ici jusqu\'à notre retour auprès de vous. Voici, vous avez avec vous Aaron et Hur; si quelqu\'un a un démêlé, qu\'il s\'adresse à eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Moïse monta donc à la montagne et une nuée couvrait la montagne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'et la gloire de l\'Éternel reposait sur le mont de Sinaï qui fut pendant six jours couvert de la nuée. Et le septième jour Il appela Moïse du sein de la nuée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Et l\'aspect de la gloire de l\'Éternel était celui d\'un feu dévorant sur la cime de la montagne aux yeux des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Et Moïse pénétra dans l\'intérieur de la nuée et monta sur la montagne, et Moïse passa quarante jours et quarante nuits sur la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Alors l\'Éternel parla à Moïse en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Dis aux enfants d\'Israël qu\'ils m\'apportent des offrandes; vous accepterez pour moi une offrande de quiconque suivra le mouvement de son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Et voici les offrandes que vous recevrez d\'eux: de l\'or et de l\'argent et de l\'airain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'de l\'azur, du pourpre, du vermillon, du lin et du poil de chèvre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'et des peaux de béliers teintes en rouge et des peaux de chiens de mer et du bois d\'acacia;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'de l\'huile pour le candélabre, des aromates pour l\'huile d\'onction et l\'encens odorant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'des pierres d\'onyx et d\'autres pierreries enchâssées pour l\'éphod et le pectoral.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Et ils me feront un sanctuaire où j\'habiterai au milieu d\'eux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'ils suivront en tout point le modèle de tabernacle que je t\'ai montré, et le modèle que je t\'ai montré pour ses meubles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Et ils feront une Arche de bois d\'acacia, ayant deux coudées et demie de longueur et une coudée et demie de largeur et une coudée et demie de hauteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Et tu la plaqueras d\'or pur; elle sera plaquée à l\'intérieur et à l\'extérieur, et tu y feras une bordure d\'or qui l\'entoure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Et tu couleras quatre anneaux d\'or que tu fixeras à ses quatre angles, deux anneaux à l\'un de ses côtés, et deux anneaux à l\'autre de ses côtés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Et tu feras des barres de bois d\'acacia que tu plaqueras d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Et tu passeras les barres dans les anneaux sur les côtés de l\'Arche, pour servir au transport de l\'Arche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'les barres resteront dans les anneaux de l\'Arche dont on ne les retirera point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Et tu déposeras dans l\'Arche le Témoignage que je te remettrai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Et tu feras un couvercle d\'or pur, long de deux coudées et demie et large d\'une coudée et demie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Fais encore deux Chérubins d\'or; ils seront travaillés au tour et placés aux deux extrémités du couvercle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'et tu placeras un Chérubin à l\'un des bouts et un Chérubin à l\'autre bout, vous les fixerez au couvercle à ses deux bouts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'et les Chérubins étendront leurs ailes par-dessus, couvrant le couvercle de leurs ailes et se faisant face l\'un à l\'autre, les Chérubins auront la face tournée vers le couvercle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'et tu couvriras l\'Arche avec le couvercle, et dans l\'intérieur de l\'Arche tu déposeras le Témoignage que je te remettrai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Et c\'est de là que je conférerai avec toi, et je t\'adresserai de dessus le couvercle, d\'entre les deux Chérubins qui seront sur l\'Arche du Témoignage, tous les ordres que je te donnerai pour les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Tu feras aussi une Table de bois d\'acacia, de deux coudées de longueur, d\'une coudée de largeur et d\'une coudée et demie de hauteur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'et tu la plaqueras d\'or pur et la couronneras d\'une bordure d\'or,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'la muniras tout autour d\'un rebord d\'un empan de hauteur, auquel tu ajouteras une bordure d\'or pur tout autour;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'et tu y fixeras quatre anneaux d\'or que tu placeras aux quatre angles répondant à ses quatre pieds;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'les anneaux se trouveront à la jonction du rebord pour recevoir les barres qui serviront au transport de la Table.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Et tu feras les barres de bois d\'acacia, et les plaqueras d\'or et elles serviront au transport de la Table.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Et tu feras ses plats et ses coupes et ses calices et ses patères qui serviront aux libations, tu les feras d\'or pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Et sur la Table tu me serviras continuellement des pains de présentation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Tu feras aussi un Candélabre d\'or pur; le Candélabre avec sa lampe et sa tige sera fait au tour; il portera des calices, des boutons et des fleurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'et six tubes sortant de ses côtés, trois tubes d\'un des côtés du Candélabre et trois tubes de l\'autre côté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'il y aura trois calices taillés en amandes à l\'un des tubes avec boutons et fleurs et trois calices taillés en amandes à l\'autre tube avec boutons et fleurs, et cela pour les six tubes sortant du Candélabre');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'qui lui-même portera quatre calices taillés en amandes avec leurs boutons et leurs fleurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'et un bouton au-dessous de l\'embranchement de deux tubes qui au nombre de six sortent du Candélabre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'il portera des boutons et des tubes, le tout fait au tour et d\'or pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Et tu en feras les sept lampes qui seront placées de manière à faire que la lumière se projette droit en avant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'et les mouchettes et les cendriers d\'or pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Pour le faire avec tout cet attirail on emploiera un talent d\'or pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Et veille à suivre dans l\'exécution le modèle que je t\'ai montré sur la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Et tu formeras la Résidence de dix tentures de lin retors, d\'azur, de pourpre et de vermillon; tu les feras portant des Chérubins en brocart d\'artiste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Une tenture aura vingt-huit coudées de longueur et quatre coudées de largeur; toutes les tentures auront la même dimension.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Elles formeront des assemblages, chacun de cinq tentures assemblées l\'une avec l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Et tu ménageras des mailles d\'azur au bord de chaque tenture à l\'extrémité au point de jonction; tu feras la même opération au bord du tapis extérieur au second assemblage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Tu ménageras cinquante mailles par tenture et de même dans le second assemblage cinquante mailles à l\'extrémité d\'un tapis de sorte que les mailles correspondent l\'une avec l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Et tu feras cinquante agrafes d\'or, et lieras les tentures l\'une à l\'autre avec les agrafes, et la Résidence sera une.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Puis tu feras des tapis de poil de chèvre pour en former une tente qui protège la Résidence; tu feras onze de ces tapis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Un tapis aura trente coudées de longueur et quatre coudées de largeur par tapis; telle sera la dimension des onze tapis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Et tu assembleras cinq tapis d\'une part et six tapis d\'autre part, et tu rendoubleras le sixième tapis qui sera sur le devant de la tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Et tu ménageras cinquante mailles au bord de chaque tapis extérieur, à la jonction, et cinquante mailles au bord de chaque tapis dans le second assemblage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Et tu feras cinquante agrafes de cuivre, et tu arrêteras les agrafes dans les mailles et tu assembleras la tente pour la rendre une.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Et l\'excédant du tapis de la tente qui se trouvera pendant, le demi-tapis de surplus, restera pendant à l\'extrémité postérieure de la Résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Et le surplus restant sur la longueur du tapis de la tente, lequel sera d\'une coudée d\'un côté et d\'une coudée de l\'autre, restera pendant aux deux côtés de la Résidence pour la protéger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Et pour garantir la tente tu feras une couverture de peaux de béliers teintes en rouge et par dessus encore une couverture de peaux de chiens de mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Et tu feras de bois d\'acacia les ais pour la Résidence, qui seront placés debout,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'la longueur d\'un ais sera de dix coudées et sa largeur d\'une coudée et demie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Chaque ais aura deux tenons taillés l\'un comme l\'autre, tu les ménageras à tous les ais de la Résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Et tu feras les ais de la Résidence au nombre de vingt pour le côté sud au midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Et tu feras quarante soubassements d\'argent pour supporter vingt ais, deux soubassements par ais pour en recevoir les deux tenons,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'et pour le côté opposé de la Résidence, le côté du nord, vingt ais');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'et quarante soubassements d\'argent, deux soubassements par ais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Et pour le fond de la Résidence à l\'occident tu feras six ais,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'et pour les angles de la Résidence au côté du fond tu feras deux ais');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'qui devront être doubles dans le bas et aussi doubles dans le haut au premier anneau; tels seront-ils les deux, et ils seront aux deux angles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'il y aura ainsi huit ais et leurs soubassements d\'argent, seize soubassements, deux soubassements sous un ais, et deux soubassements sous l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Et tu feras des traverses de bois d\'acacia, cinq pour les ais de l\'un des côtés de la Résidence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'et cinq traverses pour les ais du second côté de la Résidence, et cinq traverses pour les ais du côté de la Résidence qui forme le fond à l\'occident,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'et la traverse médiale au milieu des ais qu\'elle traversera d\'une extrémité à l\'autre extrémité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Tu plaqueras d\'or les ais, et tu feras d\'or leurs anneaux destinés à recevoir les traverses que tu plaqueras d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Elève ainsi la Résidence d\'après le modèle que je t\'ai montré sur la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Et tu feras un Rideau d\'azur, de pourpre et de vermillon et de lin retors; ce sera un ouvrage de l\'art du tisseur avec Chérubins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Tu le tendras sur quatre colonnes d\'acacia qui seront plaquées d\'or, dont les clous seront d\'or et qui poseront sur quatre soubassements d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Tu placeras le Rideau sous les agrafes des [tentures] et tu introduiras là en dedans du Rideau l\'Arche du Témoignage de sorte que le Rideau vous fasse la séparation entre le Lieu-Saint et le Lieu-très-Saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Et tu mettras le couvercle sur l\'Arche dans le Lieu-très-Saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Et tu dresseras la Table en dehors du Rideau, et le Candélabre vis-à-vis de la Table au côté sud de la Résidence, tandis que tu placeras la Table au côté nord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Et tu feras une draperie pour l\'entrée de la Tente; elle sera d\'azur, de pourpre, de vermillon et de lin retors et en brocart.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Et pour porter la draperie tu feras cinq colonnes d\'acacia que tu plaqueras d\'or, dont tu feras les clous d\'or et pour lesquelles tu couleras cinq soubassements d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Et tu feras l\'Autel en bois d\'acacia; il aura cinq coudées de longueur et cinq coudées de largeur; l\'Autel sera carré, et de trois coudées en hauteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Et tu feras ses cornes à ses quatre angles d\'où elles sortiront, et tu le plaqueras d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Et tu feras ses vases destinés à recevoir les cendres, et ses pelles et ses patères et ses fourchettes et ses brasiers; tu emploieras l\'airain pour tous ces ustensiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Et tu feras un treillis en réseau d\'airain, et tu fixeras au réseau d\'airain quatre anneaux d\'airain, à ses quatre coins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Et tu le placeras au-dessous de la corniche de l\'Autel en bas, de sorte que le réseau s\'élève jusqu\'à la moitié de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Tu feras aussi des barres pour l\'Autel, des barres d\'acacia que tu plaqueras d\'airain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'et l\'on passera les barres dans les anneaux, de sorte que les barres se trouvent aux deux côtés de l\'autel, quand on le transportera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Il sera creux et formé d\'ais; et tel qu\'il t\'a été montré sur la montagne, tel on le fera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Tu disposeras aussi le Parvis de la Résidence: au côté sud, du midi, pour former le Parvis, on tendra sur une longueur de cent coudées des toiles de lin retors, à l\'un des côtés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'au moyen de vingt colonnes fixées sur vingt soubassements d\'airain; les crochets des colonnes et leurs tringles seront d\'argent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'de même pour le côté du nord en longueur il y aura des toiles longues de cent coudées, et des colonnes au nombre de vingt avec leurs vingt soubassements d\'airain, leurs crochets et leurs tringles d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Et au côté de l\'occident, qui formera la largeur du Parvis, il y aura des toiles de cinquante coudées avec leurs colonnes au nombre de dix, et leurs soubassements au nombre de dix;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'et la largeur du Parvis du côté de l\'est, à l\'orient, sera aussi de cinquante coudées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'on y tendra d\'une part quinze coudées de toiles soutenues par trois colonnes fixées sur trois soubassements,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'et d\'autre part quinze coudées de toiles soutenues par trois colonnes fixées sur trois soubassements;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'et à la porte du Parvis il y aura un rideau de vingt coudées fait d\'azur, de pourpre et de vermillon et de lin retors, et en brocart, avec ses quatre colonnes et leurs quatre soubassements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Toutes les colonnes du pourtour du Parvis seront munies de tringles d\'argent; les crochets seront d\'argent et les soubassements d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Que la longueur du Parvis soit de cent coudées et sa largeur de cinquante contre cinquante, et sa hauteur de cinq coudées, que les toiles soient de lin retors et les soubassements d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Que tous les ustensiles employés à tout genre de service dans la Résidence, et tous les clous, et tous les clous du Parvis soient d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Et tu ordonneras aux enfants d\'Israël de t\'apporter de l\'huile d\'olive pure, d\'olives triturées, pour le Candélabre, afin d\'y entretenir les lampes perpétuellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'C\'est dans la Tente du Rendez-vous en deçà du Rideau qui voile le Témoignage que Aaron et ses fils la prépareront du soir au matin en la présence de l\'Éternel. C\'est une prestation perpétuelle payable par les enfants d\'Israël dans tous leurs âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Du milieu des enfants d\'Israël fais avancer vers toi Aaron, ton frère, et ses fils avec lui, pour me les attacher comme Prêtres, Aaron, Nadab et Abihu, Eléazar et Ithamar, fils d\'Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Et tu feras pour Aaron, ton frère, des vêtements sacrés qui soient un costume et une parure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Et tu t\'adresseras à tous les experts que j\'ai remplis d\'un esprit de sagesse pour faire les habits d\'Aaron qui doit m\'être consacré et me servir dans le sacerdoce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Et voici les habits qu\'ils ont à faire: un Pectoral et un Ephod et une Robe et une Tunique d\'un tissu de mailles et un Turban et une Ceinture; et ils feront des vêtements sacrés pour Aaron, ton frère, et ses fils, qui me serviront dans le sacerdoce;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'et qu\'ils y emploient l\'or, l\'azur, le pourpre, le vermillon et le lin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Et qu\'ils fassent l\'Ephod d\'or, d\'azur, de pourpre, de vermillon et de lin retors en ouvrage de tricot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Il se composera de deux pièces portant sur les épaules et jointes à leurs deux extrémités de manière à être assemblées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Et la ceinture appliquée sur l\'Ephod pour le serrer, en sortira et sera du même tissu d\'or, d\'azur, de pourpre, de vermillon et de lin retors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Et tu prendras deux pierres d\'onyx où tu graveras les noms des fils d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'six de ces noms sur l\'une des pierres, et les six noms restants sur l\'autre, selon l\'ordre de leur naissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Tu emploieras l\'art du lapidaire et l\'art de graver les sceaux pour graver ces deux pierres aux noms des fils d\'Israël; tu les enchâsseras dans des chatons d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Et tu placeras les deux pierres sur les épaulettes de l\'Ephod, comme pierres qui rappelleront les enfants d\'Israël, afin que Aaron porte sur ses deux épaules leurs noms devant l\'Éternel en mémorial.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Et tu feras des chatons d\'or');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'et deux chaînettes d\'or pur que tu façonneras en cordons tressés, et tu fixeras aux chatons les chaînettes tressées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Et tu feras le Pectoral du Droit, du même travail que l\'Ephod, en ouvrage de tricot; tu y emploieras l\'or, l\'azur, le pourpre, le vermillon et le lin retors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Il sera carré, rendoublé, d\'un empan de longueur et d\'un empan de largeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Et tu l\'enchâsseras de pierreries enchâssées, de quatre rangs de pierreries; le premier rang de sardoine, de topaze et d\'émeraude;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'le second rang d\'une escarboucle, d\'un saphir et d\'un diamant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'le troisième rang d\'une opale, d\'une agate et d\'une améthyste;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'et le quatrième rang d\'un chrysolithe, d\'un onyx et d\'un jaspe; les chatons où elles seront enchâssées seront d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Et il y aura autant de pierres que de noms des fils d\'Israël, douze comme les noms; elles seront gravées comme des sceaux, portant chacune son nom correspondant aux douze tribus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Et tu fixeras au Pectoral des chaînettes d\'or pur façonnées en cordons tressés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Et tu mettras au Pectoral deux anneaux d\'or que tu placeras aux deux extrémités du Pectoral.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Et tu mettras aux deux anneaux les deux cordons d\'or aux extrémités du Pectoral.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Et les deux autres bouts des deux cordons tu les arrêteras aux deux chatons et les feras tenir aux deux épaulettes de l\'Ephod sur le devant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Fais de plus deux anneaux d\'or que tu placeras aux deux extrémités du Pectoral sur celui de ses bords qui est tourné vers l\'Ephod en dedans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Et tu feras deux anneaux d\'or que tu mettras aux deux pièces de l\'Ephod en bas sur le devant juste à leur jonction au-dessus de la ceinture de l\'Ephod.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Et l\'on attachera le Pectoral par ses anneaux aux anneaux de l\'Ephod avec un cordon d\'azur pour l\'arrêter au-dessus de la ceinture de l\'Ephod, afin que le Pectoral ne bouge pas de l\'Ephod.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Et Aaron portera les noms des fils d\'Israël, sur le Pectoral du Droit, Aaron l\'aura constamment sur la poitrine lorsqu\'il entrera dans le Sanctuaire, comme mémorial devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Et tu mettras sur le Pectoral du Droit l\'Urim et Thummim qui seront sur la poitrine d\'Aaron quand il se présentera devant l\'Éternel, et Aaron portera constamment sur sa poitrine le droit des enfants d\'Israël en présence de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Et tu feras la Robe sur laquelle porte l\'Ephod, tout entière d\'azur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Et dans son milieu elle aura son ouverture pour passer la tête, et l\'ouverture sera bordée dans son contour d\'un ourlet tissé, comme l\'ouverture d\'une cotte de mailles, afin qu\'elle ne se déchire pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Et sur sa bordure tu entremêleras des grenades d\'azur, de pourpre et de vermillon, sur sa bordure tout autour avec des clochettes d\'or entre les grenades tout autour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'une clochette d\'or puis une grenade, une clochette d\'or puis une grenade, tout le long de la bordure de la robe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Et elle servira à Aaron pour le service, afin que le son en soit entendu quand, entrant dans le Sanctuaire, il paraîtra devant l\'Éternel, et quand il sortira, pour qu\'il ne meure pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Et tu feras une plaque d\'or pur, et tu y graveras, comme on grave les sceaux: Consécration à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Et tu y mettras un cordon d\'azur pour l\'attacher au Turban; elle sera fixée sur le devant du turban.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Et elle sera au front d\'Aaron qui sera chargé de l\'iniquité des choses consacrées que les enfants d\'Israël consacreront en tout genre d\'offrandes saintes, et qu\'elle soit constamment sur son front pour les faire agréer en présence de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Et tu formeras la Tunique d\'un tissu de lin, et tu feras un Turban de lin et une Ceinture en brocart.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Et pour les fils d\'Aaron tu feras des tuniques et tu leur feras des ceintures et tu leur feras des bonnets pour costume et parure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Et tu les en revêtiras, Aaron, ton frère, et ses fils avec lui, et tu les oindras, et tu les installeras et tu les consacreras à mon service dans le sacerdoce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Et tu leur feras pour voiler leur nudité des caleçons de fil, qui iront des reins jusqu\'aux cuisses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Et Aaron et ses fils les porteront quand ils entreront dans la Tente du Rendez-vous, ou qu\'ils s\'approcheront de l\'Autel pour faire leur service dans le Sanctuaire, de peur qu\'ils ne se chargent d\'une faute et ne meurent: c\'est là une règle perpétuelle pour lui et pour sa race après lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Voici le rite du Sacre par lequel tu les engageras dans mon sacerdoce. Tu prendras un jeune taureau et deux béliers intacts et des pains azymes et des galettes azymes pétries dans l\'huile,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'et des oublies azymes recouvertes d\'huile; tu les feras de fleur de farine de froment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Puis tu les mettras dans une corbeille et tu les offriras dans la corbeille en même temps que le jeune taureau et les deux béliers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Alors tu amèneras Aaron et ses fils à l\'entrée de la Tente du Rendez-vous et tu les laveras avec de l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Et prenant les vêtements tu revêtiras Aaron de la tunique et de la Robe, de l\'Ephod et du Pectoral, et le ceindras de la Ceinture de l\'Ephod;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'et tu poseras le Turban sur sa tête, et appliqueras au Turban le diadème de consécration.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Puis tu prendras l\'huile d\'onction que tu répandras sur sa tête pour lui conférer l\'onction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Tu feras aussi approcher ses fils, et tu les revêtiras de tuniques;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'et tu les ceindras d\'une ceinture, Aaron et ses fils, et tu leur attacheras les bonnets. Et le sacerdoce sera leur attribution perpétuelle; installe donc Aaron et ses fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Et tu amèneras le taureau devant la Tente du Rendez-vous, et Aaron et ses fils imposeront leurs mains sur la tête du taureau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'et tu égorgeras le taureau devant l\'Éternel à l\'entrée de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Puis tu prendras du sang du taureau, et avec le doigt tu en enduiras les cornes de l\'Autel, et tu répandras tout le reste au pied de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Et tu détacheras toute la graisse qui couvre les intestins et le grand lobe attenant, au foie et les deux reins et la graisse qui les enveloppe, et c\'est ce que tu feras fumer sur l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Mais tu brûleras au feu en dehors du camp la chair, la peau et la fiente du taureau; il est une victime d\'expiation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Ensuite tu prendras l\'un des béliers, et Aaron et ses fils imposeront leurs mains sur la tête du bélier;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'et tu égorgeras le bélier, puis prenant son sang tu en arroseras le tour de l\'Autel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'et tu découperas le bélier en quartiers, et tu laveras ses intestins et ses jambes que tu placeras sur ses quartiers et sur sa tête;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'et tu feras fumer le bélier en entier sur l\'Autel; c\'est un holocauste fait à l\'Éternel, un parfum agréable; c\'est une victime brûlée pour l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'De même tu prendras l\'autre bélier, et Aaron et ses fils imposeront leurs mains sur la tête du bélier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'et tu égorgeras le bélier; puis ayant pris de son sang tu en mettras au bout de l\'oreille droite d\'Aaron et au bout de l\'oreille droite de ses fils et au pouce droit de leurs mains et au grand orteil de leur pied droit et tu en répandras sur tout le tour de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Et tu prendras du sang sur l\'Autel et de l\'huile d\'onction et tu en aspergeras Aaron et ses vêtements, et ses fils et les vêtements de ses fils avec lui, le consacrant ainsi lui et ses vêtements et ses fils et les vêtements de ses fils avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Après cela détache du bélier la graisse et la queue plate et la graisse qui enveloppe les intestins, et le grand lobe attenant au foie et les deux reins et la graisse qui les recouvre et l\'éclanche droite (car c\'est le bélier d\'installation),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'et prends un pain et une galette à l\'huile et une oublie dans la corbeille des azymes servis devant l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'et mets le tout dans les mains d\'Aaron et dans les mains de ses fils, et balance-le par agitation devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Et l\'ayant retiré de leurs mains tu le feras fumer à l\'Autel sur l\'holocauste en parfum agréable à l\'Éternel; c\'est une offrande brûlée pour l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Puis tu détacheras la poitrine du bélier de l\'installation d\'Aaron et tu la balanceras par agitation devant l\'Éternel, et tu l\'auras pour ta part.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Consacre ainsi la poitrine balancée par agitation et l\'éclanche présentée par élévation et détachée du bélier d\'installation, qui auront été balancées et élevées, aussi bien de celui d\'Aaron que de celui de ses fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Et cela deviendra une prestation perpétuelle des enfants d\'Israël en faveur d\'Aaron et de ses fils, car c\'est une élévation; et les enfants d\'Israël prélèveront une élévation sur leurs sacrifices pacifiques, leur élévation présentée à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Et les vêtements sacrés d\'Aaron passeront à ses fils après lui, et ils les mettront pour recevoir l\'onction et être installés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Ils seront portés sept jours par celui de ses fils qui lui succédera dans le sacerdoce et paraîtra dans la Tente du Rendez-vous pour officier au Sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Et tu prendras le bélier d\'installation, et en cuiras la chair en lieu saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Et ce sera à l\'entrée de la Tente du Rendez-vous que Aaron et ses fils mangeront la chair du bélier et le pain contenu dans la corbeille,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'mangeant ainsi ce avec quoi aura été faite pour eux l\'expiation qui les préparera à être installés et consacrés; mais qu\'aucune personne étrangère n\'en mange, car ce sont choses sacrées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Que s\'il reste de la chair d\'installation et du pain jusqu\'au matin, tu brûleras ce reste au feu; il ne sera point mangé, car c\'est chose sacrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Et tu suivras à l\'égard d\'Aaron et de ses fils tous ces ordres que je t\'ai donnés; tu emploieras sept jours à leur installation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Et par jour pour les expiations tu offriras un taureau en sacrifice pour le péché, et tu purgeras de péché l\'Autel par les expiations que tu y feras et tu l\'oindras pour le consacrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Tu emploieras sept jours aux expiations à faire sur l\'Autel, et à sa consécration, afin qu\'il soit très-saint; quiconque touchera l\'Autel devra être consacré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Et voici ce que tu offriras sur l\'Autel: deux agneaux d\'un an par jour constamment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Tu offriras l\'un des agneaux le matin et l\'autre agneau dans la soirée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'et par agneau un décime de fleur de farine mêlé avec le quart d\'un hin d\'huile d\'olives triturées, et une libation d\'un quart de hin de vin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Et tu offriras l\'autre agneau dans la soirée en y ajoutant la même oblation et la même libation que le matin, comme parfum agréable et victime brûlée pour l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Tel est l\'holocauste perpétuel pour vos générations à offrir devant l\'entrée de la Tente du Rendez-vous devant l\'Éternel, où je me rencontrerai avec vous pour t\'y parler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Car je m\'y rencontrerai avec les enfants d\'Israël, et ma gloire rendra ce lieu saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Et je consacre la Tente du Rendez-vous et l\'Autel; et je consacrerai Aaron et ses fils pour me servir dans le sacerdoce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Et je résiderai au milieu des enfants d\'Israël, et je serai leur Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'et ils reconnaîtront que je suis l\'Éternel, leur Dieu, qui les ai tirés du pays d\'Egypte pour résider au milieu d\'eux, moi, l\'Éternel, leur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Et tu feras un Autel pour faire fumer l\'encens, tu le feras de bois d\'acacia;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'il aura une coudée de longueur et une coudée de largeur, une forme carrée et deux coudées de hauteur avec des cornes qui en sortent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Et tu le plaqueras d\'or pur, et le dessus et les parois, dans toute sa superficie, de même que ses cornes, et autour tu ménageras une bordure d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Et tu y fixeras deux anneaux d\'or à ses deux côtés au-dessous de la bordure; tu les fixeras à ses deux flancs pour recevoir les barres qui serviront à le transporter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Et tu feras les barres de bois d\'acacia, et tu les plaqueras d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Et tu le placeras devant le rideau qui cache l\'Arche du Témoignage devant le Propitiatoire qui couvre le Témoignage, au lieu où je m\'abouche avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Et Aaron y fera fumer un encens d\'aromates; il le fera fumer tous les matins lorsqu\'il arrangera les lampes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'et Aaron le fera fumer aussi lorsque dans la soirée il placera les lampes: que l\'encens fume ainsi continuellement devant l\'Éternel dans vos âges à venir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Vous n\'y offrirez ni encens étranger, ni holocauste, ni oblation, et n\'y répandrez aucune libation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Une fois l\'année Aaron fera des expiations sur ses cornes avec le sang versé pour l\'expiation du péché; une fois l\'année il y fera des expiations dans vos âges à venir. Ce sera un lieu très-saint à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Et l\'Éternel adressa ces paroles à Moïse:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Lorsque dans la revue des enfants d\'Israël tu en compteras le nombre total, chacun d\'eux paiera à l\'Éternel une rançon expiatoire pour sa vie au moment de leur revue, afin qu\'une plaie ne leur soit pas infligée au moment de leur revue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Voici ce que paieront tous ceux qui passeront à la revue, un demi-sicle, monnaie du sanctuaire, le sicle de vingt géras; un demi-sicle sera le don prélevé pour l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Tout homme âgé de vingt ans et au delà qui passera à la revue paiera le don prélevé pour l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Le riche ne paiera pas plus, et le pauvre pas moins que le demi-sicle de prestation à l\'Éternel, pour la rançon expiatoire de vos vies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Et ayant reçu des enfants d\'Israël l\'argent des rançons expiatoires, tu l\'affecteras au travail de la Tente du Rendez-vous, afin que ce soit pour les enfants d\'Israël un mémorial devant l\'Éternel, une rançon expiatoire de leurs vies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Et l\'Éternel adressa ces paroles à Moïse:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Tu feras un Bassin d\'airain dont le support soit d\'airain, pour les ablutions, et tu le placeras entre la Tente du Rendez-vous et l\'Autel, et tu y mettras de l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Et Aaron et ses fils s\'y laveront les mains et les pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Lorsqu\'ils entreront dans la Tente du Rendez-vous, ils feront ces ablutions, de peur qu\'ils ne meurent, ou lorsqu\'ils s\'approcheront de l\'Autel pour officier, pour faire fumer une offrande brûlée pour l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Et ils se laveront les mains et les pieds de peur qu\'ils ne meurent, et ce sera une règle perpétuelle pour eux, pour lui et sa race dans les âges à venir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Et l\'Éternel adressa ces paroles à Moïse:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Procure-toi des meilleurs aromates, cinq cents [sicles] de myrrhe fluide, une demi-dose soit deux cent cinquante sicles de cannelle odorante et deux cent cinquante de roseau de senteur:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'et cinq cents de casse, poids du sanctuaire, et un hin d\'huile d\'olive;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'et tu en composeras l\'huile sainte de l\'onction, préparation parfumée que tu feras selon l\'art du parfumeur: telle sera l\'huile sainte de l\'onction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Et tu en oindras la Tente du Rendez-vous et l\'Arche du Témoignage');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'et la Table et tous ses ustensiles et le Candélabre et tout son attirail, et l\'Autel aux parfums');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'et l\'Autel des holocaustes et tous ses ustensiles, et le Bassin et son support,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'les consacrant ainsi afin qu\'ils soient très-saints: pour les toucher il faudra, être consacré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Tu oindras aussi Aaron et ses fils que tu consacreras pour me servir dans le sacerdoce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Et tu parleras aux enfants d\'Israël en ces termes: Telle est l\'huile sainte de l\'onction, que je me réserve pour vos âges à venir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'on n\'en répandra sur le corps d\'aucun homme, et vous n\'en composerez point de pareille aux mêmes doses: elle est sainte et doit être sacrée pour vous:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'quiconque en préparera de pareille et en donnera à un étranger sera extirpé de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Et l\'Éternel dit à Moïse: Procure-toi des aromates et du stacté, et de la blatte et du galbanum à odeur forte, et de l\'oliban pur à doses égales;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'et tu en composeras un encens odorant préparé par l\'art du parfumeur, salé, pur, saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Et tu en pileras pour en faire une poudre dont tu mettras devant le Témoignage dans la Tente du Rendez-vous où je m\'abouche avec toi: vous l\'aurez pour très-saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Et vous n\'imiterez point pour votre usage cet encens dont vous prendriez les doses: il sera pour vous une chose sacrée, réservée pour l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'L\'homme qui l\'imitera pour en respirer le parfum, sera extirpé de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Et l\'Éternel adressa ces paroles à Moïse:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Vois, j\'ai appelé nommément Betsaléel, fils de Ouri, fils de Hur, de la tribu de Juda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'et je le remplis de l\'esprit de Dieu, de sens, d\'intelligence, d\'entente et d\'industrie en tout genre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'pour concevoir des idées, pour travailler l\'or et l\'argent et l\'airain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'pour graver les pierres à enchâsser, pour ouvrager le bois et exécuter toutes sortes de travaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Et voici, je lui ai adjoint Oholiab, fils d\'Ahisamach, de la tribu de Dan, et j\'ai mis de l\'intelligence dans l\'esprit de tous ceux qui ont un esprit intelligent, afin qu\'ils exécutent tout ce que je t\'ai prescrit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'la Tente du Rendez-vous et l\'Arche du Témoignage et le Propitiatoire qui la couvre et tous les meubles de la tente,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'et la Table et ses ustensiles et le Candélabre d\'or pur et tout son attirail, et l\'Autel aux parfums');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'et l\'Autel des holocaustes et tous ses ustensiles, et le Bassin et son support, et les tissus de mailles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'et les Vêtements sacrés du prêtre Aaron et les habits de ses fils pour l\'usage du sacerdoce,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'et l\'Huile de l\'onction et l\'Encens d\'aromates pour l\'usage du Sanctuaire: qu\'ils se conforment dans l\'exécution à tous les ordres que je t\'ai donnés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Et l\'Éternel s\'adressa à Moïse en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Adresse ces paroles aux enfants d\'Israël: Observez bien mes sabbats; car ils serviront de signe entre moi et vous dans vos âges futurs pour vous faire comprendre que c\'est moi, l\'Éternel, qui vous ai consacrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Observez donc le jour du repos, car il est sacré pour vous; qui le profanera sera mis à mort; toute personne qui l\'emploiera à une affaire sera extirpée du milieu de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Six jours l\'on vaquera à ses affaires, mais au septième c\'est jour de repos consacré à l\'Éternel; quiconque fera une affaire le septième jour sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Ainsi les enfants d\'Israël garderont le sabbat en observant le jour du repos dans leurs âges futurs comme une institution éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Ce sera éternellement un signe entre moi et les enfants d\'Israël; car en six jours l\'Éternel a fait les cieux et la terre, et le septième jour Il s\'est reposé et a repris haleine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Et quand Il eut achevé de parler avec Moïse sur le mont de Sinaï, Il lui remit les Deux Tables du Témoignage, tables de pierre écrites du doigt de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Et le peuple, voyant que Moïse tardait à descendre de la montagne, se rassembla autour d\'Aaron et lui dit: Allons! fais-nous un Dieu qui marche devant nous, car nous ne savons ce qu\'est devenu ce Moïse, l\'homme qui nous a fait sortir du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Et Aaron leur dit: Enlevez les anneaux d\'or qui sont aux oreilles de vos femmes, de vos fils et de vos filles, et apportez-les-moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Et tous ils s\'ôtèrent les anneaux d\'or qu\'ils avaient aux oreilles et les apportèrent à Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Alors Aaron les ayant reçus de leurs mains, les jeta au moule dans l\'atelier et il en fit un veau de fonte; alors ils dirent: Israël, voilà ton Dieu qui t\'a tiré du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Et Aaron voyant cela dressa un autel devant lui et fit publier: Demain c\'est fête en l\'honneur de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Et à leur lever le lendemain, ils sacrifièrent des holocaustes et ils offrirent des sacrifices pacifiques; et le peuple s\'assit pour manger et boire, puis ils se mirent à danser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Alors l\'Éternel parla à Moïse: Va, descends, car il forfait ton peuple que tu as tiré du pays d\'Egypte:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'ils se sont promptement écartés de la voie que je leur ai prescrite: ils se sont fabriqué un veau de fonte et l\'ont adoré, et lui ont fait des sacrifices et ont dit: Israël, c\'est là ton Dieu qui t\'a tiré du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Et l\'Éternel dit à Moïse: Je regarde ce peuple, et voici, c\'est un peuple au col roide;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'or maintenant donc laisse-moi agir; il faut que ma colère s\'allume contre eux et que je les détruise, mais de toi je ferai une grande nation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Et Moïse chercha à apaiser l\'Éternel, son Dieu, et dit: Éternel, pourquoi ta colère s\'allumerait-elle contre ton peuple que tu as tiré du pays d\'Egypte par une grande force et d\'une main puissante?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Pourquoi les Égyptiens diraient-ils: C\'est pour leur perte qu\'il les a fait partir, afin de les tuer dans les montagnes et de les exterminer de la face de la terre? Reviens de ton courroux qui s\'enflamme, et repens-toi de la menace que tu as faite à ton peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Souviens-toi d\'Abraham, d\'Isaac et d\'Israël, tes serviteurs, auxquels tu as juré par toi-même et auxquels tu as dit: Je multiplierai votre postérité comme les étoiles du ciel, et tout ce pays que j\'ai promis, je le donnerai à vos descendants en propriété éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Alors l\'Éternel se repentit de la menace qu\'il avait dit vouloir exécuter sur son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Et Moïse se tourna et descendit de la montagne, portant à la main les Deux Tables du Témoignage, tables écrites des deux côtés; elles étaient écrites aussi bien d\'un côté que de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Et les tables étaient l\'ouvrage de Dieu, et l\'écriture était l\'écriture de Dieu gravée sur les tables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Alors Josué entendit les cris du peuple qui vociférait, et dit à Moïse: C\'est le cri de guerre dans le camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Et Moïse répondit: Ce ne sont ni les cris de gens qui chantent victoire, ni les cris de gens qui déplorent une défaite; j\'entends les voix de gens qui chantent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Et lorsqu\'il fut près du camp et qu\'il aperçut le veau et les chœurs, Moïse fut enflammé de colère et il jeta d\'entre ses mains les tables et les brisa au pied de la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Puis il prit le veau qu\'ils avaient fait et le brûla au feu, et le broya jusqu\'à le réduire en une poudre, qu\'il répandit sur l\'eau qu\'il fit boire aux enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Et Moïse dit à Aaron: Que t\'a fait ce peuple pour le charger d\'un grand péché?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Et Aaron dit: Que la colère de mon seigneur ne s\'allume pas! Tu connais ce peuple et sa perversité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'ils m\'ont dit: Fais-nous un Dieu qui marche à notre tête; car ce Moïse, l\'homme qui nous a fait sortir du pays d\'Egypte, nous ne savons ce qu\'il est devenu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'C\'est alors que je leur ai dit: Que tous ceux qui portent de l\'or l\'enlèvent. Et ils me l\'ont remis, et je l\'ai exposé au feu, et il en est résulté ce veau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Et lorsque Moïse vit que le peuple était sans frein, Aaron lui ayant lâché la bride, et deviendrait le jouet de ses ennemis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Moïse se plaça à la porte du camp et dit: A moi tous ceux qui sont à l\'Éternel! Et tous les fils de Lévi se réunirent auprès de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Et il leur dit: Ainsi parle l\'Éternel, Dieu d\'Israël: Mettez chacun l\'épée au côté, passez et repassez d\'une porte du camp à l\'autre porte, et tuez chacun votre frère et chacun votre ami et chacun votre prochain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Et les fils de Lévi exécutèrent l\'ordre de Moïse, et en ce jour dans le peuple il tomba environ trois mille hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Et Moïse dit: Accomplissez aujourd\'hui votre consécration à l\'Éternel, même au prix de votre fils et de votre frère, et cela pour attirer sur vous aujourd\'hui une bénédiction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Et le lendemain Moïse dit au peuple: Vous avez commis un grand péché; or je vais monter vers l\'Éternel; peut-être pourrai-je expier votre péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Moïse retourna donc auprès de l\'Éternel et dit: Hélas! ce peuple s\'est rendu coupable d\'un grand péché, et ils se sont fait un dieu d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Puisses-tu maintenant pardonner leur péché! sinon, oh! efface-moi de ton livre écrit par toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Et l\'Éternel dit à Moïse: Ce sont ceux qui ont péché contre moi que j\'effacerai de mon livre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'va maintenant et mène le peuple où je t\'ai dit: Voici, mon ange te précédera; mais au jour de mes châtiments je les châtierai de leur péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Ainsi l\'Éternel frappa le peuple pour avoir fait le veau exécuté par Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Et l\'Éternel dit à Moïse: Porte-toi d\'ici, toi et le peuple que tu as tiré du pays d\'Egypte, vers le pays que j\'ai promis par serment à Abraham et à Isaac et à Jacob en disant: Je le donnerai à ta postérité:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'et je te ferai précéder par un ange, et je chasserai les Cananéens, les Amoréens et les Héthiens et les Phérisiens et les Hévites et les Jébusites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'vers le pays découlant de lait et de miel; car je ne serai point parmi vous durant le trajet, parce que vous êtes un peuple au col roide, de peur que je ne vous consume en chemin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Et le peuple ayant entendu ce sinistre langage prit le deuil et personne ne se couvrit de ses ornements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Et l\'Éternel dit à Moïse: Dis aux enfants d\'Israël: Vous êtes un peuple au col roide; si je faisais un seul instant route avec vous, je vous détruirais. Et maintenant dépose tes ornements, et je verrai ce que j\'ai à te faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Les enfants d\'Israël se dépouillèrent donc de leurs ornements, après s\'être éloignés du mont Horeb.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Et Moïse prit la Tente et se la dressa en dehors du camp, à distance du camp; et il l\'appela Tente du Rendez-vous. Et tous ceux qui cherchaient l\'Éternel se rendaient à la Tente du Rendez-vous qui se trouvait en dehors du camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Et lorsque Moïse se rendait à la Tente, tout le peuple se levait, et chacun se tenait debout à la porte de sa propre tente, et suivait Moïse du regard jusqu\'à son arrivée à la Tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Et lorsque Moïse arrivait à la Tente, la colonne de nuée descendait et se posait à l\'entrée de la Tente, et Il s\'entretenait avec Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Et tout le peuple voyait la colonne de nuée qui se tenait à l\'entrée de la Tente, et tout le peuple se levait, et chacun se prosternait à l\'entrée de sa propre tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Et l\'Éternel parlait à Moïse face à face, comme un homme parle à son ami; puis il revenait au camp; mais Josué, fils de Nun, jeune homme qui le servait, ne quittait point l\'intérieur de la Tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Et Moïse dit à l\'Éternel: Voici, tu me dis: Mène ce peuple en avant! et tu ne me fais pas connaître qui tu veux envoyer avec moi, et cependant tu m\'as dit: Je te connais nommément, et tu as aussi trouvé grâce à mes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Eh bien! puisque j\'ai pu trouver grâce à tes yeux, daigne me faire connaître ta voie pour que je te connaisse, afin de trouver grâce à tes yeux, et considère que cette nation est ton peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Et Il dit: Tu seras accompagné de ma présence et je t\'amènerai au repos.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Et il Lui répondit: Si tu ne nous accompagnes pas de ta présence, ne nous fais point partir d\'ici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Et comment sera-t-il notoire que j\'ai trouvé grâce à tes yeux, moi et ton peuple? n\'est-ce pas si tu nous accompagnes, et si nous sommes distingués moi et ton peuple de tous les peuples qui sont sur la face de la terre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Et l\'Éternel dit à Moïse: Je ferai aussi cela même que tu viens de dire; car tu as trouvé grâce à mes yeux, et je te connais nommément.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Et Moïse reprit: Fais-moi donc contempler ta gloire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Et l\'Éternel dit: Je ferai passer toute ma beauté devant ta face et nommerai le nom de l\'Éternel devant toi; aussi bien je suis propice à qui je suis propice, et miséricordieux pour qui je suis miséricordieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Et Il dit: Tu ne saurais contempler ma face, car l\'homme ne peut me voir et vivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Et l\'Éternel dit: J\'ai près de moi un lieu: tu t\'y tiendras sur le rocher,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'et quand ma gloire passera, je te placerai dans une cavité du rocher et je t\'abriterai de ma main jusqu\'à ce que je sois passé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'puis je retirerai ma main afin que tu me voies par derrière, mais ma face n\'est pas visible.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Et l\'Éternel dit à Moïse: Taille-toi deux tables de pierre comme les premières; et j\'écrirai sur les tables les paroles qui se trouvaient sur les premières tables que tu as brisées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Et tiens-toi prêt dès le matin et monte le matin à la montagne de Sinaï, et t\'y présente à moi sur le sommet de la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Et que personne ne monte avec toi, et que personne ne se montre sur toute la montagne, et que ni menu ni gros bétail ne pâture du côté de cette montagne-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Alors Moïse tailla deux tables de pierre comme les premières, et il se leva le matin et monta à la montagne de Sinaï selon l\'ordre qu\'il avait reçu de l\'Éternel, et il prit dans sa main les deux tables de pierre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Alors l\'Éternel descendit dans la nue et s\'y rencontra avec lui, et Il prononça le nom de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Et l\'Éternel passa devant lui et proclama « l\'Éternel, l\'Éternel, Dieu miséricordieux et clément, patient, et riche en amour et en fidélité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'qui conserve son amour jusqu\'à la millième génération, qui pardonne l\'iniquité, la désobéissance et le péché, mais qui ne laisse pas toujours impuni, faisant tomber la peine des pères sur les enfants et les enfants des enfants jusqu\'à la troisième et à la quatrième génération. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Alors Moïse aussitôt se prosterna contre terre et adora');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'et il dit: Si j\'ai pu trouver grâce à tes yeux, Seigneur, que le Seigneur passe au milieu de nous, puisque c\'est un peuple au col roide, et pardonne notre égarement et notre péché, et fais de nous ta propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Et Il dit: Voici, je conclus une alliance; devant tout ton peuple je veux opérer des miracles tels qu\'il n\'en a point été produit en aucun pays et chez aucune nation, et tout le peuple, au sein duquel tu es, verra l\'œuvre de l\'Éternel; car ce que je vais faire avec toi sera terrible.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Prends garde à ce que je te commande aujourd\'hui! Voici, je chasserai devant toi les Amoréens et les Cananéens et les Héthiens et les Phérisiens et les Hévites et les Jébusites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Garde-toi d\'accorder une alliance aux habitants du pays où tu entreras, de peur d\'avoir en eux un piège parmi vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'vous détruirez au contraire leurs autels et briserez leurs statues, et arracherez leurs Aschères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'car tu n\'adoreras aucun autre Dieu; car l\'Éternel, dont le nom est le Jaloux, est un Dieu jaloux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'garde-toi d\'accorder une alliance aux habitants du pays, de peur que, lorsqu\'ils se prostituent à la suite de leurs dieux et font des sacrifices à leurs dieux, ils ne t\'invitent et que tu ne manges de leurs victimes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'et que tu ne maries tes fils parmi leurs filles, et que leurs filles, se prostituant à la suite de leurs dieux, n\'entraînent tes fils à se prostituer à la suite de leurs dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Tu ne te feras point de dieu de fonte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Tu observeras la fête des azymes; sept jours tu mangeras des azymes, comme je te l\'ai prescrit, à l\'époque du mois des épis; car c\'est dans le mois des épis que tu es sorti d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Toutes les prémices de la maternité m\'appartiennent, ainsi que dans tous tes troupeaux tout mâle premier-né du gros et du menu bétail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Mais le premier-né de l\'âne tu le rachèteras au moyen d\'un mouton; et si tu ne le rachètes pas, tu l\'assommeras. Tu rachèteras tout premier-né de tes fils, et l\'on ne se présentera pas devant moi les mains vides.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Six jours tu travailleras, mais tu chômeras le septième jour, même pendant les semailles et la moisson tu le chômeras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Tu feras la fête des Semaines en offrant les prémices du froment moissonné, et la fête de la rentrée des récoltes l\'année étant révolue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Trois fois par an tous tes mâles se présenteront devant le Seigneur, l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Car je chasserai les nations devant toi et étendrai tes frontières, et personne ne convoitera ton pays, lorsque trois fois par an tu iras en pèlerinage te présenter devant l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Tu n\'immoleras point sur du levain le sang de mes victimes, et là victime de la fête de Pâques ne sera point conservée jusqu\'au matin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Tu apporteras à la maison de l\'Éternel, ton Dieu, la fleur des prémices de ton sol. Tu ne feras pas cuire le chevreau au lait de sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Et l\'Éternel dit à Moïse: Mets par écrit ces paroles; car c\'est aux termes de ces paroles que je conclus une alliance avec toi et avec Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Et Moïse fut là avec l\'Éternel quarante jours et quarante nuits; il ne mangea point de pain et ne but point d\'eau; et il écrivit sur des tables les paroles de l\'alliance, dix paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Et lorsque Moïse descendit du mont de Sinaï, les Deux Tables du Témoignage étant dans les mains de Moïse qui descendait de la montagne, Moïse ne se doutait pas que la peau de son visage resplendît, parce qu\'il s\'était entretenu avec Lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Et Aaron et tous les enfants d\'Israël regardèrent Moïse, et voici, la peau de son visage rayonnait, et ils craignaient de l\'aborder.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Mais Moïse les appela, et Aaron et tous les princes de l\'assemblée se dirigèrent vers lui, et il leur parla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Après cela, tous les enfants d\'Israël s\'approchèrent, et il leur transmit tous les ordres que l\'Éternel lui avait donnés sur le mont de Sinaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Et Moïse ayant terminé le discours qu\'il leur adressait, mit un voile sur sa figure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Et lorsque Moïse pénétrait devant l\'Éternel pour lui parler, il ôtait le voile jusqu\'à ce qu\'il sortît; et étant sorti, il redisait aux enfants d\'Israël tout ce qui lui avait été ordonné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Et les enfants d\'Israël voyant le visage de Moïse, aperçurent la peau resplendissante de son visage. C\'est pourquoi Moïse mettait le voile sur son visage jusqu\'à ce qu\'il entrât pour parler avec Lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Alors Moïse réunit toute l\'assemblée des enfants d\'Israël et leur dit: Voici les choses que l\'Éternel ordonne de faire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Pendant six jours tu vaqueras à tes affaires, mais au septième jour vous aurez un saint sabbat férié en l\'honneur de l\'Éternel; quiconque vaquera ce jour-là à une affaire sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Le jour du sabbat vous n\'allumerez de feu dans aucune de vos demeures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Et Moïse adressa à toute l\'assemblée des enfants d\'Israël ces paroles: Voici l\'ordre que l\'Éternel a donné en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Prenez sur vos biens une offrande pour l\'Éternel: que tout homme généreux de cœur la présente, cette offrande, à l\'Éternel, de l\'or, de l\'argent et de l\'airain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'et de l\'azur et du pourpre et du vermillon et du lin et du poil de chèvre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'et des peaux de béliers teintes en rouge et des peaux de chiens de mer et du bois d\'acacia;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'de l\'huile pour le Candélabre et des aromates pour l\'huile d\'onction et l\'encens odorant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'et des pierres d\'onyx et des pierreries enchâssées pour l\'Ephod et le Pectoral.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Et que tous ceux d\'entre vous qui ont un esprit intelligent viennent et exécutent tout ce que l\'Éternel a commandé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'la Résidence, sa tente et sa couverture, ses agrafes et ses ais, ses traverses, ses colonnes et ses soubassements;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'l\'Arche et ses barres, le Propitiatoire et le Rideau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'la Table et ses barres et tous ses ustensiles et les Pains de présentation;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'et le Candélabre et son attirail et ses lampes et l\'huile du Candélabre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'et l\'Autel aux parfums et ses barres et l\'huile d\'onction et l\'encens odorant, et le Rideau de la porte pour la porte de la Résidence;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'l\'Autel des holocaustes et son treillis en réseau d\'airain, ses barres et tous ses ustensiles; le Bassin et son support;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'les toiles du Parvis, ses colonnes et ses soubassements et le rideau de la porte du Parvis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'les piliers de la Résidence et les piliers du Parvis et ses cordes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'les costumes solennels pour faire le service dans le Sanctuaire, les Vêtements sacrés pour le prêtre Aaron et les vêtements de ses fils pour les fonctions sacerdotales.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Alors toute l\'assemblée des enfants d\'Israël sortit de la présence de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Et tous ceux que leur cœur y portait et qui étaient de bonne volonté vinrent et apportèrent l\'offrande de l\'Éternel pour l\'œuvre de la Tente du Rendez-vous et tous ses ouvrages et pour les vêtements sacrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Les hommes vinrent aussi bien que les femmes, tous ceux que leur cœur y portait, et offrirent des boucles de narine, des pendants d\'oreille et des bagues et des colliers, toutes sortes de joyaux d\'or,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'tous ceux qui avaient à présenter à l\'Éternel une offrande d\'or par agitation; et ceux chez qui se trouvait de l\'azur et du pourpre et du vermillon et du lin et du poil de chèvre et des peaux de béliers teintes en rouge et des peaux de chiens de mer, l\'apportèrent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'et tous ceux qui voulaient présenter par élévation une offrande d\'argent et d\'airain présentèrent l\'offrande à l\'Éternel; et tous ceux chez qui se trouvait du bois d\'acacia propre au travail de toutes sortes d\'ouvrages l\'apportèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Et toutes les femmes d\'un esprit intelligent se mirent à coudre de leurs mains et apportèrent des coutures d\'azur et de pourpre, de vermillon et de lin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Et toutes les femmes portées de bonne volonté et douées d\'intelligence firent des coutures de poil de chèvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Et les princes fournirent les pierres d\'onyx et les pierreries enchâssées pour l\'Ephod et le Pectoral,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'et les aromates et l\'huile pour le Candélabre et pour l\'huile d\'onction et l\'encens odorant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Tous, hommes et femmes, que leur cœur portait à contribuer à tous les ouvrages que l\'Éternel avait donné par Moïse l\'ordre de faire, les enfants d\'Israël apportèrent à l\'Éternel des dons volontaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Et Moïse dit aux enfants d\'Israël: Voyez, l\'Éternel a nommément appelé Betsaléel, fils de Ouri, fils de Hur, de la tribu de Juda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'et Il l\'a rempli de l\'Esprit de Dieu, d\'intelligence, de sens, de connaissance et de savoir-faire en toute chose,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'et du talent d\'inventer, et de travailler l\'or et l\'argent et l\'airain');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'et de graver les pierres à enchâsser et de sculpter le bois, d\'exécuter toute œuvre d\'art;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'et Il lui a aussi accordé le don d\'instruire, à lui et à Oholiab, fils d\'Ahisamach, de la tribu de Dan;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Il les a remplis d\'un sens intelligent pour exécuter toute sorte d\'ouvrage de forgeron et de charpentier et d\'ouvrier en brocart d\'azur, de pourpre, de vermillon et de lin, et de tisserand; ils sont à même d\'imaginer toute sorte d\'ouvrage et d\'inventer des œuvres d\'art.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Ainsi Betsaléel et Oholiab et tous les experts en qui l\'Éternel avait mis l\'intelligence et le sens du savoir-faire, exécuteront toute l\'œuvre du travail du Sanctuaire, tout ce qu\'a prescrit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Alors Moïse appela Betsaléel et Oholiab et tous les experts en qui l\'Éternel avait mis le sens de l\'intelligence, tous ceux que leur cœur portait à entreprendre l\'ouvrage pour l\'exécuter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Et ils reçurent de Moïse toutes les offrandes apportées par les enfants d\'Israël pour l\'œuvre du travail du Sanctuaire qui devait être fait; et tous les matins on lui apportait encore des dons volontaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Cependant tous ces experts occupés à tout le travail du sanctuaire, quittant chacun l\'ouvrage qu\'ils faisaient,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'vinrent et, s\'adressant à Moïse, lui dirent: Le peuple apporte beaucoup de choses, beaucoup plus qu\'il n\'en faut pour faire l\'ouvrage que l\'Éternel a commandé d\'exécuter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Alors Moïse ordonna que dans tout le camp fût répandu cet avis: Que personne, ni homme ni femme, ne procure plus d\'offrandes pour le Sanctuaire, et le peuple cessa d\'en apporter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Car il y avait assez d\'objets confectionnés pour tous les ouvrages à faire et même il y en avait de reste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'En conséquence tous ces experts employés à l\'œuvre formèrent la Résidence de dix tentures de lin retors, d\'azur, de pourpre et de vermillon; ils les firent portant des chérubins en ouvrage de broderie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Une tenture eut vingt-huit coudées de longueur et quatre coudées de largeur; toutes les tentures furent de la même dimension.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Et l\'on fit des assemblages chacun de cinq tentures assemblées l\'une avec l\'autre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'et l\'on ménagea des mailles d\'azur au bord d\'une tenture, celle du bout au point de jonction; on fit la même opération au bord du tapis du bout dans le second assemblage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'On ménagea cinquante mailles à une tenture, et de même au second assemblage cinquante mailles à l\'extrémité d\'un tapis au second assemblage, de sorte que les mailles coïncidaient l\'une avec l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Et l\'on fit cinquante agrafes d\'or, et assemblant les tentures l\'une avec l\'autre au moyen des agrafes, on obtint la Résidence formant un tout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Puis l\'on fit des tapis de poil de chèvre pour en composer une tente qui protégeât la Résidence: on fit onze tapis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Un tapis eut trente coudées de longueur et quatre coudées de largeur par tapis, les onze tapis de la même dimension.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Et l\'on assembla cinq tapis d\'une part et six tapis d\'autre part.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Et l\'on ménagea cinquante mailles au bord du tapis du bout à la jonction et cinquante mailles au bord du tapis au second assemblage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Et l\'on fit cinquante agrafes d\'airain pour assembler la tente qui devint un tout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Et pour garantir la Tente, on fit une couverture de peaux de béliers teintes en rouge, et par-dessus encore une couverture de peaux de chiens de mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Et l\'on fit de bois d\'acacia les ais pour la Résidence qui furent placés debout;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'la longueur d\'un ais fut de dix coudées et sa largeur d\'une coudée et demie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'A chaque ais on pratiqua deux tenons taillés l\'un comme l\'autre; c\'est ce qui fut fait pour tous les ais de la Résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Et l\'on fit les ais de la Résidence au nombre de vingt pour le côté sud au midi');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'et quarante soubassements d\'argent pour supporter vingt ais, deux soubassements par ais pour en recevoir les deux tenons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'et pour le côté opposé de la Résidence, le côté du nord, vingt ais');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'et quarante soubassements d\'argent, deux soubassements par ais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Et pour le fond de la Résidence, à l\'occident, on fit six ais,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'et pour les angles de la Résidence, au côté du fond, on fit deux ais,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'doubles dans le bas et doubles aussi dans le haut au premier anneau; on les fit ainsi les deux aux deux angles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'il y eut donc huit ais et leurs soubassements d\'argent, seize soubassements, deux soubassements sous l\'un des ais et deux sous l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Et l\'on fit des traverses de bois d\'acacia, cinq pour les ais de l\'un des côtés de la Résidence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'et cinq traverses pour les ais du second côté de la Résidence, et cinq traverses pour les ais du côté de la Résidence qui forma le fond à l\'occident,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'et la traverse médiale au milieu des ais qu\'elle traversa d\'une extrémité à l\'autre extrémité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Et l\'on plaqua d\'or les ais, et l\'on fit d\'or leurs anneaux destinés à recevoir les traverses qui furent aussi plaquées d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Et l\'on fit le Rideau d\'azur, de pourpre et de vermillon et de lin retors: ce fut un ouvrage de l\'art du tisseur ainsi que les chérubins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Et pour le soutenir, on fit quatre colonnes d\'acacia qui furent plaquées d\'or, munies de clous d\'or et pour lesquelles on fondit quatre soubassements d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Et il fit le Rideau à la porte de la Tente en azur et pourpre et vermillon et en lin retors selon l\'art du tisseur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'et ses cinq colonnes, et ses clous, et plaqua leurs têtes et leurs tringles, et d\'airain leurs cinq soubassements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Et Betsaléel fit l\'Arche de bois d\'acacia, ayant deux coudées et demie de longueur et une coudée et demie de largeur et une coudée et demie de hauteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Et il la plaqua d\'or pur intérieurement et extérieurement, et l\'entoura d\'une bordure d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Et il y coula quatre anneaux d\'or aux quatre angles, deux anneaux sur l\'un des côtés et deux anneaux sur l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Et il fit des barres de bois d\'acacia qu\'il plaqua d\'or;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'et il passa les barres dans les anneaux sur les côtés de l\'Arche pour servir au transport de l\'Arche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Et il fit le Propitiatoire d\'or pur, long de deux coudées et demie et large d\'une coudée et demie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Et il fit deux Chérubins d\'or, travaillés au tour, aux deux bouts du Propitiatoire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'un Chérubin à un bout et un Chérubin à l\'autre bout; c\'est sur le Propitiatoire qu\'il plaça les Chérubins à ses deux extrémités;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'et les Chérubins avaient les ailes étendues par-dessus couvrant de leurs ailes le Propitiatoire et se faisant face l\'un à l\'autre, et ayant la face tournée sur le Propitiatoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Et il fit la Table de bois d\'acacia, de deux coudées de longueur, d\'une coudée de largeur et d\'une coudée et demie de hauteur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'et il la plaqua d\'or pur, et l\'entoura d\'une bordure d\'or,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'et la munit tout autour d\'un rebord d\'un empan de hauteur auquel il adapta une bordure d\'or pur tout autour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'et il y coula quatre anneaux et fixa les anneaux aux quatre angles marqués par ses quatre pieds;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'les anneaux se trouvèrent à la jonction du rebord pour recevoir les barres servant au transport de la Table.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Et il fit les barres de bois d\'acacia et les plaqua d\'or pour servir au transport de la Table.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Et il fit la vaisselle, couvert de la Table, ses plats et ses coupes et ses calices et ses patères servant aux libations, et il y employa l\'or pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Et il fit le Candélabre, d\'or pur; le Candélabre avec sa hampe et sa tige fut fait au tour, il en surgissait des calices, des boutons et des fleurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'et six tubes sortaient de ses côtés; trois tubes du Candélabre de l\'un de ses côtés et trois tubes du Candélabre de l\'autre de ses côtés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'il y eut trois calices taillés en amande à l\'un des tubes avec bouton et fleur, et trois calices taillés en amande à l\'autre tube avec bouton et fleur et cela aux six tubes sortant du Candélabre');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'qui lui-même reçut sur sa tige quatre calices taillés en amande avec leurs boutons et leurs fleurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'et un bouton au-dessous de chaque embranchement de deux tubes dont six partaient du Candélabre:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'il en surgissait des boutons et des fleurs, le tout fait au tour et d\'or pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Et il fit ses lampes au nombre de sept et ses mouchettes et ses cendriers d\'or pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Pour le faire avec tout son attirail on employa un talent d\'or pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Et il fit l\'Autel aux parfums de bois d\'acacia, d\'une coudée de longueur et d\'une coudée de largeur, carré, et de deux coudées de hauteur, avec ses cornes attenantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Et il le plaqua d\'or pur, le dessus, les parois tout autour et les cornes, et il pratiqua à l\'entour une bordure d\'or pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Et il y fixa deux anneaux d\'or à ses deux côtés au-dessous de la bordure pour recevoir les barres servant à le transporter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Et il fit les barres de bois d\'acacia et les plaqua d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Et il fit l\'Huile d\'onction du sanctuaire et le pur Encens odorant par le procédé du parfumeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Et il fit l\'Autel des holocaustes de bois d\'acacia, de cinq coudées de longueur et de cinq coudées de largeur, carré, et de trois coudées de hauteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Et il fit ses cornes à ses quatre angles où elles furent adaptées; et il le plaqua d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Et il fit tous les ustensiles de l\'Autel, les vases et les pelles et les patères et les fourchettes et les brasiers; il employa l\'airain pour tous ses ustensiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Et il fit à l\'Autel un treillis en réseau d\'airain au-dessous de la corniche de l\'Autel jusqu\'à la moitié de l\'Autel à partir du bas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Et il fixa au réseau d\'airain quatre anneaux aux quatre angles pour recevoir les barres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Et il fit les barres de bois d\'acacia et les plaqua d\'airain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'et il passa les barres dans les anneaux aux côtés de l\'Autel pour servir à le transporter; il le fit creux et formé d\'ais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Et il fit le Bassin d\'airain et son support d\'airain, y employant les miroirs des femmes qui à tour de rôle venaient faire leur service à l\'entrée de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Et il disposa le Parvis; au côté du midi au sud, il tendit sur une longueur de cent coudées les toiles du Parvis, de lin retors,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'au moyen de vingt colonnes fixées sur vingt soubassements d\'airain et munies de clous et de tringles d\'argent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'de même au côté du nord cent coudées de toiles avec leurs vingt colonnes et leurs vingt soubassements d\'airain et leurs clous et leurs tringles d\'argent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'et au côté de l\'occident cinquante coudées de toiles avec leurs dix colonnes et leurs dix soubassements, leurs clous et leurs tringles d\'argent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'et au côté oriental, au levant, de cinquante coudées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'quinze coudées de toiles d\'une part avec leurs trois colonnes et leurs trois soubassements,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'et d\'autre part des deux côtés de la porte du Parvis quinze coudées de toiles avec leurs trois colonnes et leurs trois soubassements,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'toutes les toiles de pourtour du Parvis étant de lin retors,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'et les soubassements des colonnes, d\'airain, leurs clous et leurs tringles, d\'argent, leurs têtes plaquées d\'argent, les tringles de toutes les colonnes du Parvis étant d\'argent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'il fit aussi le Rideau à la porte du Parvis en ouvrage de brocart d\'azur, de pourpre, de vermillon et de lin retors, de vingt coudées en longueur, de cinq coudées en hauteur et largeur, exactement comme les toiles du Parvis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'et ses quatre colonnes et leurs quatre soubassements d\'airain, leurs clous d\'argent, et leurs têtes et leurs tringles plaquées d\'argent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'tous les piliers formant l\'enceinte de la Résidence et du Parvis étant d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Suivent les comptes de la Résidence, Résidence du Témoignage, rendus sur l\'ordre de Moïse par les soins des Lévites, par l\'organe d\'Ithamar, fils du Prêtre Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Car Betsaléel, fils de Ouri, fils de Hur, de la tribu de Juda, exécuta tout ce que l\'Éternel avait prescrit à Moïse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'et avec lui Oholiab, fils de Ahisamach, de la tribu de Dan, ouvrier en fer et en bois et en brocart d\'azur, de pourpre, de vermillon et de lin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Tout l\'or mis en œuvre en tout genre de travail pour le Sanctuaire était l\'or provenant des offrandes, savoir vingt-neuf talents et sept cent trente sicles, en sicles du Sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Et l\'argent de ceux de l\'assemblée qui avaient passé à la revue, fut de cent talents et mille sept cent soixante-quinze sicles, en sicles du Sanctuaire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'à raison de demi-sicle par tête, la moitié d\'un sicle, en sicles du Sanctuaire, par chacun des hommes de vingt ans et au-dessus passant à la revue, dont il y eut six cent trois mille cinq cent cinquante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Et cent talents d\'argent furent employés à couler les soubassements du Sanctuaire, et les soubassements du Rideau, cent talents pour cent soubassements, un talent par soubassement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Et avec les mille sept cent soixante-quinze [sicles] il fit les clous des colonnes dont il plaqua les têtes, et fit les tringles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Et l\'airain des offrandes fut de soixante-dix talents et deux mille quatre cents sicles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Il l\'employa aux soubassements de la porte de la Tente du Rendez-vous, à l\'Autel d\'airain, au réseau d\'airain qui y était, et à tous les ustensiles de l\'Autel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'et aux soubassements du Parvis dans son pourtour, et aux soubassements de la porte du Parvis et à tous les piliers de la Résidence et à tous les piliers du Parvis dans son pourtour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Et avec l\'azur et le pourpre et le vermillon ils firent les Costumes d\'office pour servir dans le Sanctuaire, et ils firent les vêtements sacrés pour Aaron, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Et il fit l\'Ephod d\'or, d\'azur, de pourpre et de vermillon et de lin retors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Et ils laminèrent les plaques d\'or, et taillèrent des fils pour les entrelacer dans l\'azur et le pourpre et le vermillon et le lin en ouvrage de tricot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Ils le composèrent de deux pièces portant sur les épaules et assemblées, assemblées aux deux extrémités,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'et sa ceinture qui y est appliquée et en sort, fut du même travail, d\'or, d\'azur, de pourpre et de vermillon et de lin retors comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Et ils firent les pierres d\'onyx enchâssées dans des chatons d\'or portant gravés en gravure de sceaux les noms des fils d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Et il les plaça sur les épaulettes de l\'Ephod, comme pierres commémoratives pour les fils d\'Israël, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Et il fit le Pectoral en ouvrage de tricot, comme le travail de l\'Ephod, d\'or, d\'azur, de pourpre et de vermillon et de lin retors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Il fut carré; ils firent le Pectoral double, d\'un empan de longueur et d\'un empan de largeur, double.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Et ils le garnirent de quatre rangs de pierreries; le rang de sardoine, de topaze et d\'émeraude fut le premier rang;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'et le second rang se composait d\'une escarboucle, d\'un saphir et d\'un diamant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'et le troisième, d\'une opale, d\'une agate et d\'une améthyste;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'le quatrième, d\'un chrysolithe, d\'un onyx et d\'un jaspe, enchâssés en or dans leurs chatons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Et il y eut douze pierres autant que de noms des fils d\'Israël, selon leurs noms; elles furent gravées comme des sceaux, portant chacune son nom correspondant aux douze tribus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Et ils firent au Pectoral des chaînettes torses tressées en cordons et d\'or pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Et ils firent deux chaînettes d\'or et deux anneaux d\'or et fixèrent les deux anneaux aux deux extrémités du Pectoral.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Et ils insérèrent les deux chaînettes d\'or dans les deux anneaux aux extrémités du Pectoral.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Et ils arrêtèrent aux deux chatons les deux autres bouts des deux cordons, et les nouèrent aux deux épaulettes de l\'Ephod sur le devant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Ils firent de plus deux anneaux d\'or qu\'ils placèrent aux deux extrémités du Pectoral, sur celui de ses bords qui est tourné vers l\'Ephod en dedans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Ils firent encore deux anneaux d\'or qu\'ils mirent aux deux pièces de l\'Ephod en bas sur le devant, juste à leur jonction au-dessus de la ceinture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Et ils attachèrent le Pectoral par ses anneaux aux anneaux de l\'Ephod avec des cordons d\'azur pour l\'arrêter au-dessus de la ceinture de l\'Ephod, afin que le Pectoral ne s\'écarte pas de l\'Ephod, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Et il fit la Robe sur laquelle porte l\'Ephod, en ouvrage de tisseur, toute d\'azur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'et au milieu de la robe une ouverture comme l\'ouverture d\'une cotte de mailles, et bordée dans son contour d\'un ourlet, afin qu\'elle ne se déchire pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Et sur la bordure de la Robe ils firent des grenades d\'azur, de pourpre et de vermillon en fil retors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Et ils firent des clochettes d\'or pur et ils mirent les clochettes entre les grenades à la bordure de la robe tout autour, entre les grenades,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'une clochette et une grenade, une clochette et une grenade à la bordure de la robe tout autour, pour le service, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Et ils confectionnèrent les Tuniques de byssus, en ouvrage de tisseur, pour Aaron et ses fils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'et le Turban de byssus et la coiffure des bonnets de byssus et les caleçons de lin, de byssus retors,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'et la Ceinture de byssus retors et d\'azur et de pourpre et de vermillon ouvragé en brocart, ainsi que l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Et ils firent la plaque, diadème sacré, d\'or pur, et y tracèrent en caractères de sceau: Consécration à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Et ils y adaptèrent un cordon d\'azur pour l\'attacher au Turban dans le haut, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Ainsi fut achevé tout le travail de la Résidence de la Tente du Rendez-vous, et les enfants d\'Israël se conformèrent à tous les ordres que l\'Éternel avait donnés à Moïse, ils les suivirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Et ils présentèrent à Moïse la Résidence, la Tente et tout son attirail, ses agrafes, ses ais, ses traverses et ses colonnes et ses soubassements,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'et la couverture de peaux de béliers teintes en rouge et la couverture de peaux de chiens de mer, et le Rideau intérieur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'et l\'Arche du Témoignage et ses barres et le Propitiatoire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'la Table, toute sa vaisselle et les Pains de présentation;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'le Candélabre [or] pur, ses lampes, l\'assortiment de ses lampes, et tout son attirail, et l\'huile du Candélabre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'et l\'Autel d\'or et l\'huile d\'onction et le parfum odorant et le Rideau de la porte de la Tente,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'l\'Autel d\'airain et le réseau d\'airain qui y est appliqué, ses barres et tout son attirail; le Bassin et son support,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'les toiles du Parvis, ses colonnes et ses soubassements et le rideau pour la porte du Parvis, ses cordes et ses piliers, tous les meubles servant à l\'usage de la Résidence de la Tente du Rendez-vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'les Costumes pour le service à faire dans le Sanctuaire, les Vêtements sacrés pour le Prêtre Aaron et les vêtements de ses fils pour leurs fonctions sacerdotales.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Les enfants d\'Israël exécutèrent tout l\'ouvrage conformément à tous les ordres donnés par l\'Éternel à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Et Moïse vit tout l\'ouvrage, et voici, ils l\'avaient fait comme l\'Éternel l\'avait ordonné; ainsi l\'avaient-ils fait, et Moïse les bénit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Et l\'Éternel parla à Moïse en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'A l\'époque du premier mois, le premier jour du mois, tu élèveras la Résidence de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Et tu y placeras l\'Arche du Témoignage et tu voileras l\'Arche avec le Rideau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Et tu y introduiras la Table et en arrangeras le couvert, puis le Candélabre que tu garniras de ses lampes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Et tu mettras l\'Autel d\'or pour l\'encensement devant l\'Arche du Témoignage, et tu suspendras le Rideau à la porte de la Résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Et tu placeras l\'Autel des holocaustes devant l\'entrée de la Résidence de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Et tu placeras le Bassin entre la Tente du Rendez-vous et l\'Autel, et tu y mettras de l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Et tu dresseras le Parvis à l\'entour, et tu suspendras le Rideau à la porte du Parvis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Et tu prendras l\'Huile d\'onction et tu oindras la Résidence et tout ce qu\'elle renferme, et tu la consacreras avec tous ses meubles, afin qu\'elle soit sacrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Et tu oindras l\'Autel des holocaustes et tous ses ustensiles, et tu consacreras l\'Autel afin que l\'Autel soit souverainement saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Et tu oindras le Bassin et son support et le consacreras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Et tu amèneras Aaron et ses fils à l\'entrée de la Tente du Rendez-vous et tu feras leur ablution avec de l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Et tu revêtiras Aaron des vêtements sacrés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'et tu l\'oindras et le consacreras pour qu\'il me serve dans le sacerdoce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Et tu feras approcher ses fils, et tu les revêtiras des tuniques, et tu les oindras comme tu auras oint leur père afin qu\'ils me servent dans le sacerdoce, de telle sorte que leur onction leur confère le sacerdoce à perpétuité pour leurs générations futures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Et Moïse se conforma à tous les ordres que l\'Éternel lui donnait: ainsi fit-il.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Et le premier mois de la seconde année, le premier jour du mois, la Résidence fut élevée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Et Moïse éleva la Résidence et en posa les soubassements et en plaça les ais et y mit leurs traverses et en dressa les colonnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Et il étendit la tente par-dessus la Résidence, et en haut par-dessus la tente il plaça la couverture, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Et prenant le Témoignage, il le mit dans l\'Arche, et munit l\'Arche de ses barres, et il plaça le Propitiatoire sur le haut de l\'Arche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'et il introduisit l\'Arche dans la Résidence, et suspendit le Rideau, et il voila l\'Arche du Témoignage, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Et il dressa la Table dans la Tente du Rendez-vous au côté nord de la Résidence en dehors du rideau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'et il y arrangea un couvert de pain devant l\'Éternel, comme l\'Éternel l\'avait ordonnée Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Et il plaça le Candélabre dans la Tente du Rendez-vous vis-à-vis de la Table au côté sud de la Résidence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'et il fixa les lampes devant l\'Éternel, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Et il plaça l\'Autel d\'or dans la Tente du Rendez-vous devant le Rideau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'et y fit fumer de l\'encens odorant, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Et il suspendit le Rideau à l\'entrée de la Résidence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'et il dressa l\'Autel des holocaustes à l\'entrée de la Résidence de la Tente du Rendez-vous, et y offrit les holocaustes et les offrandes, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Et il plaça le Bassin entre la Tente du Rendez-vous et l\'Autel, et il y mit de l\'eau pour les ablutions,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'et Moïse et Aaron et ses fils s\'y lavèrent les mains et les pieds;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'au moment de pénétrer dans la Tente du Rendez-vous et de s\'approcher de l\'Autel ils firent ces ablutions, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Et il éleva le Parvis autour de la Résidence et de l\'Autel, et fixa le rideau à la porte du Parvis: et ainsi Moïse acheva l\'ouvrage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Alors la nue couvrit la Tente du Rendez-vous, et la gloire de l\'Éternel remplit la Résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Et Moïse ne put pénétrer dans la Tente du Rendez-vous, car la nue séjournait sur elle, et la gloire de l\'Éternel remplissait la Résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Et lorsque la nue se levait de dessus la Résidence, les enfants d\'Israël levaient le camp dans tous leurs campements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Et quand la nue ne se retirait pas, ils ne levaient pas le camp qu\'elle ne se fût retirée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Car de jour la nue de l\'Éternel couvrait la Résidence et de nuit il y avait un feu, et c\'est ce que vit toute la maison d\'Israël durant toute sa migration.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Et l\'Éternel appela Moïse, et de la Tente du Rendez-vous Il lui parla en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Parle aux enfants d\'Israël et dis-leur: Si quelqu\'un de vous veut offrir une oblation à l\'Éternel, l\'oblation que vous offrirez sera prise parmi vos bestiaux, parmi vos bœufs et vos brebis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Si l\'oblation consiste dans l\'Holocauste d\'une pièce de gros bétail, il offrira un mâle sans défaut, et l\'amènera à l\'entrée de la Tente du Rendez-vous, afin qu\'il soit agréé devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Et il posera sa main sur la tête de l\'holocauste pour se faire agréer de Lui pour sa réconciliation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Alors il égorgera le jeune taureau devant l\'Éternel, et les Prêtres, fils d\'Aaron, apporteront le sang qu\'ils répandront à l\'Autel qui est à l\'entrée de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Et il dépouillera l\'holocauste et le détaillera en sept quartiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Et les fils du Prêtre Aaron mettront du feu sur l\'Autel et disposeront le bois sur le feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Et les Prêtres, fils d\'Aaron, rangeront les pièces, la tête et la graisse sur le bois placé sur le feu mis sur l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Et il lavera dans l\'eau la fressure et les jambes, et le Prêtre fera fumer le tout sur l\'Autel en holocauste, en victime brûlée, d\'un parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Et si son oblation est de menu bétail, chèvres ou brebis, pour holocauste, il offrira un mâle sans défaut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Et il l\'égorgera à côté de l\'Autel au nord devant l\'Éternel, et les Prêtres, fils d\'Aaron, en répandront le sang autour de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Et il le détaillera en ses quartiers, outre la tête et la graisse, et le Prêtre les rangera sur le bois placé sur le feu mis sur l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Et il lavera dans l\'eau la fressure et les jambes, et le Prêtre offrira le tout et le fera fumer sur l\'Autel: c\'est un holocauste, une victime brûlée, d\'un parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Et si l\'oblation destinée à l\'Éternel consiste dans un holocauste d\'oiseaux, il offrira pour son oblation ou des tourterelles, ou de jeunes pigeons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Et le Prêtre les approchera de l\'Autel, il leur fendra la tête avec l\'ongle et les fera fumer sur l\'Autel, et leur sang dégouttera sur les parois de l\'Autel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'et il enlèvera le gésier avec ses immondices et le jettera à côté de l\'Autel vers l\'orient dans le cendrier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Et il rompra l\'oiseau aux ailes, mais sans les détacher, et le prêtre le fera fumer sur l\'Autel, sur le bois placé sur le feu: c\'est un holocauste, une victime brûlée, d\'un parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Et si quelque personne veut offrir à l\'Éternel l\'oblation d\'une Offrande, son oblation sera de la fleur de farine sur laquelle il versera de l\'huile et mettra de l\'encens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Et il l\'apportera aux Prêtres, fils d\'Aaron, et le Prêtre y prendra une poignée sur la farine et l\'huile, une poignée pleine, ainsi que sur tout l\'encens, et il fera fumer sur l\'Autel cette portion destinée en sacrifice igné, d\'un parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Et le reste de l\'offrande sera pour Aaron et ses fils comme partie très sainte des sacrifices ignés faits à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Et si tu veux offrir l\'oblation d\'une offrande de choses cuites au four, que ce soient des galettes de fleur de farine sans levain, trempées dans l\'huile et des oublies sans levain ointes d\'huile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Et si ton oblation consiste dans une offrande cuite sur la poêle, que ce soit de la fleur de farine trempée dans l\'huile, sans levain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Romps-la en menus morceaux et verse de l\'huile dessus: c\'est une offrande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Et si ton oblation consiste en une offrande cuite dans le pot au feu, que ce soit un apprêt de fleur de farine avec de l\'huile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Et tu présenteras l\'offrande qu\'on en fera à l\'Éternel, et on la transmettra au Prêtre qui l\'apportera à l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Et le Prêtre prélèvera sur l\'offrande la portion destinée, qu\'il fera fumer sur l\'Autel en sacrifice igné d\'un parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Et le reste de l\'offrande sera pour Aaron et ses fils, comme partie très-sainte des sacrifices ignés faits à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Aucune des offrandes que vous présenterez à l\'Éternel ne sera apprêtée au levain, car vous ne devez faire fumer ni ferment ni miel en sacrifice igné à l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'vous pourrez en offrir à l\'Éternel comme oblation de primeurs, mais il n\'en paraîtra point sur l\'Autel comme parfum agréable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Et tu assaisonneras de sel toute oblation d\'une offrande, tu n\'omettras jamais le sel d\'alliance de ton Dieu dans ton offrande, tu ajouteras du sel à chaque oblation que tu offriras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Et si tu veux présenter à l\'Éternel une offrande de primeurs, tu présenteras des épis rôtis au feu, du grain concassé, comme offrande de tes primeurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'et tu y verseras de l\'huile et y ajouteras de l\'encens: c\'est une offrande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Et le Prêtre fera fumer en sacrifice igné à l\'Éternel la part destinée des grains concassés et de l\'huile avec tout l\'encens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Si l\'oblation consiste dans un Sacrifice Pacifique, et qu\'il veuille offrir une pièce de gros bétail, soit mâle, soit femelle, ce qu\'il présentera devant l\'Éternel doit être sans défaut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Et il posera sa main sur la tête de son oblation, et il l\'égorgera à l\'entrée de la Tente du Rendez-vous, et les Prêtres, fils d\'Aaron, répandront le sang autour de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Et de cette victime pacifique il offrira en sacrifice igné à l\'Éternel la graisse qui enveloppe les intestins, toute la graisse adhérente aux intestins');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'et les deux reins et la graisse qui les enveloppe, qui est adhérente aux lombes, et le grand lobe attenant au foie qu\'il détachera près des reins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Alors les fils d\'Aaron la feront fumer sur l\'Autel, sur l\'holocauste rangé sur le bois placé sur le feu, en sacrifice igné d\'un parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Et si son oblation consiste dans une pièce de menu bétail, mâle ou femelle, offerte à l\'Éternel comme sacrifice pacifique, que ce qu\'il présente soit sans défaut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'S\'il offre en oblation un mouton, qu\'il l\'amène devant l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'et qu\'il pose sa main sur la tête de son oblation, et qu\'il l\'égorge devant la Tente du Rendez-vous, et les fils d\'Aaron en répandront le sang autour de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Et de la victime pacifique il offrira à l\'Éternel en sacrifice igné sa graisse, la queue grasse tout entière qu\'il coupera à la jonction de l\'échine, et la graisse qui enveloppe les intestins, toute la graisse adhérente aux intestins,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'et les deux reins et la graisse qui y tient, aux lombes, et le grand lobe attenant au foie, qu\'il détachera près des reins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Et le Prêtre fera fumer cela sur l\'Autel comme un mets offert en sacrifice igné à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Si une chèvre est l\'oblation, il l\'amènera devant l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'et il lui posera la main sur la tête, et l\'égorgera devant la Tente du Rendez-vous; et les fils d\'Aaron en répandront le sang autour de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Et il en offrira pour son oblation en sacrifice igné à l\'Éternel la graisse qui enveloppe les intestins, toute la graisse adhérente aux intestins,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'et les deux reins et la graisse qui les couvre, tient aux lombes, et le grand lobe attenant au foie, qu\'il détachera près des reins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Et le Prêtre la fera fumer sur l\'Autel, toute la graisse comme un mets offert en sacrifice igné, en parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Règle perpétuelle pour vos générations dans toutes vos demeures: vous ne mangerez ni graisse ni sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Parle aux enfants d\'Israël et dis: Lorsqu\'une personne aura péché par mégarde et fait l\'une des choses interdites par l\'Éternel, desquelles il faut s\'abstenir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'si c\'est le Prêtre revêtu de l\'onction qui a péché et mis par là le peuple en état de délit, pour le péché qu\'il a commis, il offrira à l\'Éternel un jeune taureau sans défaut en expiation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Et il amènera le taureau à l\'entrée de la Tente du Rendez-vous devant l\'Éternel et posera sa main sur la tête du taureau, et il égorgera le taureau devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Puis le Prêtre revêtu de l\'onction prendra du sang de ce taureau et l\'apportera dans la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Là le Prêtre trempera son doigt dans ce sang dont il fera sept aspersions en face du Rideau du Sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Et le Prêtre mettra de ce sang aux cornes de l\'Autel de l\'encens odorant devant l\'Éternel dans la Tente du Rendez-vous, et il répandra tout le [reste du] sang au pied de l\'Autel des holocaustes qui se trouve devant l\'entrée de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Et il enlèvera toute la graisse du taureau expiatoire, la graisse qui enveloppe les intestins, et toute la graisse adhérente aux intestins,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'et les deux reins et la graisse qui y tient, qui tient aux lombes, et le grand lobe attenant au foie, et il la détachera près des reins');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'de la même manière qu\'on l\'enlève du taureau dans le sacrifice pacifique, et le Prêtre la fera fumer sur l\'Autel des holocaustes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Et il portera la peau du taureau, sa chair tout entière, sa tête et ses jambes et ses intestins et sa fiente,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'le taureau tout entier, hors du camp dans un lieu pur où l\'on verse les cendres; et il le brûlera sur du bois au feu; c\'est dans le lieu où l\'on verse les cendres qu\'il sera brûlé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Et si toute l\'assemblée d\'Israël tombe par mégarde en péché, et que la chose échappe à la vue de l\'Assemblée, et que, contre les commandements de l\'Éternel, on ait fait l\'une des choses dont on doit s\'abstenir, et que l\'on soit en état de délit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'lorsque l\'on aura la connaissance du péché commis, l\'assemblée offrira un jeune taureau en expiation, et on l\'amènera devant la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Et les Anciens de l\'Assemblée poseront leurs mains sur la tête du taureau devant l\'Éternel, et on égorgera le taureau devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Et le Prêtre revêtu de l\'onction apportera du sang de ce taureau dans la Tente du Rendez-vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'et le Prêtre trempera son doigt dans ce sang, et fera sept aspersions devant l\'Éternel en face du Rideau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'et il mettra de ce sang aux cornes de l\'Autel qui est devant l\'Éternel dans la Tente du Rendez-vous; et il répandra tout le [reste du] sang au pied de l\'Autel des holocaustes qui est à l\'entrée de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Et il en enlèvera toute la graisse qu\'il fera fumer sur l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Et il préparera le taureau, comme il prépare le taureau expiatoire: ainsi le préparera-t-il; c\'est ainsi que le Prêtre fera pour eux l\'expiation afin que pardon leur soit accordé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Et l\'on emportera le taureau hors du camp et on le brûlera, comme on brûle le taureau précédent: c\'est la victime expiatoire pour l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Et si un Prince pèche et, contre les commandements de l\'Éternel, son Dieu, fait par mégarde l\'une des choses dont on doit s\'abstenir, et qu\'il soit en état de délit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'quand il reconnaîtra le péché commis par lui, il présentera pour son oblation un bouc mâle sans défaut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Et il posera sa main sur la tête du bouc, et il l\'égorgera dans le lieu où l\'on égorge les holocaustes devant l\'Éternel: c\'est une victime expiatoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Et le Prêtre prendra avec le doigt du sang de la victime expiatoire, et en mettra aux cornes de l\'Autel des holocaustes, et répandra le [reste du] sang au pied de l\'Autel des holocaustes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Et il en fera fumer toute la graisse sur l\'Autel, comme la graisse de la victime pacifique: c\'est ainsi que le Prêtre fera pour lui l\'expiation de son péché afin qu\'il lui soit pardonné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Et si un homme du peuple pèche par mégarde en faisant contre les commandements de l\'Éternel l\'une des choses dont on doit s\'abstenir, et qu\'il soit en état de délit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'quand il reconnaîtra le péché commis par lui, il présentera comme oblation une chèvre sans défaut pour le péché qu\'il a commis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Et il posera sa main sur la tête de la victime expiatoire, et il l\'égorgera dans le lieu des holocaustes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Et le Prêtre prendra avec le doigt du sang de cette victime et en mettra aux cornes de l\'Autel des holocaustes, et il répandra tout [le reste de] ce sang au pied de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Et il en enlèvera toute la graisse, comme on enlève la graisse de la victime pacifique; et le Prêtre la fera fumer sur l\'Autel en parfum agréable à l\'Éternel: c\'est ainsi que le Prêtre fera pour lui l\'expiation, afin que pardon lui soit accordé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Et s\'il présente un mouton en oblation pour victime expiatoire, il présentera une femelle sans défaut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Et il posera sa main sur la tête de la victime et il l\'égorgera en expiation dans le lieu où l\'on égorge les holocaustes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Et le Prêtre prendra avec le doigt du sang de la victime et en mettra aux cornes de l\'Autel des holocaustes, et il répandra tout le [reste de ce] sang au pied de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Et il en enlèvera toute la graisse, comme on enlève la graisse du mouton offert en sacrifice pacifique. Et le Prêtre la fera fumer sur l\'Autel en sacrifice igné à l\'Éternel: c\'est ainsi que le Prêtre fera pour lui l\'expiation du péché qu\'il a commis, afin qu\'il lui soit pardonné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Si quelqu\'un pèche en refusant, quoique témoin oculaire ou informé, de déposer après avoir entendu la formule d\'adjuration, il est sous le poids de son iniquité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'ou, si quelqu\'un a touché une chose souillée quelconque, soit le corps d\'une bête impure morte, ou le corps d\'un animal impur mort, ou le corps d\'un reptile impur mort, quoiqu\'il ne s\'en soit pas douté, il est en état d\'impureté et de délit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'ou, si quelqu\'un a touché à une souillure attachée à l\'homme quelle que soit la souillure dont il est infecté, que ce soit à son insu ou de son su, il est en état de délit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'ou si quelqu\'un profère de ses lèvres légèrement le serment de faire du mal ou du bien, ou l\'une des choses que l\'homme peut jurer légèrement, qu\'il l\'ait fait de son su ou à son insu, il est en état de délit dans l\'un de ces cas:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'si donc il est en état de délit pour l\'un de ces cas, il fera l\'aveu de ce dont il est coupable');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'et offrira en sacrifice de délit à l\'Éternel pour le péché qu\'il a commis, une femelle de menu bétail, une brebis ou une chèvre, en expiation, afin que le Prêtre par la propitiation le décharge de son péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Que si ses ressources ne vont pas jusqu\'à un mouton, qu\'il offre pour le délit qu\'il a commis deux tourterelles on deux jeunes pigeons à l\'Éternel, l\'une en sacrifice expiatoire, l\'autre en holocauste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Et il les apportera au Prêtre qui présentera ce qui est destiné à l\'expiation, le premier volatile, et lui fendra la tête avec l\'ongle dans la région de la nuque, mais sans le partager.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Et avec le sang de la victime expiatoire il aspergera la paroi de l\'Autel, et le reste du sang sera exprimé au pied de l\'autel: c\'est une victime expiatoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Et il sacrifiera le second volatile en holocauste d\'après le rite: c\'est ainsi que le Prêtre fera pour lui la propitiation à cause du péché qu\'il a commis dans l\'un de ces cas, afin qu\'il lui soit pardonné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Et si ses ressources ne vont pas jusqu\'à deux tourterelles ou deux jeunes pigeons, il présentera en oblation pour son péché un dixième d\'épha de fleur de farine pour l\'expiation; il n\'y ajoutera ni huile, ni encens; car c\'est une expiation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Et il l\'apportera au Prêtre, et le Prêtre en prendra une poignée pleine, la part destinée, et il la fera fumer sur l\'Autel en sacrifice igné à l\'Éternel: c\'est une expiation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'C\'est ainsi que le Prêtre fera pour lui la propitiation à cause du péché qu\'il a commis dans l\'un de ces cas, afin qu\'il lui soit pardonné, et [il en] sera pour le Prêtre comme de l\'offrande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Si quelqu\'un fraude et fait par mégarde une infidélité dans les choses saintes dues à l\'Éternel, il présentera pour sa victime de délit à l\'Éternel un bélier sans défaut de son troupeau, sur ton évaluation, en sicles d\'argent, monnaie du Sanctuaire, pour victime de délit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Et il restituera ce en quoi il aura fraudé la redevance sainte, et y ajoutera un cinquième en sus; et il le remettra au Prêtre; et le Prêtre fera pour lui la propitiation avec le bélier, victime de délit, afin que pardon lui soit accordé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Et si quelqu\'un pèche en faisant contre les commandements de l\'Éternel l\'une des choses dont on doit s\'abstenir, et s\'il l\'a fait par ignorance et se trouve en état de délit et sous le poids de sa faute,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'il présentera un bélier sans défaut de son troupeau, selon ton évaluation, pour victime de délit, au Prêtre qui fera pour lui la propitiation à cause de son erreur et de son ignorance, afin que pardon lui soit accordé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'C\'est un sacrifice de délit, il s\'est rendu coupable de délit envers l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Transmets ce commandement à Aaron et à ses fils: Voici le rite de l\'holocauste: L\'holocauste restera sur l\'âtre, sur l\'Autel, toute la nuit jusqu\'au matin, et le feu de l\'Autel y sera entretenu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Et le Prêtre mettra ses habits de lin et couvrira sa nudité avec le caleçon de lin, et il enlèvera la cendre produite par le feu qui aura consumé l\'holocauste sur l\'Autel et la mettra à côté de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Et il ôtera ses habits et en mettra d\'autres pour porter la cendre hors du camp dans un lieu pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Et le feu de l\'Autel y brûlera sans s\'éteindre; chaque matin le Prêtre y allumera du bois et y arrangera l\'holocauste et y fera fumer la graisse des victimes pacifiques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Un feu perpétuel brûlera sur l\'Autel sans s\'éteindre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Voici le rite de l\'offrande: Des fils d\'Aaron la présenteront devant l\'Éternel, devant l\'Autel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'et ils y prendront une poignée de la fleur de farine de l\'offrande et de l\'huile, et tout l\'encens ajouté à l\'offrande, et feront fumer sur l\'Autel en parfum agréable à l\'Éternel cette part destinée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Et Aaron et ses fils mangeront le reste: ce sont des azymes qui se mangeront dans le Lieu-Saint; ils le mangeront dans le Parvis de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Elle ne sera pas boulangée avec du levain; je la leur ai donnée pour leur part sur mes sacrifices ignés; elle est très sainte comme les victimes offertes pour le péché et pour le délit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Tous les mâles d\'entre les enfants d\'Aaron la mangeront; c\'est une rente perpétuelle à prendre dans vos âges futurs sur les sacrifices ignés faits à l\'Éternel. Pour y toucher, il faut être consacré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Voici l\'oblation qu\'Aaron et ses fils offriront à l\'Éternel le jour de son Onction; le dixième d\'un épha de fleur de farine, telle sera leur offrande perpétuelle dont ils présenteront la moitié le matin, et la moitié le soir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Elle sera préparée à l\'huile sur la poêle; tu l\'apporteras bien imbibée, tu l\'offriras disposée comme l\'offrande, en menus morceaux, en parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Et le Prêtre qui parmi ses fils lui succédera dans l\'Onction, la préparera; c\'est une prestation perpétuelle due à l\'Éternel: elle sera brûlée en totalité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Et toute offrande sacerdotale sera brûlée en totalité; elle ne se mangera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Parle à Aaron et à ses fils et dis: Voici le rite du sacrifice pour le péché. C\'est dans le lieu où l\'on égorge l\'holocauste que sera égorgée la victime expiatoire devant l\'Éternel: elle est très sainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Le Prêtre expiateur la mangera; elle se mangera dans un lieu saint, dans le Parvis de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Pour en goûter la chair, il faut être consacré, et celui qui en fera jaillir du sang sur un vêtement, lavera dans un lieu saint ce qu\'il aura aspergé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Le vase de terre qui aura servi à la cuire, sera brisé, et si on la fait cuire dans un vase d\'airain, on le nettoiera et le lavera avec de l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Tout mâle parmi les Prêtres en mangera: elle est très sainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Et toute victime expiatoire dont on apportera du sang dans la Tente du Rendez-vous pour la propitiation, ne se mangera point dans le Sanctuaire, elle sera brûlée au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'La graisse de bêtes mortes ou déchirées pourra être employée à toute sorte d\'usages,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'mais vous ne devez point la manger; car quiconque mangera de la graisse des bestiaux dont on offre des sacrifices ignés à l\'Éternel, celui qui en aura mangé sera éliminé de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Et vous ne mangerez point de sang du tout dans toutes vos demeures, ni d\'oiseaux, ni de quadrupèdes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Celui qui mangera du sang d\'une espèce quelconque, celui-là sera éliminé de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Parle aux enfants d\'Israël et dis: Celui qui offre son sacrifice pacifique à l\'Éternel, apportera à l\'Éternel son oblation prise sur son sacrifice pacifique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'De ses propres mains il apportera ce qui doit être un sacrifice igné à l\'Éternel, il apportera la graisse avec la poitrine, la poitrine pour l\'offrir par agitation comme offrande agitée à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Voici le rite du sacrifice pour le délit: il est très saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'C\'est dans le lieu où l\'on égorge l\'holocauste que sera égorgée la victime pour le délit, et l\'on en répandra le sang à l\'Autel tout autour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Et l\'on en offrira toute la graisse, la queue grasse, et la graisse qui enveloppe les intestins,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'et les deux reins et la graisse qui y tient, qui tient aux lombes, et le grand lobe attenant au foie; on la détachera près des reins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Et le Prêtre la fera fumer sur l\'Autel en sacrifice igné à l\'Éternel: c\'est une victime pour le délit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Tous les mâles d\'entre les Prêtres la mangeront; elle se mangera dans un lieu saint: elle est très sainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Tel le sacrifice pour le péché, tel est le sacrifice pour le délit; même rite pour l\'un et pour l\'autre; la victime sera au Prêtre qui l\'offrira en propitiation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Et le Prêtre qui présentera l\'holocauste de quelqu\'un, aura pour lui la peau de l\'holocauste qu\'il aura présenté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Et toute offrande cuite au four et toute offrande apprêtée sur la poêle et dans le pot au feu sera au Prêtre qui l\'aura offerte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Et toute offrande frottée d\'huile et sèche sera à tous les fils d\'Aaron, à l\'un comme à l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Et voici le rite du sacrifice pacifique offert à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Si on l\'offre comme acte de louange, on offrira outre la victime de louange des galettes azymes frottées d\'huile et des oublies azymes trempées dans l\'huile et de la fleur de farine imbibée et des gâteaux frottés d\'huile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Outre les gâteaux on offrira du pain levé comme oblation en sus du sacrifice de louange et de gratitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Et de toute l\'offrande on présentera l\'une des pièces par élévation à l\'Éternel; elle sera pour le Prêtre qui aura répandu le sang de la victime pacifique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Et la chair de la victime de louange et de gratitude se mangera le jour même de l\'oblation, on n\'en gardera rien jusqu\'au matin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Et si la victime offerte en oblation est votive ou spontanée, elle se mangera le jour même de la célébration du sacrifice, et le reste se mangera le lendemain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Et ce qui restera de la chair de la victime sera le troisième jour brûlé au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Que si le troisième jour on s\'avise de manger de la chair de la victime pacifique, on ne sera pas bien venu, et il ne sera pas tenu compte du sacrifice à celui qui l\'aura offert, il sera en mauvaise odeur; et la personne qui en aura mangé, sera sous le poids de sa faute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Et la chair qui a été en contact avec quelque chose d\'impur, ne se mangera point; on la brûlera au feu. D\'ailleurs tout homme pur peut manger la chair;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'mais la personne qui, se trouvant en état d\'impureté, mangera de la chair de la victime pacifique appartenant à l\'Éternel, sera éliminée de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Et si une personne touche quoi que ce soit d\'impur, la souillure d\'un homme, ou un animal impur ou un objet abominable impur quelconque, et mangera de la chair d\'une victime pacifique appartenant à l\'Éternel, cette personne doit être éliminée de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Parle aux enfants d\'Israël et dis: Vous ne mangerez aucune graisse ni de taureau, ni de mouton, ni de chèvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'La graisse de bêtes mortes ou déchirées pourra être employée à toute sorte d\'usages,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'mais vous ne devez point la manger; car quiconque mangera de la graisse des bestiaux dont on offre des sacrifices ignés à l\'Éternel, celui qui en aura mangé sera éliminé de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Et vous ne mangerez point de sang du tout dans toutes vos demeures, ni d\'oiseaux, ni de quadrupèdes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Celui qui mangera du sang d\'une espèce quelconque, celui-là sera éliminé de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Parle aux enfants d\'Israël et dis: Celui qui offre son sacrifice pacifique à l\'Éternel, apportera à l\'Éternel son oblation prise sur son sacrifice pacifique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'De ses propres mains il apportera ce qui doit être un sacrifice igné à l\'Éternel, il apportera la graisse avec la poitrine, la poitrine pour l\'offrir par agitation comme offrande agitée à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Et le Prêtre fera fumer la graisse sur l\'Autel, et la poitrine sera pour Aaron et ses fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Et sur vos victimes pacifiques vous donnerez au Prêtre l\'éclanche droite présentée par agitation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Celui des fils d\'Aaron qui offrira le sang des victimes pacifiques, et la graisse, aura pour sa part l\'éclanche droite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Car sur les victimes pacifiques des enfants d\'Israël je prélève la poitrine qu\'on agite devant moi et l\'éclanche qu\'on élève, et je les donne au Prêtre Aaron et à ses fils comme redevance perpétuelle due par les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Telle est la part d\'Aaron et la part de ses fils sur les sacrifices ignés faits à l\'Éternel dès le jour où ils furent admis à servir l\'Éternel dans le sacerdoce,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'part qui en vertu de l\'ordre de l\'Éternel leur fut adjugée le jour où Il les oignit, pour être payée par les enfants d\'Israël soumis pour la suite de leurs âges à cette redevance perpétuelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Tel est le rite de l\'holocauste, de l\'offrande, du sacrifice pour le péché et pour le délit, et de l\'installation et du sacrifice pacifique,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'lequel l\'Éternel prescrivit à Moïse sur le mont de Sinaï le jour où Il commanda aux enfants d\'Israël de présenter leurs oblations à l\'Éternel dans le désert de Sinaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Prends Aaron et ses fils avec lui et les costumes et l\'huile d\'onction et le taureau d\'expiation et les deux béliers et la corbeille des azymes');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'et convoque toute l\'Assemblée à l\'entrée de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Et Moïse exécuta l\'ordre de l\'Éternel, et l\'Assemblée se réunit à l\'entrée de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Alors Moïse dit à l\'Assemblée: Voici ce que l\'Éternel a commandé de faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Et Moïse amena Aaron et ses fils et fit leurs ablutions avec l\'eau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'et il lui mit la Tunique et le ceignit de la Ceinture et le revêtit de la Robe et lui mit l\'Ephod et il le ceignit de la ceinture de l\'Ephod dont il le revêtit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Et il lui mit le Pectoral, et plaça sur le Pectoral l\'Urim et le Thummim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Et il lui couvrit la tête du Turban sur le devant duquel il fixa la Plaque d\'or, diadème sacré, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Et Moïse prit l\'huile d\'onction et oignit la Résidence et toutes les choses qui y sont, et ainsi, les consacra;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'et il en fit sept aspersions contre l\'Autel, et il oignit l\'Autel et tous ses ustensiles, et le Bassin et son support, afin de les consacrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Et il répandit de l\'huile d\'onction sur la tête d\'Aaron et l\'oignit afin de le consacrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Et Moïse fit avancer les fils d\'Aaron et les revêtit de tuniques et les ceignit de la ceinture, et leur attacha leurs bonnets, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Et il fit amener le taureau expiatoire, et Aaron et ses fils posèrent leurs mains sur la tête du taureau expiatoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Et Moïse l\'égorgea, et prit le sang, et de son doigt il en mit aux cornes de l\'Autel tout autour et fit la purification de l\'Autel, et le [reste du] sang il le répandit au pied de l\'Autel qu\'il consacra pour qu\'on pût y faire la propitiation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Et il prit toute la graisse qui enveloppe les intestins, et le grand lobe du foie et les deux reins et leur graisse, et Moïse les fit fumer sur l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Puis il brûla au feu en dehors du camp le taureau et sa peau et sa chair et sa fiente, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Et il offrit le bélier de l\'holocauste, et Aaron et ses fils posèrent leurs mains sur la tête du bélier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Et Moïse l\'égorgea et en répandit le sang autour de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Et il détailla le bélier en ses quartiers, et Moïse fit fumer sur l\'Autel la tête, les quartiers et la graisse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Et il lava dans l\'eau la fressure et les jambes, et Moïse, fit fumer le bélier entier sur l\'Autel, en holocauste, en parfum agréable, en sacrifice igné à l\'Éternel, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Et il offrit le second bélier, le bélier de l\'installation, et Aaron et ses fils posèrent leurs mains sur la tête du bélier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Et Moïse l\'égorgea et prit de son sang et en mit au bout de l\'oreille droite d\'Aaron et au pouce droit et au grand orteil droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Et il fit approcher les fils d\'Aaron, et Moïse leur mit de ce sang au bout de l\'oreille droite, au pouce droit et au grand orteil droit; et Moïse répandit le [reste du] sang autour de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Et il prit la graisse et la queue grasse et toute la graisse qui enveloppe les intestins et le grand lobe du foie et les deux reins et leur graisse et l\'éclanche droite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'et de la corbeille des azymes qui était devant l\'Éternel il prit une galette azyme et une galette de pain avec de l\'huile et une oublie qu\'il posa sur les graisses et l\'éclanche droite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'et il mit le tout dans les mains d\'Aaron et dans les mains de ses fils, et le brandit en oblation agitée devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Et Moïse retira ces choses de leurs mains, et les fit fumer sur l\'Autel, sur l\'holocauste, comme sacrifice d\'installation, en parfum agréable, en sacrifice igné à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Et Moïse prit du bélier d\'installation la poitrine et l\'agita en oblation agitée devant l\'Éternel, elle échut à Moïse pour sa part, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Et Moïse prit de l\'huile d\'onction et du sang qui était sur l\'Autel et en fit jaillir sur Aaron et sur ses vêtements, sur ses fils et sur les vêtements de ses fils avec lui, et consacra ainsi Aaron et ses vêtements et ses fils, et les vêtements de ses fils avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Et Moïse dit à Aaron et à ses fils: Faites cuire la chair à l\'entrée de la Tente du Rendez-vous et l\'y mangez, ainsi que le pain contenu dans la corbeille d\'installation, comme je l\'ai prescrit en disant: Aaron et ses fils la mangeront;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'et vous brûlerez au feu ce qui restera de la chair et du pain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'et pendant sept jours vous ne sortirez pas de la porte de la Tente du Rendez-vous jusqu\'à ce que les jours de votre installation soient accomplis; car votre installation doit durer sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Ce qu\'on a fait aujourd\'hui, l\'Éternel a ordonné de le faire comme propitiation pour vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'et vous resterez jour et nuit pendant sept jours à l\'entrée de la Tente du Rendez-vous, et vous observerez ce que vous êtes tenus d\'observer envers l\'Éternel, afin que vous ne mouriez pas; car tel est l\'ordre que j\'ai reçu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Et Aaron et ses fils se conformèrent en tout point à l\'ordre que l\'Éternel avait donné par Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Et le huitième jour Moïse manda Aaron et ses fils et les Anciens d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'et dit à Aaron: Prends un jeune taureau pour victime expiatoire, et un bélier pour holocauste, l\'un et l\'autre sans défaut, et offre-les à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Et tu parleras ainsi aux enfants d\'Israël: Prenez un bouc pour victime expiatoire et un veau et un agneau, l\'un et l\'autre d\'un an et sans défaut, pour holocauste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'et un bœuf et un bélier pour victimes pacifiques afin de les sacrifier devant l\'Éternel, et une offrande humectée d\'huile; car aujourd\'hui l\'Éternel vous apparaîtra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Alors ils amenèrent ce que Moïse avait ordonné, sur le devant de la Tente du Rendez-vous, et toute l\'Assemblée s\'avança et se présenta devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Et Moïse dit: C\'est ce que l\'Éternel a commandé; faites-le, et la gloire de l\'Éternel vous apparaîtra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Et Moïse dit à Aaron: Approche-toi de l\'Autel, et fais ton sacrifice expiatoire et ton holocauste et la propitiation pour toi et pour le peuple; et fais l\'oblation du peuple et la propitiation pour lui, comme l\'Éternel l\'a ordonné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Alors Aaron s\'approcha de l\'Autel et égorgea le veau, victime expiatoire, pour lui-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Et les fils d\'Aaron lui présentèrent le sang, et il trempa son doigt dans le sang et en mit aux cornes de l\'Autel, et répandit le [reste du] sang au pied de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Et il fit fumer sur l\'Autel la graisse et les reins et le grand lobe détaché du foie, de la victime expiatoire, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Et il brûla au feu en dehors du camp la chair et la peau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Et il égorgea l\'holocauste, et les fils d\'Aaron lui présentèrent le sang, et il en fit aspersion à l\'Autel tout autour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Et ils lui présentèrent l\'holocauste divisé en ses quartiers, et la tête, qu\'il fit fumer sur l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Et il lava la fressure et les jambes qu\'il fit fumer sur l\'holocauste, sur l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Puis il offrit l\'oblation du peuple et prit le bouc, victime expiatoire pour le peuple, et il l\'égorgea comme victime expiatoire pareille à la première.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Et il offrit l\'holocauste, et procéda selon le rite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Et il offrit l\'offrande et en prit une poignée qu\'il fit fumer sur l\'Autel, indépendamment de l\'holocauste du matin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Et il égorgea le bœuf et le bélier en sacrifice pacifique pour le peuple; et les fils d\'Aaron lui présentèrent le sang dont il aspergea l\'Autel tout autour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'et les parties grasses du bœuf et du bélier, la queue grasse, et la graisse qui enveloppe les intestins, et les reins et le grand lobe du foie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'et ils placèrent les graisses sur les poitrines, et il fit fumer les graisses sur l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Et Aaron agita en oblation agitée devant l\'Éternel les poitrines et l\'éclanche droite, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Et Aaron leva la main du côté du peuple et le bénit, et il descendit après la célébration du Sacrifice expiatoire, de l\'Holocauste et du Sacrifice pacifique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Et Moïse et Aaron entrèrent dans la Tente du Rendez-vous; puis en étant ressortis, ils bénirent le peuple; alors la Gloire de l\'Éternel apparut à tout le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Et de la présence de l\'Éternel il sortit un feu qui consuma sur l\'Autel l\'holocauste et les graisses, et tout le peuple en fut témoin, et éleva des acclamations et tomba la face contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Et Nadab et Abihu, fils d\'Aaron, prirent chacun leur cassolette, et y mirent du feu sur lequel ils versèrent de l\'encens, et ils apportèrent devant l\'Éternel un feu étranger, ce qu\'il ne leur avait point prescrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Alors de la présence de l\'Éternel sortit un feu qui les consuma, et ils moururent en la présence de l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'et Moïse dit à Aaron: C\'est là ce que l\'Éternel a dit et prononcé: Sur mes proches je veux montrer ma Sainteté et à la face de tout le peuple ma Majesté. Et Aaron garda le silence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Et Moïse appela Misaël et Eltsaphan, fils d\'Uriel, oncle d\'Aaron, et leur dit: Approchez! emportez vos frères loin du Sanctuaire hors du camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Et ils s\'approchèrent et les emportèrent dans leurs tuniques hors du camp selon l\'ordre de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Et Moïse dit à Aaron et à Éléazar et Ithamar, ses fils: Ne vous découvrez point la tête et ne déchirez point vos habits, de peur que vous ne mouriez et qu\'il ne s\'irrite contre toute l\'Assemblée; c\'est à vos frères, à toute la maison d\'Israël, à pleurer sur l\'embrasement allumé par l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Et ne franchissez point la porte de la Tente du Rendez-vous, de peur que vous ne mouriez; car vous avez sur vous l\'huile de l\'onction de l\'Éternel. Et ils se conformèrent à l\'avis de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Et l\'Éternel parla à Aaron et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Tu ne boiras ni vin, ni cervoise, ni toi, ni tes fils avec toi, lorsque vous devrez entrer dans la Tente du Rendez-vous, de peur que vous ne mouriez: c\'est une règle perpétuelle pour vos âges futurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'afin que vous puissiez et distinguer ce qui est saint et ce qui est profane, ce qui est immonde et ce qui est pur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'et enseigner aux enfants d\'Israël tous les usages que l\'Éternel vous a prescrits par l\'organe de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Et Moïse dit à Aaron et à Éléazar et Ithamar, ses fils, qui étaient survivants: Prenez l\'offrande restée des sacrifices ignés faits à l\'Éternel, et mangez-la sans levain à côté de l\'Autel; car elle est très sainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Et vous la mangerez en lieu saint, car c\'est ce qui te revient et revient à tes fils des sacrifices ignés faits à l\'Éternel, tel étant l\'ordre que j\'ai reçu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Quant à la poitrine de l\'oblation agitée et à l\'éclanche de l\'oblation élevée, vous les mangerez en lieu pur, toi et tes fils et tes filles avec toi; car elles te sont accordées comme ton revenu et le revenu de tes fils sur les sacrifices pacifiques des enfants d\'Israël');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'qui apporteront l\'éclanche de l\'oblation élevée et la poitrine de l\'oblation agitée à la combustion des graisses pour qu\'elles soient présentées par agitation devant l\'Éternel, et elles t\'appartiendront à toi et à tes fils comme rente perpétuelle conformément à l\'ordre de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Et Moïse cherchait le bouc expiatoire, et voilà qu\'il avait été brûlé. Alors il se courrouça contre Éléazar et Ithamar, fils d\'Aaron, qui étaient survivants, et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Pourquoi n\'avez-vous pas mangé la victime expiatoire dans le Lieu-Saint? car elle est très-sainte, et Il vous l\'a donnée pour que vous vous chargiez de l\'iniquité de l\'Assemblée et que vous fassiez la propitiation pour elle devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Voici, le sang n\'en a point été introduit dans le Sanctuaire, dans l\'intérieur; vous devez la manger dans le Sanctuaire selon l\'ordre que j\'ai reçu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Et Aaron dit à Moïse: Voici, aujourd\'hui ils ont offert leur victime expiatoire et leur holocauste devant l\'Éternel, et moi j\'ai vu ces événements; pourrais-je donc aujourd\'hui manger la victime et serait-ce bien aux yeux de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Ce que Moïse ayant entendu, il approuva.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Et l\'Éternel parla à Moïse et Aaron et leur dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Parlez aux enfants d\'Israël en ces termes: Voici les animaux que vous pouvez manger parmi toutes les bêtes qui sont sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Tout animal ayant le pied fourché et la corne fendue de part en part et qui rumine, vous servira d\'aliment;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'parmi ceux qui ruminent et ont le pied fourché, voici seulement ceux dont vous vous abstiendrez, le chameau, car il rumine, mais n\'a pas la corne fendue de part en part; vous le tiendrez pour impur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'et la gerboise, car elle rumine, mais n\'a pas de corne fendue de part en part; vous la tiendrez pour impure;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'et le lièvre, car il rumine, mais n\'a pas de corne fendue de part en part; vous le tiendrez pour impur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'et le porc, car il a bien le pied fourché et une corne fendue de part en part, mais il ne rumine pas; vous le tiendrez pour impur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Vous ne mangerez pas de leur chair, ni ne toucherez leurs corps morts; vous les tiendrez pour impurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Parmi les animaux qui sont dans les eaux, ceux que vous pouvez manger sont tous ceux qui portent nageoires et écailles dans les eaux, les mers, les rivières, ils vous serviront d\'aliments;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'mais tous ceux qui ne portent pas nageoires et écailles dans les mers et les rivières parmi tous ceux qui fourmillent dans les eaux et les êtres qui vivent dans les eaux, seront pour vous une souillure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Ils seront pour vous une souillure; vous ne mangerez point de leur chair, vous regarderez leur corps mort comme immonde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Tout ce qui dans les eaux ne porte pas nageoires et écailles sera pour vous immonde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Et parmi les oiseaux voici ceux que vous regarderez comme immondes, qui ne se mangeront pas, qui seront pour vous une souillure, l\'aigle et l\'orfraie et l\'aigle de mer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'et le faucon et l\'espèce de l\'émerillon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'toutes les espèces de corbeaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'et l\'autruche femelle et l\'autruche mâle et la mouette, et l\'espèce du vautour');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'et le hibou et le pélican sauteur et l\'ibis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'et le cygne et le pélican et le percnoptère');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'et la cigogne et l\'espèce du perroquet et la huppe et la chauve-souris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Vous regarderez comme immonde tout insecte ailé marchant sur quatre pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Les seuls insectes ailés marchant sur quatre pieds qui vous serviront d\'aliments sont ceux qui ont les pieds surmontés de jambes pour sauter sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Ceux de cette famille que vous mangerez, sont l\'espèce de l\'arbeh, l\'espèce du solam, et l\'espèce du hargal, et l\'espèce du hagab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Mais tous les autres insectes ailés à quatre pieds seront immondes pour vous; ils vous rendront impurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'quiconque aura touché leurs corps morts, sera jusqu\'au soir en état d\'impureté,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'et quiconque aura porté de leurs corps morts, lavera ses habits et sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Vous tiendrez pour immonde tout animal qui a le pied fourché, mais n\'a pas une corne fendue de part en part et ne rumine pas; quiconque le touchera sera en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Et tout ce qui marche sur ses pattes et tous les animaux qui marchent sur quatre pieds, vous les tiendrez pour immondes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'et quiconque touchera leurs corps morts sera jusqu\'au soir en état d\'impureté. Et celui qui portera leurs corps morts, lavera ses habits et sera jusqu\'au soir en état d\'impureté; vous les regarderez comme immondes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Et parmi les menus animaux qui frétillent sur la terre, vous tiendrez pour impurs les taupes, les souris et les lézards selon leur espèce,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'et l\'Anaka et le Coch, et la Letaa et le colimaçon et le caméléon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Tenez-les pour impurs parmi tous ceux qui frétillent; quiconque les touchera morts, sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Et tout objet sur lequel tombera un de ces animaux morts sera souillé, meuble quelconque de bois, ou vêtements, ou cuir, ou sac, tout ustensile servant à un usage quelconque; il sera mis dans l\'eau et restera souillé jusqu\'au soir, après quoi il se retrouvera pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Et tout vase de terre dans lequel il en tombera sera souillé avec tout son contenu, et vous briserez le vase.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Et tout comestible sur lequel il tombera de cette eau sera souillé, et toute liqueur à boire contenue dans ce vase sera souillée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Et tout objet sur lequel il tombera quelque chose de leurs corps morts, sera souillé, fourneau et foyer seront mis en pièces, comme souillés, et vous devez les regarder comme immondes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Les sources, les citernes et les réservoirs d\'eau seuls n\'en contracteront point de souillure. Mais quiconque touchera leur corps mort, tombera en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'S\'il tombe quelque chose de leur corps mort sur une semence quelconque qui doit être semée, elle ne cessera pas d\'être pure;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'mais si l\'on a humecté cette semence et qu\'il y tombe quelque chose de leurs corps morts, tenez-la pour souillée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Et si l\'un des animaux qui vous servent d\'aliment, périt, celui qui touchera son corps mort sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Et celui qui mangera de son corps mort lavera ses habits et sera jusqu\'au soir en état d\'impureté; et celui qui portera son corps mort lavera ses habits et sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Et tout reptile rampant sur la terre sera pour vous un animal immonde dont vous ne ferez pas un aliment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'En fait de reptiles rampant sur la terre, tous ceux qui se traînent sur le ventre et tous ceux qui marchent sur quatre pieds ou plus, quel qu\'en soit le nombre, ne vous serviront point d\'aliment: ce sont des souillures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Ne souillez vos personnes par aucun reptile qui se traîne, et ne vous exposez pas à leur contact immonde pour tomber par là dans l\'état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Car je suis l\'Éternel, votre Dieu, et vous devez vous sanctifier et être saints, car je suis Saint, et éviter de souiller vos personnes par aucun des reptiles qui se traînent sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Car je suis l\'Éternel qui vous ai retirés du pays d\'Egypte, pour être votre Dieu: Soyez donc saints, car je suis Saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Telle est la loi qui parmi les bestiaux et les oiseaux et tous les êtres vivants qui se meuvent dans les eaux, et tous les êtres vivants qui rampent sur la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'vous apprendra à discerner ce qui est pur ou impur, l\'animal qui se mange et celui qui ne se mange pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Parle et dis aux enfants d\'Israël: Si une femme devient enceinte et qu\'elle accouche d\'un enfant mâle, elle sera pendant sept jours en état d\'impureté, dans le même état d\'impureté qu\'aux époques de son indisposition menstruelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Et le huitième jour on circoncira la chair du prépuce de l\'enfant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Et elle gardera la maison trente-trois jours pendant qu\'elle se purifie de sang; elle ne touchera rien de sacré et n\'ira point au Sanctuaire avant que le temps de sa purification soit accompli.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Et si c\'est d\'une fille qu\'elle accouche, elle sera deux semaines en état d\'impureté comme lors de ses menstrues, et elle gardera la maison soixante-six jours pour se purifier de sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Et à l\'expiration du temps de sa purification pour un fils ou pour une fille, elle apportera un agneau d\'un an comme holocauste, et un jeune pigeon ou une tourterelle, comme victime expiatoire, à l\'entrée de la Tente du Rendez-vous au Prêtre qui l\'offrira à l\'Éternel et fera pour elle la propitiation afin qu\'elle soit purifiée de l\'évacuation de son sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Telle est la loi pour la femme accouchée d\'un fils ou d\'une fille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Et si ses ressources ne vont pas jusqu\'à un mouton, qu\'elle prenne deux tourterelles ou deux jeunes pigeons, l\'un pour l\'holocauste, l\'autre pour le sacrifice expiatoire, et le Prêtre fera pour elle la propitiation afin qu\'elle soit purifiée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Et l\'Éternel parla à Moïse et Aaron en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'S\'il Survient à la peau du corps d\'un homme une élevure, ou une dartre, ou une tache [blanche] et qu\'elle devienne sur la peau de son corps une marque lépreuse, il sera conduit au Prêtre Aaron ou à l\'un des Prêtres, ses fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Et si l\'examen fait par le Prêtre de l\'affection de la peau de son corps constate que le poil a blanchi à la place atteinte qui apparaît déprimée au-dessous du niveau de la peau de son corps, c\'est la maladie de la lèpre: ce que le Prêtre ayant observé, il le déclarera impur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Mais s\'il y a sur la peau de son corps une tache blanche qui n\'apparaisse pas déprimée au-dessous du niveau de la peau, et où le poil n\'ait pas blanchi, le Prêtre séquestrera le malade pour sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Et si l\'examen que le Prêtre fera le septième jour, constate que l\'affection a conservé le même aspect et ne s\'est pas étendue sur la peau, le Prêtre le séquestrera une seconde fois pour sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Si le second examen fait par le Prêtre le septième jour constate que l\'éruption est devenue terne et ne s\'est pas étendue sur la peau, le Prêtre le déclarera pur: c\'est une simple dartre; qu\'il lave ses habits, et il sera pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Mais si la dartre s\'est étendue sur la peau après qu\'il s\'est présenté au Prêtre pour être déclaré pur, il se présentera une seconde fois au Prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Et si l\'examen fait par le Prêtre constate que la dartre s\'est étendue sur la peau, le Prêtre le déclarera impur: il y a lèpre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Si un homme se trouve atteint de la lèpre, il sera conduit au Prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Et si l\'examen fait par le Prêtre constate sur la peau une élevure blanche qui a blanchi le poil, et sur l\'élevure l\'apparition de chair vive,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'c\'est une lèpre invétérée qui affecte la peau de son corps, et le Prêtre le déclarera impur, il n\'aura pas à le séquestrer, car il est impur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Mais si la lèpre se manifeste à la peau par des efflorescences et couvre toute la peau du malade de la tête aux pieds, tout ce que le Prêtre aperçoit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'et que l\'examen fait par le Prêtre constate que la lèpre couvre tout son corps, il déclarera le malade pur; étant devenu blanc partout, il est pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Mais du moment où il y aura sur lui apparition de chair vive, il tombera en état d\'impureté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'et après avoir vu la chair vive, le Prêtre le déclarera impur: la chair vive est immonde, il y a lèpre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Mais si la chair vive change et blanchit, il se présentera au Prêtre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'et si l\'examen du Prêtre constate que la partie affectée est devenue blanche, le Prêtre déclarera le malade en état de pureté; il est pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Quand sur un corps il se forme un ulcère qui ensuite guérit');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'et est remplacé par une élevure blanche, ou une tache d\'un blanc rougeâtre, le malade doit se présenter au Prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Si l\'examen du Prêtre constate l\'apparition d\'une dépression qui est au-dessous du niveau de la peau et où le poil a blanchi, le Prêtre le déclarera impur: c\'est une atteinte de la lèpre qui a éclaté en ulcère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Mais si l\'examen du Prêtre constate qu\'il n\'y a ni poil blanc ni dépression au-dessous du niveau de la peau et que la teinte en est mate, le Prêtre le séquestrera pour sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Et si le mal s\'étend sur la peau, le Prêtre le déclarera impur, il est atteint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Mais si la tache est stationnaire à sa place, sans s\'étendre, c\'est la cicatrice d\'un ulcère, et le Prêtre le déclarera pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Quand sur un corps il paraît à la peau une inflammation, et que l\'inflammation se manifeste par une tache blanche ou d\'un blanc rougeâtre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'et que l\'examen du Prêtre constate que le poil a blanchi dans la tache déprimée au-dessous du niveau de la peau, c\'est la lèpre; elle a éclaté en inflammation, et le Prêtre déclarera le malade impur: c\'est l\'affection de la lèpre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Mais si l\'examen du Prêtre constate que dans la tache le poil n\'a pas blanchi, et qu\'elle n\'est pas déprimée au-dessous du niveau de la peau et qu\'elle est mate, le Prêtre le séquestrera pour sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Et quand le Prêtre l\'aura examiné le septième jour, si le mal s\'est étendu sur la peau, le Prêtre le déclarera impur: c\'est l\'affection de la lèpre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Mais si la tache est stationnaire à sa place sans s\'étendre sur la peau, et qu\'elle soit mate, c\'est l\'élevure d\'une inflammation, et le Prêtre le déclarera pur, car c\'est la cicatrice d\'une inflammation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Et si un homme ou une femme est atteint d\'une affection à la tête ou à la barbe,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'et que l\'examen que le Prêtre fera de cette affection constate l\'apparition d\'une dépression au-dessous du niveau de la peau, dans laquelle les cheveux soient jaunâtres et grêles, le Prêtre le déclarera impur: c\'est la teigne, c\'est la lèpre de la tête ou de la barbe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Que si l\'examen que le Prêtre fera de l\'affection teigneuse, constate qu\'elle n\'offre pas de dépression au-dessous du niveau de la peau, mais qu\'il ne s\'y trouve point de poil noir, le Prêtre séquestrera pour sept jours la personne atteinte de la teigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Et si l\'examen que le Prêtre fera le septième jour, de cette affection, constate que la teigne ne s\'est pas étendue et qu\'il n\'y a point de poil jaunâtre et que la teigne n\'offre point de dépression au-dessous du niveau de la peau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'le malade se rasera, mais il ne rasera point la place teigneuse, et le Prêtre séquestrera une seconde fois pour sept jours la personne atteinte de la teigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Et si l\'examen que le Prêtre fera de la teigne le septième jour, constate qu\'elle ne s\'est pas étendue sur la peau et n\'offre pas de dépression au-dessous du niveau de la peau, il sera déclaré pur par le Prêtre; il lavera ses habits et sera pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Mais si, après qu\'il aura été déclaré pur, la teigne s\'étend sur la peau');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'et que l\'examen que le Prêtre fera de lui constate que la teigne s\'est étendue sur la peau, le Prêtre n\'aura pas à s\'inquiéter des poils jaunâtres: il est impur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Mais si la teigne conserve le même coup d\'œil, et qu\'il y ait crû des poils noirs, la teigne est guérie: il est pur et le Prêtre le déclarera pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Et si un homme ou une femme a sur la peau de son corps des taches, des taches blanches,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'et que l\'examen du Prêtre constate qu\'il y a sur la peau de leurs corps des taches d\'un blanc mat; c\'est un simple exanthème qui a poussé à la peau: il est pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Et si un homme a la tête dépilée, c\'est un chauve: il est pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Et si c\'est du côté de la face qu\'il a la tête dépilée, c\'est un front chauve: il est pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Mais si à son occiput lisse ou sur son front chauve il y a quelque place d\'un blanc rougeâtre, c\'est une éruption de la lèpre à son occiput lisse ou à son front chauve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Et si l\'examen du Prêtre constate que l\'affection forme une élevure d\'un blanc rougeâtre sur son occiput lisse ou sur son front chauve, qui offre l\'aspect de la lèpre sur la peau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'c\'est un lépreux: il est impur; le Prêtre le déclarera impur; c\'est à la tête qu\'il est atteint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Or un lépreux se trouvant être atteint du mal, ses habits doivent être déchirés et sa tête rasée, et il se voilera le menton et criera: Impur! impur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Il sera impur tout le temps qu\'il portera son mal; impur il est et il logera seul; sa demeure sera hors du camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Et si la lèpre a attaqué un vêtement, un vêtement de laine, ou un vêtement de lin, ou la chaîne');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'ou la trame de lin ou de laine, ou une fourrure, ou un objet quelconque fait de peau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'et qu\'une tache verdâtre ou rougeâtre ait paru sur le vêtement, ou la fourrure ou à la chaîne ou à la trame, ou à un ustensile quelconque de cuir, c\'est un cas de lèpre, et il faut la visite du Prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Et après l\'examen le Prêtre séquestrera pour sept jours l\'objet attaqué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Et si le septième jour le Prêtre voit que la tache s\'est étendue sur le vêtement ou sur la chaîne ou sur la trame, ou sur la fourrure ou sur l\'objet quelconque fait de cuir, l\'altération est une lèpre maligne: il est impur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Et on brûlera le vêtement, ou la toile ou l\'étoffe de laine ou de lin, ou l\'ustensile quelconque de cuir attaqué, car c\'est une lèpre maligne: il doit être brûlé au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Mais si l\'examen du Prêtre constate que le mal ne s\'est pas étendu sur le vêtement, la toile ou l\'étoffe, ou l\'ustensile quelconque de cuir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'le Prêtre ordonnera de laver la place attaquée, et le séquestrera une seconde fois pour sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Et si l\'examen que fera le Prêtre après que l\'objet aura été lavé, constate que la tache n\'a pas changé d\'aspect, quoiqu\'elle ne se soit pas étendue, l\'objet est souillé; il sera brûlé au feu: il y a corrosion à la partie rase de l\'endroit ou de l\'envers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Mais si l\'examen du Prêtre constate qu\'après le lavage la tache a pâli, il déchirera le morceau à l\'habit, au cuir, ou à la toile ou à l\'étoffe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Et si elle paraît encore sur le vêtement ou la toile ou l\'étoffe ou l\'ustensile quelconque de cuir, c\'est une éruption lépreuse: ce qui est attaqué sera brûlé au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Mais le vêtement ou la toile ou l\'étoffe ou tout ustensile de cuir que tu auras lavé et d\'où disparaîtra la tache, sera lavé une seconde fois et sera pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Telle est la loi pour le cas de lèpre sur les vêtements de laine ou de lin ou sur une toile ou une étoffe ou un ustensile quelconque de cuir, pour déclarer si l\'objet est pur ou impur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Voici le rite qu\'observera le lépreux le jour de sa purification. Il sera conduit au Prêtre, et le Prêtre sortira hors du camp;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'et, si l\'examen du Prêtre constate que le lépreux est guéri de l\'affection de la lèpre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'le Prêtre ordonnera d\'apporter pour celui qui doit se purifier, deux oiseaux vivants purs et du bois de cèdre et du vermillon et de l\'hysope.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Et le Prêtre ordonnera d\'égorger l\'un des oiseaux dans un vase de terre sur de l\'eau vive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Puis il prendra l\'oiseau vivant et le bois de cèdre et le vermillon et l\'hysope, qu\'il trempera ainsi que l\'oiseau vivant dans le sang de l\'oiseau égorgé sur l\'eau vive,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'et il fera sept aspersions sur celui qui se purifie de la lèpre et le purifiera, puis il lâchera l\'oiseau vivant en pleine campagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Et celui qui se purifie lavera ses vêtements et rasera tout son poil et se baignera dans de l\'eau, et il sera en état de pureté; après quoi il pourra entrer au camp, mais il devra pendant sept jours loger hors de sa tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Et le septième jour il rasera tout son poil, il se rasera et barbe et chevelure et sourcils, tout son poil; et il lavera ses vêtements et baignera son corps dans l\'eau, et ainsi il sera pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Et le huitième jour il apportera deux agneaux sans défaut et une brebis d\'un an sans défaut avec trois dixièmes de fleur de farine, comme offrande, trempée dans l\'huile, et un log d\'huile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Et le Prêtre purificateur présentera l\'homme qui se purifie, et ces objets devant l\'Éternel à l\'entrée de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Et le Prêtre prendra l\'un des agneaux qu\'il offrira avec le log d\'huile comme victime pour le délit, et il les agitera en oblation agitée devant l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'et il égorgera l\'agneau dans le lieu où l\'on égorge les victimes expiatoires et les holocaustes, en lieu saint; car de même que la victime expiatoire, la victime pour le délit appartient au Prêtre: elle est très sainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Et le Prêtre prendra du sang de la victime pour le délit, et il en mettra au bout de l\'oreille droite de celui qui se purifie, et au pouce de sa main droite et au grand orteil de son pied droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Et le Prêtre prendra du log d\'huile, et en versera dans sa main gauche, de lui Prêtre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'et le Prêtre trempera son doigt de droite dans l\'huile qu\'il aura dans la main gauche, et avec son doigt il fera sept aspersions d\'huile devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Et le Prêtre mettra de l\'huile qui lui reste dans la main, au bout de l\'oreille droite de l\'homme qui se purifie, et au pouce de sa main droite et au grand orteil de son pied droit, par-dessus le sang de la victime pour le délit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Et le reste de l\'huile qu\'il aura dans la main, le Prêtre le mettra sur la tête de l\'homme qui se purifie, et le Prêtre fera la propitiation pour lui devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Et le Prêtre fera le sacrifice expiatoire, et la propitiation pour celui qui se purifie en suite de sa souillure; après quoi il égorgera l\'holocauste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Et le Prêtre apportera sur l\'Autel l\'holocauste et l\'offrande, et fera la propitiation afin qu\'il soit pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Mais s\'il est pauvre et que ses ressources ne suffisent pas, il prendra un agneau comme victime de délit, et l\'offrira par agitation en propitiation pour lui, et un dixième de fleur de farine trempée d\'huile, comme offrande, et un log d\'huile,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'et deux tourterelles, ou deux jeunes pigeons que comportent ses ressources, l\'un comme victime expiatoire, l\'autre comme holocauste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Et il apportera ces choses le huitième jour au Prêtre pour sa purification à l\'entrée de la Tente du Rendez-vous devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Et le Prêtre prendra l\'agneau, victime de délit, et le log d\'huile qu\'il présentera en oblation agitée devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Et le Prêtre égorgera l\'agneau, victime de délit, et il prendra du sang de la victime de délit et en mettra au bout de l\'oreille droite de celui qui se purifie, et au pouce de sa main droite et au grand orteil de son pied droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Et le Prêtre versera de l\'huile dans sa main gauche, de lui Prêtre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'et avec son doigt de droite, le Prêtre fera de l\'huile qu\'il a dans la main gauche, sept aspersions devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Et le Prêtre mettra de l\'huile qu\'il a dans la main, au bout de l\'oreille droite de celui qui se purifie et au pouce de sa main droite et au grand orteil de son pied droit à la place où il y a du sang de la victime de délit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Et le reste de l\'huile qu\'il a dans la main, le Prêtre le mettra sur la tête de l\'homme qui se purifie, afin de faire la propitiation pour lui devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Et il sacrifiera l\'une des tourterelles ou l\'un des jeunes pigeons que comportent ressources,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'ce que comportent ses ressources, l\'un comme victime expiatoire, l\'autre en holocauste, en même temps que l\'offrande, et ainsi le Prêtre fera la propitiation pour celui, qui se purifie devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Tel est le rite que doit observer lors de sa purification celui qui est atteint de la lèpre et dont les ressources sont insuffisantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Et l\'Éternel parla à Moïse et Aaron et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Lorsque vous serez entrés au pays de Canaan que je vous donne en propriété, et que j\'enverrai une atteinte de lèpre à une maison du pays dont vous prendrez possession,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'le propriétaire de la maison viendra faire au Prêtre sa déclaration en ces termes: Je remarque comme une lèpre dans ma maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Et le Prêtre ordonnera de vider la maison avant qu\'il arrive pour examiner le mal, afin que ce qui est dans la maison ne contracte pas la souillure,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'et ensuite le Prêtre entrera pour examiner la maison. Et si l\'examen qu\'il fera du mal constate que l\'altération des parois de la maison consiste dans des cavités d\'une teinte verdâtre ou rougeâtre et déprimées au-dessous du niveau de la paroi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'le Prêtre sortira de la maison dont il passera, la porte, et qu\'il fermera pour sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Et revenant le septième jour, s\'il voit que le mal s\'est étendu sur les parois de la maison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'le Prêtre ordonnera d\'extraire les pierres attaquées et de les jeter hors de la ville dans un lieu impur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Puis l\'on raclera la maison intérieurement partout, et l\'on versera le crépi qu\'on aura raclé, hors de la ville dans un lieu impur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Et l\'on prendra d\'autres pierres que l\'on mettra à la place des pierres [extraites], et l\'on prendra d\'autre crépi pour en enduire la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Et si le mal reparaît et fait éruption dans la maison après que les pierres auront été extraites, et la maison raclée, puis recrépie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'et si le Prêtre qui reviendra voit que le mal s\'est étendu dans la maison, c\'est une lèpre maligne dont la maison est atteinte, elle est souillée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Alors on détruira la maison avec ses pierres, son bois et tout son crépi, et l\'on portera le tout hors de la ville dans un lieu impur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Et quiconque sera entré dans la maison pendant le temps de sa fermeture., sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Et quiconque aura couché dans la maison, lavera ses habits; et quiconque aura mangé dans la maison lavera ses habits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Mais si le Prêtre qui reviendra voit que le mal ne s\'est pas étendu dans la maison, une fois recrépie, le Prêtre la déclarera pure, car le mal est guéri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Et pour faire l\'expiation de la maison il prendra deux oiseaux et du bois de cèdre et du vermillon et de l\'hysope.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Et il égorgera l\'un des oiseaux dans un vase de terre sur de l\'eau vive,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'et il prendra le bois de cèdre et l\'hysope et le vermillon et l\'oiseau vivant, qu\'il trempera dans le sang de l\'oiseau égorgé et dans l\'eau vive et en fera sept aspersions contre la maison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'et fera ainsi l\'expiation de la maison avec le sang de l\'oiseau et avec l\'eau vive et l\'oiseau vivant et le bois de cèdre et l\'hysope et le vermillon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'puis il lâchera l\'oiseau vivant hors de la ville en pleine campagne et fera ainsi la propitiation pour la maison, afin qu\'elle soit pure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Telle est la loi touchant toute espèce de lèpre, et la teigne');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'et la lèpre des habits et des maisons,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'et les élevures et les dartres et les taches,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'pour déterminer les cas d\'impureté et les cas de pureté. Telle est la loi touchant la lèpre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Et l\'Éternel parla à Moïse et Aaron en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Parlez aux enfants d\'Israël et leur dites: Quiconque a un flux par sa chair, est par le fait de son flux en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Et voici les cas où ce flux est une souillure: le flux peut jaillir de sa chair ou bien sa chair fermer le passage à son flux: c\'est pour lui une souillure d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Tout lit où aura couché celui qui a un flux, est immonde, et tout meuble où il se sera assis, est immonde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Et qui touchera son lit, lavera ses vêtements et se baignera dans l\'eau, et il sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Et qui s\'assiéra sur le meuble qui aura servi de siège à celui qui a le flux, lavera ses vêtements et se baignera dans l\'eau, et il sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Et qui touchera la chair de celui qui a un flux, lavera ses vêtements, et se baignera dans l\'eau, et il sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Et si l\'homme qui a un flux crache sur quelqu\'un de pur, celui-ci lavera ses vêtements et se baignera dans l\'eau, et il sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Et tout siège de voiture où il aura été assis celui qui a un flux, sera souillé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Et quiconque touchera un objet qui aura été sous lui, sera jusqu\'au soir en état d\'impureté, et celui qui le portera, devra laver ses habits, et se baigner dans l\'eau et sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Et celui que touchera sans s\'être lavé les mains celui qui a un flux, lavera ses vêtements et se baignera dans l\'eau, et il sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Et tout vase de terre touché par celui qui a un flux sera brisé; et tout vase de bois sera rincé avec de l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'S\'il est purifié de son flux qui aura cessé, il comptera sept jours à partir de sa purification, puis il lavera ses vêtements et baignera sa chair dans de l\'eau vive; ainsi, il sera en état de pureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Et le huitième jour il se pourvoira de deux tourterelles ou de deux jeunes pigeons, et se présentera devant l\'Éternel à l\'entrée de la Tente du Rendez-vous, et il les remettra au Prêtre');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'qui les offrira, l\'un en sacrifice expiatoire, l\'autre en holocauste, faisant ainsi la propitiation pour lui devant l\'Éternel à cause du flux qu\'il aura eu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Et s\'il arrive à un homme d\'avoir un épanchement séminal, il baignera tout son corps dans l\'eau, et il sera jusqu\'au soir en état d\'impureté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'et tout vêtement et tout cuir atteint par l\'épanchement séminal sera lavé dans l\'eau et demeurera jusqu\'au soir immonde,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Et s\'il y a cohabitation d\'un homme et d\'une femme avec épanchement séminal, ils se baigneront dans l\'eau, et ils seront jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Et si une femme a un écoulement de son sang qui s\'écoule par sa chair, elle restera sept jours dans son immondicité, et quiconque la touchera, sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Et tout ce sur quoi elle couchera, son immondicité durant, sera souillé, et tout ce sur quoi elle aura été assise, sera souillé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Et quiconque touchera son lit, lavera ses vêtements et se baignera dans l\'eau, et il sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Et quiconque touchera un meuble où elle aura été assise, lavera ses vêtements et se baignera dans l\'eau, et il sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Et celui qui touchera un objet qui soit ou sur son lit ou sur le meuble où elle est assise, sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Et si un homme couchant avec elle sent le contact de son immondicité, il sera sept jours en état d\'impureté, et tout lit où il couchera, sera souillé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Si une femme a pendant longtemps un écoulement de sang, hors des époques de ses menstrues, ou bien si l\'écoulement se prolonge au delà de ses époques, elle sera en état d\'impureté pendant toute la durée de son écoulement immonde, comme aux époques des menstrues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Tout lit sur lequel elle couchera, le flux durant, sera pour elle, comme son lit menstruel, et tout meuble sur lequel elle s\'assiéra sera entaché de la même souillure que celle de ses menstrues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Quiconque les touchera, se souillera, et il lavera ses vêtements et se baignera dans l\'eau, et il sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Et quand elle sera purifiée de son flux, elle comptera sept jours après lesquels elle sera en état de pureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Et le huitième jour elle se pourvoira de deux tourterelles ou de, deux jeunes pigeons qu\'elle apportera au Prêtre à l\'entrée de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Et le Prêtre offrira l\'un en sacrifice expiatoire, et l\'autre en holocauste, faisant ainsi la propitiation devant l\'Éternel à cause du flux qui la souillait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Ainsi vous éloignerez les enfants d\'Israël de ce qui les souille, afin qu\'ils ne meurent pas dans leurs souillures, en souillant ma Résidence qui est au milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Telle est la loi pour celui qui a un flux, ou un épanchement séminal qui lui fait contracter une souillure,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'et pour celle qui a son indisposition menstruelle, et pour quiconque a un flux, soit homme, soit femme, et pour celui qui couche avec une femme en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Et l\'Éternel parla à Moïse après la mort des deux fils d\'Aaron qui moururent pour s\'être présentés devant l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'et l\'Éternel dit à Moïse: Avertis ton frère Aaron qu\'il ne doit pas pénétrer en tout temps dans le Sanctuaire derrière le rideau devant le Propitiatoire qui couvre l\'Arche, de peur qu\'il ne meure; car j\'apparais dans une nuée au-dessus du Propitiatoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Voici avec quoi Aaron entrera dans le Sanctuaire: avec un jeune taureau pour l\'expiation et un bélier pour l\'holocauste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Il s\'habillera d\'une tunique sacrée de lin, et portera sur sa chair des caleçons de lin, et il se ceindra d\'une ceinture de lin, et s\'enveloppera la tête d\'un turban de lin: ce sont les vêtements sacrés, qu\'il mettra après avoir baigné son corps dans l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Et il se fera donner par l\'Assemblée des enfants d\'Israël deux boucs pour l\'expiation et un bélier pour l\'holocauste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Et Aaron offrira son taureau expiatoire et fera la propitiation pour lui et pour sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Puis il prendra les deux boucs et les présentera devant l\'Éternel à l\'entrée de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Et il tirera au sort les deux boucs afin que le sort désigne l\'un pour l\'Éternel, l\'autre pour Azazel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Et Aaron offrira le bouc destiné à l\'Éternel, et le sacrifiera en expiation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Et le bouc destiné à Azazel sera présenté vivant devant l\'Éternel afin de faire pour lui la propitiation, puis de le lâcher dans le désert pour Azazel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Et Aaron offrira son taureau expiatoire et fera la propitiation pour lui et pour sa maison, et il égorgera son taureau expiatoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Et il prendra la cassolette qu\'il remplira de charbons ardents pris sur l\'Autel en la présence de l\'Éternel, et il remplira ses deux mains d\'encens odorant concassé, et il portera ces choses derrière le rideau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Et il jettera l\'encens sur le feu devant l\'Éternel pour que le nuage de l\'encens enveloppe le Propitiatoire qui couvre le Témoignage, afin qu\'il ne meure pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Et prenant du sang du taureau il en aspergera avec son doigt le devant du Propitiatoire à l\'Orient, et devant le Propitiatoire il fera avec son doigt sept aspersions de ce sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Et il égorgera le bouc expiatoire pour le peuple et en portera le sang derrière le rideau, et procédera avec ce sang comme il aura procédé avec le sang du taureau et fera des aspersions sur le Propitiatoire et devant le Propitiatoire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'ainsi il fera la propitiation pour le Sanctuaire à cause des impuretés des enfants d\'Israël et de leurs désobéissances dans tous leurs péchés; il en fera de même pour la Tente du Rendez-vous fixée chez eux au milieu de leurs impuretés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Et qu\'il n\'y ait personne dans la Tente du Rendez-vous, lorsqu\'il y entrera pour faire la propitiation du Sanctuaire, jusqu\'à ce qu\'il en sorte; et ainsi il fera la propitiation pour lui et pour sa maison et pour toute l\'Assemblée d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Et en sortant il ira à l\'Autel qui est devant l\'Éternel et pour lequel il fera la propitiation en prenant du sang du taureau et du sang du bouc dont il mettra aux cornes de l\'Autel tout autour;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'il l\'aspergera aussi sept fois de ce sang avec son doigt et le purifiera, pour le rendre saint, des impuretés des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Et après avoir achevé de faire la propitiation pour le Sanctuaire et la Tente du Rendez-vous et l\'Autel, il offrira le bouc vivant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Et Aaron posera ses deux mains sur la tête du bouc vivant, et il fera sur lui la confession de toutes les iniquités des enfants d\'Israël et de toutes leurs désobéissances dans tous leurs péchés, et il en chargera la tête du bouc qu\'il fera conduire au désert par un homme qui se trouvera là,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'pour que le bouc emporte sur soi toutes leurs iniquités dans une terre sauvage; c\'est au désert qu\'il le fera conduire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Et Aaron entrera dans la Tente du Rendez-vous et ôtera les habits de lin qu\'il aura mis en pénétrant dans le Sanctuaire, et les y laissera;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'et il baignera son corps dans l\'eau en lieu saint, et ayant mis son costume, il sortira et sacrifiera son holocauste et l\'holocauste du peuple, et fera la propitiation pour lui et pour le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Et il fera fumer sur l\'Autel la graisse de la victime expiatoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Et celui qui aura emmené le bouc pour Azazel, lavera ses vêtements et baignera son corps dans l\'eau; après quoi il pourra rentrer au camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Et le taureau expiatoire et le bouc expiatoire dont le sang aura été introduit pour la propitiation du Sanctuaire, seront transportés hors du camp et l\'on en brûlera au feu les peaux, la chair et la fiente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Et celui qui les aura brûlés, lavera ses vêtements et baignera son corps dans l\'eau; après quoi il pourra rentrer au camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Ce sera pour vous une règle perpétuelle: le septième mois, le dixième jour du mois, vous vous humilierez, et vous ne vaquerez à aucune affaire, ni les indigènes, ni les étrangers séjournant parmi vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Car ce jour-là propitiation sera faite pour vous afin de vous purifier: vous serez purifiés devant l\'Éternel de tous vos péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Ce sera pour vous un Sabbat solennel, et vous vous humilierez; c\'est une règle perpétuelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'La propitiation sera faite par le Prêtre qui a reçu l\'onction et qui a été installé dans le Sacerdoce comme successeur de son père, et il mettra des vêtements de lin, des vêtements sacrés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'et il fera une propitiation pour le Saint Sanctuaire, et une propitiation pour la Tente du Rendez-vous et l\'Autel, et une propitiation pour les Prêtres et tout le peuple de l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Et ce sera pour vous une règle éternelle que propitiation soit faite pour les enfants d\'Israël à cause de tous leurs péchés une fois l\'an. Et il se conforma à l\'ordre donné par l\'Éternel à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Et l\'Éternel parla à Moïse et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Parle à Aaron et ses fils et à tous les enfants d\'Israël et leur dis: Voici le commandement que l\'Éternel a donné en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'S\'il est un individu quelconque de la maison d\'Israël qui égorge dans le camp ou égorge hors du camp un bœuf ou un mouton ou une chèvre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'sans l\'amener à l\'entrée de la Tente du Rendez-vous pour l\'offrir en oblation à l\'Éternel devant la Résidence de l\'Éternel, effusion de sang sera imputée à cet homme-là; il a versé du sang et cet homme-là sera éliminé du sein de son peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'afin que les enfants d\'Israël amènent leurs victimes qu\'ils voudraient sacrifier en pleine campagne, qu\'ils les amènent devant l\'Éternel à l\'entrée de la Tente du Rendez-vous au Prêtre, et qu\'ils les offrent comme sacrifices pacifiques à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Et le Prêtre en répandra le sang à l\'Autel de l\'Éternel, à l\'entrée de la Tente du Rendez-vous, et fera fumer la graisse en parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Et ils ne sacrifieront plus leurs victimes aux boucs après lesquels ils vont se prostituant. C\'est une règle perpétuelle qu\'ils suivront dans tous leurs âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Tu leur diras encore: S\'il est un individu quelconque dans la maison d\'Israël ou parmi les étrangers en séjour chez eux qui offre un holocauste ou une victime');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'sans l\'amener à l\'entrée de la Tente du Rendez-vous pour l\'offrir en sacrifice à l\'Éternel, cet homme-là sera éliminé du sein de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Et s\'il est un individu quelconque dans la maison d\'Israël ou parmi les étrangers en séjour chez eux, qui mange d\'un sang quelconque, je tournerai ma face contre la personne qui mange le sang, et l\'éliminerai du sein de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Car l\'âme de la chair est dans le sang, et je vous l\'ai accordé à l\'Autel pour faire la propitiation en faveur de vos âmes, car c\'est par l\'âme que le sang opère la propitiation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'C\'est pourquoi je dis aux enfants d\'Israël: Personne parmi vous ne mangera de sang, même l\'étranger en séjour chez vous ne mangera pas de sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Et s\'il est un individu quelconque parmi les enfants d\'Israël ou les étrangers en séjour chez eux qui prenne à la chasse du gibier ou quelque oiseau qui se mange, il en fera couler le sang qu\'il couvrira de terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Car l\'âme de toute chair est son sang qui est uni à son âme: je dis donc aux enfants d\'Israël: Vous ne mangerez du sang d\'aucune chair, car l\'âme de toute chair, c\'est son sang: quiconque en mangera sera éliminé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Et toute personne parmi les indigènes ou les étrangers qui mangera d\'une bête morte ou déchirée, lavera ses vêtements, se baignera dans l\'eau et sera jusqu\'au soir en état d\'impureté: puis elle sera pure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Que si elle ne lave pas ses vêtements et ne se baigne pas le corps, elle sera sous le poids de sa faute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Parle aux fils d\'Israël et leur dis: Je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Vous n\'imiterez ni ce qui se pratique dans le pays d\'Egypte où vous avez habité, ni ce qui se pratique dans le pays de Canaan où je vais vous introduire, et vous ne suivrez point leurs usages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Vous pratiquerez mes lois et garderez mes statuts pour les suivre. Je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Et vous garderez mes statuts et mes lois; l\'homme qui les pratique y trouve la vie. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Nul ne s\'approchera d\'une personne de même sang que lui pour découvrir sa nudité. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Tu ne découvriras point la nudité de ton père, ni la nudité de ta mère; c\'est ta mère, tu ne découvriras point sa nudité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Tu ne découvriras point la nudité de la femme de ton père; c\'est la nudité de ton père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Tu ne découvriras point la nudité de ta sœur, fille de ton père, ou fille de ta mère, née dans la maison ou née hors de la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Tu ne découvriras point la nudité de la fille de ton fils ou de la fille de ta fille; car c\'est ta nudité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Tu ne découvriras point la nudité de la fille de la femme de ton père, engendrée par ton père; car c\'est ta sœur, tu ne découvriras point sa nudité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Tu ne découvriras point la nudité de la sœur de ton père, car c\'est le sang de ton père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Tu ne découvriras point la nudité de la sœur de ta mère, car c\'est le sang de ta mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Tu ne découvriras point la nudité du frère de ton père; tu ne t\'approcheras point de sa femme: c\'est ta tante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Tu ne découvriras point la nudité de ta bru; c\'est la femme de ton fils, tu ne découvriras point sa nudité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Tu ne découvriras point la nudité de la femme de ton frère: c\'est la nudité de ton frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Tu ne découvriras point la nudité d\'une femme et de sa fille; tu ne prendras ni la fille de son fils, ni la fille de sa fille pour découvrir sa nudité: elles sont du même sang; c\'est un attentat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Ne prends pas une sœur avec sa sœur, pour exciter la rivalité et découvrir sa nudité à côté d\'elle de son vivant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Tu ne t\'approcheras point d\'une femme pendant son impureté menstruelle pour découvrir sa nudité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Tu n\'auras point commerce avec la femme de ton prochain, pour te souiller avec elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Tu ne consentiras point à faire passer aucun de tes enfants à Moloch, afin de ne pas profaner le nom de ton Dieu. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Et tu n\'auras point commerce avec un homme comme on a commerce avec une femme; c\'est une abomination.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Tu n\'auras commerce avec aucun animal pour te souiller par là, et une femme ne se livrera point à un animal pour s\'accoupler avec lui; c\'est une horreur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Ne vous souillez par aucune de ces choses, car c\'est par tout cela que se sont souillées les nations que je vais expulser devant vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'C\'est par là que le pays s\'est souillé, aussi je lui fais porter la peine de son crime, et il vomit ses habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Gardez donc mes statuts et mes lois, et ne commettez aucune de ces abominations, ni l\'indigène, ni l\'étranger en séjour chez vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Car toutes ces abominations ont été commises par les hommes du pays qui vous y ont précédés, et le pays a été souillé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'et que le pays ne vous vomisse pas parce que vous le souillez, comme il vomit les nations qui vous ont précédés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Car tous ceux qui commettront quelqu\'une de ces abominations, les personnes qui s\'y adonneront, seront éliminées du sein de leurs tribus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Observez donc ce que vous avez à observer envers moi, afin de ne pratiquer aucun de ces abominables usages pratiqués avant vous, et de ne point vous souiller par là. Je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Parle à toute l\'Assemblée des enfants d\'Israël et dis-leur: Soyez saints, car je suis Saint, moi, l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Que chacun de vous respecte son père et sa mère et observez mes sabbats. Je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Ne vous adressez point aux idoles et ne vous faites point de dieux de fonte. Je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Et quand vous sacrifierez une victime pacifique à l\'Éternel, vous l\'offrirez de manière à être agréés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Et elle se mangera le jour du sacrifice et le lendemain, et ce qui sera resté jusqu\'au troisième jour sera brûlé au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Et si on en mange le troisième jour, elle sera un objet de dégoût, et n\'agréera point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Et qui en mangera sera sous le poids de sa faute; car il aura profané ce qui est consacré à l\'Éternel; et cette personne sera éliminée du sein de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Et quand vous récolterez les moissons de votre pays, tu ne moissonneras pas entièrement les angles de ton champ et ne ramasseras pas la glanure après ta moisson.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Et tu ne grappilleras pas ta vigne et ne recueilleras pas les grains tombés de tes ceps; tu les abandonneras au pauvre et à l\'étranger. Je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Ne dérobez point, et n\'employez ni mensonge ni fraude les uns envers les autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Et ne faites point de faux serment en mon nom, car ce serait profaner le nom de ton Dieu. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'N\'exerce sur ton prochain ni oppression ni rapine. Que le salaire du mercenaire ne séjourne pas chez toi jusqu\'au matin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Ne maudis point le sourd, et ne place point d\'achoppement devant l\'aveugle, et aie la crainte de ton Dieu. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Ne prévariquez point en jugeant, et n\'ayez ni partialité pour les petits, ni considération pour les grands: juge ton prochain selon la justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Ne va point calomniant parmi tes concitoyens, et ne t\'offre pas comme témoin contre la vie de ton prochain. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Ne hais point ton frère dans ton cœur, exprime tes griefs à ton prochain afin que, à cause de lui, tu ne te charges pas d\'un péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Ne sois ni vindicatif ni rancunier envers les enfants de ton peuple, et aime ton prochain comme toi-même. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Observez mes statuts. Vous n\'accouplerez point des bestiaux de deux espèces. Tu n\'ensemenceras point ton champ de semences de deux espèces, et tu ne porteras point d\'habits tissus de fils de deux espèces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Si un homme a commerce avec une femme et que ce soit une fille fiancée à un autre, mais qui n\'a pas été rachetée ni affranchie, il y aura châtiment; mais ils ne seront pas mis à mort, parce qu\'elle n\'est pas affranchie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Il amènera sa victime pour délit à l\'Éternel à l\'entrée de la Tente du Rendez-vous, un bélier comme victime pour délit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Et le Prêtre fera pour lui la propitiation avec le bélier, victime pour délit, devant l\'Éternel, à cause du péché qu\'il a commis, afin qu\'il obtienne son pardon pour le péché qu\'il a commis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Et quand vous serez entrés au pays et y aurez planté toute sorte d\'arbres fruitiers, vous jetterez leur prépuce, leurs [premiers] fruits; pendant trois ans vous les tiendrez pour incirconcis, et vous ne vous en nourrirez pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'et la quatrième année tous leurs fruits seront saints et serviront aux fêtes de l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'mais la cinquième année vous en mangerez les fruits — pour en augmenter la récolte à votre profit. Je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ne mangez rien avec du sang. Ne pratiquez point de charmes et ne tirez point d\'augures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Ne tondez point en rond l\'extrémité de votre chevelure, et ne rase point les coins de ta barbe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Ne vous faites point d\'incision sur le corps à propos d\'un mort et ne vous marquez d\'aucune inscription au poinçon. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Ne profane point ta fille en la prostituant, afin que le pays ne se prostitue pas et ne se remplisse pas de crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Observez mes Sabbats et révérez mon Sanctuaire. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Ne vous adressez ni aux évocateurs, ni aux devins; ne les consultez pas afin de ne pas vous souiller avec eux. Je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Lève-toi devant les cheveux blancs, et honore la personne du vieillard, et aie la crainte de ton Dieu. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Si un étranger séjourne chez vous dans votre pays, ne l\'opprimez pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'traitez comme un indigène l\'étranger qui séjourne chez vous, et aime-le comme toi-même, car vous fûtes étrangers dans le pays d\'Egypte. Je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Ne commettez d\'iniquité ni en jugeant, ni en prenant une dimension, ni en pesant, ni en mesurant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'ayez une balance juste, et des poids justes, et un épha juste et un hin juste. Je suis l\'Éternel, votre Dieu, qui vous ai tirés du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Observez ainsi tous mes statuts et toutes mes lois et pratiquez-les. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Et tu diras aux enfants d\'Israël: Quiconque parmi les enfants d\'Israël et les étrangers domiciliés en Israël donnera de ses enfants à Moloch, sera mis à mort; le peuple du pays le lapidera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Et moi, je tournerai ma face contre cet homme-là, et je l\'éliminerai du sein de son peuple pour avoir donné de ses enfants à Moloch, et ainsi souillé mon Sanctuaire et profané mon saint nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Et si le peuple du pays veut fermer les yeux sur le fait de cet homme qui a donné de ses enfants à Moloch, afin de ne point le faire mourir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'je tournerai ma face contre cet homme-là et contre sa race et je l\'éliminerai du sein de leur peuple lui et tous ceux qui le suivent dans sa prostitution pour aller se prostituer à Moloch.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Et quant à la personne qui s\'adressera aux évocateurs et aux devins pour se prostituer à leur suite, je tournerai ma face contre cette personne-là et l\'éliminerai du sein de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Conservez-vous donc saints, et soyez saints, car je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Et gardez mes statuts et vous y conformez. Je suis l\'Éternel qui veux vous sanctifier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Quiconque maudira son père ou sa mère sera mis à mort; il a maudit son père et sa mère; son sang retombe sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Et si un homme commet adultère avec la femme d\'un autre, s\'il commet adultère avec la femme de son prochain, l\'homme et la femme adultères seront mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Et si quelqu\'un a commerce avec la femme de son père, il a découvert la nudité de son père: ils seront l\'un et l\'autre mis à mort; leur sang retombe sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Et si quelqu\'un a commerce avec sa bru, ils seront l\'un et l\'autre mis à mort, ils ont commis un hideux attentat, leur sang retombe sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Et si quelqu\'un a commerce avec un homme comme on a commerce avec une femme, ils ont l\'un et l\'autre fait une chose abominable: ils seront mis à mort; leur sang retombe sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Et si quelqu\'un prend pour femmes la fille et la mère, c\'est un crime: ils seront brûlés lui et elles, afin que ce crime n\'existe pas parmi vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Et si quelqu\'un a ce commerce avec un animal, il sera mis à mort, et vous tuerez aussi l\'animal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Et si une femme se livre à un animal quelconque pour s\'accoupler avec lui, tu feras périr la femme et l\'animal; ils seront mis à mort; leur sang retombe sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Et si quelqu\'un prend pour femme sa sœur, fille de son père, ou fille de sa mère, et qu\'il voie sa nudité, et qu\'elle voie sa nudité, c\'est une infamie, et ils seront éliminés sous les yeux des enfants de leur peuple; il a découvert la nudité de sa sœur, il est sous le poids de sa faute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Et si un homme a commerce avec une femme pendant son indisposition et découvre sa nudité et met à nu la source de son sang, et qu\'elle-même montre la source de son sang, ils seront l\'un et l\'autre éliminés du sein de leur peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Et tu ne découvriras point la nudité de la sœur de ta mère ou de la sœur de ton père; car c\'est découvrir celle qui est de son sang; ils sont sous le poids de leur faute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Et si quelqu\'un a commerce avec la femme de son oncle, il a découvert la nudité de son oncle; ils sont sous le poids de leur péché; ils mourront sans enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Et si quelqu\'un prend la femme de son frère, c\'est une immondicité, il a découvert la nudité de son frère ils seront sans enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Gardez donc tous mes statuts et toutes mes lois, et pratiquez-les, et vous ne serez pas vomis par le pays où je vais vous introduire pour vous y établir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Et ne suivez pas les usages des peuples que j\'expulserai devant vous; car ils ont fait toutes ces choses et je les ai pris en dégoût, et je vous ai dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'C\'est vous qui posséderez leur pays, et je vous le donne en propriété, pays découlant de lait et de miel. Je suis l\'Éternel, votre Dieu, qui vous ai séparés des peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Et distinguez entre l\'animal pur et l\'animal impur, et entre l\'oiseau impur et l\'oiseau pur, afin que vous ne rendiez pas vos personnes abominables par les animaux et les oiseaux et tout ce qui rampe sur la terre, et que je vous ai fait distinguer comme impur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Soyez saints pour moi, car je suis Saint, moi l\'Éternel, et je vous ai séparés des peuples pour que vous soyez à moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Et s\'il se trouve parmi vous un homme ou une femme qui pratique les évocations ou la divination, ils seront mis à mort, on les lapidera, leur sang retombe sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Et l\'Éternel parla à Moïse: Parle aux Prêtres, fils d\'Aaron, et leur dis: Nul ne se mettra pour un mort en état d\'impureté dans son peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'excepté pour les plus proches parents du même sang que lui, pour sa mère ou son père, ou son fils ou sa fille, ou son frère,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'ou pour sa sœur vierge qui est avec lui, et n\'a pas encore un mari: pour celle-ci il pourra se mettre en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Comme mari il ne doit pas se mettre en état d\'impureté dans son peuple pour se profaner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Ils ne se raseront point la tête, ne se couperont point les coins de la barbe et ne se feront sur le corps point d\'incisions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Ils seront saints en vue de leur Dieu, et ne profaneront pas le nom de leur Dieu, car ils offrent les sacrifices ignés de l\'Éternel, l\'aliment de leur Dieu; qu\'ils soient donc en état de sainteté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Ils n\'épouseront ni une prostituée, ni une femme déshonorée, ils n\'épouseront pas non plus une femme répudiée par son mari, car ils sont consacrés à leur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Maintiens-les donc dans l\'état de sainteté, car ils présentent le pain de leur Dieu; qu\'ils soient sacrés pour toi, car je suis Saint, moi l\'Éternel qui veux vous rendre saints.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Et la fille d\'un personnage sacerdotal qui se met à être impudique, profane son père; elle sera brûlée au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Et le Prêtre qui a la prééminence sur ses frères, qui a reçu sur sa tête l\'effusion de l\'huile d\'onction, qui à son installation a été revêtu du costume, ne doit ni laisser sa tête échevelée ni déchirer ses vêtements,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'et il ne s\'approchera d\'aucun mort; même pour un père ou une mère il ne se mettra pas en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Et il ne sortira pas du Sanctuaire, afin de ne pas profaner le Sanctuaire de son Dieu, car il porte la consécration de l\'huile d\'onction de son Dieu. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Il prendra une femme qui ait sa virginité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'et il n\'épousera ni une veuve, ni une femme répudiée ou déshonorée ou impudique: mais il choisira une vierge dans son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Et il ne profanera point sa race au milieu de son peuple; car je suis l\'Éternel qui le consacre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Et l\'Éternel parla à Moïse et dit: Parle à Aaron en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Aucun de tes descendants dans tes générations, qui aura un défaut corporel, ne s\'approchera pour présenter le pain de son Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'l\'accès est interdit à tout homme affligé d\'un défaut corporel, qui sera ou aveugle ou boiteux ou camus ou disproportionné,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'ou qui aura une fracture à un pied ou à une main,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'ou qui sera bossu ou grêle, ou qui aura une tache blanche à l\'œil, ou la gale ou la teigne, ou les testicules écrasés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Aucun des descendants du Prêtre Aaron, qui aura un défaut corporel, ne sera admis à offrir les sacrifices ignés à l\'Éternel; il a un défaut, il ne saurait avoir accès pour présenter le pain de son Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Il pourra manger l\'aliment de son Dieu, des choses sacro-saintes et des choses saintes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Seulement il ne s\'approchera ni du rideau, ni de l\'Autel, parce qu\'il a un défaut, afin qu\'il ne profane pas mes Sanctuaires, car je suis l\'Éternel qui les consacre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Et Moïse parla à Aaron et à ses fils et à tous les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Dis à Aaron et à ses fils, qu\'afin de ne pas profaner mon saint nom, il y aura des cas où ils s\'abstiendront des choses saintes que me consacrent les enfants d\'Israël. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Dis-leur: Si dans vos générations futures l\'un quelconque de vos descendants s\'approche, étant en état d\'impureté, des choses saintes que les enfants d\'Israël consacrent à l\'Éternel, cette personne-là sera éliminée de ma présence. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Tout descendant d\'Aaron ayant la lèpre ou un flux ne mangera des choses consacrées qu\'après être redevenu pur; de même si quelqu\'un a touché ce qui a été souillé par un cadavre, ou a eu un écoulement séminal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'ou si quelqu\'un a touché un reptile qui le rende impur');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'ou un homme entaché d\'une souillure quelconque, celui qui aura touché ces objets, sera jusqu\'au soir en état d\'impureté, et ne mangera pas des choses consacrées, mais il baignera son corps dans l\'eau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'et après le coucher du soleil il sera en état de pureté et pourra ensuite manger des choses saintes; car c\'est sa nourriture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Il ne mangera pas d\'une bête morte ou déchirée afin de ne pas en être souillé. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Qu\'ils observent ainsi ce qu\'ils ont à observer envers moi, afin de ne pas se mettre sous le poids d\'un péché et de ne pas mourir pour s\'être profanés par là. Je suis l\'Éternel qui les consacre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Nul étranger ne mangera des choses saintes; celui qui n\'est qu\'attaché au service d\'un prêtre et le mercenaire ne mangeront point des choses saintes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Mais si un Prêtre a acheté un esclave à prix d\'argent, celui-ci en mangera, ainsi que l\'esclave né dans la maison; ceux-là pourront manger de son pain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Et si la fille d\'un Prêtre se marie à un homme d\'une autre tribu, elle ne pourra pas manger des choses saintes offertes par élévation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Mais si la fille d\'un Prêtre devient veuve ou est répudiée, et qu\'elle n\'ait point d\'enfants, et qu\'elle revienne habiter la maison de son père comme dans sa jeunesse, elle pourra manger du pain de son père; mais nul étranger n\'en mangera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Et si quelqu\'un par mégarde mange des choses saintes, il restituera au Prêtre la chose consacrée en y ajoutant un cinquième.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Et ils ne profaneront point les choses saintes des enfants d\'Israël, ce qu\'ils offrent par élévation à l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'par là ils les mettraient sous le poids du délit dont ils se rendraient coupables en mangeant ce qu\'ils ont consacré; car je suis l\'Éternel qui les consacre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Parle à Aaron et ses fils et à tous les enfants d\'Israël et leur dis: Tout individu de la maison d\'Israël ou des étrangers domiciliés en Israël, qui présentera en oblation quelqu\'une de leurs victimes votives ou volontaires qu\'ils offrent à l\'Éternel en holocauste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'devra prendre pour la faire agréer une victime sans défaut, un mâle parmi vos bœufs, vos moutons ou vos chèvres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'vous n\'en offrirez aucune qui ait un défaut, vous ne la feriez pas agréer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Et si quelqu\'un offre à l\'Éternel en sacrifice pacifique pour l\'acquit d\'un vœu, ou comme don volontaire, une pièce de gros ou de menu bétail, elle doit être sans défaut pour être agréée; il ne doit s\'y trouver aucun défaut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Celle qui serait aveugle, ou fracturée, ou blessée, ou ulcérée, ou atteinte de la gale ou de la teigne, vous ne la présenterez point à l\'Éternel, et n\'en ferez point sur l\'Autel de sacrifice igné à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Le bœuf ou le mouton ayant une excroissance, ou arrêté dans sa croissance, vous pourrez l\'offrir comme sacrifice volontaire, mais comme sacrifice votif il ne serait point agréé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Tout animal châtré par compression, par contusion, par extraction ou par amputation, vous ne le présenterez point à l\'Éternel, et ne le sacrifierez point dans votre pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Et vous ne recevrez de l\'enfant de l\'étranger aucune victime pareille pour l\'offrir comme pain de votre Dieu, car il y a là corruption et il y a là défaut; vous ne pourriez la faire agréer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Le bœuf, le mouton ou la chèvre qui naîtra, restera sept jours sous sa mère, et dès le huitième jour et au delà, il sera agréé comme oblation ignée pour l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Mais bœuf ou mouton vous n\'égorgerez pas le petit et sa mère le même jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Et quand vous offrirez un sacrifice de louange à l\'Éternel, offrez-le de manière à être agréé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Il se mangera le jour même, et vous n\'en garderez rien jusqu\'au matin. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Observez ainsi mes commandements et pratiquez-les. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Et ne profanez pas mon saint nom, afin que ma sainteté se montre au milieu des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Je suis l\'Éternel qui vous ai consacrés, qui vous ai tirés du pays d\'Egypte pour être votre Dieu. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Parle aux enfants d\'Israël et dis-leur: Quant aux solennités de l\'Éternel, que vous annoncerez comme saintes convocations, voici quelles sont mes solennités.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Six jours les affaires se feront, mais le septième jour ce sera jour solennel de repos, sainte convocation; vous ne vaquerez à aucune affaire, c\'est le sabbat de l\'Éternel, dans toutes vos demeures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Voici les solennités de l\'Éternel, les saintes convocations que vous annoncerez en leur temps:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'le premier mois, le quatorzième jour du mois, dans la soirée, ce sera Pâque en l\'honneur de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Et le quinzième jour de ce mois, ce sera la fête des azymes en l\'honneur de l\'Éternel: durant sept jours vous mangerez des azymes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Le premier jour vous aurez sainte convocation, vous ne ferez aucun travail d\'affaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Et durant sept jours vous offrirez à l\'Éternel des sacrifices ignés; le septième jour il y aura sainte convocation, vous ne ferez aucun travail d\'affaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Et l\'Éternel parla à Moïse et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Parle aux enfants d\'Israël et leur dis: Quand vous serez entrés au pays que je vous donne, et que vous voudrez en récolter les moissons, vous apporterez au Prêtre la gerbe, prémices de votre moisson.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Et il présentera la gerbe par agitation devant l\'Éternel en votre faveur; c\'est le lendemain du Sabbat que le Prêtre l\'offrira de cette manière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Et le jour où vous ferez agiter la gerbe, vous sacrifierez un agneau d\'un an sans défaut, en holocauste à l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'y ajoutant comme offrande deux dixièmes de fleur de farine trempée d\'huile comme sacrifice igné pour l\'Éternel, d\'un parfum agréable, et comme libation de vin, un quart de hin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Et vous ne mangerez ni pain, ni grain rôti ou concassé jusqu\'à ce jour-là même où vous aurez présenté l\'oblation à votre Dieu; c\'est une règle perpétuelle à suivre dans tous vos âges et dans toutes vos demeures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Puis comptez à partir du lendemain du Sabbat, du jour où vous offrez la gerbe par agitation, sept semaines pleines;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'jusqu\'au lendemain du septième sabbat vous compterez cinquante jours; alors vous présenterez une offrande nouvelle à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'De vos demeures vous apporterez des pains pour les offrir par agitation; il y aura deux pains de deux dixièmes de fleur de farine, boulangés avec du levain: ce seront des prémices pour l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Et outre le pain vous offrirez sept agneaux d\'un an sans défaut, et un jeune taureau et deux béliers, qui seront un holocauste pour l\'Éternel, avec leur offrande et leurs libations respectives, comme sacrifice igné d\'un parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Et vous offrirez un bouc comme victime expiatoire, et deux agneaux d\'un an comme sacrifice pacifique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Et le Prêtre les agitera avec le pain prémices, comme offrande agitée devant l\'Éternel, en même temps que les deux agneaux; ils seront consacrés à l\'Éternel pour le Prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Vous convoquerez pour cette journée-là; ce sera pour vous une sainte convocation; vous ne vaquerez à aucun travail d\'affaires; c\'est une règle perpétuelle à suivre dans toutes vos demeures et dans tous vos âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Et quand vous récolterez la moisson de votre pays, tu ne moissonneras point entièrement les angles de ton champ, et tu ne ramasseras point la glanure après ta moisson; tu l\'abandonneras au pauvre et à l\'étranger. Je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Parle aux enfants d\'Israël en ces termes: Le septième mois, le premier jour du mois, vous aurez grand jour de repos, rappel au son des trompettes, sainte convocation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Vous ne ferez aucun travail d\'affaires et vous offrirez des sacrifices ignés à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Mais le dixième jour de ce septième mois, ce sera le jour des propitiations; vous aurez alors sainte convocation, et vous humilierez vos âmes, et vous offrirez des sacrifices ignés à l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'et en ce jour-là vous ne vaquerez à aucune affaire, car c\'est le jour des propitiations destiné à faire propitiation pour vous devant l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Car toute personne qui ne s\'humiliera pas en ce jour-là, sera éliminée du sein de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Et toute personne qui ce jour-là vaquera à une affaire quelconque, je l\'exterminerai du milieu de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Vous vous abstiendrez de tout travail: c\'est une règle perpétuelle à suivre dans tous vos âges et dans toutes vos demeures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Vous aurez sabbat solennel et humilierez vos âmes le neuvième jour du mois, le soir; vous chômerez votre sabbat d\'un soir à l\'autre soir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Parle aux enfants d\'Israël et dis: Le quinzième jour de ce septième mois on fera pendant sept jours la fête des cabanes en l\'honneur de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Le premier jour il y aura sainte convocation; vous ne ferez aucun travail d\'affaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Durant sept jours vous offrirez des sacrifices ignés à l\'Éternel; le huitième jour vous aurez sainte convocation et vous offrirez un sacrifice igné à l\'Éternel: c\'est une assemblée solennelle; vous ne ferez aucun travail d\'affaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Telles sont les solennités de l\'Éternel que vous annoncerez comme saintes convocations pour offrir des sacrifices ignés à l\'Éternel, des holocaustes et des offrandes, des victimes et des libations, chaque jour l\'ordinaire du jour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'outre les Sabbats de l\'Éternel, et outre tous vos dons, toutes vos oblations votives et volontaires que vous ferez à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Mais le quinzième jour du septième mois, lorsque vous ferez rentrer les produits du pays, vous célébrerez la fête de l\'Éternel pendant sept jours: vous chômerez le premier jour et vous chômerez le huitième jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Et le premier jour vous vous pourvoirez de fruits de beaux arbres et de palmes et de rameaux d\'arbres touffus et de saules de rivière,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'et vous vous réjouirez devant l\'Éternel votre Dieu, durant sept jours. Et vous célébrerez ainsi la fête de l\'Éternel sept jours par année; c\'est une règle perpétuelle pour vos générations; vous la célébrerez le septième mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Pendant sept jours vous logerez dans des cabanes; tous les indigènes en Israël logeront dans des cabanes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'afin que vos races futures sachent que j\'ai fait loger dans des cabanes les enfants d\'Israël lorsque je les tirai du pays d\'Egypte. Je suis l\'Éternel votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Et Moïse indiqua les solennités de l\'Éternel aux enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Ordonne aux enfants d\'Israël de te fournir une pure huile d\'olives triturées pour le candélabre afin d\'y entretenir les lampes constamment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'En dehors du rideau qui voile le Témoignage dans la Tente du Rendez-vous, Aaron le tiendra en état du soir au matin devant l\'Éternel constamment; c\'est une règle perpétuelle pour vos générations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Sur le candélabre d\'or pur il rangera les lampes devant l\'Éternel constamment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Et tu prendras de la fleur de farine et en boulangeras douze galettes, chaque galette sera de deux dixièmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Et tu les rangeras en deux piles, six par pile, sur la table d\'or pur devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Et sur chaque pile tu mettras du pur encens, qui ajouté au pain sera la part destinée, le sacrifice igné pour l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Chaque sabbat il rangera toujours devant l\'Éternel ces pains, à fournir par les enfants d\'Israël comme signe d\'alliance éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Et ils appartiendront à Aaron et à ses fils qui les mangeront en lieu saint, car c\'est une part très-sainte qui lui revient sur les sacrifices ignés faits à l\'Éternel, une prestation perpétuelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Et le fils d\'une femme Israélite, lequel était fils d\'un Égyptien et vivait au milieu des enfants d\'Israël, sortit; et il s\'éleva dans le camp une querelle entre le fils de la femme Israélite et un Israélite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Et le fils de la femme Israélite outragea Le Nom et Le maudit. Sur quoi ils l\'amenèrent à Moïse. Or le nom de sa mère était Selomith, et elle était fille de Dibri, de la tribu de Dan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Et ils le mirent en prison, pour se déterminer selon la parole de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Alors l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Fais conduire le blasphémateur hors du camp, et tous ceux qui l\'ont entendu, poseront leurs mains sur sa tête, et il sera lapidé par toute l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Et tu parleras aux enfants d\'Israël en ces termes: Quiconque maudit son Dieu, est sous le poids de son péché;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'et qui outragera le nom de l\'Éternel sera mis à mort; il sera lapidé par toute l\'Assemblée, l\'étranger aussi bien, que l\'indigène; s\'il outrage Le Nom, il sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Quiconque ôtera la vie à un homme sera mis à mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'et quiconque aura ôté la vie à un animal, le remplacera, vie pour vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Si quelqu\'un porte dommage à son prochain il lui sera fait comme il a fait:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'fracture pour fracture, œil pour œil, dent pour dent, le même dommage qu\'il aura causé à un homme, lui sera rendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Et qui ôtera la vie à un animal le remplacera; mais qui ôtera la vie à un homme sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Vous aurez un seul droit, et l\'étranger et l\'indigène seront traités également, car je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Et Moïse parla aux enfants d\'Israël qui conduisirent le blasphémateur hors du camp et le lapidèrent, et les enfants d\'Israël se conformèrent à l\'ordre donné à Moïse par l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Et l\'Éternel parla à Moïse sur le mont de Sinaï en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Parle aux enfants d\'Israël et leur dis: Quand vous serez entrés au pays que je vous donne, la terre chômera un sabbat en l\'honneur de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Six années tu ensemenceras ton champ, tu tailleras ta vigne et tu en feras rentrer les produits;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'mais la septième année il y aura un sabbat solennel pour le pays, un sabbat en l\'honneur de l\'Éternel; tu n\'ensemenceras point ton champ et ne tailleras, point ta vigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Tu ne moissonneras pas le recrû de tes blés et ne vendangeras point les raisins de ta vigne non taillée: ce sera une année de repos pour la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Et vous aurez l\'usage du produit de la terre qui se repose, pour t\'en nourrir toi et ton serviteur et ta servante et ton mercenaire et ton étranger qui séjournent chez toi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'tout son produit servira à la nourriture de ton bétail et des animaux qui peuplent ton pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Puis tu compteras sept années sabbatiques, sept fois sept années: ce qui pour sept années sabbatiques te donnera une période de quarante-neuf années.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Et tu sonneras de la trompette le septième mois, le dixième jour du mois; le jour des propitiations vous sonnerez de la trompette dans tout votre pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Et vous consacrerez ainsi la cinquantième année et vous publierez l\'affranchissement dans le pays pour tous ses habitants: ce sera pour vous un Jubilé, chacun de vous rentrant dans sa propriété, et chacun de vous rentrant dans sa famille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Cette cinquantième année sera pour vous un Jubilé, vous ne sèmerez point et vous ne moissonnerez point son recrû, et ne vendangerez point la vigne alors non taillée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Car c\'est un Jubilé; il vous sera sacré, et vous tirerez de vos champs pour votre usage ce qu\'ils rendront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Dans cette année du Jubilé, chacun de vous rentrera dans sa propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Et si vous vendez quelque chose à votre prochain ou achetez quelque chose de votre prochain, ne vous molestez pas l\'un l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Tu compteras les années à partir du Jubilé pour acheter de ton prochain, et il te vendra d\'après le nombre des années de récoltes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Plus il y aura d\'années, plus ton prix d\'achat sera élevé, et moins il y aura d\'années, moindre aussi sera ton prix d\'achat; car c\'est le nombre des récoltes qu\'il te vend.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Qu\'aucun de vous ne moleste son prochain, et aie la crainte de ton Dieu; car je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Exécutez ainsi mes statuts et observez mes lois et les exécutez et vous habiterez votre pays en sécurité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Et le pays donnera ses fruits, et vous mangerez à rassasiement, et vous l\'habiterez en sécurité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Que si vous dites: Que mangerons-nous la septième année, si nous ne semons pas, et si nous ne récoltons pas nos produits?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'voici, je vous dispenserai ma bénédiction dans la sixième année qui rendra des produits pour trois ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Vous sèmerez donc la huitième année vous nourrissant des vieilles récoltes; jusqu\'à la neuvième année, en attendant que vous en ayez les récoltes, vous mangerez les vieilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Le pays ne sera point vendu de manière à être aliéné; car le pays m\'appartient, car vous êtes des étrangers et des locataires chez moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Et dans tout le pays dont vous aurez la possession, vous accorderez le droit de retrait pour les terres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Si ton frère réduit à la pauvreté vend quelqu\'une de ses possessions, et que se présente son plus proche parent qui a droit de retrait, que celui-ci puisse retraire ce qu\'a vendu son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Et si quelqu\'un n\'a personne pour faire le retrait, mais parvient à avoir et à trouver de quoi faire le retrait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'il supputera les années à partir de sa vente et remboursera l\'excédant à celui auquel il aura vendu, et il rentrera par là dans sa propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Et s\'il ne trouve pas de quoi le rembourser, ce qu\'il aura vendu restera entre les mains de l\'acheteur jusqu\'à l\'année du Jubilé, époque à laquelle celui-ci se dessaisira et l\'autre rentrera dans sa propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Et si quelqu\'un vend une maison d\'habitation dans une ville murée, le retrait pourra s\'en faire jusqu\'à la fin de l\'année où la vente aura eu lieu; ce sera l\'espace de temps accordé pour le retrait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Mais si le retrait n\'en est pas opéré avant la fin de l\'année complète, la propriété de la maison sise dans une ville murée sera définitivement dévolue à l\'acheteur et à ses descendants, et il ne s\'en dessaisira pas au Jubilé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Mais les maisons des villages qui ne sont pas entourés d\'un mur, seront considérées comme des champs; l\'on pourra en faire le retrait, et au Jubilé elles seront libérées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Quant aux villes des Lévites, aux maisons des villes qu\'ils posséderont, il y aura pour les Lévites droit perpétuel de retrait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Et si un Lévite ne fait pas retrait l\'année du Jubilé, ce qu\'il aura vendu de la maison et de la ville qu\'il possède lui reviendra, car les maisons des villes des Lévites sont leur propriété au milieu des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Et le terrain qui forme la banlieue de leurs villes ne doit point être vendu; ils en ont la possession perpétuelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Et si ton frère devient pauvre et incapable de travail à côté de toi, soutiens-le, même étranger et d\'une autre nation, afin qu\'il puisse vivre à côté de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Ne tire de lui ni intérêt, ni usure, et aie la crainte de ton Dieu, afin que ton frère puisse vivre à côté de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Tu ne lui prêteras point ton argent à intérêt, ni tes denrées à usure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Je suis l\'Éternel, votre Dieu, qui vous ai tirés du pays d\'Egypte pour vous donner le pays de Canaan, pour être votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Et si ton frère s\'appauvrit à côté de toi, et se vend à toi, tu ne lui feras pas faire de service servile;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'il sera chez toi comme mercenaire et comme étranger; il sera à ton service jusqu\'à l\'année du Jubilé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'alors il sortira de chez toi, lui et ses fils avec lui, pour rentrer dans sa famille, pour rentrer dans la propriété de ses pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Car ce sont mes serviteurs que j\'ai tirés du pays d\'Egypte; ils ne doivent point être vendus, comme on vend des esclaves.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Ne le gouverne pas avec dureté, mais aie la crainte de ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Le serviteur et la servante qu\'il t\'est permis d\'avoir, tu les prendras chez les nations qui t\'environnent; c\'est chez elles que vous pourrez acheter serviteur et servante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'De même des enfants des étrangers domiciliés chez vous, vous pouvez en acheter ainsi que de leurs familles établies chez vous, qu\'ils auront engendrées dans votre pays, et les avoir en propriété,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'et les transmettre par héritage à vos fils après vous comme une propriété, et les garder à perpétuité à votre service comme esclaves. Mais ne faites pas entre frères peser une dure autorité sur vos frères, les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Si à côté de toi un étranger ou un homme d\'une autre nation parvient à avoir de l\'aisance, et que à côté de lui ton frère s\'appauvrisse et se vende à un étranger domicilié chez toi, ou au rejeton de la famille d\'un étranger,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'on pourra, après qu\'il aura été vendu, faire son rachat; c\'est à l\'un de ses frères à faire son rachat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Le rachat sera fait soit par son oncle, soit par le fils de son oncle, ou un de ses plus proches consanguins de sa famille; ou bien s\'il trouve des ressources, il se rachètera lui-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Et alors il comptera avec son acheteur à partir de l\'année où il a été vendu jusqu\'à l\'année du Jubilé; et son prix de vente se réglera d\'après le nombre des années, qui lui seront mises au taux des années d\'un mercenaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'S\'il y a encore un grand nombre d\'années, il paiera son rachat en raison de ces années avec l\'argent qu\'il possède;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'et s\'il ne reste que peu d\'années jusqu\'au Jubilé, on les lui comptera: il paiera son rachat à proportion de ses années.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Il sera chez lui comme un mercenaire à l\'année. On ne le gouvernera pas avec dureté sous tes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Et s\'il n\'est pas racheté de la sorte, il sortira l\'année du Jubilé, lui et ses fils avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Car les enfants d\'Israël me sont des esclaves. Ils sont mes esclaves que j\'ai tirés du pays d\'Egypte. Je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Vous ne vous ferez point d\'idoles, et ne vous élèverez ni sculpture, ni statue, et ne dresserez dans votre pays point de pierres ciselées, pour les adorer, car je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Observez mes sabbats et révérez mes Sanctuaires. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Si vous suivez mes statuts, et si vous gardez mes commandements et les mettez en pratique,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'je vous donnerai vos pluies en leur saison, et la terre donnera ses produits et les arbres des campagnes leurs fruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Et le battage se prolongera pour vous jusqu\'à la vendange, et la vendange jusqu\'aux semailles, et vous mangerez votre pain à rassasiement, et vous habiterez votre pays en sécurité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Et je mettrai la paix dans le pays, et vous vous coucherez sans que personne vous fasse peur, et j\'exterminerai les bêtes féroces du pays, et l\'épée ne passera point, par votre pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Et vous poursuivrez vos ennemis et ils tomberont devant vous par l\'épée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'et cinq d\'entre vous en poursuivront cent, et cent d\'entre vous en poursuivront dix mille, et vos ennemis tomberont devant vous par l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Et je serai tourné vers vous, et vous féconderai et vous multiplierai, et je mettrai à effet l\'alliance que j\'ai avec vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Et vous mangerez des récoltes vieilles qui auront vieilli, et vous sortirez les anciennes pour faire place aux nouvelles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Et je fixerai ma résidence au milieu de vous, et mon âme n\'aura pas pour vous du dédain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'et j\'irai et viendrai parmi vous, et je serai votre Dieu et vous serez mon peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Je suis l\'Éternel, votre Dieu, qui vous ai tirés du pays des Égyptiens pour vous soustraire à leur servitude, et j\'ai brisé le joug que vous portiez, et vous ai fait marcher la tête droite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Mais si vous ne m\'obéissez pas, et ne faites pas toutes ces choses que je vous commande,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'et si, ayant du mépris pour mes statuts et du dédain pour mes lois, vous ne mettez point mes commandements en pratique et rompez l\'alliance que vous avez avec moi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'à mon tour aussi, voici ce que je vous ferai: je préposerai la terreur sur vous, la consomption et l\'ardente fièvre, qui éteignent les yeux et font languir l\'âme; et vous sèmerez en vain vos semences, et vos ennemis les mangeront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Et je tournerai ma face contre vous, et vous serez battus en face de vos ennemis, et assujettis à ceux qui vous haïssent, et vous fuirez, quoique personne ne vous poursuive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Et si amenés jusque-là vous ne m\'obéissez pas, j\'augmenterai la correction en vous frappant au septuple pour vos péchés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'et je briserai l\'orgueil que vous donne votre force, et je rendrai votre ciel pareil au fer et votre sol pareil à l\'airain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'afin que votre force s\'épuise en vain, et que votre terre ne rende pas ses récoltes, et que les arbres du pays ne donnent pas leurs fruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Et si vous en venez avec moi à la résistance, et refusez de m\'obéir, j\'augmenterai encore du septuple la peine de vos péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Et je lancerai contre vous les bêtes sauvages qui vous prendront vos enfants, détruiront vos bestiaux et vous diminueront à rendre vos routes désertes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Et si par là vous n\'êtes pas corrigés, et en venez avec moi à la résistance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'j\'en viendrai, moi aussi, avec vous à la résistance, et moi aussi je vous frapperai sept fois pour vos péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Je ferai fondre sur vous l\'épée vengeresse qui vengera mon alliance, et vous vous enfermerez dans vos villes, et j\'enverrai la peste parmi vous, et vous serez livrés aux mains de l\'ennemi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'cependant j\'aurai ruiné le pain qui soutient, de sorte que dix femmes auront assez d\'un four pour cuire votre pain, et vous vendront votre pain au poids, et que mangeant vous ne serez point rassasiés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Et si après tout cela vous ne m\'obéissez pas, et en venez avec moi à la résistance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'j\'en viendrai avec vous à une résistance irritée, et je vous châtierai aussi moi sept fois pour vos péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Et vous serez réduits à manger la chair de vos fils et à manger la chair de vos filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Et je saccagerai vos hauts lieux, et arracherai vos colonnes solaires, et j\'entasserai vos cadavres sur les débris de vos idoles, et mon âme sera dégoûtée de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Et je mettrai vos villes en ruine et ravagerai vos sanctuaires, et je ne respirerai plus vos parfums agréables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Et je dévasterai le pays, à en rendre stupéfaits vos ennemis qui l\'habiteront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Et je vous disséminerai parmi les nations, et je tiendrai l\'épée tirée derrière vous, et votre pays sera un désert, et vos villes des masures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Alors le pays acquittera la dette d\'années sabbatiques pendant tout le temps de sa désolation et de votre séjour dans le pays de vos ennemis; alors le pays se reposera et acquittera sa dette d\'années sabbatiques;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'pendant tout le temps de la désolation il aura ce repos dont il n\'aura pas joui pendant vos années sabbatiques, vous l\'habitant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Et ceux de vous qui survivront je les rendrai pusillanimes dans les pays de leurs ennemis; poursuivis par le frémissement d\'une feuille emportée, ils fuiront comme on fuit devant l\'épée, et tomberont quoique n\'étant poursuivis par personne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'ils se culbuteront les uns sur les autres comme en face de l\'épée, quoique n\'étant poursuivis par personne, et vous ne pourrez tenir tête à vos ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Et vous périrez au milieu des nations et serez dévorés par la terre de vos ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Et ceux de vous qui survivront, se fondront par l\'effet de leur crime dans les pays de vos ennemis, et se fondront même par l\'effet des crimes de leurs pères avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Alors ils confesseront le crime commis par eux et le crime de leurs pères, lorsqu\'ils se révoltèrent contre moi et en vinrent avec moi à la résistance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, '(c\'est pourquoi aussi j\'en viendrai avec eux à la résistance et les mènerai dans les pays de leurs ennemis). Dans le cas où alors leur cœur incirconcis serait humilié et où ils paieraient la dette de leur crime,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'je me souviendrai de mon alliance avec Jacob, et me souviendrai aussi de mon alliance avec Isaac et de mon alliance avec Abraham, et me souviendrai aussi du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Car le pays doit être abandonné par eux et acquitter sa dette d\'années sabbatiques, pendant qu\'ils ne le peupleront plus, et ils paieront la dette de leur crime pour avoir eu, oui, pour avoir eu du mépris pour mes lois et du dédain pour mes statuts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Cependant aussi, même pendant qu\'ils seront sur la terre de leurs ennemis, je ne les réprouverai pas et ne les rejetterai pas au point de les anéantir et de rompre l\'alliance que j\'ai avec eux; car je suis l\'Éternel, leur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Je leur garde la mémoire de l\'alliance traitée avec les ancêtres que j\'ai tirés du pays d\'Egypte à la vue des nations, pour être leur Dieu. Je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Tels sont les statuts et les édits et les lois que l\'Éternel établit entre Lui et les enfants d\'Israël sur le mont de Sinaï par l\'organe de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Parle aux enfants d\'Israël et leur dis: Lorsque l\'on consacre un vœu, si ce sont des personnes, elles appartiendront à l\'Éternel pour le prix que tu fixeras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Et en faisant l\'estimation d\'un mâle de vingt à soixante ans, tu fixeras son prix à cinquante sicles d\'argent, monnaie du Sanctuaire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'et, si c\'est une femme, tu fixeras son prix à trente sicles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'pour ceux de cinq à vingt ans tu fixeras le prix d\'un mâle à vingt sicles, et celui d\'une fille à dix sicles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'pour ceux d\'un mois à cinq ans tu fixeras le prix d\'un mâle à cinq sicles d\'argent, et celui d\'une fille à trois sicles d\'argent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'et pour ceux de soixante ans et au-dessus tu fixeras le prix d\'un mâle à quinze sicles et celui d\'une femme à dix sicles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Que s\'il n\'a pas le moyen de payer le prix que tu auras fixé, on présentera la personne au Prêtre qui fixera son prix; et le Prêtre fixera un prix proportionné aux moyens de celui qui a fait le vœu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Et si c\'est un animal de l\'espèce qu\'on offre en oblation à l\'Éternel, tout ce qu\'on en donnera à l\'Éternel, sera chose sacrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'On ne l\'échangera point, et n\'en substituera point un mauvais à un bon, ni un bon à un mauvais, et si on échange un animal contre un autre, il sera ainsi que l\'animal substitué, chose sacrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Et si c\'est un animal immonde quelconque de l\'espèce qu\'on n\'offre pas en oblation a l\'Éternel, on présentera l\'animal au Prêtre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'et le Prêtre l\'évaluera d\'après sa qualité bonne ou mauvaise; il vaudra ce que tu l\'auras évalué, toi, Prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Et si on veut le racheter, on ajoutera un cinquième au prix fixé par toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Et si c\'est sa maison que l\'on consacre à l\'Éternel, le Prêtre l\'évaluera d\'après ce qu\'elle est en bien ou en mal, et l\'on s\'arrêtera à l\'évaluation du Prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Et si le consacrant veut racheter sa maison, il ajoutera un cinquième du prix en argent fixé par toi, et elle sera sienne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Et lorsque quelqu\'un consacre à l\'Éternel quelque chose du champ qu\'il possède, ton estimation sera en proportion de ses semences, cinquante sicles d\'argent par homer de semences d\'orge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'S\'il consacre son champ dès l\'année du Jubilé, on s\'arrêtera à ton estimation;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'mais s\'il consacre son champ après le Jubilé, le Prêtre lui fera son compte en argent en proportion des années restantes jusqu\'au Jubilé, et tu les déduiras de ton prix d\'estimation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Et si le consacrant veut racheter son champ, il ajoutera le cinquième du prix en argent fixé par toi, et il lui reviendra;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'mais s\'il ne rachète pas son champ, et que le champ soit vendu à un autre, il ne peut plus être racheté,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'et ce champ, devenu franc au Jubilé, demeure consacré à l\'Éternel comme un champ qui a été dévoué; il appartiendra au Prêtre en propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Et lorsque quelqu\'un consacre à l\'Éternel le champ qui a été acquis par lui et qui n\'est point l\'un des champs de sa propriété,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'le Prêtre fera le compte de la somme à payer par lui sur ton estimation jusqu\'à l\'année du Jubilé, et le jour même il remettra le prix fixé par toi, comme consacré à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'L\'année du Jubilé le champ reviendra à celui de qui il l\'aura acheté et qui est propriétaire du fonds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Et tu feras toutes tes estimations en sicles du Sanctuaire: vingt géras font un sicle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Seulement quant aux animaux, les premiers-nés qui par la primogéniture sont dévolus à l\'Éternel, personne ne les consacrera;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'soit bœuf, soit mouton, ils sont à l\'Éternel. Mais s\'il s\'agit d\'un animal immonde, on le rachètera au taux de ton évaluation, en y ajoutant un cinquième; s\'il n\'est pas racheté, il sera vendu au taux de ton évaluation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Seulement tout ce qui est dévoué, et que quelqu\'un a dévoué à l\'Éternel, dans tout ce qu\'il possède, gens, bestiaux et champs de sa propriété, ne peut être ni vendu ni racheté; tout ce qui a été dévoué est une chose très sacrée de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Tout individu dévoué qui a été dévoué d\'entre les hommes ne peut être racheté, il doit être mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Et toute dîme du pays en graine de la terre et en fruits des arbres appartient à l\'Éternel, est consacrée à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Et si quelqu\'un veut racheter quelque chose de sa dîme, il y ajoutera le cinquième.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Et quant à toutes les dîmes de gros et de menu bétail, et de tout ce qui passe sous la houlette, la dîme est consacrée à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'On ne recherchera pas si la qualité en est bonne ou mauvaise, et on ne fera point d\'échanges, et si on échange une pièce de bétail, celle qui a été échangée et celle qui a été substituée seront choses sacrées, ne pourront se racheter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Tels sont les commandements que sur le mont de Sinaï l\'Éternel ordonna à Moïse de transmettre aux enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Et l\'Éternel parlant à Moïse dans le désert de Sinaï, dans la Tente du Rendez-vous, le premier jour du second mois, la seconde année après leur sortie du pays d\'Egypte, dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Faites le recensement de toute l\'Assemblée des enfants d\'Israël, selon leurs familles, leurs maisons patriarcales, en énumérant les noms de tous les mâles individuellement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'parmi les hommes depuis vingt ans et au-dessus vous ferez, toi et Aaron, passer à la revue selon leurs divisions tous les hommes d\'Israël qui doivent marcher comme soldats.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Et vous vous adjoindrez un homme par tribu, celui qui est le chef de sa maison patriarcale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Et voici les noms des hommes qui vous assisteront: pour Ruben, Elitsur, fils de Sedehur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'pour Siméon: Selumiel, fils de Tsurisaddaï;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'pour Juda: Nahesson, fils d\'Amminadab;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'pour Issaschar: Nethaneel, fils de Tsuhar;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'pour Zabulon: Eliab, fils de Hélon;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'pour les fils de Joseph, pour Ephraïm: Elisama, fils de Ammihud; pour Manassé: Gamliel, fils de Pedahtsur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'pour Benjamin: Abidan, fils de Gideoni;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'pour Dan: Ahieser, fils d\'Ammisadaï;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'pour Asser: Paghiel, fils de Hochran;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'pour Gad: Eliasaph, fils de Deguel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'pour Nephthali: Ahira, fils de Einan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Tels furent les commissaires de l\'Assemblée, princes des tribus de leurs pères; ils étaient les chefs des souches d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Moïse et Aaron s\'adjoignirent donc ces hommes qui sont désignés par leurs noms,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'et convoquèrent toute l\'Assemblée le premier jour du second mois. Là ils se firent inscrire dans les registres, selon leurs familles, selon leurs maisons patriarcales, avec l\'énumération des noms, depuis l\'âge de vingt ans et au-dessus, individuellement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'comme l\'Éternel l\'avait prescrit à Moïse qui les fit ainsi passer à la revue dans le désert de Sinaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Et les fils de Ruben, premier-né d\'Israël, enregistrés selon leurs familles, selon leurs maisons patriarcales, avec l\'énumération des noms, individuellement, tous les mâles de vingt ans et au-dessus, tous ceux qui devaient marcher comme soldats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'les hommes recensés dans la Tribu de Ruben furent au nombre de quarante-six mille cinq cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Sur les fils de Siméon ceux qui furent enregistrés selon leurs familles, selon leurs maisons patriarcales, les hommes recensés avec l\'énumération des noms individuellement, tous les mâles de vingt ans et au-dessus, tous ceux qui devaient marcher comme soldats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'les hommes recensés dans la Tribu de Siméon furent au nombre de cinquante-neuf mille trois cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Sur les fils de Gad, ceux qui furent enregistrés selon leurs familles, selon leurs maisons patriarcales avec l\'énumération des noms, ayant l\'âge de vingt ans et plus, tous ceux qui devaient marcher comme soldats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'les hommes recensés dans la Tribu de Gad furent au nombre de quarante-cinq mille six cent cinquante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Sur les fils de Juda, ceux qui furent enregistrés selon leurs familles selon leurs maisons patriarcales avec l\'énumération des noms, ayant l\'âge de vingt ans et plus, tous ceux qui devaient marcher comme soldats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'les hommes recensés dans la Tribu de Juda furent au nombre de soixante-quatorze mille six cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Des fils d\'Issaschar, ceux qui furent enregistrés selon leurs familles, selon leurs maisons patriarcales, avec l\'énumération des noms, ayant vingt ans et plus, tous ceux qui devaient marcher comme soldats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'les hommes recensés dans la Tribu d\'Issaschar furent au nombre de cinquante-quatre mille quatre cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Des fils de Zabulon, ceux qui furent enregistrés selon leurs familles selon leurs maisons patriarcales, avec l\'énumération des noms, ayant vingt ans et plus, tous ceux qui devaient marcher comme soldats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'les hommes recensés dans la Tribu de Zabulon furent au nombre de cinquante-sept mille quatre cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Des fils de Joseph, des fils d\'Ephraïm ceux qui furent enregistrés selon leurs familles, selon leurs maisons patriarcales, avec l\'énumération des noms, ayant vingt ans et plus, tous ceux qui devaient marcher comme soldats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'les hommes recensés dans la Tribu d\'Ephraïm furent au nombre de quarante mille cinq cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Des fils de Manassé, ceux qui furent enregistrés selon leurs familles, selon leurs maisons patriarcales, avec l\'énumération des noms, ayant vingt ans et plus, tous ceux qui devaient marcher comme soldats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'les hommes recensés dans la Tribu de Manassé furent au nombre de trente-deux mille deux cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Des fils de Benjamin, ceux qui furent enregistrés selon leurs familles, selon leurs maisons patriarcales, avec l\'énumération des noms, ayant vingt ans et plus, tous ceux qui devaient marcher comme soldats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'les hommes recensés dans la Tribu de Benjamin furent au nombre de trente-cinq mille quatre cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Des fils de Dan, ceux qui furent enregistrés selon leurs familles, selon leurs maisons patriarcales, avec l\'énumération des noms, ayant vingt ans et plus, tous ceux qui devaient marcher comme soldats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'les hommes recensés dans la Tribu de Dan furent au nombre de soixante-deux mille sept cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Des fils d\'Asser, ceux qui furent enregistrés selon leurs familles, selon leurs maisons patriarcales, avec l\'énumération des noms, ayant vingt ans et plus, tous ceux qui devaient marcher comme soldats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'les hommes recensés dans la Tribu d\'Asser furent au nombre de quarante-un mille cinq cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Des fils de Nephthali, ceux qui furent enregistrés selon leurs familles, selon leurs maisons patriarcales, avec l\'énumération des noms, ayant vingt ans et plus, tous ceux qui devaient marcher comme soldats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'les hommes recensés dans la Tribu de Nephthali furent au nombre de cinquante-trois mille quatre cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Tels sont les hommes recensés que recensèrent Moïse et Aaron et les princes d\'Israël, les douze hommes qui étaient là chacun pour sa maison patriarcale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Et tous ceux des enfants d\'Israël qui furent recensés selon leurs maisons patriarcales, de l\'âge de vingt ans et au-dessus, tous ceux qui devaient marcher comme soldats en Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'tous les hommes recensés furent au nombre de six cent trois mille cinq cent cinquante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Mais les Lévites, selon leur maison patriarcale, ne furent point compris dans le recensement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'C\'est la Tribu de Lévi seule que tu ne feras point passer à la revue et que tu ne comprendras point dans le dénombrement des enfants d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'mais tu préposeras les Lévites sur la Résidence du Témoignage, et sur tout son mobilier, et sur tout ce qui y tient; ils porteront la Tente de la Résidence et tout son mobilier et ils en feront le service et c\'est autour de la Résidence qu\'ils camperont.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Et quand la Résidence devra quitter une station, les Lévites la démonteront, et quand elle devra camper, les Lévites la dresseront; mais l\'étranger qui s\'en approchera, sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Et les enfants d\'Israël camperont chacun dans leur camp et chacun près de sa bannière, selon leurs divisions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Mais les Lévites camperont autour de la Résidence du Témoignage afin que [Sa] colère n\'éclate pas contre les enfants d\'Israël; et les Lévites monteront la garde dans la Résidence du Témoignage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Ainsi firent les enfants d\'Israël: ils se conformèrent à tous les ordres que l\'Éternel avait donnés à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Et l\'Éternel parla à Moïse et Aaron en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Les enfants d\'Israël camperont chacun sous sa bannière, vers les enseignes de sa maison patriarcale; ils camperont à l\'entour et vis-à-vis de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Sur le devant, au levant campera la bannière du camp de Juda d\'après ses divisions, dont le Prince est Nahesson, fils d\'Amminadab,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'et le corps d\'armée, ses soixante-quatorze mille six cents hommes enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'A ses côtés camperont la Tribu d\'Issaschar, savoir le Prince des fils d\'Issaschar, Nethaneel, fils de Tsuhar,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'et son corps d\'armée, ses cinquante-quatre mille quatre cents hommes enregistrés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'et la Tribu de Zabulon, savoir le Prince des fils de Zabulon, Éliab, fils de Hélon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'et son corps d\'armée, ses cinquante-sept mille quatre cents hommes enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Total des hommes enregistrés formant le camp de Juda, cent quatre-vingt-six mille quatre cents, selon leurs divisions: ils ouvriront la marche du départ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Au midi la bannière du camp de Ruben d\'après ses divisions, savoir le Prince des fils de Ruben, Élitsur, fils de Sedéur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'et son corps d\'armée, ses quarante-six mille cinq cents hommes enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Et à ses côtés camperont, la Tribu de Siméon, savoir le Prince des fils de Siméon, Selumiel, fils de Tsurisaddaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'et son corps d\'armée, ses cinquante-neuf mille trois cents hommes enregistrés:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'et la Tribu de Gad, savoir le Prince des fils de Gad, Eliasaph, fils de Reguel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'et son corps d\'armée, ses quarante-cinq mille six cent cinquante hommes enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Total des hommes enregistrés formant le camp de Ruben, cent cinquante-un mille quatre cent cinquante selon leurs divisions: ils se mettront en marche en second lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Alors partira la Tente du Rendez-vous, le camp des Lévites, au centre des campements; dans la marche ils suivront l\'ordre de leurs campements, chacun à son rang, sous sa bannière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'A l\'occident la bannière du camp d\'Ephraïm d\'après ses divisions, savoir le Prince des fils d\'Ephraïm, Elisamah, fils d\'Ammihud,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'et son corps d\'armée, ses quarante mille cinq cents hommes enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'A ses côtés camperont, la Tribu de Manassé, savoir le Prince des fils de Manassé, Gamliel, fils de Pedahtsur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'et son corps d\'armée, ses trente-deux mille deux cents hommes enregistrés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'et la Tribu de Benjamin, savoir le Prince des fils de Benjamin, Abidan, fils de Gideoni,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'et son corps d\'armée, ses trente-cinq mille quatre cents hommes enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Total des hommes enregistrés formant selon leurs divisions le camp d\'Ephraïm, cent huit mille et cent: ils se mettront en marche en troisième lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Au nord la bannière du camp de Dan d\'après ses divisions, savoir le Prince des fils de Dan, Ahiéser, fils de Ammisaddaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'et son corps d\'armée, ses soixante-deux mille sept cents hommes enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'A ses côtés camperont la Tribu d\'Asser, savoir le Prince des fils d\'Asser, Paghiel, fils de Hochran,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'et son corps d\'armée, ses quarante-un mille cinq cents hommes enregistrés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'et la Tribu de Nephthali, savoir le Prince des fils de Nephthali, Ahira, fils de Einan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'et son corps d\'armée, ses cinquante-trois mille quatre cents hommes enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Total des hommes enregistrés formant selon leurs divisions le camp de Dan, cent cinquante-sept mille six cents: ils se mettront en marche les derniers, avec leurs bannières.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Tels sont ceux des fils d\'Israël qui furent enregistrés par maisons patriarcales: le total des hommes enregistrés formant selon leurs divisions les campements, est de six cent trois mille cinq cent cinquante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Mais les Lévites ne furent point compris dans l\'enregistrement des fils d\'Israël, d\'après l\'ordre que l\'Éternel avait donné à Moïse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'et les enfants d\'Israël se conformèrent à tous les ordres que l\'Éternel avait donnés à Moïse; ainsi, ils rangèrent leurs campements par bannière, et au départ ils suivaient cet ordre, chacun celui de la famille de sa maison patriarcale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'C\'est ici l\'état de la famille d\'Aaron et de Moïse à l\'époque où l\'Éternel parla avec Moïse sur le mont Sinaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Et voici les noms des fils d\'Aaron: Nadab, le premier-né, et Abihu, Éléazar et Ithamar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Tels sont les noms des fils d\'Aaron, Prêtres revêtus de l\'onction, qui avaient été installés dans le sacerdoce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Mais Nadab et Abihu moururent devant l\'Éternel, pour avoir présenté devant l\'Éternel un feu étranger, dans le désert de Sinaï; et ils n\'avaient point de fils. C\'est pourquoi Éléazar et Ithamar exercèrent le sacerdoce sous les yeux d\'Aaron, leur père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Fais approcher la Tribu de Lévi et présente-la au Prêtre Aaron pour être à son service;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'et ils soigneront ce qui est commis à ses soins et aux soins de toute l\'Assemblée, devant la Tente du Rendez-vous, afin de faire le service de la Résidence;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'et ils auront le soin de tous les meubles de la Tente du Rendez-vous et de ce que devraient soigner les enfants d\'Israël, afin de faire le service de la Résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Et tu donneras les Lévites à Aaron et à ses fils; qu\'ils lui soient donnés, donnés en propre, sur les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Et tu établiras Aaron et ses fils pour vaquer à leur sacerdoce; l\'étranger qui s\'approchera de [l\'autel], sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Voici, j\'ai prélevé pour moi les Lévites sur les enfants d\'Israël en substitution de tous les premiers-nés, prémices de la maternité chez les enfants d\'Israël; et les Lévites seront à moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Car tout premier-né est à moi; au jour où je frappai tous les premiers-nés au pays d\'Egypte, je me suis consacré tous les premiers-nés en Israël, de l\'homme au bétail: ils sont à moi, à moi, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Et l\'Éternel parla à Moïse dans le désert de Sinaï en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Recense les enfants de Lévi selon leur maison patriarcale, selon leurs familles; tu recenseras tout mâle d\'un mois et au-dessus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Et Moïse en fit le recensement de par l\'Éternel, ainsi qu\'il lui était prescrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Et voici par leurs noms quels étaient les fils de Lévi: Gerson et Kahath et Merari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Et voici les noms des fils de Gerson selon leurs familles: Libni et Siméï;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'et les fils de Kahath selon leurs familles: Amram et Jitsehar, Hébron et Uzziel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'et les fils de Merari selon leurs familles: Mahali et Musi. Telles sont les familles de Lévi selon leur maison patriarcale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'De Gerson sont issues la famille de Libni et la famille de Siméï. Telles sont les branches des Gersonites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Les Gersonites enregistrés, le compte fait de tous les mâles d\'un mois et plus, furent au nombre de sept mille cinq cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Leurs familles campaient derrière la Résidence à l\'Occident.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Et le Prince de la maison patriarcale des Gersonites était Éliasaph, fils de Laël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Et dans la Tente du Rendez-vous les Gersonites avaient à soigner la Résidence et la Tente, sa couverture et le Rideau de la porte de la Tente du Rendez-vous');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'et les toiles du Parvis, et le Rideau de la porte du Parvis qui entoure la Résidence et l\'Autel de toute part, et ses cordeaux et tous ses ustensiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Et de Kahath sont issues la branche des Amraméens, et la branche des Jitseharites, et la branche des Hébronites et la branche des Uzzielites: telles sont les branches des Kahathites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Le compte fait de tous les mâles d\'un mois et plus, il y eut huit mille six cents individus chargés du soin du Sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Les familles des fils de Kahath campaient au côté méridional de la Résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Et le Prince de la maison patriarcale des familles des Kahathites était Élitsaphan, fils de Uzziel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Et ils avaient le soin de l\'Arche et de la Table et du Candélabre et des Autels et des Ustensiles sacrés avec lesquels ils faisaient le service, et du Rideau avec tout son appareil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Et le Prince des Princes de Lévi était Éléazar, fils du Prêtre Aaron; il était préposé sur ceux qui étaient chargés du soin du Sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'De Merari sont issues la branche des Mahalites et la branche des Musites: telles sont les branches des Merarites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Les Merarites enregistrés, le compte fait de tous les mâles d\'un mois et plus, furent au nombre de six mille deux cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Et le Prince de la maison paternelle des familles de Merari était Tsuriel, fils de Abihaïl. Ils campaient au côté septentrional de la Résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Et les fils de Merari avaient la surveillance et le soin des ais de la Résidence et de ses barres, et de ses colonnes et de leurs soubassements et de tout son mobilier et de tout ce qui y tient,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'et des colonnes du parvis dans son pourtour, et de leurs soubassements, et de leurs pieux et de leurs cordes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Et devant la Résidence, à l\'Orient, devant la Tente du Rendez-vous, au levant, campaient Moïse et Aaron avec ses fils chargés du soin du Sanctuaire pour les enfants d\'Israël; mais l\'étranger qui s\'en approcherait, devait être mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Total des Lévites recensés que Moïse et Aaron recensèrent de par l\'Éternel selon leurs familles, de tous les mâles d\'un mois et plus: vingt-deux mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Et l\'Éternel dit à Moïse: Recense tous les premiers-nés mâles parmi les enfants d\'Israël, d\'un mois et plus, et forme la somme de leurs noms.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Et prélève pour moi les Lévites, pour moi, l\'Éternel, en substitution de tous les premiers-nés des enfants d\'Israël et le bétail des Lévites, en substitution de tous les premiers-nés parmi les bestiaux des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Et Moïse se conformant à l\'ordre de l\'Éternel fit le recensement de tous les premiers-nés parmi les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Et tous les premiers-nés mâles d\'un mois et plus, le compte fait des noms, enregistrés, furent au nombre de vingt-deux mille deux cent soixante-treize.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Prélève les Lévites en substitution de tous les premiers-nés des enfants d\'Israël, et le bétail des Lévites en substitution de leur bétail, afin que les Lévites soient à moi, à moi, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Et pour la rançon des deux cent soixante-treize qui excèdent le nombre des Lévites, parmi les premiers-nés des enfants d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'tu lèveras cinq sicles par tête; tu feras payer en monnaie du Sanctuaire, le sicle à vingt géras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Et tu remettras à Aaron et à ses fils cet argent, rançon des excédants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Et Moïse leva le prix de la rançon sur ceux qui excédaient le nombre des Lévites rachetés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'sur les premiers-nés des enfants d\'Israël il leva cette somme, mille trois cent soixante-cinq sicles, en sicles du Sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Et Moïse remit le prix de la rançon à Aaron et à ses fils de par l\'Éternel, conformément à l\'ordre que l\'Éternel avait donné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Et l\'Éternel parla à Moïse et Aaron en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Forme la somme des fils de Kahath parmi les fils de Lévi, selon leurs familles, selon leurs maisons patriarcales,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'depuis les hommes de trente ans et plus jusqu\'à ceux de cinquante, de tous les hommes capables de servir pour exercer une fonction dans la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Voici l\'office des fils de Kahath dans la Tente du Rendez-vous: le soin du Lieu très-Saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'A la levée du camp, Aaron et ses fils y entreront et descendront le rideau qui le voile, et ils en couvriront l\'Arche du Témoignage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Et ils superposeront une couverture de peau de chien de mer, et ils étendront par-dessus une draperie toute d\'azur; puis ils arrangeront les barres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Et sur la Table des Pains de Présentation ils étendront une draperie d\'azur; puis ils y placeront les plats et les coupes, et les jattes et les patères des libations; le pain perpétuel devra s\'y trouver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Et sur le tout ils étendront une draperie de vermillon qu\'ils recouvriront d\'une couverture de peau de chien de mer, puis ils arrangeront les barres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Et ils prendront une draperie d\'azur dont ils couvriront le candélabre et ses lampes et ses mouchettes et ses pinces et tous ses vases à huile, employés à son service;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'et ils le mettront avec tous ses ustensiles dans une enveloppe de peau de chien de mer et le placeront sur le brancard.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Et sur l\'Autel d\'or ils étendront une draperie d\'azur et le couvriront d\'une couverture de peau de chien de mer; puis ils arrangeront les barres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Et ils prendront tous les ustensiles de service employés à faire le service dans le Sanctuaire et les mettront dans une draperie d\'azur et les couvriront d\'une couverture de peau de chien de mer; puis ils les placeront sur les brancards.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Et ils enlèveront les cendres de l\'Autel, sur lequel ils étendront une draperie de pourpre, puis sur lequel ils placeront tous ses ustensiles employés à y faire le service, les cendriers et les fourchettes et les pelles et les bassins, tous les ustensiles de l\'Autel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'et ils étendront par-dessus une couverture de peau de chien de mer; puis ils arrangeront les barres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Et lorsque Aaron et ses fils auront achevé de mettre à couvert le Sanctuaire et tous les meubles du Sanctuaire lors de la levée du camp, alors les fils de Kahath viendront pour le porter; mais ils ne toucheront pas au Sanctuaire sous peine de mort. Tel est l\'office de porteurs, des fils de Kahath dans la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Et Éléazar, fils du Prêtre Aaron, aura la surveillance de l\'huile du candélabre et de l\'encens aromatique et de l\'offrande perpétuelle et de l\'huile d\'onction, la surveillance de toute la Résidence et de tout ce qu\'elle contient, du Sanctuaire et de ses meubles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Et l\'Éternel parla à Moïse et Aaron en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'N\'exposez pas la race des familles des Kahathites à être exterminée du milieu des Lévites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'mais lorsqu\'ils s\'approcheront du Lieu très-Saint, voici comment vous vous y prendrez avec eux pour qu\'ils vivent et ne périssent point: Aaron et ses fils y pénétreront, et assigneront à chacun d\'eux son service et son fardeau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'mais ceux-ci n\'y entreront point pour voir, même un instant, le Sanctuaire et mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Forme aussi la somme des fils de Gerson, selon leurs maisons patriarcales, selon leurs familles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'tu les recenseras depuis ceux de trente ans et plus jusqu\'à ceux de cinquante, tous les hommes capables de servir pour exercer une fonction dans la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Voici les fonctions des familles des Gersonites quant à ce qu\'ils auront à faire et à ce qu\'ils auront à porter:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'ils porteront les tentures de la Résidence et la Tente du Rendez-vous avec sa couverture et la couverture de peau de chien de mer superposée à celle-ci, et le Rideau de la porte de la Tente du Rendez-vous');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'et les toiles du Parvis et le rideau de l\'ouverture de la Porte du Parvis qui entoure la Résidence et l\'Autel de toute part, et leurs cordes et toutes les pièces de leur appareil; d\'ailleurs ils feront tout ce qui doit y être fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Les Gersonites seront sous les ordres d\'Aaron et de ses fils pour toutes leurs fonctions, dans tous les cas où ils seront porteurs et officiants; vous leur remettrez la garde de tout ce qu\'ils auront à porter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Voilà l\'office des familles des Gersonites auprès de la Tente du Rendez-vous, et ce dont ils prendront soin sous la direction de Ithamar, fils du Prêtre Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Tu recenseras les fils de Merari selon leurs familles, selon leurs maisons patriarcales,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'depuis les hommes de trente ans et plus jusqu\'à ceux de cinquante, tous les hommes capables de servir pour exercer une fonction dans la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Et voici ce qu\'ils auront à soigner et à porter pour tout service de leur part dans la Tente du Rendez-vous: les ais de la Résidence et leurs traverses et ses colonnes et leurs soubassements et les piliers du pourtour du Parvis et leurs soubassements et leurs clous');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'et leurs cordes, toutes leurs pièces et tout leur appareil, et vous dresserez nominativement l\'état des pièces qu\'ils auront à soigner et à porter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Voilà l\'office des familles des Merarites, tout le service qu\'ils feront dans la Tente du Rendez-vous sous la direction de Ithamar, fils du Prêtre Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Ainsi Moïse et Aaron et les Princes de l\'Assemblée recensèrent les fils des Kahathites selon leurs familles, selon leurs maisons patriarcales,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'depuis ceux de trente ans et plus jusqu\'à ceux de cinquante ans, tous les hommes capables de servir pour exercer une fonction dans la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Et le nombre de leurs hommes recensés d\'après leurs familles fut de deux mille sept cent cinquante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Tels sont les hommes recensés des familles des Kahathites, tous servant dans la Tente du Rendez-vous, desquels le recensement fut fait par Moïse et Aaron sur l\'ordre de l\'Éternel par l\'organe de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Quant à ceux des Gersonites qui furent recensés selon leurs familles, selon leurs maisons patriarcales,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'depuis les hommes de trente ans et plus jusqu\'à ceux de cinquante ans, à tous les hommes capables de servir pour exercer une fonction dans la Tente du Rendez-vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'le nombre des Gersonites recensés selon leurs familles, selon leurs maisons patriarcales, fut de deux mille six cent trente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Tels sont les hommes recensés des familles des Gersonites, tous ceux qui faisaient un service dans la Tente du Rendez-vous, desquels Moïse et Aaron firent le recensement sur l\'ordre de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Quant à ceux des familles des Merarites qui furent recensés selon leurs familles, selon leurs maisons patriarcales,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'depuis les hommes de trente ans et plus jusqu\'à ceux de cinquante, tous les hommes capables de servir pour exercer une fonction dans la Tente du Rendez-vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'le nombre des Merarites recensés d\'après leurs familles fut de trois mille deux cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Tels sont les hommes recensés des familles des Merarites, desquels Moïse et Aaron firent le recensement sur l\'ordre de l\'Éternel par l\'organe de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Total des hommes des Lévites recensés dont le recensement fut fait par Moïse et Aaron et les Princes d\'Israël, selon leurs familles, selon leurs maisons patriarcales,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'des hommes de trente ans et plus jusqu\'à ceux de cinquante ans, tous capables de servir pour exercer une fonction et l\'office de porteurs dans la Tente du Rendez-vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'total des Lévites recensés: huit mille cinq cent quatre-vingts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Ils furent recensés sur l\'ordre de l\'Éternel par l\'organe de Moïse, chacun d\'après sa fonction et son office de porteur, ceux-là étant recensés que l\'Éternel avait indiqués à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Ordonne aux enfants d\'Israël qu\'ils aient à expulser du camp quiconque aura la lèpre ou un écoulement, et quiconque sera souillé par le contact d\'un mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'homme ou femme, vous l\'expulserez et le reléguerez au dehors du camp, afin qu\'il ne souille pas leurs campements au milieu desquels je réside.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Et ainsi firent les enfants d\'Israël; ils les reléguèrent au dehors du camp; les enfants d\'Israël se conformèrent à ce que l\'Éternel avait dit à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Dis aux enfants d\'Israël: Si un homme ou une femme commettent l\'un quelconque des péchés des hommes entre eux, faisant ainsi infidélité à l\'Éternel, et que par là cette personne tombe en état de délit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'ils confesseront le péché commis par eux et restitueront l\'objet du délit, le principal avec un cinquième en sus, qui sera remis à celui envers lequel ils sont coupables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Et si celui-ci n\'a point de proche parent auquel l\'indemnité puisse être payée, l\'indemnité payée revient à l\'Éternel, au Prêtre, indépendamment du bélier expiatoire avec lequel on fait la propitiation pour eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'De même tout don de toutes les choses consacrées par les enfants d\'Israël, qui seront offertes au Prêtre, lui appartiendra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Ce que chacun aura consacré, lui appartiendra. Ce que chacun aura donné au Prêtre lui appartiendra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Parle aux enfants d\'Israël et leur dis: Si la femme d\'un homme dévie et lui fait infidélité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'et qu\'un autre ait eu avec elle un commerce charnel, et cela à l\'insu du mari en cachette duquel elle se sera souillée, sans qu\'il y ait de témoin à sa charge et sans qu\'elle ait été prise sur le fait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'et si le mari est saisi d\'un mouvement de jalousie qui le rende jaloux de sa femme, et qu\'elle se soit vraiment souillée; ou bien s\'il est saisi d\'un mouvement de jalousie qui le rende jaloux de sa femme, et qu\'elle ne se soit point souillée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'le mari amènera sa femme au Prêtre, apportant l\'oblation de celle-ci pour elle, un dixième d\'épha de farine d\'orge; il n\'y versera point d\'huile, et n\'y ajoutera point d\'encens, car c\'est une offrande de jalousie, une offrande commémorative, appelant le souvenir du crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Puis le Prêtre la fera approcher et la mettra en la présence de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Et le Prêtre prendra de l\'eau sacrée dans un vase de terre, et le Prêtre prendra de la poussière qui sera sur le sol de la Résidence, et il la jettera dans cette eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Et le Prêtre mettra la femme en la présence de l\'Éternel, et découvrira la tête de la femme, et lui placera dans les mains l\'offrande commémorative, l\'offrande de jalousie; et dans la main du Prêtre restera l\'eau des amertumes, qui appelle la malédiction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Et le Prêtre l\'adjurera et dira à la femme: Si aucun homme n\'a habité avec toi, si tu ne t\'es pas écartée, en te souillant, de la soumission due à ton mari, sois à l\'épreuve de cette eau des amertumes qui appelle la malédiction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Mais si tu t\'es écartée de la soumission due à ton mari et si tu t\'es souillée, et si tu as reçu la cohabitation d\'un homme, autre que ton mari,...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'qu\'ainsi le Prêtre adjure la femme avec le serment d\'imprécation, et que le Prêtre dise à la femme: Que l\'Éternel te livre à la malédiction et à l\'exécration au milieu de ton peuple en mettant l\'amaigrissement à tes hanches et le gonflement dans ton sein,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'et que cette eau qui appelle la malédiction pénètre dans tes entrailles pour gonfler ton sein et amaigrir tes hanches. Et la femme répondra: Ainsi soit-il! Ainsi soit-il!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Et le Prêtre écrira ces imprécations dans un livre et les enlèvera avec l\'eau des amertumes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'et il fera boire à la femme l\'eau des amertumes qui appelle la malédiction, afin que cette eau des amertumes qui appelle la malédiction pénètre en elle pour lui être amère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Ensuite le Prêtre prendra des mains de la femme l\'offrande de jalousie, et ayant agité l\'offrande devant l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'il l\'offrira sur l\'Autel. Puis le Prêtre prendra une poignée de l\'offrande commémorative, et la brûlera sur l\'Autel; après quoi il fera boire à la femme de cette eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Et quand il aura fait boire à la femme de cette eau, si elle s\'est souillée et a fait infidélité à son mari, l\'eau qui appelle la malédiction pénétrera en elle pour lui être amère, et son sein se gonflera, et ses hanches s\'amaigriront, et cette femme sera livrée à la malédiction au milieu de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Mais si la femme ne s\'est point souillée, et qu\'elle soit pure, elle restera intacte et féconde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Telle est la loi touchant la jalousie. Si une femme s\'écarte de la soumission due à son mari et se souille,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'ou bien dans le cas où un mari serait saisi d\'un mouvement de jalousie qui le rendrait jaloux de sa femme, il fera paraître la femme devant l\'Éternel, et le Prêtre fera sur elle l\'application de cette loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Et le mari ne sera point pris à partie comme coupable, et la femme sera sous le poids de son crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Parle aux enfants d\'Israël et leur dis: Si un homme ou une femme par dévotion se lie par le vœu du Naziréen pour se donner à l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'il s\'abstiendra de vin et de cervoise, et ne boira ni vinaigre de vin, ni vinaigre de cervoise, et il ne boira d\'aucun suc exprimé du raisin, et ne mangera ni raisins frais, ni raisins secs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Pendant toute la durée de son Naziréat il ne mangera d\'aucun produit de la vigne depuis les pépins jusqu\'à la peau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Pendant toute la durée de son Naziréat le rasoir ne passera point sur sa tête; jusqu\'à l\'expiration du temps qu\'il aura voué à l\'Éternel il sera consacré, il laissera croître dans toute leur longueur les cheveux de sa tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Pendant tout le temps qu\'il aura voué à l\'Éternel, il ne s\'approchera du cadavre d\'aucun mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Pour son père et pour sa mère, pour son frère et pour sa sœur, il ne contractera aucune souillure à leur sujet après leur mort, car il porte sur sa tête la consécration de son Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Pendant toute la durée de son Naziréat il est consacré à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Et si quelqu\'un meurt près de lui subitement, à l\'improviste, ce qui souillerait sa tête consacrée, il se rasera la tête au jour de sa purification, le septième jour il la rasera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Et le huitième jour il apportera deux tourterelles ou deux jeunes pigeons au Prêtre, à la porte de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Et le Prêtre en sacrifiera un comme victime expiatoire et un en holocauste, et fera pour lui la propitiation, parce que le mort l\'a mis en état de péché; que donc il remette ce jour-là sa tête en état de sainteté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Il vouera de nouveau à l\'Éternel ses jours de Naziréat et offrira un agneau d\'un an en sacrifice pour délit, car les jours précédents ne comptent plus, son Naziréat ayant été souillé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Et voici la loi pour le Naziréen. A l\'expiration du temps de son Naziréat on l\'amènera à la Porte de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Et il présentera son oblation à l\'Éternel, un agneau d\'un an et sans défaut pour l\'holocauste, et une brebis d\'un an sans défaut pour le sacrifice expiatoire, et un bélier sans défaut pour le sacrifice pacifique,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'et une corbeille d\'azymes, de galettes de fleur de farine trempées dans l\'huile et d\'oublies azymes ointes d\'huile, et en sus l\'offrande et les libations qui accompagnent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Et le Prêtre présentera ces choses devant l\'Éternel et offrira son sacrifice expiatoire et son holocauste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Et il sacrifiera le bélier comme victime pacifique à l\'Éternel avec la corbeille d\'azymes, et le Prêtre fera son offrande et sa libation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Et à la porte de la Tente du Rendez-vous le Naziréen rasera sa tête consacrée, et prendra sa chevelure consacrée et la mettra sur le feu allumé sous la victime pacifique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Et le Prêtre prendra l\'épaule cuite de bélier, et une galette azyme dans la corbeille et une oublie azyme, qu\'il placera dans les mains du Naziréen après que celui-ci aura coupé sa chevelure consacrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Et le Prêtre agitera ces choses en oblation offerte par agitation devant l\'Éternel; elles sont sacrées et pour le Prêtre, outre la poitrine offerte par agitation, et outre l\'éclanche offerte par élévation. Après cela le Naziréen pourra boire du vin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Telle est la loi pour le Naziréen qui voue son oblation à l\'Éternel en suite de sa consécration nonobstant ce qu\'il a le moyen d\'offrir: aux termes du vœu qu\'il a fait, en sus de la loi de son Naziréat, ainsi s\'acquittera-t-il.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Parle en ces termes à Aaron et à ses fils: Voici comment vous bénirez les enfants d\'Israël: vous leur direz:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Que l\'Éternel te bénisse et te garde!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Que l\'Éternel tourne vers toi un visage serein, et te soit propice!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Que l\'Éternel ait sa face levée vers toi, et te donne la paix!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Qu\'ainsi ils fassent l\'imposition de mon nom sur les enfants d\'Israël, et je les bénirai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Et le jour où Moïse eut achevé de dresser la Résidence, lorsqu\'il l\'eut ointe et consacrée, ainsi que tous ses meubles et l\'Autel et tous ses ustensiles qu\'il oignit et consacra aussi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'il arriva que les Princes d\'Israël, chefs de leurs maisons patriarcales, eux, les Princes des Tribus qui avaient présidé au recensement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'présentèrent leurs dons devant l\'Éternel, six chariots à litière et douze bœufs, c\'est-à-dire un chariot pour deux princes et un bœuf pour un prince; ils les amenèrent devant la Résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Accepte d\'eux ces dons; ils seront employés au service de la Tente du Rendez-vous, et répartis-les entre les Lévites en raison des fonctions de chacun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Alors Moïse reçut les chariots et les bœufs et les répartit entre les Lévites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Il donna deux chariots et quatre bœufs aux fils de Gerson en raison de leurs fonctions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Et aux fils de Merari il donna quatre chariots et huit bœufs en raison de leurs fonctions que dirigeait Ithamar, fils du Prêtre Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Mais il ne donna rien aux fils de Kahath, parce qu\'ils étaient chargés de la fonction de porter le Sanctuaire sur l\'épaule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Et les Princes apportèrent leurs oblations pour la dédicace de l\'Autel, le jour de l\'onction de l\'Autel, devant lequel les Princes apportèrent leurs oblations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Et l\'Éternel dit à Moïse: Les Princes viendront chacun à son tour, un par jour, apporter leur oblation pour la dédicace de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Et celui qui le premier jour apporta son oblation fut Nahesson, fils de Amminadab, de la Tribu de Juda;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'voici son oblation: un plat d\'argent du poids de cent trente sicles, une jatte d\'argent de soixante-dix sicles, sicles du Sanctuaire, l\'un et l\'autre remplis de fleur de farine trempée d\'huile, pour l\'offrande;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'une coupe de dix sicles d\'or remplie d\'encens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'un jeune taureau, un bélier, un agneau d\'un an pour l\'holocauste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'un bouc velu pour le sacrifice expiatoire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'et pour le sacrifice pacifique deux taureaux, cinq béliers, cinq boucs, cinq agneaux d\'un an. Telle fut l\'oblation de Nahesson, fils de Amminadab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Le second jour offrande de Nethanéel, fils de Tsuhar, Prince d\'Issaschar;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'il présenta pour son oblation, un plat d\'argent du poids de cent trente sicles, une jatte d\'argent de soixante-dix sicles, sicles du Sanctuaire, l\'un et l\'autre remplis de fleur de farine trempée d\'huile pour l\'offrande;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'une coupe de dix sicles d\'or remplie d\'encens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'un jeune taureau, un bélier, un agneau d\'un an pour l\'holocauste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'un bouc velu pour le sacrifice expiatoire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'et pour le sacrifice pacifique deux taureaux, cinq béliers, cinq boucs, cinq agneaux d\'un an. Telle fut l\'oblation de Nethanéel, fils de Tsuhar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Le troisième jour offrande du Prince des fils de Zabulon, Eliab, fils de Hélon;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'voici son oblation: un plat d\'argent du poids de cent trente sicles, une jatte d\'argent de soixante-dix sicles, sicles du Sanctuaire, l\'un et l\'autre remplis de fleur de farine trempée d\'huile, pour l\'offrande;');
