INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'et pour le sacrifice pacifique deux taureaux, cinq béliers, cinq boucs, cinq agneaux d\'un an. Telle fut l\'oblation de Eliab, fils de Hélon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Le quatrième jour vint le Prince des fils de Ruben, Elitsur, fils de Sedéur;');
