INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Le septième jour vint le Prince des fils d\'Ephraïm, Elisamah, fils de Ammihud;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'voici son oblation: un plat d\'argent du poids de cent trente sicles, une jatte d\'argent de soixante-dix sicles, sicles du Sanctuaire, l\'un et l\'autre remplis de fleur de farine trempée d\'huile, pour l\'offrande;');
