INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'et pour le sacrifice pacifique deux taureaux, cinq béliers, cinq boucs, cinq agneaux d\'un an. Telle fut l\'oblation de Gamliel, fils de Pedahtsur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Le neuvième jour vint le Prince des fils de Benjamin, Abidan, fils de Gidéoni;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'voici son oblation: un plat d\'argent du poids de cent trente sicles, une jatte d\'argent de soixante-dix sicles, sicles du Sanctuaire, l\'un et l\'autre remplis de fleur de farine trempée d\'huile, pour l\'offrande;');
