INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'un jeune taureau, un bélier, un agneau d\'un an pour l\'holocauste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'un bouc velu pour le sacrifice expiatoire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'et pour le sacrifice pacifique deux taureaux, cinq béliers, cinq boucs, cinq agneaux d\'un an. Telle fut l\'oblation de Abidan, fils de Gidéoni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Le dixième jour vint le Prince des fils de Dan, Ahiézer, fils de Ammisaddaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'voici son oblation: un plat d\'argent du poids de cent trente sicles, une jatte d\'argent de soixante-dix sicles, sicles du Sanctuaire, l\'un et l\'autre remplis de fleur de farine trempée d\'huile, pour l\'offrande;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'une coupe de dix sicles d\'or remplie d\'encens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'un jeune taureau, un bélier, un agneau d\'un an pour l\'holocauste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'un bouc velu pour le sacrifice expiatoire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'et pour le sacrifice pacifique deux taureaux, cinq béliers, cinq boucs, cinq agneaux d\'un an. Telle fut l\'oblation de Ahiézer, fils de Ammisaddaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Le onzième jour vint le Prince des fils d\'Asser-Paghiel, fils de Hochran;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'voici son oblation: un plat d\'argent du poids de cent trente sicles, une jatte d\'argent de soixante-dix sicles, sicles du Sanctuaire, l\'un et l\'autre remplis de fleur de farine trempée d\'huile, pour l\'offrande;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'une coupe de dix sicles d\'or remplie d\'encens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'un jeune taureau, un bélier, un agneau d\'un an pour l\'holocauste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'un bouc velu pour le sacrifice expiatoire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'et pour le sacrifice pacifique deux taureaux, cinq béliers, cinq boucs, cinq agneaux d\'un an. Telle fut l\'oblation de Paghiel, fils de Hochran.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Le douzième jour vint le Prince des fils de Nephthali, Ahira, fils de Einan;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'voici son oblation: un plat d\'argent du poids de cent trente sicles, une jatte d\'argent de soixante-dix sicles, sicles du Sanctuaire, l\'un et l\'autre remplis de fleur de farine trempée d\'huile, pour l\'offrande;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'une coupe de dix sicles d\'or remplie d\'encens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'un jeune taureau, un bélier, un agneau d\'un an pour l\'holocauste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'un bouc velu pour le sacrifice expiatoire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'et pour le sacrifice pacifique deux taureaux, cinq béliers, cinq boucs, cinq agneaux. Telle fut l\'oblation de Ahira, fils de Einan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Tels sont les dons apportés par les Princes d\'Israël pour la dédicace de l\'Autel, le jour où il fut oint: douze plats d\'argent, douze jattes d\'argent, douze coupes d\'or,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'chaque plat d\'argent de cent trente sicles, et chaque jatte d\'argent de soixante-dix sicles; poids total de l\'argent des ustensiles: deux mille quatre cents sicles, sicles du Sanctuaire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'douze coupes d\'or remplies d\'encens, chaque coupe de dix sicles, sicles du Sanctuaire; poids total de l\'or des coupes: cent vingt sicles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Total des taureaux pour l\'holocauste: douze taureaux, plus douze béliers, douze agneaux d\'un an et leur addition d\'offrande, et douze boucs velus pour le sacrifice expiatoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Total des taureaux pour le sacrifice pacifique: vingt-quatre taureaux, plus soixante béliers, soixante boucs, soixante agneaux d\'un an. Tels furent les dons apportés pour la dédicace de l\'Autel après qu\'il fut oint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Et lorsque Moïse entrait dans la Tente du Rendez-vous pour parler avec Lui, il entendait la voix qui lui parlait de dessus le Propitiatoire placé sur l\'Arche du Témoignage, du milieu des deux Chérubins, et il Lui parlait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Parle à Aaron et lui dis: En plaçant les lampes fais en sorte que les sept lampes jettent leur lumière en face, en avant du candélabre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Et ainsi fit Aaron: il plaça les lampes de face, en avant du candélabre, comme l\'Éternel l\'ordonnait à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Et quant à la façon du candélabre, il était d\'or et fait au tour; jusqu\'à sa tige et ses fleurs, c\'était un ouvrage fait au tour, il avait été travaillé d\'après le modèle que l\'Éternel en avait montré à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Prends les Lévites du sein des enfants d\'Israël et purifie-les.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Et voici comment tu t\'y prendras avec eux pour les purifier; fais sur eux une aspersion d\'eau lustrale, et qu\'ils passent le rasoir sur tout leur corps et lavent leurs vêtements et se purifient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Puis ils prendront (pour l\'holocauste) un jeune taureau et l\'offrande qu\'on y joint, de la fleur de farine trempée d\'huile, et tu prendras un autre jeune taureau pour le Sacrifice expiatoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Et tu amèneras les Lévites devant la Tente du Rendez-vous, et tu convoqueras toute l\'Assemblée des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Et tu amèneras les Lévites devant l\'Éternel et les enfants d\'Israël imposeront les mains aux Lévites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Et Aaron offrira par agitation de la part des enfants d\'Israël, les Lévites, à l\'Éternel, pour les mettre au service de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Et les Lévites poseront leurs mains sur la tête des taureaux, dont tu offriras l\'un en sacrifice expiatoire et l\'autre en holocauste à l\'Éternel, afin de faire la propitiation pour les Lévites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Et tu feras tenir les Lévites debout devant Aaron et ses fils et tu les offriras à l\'Éternel par agitation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Ainsi tu sépareras les Lévites des enfants d\'Israël, afin que les Lévites soient à moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Et après cela les Lévites auront l\'entrée pour faire le service dans la Tente du Rendez-vous. C\'est ainsi que tu les purifieras et les offriras par agitation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Car ils me sont donnés, donnés en propre sur les enfants d\'Israël; je les ai prélevés pour moi en substitution des prémices de la maternité de tous les premiers-nés parmi les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Car à moi sont tous les premiers-nés parmi les enfants d\'Israël, et des hommes et des bestiaux: lorsque je frappai tous les premiers-nés dans le pays d\'Egypte, je me les suis consacrés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'et j\'ai pris les Lévites en substitution de tout premier-né chez les enfants d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'et j\'ai donné les Lévites en propre à Aaron et à ses fils sur les enfants d\'Israël, afin qu\'ils accomplissent le service des enfants d\'Israël dans la Tente du Rendez-vous, et qu\'ils fassent la propitiation pour les enfants d\'Israël, afin qu\'une plaie ne survienne pas aux enfants d\'Israël, s\'ils s\'approchaient du Sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Et Moïse et Aaron et toute l\'Assemblée des enfants d\'Israël procédèrent ainsi à l\'égard des Lévites; ils procédèrent à leur égard conformément aux ordres que l\'Éternel avait donnés à Moïse touchant les Lévites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Et les Lévites firent leur expiation, et lavèrent leurs vêtements; et Aaron les offrit à l\'Éternel par agitation, et Aaron fit la propitiation pour eux, afin de les purifier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Et après cela les Lévites entrèrent pour faire leur service dans la Tente du Rendez-vous sous les yeux d\'Aaron et de ses fils; ils procédèrent à leur égard conformément aux ordres que l\'Éternel avait donnés à Moïse touchant les Lévites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Ceci concerne les Lévites: L\'homme âgé de vingt-cinq ans et plus entrera au service pour exercer une fonction dans la Tente du Rendez-vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'et celui qui aura cinquante ans, se retirera du service et n\'exercera plus de fonctions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Il pourra être servant de ses frères dans la Tente du Rendez-vous, et soigner ce qui doit être soigné, mais il ne sera plus en fonction. C\'est ainsi que tu procéderas à l\'égard des Lévites quant à leurs offices.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Et l\'Éternel parla à Moïse dans le désert de Sinaï, la seconde année après leur sortie du pays d\'Egypte, au premier mois, et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Les enfants d\'Israël célébreront la Pâque en son temps fixé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Le quatorzième jour de ce mois-ci dans la soirée vous la célébrerez en son temps fixé; vous la célébrerez selon toutes ses règles et tous ses rites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Et Moïse annonça aux enfants d\'Israël qu\'ils avaient à célébrer la Pâque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Et la Pâque fut célébrée au premier mois, le quatorzième jour du mois dans la soirée, au désert de Sinaï; les enfants d\'Israël se conformèrent à tous les ordres que l\'Éternel avait donnés à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Et il y eut des hommes qui, se trouvant en état d\'impureté à cause d\'un mort, ne pouvaient célébrer la Pâque ce jour-là; ils se présentèrent devant Moïse et devant Aaron ce jour-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Et ces mêmes hommes lui dirent: Nous nous trouvons en état d\'impureté à cause d\'un mort, pourquoi faut-il que nous soyons empêchés d\'offrir l\'oblation de l\'Éternel en son temps avec les enfants d\'Israël?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Et Moïse leur dit: Attendez que j\'aie appris ce que l\'Éternel prescrit pour votre cas particulier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Parle aux enfants d\'Israël et leur dis: Celui d\'entre vous ou vos descendants, qui se trouve en état d\'impureté à cause d\'un mort, ou fait un voyage lointain, devra célébrer la Pâque en l\'honneur de l\'Éternel:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'c\'est au second mois, le quatorzième jour du mois, dans la soirée qu\'ils la célébreront; ils la mangeront avec des azymes et des herbes amères;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'on n\'en gardera aucun reste jusqu\'au matin, et on n\'en brisera aucun os; on la célébrera selon toutes les règles de la Pâque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Quant à celui qui, se trouvant en état de pureté et n\'étant point en voyage, manquera de célébrer la Pâque, cette personne-là sera éliminée de son peuple pour ne pas avoir offert l\'oblation de l\'Éternel en son temps; cet homme-là sera sous le poids de son péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Et si un étranger séjourne chez vous, il célébrera la Pâque en l\'honneur de l\'Éternel; il la célébrera selon la règle et le rite de la Pâque. Il n\'y aura qu\'une même règle pour vous, pour l\'étranger et pour l\'indigène.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Et le jour où la Résidence fut dressée, la nuée couvrit la Résidence de la Tente du Témoignage, et le soir il y eut sur la Résidence comme une lueur de feu jusqu\'au matin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Et il en était toujours ainsi; [de jour] la nuée la couvrait, et de nuit c\'était une lueur de feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Et à mesure que la nuée s\'élevait de dessus la Tente, les enfants d\'Israël partaient aussitôt pour aller camper dans le lieu où la nuée s\'arrêtait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'C\'est sur l\'ordre de l\'Éternel que les enfants d\'Israël partaient, et sur l\'ordre de l\'Éternel ils posaient leur camp, et stationnaient tout le temps que la nuée demeurait sur la Résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Et quand la nuée séjournait longtemps sur la Résidence, les enfants d\'Israël observaient les rites du culte de l\'Éternel, et ne se mettaient point en marche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Et dans le cas où la nuée ne restait que peu de jours sur la Résidence, les enfants d\'Israël campaient sur l\'ordre de l\'Éternel, et sur l\'ordre de l\'Éternel ils partaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Et dans le cas où la nuée s\'arrêtait du soir au matin, puis s\'élevait le matin, ils partaient;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'ou si la nuée s\'élevait après un jour et une nuit, ils partaient; que ce fût deux jours, ou un mois ou plus longtemps, tant que la nuée séjournait sur la Résidence, les enfants d\'Israël restaient campés et ne partaient point; mais quand elle s\'élevait, ils partaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Sur l\'ordre de l\'Éternel ils campaient, et sur l\'ordre de l\'Éternel ils partaient; ils observaient les rites du culte de l\'Éternel sur l\'ordre de l\'Éternel transmis par Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Fais-toi deux trompettes d\'argent; tu leur donneras la façon d\'ouvrage fait autour; elles te serviront pour convoquer l\'Assemblée, et indiquer le décampement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Et quand on en sonnera [des deux], toute l\'Assemblée se réunira auprès de toi à la porte de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Et quand on sonnera d\'une seule, les Princes, les chefs des divisions d\'Israël se réuniront auprès de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Et quand vous sonnerez la charge, ceux-là lèveront le camp, qui campent à l\'orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Et quand vous sonnerez la charge pour, la seconde fois, ceux-là lèveront le camp, qui campent au midi; vous sonnerez la charge lors de votre décampement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Mais pour convoquer l\'Assemblée, vous sonnerez des trompettes, mais non pas la charge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Et ce sont les fils d\'Aaron, les Prêtres, qui sonneront des trompettes; elles sont instituées à perpétuité chez vous pour vos âges futurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Et quand vous vous mettrez en campagne dans votre pays contre vos agresseurs qui vous attaqueront, vous sonnerez la charge avec les trompettes, et votre souvenir sera rappelé devant l\'Éternel, votre Dieu, et vous serez délivrés de vos ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Et dans vos jours de réjouissance, et dans vos solennités et à vos Nouvelles Lunes vous sonnerez des trompettes en offrant vos holocaustes et vos sacrifices pacifiques, afin qu\'elles rappellent votre souvenir devant votre Dieu. Je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Et la seconde année, au second mois, le vingtième jour du mois, la nuée s\'éleva de dessus la Résidence du Témoignage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Et les enfants d\'Israël partirent, selon l\'ordre de leurs départs, du désert de Sinaï, et la nuée s\'arrêta dans le désert de Paran.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Ils firent ce premier décampement sur l\'ordre de l\'Éternel transmis par Moïse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'et d\'abord partit la bannière du camp des fils de Juda rangés par divisions, et leur corps d\'armée était sous Nahesson, fils de Amminadab,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'et le corps d\'armée de la Tribu des fils d\'Issaschar, sous Nethanéel, fils de Tsuhar,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'et le corps d\'armée de la Tribu des fils de Zabulon, sous Eliab, fils de Hélon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Puis la Résidence fut démontée, et partirent les fils de Gerson, et les fils de Merari, portant la Résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Alors partit la bannière du camp de Ruben rangé par divisions, et son corps d\'armée était sous Elitsur, fils de Sedéur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'et le corps d\'armée de la Tribu des fils de Siméon, sous Selumiel, fils de Tsurisaddaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'et le corps d\'armée de la Tribu des fils de Gad, sous Eliasaph, fils de Deguel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Puis partirent les Kahathites portant le Sanctuaire; et [les premiers] dressaient la Résidence en attendant leur arrivée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Alors partit la bannière du camp des fils d\'Ephraïm rangés par divisions, et leur corps d\'armée était sous Elisamah, fils de Ammihud,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'et le corps d\'armée de la Tribu des fils de Manassé, sous Gamliel, fils de Pedahtsur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'et le corps d\'armée de la Tribu des fils de Benjamin, sous Abidan, fils de Gidéoni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Ensuite partit la bannière du camp des fils de Dan fermant la marche de tous les campements et rangés par divisions, et leur corps d\'armée était sous Ahiézer, fils de Aramisaëdaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'et le corps d\'armée de la Tribu des fils d\'Asser, sous Paghiel, fils de Hochram,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'et le corps d\'armée de la Tribu des fils de Néphthali, sous Ahira, fils de Einan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Tel fut l\'ordre du décampement des enfants d\'Israël selon leurs divisions, c\'est ainsi qu\'ils se mirent en marche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Alors Moïse dit à Hobab, fils de Reguel, le Madianite, beau-père de Moïse: Nous marchons vers le lieu dont l\'Éternel a dit: Je veux vous le donner; viens avec nous, et nous te ferons du bien; car l\'Éternel a promis de faire du bien à Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Et il lui répondit: Je n\'irai point; mais je veux regagner mon pays et ma patrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Et Moïse reprit: Ne nous quitte donc pas, puisque en effet tu connais les lieux propres à nos campements dans le désert: sois donc notre œil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Et si tu viens avec nous, et quand sera arrivé ce bien que l\'Éternel veut nous faire, nous te ferons du bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Ils partirent ainsi de la montagne de l\'Éternel, et firent trois journées de marche, et l\'Arche de l\'alliance de l\'Éternel avait sur eux l\'avance de trois journées de marche pour leur découvrir une station.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Et la nuée de l\'Éternel était au-dessus d\'eux pendant le jour, lorsqu\'ils partaient de leur campement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Et au départ de l\'Arche Moïse disait: Lève-toi, Éternel! et que tes ennemis soient dissipés, et ceux qui te haïssent, mis en fuite devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Et quand elle s\'arrêtait, il disait: Ramène, Éternel, les myriades des divisions d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Et le peuple murmura comme des gens en détresse, aux oreilles de l\'Éternel, et l\'Éternel l\'entendit, et sa colère s\'enflamma, et un feu envoyé par l\'Éternel s\'alluma parmi eux, et fit des ravages à l\'extrémité du camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Alors le peuple éleva ses cris vers Moïse, et Moïse intercéda auprès de l\'Éternel, et le feu s\'abattit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Et ce lieu reçut le nom de Tabhera (Incendie), parce que le feu de l\'Éternel les avait incendiés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Et la tourbe qui était parmi eux fut saisie de convoitise, et même les enfants d\'Israël se remirent à pleurer et dirent: Qui nous donnera de la chair pour aliment?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Nous avons le souvenir des poissons que nous mangions en Egypte gratis, des concombres et des pastèques et du poireau et des oignons et des aulx,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'et maintenant nous sommes à jeun, il n\'y a rien; nous ne voyons que de la manne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Or la manne était comme de la graine de coriandre et avait l\'aspect du bdellium.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Le peuple courait ça et là et la recueillait, et la broyait avec les meules, ou la pilait dans des mortiers, et la faisait cuire dans des chaudières, et la façonnait en galettes; et elle avait le goût d\'oublies à l\'huile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Et quand la rosée tombait la nuit dans le camp, la manne y tombait en même temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Et Moïse entendit le peuple qui pleurait dans ses familles, chacun à la porte de sa tente; alors la colère de l\'Éternel s\'enflamma fort ce dont Moïse fut mécontent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Et Moïse dit à l\'Éternel: Pourquoi traites-tu si mal ton serviteur, et pourquoi ne trouvé-je pas grâce à tes yeux, que tu m\'imposes le fardeau de tout ce peuple?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Est-ce que j\'ai conçu tout ce peuple? l\'ai-je enfanté pour que tu me dises: Porte-le dans ton sein, comme le nourricier porte le nourrisson, au pays que j\'ai promis par serment à ses pères?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'D\'où puis-je tirer de la chair pour en nourrir tout ce peuple? Car ils s\'adressent à moi en pleurant: Donne-nous de la chair à manger!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Je ne saurais à moi seul être chargé de tout ce peuple, car c\'est au-dessus de mes forces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Que si tu veux me traiter ainsi, ah! si j\'ai trouvé grâce à tes yeux, fais-moi périr, afin que je ne voie pas ma misère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Alors l\'Éternel dit à Moïse: Choisis-moi soixante-dix hommes parmi les Anciens d\'Israël que tu connais pour être Anciens du peuple et préposés sur lui, et amène-les à la Tente du Rendez-vous, et qu\'ils s\'y présentent avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Et je descendrai et parlerai là avec toi, et je prendrai de l\'esprit qui repose sur toi, et en mettrai sur eux, afin qu\'ils portent avec toi le fardeau du peuple, et que tu n\'en sois plus chargé seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Et tu diras au peuple: Sanctifiez-vous pour demain et vous aurez de la chair à manger; car vous avez pleuré aux oreilles de l\'Éternel et dit: Qui nous donnera de la chair à manger, car nous étions bien en Egypte? et l\'Éternel vous donnera de la chair à manger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Ce ne sera ni un jour ni deux que vous en mangerez, ni cinq, ni dix, ni vingt jours,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'mais un mois de temps, jusqu\'à ce qu\'elle s\'exhale par vos narines, et qu\'elle vous dégoûte, parce que vous avez répudié l\'Éternel qui est au milieu de vous, et pleuré devant lui et dit: Pourquoi donc avons-nous quitté l\'Egypte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Et Moïse dit: Il y a six cent mille hommes de pied dans ce peuple au milieu duquel je suis, et Tu dis: Je leur donnerai de la chair, de quoi manger un mois de temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Égorgera-t-on pour eux du gros et du menu bétail jusqu\'à leur suffisance? réunira-t-on tous les poissons de la mer pour qu\'ils aient assez?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Et l\'Éternel dit à Moïse: La main de l\'Éternel se raccourcit-elle? Tu vas voir si ma parole s\'exécutera ou non.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Et Moïse sortit et redit au peuple les paroles de l\'Éternel, et il choisit soixante-dix hommes parmi les Anciens du peuple et les plaça autour de la Tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Et l\'Éternel descendit dans la nue et lui parla, et Il prit de l\'esprit qui reposait sur lui, et Il en mit sur les soixante-dix Anciens. Et lorsque l\'esprit reposa sur eux, ils prophétisèrent; mais ils ne le firent plus de nouveau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Or deux hommes étaient restés dans le camp, l\'un nommé Eldad, l\'autre Medad; et l\'esprit vint reposer sur eux (ils étaient parmi les [soixante-dix] inscrits, quoiqu\'ils n\'eussent point paru à la Tente) et ils prophétisaient dans le camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Aussitôt le jeune garçon courut en informer Moïse et lui dit: Eldad et Medad prophétisent dans le camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Et Josué, fils de Nun, serviteur de Moïse depuis sa jeunesse, prit la parole et dit: Mon seigneur, Moïse, empêche-les.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Mais Moïse lui dit: Veux-tu montrer du zèle pour moi? Je voudrais que dans le peuple de l\'Éternel tous fussent des prophètes, que l\'Éternel mît son esprit sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Et Moïse se retira dans le camp, lui et les Anciens d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Et un vent envoyé par l\'Éternel amena des cailles à travers la mer et les abattit dans le camp sur un espace d\'environ une journée de marche d\'un côté et d\'environ une journée de marche de l\'autre autour du camp, à deux coudées environ au-dessus du sol.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Et le peuple se mit en mouvement pendant tout ce jour-là, toute la nuit et tout le lendemain, et ramassa les cailles; le moins qu\'un homme en ramassât était dix homers; et ils les étendirent pour leur usage aux alentours du camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'La chair était encore entre leurs dents, et n\'était pas encore consommée, que la colère de l\'Éternel s\'enflamma contre le peuple et l\'Éternel frappa le peuple d\'une mortalité très grande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Et ce lieu reçut le nom de Kibroth-Haththava (tombeaux de la convoitise), parce que là le peuple inhuma ceux que la convoitise avait saisis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'De Kibroth-Haththava le peuple se mit en marche pour Hathseroth, et il s\'arrêta à Hathseroth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Là Marie et Aaron firent querelle à Moïse au sujet de la femme Éthiopienne qu\'il avait épousée; car il avait pris pour femme une Éthiopienne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Et ils dirent: N\'est-ce que par Moïse seul que l\'Éternel parle? n\'est-ce pas aussi par nous qu\'il parle? Et l\'Éternel entendit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Or cet homme-là, Moïse, était le plus doux des humains qui sont sur la face de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Sur-le-champ l\'Éternel dit à Moïse, et à Aaron et à Marie: Allez tous trois vous présenter à la Tente du Rendez-vous; et ils allèrent tous trois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Alors l\'Éternel descendit dans la colonne de nuée, et se tenant à la porte de la Tente Il appela Aaron et Marie, et ils parurent tous deux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Et Il dit: Entendez mes paroles! S\'il existe parmi vous un prophète, moi l\'Éternel, je me révèle à lui par la vision: c\'est dans un songe que je lui parle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Il n\'en est pas ainsi de mon serviteur Moïse: il est l\'homme de confiance dans toute ma Maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Je m\'abouche avec lui, en Personne, et sans déguisement; il voit la face de l\'Éternel. Comment donc ne craignez-vous pas de faire querelle à mon serviteur Moïse?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Ainsi s\'enflamma contre eux la colère de l\'Éternel qui s\'éloigna; et la nuée se retira aussi de la Tente,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'et voilà que Marie avait une lèpre comme la neige; et Aaron se tourna vers Marie, et voilà qu\'elle avait la lèpre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Alors Aaron dit à Moïse: Je t\'en conjure, mon seigneur, ne mets pas sur nous le poids du péché que nous avons commis dans notre folie, et dont nous sommes coupables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Oh! qu\'elle ne soit pas comme le mort-né qui en sortant du sein maternel a le corps à demi détruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Alors Moïse cria vers l\'Éternel et dit: O Dieu! oh! guéris-la donc!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Et l\'Éternel dit à Moïse: Mais si son père avait craché à sa face, ne serait-elle pas sept jours dans l\'opprobre?... Elle sera séquestrée sept jours hors du camp; après quoi elle sera réintégrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Marie fut donc séquestrée sept jours hors du camp, et le peuple ne partit point avant la réintégration de Marie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Et après cela le peuple partit de Hathseroth et vint camper au désert de Paran.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Là l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Envoie des hommes pour reconnaître le pays de Canaan que je donne aux enfants d\'Israël: vous enverrez un homme par Tribu, chacun pour celle de ses pères, et pris parmi leurs Princes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Alors Moïse les envoya du désert de Paran sur l\'ordre de l\'Éternel: il n\'y avait que des hommes, chefs des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Or voici leurs noms: pour la Tribu de Ruben, Sammua, fils de Zaccur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'pour la Tribu de Siméon, Saphat, fils de Hori;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'pour la Tribu de Juda, Caleb, fils de Jephunneh;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'pour la Tribu de Issaschar, Jighal, fils de Joseph;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'pour la Tribu d\'Éphraïm, Hosée, fils de Nun;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'pour la Tribu de Benjamin, Palti, fils de Raphu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'pour la Tribu de Zabulon, Gaddiel, fils de Sodi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'pour la Tribu de Joseph, la Tribu de Manassé, Gaddi, fils de Susi; pour la Tribu de Dan, Ammiel, fils de Gmalli;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'pour la Tribu d\'Asser, Sthur, fils de Michaël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'pour la Tribu de Nephthali, Nachbi, fils de Vophsi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'pour la Tribu de Gad, Ghuel, fils de Machi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Tels, sont les noms des hommes envoyés par Moïse pour reconnaître le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Or Moïse donna à Hosée, fils de Nun, le nom de Josué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'En les envoyant reconnaître le pays de Canaan, Moïse leur dit: Gagnez-en par ici le Midi, puis montez aux montagnes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'et voyez ce qu\'est le pays et le peuple qui l\'habite, s\'il est fort ou faible, peu nombreux ou considérable,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'et ce qu\'est le pays où il habite, s\'il est bon ou mauvais, et ce que sont les villes où ils habitent, s\'ils ont des camps ou des forteresses,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'et ce qu\'est le sol, s\'il est gras ou maigre, boisé ou non. Et ayez bon courage et rapportez des fruits du pays. Or c\'était l\'époque des primeurs du raisin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Ils allèrent donc et reconnurent le pays depuis le désert de Tsin jusqu\'à Rechob du côté de Hamath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Et ils gagnèrent le Midi et pénétrèrent jusqu\'à Hébron, et là étaient Ahiman, Sesaï et Thalmaï, enfants de Anak. Or Hébron avait été bâtie sept ans avant Tsoan en Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Et ils pénétrèrent jusque dans la vallée d\'Escol et ils y coupèrent un pampre avec une grappe de raisin qu\'ils portèrent à deux au moyen d\'une gaule; ils prirent aussi des grenades et des figues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Ce lieu reçut le nom de Vallée d\'Escol (vallée de la grappe) à cause de la grappe qu\'y avaient cueillie les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Et ayant reconnu le pays ils furent de retour au bout de quarante jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Étant donc arrivés ils se rendirent auprès de Moïse et d\'Aaron et de toute l\'Assemblée des enfants d\'Israël au désert de Paran vers Cadès, et ils leur rendirent compte ainsi qu\'à toute l\'Assemblée et leur montrèrent les fruits du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Et ils lui firent leur récit et dirent: Nous avons pénétré dans le pays où tu nous as envoyés: oui, c\'est une terre découlante de lait et de miel, et en voici les fruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Seulement le peuple qui habite le pays est vigoureux, et les villes, fortes et très grandes, et nous y avons vu aussi les enfants d\'Anak.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amalek habite le Midi du pays, et les Héthiens et les Jébusites et les Amoréens la montagne, et les Cananéens vers la mer et le long du Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Alors Caleb imposa silence au peuple à l\'égard de Moïse et dit: Marchons, marchons! faisons-en la conquête, car nous en serons maîtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Mais les hommes qui l\'avaient accompagné dirent: Nous ne saurions marcher contre ce peuple, car il est plus fort que nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Et ils décrièrent le pays qu\'ils avaient reconnu, en répandant chez les enfants d\'Israël ces propos: Le pays que nous avons parcouru pour le reconnaître, est un pays qui dévore ses habitants, et tout le peuple que nous y avons vu, est de taille élevée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Et là nous avons vu des géants, enfants d\'Anak, de la race des géants; et nous nous semblions des sauterelles, et nous leur semblions tels.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Alors toute l\'Assemblée élevant la voix poussa une clameur, et le peuple passa la nuit à pleurer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Et tous les enfants d\'Israël murmurèrent contre Moïse et contre Aaron et toute l\'Assemblée leur dit: Que ne sommes-nous morts dans le pays d\'Egypte, ou que ne mourons-nous dans ce désert-ci!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Pourquoi l\'Éternel nous mène-t-Il dans ce pays-là pour y périr par l\'épée? nos femmes et nos enfants serviront de proie. Ne vaut-il pas mieux pour nous retourner en Egypte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Et ils se disaient l\'un à l\'autre: Prenons un chef et retournons en Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Alors Moïse et Aaron se jetèrent face contre terre devant toute l\'assemblée réunie des enfants d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'et Josué, fils de Nun, et Caleb, fils de Jephunneh, du nombre des éclaireurs, déchirèrent leurs vêtements,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'et adressèrent à toute l\'Assemblée des enfants d\'Israël ces paroles: Le pays que nous avons parcouru pour le reconnaître, est un très bon, très bon pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Si l\'Éternel nous est propice, Il nous introduira dans ce pays-là, et nous la donnera, cette terre découlante de lait et de miel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Seulement ne vous révoltez-pas contre l\'Éternel, et n\'ayez pas peur du peuple du pays, car ce sera pour nous du pain à manger; leur ombrage leur a été retiré, et l\'Éternel est avec nous: n\'ayez point de peur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Alors toute l\'Assemblée parlait de les lapider. Mais la Gloire de l\'Éternel apparut dans la Tente du Rendez-vous devant tous les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Et l\'Éternel dit à Moïse: Jusques à quand ce peuple me méprisera-t-il? Et jusques à quand me refusera-t-il sa foi malgré les miracles que j\'ai accomplis dans son sein?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Je veux le frapper de la peste et le déshériter et faire de toi un peuple plus grand et plus puissant que lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Et Moïse dit à l\'Éternel: Mais ils l\'apprendront, les Égyptiens du milieu desquels tu as tiré ce peuple par ta puissance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'et ils le diront aux habitants de ce pays qui ont appris que toi, l\'Éternel, tu es au milieu de ce peuple, que tu te fais voir face à face, toi, l\'Éternel, que ta nuée les couvre, que tu marches devant eux le jour dans la colonne de nuée, et la nuit dans la colonne de feu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'or, si tu fais mourir ce peuple comme un seul homme, ces nations dont ta renommée a frappé les oreilles, diront:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'C\'est faute de pouvoir conduire ce peuple dans le pays qu\'il leur promit par serment que l\'Éternel l\'a massacré dans le désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Maintenant donc qu\'on voie dans sa grandeur la puissance du Seigneur, comme tu l\'as promis en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'l\'Éternel est lent à s\'irriter et riche d\'amour, il accorde le pardon de la faute et du péché, mais ne laisse pas quitte, impuni; Il châtie le crime des pères sur les enfants de la troisième et sur ceux de la quatrième génération.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Remets donc sa faute à ce peuple selon la grandeur de ton amour et comme tu lui as pardonné depuis l\'Egypte jusques ici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Et l\'Éternel dit: Je pardonne en tes propres termes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'et aussi vrai que je suis Vivant et que toute la terre est pleine de ma magnificence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'aucun des hommes qui ont vu ma gloire et les miracles opérés par moi en Egypte et au désert, et m\'ont tenté voici déjà dix fois et n\'ont pas écouté ma voix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'ne verra le pays que j\'ai promis par serment à leurs pères, aucun de mes contempteurs ne le verra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Mais mon serviteur Caleb qui est animé d\'un autre esprit, et m\'a pleinement obéi, je l\'introduirai dans le pays où il a pénétré et sa race le possédera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Cependant les Amalécites et les Cananéens occupent la vallée; demain par une conversion repliez-vous dans le désert dans la direction de la Mer aux algues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Et l\'Éternel parla à Moïse et Aaron en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Jusques à quand [pardonnerai-je] à cette Assemblée perverse qui murmure contre moi? J\'ai entendu les murmures des enfants d\'Israël comme ils ont murmuré contre moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Dis-leur: Aussi vrai que je suis Vivant, prononce l\'Éternel, ainsi que vous avez parlé à mes oreilles, ainsi je vous traiterai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Vous laisserez vos cadavres dans ce désert, vous tous, hommes de vingt ans et au-dessus enregistrés en totalité, qui avez murmuré contre moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Vous n\'entrerez pas dans le pays où la main levée je promis de vous établir, excepté Caleb, fils de Jephunneh, et Josué, fils de Nun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Et vos enfants dont vous avez dit: ils serviront de proie, je les y introduirai, et ils connaîtront le pays que vous avez dédaigné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Mais vous, vous laisserez vos cadavres dans ce désert-ci,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'et vos fils resteront dans ce désert comme pasteurs pendant quarante ans, et ils porteront la peine de vos prostitutions, jusqu\'à ce que vos cadavres soient au complet dans le désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Et autant de jours vous avez mis à reconnaître le pays, quarante jours, autant d\'années, une année pour un jour, vous porterez la peine de vos crimes, quarante ans, et sentirez ma disgrâce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Moi l\'Éternel j\'ai parlé: oui, ainsi je traiterai cette Assemblée perverse qui s\'est liguée contre moi: ils seront consumés dans ce désert-ci et y mourront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Et les hommes que Moïse avait envoyés pour reconnaître le pays, et qui à leur retour avaient excité toute l\'assemblée à murmurer contre lui en répandant des propos pour décrier le pays,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'ces hommes qui en répandant des propos avaient décrié le pays, moururent frappés d\'une plaie devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Mais Josué, fils de Nun, et Caleb, fils de Jephunneh, survécurent à ces hommes qui étaient allés reconnaître le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Et Moïse dit toutes ces paroles à tous les enfants d\'Israël, et le peuple fut dans un deuil profond.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Et le matin ils se levèrent et montèrent au sommet de la montagne en disant: Nous voici prêts à gagner le lieu qu\'a dit l\'Éternel; car nous avons péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Alors Moïse dit: Pourquoi voulez-vous transgresser l\'ordre de l\'Éternel? cela ne vous réussira pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Ne montez pas! car l\'Éternel n\'est pas au milieu de vous! afin que vous ne soyez pas mis en déroute devant vos ennemis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'car les Amalécites et les Cananéens sont là devant vous, et vous périrez par l\'épée parce que vous vous êtes ainsi détournés de l\'Éternel, et que l\'Éternel ne sera pas avec vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Néanmoins ils eurent la témérité de monter au sommet de la montagne, mais l\'Arche de l\'alliance de l\'Éternel et Moïse ne bougèrent du camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Alors les Amalécites et les Cananéens qui occupaient cette montagne, firent une descente et les battirent, et les menèrent battant jusqu\'à Horma.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Parle aux enfants d\'Israël et leur dis: Quand vous serez arrivés dans le pays où vous serez fixés et que je vous donnerai,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'et quand vous offrirez à l\'Éternel en sacrifice igné un holocauste ou une victime pour l\'acquit d\'un vœu ou d\'un don spontané ou dans vos solennités, pour faire fumer du gros et du menu bétail en parfum agréable à l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'celui qui présentera son oblation à l\'Éternel, présentera comme offrande un dixième de fleur de farine trempée d\'un quart de hin d\'huile;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'quant au vin pour la libation, vous en ajouterez à l\'holocauste ou à la victime un quart de hin pour chaque agneau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Ou bien au bélier tu ajouteras comme offrande deux dixièmes de fleur de farine trempée d\'un tiers de hin d\'huile;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'et pour la libation tu offriras un tiers de hin de fin en parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Et quand tu sacrifieras un jeune taureau comme holocauste ou comme victime, pour l\'acquit d\'un vœu ou en sacrifice pacifique à l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'on présentera en sus du jeune taureau comme offrande trois dixièmes de fleur de farine trempée d\'un demi-hin d\'huile,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'et pour la libation tu présenteras un demi-hin de vin en sacrifice igné d\'un parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'C\'est ce qui se pratiquera pour chaque bœuf, ou chaque bélier, ou agneau, ou chevreau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'ainsi vous procéderez, en raison du nombre des victimes sacrifiées par vous, pour chacune, en raison de leur nombre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Tout indigène le fera de cette manière pour offrir un sacrifice igné d\'un parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'De même l\'étranger séjournant chez vous, ou se rencontrant parmi vous, dans vos âges futurs, qui voudra faire un sacrifice igné d\'un parfum agréable à l\'Éternel, pratiquera tout ce que vous pratiquez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Quand il y aura Assemblée, il y aura une seule règle pour vous et pour l\'étranger domicilié, règle perpétuelle pour vos âges futurs; l\'étranger sera sur le même pied que vous devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Il n\'y aura qu\'une seule loi, et un seul rite pour vous et pour l\'étranger séjournant chez vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Parle aux enfants d\'Israël et leur dis: Quand vous serez arrivés au pays où je vous conduis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'et que vous mangerez des denrées du pays, vous prélèverez un don pour l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Comme prémices de votre mouture vous présenterez par élévation une galette; vous la présenterez comme le don prélevé sur l\'aire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Sur les prémices de votre mouture vous prélèverez un don pour l\'Éternel dans tous vos âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Et si vous manquez et n\'exécutez pas tous ces ordres que l\'Éternel a donnés à Moïse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'tout ce que l\'Éternel vous a prescrit par l\'organe de Moïse depuis le jour où Il vous donna des commandements et dès lors pour vos âges futurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'et si le fait a lieu à l\'insu de l\'Assemblée, par erreur, toute l\'Assemblée offrira un jeune taureau en holocauste, en parfum agréable à l\'Éternel, avec son offrande et sa libation selon le rite, et un bouc en sacrifice expiatoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Et le Prêtre fera la propitiation pour toute l\'Assemblée des enfants d\'Israël, et il leur sera pardonné; car c\'était une erreur; mais eux-mêmes ils présenteront leur oblation en sacrifice igné à l\'Éternel, et leur victime expiatoire devant l\'Éternel pour leur erreur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'et ainsi il sera pardonné à toute l\'Assemblée des enfants d\'Israël, et à l\'étranger séjournant parmi eux, car la chose est arrivée à l\'Assemblée par une erreur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Et si une personne seule pèche par erreur, elle offrira une chèvre d\'un an comme victime expiatoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Et le Prêtre fera la propitiation pour la personne qui a manqué en péchant par erreur, devant l\'Éternel, la propitiation se faisant pour elle, et il lui sera pardonné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Pour l\'indigène Israélite et pour l\'étranger séjournant parmi vous, vous aurez une seule loi pour celui qui manque par erreur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Mais la personne qui aura agi haut la main, parmi les indigènes ou les étrangers, aura outragé l\'Éternel, cette personne sera éliminée du milieu de son peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'car elle aura méprisé Sa parole et enfreint Ses commandements; cette personne sera éliminée: une iniquité pèse sur elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Les enfants d\'Israël, étant dans le désert, surprirent un homme qui ramassait du bois le jour du Sabbat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Et ceux qui l\'avaient surpris ramassant du bois, l\'amenèrent à Moïse et Aaron et à toute l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Et on le mit en prison, parce que ce qu\'il y avait à lui faire n\'était pas précisé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Alors l\'Éternel dit à Moïse: Que cet homme soit mis à mort; toute l\'Assemblée le lapidera hors du camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Alors toute l\'Assemblée le mena hors du camp, et le lapida, et il mourut, ainsi que l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Parle aux enfants d\'Israël et leur dis de se faire des houppes aux angles de leurs manteaux dans tous leurs âges, et d\'ajouter à la houppe de l\'angle un cordon d\'azur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Et portez-les comme des houppes dont la vue vous rappelle tous les commandements de l\'Éternel, afin que vous les pratiquiez, et ne soyez pas entraînés par votre cœur et par vos yeux dont vous suivez les désirs adultères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'afin que vous vous rappeliez et que vous exécutiez tous mes ordres et que vous soyez Saints pour votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Je suis l\'Éternel, votre Dieu, qui vous ai tirés du pays d\'Egypte pour être votre Dieu: je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Et Coré, fils de Jitsehar, fils de Kahath, fils de Lévi, forma un parti avec Dathan et Abiram, fils d\'Eliab, et On, fils de Peleth, ceux-ci fils de Ruben;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'et ils se soulevèrent contre Moïse avec deux cent cinquante hommes des enfants d\'Israël, Princes de l\'Assemblée, appelés au Conseil, personnages notables,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'et ils se réunirent contre Moïse et Aaron, et ils leur dirent: Vous en faites trop! Car cette Assemblée! c\'est tout autant d\'hommes consacrés, et l\'Éternel est au milieu d\'eux; pourquoi donc vous élevez-vous au-dessus de l\'Assemblée de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'A l\'ouïe de ces propos Moïse se jeta la face contre terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'et s\'adressant à Coré et à toute sa faction il leur dit: Demain l\'Éternel fera connaître qui est à Lui et qui est consacré pour lui donner accès auprès de Lui; et celui qu\'il choisira, Il lui donnera accès auprès de Lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Faites ceci: Prenez des encensoirs, Coré et tout son parti,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'et mettez-y du feu et jetez-y de l\'encens devant l\'Éternel, demain, et c\'est l\'homme que choisira l\'Éternel, qui sera le consacré. Vous en faites trop, enfants de Lévi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Et Moïse dit à Coré: Écoutez donc, enfants de Lévi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Est-ce trop peu pour vous que le Dieu d\'Israël vous ait triés dans l\'Assemblée d\'Israël pour vous donner accès auprès de Lui pour faire le service de la Résidence de l\'Éternel, et pour paraître devant l\'Assemblée officiant pour elle?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'A toi et à tous tes frères, enfants de Lévi avec toi, Il donne accès auprès de Lui, et vous prétendez encore au Sacerdoce!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'C\'est pour cela que vous vous liguez toi et tout ton parti contre l\'Éternel; Aaron en effet, qui est-il pour que vous murmuriez contre lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Et Moïse envoya mander Dathan et Abiram, fils d\'Eliab. Mais ils dirent: Nous n\'irons point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'N\'est-ce pas assez de nous avoir tirés d\'un pays découlant de lait et de miel pour nous faire périr dans le désert, que tu t\'ériges en dominateur au-dessus de nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Tu ne nous as point non plus conduits dans un pays découlant de lait et de miel, ni mis en possession de champs et de vignes. Veux-tu arracher les yeux à ces hommes? Nous n\'irons point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Alors Moïse fut fort irrité et il dit à l\'Éternel: Ne regarde pas leur offrande! Je ne leur ai pas enlevé un âne, et n\'ai pas fait tort à un d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Et Moïse dit à Coré: Demain paraissez, toi et tout ton parti, devant l\'Éternel, toi et eux avec Aaron,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'et prenez chacun votre encensoir, et y mettez de l\'encens, et apportez devant l\'Éternel chacun votre encensoir, deux cent cinquante encensoirs; et toi et Aaron vous viendrez aussi chacun avec son encensoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Ils prirent donc chacun leur encensoir, et y mirent du feu et y jetèrent de l\'encens, et ils parurent à la porte de la Tente du Rendez-vous, ainsi que Moïse et Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Et Coré en opposition avec eux convoqua toute l\'Assemblée à la porte de la Tente du Rendez-vous. Alors la gloire de l\'Éternel apparut à toute l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Et l\'Éternel parla à Moïse et Aaron en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Séparez-vous de ce parti-là: je vais l\'exterminer à l\'instant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Et ils se jetèrent face contre terre, et dirent: O Dieu, Dieu des esprits de toute chair, un homme seul a péché: t\'irriteras-tu contre toute l\'Assemblée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Et l\'Éternel dit à Moïse:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Parle à l\'Assemblée en ces termes: Retirez-vous de tous les côtés à distance de la demeure de Coré, de Dathan et d\'Abiram.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Alors Moïse se leva et se rendit chez Dathan et Abiram, et il fut suivi par les Anciens d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Et il dit à l\'Assemblée: Éloignez-vous des tentes de ces sacrilèges, et ne touchez rien de ce qui est à eux, afin que vous ne soyez pas emportés par tous leurs péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Et ils s\'éloignèrent de tous les côtés à distance de la demeure de Coré, et de Dathan et d\'Abiram. Et Dathan et Abiram sortirent et se placèrent à la porte de leurs tentes avec leurs femmes, leurs fils, et leurs enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Et Moïse dit: A ceci vous reconnaîtrez que l\'Éternel m\'a donné la mission de faire tout ce qui a été fait, et que je n\'ai pas agi de mon chef:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Si ces gens meurent de la mort commune à tous les hommes, et subissent la dispensation commune à tous les hommes, ce n\'est pas l\'Éternel qui m\'a envoyé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'mais si l\'Éternel crée un fait inouï, et si la terre s\'entr\'ouvre et les engloutit eux et tout ce qui est à eux, et qu\'ils descendent vivants aux Enfers, vous reconnaîtrez que ces gens-là ont répudié l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Et lorsqu\'il eut achevé de prononcer toutes ces paroles, le sol qui était sous leurs pieds se fendit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'et la terre s\'entr\'ouvrit et les engloutit eux et leurs maisons, et tous les hommes qui tenaient à Coré, et tout leur avoir, et');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'ils descendirent avec tout ce qu\'ils possédaient, vivants dans les Enfers, et la terre les recouvrit et ils furent exterminés du milieu de l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Et à leurs cris tous les Israélites qui les entouraient s\'enfuirent; car ils disaient: Nous craignons que la terre ne nous engloutisse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Et un feu envoyé par l\'Éternel consuma les deux cent cinquante hommes qui avaient offert l\'encens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Dis à Eléazar, fils du Prêtre Aaron, de retirer de l\'incendie les encensoirs, et jettes-en le feu au loin, car ce sont choses sacrées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'ces encensoirs de ces hommes qui ont perdu la vie pour leurs péchés; et qu\'on les étende en lames dont on plaquera l\'Autel; car on les a présentés devant l\'Éternel et ils sont devenus sacrés, et ce sera un monument pour les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Alors le Prêtre Eléazar prit les encensoirs d\'airain qu\'avaient présentés les incendiés, et on en fit des lames dont on plaqua l\'Autel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'pour rappeler ce souvenir aux enfants d\'Israël, afin qu\'aucun étranger n\'appartenant pas à la race d\'Aaron ne s\'approchât pour brûler l\'encens devant l\'Éternel et qu\'il ne lui advînt comme à Coré et à son parti, ainsi que l\'Éternel l\'avait dit par l\'organe de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Et il y eut des murmures de toute l\'Assemblée des enfants d\'Israël le lendemain contre Moïse et contre Aaron; ils disaient: Vous avez fait mourir le peuple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'Et comme l\'Assemblée s\'attroupait contre Moïse et contre Aaron, ceux-ci se dirigèrent vers la Tente du Rendez-vous; et voici, la nuée la couvrit, et la Gloire de l\'Éternel apparut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Et Moïse et Aaron arrivèrent devant la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Otez-vous du milieu de cette Assemblée, car je vais la consumer soudain. Alors ils se jetèrent face contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Et Moïse dit à Aaron: Prends l\'encensoir et y mets du feu pris sur l\'Autel, et y jette de l\'encens, et le promène en hâte dans l\'Assemblée, et fais la propitiation pour eux; car l\'Éternel a donné cours à Sa colère, le fléau a commencé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Et Aaron prit [l\'encensoir], comme avait dit Moïse, et courut au milieu de l\'Assemblée, et voilà que le fléau avait commencé parmi le peuple; et il offrit l\'encens et fit la propitiation pour le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'Et il se plaça entre les morts et les vivants, et le fléau fut arrêté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Et il y eut quatorze mille sept cents personnes qui périrent par ce fléau, sans compter ceux qui étaient morts à propos de Coré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Et Aaron revint auprès de Moïse à l\'entrée de la Tente du Rendez-vous, et le fléau était arrêté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Parle aux enfants d\'Israël et fais-toi donner par eux une houlette pour chaque maison patriarcale, par tous leurs Princes pour leurs maisons patriarcales, douze houlettes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'et tu inscriras le nom de chacun d\'eux sur sa houlette. Et tu inscriras le nom d\'Aaron sur la houlette de Lévi; car il y aura une houlette par chef de maison patriarcale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Et tu les déposeras dans la Tente du Rendez-vous devant le Témoignage où je me rencontre avec vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'Et la houlette de l\'homme que je choisirai, végétera; et ainsi, je ferai cesser devant moi les murmures que les enfants d\'Israël élèvent contre vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Et Moïse parla aux enfants d\'Israël, et tous leurs Princes lui donnèrent une houlette par Prince de leurs maisons patriarcales; douze houlettes, et la houlette d\'Aaron était dans le nombre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Et Moïse déposa les houlettes devant l\'Éternel dans la Tente du Témoignage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Et le lendemain, comme Moïse entrait dans la Tente du Témoignage, voilà que la houlette d\'Aaron de la Tribu de Lévi avait végété et poussé des jets, et épanoui des fleurs et mûri des amandes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Et Moïse enleva toutes les houlettes de devant l\'Éternel et les porta vers tous les enfants d\'Israël qui les virent et prirent chacun sa houlette.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Et l\'Éternel dit à Moïse: Reporte la houlette d\'Aaron devant le Témoignage pour y être conservée comme un monument pour les réfractaires, afin que tu fasses cesser devant moi leurs murmures et qu\'ils ne meurent point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Et ainsi fit Moïse: il se conforma à l\'ordre de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Et les enfants d\'Israël dirent à Moïse: Voici, nous expirons, nous périssons tous, nous périssons!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'quiconque s\'approche de la Résidence de l\'Éternel, meurt; devons-nous expirer jusqu\'au dernier?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Et l\'Éternel dit à Aaron: Toi et tes fils et ta maison patriarcale avec toi, vous serez comptables des délits commis au Sanctuaire, et toi et tes fils avec toi, vous serez comptables des délits commis dans votre Sacerdoce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Et tes frères aussi, la Tribu de Lévi, tribu de ton père, tu les feras approcher avec toi, pour qu\'ils te soient adjoints et qu\'ils te servent; mais toi et tes fils avec toi vous officierez devant la Tente du Témoignage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'et ils observeront ce qui doit être observé à ton égard et dans toute la Tente; seulement ils ne s\'approcheront ni des vases sacrés, ni de l\'Autel, de peur que vous ne mouriez et eux et vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Ils te seront adjoints et vaqueront à ce qui doit être fait dans la Tente du Rendez-vous pour tout le service de la Tente, et un étranger ne sera pas admis auprès de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Vous aurez donc à vous occuper du Sanctuaire et de l\'Autel, afin que désormais [ma] colère ne tombe plus sur les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Pour moi, voici j\'ai pris vos frères, les Lévites, du sein des enfants d\'Israël, et il vous est fait don de ceux qui ont été donnés en propre à l\'Éternel, pour faire le service de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Mais toi et tes fils avec toi, vous vaquerez à votre Sacerdoce dans tout ce qui concerne l\'Autel et derrière le rideau, et vous ferez votre service; je vous donne votre Sacerdoce comme un ministère donné en propre, et l\'étranger qui s\'approchera de vous sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Et l\'Éternel parla à Aaron: Voici, je t\'ai remis le service de ce qui m\'est offert par élévation sur toutes les choses consacrées par les enfants d\'Israël; je te le donne pour ta portion à toi et à tes fils comme redevance perpétuelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Voici ce qui te reviendra des très saints sacrifices après la combustion: toutes leurs oblations en fait d\'offrandes de tout genre, de Sacrifices expiatoires, de victimes pour délit, qu\'ils m\'offriront, t\'appartiendront, comme choses très saintes, à toi et à tes fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'C\'est dans le lieu très saint que vous les mangerez; tout mâle en mangera; qu\'elles te soient très saintes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Voici ce que tu auras encore: leurs dons offerts par élévation avec tous ceux qu\'offrent par agitation les enfants d\'Israël, je te les donne à toi et à tes fils et à tes filles avec toi comme redevance perpétuelle; toute personne pure dans ta maison en mangera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Toute l\'huile de choix, tout le moût et le blé de choix, prémices de ces denrées, qu\'ils donnent à l\'Éternel, je te les donne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Les primeurs de tout ce qui croît dans leur pays, qu\'ils présentent à l\'Éternel, t\'appartiendront; toute personne pure dans ta maison en mangera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Tout ce qui en Israël sera dévoué, t\'appartiendra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'La primogéniture de toute chair offerte à l\'Éternel, et de l\'homme et des animaux, t\'appartiendra; seulement tu recevras une rançon pour les premiers-nés de l\'homme, et aussi pour les premiers-nés des animaux impurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Quant à la rançon, tu recevras pour ce qui a l\'âge d\'un mois, d\'après ton estimation, cinq sicles d\'argent, en sicles du Sanctuaire, le sicle de vingt géras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Mais pour les premiers-nés soit du bœuf, soit du mouton, soit de la chèvre, tu ne les feras pas racheter; ils sont saints; tu répandras leur sang sur l\'Autel, et tu feras fumer leur graisse en sacrifice igné d\'un parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Et leur chair t\'appartiendra; comme la poitrine présentée par agitation et comme l\'éclanche droite, elle t\'appartiendra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Toutes les saintes oblations que les enfants d\'Israël présentent à l\'Éternel par élévation, je te les donne à toi et à tes fils et à tes filles avec toi, comme redevance perpétuelle; c\'est un pacte à perpétuité fait avec le sel devant l\'Éternel pour toi et ta race avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Et l\'Éternel dit à Aaron: Tu n\'auras ni propriété dans leur pays, ni lot parmi eux; c\'est moi qui serai ton lot et ta propriété au milieu des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Et aux fils de Lévi, voici, je donne toute dîme en Israël comme propriété, en échange du service qu\'ils font, du service de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Et que les enfants d\'Israël ne s\'approchent plus de la Tente du Rendez-vous, pour se charger d\'un péché mortel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Mais que ce soient les Lévites qui vaquent au service de la Tente du Rendez-vous, et soient responsables eux-mêmes de leurs manquements: ce sera une règle perpétuelle pour vos générations; et au milieu des enfants d\'Israël ils ne posséderont pas de propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Car je donne aux Lévites en propriété les dîmes des enfants d\'Israël que ceux-ci présentent à l\'Éternel par élévation; c\'est pourquoi je dis d\'eux: parmi les enfants d\'Israël, ils ne posséderont pas de propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Tu parleras aux Lévites et leur diras: Lorsque vous recevrez des enfants d\'Israël la dîme que je vous ai accordée sur eux comme votre propriété, vous en prélèverez pour l\'offrir par élévation à l\'Éternel la dîme sur la dîme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'et votre élévation vous sera comptée comme le froment prélevé sur l\'aire et l\'abondance prélevée au pressoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Ainsi, vous prélèverez aussi une élévation pour l\'Éternel sur toutes les dîmes que vous recevrez des enfants d\'Israël, et vous donnerez au Prêtre Aaron ce que vous en aurez élevé vers l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Et sur tous les dons reçus par vous, vous prélèverez toute élévation pour l\'Éternel, la portion sainte, sur tout ce qu\'il y a de meilleur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Et tu leur diras: Si vous en prélevez le meilleur, il sera compté aux Lévites comme le produit de l\'aire et comme le produit du pressoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Et vous le mangerez en tout lieu, vous et votre maison; car c\'est pour vous un salaire en échange du service fait par vous dans la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Et par là vous ne vous chargerez d\'aucun péché, si vous prélevez le meilleur, et vous ne profanerez point ce qui aura été consacré par les enfants d\'Israël, et vous ne mourrez point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Et l\'Éternel parla à Moïse et Aaron en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Voici le texte de la loi que l\'Éternel a prescrite en disant: Dis aux enfants d\'Israël de t\'amener une génisse rouge qui soit sans défaut et sans tache et n\'ait pas subi le joug,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'et donnez-la au Prêtre Eléazar, et qu\'on la mène hors du camp et qu\'on l\'abatte devant lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Puis, que le Prêtre Eléazar prenne de son sang avec le doigt, et que sept fois il fasse aspersion de ce sang contre la façade de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Et que la génisse soit brûlée sous ses yeux; sa peau et sa chair et son sang ainsi que sa fiente devront être brûlés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Et le Prêtre prendra du bois de cèdre, de l\'hysope et du vermillon qu\'il jettera dans le feu où la génisse brûle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Alors le Prêtre lavera ses vêtements et baignera son corps dans l\'eau, et ensuite il rentrera au camp; et le Prêtre sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Et celui qui la brûlera, lavera ses habits dans l\'eau, et baignera son corps dans l\'eau et il sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Et un homme pur recueillera la cendre de la génisse et la déposera hors du camp en lieu pur où elle sera conservée pour l\'Assemblée des enfants d\'Israël, pour servir à l\'eau de purification; c\'est une victime expiatoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Et celui qui aura recueilli la cendre de la génisse, lavera ses vêtements et sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Règle perpétuelle pour les enfants d\'Israël et pour l\'étranger séjournant chez eux: Qui touchera un mort, un cadavre humain quelconque sera sept jours en état d\'impureté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'et le troisième et le septième jour il fera son expiation avec cette [eau]; ainsi il se trouvera pur; s\'il ne fait pas son expiation le troisième et le septième jour, il ne sera pas en état de pureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Quiconque touche un mort, le cadavre d\'un homme qui est mort, et ne fait pas son expiation, souille la demeure de l\'Éternel, et cette personne-là sera retranchée d\'Israël; car l\'eau de purification n\'a pas été répandue sur elle, elle reste en état d\'impureté et porte encore sa souillure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Voici la loi: Lorsqu\'un homme meurt dans une tente, toute personne entrant dans la tente ou s\'y trouvant, tombe pour sept jours en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Tout vase ouvert et sans couvercle attaché, contracte impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Et quiconque en plein champ touche le cadavre d\'un homme tué par l\'épée, ou d\'un mort, ou des ossements humains ou un tombeau, sera pour sept jours en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Que l\'on prenne alors pour [purifier l\'individu] ainsi souillé, de la cendre du bûcher de la victime expiatoire et que l\'on verse dessus de l\'eau vive dans un vase.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Et qu\'un homme en état de pureté prenne de l\'hysope et la plonge dans l\'eau et fasse une aspersion contre la tente et contre tous les vases et contre les personnes qui y sont et contre celui qui aura touché des ossements, ou un homme tué, ou un mort, ou un tombeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Et celui qui est en état de pureté aspergera celui qui est en état d\'impureté, le troisième jour et le septième, et fera pour lui l\'expiation le septième jour et lavera ses vêtements, et se baignera dans l\'eau, et le soir il sera pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Et l\'homme qui aura contracté une impureté et ne fera pas son expiation, sera retranché du milieu de l\'Assemblée, car il souillerait le Sanctuaire de l\'Éternel; l\'eau de purification n\'ayant pas été répandue sur lui, il est en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Que ce soit là pour vous une règle perpétuelle. Et celui qui fait l\'aspersion avec de l\'eau de purification, lavera ses vêtements, et celui qui touchera l\'eau de purification sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Et tout ce que touchera l\'impur, se trouvera impur, et la personne qui le touchera sera jusqu\'au soir en état d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Et les enfants d\'Israël, l\'Assemblée entière, arrivèrent au désert de Tsin dans le premier mois et le peuple s\'arrêta à Cadès, et là mourut Marie, et elle y reçut la sépulture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Et il n\'y avait point d\'eau pour l\'Assemblée; et ils s\'attroupèrent contre Moïse et contre Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Et le peuple querella Moïse; et ils tenaient ces discours: Si au moins nous avions péri, comme périrent nos frères devant l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Pourquoi avez-vous amené l\'Assemblée de l\'Éternel dans ce désert, pour que nous y mourions nous et nos bestiaux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Et pourquoi nous avez-vous fait sortir de l\'Egypte pour nous amener dans cette méchante contrée, contrée où l\'on ne peut semer, ni avoir figuiers, vignes et grenadiers, et où il n\'y a point d\'eau à boire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Alors Moïse et Aaron quittant l\'Assemblée vinrent à l\'entrée de la Tente du Rendez-vous, et se jetèrent la face contre terre, et la Gloire de l\'Éternel leur apparut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Prends le bâton et convoque l\'Assemblée, toi et Aaron, ton frère, et parlez au rocher en leur présence, pour qu\'il vous donne son eau, et ainsi, fais-leur jaillir de l\'eau du rocher et abreuve l\'Assemblée et ses bestiaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Et Moïse prit le bâton de devant l\'Éternel, comme Il le lui avait commandé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Et Moïse et Aaron convoquèrent l\'Assemblée en face du rocher, et il leur dit: Écoutez donc, réfractaires! de ce rocher vous ferons-nous bien jaillir de l\'eau?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Et Moïse leva la main et frappa le rocher avec son bâton, à deux reprises; et l\'eau jaillit avec abondance, et l\'Assemblée et son bétail se désaltérèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Mais l\'Éternel dit à Moïse et Aaron: Parce que vous n\'avez pas eu foi en moi pour manifester ma Sainteté aux yeux des enfants d\'Israël, pour cette raison-là vous n\'introduirez pas cette Assemblée dans le pays que je veux lui donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Ce sont les eaux de la querelle, pour lesquelles les enfants d\'Israël querellèrent l\'Éternel qui leur manifesta sa Sainteté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Et Moïse envoya des messagers de Cadès au Roi d\'Edom: Ainsi parle ton frère Israël: Tu connais toutes les tribulations qui nous ont atteints,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'la descente de nos pères en Egypte, le long séjour que nous y fîmes, et les mauvais traitements que nous reçûmes des Égyptiens nous et nos pères;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'mais nous criâmes à l\'Éternel, et Il entendit notre voix, et Il envoya un Ange et nous tira de l\'Egypte; et nous voici à Cadès, ville à ton extrême frontière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Accorde-nous donc le passage à travers ton pays; nous ne traverserons ni champs, ni vignes, et ne boirons point l\'eau des puits; nous prendrons la route royale sans dévier ni à droite ni à gauche, jusqu\'à ce que nous ayons traversé ton territoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Mais Edom leur dit: Tu ne passeras point chez moi, sinon j\'irai au-devant de toi avec l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Et les enfants d\'Israël lui dirent: Nous cheminerons sur la chaussée, et si nous buvons ton eau, moi et mes troupeaux, je te la paierai; seulement (et ce n\'est rien) laisse-moi passer de mes pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Et Edom dit: Tu ne passeras pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Et Edom vint à leur rencontre avec des troupes nombreuses et à main forte. C\'est ainsi que Edom refusa à Israël le passage sur son territoire, et Israël se détourna de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Et les enfants d\'Israël, l\'Assemblée entière, partirent de Cadès et arrivèrent au mont Hor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Et l\'Éternel dit à Moïse et Aaron, au mont Hor sur la frontière du pays d\'Edom:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Aaron va être recueilli auprès de son peuple; car il n\'entrera pas dans le pays que je donne aux enfants d\'Israël, parce que vous avez été rebelles à mes ordres aux Eaux de la querelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Prends Aaron et Eléazar, son fils, et les mène sur le mont Hor;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'et là ôte à Aaron son costume et en revêts Eléazar, son fils; et Aaron sera recueilli et mourra là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Et Moïse se conforma à l\'ordre de l\'Éternel, et ils montèrent sur le mont Hor à la vue de toute l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Et Moïse ôta à Aaron son costume et en revêtit Eléazar, son fils, et Aaron mourut là au sommet de la montagne, et Moïse et Eléazar redescendirent de la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Et quand l\'Assemblée vit que Aaron avait expiré, toute la maison d\'Israël pleura Aaron pendant trente jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Et le Cananéen, Roi de Arad, qui résidait dans le Midi, apprit qu\'Israël s\'avançait par la route d\'Atharim; et il attaqua Israël et lui enleva des prisonniers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Alors Israël fit un vœu à l\'Éternel et dit: Si tu livres ce peuple entre mes mains, je dévouerai ses villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Et l\'Éternel écouta la voix d\'Israël, et livra les Cananéens, et on les dévoua eux et leurs villes, et ce lieu reçut le nom de Horma [lieu dévoué].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Et ils partirent du mont Hor prenant la route de la Mer aux algues pour tourner le pays d\'Edom. Et le peuple perdit patience en chemin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'et le peuple tint des discours contre Dieu et contre Moïse: Pourquoi nous as-tu tirés de l\'Egypte et exposés à mourir dans le désert? car il n\'y a ici ni pain ni eau, et ce vil aliment nous dégoûte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Alors l\'Éternel envoya parmi le peuple des serpents venimeux, et les morsures qu\'ils firent dans le peuple, donnèrent la mort à beaucoup de gens en Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Alors le peuple vint à Moïse et dit: Nous avons péché, car nous avons tenu des discours contre l\'Éternel et contre toi; intercède, auprès de l\'Éternel pour qu\'il éloigne de nous ces serpents. Et Moïse intercéda en faveur du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Et l\'Éternel dit à Moïse: Fais-toi un serpent et place-le au haut d\'une perche, et il arrivera que quiconque aura été mordu et le regardera, reprendra vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Alors Moïse fit un serpent d\'airain, et il le plaça au haut d\'une perche, et il arrivait que celui qui avait été mordu par un serpent et regardait vers le serpent d\'airain, reprenait vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Et les enfants d\'Israël partirent et vinrent camper à Oboth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Et ayant quitté Oboth, ils vinrent camper à Ijei-Abarim dans le désert situé à l\'Orient de Moab du côté du soleil levant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Étant partis de là ils vinrent camper dans la vallée de Zared.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Étant partis de là ils vinrent camper au delà de l\'Arnon qui coule dans le désert après sa sortie du territoire des Amoréens; car l\'Arnon est la limite de Moab, entre Moab et les Amoréens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'C\'est pourquoi il, est dit dans le Livre des Combats de l\'Éternel: Vaheb en Sufa et les torrents d\'Arnon');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'et l\'épanchement des torrents, qui tourne vers la Résidence d\'Ar, et s\'appuie aux confins de Moab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Et de là ils vinrent à Béer (puits). C\'est le puits où l\'Éternel dit à Moïse: Assemble le peuple, et je leur donnerai de l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Alors Israël chanta ce cantique: Jaillis, fontaine! Acclamez-la!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'fontaine creusée par des princes, qu\'ont fouie les chefs du peuple avec le sceptre et leurs bâtons.!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'Et du désert on vint à Mathana, et de Mathana à Nahaliel, et de Nahaliel à Bamoth;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'et de Bamoth à la vallée située dans le pays de Moab, au sommet du Pisga qui domine la plaine du désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Et Israël, envoya des messagers à Sihon, Roi, des Amoréens, pour lui dire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Laisse-moi, passer par ton pays; nous ne nous répandrons point dans les champs et les vignes, ne boirons point l\'eau des puits; nous suivrons la route royale jusqu\'à ce que nous ayons passé ta frontière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Mais Sihon n\'accorda pas à Israël le passage sur son territoire, et Sihon rassembla tout son peuple et marcha à la rencontre d\'Israël du côté du désert, et pénétra jusqu\'à Jahats et livra bataille à Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Et Israël le battit, avec le tranchant de l\'épée et conquit son pays de l\'Arnon au Jabbok, jusqu\'aux Ammonites; car la frontière des Ammonites était fortifiée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Et Israël occupa toutes ces villes, et s\'établit dans toutes les villes des Amoréens, à Hesbon et dans toutes ses dépendances.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Car Hesbon était la ville de Sihon, Roi des Amoréens, et il avait fait la guerre au précédent roi de Moab et lui avait pris tout son pays jusqu\'à l\'Arnon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'C\'est pourquoi les poètes disent: Entrez dans Hesbon! Qu\'on relève et fortifie la cité de Sihon!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Car un feu est sorti de Hesbon, Une flamme de la cité de Sihon: Il a dévoré le fort de Moab, Des maîtres des hauteurs de l\'Arnon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Malheur à toi, Moab! C\'en est fait de toi, peuple de Camos! De ses fils il a fait des fugitifs Et de ses filles des captives de Sihon, Roi des Amoréens...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Nous lançâmes nos traits,... Hesbon est détruite jusqu\'à Dibon, et nous ravageâmes jusqu\'à Nopha, l\'incendie atteignit Médéba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Et pendant le séjour d\'Israël dans le pays des Amoréens');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Moïse envoya reconnaître Jaëzer, et ils s\'emparèrent de ses dépendances, et il expulsa les Amoréens qui y étaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Et se détournant, ils montèrent du côté de Basan, et Og, Roi de Basan, vint à leur rencontre, lui et tout son peuple, pour les attaquer, à Edreï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Alors l\'Éternel dit à Moïse: Ne le crains pas; car je le livre entre tes mains, lui et tout son peuple et son pays, et tu le traiteras comme tu as traité Sihon, roi des Amoréens qui résidait à Hesbon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Et ils le battirent lui et ses fils et tout son peuple jusqu\'à ne pas lui laisser un réchappé, et ils occupèrent son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Et étant partis, les fils d\'Israël vinrent camper dans les plaines de Moab au delà du Jourdain, près de Jéricho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Et Balak, fils de Tsippor, vit tout ce qu\'Israël avait fait aux Amoréens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Et Moab conçut un grand effroi en face de ce peuple, car il était fort nombreux, et Moab eut peur à la vue des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Et Moab dit aux Anciens de Madian: Cette troupe va tout dévorer autour de nous, comme le bœuf broute la verdure de la campagne. Or Balak, fils de Tsippor, était alors Roi de Moab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Alors Balak envoya des messagers à Balaam, fils de Behor, à Pethor, sur le Fleuve (l\' Euphrate) dans le pays des fils de son peuple, pour le mander en lui disant: Voici, un peuple est sorti de l\'Égypte; voilà qu\'il couvre la face entière du pays, et il est campé en face de moi:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'maintenant viens donc! maudis pour moi ce peuple-là, car il est plus fort que moi; peut-être ainsi l\'emporterai-je; nous le battrons et je le chasserai du pays; car je sais que celui que tu bénis est béni, et que celui que tu maudis est maudit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Les Anciens de Moab et les Anciens de Madian partirent, ayant en main le salaire pour le devin. Et ils arrivèrent auprès de Balaam et lui rapportèrent les paroles de Balak.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Et il leur dit: Passez ici la nuit, et je vous rendrai réponse d\'après ce que l\'Éternel m\'aura dit. Et les princes de Moab restèrent chez Balaam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Puis Dieu vint à Balaam et dit: Qui sont ces hommes que tu as chez toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Et Balaam dit à Dieu: Balak, fils de Tsippor, Roi de Moab, m\'a fait dire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Voici, un peuple sorti de l\'Egypte couvre la face du pays: viens donc, maudis pour moi ce peuple; peut-être ainsi serai-je à même de le combattre et de le chasser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Et Dieu dit à Balaam: Ne va pas avec eux; tu n\'as point à maudire ce peuple, car il est béni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Et Balaam se leva le matin et dit aux princes de Balak: Allez-vous-en dans votre pays, car l\'Éternel a refusé de me permettre de vous accompagner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Alors les princes de Moab se levèrent et revinrent auprès de Balak à qui ils dirent: Balaam a refusé de nous accompagner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Mais Balak délégua de nouveau des princes en plus grand nombre et plus considérables que les premiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Et ils vinrent auprès de Balaam et lui dirent: Ainsi parle Balak, fils de Tsippor: Je t\'en prie, ne te laisse point arrêter de te rendre auprès de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Car je t\'accorderai beaucoup d\'honneurs, et je ferai tout ce que tu me diras: viens donc, et maudis pour moi ce peuple-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Et Balaam répondit et dit aux serviteurs de Balak: Quand Balak me donnerait sa maison pleine d\'argent et d\'or, je ne pourrais contrevenir à l\'ordre de l\'Éternel, mon Dieu, en faisant peu ou beaucoup.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Mais je vous prie aussi de rester ici cette nuit et je verrai ce que l\'Éternel me dira cette seconde fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Et pendant la nuit Dieu vint à Balaam et lui dit: Si ces hommes sont venus pour te mander, lève-toi et accompagne-les, mais tu ne feras que ce que je te dirai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Balaam se leva donc le matin et mit le harnais à son ânesse, et s\'achemina avec les princes de Moab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Mais la colère de Dieu s\'alluma parce qu\'il était parti, et l\'Ange de l\'Éternel se posta sur le chemin pour s\'opposer à lui. Or il était monté sur son ânesse ayant avec lui ses deux valets.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Et l\'ânesse aperçut l\'Ange de l\'Éternel posté sur le chemin, et son épée nue dans sa main, et l\'ânesse s\'écarta de la route et entra dans les champs; et Balaam frappa l\'ânesse pour la ramener dans la route.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Alors l\'Ange vint se placer sur le sentier des vignes, où il y avait mur d\'un côté et mur de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Et l\'ânesse voyant l\'Ange de l\'Éternel se serra contre la muraille et serra le pied de Balaam contre la muraille et il la frappa de nouveau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Et l\'Ange de l\'Éternel passa encore en avant et se plaça dans un lieu étroit où il n\'y avait aucune voie pour s\'écarter ni à droite ni à gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Et l\'ânesse voyant l\'Ange de l\'Éternel s\'abattit sous Balaam; et Balaam s\'enflamma de colère et frappa l\'ânesse avec son bâton.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Alors l\'Éternel ouvrit la bouche de l\'ânesse, et elle dit à Balaam: Que t\'ai-je fait pour m\'avoir battue déjà trois fois?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Et Balaam dit à l\'ânesse: C\'est que tu as été rétive pour moi; que n\'ai-je une épée dans ma main? je t\'aurais déjà tuée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Et l\'ânesse dit à Balaam: Ne suis-je pas ton ânesse que, depuis que tu es, tu as montée jusqu\'aujourd\'hui? Ai-je l\'habitude de te faire pareille chose? Et il dit: Non!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Alors l\'Éternel dessilla les yeux de Balaam et il aperçut l\'Ange de l\'Éternel posté sur le chemin, son épée nue à la main, et il s\'inclina et se prosterna la face contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Et l\'Ange de l\'Éternel lui dit: Pourquoi as-tu frappé ton ânesse déjà trois fois? Voici, je suis sorti pour m\'opposer, parce que je te vois suivre une voie périlleuse. Et l\'ânesse m\'a vu et à mon aspect s\'est écartée déjà trois fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Si elle ne se fût pas écartée de moi, certes je t\'aurais déjà tué, et à elle j\'aurais laissé la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Et Balaam dit à l\'Ange de l\'Éternel: J\'ai péché, car j\'ignorais que tu fusses posté contre moi sur le chemin, et maintenant, si tu me désapprouves, je m\'en retournerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Et l\'Ange de l\'Éternel dit à Balaam: Va avec ces hommes; mais ne dis pas autre chose que les paroles que je te dirai. Et Balaam chemina avec les princes de Balak.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Et Balak apprenant que Balaam arrivait, vint au-devant de lui jusqu\'à la ville de Moab, à la limite de l\'Arnon qui est l\'extrême frontière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Et Balak dit à Balaam: N\'ai-je pas envoyé auprès de toi pour te mander? Pourquoi ne t\'es-tu pas rendu auprès de moi? vraiment, ne suis-je pas en état de te donner des honneurs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Et Balaam dit à Balak: Voici, je suis arrivé auprès de toi; maintenant est-ce que je puis tenir tout discours? je rendrai les paroles que l\'Éternel me mettra dans la bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Et Balaam accompagna Balak et ils allèrent à Kiriath-Chutsoth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Et Balak fit un sacrifice de gros et de menu bétail, et en envoya à Balaam et aux princes qui l\'accompagnaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Et le matin Balak prit Balaam et le conduisit sur les hauteurs de Bahal d\'où il pût découvrir l\'extrémité du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Alors Balaam dit à Balak: Construis-moi ici sept autels et mets ici à ma disposition sept taureaux et sept béliers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Et Balak fit ce que Balaam lui demandait, et Balak et Balaam sacrifièrent un taureau et un bélier sur chaque autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Et Balaam dit à Balak: Tiens-toi auprès de ton holocauste, et moi je vais m\'éloigner: peut-être l\'Éternel viendra-t-Il au-devant de moi et je te rapporterai ce qu\'il m\'aura dévoilé. Et il alla sur une colline.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Alors l\'Éternel vint au-devant de Balaam qui Lui dit: J\'ai disposé sept autels et sacrifié un taureau et un bélier sur chaque autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Et l\'Éternel mit des paroles dans la bouche de Balaam et dit: Retourne vers Balak, et tu lui parleras ainsi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Et il revint vers lui, et voici il se tenait près de son holocauste, lui et tous les princes de Moab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Alors Balaam prononça son oracle et dit: D\'Aram m\'appelle Balak; le Roi de Moab; des montagnes de l\'Orient. « Tiens, dit-il, pour moi maudis Jacob! viens! voue Israël à la furie! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Comment maudirais-je celui que Dieu ne maudit pas, et vouerais-je à la furie, quand l\'Éternel n\'y voue pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Car de la cime des rochers je le découvre; et des hauteurs je le contemple: voici, ce peuple habite solitaire, et parmi les nations il ne se compte pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Qui supputera la poussière de Jacob, et dira le nombre d\'un seul quart d\'Israël? Que je meure de la mort des justes, et que mon avenir soit pareil au leur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Alors Balak dit à Balaam: Que m\'as-tu fait? Je t\'ai pris pour maudire mes ennemis, et voilà que tu n\'as fait que bénir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Et il répondit et dit: Ne dois-je pas veiller à dire ce que l\'Éternel met dans ma bouche?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Et Balak lui dit: Viens donc avec moi dans un autre lieu d\'où tu verras ce peuple; tu n\'en verras que l\'extrémité, et tu n\'en verras pas la totalité. Et de là maudis-le-moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Et il le mena au plateau des sentinelles, sur le sommet du Pisga, où il éleva sept autels et sacrifia un taureau et un bélier sur chaque autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Et Balaam dit à Balak: Tiens-toi ici près de ton holocauste, et j\'irai là chercher une rencontre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Alors l\'Éternel vint à là rencontre de Balaam et mit des paroles dans sa bouche et dit: Retourne vers Balak et lui parle ainsi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Et il revint vers lui; et voici, il se tenait près de son holocauste et les princes de Moab avec lui; et Balak lui dit: Qu\'a dit l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Alors Balaam prononça son oracle et dit: Sus! Balak! écoute! prête-moi l\'oreille, fils de Tsippor');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Dieu n\'est pas un homme pour mentir, ni fils d\'un homme pour se repentir. Dira-t-Il et ne fera-t-Il pas? Promettra-t-Il et ne tiendra-t-Il pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Voici, j\'ai reçu [l\'ordre] de bénir! Il a béni, je ne puis rétracter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Il ne découvre aucun mal en Jacob, et ne voit pas d\'iniquité en Israël. L\'Éternel, leur Dieu, les accompagne, et les trompettes du Roi sonnent au milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Dieu les fit sortir de l\'Egypte; ils ont la vélocité du buffle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Le charme ne peut rien contre Jacob, ni l\'enchantement contre Israël. Un jour à Jacob elle sera annoncée et à Israël, l\'œuvre de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Voici, comme la lionne, le peuple se lève, et comme le lion, il se dresse. Il ne se couche pas qu\'il n\'ait dévoré la proie, et bu le sang des blessés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Alors Balak dit à Balaam: Ne le maudis ni ne le bénis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Et Balaam répondit et dit à Balak: Ne t\'ai-je pas parlé ainsi: Je ferai tout ce que me dira l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Mais Balak dit à Balaam: Viens donc, je te conduirai dans un autre lieu, si Dieu le trouve bon, afin que de là tu me maudisses ce peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Et Balak conduisit Balaam au sommet du Pehor qui domine la plaine du désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Et Balaam dit à Balak: Construis-moi ici sept autels et mets ici à ma disposition sept taureaux et sept béliers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Et Balak fit ce que demandait Balaam et sacrifia un taureau et un bélier sur chaque autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Et Balaam voyant qu\'il plaisait à l\'Éternel de bénir Israël, n\'alla point cette fois, comme la première, à la recherche des enchantements, mais il tourna sa face du côté du désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Et Balaam levant les yeux vit Israël campé par tribus; alors vint sur lui l\'esprit de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Et il prononça son oracle et dit: Ainsi parle Balaam, fils de Behor, ainsi parle l\'homme dont l\'œil est ouvert,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'ainsi parle l\'auditeur des paroles de Dieu, qui voit les visions du Tout-Puissant, qui se prosterne et a les yeux dessillés:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Que tes tentes sont belles, ô Jacob! tes demeures, ô Israël! Elles s\'étendent comme des vallées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'comme des jardins le long d\'un fleuve, comme des aloès que planta l\'Éternel, comme des cèdres le long des eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Des ondes s\'épanchent de son seau, et sa race, en flots abondants. Au-dessus d\'Agag s\'élève son Roi, et son royaume a la prééminence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Dieu le retira de l\'Egypte, et il a la vélocité du buffle. Il dévore les peuples, ses adversaires, ronge leurs os, et fracasse leurs flèches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Il se couche, il repose, pareil au lion ou à la lionne: Qui le fera lever? Qui te bénira, sera béni, et qui te maudira, sera maudit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Alors la colère de Balak s\'enflamma contre Balaam, et frappant ses mains l\'une contre l\'autre Balak dit à Balaam: Je t\'ai mandé pour maudire mes ennemis, et voilà que tu as béni, béni déjà par trois fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Fuis donc maintenant et va-t\'en chez toi! Je disais: Je t\'accorderai des honneurs, mais voilà que l\'Éternel t\'empêche de les recevoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Et Balaam dit à Balak: Même aux messagers que tu m\'as envoyés, n\'ai-je pas dit en propres termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Quand Balak me donnerait sa maison pleine d\'argent et d\'or, je ne pourrais transgresser l\'ordre de l\'Éternel en faisant de par moi du bien ou du mal! ce que l\'Éternel dira, c\'est ce que je répéterai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Et maintenant, voici, je reprends le chemin de mon peuple. Mais viens! je veux t\'avertir de ce que ce peuple fera à ton peuple dans la suite des temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Puis Balaam prononça son oracle et dit: Ainsi parle Balaam, fils de Behor, ainsi parle l\'homme dont l\'œil est ouvert,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'ainsi parle l\'auditeur des paroles de Dieu, qui connaît les vues du Très-Haut, qui voit les visions du Tout-Puissant, qui se prosterne et a les yeux dessillés:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Je le vois, quoique non présent, Je le vois, mais dans le lointain... Un astre surgit de Jacob, et un sceptre s\'élève d\'Israël; il ébranle Moab de fond en comble, et extermine tous les fils de Seth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'et Edom devient sa conquête, et Séïr la conquête de ses ennemis, et Israël fait des actes de vaillance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Issu de Jacob il aura l\'empire, et fera périr les réchappés des villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Et à la vue d\'Amalek, il prononça son oracle et dit: Amalek est en tête des peuples, mais son avenir aboutit à la ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Et à la vue des Kénites, il prononça son oracle et dit: Que ta demeure soit permanente, et place ton aire sur le rocher!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Mais Kain est voué à la ruine: Quelle sera sa durée? Assur te fera prisonnier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Et il prononça son oracle et dit: Hélas! qui vivra, quand Il fera ces choses?...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Et des navires partis de la côte de Kittim humilieront Assur, humilieront Eber, lui aussi est voué à la ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Et Balaam se leva, et partit et retourna chez lui; de même Balak s\'en alla de son côté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Et Israël faisait une station à Sittim; alors le peuple commença à se livrer à la fornication avec les filles de Moab,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'et elles invitèrent le peuple aux sacrifices de leurs divinités, et le peuple y mangea et adora leurs divinités,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'et Israël s\'attacha à Bahal-Pehor, et la colère de l\'Éternel s\'enflamma contre Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Et l\'Éternel dit à Moïse: Prends avec toi tous les chefs du peuple et fais pendre [les coupables] en vue de l\'Éternel à la clarté du soleil, pour détourner d\'Israël le courroux de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Alors Moïse dit aux Juges d\'Israël: Que chacun de vous tue ceux de ses gens qui se sont attachés à Bahal-Pehor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Et voilà qu\'arriva un homme d\'entre les enfants d\'Israël amenant auprès de ses frères une Madianite, sous les yeux de Moïse et de toute l\'Assemblée des enfants d\'Israël qui étaient en pleurs à la porte de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'A cette vue, Phinées, fils d\'Eléazar, fils du Prêtre Aaron, se leva du milieu de l\'Assemblée, et prit une pique en sa main; et il suivit l\'Israélite dans sa chambre, et les perça l\'un et l\'autre, l\'homme d\'Israël et la femme, par le bas ventre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'Alors le fléau cessa de frapper les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Or ceux qui périrent par ce fléau, furent au nombre de vingt-quatre mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Phinées, fils d\'Eléazar, fils du Prêtre Aaron, a détourné ma fureur de dessus les enfants d\'Israël, en s\'animant de ma jalousie au milieu d\'eux, de sorte que dans ma jalousie je n\'ai pas détruit les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'En conséquence dis: Voici, je lui accorde mon alliance de paix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'et il y a pour lui et pour sa race après lui pacte de sacerdoce perpétuel, parce qu\'il s\'est montré jaloux pour son Dieu, et qu\'il a fait l\'expiation pour les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Or le nom de l\'Israélite tué, qui avait été frappé avec la Madianite, était Simri; il était fils de Salu, prince d\'une maison patriarcale des Siméonites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'et le nom de la femme tuée, Madianite, était Cozebi, fille de Tsur, lequel était chef de peuplade, d\'une famille patriarcale des Madianites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Traitez les Madianites en ennemis, et défaites-les;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'car ils vous ont eux-mêmes traités en ennemis par les artifices dont ils vous ont circonvenus dans l\'affaire de Pehor et dans celle de Cozebi, fille d\'un prince de Madian, leur propre sœur, tuée lors du fléau à vous infligé à cause de Pehor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Et après ce fléau l\'Éternel parla à Moïse et à Eléazar, fils du Prêtre Aaron, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Faites le relevé de la totalité de l\'Assemblée des enfants d\'Israël, des hommes âgés de vingt ans et plus, selon leurs maisons patriarcales, de tous ceux qui font le service militaire en Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Et Moïse et le Prêtre Eléazar leur parlèrent dans les plaines de Moab sur le Jourdain près de Jéricho, et dirent:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'De vingt ans et au-dessus, comme l\'Éternel l\'a prescrit à Moïse, et aux enfants d\'Israël sortis du pays d\'Egypte:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben, premier-né d\'Israël, fils de Ruben: Hanoch, famille des Hanochites; de Pallu, la famille des Palluites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'de Hestron, la famille des Hestronites; de Carmi, la famille des Carmites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Telles sont les familles, des Rubénites, dont quarante-trois mille sept cent trente furent enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Et le fils de Pallu était Eliab;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'et les fils d\'Eliab, Nemuel et Dathan et Abiram. C\'est ce Dathan et cet Abiram, députés de l\'Assemblée, qui, dans l\'attroupement de Coré, se soulevèrent contre Moïse et Aaron, lors de leur soulèvement contre l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'quand la terre s\'entr\'ouvrant les engloutit eux et Coré, en même temps que périssait cette troupe, le feu ayant consumé les deux cent cinquante hommes dont il fut fait un exemple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Cependant les fils de Coré ne périrent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Fils de Siméon, selon leurs familles: de Nemuel, la famille des Nemuélites; de Jamin, la famille des Jaminites; de Jachin, la famille des Jachinites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'de Zérah, la famille des Zérahites; de Saul, la famille des Saulites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Telles sont les familles des Siméonites: vingt-deux mille deux cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Fils de Gad selon leurs familles: de Tsephon, la famille des Tsephonites; de Haggi, la famille des Haggites: de Suni, la famille des Sunites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'de Ozéni, la famille des Ozénites; de Eri la famille des Erites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'de Arod, la famille des Arodites; de Areli, la famille des Arelites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Telles sont les familles des fils de Gad dont quarante mille cinq cents furent enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Fils de Juda: Er et Onan; mais Er et Onan étaient morts dans le pays de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Et les fils de Juda étaient d\'après leurs familles: de Séla, la famille des Sélanites; de Pérets, la famille des Péretsites; de Zerah, la famille des Zerahites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Et les fils de Pérets furent: de Hetsron, la famille des Hetsronites; de Hamul, la famille des Hamulites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Telles sont les familles de Juda: soixante-seize mille cinq cents furent enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Fils d\'Issaschar, selon leurs familles: de Thola, la famille des Tholaïtes; de Puva, la famille des Punites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'de Jasub, la famille des Jasubites; de Simron, la famille des Simronites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'telles sont les familles d\'Issaschar: soixante-quatre mille trois cents furent enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Fils de Zabulon, selon leurs familles: de Sered, la famille des Sardites; de Elon, la famille des Elonites; de Jahléel, la famille des Jahléélites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Telles sont les familles des Zabulonites dont soixante mille cinq cents furent enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Fils de Joseph selon leurs familles: Manassé et Ephraïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Fils de Manassé: de Machir, la famille des Machirites (et Machir engendra Galaad); de Galaad, la famille des Galaadites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Voici les fils de Galaad: Hiézer, la famille des Hiézérites; de Hélek, la famille des Hélékites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'et Asriel, la famille des Asriélites; et Sichem, la famille des Sichémites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'et Semidah, la famille des Semidahites; et Hépher, la famille des Héphrites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Et Tselophehad était fils de Hépher, il n\'avait point de fils, seulement des filles; et les noms des filles de Tselophehad étaient: Mahela et Noa, Hogla, Milca et Thirtsa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Telles sont les familles de Manassé: cinquante-deux mille sept cents furent enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Suivent les fils d\'Epbraïm, selon leurs familles: de Suthélah, la famille des Suthélahites; de Becher, la famille des Bachrites; de Thahan, la famille des Thahanites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Et voici les fils de Suthélah: de Eran, la famille des Eranites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Telles sont les familles des fils d\'Éphraïm dont trente-deux mille cinq cents furent enregistrés. Tels sont les fils de Joseph selon leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Fils de Benjamin, selon leurs familles: de Béla, la famille des Balites; de Asbel, la famille des Asbélites; de Ahiram, la famille des Ahiramites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'de Sephupham, la famille des Suphamites; de Hupham, la famille des Huphamites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Et les fils de Béla furent: Ard et Naëman, la famille des Ardites; de Naëman, la famille des Naëmanites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Tels sont les fils de Benjamin selon leurs familles: quarante-cinq mille six cents furent enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Voici les fils de Dan, selon leurs familles: de Suham, la famille des Suhamites; telles sont les familles de Dan selon leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Toutes les familles des Suhamites fournirent soixante-quatre mille quatre cents hommes enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Fils d\'Asser, selon leurs familles: de Jimna, la famille des Jimnaïtes; de Jisvi, la famille des Jïsvites; de Béria, la famille des Bériites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Des fils de Béria: de Héber, la famille des Hébrites; de Malchiel, la famille dés Malchiélites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Et le nom de la fille d\'Asser était Sarah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Telles sont les familles des fils d\'Asser dont cinquante-trois mille quatre cents furent enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Fils de Nephthali, selon leurs familles: de Jahtsehl, la famille des Jahtsehlites; de Guni, la famille des Gunites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'de Jetser, la famille des Jetsérites; de Sillem, la famille des Sillémites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Telles sont les familles de Nephthali selon leurs familles: quarante-cinq mille quatre cents hommes furent enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Tels sont les hommes des enfants d\'Israël enregistrés au nombre de six cent un mille sept cent trente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'C\'est entre eux que sera partagé le pays en autant de propriétés qu\'il y a de noms:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'aux plus nombreux tu adjugeras un lot plus grand et un plus petit aux moins nombreux; il sera donné à chacun un héritage proportionné au nombre de ses hommes enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Cependant le partage du pays se fera au sort; les propriétés seront affectées aux noms de leurs tribus patriarcales;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'c\'est par le sort qu\'à chacun sera adjugé son lot, plus ou moins considérable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Et voici les Lévites enregistrés selon leurs familles: de Gerson, la famille des Gersonites; de Kahath, la famille des Kahathites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'de Merari, la famille des Merarites. Voici les familles de Lévi: la famille des Libnites, la famille des Hébronites, la famille des Mahelites, la famille des Musites, la famille des Corahites. Et Kahath engendra Amram.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Et le nom de la femme d\'Amram était Jochébed, fille de Lévi, laquelle naquit à Lévi en Egypte; et elle enfanta à Amram Aaron et Moïse et Marie, leur sœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Et à Aaron naquirent Nadab et Abihu, Eléazar et Ithamar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Et Nadab et Abihu moururent lorsqu\'ils présentèrent devant l\'Éternel un feu étranger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Et leurs hommes enregistrés étaient au nombre de vingt-trois mille, tous mâles, d\'un mois et au-dessus; car ils ne furent pas compris dans le recensement des enfants d\'Israël, parce qu\'il ne leur fut adjugé aucune propriété parmi les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Tels sont les hommes recensés par Moïse et le Prêtre Eléazar qui recensèrent les enfants d\'Israël dans les plaines de Moab sur le Jourdain de Jéricho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Et parmi eux il ne se trouvait plus aucun des hommes recensés par Moïse et le Prêtre Aaron, lors du recensement fait des enfants d\'Israël dans le désert de Sinaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Car l\'Éternel avait, dit d\'eux: Ils mourront, mourront dans le désert, et il n\'en survivra pas un, sinon Caleb, fils de Jephunné, et Josué, fils de Nun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Et se présentèrent les filles de Tselophehad, fils de Hépher, fils de Galaad, fils de Machir, fils de Manassé, de l\'une des familles de Manassé, fils de Joseph; or voici les noms de ses filles: Mahela, Noa et Hogla et Milca et Thirtsa;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'et elles comparurent devant Moïse et devant le Prêtre Eléazar et devant les Princes et toute l\'Assemblée à l\'entrée de la Tente du Rendez-vous et dirent:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Notre père est mort dans le désert; il ne faisait point partie de la troupe conjurée contre l\'Éternel, de la troupe de Coré, mais il est mort pour son péché, et il n\'avait pas de fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Pourquoi le nom de notre père disparaîtrait-il de sa famille, parce qu\'il n\'avait pas de fils? Donne-nous un bien-fonds parmi les frères de notre père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Et Moïse porta leur affaire devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Alors l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Les filles de Tselophehad ont raison dans ce qu\'elles disent: donne-leur un bien-fonds en propriété parmi les frères de leur père, et tu leur transmettras l\'héritage de leur père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Et tu parleras aux enfants d\'Israël et diras: Quand un homme mourra sans laisser de fils, vous transmettrez son héritage à sa fille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Et s\'il n\'a pas de fille, vous donnerez son héritage à son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Et s\'il n\'a point de frère, vous donnerez son héritage aux frères de son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Et si son père n\'a point de frères, vous donnerez son héritage dans sa famille à son parent consanguin le plus proche, afin qu\'il ait cette succession; et que ce soit là pour les enfants d\'Israël une règle de droit, ainsi que l\'Éternel l\'ordonne à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Et l\'Éternel parla à Moïse: Monte sur cette montagne d\'Abarim, et vois le pays que j\'ai donné aux enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Et après l\'avoir vu, tu seras recueilli auprès de ton peuple, toi aussi, comme Aaron ton frère a été recueilli,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'parce que, dans le désert de Tsin, lorsque l\'Assemblée se mutina, vous avez résisté à mon ordre de manifester ma sainteté en faisant jaillir l\'eau à leurs yeux. (Ce sont les Eaux de la Querelle à Cadès dans le désert de Tsin.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Et Moïse parla à l\'Éternel et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Que l\'Éternel, Dieu des esprits de toute chair, prépose un homme sur l\'Assemblée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'lequel sorte à leur tête et entre à leur tête et qui les mène en campagne et les ramène, afin que l\'Assemblée de l\'Éternel ne soit pas comme un troupeau sans berger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Et l\'Éternel dit à Moïse: Prends Josué, fils de Nun, homme en qui l\'esprit se trouve, et pose ta main sur lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'et le présente au Prêtre Eléazar et à toute l\'Assemblée et donne lui tes instructions en leur présence;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'et mets-le en part de ton autorité, pour que toute l\'Assemblée des enfants d\'Israël [lui] obéisse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Et il se présentera au Prêtre Eléazar, et que celui-ci consulte pour lui par le rite de l\'Urim devant l\'Éternel, et à son ordre sortiront et à son ordre entreront lui et tous les enfants d\'Israël avec lui et toute l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Et Moïse se conforma à l\'ordre de l\'Éternel et prit Josué, et le présenta au Prêtre Eléazar et à toute l\'Assemblée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'et il posa ses mains sur lui, et lui donna ses instructions, ainsi que l\'Éternel l\'avait dit par l\'organe de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Transmets ce commandement aux enfants d\'Israël: Vous veillerez à m\'offrir à leurs époques fixes, mes oblations, mon ordinaire pour mes sacrifices ignés, mon parfum agréable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Et dis-leur: Voici le sacrifice igné que vous offrirez à l\'Éternel: deux agneaux d\'un an sans défaut, chaque jour, comme holocauste continuel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Tu sacrifieras l\'un des agneaux le matin et le second dans la soirée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'et pour l\'offrande un dixième d\'épha de fleur de farine trempée d\'un quart de hin d\'huile d\'olives concassées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'C\'est l\'holocauste continuel sacrifié sur le mont de Sinaï pour être un parfum agréable comme sacrifice igné à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Et tu ajouteras à chaque agneau une libation d\'un quart de hin [de vin]; dans le Sanctuaire verse une libation de cervoise à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Et tu sacrifieras le second des deux agneaux dans la soirée. Comme l\'offrande du matin avec sa libation tu offriras un sacrifice igné, parfum agréable à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Et le jour du Sabbat deux agneaux d\'un an sans défaut, et comme offrande deux dixièmes de fleur de farine trempée d\'huile et sa libation en sus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'C\'est l\'holocauste sabbatique à offrir chaque sabbat outre l\'holocauste continuel et sa libation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Et au commencement de vos mois vous offrirez en holocauste à l\'Éternel deux jeunes taureaux et un bélier, sept agneaux d\'un an sans défaut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'avec offrande de trois dixièmes de fleur de farine trempée d\'huile pour chaque taureau, et de deux dixièmes de fleur de farine trempée d\'huile pour un bélier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'et pour offrande un dixième de fleur de farine trempée d\'huile pour chaque agneau, en holocauste, parfum agréable, sacrifice igné à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Et les libations à y ajouter: un demi-hin pour chaque taureau, et un tiers de hin pour le bélier, et un quart de hin de vin par agneau. Tel est l\'holocauste mensuel qu\'on offrira à chaque nouvelle lune de l\'année.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Et un bouc sera sacrifié à l\'Éternel comme victime expiatoire, en sus de l\'holocauste continuel, et sa libation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Et au premier mois, le quatorzième jour du mois, il y aura Pâque en l\'honneur de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Et le quinzième jour de ce mois, il y aura fête; pendant sept jours on mangera des azymes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Le premier jour, sainte convocation: vous vous abstiendrez de toute œuvre de travail,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'et vous offrirez le sacrifice igné d\'un holocauste à l\'Éternel, deux jeunes taureaux et un bélier et sept agneaux d\'un an, qui soient sans défaut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'avec une offrande de fleur de farine trempée d\'huile, trois dixièmes pour chaque taureau, et deux dixièmes pour le bélier, c\'est ce que vous offrirez;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'puis vous offrirez un dixième pour chacun des sept agneaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'et un bouc expiatoire en propitiation pour vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Vous les sacrifierez outre l\'holocauste du matin qui sert à l\'holocauste continuel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'vous l\'offrirez ainsi chacun des sept jours comme nourriture, en sacrifice igné d\'un parfum agréable à l\'Éternel, en sus de l\'holocauste continuel et sa libation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Et le septième jour vous aurez sainte convocation; vous vous abstiendrez de toute œuvre de travail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Et au jour des premiers fruits, lorsque vous offrirez à l\'Éternel une offrande nouvelle après vos semaines [de moisson], vous aurez sainte convocation; vous vous abstiendrez de toute œuvre de travail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Et vous offrirez en holocauste d\'un parfum agréable à l\'Éternel deux jeunes taureaux, un bélier, sept agneaux d\'un an,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'avec une offrande de fleur de farine trempée d\'huile, trois dixièmes pour chaque taureau, deux dixièmes pour le bélier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'un dixième pour chacun des sept agneaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'un bouc pour votre expiation;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'vous les offrirez en sus de l\'holocauste continuel et de l\'offrande qui l\'accompagne; qu\'ils soient sans défaut, et ajoutez-y les libations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Et au septième mois, le premier jour du mois, vous aurez sainte convocation, vous vous abstiendrez de toute œuvre de travail: ce sera pour vous le jour où les trompettes sonneront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Et vous offrirez, en holocauste d\'un parfum agréable à l\'Éternel, un jeune taureau, un bélier, sept agneaux d\'un an sans défaut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'avec une offrande de fleur de farine trempée d\'huile, trois dixièmes pour chaque taureau, deux dixièmes pour le bélier');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'et un dixième pour chacun des sept agneaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'et un bouc comme victime expiatoire en propitiation pour vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'en sus de l\'holocauste mensuel et de l\'offrande qui l\'accompagne, et de l\'holocauste continuel et de l\'offrande et de la libation qui s\'y ajoute, selon le rite, parfum agréable et sacrifice igné à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Et le dixième jour de ce septième mois vous aurez sainte convocation et vous vous humilierez et vous abstiendrez de tout travail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Et vous offrirez à l\'Éternel en holocauste d\'un parfum, agréable un jeune taureau, un bélier, sept agneaux d\'un an qui soient sans défaut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'avec une offrande de fleur de farine trempée d\'huile, trois dixièmes pour chaque taureau, deux dixièmes pour le bélier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'un dixième pour chacun des sept agneaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'un bouc comme victime expiatoire, en sus de la victime expiatoire de propitiation et de l\'holocauste continuel et de l\'offrande et des libations qui s\'y ajoutent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Et le quinzième jour du septième mois, vous aurez sainte convocation, vous vous abstiendrez de toute œuvre de travail, et vous célébrerez une fête en l\'honneur de l\'Éternel pendant sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Et vous offrirez un holocauste en sacrifice igné d\'un parfum agréable à l\'Éternel: treize jeunes taureaux, deux béliers, quatorze agneaux d\'un an qui soient sans défaut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'avec une offrande de fleur de farine trempée d\'huile, trois dixièmes pour chacun des treize taureaux, deux dixièmes pour chacun des deux béliers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'et un dixième pour chacun des quatorze agneaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'et un bouc comme victime expiatoire outre l\'holocauste continuel, l\'offrande et la libation qui s\'y ajoute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Et le second jour, douze jeunes taureaux, deux béliers, quatorze agneaux sans défaut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'avec une offrande et des libations ajoutées aux taureaux, aux béliers et aux agneaux selon le nombre de ceux-ci, suivant le rite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'et un bouc comme victime expiatoire en sus de l\'holocauste continuel, de l\'offrande et des libations qui s\'y ajoutent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Et le troisième jour, onze taureaux, deux béliers, quatorze agneaux d\'un an sans défaut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'avec offrande et libations ajoutées aux taureaux, aux béliers et aux agneaux selon leur nombre, suivant le rite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'et un bouc comme victime expiatoire, en sus de l\'holocauste continuel, de l\'offrande et de la libation qui s\'y ajoute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Et le quatrième jour, dix taureaux, deux béliers, quatorze agneaux d\'un an sans défaut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'avec offrande et libations ajoutées aux taureaux, aux béliers et aux agneaux selon leur nombre, suivant le rite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'et un bouc comme victime expiatoire en sus de l\'holocauste continuel, de l\'offrande et de la libation qui s\'y ajoute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Et le cinquième jour, neuf taureaux, deux béliers, quatorze agneaux d\'un an sans défaut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'avec offrande et libations ajoutées aux taureaux, aux béliers et aux agneaux selon leur nombre, suivant le rite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'et un bouc comme victime expiatoire en sus de l\'holocauste continuel et de l\'offrande et de la libation qui s\'y ajoute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Et le sixième jour, huit taureaux, deux béliers, quatorze agneaux d\'un an sans défaut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'avec l\'offrande et les libations ajoutées aux taureaux, aux béliers et aux agneaux selon leur nombre, suivant le rite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'et un bouc comme victime expiatoire en sus de l\'holocauste continuel, de l\'offrande et des libations qui s\'y ajoutent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Et le septième jour, sept taureaux, deux béliers, quatorze agneaux d\'un an sans défaut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'avec offrandes et libations ajoutées aux taureaux, aux béliers et aux agneaux selon leur nombre, suivant leur rite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'et un bouc comme victime expiatoire, en sus de l\'holocauste continuel, de l\'offrande et de la libation qui s\'y ajoute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Et le huitième jour, vous aurez assemblée solennelle: vous vous abstiendrez de toute œuvre de travail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Et vous offrirez un holocauste en sacrifice igné d\'un parfum agréable à l\'Éternel; un taureau, un bélier, sept agneaux d\'un an sans défaut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'avec offrande et libations ajoutées au taureau, au bélier et aux agneaux selon leur nombre, suivant le rite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'et un bouc comme victime expiatoire, en sus de l\'holocauste continuel, de l\'offrande et de la libation qui s\'y ajoute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Ce sont là les sacrifices que vous offrirez à l\'Éternel dans vos solennités, indépendamment de vos vœux et de vos dons volontaires, en holocaustes, en offrandes, en libations, en sacrifices pacifiques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, 'Et Moïse parla aux enfants d\'Israël conformément à tous les ordres que l\'Eternel avait donnés à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Et Moïse parla aux Chefs des Tribus des enfants d\'Israël en ces termes: Voici ce que prescrit l\'Éternel:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Quand un homme aura fait un vœu à l\'Éternel, ou un serment pour se lier par un engagement, il ne violera pas sa parole, mais il exécutera ce que sa bouche aura prononcé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Et quand une femme aura fait un vœu à l\'Éternel, et se sera, dans la maison de son père pendant son jeune âge, liée par un engagement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'et que son père aura entendu son vœu et l\'engagement par lequel elle s\'est liée, et aura gardé là-dessus le silence, tous ses vœux subsistent, et tous les engagements par lesquels elle s\'est liée, auront leur effet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Mais si son père, le jour où il l\'entend, lui intime une défense, tous ses vœux et tous les engagements par lesquels elle se sera liée, seront sans valeur, et l\'Éternel lui pardonnera, parce que son père lui a intimé une défense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Et si elle est mariée, et qu\'elle soit sous le poids de ses vœux ou d\'une parole légère de ses lèvres qui la lie, et que son mari l\'ait entendue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'et qu\'au jour où il l\'a entendue il ne lui ait rien dit, ses vœux subsistent, et les engagements par lesquels elle se sera liée auront leur effet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Mais si son mari, le jour où il l\'entend, lui intime une défense et casse le vœu sous le poids duquel elle est, ainsi que la parole légère de ses lèvres par laquelle elle s\'est liée, alors l\'Éternel lui pardonnera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Et le vœu d\'une veuve ou d\'une femme répudiée, tous les engagements par lesquels elle se sera liée, subsisteront pour elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Et si une femme dans la maison de son mari fait un vœu ou s\'engage à quelque chose par un serment,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'et que le mari l\'entende, et ne lui dise rien et ne lui intime aucune défense, tous ses vœux subsisteront, et tous les engagements par lesquels elle s\'est liée, subsisteront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Mais si son mari les casse le jour où il les entend, tout ce que sa bouche aura prononcé en fait de vœux ou d\'engagements, n\'aura plus de valeur: son mari les a cassés, et l\'Éternel lui pardonnera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Tout vœu, tout serment qui engage à des macérations, son mari peut le ratifier ou le casser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Et si son mari a gardé là-dessus le silence d\'un jour à l\'autre, il a confirmé tous ses vœux, ou tous les engagements qu\'elle a pris: il les a confirmés parce qu\'il s\'en est tû le jour où il les a entendus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Que s\'il les casse ensuite, après qu\'il les aura entendus, il sera responsable du manquement de la femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Telles sont les règles que l\'Éternel prescrivit à Moïse, enrtre un mari et sa femme, entre un père et sa fille, jeune et étant dans la maison de son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Venge les enfants d\'Israël des Madianites; après quoi tu seras recueilli auprès de ton peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Alors Moïse parla au peuple et dit: Équipez militairement des hommes d\'entre vous qui marchent contre Madian pour exercer sur Madian les vengeances de l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'vous mettrez en campagne mille hommes par Tribu sur toutes les Tribus d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Alors on tira des groupes d\'Israël mille hommes par Tribu, douze mille hommes équipés militairement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Et Moïse les mit en campagne, mille par Tribu, eux et Phinées, fils du Prêtre Eléazar, qui portait avec lui les instruments sacrés et les trompettes pour sonner la charge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Et ils firent la campagne de Madian selon l\'ordre donné à Moïse par l\'Éternel, et ils tuèrent tous les mâles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Et ils ajoutèrent à leurs morts les Rois de Madian Evi et Rékem et Tsur et Hur et Reba, cinq rois de Madian; et ils tuèrent avec l\'épée Balaam, fils de Behor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Et les fils d\'Israël emmenèrent captives les femmes de Madian et leurs enfants, et prirent comme butin tout leur bétail, et tous leurs troupeaux et tous leurs biens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'et ils incendièrent toutes leurs villes dans les lieux qu\'ils habitaient et tous leurs bourgs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Et ils emportèrent tout le butin et toutes les dépouilles en hommes et en bestiaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'et ils les amenèrent à Moïse et au Prêtre Eléazar et à l\'Assemblée des enfants d\'Israël, les captifs et les dépouilles et le butin, au camp dans les plaines de Moab sur le Jourdain près de Jéricho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Alors sortirent à leur rencontre Moïse et le Prêtre Eléazar et tous les Princes de l\'Assemblée en dehors du camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Et Moïse s\'irrita contre les commandants de l\'armée, chefs de mille, et chefs de cent, qui revenaient de l\'expédition.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Et Moïse leur dit: Vous avez laissé la vie à toutes les femmes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Voici, ce sont elles qui, sur le conseil de Balaam, ont été pour les enfants d\'Israël une cause de rébellion contre l\'Éternel à l\'occasion de Pehor; ce qui attira la plaie sur l\'Assemblée de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Maintenant donc tuez tous les mâles parmi les enfants et tuez toute femme qui aura connu un homme en cohabitation;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'mais laissez la vie à toutes les filles enfants qui ne connaissent pas la cohabitation d\'un homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Quant à vous, campez hors du camp pendant sept jours, vous tous qui avez tué des hommes, ou touché des morts tombés dans le combat; vous ferez votre expiation le troisième jour et le septième, vous et vos prisonniers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Et de tous les vêtements, et de tous les ustensiles de cuir, et de tous les tissus de poil de chèvre et de tout meuble de bois vous ferez l\'expiation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Alors le Prêtre Eléazar dit aux hommes de guerre qui avaient fait la campagne: Voici le texte de la loi que l\'Éternel a prescrite à Moïse:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Quant à l\'or, l\'argent, l\'airain, le fer, l\'étain et le plomb,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'tout ce qui va au feu, vous le ferez passer par le feu, pour le rendre pur, et on en fera d\'ailleurs l\'expiation avec l\'eau de purification; seulement tout ce qui ne va pas au feu, vous le passerez dans l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Et lavez vos vêtements le septième jour pour être en état de pureté; puis vous pourrez rentrer au camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Fais le relevé du butin capturé, en hommes et en bestiaux, toi et le Prêtre Eléazar et les chefs de maisons de l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'Et partage les dépouilles entre les gens de guerre qui ont fait la campagne, et toute l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Et prélève un tribut pour l\'Éternel sur les gens de guerre qui ont fait la campagne, un individu sur cinq cents, hommes, bœufs, ânes et menu bétail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Vous le prendrez sur leur moitié, et tu le donneras au Prêtre Eléazar pour le présenter à l\'Éternel par élévation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Et sur la moitié qui ira aux enfants d\'Israël, tu prendras un sur cinquante, soit hommes, soit bœufs, soit ânes, soit menu bétail et animaux de toute espèce, et tu en feras don aux Lévites qui ont la garde de la Résidence de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Et Moïse et Eléazar, le Prêtre, exécutèrent les ordres donnés par l\'Éternel à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Et le butin qui resta des captures faites par les gens de guerre, fut: menu bétail, six cent soixante-quinze mille;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'bœufs, soixante-douze mille;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'ânes, soixante-un mille;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'personnes, parmi les femmes qui n\'avaient pas connu la cohabitation d\'un homme, total des personnes: trente-deux mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Et la moitié échue à ceux qui avaient fait la campagne, fut en menu bétail un nombre de trois cent trente-sept mille cinq cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'Et le tribut levé pour l\'Éternel fut: en menu bétail, six cent soixante-quinze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'et en bœufs (dont il y avait trente-six mille) le tribut pour l\'Éternel fut de soixante-douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'et en ânes (dont il y avait trente mille cinq cents) le tribut pour l\'Éternel fut de soixante-un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'et en personnes (dont il y avait seize mille) le tribut pour l\'Éternel fut de trente-deux personnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Et Moïse remit au Prêtre Eléazar le tribut à offrir par élévation à l\'Éternel, ainsi que l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Et sur la moitié échue aux enfants d\'Israël, que Moïse avait séparée de celle des gens de guerre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '(or cette moitié échue à l\'Assemblée était de trois cent trente-sept mille cinq cents pièces de menu bétail,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'trente-six mille bœufs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'trente mille cinq cents ânes');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'et seize mille personnes),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'sur la moitié donc échue aux enfants d\'Israël, Moïse préleva un sur cinquante, soit hommes, soit pièces de bétail, qu\'il donna aux Lévites chargés de la garde de la Résidence de l\'Éternel, ainsi que l\'Éternel l\'avait prescrit à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Alors s\'approchèrent de Moïse les commandants des divisions de l\'armée, les chefs de mille et les chefs de cent, et ils dirent à Moïse:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'Tes serviteurs ont fait le relevé des gens de guerre qui étaient sous notre conduite, et pas un ne fait défaut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Et nous apportons chacun comme oblation à l\'Éternel ce que nous avons trouvé de joyaux d\'or, chaînettes, bracelets, bagues, boucles d\'oreilles, globules d\'or, pour faire notre propitiation devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Et Moïse et Eléazar, le Prêtre, reçurent d\'eux cet or, ouvragé en toutes sortes de joyaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Et tout l\'or de l\'élévation qu\'ils offrirent à l\'Éternel pesait seize mille sept cent cinquante sicles et venait des chefs de mille et des chefs de cent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Les gens de guerre avaient chacun remporté son butin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Moïse et le Prêtre Eléazar reçurent ainsi cet or des chefs de mille et des chefs de cent, et le portèrent dans la Tente du Rendez-vous comme monument des enfants d\'Israël devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Or les fils de Ruben et les fils de Gad avaient des troupeaux nombreux, très considérables, et ils avaient sous les yeux le pays de Jaëzer et le pays de Galaad, et voici, ces lieux étaient des lieux propres aux troupeaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Alors les fils de Gad et les fils de Ruben s\'adressèrent à Moïse et au Prêtre Eléazar et aux Princes de l\'Assemblée et dirent:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Ataroth et Dibon et Jaëzer et Nimra et Hesbon et Eléalé et Sebam et Nébo et Bebon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'le pays que l\'Éternel a vaincu à la tête de l\'Assemblée d\'Israël, est un pays propre aux troupeaux, et tes serviteurs ont des troupeaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Et ils dirent: Si nous avons trouvé grâce à tes yeux, que ce pays soit donné en propriété à tes serviteurs, ne nous fais pas passer le Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Moïse répondit aux fils de Gad et aux fils de Ruben: Vos frères marcheront-ils au combat, et vous, resterez-vous ici?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Pourquoi voulez-vous ôter aux enfants d\'Israël le désir de passer dans le pays que leur a donné l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Ainsi firent vos pères, lorsque je les envoyai de Cadès-Barnéa explorer le pays: ils s\'avancèrent jusqu\'à la vallée d\'Escol, et après avoir vu le pays,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'ils ôtèrent aux enfants d\'Israël le désir d\'entrer dans le pays que leur donnait l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Alors en ce jour même la colère de l\'Éternel s\'alluma et Il prononça ce serment:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Ces hommes sortis de l\'Egypte, âgés de vingt ans et plus, ne verront pas le sol que je promis par serment à Abraham, à Isaac et à Jacob, car ils ne m\'ont pas rendu une pleine obéissance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'excepté Caleb, fils de Jephunné, issu de Kenaz, et Josué, fils de Nun, qui ont rendu à l\'Éternel une pleine obéissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Ainsi la colère de l\'Éternel s\'alluma contre Israël et Il les fit errer quarante ans dans le désert jusqu\'à l\'extinction de toute la génération qui avait fait le mal aux yeux de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Et voilà que vous succédez à vos pères, à cette race de pécheurs, pour accroître encore la colère de l\'Éternel contre Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Si vous lui faites défection, Il le laissera plus longtemps encore dans le désert, et vous entraînerez la perte de tout ce peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Alors s\'approchant de lui ils dirent: Nous construirons ici des parcs pour nos troupeaux et des villes pour nos enfants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'mais nous-mêmes, de suite nous marcherons armés en tête des enfants d\'Israël jusqu\'à ce que nous les ayons introduits dans leur séjour; et nos enfants demeureront dans les villes fortifiées contre les habitants du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Nous ne rentrerons pas dans nos maisons que les enfants d\'Israël n\'aient pris chacun possession de son héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Car nous ne voulons pas nous établir avec eux de l\'autre côté du Jourdain et plus loin, puisque notre héritage se présente pour nous au delà du Jourdain vers le levant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Là-dessus Moïse leur dit: Si vous le faites, si vous marchez en armes au combat sous les yeux de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'et que toute votre milice passe le Jourdain sous les yeux de l\'Éternel, jusqu\'à ce qu\'il ait chassé ses ennemis devant Lui, et que tout le pays ait été soumis par l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'et si vous revenez seulement alors, vous serez quittes envers l\'Éternel et envers Israël et ce pays vous appartiendra en propre devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Mais si vous n\'agissez pas ainsi, voici, vous péchez contre l\'Éternel et vous ressentirez les effets de votre péché, qui vous atteindront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Bâtissez-vous des villes pour vos enfants et des parcs pour vos troupeaux, et ce que votre bouche a promis, tenez-le.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Alors les fils de Gad et les fils de Ruben parlèrent à Moïse en ces termes: Tes serviteurs agiront ainsi que mon Seigneur l\'ordonne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Nos enfants, nos femmes, nos troupeaux, et tout notre bétail resteront ici dans les villes de Galaad,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'et tes serviteurs, toute leur milice guerrière, passeront sous les yeux de l\'Éternel pour prendre part au combat, ainsi que mon Seigneur le dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Et Moïse donna pour eux ses ordres au Prêtre Eléazar, et à Josué, fils de Nun, et aux patriarches des Tribus des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'Et Moïse leur dit: Si les fils de Gad et les fils de Ruben passent avec vous le Jourdain, tous équipés pour le combat, devant l\'Éternel, alors, une fois le pays mis sous vos pieds devant vous, vous leur donnerez le pays de Galaad en propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Mais s\'ils ne marchent pas en armes avec vous, qu\'ils obtiennent leur lot au milieu de vous dans le pays de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Alors les fils de Gad et les fils de Ruben répondirent et dirent: Ce que l\'Éternel a dit à tes serviteurs, nous le ferons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Nous entrerons en armes sous les yeux de l\'Éternel au pays de Canaan, mais que l\'on nous mette en possession de notre lot de ce côté du Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Ainsi Moïse donna aux fils de Gad et aux fils de Ruben, et à la demi-Tribu de Manassé, fils de Joseph, le royaume de Sihon, Roi des Amoréens, et le royaume de Og, Roi de Basan, ce pays avec ses villes, et les territoires environnants des villes du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Et les fils de Gad bâtirent Dibon et Ataroth et Aroër,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'et Atrothsophan et Jaëzer et Jogbeha');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'et Beth-Nimra et Beth-Haran, villes fortes et parcs de moutons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Et les fils de Ruben rebâtirent Hesbon et Eléalé et Kiriathaïm');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'et Nébo et Bahal-Meon, dont les noms furent changés, et Sibma; et ils donnèrent des noms aux villes qu\'ils bâtirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Et les fils de Machir, fils de Manassé, marchèrent contre Galaad et s\'en emparèrent et chassèrent les Amoréens qui y étaient établis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Et Moïse donna Galaad à Machir, fils de Manassé, qui s\'y établit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Et Jaïr, fils de Manassé, se mit en marche, et en conquit les bourgs qu\'il appela Bourgs de Jaïr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Et Nobah se mit en marche et conquit Kenath et ses dépendances et il l\'appela Nobah de son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Stations des enfants d\'Israël sortis du pays d\'Egypte, formant leurs divisions sous la conduite de Moïse et d\'Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Moïse mit par écrit leurs marches selon leurs stations sur l\'ordre de l\'Éternel, et voici les stations qu\'ils firent dans leurs marches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Ils partirent de Raemsès dans le premier mois, le quinzième jour du premier mois; le lendemain de la Pâque, les enfants d\'Israël sortirent la main haute, aux yeux de toute l\'Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'tandis que les Égyptiens donnaient la sépulture à ceux que l\'Éternel avait frappés parmi eux, à tous les premiers-nés; et l\'Éternel exerçait ses jugements sur leurs dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Étant donc partis de Raemsès, ils vinrent camper à Succoth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Et partis de Succoth ils vinrent camper à Etham situé à l\'extrémité du désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Et partis d\'Etham ils revinrent sur Pi-Hahiroth située vis-à-vis de Baal-Tsephon et campèrent devant Migdol.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Et partis de Hahiroth ils arrivèrent au travers de la mer dans le désert, et firent trois journées de marche dans le désert d\'Etham et campèrent à Mara.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Et partis de Mara ils parvinrent à Elim, or à Elim il y avait douze sources d\'eau et soixante-dix palmiers; et ils y campèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Et partis d\'Elim ils vinrent camper vers la Mer aux algues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Et partis de la Mer aux algues ils vinrent camper dans le désert de Sin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Et partis du désert de Sin ils vinrent camper à Dophka.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Et partis de Dophka ils vinrent camper à Alus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Et partis d\'Alus ils vinrent camper à Raphidim; or le peuple n\'y trouva point d\'eau à boire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Et partis de Raphidim ils vinrent camper dans le désert de Sinaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Et partis du désert de Sinaï ils vinrent camper aux Tombeaux de la convoitise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Et partis des Tombeaux de la convoitise ils vinrent camper à Hatseroth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Et partis de Hatseroth ils vinrent camper à Rithma.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Et partis de Rithma ils vinrent camper à Rimmon-Parets.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Et partis de Rimmon-Parets ils vinrent camper à Libna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Et partis de Libna ils vinrent camper à Rissa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Et partis de Rissa ils vinrent camper à Kehelatha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Et partis de Kehelatha ils vinrent camper au mont Sapher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Et partis du mont Sapher ils vinrent camper à Harada.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Et partis de Harada ils vinrent camper à Makheloth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Et partis de Makheloth ils vinrent camper à Thahath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Et partis de Thahath ils vinrent camper à Tharach.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Et partis de Tharach ils vinrent camper à Mithka.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Et partis de Mithka ils vinrent camper à Hasmona.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Et partis de Hasmona ils vinrent camper à Moseroth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Et partis de Moseroth ils vinrent camper à Bnei-Jaakan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Et partis de Bnei-Jaakan ils vinrent camper à Hor-Gidgad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Et partis de Hor-Gidgad ils vinrent camper à Jotbatha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Et partis de Jotbatha ils vinrent camper à Abrona.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Et partis de Abrona ils vinrent camper à Etsion-Géber.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Et partis de Etsion-Géber ils vinrent camper dans le désert de Tsin: c\'est Cadès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Et partis de Cadès ils vinrent camper au mont Hor, sur la frontière du pays d\'Edom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'C\'est alors que le Prêtre Aaron monta sur le mont Hor, d\'après l\'ordre de l\'Éternel, et qu\'il y mourut la quarantième année après la sortie des enfants d\'Israël hors du pays d\'Egypte, le cinquième mois, le premier jour du mois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, '(or Aaron était âgé de cent vingt-trois ans, lorsqu\'il mourut sur le mont Hor).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Et le Cananéen, Roi de Arad, établi dans le Midi du pays de Canaan entendit parler de l\'arrivée des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Et étant partis du mont Hor ils vinrent camper à Tsalmona.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Et partis de Tsalmona ils vinrent camper à Punon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Et partis de Punon ils vinrent camper à Oboth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Et partis d\'Oboth ils vinrent camper à Jiim, à la frontière de Moab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Et partis de Jiim ils vinrent camper à Dibon-Gad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Et partis de Dibon-Gad ils vinrent camper à Almon-Diblathaïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Et partis de Almon-Diblathaïm ils vinrent camper aux monts Abarim devant le Nébo.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Et partis des monts Abarim ils vinrent camper dans les plaines de Moab sur le Jourdain près de Jéricho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Et ils campèrent sur le Jourdain, de Beth-Jesimoth à Abel-Sittim dans les plaines de Moab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Et l\'Éternel parla à Moïse dans les plaines de Moab sur le Jourdain près de Jéricho, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Parle aux enfants d\'Israël et dis-leur: Quand après le passage du Jourdain vous serez entrés dans le pays de Canaan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'vous chasserez tous les habitants du pays devant vous, détruirez toutes leurs [pierres] figurées et détruirez toutes leurs images de fonte et raserez tous leurs tertres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'et vous occuperez le pays et vous y établirez, car je vous ai donné ce pays pour en prendre possession.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Et vous vous partagerez le pays au sort selon vos familles; aux plus nombreux vous adjugerez un lot plus étendu; aux moins nombreux, un lot plus restreint; l\'emplacement échu par le sort à quelqu\'un, c\'est ce qu\'il aura; vous vous le partagerez d\'après vos Tribus patriarcales.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Mais si vous ne chassez pas devant vous les habitants du pays, ceux d\'entre eux que vous laisserez, deviendront des épines pour vos yeux, et des aiguillons dans vos flancs et ils vous mettront à la gêne dans le pays où vous serez établis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Et il arrivera que ce que j\'avais résolu de leur faire, c\'est à vous que je le ferai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Donne des ordres aux enfants d\'Israël et leur dis: Quand vous entrerez dans le pays de Canaan, c\'est le pays qui doit vous échoir en propriété, le pays de Canaan selon ses limites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Vous aurez la région du Midi depuis le désert de Tsin à côté d\'Edom, et l\'extrémité de la Mer salée sera votre frontière méridionale du côte de l\'Orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Puis votre frontière tournera au Midi de la Hauteur des Scorpions et courra jusqu\'à Tsin pour aboutir au Sud de Cadès-Barnéa, et à partir de là elle ira jusqu\'à Hatsar-Addar et passera par Atsmona.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'Et d\'Atsmona votre frontière contournera vers le torrent d\'Egypte pour aboutir à la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Limite occidentale: vous aurez pour limite la Grande Mer: ce sera votre frontière à l\'Ouest.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Et voici quelle sera votre frontière au Nord: de la Grande Mer vous délimiterez jusqu\'au mont Hor (Liban);');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'du mont Hor vous délimiterez jusqu\'à Hamath pour faire aboutir la frontière à Tsedad;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'à partir de là elle ira à Ziphron pour aboutir à Hatsar-Einan. Telle sera votre frontière au Nord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Et pour la frontière orientale délimitez de Hatsar-Einan à Sepham;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'et de Sepham la frontière descendra à Ribla à l\'Orient de Aïn, puis descendra encore et longera les rives du lac de Génésareth à l\'Orient,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'puis descendra au Jourdain pour aboutir à la Mer salée. Ce sera là votre pays circonscrit par ses frontières.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Et Moïse donna cet ordre aux enfants d\'Israël: C\'est là le pays que vous vous partagerez au sort, que l\'Éternel a adjugé aux neuf Tribus et à la demi-Tribu de [Manassé].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Car la Tribu des fils de Ruben et la Tribu des fils de Gad ont reçu leur lot chacune en raison de leurs familles patriarcales, de même la demi-Tribu de Manassé a reçu son lot;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'ces deux Tribus et la demi-Tribu de Manassé ont reçu leur lot au delà du Jourdain près de Jéricho, à l\'Orient, vers le levant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Voici les noms des hommes qui vous partageront le pays: le Prêtre Eléazar et Josué, fils de Nun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Et vous prendrez pour faire le partage du pays un prince par Tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Or voici les noms de ces hommes: Pour la Tribu de Juda, Caleb, fils de Jephunné;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'et pour la Tribu des fils de Siméon, Semuel, fils de Ammihud;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'pour la Tribu de Benjamin, Elidad, fils de Ghislon;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'et pour la Tribu des fils de Dan, un prince, Buki, fils de Jogli;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'pour les fils de Joseph, pour la Tribu des fils de Manassé, un prince, Hanniel, fils de Ephod;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'et pour la Tribu des fils d\'Ephraïm, un prince, Kemuel, fils de Siphtan;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'et pour la Tribu des fils de Zabulon, un prince, Elitsaphan, fils de Pharnach;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'et pour la Tribu des fils d\'Issaschar, un prince, Paltiel, fils de Azzan;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'et pour la Tribu des fils d\'Asser, un prince, Ahihud, fils de Selomi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'et pour la Tribu des fils de Nephthali, un prince, Pedahel, fils de Ammihud.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Tels sont ceux que l\'Éternel a désignés pour distribuer aux enfants d\'Israël leurs lots dans le pays de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Et l\'Éternel parla à Moïse dans les plaines de Moab sur le Jourdain près de Jéricho, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Ordonne aux enfants d\'Israël de donner aux Lévites, sur leurs propriétés héréditaires, des villes pour y habiter, et donnez aussi aux Lévites une banlieue autour de leurs villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Et les villes leur serviront pour s\'y loger, et les banlieues, pour recevoir leur bétail, leurs biens et tous leurs animaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Et les banlieues des villes que vous donnerez aux Lévites auront, à l\'extérieur depuis la muraille de la ville, une étendue de deux mille coudées en circuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Et en dehors de la ville vous mesurerez au côté oriental deux mille coudées, et au côté méridional deux mille coudées, et au côté occidental deux mille coudées, et au côté septentrional deux mille coudées, la ville étant au centre: telles seront les banlieues des villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Et parmi les villes que vous donnerez aux Lévites, il y aura six villes de Refuge que vous destinerez à recevoir le meurtrier fugitif et en sus desquelles vous donnerez encore quarante-deux villes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'toutes les villes que vous donnerez aux Lévites seront donc au nombre de quarante-huit, chacune avec sa banlieue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Et quant aux villes que vous donnerez sur les propriétés des enfants d\'Israël, vous prendrez plus de celui qui a plus, et moins de celui qui a moins; chacun donnera de ses villes aux Lévites le nombre proportionné au lot qu\'il aura en partage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Et l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Parle aux enfants d\'Israël et leur dis: Quand après le passage du Jourdain vous entrerez dans le pays de Canaan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'vous choisirez des villes propres à servir de villes de Refuge où puisse se réfugier l\'homicide qui aura tué une personne par mégarde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Et ces villes vous seront un asile contre le vengeur du sang, afin qu\'un homicide ne meure pas jusqu\'à ce qu\'il ait comparu devant l\'Assemblée pour être jugé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Et les villes que vous désignerez seront au nombre de six villes de Refuge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Vous désignerez trois villes au delà du Jourdain, et trois villes dans le pays de Canaan: elles seront villes de Refuge:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'ces six villes serviront d\'asile aux enfants d\'Israël, et à l\'étranger et au domicilié pour que s\'y réfugie quiconque aura tué une personne par mégarde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Si c\'est avec un instrument de fer qu\'il l\'a frappée jusqu\'à donner la mort, il est meurtrier: le meurtrier est mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Et si en frappant il tenait une pierre qui pût donner la mort, et que la mort ait suivi, il est meurtrier: le meurtrier est mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Ou si en frappant il tenait un morceau de bois qui pût donner la mort et que la mort ait suivi, il est meurtrier: le meurtrier est mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'C\'est le vengeur du sang qui donnera la mort au meurtrier; s\'il le rencontre, il le tuera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Et si par haine il a fait tomber quelqu\'un, ou lui a lancé quelque objet avec intention et que la mort ait suivi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'ou si par inimitié il l\'a frappé de la main à le faire mourir; celui qui a frappé sera mis à mort; il est meurtrier; le vengeur du sang tuera le meurtrier, s\'il le rencontre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Mais si par aventure, sans inimitié, il a fait tomber quelqu\'un, ou lui a lancé un objet quelconque sans intention,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'ou si avec une pierre quelconque qui peut donner la mort, il l\'a frappé sans voir, ou qu\'il ait fait tomber la pierre sur lui et ainsi l\'ait tué, sans être toutefois son ennemi ni avoir cherché à lui faire du mal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'que l\'Assemblée juge entre celui qui a porté le coup et le vengeur du sang, d\'après ces règles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'et que l\'Assemblée sauve l\'homicide des mains du vengeur du sang et le fasse rentrer dans la ville de Refuge où il s\'était réfugié, et qu\'il y reste jusqu\'à la mort du Grand-Prêtre qui a reçu l\'onction d\'huile sainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Mais si l\'homicide sort au delà des limites de la ville de Refuge où il s\'est réfugié,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'et que le vengeur du sang le trouve en dehors des limites de la ville de Refuge, et que le vengeur du sang tue l\'homicide, il n\'est pas coupable de meurtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Car il doit rester dans sa ville de Refuge jusqu\'à la mort du Grand-Prêtre, et ce n\'est qu\'après la mort du Grand-Prêtre qu\'il peut rentrer dans son pays d\'héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Et que ceci soit pour vous une règle de droit pour toutes vos générations et partout où vous serez établis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Lorsqu\'un homme quelconque aura commis un meurtre sur un autre, on mettra à mort le meurtrier sur la déclaration de témoins; mais la déposition d\'un seul témoin à charge ne suffit pas pour une sentence de mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Et vous n\'accepterez aucune rançon pour la vie d\'un meurtrier digne de mort, mais il subira la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Et vous n\'accepterez point de rançon pour le laisser fuir dans sa ville de Refuge et en revenir et habiter dans le pays après la mort du Prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Et vous ne profanerez point le pays où vous êtes, car le sang profane le pays, et pour le pays l\'expiation ne peut être faite du sang qui y a été versé, que par le sang de celui qui l\'a versé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Et tu ne souilleras pas le pays que vous habitez, au sein duquel je réside, car moi l\'Éternel je réside au milieu des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Et se présentèrent les chefs de maisons de la famille des fils de Galaad, fils de Machir, fils de Manassé, des familles des fils de Joseph, et ils parlèrent devant Moïse et devant les princes, chefs de maisons des enfants d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'et dirent: L\'Éternel a prescrit à mon seigneur de donner par le sort le pays en propriété aux enfants d\'Israël, et mon seigneur a reçu de l\'Éternel l\'ordre d\'accorder l\'héritage de Tselophehad, notre frère, à ses filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Si donc elles se marient à l\'un des fils d\'une autre Tribu des enfants d\'Israël, leur héritage sera défalqué de l\'héritage de nos pères et sera ajouté au lot de la Tribu à laquelle elles appartiendront, et il sera défalqué du lot que nous possédons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Et quand viendra le Jubilé pour les enfants d\'Israël, leur héritage sera ajouté au lot de la Tribu dans laquelle elles seront, et leur héritage sera défalqué du lot de la Tribu de nos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Alors sur le commandement de l\'Éternel, Moïse rendit cette ordonnance aux enfants d\'Israël: La Tribu des fils de Joseph a raison dans ce qu\'elle dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Voici ce que prescrit l\'Éternel quant aux filles de Tselophehad: elles peuvent épouser qui bon leur semblera; seulement elles doivent se marier dans une famille de la Tribu de leur père,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'afin qu\'aucune propriété des enfants d\'Israël ne passe d\'une Tribu dans l\'autre; mais les enfants d\'Israël doivent chacun rester attachés à l\'héritage de la Tribu de ses pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Et toute fille, héritière d\'une propriété dans les Tribus des enfants d\'Israël, devra épouser quelqu\'un d\'une famille de la Tribu de son père, afin que les enfants d\'Israël héritent chacun leur propriété paternelle');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'et qu\'aucun lot ne passe d\'une Tribu dans l\'autre, mais que chacune des Tribus des enfants d\'Israël reste attachée à son héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Les filles de Tselophehad se conformèrent à l\'ordre donné par l\'Éternel à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Et Mahela, Tirtsa, et Hogla et Milca et Noa, filles de Tselophehad, devinrent femmes des fils des frères de leur père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'c\'est dans les familles des fils de Manassé, fils de Joseph, qu\'elles se marièrent, et leur propriété resta dans la Tribu de la famille de leur père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Telles sont les ordonnances et les lois que l\'Éternel prescrivit par l\'organe de Moïse aux enfants d\'Israël dans les plaines de Moab sur le Jourdain près de Jéricho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Ce sont ici les discours que Moïse adressa à tout Israël au delà du Jourdain dans le désert, dans la plaine vis-à-vis de Suph entre Paran et Thophel et Laban et Hatseroth et Dizahab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Il y a onze journées de marche de Horeb, par la route de la montagne de Séir, à Cadès-Barnéa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Et dans la quarantième année, dans le onzième mois, le premier jour du mois, Moïse exposa aux enfants d\'Israël toutes les choses dont l\'Éternel l\'avait chargé pour eux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'après qu\'il eut défait Sihon, Roi des Amoréens, qui résidait à Hesbon, et Og, Roi de Basan, qui résidait à Astharoth, près de Edrei.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Au delà du Jourdain, dans le pays de Moab, Moïse commença à expliquer cette Loi en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'L\'Éternel, notre Dieu, nous parla sur Horeb en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Vous avez assez séjourné dans cette montagne. Faisant volte-face mettez-vous en marche et gagnez les Monts Amoréens et tous les lieux adjacents de la plaine, de la montagne, du Pays-bas et du Midi et du bord de la mer, le pays des Cananéens et le Liban jusqu\'au Grand-Fleuve, le fleuve Phrath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Voici, je vous livre ce pays, marchez à la conquête du pays que l\'Éternel a juré à vos pères, à Abraham, à Isaac et à Jacob de leur donner et à leur race après eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Et dans ce temps-là je vous dis: Je ne puis, à moi seul, être chargé de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'L\'Éternel, votre Dieu, vous a multipliés et voilà que vous êtes aujourd\'hui égaux en nombre aux étoiles du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Que l\'Éternel, Dieu de vos pères, augmente mille fois votre nombre présent, et qu\'il vous bénisse, comme Il vous l\'a promis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Mais comment serais-je, à moi seul, chargé de votre poids et de votre fardeau et de vos contestations?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Donnez-vous donc des hommes sages, intelligents et connus tirés de vos Tribus, et je les mettrai à votre tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Et vous me répondîtes et dîtes: La chose que tu nous proposes de faire est bonne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Alors je pris les chefs de vos Tribus, hommes sages et connus, et je les préposai sur vous comme supérieurs, comme chefs de mille, et chefs de cent, et chefs de cinquante, et chefs de dix, et comme officiers de vos Tribus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Et dans le même temps je donnai à vos Juges mes instructions en ces termes: Donnez audience à vos frères en cause l\'un avec l\'autre, et dites justice entre un homme et son prochain et son étranger;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'ne faites point acception des personnes dans le jugement; écoutez le petit comme le grand; n\'ayez peur de personne; car c\'est le tribunal de Dieu. Et les causes qui seront trop difficiles pour vous, portez-les devant moi, pour que j\'en connaisse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'C\'est ainsi que dans ce temps je vous prescrivis toutes les choses que vous aviez à faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Puis étant partis d\'Horeb nous parcourûmes tout le désert, ce grand et affreux désert que vous avez vu sur le chemin des Monts Amoréens, ainsi que l\'Éternel, notre Dieu, nous l\'avait commandé, et nous arrivâmes à Cadès-Barnéa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Et je vous dis: Vous êtes parvenus aux Monts Amoréens que l\'Éternel, notre Dieu, va nous donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Vois, l\'Éternel, ton Dieu, t\'a livré ce pays, montes-y, fais-en la conquête, comme te l\'a dit l\'Éternel, Dieu de tes pères; sois sans crainte et sans peur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Alors vous vîntes tous vous présenter à moi, et vous dîtes: Envoyons des hommes en avant de nous, qui examinent pour nous ce pays, et reviennent nous informer de la route par où nous devons y monter et des villes où nous arriverons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Et j\'agréai la chose, et je choisis parmi vous douze hommes, un homme par Tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Et ils partirent et gravirent la montagne, et s\'avancèrent jusqu\'à la vallée d\'Escol, et ils firent la reconnaissance de ce pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Et ils prirent dans leurs mains des fruits de ce pays et nous les rapportèrent et nous rendirent compte en ces mots: C\'est un bon pays que l\'Éternel, notre Dieu, veut nous donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Mais vous ne voulûtes pas y monter, et vous fûtes rebelles à l\'ordre de l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Et murmurant dans vos tentes vous dîtes: C\'est parce que l\'Éternel nous hait, qu\'il nous a retirés du pays d\'Egypte pour nous livrer aux mains des Amoréens, afin de nous détruire. Où irons-nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Nos frères ont amolli notre courage en disant: C\'est un peuple plus nombreux et de plus haute taille que nous, ce sont des villes grandes et fortifiées jusqu\'au ciel; et nous y avons aussi vu les fils des Anakites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Et je vous dis: Ne vous épouvantez pas et n\'ayez pas peur d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'L\'Éternel, votre Dieu, qui marche à votre tête, combattra lui-même pour vous, comme Il a toujours fait pour vous en Egypte à vos yeux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'et dans le désert où tu as vu que l\'Éternel, ton Dieu, t\'a porté ainsi qu\'un père porte son fils, tout le long de la route que vous avez parcourue, jusqu\'à votre arrivée en ce lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Mais malgré cela vous n\'eûtes pas foi dans l\'Éternel, votre Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'qui vous précédait dans le trajet pour vous explorer un lieu où pouvoir camper, la nuit dans la colonne de feu pour vous faire voir la route que vous aviez à suivre, et le jour dans la nuée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Et l\'Éternel entendit vos propos et se courrouça et prononça ce serment:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Pas un de ces hommes dans cette race méchante ne verra ce beau pays que je promis par serment, de donner à leurs pères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'sauf Caleb, fils de Jephunné; lui, il le verra et je lui donnerai la contrée qu\'il a touchée de ses pieds, ainsi qu\'à ses fils, parce qu\'il a eu pour l\'Éternel une pleine obéissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Même contre moi l\'Éternel fut irrité à cause de vous et Il dit: Toi non plus tu n\'y entreras pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Josué, fils de Nun, qui se tient debout en ta présence, lui, y entrera; encourage-le, car c\'est lui qui en fera le partage à Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Et vos enfants desquels vous dites qu\'ils seront un butin, et vos fils qui aujourd\'hui n\'ont pas la connaissance du bien et du mal, ce sont eux qui y entreront, et c\'est à eux que je le donnerai, et eux qui en feront la conquête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Quant à vous, faites volte-face et partez pour le désert du côté de la Mer aux algues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Alors vous répondîtes et me dîtes: Nous avons péché contre l\'Éternel, nous irons en avant et nous battrons absolument comme l\'Éternel, notre Dieu, nous l\'a commandé. Et vous ceignîtes chacun ses armes, et eûtes la témérité de vous avancer dans la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Et l\'Éternel me dit: Dis-leur: N\'avancez pas, et ne livrez pas bataille, car je ne suis pas au milieu de vous, afin que vous ne soyez pas mis en déroute par vos ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Et je vous parlai, mais vous n\'écoutâtes point et vous contrevîntes à l\'ordre de l\'Éternel, et vous eûtes l\'audace de vous avancer dans la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Alors les Amoréens, habitants de cette montagne, sortirent à votre rencontre, et vous donnèrent la chasse comme font les abeilles et ils vous défirent en Séir jusqu\'à Horma.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Et vous revîntes et pleurâtes devant l\'Éternel, mais l\'Éternel n\'écouta point votre voix et ne prit point garde à vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Ainsi vous restâtes longtemps à Cadès, le temps que vous y avez passé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Faisant donc volte-face nous partîmes pour le désert du côté de la Mer aux Algues, comme l\'Éternel me l\'avait dit, et nous tournâmes longtemps autour de la montagne de Séir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Et l\'Éternel me parla en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Vous avez assez tourné autour de cette montagne, dirigez-vous vers le Nord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Et donne au peuple cet ordre: Vous allez passer à la frontière de vos frères, les fils d\'Esaü, établis en Séir, et ils ont peur de vous; aussi tenez-vous bien sur vos gardes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'N\'entrez pas en conflit avec eux, car je ne vous donnerai rien de leur pays, pas même l\'espace de la plante d\'un pied, car j\'ai donné les montagnes de Séir en propriété à Esaü.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Vous achèterez d\'eux des vivres à prix d\'argent pour avoir à manger, et aussi l\'eau vous l\'achèterez d\'eux à prix d\'argent pour votre boisson;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'car l\'Éternel, ton Dieu, t\'a béni dans tout le travail de tes mains: Il a surveillé ton voyage dans ce grand désert: voici quarante ans que l\'Éternel, ton Dieu, a été avec toi, tu n\'as manqué de rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'C\'est pourquoi nous passâmes outre à distance de nos frères, les fils d\'Esaü, établis en Séir, du chemin de la plaine, d\'Elath et de Etsion-Géber, et tournant nous prîmes la direction du désert de Moab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Alors l\'Éternel me dit: N\'attaque pas Moab et n\'engage pas le combat avec lui, car de son pays je ne t\'accorde rien en propriété, puisque j\'ai donné Ar en propriété aux fils de Lot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '(Il était jadis habité par les Emites, peuple grand et nombreux et de haute taille, comme les Anakites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'ils sont aussi regardés comme des géants, ainsi que les Anakites; et les Moabites les appellent Emites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Et jadis Séir fut habité par les Horites, et les fils d\'Esaü les expulsèrent, et les exterminèrent de devant eux, et s\'établirent à leur place, comme l\'ont fait les Israélites dans leur pays de conquête que leur a donné l\'Éternel.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Maintenant debout! et passez le torrent de Zared. Nous passâmes donc le torrent de Zared.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Et le temps écoulé depuis notre départ de Cadès-Barnéa jusqu\'à notre passage du torrent de Zared fut de trente-huit ans, ayant duré jusqu\'à ce que toute la génération des hommes de guerre fut disparue du camp, comme l\'Éternel leur en avait fait le serment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Et la main de l\'Éternel aussi agit contre eux pour les faire disparaître du milieu du camp jusqu\'à leur extinction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Et lorsque tous les gens de guerre furent disparus du peuple, étant morts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'l\'Éternel me parla en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Tu vas passer maintenant à la frontière de Moab, à Ar,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'et te rapprocher des fils d\'Ammon; ne les attaque pas et n\'entre pas en conflit avec eux; car du pays des fils d\'Ammon je ne t\'accorde rien en propriété, puisque je l\'ai donné en propriété aux fils de Lot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(Il est aussi regardé comme un pays de géants; jadis des géants l\'habitaient, et les Ammonites les appellent Zamsumites,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'peuple grand et nombreux et de haute taille, comme les Anakites, et l\'Éternel les extermina de devant eux, et ils les expulsèrent et s\'établirent à leur place,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'comme Il avait fait pour les fils d\'Esaü établis en Séir, lorsqu\'il détruisit les Horites devant eux; et ils les chassèrent et se sont établis à leur place jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Et les Avites qui habitaient dans des bourgs jusqu\'à Gaza furent détruits par des Caphthorites venus de Caphthor, qui s\'établirent à leur place.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Levez-vous, partez et passez le torrent de l\'Arnon. Voici, je livre entre tes mains Sihon, Roi de Hesbon, l\'Amoréen et son pays: commence! fais-en la conquête, et engage le combat avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Aujourd\'hui je commence à inspirer de toi une terreur et une peur telle à tous les peuples qui sont sous le ciel entier, qu\'au bruit de ta renommée ils seront terrifiés et angoissés par toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Alors, du désert de Kedémoth, j\'envoyai des messagers à Sihon, Roi de Hesbon, avec des paroles de paix, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Laisse-moi passer par ton pays! je ne suivrai que la grand\'route, sans m\'écarter ni à droite ni à gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Tu me vendras des vivres à prix d\'argent pour ma nourriture, et tu me fourniras de l\'eau contre de l\'argent pour ma boisson; je ne passerai que de mes pieds;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'ainsi en ont agi avec moi les fils d\'Esaü établis en Séir, et les Moabites établis à Ar, jusqu\'à ce qu\'ayant passé le Jourdain je sois dans le pays que nous donne l\'Éternel, notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Mais Sihon, Roi de Hesbon, ne voulut pas nous laisser passer chez lui; car l\'Éternel, ton Dieu, avait roidi son esprit et endurci son cœur pour le livrer entre tes mains, comme [on le voit] aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Et l\'Éternel me dit: Vois, je commence aujourd\'hui à te livrer Sihon et son pays; commence la conquête par la conquête de son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Et Sihon sortit à notre rencontre, lui et tout son peuple, pour nous attaquer à Jahaths.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Mais l\'Éternel, notre Dieu, nous le livra, et nous le vainquîmes lui et ses fils et tout son peuple, nous emparant en même temps de toutes ses villes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'et nous dévouâmes toute ville, hommes, femmes et enfants, sans laisser survivre aucun réchappé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Seulement nous fîmes notre butin du bétail et de la dépouille des villes prises par nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Depuis Aroër située sur le bord du torrent de l\'Arnon et la ville dans la vallée, jusqu\'à Galaad il n\'y eut pas une ville trop haut placée pour nous. L\'Éternel, notre Dieu, nous livra tout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Seulement tu ne t\'es pas approché du pays des Ammonites, de tous les bords du torrent de Jabbok, ni des villes de la montagne ni d\'aucun des lieux que l\'Éternel, notre Dieu, nous avait interdits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Et étant partis nous montâmes du côté de Basan; alors vint à notre rencontre Og, Roi de Basan, lui et tout son peuple pour nous attaquer à Edrei.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Et l\'Éternel me dit: Ne le redoute pas, car je livre entre tes mains, et lui et tout son peuple et son pays, et tu le traiteras comme tu as traité Sihon, Roi des Amoréens, qui résidait à Hesbon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'L\'Éternel, notre Dieu, livra, donc aussi entre nos mains Og, Roi de Basan, et tout son peuple, et nous le battîmes jusqu\'à ne lui laisser aucun réchappé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Et en même temps nous prîmes toutes ses villes; il n\'y eut pas une place que nous ne leur enlevâmes, soixante villes, tout le canton d\'Argob, royaume de Og en Basan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Toutes ces villes, à l\'exception des villes rurales, très nombreuses, étaient munies de hautes murailles, de portes et de barres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Et nous les dévouâmes, comme nous l\'avions fait à Sihon, Roi de Hesbon, dévouant toutes villes, hommes, femmes et enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Mais nous fîmes notre butin de la totalité du bétail et des dépouilles des villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'C\'est ainsi qu\'en ce temps-là nous conquîmes le pays sur les deux rois des Amoréens au delà du Jourdain depuis le torrent de l\'Arnon jusqu\'au mont Hermon');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(les Sidoniens donnent à l\'Hermon le nom de Sirion et les Amoréens celui de Sénir),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'toutes les villes de la plaine, et tout Galaad et tout Basan jusqu\'à Salcha et Edrei, villes du royaume de Og en Basan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, '(Og, Roi de Basan, était le seul survivant du reste des géants; voici, son lit, lit de fer, n\'est-il pas à Rabba dans le pays des fils d\'Ammon, ayant neuf coudées de longueur et quatre coudées de largeur, coudée d\'homme?)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Et dans ce temps-là nous conquîmes ce pays depuis Aroër sur l\'Arnon. Et la moitié de la montagne de Galaad avec ses villes, je la donnai aux Rubénites et. aux Gadites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'et le reste de Galaad et tout Basan, royaume de Og, je le donnai à la demi-Tribu de Manassé, tout le canton d\'Argob, Basan tout entier; c\'est ce qui s\'appelle le pays des géants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jaïr, fils de Manassé, conquit tout le canton d\'Argob jusqu\'aux frontières des Gesurites et des Maachathites, et il y donna, à Basan, d\'après son nom, le nom de bourgs de Jaïr, jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Et à Machir je donnai Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Et aux Rubénites et aux Gadites, je donnai une partie de Galaad et jusqu\'au torrent de l\'Arnon, ce qui est en dedans du torrent et le territoire adjacent, jusqu\'au Jabbok, torrent frontière des fils d\'Ammon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'et la plaine et le Jourdain et le territoire adjacent depuis Kinnéreth jusqu\'à la mer de la plaine, la Mer-Salée, au pied du Pisga, à l\'Orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'En ce temps-là je vous donnai ce commandement: L\'Éternel, votre Dieu, vous a livré ce pays pour le conquérir. Il faut que vous, tout ce que vous avez de guerriers, vous marchiez armés en tête de vos frères, les fils d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Vos femmes, vos enfants et vos troupeaux seuls (je sais que vous avez de nombreux troupeaux) resteront dans vos villes que je vous ai données,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'jusqu\'à ce que l\'Éternel ait accordé à vos frères le repos comme à vous, et qu\'eux aussi aient conquis le pays que l\'Éternel, votre Dieu, leur donne au delà du Jourdain; alors vous pourrez chacun de vous revenir dans votre conquête que je vous ai donnée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Et dans ce temps je donnai mes instructions à Josué en ces termes: Tes yeux ont vu tout ce que l\'Éternel, votre Dieu, a fait à ces deux Rois: ainsi fera l\'Éternel à tous les royaumes que tu vas envahir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Ne les redoutez pas, car l\'Éternel, votre Dieu, lui-même combattra pour vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Et dans ce même temps je fis à l\'Éternel cette supplication:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Seigneur, Éternel, tu as commencé à montrer à ton serviteur ta majesté et ta main puissante; car où est dans les Cieux et sur la terre un Dieu qui fasse rien de pareil à tes œuvres et à tes exploits?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Oh! permets aussi que je passe et que je voie ce beau pays de l\'autre côté du Jourdain, ces belles montagnes et le Liban!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Mais l\'Éternel se courrouça contre moi à cause de vous, et Il ne m\'exauça pas, et l\'Éternel me dit: C\'est assez! ne me parle plus de cette affaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Monte au sommet du Pisga, puis porte tes regards à l\'occident et au septentrion et au midi et à l\'orient, et contemple de tes yeux; car tu ne passeras pas ce Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Et laisse tes instructions à Josué, affermis et fortifie-le; car c\'est lui qui marchera à la tête de ce peuple, et qui leur partagera le pays que tu verras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Nous demeurâmes donc dans la vallée vis-à-vis de Beth-Pehor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Et maintenant, Israël, écoute les statuts et les lois que je vous inculque pour les observer, afin que vous viviez et parveniez à conquérir le pays que vous donne l\'Éternel, Dieu de vos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Ne faites aux commandements que je vous donne, aucune addition, ni aucun retranchement, gardant les commandements de l\'Éternel, votre Dieu, que je vous prescris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Vos yeux ont vu ce que l\'Éternel a fait à l\'occasion de Bahal-Pehor; car tous les hommes qui se firent les sectateurs de Bahal-Pehor, l\'Éternel, ton Dieu, les extermina du milieu de toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'tandis que vous qui êtes restés attachés à l\'Éternel, votre Dieu, vous êtes tous en vie aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Voici, je vous ai enseigné des statuts et des lois, comme l\'Éternel, mon Dieu, m\'a ordonné, pour que vous vous y conformiez dans le pays dont vous venez faire la conquête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Gardez-les donc et pratiquez-les, car ce sera votre sagesse et votre intelligence aux yeux des peuples, qui entendront parler de tous ces statuts et diront: Il n\'y a de peuple sage et intelligent que cette grande nation-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Car quelle est la grande nation dont la Divinité soit aussi près, que l\'Éternel, notre Dieu, l\'est de nous, toutes les fois que nous l\'invoquons?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Et quelle est la grande nation qui ait des statuts et des lois justes comme toute cette Loi que je vous propose en ce jour?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Seulement prends garde à toi et veille bien sur toi-même pour ne pas oublier les choses que tes yeux ont vues, afin qu\'elles ne sortent pas de ton cœur pendant toute la durée de ta vie; mais que tu les fasses connaître à tes fils et aux fils de tes fils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'cette journée [surtout] où tu parus devant l\'Éternel, ton Dieu, en Horeb, lorsque l\'Éternel me dit: Assemble-moi ce peuple, afin que je leur fasse entendre mes Paroles qu\'ils apprendront pour me craindre pendant toute la durée de leur vie sur la terre, et qu\'ils enseigneront à leurs enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Alors vous vous êtes approchés et tenus debout au pied de la montagne, et la montagne était embrasée d\'un feu qui s\'élevait jusqu\'au sein des Cieux, entre les ténèbres, les nuages et l\'obscurité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Et du centre du feu l\'Éternel vous parla; vous entendiez le son des paroles, mais vous ne vîtes aucune figure: il n\'y avait qu\'une voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Et Il vous promulgua son alliance qu\'il vous ordonnait d\'observer, les Dix Paroles, et Il les écrivit sur deux tables de pierre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Et dans ce même temps l\'Éternel m\'ordonna de vous enseigner des statuts et des lois, pour que vous les pratiquiez dans le pays où vous allez passer pour en faire la conquête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Ainsi, veillez bien sur vous-mêmes, puisque vous ne vîtes aucune figure le jour où l\'Éternel vous parla en Horeb du milieu du feu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'afin de ne pas vous pervertir et de ne pas vous faire d\'idole, image d\'une figure quelconque, point d\'effigie d\'un mâle ou d\'une femelle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'd\'effigie d\'aucun animal terrestre, d\'effigie d\'aucun oiseau ailé qui vole dans le ciel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'd\'effigie de rien qui rampe sur le sol, d\'effigie d\'aucun poisson habitant des eaux au-dessous de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'et afin de ne pas élever tes yeux vers le ciel pour te laisser entraîner par l\'aspect du soleil, de la lune et des astres et de toute l\'armée des Cieux à les adorer et à les servir, eux, que l\'Éternel, ton Dieu, a donnés en partage à tous les peuples sous le ciel entier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Car l\'Éternel vous a pris et vous a retirés de la fournaise de fer, de l\'Egypte, pour que vous fussiez son peuple particulier, comme [vous l\'êtes] dans ce jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Et l\'Éternel se courrouça contre moi à cause de vous et jura que je ne passerai point le Jourdain et n\'entrerai point dans le beau pays que l\'Éternel, ton Dieu, te donne en propriété;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'car je dois mourir dans ce pays-ci et ne passerai point le Jourdain; mais vous, vous le passerez, et vous ferez la conquête de cet excellent pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Veillez sur vous afin de ne pas oublier l\'alliance de l\'Éternel, votre Dieu, qu\'il a conclue avec vous, et de ne vous faire aucune idole, aucune effigie de rien de ce que l\'Éternel, ton Dieu, t\'a interdit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Car l\'Éternel, ton Dieu, est un feu dévorant, un Dieu jaloux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Lorsque vous aurez eu des enfants et des petits-enfants et que vous serez établis dans le pays, si vous vous corrompez, si vous vous fabriquez quelque image ou une effigie quelconque, et faites ainsi ce qui est mal aux yeux de l\'Éternel, ton Dieu, pour le provoquer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'je prends aujourd\'hui à témoin contre vous les Cieux et la terre que vous serez bientôt exterminés du pays dont, après le passage du Jourdain, vous ferez la conquête; vous n\'y passerez pas de longs jours, mais vous serez détruits, exterminés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Et l\'Éternel vous disséminera parmi les peuples et vous survivrez en petit nombre au milieu des nations où l\'Éternel vous emmènera;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'et là, vous servirez des dieux, ouvrage des mains de l\'homme, le bois et la pierre, qui ne voient, ni n\'entendent, ni ne mangent, ni n\'odorent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Mais de là tu chercheras l\'Éternel, ton Dieu, et tu le trouveras si tu le cherches de tout ton cœur et de toute ton âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Dans ta détresse et lorsque toutes ces choses t\'atteindront dans la suite des temps, tu reviendras à l\'Éternel, ton Dieu, et tu écouteras sa voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Car c\'est un Dieu miséricordieux, que l\'Éternel, ton Dieu; Il ne te laissera pas, ne te perdra pas, et n\'oubliera pas l\'alliance de tes pères, qu\'il leur a jurée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Hé! demande en effet aux temps primitifs qui t\'ont précédé, depuis le jour où Dieu créa des hommes sur la terre, et d\'une extrémité du ciel à l\'autre, si jamais advint si grande chose, ou s\'il en a été entendu une pareille,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'si jamais peuple ouït la voix d\'un Dieu parlant du milieu du feu, comme tu l\'as ouïe, et en demeurant en vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'ou si jamais un Dieu tenta de venir se choisir une nation au sein d\'une autre, par des épreuves, des signes et des prodiges, et la guerre, et d\'une main forte et d\'un bras étendu, et par des exploits grands et terribles, comme tout ce qu\'a fait pour vous l\'Éternel, votre Dieu, en Egypte devant vos yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Tu en as été rendu spectateur pour reconnaître que l\'Éternel est Dieu et que hors lui il n\'en est point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Des Cieux Il t\'a fait entendre sa voix pour t\'instruire, et sur la terre Il t\'a fait voir son feu majestueux, et c\'est du feu que tu entendis sortir ses paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Et parce qu\'il aima tes pères et qu\'il fit choix de leur race après eux, en personne et par sa grande vertu Il te fit sortir de l\'Egypte');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'pour chasser devant toi des nations grandes et fortes plus que toi, pour t\'amener, pour te donner leur pays en propriété, comme [il arrive] aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Reconnais donc maintenant et mets-le dans ton cœur, que l\'Éternel est Dieu, en haut dans les Cieux, et en bas sur la terre, qu\'il n\'en est pas d\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Et garde ses statuts et ses commandements que je te prescris en ce jour, afin que tu sois heureux toi et tes fils après toi, et que tu passes de longs jours dans le pays que l\'Éternel, ton Dieu, te donne pour toujours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Alors Moïse sépara trois villes au delà du Jourdain vers le soleil levant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'dans lesquelles pût se réfugier l\'homicide qui aurait tué son prochain sans intention, et sans avoir été son ennemi ni d\'hier ni d\'avant-hier, afin qu\'il pût se réfugier dans l\'une de ces villes, et conserver la vie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Betser, dans le désert, dans la contrée de la plaine pour les Rubénites, et Ramoth en Galaad pour les Gadites, et Golan en Basan pour les Manassites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Et voici la Loi que Moïse présenta aux enfants d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'voici les ordonnances, les statuts et les lois que Moïse adressa aux enfants d\'Israël à leur sortie de l\'Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'au delà du Jourdain, dans la vallée, vis-à-vis de Beth-Pehor, dans le pays de Sihon, Roi des Amoréens qui résidait à Hesbon, que battirent Moïse et les enfants d\'Israël à leur sortie de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'Et ils conquirent son pays et le pays de Og, Roi de Basan, des deux rois des Amoréens au delà du Jourdain, au soleil levant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'depuis Aroër située sur la rive du torrent de l\'Arnon, jusqu\'au mont Sijon qui est l\'Hermon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'et toute la plaine au delà du Jourdain à l\'orient et jusqu\'à la mer de la plaine au pied du Pisga.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Et Moïse convoqua tous les Israélites et leur dit: Écoute, Israël, les statuts et les lois que je vais redire à vos oreilles en ce jour, et apprenez-les et veillez à les pratiquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'L\'Éternel, notre Dieu, conclut avec nous une alliance en Horeb.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Ce n\'est pas avec nos pères que l\'Éternel conclut cette alliance, mais avec nous, nous ici présents et tous vivant aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'L\'Éternel vous parla face à face sur la montagne du milieu du feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'J\'étais alors intermédiaire entre l\'Éternel et vous, pour vous transmettre la parole de l\'Éternel, car vous eûtes peur à l\'aspect du feu et vous ne montâtes point sur la montagne. Et Il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Je suis l\'Éternel, ton Dieu, qui t\'ai retiré du pays d\'Egypte, de la maison de servitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Tu n\'auras point d\'autres dieux en face de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Tu ne te feras point de sculpture, aucune effigie de ce qui est en haut dans le ciel et en bas sur la terre et dans les eaux au-dessous de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Tu ne les adoreras point et ne te laisseras point aller à les servir, car je suis l\'Éternel, ton Dieu, un Dieu jaloux qui châtie l\'iniquité des pères sur les fils et sur la troisième et sur la quatrième génération de ceux qui me haïssent');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'et qui fais grâce à la millième génération de ceux qui m\'aiment et gardent mes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Tu ne proféreras pas le nom de l\'Éternel, ton Dieu, légèrement, car l\'Éternel ne laissera point impuni celui qui proférera son nom légèrement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Observe le jour du repos pour le sanctifier, comme l\'Éternel, ton Dieu, te l\'a commandé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Six jours tu travailleras et feras tout ton travail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Mais le septième jour est le sabbat de l\'Éternel, ton Dieu: tu ne feras aucun travail, ni toi, ni ton fils, ni ta fille, ni ton serviteur, ni la servante, ni ton bœuf, ni ton âne, ni aucun de tes bestiaux, ni ton étranger qui est dans tes Portes, afin que ton serviteur et ta servante se reposent, ainsi que toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'te souvenant que tu fus esclave au pays d\'Egypte et que l\'Éternel, ton Dieu, t\'a retiré de là d\'une main forte et d\'un bras étendu; c\'est pourquoi l\'Éternel, ton Dieu, t\'a commandé d\'observer le jour du repos.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Honore ton père et ta mère, comme te l\'a commandé l\'Éternel, ton Dieu, afin que tes jours se prolongent et que tu sois heureux dans le pays que l\'Éternel, ton Dieu, te donne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Tu ne seras point meurtrier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Tu ne seras point adultère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Tu ne seras point larron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Tu ne seras point faux témoin contre ton prochain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Et tu ne convoiteras point la femme de ton prochain, et tu ne convoiteras point la maison de ton prochain, ni son champ, ni son serviteur, ni sa servante, ni son bœuf, ni son âne, ni rien de ce qui est à ton prochain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Telles sont les Paroles que l\'Éternel a dites à toute votre Assemblée sur la montagne, du milieu du feu, de la nuée, de l\'obscurité, à haute voix; et Il ne l\'a plus fait; et Il les écrivit sur deux Tables de pierre qu\'il me donna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Et comme vous entendîtes cette voix sortant de l\'obscurité, et comme un feu embrasait la montagne, vous vous approchâtes de moi, tous vos Chefs de Tribus et vos Anciens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'et vous dîtes: Voilà que l\'Éternel, notre Dieu, nous a fait voir sa gloire et sa majesté, et nous avons entendu sa voix sortir du feu; en ce jour nous avons vu que Dieu parle à l\'homme, et que celui-ci peut vivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Or maintenant pourquoi mourrions-nous? car ce grand feu nous consumera; si nous continuons à ouïr encore la voix de l\'Éternel, notre Dieu, nous mourrons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Car en toute chair qui pourrait entendre comme nous la voix du Dieu vivant parlant du milieu du feu et vivre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Va, toi, plus près, et écoute tout ce que dira l\'Éternel, notre Dieu, et toi, tu nous rediras tout ce que t\'aura dit l\'Éternel, notre Dieu, et nous voulons l\'écouter et le faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Et l\'Éternel entendit vos discours, quand vous me parliez. Et l\'Éternel me dit: J\'ai entendu les paroles que ce peuple t\'a adressées; tout ce qu\'ils ont dit, est bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Puisse leur cœur rester tel pour me craindre et garder tous mes commandements dans tous les temps, afin qu\'ils soient heureux, eux et leurs enfants éternellement!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Va et dis-leur: Retournez-vous-en dans vos tentes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Mais, toi, reste ici avec moi et je te dirai la totalité des commandements, des statuts et des lois que tu leur enseigneras, afin qu\'ils les pratiquent dans le pays que je vais leur donner en propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Veillez donc à vous conformer aux ordres de l\'Éternel, votre Dieu, ne déviez ni à droite ni à gauche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'suivez entièrement la voie que vous a prescrite l\'Éternel, votre Dieu, afin que vous viviez, et soyez heureux, et ayez de longs jours dans le pays dont vous ferez la conquête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Et voici les commandements, les statuts et les lois que l\'Éternel, votre Dieu, a ordonné de vous enseigner pour que vous les pratiquiez dans le pays où vous allez passer pour le conquérir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'et afin que tu craignes l\'Éternel, ton Dieu, observant tous ses statuts et ses commandements que je te prescris, toi et ton fils et le fils de ton fils, tous les jours de ta vie, afin que tu aies de longs jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Écoute donc, Israël, et veille à les pratiquer, afin que tu sois heureux et que vous preniez un grand accroissement, puisque l\'Éternel, Dieu de tes pères, t\'a promis un pays découlant de lait et de miel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Écoute, Israël! l\'Éternel est notre Dieu, l\'Éternel seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Aime donc l\'Éternel, ton Dieu, de tout ton cœur, de toute ton âme et de toute ta puissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Et aie à cœur toutes ces choses que je te prescris en ce jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Et inculque-les à tes fils, et parles-en, et assis dans ta maison, et cheminant en voyage, et en te couchant et en te levant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Attache-les comme un signe à ta main et porte-les comme bandelettes entre tes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Inscris-les sur les piliers de ta maison, et à tes portes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Et lorsque l\'Éternel, ton Dieu, t\'aura introduit dans le pays qu\'il a juré à tes pères, à Abraham, à Isaac et à Jacob de te donner, dans de grandes et belles villes que tu n\'as point bâties,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'dans des maisons pleines de tous les biens, que tu n\'as point remplies, auprès de fontaines creusées que tu n\'as point creusées, dans des vignes et des olivaies que tu n\'as point plantées, et lorsque tu mangeras et te rassasieras,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'prends garde à toi, de peur d\'oublier l\'Éternel qui t\'a retiré du pays d\'Egypte, de la maison de servitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Crains l\'Éternel, ton Dieu, et le sers, et jure par son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Ne suivez pas d\'autres dieux parmi les dieux des peuples de vos alentours;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'car c\'est un Dieu jaloux au milieu de vous, que l\'Éternel, notre Dieu; de peur que la colère de l\'Éternel, ton Dieu, ne s\'allume contre toi et qu\'il ne vous fasse disparaître de la surface de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Ne tentez pas l\'Éternel, votre Dieu, comme vous l\'avez tenté à Massa;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'gardez, gardez les commandements de l\'Éternel, votre Dieu, et ses ordonnances et ses statuts qu\'il t\'a prescrits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Et fais ce qui est droit et bien aux yeux de l\'Éternel, afin que tu sois heureux et que tu parviennes à faire la conquête du beau pays que l\'Éternel promit par serment à tes pères');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'et qu\'il chasse tous tes ennemis devant toi, comme l\'a dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Lorsque dans l\'avenir ton fils t\'interrogera en disant: Qu\'est-ce que ces ordonnances, ces statuts et ces lois que vous a prescrites l\'Éternel, notre Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'dis à ton fils: Nous étions esclaves de Pharaon en Egypte et l\'Éternel nous a retirés de l\'Egypte d\'une main forte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'et l\'Éternel a opéré des signes et des prodiges grands et funestes pour l\'Egypte, pour Pharaon et pour toute sa maison, sous nos yeux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'et nous, Il nous a retirés de là pour nous amener ici, et nous donner le pays qu\'il avait promis par serment à nos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Et l\'Éternel nous a commandé de pratiquer tous ces statuts, de craindre l\'Éternel, notre Dieu, pour être heureux tout le temps de notre vie, ainsi qu\'[il arrive] aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Et ce sera pour nous une justice que de veiller à accomplir tous ces commandements, devant l\'Éternel, notre Dieu, ainsi qu\'il nous l\'a prescrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Lorsque l\'Éternel, ton Dieu, t\'aura introduit dans le pays vers lequel tu t\'avances pour en faire la conquête et qu\'il chassera devant toi des nations nombreuses, les Héthiens et les Gergésites, et les Amoréens et les Cananéens et les Perizzites et les Hévites, et les Jébusites, sept nations plus nombreuses et plus fortes que toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'et que l\'Éternel, ton Dieu, te les livrera, et que tu les auras vaincues, tu les dévoueras, et tu ne leur accorderas ni capitulation, ni merci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Et tu ne contracteras point d\'alliance avec eux, tu ne donneras pas tes filles à leurs fils, et tu ne prendras pas leurs filles pour tes fils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'car ils détacheraient de moi tes fils qui se mettraient à servir d\'autres dieux; et alors la colère de l\'Éternel s\'allumerait contre vous et vous détruirait bien vite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Voici, au contraire, comment vous les traiterez: vous démolirez leurs autels, briserez leurs colonnes, abattrez leurs Aschères, et brûlerez au feu leurs idoles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Car tu es un peuple consacré à l\'Éternel, ton Dieu; l\'Éternel, ton Dieu, t\'a choisi pour être son peuple particulier, entre tous les peuples qui sont sur la surface de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'ce n\'est pas parce que vous êtes supérieurs en nombre à tous les peuples, que l\'Éternel s\'est attaché à vous, et a fait choix de vous, car vous êtes le moins grand de tous les peuples;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'mais c\'est parce que l\'Éternel vous aime et qu\'il garde le serment juré à vos pères, que l\'Éternel vous a retirés avec une main forte et délivrés de la maison de servitude et de la main de Pharaon, Roi d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Reconnais donc que l\'Éternel, ton Dieu, est le Dieu, le Dieu fidèle qui garde son alliance et sa dilection à ceux qui l\'aiment et gardent ses commandements, jusqu\'à la millième génération,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'mais qui use de représailles directes envers ceux qui le haïssent, en les faisant périr; Il n\'use pas de délais envers ceux qui le haïssent; ses représailles sont directes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Ainsi, garde les commandements et les statuts et les lois que je te prescris en ce jour, pour les pratiquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Et en retour de votre docilité à ces lois, et de votre application à les pratiquer, l\'Éternel, ton Dieu, te gardera aussi l\'alliance et la dilection qu\'il promit par serment à tes pères;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'et Il t\'aimera, te bénira, te multipliera et bénira le fruit de tes flancs et le fruit de ton sol, ton blé et ton moût et ton huile et la progéniture de tes vaches et les portées de tes brebis, dans le pays qu\'il jura à tes pères de te donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Tu seras béni plus que tous les peuples; chez toi et dans tes troupeaux il n\'y aura ni mâle impuissant, ni femelle stérile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Et l\'Éternel éloignera de toi toute maladie, et Il ne t\'infligera aucune de ces malignes consomptions de l\'Egypte, que tu connais, et Il les fera subir à tous ceux qui te haïssent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Et tu dévoreras tous les peuples que l\'Éternel, ton Dieu, va te livrer: ne les regarde pas avec pitié, et ne sers pas leurs dieux, car ce serait un piège pour toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Si tu dis dans ton cœur: Ces nations sont plus nombreuses que moi, comment pourrai-je les chasser?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'ne les redoute pas; rappelle le souvenir de ce que l\'Éternel, ton Dieu, a fait à Pharaon et à toute l\'Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'les grandes épreuves que tes yeux ont vues, les signes et les prodiges; et la main forte et le bras étendu, avec lesquels l\'Éternel, ton Dieu, opéra ta sortie: ainsi fera l\'Éternel, ton Dieu, à tous les peuples que tu redoutes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Et l\'Éternel, ton Dieu, enverra aussi contre eux les frelons, jusqu\'à l\'extermination des survivants et de ceux qui se cachent devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Sois sans peur devant eux, car l\'Éternel, ton Dieu, Dieu grand et redoutable, est au milieu de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Et l\'Éternel, ton Dieu, chassera ces nations de devant toi peu à peu; tu ne pourras les anéantir rapidement, afin que les bêtes des champs multipliées ne t\'assaillent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Et l\'Éternel, ton Dieu, te les livrera, et Il les troublera par une grande épouvante jusqu\'à ce qu\'elles soient exterminées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Et Il livrera leurs rois entre tes mains, et tu feras disparaître leurs noms de dessous les cieux; nul ne te tiendra tête, jusqu\'à ce que tu les aies anéantis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Vous brûlerez au feu les images de leurs dieux; ne convoite pas l\'or et l\'argent qui les recouvre, ni n\'en fais ta proie, de peur que tu ne sois pris à leur piège, car ils sont l\'abomination de l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Et n\'introduis point l\'abomination dans ta maison, afin que tu ne tombes pas sous l\'interdit comme eux; tu dois en avoir horreur comme abomination; car c\'est chose dévouée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Gardez, pour les pratiquer, tous les commandements que je vous prescris en ce jour, afin que vous viviez et vous multipliiez, et parveniez à conquérir le pays que l\'Éternel a promis par serment à vos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Et souviens-toi de tout le trajet dans lequel l\'Éternel, ton Dieu, t\'a engagé durant ces quarante années dans le désert, pour t\'humilier, pour t\'éprouver, pour connaître ce qu\'il y a dans ton cœur, et savoir si tu observeras ou non ses commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Il t\'a donc humilié, fait sentir la faim, et Il t\'a nourri de la manne que tu ne connaissais pas et que ne connurent pas tes pères, afin de te montrer que ce n\'est pas du pain seul que l\'homme vit, mais que, de tout ce qui procède de la bouche de l\'Éternel, l\'homme peut vivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Tes habits ne se sont point usés sur toi, et tes pieds n\'ont point enflé durant ces quarante ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Tu dois reconnaître en ton cœur que, comme un père élève son fils, ainsi l\'Éternel, ton Dieu, t\'élève:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'garde donc les commandements de l\'Éternel, ton Dieu, pour marcher dans ses voies et pour le craindre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Car l\'Éternel, ton Dieu, t\'amène dans un beau pays, pays de cours d\'eaux, de sources et de lacs, qui jaillissent dans les vallées et dans les montagnes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'pays de froment, d\'orge, de vigne et de figuiers et de grenadiers, pays d\'oliviers donnant l\'huile, et de miel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'pays où tu n\'auras pas une nourriture mesquine, où tu ne manqueras de rien, pays dont les pierres sont du fer, et des montagnes duquel tu extrairas l\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Et quand tu auras mangé à rassasiement, tu béniras l\'Éternel, ton Dieu, pour le beau pays qu\'il t\'a donné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Sois sur tes gardes pour ne pas oublier l\'Éternel, ton Dieu, et ne pas négliger ses commandements, ses lois et ses statuts que je te prescris en ce jour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'de peur que, mangeant à rassasiement, bâtissant de belles maisons et y habitant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'et possédant du gros et du menu bétail qui se multiplie, de l\'or et de l\'argent qui s\'augmente aussi bien que tout ton avoir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'ton cœur ne s\'élève et que tu n\'oublies l\'Éternel, ton Dieu, qui t\'a retiré du pays d\'Egypte, de la maison de servitude,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'qui t\'a guidé au travers du désert vaste et terrible, des serpents venimeux, des scorpions, des lieux arides et sans eau, qui a fait sourdre pour toi l\'eau du caillou du rocher,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'qui dans le désert t\'a nourri de la manne inconnue de tes pères, pour t\'humilier et pour t\'éprouver, et pour te faire du bien dans la suite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'et que tu ne dises pas en ton cœur: Mes forces et la vigueur de mes mains m\'ont acquis toute cette richesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Souviens-toi de l\'Éternel, ton Dieu, car c\'est lui qui te donne la force de faire des actes de bravoure, dans le but de mettre à effet son alliance qu\'il jura à tes pères, comme [il arrive] aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Et si tu oublies l\'Éternel, ton Dieu, et que tu suives d\'autres dieux pour les servir et les adorer, je proteste aujourd\'hui contre vous que vous périrez;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'de même que les nations que l\'Éternel va détruire devant vous, ainsi vous périrez pour n\'avoir pas été dociles à la voix de l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Écoute, Israël, tu vas aujourd\'hui passer le Jourdain pour marcher à la conquête de nations grandes et fortes plus que toi, de villes grandes et fortifiées jusques au ciel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'du peuple des Anakites, grand et de haute taille que tu connais et duquel tu as ouï dire: Qui tiendrait tête aux Anakites?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Or, sache maintenant que c\'est l\'Éternel, ton Dieu, qui marchera à votre tête, en feu dévorant; c\'est lui qui les détruira, lui qui les fera plier devant toi, et tu les chasseras et les extermineras bien vite, comme l\'Éternel te l\'a promis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Ne dis pas en ton cœur, lorsque l\'Éternel, ton Dieu, les dissipera devant toi: C\'est à raison de ma justice que l\'Éternel m\'a fait parvenir à la conquête de ce pays; quand c\'est à raison de l\'impiété de ces nations-là que l\'Éternel les chasse devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Ce n\'est pas à raison de ta justice et de la droiture de ton cœur que tu viens conquérir leur pays, mais c\'est à raison de l\'impiété de ces nations-là que l\'Éternel, ton Dieu, les chasse devant toi, et afin de mettre à effet la promesse que l\'Éternel fit par serment à tes pères, à Abraham, à lsaac et à Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Reconnais donc que ce n\'est pas pour ta justice que l\'Éternel, ton Dieu, te donne ce beau pays pour en faire la conquête; car tu es un peuple au col roide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Rappelle-toi, n\'oublie pas comment tu as provoqué la colère de l\'Éternel, ton Dieu, dans le désert; depuis le jour que tu es sorti du pays d\'Egypte jusqu\'à votre arrivée en ce lieu-ci, vous avez été en rébellion contre l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Et en Horeb vous avez irrité l\'Éternel, et Il s\'est courroucé contre vous au point de penser à vous détruire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'lorsque je montai à la montagne pour recevoir les Tables de pierre, Tables de l\'alliance que l\'Éternel concluait avec vous. Et je demeurai sur la montagne quarante jours et quarante nuits sans manger de pain et sans boire d\'eau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'et l\'Éternel me donna les deux Tables de pierre écrites du doigt de Dieu et portant le texte de toutes les paroles que l\'Éternel vous avait dites sur la montagne, du milieu du feu le jour de l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Et au bout des quarante jours et des quarante nuits, l\'Éternel me donna les deux Tables de pierre, Tables de l\'alliance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'et l\'Éternel me dit: Lève-toi, hâte-toi de descendre d\'ici, car ton peuple, que tu as retiré de l\'Egypte, forfait; ils ont bientôt quitté la voie que je leur avais prescrite: ils se sont fabriqué une idole de fonte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Puis l\'Éternel me parla en ces termes: Je considère ce peuple-là; et, voici, c\'est un peuple au col roide;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'ne m\'arrête pas! je veux les anéantir et effacer leur nom de dessous les Cieux, et faire de toi un peuple plus fort et plus grand que lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Me retournant donc je descendis de la montagne, les deux Tables de l\'alliance dans mes deux mains, et le feu embrasait la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Et je vis! et voilà que vous aviez péché contre l\'Éternel, votre Dieu, vous vous étiez fait un veau de fonte; vous aviez bientôt quitté la voie que vous avait prescrite l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Alors saisissant les deux Tables je les jetai hors de mes deux mains et les brisai sous vos yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Ensuite je m\'abattis devant l\'Éternel, comme auparavant, quarante jours et quarante nuits, sans manger de pain ni boire d\'eau, à cause de tous vos péchés que vous aviez commis en faisant ce qui est mal aux yeux de l\'Éternel, pour l\'irriter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Car j\'appréhendais, vu la colère et le courroux dont l\'Éternel était animé contre vous au point de vouloir vous anéantir, mais l\'Éternel m\'exauça encore cette fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Et l\'Éternel était aussi tellement irrité contre Aaron qu\'il voulait le détruire, et j\'intercédai alors aussi pour Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Et l\'objet de votre péché, le veau que vous aviez fait, je le pris et je le brûlai au feu; et l\'ayant concassé et bien trituré jusqu\'à le réduire en poudre menue, j\'en jetai la poudre dans la rivière qui descend de la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Et à Thabeèra et à Massa et aux tombeaux de la convoitise vous excitâtes la colère de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'et aussi lorsque l\'Éternel vous envoyait de Cadès-Barnéa en disant: Montez et faites la conquête du pays que je vous ai donné; vous fûtes rebelles à l\'ordre de l\'Éternel, votre Dieu, et vous n\'eûtes pas foi en lui, et n\'obéîtes point à sa voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Vous avez été en rébellion contre l\'Éternel, depuis que je vous connais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Je fus donc abattu devant l\'Éternel pendant les quarante jours et les quarante nuits où je m\'étais abattu, parce que l\'Éternel avait parlé de vous détruire');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'et je suppliai l\'Éternel en disant: Seigneur, Éternel, ne perds pas ton peuple et ton héritage que tu as racheté, dans ta grande puissance, que tu as retiré de l\'Egypte d\'une main forte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Souviens-toi de tes serviteurs, d\'Abraham, d\'Isaac et de Jacob, ne regarde pas à la roideur de ce peuple, ni à son impiété ni à son péché,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'de peur que le pays d\'où tu nous as retirés, ne dise: C\'est par impuissance de l\'Éternel à les introduire dans le pays qu\'il leur avait promis, et parce qu\'il les haïssait, qu\'il les en a tirés pour les faire mourir dans le désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Hé! ils sont ton peuple et ton héritage que tu as délivré par ta grande force et de ton bras étendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'Dans ce même temps l\'Éternel me dit: Taille-toi deux Tables de pierre, comme les premières, et monte vers moi sur la montagne et fais-toi une Arche de bois,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'et j\'écrirai sur les Tables les Paroles qui se trouvaient sur les premières Tables que tu as brisées, et tu les placeras dans l\'Arche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Je fis donc une Arche de bois d\'acacia et taillai deux Tables de pierre pareilles aux premières, et je montai à la montagne ayant les deux Tables dans ma main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Alors Il écrivit sur les Tables les mêmes choses qui avaient été écrites sur les premières, les Dix Paroles que l\'Éternel vous avait adressées sur la montagne du milieu du feu le jour de l\'Assemblée; et l\'Éternel me les donna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Et me retournant je descendis de la montagne et je mis les Tables dans l\'Arche que j\'avais faite, et elles y furent, comme l\'Éternel me l\'avait commandé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Et les enfants d\'Israël partirent de Beeroth Benei-Jaakan pour Moser. Là mourut Aaron, et il y reçut la sépulture, et Eléazar, son fils, lui succéda dans le sacerdoce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'De là ils se portèrent à Gudgoda, et de Gudgoda à Jotbath, pays de cours d\'eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'C\'est dans ce temps-là que l\'Éternel mit à part la Tribu de Lévi, pour porter l\'Arche de l\'Alliance de l\'Éternel, et se tenir devant l\'Éternel pour le servir, et pour bénir en son nom, jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'C\'est pourquoi Lévi n\'eut point de portion ni de lot avec ses frères: l\'Éternel est son lot, ainsi que l\'Éternel, ton Dieu, le lui a dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Or moi je restai sur la montagne, comme dans le séjour précédent, quarante jours et quarante nuits; et l\'Éternel m\'exauça aussi cette fois: l\'Éternel ne voulut plus vous perdre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Et l\'Éternel me dit: Lève-toi, et dans le décampement marche à la tête du peuple, afin qu\'ils arrivent et fassent la conquête du pays que j\'ai juré à leurs pères de leur donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Et maintenant, Israël, qu\'est-ce que l\'Éternel, ton Dieu, exige de toi, sinon de craindre l\'Éternel, ton Dieu, de marcher dans toutes ses voies, et de l\'aimer, et de servir l\'Éternel, ton Dieu, de tout ton cœur et de toute ton âme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'de garder les commandements de l\'Éternel et ses statuts que je te prescris aujourd\'hui pour ton bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Voici, à l\'Éternel, ton Dieu, appartiennent les Cieux et les Cieux des Cieux, la terre et tout ce qu\'elle renferme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'cependant c\'est à tes pères seuls que l\'Éternel s\'est attaché pour les aimer, et Il a choisi leur race qui viendrait après eux, vous, entre tous les peuples, comme [il arrive] aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'En conséquence circoncisez le prépuce de vos cœurs et n\'ayez plus le col roide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Car l\'Éternel, votre Dieu, est le Dieu des Dieux, et le Seigneur des Seigneurs, le Dieu grand, puissant et redoutable qui ne fait point acception des personnes, et n\'accepte point de présents,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'qui fait droit à l\'orphelin et à la veuve et aime l\'étranger et lui donne nourriture et vêtement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Aimez donc les étrangers, car vous fûtes étrangers dans le pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Crains l\'Éternel, ton Dieu, sers-le, reste lui attaché et jure par son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Il est ta gloire, et Il est ton Dieu qui a opéré pour toi ces choses grandes et terribles que tes yeux ont vues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'C\'est avec soixante-dix âmes que tes pères descendirent en Egypte, et maintenant l\'Éternel, ton Dieu, t\'a rendu égal en nombre aux étoiles des Cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Aime donc l\'Éternel, ton Dieu, et observe ce qu\'il veut qu\'on observe, et ses statuts et ses lois et ses commandements, dans tous les temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Reconnaissez maintenant (car ce n\'est pas à vos fils que je parle, ils sont dans l\'ignorance et n\'ont pas été témoins des leçons de l\'Éternel, votre Dieu), sa grandeur, et sa main forte, et son bras étendu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'et ses signes et ses actes qu\'il accomplit au sein de l\'Egypte, sur Pharaon, roi d\'Egypte, et sur tout son pays,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'et ce qu\'il a fait à l\'armée d\'Egypte, à ses chevaux et à ses chars qu\'il submergea par les eaux de la Mer aux algues, lorsqu\'ils vous poursuivaient, et qu\'il a anéantis jusqu\'à ce jour;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'et ce qu\'il vous a fait dans le désert jusqu\'à votre arrivée en ce lieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'et ce qu\'il a fait à Dathan et à Abiram, fils d\'Eliab, fils de Ruben, lorsque la terre s\'entr\'ouvrit et les engloutit avec leurs maisons et leurs tentes et tout leur train qui les suivait, au milieu de tout Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Car vos yeux ont vu tous les grands faits accomplis par l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Et gardez tous les commandements que je vous prescris en ce jour, pour vous affermir afin que vous parveniez à conquérir le pays où vous allez entrer pour en faire la conquête,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'et afin que vous ayez de longs jours sur le sol que l\'Éternel a juré à vos pères de leur donner, à eux et à leur race, pays découlant de lait et de miel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Car le pays où tu arrives pour en faire la conquête, n\'est point comme le pays d\'Egypte d\'où vous êtes sortis, et où tu semais tes semences, et où tu devais arroser à l\'aide de ton pied, comme un jardin de légumes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Le pays où vous allez entrer pour le conquérir, est un pays de montagnes et de vallées; il boit l\'eau de la pluie du ciel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'c\'est un pays que hante l\'Éternel, ton Dieu; toujours les yeux de l\'Éternel, ton Dieu, sont fixés sur lui du commencement de l\'année jusqu\'à sa fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Et si vous obéissez à mes commandements que je vous prescris en ce jour, en aimant l\'Éternel, votre Dieu, et en le servant de tout votre cœur et de toute votre âme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'j\'enverrai en leur saison les pluies propres à votre pays, celle de l\'automne et celle du printemps, afin que tu récoltes ton blé, ton moût et ton huile,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'et je fournirai à ton bétail de l\'herbe dans tes champs, afin que tu manges à rassasiement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Veillez sur vous-mêmes de peur que votre cœur ne soit séduit et que vous ne fassiez défection et que vous ne serviez d\'autres dieux et ne les adoriez;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'car alors la colère de l\'Éternel s\'allumera contre vous, et Il fermera les Cieux et il n\'y aura point de pluie, et le sol ne rendra pas son produit, et bientôt vous serez exterminés du beau pays que vous donne l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Mais déposez dans vos cœurs et dans vos âmes ces paroles que je vous dis, et liez-les sur vos mains comme des signes et portez-les comme bandelettes entre vos yeux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'et enseignez-les à vos fils, leur en parlant et assis dans ta maison et cheminant en voyage et à ton coucher et à ton lever,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'et inscris-les sur les piliers de ta maison et à tes portes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'afin que vos jours et les jours de vos fils se multiplient sur la terre, que l\'Éternel a juré à tes pères de leur donner, aussi longtemps que le soleil luira sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Car, si vous gardez tous ces commandements que je vous prescris, pour les pratiquer en aimant l\'Éternel, votre Dieu, et en marchant dans toutes ses voies et en restant attachés à lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'l\'Éternel chassera devant vous tous ces peuples, et vous vous soumettrez des peuples plus grands et plus forts que vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'tout lieu où vous marquerez la plante de vos pieds sera à vous; votre frontière ira du Désert au Liban, du Fleuve de l\'Euphrate à la Mer occidentale;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'nul ne vous tiendra tête; l\'Éternel, votre Dieu, vous fera précéder de la terreur et de l\'effroi que vous inspirerez, par tout le pays où vous allez marcher, comme Il vous l\'a promis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Voici, je mets devant vous en ce jour bénédiction et malédiction;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'la bénédiction pour le cas où vous obéirez aux commandements de l\'Éternel, votre Dieu, que je vous prescris en ce jour;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'et la malédiction pour le cas où vous n\'obéirez pas aux commandements de l\'Éternel, votre Dieu, et où vous quitterez la voie que je vous prescris en ce jour, pour servir d\'autres dieux que vous ne connaissez pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Et lorsque l\'Éternel, ton Dieu, t\'aura introduit dans le pays dont tu viens faire la conquête, tu prononceras la bénédiction du haut du mont Garizim et la malédiction du haut du mont Ebal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Voici, ils se trouvent en deçà du Jourdain, derrière la route, vers le couchant, dans le pays des Cananéens habitants de la plaine, vis-à-vis de Gilgal, près des Térébinthes de Moreh.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Car vous allez passer le Jourdain pour marcher à la conquête du pays que l\'Éternel, votre Dieu, vous donne, et vous en ferez la conquête et vous y établirez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Veillez donc à pratiquer tous les statuts et les lois que je vous mets en ce jour devant les yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Voici les statuts et les rites que vous garderez pour les pratiquer dans le pays que t\'a donné pour en faire la conquête l\'Éternel, Dieu de tes pères, aussi longtemps que vous vivrez sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Vous détruirez tous les lieux où les nations que vous allez chasser, rendaient un culte à leurs dieux sur les montagnes élevées, et sur les collines et sous tous les arbres verdoyants;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'et vous mettrez leurs autels en ruine, et briserez leurs colonnes et brûlerez au feu leurs Aschères, et mettrez en pièces les effigies de leurs dieux, et effacerez leurs noms de ces lieux-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Ce n\'est pas de la sorte que vous en agirez avec l\'Éternel, votre Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'mais vous chercherez le lieu que choisira l\'Éternel, votre Dieu, dans toutes vos Tribus pour y fixer son nom et y résider, et il sera votre Rendez-vous:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'et là vous amènerez vos holocaustes et vos victimes et vos dîmes et les élévations de vos mains et vos oblations votives et volontaires et les premiers-nés de votre gros et de votre menu bétail;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'et là vous ferez vos banquets devant l\'Éternel, votre Dieu, vous réjouissant de tout le travail de vos mains, vous et les familles dont t\'aura béni l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Vous ne ferez pas tout ce que nous faisons ici aujourd\'hui, où chacun agit à son gré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Car jusqu\'ici vous n\'êtes point encore entrés dans le lieu de repos et dans la propriété que te donnera l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Mais ayant une fois passé le Jourdain, et vous étant établis dans le pays dont l\'Éternel, votre Dieu, veut vous mettre en possession après vous avoir débarrassés de tous vos ennemis d\'alentour, et parvenus ainsi à un état de sécurité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'alors, au lieu que vous choisira l\'Éternel, votre Dieu, pour y fixer son nom, vous amènerez tout ce que je vous ai commandé, vos holocaustes et vos victimes, vos dîmes et les élévations de vos mains et le choix entier de vos oblations votives que vous aurez vouées à l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'et vous vous réjouirez en présence de l\'Éternel, votre Dieu, vous et vos fils et vos filles et vos serviteurs et vos servantes et le Lévite qui sera dans vos Portes, car il n\'a ni portion ni lot parmi vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Garde-toi de sacrifier tes holocaustes dans tous les lieux que tu auras en vue;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'mais c\'est au lieu que choisira l\'Éternel dans l\'une de tes Tribus; c\'est là que tu sacrifieras tes holocaustes, là que tu feras, tout ce que je te prescris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Cependant toutes les fois que tu en auras le désir en ton âme, tue, et mange de la viande selon l\'abondance dont l\'Éternel, ton Dieu, te bénira, dans toutes tes Portes; on en pourra manger dans l\'état de pureté ou d\'impureté, comme de la gazelle et du cerf;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'seulement le sang vous ne le mangerez pas, vous le verserez sur la terre comme de l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Tu ne pourras manger dans tes Portes les dîmes de ton blé et de ton moût et de ton huile, ni les premiers-nés de ton gros et menu bétail, ni aucune de tes oblations votives que tu voueras et de tes dons volontaires, ni les élévations de tes mains;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'mais c\'est devant l\'Éternel, ton Dieu, que tu les mangeras dans le lieu que choisira l\'Éternel, ton Dieu, toi et ton fils et ta fille et ton serviteur et ta servante et le Lévite qui est dans tes Portes; et tu te réjouiras en présence de l\'Éternel, ton Dieu, de tout le travail de tes mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Garde-toi de négliger le Lévite durant tout ton séjour dans ton pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Lorsque l\'Éternel, ton Dieu, aura étendu tes frontières, comme Il te l\'a promis, et que tu diras: Je veux manger de la viande; parce que ton désir sera d\'en manger, tu pourras manger de la viande suivant tout le désir de ton âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Si le lieu choisi par l\'Éternel, ton Dieu, pour y fixer son nom, est trop éloigné de toi, tue une pièce du gros et du menu bétail que t\'aura donné l\'Éternel, ainsi que je te l\'ai commandé, et manges-en dans tes Portes suivant tout le désir de ton âme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'seulement tu devras en user comme on use de la gazelle et du cerf; on en mangera dans l\'état de pureté et dans l\'état d\'impureté également.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Seulement tiens ferme à ne pas manger le sang, car le sang est l\'âme, et tu ne dois pas manger l\'âme avec la chair;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'tu ne le mangeras pas, tu le verseras sur la terre comme l\'eau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'tu ne le mangeras pas, pour que tu sois heureux, toi et tes fils après toi, en faisant ce qui est droit aux yeux de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'D\'ailleurs, quant aux choses saintes et aux oblations votives que tu auras, prends-les et rends-toi au lieu qu\'aura choisi l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'et sacrifie tes holocaustes, la chair et le sang, sur l\'Autel, de l\'Éternel, ton Dieu, et que le sang de tes victimes soit versé à l\'Autel de l\'Éternel, ton Dieu; quant à la chair, mange-la.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Garde et observe toutes ces choses que je te prescris, pour que tu sois heureux, toi et tes fils après toi, jusqu\'à l\'éternité, en faisant ce qui est bien et droit aux yeux de l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Lorsque l\'Éternel, ton Dieu, aura extirpé les nations que tu viens chasser devant toi, et que tu les auras chassées, et que tu seras assis dans leur pays,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'garde-toi de te laisser prendre au piège de leur exemple, une fois qu\'elles auront été détruites par toi, ni attirer vers leurs dieux, pour dire: Le culte que ces nations rendent à leurs dieux, je veux l\'imiter, moi aussi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'n\'agis pas ainsi envers l\'Éternel, ton Dieu; car elles faisaient pour leurs dieux tout ce qui est l\'abomination de l\'Éternel et qu\'il déteste, allant jusqu\'à brûler dans les flammes, à leurs dieux, leurs fils et leurs filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Gardez pour les pratiquer tous les préceptes que je vous prescris, et n\'y faites ni addition ni retranchement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'S\'il s\'élève au milieu de vous quelque prophète ou songeur, et s\'il t\'annonce un signe ou un prodige');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'et qu\'arrive le signe ou le prodige dont il te parlait tout en te disant: Suivons d\'autres dieux (que tu ne connais pas) et servons-les!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'tu ne prêteras point l\'oreille aux discours de ce prophète-là ou de ce songeur; car l\'Éternel, votre Dieu, veut vous mettre à l\'épreuve pour savoir si vous aimez l\'Éternel, votre Dieu, de tout votre cœur et de toute votre âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'C\'est l\'Éternel, votre Dieu, que vous devez suivre, Lui que vous devez craindre, ses commandements que vous devez garder, et sa voix que vous devez écouter, et Lui que vous devez servir, et à Lui que vous devez vous attacher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Ce prophète ou ce songeur-là sera mis à mort, parce qu\'il a prêché la rébellion contre l\'Éternel, votre Dieu, qui vous a retirés du pays d\'Egypte et rachetés de la maison de servitude; afin de te faire dévier de la voie dans laquelle t\'a ordonné de marcher l\'Éternel, ton Dieu: ainsi vous ôterez le mal du milieu de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Si ton frère, fils de ta mère, ou ton fils ou ta fille, ou la femme, qui est entre tes bras, ou ton ami, qui est comme un autre toi-même, t\'incite secrètement en disant: Allons et servons d\'autres dieux (qui ne furent connus ni de toi ni de tes pères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'l\'un des dieux des peuples de vos alentours, rapprochés ou éloignés de toi, d\'un bout de la terre à l\'autre),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'tu ne lui donneras pas ton assentiment, et ne l\'écouteras pas; tu n\'auras pour lui ni pitié, ni miséricorde, et tu ne le mettras pas à couvert;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'mais tu le feras mourir, ta main se lèvera la première sur lui pour lui donner la mort, et la main de tout le peuple ensuite,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'et tu le lapideras à coups de pierres pour qu\'il meure, parce qu\'il a cherché à te détacher de l\'Éternel, ton Dieu, qui t\'a retiré du pays d\'Egypte et de la maison de servitude;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'et que tout Israël entende et craigne, pour ne pas répéter un acte aussi criminel au milieu de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Si tu entends dire de l\'une de tes villes que l\'Éternel, ton Dieu, t\'a données pour y habiter:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Des hommes perdus, sortis du milieu de toi, ont séduit les habitants de leur ville en disant: Allons et servons d\'autres dieux (que vous ne connaissez pas),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'fais des perquisitions, des enquêtes, des interrogatoires exacts; et si voilà que c\'est un fait avéré, si la chose est constatée, si cette abomination s\'est commise dans ton sein,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'passe au fil de l\'épée les habitants de cette ville-là; tu la dévoueras ainsi que tout ce qu\'elle renferme et ses bestiaux, avec le tranchant de l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'Et tu réuniras toutes ses dépouilles au milieu de sa place, et tu brûleras au feu la ville et toutes ses dépouilles en holocauste à l\'Éternel, ton Dieu; et elle restera ruine éternelle: elle ne sera point rebâtie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Et que rien de ce qui a été dévoué ne reste attaché à ta main, afin que l\'Éternel revienne de son ardente colère, et te fasse miséricorde et ait pitié de toi, et te multiplie, comme Il l\'a juré à tes pères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'si tu obéis à la voix de l\'Éternel, ton Dieu, en gardant tous ses commandements que je te prescris en ce jour, en faisant ce qui est droit aux yeux de l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Vous êtes fils de l\'Éternel, votre Dieu: ne vous faites pas des incisions et ne vous rasez pas l\'intervalle des yeux, pour un mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Car tu es un peuple consacré à l\'Éternel, ton Dieu, et l\'Éternel t\'a choisi pour être son peuple particulier entre tous les peuples qui sont sur la face de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Abstiens-toi de tout aliment abominable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Voici les animaux dont vous vous nourrirez: le bœuf, la brebis et la chèvre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'le cerf, et la gazelle et le daim, et le bouquetin, et le dischon et le theo, et le zamer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'et tout animal ayant la corne fendue, fendue de part en part, en fourche; tout ce qui rumine parmi les animaux, vous servira de nourriture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Voici seulement ceux que vous ne mangerez pas, des ruminants et de ceux qui ont la corne fendue de part en part: le chameau, et le lièvre, et la gerboise, car ils ruminent, mais n\'ont pas la corne fendue: tenez-les pour immondes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'et le porc, car il a la corne fendue, mais ne rumine pas; tenez-le pour immonde: vous ne mangerez pas leur chair et ne toucherez pas leurs cadavres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Voici ceux que vous mangerez entre tous les aquatiques: tout ce qui a nageoires et écailles, vous pouvez le manger;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'mais vous vous abstiendrez de tout ce qui n\'a pas nageoires et écailles: tenez-le pour immonde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Vous pouvez manger de tous les oiseaux purs, mais voici ceux dont vous vous abstiendrez:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'l\'aigle, l\'orfraie et l\'aigle de mer');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'et le faucon et le vautour et le milan selon leur espèce,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'et tous les corbeaux selon leurs espèces, et l\'autruche femelle');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'et l\'autruche mâle et la mouette et l\'épervier selon leur espèce,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'et le hibou et l\'ibis et le cygne');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'et le pélican et le percnoptère et le pélican sauteur');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'et la cigogne et le perroquet selon leur espèce, et la huppe et la chauve-souris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Et tenez pour immonde tout ver ailé: il ne se mangera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Mangez de tous les oiseaux purs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Vous ne mangerez point de bête morte, tu pourras la donner à l\'étranger qui est dans tes Portes pour la manger ou la vendre à un homme du dehors; car tu es un peuple consacré à l\'Éternel, ton Dieu. Tu ne feras point cuire le chevreau au lait de sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Tu dîmeras tout le produit de tes semailles, que rend annuellement ton champ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Et tu mangeras devant l\'Éternel, ton Dieu, au lieu qu\'il aura choisi pour y fixer son nom, la dîme de ton blé, de ton moût et de ton huile et la primogéniture de ton gros et menu bétail, afin que tu apprennes à craindre en tout temps l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Et si le chemin est trop long pour que tu puisses l\'y transporter vu la distance du lieu choisi par l\'Éternel, ton Dieu, pour y fixer son nom, et l\'abondance dont t\'aura béni l\'Éternel, ton Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'échange-la contre de l\'argent, et serre l\'argent dans ta main, et va au lieu choisi par l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'Et donne cet argent en échange de tout ce que tu désires en fait de bœufs, de brebis, de vin, de cervoise, de tout ce que ton désir réclame, et mange, là, devant l\'Éternel, ton Dieu, te réjouissant toi et ta famille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Et ne néglige pas le Lévite qui est dans tes Portes, car il n\'a ni portion ni lot parmi vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'A la fin de chaque troisième année tu extrairas toute la dîme de ta récolte de cette année-là, et tu la déposeras dans tes Portes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'et le Lévite (car il n\'a ni portion ni lot parmi vous) et l\'étranger et l\'orphelin et la veuve qui sont dans tes Portes, viendront et mangeront et se rassasieront, afin que l\'Éternel, ton Dieu, te bénisse dans tout le travail de tes mains que tu entreprendras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Au terme de sept années, tu feras relâche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Et voici le mode du relâche: Tout créancier se relâchera pour ce qu\'il aura prêté à son prochain; il n\'usera pas de rigueur contre son prochain et son frère; car on a proclamé relâche de par l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Contre l\'étranger tu pourras user de rigueur, mais tu te relâcheras pour ce que tu as chez ton frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Cependant il ne doit plus y avoir de pauvres chez vous, car l\'Éternel te comblera de bénédictions dans le pays que l\'Éternel, ton Dieu, te donne en propriété pour l\'occuper,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'pourvu seulement que tu sois docile à la voix de l\'Éternel, ton Dieu, pour t\'appliquer à pratiquer la totalité de ce commandement que je te prescris en ce jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Car l\'Éternel, ton Dieu, te bénira comme Il te l\'a promis, et tu prêteras sur gages à beaucoup de nations, sans emprunter toi-même, et tu tiendras sous ta dépendance beaucoup de nations, mais elles ne te tiendront pas sous la leur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'S\'il y a parmi vous quelque pauvre, lequel que ce soit de tes frères, à l\'une de tes Portes, dans ton pays que l\'Éternel, ton Dieu, te donne, tu n\'endurciras pas ton cœur et ne fermeras point ta main pour ton frère indigent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'tu ouvriras au contraire ta main pour lui et lui prêteras sur gage, assez pour ses besoins, ce qui lui manque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Prends garde qu\'en ton cœur ne s\'élève la criminelle pensée qui te ferait dire: La septième année, l\'année du relâche, approche! et que tu ne regardes d\'un œil malveillant ton frère, le pauvre, pour ne lui rien donner, et qu\'il ne réclame contre toi auprès de l\'Éternel, et que tu ne te charges d\'un péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Donne, donne-lui et n\'aie pas le cœur chagrin en lui donnant, car c\'est pour cela que l\'Éternel, ton Dieu, te bénira dans tous tes travaux et toutes tes entreprises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Puisqu\'il ne manquera pas de pauvre dans le pays, c\'est pourquoi je te donne ce commandement: Ouvre ta main pour ton frère, tes indigents et tes pauvres dans ton pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Si ton frère, Hébreu, ou femme de la nation des Hébreux, s\'est vendu à toi et t\'a servi six ans, la septième année tu le laisseras sortir libre de chez toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'et le laissant ainsi sortir libre de chez toi, tu ne le renverras pas à vide;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'gratifie-le d\'un don pris sur ton menu bétail, sur ton aire et à ton pressoir, c\'est ce dont l\'Éternel, ton Dieu, t\'aura béni, que tu lui donneras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Et souviens-toi que tu fus esclave dans le pays d\'Egypte, et que l\'Éternel, ton Dieu, t\'a racheté; c\'est pourquoi je te prescris aujourd\'hui ce commandement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Mais s\'il te dit: Je ne veux pas sortir de chez toi, car je t\'aime toi et ta maison, parce qu\'il se trouve bien chez toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'prends l\'alêne et perce-lui-en l\'oreille contre la porte; et il sera ton esclave à perpétuité; et pour ta servante tu procéderas de même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Et qu\'il ne te semble pas dur de le laisser sortir libre de chez toi, car son service de six années chez toi vaut le double de la paie d\'un mercenaire; et l\'Éternel, ton Dieu, te bénira dans tout ce que tu feras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Tu consacreras à l\'Éternel, ton Dieu, tout premier-né qui naîtra dans ton gros et ton menu bétail, les mâles. Tu n\'emploieras point à tes travaux le premier-né de ton bœuf, et ne tondras point le premier-né de tes brebis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'c\'est devant l\'Éternel, ton Dieu, que tu le mangeras chaque année, dans le lieu choisi par l\'Éternel, toi et ta famille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Et s\'il a quelque défaut, étant ou boiteux ou aveugle, s\'il est taré en quelque manière, tu ne le sacrifieras point à l\'Éternel, ton Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'tu le mangeras dans tes Portes, en état d\'impureté ou en état de pureté, comme de la gazelle et du cerf.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Seulement tu ne mangeras pas son sang, tu le verseras sur la terre comme de l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Observe le mois des épis pour faire la Pâque à l\'Éternel, ton Dieu; car c\'est dans le mois des épis que l\'Éternel, ton Dieu, t\'a retiré de l\'Egypte, pendant la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Et sacrifie comme Pâque à l\'Éternel, ton Dieu, du menu et du gros bétail, dans le lieu que choisira l\'Éternel, ton Dieu, pour y fixer son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Et tu ne mangeras en même temps rien de fermenté; pendant sept jours tu y joindras des azymes, pain du malheur, parce que tu sortis à la précipitée du pays d\'Egypte; afin que tu te souviennes toute ta vie du jour de ta sortie du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Et qu\'il ne paraisse pas de levain chez toi dans tout ton territoire pendant sept jours, et que de la chair du sacrifice que tu feras le soir du premier jour, rien ne soit conservé au delà de la nuit jusqu\'au matin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Tu n\'as pas la faculté de faire le sacrifice de la Pâque dans l\'une de tes villes que l\'Éternel, ton Dieu, te donne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'mais c\'est dans le lieu que choisira l\'Éternel, ton Dieu, pour y fixer son nom, que tu feras le sacrifice de la Pâque, le soir au coucher du soleil, moment de ta sortie de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Et fais-le cuire et le mange dans le lieu que choisira l\'Éternel, ton Dieu, et le matin retourne-t\'en et prends le chemin de tes tentes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Pendant six jours tu mangeras des azymes, et le septième jour il y aura solennelle convocation en l\'honneur de l\'Éternel, ton Dieu, tu t\'abstiendras de tout travail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Tu compteras sept semaines; à partir du moment où la faux commence à être mise aux blés, tu commenceras à compter sept semaines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Puis célèbre la fête des Semaines en l\'honneur de l\'Éternel, ton Dieu, calculant l\'oblation volontaire de ta main, que tu offriras, d\'après la bénédiction que t\'aura accordée l\'Éternel, ton Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'et tu te réjouiras devant l\'Éternel, ton Dieu, toi et ton fils et ta fille et ton serviteur et ta servante et le Lévite qui est dans tes Portes et l\'étranger et l\'orphelin et la veuve qui sont au milieu de toi, dans le lieu que choisira l\'Éternel, ton Dieu, pour y fixer son nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'et tu te rappelleras que tu fus esclave en Egypte, pour garder et mettre en pratique tous ces statuts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Tu célébreras la fête des loges pendant sept jours, lorsque tu auras retiré tes récoltes de ton aire et de ton pressoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Et réjouis-toi dans cette fête, toi et ton fils et ta fille et ton serviteur et ta servante et le Lévite et l\'étranger et l\'orphelin et la veuve qui sont dans tes Portes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Tu fêteras sept jours en l\'honneur de l\'Éternel, ton Dieu, dans le lieu que choisira l\'Éternel. Car l\'Éternel, ton Dieu, te bénira dans toute ta récolte et dans tout le travail de tes mains, afin que tu n\'aies que de la joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Trois fois dans l\'année, tous tes hommes se présenteront devant la face de l\'Éternel, ton Dieu, dans le lieu qu\'il choisira, à la fête des azymes, et à la fête des Semaines, et à la fête des loges, et l\'on ne paraîtra pas devant l\'Éternel, les mains vides,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'mais chacun selon ce qu\'il peut offrir en raison de l\'abondance dont l\'Éternel, ton Dieu, t\'aura béni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Tu établiras sur toi des Juges et des magistrats dans toutes tes Portes que te donnera l\'Éternel, ton Dieu, d\'après tes Tribus, afin qu\'ils jugent le peuple d\'un jugement juste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Tu ne feras pas fléchir le droit, et tu ne feras pas acception des personnes, et tu n\'accepteras point de présents, car les présents aveuglent les yeux des sages et gâtent les causes des justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'La justice, la justice est le but que tu as à poursuivre afin que tu vives et te rendes maître du pays que l\'Éternel, ton Dieu, te donne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Tu ne planteras point d\'Aschères d\'aucune espèce d\'arbres, à côté de l\'Autel de l\'Éternel, ton Dieu, que tu te construiras,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'et n\'élèveras point des statues que hait l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Tu ne sacrifieras à l\'Éternel, ton Dieu, ni bœuf, ni brebis qui ait un défaut, un vice quelconque, car c\'est l\'abomination de l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'S\'il se rencontre au milieu de vous dans l\'une des villes que l\'Éternel, ton Dieu, te donnera, un homme ou une femme qui fasse ce qui est mal aux yeux de l\'Éternel, en violant son alliance');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'et en allant servir d\'autres dieux, et les adorer, et le soleil ou la lune ou toute l\'armée des cieux, ce qui est contre mon ordre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'et si l\'on t\'en fait rapport et que tu en sois informé, dresse une enquête exacte; et si c\'est la vérité et que le fait soit constaté et que cette abomination ait été commise en Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'tu traduiras à tes Portes cet homme ou cette femme qui aura commis ce crime, l\'homme ou la femme, et tu les lapideras à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Celui qui mérite la mort, sera mis à mort sur la déposition de deux ou de trois témoins; il ne sera pas mis à mort sur la déposition d\'un témoin unique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'La main des témoins se lèvera la première contre lui pour le faire mourir, et la main de tout le peuple ensuite. Ainsi vous ôterez le mal du milieu de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Si à tes Portes tu as une question trop difficile à juger, entre meurtre et meurtre, entre grief et grief, entre coup et coup, dans des cas litigieux, lève-toi et monte au lieu qu\'aura choisi l\'Éternel, ton Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'et adresse-toi aux Prêtres, Lévites, et au Juge qu\'il y aura à cette époque, et enquiers-toi, et ils t\'exposeront le point de droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Puis agis suivant le point de droit qu\'ils t\'auront exposé de ce lieu-là choisi par l\'Éternel, et tu auras soin d\'agir d\'après tout ce qu\'ils t\'auront enseigné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Tu agiras d\'après la loi qu\'ils t\'enseigneront, et la règle de droit, qu\'ils te diront, tu ne t\'écarteras du point de droit qu\'ils t\'exposeront, ni à droite ni à gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Et l\'homme qui montrerait assez de présomption pour ne pas écouter le Prêtre qui est là en service devant l\'Éternel, ton Dieu, ou auprès du Juge, cet homme-là mourra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Ote ainsi le mal du sein d\'Israël, et tout le peuple entendra et craindra, et n\'aura plus cette audace dans la suite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Lorsque tu seras entré dans le pays que l\'Éternel, ton Dieu, te donne, et que tu l\'auras conquis, et y seras établi, et que tu diras: Je veux me donner un Roi à l\'exemple de toutes les nations qui m\'environnent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'tu te donneras pour Roi celui que choisira l\'Éternel, ton Dieu; c\'est parmi tes frères que tu prendras le Roi à préposer sur toi; tu ne pourras préposer sur toi un homme du dehors qui ne soit pas ton frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Seulement qu\'il n\'ait pas une multitude de chevaux et ne ramène pas le peuple en Egypte pour se procurer beaucoup de chevaux; car l\'Éternel vous a dit: Vous ne reprendrez plus ce chemin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Et qu\'il n\'ait pas un grand nombre de femmes, afin que son cœur ne se détourne pas, non plus qu\'une très grande quantité d\'or et d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Et lorsqu\'il sera assis sur le trône de son royaume, qu\'il se copie un double de cette Loi-ci d\'après l\'exemplaire conservé par les Prêtres, les Lévites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Et qu\'il l\'ait avec lui, et y lise tout le temps de sa vie, dans le but d\'apprendre à craindre l\'Éternel, son Dieu, à garder,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'pour les pratiquer, toutes les paroles de cette Loi et ces statuts, afin que son cœur ne s\'élève pas au-dessus de ses frères, et qu\'il ne dévie du commandement ni à droite ni à gauche, afin que les jours de lui et de ses fils se prolongent au sein d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Les Prêtres, les Lévites, la Tribu de Lévi entière, n\'auront ni portion ni lot au milieu d\'Israël: ils jouiront des sacrifices ignés de l\'Éternel et de Sa part;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'ils n\'auront aucune propriété parmi leurs frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'L\'Éternel est leur lot, comme Il le leur a dit. Et voici ce que les Prêtres ont le droit de réclamer du peuple et de ceux qui sacrifient des victimes, soit gros, soit menu bétail: on donnera au Prêtre l\'épaule et les deux mâchoires et le ventricule gras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Tu leur donneras les prémices de ton froment, de ton moût et de ton huile, et les prémices de la tonte de tes moutons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Car l\'Éternel, ton Dieu, l\'a choisi entre toutes tes Tribus pour porter présence officiant de par l\'Éternel, lui et ses fils à perpétuité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Et si le Lévite sort de l\'une de tes villes où il est domicilié, dans tout Israël, et que suivant tout le désir de son âme il arrive au lieu qu\'aura choisi l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'et y officie de par l\'Éternel, son Dieu, ainsi que tous ses frères les Lévites présents pour servir l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'ils jouiront de portions égales, outre ce qu\'ils peuvent vendre de leur patrimoine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Lorsque tu seras entré dans le pays que l\'Éternel, ton Dieu, te donne, tu n\'apprendras pas à imiter les abominations de ces nations-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Qu\'on ne trouve chez toi personne qui fasse passer par le feu son fils ou sa fille, qui pratique la divination, les maléfices, les enchantements et les conjurations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'personne qui fasse des nœuds magiques, évoque les morts, se livre aux sciences occultes, interroge les trépassés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Car quiconque fait ces choses est l\'abomination de l\'Éternel, et c\'est à cause de cette abomination-là que l\'Éternel, ton Dieu, va les chasser devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'C\'est sans partage que tu dois appartenir à l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Car ces nations que tu vas expulser, écoutent les enchanteurs et les devins; mais à toi, l\'Éternel, ton Dieu, ne le permet pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'C\'est un prophète de ton sein, d\'entre tes frères, semblable à moi que te suscitera l\'Éternel, ton Dieu, c\'est Lui que vous écouterez;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'ainsi que tu l\'as demandé à l\'Éternel, ton Dieu, en Horeb, le jour de l\'Assemblée, lorsque tu dis: Désormais je ne veux plus entendre la voix de l\'Éternel, mon Dieu, ni voir ce grand feu, afin de ne pas mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Et l\'Éternel me dit: Ce qu\'ils ont dit est bien;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'je leur susciterai un prophète du sein de leurs frères, semblable à toi, et je mettrai mes paroles en sa bouche, et il leur dira tout ce dont je le chargerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Et à quiconque n\'écoutera pas mes paroles qu\'il prononcera en mon nom, je lui en demanderai compte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Mais le prophète qui aura l\'audace de dire en mon nom ce que je ne lui aurai point commandé de dire, et celui qui parlera au nom de dieux étrangers, ce prophète mourra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Et si tu dis en ton cœur: A quoi reconnaîtrons-nous la parole que l\'Éternel n\'aura point prononcée?...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'ce que dira ce prophète au nom de l\'Éternel et qui n\'aura pas lieu, et ne s\'accomplira pas, telle sera la parole que l\'Éternel n\'aura pas dite; le prophète l\'a dite par audace: n\'aie pas peur de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Lorsque l\'Éternel, ton Dieu, aura extirpé les nations dont l\'Éternel, ton Dieu, te donne le pays, et que tu les auras expulsées, et que tu seras établi dans leurs villes et dans leurs maisons,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'tu sépareras trois villes au sein de ton pays que te donne l\'Éternel, ton Dieu, pour l\'occuper.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Tu construiras la route [pour y arriver], et tu diviseras en trois le territoire de ton pays dont l\'Éternel, ton Dieu, va te mettre en possession, pour y ouvrir un asile à tout homicide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Et voici la règle pour l\'homicide qui s\'y réfugiera afin de sauver sa vie: Celui qui aura tué son prochain par mégarde, ne le haïssant ni d\'hier ni d\'avant-hier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'et comme celui qui sera allé dans la forêt couper du bois avec son prochain, et brandira sa main armée de la hache pour abattre l\'arbre, si le fer se détache du manche et atteint son prochain qui en meure, il se réfugiera dans l\'une de ces villes pour mettre sa vie en sûreté,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'afin que le vengeur du sang, dans réchauffement de la colère, ne poursuive et n\'atteigne pas l\'homicide à la faveur de la longueur du chemin et ne lui ôte pas la vie, quand pourtant il ne mérite pas la mort, puisqu\'il n\'avait contre lui aucune haine antérieure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'C\'est pourquoi je te donne ce commandement: Tu sépareras trois villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Et lorsque l\'Éternel, ton Dieu, aura étendu ton territoire, comme Il l\'a juré à tes pères, et qu\'il t\'aura donné tout le pays qu\'il a promis de donner à tes pères');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, '(si tu gardes la totalité de ce commandement que je te prescris en ce jour pour le pratiquer, aimer l\'Éternel, ton Dieu, et marcher dans ses voies en tout temps), tu ajouteras encore trois villes à ces trois,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'afin que le sang innocent ne soit pas versé dans ton pays que l\'Éternel, ton Dieu, va te donner en propriété et que tu ne te mettes pas sous le poids du meurtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Mais si un homme hait son prochain et le guette et l\'attaque et le frappe à mort, et qu\'il se réfugie dans l\'une de ces villes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'les Anciens de sa ville enverront [des gens] pour l\'en tirer, et le livreront aux mains du vengeur du sang, afin qu\'il meure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Tu ne le regarderas pas avec pitié; ainsi tu déchargeras Israël du sang innocent et seras heureux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Tu ne déplaceras point les bornes de ton prochain, que les ancêtres ont placées dans ton héritage que tu posséderas dans le pays que l\'Éternel, ton Dieu, va te donner pour en faire la conquête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Un témoin unique ne sera pas recevable contre quelqu\'un dans aucune espèce de délit ou de péché quelconque, dans une espèce quelconque de péché dont on se rend coupable; une sentence ne sera valable que sur la déposition de deux ou de trois témoins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Si un faux témoin se lève contre quelqu\'un pour le déclarer coupable d\'un crime,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'les deux parties comparaîtront devant l\'Éternel, devant les Prêtres et les Juges qu\'il y aura à cette époque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Et les Juges informeront exactement; et si le témoin est un faux témoin, s\'il a déposé faussement contre son frère,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'vous lui ferez subir ce qu\'il pensait à faire à son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Ainsi vous ôterez le mal du milieu de vous; et les autres entendront et craindront, et à l\'avenir ne commettront plus cette mauvaise action au milieu de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Point de pitié! vie pour vie, œil pour œil, dent pour dent, main pour main, pied pour pied.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Lorsque tu te mettras en campagne contre tes ennemis, et que tu verras des chevaux et des chars, une armée plus nombreuse que toi, n\'aie pas peur d\'eux, car l\'Éternel, ton Dieu, est avec toi, Lui qui t\'a fait sortir du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Et quand vous serez près d\'engager le combat, le Prêtre s\'avancera et parlera au peuple');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'et il leur dira: Écoutez, Israélites! vous êtes aujourd\'hui sur le point de livrer bataille à vos ennemis; que votre cœur ne faiblisse pas, n\'ayez pas peur et ne tremblez pas, et ne prenez pas l\'alarme devant eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Car l\'Éternel, votre Dieu, est Celui qui marche avec vous pour combattre pour vous contre vos ennemis, pour vous donner la victoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Ensuite les officiers parleront au peuple en ces termes: Lequel a bâti une maison neuve et n\'en a pas encore fait la dédicace? qu\'il s\'en aille et regagne sa maison, de peur qu\'il ne périsse dans la bataille et qu\'un autre n\'en fasse la dédicace.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Et lequel a planté une vigne et n\'en a pas encore eu la première jouissance? qu\'il s\'en aille et regagne sa maison, de peur qu\'il ne périsse dans la bataille et qu\'un autre n\'en ait la première jouissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Et lequel s\'est fiancé à une femme, et ne l\'a pas encore épousée? qu\'il s\'en aille et regagne sa maison, de peur qu\'il ne périsse dans la bataille et qu\'un autre ne l\'épouse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Et les officiers continueront à parler au peuple en ces termes: Lequel a peur et est intimidé? qu\'il s\'en aille et regagne sa maison, de peur que sa pusillanimité ne se communique à ses frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Et quand les officiers auront achevé de parler au peuple, ils mettront à la tête du peuple les chefs de corps d\'armée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Quand tu arriveras devant une place pour lui donner l\'assaut, somme-la de capituler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Et si elle te répond en acceptant la capitulation, et s\'ouvre devant toi, tout le peuple qui s\'y trouvera, te deviendra corvéable, et te sera asservi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Mais si elle ne veut pas capituler avec toi, et qu\'elle se mette en guerre contre toi et que tu l\'assièges,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'et que l\'Éternel, ton Dieu, la livre entre tes mains, tu en passeras tous les mâles au fil de l\'épée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'seulement tu feras ton butin des femmes et des enfants et des bestiaux et de tout ce qu\'elle renfermera, et de toutes ses dépouilles, et vous jouirez de la dépouille de vos ennemis que vous livre l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Ainsi traiterez-vous toutes les villes situées à une très grande distance de vous et ne faisant pas partie des villes de ces peuples d\'ici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Mais dans les villes de ces peuples-ci, que l\'Éternel, ton Dieu, te donne en propriété, tu ne laisseras la vie à rien de ce qui respire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'tu les dévoueras, au contraire: les Héthiens et les Amoréens, les Cananéens et les Perizzites, les Hévites et les Jébusites, conformément à l\'ordre de l\'Éternel, ton Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'afin qu\'ils ne vous apprennent pas à imiter toutes leurs abominations qu\'ils font pour leurs dieux, et que vous ne vous rendiez pas coupables envers l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Quand tu auras tenu longtemps une ville bloquée pour l\'assiéger, pour la prendre, tu ne détruiras pas les arbres, en y mettant la hache, car tu peux t\'en nourrir, et tu ne dois pas les abattre, car les arbres des champs sont [trop utiles] à l\'homme pour être aussi assiégés par toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Les arbres seuls dont tu sais qu\'ils ne fournissent point d\'aliments, tu pourras les endommager et les abattre, et en construire des ouvrages propres à faire le siège de la ville qui est en guerre avec toi, jusqu\'à ce qu\'elle succombe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Si l\'on trouve dans le pays que l\'Éternel, ton Dieu, te donne pour le conquérir un homme percé de coups, gisant dans la campagne, sans que l\'on sache qui l\'a tué,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'tes Anciens et tes Juges sortiront et prendront les distances des villes qui se trouvent dans tous les environs du cadavre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'or la ville la plus proche du cadavre trouvée, les Anciens de cette ville-ci prendront une génisse qu\'on n\'ait pas employée au travail et qui n\'ait pas encore tiré au joug,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'et les Anciens de cette ville amèneront cette génisse auprès d\'un cours d\'eau qui ne tarit pas, et dont le lit ne soit ni labouré, ni ensemencé, et là ils rompront la nuque à la génisse dans le cours d\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Alors s\'approcheront les Prêtres, fils de Lévi, car l\'Éternel, ton Dieu, les a choisis pour le servir et bénir au nom de l\'Éternel, et ils prononcent sur tous les procès et dommages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Et tous les Anciens de cette ville les plus rapprochés du cadavre laveront leurs mains sur la génisse à laquelle on a rompu la nuque dans le cours d\'eau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'et ils feront cette déclaration: Nos mains n\'ont point versé ce sang, et nos yeux n\'ont pas vu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'sois propice à ton peuple d\'Israël que tu as racheté, Éternel, et ne mets pas le sang innocent à la charge de ton peuple d\'Israël: ainsi sera faite pour eux l\'expiation de ce sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Et toi tu ôteras de ton sein le sang innocent, car tu dois faire ce qui est droit aux yeux de l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Lorsque tu te mettras en campagne contre tes ennemis et que l\'Éternel les livrera entre tes mains, et que tu leur feras des prisonniers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'si tu distingues parmi les captives une femme d\'une belle figure et que tu t\'attaches à elle et que tu veuilles l\'épouser,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'amène-la dans l\'intérieur de ta maison, et qu\'elle se rase la tête, et se fasse les ongles');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'et dépouille ses habits de captive, et demeure dans ta maison et pleure son père et sa mère durant une lunaison; et après ces choses ainsi faites, tu pourras t\'approcher d\'elle et l\'épouser pour qu\'elle soit ta femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Et si tu te dégoûtes d\'elle, laisse-la libre d\'aller où elle voudra; mais tu ne la vendras pas à prix d\'argent, ni ne l\'emploieras comme esclave, puisque tu as usé envers elle des droits d\'un mari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Un homme ayant deux femmes, l\'une aimée, l\'autre haïe, et l\'une et l\'autre, celle qui est aimée et celle qui est haïe, lui ayant donné des fils, et le fils premier-né étant de l\'épouse haïe,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'il ne pourra, lorsqu\'il fera entre ses fils le partage de ce qu\'il a, conférer la primogéniture au fils de l\'épouse aimée, en face du fils de l\'épouse haïe, lequel est le premier-né;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'mais il devra reconnaître le premier-né, fils de l\'épouse haïe, en lui donnant double part dans sa succession entière, car il est les prémices de sa vigueur, à lui appartiennent les droits de primogéniture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Un homme ayant un fils réfractaire et indiscipliné qui n\'écoute ni la voix de son père, ni la voix de sa mère, et même châtié ne leur obéit pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'le père et la mère le prendront et le traduiront devant les Anciens de sa ville et aux Portes du lieu qu\'il habite,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'et ils diront aux Anciens de sa ville: Notre fils ici présent est réfractaire et indiscipliné; il n\'écoute pas notre voix; il est dissipateur et ivrogne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Et tous les hommes de sa ville le lapideront, et il mourra. Ote ainsi le mal du milieu de toi, et que tout Israël entende et craigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Quand en suite d\'un péché qui méritait la mort, un homme aura été mis à mort, et que tu l\'auras pendu à un arbre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'son corps ne passera pas la nuit attaché au bois; mais tu l\'inhumeras le jour même, car le pendu est sous la malédiction de Dieu, et tu ne dois pas souiller ton pays que l\'Éternel, ton Dieu, te donne en propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Apercevant le bœuf de ton frère ou sa brebis, qui errent, ne les esquive pas; ramène-les à ton frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Et si ton frère n\'est pas à ta proximité, et si tu ne les connais pas, recueille-les dans ta maison et garde-les chez toi, jusqu\'à ce que ton frère vienne les réclamer; et alors rends-les-lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Et ainsi feras-tu s\'il s\'agit de son âne et ainsi feras-tu pour son manteau et ainsi feras-tu pour tout objet perdu que ton frère aura perdu et que tu trouveras: il ne t\'est pas permis d\'esquiver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Quand tu verras l\'âne de ton frère, ou son bœuf, tombés sur la route, ne les esquive pas: joins-toi à lui pour les relever.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Une femme ne prendra point le costume d\'un homme, ni un homme des vêtements de femme; car quiconque le fait, est l\'abomination de l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Si en chemin tu rencontres devant toi un nid d\'oiseau, sur quelque arbre ou sur le sol, avec des petits ou des œufs et la mère posée sur les petits ou sur les œufs, tu ne prendras pas la mère avec la couvée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Lâche la mère et prends la couvée pour toi, afin que tu sois heureux et aies de longs jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Lorsque tu bâtiras une maison neuve, munis ton toit d\'un parapet, afin de ne pas entacher de sang ta maison, si quelqu\'un en tombait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Ne sème point dans ta vigne des semences de deux espèces, de peur que l\'abondance donnée par la semence que tu sèmeras, et le produit de ta vigne, n\'aille au sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Tu ne laboureras pas avec un bœuf et un âne réunis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Tu ne t\'habilleras pas d\'un tissu mélangé, ourdi de laine et de lin réunis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Tu te feras des houppes aux quatre angles du manteau dont tu t\'enveloppes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Si un homme épouse une femme, habite avec elle, puis la prend en haine,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'et lui attribue des choses criminelles, et répand de mauvais bruits sur son compte, et dit: J\'ai épousé cette femme et me suis approché d\'elle, mais je ne l\'ai pas eue vierge;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'dans ce cas le père de la fille et sa mère prendront les preuves de la virginité de la fille et les exhiberont aux Anciens de la ville, à la Porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'Et le père de la fille dira aux Anciens: J\'avais donné ma fille en mariage à l\'homme ici présent, et il l\'a prise en haine,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'et voilà qu\'il lui impute des choses criminelles en disant: Je n\'ai pas eu ta fille vierge. Mais voici les preuves de la virginité de ma fille. Puis ils étaleront le drap devant les Anciens de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Alors les Anciens de cette ville appréhenderont le mari et le châtieront');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'et lui infligeront une amende de cent sicles d\'argent, qu\'ils donneront au père de la fille, parce qu\'il a répandu de mauvais bruits sur une vierge d\'Israël. Et elle restera sa femme, et de toute sa vie il ne pourra la répudier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Mais si ce fait est avéré, si la fille n\'a pas été trouvée vierge,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'que l\'on amène la fille à la porte de la maison de son père, et que les hommes de sa ville la lapident et qu\'elle meure pour avoir commis une infamie dans Israël, en s\'abandonnant dans la maison de son père. Ote ainsi le mal du milieu de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Si un homme est surpris couchant avec une femme mariée, ils mourront l\'un et l\'autre, l\'homme qui a couché avec la femme, et la femme. Ote ainsi le mal du sein d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Si une fille vierge est fiancée à un homme, et qu\'un individu la trouve dans la ville et habite avec elle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'amenez-les l\'un et l\'autre à la Porte de cette ville et lapidez-les, et qu\'ils meurent, la fille pour n\'avoir jeté aucun cri dans la ville, et l\'homme pour avoir déshonoré la femme de son prochain. Ote ainsi le mal du milieu de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Mais si c\'est dans les champs que l\'individu a rencontré la fille fiancée, et s\'est saisi d\'elle, et a habité avec elle, la peine de mort ne sera infligée qu\'à l\'homme qui a habité avec elle, à l\'homme seulement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Et tu ne feras rien à la fille; il n\'y a à la charge de la fille aucun péché qui mérite la mort: c\'est le même cas que celui de l\'homme qui attaque son prochain et le tue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Car c\'est dans les champs qu\'il l\'a rencontrée; la fille fiancée a jeté son cri, et personne n\'est venu à son secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Si un homme rencontre une vierge non fiancée, et se saisit d\'elle, et habite avec elle, et si on les prend sur le fait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'dans ce cas l\'individu qui a habité avec la fille paiera au père de celle-ci cinquante sicles d\'argent, et elle deviendra sa femme, parce qu\'il lui a ôté sa virginité, et de toute sa vie il ne pourra la répudier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Nul n\'épousera la femme de son père, et ne soulèvera la couverture de son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Aucun individu mutilé par compression ou par amputation de l\'urètre ne sera admis dans l\'Assemblée de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Aucun bâtard ne sera admis dans l\'Assemblée de l\'Éternel; même sa dixième génération ne sera pas admise dans l\'Assemblée de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Ne seront pas admis non plus les Ammonites et les Moabites dans l\'Assemblée de l\'Éternel; même leur dixième génération ne sera pas admise dans l\'Assemblée de l\'Éternel, jamais;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'parce qu\'ils ne vous ont pas présenté le pain et l\'eau pendant le trajet, lors de votre sortie de l\'Egypte, et parce qu\'ils ont soudoyé pour te nuire, Balaam, fils de Behor, de Pethor en Mésopotamie, pour te maudire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Mais l\'Éternel, ton Dieu, n\'a pas voulu écouter Balaam, et l\'Éternel, ton Dieu, a changé sa malédiction en bénédiction, parce que l\'Éternel, ton Dieu, t\'aimait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Tu ne t\'intéresseras en aucun temps à leur prospérité et à leur bien-être, jamais. Tu n\'abomineras pas l\'Edomite, car il est ton frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Tu n\'abomineras pas l\'Égyptien, car tu fus son hôte dans son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Les fils qui leur naîtront à la troisième génération, seront admissibles dans l\'Assemblée de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Quand tu seras en campement, marchant contre tes ennemis, évite avec soin toute indécence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'S\'il se trouve chez toi quelqu\'un qui ne soit pas en état de pureté à la suite d\'un accident nocturne, qu\'il se transporte hors du camp; il ne doit pas entrer dans l\'intérieur du camp,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'mais vers le soir il se baignera dans l\'eau, et au coucher du soleil il rentrera dans l\'intérieur du camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Tu auras aussi des lieux d\'aisance hors du camp, et tu iras là, dehors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Et à tes outils tu joindras une pelle, et quand tu iras dehors, tu t\'en serviras pour en faire un creux et recouvrir tes déjections.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Car l\'Éternel, ton Dieu, est présent dans ton camp, pour te délivrer, et faire céder tes ennemis devant toi; ton camp doit donc être saint, de peur que s\'il y voit quelque chose de dégoûtant, Il ne se retire loin de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Tu ne livreras pas à son maître l\'esclave qui se sera sauvé chez toi de chez son maître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Il demeurera chez toi dans ton intérieur, au lieu qu\'il aura choisi dans l\'une de tes villes, où bon lui semblera; tu ne seras pas dur envers lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Qu\'il ne se trouve aucune prostituée parmi les filles d\'Israël, et aucun prostitué parmi les fils d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Tu n\'apporteras ni le don fait à une prostituée, ni le prix payé à un chien, dans la maison de l\'Éternel, ton Dieu, ensuite d\'un vœu quelconque, car l\'un et l\'autre sont l\'abomination de l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Tu n\'exigeras point d\'intérêts de ton frère, ni intérêt d\'argent, ni intérêt de denrées, ni intérêt de rien de ce qui se prête à intérêts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Mais de l\'homme du dehors tu pourras exiger des intérêts, et non pas de ton frère, afin que l\'Éternel, ton Dieu, te bénisse dans tout ce que tu entreprendras dans le pays dont tu viens faire la conquête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Quand tu fais un vœu à l\'Éternel, ton Dieu, ne tarde pas à l\'accomplir; car l\'Éternel, ton Dieu, le réclamera de toi, et tu te chargerais d\'un péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Si tu t\'abstiens de vœux, tu ne te charges point d\'un péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Tiens ce que tes lèvres ont exprimé, et agis conformément au vœu que tu as fait librement à l\'Éternel, ton Dieu, à ce que ta bouche a prononcé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Si tu entres dans la vigne de ton prochain, tu peux manger des raisins à souhait, à te rassasier, mais n\'en mets point dans ton panier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Si tu entres dans le champ de ton prochain, tu peux cueillir des épis avec la main, mais ne fais pas jouer la faucille dans la moisson de ton prochain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Un homme prend une femme et devient son mari, mais il arrive qu\'elle n\'entre pas en grâce auprès de lui, parce qu\'il a découvert en elle quelque chose de repoussant, il écrit pour elle une lettre de divorce, la lui remet en main et la renvoie de sa maison;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'elle quitte sa maison et part; puis elle devient la femme d\'un autre mari;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'ce dernier mari la prend en haine, et écrit pour elle une lettre de divorce, et la lui remet en main et la renvoie de sa maison; ou bien l\'homme qui l\'avait épousée en dernier lieu, vient à mourir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'dans ce cas le premier mari qui l\'a répudiée, ne pourra la reprendre pour femme après qu\'elle se sera souillée, car c\'est l\'abomination de l\'Éternel, et tu ne dois pas entacher de péché le pays que l\'Éternel, ton Dieu, te donne en propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Un nouveau marié ne fera point la campagne avec l\'armée; on ne lui imposera aucune charge quelconque; il sera exempté pendant un an pour sa maison, afin qu\'il puisse réjouir la femme qu\'il a épousée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'L\'on ne se nantira pas du moulin et de la meule; car ce serait se nantir de la vie même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Si quelqu\'un est surpris volant un homme, l\'un de ses frères, l\'un des enfants d\'Israël, et l\'employant comme esclave et le vendant, ce voleur-là mourra. Ote ainsi le mal du milieu de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Prends garde à l\'affection de la lèpre, afin d\'être bien attentif à faire tout ce que vous enjoindront les Prêtres, les Lévites. Ayez soin de vous conformer à ce que je leur ai prescrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Rappelle-toi ce que l\'Éternel, ton Dieu, a fait à Marie, pendant la route lors de votre sortie de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Lorsque tu feras à ton frère un prêt quelconque, tu n\'entreras point dans sa maison, pour t\'y saisir d\'un gage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'tu resteras dehors, et celui à qui tu fais le prêt, t\'apportera le gage dehors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Et si c\'est un homme pauvre, tu ne te coucheras pas ayant encore son gage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Tu lui rendras le gage au coucher du soleil, afin qu\'il ait son manteau pour se coucher, et qu\'il te bénisse; et cela te sera compté comme justice devant l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Ne frustre pas le mercenaire pauvre et indigent, d\'entre tes frères ou les étrangers qui seront dans ton pays, dans tes Portes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Donne-lui son salaire à son jour, et que le soleil ne se couche pas sans qu\'il l\'ait; car il est pauvre, et c\'est le souhait de son âme, de peur qu\'il ne réclame contre toi auprès de l\'Éternel, et que tu ne te charges d\'un péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Les pères ne seront pas mis à mort pour les fils, ni les fils pour les pères: chacun sera mis à mort pour son propre péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Ne fais pas céder le droit de l\'étranger, ni de l\'orphelin, et ne prends pas en gage la robe de la veuve,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'te souvenant que tu as été esclave en Egypte, et que l\'Éternel, ton Dieu, t\'en a racheté; c\'est pourquoi je t\'enjoins d\'accomplir ce précepte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Lorsque tu moissonneras tes blés dans ton champ, si tu oublies une gerbe au champ, ne reviens pas la prendre; qu\'elle soit pour étranger, l\'orphelin et la veuve, afin que l\'Éternel, ton Dieu, te bénisse dans tout le travail de tes mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Lorsque tu secoueras tes oliviers, ne fais pas après toi fouiller dans les rameaux; que ce soit pour l\'étranger, l\'orphelin et la veuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Lorsque tu vendangeras ta vigne, tu ne grappilleras pas derrière toi; que ce soit pour l\'étranger, l\'orphelin et la veuve:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'souviens-toi que tu as été esclave dans le pays d\'Egypte; c\'est pourquoi je t\'enjoins d\'accomplir ce précepte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'S\'il s\'élève un différend entre des hommes, ils se présenteront au Tribunal, pour qu\'on les juge, et que l\'on déclare innocent l\'innocent, et coupable le coupable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Et si le coupable mérite des coups, le Juge le fera étendre par terre et battre sous ses yeux d\'un nombre de coups suffisant en raison de sa culpabilité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Il lui fera donner quarante coups, pas plus, de peur que s\'il y fait ajouter des coups en grand nombre, ton frère ne soit avili devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Tu n\'emmusèleras pas le bœuf, quand il foule le grain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Si des frères demeurent dans un même lieu, ou que l\'un d\'eux meure sans laisser de fils, la femme du frère mort ne se mariera point au dehors à un étranger; son beau-frère s\'approchera d\'elle, et la prendra pour sa femme, et remplira envers elle le devoir du beau-frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Et ce cas échéant, le premier-né qu\'elle enfantera, succédera au nom du frère défunt, afin que son nom ne disparaisse pas d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Mais si l\'homme ne se soucie pas d\'épouser sa belle-sœur, sa belle-sœur se présentera, à la Porte devant les Anciens et dira: Mon beau-frère se refuse à faire revivre le nom de son frère en Israël; il ne veut pas remplir envers moi le devoir du Lévirat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Alors les Anciens de sa ville le citeront, et ils lui parleront;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'et s\'il persiste et dit: Je ne me soucie pas de l\'épouser; sa belle-sœur s\'avancera, vers lui, devant les yeux des Anciens, et lui détachera sa sandale du pied, et crachera en face de lui; puis prenant la parole elle dira: Ainsi soit fait à l\'homme qui n\'édifie pas la maison de son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Et en Israël on le désignera de ce nom: Maison du déchaussé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Si des hommes ont entre eux une rixe, l\'un avec l\'autre, et que la femme de l\'un accoure pour tirer son mari des mains de celui qui le bat, et qu\'étendant la main elle saisisse celui-ci par les parties honteuses,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'coupe-lui la main, et cela sans pitié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Tu n\'auras pas dans ta bourse double pierre à peser, une grosse et une petite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Tu n\'auras pas dans ta maison double épha, un grand et un petit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Aie des pierres d\'un poids complet et juste, et un épha d\'une capacité complète et juste, afin que tes jours se prolongent dans le pays que l\'Éternel, ton Dieu, te donne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Car quiconque le fait, quiconque fraude, est l\'abomination de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Rappelle-toi ce que t\'a fait Amalek pendant le trajet lors de votre sortie d\'Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'comment il t\'a attaqué sur la route, est tombé sur ton arrière-garde, sur toute la troupe débile qui se traînait après toi, toi-même étant épuisé et las, et comment il n\'eut aucune crainte de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Et lorsque l\'Éternel, ton Dieu, t\'aura donné le repos et t\'aura débarrassé de tous les ennemis de tes alentours dans le pays que l\'Éternel, ton Dieu, te donne en propriété pour le conquérir, tu mettras fin à la mémoire d\'Amalek sous les Cieux. Ne l\'oublie pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Lorsque ta seras entré dans le pays que l\'Éternel, ton Dieu, te donne en propriété et que tu l\'auras conquis, et t\'y seras établi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'tu prendras des prémices de tous les produits du sol, que tu retireras de ton pays à toi donné par l\'Éternel, ton Dieu; et tu les mettras dans une corbeille, et te rendras au lieu que choisira l\'Éternel, ton Dieu, pour y fixer son nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'puis tu t\'adresseras au Prêtre qui existera à cette époque, et tu lui diras: Je déclare aujourd\'hui à l\'Éternel, ton Dieu, être entré dans le pays que l\'Éternel a juré à nos pères de nous donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Et le Prêtre recevra la corbeille de ta main et la déposera devant l\'Autel de l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Alors tu prendras la parole et diras devant l\'Éternel, ton Dieu: Mon père était un Araméen nomade, et il descendit en Egypte, et y séjourna n\'ayant que peu de gens avec lui, et là il est devenu une grande, puissante et nombreuse nation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Et les Égyptiens nous maltraitèrent et nous opprimèrent, et nous soumirent à un dur esclavage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'et nous criâmes à l\'Éternel, Dieu de nos pères, et l\'Éternel entendit notre voix et vit notre misère et notre peine et notre oppression.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Et l\'Éternel nous retira de l\'Egypte d\'une main forte et avec un bras étendu, et au moyen d\'une grande terreur et de signes et de prodiges;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'et Il nous a fait arriver en ce lieu, et nous a donné ce pays, pays découlant de lait et de miel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Et maintenant, voici, j\'apporte les prémices des produits du sol que tu m\'as donné, Éternel. Puis dépose-les devant l\'Éternel, ton Dieu, et adore l\'Éternel, ton Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'et réjouis-toi de tous les biens que t\'a donnés à toi et à ta maison l\'Éternel, ton Dieu, toi et le Lévite et l\'étranger qui sera chez toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Quand tu auras achevé de délivrer toute la dîme de ton revenu, la troisième année, année de cette dîme, et que tu auras donné au Lévite, à l\'étranger, à l\'orphelin et à la veuve de quoi manger et se rassasier dans tes Portes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'tu diras devant l\'Éternel ton Dieu: J\'ai ôté de ma maison la chose sacrée, et l\'ai donnée au Lévite, à l\'étranger, à l\'orphelin et à la veuve et me conformant en tout point au commandement que tu m\'as prescrit, je n\'ai ni transgressé, ni oublié tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Je n\'en ai point mangé pendant mon deuil, et n\'en ai rien soustrait pour un [usage] immonde, et n\'en ai rien donné pour un repas mortuaire; j\'ai été docile à la voix de l\'Éternel, mon Dieu, j\'ai agi en tout comme tu me l\'as prescrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Abaisse tes regards de ta demeure sainte, des Cieux, et bénis ton peuple d\'Israël et le sol que tu nous as donné à teneur du serment que tu fis à nos pères, pays découlant de lait et de miel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'En ce jour l\'Éternel, ton Dieu, te commande de mettre en pratique ces statuts et ces lois: applique-toi donc à les pratiquer de tout ton cœur et de toute ton âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Aujourd\'hui tu as obtenu de l\'Éternel la déclaration qu\'il sera ton Dieu, et que tu dois marcher dans ses voies et garder ses statuts, ses commandements et ses lois, et obéir à sa voix;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'et aujourd\'hui l\'Éternel t\'a fait promettre que tu seras son peuple particulier, comme Il te l\'a promis, et que tu garderas tous ses commandements,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'et qu\'il te rendra supérieur à toutes les nations qu\'il a faites, en gloire, et en renom et en magnificence, et que tu seras un peuple consacré à l\'Éternel, ton Dieu, comme Il l\'a promis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Et Moïse et les Anciens d\'Israël intimèrent au peuple cet ordre: Gardez la totalité du commandement que je vous prescris en ce jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Au jour où vous passerez le Jourdain pour entrer dans le pays que l\'Éternel, ton Dieu, te donne, tu érigeras de grandes pierres et les enduiras de chaux et');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'tu y graveras toutes les paroles de cette loi, quand tu seras passé, afin que tu parviennes au pays que l\'Éternel, ton Dieu, te donne, pays découlant de lait et de miel, comme l\'Éternel, Dieu de tes pères, te l\'a promis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Après le passage du Jourdain, vous ferez donc l\'érection de ces pierres, que je vous ordonne aujourd\'hui, sur le mont Ebal et vous les enduirez de chaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Et tu bâtiras là un autel à l\'Éternel, ton Dieu, et un autel de pierres sur lesquelles tu ne porteras pas le fer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'c\'est de pierres brutes que tu bâtiras l\'Autel de l\'Éternel, ton Dieu; et tu y offriras des holocaustes à l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Et tu feras des sacrifices pacifiques; et tu mangeras là et te réjouiras devant l\'Éternel, ton Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'et tu graveras sur les pierres toutes les paroles de cette Loi, en caractères nets.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Alors Moïse et les Prêtres, les Lévites, parlèrent à tout Israël en ces termes: Israël, fais silence et sois-attentif! Aujourd\'hui tu es devenu le peuple de l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Obéis donc à la voix de l\'Éternel, ton Dieu, et pratique ses commandements et ses statuts que je te prescris aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Et ce jour-là Moïse donna cet ordre au peuple:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Ceux-ci se placeront, pour bénir le peuple, sur le mont Garizim, quand vous aurez passé le Jourdain: Siméon et Lévi et Juda et Issaschar et Joseph et Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Et ceux-ci se placeront, pour prononcer la malédiction, sur le mont Ebal: Ruben, Gad, et Asser et Zabulon, Dan et Nephthali.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Puis les Lévites prendront la parole et diront à tous les hommes d\'Israël d\'une voix élevée:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Maudit soit l\'homme qui fait une image sculptée ou jetée en fonte, abomination de l\'Éternel, œuvre de main d\'artiste, et l\'érige en secret. Et tout le peuple répondra et dira: Ainsi soit-il!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Maudit celui qui avilit son père et sa mère. Et tout le peuple dira: Ainsi soit-il!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Maudit celui qui déplace la borne de son prochain. Et tout le peuple dira: Ainsi soit-il!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Maudit celui qui fourvoie l\'aveugle en chemin. Et tout le peuple dira: Ainsi soit-il!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Maudit celui qui fait plier le droit de l\'étranger, de l\'orphelin et de la veuve. Et tout le peuple dira,: Ainsi soit-il!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Maudit celui qui partage le lit de la femme de son père; car il a soulevé la couverture de son père. Et tout le peuple dira: Ainsi soit-il!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Maudit celui qui a commerce avec un animal quelconque. Et tout le peuple dira: Ainsi soit-il!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Maudit celui qui partage le lit de sa sœur, fille de son père ou fille de sa mère. Et tout le peuple dira: Ainsi soit-il!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Maudit celui qui partage le lit de sa belle-mère. Et tout le peuple dira: Ainsi soit-il!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Maudit celui qui frappe son prochain clandestinement. Et tout le peuple dira: Ainsi soit-il!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Maudit celui qui accepte des présents pour attenter à une vie, au sang innocent. Et tout le peuple dira: Ainsi soit-il!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Maudit celui qui ne met pas à effet les paroles de cette Loi pour la pratiquer. Et tout le peuple dira: Ainsi soit-il!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Et si tu es docile à la voix de l\'Éternel, ton Dieu, pour t\'appliquer à pratiquer tous ses commandements que je te prescris en ce jour, l\'Éternel, ton Dieu, te donnera la prééminence sur toutes les nations de la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'et toutes ces bénédictions t\'arriveront et viendront te trouver, pourvu que tu sois docile à la voix de l\'Éternel, ton Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'tu seras béni à la ville et tu seras béni aux champs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'tu seras béni dans la fécondité de tes flancs, dans la fécondité de ton sol, et dans la fécondité de ton bétail, la progéniture de tes vaches et les portées de tes brebis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'La bénédiction remplira tes paniers et ta maie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Tu seras béni, quand tu sortiras, béni quand tu entreras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'L\'Éternel te livrera défaits tes ennemis levés contre toi; par une seule route ils s\'avanceront contre toi et par sept routes ils s\'enfuiront devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Au commandement de l\'Éternel tu auras la bénédiction dans tes greniers, et dans toutes tes entreprises, et Il te bénira dans le pays que l\'Éternel, ton Dieu, te donne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'L\'Éternel te constituera son peuple saint, comme Il te l\'a juré, si tu gardes les commandements de l\'Éternel, ton Dieu, et si tu marches dans ses voies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Et tous les peuples de la terre verront que tu es appelé du nom de l\'Éternel, et ils te craindront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Et l\'Éternel te comblera de biens par la fécondité de tes flancs, et par la fécondité de ton bétail et par la fécondité de ton sol dans le pays que l\'Éternel a juré à tes pères de te donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'L\'Éternel t\'ouvrira son trésor d\'abondance, le Ciel, pour te donner à son époque la pluie propre à ton pays et bénir tout le travail de ta main; et tu prêteras à beaucoup de nations, mais n\'emprunteras pas toi-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Et l\'Éternel fera de toi la tête et non pas la queue, et tu ne seras qu\'en haut et non point en bas, si tu obéis aux commandements de l\'Éternel, ton Dieu, que je te prescris en ce jour, pour les garder et les pratiquer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'et si tu ne t\'écartes de tous les ordres que je vous intime en ce jour, ni à droite ni à gauche, pour suivre d\'autres dieux et les servir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Mais si tu n\'es pas docile à la voix de l\'Éternel, ton Dieu, pour t\'appliquer à la pratique de tous ses commandements et ses statuts que je te prescris en ce jour, toutes ces malédictions s\'accompliront pour toi, et t\'atteindront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Tu seras maudit dans la ville, et maudit dans les champs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Maudits seront tes paniers et ta maie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Maudit seras-tu quant à la fécondité de tes flancs, à la fécondité de ton sol, à la progéniture de tes vaches et aux portées de tes brebis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'maudit lorsque tu entreras, maudit lorsque tu sortiras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'L\'Éternel enverra contre toi la malédiction, l\'alarme et la ruine à toutes tes entreprises que tu formeras, jusqu\'à ce que tu sois détruit et promptement perdu, à cause de la méchanceté de tes actions, pour m\'avoir abandonné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'L\'Éternel mettra la peste à ta poursuite, jusqu\'à ce qu\'il t\'ait exterminé du pays dont tu viens faire la conquête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'L\'Éternel t\'affligera de marasme et de fièvre, et d\'inflammation, de sécheresse et de brûlure, de gangrène et de nielle, qui s\'acharneront sur toi jusqu\'à ce que tu périsses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Et le ciel qui est au-dessus de ta tête, sera d\'airain, et la terre que tu as sous les pieds, de fer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Au lieu de pluie sur ton pays l\'Éternel enverra de la poussière et du sable qui tomberont du ciel jusqu\'à ce que tu sois détruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'L\'Éternel te livrera défait à tes ennemis; par une route unique tu t\'avanceras contre eux, et par sept routes tu t\'enfuiras devant eux, et tu seras en butte aux vexations de tous les royaumes, de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Et ton cadavre sera la proie de tous les oiseaux des Cieux et de toutes les bêtes de la terre, que personne n\'effarouchera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'L\'Éternel t\'affligera de l\'ulcère d\'Egypte, et de tumeurs, et de dartres, et de gale, dont tu ne pourras guérir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'L\'Éternel t\'affligera de délire et de cécité, et d\'égarement d\'esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Et tu iras à tâtons en plein midi, comme l\'aveugle tâtonne dans l\'obscurité, et tu ne trouveras pas le succès sur ta route; tu ne seras qu\'opprimé et pillé tous les jours, et tu n\'auras aucun libérateur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Tu te fianceras à une femme et un autre homme entrera dans son lit; tu bâtiras une maison et tu ne l\'habiteras pas; tu planteras une vigne et tu n\'en goûteras pas les fruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Ton bœuf sera égorgé sous tes yeux, et tu n\'en mangeras pas; ton âne sera enlevé à ta face, et ne te reviendra pas; tes brebis seront livrées à tes ennemis, et tu n\'auras aucun auxiliaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Tes fils et tes filles seront donnés à un autre peuple, tes yeux le voyant et se consumant à regarder tout le jour du côté où ils sont; et tu n\'auras pas la force en main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Le produit de ton sol et de tout ton labeur sera consommé par un peuple non connu de toi, et tu ne seras qu\'opprimé et écrasé tous les jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Tu tomberas en démence à l\'aspect de ce que tu verras de tes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'L\'Éternel t\'affligera aux genoux et aux jambes d\'ulcères malins et incurables, de la plante des pieds au sommet de la tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'L\'Éternel te chassera toi et ton roi que tu auras préposé sur toi, chez une nation inconnue à toi et à tes pères; et là, tu serviras d\'autres dieux, du bois et de la pierre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Et tu exciteras la stupeur, tu passeras en proverbe et donneras lieu aux sarcasmes chez tous les peuples où l\'Éternel te mènera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Tu ensemenceras abondamment le terrain et tu récolteras peu; car la sauterelle le broutera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Tu planteras et cultiveras des vignes, mais tu ne boiras ni ne récolteras de vin, car les vers les consumeront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Tu auras des oliviers dans tout ton territoire, mais tu ne t\'oindras pas d\'huile, car tes oliviers se dépouilleront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Tu engendreras des fils et des filles, mais ils ne seront pas à toi, car ils iront en captivité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'De tous tes arbres, et des fruits de ton sol le grillon s\'emparera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'L\'étranger qui sera parmi vous s\'élèvera au-dessus de toi toujours plus haut, et toi, tu descendras toujours plus bas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'C\'est lui qui te prêtera, et toi, tu ne lui prêteras pas; il deviendra la tête et tu deviendras la queue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Et toutes ces malédictions s\'accompliront sur toi et te poursuivront et t\'atteindront jusqu\'à ce que tu sois détruit, pour n\'avoir pas obéi à la voix de l\'Éternel, ton Dieu, en gardant ses commandements et ses statuts qu\'il t\'a prescrits,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'et elles resteront sur toi et sur ta postérité comme un signe et un exemple éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Pour n\'avoir pas servi l\'Éternel, ton Dieu, avec joie et de bon cœur au milieu de l\'abondance de toutes choses,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'tu serviras tes ennemis que l\'Éternel enverra contre toi, souffrant de la faim, de la soif, du dénuement et de la disette de toutes choses, et il chargera ton col d\'un joug de fer jusqu\'à ce qu\'il t\'ait détruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'L\'Éternel fera lever contre toi un peuple lointain, de l\'extrémité de la terre, rapide comme l\'aigle qui vole, un peuple dont tu n\'entendras pas la langue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'peuple au visage farouche, sans respect pour le vieillard, sans pitié pour le jeune homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Il dévorera la progéniture de tes bestiaux et les fruits de ton sol jusqu\'à ce que tu sois détruit, ne te laissant ni blé, ni moût, ni huile, ni la progéniture de tes vaches ni les portées de tes brebis jusqu\'à ce qu\'il t\'ait fait périr:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'il t\'assiégera dans toutes tes Portes jusqu\'à la chute de tes hautes et fortes murailles sur lesquelles tu te fies, dans tout ton pays, et il t\'assiégera dans toutes tes Portes, dans tout ton pays que t\'a donné l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Et, dans la détresse et l\'angoisse où te réduiront tes ennemis, tu te nourriras du fruit de tes entrailles, de la chair de tes fils et de tes filles que t\'aura donnés l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Le plus amolli de tes hommes, et le plus délicat regardera de mauvais œil son frère et la femme qui est entre ses bras, et ceux de ses fils qui auront survécu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'pour ne pas partager avec l\'un d\'eux la chair de ses fils dont il se nourrira, parce qu\'on ne lui aura rien laissé dans la détresse et l\'angoisse où t\'auront réduit tes ennemis dans toutes tes Portes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'La plus amollie de tes femmes et la plus délicate qui ne tentait pas de poser la plante de son pied sur la terre par excès de délicatesse et de mollesse, regardera de mauvais œil le mari qui est entre ses bras, et son fils et sa fille,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'pour ne point partager le placenta sorti d\'entre ses pieds, et les enfants dont elle est accouchée; car elle les mangera par disette de toutes choses en secret, dans la détresse et l\'angoisse où l\'auront réduite tes ennemis dans tes Portes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Si tu ne t\'appliques à pratiquer tous les préceptes de cette Loi transcrits dans ce livre, pour craindre ce magnifique et redoutable Nom, l\'Éternel, ton Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'l\'Éternel vous frappera de fléaux extraordinaires, toi et ta postérité, de fléaux grands et soutenus, et de maladies malignes et persistantes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'et Il ramènera sur toi toutes les infirmités de l\'Egypte qui te font peur, afin qu\'elles s\'attachent à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Toutes les maladies et toutes les plaies aussi, non consignées dans le volume de cette Loi, l\'Éternel les attirera sur toi, jusqu\'à ce que tu sois détruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Et vous survivrez en petit nombre, au lieu d\'être comme maintenant aussi nombreux que les étoiles du ciel, parce que tu n\'auras pas obéi à la voix de l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Et de même que l\'Éternel mettait sa joie à votre égard à vous faire du bien et à vous agrandir, de même l\'Éternel mettra sa joie à votre égard à vous perdre et à vous détruire, et vous serez arrachés du pays dont tu viens faire la conquête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Et l\'Éternel te disséminera parmi tous les peuples d\'un bout de la terre à l\'autre, et là tu serviras d\'autres dieux inconnus à toi et à tes pères, du bois et de la pierre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Et parmi ces peuples tu ne seras pas tranquille, tu n\'auras pas où reposer la plante de tes pieds, et l\'Éternel t\'y donnera un cœur inquiet, des yeux qui s\'éteignent, une âme qui se consume.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Et devant toi ta vie sera toujours en suspens, tu seras alarmé la nuit et le jour, et ne seras pas sûr de vivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Le matin tu diras: Ah! si le soir était là! et le soir tu diras: Ah! si le matin était là! par l\'effet des alarmes qui alarmeront ton cœur, et du spectacle que tu verras de tes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Et l\'Éternel te ramènera en Egypte sur des navires, par le chemin duquel je te disais: tu ne le reverras plus, et là vous vous vendrez à vos ennemis comme esclaves et comme servantes; et il n\'y aura point d\'acheteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Voici les termes de l\'alliance que l\'Éternel ordonna à Moïse de conclure avec les enfants d\'Israël dans le pays de Moab, outre l\'alliance qu\'il avait conclue avec eux en Horeb.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Et Moïse convoqua tous les Israélites et il leur dit: Vous avez vu tout ce qu\'a fait l\'Éternel sous tes yeux dans le pays d\'Egypte à Pharaon et à tous ses serviteurs et à tout son pays,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'les grandes épreuves que vos yeux ont vues, ces grands signes et prodiges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Mais jusques aujourd\'hui l\'Éternel ne vous a pas donné un cœur pour sentir, des yeux pour voir, des oreilles pour entendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Et pendant quarante ans, je vous ai conduits dans le désert; vos habits ne se sont point usés sur vous, ni vos sandales à vos pieds;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'vous n\'avez pas mangé de pain et n\'avez bu ni vin ni cervoise, afin que vous comprissiez que moi, l\'Éternel, je suis votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Et vous êtes arrivés en ce lieu. Alors, Sihon, roi de Hesbon, et Og, roi de Basan, se sont avancés contre nous pour nous attaquer, et nous les avons battus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Et nous nous sommes emparés de leur pays et l\'avons donné en propriété aux Rubénites, et aux Gadites et à la demi-Tribu de Manassé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Gardez donc les paroles de cette alliance, et pratiquez-les, afin de réussir dans tout ce que vous entreprendrez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Vous voilà comparaissant aujourd\'hui tous devant l\'Éternel, votre Dieu, vos Chefs, vos Tribus, vos Anciens et vos Officiers, tous les hommes d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'vos enfants, vos femmes et ton étranger qui est dans ton camp, depuis celui qui coupe ton bois à celui qui puise ton eau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'pour passer dans l\'alliance de l\'Éternel, ton Dieu, et sous sa sanction que l\'Éternel, ton Dieu, solennise avec toi en ce jour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'pour te constituer aujourd\'hui son peuple tandis qu\'il sera ton Dieu, comme Il te l\'a promis, et comme Il en a fait le serment à tes pères, à Abraham, à Isaac et à Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Et ce n\'est pas avec vous seuls que je conclus cette alliance et ce pacte juré,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'c\'est avec ceux qui sont ici aujourd\'hui comparaissant avec nous devant l\'Éternel, notre Dieu, et avec ceux qui ne sont pas ici avec nous aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Car vous savez comment nous avons séjourné dans le pays d\'Egypte, et comment nous avons passé au milieu des nations que vous avez traversées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'et vous avez vu les horreurs de leur culte, et leurs idoles de bois et de pierre, d\'argent et d\'or qui étaient chez eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Ayez peur qu\'il y ait parmi vous homme ou femme ou famille ou Tribu dont le cœur se détourne aujourd\'hui de l\'Éternel, notre Dieu, pour aller se mettre au service des dieux de ces nations-là; ayez peur qu\'il y ait chez vous quelque racine produisant poison ou absinthe!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Et dans le cas où, à l\'ouïe des termes de cette sanction, quelqu\'un se promettrait en son cœur un sort heureux, en disant: Je serai sain et sauf quoique je veuille marcher suivant la malice de mon cœur et en amenant ainsi la ruine du sol abreuvé et du sol altéré,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'l\'Éternel ne voudra pas lui pardonner; mais pour lors le courroux de l\'Éternel et sa jalousie s\'allumeront contre cet homme-là, et sur lui reposera toute la malédiction consignée dans ce livre-ci, et l\'Éternel effacera son nom de dessous les Cieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'et l\'Éternel le séparera, pour le perdre, de toutes les Tribus d\'Israël, suivant toutes les malédictions de l\'alliance transcrites dans ce volume de la Loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Et la génération suivante, vos fils qui s\'élèveront après vous, et l\'étranger venu d\'un pays lointain, diront à la vue du désastre de ce pays et des maux que lui aura infligés l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'du soufre et du sel et de l\'embrasement de tout son sol qui ne sera plus ensemencé, ne produira plus, où nulle plante ne croîtra, d\'un bouleversement pareil à celui de Sodome et de Gomorrhe, d\'Adema et de Tseboïm que l\'Éternel bouleversa dans sa colère et sa fureur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'tous les peuples demanderont: Pourquoi l\'Éternel a-t-Il ainsi traité ce pays-là? pourquoi l\'embrasement de cette grande colère?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Et l\'on répondra: Parce qu\'ils ont abandonné l\'alliance de l\'Éternel, Dieu de leurs pères, qu\'il avait conclue avec eux, lorsqu\'il les retira du pays d\'Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'et ils sont allés se mettre au service d\'autres dieux et les adorer, dieux qu\'ils ne connaissaient pas, et qu\'il ne leur avait pas donnés en partage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'c\'est alors que la colère de l\'Éternel s\'est allumée contre ce pays pour faire fondre sur lui toutes les malédictions consignées dans ce livre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'et l\'Éternel les a arrachés de leur pays avec courroux, colère et grande irritation et les a jetés dans un autre pays [comme il arrive] aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Les choses cachées sont à l\'Éternel, notre Dieu, mais les choses révélées sont à nous et à nos enfants à perpétuité pour que nous mettions en pratique toutes les paroles de cette Loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Mais quand s\'accompliront pour toi toutes ces paroles, la bénédiction et la malédiction que je mets devant toi, et que tu les rappelleras dans ton cœur au milieu de toutes les nations chez lesquelles l\'Éternel, ton Dieu, t\'aura banni,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'et que tu reviendras à l\'Éternel, ton Dieu, et obéiras à sa voix en tout ce que je te prescris aujourd\'hui, toi et tes fils, de tout ton cœur et de toute ton âme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'alors l\'Éternel, ton Dieu, ramènera tes captifs et prendra pitié de toi, et de nouveau vous recueillera du milieu de tous les peuples, où l\'Éternel, ton Dieu, t\'aura disséminé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Quand tes exilés seraient à l\'extrémité de l\'horizon, de là l\'Éternel, ton Dieu, te recueillera, et de là Il te retirera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Et l\'Éternel, ton Dieu, te ramènera dans le pays possédé par tes pères et possédé par toi, et Il te fera du bien et te rendra plus nombreux que tes pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Et l\'Éternel, ton Dieu, circoncira ton cœur, et le cœur de ta race pour que tu aimes l\'Éternel, ton Dieu, de tout ton cœur et de toute ton âme, afin que tu vives.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Et l\'Éternel, ton Dieu, rejettera toutes ces malédictions sur tes ennemis et sur les adversaires qui te persécutent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'De ton côté tu reviendras à obéir à la voix de l\'Éternel, et à pratiquer tous ses commandements que je te prescris en ce jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Et l\'Éternel, ton Dieu, accompagnera de l\'abondance tout le travail de tes mains, la fécondité de tes flancs, la fécondité de ton bétail et la fécondité de ton sol, pour te faire prospérer, car l\'Éternel retrouvera sa joie dans ton bonheur, comme Il trouvait sa joie dans celui de tes pères;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'pourvu que tu obéisses à la voix de l\'Éternel, ton Dieu, en gardant ses commandements et ses statuts consignés dans ce livre de la Loi; pourvu que tu reviennes à l\'Éternel, ton Dieu, de tout ton cœur et de toute ton âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Car ce commandement que je te prescris en ce jour, ne passe point ta portée, et n\'est pas à grande distance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'il n\'est pas au ciel pour que tu dises: Qui montera pour nous au ciel et nous l\'en rapportera, et nous l\'exposera pour que nous l\'accomplissions?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Il n\'est pas au delà de la mer, pour que tu dises: Qui traversera pour nous la mer et nous l\'en rapportera, et nous l\'exposera pour que nous l\'accomplissions?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Mais cette parole est tout près de toi, dans ta bouche et dans ton cœur pour que tu l\'accomplisses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Vois! j\'ai mis aujourd\'hui devant toi la vie et le bien, la mort et le mal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'en te prescrivant aujourd\'hui d\'aimer l\'Éternel, ton Dieu, de marcher dans ses voies et de garder ses commandements et ses statuts et ses lois, afin que tu vives et t\'accroisses et que l\'Éternel, ton Dieu, te bénisse dans le pays dont tu viens faire la conquête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Mais si ton cœur se détourne et si tu désobéis, et si tu te laisses aller à adorer d\'autres dieux et à les servir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'je vous déclare aujourd\'hui que vous êtes perdus; vous n\'aurez pas de longs jours dans le pays dont après le passage du Jourdain tu viens faire la conquête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'J\'en prends aujourd\'hui à témoin contre vous les Cieux et la terre: j\'ai mis devant toi la vie et la mort, la bénédiction et la malédiction; choisis donc la vie afin que tu vives, toi et ta race,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'en aimant l\'Éternel, ton Dieu, en obéissant à sa voix, en t\'attachant à lui (car Il est ta vie et prolongera tes jours), en demeurant dans le pays que l\'Éternel a juré à tes pères, à Abraham, à Isaac et à Jacob, de leur donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Et Moïse alla et adressa ces paroles à tous les Israélites');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'et leur dit: Je suis maintenant âgé de cent vingt ans, et je ne puis plus entrer et sortir, et l\'Éternel m\'a dit: Tu ne passeras pas ce Jourdain;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'l\'Éternel, ton Dieu, c\'est Lui qui te précédera, Lui qui exterminera devant toi ces nations pour que vous en soyez maîtres. C\'est Josué qui passera à votre tête, comme l\'Éternel l\'a annoncé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Et l\'Éternel les traitera, comme Il a traité Sihon et Og, rois des Amoréens, et leur pays qu\'il a détruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Mais quand l\'Éternel vous les livrera, traitez-les en tout point selon l\'ordre que je vous ai prescrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Soyez courageux et fermes, n\'ayez ni crainte ni peur d\'eux, car c\'est l\'Éternel, ton Dieu, qui marchera avec toi. Il ne vous fera pas défaut, ne vous abandonnera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Et Moïse appela Josué et lui dit en présence de tout Israël: Sois courageux et ferme, car c\'est toi qui entreras avec ce peuple dans le pays que l\'Éternel a juré à leurs pères de leur donner, et toi qui le leur partageras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Et c\'est l\'Éternel qui te précédera; Il sera avec toi, et ne te fera pas défaut, ne t\'abandonnera pas; sois sans crainte et sans alarmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Et Moïse mit par écrit cette Loi et la remit aux Prêtres, fils de Lévi, porteurs de l\'Arche de l\'alliance de l\'Éternel, et à tous les Anciens d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Et Moïse leur donna cette instruction: Au terme de sept ans, à l\'époque de l\'année du relâche, à la Fête des Loges,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'lorsque tout Israël viendra se présenter devant l\'Éternel, ton Dieu, dans le lieu choisi par Lui, tu donneras lecture de cette Loi devant tout Israël, à leurs oreilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Rassemble le peuple, les hommes et les femmes et les enfants et tes étrangers qui seront dans tes Portes, afin qu\'ils entendent, et qu\'ils apprennent à craindre l\'Éternel, votre Dieu, et à s\'appliquer à la pratique de tous les préceptes de cette Loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Et vos fils qui ignorent, écouteront et apprendront à craindre l\'Éternel, votre Dieu, aussi longtemps que vous vivrez dans le pays dont après le passage du Jourdain vous allez faire la conquête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Et l\'Éternel dit à Moïse: Voici, le moment de ta mort approche; appelle Josué, et placez-vous dans la Tente du Rendez-vous, et je lui donnerai mes ordres. Et Moïse et Josué allèrent se placer dans la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Alors l\'Éternel apparut dans la Tente, dans une colonne de nuée; et la colonne de nuée s\'arrêta à la porte de la Tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Et l\'Éternel dit à Moïse: Voici, tu vas être couché à côté de tes pères, et ce peuple se lèvera, et se prostituera à la suite des dieux étrangers du pays dans lequel il va entrer, et il m\'abandonnera, et rompra l\'alliance que j\'ai conclue avec lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'et ma colère s\'allumera contre lui dans ce moment-là, et je l\'abandonnerai et lui cacherai ma face, et il sera livré comme proie, et atteint par beaucoup de maux et de détresses, et il dira alors: N\'est-ce pas parce que notre Dieu n\'est pas au milieu de moi, que ces maux m\'ont atteint?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Et je cacherai ma face dans ce temps-là, à cause de tout le mal qu\'il aura fait en se tournant vers des dieux étrangers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Et maintenant écrivez ce cantique, et apprends-le aux enfants d\'Israël, mets-le dans leur bouche, afin que ce cantique me serve de témoin contre les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Car je les introduirai dans le pays que j\'ai promis par serment à leurs pères, pays découlant de lait et de miel; puis ils mangeront et se rassasieront et s\'engraisseront et se tourneront vers d\'autres dieux et les serviront et me mépriseront et rompront mon alliance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'et quand alors ils seront atteints par beaucoup de maux et de détresses, que ce cantique dépose contre eux comme un témoin, car il ne doit ni être oublié, ni cesser d\'être dans la bouche de leurs descendants. En effet, je connais leurs pensées qu\'ils forment dès à présent, avant que je les aie introduits dans le pays que je leur ai promis par serment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Moïse écrivit donc ce cantique ce jour-là, et il l\'apprit aux enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Et il donna ses instructions à Josué, fils de Nun, en ces termes: Aie courage et fermeté, car c\'est toi qui introduiras les enfants d\'Israël dans le pays que je leur ai promis par serment, et Moi-même Je serai avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Et lorsque Moïse eut achevé de transcrire sur un volume les paroles de cette Loi, au complet,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Moïse fit cette injonction aux Lévites, porteurs de l\'Arche de l\'alliance de l\'Éternel:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Prenez ce Volume de la Loi et le placez à côté de l\'Arche de l\'alliance de l\'Éternel, votre Dieu, et qu\'il y serve de témoin contre vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Car je connais ton caractère rebelle, et la roideur de ton col; voici, pendant que je suis encore vivant à vos côtés, déjà vous vous montrez rebelles à l\'Éternel: combien plus le serez-vous après ma mort!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Assemblez auprès de moi tous les Anciens de vos Tribus, et vos Officiers, afin que je redise à leurs oreilles ces choses-là, et que je prenne à témoin contre eux les Cieux et la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Car je sais qu\'après ma mort vous vous perdrez et quitterez la voie que je vous ai tracée, et que les maux fondront sur vous dans les temps à venir, parce que vous ferez ce qui est mal aux yeux de l\'Éternel pour le provoquer par l\'œuvre de vos mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Moïse prononça donc aux oreilles de toute l\'Assemblée d\'Israël les paroles de ce cantique dans leur entier:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Cieux, écoutez! et je parlerai, et que la terre entende les paroles de ma bouche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Que mes leçons s\'épanchent comme la pluie, que ma parole coule comme la rosée, comme l\'ondée sur la verdure, et comme les gouttes menues sur la plante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Car je proclame le Nom de l\'Éternel: magnifiez notre Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Il est le Rocher! son œuvre est parfaite; car toutes ses voies sont équité; Dieu fidèle et sans fraude, Il est juste, Il est droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Elle a forfait envers Lui, perdu par ses vices le rang de ses enfants, la race pervertie et trompeuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Payez-vous ainsi l\'Éternel de retour, peuple insensé et dénué de sagesse? N\'est-Il pas ton père, ton créateur? Il t\'a formé, et t\'a consolidé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Rappelle-toi les jours d\'autrefois, étudiez les années de tous les âges! Interroge ton père et il t\'instruira, tes Anciens, et ils te parleront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Quand le Très-Haut assignait leurs lots aux nations, et quand Il séparait les fils d\'Adam, alors Il plaça les bornes des Tribus d\'après le nombre des fils d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Car le lot de l\'Éternel, c\'est son peuple, et Jacob est sa portion d\'héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Il le trouva sur le sol de la steppe, au désert des hurlements et de la solitude; alors Il l\'entoura et s\'occupa de lui, et le garda comme la prunelle de Ses yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Tel l\'aigle fait lever sa couvée, plane autour de ses aiglons, déploie ses ailes et les prend, et les porte sur ses fortes pennes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'ainsi l\'Éternel seul le conduisit: Il n\'avait pas avec lui de Dieu étranger;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Il lui fit franchir les hauteurs du pays, et il eut pour aliments les fruits des campagnes; Il l\'allaita du miel de la roche, et de l\'huile qui vient sur la grève rocailleuse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'de la crème des génisses, du lait des brebis, avec la graisse des agneaux, et des béliers élevés en Basan, et des boucs, avec la moelle intérieure du froment; et tu bus le vin pur, sang du raisin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Mais le peuple choyé devient gras et rétif; — te voilà engraissé, épaissi, couvert d\'embonpoint! — Il quitte Dieu, son créateur, et méprise son Rocher Sauveur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Ils allumèrent sa jalousie par un culte étranger et le provoquèrent par des abominations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Ils sacrifièrent à des maîtres: qui ne sont pas Dieu, à des dieux qu\'ils ne connaissaient pas, dieux nouveaux, venus du voisinage, que ne redoutaient pas leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Tu abandonnas le Rocher, auteur de ta naissance, et oublias Dieu qui t\'avait enfanté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'L\'Éternel le vit, et d\'indignation Il rejeta ses fils, et ses filles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'et dit: Je me cache la face à leur vue: je verrai comment ils finiront; car c\'est une race pervertie, des enfants sans foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Ils m\'ont rendu jaloux par ce qui n\'est pas Dieu, et contristé par leurs vaines idoles: je les rendrai jaloux par ce qui n\'est pas un peuple, et les contristerai par une nation insensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Car un feu s\'est allumé dans ma colère, et il embrasera jusqu\'au fond des Enfers, et dévorera la terre et ses productions, et brûlera les bases des montagnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Je veux accumuler sur eux les maux, et épuiser contre eux mes traits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Ils seront amaigris par la faim, rongés par la fièvre et par une peste venimeuse, et je lancerai contre eux la dent des bêtes féroces, en même temps que le venin des reptiles de la poudre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Au dehors l\'épée sévira, et dans les chambres, la terreur sur le jeune homme et la vierge, sur le nourrisson et le vieillard.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Je dirais: je veux les dissiper, éteindre leur mémoire parmi les hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'si je ne craignais l\'insulte des ennemis, la méprise de leurs adversaires, et leurs propos: « C\'est notre éminente main et non pas l\'Éternel qui a fait toutes ces choses. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'C\'est un peuple destitué de raison, il y a chez lui défaut d\'intelligence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'S\'ils étaient sages, ils y prendraient garde, et seraient attentifs à leur avenir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Comment est-ce qu\'un homme en poursuivrait mille, et deux, en mettraient dix mille en fuite, sinon, parce que leur Rocher les a vendus et que l\'Éternel les a livrés?...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Car leur Rocher n\'est pas pareil à notre Rocher et nos ennemis en sont juges...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'C\'est que leur vigne provient de la vigne de Sodome et des campagnes de Gomorrhe; leurs raisins sont des raisins vénéneux dont les baies sont amères;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'leur vin, c\'est le virus du dragon, et le cruel venin de l\'aspic.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Cela n\'est-il pas serré par devers moi, scellé dans mes Trésors?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'A moi la vengeance et la rétribution dans le temps où leur pied bronchera! Car le jour de leur ruine approche, et leurs destinées se précipitent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Oui, l\'Éternel punira son peuple; Mais Il prendra pitié de ses serviteurs, quand Il verra que la force s\'est évanouie, et qu\'il ne reste plus ni esclave, ni homme libre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Alors Il dira: Où sont leurs dieux, ce rocher dans lequel ils avaient confiance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'qui mangeaient la graisse de leurs victimes, et buvaient le vin de leurs libations? Qu\'ils se lèvent pour vous secourir, que ce rocher soit votre refuge!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Voyez donc que c\'est Moi, Moi qui le suis, et qu\'il n\'est aucun Dieu avec moi. Je donne et la mort et la vie; je brise et je guéris: et nul ne sauve de ma main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Car je lève ma main vers le Ciel et je dis: Aussi vrai que je vis éternellement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'quand j\'aurai aiguisé le foudre de mon glaive et que ma main s\'armera du jugement, je reverserai la vengeance sur mes ennemis, et le salaire sur ceux qui me haïssent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'j\'enivrerai mes flèches de sang, et mon glaive se repaîtra de chair, du sang des blessés et des captifs, de la tête des princes ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Triomphez, ô Tribus, vous, son peuple! Car Il venge le sang de ses serviteurs, Il reverse la vengeance sur ses ennemis et Il fait la propitiation pour son pays, pour son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Et Moïse étant venu prononça toutes les paroles de ce cantique aux oreilles du peuple, lui et Josué, fils de Nun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Et Moïse ayant achevé tous ses discours adressés à tout Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'leur dit: Prenez à cœur toutes les sommations que je vous fais en ce jour pour les intimer à vos fils afin qu\'ils s\'appliquent à garder tous les préceptes de cette Loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Car ce n\'est pas pour vous une parole vaine puisqu\'elle est votre vie, et par le moyen de cette parole vous prolongerez vos jours dans le pays dont après le passage du Jourdain vous allez faire la conquête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Et ce jour même l\'Éternel parla à Moïse en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Monte sur cette montagne d\'Abarim, au mont Nébo qui est dans le pays de Moab vis-à-vis de Jéricho, et regarde le pays de Canaan que je vais donner en propriété aux enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Et tu mourras sur la montagne où tu vas monter, et tu seras recueilli auprès de ton peuple, de même que Aaron, ton frère, est mort au mont Hor et a été recueilli auprès de son peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'parce que vous m\'avez manqué au milieu des enfants d\'Israël, aux Eaux de la Querelle en Cadès, dans le désert de Tsin, en ne manifestant pas ma sainteté au milieu des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Car devant toi tu verras le pays, mais tu n\'y entreras pas, dans ce pays que je vais donner aux enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Et voici la bénédiction par laquelle Moïse, homme de Dieu, bénit les enfants d\'Israël avant sa mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Or il dit: L\'Éternel venait de Sinaï, et pour eux Il se leva de Séir, Il resplendit du mont de Paran. Et Il sortait du milieu des saintes myriades; à sa droite était un feu, pour être leur guide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Oui, Il chérit les Tribus; tous Ses saints... sont dans Ta main, et prosternés à Tes pieds, ils ont recueilli Tes paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Moïse nous prescrivit la Loi comme héritage de l\'Assemblée de Jacob;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'et Il est Roi du peuple aimé, lorsque sont convoqués les chefs de la nation, avec les Tribus d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Que Ruben vive et qu\'il ne meure pas malgré le petit nombre de ses hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Et de Juda il parla ainsi: Écoute, Éternel, la voix de Juda et le ramène à son peuple. Que de son bras il soutienne sa querelle, et soit son secours contre ses ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Et il dit de Lévi: Tes Thummim et tes Urim sont commis à ton pieux serviteur, que tu éprouvas à Massa, avec qui Tu contestas aux eaux de Mériba;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'qui dit de son père et de sa mère: Je ne les ai point vus! qui ne reconnaît pas son frère, et ignore ses fils. Car ils sont les gardiens de ta parole, les conservateurs de ton alliance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'ils enseignent tes arrêts à Jacob et ta Loi à Israël; ils présentent l\'encens à ta narine, et les holocaustes sur ton autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Bénis, Éternel, sa vertu, et agrée l\'œuvre de ses mains. Brise les reins de ses adversaires et de ses ennemis, de peur qu\'ils ne se lèvent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'De Benjamin il dit: Chéri de l\'Éternel, il demeure confiant près de Lui; Il le couvre toujours de sa protection, et Il réside entre ses épaules.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Et de Joseph il dit: L\'Éternel bénit son pays du précieux don du Ciel, de la rosée et des ondes qui reposent sous la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'et des dons précieux, effet du soleil, et des fruits exquis des mois,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'et des premiers biens des montagnes antiques, et des dons exquis des coteaux éternels,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'et des dons exquis de la terre et de son abondance. Et que la faveur de Celui qui habitait le buisson descende sur la tête de Joseph, sur le front du prince de ses frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'A son taureau premier-né, à lui l\'honneur! Ses cornes sont pareilles aux cornes du buffle. Avec elles il refoulera les peuples ensemble jusqu\'aux limites de la terre: ce sont les myriades d\'Ephraïm, ce sont les milliers de Manassé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Et de Zabulon il dit: Réjouis-toi, Zabulon, de tes excursions, et toi, Issaschar, de tes tentes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Ils convient les Tribus à la Montagne où ils offrent de pieux sacrifices; car ils jouissent des biens qui affluent de la mer et des trésors enfouis dans le sable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'De Gad il dit: Béni soit Celui qui met Gad au large! Gad est couché comme la lionne, et déchire et le jarret et le crâne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Il a vu que la première part a été pour lui et que là, de par le Chef, son lot lui fut gardé. Cependant il se met en marche en tête du peuple, il exécute la justice de l\'Éternel, et Ses jugements, avec Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Et de Dan il dit: Dan est un jeune lion qui s\'élance de Basan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Et de Nephthali il dit: Nephthali, comblé de faveurs, et tout plein de la bénédiction de l\'Éternel, prends possession de la mer et du Midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Et d\'Asser il dit: Qu\'Asser soit béni en ayant des fils, qu\'il ait la faveur de ses frères, et qu\'il baigne ses pieds dans l\'huile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Que tes verrous soient de fer et d\'airain! que ton repos dure autant que tes jours! —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Peuple aimé, nul n\'est égal à Dieu qui s\'avance dans le Ciel pour venir à ton aide, et dans sa majesté sur les nues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Le Dieu d\'autrefois est un refuge, et ses bras éternels te soutiennent. Il chasse devant toi l\'ennemi, et Il dit: Extermine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Et Israël habite en sécurité, solitaire; à l\'œil de Jacob s\'offre un pays de blé et de moût et son ciel distille la rosée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Heureux Israël, qui est comme toi un peuple sauvé par l\'Éternel, ton bouclier secourable, et ta magnifique épée? Tes ennemis viendront te flatter, et tu fouleras leurs hauteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Et Moïse monta des plaines de Moab au mont Nébo, sommité du Pisga, vis-à-vis de Jéricho, et l\'Éternel lui fit regarder tout le pays, Galaad jusqu\'à Dan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'et tout Nephthali, et le pays d\'Ephraïm et de Manassé, et tout le pays de Juda jusqu\'à la Mer occidentale');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'et le Midi et le District [du Jourdain], la vallée de Jéricho, ville des palmiers, jusqu\'à Tsohar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Et l\'Éternel lui dit: Tel est le pays que j\'ai promis par serment à Abraham, à Isaac et à Jacob en disant: Je le donnerai à ta race.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Je te l\'ai fait regarder de tes yeux, mais tu n\'y passeras point. Et ainsi mourut là Moïse, serviteur de l\'Éternel, dans le pays de Moab, par l\'ordre de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Et Il l\'ensevelit dans la vallée, au pays de Moab, vis-à-vis de Beth-Pehor, et personne n\'a connu son tombeau jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Or Moïse à sa mort était âgé de cent vingt ans; ses yeux ne s\'étaient point éteints, et il n\'avait point perdu ses forces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Et les enfants d\'Israël pleurèrent Moïse dans les plaines de Moab pendant trente jours; et ils accomplirent le temps des pleurs et du deuil de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Et Josué, fils de Nun, fut rempli de l\'esprit de sagesse, car Moïse avait imposé ses mains sur lui et les enfants d\'Israël lui obéirent et se conformèrent aux ordres que l\'Éternel avait donnés à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Et il ne parut plus en Israël de prophète pareil à Moïse (que l\'Éternel connaissait face en face)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'sous le rapport de tous les signes et miracles que l\'Éternel lui avait donné la mission d\'opérer dans le pays d\'Egypte sur Pharaon et tous ses serviteurs et tout son pays,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'et sous le rapport de toute la main puissante et de tous les actes grands et terribles que Moïse exécuta aux yeux de tout Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Et après la mort de Moïse, serviteur de l\'Éternel, l\'Éternel parla à Josué, fils de Nun, qui était au service de Moïse, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Moïse, mon serviteur, est mort; lève-toi donc maintenant, passe ce Jourdain, toi et tout ce peuple, pour entrer dans le pays que je leur donne, aux enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Tous les lieux que touchera la plante de vos pieds, je vous les ai donnés, selon la promesse que j\'ai faite à Moïse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'depuis le Désert et le Liban que voilà, jusqu\'au Grand Fleuve, l\'Euphrate, tout le pays des Héthiens et jusqu\'à la Grande Mer vers le soleil couchant, telle sera votre frontière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Personne ne tiendra devant toi, tant que tu vivras: je serai avec toi, de même que j\'ai été avec Moïse; je ne te laisserai ni au dépourvu, ni dans l\'abandon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Aie courage et fermeté, car c\'est à toi de mettre ce peuple en possession du pays que j\'ai juré à leurs pères de leur donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Aie seulement courage et grande fermeté, t\'appliquant à agir en toutes choses d\'après la Loi que t\'a prescrite Moïse, mon serviteur; ne t\'en écarte ni à droite ni à gauche, afin que tu réussisses dans toutes tes entreprises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Aie incessamment dans la bouche [les paroles du] livre de cette Loi, médite-le jour et nuit, pour avoir soin d\'agir d\'après tout ce qui y est consigné, car alors tu trouveras sur ta route réussite et succès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Ne t\'ai-je pas donné cet ordre: Aie courage et fermeté? Ne prends ni alarme, ni épouvante, car tu as avec toi l\'Éternel, ton Dieu, à tous les pas que tu feras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Alors Josué donna cet ordre aux Officiers du peuple:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Parcourez le camp et transmettez au peuple cet ordre: Pourvoyez-vous de vivres, car dans trois jours vous serez près de passer ce Jourdain pour marcher à la conquête du pays que l\'Éternel, votre Dieu, vous donne pour le conquérir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Et aux Rubénites et aux Gadites et à la demi-Tribu de Manassé Josué parla en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Souvenez-vous de la condition que vous a prescrite Moïse, serviteur de l\'Éternel, quand il disait: L\'Éternel, votre Dieu, vous a donné votre lieu de repos, et concédé cette contrée-ci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Vos femmes, vos enfants et vos troupeaux resteront dans la contrée que vous a donnée Moïse au delà du Jourdain; mais vous, vous marcherez équipés à la tête de vos frères, vous tous les braves guerriers, et vous les aiderez,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'jusqu\'à ce que l\'Éternel ait donné à vos frères leur lieu de repos comme à vous, et qu\'eux aussi aient conquis le pays que l\'Éternel, votre Dieu, leur donne. Alors vous regagnerez la contrée qui vous appartient, et vous occuperez ce lot que vous a donné Moïse, serviteur de l\'Éternel, au delà du Jourdain, vers le soleil levant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Alors ils répondirent à Josué et dirent: Nous exécuterons tous tes ordres, et nous irons partout où tu nous enverras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'En toutes choses nous t\'obéirons comme nous avons obéi à Moïse. Puisse seulement l\'Éternel, ton Dieu, être avec toi, de même qu\'il fut avec Moïse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Tout homme qui résistera à tes ordres et n\'obéira pas à tes paroles dans tout ce que tu lui commanderas, doit être mis à mort. Aie seulement courage et fermeté!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Et Josué, fils de Nun, envoya secrètement de Sittim deux éclaireurs avec cette instruction: Allez explorer le pays, surtout Jéricho. Et ils partirent et arrivèrent chez une courtisane nommée Rahab, et y couchèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Et l\'avis en fut donné au Roi de Jéricho en ces termes: Voilà que cette nuit il est arrivé ici deux hommes de la part des enfants d\'Israël pour reconnaître le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Alors le Roi de Jéricho fit faire ce message à Rahab: Livre les hommes arrivés chez toi et introduits dans ta maison, car c\'est pour explorer tout le pays qu\'ils sont venus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Mais cette femme prit les deux hommes et les cacha et dit: En effet, ces hommes sont arrivés chez moi, mais sans que je sache d\'où ils sont,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'et comme la porte allait être fermée à la tombée de la nuit, ces hommes s\'en sont allés; j\'ignore où ils se sont rendus; courez vite après eux, car vous les atteindrez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Or elle les avait fait monter sur le toit et cachés sous des tiges de lin étendues par elle sur le toit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Et ces gens se mirent à leur poursuite sur le chemin qui mène au Jourdain par les gués, et l\'on ferma la porte après la sortie des gens qui allaient à leur poursuite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Et avant qu\'ils se couchassent, elle monta vers eux sur le toit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'et elle dit à ces hommes: Je sais que l\'Éternel vous a donné le pays; et que vous nous inspirez la terreur et que tous les habitants du pays tremblent devant vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Car nous avons appris comment l\'Éternel a desséché les eaux de la Mer aux algues devant vous lorsque vous sortiez de l\'Egypte, et comment vous avez traité les deux rois des Amoréens au delà du Jourdain, Sihon et Og, que vous avez dévoués.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'A cette nouvelle notre cœur a été déconcerté, et il n\'existe plus chez personne aucun courage pour vous tenir tête, car c\'est l\'Éternel, votre Dieu, qui est Dieu, en haut dans les Cieux, et en bas sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'A présent jurez-moi donc par l\'Éternel, que comme je vous ai montré de la bonté, vous montrerez aussi de la bonté à la maison de mon père, et donnez-moi une preuve de loyauté,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'et laissez la vie à mon père et à ma mère et à mes frères et à mes sœurs et à tous ceux qui leur appartiennent, et sauvez nos âmes de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Et ces hommes lui dirent: Que nos âmes soient livrées à la mort pour vous! Si vous ne dénoncez pas notre démarche présente, nous agirons envers toi, quand l\'Éternel nous livrera le pays, avec bonté et bonne foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Alors au moyen d\'une corde, elle les dévala par la fenêtre, car sa maison était sur la muraille de la ville, et elle logeait sur la muraille de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Et elle leur dit: Gagnez la montagne pour n\'être pas atteints par ceux qui vous poursuivent, et restez-y cachés trois jours jusqu\'au retour des gens qui sont à votre poursuite, et ensuite continuez votre route.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Et ces hommes lui dirent: Nous allons nous acquitter du serment que tu nous as fait faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Voici, à notre entrée dans le pays attache ce cordon rouge à la fenêtre par laquelle tu nous as dévalés et recueille chez toi dans ton logis ton père et ta mère et tes frères et toute la maison de ton père,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'et si quelqu\'un d\'eux passe la porte de ta maison et paraît dans la rue, c\'est sur sa tête que retombera la faute de sa mort, et nous-mêmes nous en serons innocents; mais si on met la main sur aucun de ceux qui seront avec toi dans la maison, la faute de sa mort retombera sur notre tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Et si tu dénonces notre démarche présente, nous sommes déliés envers toi du serment que tu as exigé de nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Et elle dit: Comme vous le dites, ainsi soit fait; et elle les congédia, et ils partirent. Et elle attacha le cordon rouge à la fenêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Étant donc partis, ils arrivèrent à la montagne où ils restèrent trois jours jusqu\'au retour de ceux qui les poursuivaient. Et ceux-ci les cherchèrent sur toute la route, mais ne les trouvèrent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Alors les deux hommes s\'en retournant descendirent la montagne et repassèrent [le Jourdain]; et étant venus auprès de Josué, fils de Nun, ils lui racontèrent tout ce qui leur était avenu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Et ils dirent à Josué: Oui, l\'Éternel a livré tout ce pays entre nos mains, et même devant nous tous les habitants du pays tremblent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Et le matin Josué se leva, et ils partirent de Sittim et ils arrivèrent au Jourdain, lui et tous les enfants d\'Israël, et là ils firent une halte avant de passer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Et au bout de trois jours les Officiers parcoururent l\'intérieur du camp');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'et donnèrent les ordres au peuple en ces termes: Dès que vous apercevrez l\'Arche d\'Alliance de l\'Éternel, votre Dieu, portée par les Prêtres, les Lévites, partez vous-mêmes de votre station, et suivez-la. Mais qu\'il reste entre vous et Elle un espace d\'environ deux mille coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Ne vous en rapprochez pas, afin de pouvoir découvrir le chemin où vous devez marcher, car vous n\'avez passé par ce chemin ni hier ni avant-hier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Et Josué dit au peuple: Mettez-vous en état de sainteté, car demain l\'Éternel opérera des miracles au milieu de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Et Josué parla aux Prêtres en ces termes: Transportez l\'Arche de l\'Alliance et précédez le peuple. Et ils transportèrent l\'Arche de l\'Alliance et marchèrent en avant du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Et l\'Éternel dit à Josué: Aujourd\'hui je veux commencer à te grandir devant les yeux de tout Israël, afin qu\'ils comprennent que je suis avec toi, de même que j\'ai été avec Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Et toi, donne cet ordre aux Prêtres qui portent l\'Arche de l\'Alliance: Quand vous atteindrez la limite des eaux du Jourdain, arrêtez-vous dans le lit du Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Et Josué dit aux enfants d\'Israël: Approchez et écoutez les paroles de l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Et Josué dit: A ceci vous reconnaîtrez qu\'un Dieu Vivant est au milieu de vous, et qu\'il chassera devant vous les Cananéens et les Héthiens et les Hévites et les Perizzites et les Girgasites et les Amoréens et les Jébusites:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'voici, l\'Arche de l\'Alliance du Seigneur de toute la terre vous devancera dans le Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Et à présent choisissez-vous douze hommes dans les Tribus d\'Israël, un homme par Tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Et aussitôt que la plante des pieds des Prêtres, porteurs de l\'Arche de l\'Éternel, Seigneur de toute la terre, se posera dans les eaux du Jourdain, les eaux du Jourdain seront coupées dans leur cours, les eaux qui descendent d\'en haut, et s\'amoncelleront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Et au départ du peuple sorti de ses tentes pour passer le Jourdain, les Prêtres chargés de l\'Arche de l\'Alliance devançant le peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'au moment où les porteurs de l\'Arche atteignirent le Jourdain, et où se mouillèrent les pieds des Prêtres, porteurs de l\'Arche, plongèrent à la limite de l\'eau (or le Jourdain est rempli jusqu\'au-dessus de ses berges pendant tout le temps de la moisson),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'alors les eaux qui descendaient d\'en haut s\'arrêtèrent; elles s\'élevèrent en un monceau, à une très grande distance, près de Adam, ville située à côté de Tsarthan; et les eaux qui descendaient à la mer de la plaine, la Mer Salée, furent complètement détachées, et le peuple passa vis-à-vis de Jéricho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Et les Prêtres chargés de l\'Arche de l\'Alliance de l\'Éternel s\'arrêtèrent de pied ferme sur le sec dans le lit du Jourdain, et tout Israël marcha sur le sec, jusqu\'à ce que tout le peuple eût achevé de passer le Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Et lorsque tout le peuple eut achevé de passer le Jourdain, l\'Éternel parla à Josué en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Choisissez-vous dans le peuple douze hommes, un homme par Tribu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'et donnez-leur cet ordre: D\'ici, du lit du Jourdain, de la place même où les Prêtres se sont tenus de pied ferme, enlevez douze pierres que vous emporterez avec vous et déposerez à la station où vous passerez cette nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Et Josué manda les douze hommes qu\'il désigna parmi les enfants d\'Israël, un homme par Tribu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'et Josué leur dit: Passez devant l\'Arche de l\'Éternel, votre Dieu, dans le lit du Jourdain et prenez chacun sur l\'épaule une pierre, selon le nombre des Tribus des enfants d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'afin que cela reste comme une preuve parmi vous. Lorsque dans l\'avenir vos fils vous interrogeront en disant: Quel sens ces pierres ont-elles pour vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'vous leur répondrez: Que les eaux du Jourdain ont suspendu leur cours devant l\'Arche de l\'Alliance de l\'Éternel; lorsqu\'elle traversa le Jourdain, les eaux du Jourdain ont suspendu leur cours; et ces pierres sont pour les enfants d\'Israël un monument éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Et les enfants d\'Israël se conformèrent à l\'ordre de Josué, et ils enlevèrent douze pierres dans le lit du Jourdain, comme l\'Éternel l\'avait ordonné à Josué, d\'après le nombre des Tribus des enfants d\'Israël, et ils les transportèrent avec eux à la station, et les y déposèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Josué érigea aussi douze pierres dans le lit du Jourdain à l\'endroit où avaient posé les pieds des Prêtres, porteurs de l\'Arche de l\'Alliance, et elles y sont demeurées jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Or les Prêtres qui portaient l\'Arche, se tinrent dans le lit du Jourdain jusqu\'après l\'entière exécution de tout ce que l\'Éternel avait ordonné à Josué de dire au peuple, en conformité de tout ce que Moïse avait prescrit à Josué. Et le peuple mit de la célérité à faire le trajet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Et quand tout le peuple eut achevé de passer, l\'Arche de l\'Éternel et les Prêtres passèrent aussi par devant le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Et les fils de Ruben et les fils de Gad et la demi-Tribu de Manassé passèrent armés en tête des enfants d\'Israël, comme Moïse le leur avait prescrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Environ quarante mille hommes équipés militairement, passèrent devant l\'Éternel pour faire la campagne dans les plaines de Jéricho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'En ce jour-là l\'Éternel grandit Josué devant les yeux de tout Israël; et ils le respectèrent comme ils avaient respecté Moïse, tout le temps de sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Et l\'Éternel parla à Josué en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Commande aux Prêtres portant l\'Arche du Témoignage de sortir du Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Alors Josué fit aux Prêtres ce commandement: Sortez du Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Et lorsque les Prêtres, porteurs de l\'Arche de l\'Alliance de l\'Éternel, quittèrent le lit du Jourdain et que la plante de leurs pieds se fut détachée et posa sur la terre ferme, les eaux du Jourdain rentrèrent dans leur lit, et coulèrent comme auparavant par-dessus toutes ses berges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Et le peuple sortit du lit du Jourdain le dixième jour du premier mois, et il campa à Guilgal à la frontière orientale de Jéricho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Et Josué érigea à Guilgal ces douze pierres qu\'il avait tirées du Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Et il parla aux enfants d\'Israël en ces termes: Lorsque dans l\'avenir vos fils interrogeront leurs pères en disant: Qu\'est-ce que ces pierres?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'vous instruirez vos fils en disant: Israël a passé ce Jourdain par son lit mis à sec,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'parce que l\'Éternel, votre Dieu, avait desséché les eaux du Jourdain devant vous jusqu\'à ce que vous fussiez passés, ainsi que l\'Éternel, votre Dieu, l\'a fait à la Mer aux algues qu\'il a mise à sec devant nous jusqu\'à ce que nous fussions passés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'afin que tous les peuples de la terre reconnaissent la main de l\'Éternel qui est puissante, afin que vous craigniez l\'Éternel, votre Dieu, dans tous les temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Et lorsque tous les Rois des Amoréens qui étaient au delà du Jourdain à l\'occident, et tous les Rois des Cananéens des côtes de la mer, apprirent que l\'Éternel avait desséché les eaux du Jourdain devant les enfants d\'Israël, jusqu\'à ce que nous fussions passés, ils tremblèrent et n\'eurent plus aucun courage pour tenir tête aux enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Dans ce même temps l\'Éternel dit à Josué: Fais-toi des couteaux de pierre et recommence à circoncire de nouveau les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Et Josué se fit des couteaux de pierre et circoncit les enfants d\'Israël à la colline des prépuces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Or voici la raison pour laquelle Josué opéra une circoncision: tout le peuple sorti de l\'Egypte, les hommes, les gens de guerre en totalité étaient morts dans le désert pendant la route lors de leur sortie d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Car tout le peuple à sa sortie se composait de circoncis; mais tout le peuple né dans le désert pendant la route lors de la sortie d\'Egypte n\'avait pas été circoncis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'En effet, pendant quarante ans, les enfants d\'Israël durent errer dans le désert jusqu\'à l\'extinction de toute cette engeance de gens de guerre, sortis de l\'Egypte, pour n\'avoir pas obéi à la voix de l\'Éternel; ce qui fit que l\'Éternel leur jura qu\'il ne leur permettrait pas de voir le pays que l\'Éternel avait juré à leurs pères de nous donner, pays découlant de lait et de miel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Et l\'Éternel leur substitua leurs fils; ceux-ci furent donc circoncis par Josué, parce qu\'ils étaient non circoncis; car on ne les avait pas circoncis en route.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Et quand tous ces individus eurent subi en totalité la circoncision, ils restèrent sur leur séant dans le camp jusqu\'à leur rétablissement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Et l\'Éternel dit à Josué: En ce jour je vous ai déchargés de l\'opprobre des Égyptiens; alors ce lieu fut appelé du nom de Guilgal (décharge) et il l\'a porté jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Et les enfants d\'Israël campèrent à Guilgal, et ils célébrèrent la Pâque le quatorzième jour du mois au soir dans les plaines de Jéricho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Et ce jour-là même ils mangèrent des denrées du pays le lendemain de la Pâque, des azymes et du grain rôti.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Et la manne cessa dès ce lendemain où ils mangèrent, des denrées du pays, et les enfants d\'Israël n\'eurent plus de manne dès lors, et ils se nourrirent des produits du pays de Canaan cette année-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Et comme Josué était devant Jéricho, il arriva qu\'ayant levé les yeux il regardait; et voilà qu\'un homme se tenait debout en face de lui, son épée nue à la main. Et Josué alla à lui et lui dit: Es-tu des nôtres ou de nos ennemis?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Et il répondit: Non, mais je suis Chef d\'Armée de l\'Éternel; maintenant j\'arrive... Alors Josué se jeta la face contre terre et se prosterna, et lui dit: Qu\'est-ce que mon Seigneur veut dire à son serviteur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Et le Chef d\'Armée de l\'Éternel dit à Josué: Ote tes sandales de tes pieds; car le lieu où tu te tiens est saint. Et ainsi fit Josué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Or Jéricho s\'était fermée, et était fermée aux enfants d\'Israël: personne n\'entrait ni ne sortait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Alors l\'Éternel dit à Josué: Vois! j\'ai livré entre tes mains Jéricho et son Roi, milice guerrière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Vous tous les hommes de guerre, vous exécuterez une marche autour de la ville dont vous ferez une fois le tour, et ainsi pendant six jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Et sept Prêtres porteront sept trompettes en avant de l\'Arche, et le septième jour vous ferez sept fois le tour de la ville, et les Prêtres sonneront des trompettes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Et quand on donnera du cor, et que vous entendrez le son de la trompette, tout le peuple poussera un grand cri, et le mur de la ville croulera sur lui-même, et le peuple l\'escaladera, chacun droit devant soi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Alors Josué, fils de Nun, manda les Prêtres et leur dit: Chargez-vous de l\'Arche de l\'Alliance et que sept Prêtres portent sept trompettes devant l\'Arche de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Et ils dirent au peuple: Marchez et faites le tour de la ville et que les soldats équipés précèdent l\'Arche de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Et Josué ayant parlé au peuple, sept Prêtres portant sept trompettes devant l\'Éternel, se mirent en marche et sonnèrent des trompettes, et l\'Arche de l\'Alliance de l\'Éternel les suivait');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'et les soldats équipés marchaient en tête des Prêtres sonnant des trompettes, et ceux qui fermaient la marche suivaient l\'Arche, les trompettes sonnant toujours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Or Josué avait donné au peuple cet ordre: Vous ne crierez pas, et ne ferez pas entendre votre voix, et pas un son ne sortira de votre bouche jusqu\'au jour où je vous dirai: Criez! Alors poussez le cri!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'L\'Arche de l\'Éternel tourna autour de la ville dont elle fit une fois le tour; puis on rentra au camp et l\'on passa la nuit au camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Et Josué se leva le matin et les Prêtres portaient l\'Arche de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Et sept Prêtres portant sept trompettes devant l\'Arche de l\'Éternel, allaient sonnant toujours des trompettes et les soldats équipés les précédaient, et ceux qui fermaient la marche suivaient l\'Arche de l\'Éternel, les trompettes sonnant toujours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Ainsi firent-ils le tour de la ville le second jour une seule fois, puis ils revinrent au camp, et de même pendant six jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Mais le septième jour ils se levèrent à l\'apparition de l\'aurore, et ils firent le tour de la ville en cette manière, sept fois; ce jour-là seul ils firent sept fois le tour de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Et au septième tour, comme les Prêtres sonnaient des trompettes, Josué dit au peuple: Poussez le cri! car l\'Éternel vous a livré cette ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Et cette ville va être dévouée à l\'Éternel, elle et tout ce qui y est: la vie ne sera laissée qu\'à Rahab, la courtisane, qu\'à elle et à tous ceux qui sont chez elle dans la maison, parce qu\'elle a caché les émissaires que nous avions envoyés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Seulement abstenez-vous de ce qui sera dévoué, afin qu\'après avoir dévoué vous ne preniez rien de ce qui sera dévoué, et que vous n\'attiriez pas l\'anathème sur le camp d\'Israël, et n\'ameniez pas sa ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Et la totalité de l\'argent et de l\'or et des ustensiles d\'airain et de fer sera consacrée à l\'Éternel, entrera dans le trésor de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Alors le peuple poussa le cri et les trompettes sonnaient. Et le peuple entendant le son de la trompette poussa un grand cri, et la muraille croula sur elle-même, et le peuple escalada la ville, chacun droit devant soi; et ils prirent la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Et ils dévouèrent tout ce qui était dans la ville, hommes et femmes, jeunes gens et vieillards, bœufs, brebis et ânes, par le tranchant de l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Et Josué dit aux deux hommes qui étaient allés reconnaître le pays: Rendez-vous à la maison de cette femme, la courtisane, et faites en sortir la femme et tous ceux qui lui appartiennent, comme vous lui en avez fait le serment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Et les jeunes hommes, les éclaireurs, entrèrent et firent sortir Rahab et son père et sa mère et ses frères et tous ceux qui lui appartenaient; ils firent donc sortir toute sa famille, mais ils les laissèrent en dehors du camp d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Quant à la ville, ils la brûlèrent avec tout ce qu\'elle contenait; seulement ils mirent dans le trésor de la maison de l\'Éternel l\'argent et l\'or et les ustensiles d\'airain et de fer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Et Josué laissa la vie à Rahab, la courtisane, et à la maison de son père et à tous ceux qui lui appartenaient; et elle a habité au sein d\'Israël jusqu\'aujourd\'hui, parce qu\'elle avait caché les émissaires envoyés par Josué pour reconnaître Jéricho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Et dans ce même temps Josué fit un serment en ces termes: Maudit soit devant l\'Éternel celui qui entreprendra de relever cette ville de Jéricho! Qu\'au prix de son premier-né il en pose les fondements, et qu\'au prix de son plus jeune fils il en replace les portes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Et l\'Éternel était avec Josué dont la renommée se répandait dans tout le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Or les enfants d\'Israël se rendirent coupables de soustraction de choses dévouées. Car Achan, fils de Charmi, fils de Zabdi, fils de Zérah de la Tribu de Juda, prit de ce qui était dévoué, et la colère de l\'Éternel s\'alluma contre les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Cependant de Jéricho Josué envoya des hommes vers Aï qui est située près de Beth-Aven à l\'orient de Béthel, en leur disant: Allez en avant et explorez le pays. Et ces hommes s\'avancèrent et reconnurent Aï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Et étant revenus auprès de Josué, ils lui dirent: Il n\'y a pas lieu de mettre tout le peuple en campagne; deux ou trois mille hommes environ n\'ont qu\'à marcher et ils réduiront Aï; n\'en donne pas la fatigue à tout le peuple, car il n\'y a que peu de monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'On ne fit donc marcher contre elle dans tout le peuple que trois mille hommes; mais ils prirent la fuite devant les hommes d\'Aï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Et les hommes d\'Aï en tuèrent environ trente-six, et les poursuivirent depuis la porte jusqu\'à Schebarim et les défirent à la descente; et le courage se fondit et s\'écoula comme l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Et Josué déchira ses vêtements, et fut prosterné la face contre terre devant l\'Arche de l\'Éternel jusqu\'au soir, lui et les Anciens d\'Israël, et ils lancèrent la poussière en l\'air sur leurs têtes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Et Josué dit: Ah! Seigneur, Éternel, pourquoi as-tu fait passer le Jourdain à ce peuple, pour nous livrer aux mains des Amoréens, pour nous perdre? si seulement nous nous étions contentés de rester au delà du Jourdain!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Je te le demande, ô mon Seigneur, que puis-je dire après qu\'Israël a tourné le dos devant ses ennemis?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Et les Cananéens et tous les habitants du pays vont l\'apprendre et nous cerner et faire disparaître notre nom de la terre. Et que veux-tu faire pour ton grand Nom?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Et l\'Éternel dit à Josué: Relève-toi! pourquoi t\'es-tu jeté la face contre terre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israël a péché; et même ils ont transgressé mon alliance que je leur ai prescrite, et même retenu des choses dévouées, et même dérobé et dissimulé, et ils les ont cachées parmi leurs bagages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'C\'est pourquoi les enfants d\'Israël ne peuvent tenir tête à leurs ennemis, et tournent le dos devant leurs ennemis; car ils sont sous l\'anathème. Je ne serai plus désormais avec vous, si vous n\'exterminez pas le sacrilège du milieu de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Lève-toi, mets le peuple en état de sainteté et dis: Mettez-vous pour demain en état de sainteté; car ainsi parle l\'Éternel, Dieu d\'Israël: Il y a un anathème au milieu de toi, Israël; vous ne sauriez tenir tête à vos ennemis jusqu\'à ce que vous ayez ôté l\'anathème du milieu de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Vous vous présenterez donc le matin par Tribus, et la Tribu que tirera l\'Éternel, s\'avancera par familles, et la famille que l\'Éternel tirera s\'avancera par maisons, et la maison que tirera l\'Éternel s\'avancera par individus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Et celui qui sera désigné comme sacrilège, sera brûlé au feu, lui et tout ce qui lui appartient, pour avoir transgressé l\'alliance de l\'Éternel et commis un forfait en Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Et Josué s\'étant levé le matin fit approcher Israël par Tribus, et la Tribu de Juda fut désignée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Puis il fit approcher les familles de Juda, et on tira la famille de Zérah; et il fit approcher la famille de Zérah par individus, et Zabdi fut désigné,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'et il fit approcher la maison de celui-ci par individus, et Achan, fils de Charmi, fils de Zabdi, fils de Zérah, de la Tribu de Juda fut pris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Et Josué dit à Achan: Mon fils! Rends gloire à l\'Éternel, Dieu d\'Israël, et fais-lui hommage, et avoue-moi ce que tu as fait, et ne te cache pas de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Et Achan répondit à Josué et dit: C\'est la vérité; j\'ai péché contre l\'Éternel, Dieu d\'Israël; et voici, voici comment j\'ai agi:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'j\'aperçus dans le butin un beau manteau de Sinéar et deux cents sicles d\'argent et un lingot d\'or du poids de cinquante sicles, et j\'ai convoité cela, et l\'ai pris; et voilà, ces objets sont enfouis dans la terre au milieu de ma tente, et l\'argent est dessous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Et Josué dépêcha des commissaires qui coururent à la tente; et voici, les objets étaient enfouis dans sa tente, et l\'argent au-dessous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Et les ayant enlevés de la tente ils les apportèrent à Josué et à tous les enfants d\'Israël, et ils les étalèrent devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Alors Josué fit saisir Achan, fils de Zérah, et l\'argent et le manteau et le lingot d\'or et ses fils et ses filles et son bœuf et son âne et ses brebis et sa tente et tout ce qui lui appartenait, de concert avec tout Israël, et on les fit monter au val d\'Achor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Et Josué dit: Pourquoi nous as-tu perdus? que l\'Éternel te perde aujourd\'hui! Et tout Israël le lapida, et les brûla au feu, et les assaillirent de pierres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Et ils élevèrent sur lui un grand tas de pierres [demeuré] jusqu\'aujourd\'hui. Alors l\'Éternel revint de son ardente colère. C\'est pour cela que ce lieu a porté le nom de Val d\'Achor (perdition) jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Et l\'Éternel dit à Josué: Sois sans crainte et sans peur! Prends avec toi tous les gens de guerre et mets-toi en campagne et marche sur Aï. Vois! j\'ai livré entre tes mains le Roi d\'Aï et son peuple et sa ville et son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Et tu traiteras Aï et son Roi comme tu as traité Jéricho et son Roi; mettez au pillage à votre profit ses dépouilles et ses bestiaux seulement. Dresse une embuscade à la ville par derrière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Alors Josué et tous les gens de guerre se mirent en mouvement pour marcher sur Aï. Et Josué fit choix de trente mille hommes, braves guerriers, qu\'il fit partir de nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Et il leur donna ces instructions: Faites attention! vous resterez en embuscade en vue de la ville, derrière la ville, ne vous éloignez pas trop de la ville et tenez-vous tous prêts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Moi de mon côté, et toute la troupe qui m\'accompagne, nous nous approcherons de la ville, et lorsqu\'ils sortiront à notre rencontre comme la première fois, nous prendrons la fuite devant eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Et laissez-les nous poursuivre jusqu\'à ce que nous les ayons attirés loin de la ville; car ils diront: ils fuient devant nous comme la première fois. Nous fuirons donc devant eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Vous alors, sortez de l\'embuscade et emparez-vous de la ville; et l\'Éternel, votre Dieu, la livrera entre vos mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Et quand vous aurez pris la ville, mettez-y le feu. Vous agirez comme a dit l\'Éternel. Faites attention! je vous ai donné l\'ordre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Josué les chargea donc de cette mission. Arrivés au lieu de l\'embuscade, ils prirent position entre Béthel et Aï, à l\'occident d\'Aï. Cependant Josué passa cette nuit-là au milieu de sa troupe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Et le matin Josué s\'étant levé fit passer sa troupe à la revue, puis il se porta, lui et les Anciens d\'Israël, à la tête du peuple, devant Aï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Et tous les gens de guerre qui étaient avec lui, se mirent en marche et s\'avancèrent et arrivèrent en vue de la ville; et ils campèrent au nord d\'Aï, laissant la vallée entre eux et Aï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Or c\'était environ cinq mille hommes qu\'il prit et mit en embuscade entre Béthel et Aï, à l\'occident de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Et lorsque le peuple eut dressé tout son camp qui était au nord de la ville, tandis que l\'embuscade se trouvait à l\'occident de la ville, Josué s\'avança cette nuit même au milieu de la vallée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Et lorsque le Roi d\'Aï s\'aperçut de cela, les hommes de la ville se levèrent en hâte et firent une sortie contre Israël, le Roi et tout le peuple se portant au point convenu devant la plaine. Or il ne se doutait pas de l\'embuscade dressée contre lui derrière la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Josué et tout Israël se laissèrent donc battre par eux, et s\'enfuirent dans la direction du désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Alors tout le peuple resté dans la ville fut convoqué pour aller à leur poursuite; et ils poursuivirent Josué et furent attirés loin de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Et il ne resta dans Aï et dans Béthel pas un homme qui ne sortît pour poursuivre Israël; et ils laissèrent la ville ouverte, et ils poursuivaient Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Alors l\'Éternel dit à Josué: Étends contre Aï la pique que tu as à la main, car je vais la livrer entre tes mains; et Josué étendit contre la ville la pique qu\'il avait à la main, et les gens embusqués sortirent en hâte de leur poste;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'et comme il étendait sa main, ils accouraient; ils entrèrent dans la ville et la prirent, et aussitôt ils mirent le feu à la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Alors les gens d\'Aï ramenèrent leurs regards en arrière, et ils virent; voilà que la fumée de la ville montait vers le ciel; et il n\'y avait pour eux aucun moyen de fuir ni d\'un côté ni de l\'autre; et la troupe qui fuyait vers le désert se retourna contre ceux qui la poursuivaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Car Josué et tout Israël voyant la ville prise par les gens de l\'embuscade, et la fumée de la ville, qui s\'élevait, firent volte-face et mirent en déroute les hommes d\'Aï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Ceux-là étant ressortis de la ville à leur rencontre, ceux d\'Aï étaient cernés par les Israélites, par les uns d\'un côté, par les autres de l\'autre. Et les Israélites les battirent à ne pas leur laisser un survivant, ni un réchappé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Et ils prirent vivant le Roi d\'Aï et l\'amenèrent à Josué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Et lorsque Israël eut achevé le carnage des habitants d\'Aï dans la campagne, le désert où ils l\'avaient poursuivi, et qu\'ils furent tous tombés, jusqu\'au dernier, sous le tranchant de l\'épée, tous les Israélites revinrent à Aï, et ils la mirent à sac avec le tranchant de l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Et tous ceux qui périrent dans cette journée, hommes et femmes, furent au nombre de douze mille, tous gens d\'Aï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Et Josué ne retira sa main qu\'il tenait étendue avec la pique, que lorsque l\'anathème fut exécuté sur tous les habitants d\'Aï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Les Israélites ne prirent pour eux comme butin que le bétail et les dépouilles de cette ville, selon l\'ordre que l\'Éternel avait prescrit à Josué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Et Josué brûla Aï et en fit un monceau de ruines éternelles, jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Quant au Roi d\'Aï, il le pendit à un arbre jusqu\'au soir, et avec le coucher du soleil il fit enlever de l\'arbre son cadavre que l\'on jeta à l\'entrée de la porte de la ville, et sur lequel on éleva un grand tas de pierres, qui est demeuré jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Alors Josué bâtit un autel à l\'Éternel, Dieu d\'Israël, sur le mont Ebal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'ainsi que Moïse, serviteur de l\'Éternel, l\'avait ordonné aux enfants d\'Israël, et qu\'il est écrit dans le livre de la Loi de Moïse, un autel de pierres brutes que l\'on ne piqua point avec le fer. Et ils y offrirent des holocaustes à l\'Éternel, et y firent des sacrifices pacifiques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Et là il grava sur les pierres la copie de la Loi de Moïse qu\'il transcrivit en présence des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Et tous les Israélites et leurs Anciens et les Officiers et leurs Juges se tenaient des deux côtés de l\'Arche devant les Prêtres, les Lévites, porteurs de l\'Arche de l\'Alliance de l\'Éternel, les étrangers aussi bien que les nationaux, une moitié près du mont Garizim, et l\'autre moitié près du mont Ebal, conformément à l\'ordre donné précédemment par Moïse, serviteur de l\'Éternel, de bénir le peuple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Et après cela il donna lecture de toutes les paroles de la Loi, bénédiction et malédiction, en tout point selon le texte du livre de la Loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Il n\'y eut pas un mot de tout ce que Moïse prescrit, dont Josué ne donnât lecture devant toute l\'Assemblée d\'Israël, et les femmes et les enfants et les étrangers marchant au milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'A ces nouvelles, tous les rois du pays en deçà du Jourdain, de la Montagne, du Pays-bas et de toutes les côtes de la Grande Mer vis-à-vis du Liban, les Héthiens, et les Amoréens, les Cananéens, les Périzzites, les Hévites et les Jébusites');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'se coalisèrent pour attaquer Josué et Israël, d\'un commun accord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Mais les habitants de Gabaon apprenant comment Josué avait traité Jéricho et Aï, eurent de leur côté recours à la ruse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'Ils partirent donc et allèrent en ambassade, et, sur leurs ânes, ils emportèrent des sacs usés, et des outres à vin usées, trouées et ravaudées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'et à leurs pieds de vieilles sandales rapetassées, et sur eux-mêmes des haillons, et tout leur pain de provision était sec et en miettes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Et ils se rendirent vers Josué au camp de Guilgal, et ils lui dirent ainsi qu\'aux hommes d\'Israël: Nous arrivons d\'un pays lointain; dès là accordez-nous une alliance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Et les hommes d\'Israël dirent à ces Hévites: Vous habitez peut-être au milieu de nous; comment nous serait-il possible de vous accorder une alliance?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Et ils dirent à Josué: Nous sommes tes serviteurs. Et Josué leur dit: Qui êtes-vous? d\'où pouvez-vous venir?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Et ils lui dirent: Tes serviteurs viennent, au nom de l\'Éternel, ton Dieu, d\'un pays très éloigné; car nous avons entendu parler de Lui et de tout ce qu\'il a fait en Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'et de tout ce qu\'il a fait aux deux rois des Amoréens au delà du Jourdain, à Sihon, roi de Hesbon, et à Og, roi de Basan, qui était à Astaroth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Et nos Anciens et tous les habitants de notre pays nous ont parlé en ces termes: Prenez avec vous des provisions pour le voyage et allez vous présenter à eux et leur dire: Nous sommes vos serviteurs; accordez-nous donc une alliance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Voyez! notre pain, nous l\'avons pour notre viatique pris chaud dans nos maisons le jour de notre départ pour venir à vous; et maintenant, le voilà sec et en miettes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Et ces outres à vin que nous avons remplies neuves, les voilà trouées, et ces habits que nous portons et ces souliers que nous avons, se sont usés par l\'effet d\'une marche bien longue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Alors les Israélites acceptèrent de leurs provisions, et ils ne consultèrent point l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Et Josué fit avec eux une capitulation et leur accorda une alliance portant qu\'on leur laisserait la vie; et les Princes de l\'Assemblée se lièrent envers eux par un serment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Et trois jours après leur avoir accordé l\'alliance ils apprirent qu\'ils étaient tout près d\'eux et habitaient au milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Et les enfants d\'Israël se mirent en marche et atteignirent leurs villes le troisième jour; or leurs villes étaient Gabaon, et Caphira et Beéroth et Kiriath-Jearim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Et les enfants d\'Israël ne les exterminèrent pas à cause du serment que leur avaient fait les Princes de l\'Assemblée par l\'Éternel, Dieu d\'Israël. Alors toute l\'Assemblée murmura contre les Princes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Et tous les Princes dirent à toute l\'Assemblée: Nous leur avons fait serment par l\'Éternel, Dieu d\'Israël; dès lors nous ne pouvons porter la main sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Voici comment nous les traiterons: nous leur laisserons la vie afin de ne pas attirer sur nous des Vengeances..., en suite du serment que nous leur avons fait. Et les Princes leur dirent: Ils auront la vie sauve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Et ils devinrent coupeurs de bois et porteurs d\'eau auprès de toute l\'Assemblée, comme les Princes le leur avaient dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Alors Josué les fit venir et leur parla en ces termes: Pourquoi nous avez-vous trompés en disant: Nous sommes à une très grande distance de vous, tandis que vous habitez au milieu de nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'dès là vous êtes maudits, et vous ne cesserez jamais d\'être dans la servitude, de couper le bois et de puiser l\'eau pour la maison de mon Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Et ils répondirent à Josué et dirent: C\'est qu\'on avait instruit tes serviteurs de l\'ordre donné par l\'Éternel, ton Dieu, à Moïse, son serviteur, de vous livrer tout ce pays et d\'en exterminer tous les habitants devant vous; aussi avons-nous eu grande peur pour nos vies à votre aspect; c\'est pourquoi nous avons agi de telle sorte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Et maintenant nous voici entre tes mains: traite-nous comme il te semblera bon et juste de le faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Et Josué agit ainsi à leur égard, et il les sauva des mains des enfants d\'Israël, qui ne les massacrèrent pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'mais en ce jour Josué disposa d\'eux pour couper le bois et puiser l\'eau pour l\'Assemblée et pour l\'Autel de l\'Éternel jusqu\'aujourd\'hui, au lieu que choisirait l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Et lorsque Adoni-Tsédec, Roi de Jérusalem, apprit que Josué avait pris et dévoué Aï et traité Aï et son Roi, comme il avait traité Jéricho et son Roi, et que les habitants de Gabaon avaient fait leur paix avec Israël et restaient dans son sein,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'alors il eut une crainte extrême. Car Gabaon était une ville grande comme l\'une des villes royales et plus considérable qu\'Aï, et tous ses hommes étaient des guerriers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Alors Adoni-Tsédec, Roi de Jérusalem, députa vers Hoham, Roi de Hébron, et vers Piream, Roi de Jarmuth, et vers Japhia, Roi de Lachis, et vers Débir, Roi de Eglon, pour leur dire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Venez me joindre pour m\'aider à réduire Gabaon, car elle a fait sa paix avec Josué et les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Et cinq Rois des Amoréens, le Roi de Jérusalem, le Roi de Hébron, le Roi de Jarmuth, le Roi de Lachis, le Roi de Eglon opérèrent leur jonction et s\'avancèrent eux et toutes leurs armées et vinrent camper devant Gabaon, et l\'assiégèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Alors les gens de Gabaon députèrent vers Josué, à son camp près de Guilgal, pour lui dire: Ne retire pas ta main à tes serviteurs, avance-toi vers nous en hâte, apporte-nous aide et secours car tous les Rois des Amoréens habitant la montagne se sont ligués contre nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Là-dessus Josué se mit en marche de Guilgal, lui et avec lui tous les gens de guerre, et tous les braves guerriers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Et l\'Éternel dit à Josué: N\'aie pas peur d\'eux, car je les ai livrés entre tes mains, pas un de leurs hommes ne te tiendra tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Et Josué fondit sur eux tout à coup. Or il employa toute la nuit à venir de Guilgal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Et l\'Éternel jeta la confusion parmi eux devant Israël, et il leur fit essuyer une grande défaite près de Gabaon, et il les poursuivit sur la route de la montée de Beth-Horon, et les mena battant jusqu\'à Azéca et à Makkéda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Et comme ils fuyaient devant Israël, ils étaient à la descente de Beth-Horon; là l\'Éternel fit tomber sur eux du ciel de grosses pierres jusqu\'à Azéca; et ils périrent; il y eut un plus grand nombre de ceux que tuèrent les pierres de grêle, que de ceux que les enfants d\'Israël égorgèrent avec l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'C\'est alors que Josué parla à l\'Éternel, dans la journée où l\'Éternel livra les Amoréens aux enfants d\'Israël, et il dit en présence d\'Israël: Soleil, attends à Gabaon, et toi, Lune, au val d\'Ajalon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Et le soleil attendit et la lune resta, jusqu\'à ce qu\'Israël eût puni ses ennemis. N\'est-ce pas ce qui est écrit dans le Livre du Droiturier? Et le soleil resta dans le milieu du ciel et ne se hâta pas vers son couchant, presque un jour entier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Et avant et après il n\'y eut pas une journée telle que l\'Éternel écoutât la voix d\'un homme, car l\'Éternel combattait pour Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Et Josué, et tout Israël avec lui, retourna au camp à Guilgal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Ces cinq Rois étaient donc en fuite, et ils se cachèrent dans la caverne à Makkéda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Alors Josué reçut cette information: Les cinq Rois se trouvent cachés dans la caverne à Makkéda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Et Josué dit: Roulez de grosses pierres à l\'ouverture de la caverne, et postez-y des hommes pour les garder.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Quant à vous, ne vous arrêtez pas, poursuivez vos ennemis, et attaquez-les en queue, ne les laissez pas regagner leurs villes; car l\'Éternel, votre Dieu, les a livrés entre vos mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Et lorsque Josué et les enfants d\'Israël eurent consommé leur défaite qui fut très grande, jusqu\'à extermination (des réchappés échappèrent pourtant et gagnèrent les places fortes)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'et lorsque tout le peuple fut revenu sain et sauf au camp auprès de Josué à Makkéda sans que personne remuât la langue contre les enfants d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'alors Josué dit: Ouvrez l\'entrée de la caverne et tirez de la caverne pour me les amener ces cinq Rois-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Et on le fit, et on lui amena ces cinq Rois-là qui furent tirés de la caverne, le Roi de Jérusalem, le Roi de Hébron, le Roi de Jarmuth, le Roi de Lachis, le Roi de Eglon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Et ces Rois amenés devant Josué, Josué convoqua tous les hommes d\'Israël, et dit aux chefs des gens de guerre qui avaient marché avec lui: Approchez! posez vos pieds sur les cous de ces Rois. Et ils s\'approchèrent et posèrent leurs pieds sur leurs cous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Alors Josué leur dit: Soyez sans crainte et sans peur, ayez courage et résolution, car ainsi l\'Éternel traitera tous vos ennemis que vous avez à combattre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Après quoi Josué les fit égorger et tuer, puis pendre à cinq arbres; et ils restèrent pendus aux arbres jusqu\'au soir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Et au moment du coucher du soleil, sur l\'ordre de Josué, on les détacha des arbres, et on les jeta dans la caverne où ils s\'étaient cachés, et l\'on plaça de grosses pierres à l\'ouverture de la caverne, et elles y sont aujourd\'hui même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Et dans ce même jour Josué ayant pris Makkéda la mit à sac avec le tranchant de l\'épée, et il dévoua son Roi, ainsi que toutes les personnes qui s\'y trouvaient, et ne laissa survivre aucun réchappé; et il traita le Roi de Makkéda comme il avait traité le Roi de Jéricho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Alors Josué et tout Israël avec lui, de Makkéda se porta sur Libna, et il attaqua Libna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Et l\'Éternel la livra aussi entre les mains d\'Israël, ainsi que son Roi, et la frappa avec le tranchant de l\'épée, ainsi que toutes les personnes qui s\'y trouvaient, et il n\'y laissa survivre aucun réchappé, et il traita son Roi comme il avait traité le Roi de Jéricho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Puis Josué, et tout Israël avec lui, de Libna marcha sur Lachis devant laquelle il campa; et il l\'attaqua.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Et l\'Éternel livra Lachis entre les mains d\'Israël qui la prit dès le second jour et la mit à sac avec le tranchant de l\'épée ainsi que toutes les personnes qui y étaient, tout comme il avait traité Libna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Alors Horam, Roi de Gézer, s\'avança pour secourir Lachis, et Josué le défit lui et son peuple, à ne pas lui laisser un réchappé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Ensuite Josué, et tout Israël avec lui, de Lachis se porta sur Eglon devant laquelle ils campèrent et qu\'ils attaquèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Et ils la prirent le jour même, et ils sévirent sur elle avec le tranchant de l\'épée, ainsi que sur toutes les personnes qui s\'y trouvaient, et le jour même il la dévoua tout comme il avait traité Lachis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Ensuite Josué, et tout Israël avec lui, de Eglon se porta sur Hébron qu\'ils attaquèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Et l\'ayant prise ils sévirent avec le tranchant de l\'épée sur elle, et sur son Roi, et sur toutes ses villes et sur toutes les personnes qui y étaient; il ne laissa survivre aucun réchappé ainsi qu\'il avait fait à Eglon, et il la dévoua avec toutes les personnes qui y étaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Alors Josué, et tout Israël avec lui, se tourna contre Debir, et il l\'attaqua.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Et il la prit ainsi que son Roi et toutes ses villes, et ils sévirent sur elles avec le tranchant de l\'épée, et ils dévouèrent toutes les personnes qui y étaient sans laisser survivre un réchappé; comme il avait traité Hébron, ainsi traita-t-il Debir, et son Roi, de la même manière qu\'il avait traité Libna et son Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Ainsi Josué réduisit tout le pays, la Montagne, le Midi, le Pays-bas et les versants, et tous leurs Rois; il ne laissa survivre aucun réchappé, et il dévoua tout ce qui respirait, selon l\'ordre de l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Et Josué les réduisit de Cadès-Barnéa à Gaza, et tout le district de Gosen jusques à Gabaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Et dans une seule campagne Josué prit tous ces rois et leur pays, car l\'Éternel, Dieu d\'Israël, combattait pour Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Alors Josué et tout Israël avec lui, revint au camp à Guilgal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Et lorsque Jabin, Roi de Hatsor, apprit ces faits, il envoya requérir Jobab, Roi de Madon, et le Roi de Simron, et le Roi de Achsaph,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'et les Rois qui étaient au nord dans la montagne et dans la plaine au sud de Kinnéroth, et dans le Pays-bas et sur la hauteur de Dor à l\'occident;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'les Cananéens de l\'orient et de l\'occident, et les Amoréens et les Héthiens et les Périzzites, et les Jébusites sur la montagne et les Hévites au pied de l\'Hermon dans la contrée de Mitspa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Et ils se mirent en campagne, eux et toutes leurs armées avec eux, troupe considérable, égale en nombre aux grains de sable des bords de la mer, ayant de la cavalerie et des chars en quantité très grande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Et après être convenus du rendez-vous, tous ces Rois vinrent camper ensemble près des eaux de Mérom pour en venir aux mains avec Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Mais l\'Éternel dit à Josué: N\'aie pas peur d\'eux, car demain, à pareil moment, moi-même je les livrerai tous défaits à Israël; tu couperas le tendon à leurs chevaux, et tu brûleras au feu leurs chars.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Alors Josué avec toute sa troupe guerrière fondit sur eux à l\'improviste près des eaux de Mérom, et les assaillit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Et l\'Éternel les livra entre les mains des Israélites qui les battirent et les poursuivirent jusqu\'à Sidon, la grande, et jusqu\'aux Eaux-brûlantes, et jusqu\'à la vallée de Mitspeh vers l\'orient, et ils les défirent à ne leur pas laisser un réchappé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Et Josué les traita conformément à ce que lui avait dit l\'Éternel; il coupa le tendon à leurs chevaux et brûla leurs chars au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Et dans ce même temps Josué revint sur ses pas, et il s\'empara de Hatsor dont il fit périr le Roi par l\'épée; car dès longtemps Hatsor était le chef-lieu de tous ces royaumes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'et ils frappèrent avec le tranchant de l\'épée toutes les personnes qui s\'y trouvaient, après les avoir dévouées; il ne survécut rien de ce qui respirait, et il brûla Hatsor au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Et Josué s\'empara de toutes les villes de ces Rois et de tous leurs Rois qu\'il passa au fil de l\'épée et dévoua selon l\'ordre de Moïse, serviteur de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Seulement toutes les villes restées sur leur emplacement ne furent pas brûlées par Israël, à l\'exception de Hatsor qui seule fut brûlée par Josué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Et les enfants d\'Israël firent leur butin de toutes les dépouilles de ces villes et des bestiaux; seulement ils passèrent au fil de l\'épée la totalité des hommes, jusqu\'à leur extermination, sans rien laisser de ce qui respirait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Ainsi que l\'Éternel l\'avait ordonné à Moïse, son serviteur, ainsi Moïse l\'ordonna-t-il à Josué, et ainsi fit Josué sans rien omettre de tout ce que l\'Éternel avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'C\'est ainsi que Josué conquit tout ce pays-là, la Montagne et tout le Midi et tout le district de Gosen et le Pays-bas et la plaine et la montagne d\'Israël avec son Pays-bas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'depuis la croupe nue qui monte vers Séir, jusqu\'à Baal-Gad dans la vallée du Liban au pied du mont Hermon, et il prit tous leurs Rois qu\'il égorgea et fit périr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'La guerre que Josué soutint contre tous ces Rois fut de longue durée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Il n\'y eut pas une ville qui se rendît par capitulation aux enfants d\'Israël, excepté les Hévites habitant Gabaon; ils les prirent toutes après un combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Car ce fut par une dispensation de l\'Éternel que leur cœur s\'endurcit pour engager la lutte avec Israël, afin qu\'on les dévouât, qu\'on ne leur fît point de quartier, mais qu\'on les détruisît, au contraire, comme l\'Éternel l\'avait ordonné à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Et dans ce même temps Josué se mit en marche; et il extermina les Anakites de la Montagne, de Hébron, de Debir, de Anab et de toute la Montagne de Juda et de toute la montagne d\'Israël: Josué les dévoua avec leurs villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Il ne resta point d\'Anakites dans le pays des enfants d\'Israël; il n\'en resta que dans Gaza, Gath et Asdod.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Et c\'est ainsi que Josué s\'empara de tout le pays, selon toutes les promesses faites par l\'Éternel à Moïse, et Josué le donna comme patrimoine à Israël selon ses divisions, selon ses Tribus. Et le pays eut trêve de guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Suivent les rois du pays vaincus par les enfants d\'Israël qui conquirent leur pays au delà du Jourdain du côté du soleil levant depuis la rivière d\'Arnon jusqu\'au mont Hermon, et toute la plaine orientale:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sihon, Roi des Amoréens résidant à Hesbon, dont l\'autorité s\'étendait depuis Aroër sur les bords de l\'Arnon à partir du milieu du ravin et sur la moitié de Galaad jusqu\'à la rivière de Jabboc, frontière des Ammonites,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'et sur la partie orientale de la plaine d\'un côté jusqu\'au lac de Kinnéroth, de l\'autre jusqu\'à la Mer de la plaine, la Mer Salée à l\'orient vers Beth-Jesimoth, et au midi au pied des versants du Pisga.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, '[Ils conquirent] aussi les États de Og, Roi de Basan, l\'un des restes des Rephaïms, qui résidait à Astaroth et à Edreï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'Et il avait sous sa domination la chaîne de l\'Hermon et Salcha et tout Basan jusqu\'à la frontière des Gessurites et des Maachatites, et la moitié de Galaad jusqu\'aux confins de Sinon, Roi de Hesbon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Moïse, serviteur de l\'Éternel, et les enfants d\'Israël les défirent, et Moïse, serviteur de l\'Éternel, donna cette contrée en propriété aux Rubénites et aux Gadites et à la demi-Tribu de Manassé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Suivent les rois du pays vaincus par Josué et les enfants d\'Israël en deçà du Jourdain à l\'occident depuis Baal-Gad dans la vallée du Liban jusqu\'à la croupe nue qui monte vers Séir. Et Josué donna cette contrée aux Tribus d\'Israël en propriété d\'après leurs divisions,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'et la Montagne et le Pays-bas et la Plaine et les versants et le Désert et le Midi, les pays des Héthiens, des Amoréens et des Cananéens et des Périzzites, des Hévites et des Jébusites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Le Roi de Jéricho, un; le Roi d\'Aï à côté de Béthel, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'le Roi de Jérusalem, un; le Roi de Hébron, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'le Roi de Jarmuth, un; le Roi de Lachis, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'le Roi de Eglon, un; le Roi de Gézer, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'le Roi de Debir, un; le Roi de Géder, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'le Roi de Horma, un; le Roi de Arad, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'le Roi de Libna, un; le Roi de Adullam, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'le Roi de Makkéda, un; le Roi de Béthel, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'le Roi de Thappuah, un; le Roi de Hépher, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'le Roi de Aphek, un; le Roi de Lassaron, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'le Roi de Madon, un; le Roi de Hatsor, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'le Roi de Simron-Meron, un; le Roi de Achsaph, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'le Roi de Thaanach, un; le Roi de Megiddo, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'le Roi de Kedès, un; le Roi de Jockneam au Carmel, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'le Roi de Dor, aux hauteurs de Dor, un; le Roi des Gentils à Guilgal, un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'le Roi de Thirtsa, un; total des Rois, trente-un.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Cependant Josué était vieux, avancé en âge. Alors l\'Éternel lui dit: Tu es vieux, avancé en âge, et il reste encore une très grande partie du pays à conquérir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'cette partie du pays qui reste, c\'est tous les cantons des Philistins, et la totalité du Gessuri,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'depuis le Sihor (Nil) qui coule devant l\'Egypte jusqu\'à la limite de Ecron au nord doit être réputée Cananéenne; cinq princes des Philistins, celui de Gazal et celui d\'Asdod, celui d\'Ascalon, celui de Gath et celui de Ecron et les Avvites au midi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'tout le pays des Cananéens et la caverne appartenant aux Sidoniens jusqu\'à Aphek, jusqu\'à la frontière des Amoréens;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'et le pays des Giblites et tout le Liban du côté du soleil levant depuis Baal-Gad au pied du mont Hermon jusqu\'aux abords de Hamath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Tous les habitants des montagnes depuis le Liban aux Eaux qui brûlent, tous les Sidoniens, je les chasserai devant les enfants d\'Israël; partage seulement ce pays par le sort à Israël comme patrimoine, ainsi que je te l\'ai prescrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'A présent donc répartis-le par lots aux neuf Tribus et à la demi-Tribu de Manassé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Les Rubénites et les Gadites ont reçu avec l\'autre moitié [de Manassé] leurs lots que Moïse leur a donnés au delà du Jourdain à l\'orient, comme Moïse, serviteur de l\'Éternel, le leur a donné,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'savoir depuis Aroër au bord de la rivière de l\'Arnon depuis la ville qui est au milieu du ravin de l\'Arnon, et tout le pays plat de Medéba jusqu\'à Dibon');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'et toutes les villes de Sihon, Roi des Amoréens qui régnait à Hesbon, jusqu\'à la frontière des fils d\'Ammon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'et Galaad et les Gessurites et les Maachatites et toute la montagne de l\'Hermon, et tout Basan jusqu\'à Salcha;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'tout le royaume de Og, Roi de Basan qui régnait à Astaroth et à Edreï (l\'un des restes des Rephaïms); et Moïse les vainquit et les expulsa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Mais les enfants d\'Israël n\'expulsèrent point les Gessurites ni les Maachatites qui ont vécu au sein d\'Israël jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Il n\'y eut que la Tribu de Lévi à laquelle il ne donna point de lot; les sacrifices ignés faits à l\'Éternel, Dieu d\'Israël, tel est son lot, comme Il le lui a dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Et Moïse dota la Tribu des fils de Ruben en raison de ses familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Et leur territoire, à partir d\'Aroër au bord de la rivière de l\'Arnon, de la ville située au centre du ravin, comprenait aussi tout le pays plat près de Medéba,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbon et toutes ses villes dans le pays plat, Dibon, et Bamoth-Baal et Beth Baal-Meon');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'et Jahtsa et Kedémoth et Mephaath');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'et Kiriathaïm et Sibma et Tséreth-Sahar dans la montagne de la vallée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'et Beth-Pehor, et les versants du Pisga et Beth-Jesimoth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'et toutes les villes du pays plat et tout le royaume de Sihon, Roi des Amoréens, qui régnait à Hesbon, que Moïse vainquit ainsi que les Princes de Madian, Evi et Rekem et Tsur et Hur et Reba, vassaux de Sihon qui habitaient dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Et les enfants d\'Israël tuèrent avec l\'épée Balaam, fils de Behor, le devin, qu\'ils ajoutèrent aux morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Et la frontière des fils de Ruben fut le Jourdain et le territoire adjacent. Tel est le lot des fils de Ruben selon leurs familles, les villes avec leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Et Moïse dota la Tribu de Gad, les fils de Gad, d\'après leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Et leur territoire comprenait Jaëzer et toutes les villes de Galaad, et la moitié du pays des fils d\'Ammon jusqu\'à Aroër située devant Rabba,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'puis s\'étendait depuis Hesbon jusqu\'à Ramath-Mitspeh et Bethonim, et de Mahanaïm à la frontière de Debir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'et dans la vallée ils eurent Beth-Haram et Beth-Nimra et Succoth et Tsaphon, reste du royaume de Sihon, Roi de Hesbon, le Jourdain et le territoire adjacent jusqu\'à l\'extrémité de la Mer Kinnéroth, au delà du Jourdain à l\'orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Tel fut le lot des fils de Gad selon leurs familles, les villes avec leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Et Moïse dota la demi-Tribu de Manassé, et la demi-Tribu des fils de Manassé fut pourvue en raison de ses familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Et à partir de Mahanaïm leur territoire comprenait tout Basan, tout le royaume de Og, Roi de Basan, et tous les bourgs de Jaïr situés en Basan: soixante villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'Et la moitié de Galaad et Astaroth et Edreï, les villes du royaume de Og en Basan échurent aux fils de Machir, fils de Manassé, à la moitié des fils de Machir selon leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'C\'est là ce dont Moïse fit le partage dans les plaines de Moab au delà du Jourdain près de Jéricho, à l\'orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Quant à la Tribu de Lévi, Moïse ne lui donna pas de lot; l\'Éternel, Dieu d\'Israël, tel est son lot, comme Il le lui a dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Et voici ce dont les enfants d\'Israël prirent possession dans le pays de Canaan, ce que leur partagèrent le Prêtre Eléazar et Josué, fils de Nun, et les Patriarches des Tribus des enfants d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'en tirant au sort leurs lots selon l\'ordre de l\'Éternel donné par l\'organe de Moïse, aux neuf Tribus et à la demi-Tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Car Moïse avait déjà donné le lot des deux Tribus et de la demi-Tribu au delà du Jourdain; mais aux Lévites il n\'avait donné aucun lot parmi eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Car aussi les fils de Joseph formaient deux Tribus, Manassé et Ephraïm, et on ne donna aux Lévites de portion dans le pays que des villes pour y loger, et leurs banlieues pour recevoir leurs troupeaux et leurs biens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Les enfants d\'Israël exécutèrent les ordres donnés par l\'Éternel à Moïse, et firent le partage du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Et les fils de Juda s\'approchèrent de Josué à Guilgal, et Caleb, fils de Jéphunné, issu de Kénaz, lui dit: Tu as connaissance de la parole adressée par l\'Éternel à Moïse, homme de Dieu, pour ce qui me concerne ainsi que toi, à Cadès-Barnéa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'J\'avais quarante ans, lorsque Moïse, serviteur de l\'Éternel, m\'envoya de Cadès-Barnéa explorer le pays, et je lui rendis compte ainsi que mon cœur le sentait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Et mes frères qui avaient fait le voyage avec moi, découragèrent le peuple, mais moi j\'obéis pleinement à l\'Éternel, mon Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Et en ce jour-là Moïse prononça ce serment: Certainement le pays que ton pied a foulé deviendra le lot de toi et de tes fils à perpétuité, parce que tu as pleinement obéi à l\'Éternel, mon Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Et maintenant, voici, l\'Éternel m\'a conservé la vie, comme Il l\'a promis, pendant ces quarante-cinq années depuis que l\'Éternel adressa cette parole à Moïse, quand Israël parcourait le désert;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'or maintenant voici, aujourd\'hui j\'ai quatre-vingt-cinq ans; j\'ai encore aujourd\'hui la même vigueur qu\'au temps où Moïse me confia ma mission; la force que j\'avais alors est la force que j\'ai aujourd\'hui pour faire la guerre, pour aller et venir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Maintenant donc donne-moi cette montagne que l\'Éternel m\'a promise en ce temps-là. Car dans ce temps-là aussi tu as appris que les Anakites sont là et qu\'il s\'y trouve de grandes villes fortifiées. L\'Éternel peut-être sera avec moi, et je les expulserai selon la promesse de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Alors Josué le bénit et il donna Hébron à Caleb pour son lot,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'c\'est pourquoi Caleb, fils de Jéphunné, issu de Kénaz, a eu Hébron pour lot jusqu\'aujourd\'hui, parce qu\'il avait pleinement obéi à l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Or Hébron portait autrefois le nom de Kiriath-d\'Arba; celui-ci était l\'homme le plus grand parmi les Anakites, et le pays se reposa des troubles de la guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Et le lot, échu par le sort à la Tribu des fils de Juda en raison de leurs familles, fut: à la frontière d\'Edom le désert de Tsin, au sud, à l\'extrémité méridionale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Et leur frontière méridionale, partant de l\'extrémité de la Mer Salée, de la pointe tournée au midi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'courait au sud de la Hauteur des scorpions, puis passant à Tsin remontait du midi de Cadès-Barnéa, d\'où passant à Hetsron elle montait vers Addar pour tourner vers Karka');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'et passer à Atsmon pour déboucher au Torrent d\'Egypte et aboutir à la Mer. Telle sera votre frontière au midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Et la frontière orientale fut la Mer Salée jusqu\'à l\'embouchure du Jourdain. Et la frontière du côté du nord partait de la pointe de la Mer [Salée], de l\'embouchure du Jourdain');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'montait vers Beth-Hogla, et passait au nord de Beth-Araba, puis montait à la Pierre de Bohan, fils de Ruben, puis du Val d\'Achor la frontière');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'montait à Debir et au nord contournait vers Guilgal située vis-à-vis de l\'éminence d\'Adummim qui est au sud de la rivière. Ensuite la frontière continuait jusqu\'aux Eaux de la Fontaine du soleil et venait aboutir à la Fontaine des éclaireurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'De là elle montait à la vallée des fils de Hinnom au gradin méridional des Jébusites, c\'est-à-dire, de Jérusalem, puis gagnait le sommet de la montagne à l\'occident de la vallée de Hinnom qui est à l\'extrémité septentrionale de la vallée de Rephaïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Et du sommet de la montagne la frontière était tracée jusqu\'à la Fontaine des Eaux de Nephthoah et continuait jusqu\'aux villes de la montagne d\'Ephron et suivait une ligne jusqu\'à Baalah, c\'est-à-dire, Kiriath-Jearim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Et de Baalah elle tournait à l\'ouest vers le mont Séir et traversant le gradin septentrional du mont de Jearim, c\'est-à-dire, Chessalon, elle descendait à Beth-Sémès et continuait jusqu\'à Thimna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'De là suivant le gradin septentrional de Ecron elle se dirigeait vers Sichron et allait au mont Baalah et atteignait Jabnéel, pour aboutir à la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Et la frontière occidentale est formée par la Mer, la Grande Mer et la côte. Telle est la frontière des fils de Juda de tous les côtés, en raison de leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Et à Caleb, fils de Jephunné, il donna pour portion au milieu des fils de Juda, comme l\'Éternel l\'avait ordonné à Josué, la ville de Arba, père des Anakites, c\'est-à-dire, Hébron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Et Caleb en expulsa les trois fils d\'Anak, Sesaï et Ahiman et Thalmaï, issus d\'Anak.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Et de là il monta pour attaquer les habitants de Debir (jadis Debir portait le nom de Kiriath-Sépher).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Et Caleb dit: A celui qui réduira et prendra Kiriath-Sépher, je donnerai pour femme Achsa, ma fille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Et Othniel, fils de Kénaz, frère de Caleb, s\'en empara, et Caleb lui donna pour femme sa fille Achsa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Et à son entrée chez lui elle l\'incita à demander un champ à son père; et de dessus l\'âne qu\'elle montait, elle mit pied à terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Et Caleb lui dit: Qu\'as-tu? Et elle dit: Accorde-moi un bienfait! puisque tu m\'as donné la contrée du midi, donne-moi aussi des sources d\'eaux. Alors il lui donna les sources supérieures et les sources inférieures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Tel est le lot de la Tribu des fils de Juda, d\'après leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Et à l\'extrémité de la Tribu des fils de Juda vers la frontière d\'Edom dans le Midi se trouvaient ces villes-ci: Kabtséel et Eder et Jagur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'et Kîna et Dîmona et Adada');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'et Kédès et Hatsor et Jithnan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Ziph et Telem et Bealoth');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'et Hatsor-Hadatha et Kirioth, Hetsron, c\'est-à-dire, Hatsor,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam et Sema et Molada,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'et Hatsar-Gadda et Hesmon et Beth-Palet,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'et Hatsar-Sual et Béer-Séba et Bisiotheia,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala et Ijim et Atsem');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'et El-Tholad et Chesil et Horma');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'et Tsildag et Madmanna et Jansanna,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'et Lebaoth et Silhim et Aïn et Rimmon: total des villes; vingt-neuf, plus leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'Dans le Pays-bas: Esthaol et Tsarea et Asna,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'et Zanoah et Ein-Gannim, Thappuah et Einam,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmuth et Adullam, Socho et Azeka,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'et Saaraïm et Adithaïm et Gedera et Gederothaïm: quatorze villes, plus leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Tsenan et Hadasa, et Migdal-Gad,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'et Dilean et Mitspeh et Joktéel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lachis et Botskath et Eglon');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'et Chabbon et Lahmas et Chitelis');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'et Gederoth, Beth-Dagon et Naama et Makkéda: seize villes, plus leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna et Ether et Asan');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'et Jephthah et Asena et Netsîb,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'et Keïla et Achsîb, et Marésa: neuf villes, plus leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ecron et ses annexes et ses villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Et depuis Ecron et à l\'occident toutes les villes à côté de Asdod et leurs villages:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdod, ses annexes et ses villages; Gaza, ses annexes et ses villages jusqu\'au Torrent d\'Egypte et à la Grande Mer et aux côtes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Et dans la montagne: Samîr et Jathîr, et Socho');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'et Danna et Kiriath-Sanna, c\'est-à-dire, Debir');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'et Anab et Esthemo et Anim');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'et Gosen et Holon et Gilo: onze villes, plus leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab et Duma et Esean');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'et Janîm et Beth-Thappuah et Apheka');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'et Humta et Kiriath-Arba, c\'est-à-dire, Hébron, et Tsior: neuf villes, plus leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Carmel et Ziph et Juta');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'et Jizréel et Jockdeam et Zanoah,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kaïn, Gibea et Thimna: dix villes, plus leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, Beth-Tsur, et Gedor');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'et Maarath et Beth-Anoth et Elthékon: six villes, plus leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kiriath-Baal, c\'est-à-dire, Kiriath-Jearim et Harabba: deux villes plus leurs bourgs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'Dans le Désert: Beth-Araba, Middin et Sechacha');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'et Nibsan et Ir-Hammélach (Ville du sel) et Ein-Gueddi: six villes, plusieurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Quant aux Jébusites habitant Jérusalem, les fils de Juda ne purent les expulser; dès là les Jébusites ont habité avec les enfants de Juda à Jérusalem jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Et le sort fit échoir aux fils de Joseph leur lot à partir du Jourdain près de Jéricho; des eaux de Jéricho à l\'orient le désert qui de Jéricho va s\'élevant à la montagne de Béthel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'puis à partir de Béthel la limite courait vers Luz et continuait jusqu\'au territoire des Archites, à Ataroth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'ensuite elle descendait à l\'occident vers le territoire des Japhlétites jusqu\'à la frontière de Beth-Horon, la basse, et à Gézer pour aboutir à la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'C\'est ce dont furent mis en possession les fils de Joseph, Manassé et Ephraïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Et la frontière des fils d\'Ephraïm, selon leurs familles, la limite de leur lot était, du côté de l\'orient, Ataroth-Addar jusqu\'à Beth-Horon, la haute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Et la frontière courait à l\'occident vers Michmethath, au nord, puis tournait à l\'orient vers Thaenath-Silo, qu\'elle longeait à l\'orient jusqu\'à Janoha,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'ensuite de Janoha elle descendait à Ataroth et Naaratha pour toucher à Jéricho et aboutir au Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'De Thappuah la frontière allait vers l\'occident à Nahal-Kana (rivière des joncs) pour aboutir à la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Tel est le lot de la Tribu des fils d\'Ephraïm selon leurs familles, [plus] les villes réservées pour les fils d\'Ephraïm et enclavées dans le lot des fils de Manassé, toutes ces villes avec leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Et ils ne dépossédèrent point les Cananéens habitant Gézer; dès là les Cananéens sont demeurés au milieu d\'Ephraïm jusqu\'aujourd\'hui et ont été soumis à la corvée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Et le sort adjugea son lot à la tribu de Manassé (qui était le premier-né de Joseph), à Machir, premier-né de Manassé, maître du Galaad; car c\'était un guerrier; il obtint donc le Galaad et le Basan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Et les autres fils de Manassé eurent aussi leur lot en raison de leurs familles, les fils de Abiézer, et les fils de Hélek, et les fils de Asriel, et les fils de Séchem, et les fils de Hépher, et les fils de Semida; tels sont les fils de Manassé, fils de Joseph, les descendants mâles selon leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Or Tselophehad, fils de Hépher, fils de Galaad, fils de Machir, fils de Manassé, n\'avait point de fils, mais seulement des filles; et voici les noms de ses filles: Mahéla et Noa, Hogla, Milka et Thirtsa;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'et elles se présentèrent au Prêtre Eléazar, et à Josué, fils de Nun, et aux Princes, en disant: L\'Éternel a commandé à Moïse de nous donner un lot parmi nos frères. Et sur l\'ordre de l\'Éternel il leur donna un lot parmi les frères de leur père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Et il échut à Manassé dix portions outre la contrée du Galaad et du Basan, qui est au delà du Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Car les filles de Manassé obtinrent un lot parmi ses fils, et le pays de Galaad échut aux fils de Manassé de l\'autre branche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Et la frontière de Manassé allait de Asser à Michmethath située à l\'est de Sichem; et elle courait vers le sud jusqu\'aux habitants de Ein-Thappuah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Manassé eut la région de Thappuah, et les fils d\'Ephraïm, Thappuah à la frontière de Manassé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Et la frontière descendait à Nahal-Kana (rivière des joncs) au midi de la rivière. Ces villes échues à Ephraïm étaient enclavées entre celles de Manassé. Et la frontière de Manassé était au nord de la rivière et aboutissait à la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Le côté du midi fut à Ephraïm, et le côté du nord à Manassé, et la mer en était la limite. Et au nord ils confinaient à Asser, et du côté de l\'orient à Issaschar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Et Manassé eut des enclaves dans Issaschar, et dans Asser Beth-Séan et ses annexes, et Jibleam et ses annexes ainsi que les habitants de Dor et ses annexes, et les habitants de Ein-Dor et ses annexes, et les habitants de Thaanach et ses annexes et les habitants de Megiddo et ses annexes, triple district.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Et les fils de Manassé ne purent faire la conquête de ces villes et les Cananéens résolurent de demeurer dans cette contrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Et lorsque les enfants d\'Israël eurent la force, ils rendirent les Cananéens corvéables, mais sans en venir à les expulser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Et les fils de Joseph s\'adressèrent à Josué en ces termes: Pourquoi ne nous mets-tu en possession que d\'un lot, que d\'une portion, tandis que nous formons un peuple nombreux ensuite de ce que l\'Éternel nous a bénis jusqu\'ici?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Et Josué leur dit: Si vous êtes un peuple nombreux, avancez-vous dans la forêt, et faites-vous-y un défrichement dans le pays des Périzzites et des Rephaïms, puisque vous êtes à l\'étroit dans la montagne d\'Ephraïm!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Et les fils de Joseph dirent: La montagne est inaccessible pour nous, et il y a des chars ferrés chez tous les Cananéens qui habitent la région de la vallée, chez ceux qui sont dans Béth-Sean et ses annexes, et chez ceux qui sont dans la vallée de Jizréel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Et Josué dit à la maison de Joseph, à Ephraïm et à Manassé: Vous êtes un peuple nombreux et votre force est grande; vous n\'aurez pas un simple lot,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'mais la montagne sera à vous; puisque c\'est une forêt, défrichez-la, et ses issues seront à vous. Car vous expulserez les Cananéens, parce qu\'ils ont des chars ferrés, parce qu\'ils sont puissants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Et toute l\'Assemblée des enfants d\'Israël fut convoquée à Silo, et ils y dressèrent la Tente du Rendez-vous, le pays se trouvant soumis devant eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Et parmi les enfants d\'Israël il restait sept Tribus auxquelles on n\'avait pas distribué leurs lots.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Alors Josué dit aux enfants d\'Israël: Jusques à quand montrerez-vous cette nonchalance à venir occuper le pays que l\'Éternel, Dieu de vos pères, vous a donné?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Faites votre choix de trois hommes par Tribu afin que je les délègue et qu\'ils se mettent en route et parcourent le pays pour en dresser par écrit l\'état en raison de leur lot et ensuite me rejoindre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Et partagez-vous-le en sept portions. Juda est maintenu dans son territoire au midi et la maison de Joseph dans son territoire au nord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Or vous dresserez par écrit cet état du pays en sept parties, puis vous me l\'apporterez ici, et je tirerai au sort pour vous ici devant l\'Éternel, notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Car les Lévites n\'ont aucune portion parmi vous, parce que le sacerdoce de l\'Éternel est leur lot; et Gad et Ruben et la demi-Tribu de Manassé ont reçu leur lot au delà du Jourdain, au levant, lorsque Moïse, serviteur de l\'Éternel, le leur a donné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Alors ces hommes se mirent en devoir et partirent. Et Josué donna à ceux qui allaient dresser par écrit l\'état du pays ses ordres en ces termes: Allez et parcourez le pays et dressez-en l\'état par écrit; puis venez me rejoindre, et ici je tirerai au sort pour vous devant l\'Éternel à Silo.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Ces hommes partirent donc, et ils firent leurs courses dans le pays et en transcrivirent l\'état, divisé d\'après les villes en sept parties, dans un registre; puis ils rejoignirent Josué dans le camp à Silo.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Alors Josué tira pour eux au sort à Silo devant l\'Éternel. Ainsi Josué y répartit le pays aux enfants d\'Israël selon leurs divisions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Et un lot fut tiré pour la Tribu des fils de Benjamin selon leurs familles. Et les limites de leur lot étaient comprises entre les fils de Juda et les fils de Joseph.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Et au côté nord leur frontière partait du Jourdain, puis s\'élevant sur le versant septentrional de Jéricho elle atteignait la montagne vers l\'occident pour aboutir au désert de Beth-Aven.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'De là elle continuait jusqu\'à Luz, au versant méridional de Luz, c\'est-à-dire, de Béthel, puis descendait à Ataroth-Addar sur la montagne située au midi de Beth-Horon la basse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Puis elle suivait une ligne tournant du côté de l\'occident au midi de la montagne située en face de Beth-Horon au midi pour aboutir à Kiriath-Baal, c\'est-à-dire, Kiriath-Jearim, ville des fils de Juda. C\'est le côté occidental.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Et le côté méridional commençait à l\'extrémité de Kiriath-Jearim, et la frontière courait à l\'occident pour arriver à la Fontaine des Eaux de Nephthoah, puis elle descendait au bout de la montagne située devant la vallée des fils de Hinnom, dans la vallée de Rephaïm au nord,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'et descendait dans la vallée de Hinnom, au versant méridional des Jébusites, descendant encore jusqu\'à la Fontaine de l\'Espion,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'puis elle se dirigeait au nord et courait vers la Fontaine du Soleil, et de là vers Geliloth située vis-à-vis de la hauteur d\'Adummim et descendait à la Pierre de Bohan, fils de Ruben,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'et elle continuait au côté septentrional devant Araba et descendait vers Araba,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'et passait au côté septentrional de Beth-Hogla pour aboutir à la pointe septentrionale de la Mer Salée à l\'extrémité méridionale du Jourdain. C\'est la frontière méridionale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Et le Jourdain marque la limite orientale. Tel est le lot des fils de Benjamin, selon leurs frontières dans leur pourtour, selon leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Et les villes de la Tribu des fils de Benjamin selon leurs familles sont: Jéricho, Beth-Hogla, Hémek, Ketsits,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Beth-Araba, Tsémaraïm, Béthel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Avvim, Para, Ophra,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Kephar, Ammonaï, Ophni et Geba: douze villes et leurs villages;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gabaon, Rama, Beéroth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Mitspeh, Kephîra, Motsa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jirpéel, Thareala;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'et Tsela, Eleph, Jébus, c\'est-à-dire, Jérusalem, Gibeath, Kiriath: quatorze villes et leurs villages. Tel est le lot des fils de Benjamin selon leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Et le second lot tiré fut pour Siméon, pour la Tribu des fils de Siméon selon leurs familles, et leur lot était enclavé dans le lot des fils de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Et dans leur lot entrait Béer-Séba et Séba et Molada');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'et Hatsar-Sual, et Bala et Atsem');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'et Eltholad et Bethul et Horma,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'et Tsiklag et Beth-Marecaboth, et Hatsar-Sussa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'et Beth-Lebaoth et Saruhen: treize villes et leurs villages;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Aïn, Rimmon et Ether, et Asan, quatre villes et leurs villages;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'et tous les villages aux environs de ces villes jusqu\'à Baalath-Beer, Ramath-Négeb. Tel est le lot de la Tribu des fils de Siméon selon leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Le lot des fils de Siméon fut pris sur le territoire des fils de Juda, car la portion des fils de Juda était trop grande pour ceux-ci, et c\'est ainsi que les fils de Siméon reçurent un lot enclavé dans celui de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Et le troisième lot tiré fut pour les fils de Zabulon selon leurs familles. Et la limite de leur lot allait jusqu\'à Sarid.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Et leur frontière montait à l\'occident et jusqu\'à Mareala et touchait à Dabbeseth et touchait à la rivière qui coule devant Jockneam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Et de Sarid elle tournait à l\'orient vers le levant sur la frontière de Ghisloth-Thabor et continuait jusqu\'à Dabrath, puis montait à Japhia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Et de là elle passait à l\'orient, au levant à Githa-Hépher, Eth-Katsin, puis continuait jusqu\'à Rimmon qui se prolonge jusqu\'à Nea,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'autour de laquelle tournant au nord du côté de Hannathon elle allait aboutir dans la vallée de Jiphthah-El.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Et Kattath et Nahalal et Simron et Jideala et Beth-Lehem: douze villes avec leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Tel est le lot des fils de Zabulon, selon leurs familles, ces villes et leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Le quatrième lot fut tiré pour Issaschar, pour les fils d\'Issaschar selon leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Et leur frontière allait jusqu\'à Jizréel et Chesulloth et Sunem');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'et Hapharaïm et Sîon et Anaharath');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'et Rabbith et Kisèon et Abets,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'et Remeth et Ein-Gannim et Ein-Hadda et Beth-Patsets.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Et la frontière touchait au Thabor et à Sahatsima et Beth-Semés, et elle aboutissait au Jourdain: seize villes avec leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Tel est le lot de la Tribu des fils d\'Issaschar, selon leurs familles, leurs villes et leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Et le cinquième lot tiré fut pour la Tribu des fils d\'Asser, selon leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Et leur frontière était: Helkath et Hali et Beten et Acsaph');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'et Allammélech et Amead et Miseal, et elle touchait au Carmel à l\'occident et au Sihor-Libnath,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'puis elle tournait au levant vers Beth-Dagon et touchait à Zabulon et à la vallée de Jiphthah-El au nord de Beth-Aëmek et de Neïel et se prolongeait vers Chabul à gauche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'et vers Ebron et Rehob et Hammon et Kana jusqu\'à Sidon, la grande;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'puis la frontière tournait vers Rama, jusqu\'à la ville forte de Tyr, ensuite tournait vers Hosa et aboutissait à la mer à partir du district vers Achsib.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Et Umma et Aphek et Rehob: vingt-deux villes avec leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Tel est le lot de la Tribu des fils d\'Asser, selon leurs familles, ces villes-là et leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Pour les fils de Nephthali fut tiré le sixième lot, pour les fils de Nephthali selon leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Et leur frontière s\'étendait depuis Heleph, depuis le chêne près de Tsaenannim et Adami-Nekeb et Jabnéel jusqu\'à Laccum pour aboutir au Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Et la frontière tournait à l\'occident vers Aznoth-Thabor et de là courait à Huccoc et touchait à Zabulon au midi, et à Asser à l\'occident et à Juda sur le Jourdain du côté du levant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Villes fortes: Tsiddim, Tser et Hammath, Raccath et Chinnereth');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'et Adama et Rama et Hatsor');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'et Kédès, Edreï et Ein-Hatsor');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'et Jiréon et Migdal-El, Horem et Beth-Anath et Beth-Semès: dix-neuf villes avec leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Tel est le lot de la Tribu des fils de Nephthali selon leurs familles, les villes et leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Le septième lot fut tiré pour la Tribu des fils de Dan selon leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Et la frontière de leur lot était Tsorea et Esthaol et Ir-Semes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'et Sahélabbim et Ajalon et Jithla');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'et Elon et Thimnata et Ecron');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'et Elthékè et Gibethon et Baalath');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'et Jehud et Bnei-Berak et Gath-Rimmon');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'et Mei-Jarcon et Rakkon avec le territoire vis-à-vis de Japho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Et le territoire des fils de Dan s\'étendit au delà de leurs limites, et les fils de Dan se mirent en campagne, et ils attaquèrent Lesem et la prirent, et ils la frappèrent avec le tranchant de l\'épée, et en prirent possession et s\'y établirent et l\'appelèrent Lesem-Dan, du nom de Dan, leur père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Tel est le lot de la Tribu des fils de Dan, selon leurs familles, ces villes-là et leurs villages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Et lorsqu\'ils eurent achevé de répartir le pays selon ses limites, les enfants d\'Israël donnèrent à Josué, fils de Nun, une propriété au milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Sur l\'ordre de l\'Éternel, ils lui donnèrent la ville qu\'il demandait, Thimnath-Sera, dans la montagne d\'Ephraïm. Et il rebâtit la ville et s\'y établit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Tels sont les lots que distribuèrent le Prêtre Eléazar et Josué, fils de Nun, et les Chefs de famille des Tribus des enfants d\'Israël par le sort à Silo devant l\'Éternel à l\'entrée de la Tente du Rendez-vous, et ainsi fut terminé le partage du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Et l\'Éternel parla à Josué en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Parle aux enfants d\'Israël en ces termes: Établissez-vous des Villes de Refuge, comme je vous l\'ai dit par l\'organe de Moïse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'qui servent d\'asile à l\'homicide qui aura tué une personne par mégarde, sans intention; et qu\'elles soient pour vous un refuge contre le vengeur du sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Et qu\'il se réfugie dans l\'une de ces villes-là, et qu\'il se présente à l\'entrée de la Porte de la ville et qu\'il expose son cas aux oreilles des Anciens de cette ville-là; et ils le recueilleront vers eux dans la ville et lui accorderont un domicile pour y demeurer dans son enceinte avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Et, si le vengeur du sang le poursuit, on ne livrera pas l\'homicide entre ses mains, car c\'est sans intention qu\'il a tué son prochain, et il ne le haïssait ni d\'hier, ni d\'avant-hier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Et il restera dans cette même ville jusqu\'à ce qu\'il ait comparu devant l\'Assemblée pour être jugé, jusqu\'à la mort du Grand-Prêtre qui existera dans ce temps-là. Alors l\'homicide pourra s\'en retourner et rentrer dans sa ville et dans sa maison, dans la ville d\'où il s\'était enfui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Et ils consacrèrent Kédès en Galilée dans la montagne de Nephthali et Sichem dans la montagne d\'Ephraïm et Kiriath-Arba, c\'est-à-dire, Hébron dans la montagne de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Et au delà du Jourdain vers Jéricho à l\'orient ils désignèrent Betser dans le désert dans la plaine, de la Tribu de Ruben, et Ramoth en Galaad, de la Tribu de Gad, et Golan en Basan, de la Tribu de Manassé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Telles furent les villes assignées à tous les enfants d\'Israël et à l\'étranger en séjour chez eux, pour servir d\'asile à quiconque tuerait une personne par mégarde, afin qu\'il ne meure pas de la main du vengeur du sang, jusqu\'à ce qu\'il ait comparu devant l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Et les Chefs de famille des Lévites s\'approchèrent du Prêtre Eléazar et de Josué, fils de Nun, et des Chefs de famille des Tribus des enfants d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'et leur parlèrent à Silo, dans le pays de Canaan, en ces termes: L\'Éternel a ordonné par l\'organe de Moïse qu\'on nous donne des villes pour nous loger, avec leurs banlieues pour notre bétail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Alors les enfants d\'Israël donnèrent aux Lévites, sur leur propriété, d\'après l\'ordre de l\'Éternel, ces villes et leurs banlieues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Et le sort fut tiré pour les familles des Kahathites. Et les fils du Prêtre Aaron d\'entre les Lévites obtinrent par le sort, de la Tribu de Juda et de la Tribu de Siméon et de la Tribu de Benjamin, treize villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Et les fils de Kahath restants obtinrent par le sort, des familles de la Tribu d\'Ephraïm et de la Tribu de Dan et de la demi-Tribu de Manassé, dix villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Et les fils de Gerson obtinrent par le sort, des familles de la Tribu d\'Issaschar et de la Tribu d\'Asser et de la Tribu de Nephthali et de la [seconde] moitié de la Tribu de Manassé en Basan, treize villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Les fils de Merari, en raison de leurs familles, obtinrent de la Tribu de Ruben et de la Tribu de Gad et de la Tribu de Zabulon, douze villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Ainsi les enfants d\'Israël donnèrent par le sort aux Lévites ces villes-là et leurs banlieues, comme l\'Éternel l\'avait ordonné par l\'organe de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Et de la Tribu des fils de Juda, et de la Tribu des fils de Siméon ils donnèrent ces villes qui vont être indiquées nominativement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'Aux fils d\'Aaron, familles des Kahathites, enfants de Lévi (car ils eurent le premier lot)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'ils donnèrent la ville d\'Arba (celui-ci est le père des Anakites), c\'est-à-dire, Hébron dans la montagne de Juda et sa banlieue d\'alentour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Quant à la campagne de la ville et à ses villages, ils les donnèrent à Caleb, fils de Jéphuné, en propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Et aux fils du Prêtre Aaron ils donnèrent la ville de refuge pour l\'homicide, Hébron et sa banlieue, et Libna et sa banlieue');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'et Jatkthir et sa banlieue, et Esthmoa et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'et Holon et sa banlieue, et Débir et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'et Aïn et sa banlieue, et Jutta et sa banlieue, et Beth-Semès et sa banlieue: neuf villes de ces deux Tribus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'et de la Tribu de Benjamin, Gabaon et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'et Geba et sa banlieue: et Anathoth et sa banlieue, et Almon et sa banlieue, quatre villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Total des villes des Prêtres, fils d\'Aaron: treize villes avec leurs banlieues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Et quant aux familles des fils de Kahath, Lévites restants des fils de Kahath, les villes de leur lot étaient de la Tribu d\'Ephraïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Et ils leur donnèrent la ville de refuge pour l\'homicide, Sichem et sa banlieue dans la montagne d\'Ephraïm, et Gézer et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'et Kibtsaïm et sa banlieue, et Beth-Horon et sa banlieue: quatre villes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'et de la Tribu de Dan, Elthékê et sa banlieue, Gibthon et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajalon et sa banlieue, Gath-Rimmon et sa banlieue: quatre villes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'et de la demi-Tribu de Manassé, Thaënach et sa banlieue, et Gath-Rimmon et sa banlieue: deux villes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'total, dix villes avec leurs banlieues pour les familles des fils de Kahath restants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Et aux fils de Gerson, des familles des Lévites, de la demi-Tribu de Manassé, la ville de refuge pour l\'homicide, Golan en Basan et sa banlieue, et Béesthra et sa banlieue: deux villes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'et de la Tribu d\'Issaschar, Kisjon et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Dabrath et sa banlieue, Jarmuth et sa banlieue, Ein-Gannim et sa banlieue: quatre villes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'et de la Tribu d\'Asser, Miseal et sa banlieue, Abdon et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkath et sa banlieue, et Rehob et sa banlieue: quatre villes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'et de la Tribu de Nephthali, la ville de refuge pour l\'homicide, Kédès en Galilée et sa banlieue, et Hammoth-Dor et sa banlieue, et Karthan et sa banlieue: trois villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Total des villes des Gersonites, en raison de leurs familles: treize villes avec leurs banlieues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Et aux familles des fils de Merari, Lévites restants, de la Tribu de Zabulon, Jockneam et sa banlieue, Kartha et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimna et sa banlieue, Nahalal et sa banlieue: quatre villes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'et de la Tribu de Ruben, Betser, et sa banlieue, et Jahtsah et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedémoth et sa banlieue, et Mephaath et sa banlieue: quatre villes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'et de la Tribu de Gad, la ville de refuge pour l\'homicide, Ramoth en Galaad et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'et Mahanaïm et sa banlieue, Hesbon et sa banlieue, Jaëzer et sa banlieue; total des villes: quatre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Total des villes des fils de Merari, selon leurs familles, du reste des familles des Lévites, lot qui leur échut: douze villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Total des villes des Lévites enclavées dans la propriété des enfants d\'Israël, quarante-huit villes avec leurs banlieues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Et ces villes avaient chacune sa banlieue qui l\'entourait; ainsi en était-il de toutes ces villes-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'C\'est ainsi que l\'Éternel donna aux Israélites tout le pays qu\'il avait juré de donner à leurs pères, et ils en prirent possession et s\'y établirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Et l\'Éternel leur donna repos de tous les côtés conformément à la totalité du serment qu\'il avait fait à leurs pères. Et aucun de leurs ennemis ne tint devant eux; l\'Éternel livra tous leurs ennemis entre leurs mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Et de toutes les excellentes promesses que l\'Éternel avait faites à la maison d\'Israël, aucune ne tomba, tout s\'accomplit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Alors Josué manda les Rubénites, les Gadites et la demi-Tribu de Manassé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'et il leur dit: Vous avez observé tout ce que vous a prescrit Moïse, serviteur de l\'Éternel, et obéi à ma voix dans tout ce que je vous ai commandé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Vous n\'avez point abandonné vos frères pendant ce long temps jusqu\'aujourd\'hui, et vous avez observé ce qu\'il fallait observer, le commandement de l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Et maintenant l\'Éternel, votre Dieu, a accordé le repos à vos frères, comme Il le leur avait promis; retournez donc et gagnez vos tentes, le pays qui est votre propriété, que vous a concédé Moïse, serviteur de l\'Éternel, au delà du Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Seulement soyez très vigilants à mettre en pratique le commandement et la Loi que vous a prescrite Moïse, serviteur de l\'Éternel, pour aimer l\'Éternel, votre Dieu, et pour marcher dans toutes ses voies et garder ses commandements et vous attacher à Lui et Le servir de tout votre cœur et de toute votre âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Et Josué les bénit et les congédia, et ils regagnèrent leurs tentes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Or Moïse avait doté une moitié de la Tribu de Manassé en Basan, et Josué avait doté l\'autre moitié avec leurs frères en deçà du Jourdain à l\'occident. Et aussi lorsque Josué leur permit de regagner leurs tentes, il les bénit');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'et leur parla en ces termes: C\'est avec de grandes richesses que vous retournez à vos tentes, et avec des bestiaux très nombreux, avec de l\'argent et de l\'or et de l\'airain et du fer et des vêtements en très grande quantité. Partagez le butin de vos ennemis avec vos frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Ainsi s\'en retournèrent et partirent les fils de Ruben et les fils de Gad et une moitié de la Tribu de Manassé, d\'avec les enfants d\'Israël, de Silo dans le pays de Canaan, pour gagner le pays de Galaad, le pays qui était leur propriété, dont ils avaient pris possession sur l\'ordre de l\'Éternel, transmis par Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Et étant arrivés aux districts du Jourdain dans le pays de Canaan, les fils de Ruben et les fils de Gad et la demi-Tribu de Manassé, bâtirent là un autel sur le Jourdain, autel d\'une grande apparence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Et les enfants d\'Israël ouïrent dire: Voilà que les fils de Ruben et les fils de Gad et de la demi-Tribu de Manassé ont bâti l\'autel en vue du pays de Canaan, dans les districts du Jourdain en face des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Et les enfants d\'Israël l\'ayant appris, toute l\'Assemblée des enfants d\'Israël se réunit à Silo pour se mettre en campagne contre eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Et les enfants d\'Israël députèrent vers les fils de Ruben et les fils de Gad et la demi-Tribu de Manassé au pays de Galaad, Phinées, fils du Prêtre Eléazar,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'et dix Princes avec lui, un Prince par maison de toutes les Tribus d\'Israël, et ils étaient chacun chefs de leurs maisons patriarcales des divisions d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Et ils se rendirent auprès des fils de Ruben et des fils de Gad et de la demi-Tribu de Manassé au pays de Galaad, et ils leur parlèrent en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Ainsi dit toute l\'Assemblée de l\'Éternel: Qu\'est-ce que ce crime dont vous vous rendez coupables envers le Dieu d\'Israël, pour vous détourner aujourd\'hui de l\'Éternel en vous bâtissant un autel pour vous rebeller aujourd\'hui contre l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Est-ce trop peu pour nous que la faute de Pehor dont nous ne sommes pas purifiés jusqu\'à ce jour et qui a attiré la plaie sur l\'Assemblée de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Et vous, vous vous détournez aujourd\'hui de l\'Éternel! mais si vous vous rebellez aujourd\'hui contre l\'Éternel, demain Il se courroucera contre toute l\'Assemblée d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Cependant si le pays qui est votre lot, est impur, passez dans le pays qui est la propriété de l\'Éternel où est fixée la Résidence de l\'Éternel et prenez possession au milieu de nous; mais ne vous rebellez pas contre l\'Éternel, et ne faites pas défection d\'avec nous en vous bâtissant un autel en dehors de l\'Autel de l\'Éternel, notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Hacan, fils de Zérah, ne s\'est-il pas rendu coupable de crime en touchant aux choses dévouées? et une vengeance fondit sur toute l\'Assemblée d\'Israël; et il n\'a pas été le seul à périr en suite de sa faute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Alors les fils de Ruben et les fils de Gad et la demi-Tribu de Manassé répondirent et dirent aux Chefs des divisions d\'Israël:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Dieu, Dieu, l\'Éternel, Dieu, Dieu, l\'Éternel sait, et Israël doit savoir si c\'est par une rébellion, par un crime contre l\'Éternel (ne nous donne pas Ton aide en ce jour!)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'que nous nous sommes bâti un autel, pour nous détourner de l\'Éternel; et si c\'est pour y offrir des holocaustes et des offrandes, et si c\'est pour y faire des sacrifices pacifiques, que l\'Éternel nous recherche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'et si ce n\'est pas par un souci, par une raison que nous l\'avons fait en disant: A l\'avenir vos fils diront à nos fils: « Qu\'avez-vous de commun avec l\'Éternel, Dieu d\'Israël?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Aussi bien l\'Éternel a mis entre nous et vous, fils de Ruben et fils de Gad, pour limite le Jourdain: vous n\'avez point part à l\'Éternel. » Et ainsi vos fils empêcheront nos fils de craindre l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'C\'est pourquoi nous avons dit: Mettons-nous donc à bâtir un autel, non point pour holocaustes et victimes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'mais afin qu\'il soit un témoin entre nous et vos fils, et nos descendants après nous, que nous pratiquons le culte de l\'Éternel devant Lui avec nos holocaustes et nos victimes et nos sacrifices pacifiques, pour que dans l\'avenir vos fils ne disent pas à nos fils: « Vous n\'avez point part à l\'Éternel! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Et nous dîmes: Dans le cas où ils tiendraient ce langage à nous ou à nos descendants dans l\'avenir, nous répondrons: Voyez la structure de l\'autel de l\'Éternel qu\'ont fait nos pères, non point pour y offrir des holocaustes et des victimes, mais il est un témoin entre nous et vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Loin de nous la pensée de nous rebeller contre l\'Éternel, et de nous détourner aujourd\'hui de l\'Éternel en bâtissant un autel pour holocaustes, offrandes et victimes, en dehors de l\'Autel de l\'Éternel, notre Dieu, qui est devant sa Résidence!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Et lorsque le Prêtre Phinées et les Princes de l\'Assemblée et les Chefs des divisions d\'Israël qui l\'accompagnaient, eurent entendu les paroles que prononcèrent les fils de Ruben et les fils de Gad et les fils de Manassé, ils furent satisfaits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Et Phinées, fils du Prêtre Eléazar, dit aux fils de Ruben et aux fils de Gad et aux fils de Manassé: Aujourd\'hui nous reconnaissons que l\'Éternel est au milieu de nous, puisque vous ne vous êtes pas rendus coupables envers l\'Éternel d\'un tel crime. Maintenant vous avez sauvé les enfants d\'Israël de la main de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Alors Phinées, fils du Prêtre Eléazar, et les Princes quittant les fils de Ruben et les fils de Gad, revinrent du pays de Galaad dans le pays de Canaan auprès des enfants d\'Israël, et ils leur rendirent compte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Et les enfants d\'Israël furent satisfaits, et les enfants d\'Israël bénirent Dieu et ils ne parlèrent plus de marcher contre eux pour ravager le pays qu\'habitaient les fils de Ruben et les fils de Gad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Et les fils de Ruben et les fils de Gad donnèrent à l\'autel ce nom: « Car il est témoin entre nous que l\'Éternel est Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Et un long temps s\'étant écoulé, après que l\'Éternel eut donné le repos à Israël vis-à-vis de tous ses ennemis à la ronde, et lorsque Josué fut devenu vieux et avancé en âge, Josué');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'convoqua tout Israël, ses Anciens et ses Chefs et ses Juges et ses Officiers, et il leur dit: Je suis vieux et avancé en âge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Et vous avez vu tout ce que l\'Éternel, votre Dieu, a fait à tous ces peuples devant vous. Car l\'Éternel, votre Dieu, lui-même, a combattu pour vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Voyez, je vous ai fait échoir en propriété pour vos Tribus ces peuples qui ont survécu, depuis le Jourdain, et tous les peuples que j\'ai exterminés jusqu\'à la Grande Mer, où le soleil se couche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Et l\'Éternel, votre Dieu, lui-même, leur donnera la chasse devant vous et les dépossédera devant vous, et vous vous emparerez de leur pays, comme l\'Éternel, votre Dieu, vous l\'a promis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Tenez ferme à l\'observation et à la pratique de tout ce qui est écrit dans le livre de la loi de Moïse, sans vous écarter ni à droite ni à gauche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'sans vous mêler à ces nations qui restent près de vous, et sans rappeler le nom de leurs dieux, et sans faire jurer par eux, et sans leur rendre ni culte, ni hommage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'mais c\'est à l\'Éternel, votre Dieu, que vous vous attacherez, ainsi que vous l\'avez fait jusqu\'à ce jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Aussi bien l\'Éternel a chassé devant vous de grandes et fortes nations, et personne ne vous a tenu tête jusqu\'à ce jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Un seul d\'entre vous en poursuit mille, parce que l\'Éternel, votre Dieu, lui-même, combat pour vous, comme il vous l\'a promis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Faites donc bien attention en vous-mêmes d\'aimer l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Car, si vous vous détournez et vous vous attachez au résidu de ces nations qui ont été laissées près de vous, et si vous contractez des mariages chez elles, et que vous vous mêliez à elles et elles à vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'sachez bien que l\'Éternel, votre Dieu, ne continuera pas à chasser ces nations devant vous, et elles seront pour vous un piège et un lacs et une verge pour vos flancs et des épines dans vos yeux, jusqu\'à ce que vous soyez exterminés de ce beau pays que vous a donné l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Et voici, je fournis maintenant la carrière de tout ce qui est de la terre. Reconnaissez donc de tout votre cœur et de toute votre âme qu\'aucune des belles promesses que vous a faites l\'Éternel, votre Dieu, n\'est tombée: tout s\'est accompli pour vous, pas un mot n\'en est tombé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Mais de même que se sont accomplies pour vous toutes les promesses que vous a faites l\'Éternel, votre Dieu, de même l\'Éternel accomplira sur vous toutes les menaces, jusqu\'à ce qu\'il vous ait exterminés de ce beau pays que l\'Éternel, votre Dieu, vous a donné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Dès que vous transgresserez l\'alliance que l\'Éternel, votre Dieu, vous a prescrite et dès que vous irez vous mettre au service d\'autres dieux et les adorer, la colère de l\'Éternel s\'allumera contre vous, et vous serez bientôt exterminés du beau pays qu\'il vous a donné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Et Josué réunit toutes les Tribus d\'Israël à Sichem, et manda les Anciens d\'Israël et ses Chefs et ses Juges et ses Officiers, et ils se présentèrent devant Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Et Josué dit à tout le peuple: Ainsi parle l\'Éternel, Dieu d\'Israël: Dans les anciens temps vos pères, Thérah, père d\'Abraham et père de Nachor, habitaient au delà du Fleuve, et servaient d\'autres dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Alors je pris votre père Abraham d\'au delà du Fleuve, et je lui fis parcourir tout le pays de Canaan, et je multipliai sa race, et lui donnai Isaac.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Et je donnai à Isaac Jacob et Esaü, et je donnai à Esaü la montagne de Séir pour l\'occuper; et Jacob et ses fils descendirent en Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Et j\'envoyai Moïse et Aaron et je frappai l\'Egypte ainsi que je l\'ai fait au milieu d\'elle; après quoi je vous en retirai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Je retirai donc vos pères de l\'Egypte et vous arrivâtes à la mer et les Égyptiens poursuivirent vos pères avec des chars et de la cavalerie jusqu\'à la Mer aux algues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Alors ils crièrent vers l\'Éternel, et Il mit des ténèbres entre vous et les Égyptiens, et ramena la mer sur eux et les submergea, et vos yeux virent comment je traitai les Égyptiens, et vous fîtes un long séjour dans le désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Et je vous amènerai dans le pays des Amoréens établis au delà du Jourdain, et quand ils vous firent la guerre, je les livrai entre vos mains et vous conquîtes leur pays et je les fis disparaître devant vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Alors Balak, fils de Tsippor, roi de Moab, se mit en mouvement et attaqua Israël, et il envoya quérir Balaam, fils de Behor, pour vous maudire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Mais je ne voulus pas écouter Balaam, et il dut vous bénir, et je vous arrachai de sa main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Et lorsque, après avoir passé le Jourdain, vous fûtes venus à Jéricho, les maîtres de Jéricho se mesurèrent avec vous, les Amoréens, les Perizzites, les Cananéens, les Héthiens et les Gergésites et les Hévites et les Jébusites, et je les livrai entre vos mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Et je vous fis précéder par les frelons qui les chassèrent devant vous, les deux rois des Amoréens, et ce ne fut pas au moyen de votre épée et de votre arc.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Et je vous donnai un pays que vous n\'aviez point cultivé, et des villes que vous n\'aviez point bâties, et vous vous y êtes établis; vous jouissez de vignes et d\'olivaies que vous n\'avez point plantées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Maintenant donc craignez l\'Éternel et servez-le sans partage et en vérité, et défaites-vous des dieux que vos pères servirent au delà du Fleuve et en Egypte, et servez l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Et si vous ne vous souciez pas de servir l\'Éternel, faites aujourd\'hui votre choix de qui vous voulez servir, soit des dieux que vos pères ont servis au delà du Fleuve, soit des dieux des Amoréens dont vous habitez le pays; quant à moi et à ma maison, nous servirons l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Alors le peuple répondit et dit: Loin de nous la pensée de quitter l\'Éternel pour servir d\'autres dieux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Car l\'Éternel est notre Dieu; c\'est Lui qui nous a retirés, nous et nos pères, du pays d\'Égypte, de la maison de servitude et qui a opéré devant nos yeux ces grands signes, et nous a eus en sa garde pendant toute la route que nous avons faite, et au milieu de tous les peuples au travers desquels nous avons percé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Et l\'Éternel a chassé devant nous tous les peuples et les Amoréens établis dans le pays; nous voulons, nous aussi, servir l\'Éternel, car Il est notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Et Josué dit au peuple: Vous n\'êtes pas à même de servir l\'Éternel, car Il est un Dieu saint, un Dieu jaloux; Il ne pardonnera pas vos désobéissances et vos péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Si vous quittez l\'Éternel pour servir des dieux de l\'étranger, Il changera, et Il vous maltraitera, et vous exterminera après avoir été votre bienfaiteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Et le peuple dit à Josué: Non! car c\'est l\'Éternel que nous servirons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Et Josué dit au peuple: Vous êtes témoins contre vous-mêmes, que vous-mêmes vous avez fait votre choix de l\'Éternel pour le servir. Et ils répondirent: Témoins!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, '« En suite de cela défaites-vous des dieux étrangers qui sont au milieu de vous, et tournez vos cœurs vers l\'Éternel, Dieu d\'Israël. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Et le peuple dit à Josué: Nous servirons l\'Éternel, notre Dieu, et nous obéirons à sa voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Alors Josué conclut une alliance avec le peuple en ce jour même et lui fixa ainsi à Sichem une loi et un droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Et Josué transcrivit ces choses dans le Livre de la Loi de Dieu, et il prit une grande pierre qu\'il érigea là sous le chêne dans le lieu consacré à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Et Josué dit à tout le peuple: Voici, cette pierre sera un témoin contre nous, car elle a ouï toutes les paroles de l\'Éternel qu\'il nous a adressées; qu\'elle soit donc un témoin contre vous afin que vous ne reniiez pas votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Et Josué congédia le peuple pour que chacun se rendît dans sa propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Et après ces choses Josué, fils de Nun, serviteur de l\'Éternel, mourut à l\'âge de cent dix ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Et il reçut la sépulture dans le territoire de son lot à Thimnath-Sérah dans la montagne d\'Ephraïm au nord du mont Gaas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Et Israël servit l\'Éternel durant toute la vie de Josué et durant toute la vie des Anciens qui survécurent à Josué, et qui connaissaient tous les actes que l\'Éternel avait accomplis en faveur d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Et les os de Joseph que les enfants d\'Israël avaient ramenés de l\'Egypte, furent inhumés à Sichem dans la pièce de terre que Jacob avait achetée des fils de Hémor, père de Sichem, pour cent kesitas, et les fils de Joseph la reçurent en propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Et Eléazar, fils d\'Aaron, mourut, et il reçut la sépulture à Gibéa, ville de Phinées, son fils, laquelle lui avait été donnée dans la montagne d\'Ephraïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Et après la mort de Josué les enfants d\'Israël consultèrent l\'Éternel en disant: Lequel d\'entre nous doit marcher le premier contre les Cananéens pour les attaquer?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Et l\'Éternel dit: Juda marchera. Voici, j\'ai livré le pays entre ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Et Juda dit à Siméon, son frère: Accompagne-moi pour une expédition dans mon lot, et attaquons les Cananéens; à mon tour je t\'accompagnerai pour une expédition dans ton lot. Alors Siméon se mit en campagne avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Et Juda s\'avança, et l\'Éternel livra entre leurs mains les Cananéens et les Perizzites, et ils les défirent à Bézek au nombre de dix mille hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Et ils trouvèrent Adoni-Bézek à Bézek, et l\'ayant attaqué ils battirent les Cananéens et les Perizzites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Et Adoni-Bézek s\'enfuit et ils le poursuivirent et le prirent, et ils lui coupèrent les pouces aux mains et aux pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Alors Adoni-Bézek dit: Soixante-dix Rois ayant les pouces coupés aux mains et aux pieds en étaient à ramasser sous ma table: ce que j\'ai fait, Dieu me le rend. Et ils l\'emmenèrent à Jérusalem, et il mourut là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Et les enfants de Juda attaquèrent Jérusalem, et la prirent, et la frappèrent avec le tranchant de l\'épée et livrèrent la ville aux flammes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Ensuite les fils de Juda descendirent pour attaquer les Cananéens habitant la Montagne et le Midi et le Pays-bas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Et Juda marcha contre les Cananéens établis à Hébron (or le nom de Hébron était jadis Ville d\'Arba), et ils défirent Sesaï et Ahiman et Thalmaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Et de là ils marchèrent contre les habitants de Debir; or le nom de Debir était jadis Kiriath-Sépher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Et Caleb dit: A celui qui réduira et prendra Kiriath-Sépher, je donnerai pour femme Achsa ma fille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Et Othniel, fils de Kénaz, frère cadet de Caleb, la prit; et il lui donna pour femme sa fille Achsa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Et à son entrée chez lui elle l\'incita à demander un champ à son père; et de dessus l\'âne qu\'elle montait, elle mit pied à terre. Alors Caleb lui dit: Qu\'as-tu à dire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Et elle lui dit: Accorde-moi un bienfait! puisque tu m\'as donné une terre du midi, donne-moi aussi des sources d\'eau. Alors Caleb lui donna les sources supérieures et les sources inférieures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Et les fils de Kéni, beau-père de Moïse, firent depuis la Ville des Palmiers avec les fils de Juda une campagne dans le désert de Juda situé au midi d\'Arad, et ils allèrent s\'établir avec le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Et Juda se mit en marche avec Siméon, son frère, et ils défirent les Cananéens qui habitaient Tséphath, et ils la dévouèrent, et donnèrent à la ville le nom de Horma (anathème).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Et Juda prit Gaza et son territoire, et Askalon et son territoire, et Ekron et son territoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Et l\'Éternel fut avec Juda de sorte qu\'il se rendit maître de la montagne, car il ne put expulser les habitants de la plaine qui avaient des chars ferrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Et ils donnèrent Hébron à Caleb, d\'après ce que Moïse avait dit, et il en chassa les trois fils de Anak.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Et les fils de Benjamin n\'expulsèrent point les Jébusites établis à Jérusalem; et les Jébusites ont habité Jérusalem avec les fils de Benjamin jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Et la maison de Joseph aussi fit sa campagne contre Béthel, et l\'Éternel fut avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Et la maison de Joseph fit faire une reconnaissance à Béthel (or le nom de la ville était jadis Luz).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Et les vedettes aperçurent un homme qui sortait de la ville, et lui dirent: Indique-nous l\'accès de la ville et nous te montrerons de la bonté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Et il leur indiqua l\'accès de la ville. Et ils frappèrent la ville avec le tranchant de l\'épée; mais ils laissèrent échapper cet homme et toute sa famille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Et cet homme passa dans le pays des Héthiens et bâtit une ville qu\'il appela du nom de Luz; tel a été son nom jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Et Manassé ne déposséda point Beth-Séan et ses annexes, ni Thaanach et ses annexes, ni Dor et ses annexes, ni Jibléam et ses annexes, ni Megiddo et ses annexes, et les Cananéens persistèrent à se maintenir dans cette contrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Et lorsque Israël se fut consolidé, il soumit les Cananéens à la corvée, mais quant à les chasser, il ne le fit pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Et Ephraïm n\'expulsa point les Cananéens établis à Gézer, les Cananéens demeurèrent donc parmi eux à Gézer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zabulon n\'expulsa point les habitants de Kitron, ni les habitants de Nahalol; les Cananéens demeurèrent donc parmi eux, mais ils devinrent corvéables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Asser n\'expulsa point les habitants de Acco, ni les habitants de Sidon et d\'Ahelab et d\'Achsib et de Helba et d\'Aphik et de Rehob;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'et ainsi les Assérites demeurèrent au milieu des Cananéens, habitants du pays, car ils ne les expulsèrent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Nephthali n\'expulsa point les habitants de Beth-Semès, ni les habitants de Beth-Anath, et il demeura au milieu des Cananéens, habitants du pays. Mais les habitants de Beth-Semès et de Beth-Anath furent soumis par lui à la corvée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Et les Amoréens repoussèrent les Danites dans la montagne, car ils ne leur permirent pas de descendre dans la vallée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Et les Amoréens persistèrent à habiter Har-Herès, Ajalon et Saalbim; mais ils sentirent le poids de la main de la maison de Joseph et devinrent corvéables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Et le territoire des Amoréens s\'étendait de la hauteur des Scorpions, de Séla en haut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Alors un Envoyé de l\'Éternel arriva de Guilgal à Bochim, et dit: [Ainsi ai-je parlé]: Je veux vous retirer de l\'Egypte, et vous amener dans le pays que j\'ai promis par serment à vos pères. Et j\'ai dit: Jamais je n\'annulerai l\'alliance que j\'ai faite avec vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Vous de votre côté vous n\'accorderez aucune alliance aux habitants de ce pays; vous mettrez leurs autels en ruine. Mais vous n\'avez pas obéi à ma voix: pourquoi en avez-vous agi ainsi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Or je dis aussi: Je ne les chasserai point devant vous, afin qu\'ils deviennent des ennemis pour vous; et leurs dieux seront un piège pour vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Et lorsque l\'Envoyé de l\'Éternel disait ces choses à tous les enfants d\'Israël, le peuple éleva la voix et pleura.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Et ils donnèrent à ce lieu le nom de Bochim (les pleurants). Et ils firent là un sacrifice à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Et Josué licencia le peuple, et les enfants d\'Israël s\'en allèrent chacun dans sa propriété pour prendre possession du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Et le peuple servit l\'Éternel durant toute la vie de Josué et durant toute la vie des Anciens qui prolongèrent leurs jours après Josué et qui avaient vu tous les grands faits accomplis par l\'Éternel pour Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Et Josué, fils de Nun, serviteur de l\'Éternel, mourut âgé de cent dix ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Et il reçut la sépulture dans le domaine qui lui était échu à Thimnath-Herès, sur la montagne d\'Ephraïm au nord du mont Gaas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Et toute cette génération-là fut aussi recueillie auprès de ses pères, et une autre génération lui succéda, qui ne connaissait point l\'Éternel, ni les faits accomplis par Lui pour Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Et les enfants d\'Israël firent ce qui déplaît à l\'Éternel, et servirent les Baals.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Et ils quittèrent l\'Éternel, Dieu de leurs pères, qui les avait retirés du pays d\'Egypte, et ils s\'attachèrent à d\'autres dieux parmi les dieux des peuples de leurs alentours, et les adorèrent et irritèrent l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Et ils quittèrent l\'Éternel pour servir Baal, et les Astartés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Alors la colère de l\'Éternel s\'alluma contre Israël et Il les abandonna aux mains des spoliateurs qui les dépouillèrent, et Il les vendit entre les mains de leurs ennemis d\'alentour; et ils ne purent plus tenir tête à leurs ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Et partout où ils se portaient, ils trouvaient contre eux la main de l\'Éternel, hostile, selon la menace de l\'Éternel et selon le serment qu\'il leur en avait fait. Et ils furent fort à la gêne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Cependant l\'Éternel suscita des Juges qui les sauvèrent des mains de leurs spoliateurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Mais ils n\'obéirent pas non plus à leurs Juges, car ils se prostituèrent à des dieux étrangers qu\'ils adorèrent; bientôt ils s\'écartèrent de la voie qu\'avaient suivie leurs pères en obéissant aux ordres de l\'Éternel; ils ne les imitèrent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Et lorsque l\'Éternel leur suscitait des Juges, l\'Éternel était avec le Juge et les sauvait de la main de leurs ennemis pendant toute la vie du Juge. Car l\'Éternel se laissait toucher par leurs plaintes contre ceux qui les opprimaient et les tourmentaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Mais à la mort du Juge il arrivait que de nouveau ils se dépravaient plus que leurs pères en suivant d\'autres dieux pour les servir et les adorer. Ils ne retranchèrent rien de leurs vices, ni de leur conduite obstinée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Alors la colère de l\'Éternel s\'alluma contre Israël, et Il dit: Puisque ce peuple a transgressé mon alliance que j\'avais prescrite à leurs pères, et n\'a pas été docile à ma voix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'moi de même je ne chasserai plus devant eux un seul homme des nations qu\'à sa mort Josué laissa survivre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'afin de mettre par elles Israël à cette épreuve: tiendront-ils la voie de l\'Éternel pour y marcher comme l\'ont tenue leurs pères, ou non?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'L\'Éternel laissa donc ces nations tranquilles sans se presser de les expulser et sans les livrer aux mains de Josué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Or voici les nations que l\'Éternel épargna pour mettre par elles à l\'épreuve les Israélites, tous ceux qui n\'avaient pas connu par eux-mêmes toutes les guerres de Canaan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'uniquement pour donner l\'expérience aux générations des enfants d\'Israël, leur apprendre la guerre, à ceux seulement qui jadis ne l\'avaient pas connue par eux-mêmes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'cinq princes des Philistins et tous les Cananéens et les Sidoniens et les Hévites établis au mont Liban depuis la montagne de Baal-Hermon jusque vers Hamath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Et ils servirent d\'instruments pour éprouver Israël et montrer s\'il serait docile aux commandements de l\'Éternel, prescrits à ses pères par l\'organe de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Les enfants d\'Israël demeurèrent donc au milieu des Cananéens, des Héthiens, des Amoréens, et des Perizzites et des Hévites et des Jébusites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'et ils prirent leurs filles pour femmes, et marièrent leurs filles à leurs fils, et servirent leurs dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Et les enfants d\'Israël firent ce qui déplaît à l\'Éternel, et oublièrent l\'Éternel, leur Dieu, et servirent les Baals et les Aschères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Alors la colère de l\'Éternel s\'alluma contre Israël et Il les vendit entre les mains de Cusan-Risathaïm, roi de Mésopotamie, et les enfants d\'Israël furent asservis huit ans à Cusan-Risathaïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Alors les enfants d\'Israël crièrent vers l\'Éternel, et l\'Éternel suscita aux enfants d\'Israël un libérateur qui les sauva, Othniel, fils de Kénaz, frère cadet de Caleb.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Et l\'Esprit de l\'Éternel reposa sur lui, et il jugea Israël, et il entra en campagne. Et l\'Éternel livra entre ses mains Cusan-Risathaïm, roi de Mésopotamie, et sa main l\'emporta sur Cusan-Risathaïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Ainsi, le pays eut un repos de quarante ans, et Othniel, fils de Kénaz, mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Et les enfants d\'Israël continuèrent à faire ce qui déplaît à l\'Éternel, et l\'Éternel prêta force à Eglon, roi de Moab, contre Israël, parce qu\'ils faisaient ce qui déplaît à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Et il s\'adjoignit les enfants d\'Ammon et Amalek, et il se mit en marche et défit Israël, et la Ville des Palmiers fut prise par eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Et les enfants d\'Israël furent asservis à Eglon, roi de Moab, durant dix-huit ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Alors les enfants d\'Israël crièrent vers l\'Éternel, et l\'Éternel leur suscita un libérateur, Ehud, fils de Géra, Benjaminite, homme perclus de la main droite. Alors les enfants d\'Israël envoyèrent par son entremise un présent à Eglon, roi de Moab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Et Ehud se fit un glaive à double tranchant, long d\'une coudée, et il se l\'attacha sous sa casaque sur le flanc droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Et ainsi, il porta le présent à Eglon, roi de Moab; or Eglon était un homme de très grand embonpoint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Et lorsqu\'il eut achevé l\'offrande du présent, il reconduisit les gens qui en avaient été les porteurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'mais lui-même il rebroussa aux Idoles près de Guilgal et fit faire ce message: J\'ai à te dire un mot en secret, ô Roi! Et celui-ci dit: Chut! Alors sortirent de sa présence tous ses entours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Et Ehud l\'aborda; or le roi qui était assis dans son cabinet de fraîcheur, se trouva seul. Et Ehud parla: J\'ai un message de Dieu pour toi; et il se leva de son siège.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Alors Ehud avança la main gauche, et tirant son glaive de son flanc droit il le lui plongea dans le ventre');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'tellement que la poignée aussi s\'enfonça après la lame, et que la graisse se referma sur le glaive; car il ne retira pas le glaive du ventre du roi; et il ressortit par derrière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Et Ehud sortant passa dans le péristyle et ferma après lui les portes du pavillon, et poussa les verrous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Et lorsqu\'il fut parti, les serviteurs du roi entrèrent, et remarquant que les portes du pavillon étaient fermées aux verrous, ils dirent: Sans doute il se couvre les pieds dans son cabinet de fraîcheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Et ils furent très longtemps à attendre; et voici, personne n\'ouvrait les portes du pavillon; alors ils prirent la clef et ouvrirent, et voilà que leur maître était étendu par terre mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Cependant Ehud s\'était échappé, tandis qu\'ils hésitaient; il passa les Idoles et se sauva à Séïra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Et en arrivant il sonna de la trompette sur la montagne d\'Ephraïm, et les enfants d\'Israël descendirent avec lui de la montagne, lui à leur tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Et il leur dit: Suivez-moi! car l\'Éternel a livré vos ennemis, les Moabites, entre vos mains. Et ils descendirent sous sa conduite, et ils occupèrent les gués du Jourdain vis-à-vis de Moab; et ils ne laissaient passer personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Et dans ce temps-là ils défirent, les Moabites, qui étaient environ dix mille, tous hommes robustes et guerriers dont pas un n\'échappa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'C\'est ainsi qu\'en ce temps Moab fléchit sous la main d\'Israël. Et le pays eut quatre-vingts ans de repos.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Et après lui il y eut Samgar, fils d\'Anath; il défit les Philistins, au nombre de six cents hommes, avec un aiguillon de bouvier; lui aussi fut le libérateur d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Et les enfants d\'Israël recommencèrent à faire ce qui déplaît à l\'Éternel; or Ehud était mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Alors l\'Éternel les vendit entre les mains de Jabin, roi de Canaan, qui régnait à Hatsor, et son chef d\'armée était Sisera, lequel demeurait à Haroseth-Gojim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Et les enfants d\'Israël crièrent vers l\'Éternel, car il avait neuf cents chars ferrés, et il opprima fortement les enfants d\'Israël durant vingt ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Or c\'était Debora, femme prophète, mariée à Lappidoth, qui à cette époque était juge en Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Et elle siégeait sous le Palmier de Debora entre Rama et Béthel dans la montagne d\'Ephraïm. Et les enfants d\'Israël montaient auprès d\'elle pour obtenir jugement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Alors elle envoya mander Barak, fils d\'Abinoam, de Kédès-Nephthali; et elle lui dit: Voici, l\'Éternel, Dieu d\'Israël, l\'ordonne; va occuper le mont Thabor, prenant avec toi dix mille hommes parmi les enfants de Nephthali et les enfants de Zabulon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'et j\'attirerai vers toi au torrent du Kison, Sisera, chef d\'armée de Jabin, et ses chars et sa troupe et je le livrerai entre tes mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Et Barak lui dit: Si tu marches avec moi, je marcherai; mais si tu ne marches pas avec moi, je ne marcherai pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Et elle dit: Oui, je veux marcher avec toi; seulement tu ne rencontreras pas ta gloire sur la voie que tu prends, car c\'est à la main d\'une femme que l\'Éternel livrera Sisera. Puis Debora se leva et se rendit avec Barak à Kédès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Alors Barak cita Zabulon et Nephthali à Kédès, et dix mille hommes marchèrent sous sa conduite, et Debora l\'accompagna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, '(Or Héber, le Kénite, s\'était séparé des Kénites, des fils de Hobab, beau-père de Moïse, et il dressa ses tentes jusqu\'aux chênes de Tsaannaïm, situé près de Kédès.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Et Sisera fut informé que Barak, fils d\'Abinoam, s\'était porté au mont Thabor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Alors de Haroseth-Gojim Sisera rassembla vers le torrent du Kison tous ses chars, neuf cents chars ferrés et toute la troupe qui était sous ses ordres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Alors Debora dit à Barak: Debout! car, voici la journée où l\'Éternel livre Sisera entre tes mains! L\'Éternel n\'ouvre-t-Il pas la marche devant toi? Et Barak descendit du mont Thabor suivi de dix mille hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Alors l\'Éternel mit en déroute Sisera et tous ses chars et toute son armée à la pointe de l\'épée devant Barak, et Sisera descendit de son char et s\'enfuit à pied.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Cependant Barak poursuivit les chars et l\'armée jusqu\'à Haroseth-Gojim. Et toute l\'armée de Sisera tomba sous le tranchant de l\'épée; pas un ne survécut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Quant à Sisera, il se réfugia à pied dans la tente de Jaël, femme de Héber, le Kénite. Car il y avait paix entre Jabin, roi de Hatsor, et la maison de Héber, le Kénite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Alors Jaël sortit au-devant de Sisera et lui dit: Entre, mon Seigneur, entre chez moi! sois sans crainte! Et il entra chez elle dans la tente, et elle le couvrit d\'un tapis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Et il lui dit: Donne-moi donc un peu d\'eau à boire, car j\'ai soif. Et elle ouvrit l\'outre du lait, et le fit boire et le couvrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Et il lui dit: Tiens-toi à l\'entrée de la tente, et dans le cas où un homme viendrait et te questionnerait en disant: Y a-t-il quelqu\'un ici? réponds: Personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Alors Jaël, femme de Héber, prit l\'épieu de la tente, et arma sa main du marteau et pénétra doucement vers lui et lui enfonça dans la tempe l\'épieu qui se ficha dans le sol. Or il était profondément endormi et exténué, et il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Et voici, Barak était à la poursuite de Sisera, et Jaël sortit à sa rencontre et lui dit: Viens! je vais te montrer l\'homme que tu cherches. Et il entra chez elle, et voilà que Sisera était étendu mort, l\'épieu dans la tempe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'C\'est ainsi que ce jour Dieu fit fléchir Jabin, roi de Canaan, devant les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Et la main des enfants d\'Israël s\'appesantit de plus en plus sur Jabin, roi de Canaan, jusqu\'à ce qu\'ils eussent extirpé Jabin, roi de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Et Debora avec Barak, fils d\'Abinoam, en ce jour chanta ces paroles:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'En Israël des chefs ont ouvert la campagne, et comme volontaire un peuple s\'est levé! Louez l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Rois, entendez! Princes, prêtez l\'oreille! Je veux, je veux offrir mes chants à l\'Éternel, mes accords à l\'Éternel, Dieu d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Éternel, lorsque tu sortais de Séir, que tu t\'avançais des champs de l\'Idumée, la terre s\'ébranla, et les Cieux distillèrent, et les nues distillèrent des eaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'à l\'aspect de l\'Éternel, les montagnes tremblèrent, ce Sinaï à l\'aspect de l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Aux jours de Samgar, fils d\'Anath, aux jours de Jaël, les routes restaient désertes, et ceux qui jadis suivaient les chaussées, pratiquaient les sentiers tortueux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Les princes avaient cessé, en Israël, cessé; jusqu\'à ce que je parusse, moi, Debora, que je parusse comme une mère pour Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Choisissait-il de nouveaux dieux, la guerre était aux portes: un bouclier, une lance se voyaient-ils parmi quarante mille Israélites?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Mon cœur est aux commandants d\'Israël! Volontaires sortis du peuple, louez l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Vous qui montez de blanches ânesses, qui pour siège avez des tapis, et vous qui marchez sur les chemins, joignez vos accents');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'à la voix de ceux qui partagent le butin au milieu des fontaines; là ils célèbrent les bienfaits de l\'Éternel, les bienfaits de son prince en Israël! Alors aux Portes descendit le peuple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Sus! Sus! Debora (m\'écriai-je) Sus! Sus! dis un cantique! Allons! Barak, emmène tes captifs, fils d\'Abinoam!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Réserve (dis-je alors), descends, joins les héros! Peuple de l\'Éternel, fais une descente parmi ces guerriers!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'D\'Ephraïm arrivèrent les habitants d\'Amalek; après lui Benjamin, avec sa milice; Machir envoya les commandants, et Zabulon ceux qui tiennent le bâton d\'officier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Mes princes d\'Issaschar accompagnaient Debora, et Issaschar soutint Barak, il fut détaché dans la vallée sur ses traces... Entre les cours d\'eau de Ruben il y eut grande consultation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Pourquoi rester oisif entre tes bercails, pour écouter les flûtes des pasteurs? Entre les cours d\'eau de Ruben il y eut grande délibération.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Galaad fut immobile au delà du Jourdain. Et Dan, pourquoi se tint-il sur ses navires? Asser resta au rivage des mers, et se tranquillisa dans ses baies,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Zabulon est un peuple qui méprisa sa vie pour affronter la mort, de même Nephthali dans les plaines élevées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Des rois vinrent prendre part au combat, alors combattirent les rois de Canaan à Thaanach vers les eaux de Megiddo; ils ne remportèrent pas une pièce d\'argent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Du ciel même on prit part au combat, de leurs orbites, les astres combattirent Sisera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Le torrent du Kison entraîna les cadavres, le Kison est le torrent des rencontres. Mon âme, terrasse la bravoure!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Alors les sabots des chevaux martelèrent le sol à la poursuite, à la poursuite de leurs guerriers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Maudissez Méroz, dit l\'Ange de l\'Éternel, maudissez, maudissez ceux qui l\'habitent; car ils ne vinrent pas prêter secours à l\'Éternel, prêter secours à l\'Éternel avec les braves.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Qu\'entre les femmes Jaël soit louée, l\'épouse de Héber, le Kénite; qu\'elle soit louée entre les femmes qui habitent sous la tente!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Il demandait de l\'eau; elle donna du lait, dans la coupe d\'apparat elle servit du caillé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'D\'une main elle saisit l\'épieu, et de sa droite le marteau des gens de peine, et elle frappe Sisera, lui brise la tête, lui fracasse et lui perce les tempes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'A ses pieds il s\'affaisse, tombe, est étendu; à ses pieds il s\'affaisse et tombe; où il s\'affaisse, c\'est là qu\'il tombe sans vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Par la fenêtre, à travers le treillis la mère de Sisera, penchée, regarde et s\'écrie: « Pourquoi son char tarde-t-il à venir? pourquoi les pas de son attelage sont-ils si lents? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Ses princesses avisées lui font une réponse; et elle-même retire ses discours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, '« N\'auront-ils pas trouvé du butin? ils le partagent; une, deux captives par tête, une dépouille d\'étoffes teintes pour Sisera; une dépouille d\'étoffes teintes, brodées, une housse teinte, deux tissus de brocart pour le col de ses montures capturées. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Ainsi périssent tous tes ennemis, Éternel! mais que ceux qui t\'aiment soient comme le soleil quand il paraît avec sa puissance! Et le pays fut en paix durant quarante ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Et les enfants d\'Israël firent ce qui déplaît à l\'Éternel; c\'est pourquoi l\'Éternel les livra aux mains des Madianites pendant sept ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Et la main de Madian pesa fortement sur Israël. Pour leur sûreté contre Madian, les enfants d\'Israël disposèrent pour eux les ravins des montagnes, les cavernes et les hauteurs fortes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Or il arrivait que quand les Israélites avaient fait les semailles, les Madianites, les Amalécites et les enfants de l\'Orient s\'avançaient et marchaient contre eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Et ils dressaient leur camp en face d\'eux, et détruisaient tous les produits du sol jusque vers Gaza, et ne laissaient en Israël ni subsistances, ni brebis, ni bœufs, ni ânes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Car eux-mêmes ils venaient avec leurs troupeaux et leurs tentes, arrivant en masse comme des sauterelles innombrables, aussi bien que leurs chameaux, ils envahissaient le pays pour le saccager.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Et Israël fut extrêmement affaibli par Madian, alors les enfants d\'Israël crièrent vers l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Et lorsque les enfants d\'Israël crièrent vers l\'Éternel, au sujet de Madian,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'l\'Éternel envoya un prophète aux enfants d\'Israël, et il leur dit: Ainsi parle l\'Éternel, Dieu d\'Israël: Je vous ai amenés de l\'Egypte et retirés de la maison de servitude,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'et je vous ai arrachés des mains des Égyptiens et des mains de tous vos oppresseurs, que j\'ai chassés devant vous, et je vous ai donné leur pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Et je vous ai dit: Moi, l\'Éternel, je suis votre Dieu; ne craignez pas les dieux des Amoréens dans le pays desquels vous vous établissez. Mais vous n\'avez pas écouté ma voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Ensuite vint un Ange de l\'Éternel qui s\'assit sous le térébinthe d\'Ophra appartenant à Joas de la maison de Abi-Ezer. Et Gédéon, son fils, battait du froment au pressoir pour le mettre à l\'abri des Madianites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Et l\'Ange de l\'Éternel lui apparut et lui dit: L\'Éternel est avec toi, héros guerrier!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Et Gédéon lui dit: Pardonne! mon Seigneur. Si l\'Éternel est avec nous, pourquoi toutes ces choses nous sont-elles advenues? Et où sont tous Ses miracles que nous ont racontés nos pères en disant: L\'Éternel ne nous a-t-Il pas retirés de l\'Egypte? Eh bien! l\'Éternel nous a abandonnés et nous a livrés aux mains des Madianites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Et l\'Éternel s\'adressa à lui et lui dit: Va avec cette force que tu as, et délivre Israël de la main de Madian. Voici, je te donne mission.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Et il Lui dit: Pardonne, mon Seigneur! Avec quoi délivrerais-je Israël? Voici, ma famille est la plus faible de Manassé, et je suis le plus petit de la maison de mon père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Et l\'Éternel lui dit: Oui, je serai avec toi et tu déferas les Madianites comme un seul homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Et il Lui dit: Si je puis avoir trouvé grâce à tes yeux, opère un signe qui me prouve que c\'est Toi qui me parles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Consens à ne pas quitter ce lieu jusqu\'à que je te rejoigne et que j\'apporte mon offrande et la dépose devant Toi. Et Il lui dit: Je resterai jusqu\'à ton retour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Et Gédéon entra et apprêta un chevreau et un épha de farine sans levain; il mit la chair dans la corbeille et le jus dans le vase à cuire; puis il l\'apporta vers Lui sous le térébinthe, et le Lui offrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Et l\'Ange de Dieu lui dit: Prends la chair et les azymes et pose-les sur ce rocher-ci, et verse le jus. Et il fit ainsi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Et l\'Ange de l\'Éternel présentant le bout du bâton qu\'il avait à la main, toucha la chair et les azymes, et le feu jaillit du rocher, et consuma la chair et les azymes, et l\'Ange de l\'Éternel disparut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Alors Gédéon vit que c\'était un ange de l\'Éternel, et Gédéon dit: Ah! Seigneur, Éternel... car puisque j\'ai vu un ange de l\'Éternel face à face...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Et l\'Éternel lui dit: Salut pour toi! n\'aie pas peur! tu ne mourras pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Alors Gédéon éleva là un autel à l\'Éternel, et il l\'appela Jehova-Schalom (Éternel Salut). Il subsiste encore aujourd\'hui à Ophra des Abi-Ezrites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Et pendant la nuit même l\'Éternel lui dit: Prends le jeune taureau de ton père, et un second taureau de sept ans, et démolis l\'autel de Baal, qui est à ton père et coupe l\'Aschère qui est auprès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Puis élève un autel à l\'Éternel, ton Dieu, sur le sommet de ce rocher avec la pile du bûcher, et prends le second taureau, et offre un holocauste avec le bois de l\'Aschère que tu auras coupée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Alors Gédéon prit dix hommes parmi ses serviteurs et exécuta ce que l\'Éternel lui avait dit. Et comme il craignait de le faire de jour à la vue de la maison de son père et des gens de la ville, il le fit de nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Et lorsque les gens de la ville se levèrent le matin, voilà que l\'autel de Baal était en ruine, et l\'Aschère qui l\'avoisinait, coupée, et le second taureau placé comme holocauste sur l\'autel construit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Et ils se dirent l\'un à l\'autre: Qui a fait cela? Et ils firent des recherches et des perquisitions et dirent: C\'est Gédéon, fils de Joas, qui l\'a fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Alors les gens de la ville dirent à Joas: Livre ton fils et qu\'il meure! car il a détruit l\'autel de Baal et coupé l\'Aschère avoisinante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Et Joas dit à tous ceux qui l\'entouraient: Voulez-vous prendre parti pour Baal ou voulez-vous le sauver? Celui qui prendra parti pour Baal sera mis à mort d\'ici à demain. S\'il est dieu, il peut se venger lui-même de la destruction de son autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Et ce jour-là on l\'appela Jérubbaal, en disant: Que Baal le prenne à partie pour avoir démoli son autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Cependant Madian entier, et Amalek, et les enfants de l\'Orient, se réunirent tous et passèrent [le Jourdain] et campèrent dans la vallée de Jizréel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Et l\'Esprit de l\'Éternel revêtit Gédéon, et il sonna de la trompette et les Abi-Ezrites vinrent se mettre sous sa conduite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Et il dépêcha des messagers dans tout Manassé, et Manassé aussi vint se mettre sous sa conduite; et il dépêcha des messagers dans Asser, dans Zabulon et dans Nephthali, et ils se mirent en marche à sa rencontre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Alors Gédéon dit à Dieu: Si tu veux délivrer Israël par mon bras, ainsi que tu l\'as dit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'voici j\'étendrai la toison de laine sur l\'aire; si la toison seule reçoit la rosée, et que tout le sol d\'alentour reste sec, alors je comprendrai que tu veux délivrer Israël par mon bras, ainsi que tu l\'as dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Et ainsi arriva. Et le lendemain à son lever il pressa la toison et il en exprima toute une jatte d\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Et Gédéon dit à Dieu: Que ta colère ne s\'allume pas contre moi, de ce que je vais parler cette fois seulement: je voudrais encore une seule fois faire l\'épreuve avec la toison. Que la toison seule donc reste sèche et que la rosée couvre tout le sol.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Et la nuit même Dieu opéra la chose, et la toison seule resta sèche, tandis que la rosée couvrit tout le sol.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Alors Jérubbaal (c\'est-à-dire, Gédéon) se leva dès le matin, ainsi que toute la troupe qu\'il avait avec lui, et ils campèrent à la source de Harod. Or les Madianites avaient leur camp au nord près du monticule de More dans la vallée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Et l\'Éternel dit à Gédéon: Il y a trop de gens avec toi, pour que je livre Madian entre leurs mains, car il ne faut pas qu\'Israël se glorifie à ma face et dise: C\'est mon bras qui m\'a sauvé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Fais donc proclamer aux oreilles de l\'armée cet avis: Que tous ceux qui sont timides et craintifs s\'en retournent, et de la montagne se retirent à Galaad. Alors vingt-deux mille s\'en allèrent de l\'armée, et il en resta dix mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Et l\'Éternel dit à Gédéon: Il y en a encore trop. Fais-les descendre à l\'eau, et là je t\'en ferai l\'épuration; et celui-là marchera avec toi, duquel je te dirai: il marchera avec toi; et aucun de ceux desquels je te dirai: il ne marchera pas avec toi, ne devra marcher avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Et il fit descendre la troupe à l\'eau, et l\'Éternel dit à Gédéon: Mets à part tous ceux qui tireront l\'eau avec la langue en lapant comme lape le chien, et de même tous ceux qui s\'agenouilleront pour boire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Et le nombre de ceux qui lapèrent en portant avec la main l\'eau à la bouche fut de trois cents hommes, et tout le reste de la troupe s\'était agenouillé pour humer l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Et l\'Éternel dit à Gédéon: C\'est par ces trois cents hommes qui ont lapé, que je vous sauverai et livrerai Madian entre tes mains; d\'ailleurs que tout le reste de la troupe regagne le logis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Et ils prirent avec eux des vivres et leurs trompettes, et Gédéon renvoya les autres Israélites chacun dans leurs tentes, et il retint les trois cents hommes. Or le camp de Madian était en bas dans la vallée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Et pendant la nuit même l\'Éternel lui dit: Debout! descends sur le camp, car je l\'ai livré entre tes mains,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'et si tu redoutes cette descente, descends au camp avec Pura, ton valet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'Et tu écouteras ce qu\'on y dit; en suite de quoi tu prendras courage pour descendre sur le camp. Alors il descendit avec Pura, son valet, jusqu\'à l\'extrémité des avant-postes du camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Or les Madianites et les Amalécites et tous les enfants de l\'Orient s\'étendaient dans la vallée aussi nombreux que des sauterelles, et leurs chameaux étaient innombrables, pareils en quantité aux grains de sable des bords de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Et Gédéon vint, et voici, l\'un d\'eux racontait à l\'autre un songe en ces termes: Voici, j\'ai eu un songe: et voilà qu\'une galette de pain d\'orge roulait dans le camp de Madian, et elle arriva jusqu\'aux tentes et elle les heurta, et elles tombèrent, et elle les mit sens dessus dessous, et les tentes étaient renversées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Et l\'autre répondait et disait: Ce n\'est pas autre chose que l\'épée de Gédéon, fils de Joas, l\'homme d\'Israël: Dieu livre entre ses mains Madian et toute l\'armée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Et Gédéon, à l\'ouïe du récit du songe et de son explication, se prosterna. Puis étant rentré au camp d\'Israël il dit: Debout! car l\'Éternel livre entre vos mains le camp de Madian.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Et il divisa les trois cents hommes en trois sections. Et il leur mit à tous des trompettes à la main et des cruches vides, et des torches dans les cruches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Et il leur dit: Regardez à moi, et imitez! Voici, je vais me porter au bout du camp, et ce que je ferai, faites-le de même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Et quand moi et tous mes compagnons, nous sonnerons de la trompette, vous aussi, sonnez de la trompette tout autour du camp et criez: Pour l\'Éternel et Gédéon!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Ainsi Gédéon accompagné de ses cent hommes se porta à un bout du camp à l\'entrée de la veille médiale: on venait à peine de placer les sentinelles. Alors ils sonnèrent des trompettes et cassèrent les cruches qu\'ils portaient à la main,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'et les trois sections sonnèrent des trompettes, et cassèrent les cruches, et prenant de la main gauche les torches et de la droite les trompettes pour en sonner, ils crièrent: Épée de l\'Éternel et de Gédéon!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Et ils restèrent chacun en place tout autour du camp. Alors dans tout le camp, de courir, de pousser des cris, et de fuir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Et ils sonnèrent des trois cents trompettes, et l\'Éternel leur fit dans toute l\'enceinte du camp tourner leurs épées les uns contre les autres. Et l\'armée s\'enfuit jusqu\'à Beth-Sitta vers Tsejera, à la lisière d\'Abel-Mehola près de Thabbath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Alors se rassemblèrent les Israélites de Nephthali et d\'Asser et de tout Manassé, et ils se mirent à la poursuite de Madian.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Et Gédéon dépêcha des messagers dans toute la montagne d\'Ephraïm pour dire: Descendez à la rencontre des Madianites, et coupez-leur l\'eau jusqu\'à Beth-Bara et au Jourdain. Alors tous les hommes d\'Ephraïm se rassemblèrent, et ils leur coupèrent l\'eau jusqu\'à Beth-Bara et au Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Et ils firent prisonniers deux princes de Madian, Oreb et Zeeb, et ils égorgèrent Oreb sur le rocher d\'Oreb et Zeeb près du Pressoir de Zeeb; et ils poursuivirent les Madianites, et ils apportèrent à Gédéon depuis l\'autre côté du Jourdain les têtes d\'Oreb et de Zeeb.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Et les hommes d\'Ephraïm lui dirent: Qu\'est-ce de ta part que cette manière d\'agir envers nous, de ne pas nous appeler lorsque tu marchais à l\'attaque de Madian? Et ils le prirent à partie avec véhémence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Et il leur dit: Qu\'ai-je fait d\'égal à vos exploits? le grappillage d\'Ephraïm n\'est-il pas préférable à la vendange d\'Abiézer?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'C\'est entre vos mains que Dieu a livré les princes Madianites Oreb et Zeeb. Qu\'ai-je pu faire aussi bien que vous? Alors l\'animosité qu\'ils avaient contre lui, s\'apaisa, comme il parlait ainsi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Et Gédéon, arrivé sur le Jourdain, le passa avec les trois cents hommes qui l\'accompagnaient fatigués et poursuivant toujours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Alors il dit aux gens de Succoth: Donnez donc des galettes de pain à la troupe qui me suit, car elle est rendue, et je suis à la poursuite de Zébah et Tsalmunna, rois de Madian.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Et les chefs de Succoth lui dirent: Tiens-tu déjà captifs Zébah et Tsalmunna pour que nous donnions du pain à ton escorte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Et Gédéon dit: Eh bien! si l\'Éternel met Zébah et Tsalmunna en mon pouvoir, je triturerai votre chair avec des ronces de la steppe et des chardons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Et de là il monta à Pnuel, et il y tint le même langage, et les gens de Pnuel lui firent la même réponse que les gens de Succoth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Et il dit aussi aux gens de Pnuel: Si je reviens sain et sauf, je raserai cette tour-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Or Zébah et Tsalmunna étaient à Carcor avec leur armée d\'environ quinze mille hommes, total de ce qui était resté de toute l\'armée des enfants de l\'Orient: cent vingt mille hommes tirant l\'épée avaient péri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Et Gédéon s\'avança du côté de ceux qui logent dans des tentes, à l\'orient de Noba et de Jogbeha et dressa son camp, tandis que [l\'autre] camp était en sécurité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Et Zébah et Tsalmunna prirent la fuite, et il les poursuivit, et fit prisonniers les deux rois de Madian, Zébah et Tsalmunna: il avait jeté l\'épouvante dans tout le camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Alors Gédéon, fils de Joas, revint de la guerre et partit de la hauteur qui domine Hérès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Et il arrêta un jeune homme d\'entre les gens de Succoth, qu\'il interrogea, et qui lui désigna par écrit les chefs de Succoth et les Anciens, soixante-dix-sept hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Puis il se présenta aux gens de Succoth et dit: Voici Zébah et Tsalmunna desquels vous me disiez ironiquement: Tiens-tu déjà Zébah et Tsalmunna captifs, pour que nous donnions du pain à tes gens épuisés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Et il saisit les Anciens de la ville et prit des ronces de la steppe et des chardons, et les fit servir au supplice des hommes de Succoth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Et il rasa la tour de Pnuel, et massacra les gens de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Et il dit à Zébah et Tsalmunna: Comment étaient les hommes que vous avez égorgés au Thabor? Et ils dirent: Tel tu es, tels ils étaient: ils avaient chacun la prestance de fils de rois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Et il dit: C\'étaient mes frères, fils de ma mère. Par la vie de l\'Éternel, si vous leur eussiez laissé la vie, je ne vous égorgerais pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Et il dit à Jéther, son premier-né: Va, égorge-les! Mais l\'enfant ne tirait pas l\'épée, parce qu\'il avait peur, car c\'était encore un enfant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Alors Zébah et Tsalmunna dirent: Allons, toi-même, jette-toi sur nous! car tel est l\'homme, telle est sa force. Alors Gédéon se leva et égorgea Zébah et Tsalmunna. Et il prit les lunules qui étaient au cou de leurs chameaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Et les hommes d\'Israël dirent à Gédéon: Domine sur nous, et toi et ton fils et le fils de ton fils, parce que tu nous as sauvés des mains des Madianites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Et Gédéon leur dit: Je ne dominerai point sur vous, et mon fils ne dominera point sur vous; c\'est l\'Éternel qui doit dominer sur vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Et Gédéon leur dit: J\'ai une demande à vous faire: donnez-moi chacun une boucle de narine de votre butin! (Car ils portaient à la narine des boucles d\'or, étant Ismaélites.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Et ils dirent: Nous te les donnerons. Et ils étendirent un manteau et chacun y jeta une boucle de narine de son butin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Et le poids des boucles de narine d\'or qu\'il demanda, fut de mille sept cents sicles d\'or, non compris les lunules et les pendants d\'oreille et les vêtements de pourpre que portaient les rois de Madian, et les colliers qui étaient au cou de leurs chameaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Et Gédéon en fit un Ephod, et il le plaça dans sa ville, à Ophra; et tout Israël alla s\'y prostituer, et ce fut un piège pour Gédéon et pour sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'C\'est ainsi que les Madianites plièrent devant les enfants d\'Israël, et ils ne relevèrent plus la tête. Et le pays eut un repos de quarante ans à l\'époque de Gédéon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Et Jérubbaal, fils de Joas, s\'en alla habiter dans sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Or Gédéon eut soixante-dix fils, issus de son sang, car il avait beaucoup de femmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Et sa concubine, qui était à Sichem, lui enfanta un fils, et il lui donna le nom d\'Abimélech.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Et Gédéon, fils de Joas, mourut dans une belle vieillesse, et reçut la sépulture dans le tombeau de Joas, son père, à Ophra des Abi-Ezrites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Et lorsque Gédéon fut mort, de nouveau les enfants d\'Israël se prostituèrent aux Baals, et ils firent leur dieu de Baal-Berith.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Et les enfants d\'Israël ne se souvinrent pas de l\'Éternel, leur Dieu, qui les avait sauvés des mains de tous leurs ennemis d\'alentour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Et ils ne montrèrent pas à la maison de Jérubbaal, de Gédéon, une affection proportionnée à tout le bien qu\'il avait fait à Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Et Abimélech, fils de Jérubbaal, se rendit à Sichem auprès des frères de sa mère; et il leur parla ainsi qu\'à toute la race de la maison du père de sa mère, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Portez donc ces paroles aux oreilles de tous les citoyens de Sichem: Lequel vaut le mieux pour vous ou que soixante-dix hommes, tous fils de Jérubbaal, vous gouvernent, ou bien qu\'un seul homme vous gouverne? rappelez-vous que je suis votre sang, votre chair même!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Et les frères de sa mère portèrent pour lui toutes ces paroles aux oreilles de tous les citoyens de Sichem, et leur cœur inclina du côté d\'Abimélech; car, disaient-ils, il est notre frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Et ils tirèrent du temple de Baal-Berith soixante-dix sicles d\'argent pour les lui donner; et avec cela Abimélech soudoya des vauriens et des hommes audacieux qui s\'attachèrent à lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Et il vint dans la maison de son père à Ophra, et il égorgea ses frères, fils de Jérubbaal, soixante-dix hommes, sur une même pierre; cependant Jotham, fils cadet de Jérubbaal, survécut, parce qu\'il s\'était caché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Et tous les citoyens de Sichem et tous les habitants de la citadelle s\'étant assemblés, vinrent et établirent Abimélech roi près du chêne du corps-de-garde vers Sichem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Et Jotham en ayant été informé alla se placer au haut du mont Garizim, et élevant la voix il les harangua et leur dit: « Ecoutez-moi, citoyens de Sichem, afin que Dieu vous écoute!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Les arbres se réunirent pour oindre un roi qui régnât sur eux. Et ils dirent à l\'olivier: Règne sur nous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Et l\'olivier leur dit: Renoncerais-je à mon huile qui m\'attire l\'estime des dieux et des hommes, pour aller me balancer au-dessus des arbres?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Alors les arbres dirent au figuier: Eh bien! toi, règne sur nous! Et le figuier leur dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Renoncerais-je à ma douceur et à mon fruit exquis pour aller me balancer au-dessus des arbres?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Alors les arbres dirent à la vigne: Eh bien! toi, règne sur nous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Et la vigne leur dit: Renoncerais-je à ma liqueur qui réjouit les dieux et les hommes, pour aller me balancer au-dessus des arbres?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Alors tous les arbres dirent au buisson d\'épines: Eh bien! toi, règne sur nous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Et le buisson d\'épines dit aux arbres: Si en vérité vous voulez m\'oindre pour m\'établir roi sur vous, venez et abritez-vous sous mon ombrage; sinon du buisson d\'épines sortira un feu qui dévorera les cèdres du Liban.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Ainsi donc, si c\'est avec fidélité et droiture que vous avez agi en faisant Abimélech roi, et si vous vous êtes bien conduits envers Jérubbaal et sa maison, et si vous l\'avez traité en raison de ce qu\'il a fait pour vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'des combats que mon père a livrés pour vous, des dangers auxquels il a exposé sa vie pour vous, afin de vous sauver des mains des Madianites...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, '(mais aujourd\'hui vous vous êtes levés contre la maison de mon père, et vous avez égorgé ses fils, soixante-dix hommes sur une pierre; et vous avez établi Abimélech, fils de sa servante, roi des citoyens de Sichem, parce qu\'il est votre frère),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'si c\'est avec sincérité et droiture qu\'en ce jour vous en avez agi avec Jérubbaal et sa maison, alors soyez satisfaits d\'Abimélech, et que lui aussi soit satisfait de vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'sinon, un feu sortira d\'Abimélech et dévorera les citoyens de Sichem et les habitants de la citadelle, et un feu sortira des citoyens de Sichem et des habitants de la citadelle, et dévorera Abimélech. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Et Jotham se retira et s\'enfuit, et gagna Béer où il vécut à distance d\'Abimélech, son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Et Abimélech fut pendant trois ans le prince d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Alors Dieu envoya un mauvais esprit entre Abimélech et les citoyens de Sichem; et les citoyens de Sichem se révoltèrent contre Abimélech,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'afin que l\'atrocité commise sur les soixante-dix fils de Jérubbaal retombât et que leur sang rejaillît sur Abimélech, leur frère, qui était leur meurtrier, et sur les citoyens de Sichem, qui lui avaient prêté main-forte pour égorger ses frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Et les citoyens de Sichem apostèrent contre lui des gens en embuscade sur les sommets des montagnes; et ils pillaient tous ceux qui passaient près d\'eux sur la route. Et l\'avis en fut donné à Abimélech.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Alors arriva Gaal, fils de Ebed, avec ses frères; et ils entrèrent dans Sichem; et les citoyens de Sichem eurent confiance en lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Et ils firent une excursion dans la campagne et vendangèrent leurs vignes, et pressurèrent, et firent une fête, et entrèrent dans le temple de leur dieu, et mangèrent et burent et maudirent Abimélech.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Et Gaal, fils de Ebed, disait: Qui est Abimélech et qu\'est Sichem pour que nous lui soyons asservis? N\'est-il pas fils de Jérubbaal, et Zebul n\'est-il pas son lieutenant? Soumettez-vous aux hommes de Hamor, père de Sichem; mais pourquoi lui serions-nous soumis, nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Oh! si l\'on me donnait la conduite de ce peuple! je mettrais de côté Abimélech! Et il disait à Abimélech: Renforce ton armée et parais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Et Zebul, commandant de la ville, eut avis des propos de Gaal, fils de Ebed; et sa colère s\'alluma,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'et il dépêcha secrètement des messagers à Abimélech pour lui dire: Voici, Gaal, fils de Ebed, et ses frères sont entrés dans Sichem, et voilà qu\'ils soulèvent la ville contre toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Pars donc pendant la nuit avec les troupes que tu as avec toi, et viens te mettre en embuscade dans les champs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Et le lendemain au lever du soleil, lève-toi le matin et fais irruption contre la ville; et voici, lui et les gens qui sont avec lui, feront une sortie contre toi: alors agis contre lui d\'après les occurences.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Là-dessus Abimélech se mit en marche de nuit avec toutes les troupes qu\'il avait, et il vint se placer en embuscade près de Sichem, en quatre, divisions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Et Gaal, fils de Ebed, sortit et se posta à l\'entrée de la porte de la ville. Alors Abimélech et les troupes qu\'il avait avec lui quittèrent l\'embuscade.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Et à la vue des troupes Gaal dit à Zebul: Voilà des troupes qui descendent des sommets des montagnes. Et Zebul lui dit: Tu prends l\'ombre des montagnes pour des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Et Gaal reprit la parole et dit: Voilà des troupes qui descendent de la sommité du pays, et une division arrive du chemin du chêne des augures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Et Zebul lui dit: Eh bien! où est cette bouche de laquelle sortaient tes propos: Qui est Abimélech pour que nous lui soyons asservis? N\'est-ce pas là la troupe que tu méprisais? Allons! en avant! mesure-toi avec lui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Alors Gaal s\'avança à la tête des citoyens de Sichem et livra bataille à Abimélech.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Et Abimélech le poursuivit, et il prit la fuite devant lui, et jusqu\'à l\'entrée de la porte il y eut beaucoup de monde tué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Et Abimélech resta à Aruma, et Zebul chassa Gaal et ses frères, qui ainsi cessèrent de demeurer dans Sichem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Et le lendemain le peuple parut dans la campagne et Abimélech en fut informé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Alors il prit sa troupe et la partagea en trois corps, et se mit en embuscade dans les champs. Il observa, et dès que le peuple sortit de la ville, il l\'attaqua et le défit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Et Abimélech et les corps qui étaient avec lui se précipitèrent et vinrent prendre position à l\'entrée de la porte de la ville, et deux corps se jetèrent sur tous ceux qui étaient dans les champs, et les battirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Et Abimélech donna l\'assaut à la ville toute la journée, et il la prit et massacra le peuple qui s\'y trouvait, et il rasa la ville et y sema du sel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'A l\'ouïe de ces choses, les habitants de la Tour de Sichem gagnèrent le donjon du temple du dieu Berith.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Et on rapporta à Abimélech que tous les habitants de la Tour de Sichem étaient réunis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Alors Abimélech gravit la montagne du Tsalmon avec toute la troupe qu\'il avait avec lui; et Abimélech prit une hache dans sa main, et coupa une branche d\'arbre, et l\'enleva et la mit sur son épaule, et il dit à la troupe qui l\'accompagnait: Ce que vous m\'avez vu faire, hâtez-vous de le faire comme moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Alors tous les hommes de la troupe coupèrent aussi chacun sa branche, et suivirent Abimélech et posèrent [les branches] sur le donjon, et ils incendièrent le donjon avec ceux qui y étaient. Et tous les habitants de la Tour de Sichem moururent aussi, au nombre de mille, hommes et femmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Et Abimélech marcha contre Thébets, et il bloqua Thébets et la prit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Or il y avait au milieu de la ville une tour forte où tous se réfugièrent, hommes et femmes et tous les citoyens de la ville; ils s\'y enfermèrent et montèrent sur le toit de la tour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Et Abimélech arriva à cette tour et il l\'attaqua et s\'approcha jusqu\'à la porte de la tour, pour la brûler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Alors une femme lança un fragment de meule sur la tête d\'Abimélech et lui brisa le crâne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Aussitôt il appela son valet qui portait ses armes et lui dit: Tire ton épée et tue-moi, afin qu\'on ne dise pas de moi: Une femme l\'a tué. Et son valet le transperça et il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Et quand les hommes d\'Israël virent Abimélech mort, ils rentrèrent chacun chez soi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Ainsi tout le mal qu\'Abimélech avait fait à son père, en égorgeant ses soixante-dix frères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'et tout le mal qu\'avaient fait les gens de Sichem, Dieu le fit retomber sur leur tête; et ainsi s\'accomplit sur eux la malédiction de Jotham, fils de Jérubbaal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Et après Abimélech s\'éleva, pour délivrer Israël, Thola, fils de Puali, fils de Dodo, homme d\'Issaschar, lequel habitait Samir dans la montagne d\'Ephraïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Et il jugea Israël pendant vingt-trois ans, puis il mourut et reçut la sépulture à Samir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Et après lui s\'éleva Jaïr de Galaad, qui jugea Israël pendant vingt-deux ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Et il avait trente fils qui montaient trente ânes poulains, et ils possédaient trente villes, qu\'on appelle encore aujourd\'hui Bourgs de Jaïr, et elles sont dans le pays de Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Et Jaïr étant mort reçut la sépulture à Kamon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Et les enfants d\'Israël continuèrent à faire ce qui déplaît à l\'Éternel et ils servirent les Baals et les Astartés et les dieux de Syrie et les dieux de Sidon et les dieux de Moab et les dieux des Ammonites et les dieux des Philistins, et abandonnèrent l\'Éternel et son service.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Et la colère de l\'Éternel s\'alluma contre les Israélites et Il les vendit entre les mains des Philistins et les mains des Ammonites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Et ils tourmentèrent et écrasèrent les enfants d\'Israël cette année-là, et pendant dix-huit ans tous les enfants d\'Israël habitant au delà du Jourdain dans le pays des Amoréens en Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Et les Ammonites passèrent le Jourdain pour attaquer aussi Juda et Benjamin et la maison d\'Ephraïm. Et Israël fut serré de très près.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Alors les enfants d\'Israël crièrent vers l\'Éternel, disant: Nous avons péché contre toi, en abandonnant notre Dieu et en servant les Baals.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Et l\'Éternel dit aux enfants d\'Israël: Ne vous avais-je pas délivrés des Égyptiens et des Amoréens, des Ammonites et des Philistins,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'et, lorsque les Sidoniens, Amalek et Maon, vous opprimèrent, et que vous avez crié vers moi, ne vous ai-je pas sauvés de leurs mains?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Mais vous, vous m\'avez abandonné et vous avez servi d\'autres dieux. C\'est pourquoi je ne continuerai pas de vous délivrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Allez et adressez vos cris aux dieux dont vous avez fait choix! qu\'ils vous délivrent au moment de votre détresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Et les enfants d\'Israël dirent à l\'Éternel: Nous avons péché: traite-nous comme il te semblera bon; seulement, oh! sauve-nous aujourd\'hui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Et ils firent disparaître du milieu d\'eux les dieux de l\'étranger et ils servirent l\'Éternel. Alors Son âme ne put être indifférente aux tribulations d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Et les Ammonites se rassemblèrent et campèrent en Galaad, et les enfants d\'Israël se réunirent et campèrent à Mitspa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Alors le peuple, les princes de Galaad se dirent l\'un à l\'autre: Quel est l\'homme qui commencera l\'attaque des Ammonites? il deviendra le chef de tous les habitants de Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Et Jephthé de Galaad était un brave guerrier; or il était fils d\'une courtisane, et Galaad avait engendré Jephthé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Et lorsque l\'épouse de Galaad lui eut donné des fils et que les fils de l\'épouse furent adultes, ils avaient chassé Jephthé en lui disant: Tu ne peux être héritier dans la maison de notre père, car tu es le fils d\'une autre femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Alors Jephthé s\'était enfui loin de ses frères et s\'était établi dans la contrée de Tob. Et des aventuriers affluèrent vers Jephthé, et ils allèrent en course avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Et quelque temps après survint la guerre des Ammonites contre Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Et comme les Ammonites en étaient venus aux hostilités avec Israël, les Anciens de Galaad partirent pour aller chercher Jephthé au pays de Tob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Et ils dirent à Jephthé: Viens et sois notre général pour nous mener au combat contre les Ammonites. Et Jephthé dit aux Anciens de Galaad:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'N\'est-ce pas vous qui m\'avez haï et chassé de la maison de mon père? Et pourquoi venez-vous à moi maintenant que vous êtes dans l\'embarras?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Et les Anciens de Galaad dirent à Jephthé: C\'est à cause de cela que nous revenons maintenant à toi: viens donc avec nous combattre les Ammonites, et sois notre chef à nous tous les habitants de Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Et Jephthé dit aux Anciens de Galaad: Si vous me ramenez pour combattre les Ammonites, et que l\'Éternel me rende maître d\'eux, moi je veux rester votre chef.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Et les Anciens de Galaad dirent à Jephthé: Que l\'Éternel entende ce qui se traite entre nous! Oui, nous ferons ce que tu viens de dire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Alors Jephthé partit avec les Anciens de Galaad, et le peuple le préposa sur lui-même comme chef et général. Et Jephthé prononça toutes ces paroles en la présence de l\'Éternel à Mitspa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Alors Jephthé dépêcha des messagers au Roi des Ammonites pour lui dire: Qu\'avons-nous à démêler ensemble, que tu marches contre moi pour faire la guerre à mon pays?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Et le roi des Ammonites dit aux messagers de Jephthé: C\'est qu\'Israël s\'est emparé de mon pays, lors de sa sortie de l\'Egypte, depuis l\'Arnon au Jabbok et au Jourdain. Et maintenant restitue-le à l\'amiable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Alors Jephthé dépêcha de nouveau des messagers au roi des Ammonites');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'pour lui dire: Ainsi parle Jephthé: Israël ne s\'est emparé ni du pays de Moab, ni du pays des Ammonites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Car après sa sortie de l\'Egypte, Israël parcourut le désert jusqu\'à la Mer aux algues, et il atteignit Cadès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Alors Israël envoya des messagers au roi d\'Edom pour lui dire: Daigne m\'accorder le passage par ton territoire! Mais le roi d\'Edom ne consentit pas. Et ils députèrent aussi auprès du roi de Moab, et celui-ci ne voulut pas. Israël resta donc à Cadès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Et il parcourut le désert, et tourna le pays d\'Edom et le pays de Moab, et ils arrivèrent à l\'orient du pays de Moab et ils campèrent au delà de l\'Arnon, sans entrer sur le territoire de Moab; car l\'Arnon forme la frontière de Moab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Alors Israël envoya des messagers à Sihon, roi des Amoréens, roi de Hesbon, et Israël lui disait: Daigne m\'accorder le passage à travers ton pays jusqu\'au lieu où je vais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Mais Sihon ne se crut pas assez sûr des Israélites pour les laisser passer sur son territoire, et Sihon rassembla tout son peuple et campa à Jahtsa et fit la guerre à Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Et l\'Éternel, Dieu d\'Israël, livra Sihon et tout son peuple aux mains des Israélites qui les battirent. Et Israël conquit tout le pays des Amoréens établis dans cette contrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Et ils conquirent tout le territoire des Amoréens de l\'Arnon au Jabbok et du désert au Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Ainsi l\'Éternel, Dieu d\'Israël, a expulsé les Amoréens devant son peuple d\'Israël! et toi, tu voudrais t\'emparer de leur pays!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'N\'as-tu pas la propriété de ce dont Camos, ton dieu, t\'a mis en possession? De même nous avons la propriété de tout ce dont l\'Éternel, notre Dieu, nous a mis en possession.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Et puis, es-tu mieux placé que Balak, fils de Tsippor, roi de Moab? A-t-il cherché querelle aux Israélites ou leur a-t-il fait la guerre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Pendant les trois cents ans du séjour des Israélites dans Hesbon et ses annexes, dans Aroër et ses annexes et toutes les villes sises sur les bords de l\'Arnon, pourquoi ne les avez-vous pas revendiquées à cette époque-là?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Moi, je n\'ai pas failli à ton égard, et toi, tu en agis mal avec moi, en me faisant la guerre. Que l\'Éternel, qui est Juge, prononce donc aujourd\'hui entre les enfants d\'Israël et les enfants d\'Ammon!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Mais le roi des Ammonites n\'écouta point les raisons que Jephthé lui avait fait alléguer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Alors l\'esprit de l\'Éternel descendit sur Jephthé, qui, traversant Galaad et Manassé, passa à Mitspa en Galaad et de Mitspa en Galaad marcha contre les Ammonites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Et Jephthé fit un vœu à l\'Éternel en ces termes: Si tu livres les Ammonites entre mes mains,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'la personne qui de la porte de ma maison sortira à ma rencontre, moi revenant sain et sauf de la guerre des Ammonites, appartiendra à l\'Éternel et je la Lui offrirai en holocauste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Puis Jephthé marcha contre les Ammonites pour engager le combat avec eux. Et l\'Éternel les livra entre ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Et il les battit depuis Aroër jusque vers Minnith, dans vingt villes, et jusqu\'à Abel-Keramim; ce fut une grande défaite et les Ammonites furent abaissés devant les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Et comme Jephthé revenait dans sa maison à Mitspa, voilà que sa fille sortit à sa rencontre avec des tambourins et des chœurs; et elle était seule, unique; il n\'avait point d\'autres fils ou filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Et quand il la vit, il déchira ses vêtements et dit: Ah! ma fille! tu m\'atterres, tu m\'atterres! c\'est toi qui me plonges dans l\'affliction! J\'ai laissé ma bouche promettre à l\'Éternel et je ne puis revenir en arrière!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Et elle lui dit: Mon père, si tu as laissé ta bouche promettre à l\'Éternel, traite-moi d\'après ce qu\'a proféré ta bouche, dès que l\'Éternel t\'a permis de tirer vengeance de tes ennemis, des enfants d\'Ammon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Et elle dit à son père: Qu\'une chose me soit accordée: relâche-toi de deux mois en ma faveur, et j\'irai m\'enfoncer dans les montagnes et y pleurer ma virginité avec mes compagnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Et il lui dit: Va! et il la laissa libre pour deux mois. Et elle s\'en alla avec ses compagnes et pleura sa virginité sur les montagnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Et au bout de deux mois elle revint chez son père et il accomplit sur elle le vœu qu\'il avait fait. Et elle ne connut point d\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'Et l\'usage s\'établit en Israël que toutes les années les filles d\'Israël s\'en vont pendant quarante jours de l\'année louer la fille de Jephthé, de Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Et les hommes d\'Ephraïm se rassemblèrent, et montèrent vers le nord et dirent à Jephthé: Pourquoi t\'es-tu mis en marche pour la guerre des Ammonites sans nous appeler à faire la campagne avec toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Nous allons brûler par le feu ta maison sur toi. Et Jephthé leur dit: J\'étais en grande contestation, moi et mon peuple, avec les Ammonites, et je vous fis un appel, mais vous ne m\'avez pas aidé à me tirer de leurs mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Et voyant que vous ne vouliez pas m\'aider, j\'osai, au péril de ma vie, marcher contre les Ammonites. Et l\'Éternel les a livrés entre mes mains. Pourquoi donc aujourd\'hui vous avancer contre moi pour me faire la guerre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Et Jephthé réunit tous les hommes de Galaad, et il en vint aux mains avec les Ephraïmites, et les hommes de Galaad défirent ceux d\'Ephraïm, car ils disaient: Gens de Galaad, vous êtes des réchappés d\'Ephraïm, un juste milieu entre Ephraïm et Manassé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Et les Galaadites s\'emparèrent des gués du Jourdain vers Ephraïm. Et lorsque quelqu\'un des fuyards d\'Ephraïm disait: Laissez-moi passer! les hommes de Galaad lui demandaient: Es-tu Ephraïmite? et celui-ci répondant: Non!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'ils lui disaient: Prononce donc Schibboleth! Et s\'il prononçait Sibboleth, sans s\'aviser pour prononcer bien, ils le saisissaient et l\'égorgeaient dans le gué du Jourdain. Et dans ce temps-là il périt quarante-deux mille Ephraïmites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Et Jephthé jugea Israël pendant six ans; puis Jephthé de Galaad mourut, et il reçut la sépulture dans l\'une des villes de Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Et après lui Ibtsan de Bethléhem jugea Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Et il eut trente fils et il maria ses trente fils au dehors, et du dehors il introduisit chez lui pour ses fils trente filles, et il jugea Israël pendant sept ans;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'puis Ibtsan mourut, et reçut la sépulture à Bethléhem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Et après lui Elon de Zabulon fut Juge d\'Israël, et il jugea Israël pendant dix ans;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'puis Elon de Zabulon mourut et reçut la sépulture à Ajalon dans le pays de Zabulon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Et après lui Abdon, fils de Hillel, de Pirathon, jugea Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Et il eut quarante fils et trente petits-fils qui montaient soixante-dix ânes poulains. Et il jugea Israël pendant huit ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Puis Abdon, fils de Hillel, de Pirathon, mourut et reçut la sépulture à Pirathon, dans le pays d\'Ephraïm, sur le mont Amalécite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Et les enfants d\'Israël continuèrent de faire ce qui déplaît à l\'Éternel, et l\'Éternel les livra entre les mains des Philistins pour quarante ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Et il y avait un homme de Tsorea, de la race des Danites, et son nom était Manoah. Et sa femme était stérile et n\'enfantait pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Alors un ange de l\'Éternel apparut à la femme et lui dit: Te voilà, hélas! stérile, et tu n\'as pas d\'enfants! mais tu deviendras enceinte et tu enfanteras un fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Dès lors prends garde à toi, et ne bois ni vin, ni cervoise, et ne mange rien d\'immonde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Car voici, tu seras enceinte et tu enfanteras un fils, et le rasoir ne doit point passer sur sa tête. Car dès le sein maternel l\'enfant sera consacré à Dieu; et il commencera à délivrer Israël des mains des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Alors la femme vint parler à son mari et lui dit: Un homme de Dieu est venu à moi, et son aspect était celui d\'un ange de Dieu, très imposant, et je ne lui ai point demandé d\'où il était, et il ne m\'a point indiqué son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Et il m\'a dit: Voici, tu deviendras enceinte et tu enfanteras un fils. Dès lors ne bois ni vin, ni cervoise et ne mange rien d\'immonde, car dès le sein de sa mère jusqu\'à sa mort l\'enfant sera consacré à Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Alors Manoah éleva sa prière vers l\'Éternel et dit: Oh! Seigneur, permets que l\'homme de Dieu que tu as envoyé revienne encore auprès de nous, et nous montre ce que nous devons faire pour l\'enfant qui naîtra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Et Dieu exauça la prière de Manoah et l\'ange de Dieu revint auprès de la femme; or elle était assise dans la campagne et Manoah, son mari, n\'était pas avec elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Et en toute hâte la femme courut informer son mari, et elle lui dit: Voici, l\'homme qui est venu à moi l\'autre jour, m\'est apparu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Alors Manoah se leva et suivit sa femme; et arrivé auprès de l\'homme il lui dit: Es-tu l\'homme qui a parlé à cette femme? Et il répondit: Je le suis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Et Manoah dit: Maintenant, si ce que tu as dit arrive, quelle doit être la règle de l\'enfant et que doit-il faire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Et l\'ange de l\'Éternel dit à Manoah: Il faut que la femme s\'abstienne de tout ce que je lui ai indiqué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Elle ne mangera rien de ce qui sort du cep de vigne, et ne boira ni vin, ni cervoise et ne prendra aucun aliment immonde; elle doit observer tout ce que je lui ai prescrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Et Manoah dit à l\'ange de l\'Éternel: Nous voudrions te retenir, et t\'apprêter et te servir un chevreau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Et l\'ange de l\'Éternel dit à Manoah: Quand tu me retiendrais, je ne mangerais pas de ton mets. Mais, si tu veux préparer un holocauste, offre-le à l\'Éternel. Car Manoah ne savait pas que ce fût un ange de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Et Manoah dit à l\'ange de l\'Éternel: Quel est ton nom, afin que si tes paroles s\'accomplissent, nous te rendions honneur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Et l\'ange de l\'Éternel lui dit: Pourquoi cette question que tu me fais sur mon nom? car il est merveilleux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Alors Manoah prit le chevreau et l\'offrande et en fit un sacrifice à l\'Éternel sur un rocher. Et Il opéra une merveille, et Manoah et sa femme furent témoins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Car comme la flamme s\'éleva de l\'autel vers le ciel, l\'ange de l\'Éternel s\'éleva aussi dans la flamme de l\'autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Et à ce spectacle Manoah et sa femme se jetèrent la face contre terre. Et l\'ange de l\'Éternel n\'apparut plus à Manoah et à sa femme. Alors Manoah comprit que c\'était un ange de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Et Manoah dit à sa femme: Nous allons mourir, puisque nous avons vu Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Mais sa femme lui dit: Si l\'Éternel avait l\'intention de nous faire mourir, Il n\'aurait pas accepté de nos mains holocauste et offrande, et Il ne nous aurait pas fait voir ces choses, ni annoncé maintenant un tel événement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Et cette femme enfanta un fils et l\'appela du nom de Samson (batteur). Et l\'enfant grandit, et l\'Éternel le bénit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Et l\'esprit de l\'Éternel commença à lui donner l\'impulsion à Mahaneh-Dan outre Tsorea et Esthaol.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Samson descendit à Thimna, et distingua à Thimna une femme entre les filles des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Et à son retour il s\'en ouvrit à son père et à sa mère et dit: A Thimna j\'ai distingué une femme outre les filles des Philistins, maintenant demandez-la en mariage pour moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Et son père et sa mère lui dirent: N\'y a-t-il pas de femme parmi les filles de tes frères et dans tout notre peuple, que tu vas prendre une femme chez les Philistins incirconcis? Et Samson dit à son père: Demande celle-là pour moi, car elle me plaît.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Or son père et sa mère ignoraient que cela procédait de l\'Éternel, car il cherchait une occasion fournie par les Philistins. Or à cette époque les Philistins avaient la domination sur Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Samson descendit donc avec son père et sa mère à Thimna. Et lorsqu\'ils arrivèrent au vignoble de Thimna, voilà qu\'un jeune lion rugissant vint à sa rencontre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Alors l\'esprit de l\'Éternel s\'empara de lui; il déchira le lion comme on déchire un chevreau, et il n\'avait rien à la main. Et il ne raconta point à son père et à sa mère ce qu\'il avait fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Et il descendit et parla à la femme, et elle plaisait à Samson.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Et comme il revenait quelque temps après pour l\'épouser, il fit un détour pour voir le squelette du lion; et voilà que dans la carcasse du lion il y avait un essaim d\'abeilles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'et du miel qu\'il emporta dans ses mains et dont il mangea en cheminant. Et étant arrivé chez son père et sa mère il leur en donna, et ils en mangèrent. Et il ne leur découvrit pas qu\'il avait tiré le miel de la carcasse du lion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Et son père descendit auprès de la femme; et Samson donna là un festin, car ainsi le pratiquent les jeunes gens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Et lorsqu\'ils le virent, ils prirent trente compagnons pour être avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Et Samson leur dit: Je veux vous proposer une énigme. Si vous m\'en dites le mot pendant les sept jours du festin, et si vous le trouvez, je vous donnerai trente tuniques et trente habits de rechange.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Mais si vous ne pouvez m\'en dire le mot, ce sera à vous de me donner trente tuniques et trente habits de rechange. Et ils lui dirent: Propose ton énigme pour que nous l\'écoutions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Et il leur dit: De celui qui mange est venu ce qui se mange, et du fort est venu le doux. Et pendant trois jours ils ne purent dirent le mot de l\'énigme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Et le septième jour ils s\'adressèrent à la femme de Samson: Persuade à ton mari de nous dire le mot de l\'énigme, si tu ne veux pas que nous te brûlions toi et la maison de ton père dans les flammes. C\'est pour nous dépouiller que vous nous avez invités! n\'est-ce pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Et la femme de Samson pleurait à ses côtés et lui disait: Tu n\'as pour moi que de la haine et tu ne m\'aimes pas. Tu as proposé une énigme aux fils de mon peuple et tu ne m\'en as pas fait connaître le mot. Et il lui répondit: Je ne l\'ai pas dit à mon père et à ma mère, puis-je te le dire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Et elle pleura à ses côtés pendant les sept jours où ils eurent le festin. Et le septième jour il lui dit le mot, car elle le molestait. Et elle dit le mot de l\'énigme aux fils de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Et le septième jour les gens de la ville lui dirent avant le coucher du soleil: Quoi de plus doux que le miel et de plus fort que le lion! Et il leur dit: Si vous n\'eussiez labouré avec ma génisse, vous n\'eussiez pas trouvé le mot de mon énigme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Alors l\'esprit de l\'Éternel s\'empara de lui, et il descendit à Ascalon, et il en tua trente hommes auxquels il prit leurs habits de rechange et il donna ces habits de rechange à ceux qui avaient dit le mot de l\'énigme. Et il était enflammé de colère et il regagna la maison de son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Et sa femme appartint à l\'ami qu\'il s\'était donné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Et quelque temps après, à l\'époque de la moisson des orges, Samson visita sa femme, apportant un chevreau, et il dit: Je veux entrer chez ma femme dans la chambre; mais le père ne lui permit pas d\'entrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Et le père dit: Je pensais que tu la haïssais et je l\'ai donnée à ton ami. Sa sœur cadette n\'est-elle pas plus belle qu\'elle? prends-la donc à sa place!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Alors Samson leur dit: Cette fois si je fais du mal aux Philistins, les Philistins ne pourront en rejeter la faute sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Et Samson partit, et ayant attrapé trois cents renards, il se procura des torches; et croisant une queue avec l\'autre queue, il fixa une torche entre deux queues, au milieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Puis ayant allumé les torches, il les lâcha dans les moissons des Philistins, et ainsi embrasa et les tas de gerbes et les blés qui étaient sur pied, et les olivaies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Alors les Philistins dirent: Qui a fait cela? Et on dit: C\'est Samson, gendre du Thimnite, parce que celui-ci lui a ôté sa femme et l\'a donnée à son ami. Alors les Philistins arrivèrent, ils la brûlèrent elle et son père dans les flammes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Et Samson leur dit: Est-ce ainsi que vous faites?... Oui, quand j\'aurai tiré vengeance de vous, alors je cesserai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Et il leur frappa jambes et reins d\'un grand coup. Puis il descendit, et prit pour sa demeure la caverne du rocher d\'Eitam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Alors les Philistins se mirent en campagne et vinrent camper en Juda, et ils se déployèrent dans Léchi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Et les hommes de Juda dirent: Pourquoi marchez-vous contre nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Et ils dirent: C\'est pour enchaîner Samson que nous sommes venus, pour lui rendre ce qu\'il nous a fait. Là-dessus trois mille hommes de Juda descendirent à la caverne du rocher d\'Eitam, et ils dirent à Samson: Ne savais-tu pas que les Philistins sont nos dominateurs? et qu\'est-ce que tu nous as fait là? Et il leur dit: Je les ai traités comme ils m\'ont traité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Et ils lui dirent: C\'est pour te garrotter que nous venons, pour te livrer aux mains des Philistins. Et Samson leur dit: Jurez-moi que vous ne me tuerez pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Et ils lui dirent: Non; nous ne voulons que te garrotter et te remettre entre leurs mains; quant à te faire mourir, nous ne le ferons point. Et ils le lièrent de deux cordes neuves, et ils l\'emmenèrent loin du rocher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Il arriva à Léchi et les Philistins l\'accueillirent par des huées; alors l\'esprit de l\'Éternel s\'empara de lui, et les cordes qu\'il avait aux bras ne furent plus que comme des brins de fil qui brûlent dans le feu, et ses liens coulèrent de ses poignets.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Et il trouva une mâchoire d\'âne fraîche, et il étendit la main et la saisit, et en frappa mille hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Et Samson dit: Avec une mâchoire d\'âne, une, deux troupes! Avec une mâchoire d\'âne j\'ai défait mille hommes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Et quand il eut achevé son discours, il jeta la mâchoire loin de sa main, et il nomma ce lieu Ramath-Léchi (jet de la mâchoire).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Et il était fort altéré; alors il invoqua l\'Éternel et dit: Par la main de ton serviteur tu as procuré cette grande victoire, et maintenant devrais-je mourir de soif et tomber entre les mains des incirconcis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Alors Dieu entrouvrit une cavité qui était à Léchi, et il en jaillit de l\'eau et il but, et ses esprits revinrent, et il fut ranimé. C\'est pourquoi on la nomma Source de l\'invocateur, et elle existe encore aujourd\'hui à Léchi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Et il jugea Israël à l\'époque des Philistins pendant vingt ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Et Samson étant allé à Gaza, y vit une courtisane, et il entra chez elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'On dit aux Gazites: Samson est arrivé ici! Et ils firent des rondes, et toute la nuit ils le guettèrent à la porte de la ville, et ils ne firent point de bruit de toute la nuit et ils disaient: Attendons l\'aube du matin; alors nous le tuerons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Et Samson fut couché jusqu\'à minuit; et vers minuit il se leva, et il saisit les deux battants de la porte de la ville et les deux jambages, et les arracha avec la barre, et les chargea sur ses épaules et les porta sur le sommet de la montagne qui est vis-à-vis d\'Hébron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Et il arriva ensuite qu\'il aima une femme dans la vallée de Sorek, et elle se nommait Delila.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Alors les princes des Philistins allèrent chez elle et lui dirent: Flatte-le et observe où gît sa grande force, et par où nous pourrions le maîtriser pour le garrotter et le dompter; et nous, nous te donnerons chacun mille et cent sicles d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Alors Delila dit à Samson: Révèle-moi donc où gît ta grande force, et de quoi il faudrait te lier pour te dompter!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Et Samson lui dit: Qu\'on me lie de sept cordes encore humides, non séchées, et je deviens débile et tel qu\'un autre homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Alors les princes des Philistins firent porter chez elle sept cordes encore humides, non séchées; et elle l\'en garrotta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Or des gens se tenaient chez elle embusqués dans une chambre. Et elle lui dit: Les Philistins contre toi, Samson! Alors il cassa les cordes comme l\'on casse un cordon de chanvre, quand il sent le feu. Et l\'on ne connut pas le secret de sa force.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Alors Delila dit à Samson: Voici, tu m\'as abusée, et tu m\'as fait un mensonge. A présent indique-moi donc avec quoi il faut te lier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Et il lui dit: Qu\'on me lie de cordes neuves qui n\'aient servi à aucun travail, et je deviens débile et tel qu\'un autre homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Alors Delila prit des cordes neuves et l\'en lia; puis elle lui dit: Les Philistins contre toi, Samson! Or des gens se tenaient embusqués dans une chambre. Et il dégagea ses bras en cassant les cordes comme un fil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Alors Delila dit à Samson: Jusqu\'ici tu m\'as abusée et tu m\'as dit des mensonges! Indique-moi avec quoi il faut te lier. Et il lui dit: Si avec des fils tu tisses en natte les sept tresses de ma tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Et avec un clou elle les fixa [à la paroi] et elle lui dit: Les Philistins contre toi, Samson! Et il se réveilla de son sommeil, et rompit le clou qui fixait la natte, et les fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Alors elle lui dit: Comment peux-tu dire: Je t\'aime! tandis que ton cœur n\'est pas avec moi? Voici trois fois que tu m\'abuses sans me révéler où gît ta grande force.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Et comme tous les jours elle l\'importunait par ses discours et par son insistance, son âme ennuyée à la mort perdit patience;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'alors il lui ouvrit tout son cœur et lui dit: Jamais rasoir ne passa sur ma tête, parce que dès le sein de ma mère je suis consacré à Dieu; si j\'étais rasé, ma force s\'en irait, et je deviendrais débile et tel que tous les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Et Delila, voyant qu\'il lui avait ouvert tout son cœur, envoya un message aux princes des Philistins pour les mander et leur dire: Cette fois venez, car il m\'a ouvert tout son cœur. Et les princes des Philistins arrivèrent chez elle et apportèrent l\'argent dans leurs mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Et elle l\'endormit sur ses genoux et fit venir un homme, et elle fit raser les sept tresses de sa tête, et commença ainsi à le dompter, et sa force disparut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Et elle dit: Les Philistins contre toi, Samson! Et il se réveilla de son sommeil; et il se disait: Je m\'en tirerai cette fois comme l\'autre fois et je me dégagerai. Or il ne se doutait pas que l\'Éternel s\'était retiré de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Alors les Philistins le saisirent et lui crevèrent les yeux, et le menèrent à Gaza, et le lièrent d\'une double chaîne d\'airain, et il fut réduit à moudre dans la prison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Cependant sa chevelure commençait à croître depuis qu\'elle avait été rasée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Or les princes des Philistins se réunirent pour immoler un grand sacrifice à Dagon, leur dieu, et pour se réjouir. Et ils dirent: Notre Dieu a fait tomber entre nos mains Samson, notre ennemi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Et quand le peuple le vit, ils louèrent leur dieu; car ils disaient: Notre Dieu a fait tomber entre nos mains notre ennemi, et le dévastateur de notre pays, et le meurtrier d\'un grand nombre des nôtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Et comme ils étaient en belle humeur, ils dirent: Faites venir Samson pour nous divertir. Et ils firent venir Samson de la prison, et il fit des bouffonneries devant eux et ils le placèrent entre les colonnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Et Samson dit au valet qui lui tenait la main: Laisse-moi tâter les colonnes sur lesquelles pose l\'édifice, je voudrais m\'y appuyer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Or l\'édifice était rempli d\'hommes et de femmes, et tous les princes des Philistins s\'y trouvaient; et sur le toit il y avait environ trois mille hommes et femmes regardant Samson faire des bouffonneries.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Alors Samson invoqua l\'Éternel et dit: Seigneur, Éternel! oh! souviens-toi de moi, et prête-moi force pour cette fois seulement, ô Dieu, afin que je tire des Philistins une vengeance unique pour la perte de mes deux yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Et Samson fit pencher les deux colonnes médiales sur lesquelles posait l\'édifice, en s\'y appuyant, à l\'une de la main droite, à l\'autre de la gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Et Samson dit: Que je périsse avec les Philistins! Et il les renversa avec force, et l\'édifice croula sur les princes et sur tout le peuple présent, et les morts qu\'il fit mourir lors de sa mort, furent plus nombreux que ceux qu\'il avait fait mourir de son vivant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Et ses frères avec toute la maison de son père vinrent pour l\'enlever; et ils le transportèrent et lui donnèrent la sépulture entre Tsorea et Esthaol dans le tombeau de Manoah, son père. Or il jugea Israël pendant vingt ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Et il y avait un homme de la montagne d\'Ephraïm, et Micha était son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Et il dit à sa mère: Les mille et cent sicles d\'argent qui t\'ont été soustraits et au sujet desquels tu as fait une adjuration prononcée par toi à mes oreilles mêmes, eh bien! cet argent est par devers moi, c\'est moi qui l\'ai soustrait. Alors sa mère dit: Que mon fils soit béni de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Il restitua donc les mille et cent sicles d\'argent à sa mère. Et sa mère dit: J\'ai consacré cet argent à l\'Éternel. De ma main il passera à mon fils pour en faire une image de taille et de fonte, je te le rends donc.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Cependant il restitua l\'argent à sa mère. Alors sa mère prit deux cents sicles qu\'elle remit à l\'orfèvre, et il en fit une image de taille et de fonte qui fut dans la maison de Micha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Et cet homme, Micha, avait une chapelle, et il fit un Ephod, et des Théraphims, et il installa l\'un de ses fils dans lequel il eut un prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'A cette époque il n\'y avait pas de roi en Israël; chacun faisait ce qui lui semblait bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Et il y avait un jeune homme de Bethléhem de Juda, de la famille de Juda, or il était Lévite; et il séjournait là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Et cet homme partit de la ville de Bethléhem de Juda, pour établir son séjour là où il trouverait. Et il arriva dans la montagne d\'Ephraïm à la maison de Micha pour de là continuer sa route.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Et Micha lui dit: D\'où viens-tu? Et il lui dit: Je suis un Lévite, de Bethléhem de Juda, et je vais établir mon séjour là où je trouverai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Et Micha lui dit: Reste avec moi; sois pour moi un père et un prêtre, et je te donnerai dix sicles d\'argent par an et un assortiment d\'habits et ta nourriture. Et le Lévite partit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Et le Lévite se décida à rester avec cet homme, et le jeune homme fut pour celui-ci comme l\'un de ses fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Et Micha installa le Lévite, et le jeune homme devint son prêtre, et il fut dans la maison de Micha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Et Micha dit: Maintenant je sais que l\'Éternel me fera du bien, puisque j\'ai ce Lévite pour prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'A cette époque il n\'y avait pas de roi en Israël, et à cette époque la Tribu des Danites se cherchait une propriété où s\'établir, car jusqu\'à ce jour il ne lui était rien échu en propriété parmi les Tribus d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Et les fils de Dan envoyèrent de Tsoréa et d\'Esthaol cinq hommes de leur race pris sur eux tous, hommes de cœur, pour explorer et scruter le pays, et ils leur dirent: Partez et explorez le pays! Et ils pénétrèrent dans la montagne d\'Ephraïm jusqu\'à la maison de Micha, et ils firent là leur halte pour la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Comme ils étaient près de la maison de Micha, ils reconnurent le langage du jeune homme, du Lévite, et ils se dirigèrent de ce côté-là et lui dirent: Qui t\'a amené ici? et que fais-tu dans ce lieu? et qu\'y as-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Et il leur dit: Micha m\'a traité de telle et telle manière, il me salarie pour que je sois son prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Et ils lui dirent: Consulte donc Dieu pour que nous sachions si nous réussirons dans le voyage que nous faisons!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Et le prêtre leur dit: Allez en paix! Le voyage que vous faites est sous le regard de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Et les cinq hommes partirent et parvinrent à Laïs. Et ils virent que le peuple qui y était, vivait en sécurité, à la manière des Sidoniens, paisible et confiant, et que dans le pays il n\'y avait pas de maître du pouvoir qui leur fît injure en rien; d\'ailleurs, ils étaient à distance des Sidoniens et ils n\'avaient pas affaire avec les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Et ils revinrent auprès de leurs frères à Tsoréa et Esthaol, et leurs frères leur dirent: Qu\'apportez-vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Et ils répondirent: Levons-nous et marchons contre eux; car nous avons examiné le pays; et voici, il est excellent; mais ne dites mot! Ne tardez pas à marcher, à aller conquérir le pays!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'En arrivant vous arriverez chez un peuple en sécurité; et le pays est vaste dans les deux sens. Car Dieu livre ce pays entre vos mains, cette contrée où rien ne manque de tout ce qui est sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Alors de là, de Tsoréa et d\'Esthaol, partirent six cents hommes de la Tribu des Danites, munis de l\'attirail de guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Et s\'étant avancés ils campèrent à Kiriath-Jearim en Juda. C\'est pourquoi ce lieu conserve jusqu\'aujourd\'hui le nom de Mahaneh-Dan (camp de Dan).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Voici, il est derrière Kiriath-Jearim. Et de là ils passèrent sur les monts d\'Ephraïm, et atteignirent la maison de Micha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Alors les cinq hommes qui étaient allés explorer la région de Laïs, prirent la parole et dirent à leurs frères: Savez-vous que dans [l\'une de] ces maisons il y a un Ephod et des Théraphims et une image de taille et de fonte? Voyez donc ce que vous avez à faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Et ils se dirigèrent de ce côté-là, et ils entrèrent dans la maison du jeune Lévite, dans la maison de Micha, et ils le saluèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Or les six cents hommes (qui étaient d\'entre les Danites) munis de leurs armes de guerre étaient postés à l\'entrée de la porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Alors les cinq hommes qui étaient allés explorer le pays montèrent, entrèrent là, et prirent l\'image taillée et l\'Ephod et les Théraphims et l\'image de fonte; or le prêtre se tenait à l\'entrée de la porte comme les six cents hommes munis d\'armes de guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Ceux-là donc pénétrèrent dans la maison de Micha et enlevèrent l\'image taillée et l\'Ephod et les Théraphims et l\'image de fonte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Alors le prêtre leur dit: Que faites-vous? Et ils lui dirent: Tais-toi! mets ta main sur ta bouche et viens avec nous, et sois pour nous un père et un prêtre! Vaut-il mieux pour toi être le prêtre de la maison d\'un seul homme, ou bien être le prêtre d\'une tribu et d\'une race en Israël?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Et cela satisfit le cœur du prêtre, qui prit l\'Ephod et les Théraphims et l\'image taillée et se mêla à ce peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Et ils firent volte-face et partirent en se faisant précéder par les enfants, le bétail et les bagages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Ils étaient à distance de la maison de Micha lorsque les gens logés dans les maisons voisines de la maison de Micha se rassemblèrent et se mirent à la poursuite des Danites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Et ils hélèrent les Danites, et ceux-ci tournant la tête dirent à Micha: Que veux-tu avec ta bande?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Et il dit: Vous avez enlevé mes dieux que j\'ai faits et le prêtre et vous êtes partis; et que me reste-t-il? et que faites-vous de me dire: que veux-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Et les Danites lui dirent: Ne nous fais pas entendre ta voix, si tu ne veux pas que des hommes exaspérés fondent sur vous et mettent en danger ta vie et la vie de ta maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Là-dessus les Danites suivirent leur route, et Micha voyant qu\'ils étaient plus forts que lui, fit volte-face et retourna dans sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Cependant ils avaient pris l\'ouvrage fait par Micha et le prêtre qui était à lui. Ils attaquèrent Laïs, des gens paisibles et pleins de sécurité, et ils les frappèrent avec le tranchant de l\'épée et ils incendièrent la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Et il n\'y eut point de libérateur, car elle était éloignée de Sidon, et ils n\'avaient point affaire avec les hommes: or elle était dans la vallée qui avoisine Beth-Rehob. Et ils rebâtirent la ville et s\'y établirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Et ils nommèrent la ville Dan du nom de Dan, leur père, qui était né à Israël; mais Laïs était primitivement le nom de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Et les Danites érigèrent l\'image pour leur usage, et Jonathan, fils de Gersom, fils de Moïse, lui et ses fils furent prêtres de la Tribu des Danites jusqu\'à l\'époque de la captivité du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Et l\'image faite par Micha resta debout pour leur usage pendant tout le temps que la maison de Dieu fut à Silo.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Et à cette époque où il n\'y avait pas de roi en Israël, il se trouva qu\'un homme de Lévi séjournait au fond des monts d\'Ephraïm; et il prit une femme, une concubine, de Bethléhem de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Et elle lui fit infidélité et elle le quitta et regagna la maison de son père à Bethléhem de Juda, et elle y demeura un an quatre mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Alors son mari se leva et il alla après elle pour parler à son cœur et la ramener; or il avait avec lui son valet et une couple d\'ânes. Et elle l\'introduisit dans la maison de son père, et l\'ayant vu, le père de la jeune fille vint joyeux au-devant de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Et son beau-père, le père de la jeune fille, le retint à demeurer trois jours avec lui. Et ils mangèrent et burent et ils passèrent la nuit là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Et le quatrième jour ils se levèrent le matin, et il se mettait en devoir de partir, lorsque le père de la jeune fille dit à son gendre: Prends pour soutenir ton cœur un peu de nourriture, et ensuite vous partirez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Et ils s\'assirent et mangèrent et burent les deux ensemble. Puis le père de la jeune fille dit à l\'homme: Consens donc à passer la nuit ici et que ton cœur soit content.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Et comme il se disposait à partir, son beau-père le pressa tellement que derechef il resta pour la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Et le cinquième jour dès le matin il se leva pour s\'en aller. Alors le père de la jeune fille lui dit: Restaure-toi donc le cœur, et ils différèrent jusqu\'au déclin du jour et ils mangèrent ensemble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Alors avec sa concubine et son valet l\'homme s\'apprêta à partir; et son beau-père, père de la jeune fille, lui dit: Vois donc! le jour baisse, le tard arrive! passez donc ici la nuit! Voici la chute du jour! passe ici la nuit et te réjouis le cœur, et demain dès le matin vous vous mettrez en route pour regagner ta tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Mais l\'homme ne voulut pas rester encore une nuit; et s\'étant levé il partit; et il arriva jusqu\'en vue de Jébus, c\'est-à-dire, Jérusalem; or il avait avec lui une couple d\'ânes bâtés et sa concubine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Il étaient près de Jébus, et le jour avait beaucoup baissé. Et le valet dit à son maître: Viens, s\'il te plaît, et entrons dans cette ville des Jébusites pour la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Mais son maître lui dit: Nous n\'irons point loger dans une ville de l\'étranger, où il n\'y a point d\'enfants d\'Israël, mais nous gagnerons Gibea.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Et il dit à son valet: Viens et avançons vers un de ces lieux pour passer la nuit à Gibea ou à Rama.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Et ils passèrent outre et cheminèrent, et le soleil se coucha pour eux près de Gibea, qui est à Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Et ils tournèrent de ce côté pour venir passer la nuit à Gibea. Et y étant entré il s\'arrêta dans la place de la ville, et il n\'y eut personne qui leur offrît un asile dans sa maison pour la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Et voilà qu\'un vieillard revenait des champs après son travail le soir; or cet homme était des monts d\'Ephraïm, et il séjournait à Gibea; et les gens du lieu étaient Benjaminites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'et ayant levé les yeux il aperçut le voyageur dans la place de la ville; et le vieillard dit: Où vas-tu et d\'où viens-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Et il lui répondit: De Bethléhem de Juda nous allons au fond de la montagne d\'Ephraïm d\'où je suis; et je suis allé à Bethléhem de Juda, et je me rends à la maison de l\'Éternel, et personne ne m\'offre un asile dans sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Et nous avons et litière et fourrage pour nos ânes; et j\'ai aussi du pain et du vin pour moi et pour ta servante et pour le valet qui accompagne tes serviteurs; nous n\'avons faute de rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Alors le vieillard dit: Rassure-toi! tout ce qui te manque sera à ma charge seulement; seulement tu ne passeras pas la nuit dans la rue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Et il le mena dans sa maison, et garnit le râtelier pour les ânes; et ils baignèrent leurs pieds et ils mangèrent et burent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Comme ils se récréaient le cœur, voilà que les hommes de la ville, gens dépravés, entourèrent la maison en se ruant contre la porte, et ils dirent au vieillard, maître de la maison: Livre-nous l\'homme arrivé chez toi, pour que nous le connaissions!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Alors le maître de la maison se présenta à eux et leur dit: Non! mes frères, oh! non, ne faites pas le mal! Dès que cet homme est entré dans ma maison, ne commettez pas cette action infâme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Voici, ma fille qui est vierge, et sa concubine, je vous les livrerai; abusez d\'elles, et les traitez à votre gré; mais sur cet homme ne commettez pas cette action infâme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Mais ces gens ne voulurent pas l\'écouter. Alors l\'homme prit sa concubine et la leur amena dans la rue; et ils la connurent, et assouvirent sur elle leur lubricité toute la nuit jusqu\'au matin, et ils la relâchèrent au lever de l\'aurore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Et à l\'aube du matin cette femme vint tomber à la porte de la maison de l\'homme chez qui était son maître et elle fut là jusqu\'au jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Et le matin comme son maître s\'étant levé ouvrait les portes de la maison et sortait pour suivre sa route, voilà que sa concubine était étendue à la porte de la maison, les mains posées sur le seuil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Et il lui dit: Lève-toi et partons! Mais personne ne répondit: Alors le mari la chargea sur son âne, et se mit en marche et gagna sa demeure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Et arrivé dans sa maison il prend le couteau, et saisit sa concubine, et la coupe en douze pièces et la démembre, et en fait des envois dans tout le territoire d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'A ce spectacle tout le monde dit: Jamais fait pareil ne s\'est passé ni vu depuis le jour où les enfants d\'Israël sortirent du pays d\'Egypte jusqu\'aujourd\'hui! Ayez-le sur le cœur, consultez-vous et parlez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Et de Dan à Beerséba et au pays de Galaad tous les enfants d\'Israël se mirent en mouvement comme un seul homme, et l\'Assemblée se réunit devant l\'Éternel à Mitspa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Et dans l\'Assemblée du peuple de Dieu parurent les chefs de tout le peuple, toutes les Tribus d\'Israël, quatre cent mille hommes de pied, tirant l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Et les enfants de Benjamin apprirent que les enfants d\'Israël étaient montés à Mitspa. Et les enfants d\'Israël dirent: Exposez la manière en laquelle ce forfait a été commis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Alors le Lévite, mari de la femme qu\'on avait tuée, prit la parole et dit: J\'entrai à Gibea en Benjamin, moi et ma concubine, pour y passer la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Et les citoyens de Gibea firent une émeute contre moi, et à cause de moi pendant la nuit ils cernèrent la maison. Ils pensaient à me tuer, et ils ont si indignement abusé de ma concubine qu\'elle en est morte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Alors j\'ai pris ma concubine et je l\'ai coupée en pièces dont j\'ai fait des envois dans toutes les terres de l\'héritage d\'Israël, parce qu\'on a commis un forfait et une action infâme en Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Voilà que vous êtes tous ici, enfants d\'Israël; ici même délibérez et décidez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Alors tout le peuple se leva comme un seul homme et dit: Tous tant que nous sommes, nous ne voulons ni retourner à nos tentes ni rentrer dans nos maisons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Et maintenant voici comment nous traiterons Gibea: le sort désignera ceux de nous qui marcheront contre elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Et nous lèverons dix hommes sur cent dans toutes les Tribus d\'Israël et cent sur mille et mille sur dix mille, pour procurer des vivres à la troupe afin que s\'étant mise en marche, elle traite Gibea de Benjamin en raison exacte de l\'action infâme commise en Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Tous les hommes d\'Israël se rassemblèrent donc près de la ville unis comme un seul homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Et les Tribus d\'Israël députèrent à toutes les familles de Benjamin, pour dire: Qu\'est-ce que ce crime qui s\'est commis chez vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Et maintenant livrez-nous les hommes dépravés de Gibea afin que nous les fassions mourir et que nous exterminions le crime du sein d\'Israël. Mais les Benjaminites ne voulurent pas écouter la voix de leurs frères, les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Et les enfants de Benjamin vinrent de leurs villes se réunir à Gibea pour marcher au combat contre les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Et l\'on fit ce jour-là passer à la revue vingt-six mille Benjaminites tirant l\'épée sortis des villes, non compris les habitants de Gibea qui passèrent à la revue au nombre de sept cents hommes d\'élite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Sur toute cette milice il y avait sept cents hommes d\'élite inhabiles de la main droite; tous ils lançaient une pierre avec la fronde et ne manquaient pas le but d\'un cheveu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Et les Israélites qui passèrent à la revue, étaient, sans Benjamin, quatre cent mille hommes tirant l\'épée, tous gens de guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Et s\'étant mis en marche ils montèrent à Béthel et consultèrent Dieu. Et les enfants d\'Israël demandèrent: Lequel de nous marchera le premier au combat contre les enfants de Benjamin? Et l\'Éternel dit: Juda marchera le premier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Là-dessus les enfants d\'Israël se mirent en campagne le matin, et ils vinrent camper devant Gibea.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Et les hommes d\'Israël sortirent pour livrer bataille aux Benjaminites, et ils se rangèrent en bataille contre eux devant Gibea.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Alors les Benjaminites firent une sortie de Gibea, et en ce jour tuèrent aux Israélites vingt-deux mille hommes qui jonchèrent le sol.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Mais l\'armée, les hommes d\'Israël, prirent courage et reformèrent leur ligne dans le lieu même où le premier jour ils l\'avaient formée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Et les enfants d\'Israël montèrent [à Béthel] et pleurèrent devant l\'Éternel jusqu\'au soir, et ils consultèrent l\'Éternel en disant: Dois-je engager de nouveau le combat avec les enfants de Benjamin, mon frère? Et l\'Éternel dit: Attaque-les!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Les enfants d\'Israël s\'avancèrent donc contre les enfants de Benjamin, le deuxième jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Mais Benjamin sortit de Gibea à leur rencontre, le deuxième jour, et fit encore mordre la poussière à dix-huit mille hommes des enfants d\'Israël, tous tirant l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Alors tous les enfants d\'Israël et tout le peuple montèrent et vinrent à Béthel, et pleurant ils s\'assirent là devant l\'Éternel, et ils jeûnèrent ce jour-là jusqu\'au soir et offrirent à l\'Éternel des holocaustes et des sacrifices pacifiques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Et les enfants d\'Israël consultèrent l\'Éternel (or à cette époque l\'Arche de l\'Alliance de Dieu était là;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'et Phinées, fils d\'Eléazar, fils d\'Aaron, était en charge devant Lui à cette époque) en disant: Dois-je derechef marcher au combat contre les enfants de Benjamin, mon frère, ou bien me désisterai-je? Et l\'Éternel dit: Marchez, car demain je les livrerai entre vos mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Alors Israël dressa une embuscade contre Gibea de tous les côtés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Et les enfants d\'Israël marchèrent contre ceux de Benjamin le troisième jour, et ils prirent position devant Gibea cette fois comme les autres fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Ensuite les enfants de Benjamin firent une sortie contre cette armée, et ils se laissèrent entraîner loin de la ville, et cette fois comme les autres fois ils se mirent à frapper et à tuer dans les rangs du peuple, sur les routes dont l\'une mène à Béthel et l\'autre à Gibea par la campagne, environ trente hommes d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Et les enfants de Benjamin disaient: Ils sont battus par nous, comme au début. Mais les enfants d\'Israël disaient: Fuyons, afin de les attirer loin de la ville sur ces routes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Et tous les hommes d\'Israël quittant leur position formèrent leur ligne à Baal-Thamar, et les Israélites embusqués s\'élancèrent hors de leur retraite, de la steppe de Gibea.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Et de devant Gibea s\'avancèrent dix mille hommes d\'élite de tout Israël, et l\'action devint sérieuse. Or [les Benjaminites] ne se doutaient pas du désastre qu\'ils allaient essuyer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Et l\'Éternel battit Benjamin devant Israël; et les enfants d\'Israël, dans cette journée, tuèrent à Benjamin vingt-cinq mille et cent hommes tous tirant l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Les enfants de Benjamin voyaient déjà en déroute les enfants d\'Israël qui cédaient le terrain aux Benjaminites, comptant sur l\'embuscade qu\'ils avaient dressée contre Gibea.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Mais ces gens embusqués par un prompt mouvement assaillirent Gibea et l\'occupèrent et frappèrent toute la ville avec le tranchant de l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Or les hommes d\'Israël étaient convenus avec les gens embusqués de ceci: « Faites en sorte qu\'il s\'élève de la ville un gros nuage de fumée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'C\'est alors que dans la bataille les Israélites firent leur conversion, Benjamin commençant à tuer environ trente hommes à Israël et disant: Nul doute! ils sont battus par nous comme dans la première bataille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Cependant de la ville commençait à s\'élever le nuage, une colonne de fumée; et les Benjaminites regardèrent derrière eux, et voilà que toute la ville en feu s\'élevait vers le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Et les Israélites ayant fait leur conversion, les hommes de Benjamin furent éperdus, car ils se voyaient sous le coup du désastre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Et tournant le dos aux Israélites ils prirent le chemin du désert; mais les combattants s\'acharnèrent sur leurs traces, et massacrant ceux des villes dans les villes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'cernant et poursuivant Benjamin, l\'écrasant quand il s\'arrêtait, et cela jusque vis-à-vis de Gibea du côté du soleil levant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Et ainsi périrent dix-huit mille hommes de Benjamin, tous braves guerriers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Et ayant tourné le dos, ils s\'enfuirent dans le désert au rocher de Rimmon; mais les Israélites firent sur les routes une glanure de cinq mille hommes, et les poursuivirent jusqu\'à Gédéon, et ils en tuèrent deux mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Et la totalité des Benjaminites tués dans cette journée fut de vingt-cinq mille hommes tirant l\'épée et tous braves guerriers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Et il y eut six cents hommes qui ayant tourné le dos s\'enfuirent dans le désert au rocher de Rimmon et ils y demeurèrent quatre mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Et les Israélites revinrent aux Benjaminites [restants], et ils les frappèrent avec le tranchant de l\'épée depuis les hommes des villes jusqu\'au bétail et à tout ce qui se trouva, ils incendièrent aussi toutes les villes qu\'ils rencontrèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Or les hommes d\'Israël avaient fait ce serment à Mitspa: Aucun de nous ne donnera sa fille en mariage à un Benjaminite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Et le peuple vint à Béthel où il resta jusqu\'au soir en la présence de Dieu, et ils élevèrent leurs sanglots, et tout en pleurs firent une grande lamentation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'Et ils disaient: Pourquoi faut-il, Éternel, Dieu d\'Israël en Israël, qu\'aujourd\'hui toute une Tribu manque en Israël?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Et le lendemain dès le matin le peuple fut debout, et ils bâtirent là un autel et offrirent des holocaustes et des sacrifices pacifiques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Et les enfants d\'Israël dirent: Qui est-ce qui dans toutes les Tribus d\'Israël ne s\'est pas rendu à l\'Assemblée auprès de l\'Éternel? Car un grand serment a été prononcé contre celui qui ne se présenterait pas devant l\'Éternel à Mitspa; on a dit: Il sera mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Et les enfants d\'Israël s\'affligèrent au sujet de Benjamin, leur frère, et dirent: Aujourd\'hui donc une Tribu a été retranchée d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Que ferons-nous pour eux, les survivants, à l\'égard des femmes? Car nous avons juré par l\'Éternel de ne point leur donner de nos filles en mariage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Et ils dirent: Quels sont les seuls dans les Tribus d\'Israël qui n\'aient point paru devant l\'Éternel à Mitspa? Et voici, de Jabès en Galaad personne ne s\'était rendu à l\'armée, à l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Et l\'on fit passer le peuple à la revue, et voilà qu\'il n\'y avait aucun des habitants de Jabès en Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Alors l\'Assemblée y détacha douze mille hommes pris entre les braves, et on leur donna cet ordre: Allez et frappez les habitants de Jabès de Galaad avec le tranchant de l\'épée, et les femmes et les enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Et voici comment vous les traiterez: vous dévouerez tous les mâles, et toute femme ayant connu la cohabitation d\'un homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Et ils trouvèrent parmi les habitants de Jabès en Galaad quatre cents jeunes filles vierges n\'ayant pas connu la cohabitation d\'un homme, et ils les amenèrent dans le camp à Silo qui est dans le pays de Canaan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Alors toute l\'Assemblée s\'adressa par députés aux Benjaminites retirés au rocher de Rimmon, et leur annonça la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Et dans ce temps les Benjaminites revinrent, et on leur donna les femmes qui avaient survécu aux femmes de Jabès en Galaad, mais ce nombre ne fut pas suffisant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Cependant le peuple s\'affligeait au sujet de Benjamin, parce que l\'Éternel avait fait une brèche dans les Tribus d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Et les Anciens de l\'Assemblée dirent: Que pourrions-nous faire pour les survivants quant aux femmes? Car les femmes ont été exterminées de Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Et ils dirent: Que la propriété dévolue aux réchappés soit maintenue à Benjamin, afin qu\'une Tribu ne soit pas rayée d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Cependant nous ne pouvons leur donner de nos filles en mariage, puisque les enfants d\'Israël ont fait ce serment: Maudit soit celui qui mariera une fille en Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Et ils dirent: Voici, toutes les années il y a une fête de l\'Éternel à Silo qui est au nord de Béthel, à l\'orient de la route qui monte de Béthel à Sichem et au midi de Lebona.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Et ils donnèrent cette instruction aux Benjaminites: Venez et vous mettez en embuscade dans les vignes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'et regardez! et voici, lorsque les filles de Silo sortiront pour danser en chœur, sortez aussi des vignes, et ravissez chacun pour vous une femme parmi les filles de Silo, puis rentrez sur le territoire de Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Et si leurs pères ou leurs frères viennent nous prendre à partie, nous leur dirons: Accordez-les, à nous, de bon gré (car ils n\'ont pas reçu chacun sa femme dans la guerre), puisque ce n\'est pas vous qui les leur avez données; dans ce dernier cas vous seriez en faute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Et ainsi firent les enfants de Benjamin, et ils enlevèrent un nombre de femmes égal au leur, parmi les danseuses dont ils furent les ravisseurs, puis ils partirent et regagnèrent leur domaine, et ils bâtirent les villes et s\'y établirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Et en ce temps les enfants d\'Israël s\'en allèrent de là chacun dans sa Tribu et dans sa famille, se rendant chacun dans sa propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'En ce temps-là il n\'y avait pas de roi en Israël et chacun faisait ce qui lui semblait bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Et à l\'époque du régime des juges il survint une famine dans le pays. Et un homme de Bethléhem de Juda émigra pour établir son séjour en Moabie, lui, sa femme et ses deux fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Or le nom de cet homme était Elimélech, et le nom de sa femme, Noomi, et le nom de ses deux fils, Mahlon et Chilion, Ephratites de Bethléhem de Juda. Et arrivés en Moabie, ils s\'y fixèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Cependant Elimélech, mari de Noomi, vint à mourir, et elle resta avec ses deux fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Et ils épousèrent des femmes Moabites qui se nommaient, l\'une, Orpa, l\'autre Ruth, et ils demeurèrent là près de dix ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Puis Mahlon et Chilion moururent tous deux aussi, et la femme survécut à ses deux fils et à son mari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Alors elle se disposa avec ses deux brus à revenir de Moabie, parce qu\'en Moabie elle avait appris que l\'Éternel avait visité son peuple pour lui donner du pain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Elle quitta donc le lieu où elle avait vécu, et ses deux brus avec elle, et elles se mirent en chemin pour retourner au pays de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Alors Noomi dit à ses deux brus: Allez, retournez chacune dans la maison de sa mère! Que l\'Éternel agisse envers vous avec amour, comme vous l\'avez fait envers les décédés et envers moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Que l\'Éternel vous donne de trouver le repos chacune dans la maison d\'un époux! Et elle les embrassa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'Alors elles élevèrent leur voix et pleurèrent; et elles lui dirent: Non! nous irons avec toi rejoindre ton peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Et Noomi dit: Retournez donc, mes filles! Pourquoi viendriez-vous avec moi? Ai-je encore dans mon sein des fils qui puissent devenir pour vous des époux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Retournez, mes filles, allez! Car je suis trop vieille pour être à un mari. Quand je penserais: Il y a lieu pour moi d\'espérer; quand cette nuit même je me trouverais mariée, bien plus, quand j\'enfanterais des fils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'voudriez-vous pour cela attendre qu\'ils aient grandi, et vous séquestrer pour ne point vous marier? Oh! non! mes filles! j\'ai plus d\'amertumes que vous, car la main de l\'Éternel a frappé sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Et elles élevèrent leur voix et se remirent à pleurer. Alors Orpa donna le baiser à sa belle-mère, mais Ruth s\'attacha à elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Et [Noomi] dit: Voilà que ta belle-sœur est allée retrouver son peuple et son Dieu: suis ta belle-sœur et t\'en retourne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Mais Ruth dit: Ne me presse pas de te quitter, de renoncer à te suivre! non! où tu iras, j\'irai, où tu coucheras, je coucherai; ton peuple est mon peuple, et ton Dieu mon Dieu:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'où tu mourras, je veux mourir, et là trouver ma sépulture; si non, que l\'Éternel m\'inflige ceci et plus encore! c\'est la mort qui mettra une barrière entre moi et toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Et la voyant fermement résolue à l\'accompagner, Noomi renonça à la contrarier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Elles firent donc le voyage à elles deux jusqu\'à leur arrivée à Bethléhem. Et à leur entrée dans Bethléhem, toute la ville s\'émut à leur occasion, et les femmes disaient: Est-ce Noomi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Et elle leur répondit: Ne m\'appelez pas Noomi (ma suavité)! appelez-moi Mara (amertume), car le Tout-Puissant m\'a affligée de bien des amertumes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Pourvue je suis partie et l\'Éternel me ramène dénuée. Pourquoi m\'appeler Noomi, quand l\'Éternel se prononce contre moi et que le Tout-Puissant m\'a rendue malheureuse?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Ainsi revint Noomi accompagnée de Ruth, la Moabite, sa bru, qui avait quitté les champs de Moab; or elles arrivaient à Bethléhem au début de la moisson des orges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Et Noomi avait du côté de son mari un parent, grand homme de bien, de la famille d\'Elimélech, et il se nommait Boaz.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Et Ruth, la Moabite, dit à Noomi: Laisse-moi donc aller au champ glaner des épis à la suite de celui aux yeux de qui je trouverai grâce!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Et elle lui dit: Va, ma fille. Et elle alla, et elle vint et glana dans le champ à la suite des moissonneurs. Et fortuitement il se trouva que c\'était une pièce de terre de Boaz qui était de la famille d\'Elimélech.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Et voilà que Boaz vint de Bethléhem; et il dit aux moissonneurs: Que l\'Éternel soit avec vous! Et ils lui dirent: Que l\'Éternel te bénisse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Et Boaz dit à son valet préposé sur les moissonneurs: A qui est cette jeune personne?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Et le valet préposé sur les moissonneurs répondit et dit: C\'est une jeune Moabite revenue de Moabie avec Noomi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'et elle m\'a dit: Permets-moi de glaner et de ramasser des épis près des javelles à la suite des moissonneurs! et elle est venue et a été assidue depuis le matin jusqu\'à présent, sauf un court moment de repos qu\'elle a pris sous le couvert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Et Boaz dit à Ruth: Entends-tu, ma fille! Ne va pas glaner dans un autre champ, et ne t\'en va pas d\'ici et joins-toi à mes servantes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'aie les yeux sur le champ qu\'on moissonne, et suis-les. Voici, j\'ai défendu aux valets de toucher à toi. Et, si tu as soif, va aux cruches et bois de ce que puiseront les valets.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Alors Ruth tombant à ses pieds et s\'inclinant jusqu\'à terre lui dit: Comment ai-je trouvé grâce à tes yeux pour que tu me traites comme une connaissance, et je suis une étrangère?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Et Boaz répondit et lui dit: On m\'a raconté tout ce que tu as fait pour ta belle-mère après la mort de ton mari, et comment tu as quitté ton père et ta mère et le pays de ta naissance pour venir chez un peuple que tu ne connaissais ni d\'hier, ni d\'avant-hier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Que l\'Éternel te rende ce que tu as fait et qu\'une parfaite récompense te soit accordée par l\'Éternel, Dieu d\'Israël, sous les ailes de qui tu es venue te réfugier!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Et elle dit: Puissé-je trouver grâce à tes yeux, mon Seigneur! Car tu m\'as consolée et tu as parlé au cœur de ta servante, et pourtant je ne suis pas comme l\'une de tes servantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Et au moment du repas Boaz lui dit: Approche et mange de ce pain, et trempe ta mouillette dans le vinaigre. Alors elle s\'assit à côté des moissonneurs, et il lui présenta du grain rôti et elle mangea et se rassasia et en garda des restes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Et elle se leva pour glaner. Alors Boaz donna cet ordre à ses valets: Elle glanera même entre les javelles, et vous ne lui ferez point affront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Et pour elle des faisceaux vous extrairez aussi quelque chose que vous négligerez afin qu\'elle le recueille, et vous ne la gronderez point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Et elle glana dans le champ jusqu\'au soir, et elle égrena sa glane, et il y eut environ un épha d\'orge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Et elle l\'emporta et vint à la ville, et sa belle-mère vit ce qu\'elle avait glané; et Ruth ayant sorti ce qu\'elle avait réservé de son repas, le lui donna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Alors sa belle-mère lui dit: Où as-tu glané aujourd\'hui? D\'où vient ce fruit de ton travail? béni soit celui qui a pris intérêt à toi! Et elle indiqua à sa belle-mère celui chez qui elle avait travaillé, et dit: Le nom de l\'homme chez qui j\'ai travaillé aujourd\'hui est Boaz.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Alors Noomi dit à sa bru: Béni soit-il par l\'Éternel qui ne s\'est point désisté de son amour envers les vivants et envers les décédés! Et Noomi lui dit: Cet homme est notre parent, un de nos proches, ayant envers nous le droit et le devoir lignager.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Et Ruth, la Moabite, dit: Il m\'a dit encore: Joins-toi à mes gens jusqu\'à ce qu\'ils aient achevé toute ma moisson.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Et Noomi dit à Ruth, sa bru: Il est bon, ma fille, que pour sortir tu accompagnes ses servantes, afin qu\'on ne te rencontre pas dans un autre champ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Elle se joignit donc aux servantes de Boaz pour glaner jusqu\'à la fin de la moisson des orges et de celle du froment. Et elle habitait chez sa belle-mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Et Noomi, sa belle-mère, lui dit: Ma fille, ne dois-je pas chercher pour toi un établissement qui te rende heureuse?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Eh bien! Boaz dont tu as accompagné les filles, n\'est-il pas notre parent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Voici, il vanne cette nuit l\'orge sur l\'aire; baigne-toi donc, oins-toi, et te couvre de ta mante, et descends à l\'aire. Reste ignorée de lui jusqu\'à ce qu\'il ait fini de manger et de boire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Et lorsqu\'il se couchera, remarque le lieu où il se couche; puis va, relève la couverture de ses pieds, et couche-toi: or lui-même il t\'indiquera ce que tu as à faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Et elle lui répondit: Tout ce que tu m\'as dit, je le ferai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Elle descendit donc à l\'aire et s\'y prit en tous points comme sa belle-mère l\'avait prescrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Et lorsque Boaz eut mangé et bu et qu\'il eut le cœur gai, il vint se coucher au bout du monceau des gerbes. Alors elle arriva doucement, et elle releva la couverture de ses pieds, puis elle se coucha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Et à minuit il eut une frayeur, et il se pencha en avant, et voilà qu\'une femme était couchée à ses pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Et il dit: Qui es-tu? Et elle dit: Je suis Ruth, ta servante; et étends ton aile sur ta servante, car tu as le droit et le devoir lignager.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Et il dit: Sois bénie par l\'Éternel, ma fille! car tu montres mieux ton amour en dernier lieu que tu ne l\'as déjà fait en premier lieu, car tu ne vises pas aux jeunes hommes, soit pauvres, soit riches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Dès lors, ma fille, sois sans crainte! tout ce que tu as dit, je le ferai pour toi, car toute la Porte de mon peuple sait que tu es une femme de bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Et maintenant, quoiqu\'il soit vrai que je suis lié par le devoir lignager, tu as cependant un parent lignager plus proche que moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Laisse passer la nuit; et dès le matin, s\'il veut user de son droit, bien, qu\'il en use; mais s\'il ne se soucie pas de te réclamer, je te réclamerai, moi, Vive l\'Éternel! Reste couchée jusqu\'au matin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Elle demeura donc couchée à ses pieds jusqu\'au matin. Puis elle se leva avant que deux personnes pussent se reconnaître l\'une l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Et il dit: Il ne faut pas qu\'on sache que la femme est venue sur l\'aire. Et il dit: Donne le manteau que tu as sur toi et tiens-le. Et elle le tint et il mesura six boisseaux d\'orge, et il l\'en chargea puis il revint à la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Et lorsqu\'elle arriva chez sa belle-mère, celle-ci dit: Qui es-tu, ma fille? Et Ruth lui raconta tout ce que l\'homme avait fait pour elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Et elle dit: Il m\'a donné ces six boisseaux d\'orge; car il disait: Tu ne dois pas te présenter sans rien chez ta belle-mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Et celle-ci dit: Attends, ma fille, de voir l\'issue qu\'aura la chose. Car cet homme n\'aura pas de repos qu\'il n\'ait terminé l\'affaire aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Et Boaz se rendit à la Porte, et il y prit séance. El voilà que vint à passer le parent lignager dont Boaz avait parlé; alors il dit: Toi, un tel, viens ici et y prends séance. Et il tira de côté et y prit séance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Et Boaz fit choix de dix hommes parmi les Anciens de la ville et dit: Prenez séance. Et ils prirent séance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Et il dit au parent lignager: La pièce de terre appartenant à notre frère Elimélech est mise en vente par Noomi revenue de Moabie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Et je me suis dit: Je veux t\'en donner avis et te dire: Fais-en l\'acquisition devant l\'assistance et devant les Anciens de mon peuple; si tu veux user du droit de retrait, fais le retrait; si tu ne veux pas, déclare-le-moi, pour que je sois au fait. Car hors toi il n\'y a personne pour faire le retrait, et je viens après toi. Et l\'autre dit: Je veux faire le retrait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Et Boaz dit: En achetant le champ des mains de Noomi, et de Ruth, la Moabite, femme du décédé, tu l\'achètes à la condition de faire revivre le nom du décédé sur son héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Sur ce le parent lignager dit: Dans ce cas je ne puis exercer mon droit sans ruiner mon héritage. Use à ton profit de mon droit de retrait! car je ne puis faire le retrait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Or voici ce qui se pratiquait jadis en Israël, lors d\'un retrait ou d\'une mutation, pour ratifier toute transaction: l\'une des parties ôtait sa sandale et la donnait à l\'autre: telle était la coutume en Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Le parent lignager dit donc à Boaz: Fais l\'achat pour toi! et il ôta sa sandale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Et Boaz dit aux Anciens et à tout le peuple: Aujourd\'hui vous êtes témoins que j\'ai acquis par transmission, de Noomi tout ce qui appartenait à Elimélech, à Chilion et à Mahlon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'et que j\'ai aussi acquis comme ma femme Ruth, la Moabite, femme de Mahlon, pour faire revivre le nom du décédé sur son héritage afin que le nom du décédé ne soit pas extirpé de la souche de ses frères, et de la Porte de sa cité. Soyez-en témoins aujourd\'hui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Et tout le peuple présent dans la Porte et les Anciens dirent: Nous en sommes témoins! Que l\'Éternel rende la femme qui entre dans ta maison, pareille à Rachel et à Léa qui toutes deux ont élevé la maison d\'Israël! Prospère en Ephratha et fais-toi un nom en Bethléhem!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Et que ta maison soit égalée à la maison de Pérets que Thamar enfanta à Juda, par la postérité que l\'Éternel te fera naître de cette jeune femme!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'C\'est ainsi que Boaz épousa Ruth; et elle devint sa femme, et il s\'approcha d\'elle. Et l\'Éternel lui accorda une grossesse, et elle enfanta un fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Alors les femmes dirent à Noomi: Béni soit l\'Éternel qui en ce jour ne t\'a pas laissée sans te donner un réparateur; et que son nom soit prononcé en Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Il sera un réconfort pour ton âme, et un appui pour ta vieillesse. Car ta bru qui t\'aime, l\'a enfanté, elle qui pour toi vaut mieux que sept fils!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Et Noomi prit l\'enfant, et le plaça sur son sein; et elle fut sa garde soigneuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Et les voisines lui donnèrent un nom et dirent: Un fils est né à Noomi! Et elles l\'appelèrent du nom d\'Obed; c\'est lui qui fut le père d\'Isaï, père de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Et voici la généalogie de Pérets:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Pérets engendra Hetsron; et Hetsron engendra Ram; et Ram engendra Amminadab;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'et Amminadab engendra Nahesson; et Nahesson engendra Salmon;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'et Salmon engendra Boaz; et Boaz engendra Obed;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'et Obed engendra Isaï; et Isaï engendra David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Et il y avait un homme de Ramathaïm-Tsophim, des monts d\'Ephraïm, nommé Elkana, fils de Jeroham, fils d\'Elihu, fils de Thobu, fils de Tsouph: c\'était un Ephratite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Et il avait deux femmes nommées, l\'une Hanna, la seconde Peninna; et Peninna avait des enfants, mais Hanna était sans enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Et chaque année depuis sa ville cet homme faisait le pèlerinage pour offrir ses adorations et ses sacrifices à l\'Éternel des armées dans Silo. Or là se trouvaient les deux fils d\'Eli, Hophni et Phinées, Prêtres de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Et le jour où Elkana faisait son sacrifice, il en donnait des parts à Peninna, sa femme, et à tous les fils et filles de celle-ci,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'mais à Hanna il donnait une double part, car il aimait Hanna, mais l\'Éternel l\'avait frappée de stérilité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Et sa rivale la mortifiait jusqu\'à l\'aigrir dans le but de l\'irriter parce que l\'Éternel l\'avait frappée de stérilité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'C\'est ainsi qu\'il faisait d\'année en année toutes les fois que [Hanna] se rendait à la maison de l\'Éternel, et c\'est ainsi que Peninna la mortifiait; et elle pleurait et ne mangeait point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Alors Elkana, son mari, lui disait: Hanna, pourquoi pleures-tu et ne manges-tu pas? et pourquoi ton cœur s\'attriste-t-il? Ne suis-je pas pour toi plus que dix fils?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Et Hanna se leva, après qu\'on eut mangé et bu à Silo. Or le Prêtre Eli était assis sur son siège à côté de la Porte du Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Et elle avait l\'amertume dans le cœur, et elle implorait l\'Éternel, et était toute en larmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Et elle prononça un vœu en ces termes: Éternel des armées, si tu veux prendre en considération la misère de ta servante, et te souvenir de moi, et ne point oublier ta servante, et donner à ta servante une postérité mâle, alors j\'en ferai don à l\'Éternel tout le temps de sa vie, et jamais rasoir ne passera sur sa tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Et comme elle prolongeait sa prière devant l\'Éternel, Eli observa sa bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Or Hanna parlait mentalement, ne remuant que les lèvres, mais sa voix ne se faisait pas entendre; et Eli la crut ivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Et Eli lui dit: Jusques à quand montreras-tu ton ivresse? dissipe le vin qui te maîtrise?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Et Hanna répondit et dit: Non, mon Seigneur! je suis une femme qui souffre intérieurement, et je n\'ai bu ni vin ni cervoise, mais j\'épanchais mon cœur devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Ne mets pas ta servante au rang des femmes viles; c\'est sous le poids de ma pensée et de mon chagrin que j\'ai parlé jusqu\'ici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Et Eli répondit et dit: Va en paix! et que le Dieu d\'Israël t\'accorde la requête que tu lui as adressée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Et elle dit: Puisse ta servante trouver grâce à tes yeux! Là-dessus elle suivit sa route, et elle mangea, et elle n\'eut plus le même air.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Et s\'étant levés dès le matin, et avant présenté leurs adorations à l\'Éternel, ils s\'en retournèrent et revinrent chez eux à Rama. Et Elkana connut Hanna, sa femme, et l\'Éternel se ressouvint d\'elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Et dans le courant de l\'année Hanna devint enceinte et enfanta un fils, et elle lui donna le nom de Samuel (L\'Éternel exauce), car [dit-elle] je l\'ai sollicité de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Et le mari, Elkana, fit le pèlerinage avec toute sa maison pour offrir le sacrifice annuel, et accomplir son vœu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'mais Hanna ne le fit pas; car elle dit à son mari: Lorsque l\'enfant sera sevré, je le mènerai pour qu\'il soit présenté à l\'Éternel, et qu\'il reste là pour toujours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Et Elkana, son mari, lui dit: Fais ce qui te semblera bon, et attends que tu l\'aies sevré. Seulement que l\'Éternel mette à effet sa parole! Sa femme resta donc et elle allaita son fils jusqu\'au sevrage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Et quand elle l\'eut sevré, elle l\'amena avec elle, avec trois taureaux, et un épha de farine et une outre de vin, et elle l\'introduisit dans la maison de l\'Éternel à Silo. Or l\'enfant était encore petit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Et ils égorgèrent le taureau, et amenèrent l\'enfant à Eli.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Et Hanna dit: Pardonne, mon Seigneur! par ta vie, mon Seigneur! je suis cette femme qui me tenais ici debout près de toi adressant ma prière à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'C\'est pour l\'enfant ici présent que je le suppliais, et l\'Éternel m\'a accordé la requête que je lui présentais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'A mon tour je veux le donner en prêt à l\'Éternel: qu\'il reste toute sa vie prêté à l\'Éternel. Et ils rendirent là leurs adorations à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Et Hanna fit une prière et dit: L\'Éternel a transporté mon cœur, l\'Éternel a relevé mon front; ma bouche s\'ouvre contre mes ennemis, car je me réjouis de Ton secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Nul n\'est saint comme l\'Éternel; car nul n\'est sinon Toi, et il n\'est point de rocher comme notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Ne multipliez pas les superbes propos, et que votre bouche n\'exprime pas l\'arrogance! Car l\'Éternel est un Dieu qui connaît, et par Lui les actions sont pesées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Les arcs des héros sont brisés, et ceux qui chancellent se ceignent de vigueur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'ceux qui se rassasiaient se louent pour du pain et les affamés prennent du relâche; la stérile même sept fois enfante, et celle qui a nombre de fils, est languissante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'L\'Éternel donne et la mort et la vie, précipite aux Enfers et en ramène;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'rend pauvre et rend riche, Il abaisse et Il élève,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'de la poudre Il relève les petits, de la fange Il retire l\'indigent, pour le faire asseoir à côté des princes, Il lui adjuge un siège d\'honneur. Car à l\'Éternel sont les colonnes de la terre, sur elles il fait reposer le monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'L\'Éternel a sous sa garde les pas de ses fidèles, mais les impies périssent dans les ténèbres; car ce n\'est pas la force qui fait triompher l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'L\'Éternel! ses ennemis sont terrifiés, sur eux du ciel l\'Éternel tonne. Il juge les extrémités de la terre, et Il donne force à son Roi, et Il tient élevé le front de son Oint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Et Elkana s\'en alla à Rama dans sa maison, tandis que l\'enfant resta au service de l\'Éternel sous les yeux du Prêtre Eli.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Or les fils d\'Eli étaient de mauvais hommes, ils ne connaissaient pas l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'Et voici quelle était la manière de faire des Prêtres à l\'égard du peuple: toutes les fois que quelqu\'un offrait un sacrifice, le valet du Prêtre arrivait au moment de la cuisson de la viande, une fourchette en trident à la main,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'et il piquait dans la chaudière ou dans la marmite, ou dans la poële, ou dans le pot à bouillir, et le Prêtre en prenait tout ce qu\'amenait la fourchette; ainsi procédaient-ils envers tous les Israélites venant là, à Silo.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Même avant qu\'on fit fumer la graisse le valet du Prêtre arrivait et disait au sacrifiant: Donne pour le Prêtre de la viande à rôtir, car il ne recevra pas de toi de la viande bouillie, mais seulement de la viande fraîche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Et si l\'homme lui disait: On va faire fumer la graisse; alors sers-toi au gré de tes désirs! le valet répondait: Nullement! donne sur-le-champ, sinon je prends de force.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Et le péché de ces jeunes gens fut très grand aux yeux de l\'Éternel, parce que ces gens-là méprisaient l\'oblation de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Cependant Samuel faisait le service devant l\'Éternel, comme servant, et il portait un éphod de lin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Et sa mère lui faisait un petit manteau qu\'elle lui apportait chaque année, lorsqu\'elle venait avec son mari offrir le sacrifice annuel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Et Eli bénit Elkana et sa femme et dit: Que l\'Éternel te fasse naître de cette femme une famille en échange du prêt qu\'elle a fait à l\'Éternel. Et ils regagnèrent leur logis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Et quand l\'Éternel jeta la vue sur Hanna, elle devint enceinte et elle enfanta encore trois fils et deux filles. Et le jeune Samuel croissait auprès de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Or Eli était fort âgé et il apprit comment ses fils traitaient tous les Israélites, et comment ils couchaient avec les femmes qui étaient de service à l\'entrée de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Et il leur parla ainsi: Pourquoi vous conduisez-vous comme on le dit? car de tout ce peuple j\'apprends de vous des choses fâcheuses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Non! mes enfants; les bruits que j\'entends ne sont pas favorables: vous fourvoyez le peuple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Qu\'un homme pèche contre un homme, on peut prier Dieu pour lui; mais si un homme pèche contre l\'Éternel, qui intercédera pour lui? Mais ils n\'écoutèrent point la voix de leur père, car l\'Éternel avait résolu de les faire mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Cependant le jeune Samuel continuait de grandir et de plaire et à l\'Éternel et aux hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Et un homme de Dieu vint trouver Eli et lui dit: Ainsi parle l\'Éternel: Me suis-je bien révélé à la maison de ton père lorsqu\'ils étaient en Egypte appartenant à la maison de Pharaon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'et que je l\'ai choisie à l\'exclusion de toutes les Tribus d\'Israël pour exercer de ma part le sacerdoce, pour monter à mon Autel, pour brûler l\'encens, pour porter l\'éphod devant moi, et que j\'ai donné à la maison de ton père tous les sacrifices ignés des enfants d\'Israël?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Pourquoi foulez-vous aux pieds mes sacrifices et mes offrandes que j\'ai ordonnées dans ma Résidence? Et tu estimes tes fils plus que moi, pour vous engraisser des prémices de toutes les offrandes d\'Israël, mon peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'C\'est pourquoi l\'Éternel, Dieu d\'Israël, le déclare: J\'ai dit ta maison et la maison de ton père fonctionneront devant moi éternellement. Mais à présent voici ce que l\'Éternel prononce: Je ne veux plus qu\'il en soit ainsi. Car j\'honore ceux qui m\'honorent, mais ceux qui me méprisent, seront avilis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Voici le temps arrivera où je trancherai ton bras et le bras de la maison de ton père de sorte qu\'il n\'y ait plus de vieillard dans ta maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Et tu verras un rival dans la Résidence, tant que [l\'Éternel] sera le bienfaiteur d\'Israël; et dans ta maison il n\'y aura plus jamais de vieillard.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Mais des alentours de mon autel je ne retrancherai pas l\'un des tiens, afin de consumer tes yeux et de faire languir ton âme; et tous les rejetons de ta maison mourront dans l\'âge viril.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Et tu auras pour signe ce qui arrivera à tes deux fils, Hophni et Phinées: ils mourront l\'un et l\'autre le même jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Et je me susciterai, un Prêtre fidèle; il se réglera d\'après ce qui est dans mon cœur et dans mon âme, et je lui édifierai une maison durable et il marchera devant mon Oint à perpétuité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Et tout ce qui restera de ta maison viendra se prosterner devant lui pour obtenir une menue pièce d\'argent et une galette de pain et dira: Attache-moi donc à l\'un des sacerdoces pour que j\'aie un morceau de pain à manger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Or le jeune Samuel faisait son service devant l\'Éternel sous les yeux d\'Eli. Et la parole de l\'Éternel était rare en ce temps-là; les visions n\'étaient pas fréquentes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Et comme dans ce temps Eli était alité en son lieu, (or ses yeux commençaient à être ternes, il ne pouvait voir),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'la lampe de Dieu n\'était pas encore éteinte, et Samuel était couché dans le Temple de l\'Éternel, place de l\'Arche de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'alors l\'Éternel appela Samuel. Et il répondit: Me voici!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Puis il courut vers Eli et dit: Me voici! car tu m\'as appelé. Et Eli dit: Je ne t\'ai pas appelé; retourne et te couche. Et il alla et se coucha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Et derechef l\'Éternel appela encore Samuel. Et Samuel se leva et alla vers Eli et dit: Me voici! car tu m\'as appelé. Et Eli dit: Je ne t\'ai point appelé, mon fils; retourne et te couche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Or Samuel ne connaissait pas encore l\'Éternel, et la parole de l\'Éternel ne lui avait pas encore été révélée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Et de nouveau l\'Éternel appela Samuel pour la troisième fois. Et Samuel se leva et alla vers Eli et dit: Me voici! car tu m\'as appelé. Alors Eli comprit que l\'Éternel appelait l\'enfant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'et Eli dit à Samuel: Va et te couche, et si l\'on t\'appelle, tu diras: Parle, Éternel, car ton serviteur écoute. Et Samuel alla et se coucha en son lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Alors l\'Éternel vint et se présenta et appela cette fois comme les autres fois: Samuel! Samuel! Et Samuel dit: Parle, car ton serviteur écoute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Et l\'Éternel dit à Samuel: Voici, je vais opérer en Israël une chose telle, que à quiconque l\'apprendra, les deux oreilles lui retentiront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'En ce jour-là j\'accomplirai sur Eli tout ce que j\'ai prononcé; je commencerai et j\'achèverai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Car je lui ai annoncé que je condamne sa maison à perpétuité parcequ\'il a été criminel en ce que sachant que ses fils attiraient sur Dieu le mépris, il ne les a pas contenus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Dès-là je fais à la maison d\'Eli ce serment: Le crime de la maison d\'Eli ne sera expié ni par victime, ni par offrande en aucun temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Et Samuel fut couché jusqu\'au matin; alors il ouvrit les portes de la maison de l\'Éternel. Mais Samuel craignait de raconter la vision à Eli.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Cependant Eli appela Samuel et dit: Samuel, mon fils! Et il répondit: Me voici!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Et Eli dit: Quelle est la parole qu\'Il t\'a adressée? Ne me cèle rien! Que Dieu te le rende et plus encore, si tu me caches rien de tout ce qu\'Il t\'a dit!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Alors Samuel lui rapporta tous les détails, sans lui rien celer. Et Eli dit: C\'est l\'Éternel! qu\'il fasse ce qui lui semblera bon!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Et Samuel grandissait et l\'Éternel était avec lui, et ne laissait tomber à terre aucune de ses paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Et de Dan à Béerséba tout Israël reconnut que Samuel était accrédité comme prophète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Et l\'Éternel continua d\'apparaître à Silo par la parole de l\'Éternel; car l\'Éternel se révélait à Samuel à Silo par la parole de l\'Éternel. Et la parole de Samuel s\'étendait à tout Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Et les Israélites sortirent à la rencontre des Philistins pour livrer bataille, et ils campèrent près d\'Ebenézer; et les Philistins campèrent à Aphek.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Et les Philistins formèrent leurs lignes vis-à-vis des Israélites, et le combat s\'engagea, et les Israélites furent défaits par les Philistins qui, en bataille rangée, leur tuèrent dans la plaine environ quatre mille hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Et le peuple étant rentré dans le camp, les Anciens d\'Israël dirent: Pourquoi l\'Éternel nous a-t-Il aujourd\'hui laissé recevoir ce coup des Philistins? Allons nous chercher à Silo l\'Arche de l\'alliance de l\'Éternel, afin qu\'amenée au milieu de nous elle nous sauve des mains de nos ennemis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Le peuple députa donc à Silo, et l\'on en ramena l\'Arche d\'alliance de l\'Éternel des armées trônant sur les Chérubins; or les deux fils d\'Elie, Hophni et Phinées étaient là accompagnant l\'Arche d\'alliance de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Et à l\'arrivée de l\'Arche d\'alliance de l\'Éternel dans le camp, tous les Israélites applaudirent à grands cris à ébranler la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Et les Philistins entendant retentir ces acclamations dirent: Qu\'est-ce que ces grandes acclamations qui retentissent dans le camp des Hébreux? Et ayant eu connaissance de l\'arrivée de l\'Arche de l\'Éternel dans le camp,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'les Philistins eurent peur, car ils dirent: Dieu est venu au camp! et ils ajoutèrent: Malheur à nous! car ni hier ni avant-hier les choses n\'ont été telles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'malheur à nous! qui nous arrachera des mains de ce Dieu très puissant? C\'est ce Dieu qui frappa les Egyptiens de tous les fléaux dans le désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Ramassez vos forces et soyez hommes, Philistins, pour ne pas être asservis aux Hébreux comme ils vous ont été asservis! soyez donc hommes et combattez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Et les Philistins livrèrent le combat, et les Israélites furent défaits et s\'enfuirent chacun dans leurs tentes, et la déroute fut fort grande, et Israël perdit trente mille fantassins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Et l\'Arche de Dieu fut prise et les deux fils d\'Eli, Hophni et Phinées périrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Alors un homme de Benjamin partit à la course du champ de bataille et parvint à Silo le jour même, les habits déchirés, et la tête couverte de poussière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Et lorsqu\'il arriva, voilà que Eli était assis sur son siège, regardant du côté de la route, car son cœur était inquiet de l\'Arche de Dieu, et lorsque l\'homme vint apporter la nouvelle dans la ville, toute la ville poussa des cris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Et à l\'ouïe de ces cris Eli dit: Que signifie celte rumeur! Et aussitôt l\'homme vint informer Eli.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Or Eli était âgé de quatre-vingt-dix-huit ans, et il avait l\'œil fixe et ne pouvait voir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Et l\'homme dit à Eli: J\'arrive du champ de bataille aujourd\'hui. Et Eli dit: Qu\'a été l\'affaire mon fils?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Et le courrier répondit et dit: Israël a fui devant les Philistins, et de plus la déroute a été grande dans le peuple, et sont aussi morts tes deux fils Hophni et Phinées, et l\'Arche de Dieu est prise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Et quand il fit mention de l\'Arche de Dieu, Eli tomba de son siège à la renverse vers le côté de la porte et se rompit la nuque et mourut, car l\'homme était vieux et appesanti. Or il avait été quarante ans Juge d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Et sa bru, femme de Phinées, était enceinte, près de son terme. Et en apprenant la nouvelle de la prise de l\'Arche de Dieu, et de la mort de son beau-frère et de son mari, elle se baissa et accoucha, car les maux la surprirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Et comme elle se mourait, et que celles qui l\'assistaient dirent: Ne crains point, car tu as enfanté un fils! elle ne répondit point, et ne prit pas garde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Et elle nomma l\'enfant Icabod (sans gloire), et elle dit: « La gloire a émigré d\'Israël! » à cause de la prise de l\'Arche et en vue de son beau-frère et de son mari;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'c\'est pourquoi elle dit: « La gloire a émigré d\'Israël, car l\'Arche de Dieu est prise. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Les Philistins ayant donc pris l\'Arche de Dieu la transférèrent d\'Ebenézer à Asdod.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Et les Philistins ayant pris l\'Arche de Dieu l\'introduisirent dans le temple de Dagon, et la placèrent à côté de Dagon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Et quand le lendemain matin les Asdodéens se levèrent, voilà que Dagon était étendu la face contre terre devant l\'Arche de l\'Éternel. Et ils prirent Dagon et le remirent en place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Et lorsque le lendemain matin ils se levèrent, voilà que Dagon était gisant la face contre terre devant l\'Arche de l\'Éternel, et la tête de Dagon et ses deux mains étaient en tronçons sur le seuil, il ne restait de lui que la partie poisson.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, '(C\'est pourquoi les prêtres de Dagon et tous ceux qui entrent dans le temple de Dagon ne posent point le pied sur le seuil de Dagon à Asdod jusqu\'aujourd\'hui).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Et la main de l\'Éternel s\'appesantit sur les Asdodéens, et Il fit des ravages chez eux et les affligea de bubons, Asdod et son territoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Et les gens d\'Asdod voyant qu\'il en était ainsi, dirent: il ne faut pas que l\'Arche du Dieu d\'Israël reste chez nous, car Sa main a été rigoureuse pour nous et pour Dagon, notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Alors par des envoyés ils convoquèrent chez eux tous les princes des Philistins, et ils dirent: Que ferons-nous de l\'Arche du Dieu d\'Israël? Et il fut dit: Que l\'Arche du Dieu d\'Israël soit transférée à Gath. Et on fit la translation de l\'Arche du Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Et après qu\'elle eut été transférée, la main de l\'Éternel se fit sentir à la ville; il y eut très grande perturbation, et Il frappa les gens de la ville du petit au grand, et ils eurent une éruption de bubons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Alors ils dirigèrent l\'Arche de Dieu vers Ekron. Et lorsque l\'Arche de Dieu entra dans Ekron, les Ekronites se récrièrent et dirent: Ils transfèrent chez nous l\'Arche du Dieu d\'Israël pour nous tuer, nous et notre peuple!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Puis par des députés ils convoquèrent tous les princes des Philistins; et ils dirent: Renvoyez l\'Arche du Dieu d\'Israël, et qu\'elle retourne en son lieu pour qu\'elle ne nous tue pas, nous et notre peuple. Car il y avait dans toute la ville une rumeur de mort; et la main de Dieu s\'y faisait gravement sentir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Et les gens qui ne mouraient pas, étaient affligés de bubons, et les cris de la ville en détresse montaient vers le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Et l\'Arche de l\'Éternel fut sept mois dans le pays des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Et les Philistins mandèrent les prêtres et les devins, et ils dirent: Que ferons-nous de l\'Arche de l\'Éternel? Indiquez-nous avec quoi nous devons la renvoyer dans son lieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Et ils répondirent: Si vous voulez renvoyer l\'Arche du Dieu d\'Israël, il ne faut pas la renvoyer sans rien, mais Lui payer une amende expiatoire: alors vous pourrez guérir et savoir pourquoi sa main n\'a pas cessé de peser sur vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Et ils dirent: Quelle est l\'amende que nous avons à Lui payer? Et ils reprirent: A raison du nombre des Princes des Philistins cinq bubons d\'or et cinq souris d\'or; car la plaie est une pour eux tous et pour vos Princes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Faites donc des effigies de vos bubons et des effigies de vos souris qui ravagent le pays et donnez gloire au Dieu d\'Israël: peut-être aura-t-Il une main plus légère pour vous et pour votre dieu et pour votre pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Et pourquoi endurciriez-vous votre cœur, comme les Egyptiens et Pharaon endurcirent leur cœur? Après qu\'il eut achevé Ses vengeances sur eux, ne leur permirent-ils pas de partir?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'A l\'œuvre donc! procurez-vous et faites un chariot neuf et deux vaches qui allaitent et qui n\'aient pas porté le joug et attelez les vaches au chariot et ôtez-leur leurs veaux que vous ramènerez à l\'étable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Et prenez l\'Arche de l\'Éternel et placez-la sur le chariot, et les ouvrages par lesquels vous Lui payez l\'amende expiatoire, mettez-les dans une cassette à côté; puis laissez-la partir');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'et regardez! Si elle se dirige vers Sa frontière en montant à Beth-Sémès, c\'est Lui qui nous a fait ce grand mal; sinon nous saurons que ce n\'est pas Sa main qui nous a frappés: c\'est pour nous un événement fortuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Et ainsi firent ces hommes; et ils prirent deux vaches qui allaitaient, et les attelèrent à un chariot, et ils tinrent les veaux enfermés à l\'étable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Et ils placèrent l\'Arche de l\'Éternel sur le chariot, ainsi que la cassette et les souris d\'or et les effigies de leurs bubons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Et les vaches allèrent tout droit au chemin de Bethsémès, et elles suivirent une seule route allant toujours et mugissant, et sans s\'écarter ni à droite ni à gauche, et les Princes des Philistins suivirent jusques aux confins de Bethsémès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Or les Bethsémites récoltaient la moisson des orges dans la vallée; et ils levèrent les yeux et ils aperçurent l\'Arche, et ils se réjouirent de la voir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Et le chariot arriva dans le champ de Josué, Bethsémite, et fit halte là; or il y avait là une grande pierre. Et ils fendirent le bois du chariot, et offrirent les vaches en holocauste à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Et les Lévites descendirent l\'Arche de l\'Éternel, et la cassette qui y était jointe et contenait les ouvrages d\'or; et ils les placèrent sur la grande pierre, et les gens de Bethsémès offrirent des holocaustes et sacrifièrent des victimes en ce jour à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Et les cinq Princes des Philistins le virent et retournèrent à Ekron le jour même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Or voici les bubons d\'or par lesquels les Philistins payèrent à l\'Éternel l\'amende expiatoire: pour Asdod, un; pour Gaza, un; pour Askalon, un; pour Gath un; pour Ekron, un.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Et de souris d\'or il y en avait en raison de toutes les villes des Philistins appartenant aux cinq princes depuis les villes fortes aux villages ruraux. Et témoin en est la grande pierre où ils déposèrent l\'Arche de l\'Éternel, jusqu\'à ce jour, dans le champ de Josué, Bethsémite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Et Il porta des coups parmi les Bethsémites, parce qu\'ils avaient regardé l\'Arche de l\'Éternel [sans respect], et Il frappa dans le peuple [ici] soixante-dix hommes, [là] cinquante mille, et le peuple fut dans le deuil de ce que l\'Éternel eût frappé un si grand coup dans le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Et les gens de Bethsémès dirent: Qui pourrait tenir devant l\'Éternel, ce Dieu saint? Et chez qui ira-t-elle en nous quittant?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Et ils envoyèrent des messagers aux habitants de Kiriath-Jearim pour dire: Les Philistins ont ramené l\'Arche de l\'Éternel; descendez et emmenez-la chez vous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Alors vinrent des hommes de Kiriath-Jearim, et ils emmenèrent l\'Arche de l\'Éternel et l\'introduisirent dans la maison d\'Abinadab sur la colline, et ils consacrèrent son fils Eléazar pour garder l\'Arche de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Et depuis le jour où l\'Arche de l\'Éternel séjourna dans Kiriath-Jearim, un long temps s\'écoula; or ce fut vingt ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Et toute la maison d\'Israël allait se plaignant après l\'Éternel. Samuel parla en ces termes à toute la maison d\'Israël: Si c\'est de tout votre cœur que vous revenez à l\'Éternel, bannissez du milieu de vous les dieux de l\'étranger et les Astartés, et dirigez votre cœur vers l\'Éternel, et servez-le seul, et Il vous tirera des mains des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Et les enfants d\'Israël bannirent les Baals et les Astartés et servirent l\'Éternel seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Et Samuel dit: Assemblez tous les Israélites à Mitspa, afin que j\'intercède pour vous auprès de l\'Éternel. Et ils s\'assemblèrent à Mitspa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'et ils puisèrent de l\'eau et la répandirent devant l\'Éternel, et ils jeûnèrent ce jour-là et dirent alors: Nous avons péché contre l\'Éternel. Et Samuel fit à Mitspa, la censure des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Et lorsque les Philistins apprirent que les enfants d\'Israël s\'étaient rassemblés à Mitspa, les Princes des Philistins s\'avancèrent contre Israël; et à cette nouvelle les enfants d\'Israël eurent peur des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Et les enfants d\'Israël dirent à Samuel: Ne néglige pas de supplier pour nous l\'Éternel, notre Dieu, afin qu\'il nous sauve des mains des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Alors Samuel prit un agneau de lait et l\'offrit en holocauste parfait à l\'Éternel, et Samuel supplia l\'Éternel en faveur d\'Israël, et l\'Éternel l\'exauça.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Et au moment même où Samuel offrait l\'holocauste, les Philistins s\'avancèrent à l\'attaque d\'Israël. Et dans cette journée l\'Éternel fit tonner avec grand fracas son tonnerre sur les Philistins, et les mit en déroute, et ils furent battus par les Israélites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Et les hommes d\'Israël sortant de Mitspa poursuivirent les Philistins et les chargèrent jusqu\'au-dessous de Bethcar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Alors Samuel prit une pierre et la plaça entre Mitspa et Sen, et l\'appela du nom d\'Ebenézer (pierre du secours) et dit: Jusqu\'ici l\'Éternel nous a secourus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Ainsi furent abaissés les Philistins qui ne firent plus d\'incursions dans le territoire d\'Israël, et la main de l\'Éternel fut contraire aux Philistins durant toute la vie de Samuel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Et Israël recouvra les villes que les Philistins lui avaient enlevées, depuis Ekron à Gath, et dont il arracha aussi le territoire des mains des Philistins. Et il y eut paix entre Israël et les Amoréens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Et Samuel fut Juge d\'Israël pendant toute sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Et chaque année Samuel allait en tournée à Béthel, à Guilgal et à Mitspa, et dans tous ces lieux il exerçait la judicature sur Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Et il revenait à Rama, car c\'est là qu\'était sa maison et là qu\'il jugeait Israël; et il y éleva un autel à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Et lorsque Samuel fut vieux, il préposa ses fils comme Juges sur Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Et son fils premier-né se nommait Joël et son second fils Abija, et ils exerçaient la judicature à Beerséba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Mais ses fils ne suivirent pas ses errements; la cupidité les fit dévier et ils acceptèrent des présents et firent plier la justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Alors tous les Anciens d\'Israël se réunirent et vinrent trouver Samuel à Rama pour lui dire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'Voilà que tu es âgé et tes fils ne suivent pas tes errements; ainsi, établis-nous un roi qui nous régisse, comme toutes les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Et Samuel trouva mauvais qu\'ils tinssent ce langage: Donne-nous un roi pour nous régir! et Samuel pria l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Et l\'Éternel dit à Samuel: Ecoute la voix du peuple dans tout ce qu\'il te dira; car ce n\'est pas toi qu\'ils rejettent, c\'est moi qu\'ils rejettent pour ne plus m\'avoir pour leur roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'La conduite que toujours ils ont tenue [envers moi] à partir du jour où je les retirai de l\'Egypte, jusqu\'aujourd\'hui, en m\'abandonnant et servant d\'autres dieux, cette même conduite ils l\'ont aussi envers toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Eh bien! écoute leur voix, mais adresse-leur une sommation, et leur explique le régime du roi qui régnera sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Et Samuel rapporta toutes les paroles de l\'Éternel au peuple qui demandait un roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Et il dit: Voici quel sera le régime du roi qui régnera sur vous. Il prendra vos fils qu\'il mettra pour lui sur ses chars et dans sa cavalerie, et comme coureurs ils précéderont son char,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'et il se servira d\'eux pour en faire des chefs de mille et des chefs de cinquante, et pour travailler à son labour et pour récolter ses moissons et pour confectionner ses armes de guerre et l\'attirail de ses chars.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Et il prendra vos filles comme parfumeuses, comme cuisinières et comme boulangères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Et il prendra vos champs et vos vignes et vos olivaies, vos meilleures [terres] pour en doter ses serviteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Et il lèvera des dîmes sur vos grains et vos vignes pour les donner à ses eunuques et à ses domestiques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Et il prendra vos serviteurs et vos servantes et vos jeunes gens d\'élite, les meilleurs, et vos ânes pour les employer à ses affaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Il dîmera vos brebis et vous-mêmes serez ses serviteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Et dans ce temps vous récriminerez contre le roi choisi par vous-mêmes, et l\'Éternel ne vous exaucera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Mais le peuple refusa d\'écouter la voix de Samuel et ils dirent: Non! car il nous faut au-dessus de nous un roi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'afin que nous soyons sur le pied de toutes les nations, et que notre roi nous rende la justice, et marche à notre tête et soutienne nos guerres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Et Samuel entendit tous les propos du peuple et en fit rapport à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Et l\'Éternel dit à Samuel: Acquiesce à leur vœu et donne-leur un roi. Et Samuel dit aux hommes d\'Israël: Allez chacun de vous dans sa ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Et il y avait là un homme de Benjamin, nommé Kis, fils d\'Abiel, fils de Teseror, fils de Bechorath, fils d\'Aphia, fils d\'un Benjaminite; c\'était un brave guerrier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Et il avait un fils, nommé Saül, homme d\'élite et d\'une belle figure; et il n\'y en avait pas de plus beau parmi les enfants d\'Israël, et des épaules en haut il dépassait tout le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Et les ânesses de Kis, père de Saül, se perdirent; et Kis dit à Saül, son fils: Prends donc avec toi l\'un des valets, et lève-toi et va à la recherche des ânesses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Et il franchit les monts d\'Ephraïm et traversa la contrée de Salisa ils ne les trouvèrent pas; et ils parcoururent la région de Saalim, et elles n\'y étaient pas; et ils passèrent par le pays de Benjamin et ils ne les trouvèrent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Ils arrivaient dans la contrée de Tsouph, lorsque Saül dit à son valet qui l\'accompagnait: Viens et retournons, de peur que mon père, cessant de penser aux ânesses ne s\'inquiète de nous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Et le valet lui dit: Mais vois! il y a dans cette ville un homme de Dieu, et cet homme est considéré; tout ce qu\'il annonce, arrive: dès-lors allons-y! peut-être nous éclaircira-t-il sur le voyage où nous sommes engagés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Et Saül dit à son valet: Mais! si nous allons, qu\'offrirons-nous à l\'homme [de Dieu]? Car il n\'y a plus de provisions dans nos valises, et nous n\'avons point de présent à offrir à l\'homme de Dieu. Qu\'avons-nous d\'ailleurs avec nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Et reprenant la parole le valet dit à Saül: Voilà, il se trouve que j\'ai en main un quart de sicle d\'argent, et je le donnerai à l\'homme de Dieu, pour qu\'il nous indique notre route. (');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, 'Jadis en Israël, quand on allait consulter Dieu on disait: Venez et allons au Voyant; car autrefois on donnait au prophète d\'aujourd\'hui le nom de Voyant).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Et Saül dit à son valet: Tu as raison, viens! allons! et ils gagnèrent la ville où était l\'homme de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Ils montaient la montée de la ville, lorsqu\'ils rencontrèrent des jeunes filles sorties pour puiser de l\'eau, et ils leur dirent: Le Voyant est-il ici?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Et elles leur répondirent et dirent: Oui, voilà qu\'il te devance; hâtez-vous seulement, car aujourd\'hui il est venu à la ville pour un sacrifice que le peuple fait sur le tertre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Aussitôt entrés dans la ville vous le trouverez avant qu\'il monte au tertre pour le banquet; car le peuple ne mangera pas avant qu\'il soit venu, parce que c\'est lui qui bénit le sacrifice; après quoi les conviés se mettent à table. Montez donc, car aujourd\'hui vous le trouverez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Et ils montèrent à la ville. Comme ils entraient dans l\'intérieur de la ville, voilà que Samuel sortait au devant d\'eux pour se rendre au tertre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Or, un jour avant l\'arrivée de Saül, l\'Éternel avait fait à Samuel cette révélation:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'A pareil moment demain je t\'enverrai un homme du pays de Benjamin; sacre-le par l\'onction Prince de mon peuple d\'Israël, et il sauvera mon peuple des mains des Philistins, parce que j\'ai regardé mon peuple, car ses cris sont venus jusqu\'à moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Et lorsque Samuel aperçut Saül, l\'Éternel prévint Samuel en disant: Voici l\'homme duquel je t\'ai dit: Il aura le commandement de mon peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Et Saül aborda Samuel dans l\'intérieur de la Porte, et dit: Indique moi je te prie, où est la maison du Voyant!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Et Samuel répondit à Saül et dit: Je suis moi-même le Voyant; précède-moi au tertre, et aujourd\'hui vous prendrez part au banquet avec moi, et demain je te laisserai partir; et je te découvrirai tout ce que tu as dans le cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Et quant aux ânesses perdues pour toi depuis trois jours, ne t\'en inquiètes pas, car elles sont retrouvées. Et à qui sera tout ce qu\'Israël a de cher, sinon à toi et à toute la maison de ton père?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Et Saül répondit et dit: Ne suis-je pas un Benjaminite, de l\'une des plus petites des Tribus d\'Israël, et ma famille n\'est-elle pas la moindre des familles de la Tribu de Benjamin? et pourquoi me tiens tu un pareil langage?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Et Samuel prit Saül et son valet et les introduisit dans la salle, et leur donna une première place parmi les conviés qui étaient au nombre de trente hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Et Samuel dit au cuisinier: Donne le quartier que je t\'ai remis, dont je t\'ai dit: Réserve-le.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Alors le cuisinier sortit l\'éclanche et ce qui y adhère, et la servit devant Saül. Et il dit: Voici la portion réservée, mets-la devant toi et mange, car c\'est dans un but qu\'elle a été gardée pour toi, lorsque j\'ai convié le peuple. Saül mangea donc avec Samuel ce jour-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Et du tertre ils descendirent dans la ville, et Samuel s\'entretint avec Saül sur la terrasse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Et ils se levèrent, et quand l\'aurore surgit, Samuel appela Saül [qui était] sur la terrasse, et il dit: Lève-toi, je veux te reconduire; et Saül se leva et ils sortirent, les deux, lui et Samuel dans la rue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Ils descendirent jusqu\'à l\'extrémité de la ville; alors Samuel dit à Saül: Dis à ton valet de prendre les devants sur nous! (et il prit les devants) mais toi, demeure à présent pour que je te fasse entendre la parole de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Alors Samuel prit la fiole d\'huile, et la répandit sur sa tête, et il l\'embrassa et dit: Voici, par l\'onction l\'Éternel te sacre Prince de son héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Aujourd\'hui après m\'avoir quitté tu trouveras deux hommes près du tombeau de Rachel sur la frontière de Benjamin à Tseltsah, et ils te diront: Les ânesses que tu es allé chercher, sont retrouvées; et voici, ton père ne songe plus à l\'affaire des ânesses, mais il est inquiet de vous et dit: Que dois-je faire à l\'égard de mon fils?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Et de là passant plus loin tu atteindras le chêne de Thabor, où tu seras rencontré par trois hommes se rendant auprès de Dieu à Béthel et portant, l\'un trois chevreaux, l\'autre trois galettes de pain, l\'autre une jarre de vin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Et ils te salueront et te donneront deux pains que tu recevras de leur main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Ensuite tu arriveras à Gibea-Elohim où sont les postes des Philistins, et là, près d\'arriver à la ville tu rencontreras un chœur de prophètes descendant du tertre, précédés de harpes, de tambourins, de flûtes et de luths, et prophétisant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Et l\'Esprit de l\'Éternel s\'emparera de toi et tu prophétiseras avec eux, et seras transformé en un autre homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Et lorsque ces signes auront eu lieu pour toi, entreprends tout ce que tu trouveras à faire, car Dieu est avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Et devance-moi à Guilgal, et voici, je te rejoindrai pour offrir des holocaustes et des sacrifices pacifiques: tu attendras sept jours jusqu\'à ce que je t\'aie rejoint; alors, je t\'instruirai de ce que tu dois faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Et lorsqu\'il eut tourné le dos pour se séparer de Samuel, alors Dieu lui changea le cœur, et le jour même tous ces signes s\'accomplirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Et ils arrivaient là, à Gibea, et voilà qu\'un chœur de prophètes venait à sa rencontre, et l\'Esprit de Dieu s\'empara de lui, et il prophétisa au milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Et lorsque tous ceux qui le connaissaient d\'ancienne date, le virent prophétiser avec les prophètes, dans tout le peuple on se disait mutuellement: Qu\'est-il donc survenu au fils de Kis? Saül est-il aussi au nombre des prophètes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Et un homme de là prit la parole et dit: Et qui est leur père? De là le proverbe: Saül est-il aussi au nombre des prophètes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Et ayant fini de prophétiser, il vint au tertre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Alors l\'oncle de Saül dit à lui et à son valet: Où êtes-vous allés? Et il répondit: Chercher les ânesses, et ne les découvrant nulle part, nous nous sommes rendus auprès de Samuel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Et l\'oncle de Saül dit: Raconte-moi donc ce que Samuel vous a dit!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Et Saül répondit à son oncle: Il nous a annoncé que les ânesses sont retrouvées. Mais quant à l\'affaire de la royauté il ne lui communiqua point ce qu\'avait dit Samuel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Et Samuel convoqua le peuple devant l\'Éternel à Mitspa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Et il dit aux enfants d\'Israël: Ainsi parle l\'Éternel, Dieu d\'Israël: J\'ai retiré Israël de l\'Egypte, et je vous ai arrachés des mains des Egyptiens, et de l\'empire de tous les royaumes de vos oppresseurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'mais aujourd\'hui vous rejetez votre Dieu qui vous a délivrés de toutes vos tribulations et de vos détresses, et vous lui dites: Etablis un roi sur nous. Eh bien donc! présentez-vous devant l\'Éternel rangés selon vos Tribus et vos milliers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Puis Samuel fit approcher toutes les Tribus d\'Israël, et le sort désigna la Tribu de Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Et il fit approcher la Tribu de Benjamin par familles, et le sort désigna la famille de Matri, puis Saül, fils de Kis. Et on le chercha, mais il ne se trouvait pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Alors ils consultèrent encore l\'Éternel: Est-il encore venu un homme ici? Et l\'Éternel dit: Voici il est caché vers les bagages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Alors ils coururent l\'y chercher. Il parut au milieu du peuple, et il dépassait tout le peuple des épaules en haut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Et Samuel dit à tout le peuple: Voyez-vous celui qu\'a élu l\'Éternel? Car il n\'a pas son pareil dans tout le peuple. Alors tout le peuple acclama et dit: Vive le Roi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Et Samuel développa au peuple le statut de la royauté et l\'inscrivit dans un volume qu\'il déposa devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Et Samuel fit retirer tout le peuple, chacun chez soi. Saül aussi se rendit chez lui à Gibea, accompagné du cortège de ceux dont Dieu avait touché le cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Mais des gens de bas aloi dirent: En quoi celui-là nous aidera-t-il? Et ils lui montrèrent du mépris, et ne lui apportèrent point de présents; mais il fut comme sourd.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Et Nahas, l\'Ammonite, s\'avança et vint camper devant Jabès en Galaad. Et tous les hommes de Jabès dirent à Nahas: Accorde-nous une capitulation, et nous nous soumettrons à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Et Nahas, l\'Ammonite, leur dit: Je capitulerai avec vous à cette condition que je vous crève à tous l\'œil droit et qu\'ainsi j\'imprime un affront sur tout Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Et les Anciens de Jabès lui dirent: Accorde-nous sept jours pour dépêcher des messagers dans tout le territoire d\'Israël, et s\'il n\'y a personne pour nous délivrer, nous nous rendrons à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Et les messagers arrivèrent à Gibea-Saül, et ils exposèrent l\'affaire devant le peuple. Et tout le peuple éleva sa voix et pleura.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Et voilà que Saül revenait des champs derrière ses bœufs. Et Saül dit: Qu\'a le peuple pour pleurer? Et on lui rapporta le discours des hommes de Jabès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Alors l\'Esprit de Dieu s\'empara de Saül à cette nouvelle, et sa colère s\'alluma vivement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Et il prit un attelage de bœufs qu\'il coupa en pièces, et il fit porter dans tout le territoire d\'Israël par les messagers cet avis: Ainsi fera-t-on aux bœufs de quiconque ne marchera pas à la suite de Saül et de Samuel. Alors la terreur de l\'Éternel envahit tout le peuple qui se leva comme un seul homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Et il les fit passer à la revue à Bézek; et d\'enfants d\'Israël il y eut trois cent mille, et d\'hommes de Juda trente mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Et ils dirent aux messagers arrivés: Parlez ainsi aux hommes de Jabès en Gaalad: Demain vous aurez du secours lorsque le soleil sera ardent. Et les messagers vinrent faire rapport aux hommes de Jabès qui furent réjouis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Alors les hommes de Jabès dirent [à Nahas]: Demain nous nous rendrons à vous, et vous nous traiterez à discrétion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Et le lendemain Saül rangea le peuple en trois corps; et ils envahirent le camp à la veille matinale, et ils battirent les Ammonites jusqu\'à l\'heure chaude du jour, et les réchappés furent dissipés, et il n\'en resta pas deux ensemble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Ensuite le peuple dit à Samuel: Qui sont ceux qui ont dit: Saül régnerait-il sur nous? Livrez ces gens pour que nous les fassions mourir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Mais Saül dit: Personne ne sera mis à mort en ce jour, car aujourd\'hui l\'Éternel a opéré une délivrance en Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Et Samuel dit au peuple: Venez et allons à Guilgal pour l\'inauguration de la royauté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Alors tout le peuple se rendit à Guilgal et y déféra la royauté à Saül devant l\'Éternel, à Guilgal, et y offrit des sacrifices pacifiques à l\'Éternel. Et Saül et tous les hommes d\'Israël y firent de grandes réjouissances.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Et Samuel dit à tout Israël: Voici, j\'ai écouté votre voix dans tout ce que vous m\'avez exprimé, et j\'ai établi sur vous un roi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'et désormais, voici, c\'est le roi qui marchera à votre tête. Pour moi je suis vieux et j\'ai blanchi, et mes fils sont parmi vous, et j\'ai marché à votre tête depuis ma jeunesse jusqu\'à ce jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Me voici! témoignez contre moi en la présence de l\'Éternel et de son Oint! De qui ai-je pris le bœuf, et de qui ai-je pris l\'âne? et sur qui ai-je exercé des violences et sur qui des vexations? et de qui ai-je accepté des présents pour fermer les yeux en sa faveur? Je suis prêt à vous faire restitution.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Et ils dirent: Tu n\'as exercé sur nous ni violences ni vexations, et tu n\'as reçu quoi que ce soit des mains de personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Et il leur dit: Que l\'Éternel et son Oint soient aujourd\'hui témoins contre vous que vous n\'avez rien trouvé dans mes mains. Et le peuple répondit: Qu\'ils soient témoins!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Et Samuel dit au peuple: [J\'en atteste] l\'Éternel qui a fait Moïse et Aaron, et qui a retiré vos pères du pays d\'Egypte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Et maintenant présentez-vous, afin que je vous fasse le procès devant l\'Éternel sur tous les bienfaits que l\'Éternel vous a accordés, à vous et à vos pères!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Lorsque Jacob vint en Egypte, et que vos pères crièrent vers l\'Éternel, l\'Éternel envoya Moïse et Aaron qui retirèrent vos pères de l\'Egypte et vous établirent dans ce lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Mais ils oublièrent l\'Éternel, leur Dieu, et Il les vendit entre les mains de Sisera, chef d\'armée de Hatsor, et entre les mains des Philistins et entre les mains du roi de Moab, qui leur firent la guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Alors ils crièrent vers l\'Éternel et dirent: Nous avons péché en abandonnant l\'Éternel et en servant les Baals et les Astartés; mais maintenant sauve-nous des mains de nos ennemis et nous te servirons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Alors l\'Éternel envoya Jérubbaal, et Bedan, et Jephthé et Samuel, et Il vous arracha des mains de vos ennemis d\'alentour pour vous faire vivre en sécurité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Cependant, lorsque vous vîtes Nahas, roi des Ammonites, s\'avancer contre vous, vous me dites: Non! car c\'est un roi qu\'il nous faut pour nous régir, et pourtant l\'Éternel, votre Dieu, était votre Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Eh bien! voilà le roi que vous avez préféré, demandé! voici, l\'Éternel a établi un roi sur vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Si vous craignez l\'Éternel et Le servez, et si vous écoutez sa voix et ne vous rebellez pas contre les ordres de l\'Éternel, et si, et vous et votre roi qui règne sur vous, vous suivez l\'Éternel, votre Dieu...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Mais si vous n\'écoutez pas la voix de l\'Éternel, et si vous êtes rebelles aux ordres de l\'Éternel, la main de l\'Éternel se tournera contre vous comme contre vos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'En cet instant restez encore en place, et voyez la grande chose que l\'Éternel va opérer devant vos yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'N\'est-ce pas l\'époque de la moisson des orges? En ce jour j\'invoquerai l\'Éternel, et Il fera tonner et pleuvoir; ensuite sentez et voyez que vous avez fait un grand mal aux yeux de l\'Éternel en demandant pour vous un roi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Et Samuel invoqua l\'Éternel, et l\'Éternel fit tonner et pleuvoir le jour même. Et tout le peuple eut une grande crainte de l\'Éternel et de Samuel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Et tout le peuple dit à Samuel: Intercède en faveur de tes serviteurs auprès de l\'Éternel, ton Dieu, pour que nous ne mourions pas! Car à tous nos péchés nous avons ajouté la faute de demander pour nous un roi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Et Samuel dit au peuple: N\'ayez pas peur! vous avez fait tout ce mal-là! Seulement ne vous détournez pas de l\'Éternel et servez l\'Éternel de tout votre cœur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'ne vous détournez pas pour vous attacher au néant qui ne profite ni ne sauve! car elles [les idoles] sont un néant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Car l\'Éternel ne délaissera pas son peuple, en vertu de son grand Nom, car l\'Éternel veut faire de vous son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Loin de moi aussi la pensée de pécher contre l\'Éternel en cessant d\'intercéder pour vous! je veux vous montrer la bonne et droite voie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Seulement craignez l\'Éternel et servez-Le véritablement de tout votre cœur; car voyez comme Il est magnifique pour vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Mais si vous faites le mal, c\'en est fait de vous et de votre roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'A son avènement Saül était âgé de... et il régna deux ans sur Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Et Saül se fit une élite de trois milles hommes d\'Israël, et Saül en avait avec lui deux mille à Michmas et sur le mont de Béthel, et Jonathan en avait mille avec lui à Gibea de Benjamin, et il renvoya tout le reste de la troupe dans ses tentes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Et Jonathan battit le poste des Philistins à Geba: les Philistins l\'apprirent. Et Saül fit sonner de la trompette dans tout le pays pour dire: Que les Hébreux entendent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Et tous les Israélites entendirent qu\'on disait: Saül a battu le poste des Philistins, et aussi Israël est en mauvaise odeur auprès des Philistins. Et le peuple fut cité à se mettre à la suite de Saül à Guilgal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Cependant les Philistins se rassemblèrent pour entrer en guerre avec Israël, avec mille chars et six mille hommes de cavalerie et une infanterie égale au sable qui est sur le bord de la mer; et ils s\'avancèrent et campèrent à Michmas à l\'orient de Beth-Aven.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Et les Israélites se voyant serrés de près par la troupe qui approchait, se cachèrent dans les cavernes et dans les buissons et dans les gorges et dans les tours et dans les citernes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Et des Hébreux passant le Jourdain gagnèrent la contrée de Gad et de Galaad. Or Saül était encore à Guilgal, et tout le peuple tremblait derrière lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Et il attendit sept jours jusqu\'au terme fixé par Samuel; mais Samuel n\'arrivant pas à Guilgal, la troupe se débanda et le quittait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Alors Saül dit: Amenez-moi l\'holocauste et les oblations pacifiques! Et il offrit l\'holocauste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Et comme il avait achevé le sacrifice de l\'holocauste, voilà que Samuel arriva, et Saül sortit au-devant de lui pour le saluer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Et Samuel dit: Qu\'as-tu fait? Et Saül dit: Voyant que la troupe se débandait et me quittait, et que tu ne venais pas au terme fixé, et que les Philistins étaient réunis à Michmas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'j\'ai dit: Les Philistins vont faire une descente sur moi à Guilgal, et je ne me suis pas encore rendu l\'Éternel favorable; et j\'ai pris sur moi d\'offrir l\'holocauste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Alors Samuel dit à Saül: Tu as agi follement; tu n\'as pas observé l\'ordre de l\'Éternel, ton Dieu, tel qu\'Il te l\'avait prescrit; car maintenant l\'Éternel aurait confirmé ta royauté sur Israël pour l\'éternité; mais maintenant ta royauté ne subsistera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'L\'Éternel s\'est cherché un homme selon son cœur et l\'Éternel l\'a constitué prince de son peuple, parce que tu n\'as pas observé ce que l\'Éternel t\'avait commandé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Là-dessus Samuel se leva, et de Guilgal monta à Gibea de Benjamin. Saül fit passer à la revue la troupe qui se trouvait avec lui et était d\'environ six cents hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Or Saül et et Jonathan, son fils, avec la troupe qui se trouvaient avec eux, avaient pris position à Gibea de Benjamin, et les Philistins campaient à Michmas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Et les fourrageurs sortirent du camp des Philistins en trois corps, dont le premier se porta sur la route d\'Ophra dans la contrée de Sual;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'et l\'autre corps se porta sur la route de Bethoron, et le troisième sur la route de la frontière en saillie au-dessus de la vallée de Tesboïm du côté du désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Cependant il ne se serait pas trouvé de forgeron dans tout le pays d\'Israël, car les Philistins avaient dit: Il ne faut pas que les Hébreux se fabriquent ni épée ni javelot;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'et tous les Israélites descendaient chez les Philistins pour aiguiser chacun sa charrue, et son hoyau et sa bêche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'quand le tranchant des bêches et des hoyaux et des tridents et des haches était ébréché, et pour redresser les aiguillons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Et quand vint le jour du combat, il ne se trouvait ni épée ni javelot entre les mains de toute la troupe qui était avec Saül et Jonathan; il ne s\'en trouvait que chez Saül et Jonathan, son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Et un détachement de Philistins se porta au Pas-de-Michmas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Et un jour, Jonathan, fils de Saül, dit à son écuyer: Viens et allons attaquer le poste des Philistins qui est là vis-à-vis! mais il ne mit point son père dans la confidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Or Saül se tenait à l\'extrémité de Gibea, sous le grenadier de Migron, et la troupe qu\'il avait avec lui, d\'environ six cents hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Et Ahija, fils d\'Ahitub frère de Icabod, fils de Phinées, fils d\'Eli, Prêtre de l\'Éternel à Silo, portait l\'éphod. Et la troupe ignorait le départ de Jonathan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Et au milieu des passages que Jonathan cherchait à franchir pour atteindre le poste des Philistins, il y avait un pic d\'un côté et un pic de l\'autre côté; et le nom de l\'un est Botsets, et celui de l\'autre Séneh.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'L\'un de ces pics forme une colonne au nord vis-à-vis de Michmas et l\'autre est au midi vis-à-vis de Geba (Gibea).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Et Jonathan dit à son écuyer: Viens et allons attaquer le poste de ces incirconcis-là: peut-être l\'Éternel agira-t-Il pour nous; car pour vaincre, l\'Éternel n\'est pas arrêté par le nombre, grand ou petit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Et son écuyer lui dit: Exécute tout ce que tu as dans le cœur; suis ton mouvement; me voici avec toi partageant ton sentiment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Et Jonathan dit: Voici! nous marchons contre ces gens et nous allons nous découvrir à eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'S\'ils nous disent: Faites halte jusqu\'à ce que nous vous joignions! nous resterons en place, et ne marcherons point contre eux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'mais s\'ils disent: Montez à nous! nous monterons, car l\'Éternel les livre à nos mains; ce sera le signe que nous aurons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Puis ils se découvrirent les deux au poste des Philistins, et les Philistins dirent: Voilà que les Hébreux sortent des trous où ils se sont cachés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Et les hommes du poste crièrent à Jonathan et à son écuyer: Montez à nous! nous avons quelque chose à vous notifier! Alors Jonathan dit à son écuyer: En avant! suis-moi car l\'Éternel les livre aux mains d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Et Jonathan se mit à gravir avec les pieds et les mains, et son écuyer le suivait. Les Philistins tombèrent devant Jonathan, et son écuyer tuait après lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Et du premier coup porté par Jonathan et son écuyer ils tuèrent environ vingt hommes sur un espace d\'environ un demi sillon d\'un arpent de champ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Et l\'épouvante se mit dans le camp, dans la campagne et dans tout le peuple; le poste et les fourrageurs furent de même pris par la peur; tout le pays était en émoi; c\'étaient les terreurs de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Alors les sentinelles de Saül à Gibea de Benjamin regardèrent, et voilà que la multitude s\'écoulait et se répandait çà et là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Et Saül dit à la troupe qui était avec lui: Comptez donc et voyez qui a quitté nos rangs. Et ils comptèrent, et voilà que Jonathan et son écuyer n\'étaient pas présents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Alors Saül dit à Ahija: Fais approcher l\'Arche de Dieu! (Car en cette journée l\'Arche de Dieu accompagnait les enfants d\'Israël).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Et tandis que Saül parlait au Prêtre, le tumulte dans le camp des Philistins allait toujours croissant; alors Saül dit au Prêtre: Ramène ta main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Et Saül et toute la troupe qui était avec lui, se réunirent et ils s\'avancèrent jusqu\'à la mêlée, et voici, les Philistins tournaient leurs épées les uns contre les autres; c\'était un désordre immense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Et les esclaves qui depuis longtemps étaient aux Philistins, et qui étaient venus avec eux au camp, firent volte-face eux aussi pour passer du côté des Israélites qui étaient avec Saül et Jonathan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Et tous les Israélites cachés dans les montagnes d\'Ephraïm, vinrent aussi, à la nouvelle de la fuite des Philistins se mettre à la poursuite de ceux-ci avec les combattants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'C\'est ainsi que dans cette journée l\'Éternel délivra Israël, et la charge se prolongea jusqu\'au-delà de Beth-Aven.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Et en ce jour-là les hommes d\'Israël avaient étaient harassés; et Saül avait assermenté le peuple en disant: Maudit soit l\'homme qui mangera jusqu\'à la soirée, avant que j\'aie tiré vengeance de mes ennemis. Et aucun homme de la troupe ne goûta de la nourriture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Et tout le monde vint dans la forêt, et il y avait du miel sur la campagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Toute la troupe donc arriva dans la forêt et voilà que le miel suintait; mais personne ne porta sa main à sa bouche car le peuple respectait le serment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Or Jonathan n\'avait pas entendu son père intimer le serment au peuple et il présenta le bout du bâton qu\'il avait à la main, et le plongea dans un buisson à miel, et il ramena sa main à sa bouche et sa vue s\'éclaircit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Alors un homme de la troupe prit la parole et dit: Ton père a lié le peuple par un serment en disant: Maudit soit l\'homme qui prendra de la nourriture aujourd\'hui. Et la troupe était harassée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Et Jonathan dit: Mon père trouble le pays: voyez donc comme j\'ai la vue claire pour avoir goûté un peu de ce miel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Eh bien! si seulement la troupe aujourd\'hui se fût bien nourrie des prises faites à l\'ennemi! Car maintenant la défaite des Philistins n\'a pas été si grande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Et en ce jour ils battirent les Philistins de Michmas à Ajalon, et la troupe était très épuisée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Et le peuple se jeta sur le butin, et ils prirent des brebis et des bœufs et des veaux, et ils les égorgèrent sur le sol et le peuple mangea [de la chair] avec du sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Et l\'on fit rapport à Saül en ces termes: Voilà que le peuple pèche contre l\'Éternel en mangeant [la chair] avec le sang. Et il dit: Vous êtes infidèles! Roulez de suite vers moi une grande pierre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Et Saul dit: Répandez-vous parmi le peuple et dites-leur: Amenez-moi chacun son bœuf, et chacun sa brebis et l\'égorgez ici et mangez, et ne péchez point contre l\'Éternel en mangeant [la chair] avec le sang. Et tout le monde amena chacun son bœuf, de nuit, pour l\'égorger là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Et Saül éleva là un autel à l\'Éternel. Cet autel fut le premier qu\'il éleva à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Et Saül dit: Faisons une descente nocturne sur les Philistins, et pillons-les jusqu\'à l\'aube du matin, et ne leur laissons pas un homme. Et ils dirent: Exécute tout ce que tu jugeras bon! Et le Prêtre dit: Approchons-nous ici de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Et Saül consulta Dieu: Ferai-je une descente sur les Philistins? les livreras-tu aux mains d\'Israël? Mais Il ne lui donna point de réponse le jour même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Alors Saül dit: Avancez ici vous tous les chefs du peuple! Examinez et voyez en qui se trouve ce péché aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Car, par la vie de l\'Éternel qui a fait triompher Israël! quand il pèserait sur Jonathan, mon fils, il faut qu\'il meure! Et dans tout le peuple personne ne lui répondit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Et il dit à tout Israël: Soyez d\'un côté, et moi et Jonathan, mon fils, nous serons de l\'autre. Et tout le peuple dit à Saül: Fais ce qui te semblera bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Et Saül dit à l\'Éternel: Dieu d\'Israël, manifeste la vérité. Alors Saül et Jonathan furent désignés et le peuple laissé en dehors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Et Saül dit: Tirez au sort entre moi et Jonathan, mon fils. Alors Jonathan fut désigné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Et Saül dit à Jonathan: Confesse-moi ce que tu as fait. Et Jonathan le lui confessa et dit: Avec le bout du bâton que j\'avais à la main, j\'ai goûté un peu de miel: eh bien! je mourrai!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Alors Saül dit: Que Dieu m\'inflige ceci, et plus encore! il faut que tu meures, Jonathan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Mais le peuple dit à Saül: Jonathan mourrait, lui qui a exécuté cette grande délivrance en Israël! Non, non, par la vie de l\'Éternel, s\'il tombe à terre un seul des cheveux de sa tête! car en cette journée, c\'est avec Dieu qu\'il a agi. Ainsi, le peuple sauva Jonathan, et il ne mourut pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Et Saül revint de la poursuite des Philistins, et il regagnèrent leur pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Or Saül, ayant reçu la royauté sur Israël, porta la guerre de toutes parts contre tous ses ennemis. Contre Moab et contre les Ammonites et contre Edom et contre les rois de Tsoba et contre les Philistins; et quoi qu\'il entreprit, il était victorieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Et il montra de la bravoure, et il battit Amalek et sauva Israël des mains de ses spoliateurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Et les fils de Saül étaient: Jonathan et Jisvi et Malkisua. Et ses deux filles se nommaient, l\'aînée Merab et la cadette, Michal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Et le nom de la femme de Saül était Ahinoam, fille d\'Ahimaats. Et le nom de son chef d\'armée était Abner, fils de Ner, oncle de Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Car Kis, père de Saül, et Ner, père d\'Abner, étaient fils d\'Abiel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Et la guerre fut véhémente contre les Philistins, durant toute la vie de Saül; et Saül apercevait-il quelque homme capable et quelque brave, il se l\'attachait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Et Samuel dit à Saül: C\'est à moi que l\'Éternel a donné la mission de t\'oindre pour t\'établir roi sur son peuple, sur Israël: écoute donc l\'énoncé des paroles de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Ainsi parle l\'Éternel des armées: Je veux punir ce qu\'ont fait les Amalécites à Israël en se mettant sur son chemin lorsqu\'il sortait de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Dès lors, marche et défais les Amalécites et dévoue tout ce qui est à eux, sans pitié pour eux, et fais mourir hommes et femmes, et l\'enfant et le nourrisson, et le bœuf et la brebis, et le chameau et l\'âne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Et Saül adressa l\'appel au peuple, et le fit passer à la revue à Telaïm où il compta deux cent mille hommes d\'infanterie, et dix mille hommes de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Et Saül s\'avança jusqu\'à la ville d\'Amalek et dressa une embuscade dans la vallée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Et Saül dit aux Kénites: Allez, faites votre retraite, descendez et sortez du milieu des Amalécites, afin que je ne vous emporte pas avec eux. Car vous avez montré de l\'amitié à tous les Israélites lorsqu\'ils venaient de l\'Egypte. Et les Kénites se retirèrent du milieu des Amalécites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Et Saül battit Amalek de Havila à Sour qui est au devant de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Et il prit vivant Agag, roi d\'Amalek; et il exécuta l\'anathème sur tout le peuple au fil de l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Mais Saül et le peuple épargnèrent Agag et les meilleures pièces du menu et du gros bétail, et celles de seconde qualité, et les agneaux, et tout ce qui était bon; et ils ne voulurent pas le dévouer; mais tout ce qui était vil et détérioré, ils le dévouèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Alors la parole de l\'Éternel fut adressée à Samuel en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Je me repens d\'avoir fait Saül roi, car il s\'est détourné de moi, et n\'a point mis à effet mes paroles. Et Samuel fut irrité, et toute la nuit il éleva des cris vers l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Et Samuel se leva pour rencontrer Saül le matin. Et Samuel reçut cet avis: Saül est venu au Carmel, et voilà qu\'il s\'érige un monument, et il s\'en retourne et passe pour descendre à Guilgal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Et lorsque Samuel arriva près de Saül, Saül lui dit: Sois béni de l\'Éternel, car j\'ai mis à effet la parole de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Et Samuel dit: Mais qu\'est-ce que ce que ces bêlements de brebis, qui arrivent à mes oreilles, et ces mugissements de bœufs que j\'entends?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Et Saül dit: ils ont été amenés d\'Amalek parce que le peuple a épargné les meilleures pièces du menu et du gros bétail, pour les offrir à l\'Éternel, ton Dieu; mais le reste, nous l\'avons dévoué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Et Samuel dit à Saül: Arrête pour que je te déclare ce que l\'Éternel m\'a dit cette nuit. Et il lui dit: Parle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Et Samuel dit: Est-ce que, lors même que tu étais petit à tes propres yeux, tu n\'es pas devenu le chef des Tribus d\'Israël et par l\'onction de l\'Éternel ne t\'a-t-Il pas créé roi d\'Israël?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Et l\'Éternel t\'avait donné la mission de marcher, et Il t\'avait dit: Va et mets sous l\'anathème les pécheurs, les Amalécites, et leur fais la guerre jusqu\'à ce que tu les aies extermines;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'or, pourquoi n\'as-tu pas écouté la voix de l\'Éternel, et t\'es-tu jeté sur le butin, et as-tu fait ce qui est mal aux yeux de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Et Saül dit à Samuel: J\'ai écouté la voix de l\'Éternel et suivi la route par laquelle Il m\'envoyait; et j\'ai amené Agag, roi d\'Amalek et exécuté l\'anathème sur les Amalécites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Mais le peuple a pris sur le butin des brebis et des bœufs, prémices de l\'anathème, pour les sacrifier à l\'Éternel ton Dieu, à Guilgal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Et Samuel dit: L\'Éternel prend-Il plaisir aux holocaustes et aux victimes comme à l\'obéissance rendue à l\'Éternel? Voici, l\'obéissance est plus qu\'une belle victime, l\'attention plus que la graisse des béliers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Car la rébellion équivaut au péché de divination, et la révolte au crime d\'idolâtrie. Puisque tu as rejeté la parole de l\'Éternel, l\'Éternel t\'a rejeté pour t\'ôter la royauté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Et Saül dit à Samuel: J\'ai péché en transgressant l\'ordre de l\'Éternel et tes instructions, car j\'ai eu peur du peuple et j\'ai écouté sa voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Et maintenant pardonne mon péché, et reviens avec moi, afin que j\'adore l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Et Samuel dit à Saül: Je ne retournerai point avec toi! Puisque tu as répudié la parole de l\'Éternel, l\'Éternel t\'a aussi répudié pour que tu ne règnes plus sur Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Puis Samuel se tourna pour s\'en aller; mais Saül le saisit par la houppe de son manteau, qui fut arrachée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Alors Samuel lui dit: Aujourd\'hui l\'Éternel t\'arrache la royauté d\'Israël, et Il la donne à un autre, meilleur que toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Aussi bien Celui en qui Israël place sa confiance ne ment point et ne se repent point; car Il n\'est pas homme, pour se repentir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Et [Saül] dit: J\'ai péché! toutefois honore-moi devant les Anciens de mon peuple et devant Israël et reviens avec moi, afin que je rende mes adorations à l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Alors Samuel retourna à la suite de Saül, et Saül rendit ses adorations à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Et Samuel dit: Amenez-moi Agag, roi d\'Amalek. Et Agag l\'aborda gaiement, et Agag dit: Certes, la mort a perdu son amertume.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Et Samuel dit: De même que ton épée a privé des femmes [de leurs enfants], de même entre les femmes ta mère restera sans enfants. Et Samuel coupa Agag en pièces devant l\'Éternel à Guilgal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Ensuite Samuel partit pour Rama, et Saül retourna dans sa maison à Gibea de Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Samuel ne visita plus Saül jusqu\'au jour de sa mort; car Samuel était dans le deuil à cause de Saül, et l\'Éternel se repentait d\'avoir fait Saül roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Et l\'Éternel dit à Samuel: Jusques à quand t\'attristeras-tu pour Saül, puisque moi je l\'ai rejeté? il est déchu de la royauté d\'Israël. Remplis ta corne d\'huile et pars! je t\'envoie chez Isaï de Bethléhem; car j\'ai remarqué parmi ses fils un roi pour moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Et Samuel dit: Comment irais-je! Si Saül l\'apprend, il me fera mourir. Et l\'Éternel dit: Prends avec toi une génisse et dis: Je viens offrir un sacrifice à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Et convie Isaï au sacrifice, et moi je t\'indiquerai ce que tu auras à faire, et tu oindras pour moi celui que je te dirai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Et Samuel fit ce que prescrivait l\'Éternel et vint à Bethléem. Alors les Anciens de la ville accoururent inquiets au-devant lui et dirent: Ta venue est-elle un signe de paix?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Et il dit: De paix! C\'est pour offrir un sacrifice à l\'Éternel que j\'arrive. Mettez-vous en état de sainteté et venez avec moi au sacrifice. Et il mit en état de sainteté Isaï et ses fils et les convia au sacrifice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Et lorsqu\'ils parurent, il aperçut Eliab et se dit: Certes voilà devant l\'Éternel son Oint!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Mais l\'Éternel dit à Samuel: Ne considère pas sa figure et la hauteur de sa taille, car je l\'ai rejeté; car [je ne considère] pas ce que l\'homme considère; car l\'homme considère l\'aspect, mais l\'Éternel considère le cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Alors Isaï appela Abinadab et le fit passer devant Samuel. Et il dit: De celui-ci l\'Éternel n\'a pas fait choix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Alors Isaï fit passer Samma. Et il dit: De celui-ci aussi l\'Éternel n\'a pas fait choix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Et Isaï fit ainsi passer sept de ses fils devant Samuel. Et Samuel dit à Isaï: L\'Éternel n\'a pas fait choix de ceux-ci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Puis Samuel dit à Isaï: Sont-ce là tous tes enfants? Et il répondit il reste encore le cadet, et voici, il fait paître les brebis. Et Samuel dit: Envoie-le chercher! car nous ne prendrons pas place qu\'il ne soit ici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Isaï l\'envoya donc chercher. Or il était blond ayant aussi de beaux yeux et bonne mine. Et l\'Éternel dit: Lève-toi! oins-le; car c\'est lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Samuel prit la corne d\'huile et l\'oignit au milieu de ses frères. Et à partir de ce jour l\'Esprit de l\'Éternel descendit désormais sur David. Et Samuel se leva et partit pour Rama.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Cependant l\'Esprit de l\'Éternel se retira d\'avec Saül et de par l\'Éternel il subit les atteintes d\'un mauvais esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Et les serviteurs de Saül lui dirent: Te voilà assailli par un mauvais esprit de par Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Que notre Seigneur parle donc, et tes serviteurs présents chercheront un homme habile à jouer du luth, et lorsque tu sentiras les atteintes du mauvais esprit divin, de sa main il jouera, et tu te trouveras mieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Et Saül dit à ses serviteurs: Oui, cherchez un homme qui soit bon musicien et me l\'amenez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Et l\'un des servants prit la parole et dit: Voici, j\'ai vu un fils d\'Isaï de Bethléhem, habile musicien et très homme de bien, et guerrier et ayant le talent de bien dire et ayant une belle figure, et l\'Éternel est avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Alors Saül dépêcha des messagers à Isaï pour lui dire: Envoie-moi David, ton fils, qui est berger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Et Isaï prit un âne avec du pain et une outre de vin et un chevreau, qu\'il envoya par David, son fils, à Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'C\'est ainsi que David entra chez Saül, et il fut à son service, et il prit beaucoup d\'affection pour lui et il devint son écuyer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Et Saül envoya ce message à Isaï: Laisse donc David à mon service, car il a trouvé grâce à mes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Et lorsque l\'esprit de Dieu assaillait Saül, David prenait son luth et en jouait de sa main et Saül était soulagé et il se trouvait mieux, et le mauvais esprit s\'éloignait de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Et les Philistins rassemblèrent leurs armées pour faire la guerre, et ils se réunirent à Socho qui appartient à Juda, et ils campèrent entre Socho et Azeka vers Ephès-Dammim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Saül et les hommes d\'Israël se rassemblèrent et campèrent dans la Vallée des Térébinthes, et formèrent leur ordre de bataille contre les Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Or les Philistins s\'appuyaient à une montagne d\'un côté, et les Israélites s\'appuyaient à une montagne de l\'autre côté, et la vallée les séparait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Alors le champion duelliste sortit des rangs des Philistins; il se nommait Goliath, était de Gath et avait une taille de cinq coudées et un empan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Sa tête était couverte d\'un casque d\'airain et il portait une cotte de mailles, et cette cuirasse pesait cinq mille sicles d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Et il avait aux pieds des bottes d\'airain, et une pique d\'airain entre ses épaules.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Et la hampe de sa lance était comme l\'ensouple du tisserand, et la pointe de sa lance pesait six cent sicles de fer, et le porte-bouclier le précédait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Et s\'arrêtant il adressa aux lignes d\'Israël ces paroles? Pourquoi faites-vous une sortie pour vous ranger en bataille? Ne suis-je pas le Philistin, et vous les esclaves de Saül? Choisissez un homme qui descende contre moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'S\'il est de force à lutter avec moi et qu\'il me batte, nous vous serons asservis; mais si j\'ai le dessus et que je le batte, vous serez nos esclaves, et vous nous serez asservis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Et le Philistin dit: Aujourd\'hui j\'ai jeté un défi aux rangs d\'Israël! Donnez-moi un homme pour que nous nous mesurions ensemble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Et Saül et tous les Israélites entendirent ces discours du Philistin, et ils furent effrayés et saisis d\'une grande peur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'Or David était le fils de cet Ephratite de Bethléem de Juda, nommé Isaï qui avait huit fils; et cet homme au temps de Saül était vieux, avancé en âge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Et les trois fils aînés d\'Isaï avaient suivi Saül à la guerre; or les noms de ses trois fils qui marchaient comme soldats, étaient: Eliab, le premier-né, et Abinadab, son puîné, et Samma le troisième,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'et David était le cadet. Et lorsque les trois aînés eurent suivi Saül,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'David allait et revenait de chez Saül pour garder les troupeaux de son père à Bethléem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Cependant le Philistin s\'avançait matin et soir, et il se présenta durant quarante jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Et Isaï dit à David: Prends donc pour tes frères cet épha de grain rôti et ces dix pains, et cours les porter à tes frères au camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Et ces dix tranches de caillé porte-les aux chefs de mille, et visite tes frères pour voir comment ils se trouvent, et t\'informer de leurs désirs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'or Saül et eux et tous les Israélites sont dans la vallée des Térébinthes en guerre avec les Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Alors David se leva le matin, et laissant les troupeaux à un gardien, il prit son fardeau et partit comme Isaï le lui avait commandé, et il arriva à la circonvallation, et l\'armée qui se formait en ligne poussait le cri de guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Et les Israélites et les Philistins se rangèrent ligne contre ligne de bataille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Et David laissa les valises qu\'il portait aux soins du garde des bagages et courut à la ligne de bataille, et en arrivant il demanda à ses frères comment ils se trouvaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Et comme il parlait avec eux, voilà que le duelliste, le Philistin de Gath, nommé Goliath, sortit des rangs des Philistins et tint les mêmes discours, et David les entendit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Et à la vue de cet homme tous les Israélites s\'enfuirent devant lui, et eurent une grande peur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Et les Israélites disaient: Avez-vous vu cet homme qui s\'avance? C\'est pour jeter à Israël un défi qu\'il s\'avance. Et celui qui le vaincra, le Roi l\'enrichira d\'une grande opulence et il lui donnera sa fille et il affranchira la maison de son père en Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Et David s\'adressant aux hommes qui l\'accompagnaient, dit: Qu\'est-ce qui sera fait à celui qui vaincra ce Philistin-là et préservera Israël de l\'opprobre? En effet qui est ce Philistin, cet incirconcis, pour jeter un défi aux bataillons du Dieu Vivant?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Et le peuple lui tint le même langage et dit: Ainsi sera-t-il fait à l\'homme qui le vaincra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Et Eliab, son frère aîné, entendit son entretien avec ces hommes, et Eliab fut enflammé de colère contre David et dit: Pourquoi donc es-tu descendu ici, et à qui tu laissé ce peu de brebis dans le désert? Je connais ta présomption et la malice de ton cœur; car c\'est pour voir la bataille que tu es descendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Et David dit: Qu\'ai-je donc fait? Ce n\'est qu\'une parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Et David se détourna de lui et s\'adressant à un autre il parla dans les mêmes termes et le peuple lui fit la première réponse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Et les paroles prononcées par David furent entendues, puis rapportées devant Saül qui le fit chercher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Et David dit à Saül: Que le cœur ne défaille à personne à cause de lui! Ton serviteur ira et se mesurera avec ce Philistin-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Et Saül dit à David: Tu ne saurais affronter ce Philistin pour te mesurer avec lui, car tu es un enfant, et lui, il est homme de guerre dès sa jeunesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Et David dit à Saül: Ton serviteur faisait paître les brebis de son père, lorsque survinrent le lion et l\'ours qui enleva une pièce du troupeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'Et je me mis à sa poursuite et lui portai un coup et la lui arrachai de la gueule; et comme il se dressa contre moi, je le saisis par sa barbe et lui portai un coup et le tuai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Ainsi ton serviteur a abattu le lion et l\'ours, et le Philistin, cet incirconcis, aura le sort de l\'un ou de l\'autre, car il jette un défi aux bataillons du Dieu Vivant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Et David dit: L\'Éternel qui m\'a sauvé de la griffe du lion et de la griffe de l\'ours, Lui-même me sauvera aussi de la main de ce Philistin-là. Et Saül dit à David: Va, et que l\'Éternel soit avec toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Et Saül revêtit David de ses propres habits et lui mit sur la tête un casque d\'airain, et lui endossa la cuirasse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Et David ceignit son épée pardessus ses habits, et il se mit à marcher, car il n\'avait pas encore essayé. Alors David dit à Saül: Je ne saurais marcher avec cet équipement, car je ne l\'ai pas encore essayé. Et David s\'en débarrassa');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'et il prit dans sa main sa houlette et se choisit cinq cailloux polis dans la rivière et les mit dans sa gibecière de berger qui lui servait de valise, et, sa fronde à la main, il s\'avança contre le Philistin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Cependant le Philistin se rapprochait toujours plus près de David, précédé de l\'homme qui portait son bouclier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Et le Philistin ayant regardé et ayant vu David, il le méprisa; car c\'était un adolescent (or il était blond, avec une belle figure).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Et le Philistin dit à David: Suis-je un chien, que tu te présentes à moi avec des bâtons? Et le Philistin maudit David par le nom de son dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Et le Philistin dit à David: Viens à moi pour que je livre ta chair aux oiseaux du ciel et aux bêtes de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Et David dit au Philistin: Tu viens à moi avec épée, lance et javelot, mais moi, je viens à toi avec le Nom de l\'Éternel des armées, Dieu des lignes d\'Israël, que tu as défié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Aujourd\'hui l\'Éternel te livrera à mes mains, et je te terrasserai et te couperai la tête, et aujourd\'hui je livrerai les cadavres de l\'armée des Philistins aux oiseaux du ciel et aux bêtes de la terre, et toute la terre comprendra qu\'Israël a un Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'et toute cette assemblée comprendra que ce n\'est pas par l\'épée et le dard que l\'Éternel sauve; car c\'est ici la querelle de l\'Éternel et Il vous livre à nos mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Et quand le Philistin se leva et se mit en marche et s\'avança contre David, David se hâta et courut devant la ligne à la rencontre du Philistin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Et portant sa main à sa gibecière il en tira une pierre qu\'il lança avec la fronde, et il atteignit le Philistin au front et la pierre s\'enfonça dans son front, et il tomba le visage contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Ainsi David avec une fronde et une pierre l\'emporta sur le Philistin, à qui il porta ses coups et ôta la vie, sans avoir d\'épée à la main,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'et David accourut et se plaçant près du Philistin, il se saisit de son épée et la tira du fourreau et le tua, et lui trancha la tête. Et les Philistins voyant leur héros mort, prirent la fuite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Et les hommes d\'Israël et Juda s\'ébranlèrent et poussèrent un cri, et poursuivirent les Philistins jusqu\'à l\'ouverture de la vallée et jusqu\'aux portes d\'Ecron, et les Philistins frappés à mort, tombèrent dans le chemin de Saharaïm, et jusques à Gath et jusqu\'à Ecron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Et les enfants d\'Israël revenus après la chasse aux Philistins pillèrent leur camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Et David prit la tête du Philistin et la porta à Jérusalem, quant à son armure il la déposa dans sa tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Or lorsque Saül vit David s\'avancer à la rencontre du Philistin, il dit à Abner, général de l\'armée: De qui donc ce jeune homme est-il fils, Abner? Et Abner dit: Par ta vie, ô Roi je l\'ignore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Et le Roi dit: Eh bien! informe-toi de qui cet adolescent est fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Et lorsque David revint après avoir abattu le Philistin, Abner le prit et vint le présenter à Saül, tenant la tête du Philistin à la main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Et Saül lui dit: De qui es-tu le fils, jeune homme? Et David dit: Le fils de ton serviteur, Isaï de Bethléhem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Et lorsqu\'il eut achevé son entretien avec Saül, l\'âme de Jonathan s\'unit à l\'âme de David, et Jonathan l\'aima comme son âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Et en ce même jour Saül l\'attacha à sa personne et ne lui permit pas de retourner dans la maison de son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Et Jonathan se lia avec David par un pacte, car il l\'aimait comme son âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Et Jonathan ôta le manteau qu\'il portait et le donna à David avec son équipement jusqu\'à son épée, son arc et sa ceinture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Et David allait en course et réussissait partout ou Saul l\'envoyait, et Saül le préposait sur les gens de guerre et il était bien vu de tout le peuple et de même des serviteurs de Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Et comme ils faisaient leur entrée lors du retour de David après sa victoire sur le Philistin, les femmes sortirent de toutes les villes d\'Israël pour chanter et former des chœurs au-devant du Roi Saül avec des tambourins et des triangles, et dans l\'allégresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Et les femmes dansant chantaient tour à tour et disaient: Saül a abattu ses mille et David ses dix mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Et Saül en fut très irrité et mécontent de ce discours, et il dit: A David elles en donne dix mille, et à moi elles donnent les mille, il ne lui manque plus que la royauté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'A partir de ce jour et dorénavant Saül regarda David de mauvais œil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Et dès le lendemain Dieu fit sentir à Saül les atteintes d\'un esprit sinistre; et il se démenait dans sa maison; cependant ce jour-là comme les autres jours David de sa main jouait du luth, et Saül avait la pique en main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Et Saül brandissant sa pique dit: Je veux percer David et la paroi; mais David se mit deux fois hors de sa portée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Et Saül avait peur de David, car l\'Éternel était avec lui et s\'était éloigné de Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Et Saül l\'éloigna de lui et il l\'établit chef de mille hommes; et il allait en course, et rentrait à la tête du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Et David réussissait dans toutes ses expéditions, et l\'Éternel était avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Et Saül à la vue de ses grands succès avait peur de lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'mais tout Israël et Juda aimaient David parce qu\'il sortait et rentrait à leur tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Et Saül dit à David: Voici, je veux te donner pour femme Merab, ma fille aînée; seulement que j\'aie en toi un brave soldat, et soutiens les guerres de l\'Éternel. Or Saül se disait: Il faut qu\'il sente, non pas ma main, mais celle des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Et David dit à Saül: Qui suis-je et quelle existence ai-je et qu\'est la famille de mon père en Israël, pour devenir le gendre du Roi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Mais au moment où Merab, fille de Saül, devait être donnée à David, elle fut mariée à Adriel de Mehola.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Cependant Michal, fille de Saül, aimait David, et l\'on en informa Saül, à qui la chose agréa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Et Saül dit je veux la lui donner pour qu\'elle lui soit un piège et pour le mettre sous la main des Philistins. Et Saül dit à David pour la seconde fois: Tu deviendras mon gendre aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Et Saül donna cet ordre à ses serviteurs: Parlez secrètement à David en ces termes: Voici, le Roi a de l\'affection pour toi, et tous ses serviteurs t\'aiment; ainsi, deviens gendre du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Et les serviteurs de Saül répétèrent ces paroles aux oreilles de David. Et David dit: Est-ce peu de chose à vos yeux que de devenir le gendre du Roi, moi, homme pauvre et sans considération?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Et les serviteurs de Saül firent rapport et dirent: C\'est en ces termes que David a parlé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Et Saül dit: Parlez ainsi à David: Le Roi ne veut pas de dot, mais cent prépuces des Philistins pour tirer vengeance des ennemis du Roi. Or la pensée de Saül était de faire périr David par la main des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Et ses serviteurs transmirent à David ces paroles, et David agréa le projet de devenir gendre du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Et le temps n\'étant pas encore accompli, David se mit en mouvement, et marcha avec son monde et abattit parmi les Philistins deux cents hommes et il apporta leurs prépuces dont le nombre complet fut présenté au Roi, pour qu\'il pût être son gendre; et Saül lui donna sa fille Michal en mariage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Et Saül comprit que l\'Éternel était avec David; et Michal, fille de Saül, l\'aimait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Et la crainte que Saül avait de David, ne fit que s\'accroître, et Saül devint pour toujours hostile à David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Et lorsque les princes des Philistins se mettaient en campagne, à chacune de leurs campagnes David avait plus de succès que tous les serviteurs de Saül, et son nom était fort considéré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Et Saül parla à Jonathan, son fils, et à tous ses serviteurs de faire mourir David. Et Jonathan, fils de Saul, était très affectionné à David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Et Jonathan informa David en ces termes: Saül, mon père, cherche à te faire mourir; dès-lors sois dès le matin bien sur tes gardes, reste dans la retraite et cache-toi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'quant à moi, je sortirai et me tiendrai aux côtés de mon père dans la campagne où tu seras, et je parlerai de toi à mon père et te communiquerai tout ce que je pourrai découvrir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Et Jonathan parla en bien de David à Saül, son père, et lui dit: Que le Roi ne se rende pas coupable envers son serviteur, envers David, car il ne s\'est point rendu coupable envers toi; au contraire, ses actes te sont très avantageux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'et il a mis sa vie au jeu et il a défait le Philistin, et l\'Éternel a opéré une grande délivrance pour tout Israël. Tu l\'as vu et t\'en es réjoui. Et pourquoi te rendrais-tu coupable sur le sang innocent en faisant mourir David sans raison?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Et Saül écouta la voix de Jonathan et fit ce serment: Par la vie de l\'Éternel il ne sera pas mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Alors Jonathan appela David et il lui rapporta tous ces discours, et Jonathan ramena David à Saül, et il fut en sa présence sur le même pied que ci-devant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Et il y eut de nouveau guerre, et David se mit en campagne, et en vint aux mains avec les Philistins, et il leur fit essuyer une grande défaite, et ils fuirent devant lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Alors l\'Éternel mit Saül sous l\'influence d\'un esprit sinistre; or il restait dans sa maison et il avait sa pique en main,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'et David de sa main jouait du luth. Et Saül chercha à percer avec sa pique David d\'un coup qui l\'attachât à la paroi; mais David l\'esquiva, et la pique se planta dans la paroi, et David s\'enfuit et s\'échappa cette nuit même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Cependant Saül envoya des agents au logis de David pour le surveiller et le tuer au matin. Mais Michal, sa femme, lui donna cet avis: Si tu ne sauves pas ta vie cette nuit, demain tu reçois la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Puis Michal descendit David par la fenêtre, et s\'en allant il s\'enfuit et échappa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Et Michal prit le Theraphim et le mit dans le lit, et plaça la couverture de poil de chèvre à son chevet, et le recouvrit avec un tapis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Saül ayant donc envoyé les agents pour se saisir de David, elle dit: Il est malade.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Et Saül renvoya les agents pour voir David, en disant: Amenez-le moi dans son lit, pour que je le tue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Et les agents entrèrent; et voilà que c\'était le Theraphim qui était dans le lit, et la couverture de poil de chèvre à son chevet');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Alors Saül dit à Michal: Pourquoi m\'as-tu ainsi trompé et as-tu fait échapper mon ennemi? Et Mical dit à Saül: Il me disait: Laisse-moi partir, sinon, je te tue!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Or David s\'étant enfui et sauvé arriva chez Samuel à Rama, et il lui raconta tout ce que lui avait fait Saül. Et ils allèrent lui et Samuel habiter Naioth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Et l\'avis en fut donné à Saül en ces termes: Voici, David est à Naioth, près de Rama.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Et Saül envoya des agents pour arrêter David. Et à la vue du collège des prophètes qui prophétisaient sous la conduite de Samuel, les agents de Saül furent sous l\'action de l\'Esprit de Dieu, et ils prophétisèrent eux aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Et Saül en ayant été informé envoya d\'autres agents, et ceux-ci prophétisèrent aussi. Et Saul envoya encore de troisièmes agents, et ceux-ci prophétisèrent aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Alors il vint en personne à Rama; et arrivant à la grande citerne de Sechou, il interrogea en ces termes: Où sont Samuel et David? Et l\'on répondit: Voici, à Naioth près de Rama.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Et il s\'achemina de ce côté-là, vers Naioth près de Rama, et il fut lui-même sous l\'influence de l\'Esprit de Dieu, et il cheminait toujours prophétisant jusqu\'à son arrivée à Naioth près de Rama.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Et lui aussi ôta ses habits, lui aussi prophétisa devant Samuel et ainsi déshabillé il fut prosterné toute cette journée et toute la nuit. C\'est pourquoi on a coutume de dire: Saül est-il aussi entre les prophètes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Et David s\'enfuit de Naioth près Rama et il vint trouver Jonathan et dit: Qu\'ai-je fait et quel est mon crime et quel est mon péché contre ton père pour qu\'il attente à ma vie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Et [Jonathan] lui dit: A Dieu ne plaise! Tu ne mourras point. Voici, mon père ne fait rien? chose grande ou petite, sans me mettre en part; et pourquoi mon père se cacherait-il de moi en ceci? Il n\'en est rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Et David fit encore serment et dit: Ton père sait très bien que j\'ai trouvé grâce à tes yeux, et il aura dit: Il ne faut pas que Jonathan en soit instruit de peur qu\'il ne s\'afflige. Mais certainement, par la vie de l\'Éternel et par ta vie, il n\'y a qu\'un pas entre moi et la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Et Jonathan dit à David: Je ferai pour toi ce que ton âme dictera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Et David dit à Jonathan: Voici, demain, c\'est lune nouvelle, et j\'ai ma place à la table du Roi; mais laisse-moi libre et j\'irai me cacher dans la campagne jusqu\'à la troisième soirée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Si ton père remarquait mon absence, dis: David m\'a prié de lui permettre de faire une course à Bethléhem, sa cité, à l\'occasion d\'un sacrifice annuel qui s\'y fait pour toute la famille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'S\'il reprend ainsi: C\'est bon! il y a paix pour ton serviteur; mais s\'il se courrouce, sache que ma perte est arrêtée par devers lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Montre donc de l\'affection à ton serviteur, car tu as associé avec toi ton serviteur dans un contrat scellé devant l\'Éternel. Or, s\'il y a transgression de ma part, donne-moi la mort toi-même; pourquoi m\'adresserais-tu à ton père?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Et Jonathan dit: A Dieu ne plaise! Mais si j\'apprends de science certaine que ta perte résolue chez mon père doit t\'atteindre, ne t\'en informerai-je pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Et David dit à Jonathan: Qui m\'informerait dans le cas où ton père te ferait quelque réponse dure?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Et Jonathan dit à David: Viens et sortons dans la campagne. Et ils gagnèrent tous deux la campagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Et Jonathan dit à David: [Par] l\'Éternel, Dieu d\'Israël, si dans l\'espace de demain à après-demain je sonde mon père, et s\'il se montre bien disposé pour David, et que, le cas échéant, je ne te le mande pas et ne t\'en informe pas...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'que l\'Éternel fasse ceci à Jonathan et pis encore. Si je vois chez mon père une disposition sinistre à ton égard, je t\'en instruirai et te mettrai à même de partir de manière à t\'en aller sain et sauf. Et que l\'Éternel soit avec toi, comme il fut avec mon père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Et puisses-tu, si je dois vivre encore, puisses-tu en agir envers moi avec la bonté de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'et, si je viens à mourir, ne jamais retirer ta bienveillance de ma maison. Et si l\'Éternel fait disparaître de la face de la terre les ennemis de David jusqu\'au dernier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'que le nom de Jonathan ne disparaisse pas de la maison de David! Mais que l\'Éternel tire satisfaction des ennemis de David!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Et Jonathan réitéra son serment à David parce qu\'il l\'aimait; car il l\'aimait comme son âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Et Jonathan lui dit: Demain, c\'est lune nouvelle, et ton absence sera remarquée, car ton siège sera vacant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'après-demain donc hâte-toi de descendre et viens à l\'endroit où tu t\'es caché le jour de l\'attentat et tiens-toi vers la pierre Azel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Pour moi, je décocherai trois flèches dans cette direction pour tirer au but.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Et voici, j\'enverrai le valet en disant: « Va chercher les flèches! » Si je lui dis: « Voici, les flèches sont en deçà de toi, enlève-les! » viens, car tu es en sûreté, il n\'y a rien, par la vie de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Mais si j\'adresse au jeune homme ces paroles: « Voilà, les flèches sont en avant de toi », va t\'en, car l\'Éternel te fait partir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Et quant à la parole que nous avons prononcée toi et moi, que l\'Éternel reste entre toi et moi éternellement!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'David se cacha donc dans la campagne. Et c\'était nouvelle lune et le Roi vint se mettre à table pour prendre son repas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Et le Roi, cette fois comme les autres, prit place sur son siège, le siège adossé à la muraille; et Jonathan s\'étant levé, Abner prit place à côté de Saül et la place de David resta vide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Cependant ce jour-là Saül ne dit mot; car sa pensée était: il aura par aventure contracté quelque souillure; c\'est qu\'il n\'est pas en état de pureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Le lendemain de la nouvelle lune, le second jour, comme la place de David était encore vacante, Saül dit à Jonathan son fils: Pourquoi le fils d\'Isaï n\'a-t-il ni hier ni aujourd\'hui paru à table?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Et Jonathan répondit à Saül: David m\'a prié instamment de le laisser aller à Bethléhem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'et il m\'a dit: Donne-moi un congé car nous avons dans la ville un sacrifice de famille, et mon frère m\'a mandé; si donc j\'ai trouvé grâce à tes yeux, laisse-moi libre d\'aller afin que je voie mes frères; telle est la raison pour laquelle il ne paraît pas à la table du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Alors la colère de Saül s\'enflamma contre Jonathan et il lui dit: Fils d\'une perverse obstinée! ne connaissé-je pas la préférence que tu as pour le fils d\'Isaï, à ta honte et à la honte du ventre de ta mère?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Car tant que le fils d\'Isaï sera vivant sur la terre, il n\'y aura de position assurée ni pour toi ni pour ta souveraineté! Dépêche donc à l\'instant et fais qu\'on me l\'amène, car c\'est un enfant de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Et Jonathan répondit à Saül, son père, et lui dit: Pourquoi le mettre à mort? qu\'a-t-il fait?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Alors Saül lança contre lui sa pique pour le percer, et Jonathan comprit que c\'était parti arrêté chez son père que de faire mourir David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Et Jonathan se leva de table enflammé de colère, et le second jour de la nouvelle lune il ne mangea point, car il était chagriné au sujet de David parce que son père l\'avait outragé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Et dès le matin Jonathan alla dans la campagne au rendez-vous fixé avec David, ayant avec lui un petit valet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Et il dit à son valet: Cours, va chercher les flèches que je tire! Le valet courut et Jonathan tira la flèche de manière à le dépasser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Et lorsque le valet fut venu jusqu\'à la portée des flèches tirées par Jonathan, celui-ci lui cria par derrière: La flèche n\'est-elle pas en avant de toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Et Jonathan cria au valet par derrière: Fais diligence, hâte-toi, ne t\'arrête pas! Et le valet de Jonathan ramassa les flèches et revint vers sont maître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Or le valet ne se doutait de rien, Jonathan et David seuls savaient de quoi il s\'agissait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Et Jonathan remit ses armes à son valet et lui dit: Va et les porte en ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Le valet partit, et David sortit d\'auprès [le tas de pierres] qu\'il avait devant lui et se jeta la face contre terre et adora par trois fois, et ils se donnèrent l\'un à l\'autre le baiser, et ils pleurèrent ensemble, David jusqu\'au sanglot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Et Jonathan dit à David: Va en paix! Nous en resterons à ce que nous avons juré tous les deux par le Nom de l\'Éternel en disant que l\'Éternel soit éternellement entre moi et toi, entre ma race et la tienne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Et David vint à Nob, chez Ahimélech, le Prêtre; et Ahimélech accourut au devant de David et lui dit: Pourquoi es-tu seul, sans personne avec toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'Et David répondit au Prêtre Ahimélech: Le Roi m\'a chargé d\'une affaire et m\'a dit: Personne ne doit rien savoir de l\'affaire pour laquelle je te dépêche, non plus que des instructions que je t\'ai données. Et j\'ai marqué aux gens de ma suite un certain lieu pour rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Et maintenant ce que tu as sous la main, donne-le moi, cinq pains ou ce qui se trouvera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Et le Prêtre répondit à David et lui dit: Je n\'ai pas sous la main de pain ordinaire; il n\'y a que du pain sacré; si tes gens s\'étaient seulement abstenus de femmes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Et David répondit au Prêtre et lui dit: Ce qui est certain, c\'est que depuis nombre de jours tout accès auprès des femmes nous est fermé, et à mon départ mes gens avaient leurs personnes en état de sainteté, et l\'usage profane que nous voulons faire d\'une chose sacrée, sera aujourd\'hui sanctifié par l\'état de nos personnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Alors le Prêtre lui remit le pain sacré, car il n\'y avait là pas d\'autre pain que le pain de présentation, qu\'on avait enlevé de devant l\'Éternel pour substituer au moment même du pain chaud à celui qu\'on ôtait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, '[Or là se trouvait en ce jour un homme d\'entre les serviteurs de Saül, séquestré devant l\'Éternel; il se nommait Doëg, était Iduméen et grand-maître des bergers de Saül].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Et David dit à Ahimélech: N\'as-tu pas à ta portée une pique ou une épée? Car je n\'ai pris avec moi ni mon épée ni mon équipement, car la commission du Roi était pressante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Et le Prêtre dit: L\'épée de Goliath, le Philistin, que tu as fait tomber sous tes coups dans la vallée des Térébinthes, voici, est enveloppée dans une toile derrière l\'Ephod; si tu veux la prendre prends-là; car ici il n\'y en a pas d\'autre que celle-là. Et David dit: Elle n\'a pas sa pareille; donne-la moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Et David se remit en route, continuant le jour même à fuir devant Saül, et il arriva chez Achis, Roi de Gath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Et les serviteurs d\'Achis disaient de lui: N\'est-ce pas David, le Roi du pays? N\'est-ce pas à lui que dans les chœurs on chantait ces paroles: Saül a tué ses mille, et David ses dix mille!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Et ces discours firent impression sur le cœur de David, qui prit une grande peur d\'Achis, Roi de Gath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Et il contrefit l\'insensé devant eux, et il se démenait comme un furieux entre leurs mains, et il grattait les battants de la porte et laissait couler sa salive dans sa barbe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Alors Achis dit à ses serviteurs: Voici, vous voyez que cet homme est hors de sens; pourquoi me l\'amenez-vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Manqué-je de fous, que vous m\'amenez celui-ci pour m\'exposer à ses accès? Doit-il entrer dans ma maison?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Et David partit de là et se retira dans la caverne d\'Adullam. A cette nouvelle, ses frères et toute la maison de son père descendirent auprès de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Et autour de lui s\'attroupèrent tous ceux qui étaient dans la gêne et avaient des créanciers et la vie amère, et il devint leur chef, et il se trouva avoir environ quatre cents hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Et de là David se rendit à Mitspeh en Moabie, et il dit au Roi de Moab: Veuille permettre à mon père et à ma mère d\'émigrer chez toi jusqu\'à ce que je sache ce que Dieu me dispensera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Et il les amena au roi de Moab, avec lequel ils demeurèrent tout le temps que David passa dans le lieu fort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Et le prophète de Gad dit à David: Ne reste pas dans le lieu fort; pars et viens au pays de Juda. Et David partit et gagna la forêt de Hareth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Et Saül apprit qu\'on était renseigné sur David et ses compagnons. Or Saül siérait à Gibea sous le Tamarin sur la hauteur, ayant la pique à la main et entouré de tous ses serviteurs debout autour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Et Saül dit à ses serviteurs debout autour de lui: Ecoutez, enfants de Benjamin! Le fils d\'Isaï vous dotera-t-il bien tous de champs et de vignes, et fera-t-il de vous tous des chefs de mille hommes et des capitaines de cent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'que vous vous êtes ligués contre moi sans qu\'aucun m\'ait dénoncé le pacte de mon fils avec le fils d\'Isaï, sans qu\'aucun me montre de la sympathie et me révèle que mon fils aposte mon serviteur pour m\'épier comme il le fait aujourd\'hui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Alors Doëg, l\'Iduméen, qui se tenait à côté des serviteurs de Saül, répondit et dit: J\'ai vu le fils d\'Isaï venir à Nob chez Ahimélech,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'lequel a consulté pour lui l\'Éternel et lui a donné des vivres et remis l\'épée de Goliath le Philistin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Alors le Roi fit mander Ahimélech, fils d\'Ahitub, le Prêtre, et toute la maison de son père les Prêtres, qui étaient à Nob, et tous ils parurent devant le Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Et Saül dit: Ecoute donc, fils d\'Ahitub! Et il dit: Me voici mon Seigneur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Et Saül lui dit: Pourquoi vous êtes-vous ligués contre moi, toi et le fils d\'Isaï, car tu lui as donné du pain et une épée et pour lui tu as consulté Dieu, afin qu\'il se dresse contre moi en insidiateur jusqu\'aujourd\'hui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Et Ahimélech répondit au Roi et dit: Mais de tous tes serviteurs lequel a comme David la confiance du Roi, dont il est d\'ailleurs le gendre, et dont il a l\'oreille étant admis à son intimité et considéré dans ta maison?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Est-ce d\'aujourd\'hui que j\'ai commencé à consulter Dieu pour lui? Ce serait odieux à moi! Que le Roi n\'inculpe en rien ton serviteur, ni toute la maison de mon père; car ton serviteur en tout cela n\'a aucune complicité, ni petite ni grande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Mais le Roi dit à Ahimélech: Il faut que tu meures, Ahimélech, toi et toute la maison de ton père!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Et le Roi dit aux coureurs qui se trouvaient près de lui: Allez et mettez à mort les Prêtres de l\'Éternel, parce que eux aussi donnent la main à David, et parce que instruits de sa fuite ils ne me l\'ont pas dénoncée. Mais les serviteurs du Roi ne voulurent pas prêter leurs mains au massacre des Prêtres de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Alors le Roi dit à Doëg: Va, toi, et fais main basse sur les Prêtres. Et Doëg, l\'Iduméen, s\'avança et il massacra les Prêtres, et en ce jour-là il donna la mort à quatre-vingt-cinq hommes portant l\'éphod de lin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Et Nob, la ville sacerdotale, il la passa au fil de l\'épée; hommes, femmes, enfants, nourrissons, bœufs, ânes et moutons, tout fut passé au fil de l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Cependant il échappa un fils d\'Ahimélech, fils d\'Ahitub, il se nommait Abiathar, et il s\'enfuit à la suite de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Et Abiathar annonça à David que Saül avait fait mourir les Prêtres de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Et David dit à Abiathar: J\'ai compris ce jour-là même que, puisque Doëg, l\'Iduméen, était présent, il ne manquerait pas d\'informer Saül. C\'est moi qui ai occasionné la mort de toutes les personnes de la maison de ton père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Reste avec moi! Sois sans crainte! car qui attente à ma vie, attente à la tienne, près de moi tu es bien gardé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Et David reçut cet avis: Voilà que les Philistins ont attaqué Kéhila et ils pillent les aires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Aussitôt David consulta l\'Éternel en disant: Marcherai-je et porterai-je un coup à ces Philistins-là? Et l\'Éternel dit à David: Marche et défais ces Philistins et dégage Kéhila.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Mais les gens de David lui dirent: Voici, ici en Juda, nous sommes en crainte: ce seras bien pis, si nous marchons sur Kéhila contre les lignes des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Alors David de nouveau consulta l\'Éternel, et l\'Éternel lui fit cette réponse: En avant! fonds sur Kéhila, car je livre les Philistins à tes coups.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'David avec ses gens marcha sur Kéhila, et il en vint aux mains avec les Philistins, et il emmena leurs troupeaux, et les mit en grande déroute, et ainsi, David délivra les habitants de Kéhila. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Or quand Abiathar, fils d\'Ahimélech, fugitif suivit David à Kéhila, il descendit ayant en main l\'Ephod.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Et Saül eut avis de l\'arrivée de David à Kéhila et Saül dit: Dieu me le livre à discrétion, puisque par cette manière il s\'est enfermé dans une place qui a portes et verrous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Et Saül appela tout le peuple sous les armes pour opérer une descente sur Kéhila et cerner David et ses gens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Et David s\'étant aperçu que Saül machinait contre lui un mauvais coup, dit au Prêtre Abiathar: Apporte l\'Ephod!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Et David dit: Éternel, Dieu d\'Israël, ton serviteur apprend que Saül va tenter d\'entrer dans Kéhila pour ruiner cette ville à mon occasion;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'les maîtres de Kéhila me mettront-ils à sa merci? Saül fera-t-il la descente, comme l\'a ouï ton serviteur? Éternel, Dieu d\'Israël, daigne en instruire ton serviteur! Et l\'Éternel dit: Il la fera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Et David dit: Les maîtres de Kéhila me mettront-ils moi et mes gens à la merci de Saül? Et l\'Éternel dit: Ils t\'y mettront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Alors David se mit en mouvement avec sa troupe d\'environ six cents hommes, et ils évacuèrent Kéhila, puis se mirent à errer à l\'aventure. Et Saül informé que David s\'était retiré de Kéhila, cessa de tenir la campagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Et David resta dans le désert sur les hauteurs, et il stationna sur la montagne au désert de Ziph. Et Saül cherchait incessamment à l\'atteindre, mais Dieu ne le laissa pas tomber entre ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Et comme David voyait que Saül se mettait en campagne pour attenter à sa vie, et comme David était alors au désert de Ziph dans la Forêt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Jonathan, fils de Saül, s\'étant levé vint joindre David dans la Forêt et lui fit prendre courage en Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Et il lui dit: Sois sans crainte! tu ne seras pas atteint par la main de Saül, mon père, et c\'est toi qui régneras sur Israël, et moi j\'aurai le second rang après toi, et Saül, mon père, aussi le sait bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Et les deux ils solennisèrent un pacte devant l\'Éternel, et David demeura dans la Forêt, et Jonathan retourna chez lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Alors les Ziphites montèrent chez Saül à Gibea pour lui dire: Voilà que David s\'est caché chez nous sur les hauteurs dans la Forêt, sur la colline de Hachila qui est au midi du désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Eh bien donc, ô Roi, puisque tout le désir de ton cœur est de descendre, descends! à nous de le livrer aux mains du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Et Saül dit: Soyez les bénis de l\'Éternel pour l\'intérêt que vous prenez à moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Allez donc et vous tenez mieux prêts encore, étudiez, voyez le lieu où son pied s\'arrêtera et ceux qui l\'y ont aperçu, car il m\'a été dit qu\'il est très fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Et regardez et le dépistez dans tous les recoins où il va se cacher, puis revenez vers moi avec du certain et je partirai avec vous. Et dans le cas où il serait dans le pays, pour l\'avoir je fouillerai dans tous les milliers de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Là-dessus ils partirent et devancèrent Saül à Ziph. Cependant David et ses gens étaient au désert de Maon dans la plaine au midi du désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Et Saül et ses hommes se mirent en route à sa recherche. Mais on informa David, et il descendit le rocher et il se tint dans le désert de Maon. A cette nouvelle Saül poursuivit David au désert de Maon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Et Saul se porta sur l\'un des flancs de la montagne, tandis que David avec ses gens occupait l\'autre flanc de la montagne. Et comme David faisait diligence pour se placer hors de la portée de Saül, et que Saül et ses hommes cernaient David et les siens pour se saisir de lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'un messager vint à Saül avec cet avis viens en toute hâte, car les Philistins ont fait invasion dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Aussitôt Saül renonçant à poursuivre David marcha à la rencontre des Philistins. C\'est ce qui fit donner à ce lieu le nom de Sélah-Hammahelkoth (rocher des séparations).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, 'Et de là David s\'éleva et se porta sur les hauteurs d\'Enguedi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'Et comme Saül était revenu de son expédition contre les Philistins, il reçut cet avis: Voici, David est au désert de Enguedi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Alors Saül leva trois mille hommes d\'élite sur tout Israël et il se mit en marche pour chercher David et ses gens sur les rochers des bouquetins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Et il vint aux parcs des brebis qui sont sur la route; et là était une grotte, et Saül y entra pour se couvrir les pieds; cependant David et ses gens étaient assis au fond de la grotte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Alors les gens de David lui dirent: Voici, c\'est le jour où l\'Éternel te dit: Voici, Moi-même je mets ton ennemi entre tes mains: traite-le donc à ton gré. Et David se leva et coupa la frange du manteau de Saül à la dérobé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Mais il arriva tôt après que le cœur battit à David de ce qu\'il avait coupé la frange de Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Et il dit à ses gens: L\'Éternel me garde de faire une telle chose à mon Seigneur, à l\'Oint de l\'Éternel, que de porter la main sur lui; car il est l\'Oint de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Et David tança ses gens et ne leur permit pas d\'aller s\'attaquer à Saül. Cependant Saul, s\'étant levé, sortit de la grotte et continua son chemin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Sur ces entrefaites David se leva et sortit de la grotte, et s\'adressant par derrière à Saül il dit en s\'écriant: Mon Seigneur, le Roi! Alors Saül regarda en arrière, et David s\'inclina le visage contre terre et se prosterna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Et David dit à Saül: Pourquoi écoutes-tu les propos des gens qui disent: Voici, David, cherche ta ruine!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Voici, en ce jour même tu as vu de tes yeux qu\'aujourd\'hui où l\'Éternel t\'a mis entre mes mains dans la grotte et où l\'on me disait de te tuer, je t\'ai épargné et j\'ai dit: Je ne porterai point la main sur mon Seigneur, car c\'est l\'Oint de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Et, mon père, vois aussi, vois la frange de ton manteau dans ma main! Que si en coupant la frange de ton manteau je ne t\'ai pas ôté la vie, reconnais et vois que j\'ai la main nette de crime et de révolte et que je ne suis pas coupable envers toi; mais toi, tu guettes ma vie pour me la ravir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Que l\'Éternel juge entre moi et toi et me venge de toi! quant à moi, je ne mettrai pas la main sur toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Comme dit le proverbe des aïeux: « Du méchant procède le mal, » je ne mettrai donc pas la main sur toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Contre qui le Roi d\'Israël marche-t-il? qui poursuis-tu? Un chien mort, quelque puce!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Qu\'ainsi l\'Éternel soit arbitre et qu\'il juge entre moi et toi, et qu\'il voie et défende ma cause et me rende justice en me tirant de ta main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Et lorsque David eut achevé de parler en ces termes à Saül, Saül dit: Est-ce là ta voix, mon fils David? Et Saül donna l\'essor à sa voix et pleura.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Et il dit à David: Tu es plus juste que moi; car tu m\'as fait du bien, tandis que je t\'ai rendu le mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Et aujourd\'hui tu as mis en évidence le bien que tu m\'as fait, puisque l\'Éternel m\'ayant mis entre tes mains, tu ne m\'as pas ôté la vie. En effet, si quelqu\'un rencontre son ennemi, le laisse-t-il aller sain et sauf?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Que l\'Éternel donc te fasse du bien en retour de ce que tu as fait aujourd\'hui pour moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Or voici, je sais que tu deviendras Roi et que la Souveraineté d\'Israël subsistera en ta main;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'jure-moi donc par l\'Éternel que tu n\'extirperas pas ma souche après moi et que tu ne feras pas disparaître mon nom de la maison de mon père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Et David en fit le serment à Saül; et Saül reprit le chemin de sa maison et David et le siens gagnèrent la hauteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Et Samuel mourut, et il y eut assemblée de tout Israël, et l\'on célébra son deuil, et on lui donna la sépulture dans sa demeure à Rama. C\'est alors que David fit un mouvement et descendit au désert de Paran.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Or à Maon était un homme ayant des biens à faire valoir sur le Carmel, homme très considérable, et il possédait trois mille moutons et mille chèvres et il assistait à la tonte de ses troupeaux sur le Carmel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Or cet homme se nommait Nabal et sa femme, Abigaïl, et cette femme excellait par l\'intelligence et avait une belle figure; mais le mari était dur et méchant. Et c\'était un descendant de Caleb.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Et David apprit au désert que Nabal faisait la tonte de ses moutons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Et David dépêcha dix valets avec cette instruction: Montez au Carmel et présentez-vous chez Nabal et le saluez de ma part');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'et lui tenez ce langage: Pour la vie! salut à toi, et salut à toute ta maison et salut à tout ce qui tient à toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Maintenant, j\'apprends que tu as des tondeurs; or tes bergers ont été avec nous; nous ne les avons point molestés, et ils n\'ont éprouvé aucune perte quelconque pendant tout le temps de leur séjour au Carmel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, '– interroge-les, ils te renseigneront, – que donc mes valets trouvent grâce à tes yeux, car nous sommes venus pour un jour de fête; veuille donner ce qui se trouvera sous ta main, à tes serviteurs et à ton fils David!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Les valets de David vinrent donc et de la part de David ils tinrent à Nabal ce langage, puis ils attendirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Mais Nabal fit cette réponse aux serviteurs de David: Qui est David, et qui est le fils d\'Isaï? Aujourd hui il y a beaucoup de serviteurs qui rompent avec leurs maîtres!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Et faut-il que je prenne mon pain et mon eau et la chair des bêtes que j\'ai tuées pour mes tondeurs et que je les donne à des gens desquels je ne sais d\'où ils sont?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Et le valets de David rebroussant chemin s\'en retournèrent à leur arrivée ils lui firent un rapport exact du tout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Alors David dit à ses hommes: Ceignez chacun votre épée! Et ils ceignirent chacun son épée, et David ceignit aussi son épée, et ils se mirent en marche sous la conduite de David au nombre d\'environ quatre cents, et deux cents restèrent auprès des bagages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Cependant Abigaïl, femme de Nabal, fut informée par l\'un des valets, qui lui dit: Voilà que du désert David a envoyé des messagers pour saluer notre maître, mais celui-ci les a rebutés avec rudesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Et ces hommes ont beaucoup de bonté pour nous; et nous n\'avons point été molestés, et n\'avons éprouvé aucune perte quelconque pendant toute la saison où nous avons cheminé avec eux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'durant notre séjour aux champs ils ont été pour nous un rempart et la nuit et le jour tant que nous avons été à côté d\'eux occupés à faire paître nos troupeaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Maintenant examine et vois ce que tu as à faire, car la ruine de notre maître et de toute sa maison est résolue; car c\'est un méchant homme; on ne peut lui parler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Alors Abigaïl fit diligence, et elle prit deux cents pains et deux outres de vin et cinq moutons apprêtés et cinq mesures de grain rôti et cent gâteaux de raisins secs et deux cents bols de figues, qu\'elle chargea sur les ânes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'et elle dit à ses valets: Précédez-moi! je vous suivrai. Or elle ne mit point Nabal, son mari, au fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Et cheminant montée sur son âne, elle débouchait à une anfracture de la montagne, lorsque voilà qu\'elle fit la rencontre de David descendant avec ses hommes; et elle se trouva en face d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Or David avait dit: C\'est en pure perte que j\'ai surveillé tout ce que cet homme-là a dans le désert, et empêché que rien ne fût soustrait de ce qui lui appartient: il m\'a rendu le mal pour le bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Qu\'ainsi Dieu traite les ennemis de David, et plus mal encore, si jusqu\'au point du jour je laisse subsister rien de ce qui lui appartient, fut-ce l\'enfant qui pisse à la muraille!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Et à la vue de David, Abigaïl s\'empressa de descendre de l\'âne qu\'elle montait, et en face de David, elle inclina sa tête et se prosterna jusqu\'à terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'et, se jetant à ses pieds elle dit: A moi la faute, mon Seigneur! daigne permettre à ta servante de se faire entendre à tes oreilles, et écoute les explications de ta servante!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Veuille, mon Seigneur, ne pas t\'inquiéter de cet homme de rien, de Nabal; car il est ce que son nom indique: Nabal (fou) tel est son nom, et il y a chez lui folie; quant à moi, ta servante, je n\'ai point vu les valets de mon Seigneur, que tu as envoyés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Or, mon Seigneur, aussi vrai que l\'Éternel vit, et que tu vis toi-même, aussi vrai est-il que l\'Éternel t\'a empêché de devenir coupable de meurtre et de te venger de ta propre main. Ainsi, ils auront beau être comme Nabal, tes ennemis et ceux qui cherchent à nuire à mon Seigneur!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Accepte donc ce présent qu\'apporte à mon Seigneur ta servante, et le donne aux valets qui vont à la suite de mon Seigneur...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Ah! pardonne l\'offense de ta servante! Car l\'Éternel veut créer à mon Seigneur une maison stable, car mon Seigneur soutient les guerres de l\'Éternel, et le mal ne t\'atteindra pas durant ta vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Et si des hommes se lèvent pour te persécuter et attenter à ta vie, la vie de mon Seigneur sera serrée dans l\'écrin de la vie auprès de l\'Éternel, ton Dieu, tandis que la vie de tes ennemis sera agitée dans la paume de la fronde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Et lorsque l\'Éternel accomplira pour mon Seigneur toutes les excellentes promesses qu\'il t\'a faites, et qu\'il l\'ordonnera souverain d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'mon Seigneur n\'aura ni remords, ni embarras de conscience pour avoir versé gratuitement le sang et s\'être vengé lui-même. Mais lorsque mon Seigneur sera l\'objet des bienfaits de l\'Éternel, souviens-toi de ta servante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Et David dit à Abigaïl: Béni soit l\'Éternel, Dieu d\'Israël, qui m\'a fait faire aujourd\'hui ta rencontre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Et béni soit ton jugement! et bénie sois-tu pour m\'avoir empêché en ce jour de me rendre coupable de meurtre, et de me venger de ma propre main!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Sans cela, par la vie de l\'Éternel, Dieu d\'Israël, qui m\'a empêché de te faire du mal, si tu ne t\'étais empressée, et ne m\'avais prévenu, il ne resterait d\'ici au point du jour, rien de Nabal, fût-ce l\'enfant qui pisse à la muraille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Et David reçut de sa main ce qu\'elle lui présentait et il lui dit: Regagne en paix ta maison! Voici, j\'ai écouté ta voix, et eu égard à ta personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Et lorsque Abigaïl entra chez Nabal, voilà qu\'il avait un festin dans sa maison, comme le festin du Roi; et le cœur de Nabal était en belle humeur, et il s\'était enivré à l\'excès. Et jusqu\'au matin elle ne l\'informa d\'aucun détail, ni grand, ni petit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Et le matin l\'ivresse de Nabal s\'étant dissipée, sa femme lui raconta toutes ces choses et il en eut intérieurement la mort dans le cœur et il fut pétrifié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Et il se passa environ dix jours, et l\'Éternel frappa Nabal, qui mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Et à la nouvelle de la mort de Nabal, David dit: Béni soit l\'Éternel qui a tiré sur Nabal vengeance de mon outrage, et préservé du crime Son serviteur! – C\'est ainsi que l\'Éternel fit retomber la méchanceté de Nabal sur sa propre tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Et David, par une délégation, fit proposer à Abigaïl de l\'épouser. Et les serviteurs de David arrivèrent chez Abigaïl au Carmel, et lui transmirent le message en ces termes: David nous a délégués auprès de toi afin de te prendre pour être sa femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Alors Abigaïl se leva et s\'inclina la face contre terre et dit: Voici ta servante pour faire le service de laver les pieds des serviteurs de mon Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Et Abigaïl avec empressement se leva, et elle prit l\'âne pour monture avec cinq jeunes filles pour suivantes, et elle se mit en route à la suite des délégués de David, et elle devint sa femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'David épousa aussi Ahinoam de Jizréel, et l\'une et l\'autre elles furent ses femmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Cependant Saül maria Michal, sa fille, femme de David, à Palti, fils de Laïs, de Gallim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Et les Ziphites vinrent trouver Saül à Gibea et dirent: Voici David se tient caché sur la colline de Hachila à l\'Orient du désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Et Saül se mit en mesure et descendit au désert de Ziph accompagné de trois mille hommes de l\'élite d\'Israël pour aller à la recherche de David dans le désert de Ziph.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Et Saül campa près de la colline de Hachila qui est à l\'orient du désert sur la route, et David s\'était fixé au désert,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'et ayant découvert que Saül était à sa poursuite dans le désert, David envoya des éclaireurs, et il sut que l\'arrivée de Saül était positive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Aussitôt David se leva et vint à l\'endroit où Saül campait, et David observa le lieu où couchait Saül ainsi que Abner, fils de Ner, général de son armée; or Saül couchait au quartier des chars, et les troupes étaient campées à l\'entour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Et David prenant la parole s\'adressa à Ahimélech, le Héthien, et à Abisaï, fils de Tseruia, et frère de Joab, et il dit: Qui fait avec moi une descente jusqu\'à Saül dans son camp? Et Abisaï dit: C\'est moi qui la ferai avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'David et Abisaï pénétrèrent donc de nuit vers l\'armée, et voilà que Saül était couché endormi dans le quartier des chars, et sa pique était fichée en terre à son chevet et Abner et la troupe étaient couchés tout autour de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Et Abisaï dit à David: Aujourd\'hui Dieu a livré ton ennemi entre tes mains: et maintenant laisse-moi le percer avec la pique de part en part, jusqu\'au sol, du premier coup que je n\'aurai pas à lui réitérer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Mais David dit à Abisaï: Ne le détruis pas! car qui porterait la main sur l\'Oint de l\'Éternel impunément?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'David dit: Par la vie de l\'Éternel! Si l\'Éternel le frappe et que, ou bien son jour arrivé il meure, ou bien que descendu sur le champ de bataille il soit emporté, eh bien!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Que l\'Éternel me garde de porter la main sur Son Oint! Cependant prends la pique qui est à son chevet et l\'aiguière, et allons-nous-en!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'David emporta donc la pique et l\'aiguière que Saül avait à son chevet, et ils s\'en allèrent sans que personne s\'aperçût, se doutât de rien et fût réveillé; car tous ils étaient endormis parce qu\'un profond sommeil les accablait de par l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Et David passa de l\'autre côté, et se porta sur la cime d\'un mont à distance; grand était l\'espace qui les séparait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Et David cria à la troupe et à Abner, fils de Ner, et dit: Ne réponds-tu pas, Abner? Et Abner répondit et dit: Qui es-tu, toi qui assailles le Roi de tes clameurs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Et David dit à Abner: N\'es-tu pas homme? et qui est ton pareil en Israël? Pourquoi n\'as-tu pas veillé sur le Roi, ton maître? Car un homme du peuple s\'est introduit pour tuer le Roi, ton Maître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Tu n\'as pas fait là un bel acte, par la vie de l\'Éternel! Car vous êtes des enfants de la mort pour n\'avoir pas veillé sur votre Maître, l\'Oint de l\'Éternel Eh bien! vois donc où est la pique du Roi et l\'aiguière qui étaient à son chevet!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Alors Saül reconnut la voix de David et dit: Est-ce là ta voix, mon fils David! Et David dit: C\'est ma voix, ô Roi, mon Maître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Et il dit: Pourquoi donc mon Maître poursuit-il son serviteur; car qu\'ai-je fait? quel crime a laissé [sa tache] dans ma main?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Et maintenant daigne mon Seigneur le Roi écouter les paroles de son serviteur. Si c\'est l\'Éternel qui t\'excite contre moi, qu\'il reçoive le parfum d\'une offrande! mais si ce sont des hommes, qu\'ils soient maudits devant l\'Éternel, pour m\'avoir chassé aujourd\'hui, détaché de l\'héritage de l\'Éternel en disant: Va-t\'en! sers d\'autres dieux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Et maintenant que mon sang ne tombe pas en terre loin de la face de l\'Éternel, quand le Roi d\'Israël s\'est mis en campagne à la recherche d\'une puce, comme on chasse la perdrix dans les montagnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Alors Saül dit: J\'ai péché; reviens, mon fils David! Car je ne te maltraiterai plus, puisque en ce jour ma vie a été précieuse à tes yeux. Voici, j\'ai été dans l\'égarement et ai grandement manqué!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'Et David répondit et dit: Voici la pique du Roi! que l\'un des écuyers vienne la chercher!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Or l\'Éternel donnera à chaque homme le réciproque de sa justice et de sa fidélité; car aujourd\'hui l\'Éternel t\'a livré à ma discrétion et je n\'ai pas voulu porter la main sur l\'Oint de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Et voici, de même que aujourd\'hui ta vie a été précieuse à mes yeux, de même ma vie aura une grande valeur aux yeux de l\'Éternel qui me tirera de toutes les perplexités.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Et Saül dit à David: Sois béni, mon fils David! tu entreprendras, et tu viendras à bout. Et David poursuivit sa route, mais Saül regagna son lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Et David se dit lui-même: Maintenant je puis au premier jour être enlevé par la main de Saül: il n\'y a pour moi rien de mieux que de me sauver au pays des Philistins pour déjouer Saül qui se dégoûtera de me chercher encore dans tout le territoire d\'Israël; ainsi, je m\'échapperai de sa main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'David partit donc et passa avec six cents hommes qui l\'accompagnaient chez Achis, fils de Maoch, roi de Gath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Et David demeura chez Achis à Gath, ainsi que ses hommes et leurs familles à chacun, David ayant avec lui ses deux femmes, Ahinoam de Jizréel, et Abigaïl, femme de Nabal, du Carmel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Et Saül eut avis de la fuite de David à Gath; mais il ne continua pas à le chercher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Et David dit à Achis: Si j\'ai pu trouver grâce à tes yeux, que l\'on me donne un lieu dans l\'une des villes de la campagne, où je m\'établisse; car comment ton serviteur resterait-il avec toi dans la cité royale?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Et le jour même Achis lui accorda Tsiklag. C\'est pourquoi Tsiklag est dévolue aux Rois de Juda jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Et la durée du séjour de David dans les terres des Philistins fut d\'un an et quatre mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Et David et ses hommes firent invasion chez les Gessurites et les Girzites et les Amalécites; car dès les anciens temps ils habitaient le pays jusqu\'à Sur, et jusqu\'au pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Et David saccagea la contrée et ne laissa vivants ni homme ni femme, et il enleva du menu et du gros bétail et des ânes et des chameaux et des habits, et à son retour il vint chez Achis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Et Achis lui dit: Contre qui êtes-vous allés en course? Et David dit: Contre le Midi de Juda et le Midi des Jérahméhélites et le Midi des Kénites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Mais David n\'avait laissé vivants ni hommes ni femmes pour les amener à Gath, ayant cette pensée: Il ne faut pas qu\'ils puissent faire rapport contre nous et dire: Ainsi a fait David. Et telle fut sa règle pendant toute la durée de son séjour dans les terres des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Et Achis avait confiance en David et disait: Il s\'est mis en très mauvaise odeur auprès de son peuple, auprès d\'Israël, et il sera toujours mon serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Et dans le même temps les Philistins rassemblèrent leurs troupes pour entrer en campagne, porter la guerre en Israël. Et Achis dit à David: Tu sais bien que tu dois faire la campagne dans mon corps, toi et tes hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Et David dit à Achis: Aussi tu verras comment ton serviteur se comportera. Et Achis dit à David: Aussi je te donnerai en permanence la garde de ma personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, '(Or Samuel était mort et tout Israël avait célébré son deuil et on lui avait donné la sépulture à Rama, dans sa cité. Et Saül avait éloigné du pays les nécromanciens et les divinateurs).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Les Philistins se rassemblèrent donc et ils vinrent camper à Sunem. Et Saül rassembla tous les Israélites, et ils campèrent sur Gilboa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Et à la vue du camp des Philistins, Saül eut peur, et son cœur fut fort alarmé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Et Saül interrogea l\'Éternel, mais l\'Éternel ne lui répondit point, ni par des songes, ni par l\'Urim, ni par les prophètes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Alors Saül dit à ses serviteurs: Cherchez-moi une femme qui possède la nécromancie, et j\'irai chez elle et la consulterai. Et ses serviteurs lui dirent: Voici, à Endor il y a une femme qui possède la nécromancie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Et Saül se travestit, et mit d\'autres habits et partit accompagné de deux hommes, et ils arrivèrent chez la femme de nuit, et il dit: Opère pour moi une divination par la nécromancie, et évoque-moi celui que je te dirai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Et la femme lui dit: Voici, tu sais ce qu\'a fait Saül, comment il a extirpé du pays les nécromanciens et les divinateurs; et pourquoi tends-tu un piège pour attirer sur moi la peine de mort?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Alors Saül lui fit serment par l\'Éternel en ces termes: Par la vie de l\'Éternel, tu n\'encourras aucune culpabilité dans ce cas-ci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Et la femme dit: Qui te ferais-je apparaître? Et il dit: Evoque-moi Samuel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Et à l\'aspect de Samuel elle jeta un grand cri, et s\'adressant à Saül elle dit: Pourquoi m\'as-tu trompée? tu es Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Et le Roi lui dit: Sois sans crainte! mais que vois-tu? Et la femme dit à Saül: Je vois surgir de terre un dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Et il lui dit: Quelle figure est la sienne? Et elle dit: C\'est un vieillard qui surgit, et il est enveloppé d\'un manteau. Alors Saül comprit que c\'était Samuel, et il s\'inclina le visage contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Et Samuel dit à Saül: Pourquoi as-tu troublé mon repos en m\'évoquant? Et Saül dit: Je suis dans une grande détresse, car les Philistins m\'attaquent, et Dieu s\'est retiré de moi et ne me répond plus, ni par l\'organe des prophètes, ni par des songes, c\'est pourquoi je t\'ai fait évoquer afin que tu m\'apprennes ce que je dois faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Et Samuel dit: Et pourquoi m\'interroges-tu, puisque l\'Éternel s\'est retiré de toi et t\'est devenu hostile?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Et l\'Éternel a agi, comme Il l\'avait annoncé par moi, et l\'Éternel a arraché la royauté de ta main, et l\'a transférée à ton prochain, à David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Comme tu n\'as pas été docile à la voix de l\'Éternel, et n\'as pas fait subir à Amalek le feu de Ses vengeances, c\'est pourquoi l\'Éternel te traite en cette sorte aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Et l\'Éternel livrera aussi Israël avec toi aux mains des Philistins; et demain tu me rejoindras avec tes fils, et l\'armée d\'Israël aussi, l\'Éternel la livrera aux mains des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Et soudain Saül tomba de toute sa longueur sur le sol, épouvanté qu\'il était du discours de Samuel, et de plus il était exténué n\'ayant pris aucun aliment de tout le jour et de toute la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Et lorsque la femme entra chez Saül et le vit si fort consterné, elle lui dit: Voici, ta servante a obéi à ta voix, et j\'ai mis ma vie au jeu et prêté l\'oreille aux paroles que tu m\'as dites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Eh bien! de ton côté prête aussi l\'oreille à la voix de ta servante, et laisse-moi te servir quelque peu de nourriture et mange pour avoir la force de continuer ta route.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Mais il refusa et dit: Je ne mangerai point! Alors ses serviteurs et la femme aussi le pressèrent, et il céda à leurs instances, et il se releva de terre et se plaça sur le divan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Et la femme avait dans la maison un veau gras qu\'elle se hâta de tuer; puis elle prit de la farine qu\'elle pétrit et boulangea en azymes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Et elle servit ces mets à Saül et à ses serviteurs, qui mangèrent, puis se levèrent et partirent la nuit même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Et les Philistins réunirent toutes leurs forces à Aphek, et les Israélites campèrent à la source près de Jizréel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Et les Princes des Philistins marchèrent par divisions de cent et de mille, et David et ses hommes prirent l\'arrière-garde avec Achis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Et les Princes des Philistins dirent: Qu\'ont à faire ici ces Hébreux? Et Achis dit aux chefs des Philistins: N\'est-ce pas David, serviteur de Saül, Roi d\'Israël, qui a déjà passé avec moi des jours ou plutôt des années sans que j\'aie rien trouvé à redire en lui depuis son arrivée jusqu\'à ce jour?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Mais les chefs des Philistins furent irrités contre lui et lui dirent: Congédie cet homme et qu\'il retourne au lieu où tu l\'as consigné: qu\'il ne descende pas avec nous au champ de bataille, afin qu\'il ne nous fasse pas volte-face dans la mêlée; car comment regagnera-t-il la faveur de son maître? n\'est-ce pas au moyen des têtes de ces hommes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'N\'est-ce pas ce David auquel on chantait dans les chœurs: Saül abat ses mille, et David ses dix mille?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Alors Achis manda David et lui dit: Par la vie de l\'Éternel, tu as de la droiture, et j\'aimerais à t\'avoir, faisant ton service dans cette campagne, et je n\'ai rien trouvé à redire en toi depuis le jour de ton entrée chez moi jusqu\'aujourd\'hui; mais tu n\'es pas bien vu des princes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Retourne-t-en donc et va-t\'en en paix et ne fais rien qui déplaise aux Princes des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'Et David dit à Achis: Mais qu\'ai-je donc fait, et qu\'as-tu trouvé à redire en ton serviteur depuis le jour de mon entrée chez toi jusqu\'aujourd\'hui, pour que je ne puisse être admis, ni me battre contre les ennemis du Roi, mon maître?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Et Achis répondit et dit à David: Je le sais, tu es agréable à eux comme un ange de Dieu; mais les généraux des Philistins ont dit: Il ne doit pas marcher avec nous au combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Ainsi, demain lève-toi dès le matin avec les serviteurs de ton maître venus avec toi, et levez-vous le matin quand il fera jour, et allez-vous-en!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'En conséquence David se leva dès le matin avec ses hommes pour se mettre en route le matin et regagner le pays des Philistins. Et les Philistins montèrent à Jizréel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Et il se trouva que, lors du retour de David et de son monde à Tsiklag le troisième jour, les Amalécites avaient fait une expédition sur le Midi et sur Tsiklag qu\'ils avaient saccagée et incendiée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'ayant emmené captives les femmes avec ceux qui y restaient, petits et grands: ils n\'avaient tué personne; seulement ils avaient emmené leur prise, puis continué leur route.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Et au retour de David et de ses hommes à la ville, voilà qu\'elle était incendiée et leurs femmes et leurs fils et leurs filles emmenées en captivité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Alors David et la troupe qui l\'accompagnait laissèrent éclater leur voix et pleurèrent jusqu\'à n\'avoir plus la force de pleurer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Et les deux femmes de David étaient prisonnières, Ahinoam de Jizréel, et Abigaïl, femme de Nabal, le carmélite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Et David était dans une détresse car la troupe parlait de le lapider parce que l\'amertume était dans le cœur de tous, chacun regrettant ses fils et ses filles. Mais David prit sa force dans l\'Éternel son Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Et David dit à Abiathar, le Prêtre, fils d\'Ahimélech: Apporte-moi donc l\'éphod! Et Abiathar apporta l\'éphod à David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Et David interrogea l\'Éternel en ces termes: Me mettrai-je à la poursuite de cette horde-là? l\'atteindrai-je? Et Il répondit: Poursuis, car tu atteindras et délivreras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Alors David marcha avec les six cents hommes qui l\'accompagnaient, et ils s\'avancèrent jusqu\'au torrent du Bésor, et les traîneurs firent halte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Et David entreprit la poursuite avec quatre cents hommes, deux cents hommes ayant fait halte parce qu\'ils étaient trop fatigués pour passer le torrent du Bésor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Et ils trouvèrent un Egyptien dans la campagne et ils l\'amenèrent à David, et ils lui servirent des aliments et il mangea, et ils lui donnèrent de l\'eau à boire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'ils lui donnèrent aussi un quartier de bol de figues et deux gâteaux de raisins secs, et il mangea, et fut ranimé, car il n\'avait ni mangé, ni bu, ni pain, ni eau, trois jours et trois nuits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Et David lui dit: A qui es-tu? et d\'où es-tu? Et il répondit: Je suis un jeune Egyptien, au service d\'un Amalécite, et mon maître m\'a laissé parce que je suis malade voici trois jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Nous avons fait une incursion dans le Midi des Chrétites et dans les dépendances de Juda et dans le Midi de Caleb et nous avons livré Tsiklag aux flammes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'Et David lui dit: Veux-tu être mon guide jusqu\'à cette horde-là? Et il dit: Jure-moi devant Dieu que tu ne me feras pas mourir et ne me livreras pas à mon maître, et je te conduirai à cette horde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Et il fut leur guide. Et voilà que les Amalécites étaient épars dans toute la campagne mangeant et buvant et faisant fête pour tout le grand butin qu\'ils avaient enlevé du pays des Philistins et du pays de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Et depuis l\'aube jusqu\'au soir qui ouvrait le lendemain il en fit un tel carnage que pas un homme n\'échappa sauf quatre cents jeunes gens qui montèrent sur des chameaux et s\'enfuirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Et ainsi, David recouvra tout ce qu\'avaient enlevé les Amalécites, et délivra aussi ses deux femmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Et ils n\'eurent à regretter personne, ni petit ni grand, ni fils ni fille, ni aucun objet du butin qui leur avait été pris; David fit tout rentrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Et David prit tout le menu et le gros bétail; et ceux qui étaient en tête du troupeau disaient en le conduisant: C\'est la capture de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Et David ayant rejoint les deux cents hommes trop fatigués pour suivre David, qu\'il avait laissés faire halte au torrent du Bésor, ils vinrent au devant de David et de la troupe qui l\'accompagnait, et David les aborda en s\'informant d\'eux amicalement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Et tous les hommes mauvais et de bas aloi, parmi les compagnons de David, prirent la parole et dirent: Puisqu\'ils n\'ont pas marché avec nous, nous ne voulons leur donner aucune part au butin que nous avons reconquis, sinon à chacun sa femme et qu\'il les emmène et parte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Mais David dit: N\'en usez pas ainsi, mes frères, avec ce que l\'Éternel nous a donné, d\'autant qu\'Il nous a eus en sa garde et a livré entre nos mains la horde de nos envahisseurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Et qui vous écoutera dans ce que vous prononcez là... car telle la part de ceux qui sont descendus sur le champ de bataille, telle doit être la part de ceux qui sont restés auprès des bagages: ensemble ils partageront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Et c\'est ce qui à partir de ce jour eut lieu postérieurement et dont on fit une règle et une pratique pour Israël jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Et revenu à Tsiklag, David envoya du butin aux Anciens de Juda, à ses amis, avec ces paroles: Voici pour vous un don sur le butin des ennemis de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, '[il l\'envoya] à ceux de Béthel et à ceux de Ramoth-Negeb, et à ceux de Jathir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'et à ceux d\'Aroër, et à ceux de Siphmoth, et à ceux d\'Esthmoha,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'et à ceux de Rachal, et à ceux des villes de Jehraméel, et à ceux des villes des Kénites,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'et à ceux de Horma, et à ceux de Chor-Asan, et à ceux d\'Athach,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'et à ceux de Hébron et dans tous les lieux où David avait erré lui et ses hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Or les Philistins étaient en guerre avec Israël, et les hommes d\'Israël fuirent devant les Philistins, et il tomba des morts sur la montagne de Gilboa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Et les Philistins s\'acharnèrent à la poursuite de Saül et de ses fils, et tuèrent Jonathan et Abinadab et Malchisua, fils de Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Et le faix de la bataille tombait sur Saül qui, se trouvant à la portée des tireurs, hommes armés de l\'arc, fut blessé grièvement par eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Alors Saül dit à son écuyer: Tire ton épée et m\'en perce de peur que ces incirconcis ne surviennent et ne me percent et ne s\'assouvissent sur moi. Mais son écuyer ne voulut pas, car il avait grande crainte. Alors Saül prit l\'épée et se jeta dessus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Et l\'écuyer voyant Saül mort se jeta aussi sur son épée et mourut avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Ainsi périrent Saül et ses trois fils et son écuyer, de même que tous ces hommes en cette journée simultanément.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Et lorsque les Israélites de ce côté de la plaine et de ce côté du Jourdain virent que les hommes d\'Israël étaient en fuite, et que Saül et ses fils étaient morts, ils désertèrent les villes et s\'enfuirent, et les Philistins y entrèrent et s\'y établirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Et le lendemain les Philistins vinrent pour dépouiller les morts, et trouvèrent Saül et ses trois fils tombés sur la montagne de Gilboa...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Et ils lui coupèrent la tête et le dépouillèrent de son armure, et ils firent porter au pays des Philistins de toutes parts la bonne nouvelle dans les temples de leurs idoles et au peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Et ils placèrent son armure dans le temple d\'Astarté, et fixèrent son cadavre aux murs de Bethsan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Et les habitants de Jabès en Galaad furent renseignés quant à Saül et à la manière dont les Philistins l\'avaient traité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'aussitôt tous les braves se mirent en mouvement, et ils marchèrent toute la nuit et ils enlevèrent le cadavre de Saül et les cadavres de ses fils de la muraille de Bethsan, puis regagnèrent Jabès où ils les brûlèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Et ils prirent leurs ossements et les inhumèrent sous le Tamarin de Jabès et ils jeûnèrent sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Et dans le temps qui suivit la mort de Saül, David de retour après la défaite des Amalécites, s\'arrêta deux jours à Tsiklag.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Et le troisième jour, voilà qu\'il arrive un homme venant du camp et des entours de Saül, les habits déchirés et la tête couverte de poussière, et en abordant David il s\'inclina jusqu\'à terre et se prosterna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Et David lui dit: D\'où viens-tu? Et il lui répondit: Je me suis sauvé du camp d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Et David lui dit: Qu\'y a-t-il eu? Mets-moi donc au fait! Et il reprit: Il y a eu fuite des troupes qui ont quitté le champ de bataille, et de plus nombre d\'hommes du peuple tombés et morts, et Saül et Jonathan, son fils, sont morts aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Et David dit au jeune homme qui l\'informait: Comment sais-tu que Saül et son fils Jonathan sont morts?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Et le jeune informateur répondit: Par aventure je me trouvai sur la montagne de Gilboa, et voici, Saül s\'appuyait sur sa pique, et voici, les chars et la cavalerie étaient à sa poursuite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Et se tournant il me vit et m\'appela, et je dis: Me voici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Et il me dit: Qui es-tu? Et je lui dis: Je suis un Amalécite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Et il me dit: Eh bien! approche et tue-moi! car je suis saisi du spasme, tout plein de vie que je suis encore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Et je m\'avançai et le tuai, car je savais qu\'il ne survivrait pas à sa chute et j\'enlevai le diadème qu\'il avait à la tête et le brassard qu\'il portait au bras, et je les apporte ici à mon Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Alors David saisit ses habits et les déchira, et tous les hommes de son entourage en firent autant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Et ils firent les actes du deuil et pleurèrent et jeûnèrent jusqu\'au soir pour Saül et pour Jonathan, son fils, et pour le peuple de l\'Éternel et pour ta maison d\'Israël, qui étaient tombés sous l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Et David dit au jeune informateur: D\'où es-tu? Et il répondit: Je suis le fils d\'un émigré Amalécite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Et David lui dit: Comment n\'as-tu pas craint de prêter ta main au meurtre de l\'Oint de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Et David appela un des valets et dit: Avance et fais main basse sur lui! et il lui porta un coup qui le tua.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Et David lui dit: Ton sang reste sur ta tête, car ta bouche a déposé contre toi quand tu as dit: J\'ai tué l\'Oint de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Et David chanta cette complainte sur Saül et Jonathan, son fils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'il prescrivit d\'apprendre aux enfants de Juda [la complainte] de l\'arc; et voici, elle est transcrite dans le livre du Droiturier:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'La fleur d\'Israël sur tes monts a péri: comment des héros ont-ils succombé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Ne le redites pas dans Gath, ne le proclamez pas aux champs d\'Askalon, de peur de réjouir des filles de Philistins, de transporter des filles d\'incirconcis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Monts de Gilboa, que sur vous il ne tombe ni pluie, ni rosée, il n\'y ait plus de champs qui fournissent des offrandes! Car là fut jeté le bouclier des braves, le bouclier de Saül, que l\'huile n\'oignait plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Devant le sang des blessés et la graisse des héros L\'arc de Jonathan ne faisait pas retraite et l\'épée de Saül ne rentrait pas, sans avoir porté coup.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saül et Jonathan qui dans la vie s\'aimaient et s\'agréaient l\'un à l\'autre, dans la mort ne furent point séparés. Plus que les aigles ils étaient rapides, plus que les lions ils étaient vigoureux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Filles d\'Israël, donnez vos larmes à Saül qui gracieusement vous distribuait la pourpre pour vous habiller, et des joyaux d\'or pour rehausser vos robes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Comment des héros dans le combat ont-ils succombé, Jonathan fut-il percé sur tes montagnes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Je te regrette, ô Jonathan! mon frère! car tu avais un attrait puissant pour moi. Je préférais ton amour à l\'amour des femmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Comment des héros ont-ils succombé, et les armures guerrières se sont-elles perdues!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Et après ces événements, David interrogea l\'Éternel en ces termes: Dois-je gagner l\'une des villes de Juda? Et l\'Éternel lui dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Oui. Et David dit: Laquelle? Et Il répondit: Hébron. Et David s\'y transporta avec ses deux femmes, Ahinoam de Jizréel, et Abigaïl, femme de Nabal, le Carmélite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Il y emmena de même avec lui les hommes qui l\'accompagnaient, chacun d\'eux avec sa maison, et ils demeurèrent dans les villes attenantes à Hébron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Alors arrivèrent des hommes de Juda, et là ils oignirent David comme roi de la maison de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Et l\'on apporta cet avis à David: Ce sont les hommes de Jabès en Galaad, qui ont donné la sépulture à Saül. Aussitôt David dépêcha des envoyés aux hommes de Jabès en Galaad avec ce message: Soyez les bénis de l\'Éternel pour votre acte de piété envers votre Seigneur, envers Saül à qui vous avez donné la sépulture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Qu\'en retour l\'Éternel vous témoigne Son amour et Sa fidélité! de mon côté je vous donne ce témoignage de bonté, en suite de ce que vous avez fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Maintenant ayez toujours la main ferme, et soyez des braves! car si votre Seigneur Saül est mort, moi, j\'ai été oint par la maison de Juda pour être son Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Cependant Abner, fils de Ner, général d\'armée de Saül, prit Isboseth, fils de Saül, et le fit passer à Mahanaïm');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'et l\'établit roi de Galaad, et des Assurites et de Jizréel, et d\'Ephraïm et de Benjamin, ainsi de tout Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Isboseth, fils de Saül, avait quarante ans, lorsqu\'il devint roi d\'Israël, et il régna deux ans; la maison de Juda seule s\'attachait à David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Et la durée du temps que David passa à Hébron, comme roi de la maison de Juda, fut de sept ans et six mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Et Abner, fils de Ner, avec les serviteurs d\'Isboseth, fils de Saül, sortit de Mahanaïm pour marcher sur Gabaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Et Joab, fils de Tseruïa, et les serviteurs de David se mirent en campagne, et ils se rencontrèrent de part et d\'autre à l\'étang de Gabaon, et ils prirent position ceux-ci d\'un côté de l\'étang, ceux-là de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Alors Abner dit à Joab: Prenons pour champions des jeunes gens soldats, et qu\'ils s\'escarmouchent devant nous! Et Joab dit: Prenons ces champions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Et ils se mirent sur pied et ils s\'avancèrent au nombre de douze pour Benjamin et Isboseth, fils de Saül, et douze des serviteurs de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Et chacun d\'eux saisit la tête de son adversaire, et chacun d\'eux enfonça son épée dans le flanc de son adversaire, et ils tombèrent tous à la fois. Et l\'on donna à cet emplacement le nom de Helkath-Hatsourim (champ des lames): il est près de Gabaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'En cette journée le combat fut très rude et Abner et les hommes d\'Israël furent défaits par les serviteurs de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Et il y avait là trois fils de Tseruïa: Joab et Abisaï et Hasahel. Et Hasahel avait dans ses pieds l\'agilité d\'une gazelle qui court dans les champs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Et Hasahel poursuivait Abner sans s\'écarter ni à droite ni à gauche des traces d\'Abner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Et Abner se tournant en arrière dit: Est-ce toi qui es Hasahel? Et il répondit: C\'est moi-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Et Abner lui dit: Tire-toi de côté à ta droite ou à ta gauche, et attaque-toi à l\'un de ces jeunes hommes, et t\'empare de son armure. Mais Hasahel ne voulut pas se désister de sa poursuite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Et Abner répéta à Hasahel: Renonce à me poursuivre! pourquoi devrais-je t\'étendre sur le carreau? Comment alors pourrais-je me présenter à ton frère Joab?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Mais il refusa de céder. Alors Abner lui porta au ventre un coup du talon de sa lance qui ressortit par derrière, et Hasahel tomba et mourut sur la place. Et tous ceux qui arrivaient à l\'endroit où Hasahel était tombé et mort, s\'arrêtaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Et Joab et Abisaï poursuivirent Abner, et au coucher du soleil ils atteignirent le monticule d\'Amma, situé devant Giah sur la route du désert de Gabaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Et les Benjaminites vinrent se grouper à la suite d\'Abner et se formèrent en légion et prirent position au sommet d\'un coteau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Alors Abner s\'adressant à Joab lui dit: L\'épée sera-t-elle donc toujours dévorante? Ne sais-tu pas qu\'il ne résultera que misère? Combien de temps encore veux-tu ne pas dire au peuple de renoncer à poursuivre des frères?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Et Joab dit: Par la vie de Dieu! si tu n\'avais pas parlé, c\'est demain seulement que le peuple aurait été ramené de la poursuite de ses frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Puis Joab sonna de la trompette, et tout le peuple fit halte, et cessa de harceler Israël et ne continua pas la guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Cependant Abner et ses hommes employèrent toute cette même nuit à traverser la plaine, et ils passèrent le Jourdain et traversèrent tout le Bithron et gagnèrent Mahanaïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Et Joab renonçant à la poursuite d\'Abner, rassembla tout le peuple; et des serviteurs de David il manquait dix-neuf hommes et Hasahel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'D\'un autre côté les serviteurs de David avaient frappé dans Benjamin et la troupe d\'Abner, trois cent soixante hommes, à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Et ils emportèrent Hasahel et lui donnèrent la sépulture dans le tombeau de son père à Bethléhem. Et Joab et ses hommes marchèrent toute la nuit et avec le jour ils arrivaient à Hébron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Et la lutte fut longue entre la maison de Saül et la maison de David; mais David allait se renforçant de plus en plus, tandis que la maison de Saül allait s\'affaiblissant de plus en plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Et il naquit à David des fils à Hébron, et son premier-né fut Amnon, d\'Ahinoam de Jizréel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'et son deuxième, Chileab, d\'Abigaïl, femme de Nabal, le Carmélite; et le troisième, Absalom, fils de Maacha, fille de Thalmaï, roi de Gessur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'et le quatrième Adonia, fils de Haggith; et le cinquième Sephatia, fils d\'Abital;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'et le sixième Jithream, de Egla, femme de David. Tels sont ceux qui naquirent à David à Hébron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Et pendant qu\'il y eut guerre entre la maison de Saül et la maison de David, Abner tint ferme pour la maison de Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Or Saül avait eu une concubine, nommée Ritspa, fille d\'Aia. Et [Isboseth] dit à Abner: Pourquoi es-tu entré chez la concubine de mon père?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Et Abner fut fort irrité du langage d\'Isboseth et il dit: Suis-je une tête de chien qui tienne pour Juda? Aujourd\'hui je rends de bons services à la maison de Saül, ton père, à ses frères et à ses amis, et je ne t\'ai point livré aux mains de David; et aujourd\'hui tu me prends à partie à propos d\'un écart avec cette femme!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Qu\'ainsi Dieu traite Abner et plus mal encore! oui, comme l\'Éternel en a fait le serment à David,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'ainsi travaillerai-je dans son intérêt au transfert de la souveraineté ôtée à la maison de Saül, et à l\'élévation du trône de David sur Israël et sur Juda de Dan à Béerseba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Et Isboseth ne put plus répliquer un mot à Abner dont il avait peur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Sur-le-champ Abner dépêcha vers David des émissaires pour lui dire: A qui est le pays? et de plus: Fais ton traité avec moi, et voici tu auras l\'aide de ma main pour tourner Israël de ton côté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Et il répondit: Bien! Je traiterai avec toi; je n\'exige de toi qu\'une condition: tu ne reverras pas mon visage, à moins de m\'amener préalablement Michal, fille de Saül, quand tu viendras te présenter devant moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Et David envoya des délégués à Isboseth, fils de Saül, avec ce message: Rends-moi ma femme Michal, que je me suis fiancée au prix de cent prépuces de Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Et Isboseth la fit prendre chez le mari, Paltiel, fils de Laïs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Et son mari l\'accompagna et alla pleurant derrière elle jusqu\'à Bahurim. Là Abner lui dit: Va, rebrousse! Et il rebroussa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Et Abner était entré en pourparler avec les Anciens d\'Israël et avait dit: Ce n\'est pas d\'aujourd\'hui que vous, cherchez à avoir David pour Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Agissez maintenant, car l\'Éternel a dit touchant David: C\'est par la main de David, mon serviteur, que Je sauverai mon peuple d\'Israël de la main des Philistins et de la main de tous ses ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Et Abner s\'étant aussi abouché avec les Benjaminites, alla de même redire en entier aux oreilles de David à Hébron la résolution d\'Israël et de toute la maison de Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Abner arriva donc chez David à Hébron avec une escorte de vingt hommes, et David fit un festin à Abner et à son escorte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Et Abner dit à David: Je vais me mettre en mouvement et partir et réunir auprès de mon Seigneur le Roi la totalité des Israélites, afin qu\'ils fassent un accord avec toi, et tu régneras en tous points selon ton désir. Et David congédia Abner qui s\'en alla sain et sauf.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Et voilà que les serviteurs de David et Joab revinrent de leur expédition, ramenant avec eux un butin considérable. Or Abner n\'était plus chez David à Hébron. Celui-ci l\'avait congédié, et il s\'en était allé sain et sauf.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Et au retour de Joab et de toute la troupe qui l\'accompagnait, on fit à Joab ce rapport: Abner, fils de Ner, est venu chez le Roi, qui l\'a laissé partir, et il s\'en est allé sain et sauf.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Alors Joab entra chez le Roi et dit: Qu\'as-tu fait? Voici, Abner est venu chez toi; pourquoi donc l\'as-tu laissé partir et s\'en aller?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Tu connais Abner, fils de Ner! c\'est pour te surprendre qu\'il est venu, pour étudier tes allures, et savoir tout ce que tu fais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Et Joab ayant quitté David envoya des émissaires après Abner et ils le firent rebrousser depuis la citerne de Hasira, et cela à l\'insu de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Abner étant ainsi revenu à Hébron, Joab le tira à part dans l\'intérieur de la porte pour l\'entretenir en secret, et là il lui porta dans le ventre un coup qui le tua, vengeant ainsi le meurtre d\'Hasahel, son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Et David l\'ayant appris plus tard dit: Ni à moi, ni à mon règne ne pourra jamais être imputé de par l\'Éternel le meurtre d\'Abner, fils de Ner:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'qu\'il retombe sur la tête de Joab et sur toute la maison de son père, et que la maison de Joab ne soit jamais purgée d\'hommes ayant un flux immonde, de lépreux, de perclus, de tués par l\'épée et de gens manquant de pain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Or Joab et Abisaï, son frère, avaient donné la mort à Abner parce qu\'il avait tué Hasahel, leur frère, à Gabaon dans la bataille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Et David dit à Joab et à tout le peuple qui était avec lui: Déchirez vos habits et revêtez le cilice et célébrez le deuil d\'Abner. Et le roi David suivit le cercueil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Et Abner reçut la sépulture à Hébron, et le Roi laissant éclater sa voix, pleura au tombeau d\'Abner, et tout le peuple pleura.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Et le Roi chanta une complainte sur Abner en ces mots: Est-ce de la mort de l\'impie que devait mourir Abner?...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Tu n\'avais ni les mains garrottées, ni les pieds serrés dans les fers!... Tu as péri, comme on périt sous les coups du crime!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Et tout le peuple ne fit que le pleurer, davantage. Et tout le peuple se présenta dans le but de faire prendre à David de la nourriture encore de jour, mais David fit ce serment: Qu\'ainsi Dieu me fasse et pis encore si avant le coucher du soleil je goûte du pain ou d\'un mets quelconque!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Tout le peuple reconnut alors [sa sincérité] qui lui plut; tout ce que faisait le Roi était au gré de tout le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Et en ce jour tout le peuple et tout Israël acquit la conviction que ce n\'était pas de par le Roi que Abner, fils de Ner, avait été assassiné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Et le Roi dit à ses serviteurs: Ne sentez-vous pas qu\'aujourd\'hui un grand capitaine est tombé en Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'et que pour le moment je suis faible et que je viens de recevoir l\'onction de Roi? Ces hommes, les fils de Tseruïa, sont trop durs pour moi. Que l\'Éternel paie au méchant le salaire dû à sa méchanceté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Et lorsque le fils de Saül apprit que Abner était mort à Hébron, il perdit courage et tout Israël fut consterné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Or le fils de Saül avait deux hommes, chefs de partisans, nommés, l\'un Baana, et l\'autre Rechab, qui étaient fils de Rimmon de Bééroth, d\'entre les enfants de Benjamin. (Car Bééroth aussi est regardée comme étant sur Benjamin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'et les Béérothites se sont enfuis à Githaïm où ils ont été comme émigrés jusqu\'aujourd\'hui.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Et Jonathan, fils de Saül, avait un fils perclus des deux pieds: il était âgé de cinq ans lorsque de Jizréel étaient venues les nouvelles de Saül et de Jonathan; alors sa nourrice l\'avait pris et s\'était enfuie; et dans la précipitation de sa fuite, il avait fait une chute qui l\'avait laissé boiteux, et son nom était Mephiboseth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Et les fils de Rimmon de Bééroth, Rechab et Baana, s\'en vinrent et entrèrent au chaud du jour chez Isboseth, comme il était couché pour son repos de midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Et là ils s\'introduisirent dans le centre de la maison [comme] pour enlever du froment; et ils l\'éventrèrent; et Rechab et Baana, son frère, s\'évadèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Ils pénétrèrent dans la maison comme il reposait sur son lit dans sa chambre à coucher, et ils le frappèrent et le tuèrent, et lui coupèrent la tête qu\'ils emportèrent; et ils cheminèrent toute la nuit à travers la plaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Et ils présentèrent la tête d\'Isboseth à David à Hébron et dirent au Roi: Voici la tête d\'Isboseth, fils de Saül, ton ennemi, qui cherchait ta perte. Aujourd\'hui donc l\'Éternel a permis que mon Seigneur le Roi fût vengé de Saül et de sa race.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Mais David répondit à Rechab et à Baana, son frère, fils de Rimmon de Bééroth, et leur dit: Par la vie de l\'Éternel qui a sauvé ma personne de tous les périls,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'l\'informateur qui m\'a dit: « Voici, Saül est mort » et se flattait d\'apporter un heureux message, je l\'ai fait saisir et mettre à mort à Tsiklag, lui à qui j\'aurais dû donner une récompense:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'à plus forte raison, lorsque des scélérats ont tué un homme juste dans sa maison sur sa couche, ne dois-je pas redemander son sang à vos mains, et vous exterminer de la terre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Et David donna ordre aux valets, et ceux-ci les tuèrent et leur coupèrent les mains et les pieds, et les pendirent sur l\'étang de Hébron; ils prirent la tête d\'Isboseth et lui donnèrent la sépulture dans le tombeau d\'Abner à Hébron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Et toutes les Tribus d\'Israël firent une démarche auprès de David à Hébron et parlèrent en ces termes: Voici, nous sommes tes os et ta chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Ci-devant déjà, quand Saül régnait sur nous, c\'est toi qui menais et ramenais Israël, et l\'Éternel t\'a dit: Tu seras le pasteur de mon peuple d\'Israël et tu deviendras prince d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Tous les Anciens d\'Israël se présentèrent donc chez le Roi à Hébron, et le Roi David conclut avec eux un pacte à Hébron devant l\'Éternel, et ils oignirent David comme Roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'David avait trente ans à son avènement, et il régna quarante ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'A Hébron il régna sur Juda sept ans et six mois, et à Jérusalem il régna trente-trois ans sur la totalité d\'Israël et de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Et le Roi avec ses hommes marcha sur Jérusalem contre les Jébusites habitants du pays. Et ils tinrent à David ce langage: Tu ne saurais pénétrer ici, mais les aveugles et les perclus te tiendraient à distance! pour dire: David ne pénétrera pas ici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Cependant David s\'empara de la citadelle de Sion, c\'est la Cité de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Et David avait dit en ce jour-là: Quiconque battra les Jébusites et s\'avancera jusqu\'à l\'aqueduc et aux perclus et aux aveugles hostiles à la personne de David... (De là le dicton: Ni aveugle ni perclus n\'entrera au logis.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Et David prit sa résidence dans la citadelle qu\'il appela Cité de David; et David fit des constructions tout autour à partir de Millo jusque dans l\'intérieur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Et David allait grandissant pas à pas, et l\'Éternel, Dieu des armées, l\'assistait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Et Hiram, roi de Tyr, envoya une députation à David, et du bois de cèdre et des charpentiers et des maçons, qui bâtirent une maison à David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Et David sentit que l\'Éternel le confirmait comme roi d\'Israël, et qu\'il élevait son royaume en vue de son peuple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Et David prit encore des concubines et des femmes de Jérusalem après être venu d\'Hébron; et il naquit encore à David des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Or voici les noms de ses enfants nés à Jérusalem: Sammuah et Sobab et Nathan et Salomon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'et Jibehar, et Elisuah et Népheg et Japhiah');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'et Elisamah et Eliada et Eliphélet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Et à la nouvelle de l\'onction de David en qualité de roi d\'Israël les Philistins en totalité se mirent en campagne à la recherche de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Et David en ayant eu avis descendit au fort. Et les Philistins parurent et occupèrent la vallée de Rephaïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Alors David interrogea l\'Éternel en ces termes: Irai-je attaquer les Philistins? les feras-tu tomber dans mes mains? Et l\'Éternel dit à David: Va, car je ferai tomber les Philistins dans tes mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Et David s\'avança sur Bahal-Peratsim où il les défit; et il dit: L\'Éternel a rompu mes ennemis devant moi comme des eaux dont on rompt le fil. C\'est pourquoi il donna à ce lieu le nom de Bahal-Peratsim (lieu des ruptures).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Et ils abandonnèrent leurs idoles, et David et ses hommes les emportèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Et les Philistins renouvelèrent l\'attaque et occupèrent la vallée de Rephaïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Et David interrogea l\'Éternel qui répondit: N\'attaque pas! tourne-les et les prends à dos et joins-les vis-à-vis des baumiers-pleureurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Et lorsque tu ouïras un bruit de pas dans les cimes des baumiers-pleureurs, alors dépêche-toi! car c\'est le moment où l\'Éternel marchera devant toi à la défaite de l\'armée des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'Et David se conforma à l\'ordre de l\'Éternel et il battit les Philistins, de Geba aux abords de Gézer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Et par de nouvelles recrues David porta toute l\'élite d\'Israël à trente mille hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Et David se mit en mouvement et en marche de Baalei-Juda, ainsi que tout le monde qu\'il avait avec lui, pour en ramener l\'Arche de Dieu où l\'on invoque le Nom de l\'Éternel des armées siégeant sur les Chérubins qui la couvrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Et pour transporter l\'Arche de Dieu, ils prirent un chariot neuf et ils l\'enlevèrent de la maison d\'Abinadab sise sur la colline; et Uzza et Ahio, fils d\'Abinadab, conduisaient le chariot qui était neuf.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Ils la prirent donc dans la maison d\'Abinadab, sise sur la colline. [Et Uzza cheminait] à côté de l\'Arche de Dieu, et Ahio la précédait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Et David et toute la maison d\'Israël jouaient devant l\'Éternel de toutes sortes d\'instruments de cyprès, et luths et harpes, et tambourins et sistres et cymbales.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Et lorsqu\'ils atteignirent l\'aire de Nachon, Uzza étendit la main vers l\'Arche de Dieu et la saisit, parce que l\'attelage la faisait verser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Alors la colère de l\'Éternel s\'alluma contre Uzza et là Dieu le frappa à cause du sacrilège, et il mourut là à côté de l\'Arche de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Et David eut une cuisante douleur du coup dont l\'Éternel frappait Uzza; et il donna à ce lieu le nom resté jusqu\'aujourd\'hui de Perets-Uzza (coup d\'Uzza).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Et en ce jour David eut peur devant l\'Éternel et il dit: Comment entrerait chez moi l\'Arche de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Et David ne voulut pas retirer chez lui dans la cité de David l\'Arche de l\'Éternel, et il l\'entreposa dans la maison d\'Obed-Edom de Gath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'Ainsi, l\'Arche de l\'Éternel demeura trois mois dans la maison d\'Obed-Edom de Gath. Et l\'Éternel bénit Obed-Edom et toute sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Et le Roi David reçut cet avis: L\'Éternel a béni la maison d\'Obed-Edom et tout ce qui est à lui, à cause de l\'Arche de Dieu. Et David fit le voyage et transféra l\'Arche de Dieu de la maison d\'Obed-Edom à la Cité de David, dans la joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Et lorsque les porteurs de l\'Arche eurent fait six pas en avant, il sacrifia un taureau et un veau gras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Et David allait dansant de toute sa force devant l\'Éternel, et David avait endossé un éphod de lin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Et David et toute la maison d\'Israël firent la translation de l\'Arche de l\'Éternel avec des cris de joie et au son des trompettes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Cependant lorsque l\'Arche de l\'Éternel faisait son entrée dans la Cité de David, Michal, fille de Saül, regardait par la fenêtre, et à la vue du Roi David sautant et dansant devant l\'Éternel, elle ressentit pour lui du mépris en son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Et ils introduisirent l\'Arche de l\'Éternel, et ils la dressèrent à sa place dans le pavillon que David lui avait préparé, et David offrit à l\'Éternel des holocaustes et des offrandes pacifiques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Et lorsque David eut achevé le sacrifice des holocaustes et des offrandes pacifiques, il bénit le peuple au nom de l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Et il distribua à tout le peuple et à toute la multitude d\'Israël, et hommes et femmes, à chacun une galette de pain, une ration de vin, et un gâteau de raisins secs. Puis tout le monde regagna son logis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Et lorsque David revint pour saluer sa maison, Michal, fille de Saül, sortit à la rencontre de David, et elle lui dit: Comme le Roi d\'Israël s\'est honoré aujourd\'hui en se déshabillant aujourd\'hui devant les servantes de ses serviteurs, comme se déshabille quelque homme de rien!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Alors David dit à Michal: C\'est devant l\'Éternel qui a fait choix de moi à l\'exclusion de ton père et de toute sa maison pour m\'ordonner prince du peuple de l\'Éternel, d\'Israël, c\'est devant l\'Éternel que j\'ai dansé!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'et je consens à un plus grand mépris, à m\'abaisser encore à mes yeux; mais auprès des servantes dont tu parles, auprès d\'elles je serai en honneur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Or Michal, fille de Saül, fut sans enfants jusqu\'au jour de sa mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Comme le Roi était établi dans sa maison, et que de toutes parts l\'Éternel lui assurait le repos de la part de tous ses ennemis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'le Roi dit à Nathan, le prophète: Considère donc que j\'habite un palais de cèdre et que l\'Arche de Dieu loge entre des toiles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Et Nathan dit au Roi: Tout ce que tu as au cœur, va, exécute-le, car l\'Éternel est avec foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Mais, la nuit même, la parole de l\'Éternel fut adressée à Nathan en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Va et dis à mon serviteur, à David: Ainsi parle l\'Éternel: Est-ce bien toi qui me bâtiras une Maison pour ma Résidence?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Aussi bien, je n\'ai point eu de maison comme demeure depuis le jour où j\'ai tiré de l\'Egypte les enfants d\'Israël, jusqu\'au jour actuel, et j\'ai voyagé sous la tente et dans le pavillon');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'en tous les lieux que j\'ai parcourus avec tous les enfants d\'Israël. Ai-je dit un mot à l\'une des Tribus d\'Israël à qui j\'avais commis la conduite de mon peuple d\'Israël, et demandé: Pourquoi ne m\'élevez-vous pas un palais de cèdre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Eh bien donc! tu diras à mon serviteur, à David: Ainsi parle l\'Éternel des armées: Je t\'ai tiré du pâturage où tu suivais les troupeaux, pour te faire prince de mon peuple, d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'et j\'ai été avec toi dans toutes tes migrations, et j\'ai exterminé tous tes ennemis devant toi, et je t\'ai créé un grand nom, égal au nom des Grands qui sont sur la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'et j\'ai préparé un sol pour mon peuple d\'Israël, et je l\'ai planté pour qu\'il demeure en place et ne soit plus agité, et que désormais les impies ne le tourmentent plus comme dans l\'origine');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'et depuis le temps où j\'ordonnai des Juges sur mon peuple d\'Israël; et je t\'ai assuré le repos de la part de tous tes ennemis; et l\'Éternel t\'annonce qu\'il te créera une dynastie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Quand tu auras accompli le nombre de tes jours et seras gisant à côté de tes pères, j\'élèverai après toi ton descendant issu de tes entrailles, et j\'affermirai sa souveraineté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'C\'est lui qui bâtira une maison à Mon Nom, et je consoliderai son trône royal pour l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Je serai pour lui un père et il sera pour moi un fils, et, s\'il s\'égare, je le châtierai d\'une verge humaine et de coups tels que sont ceux des fils de l\'homme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'et je ne lui retirerai pas ma grâce, comme je l\'ai retirée à Saül que j\'ai fait retirer devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Et ta maison et ta souveraineté sont affermies pour l\'éternité devant toi, ton trône est consolidé pour l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Nathan tint à David un langage conforme à toutes ces paroles et à toute cette révélation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Puis le Roi David se présenta devant l\'Éternel, et il dit: Qui suis-je, Seigneur, Éternel? et qu\'est ma maison pour que tu m\'aies fait parvenir où je suis?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Et c\'était encore trop peu de chose à tes yeux, Seigneur, Éternel; tu as aussi fait à la maison de ton serviteur une promesse à terme lointain! et tu as parlé comme les hommes le font entre eux, Seigneur, Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Et qu\'est-ce que David pourrait te dire de plus?... déjà tu connais ton serviteur, Seigneur, Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'C\'est ensuite de ta parole et de ta dilection que tu as fait toute cette grande promesse que tu as voulu révéler à ton serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Aussi, tu es grand, Dieu, Éternel! car tu es sans égal; il n\'est pas d\'autre Dieu que toi, d\'après tout ce que nous avons ouï de nos oreilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Et est-il sur la terre une nation, comme ton peuple, comme Israël, que Dieu soit venu racheter pour en faire son peuple et se créer un nom, et opérer pour elle le grand acte et les miracles que tu as accomplis pour ton pays à la face de ton peuple que pour toi tu as revendiqué de l\'Egypte, de ses peuples et de ses dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Ainsi, tu t\'es assuré ton peuple d\'Israël pour qu\'il soit ton peuple à jamais, et toi, Éternel, tu es devenu son Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Maintenant donc, Éternel, Dieu, donne un effet éternel à la promesse que tu as prononcée à l\'égard de ton serviteur et de sa maison, et accomplis ce que tu as annoncé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Et qu\'on magnifie éternellement ton nom en disant: L\'Éternel des armées est le Dieu d\'Israël, et que la maison de ton serviteur David soit permanente devant toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Car toi-même, Éternel des armées, Dieu d\'Israël, tu t\'es révélé à ton serviteur et as dit: Je t\'édifierai une maison! C\'est pourquoi ton serviteur a trouvé son cœur prêt à t\'adresser cette prière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Maintenant, Seigneur, Éternel, tu es Dieu, et tes paroles sont vérité, et tu as fait à ton serviteur cette, excellente promesse:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Veuille donc! et bénis la maison de ton serviteur, afin qu\'elle soit à jamais sous ton regard; car c\'est toi, Seigneur, Éternel, qui l\'as promis et par l\'effet de ta bénédiction la maison de ton serviteur sera bénie éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Et dans les temps qui suivirent, David battit les Philistins et les humilia, et ôta des mains des Philistins les rênes de leur métropole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Et il battit les Moabites, et il les mesura au cordeau, en les faisant coucher par terre, et il en mesura deux cordeaux pour les livrer à la mort et un cordeau entier pour leur laisser la vie. Ainsi, les Moabites furent asservis à David, et payèrent le tribut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Et David battit Hadadézer, fils de Rehob, roi de Tsoba, en allant reprendre la haute main sur l\'Euphrate.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Et David lui prit mille sept cents cavaliers, et vingt mille fantassins. David énerva tous les chevaux de trait, dont pourtant il garda cent pour lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Et les Syriens de Damas vinrent au secours de Hadadézer, roi de Tsoba, et David tua aux Syriens vingt-deux mille hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Et David mit des garnisons dans la Syrie de Damas, et les Syriens furent asservis à David et payèrent le tribut. Ainsi l\'Éternel rendait David victorieux dans toutes ses expéditions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Et David prit les boucliers d\'or que portaient les serviteurs d\'Hadadézer et les apporta à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Et de Bétah et de Bérothaï, villes de Hadadézer, David enleva une très grande quantité d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Et Thoï, roi de Hamath, apprit que David avait abattu toute la puissance de Hadadézer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'alors Thoï députa Joram, son fils, au Roi David pour le saluer, et pour le féliciter d\'avoir fait la guerre à Hadadézer, et de l\'avoir défait (car Thoï était en hostilité avec Hadadézer); et Joram apportait de la vaisselle d\'argent, de la vaisselle d\'or et de la vaisselle d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Et le Roi David la consacra aussi à l\'Éternel, de même que l\'argent et l\'or qu\'il avait consacré sur les dépouilles de tous les peuples domptés par lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'Syriens, Moabites, Ammonites, Philistins, Amalécites, et sur le butin de Hadadézer, fils de Rehob, roi de Tsoba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'David acquit aussi un nom par la défaite des Syriens dans la vallée du sel, au nombre de dix-huit mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Et il mit des garnisons dans l\'Idumée, dans toute l\'Idumée il mit des garnisons et toute l\'Idumée fut asservie à David. Ainsi l\'Éternel rendait David victorieux dans toutes ses campagnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Et David régna sur la totalité d\'Israël et exerça le droit et la justice sur la totalité de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Or Joab, fils de Tseruïa, était préposé sur l\'armée, et Josaphat, fils d\'Ahilud, était chancelier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'et Tsadoc, fils d\'Ahitub, et Ahimélech, fils d\'Abiathar, étaient Prêtres, et Seraïa, secrétaire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'et Benaïa, fils de Joïada, était préposé sur les satellites et les coureurs, et les fils de David étaient ministres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Et David dit: Est-ce qu\'il y a encore quelque survivant de la maison de Saül? je veux lui témoigner de l\'affection en considération de Jonathan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Or de la maison de Saül il restait un serviteur, nommé Tsiba; et il fut mandé chez David, et le Roi lui dit: Es-tu Tsiba? Et il répondit: Pour te servir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Et le Roi dit: N\'y a-t-il d\'ailleurs plus personne de la maison de Saül, que je puisse rendre l\'objet d\'une bonté divine? Et Tsiba dit au Roi: Il y a encore un fils de Jonathan, impotent des deux pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Et le Roi lui dit: Où est-il? Et Tsiba dit au Roi: Voici, il est dans la maison de Machir, fils de Ammiel, à Lodebar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Alors le Roi David l\'envoya chercher dans la maison de Machir, fils de Ammiel, de Lodebar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Et Mephiboseth, fils de Jonathan, fils de Saül, arrivé auprès de David, s\'inclina face contre terre et se prosterna. Et David dit: Mephiboseth! Et celui-ci dit: Me voici pour te servir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Et David lui dit: N\'aie aucune crainte! car je veux te témoigner de l\'affection pour l\'amour de Jonathan, ton père, et te restituer toutes les terres de Saül, ton aïeul, et tu mangeras le pain à ma table à la continue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Et il s\'inclina et dit: Qu\'est ton serviteur pour que tu portes tes regards sur un chien mort tel que moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Alors le Roi manda Tsiba, écuyer de Saül, et lui dit: Je donne au petit-fils de ton Maître tout ce qui appartenait à Saül et à toute sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Cultive-lui la terre, toi avec tes fils et tes serviteurs, et soigne les récoltes afin que ton maître ait du pain à manger. Et Mephiboseth, fils de ton Maître, mangera à ma table à la continue. Or Tsiba avait quinze fils et vingt serviteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Et Tsiba dit au Roi: Ton serviteur agira conformément à tous les ordres donnés par le Roi, mon Seigneur, à son serviteur. Et Mephiboseth mangera à ma table, comme l\'un des fils du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Or Mephiboseth avait un fils en bas âge, nommé Mica, et tout le domestique de la maison de Tsiba était au service de Mephiboseth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Et Mephiboseth habitait Jérusalem, car il mangeait à la table du Roi à la continue. Or il était boiteux des deux pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Et dans le temps qui suivit, mourut le Roi des Ammonites, et Hanoun, son fils, lui succéda sur le trône.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Alors David dit: Je témoignerai à Hanoun, fils de Nahas, la même bonté que m\'a témoignée son père. Et David lui envoya par ses serviteurs des consolations au sujet de son père. Et lorsque les serviteurs de David furent arrivés au pays des Ammonites,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'les chefs Ammonites dirent à Hanoun, leur maître: Est-ce pour rendre devant tes yeux honneur à ton père que David t\'envoie des consolateurs? Son but n\'est-il pas d\'explorer la ville et d\'en faire l\'espionnage et le sac, quand il te délègue ses serviteurs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Alors Hanoun arrêta les serviteurs de David et leur fit raser la moitié de la barbe et couper leurs habits jusqu\'à mi-cuisses, puis les renvoya.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Et le rapport en fut fait à David qui dépêcha des gens à leur rencontre parce que ces hommes avaient été indignement traités; et le Roi dit: Restez à Jéricho, jusqu\'à ce que votre barbe ait recru; alors revenez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Cependant les Ammonites voyant qu\'ils étaient en mauvaise odeur auprès de David, dépêchèrent des émissaires et prirent à leur solde dans la Syrie de Beth-Rechob et la Syrie de Tsoba vingt mille hommes d\'infanterie, et chez le Roi de Maacha mille hommes, et des hommes de Tob, douze mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'A cette nouvelle David mit en campagne Joab et toute l\'armée, les guerriers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'De leur côté les Ammonites firent une sortie et se rangèrent en bataille à l\'entrée même de la porte, et les Syriens de Tsoba et de Rechob et les hommes de Tob et de Maacha seuls étaient dans les champs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Et Joab voyant devant et derrière lui un front d\'attaque fit un choix dans toute l\'élite d\'Israël et forma sa ligne contre les Syriens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'et il mit le reste de la troupe sous la conduite d\'Abisaï, son frère, qui fit face aux Ammonites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Et il dit: Si les Syriens ont l\'avantage sur moi, viens à mon secours, et si les Ammonites ont l\'avantage sur toi, j\'irai à ton secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Courage et tenons ferme pour notre peuple et pour les cités de notre Dieu; et que l\'Éternel fasse ce qui sera bon à ses yeux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Ainsi s\'avança Joab avec la troupe qui l\'accompagnait, à l\'attaque des Syriens, et devant lui ils prirent la fuite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Et les Ammonites voyant les Syriens en fuite, prirent eux-mêmes la fuite devant Abisaï et rentrèrent dans la ville. Et Joab revint de chez les Ammonites et rentra dans Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Et les Syriens se voyant battus par les Israélites firent un rassemblement général.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Et Hadarézer dépêcha des messagers et fit mettre sur pied les Syriens de l\'autre rive du Fleuve, et ils arrivèrent avec leurs forces ayant à leur tête Sobach, général d\'armée de Hadarézer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Et David fut informé: aussitôt il réunit tout Israël et passa le Jourdain et gagna Helam, et les Syriens se rangèrent en bataille contre David et en vinrent aux mains avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Mais les Syriens s\'enfuirent devant Israël, et David massacra aux Syriens sept cents chars et quarante mille cavaliers et fit tomber sous ses coups Sobach, général de leur armée, qui mourut là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Et tous les rois vassaux d\'Hadarézer se voyant battus par Israël firent leur paix avec Israël et ils lui furent assujettis. Et les Syriens eurent peur de venir encore au secours des Ammonites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Et au retour de l\'année, à l\'époque où les Rois ouvraient la campagne, David envoya Joab et avec lui ses serviteurs et tout Israël; et ils ravagèrent le pays des Ammonites et mirent le siège devant Rabba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Mais David resta à Jérusalem. Et il advint que dans la soirée David s\'étant levé de son lit de repos, se promenait sur le toit de la demeure royale; et de cette terrasse il aperçut une femme au bain; et cette femme, de figure, était belle au plus haut point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Et David envoya demander qui était cette femme, et on dit: Mais, c\'est Bathséba, fille d\'Eliam, femme d\'Urie, le Héthien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Et David dépêcha des émissaires chargés de l\'emmener; et elle entra chez lui, et il habita avec elle; puis, elle accomplit la pratique sainte pour secouer sa souillure, et elle s\'en retourna dans sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Et elle se trouva enceinte, et elle en fit informer David en ces termes: Je suis enceinte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Alors David fit dire à Joab: Envoie-moi Urie, le Héthien. Et Joab envoya Urie à David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Et Urie étant arrivé chez lui, David le questionna sur l\'état de Joab, et sur l\'état de l\'armée, et sur l\'état des opérations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Et David dit à Urie: Descends chez toi et te baigne les pieds. Et Urie sortit du palais du Roi, et il fut suivi d\'un don du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Mais Urie se coucha à la porte du palais du Roi avec tous les serviteurs de son maître, et ne descendit point à son logis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Et l\'on informa David en ces termes: Urie n\'est point descendu chez lui. Et David dit à Urie: N\'arrives-tu pas de voyage? Pourquoi n\'es-tu pas descendu chez toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Et Urie dit à David: L\'Arche et Israël et Juda logent dans des huttes, et mon seigneur Joab et les serviteurs de mon seigneur campent sur le sol; et moi, j\'entrerais dans ma maison pour manger et boire et coucher aux côtés de ma femme! Par ta vie et la vie de ton âme! non, je n\'en ferai rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Et David dit à Urie: Reste ici encore aujourd\'hui, et demain je te congédierai. Urie resta donc à Jérusalem ce jour-là et le suivant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Et David le convia; et il mangea devant lui et but; et David l\'enivra. Mais le soir il sortit pour se coucher sur son lit à côté des serviteurs de son maître, et il ne descendit point dans sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Et le lendemain, David écrivit à Joab une lettre qu\'il lui expédia par Urie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Et dans cette lettre il marquait: Exposez Urie au plus fort de la mêlée, puis retirez-vous de ses côtés, pour qu\'il soit atteint et meure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Et comme Joab faisait le siège de la ville, il plaça Urie à l\'endroit où il savait qu\'il y avait des braves.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Et les hommes de la ville firent une sortie et en vinrent aux prises avec Joab, et la troupe, les serviteurs de David, eurent des hommes tués, et Urie, le Héthien, fut aussi du nombre des morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Là-dessus Joab envoya à David un rapport de toutes les circonstances de l\'affaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Et il donna au messager cette instruction: Quand tu auras fini de raconter au Roi tous les détails de l\'engagement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'si la colère monte au Roi et qu\'il te dise: Pourquoi vous approcher de la ville pour une attaque? ne saviez-vous pas qu\'ils tireraient du haut de la muraille?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Qui a abattu Abimélech, fils de Jérubbéseth? n\'est-ce pas une femme qui du haut du mur lui a lancé un fragment de meule, et il en est mort à Thébets? pourquoi vous approcher de la muraille? — alors dis-lui: Ton serviteur Urie, le Héthien, est mort aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Le courrier partit, et arrivé il redit à David tout ce dont Joab l\'avait chargé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Et le messager dit à David: Comme les gens de la ville nous avaient fortement attaqués et avaient dirigé contre nous une sortie dans les champs, nous les avons refoulés jusqu\'à l\'abord de la porte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'c\'est alors que du haut du mur les archers ont tiré sur tes serviteurs et que plusieurs des serviteurs du Roi ont péri, et ton serviteur Urie, le Héthien, a aussi succombé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Alors David dit au messager: Voici ce que tu as à dire à Joab: Ne sois point peiné de cette affaire! car par-ci, par-là l\'épée tranche: pousse avec vigueur l\'assaut de la place et la rase! — Et encourage-le!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Et la femme d\'Urie apprenant la mort d\'Urie, son mari, prit le deuil pour son seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Et à l\'expiration du deuil, David la fit chercher et l\'introduisit dans sa maison, et elle devint sa femme et lui enfanta un fils. Mais l\'action que David avait faite, déplut à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Et l\'Éternel adressa Nathan à David. Et entré chez lui, il lui dit: Dans une ville il y avait deux hommes, l\'un riche, l\'autre pauvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Le riche avait des brebis et des bœufs en très grand nombre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Et pour tout bien le pauvre ne possédait qu\'un seul petit agneau qu\'il avait acheté, et qu\'il élevait, et qui grandissait à ses côtés et avec ses fils, en même temps, et mangeait à son morceau de pain et buvait à sa coupe et couchait dans son sein et était pour lui comme une fille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Et un voyageur arriva chez l\'homme riche, et il en coûtait à celui-ci de prendre parmi ses brebis ou ses bœufs de quoi traiter l\'hôte qui lui venait, et il prit l\'agneau de l\'homme pauvre et l\'apprêta pour l\'homme arrivé chez lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Alors David fut enflammé d\'une violente colère contre le riche et il dit à Nathan: Par la vie de l\'Éternel! il mérite la mort, celui qui a fait cette action.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Il faut que pour l\'agneau il donne une compensation quadruple, puisqu\'il a été capable d\'un tel acte, et qu\'il est resté sans pitié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Et Nathan dit à David: Tu es cet homme-là! Ainsi parle l\'Éternel, Dieu d\'Israël: Je t\'ai oint comme Roi d\'Israël, et je t\'ai arraché des mains de Saül,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'et je t\'ai donné la maison de ton maître, et ai mis les femmes de ton maître entre tes bras, et t\'ai donné la maison d\'Israël et de Juda, et comme si c\'était trop peu, je t\'aurais en sus fait tels dons pareils:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'pourquoi, au mépris de la parole de l\'Éternel, as-tu fait ce qui est mal à ses yeux? tu as frappé de l\'épée Urie, le Héthien, et tu lui as pris sa femme pour en faire la tienne, et lui-même tu l\'as assassiné par le glaive des Ammonites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Aussi désormais le glaive ne cessera jamais de sévir dans ta maison, parce que tu m\'as méprisé et que tu as pris la femme d\'Urie, le Héthien, pour en faire ta femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Ainsi parle l\'Éternel: Voici, je vais faire surgir les calamités contre toi de ta propre maison, et je t\'enlèverai tes femmes sous tes yeux mêmes, et je les donnerai à un autre, afin qu\'il habite avec tes femmes à la vue de ce soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Si tu as agi en cachette, moi j\'exécuterai cette menace à la face de tout Israël et à la face du soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Alors David dit à Nathan: J\'ai péché contre l\'Éternel! Et Nathan dit à David: Néanmoins l\'Éternel a pardonné ton péché: tu ne mourras pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'seulement, comme par cet acte tu as provoqué les calomnies des ennemis de l\'Éternel, le fils qui t\'est né, doit mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Là-dessus Nathan s\'en alla dans sa maison. Et l\'Éternel frappa l\'enfant que la femme d\'Urie avait enfanté à David, et qui fut dans un état désespéré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Et David chercha Dieu pour cet enfant, et David jeûna et se renferma et passa la nuit couché sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Et les Anciens de sa maison firent une tentative auprès de lui pour qu\'il se relevât de terre; mais il ne voulut pas et il ne prit aucun aliment avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Et le septième jour l\'enfant vint à mourir, et les serviteurs de David redoutaient de lui annoncer la mort de l\'enfant, car ils disaient: Voici, lorsque l\'enfant était encore en vie, nous lui parlions et il n\'entendait pas notre voix: comment lui dirions-nous: L\'enfant est mort!? il fera bien pis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Et David ayant remarqué les chuchotements de ses serviteurs, comprit que l\'enfant était mort, et David dit à ses serviteurs: L\'enfant est-il mort? Et ils dirent: Il est mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Alors David se leva de terre et se baigna et s\'oignit et changea d\'habits, et entra dans la maison de l\'Éternel, et adora, puis revint dans sa maison, et sur sa demande on lui servit des aliments et il mangea.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Et ses serviteurs lui dirent: Quelle est donc ta manière d\'agir? Tant que vivait l\'enfant, tu jeûnais et pleurais, et aussitôt après la mort de l\'enfant tu te lèves et prends de la nourriture!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Et il dit: Tant que l\'enfant était en vie, je jeûnais et pleurais, car je me disais: Qui sait? peut-être l\'Éternel me fera grâce, et l\'enfant sera conservé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Mais à présent, il est mort: pourquoi jeûnerais-je? puis-je le faire revenir? C\'est moi qui vais à lui, mais lui ne reviendra pas à moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Et David consola Bathséba, sa femme, et il entra chez elle et habita avec elle et elle lui enfanta un fils qu\'il appela du nom de Salomon. Et l\'Éternel l\'aima.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Et il le remit entre les mains du prophète Nathan qui l\'appelait Iedid-Iah (aimé de l\'Éternel) en vue de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Et Joab assiégeait Rabba des Ammonites, et comme il était près de prendre la ville royale,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'il dépêcha des courriers à David pour lui dire: J\'ai donné l\'assaut à Rabba, et, qui plus est, je suis maître du quartier des eaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'maintenant réunis le reste des troupes et viens attaquer la ville et la prendre, afin que ce ne soit pas moi qui la prenne et dont le nom soit nommé à son occasion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Alors David rassembla toutes les troupes et il marcha sur Rabba et il l\'assaillit et la prit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Et il enleva la couronne de son Roi de dessus sa tête (or elle pesait un talent d\'or et était garnie de pierreries) et il la mit sur sa propre tête et il tira de la ville un butin immense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Quant à sa population, il la fit sortir et subir les scies et les traîneaux ferrés et les haches de fer, et passer par leurs propres fournaises. Et ainsi traita-t-il toutes les villes des Ammonites. Ensuite David et tout le peuple retournèrent à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Et après cela il arriva que Absalom, fils de David, avait une sœur qui était belle, nommée Thamar, et que Amnon, fils de David, s\'éprit d\'elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Et Amnon se tourmentait pour Thamar, sa sœur, à se rendre malade; car elle était vierge et il voyait la difficulté de rien entreprendre sur elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Or Amnon avait un ami, nommé Jonadab, fils de Siméa, frère de David, et Jonadab était un homme fort avisé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Et il lui dit: Pourquoi es-tu ainsi défait, toi, fils du Roi, un matin comme l\'autre? ne me feras -tu pas confidence? Et Amnon lui dit: J\'aime Thamar, sœur d\'Absalom, mon frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Et Jonadab lui dit: Mets-toi au lit et fais le malade, et si ton père vient te voir, dis-lui: Permets à Thamar, ma sœur, de venir pour me donner à manger et préparer la collation sous mes yeux, afin que je voie et que je reçoive les aliments de sa main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Amnon se mit donc au lit et fit le malade, et le Roi vint le voir, et Amnon dit au Roi: Permets à Thamar, ma sœur, de venir pour préparer sous mes yeux deux gâteaux que je prendrai de sa main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Et David fit dire à Thamar dans son appartement: Va donc chez ton frère Amnon et prépare-lui la collation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Et Thamar se rendit chez Amnon, son frère, lequel était alité. Et elle prit du levain, et pétrit et prépara sous ses yeux les gâteaux, qu\'elle fit cuire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'puis, prenant la poêle, elle les versa devant lui. Mais il refusa de manger. Et Amnon dit: Faites sortir tout le monde d\'ici! Et tout le monde sortit de chez lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Alors Amnon dit à Thamar: Apporte la collation dans l\'appartement afin que je la reçoive de ta main. Et Thamar prit les gâteaux qu\'elle avait préparés et les apporta à Amnon, son frère, dans l\'appartement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Et comme elle lui servait à manger, il la saisit et lui dit: Viens, couche avec moi, ma sœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Et elle lui dit: Non, mon frère, non! n\'abuse pas de moi! car on ne fait pas ainsi en Israël; ne commets pas cette infamie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Et moi, où irais-je porter ma honte? et toi, tu serais comme l\'un des infâmes en Israël. Maintenant parle donc au Roi! Il ne me refusera pas à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Mais il ne voulut pas écouter sa sœur, et il lui fit violence et abusa d\'elle et habita avec elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Et Amnon la prit en forte aversion; car l\'aversion qu\'il conçut contre elle fut plus grande que l\'amour dont il avait été épris pour elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Et Amnon lui dit: Lève-toi! va-t\'en! Et elle lui dit: A tes torts tu ajoutes en me chassant un mal plus grand que l\'autre que tu m\'as fait!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Mais il ne voulut pas l\'écouter. Et il appela le valet qui le servait et lui dit: Chasse donc cette femme d\'ici dans la rue, et ferme la porte au verrou après elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Or elle portait une tunique à manches; car c\'était avec la mante le vêtement porté par les filles du Roi, vierges. Et le valet la mit dehors à la rue et ferma la porte au verrou après elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Alors Thamar mit de la cendre sur sa tête et déchira la tunique à manches qu\'elle portait, et la main appliquée sur la tête, elle s\'en alla, et elle marchait en poussant des cris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Et Absalom, son frère, lui dit: Amnon, ton frère, a-t-il été avec toi? A présent, ma sœur, ne dis mot! c\'est ton frère; ne laisse pas peser sur ton cœur ce qui est arrivé. Et Thamar demeura, éperdue qu\'elle était, dans la maison d\'Absalom, son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Et David apprit toutes ces choses et fut fort irrité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Et Absalom n\'adressait point la parole à Amnon, ni en bien ni en mal, car Absalom haïssait Amnon, parce qu\'il avait abusé de Thamar, sa sœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Et au bout de deux ans environ, comme Absalom avait des tondeurs à Bahal-Hatsor, située près d\'Ephraïm, Absalom convia tous les fils du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Et Absalom entra chez le Roi et dit: Voici, ton serviteur a des tondeurs: que le Roi daigne avec ses serviteurs accompagner ton serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Et le Roi dit à Absalom: Hé! non, mon fils, nous n\'irons pas tous, pour ne point t\'être à charge. Et il insista, mais David ne voulut point aller, et il le congédia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Et Absalom dit: Mais du moins Amnon, mon frère, ne sera-t-il pas des nôtres? Et le Roi dit: Pourquoi irait-il avec toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Mais Absalom insista auprès de lui, et David accorda permission de l\'accompagner à Amnon et à tous les fils du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Et Absalom donna cet ordre à ses valets: Observez le moment où le vin aura égayé le cœur d\'Amnon, alors à mon commandement: « Frappez Amnon! » tuez-le! n\'ayez pas peur! n\'est-ce pas moi qui vous l\'ordonne? courage et soyez des braves!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Et les valets d\'Absalom exécutèrent sur Amnon l\'ordre d\'Absalom. Sur cela tous les fils du Roi se levèrent, et montant chacun son mulet, ils s\'enfuirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Et comme ils étaient en chemin, la nouvelle parvint à David à qui l\'on dit: Absalom a fait main basse sur tous les fils du Roi, et pas un n\'a survécu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Là-dessus le Roi se leva et déchira ses habits et il se coucha par terre et tous ses serviteurs assistaient, les habits déchirés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Alors Jonadab, fils de Siméa, frère de David, prit la parole et dit: Que mon Seigneur n\'ait pas cette idée: on a mis à mort tous les jeunes hommes, fils du Roi! puisque Amnon seul a péri; car à l\'air d\'Absalom, c\'était pour lui parti pris dès le jour où il a abusé de Thamar, sa sœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Ainsi, que mon Seigneur le Roi n\'ait pas la chose sur le cœur avec cette idée: tous les fils du Roi sont morts! car Amnon seul est mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Et Absalom avait pris la fuite. Et le valet qui était en vedette leva les yeux et regarda, et voilà que par la route qu\'il avait derrière lui, une grande troupe arrivait du versant de la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Alors Jonadab dit au Roi: Voilà que les fils du Roi arrivent! les choses se sont passées comme ton serviteur l\'a dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Et quand il achevait de parler, voici, arrivèrent les fils du Roi; et laissant éclater leur voix ils pleurèrent, et le Roi aussi et tous ses serviteurs versèrent beaucoup de larmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Or Absalom dans sa fuite s\'était rendu chez Thalmaï, fils de Ammihur, roi de Gesur. Et David était toujours en deuil de son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Absalom avait donc fui, et gagné Gesur où il séjourna trois ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Et le Roi David cessa de rien entreprendre contre Absalom, car il s\'était consolé de la mort d\'Amnon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Et Joab, fils de Tseruïa, comprenait que le cœur du Roi revenait à l\'égard d\'Absalom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Alors Joab dépêcha à Thékôa et en fit venir une femme avisée; et il lui dit: Prends donc le deuil et revêts des habits de deuil, et ne t\'oins pas d\'huile, et aie l\'attitude d\'une femme depuis longtemps en deuil d\'un mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'puis présente-toi au Roi et lui parle de telle et telle manière. Et il lui mit dans la bouche le discours à tenir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'La femme Thékôïte vint donc parler au Roi, et elle se jeta le visage contre terre et se prosterna et dit: Sois secourable, ô Roi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'et le Roi lui dit: Qu\'as-tu? Et elle dit: Au vrai, je suis veuve et mon mari est mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Et ta servante avait deux fils, et ils eurent entre eux deux une rixe dans les champs, et il ne se trouva personne pour les séparer, et l\'un porta un coup à l\'autre et le tua.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Et voilà qu\'il y eut une levée de toute la parenté contre ta servante, et ils dirent: Livre le fratricide afin que nous lui donnions la mort pour l\'âme de son frère qu\'il a égorgé! et ils veulent aussi détruire l\'héritier, et ainsi éteindre le tison qui me reste pour ne laisser à mon mari ni nom ni lignée sur la face de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Et le Roi dit à la femme: Va dans ta maison! et moi, j\'aviserai à ton égard.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Et la femme Thékôïte dit au Roi: C\'est à moi, ô Roi, mon Seigneur, qu\'on s\'en prendra de la dérogation, et à la maison de mon père et le Roi et son trône ne seront pas responsables!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Et le Roi dit: Si quelqu\'un te menace, amène-le-moi! il ne s\'avisera plus de s\'attaquer à toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Et elle dit: Oh! que le Roi, mon Seigneur, se souvienne de l\'Éternel, ton Dieu, pour empêcher le vengeur du sang de multiplier les victimes et de faire périr le fils que j\'ai! Et il dit: Par la vie de l\'Éternel! non, si des cheveux de ton fils un seul tombe en terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Et la femme dit: Permets que ta servante dise un mot à mon Seigneur, le Roi! Et il dit: Parle!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Et la femme dit: Pourquoi est-ce là ta manière de penser quand il s\'agit du peuple de Dieu, puisque en se prononçant ainsi le Roi est comme coupable de ne pas accorder le retour de son banni?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Car il nous faut mourir tous, et nous devenons comme une eau épanchée sur la terre et qui ne se recueille plus; et Dieu ne se presse pas d\'ôter une vie, mais Sa pensée constante est de ne pas repousser loin de Lui celui qui s\'est banni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Or, si je suis venue tenir ce langage au Roi, mon Seigneur, c\'est que le peuple m\'avait alarmée! et ta servante s\'est dit: Je veux parler au Roi; peut-être donnera-t-il effet à la parole de sa servante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Oui, le Roi prêtera l\'oreille pour sauver sa servante des mains de l\'homme qui veut éliminer moi et mon fils à la fois de l\'héritage de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Et ta servante se disait: Puisse le langage du Roi, mon Seigneur, servir à me tranquilliser! car pareil à un ange de Dieu, le Roi, mon Seigneur, saura entendre le bien et le mal: et que l\'Éternel, ton Dieu, t\'assiste!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Et le Roi répondit et dit à la femme: Ne me cache rien de ce que je vais te demander! Et la femme dit: Que mon Seigneur le Roi daigne parler!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Et le Roi dit: La main de Joab n\'est-elle pas ta complice en tout ceci? Et la femme répondit et dit: Par ta vie, ô Roi, mon Seigneur! Ce n\'est ni à droite ni à gauche qu\'a frappé aucune des paroles du Roi, mon Seigneur! oui, c\'est ton serviteur Joab qui m\'a donné ses ordres, et a mis toutes ces paroles dans la bouche de ta servante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'C\'est pour donner à l\'affaire une autre tournure que Joab s\'y est pris de cette façon. Mais mon Seigneur a la sagesse d\'un ange de Dieu pour savoir tout ce qui a lieu sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Et le Roi dit à Joab: Eh bien! voici, je donne effet à cette parole: va donc, ramène le jeune homme, Absalom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Alors Joab se jeta la face contre terre et se prosterna et bénit le Roi, et Joab. dit: Aujourd\'hui ton serviteur sent qu\'il a trouvé grâce à tes yeux, ô Roi, mon Seigneur, puisque le Roi met à effet la parole de son serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Et Joab partit et se rendit à Gesur et il ramena Absalom à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Mais le Roi dit: Qu\'il se retire dans sa maison et ne se montre pas devant moi. Ainsi Absalom se retira dans sa maison et ne parut point devant le Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Et dans tout Israël il n\'y avait pas un homme qui eût la beauté d\'Absalom; elle était fort célèbre; de la plante des pieds au sommet de la tête il était sans défaut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Et lorsqu\'il se tondait la tête, — or toutes les années il se la tondait, car sa chevelure lui pesait, c\'est pourquoi il la coupait; — le poids des cheveux de sa tête était de deux cents sicles, poids de Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Et il était né à Absalom trois fils et une fille, nommée Thamar, et celle-ci était une femme belle de figure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Et Absalom demeura ainsi deux ans à Jérusalem, mais sans paraître en la présence du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Et Absalom manda Joab pour le députer auprès du Roi; mais il ne voulut pas venir; et il lui fit faire un second message, mais il ne voulut pas venir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Alors il dit à ses serviteurs: Voyez le champ de Joab à côté du mien, et il y a de l\'orge; allez et mettez-y le feu. Et les serviteurs d\'Absalom mirent le feu au champ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Là-dessus Joab se leva et vint trouver Absalom chez lui et lui dit: Pourquoi tes serviteurs ont-ils mis le feu à mon champ?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Et Absalom dit à Joab: Voilà que je t\'ai fait faire un message en ces termes: Viens ici et je te députerai auprès du Roi pour lui dire: Pourquoi suis-je revenu de Gesur? Mieux vaudrait pour moi d\'y être encore; maintenant je veux voir le visage du Roi; si un crime est à ma charge, qu\'il me fasse mourir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Alors Joab se présenta chez le Roi et lui fit rapport. Et il rappela Absalom, lequel vint chez le Roi et se prosterna devant le Roi face contre terre; et le Roi donna le baiser à Absalom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Et après ces choses Absalom se procura un char et des chevaux et cinquante hommes pour le précéder comme coureurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Et dès le matin Absalom se postait au bord de l\'avenue de la Porte, et à tout homme qui, ayant une affaire litigieuse, voulait entrer chez le Roi pour un jugement, Absalom adressait ces paroles: De quelle ville es-tu? Et celui-ci répondant: Ton serviteur est de l\'une des Tribus d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Absalom lui disait: Voilà que tes raisons sont bonnes et justes; mais de chez le Roi tu n\'obtiendras point d\'Auditeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Et Absalom disait: Ah! si l\'on m\'établissait Juge dans le pays, et qu\'à mon audience vînt quiconque aurait cause, et procès, je lui ferais obtenir justice!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Et lorsque quelqu\'un se prosternait en l\'abordant, il étendait la main, l\'arrêtait et lui donnait le baiser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Et Absalom s\'y prenait de cette façon à l\'égard de tous les Israélites qui se présentaient au jugement du Roi, et ainsi, Absalom soutirait l\'affection des hommes d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Et au bout de quatre ans Absalom dit au Roi: Permets que j\'aille accomplir à Hébron le vœu que j\'ai fait à l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Car ton serviteur pendant son séjour à Gesur en Syrie a fait à l\'Éternel un vœu en ces termes: Si l\'Éternel me fait revenir à Jérusalem, je servirai l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Et le Roi lui dit: Va en paix! Et Absalom partit et se rendit à Hébron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Cependant Absalom avait envoyé des émissaires dans toutes les Tribus d\'Israël pour dire: Dès que vous ouïrez le son de la trompette, dites: Absalom est Roi à Hébron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Et Absalom fut accompagné par deux cents hommes de Jérusalem, conviés et allant dans leur innocence, sans se douter de rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Et Absalom fit mander Achitophel, le Gilonite, conseiller de David, de Gilo, de sa ville, pendant qu\'il vaquait aux sacrifices. Et la ligue se renforçait et le peuple affluait toujours plus nombreux auprès d\'Absalom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Et un informateur arriva chez David en disant: Le cœur des hommes d\'Israël s\'est attaché à Absalom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Alors David dit à tous ceux de ses serviteurs qu\'il avait avec lui à Jérusalem: Debout! fuyons, car il n\'y aura pas moyen pour nous d\'échapper à Absalom. Pressez la marche, de peur qu\'il ne se presse et ne nous attaque, et ne nous écrase sous le désastre, et ne passe la cité au fil de l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Et les serviteurs du Roi dirent au Roi: Tes serviteurs sont pour tout parti que le Seigneur Roi choisira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Alors le Roi sortit, et toute sa maison à sa suite; et le Roi laissa dix concubines pour garder la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Ainsi le roi sortit et tout le peuple à sa suite; et ils firent une halte à Beth-Merhak (dernière maison).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Et tous ses serviteurs défilèrent à côté de lui, et tous les satellites et tous les coureurs et tous les Gathites formant six cents hommes venus à sa suite de Gath, défilèrent devant le Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Alors le Roi dit à Ithaï, le Gathite: Pourquoi viendrais-tu toi aussi avec nous? Retourne et reste près du Roi! car tu es étranger, et tu es un émigré dans le lieu où tu es.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Tu es arrivé d\'hier, et aujourd\'hui je te traînerais avec nous aux aventures! Car je vais où mes pas me mènent. Retourne et reconduis tes frères avec toi. Grâce et fidélité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Mais Ithaï répondit au Roi et dit: Par la vie de l\'Éternel! et par la vie de mon Seigneur le Roi! là où sera mon Seigneur le Roi, soit pour mourir, soit pour vivre, ton serviteur y sera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Et David dit à Ithaï: Va et passe! Ainsi, Ithaï, le Gathite, et tous ses hommes défilèrent de même que tous les enfants qui étaient avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Cependant tout le pays pleurait avec de grands cris au défilé de tout le peuple, et le Roi passa le torrent de Cédron, et tout le peuple passa aussi dans la direction du chemin du désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Et voici, là était aussi Tsadoc et tous les Lévites avec lui portant l\'Arche de l\'alliance de Dieu; et ils posèrent l\'Arche de Dieu, et Abiathar montait en attendant la fin du défilé du peuple sortant de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Mais le Roi dit à Tsadoc: Reconduis l\'Arche de Dieu dans la cité! Si je trouve grâce aux yeux de l\'Éternel, Il me ramènera et me la fera revoir ainsi que sa Résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Mais s\'il prononce ainsi: Je ne prends point plaisir en toi; me voici! qu\'il me traite comme il Lui semblera bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Et le Roi dit au Prêtre Tsadoc: Vois-tu! retourne dans la ville en paix, ainsi que Ahimaats, ton fils, et Jonathan, fils d\'Abiathar, vos deux fils avec vous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Voici, je veux temporiser dans les plaines du désert, jusqu\'à ce que de votre part m\'arrive un avis pour m\'informer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Là-dessus Tsadoc et Abiathar ramenèrent l\'Arche de Dieu à Jérusalem, et ils y restèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Et David gravit la pente des Oliviers, et pleurait en montant, il avait la tête couverte et marchait nu-pieds, et dans tout le peuple qui le suivait chacun se couvrit la tête et ils gravissaient et pleuraient en montant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Et David reçut cet avis: Achitophel est parmi les conjurés, complices d\'Absalom. Sur quoi David dit: Oh! déjoue le conseil Achitophel, Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Et lorsque David eut atteint la cime où Dieu est adoré, voilà que au-devant de lui arrive Husaï d\'Erech, les habits déchirés et la tête couverte de terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Et David lui dit: Si tu marches avec moi, tu me seras à charge;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'mais si tu rentres dans la ville et que tu dises à Absalom: O Roi, je veux être ton serviteur; je fus le serviteur de ton père, mais désormais je serai le tien!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'ainsi pour moi tu déjoueras les projets d\'Achitophel. Et n\'y auras-tu pas avec toi les Prêtres Tsadoc et Abiathar? et tout ce que tu apprendras de la maison du Roi, communique-le aux Prêtres Tsadoc et Abiathar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Voici, là sont avec eux leurs deux fils Ahimaats, fils de Tsadoc, et Jonathan, fils d\'Abiathar. Transmettez-moi par leur organe tout ce que vous apprendrez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Ainsi, Husaï, l\'ami de David, entra dans la ville comme Absalom arrivait à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Et David s\'était un peu avancé au delà du sommet, lorsque voilà que Tsiba, valet de Mephiboseth, arrive à sa rencontre avec une couple d\'ânes sellés et chargés de deux cents pains et de cent gâteaux de raisins secs et de cent bols de figues et d\'une outre de vin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Et le Roi dit à Tsiba: Que veux-tu faire de cela? Et Tsiba dit: Les ânes serviront de montures à la maison du Roi, et le pain et les figues, d\'aliments aux valets, et le vin, de breuvage, dans le désert, aux altérés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Et le Roi dit: Et où est le fils de ton maître? Et Tsiba dit au Roi: il se tient à Jérusalem, car il s\'est dit: Aujourd\'hui la maison d\'Israël va me restituer le royaume de mon père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Et le Roi dit à Tsiba: Voici, tout ce que possède Mephiboseth, est à toi. Et Tsiba dit: Je m\'incline! Puissé-je trouver grâce à tes yeux, Seigneur Roi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Et le Roi David ayant atteint Bahurim, voilà que en sortit un homme issu de la souche de la maison de Saül; et il se nommait Siméï, fils de Géra; il s\'avança et maudit');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'et assaillit David à coups de pierres, tandis que tous les serviteurs du Roi David et toute la troupe et tous les braves étaient à sa droite et à sa gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Et ainsi parlait Siméï en maudissant: Pars, pars, homme sanguinaire, homme de rien!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'l\'Éternel reverse sur toi tout le sang de la maison de Saül de qui tu as usurpé la souveraineté, et Il met la royauté dans la main d\'Absalom, ton fils, et te voilà dans ton malheur, parce que tu es un homme sanguinaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Alors Abisaï, fils de Tseruïa, dit au Roi: Pourquoi faut-il que ce chien mort maudisse mon Seigneur le Roi? Laisse-moi donc aller lui détacher la tête!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Mais le Roi dit: Quel rapport ai-je avec vous, fils de Tseruïa? il n\'a qu\'à maudire! car c\'est l\'Éternel qui lui a dit: Maudis David! Et qui osera dire: Pourquoi en agis-Tu ainsi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Et David dit à Abisaï et à tous ses serviteurs: Voilà que mon fils, qui est sorti de mes entrailles, attente à ma vie! A plus forte raison ce Benjaminite. Laissez-le et qu\'il maudisse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Car l\'Éternel le lui a dit. Peut-être l\'Éternel considérant ma misère, me dispensera-t-Il aujourd\'hui le bien en retour de ses malédictions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Et David et ses hommes continuèrent leur marche; mais Siméï suivit le flanc de la montagne en regard de lui, et en cheminant il maudissait et l\'assaillait à coups de pierres et soulevait la poussière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Et le Roi et toute la troupe qui l\'accompagnait, atteignirent Hajephim (les Lassitudes) et là il reprit haleine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Or Absalom et toute la troupe des hommes d\'Israël entrèrent dans Jérusalem, et Achitophel avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Et lorsque Husaï d\'Erech, ami de David, se présenta chez Absalom, Husaï dit à Absalom: Vive le Roi! Vive le Roi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Et Absalom dit à Husaï: Telle étant ton affection pour ton ami, pourquoi n\'as-tu pas accompagné ton ami?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Et Husaï dit à Absalom: Non, parce que c\'est à celui qu\'a choisi l\'Éternel et ce peuple et tout Israël, que je veux être, et auprès de lui que je resterai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Et en second lieu au service de qui entrerai-je? n\'est-ce pas à celui de son fils? De même que j\'ai servi chez ton père, de même je servirai chez toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Et Absalom dit à Achitophel: Avisez-vous de ce que nous avons à faire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Et Achitophel dit à Absalom: Habite avec les concubines de ton père, laissées par lui pour garder la maison; et tout Israël comprendra que tu es en mauvaise odeur auprès de ton père, et tous les hommes de ton bord en auront les mains plus fortes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Alors on dressa pour Absalom le pavillon de David sur la terrasse, et Absalom habita avec les concubines de son père à la face de tout Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Or les conseils que donnait Achitophel à cette époque avaient autant de crédit que la parole de Dieu consultée; tel était le crédit de tout conseil d\'Achitophel et auprès de David et auprès d\'Absalom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Et Achitophel dit à Absalom: Laisse-moi donc douze mille hommes à mon choix! je veux entreprendre la poursuite de David cette nuit même');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'et le surprendre dans le moment où il est fatigué et a les mains énervées, et lui donner l\'alarme, et la troupe qui l\'accompagne prendra la fuite, et mes coups porteront sur le Roi seul;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'et ainsi, je ferai revenir à toi tout le peuple, comme une fiancée revient à son époux. C\'est à la vie d\'un homme que tu en veux, et tout le peuple aura la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Et la proposition plut à Absalom et à tous les Anciens d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Et Absalom dit: Appelez donc aussi Husaï d\'Erech, afin que nous l\'entendions aussi s\'exprimer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Et Husaï vint chez Absalom qui lui parla en ces termes: Achitophel ouvre tel et tel avis: mettrons-nous son avis à effet? si non, dis toi-même ton opinion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Et Husaï dit à Absalom: Le conseil donné cette fois par Achitophel n\'est pas bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Et Husaï dit: Tu connais ton père et ses hommes pour des braves, exaspérés dans l\'âme comme l\'ourse dans les champs, à qui on a enlevé ses petits; et ton père est un guerrier qui n\'est pas homme à passer la nuit au repos avec sa troupe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Voilà que maintenant il s\'est caché dans quelque ravin ou autre lieu. Et si d\'emblée il fond sur eux, au premier bruit on dira: La déroute est dans la troupe qui suit Absalom!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'et même le brave qui a un cœur de lion, prendra l\'épouvante; car tout Israël sait que ton père est un héros, et que des braves l\'accompagnent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Je donne plutôt ce conseil: Qu\'autour de toi viennent se grouper tous les Israélites, de Dan à Béerséba, nombreux comme les grains de sable sur le bord de la mer, et en personne marche au combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Et si nous le joignons dans l\'un des endroits où il se tient, nous fondrons sur lui, comme la rosée sur le sol, et de lui et de tous les hommes qui l\'accompagnent, il ne restera pas un seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Que s\'il se retire dans une ville, tout Israël enceindra de câbles cette ville, et nous la culbuterons dans le torrent, jusqu\'à ne pas y laisser un seul caillou.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Et Absalom et tous les hommes d\'Israël dirent: Mieux vaut le conseil d\'Husaï d\'Erech que le conseil d\'Achitophel. Or l\'Éternel avait résolu de rendre inutile le conseil d\'Achitophel, qui était le bon, afin d\'attirer le désastre sur Absalom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Et Husaï dit aux Prêtres Tsadoc et Abiathar: Achitophel a conseillé Absalom et les Anciens d\'Israël dans tel et tel sens, et moi je les ai conseillés dans tel et tel sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Maintenant envoyez en hâte informer David en ces termes: Ne reste pas cette nuit dans les plaines du désert, mais passe plus loin, afin de prévenir la perte du Roi et de toute la troupe qui l\'accompagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Cependant Jonathan et Ahimaats étaient postés près de la Fontaine du Foulon, et la servante vint leur apporter l\'avis d\'aller informer le Roi David; car il n\'y avait pas possibilité pour eux de se faire remarquer en entrant dans la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Mais ayant été aperçus par un jeune garçon qui fit rapport à Absalom, aussitôt ils partirent tous les deux en hâte et ils gagnèrent la maison d\'un homme à Bahurim, lequel avait une citerne dans son enclos, et ils s\'y dévalèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Et sa femme prit la couverture qu\'elle étendit sur l\'ouverture de la citerne et par-dessus elle répandit des gruaux pour qu\'on ne se doutât de rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Alors les serviteurs d\'Absalom entrèrent chez la femme dans la maison et dirent: Où sont Ahimaats et Jonathan? Et la femme leur dit: Ils ont passé le Filet-d\'eau. Et ils cherchèrent et ne trouvèrent pas et ils regagnèrent Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Et après le départ des serviteurs, ils sortirent de la citerne, et ils allèrent porter l\'avis au Roi David et dirent à David: Debout! et hâtez-vous de passer l\'eau; car Achitophel a donné tel et tel conseil contre vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Alors David se mit sur pied avec toute la troupe qui l\'accompagnait, et ils passèrent le Jourdain, et au lever du jour, tous, sans qu\'il en manquât un seul, avaient franchi le Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Et lorsque Achitophel vit que son conseil n\'avait pas été mis à exécution, il sella son âne et partit et regagna sa maison, sa cité, et après avoir mis ordre à ses affaires domestiques, il s\'étrangla; et il mourut, et on lui donna la sépulture dans le tombeau de ses pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Cependant David gagna Mahanaïm, et Absalom passa le Jourdain, lui et tous les hommes d\'Israël avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Et Absalom substitua Amasa à Joab dans le commandement de l\'armée. Or Amasa était fils d\'un homme nommé Jithra l\'Israélite, qui avait habité avec Abigal, fille de Nahas, sœur de Tseruïa, mère de Joab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Et Israël et Absalom campèrent sur le territoire de Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Et lorsque David fut arrivé à Mahanaïm, Sobi, fils de Nahas, de Rabba des Ammonites, et Machir, fils d\'Ammiel, de Lodebar, et Barzillaï, le Galaadite, de Roglim,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'apportèrent des lits et des tapis et de la vaisselle de potier, du froment et de l\'orge et de la farine et du grain rôti et des fèves et des lentilles et du grain rôti');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'et du miel et du caillé et des moutons et des fromages de vache, à David et à la troupe qui l\'accompagnait, pour se nourrir; car ils s\'étaient dit: La troupe a eu faim, fatigue et soif dans le désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Et David passa en revue la troupe qu\'il avait avec lui et la mit sous la conduite de chefs de mille et de chefs de cent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Et David confia le commandement d\'un tiers de l\'armée à Joab, celui d\'un tiers à Abisaï, fils de Tseruïa, frère de Joab, et celui d\'un tiers à Ithaï de Gath. Et le Roi dit à l\'armée: Je veux aussi moi-même marcher avec vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Et l\'armée dit: N\'en fais rien! car si nous fuyons, ils n\'auront aucun souci de nous; et si la moitié d\'entre nous périssent, ils n\'auront aucun souci de nous; car tu es comme dix mille de nous; il vaut donc mieux que de la ville tu sois à même de nous secourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Et le Roi leur dit: Je ferai ce qui à vos yeux est préférable. Et le Roi vint se placer à côté de la Porte et toute l\'armée sortit par centaines et milliers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Et le Roi fit cette injonction à Joab, et à Abisaï et à Ithaï: Ménagez-moi le jeune homme Absalom! Et tout le peuple entendit l\'injonction de David à tous les chefs touchant Absalom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Et l\'armée sortit dans les champs à la rencontre d\'Israël; et le combat eut lieu dans la forêt d\'Ephraïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Et le peuple d\'Israël y fut battu par les serviteurs de David, et il y eut là en cette journée grand carnage, vingt mille hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Et le combat se déploya sur toute la contrée et la forêt fit plus de victimes dans le peuple que le glaive en cette journée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Et Absalom se trouva fortuitement en vue des serviteurs de David. Or Absalom montait un mulet, et son mulet s\'engagea sous l\'épaisse ramure du grand Térébinthe, et sa tête se prit au térébinthe, et il resta suspendu entre le ciel et la terre, tandis que le mulet qu\'il\'avait sous lui prit le large.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Et un homme le vit dans cet état et en donna avis à Joab en ces termes: Voilà que j\'ai vu Absalom pendu au Térébinthe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Et Joab dit à son informateur: Mais, si tu l\'as vu, pourquoi ne l\'as-tu pas abattu par terre au lieu même? pour ma part, je t\'aurais donné dix sicles d\'argent et un ceinturon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Et l\'homme dit à Joab: Et eussé-je senti dans ma main le poids de mille sicles d\'argent, je n\'aurais pas porté la main sur le fils du Roi, car à nos oreilles le Roi a fait cette injonction à toi et à Abisaï et à Ithaï: Prenez garde chacun de vous au jeune homme, à Absalom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Et dans le cas où j\'aurais attenté à sa vie en guet-apens, d\'un côté rien ne reste caché au Roi, de l\'autre, toi-même tu aurais été contre moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Et Joab dit: Non, pour cela je n\'attendrai pas devant toi! Et il prit trois épieux dans sa main, et il les enfonça dans le sein d\'Absalom. Celui-ci était encore en vie au cœur du térébinthe,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'lorsque survinrent dix jeunes hommes, écuyers de Joab, qui l\'égorgèrent et lui donnèrent la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Alors Joab sonna de la trompette, et la troupe se replia cessant de harceler Israël; car Joab voulait épargner le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Et ils prirent Absalom et le jetèrent dans la forêt dans un grand creux, et sur lui ils élevèrent un très gros tas de pierres. Et tous les Israélites s\'enfuirent chacun dans sa tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Or de son vivant Absalom s\'était procuré et érigé un cippe qui est dans la vallée royale; car il disait: Je n\'ai point de fils pour perpétuer le souvenir de mon nom; et il donna son nom au cippe, appelé Cippe d\'Absalom jusqu\'à nos jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Cependant Ahimaats, fils de Tsadoc, dit: Je vais courir porter au Roi la bonne nouvelle que l\'Éternel lui a fait droit en le tirant des mains de ses ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Et Joab lui dit: Non, ce n\'est pas le jour pour toi de porter la nouvelle; tu feras le message un autre jour aujourd\'hui tu ne dois pas faire le message vu la circonstance de la mort du fils du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Et Joab dit à Chusi: Va annoncer au Roi ce que tu as vu. Et Chusi s\'inclina devant Joab et partit à la course.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Et Ahimaats, fils de Tsadoc, revint à la charge et dit à Joab: Quoi qu\'il puisse arriver, je veux moi aussi, avec votre permission, me mettre en course après Chusi! Et Joab dit: A quoi bon cette course, mon fils? Ce n\'est pas là pour toi un message profitable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, '« Quoi qu\'il arrive, je veux aller. » Et il lui dit: Cours donc! Et Ahimaats franchit à la course le chemin de la plaine et il devança Chusi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'Cependant David était assis entre les deux portes, et la sentinelle parcourait le toit de la porte attenante à la muraille; et levant les yeux elle regarda; et voilà que venait en courant un homme seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Et la sentinelle cria et avertit le Roi; et le Roi dit: S\'il est seul, c\'est un bon message qu\'il vient rendre. Et il arrivait toujours plus près.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Et la sentinelle aperçut un autre homme qui accourait, et la sentinelle cria du côté de la porte et dit: Voilà qu\'un homme accourt seul. Et le Roi dit: C\'est aussi un messager.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Et la sentinelle dit: A voir la manière de courir du premier, c\'est comme celle d\'Ahimaats, fils de Tsadoc. Et le Roi dit: C\'est un homme de bien, c\'est du bien qui l\'amène.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Et Ahimaats cria et dit au Roi: Tout va bien! Et il s\'inclina devant le Roi le visage contre terre et dit: Béni soit l\'Éternel, ton Dieu, qui a arrêté les hommes qui levaient leur main contre mon Seigneur, le Roi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Et le Roi dit: Est-il sain et sauf, le jeune homme, Absalom? Et Ahimaats dit: Je voyais bien la grande mêlée lorsque Joab dépêcha le serviteur du Roi (Chusi) et ton serviteur, mais je ne suis au fait de rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Et le Roi dit: Approche et tiens-toi ici! Et il s\'approcha et resta debout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Et voilà qu\'alors arriva Chusi; et Chusi dit: Que mon Seigneur le Roi reçoive la bonne nouvelle: l\'Éternel t\'a fait droit aujourd\'hui en te tirant des mains de tous ceux qui se soulevaient contre toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Et le Roi dit à Chusi: Est-il sain et sauf, le jeune homme, Absalom? Et Chusi dit: Qu\'il en advienne comme au jeune homme, à tous les ennemis du Roi, mon Seigneur, et à tous ceux qui se lèvent contre toi pour te nuire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Alors le Roi eut de l\'ébranlement et il monta à l\'étage supérieur de la porte et pleura; et ainsi parlait-il en s\'en allant: Mon fils Absalom! mon fils, mon fils Absalom! Oh! si seulement j\'étais mort à ta place, Absalom! mon fils! mon fils!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Et Joab fut averti: Voici, le Roi est en larmes; il s\'abîme dans son deuil pour Absalom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Et la victoire de cette journée devint un deuil pour tout le peuple, car en ce jour le peuple entendait qu\'on disait: Le Roi est dans la douleur à cause de son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Et en ce jour le peuple rentra dans la ville en s\'effaçant de la même manière que filent des troupes, honteuses d\'avoir fui dans le combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Et le Roi se voila le visage et le Roi s\'écriait à voix haute: Mon fils Absalom! Absalom! mon fils! mon fils!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Alors Joab entra chez le Roi dans la maison et dit: Aujourd\'hui tu as jeté l\'abattement sur le visage de tous tes serviteurs qui aujourd\'hui ont sauvé ta vie et la vie de tes fils et de tes filles et la vie de tes femmes et la vie de tes concubines,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'par l\'amour que tu témoignes à ceux qui te haïssent et par la haine que tu montres pour ceux qui t\'aiment; car aujourd\'hui tu as déclaré ne te soucier ni de capitaines, ni de serviteurs; car je me suis convaincu aujourd\'hui que, si Absalom vivait, et que nous tous, nous fussions morts, alors tu serais content.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Maintenant donc lève-toi, sors, et adresse des paroles affectueuses à tes serviteurs! Car, par l\'Éternel je le jure, si tu ne te montres pas, personne ne restera avec toi cette nuit; et pour toi cela serait plus funeste que tout ce qui a pu t\'arriver de funeste depuis ta jeunesse jusqu\'à présent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Alors le Roi se leva et s\'installa dans la Porte. Et le fait fut annoncé à tout le peuple en ces termes: Voici, le Roi a pris séance dans la Porte. Et tout le peuple se présenta devant le Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Cependant les Israélites s\'étaient enfuis chacun dans ses tentes. Et dans toutes les Tribus d\'Israël tout le monde récriminait et disait: Le Roi nous a arrachés de la main de nos ennemis, et sauvés de la main des Philistins, et maintenant il a fui hors du pays par le fait d\'Absalom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Et Absalom que nous avions oint [pour régner] sur nous a péri dans le combat; à présent pourquoi tardez-vous à réintégrer le Roi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'De son côté, le Roi David envoyait aux Prêtres Tsadoc et Abiathar cette dépêche: Parlez aux Anciens de Juda en ces termes: Pourquoi seriez-vous les derniers à réintégrer le Roi dans sa maison, tandis que le langage de tout Israël parvient jusqu\'au Roi dans sa maison?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Vous êtes mes frères, mes os et ma chair: pourquoi seriez-vous donc les derniers à restaurer le Roi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Et dites à Amasa: N\'es-tu pas mes os et ma chair? Qu\'ainsi Dieu me fasse et pis encore, si tu n\'entres pas à mon service en permanence comme général d\'armée à la place de Joab!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Et il inclina le cœur de tous les hommes de Juda comme d\'un seul homme, et par une députation ils firent dire au Roi: « Reviens, toi et tous tes serviteurs! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Là-dessus le Roi opéra son retour et arriva sur le Jourdain. Et Juda s\'avança jusqu\'à Guilgal pour aller au-devant du Roi et lui faire passer le Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Alors accourut Siméï, fils de Géra, Benjaminite, de Bahurim, et il descendit avec les hommes de Juda au-devant du Roi David,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'ayant avec lui mille hommes de Benjamin, et Tsiba, valet de la maison de Saül, escorté de ses quinze fils et de ses vingt domestiques; et ils franchirent le Jourdain à la vue du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Et le bac était à l\'autre bord à la disposition du Roi, pour passer la maison du Roi, et Siméï, fils de Géra, se prosterna devant le Roi prêt à passer le Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Et il dit au Roi: Veuille mon Seigneur, le Roi, ne pas me compter une faute, et ne pas se souvenir, pour le garder sur le cœur, du tort qu\'a eu ton serviteur, lorsque mon Seigneur le Roi sortait de Jérusalem!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Car ton serviteur sent qu\'il a manqué; et voici, aujourd\'hui, de toute la maison de Joseph, je suis le premier à me présenter à la rencontre du Roi, mon Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Et Abisaï, fils de Tseruïa, prit la parole et dit: Pourquoi faudrait-il que Siméï ne subît pas la mort pour le fait d\'avoir maudit l\'Oint de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Et David dit: Quel rapport ai-je avec vous, fils de Tseruïa, qui devenez aujourd\'hui mes adversaires? Aujourd\'hui un homme pourrait-il être mis à mort en Israël? car ne sais-je pas que c\'est aujourd\'hui que je suis Roi sur Israël?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Et le Roi dit à Siméï: Tu ne seras point mis à mort. Et le Roi lui en fit le serment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Et Mephiboseth, [petit-]fils de Saül, descendit à la rencontre du Roi. Or il n\'avait ni baigné ses pieds, ni fait sa barbe, ni lavé ses habits depuis le jour du départ du Roi jusqu\'au jour de son heureux retour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Comme il vint donc de Jérusalem à la rencontre du Roi, le Roi lui dit: Pourquoi n\'es-tu pas parti avec moi, Mephiboseth?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Et il répondit: O Roi, mon Seigneur, j\'ai été la dupe de mon valet. Car ton serviteur avait donné l\'ordre: Selle-moi l\'âne! et je le monterai et joindrai le Roi; car ton serviteur est perclus');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'et ton serviteur a été desservi par lui auprès de mon Seigneur le Roi. Mais, mon Seigneur le Roi est comme un ange de Dieu! Fais donc ce qui sera bon à tes yeux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Car toute la maison de mon père n\'avait à attendre de mon Seigneur le Roi que la mort; et pourtant tu as mis ton serviteur au nombre de tes commensaux. Et quel droit me reste, et quel sujet de me récrier auprès du Roi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Et le Roi lui dit: Pourquoi prolonger tes discours? J\'ai prononcé: Toi et Tsiba, vous aurez le champ en commun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Et Mephiboseth dit au Roi: Qu\'il prenne la totalité dès que mon Seigneur le Roi est heureusement rentré dans sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Et Barzillaï, de Galaad, descendit de Roglim et passa le Jourdain avec le Roi pour raccompagner dans la traversée du Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Or Barzillaï était très âgé; il avait quatre-vingts ans; et il avait fourni le Roi pendant son séjour à Mahanaïm; car c\'était un personnage très considérable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Et le Roi dit à Barzillaï: Passe avec moi sur l\'autre rive; j\'aurai soin de toi chez moi à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Et Barzillaï dit au Roi: Quel est le nombre des années de ma vie pour que je suive le Roi à Jérusalem?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'J\'ai quatre-vingts ans aujourd\'hui: suis-je à même de discerner le bien du mal? et ton serviteur peut-il savourer ce qu\'il mange ou ce qu\'il boit? ou puis-je encore jouir de la voix des chantres et des cantatrices? Et pourquoi ton serviteur serait-il encore à charge à mon Seigneur le Roi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'C\'est pour peu de temps que ton serviteur passerait avec le Roi de l\'autre côté du Jourdain; et pourquoi le Roi m\'accorderait-il ce bienfait?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Permets que ton serviteur retourne et que je meure dans ma cité près du tombeau de mon père et de ma mère. Mais, voici, ton serviteur Chimham passera avec mon Seigneur le Roi. Agis-en avec lui, comme tu le trouveras bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Et le Roi dit: Chimham passera avec moi et je veux le traiter à ton gré, et faire pour l\'amour de toi tout ce que tu désirerais de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Et ainsi tout le peuple passa le Jourdain; et le Roi passa; et le Roi donna le baiser à Barzillaï qu\'il bénit et qui regagna sa demeure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Et le roi se dirigea vers Guilgal, et Chimham l\'accompagnait, et tout le peuple de Juda formait le cortège du Roi, ainsi que la moitié du peuple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Et voilà que tous les hommes d\'Israël se présentèrent au Roi et lui dirent: Pourquoi nos frères, les hommes de Juda, t\'ont-ils accaparé, et ont-ils conduit le Roi et sa maison à travers le Jourdain, et tous les hommes de David avec lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Et tous les hommes de Juda répondirent aux hommes d\'Israël: Parce que le Roi me tient de plus près; et pourquoi donc t\'irrites-tu de ce fait? Avons-nous vécu aux frais du Roi et nous a-t-il dotés de largesses?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Et les hommes d\'Israël répondirent aux hommes de Juda et dirent: Je tiens au Roi par dix côtés et à David plus que toi; et pourquoi m\'as-tu ainsi dédaigné? Et n\'est-ce pas moi qui le premier ai parlé de la restauration de mon Roi? Et les discours des hommes de Juda furent plus rudes que les discours des hommes d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Et là se rencontra un homme mauvais, nommé Séba, fils de Bicheri, Benjaminite; et il sonna de la trompette et dit: Nous ne sommes ni participants de David, ni tenanciers du fils d\'Isaï:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Chacun à sa tente, Israélites! Alors tous les Israélites se détachèrent de David, pour suivre Séba, fils de Bicheri. Mais les hommes de Juda se serrèrent autour de leur Roi, du Jourdain à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Et David rentra dans sa maison à Jérusalem. Et le Roi prit les dix concubines qu\'il avait laissées pour garder la maison, et les mit en lieu de détention, et pourvut à leur entretien; mais il n\'habita point avec elles, et elles furent recluses jusqu\'au jour de leur mort, vivant en état de viduité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Et le Roi dit à Amasa: Convoque-moi les hommes de Juda dans l\'espace de trois jours, puis reviens ici à ton poste!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Et Amasa se mit en route pour convoquer Juda, mais il tarda au delà du terme à lui fixé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Et David dit à Abisaï: Maintenant Séba, fils de Bicheri, nous nuira plus qu\'Absalom. Toi donc, prends les serviteurs de ton Souverain, et mets-toi à sa poursuite, de peur qu\'il n\'occupe des places fortes, et ne se dérobe à notre vue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Alors sous sa conduite partirent les hommes de Joab et les satellites et les coureurs et tous les braves; et ils sortirent de Jérusalem à la poursuite de Séba, fils de Bicheri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Ils étaient à la grande pierre près de Gabaon, lorsque Amasa parut en vue d\'eux. Or Joab avait ceint une cotte d\'armes sur son habit; et par-dessus il était ceint de l\'épée qui était attachée à ses reins dans le fourreau; et comme elle en était sortie, il laissa retomber [sa main].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Et Joab dit à Amasa: Te va-t-il bien, mon frère? Et de sa main droite Joab prit la barbe d\'Amasa pour lui donner le baiser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Or Amasa n\'avait pas pris garde à l\'épée qui était dans la main de Joab, et celui-ci lui en porta un coup dans le ventre d\'où ses entrailles se répandirent sur le terrain, et il ne réitéra pas, et Amasa mourut. Cependant Joab et Abisaï, son frère, poursuivirent Séba, fils de Bicheri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Et à côté d\'Amasa était resté un homme d\'entre les écuyers Joab et il disait: Que ceux qui sont du parti de Joab et pour David, suivent Joab!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Or Amasa roulait dans son sang au milieu du chemin, et quand l\'homme vit que tout le monde s\'arrêtait, il poussa Amasa de la route dans un champ et jeta sur lui un manteau, lorsqu\'il vit que tous ceux qui arrivaient près de lui, s\'arrêtaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Lorsqu\'il fut écarté de la route, chacun passa à la suite de Joab, à l\'effet de poursuivre Séba, fils de Bicheri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Et il parcourut toutes les Tribus d\'Israël jusqu\'à Abéla et Beth-Maacha; et tous les hommes d\'élite s\'étaient réunis et joints à lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Et ils vinrent l\'assiéger dans Abéla-Beth-Maacha; et ils élevèrent une terrasse contre la place; et il était posté sur le glacis, et comme toute la troupe que Joab avait avec lui sapait pour faire crouler la muraille,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'une femme bien avisée cria de la ville: Écoutez! écoutez! Dites donc à Joab: Approche jusqu\'ici, que je te parle!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Et il vint à proximité et la femme lui dit: Est-ce toi qui es Joab? Et il dit: Moi-même. Et elle lui dit: Écoute le langage de ta servante! Et il dit: J\'écoute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Et elle dit: Jadis on avait coutume de dire: Que l\'on demande conseil dans Abéla, et ainsi, l\'on viendra à bout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Je suis l\'une des pacifiques, fidèles en Israël: tu cherches à tuer une ville, une cité mère en Israël! pourquoi veux-tu abîmer une propriété de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Et Joab répondit et dit: Loin, loin de moi la pensée d\'abîmer et de détruire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Telle n\'est pas la question; mais un homme de la Montagne d\'Ephraïm, nommé Séba, fils de Bicheri, a levé sa main contre le Roi David; livrez-le seul et je m\'éloignerai de la place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Et la femme dit à Joab: Voici, sa tête va t\'être jetée par-dessus la muraille. Alors la femme se présenta à tout le peuple avec son sage avis; et on trancha la tête à Séba, fils de Bicheri, et on la jeta à Joab. Et il sonna de la trompette, et levant le siège de la place ils se disséminèrent tous gagnant chacun leurs tentes; quant à Joab, il revint à Jérusalem auprès du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Or Joab était préposé sur toute la milice d\'Israël, et Benaïa, fils de Joïada, sur les satellites et les coureurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'et Adoram sur les corvées, et Josaphat, fils de Ahilud, était chancelier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'et Séja, secrétaire, et Tsadoc et Abiathar, Prêtres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'et Ira de Jaïr était aussi ministre de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Et au temps de David il y eut famine durant trois années consécutives. Et David chercha la face de l\'Éternel et l\'Éternel dit: Sur Saül et sa maison pèse le sang versé, parce qu\'il a fait périr les Gabaonites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Alors le Roi manda les Gabaonites et leur parla. Or les Gabaonites ne font point partie des enfants d\'Israël, mais d\'un reste des Amoréens, et les enfants d\'Israël s\'étaient liés envers eux par un serment; mais Saül cherchait à s\'en défaire, dans son: zèle pour les enfants d\'Israël et de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Et David dit aux Gabaonites: Que puis-je faire pour vous, et par quelle expiation vous donnerai-je lieu de bénir l\'héritage de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Et les Gabaonites lui dirent: Il n\'est pas question pour nous de réclamer argent et or de Saül et de sa maison, et ce n\'est pas à nous de faire mourir personne en Israël. Et il dit: Que dites-vous que je dois faire pour vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Et ils dirent au Roi: [Nous en voulons à] l\'homme qui nous a perdus et a formé le projet de nous exterminer et de nous empêcher d\'exister dans tout le territoire d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'qu\'on nous livre sept hommes d\'entre ses fils, et nous les pendrons devant l\'Éternel dans Gibea de Saül, l\'élu de l\'Éternel. Et le Roi dit: Je les livrerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Or le Roi épargna Mephiboseth, fils de Jonathan, fils de Saül, à cause du serment prêté devant l\'Éternel et intervenu entre eux, entre David et Jonathan, fils de Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Et le Roi prit les deux fils de Ritspa, fille d\'Aïa, qu\'elle avait enfantés à Saül, Armoni et Mephiboseth, et les cinq fils de Merab, fille de Saül, qu\'elle avait enfantés à Adriel, fils de Barzillaï, de Mehola,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'et il les livra aux mains des Gabaonites qui les pendirent sur la montagne devant l\'Éternel. Ainsi périrent-ils les sept à la fois; or ils subirent la mort dans les premiers jours de la moisson, au début de la moisson des orges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Alors Ritspa, fille d\'Aïa, prit le cilice, et l\'étendit sous elle sur le rocher depuis le début de la moisson jusqu\'au moment où la pluie du ciel tomba sur les cadavres, et elle ne permettait pas aux oiseaux du ciel de se poser sur les corps pendant le jour, et la nuit elle en écartait les bêtes des champs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Et l\'on informa David de ce qu\'avait fait Ritspa, fille d\'Aïa, concubine de Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Alors David alla reprendre les os de Saül et les os de Jonathan, son fils, aux maîtres de Jabès en Galaad, qui les avaient dérobés de la place de Bethséan où les Philistins les avaient suspendus le jour où les Philistins avaient battu Saül sur Gilboa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Et il transféra de là les os de Saül et les os de Jonathan, son fils, et ils recueillirent aussi les os des pendus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'et ils donnèrent la sépulture aux os de Saül et de Jonathan, son fils, dans le pays de Benjamin à Tsela, dans le tombeau de Kis, son père, et ils exécutèrent tous les ordres du Roi. Et là-dessus Dieu se laissa fléchir en faveur du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Et les Philistins furent encore en guerre avec Israël. Alors David descendit et ses serviteurs avec lui, et ils engagèrent le combat avec les Philistins. Et David éprouvait de la fatigue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Et Jesbibenob, l\'un des descendants du Géant (le poids du fer de sa lance était de trois cents sicles d\'airain, et il portait à la ceinture une [épée] neuve), parlait de faire tomber David sous ses coups.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Mais Abisaï, fils de Tseruïa, lui vint en aide et battit le Philistin et le tua. Alors les hommes de David l\'adjurèrent en ces termes: Il ne faut plus que tu marches au combat avec nous, car tu ne dois pas éteindre le flambeau d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Et sur ces entrefaites il y eut encore combat à Gob avec les Philistins. Alors Sibchaï, de Husa, battit Saph, qui était l\'un des descendants du Géant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Et il y eut encore combat à Gob avec les Philistins. Alors Elchanan, fils de Jaarei-Orgim, de Bethléhem, battit Goliath, de Gath, et la hampe de sa lance était comme une ensouple de tisserand.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Et il y eut encore combat à Gath. Là était un homme de haute taille, et il avait six doigts aux mains et six orteils aux pieds, vingt-quatre en somme, et lui aussi était un descendant du Géant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Et il outragea Israël, mais fut battu par Jonathan, fils de Siméa, frère de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Ces quatre étaient nés au Géant à Gath et ils périrent par la main de David et par la main de ses serviteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Et David adressa à l\'Éternel les paroles de ce cantique, lorsque l\'Éternel l\'eut délivré de la main de tous ses ennemis et de la main de Saül');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'et il dit: Éternel, mon rocher, mon asile et mon libérateur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'ô Dieu, mon rocher, où je vais m\'abriter! mon bouclier, corne de mon salut, mon boulevard et mon refuge, mon Sauveur, de la violence tu me sauves!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Loué soit l\'Éternel, me suis-je écrié, et de mes ennemis j\'ai été délivré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Car les vagues de la mort m\'enserraient, et les torrents de l\'adversité m\'épouvantaient,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'les chaînes des Enfers m\'enlaçaient et j\'étais pris dans les rêts de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Dans mon angoisse j\'invoquai l\'Éternel et à mon Dieu j\'adressai mon appel, et de son palais Il entendit ma voix, et mes cris [vinrent] à ses oreilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Alors la terre oscilla et trembla, les fondements des Cieux s\'ébranlèrent et tremblèrent, parce qu\'il était courroucé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Une fumée sortit de ses narines, et de sa bouche, un feu dévorant, et Il fit jaillir des charbons ardents,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'et Il inclina le Ciel et Il descendit, et l\'obscurité était sous ses pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Et Il était monté sur le Chérubin et volait Et Il se montra sur les ailes du vent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'et autour de Lui Il fit sa tente des ténèbres, des amas d\'eau et des sombres nuées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'De la splendeur qui le précède, jaillirent les charbons ardents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'L\'Éternel tonna du ciel et le Très-Haut émit sa voix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'et Il lança ses flèches et Il les dissipa, la foudre, et Il les défit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Et l\'on vit paraître les vallées de la mer, et les fondements du monde furent mis à nu au grondement de l\'Éternel, au souffle du vent de ses narines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Il tendit [sa main] d\'en haut et me prit et Il me retira des grandes eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Il me sauva de mes puissants ennemis, de mes adversaires qui l\'emportaient sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Ils m\'attaquaient au jour du malheur, mais l\'Éternel fut un soutien pour moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Il m\'amena au large, Il me dégagea parce qu\'il m\'était propice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'L\'Éternel me traita selon ma justice, et me rendit selon la pureté de mes mains;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'car je gardais les voies de l\'Éternel, et n\'étais point rebelle à mon Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Car j\'avais toutes ses lois sous les yeux, et ne m\'écartais pas de ses commandements;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'j\'étais sans reproche envers Lui, et je prenais garde de me rendre coupable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Aussi l\'Éternel me rendit selon ma justice, selon ma pureté dont Il était témoin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'A celui qui t\'aime, tu donnes ton amour, tu te montres juste pour l\'homme juste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'tu es pur envers celui qui est pur, et tu trahis celui qui est perfide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Et tu es en aide au peuple qui souffre, et tes yeux sont sur les superbes pour les humilier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Oui, tu as été mon flambeau, Éternel, et l\'Éternel éclaira mes ténèbres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Avec toi j\'affrontai des bataillons, et avec mon Dieu je franchis des murailles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Les voies de Dieu ne sont point trompeuses, et la parole de l\'Éternel est sans alliage. Il est un bouclier pour quiconque le réclame.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Car qui est-ce qui est Dieu hors l\'Éternel? et qui est un rocher sinon notre Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'ce Dieu qui fut ma forte citadelle et guida le juste dans Sa voie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Il assimila mes pieds à ceux de la biche, et Il m\'établit sur mes hauteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Il forma mes mains au combat, et mon bras sut bander l\'arc d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Tu me donnas le bouclier de ton secours, et en m\'exauçant tu m\'agrandis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Sous mes pieds tu donnas de l\'espace à mes pas, et mes talons ne furent point vacillants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Je poursuivis mes ennemis et les anéantis, et je ne revins pas qu\'ils ne fussent détruits;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'je les achevai, et les écrasai, et ils n\'ont pu se relever, ils tombèrent sous mes pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Tu me ceignis de force pour la bataille, et tu fis plier mes adversaires sous moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Tu me fis voir le dos de mes ennemis, et j\'anéantis ceux qui me haïssaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Ils regardèrent autour d\'eux; il n\'y eut point de sauveur, vers l\'Éternel, Il ne leur répondit pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Je les pulvérisai comme la poudre de la terre, comme la boue des rues les foulai, les broyai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Tu me délivras des attaques de mon peuple, et me gardas pour chef des nations; des peuples à moi inconnus me sont asservis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'les enfants de l\'étranger devinrent mes flatteurs; sur ma renommée ils se soumirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Les enfants de l\'étranger sont en décadence, et quittent alarmés leurs châteaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Vive l\'Éternel! béni soit mon rocher! qu\'il soit exalté le Dieu, mon rocher, mon sauveur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'le Dieu qui m\'accorda la vengeance et m\'assujettit les peuples,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'qui me délivra de mes ennemis, m\'éleva au-dessus de mes adversaires et me fit échapper à l\'homme violent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Aussi je veux te chanter parmi les peuples, Éternel, et célébrer ton Nom,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'ô toi, qui accordes un grand salut à ton Roi, et fais miséricorde à ton Oint, à David et à sa race éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Et voici les dernières paroles de David: Prononcé de David, fils d\'Isaï, prononcé de l\'homme élevé au rang d\'Oint du Dieu de Jacob, et du chantre aimable d\'Israël:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'L\'Esprit de l\'Éternel parle par moi, et sa parole est sur mes lèvres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Le Dieu d\'Israël a parlé, le rocher d\'Israël m\'a dit: Parmi les hommes un souverain juste, un souverain qui a la crainte de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'est comme l\'aube matinale: le soleil se lève, le matin est sans nuage; ses rayons qui suivent la rosée font poindre la verdure de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'N\'est-ce pas sur ce pied qu\'est ma maison avec Dieu, qu\'il a fait avec moi une alliance éternelle, en tous points stipulée et gardée? Ne fera-t-Il pas croître et mûrir mon salut tout entier et tous mes vœux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Mais les méchants sont tous comme des ronces à jeter, dans la main personne ne les prend,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'et qui veut les atteindre s\'arme d\'un fer ou du bois d\'une lance, et sur-le-champ elles sont brûlées au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Suivent les noms des capitaines qu\'avait David: Joseb-Bassebeth, de Tahchemon, l\'un des chefs des Triaires; il brandissait sa hampe sur huit cents hommes percés d\'une seule fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Et après lui Éléazar, fils de Dodo, fils d\'Ahohi: c\'était l\'un des trois héros qui accompagnaient David, lorsqu\'ils défièrent les Philistins réunis là pour le combat; et les hommes d\'Israël gagnèrent les hauteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Mais il tint ferme, et il battit les Philistins jusqu\'à ce que sa main fatiguée resta collée à son épée; et en cette journée l\'Éternel opéra une grande victoire. Et le peuple revint sur ses pas pour le suivre, mais seulement pour piller.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Et après lui Samma, fils de Agé, de Harar. Et les Philistins s\'étaient réunis à Léchi; et il y avait là une pièce de terre remplie de lentilles, et le peuple prit la fuite devant les Philistins;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'alors il vint se poster au milieu du champ et le dégagea, et battit les Philistins; et l\'Éternel opéra une grande victoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Et trois des trente chefs descendirent, et vinrent au temps de la moisson joindre David à la grotte d\'Adullam, et un gros de Philistins campait dans la vallée de Rephaïm,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'et David était alors le sommet, et les Philistins avaient alors un poste à Bethléhem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Et David eut une envie et dit: Qui va me chercher de l\'eau à boire à la fontaine de Bethléhem, qui est à la Porte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Alors les trois héros se firent jour à travers le camp des Philistins, et puisèrent de l\'eau à la fontaine de Bethléhem vers la Porte, et ils l\'apportèrent et l\'offrirent à David. Mais il ne voulut pas la boire, et il en fit une libation à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'Et il dit: Ce serait odieux à moi, Éternel, de le faire! Moi [boire] le sang des hommes qui sont allés au péril de leur vie! Et il ne voulut pas la boire. Tel fut l\'exploit des trois héros.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Et Abisaï, frère de Joab, fils de Tseruïa: il était l\'un des chefs des Triaires; et il brandit sa lance sur trois cents morts; et il avait un nom parmi les Triaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Il était bien illustre parmi les Triaires; il était un de leurs chefs; mais il n\'était pas au niveau des trois premiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Et Benaïa, fils de Joïada, fils d\'un brave, grand par ses exploits, de Cabtsel: il abattit deux lions de Dieu de Moab; il fit une descente et abattit un lion dans la citerne un jour de neige.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Et il abattit un Égyptien, homme d\'apparence; et dans la main de l\'Égyptien était une pique; et il fondit sur lui avec le bâton, et arracha la pique de la main de l\'Égyptien, qu\'il tua avec sa propre pique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Tels sont les exploits de Benaïa, fils de Joïada, et il avait un nom entre les trois héros.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Il était honoré par les Triaires; mais il n\'était pas au niveau des trois [premiers]. Et David en fit son conseiller intime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Hasahel, frère de Joab d\'entre les Triaires. El-Hanan, fils de Dodo, de Bethléhem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Samma de Harad. Elika, de Harod,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Hélets, de Palti. Ira, fils de Ikès, de Thékôa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abiézer, d\'Anathoth. Mevunaï, de Husa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Tsalmon, de Hachoach. Mahoraï, de Netopha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Héleb, fils de Baëna, de Netopha. Ithaï, fils de Ribaï, de Gibea en Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benaïa, de Pireathon. Hidaï, de Nahalei-Gaas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abialbon, de Arabah. Azmaveth, le Bahrumite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eliahba, de Saalbon, Beneijasen. Jonathan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Samma, de Harar. Ahiam, fils de Sarar, de Arar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Eliphelet, fils de Ahasbaï, fils de Maachathi. Eliam, fils d\'Achitophel, de Gilo.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hetsraï, le Carmélite. Paëraï, de Arab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jigeal, fils de Nathan, de Tsoba. Bani, de Gad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Tsélec, l\'Ammonite. Naharaï, de Bééroth, écuyer de Joab, fils de Tseruïa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira, de Jéther.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Gareb, de Jéther. Urie le Héthien. En totalité trente-sept.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Et de nouveau la colère de l\'Éternel s\'alluma contre les Israélites et excita David contre eux, en lui suggérant: Va, fais le recensement d\'Israël et de Juda!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Et le Roi dit à Joab, chef de la milice, à côté de lui: Fais donc la tournée de toutes les Tribus d\'Israël de Dan à Béerseba, et passe le peuple en revue pour que j\'en connaisse le chiffre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Et Joab dit au Roi: Que non seulement l\'Éternel, ton Dieu, ajoute au peuple, quelque nombreux qu\'il soit, cent fois autant d\'hommes, mais encore que les yeux de mon Seigneur le Roi en aient le spectacle! cependant pourquoi plaît-il au Roi, mon Seigneur, de prendre cette mesure?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Mais la parole du Roi prévalut sur Joab et sur les chefs militaires; et Joab et les chefs militaires sortirent, de l\'audience du Roi pour passer le peuple d\'Israël en revue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Et ils traversèrent le Jourdain, et ils eurent leur quartier général vers Aroër à droite de la ville sise au milieu du ravin de Gad et dans la direction de Jaëzer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Et ils gagnèrent Galaad et la terre neuve des habitants du Bas; et ils gagnèrent Dan-Jaan et les alentours du côté de Sidon;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'et ils gagnèrent la place forte de Tyr et toutes les villes des Hévites et des Cananéens, et ils pénétrèrent au Midi de Juda vers Béerseba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Ils parcoururent ainsi la totalité du pays, et ils rentrèrent à Jérusalem au bout de neuf mois et vingt jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Alors Joab présenta au Roi le résultat du recensement du peuple, et en Israël il y avait huit cent mille soldats tirant l\'épée, et les hommes de Juda étaient au nombre de cinq cent mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Et David eut des remords en son cœur après qu\'il eut fait le recensement du peuple, et David dit à l\'Éternel: J\'ai péché grandement par cet acte! Et maintenant, Éternel, veuille pardonner la faute de ton serviteur, car j\'ai très follement agi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Et au lever de David le lendemain, la parole de l\'Éternel fut adressée à Gad, le prophète, le Voyant de David, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Va et porte à David ces paroles: Ainsi parle l\'Éternel: Je suspends sur toi trois menaces; choisis-en une, afin que je l\'exécute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Gad se présenta donc chez David et le mit au fait et lui dit: Veux-tu essuyer sept années de famine dans ton pays, ou bien fuir durant trois mois devant tes ennemis et être poursuivi par eux, ou bien avoir trois jours la peste dans ton pays? Maintenant réfléchis et vois quelle réponse je rendrai à Celui qui me délègue!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Alors David dit à Gad: Je suis dans une grande perplexité!... oh! tombons entre les mains de l\'Éternel, car sa miséricorde est immense, mais que je ne tombe pas entre les mains des hommes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Là-dessus l\'Éternel envoya une peste en Israël depuis le matin jusqu\'au terme fixé, et dans le peuple il mourut de Dan à Béerseba soixante-dix mille hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Et comme l\'Ange étendait sa main sur Jérusalem pour la ravager, l\'Éternel eut regret du fléau, et Il dit à l\'Ange qui sévissait parmi le peuple: Assez! à présent ramène ta main! Or l\'Ange de l\'Éternel se trouvait alors près de l\'aire d\'Aravena, le Jébusite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Et David s\'adressa à l\'Éternel, lorsqu\'il vit l\'Ange taillant parmi le peuple, et dit: Voici, j\'ai péché, et c\'est moi qui suis en faute; mais ceux-là, ce troupeau, qu\'ont-ils fait? que ta main fonde donc sur moi et la maison de mon père!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Alors ce jour même, Gad arriva chez David et lui dit: Monte et érige à l\'Éternel un autel sur l\'aire d\'Aravena, le Jébusite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Et David s\'y rendit ensuite de la parole de Gad conforme à l\'ordre de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Et Aravena, qui regardait au dehors, vit le Roi et ses serviteurs se dirigeant vers lui; alors Aravena sortit, et il s\'inclina devant le Roi, le visage contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Et Aravena dit: Dans quel but mon Seigneur le Roi vient-il trouver son serviteur? Et David dit: Dans le but d\'acheter de toi l\'aire pour y bâtir un autel à l\'Éternel, afin d\'arrêter le fléau et d\'en délivrer le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Et Aravena dit à David: Que mon Seigneur le Roi la prenne et fasse le sacrifice qu\'il trouvera bon! vois! l\'attelage servira pour l\'holocauste et les traîneaux et les jougs des taureaux pour le bûcher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'O Roi, Aravena fait don du tout au Roi. Et Aravena dit au Roi: Que l\'Éternel, ton Dieu, te soit propice!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Et le Roi dit à Aravena: Non, car je veux l\'acheter de toi pour un prix, et je ne veux pas offrir à l\'Éternel, mon Dieu, un sacrifice qui ne me coûte rien. David acheta donc l\'aire et les taureaux pour cinquante sicles d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Et David y éleva un autel à l\'Éternel, et offrit des holocaustes et des sacrifices pacifiques, et l\'Éternel se laissa fléchir en faveur du pays, et le fléau fut détourné d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Or David était vieux, avancé en âge, et on le couvrait de vêtements, mais il ne se réchauffait point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Et ses serviteurs lui dirent: Que l\'on cherche à mon Seigneur le Roi une jeune fille, une vierge, pour faire le service du Roi et le soigner et dormir entre ses bras, afin que mon Seigneur se réchauffe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Et l\'on se mit en quête d\'une jeune fille, belle, dans tout le territoire d\'Israël, et l\'on trouva Abisag, de Sunem, et on l\'amena au Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Or la jeune fille était extrêmement belle. Et elle soigna le Roi et le servit, mais il ne la connut point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Cependant Adonia, fils de Haggith, se mit en avant et dit: C\'est moi qui serai Roi! Et il se procura un char et des cavaliers et cinquante hommes pour le précéder comme coureurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Et son père durant toute sa vie ne lui avait jamais fait de la peine en disant: Pourquoi agis-tu ainsi? Et il était aussi très beau de figure, et [sa mère] l\'avait enfanté après Absalom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Et il entra en pourparler avec Joab, fils de Tseruïa, et avec le Prêtre Abiathar qui le suivaient comme auxiliaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Alors le Prêtre Tsadoc, et Benaïa, fils de Joïada, et Nathan, le prophète, et Siméï et Réï et les héros de David ne furent point les partisans d\'Adonia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Et Adonia tua des moutons et des bœufs et des veaux gras près de la pierre Sohéleth qui est à côté de la Fontaine du Foulon, et il convia tous ses frères fils du Roi, et tous les hommes de Juda au service du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Mais il ne convia point Nathan, le prophète, ni Benaïa, ni les héros, ni Salomon, son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Alors Nathan s\'aboucha avec Bathséba, mère de Salomon, et dit: N\'as-tu pas appris l\'avènement d\'Adonia, fils de Haggith, à la royauté? Et notre Seigneur, David, l\'ignore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Eh bien! maintenant reçois de moi un conseil pour mettre en sûreté ta vie et la vie de ton fils Salomon!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Va et entre chez le Roi David et lui dis: N\'as-tu pas, ô Roi, mon Seigneur, fait à ta servante un serment et cette déclaration: Salomon, ton fils, sera Roi après moi, et il s\'assiéra sur mon trône? Pourquoi donc Adonia est-il Roi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Voici, pendant que tu seras encore là en pourparler avec le Roi, moi, j\'entrerai après toi, et je compléterai ton discours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Bathséba entra donc chez le Roi dans l\'appartement. Or le Roi était très vieux, et Abisag, la Sunamite, servait le Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Et Bathséba s\'inclina et se prosterna devant le Roi. Et le Roi dit: Qu\'est-ce qui t\'amène?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Et elle lui dit: Mon Seigneur, tu as fait par l\'Éternel, ton Dieu, à ta servante ce serment: Salomon, ton fils, sera Roi après moi, et c\'est lui qui s\'assiéra sur mon trône;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'et maintenant voilà que Adonia est Roi; et cependant, ô Roi, mon Seigneur, tu l\'ignores. Et il a tué des bœufs et des veaux gras et des moutons en quantité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'et il a convié tous les fils du Roi, et le Prêtre Abiathar et Joab, le chef de l\'armée; mais à Salomon, ton serviteur, il n\'a point adressé d\'invitation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Et sur toi, ô Roi, mon Seigneur, sont fixés les yeux de tout Israël afin que tu déclares qui doit s\'asseoir sur le trône de mon Seigneur le Roi après lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Et il adviendra que, lorsque mon Seigneur le Roi ira reposer avec ses pères, nous serons, moi et mon fils Salomon, traités comme coupables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Et voilà que comme elle parlait encore avec le Roi, Nathan, le prophète, arriva.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Et on l\'annonça au Roi en ces termes: Voici Nathan, le prophète. Et il se présenta devant le Roi, et il se prosterna devant le Roi le visage contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Et Nathan parla: Mon Seigneur le Roi, tu as donc dit: Adonia sera Roi après moi, et c\'est lui qui s\'assiéra sur mon trône!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'car aujourd\'hui il est descendu et a tué des bœufs et des veaux gras et des moutons en quantité, et a convié tous les fils du Roi et les chefs de l\'armée et le Prêtre Abiathar, et les voilà mangeant et buvant devant lui et disant: Vive le Roi Adonia!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Mais à moi qui suis ton serviteur et au Prêtre Tsadoc et à Benaïa, fils de Joïada, et à Salomon, ton serviteur, il n\'a point adressé d\'invitation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Est-ce que ce serait de par mon Seigneur le Roi que telle chose aurait lieu, sans que tu aies notifié à ton serviteur qui doit s\'asseoir sur le trône de mon Seigneur le Roi après lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Alors le Roi David répondit et dit: Mandez-moi Bathséba! Et elle parut devant le Roi et se présenta au Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Et le Roi prononça le serment en ces termes: Par la vie de l\'Éternel qui a délivré mon âme de toutes les détresses!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'ainsi que je te l\'ai juré par l\'Éternel, Dieu d\'Israël, quand j\'ai dit: Salomon, ton fils, sera Roi après moi, et c\'est lui qui me remplacera sur le trône, ainsi veux-je l\'effectuer aujourd\'hui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Alors Bathséba s\'inclina le visage contre terre et se prosterna devant le Roi et dit: Vive mon Seigneur le roi David éternellement!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Et le Roi David dit: Mandez-moi le Prêtre Tsadoc et le prophète Nathan, et Benaïa, fils de Joïada! Et ils se présentèrent au Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Et le Roi leur dit: Prenez avec vous les serviteurs de votre maître, et donnez à mon fils Salomon pour monture mon propre mulet et faites-le descendre à Gihon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Et que l\'onction lui soit conférée là par le Prêtre Tsadoc et le prophète Nathan, pour l\'établir Roi d\'Israël! et sonnez de la trompette et dites: Vive le Roi Salomon!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Et remontez à sa suite, et qu\'il vienne et se place sur mon trône, et c\'est lui qui me succédera dans la royauté, et je l\'ordonne Prince d\'Israël et de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Alors Benaïa, fils de Joïada, répondit au Roi et dit: Ainsi soit-il! Ainsi prononce l\'Éternel, le Dieu de mon Seigneur, du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Que de même que l\'Éternel a été avec mon Seigneur le Roi, de même Il soit avec Salomon, et donne à son trône plus de grandeur qu\'au trône de mon Seigneur le Roi David!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'En conséquence le Prêtre Tsadoc et le prophète Nathan, et Benaïa, fils de Joïada, et les satellites et les coureurs descendirent et placèrent Salomon sur le mulet du Roi David, et le menèrent à Gihon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Et le Prêtre Tsadoc prit la corne d\'huile dans la Tente, et il oignit Salomon, et on sonna de la trompette et tout le peuple dit: Vive le Roi Salomon!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Et tout le peuple monta à sa suite, et tout le peuple formait des concerts de flûtes, et ils se livraient aux transports d\'une grande joie, à faire éclater la terre par leurs acclamations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Et Adonia entendit, et tous les convives avec lui; or ils étaient a la fin du banquet, et Joab distingua le son de la trompette et dit: Pourquoi cette clameur dans la ville en rumeur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Il parlait encore que voici venir Jonathan, fils du Prêtre Abiathar; et Adonia dit: Viens! tu es un brave, et tu nous donneras de bonnes nouvelles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Mais Jonathan répondit et dit à Adonia: Au contraire! notre Seigneur le Roi David a fait Salomon Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Et le Roi a envoyé avec lui le Prêtre Tsadoc et le prophète Nathan et Benaïa, fils de Joïada, et les satellites et les coureurs et ils lui ont donné pour monture le mulet du Roi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'et le Prêtre Tsadoc et le prophète Nathan l\'ont oint comme Roi à Gihon, et de là sont remontés joyeux, et la ville est en rumeur; c\'est le bruit que vous entendez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Et de plus Salomon s\'est assis sur le trône royal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'et de plus les serviteurs du Roi sont entrés pour féliciter notre Seigneur le Roi David en disant: Que ton Dieu rende le nom de Salomon plus beau que le tien, et son trône plus éminent que ton trône!... et le Roi s\'est prosterné sur son lit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'et de plus le Roi a prononcé ces paroles: Béni soit l\'Éternel, Dieu d\'Israël, qui en ce jour m\'a accordé quelqu\'un pour s\'asseoir sur mon trône, et m\'en a rendu témoin!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Alors tous les convives d\'Adonia prirent l\'épouvante et se levèrent et s\'en allèrent chacun de son côté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Mais Adonia eut peur de Salomon, et s\'étant levé il alla saisir les cornes de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Et l\'avis en fut porté à Salomon en ces termes: Voilà qu\'Adonia a peur du Roi Salomon, et voilà qu\'il a saisi les cornes de l\'Autel, disant: Qu\'aujourd\'hui le Roi Salomon me fasse le serment de ne pas mettre à mort son serviteur par l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Alors Salomon dit: S\'il veut être un brave homme, pas un seul de ses cheveux ne tombera en terre; mais s\'il est pris en flagrant délit, il est mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Là-dessus le Roi Salomon envoya des gens pour le faire descendre de l\'Autel, et il se présenta et il se prosterna devant le Roi Salomon et Salomon lui dit: Va dans ta maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Et comme les jours de David avançaient vers la mort, il donna ses instructions à Salomon, son fils, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Je prends le chemin de tout le monde, aie courage et sois homme!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Observe ce que tu dois observer envers l\'Éternel, ton Dieu, en suivant Ses voies et observant Ses statuts et Ses Commandements et Ses règles et Ses Ordonnances, tels qu\'ils sont consignés dans la Loi de Moïse, afin que tu réussisses dans toutes tes entreprises et dans tous tes projets,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'pour que l\'Éternel exécute la promesse qu\'il a prononcée sur moi, lorsqu\'il dit: Si tes fils prennent garde à leur voie pour marcher devant moi fidèlement de tout leur cœur et de toute leur âme, alors, ce sont Ses paroles, alors tu ne manqueras, jamais d\'un homme qui occupe le trône d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Tu sais aussi ce que m\'a fait Joab, fils de Tseruïa, comment il a traité les deux chefs militaires d\'Israël, Abner, fils de Ner, et Amasa, fils de Jéther, qu\'il a égorgés, versant en pleine paix le sang des combats dont il tacha la ceinture qu\'il portait aux reins et la chaussure qu\'il avait aux pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Agis donc selon ta sagesse, et ne laisse pas ses cheveux blancs descendre en paix aux Enfers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Mais marque de la bonté aux fils de Barzillaï, le Galaadite; qu\'ils soient de ceux qui sont nourris de ta table, car c\'est ainsi qu\'ils m\'ont prévenu, lorsque je fuyais devant Absalom, ton frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Et voici, tu as à ta portée Siméï, fils de Géra, le Benjaminite, de Bahurim; c\'est lui qui me maudit d\'une malédiction horrible lorsque je m\'en allais à Mahanaïm; toutefois il descendit à ma rencontre sur le Jourdain, et je lui fis par l\'Éternel ce serment: Je ne te ferai point mourir par l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Mais ne le laisse pas impuni; car tu es un homme sage, et tu sais comment tu dois le traiter, et tu feras descendre sanglants ses cheveux blancs aux Enfers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Ensuite David alla reposer avec ses pères, et il reçut la sépulture dans la Cité de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Et le temps que David régna sur Israël, fut de quarante ans; à Hébron il régna sept ans, et à Jérusalem il régna trente-trois ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Et Salomon s\'assit sur le trône de David, son père, et son empire fut bien affermi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Cependant Adonia, fils de Haggith, entra chez Bathséba, mère de Salomon; et elle dit: Est-ce la paix que tu apportes? Et il répondit: C\'est la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Et il ajouta: J\'ai un mot à te dire. Et elle reprit: Parle!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Et il dit: Tu sais que j\'avais la royauté, et que tout Israël voyait en moi son futur roi; mais il y a eu détournement de la royauté, qui est dévolue à mon frère; car il l\'a de par l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Or maintenant je te fais une demande: ne me rebute pas! Et elle lui dit: Parle!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Et il dit: Veuille dire au Roi Salomon, car il ne te rebutera pas, qu\'il me donne Abisag, la Sunamite, pour femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Et Bathséba dit: Bien! je parlerai en ta faveur au Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Là-dessus Bathséba entra chez le Roi Salomon pour lui parler en faveur d\'Adonia. Et le Roi se levant vint au-devant d\'elle et s\'inclina devant elle, puis il s\'assit sur son trône et l\'on avança un trône pour la mère du Roi, et elle prit place à sa droite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Et elle dit: J\'ai à te faire une petite demande; ne me rebute pas! Et le Roi lui dit: Demande, ô ma mère, je ne te rebuterai pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Et elle dit: Qu\'Abisag, la Sunamite, soit donnée pour femme à ton frère Adonia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Alors le Roi Salomon répondit et dit à sa mère: Pourquoi demandes-tu Abisag, la Sunamite, en faveur d\'Adonia? Demande donc pour lui la royauté, car il est mon frère aîné, pour lui et pour le Prêtre Abiathar, et pour Joab, fils de Tseruïa!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Et le Roi Salomon fit serment par l\'Éternel et dit: Qu\'ainsi Dieu me fasse et pis encore! Il y va de la vie pour Adonia d\'avoir dit ce mot!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Maintenant donc par la vie de l\'Éternel, qui m\'a affermi et placé sur le trône de David, mon père, et qui m\'a créé une maison selon sa promesse, aujourd\'hui même Adonia subira la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Et le Roi Salomon dépêcha Benaïa, fils de Joïada, qui fit main basse sur lui, et il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Et au Prêtre Abiathar le Roi dit: Va-t\'en à Anathoth sur tes terres, car tu es digne de mort; mais en ce jour je ne te ferai pas mourir, parce que tu as porté l\'Arche du Seigneur, l\'Éternel, devant David, mon père, et que tu as souffert de tout ce que mon père a souffert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Et ainsi Salomon destitua Abiathar de sa charge de Prêtre de l\'Éternel, à l\'effet d\'accomplir la menace de l\'Éternel qu\'il avait prononcée sur la maison d\'Héli à Silo.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Et lorsque le bruit en vint à Joab (car Joab avait incliné du côté d\'Adonia, lui qui n\'avait pas incliné du côté d\'Absalom), Joab se réfugia dans la Tente de l\'Éternel, et saisit les cornes de l\'Autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Et le Roi Salomon eut avis de la fuite de Joab dans la Tente de l\'Éternel: « Et voilà qu\'il est près de l\'Autel! » Alors Salomon envoya Benaïa, fils de Joïada, avec cet ordre: Va et fais main basse sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Benaïa vint donc dans la Tente de l\'Éternel, et lui dit: Ainsi parle le Roi: Sors! Et il dit: Non! car ici je mourrai. Et Benaïa rapporta la réponse au Roi et dit: Ainsi a parlé Joab, et ainsi m\'a-t-il répondu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Alors le Roi lui dit: Fais comme il a dit, et frappe le et donne lui la sépulture, et décharge moi, ainsi que la maison de mon père, du sang que Joab a gratuitement versé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Et que l\'Éternel reverse son sang sur sa tête, parce qu\'il a été le meurtrier de deux hommes plus justes et meilleurs que lui, et les a égorgés avec le glaive à l\'insu de David, mon père, Abner, fils de Ner, général d\'Israël, et Amasa, fils de Jéther, général de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Que leur sang retombe sur la tête de Joab et sur la tête de ses descendants à jamais; mais que David et sa race et sa maison et son trône aient le salut en partage à jamais de par l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Ensuite de cela Benaïa, fils de Joïada, monta, et fit main basse sur lui, et le tua; et il reçut la sépulture dans sa demeure au désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Et le Roi lui substitua Benaïa, fils de Joïada, dans le commandement de l\'armée, et le Roi remplaça Abiathar par le Prêtre Tsadoc.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Et le roi envoya mander Siméï et il lui dit: Bâtis-toi une maison à Jérusalem et y demeure, et n\'en sors pas pour aller çà et là!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Le jour où tu sortiras et passeras le torrent de Cédron, sache-le, tu es mort! que ton sang retombe sur ta tête!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Et Siméï dit au Roi: Bonne parole! Ton serviteur se conformera à l\'ordre du Roi, mon Seigneur. Et Siméï resta dans Jérusalem longtemps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Et au bout de trois ans il advint que deux serviteurs de Siméï s\'enfuirent chez Achis, fils de Maacha, Roi de Gath, et l\'avis en fut donné à Siméï en ces termes: Voilà que tes serviteurs sont à Gath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Alors Siméï se mit en mouvement et sella son âne et s\'en alla à Gath chez Achis pour réclamer ses serviteurs; et Siméï fit le voyage et ramena ses serviteurs de Gath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Et Salomon fut informé que Siméï était allé de Jérusalem à Gath et était de retour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Alors le Roi envoya mander Siméï et lui dit: Ne t\'ai-je pas assermenté par l\'Éternel et adjuré en ces termes: Le jour où tu sortiras d\'ici pour aller ça et là, sache-le, tu es mort? Et tu m\'as répondu: Bonne parole! j\'ai entendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Pourquoi donc n\'as-tu pas observé le serment fait devant l\'Éternel et l\'ordre que je t\'avais intimé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Et le Roi dit à Siméï: Tu sais tout le mal dont ton cœur a la conscience et comment tu en as agi envers David, mon père; et l\'Éternel fait retomber ta méchanceté sur ta tête;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'mais le Roi Salomon sera béni, et le trône de David consolidé devant l\'Éternel à jamais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Et le Roi donna ses ordres à Benaïa, fils de Joïada, qui sortit et fit main basse sur Siméï qui mourut. Or la royauté fut affermie dans la main de Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Et Salomon s\'apparenta à Pharaon, Roi d\'Egypte, et il épousa la fille de Pharaon, qu\'il introduisit dans la ville de David, en attendant qu\'il eût achevé la construction de sa maison et de la Maison de l\'Éternel, et du mur d\'enceinte de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Seulement le peuple sacrifiait sur les tertres, parce que jusqu\'à cette époque il n\'avait pas été élevé de Maison au Nom de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Et Salomon aimait l\'Éternel, marchant sur les errements de David, son père; seulement offrait-il sur les tertres les sacrifices et l\'encens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Et le Roi se rendit à Gabaon pour y faire un sacrifice, car c\'était le tertre principal; Salomon offrit mille holocaustes sur cet autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'A Gabaon l\'Éternel apparut à Salomon en songe pendant la nuit, et Dieu dit: Demande ce que je dois te donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Et Salomon dit: Tu as témoigné à ton serviteur David, mon père, un grand amour, comme il marchait devant Toi en vérité et en justice et en droiture de cœur avec Toi, et Tu lui as conservé ce grand amour et lui as accordé un fils qui est assis sur son trône, comme cela est aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Et maintenant Éternel, mon Dieu, tu as fait ton serviteur Roi, successeur de David, mon père, et je ne suis qu\'un jeune adolescent sans expérience pour se conduire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'et ton serviteur se trouve au milieu de ton peuple que tu as élu, peuple considérable qu\'on ne saurait ni mesurer ni compter, tant il est immense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Dote donc ton serviteur d\'un cœur qui sache écouter, à l\'effet de rendre la justice à ton peuple, et d\'avoir le discernement du bien et du mal; car qui est-ce qui serait capable d\'administrer la justice à ton peuple, ce peuple immense?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Et le fait fut agréable aux yeux du Seigneur, que Salomon eût demandé cette chose-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Et Dieu lui dit: Parce que tu as demandé cette chose, et que tu n\'as demandé pour toi ni longue vie, ni richesses, ni mort de tes ennemis, et que tu as demandé pour toi la capacité d\'administrer la justice,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'voici, J\'agirai d\'après tes paroles; voici, Je te donne un cœur sage et intelligent, tel qu\'il n\'y en a pas eu de pareil avant toi et qu\'après toi ne surgira personne qui t\'égale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Et qui plus est, ce que tu n\'as pas demandé, je te le donne, et opulence et honneur, tellement que tu n\'auras pas ton pareil parmi les rois tout le temps de ta vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Et si tu suis mes voies pour garder mes statuts et mes ordonnances, comme l\'a fait David, ton père, je prolongerai tes jours...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Alors Salomon s\'éveilla, et voilà que c\'était un songe. Et il rentra à Jérusalem, et se présenta devant l\'Arche de l\'Alliance de l\'Éternel, et offrit des holocaustes et fit des sacrifices pacifiques, et donna un grand banquet à tous ses serviteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Alors deux prostituées arrivèrent chez le Roi et parurent devant lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Et l\'une des femmes dit: J\'ai recours à toi, mon Seigneur! Moi et cette femme nous habitions le même logis, et j\'accouchai chez elle dans la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Et le troisième jour après mes couches, cette femme accoucha aussi. Et nous étions ensemble et aucune personne étrangère n\'était avec nous dans la maison; il n\'y avait que nous deux dans la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Et le fils de cette femme mourut pendant la nuit, parce qu\'elle s\'était couchée sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Et au milieu de la nuit elle se leva et prit mon fils à mes côtés pendant le sommeil de ta servante, et elle le mit sur son sein, et sur mon sein elle mit son enfant mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Et lorsque le matin je me disposais à allaiter mon enfant, voilà qu\'il était mort! mais l\'ayant regardé attentivement le matin, je vis que ce n\'était pas le fils que j\'avais enfanté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Et l\'autre femme dit: Nullement! c\'est l\'enfant vivant qui est mon fils, et l\'enfant mort est ton fils. Et l\'autre reprit: Nullement! mais ton fils est l\'enfant mort, et mon enfant est celui qui est en vie. Et elles disputaient devant le Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Alors le Roi dit: L\'une dit: C\'est mon fils qui est l\'enfant vivant et ton fils est le mort. Et l\'autre dit: Nullement! mais c\'est ton fils qui est le mort, et le mien qui est le vivant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Et le Roi dit: Allez me chercher une épée! Et l\'on apporta une épée devant le Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Et le Roi dit: Coupez en deux l\'enfant qui vit, et donnez-en une moitié à l\'une, et une moitié à l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Alors la femme dont l\'enfant vivant était le fils, s\'adressant au Roi (car ses entrailles bouillaient pour son enfant) dit: Je t\'en supplie, mon Seigneur! Donnez-lui l\'enfant qui vit, mais ne le faites pas mourir! Et l\'autre femme dit: Qu\'il ne soit ni à moi, ni à toi! coupez-le!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Alors le Roi prit la parole et prononça: Redonnez-lui l\'enfant qui vit! et ne le faites pas mourir! c\'est sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Et tous les Israélites entendirent le jugement rendu par le Roi, et ils conçurent un grand respect pour lui; car ils apercevaient en lui la sagesse de Dieu pour l\'exercice de la justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Ainsi le Roi Salomon était Roi de la totalité d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Or voici quels étaient ses grands dignitaires: Azarias, fils du Prêtre Tsadoc,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elihoreph et Ahija, fils de Sisa, étaient Secrétaires [sous] Josaphat, fils d\'Ahilud, qui était chancelier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'et Benaïa, fils de Joïada, était préposé sur l\'armée, et Tsadoc et Abiathar, Prêtres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'et Azarias, fils de Nathan, Prêtre, était préposé sur les gens d\'office, et Sabud, fils de Nathan, Prêtre, ami du Roi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'et Ahisar était chef de la Maison [du Roi], et Adoniram, fils de Abda, était préposé sur la corvée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Et Salomon avait douze intendants préposés sur tout Israël, et ils fournissaient le Roi et sa Maison; chacun d\'eux avait l\'office de fournisseur un mois par année.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Or voici leurs noms: le fils de Hur sur la montagne d\'Ephraïm,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'le fils de Déquer à Makats et Saalbim et Bethsémès, et Elon et Beth-Hanan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'le fils de Hésed à Aruboth; à lui ressortissait Socho et toute la contrée de Hépber;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'le fils de Abinadab dans tout Naphath Dor (Taphath, fille de Salomon, était sa femme);');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baëna, fils d\'Ahilud à Thaënach et Megiddo, et tout Bethséan, situé près de Tsorthan, au-dessous de Jizréel, de Bethséan à Abel-Mehola jusqu\'au delà de Jockméam;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'le fils de Géber à Ramoth de Galaad: à lui ressortissaient les bourgs de Jaïr, fils de Manassé, en Galaad; à lui ressortissait le cercle d\'Argob en Basan, soixante villes grandes avec murailles et verrous d\'airain;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ahinadab, fils de Iddo, à Mahanaïm;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ahimaats à Naphthali (lui aussi prit Basmath, fille de Salomon, pour femme);');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baëna, fils de Husaï, dans Asser et Bealoth;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Josaphat, fils de Pharuah, dans Issaschar;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Siméï, fils de Ela, dans Benjamin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Géber, fils d\'Uri, dans la région de Galaad, pays de Sihon, Roi des Amorites, et de Og, Roi de Basan; or c\'était un seul intendant pour ce district.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Et Juda et Israël avaient une multitude immense comme le sable sur le bord de la mer; et ils étaient mangeant et buvant et se réjouissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Et Salomon régnait sur tous les royaumes à partir du Fleuve [jusqu\']au pays des Philistins et à la frontière d\'Egypte; ils apportaient des présents, et ils furent, assujettis à Salomon durant toute sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'Et l\'ordinaire quotidien de Salomon était: trente cors de fleur de farine et soixante cors de farine brute,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'dix bœufs engraissés, et vingt bœufs de pâture et cent moutons, non compris les cerfs et gazelles et daims et la volaille grasse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Car il avait sous sa domination tout le pays en deçà du Fleuve, de Thipbsach à Gaza, sur tous les rois en deçà du Fleuve; et il était en paix de toutes parts avec ceux qui lui obéissaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'Et dans Juda et Israël chacun habitait en sûreté sous sa vigne et sous son figuier, de Dan à Béerséba, tant que vécut Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Et Salomon avait quarante mille râteliers pour ses chevaux et chars et douze mille cavaliers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'Et ces intendants fournissaient le Roi Salomon et tous les commensaux du Roi Salomon, chacun pendant son mois; ils ne laissaient rien manquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Et, chacun selon son emploi, ils apportaient et l\'orge et la litière pour les chevaux et les coursiers dans le lieu où il séjournait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Et Dieu dota Salomon de la sagesse et du discernement en très grande mesure, et d\'un esprit étendu comme le sable du rivage de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Et la sagesse de Salomon était plus grande que la sagesse de tous les enfants de l\'Orient et que toute la sagesse de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Et il était plus sage que tous les hommes, que Ethan l\'Esrahite, et Eiman et Chalchol et Darda, fils de Mahol; et il était renommé parmi tous les peuples d\'alentour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Et Salomon prononça trois mille sentences et ses hymnes furent au nombre de mille et cinq.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Et il traita des arbres, depuis le cèdre du Liban à l\'hysope qui croît à la muraille, et il traita des quadrupèdes et des oiseaux et des reptiles et des poissons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'Et de chez tous les peuples on venait écouter la sagesse de Salomon, de la part de tous les Rois de la terre qui entendaient parler de sa sagesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Et Hiram, Roi de Tyr, députa ses serviteurs vers Salomon, car il avait appris qu\'il avait été oint comme Roi à la place de son père; car Hiram avait toujours été l\'ami de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'A son tour Salomon députa vers Hiram pour lui dire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Tu sais que David, mon père, n\'a pu bâtir une maison au Nom de l\'Éternel, son Dieu, à cause des ennemis qui l\'entouraient, jusqu\'à ce que l\'Éternel les eût mis sous la plante de ses pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Or maintenant l\'Éternel, mon Dieu, m\'a mis en paix avec mes alentours; il n\'y a ni adversaire, ni conjoncture fâcheuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Aussi, voici, je pense à bâtir une maison au Nom de l\'Éternel, mon Dieu, aux termes de la déclaration faite par l\'Éternel à David, mon père, quand Il dit: Ton fils que Je placerai sur ton Trône pour te succéder, c\'est lui qui élèvera la maison à Mon Nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Maintenant donc, donne l\'ordre de couper pour moi des cèdres au Liban; et mes serviteurs se joindront à tes serviteurs, et je te remettrai le salaire de tes serviteurs tel que tu l\'indiqueras; car tu sais que chez nous personne ne s\'entend à la coupe des bois comme les Sidoniens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Et lorsque Hiram entendit le message de Salomon, il en eut une grande joie, et il dit: Béni soit l\'Éternel en ce jour de ce qu\'il a donné à David un fils sage comme chef de ce grand peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Et Hiram députa vers Salomon pour lui mander: J\'ai entendu ce que tu m\'as fait dire; de mon côté, j\'accomplirai tout ton désir en fait de bois de cèdre et de bois de cyprès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Mes serviteurs le descendront du Liban à la mer, et j\'en ferai des radeaux qui par mer se porteront au lieu que tu me feras savoir, et là je les disloquerai, et tu les feras prendre. En retour tu accompliras aussi mon désir en fournissant des denrées à ma maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Et Hiram donna à Salomon des bois de cèdre et des bois de cyprès en tout point selon son désir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'De son côté Salomon donna à Hiram vingt mille cors de froment pour l\'entretien de sa maison, et vingt cors d\'huile d\'olives concassées; c\'est ce que Salomon donna à Hiram annuellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Et l\'Éternel dota Salomon de la sagesse selon Sa promesse, et il y eut paix entre Hiram et Salomon, et ils firent alliance l\'un avec l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Et le Roi Salomon commanda une corvée à tout Israël, et pour la corvée il y eut trente mille hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Et il les envoya au Liban, dix mille par mois à tour; ils passaient un mois au Liban, et deux mois chez eux, et Adoniram était préposé sur la corvée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Et Salomon avait soixante-dix mille porte-faix et quatre-vingt mille carriers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'non compris les chefs préposés par Salomon sur l\'ouvrage, au nombre de trois mille trois cents, piqueurs des gens qui faisaient l\'ouvrage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Et le Roi leur ordonna d\'extraire de grandes pierres, des pierres massives, pour asseoir les fondements de la Maison sur pierres équarries.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Et les maçons de Salomon et les maçons de Hiram et les Giblites les taillèrent, et préparèrent le bois et les pierres pour la construction de la Maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Et l\'an quatre cent quatre-vingt après la sortie des enfants d\'Israël hors du pays d\'Egypte, dans la quatrième année, au mois de Ziv (c\'est le second mois), du règne de Salomon sur Israël, il se mit à édifier la Maison en l\'honneur de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Et la Maison que le Roi Salomon bâtit en l\'honneur de l\'Éternel, avait soixante coudées de longueur et vingt coudées de largeur et trente coudées de hauteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Et le Vestibule au front du Temple de la Maison avait vingt coudées dans sa longueur, faisant face à la largeur de l\'édifice, et dix coudées dans sa largeur à partir du front de l\'édifice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Et il ménagea au bâtiment des fenêtres munies de jalousies en barreaux de clôture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Et il flanqua le mur du bâtiment d\'une substruction qui l\'entourait, attenante aux murs de l\'édifice dans leur pourtour, (c\'est-à-dire) du Temple et du Sanctuaire, et y pratiqua des chambres latérales étagées à l\'entour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'L\'étage inférieur avait cinq coudées en largeur, le mitoyen, six coudées en largeur, et le troisième, sept coudées en largeur; car il avait ménagé des saillies au bâtiment tout autour en dehors pour n\'avoir pas à entamer les murs de l\'édifice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Et le bâtiment, lorsqu\'il fut élevé, fut construit de pierres complètement préparées quant à la taille; et ni marteau, ni ciseau, ni outil de fer quelconque ne furent entendus dans l\'édifice durant sa construction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Une porte de l\'étage inférieur se trouvait au côté droit du bâtiment, et par un escalier à vis on montait à l\'étage mitoyen, et de l\'étage mitoyen au troisième.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'C\'est ainsi qu\'il bâtit la Maison et l\'acheva, et il couvrit l\'édifice de pièces de bois en arc et de rangées de cèdres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Et chacun des étages qui entouraient tout l\'édifice, fut élevé à cinq coudées de hauteur et lié au bâtiment par du cèdre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Et la parole de l\'Éternel fut adressée à Salomon en ces termes: Quant à cette Maison que tu construis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'si tu prends mes statuts pour guides, exécutes mes lois et gardes tous mes commandements pour les suivre, je mettrai à effet sur toi la promesse que j\'ai faite à David, ton père,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'et j\'habiterai au milieu des enfants d\'Israël, et n\'abandonnerai point mon peuple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Salomon bâtit donc la Maison et l\'acheva.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Et il construisit en cèdre les parois intérieures de l\'édifice; du sol de l\'édifice jusqu\'aux poutres du plafond, le revêtement intérieur ayant été fait de bois, il revêtit le sol de l\'édifice d\'un parquet de cyprès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Et il recouvrit les vingt coudées à partir du fond de l\'édifice d\'ais de cèdre, du sol aux poutres, et il disposa l\'intérieur en Sanctuaire, en Lieu Très-Saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Et l\'édifice avait quarante coudées, c\'est-à-dire, le Temple devant [le Sanctuaire].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Et le dedans de l\'édifice était pur cèdre, bas-reliefs sculptés en coloquintes et fleurs épanouies, le tout de cèdre; on n\'y voyait pas de pierres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Et au centre de la Maison intérieurement il disposa un Sanctuaire pour y placer l\'Arche de l\'Alliance de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'D\'ailleurs le Sanctuaire avait vingt coudées de longueur et vingt coudées de largeur et vingt coudées de hauteur, et il en fit le revêtement de l\'or le plus pur, et le revêtement de l\'Autel, de bois de cèdre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Et Salomon recouvrit à l\'intérieur la Maison de l\'or le plus pur, et il fit passer au moyen de chaînettes d\'or [le Voile] devant le Sanctuaire, qu\'il avait recouvert d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Et il recouvrit d\'or toute la Maison, la totalité de la Maison dans son entier, et recouvrit d\'or tout l\'Autel qui était devant le Sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Et il fit dans le Sanctuaire deux Chérubins d\'olivier sauvage, ayant dix coudées de hauteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Et l\'une des ailes d\'un Chérubin avait cinq coudées, et la seconde aile d\'un Chérubin avait cinq coudées, dix coudées d\'un bout de ses ailes à l\'autre bout de ses ailes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Et le second Chérubin avait aussi dix coudées: une même mesure et une même taille pour les deux Chérubins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'L\'un des deux Chérubins avait dix coudées de hauteur, et l\'autre de même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Et il plaça les Chérubins au centre de l\'édifice intérieur, et ils avaient les ailes déployées, de telle sorte que l\'aile de l\'un touchait à la paroi, et l\'aile du second à l\'autre paroi, et que leurs ailes se rencontraient bout à bout au centre de l\'édifice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Et il recouvrit d\'or les Chérubins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Et à toutes les parois de la Maison il fit de tous les côtés des ciselures en relief représentant des Chérubins et des palmes et des fleurs épanouies, à l\'intérieur et à l\'extérieur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Et il recouvrit d\'or le sol de l\'édifice, à l\'intérieur et à l\'extérieur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Et il forma la porte du Sanctuaire de battants de bois d\'olivier sauvage et donna à la saillie des jambages le cinquième [de l\'épaisseur de la muraille].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Et sur les deux battants de bois d\'olivier sauvage il cisela en relief des Chérubins et des palmes et des fleurs épanouies, et fit un revêtement d\'or, et il étendit l\'or sur les Chérubins et les palmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Il fit ainsi à la porte du Temple des jambages de bois d\'olivier sauvage ayant le quart [de l\'épaisseur de l\'entrée], et une porte à battants de bois de cyprès,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'l\'un des battants formé de deux ais versatiles, et l\'autre battant formé de deux ais versatiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Et il cisela des Chérubins et des palmes et des fleurs épanouies et les recouvrit d\'or étendu sur la ciselure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Et pour former les parois intérieures il éleva trois rangées de pierres de taille surmontées d\'une rangée de madriers de cèdres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'L\'an quatre fut fondée la Maison de l\'Éternel au mois de Ziv,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'et l\'an onze au mois de Boul (qui est le huitième mois) la Maison fut achevée dans tous ses détails et la totalité de son plan, et l\'on y travailla sept ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Et Salomon mit treize ans a construire son palais qu\'il acheva complètement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'D\'abord il éleva la maison de la Forêt du Liban, longue de cent coudées, large de cinquante, haute de trente, sur quatre rangs de colonnes de cèdre sur lesquelles posaient des poutres de cèdre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'et une couverture de cèdre surmontait les chambres qui reposaient sur les colonnes et dont il y avait quarante-cinq, quinze par galerie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Or il y avait trois étages de planchers, et une triple série de jours à la file l\'un de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Et toutes les portes et les jours étaient formés de poutres en carré, et il y avait trois étages de jours à l\'opposite l\'un de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Il fit aussi la cour de la colonnade, de cinquante coudées dans sa longueur et de trente coudées dans sa largeur, et devant ce portique une cour avec des colonnes et un perron devant celles-ci;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'et il fit la salle du Trône où il rendait la justice, la salle des Jugements avec une boiserie de cèdre d\'un plancher à l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Et son palais où il résidait, dans l\'autre cour, derrière la cour [du Trône] était une construction pareille. Et il bâtit pour la fille de Pharaon, que Salomon avait épousée, un palais pareil à cette cour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Tous ces bâtiments étaient de pierres choisies, taillées d\'après des mesures, sciées avec la scie, et cela à l\'intérieur et à l\'extérieur, des fondements à la crénelure, du devant à la grande cour;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'et ils avaient pour assises des pierres de choix, des pierres de grande dimension, des pierres de dix coudées et des pierres de huit coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Et au-dessus c\'étaient des pierres de choix taillées d\'après des mesures, et du cèdre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Et à l\'entour de la grande cour régnaient trois rangées de pierres de taille et une rangée de poutres de cèdre, ainsi qu\'au Parvis du Temple de l\'Éternel, au Parvis intérieur et touchant au Vestibule du Temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Et par une députation le Roi Salomon fit venir Hiram de Tyr:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'il était fils d\'une veuve de la Tribu de Nephthali, mais son père était un Tyrien, ouvrier en airain; et il était plein d\'habileté, d\'intelligence et de connaissance pour exécuter tous les ouvrages d\'airain; il vint donc chez le Roi Salomon, et il exécuta tous ses ouvrages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Et il modela les deux colonnes d\'airain, dont l\'une avait dix-huit coudées de hauteur, et un cordeau de douze coudées formait la circonférence de la seconde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Et il fit deux chapiteaux pour les poser sur les cimes des colonnes, coulés en airain, cinq coudées étant la hauteur de l\'un et cinq coudées la hauteur de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Des treillis en ouvrage treillissé, des cordons en travail de chaînettes tenaient aux chapiteaux sur les cimes des colonnes, sept à l\'un des chapiteaux et sept à l\'autre chapiteau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Et il fit les grenades, savoir tout autour deux rangs à un treillis pour revêtements des chapiteaux qui étaient à la cime des colonnes; et il en fit autant à l\'autre chapiteau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Et les chapiteaux posés sur la cime des colonnes étaient en façon de lis au Vestibule, ayant quatre coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Et les chapiteaux superposés aux deux colonnes montaient encore plus haut droit au-dessus du bourrelet qui était à l\'envers du treillis, et deux cents grenades en colliers entouraient le second chapiteau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Et il érigea les colonnes pour le Vestibule du Temple, et il érigea la colonne de droite et la nomma Jachin, et il érigea la colonne de gauche et la nomma Boas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Et sur la cime des colonnes il y avait une façon de lis, et ainsi fut achevé le travail des colonnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Et il fit la Mer en fonte, ayant dix coudées de l\'un de ses bords à l\'autre bord, ronde en circonférence, haute de cinq coudées et mesurant trente coudées dans le tour de sa circonférence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Et des coloquintes l\'entouraient au-dessous de son bord tout autour, à raison de dix par coudée en cercle autour de la Mer dans sa circonférence sur deux rangs: les coloquintes furent coulées dans la fonte même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Elle reposait sur douze taureaux, trois regardant vers le Nord, et trois vers l\'Occident, et trois vers le Midi et trois vers le Levant, et la Mer leur était directement superposée, et toutes leurs croupes convergeaient vers le dessous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Et elle avait une palme d\'épaisseur, et son rebord avait la façon d\'un rebord de coupe, en fleur de lis; elle contenait deux mille baths.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Et il fit les dix porte-aiguière d\'airain, chaque porte-aiguière long de quatre coudées et large de quatre coudées et haut de trois coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Et voici quelle était la façon des porte-aiguière: ils avaient des panneaux et les panneaux étaient tenus entre les listels.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Et sur les panneaux tenus entre les listels il y avait des lions, des taureaux et des Chérubins, et sur les listels, aussi bien au-dessus qu\'au-dessous des lions et des taureaux, il y avait des guirlandes en ciselure profonde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Et chaque porte-aiguière avait quatre roues d\'airain munies d\'essieux d\'airain, et ses quatre pieds leur servaient d\'épaulements; les épaulements avaient été coulés sous le bassin vis-à-vis l\'un de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, '(Et l\'orifice du porte-aiguière se trouvait en dedans du chapiteau, puis il y avait une coudée en hauteur; et l\'orifice du chapiteau était arrondi, comme cela se pratique pour de tels meubles, et avait une coudée et demie d\'ouverture, et à l\'orifice il y avait aussi une garniture ciselée.) Or les panneaux [des porte-aiguière] étaient carrés et non pas ronds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Et les quatre roues étaient sous les panneaux, et les épaulements des roues furent fixés au porte-aiguière, et chaque roue avait une coudée et une demi-coudée de hauteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Et la façon des roues était la même que la façon des roues de char; leurs essieux, leurs jantes et leurs rais, et leurs moyeux, le tout avait été coulé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Et quatre épaulements étaient aux quatre angles de chaque porte-aiguière; et de chaque porte-aiguière sortaient ses épaulements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Et le dessus du porte-aiguière s\'élevait d\'une demi-coudée en forme arrondie, et sur [ce] dessus du porte-aiguière était [un bassin], portant ses propres épaulements et ses panneaux qui y tenaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Et sur les plaques de ses épaulements et sur ses panneaux il cisela des Chérubins, des lions et des palmes, selon l\'espace libre qu\'il y avait sur chacun d\'eux, et des guirlandes à l\'entour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'C\'est de cette manière qu\'il fit les dix porte-aiguière; même coulure, même mesure et même coupe pour tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Et il fit dix bassins d\'airain, chaque bassin de la contenance de quarante baths, chaque bassin de quatre coudées, chacun des bassins superposé à un des dix porte-aiguière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Et il plaça les porte-aiguière, cinq au côté droit de l\'édifice, et cinq au côté gauche de l\'édifice; et il plaça la Mer dans la direction du côté droit de l\'édifice vers l\'Orient contre le Midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Et Hiram fit la poterie et les pelles et les jattes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'et Hiram acheva tout l\'ouvrage qu\'il avait entrepris pour le Roi Salomon dans la maison de l\'Éternel; deux colonnes et les bourrelets [et] chapiteaux surmontant les colonnes, au nombre de deux, et les deux treillis pour revêtement des deux bourrelets des chapiteaux superposés aux colonnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'et les quatre cents grenades pour les deux treillis, deux rangées de grenades par treillis pour revêtement des deux bourrelets des chapiteaux superposés aux colonnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'et les dix porte-aiguière et les dix bassins qui reposaient sur les porte-aiguière;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'et la Mer, unique, et les douze taureaux qui étaient sous la Mer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'et la poterie et les pelles et les jattes. Et tous ces meubles que Hiram fit pour le Roi Salomon dans la Maison de l\'Éternel, étaient d\'airain fourbi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Et c\'est dans le Cercle du Jourdain que le Roi les fit couler, au moyen de la terre glaise, entre Succoth et Tsarthan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Et Salomon ne se soucia point de tous les meubles à cause de l\'énorme quantité: on ne s\'enquit point du poids de l\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Et Salomon fit tout le mobilier de la Maison de l\'Éternel, l\'Autel d\'or et la Table d\'or où l\'on posait les pains de présentation,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'et les candélabres, d\'or fin, cinq à droite et cinq à gauche devant le Sanctuaire, et les fleurs et les lampes et les mouchettes d\'or,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'et les bassins et les couteaux et les jattes et les poêles et les pinces d\'or fin, et les gonds aux portes à battants du Temple intérieur donnant sur le Lieu Très-Saint; et les portes à battants de la maison pour entrer au Temple, étaient d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Et ainsi fut achevé tout l\'ouvrage que le Roi Salomon exécuta dans la Maison de l\'Éternel. Et Salomon y fit entrer ce que David, son père, avait consacré; il mit l\'argent et l\'or et les meubles dans les Trésors de la maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Alors Salomon convoqua les Anciens d\'Israël et tous les Chefs des Tribus, Patriarches des enfants d\'Israël, auprès du Roi Salomon à Jérusalem, pour transférer l\'Arche de l\'Alliance de l\'Éternel de la Cité de David, c\'est-à-dire de Sion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Et auprès du Roi Salomon se réunirent tous les hommes d\'Israël, au mois d\'Ethanim, à la Fête (c\'est le septième mois).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Et tous les Anciens d\'Israël arrivèrent et les Prêtres portèrent l\'Arche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'Et ils transférèrent l\'Arche de l\'Éternel et la Tente du Rendez-vous et tous les meubles sacrés qui étaient dans la Tente et qui furent portés par les Prêtres et les Lévites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Et le Roi Salomon et toute l\'Assemblée d\'Israël convoquée auprès de lui se tenait avec lui devant l\'Arche, et l\'on fit un sacrifice de moutons et de taureaux qui ne furent ni comptés, ni nombrés à cause de la quantité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Et les Prêtres amenèrent l\'Arche de l\'Alliance de l\'Éternel à sa place dans le Sanctuaire de la Maison, dans le Lieu Très-Saint, sous les ailes des Chérubins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Car les Chérubins avaient les ailes étendues sur la place de l\'Arche et formaient le dais de l\'Arche et de ses barres, dans le haut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Et l\'on avait donné aux barres de l\'Arche assez de longueur pour que l\'on pût en voir les têtes depuis le Lieu-Saint qui précède le Sanctuaire, mais elles n\'étaient pas visibles à l\'extérieur; et elles y ont été jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Il n\'y avait rien dans l\'Arche que les deux Tables de pierre que Moïse y avait déposées en Horeb, lorsque l\'Éternel traita avec les enfants d\'Israël à leur sortie du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Et il advint que, les Prêtres étant ressortis du Lieu-Saint, la Nuée remplit la Maison de l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'et en présence de la Nuée les Prêtres ne purent demeurer pour officier, car la Gloire de l\'Éternel remplissait la Maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Alors Salomon dit: L\'Éternel a déclaré vouloir, habiter l\'obscurité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Et de mon côté je T\'ai élevé une Maison pour Séjour, un lieu pour ta résidence éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Et le Roi se tournant s\'avança et bénit toute l\'Assemblée d\'Israël, et toute l\'Assemblée d\'Israël était là debout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Et il dit: Béni soit l\'Éternel, Dieu d\'Israël, qui de sa bouche a parlé à David, mon père, et de sa main accomplit, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Depuis le jour où j\'ai retiré Israël, mon peuple, de l\'Egypte, je n\'ai pas choisi de ville dans aucune des Tribus d\'Israël, pour bâtir une Maison où fût mon Nom, et j\'ai fait choix de David pour présider à mon peuple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Et David, mon père, avait à cœur d\'édifier une Maison au Nom de l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Et l\'Éternel dit à David, mon père: Puisque tu avais à cœur d\'édifier une Maison à mon Nom, tu faisais bien de l\'avoir à cœur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'seulement ce n\'est pas toi qui bâtiras la Maison, mais ton fils issu de tes entrailles: c\'est lui qui édifiera la Maison à Mon Nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Et l\'Éternel a mis à effet sa parole, qu\'il a prononcée, et j\'ai succédé à David, mon père, et suis assis sur le Trône d\'Israël, comme l\'Éternel a dit, et j\'ai édifié la Maison au Nom de l\'Éternel, Dieu d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'et j\'y ai donné une place à l\'Arche où est le traité de l\'Alliance conclue par l\'Éternel avec nos pères, lorsqu\'il les retira au pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Et Salomon se plaça devant l\'Autel de l\'Éternel en vue de toute l\'Assemblée d\'Israël, et il étendit ses mains vers le Ciel et il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'Éternel, Dieu d\'Israël, ni là-haut dans les Cieux, ni ici-bas sur la terre, il n\'existe un Dieu tel que toi qui gardes l\'alliance et l\'amour à tes serviteurs qui marchent en ta présence de tout leur cœur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'toi qui as tenu à ton serviteur David, mon père, ce que tu lui avais promis: tu l\'avais dit de ta bouche, et de ta main tu l\'as accompli ce jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Maintenant donc, Éternel, Dieu d\'Israël, tiens à ton serviteur David, mon père, la promesse que tu lui fis en ces termes: Tu n\'auras jamais faute d\'un homme de par Moi pour occuper le Trône d\'Israël, pourvu seulement que tes fils prennent garde à leur voie pour marcher en ma présence, comme tu as marché en ma présence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Maintenant donc, Dieu d\'Israël! oh! qu\'elle se confirme la parole adressée par toi à ton serviteur David, mon père!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Est-ce vraiment que Dieu habiterait sur la terre? Voici, les Cieux et les Cieux des Cieux ne te contiendraient pas; combien moins cette Maison que j\'ai bâtie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Mais tourne ta face vers la prière de ton serviteur et vers son invocation, Éternel, mon Dieu, pour écouter le cri suppliant et la requête qu\'aujourd\'hui porte devant toi ton serviteur en prière,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'pour avoir jour et nuit tes yeux ouverts sur cette Maison, sur le Lieu duquel tu as dit: Mon Nom y sera! pour entendre la prière que ton serviteur adressera pour ce Lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Écoute donc la supplication de ton serviteur et de ton peuple d\'Israël, qui élèveront leur prière pour ce Lieu, écoute-la du lieu où tu résides dans le Ciel; écoute et pardonne!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Si quelqu\'un pèche contre son prochain, et qu\'on lui intime le serment, pour l\'adjurer, et que le serment soit porté devant ton Autel, dans cette Maison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'Toi, écoute des Cieux, et agis et juge tes serviteurs, pour condamner le coupable et mettre sa tête sous le poids de son méfait, et pour absoudre l\'innocent et le traiter à raison de son innocence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Lorsque ton peuple d\'Israël sera battu par l\'ennemi pour avoir péché contre toi, s\'il revient à toi et confesse ton Nom, et t\'adresse ses prières et ses supplications dans cette Maison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'Toi, écoute des Cieux et pardonne le péché de ton peuple d\'Israël et ramène-le au pays que tu as donné à ses pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Quand le Ciel se fermera, et qu\'on sera sans pluie pour avoir péché contre toi, s\'ils élèvent leurs prières vers ce Lieu et confessent ton Nom et reviennent de leur péché parce que tu les humilies,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'Toi, écoute des Cieux et pardonne le péché de tes serviteurs et de ton peuple d\'Israël, parce que tu leur montres la bonne voie qu\'ils ont à suivre, et rends la pluie à ton pays que tu as donné à ton peuple en propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'S\'il y a famine dans le pays, s\'il y a peste, s\'il y a brûlure, nielle, bruches et sauterelles, s\'il y a détresse, l\'ennemi étant dans une de ses villes, s\'il y a fléau, maladie quelconque,...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'toute prière, toute supplication partant d\'un individu quelconque de tout ton peuple d\'Israël, s\'ils comprennent chacun d\'eux le coup dont leur cœur est frappé et étendent leurs mains vers cette Maison, —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Toi, écoute-la des Cieux, ton lieu de résidence, et pardonne, et traite et paie chacun à raison de toute sa conduite, selon la connaissance que tu as de son cœur, car seul tu connais le cœur de tous les enfants des hommes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'afin qu\'ils te craignent tout le temps qu\'ils vivront dans le pays que tu as donné à nos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'L\'étranger aussi qui n\'est point de ton peuple d\'Israël et vient d\'un pays lointain pour l\'amour de ton Nom,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(car ils entendront parler de ton grand Nom et de ta main puissante et de ton bras étendu) et qui arrive et élève ses prières vers cette Maison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Toi, écoute-le des Cieux, ton lieu de résidence, et accomplis tout ce que l\'étranger réclamera de toi, afin que tous les peuples de la terre connaissent ton Nom et te révèrent, comme ton peuple d\'Israël, et sachent que ton Nom a été invoqué sur cette Maison que j\'ai bâtie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Lorsque ton peuple ira en guerre contre son ennemi par la voie où tu l\'auras engagé, et s\'ils prient l\'Éternel tournés vers la Ville que tu as choisie et vers la Maison que j\'ai édifiée à ton Nom,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'écoute des Cieux leur prière et leur supplication, et leur fais droit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 's\'ils pèchent contre toi (car il n\'est pas d\'homme qui ne pèche), et que tu te courrouces contre eux, et que tu les livres à la merci de leur ennemi, et qu\'ils soient emmenés captifs par leurs vainqueurs au pays de l\'ennemi, lointain ou rapproché,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'et si rentrant en eux-mêmes dans le pays où ils seront captifs, ils reviennent à t\'implorer dans le pays de leurs vainqueurs, disant: Nous avons péché, nous avons été pervers et méchants;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'et s\'ils reviennent à toi de tout leur cœur et de toute leur âme dans le pays de leurs ennemis qui les ont emmenés captifs, et qu\'ils t\'invoquent tournés vers leur pays que tu as donné à leurs pères, vers la Ville que tu as choisie et la Maison que j\'ai édifiée à ton Nom,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'alors écoute des Cieux, ton lieu de résidence, leur prière et leur supplication, et leur fais droit');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'et pardonne à ton peuple le péché commis par lui contre toi, et toutes les rébellions dont il sera coupable envers toi et fais-leur obtenir compassion de la part de leurs vainqueurs, afin qu\'ils prennent pitié d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Car ils sont ton peuple et ta propriété, que tu as retirée de l\'Egypte, hors du creuset de fer, —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'afin que tu aies les yeux [et les oreilles] ouvertes à la requête de ton serviteur et à la prière de ton peuple d\'Israël pour les exaucer en tout ce qu\'ils réclameront de toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'car tu les as séparés comme ta propriété de tous les peuples de la terre, ainsi que tu l\'as déclaré par l\'organe de Moïse, ton serviteur, lorsque tu retiras nos pères de l\'Egypte, ô Seigneur, Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Et lorsque Salomon eut achevé d\'adresser à l\'Éternel toute cette prière et cette oraison, il se leva de devant l\'Autel de l\'Éternel où il était agenouillé les mains étendues vers le ciel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'et il s\'avança et bénit toute l\'Assemblée d\'Israël d\'une voix haute et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Béni soit l\'Éternel qui a donné repos à son peuple d\'Israël aux termes de toutes ses promesses! Il n\'a pas laissé tomber un mot de toute l\'excellente parole qu\'il a prononcée par l\'organe de Moïse, son serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Que l\'Éternel, notre Dieu, soit avec nous, comme Il fut avec nos pères, qu\'il ne nous abandonne et ne nous délaisse pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'afin d\'incliner nos cœurs vers Lui pour que nous suivions toutes ses voies et gardions ses commandements et ses statuts et ses lois, qu\'il prescrivit à nos pères!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Et que mes paroles, ces paroles de l\'invocation que j\'ai faite devant l\'Éternel, demeurent jour et nuit près de l\'Éternel, notre Dieu, afin qu\'il fasse droit à son serviteur et droit à son peuple d\'Israël, selon le besoin de chaque jour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'à cet effet que tous les peuples de la terre comprennent que l\'Éternel est Dieu et pas d\'autre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Et que votre cœur soit tout à l\'Éternel, notre Dieu, pour suivre ses statuts et garder ses commandements comme aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Et le Roi et tout Israël avec lui, offrirent des sacrifices devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Et Salomon offrit pour le sacrifice pacifique qu\'il offrait à l\'Éternel, vingt-deux mille taureaux et cent vingt mille moutons, et c\'est ainsi que le Roi et tous les enfants d\'Israël firent la dédicace de la Maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Le même jour le Roi consacra l\'espace du Parvis devant la Maison de l\'Éternel, car c\'est là qu\'il sacrifia l\'holocauste et l\'offrande et les graisses des victimes pacifiques; car l\'Autel d\'airain qui est devant l\'Éternel, était trop petit pour contenir les holocaustes et les offrandes et les graisses des victimes pacifiques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Ainsi, en ce temps Salomon fit la Fête et avec lui tout Israël convoqué en grande assemblée des abords de Hamath au torrent d\'Egypte devant l\'Éternel, notre Dieu, pendant sept jours, puis sept jours, quatorze jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Le huitième jour il licencia le peuple; et ils bénirent le Roi et gagnèrent leurs tentes, joyeux et le cœur content de tout le bien que l\'Éternel avait fait à David, son serviteur, et à Israël, son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Et lorsque Salomon eut terminé la construction de la Maison de l\'Éternel, et du palais royal et de tous les lieux de plaisance de Salomon qu\'il désirait élever,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'l\'Éternel apparut à Salomon une seconde fois, comme Il lui était apparu à Gabaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Et l\'Éternel lui dit: J\'ai ouï ta prière et ta supplication, par laquelle tu m\'as imploré, j\'ai consacré cette Maison que tu as édifiée, afin d\'y mettre mon Nom pour l\'éternité, et mes yeux et mon cœur y seront dans tous les temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Quant à toi, si tu marches en ma présence comme David, ton père, a marché, avec l\'intégrité du cœur et la droiture pour te conformer à tout ce que je t\'ai prescrit, observant mes statuts et mes lois,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'je maintiendrai éternellement le trône de ta royauté sur Israël, ainsi que je l\'ai promis à David, ton père, en ces termes: Tu n\'auras jamais faute d\'un homme pour occuper le trône d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Mais si vous et vos fils vous faites défection contre moi, et ne gardez pas mes commandements, mes statuts que j\'ai mis en face de vous, et si vous vous en allez servir d\'autres dieux et les adorer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'j\'arracherai Israël du sol que je lui ai donné, et, la Maison que j\'ai consacrée à mon Nom, je l\'ôterai de ma présence, et Israël deviendra la fable et l\'objet des sarcasmes de tous les peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Quant à cette Maison, quelle qu\'en soit l\'éminence, quiconque passera près d\'elle, frissonnera et frémira, et l\'on dira: Pourquoi l\'Éternel a-t-Il ainsi traité ce pays et cette Maison?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'et il sera répondu: Parce qu\'ils ont abandonné l\'Éternel, leur Dieu, qui avait retiré leurs pères du pays d\'Egypte, et se sont attachés à d\'autres dieux, qu\'ils ont adorés et servis; c\'est pourquoi l\'Éternel a fait fondre sur eux tout ce désastre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Et au bout de vingt ans, lorsque Salomon eut construit les deux édifices, le Temple de l\'Éternel et le palais royal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, '(Hiram, roi de Tyr, avait fait au Roi l\'avance de bois de cèdre et de cyprès, et d\'or, en tout selon son gré) alors le Roi Salomon céda à Hiram vingt villes au pays de Galilée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Et Hiram partit de Tyr pour examiner les villes que lui donnait Salomon, mais elles ne furent point selon son gré. Et il dit: Qu\'est-ce que ces villes que tu me donnes là, mon frère?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Et il les appela de leur nom d\'aujourd\'hui, pays de Cabul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Et Hiram avait envoyé au Roi cent vingt talents d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Et voici le mode de la corvée dont le Roi Salomon fit la levée pour construire le Temple de l\'Éternel et son palais et la redoute, et le mur de Jérusalem, et Hatsor et Megiddo et Gazer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Pharaon, Roi d\'Egypte, était monté, et s\'était emparé de Gazer, et l\'avait incendiée, et il avait massacré les Cananéens qui habitaient la ville, et il l\'avait donnée en dot à sa fille, femme de Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Et Salomon rebâtit Gazer et Beth-Horon la basse');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'et Baalath et Thadmor au désert dans le pays');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'et toutes les villes d\'approvisionnement appartenant à Salomon, et les villes des chars et les villes de la cavalerie, et les maisons de plaisance de Salomon qu\'il se plut à bâtir à Jérusalem et au Liban, et dans tout le territoire de son royaume.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Toute la population restée des Amoréens, Héthiens, Périzzites, Hévites et Jébusites, ne faisant point partie des enfants d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'c\'est-à-dire leurs descendants restés après eux dans le pays, les enfants d\'Israël n\'ayant pu exécuter sur eux l\'anathème, Salomon les leva comme serfs de corvée, ce qu\'ils sont aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Mais des enfants d\'Israël Salomon ne fit point de serfs; car ils furent ses hommes de guerre et ses officiers et ses généraux, et ses triaires, et les chefs de ses chars et de sa cavalerie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Chefs préposés sur les travaux de Salomon: cinq cent cinquante, commandant la population occupée aux travaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Aussitôt que la fille de Pharaon fut montée de la Cité de David dans la maison qu\'il lui avait bâtie, ce fut alors que Salomon bâtit la redoute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Et trois fois par année Salomon offrait des holocaustes, et des sacrifices pacifiques sur l\'Autel qu\'il avait élevé à l\'Éternel, et il brûlait en personne l\'encens devant l\'Éternel. Il acheva donc la Maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Et le Roi Salomon construisit une flotte à Etseion-Géber, située près d\'Élath, au bord de la Mer aux algues, dans le pays d\'Édom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Et Hiram envoya par un navire ses serviteurs, hommes de mer connaissant la marine, avec les serviteurs de Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Et ils gagnèrent Ophir d\'où ils rapportèrent de l\'or, quatre cent vingt talents qu\'ils présentèrent au Roi Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Et la Reine de Séba, au bruit de la renommée de Salomon, du Nom de l\'Éternel, vint pour l\'éprouver par des problèmes énigmatiques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Et elle fit son entrée à Jérusalem avec très grand train, avec des chameaux portant des aromates et de l\'or en très grande quantité et des pierres précieuses, et elle entra chez Salomon et lui exposa tout ce qu\'elle avait dans la pensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Et Salomon lui résolut toutes ses questions; il n\'y eut pour le Roi rien de trop difficile qu\'il ne pût résoudre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Et comme la Reine de Séba contemplait toute la sagesse de Salomon, et le palais qu\'il avait bâti,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'et les mets de sa table, et les appartements de ses serviteurs, et les loges de ses valets, et leurs costumes, et ses celliers et ses holocaustes qu\'il offrait dans la Maison de l\'Éternel, elle était toute hors d\'haleine, et elle dit au Roi:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Il étaient vrais les rapports que j\'entendais faire dans mon pays de tes dits et faits et de ta sagesse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'et je n\'ajoutais pas foi à ces rapports jusqu\'à ce qu\'étant venue j\'ai vu de mes yeux, et voilà qu\'on ne m\'a pas dit la moitié; tu surpasses en sagesse et en prospérité ta renommée parvenue jusqu\'à moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Heureux ton monde! heureux tes serviteurs que voilà en permanence debout devant toi, auditeurs de ta sagesse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Que béni soit l\'Éternel, ton Dieu, qui t\'a fait la faveur de te placer sur le trône d\'Israël! C\'est parce que le Seigneur a pour Israël un éternel amour qu\'il t\'a établi Roi pour que tu fasses droit et justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Et elle donna au Roi cent vingt talents d\'or et des aromates en immense quantité et des pierres précieuses: il ne vint plus une quantité d\'aromates égale au don que la Reine de Séba fît au Roi Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, '(La flotte d\'Hiram qui rapportait l\'or d\'Ophir, ramenait aussi d\'Ophir du bois de sandal en très grande quantité et des pierres précieuses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Et avec le bois de sandal le Roi Salomon fit une balustrade au Temple de l\'Éternel et au palais royal et des luths et des harpes pour les chantres; il n\'était pas encore venu tant de bois de sandal et jusqu\'aujourd\'hui on n\'en a pas vu au tant.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Et le Roi Salomon donna à la Reine de Séba tout ce qui fut à son gré et qu\'elle demanda, outre les présents qu\'il lui fit à la manière du Roi Salomon. Puis elle s\'en retourna et regagna son pays, elle et sa suite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Et le poids de l\'or qui formait le revenu annuel de Salomon, était de six cent soixante-six talents d\'or,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'non compris ce qu\'il retirait des marchands et du trafic des commerçants, et de tous les rois des étrangers et gouverneurs du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Et le Roi Salomon fit deux cents boucliers d\'or laminé, plaquant chaque bouclier de six cents sicles d\'or,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'et trois cents rondaches d\'or laminé, plaquant chaque rondache de trois mines d\'or; et le Roi les plaça dans la Maison de la Forêt du Liban.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Et le Roi fit un grand trône d\'ivoire et il le recouvrit d\'or affiné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Le trône avait six marches, et le haut du dossier en était arrondi, et au siège étaient les bras d\'un côté et de l\'autre, et deux lions debout à côté des bras,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'et douze lions debout se trouvaient là sur les six marches de part et d\'autre: il n\'en fut fait de pareil en aucun royaume;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'et toutes les coupes du Roi Salomon étaient d\'or et toute la vaisselle de la Maison de la Forêt du Liban était d\'or fin: point d\'argent; au temps de Salomon, on n\'en faisait aucun cas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Car le Roi avait en mer une flotte de Tharsis de conserve avec la flotte d\'Hiram; une fois, en trois ans arrivait la flotte de Tharsis, apportant de l\'or et de l\'argent, de l\'ivoire et des singes et des paons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Et le Roi Salomon devint plus grand que tous les rois de la terre en opulence et en sagesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Et tout le monde recherchait la présence de Salomon pour ouïr sa sagesse, de laquelle Dieu avait doué son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Et chacun apportait son présent, de la vaisselle d\'argent et de la vaisselle d\'or, et des vêtements et des armes et des aromates, des chevaux et des mules, chaque année le contingent de l\'année.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Et Salomon rassembla chars et cavalerie, et il avait mille et quatre cents chars et douze mille cavaliers, dont il établit le dépôt dans les villes des chars et à Jérusalem près du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Et le Roi rendit l\'argent à Jérusalem aussi commun que les pierres, et les cèdres, quant au nombre, que les sycomores qui viennent dans la plaine basse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Et les chevaux qu\'il avait, Salomon les tirait de l\'Egypte, et c\'était à Thékôa que les marchands de Salomon allaient recevoir le convoi contre paiement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Et l\'on amenait et tirait de l\'Egypte un char pour six cents sicles d\'argent, et un cheval pour cent cinquante, et de la même manière on en exportait par leur entremise pour tous les rois des Héthiens et pour tous les rois de la Syrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Et le Roi Salomon aima des femmes étrangères en grand nombre, et d\'abord la fille de Pharaon, puis des Moabites, des Ammonites, des iduméennes, des Sidoniennes, des Héthiennes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'appartenant aux peuples desquels l\'Éternel avait dit aux enfants d\'Israël: Vous n\'entrerez point chez eux, et ils n\'entreront point chez vous; certainement ils tourneront votre cœur du côté de leurs dieux; c\'est à eux que Salomon s\'attacha par l\'amour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Et il avait en femmes sept cents princesses et trois cents concubines; et ses femmes firent dévier son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Et à l\'époque de la vieillesse de Salomon ses femmes tournèrent son cœur du côté d\'autres dieux, et son cœur ne fut pas sans partage avec l\'Éternel, son Dieu, comme le cœur de David, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Et Salomon se mit à la suite d\'Astarté, divinité des Sidoniens, et de Milcom, l\'Abominable des Ammonites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Et Salomon fit ce qui est mal aux yeux de l\'Éternel, et il ne s\'attacha point complètement à l\'Éternel comme David, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Alors Salomon éleva un tertre à Camos, l\'Abominable des Moabites, sur la montagne située devant Jérusalem, et à Moloch, l\'Abominable des Ammonites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Et ainsi fit-il pour toutes ses femmes étrangères qui offraient de l\'encens et des sacrifices à leurs dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Et l\'Éternel se courrouça contre Salomon parce qu\'il avait détourné son cœur de l\'Éternel, Dieu d\'Israël, qui lui était apparu deux fois,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'et lui avait donné sur ce point un ordre exprès en lui défendant de s\'attacher à d\'autres dieux; mais Salomon n\'observa point la défense de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Et l\'Éternel dit à Salomon: Puisque tu t\'es ainsi comporté, et que tu n\'as pas gardé mon alliance et mes statuts que je t\'avais prescrits, je t\'arracherai le royaume et le donnerai à ton serviteur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'cependant je ne le ferai pas de ton vivant, pour l\'amour de David, ton père; c\'est de la main de ton fils que je l\'arracherai;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'seulement ce n\'est pas la totalité du royaume que je détacherai; je laisserai une Tribu à ton fils pour l\'amour de David, mon serviteur, et pour l\'amour de Jérusalem que j\'ai choisie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Et l\'Éternel suscita un adversaire à Salomon, Hadad, l\'Iduméen, de la race royale qui régnait en Edom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Et il arriva, David étant en Idumée, lorsque Joab, général de l\'armée, eut gagné les hauteurs pour donner la sépulture aux morts, que celui-ci massacra tous les mâles de l\'Idumée');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(car Joab y resta six mois avec tous les Israélites jusqu\'à ce qu\'il eût exterminé tous les mâles de l\'Idumée);');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'alors Hadad, ayant avec lui des Iduméens d\'entre les serviteurs de son père, prit la fuite pour gagner l\'Egypte; or Hadad était encore un jeune garçon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Et après être partis de Madian, ils atteignirent Pharan, et de Pharan ils emmenèrent du monde avec eux et ils arrivèrent en Egypte chez Pharaon, roi d\'Egypte, lequel lui donna une demeure, et lui assigna des subsistances et lui concéda des terres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Et Hadad trouva à un haut degré grâce aux yeux de Pharaon, qui lui donna en mariage la sœur de sa femme, la sœur de la reine Thachpenès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Et la sœur de Thachpenès lui enfanta Genubath, son fils; et Thachpenès fit son sevrage au palais de Pharaon, et Genubath fut dans le palais de Pharaon au milieu des fils de Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Et Hadad ayant appris en Egypte que David reposait avec ses pères, et que Joab, général de l\'armée, était mort, Hadad alors dit à Pharaon: Laisse-moi libre de retourner dans mon pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Et Pharaon lui dit: Mais, que te manque-t-il chez moi? Et te voilà cherchant à aller dans ton pays! Et il reprit: Non, mais laisse, laisse-moi partir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'En outre Dieu suscita à Salomon un adversaire dans Rezon, fils d\'Eljada, déserteur d\'Hadadézer, roi de Tsoba, son maître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Et il ramassa auprès de lui des hommes, et devint chef de bande, lorsque David en fit le carnage (des Syriens); et ils se portèrent à Damas, et ils s\'y maintinrent, et dominèrent à Damas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Et il fut un adversaire pour Israël durant toute la vie de Salomon. Et quant au mal que fit Hadad, il harcela Israël et il régna sur la Syrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Et aussi Jéroboam, fils de Nebat, Ephraïmite de Tsérèda (or sa mère, veuve, s\'appelait Tserua), sujet de Salomon, leva la main contre le Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Et voici la cause pour laquelle il leva la main contre le Roi: Salomon construisait la Redoute et fermait la brèche de la Cité de David, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Et le personnage, Jéroboam, était un brave, un homme de ressource, et Salomon voyant dans le jeune homme de l\'aptitude à l\'œuvre, le préposa sur tous les gens de charge de la maison de Joseph...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Et il arriva dans ce temps-là que Jéroboam, étant sorti de Jérusalem, fut rencontré par Ahia, de Silo, le prophète, dans la route; or Ahia portait un manteau neuf, et ils étaient seuls dans la campagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Alors Ahia prit le manteau neuf qu\'il avait sur lui et le déchira en douze morceaux');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'et dit à Jéroboam: Prends pour toi dix morceaux; car ainsi parle l\'Éternel, Dieu d\'Israël: Voici, je vais arracher le royaume de la main de Salomon, et te remettre les dix Tribus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'mais une Tribu lui restera en considération de mon serviteur David et en considération de Jérusalem, la ville que j\'ai choisie dans la totalité des Tribus d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'parce que l\'on m\'a abandonné et que l\'on a adoré Astarté, divinité des Sidoniens, Camos, dieu de Moab, et Milcom, dieu des Ammonites, et que l\'on n\'a pas pratiqué mes voies pour accomplir ce qui est droit à mes yeux, ni mes statuts, ni mes lois, comme David, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Cependant je ne lui arracherai pas de la main la totalité du royaume, mais je lui laisserai sa place de Prince sa vie durant, en considération de David, mon serviteur, que j\'ai choisi et qui a gardé mes commandements et mes statuts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'et j\'arracherai le royaume de la main de son fils, et te donnerai les dix Tribus; quant à son fils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'je lui laisserai une Tribu, afin que mon serviteur David ait dans tous les temps une lampe devant moi à Jérusalem, la ville que je me suis choisie pour y placer mon Nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Et je te prendrai pour que tu règnes sur tout ce qu\'ambitionne ton âme et deviennes roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Et si tu obéis à tout ce que je te commanderai, et pratiques mes voies et fais ce qui est droit à mes yeux, gardant mes statuts et mes commandements, comme l\'a fait David, mon serviteur, alors je serai avec toi et t\'édifierai une maison stable, comme je l\'ai édifiée à David, et je te donnerai Israël');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'et j\'humilierai la race de David à cet effet, seulement pas pour toujours. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Et Salomon cherchait à se défaire de Jéroboam; alors Jéroboam partit, et s\'enfuit en Egypte chez Sisac, roi d\'Egypte, et il fut en Egypte jusqu\'à la mort de Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Et le reste de l\'histoire de Salomon, et tous ses actes et sa sagesse sont consignés dans le livre de l\'histoire de Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Et le temps que Salomon régna à Jérusalem sur tout Israël, fut quarante années.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Et Salomon reposa à côté de ses pères et reçut la sépulture dans la ville de David, son père. Et Roboam, son fils, régna à sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Et Roboam se rendit à Sichem, parce que tout Israël était venu à Sichem pour le faire roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Et lorsque Jéroboam, fils de Nebat, qui se tenait encore en Egypte où il avait fui hors de la présence du Roi Salomon, apprit [la mort de Salomon], il revint d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Alors on députa vers lui pour le mander, et Jéroboam arriva, et toute l\'Assemblée d\'Israël tint à Roboam ce langage:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Ton père nous a chargés d\'un joug onéreux, mais à présent, toi, allège le rigide service de ton père et le joug onéreux qu\'il nous a imposé, et nous serons tes sujets.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Et il leur dit: Retirez-vous pour trois jours encore, puis revenez auprès de moi. Et le peuple se retira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Alors Roboam conféra avec les vieillards qui avaient été au service de Salomon, son père, de son vivant, et il leur dit: Quelle réponse me conseillez-vous de rendre à ce peuple?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Et ils lui parlèrent en ces termes: Si aujourd\'hui tu accordes ce service à ce peuple, et si tu lui cèdes et l\'exauces, et si tu leur adresses des paroles de bonté, ils resteront toujours à ton service.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Mais il négligea le conseil que lui donnaient les vieillards, et il conféra avec les jeunes gens qui avaient grandi avec lui et étaient ses ministres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Et il leur dit: Quelle réponse me conseillez-vous de rendre à ce peuple-là qui me tient ce langage: Allège le joug que ton père nous a imposé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Et les jeunes gens qui avaient grandi avec lui, lui parlèrent en ces termes: Ainsi parle à ce peuple qui t\'a tenu ce langage et t\'a dit: Ton père nous a chargés d\'un joug onéreux, mais toi rends-le plus léger pour nous; ainsi parle-leur: Mon petit doigt est plus épais que la taille de mon père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'si donc mon père vous a fait porter un joug onéreux, moi j\'ajouterai encore à votre joug; si mon père vous a morigénés avec des lanières, moi je vous morigénerai avec des fouets à pointes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Et Jéroboam et tout le peuple se présentèrent à Roboam le troisième jour ensuite des paroles à eux adressées par le Roi: Revenez auprès de moi dans trois jours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'et le Roi répondit au peuple avec dureté, négligeant le conseil des vieillards, qui lui avait été donné par eux, et selon le conseil des jeunes il leur tint ce langage:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Mon père vous a chargés d\'un joug pesant, mais moi j\'y ajouterai encore, mon père vous a morigénés avec des lanières, mais moi je vous morigénerai avec des fouets à pointes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Ainsi le Roi n\'exauça point le peuple; car ce fut une dispensation de l\'Éternel pour la mise à effet de la parole que l\'Éternel avait émise par l\'organe d\'Ahia, de Silo, à Jéroboam, fils de Nebat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Et lorsque tous les Israélites virent que le Roi ne les exauçait pas, le peuple rendit au Roi sa réponse en ces termes: En quoi sommes-nous participants de David? Nous ne sommes point cohéritiers du fils d\'Isaï. A tes tentes, Israël! Désormais pourvois à ta maison, David!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Et les Israélites regagnèrent leurs tentes. Et quant aux Israélites domiciliés dans les villes de Juda, Roboam régna sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Alors le Roi Roboam délégua Adoram, qui était préposé sur la corvée, mais il fut reçu à coups de pierres par tout Israël et il en mourut, et en toute hâte le Roi Roboam monta sur un char pour fuir à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'C\'est ainsi qu\'Israël s\'est détaché de la maison de David jusqu\'à ce jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Et à la nouvelle du retour de Jéroboam tous les Israélites par députation le mandèrent à l\'Assemblée, et ils l\'établirent Roi de tout Israël, et il n\'y eut plus à la suite de la maison de David que la Tribu de Juda seule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Et Roboam rentré à Jérusalem convoqua toute la maison de Juda et la Tribu de Benjamin, cent quatre-vingt mille hommes d\'élite portant les armes, pour attaquer la maison d\'Israël afin de reconquérir le royaume à Roboam, fils de Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Alors la parole de Dieu fut adressée à Semaïa, homme de Dieu, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Parle à Roboam, fils de Salomon, Roi de Juda, et à toute la maison de Juda et de Benjamin et au reste du peuple en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Ainsi parle l\'Éternel: Ne vous mettez point en campagne et n\'attaquez point vos frères, les enfants d\'Israël! rentrez chacun chez vous, car cet événement a lieu de par Moi. Et ils obéirent à la parole de l\'Éternel et ils s\'en retournèrent conformément à la parole de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Et Jéroboam édifia Sichem sur la montagne d\'Éphraïm et il y résida, puis il en sortit et édifia Pnuel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Et Jéroboam disait en son cœur: Maintenant le royaume retournera à la maison de David,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'si ce peuple s\'en va offrir des sacrifices dans la Maison de l\'Éternel à Jérusalem, et le cœur de ce peuple retournera à leur Souverain, à Roboam, Roi de Juda, et ils me feront mourir, et retourneront à Roboam, Roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Alors le Roi se consulta, puis il fit deux veaux d\'or, et il dit au peuple: Vous êtes assez montés à Jérusalem! Israël, voici ton Dieu qui t\'a retiré du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Et il les plaça, l\'un à Béthel, l\'autre à Dan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Et ce fait devint une cause de péché, et le peuple allait en pèlerinage vers l\'un jusqu\'à Dan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Il construisit aussi un temple sur les hauteurs, et créa des prêtres tirés de la masse du peuple et n\'appartenant point à la descendance de Lévi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Et Jéroboam institua une fête au huitième mois, le quinzième jour du mois, comme la fête qui existait en Juda, et il offrit des sacrifices sur l\'autel. Et à Béthel il s\'y prit ainsi: il fit des sacrifices aux veaux qu\'il avait fabriqués, et il établit à Béthel les prêtres des tertres qu\'il avait élevés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'et il monta à l\'autel qu\'il avait érigé à Béthel, le quinzième jour du huitième mois, jour qu\'il avait imaginé en son cœur et auquel il fixa une fête pour les enfants d\'Israël, et il monta à l\'autel pour encenser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Et voilà qu\'un homme de Dieu arriva de Juda à Béthel avec la parole de l\'Éternel, comme Jéroboam était debout à l\'autel pour offrir l\'encens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Et apostrophant l\'autel avec la parole de l\'Éternel il dit: Autel! Autel! ainsi parle l\'Éternel: Voici, il naîtra un fils à la maison de David, Josias sera son nom, et sur toi il immolera les prêtres des hauts lieux, qui sur toi offrent l\'encens, et sur toi l\'on brûlera des ossements humains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Et le même jour il donna un signe et dit: C\'est le signe que l\'Éternel a parlé: voici, l\'autel sera détruit, et la graisse qui y est, se répandra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Et quand le Roi entendit la parole que l\'homme de Dieu adressait à l\'autel, à Béthel, Jéroboam étendit la main de dessus l\'autel en disant: Arrêtez-le! et la main qu\'il étendait contre lui, sécha, et il ne pouvait la ramener à soi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Et l\'autel fut mis en pièces, et la graisse coula de l\'autel conformément au signe qu\'avait donné l\'homme de Dieu par ordre de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Alors le Roi prit la parole et dit à l\'homme de Dieu: Apaise donc l\'Éternel, ton Dieu, et intercède pour moi, afin que je recouvre ma main. Alors l\'homme de Dieu apaisa l\'Éternel, et la main du Roi put être ramenée et elle revint à son premier état.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Et Le Roi parlant à l\'homme de Dieu: Entre avec moi [dit-il] dans la maison pour te restaurer, et je te donnerai un présent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Mais l\'homme de Dieu dit au Roi: Quand tu me donnerais la moitié de ta maison, je n\'entrerais pas avec toi; d\'ailleurs je ne mangerai point de pain et ne boirai point d\'eau en ce lieu-ci,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'car tel est l\'ordre compris dans la parole de Dieu qui m\'a été adressée: Tu ne mangeras point de pain et ne boiras point d\'eau et pour ton retour tu ne prendras pas le chemin par lequel tu seras allé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Puis il partit par un autre chemin, et pour son retour il ne prit point le chemin par lequel il était venu à Béthel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Or à Béthel demeurait un prophète âgé; et son fils vint lui raconter tout ce qu\'avait fait à Béthel ce jour-là l\'homme de Dieu, et les paroles qu\'il avait adressées au Roi; et comme [les fils] faisaient ce récit à leur père,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'celui-ci leur dit: Quel chemin a-t-il pris? Et ses fils s\'assurèrent du chemin pris par l\'homme de Dieu venu de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Et il dit à ses fils: Sellez-moi l\'âne. Et ils lui sellèrent l\'âne, et il le monta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'Et il suivit l\'homme de Dieu et il le trouva assis sous le Térébinthe, et il lui dit: Es-tu l\'homme de Dieu venu de Juda?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Et il répondit: Je le suis. Et il lui dit: Viens avec moi au logis et tu mangeras le pain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Et il répondit: Je ne saurais retourner avec toi, ni entrer avec toi, ni manger du pain, ni boire de l\'eau avec toi dans ce lieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'car dans la parole de l\'Éternel il m\'a été dit: Tu ne mangeras point de pain et ne boiras point d\'eau là, et pour ton retour tu ne prendras pas le chemin par lequel tu seras allé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Et il lui dit: Moi aussi je suis prophète comme toi, et un ange m\'a parlé avec la parole de l\'Éternel, et dit: Ramène-le avec toi dans ta maison, pour qu\'il mange du pain et boive de l\'eau. Il lui mentait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Alors [le prophète de Juda] revint avec lui et mangea du pain dans sa maison et but de l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Et comme ils étaient assis à table, la parole de l\'Éternel fut adressée au prophète qui l\'avait ramené,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'et qui cria à l\'homme de Dieu venu de Juda ces mots: Ainsi parle l\'Éternel: Puisque tu as désobéi à l\'ordre de l\'Éternel et n\'as pas observé le commandement que t\'avait prescrit l\'Éternel, ton Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'et que tu as rebroussé et que tu as mangé du pain et bu de l\'eau dans le lieu duquel Il t\'avait dit: Tu n\'y mangeras point de pain et n\'y boiras point d\'eau; ton cadavre n\'entrera point au tombeau de tes pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Et après avoir mangé le pain et avoir bu, il sella l\'âne au prophète qu\'il avait ramené,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'et qui partit; et il fut rencontré dans la route par un lion qui le tua. Et son cadavre était gisant sur le chemin et l\'âne restait à ses côtés, et le lion restait à côté du cadavre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Et voilà que des gens passèrent et virent le cadavre gisant sur le chemin et le lion qui restait à côté du cadavre, et ils vinrent le redire dans la ville qu\'habitait le vieux prophète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Ce qu\'apprenant, le prophète qui lui avait fait rebrousser chemin, dit: C\'est l\'homme de Dieu qui a désobéi à l\'ordre de l\'Éternel; aussi l\'Éternel l\'a-t-Il livré au lion qui l\'a terrassé et tué selon la parole de l\'Éternel qu\'il lui avait adressée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Et parlant à ses fils il dit: Sellez-moi l\'âne. Et ils le sellèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Puis il se mit en route et il trouva le cadavre gisant sur le chemin, et l\'âne et le lion restés à côté du cadavre: le lion n\'avait ni dévoré le cadavre, ni abattu l\'âne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Alors le prophète leva le cadavre de l\'homme de Dieu et le plaça sur l\'âne et le ramena, et rentra en ville, lui le prophète âgé, pour son deuil et sa sépulture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Et il déposa le cadavre dans son tombeau, et on éleva sur lui la complainte: « Hélas! mon frère. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Et après avoir vaqué à sa sépulture, il parla à ses fils en ces termes: A ma mort vous m\'inhumerez dans le tombeau où l\'homme de Dieu est inhumé, et vous déposerez mes os à côté de ses os.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Car elle aura son effet, la menace qu\'il a proclamée par ordre de l\'Éternel contre l\'autel de Béthel et contre tous les temples des hauteurs qui sont dans les villes de Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Après ce fait Jéroboam ne quitta point sa mauvaise voie, mais de nouveau il créa des prêtres des tertres, tirés de la masse du peuple, et il instituait qui le voulait, pour en faire un prêtre des hauts lieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Et par cette manière d\'agir il devint la cause du péché de la maison de Jéroboam et de sa destruction et de son extermination de la face de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Dans le même temps Abia, fils de Jéroboam, était malade.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Et Jéroboam dit à sa femme: Lève-toi donc et te travestis, de sorte qu\'on ne se doute pas que tu es la femme de Jéroboam, et va-t\'en à Silo! Voici, là est Ahia, le prophète, qui m\'a annoncé que je deviendrais le roi de ce peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Et prends dans ta main dix pains et des gâteaux et une cruche de miel, et entre chez lui: il te révélera ce qui arrivera à l\'enfant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Et ainsi fit la femme de Jéroboam, et s\'étant levée elle se rendit à Silo chez Ahia. Or Ahia avait perdu la vue, car l\'âge rendait ses yeux obtus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Et l\'Éternel avait dit à Ahia: Voici que la femme de Jéroboam vient pour requérir de toi un avis touchant son fils, parce qu\'il est malade: tu lui parleras de telle et telle manière, et quand elle paraîtra, elle ne voudra pas être reconnue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Et lorsque Ahia entendit le bruit de ses pas, comme elle entrait dans la porte, il dit: Entre, femme de Jéroboam! pourquoi donc ne veux-tu pas être connue? Pour moi, j\'ai pour toi un message sévère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Va, dis à Jéroboam: Ainsi parle l\'Éternel, Dieu d\'Israël: Parce que je t\'ai élevé du sein du peuple, et établi prince de mon peuple d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'et que j\'ai détaché le royaume de la maison de David et te l\'ai donné, mais que tu n\'as pas imité mon serviteur David qui a gardé mes commandements et m\'a suivi de tout son cœur pour ne faire que ce qui est droit à mes yeux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'et parce que tu as fait pis que tous tes prédécesseurs, et que tu t\'en es allé et t\'es fait d\'autres dieux et des images de fonte pour me provoquer et que tu m\'as jeté en arrière de toi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'cela étant, voici je vais amener la calamité sur la maison de Jéroboam et j\'arracherai à Jéroboam ceux qui pissent à la muraille, le mineur et l\'émancipé en Israël, et je balaierai après la maison de Jéroboam comme on balaie les ordures, à fond.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Ceux qui mourront à Jéroboam dans la ville, seront mangés par les chiens, et ceux qui mourront dans la campagne, seront mangés par les oiseaux du ciel; car l\'Éternel a parlé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Quant à toi, lève-toi et regagne ta maison! comme tu mettras le pied dans la ville, l\'enfant mourra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Et tout Israël célébrera son deuil et lui donnera la sépulture, car seul de ceux de Jéroboam il recevra la sépulture, parce qu\'il s\'est trouvé en lui pour l\'Éternel, Dieu d\'Israël, quelque chose de bon dans la maison de Jéroboam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Et l\'Éternel se suscitera un roi dans Israël qui extirpera la maison de Jéroboam, née aujourd\'hui et à naître encore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Et l\'Éternel frappera Israël [à le faire branler] comme branle le jonc dans les eaux, et arrachera Israël de ce sol excellent qu\'il avait donné à leurs pères, et les dispersera par delà le Fleuve, parce qu\'ils se sont fait des Astartés, provoquant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Et il livrera Israël pour les péchés de Jéroboam, dont il s\'est rendu coupable et où il a entraîné Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Et la femme de Jéroboam se leva et partit, et gagna Thirtsa; comme elle atteignit le seuil de la maison, l\'enfant mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Et tout Israël lui donna la sépulture et célébra son deuil, selon la parole de l\'Éternel qu\'il avait dite par l\'organe de son serviteur Ahia, le prophète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Le reste des actes de Jéroboam, ses guerres et son règne sont d\'ailleurs consignés dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Et la durée du règne de Jéroboam fut de vingt-deux ans, et il reposa à côté de ses pères, et Nadab, son fils, régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Et Roboam, fils de Salomon, régna sur Juda. Roboam, à son avènement, avait quarante-un ans, et il régna dix-sept ans à Jérusalem, la ville que l\'Éternel avait choisie pour y placer son Nom, de préférence à toutes les Tribus d\'Israël. Or le nom de sa mère était Naama, l\'Ammonite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Et Juda fit ce qui est mal aux yeux de l\'Éternel, et ils L\'irritèrent plus que tout ce qu\'avaient fait leurs pères par les péchés dont ils s\'étaient rendus coupables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Et ils se bâtirent, eux aussi, des tertres et des colonnes et des Astartés et des Aschères sur toute colline éminente et sous tout arbre verdoyant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Il y avait aussi des prostitués dans le pays; ils imitèrent toutes les infamies des nations que l\'Éternel avait chassées devant les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Et la cinquième année du règne de Roboam, il arriva que Sisac, roi d\'Egypte, s\'avança contre Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Et il enleva les Trésors du Temple de l\'Éternel et les trésors du palais royal, et il enleva tout et enleva tous les boucliers d\'or qu\'avait faits Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Et pour les remplacer le roi Roboam fit des boucliers d\'airain et il les commit aux soins des chefs des coureurs qui gardaient la porte du palais du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Et toutes les fois que le Roi venait au temple de l\'Éternel, les coureurs les portaient; puis ils les rapportaient dans la salle des coureurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Or le reste des actes de Roboam et tout ce qu\'il fit, est d\'ailleurs consigné dans le livre des annales des rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Et il y eut toujours guerre entre Roboam et Jéroboam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Et Roboam reposa à côté de ses pères et reçut la sépulture avec ses pères dans la ville de David. Or le nom de sa mère était Naama, l\'Ammonite. Et Abiam, son fils, régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Et la dix-huitième année du roi Jéroboam, fils de Nebat, Abiam devint roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Il régna trois ans à Jérusalem. Or le nom de sa mère était Maacha, fille d\'Abisalom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Et il vécut dans tous les péchés de son père, que celui-ci avait commis avant lui, et son cœur ne fut point sans partage uni à l\'Éternel, son Dieu, comme l\'avait été le cœur de David, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Cependant eu égard à David, l\'Éternel, son Dieu, lui accorda d\'avoir une lampe dans Jérusalem, en élevant son fils après lui et en laissant Jérusalem debout;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'parce que David avait fait ce qui est droit aux yeux de l\'Éternel et ne s\'était point écarté durant toute sa vie de tout ce qu\'il lui commandait, excepté dans l\'affaire d\'Urie, le Héthien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Et il y avait eu guerre entre Roboam et Jéroboam tout le temps de sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Et le reste des actes d\'Abiam et tout ce qu\'il fit, est d\'ailleurs consigné dans le livre des annales des rois de Juda. Et il y eut guerre entre Abiam et Jéroboam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Et Abiam reposa avec ses pères et reçut la sépulture dans la ville de David, et Asa, son fils, régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Et la vingtième année de Jéroboam, roi d\'Israël, Asa devint roi de Juda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'et il régna quarante-un ans à Jérusalem. Or le nom de sa mère était Maacha, fille d\'Abisalom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Et Asa fit ce qui est bien aux yeux de l\'Éternel, comme David, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Et il expulsa les prostitués du pays et fit disparaître toutes les idoles qu\'avaient faites ses pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Et même Maacha, sa mère, il la destitua de son rang de Reine parce qu\'elle s\'était fait un simulacre d\'Astarté, et Asa abattit son simulacre et le brûla dans le ravin du Cédron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Cependant les tertres ne disparurent pas; seulement le cœur d\'Asa resta-t-il tout entier uni à l\'Éternel toute sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Et il transféra dans le Temple de l\'Éternel les objets consacrés par son père et par lui-même, l\'argent, l\'or et la vaisselle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Or il y eut guerre entre Asa et Baësa, roi d\'Israël, durant toute leur vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Et Baësa, roi d\'Israël, s\'avança sur Juda et bâtit Rama pour empêcher que personne sortît ou entrât dans l\'intérêt d\'Asa, roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Alors Asa prit tout l\'argent et l\'or qui restait dans les Trésors du Temple de l\'Éternel et les trésors du palais royal, et les mit entre les mains de ses serviteurs, et le roi Asa les envoya à Ben-Hadad, fils de Tabrimmon, fils de Hézion, roi de Syrie, résidant à Damas, avec ce message:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Il existe une alliance entre moi et toi, entre mon père et ton père; voici, je t\'envoie un présent d\'argent et d\'or: eh bien! romps ton alliance avec Baësa, roi d\'Israël, afin qu\'il se retire de chez moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Et Ben-Hadad écouta le roi Asa, et il expédia ses généraux d\'armée contre les villes d\'Israël, et réduisit Ijon et Dan et Abel-Beth-Maacha et tout le Kinnereth dans tout le territoire de Nephthali.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Et à cette nouvelle Baësa renonça à l\'édification de Rama, et il resta à Thirtsa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Et le roi Asa convoqua la totalité de Juda sans exempter personne, et ils emportèrent de Rama les pierres et le bois employé par Baësa à sa bâtisse et le roi Asa s\'en servit pour édifier Géba en Benjamin et Mitspa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Et le reste de tous les actes d\'Asa, et tous ses exploits, et toutes ses entreprises, et les villes qu\'il bâtit, tout cela est consigné dans le livre des annales des rois de Juda. Seulement dans ses vieux jours il eut les pieds malades.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Et Asa reposa avec ses pères et reçut la sépulture avec ses pères dans la ville de David, son père, et Josaphat, son fils, régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Or Nadab, fils de Jéroboam, devint roi d\'Israël, la seconde année d\'Asa, roi de Juda, et régna deux ans sur Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Et il fit ce qui est mal aux yeux de l\'Éternel, et marcha dans la voie de son père et dans son péché où il avait entraîné Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Et Baësa, fils d\'Ahia, de la maison d\'Issaschar, conspira contre lui, et Baësa le fit tomber sous ses coups devant Gibbethon, qui est aux Philistins, pendant que Nadab et tout Israël assiégeaient Gibbethon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Ainsi Baësa lui donna la mort la troisième année d\'Asa, roi de Juda, et prit sa place comme roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Et devenu roi il extermina toute la maison de Jéroboam, sans laisser survivre de Jéroboam rien qui eût vie jusqu\'à ce qu\'il eût tout détruit selon la parole de l\'Éternel prononcée par l\'organe de son serviteur Ahia, de Silo,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'à cause des péchés de Jéroboam qu\'il avait commis et où il avait entraîné Israël par sa provocation dont il avait provoqué l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Or le reste des actes de Nadab, et toutes ses entreprises, cela est d\'ailleurs consigné dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Et il y eut guerre entre Asa et Baësa, roi d\'Israël, durant toute leur vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'La troisième année d\'Asa, roi de Juda, Baësa, fils d\'Ahia, devint roi de tout Israël à Thirtsa et [régna] vingt-quatre ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Et il fit ce qui est mal aux yeux de l\'Éternel et marcha dans la voie de Jéroboam et son péché où il avait entraîné Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Et la parole de l\'Éternel fut adressée à Jéhu, fils de Hanani, contre Baësa en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Parce que je t\'ai fait surgir de la poussière, et établi prince de mon peuple d\'Israël, et que tu as marché sur les errements de Jéroboam et entraîné à pécher mon peuple d\'Israël pour me provoquer par leurs péchés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'voici je vais ravager après Baësa et sa maison et réduire ta maison à l\'état de la maison de Jéroboam, fils de Nebat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Ceux qui mourront à Baësa dans la ville seront dévorés par les chiens et ceux qui lui mourront aux champs, dévorés par les oiseaux du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Et le reste des actes de Baësa, et ses entreprises et ses exploits sont d\'ailleurs consignés dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Et Baësa reposa à côté de ses pères et reçut la sépulture à Thirtsa, et Éla, son fils, régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Et par l\'organe de Jéhu, fils de Hanani, le prophète, la parole de l\'Éternel fut donc aussi prononcée contre Baësa et contre sa maison et à cause de tout le mal qu\'il avait fait à la face de l\'Éternel, Le provoquant par l\'ouvrage de ses mains, et étant comme la maison de Jéroboam, et aussi parce qu\'il lui avait porté ses coups.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'La vingt-sixième année d\'Asa, roi de Juda, Éla, fils de Baësa, devint roi d\'Israël à Thirtsa, pour deux ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Et contre lui conspira son serviteur Zimri, chef de la demi-division des chars. Et comme il était à s\'enivrer à Thirtsa dans la maison d\'Artsa, préfet du palais,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Zimri s\'introduisit et l\'assassina et lui donna la mort la vingt-septième année d\'Asa, roi de Juda, et régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Et quand il fut roi et fut assis sur son trône, il fit main basse sur toute la maison de Baësa, sans laisser la vie à aucun des siens, soit [enfants] pissant à la muraille, soit proche, soit ami.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Ainsi Zimri anéantit toute la maison de Baësa, selon la menace de l\'Éternel qu\'il avait prononcée contre Baësa par l\'organe de Jéhu, le prophète,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'à cause de tous les péchés de Baësa et des péchés d\'Éla, son fils, dont ils se rendirent coupables et où ils entraînèrent les Israélites, qui provoquèrent l\'Éternel, Dieu d\'Israël, par leurs vaines idoles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Le reste des actes d\'Éla et toutes ses entreprises sont d\'ailleurs consignés dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'La vingt-septième année d\'Asa, roi de Juda, Zimri devint roi, pour sept jours, à Thirtsa. Or le peuple campait cernant Gibbethon, qui est aux Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Et le peuple campé entendit cette nouvelle: Zimri a conspiré, et a même tué le roi; et tous les Israélites ce jour-là dans le camp constituèrent roi d\'Israël Omri, général de l\'armée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Alors Omri accompagné de tous les Israélites, partit de Gibbethon, et ils vinrent assiéger Thirtsa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Et Zimri voyant que la ville était prise, se retira dans le donjon du palais royal et il mit le feu sur lui au palais royal qu\'il brûla,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'et il périt ensuite de ses péchés qu\'il avait commis en faisant ce qui est mal aux yeux de l\'Éternel, en marchant sur les errements de Jéroboam et dans son péché qu\'il avait commis pour entraîner Israël au péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Le reste des actes de Zimri, et sa conspiration qu\'il ourdit, est d\'ailleurs consigné dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Alors le peuple d\'Israël se divisa en deux partis: une moitié du peuple suivit Thibni, fils de Ginath, dans le but de lui donner la royauté; et l\'autre moitié suivit Omri;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'mais le peuple qui suivait Omri, l\'emportait sur le peuple qui suivait Thibni, fils de Ginath, et Thibni mourut et Omri régna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'La trente-unième année d\'Asa, roi de Juda, Omri devint roi d\'Israël, pour douze ans, dont il régna six à Thirtsa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Et il acheta le mont de Samarie de Semer pour deux talents d\'argent, et il y éleva des bâtiments, et il nomma la ville qu\'il avait bâtie, Samarie du nom de Semer, seigneur du mont.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Et Omri fit ce qui est mal aux yeux de l\'Éternel et fut pire que tous ses prédécesseurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Et il marcha en tout sur les errements de Jéroboam, fils de Nebat, et dans ses péchés où il avait entraîné Israël qui provoqua l\'Éternel, Dieu d\'Israël, par ses vaines idoles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Le reste des actes d\'Omri et ses entreprises, et les exploits qu\'il exécuta, sont d\'ailleurs consignés dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Et Omri reposa à côté de ses pères et il reçut la sépulture à Samarie. Et Achab, son fils, régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Or Achab, fils d\'Omri, devint roi d\'Israël, la trente-huitième année d\'Asa, roi de Juda, et Achab, fils d\'Omri, régna sur Israël à Samarie vingt-deux ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Et Achab, fils d\'Omri, fit ce qui est mal aux yeux de l\'Éternel plus que tous ses prédécesseurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Et (était-ce trop peu pour lui de marcher sur les errements de Jéroboam, fils de Nebat?) il prit pour femme Jézabel, fille d\'Ethbaal, roi de Sidon, et il s\'en alla servir Baal et l\'adorer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Et il érigea un autel à Baal dans le temple de Baal qu\'il avait bâti à Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Et Achab fit une Astarté, et Achab fit davantage encore pour provoquer l\'Éternel, Dieu d\'Israël, plus que tous les rois d\'Israël, ses prédécesseurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'De son temps, Hiel, de Béthel, édifia Jéricho. Il en posa les fondements au prix d\'Abiram, son premier-né; et au prix de Serub, son cadet, il en éleva les portes selon la parole que l\'Éternel avait prononcée par l\'organe de Josué, fils de Nun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Et Élie, de Thisbé, l\'un des domiciliés de Galaad, dit à Achab: Par la vie de l\'Éternel, Dieu d\'Israël, aux ordres de qui je suis, il n y aura durant ces années-ni rosée, ni pluie, sinon à ma voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Et la parole de l\'Éternel lui fut adressée en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Va-t\'en d\'ici et dirige-toi vers l\'Orient, et cache-toi dans le ravin du Krith qui est en face du Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Et le torrent te fournira ton breuvage, et j\'ai commandé aux corbeaux de t\'y nourrir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Et Élie partit et se conforma à la parole de l\'Éternel, et il alla s\'établir dans le ravin du Krith qui est en face du Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Et les corbeaux lui apportaient du pain et de la viande le matin, et du pain et de la viande le soir, et l\'eau du torrent était son breuvage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Et après un certain temps le torrent fut à sec; car il ne pleuvait point dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Alors la parole de l\'Éternel lui fut adressée en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Lève-toi et t\'en va à Tsarpath qui tient à Sidon, et t\'y établis: voici, j\'y ai donné ordre à une femme veuve de te nourrir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Et Élie se leva et gagna Tsarpath; et il arriva à l\'entrée de la ville, et voici que là était une femme veuve qui ramassait des brins de bois. Et s\'adressant à elle il dit: Veuille me chercher un peu d\'eau dans la cruche pour que j\'aie à boire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Et elle alla en chercher. Et s\'adressant à elle il dit: Veuille prendre en ta main une bouchée de pain pour moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Et elle dit: Par la vie de l\'Éternel, ton Dieu, je n\'ai pas une galette, je n\'ai qu\'une poignée de farine dans la caisse, et une goutte d\'huile dans la jarre, et me voici ramassant une couple de brins de bois, et rentrée avec cela je préparerai à manger pour moi et mon fils, puis nous mourrons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Et Élie lui dit: Sois sans crainte, rentre, fais comme tu as dit, seulement commence par en préparer pour moi une petite galette que tu m\'apporteras dehors et après cela tu prépareras pour toi et ton fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Car ainsi parle l\'Éternel, Dieu d\'Israël: La caisse de la farine ne s\'épuisera pas et la jarre d\'huile ne fera pas défaut, jusqu\'au jour où l\'Éternel accordera de la pluie à la face de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Et elle s\'en alla et exécuta ce qu\'avait dit Élie; et elle prit son repas, elle, lui et toute sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'A partir de ce jour la caisse de la farine ne s\'épuisa pas et la jarre d\'huile ne fit pas défaut, selon la parole de l\'Éternel prononcée par l\'organe d\'Élie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Et sur ces entrefaites, le fils de la femme, maîtresse de la maison, tomba malade, et sa maladie était très intense, au point qu\'il ne lui restait plus un souffle de vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Alors elle dit à Élie: Que peut-il y avoir entre moi et toi, homme de Dieu? Es-tu venu chez moi pour rappeler la mémoire de ma faute, et faire mourir mon fils?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Et il lui dit: Confie-moi ton fils. Et il le prit d\'entre ses bras et le porta dans la chambre supérieure où il logeait, et il le coucha sur son lit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Et il implora l\'Éternel et dit: Éternel, mon Dieu, est-ce que même cette veuve chez qui je trouve l\'hospitalité, tu veux l\'affliger en faisant mourir son fils?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Puis il s\'étendit sur l\'enfant par trois fois et implora l\'Éternel en disant: Éternel, mon Dieu, oh! que l\'âme de cet enfant revienne au dedans de lui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Et l\'Éternel écouta la voix d\'Élie et l\'âme de l\'enfant revint au dedans de lui et il reprit vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Alors Élie prit l\'enfant et le descendit de l\'étage supérieur dans l\'habitation, et le rendit à sa mère en disant: Vois! ton fils est vivant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Et la femme dit à Élie: Maintenant je reconnais que tu es un homme de Dieu et que la parole de l\'Éternel dans ta bouche est vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Et longtemps après, la parole de l\'Éternel fut adressée à Élie, la troisième année, en ces termes: Va et te présente à Achab, puis je laisserai la pluie descendre sur la face de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Alors Élie alla se présenter à Achab. Or la famine était extrême dans Samarie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'et Achab manda Obadia, préfet du palais (or Obadia avait une très grande crainte de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'et lorsque Jézabel extermina les prophètes de l\'Éternel, Obadia recueillit cent prophètes et les cacha, cinquante hommes par grotte, et les fournit de pain et d\'eau);');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'et Achab dit à Obadia: Va dans le pays à toutes les sources et à tous les courants d\'eau, peut-être se trouvera-t-il quelque herbe pour faire vivre nos chevaux et nos mulets, et n\'avoir pas à nous défaire d\'une partie du bétail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Et ils se distribuèrent entre eux le pays pour le parcourir; Achab s\'achemina par une voie seul, et Obadia s\'achemina par l\'autre voie, seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Et comme Obadia était en route, voilà qu\'Élie le rencontra; et le reconnaissant, Obadia se jeta la face contre terre et dit: Est-ce toi, mon seigneur Élie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Et il lui répondit: Moi-même. Va, dis à ton maître: Voici Élie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Et il dit: En quoi ai-je péché que tu veuilles livrer ton serviteur aux mains d\'Achab pour qu\'il me fasse mourir?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Par la vie de l\'Éternel, ton Dieu, il n\'est ni peuple, ni royaume où mon maître ne t\'ait envoyé chercher, et quand on disait: Il n\'est pas ici, le roi faisait jurer au royaume et au peuple qu\'on ne te trouvait pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Et maintenant tu dis: Va, dis à ton maître: Voici Élie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'et si je te quitte et que l\'Esprit de l\'Éternel te transporte j\'ignore où, et que je vienne donner l\'avis à Achab, et qu\'il ne te trouve pas, alors il me fera mourir, et pourtant ton serviteur a craint l\'Éternel dès sa jeunesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Mon seigneur n\'a-t-il pas été informé de ce que j\'ai fait lorsque Jézabel massacra les prophètes de l\'Éternel, que je cachai cent hommes d\'entre les prophètes de l\'Éternel, cinquante par grotte, et les fournis de pain et d\'eau?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Et maintenant tu dis: Va, dis à ton maître: Voici Élie! Il me fera mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Mais Élie dit: Par la vie de l\'Éternel des armées, aux ordres de qui je me tiens, aujourd\'hui je me présenterai à lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Alors Obadia alla au-devant d\'Achab et lui fit rapport. Et Achab vint au-devant d\'Élie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Et à la vue d\'Élie, Achab lui dit: Est-ce toi, perturbateur d\'Israël?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Et il répondit: Je ne suis point le perturbateur d\'Israël, c\'est toi au contraire et la maison de ton père, en désertant les commandements de l\'Éternel, et quand tu as pris ton chemin après les Baals.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Maintenant donc dépêche et convoque devant moi tout Israël au mont Carmel et les quatre cent cinquante prophètes de Baal et les quatre cents prophètes d\'Astarté qui mangent à la table de Jézabel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Et Achab dépêcha chez tous les enfants d\'Israël et convoqua les prophètes au mont Carmel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Alors Élie s\'avança vers le peuple entier et dit: Jusques à quand boiterez-vous sur les deux jarrets? Si l\'Éternel est Dieu, suivez-le! Si c\'est Baal, suivez-le. Et le peuple ne lui répondit mot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Et Élie dit au peuple: Je suis resté seul prophète de l\'Éternel, et de prophètes de Baal il y a quatre cent cinquante hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Qu\'on nous procure deux taureaux, ils en choisiront l\'un pour eux, puis le dépèceront et le placeront sur le bûcher, mais sans y mettre le feu; moi j\'immolerai l\'autre taureau et le placerai sur le bûcher, mais sans y mettre le feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Ensuite invoquez le nom de votre dieu et moi j\'invoquerai le nom de l\'Éternel, et que le dieu qui répondra par le feu, que celui-là soit Dieu! Et le peuple entier répondit: Bien parlé!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Et Élie dit aux prophètes de Baal: Choisissez pour vous l\'un des taureaux, et sacrifiez les premiers, car vous faites nombre, et invoquez le nom de votre dieu; mais ne mettez pas le feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Et ils prirent le taureau laissé à leur choix, et l\'immolèrent et invoquèrent le nom de Baal du matin à midi, en disant: Baal, réponds-nous! Mais pas un son, et personne qui réponde. Et ils marchaient en se balançant autour de l\'autel qu\'on avait élevé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Et à midi Élie les railla et dit: Invoquez à voix forte, car c\'est un dieu; il est sans doute préoccupé; il est allé à l\'écart; sans doute il est en voyage; peut-être sommeille-t-il; alors il se réveillera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Et ils invoquèrent à voix forte, et ils se firent des incisions selon leur rite avec des poignards et avec des piques jusqu\'à faire effusion de leur sang sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Et quand midi fut passé, ils furent en frénésie jusqu\'à l\'oblation de l\'offrande; mais pas un son et personne qui répondît et personne qui écoutât.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Alors Élie s\'adressa à tout le peuple: Approchez-vous de moi! Et le peuple entier s\'approcha de lui; et il remit en état l\'autel de l\'Éternel, démoli.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Et Élie prit douze pierres d\'après le nombre des Tribus des fils de Jacob, à qui la parole de l\'Éternel avait été adressée en ces termes: Israël sera ton nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'et avec les pierres il construisit un autel au Nom de l\'Éternel, et il pratiqua autour de l\'autel une rigole de la dimension de deux émines de grain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'et il arrangea le bûcher, et il dépeça le taureau et il le plaça sur le bûcher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Et il dit: Remplissez quatre brocs d\'eau, que vous verserez sur l\'holocauste et sur le bûcher. Puis il dit: Réitérez! Et ils réitérèrent. Puis il dit: Faites-le une troisième fois. Et ils le firent pour la troisième fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Et l\'eau circula autour de l\'autel et l\'on remplit aussi d\'eau la rigole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Et au moment de l\'oblation de l\'offrande, Élie, le prophète, s\'avança et dit: Éternel, Dieu d\'Abraham, d\'Isaac et d\'Israël, qu\'il soit notoire aujourd\'hui que tu es Dieu en Israël et que je suis ton serviteur et que c\'est par ton ordre que j\'ai fait toutes ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Réponds-moi, Éternel, réponds-moi, afin que ce peuple reconnaisse que tu es l\'Éternel, le Dieu, et que c\'est toi qui, derrière eux, convertissais leur cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Alors le feu de l\'Éternel descendit et consuma l\'holocauste et le bûcher et les pierres et la terre, et il absorba aussi l\'eau dans la rigole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Et à ce spectacle le peuple entier se jeta la face contre terre en disant: C\'est l\'Éternel qui est Dieu, l\'Éternel qui est Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Et Élie leur dit: Arrêtez les prophètes de Baal! que pas un d\'eux n\'échappe! Et ils les arrêtèrent et Élie les fit descendre dans le ravin du Kison et là il les immola.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Et Élie dit à Achab: Remonte, mange et bois! car j\'entends le bruissement de la pluie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Alors Achab remonta pour manger et boire. Et Élie gagna le sommet du Carmel, et il se prosterna contre terre, et mit son visage entre ses genoux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Et il dit à son valet: Monte donc et regarde dans la direction de la mer. Et il monta, et regarda et dit: Il n\'y a rien. Et Élie dit: Répète sept fois la course.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Et à la septième il dit: Voilà un petit nuage, comme la paume de la main d\'un homme, qui surgit de la mer. Alors Élie dit: Monte et dis à Achab: Attelle et descends, afin que la pluie ne t\'arrête pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Et en un tour de main le ciel s\'obscurcit, il y eut nuages et vent, puis une forte pluie, et Achab monta sur son char et gagna Jizréel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Et la main de l\'Éternel poussa Élie, qui ceignit ses reins et courut en devançant Achab jusqu\'à Jizréel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Et Achab raconta à Jézabel tout ce qu\'avait accompli Élie, et tout le carnage qu\'il avait fait de tous les prophètes avec l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Alors Jézabel envoya un messager vers Élie pour lui dire: Que les dieux me fassent ceci et pis encore, si demain je ne fais de ta personne ce que tu as fait de la personne de chacun d\'eux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Et voyant cela il se leva et partit pour sauver sa vie, et il gagna Béerséba, qui est à Juda, et il y laissa son valet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Quant à lui, il s\'en alla dans le désert à une journée de marche, et arrivé il s\'assit sous un genêt. Et il demandait la mort et disait: C\'en est assez! Maintenant, Éternel, reprends-moi mon âme, car je ne suis pas supérieur à mes pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Et il se coucha et s\'endormit sous un genêt. Et voilà qu\'un ange le toucha et lui dit: Lève-toi! mange.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Il regarda, et voilà qu\'à son chevet se trouvait une galette, cuite sur des cailloux chauffés, et une cruche d\'eau. Et il mangea et but, puis se recoucha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Et l\'ange de l\'Éternel revint une seconde fois et le toucha et dit: Lève-toi! mange, car la course est trop forte pour toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Et il se leva et mangea et but, et par la vertu de cette nourriture il marcha quarante jours et quarante nuits jusqu\'à la montagne de Dieu, à Horeb.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Et là il pénétra dans la grotte et il y passa la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Et voilà que la parole de l\'Éternel lui fut adressée en ces termes: Qu\'est-ce qui t\'amène ici, Élie? Et il répondit: Le zèle qui m\'anime pour l\'Éternel, le Dieu des armées, car les fils d\'Israël ont déserté ton alliance, démoli tes autels et tué tes prophètes avec l\'épée et j\'ai survécu seul et ils attentent à ma vie pour me la ravir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Et dit: Sors et parais sur la montagne devant l\'Éternel. Et voilà que l\'Éternel passa, et un vent grand et violent qui déchirait les montagnes et brisait les rochers précédait l\'Éternel; dans le vent n\'était pas l\'Éternel. Et après le vent ce fut un tremblement de terre; dans le tremblement de terre n\'était pas l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Et après le tremblement de terre un feu; dans le feu n\'était pas l\'Éternel. Et après le feu, murmure d\'une brise légère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Et lorsque Élie l\'entendit, il se couvrit le visage de son manteau, et sortit et se plaça à l\'ouverture de la grotte, et voilà qu\'une voix lui parvint, qui dit: Qu\'est-ce qui t\'amène ici, Élie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Et il dit: Le zèle qui m\'anime pour l\'Éternel, le Dieu des armées, car les fils d\'Israël ont déserté ton alliance, démoli tes autels, tué tes prophètes avec l\'épée et j\'ai survécu seul et ils attentent à ma vie pour me la ravir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Et l\'Éternel lui dit: Pars, rebrousse par le désert vers Damas, et arrivé là tu oindras Hazaël comme roi de Syrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'De plus, tu oindras Jéhu, fils de Nimsi, comme roi d\'Israël, et Elisée, fils de Schaphat, d\'Abel-Mehola, tu l\'oindras comme prophète pour te succéder.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Et il se fera que qui échappera à l\'épée d\'Hazaël, périra par Jéhu, et qui échappera à l\'épée de Jéhu, périra par Elisée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Et je laisserai survivre en Israël sept mille hommes, tout autant de genoux qui n\'ont pas ployé devant Baal, et de bouches qui ne lui ont pas jeté de baiser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Il partit donc de là et il trouva Elisée, fils de Schaphat, comme il labourait précédé de douze paires de bœufs, et il était auprès de la douzième, et Élie s\'avança vers lui et lui jeta son manteau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Sur quoi Elisée quitta ses bestiaux et courut après Élie et dit: Permets-moi de donner le baiser à mon père et à ma mère, puis je te suivrai. Et [Élie] lui dit: Va, retourne! Cependant qu\'est-ce que j\'ai fait à ton égard?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Et le quittant il revint en arrière et il prit sa paire de bœufs et l\'immola, et avec le harnais de l\'attelage il en fit cuire la chair dont il donna à ses gens qui en mangèrent; et il se leva et suivit Élie et fut à son service.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Cependant Ben-Hadad, roi de Syrie, ayant trente-deux rois pour auxiliaires, rassembla toutes ses forces, et chevaux et chars, et il s\'avança, et mit le siège devant Samarie et l\'attaqua.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Et il envoya des messagers à Achab, roi d\'Israël, dans la ville');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'et lui tint ce langage: Ainsi parle Ben-Hadad: Je suis maître de ton argent et de ton or, maître de tes femmes et de tes fils, de tes meilleurs biens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Et le roi d\'Israël répondit et dit: Comme tu le dis, roi mon seigneur, tu es maître de ma personne et de tout ce que j\'ai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Et les messagers revinrent et dirent: Ainsi parle Ben-Hadad: Si je t\'ai envoyé dire: Livre-moi ton argent et ton or, et tes femmes et tes fils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'c\'est que demain à pareille heure j\'enverrai chez toi mes serviteurs pour fouiller ta maison et les maisons de tes serviteurs et mettre la main sur tout ce qui charme tes yeux et l\'enlever.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Alors le roi d\'Israël fit assembler tous les Anciens du pays et dit: Sachez donc et considérez qu\'il cherche [notre] ruine, puisqu\'il m\'a envoyé une sommation par rapport à mes femmes et à mes fils, et à mon argent et à mon or que je ne lui ai point refusé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Et tous les Anciens et tout le peuple lui dirent: N\'obéis point et ne consens point!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Il dit donc aux messagers de Ben-Hadad: Dites à mon seigneur le roi: Je ferai tout ce que tu as demandé à ton serviteur en premier lieu, mais ceci, je ne saurais le faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Et les messagers partirent et reportèrent la réponse. Alors Ben-Hadad députa vers lui pour lui dire: Qu\'ainsi me fassent les dieux et pis encore, si la poussière de Samarie suffit à remplir les mains de tout le monde qui me suit!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Et le roi d\'Israël répondit et dit: Celui qui se ceint ne doit pas se vanter comme celui qui se déceint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Et Ben-Hadad entendant cette réponse (or il était à boire avec les rois dans les pavillons) dit à ses serviteurs: Faites les dispositions! Et ils firent les dispositions pour l\'assaut de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Et voilà qu\'un prophète s\'approcha d\'Achab, roi d\'Israël, et dit: Ainsi parle l\'Éternel: As-tu vu toute cette grande multitude? Eh bien! Je vais aujourd\'hui la livrer à tes mains, afin que tu saches que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Et Achab dit: Par qui? Et il reprit: Ainsi parle l\'Éternel: Par les valets des chefs des provinces. Et Achab dit: Qui engagera le combat? Et il répondit: Toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Alors il passa en revue les valets des chefs des provinces et il s\'en trouva deux cent trente-deux. Et après eux il passa en revue toutes les troupes, tous les enfants d\'Israël, au nombre de sept mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Et ils firent leur sortie à midi. Cependant Ben-Hadad buvait à être ivre dans les pavillons avec les trente-deux rois, ses auxiliaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Et les valets des chefs des provinces sortirent les premiers. Alors Ben-Hadad fit aller aux informations, et il reçut ce rapport: Des gens ont fait une sortie de Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Et il dit: S\'ils sont sortis pour la paix, saisissez-les vivants, et, s\'ils sont sortis pour le combat, saisissez-les vivants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Ceux-là donc sortirent de la place, les valets des chefs des provinces, puis l\'armée qui les suivait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Et ils battirent chacun son homme, et les Syriens prirent la fuite, et les Israélites les poursuivirent, et Ben-Hadad, roi de Syrie, se sauva sur son cheval avec des cavaliers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Et le roi d\'Israël se mit en mouvement, et mit en déroute les chevaux et les chars, et fit essuyer aux Syriens une grande défaite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Alors le prophète s\'approcha du roi d\'Israël et lui dit: Allons! sois résolu! songe et avise à ce que tu feras; car, au retour de l\'année, le roi de Syrie marchera contre toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Et les serviteurs du roi de Syrie lui dirent: Leurs dieux sont les dieux des montagnes; c\'est pourquoi ils l\'ont emporté sur nous; mais peut-être nous battant avec eux dans la plaine l\'emporterons-nous sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Or, voici ce que tu as à faire: ôte chacun des rois de sa position, et mets les gouverneurs à leur place,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'et toi, lève une armée égale à celle que tu as perdue, et autant de cavalerie que tu avais de cavalerie, et autant de chars que tu avais de chars, et fais-nous combattre avec eux dans la plaine; peut-être l\'emporterons-nous sur eux. Et il écouta leurs avis et fit ainsi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Et, au retour de l\'année, Ben-Hadad passa les Syriens en revue et s\'avança jusqu\'à Aphek pour se mesurer avec Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Et les enfants d\'Israël furent aussi passés en revue et avitaillés, et ils marchèrent à leur rencontre, et les enfants d\'Israël campèrent en face d\'eux, pareils à deux petits troupeaux de chèvres, tandis que les Syriens remplissaient le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Alors l\'homme de Dieu s\'approcha et parla au roi d\'Israël en ces termes: Ainsi parle l\'Éternel: Parce que les Syriens ont dit: L\'Éternel est Dieu des montagnes, mais non Dieu des vallées, je livrerai toute cette grande multitude-là à tes mains, afin que vous sachiez que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Et ils furent campés les uns vis-à-vis des autres pendant sept jours, et le septième jour il y eut rencontre en bataille, et les enfants d\'Israël tuèrent aux Syriens cent mille hommes de pied en une journée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Et les survivants s\'enfuirent à Aphek dans la ville, et la muraille croula sur vingt-sept mille hommes, les survivants, et Ben-Hadad s\'enfuit, et étant entré dans la ville, il allait de chambre en chambre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Alors ses serviteurs lui dirent: Voici, nous avons appris que les rois de la maison d\'Israël sont des rois cléments; entourons donc nos reins de cilices et nos têtes de cordes, et présentons-nous au roi d\'Israël; peut-être te laissera-t-il la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Et ils ceignirent leurs reins de cilices, et leurs têtes de cordes, et ils parurent devant le roi d\'Israël et dirent: Ton serviteur Ben-Hadad dit: Laisse-moi la vie! Et il répondit: Est-il encore vivant? Il est mon frère!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Et ces hommes reçurent cela comme un bon augure, et ils se hâtèrent de le prendre au mot et dirent: Ben-Hadad est donc ton frère! Et il répondit: Venez! amenez-le. Alors Ben-Hadad se présenta à lui et il le fit monter à côté de lui sur son char.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Et [Ben-Hadad] lui dit: Je te restituerai les villes que mon père a enlevées à ton père, et tu auras tes rues à Damas, comme mon père avait ses rues à Samarie. Et moi [dit Achab], je te laisserai aller sous la foi d\'une alliance. Et il lui accorda une capitulation et le laissa partir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Or, l\'un des fils des prophètes dit à son condisciple par ordre de l\'Éternel: Bats-moi donc! Mais l\'autre refusa de le battre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Alors il dit à celui-ci: Parce que tu n\'as pas obéi à la voix de l\'Éternel, voici, quand tu m\'auras quitté, tu seras abattu par le lion. Et quand il l\'eut quitté, le lion le rencontra et l\'abattit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Et il trouva un autre homme à qui il dit:Bats-moi donc! Et l\'homme le battit et le blessa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Alors le prophète alla se placer sur le chemin du roi, et il se déguisa en abaissant son turban sur ses yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Et au passage du roi il cria vers lui et dit: Ton serviteur faisait son service dans la mêlée du combat, lorsque, voilà qu\'un homme tire de côté, m\'amenant un homme et me dit: Garde cet homme-ci. S\'il vient à manquer, ta vie répondra de sa vie, ou bien tu paieras un talent d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Et comme ton serviteur était occupé çà et là, l\'homme disparut. Et le roi d\'Israël lui dit: C\'est ton jugement! Tu as décidé toi-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Alors vite il releva son turban de dessus ses yeux, et le roi d\'Israël reconnut en lui l\'un des prophètes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Et il dit au roi: Ainsi parle l\'Éternel: Parce que tu as laissé échapper de ta main l\'homme que j\'avais anathématisé, ta vie répondra de sa vie, et ton peuple, de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Et le roi d\'Israël rentra dans sa maison, chagrin et irrité, puis il gagna Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Et après ces choses il arriva que Naboth, de Jizréel, ayant à Jizréel une vigne touchant au palais d\'Achab, roi de Samarie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Achab parla à Naboth en ces termes: Cède-moi ta vigne pour en faire mon jardin potager, car elle est proche, à côté de mon habitation, et je te donnerai en échange une vigne meilleure que celle-là; si cela t\'agrée, je te donnerai de l\'argent en paiement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Mais Naboth dit à Achab: A l\'Éternel ne plaise que je te cède le patrimoine de mes pères!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Alors Achab rentra dans son palais, chagrin et irrité du langage que lui avait tenu Naboth de Jizréel en disant: Je ne te cède point le patrimoine de mes pères. Et il se coucha sur son lit et détourna la tête, et ne prit aucune nourriture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Alors Jézabel, sa femme, entra chez lui et lui dit: D\'où vient ton humeur sombre et que tu ne prends point de nourriture?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Et il lui dit: J\'ai parlé à Naboth de Jizréel et lui ai dit: Cède-moi ta vigne pour de l\'argent, ou, si tu préfères, je te donnerai une vigne pour celle-là. Mais il a dit: Je ne te cède point ma vigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Alors Jézabel, sa femme, lui dit: Exerces-tu maintenant, toi, la souveraineté sur Israël? Lève-toi, prends de la nourriture, aie le cœur à l\'aise; moi, je saurai te donner la vigne de Naboth de Jizréel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Et elle écrivit des lettres au nom d\'Achab et les scella de son sceau, et elle expédia les lettres dans sa ville aux Anciens et aux notables qui y habitaient avec Naboth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Et dans ces lettres elle écrivait en s\'exprimant ainsi: Publiez un jeûne et donnez à Naboth la première place du peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'et apostez deux hommes, gens de rien, en face de lui pour qu\'ils déposent contre lui en ces termes: Tu as maudit Dieu et le roi. Puis menez-le dehors, et le lapidez à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Et les hommes de sa ville, les Anciens et les notables qui habitaient dans sa ville, s\'y prirent comme le leur avait mandé Jézabel, d\'après le contenu des lettres qu\'elle leur avait envoyées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'ils publièrent un jeûne et donnèrent à Naboth la première place du peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'et les deux hommes, gens de rien, vinrent s\'asseoir en face de lui, et ces hommes de rien déposèrent contre Naboth devant le peuple en ces termes: Naboth a maudit Dieu et le roi. Et ils le menèrent en dehors de la ville, et ils le lapidèrent, et il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Alors ils expédièrent à Jézabel un message: Naboth est lapidé et mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Et lorsque Jézabel apprit que Naboth était lapidé et mort, Jézabel dit à Achab: Lève-toi, prends possession de la vigne de Naboth de Jizréel, qu\'il refusait de te céder pour de l\'argent, car Naboth n\'est plus en vie, car il est mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Et lorsque Achab apprit que Naboth était mort, Achab se leva pour descendre à la vigne de Naboth de Jizréel, afin d\'en prendre possession.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Alors la parole de l\'Éternel fut adressée à Élie, de Thisbé, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Lève-toi, descends à la rencontre d\'Achab, roi d\'Israël, qui réside à Samarie. Voilà qu\'il est dans la vigne de Naboth où il est descendu pour en prendre possession,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'et tiens-lui ce langage: Ainsi parle l\'Éternel: Es-tu meurtrier et usurpateur? Parle-lui et dis-lui: Ainsi parle l\'Éternel: A l\'endroit où les chiens ont lapé le sang de Naboth, les chiens laperont ton sang aussi à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Et Achab dit à Élie: M\'as-tu donc atteint, mon ennemi? Et il répondit: Je [t\']ai atteint, parce que tu t\'es vendu pour faire ce qui est mal aux yeux de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Voici, je vais amener la calamité sur toi et ravager après toi, et exterminer à Achab ce qui pisse à la muraille, mineur et émancipé en Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'et réduire ta maison à l\'état de la maison de Jéroboam, fils de Nebat, et à l\'état de la maison de Baësa, fils d\'Ahia, pour les provocations dont tu [M\']as provoqué, et parce que tu as entraîné Israël à pécher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Sur Jézabel aussi l\'Éternel parle et dit: Les chiens dévoreront Jézabel sur le rempart de Jizréel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Ceux qui mourront à Achab dans la ville, seront mangés par les chiens, et ceux qui mourront dans les champs, par les oiseaux du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Sauf Achab il n\'y en eut point qui se soit vendu comme lui pour faire ce qui est mal aux yeux de l\'Éternel, parce qu\'il fut séduit par Jézabel, sa femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Et il commit nombre d\'abominations, et adhéra aux idoles tout comme le faisaient les Amorites que l\'Éternel avait chassés devant les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Et lorsque Achab entendit ce discours, il déchira ses vêtements et appliqua le cilice sur son corps et jeûna, et coucha dans le cilice et prit une démarche lente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Alors la parole de l\'Éternel fut adressée à Élie, de Thisbé, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'As-tu vu que Achab s\'est courbé devant moi? Aussi, puisqu\'il s\'est courbé devant moi, je ne ferai pas venir la calamité de son vivant, c\'est au temps de son fils que j\'amènerai la calamité sur sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Et il y eut entre eux une trêve de trois ans, car il n\'y eut pas guerre entre la Syrie et Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Et la troisième année, Josaphat, roi de Juda, descendit chez le roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Et le roi d\'Israël dit à ses serviteurs: Savez-vous que Ramoth en Galaad est à nous? Et nous ne parlons pas de la reprendre des mains du roi de Syrie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Et il dit à Josaphat: Veux-tu venir avec moi attaquer Ramoth en Galaad? Et Josaphat dit au roi d\'Israël: Nous irons de pair moi et toi, mon monde et ton monde, ma cavalerie et ta cavalerie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Et Josaphat dit au roi d\'Israël: Requiers donc aujourd\'hui la parole de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Alors le roi d\'Israël réunit les prophètes, près de quatre cents hommes, et il leur dit: Marcherai-je à l\'attaque de Ramoth en Galaad, ou m\'abstiendrai-je? Et ils lui dirent: Tiens la campagne et le Seigneur la livrera aux mains du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Et Josaphat dit: N\'y a-t-il plus ici de prophète de l\'Éternel, que nous puissions interroger?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Et le roi d\'Israël dit à Josaphat: Il y a encore un homme par qui nous pouvons consulter l\'Éternel; mais je le hais, parce qu\'il ne me prédit pas du bien, mais du mal, Michée, fils de Jimla. Et Josaphat dit: Que le roi ne s\'exprime pas ainsi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Alors le roi d\'Israël manda un eunuque et lui dit: Fais vite venir Michée, fils de Jimla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Or le roi d\'Israël et Josaphat, roi de Juda, étaient assis chacun sur son trône, revêtus du costume, dans un local à l\'entrée de la porte de Samarie, et tous les prophètes prophétisaient devant eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Et Sédécias, fils de Knaana, se fit des cornes de fer et dit: Ainsi parle l\'Éternel: Avec ceci tu culbuteras les Syriens jusqu\'à les détruire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Et tous les prophètes prophétisèrent de même et dirent: Marche contre Ramoth en Galaad, et tu réussiras, et l\'Éternel la livrera entre les mains du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Cependant le messager parti pour mander Michée lui parla en ces termes: Voici, les paroles des prophètes ont été unanimement favorables au roi: que ta réponse soit donc semblable à la réponse de chacun d\'eux, et parle favorablement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Et Michée dit: Par la vie de l\'Éternel! Ce que l\'Éternel me dira, je le rendrai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Et quand il fut arrivé auprès du roi, le roi lui dit: Michée, marcherons-nous sur Ramoth en Galaad pour l\'attaquer, ou bien nous abstiendrons-nous? Et il lui répondit: Mets-toi en campagne et tu réussiras, et l\'Éternel la livrera aux mains du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Et le roi lui dit: Combien de fois me faudra-t-il t\'adjurer de ne me dire que la vérité, au nom de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Et il répondit: Je vois tout Israël épars sur les montagnes comme un troupeau sans pasteur. Et l\'Éternel dit: Ils n\'ont plus de souverain; qu\'ils retournent chacun dans sa demeure en paix!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Alors le roi d\'Israël dit à Josaphat: Ne te l\'ai-je pas dit? Il ne me prédit pas du bonheur, mais du malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Et il reprit: En conséquence écoute la parole de l\'Éternel! J\'ai vu l\'Éternel assis sur son trône et toute l\'armée des Cieux debout près de Lui à sa droite et à sa gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Et l\'Éternel dit: Qui fascinera Achab pour qu\'il marche et aille tomber à Ramoth en Galaad? Et l\'un parla d\'une manière et l\'autre d\'une autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Alors l\'esprit parut et se présenta devant l\'Éternel et dit: Moi, j\'irai le fasciner. Et l\'Éternel lui dit: Comment?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Et il répondit: Je veux sortir et être esprit de mensonge dans la bouche de tous ses prophètes. Et il dit: Fascine, et aussi tu le pourras; pars et ainsi fais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Eh bien! donc l\'Éternel a mis un esprit de mensonge dans la bouche de tous ces tiens prophètes; et l\'Éternel a contre toi dénoncé le désastre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Alors Sédécias, fils de Knaana, s\'approcha et frappa Michée à la joue et dit: Par quelle voie l\'esprit de l\'Éternel s\'en est-il allé d\'avec moi pour parler avec toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Et Michée dit: Voici, tu le verras le jour même que tu passeras de chambre en chambre pour te cacher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Et le roi d\'Israël dit à [quelqu\'un]: Saisis Michée et le ramène chez Amon, préfet de la ville, et chez Joas, fils du roi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'et tu diras: Ainsi parle le roi: Mettez celui-ci en prison et le nourrissez du pain et de l\'eau de tribulation jusqu\'à ce que je revienne sain et sauf.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Et Michée dit: Si tu reviens sain et sauf, l\'Éternel n\'a pas parlé par moi. Il dit encore: Entendez-le! vous toutes les Tribus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Ainsi le roi d\'Israël marcha avec Josaphat, roi de Juda, contre Ramoth en Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Et le roi d\'Israël dit à Josaphat: Je me travestirai pour aller au combat; mais toi, revêts-toi de tes habits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Et le roi d\'Israël se travestit et alla au combat. Or le roi de Syrie avait donné cet ordre aux trente-deux chefs des chars qu\'il avait: N\'engagez la lutte avec personne, petit ou grand, mais avec le roi d\'Israël seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Et quand les chefs des chars aperçurent Josaphat, ils dirent: Ce ne peut être que le roi d\'Israël; et ils appuyèrent de son côté pour l\'attaquer. Alors Josaphat cria.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Les chefs des chars, qui virent alors que ce n\'était pas le roi d\'Israël, cessèrent de le poursuivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Cependant un homme banda son arc, tout innocemment, et décocha un coup au roi d\'Israël au défaut de la cuirasse. Et celui-ci dit à son cocher: Tourne et mène-moi hors de la mêlée, car je me sens mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Et l\'action était chaude en cette journée, et le roi fut tenu debout sur son char en face des Syriens, et il mourut dans la soirée. Et le sang de la blessure coula dans la caisse du char.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Alors retentit dans la mêlée au coucher du soleil cette proclamation: Chacun à sa ville et chacun dans son pays!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Et le roi mort fut ramené à Samarie, et on donna la sépulture au roi à Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Et lorsqu\'on lava le char à l\'étang de Samarie, les chiens lapèrent son sang, et les prostituées s\'y baignèrent selon la menace que l\'Éternel avait prononcée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Le reste des actes d\'Achab, et toutes ses entreprises, et la construction du palais d\'ivoire, et la fondation de toutes les villes qu\'il bâtit, cela est d\'ailleurs consigné dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Et Achab reposa avec ses pères, et son fils Achazia régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Et Josaphat, fils d\'Asa, devint roi de Juda la quatrième année d\'Achab, roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Et Josaphat à son avènement avait trente-cinq ans, et il régna vingt-cinq ans à Jérusalem. Or le nom de sa mère était Azouba, fille de Silchi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Et il marcha sur tous les errements d\'Asa, son père, sans s\'en écarter, faisant ce qui est droit aux yeux de l\'Éternel. Seulement les tertres ne disparurent pas; le peuple offrait encore des victimes et de l\'encens sur les tertres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Et Josaphat fut en paix avec le roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Le reste des actes de Josaphat, et ses exploits et ses guerres, sont d\'ailleurs consignés dans le livre des annales des rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Et il extermina du pays le reste des prostitués qui restaient à l\'époque d\'Asa, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Et il n\'y avait pas de roi en Édom, qui était régi par un gouverneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Josaphat construisit des navires de Tharsis pour aller à Ophir chercher l\'or; mais ils n\'allèrent point, car les navires firent naufrage à Etsion Géber.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Alors Achazia, fils d\'Achab, dit à Josaphat: Permets que mes serviteurs s\'embarquent avec tes serviteurs dans les navires; mais Josaphat ne consentit pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Et Josaphat reposa avec ses pères et reçut la sépulture avec ses pères dans la ville de David, son père, et Joram, son fils, régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Achazia, fils d\'Achab, devint roi d\'Israël à Samarie la dix-septième année de Josaphat, roi de Juda, et il régna deux ans sur Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Et il fit ce qui est mal aux yeux de l\'Éternel et marcha sur les errements de son père et sur les errements de sa mère, et sur les errements de Jéroboam, fils de Nebat, qui avait entraîné Israël au péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Et il servit Baal et l\'adora et provoqua l\'Éternel, Dieu d\'Israël, tout comme avait fait son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Et il y eut rébellion de Moab contre Israël après la mort d\'Achab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Or Achazia fit une chute par le treillis de son étage supérieur à Samarie, et en fut malade. Alors il expédia des messagers auxquels il dit: Allez consulter Baal-Zébub, dieu d\'Ecron, pour savoir si je relèverai de cette maladie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Mais l\'ange de l\'Éternel avait parlé à Élie de Thisbé: Lève-toi, va au-devant des messagers du roi de Samarie et dis-leur: Est-ce donc au défaut d\'un Dieu en Israël que vous allez consulter Baal-Zébub, dieu d\'Ecron?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'C\'est pourquoi ainsi parle l\'Éternel: Du lit où tu es monté, tu ne redescendras pas, car tu dois mourir. Et Élie partit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Alors les messagers revinrent auprès du roi qui leur dit: Pourquoi donc revenez-vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Et ils lui dirent: Un homme s\'est avancé à notre rencontre et nous a dit: Allez et retournez vers le roi qui vous a envoyés, et dites-lui: Ainsi parle l\'Éternel: Est-ce au défaut d\'un Dieu en Israël que tu envoies consulter Baal-Zébub, dieu d\'Ecron? C\'est pourquoi du lit ou tu es monté, tu ne redescendras pas, car tu dois mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Et il leur dit: Quelle façon avait l\'homme qui s\'est avancé à votre rencontre et vous a tenu ce langage?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Et ils lui dirent: C\'était un homme portant un manteau velu et ayant les reins entourés d\'une ceinture de cuir. Et il dit: C\'est Élie de Thisbé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Alors il délégua vers lui un capitaine de cinquante avec ses cinquante hommes. Et celui-ci monta vers lui; et voici, il était assis au sommet de la montagne; et il lui dit: Homme de Dieu, le roi a dit: Descends!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Et Élie répondit et dit au capitaine de cinquante: Que si je suis un homme de Dieu, que le feu descende du ciel et te consume toi et tes cinquante hommes. Et le feu du ciel descendit et le consuma lui et ses cinquante hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Et derechef il lui délégua un autre capitaine de cinquante avec ses cinquante hommes. Et celui-ci prenant la parole lui dit: Homme de Dieu, ainsi a dit le roi: Hâte-toi de descendre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Et Élie répondit et leur dit: Que si je suis un homme de Dieu, que le feu descende du ciel et te consume, toi et tes cinquante hommes. Et le feu de Dieu descendit du ciel et le consuma lui et ses cinquante hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Et il lui délégua encore un autre chef de cinquante, un troisième, avec ses cinquante hommes. Et le capitaine de cinquante, le troisième, monta et arriva, et fléchit les genoux devant Élie, et le suppliant il lui dit: Homme de Dieu, ah! que ma vie et la vie de tes serviteurs, ces cinquante hommes, puisse être précieuse à tes yeux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Voilà que le feu est descendu du ciel, et a consumé les deux premiers capitaines de cinquante et leurs cinquante hommes; mais maintenant, puisse ma vie être précieuse à tes yeux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Et l\'ange de l\'Éternel dit à Élie: Descends avec lui! sois sans crainte devant lui! Alors il se leva et descendit avec lui vers le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Et il lui dit: Ainsi parle l\'Éternel: Parce que tu as envoyé des messagers consulter Baal-Zébub, dieu d\'Ecron, (était-ce au défaut d\'un Dieu en Israël?) pour requérir sa parole, pour cela, du lit où tu es monté, tu ne redescendras pas, car tu dois mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Et il mourut selon la menace de l\'Éternel prononcée par Élie. Et Joram devint roi en sa place, la seconde année de Joram, fils de Josaphat, roi de Juda, car il n\'avait point de fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Le reste des actes d\'Achazia, ses entreprises, est d\'ailleurs consigné dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Et lorsque l\'Éternel dans l\'ouragan éleva Élie au ciel, Élie et Elisée partaient de Guilgal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Et Élie dit à Elisée: Reste donc ici, car l\'Éternel m\'envoie à Béthel. Et Elisée dit: Par la vie de l\'Éternel et par la vie de ton âme, je ne te quitte pas! Ils descendirent donc à Béthel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Alors les fils des prophètes qui étaient à Béthel, sortirent vers Elisée et lui dirent: Sais-tu qu\'aujourd\'hui l\'Éternel enlève ton maître au-dessus de ta tête? Et il répondit: Je le sais aussi: silence!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Et Élie lui dit: Elisée, reste donc ici, car l\'Éternel m\'envoie à Jéricho. Et il répondit: Par la vie de l\'Éternel et par ta propre vie, je ne te quitte pas! Ils gagnèrent donc Jéricho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Et les fils des prophètes qui étaient à Jéricho, abordèrent Elisée et lui dirent: Sais-tu qu\'aujourd\'hui l\'Éternel enlève ton maître au-dessus de ta tête? Et il dit: Je le sais aussi: silence!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Et Élie lui dit: Reste donc ici, car l\'Éternel m\'envoie au Jourdain. Et il répondit: Par la vie de l\'Éternel et par ta propre vie! je ne te quitte pas! Ils s\'acheminèrent donc les deux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Or cinquante hommes d\'entre les fils des prophètes étaient en route et de loin ils s\'arrêtèrent en face, comme les deux étaient arrêtés au Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Alors Élie prit son manteau et le roula et frappa les eaux et elles se partagèrent mi-partie ça, mi-partie là, et les deux passèrent sur terre sèche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Et quand ils eurent passé, Élie dit à Elisée: Demande ce que je puis faire pour toi avant d\'être enlevé d\'avec toi! Et Elisée dit: Ah! puissé-je avoir une double portion de ton esprit!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Et il répondit: Tu demandes une chose difficile! Si tu peux me voir enlever d\'avec toi, il te sera fait ainsi; sinon, cela n\'aura pas lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Et comme ils allaient et parlaient en marchant, voici venir un char de feu et des chevaux de feu qui les séparèrent l\'un de l\'autre, et Élie s\'éleva dans l\'ouragan vers le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Or Elisée le vit et s\'écria: Mon père! mon père! Char d\'Israël et ses cavaliers! puis il ne le vit plus. Alors il saisit ses habits et les déchira en deux morceaux');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'et il releva le manteau d\'Élie qu\'il avait laissé tomber, et rebroussa et se tint au bord du Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Et il prit le manteau d\'Élie qu\'il avait laissé tomber et frappa les eaux et dit: Où est l\'Éternel, Dieu d\'Élie? Lors aussi qu\'il frappa les eaux, elles se partagèrent mi-partie ça, mi-partie là, et Elisée passa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Et il fut vu par les fils des prophètes qui étaient à Jéricho vis-à-vis et qui dirent: L\'esprit d\'Élie repose sur Elisée. Et ils vinrent au-devant de lui et ils s\'inclinèrent devant lui jusqu\'à terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'Et ils lui dirent: Vois donc! il y a parmi tes serviteurs cinquante braves: qu\'ils aillent donc à la recherche de ton maître. Pourvu que l\'Esprit de l\'Éternel ne l\'ait pas enlevé et jeté sur l\'une des montagnes ou dans l\'une des vallées! Et il dit: N\'envoyez pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Et ils insistèrent auprès de lui jusqu\'à le mettre dans l\'embarras. Alors il dit: Envoyez! Ils envoyèrent donc les cinquante hommes qui cherchèrent trois jours, mais sans le trouver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Et ils revinrent auprès de lui, qui cependant restait à Jéricho; et il leur dit: Ne vous avais-je pas dit: N\'allez pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Et les gens de la ville dirent à Elisée: Vois donc! cette ville est un bon séjour, comme mon seigneur le voit; mais l\'eau est mauvaise; et il y a de fréquents avortements dans la contrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Alors il dit: Procurez-moi un plat neuf et mettez-y du sel. Et ils le lui apportèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Et il sortit et se rendit à la source des eaux, et il y jeta le sel et dit: Ainsi parle l\'Éternel: J\'assainis cette eau, et il n\'en résultera plus ni mort, ni avortement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Ainsi l\'eau a été assainie jusqu\'à présent selon la parole d\'Elisée qu\'Elisée avait prononcée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Et de là il monta à Béthel, et comme il montait la route, des petits garçons sortirent de la ville et l\'assaillirent de pierres en lui disant: Monte, chauve! monte, chauve!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Et il se retourna et les regarda et il les maudit au nom de l\'Éternel. Alors deux ours sortirent de la forêt et déchirèrent quarante-deux de ces enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Et de là il se rendit au mont Carmel d\'où il regagna Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Cependant Joram, fils d\'Achab, devint roi d\'Israël à Samarie la dix-huitième année de Josaphat, roi de Juda, et régna douze ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Et il fit ce qui est mal aux yeux de l\'Éternel, seulement pas au même degré que son père et que sa mère, et il fit disparaître les statues de Baal qu\'avait faites son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Il s\'adonna seulement aux péchés de Jéroboam, fils de Nebat, qui avait entraîné Israël au péché; il ne s\'en départit pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Or Mésa, roi de Moab, était propriétaire de troupeaux et payait au roi d\'Israël un tribut de cent mille agneaux et cent mille béliers avec la toison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Mais à la mort d\'Achab le roi de Moab se rebella contre le roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Et à cette occasion le roi Joram sortit de Samarie et passa en revue tous les Israélites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'puis il se mit en mouvement et députa vers Josaphat, roi de Juda, pour lui dire: Le roi de Moab s\'est rebellé contre moi; veux-tu marcher avec moi contre Moab pour l\'attaquer? Et il répondit: Je marcherai, moi comme toi, mon monde comme ton monde, mes chevaux comme tes chevaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Et il dit: Quel chemin prendrons-nous? Et il répliqua: Le chemin du désert d\'Edom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Ainsi, se mirent en marche le roi d\'Israël et le roi de Juda et le roi d\'Edom, et après une traite de sept jours, l\'eau manqua pour l\'armée et le bétail qui les suivait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Alors le roi d\'Israël dit: Hélas! l\'Éternel a fait appel à ces trois rois pour les mettre dans la main de Moab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Et Josaphat dit: N\'y a-t-il ici aucun prophète de l\'Éternel pour consulter l\'Éternel par son moyen? Et l\'un des serviteurs du roi d\'Israël répondit et dit: Il y a ici Elisée, fils de Schaphat, qui versait l\'eau sur les mains d\'Elie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Et Josaphat dit: La parole de l\'Éternel est chez lui! Là-dessus le roi d\'Israël et Josaphat et le roi d\'Edom descendirent auprès de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Mais Elisée dit au roi d\'Israël: Qu\'ai-je à faire avec toi? Va aux prophètes de ton père et aux prophètes de ta mère! Et le roi d\'Israël lui dit: Non! car c\'est l\'Éternel qui a fait appel à ces trois rois pour les mettre dans la main de Moab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Et Elisée dit: Par la vie de l\'Éternel des armées, aux ordres de qui je suis, si je n\'avais égard à Josaphat, roi de Juda, je ne te regarderais pas, je ne te verrais pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Eh bien! amenez-moi un joueur de luth. Et comme le joueur de luth touchait les cordes, la main de l\'Éternel s\'étendit sur lui');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'et il dit: Ainsi parle l\'Éternel: Pratiquez dans ce ravin fossés et fossés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Car ainsi parle l\'Éternel: Vous ne verrez ni vent ni pluie, et ce ravin s\'emplira d\'eau, et vous vous désaltérerez, vous et vos troupeaux et votre bétail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Mais c\'est trop peu aux yeux de l\'Éternel: Il mettra Moab dans votre main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Et vous forcerez toutes les villes fortes et toutes les villes d\'élite, et vous abattrez tous les meilleurs arbres, et comblerez toutes les sources, et vous affligerez de pierres tous les champs fertiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Et le matin au moment de l\'oblation de l\'offrande, voilà que l\'eau arriva du chemin d\'Edom, et toute la contrée fut pleine d\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Cependant lorsque tous les Moabites apprirent que les rois s\'avançaient pour les attaquer, ils furent tous convoqués depuis les hommes à même de porter les armes et au-dessus, et ils se portèrent à la frontière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Et à leur lever le matin, quand le soleil parut sur les eaux, les Moabites virent devant eux l\'eau rouge comme le sang,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'et ils dirent: C\'est du sang! les rois se sont détruits l\'un l\'autre et se sont massacrés entre eux; au pillage donc, Moabites!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Mais lorsqu\'ils arrivèrent au camp d\'Israël, les Israélites se levèrent et défirent les Moabites qui s\'enfuirent devant eux, et [les Israélites] pénétrèrent dans le pays et mirent Moab en déroute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Et ils démolirent les villes, et ils jetèrent chacun sa pierre sur tous les champs fertiles qu\'ils en remplirent, et comblèrent toutes les sources et abattirent tous les meilleurs arbres, jusqu\'à ne laisser que les pierres de la ville à Kir-Haréseth. Et les frondeurs l\'enveloppèrent et la battirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Et lorsque le roi de Moab vit que la bataille était plus forte que lui, il prit avec lui sept cents hommes tirant l\'épée pour percer jusqu\'au roi d\'Edom; mais ils ne purent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Alors il prit son fils premier-né, qui devait régner en sa place, et l\'immola en holocauste sur le rempart. Et il y eut une grande indignation contre les Israélites, qui partirent et regagnèrent le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Et une femme d\'entre les épouses des fils des prophètes jeta son cri à Elisée en disant: Ton serviteur, mon mari, est mort; et tu sais que ton serviteur était craignant l\'Éternel; or le créancier s\'est présenté pour prendre mes deux enfants et les avoir comme ses esclaves.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Et Elisée lui dit: Que faut-il que je fasse pour toi? Dis-moi ce que tu as au logis! Et elle lui dit: Ta servante n\'a rien au logis sinon une fiole d\'huile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Et il dit: Va et emprunte pour toi au dehors des vases à tous tes voisins, des vases vides, et pas en petit nombre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Puis, rentrée, ferme la porte sur toi et tes fils et verse dans tous ces vases, et mets de côté ce qui sera plein.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Alors elle le quitta; et elle ferma la porte sur elle et sur ses fils; ceux-ci lui tendaient les vases, et elle versait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'et lorsque les vases furent pleins, elle dit à son fils: Tends-moi encore un vase! Et il lui dit: Il n\'y a plus de vases. Alors l\'huile s\'arrêta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Et elle vint raconter à l\'homme de Dieu, qui lui dit: Va, vends l\'huile et paye ta dette, et toi et tes fils vivez du surplus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Et il advint alors que Elisée passa à Sunem; et il y avait là une femme notable qui l\'obligea à prendre son repas [chez elle]. Et toutes les fois qu\'il passait, il entrait là pour prendre son repas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Et elle dit à son mari: Vois-tu! eh bien! je sens que c\'est un saint homme de Dieu qui passe chez nous constamment;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'faisons-lui donc à l\'étage une petite chambre en maçonnerie, et plaçons-y pour lui un lit et une table et un siège et un flambeau pour qu\'il y loge quand il viendra chez nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Et il arriva alors qu\'étant venu là il logea dans la chambre de l\'étage et y coucha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Et il dit à Gehazi, son valet: Appelle cette Sunamite. Et il l\'appela et elle se présenta à lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Et il lui dit: Eh bien! dis-lui: Voici, tu t\'es agitée pour nous de toute cette sollicitude: que puis-je faire pour toi? Y-a-t-il à parler pour toi au roi ou au général de l\'armée? Et elle dit: Je reste au milieu de ma Tribu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Et il dit: Que puis-je donc faire pour elle? Et Gehazi dit: Mais! elle n\'a pas de fils et son mari est vieux. Et il dit: Appelle-la.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Et il l\'appela, et elle se présenta à la porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Et il dit: A cette époque l\'année prochaine tu embrasseras un fils. Et elle dit: Oh! non! mon Seigneur! Homme de Dieu! Ne trompe pas ta servante!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Et cette femme devint enceinte et elle enfanta un fils à la même époque, l\'année révolue, comme lui avait dit Elisée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Et l\'enfant ayant grandi, il arriva alors qu\'il sortit pour joindre son père auprès des moissonneurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Là il dit à son père: Ma tête! Ma tête! Et celui-ci dit au valet: Porte-le à sa mère. Et il le porta et l\'amena à sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Et l\'enfant resta sur ses genoux jusqu\'à midi, puis il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Et elle monta et le déposa sur le lit de l\'homme de Dieu, puis ferma sur lui et sortit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Et s\'adressant à son mari elle dit: Envoie-moi donc un des valets et une des ânesses, et je vais courir chez l\'homme de Dieu, puis revenir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Et il dit: Pourquoi vas-tu chez lui aujourd\'hui? ce n\'est ni lune nouvelle, ni sabbat. Et elle dit: Laisse-moi faire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Et elle sella l\'ânesse et dit à son valet: Mène et va sans m\'arrêter dans la course, que je ne te le dise!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Et étant partie elle arriva chez l\'homme de Dieu au mont Carmel. Et lorsque l\'homme de Dieu la vit de loin, il dit à Gehazi, son valet: Voici cette Sunamite!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Maintenant cours donc à sa rencontre et lui dis: Tout va-t-il bien pour toi, bien pour ton mari, bien pour l\'enfant? Et elle dit: Bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Et elle arriva chez l\'homme de Dieu à la montagne, et elle embrassa ses pieds. Alors Gehazi s\'approcha pour la repousser, mais l\'homme de Dieu dit: Laisse-la faire! car elle a dans l\'âme une amère douleur; et l\'Éternel m\'en a fait un secret et ne m\'a point mis au fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Et elle dit: Est-ce que j\'ai demandé un fils à mon Seigneur? N\'ai-je pas dit: Ne me trompe pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Et il dit à Gehazi: Ceins tes reins et prends mon bâton dans ta main et pars! Si tu rencontres quelqu\'un, ne le salue point, et si quelqu\'un te salue, ne lui réponds point, et tu mettras mon bâton sur la figure de l\'enfant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Et la mère de l\'enfant dit: Par la vie de l\'Éternel et par ta propre vie, je ne te quitte pas! Alors il se leva et la suivit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Or Gehazi les avait devancés et avait posé le bâton sur la figure de l\'enfant; mais pas un son, pas un signe d\'attention. Et il rebroussa à leur rencontre, et il l\'informa et dit: L\'enfant ne s\'est pas réveillé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Et lorsque Elisée entra dans la maison, voilà que l\'enfant était mort, gisant sur son lit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Alors il entra et ferma la porte sur eux deux, et il invoqua l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Et étant monté il se coucha sur l\'enfant et appliqua sa bouche sur sa bouche, et ses yeux sur ses yeux et ses mains sur ses mains, et il s\'étendit sur lui de manière à réchauffer le corps de l\'enfant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Et il se releva, et marcha dans la maison une fois d\'un côté, une fois de l\'autre; puis étant remonté il s\'étendit sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Alors l\'enfant éternua sept fois, et l\'enfant ouvrit les yeux. Et il appela Gehazi et dit: Appelle cette Sunamite! Et il l\'appela et elle vint à lui et il dit: Reprends ton fils!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Alors elle vint tomber à ses pieds et s\'inclina jusqu\'à terre et emmena son fils et s\'en alla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Cependant Elisée revint à Guilgal et la famine régnait dans le pays, et les fils des prophètes demeuraient devant lui. Et il dit à son valet: Mets en place la grande marmite et fais cuire un légume pour les fils des prophètes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Alors l\'un d\'eux sortit dans les champs pour cueillir de la verdure, et il trouva une sorte de vigne sauvage et il y cueillit des concombres sauvages plein son habit; et étant rentré il les coupa en morceaux dans la marmite aux légumes, car on ne savait pas ce que c\'était.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Et ils les en sortirent pour le repas des hommes; mais lorsqu\'ils goûtèrent du légume, ils se récrièrent et dirent: La mort est dans la marmite, homme de Dieu! et ils ne pouvaient manger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Alors il dit: Mais! prenez donc de la farine! Et il en jeta dans la marmite et dit: Sers-en à ce monde! et ils en mangèrent. Et il n\'y avait plus rien de nuisible dans la marmite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Or il vint un homme de Baal-Salisa et il apportait à l\'homme de Dieu du pain de prémices, vingt pains d\'orge et des gruaux dans sa valise. Et il dit: Donnes-en à manger à ce monde!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Et son domestique dit: Comment pourrais-je en servir à cent personnes? Et il dit: Sers-leur-en pour qu\'ils en mangent; car ainsi parle l\'Éternel: On en mangera et on en laissera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Alors il leur en servit et ils mangèrent, et en laissèrent selon la parole de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naaman, général d\'armée du roi de Syrie, était un homme en grand crédit auprès de son maître et un personnage considérable, car c\'est par lui que l\'Éternel avait donné la victoire aux Syriens, et c\'était un héros vaillant, mais il avait la lèpre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Or les Syriens étaient sortis en course par bandes et avaient ramené captive du pays d\'Israël une jeune fille qui fut au service de la femme de Naaman.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Et elle dit à sa maîtresse: Ah! si mon maître était devant le prophète qui est à Samarie! Alors il le débarrasserait de sa lèpre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Alors il (Naaman) alla informer son maître en disant: De telle et telle manière a parlé la jeune fille du pays d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Et le roi de Syrie dit: Pars, vas-y et j\'enverrai une lettre au roi d\'Israël. Et il partit prenant avec lui dix talents d\'argent et six mille sicles d\'or et dix habits de gala.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Et il porta au roi d\'Israël la lettre conçue en ces termes... « avec cette lettre qui te parvient, voici, je t\'adresse Naaman, mon serviteur, afin que tu le débarrasses de sa lèpre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Et à la lecture de la lettre, le roi d\'Israël déchira ses habits et dit: Suis-je un dieu pour donner la mort ou la vie, qu\'il s\'adresse à moi pour que je débarrasse un homme de sa lèpre? Sans doute que, comprenez donc et voyez, il veut se donner prise sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Et lorsque Elisée, l\'homme de Dieu, apprit que le roi d\'Israël avait déchiré ses habits, il députa vers le roi pour lui dire: Pourquoi donc déchirer tes habits? Qu\'il vienne donc à moi et éprouve qu\'il y a un prophète en Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Et Naaman vint avec ses chevaux et son char, et s\'arrêta à la porte de la maison d\'Elisée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Et Elisée lui envoya un messager pour lui dire: Va et te plonge sept fois dans le Jourdain, et ta chair se remettra et tu seras pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Alors Naaman fut irrité et s\'en alla en disant: Voilà que je m\'étais dit: il ne manquera pas de sortir vers moi et de paraître et d\'invoquer le Nom de l\'Éternel, son Dieu, et de mouvoir sa main sur la place et enlever ainsi la lèpre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'L\'Abana et le Pharphar, rivières de Damas, ne valent-ils pas mieux que toutes les eaux d\'Israël? Ne puis-je pas m\'y baigner et ressortir pur? Et il tourna le dos et partit en colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Alors ses serviteurs l\'abordèrent et lui parlèrent en ces termes: Mon père, le prophète t\'a-t-il donc indiqué quelque chose de si difficile? Ne veux-tu pas le faire? d\'autant plus qu\'il t\'a dit: Baigne-toi et te voilà pur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Alors il descendit et se plongea dans le Jourdain sept fois d\'après l\'avis de l\'homme de Dieu. Et sa chair revint à l\'état de la chair d\'un jeune garçon; et il se trouva pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Alors il retourna vers l\'homme de Dieu, lui et toute son escorte, et arrivé il se présenta devant lui et dit: Oh! maintenant je reconnais qu\'il n\'existe pas de Dieu sur toute la terre, sinon dans Israël, et maintenant daigne accepter un présent de ton serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Et il répondit: Par la vie de l\'Éternel sous les ordres de qui je suis, je n\'accepte point. Et Naaman insista pour le faire accepter, mais il refusa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Et Naaman dit: Au défaut de cela, qu\'au moins il soit accordé à ton serviteur la charge de deux mulets de terre! Car désormais ton serviteur n\'offrira plus ni holocauste, ni victime à d\'autres dieux, mais uniquement à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Mais que sur un point ton serviteur obtienne indulgence de l\'Éternel, lorsque mon Maître ira au temple de Rimmon pour s\'y prosterner, et qu\'il s\'appuiera sur ma main et que je me prosternerai dans le temple de Rimmon! lors donc que je me prosternerai dans le temple de Rimmon, veuille l\'Éternel pardonner à ton serviteur sur ce point!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Et Elisée lui répondit: Va-t\'en avec la paix. Et l\'ayant quitté il fit quelque peu de chemin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Alors Gehazi, valet d\'Elisée, homme de Dieu, dit: Voilà que mon maître a ménagé Naaman, ce Syrien-là, en n\'acceptant pas de sa main ce qu\'il lui offrait! par la vie de l\'Éternel, je vais courir après lui, et tirer de lui quelque chose.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Et Gehazi se mit à courir après Naaman. Et Naaman voyant quelqu\'un accourir après lui sauta en bas de son char et venant à sa rencontre il dit: Va-t-il bien?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Et il répondit: Bien. Mon maître m\'envoie te dire: Voilà qu\'il vient de m\'arriver deux jeunes gens de la montagne d\'Ephraïm, d\'entre les fils des prophètes: eh bien! donne pour eux un talent d\'argent et deux habillements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Et Naaman dit: Tu voudras bien accepter deux talents. Et il insista auprès de lui et serra les deux talents d\'argent dans deux bourses et deux habillements et les remit a deux de ses valets qui les portèrent en le précédant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Et arrivé à la colline il les reçut de leurs mains, et les cacha dans la maison, puis il congédia les gens qui partirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Quant à lui, une fois rentré il se présenta à son maître. Alors Elisée lui dit: D\'où viens-tu, Gehazi? Et il répondit: Ton serviteur ne s\'en était allé ni ici ni là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Et il lui dit: Mon esprit s\'en était-il allé, lorsque l\'homme quitta son char pour venir à ta rencontre? Était-ce le moment de recevoir de l\'argent et de recevoir des habillements, et puis des oliviers et des vignes et du menu et du gros bétail et des serviteurs et des servantes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Que donc la lèpre de Naaman s\'attache à toi et à ta race pour toujours! Et il sortit de sa présence couvert d\'une lèpre comme la neige.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Et les fils des prophètes dirent à Elisée: Daigne considérer que le local où nous habitons devant toi, est trop restreint pour nous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'permets-nous donc d\'aller au Jourdain, et d\'y prendre chacun une solive, et nous nous ferons ici un local pour notre habitation. Et il dit: Allez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Et l\'un d\'eux dit: Consens donc à venir avec tes serviteurs. Et il dit: J\'irai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Et il s\'achemina avec eux et ils arrivèrent au Jourdain et ils coupèrent les bois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Et comme l\'un d\'eux abattait une solive, le fer tomba dans l\'eau, et il s\'écria disant: Hélas! mon Seigneur, il était emprunté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Alors l\'homme de Dieu dit: Où est-il tombé? Et quand il lui eut montré la place, Elisée coupa un morceau de bois et l\'y jeta et fit surnager le fer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Et il dit: Ramasse-le! Et étendant la main il le prit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Cependant le roi de Syrie faisait la guerre en Israël et il se consulta avec ses serviteurs et dit: Dans tel lieu j\'aurai mon camp.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Alors l\'homme de Dieu envoya au roi d\'Israël cet avis: Prends garde de négliger cette position-là, car les Syriens vont s\'y embusquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Alors le roi d\'Israël fit occuper le lieu que lui indiquait et signalait l\'homme de Dieu, et s\'y tint en observation, et cela non pas à une seule, ni à deux reprises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Et cette manœuvre inquiéta le cœur du roi de Syrie, qui manda ses serviteurs et leur dit: Ne me dénoncerez-vous pas celui des nôtres qui est pour le roi d\'Israël?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Et l\'un de ses serviteurs dit: Non! ô roi, mon Seigneur, car c\'est Elisée, le prophète, qui en Israël rapporte au roi d\'Israël les mots que tu dis dans ta chambre à coucher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Sur ce il dit: Allez voir où il est, afin que j\'envoie le saisir. Et il lui vint cet avis: Voici, il est à Dothan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Alors il y expédia chevaux et chars et une grosse armée; et ils arrivèrent de nuit et cernèrent la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Et lorsque le matin celui qui servait l\'homme de Dieu, se leva et sortit, voilà qu\'une armée avec chevaux et chars enveloppait la ville. Et son valet lui dit: Ah! mon Seigneur, comment ferons-nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Et il répondit: N\'aie pas peur! car nous en avons plus pour nous qu\'ils n\'en ont pour eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Et Elisée fit sa prière et dit: Éternel, daigne lui ouvrir les yeux pour qu\'il voie! Et l\'Éternel ouvrit les yeux au valet, et il regarda, et voilà que la montagne était remplie de chevaux et de chars de feu entourant Elisée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Alors ils descendirent vers lui, et Elisée fit cette prière à l\'Éternel: A ma prière frappe cette troupe-là d\'aveuglement. Alors Il les frappa d\'aveuglement selon la demande d\'Elisée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Et Elisée leur dit: Ce n\'est ni le chemin, ni la ville: suivez-moi, et je vous mènerai vers l\'homme que vous cherchez. Et il les mena à Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Et quand ils arrivèrent à Samarie, Elisée dit: Éternel, ouvre-leur les yeux pour qu\'ils voient. Alors l\'Éternel leur ouvrit les yeux, et ils virent: et voilà qu\'ils étaient au milieu de Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Et le roi d\'Israël, lorsqu\'il les vit, dit à Elisée: Frapperai-je? frapperai-je, mon père?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Et Elisée dit: Tu n\'as pas à frapper: est-ce ceux que tu as faits prisonniers avec ton épée et ton arc, que tu frappes? Sers-leur du pain et de l\'eau, et qu\'ils mangent et boivent, puis s\'en aillent vers leur Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Alors il leur fit grande chère, et ils mangèrent et burent, et il les congédia et ils partirent vers leur Seigneur. Dès lors les bandes Syriennes n\'infestèrent plus le territoire d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Et plus tard Ben-Hadad, roi de Syrie, rassembla toute son armée et se mit en campagne et vint assiéger Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Et il y avait grande famine à Samarie; et voici, ils la serrèrent de près jusqu\'à faire monter à quatre-vingts sicles d\'argent une tête d\'âne, et à cinq sicles le quart d\'un cab de fiente de pigeon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Et comme le roi d\'Israël passait sur le rempart, une femme lui cria: Au secours! roi, mon Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Et il dit: L\'Éternel ne te secourt-Il pas? De quoi t\'assisterais-je? de l\'aire ou du pressoir?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Et le roi lui dit: Que t\'arrive-t-il? Et elle répondit: Cette femme-là m\'a dit: Donne-moi ton fils et nous le mangerons aujourd\'hui, et demain nous mangerons le mien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Alors nous fîmes cuire mon fils et nous l\'avons mangé; et le jour suivant je lui ai dit: Donne ton fils et nous le mangerons; mais elle a caché son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Et lorsque le roi ouït le discours de la femme, il déchira ses habits; et comme il passait sur la muraille, le peuple le vit et voilà qu\'il portait intérieurement un cilice sur son corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Et il dit: Que Dieu me fasse ceci et pis encore si aujourd\'hui la tête d\'Elisée, fils de Schaphat, reste sur sa personne!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Cependant comme Elisée était assis dans sa maison et les Anciens assis auprès de lui, [le roi] envoya un homme avant lui. Mais avant que le messager arrivât chez lui, il dit aux Anciens: Voyez-vous que ce fils d\'assassin envoie quelqu\'un pour faire tomber ma tête? Observez quand le messager viendra; alors fermez la porte et repoussez-le à l\'aide de la porte. N\'entendez-vous pas le bruit des pas de son maître qui le suit?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Il leur parlait encore que voilà que le messager descendit chez lui et dit: Voici, ce mal procède de l\'Éternel: pourquoi m\'attendrai-je encore à l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Alors Elisée dit: Écoutez la parole de l\'Éternel! Ainsi parle l\'Éternel: Demain à pareille heure un boisseau de fleur de farine vaudra un sicle et deux boisseaux d\'orge un sicle à la Porte de Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Et l\'adjudant sur la main duquel le roi s\'appuyait, répondit à l\'homme de Dieu et dit: Voici, quand l\'Éternel ouvrirait des fenêtres dans le ciel, la chose arriverait-elle? Et il reprit: Voici, tu le verras de tes yeux, mais tu n\'en mangeras pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Or quatre hommes qui avaient la lèpre, se tenaient à l\'avenue de la Porte et ils se dirent l\'un à l\'autre: Que faisons-nous d\'attendre ici jusqu\'à notre mort?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Si nous disions: Nous entrerons dans la ville! la famine y est, et nous y mourrions, et si nous restons ici, nous mourons. Eh bien! venez et passons au camp des Syriens; s\'ils nous laissent vivre, nous vivrons; s\'ils nous font mourir, nous mourrons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Ils se levèrent donc au crépuscule pour passer au camp des Syriens, et quand ils atteignirent l\'extrémité du camp des Syriens, voilà qu\'il n\'y avait personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Car le Seigneur avait fait entendre à l\'armée des Syriens un fracas de chars et un fracas de chevaux, un fracas de grandes troupes, et ils se dirent l\'un à l\'autre: Voici, le roi d\'Israël a pris à sa solde contre nous les rois des Héthiens et les rois d\'Egypte pour fondre sur nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Puis ils se levèrent et fuirent au crépuscule, abandonnant leurs tentes et leurs chevaux et leurs ânes, et leur camp, tel quel, et fuyant pour sauver leur vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Et ces lépreux ayant atteint l\'extrémité du camp, pénétrèrent dans une tente, et mangèrent et burent, et en emportèrent de l\'argent et de l\'or et des habillements qu\'ils allèrent cacher; puis revenant ils pénétrèrent dans une autre tente et y firent des captures qu\'ils allèrent cacher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Alors ils se dirent l\'un à l\'autre: Nous n\'agissons pas bien! Ce jour est un jour de bonne nouvelle, et si nous nous taisons et attendons jusqu\'à l\'aube du matin, nous nous trouverons en état de délit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Venez donc et entrons et informons la maison du roi. Et ils vinrent et appelèrent la garde de la Porte de la ville et l\'informèrent en ces termes: Nous avons pénétré dans le camp des Syriens, et voilà qu\'il n\'y avait personne, ni voix d\'hommes, mais les chevaux attachés et les ânes attachés et les tentes telles quelles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Et la chose fut répétée par les gardes de la Porte, puis transmise à l\'intérieur du palais du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Alors le roi se leva dans la nuit et dit à ses serviteurs: Je veux vous découvrir ce que les Syriens entreprennent contre nous: sachant que nous sommes affamés, ils sont sortis du camp pour se cacher dans la campagne avec cette idée: Qu\'ils sortent, et nous les prenons vivants et envahissons la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Et l\'un de ses serviteurs prit la parole et dit: Mais! que l\'on prenne cinq des chevaux restants qui survivent dans la ville (hé! ils sont comme toute la multitude d\'Israël restée dans la ville, comme toute la multitude d\'Israël qui dépérit); et envoyons en reconnaissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Et ils prirent un double attelage de chevaux, et le roi les envoya sur les traces de l\'armée des Syriens avec cet ordre: Allez et voyez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Et ils les suivirent jusqu\'au Jourdain, et voilà que toute la route était jonchée d\'habillements et de meubles que les Syriens avaient jetés dans leur précipitation. Ensuite les courriers revinrent et firent rapport au roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Alors le peuple sortit et pilla le camp des Syriens, et l\'on eut un boisseau de fleur de farine pour un sicle et deux boisseaux d\'orge pour un sicle selon la parole de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Et le roi avait confié la garde de la Porte à l\'adjudant sur la main duquel il s\'appuyait; et celui-ci fut écrasé contre la Porte par le peuple et il mourut, comme l\'avait annoncé l\'homme de Dieu, qui avait parlé lorsque le roi descendit chez lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'En effet, lorsque l\'homme de Dieu parlait au roi en ces termes: On aura deux boisseaux d\'orge pour un sicle et un boisseau de fleur de farine pour un sicle demain à pareille heure dans la Porte de Samarie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'l\'adjudant répondit à l\'homme de Dieu en ces termes: L\'Éternel va-t-Il ouvrir des fenêtres dans le ciel? pareille chose arrivera-t-elle? Et Elisée répondit: Voici, tu le verras de tes yeux, mais tu n\'en mangeras pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Et il en fut ainsi pour lui, et il fut écrasé par le peuple dans la Porte, et il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Et Elisée parla en ces termes à la femme dont il avait rendu le fils à la vie: Lève-toi et pars, toi et ta maison, et émigre quelque part, car l\'Éternel fait venir la famine, et qui plus est, elle envahira le pays durant sept ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Et la femme se leva et se conforma à l\'avis de l\'homme de Dieu, et elle partit, elle et sa maison, et fut en émigration dans le pays des Philistins durant sept années.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Et au bout des sept années la femme revint du pays des Philistins; et elle sortit dans le but de réclamer auprès du roi pour sa maison et son champ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Et le roi s\'entretenait avec Gehazi, le valet de l\'homme de Dieu, et disait: Raconte-moi donc toutes les grandes choses qu\'a faites Elisée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Et en effet, Gehazi racontait au roi qu\'il avait rendu la vie au mort, lorsque la femme au fils de laquelle il avait rendu la vie, fit au roi sa réclamation pour sa maison et son champ; et Gehazi dit au roi: O Roi, mon Seigneur, c\'est la femme même et c\'est à son fils qu\'Elisée a rendu la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Et le roi interrogea la femme et elle lui fit le récit, et le roi lui donna (pour l\'accompagner) un eunuque auquel il dit: Restitue tout ce qui lui appartient, y compris le revenu du champ à partir du jour où elle a quitté le pays, jusqu\'à maintenant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Et Elisée vint à Damas, et Ben-Hadad, roi de Syrie, était malade; et il fut averti en ces termes: L\'homme de Dieu est arrivé ici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Alors le roi dit à Hazaël: Prends dans ta main une offrande et va au-devant de l\'homme de Dieu, et adresse par lui cette question à l\'Éternel: Relèverai-je de cette maladie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Et Hazaël alla au-devant de lui, et prit dans sa main une offrande, tous les plus excellents produits de Damas, la charge de quarante chameaux, et il vint se présenter à lui et dit: Ton fils Ben-Hadad, roi de Syrie, m\'envoie vers toi avec ce message: Relèverai-je de cette maladie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Et Elisée lui dit: Va! dis-lui: Certainement tu en relèveras! Mais l\'Éternel m\'a découvert qu\'il mourra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Et l\'homme de Dieu fixa sur lui son regard qu\'il soutint jusqu\'au point de le confondre, et l\'homme de Dieu pleura.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Alors Hazaël dit: Pourquoi pleure mon Seigneur? Et il répondit: Parce que je sais le mal que tu feras aux enfants d\'Israël: tu incendieras leurs forteresses, et égorgeras leur jeunesse avec l\'épée, et écraseras leurs enfants et éventreras leurs femmes enceintes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Et Hazaël dit: Mais! qu\'est donc ton chien de serviteur pour exécuter de si grandes choses? Et Elisée dit: L\'Éternel m\'a fait voir en toi un roi de Syrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Et il quitta Elisée pour revenir chez son Maître qui lui dit: Que t\'a dit Elisée? Et il répondit: il m\'a dit: Certainement tu en relèveras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Et le lendemain il prit la couverture qu\'il plongea dans l\'eau, et il l\'étendit sur le visage du roi qui mourut; et Hazaël régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Cependant la cinquième année de Joram, fils du roi d\'Israël, Achab, Joram, fils de Josaphat, devint roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Il avait trente-deux ans à son avènement, et il régna huit ans à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Et il marcha sur les errements des rois d\'Israël comme avait fait la maison d\'Achab; car il avait épousé une fille d\'Achab, et il fit ce qui est mal aux yeux de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Mais l\'Éternel ne voulut pas ruiner Juda, et cela pour l\'amour de David, son serviteur, selon la promesse qu\'il lui avait faite de lui laisser un flambeau pour ses fils dans tous les temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'De son temps les Edomites se rendirent indépendants de Juda; et ils se donnèrent un roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Joram alors se porta sur Tsaïra avec tous ses chars: et il se leva la nuit et battit les Iduméens qui l\'enveloppaient, et les chefs des chars; et la troupe s\'enfuit dans ses tentes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'C\'est ainsi que Edom est détaché de la domination de Juda jusqu\'à ce jour. Alors à la même époque eut lieu la défection de Libna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Le reste des actes de Joram et toutes ses entreprises sont d\'ailleurs consignés dans le livre des annales des rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Et Joram reposa à côté de ses pères, et reçut la sépulture avec ses pères dans la ville de David, et Achazia, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'La douzième année de Joram, fils du roi d\'Israël, Achab, Achazia, fils de Joram, devint roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Achazia avait vingt-deux ans à son avènement et il régna un an à Jérusalem. Or le nom de sa mère était Athalie, fille d\'Omri, roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Et il marcha sur les errements de la maison d\'Achab et fit ce qui est mal aux yeux de l\'Éternel, comme la maison d\'Achab; car il s\'était allié à la maison d\'Achab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Et il marcha avec Joram, fils d\'Achab, dans la guerre contre Hazaël, roi de Syrie, pour Ramoth en Galaad. Et les Syriens blessèrent Joram.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Alors le roi Joram rebroussa pour se rétablir à Jizréel des blessures qu\'il avait reçues des Syriens à Rama, lorsqu\'il se battait contre Hazaël, roi de Syrie. Et Achazia, fils de Joram, roi de Juda, descendit pour visiter Joram, fils d\'Achab, à Jizréel, car il était malade.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Cependant Elisée, le prophète, manda l\'un des fils des prophètes et lui dit: Ceins tes reins et prends cette fiole d\'huile dans ta main et pars pour Ramoth en Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Et arrivé là enquiers-toi de Jéhu, fils de Josaphat, fils de Nimsi, puis entre, et fais-le lever du milieu de ses frères et conduis-le de chambre en chambre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'et tu prendras la fiole d\'huile et la verseras sur sa tête et diras: Ainsi parle l\'Éternel: Je t\'oins roi d\'Israël. Ensuite ouvre la porte et fuis sans attendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Le jeune homme, valet du prophète, se rendit ainsi à Ramoth en Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Et à son entrée, voilà que les chefs de l\'armée étaient en séance. Et il dit: J\'ai à te parler, Capitaine. Et Jéhu dit: Auquel de nous tous? Et il répondit: A toi, Capitaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Alors il se leva et entra dans l\'intérieur de la maison, et le prophète versa l\'huile sur sa tête, et lui dit: Ainsi parle l\'Éternel, Dieu d\'Israël: Je t\'oins roi du peuple de l\'Éternel, d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Et tu abattras la maison d\'Achab, ton souverain, et je vengerai le meurtre de mes serviteurs, les prophètes, et le meurtre de tous les serviteurs de l\'Éternel, sur Jézabel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'et toute la maison d\'Achab périra, et j\'exterminerai à Achab ceux qui pissent à la muraille, mineur et émancipé, en Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Et je réduirai la maison d\'Achab à l\'état de la maison de Jéroboam, fils de Nebat, et à l\'état de la maison de Baësa, fils d\'Ahia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Et Jézabel sera dévorée par les chiens dans le clos de Jizréel, et personne ne lui donnera la sépulture. Et il ouvrit la porte et s\'enfuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Et Jéhu sortit vers les serviteurs de son. Maître. Alors on lui dit: Est-ce bonne nouvelle? Pourquoi ce frénétique est-il venu te trouver? Et il leur dit: Vous connaissez l\'homme et sa manie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Et ils lui dirent: Défaite! Ouvre-toi donc à nous! Et il dit: il m\'a parlé dans tel et tel sens disant: Ainsi parle l\'Éternel: Je t\'oins roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Et aussitôt prenant chacun leurs habits ils les étendirent sous ses pieds sur les gradins mêmes et ils sonnèrent de la trompette et dirent: Jéhu est roi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'C\'est ainsi que Jéhu, fils de Josaphat, fils de Nimsi, conspira contre Joram. (Or Joram défendait Ramoth en Galaad, lui et tous les Israélites, contre Hazaël, roi de Syrie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'et le roi Joram était revenu se rétablir à Jizréel des blessures qu\'il avait reçues des Syriens lorsqu\'il se battait contre Hazaël, roi de Syrie). Et Jéhu dit: Si c\'est votre sentiment, aucun fugitif ne sortira, de la ville pour s\'en aller avertir à Jizréel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'et Jéhu monta sur son char et gagna Jizréel, car Joram y était alité, et Achazia, roi de Juda, était descendu pour visiter Joram.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Cependant la sentinelle se tenait, sur la tour à Jizréel et vit. arriver la troupe de Jéhu et dit: Je vois une troupe. Et Joram dit: Prends un cavalier et le dépêche à sa rencontre pour demander si c\'est la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Et l\'homme à cheval alla au-devant de lui et dit: Ainsi parle le roi: Est-ce la paix? Et Jéhu dit: Que te fait la paix? Passe à ma suite. Et la sentinelle fit rapport et dit: Le courrier est arrivé vers eux, mais pas revenu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Alors il dépêcha un second cavalier qui arriva vers, eux et dit: Ainsi parle le roi: Est-ce la paix? Et Jéhu dit: Que te fait la paix? Passe à ma suite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Et la sentinelle fit rapport et dit: il est arrivé vers eux, mais pas revenu. C\'est un train, comme le train, de Jéhu, fils de Nimsi, qui toujours va d\'un train furieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Alors Joram dit: Attelle! Et l\'on attela son char. Et Joram, roi d\'Israël, et Achazia, roi de Juda, sortirent chacun sur son char et s\'avancèrent au-devant de Jéhu qu\'ils trouvèrent au clos de Naboth de Jizréel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Et lorsque Joram vit Jéhu, il dit: Est-ce la paix, Jéhu? Et celui-ci dit: Quoi! la paix tant que durent les adultères de Jézabel, ta mère, et ses sortilèges multipliés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Et Joram tourna bride et s\'enfuit, et il dit à Achazia: Trahison! Achazia!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Mais Jéhu arma sa main de l\'arc et frappa Joram entre les épaules de telle sorte que le trait ressortit par le cœur, et il s\'affaissa dans son char.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Et Jéhu dit à Bidecar, son adjudant: Enlève-le et le jette dans le clos de Naboth de Jizréel. Car rappelle-toi comment nous chevauchions moi et toi de pair derrière Achab, son père, et que l\'Éternel a prononcé contre lui cette menace:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Certes j\'ai vu hier le sang de Naboth et le sang de ses fils, déclare l\'Éternel, et je te rendrai la pareille dans ce clos même, déclare l\'Éternel. Enlève-le donc et le jette dans le clos selon la parole de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Et Achazia, roi de Juda, vit et s\'enfuit vers le pavillon du jardin. Et Jéhu le poursuivit et dit: Frappez aussi celui-là sur son char! Ce fut sur la hauteur de Gur près de Jibleam. Et il se réfugia à Megiddo où il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Et ses serviteurs le transférèrent à Jérusalem, et lui donnèrent la sépulture dans son tombeau à côté de ses pères dans la ville de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'C\'est la onzième année de Joram, fils d\'Achab, que Achazia était devenu roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Et Jéhu vint à Jizréel. A cette nouvelle Jézabel appliqua le fard à ses yeux et se para la tête, et se mit à la fenêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Et lorsque Jéhu arriva dans le portail, elle dit: Est-ce la paix, [nouveau] Zimri, assassin de son Maître?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Et il leva les yeux vers la fenêtre et dit: Qui tient mon parti? qui? Et deux ou trois eunuques se penchèrent vers lui en avant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Et il dit: Précipitez-la! Et ils la précipitèrent, et il jaillit de son sang sur la muraille et sur les chevaux qui la foulèrent sous leurs pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Et il entra et mangea et but et dit: Prenez soin de cette maudite, et lui donnez la sépulture, car elle est fille de roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Et ils se mirent en devoir de lui donner la sépulture; mais ils ne retrouvèrent rien d\'elle sauf le crâne et les pieds et les paumes des mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Et ils revinrent l\'informer; et il dit: C\'est la menace de l\'Éternel qu\'il a prononcée par l\'organe de son serviteur, Élie de Thisbé, en ces termes: Dans le clos de Jizréel les chiens mangeront la chair de Jézabel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'et le cadavre de Jézabel jonchera comme du fumier le clos de Jizréel de sorte qu\'on ne puisse dire: C\'est Jézabel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Cependant il y avait d\'Achab à Samarie soixante-dix fils. Et Jéhu écrivit des lettres et les envoya à Samarie aux chefs de Jizréel, les Anciens, et à ceux par qui Achab faisait élever ses enfants, et elles disaient:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, '... « lors donc que cette lettre vous parviendra, puisque vous avez à votre portée les fils de votre Souverain et les chars et les chevaux et une place forte et des armes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'choisissez le plus probe et le plus apte des enfants de votre Souverain et placez-le sur le trône de son père, et combattez pour la maison de votre Souverain! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Mais ils eurent une très grande peur et dirent: Voici, les deux rois ne lui ont pas tenu tête, comment donc lui tiendrions-nous tête, nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Et ils déléguèrent le préfet du palais et le préfet de la ville et les Anciens et les éducateurs vers Jéhu pour dire: Nous sommes tes serviteurs et nous ferons tout ce que tu nous diras; nous ne ferons pas de roi; agis comme il te semblera bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Alors il leur écrivit une seconde lettre ainsi conçue: « Si vous êtes à moi et obéissez à ma voix, prenez les têtes des hommes, fils de votre Souverain, et venez auprès de moi demain à pareille heure à Jizréel. » (Or les fils du roi, soixante-dix hommes, étaient chez les Grands de la ville qui les avaient élevés.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Et à la réception de cette lettre ils prirent les fils du roi et les égorgèrent au nombre de soixante-dix hommes, et ils mirent leurs têtes dans des corbeilles et les lui envoyèrent à Jizréel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Puis entra le messager qui fit rapport en ces termes: Ils ont apporté les têtes des fils du roi. Et il dit: Mettez-les en deux tas dans l\'avenue de la Porte jusqu\'au matin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Et le matin il sortit et se présenta et dit à tout le peuple: Vous êtes justes; voici, quant à moi, j\'ai conspiré contre mon Souverain et l\'ai tué; et qui a frappé tous ceux-ci?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Sachez en effet qu\'il ne tombe rien a terre de la menace de l\'Éternel que l\'Éternel a prononcée contre la maison d\'Achab; et l\'Éternel a exécuté ce qu\'il avait dit par l\'organe de son serviteur Élie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Et Jéhu fit main basse sur tous les survivants de la maison d\'Achab à Jizréel, et sur tous ses Grands, et sur tous ses familiers et sur tous ses prêtres, jusqu\'à ne pas lui laisser un seul survivant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Et il se leva et partit et gagna Samarie. Jéhu se trouvait à la maison du Rendez-vous des bergers sur la route,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'lorsqu\'il eut la rencontre des frères d\'Achazia, roi de Juda, et il dit: Qui êtes-vous? Et ils dirent: Nous sommes les frères d\'Achazia, et nous descendons pour saluer les fils du roi et les fils de la reine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Et il dit: Saisissez-les tout vifs! Et ils les saisirent tout vifs et les égorgèrent à la citerne de la maison du Rendez-vous, au nombre de quarante-deux hommes; et il n\'en laissa survivre aucun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Et étant parti de là il rencontra Jonadab, fils de Rechab, qui venait au-devant de lui, et il le salua et lui dit: Ton cœur est-il sincère, comme mon cœur est sincère pour le tien? Et Jonadab dit: Il l\'est. — S\'il l\'est, donne-moi ta main! — Et il lui donna sa main. Et Jéhu le fit monter à ses côtés sur son char');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'et dit: Accompagne-moi et sois témoin de mon zèle pour l\'Éternel. Il le fit donc cheminer avec lui sur son char.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Et arrivé à Samarie il fit main basse sur tous les survivants à Achab dans Samarie, jusqu\'à ce qu\'il en eût fini avec Achab, selon la parole de l\'Éternel qu\'il avait adressée à Élie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Et Jéhu assembla tout le peuple et il leur dit: Achab a un peu servi Baal, Jéhu le servira beaucoup.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Maintenant donc convoquez vers moi tous les prophètes de Baal, et tous ses serviteurs et tous ses prêtres: que nul ne manque! car j\'ai à offrir un grand sacrifice à Baal: qui manquera, perdra la vie. Mais Jéhu employait l\'artifice pour faire périr les serviteurs de Baal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Et Jéhu dit: Consacrez une fête: générale à Baal. Et elle fut proclamée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Et Jéhu fit faire le message dans tout Israël, et tous les serviteurs de Baal arrivèrent et il n\'en resta pas un qui ne vînt, et ils entrèrent dans le: temple de Baal, et le temple de Baal fut rempli d\'un bout à l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Et il dit à l\'intendant du vestiaire: Sors un habillement pour tous les Serviteurs de Baal. Et il sortit pour eux l\'habillement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Alors Jéhu avec Jonadab, fils de Rechab, vint au temple de Baal et. il; dit aux serviteurs de Baal: Cherchez et avisez, à ce qu\'il n\'y ait pas ici avec vous de serviteurs de l\'Éternel, mais des serviteurs de Baal seuls.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Et ils entrèrent pour sacrifier leurs victimes et leurs holocaustes. Cependant Jéhu avait, pour son but, posté à, l\'extérieur quatre-vingts hommes et dit: Qui laissera échapper un seul des hommes, que j\'ai mis à portée de vos mains, de sa vie payera la vie de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Et lorsque l\'on eut achevé d\'offrir les holocaustes, Jéhu dit aux coureurs et aux triaires: Entrez, frappez-les, que nul, ne ressorte! Et ils les frappèrent avec le tranchant de l\'épée. Et les coureurs et les triaires poussèrent en avant et gagnèrent la cité du temple de Baal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'et ils tirèrent les colonnes hors du temple de Baal et les brûlèrent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'et ils renversèrent la colonne de Baal, et renversèrent le temple de Baal et en firent un cloaque: ce qu\'il est aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'C\'est ainsi que Jéhu extermina Baal du sein d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Seulement il ne se départit pas des péchés de Jéroboam, fils de Nebat, où celui-ci avait entraîné Israël, des veaux d\'or de Béthel et de Dan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Et l\'Éternel dit à Jéhu: Parce que tu as bien agi en faisant ce qui est droit à mes yeux, et traitant la maison d\'Achab, tout à fait comme c\'était dans ma volonté, tu auras des fils, de la quatrième génération assis au trône d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Mais Jéhu ne prit point garde de pratiquer la loi de l\'Éternel, Dieu d\'Israël, de tout son cœur, il ne se départit point des péchés de Jéroboam où celui-ci avait entraîné Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Dans ce temps-là l\'Éternel commença à entamer Israël qu\'Hazaël battit dans toutes les limites d\'Israël');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'depuis le Jourdain au soleil levant, la totalité du pays de Galaad, les Gadites et les Rubénites, et, les Manassites depuis. Aroër située sur la rivière de l\'Arnon jusques à Galaad et Basan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Le reste des actes de Jéhu et toutes ses entreprises et tous ses exploits sont d\'ailleurs consignés dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Et Jéhu reposa à côté de ses pères, et on lui donna là sépulture à Samarie, et Joachaz, son fils, régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Or la durée du règne de Jéhu sur Israël fut de vingt-huit ans à Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Cependant Athalie, mère d\'Achazia, voyant son fils mort, se leva et fit périr toute la race royale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Alors Joséba, fille du roi Joram, sœur d\'Achazia, enleva Joas, fils d\'Achazia, et le déroba du milieu des fils du roi qui recevaient la mort, et le recela lui et sa nourrice dans la salle des lits. Et elles le cachèrent aux regards d\'Athalie en sorte qu\'il ne fut pas mis à mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'et il fut caché six ans avec elle dans le temple de l\'Éternel. Or Athalie régissait le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Et la septième année, Jehojada envoya chercher les centurions des satellites et des coureurs, et il les fit venir chez lui dans le temple de l\'Éternel et conclut avec eux un accord, et les assermenta dans le temple de l\'Éternel et leur montra le fils du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Et il leur donna ses ordres en ces termes: Voici ce que vous avez à faire: Un tiers d\'entre vous qui entrez en service le jour du sabbat, gardera le palais royal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'et un tiers occupera la porte Sur (latérale), et un tiers la porte derrière les coureurs, et vous garderez ainsi le palais, en arrêt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Et les deux sections que vous formez, vous tous qui êtes relevés le jour du sabbat [de la garde du palais], monteront la garde dans le temple de l\'Éternel auprès du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Et entourez le roi de toutes parts, ayant chacun ses armes à la main; et mort à qui s\'introduira entre les rangs! et accompagnez le roi à sa sortie et à son entrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Et les centurions exécutèrent tous les ordres du Prêtre Jehojada, et ils prirent chacun son monde, savoir et ceux qui montaient et ceux qui descendaient la garde le jour du sabbat, et joignirent le Prêtre Jehojada.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Et le Prêtre remit aux centurions les piques et les boucliers du roi David, qui étaient dans le temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Et les coureurs, chacun ses armes à la main, se portèrent depuis le côté droit au côté gauche du temple, et à l\'autel vers le Temple à l\'entour du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Et il produisit le fils du roi et il le couvrit de la couronne et lui remit la Loi; et ils le constituèrent roi et l\'oignirent et frappèrent des mains et crièrent: Vive le Roi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Alors Athalie entendit les voix des coureurs et du peuple et elle se porta vers le peuple dans le temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Et elle regarda, et voilà que le roi se tenait sur le palier selon l\'usage et aux côtés du roi les centurions et les trompettes et tout le peuple du pays joyeux et sonnant de la trompette.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Alors Athalie déchira ses vêtements et s\'écria: Complot! Complot! Mais le Prêtre Jehojada fit aux centurions, généraux de l\'armée, ce commandement: Tirez-la jusqu\'entre les rangs! et tuez avec l\'épée quiconque la suivra! Car le Prêtre disait: Qu\'elle ne reçoive pas la mort dans le temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Et pour lui faire place ils formèrent deux lignes, et elle arriva par la voie du passage des chevaux au palais royal, où elle reçut la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Et Jehojada solennisa l\'alliance entre l\'Éternel et le roi et le peuple, stipulant qu\'il serait le peuple de l\'Éternel, et entre le roi et le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Alors toute la population du pays envahit le temple de Baal, et ils le démolirent et brisèrent ses autels et ses simulacres, à fond, et égorgèrent Mathan, prêtre de Baal, devant les autels. Et le Prêtre préposa des préfectures sur le temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Et il prit les centurions et les satellites et les coureurs et tout le peuple du pays, et ils firent descendre le roi du temple de l\'Éternel, et passant par la porte des coureurs ils arrivèrent au palais royal, et le roi prit place sur le trône des rois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Et tout le peuple du pays était dans l\'allégresse, et la ville était tranquille: quant à Athalie, ils lui avaient donné la mort avec l\'épée au palais royal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Joas avait sept ans à son avènement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Ce fut la septième année de Jéhu que Joas devint roi, et il régna quarante ans à Jérusalem. Or le nom de sa mère était Tsibia de Béerséba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Et Joas pratiqua ce qui est droit aux yeux de l\'Éternel, aussi longtemps qu\'il eut les directions du Prêtre Jehojada.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Seulement les tertres ne disparurent pas; le peuple offrait encore des victimes et de l\'encens sur les tertres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Et Joas dit aux Prêtres: Tout l\'argent consacré qui est apporté au temple de l\'Éternel, argent ayant cours, l\'argent pour la vie payé par chacun d\'après son estimation, tout l\'argent que le cœur suggère à quelqu\'un d\'apporter au temple de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'que les Prêtres le retirent chacun de ses relations et l\'emploient à réparer les brèches du temple partout où il s\'y trouvera une brèche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Et il arriva que, la vingt-troisième année du roi Joas, les Prêtres n\'avaient point réparé les brèches du temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Alors le roi Joas manda le Prêtre Jehojada et les Prêtres et leur dit: Pourquoi ne réparez-vous pas les brèches du temple? Eh bien! donc vous n\'avez plus à retirer d\'argent de vos relations, car vous devez l\'affecter aux brèches du temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Et les Prêtres consentirent à ne plus retirer l\'argent du peuple et à ne pas réparer les brèches du temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Et le Prêtre Jehojada prit un coffre au couvercle duquel il perça un trou et qu\'il plaça à côté de l\'autel à droite; quelqu\'un entrait-il au temple de l\'Éternel, les Prêtres, gardes du seuil, y jetaient tout l\'argent apporté au temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Et quand ils virent il qu\'il y avait beaucoup d\'argent dans le coffre, le Secrétaire du roi et le Grand Prêtre vinrent, et ils en firent des rouleaux, et comptèrent cet argent qui se trouvait dans le temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Et ils remirent l\'argent, pesé, entre les mains des entrepreneurs de l\'ouvrage employés au temple de l\'Éternel, et ceux-ci en payèrent les charpentiers et architectes occupés au temple de l\'Éternel');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'et les maçons et tailleurs de pierre, et les achats de bois et de pierre de taille pour la réparation des brèches du temple de l\'Éternel, et toutes les dépenses faites au temple pour la restauration.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Cependant pour le temple de l\'Éternel on ne fit ni bassins d\'argent, ni couteaux, ni jattes, ni trompettes, ni vaisselle quelconque d\'or et d\'argent, avec l\'argent entré au temple de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'mais on l\'employa à payer ceux qui firent l\'ouvrage, et qui l\'appliquèrent à la restauration du temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Et l\'on ne compta point avec les hommes entre les mains desquels on avait remis l\'argent pour en payer les ouvriers, car c\'est avec bonne foi qu\'ils agissaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'L\'amende pour délit et l\'amende pour péché');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'n\'entrèrent point dans le temple de l\'Éternel; elles furent pour les Prêtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'C\'est alors que Hazaël, roi de Syrie, s\'avança et vint attaquer Gath dont il s\'empara. Et Hazaël ayant résolu de marcher sur Jérusalem, Joas, roi de Juda, prit toutes les choses consacrées qu\'avaient consacrées Josaphat et Joram et Achazia, ses pères, rois de Juda, et ce qu\'il avait consacré lui-même et tout l\'or qui se trouvait dans les trésors du temple de l\'Éternel et du palais royal, et envoya le tout à Hazaël, roi de Syrie. Et Hazaël s\'éloigna de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Le reste des actes de Joas et toutes ses entreprises sont d\'ailleurs consignés dans le livre des annales des rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Et ses serviteurs se levèrent et formèrent une conjuration et frappèrent Joas à Beth-Millo, qui descend à Silla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Et Jozachar, fils de Simeath, et Jozabad, fils de Somer, ses serviteurs, lui portèrent les coups dont il mourut; et ils lui donnèrent la sépulture à côté de ses pères dans la ville de David. Et Amatsia, son fils, régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'La vingt-troisième année de Joas, fils d\'Achazia, roi de Juda, Joachaz, fils de Jéhu, devint roi d\'Israël à Samarie pour dix-sept ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Et il fit ce qui est mal aux yeux de l\'Éternel, et dans sa conduite continua les péchés de Jéroboam, fils de Nebat, où celui-ci avait entraîné Israël, et il ne s\'en départit point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Dès lors le courroux de l\'Éternel s\'alluma contre Israël qu\'il livra aux mains de Hazaël, roi de Syrie, et aux mains de Ben-Hadad, fils de Hazaël, tout ce temps-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Alors Joachaz chercha à apaiser l\'Éternel, et l\'Éternel l\'exauça, car Il voyait l\'oppression d\'Israël opprimé par le roi-de Syrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Et l\'Éternel accorda aux Israélites un sauveur, et ils secouèrent le joug de la Syrie, et les enfants d\'Israël purent rester sous leurs tentes comme autrefois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Néanmoins ils ne se départirent pas des péchés delà maison de Jéroboam, où elle avait entraîné Israël; ils y persévérèrent et même Astarté resta debout à Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Aussi bien Il n\'avait laissé à Joachaz en fait de troupes que cinquante cavaliers et dix chars et dix mille hommes de pied; en effet, le roi de Syrie les avait taillés en pièces et réduits à l\'état de la poussière qu\'on foule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Le reste des actes de Joachaz et toutes ses entreprises et ses exploits sont d\'ailleurs consignés dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Et Joachaz reposa avec ses pères et reçut la sépulture à Samarie, et Joas, son fils, régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'La trente-septième année de Joas, roi de Juda, Joas, fils de Joachaz, devint roi d\'Israël à Samarie pour seize ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Et il fit ce qui est mal aux yeux de l\'Éternel, il ne se départit d\'aucun des péchés de Jéroboam, fils de Nebat, qui avait fait pécher Israël; il y persévéra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Le reste des actes de Joas et toutes ses entreprises et ses exploits, la guerre qu\'il eut avec Amatsia, roi de Juda, sont d\'ailleurs consignés dans le livre des annales dès rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Et Joas reposa à côté de ses pères, et Jéroboam s\'assit sur son trône et Joas reçut la sépulture à Samarie à côté des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Cependant Elisée tomba malade de la maladie dont il mourut. Alors Joas, roi d\'Israël, descendit chez lui et pleura penché sur son visage et dit: Mon père! mon père! Char d\'Israël et ses cavaliers!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Et Elisée lui dit: Prends un arc et des flèches! et il se munit d\'un arc et de flèches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Et il dit au roi d\'Israël: De ta main arme l\'arc! et de sa main il arma, et Elisée posa ses mains sur les mains du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Puis il dit: Ouvre la fenêtre à l\'orient! Et il l\'ouvrit. Et Elisée dit: Tire. Et il tira. Et Elisée dit: Flèche de victoire de par l\'Éternel et flèche de victoire sur la Syrie! tu battras donc les Syriens à Aphek jusqu\'à extermination.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Et il dit: Prends les flèches! Et il les prit. Et il dit au roi d\'Israël: Frappe contre le sol! Et il frappa trois fois, puis s\'arrêta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Alors l\'homme de Dieu s\'irrita contre lui et dit: Il y avait à frapper cinq ou six fois; alors tu battais les Syriens jusqu\'à extermination; mais maintenant tu battras les Syriens trois fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Et Elisée mourut et on lui donna la sépulture. Et les bandes des Moabites envahissaient le pays, quand venait la [nouvelle] année.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Et il advint qu\'ils donnèrent la sépulture à un homme, et voilà qu\'ils aperçurent les bandes: aussitôt ils jetèrent l\'homme dans le tombeau d\'Elisée, puis partirent; et l\'homme fut en contact avec les os d\'Elisée et il reprit vie et se dressa sur ses pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Cependant Hazaël, roi de Syrie, avait opprimé les Israélites durant toute la vie de Joachaz.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Mais l\'Éternel leur fut propice et prit pitié d\'eux et tourna ses regards vers eux, eu égard à son alliance avec Abraham, Isaac et Jacob, et Il ne voulut pas les détruire et ne les bandit point de sa présence jusqu\'à présent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Et Hazaël, roi de Syrie, mourût, et Ben-Hadad, son fils, régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Alors Joas, fils de Joachaz, reprit des mains de Ben-Hadad, fils de Hazaël, les villes que celui-ci avait enlevées à Joachaz, son père, dans la guerre. Joas le battit trois fois et recouvra les villes d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'La deuxième année de Joas, fils de Joachaz, roi d\'Israël, Amatsia, fils de Joas, roi de Juda, devint roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Il avait vingt-cinq ans à son avènement et il régna vingt-neuf ans à Jérusalem. Or, le nom de sa mère était Joadan de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Et il fit ce qui est droit aux yeux de l\'Éternel, toutefois pas à l\'égal de David, son père: il agit entièrement comme avait agi Joas, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Seulement les tertres ne disparurent pas; le peuple offrait encore des victimes et de l\'encens sur les tertres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Et lorsque la royauté fut affermie dans sa main, il fit main basse sur ceux de ses serviteurs qui avaient fait main basse sur le roi, son père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'mais les fils des meurtriers, il ne les mit pas à mort, aux termes du livre de la Loi de Moïse et de ce que l\'Éternel avait prescrit en disant: Les pères ne subiront pas la mort pour les fils, ni les fils pour les pères, mais chacun subira la mort pour son péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Il battit les Edomites dans la Vallée du sel, dix mille hommes, et prit Séla dans la guerre et l\'appela du nom de Jockthéel qu\'elle porte encore aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'C\'est alors qu\'Amatsia envoya des messagers à Joas, fils de Joachaz, fils de Jéhu, roi d\'Israël, pour dire: Viens! il faut que nous nous voyions en face.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Alors Joas, roi d\'Israël, députa vers Amatsia, roi de Juda, avec cette réponse: L\'épine du Liban fit-porter au Cèdre du Liban ce message: Donne ta fille en mariage à mon fils. Alors les bêtes sauvages du Liban passèrent sur l\'épine et l\'écrasèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Tu as bien battu les Edomites, et ton cœur t\'a exalté: sois glorieux! mais reste chez toi! Pourquoi veux-tu te mettre aux prises avec le malheur pour succomber, toi et Juda avec toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Mais Amatsia n\'écouta point, et Joas, roi d\'Israël, s\'avança, et ils se trouvèrent en présence, lui et Amatsia, roi de Juda, à Bethsémès, qui est à Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Mais Juda fut défait par Israël, et chacun s\'enfuit dans sa tente:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'et Amatsia, roi de Juda, fils de Joas, fils d\'Achazia, fut fait prisonnier à Bethsémès par Joas, roi d\'Israël, qui vint à Jérusalem et fit une brèche au mur de Jérusalem à la porte d\'Ephraïm jusqu\'à la porte de l\'angle, espace de quatre cents coudées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'et il enleva la totalité de l\'or et de l\'argent et la totalité de la vaisselle, qui se trouva dans le temple de l\'Éternel et dans les trésors du palais royal, et les otages et regagna Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Le reste des actes de Joas, ses entreprises et ses exploits et la guerre qu\'il soutint contre Amatsia, roi de Juda, sont d\'ailleurs consignés dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Et Joas reposa avec ses pères et reçut la sépulture à Samarie à côté des rois d\'Israël, et Jéroboam, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Et Amatsia, fils de Joas, roi de Juda, survécut quinze ans après la mort de Joas, fils de Joachaz, roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Le reste des actes d\'Amatsia est d\'ailleurs consigné dans le livre des annales des rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Et l\'on forma contre lui une conjuration dans Jérusalem, et il s\'enfuit à Lachis et ils firent courir après lui à Lachis, et lui donnèrent la mort là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Et on le chargea sur les chevaux, et il reçut la sépulture dans Jérusalem à côté de ses pères dans la ville de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Alors tout le peuple de Juda prit Azaria, lequel avait seize ans, et l\'établit roi en la place de son père, Amatsia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'C\'est lui qui rebâtit Élath, l\'ayant reconquise à Juda, après que le roi fut couché à côté de ses pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'La quinzième année d\'Amatsia, fils de Joas, roi de Juda, Jéroboam, fils de Joas, roi d\'Israël, devint roi à Samarie pour quarante-un ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Et il fit ce qui est mal aux yeux de l\'Éternel; il ne se départit d\'aucun des péchés de Jéroboam, fils de Nebat, qui avait entraîné Israël à pécher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Il rétablit les frontières d\'Israël à partir de Hamath jusqu\'à la Mer de la Plaine, selon la parole de l\'Éternel, Dieu d\'Israël, qu\'il avait prononcée par l\'organe de son serviteur Jonas, fils d\'Amittaï, le prophète, originaire de Gath-Hépher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Car l\'Éternel voyait la misère d\'Israël, bien rebelle tout y étant à bout, mineurs et émancipés, et nul ne délivrant Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'et l\'Éternel n\'avait point parlé d\'effacer le nom d\'Israël de dessous les cieux, et Il leur vint en aide par le moyen de Jéroboam, fils de Joas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Le reste des actes de Jéroboam et toutes ses entreprises et ses exploits, ses guerres, et le recouvrement de Damas et de Hamath, [jadis] à Juda, par Israël, sont d\'ailleurs consignés dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Et Jéroboam reposa avec ses pères, avec les rois d\'Israël, et Zacharie, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'La vingt-septième année de Jéroboam, roi d\'Israël, Azaria, fils d\'Amatsia, roi de Juda, devint roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Il avait seize ans à son avènement, et il régna cinquante-deux ans à Jérusalem. Or, le nom de sa mère était Jecholia de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Et il fit ce qui est droit aux yeux de l\'Éternel tout comme avait fait Amatsia, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Seulement les tertres ne disparurent pas, le peuple offrait encore des victimes et de l\'encens sur les tertres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Et l\'Éternel infligea une plaie au roi, qui fut lépreux jusqu\'au jour de sa mort et demeura dans une infirmerie. Cependant Jotham, fils du roi, était préposé sur la Maison, rendant la justice au peuple du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Le reste des actes d\'Azaria et toutes ses entreprises sont d\'ailleurs consignés dans le livre des annales des rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Et Azaria reposa avec ses pères et on lui donna la sépulture avec ses pères dans la ville de David, et Jotham, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Là trente-huitième année d\'Azaria, roi de Juda, Zacharie, fils de Jéroboam, devint roi d\'Israël à Samarie pour six mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Et il fit ce qui est mal aux yeux de l\'Éternel comme avaient fait ses pères; il ne se départit point des péchés de Jéroboam, fils de Nebat, qui avait entraîné Israël à pécher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Et Sallum, fils de Jabès, conspira contre lui et fit main basse sur lui publiquement, et le tua et devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Le reste des actes de Zacharie est d\'ailleurs consigné dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'C\'est la parole de l\'Éternel qu\'il avait dite à Jéhu en ces termes: Tu auras des fils de la quatrième génération assis au trône d\'Israël, et il en fut ainsi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sallum, fils de Jabès, devint roi la trente-neuvième année d\'Hozias, roi de Juda, et régna un mois de temps à Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Et Menahem, fils de Gadi, s\'avança de Thirtsa, et entra dans Samarie, et fit main basse sur Sallum, fils de Jabès, dans Samarie, et lui donna la mort et devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Le reste des actes de Sallum, et sa conjuration qu\'il avait formée, sont d\'ailleurs consignés dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'C\'est alors que Menahem fit main basse sur Thiphsach et sur tous ceux qui y étaient, et sur tout son territoire à partir de Thirtsa; ce fut parce qu\'on ne lui ouvrit pas qu\'il porta ce coup; il y éventra toutes les femmes enceintes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'La trente-neuvième année d\'Azaria, roi de Juda, Menahem, fils de Gadi, devint roi d\'Israël, pour dix ans à Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Et il fit ce qui est mal aux yeux de l\'Éternel; il ne se départit point des péchés de Jéroboam, fils de Nebat, auxquels celui-ci avait entraîné Israël, toute sa vie durant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Phul, roi d\'Assyrie, fit invasion dans le pays, et Ménahem donna à Phul mille talents d\'argent afin qu\'il lui prêtât la main pour assurer la royauté dans sa propre main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Et Menahem tira cette somme à payer au roi d\'Assyrie, sur les Israélites, tous les gens à moyens, à raison de cinquante sicles d\'argent par individu. Puis le roi d\'Assyrie rebroussa sans séjourner alors dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Le reste des actes de Menahem et toutes ses entreprises sont d\'ailleurs consignés dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Et Menahem reposa avec ses pères, et Pekachia, son fils, devint roi à sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'La cinquantième année d\'Azaria roi de Juda, Pekachia, fils de Menahem, devint roi d\'Israël à Samarie, pour deux ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Et il fit ce qui est mal aux yeux de l\'Éternel; il ne se départit point des péchés de Jéroboam, fils de Nebat, auxquels celui-ci avait entraîné Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Et Pékach, fils de Remalia, son aide-de-camp, conspira contre lui et lui porta le coup dans Samarie au donjon du palais royal, en même temps qu\'à Argob et à Ariè; or il se trouvait avec lui cinquante hommes d\'entre les fils des Galaadites; c\'est ainsi qu\'il lui donna la mort et devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Le reste des actes de Pekachia et toutes ses entreprises sont d\'ailleurs consignés dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'La cinquante-deuxième année d\'Azaria roi de Juda, Pékach, fils de Remalia, devint roi d\'Israël à Samarie pour vingt ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Et il fit ce qui est mal aux yeux de l\'Éternel; il ne se départit point des péchés de Jéroboam, fils de Nebat, auxquels celui-ci avait entraîné Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Au temps de Pékach, roi d\'Israël, Thiglath-Piléser, roi d\'Assyrie, vint et prit Ijon et Abel-Beth-Maacha et Janoha et Kédès et Hatsor et Galaad et la Galilée, tout le territoire de Nephthali, et il les emmena captifs en Assyrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Et Hosée, fils d\'Éla, forma une conspiration contre Pékach, fils de Remalia, et fit main basse sur lui et lui donna la mort et devint roi en sa place la vingtième année de Jotham, fils d\'Hozias.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Le reste des actes de Pékach et toutes ses entreprises, sont d\'ailleurs consignés dans le livre des annales des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'La seconde année de Pékach, fils de Remalia, roi d\'Israël, Jotham, fils d\'Hozias, roi de Juda, devint roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Il avait vingt-cinq ans à son avènement et il régna seize ans à Jérusalem. Or le nom de sa mère était Jérusa, fille de Tsadoc.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Et il fit ce qui est droit aux yeux de l\'Éternel; il agit en tout comme avait agi Hozias, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Seulement les tertres ne disparurent pas; le peuple offrait encore des victimes et de l\'encens sur les tertres. Il construisit la porte supérieure du temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Le reste des actes, de Jotham et toutes ses entreprises sont d\'ailleurs consignés dans le livre des annales des rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'Dans ce même temps l\'Éternel commença à envoyer contre Juda, Retsin, roi de Syrie, et Pékach, fils de Remalia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Et Jotham reposa avec ses pères et reçut la sépulture avec ses pères dans la ville de David, son père, et Achaz, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'La dix-septième année de Pékach, fils de Remalia, Achaz, fils de Jotham, roi de Juda, devint roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Achaz avait vingt ans à son avènement: et il régna seize ans à Jérusalem. Et il ne fit pas ce qui est droit aux, yeux de l\'Éternel, son Dieu, comme David, son père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'et il marcha sur les errements des rois d\'Israël, et son fils même, il le fit passer [à Moloch] par le feu, selon les rites abominables, des nations que l\'Éternel avait chassées, devant les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Et il offrit des victimes et de l\'encens sur les tertres et sur les collines, et sous tout arbre vert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Alors Retsin, roi de Syrie, et Pékach, fils de Remalia, roi d\'Israël, s\'avancèrent à l\'attaque de Jérusalem, et ils bloquèrent Achaz, mais ils ne purent l\'emporter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Dans le même temps, Retsin, roi de Syrie, reconquit Élath à la Syrie, et expulsa les Juifs d\'Élath, et les Syriens entrèrent dans Élath, où ils sont demeurés jusqu\'à ce jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'A ce moment Achaz expédia des messagers à Thiglath-Piléser, roi d\'Assyrie, pour lui dire: Je suis ton serviteur et fils: arrive et me sauve des mains du roi de Syrie et de la paume du roi d\'Israël qui m\'assaillent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Et Achaz prit l\'argent et l\'or qui se trouvaient au temple de l\'Éternel et dans les trésors du palais royal, et envoya au roi d\'Assyrie un présent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Et le roi d\'Assyrie l\'exauça et le roi d\'Assyrie, marcha, sur Damas et s\'en empara et en déporta les habitants à Kir, et fit mourir Retsin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Puis le roi Achaz s\'avança à la rencontre de Thiglath-Piléser, roi d\'Assyrie, jusqu\'à Damas. Et ayant vu l\'autel qui était à Damas, le roi Achaz envoya au prêtre Urie la copie et le dessin de l\'autel dans toute sa structure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Et le prêtre Urie construisit l\'autel; et suivant en tout point ce que le roi Achaz avait envoyé de Damas, le prêtre Urie fit l\'autel, pour le retour du roi Achaz de Damas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Et le roi à son arrivée de Damas vit l\'autel, et le roi s\'approcha de l\'autel et y monta');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'et y fit fumer son holocauste et son offrande et y répandit ses libations, et fit sur l\'autel l\'aspersion du sang de son sacrifice pacifique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Quant à l\'autel d\'airain, qui était devant l\'Éternel, il l\'ôta de devant la façade du temple entre le [nouvel] autel et le temple de l\'Éternel, et le plaça à côté de l\'autel au nord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Et le roi Achaz donna ses ordres au prêtre Urie en ces termes: Sur le grand autel fais fumer l\'holocauste du matin, et l\'offrande du soir et l\'holocauste du roi et son offrande et les holocaustes de tout le peuple du pays et leurs offrandes et leurs libations et fais-y aspersion de tout le sang des holocaustes et de tout le sang des victimes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'quant à l\'autel d\'airain, je me consulterai: il sera à mon usage. Et le prêtre Urie agit en tous points selon les ordres du roi Achaz.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Et le roi Achaz brisa les panneaux des porte-aiguière et en détacha les bassins, il descendit la Mer de dessus les taureaux d\'airain qui lui servaient de support et la posa sur un piédestal de pierre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Et le portique du Sabbat qu\'on avait construit dans le temple et l\'avenue extérieure du roi, il les changea dans le temple de l\'Éternel, en vue du roi d\'Assyrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Le reste des actes d\'Achaz, ses entreprises, est d\'ailleurs consigné dans le livre des annales des rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Et Achaz reposa avec ses pères et reçut la sépulture avec ses pères dans la ville de David. Et Ezéchias, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'La douzième année d\'Achaz, roi de Juda, Hosée, fils d\'Éla, devint roi d\'Israël à Samarie, pour neuf ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Et il fit ce qui est mal aux yeux de l\'Éternel, seulement pas à l\'égal des rois d\'Israël, ses prédécesseurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Contre lui s\'avança Salmanassar, roi d\'Assyrie, et Hosée lui fut assujetti, et lui paya un tribut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Mais le roi d\'Assyrie découvrit une menée chez Hosée, lequel envoyait des messagers à So, roi d\'Egypte, et ne payait point le tribut au roi d\'Assyrie année par année; c\'est pourquoi le roi d\'Assyrie le fit prisonnier et le mit aux fers dans un cachot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Et le roi d\'Assyrie s\'avança sur tout le pays, et marcha contre Samarie qu\'il assiégea trois ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'La neuvième année d\'Hosée le roi d\'Assyrie prit Samarie et déporta les Israélites en Assyrie, et les établit à Chala et au Chabor, fleuve de Gozan, et dans les villes des Mèdes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'C\'est que les enfants d\'Israël s\'étaient rendus coupables envers l\'Éternel, leur Dieu, qui les avait retirés du pays d\'Egypte, de dessous la main de Pharaon, roi d\'Egypte, et qu\'ils révérèrent des dieux différents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'Et ils suivirent les us des nations que l\'Éternel avait chassées devant les enfants d\'Israël, et des rois d\'Israël qui les avaient institués.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Et les enfants d\'Israël firent parade de choses qui ne sont pas bien, en opposition à l\'Éternel, leur Dieu, et s\'élevèrent des tertres dans toutes leurs villes, depuis les tours d\'observation aux places fortes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Et ils se dressèrent des colonnes et des Astartés sur toute colline éminente, et sous tout arbre vert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'Et là ils offrirent l\'encens sur tous les tertres comme les nations que l\'Éternel avait exilées devant eux, et pratiquèrent des choses mauvaises pour provoquer l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Et ils servirent les idoles dont l\'Éternel leur avait dit: Vous n\'en ferez rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Et l\'Éternel somma Israël et Juda par l\'organe de tous ses prophètes, de tout Voyant, en ces termes: Quittez vos voies mauvaises et gardez mes commandements, mes statuts, d\'après toute la Loi que j\'ai prescrite à vos pères, et tous les messages que je vous ai envoyés par l\'organe de mes serviteurs les prophètes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Mais ils n\'écoutèrent point, ils roidirent leur col comme le col de leurs pères, qui n\'avaient pas cru en l\'Éternel, leur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Et ils méprisèrent ses statuts et son alliance qu\'il avait conclue avec leurs pères, et ses sommations qu\'il leur adressait, et ils suivirent les vaines idoles et s\'adonnèrent à la vanité, et imitèrent les nations de leurs alentours que l\'Éternel leur avait commandé de ne point imiter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Et ils négligèrent tous les commandements de l\'Éternel, leur Dieu, et se fabriquèrent des images de fonte, deux veaux, et ils se firent des Astartés, et adorèrent toute l\'armée des cieux, et rendirent un culte à Baal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Et ils firent passer par le feu leurs fils et leurs filles et pratiquèrent la divination et les augures et se vendirent pour faire ce qui est mal aux yeux de l\'Éternel, afin de le provoquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Alors l\'Éternel se courrouça fort contre Israël et Il les exclut de sa présence: il ne resta que la tribu de Juda seule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Même Juda ne garda pas les commandements de l\'Éternel, leur Dieu; ils marchèrent d\'après les statuts dressés par les Israélites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Ce qui fit que l\'Éternel répudia la totalité de la race d\'Israël qu\'il humilia et livra à la merci des spoliateurs jusque-là qu\'il les bannit de sa présence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'C\'est pourquoi Israël avait fait scission avec la maison de David, et s\'était donné pour roi Jéroboam, fils de Nebat, et Jéroboam avait débauché Israël du service de l\'Éternel et l\'avait entraîné à un péché grand.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Et les enfants d\'Israël persistèrent dans tous les péchés de Jéroboam, que celui-ci avait commis, et ne s\'en départirent pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'jusque là que l\'Éternel exclut Israël de sa présence, comme Il avait dit par l\'organe de tous ses serviteurs les prophètes, et Israël fut déporté de son pays en Assyrie; ce qu\'il est encore aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Et le roi d\'Assyrie fit venir [du monde] de Babel et de Cutha et de Arva et de Hamath et de Sepharvaïm, et il l\'établit dans les villes de la Samarie en place des enfants d\'Israël; et ils prirent possession de la Samarie et se domicilièrent dans les villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Et il arriva au début de l\'établissement de ces gens qui ne craignaient pas l\'Éternel, que l\'Éternel envoya contre eux les lions, qui firent du carnage parmi eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Alors ils s\'adressèrent au roi d\'Assyrie en ces termes: Les nations que tu as transportées et établies dans les villes de la Samarie, ne connaissent pas le rite du dieu du pays: aussi a-t-il envoyé contre eux les lions qui, voici, les tuent, parce qu\'ils ignorent, le rite du dieu du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Et le roi d\'Assyrie donna cet ordre: Ramenez-y l\'un des prêtres que vous avez emmenés de là en captivité; afin qu\'ils puissent aller y habiter étant initiés [par le prêtre] au rite du dieu du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Il vint donc un des prêtres qu\'ils avaient emmenés de Samarie, et il se fixa à Béthel, et il leur enseigna comment ils devaient célébrer le culte de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Cependant chaque peuplade se faisait d\'ailleurs son dieu, et elles les placèrent dans les temples des tertres élevés par les Samaritains, chacune dans les villes où elle était établie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Et les gens de Babel firent des loges de filles, et les gens de Cuth [l\'idole] Nergal, et les gens de Hamath, Asima,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'et les Avites, Nibchaz et Thirthak, et les Sepharvites brûlaient leurs fils dans le feu à Adrammelech et Anammelech, divinités de Sepharvaïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Et ils rendaient aussi un culte à l\'Éternel, et se créèrent de leur sein des prêtres pour les tertres, qui sacrifiaient pour eux dans les temples des tertres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Ils rendaient un culte à l\'Éternel et servaient leurs dieux selon le rite des nations d\'où on les avait transportés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Jusqu\'aujourd\'hui leur pratique est conforme à leurs premiers usages; ils ne rendent point un culte à l\'Éternel [seul]; et n\'agissent point [uniquement] d\'après leurs us, et coutumes, nom plus que d\'après la Loi et le Commandement prescrit par l\'Éternel aux fils de Jacob à qui Il avait donné le nom d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Car l\'Éternel avait conclu une alliance avec eux, et leur avait donné cet ordre: Vous ne craindrez pas d\'autres dieux et vous ne les adorerez pas et ne les servirez pas et ne leur ferez pas de sacrifices;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'mais l\'Éternel, qui vous a retirés du pays d\'Egypte avec une grande puissance et le bras étendu, c\'est Lui que vous craindrez, adorerez, Lui à qui vous offrirez des sacrifices;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'et les statuts et les rites et la Loi et le Commandement qu\'il vous a donnés par écrit, c\'est ce que vous observerez pour le pratiquer en tout temps, sans craindre d\'autres dieux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'et l\'alliance que J\'ai conclue avec vous, vous ne l\'oublierez pas, et vous ne craindrez pas d\'autres dieux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'mais l\'Éternel, votre Dieu, vous le craindrez, et Il vous sauvera de la main de tous vos ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Mais ils n\'obéirent pas; au contraire, ils se réglèrent d\'après leurs premiers usages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'C\'est ainsi que ces nations, tout en rendant un culte à l\'Éternel, servaient leurs idoles, et leurs enfants et petits-enfants agissent aujourd\'hui encore, comme ont agi leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'La troisième année d\'Hosée, fils d\'Éla, roi d\'Israël, Ezéchias, fils d\'Achaz, roi de Juda, devint roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Il avait vingt-cinq ans à son avènement et il régna vingt-neuf ans à Jérusalem. Or le nom de sa mère était Abi, fille de Zacharie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Et il fit ce qui est droit aux yeux de l\'Éternel, en tout point comme David, son père, avait fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Lui il abolit les tertres, et brisa les colonnes et extirpa les Aschères, et mit en pièces le serpent d\'airain qu\'avait fait Moïse; car jusqu\'à cette époque les enfants d\'Israël l\'avaient encensé, et on l\'appelait Nehustan (serpent d\'airain).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'C\'est dans l\'Éternel, Dieu d\'Israël, qu\'il mit sa confiance et après lui il n\'y eut pas son pareil entre tous les rois de Juda, non plus que parmi ses prédécesseurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Et il fut attaché à l\'Éternel: il ne Le déserta point, et il garda ses commandements, que l\'Éternel avait prescrits à Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Et l\'Éternel fut avec lui: il réussit dans toutes ses expéditions. Et il rompit avec le roi d\'Assyrie et ne fut point dans sa dépendance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Il battit les Philistins jusqu\'à Gaza et [ravagea] leur territoire depuis la tour d\'observation aux villes fortes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Et la quatrième année du roi Ezéchias, qui est la septième année d\'Hosée, fils d\'Éla, roi d\'Israël, Salmanassar, roi d\'Assyrie, s\'avança contre Samarie et l\'assiégea,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'et s\'en empara au bout de trois ans: ce fut la sixième année d\'Ezéchias, c\'est-à-dire, la neuvième année d\'Hosée, roi d\'Israël, que Samarie fut prise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Et et roi d\'Assyrie déporta les Israélites en Assyrie et les établit à Halah et au Chabor, fleuve de Gozan, et dans les villes des Mèdes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'parce qu\'ils n\'avaient pas écouté la voix de l\'Éternel, leur Dieu, et qu\'ils avaient transgressé son alliance: tout ce qu\'avait prescrit Moïse, serviteur de l\'Éternel, ils ne l\'avaient ni écouté, ni fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'La quatorzième année du roi Ezéchias, Sanchérib, roi d\'Assyrie, s\'avança contre toutes les villes fortes de Juda, et s\'en empara.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Alors Ezéchias, roi de Juda, dépêcha vers le roi d\'Assyrie à Lachis pour lui dire: J\'ai forfait! retire-toi de chez moi et je subirai ce que tu m\'imposeras. Et le roi d\'Assyrie imposa à Ezéchias, roi de Juda, trois cents talents d\'argent et trente talents d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Et Ezéchias délivra tout l\'argent qui se trouvait dans le temple de l\'Éternel et dans les trésors du palais royal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Dans cette circonstance Ezéchias coupa les portes du temple de l\'Éternel et leurs cadres qu\'avait plaqués Ezéchias, roi de Juda, et les remit au roi d\'Assyrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Néanmoins le roi d\'Assyrie envoya Tharthan et Rabsaris et Rabsaké de Lachis contre le roi Ezéchias avec des forces considérables à Jérusalem: et ils s\'avancèrent et arrivèrent à Jérusalem; et quand on se fut avancé et qu\'on fut arrivé, ils se placèrent à l\'aqueduc de l\'étang supérieur qui est sur le chemin du champ du foulon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Et ils appelèrent le roi. Alors sortit vers eux Eliakim, fils d\'Hilkia, préfet du palais, et Sebna, le Secrétaire, et Joah, fils d\'Asaph, le Chancelier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Et Rabsaké leur dit: Allez dire à Ezéchias: Ainsi parle le grand roi, le roi d\'Assyrie: Qu\'est-ce que cette confiance où tu mets ton appui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Tu dis (pur vain parler): J\'ai pour faire la guerre conseil et bravoure. Eh bien! sur qui as-tu mis ton appui pour rompre avec moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Eh bien! voilà que tu t\'appuies sur ce roseau cassé, sur l\'Egypte, lequel perce la main de qui s\'en étaie: tel est Pharaon, roi d\'Egypte, pour tous ceux qui s\'appuient sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Que si vous me dites: C\'est dans l\'Éternel, notre Dieu, que nous nous confions; n\'est-ce pas lui dont Ezéchias a aboli les tertres et les autels, et Ezéchias qui a dit à Juda et à Jérusalem: Devant cet autel vous adorerez à Jérusalem?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Maintenant donc fais un accord avec mon Maître, le roi d\'Assyrie, et je te donnerai deux mille chevaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'si tu peux te donner les cavaliers pour les monter. Et comment repousserais-tu un seul général des moindres serviteurs de mon Maître? mais tu te confies dans l\'Egypte pour chars et cavaliers!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Hé! est-ce sans l\'Éternel que je me suis avancé jusqu\'à cette place pour la saccager? L\'Éternel m\'a dit: Marche contre ce pays-là et le saccage!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Et Eliakim, fils d\'Hilkia, et Sebna et Joah dirent à Rabsaké: Parle donc à tes serviteurs dans la langue syrienne que nous comprenons et ne nous parle pas dans la langue juive aux oreilles de ce peuple qui est sur la muraille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Et Rabsaké leur dit: Est-ce à ton maître et à toi que mon Maître m\'a envoyé porter ces paroles? n\'est-ce pas aux gens assis sur la muraille pour manger leurs excréments et boire leur urine avec vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Se présentant alors, Rabsaké cria d\'une voix forte en langue juive, et parla et dit: Écoutez la parole du grand roi, roi d\'Assyrie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Ainsi parle le roi: Qu\'Ezéchias ne vous abuse pas, car il ne saurait vous sauver de ma main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Et qu\'Ezéchias ne vous fasse pas avoir confiance dans l\'Éternel en disant: L\'Éternel veut nous sauver et cette ville-ci ne sera point livrée aux mains du roi d\'Assyrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'N\'écoutez pas Ezéchias! car ainsi parle le roi d\'Assyrie: Faites amitié avec moi et passez de mon côté; et vous jouirez chacun de sa vigne, et chacun de son figuier, et vous vous désaltérerez chacun à l\'eau de sa citerne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'jusqu\'à ce que je vienne pour vous emmener dans un pays pareil à votre pays, dans un pays de blé et de vin, un pays de pain et de vignes, un pays d\'oliviers à huile, et de miel, et vous vivrez et ne mourrez pas. N\'écoutez donc pas Ezéchias, quand il vous leurre en disant: L\'Éternel nous sauvera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Les dieux des nations ont-ils, l\'un ou l\'autre, sauvé son pays de la main du roi d\'Assyrie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Où sont les dieux de Hamath ou d\'Arpad? Où les dieux de Sepharvaïm, Héna et Ivva, pour sauver Samarie de ma main?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Quels sont parmi tous les dieux des États ceux qui ont sauvé leur État de ma main pour croire que l\'Éternel sauvera Jérusalem de ma main?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Et le peuple fut muet et ne lui répondit mot, car tel était l\'ordre du roi qui avait dit: Ne répondez pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Et Eliakim, fils d\'Hilkia, préfet du palais, et Sebna, le Secrétaire, et Joah, fils d\'Asaph, le Chancelier, se présentèrent à Ezéchias, les habits déchirés, et lui redirent les discours de Rabsaké.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Et quand le roi Ezéchias entendit ce récit, il déchira ses habits et s\'enveloppa du cilice et gagna le temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Et il délégua Eliakim, préfet du palais, et Sebna, le Secrétaire, et les doyens des Prêtres, enveloppés de cilices, vers Ésaïe, le prophète, fils d\'Amots.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Et ils lui dirent: Ainsi parle Ezéchias: Ce jour est un jour de détresse et de châtiment et d\'opprobre! Car les enfants sont venus jusqu\'à l\'ouverture de la matrice, et la force manque pour l\'enfantement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Sans doute que l\'Éternel, ton Dieu, a l\'oreille ouverte à tous les discours de Rabsaké envoyé par le roi d\'Assyrie, son Maître, pour outrager le Dieu vivant, et qu\'il châtie ensuite des discours entendus par l\'Éternel, ton Dieu. Élève donc une prière en faveur du reste existant encore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Ainsi se présentèrent les serviteurs du roi Ezéchias chez Ésaïe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Et Ésaïe leur dit: Ainsi parle l\'Éternel: Parlez ainsi à votre Seigneur: Ne t\'effraie pas des discours que tu as entendus et par lesquels me bravent les valets du roi d\'Assyrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Voici, je vais l\'inspirer d\'un esprit, et il ouïra une nouvelle, qui lui feront regagner son pays, et je le ferai tomber sous l\'épée dans son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Et Rabsaké s\'en retourna et alla trouver le roi d\'Assyrie assiégeant Libna, car il avait appris son départ de Lachis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Alors il entendit parler de Thirhaka, roi d\'Ethiopie, dont on disait: Voilà qu\'il s\'est mis en campagne pour t\'attaquer. Et derechef il dépêcha des messagers à Ezéchias, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Ainsi parlez à Ezéchias, roi de Juda: Ne sois pas la dupe de ton Dieu en qui tu te confies, disant: Jérusalem ne sera point livrée aux mains du roi d\'Assyrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Voici, tu as appris ce qu\'ont fait les rois d\'Assyrie à tous les pays, comment ils les ont détruits; et toi, tu serais sauvé!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Est-ce que les dieux des nations que mes pères ont détruites, les ont sauvées, Gozan et Haran et Retseph et les fils d\'Eden en Thelassar?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Où est le roi de Hamath, et le roi d\'Arpad et le roi de la ville de Sepharvaïm, de Héna et Ivva?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Et Ezéchias reçut la lettre de la main des messagers, et la lut, puis monta au temple de l\'Éternel et la déploya devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Et Ezéchias fit sa prière devant l\'Éternel et dit: Éternel, Dieu d\'Israël, dont le trône est porté par les Chérubins, seul tu es le Dieu de tous les royaumes de la terre, c\'est toi qui as fait les cieux et la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Incline, Éternel, ton oreille et écoute, ouvre tes yeux, Éternel, et vois, et entends les discours de Sanchérib qu\'il a émis pour outrager le Dieu vivant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'C\'est vrai, Éternel! les rois d\'Assyrie ont désolé les nations et leur territoire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'et livré leurs dieux aux flammes, car ce ne sont pas des dieux, mais l\'ouvrage des mains de l\'homme, c\'est du bois et de la pierre, et ils les ont détruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Eh bien donc! Éternel, ô notre Dieu, viens nous sauver, de sa main, afin que tous les royaumes de la terre reconnaissent que seul, Éternel, tu es Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Alors Ésaïe, fils d\'Amots, envoya ce message à Ezéchias: Ainsi parle l\'Éternel, Dieu d\'Israël: La prière que tu m\'as adressée au sujet de Sanchérib, roi d\'Assyrie, je l\'ai ouïe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Voici la parole que l\'Éternel prononce sur lui: Elle te méprise, se rit de toi la vierge fille de Sion; derrière toi elle hoche la tête la fille de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Qui as-tu et bravé et outragé? et contre qui as-tu élevé la voix? et contre qui as-tu porté tes regards hautains?... Contre le Saint d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Par l\'organe de tes messagers tu as outragé le Seigneur, et dit: Avec le nombre de mes chars j\'ai escaladé les dernières cimes des montagnes aux côtés du Liban. Et j\'abattrai ses hauts cèdres et l\'élite de ses cyprès et je pénétrerai jusqu\'au gîte du sommet, au bois de son parc.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'J\'ai creusé et je me suis désaltéré à des eaux étrangères, et sous la plante de mes pieds je dessécherai tous les canaux de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'N\'as-tu pas entendu? De loin je l\'ai préparé, dès les temps anciens j\'en ai formé le plan; maintenant j\'amène pour effet que tu fais crouler les villes fortes en ruines désolées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'et leurs habitants, les bras raccourcis, furent éperdus et confus; ils devinrent comme le gazon des prés, comme la verdure de la plante, l\'herbe des toits et la nielle avant de lever.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Je sais quand tu t\'assieds, et sors et entres et quand tu te mutines contre moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Parce que tu te mutines contre moi, et que ta superbe est venue à mes oreilles, je mets ma boucle à ta narine et mon mors entre tes lèvres et je te ramène par la voie par où tu es venu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Et aie ceci comme signe: La première année vous mangerez le recru du blé, et la seconde année un grain spontané, et la troisième année semez et moissonnez et plantez des vignes et en mangez le fruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Et les réchappés de la maison de Juda, survivants, auront plus de racine en bas, et plus de fruit en haut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'car de Jérusalem il sortira un reste, et de la montagne de Sion des réchappés: le zèle de l\'Éternel opérera ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'C\'est pourquoi ainsi parle l\'Éternel touchant le roi d\'Assyrie: Il ne pénétrera point dans cette ville, et n\'y décochera point de flèches, et il ne l\'abordera point sous le bouclier et n\'élèvera point de terrasse contre elle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'le chemin qu\'il a pris, il le reprendra, et dans cette ville il ne pénétrera pas, prononce l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Car Je protège cette ville, afin de la sauver pour l\'amour de moi et pour l\'amour de David, mon serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Et il arriva la nuit même que l\'ange de l\'Éternel sortit et abattit dans le camp des Assyriens cent quatre-vingt-cinq mille hommes. Et quand au matin on se leva, voilà que c\'étaient tout autant de corps morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Alors Sanchérib, roi d\'Assyrie, décampa et partit et s\'en retourna et resta dans Ninive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Et comme il adorait dans le temple de Nisroch, son dieu, Adrammelech et Saresser le frappèrent avec l\'épée; quant à eux, ils se réfugièrent dans la contrée d\'Ararat. Et Assarhaddon, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'Dans ces jours-là Ezéchias fut malade à la mort. Alors Ésaïe, fils d\'Amots, le prophète, vint le trouver et lui dit: Ainsi parle l\'Éternel: Donne tes ordres pour ta maison, car tu mourras et ne guériras point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Alors Ezéchias tourna son visage vers la paroi et fit sa prière à l\'Éternel en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Oh! Éternel, daigne te rappeler que j\'ai marché en ta présence avec fidélité et avec un cœur non partagé, et pratiqué ce qui est bien à tes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Et Ezéchias versa d\'abondantes larmes. Et Ésaïe qui était sorti, n\'avait pas atteint le milieu de la cour, que la parole de l\'Éternel lui fut adressée en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Retourne et dis à Ezéchias, prince de mon peuple: Ainsi parle l\'Éternel, Dieu de David, ton père: J\'ai entendu ta prière, vu tes larmes; voici, je vais te rétablir: dans trois jours tu monteras au temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Et j\'ajouterai à tes jours quinze années et te sauverai de la main du roi d\'Assyrie, ainsi que cette ville, et je protégerai cette ville pour l\'amour de moi, et pour l\'amour de David, mon serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Et Ésaïe dit: Procurez un gâteau de figues. Et on l\'apporta, et l\'appliqua sur l\'ulcère, et il guérit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Et Ezéchias dit à Ésaïe: Quel signe me prouvera que l\'Éternel va me rétablir et que dans trois jours je monterai au temple de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Et Ésaïe dit: Aie ceci comme signe de par l\'Éternel de l\'exécution de la promesse à toi faite par l\'Éternel: L\'ombre doit-elle avancer de dix degrés ou reculer de dix degrés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Et Ezéchias dit: Il est facile que l\'ombre se projette de dix degrés: non! il faut que l\'ombre recule de dix degrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Alors Ésaïe, le prophète, invoqua l\'Éternel, et Il fit reculer l\'ombre au cadran solaire où elle était descendue, au cadran solaire d\'Achaz, de dix degrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Dans ce temps-là Berodach-Baladan, fils de Baladan, roi de Babel, envoya une lettre et un présent à Ezéchias, sur ce qu\'il avait appris la maladie d\'Ezéchias.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Et Ezéchias leur donna audience, et il leur montra tout son trésor, l\'argent et l\'or, et les aromates et l\'huile fine et tout son arsenal et tout ce qui se trouvait dans ses trésors; il n\'y eut rien qu\'Ezéchias ne leur montrât dans son palais et dans toute sa souveraineté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Alors Ésaïe, le prophète, vint trouver le roi Ezéchias et lui dit: Qu\'ont dit ces gens? et d\'où sont-ils venus chez toi? Et Ezéchias dit: Ils viennent d\'un pays lointain, de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Et Ésaïe dit: Qu\'ont-ils vu dans ton palais? Et Ezéchias dit: Ils ont vu tout ce qui est dans mon palais; il n\'est rien que je ne leur aie montré dans mes trésors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Alors Ésaïe dit à Ezéchias: Écoute la parole de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Voici, les jours viennent où sera emporté tout ce qui est dans ton palais et tout ce qu\'ont amassé tes pères jusqu\'à ce jour, à Babel; il ne restera rien, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Et parmi tes fils qui seront issus de toi, que tu engendreras, ils en prendront pour en faire des eunuques dans le palais du roi de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Et Ezéchias dit à Ésaïe: Bénigne est la parole de l\'Éternel que tu as exprimée! et il dit: Qu\'il y ait du moins ma vie durant salut et stabilité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Le reste des actes d\'Ezéchias, et tous ses exploits et l\'exécution de l\'étang et de l\'aqueduc, et l\'introduction de l\'eau dans la ville, cela est d\'ailleurs consigné dans le livre des annales des rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Et Ezéchias reposa avec ses pères, et Manassé, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, '1Manassé avait douze ans à son avènement, et il régna cinquante-cinq ans à Jérusalem. Or le nom de sa mère était Hephtsiba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Et il fit ce qui est mal aux yeux de l\'Éternel, imitant les pratiques abominables des nations que l\'Éternel avait chassées devant les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Et il releva les tertres qu\'avait rasés Ezéchias, son père, et dressa des autels à Baal et fit une Astarté comme avait fait Achab, roi d\'Israël, et il adora toute l\'armée des cieux, qu\'il servit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Et il érigea des autels dans le temple de l\'Éternel, dont l\'Éternel avait dit: C\'est dans Jérusalem que je fixerai mon Nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Et il bâtit des autels à toute l\'armée des cieux dans les deux parvis du temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Et il fit passer son fils par le feu, et s\'adonna à la divination et aux augures et institua des évocateurs et des devins et il multiplia le mal aux yeux de l\'Éternel à l\'effet de Le provoquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Et il plaça le simulacre d\'Astarté, qu\'il avait fait, dans le temple duquel l\'Éternel avait dit à David et à Salomon, son fils: Dans ce temple et à Jérusalem que j\'ai choisie dans toutes les Tribus d\'Israël, je fixerai mon Nom pour l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Et je ne veux plus qu\'Israël porte ses pas errants loin du sol que j\'ai donné à ses pères, pourvu seulement qu\'il prenne garde de se conformer à tout ce que je lui ai prescrit, et à la totalité de la Loi que lui a prescrite mon serviteur Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Mais ils n\'écoutèrent point, et Manassé les entraîna à faire pis que les nations que l\'Éternel avait détruites devant les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Et l\'Éternel parla par l\'organe de ses serviteurs, les prophètes, et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Parce que Manassé, roi de Juda, a pratiqué ces abominations faisant pis que tout ce qu\'avaient, fait les Amoréens, antérieurs à lui, et qu\'il a aussi entraîné Juda au péché par son idolâtrie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'dès là, ainsi prononce l\'Éternel, Dieu d\'Israël: Voici, j\'amène une calamité sur Jérusalem et Juda telle que à quiconque en ouïra parler les deux oreilles lui résonneront,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'et j\'étendrai sur Jérusalem le cordeau de Samarie et le niveau de la maison d\'Achab et je frotterai Jérusalem comme on frotte un plat: après l\'avoir frotté on le retourne sens dessus dessous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Et je ferai abandon du reste de mon héritage que je livrerai à la merci de leurs ennemis, afin qu\'ils soient une proie, une dépouille pour tous leurs ennemis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'parce qu\'ils ont fait ce qui est mal à mes yeux et qu\'ils m\'ont provoqué dès le jour où leurs pères sont sortis de l\'Egypte, jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Et Manassé répandit aussi le sang innocent à grands flots jusqu\'à en remplir Jérusalem d\'un bout à l\'autre bout, non compris son péché où il entraîna Juda pour faire ce qui est mal aux yeux de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Le reste des actes de Manassé, et toutes ses entreprises et son péché qu\'il commit, sont d\'ailleurs consignés dans le livre des annales des rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Et Manassé reposa avec ses pères et reçut la sépulture dans le jardin de son palais, dans le jardin d\'Uzza, et Amon, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Amon avait vingt-deux ans à son avènement, et il régna deux ans à Jérusalem. Or le nom de sa mère était Mesullémeth, fille de Harouts de Jotbah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Et il fit ce qui est mal aux yeux de l\'Éternel, comme avait fait Manassé, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Et il marcha sur tous les errements qu\'avait suivis son père, et servit les idoles qu\'avait servies son père, et il les adora,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'et il déserta l\'Éternel, le Dieu de ses pères, et ne pratiqua point la voie de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Et les serviteurs d\'Amon conspirèrent contre lui et donnèrent la mort au roi dans son palais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Mais le peuple du pays fit périr tous ceux qui avaient conspiré contre le roi Amon et le peuple du pays établit son fils Josias roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Le reste des actes d\'Amon, ses entreprises, est d\'ailleurs consigné dans le livre des annales des rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Et on lui donna la sépulture dans son tombeau, dans le jardin d\'Uzza, et Josias, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Josias avait huit ans à son avènement et il régna trente-un ans à Jérusalem. Or le nom de sa mère était Jedida, fille de Adaïa, de Botsekath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Et il fit ce qui est droit aux yeux de l\'Éternel, et marcha sur tous les errements de David, son père, et ne dévia ni à droite ni à gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Or il arriva la dix-huitième année de Josias que le roi envoya Saphan, fils d\'Atsalia, fils de Mesullam, le Secrétaire, au temple de l\'Éternel');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'avec cette instruction: Monte chez le Grand-Prêtre Hilkia, afin qu\'il délivre l\'argent entré au temple de l\'Éternel, que les portiers ont recueilli des mains du peuple, et qu\'on le dépose entre les mains des entrepreneurs préposés dans le temple de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'pour que ceux-ci en paient les ouvriers occupés dans le temple de l\'Éternel, à l\'effet de réparer les brèches de l\'édifice,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'les charpentiers et les architectes et les maçons, les achats de bois et de pierre de taille pour la restauration de l\'édifice,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'mais qu\'avec eux l\'on ne dresse pas un état de l\'argent remis entre leurs mains, car ils agissent avec bonne foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Alors le Grand-Prêtre Hilkia dit à Saphan, le Secrétaire: J\'ai trouvé le livre de la Loi dans le temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Et Hilkia remit le volume à Saphan, qui le lut. Et Saphan, le Secrétaire, vint chez le roi et rendit compte au roi et dit; Tes serviteurs ont déboursé l\'argent qui se trouvait dans le temple et l\'ont remis entre les mains des entrepreneurs préposés dans le temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Et Saphan, le Secrétaire, fit rapport au roi en ces termes: Le Prêtre Hilkia m\'a remis un livre. Et Saphan en fit la lecture devant le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Et lorsque le roi entendit le contenu du Livre de la Loi, il déchira ses habits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Et le roi donna ses ordres au Prêtre Hilkia et à Achikam, fils de Saphan, et à Achbor, fils de Michée, et à Saphan, le Secrétaire, et à Asaïa, serviteur du roi, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Allez et consultez l\'Éternel pour moi et pour le peuple et pour tout Juda au sujet du contenu de ce livre trouvé. Car grand est le courroux de l\'Éternel, allumé contre nous, parce que nos pères n\'ont pas écouté les paroles de ce livre pour se conformer à tout ce qui nous y est prescrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Alors le Prêtre Hilkia et Achikam et Achbor et Saphan et Asaïa se rendirent chez Hulda, la prophétesse, femme de Sallum, fils de Thikva, fils de Harhas, garde du vestiaire (or elle habitait à Jérusalem dans l\'autre quartier), et ils lui parlèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Et elle leur dit: Ainsi parle l\'Éternel, le Dieu d\'Israël: Dites à l\'homme qui vous délègue vers moi:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Ainsi parle l\'Éternel: Voici, j\'amène la calamité sur ce lieu et sur ses habitants, toutes les choses contenues dans le livre lu par le roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Puisqu\'ils m\'ont abandonné, et qu\'ils ont encensé d\'autres dieux, à l\'effet de me provoquer par tous les ouvrages de leurs mains, pour cela, mon courroux s\'est allumé contre ce lieu, et il ne s\'éteindra pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Quant au roi de Juda qui vous délègue pour consulter l\'Éternel, vous lui parlerez ainsi: Ainsi parle l\'Éternel, Dieu d\'Israël: Quant aux paroles que tu as entendues,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'puisque ton cœur est sensible et que tu t\'humilies devant l\'Éternel à l\'ouïe de ce que j\'ai prononcé contre ce lieu et ses habitants, qui seront l\'objet de la désolation et de la malédiction, et puisque tu as déchiré tes habits et pleuré devant moi, moi aussi j\'ai entendu, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'C\'est pourquoi voici, je te recueillerai auprès de tes pères et tu seras recueilli auprès de leurs tombeaux en paix et tes yeux n\'auront pas à voir toute la calamité que j\'amène sur ce lieu. Et ils rendirent au roi la réponse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Alors le roi donna commission et réunit vers lui tous les Anciens de Juda et de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Et le roi monta au temple de l\'Éternel et avec lui tous les hommes de Juda et tous les habitants de Jérusalem et les Prêtres et les prophètes et toute la population, petits et grands, et il lut à leurs oreilles toutes les paroles du livre de l\'alliance trouvé dans le temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Et le roi debout sur l\'estrade solennisa l\'alliance devant l\'Éternel, à l\'effet de suivre l\'Éternel et de garder ses commandements et ses témoignages et ses statuts du cœur tout entier et de l\'âme tout entière et d\'accomplir les articles de cette alliance, consignés dans le présent livre. Et tout le peuple adhéra à l\'alliance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Et le roi ordonna au Grand-Prêtre Hilkia et aux Prêtres du second rang et aux portiers de sortir du temple de l\'Éternel tous les meubles faits pour Baal et Astarté et toute l\'armée des cieux et il les brûla en dehors de Jérusalem dans les champs du Cédron, et en transporta la cendre à Béthel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Et il destitua les prêtres idolâtres qu\'avaient établis les rois de Juda, qui offraient de l\'encens sur les tertres dans les villes de Juda et aux alentours de Jérusalem, et ceux qui encensaient Baal, le soleil, et la lune et le Zodiaque, et toute l\'armée des cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Et du temple de l\'Éternel il transporta l\'Astarté hors de Jérusalem vers le torrent du Cédron, et il la brûla dans le ravin du Cédron, et il la réduisit en poudre, et en jeta la poudre sur les tombeaux des fils du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Et il démolit les maisons des garçons infâmes qui étaient dans le temple de l\'Éternel où les femmes tissaient des tentes pour Astarté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Et il fit arriver tous les Prêtres des villes de Juda, et il souilla les tertres où encensaient les prêtres depuis Gèba à Béerséba, et il démolit les tertres des portes, [celui] qui se trouve aux abords de la porte de Josué, préfet de la ville, et [celui] qui était à gauche dans la porte de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Pourtant les prêtres des tertres ne sacrifiaient pas sur l\'autel de l\'Éternel dans Jérusalem, mais ils mangeaient des azymes parmi leurs frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Et il souilla Topheth située dans la vallée des fils de Hinnom, pour que personne ne fit plus passer son fils et sa fille par le feu à Moloch.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Et il se défit des chevaux que les rois de Juda avaient dédiés au soleil près du temple de l\'Éternel vers le logis de Nethanmelech, l\'eunuque, lequel est dans le portique ouvert, et il brûla au feu les chars du soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Et le roi démolit les autels qui étaient sur la terrasse de l\'appartement supérieur d\'Achaz qu\'avaient bâtis les rois de Juda, et les autels qu\'avait bâtis Manassé dans les deux parvis de la Maison de l\'Éternel, et il s\'éloigna de là en hâte, et en jeta la poussière dans le torrent du Cédron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Et les tertres qui étaient devant Jérusalem à droite du Mont de la perdition, que Salomon, roi d\'Israël, avait élevés à Astarté, l\'odieuse idole des Sidoniens, et à Camos, l\'odieuse idole de Moab, et à Milcom, l\'abominable divinité des fils d\'Ammon, le roi les souilla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Et il brisa les colonnes, extirpa les Aschères et remplit leur emplacement d\'ossements humains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Et de même l\'autel qui était à Béthel, le tertre élevé par Jéroboam, fils de Nebat, qui avait entraîné Israël à pécher, cet autel-là aussi et le tertre il les démolit et il brûla le tertre et le réduisit en poudre, et il brûla l\'Astarté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Et en se tournant, Josias aperçut les tombeaux qui étaient là sur la montagne; puis il envoya enlever les ossements des tombeaux, et il les brûla sur l\'autel qu\'il souilla, selon la parole de l\'Éternel prononcée par l\'homme de Dieu qui proclama ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Et il dit: Qu\'est-ce que ce cippe que j\'aperçois? Et les gens de la ville lui dirent: C\'est le tombeau de l\'homme de Dieu, qui est venu de Juda, et a proclamé ces choses que tu as exécutées sur l\'autel de Béthel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Et il dit: Laissez-le en repos! que nul ne touche à ses os! ils sauvèrent donc ces os ainsi que les os du prophète venu de la Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Et de même tous les temples des tertres dans les villes de la Samarie, qu\'avaient élevés les rois d\'Israël en provocation, Josias les fit disparaître et les traita tout comme il avait procédé à Béthel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Et il immola tous les prêtres des tertres qui étaient présents, sur les autels, sur lesquels il brûla des ossements humains. Là-dessus il regagna Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Et le roi donna un ordre à tout le peuple en ces termes: Faites une Pâque à l\'Éternel, votre Dieu, aux termes de ce qui est écrit dans le présent livre de l\'alliance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Car pareille Pâque n\'avait pas été célébrée depuis l\'époque des Juges qui jugeaient Israël et durant toute la période des rois d\'Israël et des rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Mais la dix-huitième année du roi Josias cette Pâque fut célébrée en l\'honneur de l\'Éternel à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Et Josias fit aussi disparaître les évocateurs et les pronostiqueurs et les Théraphim et les idoles et les horribles simulacres qui se voyaient dans le pays de Juda et dans Jérusalem, afin de mettre à effet les paroles de la Loi consignées dans le volume trouvé par le prêtre Hilkia au temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Avant lui il n\'y avait pas eu de roi pareil à lui, qui fût revenu à l\'Éternel de tout son cœur et de toute son âme et de toute son énergie conformément à la totalité de la Loi de Moïse, et après lui il n\'en parut point de pareil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Néanmoins l\'Éternel ne revint pas de sa grande et ardente colère dont Il était enflammé contre Juda à cause de toutes les provocations dont Manassé l\'avait provoqué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Et l\'Éternel dit: Même Juda, je le bannirai de ma présence ainsi que j\'en ai banni Israël, et je répudie cette ville que j\'avais choisie, Jérusalem, et le temple duquel j\'ai dit: Mon Nom y résidera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Le reste des actes de Josias, et toutes ses entreprises, sont d\'ailleurs consignés dans le livre des annales des rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'De son temps Pharaon Nécho, roi d\'Egypte, s\'avança contre le roi d\'Assyrie sur le fleuve de l\'Euphrate, et le roi Josias se porta à sa rencontre, et reçut de lui la mort à Megiddo, dès qu\'il fut en vue de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Et ses serviteurs sur un char l\'emmenèrent mort de Megiddo et le conduisirent à Jérusalem et lui donnèrent la sépulture dans son tombeau. Et le peuple du pays prit Joachaz, fils de Josias, et ils l\'oignirent et le firent roi en la place de son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Joachaz avait vingt-trois ans à son avènement et il régna trois mois à Jérusalem. Or, le nom de sa mère était Hamutal, fille de Jérémie de Libna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Et il fit ce qui est mal aux yeux de l\'Éternel en tout comme ses pères avaient fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Et Pharaon Nécho l\'enchaîna à Ribla dans la contrée de Hamath pour qu\'il ne régnât plus à Jérusalem, et il imposa le pays d\'une amende de cent talents d\'argent et d\'un talent d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Et Pharaon Nécho fit roi Eliakim, fils de Josias, en la place de Josias, son père, et changea son nom en celui de Jojakim; quant à Joachaz, il le fit prisonnier; et Joachaz vint en Egypte, et il y mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Et Jojakim donna à Pharaon l\'argent et l\'or; mais il taxa le pays pour payer l\'argent exigé par Pharaon, et par une contribution forcée il leva sur le peuple du pays, sur chacun selon son estimation, l\'argent a délivrer à Pharaon Nécho.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Jojakim avait vingt-cinq ans à son avènement et il régna onze ans à Jérusalem. Or le nom de sa mère était Zébida, fille de Pedaïa de Ruma.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Et il fit ce qui est mal aux yeux de l\'Éternel en tout point comme avaient fait ses pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'De son temps Nebucadnetsar, roi de Babel, se mit en campagne, et Jojakim lui fut assujetti trois ans; mais de nouveau il se rebella contre lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Alors l\'Éternel envoya contre lui les bandes des Chaldéens et les bandes des Syriens et les bandes des Moabites et les bandes des fils d\'Ammon, qu\'il envoya contre Juda pour le détruire, selon la menace que l\'Éternel avait prononcée par l\'organe de ses serviteurs les prophètes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Ce fut sur l\'ordre seul de l\'Éternel qu\'il en fut ainsi pour Juda, afin qu\'il fût exclu de Sa présence à cause des péchés de Manassé, ensuite de tout ce qu\'il avait fait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'et à cause aussi du sang innocent qu\'il avait versé remplissant Jérusalem de sang innocent; et l\'Éternel ne voulut pas pardonner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Le reste des actes de Jojakim, et toutes ses entreprises sont d\'ailleurs consignés dans le livre des annales des rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Et Jojakim reposa avec ses pères, et Jojachin, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Cependant le roi d\'Egypte ne fit plus d\'excursion hors de son pays; car le roi de Babel avait conquis tout ce qui était au roi d\'Egypte depuis le torrent d\'Egypte jusqu\'au fleuve de l\'Euphrate.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Jojachin avait dix-huit ans à son avènement et il régna trois mois à Jérusalem. Or le nom de sa mère était Nehustha, fille d\'Elnathan de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Et il fit ce qui est mal aux yeux de l\'Éternel en tout point comme avait fait son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Dans ce temps-là les serviteurs de Nebucadnetsar, roi de Babel, s\'avancèrent sur Jérusalem et la ville essuya un siège.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Et Nebucadnetsar, roi de Babel, arriva devant la ville au moment où ses serviteurs en faisaient le siège.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Alors Jojachin, roi de Juda, se rendit auprès du roi de Babel, lui et sa mère et ses serviteurs et ses généraux et ses eunuques, et le roi de Babel le fit prisonnier, la huitième année de son règne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Et il enleva de là tous les trésors du temple de l\'Éternel et tous les trésors du palais royal et mit en pièces toute la vaisselle d\'or qu\'avait faite Salomon, roi d\'Israël, dans le temple de l\'Éternel, ainsi qu\'avait prononcé l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Et il déporta tout Jérusalem et tous les généraux et tous les braves guerriers, dix mille hommes furent emmenés, ainsi que tous les forgerons et les serruriers: il ne resta rien que le petit peuple du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Et il emmena Jojachin à Babel; et la mère du roi, et les femmes du roi et ses eunuques et tous les notables du pays il les fit marcher en captivité de Jérusalem à Babel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'et tous les gens à moyens, au nombre de sept mille, et les forgerons et les serruriers au nombre de mille, la totalité des guerriers, de tous les hommes aptes à la guerre, le roi de Babel les emmena captifs à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Et le roi de Babel établit Matthania, son oncle, roi en sa place et changea son nom en celui de Sédécias.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Sédécias avait vingt-un ans à son avènement et il régna onze ans à Jérusalem. Or le nom de sa mère était Hamutal, fille de Jérémie de Libna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Et il fit ce qui est mal aux yeux de l\'Éternel en tout point comme avait fait Jojakim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Car c\'est ensuite de la colère de l\'Éternel qu\'il en advint ainsi de Jérusalem et de Juda jusque là qu\'il les bannit de sa présence. Et Sédécias se rebella contre le roi de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Et la neuvième année de son règne, au dixième mois, le dixième jour du mois, survint Nebucadnetsar, roi de Babel, lui et toute son armée, devant Jérusalem; et ils en firent le siège, et ils élevèrent à l\'entour une circonvallation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Et la ville soutint le siège jusqu\'à la onzième année du roi Sédécias.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Le neuvième jour du [quatrième] mois la famine était extrême dans la ville et il n\'y avait point de pain pour le peuple du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Et la brèche était faite à la ville, et tous les gens de guerre [s\'enfuirent] la nuit par la porte entre les deux murs à côté du jardin du roi, tandis que les Chaldéens cernaient la ville; et l\'on prit le chemin de la Plaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Mais l\'armée des Chaldéens poursuivit le roi et l\'atteignit dans les plaines de Jéricho, et toute son armée le quittant se débanda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Et le roi fut pris et conduit vers le roi de Babel à Ribla; et on lui fit son procès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Et ils égorgèrent les fils de Sédécias sous ses yeux, et on creva les yeux à Sédécias, et on le lia de chaînes et le mena à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Et le cinquième mois, le septième jour du mois, c\'était la dix-neuvième année du règne de Nebucadnetsar, roi de Babel, arriva Nebuzaradan, chef des satellites, serviteur du roi de Babel, à Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'et il incendia le temple de l\'Éternel et le palais royal et toutes les maisons de Jérusalem, il livra aux flammes tous les grands édifices.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Et toute l\'armée des Chaldéens, qui accompagnait le chef des satellites, démolit les murs de Jérusalem dans leur pourtour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Quant au résidu du peuple, à ceux qui étaient restés dans la ville, et aux transfuges qui étaient passés au roi de Babel, et au reste de la foule, Nebuzaradan, chef des satellites, les emmena captifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Cependant le chef des satellites laissa dans le pays du petit peuple comme laboureurs et vignerons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Et les Chaldéens brisèrent les colonnes d\'airain qui étaient dans le temple de l\'Éternel, et les porte-aiguière et la Mer d\'airain qui étaient dans le temple de l\'Éternel et en emportèrent l\'airain à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Et ils enlevèrent les chaudières et les pelles et les couteaux et les coupes et toute la vaisselle d\'airain employée pour le service;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'et le chef des satellites enleva les réchauds et les jattes, et ce qui était d\'or, l\'orfèvrerie, et ce qui était d\'argent, l\'argenterie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Les deux colonnes, la mer unique, les porte-aiguière qu\'avait faits Salomon pour le temple de l\'Éternel: le poids de l\'airain de tout ce mobilier était incalculable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Chaque colonne avait dix-huit coudées de hauteur, portant un chapiteau d\'airain et dont la hauteur était de trois coudées, et le chapiteau était enveloppé d\'un treillis et de grenades, le tout d\'airain; et il en était de même pour l\'autre colonne avec le treillis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Et le chef des satellites prit Seraïa, Grand-Prêtre, et Sophonie, Prêtre en second, et les trois portiers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'et de la cité il prit un eunuque, qui était préposé sur les hommes de guerre et cinq hommes d\'entre les conseillers intimes du roi, qui furent trouvés dans la ville, et le Secrétaire, Général de l\'armée, qui levait la troupe pour le pays, et soixante hommes de la milice du pays, qui furent trouvés dans la ville,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'tels sont ceux que prit Nebuzaradan, chef des satellites, et il les mena vers le roi de Babel à Ribla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Et le roi de Babel les exécuta et les fit mourir à Ribla, canton de Hamath. C\'est ainsi que Juda fut déporté loin de son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Quant au peuple resté dans le pays de Juda, que Nebucadnetsar, roi de Babel, avait laissé, il préposa sur lui Gedalia, fils d\'Achikam, fils de Schaphan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Et lorsque tous les chefs des troupes, eux et leur monde, apprirent que le roi de Babel avait préposé Gedalia, ils vinrent auprès de Gedalia à Mitspa, savoir Ismaël, fils de Nethania, et Jochanan, fils de Caréah, et Seraïa, fils de Tanchumeth, de Netopha, et Jaazania, fils du Maachatite, eux et leurs gens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Et Gedalia s\'engagea par serment envers eux et leur monde, et leur dit: Ne craignez point les serviteurs des Chaldéens, restez dans le pays, et soyez soumis au roi de Babel, et vous serez bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Mais au septième mois parut Ismaël, fils de Nethania, fils d\'Elisama, de la race royale, accompagné de dix hommes, et ils firent main basse sur Gedalia, qui mourut, ainsi que sur les Juifs et les Chaldéens qui étaient avec lui à Mitspa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Alors il y eut levée de tout le peuple, petits et grands, et des généraux d\'armée, et ils gagnèrent l\'Egypte, parce qu\'ils avaient peur des Chaldéens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Et trente-sept ans après la déportation de Jojachin, roi de Juda, au douzième mois, le vingt-septième jour du mois, Evil-Mérodach, roi de Babel, l\'année de son avènement, fit relever la tête à Jojachin, roi de Juda, en le tirant de la prison;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'et il lui parla avec bonté, plaça son trône au-dessus du trône des rois qui étaient avec lui à Babel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'et il lui fit quitter ses habits de prison; et il mangea constamment devant lui toute sa vie durant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'et son approvisionnement, son approvisionnement perpétuel lui fut fourni par le roi, au jour le jour, toute sa vie durant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Seth, Enos,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kénan, Mahalaléel, Jared,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Hénoch, Méthuséla, Lamech,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noé, Sem, Cham et Japheth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Fils de Japheth: Gomer et Magog et Madaï et Javan et Thubal et Mésech et Thiras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Et les fils de Gomer: Askenaz et Riphath et Thogarma.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Et les fils de Javan: Elisa et Tharsisa; les Kitthim et les Dodanim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Fils de Cham: Cus et Mitsraïm, Put et Canaan;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'et les fils de Cus: Seba et Havilah et Sabtha et Raëma et Sabthecha. Et les fils de Raëma: Schebah et Dedan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Et Cus engendra Nimrod: celui-ci commença à être un héros sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Et Mitsraïm engendra les Ludim et les Anamim et les Lehabim et les Naphtuhim');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'et les Pathrusim et les Casluhim (desquels sont issus les Philistins), et les Caphthorim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Et Canaan engendra Sidon, son premier-né, et Heth');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'et le Jébusite et l\'Amorite et le Girgésite');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'et le Hévite et l\'Arkite et le Sinite');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'et l\'Arvadien et le Tsemarien et l\'Hamathite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Fils de: Sem: Eilam et Assur et Arphachsad et Lud et Aram et Uts et Hul et Géther et Mésech.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Et Arphachsad engendra Sélach, et Sélach engendra Héber.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Et à Héber naquirent deux fils, le nom de l\'un fut Péleg, parce que de son temps la terre fut partagée, le nom de son frère était Joctan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Et Joctan engendra Almonad et Séleph et Hatsarmaveth et Jara');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'et Adoram et Uzal et Dicla');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'et Ebal et Abimaël et Schébah et Ophir et Havila et Jobab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Tout autant de fils de Joctan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arphachsad, Salach,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eber, Péleg, Rehu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nachor, Tharach,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, c\'est-à-dire Abraham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Fils d\'Abraham: Isaac et Ismaël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Suit leur généalogie. Le premier-né d\'Ismaël Nébaïoth et Kédar et Adbeël et Mibsam,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Misma et Duma, Massa, Hadad et Theima,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jethur, Naphis et Kedma. Ce sont les fils d\'Ismaël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Et les fils de Ketura, concubine d\'Abraham: elle enfante Zimran et Jocschan et Medan et Midian et Jisbak et Suach. Et les fils de Jocschan: Seba et Dedan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Et les fils de Midian: Epha et Epher et Hénoch et Abida et Eldaa. Tout autant de fils de Ketura.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Et Abraham engendra Isaac. Fils d\'Isaac: Esaü et Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Fils d\'Esaü: Eliphaz, Rehuël et Jeüs et Jaëlam et Coré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Fils d\'Eliphaz: Theiman et Omar, Tsephi et Gaëtham, Kenaz et Thimnah et Amalek.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Fils de Rehuël: Nachath, Zérach, Samma et Mizza.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Et les fils de Séir: Lotan et Sobal et Tsibeon et Ana et Dison et Etser et Disan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Et les fils de Lotan: Hori et Homam, et la sœur de Lotan, Thimna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Fils de Sobal: Alian et Manachath et Eibal, Sephi et Onam. Et les fils de Tsibeon: Aia et Ana.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Fils d\'Ana: Dison. Et les fils de Dison: Hamran et Esban et Jithran et Kéran.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Fils de Etser: Bilhan et Zaëvan, Jaëcan; fils de Disan: Uts et Aran.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Et suivent les rois qui régnèrent au pays d\'Edom avant que des rois régnassent sur les enfants d\'Israël. Béla, fils de Beor, et le nom de sa ville était Dinhaba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Et Béla mourut et en sa place régna Jobab, fils de Zérach, de Botsra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Et Jobab mourut et en sa place régna Husam, du pays des Theimanites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Et Husam mourut et en sa place régna Hadad, fils de Bedad, qui battit les Madianites dans les campagnes de Moab; et le nom de sa ville était Avvith.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Et Hadad mourut et en sa place régna Samla de Masréca.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Et Samla mourut et Saül, de Rechoboth sur le Fleuve, régna en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Et Saül mourut et en sa place régna Baal-Chanan, fils d\'Achbor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Et Baal-Chanan mourut, et en sa place régna Hadad, et le nom de sa ville était Pahi et le nom de sa femme Mehètabeël, fille de Matred, fille de Meizahab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Et Hadad mourut. Et il y eut des princes en Edom: le prince de Thimna, le prince d\'Alia, le prince de Jetheth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'le prince d\'Oolibama, le prince d\'Ela, le prince de Pinon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'le prince de Kenaz, le prince de Theiman, le prince de Mibtsar,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'le prince de Magdiel, le prince d\'Iram. Tels sont les princes d\'Edom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Suivent les fils d\'Israël: Ruben, Siméon, Lévi et Juda, Issaschar et Zabulon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Joseph et Benjamin, Nephthali, Gad et Asser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Fils de Juda: Ger et Onan et Sélah, ces trois lui naquirent de la fille de Suah la Cananéenne. Et Ger, le premier-né de Juda, fui méchant aux yeux de l\'Éternel, qui le fit mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Et Thamar, sa bru, lui enfanta Pérets et Zérach. Tous les fils de Juda sont au nombre de cinq.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Fils de Pérets: Hetsron et Hamul;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'et les fils de Zérach: Zimri et Eithan et Eiman et Calcol et Dara, tous ensemble cinq.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Et les fils de Carmi: Achar qui troubla Israël par son sacrilège;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'et les fils d\'Eithan: Azaria;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'et les fils de Hetsron qui lui naquirent: Jérahmeël et Ram et Chelubaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Et Ram engendra Amminadab, et Amminadab engendra Nachson, prince des fils de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Et Nachson engendra Salma, et Salma engendra Boaz');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'et Boaz engendra Obed, et Obed engendra Isaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'et Isaï engendra son premier-né Eliab, et Abinadab le puîné et Siméa le troisième,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Nethaneël le quatrième, Raddaï le cinquième,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Otsem le sixième, David le septième.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Et leurs sœurs étaient: Tseruïa et Abigaïl. Et les fils de Tseruïa: Abisaï et Joab et Hasahel, trois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Et Abigaïl enfanta Amasa, et le père d\'Amasa était Jéther, l\'Ismaélite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Et Caleb, fils de Hetsron, eut des enfants de Azuba, sa femme, et de Jerihoth dont voici les fils: Jéser et Sobab et Ardon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Et à la mort d\'Azuba, Caleb épousa Ephrath qui lui enfanta Hur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Et Hur engendra Uri, et Uri engendra Betsaleël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Et ensuite Hetsron s\'approcha de la fille de Machir père de Galaad, et il l\'épousa étant âgé de soixante ans, et elle lui engendra Segub.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Et Segub engendra Jaïr qui eut vingt-trois villes au pays de Galaad;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'mais les Gesurites et les Syriens leur ravirent les bourgs de Jaïr avec Kenath et ses annexes, soixante villes. Tout autant de fils de Machir, père de Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Et lorsque Hetsron fut mort à Caleb-Ephrata, sa femme Abia lui enfanta Aschur, père de Thékôa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Et les fils de Jérahmeël, premier-né de Hetsron, furent: le premier-né Ram et Buna et Oren et Otsem, Ahia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Et Jérahmeël eut une autre femme nommée Atara qui fut mère d\'Onam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Et les fils de Ram, premier-né de Jérahmeël, furent: Mahats et Jamim et Eker.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Et les fils d\'Onam furent: Sammaï et Jada. Et les fils de Sammaï: Nadab et Abisur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Et le nom de la femme d\'Abisur était Abihaïl, et elle lui enfanta Achban et Molid.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Et les fils de Nadab: Séled et Appaïm. Et Séled mourut sans fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Et les fils d\'Appaïm: Jiseï. Et les fils de Jiseï: Sésan. Et les fils de Sésan: Achlaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Et les fils de Jada, frère de Sammaï: Jéther et Jonathan. Et Jéther mourut sans fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Et les fils de Jonathan: Péleth et Zaza. Ce sont là les fils de Jérahmeël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Et Sésan n\'eut pas de fils, mais il eut des filles. Et Sésan eut un serviteur Égyptien nommé Jarcha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Et Sésan donna sa fille en mariage à Jarcha, son serviteur, et elle lui enfanta Athaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Et Athaï engendra Nathan, et Nathan engendra Zabad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Et Zabad engendra Ephlal, et Ephlal engendra Obed,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'et Obed engendra Jéhu. Et Jéhu engendra Azaria');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'et Azaria engendra Halets et Halets engendra Elasa');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'et Elasa engendra Sisemaï et Sisemaï engendra Sallum');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'et Sallum engendra Jecamia et Jecamia engendra Elisama.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Et les fils de Caleb, frère de Jérahmeël, furent: Meisa, son pre­mier-né, qui est le père de Ziph, et les fils de Marésa, père d\'Hébron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Et les fils d\'Hébron: Coré et Thappuach et Rékem et Sema.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Et Sema engendra Raham, père de Jorkeam, et Rékem engendra Sammaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Et le fils de Sammaï fut Maon et Maon fut le père de Bethsur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Et Epha, concubine de Caleb, enfanta Haran et Motsa et Gazez. Et Haran engendra Gazez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Et les fils de Jehdaï: Régem et Jotham et Geisan et Pélet et Epha et Saaph.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'La concubine de Caleb, Maacha, enfanta Séber et Thirhana,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'et enfanta Saaph, père de Mademanna, Seva, père de Machbéna et père de Gibea. Et la fille de Caleb était Achsa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Ceux-ci furent fils de Caleb: le fils de Hur, premier-né d\'Ephrata, est Sobal, père de Kiriath-Jearim,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, père de Bethléhem, Hareph, père de Beth-Gader.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Et les fils de Sobal, père de Kiriath-Jearim, furent: Haroé, Hatsi, Hammenuhoth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Et les familles de Kiriath-Jearim sont: les Jéhirites, les Phuthites et les Sumathites et les Misraïtes; de ceux-ci sont issus les Tsorehatites et les Esthaülites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Les fils de Salma: Bethléhem et les Nétophatites, Ataroth, la maison de Joab et une moitié des Manachtites, les Tsoreïtes');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'et les familles des Secrétaires, des habitants de Jabets, des Thirathites, des Simeathites, des Suchohites. Ce sont les Kinnites issus de Hammath, père de la maison de Rechab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Suivent les fils de David, qui lui naquirent à Hébron: le pre­mier-né Amnon, de Ahinoam de Jizréel; le second Daniel, d\'Abigaïl, du Carmel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'le troisième Absalom, fils de Maacha, fille de Thalmaï, roi de Gesur, le quatrième Adonia, fils de Haggith;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'le cinquième Sephatia, de Abital; le sixième Jithream, de Egla, sa femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Six fils lui naquirent à Hébron et il régna là sept ans et six mois, et à Jérusalem il régna trente-trois ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Et voici ceux qui lui naquirent à Jérusalem;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Simea et Sobab et Nathan et Salomon, quatre, de Bathsuah, fille d\'Ammiel, et Jibechar et Elisama et Eliphélet');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'et Noga et Népheg et Japhia et Elisama');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'et Eliada et Eliphélet, neuf,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'tous fils de David, outre les fils des concubines. Et Thamar était leur sœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Et le fils de Salomon fut Roboam, dont le fils fut Abia qui eut pour fils Asa, dont le fils fut Josaphat');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'qui eut pour fils Joram, dont le fils fut Achazia qui eut pour fils Joas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'dont le fils fut Amatsia qui eut pour fils Azaria, dont le fils fut Jotham');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'qui eut pour fils Achaz, dont le fils fut Ezéchias qui eut pour fils Manassé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'dont le fils fut Amon qui eut pour fils Josias.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Et les fils de Josias: le premier-né Jochanan, le second Jojakim, le troisième Sédécias, le quatrième Sallum.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Et les fils de Jojakim: son fils Jéchonias qui eut pour fils Sédécias.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Et les fils de Jéchonias, le captif: son fils fut Sealthiel');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'et Malchiram et Phedaia et Sénatsar, Jecamia, Hosama et Nedabia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Et les fils de Phedaia: Zorobabel et Siméï. Et les fils de Zorobabel: Mesullam et Hanania et Selomith, leur sœur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'et Hasuba et Ohel et Béréchia et Hasadia, Jusab-Hesed, cinq.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Et le fils de Hanania: Platia et Esaïe, les fils de Rephaia, les fils d\'Arnan, les fils d\'Obadia, les fils de Sechania.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Et les fils de Sechania: Semaia. Et les fils de Semaia: Hatus et Jigal et Bariah et Nearia et Saphat, six.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Et le fils de Nearia: Elioeinaï et Ezéchias et Azrikam, trois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Et les fils d\'Elioeinaï: Hodaïa et Eliasib et Plaia et Accub et Jochanan et Delaïa et Anani, sept.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Fils de Juda: Pérets, Hetsron et Charmi et Hur et Sobal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Et Reaïa, fils de Sobal, engendra Jahath, et Jahath engendra Ahumaï et Lehad. Ce sont les familles des Tsorehatites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Et du père d\'Eitam sont issus: Jizréel et Jisma et Jidbas, et le nom de leur sœur était Hatselelponi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Et Pnuel fut père de Gedor, et Eser, père de Husa. Voici les fils de Hur, premier-né d\'Ephrata, père de Bethléhem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Et Ashur, père de Thékôa, eut deux femmes Hélea et Naara.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Et Naara lui enfanta Ahuzzam et Hépher et Théïmni et Aasthari. Ce sont là les fils de Naara.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Et les fils de Hélea: Tséreth, Jetsohar et Ethnan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Et Cots engendra Anub et Hatsobèba et les familles d\'Arahehel, fils de Harum.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Et Jabets était honoré par ses frères, et sa mère l\'appela du nom de Jabets disant: Je l\'ai enfanté avec douleur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Et Jabets invoqua le Dieu d\'Israël et dit: Si tu me bénissais et agrandissais mes frontières, et si ta main m\'assistait, et si tu me préservais du malheur, de sorte que je fusse sans douleurs!... L\'Éternel fit arriver ce qu\'il avait demandé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Chelub, frère de Suah, engendra Mehir, c\'est le père d\'Esthon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Et Esthon engendra la maison de Rapha et Pasea et Thehinna, père de la ville de Nattas. Ce sont là les hommes de Recha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Et les fils de Kenaz: Othniel et Seraïa. Et les fils d\'Hothniel: Hathath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Et Meonothaï engendra Ophra, et Seraïa engendra Joab, père de la vallée des charpentiers; car c\'étaient des charpentiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Et les fils de Caleb, fils de Jephunné: Iru, Ela et Naam. Et les fils d\'Ela: Kenaz.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Et les fils de Jehalleël: Ziph et Zipha et Thiria et Asareël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Et les fils d\'Ezra: Jéther et Méred et Epher et Jalon; ... et elle conçut Miriam et Sammaï et Jisba, père d\'Esthemoa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Et sa femme, la Juive, enfanta Jéred, père de Gedor, et Héber, père de Socho, et Jecuthiel, père de Zanoah. Et voici les fils de Bithia, fille de Pharaon, qu\'épousa Méred...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Et les fils de la femme de Hodia, sœur de Naham, père de Kéhila, sont: le Garmite et Esthemoa de Maacha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Et les fils de Simon sont: Amnon et Rinna, Benhanan et Thilon. Et les fils d\'Iseï: Zoheth et Benzoheth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Les fils de Séla, fils de Juda, sont: Er, père de Lécha, et Laada, père de Marésa, et les familles de la maison des ouvriers en lin de la maison d\'Asbea,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'et Jokim, et les hommes de Cozéba et Joas et Saraph, qui furent maîtres de Moab, et Jasubi-Léchem. Or ces choses sont anciennes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'C\'étaient les potiers et ceux qui habitaient dans des plantations fermées, y restant avec le roi pen­dant qu\'il y avait affaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Fils de Siméon: Nemuel et Jamin, Jarib, Zérah, Saül');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'qui eut pour fils Sallum, dont le fils fut Mibsam, qui eut pour fils Misma.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Et les fils de Misma: son fils Hamuel, dont le fils fut Zacchur qui eut pour fils Siméï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Et Siméï eut seize fils et six filles, et ses frères n\'eurent pas beaucoup de fils, et toutes leurs familles ne se multiplièrent pas au même point que celles des fils de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Et ils habitaient à Béerséba, Molada et Hatsar-Sual');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'et à Bila et Etsem et Tholad,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'et à Béthuel et Horma et Tsiklag');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'et à Beth-Marchaboth et Hatsar-Susim et Beih-Bireï et Saaraïm. Ce furent leurs villes jusqu\'au règne de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Et leurs villages: Eitam et Aïn, Rimmon et Thochen et Asan, cinq cités,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'et tous leurs villages qui étaient autour de ces villes jusqu\'à Baal: tels étaient leurs établissements et leur généalogie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Et Mesobab et Jamlech et Josa, fils d\'Amatsia,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'et Joël et Jéhu, fils de Josibia, fils de Seraïa, fils d\'Asiel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'et Elioeinaï et Jaacoba et Jesohaïa et Asaïa et Adiol et Jesimiel et Benaïa');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'et Ziza, fils de Sipheï, fils de Allon, fils de Jedaïa, fils de Simri, fils de Semaïa:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'ces hommes cités par leurs noms furent princes dans leurs familles et leurs maisons patriarcales s\'étendirent beaucoup.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Et ils se por­tèrent à l\'occident de Gedor jusques au côté oriental de la vallée, afin de chercher un pâturage pour leurs troupeaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Et ils trou­vèrent un gras et bon pâturage et une contrée spacieuse dans tous les sens, et tranquille et sûre, car les habitants précédents descendaient de Cham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Ainsi arrivèrent ces hommes, inscrits par leurs noms, à l\'époque d\'Ezéchias, roi de Juda, et ils défirent les Meünites et leur campement qui se trouvait là, et ils les détrui­sirent comme ils sont aujourd\'hui, et prirent leur place, parce qu\'il y avait là des pâturages pour leurs troupeaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Et il y en eut, des fils de Siméon, qui se portèrent à la montagne de Séir au nombre de cinq cents hommes, et Platia et Nearia et Rephaïa et Uzziel, fils de Jiseï, étaient à leur tête,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'et ils défirent le reste des réchappes d\'Amalek, et ils ont demeuré là jusqu\'aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Et les fils de Ruben, premier-né d\'Israël, (car il était le premier-né, mais, pour avoir profané le lit de son père, sa pri­mogéniture fut dévolue aux fils de Joseph, fils d\'Israël, sans cependant qu\'ils fussent comptés dans la généalogie à titre de primo­géniture;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'sans doute Juda fut puissant parmi ses frères et fournit un prince, mais la primogéniture appartenait à Joseph)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'les fils de Ruben, premier-né d\'Israël, sont: Hanoch et Pallu, Hetsron et Charmi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Les fils de Joël: son fils Semaïa, dont le fils fut Gog qui eut pour fils Siméï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'dont le fils fut Michée qui eut pour fils Reaïa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'dont le fils fut Baal qui eut pour fils Beéra que Thiglath-Pilnéser, roi d\'Assyrie, emmena captif; il était Prince des Rubénites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Et ses frères selon leurs familles au registre de leurs généalogies furent: le chef Jehiel et Zacharie');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'et Béla, fils de Azaz, fils de Sema, fils de Joël; celui-ci habitait à Aroër et jusqu\'à Nebo et Baal-Meon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'et au levant jusqu\'à l\'entrée du désert borné par l\'Euphrate; car ils avaient de nombreux troupeaux dans la contrée de Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Et à l\'époque de Saul ils firent la guerre aux Hagarites qui tombèrent entre leurs mains et dont ils habitèrent les tentes sur tout le côté oriental de Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Et les fils de Gad habitaient vis-à-vis d\'eux au pays de Basan jusqu\'à Salcha:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joël, le chef, et Sapham, le second, puis Jaënaï et Saphat en Basan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Et leurs frères selon leurs maisons patriarcales sont: Michaël et Mesullam et Séba et Joraï et Jaëchan et Zia et Eber, sept.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Ce sont les fils d\'Abihaïl, fils de Huri, fils de Jaroach, fils de Galaad, fils de Michaël, fils de Jesisaï, fils de Jahdo, fils de Buz.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ahi, fils d\'Abdiel, fils de Guni, était leur patriarche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Et ils habitaient en Galaad et en Basan et dans les villes de leur dépendance et dans tous les chesaux de Saron jusqu\'à leurs issues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Tous ils furent inscrits aux registres à l\'époque de Jotham, roi de Juda, et à l\'époque de Jéroboam, roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Les fils de Ruben et les Gadites et la demi-Tribu de Manassé, ce qu\'il y avait d\'hommes braves, portant le bouclier et l\'épée et bandant l\'arc et formés à la guerre, au nombre de quarante-quatre mille sept cent soixante, se mirent en campagne');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'et firent la guerre aux Hagarites et à Jetur et Naphis et Nodab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Et secours leur fut dispensé contre eux, et les Hagarites furent livrés entre leurs mains avec tous leurs auxiliaires; car dans le combat ils élevèrent leur cri vers Dieu qui les exauça parce qu\'ils se confiaient en Lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Et ils emmenèrent leur bétail et leurs chameaux au nombre de cinquante mille et deux cent cinquante mille moutons, et deux mille ânes, et en hommes cent mille âmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Car il tomba une multitude de morts, parce que le combat était engagé de par Dieu. Et ils habitèrent en leur place jusqu\'à la déportation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Et les fils de la demi-Tribu de Manassé habitèrent au pays de Basan jusqu\'à Baal-Hermon et Senir et le mont Hermon: ils étaient nombreux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Et voici leurs patriarches: Epher et Jiseï et Eliel et Azriel et Jérémie et Hodavia et Jachdiel, braves guerriers et hommes de renom, chefs de leurs familles patriarcales.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Mais ils firent infidélité au Dieu de leurs pères et allèrent se prostituer après les dieux des peuples du pays, que Dieu avait exterminés devant eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Alors le Dieu d\'Israël émut l\'esprit de Phul, roi d\'Assyrie, et l\'esprit de Thiglath-Pilnéser, roi d\'Assyrie, et Il déporta les Rubénites et les Gadites et la demi-Tribu de Manassé et les amena à Chala et Chabor et Chara et au fleuve du Gozan, où ils sont aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Fils de Lévi: Gerson, Cahath et Merari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Et les fils de Cahath: Amram, Jitsehar et Hébron et Uzziel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Et les fils d\'Amram: Aaron et Moïse et Miriam. Et les fils d\'Aaron: Nadab et Abihu, Eléazar et Ithamar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eléazar engendra Phinées, Phinées engendra Abisua,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'et Abisua engendra Buki, et Buki engendra Uzzi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Et Uzzi engendra Zerachia, et Zerachia engendra Meraioth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Meraioth engendra Amaria, et Amaria engendra Ahitub,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'et Ahitub engendra Tsadoc, et Tsadoc engendra Ahimaats.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Et Ahimaats engendra Azaria, et Azaria engendra Jochanan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'et Jochanan engendra Azaria (c\'est lui qui exerça le sacerdoce dans le Temple que bâtit Salomon à Jérusalem);');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'et Azaria engendra Amaria, et Amaria engendra Ahitub,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'et Ahitub engendra Tsadoc, et Tsadoc engendra Sallum,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'et Sallum engendra Hilkia, et Hilkia engendra Azaria,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'et Azaria engendra Seraïa, et Seraïa engendra Jotsadac,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'et Jotsadac partit lorsque l\'Éternel déporta Juda et Jérusalem par le moyen de Nebucadnetsar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Fils de Lévi: Gersom, Cahath et Merari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Suivent les noms des fils de Gersom: Libni et Siméï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Et les fils de Cahath: Amram et Jitsehar et Hébron et Uzziel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Fils de Merari: Maheli et Mussi. Suivent les familles des Lévites selon leurs patriarches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'De Gersom, dont le fils fut Libni, dont le fils fut Jéhath, dont le fils fut Zimma,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'dont le fils fut Joah, dont le fils fut Iddo, dont le fils fut Zérach, dont le fils fut Jeathraï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Fils de Cahath: Amminadab, dont le fils fut Coré, dont le fils fut Assir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'dont le fils fut Elkana, dont le fils fut Ebiasaph, dont le fils fut Assir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'dont le fils fut Thahath, dont le fils fut Uriel, dont le fils fut Uzziia, dont le fils fut Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Et les fils d\'Elkana: Amasaï et Ahimoth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'dont le fils fut Elkana qui eut pour fils Elkana-Tsophaï, dont le fils fut Nahath');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'qui eut pour fils Eliab, dont le fils fut Jeroham qui eut pour fils Elkana.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Et les fils de Samuel: le premier-né Vasni et Abia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Fils de Merari: Maheli, dont le fils fut Libni qui eut pour fils Siméï, dont le fils fut Uzza');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'qui eut pour fils Simea, dont le fils fut Haggia qui eut pour fils Asaïa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Suivent ceux que David préposa à la conduite du chant dans la Maison de l\'Éternel dès que l\'arche fut fixée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'Et ils officièrent devant la Résidence de la Tente du Rendez-vous dans le chant jusqu\'à ce que Salomon construisît le Temple de l\'Éternel à Jérusalem, et ils s\'acquittaient selon leur règle de leur fonction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Et voici ces fonctionnaires, ainsi que leurs fils: des fils des Cahathites: Heiman, le chantre, fils de Joël, fils de Samuel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'fils d\'Elkana, fils de Jeroham, fils d\'Eliel, fils de Thoah,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'fils de Tsuph, fils d\'Elkana, fils de Mahath, fils d\'Amasaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'fils d\'Elkana, fils de Joël, fils d\'Azaria, fils de Sophonie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'fils de Thahath, fils d\'Assir, fils d\'Ebiasaph, fils de Coré,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'fils de Jitsehar, fils de Cahath, fils de Lévi, fils d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Et son frère Asaph qui se tenait à sa droite, Asaph, fils de Béréchia, fils de Silea,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'fils de Michaël, fils de Baaseïa, fils de Malchiia,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'fils de Etni, fils de Zérah, fils de Adaïa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'fils d\'Eithan, fils de Zimna, fils de Siméi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'fils de Jahath, fils de Gersom, fils de Lévi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Et les fils de Merari, leurs frères, se tenaient à la gauche: Eithan, fils de Kisi, fils d\'Abdi, fils de Malluch,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'fils de Hasabia, fils de Amatsia, fils d\'Hillda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'fils d\'Amtsi, fils de Bani, fils de Samer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'fils de Maheli, fils de Mussi, fils de Merari, fils de Lévi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Et leurs frères les Lévites étaient affectés à tout le service de la Résidence de la Maison de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Et Aaron et ses fils faisaient fumer les oblations sur l\'autel des holocaustes et sur l\'autel aux parfums, chargés de tout le service du Lieu Très-Saint, et de l\'expiation pour Israël selon toutes les prescriptions de Moïse, serviteur de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Suivent les fils d\'Aaron: Son fils Eléazar qui eut pour fils Phinées, dont le fils fut Abisua');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'qui eut pour fils Buki, dont le fils fut Uzzi qui eut pour fils Zerahia,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'dont le fils fut Meraioth qui eut pour fils Amaria, dont le fils fut Ahitub');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'qui eut pour fils Tsadoc, dont le fils fut Ahimaats.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Et voici leurs habitations selon leurs clos dans leurs limites, savoir des fils d\'Aaron de la famille des Cahathites, car à eux échut le sort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'On leur donna Hébron au pays de Juda et sa banlieue environnante,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'mais les champs de la ville et ses villages furent donnés à Caleb, fils de Jéphunné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Et aux fils d\'Aaron on donna les villes de refuge: Hébron et Libna et sa banlieue, et Jatthir, et Esthmoa et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'et Hilen et sa banlieue, Debir et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'et Asan et sa banlieue, et Bethsémès et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'et de la Tribu de Benjamin: Geba et sa banlieue, et Allemeth et sa banlieue, et Anathoth et sa banlieue. Total de leurs villes, treize en raison de leurs familles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Et les fils de Cahath restants [reçurent] des familles de la Tribu [d\'Ephraïm et de celle de Dan] et de la demi-Tribu de Manassé par le sort dix villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Et les fils de Gersom selon leurs familles reçurent de la Tribu d\'Issaschar et de la Tribu d\'Asser et de la Tribu de Nephthali et de la Tribu de Manassé en Basan, treize villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Les fils de Merari selon leurs familles reçurent de la Tribu de Ruben et de la Tribu de Gad et de la Tribu de Zabulon par le sort douze villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'C\'est ainsi que les enfants d\'Israël donnèrent aux Lévites les villes et leurs banlieues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Et ils donnèrent par le sort, de la Tribu des fils de Juda et de la Tribu des fils de Siméon et de la Tribu des fils de Benjamin, ces villes qu\'ils désignèrent par leurs noms.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Quant [aux restants] des familles de Cahath les villes de leur district étaient de la Tribu d\'Ephraïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Et on leur donna les villes de refuge: Sichem et sa banlieue dans la montagne d\'Ephraïm, et Gézer et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'et Jocmeam et sa banlieue, et Beth-Horon et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'et Ajalon et sa banlieue, et Gath-Rimmon et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'et de la demi-Tribu de Manassé Aner et sa banlieue, et Bileam et sa banlieue, — à la famille des autres fils de Cahath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Les fils de Gersom eurent de la famille de la demi-Tribu de Manassé: Golan en Basan et sa banlieue, et Astaroth et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'et de la Tribu d\'Issaschar: Kédès et sa banlieue, Dobrath et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'et Ramoth et sa banlieue, et Anem et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'et de la Tribu d\'Asser: Masal et sa banlieue, et Abdon et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'et Hucoc et sa banlieue, et Rechob et sa banlieue;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'et de la Tribu de Nephthali: Kédès en Galilée et sa banlieue, et Hammon et sa banlieue, et Kiriathaïm et sa banlieue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Les autres fils de Merari eurent de la Tribu de Zabulon: Rimmon et sa banlieue, et Thabor et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'et au delà du Jourdain près de Jéricho à l\'Orient du Jourdain, de la Tribu de Ruben: Betser au désert et sa banlieue, et Jahtsa et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'et Kedémoth et sa banlieue, et Meiphaath et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'et de la Tribu de Gad: Ramoth en Galaad et sa banlieue, et Mahanaïm et sa banlieue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'et Hesbon et sa banlieue, et Jaëzer et sa banlieue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Quant aux fils d\'Issaschar c\'étaient: Thola et Phua, Jasub et Simron, quatre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Et les fils de Thola: Uzzi et Rephaïa, Jeriel et Jachmaï et Jibsam et Samuel, patriarches de leurs maisons, de Thola, c\'étaient de braves guerriers, selon leurs familles; leur nombre à l\'époque de David, était de vingt-deux mille six cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Et les fils d\'Uzzi: Jizrachia. Et les fils de Jizrachia, Michaël et Obadia et Joël, Jissia, cinq, tous patriarches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Et avec eux étaient, selon leurs familles, selon leurs maisons patriarcales, des bandes militaires pour la guerre, trente-six mille hommes; car ils avaient beaucoup de femmes et de fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Et leurs frères, selon toutes les familles d\'Issaschar, hommes vaillants, étaient au nombre de quatre-vingt-sept mille, enregistrés en totalité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Benjamin: Béla et Bécher et Jediaël, trois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Et les fils de Béla: Etsbon et Uzzi et Uzziel et Jérimoth et Iri, cinq, patriarches, hommes vaillants, enregistrés au nombre de vingt-deux mille trente-quatre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Et les fils de Bécher: Zemira et Joas et Eliézer et Elioeinaï et Omri et Jerémoth et Abia et Anathoth et Alameth, tout autant de fils de Bécher,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'portés aux registres, selon leurs familles, comme leurs patriarches, hommes vaillants au nombre de vingt mille deux cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Et les fils de Jediaël: Bilhan. Et les fils de Bilhan: Jeüs et Benjamin et Ehud et Cnaana et Zeithan et Tharsis et Ahisahar,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'tout autant de fils de Jediaël selon leurs maisons patriarcales, hommes vaillants au nombre de dix-sept mille deux cents qui sortaient comme soldats pour la guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Et Suppim et Hupim, fils d\'Ir, Husim, les fils d\'Aher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Fils de Nephthali: Jatsiel et Guni et Jetser et Sallum, fils de Bilha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Fils de Manassé: Asriel qu\'enfanta sa concubine Syrienne: elle avait enfanté Machir, père de Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Et Machir prit une femme de Hupim et de Suppim, et le nom de sa sœur était Maacha et le nom du [second] fils était Tselophehad; et Tselophehad eut des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Et Maacha, femme de Machir, enfanta un fils et le nomma Pérès; et le nom de son frère était Sarès et ses fils Ulam et Rakem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Et les fils d\'Ulam: Bedan. Ce sont des fils de Galaad fils de Machir, fils de Manassé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Et sa sœur Hammolecheth enfanta Ishod et Abiézer et Mahela.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Et les fils de Semida furent: Achian et Sichem et Likhi et Aniam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Et les fils d\'Ephraïm sont: Suthela, dont le fils fut Béred qui eut pour fils Thahath, dont le fils fut Elada qui eut pour fils Thahath,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'dont le fils fut Zabad, dont le fils fut Suthela et Ezer et Elead. Et ceux-ci furent tués par les hommes de Gath, indigènes du pays, car ils avaient fait une descente pour enlever leurs troupeaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Et Ephraïm, leur père, les pleura longtemps et ses frères vinrent pour le consoler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Et il s\'approcha de sa femme et elle devint enceinte et enfanta un fils qu\'il appela du nom de Beria parce que sa maison avait été malheureuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Et sa fille était Séèra, et elle bâtit Beth-Horon, la basse et la haute, et Uzzen-Séèra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Et son fils fut Réphah qui eut pour fils Réseph et Thélah, dont le fils fut Thahan qui eut pour fils');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'Laedan, dont le fils fut Ammihud qui eut pour fils Elisama,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'dont le fils fut Nun qui eut pour fils Josué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Et Béthel avec ses annexes était leur propriété et leur demeure, et du côté du levant ils avaient Naaran, et du côté du couchant Gézer et ses annexes, et Sichem et ses annexes jusques à Gaza et à ses annexes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'et à côté des fils de Manassé Beth-Séan et ses annexes, Thaënach et ses annexes, Megiddo et ses annexes, Dor et ses annexes. C\'est dans ces localités qu\'habitèrent les fils de Joseph, fils d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Fils d\'Asser: Jimna et Jisva et Jisvi et Bria et Serah, leur sœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Et les fils de Bria: Héber et Malchiel, c\'est le père de Birzavith.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Et Héber engendra Japhlet et Somer et Hotham et Suah, leur sœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Et les fils de Japhlet: Pasach et Bimehal et Asvath; tels sont les fils de Japhlet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Et les fils de Samer: Ahi et Rahga et Hubba et Aram.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Et les fils de Hélem (Hotham), son frère: Tsophah et Jimna et Selès et Amal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Fils de Tsophah: Suach et Harnepher et Suai et Beri et Jimra,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Betser et Hod et Samma et Silsa et Jithran et Béera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Fils de Jéther: Jephunné et Phispa et Ara.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Et les fils de Ulla: Arach et Haniel et Ritsia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Tout autant de fils d\'Asser, chefs des maisons patriarcales, hommes d\'élite et de bravoure, chefs des princes. Et leur rôle dans l\'armée pour le combat, leur nombre, porte vingt-six mille hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Et Benjamin engendra Béla, son premier-né, Asbel, le second, et Aherach, le troisième,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Noha, le quatrième, et Rapha le cinquième.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Et Béla eut des fils: Addar et Géra, et Abihud');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'et Abisua et Naaman et Ahoah');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'et Géra et Sepuphan et Huram.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Et suivent les fils d\'Ehud, lesquels furent les patriarches des habitants de Géba, et ils les emmenèrent captifs à Manachath,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'savoir Naaman et Ahia et Géra, c\'est celui-ci qui les emmena captifs, et il engendra Uzza et Ahihud.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Et Sacharaïm engendra dans la campagne de Moab, après les avoir répudiées, avec Husim et Baara, ses femmes, des fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Et il eut de Hodès, sa femme, Jobab et Tsibia et Meisa et Malcam');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'et Jehuts et Sochia et Mirma. Tels sont ses fils, patriarches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Et de Husim il eut Abitub et Elpaal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Et les fils d\'Elpaal: Eber et Miseam et Samer, lequel bâtit Ono et Lod et ses annexes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Et Bria et Sema sont les patriarches des habitants d\'Ajalon; ils mirent en fuite les habitants de Gath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Et Ahio, Sasac et Jerémoth');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'et Zebadia et Arad et Ader');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'et Michaël et Jispa et Joah sont les fils de Bria.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Et Zebadia et Mesullam et Hiski et Haber');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'et Jismeraï et Jizlia et Jobab sont les fils d\'Elpaal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Et Jakim et Zichri et Zabdi');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'et Elioeinaï et Tsilthaï et Eliel');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'et Adaïa et Beraïa et Simrath sont les fils de Siméï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Et Jispan et Héber et Eliel');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'et Abdon et Zichri et Hanan');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'et Hanania et Eilam et Anthothia');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'et Jiphdia et Pnuel sont les fils de Sasac.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Et Samseraï et Secharia et Athalia');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'et Jaerseia et Elia et Zichri sont les fils de Jeroham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Ce sont des patriarches d\'après leurs familles, des chefs: ils habitaient à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Et à Gabaon habitait le père de Gabaon, et le nom de sa femme était Maacha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Et son fils premier-né était Abdon, et [les autres] Tsur et Kis et Baal et Nadab');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'et Gedor et Ahio et Zacher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Et Micloth engendra Simea et eux aussi habitaient en face de leurs frères à Jérusalem avec leurs frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Et Ner engendra Kis, et Kis engendra Saül, et Saül engendra Jonathan et Maleki-Sua et Abinadab et Esbaal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Et le fils de Jonathan fut Meribbaal, et Meribbaal engendra Micha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Et les fils de Micha sont: Pithon et Mélech et Thaërèa et Achaz.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Et Achaz engendra Joadda, et Joadda engendra Alemeth et Azmaveth et Zimri, et Zimri engendra Motsa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Et Motsa engendra Binea, dont le fils fut Rapha qui ont pour fils Eleasa, dont le fils fut Atsel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Et Atsel eut six fils dont les noms suivent: Azricam, Bochru et Ismaël et Séaria et Obadia et Hanan: tout autant de fils de Atsel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Et les fils de Esec son frère: Ulam, son premier-né, Jeüs, le second, et Elipheleth, le troisième.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Et les fils d\'Ulam furent de braves guerriers, bandant l\'arc, et ils eurent beaucoup de fils et de petits-fils, cent cinquante. Tous ceux-là sont d\'entre les fils de Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Or tous les Israélites furent enregistrés, et voici ils sont inscrits dans le livre des rois d\'Israël. Et Juda fut déporté à Babel à cause de ses forfaits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Les premiers habitants qui [vivaient] sur leur propriété dans leurs villes, étaient, les Israélites, les Prêtres, les Lévites et les attachés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Et à Jérusalem habitaient des fils de Juda et des fils de Benjamin et des fils d\'Ephraïm et de Manassé, Uthaï, fils d\'Ammihud, fils de Omri, fils d\'Imri, fils de Bani,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'des fils de Pérets, fils de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Et des Silonites: Asaïa, le premier-né, et ses fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Et des fils de Zérach: Jehuel et leurs frères, six cent quatre-vingt-dix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Et des fils de Benjamin: Sallu, fils de Mesullam, fils d\'Hodavia, fils de Assenua,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'et Jibneia, fils de Jéroham, et Ela, fils de Uzzi, fils de Michri et Mesullam, fils de Sephatia, fils de Rehuel, fils de Jibniia,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'et leurs frères, selon leurs familles, neuf cent cinquante-six. Tous ces hommes étaient patriarches de leurs maisons patriarcales.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Et des Prêtres: Jedaïa et Jojarib et Jachin');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'et Azaria, fils d\'Hilkia, fils de Mesullam, fils de Tsadoc, fils de Meraioth, fils d\'Ahitub, primicier de la Maison de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'et Adaïa, fils de Jeroham, fils de Paschur, fils de Malchiia, et Maesaï, fils de Adiel, fils de Jahzera, fils de Mesullam, fils de Messilêmith, fils de Immer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'et leurs frères, chefs de leurs maisons patriarcales, mille sept cent soixante, hommes vigoureux à l\'œuvre du service de la maison de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Et des Lévites: Semaia, fils de Chassub, fils d\'Azricam, fils de Hasabia, des fils de Merari,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'et Bacbaccar, Hérès et Galal et Matthania, fils de Michée, fils de Zichri, fils d\'Asaph;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'et Obadia, fils de Semaia, fils de Galal, fils de Jeduthun, et Berechia, fils d\'Asa, fils d\'Elkana, qui habitait dans les bourgs des Netophathites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Et les portiers: Sallum et Accub et Talmon et Abiman et leurs frères; Sallum était le chef.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Et jusqu\'à présent ils sont à la Porte Royale à l\'orient, eux, les portiers du campement des fils de Lévi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Et Sallum, fils de Coré, fils d\'Ebiasaph, fils de Coré, et ses frères de la maison de son père, les Coraïtes étaient préposés à la fonction du service, comme gardes des seuils de la Tente, et leurs pères étaient préposés sur le camp de l\'Éternel, gardes de l\'avenue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Et Phinées, fils d\'Eléazar, fut jadis leur chef (l\'Éternel était avec lui).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zacharie, fils de Mesélémia, était un portier à l\'entrée de la Tente du Rendez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Tous, choisis pour être gardes des seuils, ils étaient au nombre de deux cent douze. Ils étaient enregistrés d\'après leurs villages. David et Samuel, le Voyant, les avaient institués sur leur foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Eux et leurs fils étaient de garde aux portes de la maison de l\'Éternel, de la Résidence de la Tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Les portiers stationnaient aux quatre vents, à l\'orient, à l\'occident, au septentrion et au midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Et leurs frères demeuraient dans leurs villages pour venir se joindre à eux le septième jour à époques fixes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'car ces quatre chefs des portiers, ces mêmes Lévites, étaient laissés sur leur foi, et ils avaient la surveillance des cellules et des trésors de la Maison de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Et ils passaient la nuit aux alentours de la Maison de Dieu, car ils étaient chargés de faire la garde et d\'ouvrir tous les matins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Et il y en avait de préposés sur la vaisselle du service, qu\'ils rentraient en la comptant, et sortaient en la comptant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Et il y en avait de préposés sur les ustensiles, sur tous les ustensiles sacrés, et sur la fleur de farine et le vin et l\'huile et l\'encens et les aromates.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Et c\'étaient des fils de Prêtres qui composaient l\'huile aromatisée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Et à Matthithia, l\'un des Lévites (premier-né de Sallum), le Coraïte, était confié le soin de la boulangerie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Et quelques-uns des fils des Kahathites, leurs frères, étaient préposés sur les pains de présentation, qu\'ils avaient à préparer sabbat par sabbat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Ce sont là les chantres, patriarches des Lévites, exemptés du service des cellules, parce que jour et nuit ils vaquaient à leur affaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Ce sont là les patriarches des Lévites selon leurs familles, les chefs; ils demeuraient à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'Or à Gabaon demeurait le père de Gabaon, Jehiel, le nom de sa femme était Maacha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Et son fils premier-né fut Abdon, puis il eut Tsur et Kis et Baal et Ner et Nadab');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'et Gedor et Ahio et Zacharie et Micloth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Et Micloth engendra Simeam, et ceux-ci aussi habitèrent vis-à-vis de leurs frères à Jérusalem auprès de leurs frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Et Ner engendra Kis, et Kis engendra Saül, et Saül engendra Jonathan et Malkisua et Abinadab et Esbaal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Et le fils de Jonathan fut Meribbaal, et Meribbaal engendra Micha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Et les fils de Micha furent Pithon et Mélech et Thaherèa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Et Achaz engendra Jaëra, et Jaëra engendra Alemeth et Azmaveth et Zimri, et Zimri engendra Motsa. Et Motsa engendra Binea,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'dont le fils fut Rephaia qui eut pour fils Elasa, dont le fils fut Atsel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Et Atsel eut six fils dont les noms suivent: Azricam, Bochru et Jismaël et Searia et Obadia et Chanan. Ce sont les fils de Atsel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Et les Philistins étaient aux prises avec Israël et les hommes d\'Israël fuiront devant les Philistins et il tomba des blessés sur la montagne de Gilboa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Et les Philistins se mirent à la poursuite de Saül et de ses fils, et les Philistins abattirent Jonathan et Abinadab et Malchisua, fils de Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Et le faix de la bataille tombait sur Saül, qui fut atteint par les tireurs d\'arc; et Saül trembla devant les tireurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Alors Saül dit à son écuyer: Tire ton épée et m\'en perce, afin que ces incirconcis ne viennent pas faire de moi leur jouet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Et son écuyer ne voulut pas, car il avait une crainte extrême. Alors Saül prit l\'épée et se rua dessus. Et l\'écuyer voyant Saül mort se rua aussi sur l\'épée et mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Ainsi périt Saül et ses trois fils, et toute sa maison périt à la fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Et quand tous les Israélites de la plaine virent la fuite et la mort de Saül et de ses fils, ils abandonnèrent leurs villes et s\'enfuirent, et les Philistins arrivèrent et s\'y établirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Et le lendemain les Philistins vinrent pour dépouiller les morts, et ils trouvèrent Saül et ses fils tombés sur la montagne de Gilboa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Et ils le dépouillèrent et emportèrent sa tête et ses armes, qu\'ils firent circuler dans le pays des Philistins pour donner la nouvelle à leurs idoles et au peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Et ils placèrent ses armes dans le temple de leur dieu, et fichèrent son crâne dans le temple de Dagon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Et tout Jabès de Galaad fut instruit de tout ce que les Philistins avaient fait à Saül;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'alors tous les braves se mirent sur pied et allèrent enlever le corps de Saül et les corps de ses fils, qu\'ils amenèrent à Jabès, et ils inhumèrent leurs os sous le térébinthe de Jabès et jeûnèrent sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Ainsi périt Saül ensuite du forfait qu\'il avait commis contre l\'Éternel à l\'occasion de la parole de l\'Éternel qu\'il n\'avait pas observée, et aussi en consultant, cherchant les évocateurs des morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'Mais, l\'Éternel, il ne Le consulta point; c\'est pourquoi Il le fit mourir et transféra la royauté à David, fils d\'Isaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Et tous les Israélites formèrent assemblée auprès de David à Hébron et dirent: Voici, nous sommes tes os et ta chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Déjà hier et avant-hier, déjà pendant le règne de Saül, c\'était toi qui menais en campagne et ramenais Israël, et l\'Éternel, ton Dieu, t\'a dit: C\'est toi qui seras le pasteur de mon peuple d\'Israël, et c\'est toi qui seras prince de mon peuple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Ainsi se présentèrent tous les Anciens d\'Israël au Roi en Hébron et David solennisa un pacte avec eux à Hébron devant l\'Éternel; et ils oignirent David roi d\'Israël aux termes de la parole de l\'Éternel prononcée par l\'organe de Samuel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Et David et tous les Israélites se portèrent sur Jérusalem, c\'est- à-dire Jébus; or là vivaient les Jébusites habitants du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Et les habitants de Jébus dirent à David: Tu n\'entreras pas ici. Mais David s\'empara de la citadelle de Sion, c\'est-à-dire, de la Cité de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Et David dit: Le premier qui battra les Jébusites aura rang de chef et de général. Et le premier qui escalada fut Joab, fils de Tseruïa, et il devint chef.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Et David habita la citadelle; c\'est pourquoi elle reçut le nom de Cité de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Et il éleva la cité dans son pourtour, à partir de Millo, et l\'enceinte entière, et Joab restaura le restant de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Et David allait toujours grandissant et l\'Éternel des armées était avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Suivent les principaux héros qu\'avait David, qui lui prêtèrent main forte lors de son avènement, avec tout Israël, pour le faire roi selon la parole de l\'Éternel concernant Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Et voici la liste des héros qu\'avait David: Jasobeam, fils de Hachmoni, chef des trente, il brandissait sa lance sur trois cents hommes tués tout d\'une haleine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Et après lui Eléazar, fils de Dodo, l\'Ahohite; il était l\'un des trois héros.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'C\'est lui qui était avec David à Pas-Damim, lorsque les Philistins s\'étaient concentrés là pour le combat. Et il y avait là une pièce de terre, pleine d\'orge, et la troupe s\'enfuit devant les Philistins;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'alors ils se postèrent au milieu du champ et le délivrèrent et battirent les Philistins, et l\'Éternel accorda une grande victoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Et ces trois qui faisaient partie des trente chefs, descendirent au rocher vers David dans la grotte d\'Adullam, et le camp des Philistins était assis dans la vallée de Rephaïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Or David se trouvait à ce moment sur la hauteur, et il y avait alors à Bethléhem un poste de Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Et David fit un souhait et dit: Qui me fera boire de l\'eau de la citerne de Bethléhem, qui est dans la porte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Alors les trois se firent jour à travers le campement des Philistins, et puisèrent de l\'eau à la citerne de Bethléhem dans la porte, et ils l\'apportèrent et l\'offrirent à David; mais David ne voulut pas la boire et il la répandit en hommage à l\'Éternel');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'et dit: Mon Dieu me préserve de faire pareille chose! Boirais-je le sang de ces hommes qui ont risqué leur vie? Car c\'est au péril de leur vie qu\'ils l\'ont apportée. Il ne voulut donc pas la boire. Tel est l\'exploit des trois héros.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Et Abisaï, frère de Joab: il était le chef des Trois, et il brandit sa lance sur trois cents tués et il avait un nom dans les Trois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Il était honoré par les Trois de la seconde série, et était leur chef, mais il n\'atteignait pas aux Trois [premiers].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaïa, fils de Joiada, fils d\'un brave, illustre par ses exploits, du Cabtséel; c\'est lui qui abattit les deux Ariels de Moab. C\'est aussi lui qui descendit et abattit le lion dans la citerne un jour de neige.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'C\'est aussi lui qui terrassa l\'homme d\'Egypte, un homme ayant une stature de cinq coudées, et dans la main de l\'Égyptien était une lance comme l\'ensuble d\'un tisserand, et il fondit sur lui avec le bâton, et arracha la lance de la main de l\'Égyptien, qu\'il tua avec sa lance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Tels sont les faits de Benaïa, fils de Joiada, et il avait avec un nom entre les Trois héros.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Voici, il était honoré par les trente, mais il n\'atteignait pas aux trois premiers. Et David le mit à la tête de sa garde du corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Et les chefs des ces corps d\'armée étaient: Asahel, frère de Joab; Elchanam fils de Dodo, de Bethléhem;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Sammoth l\'Harorite; Hélets, le Pelonite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira, fils de Ickesch de Thékôa; Abiézer, d\'Anatoth;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibchaï le Husathite; Ilaï l\'Ahohite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maheraï de Nétophah; de Héled, fils de Baëna, de Nétophah;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ithaï, fils de Ribaï, de Gibea des Benjaminites; Benaïa, de Piratheon;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Huraï de Nahalei-Gaas; Abiel de Arba;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Azmaveth, le Baherumite; Elihaba, de Saalbon;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Benei-Hasem, de Gizon; Jonathan, fils de Sagè, de Harar;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Hahiam, fils de Sachar, de Harar; Eliphal, fils de Hur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hépher, de Mechébaï; Ahia, le Pelonite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hetsro, le Carmélite; Naaraï, fils de Ezbaï;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joël, frère de Nathan; Mibehar, fils de Hagri;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Tsélec, l\'Ammonite; Naheraï, le Bérothite, écuyer de Joab, fils de Tseruïa;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Irah, de Jéther; Gareb, de Jéther;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Uria le Héthien; Zabad, fils de Ahelaï;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, fils de Siza, le Rubénite, chef des Rubénites, suivi de trente hommes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanan, fils de Maëcha, et Josaphat, le Mithenite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Uzzia d\'Astherah; Sama et Jehiel, fils de Hotham d\'Aroër;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, fils de Simri, et Joha, son frère, le Thitsite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel de Mahevim; Jeribaï et Josavia, fils d\'Elnaam; et Jithma, le Moabite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel et Obed et Jaësiel-Hammetsobaïa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Et voici ceux qui joignirent David à Tsiklag lorsqu\'il était encore exclu de la présence de Saül, fils de Kis, et ceux-ci étaient du nombre des braves qui le secondaient à la guerre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'maniant l\'arc de la main droite, et de la gauche lançant des pierres, et décochant des flèches avec l\'arc, et du nombre des frères de Saül de Benjamin:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'le chef Ahiézer et Joas, fils de Semaa de Gibea, et Jéziel et Pélet, fils d\'Azmaveth, et Beracha et Jéhu d\'Anathoth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'et Jismaia de Gabaon, héros entre les trente, et commandant les trente, et Jérémie et Jehaziel et Jochanan et Jozabad, de Gedèra,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Elouzaï et Jerimoth et Bealia et Semaria et Sephatia, de Haroph,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elcana et Jissia et Azareël et Joëzer et Jasobeam, Coraïtes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'et Joëla et Zebadia, fils de Jeroham, de Gedor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Et parmi les Gadites vinrent comme transfuges joindre David à la forteresse du désert, des chefs de corps, soldats guerriers, armés de boucliers et de lances, ayant l\'air de lions et l\'agilité de la gazelle sur les montagnes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Ezer, le chef, Obadia, le second, Eliab, le troisième,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Mismanna, le quatrième, Jérémie, le cinquième,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Atthaï, le sixième, Eliel, le septième,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Jochanan, le huitième, Elzabad, le neuvième,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jérémie, le dixième, Machbanaï, le onzième:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'ils faisaient partie des fils de Gad, officiers de l\'armée, de cent l\'inférieur, de mille le supérieur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Ce furent eux qui passèrent le Jourdain, au premier mois, quand il remplit tout son lit, et mirent en fuite tous les habitants des vallées au levant et au couchant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Et des fils de Benjamin et de Juda vinrent aussi joindre David à la forteresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Et David sortit à leur rencontre, et prenant la parole, il leur dit: Si vous venez à moi en amis pour m\'aider, je m\'unirai de cœur à vous, mais si c\'est pour me surprendre au profit de mes ennemis, sans qu\'il y ait injustice en ma main, que le Dieu de nos pères voie et juge!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Alors revêtu d\'inspiration Amasaï, chef des triaires: Nous sommes à toi, David, [dit-il] et de ton bord, fils d\'Isaï! Salut, salut à toi, et salut à tes aides, car ton Dieu est ton aide! Et David les admit et les plaça comme chefs de bataillons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Et de Manassé des transfuges passèrent à David, lorsqu\'il allait en guerre contre Saül avec les Philistins, dont il ne resta pas l\'auxiliaire, car ensuite d\'une délibération les princes des Philistins le congédièrent, se disant: Au prix de nos têtes il passera du côté de son Seigneur Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Lorsqu\'il se rendit à Tsiklag, de Manassé lui vinrent en transfuges: Adna et Jozabad et Jediael et Michaël et Jozabad et Elihu et Tsilthaï, chef des mille de Manassé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Et ceux-ci aidèrent David contre les bandes, car ils étaient tous des héros belliqueux, et ils furent officiers supérieurs dans l\'armée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Car journellement il arrivait des auxiliaires à David jusqu\'à former une grande armée comme une armée de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Or voici le nombre par têtes des hommes armés en guerre qui joignirent David à Hébron pour lui déférer la royauté de Saül selon l\'ordre de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Fils de Juda portant bouclier et lance, six mille et huit cents, armés en guerre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'des fils de Siméon, héros belliqueux pour l\'armée, sept mille et cent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'des fils de Lévi, quatre mille six cents,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'et Joiada, le prince d\'Aaron, et avec lui trois mille et sept cents hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'et Tsadoc, jeune héros brave et sa maison patriarcale, vingt-deux chefs:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'et des fils de Benjamin, frères de Saül, trois mille: c\'est que jusqu\'alors la plus grande partie d\'entre eux adhérait encore à la maison de Saül,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'et des fils d\'Ephraïm vingt-mille huit cents, héros vaillants, hommes de renom, d\'après leurs maisons patriarcales;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'et de la demi-Tribu de Manassé dix-huit mille désignés nommément pour joindre et faire roi David;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'et des fils d\'Issaschar experts à comprendre les temps, pour savoir ce qu\'Israël avait à faire, leurs chefs au nombre de deux cents et dont tous leurs frères à leurs ordres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'de Zabulon ceux qui faisaient les campagnes, équipés pour le combat de toutes les armes de guerre, cinquante mille pour se ranger en bataille avec un cœur non partagé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'et de Nephthali mille chefs accompagnés de trente-sept mille portant bouclier et lance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'et des Danites armés en guerre, vingt-huit mille et six cents;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'et d\'Asser quarante mille se mettant en campagne pour se ranger en bataille;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'et d\'au delà le Jourdain, des Rubénites et des Gadites et de la demi-Tribu de Manassé, cent vingt mille avec toutes les armes de guerre pour le combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Tous ces hommes, gens de guerre, se formant en bataille avec, un cœur entier arrivèrent à Hébron pour établir David roi sur tout Israël. Et tout le restant d\'Israël était unanime aussi pour faire David roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Et ils furent là auprès de David trois jours, et mangèrent et burent, car leurs frères les pourvoyaient;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'et ceux aussi qui demeuraient près d\'eux jusqu\'à Issaschar, Zabulon et Nephthali apportaient des vivres à dos d\'ânes et de chameaux et de mulets et de bœufs, des mets de farine, des figues, des raisins secs et du vin, et de l\'huile, puis des bœufs et des moutons en abondance; car c\'était une joie en Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Et David se consulta avec les chefs de mille et de cent, avec la totalité des princes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Et David dit à toute l\'Assemblée d\'Israël: Si vous le trouvez bon, et si c\'est de par l\'Éternel notre Dieu, promptement dépêchons vers nos frères restés dans tous les cantons d\'Israël, et en même temps que vers eux, vers les Prêtres et les Lévites, dans leurs villes à banlieues pour qu\'ils se joignent à nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Et transférons l\'Arche de notre Dieu près de nous, car nous n\'en prenions point de souci au temps de Saül.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Et toute l\'Assemblée dit que c\'était ce qu\'il fallait faire, car la chose agréait à tout le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'David convoqua donc tout Israël depuis le Nil d\'Egypte jusque vers Hamath, afin d\'amener de Kiriath-Jearim l\'Arche de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Et David avec tout Israël monta vers Baala, à Kiriath-Jearim qui est à Juda, pour en ramener l\'Arche de Dieu, l\'Éternel qui siège sur les Chérubins, où le Nom est invoqué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Et ils transportèrent l\'Arche de Dieu sur un chariot neuf depuis la maison d\'Abinadab; or Uzza et Ahio conduisaient le chariot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Et David et tous les Israélites dansaient devant Dieu à toute force avec chants, et luths et harpes et tambourins et cymbales et trompettes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Et quand ils arrivèrent à l\'aire de Chidon, Uzza étendit sa main pour saisir l\'Arche parce que l\'attelage récalcitrait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Alors la colère de l\'Éternel s\'alluma contre Uzza et Il le frappa pour avoir porté la main sur l\'Arche, et il mourut là devant Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Et David fut attristé de ce que l\'Éternel avait frappé Uzza d\'un tel coup et il donna à ce lieu le nom de Pérets-Uzza (coup d\'Uzza) qu\'il porte encore aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Et David eut en ce jour peur de Dieu: il disait: Comment introduire chez moi l\'Arche de Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Et David ne fit pas prendre à l\'Arche son chemin vers lui dans la Cité de David, mais il la dirigea de côté vers la maison d\'Obed-Edom, de Gath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Et l\'Arche de Dieu séjourna ainsi dans la maison d\'Obed-Edom, dans sa maison, durant trois mois. Et l\'Éternel bénit la maison d\'Obed-Edom et tout ce qui était à lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Et Hiram, roi de Tyr, envoya des messagers à David, et du bois de cèdre et des maçons et des charpentiers, pour lui bâtir un palais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Et David sentit que l\'Éternel le consolidait comme roi d\'Israël et que son royaume était élevé toujours plus haut pour l\'amour de son peuple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Et David prit encore des femmes à Jérusalem, et engendra encore des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Or voici les noms de ceux qui lui naquirent à Jérusalem: Sammuah et Sobab, Nathan et Salomon');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'et Jibschar et Elisua et Elphalet');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'et Nogah et Népheg et Japhia');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'et Elisama et Beéliada et Eliphéleth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Et quand les Philistins apprirent que David avait été oint roi de la totalité d\'Israël, tous les Philistins s\'avancèrent à la recherche de David. A cette nouvelle, David sortit à leur rencontre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Et les Philistins vinrent se déployer dans la vallée, de Rephaïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Alors David interrogea Dieu en ces termes: Marcherai-je contre les Philistins et les livreras-tu entre mes mains? Et l\'Éternel lui répondit: Marche et je les livrerai entre tes mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Et ils se portèrent sur Baal-Pératsim et David les y battit et dit: L\'Éternel a par ma main rompu mes ennemis, comme les eaux faisant irruption. C\'est pourquoi on donna à ce lieu le nom de Baal-Pératsim (lieu d\'irruptions).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Et ils laissèrent là leurs dieux, qui, sur l\'ordre de David, furent livrés au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Et de nouveau les Philistins vinrent se déployer dans la vallée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Et David interrogea encore Dieu, et Dieu lui dit: Ne monte pas après eux, tourne-les et viens leur faire face vis-à-vis des baumiers-pleureurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Et quand tu entendras un bruit de pas dans les cimes des baumiers, alors montre-toi pour l\'attaque, car Dieu marche devant toi, pour battre l\'armée des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Et David s\'y prit comme Dieu lui en donnait l\'ordre, et il défit l\'armée des Philistins de Gabaon à Gézer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Et la renommée de David se répandit dans tous les pays, et l\'Éternel mit la terreur de son nom sur tous les peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Et il bâtit pour lui des maisons dans la Cité de David, et prépara une place à l\'Arche de Dieu et dressa une tente pour la recevoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Alors David dit: L\'Arche de Dieu ne doit être portée que par les Lévites, car c\'est eux que l\'Éternel a choisis pour porter l\'Arche de Dieu et en faire le service à perpétuité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Et David assembla tout Israël à Jérusalem pour transporter l\'Arche de l\'Éternel à sa place, qu\'il lui avait préparée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Et David réunit les fils d\'Aaron et les Lévites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'des fils de Cahath: Uriel, le chef, et ses frères, cent vingt;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'des fils de Merari: Asaïa, le chef, et ses frères, deux cent vingt;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'des fils de Gersom: Joël, le chef, et ses frères, cent trente;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'des fils d\'Elitsaphan: Semaïa, le chef, et ses frères, deux cents;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'des fils de Hébron: Eliel, le chef, et ses frères, quatre-vingts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'des fils de Uzziel: Amminadab, le chef, et ses frères, cent-douze.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Et David manda Tsadoc et Abiathar, Prêtres; et les Lévites Uriel, Asaïa et Joël; Semaïa, Eliel, et Amminadab,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'et leur dit: Vous êtes les patriarches des Lévites; mettez-vous en état de sainteté, vous et vos frères, et transportez l\'Arche de l\'Éternel, Dieu d\'Israël, au lieu que je lui ai préparé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'C\'est parce que la première fois vous ne l\'avez pas fait, que l\'Éternel, notre Dieu, a frappé un coup sur nous, parce que nous ne l\'avions pas consulté selon le droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Et les Prêtres et les Lévites se mirent en état de sainteté pour faire la translation de l\'Arche de l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Et les fils des Lévites portèrent l\'Arche de Dieu, comme Moïse l\'avait prescrit d\'après la parole de l\'Éternel, sur leurs épaules où posaient les barres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Et David dit aux chefs des Lévites de mettre de service leurs frères les chantres, avec des instruments de musique, harpes et luths et cymbales, retentissants, pour prendre un ton éclatant en signe de joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Et les Lévites mirent de service: Heiman, fils de Joël, et, de ses frères, Asaph, fils de Béréchia, et, des fils de Merari, leurs frères: Eithan, fils de Cusaïa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'et avec eux leurs frères puînés Zacharie, Ben et Jaëziel et Semiramoth et Jehiel et Unni, Eliab et Benaïa et Maëséia et Matthithia et Eliphéléhou et Micnéihu et Obed-Edom et Jeïel, portiers;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'et les chantres Heiman, Asaph et Eithan pour faire résonner les cymbales d\'airain, et');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Zacharie et Aziel et Semiramoth et Jehiel et Unni et Eliab et Maëséia et Benaïa avec des harpes en mode virginal');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'et Matthithia et Eliphéléhou et Micnéihu et Obed-Edom et Jeïel et Azazia avec des luths en octave de basse pour conduire le chant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Et Chenania, Maître chantre des Lévites, enseignait le chant, car il était entendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Et Béréchia et Elcana étaient portiers de l\'Arche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Et Sebania et Josaphat et Nethaneël et Amasaï et Zacharie et Benaïa et Eliézer, Prêtres, sonnaient des trompettes devant l\'Arche de Dieu. Et Obed-Edom et Jehia étaient portiers de l\'Arche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Ainsi David et les Anciens d\'Israël et les chefs de mille partirent pour transporter l\'Arche de l\'alliance de l\'Éternel de la maison d\'Obed-Edom, dans l\'allégresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Et comme Dieu fut en aide aux Lévites qui portaient l\'Arche d\'alliance de l\'Éternel, ils sacrifièrent sept taureaux et sept béliers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Et David était revêtu d\'un manteau de byssus, de même que tous les Lévites, porteurs de l\'Arche, et les chantres et Chenania, Maître chantre parmi les chantres; et David portait un éphod de lin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Et tout Israël opéra la translation de l\'Arche de l\'alliance de l\'Éternel avec des acclamations et au son des clairons et des trompettes et des cymbales, faisant résonner les harpes et les luths.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Et lorsque l\'Arche d\'alliance de l\'Éternel atteignait la cité de David, Michal, fille de Saül, regardait par la fenêtre, et elle vit le roi David dansant et sautant, et elle conçut pour lui du mépris en son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Et ils introduisirent l\'Arche de Dieu et la placèrent au centre de la Tente que lui avait dressée David, et ils offrirent des holocaustes et des sacrifices pacifiques en la présence de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Et après avoir achevé l\'oblation des holocaustes et des sacrifices pacifiques, David bénit le peuple au nom de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Et il distribua à tous les Israélites, et hommes et femmes, à chacun, une galette de pain et une ration [de vin] et de raisins secs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Et il plaça devant l\'Arche de l\'Éternel des Lévites comme desservants et pour célébrer et pour louer et magnifier l\'Éternel, Dieu d\'Israël:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asaph, comme chef, et Zacharie, comme son second, Jeïel et Semiramoth et Jehiel et Matthithia et Eliab et Benaïa et Obed-Edom et Jeïel avec des harpes et des luths, et Asaph faisant résonner les cymbales;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'et Benaïa et Jahaziel, Prêtres, sonnant constamment des trompettes devant l\'Arche d\'alliance de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'En ce jour, alors pour la première fois, David chargea Asaph et ses frères de rendre grâces à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Louez l\'Éternel, invoquez son Nom! Publiez ses exploits parmi les peuples!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Célébrez-le par vos chants et vos accords! Chantez toutes ses merveilles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Glorifiez-vous de son saint Nom! Qu\'ils aient le cœur joyeux ceux qui cherchent l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Méditez sur l\'Éternel et sa puissance! Cherchez sans cesse sa présence!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Pensez aux merveilles qu\'il a faites, à ses prodiges et aux jugements émanés de sa bouche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Race d\'Israël, son serviteur, enfants de Jacob, ses élus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Lui, l\'Éternel! Il est notre Dieu, ses jugements embrassent toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Pensez toujours à son alliance, parole qu\'il a promulguée pour mille générations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'qu\'Il a conclue avec Abraham, et au serment qu\'il a fait à Isaac;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'et il a érigée pour Jacob en statut, et pour Israël en alliance éternelle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'disant: Je te donnerai la terre de Canaan comme votre lot d\'héritage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'alors vous étiez encore un petit nombre, peu considérables et étrangers dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Ils émigraient de nation en nation, d\'un royaume chez un autre peuple:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Il ne permettait à personne de les opprimer, et à cause d\'eux Il châtia des rois:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Ne touchez pas à mes oints, et ne maltraitez pas mes prophètes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Chantez à l\'Éternel, vous tous les habitants de la terre! Annoncez son salut de jour en jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Racontez parmi les nations sa gloire, parmi tous les peuples ses merveilles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Car l\'Éternel est grand et digne d\'une grande louange, et plus redoutable que tous les dieux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'car tous les dieux des peuples sont des idoles, et l\'Éternel a fait les cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Devant sa face, c\'est splendeur et majesté, gloire et allégresse dans sa demeure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Tribus des peuples, rendez à l\'Éternel, rendez à l\'Éternel l\'honneur et la louange!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'rendez à l\'Éternel l\'honneur dû à son Nom! apportez des offrandes et venez devant lui! Adorez l\'Éternel avec une pompe sainte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Tremblez devant lui, vous toutes les contrées! le monde est ferme et ne chancelle pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Que les cieux se réjouissent et que la terre tressaille! qu\'on dise parmi les peuples: L\'Éternel règne!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Que la mer s\'émeuve avec tout ce qu\'elle enserre! que les campagnes s\'égayent avec tout ce qui les couvre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'que les arbres des forêts acclament l\'Éternel, car Il vient pour juger la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Louez l\'Éternel, car Il est bon, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'et dites: Sauve-nous, ô notre Dieu sauveur, recueille et retire-nous du milieu des peuples, pour que nous chantions ton saint Nom, que nous fassions gloire de te louer!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Béni soit l\'Éternel, Dieu d\'Israël, de l\'éternité a l\'éternité! et que tout le peuple dise: Ainsi soit-il! Alléluia!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Et il laissa là devant l\'Arche d\'alliance de l\'Éternel Asaph et ses frères, pour faire devant l\'Arche le service ordinaire, quotidien;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'et Obed-Edom [et Hosa] et leurs frères au nombre de soixante-huit, et Obed-Edom, fils de Jeduthun, et Hosa comme portiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Et il laissa Tsadoc, le Prêtre, et ses frères les Prêtres devant la Résidence de l\'Éternel sur la hauteur de Gabaon');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'pour offrir des holocaustes à l\'Éternel sur l\'autel aux holocaustes, à l\'ordinaire, matin et soir, selon tout le texte de la Loi de l\'Éternel, par Lui prescrite à Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'et avec eux Heiman et Jeduthun et les autres élus nommément désignés pour rendre grâces à l\'Éternel de ce que sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'et avec eux Heiman et Jeduthun pour faire résonner les trompettes et les cymbales et les instruments de musique de Dieu, et les fils de Jeduthun comme portiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Et tout le monde se retira, chacun dans sa maison, et David s\'en retourna pour bénir sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Et comme David habitait son palais, David dit à Nathan, le prophète: Voici que je réside dans un palais de cèdre, et l\'Arche d\'alliance de l\'Éternel est sous des toiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Et Nathan dit à David: Exécute tout ce que tu as dans le cœur, car Dieu est avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Mais cette nuit même la parole de Dieu fut adressée à Nathan en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Va et dis à David, mon serviteur: Ainsi parle l\'Éternel: Ce n\'est pas toi qui me bâtiras le Temple pour ma résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Car je n\'ai pas eu de temple pour résidence depuis le jour où j\'ai retiré Israël jusqu\'aujourd\'hui, et j\'ai été de tente en tente et de résidence en résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Pendant toute la période de mes migrations, au milieu de tout Israël, est-ce que j\'ai adressé une parole à l\'un des juges d\'Israël à qui j\'avais commandé d\'être le pasteur de mon peuple et dit: Pourquoi ne me bâtissez-vous pas un temple de cèdre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Or, ainsi parle à mon serviteur, à David: Ainsi parle l\'Éternel des armées: Je t\'ai pris au pâturage derrière le troupeau pour te faire prince de mon peuple d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'et j\'ai été avec toi partout où tu as porté tes pas, et taillé en pièces tous tes ennemis devant toi, et t\'ai fait un nom égal au nom des grands sur la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'et je donnerai un lieu fixe à mon peuple d\'Israël et je le planterai pour qu\'il ait une demeure stable et ne soit plus agité, et que les pervers ne le dévorent plus comme dans l\'origine');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'et depuis le temps que je préposai des Juges sur mon peuple d\'Israël, et j\'abaisserai tous tes ennemis, et je t\'ai annoncé que l\'Éternel t\'élèvera une maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Et lorsque tes jours seront au complet pour joindre tes pères, j\'élèverai ta race après toi, l\'un de toi et je consoliderai son empire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'C\'est lui qui me bâtira un temple, et je consoliderai son trône pour l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Je serai pour lui un père et il sera pour moi un fils et je ne lui retirerai pas ma grâce, comme je l\'ai retirée à ton prédécesseur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'mais je l\'affermirai dans ma maison et mon royaume pour l\'éternité, et son trône sera stable éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Nathan rendit à David la totalité de ces paroles et de cette révélation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Alors le roi David entra et se plaça en la présence de l\'Éternel et dit: Éternel, Dieu, qui suis-je et qu\'est ma maison, que tu m\'aies fait parvenir à ce point?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Et cependant, ô Dieu, à tes yeux c\'était peu, et tu parles au sujet de la maison de ton serviteur pour un temps éloigné et tu m\'as fait voir la série des hommes jusques au haut, Éternel, Dieu!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Qu\'aurait encore David à te dire de plus de l\'honneur accordé à ton serviteur? Tu connais ton serviteur!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Éternel! c\'est en vue de lui et selon ton amour que tu as opéré toute cette magnificence pour manifester toutes les grandeurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Éternel, nul n\'est comme toi, et il n\'est point de Dieu que toi, d\'après tout ce que nous avons ouï de nos oreilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Et où est sur la terre une nation comme ton peuple d\'Israël, que Dieu soit venu se racheter pour en faire son peuple, et t\'acquérir un nom, et opérer des actes grands et terribles en expulsant les nations devant ton peuple que tu avais racheté de l\'Egypte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Ainsi, tu t\'es donné ton peuple d\'Israël pour être ton peuple à jamais, et toi, Éternel, tu es devenu leur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Maintenant donc, Éternel, que la parole que tu as prononcée sur ton serviteur et sa maison, soit vraie éternellement, et fais comme tu as dit!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Et que ton Nom se justifie et grandisse éternellement afin que l\'on dise: L\'Éternel des armées est Dieu d\'Israël, un Dieu pour Israël, et la maison de David, ton serviteur, est stable devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Car toi-même, ô mon Dieu, tu as révélé à ton serviteur que tu lui élèveras une maison; c\'est pourquoi ton serviteur ose te présenter sa prière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Or, c\'est toi, Éternel, qui es Dieu, et tu as fait à ton serviteur cette excellente promesse:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'qu\'il te plaise donc bénir la maison de ton serviteur, afin qu\'elle subsiste éternellement devant toi, car c\'est toi, Éternel, qui bénis, et par toi on est éternellement béni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Et dans la suite David battit les Philistins et les abaissa, et il enleva Gath et ses annexes à la domination des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Et il battit les Moabites et les Moabites furent asservis à David, payant le tribut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Et David battit Hadarézer, roi de Tsoba, vers Hamath, comme il allait établir sa puissance sur l\'Euphrate.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Et David lui enleva mille chars et sept mille cavaliers et vingt mille fantassins, et David coupa le tendon à tous les chevaux de trait, dont il garda une centaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Et les Syriens de Damas vinrent au secours d\'Hadarézer, roi de Tsoba, et David mit des Syriens vingt-deux mille hommes en déroute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Et David mit [garnison] dans la Syrie de Damas, et les Syriens furent asservis à David payant le tribut. Et l\'Éternel était en aide à David dans toutes ses campagnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Et David prit les boucliers d\'or que portaient les serviteurs d\'Hadarézer et les amena à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Et de Tibehath et de Chun, villes d\'Hadarézer, David enleva de l\'airain en très grande quantité, dont Salomon fit la mer d\'airain et les colonnes et les ustensiles d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Et Thôou, roi de Hamath, apprenant que David avait abattu toute la puissance d\'Hadarézer, roi de Tsoba,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'envoya Hadoram, son fils, au roi David pour le saluer et le féliciter d\'avoir combattu Hadarézer et de l\'avoir défait, (car Thôou était en guerre avec Hadarézer) et toutes sortes d\'ustensiles d\'or, d\'argent et d\'airain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'que le roi David consacra aussi à l\'Éternel avec l\'argent et l\'or qu\'il avait pris sur toutes les nations, sur les Edomites et les Moabites et les Ammonites et les Philistins et les Amalécites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Et Abisaï, fils de Tseruïa, défit dans la vallée du sel les Edomites, au nombre de dix-huit mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'Et il mit des garnisons en Edom, et tout Edom fut assujetti à David. Ainsi l\'Éternel était en aide à David dans toutes ses campagnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Et David régnait sur la totalité d\'Israël, et il faisait droit et justice à tout son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Et Joab, fils de Tseruïa, était préposé sur l\'armée, et Josaphat, fils d\'Ahilud, était chancelier;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'et Tsadoc, fils d\'Ahitub, et Abimélech, fils d\'Abiathar, étaient Prêtres; et Savsa, secrétaire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'et Benaïa, fils de Joiada, était préposé sur les exécuteurs et les coureurs; et les fils de David étaient les premiers au côté du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Et dans la suite vint à mourir Nahas, roi des Ammonites, et son fils régna à sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Alors David dit: Je témoignerai de la bonté à Hanoun, fils de Nahas, car son père m\'a témoigné de la bonté. Et David délégua des envoyés pour le consoler au sujet de son père. Ainsi vinrent des serviteurs de David au pays des Ammonites, chez Hanoun pour le consoler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Alors les chefs des Ammonites dirent à Hanoun: Est-ce, à tes yeux, pour honorer ton père que David t\'envoie des consolateurs? N\'est-ce pas dans le but d\'explorer, de bouleverser, et d\'espionner le pays que ses serviteurs sont venus te trouver?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Là-dessus Hanoun fit prendre et raser les serviteurs de David et leur fit couper les habits jusqu\'à mi-hanches, puis les congédia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Et l\'on vint renseigner David touchant ces hommes, et il envoya à leur rencontre (car ces hommes étaient fort outragés), et le roi dit: Restez à Jéricho jusqu\'à ce que votre barbe ait poussé, puis revenez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Et les Ammonites virent qu\'ils étaient en mauvaise odeur auprès de David, et Hanoun et les Ammonites envoyèrent mille talents d\'argent pour prendre à leurs gages des chars et de la cavalerie chez les Syriens de Mésopotamie et les Syriens de Maacha et de Tsoba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Et ils prirent à leur solde trente-deux mille chars et le roi de Maacha et son monde: ceux-ci vinrent et campèrent devant Médeba. Et les Ammonites se rassemblèrent de leurs villes et arrivèrent pour se battre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'A cette nouvelle, David fit partir Joab et toute l\'armée des guerriers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Et les Ammonites sortirent et se rangèrent en bataille en dehors des portes de la ville tandis que les rois venus étaient seuls dans la campagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Et Joab se voyant attaqué par devant et par derrière, fit un choix dans toute l\'élite d\'Israël et forma sa ligne contre les Syriens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'laissant sous la conduite de son frère Abisaï le reste de la troupe, qui forma sa ligne contre les Ammonites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Et il dit: Si les Syriens prennent l\'avantage sur moi, viens à mon secours; et si les Ammonites prennent l\'avantage sur toi, j\'irai à ton secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Tiens bien, et tenons bien pour notre peuple et pour les cités de notre Dieu, et que l\'Éternel agisse comme il Lui semblera bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Joab donc et la troupe qui était avec lui, s\'avança à l\'attaque des Syriens qui s\'enfuirent devant lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Et les Ammonites voyant les Syriens en fuite, prirent aussi la fuite devant Abisaï, son frère, et rentrèrent dans la ville. Et Joab gagna Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Et les Syriens se voyant battus par les Israélites dépêchèrent des messagers et firent mettre en campagne les Syriens d\'au delà le Fleuve, et Sophach, général d\'armée d\'Hadarézer, à leur tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Et David en reçut l\'avis; et il rassembla tous les Israélites et passa le Jourdain et les joignit et forma sa ligne contre eux, et David se rangea en bataille contre les Syriens, qui en vinrent aux mains avec lui. Mais les Syriens s\'enfuirent devant les Israélites,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'et David fit aux Syriens un massacre de sept mille chars et quarante mille fantassins et tua Sophach, général de l\'armée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Et les serviteurs d\'Hadarézer se voyant battus par les Israélites firent la paix avec David, auquel ils furent asservis. Et les Syriens ne voulurent plus porter secours aux Ammonites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Et à l\'époque du retour de l\'année, à l\'époque de la mise en campagne des rois, Joab conduisit la force armée, et ravagea le pays des Ammonites et vint mettre le siège devant Rabba. Cependant David resta à Jérusalem. Et Joab vint à bout de Rabba et la détruisit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Et David prit la couronne de leur roi de dessus sa tête, et la trouva pesant un talent d\'or et garnie de pierres précieuses, et il la posa sur sa propre tête, et il tira dehors le butin de la ville en immense quantité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Et il la fit évacuer par le peuple qui l\'habitait, et les hacha avec des scies et des traîneaux ferrés et des cognées. Et David en fit autant à toutes les villes des Ammonites. Puis David avec tout son monde revint à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Et dans la suite il y eut hostilité à Gézer avec les Philistins. Alors Sibkaï, de Husta, battit Sippaï, l\'un des enfants nés à Rapha, et les Philistins furent abaissés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Et il y eut encore hostilité avec les Philistins. Alors Elchanan, fils de Jaïs, battit Lachemi, frère de Goliath, de Gath. Or la hampe de sa lance était comme une ensuble de tisserand.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Et il y eut de nouveau hostilité à Gath. Là était un homme de haute stature, qui avait six doigts et six orteils, vingt-quatre. Lui aussi était des enfants nés à Rapha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Et il défia Israël. Et Jonathan, fils de Simea, frère de David, le battit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Ces hommes étaient nés à Rapha à Gath, et ils périrent par la main de David et par la main de ses serviteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Et Satan se dressa contre Israël et incita David à dénombrer Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Alors David dit à Joab et aux chefs du peuple: Allez, comptez les Israélites de Béerséba à Dan et faites-moi rapport, afin que j\'en sache le nombre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Et Joab dit: Puisse l\'Éternel augmenter le peuple au centuple de ce qu\'il est! Ne sont-ils pas tous, ô roi, mon seigneur, sujets de mon seigneur? Pourquoi mon seigneur a-t-il un tel désir? Pourquoi, mettre Israël en état de délit?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Mais la parole du roi prévalut contre Joab, qui partit, fit la tournée de tout Israël et revint à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Alors Joab rendit compte à David du recensement du peuple. Et dans tout Israël il y avait un million cent mille hommes tirant l\'épée, et en Juda quatre cent soixante-dix mille hommes tirant l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Mais il ne fit pas la revue de Lévi et de Benjamin parmi eux; car l\'ordre du roi était une abomination pour Joab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Et la mesure déplut à Dieu qui frappa Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Et David dit à Dieu: J\'ai gravement péché en faisant cette chose-là! Et maintenant, oh! pardonne la faute de ton serviteur, car j\'ai très follement agi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Et l\'Éternel parla à Gad, Voyant de David, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Va et parle à David en ces termes: Ainsi parle l\'Éternel: Je te propose trois choses, choisis-en une, afin que je l\'exécute sur toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Et Gad vint trouver David et lui dit: Ainsi parle l\'Éternel:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Accepte, ou pour trois ans la famine, ou pour trois mois la fuite devant tes adversaires sous l\'atteinte de l\'épée de tes ennemis, ou pour trois jours l\'épée de l\'Éternel et la peste dans le pays et l\'Ange de l\'Éternel répandant le carnage dans toutes les limites d\'Israël; vois donc quelle réponse je dois rendre à Celui qui m\'envoie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Alors David dit à Gad: Je suis fort angoissé!..., oh! que je tombe par la main de l\'Éternel, car sa miséricorde est infinie; mais que je ne tombe pas par une main d\'homme!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Et l\'Éternel infligea une peste à Israël, et il périt dans Israël soixante-dix mille hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Et Dieu envoya un Ange dans Jérusalem pour la ravager, et pendant qu\'il ravageait, l\'Éternel était témoin, et Il eut regret du désastre et dit à l\'Ange destructeur: Assez! ramène ta main. Or l\'Ange de l\'Éternel se tenait près de l\'aire d\'Ornan le Jébusite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Et David levant les yeux vit l\'Ange de l\'Éternel debout entre la terre et le ciel, ayant en main son glaive nu étendu sur Jérusalem. Alors David et les Anciens, couverts de cilices, tombèrent la face contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Et David dit à Dieu: N\'est-ce pas moi qui ai ordonné le dénombrement du peuple? C\'est donc moi qui suis le coupable et qui ai forfait; mais ceux-ci, le troupeau, qu\'ont-ils fait? Éternel, mon Dieu, oh! que ta main se dirige sur moi et la maison de mon père, mais pas sur ton peuple, pour frapper.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Cependant l\'Ange de l\'Éternel dit à Gad de dire à David, que David eût à monter pour ériger un autel à l\'Éternel sur l\'aire d\'Ornan le Jébusite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Et David monta suivant la parole de Gad, qu\'il avait dite au nom de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Et Ornan s\'étant retourné vit l\'Ange, et lui et ses quatre fils avec lui se cachèrent. Or Ornan foulait alors le froment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Et David arriva chez Ornan; et Ornan ayant regardé vit David, puis sortit de l\'aire et se prosterna devant David la face contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Et David dit à Ornan: Cède-moi l\'emplacement de ton aire pour que j\'y élève un autel à l\'Éternel, cède-le-moi pour la valeur totale, afin que le fléau soit éloigné de dessus le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Et Ornan dit à David: Accepte-le, et que mon seigneur le roi fasse ce qui lui semblera bon; voici, je donne les taureaux pour l\'holocauste et les traîneaux pour le bûcher et le blé pour l\'offrande; je donne tout cela.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Et le roi David dit à Ornan: Non! mais je veux l\'acquérir pour la valeur totale, car je n\'offrirai point à l\'Éternel ce qui est à toi et ne sacrifierai point un holocauste qui ne coûte rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'David paya donc à Ornan pour l\'emplacement, en sicles d\'or, six cents sicles pesant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Et David y éleva un autel à l\'Éternel et offrit des holocaustes et des sacrifices pacifiques et invoqua l\'Éternel, qui lui répondit par le feu du ciel qui vint sur l\'autel de l\'holocauste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Et l\'Éternel parla à l\'Ange, qui remit son épée dans le fourreau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Dans le même temps David voyant que l\'Éternel l\'exauçait à l\'aire d\'Ornan, le Jébusite, y offrit des sacrifices.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Or la Résidence de l\'Éternel que Moïse avait faite dans le désert, et l\'autel des holocaustes étaient en ce temps sur la hauteur de Gabaon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'mais David n\'osait s\'y présenter pour chercher Dieu, parce qu\'il avait pris l\'épouvante en face de l\'épée de l\'Ange de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Et David dit: C\'est ici que doit être le Temple de l\'Éternel, Dieu, et ici l\'autel pour les holocaustes d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Et David dit de ramasser les étrangers qui étaient dans le pays d\'Israël; et il désigna des tailleurs de pierre pour tailler les carrés de pierres en vue de la bâtisse du Temple de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Et David avait préparé du fer en masse pour les clous des battants des portes et les crampons, et une quantité incalculable d\'airain');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'et des pièces de cèdre sans nombre; car les Sidoniens et les Tyriens avaient amené à David du bois de cèdre en masse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Car David disait: Salomon, mon fils, est enfant et dans l\'âge tendre; or il s\'agit de bâtir à l\'Éternel un temple majestueux, élevé, qui ait un nom et du lustre en tout pays; je veux donc faire pour lui les apprêts. C\'est pourquoi David fit des préparatifs immenses avant de mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Et il manda Salomon, son fils, et lui ordonna de construire un Temple à l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Et David dit à Salomon: Mon fils, je pensais à élever un Temple au Nom de l\'Éternel, mon Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Mais la parole de l\'Éternel m\'a été adressée en ces termes: Tu as versé beaucoup de sang et fait de grandes guerres: ce n\'est pas à toi à élever un temple à Mon Nom, car tu as fait couler beaucoup de sang sur la terre devant moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Voilà qu\'un fils t\'est né; il sera un homme de paix, et je lui assurerai la paix de la part de tous ses ennemis d\'alentour, car Salomon (le pacifique) sera son nom, et je doterai Israël de la paix et de la tranquillité pendant sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'C\'est lui qui élèvera un temple à Mon Nom, et il sera pour moi un fils et je serai pour lui un père, et je consoliderai le trône de sa souveraineté sur Israël pour l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Dès lors, mon fils, que l\'Éternel soit avec toi, pour que tu réussisses à élever un temple à l\'Éternel, ton Dieu, ainsi qu\'il l\'a dit de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Seulement que l\'Éternel t\'accorde sagesse et intelligence et te prépose sur Israël! et tu auras à garder la Loi de l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Alors tu seras heureux, si tu veilles à pratiquer les décrets et les lois que l\'Éternel a prescrites à Moïse pour Israël. Courage! et force! sois sans crainte et sans peur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Et voilà que, par mes pénibles efforts, j\'ai préparé en vue du Temple de l\'Éternel, en or, cent mille talents, et en argent, un million de talents, et en fer et en airain, une quantité incalculable, car il y en a une masse; et j\'ai aussi préparé du bois et des pierres; et tu pourras y ajouter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Et tu as une multitude d\'artisans, des tailleurs de pierre et des ouvriers en pierre et en bois, et toute espèce d\'hommes experts en tous métiers;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'l\'or, l\'argent, l\'airain et le fer ne sauraient être comptés. Debout donc et exécute, et que l\'Éternel soit avec toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Et David enjoignit à tous les princes d\'Israël d\'aider Salomon, son fils:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, '« Est-ce que l\'Éternel, votre Dieu, n\'est pas avec vous, et ne vous a-t-Il pas mis en paix avec vos alentours? Car Il a mis en ma main les habitants du pays, et le pays est soumis devant l\'Éternel et devant son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Maintenant appliquez vos cœurs et vos âmes à chercher l\'Éternel, votre Dieu, et mettez-vous à l\'œuvre, et élevez le Sanctuaire de l\'Éternel, Dieu, pour installer l\'Arche d\'alliance de l\'Éternel et les saints ustensiles de Dieu dans le Temple élevé au Nom de l\'Éternel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Et David devenu vieux, et rassasié de jours, fit Salomon, son fils, roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Et il assembla tous les princes d\'Israël et les Prêtres et les Lévites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Et l\'on dressa un état des Lévites depuis trente ans et au-dessus, et leur nombre compté par tête d\'homme fut de trente-huit mille:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, '« Que d\'entre eux vingt-quatre mille aient la conduite des travaux du Temple de l\'Éternel, et que six mille soient scribes et juges,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'et quatre mille, portiers, et quatre mille, chargés de louer l\'Éternel avec les instruments que j\'ai faits pour le louer. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Et David les divisa en classes selon les fils de Lévi, Gerson, Kahath et Merari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Des Gersonites c\'étaient: Laëdan et Siméï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Fils de Laëdan; le chef Jehiel et Zétham et Joël, trois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Les fils de Siméï: Selomith et Haziel, et Haran, trois: ceux-ci étaient patriarches de [la maison de] Laëdan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Et les fils de Siméï: Jahafh, Zina et Jeüs et Bria: ce sont des fils de Siméï, quatre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Et Jahath était le chef, et Zina, le second; et Jeüs et Bria n\'eurent pas beaucoup de fils; c\'est pourquoi ils formèrent une seule maison patriarcale et une classe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Fils de Kahath: Amram, Jitsehar, Hébron et Uzziel, quatre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Fils d\'Amram: Aaron et Moïse. Et Aaron fut séparé pour le saint service du Lieu Très-Saint, lui et ses fils à perpétuité, pour offrir l\'encens à l\'Éternel et Le servir et bénir en Son Nom à perpétuité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Quant à Moïse, homme de Dieu, ses fils furent agrégés à la Tribu de Lévi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Fils de Moïse: Gersom et Eliézer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Fils de Gersom: Sebuel, le chef. Et les fils d\'Eliézer furent: Rehabia, le chef;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'et Eliézer n\'eut pas d\'autre fils; mais les fils de Rehabia furent fort nombreux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Fils de Jitsehar: Selomith, le chef.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Fils d\'Hébron: Jeria, le chef, Amaria, le second, Jahaziel, le troisième, et Jecameam, le quatrième.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Fils d\'Uzziel: Micha, le chef, et Jissia, le second.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Fils de Merari: Machli et Musi. Fils de Machli: Eléazar et Kis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Et Eléazar mourut; et il n\'avait pas de fils, mais des filles qu\'épousèrent les fils de Kis, leurs frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Fils de Musi: Machli et Eder et Jerémoth, trois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Ce sont là les fils de Lévi, selon leurs maisons patriarcales et leurs patriarches, ainsi qu\'ils furent recensés selon le nombre des noms par tête, occupés au service de la maison de l\'Éternel dès l\'âge de vingt ans et au-dessus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Car David dit: L\'Éternel, Dieu d\'Israël, a donné la paix à son peuple, et il habite Jérusalem à perpétuité:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'dès lors les Lévites n\'ont plus à transporter la Résidence et tout le mobilier affecté à son service.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Car c\'est ensuite des derniers ordres de David qu\'eut lieu ce dénombrement des fils de Lévi dès l\'âge de vingt ans et au-dessus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Car leur poste était à côté des fils d\'Aaron pour le service de la maison de l\'Éternel, pour le soin des parvis et des cellules, la purification de tous les objets sacrés et le détail du service de la maison de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'les pains de présentation et la fleur de farine pour l\'offrande et les oublies azymes, et la poêle et le grillé et toutes les mesures de capacité et de longueur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'et pour être assidus chaque matin à l\'action de grâces et à la louange de l\'Éternel, et de même le soir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'et pour offrir tous les holocaustes à l\'Éternel, aux jours de sabbat, de lune nouvelle et de fêtes, selon le nombre et le rite, à la continue devant l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'et pour vaquer à l\'entretien de la Tente du Rendez-vous et à l\'entretien du Sanctuaire, et au soin des fils d\'Aaron, leurs frères, pour le service du Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Et quant aux fils d\'Aaron, voici leurs classes. Fils d\'Aaron: Nadab et Abiliu, Eléazar et Ithamar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Et Nadab et Abihu moururent avant leur père, et ils n\'avaient pas de fils, et Eléazar et Ithamar furent revêtus du sacerdoce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Et David les divisa ainsi, [d\'un côté] Tsadoc d\'entre les fils d\'Eléazar, [de l\'autre] Ahimélech d\'entre les fils d\'Ithamar, selon leur classement dans leur service.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Et il se trouva dans les fils d\'Eléazar plus de patriarches que dans les fils d\'Ithamar, et division en fut faite; les fils d\'Eléazar avaient seize chefs de maisons patriarcales, et les fils d\'Ithamar, selon leurs maisons patriarcales, huit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Et la division se fit par le sort pour les uns comme pour les autres; car les primiciers du Sanctuaire, et les primiciers de Dieu étaient des fils d\'Eléazar et des fils d\'Ithamar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Et ils furent inscrits par Semaïa, fils de Nethaneël, scribe de la Tribu de Lévi, devant le roi, et les princes, et le Prêtre Tsadoc, et Abimélech, fils d\'Abiathar, et les patriarches des Prêtres et des Lévites; chaque maison patriarcale fut tirée au sort pour Eléazar, et pour Ithamar il y eut double tirage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Et le premier bulletin sortit pour Jojarib; pour Jedaïa le second;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'pour Harim le troisième; pour Seorim le quatrième;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'pour Malchiia le cinquième; pour Mijamin le sixième;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'pour Haccots le septième; pour Abia le huitième;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'pour Jèsua le neuvième; pour Sechania le dixième;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'pour Eliasib le onzième; pour Jakim le douzième;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'pour Huppa le treizième; pour Jésébeab le quatorzième;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'pour Bilga le quinzième; pour Immer le seizième;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'pour Hezir le dix-septième; pour Happitsets le dix-huitième;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'pour Pethaïa le dix-neuvième; pour Ihezkel le vingtième;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'pour Jachin le vingt-unième; pour Gamul le vingt-deuxième;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'pour Delaïa le vingt-troisième; pour Maazia le vingt-quatrième.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Telle est leur classification pour leur service, pour leur entrée dans le Temple de l\'Éternel selon leur règle dressée par Aaron, leur père, selon l\'ordre qu\'il en avait reçu de l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Et quant aux fils de Lévi, voici les restants: des fils d\'Amram: Subaël; des fils de Subaël: Jehdia;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'de Rehabia, des fils de Rehabia: le chef Jissia;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'des Jitseharites: Selomoth; des fils de Selomoth: Jahath;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'et les fils [d\'Hébron:] Jeria [le chef], Amaria, le second, Jaheziel, le troisième, Jecameam, le quatrième;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'fils d\'Uzziel: Micha; fils de Micha: Samir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'le frère de Micha: Jissia; des fils de Jissia: Zacharie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'fils de Merari: Machli et Musi, fils de Jaëzia, son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Les fils de Merari, de Jaëzia son fils: Soham et Zaccur et Ibri;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'de Machli: Eléazar, lequel n\'eut point de fils;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'de Kis, le fils de Kis: Jérahmeël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'et les fils de Musi: Machli et Eder et Jerimoth. Tels étaient les fils des Lévites selon leurs maisons patriarcales.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Et eux aussi ils tirèrent au sort comme leurs frères, les fils d\'Aaron, devant le roi David et Tsadoc et Ahimélech et les patriarches des Prêtres et des Lévites, le patriarche aussi bien que son frère cadet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Et David et les généraux de l\'armée mirent à part, pour le service, des fils d\'Asaph et d\'Heiman et de Jeduthun jouant avec animation du luth, de la harpe et des cymbales, et le nombre des hommes occupés à leur office était:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'des fils d\'Asaph: Zaccur et Joseph et Nethania et Asarèla, fils d\'Asaph, subordonnés à Asaph qui exécutait sous les ordres du roi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'de Jeduthun, les fils de Jeduthun: Gedalia et Tseri et Esaïe, Hasabia et Matthithia [et Siméï], six sous les ordres de leur père Jeduthun qui jouait du luth pour célébrer et louer l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'd\'Heiman, les fils d\'Heiman: Buchia et Matthania, Uzziel, Sebul et Jerimoth, Hanania, Hanani, Eliatha, Giddalthi et Romamethi-Ezer, Josbecasa, Mallothi, Hothir, Mahezioth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'tout autant de fils d\'Heiman, Voyant du roi, suivant l\'ordre de Dieu pour sonner du cor; et Dieu accorda à Heiman quatorze fils et trois filles:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'tous ils étaient sous la conduite de leur père aux concerts du Temple de l\'Éternel, avec des cymbales, des harpes et des luths pour le service de la maison de Dieu: sous la conduite du roi étaient Asaph et Jeduthun et Heiman.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Et leur nombre, y compris leurs frères formés au chœur de l\'Éternel, tous les habiles, était de deux cent quatre-vingt-huit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Et ils tirèrent au sort leur office, sur le même pied, petit et grand, habile et élève.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Et le premier bulletin sortit pour Asaph [c\'est-à-dire] Joseph [son fils]; pour Gedalia le second, pour lui et ses frères et fils, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'le troisième pour Zaccur, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'le quatrième pour Jitseri (Tseri), ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'le cinquième pour Nethania, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'le sixième pour Buckia, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'le septième pour Jesarèla (Asarèla), ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'le huitième pour Ésaïe, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'le neuvième pour Matthania, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'le dixième pour Siméï, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'le onzième pour Azaréel (Uzziel), ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'le douzième pour Hasabia, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'le treizième pour Subaël (Sebuël), ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'le quatorzième pour Matthithia, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'le quinzième pour Jerémoth, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'le seizième pour Hanania, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'le dix-septième pour Josbecasa, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'le dix-huitième pour Hanani, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'le dix-neuvième pour Maltothi, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'le vingtième pour Eliath, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'le vingt-unième pour Hothir, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'le vingt-deuxième pour Giddalthi, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'le vingt-troisième pour Mahezioth, ses fils et frères, douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'le vingt-quatrième pour Romamethi-Ezer, ses fils et frères, douze.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Quant aux classes des portiers, des Coraïtes: Méselmia, fils de Coré, d\'entre les fils d\'Asaph;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'et les fils de Méselmia: Zacharie, le premier-né, Jediaël, le second, Zebadia, le troisième, Jathniel, le quatrième,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Eilam, le cinquième, Jochanan, le sixième, Elioeinaï, le septième;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'et les fils d\'Obed-Edom: Semaïa, le premier-né, Jozabad, le second, Joah, le troisième, et Sachar, le quatrième, et Nethaneël, le cinquième,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Ammiel, le sixième, Issaschar, le septième, Pehultaï, le huitième, car Dieu l\'avait béni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Et à Semaïa, son fils, naquirent aussi des fils, princes dans la maison de leur père car c\'étaient des hommes vaillants;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'fils de Semaïa: Othni et Rephaël et Obed, Edom, son frère, hommes vaillants, Elihu et Semachia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Tous ils étaient fils d\'Obd-Edom; eux et leurs fils et frères étaient des hommes énergiques pour le service, soixante-deux issus d\'Obed-Edom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Et les fils et frères de Méselmia, hommes vaillants, étaient au nombre de dix-huit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Et les fils de Hosa, des fils de Merari: Simri le chef (non qu\'il fût le premier-né, mais son père l\'avait fait chef),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Hilkia, le second, Tebalia, le troisième, Zacharie, le quatrième; tous les fils et frères de Hosa étaient au nombre de treize.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'A ces classes de portiers, c\'est-à-dire, aux chefs de ces hommes échut conjointement avec leurs frères la garde de service dans le Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Et ils tirèrent au sort, petits et grands, selon leurs maisons patriarcales, chacune des portes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Et le côté du Levant échut a Sélémia; et pour Zacharie, son fils, prudent conseiller, ils tirèrent aussi au sort, et il eut pour lot le Septentrion,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'le Midi fut pour Obed-Edom et pour ses fils, près des magasins,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'pour Suppim et Hosa le Couchant, à la porte Sallécheth, où la voie monte, une garde étant à l\'opposite de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'L\'Orient était gardé par six Lévites, le Nord journellement par quatre, le Midi journellement par quatre et les magasins par deux alternativement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'au portique ouvert du couchant quatre sur la rue, deux près du portique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Telles sont les classes des portiers pris dans les fils des Coraïtes et dans les fils des Merarites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Et parmi les Lévites, Ahia était préposé sur les trésors de la Maison de Dieu et sur les trésors des objets consacrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Les fils de Laëdan, des fils des Gersonites de Laëdan, patriarches [de la race de] Laëdan, le Gersonite Jehièli;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'les fils de Jehièli, Zétham et Joël, son frère, étaient préposés sur les trésors du Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Des Amramites, des Jitseharites, des Hébronites, des Azzièlites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Et Sebuel, fils de Gersom, fils de Moïse, était surintendant des trésors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Et ses frères par Éliézer: lequel eut pour fils Rehabia, dont le fils fut Ésaïe qui eut pour fils Joram, dont le fils fut Sichri qui eut pour fils Salomith:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'ce Salomith et ses frères avaient l\'intendance de tous les trésors des objets consacrés qu\'avaient consacrés le roi David et les patriarches, les chefs de mille et de cent et les généraux de l\'armée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'c\'est à la suite des guerres et sur le butin qu\'ils les avaient consacrés comme réserve pour le Temple de l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'et tout ce qui avait été consacré par Samuel, le Voyant, et par Saül, fils de Kis, et par Abner, fils de Ner, et par Joab, fils de Tseruïa, tous les objets consacrés étaient commis à Salomith et ses frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Parmi les Jitseharites Chenania et ses fils étaient pour les affaires extérieures, préposés sur Israël comme Secrétaires et Juges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Parmi les Hébronites Hasabia et ses frères, hommes de ressource, au nombre de mille sept cents, avaient l\'intendance d\'Israël en deçà du Jourdain au couchant pour toutes les affaires de l\'Éternel et le service du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Parmi les Hébronites était Jeria le chef des Hébronites selon leurs familles et maisons patriarcales. (Dans la quarantième année du règne de David recherche en fut faite, et il se trouva parmi eux de vaillants héros à Jaëzer en Galaad).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'Et ses frères, hommes de ressource, étaient au nombre de deux mille sept cents, patriarches. Et le roi David les préposa sur les Rubénites et les Gadites et la demi-Tribu de Manassé pour toutes les affaires de Dieu et les affaires du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Suivent les enfants d\'Israël selon leur nombre, patriarches et chefs de mille et de cent et leurs officiers au service du roi, selon tout le mode de classement de ceux qui relevaient et de ceux qui étaient relevés, mois par mois de tous les mois de l\'année, chaque division de vingt-quatre mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'La première division du premier mois était sous Jasobeam, fils de Zabdiel, et sa division était de vingt-quatre mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Il était des fils de Pérets, chef de tous les capitaines de service du premier mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Et la division du second mois était sous Dodaï, l\'Ahohïte, et dans sa division Micloth était officier [sous lui], et sa division était de vingt-quatre mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Le général de la troisième division du troisième mois était Benaïa, fils du Prêtre Joïada, chef; et sa division était de vingt-quatre mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Ce Benaïa était un héros entre les Trente et préposé aux Trente, et sa division était [commandée] par Ammizabad, son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Le quatrième du quatrième mois était Asahel, frère de Joab, et Zebadia, son fils, après lui, et sa division était de vingt-quatre mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Le cinquième du cinquième mois, le général était Samehuth, le Jizrahite, et sa division était de vingt-quatre mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Le sixième du sixième mois était Ira, fils de Ikkès, de Thékôa, et sa division était de vingt-quatre mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Le septième du septième mois était Hélets, le Pelonite, des fils d\'Ephraïm, et sa division était de vingt-quatre mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Le huitième du huitième mois était Sibchaï, de Husa, des Zarehites, et sa division était de vingt-quatre mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Le neuvième du neuvième mois était Abiézer, d\'Anathoth, des Benjaminites, et sa division était de vingt-quatre mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Le dixième du dixième mois était Maharaï, de Netophah, des Zarehites, et sa division était de vingt-quatre mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Le onzième du onzième mois était Benaïa, de Pirathon, des fils d\'Éphraïm, et sa division était de vingt-quatre mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Le douzième du douzième mois était Heldaï, de Netophah, de [la souche de] Othniel, et sa division était de vingt-quatre mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Et à la tête des Tribus d\'Israël étaient: à la tête des Rubénites, le prince Éliézer, fils de Zichri; des Siméonites, Sephatia, fils de Maacha;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'des Lévites, Hasabia, fils de Kemuel; de la souche d\'Aaron, Tsadoc;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'de Juda, Elihu, des frères de David; d\'Issaschar, Omri, fils de Michaël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'de Zabulon, Jismaïa, fils de Obadia; de Nephthali, Jerimoth, fils d\'Azriel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'des fils d\'Éphraïm, Hosée, fils de Azazia;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'de la demi-Tribu de Manassé, Joël, fils de Pedaïa; de la demi-Tribu de Manassé en Galaad, Iddo, fils de Zacharie; de Benjamin, Jaësiel, fils d\'Abner;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'de Dan, Azareël, fils de Jeroham. Tels sont les princes des Tribus d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Et David n\'admit pas dans le relevé de leur nombre ceux de vingt ans et au-dessous, car l\'Éternel avait promis de multiplier les Israélites comme les étoiles du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joab, fils de Tséruïa, commença le recensement, mais ne l\'acheva pas; et cette mesure attira sur Israël la colère [de l\'Éternel], et le nombre ne fut pas consigné dans le calcul des Annales du roi David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Et sur les trésors du roi était préposé Azmaveth, fils de Adiel, et sur les approvisionnements dans les campagnes, les villes, les villages et les tours, Jonathan, fils de Uzzia;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'et sur les agriculteurs pour la culture du sol, Ezri, fils de Chelub;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'et sur les vignes, Siméï, de Rama, et sur les provisions de vin dans les vignes, Zabdi, de Séphem;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'et sur les olivaies et les sycomores dans le pays-bas, Baal-Hanan, de Gader; et sur les provisions d\'huile, Joas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'et sur le gros bétail paissant en Saron, Sitraï, de Saron; et sur le bétail des vallées, Saphat, fils d\'Adlaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'et sur les chameaux, Obil, l\'Ismaélite, et sur les ânesses, Jèhedia de Meronath;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'et sur le menu bétail, Jaziz, l\'Hagarite. Tous ceux-là étaient intendants des biens du roi David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Et Jonathan, oncle de David, était conseiller, homme intelligent et instruit, et Jehiel, fils de Hachmoni, était auprès des fils du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Et Achitophel était conseiller du roi, et Husaï, d\'Érech, ami du roi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'à la suite d\'Achitophel étaient Joïada, fils de Benaïa, et Abiathar; et le roi avait pour général d\'armée Joab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Et David assembla tous les chefs d\'Israël, les chefs des Tribus et les chefs des Classes, qui étaient au service du roi, et les chefs des milliers et les chefs des centaines et les chefs qui avaient l\'intendance de toutes les propriétés et des troupeaux du roi et qui étaient auprès de ses fils, ainsi que les eunuques et les héros et tous les hommes vaillants, à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Et le roi David debout sur ses pieds dit: Écoutez-moi, mes frères et mon peuple! J\'avais l\'intention de bâtir une maison de repos pour l\'Arche d\'Alliance de l\'Éternel et le marchepied de notre Dieu, et je m\'apprêtais à bâtir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'lorsque Dieu me dit: Tu n\'élèveras pas de Temple à Mon Nom, parce que tu es un homme de guerre et que tu as fait couler du sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Et l\'Éternel, Dieu d\'Israël, m\'a choisi dans toute la maison de mon père pour être roi d\'Israël à jamais; car c\'est Juda qu\'il a choisi pour prince, et dans la maison de Juda la maison de mon père, et entre les fils de mon père c\'est moi qu\'il a daigné faire roi de tout Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'et entre tous mes fils (car l\'Éternel m\'a accordé beaucoup de fils). Il a fait choix de mon fils, Salomon, pour s\'asseoir sur le trône royal de l\'Éternel au-dessus d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Et Il m\'a dit: C\'est Salomon, ton fils, qui édifiera mon Temple et mes parvis; car je me le suis choisi pour fils et veux être pour lui un père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Et je consoliderai sa royauté pour l\'éternité, s\'il tient ferme à l\'exécution de mes commandements et de mes arrêts, comme aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Et maintenant devant les yeux de tout Israël, Assemblée de l\'Éternel, et aux oreilles de notre Dieu [je vous adresse cette sommation]: Gardez et étudiez tous les commandements de l\'Éternel, votre Dieu, afin de rester possesseurs de l\'excellent pays, et de le transmettre à vos fils après vous éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Et toi, mon fils, Salomon, connais le Dieu de ton père et Le sers d\'un cœur non partagé et par inclination d\'âme, car l\'Éternel sonde tous les cœurs et pénètre toute formation de pensées. Si tu Le cherches, Il se laissera trouver par toi, mais si tu L\'abandonnes, Il te réprouvera pour toujours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Avise donc, puisque l\'Éternel t\'a choisi pour élever un édifice qui soit un Sanctuaire; courage! et exécute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Et David donna à Salomon, son fils, le plan du vestibule et de ses constructions et de ses trésors et de ses chambres hautes et de ses chambres intérieures, et de l\'édifice du propitiatoire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'le plan de tout ce qu\'il avait dans l\'esprit pour les parvis du Temple de l\'Éternel, et toutes les cellules du pourtour et les trésors de la maison de Dieu');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'et les trésors des objets consacrés pour les classes des Prêtres et des Lévites et tout le détail du service dans la maison de l\'Éternel, et tous les ustensiles du service dans la maison de l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'pour les ustensiles d\'or, avec le poids pour ce qui serait d\'or, pour tous les ustensiles des divers services, et pour tous les ustensiles d\'argent, avec le poids pour tous les ustensiles des divers services,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'et pour le poids des candélabres d\'or et de leurs lampes d\'or avec le poids de chaque candélabre et de ses lampes, et pour les candélabres d\'argent avec le poids de chaque candélabre et de ses lampes, selon l\'usage de chaque candélabre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'et pour l\'or, avec le poids, pour les tables de pains de présentation, pour chaque table, et pour l\'argent des tables d\'argent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'et pour les fourchettes et les patères et les fioles d\'or pur, et pour les coupes d\'or avec le poids pour les diverses coupes, et pour les coupes d\'argent avec le poids de chaque coupe,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'et pour l\'autel aux parfums d\'or purifié, avec le poids, et pour le plan du char, des chérubins d\'or, de leurs ailes déployées couvrant l\'Arche d\'Alliance de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, '« Tout cela est mis par écrit de par l\'Éternel qui m\'a instruit de tout le détail du plan. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Et David dit à Salomon, son fils: Courage et fermeté! et exécute sans crainte ni peur, car l\'Éternel, Dieu, mon Dieu, est avec toi. Il ne te fera pas défaut et ne te délaissera pas jusqu\'à l\'achèvement de tout ce qui est a faire pour le service de la maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Et tu as ici les classes des Prêtres et des Lévites pour la totalité du service de la maison de Dieu, et pour toute l\'œuvre, l\'aide de tout autant d\'hommes distingués par leur habileté à tout travail, et des chefs et de tout le peuple pour toutes tes affaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Et le roi David dit à toute l\'Assemblée: Mon fils Salomon, le seul que Dieu ait choisi, est enfant et dans l\'âge tendre, et l\'entreprise est grande, car il ne s\'agit pas du palais d\'un homme, mais de celui de l\'Éternel Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Usant de tous mes moyens j\'ai amassé en vue du Temple de mon Dieu de l\'or pour ce qui sera d\'or, de l\'argent pour ce qui sera d\'argent, de l\'airain pour ce qui sera d\'airain, du fer pour ce qui sera de fer, et du bois pour ce qui sera de bois, des pierres d\'onyx et des gemmes enchâssées, des pierres à coloris et jaspées et toutes sortes de pierres précieuses, et des quartiers de marbre en masse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'de plus, comme je prends mon plaisir à la Maison de mon Dieu, je veux dédier l\'or et l\'argent que je possède, à la Maison de mon Dieu en sus de tout ce que j\'ai amassé en vue de l\'édifice sacré:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'trois mille talents d\'or, d\'or d\'Ophir, et sept mille talents d\'argent purifié, pour en revêtir les parois des bâtiments,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'l\'or pour ce qui sera d\'or, et l\'argent pour ce qui sera d\'argent, et pour tous les ouvrages d\'art. Et aujourd\'hui qui veut venir spontanément, les mains pleines, à l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Et vinrent spontanément les chefs des maisons patriarcales et les chefs des Tribus d\'Israël et les chefs des milliers et des centaines et les intendants du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Et ils donnèrent pour les ouvrages du Temple de Dieu, en or cinq mille talents et dix mille dariques, et en argent dix mille talents, et en airain dix-huit mille talents, et en fer cent mille talents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Et ceux chez qui se trouvaient des pierreries, les remirent pour le trésor du Temple de l\'Éternel entre les mains de Jehiel, le Gersonite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Et le peuple se réjouit de leurs dons spontanés, parce qu\'ils les offraient de plein cœur à l\'Éternel, et le roi David aussi était pénétré d\'une grande joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Et David bénit l\'Éternel à la vue de toute l\'Assemblée, et David dit: Sois béni, Éternel, Dieu d\'Israël, notre Père, de l\'éternité à l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'A toi Éternel, la majesté et la puissance et la magnificence et la perpétuité et la splendeur, oui, tout dans les cieux et sur la terre; à toi, Éternel, est l\'empire, et tu domines tout comme Souverain;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'richesse et honneur émanent de toi, et tu règnes sur toutes choses, et ta main est force et vertu, et c\'est dans ta main qu\'est le pouvoir de tout agrandir et de tout consolider.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Maintenant donc, ô notre Dieu, nous te rendons grâces et célébrons ton Nom magnifique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Car que suis-je et qu\'est mon peuple pour être à même de faire de tels dons? Car tout vient de toi, et c\'est de ta main que sortent les dons que nous t\'offrons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Devant toi nous sommes des hôtes et des passagers ainsi que tous nos pères; car nos jours sont comme l\'ombre sur la terre, et il n\'y a point d\'arrêt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Éternel, notre Dieu, tout cet appareil que nous avons préparé en vue de t\'élever un temple pour ton saint Nom, vient de ta main, et tout est à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Et je sais, ô mon Dieu, que tu sondes le cœur et aimes la droiture. C\'est dans la droiture de mon cœur que j\'ai fait tous ces dons spontanés, et maintenant ton peuple ici présent, je l\'ai vu avec joie t\'offrir ses dons volontaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Éternel, Dieu d\'Abraham, d\'Isaac et d\'Israël, nos pères, conserve à jamais dans le cœur de ce peuple cette volonté et ces pensées et dirige leurs cœurs vers toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Et à mon fils Salomon donne un cœur tout entier à l\'observation de tes commandements et de tes ordonnances et de tes statuts et à la pratique de toutes choses et à l\'édification du palais dont j\'ai fait les apprêts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Et David dit à toute l\'Assemblée: Allons! bénissez l\'Éternel, votre Dieu. Et toute l\'Assemblée bénit l\'Éternel, Dieu de leurs pères, et s\'inclina et se prosterna devant l\'Éternel et devant le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Et ils sacrifièrent à l\'Éternel des victimes et offrirent des holocaustes à l\'Éternel le lendemain de cette journée, mille taureaux, mille béliers, mille brebis avec leurs libations, et d\'autres sacrifices en quantité pour tout Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Et ils mangèrent et burent devant l\'Éternel en ce jour avec grande allégresse, et pour la seconde fois ils firent roi Salomon, fils de David, et l\'oignirent comme Prince de l\'Éternel, et Tsadoc comme Prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Et Salomon s\'assit sur le trône de l\'Éternel comme roi, en la place de David, son père, et il fut heureux et tout Israël lui obéit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Et tous les chefs et les héros et aussi tous les fils du roi David se soumirent à Salomon roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Et l\'Éternel rendit Salomon éminemment grand aux yeux de tous les Israélites et lui donna une magnificence royale, comme ne l\'avait eue aucun de ceux qui avaient régné avant lui sur Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Or David, fils d\'Isaï, régna sur la totalité d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Et la durée de son règne sur Israël fut de quarante années; à Hébron il régna sept ans et à Jérusalem il en régna trente-trois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Et il mourut dans une belle vieillesse, comblé d\'années, de richesse et de gloire, et Salomon, son fils, fut roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Les actes du roi David, les premiers et les derniers, sont d\'ailleurs consignés dans les histoires de Samuel, le Voyant, et dans les histoires de Nathan, le prophète, et dans les histoires de Gad, le contemplateur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'avec tout son règne et ses exploits et les époques qui passèrent sur lui et sur Israël et sur tous les royaumes du monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Et Salomon, fils de David, s\'affermit dans sa royauté, et l\'Éternel, son Dieu, était avec lui et l\'agrandissait éminemment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Et Salomon dit à tout Israël, [c\'est-à-dire] aux chefs des milliers et des centaines et aux Juges et à tous les Princes dans tout Israël, aux patriarches,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'qu\'on eût à se rendre, Salomon et toute l\'Assemblée avec lui, à la hauteur de Gabaon; car là était la Tente du Rendez-vous de Dieu, qu\'avait faite Moïse, serviteur de l\'Éternel, dans le désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Cependant David avait transféré l\'Arche de Dieu de Kiriath-Jearim à la place que David avait disposée pour elle, car il lui érigea une tente à Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'mais l\'autel d\'airain, ouvrage de Betsaléèl, fils de Uri, fils de Hur, il l\'avait placé devant la Résidence de l\'Éternel, et Salomon et l\'Assemblée le fréquentaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Et Salomon y sacrifia sur l\'autel d\'airain de l\'Éternel, qui se trouvait devant la Tente du Rendez-vous, et il offrit sur cet autel mille holocaustes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Dans la nuit même Dieu apparut à Salomon et lui dit: Demande ce que j\'ai à te donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Et Salomon dit à Dieu: Tu as fait à David, mon père, une grande faveur, et tu m\'as fait roi en sa place:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'maintenant, Éternel, Dieu, qu\'elle se justifie ta promesse à David, mon père! Tu m\'as constitué roi d\'un peuple nombreux comme la poudre de la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'donne-moi donc sagesse et science, afin que je puisse marcher et rentrer à la tête de ce peuple; car qui est-ce qui saurait gouverner ton peuple, ce grand peuple?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Et Dieu dit à Salomon: Puisque c\'est cela qui est dans ton cœur, et que tu n\'as demandé ni richesse, ni trésors, ni gloire, ni la mort de tes ennemis, et que tu n\'as pas même demandé de longs jours, mais que tu as demandé pour toi sagesse et science pour gouverner mon peuple dont je t\'ai fait roi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'sagesse et science te sont données, et je t\'accorderai richesse et trésors et gloire, comme n\'en eurent jamais les rois, tes prédécesseurs, et comme n\'en aura aucun de tes successeurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Et de la hauteur de Gabaon Salomon revint à Jérusalem ayant quitté la Tente du Rendez-vous, et il régna sur Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Et Salomon rassembla des chars et de la cavalerie, et il avait mille et quatre cents chars et douze mille cavaliers, dont il établit le dépôt dans les villes des chars et auprès du roi à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Et le roi rendit l\'argent et l\'or, à Jérusalem, aussi communs que les pierres, et les cèdres égaux en nombre aux sycomores qui croissent dans le pays-bas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Et l\'on tirait de l\'Egypte les chevaux pour Salomon, et c\'était à Thékôa que les marchands du roi allaient recevoir un convoi contre payement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Et l\'on amenait et tirait de l\'Egypte un char pour six cents sicles d\'argent, et un cheval pour cent cinquante, et de la même manière on en exportait par leur entremise pour tous les rois des Héthiens et les rois de Syrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Et Salomon pensait à élever un temple au Nom de l\'Éternel et un palais pour sa demeure royale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Alors Salomon fixa un nombre de soixante-dix mille portefaix et de quatre-vingt mille tailleurs de pierre dans la montagne et trois mille six cents préposés pour les conduire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Et Salomon députa vers Huram, roi de Tyr, pour lui dire: [Fais pour moi] comme tu as fait pour David, mon père, en lui envoyant des cèdres pour se bâtir un palais pour sa demeure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Voici, j\'élève un temple au Nom de l\'Éternel, mon Dieu, pour le Lui consacrer, pour brûler devant lui l\'encens odorant et lui offrir les pains de présentation à l\'ordinaire, et les holocaustes du matin et du soir aux Sabbats, aux Nouvelles-Lunes, et aux Fêtes de l\'Éternel, notre Dieu: c\'est à perpétuité un devoir pour Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Et l\'édifice que je veux construire sera grand; car notre Dieu est plus grand que tous les dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Mais qui sera de force à lui élever un temple? car les Cieux et les Cieux des Cieux ne peuvent Le contenir; et qui suis-je pour lui élever un temple? ce n\'est que pour faire fumer l\'encens devant lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Envoie-moi donc un homme habile à travailler en or et en argent et en airain et en fer et en pourpre rouge et cramoisi et pourpre d\'azur, et sachant sculpter des sculptures, pour se joindre aux hommes habiles que j\'ai à ma portée en Juda et à Jérusalem et qu\'a préparés David, mon père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Et envoie-moi des bois de cèdre, de cyprès et de santal, du Liban; car je sais que tes serviteurs s\'entendent à couper le bois au Liban, et voici, mes serviteurs se joindront à tes serviteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Et je dois me procurer du bois en masse, car le temple que je vais élever doit être grand et merveilleux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Et voici, pour les bûcherons qui couperont le bois je donnerai à tes serviteurs du froment égrené, vingt mille cors, et de l\'orge, vingt mille cors, et du vin, vingt mille baths, et de l\'huile, vingt mille baths.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Et Huram, roi de Tyr, répondit par écrit, mandant à Salomon: « C\'est par amour pour son peuple que l\'Éternel t\'en a fait roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Et Huram disait: Béni soit l\'Éternel, Dieu d\'Israël, qui a fait les Cieux et la terre, de ce qu\'il a donné au roi David un fils sage et prudent et intelligent qui veut élever un temple à l\'Éternel et un palais pour sa demeure royale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Je t\'envoie donc un homme habile et doué d\'intelligence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'savoir Huram-Abi, fils d\'une femme d\'entre les filles de Dan, tandis que son père était un Tyrien, habile ouvrier en or et en argent, en airain, en fer, en pierre et en bois, en pourpre rouge, en pourpre d\'azur et en byssus et en cramoisi et sachant sculpter toutes sortes de sculptures, et imaginer toutes les sortes d\'ouvrages d\'art qui lui sont proposés, avec le concours de tes hommes entendus et des hommes entendus de mon Seigneur David, ton père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Et quant au froment et à l\'orge, à l\'huile et au vin, dont mon Seigneur a parlé, qu\'il veuille l\'envoyer à ses serviteurs:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'de notre côté nous couperons du bois au Liban selon tous tes besoins, et nous te l\'amènerons en radeaux par mer à Joppe; d\'où tu pourras le faire conduire à Jérusalem. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Et Salomon dénombra tous les étrangers qui étaient au pays d\'Israël, d\'après le dénombrement qu\'avait fait d\'eux David, son père, et il s\'en trouva cent cinquante-trois mille six cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'Et il en fit soixante-dix mille portefaix, et quatre-vingt mille tailleurs de pierre dans la montagne, et trois mille six cents préposés pour tenir ce monde assujetti.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Et Salomon commença à construire le Temple de l\'Éternel à Jérusalem sur le mont de Moriia qui avait été indiqué à David, son père, au lieu que David avait disposé sur l\'aire d\'Ornan, le Jébusite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Et il commença la construction au second mois, le second [jour], la quatrième année de son règne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Et voici la base que Salomon fixa pour la construction de la Maison de Dieu: la longueur, en coudées ancienne mesure, soixante coudées, et la largeur, vingt coudées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'et le vestibule dont la longueur occupait la largeur de la façade de l\'édifice, vingt coudées, et la hauteur cent vingt, et il le revêtit intérieurement d\'or pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Et il revêtit le grand bâtiment de bois de cyprès, et le revêtit de bel or et d\'un parement de palmiers et de chaînettes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Et il recouvrit l\'édifice de pierres précieuses comme ornement, et l\'or était or de Parvaïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Et il revêtit d\'or l\'édifice, les solives, les seuils et ses parois et battants de porte, et cisela des Chérubins aux parois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Et il fit le bâtiment du Lieu Très-Saint, sa longueur égale à la largeur de l\'édifice, étant de vingt coudées, et sa largeur de vingt coudées, et le revêtit de bel or qui se montait à six cents talents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Et le poids pour les clous était de cinquante sicles d\'or. Et il revêtit aussi d\'or les chambres supérieures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Et il fit dans le Lieu Très-Saint deux Chérubins en travail de sculpture, et on les recouvrit d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Quant aux ailes des Chérubins, leur longueur était de vingt coudées; l\'aile de l\'un, longue de cinq coudées, touchait à la paroi de l\'édifice, et l\'autre aile, longue de cinq coudées, touchait à l\'aile de l\'autre Chérubin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'et l\'aile de l\'autre Chérubin, longue de cinq coudées, touchait à la paroi de l\'édifice, et l\'autre aile, longue de cinq coudées, joignait l\'aile de l\'autre Chérubin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'les ailes de ces Chérubins, déployées, avaient vingt coudées de longueur, et ils étaient debout sur leurs pieds et leurs visages regardaient l\'édifice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Et il fit le voile de pourpre azuré et rouge et de cramoisi et de byssus et y adapta des Chérubins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Et il fit devant l\'édifice deux colonnes ayant trente-cinq coudées de hauteur, et le parement de leur faîte avait cinq coudées [de longueur].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Et il fit des chaînettes dans le Sanctuaire et en mit aux faîtes des colonnes et fit cent grenades qu\'il ajusta aux chaînettes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Et il dressa les colonnes à la façade du Temple, une à droite et une à gauche, et donna à celle de droite le nom de Jachin et à celle de gauche le nom de Boaz.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Et il fit un autel d\'airain long de vingt coudées, large de vingt coudées, et haut de dix coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Et il fit la Mer, en fonte, ayant dix coudées de l\'un de ses bords à l\'autre, ronde dans son contour et haute de cinq coudées, et un cordon de trente coudées l\'embrassait tout à l\'entour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Et des figures de coloquintes étaient en dessous à l\'entour, l\'embrassant dans sa Circonférence à raison de dix par coudée, ceignant la Mer dans sa circonférence; il y avait deux rangées de coloquintes coulées d\'une même fonte avec elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Elle reposait sur douze taureaux regardant, trois le septentrion, et trois l\'occident, et trois le midi, et trois l\'orient, et toutes leurs croupes étaient tournées en dedans, et la mer posait dessus en hauteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Et son épaisseur était d\'une palme, et son rebord comme le travail du rebord d\'une coupe, en fleur de lis, et quant à sa capacité en baths, elle en pouvait contenir trois mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Et il fit dix bassins, dont il plaça cinq à droite et cinq à gauche, pour y laver; on y rinçait la batterie de l\'holocauste, et la Mer servait à l\'ablution des Prêtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Et il fit les candélabres d\'or, selon leur façon, et les plaça dans le Temple, cinq à droite et cinq à gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Et il fit dix tables qu\'il déposa dans le temple, cinq à droite et cinq à gauche; et il fit cent jattes d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Et il fit le Parvis des Prêtres, et le grand Parvis et des portes au grand Parvis, et il en revêtit d\'airain les battants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Et il plaça la Mer au côté droit de l\'édifice, à l\'orient vers le midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Et Huram fit les pots, les pelles et les jattes; et Huram termina le travail qu\'il faisait pour le roi Salomon dans la Maison de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'deux colonnes et les globes et les chapiteaux sur le faîte des deux colonnes et les deux treillis recouvrant les deux globes des chapiteaux sur le faîte des colonnes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'et les quatre cents grenades des deux treillis, deux rangées de grenades par treillis pour couvrir les deux globes des chapiteaux aux colonnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'et il fit les piédestaux et fit les bassins posant sur les piédestaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'la Mer, unique, et les douze taureaux qui étaient dessous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'et les pots et les pelles et les fourchettes et tous les ustensiles assortis, Huram-Abiv les fit pour le roi Salomon dans le Temple de l\'Éternel, en airain poli.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'C\'est dans le Cercle du Jourdain que le roi les fit couler dans une terre glaise entre Succoth et Tserédatha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Et Salomon fit tous ces ustensiles en grande quantité; car on ne s\'enquit point du poids de l\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Et Salomon fit tous les meubles qui étaient dans la Maison de Dieu, savoir, l\'autel d\'or et les tables sur lesquelles étaient les pains de présentation,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'et les candélabres et leurs lampes d\'or pur pour brûler selon le rite devant le Sanctuaire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'et les fleurs et les lampes et les pinces d\'or, tout d\'or pur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'et les couteaux et les jattes et les coupes et les bouilloires d\'or fin, et à la porte du Temple ses battants, intérieurs, du Lieu Très-Saint, et les battants des portes de l\'édifice, du Temple, d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Et ainsi fut terminé tout l\'ouvrage exécuté par Salomon pour le Temple de l\'Éternel, et Salomon introduisit ce que David, son père, avait consacré; et l\'argent et l\'or et tout le mobilier, il le mit dans le Trésor de la Maison de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Alors Salomon assembla les Anciens d\'Israël et tous les chefs des Tribus, les princes des maisons patriarcales des enfants d\'Israël, à Jérusalem pour transférer l\'Arche d\'Alliance de l\'Éternel de la Cité de David, c\'est-à-dire, de Sion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Et auprès du roi s\'assemblèrent tous les hommes d\'Israël à la Fête (c\'était le septième mois).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Et vinrent tous les Anciens d\'Israël, et les Lévites portèrent l\'Arche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Et ils apportèrent l\'Arche et la Tente du Rendez-vous et tout le mobilier sacré qui était dans la Tente, ces objets furent apportés par les Prêtres, les Lévites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Et le roi Salomon et toute l\'Assemblée d\'Israël qui s\'était réunie auprès de lui, devant l\'Arche sacrifièrent des brebis et des bœufs qui ne pouvaient se nombrer, ni se compter, tant il y en avait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Et les Prêtres introduisirent l\'Arche d\'Alliance de l\'Éternel à sa place, dans le Sanctuaire de l\'édifice, dans le Lieu Très-Saint au-dessous des ailes des Chérubins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Et les Chérubins avaient les ailes étendues sur l\'emplacement de l\'Arche, et les Chérubins couvraient l\'Arche et ses barres d\'en haut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Et les barres étaient assez longues pour que de l\'Arche devant le Sanctuaire on pût en voir les extrémités, mais du dehors on ne les apercevait pas, et elle y a été jusqu\'à ce jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Il n\'y avait rien dans l\'Arche que les deux Tables qu\'y avait mises Moïse en Horeb, quand l\'Éternel fit alliance avec les enfants d\'Israël à leur sortie de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Et lorsque les Prêtres sortirent du Lieu-Saint, (car tous les Prêtres présents s\'étaient mis en état de sainteté, sans égard à la distinction des classes)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'et lorsque les Lévites, les Chantres, eux tous, savoir Asaph, Heiman et Jeduthun, et leurs fils et leurs frères, vêtus de byssus et munis de cymbales, de harpes et de luths furent debout, au côté oriental de l\'autel accompagnés de cent vingt Prêtres sonnant des trompettes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'et lorsque, comme un seul homme, les trompettes et les chantres entonnèrent tout d\'une voix la louange de l\'Éternel et l\'action de grâces à l\'Éternel, et lorsqu\'ils poussèrent leur voix au bruit des trompettes et des cymbales et des instruments à cordes et louant l\'Éternel de ce qu\'il est bon et sa miséricorde éternelle, alors l\'édifice, le temple de l\'Éternel se remplit d\'une nuée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'et les Prêtres ne pouvaient y tenir pour faire leur service, par l\'effet de la nuée, caria gloire de l\'Éternel avait rempli la Maison de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Alors Salomon dit: L\'Éternel a résolu d\'habiter dans l\'obscurité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Et moi, je T\'ai élevé une Maison pour demeure et un lieu fixe pour ta résidence à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Et le roi tourna son visage et bénit toute l\'Assemblée d\'Israël, et toute l\'Assemblée était debout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Et il dit: Béni soit l\'Éternel, Dieu d\'Israël, qui de sa bouche a parlé à David, mon père, et qui de sa main accomplit ce qu\'il a dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Depuis le jour où j\'ai retiré mon peuple du pays d\'Egypte, je n\'avais point choisi de ville dans aucune des Tribus d\'Israël pour y construire une Maison où mon Nom habitât, ni n\'ai choisi d\'homme pour être prince de mon peuple d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'mais j\'ai choisi Jérusalem pour que mon Nom y fût, et choisi David pour qu\'il régnât sur mon peuple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Et David, mon père, avait la pensée d\'élever un temple au Nom de l\'Éternel, Dieu d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'mais l\'Éternel dit à David, mon père: En ayant la pensée d\'élever un temple à mon Nom, tu as bien fait d\'en avoir la pensée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'seulement ce n\'est pas toi qui construiras le temple, mais ton fils sorti de tes entrailles, c\'est lui qui élèvera le temple à Mon Nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Et l\'Éternel a mis à effet sa parole, qu\'il avait prononcée, et j\'ai succédé à David, mon père, et me suis assis sur le trône d\'Israël, ainsi qu\'a dit l\'Éternel, et ai élevé le temple au Nom de l\'Éternel, Dieu d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'et j\'y ai placé l\'Arche où est l\'alliance de l\'Éternel, qu\'il a conclue avec les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Et Salomon s\'avança devant l\'autel de l\'Éternel en face de toute l\'Assemblée d\'Israël et il étendit ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Car Salomon s\'était fait une tribune d\'airain et l\'avait placée au centre du parvis; elle avait cinq coudées de longueur et cinq coudées de largeur et trois coudées de hauteur; et il s\'y plaça et s\'agenouilla en face de toute l\'Assemblée d\'Israël, et il étendit ses mains vers le ciel et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'Éternel, Dieu d\'Israël, il n\'est au ciel et sur la terre point de Dieu pareil à toi gardant alliance et grâce à tes serviteurs marchant devant toi de tout leur cœur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'toi qui as tenu à ton serviteur David, mon père, ce que tu lui as promis; de ta bouche tu parlais, et de ta main tu as accompli ce qu\'on voit aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Et maintenant, Éternel, Dieu d\'Israël, tiens à ton serviteur, David, mon père, ce que tu lui as promis, en disant: Tu ne manqueras jamais d\'un homme devant moi pour occuper le trône d\'Israël, pourvu que tes fils prennent garde à leurs voies pour suivre ma loi, comme tu l\'as suivie devant moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'et maintenant, Éternel, Dieu d\'Israël, qu\'elle se justifie ta promesse que tu as faite à ton serviteur, à David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Quoi! Vraiment Dieu habiterait-Il avec l\'homme sur la terre! Voici, les Cieux et les Cieux des Cieux ne te contiennent pas; combien moins ce temple que j\'ai bâti!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Mais aie égard à la prière de ton serviteur et à sa supplication, Éternel, mon Dieu, pour écouter mon cri et la prière que ton serviteur te présente aujourd\'hui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'afin que tes yeux soient ouverts jour et nuit sur cette maison, sur le lieu dont tu as dit que tu veux y mettre ton Nom, afin d\'exaucer la prière que ton serviteur élèvera vers ce lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Exauce donc la requête que ton serviteur et ton peuple d\'Israël élèveront vers ce lieu; exauce-les du lieu de ta demeure, des Cieux, exauce et pardonne!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Si quelqu\'un pèche contre son prochain et qu\'on lui impose un serment pour l\'assermenter, et que le serment intervienne devant ton autel dans ce temple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'toi, écoute des Cieux et agis et juge tes serviteurs pour payer de retour le coupable et faire retomber sa conduite sur sa tête et pour absoudre l\'innocent et lui rendre selon sa justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Et si ton peuple d\'Israël est battu devant l\'ennemi pour avoir péché contre toi, et s\'ils se convertissent et confessent ton Nom, et te prient et te supplient dans cette Maison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'ô toi, écoute des Cieux et pardonne le péché de ton peuple d\'Israël et ramène-les au pays que tu as donné à eux et à leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Si le ciel se ferme et qu\'il n\'y ait pas de pluie parce qu\'ils ont péché contre toi, et s\'ils élèvent leurs prières vers ce lieu et confessent ton Nom et reviennent de leur péché, parce que tu les humilies,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'ô toi, écoute des Cieux et pardonne le péché de tes serviteurs et de ton peuple d\'Israël, après leur avoir montré la bonne voie où ils doivent marcher, et accorde la pluie à ton pays que tu as donné à ton peuple pour le posséder.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'S\'il y a famine dans le pays, s\'il y a peste, brûlure et nielle, sauterelles et locustes, si ses ennemis le pressent dans le pays de ses Portes, s\'il y a fléau ou maladie quelconque,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'toute prière, toute supplication faite par un individu quelconque ou par la totalité de ton peuple d\'Israël, si chacun a le sentiment de sa plaie et de sa douleur et qu\'ils tendent leurs mains vers ce temple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'ô toi, écoute-la des Cieux, lieu de ta résidence, et pardonne et rends à chacun en raison de toutes ses voies selon la connaissance que tu as de son cœur, car seul tu connais le cœur des enfants de l\'homme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'afin qu\'ils te craignent pour suivre tes voies tout le temps qu\'ils vivront sur la face du sol que tu as donné à nos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Et l\'étranger aussi qui n\'est pas de ton peuple d\'Israël et vient d\'un pays lointain à cause de ton grand Nom et de ta main puissante et de ton bras étendu, et arrive et élève sa prière vers ce temple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'ô toi, écoute-le des Cieux, du lieu de ta résidence, et effectue tout ce pour quoi l\'étranger t\'invoque, afin que tous les peuples de la terre connaissent ton Nom et te révèrent comme ton peuple d\'Israël et sachent que ton Nom est invoqué sur ce temple que j\'ai élevé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Si ton peuple se met en marche pour une guerre contre ses ennemis en suivant la voie où tu l\'engages, et s\'ils te prient en se tournant vers cette cité que tu as choisie et vers ce temple que j\'ai élevé à ton Nom,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'oh! écoute des Cieux leur prière et leur supplication, et fais-leur droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'S\'ils péchent contre toi, (car il n\'est pas un homme qui ne pèche) et si tu t\'irrites contre eux, et les livres à l\'ennemi, et que leurs vainqueurs les emmènent dans un pays lointain ou rapproché,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'et s\'ils rentrent en eux-mêmes dans le pays où ils auront été emmenés captifs, et s\'ils se convertissent, et élèvent vers toi leur prière dans le pays de leur captivité disant: Nous avons péché, nous avons forfait, nous sommes coupables!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'et s\'ils reviennent à toi de tout leur cœur et de toute leur âme dans le pays de leur captivité où on les aura emmenés captifs, et s\'ils te prient en se tournant vers leur pays que tu as donné à leurs pères, et vers la cité que tu as choisie et vers le temple que j\'ai élevé à ton Nom,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'oh! écoute des Cieux, du lieu de ta résidence, leurs prières et leurs supplications et fais-leur droit et pardonne à ton peuple ce qu\'ils auront fait de coupable contre toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Maintenant, ô mon Dieu, que tes yeux soient ouverts et tes oreilles attentives aux prières de ce lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Maintenant, lève-toi, Dieu, Éternel, vers ton lieu de repos, toi et ton Arche glorieuse! Que tes Prêtres, Dieu, Éternel, soient revêtus de salut et que tes saints aient la joie du bonheur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Dieu, Éternel, ne repousse pas ton Oint, aie souvenir des grâces faites à David, ton serviteur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Et lorsque Salomon eut terminé sa prière, le feu descendit du ciel et consuma l\'holocauste et les victimes, et la gloire de l\'Éternel remplit le Temple;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'et les Prêtres ne pouvaient pénétrer dans le Temple de l\'Éternel, car la gloire de l\'Éternel avait rempli le Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Et tous les enfants d\'Israël furent témoins de la descente du feu, de la gloire de l\'Éternel sur le Temple; et ils se prosternèrent la face contre terre sur le pavé et ils adorèrent, et rendirent grâces à l\'Éternel de ce qu\'il est bon, de ce que sa miséricorde est éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Et le roi et tout le peuple sacrifièrent des victimes devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Et le roi Salomon offrit le sacrifice de vingt-deux mille taureaux et de cent vingt mille moutons, et le roi et tout le peuple dédièrent ainsi le Temple de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Et les Prêtres vaquaient à leurs fonctions, ainsi que les Lévites avec les instruments de l\'Éternel, qu\'avait faits le roi David pour rendre grâces à l\'Éternel de ce que sa miséricorde est éternelle, quand David louait [l\'Éternel] par leur organe; et les Prêtres sonnaient de la trompette en face d\'eux, et tous les Israélites assistaient debout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Et Salomon consacra l\'aire du parvis qui est devant le Temple de l\'Éternel, car il y offrit des holocaustes et les graisses des sacrifices pacifiques, parce que l\'autel d\'airain qu\'avait fait Salomon, ne pouvait contenir les holocaustes et les offrandes et les graisses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'C\'est ainsi que Salomon fit la fête en ce temps-là pendant sept jours avec tous les Israélites, immense assemblée convoquée de Hamath au Torrent d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Et ils eurent le huitième jour convocation solennelle; car ils firent la dédicace de l\'autel pendant sept jours, et la fête pendant sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Et le vingt-troisième, jour du septième mois il renvoya le peuple à ses tentes, content et joyeux du bien que l\'Éternel avait fait à David et à Salomon et à Israël, son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'C\'est ainsi que Salomon acheva le Temple de l\'Éternel et le palais royal; et tout ce que Salomon avait eu la pensée d\'exécuter dans le Temple de l\'Éternel et dans son palais, lui réussit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Alors l\'Éternel apparut à Salomon de nuit et lui dit: J\'ai entendu ta prière et choisi pour moi ce lieu-ci comme maison sacrificatoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Dans le cas où je fermerai les Cieux pour qu\'il n\'y ait pas de pluie, et commanderai aux sauterelles de brouter le pays, et enverrai la peste dans mon peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'et si mon peuple qui porte mon Nom s\'humilie et me prie et cherche ma face, et revient de ses mauvaises voies, de mon côté j\'écouterai du ciel et pardonnerai leur péché et restaurerai leur pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Désormais mes yeux seront ouverts et mes oreilles attentives aux prières de ce lieu-ci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'J\'ai donc choisi et sanctifié ce Temple afin que mon Nom y soit éternellement, et mes yeux et ma dilection y seront à perpétuité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Quant à toi, si tu marches devant moi comme a marché David, ton père, et que dans tes actes tu te conformes à tout ce que je t\'ai prescrit, et gardes mes statuts et mes arrêts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'alors je maintiendrai sur pied ton trône royal, ainsi que je m\'y suis engagé envers David, ton père, en ces termes: Tu ne manqueras jamais d\'un homme pour être dominateur d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Mais si vous faites défection et abandonnez mes statuts et mes commandements que j\'ai mis devant vous, et si vous vous en allez servir d\'autres dieux et les adorer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'alors je vous arracherai de mon sol que je vous ai donné, et ce Temple que j\'ai sanctifié pour mon Nom, je le repousserai loin de mes regards, et le ferai passer en proverbe et en sarcasme parmi tous les peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Et ce Temple qui aura été si éminent, quiconque y passera, aura le frisson et dira: Pourquoi l\'Éternel a-t-Il ainsi fait à ce pays et à ce Temple?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Et l\'on dira: Parce qu\'ils ont abandonné l\'Éternel, Dieu de leurs pères, qui les avait retirés du pays d\'Egypte, et qu\'ils se sont attachés à d\'autres dieux et qu\'ils les ont adorés et les ont servis: c\'est pour cela qu\'il a fait fondre sur eux tout ce désastre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Et vingt ans s\'étant écoulés depuis que Salomon eut bâti le Temple de l\'Éternel et son palais,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'il fortifia les villes données par Huram à Salomon, et les peupla d\'enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Et Salomon marcha contre Hamath en Tsoba et s\'en empara.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Et il bâtit Thadmor au Désert et toutes les villes des magasins qu\'il construisit en Hamath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Et il fortifia Bethoron la haute et Bethoron la basse, places fortes, de murs, de portes et de verrous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'et Baalath et toutes les villes à magasins qu\'avait Salomon, et toutes les villes aux chars et les villes à cavalerie et tous les lieux de plaisance qu\'il plut à Salomon de construire à Jérusalem et au Liban et dans tout le pays de sa domination.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Quant à toute la population restée des Héthiens et des Amorites et des Périziens et des Hévites et des Jébusites, qui n\'étaient pas des enfants d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'sur leurs fils qui étaient restés après eux dans le pays, et que les enfants d\'Israël n\'avaient pas détruits, Salomon en fit une levée pour la corvée, comme c\'est aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Mais des enfants d\'Israël Salomon ne fit point de serfs pour ses travaux, car ils étaient les gens de guerre et les chefs de ses triaires et les chefs de ses chars et de sa cavalerie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Et les surintendants du roi Salomon étaient au nombre de deux cent cinquante régissant le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Et Salomon fit monter la fille de Pharaon de la Cité de David au palais qu\'il lui avait bâti, car il disait: Je ne veux pas que femme habite de par moi le palais de David, roi d\'Israël, car sacrés sont les lieux où est entrée l\'Arche de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Alors Salomon offrit des holocaustes à l\'Éternel sur l\'autel de l\'Éternel qu\'il avait érigé devant le vestibule,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'et il offrait l\'ordinaire quotidien selon l\'ordre de Moïse pour les sabbats, les nouvelles lunes et les fêtes, trois fois l\'année, à la fête des azymes, et à la fête des semaines et à la fête des huttes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Et il établit selon la règle de David, son père, les classes des Prêtres pour leur service, et les Lévites dans leurs fonctions pour rendre grâces et officier devant les Prêtres à l\'ordinaire quotidien, et les portiers selon leurs classes à chaque porte, car tel était l\'ordre de David, homme de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Et l\'on ne s\'écarta point de l\'ordonnance du roi pour les Prêtres et les Lévites relativement à chaque point et relativement aux trésors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Et ainsi fut organisée toute l\'œuvre de Salomon jusqu\'au jour de la fondation du Temple de l\'Éternel et jusqu\'à son achèvement, à la complète construction du Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Alors Salomon se rendit à Etsion-Géber et à Eloth sur le bord de la mer au pays d\'Edom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Et Huram lui envoya par ses serviteurs des navires et des serviteurs connaissant la mer, et ils vinrent avec les serviteurs de Salomon à Ophir d\'où ils rapportèrent quatre cent cinquante talents d\'or qu\'ils présentèrent au roi Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Et la reine de Séba entendit le bruit de la renommée de Salomon, et, pour mettre Salomon à l\'épreuve par des énigmes, elle vint à Jérusalem avec une très grande suite, avec des chameaux portant des aromates et de l\'or en quantité et des pierres précieuses; et elle entra chez Salomon et parla avec lui de tout ce qu\'elle avait dans la pensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Et Salomon résolut toutes ses questions, et il n\'y eut pas de question trop abstruse pour Salomon, dont il ne lui donnât la solution.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Et lorsque la reine de Séba vit la sagesse de Salomon et le palais qu\'il avait bâti');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'et le service de sa table, et ses ministres assis et ses serviteurs debout et leur costume, et ses échansons et leur costume, et sa rampe par où on montait au Temple de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'elle était hors d\'haleine, et elle dit au roi: Ils étaient vrais les rapports que j\'ai entendus dans mon pays, sur tes circonstances et sur ta sagesse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'et je n\'ai pas cru à leurs rapports jusqu\'à ce que je suis venue et ai vu de mes yeux, et voilà qu\'on ne m\'a pas raconté la moitié de la grandeur de ta sagesse: tu es au-dessus de ta renommée dont j\'avais entendu le bruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Heureux tes gens et heureux ces tiens serviteurs debout continuellement devant toi et auditeurs de ta sagesse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Béni soit l\'Éternel, ton Dieu, qui a daigné te placer sur son trône comme roi de par l\'Éternel, ton Dieu. C\'est parce que ton Dieu aimait Israël pour le maintenir éternellement, qu\'il t\'en a établi le roi pour faire droit et justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Et elle donna au roi cent vingt talents d\'or et des aromates en très grande quantité et des pierres précieuses; et il n\'y eut pas d\'aromates pareils à ceux que la reine de Séba donna au roi Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, '(Et aussi les serviteurs de Huram, et les serviteurs de Salomon qui apportèrent de l\'or d\'Ophir, présentèrent du bois de santal et des pierres précieuses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Et le roi fit avec le bois de santal des escaliers dans le Temple de l\'Éternel et le palais royal, et des luths et des harpes pour les chantres; et il ne s\'en était auparavant pas vu de pareil dans le pays de Juda.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Et le roi Salomon donna à la reine de Séba tout ce qui lui agréa, qu\'elle lui demanda, hormis ce qu\'elle avait offert au roi. Et elle s\'en retourna et regagna son pays, elle et ses serviteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Et le poids de l\'or qui revenait par année à Salomon était de six cent soixante-six talents d\'or,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'en sus de celui qui venait des trafiquants et que les marchands apportaient; et tous les rois d\'Arabie et les gouverneurs du pays apportaient de For et de l\'argent pour Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Et le roi Salomon fit deux cents boucliers d\'or battu, il étendit sur chaque bouclier six cents sicles d\'or battu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'puis trois cents rondaches d\'or battu, et il étendit sur chaque rondache trois cents sicles d\'or, et le roi les plaça dans le palais de la forêt du Liban.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Et le roi fit un grand trône d\'ivoire et le recouvrit d\'or pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Or le trône avait six marches et un marchepied d\'or adapté au trône, et des accoudoirs de part et d\'autre au siège, et deux lions debout à côté des accoudoirs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'et douze lions étaient debout là sur les six marches des deux côtés; il n\'en avait jamais été fait de pareil dans aucun royaume.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Et tous les vases à boire du roi Salomon étaient d\'or; et tous les meubles du palais de la forêt du Liban étaient d\'or de prix; l\'argent n\'était réputé d\'aucune valeur au temps de Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Car les navires du roi allaient à Tarsis avec les serviteurs de Huram; une fois en trois ans arrivaient les navires de Tarsis avec des cargaisons d\'or et d\'argent, d\'ivoire et de singes et de paons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Et le roi Salomon surpassa tous les rois de la terre en opulence et en sagesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Et tous les rois de la terre recherchaient la présence de Salomon pour recueillir sa sagesse dont Dieu avait doté son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Et ils apportaient chacun son présent, de la vaisselle d\'argent et de la vaisselle d\'or, et des habits, des armes et des aromates, des chevaux et des mulets, année par année.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Et Salomon avait quatre mille râteliers de chevaux et chars et douze mille cavaliers dont il mit le dépôt dans les villes aux chars et près du roi à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Et il avait sous sa domination tous les rois depuis le Fleuve jusqu\'au pays des Philistins et à la frontière d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Et le roi rendit l\'argent à Jérusalem commun comme les pierres, et les cèdres communs comme les sycomores qui croissent dans le pays-bas, tant il y en avait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Et l\'on importait pour Salomon des chevaux de l\'Egypte et de tous les pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Le reste des actes de Salomon, les premiers et les derniers, sont d\'ailleurs consignés dans le livre de Nathan, le prophète, et dans la Prophétie d\'Ahia, le Silonite, et dans les Visions de Jehdo, le Voyant, sur Jéroboam, fils de Nebat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Et Salomon régna à Jérusalem sur tout Israël quarante ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Et Salomon reposa à côté de ses pères et reçut la sépulture dans la Cité de David, son père. Et Roboam, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Et Roboam se rendit à Sichem, car à Sichem étaient venus tous les Israélites pour le faire roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Et à cette nouvelle Jéroboam, fils de Nebat, qui était en Egypte, où il avait fui loin du roi Salomon, revint de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Et par une députation ils le mandèrent, et Jéroboam arriva ainsi que tous les Israélites, et ils tinrent à Roboam ce langage:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Ton père a rendu lourd notre joug, maintenant allège le dur service de ton père et le joug pesant qu\'il nous a imposé, et nous te serons soumis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Et il leur dit: Encore trois jours et revenez me trouver. Et le peuple se retira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Alors le roi Roboam se consulta avec les Anciens qui avaient été les ministres de Salomon, son père, de son vivant, et dit: Comment conseillez-vous de répondre à ce peuple-là?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Et ils lui parlèrent en ces termes: Si tu es bon envers ce peuple, si tu lui es propice et lui parles un langage de bonté, il te sera toujours soumis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Mais il négligea le conseil des Anciens qui le conseillaient, et il se consulta avec les jeunes hommes qui avaient grandi avec lui et étaient ses ministres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Et il leur dit: Que conseillez-vous que nous répondions à ce peuple-là qui m\'a tenu ce langage: Allège le joug que nous a imposé ton père?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Et les jeunes hommes qui avaient grandi avec lui, lui parlèrent en ces termes: Réponds ainsi au peuple qui t\'a tenu ce langage: Ton père a rendu lourd notre joug, mais toi, allège-le-nous! parle-leur ainsi: Mon petit doigt est plus fort que les reins de mon père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'eh bien donc! mon père vous a chargés d\'un joug pesant, et moi j\'ajouterai à votre joug: mon père vous a morigénés avec des étrivières, et moi j\'userai de fouets à pointes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Et lorsque Jéroboam avec tout le peuple se présenta le troisième jour à Roboam, aux termes de ce qu\'avait dit le roi: Revenez me trouver dans trois jours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'le roi leur répondit durement, et le roi Roboam négligea le conseil des Anciens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'Et il leur parla suivant le conseil des jeunes et dit: Mon père a rendu lourd votre joug et moi j\'y ajouterai encore; mon père vous a morigénés avec des étrivières, et moi j\'userai de fouets à pointes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Et le roi n\'exauça point le peuple, car la chose tourna ainsi de par Dieu, à cet effet que l\'Éternel accomplît sa parole qu\'il avait dite par l\'organe d\'Ahia, le Silonite, à Jéroboam, fils de Nebat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Et quand tous les Israélites virent que le roi ne les exauçait pas, le peuple répondit au roi en ces termes: En quoi sommes-nous participants de David? nous ne sommes point légataires du fils d\'Isaï! Chacun à vos tentes, Israélites! Désormais pourvois à ta maison, David. Et tout Israël regagna ses tentes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Quant aux Israélites domiciliés dans les villes de Juda, Roboam continua de régner sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Alors le roi Roboam délégua Adoram qui présidait aux corvées; mais les enfants d\'Israël le lapidèrent et il mourut. Et le roi Roboam se hâta de remonter sur son char et s\'enfuit à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Ainsi Israël s\'est détaché de la maison de David, comme il l\'est aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Et Roboam rentré à Jérusalem assembla la maison de Juda et de Benjamin, cent quatre-vingt mille hommes d\'élite faisant le service militaire pour entrer en guerre avec Israël, afin de reconquérir le royaume à Roboam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Alors la parole de l\'Éternel fut adressée à Semaïa, homme de Dieu, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Parle à Roboam, fils de Salomon, roi de Juda, et à tous les Israélites de Juda et de Benjamin, en ces termes: Ainsi parle l\'Éternel:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Ne marchez pas et ne vous battez pas contre vos frères, rentrez, chacun dans sa demeure; car c\'est de par Moi que cette chose a eu lieu. Et ils obéirent aux paroles de l\'Éternel, et renoncèrent à la campagne contre Jéroboam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Et Roboam résidait à Jérusalem, et il édifia des villes en forteresses dans Juda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'et il éleva Bethléhem et Eitam et Thékôa');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'et Bethtsur et Socho et Adullam');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'et Gath et Marésa et Ziph');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'et Adoraïm et Lachis et Azéca');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'et Tsorea et Ajalon et Hébron situées dans Juda et Benjamin, en villes fortes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Et il donna de la force aux remparts et y plaça des commandants et des provisions de vivres, et d\'huile et de vin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'et dans chaque ville des boucliers et des lances, et les rendit très fortes. Et à lui étaient Juda et Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Et les Prêtres et les Lévites qui étaient dans tout Israël, vinrent de tout son territoire, se ranger de son côté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Car les Lévites abandonnèrent leurs aires et leurs propriétés et passèrent en Juda et à Jérusalem, parce que Jéroboam et ses fils les chassèrent du sacerdoce de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'et il s\'institua des prêtres pour les tertres et les boucs et les veaux qu\'il avait fabriqués.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Et à leur suite, de toutes les Tribus d\'Israël ceux qui portaient leur cœur à chercher l\'Éternel, Dieu d\'Israël, vinrent à Jérusalem pour sacrifier à l\'Éternel, Dieu de leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Et ils renforcèrent le royaume de Juda, et affermirent Roboam, fils de Salomon, pendant trois ans. Car ils suivirent les errements de David et de Salomon, pendant trois ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Et Roboam prit pour sa femme Mahelath, fille de Jerimoth, fils de David et d\'Abihaïl, fille d\'Eliab, fils d\'Isaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Et elle lui enfanta des fils, Jeüs et Semaria et Zaham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Et après il épousa Maacha, fille d\'Absalom, et elle lui enfanta Abia et Atthaï et Ziza et Selomith.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Et Roboam aimait Maacha, fille d\'Absalom, plus que toutes ses femmes et concubines; car il avait pris dix-huit femmes et soixante concubines, et il engendra vingt-huit fils et soixante filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Et Roboam constitua comme chef Abia, fils de Maacha, comme prince entre ses frères, car c\'était en vue de le faire roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Et il agit prudemment et distribua de ses fils dans toutes les terres de Juda et de Benjamin, dans toutes les villes fortifiées et leur fournit des denrées en abondance, et fit pour eux la demande d\'une multitude de femmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Et lorsque la royauté de Roboam se fut affermie, et qu\'il fut devenu fort, il abandonna la Loi de l\'Éternel, et tout Israël avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Et dans la cinquième année du règne de Roboam, Sisac, roi d\'Egypte, marcha avec mille deux cents chars et soixante mille hommes de cavalerie sur Jérusalem, parce qu\'ils avaient été infidèles à l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'et innombrables étaient les troupes venues avec lui d\'Egypte, des Libyens, des Suchites et des Éthiopiens:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'et il prit les places fortes appartenant à Juda, et parut devant Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Mais Semaïa, le prophète, vint trouver Roboam et les princes de Juda qui s\'étaient rassemblés à Jérusalem pour échapper à Sisac, et leur dit: Ainsi parle l\'Éternel: Vous m\'avez abandonné, et aussi je vous abandonne aux mains de Sisac.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Alors les princes d\'Israël et le roi s\'humilièrent et dirent: L\'Éternel est juste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Et lorsque l\'Éternel vit qu\'ils s\'étaient humiliés, la parole de l\'Éternel fut adressée à Semaïa, en ces termes: Ils se sont humiliés, je ne les détruirai pas, et dans peu je les dégagerai, et ma colère ne s\'épanchera pas sur Jérusalem par la main de Sisac.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Cependant ils lui seront assujettis, afin qu\'ils sentent ce que c\'est que m\'être assujetti et être assujetti aux royaumes des autres pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Sisac, roi d\'Egypte, marcha donc sur Jérusalem; et il enleva les trésors du Temple de l\'Éternel, et les trésors du palais royal; il enleva tout, et enleva les boucliers d\'or qu\'avait faits Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Et pour les remplacer le roi Roboam fit des boucliers d\'airain qu\'il commit aux mains des chefs des coureurs, gardes de l\'entrée du palais royal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Et toutes les fois que le roi venait au Temple de l\'Éternel, les coureurs venaient les apporter, puis les reportaient dans la salle des coureurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Comme donc il s\'humilia, la colère de l\'Éternel se détourna de lui, à l\'effet de ne pas le détruire totalement: il y avait aussi dans Juda encore de bonnes choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Et le roi Roboam s\'affermit dans Jérusalem et régna. Roboam avait quarante-un ans à son avènement, et il régna dix-sept ans à Jérusalem, ville que l\'Éternel avait choisie dans toutes les Tribus d\'Israël, pour y placer son Nom. Or le nom de sa mère était Naama, l\'Ammonite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Et il fit le mal parce qu\'il ne dirigea pas son cœur vers la recherche de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Les actes de Roboam, les premiers et les derniers, sont d\'ailleurs consignés dans les histoires de Semaïa, le prophète, et de Iddo, le Voyant, aux registres. Et il y eut constamment hostilité entre Roboam et Jéroboam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Et Roboam reposa à côté de ses pères et reçut la sépulture dans la Cité de David, et son fils Abia devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'La dix-huitième année du roi Jéroboam, Abia devint roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Il régna trois ans à Jérusalem. Or le nom de sa mère était Michaïa, fille d\'Uriel, de Gibea.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Et il y eut hostilité entre Abia et Jéroboam. Et Abia ouvrit les hostilités avec une armée de braves guerriers forte de quatre cent mille hommes d\'élite, et Jéroboam se rangea en bataille contre lui avec huit cent mille hommes d\'une élite de braves guerriers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Alors Abia se leva debout sur le mont Tsemaraïm situé dans la montagne d\'Ephraïm, et dit: Écoutez-moi, Jéroboam et Israël tout entier!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'N\'est-il pas à votre connaissance que l\'Éternel, Dieu d\'Israël, a donné à David le royaume d\'Israël à perpétuité, à lui et à ses fils, par un pacte solennisé avec le sel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Mais Jéroboam, fils de Nebat, serviteur de Salomon, fils de David, s\'est soulevé et révolté contre son Seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'et à lui se sont joints des gens légers et des hommes de bas aloi, et ils ont conjuré contre Roboam, fils de Salomon, et Roboam était encore un homme jeune, et faible de cœur, et il ne leur opposa pas de la fermeté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Et maintenant vous pensez tenir tête à la royauté de l\'Éternel, qui est dans la main des fils de David, et vous êtes une grande multitude et avez avec vous les veaux d\'or dont Jéroboam a fait vos dieux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'N\'avez-vous pas expulsé les Prêtres de l\'Éternel, les fils d\'Aaron, et les Lévites, et vous vous êtes fait des prêtres, comme les peuples des autres pays! Quiconque se présentait pour se faire installer, avec un jeune taureau et sept béliers, devenait prêtre des non-dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Mais nous! l\'Éternel est notre Dieu et nous ne l\'avons point abandonné, et des Prêtres, fils d\'Aaron, et les Lévites en fonctions vaquent au service de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'et font fumer pour l\'Éternel des holocaustes chaque matin et chaque soir et de l\'encens odorant, et font la présentation du pain sur la table pure, et [nous avons] le candélabre d\'or et ses lampes pour brûler tous les soirs; car nous observons ce qui doit être observé envers l\'Éternel, notre Dieu; mais vous, vous l\'avez abandonné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Et voici avec nous, en tête, nous avons Dieu et ses Prêtres et les trompettes sonores pour les faire résonner contre vous. Enfants d\'Israël, ne faites pas la guerre à l\'Éternel, Dieu de vos pères, car vous n\'auriez pas le succès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Mais Jéroboam fit manœuvrer les troupes d\'embuscade de manière à les prendre par derrière de sorte qu\'il y en avait qui faisaient face à Juda et que l\'embuscade l\'attaquait par derrière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Et lorsque Juda tourna les yeux, voila qu\'il se vit attaqué par devant et par derrière. Alors ils crièrent vers l\'Éternel, et les Prêtres sonnèrent des trompettes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'et les hommes de Juda poussèrent un cri de guerre; et au cri de guerre des hommes de Juda, Dieu défit Jéroboam et tout Israël devant Abia et Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Et les enfants d\'Israël s\'enfuirent devant Juda, et Dieu les livra entre ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Et Abia et sa troupe en firent un grand carnage; et d\'Israël tombèrent morts cinq cent mille hommes d\'élite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Ainsi furent humiliés les enfants d\'Israël en ce temps, tandis que les enfants de Juda devinrent puissants, parce qu\'ils s\'appuyaient sur l\'Éternel, le Dieu de leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Et Abia poursuivit Jéroboam et lui enleva des villes, Béthel et ses annexes et Jesana et ses annexes, et Ephron et ses annexes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Et Jéroboam resta sans force tant que vécut Abia, et l\'Éternel l\'ayant frappé, il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Et Abia se fortifia et épousa quatorze femmes et engendra vingt-deux fils et seize filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Le reste des actes d\'Abia et de ses faits et de ses affaires est d\'ailleurs consigné dans le commentaire du prophète Iddo.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Et Asa fit ce qui est bien et droit aux yeux de l\'Éternel, son Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Et il fit disparaître les autels de l\'étranger et les tertres et il brisa les colonnes et mit en pièces les Astartés');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'et enjoignit à Juda de chercher l\'Éternel, Dieu de ses pères, et de pratiquer la Loi et le Commandement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Et il fit disparaître de toutes les villes de Juda les tertres et les colonnes solaires, et le pays fut en paix devant lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Et il bâtit des places fortes en Juda, car le pays était tranquille et durant ces années il n\'eut pas de guerre à soutenir, parce que l\'Éternel lui donna du repos.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Et il dit à Juda: Bâtissons ces villes et les entourons de murs et de tours, de portes et de verrous; le pays est encore à notre discrétion, parce que nous avons cherché l\'Éternel, notre Dieu, l\'avons cherché, et Il nous a assuré le repos de la part de tous nos alentours. Ils bâtirent donc et réussirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Et Asa avait une armée portant bouclier et lance, de Juda trois cent mille hommes, et de Benjamin deux cent quatre-vingt mille, portant la rondache et maniant l\'arc, tous braves guerriers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Et contre eux s\'avança Zérach, l\'Ethiopien, avec une armée d\'un million d\'hommes et trois cents chars, et il pénétra jusqu\'à Marésa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Et Asa sortit à sa rencontre, et ils se rangèrent en bataille dans la vallée de Tsephatha près de Marésa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Et Asa invoqua l\'Éternel, son Dieu, et dit: Éternel, nul autre que toi ne peut intervenir comme aide entre un fort et un faible: sois notre aide, Éternel, notre Dieu! car c\'est toi que nous prenons pour appui et c\'est en ton Nom que nous affrontons cette multitude; Éternel, tu es notre Dieu; que le mortel ne l\'emporte pas sur loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Alors l\'Éternel défit les Ethiopiens devant Asa et devant Juda, et les Ethiopiens prirent la fuite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Et Asa avec la troupe qui était avec lui les poursuivit jusqu\'à Gérar, et il tomba tant d\'Éthiopiens que pas un n\'eut la vie sauve; car ceux-ci furent taillés en pièces devant l\'Éternel et son armée. Et ils remportèrent un très grand butin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Et ils firent main basse sur toutes les villes autour de Gérar, car elles étaient sous la terreur de l\'Éternel, et ils pillèrent toutes les villes, car il s\'y trouvait beaucoup de butin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Et ils firent aussi main basse sur les tentes des troupeaux, et ils emmenèrent des brebis en quantité et des chameaux et regagnèrent Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'et tout Juda se réjouit du serment, car ils l\'avaient prêté de tout leur cœur, et c\'était de leur plein gré qu\'ils le cherchaient, et Il se laissa trouver par eux, et l\'Éternel leur donna paix de toutes parts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Or Azaria, fils de Oded, reçut l\'Esprit de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Et il alla au-devant d\'Asa et lui dit: Écoutez-moi, Asa, et vous tous de Juda et de Benjamin! L\'Éternel a été avec vous, parce que vous ayez été avec Lui; et si vous Le cherchez, Il se laissera trouver par vous; mais si vous L\'abandonnez, Il vous abandonnera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Il y a eu pour Israël de longs jours sans vrai Dieu et sans Prêtre enseignant, et sans Loi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'mais comme dans la détresse ils revinrent à l\'Éternel, Dieu d\'Israël, et le cherchèrent, Il se laissa trouver par eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Dans ces temps-là il n\'y avait point de sûreté pour qui sortait et qui entrait, mais une grande perturbation affectait tous les habitants du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Un peuple se heurtait contre un peuple et une ville contre une ville; car Dieu les inquiétait par toutes sortes de tribulations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Mais vous, restez fermes et n\'ayez pas les mains lâches; car il est un salaire pour vos œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Et lorsque Asa entendit ces paroles et la prophétie de Oded, le prophète, il s\'encouragea et extermina toutes les horreurs de tout le pays de Juda et de Benjamin, et des villes qu\'il avait conquises dans la montagne d\'Ephraïm, et il restaura l\'autel de l\'Éternel qui est devant le vestibule de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Et il assembla tout Juda et Benjamin et avec eux les étrangers d\'Ephraïm et de Manassé et de Siméon; car une multitude de gens étaient passés chez lui d\'Israël, lorsqu\'ils virent que l\'Éternel, son Dieu, était avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Et ils s\'assemblèrent à Jérusalem au troisième mois, la quinzième année du règne d\'Asa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'et dans cette journée ils sacrifièrent à l\'Éternel, sur le butin qu\'ils avaient remporté, sept cents taureaux et sept mille moutons,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'et conclurent l\'engagement de chercher l\'Éternel, Dieu de leurs pères, de tout leur cœur et de toute leur âme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'et quiconque ne chercherait pas l\'Éternel, Dieu d\'Israël, subirait la mort, petit et grand, homme et femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Et ils prêtèrent serment à l\'Éternel d\'une voix forte et par acclamation et au son des trompettes et des clairons:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'et tout Juda se réjouit du serment, car ils l\'avaient prêté de tout leur cœur, et c\'était de leur plein gré qu\'ils le cherchaient, et Il se laissa trouver par eux, et l\'Éternel leur donna paix de toutes parts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Et même il destitua Maacha, mère du roi Asa, de sa qualité de reine, pour avoir fait une idole Astarté; et Asa mit son idole en pièces, et la broya et la brûla dans la vallée du Cédron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Mais les tertres ne disparurent pas d\'Israël, néanmoins le cœur d\'Asa resta intact toute sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Et il introduisit ce que son père avait consacré et ce que lui-même avait consacré, dans le temple de Dieu, argent, or et meubles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Et il n\'y eut pas guerre jusqu\'à la trente-cinquième année du règne d\'Asa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'La trente-sixième année du règne d\'Asa, Baësa, roi d\'Israël, s\'avança contre Juda et fortifia Rama pour couper entrée et sortie à Asa, roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Alors Asa sortit de l\'argent et de l\'or des trésors du temple de l\'Éternel et du palais royal et l\'envoya à Ben-hadad, roi de Syrie, résidant à Damas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'avec ce message: Il existe une alliance entre moi et toi, et mon père et ton père: voici, je t\'envoie de l\'argent et de l\'or; va! romps ton alliance avec Baësa, roi d\'Israël, pour m\'en débarrasser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Et Ben-Hadad écouta le roi Asa et envoya ses généraux d\'armée contre les villes d\'Israël, et ils firent main basse sur Ijon, et Dan et Abel-Maïm et tous les magasins dans les villes de Nephthali.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Et à cette nouvelle Baësa renonça à fortifier Rama et fit cesser ses travaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Mais le roi Asa employa tout Juda pour faire enlever de Rama les pierres et le bois employés par Baësa, et il s\'en servit pour fortifier Géba et Mitspa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'Or dans le même temps Hanani, le Voyant, vint trouver Asa, roi de Juda, et lui dit: Parce que tu as pris pour appui le roi de Syrie, et que tu n\'as pas pris pour appui l\'Éternel, ton Dieu, pour cette raison l\'armée du roi de Syrie a échappé à ta main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Est-ce que les Éthiopiens et les Libyens n\'étaient pas des forces immenses quant au nombre, et aux chars et à la cavalerie? Mais parce que tu t\'appuyais sur l\'Éternel, Il les a livrés entre tes mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Car les yeux de l\'Éternel parcourent toute la terre pour soutenir ceux dont le cœur est tout à Lui. En cela tu as agi follement; car dès ce moment tu auras guerre à soutenir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Et Asa fut mécontent du Voyant et le mit en prison, car il était en colère contre lui à ce sujet. Dans ce temps aussi Asa opprima des gens dans le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Les actes d\'Asa, les premiers et les derniers, sont d\'ailleurs consignés dans le livre des rois de Juda et d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Et, la trente-neuvième année de son règne, Asa eut une maladie des pieds qui le rendait fort malade; et même dans sa maladie il eut recours non pas à l\'Éternel, mais aux médecins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Et Asa reposa à côté de ses pères, et il mourut dans la quarante-unième année de son règne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Et on lui donna la sépulture dans son tombeau qu\'il s\'était taillé dans la Cité de David, et on le coucha sur le lit qu\'on avait garni de parfums et d\'aromates préparés en pâte balsamique au moyen d\'un baume, et on lui fit une combustion d\'une magnificence extrême.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Et Josaphat, son fils, devint roi en sa place,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'et il se fortifia contre Israël. Et il mit des troupes dans toutes les villes de Juda, qui étaient places fortes, et mit des garnisons dans le pays de Juda et dans les villes d\'Ephraïm conquises par Asa, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Et l\'Éternel fut avec Josaphat, car il marcha sur les premiers errements de David, son père, et ne chercha pas les Baals,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'mais ce fut le Dieu de son père qu\'il chercha et dont il suivit les commandements et non point l\'exemple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Et l\'Éternel affermit la royauté dans sa main, et tout Juda faisait des présents à Josaphat, et il eut richesse et gloire en abondance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Et son courage s\'éleva comme il suivait les voies de l\'Éternel, et de plus il fit disparaître de Juda les tertres et les Aschères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Et la troisième année de son règne il délégua ses Chefs Ben-Haïl et Obadia et Zacharie et Nethaneël et Michée pour enseigner dans les villes de Juda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'et avec eux les Lévites Semaïa et Nethania et Zebadia et Asahel et Semiramoth et Jonathan et Adonia et Tobie et Tob-Adonia, Lévites, et avec eux Elisama et Joram, Prêtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Et ils enseignèrent en Juda, munis du Livre de la Loi de l\'Éternel, et ils firent le tour de toutes les villes de Juda et enseignèrent parmi le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Et la terreur de l\'Éternel pesa sur tous les royaumes des pays environnant Juda, de telle sorte qu\'ils ne s\'attaquèrent point à Josaphat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Et il y eut des Philistins qui apportaient à Josaphat des présents et de l\'argent en masse; les Arabes aussi lui amenèrent du menu bétail, sept mille sept cents béliers et sept mille sept cents boucs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Et Josaphat allait grandissant jusqu\'au plus haut point, et il construisit en Juda des châteaux et des villes avec magasins,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'et il faisait faire des travaux considérables dans les villes de Juda, et il avait des gens de guerre, vaillants soldats, à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Et voici leur rôle selon leurs maisons patriarcales. En Juda étaient chefs de milliers Adna, le chef, ayant avec lui trois cent mille vaillants soldats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'et à côté de lui Jochanan, le chef avec ses deux cent quatre-vingt mille hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'et à côté de lui Amasia, fils de Zichri, volontaire de l\'Éternel, avec ses deux cent mille vaillants soldats.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Et de Benjamin: le vaillant Eliada et avec lui deux cent mille hommes armés de l\'arc et du bouclier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'et à côté de lui Jozabad, et avec lui cent quatre-vingt mille hommes équipés pour le combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Tels étaient ceux qui étaient au service du roi, non compris ceux que le roi avait placés dans les villes fortes dans tout Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Et Josaphat avait en abondance richesse et gloire, et il s\'allia à Achab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Et au bout de quelques années il descendit chez Achab à Samarie, et Achab tua pour lui nombre de moutons et des bœufs, ainsi que pour les gens de sa suite et l\'invita à marcher contre Ramoth en Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Et Achab, roi d\'Israël, dit à Josaphat, roi de Juda: Veux-tu marcher avec moi contre Ramoth en Galaad? Et il lui répondit: Nous serons de pair moi et toi, et ton peuple et mon peuple, et avec toi j\'irai en guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Et Josaphat dit au roi d\'Israël: Qu\'il te plaise requérir aujourd\'hui la parole de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Et le roi d\'Israël réunit les prophètes au nombre de quatre cents hommes, et leur dit: Marcherons-nous à l\'attaque de Ramoth en Galaad? ou y renoncerai-je? Et ils dirent: Marche! et Dieu la livrera aux mains du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Et Josaphat dit: N\'y a-t-il point encore ici de prophète de l\'Éternel, par qui nous puissions consulter?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Et le roi d\'Israël dit à Josaphat: Il y a encore un homme par qui nous pourrions consulter l\'Éternel; mais je le hais parce que pour moi il ne prophétise jamais en bien, mais toujours en mal; c\'est Michée, fils de Jimla. Et Josaphat dit: Que le roi ne parle pas de la sorte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Alors le roi d\'Israël appela un eunuque et lui dit: Fais vite venir Michée, fils de Jimla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Cependant le roi d\'Israël et Josaphat, roi de Juda, étaient assis, chacun sur son trône, revêtus de leur costume, et se tenaient dans une aire aux abords de la porte de Samarie, et tous les prophètes prophétisaient devant eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Et Sédécias, fils de Cnaana, se fit des cornes de fer et dit: Ainsi parle l\'Éternel: Avec ceci tu heurteras les Syriens jusqu\'à les achever.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Et tous les prophètes prophétisaient de même et disaient: Marche contre Ramoth en Galaad et tu viendras à bout d\'elle, et l\'Éternel la livrera aux mains du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Et le messager qui était allé quérir Michée, lui parla en ces termes: Voici, les discours des prophètes sont à l\'unanimité favorables au roi, que ton discours soit donc comme celui de l\'un d\'eux, et parle favorablement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Et Michée dit: Par la vie de l\'Éternel! ce que mon Dieu me dira, je le rendrai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Et quand il fut arrivé vers le roi, le roi lui dit: Michée, marcherons-nous à l\'attaque de Ramoth en Galaad? ou y renoncerai-je? Et il répondit: Marchez!..., et vous réussirez..., et elle sera livrée à vos mains!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Et le roi lui dit: Combien de fois faut-il que je t\'adjure ils de ne me dire que la vérité au nom de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Et il dit: J\'ai vu tout Israël épars sur les montagnes comme un troupeau sans pasteur. Et l\'Éternel dit: Ils sont sans maîtres! qu\'ils retournent chacun dans sa maison en paix!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Alors le roi d\'Israël dit à Josaphat: Ne te l\'ai-je pas dit? pour moi il ne prophétise pas en bien, mais en mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Et il dit: En conséquence, écoutez la parole de l\'Éternel: J\'ai vu l\'Éternel assis sur son trône, et toute l\'armée des Cieux debout à sa droite et à sa gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Et l\'Éternel dit: Qui veut suggérer à Achab, roi d\'Israël, de marcher pour aller tomber à Ramoth en Galaad? Et l\'un parla d\'une manière, et l\'autre d\'une autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Alors l\'Esprit sortit et parut devant l\'Éternel et dit: Moi, je le lui suggérerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Et l\'Éternel lui dit: Comment? Et il dit: Je partirai et serai esprit de mensonge dans la bouche de tous ses prophètes. Et il dit: Suggère! et emporte-le! pars et ainsi fais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Eh bien! voici, l\'Éternel a mis un esprit de mensonge dans la bouche de ces tiens prophètes, et l\'Éternel a prononcé sur toi la ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Alors Sédécias, fils de Cnaana, s\'approcha et frappa Michée sur la joue et dit: Est-ce là la voie par où l\'esprit de l\'Éternel se serait retiré de moi pour communiquer avec toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Et Michée dit: Voici tu le verras le jour même où tu iras de chambre en chambre pour te cacher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Et le roi d\'Israël dit: Arrêtez Michée et le menez à Amon, préfet de la ville, et à Joas, fils du roi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'et dites: Ainsi parle le roi: Mettez cet homme en prison, et nourrissez-le de pain et d\'eau de rigueur, jusqu\'à ce que je revienne sain et sauf.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Et Michée dit: Si tu reviens sain et sauf, l\'Éternel n\'a pas parlé par moi. Et il dit: Entendez, vous tous les peuples!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Et le roi d\'Israël avec Josaphat, roi de Juda, marcha contre Ramoth en Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Et le roi d\'Israël dit à Josaphat: Je me travestirai pour aller au combat, mais toi, revêts-toi de ton costume. Le roi d\'Israël se travestit donc, et ils vinrent au combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Et le roi de Syrie avait donné cet ordre aux commandants de ses chars: N\'attaquez personne, ni petit, ni grand, sinon le roi d\'Israël seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Et lorsque les commandants des chars virent Josaphat, ils se dirent: C\'est le roi d\'Israël! et ils appuyèrent de son côté pour l\'attaquer. Alors Josaphat fit un cri, et l\'Éternel le secourut, et Dieu les écarta de lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'et lorsque les commandants des chars virent que ce n\'était pas le roi d\'Israël, ils revinrent de sa poursuite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Cependant un homme banda son arc tout innocemment, et atteignit le roi d\'Israël entre les pendants de la cuirasse et la cotte d\'armes. Et celui-ci dit à son cocher: Tourne et mène-moi hors de la mêlée, car je suis blessé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Et la bataille était intense pendant cette journée, et le roi d\'Israël resta debout sur son char en vue des Syriens jusqu\'au soir, et il mourut au moment du coucher du soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Et Josaphat, roi de Juda, revint sain et sauf dans son palais à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Alors se présenta devant lui Jéhu, fils de Hanani, le Voyant, et il dit au roi Josaphat: Faut-il être l\'auxiliaire de l\'impie? et aimes-tu les ennemis de l\'Éternel? et pour cela tu es un objet de colère de la part de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'cependant il s\'est trouvé chez toi des actions bonnes, puisque tu as exterminé du pays les Astartés, et que tu as appliqué ton cœur à la recherche de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Et Josaphat resta à Jérusalem. Et de nouveau il fit une tournée parmi le peuple, de Béerséba à la montagne d\'Éphraïm; et il les ramenait à l\'Éternel, Dieu de leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Et il établit des juges dans le pays, dans toutes les villes de Juda, places fortes, de ville en ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Et il dit aux Juges: Veillez à ce que vous ferez, car ce n\'est pas pour l\'homme que vous jugez, mais pour l\'Éternel; et Il est près de vous dans l\'affaire à juger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Maintenant donc soyez sous la crainte de l\'Éternel, prenez garde à vos actes, car chez l\'Éternel, notre Dieu, il n\'y a ni iniquité, ni partialité, ni acceptation de présents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Et à Jérusalem aussi Josaphat établit des Lévites et des Prêtres et des chefs de maisons patriarcales en Israël, pour la judicature de l\'Éternel et pour les procès; et ils étaient revenus à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Et il leur donna ses ordres en ces termes: Ainsi devez-vous agir dans la crainte de l\'Éternel avec bonne foi et un cœur intègre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'et quelle que soit la cause portée devant vous de la part de vos frères habitant vos villes, qu\'il s\'agisse de question de sang, de Loi, de commandement, de statuts et d\'arrêts, éclairez-les, afin qu\'ils ne se rendent pas coupables envers l\'Éternel, et que vous ne deveniez pas les objets de sa colère, vous et vos frères; ainsi faites et n\'assumez pas de culpabilité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Et voici, Amaria, le Grand-Prêtre, est préposé sur vous pour toutes les affaires de l\'Éternel, et Zebadia, fils d\'Ismaël, prince, de la maison de Juda pour toutes les affaires du roi; et vous avez devant vous des Secrétaires et des Lévites; fortifiez-vous et agissez, et que l\'Éternel soit avec l\'homme de bien!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Et dans la suite il arriva que les fils de Moab et les fils d\'Ammon, et avec eux une fraction des Meünites s\'avancèrent contre Josaphat pour l\'attaquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Et l\'on vint en donner avis à Josaphat en ces termes: Il arrive contre toi une grande multitude depuis l\'autre côté de la mer, depuis Aram, et voilà qu\'ils sont à Hatsatson-Thamar, c\'est-à-dire Engueddi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Alors Josaphat eut crainte, et il se décida à consulter pour lui l\'Éternel; et il proclama un jeûne pour tout Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Et Juda s\'assembla pour obtenir secours de l\'Éternel, et de toutes les villes de Juda aussi l\'on arriva pour chercher l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Et Josaphat parut dans l\'Assemblée de Juda et de Jérusalem au Temple de l\'Éternel devant le nouveau parvis');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'et il dit: Éternel, Dieu de nos pères, n\'es-tu pas Dieu dans les Cieux, et n\'es-tu pas souverain de tous les royaumes des nations? et dans ta main est force et vertu, et il n\'est personne qui te résiste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'N\'as-tu pas, ô notre Dieu, chassé les habitants de ce pays devant ton peuple d\'Israël, et ne l\'as-tu pas donné pour l\'éternité à la race d\'Abraham qui t\'aimait?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Et ils l\'ont habité et t\'y ont érigé un Sanctuaire pour ton Nom, disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Si nous sommes assaillis par la calamité, l\'épée, le jugement et la peste et la famine, nous nous présenterons devant ce Temple et devant toi, car ton Nom est dans ce Temple, et nous élèverons vers toi nos cris du sein de notre détresse, et tu exauceras et sauveras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Or maintenant voici les fils d\'Ammon et de Moab et ceux de la montagne de Séïr, chez lesquels tu n\'as pas permis aux Israélites d\'entrer, lorsqu\'ils venaient du pays d\'Egypte et qu\'ils évitèrent et ne détruisirent pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'voilà que ces gens nous payent de retour en venant nous chasser de notre propriété où tu nous as installés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'O notre Dieu, n\'exerceras-tu pas tes jugements sur eux? Car nous sommes sans force devant cette nombreuse multitude qui marche sur nous, et nous ne savons que faire, mais nos yeux sont tournés vers toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Or tout Juda était debout devant l\'Éternel, et même leurs enfants, leurs femmes et leurs fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Mais Jahaziel, fils de Zacharie, fils de Benaïa, fils de Jehiel, fils de Matthania, Lévite, des fils d\'Asaph, reçut l\'Esprit de l\'Éternel au sein de l\'Assemblée');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'et il dit: Attention! tout Juda, et habitants de Jérusalem, et toi, roi Josaphat! Ainsi parle à vous l\'Éternel: Soyez sans crainte et sans effroi devant cette nombreuse multitude, car ce n\'est pas ici votre guerre, c\'est celle de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Demain faites une descente sur eux; voici, ils graviront la montée de Tsits et vous les atteindrez à l\'extrémité de la vallée devant le Désert de Jéruël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Vous n\'aurez pas à vous y battre, paraissez, faites halte et soyez témoins de la délivrance que l\'Éternel opérera pour vous. Juda et Jérusalem, soyez sans crainte et sans effroi, demain sortez à leur rencontre! et l\'Éternel sera avec vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Alors Josaphat s\'inclina la face contre terre, et tout Juda et les habitants de Jérusalem se prosternèrent devant l\'Éternel pour rendre hommage à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Et les Lévites, des fils des Cahathites et des fils des Coraïtes, se levèrent pour louer l\'Éternel, Dieu d\'Israël, à haute et forte voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Et au matin ils se levèrent et partirent pour le Désert de Thékôa, et à leur départ Josaphat parut et dit: Écoutez-moi, Juda et habitants de Jérusalem! soyez fermes à vous confier en l\'Éternel, votre Dieu, et vous pourrez être fermes: confiez-vous dans ses prophètes et vous aurez le succès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Et il se consulta avec le peuple, et il désigna des chantres de l\'Éternel, qui, en costume sacré, rendaient grâces en passant devant la troupe équipée, et disaient: Louez l\'Éternel, car sa miséricorde est éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Et dans le moment où ils commençaient le concert et le cantique, l\'Éternel plaça une embuscade contre les fils d\'Ammon, de Moab, et ceux de la montagne de Séïr venus en Juda, et ceux-ci furent défaits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Et les fils d\'Ammon et de Moab prirent position contre les habitants de la montagne de Séïr pour les dévouer et les massacrer, et quand ils en eurent fini avec les habitants de Séïr, ils s\'aidèrent l\'un l\'autre à leur propre carnage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Cependant Juda atteignit la hauteur d\'où on a la vue du Désert, et là ils regardèrent du côté de la multitude, et voilà que c\'étaient des cadavres jonchant la terre, et pas un n\'avait échappé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Alors Josaphat et son monde vinrent pour le pillage de leur butin, et ils trouvèrent chez eux abondance de bien, d\'habits et de vases précieux, et ils en enlevèrent tant qu\'ils ne les pouvaient porter; et ils furent trois jours à piller le butin, car il était considérable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Et le quatrième jour ils s\'assemblèrent dans la Vallée de bénédiction, car là ils bénirent l\'Éternel, c\'est pourquoi ils donnèrent à ce lieu le nom de Vallée de bénédiction, qu\'il a encore aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Et tous les hommes de Juda et de Jérusalem, et Josaphat à leur tête, reprirent le chemin de Jérusalem dans la joie, car l\'Éternel leur avait donné dans leurs ennemis une cause de joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Et ils firent leur entrée à Jérusalem avec des harpes et des luths et des trompettes, jusqu\'au Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Et la terreur de Dieu envahit tous les royaumes des pays divers, lorsqu\'ils apprirent que l\'Éternel avait livré bataille aux ennemis d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Et le royaume de Josaphat fut tranquille, et son Dieu lui donna le repos de toutes parts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Ainsi régna Josaphat sur Juda. Il avait trente-cinq ans à son avènement et régna vingt-cinq ans à Jérusalem. Or le nom de sa mère était Azuba, fille de Silchi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Et il marcha sur les errements de son père Asa, et il n\'en dévia point, pratiquant ce qui est bien aux yeux de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Seulement les tertres ne disparurent pas, et le peuple n\'avait pas non plus le cœur dirigé vers le Dieu de ses pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Le reste des actes de Josaphat, les premiers et les derniers sont d\'ailleurs consignés dans les histoires de Jéhu, fils de Hanani, insérées dans le livre des rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Et dans la suite Josaphat, roi de Juda, se confédéra avec Achazia, roi d\'Israël, impie dans sa conduite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Et ils se confédérèrent ensemble pour construire des navires pour le voyage de Tarsis; et ils firent leurs vaisseaux à Etsion-Géber.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Alors Eliézer, fils de Dodava, de Marésa, prononça une prophétie contre Josaphat en ces termes: Parce que tu t\'es confédéré avec Achazia, l\'Éternel a détruit ton œuvre. Et les navires furent mis en pièces et ne purent faire le voyage de Tarsis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Et Josaphat reposa à côté de ses pères et reçut la sépulture auprès de ses pères dans la Cité de David, et Joram, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Et Joram avait des frères, fils de Josaphat: Azaria et Jehiel, et Zacharie et Azarie et Michaël et Sephatia, tout autant de fils de Josaphat, roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Et leur père leur avait fait des dotations considérables en argent et en or et en objets de prix, et en même temps en villes fortes de Juda; mais il donna la royauté à Joram, parce que celui-ci était le premier-né.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Joram fut donc élevé à la souveraineté de son père; et lorsqu\'il se fut affermi, il fit périr tous ses frères par l\'épée et quelques-uns aussi des Chefs d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Joram avait trente-deux ans à son avènement, et il régna huit ans à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Et il marcha sur les errements des rois d\'Israël, suivant l\'exemple donné par la maison d\'Achab; car il avait pour femme une fille d\'Achab; et il fit ce qui est mal aux yeux de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Cependant l\'Éternel ne voulut pas ruiner la maison de David, et cela en considération de l\'alliance qu\'il avait accordée à David et de la promesse qu\'il lui avait faite de laisser luire dans tous les temps un flambeau pour lui et ses fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'Au temps de Joram, Édom se rebella contre la domination de Juda, et ils établirent un roi au-dessus d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Alors Joram passa la frontière avec ses généraux, et ayant tous les chars avec lui; et il se leva pendant la nuit et battit les Édomites qui l\'avaient cerné, et les commandants des chars.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Néanmoins Édom [réussit à] se soustraire à la domination de Juda jusqu\'aujourd\'hui. Alors, dans le même temps Libna se rebella contre sa domination, parce qu\'il avait abandonné l\'Éternel, Dieu de ses pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Lui aussi éleva des tertres dans les montagnes de Juda et débaucha les habitants de Jérusalem, et fut le séducteur de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Et il lui vint une lettre d\'Élie, le prophète, portant: Ainsi parle l\'Éternel, Dieu de David, ton père: Puisque tu n\'as pas marché sur les errements de Josaphat, ton père, et sur les errements d\'Asa, roi de Juda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'mais que tu as marché sur les errements des rois d\'Israël, et débauché Juda et les habitants de Jérusalem, comme débauche la maison d\'Achab, et que tu as aussi fait périr tes frères, maison de ton père, meilleure que toi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'voici, l\'Éternel frappera d\'une grande plaie ton peuple et tes fils et tes femmes et toute ta fortune,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'et tu souffriras, d\'époque en époque, de grandes douleurs par l\'effet d\'une maladie de tes entrailles qui finiront par sortir ensuite de la maladie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'En conséquence l\'Éternel éveilla contre Joram l\'animosité des Philistins et des Arabes confinant aux Éthiopiens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Et ils s\'avancèrent contre Juda, et ils y ouvrirent la brèche, et ils emportèrent toute la propriété qui se trouvait dans le palais du roi, et aussi ses fils et ses femmes, de sorte qu\'il ne lui resta de fils que Joachaz, le cadet de ses fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Et après tout cela l\'Éternel le frappa aux entrailles d\'une maladie incurable;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'et elle suivit ses époques, et au bout de deux périodes ses entrailles sortirent, dans sa maladie; et il mourut dans des douleurs poignantes; et son peuple ne fit pas pour lui une combustion pareille à la combustion de ses pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Il avait trente-deux ans à son avènement et il régna huit ans à Jérusalem. Et il s\'en alla sans être regretté; et on lui donna la sépulture dans la Cité de David, mais non dans les tombeaux des rois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Et les habitants de Jérusalem firent Achazia, son fils cadet, roi en sa place; car tous les aînés avaient été tués par la horde venue avec les Arabes au camp. Ainsi devint roi Achazia, fils de Joram, roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Achazia avait quarante-deux ans à son avènement, et il régna un an à Jérusalem. Or le nom de sa mère était Athalie, fille d\'Omri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Lui aussi marcha sur les errements de la maison d\'Achab, car sa mère était sa conseillère d\'impiété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Et il fit ce qui est mal aux yeux de l\'Éternel, comme la maison d\'Achab, car là furent ses conseillers après la mort de son père, pour sa perte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Ce fut aussi d\'après leur conseil qu\'il se conduisit, et qu\'il marcha avec Joram, fils d\'Achab, roi d\'Israël, à l\'attaque de Hazaël, roi de Syrie, à Ramoth en Galaad. Et les Syriens blessèrent Joram,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'qui alors rebroussa pour se faire traiter à Jizréel des blessures qu\'il avait reçues à Rama, lorsqu\'il se battait contre Hazaël, roi de Syrie. Et Azaria, fils de Joram, roi de Juda, descendit pour visiter Joram, fils d\'Achab, à Jizréel, parce qu\'il était malade.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Et c\'est par la volonté de Dieu qu\'Achazia se perdit en venant auprès de Joram; et à son arrivée il s\'achemina avec Joram, au-devant de Jéhu, fils de Nimsi, que l\'Éternel avait oint pour extirper la maison d\'Achab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Et comme Jéhu faisait justice de la maison d\'Achab, il atteignit les chefs de Juda et les fils des frères d\'Achab, qui étaient au service d\'Achazia, et les massacra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Et il chercha Achazia, qui fut pris comme il se cachait dans Samarie, et on l\'emmena à Jéhu, et on le fit mourir, et on lui donna la sépulture; car ils disaient: C\'est le fils de Josaphat qui cherchait l\'Éternel de tout son cœur. Et dans la maison d\'Achazia il n\'y avait personne d\'apte à régner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Mais Athalie, mère d\'Achazia, voyant son fils mort, se mit en devoir de détruire toute la race royale de la maison de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Alors Josabeath, fille de roi, prit Joas, fils d\'Achazia, et parvint à le soustraire du milieu des fils du roi qu\'on mettait à mort, et le logea lui et sa nourrice dans la salle des lits; ainsi le cacha Josabeath, fille du roi Joram, femme de Joiada, le Prêtre (car elle était sœur d\'Achazia) aux regards d\'Athalie, afin que celle-ci ne le fît pas mourir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'et il fut avec eux dans la maison de Dieu, caché pendant six ans. Cependant Athalie régissait le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Et la septième année Joiada s\'enhardit et forma ligue avec les chefs de cent, Azaria, fils de Jéroham, et Ismaël, fils de Jochanan, et Azaria, fils de Obed, et Maaseïa, fils de Adaïa, et Elisaphat, fils de Zichri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Et ils firent la tournée de Juda, et rassemblèrent les Lévites de toutes les villes de Juda et les patriarches d\'Israël, afin qu\'ils vinssent à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Et toute l\'Assemblée conclut un pacte dans le Temple de Dieu avec le roi. Et Joiada leur dit: Voici, le fils du roi sera roi, ainsi que l\'Éternel l\'a promis au sujet des fils de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Voici ce que vous avez à faire: Un tiers d\'entre vous pris dans les Prêtres et les Lévites montera la garde le jour du Sabbat, comme portiers des seuils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'et un tiers se tiendra au palais royal, et un tiers à la porte Jesod, et tout le peuple dans les parvis de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Et que dans le Temple de l\'Éternel ne pénètre personne autre que les Prêtres et Lévites de service; que ceux-là entrent, car ils sont consacrés; et tout le peuple fera la garde de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Et les Lévites entoureront le roi de tous les côtés, chacun ses armes à la main, et quiconque s\'introduira dans le Temple doit être mis à mort; et escortez le roi à son entrée et à sa sortie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Et les Lévites et tous les hommes de Juda exécutèrent tous les ordres du Prêtre Joiada, et ils prirent chacun ses gens, ceux qui montaient la garde le jour du Sabbat, et ceux qui descendaient la garde le jour du Sabbat; car le Prêtre Joiada n\'avait pas exempté les classes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Et le Prêtre Joiada donna aux chefs de cent les lances et les boucliers et les écus du roi David qui étaient dans la maison de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Et il posta tout le monde, chacun son javelot à la main, depuis le flanc droit de l\'édifice jusqu\'au flanc gauche de l\'édifice, à l\'autel et vers le temple auprès du roi tout à l\'entour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Et ils amenèrent dehors le fils du roi et lui posèrent la couronne et lui remirent la Loi, et le firent roi, et Joiada et ses fils l\'oignirent et dirent: Vive le roi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Alors Athalie entendit l\'acclamation du peuple accourant et proclamant le roi, et elle vint se présenter au peuple dans le Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Et elle regarda, et voilà que le roi était debout sur son estrade à l\'entrée, et les généraux et les trompettes étaient aux côtés du roi, et tout le peuple du pays était dans l\'allégresse et sonnant des trompettes et les chantres avec des instruments préludaient à la louange. Alors Athalie déchira ses habits et dit: Conjuration! conjuration!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Mais le Prêtre Joiada fit paraître les chefs de cent, commandants de l\'armée, et leur dit: Menez-la dehors jusqu\'entre les rangs, et que qui la suivra meure par l\'épée; car le Prêtre disait: Ne la faites pas mourir dans le Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Et ils lui ouvrirent passage, et elle entra par l\'avenue de la porte des chevaux dans le palais royal, et là ils lui donnèrent la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Et Joiada conclut un pacte entre lui et tout le peuple et le roi, à cet effet que le peuple devînt le peuple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Alors tout le peuple envahit le temple de Baal, et ils le renversèrent et en brisèrent les autels et les images; et Mathan, prêtre de Baal, ils le tuèrent devant les autels.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Et Joiada remit les fonctions du Temple de l\'Éternel entre les mains des Prêtres, des Lévites que David avait répartis dans le Temple de l\'Éternel pour offrir les holocaustes de l\'Éternel, comme il est écrit dans la Loi de Moïse, avec réjouissance et avec chant, à la manière de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Et Joiada établit les portiers aux portes du Temple de l\'Éternel, afin qu\'il n\'y pénétrât aucun impur à un titre quelconque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Et il prit les chefs de cent et les nobles et les Seigneurs du peuple et tout le peuple du pays et fit descendre le roi du Temple de l\'Éternel, et ils entrèrent par la porte supérieure dans le palais royal et ils installèrent le roi sur le trône royal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Et tout le peuple du pays se réjouissait, et la ville était tranquille, d\'ailleurs ils avaient fait périr Athalie par l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joas avait sept ans à son avènement, et il régna quarante ans à Jérusalem. Or le nom de sa mère était Tsibia de Béerséba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Et Joas fit ce qui est bien aux yeux de l\'Éternel, tant que vécut le Prêtre Joiada.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Et Joiada prit pour Joas deux femmes; et il engendra des fils et des filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Et il arriva dans la suite que Joas eut la pensée de restaurer le Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'A cet effet il assembla les Prêtres et les Lévites et leur dit: Rendez-vous dans les villes de Juda et recueillez dans tout Israël de l\'argent pour réparer la Maison de votre Dieu, annuellement, et accélérez cette affaire. Mais les Lévites n\'usèrent pas de célérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Alors le roi manda Joiada, le Grand-Prêtre, et lui dit: Pourquoi n\'as-tu pas surveillé les Lévites pour qu\'ils fissent en Juda et à Jérusalem le recouvrement de la taxe de Moïse, serviteur de l\'Éternel, et de l\'Assemblée d\'Israël pour la Tente du Témoignage?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Car Athalie, l\'impie, ses fils ont abîmé la Maison de Dieu, et même de tous les objets consacrés du Temple de l\'Éternel ils ont fabriqué des Baals.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Et le roi ordonna de faire un coffre, qui fut placé à la porte du Temple de l\'Éternel en dehors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Et l\'on publia dans Juda et dans Jérusalem qu\'on eût à venir acquitter à l\'Éternel la taxe de Moïse, serviteur de Dieu, imposée à Israël dans le Désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Et tous les chefs et tout le peuple furent réjouis, et l\'on apporta et versa dans le coffre, jusqu\'à ce que les versements fussent au complet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Et quand c\'était le moment de faire apporter le coffre à l\'officier du roi par les soins des Lévites, et quand ils voyaient qu\'il y avait beaucoup d\'argent, alors arrivaient le secrétaire du roi et l\'officier du Grand-Prêtre, et ils vidaient le coffre, puis le prenaient et le remettaient à sa place; c\'était pour eux l\'affaire de chaque jour, et ils recueillirent de l\'argent en quantité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Et le roi: et Joiada le remirent à l\'entrepreneur des travaux dans le Temple de l\'Éternel, lequel prenait à gages des tailleurs de pierre et des charpentiers pour restaurer le Temple de l\'Éternel, et aussi des ouvriers en fer et en airain pour réparer le Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Et les entrepreneurs de l\'ouvrage s\'exécutèrent et les réparations à faire avancèrent par leurs mains, et ils remirent en état le Temple de Dieu et le consolidèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Et quand ils l\'eurent achevé, ils apportèrent devant le roi et Joiada le reste de l\'argent, et l\'on en fit des ustensiles pour le Temple de l\'Éternel, des ustensiles pour le service et le sacrifice et des jattes et de la vaisselle d\'or et d\'argent. Et l\'on offrit des holocaustes dans le Temple de l\'Éternel, constamment tant que vécut Joiada.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Mais Joiada était devenu vieux, et il était comblé de jours et il mourut; et il avait à sa mort l\'âge de cent trente ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Et on lui donna la sépulture dans la Cité de David avec les rois, parce qu\'il avait fait du bien en Israël et pour Dieu et sa Maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Et après la mort de Joiada les princes de Juda vinrent s\'incliner devant le roi; alors le roi les écouta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Et ils abandonnèrent le Temple de l\'Éternel, Dieu de leurs pères, et servirent les Astartés et les idoles, et Juda et Jérusalem furent un objet de colère pour s\'être rendus coupables de la sorte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Et Il envoya parmi eux, pour les ramener à l\'Éternel, des prophètes qui les sommèrent, mais ils ne prêtèrent pas l\'oreille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Cependant Zacharie, fils du Prêtre Joiada, fut revêtu de l\'esprit de Dieu, et il se présenta de haut lieu devant le peuple et il lui dit: Ainsi parle Dieu: Pourquoi transgressez-vous les commandements de l\'Éternel? Vous ne vous en trouverez pas bien! Puisque vous abandonnez l\'Éternel, Il vous abandonnera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Et ils conjurèrent contre lui et ils l\'assommèrent à coups de pierres par l\'ordre du roi, dans le parvis du Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Et le roi Joas ne se souvint pas de l\'amour que lui avait témoigné Joiada, son père, et il fut le meurtrier de son fils. Et en mourant celui-ci dit: L\'Éternel voit et redemandera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Et l\'année révolue, l\'armée des Syriens s\'avança contre Joas, et ils envahirent Juda et Jérusalem et massacrèrent tous les princes du peuple dans son sein, et envoyèrent tout leur butin au roi à Damas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Bien que ce fût avec un petit nombre d\'hommes qu\'arrivât l\'armée des Syriens, cependant l\'Éternel livra entre leurs mains une armée très considérable, parce qu\'ils avaient abandonné l\'Éternel, Dieu de leurs pères; et les Syriens exécutèrent sur Joas les jugements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Et après le départ des Syriens qui l\'avaient laissé avec beaucoup de blessures, ses serviteurs conjurèrent contre lui, à cause du meurtre du fils du Prêtre Joiada, et ils l\'égorgèrent sur son lit, et il mourut. Et on l\'inhuma dans la Cité de David, mais il ne reçut pas la sépulture dans les tombeaux des rois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Et voici ceux qui conjurèrent contre lui: Zabad, fils de Simeath, l\'Ammonite, et Jozabad, fils de Simrith, la Moabite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'D\'ailleurs quant à ses fils et à la grandeur du tribut à lui imposé et aux constructions faites à la Maison de Dieu, ces choses sont consignées dans le commentaire du livre des rois. Et Amatsia, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'C\'est à vingt-cinq ans que Amatsia devint roi, et il régna vingt-neuf ans à Jérusalem. Or le nom de sa mère était Joadan de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Et il fit ce qui est bien aux yeux de l\'Éternel, seulement pas d\'un cœur non partagé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Et lorsque la royauté lui fut assurée, il fit périr ses serviteurs, meurtriers du roi son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Mais il ne mit pas à mort leurs fils, se conformant à ce qui est écrit dans la Loi, dans le Livre de Moïse, d\'après l\'ordre de l\'Éternel, portant: Les pères ne subiront pas la mort à cause de leurs fils, et les fils ne subiront pas la mort à cause de leurs pères, mais chacun subira la mort pour son péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Et Amatsia assembla les hommes de Juda et les rangea par maisons patriarcales, par chefs de milliers et par chefs de centaines, pour la totalité de Juda et de Benjamin, et il les dénombra dès l\'âge de vingt ans et au-dessus, et il en trouva trois cent mille d\'élite, aptes à la guerre, maniant la lance et le bouclier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Et il prit à sa solde d\'Israël cent mille hommes forts dans la guerre, pour le prix de cent talents d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Cependant un homme de Dieu vint le trouver et lui dit: O roi, ne te fais pas accompagner par des troupes d\'Israël, car l\'Éternel n\'est pas avec Israël, avec tous les enfants d\'Éphraïm!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'va plutôt seul, agis et tiens ferme au combat! Dieu pourrait te faire tomber devant l\'ennemi, car à Dieu est le pouvoir de soutenir ou de faire tomber.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Et Amatsia dit à l\'homme de Dieu: Mais que faire à l\'égard des cent talents que j\'ai délivrés à la troupe d\'Israël? Et l\'homme de Dieu dit: Dieu peut te rendre plus que cela.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Alors Amatsia les sépara, c\'est-à-dire la troupe arrivée chez lui d\'Éphraïm, afin qu\'ils retournassent en leurs lieux. Mais ils furent irrités d\'une extrême colère contre Juda, et ils rentrèrent en leurs lieux enflammés de colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Néanmoins Amatsia s\'enhardit et prit son peuple sous sa conduite et gagna la Vallée du sel, et il tua aux enfants de Séïr dix mille hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Et les enfants de Juda en firent prisonniers dix mille vivants, qu\'ils menèrent à la pointe de la roche d\'où ils les précipitèrent, de sorte que tous ils furent éventrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Cependant les gens de la troupe qu\'Amatsia avait congédiés pour n\'en être pas accompagné au combat, se jetèrent dans les villes de Juda, de Samarie à Bethoron, et y tuèrent trois mille hommes et emportèrent un grand butin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Et Amatsia, de retour après la défaite des Édomites, fit venir les dieux des enfants de Séïr et se les érigea en dieux, et les adora et leur offrit de l\'encens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Alors la colère de l\'Éternel s\'alluma contre Amatsia, et Il lui délégua un prophète, qui lui dit: Pourquoi vas-tu chercher les dieux de ce peuple, qui n\'ont pu sauver leur peuple de ta main?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Et comme il lui parlait, [Amatsia] lui dit: T\'a-t-on constitué conseiller du roi? Cesse! pourquoi veux-tu être battu? Alors le prophète s\'abstint et dit: Je reconnais que Dieu a résolu ta perte, parce que tu agis ainsi et n\'écoutes pas mon conseil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Et Amatsia, roi de Juda, se consulta, et il députa vers Joas, fils de Joachaz, fils de Jéhu, roi d\'Israël, pour lui dire: Viens! voyons-nous en présence!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Alors Joas, roi d\'Israël, députa vers Amatsia, roi de Juda, pour lui dire: L\'épine du Liban députa vers le cèdre du Liban pour lui dire: Donne ta fille à mon fils pour femme! Alors passèrent les bêtes sauvages du Liban, et elles écrasèrent l\'épine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Tu te dis: Voici, tu as battu les Édomites! et ton cœur te donne l\'ambition de la gloire; or, reste chez toi! pourquoi veux-tu provoquer un revers pour tomber, toi, et Juda avec toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Mais Amatsia n\'écouta point, car c\'était une dispensation de Dieu à l\'effet de le livrer pour avoir recherché les dieux d\'Édom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Joas, roi d\'Israël, s\'avança donc et ils se virent en présence, lui et Amatsia, roi de Juda, à Bethsémès en Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Mais Juda fut battu devant Israël, et ils s\'enfuirent chacun dans leurs tentes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Et Amatsia, roi de Juda, fils de Joas, fils d\'Achazia, fut fait prisonnier à Bethsémès par Joas, roi d\'Israël, qui le mena à Jérusalem, et démolit le mur de Jérusalem, depuis la porte d\'Éphraïm jusqu\'à la porte de l\'angle sur un espace de quatre cents coudées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'et prit tout l\'or et l\'argent et tous les trésors qui se trouvaient dans la Maison de Dieu chez Obed-Édom, et les trésors du palais royal et les otages, puis revint à Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Et Amatsia, fils de Joas, roi de Juda, vécut encore quinze ans après la mort de Joas, fils de Joachaz, roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Le reste des actes d\'Amatsia, les premiers et les derniers, est d\'ailleurs consigné dans le livre des rois de Juda et d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Et à partir du temps où Amatsia s\'éloigna de l\'Éternel, il se forma contre lui une conjuration à Jérusalem, et il s\'enfuit à Lachis, et ils envoyèrent à sa poursuite à Lachis, et là on le fit mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Et il fut rapporté à dos de chevaux et reçut la sépulture à côté de ses pères dans la ville de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Alors tout le peuple de Juda prit Hozias, alors âgé de seize ans, et le fit roi en la place de son père, Amatsia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Il rebâtit Eloth et la reconquit à Juda, après que le roi eut été couché à côté de ses pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Hozias avait seize ans à son avènement et il régna cinquante-deux ans à Jérusalem. Or le nom de sa mère était Jecholia de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Et il fit ce qui est bien aux yeux de l\'Éternel en tout à l\'exemple d\'Amatsia, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Et il fut cherchant Dieu du vivant de Zacharie, l\'homme versé dans la contemplation de Dieu, et durant les jours où il chercha l\'Éternel, Dieu le fit prospérer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Et il se mit en campagne et se battit contre les Philistins, et il renversa les murs de Gath et les murs de Jabné et les murs d\'Asdod, et bâtit des villes en Asdod et parmi les Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Et Dieu lui fut en aide contre les Philistins et contre les Arabes établis à Gurbaal, et les Meünites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Et les Ammonites firent des présents à Hozias, et son nom parvint jusqu\'en Egypte; car il était extrêmement puissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Et Hozias construisit des tours à Jérusalem à la porte de l\'angle et à la porte de la vallée, et au redan, et les mit en état de défense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Et il bâtit des tours dans le Désert, et creusa une multitude de citernes, car il avait de nombreux troupeaux et dans le pays-bas et dans la plaine, des laboureurs et des vignerons sur les monts et au Carmel, car il aimait l\'agriculture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Et Hozias avait une force armée propre à la guerre, qui allait en campagne par bataillons, d\'après le chiffre de leur recensement fait par Jehiel, le Scribe, et Maaseïa, le préposé, sous les ordres de Hanania, l\'un des généraux du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Le nombre total des patriarches des guerriers était de deux mille six cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Et la milice sous leurs ordres était de trois cent sept mille cinq cents hommes faisant la guerre avec une force vaillante pour aider le roi contre l\'ennemi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Et Hozias leur procura, à toute l\'armée, des boucliers et des lances et des casques et des cuirasses et des arcs et jusqu\'à des pierres à fronde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Et il fit à Jérusalem des engins, ingénieux travail des ingénieurs, pour être placés sur les tours et aux redans pour tirer avec des flèches et de grosses pierres. Et son nom se répandit au loin, car il fut aidé merveilleusement à devenir puissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Mais quand il fut puissant, son cœur s\'éleva, pour sa perte; et il fut infidèle à l\'Éternel, son Dieu; et il pénétra dans le Temple de l\'Éternel pour encenser sur l\'autel aux parfums.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Alors il y fut suivi par le Prêtre Azaria accompagné de Prêtres de l\'Éternel au nombre de quatre-vingts hommes de cœur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'et ils s\'opposèrent à Hozias, le roi, et lui dirent: Ce n\'est pas à toi, Hozias, à offrir l\'encens à l\'Éternel, mais aux Prêtres, fils d\'Aaron, qui sont consacrés pour l\'encensement. Sors du sanctuaire, car tu forfais! et cet honneur ne t\'a pas été décerné par l\'Éternel, Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Alors Hozias se courrouça, et il avait en main un encensoir pour encenser; et comme il se courrouçait contre les Prêtres, la lèpre éclata sur son front à la vue des Prêtres dans le Temple de l\'Éternel à côté de l\'autel aux parfums.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Et lorsque le Grand-Prêtre Azaria et tous les Prêtres arrêtèrent leurs regards sur lui, voilà qu\'il avait la lèpre au front; et ils le chassèrent de là, et lui-même se hâta de sortir parce que l\'Éternel l\'avait frappé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Et le roi Hozias fut lépreux jusqu\'au jour de sa mort, et il logea dans une infirmerie en tant que lépreux: car il était exclu du Temple de l\'Éternel. Et Jotham, son fils, fut préposé sur la maison du roi, et gouverna le peuple du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Le reste des actes d\'Hozias, les premiers et les derniers, Ésaïe, fils d\'Amots, le prophète, en a écrit l\'histoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Et Hozias reposa à côté de ses pères, et reçut la sépulture à côté de ses pères dans le champ sépulcral des rois; car l\'on dit: Il est lépreux. Et Jotham, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jotham avait vingt-cinq ans à son avènement et il régna seize ans à Jérusalem. Or le nom de sa mère était Jerusa, fille de Tsadoc.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Et il fit ce qui est bien aux yeux de l\'Éternel, en tout à l\'exemple de Hozias, son père, seulement il ne s\'introduisit pas dans le Temple de l\'Éternel; le peuple se corrompait encore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Et il construisit la porte supérieure du Temple de l\'Éternel, et il fit beaucoup de travaux aux murs d\'Ophel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Et il bâtit des villes dans la montagne de Juda, et dans les forêts il bâtit des châteaux et des tours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Et il eut guerre avec le roi des Ammonites, et il les vainquit, et les Ammonites lui payèrent cette année-là cent talents d\'argent et dix mille cors de froment et dix mille d\'orge. C\'est ce que lui payèrent les Ammonites aussi la seconde année et la troisième.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Et Jotham devint puissant, parce qu\'il réglait ses voies devant l\'Éternel son Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Le reste des actes de Jotham et tous ses combats, et tous ses errements sont d\'ailleurs consignés dans le livre des rois d\'Israël et de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Il avait vingt-cinq ans à son avènement et il régna seize ans à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Et Jotham reposa à côté de ses pères et reçut la sépulture dans la Cité de David. Et Achaz, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Achaz avait vingt ans à son avènement et il régna seize ans à Jérusalem. Et il ne fit pas ce qui est bien aux yeux de l\'Éternel, comme David, son père,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'et il marcha sur les errements des rois d\'Israël, et il fit aussi des images de fonte aux Baals,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'et il offrit de l\'encens dans la vallée des fils de Hinnom et brûla ses fils au feu, imitant les abominations des nations que l\'Éternel avait chassées devant les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Et il offrit des victimes et de l\'encens sur les tertres et sur les collines et sous tous les arbres verts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Alors l\'Éternel, son Dieu, le livra aux mains du roi de Syrie, et [les Syriens] le battirent et lui firent beaucoup de prisonniers qu\'ils menèrent à Damas; il fut aussi livré aux mains du roi d\'Israël qui lui fit essuyer une grande défaite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Et Pékach, fils de Remalia, tua en Juda dans une journée cent vingt mille hommes, tous braves guerriers, parce qu\'ils abandonnaient l\'Éternel, Dieu de leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Et Zichri, héros d\'Éphraïm, tua Maaseïa, fils du roi, et Azricam, préfet du palais, et Elkana, le second après le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Et les Israélites emmenèrent en captivité, de leurs frères, deux cent mille femmes, fils et filles, et ils leur enlevèrent aussi un grand butin qu\'ils amenèrent à Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Or il y avait là un prophète de l\'Éternel, nommé Oded, et il sortit à la rencontre de l\'armée qui rentrait à Samarie et il leur dit: Voilà que dans sa colère contre Juda l\'Éternel, Dieu de vos pères, les a livrés entre vos mains, et dans la fureur vous en avez fait un tel carnage, qu\'il est parvenu jusqu\'aux Cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Et maintenant pensez-vous vous assujettir comme serviteurs et servantes les enfants de Juda et de Jérusalem? mais vous, en votre particulier, ne vous sentez-vous pas coupables envers l\'Éternel, votre Dieu?...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Écoutez-moi donc et renvoyez les prisonniers que vous avez faits sur vos frères; car la colère de l\'Éternel est allumée sur vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Alors se levèrent des hommes d\'entre les chefs des fils d\'Éphraïm, Azaria, fils de Jochanan, Béréchia, fils de Mesillemoth, et Ézéchias, fils de Sallum, et Amasa, fils de Hadlaï, pour s\'opposer à ceux qui venaient de l\'armée');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'et ils leur dirent: N\'introduisez pas ces prisonniers-là! pensez-vous en effet, pour nous attirer la vindicte de l\'Éternel, augmenter encore nos péchés et notre culpabilité? car notre culpabilité est grande et la colère est allumée sur Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Alors la troupe armée laissa les prisonniers et le butin devant les chefs et toute l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Et les hommes, qui ont été désignés par leurs noms, se levèrent et s\'emparèrent des prisonniers, et vêtirent tous ceux d\'entre eux qui étaient nus, en prenant sur le butin, ils les vêtirent et les chaussèrent et leur donnèrent à manger et à boire, et les oignirent et les reconduisirent, sur des ânes tous les excédés, et les amenèrent à Jéricho, la ville des palmiers, chez leurs frères, puis-regagnèrent Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Dans ce temps-là le roi Achaz députa vers les rois d\'Assyrie pour se ménager leur secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Et vinrent encore les Edomites qui firent un coup en Juda et emmenèrent des captifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Et il y eut invasion des Philistins dans les villes du pays-bas et du midi de Juda, et ils s\'emparèrent de Bethsémès et d\'Ajalon et de Gedéroth et de Socho et de ses annexes et de Thimna et de ses annexes, et de Gimzo et de ses annexes, et s\'y établirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Car l\'Éternel humiliait Juda à cause d\'Achaz, roi d\'Israël, parce qu\'il laissait Juda sans frein et qu\'il était rebelle à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Et il fut assailli par Thiglath-Pilnéser, roi d\'Assyrie, qui le serra de près, loin de lui prêter secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Bien que Achaz eût dépouillé le Temple de l\'Éternel et le palais du roi et des Grands pour payer le roi d\'Assyrie, cela ne lui servit de rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Et dans le moment de la détresse il fut encore plus infidèle à l\'Éternel, lui, le roi Achaz.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Et il fit des sacrifices aux dieux de Damas qui l\'avaient battu et il dit: Les dieux des rois de Syrie leur sont secourables, je veux leur faire des sacrifices afin qu\'ils me soient secourables. Mais ils servirent à amener la chute de lui et de tout Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Et Achaz ramassa toute la vaisselle de la Maison de Dieu et mit en pièces la vaisselle de la Maison de Dieu, et il ferma les portes du Temple de l\'Éternel et se fit des autels à tous les coins de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Et dans toutes les villes de Juda il fit des tertres pour brûler de l\'encens aux autres dieux; et il provoqua l\'Éternel, Dieu de ses pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Le reste de ses actes et tous ses errements, les premiers et les derniers, sont d\'ailleurs consignés dans le livre des rois de Juda et d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Et Achaz reposa à côté de ses pères et reçut la sépulture dans la ville de Jérusalem; car on ne l\'introduisit pas dans les tombeaux des rois d\'Israël. Et Ezéchias, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Et Ezéchias fut roi à l\'âge de vingt-cinq ans et il régna vingt-neuf ans à Jérusalem. Or le nom de sa mère était Abia, fille de Zacharie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Et il fit ce qui est bien aux yeux de l\'Éternel, en tout à l\'exemple de David, son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Quant à lui, dès la première année de son règne, au premier mois, il rouvrit les portes du Temple de l\'Éternel et les restaura.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Et il convoqua les Prêtres et les Lévites et les assembla dans la place orientale,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'et il leur dit: Écoutez-moi, Lévites! Maintenant mettez-vous en état de sainteté, et mettez en état de sainteté le Temple de l\'Éternel, Dieu de vos pères, et ôtez du Sanctuaire la souillure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Car nos pères ont été infidèles et ont fait ce qui est mal aux yeux de l\'Éternel, notre Dieu, et ils l\'ont abandonné et ont détourné leurs regards de la résidence de l\'Éternel et lui ont tourné le dos;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'ils ont aussi fermé les portes du vestibule et éteint les lampes, et n\'ont pas brûlé d\'encens, ni offert d\'holocaustes dans le Sanctuaire au Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Aussi la colère de l\'Éternel a-t-elle éclaté sur Juda et Jérusalem, dont Il a fait un objet de vexations, d\'horreur et de moquerie, comme vous le voyez de vos yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Et voici pour cela, nos pères sont tombés sous le glaive, et nos fils et nos filles et nos femmes sont dans la captivité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Maintenant j\'ai à cœur de solenniser une alliance avec l\'Éternel, Dieu d\'Israël, à l\'effet de détourner de nous le feu de sa colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Mes fils, à cette heure point de nonchalance! car c\'est vous que l\'Éternel a élus pour vous tenir devant lui, le servir et être ses ministres et lui brûler l\'encens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Alors se levèrent les Lévites Mahath, fils d\'Amasaï, et Joël, fils d\'Azaria, d\'entre les fils des Cahathites; et d\'entre les fils de Merari, Kis, fils d\'Abdi, et Azaria, fils de Jehaléleël; et d\'entre les Gersonites, Joah, fils de Zimma, et Eden, fils de Joah;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'et d\'entre les fils d\'Elitsaphan, Simri et Jehiel; et d\'entre les fils d\'Asaph, Zacharie et Mathania;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'et d\'entre les fils de Heiman, Jehiel et Siméï, et d\'entre les fils de Jeduthun, Semaïa et Uzziel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Et ils réunirent leurs frères et se mirent en état de sainteté, et ils vinrent selon l\'ordre du roi conforme aux paroles de l\'Éternel pour la purification de la Maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Et les Prêtres entrèrent dans l\'intérieur de la Maison de l\'Éternel, et toutes les souillures qu\'ils trouvèrent dans le Temple de l\'Éternel, ils les tirèrent dans le parvis de la Maison de l\'Éternel; et les Lévites les enlevèrent pour les mener dehors au torrent du Cédron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Et ils commencèrent la sanctification le premier jour du premier mois, et le huitième jour du mois ils arrivèrent au vestibule de l\'Éternel; et employèrent huit jours à la purification du Temple de l\'Éternel; et le seizième jour du premier mois ils avaient terminé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Alors ils entrèrent dans l\'intérieur chez le roi Ézéchias et dirent: Nous avons purifié tout le Temple de l\'Éternel, et l\'autel des holocaustes et tous ses ustensiles, et la table des pains de présentation et tous ses ustensiles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'et toute la vaisselle profanée par le roi Achaz pendant son règne dans sa rébellion, nous l\'avons mise en état et sanctifiée: et la voilà devant l\'autel de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Alors le roi Ézéchias dès le matin assembla les chefs de la ville et monta au Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Et ils offrirent sept taureaux et sept béliers et sept agneaux et sept boucs en expiation pour le royaume et pour le Sanctuaire et pour Juda. Et il ordonna aux Prêtres, fils d\'Aaron, de sacrifier sur l\'autel de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Alors les Prêtres égorgèrent les taureaux dont ils reçurent le sang, et ils en aspergèrent l\'autel, et ils égorgèrent les béliers et avec leur sang aspergèrent l\'autel, et ils égorgèrent les agneaux et avec leur sang aspergèrent l\'autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Et ils amenèrent les boucs expiatoires devant le roi et l\'Assemblée, qui imposèrent leurs mains sur eux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'et les Prêtres les égorgèrent, et avec leur sang firent l\'expiation sur l\'autel, en propitiation pour tout Israël; car c\'était pour tout Israël que le roi avait ordonné l\'holocauste et l\'expiation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Et il fit tenir les Lévites dans le Temple de l\'Éternel avec des cymbales et des harpes et des luths selon l\'ordre de David et de Gad, Voyant du roi, et de Nathan, le prophète; car l\'ordre avait été donné par l\'Éternel, par ses prophètes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Et les Lévites étaient là avec les instruments de David, et les Prêtres avec les trompettes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Et Ézéchias ordonna d\'offrir des holocaustes sur l\'autel, et quand commençait l\'holocauste, commençait le chant de l\'Éternel, et les trompettes et l\'accompagnement, des instruments de David, roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Et toute l\'Assemblée se prosterna, et le chant retentit, et les trompettes sonnèrent, le tout jusqu\'à la consommation de l\'holocauste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Et quand l\'holocauste fut achevé, le roi et tous ceux qui se trouvaient avec lui, s\'inclinèrent et adorèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Et le roi Ézéchias et les chefs dirent aux Lévites de louer l\'Éternel avec les paroles de David et d\'Asaph, le Voyant. Et ils louèrent avec allégresse et s\'inclinèrent et adorèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Et Ézéchias prit la parole et dit: Maintenant vous vous êtes consacrés à l\'Éternel, approchez et amenez des victimes et des sacrifices d\'actions de grâces au Temple de l\'Éternel. Alors l\'Assemblée amena des victimes et des sacrifices pacifiques, et tout homme généreux des holocaustes volontaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Et voici le nombre des victimes offertes par l\'Assemblée: soixante-dix taureaux, cent béliers, deux cents agneaux, tout autant d\'holocaustes à l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'et six cents bœufs, et trois mille moutons furent consacrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Seulement les Prêtres étaient trop peu nombreux, et ils ne pouvaient écorcher toutes les victimes; alors ils furent aidés par leurs frères les Lévites jusqu\'à ce que l\'opération fût terminée, et que les [autres] Prêtres se fussent mis en état de sainteté, car les Lévites avaient été plus scrupuleux que les Prêtres pour se mettre en état de sainteté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Mais aussi il y avait là une multitude d\'holocaustes en même temps que les graisses des victimes pacifiques et les libations des holocaustes. Et ainsi fut restauré le service du Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Et Ézéchias et tout le peuple se réjouirent de ce que Dieu avait donné la disposition au peuple; car la chose s\'était faite promptement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Et Ézéchias envoya dans tout Israël et Juda et adressa aussi des rescrits à Éphraïm et Manassé pour qu\'ils vinssent au Temple de l\'Éternel à Jérusalem faire une Pâque à l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Et le roi et ses princes et toute l\'Assemblée de Jérusalem furent d\'avis de faire la Pâque au second mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Car ils ne pouvaient la faire à ce moment, les Prêtres ne s\'étant pas encore mis en état de sainteté en nombre suffisant, et la nation n\'étant pas réunie dans Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Et l\'avis eut l\'agrément du roi et de toute l\'Assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Et ils statuèrent qu\'on ferait publier dans tout Israël, de Béerséba à Dan, qu\'on eût à venir faire une Pâque à l\'Éternel, Dieu d\'Israël, à Jérusalem, car ils ne l\'avaient pas célébrée en nombre conformément à l\'Écriture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Et les coureurs allèrent avec les rescrits émanant du roi et de ses princes dans tout Israël et Juda, et d\'après l\'ordre du roi ils dirent: Enfants d\'Israël, revenez à l\'Éternel, Dieu d\'Abraham, d\'Isaac et d\'Israël, afin qu\'il revienne à votre reste échappé aux mains des rois d\'Assyrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Et n\'imitez pas vos pères et vos frères qui ont été infidèles à l\'Éternel, Dieu de leurs pères, et qu\'il a livrés à la désolation, comme vous le voyez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Maintenant ne roidissez pas votre col comme vos pères, donnez la main à l\'Éternel et venez à son Sanctuaire qu\'il a sanctifié pour l\'éternité, et soumettez-vous à l\'Éternel, votre Dieu, pour que se détourne de vous l\'ardeur de sa colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Car si vous revenez à l\'Éternel, vos frères et vos fils seront l\'objet de la compassion de leurs ravisseurs, et pourront revenir dans ce pays; car l\'Éternel, votre Dieu, est clément et miséricordieux, et Il ne détournera pas son visage de vous, si vous vous retournez vers Lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Et les coureurs passèrent de ville en ville dans le pays d\'Ephraïm et de Manassé et jusqu\'à Zabulon; mais l\'on se rit d\'eux et l\'on se moqua d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Cependant il y eut des hommes de Asser et de Manassé et de Zabulon qui s\'humilièrent et vinrent à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Juda aussi sentit la main de Dieu qui leur donna un même cœur pour exécuter l\'ordre du roi et des princes conforme à la parole de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Et il se réunit à Jérusalem un peuple nombreux pour faire la fête des azymes au second mois, assemblée immense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Et ils se mirent en devoir de faire disparaître les autels qui étaient dans Jérusalem, et toutes les tables à encenser, et ils les jetèrent dans le torrent du Cédron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Et ils immolèrent la Pâque le quatorzième jour du second mois; et les Prêtres et les Lévites avaient eu honte, et s\'étaient mis en état de sainteté, et ils offrirent des holocaustes dans le Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Et ils se tenaient à leur poste, suivant leur règle, d\'après la Loi de Moïse, homme de Dieu, les Prêtres faisant l\'aspersion du sang qu\'ils recevaient des mains des Lévites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Comme il y avait beaucoup de gens dans l\'Assemblée qui ne s\'étaient pas mis en état de sainteté, les Lévites se chargèrent d\'immoler les agneaux de Pâque pour tous ceux qui n\'étaient pas purs, et ils les consacraient à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'En effet, une grande quantité de gens d\'Éphraïm et de Manassé et d\'Issaschar et de Zabulon ne s\'étaient pas purifiés, mais mangeaient la Pâque contrairement à l\'Écriture. Mais Ézéchias avait intercédé pour eux par cette prière: Que l\'Éternel, le Dieu bon, pardonne');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'à tous ceux qui ont dirigé leur cœur à la recherche du Dieu, l\'Éternel, Dieu de leurs pères, sans avoir toutefois pratiqué la sainte purification.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Et l\'Éternel exauça Ézéchias et pardonna au peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Ainsi fut célébrée par les enfants d\'Israël présents à Jérusalem la fête des azymes pendant sept jours en grande allégresse, et chaque jour les Lévites et les Prêtres louaient l\'Éternel avec les instruments de la louange de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Et Ézéchias adressa des encouragements à tous les Lévites qui se montraient habiles dans la belle science [du culte] de l\'Éternel, et ils mangèrent l\'aliment festal pendant sept jours, en offrant des sacrifices pacifiques et louant l\'Éternel, Dieu de leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Et toute l\'Assemblée fut d\'avis de fêter sept autres jours, et ils fêtèrent [encore] sept jours dans la joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Car Ézéchias, roi de Juda, offrit à l\'Assemblée mille taureaux et sept mille moutons, et les princes offrirent à l\'Assemblée mille taureaux et dix mille moutons; et les Prêtres en masse s\'étaient mis en état de sainteté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Et toute l\'Assemblée de Juda et les Prêtres et les Lévites et toute l\'Assemblée venue d\'Israël et les étrangers venus du pays d\'Israël ou établis en Juda, se réjouirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Et il y eut grande réjouissance à Jérusalem, car depuis l\'époque de Salomon, fils de David, roi d\'Israël, il n\'y avait rien eu de pareil à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Et les Prêtres et les Lévites se levèrent et bénirent le peuple, et leur voix fut écoutée et leur prière parvint à Sa résidence sainte dans les Cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Et, toutes ces choses accomplies, tous les Israélites présents partirent pour les villes de Juda, et ils brisèrent les colonnes, coupèrent les Aschères et détruisirent les tertres et les autels dans tout Juda et Benjamin et dans Éphraïm et Manassé, jusqu\'à ruine complète; puis tous les enfants d\'Israël retournèrent chacun dans sa propriété, dans leurs villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Et Ézéchias établit les classes des Prêtres et des Lévites, selon leur classification, chacun selon son office, les Prêtres et les Lévites pour les holocaustes et les sacrifices pacifiques, pour le ministère et l\'action de grâces et la louange, aux portes du camp de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Et le roi affecta une portion de son bien aux holocaustes, aux holocaustes du matin et du soir et aux holocaustes des sabbats et des nouvelles lunes et des fêtes prescrites dans la Loi de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Et le roi dit au peuple, aux habitants de Jérusalem, de payer la part des Prêtres et des Lévites pour les mettre à même de s\'appliquer à la Loi de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Et à la promulgation de cet édit les enfants d\'Israël apportèrent en abondance les prémices du blé, du moût et de l\'huile et du miel et de toutes les productions du sol, et ils apportèrent en masse les dîmes de toutes choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Et les enfants d\'Israël et de Juda domiciliés dans les villes de Juda, apportèrent eux aussi la dîme du gros et du menu bétail et la dîme des consécrations qui avaient été consacrées à l\'Éternel, leur Dieu, et en firent des tas et des tas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Au troisième mois ils commencèrent à former des tas, et ils eurent achevé au septième mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Et vinrent Ézéchias et les princes, qui à la vue des tas bénirent l\'Éternel et son peuple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Et Ézéchias consulta les Prêtres et les Lévites touchant les tas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Alors le Grand-Prêtre, Azaria, de la maison de Tsadoc, lui parla et dit: Depuis qu\'on a commencé à apporter les dons dans le Temple de l\'Éternel, nous avons mangé, et nous avons été rassasiés, et le reliquat est considérable; car l\'Éternel a béni son peuple, et le reliquat, c\'est le grand tas que voilà.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Et Ézéchias dit de disposer des cellules dans la Maison de l\'Éternel. Et ils les disposèrent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'et y apportèrent fidèlement les prémices et les dîmes et les consécrations. Et ils eurent pour surintendant Chanania, le Lévite, avec Siméï son frère, comme second.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Et Jehiel et Azazia et Nahath et Asahel et Jerimoth et Jozabad et Eliel et Jismachia et Mahath et Benaïa étaient intendants sous les ordres de Chanania et de Siméï, son frère, d\'après l\'ordonnance du roi Ezéchias, et d\'Azaria, surintendant de la Maison de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Et Coré, fils de Jimna, Lévite, portier de l\'orient, avait l\'intendance des dons volontaires faits à Dieu, pour délivre la part réservée de l\'Éternel, et les très saintes consécrations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Et sous ses ordres étaient Eden et Miniamin et Jésua et Semaïa, Amaria et Sechonia dans les villes sacerdotales, laissés sur leur foi pour faire les délivrances à leurs frères selon leurs classes, au grand comme au petit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'non compris les mâles enregistrés dès l\'âge de trois ans et au-dessus, tous ceux qui entraient journellement dans le Temple de l\'Éternel pour les fonctions de leur office, dans leurs classes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'non compris les Prêtres enregistrés par maisons patriarcales, et les Lévites de vingt ans et plus en fonctions dans leurs classes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'et tous les leurs enregistrés, enfants, femmes et fils et filles, de toute la corporation, car ils se consacraient fidèlement à leur saint service.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Et pour les Prêtres, fils d\'Aaron, il y avait dans la banlieue de leurs villes, ville par ville, des hommes préposés, désignés par leurs noms, pour délivrer leur part à tous les mâles des Prêtres et à tous les Lévites enregistrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Et ainsi fit Ezéchias dans tout Juda et il agit bien et avec droiture et fidélité devant l\'Éternel, son Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'et dans toute l\'œuvre qu\'il entreprit pour le service de la Maison de Dieu, et pour la Loi et pour le commandement, cherchant son Dieu, il agit de tout son cœur et réussit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Après ces faits et ces actes de fidélité [d\'Ézéchias], parut Sanchérib, roi d\'Assyrie, et il envahit Juda et assiégea les places fortes et parlait de s\'y ouvrir la brèche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Et Ezéchias voyant que Sanchérib était venu et projetait d\'attaquer Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'il décida avec ses chefs et ses braves d\'obstruer les sources d\'eau qui sont en dehors de la ville, et ils l\'aidèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Et il y eut concours d\'une grande foule de gens qui obstruèrent toutes les sources et le cours d\'eau qui arrose le milieu de la contrée, et disaient: Pourquoi faudrait-il que les rois d\'Assyrie vinssent et trouvassent des eaux abondantes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Et il prit courage et releva tous les murs écroulés et les éleva jusqu\'aux tours, et en dehors il construisit un autre mur, et fortifia Millo, Cité de David, et fit quantité de projectiles et boucliers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Et il préposa des chefs militaires sur le peuple, et les assembla auprès de lui dans la place à la porte de la ville et leur parla affectueusement en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Courage et fermeté! N\'ayez ni crainte ni appréhension du roi d\'Assyrie, non plus que de toute la multitude qu\'il a avec lui! car nous, nous avons avec nous plus que lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Avec lui est un bras de chair, et avec nous, l\'Éternel, notre Dieu, pour nous être en aide et combattre notre combat. Et le peuple s\'assura sur les paroles d\'Ézéchias, roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Sur ces entrefaites Sanchérib, roi d\'Assyrie, envoya ses serviteurs à Jérusalem (lui-même étant devant Lachis, ayant avec lui toutes les forces de son empire) vers Ezéchias, roi de Juda, et vers tout le monde de Juda qui était à Jérusalem, pour dire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Ainsi parle Sanchérib, roi d\'Assyrie: En quoi vous confiez-vous, et pourquoi restez-vous bloqués dans Jérusalem?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'N\'êtes-vous pas les dupes d\'Ézéchias qui vous mène à la mort par la famine et la soif, quand il dit: L\'Éternel, notre Dieu, nous tirera des mains du roi d\'Assyrie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'N\'est-ce pas Ezéchias qui a aboli ses tertres et ses autels, et fait cette injonction à Juda et à Jérusalem: Devant l\'unique autel vous adorerez et offrirez l\'encens?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Ne savez-vous pas ce que moi et mes pères avons fait à tous les peuples des pays divers? Les dieux des nations des pays divers ont-ils été capables de sauver leurs pays de ma main?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'De tous ces dieux des nations anéantis par mes pères lequel est-ce qui a pu sauver son peuple de ma main, pour que votre Dieu puisse vous en sauver?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Eh bien! donc, ne soyez pas les dupes d\'Ézéchias, et ne vous laissez pas leurrer de la sorte, et ne le croyez pas! Car aucun dieu d\'aucune nation ni royaume n\'a su sauver son peuple de ma main et de celles de mes pères combien moins votre Dieu vous sauverait-il de ma main?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Et plus encore en dirent ses serviteurs contre Dieu, l\'Éternel, et contre Ézéchias, son serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Et il écrivit une lettre pour outrager l\'Éternel, Dieu d\'Israël, et l\'attaquer par ses discours, en disant: De même que les dieux des nations des pays divers qui n\'ont pu sauver leur peuple de ma main, de même le Dieu d\'Ézéchias ne sauvera pas son peuple de ma main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Et ils crièrent à voix forte en hébreu au peuple de Jérusalem assis sur le mur, pour les effrayer et les épouvanter, à l\'effet de venir à bout de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Et ils parlèrent du Dieu de Jérusalem comme des dieux des peuples de la terre, ouvrages de mains d\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Et sur cela, le roi Ezéchias fut en prière ainsi que Ésaïe, fils d\'Atmos, le prophète, et ils crièrent au ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Alors l\'Éternel envoya un ange qui fit périr tous les guerriers et princes et généraux dans le camp du roi d\'Assyrie, qui retourna la honte au front dans son pays. Et comme il entrait dans le temple de son dieu, [les fils] sortis de ses entrailles l\'y firent périr par l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Ainsi l\'Éternel sauva Ézéchias et les habitants de Jérusalem de la main de Sanchérib, roi d\'Assyrie, et de la main de tous, et les mit en sûreté de toutes parts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Et un grand nombre apportèrent des offrandes à l\'Éternel, à Jérusalem, et des objets de prix à Ézéchias, roi de Juda, qui dorénavant fut éminent aux yeux de toutes les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'Dans ces mêmes temps Ézéchias fut malade à la mort, et il fit sa prière à l\'Éternel, qui l\'exauça et lui accorda un prodige.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Mais Ézéchias ne fut pas reconnaissant en raison du bienfait dont il était l\'objet, car son cœur s\'éleva; ce qui attira de la colère sur lui et sur Juda et Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Alors Ézéchias s\'humilia de l\'orgueil de son cœur, lui et les habitants de Jérusalem, et la colère de l\'Éternel n\'éclata pas sur eux du vivant d\'Ézéchias.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Et Ézéchias eut richesse et gloire en grande abondance; et il se fit des trésors pour l\'argent et l\'or et les pierres précieuses et les aromates et les boucliers et toutes sortes de vases précieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'et des magasins pour les produits en blé et moût et huile, et des râteliers pour toute espèce de bestiaux et des parcs pour les troupeaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Et il se créa des villes et des troupeaux de menu et de gros bétail, en quantité, car Dieu lui avait accordé des biens très considérables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Et ce même Ézéchias boucha l\'issue supérieure de l\'eau de Gihon qu\'il conduisit en bas à l\'occident de la Cité de David. Et Ézéchias réussit dans toutes ses entreprises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Et en conséquence lors des messages des princes de Babel qui députèrent vers lui pour s\'enquérir du miracle arrivé dans le pays, Dieu l\'abandonna pour l\'éprouver afin de connaître tout son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Le reste des actes d\'Ézéchias et ses actions pieuses sont d\'ailleurs consignés dans la Vision d\'Ésaïe, fils d\'Amots, le prophète, dans le livre des rois de Juda et d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Et Ézéchias reposa à côté de ses pères, et reçut la sépulture sur l\'éminence des tombeaux des fils de David, et dans sa mort il fut l\'objet de témoignages magnifiques de la part de tout Juda et des habitants de Jérusalem. Et Manassé, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manassé avait douze ans à son avènement et il régna cinquante-cinq ans à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Et il fit ce qui est mal aux yeux de l\'Éternel, imitant les abominations des nations que l\'Éternel avait chassées devant les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Et il releva les tertres qu\'Ézéchias, son père, avait renversés, et érigea des autels aux Baals, et fit des Astartés et adora toute l\'armée des Cieux et lui rendit un culte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Et il bâtit des autels dans le Temple de l\'Éternel, dont l\'Éternel avait dit: A Jérusalem sera mon Nom éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Et il bâtit des autels a toute l\'armée des Cieux dans les deux parvis du Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Et il fit passer ses fils par le feu dans la Vallée des fils de Hinnom, et pratiqua la magie, les augures et les évocations, et institua des évocateurs et des pronostiqueurs et il fit le mal à l\'extrême aux yeux de l\'Éternel, à l\'effet de le provoquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Et il plaça le simulacre sculpté qu\'il avait fait, dans le Temple de Dieu, dont Dieu avait dit à David et à Salomon, son fils: Dans ce Temple-ci, et à Jérusalem que j\'ai choisie sur toutes les Tribus d\'Israël, je mettrai Mon Nom pour l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Et je ne laisserai plus le pied d\'Israël quitter le sol que j\'ai assuré à vos pères, pourvu seulement qu\'ils veillent à pratiquer tout ce que par l\'organe de Moïse je leur ai prescrit, toute la Loi, et les statuts et les arrêts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Mais Manassé égara Juda et les habitants de Jérusalem au point qu\'ils firent pis que les nations que l\'Éternel avait exterminées devant les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Et l\'Éternel parla à Manassé et à son peuple, mais ils n\'y prirent pas garde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Alors l\'Éternel les fit envahir par les généraux d\'armée du roi d\'Assyrie, qui avec des ceps firent Manassé prisonnier et le lièrent avec des chaînes et le menèrent à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Et dans la gêne où il était, il chercha à fléchir l\'Éternel, son Dieu, et s\'humilia profondément devant le Dieu de ses pères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'et lui adressa sa prière, et Dieu se laissa fléchir et exauça sa prière et le fit revenir à Jérusalem dans son royaume, et Manassé reconnut que l\'Éternel est Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Et ensuite il bâtit un mur extérieur à la Cité de David, à l\'occident de Gihon dans le ravin, et à l\'avenue de la porte des Poissons, et lui fit contourner Ophel, et l\'éleva très haut, et il plaça des commandants militaires dans toutes les places fortes de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Et il fit disparaître les dieux de l\'étranger et le simulacre, du Temple de l\'Éternel, et tous les autels qu\'il avait bâtis sur la montagne du Temple de l\'Éternel et à Jérusalem, et les jeta en dehors de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Et il releva l\'autel de l\'Éternel et y offrit des sacrifices pacifiques et d\'actions de grâces et enjoignit à Juda de servir l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Cependant le peuple sacrifiait encore sur les tertres, mais seulement à l\'Éternel, leur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Le reste des actes de Manassé et sa prière à son Dieu, et les discours des Voyants qui lui parlèrent au nom de l\'Éternel, Dieu d\'Israël, sont d\'ailleurs consignés dans les histoires des rois d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'et sa prière et son exaucement et tout son péché et sa rébellion et les lieux où il avait construit des tertres et érigé des Astartés et des idoles, avant de s\'être humilié, tout cela se trouve consigné dans les Histoires de Hozaï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Et Manassé reposa à côté de ses pères et reçut la sépulture dans sa demeure, et Amon, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Amon avait vingt-deux ans à son avènement, et il régna deux ans à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Et il fit ce qui est mal aux yeux de l\'Éternel comme avait fait Manassé, son père, et Amon offrit des sacrifices à toutes les idoles qu\'avait faites Manassé, son père, et leur rendit un culte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Mais il ne s\'humilia pas devant l\'Éternel, comme s\'était humilié Manassé, son père; car lui, Amon, se rendit beaucoup plus coupable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Et ses serviteurs conjurèrent contre lui et le tuèrent dans son palais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Cependant le peuple du pays fit main basse sur tous ceux qui avaient conjuré contre le roi Amon, et établit Josias, son fils, roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Josias avait huit ans a son avènement et il régna trente-un ans à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Et il fit ce qui est bien aux yeux de l\'Éternel, et il marcha sur les errements de David, son père, sans en dévier ni à droite ni à gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Et dans la huitième année de son règne, comme il était encore enfant, il commença à chercher le Dieu de David, son père; et la douzième année, il commença à purger Juda et Jérusalem des tertres et des Astartés, et des idoles et sculptées et coulées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Et l\'on renversa sous ses yeux les autels des Baals, et il en abattit les colonnes solaires qui étaient dessus, et il mit en pièces et broya les Astartés et les idoles sculptées et coulées, et en sema la poussière sur les tombeaux de ceux qui leur avaient sacrifié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Et il brûla les ossements des prêtres sur leurs autels, et ainsi purifia Juda et Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Et dans les villes de Manassé et d\'Éphraïm et de Siméon jusqu\'en Nephthali, il fit des fouilles générales dans leurs maisons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'Et il renversa les autels, et il brisa et broya les Astartés et les idoles et abattit toutes les colonnes solaires dans tout le territoire d\'Israël. Puis il retourna à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Et dans la dix-huitième année de son règne, pour la purification du pays et du Temple il délégua Saphan, fils d\'Atsalia, et Maaseïa, préfet de la ville, et Joah, fils de Joachaz, le Chancelier, pour réparer le Temple de l\'Éternel, son Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Et ils se rendirent chez Hilkia, le Grand-Prêtre, où on leur donna l\'argent rentré au Temple de Dieu, lequel avait été recueilli par les Lévites, gardes du seuil, dans Manassé et Éphraïm et dans tout le reste d\'Israël, et dans tout Juda et Benjamin, et chez les habitants de Jérusalem;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'et ils le remirent entre les mains des entrepreneurs préposés dans le Temple de l\'Éternel; et les entrepreneurs occupés dans le Temple de l\'Éternel le délivrèrent pour la réparation et la restauration du Temple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'et ils en payèrent les charpentiers et les maçons pour l\'achat de pierres de taille et de bois pour les architraves et pour la charpente des maisons qu\'avaient détériorées les rois de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Et ces hommes agirent avec bonne foi dans le travail. Et ils eurent au-dessus d\'eux Jahath et Obadia, Lévites, des fils de Merari, et Zacharie et Mesullam des fils des Cahathites, pour les inspecter, et les Lévites, tous habiles musiciens;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'ils étaient aussi préposés sur les porte-faix, et inspecteurs de tous les ouvriers occupés à tout genre de travail, et il y avait des Lévites secrétaires, officiers et portiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Et comme ils sortaient l\'argent entré au Temple de l\'Éternel, le Prêtre Hilkia trouva le livre de la Loi de l\'Éternel par Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Alors Hilkia prit la parole et dit à Saphan, le Secrétaire: J\'ai trouvé dans le Temple de l\'Éternel le livre de la Loi! et Hilkia remit le livre à Saphan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Et Saphan apporta le livre au roi, et fit aussi rapport au roi en ces termes: Tout ce qui a été remis aux soins de tes serviteurs, ils l\'exécutent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Et ils déboursèrent l\'argent trouvé dans le Temple de l\'Éternel et le délivrèrent aux préposés et aux ouvriers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Et Saphan, le Secrétaire, informa le roi en ces termes: Le Prêtre Hilkia m\'a remis un livre! et Saphan y lut devant le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Et lorsque le roi ouït les paroles de la Loi, il déchira ses vêtements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Et le roi donna ses ordres à Hilkia et à Ahikam, fils de Saphan, et à Abdon, fils de Michée, et à Saphan, le Secrétaire, et à Asaïa, serviteur du roi, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Allez consulter l\'Éternel pour moi et pour les restants en Israël et Juda touchant les paroles du livre trouvé, car grande est la colère de l\'Éternel allumée contre nous, parce que nos pères n\'ont pas gardé la parole de l\'Éternel pour se conformer à tout ce qui est écrit dans ce livre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Alors Hilkia, avec les hommes [désignés par] le roi, se rendit chez Hulda, la prophétesse, femme de Sallum, fils de Thokehath, fils de Hasrah, garde du vestiaire, (or elle habitait à Jérusalem dans l\'autre quartier) et ils lui parlèrent dans ce sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Et elle leur dit: Ainsi parle l\'Éternel, Dieu d\'Israël: Dites à l\'homme qui vous a envoyés chez moi:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Ainsi parle l\'Éternel: Voici, je veux amener la calamité sur ce lieu et sur ses habitants, toutes les malédictions consignées dans le livre dont on a fait lecture devant le roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Puisqu\'ils m\'ont abandonné, et ont brûlé de l\'encens à d\'autres dieux, à l\'effet de me provoquer par tous les ouvrages de leurs mains, ma colère s\'épanchera sur ce lieu et ne s\'éteindra point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Mais au roi de Juda qui vous a envoyés pour consulter l\'Éternel, parlez-lui en ces termes: Ainsi parle l\'Éternel, Dieu d\'Israël: Quant aux paroles que tu as entendues...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'puisque ton cœur est délicat, et qu\'il s\'est humilié devant Dieu, lorsque tu as entendu ses menaces contre ce lieu et ses habitants, et que tu t\'es humilié devant moi, et as déchiré tes habits et pleuré devant moi, de mon côté j\'ai aussi entendu, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Voici, je te recueillerai auprès de tes pères et tu seras recueilli dans tes tombeaux en paix, et tes yeux ne verront pas toute la calamité que j\'amène sur ce lieu et sur ses habitants. Et ils rendirent au roi la réponse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Alors le roi envoya convoquer tous les Anciens de Juda et de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Et le roi monta au Temple de l\'Éternel, ainsi que tous les hommes de Juda, et les habitants de Jérusalem, et les Prêtres et les Lévites et tout le peuple, grands et petits, et il lut à leurs oreilles toutes les paroles du livre de l\'alliance trouvé dans le Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Et le roi, debout sur son estrade, solennisa devant l\'Éternel l\'engagement de suivre l\'Éternel et de garder de tout son cœur et de toute son âme, et ses commandements et ses ordonnances et ses statuts pour exécuter les clauses de l\'alliance consignées dans ce livre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Et il engagea tous ceux qui se rencontraient à Jérusalem et en Benjamin; et les habitants de Jérusalem agirent conformément à l\'alliance de Dieu, Dieu de leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Et Josias fit disparaître toutes les abominations de toutes les terres appartenant aux enfants d\'Israël, et il astreignit tous ceux qui se trouvaient en Israël, au service de l\'Éternel, leur Dieu; tant qu\'il vécut, ils ne se détachèrent point de l\'Éternel, Dieu de leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Et Josias fit à Jérusalem une Pâque à l\'Éternel, et on immola la Pâque le quatorzième jour du premier mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Et il établit les Prêtres dans leurs fonctions et les encouragea pour le service du Temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Et il dit aux Lévites qui enseignaient tout Israël, étant consacrés à l\'Éternel: Placez l\'Arche sainte dans le Temple bâti par Salomon, fils de David, roi d\'Israël; vous n\'avez plus à en charger votre épaule. Maintenant servez l\'Éternel, votre Dieu, et son peuple d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'et tenez-vous prêts, par maison patriarcale et par classe, suivant le rescrit de David, roi d\'Israël, et suivant le rescrit de Salomon, son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Et tenez-vous dans le Sanctuaire selon les sections des maisons patriarcales de vos frères, des fils du peuple, et selon la classification de la maison patriarcale des Lévites;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'et immolez la Pâque et mettez-vous dans l\'état de sainteté, et préparez-la à vos frères pour vous conformer à la parole de l\'Éternel prononcée par l\'organe de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Et Josias fit pour les enfants du peuple un don d\'agneaux et de chevreaux (le tout pour victimes pascales pour tous ceux qui étaient présents) au nombre de trente mille et de trois mille taureaux, le tout pris dans la propriété du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Et les princes firent un don spontané au peuple, aux Prêtres et aux Lévites. Hilkia et Zacharie et Jehiel, primiciers de la Maison de Dieu, donnèrent au peuple pour victimes pascales deux mille six cents [agneaux] et trois cents bœufs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Et Chanania et Semaïa et Nethaneël, ses frères et Hasabia et Jehiel et Jozabad, chefs des Lévites, firent aux Lévites pour victimes pascales un don de cinq mille agneaux et de cinq cents bœufs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Ainsi fut organisé le service, et les Prêtres se placèrent à leur poste, et les Lévites d\'après leurs classes, suivant l\'ordre du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Et [les Lévites] immolèrent la Pâque et les Prêtres firent l\'aspersion avec le sang reçu de leurs mains, et les Lévites dépouillèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Et ils mirent à part les holocaustes pour les distribuer aux sections des maisons patriarcales des enfants du peuple pour les sacrifier à l\'Éternel selon ce qui est écrit dans le livre de Moïse; et de même quant aux taureaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Et ils firent rôtir la Pâque au feu selon le rite, et les quartiers consacrés ils les firent cuire dans des marmites, des chaudières et des poêles, et de suite les distribuèrent à tous les enfants du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Et ensuite ils apprêtèrent pour eux et les Prêtres, car les Prêtres, fils d\'Aaron, assistèrent au sacrifice des holocaustes et des graisses jusque dans la nuit; les Lévites apprêtèrent donc pour eux et les Prêtres, fils d\'Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Et les chantres, fils d\'Asaph, étaient à leur poste selon l\'ordre de David et d\'Asaph et d\'Heiman et de Jeduthun, Voyant du roi, et les portiers à chaque porte; ils n\'avaient pas à interrompre leur service, parce que leurs frères, les Lévites, apprêtaient pour eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Ainsi fut organisé tout le service de l\'Éternel en cette journée pour immoler la Pâque et offrir les holocaustes sur l\'autel de l\'Éternel, selon l\'ordre du roi Josias.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Et les enfants d\'Israël, présents, célébrèrent la Pâque en ce temps-là et la fête des azymes pendant sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Et il ne s\'était pas célébré de Pâque pareille en Israël depuis l\'époque de Samuel, le prophète, et de tous les rois d\'Israël aucun n\'avait célébré une Pâque pareille à la Pâque célébrée par Josias, et les Prêtres et les Lévites et tout Juda et Israël, présents, et les habitants de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Ce fut dans la dix-huitième année du règne de Josias que cette Pâque fut célébrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Après tout cela, comme Josias avait mis en état le Temple, s\'avança Nécho, roi d\'Egypte, pour attaquer Charchemis sur l\'Euphrate, et Josias marcha à sa rencontre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Et il envoya à celui-ci des messagers pour lui dire: Qu\'ai-je à démêler avec toi, roi de Juda? Ce n\'est pas à toi que j\'en veux, pas à toi aujourd\'hui, mais c\'est à une [autre] maison que je porte la guerre, et Dieu a dit que je dois me hâter. Ne t\'attaque donc pas au Dieu qui est avec moi, de peur qu\'il ne t\'écrase.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Mais Josias ne détourna point sa face de lui, au contraire, pour en venir aux mains avec lui, il se travestit, sans écouter les discours de Nécho, qui émanaient de la bouche de Dieu, et il se présenta au combat dans la vallée de Megiddo.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Et les tireurs tirèrent sur le roi Josias, et le roi dit à ses serviteurs: Emmenez-moi, car je suis grièvement blessé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Et ses serviteurs l\'enlevèrent de son char, et le transportèrent sur son second char et l\'amenèrent à Jérusalem. Et il mourut, et il reçut la sépulture dans les tombeaux de ses pères, et tout Juda et Jérusalem célébrèrent le deuil de Josias.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Et Jérémie composa une complainte sur Josias. Et tous les chantres et toutes les chanteresses ont fait mention de Josias dans leurs complaintes jusqu\'aujourd\'hui, et en établirent la coutume en Israël; elles sont d\'ailleurs transcrites dans Les Complaintes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Le reste des actes de Josias et ses actions pieuses conformes à ce qui est écrit dans la Loi de l\'Éternel, et ses faits,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'les premiers et les derniers, sont d\'ailleurs consignés dans le livre des rois d\'Israël et de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Et le peuple du pays prit Joachaz, fils de Josias, et le fit roi en la place de son père à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Joachaz avait vingt-trois ans à son avènement, et il régna trois mois à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Et le roi d\'Égypte le destitua à Jérusalem et frappa le pays d\'une amende de cent talents d\'argent et un talent d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Et le roi d\'Egypte fit son frère Eliakim roi de Juda et de Jérusalem et changea son nom en celui de Jojakim, et Nécho fit prisonnier son frère Joachaz et le mena en Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Jojakim avait vingt-cinq ans à son avènement, et il régna onze ans à Jérusalem. Et il fit ce qui est mal aux yeux de l\'Éternel, son Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Contre lui s\'avança Nebucadnetsar, roi de Babel, qui le lia de chaînes pour le mener à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Nebucadnetsar emporta aussi à Babel de la vaisselle du Temple de l\'Éternel, et la plaça dans son temple à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Le reste des actes de Jojakim, et ses abominations, auxquelles il s\'adonna, et ce qui se trouvait en lui, cela est d\'ailleurs consigné dans le livre des rois d\'Israël et de Juda. Et Jojachin, son fils, devint roi en sa place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Jojachin avait [dix-] huit ans à son avènement, et il régna trois mois et dix jours à Jérusalem. Et il fit ce qui est mal aux yeux de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Et l\'année étant révolue, le roi Nebucadnetsar l\'envoya chercher pour l\'amener à Babel avec de la vaisselle précieuse du Temple de l\'Éternel, et fit Sédécias, son frère, roi de Juda et de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Sédécias avait vingt-un ans à son avènement, et il régna onze ans à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Et il fit ce qui est mal aux yeux de l\'Éternel, son Dieu; il ne s\'humilia point devant Jérémie, le prophète, interprète de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Et il se rebella aussi contre le roi Nebucadnetsar, qui l\'avait assermenté au nom de Dieu, et il eut le col trop roide, et le cœur trop dur pour revenir à l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Tous les chefs des Prêtres aussi et le peuple accumulèrent les transgressions imitant toutes les abominables pratiques des nations, et souillèrent le Temple de l\'Éternel dont Il avait fait un lieu saint à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Et l\'Éternel, Dieu de leurs pères, leur adressa des messages par l\'organe de ses envoyés, que dès le matin déléguait; car Il voulait épargner son peuple et sa résidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Mais ils se moquèrent des envoyés de Dieu, et méprisèrent leurs avis et se rirent de ses prophètes, jusqu\'à ce qu\'enfin monta le courroux de l\'Éternel contre son peuple pour lequel il n\'y eut plus de salut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Alors il fit marcher contre eux le roi des Chaldéens, qui tua leurs jeunes hommes avec l\'épée dans leur Sanctuaire et n\'épargna ni l\'adolescent, ni la vierge, ni le vieillard et l\'homme caduc. Il livra tout entre ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Et tous les meubles de la Maison de Dieu, et les grands et les petits, et les trésors du Temple de l\'Éternel et les trésors du roi et de ses princes, il emmena tout à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Et ils incendièrent la Maison de Dieu et démolirent la muraille de Jérusalem et en livrèrent tous les palais aux flammes et exterminèrent tous les meubles de prix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Et il emmena à Babel les restants échappés a l\'épée, comme prisonniers; et ils lui furent asservis et à ses fils jusqu\'à l\'avènement de la monarchie des Perses,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'pour accomplir la menace de l\'Éternel, prononcée par la bouche de Jérémie, jusqu\'à ce que le pays eût satisfait à ses Sabbats; il y satisfit tout le temps de la désolation jusqu\'à l\'accomplissement de soixante-dix années.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Et dans la première année de Cyrus, roi de Perse, afin que s\'accomplît la promesse de l\'Éternel faite par la bouche de Jérémie, l\'Éternel émut l\'esprit de Cyrus, roi de Perse, lequel fit publier de vive voix dans tout son empire, et aussi par un rescrit, ce message:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Ainsi parle Cyrus, roi de Perse: Tous les royaumes de la terre m\'ont été donnés par l\'Éternel, Dieu des Cieux, et il m\'a enjoint de lui édifier une Maison à Jérusalem en Juda. Qu\'avec tous ceux qui sont de son peuple, soit l\'Éternel, son Dieu, et qu\'ils partent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Et dans la première année de Cyrus, roi de Perse, pour que s\'accomplît la Parole de l\'Éternel émise par l\'organe de Jérémie, l\'Éternel émut l\'esprit de Cyrus, roi de Perse, lequel fit publier de vive voix dans tout son empire, et aussi par un rescrit, ce message:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Ainsi parle Cyrus, roi de Perse: Tous les royaumes de la terre m\'ont été donnés par l\'Éternel, Dieu des Cieux, et Il m\'a enjoint de lui édifier une Maison à Jérusalem en Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'A quiconque d\'entre vous est de son peuple, que son Dieu soit en aide, et qu\'il monte à Jérusalem en Juda pour construire la Maison de l\'Éternel, du Dieu d\'Israël, du Dieu de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Et à quiconque est resté, que dans tous les lieux où il a fixé son séjour, les gens du lieu lui donnent des secours en argent et en or, et en mobilier et en bétail, en même temps que des contributions spontanées pour la Maison du Dieu de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Alors se mirent en devoir les patriarches de Juda et de Benjamin, et les Prêtres et les Lévites, tous ceux dont Dieu émut l\'esprit, à l\'effet de se transporter pour construire la Maison de l\'Éternel à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Et tous leurs entours les pourvurent de vaisselle d\'argent, d\'or, de mobilier, de bétail et d\'objets précieux, non compris tous les dons spontanés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Et le roi Cyrus sortit la vaisselle du Temple de l\'Éternel, que Nebucadnetsar avait enlevée de Jérusalem et placée dans le temple de son Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Et Cyrus, roi de Perse, la délivra entre les mains de Mithredath, le trésorier, lequel en fit la remise à Sesbatsar (Zorobabel), prince de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Et en voici l\'état: trente bassins d\'or, mille bassins d\'argent, vingt-neuf couteaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'trente coupes d\'or, quatre cent dix coupes d\'argent de second aloi, mille autres vases.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Tous les vases d\'or et d\'argent étaient au nombre de cinq mille quatre cents. Tout cela Sesbatsar l\'emmena lors du transport des captifs de Babel à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Et ce sont ici les ressortissants de la province qui revinrent de l\'exil des déportés que Nebucadnetsar, roi de Babel, emmena captifs à Babel et qui rentrèrent à Jérusalem et en Juda, chacun dans sa ville,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'et vinrent avec Zorobabel: Jésuah, Néhémie, Seraïa, Reélia, Mordechaï, Bilsan, Mispar, Bigvaï, Rehum, Baëna; nombre des hommes du peuple d\'Israël:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'les fils de Paréos, deux mille cent soixante-douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'les fils de Sephatia, trois cent soixante-douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'les fils d\'Arach, sept cent soixante-quinze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'les fils de Pachath-Moab, des fils de Jésuah [et] de Joab, deux mille huit cent douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'les fils d\'Eilam, mille deux cent cinquante-quatre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'les fils de Zatthu, neuf cent quarante-cinq;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'les fils de Zaccaï, sept cent soixante;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'les fils de Bani, six cent quarante-deux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'les fils de Bébaï, six cent vingt-trois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'les fils de Azgad, mille deux cent vingt-deux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'les fils d\'Adonikam, six cent soixante-six;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'les fils de Bigvaï, deux mille cinquante-six;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'les fils d\'Adin, quatre cent cinquante-quatre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'les fils d\'Ater [de la famille d\'] Ezéchias, quatre-vingt-dix-huit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'les fils de Betsaï, trois cent vingt-trois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'les fils de Jorah, cent douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'les fils de Chasum, deux cent vingt-trois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'les fils de Gibbar, quatre-vingt-quinze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'les fils de Bethléhem, cent vingt-trois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'les gens de Netopha, cinquante-six;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'les gens d\'Anathoth, cent vingt-huit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'les fils d\'Azmaveth, quarante-deux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'les fils de Kiriath-Arim (Kiriath-Jearim), de Kephira et de Bééroth, sept cent quarante-trois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'les fils de Rama et de Géba, six cent vingt-un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'les gens de Michmas, cent vingt-deux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'les gens de Béthel et d\'Aï, deux cent vingt-trois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'les fils de Nébo, cinquante-deux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'les fils de Magbis, cent cinquante-six;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'les fils de l\'autre Eilam, mille deux cent cinquante- quatre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'les fils de Harim, trois cent vingt;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'les fils de Lod, de Hadid et de Ono, sept cent vingt-cinq;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'les fils de Jéricho, trois cent quarante-cinq;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'les fils de Senaa, trois mille six cent trente;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'les Prêtres: les fils de Jésaia de la maison de Jésuah, neuf cent soixante-treize;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'les fils d\'Immer, mille cinquante-deux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'les fils de Paschur, mille deux cent quarante-sept;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'les fils de Harim, mille dix-sept;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'les Lévites: les fils de Jésuah et de Cadmiel, des fils de Hodavia, soixante-quatorze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'les Chantres: les fils d\'Asaph, cent vingt-huit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'les fils des Portiers: les fils de Salhim, les fils d\'Ater, les fils de Talmon, les fils de Accub, les fils de Hatita, les fils de Sobaï, en tout cent trente-neuf;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'les assujettis: les fils de Tsiha, les fils de Hasupha, les fils de Tabbaoth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'les fils de Kèros, les fils de Siëha, les fils de Phadon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'les fils de Lebana, les fils de Hagaba, les fils de Accub,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'les fils de Hagab, les fils de Samlaï, les fils de Hanan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'les fils de Giddel, les fils de Gahar, les fils de Reaïa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'les fils de Retsin, les fils de Necoda, les fils de Gazzam,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'les fils de Uzza, les fils de Phasea, les fils de Besaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'les fils de Asna, les fils de Meünim, les fils de Néphusim,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'les fils de Bacbuc, les fils de Hacupha, les fils de Harchur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'les fils de Batseluth, les fils de Mehida, les fils de Harsa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'les fils de Barcos, les fils de Sisera, les fils de Thamah,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'les fils de Netsia, les fils de Hatipha;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'les fils des serviteurs de Salomon: les fils de Sotaï, les fils de Sophéreth, les fils de Pruda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'les fils de Jaëla, les fils de Darcon, les fils de Giddel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'les fils de Sephatia, les fils de Hattil, les fils de Pochéreth-Hatsebaïm, les fils de Ami:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'tous assujettis et fils des serviteurs de Salomon, trois cent quatre-vingt-douze.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Et voici ceux qui partirent de Thel-Mélah, de Thel-Harsa, de Cherub-Addan, d\'Immer, mais sans pouvoir indiquer leurs maisons patriarcales, ni leur race pour constater s\'ils étaient d\'Israël:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'les fils de Delaia, les fils de Tobie, les fils de Necoda, six cent cinquante-deux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'et des fils des Prêtres: les fils de Habaïa, les fils de Haccots, les fils de Barzillaï qui avait épousé une des filles de Barzillaï de Galaad, et fut appelé de son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Ceux-là cherchèrent leur généalogie, mais elle ne fut pas retrouvée et ils furent forclos du Sacerdoce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Et le Gouverneur leur dit qu\'ils n\'eussent pas à manger des choses sacro-saintes jusqu\'à l\'avènement d\'un Prêtre pour consulter l\'Urim et le Thummim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Toute l\'Assemblée était en somme de quarante-deux mille trois cent soixante,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'non compris leurs serviteurs et leurs servantes, dont il y avait sept mille trois cent trente-sept; ils avaient deux cents chantres et chanteuses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Le nombre de leurs chevaux était de sept cent trente-six, et celui de leurs mulets de deux cent quarante-cinq;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'celui de leurs chameaux de quatre cent trente-cinq, de leurs ânes, six mille sept cent vingt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Et plusieurs des chefs des maisons patriarcales, lorsqu\'ils arrivèrent pour la maison de l\'Éternel à Jérusalem, firent des dons spontanés pour la maison de Dieu, à l\'effet de la relever sur son emplacement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'et ils donnèrent à proportion de leurs moyens au trésor de l\'entreprise, en or soixante-un mille dariques et en argent cinq mille mines, et cent habillements sacerdotaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Et ainsi les Prêtres et les Lévites et ceux du peuple et les chantres et les portiers et les assujettis se logèrent dans leurs villes, et tout Israël dans ses villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Et l\'on touchait au septième mois, et les enfants d\'Israël étaient dans [leurs] villes, et le peuple se rassembla comme un seul homme à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Alors se levèrent Jésuah, fils de Jotsadac, et ses frères, les Prêtres, et Zorobabel, fils de Sealthiel, et ses frères, et ils bâtirent l\'autel du Dieu d\'Israël pour y offrir des holocaustes aux termes du texte de la Loi de Moïse, l\'homme de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Et ils assirent l\'autel sur ses fondements, parce qu\'ils étaient sous la terreur que leur donnaient les peuples des pays [voisins], et ils y offrirent des holocaustes à l\'Éternel, les holocaustes du matin et du soir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Et ils firent la fête des Loges aux termes du texte écrit, et offrirent jour par jour des holocaustes, selon le nombre voulu et le rite, l\'ordinaire de chaque jour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'et après cela les holocaustes perpétuels et ceux des nouvelles lunes et de toutes les solennités consacrées de l\'Éternel, et pour tous ceux qui faisaient à l\'Éternel des offrandes spontanées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'A partir du premier jour du septième mois ils commencèrent à sacrifier les holocaustes à l\'Éternel. Cependant les fondements du Temple de l\'Éternel n\'étaient point encore posés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Et ils donnèrent de l\'argent aux tailleurs de pierre et aux charpentiers, et des vivres et des boissons et de l\'huile aux Sidoniens et aux Tyriens pour qu\'ils leur amenassent du bois de cèdre du Liban par mer à Joppe, selon l\'autorisation qu\'ils avaient reçue de Cyrus, roi de Perse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Et la seconde année depuis leur retour à la Maison de Dieu à Jérusalem, au second mois, commencèrent Zorobabel, fils de Sealthiel, et Jésuah, fils de Jotsadac, et le reste de leurs frères, les Prêtres et les Lévites et tous ceux qui de la captivité étaient revenus à Jérusalem, et ils établirent les Lévites de vingt ans et au-dessus pour présider à la bâtisse de la Maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Et Jésuah, ses fils et ses frères, Cadmiel et ses fils, fils de Juda, furent à leur poste comme un seul homme pour surveiller les ouvriers occupés à la maison de Dieu; [de même] les fils de Hènadad, leurs fils et leurs frères, les Lévites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Et lorsque les constructeurs posaient les fondements du Temple de l\'Éternel, les Prêtres en costume portaient présence, avec des trompettes, ainsi que les Lévites, fils d\'Asaph, avec des cymbales pour louer l\'Éternel selon le mode de David, roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Et ils se répondaient en chantant, et en louant l\'Éternel de ce qu\'il est bon, et sa miséricorde éternelle envers Israël. Et tout le peuple acclama par une puissante acclamation à la louange de l\'Éternel, la fondation de la Maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Mais plusieurs des Prêtres et des Lévites, et des chefs des maisons patriarcales, vieillards qui avaient vu la première Maison dans sa structure, quand cette maison fut devant leurs yeux, se mirent à pleurer à grand bruit; d\'un autre côté plusieurs élevaient la voix en cris de joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Et le peuple ne pouvait distinguer entre le bruit des acclamations de joie et le bruit des pleurs dans le peuple; car le peuple poussait une immense clameur dont le bruit s\'entendait au loin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Et lorsque les ennemis de Juda et de Benjamin apprirent que les enfants de la captivité bâtissaient un Temple à l\'Éternel, Dieu d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'ils se présentèrent à Zorobabel et aux chefs des maisons patriarcales et leur dirent: Nous voulons nous joindre à vous pour la bâtisse, car comme vous nous invoquons votre Dieu, et nous lui offrons des sacrifices depuis les jours d\'Assarhaddon, roi d\'Assyrie, qui nous a fait venir ici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Mais Zorobabel et Jésuah et les autres chefs des maisons patriarcales d\'Israël leur dirent: Ni vous ni nous n\'avons le droit de bâtir [en commun] la Maison de notre Dieu; mais nous seuls nous élèverons l\'édifice à l\'Éternel, Dieu d\'Israël, comme nous l\'a recommandé le roi Cyrus, roi de Perse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Alors le peuple du pays ôta le courage au peuple de Juda en lui faisant peur de bâtir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Et ils soudoyèrent contre eux des Conseillers à l\'effet de déjouer leur plan, et cela pendant tout [le reste de] la vie de Cyrus, roi de Perse, et jusqu\'au règne de Darius, roi de Perse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Cependant sous le règne d\'Assuérus, au début de son règne, ils écrivirent une accusation contre les habitants de Juda et de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Et au temps de Arthachsastha, Bislam, Mithredath, Tabeël et ses consorts écrivirent à Arthachsastha, roi de Perse. Or la lettre fut écrite en caractères araméens et traduite en araméen.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Rehum, fondé de pouvoirs, et Simsaï, le Secrétaire, écrivirent contre Jérusalem au roi Arthachsastha une lettre ainsi conçue:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, '« A cette date. — Rehum, fondé de pouvoirs, et Simsaï, le Secrétaire, et leurs autres collègues de Dina et Apharsatcha, Tarpela, Perse, Arach, Babel, Suse, Deha et Eilam,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'et les autres peuples qu\'a déportés Osnappar, le grand et le puissant, et auxquels il a assigné un domicile dans la ville de Samarie, et les autres peuples en deçà du Fleuve et cætera. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'C\'est ici la copie de la lettre qu\'ils lui envoyèrent à lui, au roi Arthachsastha: « Tes serviteurs, hommes d\'au delà du Fleuve et caetera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Notoire soit au Roi que les Juifs partis de chez toi sont venus vers nous à Jérusalem, qu\'ils rebâtissent la ville séditieuse et méchante et en achèvent les murs et en restaurent les fondements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Or qu\'il soit notoire au Roi que, si cette ville est relevée et les murs achevés, ils ne paieront pas le tribut, l\'accise, ni les droits de route, et qu\'ils frustreront d\'autant le trésor royal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Puis donc que nous mangeons le sel du palais, et que nous ne pouvons être plus longtemps témoins du dommage du Roi, en conséquence nous t\'adressons ce message et faisons savoir au Roi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'que l\'on recherche dans le livre des Annales de tes pères, et dans le livre des Annales tu trouveras et apprendras que cette ville a été une ville séditieuse et funeste aux rois et aux provinces et qu\'on y a comploté la révolte dès les jours d\'autrefois: ensuite de quoi cette ville a été détruite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Nous faisons savoir au Roi que, si cette ville est relevée et ses murs achevés, il résultera que de ce côté du Fleuve tu n\'auras plus de possessions. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Alors le roi expédia un rescrit à Rehum, le fondé de pouvoirs, et à Simsaï, le Secrétaire, et à leurs autres collègues habitant Samarie, et aux autres en deçà du Fleuve: « Salut et cætera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'La lettre que vous nous avez envoyée a été lue exactement devant moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Et de ma part ordre a été donné de faire des recherches, et l\'on a trouvé que cette ville dès les jours d\'autrefois s\'est soulevée contre les Rois et que la révolte et la sédition y ont été pratiquées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Et des Rois puissants ont été à Jérusalem et ont régné sur tout ce qui est au delà du Fleuve, et tribut, accise et droits de route leur ont été payés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'En conséquence, donnez l\'ordre d\'empêcher ces gens de rebâtir cette ville jusqu\'à ce que de moi un ordre en émane.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Et prenez garde de manquer d\'agir en conséquence. Et pourquoi le dommage s\'accroîtrait-il au détriment du roi? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Là-dessus, dès que la copie de la lettre du roi Arthachsastha eut été lue devant Rehum et Simsaï, le Secrétaire, et leurs collègues, ils se rendirent en hâte à Jérusalem auprès des Juifs et ils les arrêtèrent de main forte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Dès lors cessèrent les travaux à la Maison de Dieu à Jérusalem, et ils furent entravés jusqu\'à la seconde année du règne de Darius, roi de Perse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Cependant Aggée, le prophète, et Zacharie, fils de Iddo, les prophètes, prophétisèrent aux Juifs en Juda et à Jérusalem au nom du Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Et de suite se mirent en devoir Zorobabel, fils de Sealthiel, et Jésuah, fils de Jotsadac, et ils commencèrent à relever la Maison de Dieu à Jérusalem, et avec eux les prophètes de Dieu qui les assistaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Dans le même temps arrivèrent chez eux Thathnaï, gouverneur de ce côté de l\'Euphrate et Sthar-Boznaï et leurs collègues, et ils leur parlèrent ainsi: Qui vous a autorisés à rebâtir cette maison et à achever ces murs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Sur quoi nous leur dîmes ainsi quels étaient les noms des hommes qui exécutaient cette construction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Et l\'œil de leur Dieu fut sur les Anciens des Juifs de telle sorte qu\'on ne les entrava point en attendant que l\'affaire fût portée devant Darius et qu\'ensuite on leur récrivît sur cet objet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Copie de la lettre adressée au roi Darius par Thathnaï, gouverneur de ce côté du Fleuve, et Sthar-Boznaï et ses collègues, d\'Apharsach de ce côté du Fleuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Ils lui envoyèrent un rapport qui était rédigé en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, '« Au Roi Darius tout salut! Qu\'il soit notoire au Roi que nous nous sommes rendus dans la province de Juda à la Maison du Grand-Dieu; et cette Maison se bâtit en grandes pierres de taille, et du bois est appliqué aux parois, et l\'ouvrage se fait avec diligence et réussit sous leurs mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Sur quoi nous avons interrogé les Anciens; ainsi leur avons-nous parlé: Qui vous a autorisés à bâtir cette maison et à achever ces murs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Et nous leur avons aussi demandé leurs noms pour te les indiquer, afin d\'être à même d\'écrire les noms des hommes qui sont à leur tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Et voici la réponse qu\'ils nous ont rendue en disant: Nous, c\'est nous qui sommes serviteurs du Dieu des Cieux et de la terre, et nous relevons la Maison qui jadis a été élevée il y a bien des années, et qu\'un grand roi d\'Israël a construite et achevée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Mais comme nos pères avaient irrité le Dieu des Cieux, Il l\'a livrée aux mains de Nebucadnetsar, roi de Babel, le Chaldéen, lequel a détruit cette Maison et emmené le peuple captif à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Mais, la première année de Cyrus, roi de Babel, le roi Cyrus a donné l\'ordre de relever cette Maison de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Et la vaisselle aussi de la Maison de Dieu, vaisselle d\'or et d\'argent, enlevée par Nebucadnetsar du Temple de Jérusalem et amenée dans le temple de Babel, le roi Cyrus l\'a tirée du temple de Babel, et elle a été remise au nommé Sesbatsar, qu\'il établit gouverneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'Et il lui dit: Prends cette vaisselle, pars, transporte-la dans le Temple de Jérusalem, et que la Maison de Dieu soit rebâtie sur son emplacement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Ensuite de quoi ce Sesbatsar est venu et a posé les fondements de la Maison de Dieu à Jérusalem, et dès lors jusqu\'à présent on la relève, mais elle n\'est point encore achevée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Dès là, s\'il plaît au Roi, que l\'on recherche dans le Trésor du Roi qui est là à Babel s\'il en est ainsi que de par le roi Cyrus ordre ait été donné de relever cette Maison de Dieu à Jérusalem, et que le Roi nous fasse parvenir son agrément à cet égard. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Là-dessus le roi Darius donna ordre de faire des recherches dans les Archives, où étaient déposés les trésors, à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Et l\'on trouva à Achmetha, dans la capitale, située dans la province de Médie, un volume contenant cet écrit sous forme de Mémoire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, '« La première année du roi Cyrus, le roi Cyrus prit cet arrêté: Quant à la Maison de Dieu à Jérusalem, que la Maison soit rebâtie comme un lieu où l\'on sacrifie des victimes, et que ses fondements soient restaurés; elle aura en hauteur soixante coudées, et en largeur soixante coudées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'trois assises de pierres de taille et une assise de bois; et les frais seront payés par la Maison du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Et aussi la vaisselle de la Maison de Dieu, vaisselle d\'or et d\'argent enlevée par Nebucadnetsar du Temple de Jérusalem et amenée à Babel, sera restituée pour être replacée dans le Temple de Jérusalem à sa place et déposée dans la Maison de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'En conséquence, vous Thathnaï, gouverneur de l\'autre côté du Fleuve, Sthar-Boznaï et leurs collègues d\'Arphachsa, qui êtes de l\'autre côté du Fleuve, tenez-vous éloignés de là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Laissez se faire les travaux à cette Maison de Dieu; que le gouverneur des Juifs et les Anciens des Juifs construisent cette Maison de Dieu sur son emplacement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Et voici l\'ordre émané de moi pour ce que vous aurez à fournir à ces Anciens des Juifs pour la construction de cette Maison de Dieu: savoir, sur les biens royaux, sur les revenus perçus de l\'autre côté du Fleuve, l\'on paiera exactement les dépenses à ces hommes afin qu\'ils ne soient pas gênés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Et le nécessaire, des jeunes taureaux et des béliers, et des agneaux pour holocaustes au Dieu des Cieux, du froment, du sel, du vin et de l\'huile, comme le prescrivent les Prêtres de Jérusalem, leur seront fournis jour par jour sans y manquer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'afin qu\'ils offrent des sacrifices d\'un parfum agréable au Dieu des Cieux, et qu\'ils prient pour la vie du Roi et de ses fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Et par moi ordre est donné que, si quelqu\'un enfreint cette ordonnance, on arrachera une poutre de sa maison, on la dressera et on l\'y clouera, et l\'on fera de sa maison un tas de fumier pour ce fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Et que le Dieu dont le Nom y réside, précipite tous les rois et peuples qui étendront la main pour contrevenir, pour détruire cette Maison de Dieu à Jérusalem. Moi Darius je donne cet ordre, qu\'il soit ponctuellement exécuté. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Là-dessus Thathnaï, gouverneur de ce côté du Fleuve, Sthar-Boznaï et leurs collègues, vu le message envoyé tel par le roi Darius, l\'exécutèrent ponctuellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Et les Anciens des Juifs se mirent à bâtir et ils réussirent par l\'effet des prophéties de Aggée, le prophète, et de Zacharie, fils de Iddo. Et ils édifièrent et achevèrent ensuite de l\'ordre du Dieu d\'Israël, et ensuite de l\'ordre de Cyrus, Darius et Arthachsastha, roi de Perse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Et cette Maison fut achevée au troisième jour du mois Adar; c\'était la sixième année du règne du roi Darius.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Et les enfants d\'Israël, les Prêtres et Lévites et les autres fils de la captivité solennisèrent la dédicace de cette Maison de Dieu avec allégresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Et pour la dédicace de cette Maison de Dieu, ils sacrifièrent cent taureaux, deux cents béliers, quatre cents agneaux, et douze boucs comme victimes expiatoires pour tout Israël selon le nombre des Tribus d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Et ils établirent les Prêtres selon leurs classes et les Lévites selon leurs sections pour le service de Dieu à Jérusalem, d\'après le texte du livre de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Et les fils de la captivité célébrèrent la Pâque le quatorzième jour du premier mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Car les Prêtres et les Lévites s\'étaient purifiés; ils étaient tous purs comme si ce n\'eût été qu\'un seul homme; et ils immolèrent la Pâque pour tous les fils de la captivité, et pour leurs frères, les Prêtres, et pour eux-mêmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Et mangèrent [la Pâque] les enfants d\'Israël qui étaient revenus de la captivité et tous ceux qui pour se joindre à eux avaient rompu avec l\'impureté des nations de la terre pour chercher l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Et ils firent la fête des azymes pendant sept jours dans l\'allégresse; car l\'Éternel les avait réjouis en disposant en leur faveur le cœur du roi d\'Assyrie à soutenir leurs mains dans l\'œuvre de la Maison de Dieu, du Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Et après ces choses sous le règne d\'Arthachsastha, roi de Perse, Esdras, fils de Seraïa, fils de Azaria, fils de Hilkia,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'fils de Sallum, fils de Tsadoc, fils d\'Ahitub,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'fils d\'Amaria, fils d\'Azaria, fils de Meraïoth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'fils de Zerachia, fils de Uzzi, fils de Bukki,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'fils d\'Abisua, fils de Phinées, fils d\'Eléazar, fils d\'Aaron, le Grand Prêtre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'cet Esdras revint de Babel; or il était un Scribe versé dans la Loi de Moïse, qu\'a donnée l\'Éternel, le Dieu d\'Israël. Et le roi, en vertu de la main de l\'Éternel, son Dieu, agissant sur lui, lui accordait toutes ses demandes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Et il vint [avec lui] quelques-uns des enfants d\'Israël, des Prêtres et des Lévites, et des chantres et des portiers et des assujettis, à Jérusalem dans la septième année du roi Arthachsastha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Et ils arrivèrent à Jérusalem au cinquième mois; c\'était la septième année du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Car ce fut le premier jour du premier mois que fut organisé le départ de Babel, et le premier jour du cinquième mois qu\'il arriva à Jérusalem en vertu de la bonne main de Dieu agissant sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Car Esdras avait appliqué son cœur à l\'étude de la Loi de l\'Éternel, et à la pratique et à l\'enseignement en Israël du statut et des lois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Et voici la copie de la lettre que le roi Arthachsastha remit à Esdras, le Prêtre, le Scribe versé dans le texte des commandements de l\'Éternel et de Ses statuts prescrits à Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, '« Arthachsastha, Roi des Rois, à Esdras, le Prêtre et savant consommé dans la Loi du Dieu du Ciel et cætera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Par moi ordre a été donné que quiconque dans mon empire, faisant partie du peuple d\'Israël et de ses Prêtres et de ses Lévites, est disposé à retourner à Jérusalem, peut partir avec toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'puisque tu es délégué par le Roi et ses sept conseillers pour faire une enquête sur Juda et Jérusalem quant à la Loi de ton Dieu, que tu as en main,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'et pour transporter l\'argent et l\'or que le Roi et ses conseillers ont spontanément donnés au Dieu d\'Israël dont la Résidence est à Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'ainsi que tout l\'argent et l\'or que tu auras trouvés dans toute la province de Babel, avec les dons spontanés faits par le peuple et les Prêtres pour la Maison de leur Dieu à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'C\'est pourquoi tu auras soin d\'acheter avec cet argent des taureaux, des béliers, des agneaux, et les offrandes et libations respectives, et de les offrir sur l\'autel de la Maison de votre Dieu à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Et quant à l\'emploi que toi et tes frères trouverez bon de faire du reste de l\'argent et de l\'or, vous pourrez l\'appliquer conformément à la volonté de votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Et la vaisselle qui t\'a été remise pour le service de la Maison de ton Dieu, rends-la au complet devant Dieu à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Et pour les autres dépenses nécessaires à la Maison de ton Dieu, que tu seras dans le cas de faire, tu en tireras le montant du trésor du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Et de par moi Arthachsastha, le Roi, ordre est donné à tous les trésoriers de l\'autre côté du Fleuve, que tout ce que vous demandera Esdras, le Prêtre et Scribe versé dans la Loi du Dieu du Ciel, se fasse ponctuellement');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'jusqu\'à la concurrence de cent talents d\'argent et cent cors de froment et cent baths de vin et cent baths d\'huile, et du sel en quantité illimitée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Tout ce qui est ordonné par le Dieu du Ciel, doit s\'exécuter exactement pour la Maison du Dieu du Ciel, afin que [son] courroux ne fonde pas sur l\'Empire, le Roi et ses fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Et notoire soit à vous que sur tous ces Prêtres, Lévites, chantres, portiers, assujettis et servants dans la Maison de ce Dieu vous n\'avez pas le pouvoir d\'imposer tribut, accise et droits de route.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Et toi, Esdras, avec la sagesse de ton Dieu que tu possèdes, établis des Juges et des Magistrats qui administrent tout le peuple de l\'autre côté du Fleuve, tous ceux qui connaissent la Loi de ton Dieu; et ceux qui ne Le connaissent pas, instruisez-les.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Et quiconque ne pratiquera pas la Loi de ton Dieu, et la Loi du Roi, de lui vous ferez rigoureuse justice, soit par la mort, soit par le bannissement, soit par l\'amende sur ses biens, soit par la prison. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Béni soit l\'Éternel, Dieu de nos pères, qui mit ainsi dans le cœur du roi la volonté d\'honorer la Maison de l\'Éternel à Jérusalem');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'et qui m\'a concilié la faveur du roi et de ses conseillers et de tous les puissants princes du roi! Et je me fortifiai par la main de l\'Éternel, mon Dieu, qui me couvrait, et je rassemblai les Chefs d\'Israël pour se mettre en marche avec moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Et voici leurs Chefs de maisons patriarcales, et leur généalogie, de ceux qui partirent avec moi, sous le règne du roi Arthaehsastha, de Babel:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Des fils de Phinées, Gersom; des fils d\'Ithamar, Daniel; des fils de David, Hattus; des fils de Sechania');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, '(des fils de Paréos) Zacharie, et avec lui furent enregistrés cent cinquante mâles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'des fils de Pachath-Moab Elioénaï, fils de Zeraïa, et avec lui deux cents mâles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'des fils de Sechania, le fils de Jahaziel, et avec lui trois cents mâles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'et des fils de Adin, Ebed, fils de Jonathan, et avec lui cinquante mâles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'et des fils de Eilam, Ésaïe, fils d\'Athalia, et avec lui soixante-dix mâles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'et des fils de Sephatia, Zebadia, fils de Michaël, et avec lui quatre-vingts mâles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'des fils de Joab, Obadia, fils de Jehiel, et avec lui deux cent dix-huit mâles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'et des fils de Selomith, le fils de Josiphia, et avec lui cent soixante mâles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'et des fils de Bébaï, Zacharie, fils de Bébaï, et avec lui vingt-huit mâles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'et des fils de Azgad, Jochanan, fils de Haccatan, et avec lui cent dix mâles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'et des fils d\'Adonicam, les derniers, dont voici les noms: Eliphélet, Jehiel et Semaïa, et avec eux soixante mâles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'et des fils de Bigvaï, Uthaï et Zabbud, et avec eux soixante-dix mâles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Et je les rassemblai sur le fleuve qui coule à Ahava, et nous campâmes là trois jours; et considérant avec attention le peuple et les Prêtres, je ne trouvai là aucun des fils de Lévi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Alors j\'envoyai chercher Eliézer, Ariel, Semaïa et Elnathan et Jarib et Elnathan et Nathan et Zacharie et Mesullam, les chefs, et Jojarib et Elnathan, les experts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'et je les dépêchai à Iddo, chef dans la localité de Casphia, et je leur mis dans la bouche ce qu\'ils devaient dire à Iddo [et] à son frère, aux asservis, dans la localité de Casphia pour nous amener des servants pour la Maison de notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Et par l\'effet de la bénigne main de notre Dieu qui nous protégeait, ils nous amenèrent un homme entendu d\'entre les fils de Maheli, fils de Lévi, fils d\'Israël, et Serabia et ses fils et frères, dix-huit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'et Hasabia et avec lui Ésaïe, des fils de Merari ses frères et fils, vingt;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'et des asservis que David et ses princes avaient, affectés comme assujettis au service des Lévites, deux cent vingt, tous désignés par leurs noms.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Et là sur le fleuve Ahava je publiai un jeûne pour nous humilier devant notre Dieu, à l\'effet de lui demander heureux voyage pour nous et nos enfants et tout notre avoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Car j\'avais honte de demander au roi de la troupe et de la cavalerie pour nous protéger contre nos ennemis pendant le trajet. En effet nous avions dit au roi: La main de notre Dieu est étendue sur tous ceux qui Le cherchent, pour leur faire du bien; mais sa puissance et sa colère sont contre tous ceux qui L\'abandonnent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'C\'est ainsi que nous jeûnâmes et adressâmes sur ce point notre requête à notre Dieu, et Il nous exauça.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Et parmi les chefs des Prêtres j\'en choisis douze, Sérébia, Hasabia et avec eux dix de leurs frères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'et je leur pesai l\'argent et l\'or et la vaisselle, don pour la Maison de notre Dieu, qu\'avaient dédié le roi et ses conseillers et ses princes et tous les Israélites présents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Et je délivrai entre leurs mains un poids de six cent cinquante talents d\'argent, et en vaisselle d\'argent cent talents, en or cent talents');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'et vingt coupes d\'or valant mille dariques, et deux vases d\'airain fin ayant l\'éclat de l\'or, estimé à l\'égal de l\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Et je leur dis: Vous êtes consacrés à l\'Éternel, et la vaisselle est chose sainte, et l\'argent et l\'or est un don spontané fait à l\'Éternel, Dieu de vos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Soyez vigilants et le gardez jusqu\'à ce que vous le pesiez en présence des chefs des Prêtres et des Lévites et des Patriarches d\'Israël à Jérusalem dans les cellules de la Maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Et les Prêtres et les Lévites reçurent l\'argent et l\'or pesé et la vaisselle pour les porter à Jérusalem dans la Maison de notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Ensuite nous partîmes du fleuve Ahava le douzième jour du premier mois pour gagner Jérusalem. Et la main de notre Dieu nous couvrit et nous sauva de la main de l\'ennemi et de l\'insidiateur sur la route.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Et arrivés à Jérusalem nous y primes trois jours de repos.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Et le quatrième jour nous pesâmes l\'argent et l\'or et la vaisselle dans le Temple de notre Dieu, entre les mains de Merémoth, fils du Prêtre Urie, et avec lui était Eléazar, fils de Phinées, et avec eux Jozabad, fils de Jésuah, et Noadia, fils de Binnuï, Lévites,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'd\'après le nombre et le poids de tous les objets; et le poids total fut consigné à cette occasion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Et revenus de l\'exil les fils de la captivité offrirent des holocaustes au Dieu d\'Israël: douze taureaux pour tout Israël, quatre-vingt-seize béliers, soixante-dix-sept brebis, et douze boucs comme victimes expiatoires, le tout en holocauste à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Et ils transmirent les ordres du roi aux satrapes du roi, et aux gouverneurs de ce côté du Fleuve, et ceux-ci donnèrent leur appui au peuple et à la Maison de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Et quand ces choses furent accomplies, les chefs s\'approchèrent de moi en disant: Le peuple d\'Israël et les Prêtres et les Lévites ne se séparent point des populations du monde, imitant leurs abominations qui sont celles des Cananéens, des Héthiens, des Phérésiens, des Jébusites, des Ammonites, des Moabites, des Égyptiens et des Amoréens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Car ils ont pris de leurs filles pour eux et leurs fils et ont mélangé la race sainte avec les populations du monde. Et les chefs et les grands ont les premiers prêté la main à ce crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Et lorsque j\'entendis ce discours, je déchirai mon habit et mon manteau, et je m\'arrachai les cheveux de ma tête et la barbe, et je m\'assis stupéfait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Et vers moi se réunirent tous ceux qui révéraient les paroles du Dieu d\'Israël, à cause du crime des captifs, et je restai stupéfait jusqu\'à l\'oblation du soir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Et à l\'oblation du soir je me levai de mon état d\'humiliation, avec mon habit et mon manteau déchirés, et je tombai à genoux et étendis mes mains vers l\'Éternel, mon Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'et je m\'écriai: O mon Dieu, je suis honteux et confus à n\'oser, ô mon Dieu, lever mon front vers toi. Car nos crimes par leur nombre dépassent notre tête, et notre iniquité par sa grandeur atteint jusqu\'aux cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Dès les jours de nos pères jusqu\'aujourd\'hui nous avons été grandement coupables, et à cause de nos crimes, nous, nos rois et nos Prêtres avons été livrés aux mains des rois des nations, à l\'épée, à la captivité et au pillage et à l\'opprobre, comme nous le sommes aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Cependant un instant de grâce nous est accordé de par l\'Éternel, notre Dieu, qui nous laisse quelques réchappés et nous accorde le pilier d\'une tente dans le lieu de son Sanctuaire, notre Dieu récréant ainsi nos yeux et nous faisant un peu reprendre vie dans notre servitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Car nous sommes esclaves; mais dans notre esclavage notre Dieu ne nous a pas abandonnés, et Il nous a concilié la faveur des rois de Perse, pour nous redonner la vie, pour relever la Maison de notre Dieu, pour restaurer ses ruines et nous permettre d\'avoir des murs en Juda et à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Et maintenant, ô notre Dieu, que dirons-nous après cela? Car nous avons déserté tes commandements');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'que tu nous avais prescrits par tes serviteurs les prophètes en disant: Le pays où vous entrez pour l\'occuper est un pays souillé de la souillure des peuples du monde, des abominations dont ils l\'ont rempli d\'un bout à l\'autre bout par leur impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Vous ne marierez donc point vos filles à leurs fils, ni leurs filles à vos fils, et vous ne chercherez jamais ni leur amitié, ni leur prospérité, si vous voulez être forts et jouir des biens du pays et le transmettre par héritage à vos fils à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Et après tout ce qui nous est advenu par suite de nos méchantes actions et de notre grande culpabilité (car, ô notre Dieu, tu nous as ménagés plus que ne le méritaient nos forfaits, et tu nous as procuré le salut de cette manière),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'reviendrions-nous à enfreindre tes commandements et à nous allier à ces peuples abominables? Ne t\'irriteras-tu pas contre nous jusqu\'à notre extinction: jusqu\'à nous ôter tout reste, et tous réchappés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Éternel, Dieu d\'Israël, tu es juste. Car nous sommes conservés et avons échappé, comme c\'est aujourd\'hui: Nous voici devant ta face dans notre état de coupables; car nul ne saurait subsister devant toi dans cette condition.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Et comme Esdras priait et faisait la confession, pleurant et prosterné devant la Maison de Dieu, il se forma vers lui une assemblée très nombreuse d\'Israélites, hommes, femmes et enfants; car le peuple versait d\'abondantes larmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Alors prit la parole Sechania, fils de Jehiel, des fils d\'Eilam, et il dit à Esdras: Nous avons forfait contre notre Dieu en épousant des femmes étrangères des peuples de la terre, néanmoins il y a encore espoir pour Israël à cet égard.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'A présent nous voulons faire un pacte avec notre Dieu pour le renvoi de toutes ces femmes et de ce qui est né d\'elles, — sur le conseil de monseigneur [Esdras] et de ceux qui révèrent les commandements de notre Dieu, afin qu\'il soit fait selon la Loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Lève-toi! à toi l\'affaire! et nous serons de ton côté. Courage! et agis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Alors Esdras se leva et fit jurer aux chefs des Prêtres, des Lévites et de tout Israël d\'agir dans ce sens. Et ils prêtèrent le serment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Et Esdras se leva de devant la Maison de Dieu, et se rendit dans la cellule de Jochanan, fils d\'Eliasib, et il y alla et ne mangea point de pain et ne but point d\'eau, parce qu\'il était en deuil à cause du forfait des captifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Et ils firent circuler en Juda et à Jérusalem la citation pour tous les fils de la captivité de se rassembler à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'Quant à celui qui ne paraîtrait pas dans l\'espace de trois jours, selon le conseil des chefs et des Anciens, tous ses biens seraient confisqués et lui-même éliminé du corps des captifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Alors tous les hommes de Juda et de Benjamin se rassemblèrent à Jérusalem dans l\'espace de trois jours: c\'était le neuvième mois, le vingtième du mois. Et tout le peuple prit séance dans la place de la Maison de Dieu, tremblant à cause de la question et à cause des pluies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Alors Esdras, le Prêtre, se leva et leur dit: Vous avez forfait en épousant des femmes étrangères, et avez ainsi ajouté à la culpabilité d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Faites donc votre confession à l\'Éternel, Dieu de vos pères, et exécutez sa volonté en vous séparant des peuples du pays et des femmes étrangères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Et toute l\'Assemblée répondit et dit à voix forte: Oui, c\'est comme tu nous le dis que nous devons agir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Mais le peuple est nombreux, et c\'est la saison des pluies, et il n\'y a pas moyen de rester en plein air, et ce n\'est pas l\'affaire d\'un ni de deux jours; car nous avons abondamment manqué à cet égard.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Que nos chefs soient donc les représentants de toute l\'Assemblée; et tous ceux qui dans nos villes ont épousé des femmes étrangères, pourront venir à époques fixes, et avec eux les Anciens de chaque ville et ses Juges, jusqu\'à ce que l\'on ait détourné de nous la colère de notre Dieu, allumée pour cette raison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Cependant Jonathan, fils de Hasahel, et Jahezia, fils de Thicva, firent opposition, et Mesullam et Sabthaï, le Lévite, les appuyèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Mais les fils de la captivité suivirent ce mode. Et l\'on choisit Esdras, le Prêtre, et quelques-uns des chefs des maisons patriarcales, tous désignés par leurs noms.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'Et ils siégèrent le premier jour du dixième mois pour connaître de l\'affaire. Et ils en finirent avec tous les hommes qui avaient épousé des femmes étrangères, le premier jour du premier mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Et parmi les fils de Prêtres qui avaient épousé des femmes étrangères, se trouvèrent des fils de Jésuah, fils de Jotsadac, et de ses frères, Mahaseïa et Éliézer et Jarib et Gedalia;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'et en donnant leur main ils s\'engagèrent à renvoyer leurs femmes, et à offrir un bélier en sacrifice expiatoire pour leur faute;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'et des fils de Immer: Hanani et Zebadia;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'et des fils de Harim: Mahaseïa et Elia et Semaïa et Jehiel et Uzzia;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'et des fils de Paschur: Elioénaï, Mahaseïa, Ismaël, Nathanaël, Jozabad et Eleasa;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'et des Lévites: Jozabad et Siméï et Kelaïa (c\'est Kelita), Pethahia, Juda et Eliézer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'et des Chantres: Eliasib; et des Portiers: Sallum et Télem et Uri;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'et d\'Israël, des fils de Paréos: Ramia et Jizzia et Malchiia et Mijamin et Eléazar et Malchiia et Benaïa;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'et des fils d\'Eilam: Matthania, Zacharie et Jehiel et Abdi et Jerémoth et Elia;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'et des fils de Zatthu: Elioénaï, Eliasib, Matthania et Jerémoth et Zabad et Aziza;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'et des fils de Bébaï: Jochanan, Hanania, Zabbaï, Athlaï;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'et des fils de Bani: Mesullam, Malluch et Adaïa, Jasub et Seal, Jeramoth;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'et des fils de Pachath-Moab: Adna et Chelal, Benaïa, Mahaseïa, Matthania, Betsaleël et Binnuï et Manassé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'et des fils de Harim: Eliézer, Jissia, Malchia, Semaïa, Siméon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Malluch, Semaria;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'des fils de Chasum: Mathnaï, Matthattha, Zabad, Eliphéleth, Jerémaï, Manassé, Siméï;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'des fils de Bani: Maëdaï, Amram et Uel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaïa, Bédia, Cheluhi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'et Naïa, Merémoth, Eliasib,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Matthania, Matthnaï et Jaësaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'et Bani et Binnuï, Siméï');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'et Sélémia et Nathan et Adaïa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Machnadbaï, Sasaï, Saraï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Azareël et Sélémia, Semaria,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sallum, Amaria, Joseph;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'des fils de Nebo: Jehiel, Matthithia, Zabad, Zebina, Jaddaï et Joël, Benaïa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Tous ceux-là avaient épousé des femmes étrangères, et il y en avait parmi ces femmes qui avaient apporté des fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Dits et faits de Néhémie, fils de Hachalia. Et il arriva au mois de Chisleu, de la vingtième année, comme j\'étais dans Suse, la ville capitale,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'qu\'alors vint Chanani, l\'un de mes frères, ayant avec lui quelques hommes de Juda. Et je les interrogeai sur les Juifs, sur les réchappés qui étaient restés de la captivité, et sur Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Et ils me dirent: Les restants qui ont survécu à la captivité sont là dans la province en une grande misère et dans l\'opprobre, et le mur de Jérusalem est démoli, et ses portes brûlées au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Et lorsque j\'entendis ce récit, je m\'assis et pleurai, et je fus dans le deuil plusieurs jours, et je jeûnai et fis ma prière devant le Dieu des Cieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'et je dis: Ah! Éternel, Dieu des Cieux, Dieu grand et redoutable, toi qui gardes ton alliance et ta grâce à ceux qui t\'aiment et gardent tes commandements!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Que ton oreille soit donc attentive et tes yeux ouverts pour ouïr la prière de ton serviteur que je porte devant ta face à cette heure, jour et nuit pour les fils d\'Israël, tes serviteurs, et la confession que je fais des péchés des enfants d\'Israël, dont nous nous sommes rendus coupables envers toi; moi aussi et la maison de mon père nous avons péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Nous avons forfait à notre devoir envers toi, et n\'avons point gardé les commandements, ni les statuts, ni les lois que tu prescrivis à Moïse, ton serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Ah! souviens-toi de la promesse que tu as fait prononcer par Moïse, ton serviteur, en ces termes: Si vous vous rebellez, je vous disséminerai parmi les peuples;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'mais si vous revenez à moi et observez mes commandements et les mettez en pratique, quand vos bannis seraient à l\'extrémité des Cieux, je vous y recueillerai et vous ramènerai au lieu que j\'ai choisi pour y faire résider Mon Nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Mais ils sont tes serviteurs et ton peuple, que tu as rachetés par ton grand pouvoir et ta puissante main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Oh! Seigneur, que ton oreille soit attentive à la prière de ton serviteur, et à la prière de tes serviteurs, qui sont disposés à craindre ton Nom, et accorde aujourd\'hui le succès à tes serviteurs et fais-leur trouver grâce aux yeux de cet homme. Or j\'étais échanson du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Et au mois de Nisan, la vingtième année du roi Arthachsastha, comme le vin était devant lui, je pris le vin et le servis au roi; (d\'ailleurs je n\'avais jamais été mal avec lui.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Alors le roi me dit: Pourquoi as-tu l\'air triste? Tu n\'es pourtant pas malade? Ce n\'est pas autre chose que chagrin du cœur. Et j\'éprouvai une grande crainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'Et je dis au roi: Que le roi vive éternellement! Comment n\'aurais-je pas un air triste quand la cité, sépulture de mes pères, gît désolée, et que le feu a consumé ses portes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Et le roi me dit: Que me demandes-tu donc? Alors j\'adressai ma prière au Dieu des Cieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'et je dis au roi: Avec l\'agrément du roi, et si ton serviteur a tes bonnes grâces, c\'est que tu m\'envoies en Juda, dans la ville des tombeaux de mes pères, pour la restaurer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Alors le roi et l\'épouse assise à ses côtés me dirent: Combien de temps durera ton voyage, et quand seras-tu de retour? Et il plut au roi de m\'envoyer, et je lui fixai un temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Et je dis au roi: Avec l\'agrément du roi je voudrais que l\'on me donnât des lettres pour les gouverneurs de l\'autre côté du Fleuve, afin qu\'ils m\'accordent le passage jusqu\'à mon arrivée en Juda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'et une lettre pour Asaph, l\'intendant de la forêt royale, afin qu\'il me fournisse le bois pour la charpente des portes de la citadelle près du Temple, et pour le mur de la ville, et la Maison en vue de laquelle je vais. Et le roi me l\'accorda par l\'effet de la bénigne main de Dieu qui me protégeait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'J\'arrivai donc chez les gouverneurs de l\'autre côté du Fleuve, et je leur remis les lettres du roi; et le roi me fit escorter par des officiers de l\'armée et de la cavalerie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Mais lorsque Saneballat, de Choronaïm, et Tobie, le serviteur, Ammonite, en furent informés, ils furent extrêmement chagrins de ce qu\'il vînt un homme pour chercher l\'intérêt des enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Et j\'arrivai à Jérusalem, et après y avoir été trois jours,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'je me levai pendant la nuit, moi et le peu d\'hommes que j\'avais avec moi, mais je ne m\'ouvris à personne sur ce que mon Dieu m\'avait mis dans le cœur de faire pour Jérusalem; et point de bête de somme avec moi, sinon l\'animal qui me servait de monture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Et de nuit je sortis par la porte de la Vallée, en allant à la source des dragons jusqu\'à la porte du Fumier et j\'examinai les murs de Jérusalem qui étaient là en ruine, et ses portes consumées par le feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Puis je passai à la porte de la Fontaine et à l\'Étang Royal; et il n\'y avait pas de place où pût passer l\'animal que je montais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Et de nuit je montai la Vallée, examinant les murs, et reprenant mon chemin par la porte de la Vallée je rentrai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Cependant les chefs ignoraient où j\'étais allé et ce que j\'avais fait. Car ni aux Juifs, ni aux Prêtres, ni aux notables, ni aux chefs, ni aux autres qui devaient faire les travaux, jusqu\'ici je ne m\'étais encore ouvert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Alors je leur dis: Vous voyez l\'état misérable où nous sommes, comme Jérusalem est désolée et ses portes brûlées par le feu. Venez! relevons le mur de Jérusalem, afin que nous ne soyons plus dans l\'opprobre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Et je leur découvris comment la bénigne main de mon Dieu m\'avait protégé, et aussi les paroles que le roi m\'avait adressées. Et ils dirent: Nous sommes prêts pour faire la restauration. Et ils s\'encouragèrent au bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Mais lorsque Saneballat de Choronaïm, et Tobie, le serviteur, Ammonite, et Gésem l\'Arabe, l\'apprirent, ils se moquèrent de nous, et nous montrèrent du mépris et dirent: Qu\'est-ce que vous faites là? Est-ce que vous vous révoltez contre le roi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Et je leur répliquai en ces termes: Le Dieu des Cieux nous donnera le succès, et nous, ses serviteurs, nous allons nous mettre à restaurer. Mais vous n\'avez ni communauté, ni droit, ni souvenir en Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Alors se mirent à l\'œuvre le Grand-Prêtre Eliasib et ses frères, les Prêtres, et ils construisirent la Porte des Brebis. Ils la consacrèrent et en établirent les battants; et ils la consacrèrent jusqu\'à la Tour Mea, jusqu\'à la Tour Hananeël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Et à côté de lui bâtirent les hommes de Jéricho; et à côté de lui bâtit Zaccur, fils d\'Imri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Et la Porte des Poissons fut construite par les fils de Senaa. Et ils en firent la charpente et en établirent les battants, les serrures et les verrous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Et à côté d\'eux restaurait Merémoth, fils d\'Urie, fils de Haccots; et à côté d\'eux restaurait Mesullam, fils de Beréchia, fils de Meseizabeël; et à côté d\'eux restaurait Tsadoc, fils de Baëna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Et à côté d\'eux restauraient les Thékôïtes, mais leurs notables ne prêtèrent pas leur dos au service de leur maître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Et la Porte Ancienne fut restaurée par Joiada, fils de Paseach, et Mesullam, fils de Besodia: ils en firent la charpente, et en posèrent les battants, les serrures et les verrous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Et à côté d\'eux restauraient Melathia, le Gabaonite, et Jadon, le Méronothite, les gens de Gabaon et de Mitspa ressortissant au siège du gouverneur de ce côté du Fleuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'A côté d\'eux restaurait Uzziel, fils de Charaïa, [l\'un] des orfèvres; et à côté de lui restaurait Hanania, fils du parfumeur. [Or ils (l es Chaldéens) avaient laissé Jérusalem debout jusqu\'au large mur.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Et à côté d\'eux restaurait Rephaïa, fils de Hur, chef de la moitié du Cercle de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Et à côté d\'eux restaurait Jedaïa, fils de Harumaph, vis-à-vis de sa maison; et à côté de lui restaurait Hattus, fils de Hasabenia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Malchiia, fils de Harim, et Hassub, fils de Pachath-Moab, restauraient une section et la Tour des Fourneaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Et à côté de lui restaurait Sallum, fils de Halloës, chef de l\'autre moitié du Cercle de Jérusalem, lui et ses filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'La Porte de la Vallée fut restaurée par Hanun et les habitants de Zanoah; ils la bâtirent et en posèrent les battants, les serrures et les verrous, et mille coudées au mur jusqu\'à la Porte du Fumier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Et la Porte du Fumier fut restaurée par Malchiia, fils de Rechab, chef du Cercle de Beth-Haccarem; il la bâtit et en posa les battants, les serrures et les verrous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Et la Porte de la Source fut restaurée par Sallun, fils de Col-Hozeh, chef du Cercle de Mitspa; il la bâtit, en fit la toiture, et en posa les battants, les serrures et les verrous, et le mur de l\'Étang de Siloé près du Jardin Royal jusqu\'à la rampe qui descend de la Cité de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Après lui restaurait Néhémie, fils de Azbuc, chef de la moitié du Cercle de Beth-Tsur, jusque vis-à-vis des tombeaux de David vis-à-vis jusqu\'à l\'étang artificiel et jusqu\'à l\'hôtel des héros.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Après lui restauraient les Lévites, Rehum, fils de Bani. A côté de lui restaurait Hasabia, chef de la moitié du Cercle de Kehila, pour son Cercle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Après lui restauraient ses frères, Bavvaï, fils de Hénadad, chef de l\'autre moitié du Cercle de Kehila.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Et à côté de lui restaurait Eser, fils de Jésuah, chef de Mitspa, une autre section vis-à-vis de la montée de l\'arsenal de l\'angle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Après lui avec ardeur restaurait Baruch, fils de Zabbaï, une seconde section à partir de l\'angle jusqu\'à la porte de la maison d\'Eliasib, le Grand-Prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Après lui restaurait Merémoth, fils de Urie, fils de Haccots, une seconde section à partir de la porte de la maison d\'Eliasib jusqu\'à l\'extrémité de la maison d\'Eliasib.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Et après lui restauraient les Prêtres, les hommes du District [du Jourdain].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Après eux restauraient Benjamin et Hassub vis-à-vis de leur maison. Après eux restaurait Azaria, fils de Mahaseïa, fils d\'Ananias, à côté de sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Après lui restaurait Binnuï, fils de Hénadad, une seconde section à partir de la maison d\'Azaria jusqu\'à l\'angle et jusqu\'au coin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal, fils de Usaï, vis-à-vis de l\'angle et de la Tour qui sort de la maison supérieure du roi dans la cour de la prison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'Après lui Pedaïa, fils de Paréos. Or les assujettis habitaient sur la colline vis-à-vis de la Porte de l\'Eau au Levant, et de la Tour saillante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Après eux restauraient les Thékôïtes, une seconde section vis-à-vis de la Grande Tour saillante jusqu\'au mur de la colline.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Au-dessus de la Porte des Chevaux restauraient les Prêtres, chacun vis-à-vis de sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Après eux restaurait Tsadoc, fils de Immer, vis-à-vis de sa maison, et après lui restaurait Semaïa, fils de Sechania, garde de la Porte du Levant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Après lui restauraient Hanania, fils de Sélémia, et Hanun, le sixième fils de Tsalaph, une seconde section. Après eux restaurait Mesullam, fils de Béréchia, vis-à-vis de sa cellule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Après lui restaurait Malchiia, l\'orfèvre, jusqu\'à la maison des assujettis et des marchands, vis-à-vis de la Porte de la Revue, jusqu\'à la haute chambre de l\'angle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Et entre la haute chambre de l\'angle et la Porte des Brebis restauraient les orfèvres et les marchands.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Et lorsque Saneballat apprit que nous relevions les murs, il fut irrité et très chagrin, et il se moqua des Juifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Et il parla devant ses frères et les puissants de Samarie en ces termes: Que font les Juifs impuissants? les laissera-t-on faire? Sacrifieront-ils? achèveront-ils maintenant? feront-ils renaître les pierres du sein des décombres poudreux, quand elles sont brûlées?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Et Tobie, l\'Ammonite, se tenait à ses côtés et dit: Aussi bien qu\'est-ce qu\'ils bâtissent? Quand un renard sauterait dessus, il ferait crouler leur mur de pierres! —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Entends, ô notre Dieu, que nous sommes méprisés, et fais retomber leurs outrages sur leur tête, et livre-les au pillage dans le pays de la captivité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Ne couvre pas leur forfait, et que leur péché ne soit pas effacé devant toi, car ils t\'ont provoqué en s\'opposant aux réparateurs. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Cependant nous relevâmes le mur, et tout le mur fut achevé jusqu\'à la moitié; et le peuple avait cœur au travail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Et lorsque Saneballat et Tobie et les Arabes et les Ammonites et les Asdodites apprirent que le mur de Jérusalem était remis en état et que les brèches commençaient à se fermer, ils en eurent une colère extrême.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Et ils se liguèrent tous entre eux pour venir attaquer Jérusalem et lui porter dommage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Alors nous priâmes notre Dieu, et nous fîmes le guet jour et nuit par précaution contre eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Mais Juda dit: La vigueur des porteurs cède, et il y a trop de décombres: nous ne pouvons plus travailler au mur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Et nos adversaires avaient cette idée: il faut qu\'ils ne se doutent, ne s\'aperçoivent de rien, jusqu\'à ce que nous soyons arrivés au milieu d\'eux, et que nous les massacrions, et fassions cesser l\'ouvrage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Et comme il vint des Juifs qui habitaient près d\'eux, et qu\'ils nous le répétèrent bien dix fois, de tous les lieux d\'où ils allaient et venaient chez nous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'je posai des postes dans l\'enfoncement à l\'endroit qui est derrière le mur, dans les places exposées au soleil, et je postai le peuple par familles avec leurs épées, leurs lances et leurs arcs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Et j\'examinai, puis je me levai et dis aux nobles et aux chefs et au reste du peuple: N\'ayez pas peur d\'eux! Pensez au Seigneur, le Grand et le Redoutable, et combattez pour vos frères, vos fils et vos filles, vos femmes et vos maisons!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Et lorsque nos ennemis apprirent que nous étions informés, par là Dieu déjoua leur plan, et nous retournâmes tous au mur, chacun à sa besogne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Et à partir de ce jour, la moitié de mes écuyers travaillaient à l\'ouvrage, et l\'autre moitié restait sous les armes avec lances, boucliers, et arcs et cuirasses. Et les chefs se tenaient derrière toute la Maison de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Ceux qui travaillaient au mur et ceux qui portaient et chargeaient les fardeaux, d\'une main travaillaient à l\'ouvrage et de l\'autre tenaient leur armure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'Les constructeurs avaient chacun son épée ceinte autour de ses reins, et travaillaient. Et celui qui sonnait de la trompette, était à mes côtés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Et je dis aux nobles et aux chefs et au reste du peuple: L\'ouvrage est considérable et étendu, et nous sommes épars sur les murs, l\'un à distance de l\'autre:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'au lieu donc d\'où vous entendrez partir le son de la trompette, réunissez-vous-y à nous! Notre Dieu combattra pour nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Et c\'est ainsi que nous travaillions à l\'ouvrage; et une moitié des hommes tenaient la lance depuis le lever de l\'aurore jusqu\'à l\'apparition des étoiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Et dans le même temps je dis aussi au peuple: Que chacun avec son écuyer passe la nuit dans Jérusalem, et que la nuit il fasse le guet pour nous, et que le jour il soit à l\'ouvrage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Ni moi, ni mes frères, ni mes écuyers, ni les hommes de la garde qui me suivaient, ne quittâmes nos habits; pour bain — chacun avait son armure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Et il y eut grande réclamation du peuple et des femmes auprès de leurs frères les Juifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Et il y en avait qui disaient: De nos fils et de nos filles nous avons un grand nombre: fournissez-nous donc de blé afin que nous ayons de quoi manger pour vivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Et il y en avait qui disaient: Nous allons engager nos champs et nos vignes et nos maisons pour nous procurer du blé dans la disette.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Puis il y en avait qui disaient: Nous avons emprunté de l\'argent, pour les impôts à payer au roi, sur nos champs et nos vignes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Et pourtant notre corps est comme le corps de nos frères, et nos enfants comme leurs enfants. Et voilà que nous devons soumettre à l\'esclavage nos fils et nos filles; et il y a déjà de nos filles qui le subissent, et nous ne possédons absolument rien, et nos champs et nos vignes sont à d\'autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Alors j\'eus une colère extrême, lorsque j\'entendis leur clameur et ces discours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Et mon cœur me fit prendre la résolution de réprimander les nobles et les chefs, et je leur dis: Vous pratiquez l\'usure l\'un envers l\'autre. Et je provoquai contre eux une grande assemblée');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'et je leur dis: Nous avons racheté nos frères, les Juifs, qui avaient été vendus aux nations, selon nos moyens; et vous aussi vous voulez vendre nos frères! et ils devront se vendre à nous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Alors ils se turent, et ils ne trouvèrent mot à dire. Et je dis: Il n\'est pas bien à vous d\'en agir de la sorte! Ne devriez-vous pas marcher dans la crainte de notre Dieu, pour n\'être pas honnis par les peuples, nos ennemis?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Moi aussi, mes frères et mes écuyers nous leur avons prêté de l\'argent et du blé. Faisons donc abandon de ce dû!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Restituez-leur donc aujourd\'hui leurs champs, leurs vignes, leurs olivaies et leurs maisons et le centième de l\'argent et du blé et du moût et de l\'huile, que vous avez reçu d\'eux comme intérêt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Alors ils dirent: Nous voulons le restituer et ne rien exiger d\'eux, nous voulons nous conformer à ce que tu as dit. Et j\'appelai les Prêtres et leur fis jurer d\'agir en ce sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Et je secouai aussi le pan de mon manteau et dis: Qu\'ainsi Dieu secoue quiconque n\'exécutera pas cette promesse, hors de sa maison et de ses biens, et qu\'il soit ainsi secoué et vidé! Alors toute l\'Assemblée s\'écria: Ainsi soit-il! Et ils louèrent l\'Éternel et le peuple agit dans ce sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'De même, à partir du jour où l\'on me préposa comme gouverneur du pays, depuis la vingtième jusqu\'à la trente-deuxième année du roi Arthachsastha, douze années durant, ni moi, ni mes frères ne mangeâmes la pension de gouverneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Car les premiers gouverneurs, mes prédécesseurs, avaient opprimé le peuple, et reçu de lui du pain et du vin outre quarante sicles d\'argent; leurs écuyers aussi tyrannisaient le peuple. Mais moi je n\'agis point ainsi, par crainte de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Et je m\'appliquai fortement à la restauration de ces murs; et nous n\'achetâmes point de champs, et tous mes écuyers étaient réunis là pour l\'ouvrage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Et [chaque jour] j\'avais à ma table cent cinquante hommes, Juifs et Chefs, outre ceux qui arrivaient chez moi des peuples d\'alentour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Et l\'ordinaire de chaque jour, un bœuf, six moutons gras et de la volaille, était préparé à mes frères; et aussi de dix jours en dix jours tout le vin en abondance; et avec cela je ne réclamai point le traitement de gouverneur, car le service pesait lourdement sur ce peuple. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Garde-moi bonne mémoire, ô mon Dieu, de tout ce que j\'ai fait pour ce peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Et lorsque Saneballat et Tobie et Gésem, l\'Arabe, et nos autres ennemis eurent appris que j\'avais restauré les murs, et qu\'il n\'y restait plus de brèche, quoique jusqu\'à ce moment-là je n\'y eusse point encore posé les battants aux portes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Saneballat et Gésem m\'adressèrent ce message: Viens, et ayons une conférence dans les bourgs du val d\'Ono! Or ils pensaient à me faire un mauvais parti.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Alors je leur dépêchai des messagers pour leur dire: Une grande affaire m\'occupe et je ne puis descendre: pourquoi faire cesser l\'ouvrage en me relâchant et en descendant auprès de vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Et ils me firent faire le même message quatre fois, et je leur renvoyai la même réponse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Alors Saneballat m\'adressa le même message une cinquième fois par son écuyer, porteur d\'une lettre ouverte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Elle était conçue en ces termes: « Parmi les nations court ce bruit, et Gasmu dit: Toi et les Juifs vous pensez à vous révolter; c\'est pourquoi tu relèves les murs, et tu dois devenir leur roi d\'après ces dires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Tu as aussi aposté des prophètes pour te proclamer à Jérusalem en disant: Roi de Juda! Et maintenant ces propos viendront aux oreilles du roi. Viens donc afin que nous nous concertions ensemble! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Et je lui envoyai ce message: Il ne s\'est rien fait dans le sens que tu dis; mais c\'est une imagination de ton cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Car tous ils voulaient nous intimider, et ils se disaient: De guerre lasse ils quitteront l\'ouvrage qui ne s\'achèvera pas. Eh bien! ô Dieu, prête force à mes mains!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Et j\'entrai chez Semaïa, fils de Delaia, fils de Meheitabéel, or il s\'était renfermé. Et il dit: Réunissons-nous dans la Maison de Dieu, dans l\'intérieur du Temple, et fermons les portes du Temple, car il vient des gens pour t\'assassiner, et c\'est cette nuit qu\'ils arrivent pour t\'assassiner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Et je dis: Un homme comme moi fuirait! Et quel est mon pareil qui pénétrerait dans le Temple et resterait en vie? Je n\'entre point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Et je reconnus, et voilà que ce n\'était pas Dieu qui l\'envoyait, et il prononçait une prophétie contre moi parce que Saneballat et Tobie l\'avaient soudoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Et le but pour lequel il avait été soudoyé, c\'était que je prisse peur et agisse en conséquence, et commisse un péché, et que, m\'étant fait un mauvais nom, ils eussent de quoi me calomnier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'O mon Dieu, garde de Tobie et de Saneballat un souvenir conforme à leurs œuvres, et aussi de la prophétesse Noadia et des autres prophètes qui prétendaient m\'intimider!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Et le mur fut achevé le vingt-cinq Elul au bout de cinquante-deux jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Et quand tous nos ennemis l\'apprirent, tous les peuples d\'alentour prirent peur, et ils furent extrêmement découragés, et ils comprirent que cette œuvre s\'était accomplie de par notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Et il y eut aussi dans ce même temps beaucoup de nobles Juifs qui adressèrent des lettres à Tobie et en reçurent de Tobie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Car plusieurs en Juda s\'étaient conjurés avec lui. Car il était beau-frère de Sechania, fils d\'Arach, et son fils Jochanan avait épousé la fille de Mesullam, fils de Béréchia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Même ils parlaient devant moi de ses bonnes qualités, et ils lui rapportaient mes discours. C\'est pourquoi Tobie envoya des lettres pour m\'intimider.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Et lorsque le mur fut restauré, je posai les battants des portes, et les Portiers, et les Chantres et les Lévites furent mis en fonctions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Et je donnai mes ordres à Hanani, mon frère, et à Hanania, commandant de la citadelle de Jérusalem, (car c\'était un homme fidèle et craignant Dieu plus que beaucoup)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'et je leur dis: Les portes de Jérusalem ne s\'ouvriront pas avant que le soleil soit ardent; et pendant qu\'on est encore debout, il faudra les fermer et les clore. Et formez un guet des habitants de Jérusalem, et que chacun soit à son poste vis-à-vis de sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Or la ville était spacieuse et grande, mais ne contenait que peu de population, et l\'on n\'avait pas encore bâti de maisons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Alors mon Dieu me mit dans le cœur l\'idée d\'assembler les nobles et les chefs et le peuple pour un recensement. Et je trouvai un registre de ceux qui étaient rentrés les premiers, et voici ce que j\'y trouvai consigné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Ce sont ici les ressortissants de la province revenus de la captivité, de la déportation, que Nebucadnetsar, roi de Babel, avait emmenés et qui revinrent à Jérusalem et en Juda, chacun dans sa ville,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'lesquels vinrent avec Zorobabel: Jésuah, Néhémie, Azaria, Raamia, Nahemani, Mordechaï, Bilsan, Mispéreth, Bigvaï, Nehum, Baëna. Nombre des hommes du peuple d\'Israël:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'les fils de Paréos, deux mille cent soixante-douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'les fils de Sephatia, trois cent soixante-douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'les fils d\'Arach, six cent cinquante-deux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'les fils de Pachath-Moab, des fils de Jésuah et de Joab, deux mille huit cent dix-huit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'les fils de Eilam, mille deux cent cinquante-quatre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'les fils de Zattu, huit cent quarante-cinq;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'les fils de Zaccaï, sept cent soixante;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'les fils de Binnuï, six cent quarante-huit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'les fils de Bébaï, six cent vingt-huit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'les fils de Azgad, deux mille trois cent vingt-deux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'les fils d\'Adonicam, six cent soixante-sept;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'les fils de Bigvaï, deux mille soixante-sept;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'les fils d\'Adin, six cent cinquante-cinq;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'les fils de Ater [de la famille de] Ézéchias, quatre-vingt-dix-huit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'les fils de Hasum, trois cent vingt-huit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'les fils de Betsaï, trois cent vingt-quatre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'les fils de Hariph, cent douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'les fils de Gibéon, quatre-vingt-quinze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'les gens de Bethléhem et Netopha, cent quatre-vingt-huit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'les gens d\'Anathoth, cent vingt-huit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'les gens de Beth-Azmaveth, quarante-deux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'les gens de Kiriath-Jearim, Caphira et Beéroth, sept cent quarante-trois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'les gens de Rama et Géba, six cent vingt-un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'les gens de Michmas, cent vingt-deux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'les gens de Béthel et Aï, cent vingt-trois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'les gens de Nebo, l\'autre, cinquante-deux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'les fils d\'Eilam, l\'autre, mille deux cent cinquante-quatre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'les fils de Harim, trois cent vingt;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'les fils de Jéricho, trois cent quarante-cinq;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'les fils de Lod, Hadid et Ono, sept cent vingt-un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'les fils de Senaa, trois mille neuf cent trente;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'les Prêtres: les fils de Jedaïa, de la maison de Jésuah, neuf cent soixante-treize;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'les fils de Immer, mille cinquante-deux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'les fils de Paschur, mille deux cent quarante-sept;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'les fils de Harim, mille dix-sept;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'les Lévites: les fils de Jésuah, de Cadmiel, des fils de Hodva, soixante-quatorze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'les Chantres: les fils d\'Asaph, cent quarante-huit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'les Portiers: les fils de Sallum, les fils d\'Ater, les fils de Talmon, les fils d\'Accub; les fils de Hatita, les fils de Sobaï, cent trente-huit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'les Assujettis: les fils de Tsiha, les fils de Hasupha, les fils de Tabbaoth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'les fils de Keiros, les fils de Sia, les fils de Phadon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'les fils de Lebana, les fils de Hagaba, les fils de Salmaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'les fils de Hanan, les fils de Giddel, les fils de Gahar,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'les fils de Reaïa, les fils de Retsin, les fils de Necoda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'les fils de Gazzam, les fils de Uzza, les fils de Paseach,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'les fils de Bèsaï, les fils de Meünim, les fils de Nephusim,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'les fils de Bacbuc, les fils de Hacupha, les fils de Harhur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'les fils de Bathsélith, les fils de Mehida, les fils de Harsa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'les fils de Barcos, les fils de Sisera, les fils de Thamach,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'les fils de Netsiah, les fils de Hatipha;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'les fils des serviteurs de Salomon: les fils de Sotaï, les fils de Sophéreth, les fils de Pherida,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'les fils de Jaëla, les fils de Darcon, les fils de Giddel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'les fils de Sephatia, les fils de Hattil, les fils de Pochéreth-Halsébaïm, les fils de Amon:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'tous les assujettis et fils des serviteurs de Salomon: trois cent quatre-vingt-douze.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Et voici ceux qui revinrent de Thel-Mélah, Thel-Harsa, Chérub-Addon et Immer (mais ils ne purent indiquer leurs maisons patriarcales, ni leur souche, ni s\'ils étaient d\'Israël):');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'les fils de Delaïa, les fils de Tobie, les fils de Necoda, six cent quarante-deux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'et des Prêtres: les fils de Hobaïa, les fils de Haccots, les fils de Barzillaï qui prit femme parmi les filles de Barzillaï de Galaad et fut appelé de leur nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Ceux-là cherchèrent leur acte généalogique, mais il ne se trouva pas, et ils furent exclus du sacerdoce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Et le Thirsatha (gouverneur) leur défendit de manger des choses sacro-saintes jusqu\'à ce que reparût un Prêtre pour consulter l\'Urim et le Thummim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Toute l\'Assemblée en masse était de quarante-deux mille trois cent soixante,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'sans leurs serviteurs et leurs servantes dont il y avait sept mille trois cent trente-sept. A eux appartenaient deux cent quarante-cinq chantres et chanteresses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Ils avaient sept cent trente-six chevaux, deux cent quarante-cinq mulets,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'quatre cent trente-cinq chameaux, six mille sept cent vingt ânes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Et sur le nombre des chefs des maisons patriarcales plusieurs firent des dons pour l\'entreprise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Le Thirsatha donna pour le trésor, en or mille dariques, cinquante jattes, cinq cent trente costumes de Prêtres. Et parmi les chefs des maisons patriarcales plusieurs donnèrent pour la caisse de l\'entreprise, en or vingt mille dariques, et en argent deux mille deux cents mines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Et ce que le reste du peuple donna, était, en or vingt mille dariques, et. en argent deux mille mines, et soixante-sept costumes de Prêtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Et ainsi les Prêtres et les Lévites, et les Portiers et les Chantres et les gens du peuple et les assujettis et tous les Israélites habitèrent dans leurs villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Et à l\'approche du septième mois, comme les enfants d\'Israël étaient dans leurs villes, tout le peuple se rassembla comme un seul homme dans la place qui est devant la Porte de l\'Eau. Et ils dirent à Esdras, le Scribe, d\'apporter le livre de la Loi de Moïse, prescrite par l\'Éternel à Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Et le Prêtre Esdras apporta la Loi devant l\'Assemblée composée d\'hommes et de femmes et de tous ceux qui étaient capables de l\'entendre, le premier jour du septième mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Et il en fit la lecture en face de la Place qui est devant la Porte de l\'Eau, depuis l\'aube jusqu\'à midi, en présence des hommes et des femmes et de tous ceux qui étaient capables d\'entendre. Et les oreilles de tout le peuple se dirigeaient vers le livre de la Loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Et Esdras, le Scribe, se tenait sur une estrade en bois qu\'on avait faite pour cet objet. Et à côté de lui se tenaient Matthithia et Sema et Anaïa et Uri et Hilkia et Maaseïa à sa droite; et à sa gauche étaient Pedaïa et Misaël et Malchiia et Hasum et Hasbaddana, Zacharie, Mesullam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Et Esdras ouvrit le volume devant les yeux de tout le peuple, car il était placé plus haut que tout le peuple; et quand il l\'ouvrit, tout le peuple se leva.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Et Esdras bénit l\'Éternel, le Grand Dieu, et tout le peuple répondit: Ainsi soit-il! Ainsi soit-il! en élevant leurs mains, et ils s\'inclinèrent et se prosternèrent devant l\'Éternel la face contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Et Jésuah et Bani et Sérébia, Jamin, Accub, Sabthaï, Hodia, Maaseïa, Kelita, Azaria, Jozabad, Hanan, Pelaïa et les Lévites interprétaient la Loi au peuple, et le peuple restait en place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Et ils lurent dans le livre de la Loi de Dieu distinctement et indiquaient le sens, et expliquaient en faisant lecture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Et Néhémie, le Thirsatha, et le Prêtre Esdras, le Scribe, et les Lévites qui enseignaient le peuple, dirent à tout le peuple: Ce jour est consacré à l\'Éternel, votre Dieu. Ne soyez ni dans le deuil ni dans les larmes! (car tout le peuple pleurait en écoutant les paroles de la Loi.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Et il leur dit: Allez, faites chère grasse et buvez des boissons douces, et envoyez des parts à ceux qui n\'ont rien d\'apprêté, car ce jour est consacré à notre Seigneur. Et ne vous tourmentez pas, — car la joie que vous donne l\'Éternel, doit être votre réconfort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Et les Lévites calmèrent tout le peuple et dirent: Silence! car le jour est Saint! et ne vous tourmentez pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Là-dessus tout le peuple s\'en alla manger et boire et envoyer des portions et faire une grande réjouissance. Car ils avaient compris les paroles dont il leur avait été donné connaissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Et le second jour s\'assemblèrent les chefs des maisons patriarcales de tout le peuple, les Prêtres et les Lévites, auprès d\'Esdras, le Scribe, pour étudier les paroles de la Loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Et ils trouvèrent consigné dans la Loi, que l\'Éternel avait prescrite par l\'organe de Moïse: que les enfants d\'Israël devaient se loger dans des huttes, à la fête du septième mois,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'et qu\'ils devaient publier et faire circuler dans toutes leurs villes et à Jérusalem cet appel: Allez à la montagne et en rapportez des rameaux d\'olivier à huile et des rameaux d\'olivier sauvage, et des rameaux de myrte et des branches de palmier et des branches d\'arbres touffus pour en faire des loges, comme c\'est écrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Et le peuple sortit et en rapporta, et ils se firent des loges, chacun sur sa terrasse, et dans leurs cours et dans les cours de la Maison de Dieu, et dans la Place de la Porte de l\'Eau, et dans la Place de la Porte d\'Éphraïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Et toute l\'Assemblée de ceux qui étaient revenus de la captivité, fit des loges, et habita dans des loges. Car depuis l\'époque de Josué, fils de Nun, jusqu\'à ce jour, les enfants d\'Israël n\'avaient rien fait de pareil, et ce fut une très grande réjouissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Et on lut dans le livre de la Loi de Dieu chaque jour, du premier au dernier jour. Et ils firent la fête pendant sept jours, et le huitième jour eut lieu la Grande Convocation selon l\'usage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Et le vingt-quatrième jour de ce mois-là les enfants d\'Israël s\'assemblèrent en jeûne, et vêtus de cilices, et ils se couvrirent de poussière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Et la race d\'Israël fut séparée de tous les enfants de l\'étranger. Et ils se présentèrent et confessèrent leurs péchés et les égarements de leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Et ils se levèrent à leur place et lurent dans le livre de la Loi de l\'Éternel, leur Dieu, pendant le quart de la journée, et pendant l\'autre quart ils firent leur confession et se prosternèrent devant l\'Éternel, leur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Et à l\'estrade des Lévites parurent Jésuah et Bani, Cadmiel, Sebania, Bunni, Sérébia, Bani, Chenani, et à voix forte ils crièrent vers l\'Éternel, leur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Et les Lévites Jésuah et Cadmiel, Bani, Hasabnia, Sérébia, Hodia, Sebania, Pethahia, dirent: Sus! bénissez l\'Éternel, votre Dieu, de l\'Éternité jusqu\'à l\'Éternité! Que l\'on bénisse Ton Nom glorieux élevé au-dessus de toute bénédiction et louange!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'C\'est Toi, Éternel, toi seul qui as fait les Cieux, les Cieux des Cieux, et toute leur armée, la terre et tout ce qui la couvre, les mers et tout ce qui est en elles. Et tu fais vivre tous ces êtres, et l\'armée des Cieux t\'adore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'C\'est toi, Éternel, ô Dieu, qui fis choix d\'Abram et le tiras d\'Ur en Chaldée et lui conféras le nom de Abraham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Et tu trouvas son cœur fidèle devant toi et tu conclus avec lui l\'engagement de lui donner le pays des Cananéens, des Héthiens, des Amoréens et des Phérézites et des Jébusites et des Girgésiens, de le donner à sa postérité. Et tu as tenu Ta Parole, car tu es juste!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Et tu vis la misère de nos pères en Egypte et entendis leurs cris vers la mer aux Algues;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'et tu opéras des signes et des miracles sur Pharaon et sur tous ses serviteurs et sur tout le peuple de son pays; car tu savais qu\'ils les traitaient avec orgueil, et tu te fis un Nom tel qu\'il est aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Et tu partageas la mer devant eux, et ils passèrent à sec par le milieu de la mer, et ceux qui les poursuivaient, tu les abîmas dans les flots comme une pierre dans les eaux puissantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Et dans une colonne de nuée tu les guidais le jour, et la nuit dans une colonne de feu pour leur éclairer la voie où ils avaient à marcher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Et tu descendis sur le mont Sinaï, et du Ciel tu parlas avec eux et leur donnas des lois justes, et des règles vraies, et des statuts et commandements excellents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Et tu leur révélas ton saint Sabbat, et leur prescrivis des commandements, des statuts et une Loi par l\'organe de Moïse, ton serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Et pour leur faim tu leur donnas un pain céleste, et pour leur soif tu leur fis sourdre l\'eau du rocher. Et tu leur dis de marcher à la conquête du pays que tu avais levé la main de leur donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Et eux, nos pères, ils furent orgueilleux et roidirent leur col et n\'obéirent point à tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Et ils refusèrent l\'obéissance et ne se souvinrent plus de tes merveilles que tu avais opérées pour eux, et ils roidirent leur col, et dans leur rébellion se donnèrent un chef pour rentrer sous leur esclavage. Mais tu es un Dieu qui pardonnes, clément et miséricordieux, patient et riche d\'amour, et tu ne les abandonnas pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Même quand ils se fabriquèrent un veau en fonte et dirent: Voilà ton Dieu qui t\'a retiré de l\'Egypte! et qu\'ils firent de grands blasphèmes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'alors même, dans ton immense miséricorde, tu ne les abandonnas pas au Désert. La colonne de nuée ne leur fit point défaut le jour pour les guider dans le trajet, ni de nuit la colonne de feu pour leur éclairer la voie où ils avaient à marcher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Et tu leur donnas ton bon esprit pour les instruire, et ne refusas point ta manne à leur bouche, et tu leur fournis de l\'eau pour leur soif.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Et quarante ans tu les entretins au Désert; ils n\'eurent point de disette; leurs habits ne s\'usèrent point, et leurs pieds n\'enflèrent point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Et tu leur livras des royaumes et des peuples, et tu les répartis dans tous les sens; et ils conquirent le pays de Sihon, et le pays du roi de Hesbon, et le pays de Og, roi de Basan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Et tu multiplias leurs fils comme les étoiles du ciel, et tu les introduisis dans le pays que tu avais promis à leurs pères pour qu\'ils en vinssent faire la conquête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Et les fils vinrent faire la conquête du pays. Et tu fis plier devant eux les habitants du pays, les Cananéens, et tu les livras à leurs mains, ainsi que leurs rois et les peuples du pays pour les traiter à leur gré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Et ils occupèrent des villes fortes et un sol gras, et s\'emparèrent de maisons remplies de tous les biens, de puits creusés, de vignes, d\'olivaies et d\'arbres à fruit en quantité. Et ils mangèrent et se rassasièrent et s\'engraissèrent et vécurent dans les délices par ta grande bonté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Mais ils furent rebelles et s\'insurgèrent contre toi, et jetèrent ta Loi derrière leur dos et massacrèrent tes prophètes qui les sommaient de revenir à toi, et ils se portèrent à de grands blasphèmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Alors tu les livras aux mains de leurs ennemis qui les opprimèrent. Mais à l\'heure de leur détresse ils crièrent vers toi, et toi des Cieux tu exauças, et en vertu de la grande miséricorde tu leur accordas des libérateurs qui les sauvèrent des mains de leurs oppresseurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Mais quand ils avaient trêve, de nouveau ils faisaient le mal devant toi; alors tu les abandonnais aux mains de leurs ennemis qui les subjuguaient. Alors de nouveau ils criaient vers toi, et toi du ciel tu exauçais, et dans ta grande miséricorde tu les sauvas à maintes époques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Et tu les sommais de revenir à ta Loi; mais eux ils étaient orgueilleux, et n\'écoutaient point tes commandements, et ils péchaient contre tes lois, que l\'homme doit pratiquer pour vivre par elles, et ils opposaient une épaule rebelle et raidissaient leur col, et n\'obéissaient pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Et tu différas avec eux de longues années et tu les sommas par ton Esprit, par l\'organe de tes prophètes, mais ils ne prêtèrent point l\'oreille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Alors tu les livras aux mains des peuples des nations. Mais en vertu de ta grande miséricorde tu n\'en as point fini avec eux, et tu ne les as point abandonnés, parce que tu es un Dieu clément et miséricordieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Et maintenant, ô notre Dieu, ô toi, le Grand Dieu, le puissant et le redoutable, qui gardes l\'alliance et la grâce, ne tiens pas pour peu de chose toute la tribulation qui nous a atteints, nous, nos Rois, nos Chefs et nos Prêtres et nos Prophètes, et nos pères et tout ton peuple, depuis le jour des rois d\'Assyrie jusqu\'à ce jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Mais tu as été juste dans tout ce qui nous est advenu; car tu agis fidèlement, et c\'est nous qui sommes coupables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Et nos Rois, nos Chefs, nos Prêtres et nos pères n\'ont point pratiqué ta Loi, ni pris garde à tes commandements et à tes sommations par lesquelles tu les as adjurés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Et dans leur gouvernement et au milieu des bienfaits nombreux dont tu les as comblés, et dans le pays spacieux et fertile que tu avais mis à leur disposition, ils ne t\'ont point servi, et n\'ont point renoncé à leurs mauvaises œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Voici, nous sommes aujourd\'hui esclaves, et dans le pays que tu as donné à nos pères, pour jouir de ses fruits et de ses biens, voilà que nous y sommes esclaves; et il multiplie ses produits pour les rois que tu as établis sur nous à cause de nos péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Et ils dominent sur nos personnes et sur notre bétail, selon leur bon plaisir, et nous sommes dans une grande angoisse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'Et avec tout cela nous stipulâmes un pacte que nous mîmes par écrit et qui fut revêtu du seing de nos Chefs, de nos Lévites, de nos Prêtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Et présidèrent à la signature: Néhémie, le Thirsatha, fils de Hachalia,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'et Sédécias, Seraïa, Azaria, Jérémie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Paschur, Amaria, Malchiia,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hattus, Sebania, Malluc,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Harim, Merémoth, Obadia,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Ginthon, Baruch,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mesullam, Abia, Mijamin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Mahazia, Rilgaï, Semaïa, ce sont les Prêtres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'et les Lévites: Jésuah, fils de Azania, Binnui, des fils de Hénadad, Cadmiel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'et leurs frères: Sebania, Hodiia, Kelita, Pelaïa, Hanan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Micha, Rehob, Hasabia,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Zaccur, Sérébia, Sebania,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodiia, Bani, Beninu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'les Chefs du peuple: Paréos, Pachath-Moab, Eilam, Zatthu, Bani,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bunni, Azgad, Bébaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adoniia, Bigvaï, Adin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Ezéchias, Azzur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodiia, Hasum, Betsaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hariph, Anathoth, Nèbaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpias, Mesullam, Hézir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mesèzabéel, Tsadoc, Jaddus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Platia, Hanan, Anaïa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Hosée, Hanania, Hassub,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Hallohes, Pilcha, Sobec,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rehum, Hasabna, Maaseïa');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'et Ahia, Hanan, Anan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Malluch, Harim, Baëna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Et le reste du peuple, les Prêtres, les Lévites, les Portiers, les Chantres, les Assujettis, et tous ceux qui s\'étaient séparés des peuples des autres pays pour adhérer à la Loi de Dieu, leurs femmes, leurs fils et leurs filles, et tous ceux qui avaient la connaissance et l\'intelligence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'se joignirent à leurs frères notables, et se soumirent à l\'adjuration et au serment de marcher selon la loi de Dieu, donnée par l\'organe de Moïse, serviteur de Dieu, et de garder et pratiquer tous les commandements de l\'Éternel, notre Seigneur, et ses lois et ses statuts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'et de ne pas donner nos filles aux peuples de la terre, et de ne pas marier nos fils à leurs filles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'et dans le cas où les peuples du pays apporteraient des marchandises, et toutes sortes de grains le jour du Sabbat pour les vendre, de ne pas les acheter d\'eux le jour du Sabbat, ou d\'autres saints jours, et de laisser relâche la septième année en remettant toutes les dettes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Et nous nous prescrivîmes de nous soumettre à la règle de nous imposer annuellement d\'un tiers de sicle pour le service de la Maison de notre Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'pour les pains de présentation et l\'oblation perpétuelle, et l\'holocauste perpétuel, celui des Sabbats et des nouvelles lunes, et pour les fêtes et pour les consécrations et pour les victimes expiatoires destinées à la propitiation pour Israël, et pour tout le mouvement de la Maison de notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Et nous, Prêtres, Lévites et peuple, nous jetâmes aussi les sorts au sujet des prestations en bois à amener dans la Maison de notre Dieu, selon nos familles patriarcales, à époques fixes, année par année, pour le brûler sur l\'autel de l\'Éternel, notre Dieu, conformément au texte de la Loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Et nous arrêtâmes d\'apporter les prémices de notre sol, et les prémices de tous les arbres fruitiers annuellement à la Maison de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'et d\'amener les premiers-nés de nos fils et de nos bestiaux, selon le texte de la Loi, et les premiers-nés de notre gros et de notre menu bétail dans la Maison de notre Dieu aux Prêtres desservant la Maison de notre Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'et les prémices de nos gruaux et nos offrandes et les fruits de tous les arbres, moût et huile, nous les apporterons aux Prêtres dans les cellules de la Maison de notre Dieu, et les dîmes de notre pays aux Lévites; car les Lévites [à leur tour] paient la dîme dans toutes nos villes rurales.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Et le Prêtre, fils d\'Aaron, s\'adjoindra aux Lévites, lorsque les Lévites paieront la dîme, afin que les Lévites apportent la dîme de la dîme dans la Maison de notre Dieu, dans les cellules, au trésor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Car les enfants d\'Israël et les fils de Lévi doivent apporter dans les cellules l\'oblation prélevée sur le blé, le moût et l\'huile; car là sont les vases sacrés et les Prêtres qui font le service et les Portiers et les Chantres. Et nous ne délaisserons point la Maison de notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Et les Chefs du peuple demeuraient dans Jérusalem, et le reste du peuple tira au sort pour en faire venir un sur dix habiter Jérusalem, la Ville Sainte, et distribuer les neuf autres dixièmes dans les villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Et le peuple bénit tous les hommes qui volontairement consentirent à habiter Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Et voici les chefs de la province dont le domicile fut à Jérusalem. Or dans les villes de Juda chacun habitait sur sa propriété dans leurs villes, Israélites, Prêtres et Lévites et Assujettis et fils des serviteurs de Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Et à Jérusalem habitaient des fils de Juda et des fils de Benjamin; des fils de Juda: Athaïa, fils de Uzzia, fils de Zacharie, fils d\'Amaria, fils de Sephatia, fils de Mahalaleël, des fils de Pérets,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'et Maaseïa, fils de Baruch, fils de Chol-Hoseh, fils de Hazaïa, fils de Adaïa, fils de Jojarib, fils de Zacharie, fils de Siloni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Tous les fils de Pérets domiciliés à Jérusalem étaient au nombre de quatre cent soixante-huit, hommes vaillants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Et voici les fils de Benjamin: Sallu, fils de Mesullam, fils de Joëd, fils de Pedaïa, fils de Colaïa, fils de Maaseïa, fils de Ithiel, fils d\'Esaïe;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'et après lui Gabbaï et Sallaï, neuf cent vingt-huit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'et Joël, fils de Zichri, était préposé sur eux, et Juda, fils de Hasnua, était préposé en second sur la Ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Des Prêtres: Jedaïa, fils de Jojarib, Jachin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraïa, fils de Hilkia, fils de Mesullam, fils de Tsadoc, fils de Meraïoth, fils de Ahitub, primicier de la Maison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'et leurs frères occupés aux affaires de la Maison de Dieu, huit cent vingt-deux; et Adaïa, fils de Jeroham, fils de Pelalia, fils de Amtsi, fils de Zacharie, fils de Paschur, fils de Malchiia,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'et ses frères, chefs des maisons patriarcales, deux cent quarante-deux; et Amassai, fils de Azareël, fils de Achzaï, fils de Mesillémoth, fils de Immer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'et leurs frères, hommes vaillants, cent vingt-huit; et sur eux était préposé Zabdiel, fils de Gedolim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Et des Lévites: Semaïa, fils de Hassub, fils de Azricam, fils de Hasabia, fils de Bunni,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'et Sabthaï, et Jozabad, préposé sur les affaires extérieures dans la Maison de Dieu, des chefs des Lévites,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'et Matthania, fils de Micha, fils de Zabdi, fils de Asaph, le chef qui le premier entonnait la louange à la prière, et Bakbukia, le second de ses frères, et Abda, fils de Sammua, fils de Galal, fils de Jeduthun:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'total des Lévites dans la Ville Sainte, deux cent quatre-vingt-quatre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Et les Portiers: Accub, Talmon et leurs frères, gardes des Portes, cent soixante-douze.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Et les autres Israélites, les Prêtres, les Lévites étaient dans toutes les villes de Juda, chacun sur sa propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Et les Assujettis habitaient sur la Colline, et Tsiha et Gispa étaient préposés sur les Assujettis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Et le préposé des Lévites à Jérusalem était Uzzi, fils de Bani, fils de Hasabia, fils de Matthania, fils de Micha, des fils d\'Asaph les Chantres, pour les affaires de la Maison de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Car un ordre du roi avait été donné à leur égard, et il y avait un salaire assuré pour les Chantres, un ordinaire de chaque jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Et Pethahia, fils de Meseizabéel, des fils de Zérah, fils de Juda, était à la portée du roi dans toutes les choses du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Quant aux bourgs de leurs campagnes, des fils de Juda habitaient Kiriath-Arba et ses annexes, et Dibon et ses annexes et Jecabtseël et ses bourgs');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'et Jésua et Molada et Beth-Palet');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'et Hatsar-Sual et Bëerséba et ses annexes');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'et Tsiklag et Mechona et ses annexes');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'et Ein-Rimmon et Tsoreha et Jarmuth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Zanoah, Adullam et leurs bourgs, Lachis et ses campagnes, Azeca et ses annexes. Et ils s\'établirent de Béerséba à la vallée de Hinnom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Et les fils de Benjamin depuis Géba dans Michmas et Aïa et Béthel et ses annexes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'Anathoth, Nob, Anania,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hatsor, Rama, Githaïm,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadid, Tseboïm, Neballat,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lod et Ono dans la vallée des charpentiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Et des Lévites habitaient par divisions entre Juda et Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Et voici les Prêtres et les Lévites qui rentrèrent avec Zorobabel, fils de Sealthiel, et Jésuah: Seraïa, Jérémie, Esdras,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amaria, Malluch, Hattus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sechania, Rehum, Merémoth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Ginthoï, Abia,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijamin, Maadia, Bilga,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semaïa et Jojarib, Jedaïa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Amoc, Hilkia, Jedaïa. C\'étaient les Chefs des Prêtres et de leurs frères au temps de Jésuah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Et les Lévites: Jésuah, Binnuï, Cadmiel, Sérébia, Juda, Matthania [préposés] pour les hymnes, lui et ses frères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'et Bacbukia et Unni, leurs frères, collatéralement avec eux pour faire la garde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Et Jésuah engendra Jojakim, et Jojakim engendra Eliasib, et Eliasib engendra Jojada,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'et Jojada engendra Jonathan, et Jonathan engendra Jadduah.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Et au temps de Jojakim parmi les Prêtres étaient patriarches: de Seraïa Meraïa, de Jérémie Hanania,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'd\'Esdras Mesullam, d\'Amaria Jochanan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'de Meluchi Jonathan, de Sebania Joseph,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'de Harim Adna, de Meraïoth Helcaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'de Iddo Zacharie, de Ginthon Mesullam,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'de Abia Zichri, de Minjamin, de Moadia Piltaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'de Bilga Sammua, de Semaïa Jonathan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'de Jojarib Matthnaï, de Jedaïa Uzzi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'de Sallaï Callaï, de Amoc Eber,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'de Hilkia Hasabia, de Jedaïa Nethaneël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Quant aux Lévites au temps d\'Eliasib, de Jojada, de Jochanan et de Jaddua les patriarches furent inscrits, et quant aux Prêtres ce fut sous le règne de Darius, le Perse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Les patriarches des fils de Lévi sont inscrits dans le livre des Annales jusqu\'au temps de Jochanan, fils d\'Eliasib.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Or les chefs des Lévites étaient: Hasabia, Sérébia et Jésuah, fils de Cadmiel, et leurs frères étaient collatéralement chargés de la louange et de l\'action de grâces, selon l\'ordonnance de David, l\'homme de Dieu, une fonction correspondant à une fonction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Matthania et Bacbukia, Obadia, Mesullam, Talmon, Accub montaient la garde comme portiers aux magasins des portes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Ceux-ci appartenaient à l\'époque de Jojakim, fils de Jésuah, fils de Jotsadac, et à l\'époque de Néhémie, le Gouverneur, et d\'Esdras, le Prêtre, le Scribe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Et lorsqu\'il s\'agit de la consécration du mur de Jérusalem, on alla chercher les Lévites dans toutes leurs localités pour les amener à Jérusalem, pour faire la consécration et la réjouissance avec des hymnes et des cantiques, avec des cymbales, des harpes et des luths.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Alors se réunirent les fils des Chantres du district qui entoure Jérusalem, et des bourgs des Netophatites,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'et de Beth-Gilgal, et des campagnes de Géba et d\'Azmaveth; car les Chantres s\'étaient bâti des bourgs autour de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Et les Prêtres et les Lévites se purifièrent, et purifièrent le peuple, et les portes et le mur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Alors je fis monter les chefs de Juda sur la muraille, et je disposai deux grands chœurs pour l\'action de grâces et des processions: [le premier marcha] à droite sur le mur vers la Porte du Fumier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Et après eux marchaient Hosaïa et une moitié des Princes de Juda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'savoir Azaria, Esdras et Mesullam,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda et Benjamin et Semaïa et Jérémie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'et des fils des Prêtres avec des trompettes: Zacharie, fils de Jonathan, fils de Semaïa, fils de Matthania, fils de Michaïa, fils de Zaccur, fils d\'Asaph');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'et ses frères: Semaïa et Azareël, Milelaï, Gilelaï, Maaï, Nethaneël et Juda, Hanani, avec les instruments de musique de David, l\'homme de Dieu, et Esdras, le Scribe, les précédait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Et à la Porte de la Source vis-à-vis d\'eux ils montèrent la rampe de la Cité de David, la montée du mur au-dessus du palais de David jusqu\'à la Porte de l\'Eau à l\'Orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Et le second chœur marchait à l\'opposite, et moi derrière lui, ainsi que l\'autre moitié du peuple, sur le mur au-dessus de la Tour aux Fourneaux, jusqu\'au large mur');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'et au-dessus de la Porte d\'Éphraïm et de l\'Ancienne Porte et de la Porte aux Poissons et de la Tour Hananeël et de la Tour Méa jusqu\'à la Porte des Brebis, et ils firent halte près de la Porte des Prisons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Et ainsi, les deux chœurs se trouvèrent à la Maison de Dieu, ainsi que moi et la moitié des chefs qui m\'accompagnaient et les Prêtres:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'Eliakim, Maaseïa, Minjamin, Michaïa, Elioeinaï, Zacharie, Hanania avec des trompettes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'et Maaseïa et Semaïa et Éléazar et Uzzi et Jochanan et Malchiia et Eilam et Ezer. Et les Chantres se firent entendre, et Jizerahia dirigeait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Et l\'on offrit dans cette journée de grands sacrifices et ils furent dans l\'allégresse, car Dieu leur avait accordé une grande joie, et les femmes et les enfants se réjouirent aussi, et la réjouissance de Jérusalem fut entendue au loin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Et le même jour des hommes furent préposés sur les cellules, aux trésors et aux oblations, aux prémices et aux dîmes, pour y recueillir des campagnes, des villes, les prestations légales attribuées aux Prêtres et aux Lévites. Car c\'était pour Juda plaisir que de voir les Prêtres et les Lévites en fonctions;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'et ils s\'acquittaient de tout ce dont il fallait s\'acquitter pour leur Dieu, et de ce dont il fallait s\'acquitter pour la purification, ainsi que les Chantres et les Portiers, selon l\'ordonnance de David et de Salomon, son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Car autrefois à l\'époque de David et d\'Asaph, il y avait des chefs des Chantres et des chefs d\'orchestre pour la louange et l\'action de grâces à l\'honneur de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Et tout Israël, à l\'époque de Zorobabel et à l\'époque de Néhémie, paya les redevances aux Chantres et aux Portiers, l\'ordinaire de chaque jour, et l\'on donna aux Lévites des choses consacrées, et les Lévites firent part des consécrations aux fils d\'Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Le même jour on lut dans le Livre de Moïse aux oreilles du peuple, et l\'on y trouva écrit: Aucun Ammonite ou Moabite n\'aura entrée dans l\'Assemblée de Dieu, jamais,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'parce qu\'ils ne prévinrent pas les enfants d\'Israël avec le pain et l\'eau, et qu\'ils soudoyèrent contre eux Balaam pour les maudire; mais notre Dieu fit tourner la malédiction en bénédiction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Et lorsqu\'ils eurent entendu cette loi, ils séparèrent d\'Israël tous les étrangers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Cependant avec cela le Prêtre Eliasib, préposé sur une cellule dans la maison de Dieu, parent de Tobie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'lui avait arrangé une grande cellule où l\'on déposait auparavant les offrandes, l\'encens et la vaisselle et la dîme du blé, du moût et de l\'huile, les redevances dues aux Lévites, aux Chantres et aux Portiers, et ce qui était prélevé pour les Prêtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Et quand cela se fit, je n\'étais point à Jérusalem, car c\'est la trente-deuxième année d\'Arthachsastha, roi de Babel, que je me présentai au roi et à la fin de l\'année que j\'obtins l\'agrément du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'Étant ainsi arrivé à Jérusalem, je m\'aperçus de l\'abus qu\'avait commis Eliasib en faveur de Tobie en lui laissant l\'usage d\'une cellule dans les Parvis de la Maison de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'et je fus fort mécontent, et je jetai tous les meubles de la demeure de Tobie dehors, hors de la cellule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Et j\'ordonnai qu\'on purifiât les cellules, et j\'y fis rentrer les meubles de la Maison de Dieu, l\'offrande et l\'encens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Et j\'appris que les redevances dues aux Lévites n\'avaient point été payées, et qu\'avaient fui, chacun vers son champ, les Lévites et Chantres qui exerçaient les fonctions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Alors je pris à partie les chefs et je dis: Pourquoi la Maison de Dieu est-elle délaissée? Et je les rassemblai et les mis à leur poste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Et tout Juda apporta la dîme de blé, moût et huile au trésor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Et j\'établis comme préposés sur le trésor, Sélémia, le Prêtre, et Tsadoc, le Scribe, et Pedaïa d\'entre les Lévites, et comme leurs adjoints, Hanan, fils de Zaccur, fils de Matthania, car ils étaient réputés hommes sûrs, et c\'était à eux à faire les répartitions à leurs frères. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Souviens-toi de moi, ô mon Dieu, à cause de cela, et ne raie pas les actes pieux que j\'ai accomplis dans la Maison de Dieu et dans son administration!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'Dans le même temps, je vis en Juda des pressureurs aux pressoirs le jour du Sabbat et des gens rentrer des gerbes et les charger sur des ânes, ainsi que du vin, des raisins et des figues et toutes sortes de fardeaux, et les amener à Jérusalem le jour du Sabbat. Et je leur fis une remontrance le jour où ils vendaient les denrées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Il s\'y trouvait aussi des Tyriens qui apportaient du poisson et toutes sortes de marchandises qu\'ils vendaient le jour du Sabbat aux enfants de Juda et de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Alors je pris à partie les notables de Juda et leur dis: Qu\'est-ce que ce mal que vous faites là, profanant ainsi le jour du Sabbat?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'N\'est-ce pas ainsi qu\'ont agi vos pères, ensuite de quoi notre Dieu a fait tomber sur nous et sur cette ville tous ces malheurs? Et vous accumulez la colère divine sur Israël par la profanation du Sabbat!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Et lorsqu\'il fit sombre dans les Portes de Jérusalem avant le Sabbat, j\'ordonnai que les portes fussent fermées, et ordonnai de ne les rouvrir qu\'après le Sabbat passé. Et je postai de mes écuyers aux portes, afin qu\'il n\'entrât aucune charge le jour du Sabbat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Et les marchands et vendeurs de toutes sortes de marchandises durent passer la nuit en dehors de Jérusalem, une et deux fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Et je les tançai et leur dis: Pourquoi passez-vous la nuit devant le mur? Si vous réitérez, je mettrai la main sur vous. Dès ce moment ils ne vinrent plus le jour du Sabbat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Et je dis aux Lévites de se purifier et de venir garder les portes pour sanctifier le jour du Sabbat. — De cela aussi conserve-moi le souvenir, ô mon Dieu, et use de clémence envers moi selon ta grande miséricorde!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Dans ce temps aussi je vis des Juifs qui avaient épousé des femmes Asdodites, Ammonites, Moabites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Et la moitié de leurs fils parlaient asdodite, et ne savaient pas parler le juif, mais bien la langue de tel ou tel de ces peuples-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Et je les pris à partie, et les maudis et en battis quelques-uns, et leur arrachai les cheveux, et je leur fis jurer ceci par le Nom de Dieu: Vous ne donnerez point vos filles à leurs fils et ne prendrez point de leurs filles pour vos fils, ni pour vous-mêmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'N\'est-ce pas en ce point qu\'a péché Salomon, le roi d\'Israël? et dans le nombre des peuples il n\'y eut pas de roi comme lui, et il était aimé de son Dieu, et Dieu l\'établit roi de tout Israël; néanmoins c\'est lui qu\'entraînèrent au péché des femmes étrangères!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Nous faudrait-il vous faire la concession de commettre un si grand crime que de nous révolter contre notre Dieu par des mariages avec des femmes étrangères?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Et l\'un des fils de Joïada, fils d\'Eliasib, le Grand-Prêtre, était devenu gendre de Saneballat, l\'Horonite, et je le chassai loin de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Souviens-toi d\'eux, ô mon Dieu, à cause de la souillure du Sacerdoce, et de la constitution Sacerdotale et Lévitique!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Et ainsi, je les purifiai de tout étranger, et je fixai les fonctions pour les Prêtres et pour les Lévites, pour chacun dans son office,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'et les prestations en bois à fournir par époques déterminées, et en prémices. — Garde de moi, ô mon Dieu, un favorable souvenir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Et au temps d\'Assuérus (cet Assuérus régnait de l\'Inde à l\'Éthiopie sur cent vingt-sept provinces),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'comme le roi Assuérus était assis sur son trône royal dans Suse, la ville capitale,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'la troisième année de son règne, il donna un festin à tous ses seigneurs et à ses serviteurs, aux généraux de Perse et de Médie, aux Grands et aux Princes des provinces, devant lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'en déployant l\'opulence et la pompe de son empire et la riche magnificence de sa majesté, pendant nombre de jours, pendant cent quatre-vingts jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Et quand ces jours furent passés, le roi donna à tout le peuple qui se trouvait dans Suse, la ville capitale, depuis le grand jusqu\'au petit, un banquet de sept jours dans la cour du jardin de la demeure royale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Des draperies de lin blanc et d\'azur y étaient suspendues avec des cordons de byssus et de pourpre à des anneaux d\'argent et à des colonnes de marbre; des divans d\'or et d\'argent couvraient un parquet d\'albâtre et de marbre et de perles et d\'écaille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Et l\'on versait à boire dans des vases d\'or, et il y avait variété de vaisselle, et le vin royal en abondance, à la façon des rois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Et ordre était donné de ne point forcer à boire, car ainsi l\'avait prescrit le roi à tous les grands officiers de sa maison, de faire selon le gré de chacun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'De son côté, la reine Vasthi donna un banquet de femmes dans la demeure royale du roi Assuérus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Le septième jour, comme le vin avait mis le cœur du roi en belle humeur, il ordonna à Mehuman, Biztha, Harbona, Bigtha et Abagtha, Zéther et Charcas, les sept eunuques qui étaient de service devant le roi Assuérus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'd\'amener la reine Vasthi devant le roi, avec la couronne royale, pour faire voir sa beauté aux peuples et aux Grands, car elle avait une belle figure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Mais la reine Vasthi refusa de se rendre à l\'ordre du roi, porté par les eunuques. Alors le roi fut fort irrité, et la colère bouillonnait au dedans de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Et le roi s\'adressa aux sages qui avaient la connaissance des temps (car ainsi se traitaient les affaires du roi devant tous les jurisconsultes et hommes de loi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'et le plus près de lui étaient Charsena, Séthar, Admatha, Tharsis, Mérès, Marsena, Memuchan, les sept seigneurs de Perse et de Médie qui avaient la faculté de voir la face du roi et occupaient la première place dans le royaume):');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Aux termes de la loi que faut-il faire à la reine Vasthi pour n\'avoir pas exécuté l\'ordre du roi Assuérus, porté par les eunuques?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Alors Memuchan dit devant le roi et les Grands: Ce n\'est pas au roi seul que la reine Vasthi a manqué, mais à tous les Grands et à toutes les populations de toutes les provinces du roi Assuérus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Car l\'acte de la reine se répandra chez toutes les femmes pour leur faire mépriser leurs maris, puisqu\'elles diront: Le roi Assuérus a dit d\'amener la reine Vasthi devant lui, et elle n\'est pas venue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Et aujourd\'hui même les dames des Perses et des Mèdes, qui ont entendu la réponse de la reine, la répéteront à tous les Grands du roi, et il y aura assez de mépris et de colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Si c\'est l\'agrément du roi, qu\'il émane de lui une ordonnance royale, qui soit consignée dans les lois de Perse et de Médie pour ne pas se perdre: que Vasthi ne se présente plus devant le roi Assuérus, et que le roi confère sa qualité de reine à une autre, meilleure qu\'elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Et l\'ordonnance du roi qui sera portée dans tout son royaume, car il est grand, une fois entendue, toutes les femmes rendront honneur à leurs maris, du grand au petit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Et la proposition plut au roi et aux Grands, et le roi fit ce que Memuchan avait proposé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Et il expédia des lettres à toutes les provinces du roi, dans l\'écriture de chaque province, et dans l\'idiome de chaque peuple; elles portaient: que chaque mari devait être maître dans sa maison, et parlerait la langue de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Après ces choses, lorsque la colère du roi Assuérus se fut calmée, il repensa à Vasthi, et à ce qu\'elle avait fait, et à ce qu\'il avait décidé à son sujet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Alors les écuyers du roi, qui étaient à son service, dirent: Que l\'on cherche pour le roi de jeunes vierges, belles de figure,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'et que le roi prépose des commissaires dans toutes les provinces de son empire, chargés de rassembler toutes les vierges, belles de figure, dans la ville capitale de Suse, à la maison des femmes sous l\'autorité de Hégaï, eunuque du roi, gardien des femmes, qui leur donnera leurs cosmétiques,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'et que la jeune fille qui plaira au roi devienne reine à la place de Vasthi. Et l\'avis eut l\'agrément du roi, qui le suivit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Cependant il y avait dans Suse, la ville capitale, un Juif, nommé Mardochée, fils de Jaïr, fils de Siméï, fils de Kis, homme de Benjamin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'lequel avait été emmené de Jérusalem avec les captifs déportés avec Jéchonias, roi de Juda, qu\'avait emmené Nebucadnetsar, roi de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Et il était tuteur de Hadassa, c\'est-à-dire Esther, fille de son oncle, car elle n\'avait plus ni père ni mère. Et la jeune fille était belle de figure et avait bon air. Et à la mort de son père et de sa mère, Mardochée l\'avait adoptée pour fille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Et lorsque fut publié l\'ordre du roi et son édit, et qu\'un grand nombre de jeunes filles furent rassemblées dans Suse, la ville capitale, sous la garde de Hégaï, il arriva qu\'Esther fut prise et menée au palais du roi, et remise à Hégaï, gardien des femmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Et la jeune fille lui plut et gagna ses bonnes grâces, et il s\'empressa de lui fournir ses cosmétiques et ses aliments, et de lui donner sept suivantes d\'élite de la maison du roi, et il la transféra, elle et ses femmes, dans le meilleur appartement du logis des femmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Esther n\'avait point révélé sa nation, ni sa naissance, car Mardochée lui avait enjoint de n\'en pas faire la révélation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Et journellement Mardochée allait et venait devant la cour du logis des femmes pour apprendre des nouvelles d\'Esther et de ce qui arrivait d\'elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Et quand venait le tour pour chaque jeune fille d\'être admise chez le roi Assuérus, après s\'être traitée selon le régime prescrit aux femmes pendant douze mois (car c\'est le temps que durent leurs ablutions, que six mois elles font avec l\'huile de myrrhe et six mois avec des baumes et d\'autres cosmétiques de femmes),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'alors seulement la jeune fille entrait chez le roi. Et tout ce qu\'elle demandait lui était donné pour s\'en parer en passant du logis des femmes au palais du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Le soir elle entrait et le matin elle retournait dans l\'autre logis des femmes sous la surveillance de Saasgaz, eunuque du roi, gardien des concubines. Elle ne rentrait point chez le roi à moins d\'être désirée par le roi et appelée nominativement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Et lorsque vint le tour d\'Esther, fille d\'Abihaïl, oncle de Mardochée qui l\'avait adoptée pour fille, de venir chez le roi, elle ne demanda rien autre que ce que désigna Hégaï, eunuque du roi, gardien des femmes. Et Esther gagnait les bonnes grâces de tous ceux qui la voyaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Et Esther fut amenée chez le roi Assuérus, dans son palais royal, le dixième mois qui est le mois de Tébeth, la septième année de son règne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Et le roi éprouva pour Esther plus d\'amour que pour toutes les autres femmes, et elle gagna sa faveur et ses bonnes grâces plus que toutes les autres jeunes filles. Et il posa la couronne royale sur sa tête et la fit reine en place de Vasthi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Et le roi donna un grand festin à tous ses Grands et serviteurs, le festin d\'Esther, et accorda un relâche aux provinces et fit des présents à la façon d\'un roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Et lorsque les jeunes filles furent rassemblées pour la seconde fois, Mardochée était assis à la porte du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Esther n\'avait point révélé sa naissance ni son peuple, comme Mardochée le lui avait commandé; et Esther exécutait les ordres de Mardochée, comme quand elle était sous sa tutelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'Dans ce même temps, comme Mardochée était assis à la porte du roi, Bigthan et Thérès, deux eunuques du roi, des gardes du seuil, s\'exaspérèrent, et ils tentèrent de porter la main sur le roi Assuérus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Et la chose vint à la connaissance de Mardochée qui en informa la reine Esther. Et Esther le redit au roi de la part de Mardochée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Et le fait fut soumis à une enquête, et trouvé tel, et ils furent tous les deux pendus à un arbre. Et cela fut consigné dans le livre des annales devant le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Après ces événements, le roi Assuérus agrandit Aman, fils de Medatha, l\'Agagite, et il l\'éleva et plaça son siège au-dessus de tous les Grands de son entourage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Et tous les serviteurs du roi qui se tenaient à la porte du roi, se courbaient et se prosternaient devant Aman, car tel était l\'ordre du roi à son égard. Mais Mardochée ne se courbait, ni ne se prosternait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Alors les serviteurs du roi qui se tenaient à la porte du roi, dirent à Mardochée: Pourquoi contreviens-tu à l\'ordre du roi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Et comme ils le lui disaient chaque jour, et qu\'il ne les écoutait point, ils informèrent Aman pour voir si les discours de Mardochée tiendraient. Car il leur avait découvert qu\'il était Juif.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Et Aman voyant que Mardochée ne se courbait ni ne se prosternait devant lui, il fut rempli de fureur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Mais Aman trouvait indigne de lui de mettre la main sur Mardochée seul; car on lui avait découvert quel était le peuple de Mardochée, et Aman chercha à exterminer tous les Juifs qui se trouvaient dans tout l\'empire d\'Assuérus, le peuple de Mardochée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Au premier mois, qui est le mois de Nisan, la douzième année du roi Assuérus, on consulta le Pur, c\'est-à-dire le sort, devant Aman pour tous les jours et pour tous les mois jusqu\'au douzième mois qui est le mois d\'Adar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Et Aman dit au roi Assuérus: Il est un peuple séparé, et disséminé parmi les peuples dans toutes les provinces de ton empire, dont les lois diffèrent de celles de tous les peuples, et il ne pratique point les lois du roi; et il ne convient point au roi de le tolérer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Si le roi le trouve bon, qu\'on rédige l\'édit de leur destruction; et je paierai dix mille talents d\'argent pesant, entre les mains des intendants pour les faire entrer au trésor royal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Alors le roi tira son anneau de son doigt, et le donna à Aman, fils de Medatha, l\'Agagite, l\'ennemi des Juifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Et le roi dit à Aman: L\'argent t\'est donné, le peuple aussi, pour que tu en fasses ce que tu voudras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Alors furent convoqués les Secrétaires du roi, le premier mois, le treizième jour du mois, et l\'on écrivit en tout point dans le sens que prescrivait Aman, aux satrapes du roi et aux gouverneurs de chaque province, et aux chefs de chaque peuple, province par province, dans leur écriture, et peuple par peuple, dans sa langue; c\'est au nom du roi Assuérus que l\'on écrivit, et on scella avec l\'anneau du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Et des lettres furent expédiées par courriers dans toutes les provinces du roi, à l\'effet d\'exterminer, massacrer et faire périr tous les Juifs, de l\'adolescent au vieillard, petits enfants et femmes, en un jour, le treizième du douzième mois, c\'est-à-dire du mois d\'Adar, et de livrer leurs dépouilles au pillage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Une copie du rescrit, afin que l\'ordre fût donné dans toutes les provinces, fut communiquée à tous les peuples, afin qu\'ils se tinssent prêts pour cette journée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Les courriers partirent aussitôt sur l\'ordre du roi, et l\'édit fut promulgué dans Suse, la ville capitale. Et le roi et Aman s\'attablèrent et burent; mais toute la ville de Suse était dans la consternation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Et lorsque Mardochée apprit tout ce qui s\'était fait, il déchira ses habits, et revêtit le cilice et la cendre, et parut au milieu de la ville et poussa un haut et lamentable cri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Et il vint jusque devant la porte du roi, car il n\'était pas permis d\'entrer en cilice dans la porte du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Et dans toutes les provinces où parvinrent l\'ordre du roi et son édit, il y eut une grande désolation parmi les Juifs, et jeûne et pleurs et deuil, et beaucoup se couvrirent du cilice et de la cendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Et les compagnes d\'Esther et ses eunuques vinrent l\'informer. Alors la reine fut dans une angoisse extrême, et elle envoya des habits pour en vêtir Mardochée, et lui faire déposer le cilice, mais il ne les accepta pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Alors Esther appela Hathach, l\'un des eunuques que le roi avait placés auprès d\'elle, et le dépêcha à Mardochée pour savoir ce que c\'était et à quel sujet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Et Hathach alla trouver Mardochée dans la Place de la ville, qui est devant la porte du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Et Mardochée lui raconta tout ce qui lui était survenu, en indiquant la somme d\'argent qu\'Aman avait promis de payer pour le prix des Juifs au trésor du roi, afin de les détruire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Et il lui remit aussi la copie du rescrit publié dans Suse pour leur massacre, afin qu\'il le montrât à Esther, qu\'il la mît au fait de tout, et lui enjoignît de se rendre chez le roi pour implorer sa pitié et le prier en faveur de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Et Hathach vint rapporter à Esther les paroles de Mardochée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Et Esther répondant à Hathach lui donna ce message pour Mardochée:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Tous les serviteurs du roi et les peuples des provinces du roi savent que quiconque, homme et femme, entre chez le roi dans la cour intérieure, sans être appelé, est, en vertu d\'une loi spéciale, passible de la mort, à moins que le roi ne lui tende son sceptre d\'or pour lui laisser la vie. Or je n\'ai point été appelée à entrer chez le roi voici trente jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Et l\'on rapporta à Mardochée les paroles d\'Esther.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Et Mardochée renvoya cette réponse à Esther: Ne te figure pas en ton âme pouvoir être sauvée dans le palais du roi plus que tous les Juifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Que si tu restais neutre à cette heure-ci, le secours et la délivrance arriveraient aux Juifs d\'autre part, et toi et la maison de ton père vous péririez. Et qui sait si ce n\'est pas pour cette heure-ci que tu es parvenue au rang de reine?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Et Esther dit en réponse à Mardochée:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Va et rassemble tous les Juifs qui se trouvent dans Suse, et jeûnez pour moi, et ne mangez ni ne buvez pendant trois jours, ni jour, ni nuit. Moi aussi avec mes compagnes je jeûnerai de même, et ensuite j\'irai chez le roi, malgré la loi; et si je péris, je périrai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Et Mardochée s\'en alla et exécuta tous les ordres que lui donnait Esther.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Et le troisième jour Esther prit son costume de reine et se présenta dans la cour intérieure du palais royal vis-à-vis de la demeure du roi. Et le roi était assis sur son trône royal dans le palais royal, en face de l\'entrée du palais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Et quand le roi vit la reine Esther arrêtée dans la cour, elle trouva grâce à ses yeux; et le roi tendit vers Esther le sceptre d\'or qui était dans sa main, et Esther s\'avança et toucha le bout du sceptre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Et le roi lui dit: Que veux-tu, reine Esther? et qu\'est-ce que tu demandes? quand ce serait la moitié de mon royaume, tu l\'obtiendrais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Et Esther dit: Si le roi l\'agrée, que le roi avec Aman vienne aujourd\'hui au banquet que je lui ai préparé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Et le roi dit: Vite, allez chercher Aman pour faire ce qu\'a dit Esther. Le roi et Aman vinrent donc au banquet qu\'Esther avait préparé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Et le roi dit à Esther, lorsque l\'on but le vin: Quelle est ta demande? elle te sera accordée; et quel est ton désir? quand ce serait la moitié de mon royaume, il sera satisfait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Alors Esther répondit et dit: Voici ce que je demande et désire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Si j\'ai trouvé grâce aux yeux du roi, et s\'il plaît au roi de m\'accorder ma demande et de satisfaire mon désir, que le roi avec Aman vienne au banquet que je veux préparer pour eux, et demain je ferai réponse à la question du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Et Aman sortit ce jour-là joyeux et de bonne humeur; mais lorsqu\'Aman aperçut Mardochée dans la porte du roi, sans qu\'il se levât et se courbât devant lui, Aman fut rempli de fureur contre Mardochée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Mais Aman se contint. Et arrivé à la maison, il manda ses amis et Zérès, sa femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Et Aman leur fit le détail de sa magnifique opulence, du nombre de ses fils, et de toute la grandeur que le roi lui avait donnée, et du rang où il l\'avait élevé plus haut que les Grands et les serviteurs du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Aman dit encore: Bien plus, la reine Esther m\'a admis avec le roi au banquet qu\'elle nous a donné, sans personne autre que moi, et même pour demain je suis invité chez elle avec le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Mais tout cela m\'est indifférent tant que je vois Mardochée, le Juif, assis dans la porte du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Alors Zérès, sa femme et tous ses amis lui dirent: Que l\'on dresse un poteau, haut de cinquante coudées, et demain demande au roi qu\'on y pende Mardochée, puis tu accompagneras le roi au festin, content. Et la proposition plut à Aman, qui fit dresser le poteau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Cette nuit-là le sommeil fuyait le roi, et il dit qu\'on lui apportât le livre mémorial, les annales; et il en fut fait, lecture devant le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Là se trouvait consignée la révélation faite par Mardochée au sujet de Bigthan et Thérès, les deux eunuques du roi d\'entre les gardes du seuil, qui avaient cherché à porter la main sur le roi Assuérus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Et le roi dit: Quel prix et quel honneur Mardochée a-t-il obtenus pour cela? Et les écuyers du roi qui étaient de service auprès de lui, dirent: Il n\'a rien reçu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Et le roi dit: Qui est dans la cour? Or Aman arrivait dans la cour extérieure du palais royal, pour proposer au roi de faire pendre Mardochée au poteau qu\'il avait préparé pour lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Et les écuyers du roi lui dirent: Voilà, c\'est Aman qui est dans la cour. Et le roi dit: Qu\'il entre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Et Aman entra, et le roi lui dit: Que faut-il faire à un homme que le roi veut récompenser? Et Aman disait en son cœur: Qui est-ce que le roi voudrait récompenser sinon moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Et Aman dit au roi: L\'homme que le roi veut récompenser!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'il faut apporter un habillement royal dont le roi se revêt, et le cheval que le roi monte, et sur la tête duquel on place la couronne royale,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'puis remettre l\'habillement et le cheval à quelqu\'un des Grands du roi, des nobles, et revêtir l\'homme que le roi veut récompenser, et le promener monté sur le cheval dans les rues de la ville en criant devant lui: Ainsi est traité l\'homme que le roi veut récompenser!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Et le roi dit à Aman: Vite, prends l\'habillement et le cheval, comme tu as dit, et fais ainsi pour Mardochée, le Juif, qui est assis dans la porte du roi; n\'omets aucun des points que tu as indiqués.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Alors Aman prit l\'habillement et le cheval, et revêtit Mardochée et le conduisit par les rues de la ville en criant devant lui: Ainsi est traité l\'homme que le roi veut récompenser!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Et Mardochée revint à la porte du roi, mais Aman regagna en hâte sa maison, triste et la tête voilée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Et Aman raconta à Zérès, sa femme, et à tous ses amis tout ce qui lui était arrivé. Alors ses sages et Zérès, sa femme, lui dirent: Si Mardochée, devant qui tu as commencé de tomber, est de la race des Juifs, tu ne l\'emporteras pas sur lui, mais c\'est toi qui tomberas devant lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Ils s\'entretenaient encore avec lui, lorsque arrivèrent les eunuques du roi, qui se hâtèrent de conduire Aman au banquet préparé par Esther.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Et le roi avec Aman se rendit au banquet chez la reine Esther.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Et le roi dit encore à Esther le second jour, quand on servait le vin: Quelle est ta demande, reine Esther? elle te sera accordée; et quel est ton désir? fût-ce la moitié de mon royaume, il sera satisfait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Alors la reine Esther répondit et dit: Si j\'ai trouvé grâce à tes yeux, ô roi, et si c\'est le bon plaisir du roi, que ma vie soit accordée à ma prière, et mon peuple à ma requête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Car nous sommes vendus, moi et mon peuple, à l\'extermination, au massacre et à l\'assassinat. Et si nous étions vendus pour devenir serviteurs et servantes, je me tairais, mais l\'ennemi n\'est pas à même de compenser le dommage fait au roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Alors le roi Assuérus parla et dit à la reine Esther: Qui est donc celui, et où est celui qui a l\'audace d\'agir de la sorte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Et Esther dit: L\'homme hostile et l\'ennemi, — c\'est Aman, c\'est ce méchant-là! Et Aman fut atterré en présence du roi et de la reine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Et le roi se leva dans son courroux, et, quittant le repas, il gagna le jardin du palais; mais Aman resta pour solliciter en faveur de sa vie auprès de la reine Esther, car il voyait que sa ruine était consommée par devers le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Et quand le roi revint du jardin du palais dans la salle du festin, Aman était tombé au pied du lit sur lequel était Esther. Alors le roi dit: Veut-il même faire violence à la reine à mes côtés, au palais? Le mot sorti de la bouche du roi, on voila le visage d\'Aman.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Et Harbona, l\'un des eunuques, dit devant le roi: Vois aussi, le poteau qu\'Aman a fait faire pour Mardochée qui a parlé pour le bien du roi, est dressé dans la demeure d\'Aman avec la hauteur de cinquante coudées. Alors le roi dit: Pendez-l\'y!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Et l\'on pendit Aman au poteau qu\'il avait préparé pour Mardochée, et la colère du roi fut apaisée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'En ce même jour le roi Assuérus fit don à la reine Esther de la maison d\'Aman, l\'ennemi des Juifs; et Mardochée vint se présenter au roi, car Esther avait révélé au roi ce qu\'il lui était.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Et le roi tira son anneau, qu\'il avait ôté à Aman, et le donna à Mardochée. Et Esther préposa Mardochée sur la maison d\'Aman.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Et derechef Esther parla devant le roi, et elle se jeta à ses pieds? et pleura et le supplia de déjouer la méchanceté d\'Aman, l\'Agagite, et les complots qu\'il avait tramés contre les Juifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Et le roi tendit à Esther le sceptre d\'or; alors Esther se releva, et se tint debout devant le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Et elle dit: Si le roi le trouve bon, et si j\'ai trouvé grâce à ses yeux, et si la chose a l\'approbation du roi, et si j\'ai son agrément, que l\'on écrive pour révoquer les lettres d\'Aman, et le plan d\'Aman, fils de Medatha, l\'Agagite, lettres qu\'il a écrites à l\'effet d\'exterminer les Juifs qui sont dans toutes les provinces du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Car comment pourrais-je être témoin du désastre qui atteindrait mon peuple? et comment pourrais-je être témoin de l\'anéantissement de ma race?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Et le roi Assuérus dit à la reine Esther et à Mardochée, le Juif: Voilà que j\'ai fait don à Esther de la maison d\'Aman, et il a été pendu à un poteau pour avoir levé la main sur les Juifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Ecrivez donc à l\'égard des Juifs, comme il vous semblera bon, au nom du roi, et apposez le sceau avec l\'anneau du roi. Car un rescrit, écrit au nom du roi et scellé avec l\'anneau du roi, est irrévocable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Alors furent mandés les Secrétaires du roi, dans ce même temps, au troisième mois, c\'est-à-dire au mois de Sivan, le vingt-troisième jour de ce mois, et l\'on écrivit en tout point comme Mardochée le prescrivit, aux Juifs et aux satrapes, et aux gouverneurs, et aux chefs des provinces, de l\'Inde à l\'Ethiopie, des cent vingt-sept provinces, province par province, dans son écriture, et peuple par peuple dans sa langue, et aussi aux Juifs, dans leur écriture et leur langue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Et Mardochée écrivit au nom du roi Assuérus et scella avec l\'anneau du roi et expédia les lettres par des courriers à cheval, montés sur des coursiers, des mulets, faons de cavales,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, '[lettres portant] que le roi permettait aux Juifs de se rassembler dans toutes et chaque villes, et de défendre leur vie, et d\'exterminer et de massacrer et de tuer toute force armée du peuple et de la province qui les assaillirait, enfants et femmes, et de piller leurs dépouilles');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'le même jour dans toutes les provinces du roi Assuérus le troisième jour du douzième mois, c\'est-à-dire du mois d\'Adar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Une copie du rescrit fut, afin que l\'ordre circulât dans toutes les provinces, communiquée à tous les peuples, à cet effet que les Juifs se tinssent prêts pour ce jour-là à se venger de leurs ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Les courriers montés sur des coursiers et des mulets partirent de suite et en hâte sur la parole du roi, et l\'ordre fut donné dans Suse, la ville capitale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Et Mardochée se retira de la présence du roi, en costume royal, azur et blanc, avec une grande couronne d\'or et un manteau de byssus et de pourpre. Et la ville de Suse poussa des cris de joie et fut dans l\'allégresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Pour les Juifs il y eut clarté et joie, et transports, et honneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Et dans toutes et chaque provinces et dans toutes et chaque villes où parvint le prononcé du roi et son édit, il y eut joie et ravissement pour les Juifs, banquet et réjouissance. Et un grand nombre des indigènes devinrent Juifs, car la terreur des Juifs les avait assaillis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Et au douzième mois, c\'est-à-dire au mois d\'Adar, le treizième jour du mois, jour où s\'exécuta le prononcé et l\'ordre du roi, le jour où les ennemis des Juifs espéraient venir à bout d\'eux, et où les choses tournèrent de telle sorte que ce furent les Juifs qui vinrent à bout de leurs adversaires,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'les Juifs se rassemblèrent dans leurs villes, dans toutes les provinces du roi Assuérus pour faire main basse sur ceux qui cherchaient leur ruine; et personne ne leur tint, tête, car tous les peuples subissaient la terreur qu\'ils donnaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Et tous les chefs des provinces et les satrapes et les gouverneurs et les agents du roi soutinrent les Juifs, car Mardochée leur inspirait la terreur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'En effet, grand était Mardochée au Palais et sa renommée se répandait dans toutes les provinces, parce que la personne de Mardochée allait toujours grandissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Et les Juifs battirent tous leurs ennemis à coups d\'épée, et ce fut un massacre et une extermination, et ils traitèrent leurs adversaires à leur discrétion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Et dans Suse, la ville capitale, les Juifs tuèrent et firent périr cinq cents hommes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'et Parsandatha et Dalphon et Aspatha');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'et Poratha et Adalia et Aridatha');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'et Parmaslha et Arisaï et Aridaï et Vajezatha,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'les dix fils d\'Aman, fils de Medatha, l\'ennemi des Juifs, furent égorgés par eux, mais ils ne touchèrent pas au butin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Le même jour, le nombre des hommes tués dans Suse, la ville capitale, fut porté devant le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Et le roi dit à la reine Esther: Dans Suse, la ville capitale, les Juifs ont tué et massacré cinq cents hommes, et les dix fils d\'Aman: qu\'auront-ils fait dans les autres provinces du roi? Et quelle est ta demande? elle te sera accordée; et ton désir encore? et il sera satisfait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Et Esther dit: S\'il plaît au roi, que demain aussi il soit permis aux Juifs dans Suse d\'agir d\'après l\'ordre d\'aujourd\'hui; et que les dix fils d\'Aman soient pendus au poteau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Et le roi ordonna qu\'ainsi fût fait. Et l\'ordre fut donné dans Suse, et les dix fils d\'Aman furent pendus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Les Juifs se rassemblèrent donc aussi dans Suse le quatorzième jour du mois d\'Adar et massacrèrent dans Suse trois cents hommes, mais ils ne touchèrent point au butin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'De même, les autres Juifs dans les provinces du roi se rassemblèrent et défendirent leur vie, et conquirent le repos sur leurs ennemis, et tuèrent soixante-quinze mille de leurs adversaires, mais ils ne touchèrent point au butin:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'c\'était le treizième jour du mois d\'Adar. Et le quatorzième jour de ce mois, ils avaient le repos, et ils en firent un jour de festins et de réjouissances.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Et les Juifs dans Suse se rassemblèrent le treizième jour et aussi le quatorzième jour et eurent le repos le quinzième jour de ce mois; et ils en firent un jour de festins et de réjouissances.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'C\'est pourquoi les Juifs de la campagne habitant les villes du pays plat font du quatorzième jour du mois d\'Adar un jour de réjouissances et de festins et un jour de fête et dans lequel l\'on s\'envoie mutuellement des mets.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Et Mardochée rédigea par écrit ces histoires, et il adressa des lettres à tous les Juifs dans toutes les provinces du roi Assuérus, rapprochées et éloignées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'pour leur poser comme règle de célébrer chaque année le quatorzième jour et le quinzième du mois d\'Adar,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'comme jours auxquels les Juifs avaient conquis le repos sur leurs ennemis, et comme le mois où il y avait eu pour eux changement d\'affliction en joie et de deuil en fête, pour les célébrer comme jours de festins et de réjouissances, et où l\'on s\'envoie mutuellement des mets, et où l\'on fait des dons aux pauvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Et les Juifs adoptèrent ce qu\'ils avaient commencé de faire et que Mardochée leur prescrivait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'C\'est que Aman, fils de Medatha, l\'Agagite, l\'ennemi de tous les Juifs, avait formé contre les Juifs le plan de les anéantir, et avait tiré au Pur, c\'est-à-dire au sort, en vue de leur désastre et de leur destruction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Et lorsque Esther se présenta devant le roi, il ordonna par lettres que le funeste plan qu\'il avait formé contre les Juifs, retombât sur sa tête, et il fut pendu au poteau, ainsi que ses fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'C\'est pourquoi ils donnèrent à ces jours le nom de Purim d\'après le mot Pur. C\'est pourquoi ensuite de toute la teneur de cette lettre, et ensuite de tout ce qu\'ils en avaient vu et de ce qui leur était arrivé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'les Juifs fixèrent et adoptèrent pour eux et leur postérité et pour tous ceux qui s\'attacheraient à eux, l\'usage inviolable de célébrer ces deux jours selon la règle écrite et à l\'époque déterminée, chaque année,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'et ces jours devaient rester dans la mémoire et être célébrés dans toutes et chaque générations, dans chaque famille, dans chaque province et dans chaque ville; et ces jours du Purim devaient ne jamais se perdre parmi les Juifs et leur souvenir ne pas s\'effacer dans leur race.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Et la reine Esther, fille d\'Abihaïl, et Mardochée, le Juif, écrivirent avec toute leur autorité pour confirmer cette seconde lettre concernant le Purim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Et l\'on adressa des lettres à tous les Juifs dans les cent vingt-sept provinces de l\'empire d\'Assuérus, des paroles de paix et de fidélité');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'pour consolider ces jours du Purim, à l\'époque précise, comme Mardochée, le Juif, et la reine Esther les avaient institués, et comme ils avaient établi pour eux-mêmes et leur postérité, la règle de leur jeûne et de leur cri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Et l\'ordre d\'Esther confirma cette institution du Purim et fut consigné dans un livre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Et le roi Assuérus imposa une corvée au pays et aux îles de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Et tous les actes de son autorité et de sa puissance, et l\'exposé de la grandeur de Mardochée, à laquelle le roi l\'avait élevé, sont d\'ailleurs consignés dans le livre des Annales des rois des Mèdes et Perses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Car Mardochée, le Juif, était le second après le roi Assuérus, et il était grand auprès des Juifs, et agréable à la multitude de ses frères, cherchant le bien de son peuple et parlant pour le salut de toute sa race.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Il y avait un homme dans le pays de Uz; Job était son nom, et cet homme était intègre et droit et craignant Dieu et fuyant le mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Et il lui était né sept fils et trois filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Et son bétail consistait en sept mille brebis, et trois mille chameaux, et cinq cents paires de bœufs, et cinq cents ânesses, et il avait un domestique nombreux, et cet homme était plus grand que tous les enfants de l\'Orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Or ses fils avaient la coutume de faire un festin dans leur maison chacun son jour; et ils envoyaient et invitaient leurs trois sœurs à manger et boire avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Et, quand le tour des jours du festin était terminé, Job les envoyait chercher, et les purifiait, et se levant matin, il offrait des holocaustes selon le nombre d\'eux tous; car, disait Job, peut-être mes fils ont-ils péché et renié Dieu en leur cœur. Ainsi faisait Job en tout temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Et il arriva, un jour où les Fils de Dieu vinrent se présenter devant l\'Éternel, que Satan vint aussi parmi eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Et l\'Éternel dit à Satan: « D\'où viens-tu? » Et Satan répondit à l\'Éternel et dit: « De parcourir la terre, et de m\'y promener. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Et l\'Éternel dit à Satan: « As-tu pris garde à mon serviteur Job? Car nul n\'est comme lui, sur la terre, intègre et droit et craignant Dieu et fuyant le mal. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Et Satan répondit à l\'Éternel et dit: « Est-ce sans intérêt que Job craint Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Ne l\'as-tu pas protégé lui et sa maison, et tout ce qui est à lui, de toutes parts? Tu as béni le travail de ses mains, et ses troupeaux se sont répandus dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Mais étends donc ta main, et touche tout ce qu\'il a, et tu verras s\'il ne te renie pas en face. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Et l\'Éternel dit à Satan: « Voici, que tout ce qu\'il a, soit en ta main; seulement ne mets point la main sur lui. » Et Satan sortit de la présence de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Et, le jour où ses fils et ses filles mangeaient et buvaient du vin dans la maison de leur frère premier-né,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'il arriva à Job un messager qui lui dit: « Les bœufs étaient à la charrue, et les ânesses paissaient à leurs côtés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'alors des Sabéens ont fondu sur eux, et les ont pris, et ont passé les gardiens au fil de l\'épée, et seul j\'ai pu m\'échapper pour te l\'annoncer. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Il parlait encore, qu\'un autre vint et dit: « Le feu de Dieu est tombé du ciel, et a exercé ses ravages parmi les brebis et les gardiens, et les a dévorés, et seul j\'ai pu m\'échapper pour te l\'annoncer. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Il parlait encore, qu\'un autre vint et dit: « Des Chaldéens, formés en trois bandes, se sont jetés sur les chameaux, les ont pris, et ont passé les gardiens au fil de l\'épée, et seul j\'ai pu m\'échapper pour te l\'annoncer. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Il parlait encore, qu\'un autre vint et dit: « Tes fils et tes filles mangeaient et buvaient du vin dans la maison de leur frère premier-né,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'et voici, un grand vent est venu de par delà le désert, et a frappé contre les quatre angles de la maison, et elle s\'est écroulée sur les jeunes gens, et ils sont morts, et seul j\'ai pu m\'échapper pour te l\'annoncer. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Alors Job se leva, et déchira son manteau, et se rasa la tête, et tombant contre terre il adora');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'et dit: « Nu je suis sorti du sein de ma mère, et nu je retournerai d\'où j\'ai été tiré: l\'Éternel avait donné, l\'Éternel a repris; béni soit le nom de l\'Éternel! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'A tous ces coups Job ne pécha point, et n\'attribua point de mal à Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Et il arriva, un jour où les Fils de Dieu vinrent se présenter devant l\'Éternel, que Satan vint aussi parmi eux se présenter devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Et l\'Éternel dit à Satan: « D\'où viens-tu? » « Et Satan répondit à l\'Éternel et dit: « De parcourir la terre, et de m\'y promener. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Et l\'Éternel dit à Satan: « As-tu pris garde à mon serviteur Job? Car nul n\'est comme lui, sur la terre, homme intègre et droit et craignant Dieu et fuyant le mal; il est encore ferme dans sa piété, et tu m\'excites à le perdre gratuitement. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Et Satan répondit à l\'Éternel et dit: « Peau pour peau! Mais tout ce que l\'homme possède, il le donnera pour sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Or étends donc ta main, et touche à ses os et à sa chair, et tu verras s\'il ne te renie pas en face. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Et l\'Éternel dit à Satan: « Le voilà entre tes mains! seulement conserve-lui la vie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Alors Satan sortit de la présence de l\'Éternel, et il frappa Job d\'un ulcère malin depuis la plante des pieds jusqu\'au sommet de la tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Et il prit un têt pour se gratter, tandis qu\'il était assis sur la cendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Et sa femme lui dit: « Tu es encore ferme dans ta piété! » renie Dieu, et meurs! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Et Job lui dit: « Ainsi que parle une insensée, ainsi parles-tu. Quoi! nous recevons les biens de la main de Dieu, et nous n\'en recevrions pas les maux! » Malgré tout cela, Job ne pécha point par ses discours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Et trois amis de Job ouïrent parler de tous ces maux qui lui étaient survenus, et ils vinrent chacun de leur lieu, Eliphaz de Théman, Bildad de Such, et Tsophar de Naama, et ils se concertèrent ensemble pour venir plaindre Job et le consoler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Et, lorsqu\'ils levèrent les yeux de loin, ils ne le reconnurent pas, et élevant la voix, ils pleurèrent, et ils déchirèrent chacun leur manteau, et jetèrent de la poussière au-dessus de leur tête en l\'air.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Et ils furent assis avec lui sur la terre, sept jours et sept nuits, et aucun d\'eux ne lui disait une parole, car ils voyaient que sa douleur était très grande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Après cela Job ouvrit la bouche, et maudit le jour de sa naissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Et Job prit la parole et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Périsse le jour où je suis né, et la nuit qui dit: Un enfant est conçu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Que ce jour se change en ténèbres, que Dieu d\'en haut ne s\'en informe plus! et que sur lui la clarté ne resplendisse plus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Que l\'obscurité et l\'ombre de mort le réclament, que les sombres nuées viennent s\'y établir, et que l\'absence de jour y répande l\'effroi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Cette nuit! que les ténèbres s\'en emparent, qu\'elle ne se réjouisse plus parmi les jours de l\'année, et que dans le compte des mois elle n\'entre plus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Voici, que cette nuit soit inféconde, que l\'allégresse n\'y ait plus accès!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Qu\'elle soit notée par ceux qui maudissent les jours, experts à faire lever le Léviathan!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Que les astres de son crépuscule s\'éteignent! qu\'elle espère la lumière, et qu\'elle ne vienne pas, et que jamais elle ne voie les paupières de l\'aurore,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'car elle ne ferma point le sein dont j\'ai franchi les portes, et n\'a point dérobé le chagrin à ma vue!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Pourquoi ne quittai-je pas sans vie les flancs de ma mère, et au sortir de son sein n\'expirai-je pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Pourquoi rencontrai-je des genoux devant moi, et pourquoi des mamelles où je fusse allaité?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Car maintenant je serais gisant et tranquille, je dormirais, et aurais aussi le repos,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'avec les Rois et les arbitres de la terre qui se sont élevé des tombes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'ou avec les Princes qui possédaient de l\'or, et ont rempli d\'argent leurs habitations;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'ou, tel que l\'avorton enfoui, je ne serais pas, tel que les enfants qui n\'ont pas vu le jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Là les impies cessent de s\'agiter, là se reposent ceux qui sont fatigués d\'efforts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'là sont réunis les captifs en sécurité, et ils n\'entendent pas la voix de l\'exacteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Petits et grands y sont égaux, et l\'esclave y est affranchi de son maître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Pourquoi accorde-t-Il la lumière au misérable, et la vie à ceux qui ont l\'amertume dans l\'âme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'qui attendent la mort, et elle n\'arrive pas, qui creusent la terre, plus désireux d\'elle que des trésors,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'qui se réjouissent jusqu\'à l\'allégresse, sont transportés, quand ils trouvent un tombeau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'à l\'homme enfin, à qui son chemin se dérobe, et que Dieu cerne de toutes parts?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Car le pain que je mange, rencontre mes sanglots, et, comme les flots, mes soupirs s\'épanchent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'car la terreur que je crains, m\'assaille aussitôt, et ce que je redoute, c\'est ce qui m\'arrive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Je n\'ai ni trêve, ni calme, ni repos, et toujours le trouble survient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Et Eliphaz de Théman répondit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Tenter de te parler, sera-ce t\'être importun? Mais qui pourrait s\'empêcher de parler?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Voici, tu redressas beaucoup d\'hommes, et fortifias des mains débiles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'ta parole releva ceux qui bronchaient, et tu raffermis les genoux qui pliaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Maintenant que ton tour vient, tu faiblis! maintenant que tu es atteint, tu es éperdu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'En ta crainte de Dieu ne te confies-tu pas, et ton espoir n\'est-il pas l\'innocence de ta vie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Eh! penses-y! quel innocent a péri, et où les justes ont-ils été détruits?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Ainsi que je l\'ai vu, ceux qui cultivent le mal, et sèment la malice, l\'ont pour récolte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'au souffle de Dieu ils périssent, et le vent de son courroux les consume;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'le cri du lion, et la voix du rugissant, et les dents des lionceaux leur sont ôtés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'le vieux lion périt faute de proie, et les petits de la lionne sont dispersés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Mais une parole me fut dite à la dérobée, et mon oreille en a saisi le murmure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Les visions de la nuit agitaient mes pensées, à l\'heure où le sommeil accable les humains:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'une terreur me saisit avec un tremblement, et le frisson parcourut tous mes os;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'et un esprit passa devant mon visage, et sur mon corps mes cheveux se dressèrent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'une figure dont l\'air m\'est inconnu, s\'arrêta en face de mes yeux; il y eut un frémissement, et j\'entendis une voix:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, '« L\'homme est-il juste devant Dieu, et le mortel, pur devant son créateur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Voici, de ses serviteurs Il se défie, et dans ses anges mêmes Il trouve du péché;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'que sera-ce donc des habitants de maisons d\'argile, dont les fondements posent sur la poudre? Ils sont détruits comme par la teigne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'd\'un matin à un soir ils sont mis en pièces; sans qu\'on y prenne garde, ils périssent pour toujours;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'leur magnificence ne leur est-elle pas ôtée? Ils meurent, et n\'ont pas la sagesse. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Appelle donc! y aura-t-il quelqu\'un qui te réponde? et auquel des Saints t\'adresseras-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Non, le chagrin tue l\'insensé, et le fou trouve la mort dans sa fureur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'J\'ai vu l\'insensé pousser des racines; mais soudain j\'ai dû dire sa maison maudite:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'ses enfants étaient loin de secours, on les foulait aux Portes, et point de sauveur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'L\'affamé mangea ses moissons, et jusqu\'entre les haies alla les saisir, et des hommes altérés engloutirent ses biens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Car les maux ne sortent point de terre, et sur le sol le malheur ne croît pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'mais l\'homme est né pour le malheur, comme l\'étincelle pour s\'élever et voler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Mais pour moi, je m\'adresserais à Dieu, et j\'exposerais ma cause au Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Il fait des choses grandes, insondables, merveilleuses, innombrables;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Il répand la pluie sur la terre, et envoie ses eaux sur les campagnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Il place en haut lieu les hommes abaissés, et les affligés atteignent le salut;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Il rompt les complots des gens rusés, pour que leurs mains n\'exécutent pas leurs plans;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Il prend les habiles dans leurs ruses, et le projet des astucieux est déjoué;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'de jour ils heurtent contre les ténèbres, et comme dans la nuit ils tâtonnent à midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Ainsi sauve-t-il de l\'épée de leur bouche, et de la main du puissant, le misérable;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'et il y a pour le faible une espérance, et leur méchanceté a la bouche fermée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Voici, heureux l\'homme que Dieu châtie!... Mais ne repousse pas la correction du Seigneur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'car Il blesse, et bande la plaie, Il brise, et ses mains guérissent:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'dans six détresses, Il est ton libérateur, et dans sept, le mal ne t\'atteindra pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'durant la famine, Il te sauve de la mort, et durant la guerre, des coups de l\'épée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'au fouet de la langue tu seras dérobé, tu n\'auras point peur du désastre, s\'il arrive;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'tu te riras du désastre et de la famine, et tu ne redouteras point les bêtes de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'car tu as un pacte avec les pierres des champs, et les bêtes des champs sont en paix avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Alors tu éprouveras que ta tente n\'est que paix, et en visitant ta demeure, tu ne seras point trompé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'et tu éprouveras que ta race est nombreuse, et ta postérité comme l\'herbe de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'tu descendras au sépulcre dans une verte vieillesse, ainsi que s\'élève le tas des gerbes, quand c\'en est la saison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Voilà ce que nous avons approfondi: il en est ainsi; entends-le, et fais-en ton profit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Et Job reprit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'Ah! qu\'on pèse, qu\'on pèse mon tourment! et qu\'on mette mon malheur dans la balance aussi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'car sur le sable des mers il l\'emporte en grandeur: de là mes paroles outrées!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Car je porte sur moi les flèches du Tout-puissant, de leur poison mon cœur est abreuvé; les terreurs de Dieu m\'ont cerné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'L\'onagre brait-il auprès de la verdure? Le taureau mugit-il auprès de son fourrage?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Mange-t-on ce qui est insipide, sans sel? Le blanc de l\'œuf a-t-il une saveur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Mon âme refuse d\'y toucher, et c\'est comme une pourriture qui infecte mon pain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'O, si mon vœu pouvait s\'accomplir, et si Dieu remplissait mon souhait!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'S\'il plaisait à Dieu de m\'écraser, d\'étendre sa main, et de me retrancher!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Ainsi j\'aurais encore une consolation, et une joie dans les maux qu\'il ne m\'épargne pas, car je n\'ai point renié la parole du Dieu Saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Qu\'est-ce que ma force pour attendre? et qu\'est-ce que ma fin, pour patienter?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Ma force est-elle la force de la pierre? mon corps est-il d\'airain?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Par moi-même ne suis-je pas sans ressources, et le secours n\'est-il pas refoulé loin de moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'A l\'affligé son ami doit de l\'affection, sinon il dépouille la crainte du Tout-puissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Mes frères sont perfides comme le torrent, comme les eaux des ravins, qui tarissent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'que troublent les glaces, où s\'enfonce la neige,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'qui, au temps de leur baisse, se dissipent, et, quand vient la chaleur, leur lit se trouve à sec.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Les caravanes s\'écartent de leur route, s\'avancent dans le désert, et périssent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'là portent leurs regards les caravanes de Théma, là les voyageurs de Séba placent leur espérance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'ils ont honte d\'avoir eu confiance, ils y arrivent, et sont confus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'De même vous n\'êtes rien, vous voyez la terreur, et tremblez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Est-ce que j\'ai dit: Donnez-moi! et avec vos biens, gagnez-moi la faveur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'et tirez-moi de la main de l\'ennemi, et de la main des furieux rachetez-moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Instruisez-moi! je veux me taire, et faites-moi sentir en quoi j\'ai failli!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Quelle force dans le langage de la vérité! mais que démontrent vos remontrances?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Est-ce des discours que vous pensez à reprendre? mais on livre au vent les propos du désespoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Oui, sur l\'orphelin vous jetez le filet, et vous creusez la fosse devant votre ami.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Mais ici, veuillez me regarder! et vos yeux vous diront si je suis un menteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Revenez donc! qu\'il n\'y ait pas injustice! revenez! j\'ai encore raison sur ce point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'L\'injustice est-elle sur ma langue, et mon palais ne distingue-t-il pas ce qui est mauvais?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'L\'homme ne fait-il pas sur la terre le service d\'un soldat, et ses jours ne sont-ils pas comme les jours d\'un mercenaire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Comme l\'esclave soupire après l\'ombre, et comme un journalier attend son salaire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'ainsi j\'eus pour mon lot des mois de douleur, et des nuits de tourment ont été mon partage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Couché, je dis: Quand me lèverai-je? la nuit finira-t-elle? et je m\'excède d\'agitations jusqu\'à l\'aube du jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Mon corps se couvre de vers et d\'une croûte terreuse, ma peau se roidit, et de nouveau suppure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Mes jours fuient plus prompts que la navette, ils se consument, et je suis sans espoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Souviens-Toi que ma vie est un souffle! Mes yeux ne reverront plus de bonheur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'l\'œil de celui qui me voit, ne m\'apercevra plus; Tes yeux me chercheront, et je ne serai plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'La nuée se dissipe et s\'en va: ainsi, qui descend aux Enfers, n\'en revient pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'il ne rentre plus dans sa maison, et ses lieux ne le reconnaissent plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Aussi ne mettrai-je pas un frein à ma bouche, mais je parlerai dans l\'angoisse de mon cœur, et me plaindrai dans l\'amertume de mon âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Suis-je une mer? suis-je un dragon, que contre moi Tu mettes une barrière?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Quand je dis: Mon lit me soulagera, ma couche portera une partie de ma peine!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'alors tu m\'effraies par des songes, et par des visions tu m\'épouvantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Aussi je préférerais suffoquer, mourir, à conserver ma chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Je dédaigne la vie! je ne vivrai pas toujours!... Suspends tes coups, car mes jours sont un souffle!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Qu\'est-ce que l\'homme, pour que tu l\'honores, pour que tu prennes garde à lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'que tu t\'occupes de lui chaque matin, et l\'éprouves à tous les instants?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Jusques à quand les yeux ne me quitteront-ils pas, ne me laisseras-tu pas le temps d\'avaler ma salive?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Si j\'ai péché, qu\'ai-je pu te faire, observateur des hommes? Pourquoi me fais-tu le but de tes coups, tellement que je suis à moi-même un fardeau?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Et que ne pardonnes-tu ma faute, et ne passes-tu mon péché? car bientôt je dormirai dans la poudre, et tu me chercheras, et je ne serai plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Et Bildad de Such prit la parole et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Jusques à quand tiendras-tu ces discours? Les paroles de ta bouche ont la violence de l\'ouragan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Dieu fera-t-Il plier la loi, et le Tout-puissant, plier la justice?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Si tes fils ont péché contre Lui, Il les a mis à la merci de leur crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Mais si tu veux chercher Dieu, et du Tout-puissant implorer la clémence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'si tu es pur et droit, oh! alors Il veillera sur toi, et donnera le bonheur à la maison d\'un juste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'et tes commencements auront été petits, tant ton avenir aura de grandeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Interroge en effet l\'âge qui précède, et fais attention aux recherches de ses pères:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, '(car nous sommes d\'hier, et nous ne savons pas, car nos jours sont une ombre sur la terre).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Ne t\'instruiront-ils pas? ne te diront-ils pas, et de leur cœur ces mots ne sortiront-ils pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Le papyrus grandit-il où il n\'y a pas de marais? le roseau prospère-t-il où il n\'y a pas d\'eau?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'il en est encore à son premier jet, on ne le fauche pas, cependant il sèche avant toutes les herbes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Tel est le chemin de quiconque oublie Dieu, et l\'espoir de l\'impie s\'évanouit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'son assurance est brisée, en une toile d\'araignée il met sa confiance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'il s\'appuie sur sa maison, et elle ne tient pas, il s\'y cramponne, et elle ne reste pas debout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Il est plein de sève aux rayons mêmes du soleil, et ses jets s\'étendent au delà de son enclos,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'dans des monceaux de cailloux ses racines s\'insinuent, il affronte un sol pierreux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'qu\'on l\'arrache de sa place, elle le renie: « Je ne t\'ai jamais vu! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Telles sont les délices de ses voies, et de la poussière il en croîtra d\'autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Voici, Dieu ne rejette pas l\'innocent, mais Il ne prend point les pécheurs par la main:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'si bien qu\'il remplira ta bouche d\'allégresse, et tes lèvres, de jubilation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Ceux qui te haïssent, seront couverts de honte, et la tente des impies cessera d\'être,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Et Job reprit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Assurément je sais qu\'il en est ainsi; et comment un mortel serait-il juste devant Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 's\'il voulait contester avec Lui, il ne répondrait pas à une chose sur mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Pour l\'intelligence, Il est sage, et pour la force, Il est puissant; qui pourrait Le braver, et rester sain et sauf?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Il déplace soudain les montagnes qu\'il bouleverse dans sa colère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Il ébranle la terre sur sa base, et ses colonnes tremblent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Il commande au soleil de ne point se lever, et Il met un sceau sur les étoiles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Il incline les cieux à Lui seul, et s\'avance sur les sommités des flots;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Il fit l\'Ourse, Orion, les Pléiades, et les retraites lointaines du Midi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Il fait des choses grandes, qu\'on ne peut sonder, et des merveilles qu\'on ne peut compter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Voici, Il m\'assaille, et je ne le vois pas, Il attaque, et je ne l\'aperçois pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Voici, Il emporte: qui le fera revenir? Qui lui dira: Que fais-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Dieu ne calme pas son courroux; sous lui plient les appuis de l\'orgueil;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'et je pourrais lui répondre, et choisir les paroles à lui dire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Eussé-je raison, je ne répondrais pas, de mon Juge j\'invoquerais la clémence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Quand Il répondrait à mon appel, je ne croirais pas qu\'il ait ouï ma voix;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'car Il m\'assaille par la tempête, et Il multiplie mes plaies sans motif;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Il ne me laisse pas reprendre haleine, car Il me rassasie d\'amertumes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'En appelle-t-on à la vigueur du fort: « Me voici! » [dit-Il] au droit: « Qui M\'assignera? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Eussé-je raison, ma bouche devrait me condamner; fussé-je innocent, Il me trouverait pervers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Je suis innocent, et ne fais nul cas de la vie. je dédaigne de vivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'C\'est tout un! Aussi dis-je: Il détruit innocent et coupable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Quand sa verge donne soudain la mort, Il se rit de l\'épreuve de l\'innocent:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'la terre est livrée aux mains de l\'impie, Il ôte la vue aux yeux de ses juges. Si ce n\'est pas lui, qui est-ce donc?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Mes jours s\'en vont plus rapides que le coureur, ils fuient sans voir le bonheur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'ils passent comme des nacelles de roseau, comme l\'aigle qui fond sur sa proie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Si je dis: Je veux oublier ma plainte, quitter mon air triste, redevenir serein;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'je m\'épouvante de tous mes maux, je sais que Tu ne m\'absoudras pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Je dois être coupable; pourquoi prendre une peine inutile?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Quand je me laverais dans l\'eau de neige, quand avec la lessive je rendrais mes mains nettes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'même alors tu me plongerais dans la fosse, et mes habits mêmes me trouveraient repoussant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Car Il n\'est pas homme comme moi, pour que je réplique, pour que nous paraissions en jugement ensemble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Entre nous il n\'y a point d\'arbitre qui interpose sa main entre nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Qu\'il éloigne de moi sa verge, et que ses terreurs ne m\'effraient plus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'alors je parlerai, et serai sans crainte: car ainsi, je ne suis pas à moi-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Ma vie donne à mon cœur du dégoût: je veux me soulager, donner cours à mes plaintes, et parler dans l\'amertume de mon âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Je dis à Dieu: Ne me condamne pas! Déclare-moi sur quoi tu me prends à partie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Est-ce un bonheur pour toi de me maltraiter, de rejeter l\'ouvrage de tes mains, et de prêter la lumière aux complots des impies?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'As-tu des yeux de chair? vois-tu, comme voient les mortels?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Tes jours sont-ils comme les jours des mortels. et tes années, comme celles des humains,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'que tu fais une enquête de ma faute, et une perquisition de mon péché,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'sachant bien que je ne suis pas coupable, et que nul ne peut sauver de ta main?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Tes mains m\'ont façonné, m\'ont fait, en entier; et tu veux me détruire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Ah! souviens-toi que tu m\'as modelé comme l\'argile! et dans la poudre tu veux me faire rentrer!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Ne m\'as-tu pas versé comme du lait? comme le caillé ne m\'as-tu pas fait prendre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'De peau et de chair tu m\'as revêtu, d\'os et de nerfs tu m\'as tissé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'tu m\'as donné la vie et la grâce, tes soins ont protégé ma respiration:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'et tu me réservais ces maux dans ton cœur! Je sais qu\'ils étaient dans ta pensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Au cas que je péchasse, tu voulais m\'épier, et ne point m\'absoudre de ma faute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Suis-je coupable? malheur à moi! innocent? je n\'ose lever la tête, rassasié d\'opprobre, et voyant ma misère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'qu\'elle se lève, tu vas, tel qu\'un lion, me donner la chasse, et renouveler sur moi tes miracles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'm\'opposer de nouveaux témoins, redoubler ta fureur contre moi, et faire contre moi se succéder les bataillons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Ah! pourquoi me tiras-tu du sein de ma mère? Je serais expiré, et aucun œil ne m\'eût vu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'je serais comme n\'ayant pas été; du ventre au tombeau j\'aurais été porté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Qu\'ai-je, sinon quelques jours? Qu\'Il cesse! se retire de moi, pour que je me rassérène un peu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'avant que je m\'en aille, pour ne plus revenir, dans la région des ténèbres et de l\'ombre de mort,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'région sombre comme la nuit, d\'ombre de mort et de désordre, où la clarté ressemble aux ténèbres!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Et Zophar de Naama prit la parole et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'A tant de paroles ne répondra-t-on point? Et l\'homme aux discours aura-t-il gain de cause?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'A tes vains propos des hommes se tairont-ils, pour que tu te moques, sans que nul te réponde,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'que tu dises: Ma doctrine est pure; et je suis net à Tes yeux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Mais que Dieu veuille parler, et ouvrir ses lèvres contre toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'pour te révéler les mystères d\'une sagesse double de notre prudence! et tu verras que pour toi Dieu oublie une partie de ton crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Atteindras-tu à la portée de Dieu? A la science parfaite du Tout-puissant atteindras-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'C\'est la hauteur des Cieux! que ferais-tu? plus que la profondeur des Enfers! que saurais-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Elle mesure en longueur plus que la terre, en largeur plus que la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'S\'Il se porte agresseur, s\'Il saisit, s\'il convoque, qui l\'arrêtera?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Car Il connaît les hommes méchants, et voit le mal, sans effort d\'attention.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Mais l\'homme est stupide dans sa sagacité, et le poulain de l\'onagre naît l\'égal d\'un humain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Mais si tu diriges bien ton cœur, et que tu tendes vers Lui tes mains,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, '(secoue le mal qui est en ta main, et ne laisse pas l\'iniquité loger dans ta tente!)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'alors tu lèveras la tête sans reproche, tu seras ferme et sans crainte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'alors tu oublieras ta peine; il t\'en souviendra comme d\'eaux écoulées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'la vie surgira plus claire que le midi; assombri, tu seras comme le matin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'tu auras de l\'assurance, car il y aura espérance; outragé, tu te coucheras tranquille;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'dans ton repos, nul ne te troublera, et plusieurs flatteront ton visage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Mais les yeux des impies se consumeront, la retraite leur sera coupée, et leur espoir sera un dernier soupir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Et Job reprit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'En vérité vous êtes tout un peuple, et avec vous mourra la sagesse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Moi aussi, j\'ai du sens comme vous, je ne vous le cède point! Et de qui ces choses sont-elles ignorées?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'De mon ami je suis la risée, quand j\'invoque Dieu et qu\'il m\'exauce; la risée! un juste! un innocent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Au malheur le mépris, dans l\'idée des heureux! il est près de celui dont le pied chancelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Les tentes tranquilles sont pour les destructeurs, et la sécurité, pour ceux qui bravent le Seigneur, et qui se font un Dieu de leur bras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Mais interroge les brutes, pour qu\'elles t\'instruisent, et les oiseaux des cieux, pour qu\'ils l\'expliquent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'ou parle à la terre, pour qu\'elle t\'instruise! et les poissons de la mer te raconteront!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Entre eux tous, qui pourrait ignorer que la main de l\'Éternel a fait ces choses?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'Il tient en sa main l\'âme de tout ce qui vit, et l\'esprit de tout corps d\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Est-ce que l\'ouïe ne discerne pas les discours, de même que le palais goûte les aliments?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Les vieillards ont de la sagesse, et l\'âge avancé, de l\'intelligence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Chez Lui se trouve sagesse et puissance, Il a conseil et intelligence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Voici, Il détruit, et on ne relève pas. Enferme-t-Il un homme, il n\'est pas élargi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Voici, Il retient les eaux, et elles sèchent; Il les envoie, et elles bouleversent la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Chez lui se trouvent force et sagesse, Il est maître de celui qui erre, et de celui qui fait errer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Il emmène les conseillers captifs, et fait délirer les juges;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Il relâche l\'autorité des rois, et enchaîne leurs reins d\'une ceinture;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Il emmène les prêtres captifs, et Il renverse les puissants;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Il ôte la parole aux hommes éprouvés, et retire le jugement aux vieillards;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Il verse le mépris sur les nobles, et délie la ceinture des forts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'produit les secrets hors des ténèbres, et fait sortir au jour l\'ombre de mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Il élève les peuples, et les perd; Il disperse les peuples, et les rétablit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Il ôte le sens aux chefs des peuples, et les égare dans des déserts sans chemins;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'ils tâtonnent dans l\'obscurité, sans clarté, Il leur donne le vertige, comme à l\'homme ivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Voici, mes yeux ont vu toutes ces choses, mon oreille les a ouïes et comprises;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'ce que vous connaissez, je le connais aussi, je ne vous suis nullement inférieur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Mais c\'est au Tout-puissant que je désire parler, et avec Dieu que je voudrais engager le débat;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'car pour vous, vous tissez des mensonges, et êtes tous des médecins inutiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Que ne gardez-vous le silence! on vous croirait de la sagesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Entendez ma réfutation, et recueillez de ma bouche mes moyens de défense!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'En faveur de Dieu direz-vous ce qui est faux, et en parlant pour lui userez-vous de fraude?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Ferez-vous acception de personne pour lui? Voulez-vous être les avocats de Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Aimerez-vous qu\'il vous pénètre à fond? Comme on trompe les hommes, pourrez-vous le tromper?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Il vous châtiera, vous châtiera, si en secret vous faites acception.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Sa majesté ne vous fait-elle pas peur, et la crainte de lui ne vous saisit-elle pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Vos maximes sont des propos vains comme la cendre, et vos retranchements, des retranchements d\'argile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Taisez-vous! laissez-moi! il faut que je parle: et m\'arrive ce qui pourra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Je veux tout tenter, quand même... Je veux risquer ma vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Voici, Il me tuera; je suis sans espoir: je veux devant lui justifier ma conduite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'C\'est aussi là mon salut; car un impie ne l\'affronterait pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Ecoutez, écoutez mon discours, et que ma déclaration descende en vos oreilles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Eh bien! voici, j\'ai mis mes moyens en ordre: je sais que je suis innocent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Quel est Celui qui se ferait ma partie?... Car alors je n\'aurais qu\'à me taire et mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Seulement, épargne-moi deux choses! alors de Ta face je ne me cacherai pas:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'éloigne ta main de moi, et de tes terreurs ne m\'épouvante pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Ainsi, sois l\'appelant, et je répliquerai: ou bien je parlerai, et toi, réponds-moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Quel est le nombre de mes fautes et de mes. péchés? Indique-moi mon forfait, et mon péché!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Pourquoi caches-tu ta face, et me regardes-tu comme ton ennemi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Veux-tu terrifier une feuille emportée, poursuivre une paille desséchée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'que tu prononces contre moi avec tant de rigueur, et que tu m\'imputes mes péchés de jeunesse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'et que tu mets mes pieds aux entraves, et surveilles toutes mes voies, circonscrivant la plante de mes pieds,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'tandis que je m\'use comme une chose cariée, comme un vêtement que rongent les teignes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'L\'homme né de la femme est borné dans ses jours, et rassasié d\'alarmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Comme la fleur il pousse, et il est tranché, il fuit comme l\'ombre, et n\'est point permanent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Et c\'est sur lui que tu tiens tes yeux ouverts! et c\'est moi que tu mènes en jugement avec toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'De la souillure fera-t-on naître un homme pur? Pas un.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Si ses jours sont déterminés, si le nombre de ses mois par devers toi est marqué, si tu en fixas le terme qu\'il ne franchira pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'ne le suis plus de l\'œil! pour qu\'il ait du relâche, et puisse se réjouir, comme un mercenaire de sa journée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Pour l\'arbre, en effet, il est un espoir: est-il coupé, il reverdit encore, et ne cesse pas de pousser des jets;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'si sa racine devient caduque en terre, et que dans la poussière sa tige se meure,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'au parfum des eaux il se ranime, et, comme un plant, il pousse des rameaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Mais quand l\'homme meurt, le voilà gisant! quand le mortel expire, où est-il?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'L\'eau s\'est écoulée du lac, et la rivière tarit et se dessèche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'ainsi l\'homme se couche, et il ne se relève pas; jusqu\'à ce qu\'il n\'y ait plus de ciel, on ne se réveille pas, et l\'on n\'est point tiré de son sommeil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'O! si dans les Enfers Tu me plongeais, me cachais, jusqu\'à ce que passe ta colère, me fixant un terme pour me rendre ton souvenir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Une fois mort, l\'homme revivrait-il?... Je patienterais durant tous mes jours de corvée, jusqu\'à ce qu\'on vînt me relever:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'tu appellerais, et je te répondrais... Tu languirais après l\'ouvrage de tes mains!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Mais maintenant tu comptes mes pas! N\'es-tu pas aux aguets de mon péché?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'L\'acte de mon crime dans le sac est scellé, et tu imagines encore, pour ajouter à ma faute!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Mais enfin la montagne éboulée gît anéantie, et le rocher se mine détaché de sa place:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'les pierres sont creusées par les eaux, dont les flots emportent la poudre de la terre. Ainsi tu as détruit l\'espérance du mortel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'incessamment tu l\'assailles, et il s\'en va; tu altères son visage, et le pousses dehors:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'ses fils sont honorés, et il n\'en sait rien; ils sont dans la bassesse, et il l\'ignore;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'sa chair ne ressent que sa propre douleur, et son âme pour lui seul s\'attriste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Et Eliphaz de Théman reprit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Un sage répond-il par des propos en l\'air, et laisse-t-il la tempête gonfler sa poitrine?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Ses arguments sont-ils des mots qui ne disent rien, et des paroles qui ne sauraient lui servir?...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Bien plus, tu attentes à la crainte de Dieu, et tu entames la dévotion qui s\'élève à lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Ta bouche en effet révèle ton crime, quand même tu recours au langage des fourbes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'c\'est ta bouche, et non moi, qui te condamne, et tes lèvres déposent contre toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Es-tu né le premier des humains, et avant les collines fus-tu mis au jour?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Confident des secrets de Dieu, as-tu accaparé la sagesse?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Que sais-tu que nous ne sachions? Qu\'as-tu pénétré qui nous soit inconnu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Il en est parmi nous qui ont vieilli, ont blanchi, par leur âge ont acquis plus de poids que ton père...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Tiens-tu pour si peu les consolations de Dieu, et la douceur du langage dont on use avec toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Où t\'emporte ton cœur? d\'où viennent ces roulements d\'yeux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'que tu retournes contre Dieu ta fureur, et exhales de ta bouche ces propos?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Qu\'est-ce que l\'homme, pour être pur? et l\'enfant de la femme, pour être juste?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Voici, Il ne fait pas fond sur ses Saints mêmes, et le ciel n\'est pas pur à ses yeux...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Combien moins l\'abominable, le pervers, l\'homme qui boit l\'iniquité comme l\'eau?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Je veux t\'instruire! écoute-moi! et que je te dise ce que j\'ai vu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'ce que les sages ont proclamé, sans le cacher, d\'après leurs pères:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'seuls ils étaient maîtres du pays, et nul étranger ne pénétrait chez eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Toute sa vie l\'impie est tourmenté, et le nombre de ses ans est caché au méchant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'La voix de l\'alarme sonne à ses oreilles: en temps de paix, le destructeur va fondre sur lui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Il ne croit plus possible de sortir des ténèbres; c\'est à lui que l\'épée vise!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Il court après du pain: Où [en trouverai-je]? il sait qu\'il touche au sombre jour qui est prêt;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'la détresse et l\'angoisse l\'épouvantent, et l\'assaillent comme un roi équipé pour la charge...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'C\'est qu\'il étendit sa main contre Dieu, et qu\'il brava le Tout-puissant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'il Lui livra l\'assaut d\'un front audacieux, serrant les dos hérissés de ses boucliers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'C\'est qu\'il se couvrit le visage de sa graisse, et qu\'il entoura ses reins d\'embonpoint,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'et qu\'il habite des villes détruites, des maisons inhabitées, destinées à être des ruines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Son opulence n\'est pas durable, et sa richesse n\'est point stable, et ses possessions ne s\'étendent point dans le pays;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'il n\'échappe point aux ténèbres, la flamme sèche ses rejetons, et il périt par le souffle de Sa bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Qu\'il ne se fie pas au mal! il sera déçu! car le mal sera sa rétribution,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'qui arrivera avant le terme de ses jours; et ses rameaux ne verdiront plus:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'il est comme la vigne d\'où se détache le raisin encore vert, comme l\'olivier qui laisse tomber sa fleur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Oui, la maison de l\'impie devient stérile, et le feu dévore le logis de la corruption;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'ils conçoivent le crime et enfantent la misère, et leur sein tient le mécompte tout prêt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Et Job répondit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Je n\'ai que trop entendu de pareils discours; vous êtes tous des consolateurs fâcheux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Mettra-t-on fin à ces propos en l\'air? Ou pourquoi cette aigreur dans tes réponses?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Moi aussi, je pourrais parler comme vous, si seulement vous étiez à ma place! Je pourrais contre vous assembler des paroles, et faire sur vous des hochements de tête;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'je pourrais vous fortifier de la bouche, et remuer les lèvres pour calmer votre peine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, '[Mais!..] parler, ne calmera pas ma peine, et me taire, ne l\'éloignera pas de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Oui, déjà Il m\'a tout épuisé, et Il a désolé toute ma maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Tu m\'as réduit à un état qui dépose contre moi; mon aspect s\'élève pour me calomnier, et m\'accuser en face.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Sa colère me déchire et me poursuit, Il grince les dents contre moi, mon ennemi, Il lance sur moi des regards acérés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Ils ouvrent contre moi une large bouche, et frappent mes joues de coups outrageants; ensemble ils se liguent contre moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Dieu me livre à la merci du méchant, et Il me jette aux mains des impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Je vivais tranquille, et Il m\'a brisé, et, me saisissant au col, Il m\'a mené battant, et m\'a dès-lors pris pour son point de mire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'de toutes parts sur moi ses traits fondirent, Il me perça les reins sans pitié, et fit couler ma bile sur la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Il m\'enfonça, faisant brèche sur brèche, et me donna l\'assaut, comme un guerrier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Je cousis un cilice à ma peau, et je plongeai mon front dans la poudre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Mon visage est tout rougi de pleurs, et la nuit de la mort couvre mes paupières:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'cependant ma main ne retient rien d\'injuste, et ma prière est pure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Terre, ne recouvre pas mon sang! et qu\'aucun de tes lieux n\'arrête mes cris!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Encore à présent, voici, j\'ai dans les Cieux mon témoin, et mon avocat dans les lieux très-hauts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'En mes amis je trouve des moqueurs; c\'est vers Dieu que se tournent mes yeux en pleurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'afin qu\'il prononce pour l\'homme contre Dieu, et pour l\'enfant de l\'homme contre ses amis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Mes quelques années avancent, et je vais franchir un chemin, par lequel je ne reviendrai pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Mon souffle se perd, mes jours s\'éteignent: pour moi, le tombeau!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Si nulle iniquité n\'est par devers moi, mon œil peut avec calme regarder leur querelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Ah! dépose ton gage! sois ma caution auprès de Toi! Qui est-ce qui mettrait sa main dans la mienne?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Car tu as fermé leur cœur à l\'intelligence; aussi ne leur laisse pas l\'avantage!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Tel convie son prochain à partager, dont les fils ont le regard éteint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Il m\'a fait passer en proverbe dans le peuple, et l\'on me crache au visage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'et le chagrin a rendu mes yeux ternes, et ma figure est toute entière comme une ombre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'C\'est de quoi les gens de bien sont stupéfaits, et, ce qui irrite l\'innocent contre l\'impie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'mais le juste tient ferme à sa voie, et celui qui a les mains pures, redouble de vigueur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Mais enfin, vous tous, revenez-y, venez encore à la charge, je n\'en trouverai pas plus un sage entre vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Mes jours sont passés, mes plans sont déchirés, cette fortune de mon cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Quand il est nuit, je suis, selon eux, en plein jour, et la lumière est plus près que les ténèbres présentes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Quand je dois compter sur les Enfers, comme sur ma demeure, étendre ma couche dans le séjour ténébreux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'dire au tombeau: Tu es mon père! et aux vers: Vous êtes ma mère et ma sœur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'où donc est mon espoir? Et l\'espoir que j\'aurais, qui le verrait [accompli]?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Il descend vers les portes des Enfers, puisqu\'ensemble nous allons reposer dans la poudre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Et Bildad de Such répondit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Jusques à quand chasserez-vous aux mots? Prenez du sens, puis nous parlerons!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Pourquoi nous tient-on pour des brutes, sommes-nous stupides à vos yeux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Toi, qui dans ta fureur te déchires toi-même, la terre à cause de toi sera-t-elle désertée, et le rocher transporté de sa place?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Aussi bien la lumière des impies s\'éteint, et la flamme de son feu cesse de briller;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'la lumière de sa tente s\'éclipse, et sa lampe au-dessus de lui s\'éteint;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'sa vigoureuse allure s\'embarrasse, et il se perd par les mesures qu\'il prend;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'car ses pieds mêmes le conduisent au piège, et il marche sur des lacs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'le lacet le saisit au talon, et le filet se rend maître de lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'le sol pour lui recouvre des rêts, et la trappe l\'attend sur le sentier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'De toutes parts des terreurs l\'épouvantent, et le pressent par derrière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Le malheur est avide de lui, et la misère s\'apprête à le faire tomber.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Il dévore les membres de son corps, il dévore ses membres, le Premier-né de la Mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Il est arraché de sa tente, sa sécurité, et traîné vers le Roi de l\'épouvante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'D\'autres que les siens viennent habiter sa tente, et le soufre tombe en pluie sur sa demeure;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'à ses pieds ses racines sèchent, à son sommet son rameau se flétrit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'sa mémoire disparaît du pays, et il n\'a plus un nom dans les campagnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'il est refoulé de la lumière dans la nuit, et banni de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'il n\'a dans son peuple ni race, ni lignée, et pas un reste de lui dans ses demeures;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'son jour terrifie la postérité, et fait frissonner les contemporains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Ainsi seulement finissent les demeures du méchant, et ainsi le séjour de qui méconnaît Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Et Job répondit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Jusques à quand affligerez-vous mon cœur, et me briserez-vous par vos discours?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Dix fois déjà vous m\'avez humilié; n\'aurez-vous point honte de me maltraiter?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Si vraiment j\'ai failli, c\'est à moi qu\'en reste la faute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Est-ce bien envers moi que vous le prenez haut? Est-ce moi que vous déclarez coupable de ma honte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Comprenez donc que c\'est Dieu qui m\'abat, et m\'enserre dans son filet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Voici, je crie à la violence, et ne suis pas écouté! je demande du secours, et n\'obtiens pas justice!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Il a barré ma route pour que je ne puisse passer, et Il a mis l\'obscurité sur mon sentier:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Il m\'a dépouillé de ma gloire, et a enlevé la couronne de ma tête;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Il m\'a miné de toutes parts, et c\'en est fait de moi! et Il a arraché, comme un arbre, mon espoir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'et Il a allumé contre moi sa colère, et m\'a envisagé comme son ennemi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Ensemble ses bataillons se sont avancés, et ils ont élevé leur chaussée pour m\'atteindre, et se sont campés autour de ma tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Il a éloigné mes frères de moi, et mes intimes ne sont plus pour moi que des étrangers;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'mes proches se retirent, et mes connaissances m\'oublient;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'les gens de ma maison et mes servantes me considèrent comme un étranger,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'je ne suis plus pour eux qu\'un inconnu. J\'appelle mon serviteur, et il ne répond point; de ma bouche il faut que je le prie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Mon humeur est importune à ma femme, et je dégoûte les fils de mon sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Des enfants mêmes me méprisent: tenté-je de me lever, ils me tiennent des propos!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Je suis l\'aversion des hommes de ma société, et ceux que j\'aimais, se tournent contre moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Mes os sont collés à ma peau et à ma chair, et j\'échappe à peine avec la peau de mes dents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Ayez, ayez pitié de moi, vous au moins, mes amis! car c\'est la main de Dieu qui m\'a frappé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Pourquoi me poursuivez-vous, comme Dieu? et êtes-vous insatiables de ma chair?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Ah! si mes paroles pouvaient être écrites, et consignées dans un livre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Si, avec le burin de fer et le plomb, on pouvait pour toujours les incruster sur le roc!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Pour moi, je sais que mon Sauveur est vivant, et qu\'il demeurera le dernier sur la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'et, quand après ma peau ce [reste] aura été détruit, même sans chair je verrai Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'oui! moi, je le verrai à moi propice, mes yeux le verront, et non ceux d\'un autre: mon cœur en languit dans mon sein!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Oui, alors vous direz: Pourquoi le poursuivions-nous, et trouvions-nous en lui une racine de débats?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Redoutez l\'épée pour vous, car la fureur est un crime puni par l\'épée... C\'est afin que vous sachiez qu\'il y a un jugement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Et Zophar de Naama répondit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Mes pensées vont, et pour cause, me fournir la réplique; aussi j\'ai hâte de la faire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'j\'ai dû entendre une leçon qui m\'outrage! mais l\'esprit selon mes lumières répondra pour moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Ne sais-tu pas que, de tout temps, depuis que l\'homme fut placé sur la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'la joie des impies est de courte durée, et l\'allégresse des profanes n\'a qu\'un instant?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Que sa grandeur s\'élève jusques aux Cieux, et que sa tête touche aux nues,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'pour toujours il périt comme les excréments; ceux qui l\'ont vu, demandent: Où est-il?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Il s\'envole comme un songe, et on ne le retrouve pas; il a fui comme une vision nocturne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'l\'œil qui l\'a vu, ne l\'aperçoit plus, et sa demeure ne le reverra pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Les indigents accablent ses fils dont les mains doivent restituer ses biens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Ses os surabondaient d\'une vigueur juvénile, et sur la poussière elle gît avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Quelque douceur que sa bouche trouve au mal, qu\'il le tienne en réserve sous sa langue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'le savourant lentement, sans le laisser aller, mais le retenant collé à son palais,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'cet aliment qu\'il prend, se transforme dans ses entrailles, et devient au dedans de lui un venin d\'aspic,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Il engloutit des richesses, et il les revomit; de son ventre Dieu les fait ressortir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'il suce le venin de l\'aspic, et la langue de la vipère le tue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Son regard n\'est plus réjoui par les ruisseaux, ni par les fleuves, les torrents de miel et de lait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Il restitue ses gains, et ne les consomme pas: autant il possède, autant il restitue, et il ne peut se réjouir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Car il écrasa, délaissa les pauvres, il ravit des maisons, et ne les releva pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'car il ne connut pas le repos dans son sein. Mais il ne se sauvera pas avec ce qu\'il a de plus cher,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Rien n\'échappe à sa voracité, c\'est pourquoi son bien-être ne dure pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Dans la plénitude de l\'abondance, il est mis à la gêne; les bras des opprimés fondent sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Voici Celui qui assouvira son avidité: Il enverra sur lui le feu de Sa colère, et fera pleuvoir sur lui Son pain de douleur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 's\'il fuit devant l\'armure de fer, l\'arc d\'airain le transperce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Il extrait le dard de son corps avec le fer brillant qui lui a percé le foie; c\'en est fait: il est sous les terreurs de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Toutes les misères lui sont réservées en échange de ce qu\'il a mis en réserve; un feu qu\'on n\'a pas à souffler, le dévore, et consume ce qui resterait dans sa tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Le ciel dévoile son crime, et la terre s\'élève contre lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Tout le revenu de sa maison s\'en va, s\'écoulant au jour de Sa colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Telle est la part que Dieu donne à l\'impie, et le lot que le Seigneur lui décerne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Et Job répondit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Ecoutez, écoutez mon discours, et donnez-moi cette consolation-là!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Souffrez que je parle, et, quand j\'aurai parlé, tu pourras te moquer!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Est-ce à l\'homme qu\'en veut ma plainte? Et pourquoi la patience ne m\'échapperait-elle pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Tournez les yeux vers moi, et vous serez stupéfaits, et vous mettrez la main sur la bouche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Quand j\'y pense, je me trouble, et ma chair frissonne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Pourquoi les impies vivent-ils, avancent-ils en âge, accroissent-ils leurs moyens?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Devant eux, autour d\'eux, leur race s\'affermit, et leurs rejetons réjouissent leurs regards.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Leurs maisons sont en paix, à l\'abri de la crainte, et la verge de Dieu ne passe point sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Leur taureau saillit, et n\'est point impuissant, leur génisse vêle, et n\'avorte point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Ils promènent leur famille qui égale un troupeau, et leurs enfants s\'ébattent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Ils chantent au son des cymbales et du luth, et s\'égaient au bruit de la cornemuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Ils emploient leurs jours à jouir, et la descente aux Enfers est pour eux l\'affaire d\'un instant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Cependant ils disent à Dieu: « Retire-toi de nous! et pour la science de tes voies nous n\'avons aucun goût.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Qu\'est-ce que le Tout-puissant, pour que nous le servions? et que gagnerions-nous à le prier? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Voici, n\'ont-ils pas leur bonheur en leurs mains? (Loin de moi les principes des impies!)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Combien de fois arrive-t-il que la lampe des impies s\'éteigne, et que leur ruine fonde sur eux; que Dieu leur distribue leurs lots dans sa colère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'qu\'ils soient comme le chaume au souffle du vent, ou comme la balle qu\'enlève l\'ouragan?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'C\'est à ses fils que Dieu réserve la misère! C\'est lui que Dieu devrait punir, afin qu\'il en pâtit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'c\'est lui qui de ses yeux devrait contempler sa chute, et être abreuvé du courroux du Tout-puissant!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Car, que lui fait sa maison après lui, quand le terme de ses jours est échu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Est-ce à Dieu qu\'on veut révéler la science, à lui qui juge les Intelligences célestes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'L\'un meurt au sein même du bien-être, dans une sécurité et une paix complète;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'ses bergeries sont remplies de lait, et la moelle de ses os est toujours rafraîchie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Et l\'autre meurt, l\'amertume dans l\'âme, et il n\'a point goûté le bonheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Ensemble ils sont gisants dans la poudre, et les vers les recouvrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Voici, je sais quelles sont vos pensées, et les jugements qu\'à tort vous portez sur moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Car vous dites: « Où est la maison de l\'homme puissant, et la tente où habitaient les impies? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'N\'avez-vous pas interrogé les voyageurs? et ne vous rendrez-vous pas aux preuves qu\'ils rapportent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'C\'est qu\'au jour de la ruine, l\'impie est préservé, et qu\'au jour des vengeances, il est conduit en lieu sûr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Qui est-ce qui lui reproche en face sa conduite, et qui est-ce qui lui rend ce qu\'il a fait?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Il est porté au tombeau, et il veille encore sur le tertre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'La terre de la vallée pèse doucement sur lui; après lui tous les hommes vont à la file, et ses devanciers sont innombrables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Comment pouvez-vous donc m\'offrir des consolations si vaines? De vos réponses, ce qui reste, c\'est la perfidie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Et Eliphaz de Théman reprit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'L\'homme peut-il en quelque chose être utile à Dieu? Non! c\'est à lui seul que le sage est utile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Le Tout-puissant a-t-Il un intérêt dans ta justice, et un bénéfice dans l\'intégrité de les voies?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Est-ce par peur de toi qu\'il te châtie, et qu\'avec toi Il vient en jugement?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'N\'est-ce pas ton crime qui fut énorme, et tes transgressions qui furent infinies?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Car tu acceptas de ton frère des gages, sans motif, et tu dépouillas les pauvres de leurs habits;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'tu n\'offris point d\'eau à l\'homme altéré, et tu refusas ton pain à l\'homme affamé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'le pays était à la merci du violent, et le puissant s\'y établissait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'tu renvoyais les veuves à vide, et tu laissais briser le bras des orphelins!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'C\'est pourquoi les filets t\'enveloppent, et la terreur t\'épouvante soudain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Ou bien ne vois-tu pas ces ténèbres, et la masse des eaux qui te submergent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Dieu n\'est-Il pas élevé comme le ciel? Regarde le faîte des étoiles! quelle hauteur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Et cependant tu dis: « Qu\'est-ce que Dieu sait? A travers l\'obscurité peut-Il juger?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Les nuées lui sont une enveloppe qui l\'empêche de voir; c\'est la sphère des cieux qu\'il parcourt. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Tu veux dont te tenir sur l\'ancienne voie que suivirent ces hommes méchants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'qui furent retranchés avant le temps, et dont un torrent submergea le séjour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'qui disaient à Dieu: « Retire-toi de nous! et que pourrait nous faire le Tout-puissant? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Cependant Il avait rempli leurs maisons de biens. Loin de moi les principes des méchants!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Les justes seront témoins, et se réjouiront, et l\'innocent se moquera d\'eux:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, '« Oui, notre adversaire est anéanti, et le feu a dévoré sa magnificence. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Rapproche-toi donc de Lui, et tu seras sain et sauf, et par-là le bonheur te viendra!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Reçois donc l\'instruction que Sa bouche te donne, et mets Ses paroles dans ton cœur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Si tu reviens au Tout-puissant, tu seras rétabli! Bannis l\'iniquité de ta tente,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'et estime comme poussière le métal qui brille, et l\'or d\'Ophir, comme les cailloux des torrents!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Alors le Tout-puissant te sera richesse et argent et trésors!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Alors tu auras à te réjouir du Très-haut, et à relever ton visage vers Dieu:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'tu le prieras, et Il t\'exaucera, et tu accompliras tes vœux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'si tu prends un parti, il te réussira, et la clarté luira sur ta voie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'et si elle s\'affaisse, tu pourras dire: Qu\'elle se relève! car Il est secourable à l\'homme abattu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Il sauvera même le coupable, sauvé en faveur de la pureté de ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Et Job répondit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Maintenant ma plainte est une révolte! et pourtant la main qui me frappe, arrête de son poids l\'essor de mes soupirs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Ah! si je savais Le trouver, et arriver jusqu\'à son trône!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'J\'exposerais ma cause devant Lui, et j\'aurais la bouche pleine d\'arguments;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'je saurais en quels termes Il me répondrait, et j\'entendrais ce qu\'il me dirait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Faut-il qu\'avec la plénitude de sa puissance, Il se constitue ma partie? Non! seulement qu\'il me prête attention!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Alors ce serait un juste qui plaiderait avec Lui, et j\'échapperais pour toujours à mon juge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Mais voici, vais-je à l\'Orient; Il n\'y est pas! à l\'Occident; je ne l\'aperçois pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Agit-Il au Nord; je ne le découvre pas! S\'enfonce-t-Il dans le Midi; je ne le vois pas!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'C\'est qu\'il sait quelle est la voie que je suis. Qu\'il me mette à l\'épreuve, j\'en sortirai comme l\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Mon pied a tenu ferme sur Ses pas, j\'ai gardé sa voie, et n\'ai point dévié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Des ordres de ses lèvres je ne m\'écartai point, et je fis céder ma volonté aux paroles de sa bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Cependant Il n\'a qu\'une pensée: et qui l\'en fera revenir? Son âme a désiré, et Il exécute:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Oui, Il accomplira mon destin, et Il me garde nombre de maux pareils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Voilà pourquoi en sa présence je suis éperdu; je réfléchis, et je prends peur de Lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Dieu aussi bien a brisé mon courage, et le Tout-puissant m\'a effarouché;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'car je ne suis pas muet par la crainte des ténèbres, ou parce que je m\'effraie de moi-même qui suis couvert d\'un sombre nuage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Pourquoi le Tout-puissant n\'a-t-Il pas des époques en réserve, et ses adorateurs ne voient-ils pas ses jours [de vengeance]?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'On déplace les bornes, on ravit les troupeaux, et on les fait paître comme siens;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'on enlève l\'âne de l\'orphelin, on prend pour gage le bœuf de la veuve;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'on pousse le pauvre hors du chemin, et les malheureux du pays se cachent tous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'voici, comme des onagres, ils vont dans le désert à leur labeur, cherchant une proie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'la steppe leur donne du pain pour leurs enfants; ils ramassent dans les champs leur fourrage, et grapillent dans la vigne de l\'impie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'nus ils passent la nuit, faute de manteau, ils sont sans abri durant la froidure;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'trempés par les pluies des montagnes, et manquant d\'asile, ils embrassent les rochers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'On arrache l\'orphelin à la mamelle, et l\'on prend pour gage la couverture du pauvre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'qui s\'en va nu, privé de manteau, et qui reste affamé en portant les gerbes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'dans leurs enclos il pressure l\'olive, il foule au pressoir, et reste altéré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Du sein des villes sortent les soupirs des mourants, et l\'âme des blessés crie au secours... Mais pour Dieu n\'importe le contre-sens!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'D\'autres sont ennemis de la lumière, n\'en connaissent pas les voies, et n\'en pratiquent point les sentiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Au jour, le meurtrier se lève, tue le misérable et le pauvre, et la nuit, il est comme le voleur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'L\'œil de l\'adultère épie le crépuscule, disant: Aucun œil ne me verra! et d\'un voile il se couvre la tête...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'De nuit, ils percent les murs des maisons, de jour, ils se tiennent renfermés, ne connaissant pas la lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Car le matin est pour eux l\'ombre de la mort, et les terreurs nocturnes leur sont familières.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Vite [l\'impie] passe comme glissant sur les eaux! dans le pays son héritage est maudit! il ne se tourne plus du côté de ses vignes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Comme le sec et le chaud enlèvent l\'eau de neige, ainsi l\'Enfer absorbe ceux qui ont péché!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'le sein maternel les oublie! ils font le régal des vers! on ne pense plus à eux! comme le bois l\'impie est brisé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'lui qui dépouilla la femme stérile, celle qui n\'enfantait pas, et qui ne fit aucun bien à la veuve!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Non! Dieu par sa force conserve les violents; l\'impie se relève, alors qu\'il ne compte plus sur sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Il lui donne de quoi se rassurer, afin qu\'il soit soutenu, et Il a les yeux sur ses voies;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'ils se sont élevés: il ne faut qu\'un instant, et ils ne sont plus: les voilà gisants, ils meurent comme tous les hommes, ils sont moissonnés comme les cimes des épis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'S\'il n\'en était pas ainsi, qui me démentirait, et mettrait mon discours à néant?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Et Bildad de Such répondit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Il a l\'empire et une majesté redoutable; Il fait régner la paix dans ses hautes régions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Peut-on compter ses bataillons? Et sur qui ne se lève pas sa lumière?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Aussi comment serait juste l\'homme devant Dieu, et comment pur, l\'enfant de la femme?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Voici, la lune même n\'est pas brillante, ni les étoiles pures, à ses yeux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Combien moins le mortel, qui est un ver, et l\'enfant de l\'homme, qui est un vermisseau!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Et Job répondit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Comme tu as aidé la faiblesse, soutenu le bras débile!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Comme tu as conseillé l\'ignorance, et montré beaucoup de lumières!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'A qui s\'adressaient tes propos? et qui t\'inspirait ce que tu as énoncé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Devant Lui les Ombres tremblent, au-dessous des eaux et de leurs habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Les Enfers sont à nu devant Lui, et rien ne Lui masque l\'abîme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Il étendit l\'Aquilon au-dessus du vide; la terre est suspendue sur le néant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Il serra les eaux dans ses nues, et sous leur poids le nuage n\'éclate pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Il cache l\'aspect de son trône, et Il l\'enveloppe de sa nuée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Il traça sur les eaux une limite circulaire, au point où la lumière confine aux ténèbres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Les colonnes des Cieux s\'ébranlent, et s\'étonnent à sa voix menaçante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Par sa force, Il soulève la mer, et par sa sagesse, Il en abat l\'orgueil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Son souffle rassérène le ciel, et sa main transperce le dragon qui fuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Ce sont là les bords de ses voies. Qu\'il est faible le bruit qu\'en saisit notre oreille! et le tonnerre de sa puissance, qui est-ce qui l\'entend?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Et Job continuant à parler en discours relevés, dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Par le Dieu vivant qui me prive de mon droit, et par le Tout-puissant qui a mis l\'amertume dans mon âme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, '(car je ne perds pas haleine encore, et j\'ai toujours dans mes narines le souffle de Dieu)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'non! mes lèvres ne calomnieront pas, et ma langue ne dira rien de faux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Loin de moi la pensée de vous donner raison! Jusqu\'à mon dernier soupir, je ne me laisserai pas ravir mon innocence;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'je tiens à ma justice, et je n\'y renoncerai point; mon cœur ne me reproche aucun de mes jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Que mon ennemi soit tel que l\'impie, et mon adversaire semblable au méchant!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Eh! quel espoir a l\'impie, quand Dieu tranche, quand Il lui arrache sa vie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Dieu écoute-t-Il les cris qu\'il pousse, quand l\'angoisse l\'assaille?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Est-ce dans le Tout-puissant qu\'il cherche sa joie? Est-ce Dieu qu\'il invoque dans tous les moments?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Je veux vous montrer comment agit Dieu, ne pas vous celer la pensée du Tout-puissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Je l\'accorde, vous avez bien observé! mais pourquoi tirez-vous une conclusion vaine?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Tel est bien le lot que Dieu donne à l\'impie, et la part que le méchant obtient du Tout-puissant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 's\'il a nombre de fils, c\'est une proie pour l\'épée, et ses rejetons n\'ont pas de pain à manger;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'ceux qui restent de lui, sont conduits par la mort au tombeau, et leurs veuves ne pleurent point;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'qu\'il entasse l\'argent comme la poussière, qu\'il se procure un riche vestiaire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'il l\'acquiert, et le juste s\'en revêt, et l\'homme de bien a son argent en partage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'il bâtit une maison fragile comme celle de la teigne, comme la guérite qu\'élève le garde-champêtre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'riche il se couche, et il ne se relève pas; il ouvre les yeux, et il n\'est plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Comme des eaux les terreurs l\'atteignent, la nuit l\'ouragan le dérobe,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'le vent d\'orient l\'enlève et part, et dans un tourbillon le porte loin de ses lieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, '[Dieu] tire sur lui sans pitié il voudrait par la fuite échapper à Sa main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'On l\'accompagne de battements de mains et de sifflements, quand il quitte ses lieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Oui, on a pu trouver la source de l\'argent, et le lieu où gît cet or qu\'on affine;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'on extrait le fer de la terre, et la fusion change la pierre en airain;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'on sait faire cesser les ténèbres, et sonder parfaitement la roche obscure et sombre:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'on perce un puits loin des lieux habités; les pieds [du mineur] oublient de le servir, et il est là suspendu, loin des humains il est balancé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'La terre d\'où sort la nourriture, est dans ses profondeurs bouleversée comme par le feu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'c\'est dans ses pierres qu\'est le lieu du saphir couvert d\'une poudre d\'or;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'nul oiseau de proie n\'en sait le sentier, et l\'œil du vautour ne le découvre pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'il n\'est point foulé par les bêtes sauvages, et le lion n\'y passe point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'L\'homme met la main au roc le plus dur, et fait par leurs bases crouler des montagnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Dans le rocher il ouvre des canaux, et son œil voit alors tout ce qui est précieux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'il arrête les eaux qui suintent, et produit au jour ce qui était caché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Mais la sagesse, où peut-on la trouver? Et quel est donc le lieu où gît la science?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'L\'homme ne saurait en faire l\'estimation, et elle ne se trouve pas sur la terre des vivants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'L\'abîme dit: Elle n\'est pas chez moi! et la mer dit: Elle n\'est pas avec moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'On ne l\'obtient point contre de l\'or fin, et pour la payer on ne pèse pas d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'On ne la met point dans la même balance avec l\'or pur d\'Ophir, avec le précieux onyx et le saphir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'On ne peut lui comparer l\'or, ni le verre, ni la vaisselle d\'or, comme son équivalent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'A côté d\'elle on ne saurait citer ni les coraux, ni le cristal; et qui aurait la sagesse, aurait plus que des perles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'On ne peut lui comparer la topaze d\'Ethiopie, ni la peser avec l\'or affiné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'La sagesse donc, d\'où vient-elle? et où donc est le séjour de la science?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Elle est cachée aux yeux de tous les vivants, et voilée aux oiseaux des Cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'L\'abîme et la mort disent: De nos oreilles nous en ouïmes parler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Dieu en sait le chemin, et Il en connaît le séjour;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'car Il voit jusqu\'aux bouts de la terre, et son regard embrasse tout ce qui est sous le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Quand Il donnait une pesanteur au vent, et qu\'il pondérait les eaux avec mesure;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'quand Il traçait à la pluie des lois, et une route à la foudre bruyante;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'alors Il la voyait, et Il la proclama, Il l\'établit, et la contrôla,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'et Il dit à l\'homme: Voici, la crainte du Seigneur, c\'est là la sagesse, et fuir le mal, c\'est là la science.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Et Job continuant à parler en discours relevés, dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'O! qui me rendra les mois de jadis, et les jours, où Dieu me gardait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'où, sa lampe brillant au-dessus de ma tête, à sa clarté je perçais les ténèbres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'où j\'étais au temps de mon automne; quand Dieu avec sa cour veillait sur ma tente;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'quand le Tout-puissant était encore avec moi, qu\'autour de moi j\'avais mes enfants;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'quand mes pieds baignaient dans le lait, et que le rocher me versait des ruisseaux d\'huile;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'quand je me rendais à la Porte dans la ville, et que je mettais mon siège dans la Place?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'A mon aspect les jeunes se tiraient en arrière, et les vieux se levaient, et demeuraient debout;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'les princes s\'arrêtaient en parlant, et mettaient leur main sur leur bouche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'la voix des nobles restait muette, et leur langue, collée à leur palais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Car, sur ma renommée, on me disait heureux, et à ma vue, on me donnait des éloges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'C\'est que je sauvais le pauvre gémissant, et l\'orphelin qui était sans aide;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'l\'homme qui périssait, avait à me bénir, et je mettais la joie dans le cœur de la veuve;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'je prenais la justice pour mon vêtement, et elle me prenait pour son vêtement; mon équité m\'était comme un manteau et un turban;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'je servais d\'œil à l\'aveugle, et de pieds au boiteux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'j\'étais un père pour le pauvre, et je connaissais de la cause de l\'inconnu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'et je brisais la mâchoire du méchant, et d\'entre ses dents lui arrachais sa proie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Aussi je me disais: Je mourrai avec mon aire, et comme le Phénix, je prolongerai mes jours;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'ma racine sera exposée aux eaux, et la rosée passera la nuit sur mes branches;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'ma gloire me restera toujours jeune, et mon arc en ma main prendra force nouvelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Ils m\'écoutaient avec attente, et à mon avis ils se taisaient;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'après moi ils ne prenaient plus la parole, et sur eux mon discours s\'épanchait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Ils m\'attendaient, comme on attend la rosée, et leur bouche s\'ouvrait, comme pour recevoir une pluie du printemps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Je leur souriais, quand ils perdaient courage; et ils ne pouvaient m\'ôter la sérénité de mon front.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Si je prenais mon chemin vers eux, j\'y avais la place d\'un chef, et j\'étais assis comme un roi, au milieu de la foule, comme un consolateur, parmi les affligés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Et maintenant je suis la risée de mes cadets, dont je ne daignais pas associer les pères aux chiens de mes troupeaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Aussi bien la force de leurs mains, qu\'eût-elle été pour moi? Pour ces hommes il n\'y a jamais d\'âge mûr:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'desséchés par la disette et la faim, ils rongent la steppe, le vieux désert et la solitude;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'ils cueillent l\'arroche le long des haies, et la racine du genêt est leur pain;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'ils sont bannis de la société; on crie après eux, comme après les larrons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'réduits à habiter des ravins affreux, les antres de la terre et des rochers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'parmi les buissons ils poussent des hurlements, et pêle-mêle se blottissent sous les ronces,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'impies, hommes sans nom, qui furent chassés du pays!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Et maintenant je suis leur chanson, et le sujet de leurs discours;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'ils me maudissent, puis me quittent, et devant moi ne s\'abstiennent pas de cracher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Bien plus, ils déceignent leur corde, et m\'en frappent, et ils secouent tout frein devant moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'A ma droite leur engeance se lève; ils ne me laissent pas prendre pied, et se fraient jusqu\'à moi une voie pour me nuire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'ils ruinent mon sentier, aident à ma perte, eux que personne ne soutient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Ils viennent comme par une large brèche, se précipitent avec fracas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Toutes les terreurs se tournent contre moi; c\'est comme un ouragan qui poursuit ma grandeur, et, comme un nuage, mon bonheur a passé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Aussi, maintenant mon âme en moi épanche sa plainte; les jours de malheur m\'ont saisi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'La nuit perce mes os et les détache, et le mal qui me ronge, ne sommeille pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Sous Ses coups puissants mon manteau se déforme, comme ma tunique il s\'applique à mon corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Il m\'a jeté dans la boue, et assimilé à la poudre et à la cendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Je crie à Toi, et Tu ne m\'écoutes pas! je suis là debout, et Tu me regardes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Tu T\'es changé pour moi en cruel ennemi, et Tu m\'opposes la force de ton bras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Tu me soulèves sur la tempête et m\'emportes avec elle, et pour moi tu anéantis tout espoir de salut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Car, je le sais, c\'est à la mort que tu me mènes, au rendez-vous de tous les vivants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Cependant du sein des décombres ne tend-on pas la main? Quand on périt, ne crie-t-on pas au secours?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Oui, je pleurai sur ceux pour qui les temps étaient durs, et les indigents attristaient mon âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Et pourtant! j\'attendais le bonheur, et le malheur est venu; j\'espérais la clarté, et les ténèbres sont arrivées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Mes entrailles bouillonnent, et n\'ont aucun repos, des jours de chagrin me sont survenus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Je marche noirci, mais non par le soleil; debout dans l\'assemblée, je me lamente,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'devenant ainsi le frère des chacals, et l\'égal de l\'autruche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Ma peau noircit et tombe, et mes os brûlent d\'inflammation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Ainsi le deuil a remplacé mon luth, et des sons lugubres, ma cornemuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'J\'avais fait un pacte avec mes yeux... Comment les eussé-je arrêtés sur une vierge?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Et quel sort d\'en haut Dieu m\'eût-il envoyé, et quel lot le Tout-puissant, des lieux suprêmes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'La ruine n\'est-elle pas pour le criminel, et le malheur pour ceux qui font le mal?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Ne découvre-t-Il pas mes voies, et ne compte-t-Il pas tous mes pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Ai-je eu commerce avec le mensonge, et mon pied fut-il prompt à supplanter?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Que Dieu me pèse à la juste balance, et Il reconnaîtra mon innocence!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Mes pas ont-ils dévié de la voie, et mon cœur suivit-il l\'attrait de mes yeux? Une seule tache est-elle empreinte sur ma main?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'Alors, que je sème, et qu\'un autre moissonne, et que mes rejetons soient extirpés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Mon cœur pour une femme s\'est-il laissé séduire? ai-je été aux aguets à la porte de mon prochain?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'Alors, que ma femme tourne la meule pour un autre, et que d\'autres abusent d\'elle!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Car c\'est là un crime, un forfait que les juges doivent punir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'oui, c\'est un feu qui consume, à détruire, et aurait dans sa racine ruiné tout mon avoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Ai-je méprisé les droits de mon esclave, et de ma servante, quand ils n\'étaient pas d\'accord avec moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'Mais que ferais-je, si Dieu se levait? et, s\'il me châtiait, que lui répliquerais-je?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Dans le sein maternel, Celui qui me forma, ne le forma-t-Il pas aussi? et ne nous prépara-t-Il pas dans le sein d\'une mère?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Ai-je rebuté le vœu du pauvre, et fait languir les yeux de la veuve?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'Ai-je mangé mon pain seul, et l\'orphelin n\'y eut-il point de part?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'Non, dès ma jeunesse, j\'élevai l\'un en père, et dès ma naissance je fus le guide de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Ai-je pu voir l\'indigent non vêtu, et le pauvre non couvert?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Leurs reins ne me bénissaient-ils pas, et la toison de mes agneaux ne les réchauffait-elle pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Ma main a-t-elle menacé l\'orphelin, parce que je me voyais soutenu à la Porte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'Alors, que mon épaule se détache de ma nuque, et que mon bras brisé sorte de son emboîture!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Mais les vengeances de Dieu sont ma terreur, et devant Sa majesté je deviens impuissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Ai-je pris l\'or pour mon appui, et ai-je dit au métal: En toi je me confie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Me suis-je applaudi de la grandeur de mes biens, et des grands gains obtenus par mes mains?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Ai-je regardé la lumière, quand elle resplendit, et la lune, quand magnifique elle s\'avance?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'Et mon cœur en secret s\'est-il laissé séduire, jusqu\'à confier à ma main les baisers de ma bouche?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'Cela aussi serait un crime que les juges doivent punir, parce que j\'aurais menti au Dieu suprême.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Étais-je joyeux de la ruine de mon ennemi, transporté de le voir atteint par les revers?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'Mais je ne permettais pas à ma langue de pécher en demandant sa mort dans une imprécation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Les gens de ma tente ne disaient-ils pas: Montrez-nous qui ne fut pas rassasié à sa table?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'L\'étranger ne passait pas la nuit dehors, et j\'ouvrais ma porte au voyageur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'A l\'exemple des hommes ai-je dissimulé mes fautes, enfouissant dans mon sein mes égarements,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'parce que je redoutais le peuple assemblé, et que le mépris des tribus me faisait peur à m\'ôter la parole, et à m\'empêcher de passer ma porte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Ah! s\'il voulait m\'écouter et me dire: Voici ma signature! Si le Tout-puissant voulait répliquer! si j\'avais le grief écrit par ma partie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Oui, je le porterais sur mon épaule, je le ceindrais comme un diadème,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'j\'avouerais chacun de mes pas, comme un prince je L\'aborderais. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Mon champ réclame-t-il contre moi, et ses sillons en même temps portent-ils plainte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'En ai-je mangé le produit, sans l\'avoir payé, et ai-je arraché des soupirs à son maître?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Alors, que la ronce germe au lieu du froment, et l\'herbe gourmande à la place de l\'orge! Fin des discours de Job.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Et ces trois hommes cessèrent de répondre à Job, parce qu\'il était juste à ses propres yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Alors s\'enflamma de colère Elihu, fils de Barachéel, de Buz, de la famille de Ram: sa colère s\'enflamma contre Job, parce que devant Dieu il se déclarait lui-même juste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'et sa colère s\'enflamma contre ses trois amis, parce qu\'ils ne trouvaient rien à répondre, et que néanmoins ils condamnaient Job.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Cependant Elihu avait attendu de s\'adresser à Job. parce que ceux-là étaient plus vieux que lui par le nombre de leurs jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Elihu voyant donc qu\'il n\'y avait aucune réponse dans la bouche des trois hommes, s\'enflamma de colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Et Elihu, fils de Barachéel, de Buz, prit la parole et dit: Je n\'ai que peu d\'années, et vous êtes âgés; dès lors je m\'intimidais, et je craignais de vous exposer mes sentiments.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Je disais: Le grand âge parlera, et la vieillesse enseignera la sagesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Mais il est dans l\'homme un esprit, et un souffle du Tout-puissant, qui lui donne l\'intelligence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Les années seules ne donnent pas la sagesse, ni l\'âge, le discernement du juste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'C\'est pourquoi je dis: Ecoute-moi! je veux aussi exposer mes sentiments.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Voici, j\'ai attendu vos discours, j\'ai prêté l\'oreille à vos raisonnements que je vous ai laissés développer à fond;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'je vous ai suivis avec attention; mais voici, aucun d\'entre vous n\'a réfuté Job, ni répondu à ses discours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Cependant n\'allez pas dire: « Nous avons rencontré de la sagesse; Dieu, mais non l\'homme, lui fera lâcher pied. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'D\'ailleurs il n\'a point dirigé contre moi ses discours, et ce n\'est pas dans votre langage que je lui répondrai...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Ils sont éperdus, et ne répliquent plus! on leur a ôté l\'usage de la parole!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Dois-je aussi m\'arrêter, parce qu\'ils ne parlent plus, parce qu\'ils sont là debout, sans dire mot?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Je répondrai aussi pour ma part; moi aussi j\'exposerai mes idées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'car je suis plein de ce que j\'ai à dire, l\'esprit en mon sein me met à la gêne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Voici, mon sein est comme un vin qu\'on n\'a pas ouvert, comme des outres neuves qui vont éclater.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Je veux parler, pour respirer, ouvrir mes lèvres et répliquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Mais je ne ferai acception de personne, et ne serai le flatteur d\'aucun homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Car je ne sais pas flatter: d\'ailleurs bientôt mon Créateur me ferait disparaître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Eh bien donc! ô Job, écoute mes discours, et prête l\'oreille à toutes mes paroles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Voici, je vais ouvrir la bouche, et déjà ma langue sur mon palais marque ma parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'La droiture de mon cœur sera dans mon langage, et mes lèvres exprimeront sincèrement ma pensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'L\'Esprit de Dieu m\'a créé, et le souffle du Tout-puissant m\'anime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Si tu le peux, réponds-moi! prépare-toi au combat! prends position!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Devant Dieu mon rang est le même que le tien; du limon je fus aussi formé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Voici, la peur de moi ne peut t\'épouvanter, et mon poids ne saurait t\'accabler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Oui, tu l\'as dit à mes propres oreilles, et j\'entends encore le son de tes paroles:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, '« Je suis pur, sans péché, je suis net et sans crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Voici, Il en vient contre moi à des hostilités, et Il me regarde comme son ennemi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Il met des entraves à mes pieds, et surveille toutes mes voies. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Voici quelle est ma réponse: En cela tu n\'as pas raison; car Dieu est plus grand qu\'un mortel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Pourquoi Le prends-tu à partie, puisqu\'il ne répond point à ce qu\'on lui dit?...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Cependant Dieu parle d\'une manière, puis d\'une autre, mais on n\'y prend pas garde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'c\'est par un songe, une vision nocturne, quand le sommeil envahit les hommes assoupis sur leur couche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'alors Il se révèle aux humains, et scelle la leçon qu\'il leur donne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'afin de retirer l\'homme de son train, et de mettre le mortel à l\'abri de l\'orgueil,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'l\'empêchant ainsi de descendre au tombeau, et d\'exposer sa vie aux coups de l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'La douleur sur son lit vient aussi l\'avertir, quand il sent dans ses os un combat incessant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'quand le pain répugne à son palais, et qu\'un mets favori n\'excite plus son envie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'quand sa chair dépérit et disparaît, et qu\'on voit paraître ses os mis à nu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'quand son âme s\'avance vers le tombeau, et sa vie, vers les anges de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'S\'il se trouve alors un ange pour lui, un intercesseur, l\'un d\'entre ces mille chargés d\'indiquer à l\'homme son droit chemin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'alors Il prend pitié de lui et dit: Rachète-le de la descente au tombeau! j\'ai trouvé une rançon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Aussitôt son corps reprend plus de fraîcheur que dans son enfance; il revient aux jours de sa jeunesse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'il adresse à Dieu sa prière, et Dieu lui redevient propice; il contemple sa face avec des transports, et Dieu lui rend sa justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Il triomphe devant les hommes et dit: « J\'avais péché et fait fléchir la droiture, mais je n\'ai point subi la peine équivalente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Il a racheté mon âme de la descente au tombeau: Je vis! et la lumière réjouit mes regards. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Voilà, toutes ces choses, Dieu les fait deux fois, trois fois à l\'homme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'pour retirer son âme du tombeau, afin qu\'il soit éclairé de la lumière de la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'O Job! sois attentif! écoute-moi! et je parlerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Si tu as à parler, réponds-moi! parle, car je désire te donner raison!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Sinon, écoute-moi! Garde le silence, et je t\'enseignerai la sagesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Et Elihu reprit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Sages, écoutez mes discours! et, hommes entendus, prêtez-moi l\'oreille!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Car l\'ouïe éprouve les discours, de même que le palais goûte les aliments.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Démêlons ce qui est juste, et discernons ensemble ce qui est bien!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Oui, Job a dit: « Je suis juste, et Dieu m\'a frustré de mon droit!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'en dépit de mon droit je suis réduit à mentir; ma plaie est incurable, et je suis sans péché. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Y a-t-il un homme pareil à Job, pour boire le blasphème comme l\'eau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'pour marcher de concert avec les méchants, et cheminer avec les impies?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Car il a dit: « L\'homme ne retire aucun avantage de se plaire avec Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Aussi, hommes de sens, écoutez-moi! Non, Dieu n\'est point méchant, et le Tout-puissant n\'est point inique!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Il rend au contraire à l\'homme selon ses œuvres, et lui fait trouver selon ses voies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Non, en vérité Dieu n\'est pas méchant, et le Tout-puissant ne fait pas fléchir la justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Qui a commis à Dieu le soin de la terre? et qui a créé le monde, l\'Univers?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'S\'il ne pensait qu\'à Lui seul, s\'il retirait à Lui son esprit et son souffle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'toute chair expirerait soudain, et l\'homme rentrerait dans la poudre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Or, si tu as du sens, écoute ceci, prête l\'oreille au son de mes paroles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Celui qui haïrait la justice, régnerait-Il? Et oses-tu condamner le Juste, le Puissant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'qui dit à un Roi: Méchant! et: Impies! à des Princes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'qui ne prend pas parti pour des Grands, et ne préfère pas le riche au pauvre, parce qu\'ils sont l\'un et l\'autre l\'ouvrage de ses mains?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Il ne faut qu\'un instant, et ces impies meurent au milieu de la nuit; leurs peuples chancellent et passent; des potentats sont chassés, mais non par une main d\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Car Il a les yeux sur les voies des humains, et Il voit tous leurs pas:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'il n\'y a ni ténèbres, ni nuit, où puissent se cacher ceux qui font le mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Il ne Lui faut pas un long temps pour juger qu\'un homme doit paraître en jugement devant Lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Il écrase des potentats, sans enquête, et en établit d\'autres à leur place;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'car Il connaît leurs œuvres. Il les renverse de nuit, et il sont mis en pièces;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Il les supplicie sur la place des criminels, et dans un lieu exposé aux regards;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'car ils se sont retirés loin de lui, et ont négligé toutes ses voies;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'c\'est afin de Lui faire parvenir les cris des petits, pour qu\'il écoutât les cris des malheureux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Si par là Il procure le repos, qui Le condamnera? S\'il cache sa face, qui prétendra Le voir? C\'est ainsi qu\'il gouverne les nations et les hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Ôtant l\'empire à l\'impie, et aux fléaux des peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Est-ce que, en effet, ils disent à Dieu: « Je porterai [ton joug] et ne le secouerai point!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Montre-moi mes fautes qui échappent à ma vue! Si j\'ai fait le mal, je ne le ferai plus? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Réglera-t-Il d\'après toi ses rétributions? Car tu es mécontent de l\'ordre de Dieu... A toi donc, et non à moi, d\'en indiquer un autre! Dis ce que tu sais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Voici ce que me diront des hommes de sens, et le sage qui m\'aura écouté:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, '« Job ne parle pas en connaissance de cause, et ses paroles manquent de prudence. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Voici mon vœu: Que Job ne cesse pas d\'être éprouvé, parce qu\'il a répondu à l\'instar des méchants!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'car il ajoute un péché à son crime; il prend parmi nous un air de triomphe, et multiplie ses plaintes contre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Et Elihu reprit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Crois-tu avoir une juste raison, penses-tu être fondé en droit devant Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'quand tu dis: A quoi bon? Qu\'y gagné-je plus qu\'à pécher?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Je veux te faire une réponse, et à tes amis avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Regarde les Cieux! et vois!... Contemple les airs!... ils sont plus hauts que toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'En péchant, qu\'est-ce que tu Lui fais? Par mille péchés comment Lui nuirais-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'En étant juste, que Lui procures-tu? ou que recevrait-Il de la main?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'C\'est à l\'homme, comme à toi, que le péché nuit, et à l\'enfant de l\'homme, que profite ta justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Oui, de grandes oppressions font pousser des cris, et l\'on se plaint des violences de plusieurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'mais nul ne demande: « Où est Dieu, mon créateur, qui dans les jours sombres sait donner des joies,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'qui nous a mieux dotés que les bêtes des champs, et nous a faits plus sages que les oiseaux des Cieux? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Sans doute ils réclament; mais Dieu ne répond pas à l\'orgueil des impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Non! c\'est en vain! Dieu n\'exauce pas, et le Tout-puissant n\'a point égard à ces cris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Combien toi, tu seras moins écouté, si tu dis que tu peux parvenir à le voir! La cause est sous ses yeux! mets en lui ton espoir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Mais parce que sa colère ne punit pas à ton gré, le crime, selon toi, lui importe fort peu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'et Job ouvre la bouche pour de vains discours, et entasse des propos dénués de raison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Et Elihu poursuivit et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Accorde-moi un peu de patience, et je t\'instruirai! car en faveur de Dieu j\'ai encore à parler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Je prendrai mes preuves de haut, et je justifierai mon Créateur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Car mes discours certes ne seront pas menteurs, et tu trouveras en moi droiture de pensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Voici, Dieu est grand, mais Il est sans dédain, Il est grand par sa puissante intelligence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Il ne laisse pas vivre le méchant, et Il fait droit au misérable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Du juste Il ne détourne pas ses yeux, et avec les rois sur le trône pour toujours Il le place, afin qu\'il soit élevé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Mais s\'il est captif dans les fers, retenu dans les chaînes de l\'adversité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'c\'est que Dieu veut lui dévoiler sa conduite et ses péchés, car il fut orgueilleux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'faire que son oreille s\'ouvre aux leçons, et lui dire de renoncer au mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'S\'il écoute et se soumet, il achève sa vie dans la félicité, et ses années dans les délices;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'mais, s\'il n\'écoute pas, il court au devant de la flèche, et il périt, faute d\'avoir voulu comprendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Les impies nourrissent la colère, ne prient point, quand Dieu les enchaîne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'leur âme meurt dans le premier âge, et ils perdent la vie, comme les victimes de l\'infamie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Mais Il retire les malheureux de leurs maux, se révélant à eux par les afflictions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Il te tirera de même des serres de l\'angoisse, pour te mettre au large, où il n\'y aura plus de gêne; et des mets succulents seront servis sur ta table.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Mais si tu te remplis de la pensée de l\'impie, le châtiment suivra de près ta pensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Que la colère de Dieu ne te pousse pas au blasphème! Une grosse rançon ne te ferait pas échapper:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'ta richesse y suffirait-elle? Ici l\'or et les moyens de l\'opulence ne font rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Ne soupire pas après la nuit qui arrache des peuples de leur sol!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Veille sur toi! ne prends pas le parti du mal... Car il te semble préférable au malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Voici, Dieu est élevé par sa puissance; est-il un maître pareil à Lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Qui lui prescrira ses voies? et qui lui dira: Tu fais mal?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Pense à exalter ses œuvres, que les hommes célèbrent par leurs chants!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Tous les humains les admirent, quoiqu\'un mortel ne les voie que de loin!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Voici, Dieu est grand, nous ne Le concevons pas, le nombre de ses ans ne peut être trouvé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Quand Il attire les gouttes de l\'eau, la vapeur qu\'il en forme distille la pluie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'que versent les nuages qui l\'épanchent sur la foule des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Qui comprendra les déchirements de la nue, et le fracas dont Sa tente retentit?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Voici, autour de Lui Il déploie la clarté, et prend pour se couvrir la mer jusques dans ses racines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Car tels sont ses moyens pour châtier les peuples, et pour donner la nourriture avec abondance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Il arme ses mains de flammes, et à son ordre elles fondent sur les rebelles:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Son grondement l\'annonce, annonce aux troupeaux son approche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Oui, à ce bruit mon cœur s\'épouvante, il s\'ébranle et se déplace.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Ecoutez! écoutez le roulement de sa voix, et le murmure qui sort de sa bouche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Il lui fait parcourir tout le ciel, et Il lance l\'éclair jusqu\'à l\'horizon de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Aussitôt sa voix mugit, Il tonne de sa voix de majesté, et ne retient plus sa foudre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Dieu par sa voix produit la merveille du tonnerre; Il fait des choses grandes que nous ne comprenons point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Il dit à la neige: Tombe sur la terre! la pluie et les torrents de pluie attestent sa puissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Il engourdit les mains de tous les hommes, afin que tous les humains qui sont ses créatures, reconnaissent ce qu\'il est.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Alors les bêtes sauvages gagnent leurs tanières, et sommeillent dans leurs cavernes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'La tempête sort de sa prison, et les vents impétueux amènent la froidure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Au souffle de Dieu la glace est formée, et les ondes dilatées se condensent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'd\'humidité Il charge aussi la nue; Il épand les nuages porteurs de ses feux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'qui tournoient en tout sens, sous sa conduite, pour exécuter tout ce qu\'il leur commande, sur la surface du disque de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'tantôt pour punir, si sa terre est coupable, tantôt pour bénir, Il les fait arriver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'O Job, prête l\'oreille à ces choses! continue à étudier les miracles de Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'En sais-tu les causes, quand Dieu les fait paraître, et qu\'il fait resplendir le feu de sa nuée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Comprends-tu le balancement des nues, merveille du Dieu parfaitement sage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'la chaleur que prennent tes vêtements, quand la terre reçoit du midi un air qui accable?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Etendras-tu, comme Lui, le firmament, lui donnant la solidité d\'un miroir de fonte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Apprends-nous ce qu\'il nous faut Lui dire? Ah! les ténèbres où nous sommes, nous mettent hors d\'état de Lui rien proposer!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Mes discours lui seront-ils rapportés?... Mais désira-t-on jamais d\'être anéanti?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Aussi bien l\'on ne regarde point fixement le soleil, quand il brille dans les airs, et qu\'un vent passe, et lui rend sa pureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Du Septentrion l\'on peut bien tirer l\'or, mais Dieu oppose un éclat formidable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Jusqu\'au Tout-puissant nous ne saurions pénétrer! Il est éminent par la force et par l\'équité, et par une souveraine justice; Il ne rend aucun compte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Craignez-le donc, ô hommes; Il n\'accorde ses regards à aucun des sages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Et l\'Éternel répondit à Job du milieu de la tempête et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Qui est-ce qui obscurcit mes décrets par des discours dénués d\'intelligence?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Eh bien! ceins tes reins, comme un homme! puis je te questionnerai, et tu m\'instruiras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Où étais-tu, quand je fondai la terre? Indique-le, si tu as vraiment la science!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Qui est-ce qui en fixa la dimension, que tu saches, ou étendit sur elle le cordeau?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Quel est le support jusqu\'où ses bases plongent? Ou qui est-ce qui en a posé la pierre angulaire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'aux accords unanimes des étoiles du matin, aux acclamations de tous les Fils de Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Et qui est-ce qui enferma la mer entre des portes, quand elle fit éruption du sein maternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'quand je lui donnai la nuée pour manteau, et les sombres vapeurs pour lui servir de langes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'quand je lui prescrivis ma loi, et que j\'établis ses barres et ses portes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'et que je dis: Jusqu\'ici tu viendras, et pas plus avant! et ici s\'arrêtera l\'orgueil de tes vagues?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'De ton vivant as-tu commandé au matin, et fait connaître à l\'aurore le lieu d\'où elle part,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'pour saisir la terre par ses bords? Alors les impies en sont balayés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'alors la terre prend une face nouvelle, telle que l\'argile qui reçoit une empreinte, et toutes choses paraissent comme pour la vêtir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'alors les impies perdent la clarté qu\'ils aiment, et le bras qu\'ils ont levé déjà, se brise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'As-tu pénétré jusqu\'aux sources des mers, et au fond de l\'abîme as-tu porté tes pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Les portes de la mort te furent-elles découvertes? As-tu vu les portes de la sombre mort?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Ton regard embrasse-t-il les contours de la terre? Raconte, si tu sais toutes ces choses!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Quelle route mène où la lumière habite? et la nuit, où fait-elle son séjour?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Iras-tu les chercher l\'une et l\'autre, pour les amener chacune à leurs limites? Et connais-tu le chemin de leur demeure?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Tu le sais! car alors tu étais déjà né! et le nombre de tes jours est immense!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'As-tu pénétré jusqu\'aux dépôts de la neige, et as-tu vu les dépôts de la grêle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'que je réserve pour les temps du désastre, pour le jour du combat et de la bataille?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Quel chemin mène aux lieux où la lumière se divise, d\'où le vent d\'Est se répand sur la terre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Qui a fait ces conduits qui éparpillent la pluie, et a tracé une route à la foudre bruyante,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'afin d\'arroser une terre inhabitée, une steppe où il n\'y a pas un humain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'afin d\'abreuver les lieux déserts et solitaires, et de fertiliser le sol qui donne le gazon?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'La pluie a-t-elle un père? Ou qui est-ce qui engendra les gouttes de la rosée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Du sein de qui la glace sort-elle? et qui est-ce qui produit le givre du ciel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Comme la pierre, les eaux se condensent, et la surface de l\'abîme est enchaînée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'As-tu formé le lien qui unit les Pléiades? Ou peux-tu détacher les chaînes d\'Orion?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Fais-tu paraître en leur temps les signes du Zodiaque? Ou conduis-tu Arcture avec son cortège?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Connais-tu les lois des Cieux? Les as-tu mis à même d\'influer sur la terre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Parles-tu à la nue avec autorité, et te couvre-t-elle aussitôt d\'une eau abondante?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Lances-tu des foudres, et partent-elles, et disent-elles: Nous voici?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Qui a mis une sagesse dans les sombres nuages, et a donné aux météores une intelligence?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Qui a calculé les nuées avec sagesse? Et qui est-ce qui incline les urnes des Cieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'quand la poussière coule comme un métal en fonte, et que les glèbes se collent l\'une à l\'autre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Pour la lionne vas-tu chasser une proie? et assouvis-tu la faim des lionceaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'quand ils sont blottis dans leurs repaires, ou dans leurs tanières, tapis en embuscade?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Qui est-ce qui procure au corbeau sa pâture, quand ses petits poussent vers Dieu leurs cris, et errent affamés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Sais-tu l\'époque où met bas le chamois? Et présides-tu à la délivrance des biches?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Comptes-tu les mois que dure le temps de leur portée, et connais-tu l\'époque où elles faonnent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Elles se baissent, laissent leurs petits naître, et secouent leurs douleurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'leurs petits deviennent forts, grandissent en plein air; ils partent, et ne reviennent plus à elles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Qui est-ce qui a mis l\'onagre en liberté, et lâché les liens de l\'âne sauvage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'auquel je donnai le désert pour logis, et la plaine salée pour habitation?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Il se rit de la rumeur des villes, et les cris du meneur ne frappent pas son oreille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Ce qu\'il attrape sur les montagnes est sa pâture, et il est en quête de tous les brins d\'herbe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Le buffle consent-il à te servir? Ou passe-t-il la nuit à côté de ta crèche?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Attaches-tu par une corde le buffle au sillon? Ou herse-t-il les guérêts à ta suite?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Te fies-tu en lui, parce que grande est sa force? Et t\'en remets-tu à lui de ton labour?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Comptes-tu qu\'il fasse rentrer les récoltes, et les entasse sur ton aire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'L\'autruche bat joyeusement de l\'aile: serait-ce la plume et le duvet du volatile aimant?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Non! elle abandonne ses œufs à la terre, et les laisse chauffer dans le sable;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'et elle oublie qu\'un pied peut les fouler, et une bête des champs les écraser! Elle est dure pour sa famille,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'qui lui devient étrangère; elle a pondu en vain, et n\'en est point émue;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'car Dieu lui fait oublier d\'être sage, et ne lui donne point part à la prudence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Quand elle se lève, et prend son essor, elle se rit du cheval et de son cavalier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Est-ce toi qui dotes le cheval de la bravoure, et revêts son col d\'un crin frémissant?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Le fais-tu bondir, comme la sauterelle? Son souffle avec noblesse résonne dans ses naseaux, et il inspire l\'effroi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Il fouit le sol, et s\'applaudit de sa force; il s\'avance au devant des armes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'il se rit de la peur, et ne tremble pas, et il ne recule point en face de l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Sur lui retentit le carquois, la lance étincelante et le javelot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'De son pas il dévore le terrain qui s\'émeut et tremble; il ne se contient plus au son de la trompette;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'à l\'ouïe de la trompette il dit: En avant! De loin il pressent la bataille, la clameur des chefs, et le cri de guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Est-ce par un effet de ton intelligence que l\'épervier prend son vol, et déployant ses ailes gagne le Midi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Est-ce à ton ordre que l\'aigle s\'élève, et va placer son aire sur les hauteurs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Il habite les rochers, et se loge sur les cîmes des rochers, le sommet des montagnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'de là il épie sa proie, et ses yeux voient au loin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'et ses petits sucent le sang, et, là où sont des cadavres, il se trouve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Puis l\'Éternel s\'adressant à Job lui dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Le censeur prend-il encore le Tout-puissant à partie? Que l\'accusateur de Dieu réponde maintenant!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Et Job répondit à l\'Éternel et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Voici, je suis trop chétif, que répliquerais-je? Je mets ma main sur ma bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'J\'ai parlé une fois, je ne répondrai pas, une seconde fois, et je ne le ferai plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Et l\'Éternel répondit à Job du milieu de la tempête et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Allons! ceins tes reins, comme un homme! Je t\'interrogerai, et tu m\'instruiras!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Penses-tu à déchirer aussi mes arrêts, à me condamner, pour paraître innocent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Ou bien as-tu un bras comme Dieu, et de la voix comme Lui peux-tu tonner?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Eh bien! revêts donc l\'éclat et la grandeur! pare-toi de la gloire et de la magnificence!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Epanche les flots de ta colère, Et d\'un regard terrasse tous les superbes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'D\'un regard abats le superbe, et écrase les impies sur la place!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Abîme-les tous dans la poudre, et cache leurs fronts dans les ténèbres!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Alors de mon côté je pourrai te louer de ce qu\'en ta main tu trouves des ressources.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Vois le Béhémoth que je créai comme toi! Ainsi que le bœuf, il broute l\'herbe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Vois la force qu\'il a dans ses reins, et la vigueur qu\'il a dans les muscles de sa panse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Il replie sa queue [roide] comme un cèdre; les tendons de ses flancs sont entrelacés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'ses os sont des tubes d\'airain, et ses jambes, des barres de fer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Il est le chef-d\'œuvre de Dieu; son Créateur l\'arma du glaive');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'dont il fauche sa pâture sur les monts, où folâtrent toutes les bêtes des champs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Il se couche sous les feuilles du lotus, et les joncs et le marécage lui donnent un abri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Pour lui le lotus entrelace son ombrage, les saules de la rivière l\'environnent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Voici, que le fleuve se soulève, il n\'a point peur; il prend plutôt de l\'assurance, quand un Jourdain bouillonne jusqu\'à sa bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Peut-on, pour le prendre, tromper son regard, ou percer son naseau pour l\'enchaîner?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Tires-tu le Léviathan avec l\'hameçon, fais-tu passer la ligne au travers de sa langue?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Attaches-tu la corde à son naseau, et perces-tu sa mâchoire pour y mettre l\'anneau?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Va-t-il t\'adresser beaucoup de prières, et te parler d\'une voix adoucie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Va-t-il faire un pacte avec toi, pour s\'engager à te servir toujours?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Vas-tu jouer avec lui comme avec un oiseau, et le mettre à l\'attache pour tes jeunes filles?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Entre-t-il dans le trafic de la confrérie, et le répartit-elle entre les marchands?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Couvres-tu sa peau de dards, et sa tête de harpons?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Tentes-tu de mettre la main sur lui; tu ne t\'aviseras plus de l\'attaquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Voici, l\'espoir de l\'agresseur est bientôt déçu; n\'est-il pas terrassé à son seul aspect?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Nul n\'a l\'audace de le provoquer: et qui pourrait Me prendre à partie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Qui m\'a prévenu, pour que j\'aie à lui rendre? Sous le ciel entier tout est ma propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Je ne tairai point sa structure, ni la nature de sa force, ni la beauté de son armure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Qui a pu soulever le recouvrement de sa robe, et pénétrer entre sa double mâchoire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Qui entr\'ouvrit les portes de sa face? Tout autour sont ses dents effroyables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Des sillons sont tracés entre les boucliers de sa croupe, retenus par un sceau qui les presse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'ils sont soudés l\'un à l\'autre, et l\'air ne s\'insinue pas dans leurs intervalles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'entre eux ils sont adhérents, et forment un masse solide, inséparable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Son éternuement produit une gerbe lumineuse, et ses yeux sont comme les paupières de l\'aurore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'De sa gueule sortent des torches, et des étincelles enflammées s\'échappent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Une fumée jaillit de ses narines, comme d\'un vaisseau qui bout, et d\'une chaudière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Son haleine allume les charbons, et des flammes partent de sa bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'La force réside dans son encolure, et devant lui la détresse tressaille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Les fanons de sa chair sont adhérents, coulés sur son corps, immobiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Son cœur a la densité de la pierre, et la densité de la meule inférieure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Se lève-t-il, les héros s\'épouvantent, et la peur les déroute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Le coup qu\'on lui porte, demeure sans effet; il brave la lance, le dard et la cuirasse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, 'Pour lui le fer est autant que de la paille, et l\'airain, que du bois vermoulu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, 'La flèche décochée ne le met pas en fuite, et sur lui les pierres de la fronde font l\'effet de la balle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, 'Pour lui la massue est autant que du chaume, et il se rit du frémissement des traits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, 'Son ventre est muni de têts acérés; on dirait que sur le limon où il couche, un traîneau à fouler a laissé son empreinte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, 'Il fait comme une chaudière bouillonner l\'onde, et donne à la mer l\'aspect d\'un vaisseau où l\'on broie les parfums.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, 'Il laisse après lui un sillage lumineux; on prendrait la mer pour une blanche chevelure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, 'Sur la terre il n\'a pas de maître; il fut créé pour être intrépide;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, 'il ose regarder toute taille élevée, il est Roi au-dessus de tous les fiers animaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Et Job répondit à l\'Éternel et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Je sais que tu peux tout, et qu\'il n\'y aura jamais d\'obstacle à tes plans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Ah! qui est-ce qui a obscurci tes décrets faute d\'intelligence?... Aussi ai-je voulu expliquer ce que je ne peux comprendre, des choses qui sont hors de ma portée, et que je ne puis concevoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'O! écoute! et que je parle à mon tour! Je t\'interrogerai, et tu m\'instruiras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Ce que je savais de toi n\'était qu\'un ouï-dire; mais maintenant je t\'ai vu de mes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Aussi je me rétracte, et je fais pénitence sur la poudre et la cendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Et après que l\'Éternel eut adressé ces discours à Job, l\'Éternel dit à Eliphaz de Théman: Ma colère s\'allume contre toi et contre tes deux amis, car vous n\'avez pas bien parlé de moi, comme mon serviteur Job.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Or maintenant prenez sept taureaux et sept béliers, et allez auprès de mon serviteur Job, et offrez un holocauste pour vous, et que Job, mon serviteur, prie en votre faveur; ce n\'est qu\'en considération de lui que je ne vous infligerai pas de châtiment; car vous n\'avez pas bien parlé de moi, comme mon serviteur Job.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Alors Eliphaz de Théman, et Bildad de Such, et Zophar de Naama allèrent, et firent comme l\'Éternel avait dit; et l\'Éternel eut égard à Job.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Et l\'Éternel rendit à Job ce qu\'il avait perdu, parce qu\'il pria en faveur de ses amis; et l\'Éternel augmenta du double tout ce que Job possédait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Alors tous ses frères, et toutes ses sœurs, et tous ses familiers d\'autrefois vinrent vers lui, et mangèrent avec lui dans sa maison, et le plaignirent, et le consolèrent de tous ses maux que l\'Éternel avait fait venir sur lui, et ils lui donnèrent chacun une Kesita, et chacun un anneau d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Et l\'Éternel bénit la fin de Job plus que son commencement; et il eut quatorze mille brebis, et six mille chameaux, et mille attelages de bœufs, et mille ânesses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'et il eut sept fils et trois filles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'et il donna à la première le nom de Jémina (belle comme le jour) et à la seconde le nom de Césia (parfum) et à la troisième le nom de Kéren-appuch (flacon de fard).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Et il ne se trouvait pas dans tout le pays de femmes belles comme les filles de Job; et leur père leur donna une part d\'héritage parmi leurs frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Et après cela Job vécut cent quarante ans; et il vit ses fils et les fils de ses fils jusqu\'à la quatrième génération.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Et Job mourut âgé, et rassasié de jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Heureux l\'homme qui ne suit point le conseil des impies, et ne pratique point la voie des pécheurs, et ne prend point place au cercle des moqueurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'mais qui fait son plaisir de la loi de l\'Éternel, et médite sa loi le jour et la nuit!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Il est comme un arbre planté près d\'une eau courante, qui donne son fruit en sa saison, et dont la feuille ne se flétrit point: tout ce qu\'il fait, est suivi de succès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Tels ne sont point les impies, mais ils sont comme la balle dissipée par le vent:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'aussi ne tiennent-ils pas devant le jugement, non plus que les pécheurs dans l\'assemblée des justes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'car l\'Éternel a l\'œil sur la voie des justes, mais la voie des impies mène à la ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Pourquoi cette rumeur dans les nations, et chez les peuples, ces complots inutiles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'cette levée des rois de la terre, et ces princes en conseil assemblés contre l\'Éternel et contre son Oint?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, '« Rompons leurs fers, et secouons leurs chaînes! » [disent-ils.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Sur son trône dans les Cieux Il se rit, le Seigneur se raille d\'eux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'puis Il leur parle dans sa colère, et par son courroux Il les épouvante:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, '« Moi-même j\'ai oint mon Roi sur Sion, ma montagne sainte! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, '– « Que je redise le décret! L\'Éternel m\'a dit: Tu es mon fils, en ce jour je t\'ai engendré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Demande-moi, et je te donnerai les nations en héritage, et en propriété les extrémités de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'tu les briseras d\'un sceptre de fer, comme un vase de potier, tu les mettras en pièces. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Maintenant, ô rois, devenez sages, soyez avertis, juges de la terre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Soumettez-vous à l\'Éternel avec crainte, soyez alarmés et tremblez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Embrassez le Fils, de peur qu\'il ne s\'irrite, et que vous ne vous perdiez en suivant votre voie. Car un instant encore, et sa colère s\'allume. Heureux tous ceux qui mettent en lui leur confiance!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Cantique de David, quand il fuyait devant Absalon, son fils. O Éternel, que mes ennemis sont nombreux! en nombre ils se lèvent contre moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Leur foule dit de moi: « Il n\'est par-devers Dieu point de salut pour lui. » (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Mais tu es, ô Éternel, le bouclier qui me couvre, tu es ma gloire, c\'est toi qui tiens ma tête levée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'De ma voix j\'invoque l\'Éternel, et Il me répond de sa montagne sainte. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Je me couche, et je m\'endors; je m\'éveille, car l\'Éternel est mon soutien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Je suis sans peur devant des milliers d\'hommes contre moi campés de toute part.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Sus! Éternel! sauve-moi, mon Dieu! car tu romps la mâchoire à tous mes ennemis, et tu brises les dents des impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Le salut vient de l\'Éternel! Que ta bénédiction soit sur ton peuple! (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Au maître chantre. Avec instruments à cordes. Cantique de David. Quand je crie, réponds-moi, mon juste Dieu! Dans l\'angoisse dégage-moi! Sois-moi propice, et écoute ma prière!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'O hommes, jusques à quand mon honneur sera-t-il outragé, aimerez-vous la vanité, poursuivrez-vous le mensonge? (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Cependant sachez que l\'Éternel a distingué son Saint! L\'Éternel écoute, quand je l\'invoque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Tremblez et ne péchez point! Couchés, pensez-y en vos cœurs, et restez tranquilles! (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Offrez des sacrifices de justice, et confiez-vous dans l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Plusieurs disent: O puissions-nous voir le bonheur! Fais lever sur nous la clarté de ta face, ô Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Tu donnes plus de joie à mon cœur, que quand leur blé et leur moût ont été abondants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'En paix je me couche, en paix je m\'endors, car seul, ô Éternel, tu me fais demeurer en sûreté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Au maître chantre. Avec les flûtes. Cantique de David, Prête l\'oreille à mes paroles, Éternel! sois attentif à mes soupirs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Ecoute ma voix qui appelle, ô mon Roi! ô mon Dieu! car c\'est toi que je prie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Éternel, dès le matin tu entends ma voix, dès le matin je me tourne vers toi, et j\'attends.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Car tu n\'es point un Dieu qui aime l\'impiété; le méchant chez toi n\'est point accueilli;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'les superbes n\'osent paraître à tes yeux; tu hais tous ceux qui font le mal;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'tu détruis les menteurs, et les hommes de sang et de fraude, l\'Éternel les abhorre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Mais moi, par ton grand amour, je viens dans ta maison, je me prosterne dans ton saint temple, en ta crainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Éternel, fais-moi marcher dans ta justice, à cause de mes ennemis! Aplanis devant moi ta voie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Car dans leur bouche il n\'y a point de vérité, dans leur cœur, c\'est envie de nuire, leur gosier est un sépulcre ouvert, et ils rendent leur langue flatteuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Punis-les, ô Dieu! déjoue leurs projets! A cause de leurs nombreux crimes, renverse-les! car ils se rebellent contre toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Alors se réjouiront tous ceux qui se confient en toi; et ils te célébreront à jamais, parce que tu les protèges; et tu seras l\'allégresse de tous ceux qui aiment ton nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Car tu bénis le juste, ô Éternel; comme d\'un bouclier tu l\'entoures de grâce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Au maître chantre. Avec les instruments à cordes. En octave. Cantique de David. Éternel, ne me châtie pas selon ta colère, et ne me punis pas selon ton courroux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Sois-moi propice, Éternel! car je suis défaillant; guéris-moi, Éternel! car mes os sont ébranlés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'et mon âme est fort ébranlée: mais toi, Éternel, jusques à quand?...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Reviens, Éternel, délivre mon âme, sauve-moi pour l\'amour de ta grâce!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Car dans la mort ta mémoire n\'est pas rappelée, et dans les Enfers qui pourrait te louer?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Je m\'épuise en soupirs, et chaque nuit je baigne mon lit de pleurs, j\'en inonde ma couche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Mes yeux s\'éteignent dans le chagrin, ils dépérissent à cause de tous mes ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Loin de moi, vous tous les artisans de malice! car l\'Éternel entend la voix de mes pleurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'l\'Éternel entend ma supplication, l\'Éternel accueille ma prière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Tous mes ennemis sont confus, saisis d\'un grand effroi, ils reculent confondus tout-à-coup.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Complainte de David, qu\'il chanta à l\'Éternel à propos de Cus, Benjamite. Éternel, mon Dieu, à toi j\'ai mon recours: sauve-moi de tous mes persécuteurs, et me délivre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'de peur que, comme un lion, ils ne me déchirent, m\'écrasant, faute de libérateur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Éternel, mon Dieu! si c\'est ici ce que j\'ai fait, s\'il y a de l\'iniquité dans mes mains,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'si j\'ai payé mon ami par le mal, dépouillé celui qui me haïssait sans cause;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'que l\'ennemi poursuive ma vie, qu\'il m\'atteigne et me foule contre terre, et traîne ma gloire dans la poussière! (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Lève-toi, Éternel, dans ta colère! élève-toi contre les fureurs de mes ennemis! Sus! à moi! apprête le jugement!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Que l\'assemblée des peuples t\'environne! au-dessus d\'elle monte sur un lieu élevé!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'L\'Éternel juge les peuples: Éternel, fais-moi justice! que selon ma justice et mon innocence il me soit fait!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Mets donc fin à la malice des impies, et fortifie le juste! toi qui sondes les cœurs et les reins, Dieu juste!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Mon bouclier est par-devers Dieu, qui est en aide à ceux dont le cœur est droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Dieu est un juste juge, un Dieu prêt à s\'irriter en tout temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'S\'il ne s\'arrête, Il aiguise son épée, Il bande son arc et l\'ajuste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'et dirige sur lui des traits mortels, des traits qu\'il enflamme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Voici, il avait conçu le mal, et portait la malice dans son sein; mais il a enfanté une déception.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Il a fait une fosse, il l\'a creusée, mais il est tombé dans le creux par lui préparé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Sa malice retombe sur sa tête, et sa violence redescend sur son front.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'J\'exalterai l\'Éternel selon sa justice, et je chanterai le nom de l\'Éternel, du Très-haut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Au maître chantre. En githith. Cantique de David. Éternel, notre Seigneur, Que ton nom est magnifique sur toute la terre! Elle élève ta gloire jusques aux Cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Par la bouche des enfants et de ceux qu\'on allaite, tu fondes ta louange, à cause de tes adversaires, pour faire taire ton ennemi et les agresseurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Quand je contemple ton ciel, ouvrage de tes doigts, la lune et les étoiles que tu y as fixées:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Qu\'est-ce que l\'homme, [pensé-je,] pour que tu songes à lui? et l\'enfant d\'Adam, pour que tu regardes à lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Et peu s\'en faut que de lui tu n\'aies fait un Dieu, et de gloire et de grandeur tu l\'as couronné;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'tu l\'as fait roi des œuvres de tes mains, tu as mis toutes choses à ses pieds,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'à la fois la brebis et le bœuf, et les bêtes des champs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'les oiseaux du ciel et les poissons de la mer, tout ce qui parcourt les sentiers des mers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Éternel, notre Seigneur, que ton nom est magnifique sur toute la terre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Au maître chantre. Avec voix de jeunes filles. Sur bénites. Cantique de David. Je loue l\'Éternel de tout mon cœur; je vais dire toutes tes merveilles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'l\'allégresse et la joie que je trouve en toi, chanter ton nom, ô Très-haut!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Car mes ennemis se retirent en arrière, chancellent et disparaissent à ta vue!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Car tu défends ma cause et mon droit, tu sièges sur ton trône en juste juge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Tu tances les peuples, détruis les impies, effaces leur nom pour toujours, à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Mes ennemis sont perdus, ruines éternelles! Tu as détruit leurs villes, leur mémoire a péri!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Oui, l\'Éternel règne à perpétuité, Il a pour le jugement disposé son trône,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'et Il juge le monde avec justice, et rend aux peuples des sentences équitables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Et l\'Éternel est un refuge pour le pauvre, un refuge dans les temps de détresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Ils se confient en toi ceux qui connaissent ton nom; car tu ne délaisses pas ceux qui te cherchent, Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Chantez l\'Éternel, qui réside en Sion, racontez aux nations ses hauts faits!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Car, vengeur du sang, Il se souvient d\'eux, Il n\'oublie pas le cri des malheureux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Sois-moi propice, Éternel! Vois la misère où mes ennemis me réduisent; retire-moi des portes de la mort,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'afin que je publie toute ta louange aux Portes de la fille de Sion, me réjouissant de ton secours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Les nations enfoncent dans la fosse qu\'elles ont creusée; leur pied se prend au filet qu\'elles ont caché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'L\'Éternel s\'est montré; Il a fait justice, en enlaçant l\'impie dans l\'ouvrage même de ses mains. (Harpes. Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Les impies vont dans les Enfers, et de même tous les peuples qui ont oublié Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Car toujours le pauvre ne sera pas oublié, et l\'espoir des malheureux n\'est pas à jamais perdu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Lève-toi, Éternel, afin que l\'homme ne s\'élève pas, afin que les nations soient jugées devant toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Mets, Éternel, ta terreur sur elles! que les peuples sentent qu\'ils ne sont que des hommes. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Éternel, pourquoi te tiens-tu à l\'écart, te caches-tu dans des temps de détresse?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Le malheureux pâtit de l\'orgueil des impies, il se prend dans les trames qu\'ils ourdissent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Car l\'impie fait gloire de sa convoitise, et le ravisseur maudit, méprise l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'L\'impie présomptueux est sans inquiétude: « Il n\'y a point de Dieu! » voilà toutes ses pensées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Le succès est sur sa route en tout temps; il n\'élève point ses regards jusques à tes jugements; sur ses ennemis il souffle avec dédain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Il dit en son cœur: « Je suis inébranlable, d\'âge en âge à l\'abri des revers. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Sa bouche est pleine de parjure, de fraude et de malice, et sa langue recèle la violence et la ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Posté en embuscade près des hameaux, en guet-apens il tue les innocents, et dans l\'ombre son œil épie le malheureux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Il guette de sa retraite, comme le lion de son repaire, il guette pour saisir le malheureux; il saisit le malheureux, le tirant dans son filet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Il se tapit, il se baisse, et entre ses griffes tombe le malheureux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Il dit en son cœur: « Dieu oublie! Il voile sa face, et ne regarde jamais! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Debout! Éternel! ô Dieu, lève ta main! N\'oublie pas les malheureux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Pourquoi l\'impie a-t-il pour Dieu ce mépris, dit-il en son cœur: « Tu ne recherches pas »?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Tu as vu! car tu as l\'œil sur la douleur et la peine, et tu l\'inscris sur ta main; le malheureux s\'en remet à toi; pour l\'orphelin tu fus toujours un aide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Brise le bras de l\'impie, et du méchant recherche le crime, afin que tu ne le retrouves plus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Le Seigneur est un Roi permanent, éternel; de son pays les nations sont exterminées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Éternel, tu entends les vœux des misérables, tu fortifies leur cœur, tu inclines ton oreille,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'tu fais droit à l\'orphelin et au pauvre, afin que de la terre désormais l\'homme ne te brave plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Au maître chantre. De David. Dans l\'Éternel je mets ma confiance; comment pouvez-vous me dire: « Comme l\'oiseau, fuyez vers vos montagnes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Car voici, les impies bandent leur arc, ils ajustent leurs flèches sur la corde, dans l\'ombre, pour tirer sur les gens de bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Quand les fondements s\'écroulent, le juste, que ferait-il? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'L\'Éternel est dans son saint parvis, l\'Éternel a son trône dans les Cieux, ses yeux voient, ses regards sondent les enfants des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'L\'Éternel sonde le juste; et l\'impie et l\'ami de la violence sont odieux à son âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Il fait pleuvoir sur les méchants des foudres; le feu, et le soufre et le vent embrasé, tel est le calice qu\'ils ont en partage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Car l\'Éternel est juste, Il aime la justice; l\'homme droit contemple sa face.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Au maître chantre. En octave. Cantique de David. Sois-nous en aide, Éternel! car les bons diminuent, et les fidèles sont perdus parmi les enfants des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'On se tient l\'un à l\'autre le langage du mensonge; la flatterie est sur les lèvres, le cœur double dans les discours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Que l\'Éternel détruise les lèvres qui flattent, et la langue qui parle avec forfanterie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'ceux qui disent: « Notre langue nous donne la puissance! Nous avons la parole, qui sera maître de nous? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Pour le pauvre opprimé, et l\'indigent qui soupire, à cette heure je me lève, dit l\'Éternel, et je leur donnerai le secours auquel ils aspirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Les paroles de l\'Éternel sont pures, comme l\'argent qu\'au creuset l\'on dégage de terre, et purifie sept fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Toi-même, ô Éternel, tu les garderas, tu les protégeras contre cette race à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Que partout les impies se promènent, comme quand la tempête se lève sur les hommes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Au maître chantre. Cantique de David. Jusques à quand, Éternel, m\'oublieras-tu toujours? Jusques à quand me cacheras-tu ta face?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Jusques à quand aurai-je l\'inquiétude dans l\'âme, et tout le jour le chagrin dans le cœur? Jusques à quand mon ennemi s\'élèvera-t-il au-dessus de moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Ah! regarde, exauce-moi, Éternel, mon Dieu! Fais luire ta clarté dans mes yeux, afin que je ne m\'endorme pas du sommeil de la mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'que mon ennemi ne dise pas: « Je l\'ai vaincu! » et que ma défaite ne réjouisse pas mes oppresseurs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Mais, en ta bonté je me confie! Ton secours réjouira mon cœur:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'je louerai l\'Éternel du bien qu\'Il m\'aura fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Au maître chantre. Cantique de David. Les impies ont dit en leur cœur: « Il n\'y a point de Dieu. » Ils se sont corrompus, leurs œuvres sont abominables; il n\'y a personne qui fasse le bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'L\'Éternel examine des Cieux les enfants des hommes, pour voir s\'il y a quelque homme raisonnable, qui cherche Dieu:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'tous se sont révoltés, pervertis tous ensemble; il n\'y a pas un homme qui fasse le bien, pas même un.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Ne se reconnaîtront-ils pas tous ces malfaiteurs, qui mangent mon peuple comme du pain? N\'invoqueront-ils point l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Bientôt la terreur les saisira; car Dieu est au milieu de la race juste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Déjouez les projets du misérable!... \\ L\'Éternel est son refuge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Ah! si de Sion le salut venait sur Israël!... \\ Que l\'Éternel ramène les captifs de son peuple, et Jacob se réjouira, et Israël triomphera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Cantique de David. Éternel, qui sera ton hôte dans ta tente? Qui habitera sur ta sainte montagne?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Celui qui vit dans l\'intégrité, et pratique la justice, et dit la vérité telle qu\'elle est dans son cœur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'dont la langue ne sème point la calomnie, à son prochain ne cause point de dommage, et ne profère pas d\'outrages contre son frère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'aux yeux de qui le réprouvé est digne de mépris, et qui honore les hommes craignant l\'Éternel; qui jure au méchant, et ne se dédit point;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'qui ne tire de son argent aucun intérêt, et contre l\'innocent n\'accepte point de présents. Qui ainsi agira, ne sera point ébranlé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Ecrit de David. Garde-moi, ô Dieu, car je me retire vers toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'J\'ai dit à l\'Éternel: Tu es le Seigneur, en toi j\'ai mon souverain bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Les saints, qui sont dans le pays, sont les nobles en qui je prends tout mon plaisir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Nombreux sont les maux de ceux qui courent ailleurs; je n\'offre point leurs libations de sang, et leurs noms ne sont jamais sur mes lèvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'L\'Éternel est mon lot, et la coupe qui est ma part; c\'est toi qui m\'assures mon héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Mon domaine m\'est échu dans de beaux lieux, et mon patrimoine est aussi mon délice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Je bénis l\'Éternel qui a été mon conseil; et, les nuits même, mon cœur me donne ses avis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Je me suis proposé l\'Éternel devant moi constamment; car s\'Il est à ma droite, je ne serai pas ébranlé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Aussi la joie est dans mon cœur, et l\'allégresse dans mon âme, et ma chair aussi repose sûrement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'car tu n\'abandonneras pas mon âme aux Enfers, et tu ne permettras pas que celui qui t\'aime voie le tombeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Tu me montreras les sentiers de la vie. En ta présence on trouve plénitude de joie, et dans ta droite, des plaisirs pour toujours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Prière de David. Éternel, écoute la justice, prête l\'oreille à ma plainte, entends, quand je te prie d\'une bouche sans feinte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Que ma cause paraisse devant toi: tes yeux discernent la droiture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Sonde mon cœur, visite-moi la nuit; éprouve-moi, tu ne trouveras rien; ma pensée ne va pas plus loin que ma parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'En face des œuvres des hommes, aidé de ta parole, j\'évitai les sentiers des pervers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Maintiens mes pas dans tes ornières, afin que mes pieds ne bronchent pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Je t\'invoque, car tu m\'exauceras, ô Dieu! penche vers moi ton oreille, écoute mon discours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Signale ta bonté, toi qui de ta droite, sauves le fidèle de ceux qui l\'assaillent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Garde-moi, comme la prunelle chère à ton œil, et me cache à l\'ombre de tes ailes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'contre les impies qui m\'attaquent, contre les mortels ennemis qui m\'enveloppent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Ils ont fermé leur cœur endurci, et ils tiennent de leur bouche des propos altiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'A tous nos pas maintenant ils nous assiègent, de leurs yeux ils visent à nous terrasser;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'pareils au lion avide d\'une proie, au jeune lion tapi en embuscade.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Lève-toi, Éternel, préviens-les, terrasse-les! Sauve-moi par ton épée des méchants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'par ta main, Éternel, des hommes, des hommes de ce monde! Ils ont leur lot dans la vie, et tu remplis leur sein de trésors: leurs fils s\'en rassasient, et laissent leur superflu à leurs enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Mais pour moi, la justice me fera voir ta face, et, à mon réveil, je me rassasierai de ton image.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Au maître chantre. Du serviteur de l\'Éternel, de David, qui adressa à l\'Éternel les paroles de ce cantique, lorsque l\'Éternel l\'eut délivré de la main de tous ses ennemis, et de la main de Saül; et il dit: Je t\'aime, ô Éternel, ô source de ma force,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Éternel, mon rocher, mon asile et mon libérateur! mon Dieu! ô mon rocher, où je vais m\'abriter! mon bouclier, corne de mon salut, mon boulevard!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Loué soit l\'Éternel! me suis-je écrié, et de mes ennemis j\'ai été délivré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Les vagues de la mort m\'enserraient, et les torrents de l\'adversité m\'épouvantaient;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'les chaînes des Enfers m\'enlaçaient, et j\'étais pris dans les rêts de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Dans mon angoisse j\'invoquai l\'Éternel, et vers mon Dieu j\'élevai mes cris: de son parvis Il entendit ma voix, et mes cris arrivés devant lui vinrent à ses oreilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Alors la terre oscilla et trembla, et les bases des montagnes furent émues, et elles s\'ébranlèrent, parce qu\'il était courroucé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Une fumée sortit de ses narines, et de sa bouche un feu dévorant; et Il fit jaillir des charbons ardents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Et Il inclina le ciel, et Il descendit; et l\'obscurité était sous ses pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Et Il était monté sur le Chérubin, et volait, et Il planait sur les ailes du vent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Il prit les ténèbres pour sa couverture, et autour de lui pour sa tente les noires vapeurs et les nuées épaisses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'De la splendeur qui le précède, sortirent les nuages, portant la grêle et les charbons de feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Et l\'Éternel tonna dans le ciel, et le Très-haut émit sa voix, avec la grêle et des charbons de feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Il lança ses flèches et Il les dissipa, et mille foudres, et Il les défit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Et l\'on vit paraître les vallées de la mer et les fondements du monde furent mis à nu au grondement de ta voix, Éternel, au souffle du vent de tes narines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Il tendit sa main d\'en haut, et me prit, et Il me retira des grandes eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Il me sauva de mes robustes ennemis, et de mes adversaires qui l\'emportaient sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Ils m\'attaquaient au jour du malheur; mais l\'Éternel fut un soutien pour moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Il me tira au large, Il me dégagea, parce qu\'il m\'était propice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'L\'Éternel me traita selon ma justice, et me rendit selon la pureté de mes mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Car je gardais les voies de l\'Éternel, et n\'étais point rebelle à mon Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Car j\'avais toutes ses lois sous les yeux, et je ne secouais point ses commandements;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'j\'étais sans reproche envers lui, et je prenais garde de me rendre coupable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Aussi l\'Éternel me rendit selon ma justice, selon la pureté de mes mains, dont Il était témoin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'A celui qui t\'aime, tu donnes ton amour, tu te montres juste pour l\'homme juste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'tu es pur envers celui qui est pur, et tu trahis celui qui est perfide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Car tu es en aide au peuple qui souffre, et tu humilies les yeux hautains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Oui, tu as fait luire ma lampe; l\'Éternel, mon Dieu, éclaira mes ténèbres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Avec toi j\'affrontai des bataillons, et avec mon Dieu je franchis des murailles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Les voies de Dieu ne sont point trompeuses, la parole de l\'Éternel est sans alliage; Il est un bouclier pour quiconque le réclame.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Car qui est-ce qui est Dieu, hors l\'Éternel? et qui est un rocher, sinon notre Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'ce Dieu, qui me donna la force pour ceinture, et rendit mes voies irréprochables?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Il assimila mes pieds à ceux de la biche, et Il m\'établit sur mes hauteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Il forma mes mains au combat, et mon bras sut bander l\'arc d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Tu me donnas le bouclier de ton secours, et ta droite me soutint, et ta clémence daigna m\'agrandir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Sous mes pieds tu donnas de l\'espace à mes pas, et mes talons ne furent point vacillants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Je poursuivis mes ennemis, et je les atteignis, et je ne revins pas qu\'ils ne fussent détruits;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'je les écrasai, et ils n\'ont pu se relever, ils tombèrent sous mes pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Tu me ceignis de force pour la bataille, et tu fis plier mes adversaires sous mes coups.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Tu me fis voir le dos de mes ennemis, et j\'anéantis ceux qui me haïssaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Ils crièrent au secours; il n\'y eut point de Sauveur; ils crièrent à l\'Éternel; Il ne leur répondit pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Je les mis en poudre, comme la poussière qui est au vent, et je les balayai comme la boue des rues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Tu me délivras des agressions des peuples, et tu me constituas chef des nations; des peuples à moi inconnus me furent asservis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'sur ma renommée ils se soumirent, les enfants de l\'étranger devinrent mes flatteurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'les enfants de l\'étranger succombèrent, et quittèrent alarmés leurs châteaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Vive l\'Éternel, et béni soit mon rocher! qu\'il soit exalté mon Dieu sauveur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'le Dieu qui m\'accorda la vengeance, et m\'assujettit les peuples!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'M\'ayant délivré de mes ennemis, tu m\'as fait triompher de mes adversaires, tu m\'as fait échapper à l\'homme violent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Aussi je veux te chanter parmi les peuples, Éternel, et célébrer ton nom,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'ô toi qui accordes un grand salut à ton Roi, et fais miséricorde à ton Oint, à David, et à sa race éternellement!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Au maître chantre. Cantique de David. Les Cieux racontent la gloire de Dieu, et le firmament proclame l\'œuvre de ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Le jour en transmet au jour le témoignage, et la nuit à la nuit en donne connaissance:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'ce n\'est pas un discours, ce n\'est pas un langage, dont la voix ne soit pas entendue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Sur toute la terre leurs accents se répandent, et leurs récits vont jusques au bout du monde, aux lieux où est dressée une tente au soleil;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'il sort, comme un époux de sa chambre nuptiale, il se réjouit, comme un héros de courir dans la lice;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'il part de l\'extrémité du ciel, et sa carrière s\'achève à ses extrémités: rien ne se dérobe à ses feux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'La loi de l\'Éternel est parfaite, elle restaure l\'âme; le témoignage de l\'Éternel est sûr, il rend sage le simple;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'les ordres de l\'Éternel sont droits, ils réjouissent le cœur; le commandement de l\'Éternel est pur, il éclaire les yeux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'la crainte de l\'Éternel est pure, elle subsiste à jamais; les préceptes de l\'Éternel sont vrais, ils sont tous justes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'ils ont plus de prix que l\'or, que beaucoup d\'or fin, plus de douceur que le miel, que le suc des rayons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Ton serviteur aussi en fut éclairé; à les garder il y a un grand gain...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Qui est-ce qui aperçoit [toutes] ses erreurs? Absous-moi de celles que j\'ignore!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Des orgueilleux aussi préserve ton serviteur! Qu\'ils ne prennent pas l\'empire sur moi! alors je serai sans reproche, et exempt d\'un grand péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Agrée les paroles de ma bouche, et accueille la méditation de mon cœur, ô Éternel, mon rocher, et mon libérateur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Au maître chantre. Cantique de David. Que Dieu t\'exauce au jour de la détresse, et que le nom du Dieu de Jacob te protège!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Que du Sanctuaire Il t\'envoie du secours, et que de Sion Il te prête son appui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Qu\'il se souvienne de toutes tes offrandes, et qu\'il accepte comme grasses les victimes! (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Qu\'il te donne ce que ton cœur désire, et qu\'il accomplisse tous tes desseins!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Nous chanterons ton salut, et au nom de notre Dieu nous agiterons le drapeau, si l\'Éternel accomplit tous tes souhaits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Or je sais que l\'Éternel est en aide à son Oint, qu\'il l\'exaucera du ciel de sa sainteté, par les exploits secourables de sa droite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Ceux-ci font gloire de leurs chars, ceux-là de leur cavalerie; mais nous, c\'est du nom de l\'Éternel notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Pour eux, ils plient et tombent; mais nous, nous restons droits, et demeurons debout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Éternel, sauve le Roi! Qu\'il nous exauce, lorsque nous L\'invoquons!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Au maître chantre. Cantique de David. Éternel, ta puissance donne au Roi de la joie, et comme ton secours le transporte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Tu as satisfait au désir de son cœur, et tu n\'as point rebuté la prière de ses lèvres. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Tu lui as présenté des biens excellents, et tu as mis sur sa tête un diadème d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Il te demandait la vie; tu la lui as donnée, une vie longue, permanente, éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Sa gloire est grande, grâce à ton secours, et tu lui accordes splendeur et majesté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'car tu le rends béni éternellement, tu le réjouis du bonheur de ta présence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Car le Roi se confie en l\'Éternel, et, par la faveur du Très-haut, il n\'est point ébranlé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Ta main saura trouver tous tes ennemis, et ta droite trouvera ceux qui te sont hostiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Tu les rendras pareils à une fournaise ardente, dès que tu te montreras; l\'Éternel dans son courroux les détruira, et ils seront consumés par le feu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'de la terre tu extermineras leur fruit, et leur race, d\'entre les fils des hommes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'parce qu\'ils ourdirent contre toi les trames de la malice, et formèrent des complots: ils seront impuissants;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'car tu leur feras prendre la fuite, et tu dirigeras ton arc contre leurs faces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Lève-toi, Éternel, avec ta puissance! Nous voulons chanter et célébrer tes hauts faits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Au maître chantre. Sur « Biche de l\'aurore ». Cantique de David. Mon Dieu! mon Dieu! pourquoi m\'as-tu abandonné, te tenant à l\'écart pour ne point m\'être en aide, et ne point ouïr quand je crie à rugir?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Mon Dieu! le jour, j\'appelle, et tu ne réponds pas; et la nuit, et je n\'obtiens pas de repos.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Cependant, tu es le Saint, les louanges d\'Israël environnent ton trône,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'En toi nos pères mirent leur confiance, mirent leur confiance, et tu les délivras;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'ils élevèrent leurs cris vers toi, et ils échappèrent; ils se confièrent en toi, et ne furent point confondus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Mais moi, je suis un ver, et non plus un homme, l\'opprobre des hommes, et le rebut du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Je suis la dérision de tous ceux qui me voient; ils grimacent de leurs lèvres, et hochent la tête, [disant:]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, '« Il s\'en remet à l\'Éternel; qu\'il le sauve! qu\'il le délivre, puisqu\'il lui est propice! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Oui, tu m\'as tiré du sein de ma mère, tu me donnais la sécurité auprès de sa mamelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'je me reposai sur toi dès ma naissance, et dès le sein de ma mère tu as été mon Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Ne sois pas loin de moi! car l\'angoisse est proche, car je suis sans secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Des taureaux puissants m\'environnent, les farouches troupeaux de Basan me cernent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'ils ouvrent leurs gueules contre moi, ainsi que des lions dévorants, rugissants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Comme les eaux je m\'écoule, et tous mes os se séparent; mon cœur, comme de la cire, fond dans ma poitrine;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'ma vigueur, comme un têt, s\'est séchée, et ma langue s\'attache à mon palais, et tu me couches dans la poussière de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Car des chiens m\'environnent, la bande des méchants m\'enveloppe, {[}s\'acharne] comme le lion, à mes mains et à mes pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Je compterais tous mes os; et eux, ils regardent et repaissent leurs yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Ils se partagent mes vêtements, et ils tirent au sort mon manteau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Mais, toi, Éternel, ne t\'éloigne pas! toi, qui es ma force, accours à mon aide!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Arrache à l\'épée mon âme, et aux chiens l\'unique bien qui me reste!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Tire-moi de la gueule du lion, et contre les cornes des buffles garantis-moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Alors je redirai ton nom à mes frères, et je te louerai au sein de l\'assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Vous qui craignez l\'Éternel, louez-le! Vous tous, race de Jacob, glorifiez-le, et tremblez devant lui, vous tous, race d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Car Il ne rebuta point, ne dédaigna point la misère du misérable, et Il ne lui cacha point sa face, et Il écouta les cris qu\'il élevait vers Lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Tu seras chanté par moi dans la grande assemblée; j\'accomplirai mes vœux devant ceux qui te craignent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Les affligés prendront part au festin, et seront rassasiés, et ceux qui cherchent l\'Éternel, chanteront ses louanges; votre cœur vivra éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Se rappelant ta mémoire, toutes les extrémités de la terre reviendront à toi, et toutes les tribus des peuples te rendront leur hommage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'car à l\'Éternel est l\'empire, et Il est le souverain des nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Tous les riches de la terre prendront part au festin, et adoreront, et l\'on verra s\'agenouiller tous ceux qui sont sur la pente du tombeau, et ceux qui ne peuvent soutenir leur vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'La race future Le servira, et l\'on parlera du Seigneur d\'âge en âge;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'il en viendra qui publieront sa justice, et raconteront à la race naissante qu\'il fut agissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Cantique de David. L\'Éternel est mon berger, je ne manque de rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Dans des pacages verts Il me fait reposer, Il me mène le long des eaux tranquilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Il restaure mon âme, Il me guide dans les ornières du salut, pour l\'amour de son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Quand je chemine dans une sombre vallée, je ne redoute aucun mal, car tu es avec moi; ta houlette et ton bâton, c\'est là ce qui me console.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Tu as dressé devant moi une table en face de mes ennemis, tu as oint d\'huile ma tête, et fait regorger ma coupe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Oui, le bonheur et la grâce me suivent tous les jours de ma vie, et la maison de l\'Éternel est mon séjour ordinaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Cantique de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'A l\'Éternel est la terre avec ce qu\'elle enserre, le monde avec ceux qui l\'habitent. Car sur des mers Il l\'a fondée, et sur des fleuves Il l\'a établie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Qui pourra monter à la montagne de l\'Éternel, et séjourner dans son lieu saint?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Celui qui a les mains innocentes et le cœur pur, qui ne porte pas ses désirs vers le mal, et ne jure pas pour tromper.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Il obtiendra bénédiction de l\'Éternel, et justice de son Dieu sauveur:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'c\'est la race de ceux qui viennent le trouver, et recherchent sa présence, la race de Jacob. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Portes, élevez vos têtes, exhaussez-vous, Portes éternelles, pour l\'entrée du Roi de gloire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, '« Qui est le Roi de gloire? » C\'est l\'Éternel, le fort et le puissant, l\'Éternel, puissant dans le combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Portes, élevez vos têtes, élevez-les, Portes éternelles, pour l\'entrée du Roi de gloire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, '« Qui est-il le Roi de gloire? » C\'est l\'Éternel des armées, C\'est lui qui est le Roi de gloire. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'De David. Vers toi, ô Éternel, j\'élève mon âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Mon Dieu, en toi je me confie: que je ne sois pas confondu! que je ne donne pas de la joie à mes ennemis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Quiconque espère en toi, n\'est point confondu; la confusion est pour ceux qui trahissent sans cause.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Éternel, indique-moi tes voies, enseigne-moi quels sont tes sentiers!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'guide mes pas dans ta vérité, et instruis-moi! car tu es mon Dieu sauveur, c\'est en toi que je mets toujours mon espoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Souviens-toi de tes compassions, Éternel, et de ta bonté, car elle remonte à l\'éternité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Oublie les péchés de mon jeune âge, et mes rebellions! En ta grâce souviens-toi de moi, au nom de ta bonté, Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'L\'Éternel est bon et équitable: aussi montre-t-Il aux pécheurs la voie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'faisant marcher les pauvres dans sa justice, et enseignant aux pauvres sa voie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Toutes les voies de l\'Éternel sont grâce et fidélité pour ceux qui gardent son alliance et ses lois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Pour l\'amour de ton nom, Éternel, tu pardonneras ma faute, car elle est grande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'A l\'homme qui craint l\'Éternel, Il montre la voie qu\'il doit choisir:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'son âme reposera au sein du bonheur, et sa postérité possédera le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'L\'Éternel se communique à ceux qui le craignent, Il leur donne son alliance pour les instruire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Mes yeux sont toujours fixés sur l\'Éternel; car Il dégagera mes pieds du filet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Tourne tes regards vers moi, Éternel, et prends pitié de moi! car je suis dans l\'abandon et dans la misère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Les angoisses m\'ont ouvert le cœur; délivre-moi donc de mes perplexités!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Vois ma misère et ma peine, et pardonne tous mes péchés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Vois le nombre de mes ennemis, et la haine violente qui les anime!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Garde mon âme, et sauve-moi! que je ne sois pas confondu! car j\'ai recours à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Que l\'intégrité et la droiture me soient un appui! car je mets en toi mon espoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'O Dieu, délivre Israël de toutes ses détresses!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'De David. Fais-moi justice, Éternel! car je vis innocent, et ma confiance au Seigneur n\'est jamais vacillante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Sonde-moi, Éternel, et me mets à l\'épreuve, passe par le creuset mes reins et mon cœur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Car ta grâce est présente à mes yeux, et je suis le chemin de ta vérité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'je ne m\'assieds point près des amis du mensonge, et je ne hante point les hommes cachés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Je hais la société des méchants, et je ne prends point place à côté des impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Je lave mes mains dans l\'innocence, et je fais, Seigneur, le tour de ton autel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'pour éclater en actions de grâces, et raconter tous tes miracles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Éternel, j\'aime le séjour de ta maison, et le lieu où réside ta gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'N\'emporte pas mon âme avec les pécheurs, ni ma vie avec les hommes de sang,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'qui portent le crime dans leurs mains, et ont leur droite remplie de présents!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Pour moi, je persévère dans mon intégrité: sauve-moi et prends pitié de moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Mon pied se tient au droit sentier: dans les assemblées je louerai l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'De David. L\'Éternel est ma lumière et mon salut; de qui aurais-je peur? L\'Éternel est le rempart de ma vie; devant qui tremblerais-je?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Quand des méchants contre moi s\'avancent acharnés, mes ennemis et mes adversaires, ils trébuchent et tombent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Qu\'une armée vienne camper contre moi, mon cœur est sans alarmes; qu\'une guerre s\'élève contre moi, alors même je suis plein d\'assurance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Il est une chose que je demande à l\'Éternel, et que je voudrais obtenir, c\'est d\'habiter la maison de l\'Éternel toute ma vie, pour contempler la majesté de l\'Éternel, et jouir de la vue de ses parvis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Car Il me cache dans sa loge au mauvais jour, et Il me donne asile sous l\'abri de sa tente, et Il m\'élève jusques sur un rocher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Aussi désormais ma tête dominera les ennemis qui me cernent, et j\'offrirai des victimes dans son tabernacle, au son de la trompette, et je louerai, et je chanterai l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Éternel, entends ma voix, je t\'invoque! Sois-moi propice et m\'exauce!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Mon cœur te rappelle ta parole: « Cherchez ma face! » Aussi, Éternel, je cherche ta face.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Ne me cache pas ta face! Dans la colère ne repousse pas ton serviteur! Tu es mon secours! Ne me laisse pas, ne m\'abandonne pas, mon Dieu sauveur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Car mon père et ma mère m\'abandonneraient, que l\'Éternel me recueillerait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Éternel, montre-moi ta voie, et conduis-moi dans le droit sentier, à cause de mes ennemis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Ne me livre pas à la merci de mes adversaires! car il s\'élève contre moi des témoins menteurs, et des hommes qui respirent la violence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Ah! si je n\'avais pas cru voir la bonté de l\'Éternel sur la terre des vivants! ...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Espère dans l\'Éternel! Courage! que ton cœur soit ferme, et espère dans l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'De David. Éternel, je t\'invoque! Mon rocher! ne sois point sourd à mes cris, de peur que, si pour moi tu ne romps le silence, je ne ressemble à l\'homme descendu au tombeau!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Ecoute ma voix suppliante, car je t\'implore, et je tends mes mains vers le sanctuaire de ton saint lieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Ne m\'emporte pas avec les impies, et avec ceux qui font le mal, qui parlent de paix à leur prochain, en ayant la malice dans le cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Donne-leur le salaire dû à leurs œuvres et à la méchanceté de leurs actions; rends-leur selon l\'ouvrage de leurs mains, en retour fais-leur ce qu\'ils ont fait!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Car ils ne prennent point garde aux actes de l\'Éternel, ni à l\'œuvre de ses mains: qu\'il les détruise, et ne les relève pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Béni soit l\'Éternel, car Il écoute ma voix suppliante!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'L\'Éternel est ma force et mon bouclier. En lui mon cœur se confie; et je suis secouru, et mon cœur se réjouit, et par mes chants je veux le célébrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'L\'Éternel est le soutien de son peuple, et le rempart et le secours de son Oint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Sauve ton peuple, et bénis ton héritage; sois son pasteur, et le maintiens à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Cantique de David. Fils de Dieu, rendez à l\'Éternel, rendez à l\'Éternel l\'honneur et la gloire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Rendez à l\'Éternel l\'honneur dû à son nom! Adorez l\'Éternel avec une pompe sainte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'La voix de l\'Éternel retentit sur les eaux, le Dieu glorieux fait gronder le tonnerre; on entend l\'Éternel sur les grandes eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'La voix de l\'Éternel est puissante, la voix de l\'Éternel est majestueuse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'la voix de l\'Éternel brise les cèdres, l\'Éternel brise les cèdres du Liban,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'et Il les fait bondir, comme les jeunes taureaux, et le Liban et le Sirion, comme les buffles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'La voix de l\'Éternel darde des flammes de feu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'la voix de l\'Éternel ébranle le désert, l\'Éternel ébranle le désert de Kadès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'La voix de l\'Éternel fait avorter les biches, elle dépouille les forêts; et dans Son palais tout s\'écrie: Gloire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'L\'Éternel sur son trône présidait au déluge, et sur son trône l\'Éternel régnera à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'L\'Éternel donnera la force à son peuple; l\'Éternel bénira son peuple de la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Cantique de David sur l\'hymne de la dédicace de la maison. Je t\'exalte, Éternel, car tu m\'as délivré, refusant à mes ennemis la joie de ma perte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Éternel, mon Dieu! j\'ai crié à toi, et tu m\'as guéri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Éternel, tu as retiré mon âme des Enfers, et m\'as rendu la vie, entre ceux qui descendent au tombeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Chantez l\'Éternel, vous ses bien-aimés, et louez son saint nom!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Car il est un instant pour son courroux, mais toute la vie pour son amour: le soir, la tristesse est notre hôte, et au matin, c\'est l\'allégresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Et moi, je disais dans ma sécurité: A jamais je suis inébranlable!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Éternel, en ta grâce tu avais affermi ma montagne; mais tu cachas ta face, et je fus éperdu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Éternel, je criai à toi, et je fis au Seigneur ma supplication:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, '« Qu\'as-tu à faire de mon sang et de mon trépas? La poudre peut-elle te louer, et dire ta fidélité?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Ecoute, Éternel, et prends pitié de moi! Éternel, sois-moi secourable! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Et tu changeas mon deuil en allégresse, tu délias mon cilice, et me donnas la joie pour ceinture,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'afin que mon cœur te loue, et ne reste point muet. Éternel, mon Dieu, je veux te louer à jamais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Au maître chantre. Cantique de David. Éternel, auprès de toi je me réfugie; que je ne sois jamais confondu! Par ta justice, délivre-moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Penche vers moi ton oreille! hâte-toi! sauve-moi! Sois pour moi un rocher, un asile, une citadelle pour me sauver!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Car tu es mon rocher et ma citadelle, et, pour l\'amour de ton nom, tu me guideras et tu me conduiras,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'tu me tireras des rets cachés par eux sous mes pas, car tu es mon soutien!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Je confie à tes mains la garde de ma vie; tu me délivreras, Dieu fidèle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Je hais les adorateurs des vaines idoles, et c\'est dans l\'Éternel que je mets mon espoir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Je serai réjoui et transporté de ta grâce; de ce que tu auras pris garde à ma misère, et fait attention aux angoisses de mon âme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'ne me livrant pas aux mains de l\'ennemi, mais ouvrant à mes pieds une voie spacieuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Éternel, aie pitié de moi! car je suis angoissé, le chagrin ronge mes yeux, mon âme et mon sein.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Car ma vie se consume dans la douleur, et mes années dans les soupirs; ma force succombe à ma peine, et mes os sont minés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'A cause de tous mes ennemis je suis un opprobre, le grand opprobre même de mes voisins, et la terreur de mes amis; ceux qui me voient dans la rue, me fuient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Je suis oublié comme un mort, banni de la pensée, je suis comme un vase mis au rebut;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'car j\'entends les sourds propos de plusieurs, de toute part l\'alarme me vient, quand ensemble ils se concertent contre moi; ils complotent de m\'ôter la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Mais en toi je me confie, Éternel! Je dis: Tu es mon Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Mes instants sont en ta main; tire-moi de la main de mes ennemis et de mes oppresseurs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Fais luire ta face sur ton serviteur! Sauve-moi dans ta clémence!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Éternel, que je ne sois pas confondu, car je t\'invoque! Confonds les impies! que, réduits au silence, ils deviennent la proie des Enfers!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Rends muettes les lèvres menteuses, qui tiennent contre le juste des discours violents, avec orgueil et mépris!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Quelle est grande la bonté que tu gardes à tes saints, que tu témoignes à ceux qui se confient en toi, à la face des hommes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Tu les protèges de l\'abri de ta face contre les complots des hommes; tu les dérobes dans ta loge aux attaques de la langue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Béni soit l\'Éternel, de ce qu\'il signala sa bonté envers moi, et me mit comme dans une ville forte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Je disais dans mes alarmes: Je suis banni de ta présence. Mais tu écoutas ma voix suppliante, quand je t\'implorai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Aimez l\'Éternel, vous tous ses saints! L\'Éternel garde les fidèles, et paie à l\'orgueilleux un abondant salaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Prenez courage, et que votre cœur s\'assure, vous tous qui espérez dans l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Hymne de David. O bonheur de celui dont la faute est pardonnée, et le péché remis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'O bonheur de l\'homme à qui l\'Éternel n\'impute point le crime, et dont le cœur est sans hypocrisie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Tant que je fus muet, mes os se consumaient par mes soupirs de tout le jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Car le jour et la nuit j\'étais sous le poids de ta main, la sève de ma vie séchait, comme aux feux de l\'été. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Je t\'avouai mon péché, et ne cachai point mon crime; je dis: Je veux à l\'Éternel confesser mon forfait! et tu pardonnas le crime de mon péché. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Aussi, que tout fidèle te prie dans le temps où l\'on te trouve! Seul, au débordement des grandes eaux, il n\'en sera pas atteint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Tu es mon asile, tu me gardes contre l\'angoisse, et tu m\'entoures de chants de délivrance. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Je veux t\'instruire et te montrer la voie qu\'il te faut suivre; je veux t\'avertir, fixant mes yeux sur toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Ne soyez pas comme le cheval et le mulet stupide, qui, sans la bride et le mors du frein qui les dompte, ne t\'approcheraient pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Il y a beaucoup de douleurs pour l\'impie; mais celui qui dans l\'Éternel met sa confiance, est environné de sa grâce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Justes, que l\'Éternel excite votre joie et vos transports, et chantez, vous tous dont le cœur est droit!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Justes, chantez l\'Éternel! la louange sied aux hommes droits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Célébrez l\'Éternel avec la harpe, touchez pour lui le luth à dix cordes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Chantez-lui un cantique nouveau, joignez vos plus beaux accords au son des trompettes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Car la parole de l\'Éternel est juste, et toute son action fidèle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Il aime le droit et la justice; de la grâce de l\'Éternel la terre est remplie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Par la parole de l\'Éternel les Cieux ont été faits, et par le souffle de sa bouche toute leur armée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Il rassemble en une masse les eaux de la mer, et dépose ses flots dans des réservoirs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Que toute la terre craigne l\'Éternel! Que tous les habitants du monde le révèrent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Car Il parle, et la chose est, Il commande, et elle existe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'L\'Éternel rompt les conseils des nations, Il déjoue les pensées des peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Les décrets de l\'Éternel subsistent à jamais, et les pensées de son cœur demeurent dans tous les âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Heureuse la nation dont l\'Éternel est le Dieu, le peuple qu\'il choisit pour son héritage!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Des Cieux l\'Éternel regarde, Il voit tous les enfants des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'De sa résidence Il observe tous les habitants de la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'lui qui, en même temps, forme le cœur de tous, et qui est attentif à toutes leurs œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Nul roi ne triomphe par la grandeur de sa puissance, nul héros n\'est sauvé par la grandeur de sa force;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'le cheval n\'est rien pour la victoire, et par la grandeur de ses moyens il ne fait pas échapper.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Voici, l\'Éternel a l\'œil sur ses fidèles qui espèrent dans sa grâce,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'pour arracher leur âme à la mort, et les faire vivre durant la famine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Notre âme espère dans l\'Éternel, Il est notre aide et notre bouclier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Car Il ravit notre cœur, parce qu\'en son saint nom nous avons confiance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Que ta grâce, Éternel, soit sur nous, comme nous l\'attendons de toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'De David, lorsqu\'il se contrefit devant Abimélech, et qu\'ayant été chassé par lui, il s\'enfuit. Je bénirai l\'Éternel en tout temps, toujours sa louange sera dans ma bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Que de l\'Éternel mon âme se glorifie! Que les malheureux l\'entendent et se réjouissent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Magnifiez l\'Éternel avec moi! Exaltons son nom tous ensemble!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Je cherchai l\'Éternel, et Il me répondit, et de toutes mes terreurs Il me délivra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Qui regarde vers lui en est rendu serein, et la honte ne couvre pas son front.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Ce malheureux a prié, et l\'Éternel a exaucé, et de toutes ses angoisses Il l\'a délivré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'L\'ange de l\'Etemel campe près de ceux qui Le craignent, et les sauve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Sentez et voyez comme l\'Éternel est bon! Heureux l\'homme qui se confie en lui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Craignez l\'Éternel, vous ses saints, car rien ne manque à ceux qui le craignent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Les lions connaissent la disette et la faim; mais ceux qui cherchent l\'Éternel, n\'ont disette d\'aucun bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Venez, mes fils! écoutez-moi! Dans la crainte de l\'Éternel je veux vous instruire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Qui que tu sois qui aimes la vie, qui souhaites des années pour goûter le bonheur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'garde ta langue de la méchanceté, et tes lèvres des discours trompeurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'fuis le mal, et fais le bien, cherche la paix, et la poursuis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Les yeux de l\'Éternel sont fixés sur les justes, et ses oreilles ouvertes à leurs cris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'L\'Éternel se retourne contre le méchant, pour extirper de la terre sa mémoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Ils crient, et l\'Éternel exauce, et de toutes leurs angoisses Il les délivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'L\'Éternel est près des cœurs brisés, et Il est secourable aux esprits froissés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Les maux du juste sont nombreux; mais de tous l\'Éternel le délivre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Il garde tous ses os, pas un d\'eux n\'est brisé. L\'adversité tue l\'impie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'et les ennemis du juste portent leur peine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'L\'Éternel rachète la vie de ses serviteurs, et tous ceux qui mettent en lui leur confiance, ne portent nulle peine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'De David. Sois l\'adversaire, ô Éternel, de mes adversaires! Combats ceux qui me combattent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Saisis le bouclier et la rondache, et lève-toi pour m\'assister!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Tire ta lance et ta hache contre mes persécuteurs! Crie-moi: Je suis ton aide!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Que la honte et l\'opprobre couvrent ceux qui demandent ma vie! qu\'ils reculent confondus ceux qui méditent ma ruine!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Qu\'ils soient comme la balle au vent, chassés par l\'ange de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Que leur route soit sombre et glissante, et que l\'ange de l\'Éternel les poursuive!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Car sans cause ils ont caché la fosse et le filet sous mes pas, sans cause ils ont miné pour m\'ôter la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Que la ruine fonde sur eux imprévue! qu\'ils soient pris dans le filet qu\'ils ont tendu! que pour y périr ils y tombent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Alors mon âme sera ravie de l\'Éternel, et se réjouira de son secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Tous mes os diront: Éternel! qui, comme toi, sauve le malheureux de plus forts que lui, le malheureux et le pauvre de ses spoliateurs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Des témoins iniques se lèvent; pour ce que j\'ignore, ils me prennent à partie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'On me rend le mal pour le bien, je suis abandonné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Mais moi, dans leurs maladies, je pris le cilice, je me macérai par des jeûnes, et je priai, la tête penchée sur la poitrine;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'à ma démarche on eût dit que j\'avais perdu mon frère, mon ami; comme en deuil d\'une mère, triste j\'étais courbé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Mais ma chute les réjouit; ils se liguent, ils se liguent contre moi, médisant, et j\'ignore tout; ils me déchirent, et ne se taisent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Avec les profanes bouffons des festins, ils grincent contre moi les dents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Seigneur, jusques à quand seras-tu spectateur? Délivre ma vie de leur fléau, et mon âme des lions!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Je te rendrai grâces dans la grande assemblée, et je te louerai au sein d\'un peuple nombreux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Ne permets pas que mes perfides ennemis triomphent à ma vue, et que, dans leur haine gratuite, ils clignent les yeux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Car ils ne parlent pas de paix, et contre les débonnaires du pays ils méditent l\'astuce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Ils ouvrent contre moi leur bouche, et disent: « Ah! ah! nos yeux voient. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Tu vois aussi, Éternel! ne te tais pas! Seigneur, ne t\'éloigne pas de moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Lève-toi, réveille-toi, pour me faire justice, mon Seigneur, mon Dieu, pour défendre ma cause!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Fais-moi droit, selon ta justice, Éternel, mon Dieu, et que je ne sois pas un triomphe pour eux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Qu\'ils ne disent pas en leur cœur: « Bien! c\'étaient nos vœux! Qu\'ils ne disent pas: « Nous l\'avons perdu! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Fais rougir et confonds tous ceux que réjouissent mes maux! Couvre de honte et d\'ignominie mes superbes adversaires!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Alors ils chanteront et seront ravis ceux qui aiment ma juste cause; ils diront incessamment: « Grand est l\'Éternel, qui se plaît au bien de son serviteur! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Et ma langue dira ta justice, et te louera tous les jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Au maître chantre. Chant du serviteur de l\'Éternel, de David. L\'impie a le péché au dedans de son cœur, la crainte de l\'Éternel n\'est pas devant ses yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Par sa manière de voir il se flatte lui-même, pour consommer son crime, pour haïr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Les paroles de sa bouche sont vaines et trompeuses, il a cessé d\'être sage et de faire le bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Il pense au mal sur son lit, il pratique une voie qui n\'est pas bonne, il n\'a point le mal en aversion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Éternel, ta grâce atteint jusques aux Cieux, ta fidélité jusques aux nues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Ta justice est pareille aux montagnes de Dieu, et tes jugements sont pareils à l\'immense mer. Éternel, tu es secourable aux hommes et aux bêtes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Que ta grâce est précieuse, ô Dieu! et les fils des hommes se réfugient à l\'ombre de tes ailes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'ils se repaissent de l\'abondance de ta maison, et tu les abreuves au fleuve de tes délices.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Car auprès de toi est la source de la vie, et à ta lumière nous voyons la lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Conserve ta grâce à ceux qui te connaissent, et ta justice à ceux qui ont le cœur droit!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Que le pied de l\'orgueil ne me foule point, et que la main des impies ne me mette pas en fuite!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Déjà les méchants tombent, ils sont terrassés et incapables de se relever.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'De David. Ne t\'irrite point à la vue des méchants, et n\'envie point ceux qui font le mal!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Car, comme l\'herbe, ils sont bientôt tranchés, et, comme le vert gazon, ils sont vite flétris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Aie confiance en l\'Éternel et fais le bien; demeure dans le pays et cultive la piété,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'et trouve en Dieu tes délices, et Il t\'accordera ce que ton cœur demande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Décharge-toi sur l\'Éternel du soin de ton sort, et te confie en lui! Il saura bien agir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'et Il fera paraître ton droit comme une lumière, et ta justice comme la clarté de midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'En silence attends l\'Éternel, et compte sur lui. Ne t\'irrite point du sort de l\'heureux, de l\'homme qui vient à bout de ses méchants desseins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Calme ta colère, renonce à ton courroux; ne t\'irrite point; ce ne serait que pour mal faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Car les méchants seront exterminés, et ceux qui espèrent dans l\'Éternel, posséderont le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Un instant encore, et le méchant n\'est plus; tu remarques sa place, il n\'est plus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'et les opprimés sont maîtres du pays, et jouissent d\'une abondante paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Le méchant complote contre le juste, et grince contre lui les dents:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'le Seigneur se rit de lui, car Il voit venir son jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Les méchants ont tiré l\'épée et bandé leur arc, pour faire tomber l\'affligé et le pauvre, pour immoler les hommes droits;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'leur épée perce leur propre cœur, et leur arc est brisé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Mieux vaut le peu du juste que l\'abondance de mille impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Car les bras des impies seront brisés, mais l\'Éternel soutient les justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'L\'Éternel a connaissance des jours des justes, et leur héritage leur est à jamais assuré;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'ils ne seront point confus dans le temps malheureux, et aux jours de famine ils sont rassasiés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Car les méchants périssent, et les ennemis de l\'Éternel, comme l\'éclat des prairies, s\'évanouissent, ils s\'évanouissent comme une fumée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'L\'impie emprunte, et il ne rend pas; mais le juste est bienfaisant, et il donne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'car ceux que bénit l\'Éternel, possèdent le pays, et ceux qu\'il maudit, sont exterminés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'L\'Éternel affermit les pas du juste, et Il prend plaisir à sa voie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 's\'il tombe, il n\'est point renversé, car l\'Éternel le soutient par la main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Je fus jeune, et je suis un vieillard, mais jamais je n\'ai vu le juste abandonné, ni sa postérité mendiant son pain;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'toujours il donne, toujours il prête, et la bénédiction repose sur sa postérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Fuis le mal, et fais le bien, et tu demeureras tranquille à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Car l\'Éternel aime la justice, et ne délaisse pas ses saints; toujours ils sont gardés, mais la race des impies est exterminée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Les justes posséderont le pays, et l\'habiteront à perpétuité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'La bouche du juste exprime des pensées sages, et sa parole est le langage de la justice;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'il a dans le cœur la loi de son Dieu, sa marche n\'est point incertaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'L\'impie guette le juste, il cherche à lui donner la mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'l\'Éternel ne le laisse pas entre ses mains, et ne le condamne point, quand Il le juge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Espère dans l\'Éternel, et tiens-toi dans ses voies, et Il te relèvera pour te faire héritier du pays. Tu seras témoin de la ruine des impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'J\'ai vu l\'impie formidable, se déployant comme l\'arbre indigène qui verdit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'il a disparu, et voici, il n\'était plus; je l\'ai cherché, et il ne s\'est plus trouvé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Observe le juste et considère l\'homme droit; car le pacifique a une postérité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'mais les méchants périssent en entier, et la race des impies est extirpée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Et le secours arrive aux justes de par l\'Éternel; Il est leur rempart au temps de la détresse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'l\'Éternel les assiste et les sauve, Il les sauve des impies, et les aide, parce qu\'ils se confient en lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Cantique de David. Pour souvenir. Éternel, en ton courroux ne me châtie pas! et en ta colère ne me punis pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Car tes flèches sont tombées sur moi, et sur moi tu as fait main basse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Ta fureur n\'a rien épargné en mon corps, et mon péché a enlevé toute santé à mes os.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Car mes misères s\'élèvent plus haut que ma tête, comme un lourd fardeau, par leur poids elles m\'accablent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Mes plaies sont fétides et purulentes, par l\'effet de ma folie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Je suis courbé, affaissé au dernier degré; incessamment je vais menant deuil;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'car un feu remplit mes entrailles, et il n\'y a plus de santé dans mon corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Je suis tout défaillant, tout brisé, un rugissement sort de mon cœur en tourmente...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Seigneur, tu connais tous mes désirs, et mes soupirs ne te sont point cachés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'mon cœur palpite, ma force m\'abandonne, et mes yeux mêmes me refusent la vue du jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Mes amis et mes frères s\'arrêtent à l\'aspect de ma plaie, et mes proches se tiennent à distance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Ceux qui en veulent à ma vie, tendent leurs pièges, et ceux qui cherchent ma perte, parlent de ruine, et tout le jour ils songent à des ruses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Mais moi, tel qu\'un sourd, je n\'entends pas, et, tel qu\'un muet, je n\'ouvre pas la bouche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'je suis comme un homme privé de l\'ouïe, et dans la bouche duquel il n\'y a point de réplique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Car c\'est en toi, Éternel, que j\'espère; tu m\'exauceras, Seigneur, mon Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Car je dis: Ne permets pas que j\'excite leur joie! Dès que mon pied bronche, je vois leur triomphe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Car je suis toujours près de faillir, et mes regrets douloureux sont toujours là, devant moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'car je confesse mes manquements, et mon péché me rend inquiet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Cependant mes ennemis sont vivants et forts, ils sont en nombre ceux qui me haïssent sans cause.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Me rendant le mal pour le bien, ils me sont hostiles, parce que je cherche le bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Ne m\'abandonne pas, Éternel! Mon Dieu, ne t\'éloigne pas de moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Accours à mon aide, ô Dieu, mon Sauveur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Au maître chantre des Jéduthunites. Cantique de David. J\'avais dit: « Je veillerai sur mes voies, pour ne point pécher par la langue; j\'aurai soin de mettre un frein à ma bouche, tant que les impies seront en ma présence. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Je fus muet, silencieux, évitant même de parler du bonheur. Mais ma douleur s\'irritait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'mon cœur s\'enflammait dans mon sein, où mes pensées allumèrent un feu, et ma langue parla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Éternel, montre-moi le terme de ma vie, et quelle est la durée de mes jours! O! que je sache combien je suis fragile!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Voici, tu as donné à mes jours l\'espace d\'une palme, et ma durée est comme un néant devant toi; oui, tout homme a la consistance d\'un souffle. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Oui, comme une ombre le mortel se promène; oui, il s\'agite avec bruit pour ce qui passe; il amasse, et il ne sait qui recueillera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Et maintenant, que puis-je attendre, Seigneur? Mon espoir est en toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Sauve-moi de tous mes péchés, ne m\'expose pas aux outrages de l\'impie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Mais je me tais, je n\'ouvre pas la bouche, car c\'est toi qui agis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Eloigne de moi tes plaies! Je péris sous ta main irritée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Quand par des peines tu châties l\'homme d\'une faute, semblable à la teigne, tu détruis son bien le plus cher. Oui, tout mortel est un souffle. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Ecoute ma prière, Éternel, et prête l\'oreille à mes cris! Ne sois point sourd à mes larmes, car je suis un étranger chez toi, un hôte, comme tous mes pères!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Ne tiens plus tes yeux attachés sur moi, afin que je retrouve la sérénité, avant que je m\'en aille, et que je ne sois plus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Au maître chantre. Cantique de David. J\'attendis fermement l\'Éternel; et se penchant vers moi, Il écouta ma plainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Et Il me retira de l\'horreur de la fosse, de la fange du bourbier; et Il fit poser mon pied sur le roc, affermissant mes pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'et Il mit dans ma bouche un cantique nouveau, les louanges de notre Dieu. Témoins de ces choses, plusieurs craindront, et auront confiance dans l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Heureux l\'homme qui choisit l\'Éternel pour placer en lui sa confiance, et ne s\'adresse pas aux présomptueux, aux menteurs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Il est grand, Éternel, mon Dieu, le nombre des miracles et des décrets que tu fis pour nous; rien n\'est comparable à toi: je voudrais les raconter et les dire, il y en a trop pour les énumérer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Ce n\'est ni la victime, ni l\'offrande que tu aimes, (tu as ouvert mes oreilles à cette instruction) l\'holocauste et l\'expiation, ce n\'est pas ce que tu demandes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Aussi j\'ai dit: « Voici, je viens; c\'est ce que me prescrit le livre de la loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Faire ta volonté, mon Dieu, c\'est mon désir, et ta loi est dans mon cœur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Je proclame [ta] justice dans la grande assemblée; voici, je ne tiens point mes lèvres fermées: Éternel, tu le sais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Je ne cèle point ta justice au dedans de mon cœur; je dis ta fidélité et ton secours, je ne dissimule point ta grâce et ta fidélité à la grande assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Et toi, Éternel, ne retiens pas non plus ta miséricorde envers moi! Que ta grâce et ta fidélité me gardent toujours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Car je suis entouré de maux sans nombre; de mes péchés je reçois des atteintes, je ne puis les voir, ils sont plus nombreux que les cheveux de ma tête, et mon cœur m\'abandonne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'O Éternel, daigne me sauver! Éternel, accours à mon aide!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Qu\'ils soient tous ensemble couverts de honte et d\'affronts ceux qui attentent à ma vie, pour me la ravir! Qu\'ils reculent confondus ceux qui veulent mon malheur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Qu\'ils soient stupéfaits de leur propre ignominie ceux qui disent: Le voilà! Le voilà!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Ainsi tu feras le ravissement et la joie de tous ceux qui te cherchent; ils diront sans cesse: « Grand est l\'Éternel! » ceux qui désirent ton secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Je suis un pauvre et un indigent, mais le Seigneur pense à moi. Tu es mon aide et mon libérateur! Mon Dieu, ne tarde pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Au maître chantre. Cantique de David. Heureux celui qui s\'intéresse au pauvre! Au jour du malheur l\'Éternel le délivre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'l\'Éternel le garde et le conserve, et il jouira du bonheur sur la terre. Tu ne le livreras pas au caprice de ses ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'L\'Éternel le soutiendra sur le lit des souffrances; et toujours Tu fais prendre une tournure heureuse au mal qui l\'étend sur sa couche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Je dis: Éternel! prends pitié de moi! guéris-moi! car j\'ai péché contre toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Mes ennemis tiennent sur moi de méchants propos: « Quand mourra-t-il, et périra son nom? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'L\'un d\'eux vient-il me voir, son langage est faux; son cœur se fait provision de malice; il s\'en va, et il parle au dehors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Entre eux contre moi mes ennemis chuchotent; contre moi ils complotent ma perte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, '« Quelque crime le met à la gêne; [disent-ils] le voilà gisant, il ne se relèvera pas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Mon ami même, qui a ma confiance et mange mon pain, lève le talon contre moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Mais toi, Éternel, aie pitié de moi, et me relève, afin que je puisse leur payer leur salaire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Ce qui me prouvera que tu m\'aimes, c\'est que je n\'excite pas la joie de mon ennemi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Mais voici, tu me maintiens dans mon intégrité, et tu me placeras sous ton regard à jamais. \\csp{');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Béni soit l\'Éternel, Dieu d\'Israël, de l\'éternité à l\'éternité! Ainsi soit-il! ainsi soit-il!}');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Au maître chantre. Hymne des fils de Coré. Comme une biche languit après les courants d\'eau, ainsi mon âme languit après toi, ô Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Mon âme a soif de Dieu, du Dieu vivant. Quand viendrai-je, et paraîtrai-je en la présence de Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Mes larmes sont mon aliment le jour et la nuit, depuis que chaque jour on me dit: « Où est ton Dieu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Il m\'en souvient, et je laisse mon cœur s\'épancher: je m\'avançais avec la foule, conduisant le cortège à la maison de Dieu, au milieu des chants, des hymnes, d\'un concours solennel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Pourquoi t\'abats-tu, mon âme, et gémis-tu au dedans de moi? Espère en Dieu, je le louerai encore, lui, mon Sauveur et mon Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Mon âme est abattue au dedans de moi: aussi pensé-je à toi des plages du Jourdain, des montagnes de l\'Hermon, et du mont de Mitshar,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Une vague appelle une vague au grondement de tes cataractes; tous tes flots, toutes tes vagues passent sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Le jour, l\'Éternel me dispensait sa grâce, et la nuit, sa louange était dans ma bouche, et je priais le Dieu de ma vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, '[Aujourd\'hui] je dois dire à Dieu, mon rocher: Pourquoi m\'oublies-tu? Pourquoi vais-je menant deuil sous l\'oppression de l\'ennemi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Mes os se brisent, quand mes ennemis m\'outragent, et me disent tous les jours: « Où est ton Dieu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Pourquoi t\'abats-tu, mon âme, et gémis-tu au dedans de moi? Espère en Dieu, je le louerai encore, lui, mon Sauveur et mon Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Fais-moi justice, ô Dieu, et soutiens ma querelle contre un peuple impitoyable! Sauve-moi de l\'homme fourbe et pervers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'car tu es mon Dieu tutélaire! Pourquoi me rejettes-tu? Pourquoi vais-je menant deuil sous l\'oppression de l\'ennemi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Envoie-moi ta lumière et ta vérité, afin qu\'elles me guident, et qu\'elles m\'amènent à ta montagne sainte et dans tes demeures,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'pour que je parvienne à l\'autel de Dieu, auprès d\'un Dieu qui excite les transports de ma joie, et que je te chante avec la harpe, ô Dieu, ô mon Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Pourquoi t\'abats-tu, mon âme, et gémis-tu au dedans de moi? Espère en Dieu, je le louerai encore, lui, mon Sauveur et mon Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Au maître chantre. Hymne des fils de Coré. O Dieu, nous avons ouï de nos oreilles, nos pères nous ont raconté les exploits que tu fis en leurs jours, aux jours d\'autrefois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'De ta main tu chassas les nations, pour les établir; tu détruisis les peuples, pour les multiplier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Car ce ne fut pas par leur épée qu\'ils conquirent le pays, ni leur bras qui les rendit vainqueurs, mais ta droite et ton bras, et la lumière de ta face; car tu leur fus propice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'O Dieu! tu es mon Roi! Ordonne la délivrance de Jacob!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Avec toi nous battons nos ennemis, par ton nom nous terrassons nos adversaires');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Car dans mon arc je ne me confie point, ce n\'est pas mon épée qui me délivre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'mais c\'est toi qui nous délivres de nos ennemis, et qui confonds ceux qui nous haïssent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'De Dieu nous faisons gloire en tout temps, et nous louons éternellement ton nom. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Cependant tu nous rejetas et nous couvris d\'opprobre, et tu ne marchas plus avec nos armées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'tu nous fis reculer devant nos ennemis, et ceux qui nous haïssent, emportèrent des dépouilles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'tu nous livras comme la brebis que l\'on mange, et parmi les nations tu nous disséminas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'tu vendis ton peuple à vil prix, et pour toi il n\'eut pas une grande valeur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'tu nous exposas aux affronts de nos voisins, aux railleries et aux insultes de nos alentours;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'tu nous fis passer en proverbe chez les nations, exciter des hochements de tête parmi les peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Toujours ma honte est devant mes yeux, et la confusion de ma face me couvre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'à la voix de celui qui m\'insulte et m\'outrage, à l\'aspect de l\'ennemi et de l\'homme hostile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Tout cela nous est arrivé, et pourtant nous ne t\'avions pas oublié, nous n\'avions pas violé ton alliance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'notre cœur ne s\'était point retiré de toi, et nos pas n\'avaient pas dévié de tes voies,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'pour que tu nous écrases dans le pays des chacals, et que tu nous enveloppes d\'une ombre de mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Si nous avions oublié le nom de notre Dieu, et tendu nos mains vers un dieu étranger, est-ce que Dieu ne le pénétrerait pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'lui qui connaît les secrets de nos cœurs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Mais non, pour toi nous sommes tués tous les jours, et regardés comme des brebis à égorger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Veille! pourquoi dors-tu, Seigneur? Réveille-toi! ne nous rejette pas à jamais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Pourquoi cacher ta face, oublier notre misère et notre oppression?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Car jusqu\'à la poussière notre âme est abattue, et notre corps à la terre est attaché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Lève-toi! à notre secours! et sauve-nous pour l\'amour de ta grâce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Au maître chantre. En schoschanim. Hymne des fils de Coré. Chant des amours. Il jaillit de mon cœur un propos excellent. Je dis: Mon œuvre est pour le Roi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Que ma langue soit le style d\'un écrivain rapide! En beauté tu surpasses les enfants des hommes, la grâce est répandue sur tes lèvres: aussi Dieu te bénit éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Guerrier, ceins à tes flancs ton épée, ta parure et ta gloire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'et ta gloire!... Monte sur ton char! triomphe pour la vérité, la bonté, la justice! et que ta droite te montre les exploits terribles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Tes flèches acérées (des peuples tomberont sous tes coups) iront au cœur des ennemis du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Ton trône, Dieu! est permanent, éternel, le sceptre de ton empire est un sceptre équitable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Tu aimes la justice, et tu hais l\'impiété: aussi, Dieu! ton Dieu par l\'onction de l\'huile d\'allégresse te distingua de tes pairs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'La myrrhe, et l\'aloès, et le laurier, parfument tes vêtements; des palais d\'ivoire le son des harpes vient te réjouir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Les filles des rois sont parmi tes bien-aimées; la Reine est à ta droite, parée d\'or d\'Ophir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Ecoute, ma fille, et considère et prête l\'oreille! Oublie ton peuple et la maison de ton père!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Le Roi désire ta beauté; puisqu\'il est ton Seigneur, rends-lui ton hommage!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Et la fille de Tyr, la plus riche des nations, par des offrandes briguera ta faveur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Dans toute sa splendeur, en face de l\'entrée, la fille royale est assise; sa robe est un brocart d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Sur des tapis diaprés elle est conduite au Roi; à sa suite, les vierges ses compagnes te sont amenées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'escortées de joie et d\'allégresse, elles entrent dans le palais du Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'A tes pères succéderont tes fils; tu les établiras princes par toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Je rappellerai ton nom d\'âge en âge: aussi les peuples te loueront toujours, à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Au maître chantre. Des fils de Coré. Chant avec voix de femmes. Dieu est pour nous un asile, un rempart, dans les maux on éprouve son puissant secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Aussi nous ne craignons point, quand la terre change de face, et que les monts oscillent au sein des mers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Que leurs ondes grondent, et écument, et que leur fier courroux ébranle les montagnes! (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Un fleuve avec ses ruisseaux égaie la cité de Dieu, sanctuaire des demeures du Très-haut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Dieu est dans son enceinte, elle est inébranlable; Dieu lui donne son secours dès l\'aube du matin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Les peuples sont en rumeur, les empires branlent: Il émet sa voix, et la terre est craintive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'L\'Éternel des armées est avec nous, le Dieu de Jacob nous est une citadelle. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Venez et contemplez les faits de l\'Éternel, comme Il a ravagé la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Faisant cesser les guerres jusqu\'au bout de la terre, Il a brisé les arcs, et fracassé les lances, et Il a brûlé au feu les chars de bataille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, '« Abstenez-vous! et sachez que je suis Dieu, qui domine les peuples, qui domine la terre! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'L\'Éternel des armées est avec nous, le Dieu de Jacob nous est une citadelle. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Au maître chantre. Des fils de Coré. Cantique. Vous tous les peuples, battez des mains! éclatez pour Dieu en acclamations!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Car l\'Éternel, le Très-haut, est digne de crainte, Il est le grand Roi de toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Il a rangé des peuples sous nos lois, et mis des nations sous nos pieds;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Il nous a choisi lui-même notre héritage, orgueil de Jacob qu\'il aime. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Dieu arrive avec des acclamations, et l\'Éternel s\'avance au son de la trompette.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Chantez l\'Éternel, chantez! Chantez à notre Roi, chantez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Car Dieu est Roi de toute la terre: chantez-lui des hymnes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Dieu règne sur les peuples; Dieu est assis sur son trône saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Les princes des peuples se réunissent au peuple du Dieu d\'Abraham; car les boucliers de la terre sont à Dieu, Il est souverainement élevé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Cantique des fils de Coré. L\'Éternel est grand et digne d\'être loué, dans la cité de notre Dieu, sur sa montagne sainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Délices de toute la terre, le mont de Sion s\'élève magnifique, sur ses flancs au Nord il porte la ville du grand Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Dieu pour ses palais s\'est montré un rempart.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Car voici, les rois se liguèrent: ensemble ils disparurent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Ils virent, et furent aussitôt éperdus, ils prirent l\'épouvante, et s\'enfuirent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'là même ils furent saisis du tremblement, des angoisses de l\'enfantement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'au souffle du vent d\'Orient, qui fracasse les navires de Tarsis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Ce qu\'on nous avait dit, nous l\'avons vu nous-mêmes dans la ville de l\'Éternel des armées, ville de notre Dieu; Dieu la maintient à jamais. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'O Dieu, nous pensons à ta grâce dans l\'enceinte de ton temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Que ta louange, ô Dieu, aussi bien que ton nom, retentisse jusqu\'aux bouts de la terre! De justice ta droite est remplie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'La montagne de Sion est dans la joie, et les filles de Juda dans l\'allégresse, à cause de tes jugements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Faites le tour de Sion et de son enceinte, comptez ses tours,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'examinez son fossé, faites la revue de ses palais, pour en parler à la race future!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Car ce Dieu est notre Dieu pour toujours, à jamais: Il nous conduira jusqu\'à la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Au maître chantre. Cantique des fils de Coré. Ecoutez ces choses, vous tous les peuples; prêtez l\'oreille, vous tous habitants du monde,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'et vous enfants des hommes, et vous fils des humains, tous ensemble, et le riche et le pauvre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Ma bouche exposera la sagesse, et mon cœur en méditant a trouvé la science:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'mon oreille en écoute les inspirations, et je vais au son du luth révéler ma pensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Que craindrais-je au jour du malheur, quand je suis enveloppé de la malice de ceux qui me tendent des embûches,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'qui se confient en leurs biens, et sont vains de leur grande richesse?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'L\'homme ne saurait racheter son frère, ni donner à Dieu une rançon pour lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Il en coûte trop pour racheter une vie, et jamais il n\'aura les moyens');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'de donner à quelqu\'un une vie éternelle, ni de lui épargner la vue du tombeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Non! il le verra! Les sages meurent, et avec eux le fou et le stupide périssent, et laissent leurs biens à d\'autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Leurs vœux sont d\'avoir des maisons éternelles, et des demeures qui durent aux siècles des siècles: leurs noms sont célèbres sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Mais l\'homme dans la splendeur n\'est pas permanent, il est assimilé aux animaux que l\'on égorge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Telle est la voie sur laquelle ils se fient; et ceux qui les suivent, approuvent leur langage. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Comme un troupeau ils sont chassés aux Enfers; la Mort devient leur berger, et les justes les foulent sous leurs pas; en un instant leur figure est la proie des Enfers, bannie du séjour qu\'on lui avait préparé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Cependant Dieu arrachera mon âme au pouvoir des Enfers, qui voudraient me saisir. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Ne crains point, quand un homme s\'enrichit, quand sa maison croît en splendeur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Car il n\'emporte pas tout en mourant, sa splendeur après lui ne descendra pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Que dans sa vie il se trouve heureux, qu\'on te vante du bien-être que tu sais te donner;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'il te faut rejoindre tes pères, qui jamais ne reverront la lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'L\'homme qui est dans la splendeur, et n\'a pas la sagesse, est assimilé aux animaux que l\'on égorge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Cantique d\'Asaph. Dieu, l\'Éternel Dieu parle, Il appelle la terre, du soleil levant au soleil couchant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'de Sion, perfection de beauté, Dieu apparaît resplendissant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'notre Dieu vient, mais non pas en silence; devant lui le feu dévore, et autour de lui il y a grande tempête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Il appelle les Cieux d\'en haut, et la terre, au jugement de son peuple:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, '« Rassemblez-moi mes bien-aimés, qui solennisèrent mon alliance par le sacrifice! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Que donc les Cieux proclament sa justice, car Dieu est celui qui va juger! (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, '« Ecoute, mon peuple, je vais parler! Israël, je vais te sommer! Je suis Dieu, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Je ne te reprends pas pour tes sacrifices, car tes holocaustes sont constamment devant moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Je n\'irai pas prendre des taureaux dans ta maison, ni des béliers dans tes bergeries.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Car à moi sont toutes les bêtes des forêts, les animaux des montagnes par milliers;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'je connais tous les oiseaux des montagnes, et les bêtes des champs sont en mon pouvoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Si j\'avais faim, je ne te le dirais pas; car à moi est le monde avec ce qu\'il enserre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Est-ce que je mange la chair des taureaux, et bois le sang des boucs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Fais à Dieu l\'offrande de tes actions de grâces, et accomplis tes vœux envers le Très-haut!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'et invoque-moi au jour de la détresse; je te délivrerai, et tu me glorifieras! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Et Dieu dit au méchant: « Que fais-tu d\'énumérer mes lois, et d\'avoir mon alliance à la bouche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'quand tu hais la discipline, et que tu jettes mes paroles derrière toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Si tu vois un voleur, tu te plais avec lui, et tu entres en part avec les adultères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Tu lâches la bride à ta bouche pour le mal, et ta langue ourdit la fraude;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'tu t\'assieds, et parles contre ton frère, et tu dresses des embûches au fils de ta mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'C\'est ce que tu as fait, et je me suis tu; tu t\'es imaginé que je te ressemblais; mais je te détromperai, et je mettrai la liste devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Prenez-y garde, vous qui oubliez Dieu, de peur que Je ne déchire, sans que personne délivre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Qui m\'offre des actions de grâces, me glorifie; et à quiconque règle sa voie, Je fais voir le salut de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Au maître chantre. Cantique de David, quand Nathan, le prophète, vint vers lui, après que David se fut approché de Bathséba. Fais-moi grâce, ô Dieu, selon ta miséricorde, selon tes grandes compassions, efface mes péchés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Lave, lave encore, et enlève mon crime, et purifie-moi de mon péché!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Car je connais ma faute, et mon péché est toujours en face de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Contre toi, toi seul, j\'ai péché, et j\'ai fait ce qui est mal à tes yeux... [Je l\'avoue] afin que ta justice ressorte, quand tu prononces, et ta pureté, quand tu juges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Voici, je naquis en péché, et en iniquité ma mère me conçut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Voici, tu aimes la vérité dans le cœur: fais-moi donc intérieurement connaître la sagesse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Avec l\'hysope fais sur moi l\'expiation, afin que je devienne pur! lave-moi, pour que je sois plus blanc que la neige!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Annonce-moi l\'allégresse et la joie! fais tressaillir mes os que tu as brisés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Cache-toi la face devant mes péchés, et efface toutes mes fautes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Crée en moi un cœur pur, ô Dieu! et mets en moi un esprit ferme et nouveau!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Ne me bannis pas de ta présence, et ne me retire pas ton Esprit Saint!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Rends-moi les délices de ton secours, et d\'un esprit prompt à bien faire donne-moi l\'appui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Alors aux pécheurs je montrerai tes voies, et ceux qui s\'écartent, reviendront à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Décharge-moi du sang versé, ô Dieu, mon Dieu Sauveur, afin que ma langue chante ta grâce!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Seigneur, ouvre mes lèvres, et ma bouche publiera tes louanges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Car tu n\'aimes pas les sacrifices, sinon j\'en offrirais; les holocaustes ne te sont point agréables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Le sacrifice que Dieu veut, c\'est un esprit contrit; un cœur contrit et brisé, de toi, ô Dieu, n\'est point dédaigné,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Sois par ta faveur le bienfaiteur de Sion, édifie les murs de Jérusalem!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Alors tu agréeras les pieux sacrifices, les holocaustes et les victimes entières, car sur ton autel on offrira des taureaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Au maître chantre. Hymne de David, lorsque Doëg, l\'Iduméen, vint et informa Saül et lui dit: David est venu dans la maison d\'Achimélech. Pourquoi fais-tu gloire de la méchanceté, superbe? La grâce de Dieu subsiste toujours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Ta langue médite la ruine, pareille au rasoir affilé, artisan de ruses!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Tu aimes le mal plus que le bien, le mensonge, plus que les paroles vraies. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Tu aimes tous les discours pernicieux, langue perfide!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Aussi Dieu te détruira pour toujours, Il te saisira, et t\'arrachera de ta tente, et t\'extirpera de la terre des vivants. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Les justes en seront témoins, et ils craindront, et ils se riront de lui:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, '« Le voilà cet homme qui ne prit point Dieu pour son rempart, et qui se confiait dans ses grandes richesses, et se prévalait de sa méchanceté! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Mais moi, je suis comme un vert olivier dans la maison de Dieu, je me confie dans la grâce de Dieu, toujours, à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Je Te louerai éternellement, parce que tu as agi, et j\'espère dans ton nom, parce que tu es bon, en présence de tes Saints.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Au maître chantre. Sur les flûtes. Hymne de David. Les impies ont dit en leur cœur: « Il n\'y a point de Dieu! » Leur méchanceté est perverse, abominable; il n\'y a personne qui fasse le bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'L\'Éternel examine des Cieux les enfants des hommes, pour voir s\'il y a quelque homme raisonnable, qui cherche Dieu:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'tous se sont révoltés, pervertis tous ensemble: il n\'y a personne qui fasse le bien, pas même un.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Ne se reconnaîtront-ils pas tous ces malfaiteurs, qui mangent mon peuple comme du pain? N\'invoqueront-ils point l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Bientôt la terreur les saisira, sans qu\'il y ait une cause de terreur. Car Dieu disséminera les ossements de ceux qui campent contre toi: tu les confondras, car Dieu les a rejetés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Ah! si de Sion le salut venait sur Israël!... \\ Que Dieu ramène les captifs de son peuple! et Jacob se réjouira, et Israël triomphera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Au maître chantre. Avec instruments à cordes. Hymne de David, lorsque les Siphéens vinrent, et dirent à Saül: Voici, David est caché parmi nous. Dieu, sois par ton nom mon sauveur, et par ta puissance, mon défenseur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'O Dieu, écoute ma prière, prête l\'oreille aux paroles de ma bouche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Car des étrangers s\'élèvent contre moi, et des furieux attentent à ma vie; ils ne mettent point Dieu en vue de leurs regards. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Voici, Dieu m\'est secourable, le Seigneur est le soutien de ma vie:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Il fera retomber sur mes ennemis leur méchanceté. Selon ta fidélité anéantis-les!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'D\'un cœur empressé je te ferai des sacrifices, je célébrerai ton nom, Éternel, car il est bon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'car il m\'a délivré de toute adversité, et mes ennemis réjouissent mes regards.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Au maître chantre. Avec instruments à cordes. Hymne de David. O Dieu! prête l\'oreille à ma prière, et ne te dérobe pas à ma supplication!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Fais attention à moi, et m\'exauce! J\'erre en gémissant, et je suis troublé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'à la voix de l\'ennemi, sous l\'oppression de l\'impie; car ils versent sur moi les maux, et me persécutent avec fureur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Mon cœur est tourmenté au dedans de moi, et des craintes de mort m\'ont assailli;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'la peur et le tremblement me pénètrent, et le frisson me parcourt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Aussi dis-je: Qu\'on me donne l\'aile de la colombe, je m\'envolerai, et j\'irai habiter en lieu sûr!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Voici, je fuirais au loin, je m\'arrêterais au désert; (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'je m\'échapperais, plus prompt que le vent rapide, que l\'ouragan!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Consume, Seigneur, confonds leurs langues! Car je vois dans la ville la violence et les rixes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'qui jour et nuit y font la ronde dans ses murs, et le mal et la gêne sont dans son enceinte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'la ruine est dans son enceinte, et la violence et la fraude ne quittent pas ses places.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Ce n\'est pas un ennemi qui m\'outrage: je le supporterais; un homme dont la haine se déclare, qui s\'élève contre moi: je pourrais m\'y soustraire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'mais c\'est toi, homme qui avais mon estime, mon ami, l\'un de mes familiers;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'nous nous rendions l\'un à l\'autre l\'intimité douce; à la maison de Dieu nous allions avec la foule!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Que la mort les surprenne, qu\'ils descendent vivants aux Enfers! car la malice est dans leurs demeures, au milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Cependant, je crie à Dieu, et l\'Éternel me sauvera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Le soir, et le matin, et à midi, je me plains et je gémis, et Il entendra ma voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Il me tirera sain et sauf du combat qu\'on me livre, car mes adversaires sont nombreux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Dieu veut m\'exaucer, et les humilier, (car Il est toujours sur son trône) (Pause) ces hommes qui ne changent point, et n\'ont de Dieu nulle crainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Ils mettent la main sur leurs amis, et brisent leur pacte [d\'union];');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'leur bouche a plus de douceur que le lait, et leur cœur est hostile; leurs paroles sont plus onctueuses que l\'huile, et ce sont des épées nues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, '« Remets à l\'Éternel le soin de ton sort, et Il te soutiendra, et ne permettra pas toujours qu\'on ébranle le juste. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Et toi, ô Dieu, tu les précipiteras au fond de la fosse; et ces hommes sanguinaires et trompeurs ne vivront pas la moitié de leurs jours; mais moi, je mets en toi ma confiance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Au maître chantre. Sur « Colombe des térébinthes lointains ». Ecrit de David, lorsque les Philistins le saisirent à Gath. O Dieu! aie pitié de moi, car des hommes s\'acharnent contre moi; toujours hostiles, ils m\'oppriment;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'mes adversaires s\'acharnent toujours, plusieurs me sont insolemment hostiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Dans mon jour d\'alarmes, je mets en toi ma confiance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Je fais gloire de Dieu, de sa parole, je me confie en Dieu, je ne crains rien: que me feraient des mortels?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Toujours ils rendent mes affaires pénibles; toutes leurs pensées sont de me nuire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Ils se liguent, ils épient et observent mes pas, car ils en veulent à ma vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'A la faveur du mensonge, ils savent échapper. Dans ta colère, ô Dieu, rabaisse les peuples!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Tu comptes mes fuites! Recueille mes larmes dans ton urne! Ne sont-elles pas inscrites dans ton livre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Alors mes ennemis reculeront, si je prie; je le sais! Dieu est pour moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Je fais gloire de Dieu, de sa parole, je fais gloire de l\'Éternel, de sa parole,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'je me confie en Dieu, je ne crains rien: que me feraient des mortels?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'O Dieu! je suis lié par les vœux que je t\'ai faits: il faut que je te rende mes actions de grâces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Car tu as sauvé mon âme de la mort, et même mon pied de la chute, afin que je marche devant Dieu, à la lumière de la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Au maître chantre. Sur « Ne détruis pas » Ecrit de David, quand, fuyant devant Saül, il se retira dans la caverne. Prends pitié de moi, ô Dieu! prends pitié de moi! Car mon âme cherche en toi son refuge; et je me réfugie à l\'ombre de tes ailes, en attendant que la calamité passe,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'J\'invoque le Dieu suprême, le Dieu qui agit en ma faveur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Il enverra des Cieux, pour me sauver et confondre mes ennemis, (Pause) Dieu enverra sa grâce et sa fidélité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Je vis au milieu des lions, gisant parmi des hommes qui vomissent des flammes, des hommes dont les dents sont des dards et des flèches, et la langue, une épée tranchante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Montre, ô Dieu, que tu domines les Cieux! Que sur toute la terre apparaisse ta gloire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Ils tendent un filet sous mes pas, mon âme succombe, ils creusent une fosse devant moi; ils y tombent eux-mêmes. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Mon cœur se rassure, ô Dieu! mon cœur se rassure. Je veux te célébrer par mes chants et mes accords.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Èveille-toi, mon esprit, éveille-toi, mon luth, ma harpe! Je veux me lever avec l\'aurore!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Je te célébrerai parmi les peuples, Seigneur, je te chanterai parmi les nations;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'car ta miséricorde est grande jusques aux Cieux, et ta fidélité jusques aux nues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Montre, ô Dieu, que tu domines les Cieux; et que sur toute la terre apparaisse ta gloire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Au maître chantre. Sur « Ne détruis pas ». Ecrit de David. Prononcez-vous vraiment selon la loi, la justice, jugez-vous avec droiture, enfants des hommes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Non! en votre cœur vous commettez l\'injustice, et vous dispensez dans le pays la violence de vos mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Les impies prévariquent dès le sein maternel, les menteurs ont dévié dès leur naissance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'ils ont un venin pareil au venin du serpent, de la vipère sourde, qui se bouche les oreilles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'qui n\'écoute point la voix des enchanteurs, du magicien habile à former les nœuds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'O Dieu! brise leurs dents dans leur bouche! Romps, ô Éternel, la mâchoire des lions!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Qu\'ils s\'évanouissent, comme une eau qui s\'écoule! Que les flèches qu\'ils décochent, soient comme tronçonnées!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Qu\'ils soient comme le limaçon qui va se fondant, comme l\'avorton de la femme, qui n\'a pas vu le jour!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Avant même que vos chaudières sentent le feu des épines, Il emportera par la tempête et l\'épine encore verte, et celle qui déjà brûle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Alors le juste sera réjoui, car il verra la vengeance: il baignera ses pieds dans le sang de l\'impie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'et l\'homme dira: Oui, il est des fruits pour le juste; oui, il est un Dieu qui juge sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Au maître chantre. Sur « Ne détruis pas ». Ecrit de David, quand Saül envoya, et qu\'ils gardèrent la maison, pour le faire mourir. Délivre-moi de mes ennemis, mon Dieu! et mets-moi hors de l\'atteinte de mes agresseurs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Délivre-moi des hommes malfaisants, et sauve-moi des hommes sanguinaires!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Car voici, ils tendent des embûches à mon âme; des violents se liguent contre moi, sans qu\'il y ait en moi ni crime, ni péché, Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Je ne suis pas coupable, et ils accourent et se campent: veille! viens à moi, et regarde!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'O toi, Éternel, Dieu des armées, Dieu d\'Israël, réveille-toi pour châtier tous les peuples! N\'épargne aucun de ces traîtres méchants! (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Ils reviennent le soir, ils hurlent comme les chiens, et ils parcourent la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Voici, de leurs bouches ils vomissent leurs propos; des glaives sont sur leurs lèvres! « Car, qui est là pour entendre? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Mais toi, Éternel, tu te ris d\'eux, et tu te moques de toutes les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Ils sont forts!... Je regarde vers toi; car l\'Éternel est mon boulevard.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Mon Dieu me prévient par sa grâce; Dieu fait que mes ennemis réjouissent mes regards.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Ne les tue point, de peur que mon peuple n\'oublie!... \\ Défais-les par ta puissance, et les précipite, ô toi, notre bouclier, Seigneur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Il y a péché dans leur bouche à tous les propos de leurs lèvres: qu\'ils soient donc pris au piège, pour leur orgueil, et pour les parjures et les mensonges qu\'ils profèrent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Détruis, détruis-les dans ton courroux, et qu\'ils ne soient plus! afin qu\'ils apprennent que Dieu règne en Jacob, jusqu\'aux extrémités de la terre. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Qu\'ils reviennent le soir, hurlent comme les chiens, et qu\'ils parcourent la ville!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Qu\'ils rôdent cherchant une curée. ayant passé la nuit sans s\'être rassasiés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Mais moi, je chanterai ta puissance, et dès le matin je dirai les louanges de ta grâce; car tu es mon boulevard, et mon refuge dans mon jour de détresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'O toi, qui es ma force, je veux te célébrer! car Dieu, mon Dieu bon, est mon boulevard.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Au maître chantre. Sur Schouschan-Edouth. Ecrit didactique de David, quand il faisait la guerre aux Syriens de Mésopotamie et aux Syriens de Zoba, et que Joab revint, et battit les Edomites dans la vallée du sel, au nombre de douze mille. O Dieu, tu nous as rejetés, nous as dispersés; tu étais irrité: rends-nous ton amour!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Tu as ébranlé, déchiré le pays: guéris ses blessures, car il est chancelant!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Tu as fait sentir la rigueur à ton peuple, tu nous a fait boire le vin du vertige.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Tu as donné à tes fidèles une bannière, afin qu\'ils se lèvent au nom de la vérité. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Pour que tes bien-aimés soient sauvés, aide-les de ta droite, et nous exauce!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Dieu l\'a promis par sa sainteté: je veux m\'en réjouir! « Je vous partagerai Sichem, et vous distribuerai la Vallée de Succoth;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Galaad est à moi, Manassé est à moi, Ephraïm est le rempart de ma tête, et Juda, mon sceptre royal;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Moab est le bassin où je me baigne, et sur Edom je jette ma chaussure; pour moi, Philistie, élève tes acclamations! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Qui me conduira dans la ville forte? qui me mènera jusqu\'en Edom?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'N\'est-ce pas toi, ô Dieu, toi qui nous rejetas, et ne marchas plus, ô Dieu, avec nos armées?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Donne-nous ton aide pour sortir de la gêne, puisque le secours de l\'homme est une vanité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Avec Dieu, nous serons vainqueurs, et c\'est Lui qui foulera nos ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Au maître chantre. Avec instruments à cordes. De David. Ecoute, ô Dieu, ma plainte, sois attentif à ma prière!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Du bout de la terre je t\'invoque, le cœur assombri: conduis-moi sur le rocher où je ne saurais monter!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Car tu es mon refuge, ma forte tour en face de l\'ennemi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Laisse-moi faire de ta tente mon séjour éternel, et chercher mon asile sous l\'abri de tes ailes. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Car, ô Dieu, tu exauces mes vœux, et tu remets en possession ceux qui craignent ton nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Ajoute des jours aux jours du Roi! Que ses ans soient comme un âge ajouté à des âges!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Qu\'il reste sur le trône éternellement devant Dieu! Dispense-lui la grâce et la fidélité, qui le gardent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Alors je chanterai ton nom à jamais, en accomplissant mes vœux tous les jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Au maître chantre, préposé aux Jéduthunites. Cantique de David. Oui, c\'est Dieu que mon âme attend en silence: de Lui me viendra le secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Oui, Il est mon rocher et mon secours, mon boulevard: je ne serai pas ébranlé beaucoup.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Jusques à quand fondrez-vous sur un homme, voulez-vous tous le mettre en pièces, comme une cloison qui penche, un mur que l\'on bat?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Oui, ils méditent de le précipiter du faîte où il est, ils se plaisent à mentir; de leur bouche ils bénissent, et dans leur cœur ils maudissent. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Oui, en Dieu, ô mon âme, espère en silence! car Il est pour moi la source de l\'espérance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Oui, Il est mon rocher et mon secours, mon boulevard: je ne serai point ébranlé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Sur Dieu reposent mon salut et ma gloire; mon rocher protecteur, mon refuge est en Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Peuple, en Lui confiez-vous toujours, répandez devant Lui vos cœurs! Dieu est notre refuge!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Les hommes ne sont qu\'un néant, et les mortels un mensonge; dans la balance ils s\'élèvent, ils ne sont rien tous ensemble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Ne vous confiez point dans l\'oppression, et dans la rapine ne mettez pas un vain espoir! Si les biens s\'accroissent, n\'en soyez point émus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Il est une chose que Dieu a dite, deux que j\'ai ouïes, c\'est que la puissance est à Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Et tu es aussi, Seigneur, le maître de la grâce; car tu rends à chacun selon ses œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Cantique de David, lorsqu\'il était dans le désert de Juda. O Dieu! tu es mon Dieu, c\'est toi que je cherche; mon âme a soif de toi, ma chair languit après toi, comme une terre aride, altérée, privée d\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Ainsi, mes regards te suivent dans le Sanctuaire, pour contempler ta gloire et ta magnificence;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'car ta grâce est meilleure que la vie: mes lèvres te glorifient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Ainsi, je te loue durant ma vie. c\'est en ton nom que j\'élève mes mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Mon âme est rassasiée comme de moelle et de graisse, et d\'une voix d\'allégresse ma bouche te célèbre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Quand ta pensée me revient sur ma couche, c\'est sur toi que je médite durant les veilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Car tu es mon secours, et je me réjouis à l\'ombre de tes ailes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'mon âme s\'attache à toi, ta droite me soutient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Mais ceux qui, pour me perdre, attentent à ma vie, tomberont dans les profondeurs de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Ils seront livrés à l\'épée, et deviendront la proie des chacals.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Et le Roi aura en Dieu une cause d\'allégresse, et quiconque jure par Lui, fera éclater sa joie, quand les menteurs auront la bouche fermée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Au maître chantre. Cantique de David. Entends, ô Dieu, ma voix, quand je gémis! Préserve ma vie de l\'ennemi qui m\'effraie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Mets-moi à couvert des complots des méchants, de la troupe de ceux qui font le mal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'qui aiguisent leur langue comme une épée, et décochent, comme des flèches, des paroles amères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'pour atteindre en cachette l\'innocent; soudain ils l\'atteignent, et sont sans crainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Résolus à faire un mauvais coup, ils se concertent pour cacher des pièges, et disent: « Qui en serait témoin? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Ils projettent des crimes: « Nous sommes prêts, le plan est conçu! » Et tous ils cachent le fond de leur pensée et de leurs cœurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Alors Dieu les atteint de sa flèche; leur défaite est soudaine,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'et ils tombent: leur langue même en est cause; tous ceux qui les voient, fuient,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'et tous les hommes sont saisis de crainte, et publient l\'œuvre de Dieu, et reconnaissent son action.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Le juste est ravi de l\'Éternel, et se confie en lui, et tous les hommes droits se glorifient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Au maître chantre. Cantique de David. A toi confiance et louange, ô Dieu, en Sion! et qu\'en ton honneur des vœux soient accomplis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'O toi, qui exauces la prière! toute chair s\'adresse à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Les iniquités l\'emportent sur moi, mais tu pardonneras nos péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Heureux celui que tu choisis, et admets à séjourner dans tes parvis! Nous voulons être nourris du bonheur de ta maison, de ton saint temple!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Tu fais des prodiges pour nous exaucer, en nous donnant la grâce, ô notre Dieu sauveur, en qui se confient toutes les extrémités lointaines de la terre et de la mer!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Celui qui par sa force affermit les montagnes, est ceint de puissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Il met fin au tumulte de la mer, au tumulte de ses flots, et à la rumeur des peuples;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'les habitants de l\'horizon s\'effraient à ses miracles, et tu remplis d\'allégresse les lieux d\'où surgissent l\'aube et le crépuscule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Tu visites la terre et tu lui donnes l\'abondance, tu l\'enrichis de mille dons; les eaux remplissent le ruisseau de Dieu; tu prépares le blé des hommes, quand tu la prépares');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'en abreuvant ses sillons, en nivelant ses glèbes; tu l\'amollis par des rosées, et tu bénis ses germes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Tu couronnes l\'année que ta bonté nous donne, et sous tes pas coule la fécondité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'ils fertilisent les pacages du désert, et les collines prennent une ceinture riante;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'les prairies se couvrent de brebis, et les blés revêtent les vallées: les cris de joie et les chants retentissent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Au maître chantre. Cantique. Terre, élève à Dieu de toutes parts tes acclamations!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Chantez son nom glorieux, que vos hymnes le glorifient!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Dites à Dieu: « Que tes œuvres sont admirables! Aux effets de ta grande puissance tes ennemis dissimulent devant toi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'toute la terre t\'adore et te célèbre; célèbre ton nom! » (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Venez et contemplez les œuvres de Dieu, admirable en ce qu\'il opère pour les enfants des hommes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Il transforma la mer en terre sèche; au travers du fleuve ils passèrent à pied, et Il excita nos transports.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Il exerce par son pouvoir un empire éternel, ses yeux observent les peuples: que les rebelles ne s\'insurgent pas! (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Peuples, bénissez notre Dieu, et proclamez sa louange!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Il redonna la vie à nos âmes, et ne laissa pas nos pieds trébucher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Car tu nous as éprouvés, ô Dieu, purifiés, comme l\'on purifie l\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Tu nous enlaças dans le filet, et tu mis un faix sur nos reins;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'tu donnas à des hommes nos têtes pour monture, nous passâmes par le feu et les eaux; mais tu nous en as tirés pour nous combler de biens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Je viens dans ta maison avec des holocaustes; je veux m\'acquitter envers toi de mes vœux');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'exprimés par mes lèvres, prononcés par ma bouche dans ma détresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Je t\'offrirai des holocaustes et des brebis engraissées, et ferai fumer la graisse des béliers; je te sacrifierai des taureaux et des boucs. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Venez, écoutez, vous tous qui craignez Dieu, je veux raconter ce qu\'il fit pour mon âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'De ma bouche je l\'invoquai; et sa louange est maintenant sur ma langue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Si dans mon cœur j\'avais eu le mal en vue, le Seigneur ne m\'eût pas exaucé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'mais Dieu m\'a exaucé, Il a été attentif aux accents de ma prière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Béni soit Dieu, qui n\'a pas rebuté ma prière, et ne m\'a pas refusé sa grâce!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Au maître chantre. Avec instruments à cordes. Cantique. Que Dieu nous soit favorable et nous bénisse! Qu\'il fasse luire sa face sur nous! (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'afin que la voie que Tu suis, soit connue sur la terre, et parmi les nations, le secours que Tu donnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Les peuples te louent, ô Dieu, tous les peuples te louent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Que les nations se réjouissent, et qu\'elles chantent! car tu juges les nations avec équité, et tu es le guide des nations sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Que les peuples te louent, ô Dieu! que tous les peuples te louent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'La terre a donné ses récoltes. Que Dieu, notre Dieu, nous bénisse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Que Dieu nous bénisse, et qu\'il soit craint de toutes les extrémités de la terre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Au maître chantre. Cantique de David. Que Dieu se lève, ses ennemis se dissipent, et ses adversaires fuient sa présence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Tu les balaies, comme une fumée chassée; de même que la cire fond au feu, ainsi disparaissent les impies devant Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Et les justes sont transportés, ravis devant Dieu, et tressaillent d\'allégresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Chantez Dieu, célébrez son nom! Ouvrez-lui les chemins, Il s\'avance au désert! L\'Éternel est son nom; réjouissez-vous à son aspect!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Père des orphelins et défenseur des veuves, tel est notre Dieu dans sa demeure sainte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Il donne aux bannis une habitation, Il élargit les captifs pour les rendre heureux; seuls les rebelles habitent une terre aride.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'O Dieu, quand tu sortis à la tête de ton peuple, quand tu t\'avançais traversant le désert, (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'la terre trembla, et les Cieux ruisselèrent en présence de Dieu; ce Sinaï trembla devant Dieu, le Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Tu fis tomber, ô Dieu, une rosée bienfaisante, et tu restauras ton héritage épuisé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Ton peuple s\'établit en ce lieu; tu l\'avais, ô Dieu, préparé dans ta bonté pour les malheureux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Dieu fit entendre les hymnes des femmes annonçant la victoire à la grande armée:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, '« Les rois des nations fuient, ils fuient, et celle qui garde le logis, distribue le butin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Tandis que vous goûtez le repos parmi les bergeries, vous recevez des ailes de colombes recouvertes d\'argent et leur plumage orné de l\'or pâle. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Lorsque dans ce lieu le Tout-puissant dispersa les rois, le sol blanchit, comme le Salmon, quand il neige.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Montagnes de Dieu, monts de Basan, monts aux cimes nombreuses, monts de Basan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'pourquoi, cimes et montagnes, ces regards d\'envie contre la montagne que Dieu choisit pour sa demeure? Aussi bien Il l\'habite pour jamais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Les chars de Dieu sont deux fois dix mille, des milliers, et encore des milliers; le Seigneur est au milieu; Sinaï est dans le Sanctuaire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Tu montes sur la hauteur, tu mènes des captifs; tu reçois des hommes en don; les rebelles aussi viennent habiter avec l\'Éternel Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Que le Seigneur soit béni chaque jour! Nous charge-t-on d\'un fardeau, Dieu est notre aide. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Ce Dieu est pour nous un Dieu secourable, et l\'Éternel, le Seigneur, sait nous soustraire à la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Oui, Dieu frappera la tête de ses ennemis, le crâne chevelu de ceux qui suivent la voie de leur crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Le Seigneur dit: « Je les ramènerai de Basan, les ramènerai du fond de la mer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'afin que tu remues tes pieds dans le sang, et que la langue des chiens ait part au sang de tes ennemis. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Ils contemplent ta marche, ô Dieu, la marche de mon Dieu, de mon Roi dans le Sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'En tête sont les chantres, après eux les musiciens, au milieu des vierges qui agitent les cymbales.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, '« En chœur bénissez Dieu, le Seigneur, vous qui sortez de la source d\'Israël! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Là est Benjamin le jeune, et ses chefs, les princes de Juda, et sa multitude, les princes de Zabulon, les princes de Nephthali.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, '[Israël!] ton Dieu a décrété ta puissance: montre-toi puissant, ô Dieu, qui as agi pour nous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'de ton temple qui domine Jérusalem! Que les rois t\'apportent leurs offrandes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Gourmande le monstre qui gîte dans les roseaux, la troupe des taureaux escortés des veaux des nations! Les faisant venir à Ses pieds avec des pièces d\'argent, Il dissipe les peuples qui se plaisent aux combats.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Des Grands arrivent de l\'Egypte, et l\'Ethiopie accourt, les mains tendues vers Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Royaumes de la terre, élevez à Dieu vos cantiques, par vos concerts célébrez le Seigneur, (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'qui s\'avance dans les espaces des Cieux éternels: voici, de sa voix Il produit des éclats puissants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Rendez l\'honneur à Dieu, dont la majesté protège Israël, et dont la puissance apparaît dans les nues!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'De ton Sanctuaire, ô Dieu, tu es redoutable. C\'est le Dieu d\'Israël, qui donne force et puissance à son peuple. Béni soit Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Au maître chantre. En schoschanim. De David. Sauve-moi, ô Dieu, car les eaux m\'envahissent au péril de ma vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Je suis plongé dans un bourbier profond, où je ne puis prendre pied; je suis enfoncé dans les eaux profondes, et les flots me submergent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Je suis las à force de crier, mon gosier est brûlant; mes yeux se consument, dans l\'attente de mon Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Ceux qui me sont gratuitement hostiles, surpassent en nombre les cheveux de ma tête; mes destructeurs, mes fourbes ennemis se sont renforcés; je dois restituer ce que je n\'ai point dérobé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'O Dieu, tu connais ma folie, et mes délits ne te sont point cachés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Ne permets pas que je sois une cause de confusion pour ceux qui se confient en toi, Seigneur, Éternel des armées, ni une cause de honte pour tes adorateurs, Dieu d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Car c\'est à cause de toi que je souffre l\'opprobre, et que la honte recouvre mon visage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Je suis devenu un étranger pour mes frères, un inconnu pour les fils de ma mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Car le zèle de ta maison me consume, et les outrages de ceux qui t\'outragent, tombent sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Et je pleure et je jeûne; mais cela me tourne à opprobre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'et je prends pour habit le cilice, par là je donne lieu à leurs satires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Je suis l\'entretien de ceux qui sont assis aux Portes, et ils disent contre moi les chansons des buveurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Cependant ma prière s\'élève à toi, Éternel! Que le temps soit propice, ô Dieu, par ta grande bonté! Exauce-moi par ta fidélité secourable!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Retire-moi du bourbier, et ne m\'y laisse pas enfoncer! Que je sois sauvé de mes ennemis, et du gouffre des eaux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Ne me laisse pas submerger par les flots, ni engloutir par l\'abîme; et que le puits ne referme pas sa bouche sur moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Exauce-moi, Éternel, car ta grâce est excellente: en tes grandes compassions tourne les yeux vers moi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'et ne cache pas ta face à ton serviteur! Car je suis angoissé; hâte-toi, réponds-moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Rapproche-toi de mon âme, rachète-là! A cause de mes ennemis sauve-moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Tu connais mon opprobre, et ma honte, et mon ignominie, tu as sous les yeux tous mes adversaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Les outrages ont brisé mon cœur, et je suis malade; j\'attends de la pitié, et il n\'en est point pour moi, et des consolateurs, et je n\'en trouve aucun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Ils mettent du fiel dans ma nourriture, et pour calmer ma soif, ils m\'abreuvent de vinaigre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Que leur propre table leur soit un piège, et un filet dans leur sécurité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Que leurs yeux obscurcis cessent de voir! et fais que leurs reins toujours soient mal affermis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Verse sur eux ta colère, et que le feu de ton courroux les atteigne!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Que leurs campements soient désolés, et qu\'en leurs tentes il n\'y ait point d\'habitants!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Car ils persécutent celui que tu as frappé, et ils narrent les douleurs de ceux que tu as percés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Fais qu\'ils ajoutent crime à crime, et qu\'ils n\'arrivent pas à ta justice!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Qu\'ils soient effacés du livre des vivants, et qu\'avec les justes ils ne soient point inscrits!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Cependant je suis affligé et souffrant: ton secours, ô Dieu, me mettra en lieu sûr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Je louerai le nom de Dieu par des chants, et je le magnifierai par des actions de grâces:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'elles plairont plus à Dieu que des taureaux, que des taureaux ayant cornes et sabots.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Les affligés le verront et seront réjouis. Que votre cœur revive, à vous qui cherchez Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Car l\'Éternel écoute les pauvres, et Il ne dédaigne point ses captifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Qu\'il soit loué par le ciel et par la terre, par les mers, et tout ce qui se meut en elles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Car Dieu sauvera Sion, et relèvera les villes de Juda, qui sera habitée, et qui sera recouvrée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'et la race de ses serviteurs l\'aura pour héritage, et ceux qui aiment son nom, l\'auront pour demeure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Au maître chantre. De David. En souvenir. >O Dieu, pour me délivrer, Éternel, accours à mon aide!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Qu\'ils soient couverts de honte et d\'opprobre ceux qui attentent à ma vie! Qu\'ils reculent confondus ceux qui veulent mon malheur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Qu\'ils fassent retraite par l\'effet de leur honte ceux qui disent: « Le voilà! le voilà! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Alors tu feras la joie et l\'allégresse de tous ceux qui te cherchent; et ils diront toujours: « Dieu est grand! » ceux qui désirent ton secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Et moi, je suis misérable et dénué: ô Dieu! accours vers moi! Tu es mon aide et mon libérateur! Éternel, ne tarde pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Éternel, je me réfugie vers toi: que je ne sois jamais confondu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Par ta justice sauve et délivre-moi! Penche vers moi ton oreille, et sois-moi secourable!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Sois pour moi un rocher où je trouve un asile, pour que je m\'y retire en tout temps! Tu as résolu de me sauver, car tu es ma citadelle et mon fort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Mon Dieu, sauve-moi de la main de l\'impie, du bras du méchant et de l\'oppresseur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Car tu es mon espérance, Seigneur, Éternel, dès mon jeune âge en toi je me confie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'sur toi je m\'appuie dès le sein de ma mère, et c\'est toi qui m\'as tiré de ses flancs; tu es toujours l\'objet de mes louanges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Je suis comme un miracle pour plusieurs: c\'est que tu es mon puissant recours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Ma bouche est remplie de tes louanges, tous les jours je te glorifie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Ne me rejette pas au temps de ma vieillesse! Quand ma force dépérit, ne me délaisse pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Car mes ennemis parlent de moi, et ceux qui épient mon âme, se concertent ensemble,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'disant: « Dieu l\'a délaissé, poursuivez, saisissez-le; car il est sans libérateur! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'O Dieu, ne sois pas loin de moi! Mon Dieu, accours à mon aide!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Qu\'ils soient confondus, exterminés, les ennemis de mon âme, couverts de honte et d\'opprobre, ceux qui cherchent ma perte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Mais j\'aurai toujours espérance, et je pourrai ajouter encore à toutes tes louanges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Ma bouche dira ta justice, chaque jour ton salut, car je ne saurais compter [tous tes bienfaits].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Je viendrai chantant tes hauts faits, Seigneur; Éternel, c\'est ta justice seule que je célébrerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'O Dieu, tu m\'as instruit dès mon jeune âge, et jusques aujourd\'hui je publie tes merveilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Mais, toi aussi, jusqu\'à la vieillesse, aux cheveux blancs, ô Dieu, ne me délaisse pas! afin que j\'annonce tes faits aux hommes d\'à présent, et à tous ceux qui naîtront, ta puissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Aussi bien ta justice, ô Dieu, atteint au ciel. Tu as fait de grandes choses, ô Dieu; qui est pareil à toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Tu nous fis voir beaucoup d\'angoisses et de maux: de nouveau tu nous donneras la vie, et tu nous tireras encore des abîmes de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Daigne augmenter ma grandeur, te tourner vers moi, et me consoler!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Et au son du luth je te louerai, dirai la fidélité, mon Dieu, je te chanterai avec la harpe, Saint d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'La joie sera sur mes lèvres, car c\'est toi que je chanterai, et dans mon âme, car tu l\'as délivrée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'ma langue aussi toujours dira ta justice; car ils sont couverts de honte et d\'opprobre ceux qui cherchent ma perte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'De Salomon. O Dieu, donne au Roi tes jugements, et ta justice au Fils du Roi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Il jugera ton peuple avec justice, et tes affligés avec équité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Les monts et les coteaux, par l\'effet de la justice, porteront la paix pour le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Il fera justice aux malheureux du peuple, il sera secourable aux enfants du pauvre, et il écrasera les oppresseurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Tu seras craint, tant que le soleil luira, tant que la lune éclairera, d\'âge en âge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Il descendra, comme une pluie sur un champ dépouillé, comme une rosée qui humecte la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'En ses jours le juste fleurira, et le salut abondera, jusqu\'à ce que la lune cesse d\'être.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Et il régnera d\'une mer à l\'autre mer, et du Fleuve aux extrémités de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Devant lui s\'inclineront les habitants du désert, et ses ennemis baiseront la poussière;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'les rois de Tarsis et des Iles paieront un tribut; les rois de Séba et de Méroë apporteront des présents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Tous les rois se prosterneront devant lui, et tous les peuples le serviront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Car il sauvera le pauvre qui crie au secours, et le malheureux qui est sans aide;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'il aura pitié du misérable et de l\'indigent, et il sauvera la vie au pauvre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'il les délivrera de la violence et de l\'oppression, et leur sang aura un grand prix à ses yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Et ils auront la vie, et il leur donnera de l\'or de Séba, et pour lui ils prieront incessamment; toujours ils le béniront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Les blés abonderont dans le pays, au sommet des montagnes et leurs épis bruiront, comme le Liban. Des villes on verra fleurir les hommes, comme l\'herbe de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Son nom sera éternel; tant que le soleil luira, son nom se propagera, on le nommera pour se bénir mutuellement; tous les peuples le proclameront heureux. \\csp{');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Béni soit l\'Éternel Dieu, Dieu d\'Israël, qui seul fait des choses merveilleuses!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'et béni soit a jamais son nom glorieux, et que toute la terre soit pleine de sa magnificence! ainsi soit-il! oui, ainsi soit-il!} \\csp{');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Fin des prières de David, fils d\'Isaï.}');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Cantique d\'Asaph. Oui, Dieu est bon envers Israël, envers ceux qui ont un cœur pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Cependant mon pied fut bien près de broncher; un rien eût déroulé mes pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'car j\'enviais les superbes: j\'avais le bonheur des impies sous les yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Car ils sont exempts de douleurs jusqu\'à leur mort, et leur corps est bien entretenu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'ils sont en dehors des peines des mortels, et comme les humains ils ne sont point frappés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Aussi, comme un collier l\'orgueil les entoure, et comme un habit la violence les revêt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'L\'embonpoint rend leurs yeux saillants, et les pensées de leur cœur se produisent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Ils sont moqueurs, et parlent méchamment; de leur hauteur ils parlent d\'opprimer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'de leur bouche ils affrontent le ciel même, et leur langue se démène sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Aussi, c\'est de ce côté que Son peuple se tourne; il veut aussi s\'abreuver aux eaux abondantes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'et dit: « Comment Dieu prendrait-il connaissance, et le Tout-puissant aurait-Il la science? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Les voilà ces impies! et toujours tranquilles ils grossissent leurs trésors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'C\'est en pure perte que je gardai mon cœur net, et que je lavai mes mains dans l\'innocence;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'et je fus frappé tous les jours, et chaque matin je subis ma peine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Si je disais: Je veux parler ainsi, voici, je trahirais la race de tes enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Alors je réfléchis, pour me rendre compte de ces choses; c\'était à mes yeux une tâche difficile,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'jusqu\'à ce que, pénétrant dans les sanctuaires de Dieu, je fis attention à la fin de ces hommes');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Tu ne les as placés que sur un sol glissant; tu les fait tomber, et ils sont en ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Comme ils sont anéantis tout à coup, emportés et détruits par une chute soudaine!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Tel un songe au réveil, ainsi, les réveillant, Seigneur, tu mets avec mépris leur fantôme à néant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Quand mon cœur s\'exaspérait, et que dans mes reins je sentais l\'aiguillon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'alors j\'étais stupide, et dans l\'ignorance, j\'étais disposé comme une brute envers toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Cependant je te demeurai toujours attaché; tu me pris par la main, par ma droite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Par ta sagesse tu me conduiras, et enfin tu me recueilleras dans la gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Qui ai-je dans les Cieux? Et auprès de toi je n\'aime rien sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Que mon cœur et ma chair soient consumés, le rocher de mon cœur et ma part, c\'est Dieu, à jamais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Car voici, ceux qui te désertent, périssent; tu détruis tous ceux qui loin de toi vont se prostituer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Mais pour moi, être près de Dieu, c\'est mon bien. Je mets ma confiance dans le Seigneur, l\'Éternel, afin de pouvoir raconter toutes tes œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Hymne d\'Asaph. Pourquoi, ô Dieu, rejettes-tu toujours, ta colère fume-t-elle sur le troupeau dont tu es le pasteur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Aie souvenir de ton peuple que tu acquis autrefois, réclamas comme ta tribu d\'héritage, de la montagne de Sion, où tu fixas ta demeure!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Dirige tes pas vers des ruines déjà vieilles! L\'ennemi dévaste tout dans le Sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Tes adversaires rugissent au sein de tes parvis: c\'est leur culte qu\'ils érigent en culte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'On dirait des hommes qui lèvent et font retomber les haches dans l\'épaisseur d\'un bois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Et ils en brisent déjà les sculptures, sous les cognées et les marteaux à la fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Ils mettent en feu ton Sanctuaire; sacrilèges ils renversent la demeure de ton nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Ils disent en leur cœur: « Accablons-les tous ensemble! » Ils brûlent dans le pays tous les saints lieux d\'assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Nous ne voyons plus notre culte, il n\'y a plus de prophète, nous n\'avons personne qui sache jusques à quand...!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Jusques à quand, ô Dieu, l\'ennemi sera-t-il insultant? Toujours l\'ennemi méprisera-t-il ton nom?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Pourquoi retires-tu ta main et ta droite? Tire-la de ton sein, et extermine!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Cependant Dieu est mon Roi dès les temps de jadis, opérant des délivrances dans le sein du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Par ta puissance tu entr\'ouvris la mer, tu brisas les têtes des dragons dans ses eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Tu fracassas les têtes des Léviathans, et les livras en proie aux hôtes du désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Tu fis jaillir des sources et des torrents, tu desséchas des fleuves qui ne tarissent jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'A toi est le jour, et à toi la nuit; tu disposas les luminaires et le soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Tu as placé toutes les bornes de la terre; l\'été et l\'hiver, c\'est toi qui les as faits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Souviens-t\'en: l\'ennemi outrage l\'Éternel, et un peuple en délire insulte à ton nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Ne livre pas aux bêtes l\'âme de ta tourterelle, et n\'oublie pas pour toujours la vie de tes affligés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Considère l\'alliance! car les retraites du pays sont pleines de repaires de la violence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Ne renvoie pas l\'opprimé confus! Que l\'affligé et le pauvre aient à louer ton nom!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Lève-toi, ô Dieu, défends ta cause! Pense aux outrages que te fait l\'impie tous les jours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'N\'oublie pas la clameur de tes ennemis, la rumeur de tes adversaires qui s\'élève sans cesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Au maître chantre. Sur « Ne détruis pas ». Cantique d\'Asaph. Nous te louons, ô Dieu, nous te louons: car ton Nom est présent, tous racontent tes merveilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, '« Quand j\'aurai fixé l\'époque, je rendrai droite justice:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'la terre tremble avec ceux qui l\'habitent: c\'est moi qui affermis ses colonnes. » (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Je dis donc aux superbes: Ne soyez point superbes! et aux impies: Ne portez point le front haut!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Ne portez point le front haut, et le col renversé ne parlez point avec audace!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Car ce n\'est ni du Levant, ni du Couchant, ni du désert, que peut venir la hauteur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'mais Dieu est celui qui juge; Il abaisse l\'un, et Il élève l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Car un calice est dans la main de l\'Éternel, et le vin y écume, il est plein d\'un mélange; et Il en verse; Oui, jusqu\'à la lie, tous les impies de la terre devront s\'en abreuver, en boire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Et c\'est ce que j\'annoncerai incessamment, en célébrant le Dieu de Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, '« Et J\'abattrai toutes les têtes des méchants; que les têtes des justes se lèvent! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Au maître chantre. Avec instruments à cordes. Cantique d\'Asaph. Dieu est connu en Juda, son nom est grand en Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'et sa demeure est en Salem, et sa résidence en Sion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Là Il a brisé les foudres de l\'arc, le bouclier, et l\'épée, et les armes de guerre. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Tu es plus brillante, plus magnifique que les montagnes des ravisseurs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Ils furent dépouillés les héros courageux, et ils s\'endormirent de leur sommeil; et tous les braves ne retrouvèrent plus leurs bras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'A ta menace, Dieu de Jacob, et chars et chevaux furent engourdis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Tu es formidable; qui peut tenir contre toi, dès que tu t\'irrites?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Des cieux tu promulguas ta sentence; la terre fut en effroi, et se calma,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'lorsque Dieu se leva pour juger, pour porter secours à tous les affligés de la terre. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Oui, la fureur de l\'homme te glorifie; tu t\'entoures de ceux qui survivent à ta colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Faites et acquittez des vœux à l\'Éternel, votre Dieu! Que de tous Ses alentours on apporte des dons au Dieu terrible!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Il abat l\'orgueil des princes, Il est redoutable aux rois de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Au maître chantre préposé aux Jeduthunites. Cantique d\'Asaph. Ma voix s\'élève à Dieu, et je prie; ma voix s\'élève à Dieu, ô qu\'il m\'écoute!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Dans mon jour d\'angoisse je cherche le Seigneur; la nuit mes mains sont tendues, et ne se lassent point; mon âme repousse la consolation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Je pense à Dieu, et je gémis, je réfléchis, et mon esprit se voile. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Tu tiens mes paupières éveillées, je suis agité, et je ne puis parler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Je repasse les jours de jadis, les années d\'autrefois,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'je me rappelle mes chants de la nuit, je réfléchis en mon cœur, et mon esprit cherche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Le Seigneur rejettera-t-Il à jamais, ne sera-t-Il plus désormais propice?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Pour toujours sa grâce a-t-elle cessé, en est-ce fait de la promesse à perpétuité?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Dieu a-t-Il oublié la pitié, et dans sa colère arrêté le cours de ses compassions? (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Et je dis: Voici ce qui me fait souffrir: la droite du Très-haut n\'est plus la même...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Je veux rappeler les actes de l\'Éternel; car je me rappelle tes miracles d\'autrefois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'et je veux méditer sur toutes tes œuvres, et considérer tes hauts faits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'O Dieu, ta voie est sainte; quel Dieu est grand comme Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Tu es le Dieu qui fais des miracles! Tu as manifesté ta puissance parmi les peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'De ton bras tu délivras ton peuple, les enfants de Jacob et de Joseph. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Les eaux t\'ont vu, ô Dieu, les eaux t\'ont vu, et ont tremblé, et les flots ont été ébranlés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Les nuages ont épandu les eaux, et les nues ont fait entendre une voix, et tes flèches volèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Ton tonnerre éclata en roulements, les éclairs illuminèrent le monde. La terre s\'émut et trembla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'La mer fut ton chemin, et les grandes eaux, tes sentiers; et l\'on ne put reconnaître tes traces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Comme un troupeau tu conduisis ton peuple, par les mains de Moïse et d\'Aaron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Hymne d\'Asaph. Mon peuple, écoute mes leçons! Prêtez l\'oreille aux paroles de ma bouche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Je vais ouvrir la bouche par des chants, et du passé faire jaillir des sentences.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Ce que nous avons entendu et appris, et que nos pères nous ont raconté,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'nous ne le cèlerons point à leurs enfants, redisant à la race future les louanges de l\'Éternel, et sa puissance, et les miracles qu\'il fit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Il érigea un témoignage en Jacob, et Il déposa une loi en Israël, qu\'il ordonna à nos pères d\'enseigner à leurs enfants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'pour qu\'elle fût connue de l\'âge qui suivrait, des enfants qui naîtraient, grandiraient pour la redire à leurs enfants;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'afin qu\'ils missent en Dieu leur confiance, et n\'oubliassent point les œuvres de Dieu, et qu\'ils gardassent ses commandements,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'et ne fussent pas, comme leurs pères, une race réfractaire et rebelle, une race qui n\'avait pas un cœur constant, et dont l\'âme ne Lui était pas fidèle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Les enfants d\'Ephraïm furent des tireurs armés de l\'arc, qui tournent le dos au jour du combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Ils ne gardèrent point l\'alliance de Dieu, et refusèrent de suivre ses lois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'et ils oublièrent ses hauts faits et ses miracles, dont Il les rendit témoins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Sous les yeux de leurs pères, Il fit des miracles, dans le pays d\'Egypte, aux campagnes de Zoan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Il entrouvrit la mer et les fit passer, et Il fit tenir les eaux comme une digue;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'et Il les guidait le jour par la nuée, et toute la nuit, à la clarté de la flamme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Il fendit les rochers au désert, et les abreuva comme de flots abondants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'et Il fit sortir des ruisseaux du rocher, et couler les eaux comme des torrents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Mais ils continuèrent encore à pécher contre Lui, à être rebelles au Très-haut dans le désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'Et ils tentèrent Dieu dans leur cœur, demandant d\'être nourris selon leur fantaisie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'et ils parlèrent contre Dieu, ils dirent: « Dieu pourra-t-Il dresser une table au désert?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Voici, Il frappa le rocher, et l\'eau a ruisselé, et les fleuves ont coulé; pourra-t-Il aussi donner du pain et fournir de la viande à son peuple? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Et à l\'ouïe de ces propos, l\'Éternel s\'irrita, et un feu s\'alluma contre Jacob, et la colère s\'éleva contre Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'parce qu\'ils n\'avaient pas foi en Dieu, et ne comptaient pas sur son secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Cependant Il commanda aux nuées d\'en haut, et Il ouvrit les portes des Cieux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'et Il fit pleuvoir sur eux la manne pour les nourrir, et Il leur donna le froment céleste;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'ils mangèrent chacun le pain des princes; Il leur envoya de quoi se nourrir à rassasiement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Il fit lever dans le ciel le vent d\'Orient, et amena par sa puissance le vent du Midi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'et Il fit pleuvoir sur eux la chair comme de la poussière et des oiseaux ailés, comme le sable des mers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'et Il les fit tomber au milieu de leur camp, tout autour de leurs habitations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Alors ils mangèrent et se rassasièrent pleinement, Il avait ainsi satisfait leur désir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Ils ne s\'étaient pas encore dépris de leur désir, ils avaient encore leur aliment dans leur bouche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'que la colère de Dieu s\'éleva contre eux, et qu\'il fit un massacre parmi leurs hommes forts, et qu\'il coucha par terre la jeunesse d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Néanmoins ils péchèrent encore, et ne crurent point à ses miracles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Et d\'un souffle Il consuma leurs jours, et leurs années par une ruine soudaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Lorsqu\'il les tuait, ils s\'enquéraient de Lui, et revenaient, et cherchaient Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'et se rappelaient que Dieu était leur rocher, et Dieu, le Très-haut, leur rédempteur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'mais leurs bouches le trompaient, et leurs langues lui mentaient,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'et leur cœur ne Lui fut pas fermement uni, et ils ne furent pas fidèles à son alliance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Toutefois, dans sa clémence, Il pardonna le crime et ne les détruisit pas; et souvent Il contint son courroux, et ne donna pas cours à toute sa colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Il se souvint donc qu\'ils étaient des mortels, un souffle qui s\'en va, et ne revient plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Que de fois ils Lui furent rebelles au désert, et ils L\'irritèrent dans la solitude!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Et de nouveau ils tentèrent le Seigneur, et provoquèrent le Saint d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Ils ne pensaient plus à ce qu\'avait fait son bras, le jour où Il les délivra de l\'ennemi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'lorsque en Egypte Il opéra des prodiges, et des miracles dans les campagnes de Zoan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Il changea ses fleuves en sang, et de leurs eaux ils ne purent plus boire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Parmi eux Il envoya des moucherons qui les dévorèrent, et des grenouilles qui furent leur fléau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'et Il livra leur récolte à l\'insecte vorace, et le fruit de leur labeur à la sauterelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Il fit périr leurs vignes par la grêle, et leurs sycomores par les fourmis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'et Il livra leur bétail à la grêle, et leurs troupeaux à la foudre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Il lança contre eux le feu de sa colère, le courroux, la fureur et l\'angoisse, une cohorte d\'anges des malheurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Il donna carrière à son courroux, ne refusa point leur âme à la mort, mais livra leur vie en proie à la peste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'et frappa tous les premiers-nés en Egypte, et les prémices de la vigueur dans les tentes de Cham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Il fit ainsi partir son peuple comme des brebis, et le guida comme un troupeau dans le désert,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'et le mena sûrement, et ils furent sans crainte, et la mer recouvrit leurs adversaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Et Il les fit arriver dans ses limites saintes, à cette montagne que sa droite conquit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'et devant eux Il chassa les nations, et les leur fit échoir en portion d\'héritage, et Il établit dans leurs tentes les tribus d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Mais, rebelles ils tentèrent Dieu, le Très-haut, et ne gardèrent point ses commandements;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'ils furent déserteurs et perfides, comme leurs pères; ils tournèrent comme un arc trompeur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'ils excitèrent sa colère par leurs hauts-lieux, et sa jalousie par leurs idoles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Dieu l\'entendit, et fut irrité, et conçut pour Israël une grande aversion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Alors Il quitta la demeure de Silo, la tente qu\'il avait dressée parmi les hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'et Il laissa sa gloire s\'en aller captive, et sa majesté tomber aux mains de l\'ennemi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'et Il livra son peuple à l\'épée, et contre son héritage Il fut irrité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'le feu dévora ses jeunes hommes, et ses vierges ne furent plus chantées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'ses prêtres succombèrent à l\'épée, et ses veuves ne pleurèrent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Alors, comme celui qui a dormi, le Seigneur s\'éveilla, tel que le héros dont le vin avait triomphé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'et Il repoussa ses ennemis, et les chargea d\'une honte éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Cependant Il répudia la tente de Joseph, et n\'élut point la tribu d\'Ephraïm;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'et Il élut la tribu de Juda, la montagne de Sion qu\'il aimait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Et Il affermit son sanctuaire à l\'égal des Cieux, à l\'égal de la terre, dont Il posa les fondements éternels;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'et Il élut David, son serviteur, et le tira des parcs des troupeaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Il lui fit quitter les brebis qui allaitent, pour être le pasteur de Jacob, son peuple, et d\'Israël, son héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Et il en fut le pasteur avec un cœur pur, et d\'une main prudente il le conduisit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Cantique d\'Asaph. O Dieu! les nations ont envahi ton héritage, profané ton saint temple, mis Jérusalem en ruines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Elles ont livré les cadavres de tes serviteurs en proie aux oiseaux des Cieux, la chair de tes bien-aimés aux bêtes de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Elles ont versé leur sang, comme de l\'eau, autour de Jérusalem, et il n\'y eut point de sépulture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Nous sommes l\'opprobre de nos voisins, le jouet et la risée des contrées d\'alentour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Jusques à quand, Éternel, ne cesseras-tu d\'être irrité, ta fureur s\'embrasera-t-elle comme un feu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Epanche ton courroux sur les nations qui t\'ignorent, et sur les royaumes qui n\'invoquent pas ton nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Car on a dévoré Jacob, et dévasté sa demeure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Ne nous garde pas la mémoire des crimes du passé! Hâte-toi de nous faire sentir tes compassions! car nous sommes très misérables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Sois-nous en aide, ô Dieu, notre Sauveur, pour l\'honneur de ton nom! Et sauve-nous et pardonne nos fautes, pour l\'amour de ton nom!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Pourquoi faut-il que les nations disent: « Où est leur Dieu? » Que parmi les nations, à nos yeux, éclate la vengeance du sang de tes serviteurs qui fut répandu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Que devant toi parviennent les soupirs des captifs, par le pouvoir de ton bras sauve les enfants de la mort!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Reverse à nos voisins sept fois dans leur sein les outrages dont ils t\'outragèrent, Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Et nous, ton peuple, le troupeau dont tu es le pasteur, nous te rendrons grâces éternellement, et d\'âge en âge nous redirons tes louanges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Au maître chantre. En schoschanim-edouth. Cantique d\'Asaph. Prête l\'oreille, berger d\'Israël, toi qui conduis Joseph, comme un troupeau; toi dont les Chérubins portent le trône, apparais! Prête l\'oreille, berger d\'Israël, toi qui conduis Joseph, comme un troupeau; toi dont les Chérubins portent le trône, apparais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Devant Ephraïm et Benjamin et Manassé donne essor à ta puissance, et viens à notre aide!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'O Dieu, rétablis-nous, et fais luire ta face, et nous serons sauvés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Éternel, Dieu des armées, jusques à quand t\'irriteras-tu, quand ton peuple prie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Tu lui fais manger un pain trempé de larmes, et boire avec larmes une portion mesurée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Tu fais de nous une proie que nos voisins se disputent, et nos ennemis nous tournent en dérision.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Dieu des armées, rétablis-nous, et fais luire ta face, et nous serons sauvés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'De l\'Egypte tu retiras une vigne, tu expulsas les nations, et tu la plantas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'tu déblayas le sol devant elle, et elle poussa des racines, et remplit le pays;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'les montagnes furent couvertes de son ombre, et ses pampres égalèrent les cèdres de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'elle étendit ses rameaux jusques à la mer, et ses jets jusques au Fleuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Pourquoi as-tu abattu ses murailles, pour que tous les passants la vendangent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'De la forêt le sanglier vient la ravager, et les bêtes des champs, y brouter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Ah! reviens, Dieu des armées, regarde des Cieux et vois, et visite cette vigne!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Protège ce que ta main a planté, et le fils que tu t\'es choisi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Elle est brûlée par le feu, elle est coupée: ils périssent à ton air menaçant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Protège de ta main l\'homme, ouvrage de ta droite, le fils de l\'homme que tu t\'es choisi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Alors nous ne te quitterons pas; rends-nous la vie, et nous invoquerons ton nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Éternel, Dieu des armées, rétablis-nous, fais luire ta face, et nous serons sauvés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Au maître chantre. En githith. D\'Asaph. Faites entendre vos hymnes au Dieu qui est notre force, et vos cris d\'allégresse au Dieu de Jacob!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Elevez vos chants, et faites résonner la cymbale, et la harpe harmonieuse avec le luth!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'C\'est la lune nouvelle, sonnez de la trompette! c\'est la lune dans son plein, notre jour de fête!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Car tel est l\'ordre donné à Israël, l\'institution du Dieu de Jacob:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Il en dressa le statut en Joseph, quand Il se mit en marche contre le pays d\'Egypte. « J\'entends une voix que je ne reconnais pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Je déchargeai son épaule du fardeau, et ses mains ne durent plus porter les paniers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'Dans l\'angoisse tu m\'invoquas, et je te sauvai, je t\'exauçai, enveloppé du tonnerre, et je t\'éprouvai aux eaux de la querelle. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Ecoute, mon peuple, que je te somme! O Israël, si tu voulais m\'écouter!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Qu\'il n\'y ait chez toi point de Dieu étranger, et n\'adore pas les dieux du dehors!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Je suis l\'Éternel, ton Dieu, qui t\'ai ramené de la terre d\'Egypte. Ouvre ta bouche, je veux la remplir!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Mais mon peuple n\'a point écouté ma voix, et Israël ne m\'a point obéi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Alors je l\'abandonnai à l\'obstination de son cœur; ils suivirent leurs propres conseils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'O si mon peuple voulait m\'écouter, et Israël, marcher dans mes voies!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Bientôt je ferais plier leurs ennemis, et contre leurs oppresseurs je tournerais ma main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Ceux qui haïssent l\'Éternel, dissimuleraient devant lui, et eux, ils auraient un bonheur éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Dieu les nourrirait de la moelle du froment, et du miel des rochers je te rassasierais! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Cantique d\'Asaph. Dieu prend séance dans l\'assemblée divine, et au milieu des Dieux Il rend la justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, '« Jusques à quand serez-vous des juges pervers, et tiendrez-vous le parti des impies? (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Faites droit aux petits et aux orphelins, rendez justice à l\'affligé et au pauvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Libérez les petits et les indigents, arrachez-les de la main des impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Ils n\'ont ni sagesse, ni intelligence, ils marchent dans les ténèbres; toutes les bases de la terre sont ébranlées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'J\'ai dit: Vous êtes des Dieux, et tous, des fils du Très-haut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Cependant vous mourrez, comme des humains, et vous tomberez, aussi bien que tel d\'entre les princes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Lève-toi, ô Dieu, juge la terre, car tous les peuples sont ta propriété!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Cantique d\'Asaph. O Dieu, ne garde pas le silence, ne sois point sourd, ne te tiens pas en repos, ô Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Car voici, tes ennemis sont en rumeur, et ceux qui te haïssent, lèvent la tête;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'ils trament contre ton peuple un astucieux complot, et se concertent contre tes protégés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Ils disent: « Sus! exterminons-les du milieu des peuples, que le nom d\'Israël ne soit plus rappelé désormais! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Car ils se concertent d\'un commun accord, ils font alliance contre toi:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'ce sont les tentes d\'Edom et des Ismaëlites, Moab et les Hagariens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Gebal et Amman et Amalek, la Philistie avec les habitants de Tyr;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Assur aussi s\'unit à eux, et prête son bras aux enfants de Lot. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Traite-les comme Madian, comme Sisera, comme Jabin au torrent de Kison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'qui furent défaits à En-Dor, et fumèrent le sol!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Rends-les, rends leurs princes pareils à Horeb et à Zéeb, et tous leurs rois, à Zébah et Tsalmunah;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'car ils disent: « Rendons-nous maîtres des demeures de Dieu! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Mon Dieu, assimile-les au tourbillon, à la balle livrée au vent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'au feu qui dévore la forêt, et à la flamme qui embrase la montagne!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Ainsi, poursuis-les de ta tempête, et terrifie-les par ton ouragan!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Couvre leur visage de honte, afin qu\'ils s\'enquièrent de ton nom, Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Qu\'ils soient confondus et terrifiés pour toujours, et qu\'ils périssent avec ignominie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'afin qu\'ils sachent que ton nom, Etemel, ton nom seul est souverain sur toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Au maître chantre. En githith. Cantique des fils de Coré. Que tes demeures sont aimables, Éternel des armées!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Mon cœur se pâme, il languit après les parvis de l\'Éternel; mon âme et ma chair crient au Dieu vivant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Le passereau même se trouve une demeure, et l\'hirondelle un nid, où ils déposent leur couvée, près de tes autels, Éternel des armées, mon Roi et mon Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Heureux les habitants de ta maison! Ils te louent encore. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Heureux l\'homme dont tu es le soutien, et que son cœur porte à s\'acheminer vers toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Traversant la vallée des pleurs, il la trouve pour lui arrosée de fontaines, et la pluie d\'automne la couvre d\'abondance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Il chemine, et ses forces augmentent: il se présente enfin devant Dieu en Sion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Éternel, Dieu des armées, écoute ma prière! Prête l\'oreille, Dieu de Jacob! (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'O notre bouclier, regarde, ô Dieu, abaisse un regard sur la face de ton Oint!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Car mieux vaut un jour dans tes parvis, que mille autres; j\'aime mieux me tenir au seuil de la maison de mon Dieu, que d\'habiter les tentes de l\'impiété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Car l\'Éternel Dieu est un soleil et un bouclier, l\'Éternel donne grâce et magnificence, ne refuse aucun bien à qui suit la droiture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Éternel des armées, heureux l\'homme qui se confie en toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Au maître chantre. Cantique des fils de Coré. Tu as été, Éternel, propice à ton pays, tu as ramené les captifs de Jacob,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'pardonné les crimes de ton peuple, effacé tous ses péchés; (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'tu as déposé toute la colère, éteint le feu de ton courroux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'rétablis-nous, ô notre Dieu sauveur, et fais cesser ta fureur envers nous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Seras-tu donc toujours irrité contre nous, feras-tu durer ta colère d\'âge en âge?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Ne veux-tu pas nous redonner la vie, pour que tu sois la joie de ton peuple?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Fais-nous, ô Éternel, jouir de ta faveur, et nous accorde ton salut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Je veux écouter ce que dit Dieu, l\'Éternel. Oui, Il parle de salut à son peuple, à ses bien-aimés; mais qu\'ils ne retournent pas à la folie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Oui, son salut est près de ceux qui le craignent, la gloire reviendra habiter notre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'L\'amour et la fidélité se rencontrent, la justice et la paix s\'embrassent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'la fidélité germe de la terre, et la justice regarde des Cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'L\'Éternel donne aussi les biens, et notre terre rend ses récoltes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'La justice marche en sa présence, et maintient ses pas dans la voie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Prière de David. Éternel, prête l\'oreille, exauce-moi! car je suis misérable et pauvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Garde mon âme, car je suis fidèle! Sois en aide, toi, mon Dieu, à ton serviteur qui se confie en toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Prends pitié de moi, Seigneur, car je t\'implore tous les jours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Réjouis l\'âme de ton serviteur, car à toi, Seigneur, j\'élève mon âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Car, Seigneur, tu es bon et clément, et riche en amour pour tous ceux qui t\'invoquent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Éternel, prête l\'oreille à ma prière, sois attentif à mes supplications.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Dans mon jour de détresse, je t\'implore, parce que tu m\'exauces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Entre les dieux nul n\'est pareil à toi, Seigneur, et rien n\'égale tes œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Que tous les peuples que tu as faits, viennent se prosterner devant toi, Seigneur, et honorer ton nom!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Car tu es grand, tu opères des miracles, seul tu es Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Éternel, montre-moi ta voie, pour que je marche dans ta vérité! Concentre mon cœur dans la crainte de ton nom!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Je veux te louer, Seigneur, mon Dieu, de tout mon cœur, et honorer éternellement ton nom!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'car ta miséricorde est grande envers moi; tu arraches mon âme du fond des Enfers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'O Dieu! des superbes s\'élèvent contre moi, et une bande de furieux attente à ma vie; et ils n\'ont pas les yeux tournés vers toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Cependant, Seigneur, tu es un Dieu miséricordieux et bon lent à t\'irriter, et riche en grâce et en fidélité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Tourne tes regards vers moi, et prends pitié de moi! Accorde ta protection à ton serviteur, et sois en aide au fils de ta servante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Opère en ma faveur un signe pour me sauver! Que mes ennemis le voient, et soient confondus! car, Éternel, tu m\'assistes et me consoles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Cantique des fils de Coré. Il a sa résidence sur les montagnes saintes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'l\'Éternel aime les portes de Sion plus que toutes les demeures de Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Il est dit de toi des choses glorieuses, Cité de Dieu! (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, '« Je me vois reconnu par l\'Egypte et Babel; voici, la Philistie, et Tyr avec l\'Ethiopie, les uns et les autres reçoivent dans Sion une [nouvelle] naissance. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Et il est dit de Sion: « Des hommes et des hommes y reçoivent une [nouvelle] naissance, et Lui-même, le Très-haut, la consolide. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'L\'Éternel énumère les peuples en les inscrivant: « Ceux-ci reçoivent là une [nouvelle] naissance. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Et les chantres, et les danseurs [s\'écrient:] « Toutes mes sources sont en toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Cantique des fils de Coré. Au maître chantre. A chanter avec les luths. Hymne de Héman Esrahite. Éternel, mon Dieu sauveur, je crie à toi et le jour et la nuit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'qu\'à toi parvienne ma prière; prête l\'oreille à ma supplication!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Car mon âme est rassasiée de malheur, et ma vie penche vers les Enfers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Je suis assimilé à ceux qui descendent dans la fosse, je suis comme un homme sans force;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'ma couche est entre les morts, je suis tel que les morts gisants dans le tombeau, auxquels tu ne penses plus, et qui ne sont plus à portée de ta main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Tu m\'as jeté dans une fosse profonde, dans des ténèbres, dans des abîmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Ton courroux pèse sur moi, et de tous tes flots tu m\'as accablé. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Tu as éloigné de moi ceux que je connais, tu m\'as rendu pour eux un objet d\'horreur; enveloppé, je ne trouve point d\'issue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Mes yeux fondent par l\'effet du malheur; Éternel, je t\'invoque chaque jour, et je tends mes mains vers toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Pour les morts feras-tu des miracles? Les ombres se lèveront-elles pour te louer? (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Dans le tombeau parle-t-on de ta grâce, et de ta fidélité, dans le séjour de la mort?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Dans les ténèbres tes miracles sont-ils remarqués, et ta justice, dans la région de l\'oubli?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Je t\'implore donc, Éternel, et dès le matin ma prière te prévient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Éternel, pourquoi me rejettes-tu, et me caches-tu ta face?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Je suis malheureux et mourant dès ma jeunesse, je subis les terreurs et je suis éperdu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Ton courroux m\'assaille, tes frayeurs m\'anéantissent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'm\'enveloppent, comme des eaux, tout le jour, me cernent toutes à la fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Tu as éloigné de moi amis et compagnons, et ceux que je connais, me sont invisibles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Hymne de Ethan Esrahite. Je veux chanter à jamais les grâces de l\'Éternel, et d\'âge en âge de ma bouche publier Ta fidélité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Car je me dis: La grâce est édifiée pour jamais, le ciel est la base que Tu donnes à ta fidélité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, '« J\'ai fait une alliance en faveur de mon élu, je l\'ai juré à David, mon serviteur:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'J\'affermirai ta race à jamais, et je fonderai ton trône pour tous les âges. » (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, '« Et les Cieux, Éternel, célèbrent tes merveilles, et disent ta fidélité dans l\'assemblée des Saints.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Car, dans les lieux éthérés, qui s\'égale à l\'Éternel? qui ressemble à l\'Éternel, parmi les Fils de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'à ce Dieu, redouté dans la vaste société des Saints, et plus formidable que tous ceux qui L\'entourent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Éternel, Dieu des armées, qui est comme toi puissant, ô Dieu? Et ta fidélité t\'environne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Tu domines l\'orgueil de la mer; quand ses flots se soulèvent, tu les apaises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Tu as écrasé l\'Egypte d\'un coup mortel, et de ton bras puissant dissipé tes ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'A toi sont les Cieux, et à toi la terre; c\'est toi qui as fondé le monde et ce qu\'il enserre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Tu as créé l\'Aquilon et le Midi; le Thabor et l\'Hermon se réjouissent à ton nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Tu as un bras armé de vigueur, ta main est forte, ta droite élevée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'La justice et l\'équité sont la base de ton trône, la grâce et la vérité marchent devant ta face.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Heureux le peuple qui connaît l\'appel de la trompette! Éternel, il marche à la clarté de ta face;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'à ton nom il se réjouit toujours, et il se glorifie de ta justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Car tu es sa glorieuse parure; et par ta faveur tu nous fais porter la tête levée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Car c\'est de l\'Éternel que vient notre bouclier, et du Saint d\'Israël que vient notre Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Alors tu parlas en vision à ton bien-aimé, et tu dis: « J\'ai prêté secours à un héros, et suscité un adolescent du milieu du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'J\'ai trouvé David, mon serviteur, et je l\'ai oint de mon huile sainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Ma main lui est assurée, et mon bras le soutiendra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'L\'ennemi ne le surprendra pas, et le méchant ne l\'humiliera point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Je déferai devant lui ses adversaires, et je battrai ses ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Et ma fidélité et ma grâce seront avec lui, et à mon nom il lèvera la tête;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'et je mettrai sa main sur la mer, et sa droite sur les fleuves.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Il m\'invoquera ainsi: « Tu es mon père, mon Dieu, et mon rocher sauveur! » –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Bien plus, je l\'instituerai mon premier-né, le plus éminent des rois de la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Je lui garderai ma grâce éternellement, et mon alliance pour lui sera perpétuelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Je rendrai sa race éternelle, et je donnerai à son trône la durée des Cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Si ses fils abandonnent ma loi, et ne se dirigent pas selon mes jugements,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 's\'ils violent mes commandements, et n\'observent pas mes préceptes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'Je punirai de la verge leur désobéissance, et de fléaux, leur crime;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'mais je ne lui retirerai point ma faveur, et ne démentirai point ma fidélité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'je ne violerai point mon alliance, et ne changerai point la parole émise par mes lèvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Je l\'ai juré une fois par ma sainteté: Jamais envers David je ne serai menteur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'sa race subsistera éternellement, et son trône, comme le soleil, subsistera devant moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'comme la lune, pour jamais il est consolidé; et le témoin qui est dans la nue, est véridique. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Et Tu nous as rejetés, nous as répudiés, tu t\'es irrité contre ton Oint;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'tu as méprisé l\'alliance faite avec ton serviteur; tu as souillé, fait tomber son diadème en terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'tu as abattu toutes ses murailles, mis ses boulevards en ruines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Tous les passants le pillent, il est l\'opprobre de ses voisins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Tu as exalté la droite de ses oppresseurs, réjoui tous ses ennemis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'et tu as fait céder le tranchant de son glaive, et tu ne l\'as pas soutenu dans le combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Tu as réduit sa splendeur, et précipité son trône sur la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'tu as abrégé les jours de sa jeunesse, tu l\'as couvert d\'ignominie. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Éternel, jusques à quand te cacheras-tu toujours, et ton courroux sera-t-il enflammé comme un feu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Pense à moi! qu\'est-ce que la vie? Pour quel néant tu as créé les enfants des humains!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Quel homme vit, et ne voit pas la mort? dégage son âme de la main des Enfers? (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Où sont tes grâces premières, Seigneur, qu\'en ta fidélité tu promis par serment à David?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Souviens-toi, Seigneur, de l\'opprobre de tes serviteurs; songe que je porte en mon cœur tous ces peuples nombreux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'que tes ennemis insultent, Éternel, insultent aux pas de ton Oint! \\csp{');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Béni soit l\'Éternel a jamais! Ainsi soit-il! Oui! Ainsi soit-il!}');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Prière de Moïse, homme de Dieu. Éternel, tu as été notre refuge d\'une génération à l\'autre génération;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'avant que les montagnes fussent enfantées, et que tu eusses engendré la terre et le monde, oui, de l\'éternité à l\'éternité tu es, ô Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Tu fais rentrer l\'homme dans la poudre, et tu dis: « Rentrez-y, enfants des hommes! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Car mille ans sont à tes yeux comme le jour d\'hier, quand il est passé, et comme une veille dans la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Tu les emportes, ils sont un rêve; le matin, comme l\'herbe, l\'homme lève;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'le matin il fleurit et lève; le soir il est tranché, et il sèche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Car nous sommes consumés par ta colère, et par ton courroux nous sommes terrassés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Tu produis nos péchés à ta vue, et nos secrets à la lumière de ta face.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Car tous nos jours fuient devant ta fureur, nous perdons nos années, comme une pensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Les jours de notre vie, ce sont soixante-dix années, et, pour les forts, quatre-vingts années; et ce qui fait leur orgueil est peine et néant; car il passe vite, et nous nous envolons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Qui connaît la puissance de ta colère, et mesure ton courroux sur la crainte qui t\'est due?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Apprends-nous à faire un tel compte de nos jours, que nous acquérions un cœur sage!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Reviens, Éternel! Jusques à quand?... \\ Et prends pitié de tes serviteurs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Rassasie-nous bientôt de ta grâce, et nous serons triomphants et joyeux durant tous nos jours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Donne-nous de la joie pour le temps que tu nous affligeas, pour les années où nous connûmes le malheur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Rends ton action visible à tes serviteurs, et ta majesté à leurs enfants!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Que la faveur du Seigneur, notre Dieu, soit sur nous! Et consolide pour nous l\'œuvre de nos mains, oui, consolide l\'œuvre de nos mains!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Assis dans l\'asile du Très-haut, on repose à l\'ombre du Tout-puissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Je dis à l\'Éternel: O mon refuge et mon fort, ô mon Dieu en qui je me confie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Oui, Il te dégage des rets de l\'oiseleur, de la peste meurtrière;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Il te couvre de ses plumes, et sous ses ailes tu trouves un abri; sa vérité est un bouclier et un rempart.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Tu n\'as pas à redouter l\'épouvante de la nuit, ni la flèche qui vole durant le jour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'ni la peste qui s\'avance dans les ténèbres, ni la contagion qui sévit au milieu du jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Que mille hommes tombent à ton côté, et des myriades à ta droite, tu es hors des atteintes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'De tes yeux seulement tu en es spectateur, et tu assistes à la rétribution des impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'C\'est, ô Éternel, que tu es mon refuge; tu t\'es choisi le Très-baut pour appui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Le malheur n\'arrive point jusqu\'à toi, et la plaie n\'approche point ta tente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Car Il donne pour toi l\'ordre à ses anges de te garder en toutes tes voies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Ils te porteront sur leurs bras, de peur que ton pied ne heurte contre la pierre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Tu marcheras sur le lion et la vipère, tu fouleras le lionceau et le dragon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, '« Puisqu\'il s\'attache à moi, je veux le sauver, le mettre en lieu sûr, puisqu\'il connaît mon nom,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Il m\'invoque, et je l\'exauce; je suis près de lui dans la détresse, je le délivrerai et je le glorifierai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'De longs jours je le rassasierai, et je lui ferai voir mon secours. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Cantique pour le jour du repos. Il est beau de louer l\'Éternel, et de chanter ton nom, ô Très-haut!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'le matin de redire ta faveur, et ta fidélité durant les nuits,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'aux sons du décachorde et du luth, aux accords de la harpe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Car tu me réjouis, Éternel, par tes hauts faits, et je suis ravi des ouvrages de tes mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Que tes œuvres sont grandes, ô Éternel, et tes pensées profondes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'L\'homme stupide l\'ignore, et l\'insensé ne le comprend pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Que les impies lèvent comme la plante, et que tous les méchants fleurissent, c\'est pour être détruits à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Et toi, tu es éternellement élevé, ô Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Car voici, tes ennemis, Seigneur, voici, tes ennemis périssent, tous ceux qui font le mal, sont dissipés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Mais tu relèves mon front, comme celui des taureaux, je suis arrosé d\'une huile nouvelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'mes adversaires réjouissent mes regards, et la chute de mes méchants ennemis flatte mon oreille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Le juste verdit comme le palmier, il croît comme un cèdre au Liban.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Planté dans la maison de l\'Éternel, il prospère dans les parvis de notre Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'et pousse encore des jets dans la vieillesse même; il est plein de sève, et son feuillage est épais;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'pour proclamer que l\'Éternel est juste, qu\'il est mon rocher, et ne fait rien d\'inique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'L\'Éternel règne, revêtu de majesté; la force est son vêtement, sa ceinture: aussi le monde est ferme et ne chancelle pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Ton trône est ferme dès les anciens jours, tu es depuis l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Les flots élèvent, ô Éternel, les flots élèvent leur voix, les flots élèvent leur murmure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Plus que les voix des eaux immenses, que les vagues magnifiques de la mer, l\'Éternel est magnifique dans les hautes régions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Tes témoignages sont parfaitement sûrs. La sainteté sied à ta maison, ô Éternel, pour la durée des temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Dieu des vengeances, Éternel, Dieu des vengeances, apparais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Lève-toi, juge de la terre, rends aux orgueilleux un salaire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Jusques à quand les impies, Éternel, jusques à quand les impies seront-ils triomphants?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Ils profèrent, ils vomissent des discours violents, et tous les méchants se glorifient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Éternel, ils écrasent ton peuple, et humilient ton héritage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'ils égorgent la veuve et l\'étranger, et mettent à mort les orphelins;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'puis ils disent: « L\'Éternel ne le voit pas, et le Dieu de Jacoh n\'y prend pas garde. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Prenez-y garde, vous, les plus stupides des hommes! et vous, insensés, quand aurez-vous la sagesse?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Celui qui a planté l\'oreille, n\'entendrait-Il pas? Celui qui a formé l\'œil, ne verrait-Il pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Celui qui fait la leçon aux peuples, ne punirait-Il pas, lui qui instruit l\'intelligence de l\'homme?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'L\'Éternel connaît les pensées des hommes; Il sait qu\'elles sont un néant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Heureux l\'homme que tu instruis, Éternel, et que tu enseignes par tes leçons,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'pour le calmer en face des jours mauvais, jusqu\'à ce que la fosse soit creusée à l\'impie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Car l\'Éternel ne délaisse point son peuple, et n\'abandonne point son héritage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'car les jugements rentreront dans la justice, et tous ceux qui ont le cœur droit, la suivront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Qui est-ce qui prend mon parti contre les méchants? Qui est-ce qui m\'assiste contre les artisans du mal?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Si Dieu n\'était mon aide, bientôt mon âme habiterait le séjour du silence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Si je dis: Mon pied chancelle; alors ta grâce, Éternel, vient me soutenir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Dans les mille anxiétés de mon cœur, tes consolations restaurent mon âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Te ferais-tu l\'allié d\'une tyrannie funeste qui complote la ruine en dépit de la loi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Ils se liguent contre la vie du juste, et ils condamnent le sang innocent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Mais l\'Éternel est mon rempart, et mon Dieu, mon rocher de refuge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Il leur paiera le salaire de leur crime, et par leur malice même Il les détruira, Il les détruira, l\'Éternel, notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Venez, élevons nos chants à l\'Éternel, et nos cris d\'allégresse à notre rocher sauveur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Présentons-nous à lui avec des louanges, offrons-lui nos joyeux cantiques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Car l\'Éternel est un grand Dieu, et un Roi grand par dessus tous les dieux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'Il tient en sa main l\'intérieur de la terre, et les trésors des montagnes sont à lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'la mer est à lui, Il l\'a faite, et ses mains ont formé les continents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Venez, adorons et nous prosternons, et nous agenouillons devant l\'Éternel, notre créateur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Car Il est notre Dieu, et nous le peuple dont Il est le pasteur, le troupeau conduit par sa main. Puissiez-vous aujourd\'hui écouter sa voix!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, '« N\'endurcissez pas votre cœur, comme aux Eaux de la querelle, et dans les jours de la Tentation au désert,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'où vos pères me tentèrent, et me mirent à l\'épreuve, quoiqu\'ils vissent mes hauts faits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Quarante années j\'eus cette race en dégoût, et je dis: « C\'est un peuple qui a le cœur égaré, et qui ne connaît pas mes voies. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Là je fis serment dans ma colère qu\'ils n\'entreraient point dans mon repos. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Chantez à l\'Éternel un cantique nouveau, chantez à l\'Éternel, vous toutes les contrées!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Chantez à l\'Éternel, bénissez son nom, annoncez son salut de jour en jour!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Racontez sa gloire parmi les nations, et ses merveilles parmi tous les peuples!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Car Dieu est grand et digne d\'une grande louange; Il est plus redoutable que tous les dieux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'car tous les dieux des peuples sont des idoles, et l\'Éternel a fait les Cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Devant sa face c\'est splendeur et majesté, gloire et magnificence, dans son Sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Tribus des peuples, rendez à l\'Éternel, rendez à l\'Éternel l\'honneur et la louange!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Rendez à l\'Éternel l\'honneur dû à son nom! d Apportez des offrandes, et entrez dans ses parvis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Adorez l\'Éternel avec une pompe sainte! Tremblez devant lui, vous toutes les contrées!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Dites parmi les peuples: « L\'Éternel règne; aussi le monde est ferme et ne chancelle point. Il juge les nations avec justice. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Que les Cieux se réjouissent, et que la terre tressaille; que la mer s\'émeuve avec tout ce qu\'elle enserre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'que les campagnes s\'égaient avec tout ce qui les couvre; qu\'ainsi les arbres des forêts frémissent tous d\'allégresse');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'au devant de l\'Éternel! Car Il vient, car il vient pour juger la terre. Il jugera le monde avec justice, et les peuples, selon sa vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'L\'Éternel règne; que la terre tressaille, que les îles nombreuses se réjouissent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Les nuées et l\'obscurité l\'environnent, la justice et l\'équité sont la base de son trône.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Devant lui le feu s\'avance, et consume ses ennemis de toutes parts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Ses éclairs illuminent le monde: la terre le voit, et tremble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Les montagnes, comme delà cire, fondent à l\'aspect de l\'Éternel, à l\'aspect du Seigneur de toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Les Cieux proclament sa justice, et tous les peuples contemplent sa magnificence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Ils sont confondus tous ceux qui servent les idoles, qui font gloire des faux dieux: devant Lui tous les dieux se prosternent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Sion l\'entend, et se réjouit, et les filles de Juda sont dans l\'allégresse, à cause de tes jugements, ô Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Car tu es, ô Éternel, le Très-haut qui domine la terre, tu es très élevé au-dessus de tous les dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Vous qui aimez l\'Éternel, haïssez le mal! Il garde les âmes de ses saints, et Il les sauve de la main des impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'La lumière se lève pour le juste, et la joie pour ceux qui ont le cœur droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Justes, faites de l\'Éternel votre joie, et louez son saint nom!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Cantique. Chantez à l\'Éternel un cantique nouveau! car Il a fait des choses merveilleuses, aidé de sa droite et du bras de sa sainteté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'L\'Éternel a montré son secours; et aux yeux des peuples Il a révélé sa justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Il s\'est souvenu de sa grâce et de sa fidélité envers la maison d\'Israël; toutes les extrémités de la terre ont vu le secours de notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Terres, élevez toutes à l\'Éternel vos acclamations! faites retentir vos cris de joie et vos accords!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Célébrez l\'Éternel avec la harpe, avec la harpe et la voix des chants!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Au bruit des clairons et des trompettes, poussez des cris de joie devant le Roi, l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Que la mer s\'émeuve avec ce qu\'elle enserre, le monde et ceux qui l\'habitent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'que les fleuves battent des mains, qu\'en même temps les montagnes jubilent');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'devant l\'Éternel! Car Il vient pour juger la terre. Il jugera le monde avec justice, et les peuples avec équité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'L\'Éternel règne, les peuples tremblent; Il est assis sur les Chérubins, la terre est ébranlée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'L\'Éternel est grand en Sion, et élevé au-dessus de tous les peuples:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'qu\'ils chantent Ton nom grand et redoutable, Il est saint!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'et la force du Roi qui aime la justice! Tu as fondé l\'équité, et créé en Jacob la justice et le droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Exaltez l\'Éternel, notre Dieu, et vous prosternez sur le marchepied de son trône! Il est saint!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Moïse et Aaron, ses Lévites, et Samuel qui invoquait son nom, implorèrent l\'Éternel, et Il les exauça.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Il leur parla dans la colonne de nuée; ils gardèrent ses commandements, et l\'ordonnance qu\'il leur avait donnée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Éternel, notre Dieu, tu les as exaucés; tu fus pour eux un Dieu qui pardonne, et un Dieu vengeur, à cause de leurs méfaits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Exaltez l\'Éternel, notre Dieu, et prosternez-vous sur sa sainte montagne! Car Il est saint, l\'Éternel, notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Cantique de louange. Elevez à l\'Éternel vos cris de joie, vous tous, habitants de la terre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Servez l\'Éternel avec allégresse, paraissez devant sa face avec des acclamations!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Sachez que l\'Éternel est Dieu! C\'est lui qui nous a faits, et non pas nous-mêmes, nous sommes son peuple, et le troupeau de sa pâture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Entrez dans ses Portes en lui rendant grâces, et dans ses parvis, en le louant! Rendez-lui grâces, célébrez son nom!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Car l\'Éternel est bon, sa grâce demeure pour jamais, et sa fidélité, pour tous les âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Cantique de David. Je vais chanter la bonté et la droiture; c\'est toi, Éternel, que je célébrerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Je m\'appliquerai à suivre une voie innocente: ô puissé-je y parvenir! J\'agirai dans l\'innocence du cœur au sein de ma maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Je ne mettrai devant mes yeux aucune chose indigne; je hais la conduite des transgresseurs, sur moi elle n\'aura pas de prise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Que le cœur pervers se tienne loin de moi, je ne veux pas connaître le méchant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Je détruirai celui qui en secret calomnie son ami; je ne supporte pas celui dont l\'œil est altier et le cœur enflé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Mes yeux se porteront vers les hommes sûrs du pays, pour les faire habiter avec moi; ceux qui suivent une voie innocente, seront mes serviteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Il ne s\'assiéra pas dans ma maison celui qui fait des fraudes; celui qui ment ne pourra demeurer sous mes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Chaque jour je veillerai à arracher les impies du pays, à bannir de la cité de l\'Éternel tous ceux qui font le mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Prière d\'un malheureux qui, plongé dans la douleur, épanche sa plainte devant l\'Éternel. Éternel, écoute ma prière, et que ma complainte arrive jusqu\'à toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Ne me cache pas ta face au jour de ma détresse! Penche vers moi ton oreille, quand je t\'invoque! hâte-toi! exauce-moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Car mes jours, comme une fumée, se sont évanouis, et mes os sont embrasés, comme un tison ardent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Frappé comme la plante, mon cœur s\'est flétri; car j\'oublie de manger mon pain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Par l\'effet des sanglots que j\'exhale, mes os s\'attachent à ma chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Je ressemble au pélican du désert, je suis comme le chat-huant des masures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'J\'ai perdu le sommeil, et je suis tel que sur un toit l\'oiseau solitaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Tous les jours mes ennemis m\'outragent; follement animés contre moi, ils emploient mon nom pour maudire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Car je mange la cendre au lieu de pain, et je trempe mon breuvage de mes pleurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'à cause de ton courroux et de ta fureur; car tu m\'as soulevé, et m\'as précipité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Mes jours sont comme les ombres allongées, et je sèche comme l\'herbe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Mais toi, Seigneur, tu es éternellement sur ton trône, et ton nom demeure à travers tous les âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Tu te lèveras, tu prendras pitié de Sion; car il est temps de prendre pitié d\'elle: le moment est venu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Car les vœux de tes serviteurs sont pour les pierres de Sion, et ils sont affectionnés à ses ruines...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Alors les peuples révéreront le nom de l\'Éternel, et tous les rois de la terre, ta majesté!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Oui, l\'Éternel relèvera Sion, Il apparaîtra dans sa gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Il se tourne vers les pauvres qui prient, et Il ne dédaigne pas leur prière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Que ceci soit écrit pour l\'âge futur, et que le peuple qui naîtra, loue l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Car Il regarde du lieu très haut de sa sainteté, l\'Éternel abaisse des Cieux ses regards sur la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'pour entendre les soupirs des captifs, pour libérer les enfants de la mort,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'afin qu\'ils redisent en Sion le nom de l\'Éternel, et ses louanges dans Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'lors du concours universel des peuples, et des royaumes qui viendront servir l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Au milieu du voyage Il a brisé ma force, abrégé mes jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Je dis: Mon Dieu, ne m\'enlève pas à la moitié de mes jours! A travers tous les âges tes années se perpétuent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Jadis tu fondas la terre, et les Cieux sont l\'ouvrage de tes mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Ils périront, mais tu subsisteras; tout entiers ils s\'useront comme un vêtement; tu les changeras comme un habit, et ils changeront;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'mais toi, tu demeures le même, et tes années n\'ont point de terme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Les enfants de tes serviteurs auront leur séjour, et leur race subsistera devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'De David. Mon âme, bénis l\'Éternel, et que tout ce qui est en moi, bénisse son saint nom!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Mon âme, bénis l\'Éternel, et n\'oublie point tous ses bienfaits!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Il pardonne toute ton iniquité; Il guérit toutes tes maladies;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Il rachète ta vie du tombeau; Il te couronne de grâce et de miséricorde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'Il rassasie de biens la fleur de ton âge, et, comme l\'aigle, Il te fait rajeunir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'L\'Éternel rend la justice, et Il fait droit à tous les opprimés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Il découvrit ses voies à Moïse, et aux enfants d\'Israël ses hauts faits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'L\'Éternel est miséricordieux et clément, lent à s\'irriter, et riche en amour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Il n\'est pas toujours accusateur, et son ressentiment n\'est pas éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Il ne nous traita point suivant nos péchés, et ne nous paya point le salaire de nos crimes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'car autant le Ciel s\'élève au-dessus de la terre, autant sa grâce fut immense pour ceux qui le craignent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Autant le Levant est éloigné du Couchant, autant Il a mis nos iniquités à distance de nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Comme un père a compassion de ses enfants, ainsi l\'Éternel eut compassion de ceux qui le craignent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Car Il connaît notre origine, Il se rappelle que nous sommes poudre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'L\'homme!... ses jours sont comme l\'herbe; il fleurit comme une fleur des champs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'qu\'un vent passe sur elle, c\'en est fait, et son sol même ne la reconnaît plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'La grâce de l\'Éternel de l\'éternité à l\'éternité demeure sur ceux qui le craignent, et sa justice, sur les enfants de leurs enfants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'sur ceux qui gardent son alliance, et se rappellent ses commandements, pour les accomplir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'L\'Éternel a établi son trône dans les Cieux, et son empire domine toutes choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Bénissez l\'Éternel, vous ses anges, héros puissants, qui exécutez sa parole, dociles à la voix de sa parole!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Bénissez l\'Éternel, vous toutes ses armées, vous ses ministres, qui faites sa volonté!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Bénissez l\'Éternel, vous toutes ses œuvres, dans tous les lieux de sa souveraineté! Mon âme, bénis l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Mon âme, bénis l\'Éternel! Éternel, mon Dieu, tu es très grand, tu es revêtu de splendeur et de majesté!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Il s\'enveloppe de lumière comme d\'un vêtement, Il déploie les Cieux comme une tenture;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Il élève sur les eaux le haut de sa demeure, Il fait des nuées son char, Il s\'avance sur les ailes du vent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Il fait des vents ses messagers, et ses ministres, du feu enflammé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Il assit la terre sur ses bases, elle est inébranlable pour toujours, pour jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Tu l\'avais couverte de l\'abîme comme d\'un manteau, les eaux se tenaient sur les montagnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'à ta menace elles ont fui, à la voix de ton tonnerre elles ont reculé:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'les montagnes montèrent, les vallées descendirent à la place que tu leur assignas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Tu posas des limites qu\'elles ne franchiraient plus, afin qu\'elles ne vinssent plus recouvrir la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Tu fais jaillir des sources pour former les ruisseaux; ils s\'écoulent entre les montagnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'ils abreuvent toutes les bêtes des champs, les onagres y étanchent leur soif.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Sur leurs bords séjournent les oiseaux du ciel, entre les rameaux ils font entendre leur voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Du haut de sa demeure Il arrose les montagnes, et la terre se rassasie du fruit de tes œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Il fait croître l\'herbe pour les quadrupèdes, et les plantes pour le service de l\'homme, tirant ainsi le pain du sein de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'et le vin qui réjouit le cœur de l\'homme, et, plus que l\'huile, fait resplendir son visage; et le pain qui fortifie le cœur de l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Les arbres de l\'Éternel sont rassasiés, les cèdres du Liban qu\'il a plantés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'où viennent nicher les oiseaux, la cigogne, qui habite les pins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Les hautes montagnes sont pour les bouquetins, et les rochers sont l\'asile des gerboises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Il créa la lune pour marquer les temps; le soleil connaît son couchant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Tu fais l\'obscurité, et il est nuit: alors toutes les bêtes des forêts sont en mouvement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'les jeunes lions rugissent après la proie, et demandent à Dieu leur pâture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Le soleil se lève: ils se retirent, et vont reposer dans leurs tanières.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'L\'homme se rend à son travail, et à son labour jusques au soir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Que tes œuvres sont nombreuses, ô Éternel! Tu les as toutes faites avec sagesse; la terre est pleine de tes richesses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Dans cette mer grande et vaste fourmillent sans nombre des animaux petits et grands.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Là circulent les navires, le Léviathan que tu formas pour s\'y jouer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Tous ils s\'attendent à toi, pour que tu leur donnes la nourriture en son temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Tu leur donnes, ils recueillent; tu ouvres ta main, ils se rassasient de biens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Tu caches ta face, ils sont éperdus; tu leur retires le souffle, ils expirent et rentrent dans leur poudre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Tu émets ton souffle, ils sont créés, et tu renouvelles la face de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'La gloire de l\'Éternel demeure à jamais; l\'Éternel se réjouit de ses œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Il regarde la terre, et elle tremble; Il touche les montagnes, et elles sont fumantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Je veux chanter l\'Etemel, tant que je vivrai, célébrer mon Dieu, tant que je serai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Que mes chants lui soient agréables! Je fais mes délices de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Que les pécheurs disparaissent de la terre, et que les impies cessent d\'être! Mon âme, bénis l\'Éternel! Alléluia!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Louez l\'Éternel, invoquez son nom! Publiez ses exploits parmi les peuples!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Célébrez-le par vos chants et vos accords! Chantez toutes ses merveilles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Glorifiez-vous de son saint nom! Que le cœur de ceux qui le cherchent, se réjouisse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Méditez sur l\'Éternel et sa puissance! Cherchez sans cesse sa présence!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Pensez aux merveilles qu\'il a faites, à ses prodiges et aux jugements émanés de sa bouche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'vous, race d\'Abraham, vous, ses serviteurs, enfants de Jacob, ses élus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Lui, l\'Éternel! Il est notre Dieu, ses jugements embrassent toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Il garde un souvenir éternel de son alliance, de la parole qu\'il promulgua pour mille générations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'du traité qu\'il conclut avec Abraham, du serment qu\'il fit à Isaac,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'et érigea pour Jacob en statut, pour Israël en alliance éternelle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'disant: « Je te donnerai la terre de Canaan pour votre lot d\'héritage; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'tandis qu\'ils étaient encore en petit nombre, peu considérables, et étrangers en elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Et ils émigraient de nation en nation, d\'un royaume chez un autre peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Il ne permettait à personne de les opprimer, et en leur faveur Il châtia des rois:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, '« Ne touchez pas à mes oints, et ne maltraitez pas mes prophètes! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Alors Il appela la famine sur le pays, et lui coupa toutes les subsistances.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Il envoya devant eux un homme; comme esclave Joseph fut vendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Ils mirent les entraves à ses pieds, et il dut vivre dans les fers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'jusqu\'au temps où ce qu\'il avait dit, arriva, et où la parole de l\'Éternel fut son épreuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Le Roi dépêcha et le fit élargir, le souverain des peuples, et le mit en liberté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'il l\'établit seigneur sur sa maison, et souverain sur tous ses domaines,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'pour qu\'il enchaînât ses princes à son gré, et qu\'à ses vieillards il enseignât la sagesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Alors Israël vint en Egypte, et Jacob fut comme hôte dans le pays de Cham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Et Il rendit son peuple très fécond, et plus fort que ses ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Il changea leur cœur qui prit son peuple en haine, et ils traitèrent ses serviteurs avec perfidie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Il envoya Moïse, son serviteur, Aaron qu\'il avait élu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Ils opérèrent au milieu d\'eux ses prodiges, et ses miracles dans la terre de Cham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Il envoya les ténèbres, et produisit l\'obscurité, et ils ne furent pas rebelles à sa parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Il changea leurs eaux en sang, et fit périr leurs poissons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Leur pays fourmilla de grenouilles, jusques dans les appartements de leurs rois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Il dit, et vinrent les moucherons, les mouches dans tout leur territoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Il fit tomber leur pluie en grêle, des flammes de feu sur leur pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Et Il frappa leurs vignes et leurs figuiers, et fracassa les arbres de leur contrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Il dit, et vinrent les sauterelles, et des insectes voraces sans nombre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'qui dévorèrent toute l\'herbe du pays, et dévorèrent les fruits de leurs champs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Et Il frappa tous les premiers-nés dans leur pays, toutes les prémices de leur vigueur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Et Il fit sortir [Israël] avec de l\'argent et de l\'or, et il n\'y eut pas un homme las dans ses tribus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'L\'Egypte se réjouit de leur départ; car la peur d\'Israël l\'avait saisie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Il déploya la nuée pour les mettre à couvert, et le feu pour illuminer la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'A leur demande Il fit arriver des cailles, et Il les rassasia avec le pain du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Il entrouvrit le rocher, et des eaux jaillirent et coulèrent dans le désert par torrents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Car Il se rappelait sa sainte parole donnée à Abraham, son serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Il fit que son peuple partit avec joie, et ses élus avec allégresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'Il leur donna les terres des nations, et ils s\'emparèrent du travail des peuples:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'pour les porter à garder ses commandements, et à observer ses lois. Alléluia!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Alléluia! Louez l\'Éternel, car Il est bon, car sa miséricorde est éternelle!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Qui saura exprimer les exploits de l\'Éternel, et énoncer sa louange tout entière?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Heureux ceux qui observent la loi, et pratiquent la justice en tout temps!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Pense à moi, Seigneur, en étant propice à ton peuple, viens à moi avec ton secours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'afin que, témoin du bonheur de tes élus, je me réjouisse de la joie de ton peuple, que je me glorifie avec ton héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Nous avons péché de même que nos pères, nous avons été pervers et impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Nos pères en Egypte ne réfléchirent point à tes miracles, ne se rappelèrent point le nombre de tes grâces, et ils se rebellèrent près de la mer, la mer des algues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Mais Il les délivra pour l\'amour de son nom, afin de faire connaître sa puissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Et Il tança la mer des algues, et elle se dessécha, et Il leur fit traverser les flots comme le désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Et Il les sauva de la main de l\'adversaire, et les racheta de la main de l\'ennemi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'et les eaux recouvrirent leurs oppresseurs, il n\'en resta pas un seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Alors ils crurent à ses paroles, ils chantèrent ses louanges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Ils furent prompts à oublier ses exploits, et ne surent pas attendre ses dispensations;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'et ils conçurent une convoitise dans le désert, et tentèrent Dieu dans la solitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Alors Il condescendit à leur demande, mais Il leur envoya aussi la consomption.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Et ils furent jaloux de Moïse dans le camp, d\'Aaron, le saint de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Alors la terre s\'ouvrit et engloutit Dathan, et recouvrit la troupe d\'Abiram,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'et un feu s\'alluma au milieu de leur troupe, et des flammes consumèrent les sacrilèges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Ils fabriquèrent un veau en Horeb, et adorèrent une image de fonte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'et ils échangèrent leur gloire contre l\'effigie d\'un bœuf qui broute l\'herbe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Ils oublièrent Dieu, leur libérateur, qui avait opéré de grandes choses en Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'des miracles dans la terre de Cham, des prodiges sur la mer des algues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Alors Il pensait à les détruire, si Moïse, son élu, ne s\'était mis à la brèche devant Lui, pour détourner sa colère de détruire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Et ils se dégoûtèrent du pays des délices; ils ne croyaient pas à ses promesses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'et ils murmurèrent dans leurs tentes, ne furent point dociles à la voix de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Alors levant sa main Il jura de les coucher dans le désert,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'et de jeter leur race au milieu des nations, et de les disséminer dans tous les pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Et ils s\'attachèrent à Baal-Pehor, et mangèrent les sacrifices des morts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'et L\'irritèrent par leurs crimes: aussi un fléau fit irruption chez eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Alors parut Phinées qui fit justice, et le fléau fut arrêté:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'et cela lui fut imputé à justice, d\'âge en âge, éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Et ils Le provoquèrent aux Eaux de la Querelle, et Moïse eut à souffrir à cause d\'eux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'car ils résistèrent à sa volonté, et les paroles de ses lèvres furent inconsidérées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Ils ne détruisirent point les peuples que l\'Éternel leur avait signalés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'et ils se mêlèrent avec les peuples, et apprirent leur façon de faire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'et ils servirent leurs idoles, qui leur furent un piège;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'ils immolèrent leurs fils et leurs filles aux idoles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'et répandirent le sang innocent, le sang de leurs fils et de leurs filles, qu\'ils immolèrent aux idoles de Canaan; et le pays fut profané par des meurtres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'et ils se souillèrent avec leurs œuvres, et leur conduite fut une prostitution.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Alors la colère de l\'Éternel s\'alluma contre son peuple, et son héritage devint son abomination;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'et Il les livra aux mains des peuples, et leurs ennemis furent leurs maîtres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'et ils furent opprimés par leurs adversaires, et plièrent sous leur main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Nombre de fois Il les délivra; mais ils regimbèrent, ne prenant conseil que d\'eux-mêmes, et ils se perdirent par leur faute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Et Il regarda vers eux pendant la détresse, quand Il entendit leurs gémissements;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'et Il se ressouvint pour eux de son alliance, et céda à la pitié dans sa grande miséricorde,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'et Il leur fit rencontrer de la compassion auprès de tous ceux qui les tenaient captifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Sois-nous en aide, Éternel, notre Dieu, et recueille-nous du milieu des peuples, pour que nous chantions ton saint nom, et que nous fassions gloire de te louer! \\csp{');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Béni soit l\'Éternel, Dieu d\'Israël, de l\'éternité à l\'éternité! et que tout le peuple dise: Ainsi soit-il! Alleluia!}');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Louez l\'Éternel, car Il est bon, car sa miséricorde est éternelle!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Qu\'ainsi parlent les rachetés de l\'Éternel, qu\'il a rachetés des mains de l\'ennemi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'et recueillis de tout pays, du Levant et du Couchant, du Septentrion et de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Ils furent errants au désert, dans une voie solitaire, et ils ne trouvaient pas une ville où habiter;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'ils éprouvaient la faim et la soif; leur âme en eux était défaillante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Et ils crièrent à l\'Éternel dans leur détresse, et Il les délivra de leurs perplexités,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'et leur fit prendre la voie directe pour arriver à une ville où pouvoir habiter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Qu\'ils rendent grâces à l\'Éternel de sa miséricorde, et disent ses merveilles aux enfants des hommes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Car Il a satisfait l\'âme altérée, et comblé de biens l\'âme affamée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Ceux qui habitaient les ténèbres et l\'ombre de la mort, prisonniers de la misère et des fers...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Car ils résistèrent aux paroles de Dieu, et méprisèrent les décrets du Très-haut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Aussi courba-t-Il leur cœur sous la peine; ils succombèrent, et ne furent point assistés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Mais ils crièrent à l\'Éternel dans leur détresse, et Il les délivra de leurs perplexités;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Il les tira des ténèbres et de l\'ombre de la mort, et rompit leurs fers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Qu\'ils rendent grâces à l\'Éternel de sa miséricorde, et disent ses merveilles aux enfants des hommes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Car Il a brisé les portes d\'airain, et mis en pièces les verrous de fer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Les insensés qui suivaient la voie de la révolte, et à cause de leurs crimes se virent humiliés...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Toute nourriture excitait leur dégoût, et ils arrivaient aux portes de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Mais ils crièrent à l\'Éternel dans leur détresse, et Il les délivra de leurs perplexités;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Il émit sa parole, et les guérit, et les retira de leurs tombeaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Qu\'ils rendent grâces à l\'Éternel de sa miséricorde, et disent ses merveilles aux enfants des hommes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'Qu\'ils Lui offrent les sacrifices de la reconnaissance, et publient ses hauts faits avec des cris de joie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Ceux qui se mirent en mer sur des navires, et firent la manœuvre sur les grandes eaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'furent témoins des œuvres de Dieu, et des merveilles qu\'il opère dans les flots.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Il dit, et excita un vent de tempête, qui souleva les vagues de la mer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'elles montèrent vers le ciel, descendirent dans l\'abîme, leur âme dans le danger était éperdue;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'saisis du vertige, ils chancelaient, comme étant ivres, et toute leur sagesse était évanouie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Mais ils crièrent à l\'Éternel dans leur détresse, et Il les délivra de leurs perplexités,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Il fit cesser la tourmente qui devint silencieuse, et les vagues se turent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'et ils furent joyeux, quand elles se calmèrent, et Il les conduisit au port désiré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Qu\'ils rendent grâces à l\'Éternel de sa miséricorde, et disent ses merveilles aux enfants des hommes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Qu\'ils L\'exaltent dans l\'assemblée du peuple, et Le louent dans la séance des anciens!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Il change les fleuves en désert, et les sources des eaux en sol aride,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'la plaine fertile en steppe salée, à cause de la méchanceté de ses habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Il change le désert en une masse d\'eaux, et la terre desséchée en sources d\'eaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'et Il y établit ceux qui sont affamés, et là ils fondent des villes, pour les habiter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Ils ensemencent des champs, et plantent des vignes qui donnent leurs fruits pour revenu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Et Il les bénit, et ils deviennent très nombreux, et Il n\'amoindrit pas leurs bestiaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Or ils étaient amoindris et accablés par l\'oppression, le malheur et les peines;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'c\'est lui qui verse le mépris sur les princes, et Il les fait errer dans un désert sans chemin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'mais Il relève le pauvre de sa misère, et rend les familles égales à des troupeaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'C\'est ce que voient les hommes droits, et ils se réjouissent, et tous les méchants ont la bouche fermée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Que tout homme sage prenne garde à ceci, et soit attentif aux grâces de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Cantique de David. O Dieu, mon cœur se rassure! Par mes chants et mes accords, oui, je veux célébrer ma gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Sus! mon luth et ma harpe! Je serai debout avec l\'aurore!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Je te louerai, Éternel, parmi les peuples, et te chanterai parmi les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Car ta grâce est plus grande que les Cieux, et ta fidélité atteint jusques aux nues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Elève-toi, ô Dieu, sur les Cieux, et que sur toute la terre apparaisse ta gloire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Pour que les bien-aimés soient sauvés, aide-les de ta droite, et nous exauce!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Dieu l\'a promis par sa sainteté: je veux m\'en réjouir! « Je vous partagerai Sichem, et vous distribuerai la vallée de Succoth;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Galaad est à moi, Manassé est à moi, Ephraïm est le rempart de ma tête, et Juda, mon sceptre royal;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Moab est le bassin où je me baigne, sur Edom je jette ma chaussure, sur la Philistie je pousse des cris de joie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Qui me conduira dans la ville forte? qui me mènera jusqu\'en Edom?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'N\'est-ce pas toi, ô Dieu, toi qui nous rejetas, et ne marchas plus, ô Dieu, avec nos armées?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Donne-nous ton aide pour sortir de la gêne, puisque le secours de l\'homme est une vanité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Avec Dieu, nous serons vainqueurs, et c\'est lui qui foulera nos ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Au maître chantre. Cantique de David. Dieu que je loue, ne reste pas muet!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Car ils ouvrent contre moi la bouche de l\'impie, la bouche du trompeur, parlent avec une langue menteuse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'et ils m\'entourent de paroles de haine, et me font gratuitement la guerre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'En échange de mon amour ils me sont hostiles, mais moi je ne fais que prier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Ils me rendent le mal pour le bien, et de la haine pour mon amour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Mets un tel homme sous le pouvoir de l\'impie, et que l\'accusateur se dresse à sa droite!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Que du jugement il sorte convaincu, et que sa prière soit comptée comme péché!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Qu\'il ait des jours peu nombreux, qu\'un autre s\'empare de sa charge!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Que ses enfants soient orphelins, et sa femme veuve!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Que ses fils soient vagabonds et mendient, et qu\'ils quêtent loin de leur maison en ruines!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Que l\'usurier jette le réseau sur tout ce qu\'il a, et que des étrangers pillent le fruit de son labeur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Que personne ne lui garde une longue affection, et que nul n\'ait pitié de ses orphelins!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Que sa postérité soit exterminée, et que dès l\'âge suivant leur nom soit éteint!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Qu\'il soit fait mention devant l\'Éternel du crime de ses pères, et que le péché de sa mère ne soit point effacé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'mais qu\'ils soient toujours présents à l\'Éternel, et qu\'il retranche sa mémoire de la terre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'parce qu\'il ne pensa point à pratiquer la bonté, et qu\'il persécuta l\'homme misérable et pauvre et l\'affligé, afin de lui ôter la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Il aimait la malédiction, qu\'elle l\'atteigne! La bénédiction n\'était pas son plaisir, qu\'elle s\'éloigne de lui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Qu\'il se couvre de la malédiction comme de son vêtement; qu\'elle pénètre au dedans de lui comme des eaux, et comme de l\'huile, dans ses os;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'qu\'elle soit pour lui comme le manteau où il s\'enveloppe et comme la ceinture dont il se ceint toujours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Tel soit le salaire que donne l\'Éternel à mon ennemi, et à ceux qui disent du mal contre moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Mais toi, Éternel, mon Dieu! assiste-moi pour l\'amour de ton nom, car ta grâce est bénigne; sauve-moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'car je suis misérable et pauvre, et mon cœur est percé au dedans de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Je m\'en vais, comme l\'ombre, quand elle s\'allonge, je suis pourchassé comme la sauterelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Mes genoux chancellent par l\'effet de mes jeûnes, et l\'embonpoint a disparu de mon corps amaigri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Je suis livré à leurs outrages; ils me regardent, et secouent la tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Assiste-moi, Éternel, mon Dieu! Sauve-moi en vertu de ta miséricorde,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'afin qu\'ils sachent que c\'est ta main, que c\'est toi, Éternel, qui l\'auras fait!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Qu\'ils maudissent! toi, tu béniras. Qu\'ils se dressent! ils seront confondus, et ton serviteur se réjouira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Que la honte enveloppe mes adversaires, et que leur opprobre les couvre comme un manteau!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Alors de ma bouche je louerai hautement l\'Éternel, et je te célébrerai au milieu de la foule,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'car Il se tient à la droite du pauvre, et le sauve de ceux qui le condamnent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Cantique de David. L\'Éternel dit à mon Seigneur: « Assieds-toi à ma droite, jusqu\'à ce que je te donne pour marchepied tes ennemis. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'De Sion l\'Éternel étendra le sceptre de ta puissance. Domine au milieu de tes ennemis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Ton peuple s\'empresse au jour de ton armement, dans une pompe sainte; ta jeunesse vient à toi comme une rosée sortant du sein de l\'aurore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'L\'Éternel a juré, et ne s\'en repentira point: « Tu es sacrificateur pour l\'éternité à l\'instar de Melchisédek. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Le Seigneur à ta droite a mis des rois en pièces au jour de sa colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Il fera justice parmi les peuples: tout est plein de cadavres; Il a mis des têtes en pièces sur un vaste pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Il boira au torrent dans sa marche, puis Il relèvera la tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Alléluia! Je loue l\'Éternel de tout mon cœur, dans la réunion des justes et dans l\'assemblée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Les œuvres de l\'Éternel sont grandes, telles que tous leurs désirs peuvent les souhaiter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Ce qu\'il opère, est splendeur et magnificence, et sa justice demeure éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Il a assuré une mémoire à ses miracles, l\'Éternel est miséricordieux et clément.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Il a donné la nourriture à ceux qui le craignaient, Il garde de son alliance un souvenir éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Il a révélé à son peuple la puissance de ses actes, en lui donnant la propriété des nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Les œuvres de ses mains sont vérité et justice, tous ses commandements sont sûrs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'stables pour jamais, pour l\'éternité, tracés selon la vérité et la droiture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Il a dispensé le salut à son peuple, et sanctionné son alliance pour l\'éternité. Son nom est saint et redoutable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'La crainte de l\'Éternel est le commencement de la sagesse; qui s\'y conforme a la bonne prudence. Sa gloire demeure éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Alléluia! Heureux l\'homme qui craint l\'Éternel, et a un grand goût pour ses commandements!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Sa race sera puissante sur la terre, et la postérité du juste sera bénie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'L\'aisance et la richesse sont dans sa maison, et sa justice demeure éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Dans les ténèbres la lumière se lève pour le juste; il est miséricordieux, clément et juste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Le bonheur est pour celui qui donne et qui prête, qui pour soutenir sa cause se fonde sur le droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Car il n\'est jamais ébranlé, et l\'homme de bien laisse une mémoire éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Il ne redoute point un message funeste; son cœur est ferme, il se confie dans l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'son cœur a de l\'assurance, il est sans crainte, attendant que ses ennemis réjouissent ses regards.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Il distribue, il donne aux indigents; sa justice demeure éternellement; sa tête se lève avec gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'L\'impie en est témoin et il s\'en chagrine, il grince des dents et se consume; les souhaits de l\'impie sont mis à néant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Alléluia! Serviteurs de l\'Éternel, louez, louez le nom de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Béni soit le nom de l\'Éternel dès maintenant à jamais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Du soleil levant jusques au couchant, que le nom de l\'Éternel soit loué!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'L\'Éternel s\'élève par dessus tous les peuples, et sa gloire par dessus les Cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Qui est semblable à l\'Éternel, notre Dieu, qui habite une sublime région,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'et qui se baisse pour voir les Cieux et la terre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Il relève l\'humble de la poudre, et Il tire le pauvre de la fange,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'pour le faire asseoir à côté des princes, à côté des princes de son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Il donne dans la maison à l\'épouse stérile la condition d\'une mère que des fils réjouissent. Alléluia!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Lorsque Israël quitta l\'Egypte, et la maison de Jacob un peuple au langage étrange,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Juda devint son Sanctuaire, et Israël, sa Souveraineté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'A sa vue la mer s\'enfuit, et le Jourdain retourna en arrière,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'les montagnes bondirent comme des béliers, les collines, comme de jeunes agneaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Qu\'as-tu, ô mer, que tu t\'enfuis, ô Jourdain, que tu retournes en arrière,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'montagnes, que vous bondissez comme des béliers, vous, collines, comme de jeunes agneaux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'A l\'aspect du Seigneur, tremble, ô terre, à l\'aspect du Dieu de Jacob,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'qui transforme la roche en un amas d\'eaux, et le dur caillou en source jaillissante!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Non pas à nous, Éternel, non pas à nous, mais à ton nom donne gloire, pour l\'amour de ta grâce, de ta fidélité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Pourquoi faut-il que les nations disent: « Où donc est leur Dieu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Cependant notre Dieu est dans les Cieux; tout ce qu\'il veut, Il le fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Leurs idoles sont de l\'argent et de l\'or, un ouvrage des mains de l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Elles ont une bouche, et ne parlent point; elles ont des yeux, et ne voient point;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'elles ont des oreilles, et n\'entendent point; elles ont des narines, et sont sans odorat;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'avec leurs mains elles ne peuvent saisir, avec leurs pieds elles ne peuvent marcher, et elles ne tirent aucun son de leur gosier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Telles elles sont, tels sont ceux qui les fabriquent, tous ceux qui mettent leur confiance en elles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Israël, confie-toi dans l\'Éternel! Il est notre aide et notre bouclier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Maison d\'Aaron, confiez-vous dans l\'Éternel! Il est notre aide et notre bouclier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Vous qui craignez l\'Éternel, confiez-vous dans l\'Éternel! Il est notre aide et notre bouclier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'L\'Éternel se souvient de nous: Il bénira, Il bénira la maison d\'Israël, Il bénira la maison d\'Aaron,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Il bénira ceux qui craignent l\'Éternel, les petits aussi bien que les grands.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Que l\'Éternel vous fasse prospérer, vous et vos enfants!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Soyez bénis de l\'Éternel, créateur des Cieux et de la terre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Les Cieux sont les Cieux de l\'Éternel, mais Il a donné la terre aux enfants des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Ce ne sont pas les morts qui louent l\'Éternel, ni ceux qui sont descendus dans le lieu du silence;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'mais nous, nous bénirons l\'Éternel, dès maintenant à l\'éternité! Alléluia!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'C\'est mon bonheur que l\'Éternel écoute ma voix, mes prières!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Car Il a penché vers moi son oreille; aussi toute ma vie je veux l\'invoquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Les liens de la mort m\'enveloppaient, j\'étais atteint des angoisses des Enfers, je trouvais devant moi la détresse et la douleur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Mais j\'invoquai le nom de l\'Éternel: « O Etemel, sauve mon âme! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'L\'Éternel est clément et juste, et notre Dieu, plein de miséricorde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'L\'Éternel garde les simples; j\'étais affligé, et Il me fut secourable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Rentre, mon âme, dans ton repos! car l\'Éternel t\'a fait du bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Car Tu as affranchi mon âme de la mort, mes yeux des pleurs, mon pied de la chute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Je marcherai sous le regard de l\'Éternel, sur la terre des vivants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'J\'ai cru, car j\'ai parlé. J\'avais beaucoup à souffrir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Je disais dans mes alarmes: « Tous les hommes sont trompeurs. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Comment rendrai-je à l\'Éternel tous les bienfaits que j\'ai reçus de lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'J\'élèverai la coupe des délivrances, et j\'invoquerai le nom de l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'j\'accomplirai mes vœux envers l\'Éternel à la face de tout son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Aux yeux de l\'Éternel, ce qui coûte, c\'est la mort de ses bien-aimés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'O exauce-moi, Éternel! car je suis ton serviteur, le fils de ta servante. Tu as détaché mes chaînes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'je t\'offrirai le sacrifice de la reconnaissance, et j\'invoquerai le nom de l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'j\'accomplirai mes vœux envers l\'Éternel, à la face de tout son peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'dans les parvis de la maison de l\'Éternel, dans ton sein, ô Jérusalem! Alléluia!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Louez l\'Éternel, vous toutes les nations; glorifiez-le, vous tous les peuples!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Car sa grâce puissamment nous protège, et la fidélité de l\'Éternel dure éternellement. Alléluia!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Louez l\'Éternel! car Il est bon, car sa grâce demeure à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Qu\'Israël dise: Sa grâce demeure à jamais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Que la maison d\'Aaron dise: Sa grâce demeure à jamais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Que ceux qui craignent l\'Éternel disent: Sa grâce demeure à jamais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Dans les angoisses j\'invoquai l\'Éternel; l\'Éternel m\'exauça en me mettant au large.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'L\'Éternel est pour moi, je suis sans crainte; qu\'est-ce que l\'homme me ferait?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'L\'Éternel est mon aide, et mes ennemis réjouiront mes regards.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Mieux vaut se réfugier auprès de l\'Éternel, que de se confier dans les hommes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'mieux vaut se réfugier auprès de l\'Éternel, que de se confier dans des princes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Tous les peuples m\'ont assiégé; au nom de l\'Éternel, oui, je les détruirai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Ils m\'ont assiégé, et encore assiégé; au nom de l\'Éternel, oui, je les détruirai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Ils m\'ont assiégé comme des abeilles: ils s\'éteignent comme un feu d\'épines; au nom de l\'Éternel, oui, je les détruirai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'par tes assauts tu voulais me terrasser, mais l\'Éternel a été mon aide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Que l\'Éternel soit le sujet de mes louanges et de mes chants; Il a été mon salut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Ecoutez! dans les tentes des justes retentissent des cris de joie et des chants de triomphe: « La droite de l\'Éternel a montré sa puissance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'la droite de l\'Éternel s\'est levée, la droite de l\'Éternel a montré sa puissance. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Je ne mourrai point, mais je vivrai, et je raconterai les actes de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'L\'Éternel m\'a châtié, mais Il ne m\'a pas livré à la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Ouvrez-moi les Portes de la Justice je veux y entrer et louer l\'Etemel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Voici la Porte de l\'Éternel, c\'est par elle qu\'entrent les justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Je te rends grâces de m\'avoir exaucé, et d\'avoir été mon libérateur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, '« La pierre rejetée par les architectes est devenue la pierre angulaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'De par l\'Éternel il en est ainsi, c\'est une merveille à nos yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'C\'est la journée que l\'Éternel a faite; soyez-en réjouis et transportés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'O! exauce, Éternel, sauve! O! exauce, Éternel, donne la prospérité! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, '« Béni soit celui qui arrive au nom de l\'Éternel! Nous vous bénissons de la maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'L\'Éternel est Dieu, et Il nous donne sa clarté. Liez la victime avec des cordes, {[}et l\'amenez{]} jusqu\'aux cornes de l\'autel! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Tu es mon Dieu, et je te loue; mon Dieu, je t\'exalte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Louez l\'Éternel, car Il est bon, car sa grâce demeure à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Heureux ceux dont la voie est innocente, qui marchent selon la loi de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Heureux ceux qui observent ses ordonnances, le cherchent de tout leur cœur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'ne commettent point le mal, et marchent dans ses voies!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Tu as prescrit tes commandements, pour qu\'on les garde avec soin!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'O! si mes voies étaient dirigées vers l\'observation de tes commandements!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Alors je ne serais pas confus, en considérant tous tes préceptes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Je te louerai d\'un cœur sincère, en apprenant tes justes lois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Je veux garder tes commandements: ne me laisse pas trop dans l\'abandonnement! Beth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Comment un jeune homme rendra-t-il sa voie pure? C\'est en la surveillant d\'après ta parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Je te cherche de tout mon cœur: fais que je ne m\'écarte pas de tes commandements!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'Je serre ta parole dans mon cœur, afin de ne point pécher contre toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Sois béni, ô Éternel! enseigne-moi tes décrets!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'De mes lèvres j\'énumère toutes les lois sorties de ta bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'La voie que tracent tes préceptes, me donne autant de joie que tous les trésors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Je veux méditer tes commandements, et avoir les yeux sur tes sentiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Je fais mes délices de tes décrets, et je n\'oublie point ta parole. Guimel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Fais du bien à ton serviteur, pour que je vive, et que j\'observe ta parole!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Dessille mes yeux, pour que je découvre les merveilles cachées dans ta loi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Je suis un étranger sur la terre: ne me cèle pas tes commandements!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Mon âme se consume à désirer tes lois en tout temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Tu gourmandes les superbes, hommes maudits, qui s\'écartent de tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Décharge-moi de l\'opprobre et du mépris, car j\'observe tes ordonnances!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Des princes mêmes se sont concertés contre moi: ton serviteur médite tes statuts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'tes ordres sont aussi mes délices et mes conseillers. Daleth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Mon âme gît dans la poudre: rends-moi la vie selon ta promesse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Je te raconte mes voies, et tu m\'exauces: enseigne-moi tes ordonnances!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Fais-moi découvrir la voie tracée par tes lois, et je veux approfondir tes merveilles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Mon âme pleure de chagrin: relève-moi selon ta promesse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Tiens à distance de moi le chemin du mensonge, et accorde-moi la faveur de [connaître] ta loi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Je choisis le chemin de la vérité, et je me propose tes jugements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Je m\'attache à tes ordonnances: Éternel, ne me rends pas confus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Je courrai dans la voie de tes commandements, car tu ouvres mon cœur. Hé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Éternel, indique-moi la voie de tes statuts, afin que je la tienne jusques au bout!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Donne-moi l\'intelligence, pour que je garde ta loi, et que je l\'observe de tout mon cœur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Fais-moi suivre le sentier de tes préceptes, car j\'en fais mes délices!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Incline mon cœur vers tes préceptes, et non vers l\'amour du gain!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Détourne mes yeux de regarder ce qui est vain, anime-moi sur tes sentiers!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Envers ton serviteur remplis ta promesse, qui fut faite à la crainte qu\'on a de toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Tiens loin de moi l\'opprobre que je redoute, car tes jugements sont pleins de bonté!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Voici, je porte mes désirs vers tes commandements, fais-moi vivre dans ta justice! Vav.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Et que tes grâces arrivent jusqu\'à moi, Éternel, ton secours, selon ta promesse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'afin que je puisse répondre à celui qui m\'outrage; car je me confie en ta promesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'N\'ôte jamais de ma bouche le langage de la vérité! car je suis dans l\'attente de tes jugements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Et j\'observerai ta loi constamment, à jamais, perpétuellement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'et je marcherai dans une voie spacieuse, car je cherche tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Et je parlerai de ta loi en présence des rois, et je n\'aurai point de honte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Et je ferai mes délices de tes commandements, que j\'aime,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'et je lèverai mes mains vers tes commandements que j\'aime et je méditerai tes statuts. Zaïn.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Souviens-toi de ta promesse à ton serviteur, puisque tu m\'as donné l\'espérance!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Voici ma consolation dans ma misère, c\'est que ta promesse me redonne la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Des superbes me tournent en grande dérision; de ta loi je ne dévie point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Je me rappelle tes jugements de jadis, Éternel, et je me console.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Un bouillant transport me saisit à la vue des impies, qui abandonnent ta loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Tes décrets me suggèrent des cantiques, dans le lieu de mon exil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'La nuit je pense à ton nom, Éternel, et j\'observe ta loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Voici ce qui m\'est propre, c\'est que je garde tes commandements. Cheth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Mon partage, ô Éternel, je le dis, c\'est de garder tes paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Je cherche ta faveur de toute mon âme: sois-moi propice selon ta promesse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Je suis circonspect dans mes voies, et je retourne mes pas vers tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Je me hâte, et ne diffère point d\'observer tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Les pièges des impies m\'enveloppent; je n\'oublie point ta loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Au milieu de la nuit, je me lève pour te louer des jugements de ta justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Je me lie avec tous ceux qui te craignent, et observent tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'La terre, ô Éternel, est pleine de ta grâce: enseigne-moi tes ordonnances! Theth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Tu fais du bien à ton serviteur, Éternel, selon ta promesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Enseigne-moi la bonne science et la connaissance! car je crois en tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Avant mon humiliation, je m\'égarais; mais maintenant je prends garde à ta parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Tu es bon et bienfaisant; enseigne-moi tes statuts!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Des superbes contre moi ourdissent l\'astuce; moi, de tout mon cœur j\'observe tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Leur cœur a l\'insensibilité de la graisse, moi, je fais mes délices de ta loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Il m\'est utile d\'avoir été humilié, pour devenir docile à tes préceptes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'La loi qui sort de ta bouche a plus de prix pour moi que des milliers d\'or et d\'argent. Jod.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Tes mains m\'ont créé, m\'ont formé; donne-moi l\'intelligence, pour apprendre tes statuts!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Ceux qui te craignent, me verront et se réjouiront, car j\'espère dans tes promesses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Je sais, Éternel, que tes jugements sont justes, et que tu m\'as affligé en demeurant fidèle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'O que ta grâce soit ma consolation, selon ta promesse à ton serviteur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Envoie-moi ta miséricorde, pour que j\'aie la vie! car ta loi fait mes délices.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Que les superbes soient confondus, car ils m\'accablent gratuitement! pour moi, je médite tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Qu\'ils reviennent à moi ceux qui te craignent, et ceux qui connaissent tes commandements!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Que mon cœur soit tout à tes ordonnances, afin que je ne sois pas confondu! Caph.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Mon âme languit après ton salut; je compte sur ta promesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Mes yeux s\'éteignent dans l\'attente de ta promesse, je dis: Quand me consoleras-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Car je suis comme une outre fumée; je n\'oublie point tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Quel est le nombre des jours de ton serviteur? Quand feras-tu justice de mes persécuteurs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Des orgueilleux creusent des fosses devant moi; ils n\'agissent point d\'après ta loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Tous tes commandements sont vrais: sans cause ils me persécutent; assiste-moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Ils m\'ont presque détruit, après m\'avoir terrassé; mais je n\'abandonne point tes commandements,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Selon ta miséricorde rends-moi la vie, afin que j\'observe les ordres de ta bouche! Lamed.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Éternellement, Seigneur, ta parole subsiste dans les Cieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'd\'âge en âge ta vérité demeure; tu as fondé la terre, et elle est stable;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'suivant tes lois tout subsiste aujourd\'hui, car toutes choses te sont assujetties.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Si ta loi n\'eût fait mes délices, j\'aurais péri dans ma misère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Jamais je n\'oublierai tes commandements, car c\'est par eux que tu me fais vivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Je suis à toi: donne-moi ton secours! car je cherche tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Les impies m\'attendent pour me faire périr; je suis attentif à tes ordres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'A toute chose parfaite j\'ai vu une fin; ta loi est infinie Mem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Combien j\'aime ta loi! elle est ma pensée de tous les jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Tes préceptes me rendent plus sage que mes ennemis. car ils sont toujours avec moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Je suis plus expert que tous mes maîtres, car tes ordonnances sont la pensée que j\'ai;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'je suis plus entendu que les vieillards, car j\'observe tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Je tiens mon pied loin de tout mauvais sentier, afin que j\'observe ta parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Je ne m\'écarte point de ta loi, car c\'est toi qui m\'instruis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Que ta parole est douce à mon palais! elle l\'est plus que le miel à ma bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Dans tes commandements je puise l\'intelligence, aussi je hais tous les sentiers du mensonge. Nun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Ta parole est une lampe devant mes pieds, et une lumière sur mon sentier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'J\'ai fait le serment, et je le tiens, d\'observer tes justes lois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Je suis extrêmement affligé: Éternel, rends-moi la vie selon ta promesse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Agrée, Éternel, le libre hommage de ma bouche, et enseigne-moi tes lois!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Ma vie est toujours en péril; mais je n\'oublie point ta loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Des impies me tendent des pièges, mais je ne m\'écarte point de tes ordres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Je me suis pour toujours approprié tes préceptes car ils sont la joie de mon cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'J\'ai plié mon cœur à la pratique de tes lois, pour jamais, jusqu\'à la fin. Samech.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Je hais les hommes partagés, et j\'aime ta loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Tu es mon abri et mon bouclier; j\'attends ta promesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Eloignez-vous de moi, méchants, afin que je garde les commandements de mon Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Soutiens-moi selon ta promesse, afin que je vive, et ne me confonds point à cause de mon espoir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Sois mon appui, pour que je sois sauvé, et que j\'aie toujours les yeux sur tes commandements!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Tu méprises tous ceux qui s\'écartent de tes lois; car leur fraude n\'est qu\'illusion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Tu enlèves comme des scories tous les impies de la terre; c\'est pourquoi j\'aime tes ordonnances.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Tes terreurs font frissonner mon corps, et je redoute tes jugements. Aïn.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'J\'ai pratiqué la loi, la justice: tu ne m\'abandonneras pas à mes oppresseurs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Prends le parti de ton serviteur pour le sauver! que les superbes ne m\'oppriment pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Mes yeux languissent après ton secours et ta juste promesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Traite ton serviteur selon ta miséricorde, et enseigne-moi tes ordonnances!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Je suis ton serviteur: donne-moi l\'intelligence, pour que j\'aie la science de tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Il est pour l\'Éternel temps d\'agir; ils ont enfreint ta loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Aussi j\'aime tes commandements, plus que l\'or, et que l\'or pur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'aussi je trouve justes tous tes commandements; et je hais tous les sentiers du mensonge. Pé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Tes commandements sont admirables; c\'est pourquoi mon âme les garde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'La révélation de tes paroles éclaire, donne de l\'intelligence aux simples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'J\'ouvre la bouche, je soupire; car je suis avide de tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Tourne tes regards sur moi, et prends pitié de moi, selon le droit de ceux qui aiment ton nom!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Affermis mes pas dans ta parole, et ne laisse aucun mal prendre empire sur moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Délivre-moi de l\'oppression des hommes, afin que j\'observe tes commandements!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Fais luire ta face sur ton serviteur, et enseigne-moi tes ordonnances!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Des torrents d\'eau coulent de mes yeux, parce que l\'on n\'observe pas ta loi. Tsadé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Tu es juste, Éternel, et tes jugements sont équitables;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'tu prescris la justice dans tes ordonnances, et une grande vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Mon indignation me consume, de ce que mes ennemis oublient tes paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Ta parole est parfaitement pure, et ton serviteur l\'aime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Je suis chétif et méprisé; je n\'oublie point tes préceptes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Ta justice est un droit éternel, et ta loi, une vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'La détresse et l\'angoisse m\'ont atteint; tes commandements sont mon délice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'La justice de tes ordonnances est éternelle; donne-moi l\'intelligence, afin que je vive! Quoph.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Je t\'invoque de tout mon cœur, exauce-moi, Éternel afin que j\'observe tes ordonnances!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Je t\'invoque: aide-moi, afin que je garde tes commandements!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Je devance l\'aurore et je crie; j\'attends ta promesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Avant les veilles j\'ouvre déjà les yeux, pour méditer ta parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Entends ma voix selon ta miséricorde! Éternel, selon ta justice donne-moi la vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Ils s\'approchent ceux qui poursuivent le mal, ils se tiennent loin de ta loi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'mais tu es proche, Éternel, et tous tes commandements sont vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Dès longtemps je sais par tes décrets que pour l\'éternité tu les as arrêtés. Resch.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Vois ma misère, et me délivre! car je n\'oublie point ta loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Soutiens ma querelle, et me rachète! selon ta promesse donne-moi la vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Le salut est loin des impies; car ils ne cherchent point tes ordonnances.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Tes compassions sont grandes, Éternel; donne-moi la vie selon tes décrets!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Mes persécuteurs et mes oppresseurs sont nombreux; je n\'ai point dévié de tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Je vois les infidèles, et j\'en ai de l\'horreur; ils n\'observent point ta parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Considère que j\'aime tes commandements: Éternel, selon ta miséricorde donne-moi la vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Le sommaire de ta parole, c\'est vérité, et toutes tes justes lois sont éternelles. Schin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Des princes me persécutent sans cause; mais mon cœur ne craint que tes paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Je me réjouis de ta parole, comme celui qui trouve un grand butin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Je hais, je déteste le mensonge; j\'aime ta loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Sept fois le jour je te célèbre, à cause de tes justes lois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Ils ont une grande paix ceux qui aiment la loi, pour eux il n\'y a point de traverses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Je m\'attends à ton secours, Éternel, et je pratique tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Mon âme observe tes ordonnances, et j\'ai pour elles un grand amour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'J\'exécute tes ordres et tes commandements, car toutes mes voies sont présentes à tes yeux. Thav.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Que mes cris aient accès près de toi, Éternel! selon ta promesse donne-moi l\'intelligence!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Que ma prière arrive devant toi! selon ta promesse sauve-moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Que mes lèvres épanchent la louange! car tu m\'enseignes tous tes commandements!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Que ma langue célèbre ta parole! car toutes tes lois sont justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Que ta main me soit en aide! car j\'ai fait choix de tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Je suis désireux de ton secours, Éternel, et ta loi fait mes délices.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Que mon âme vive, et qu\'elle te loue! et de tes jugements donne-moi le secours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Je suis errant, comme une brebis perdue; cherche ton serviteur! car je n\'oublie pas tes commandements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Cantique graduel. A l\'Éternel dans ma détresse j\'élève mes cris, et Il m\'exauce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Éternel, délivre-moi des lèvres qui mentent, de la langue qui trompe!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Que te donnera-t-Il, t\'adjugera-t-Il, langue trompeuse?...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Les traits acérés du guerrier, avec les charbons ardents du genêt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Malheureux que je suis d\'habiter en Mésech, de demeurer dans les tentes de Cédar!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Je n\'ai que trop séjourné parmi ceux qui haïssent la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Je ne veux que la paix; mais, si j\'en parle, ils sont pour la guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Cantique graduel. Je lève mes yeux vers les montagnes: d\'où me viendra le secours?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Le secours me viendra de l\'Éternel, créateur des Cieux et de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Il ne permettra pas que ton pied bronche, ton gardien ne sommeille pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Voici, Il ne dort pas, ne sommeille pas, le gardien d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'L\'Éternel est ton gardien, l\'Éternel est ton abri, à ta droite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Le jour, le soleil ne te portera pas ses coups, non plus que la lune pendant la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'L\'Éternel te préservera de tout mal, Il gardera ton âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Que tu entres, que tu sortes, l\'Éternel te gardera, dès maintenant jusqu\'à l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Cantique graduel. De David. Je me réjouis, quand on me dit: Allons à la maison de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Nos pieds s\'arrêtent dans tes Portes, Jérusalem!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jérusalem, bâtie comme une ville où les édifices se lient l\'un à l\'autre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'rendez-vous des tribus, des tribus de l\'Éternel, selon l\'ordre donné à Israël, qui vient pour y louer le nom de l\'Etemel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Car des trônes y sont placés pour le siège de la justice, les trônes de la maison de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Faites des vœux pour la prospérité de Jérusalem! Heureux soient ceux qui t\'aiment!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Que la paix soit dans tes murs, et la sécurité dans tes palais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'En faveur de mes frères et de mes amis, je veux implorer le salut pour toi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'en faveur de la maison de l\'Éternel, notre Dieu, je demanderai pour toi le bonheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Cantique graduel. Vers toi je lève les yeux, ô toi qui résides dans les Cieux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Voici, comme les yeux des serviteurs regardent la main de leurs maîtres, et les yeux de la servante, la main de sa maîtresse, ainsi nos yeux regardent vers l\'Éternel, notre Dieu, attendant qu\'il prenne pitié de nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Prends pitié de nous, Éternel, prends pitié de nous! Car nous sommes assez rassasiés de mépris;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'notre âme est assez rassasiée des railleries des superbes, du mépris des hautains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Cantique graduel. De David. Sans l\'Éternel qui nous fut secourable, (ainsi doit parler Israël)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'sans l\'Éternel qui nous fut secourable, quand les hommes s\'élevaient contre nous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'ils nous auraient engloutis tout vivants, quand leur fureur s\'enflammait contre nous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'alors les eaux nous auraient submergés, et aux torrents notre âme aurait succombé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'alors notre âme aurait succombé aux eaux bouillonnantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Béni soit l\'Éternel, qui ne nous a pas livrés en proie à leurs dents!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Notre âme s\'est échappée, comme l\'oiseau du filet de l\'oiseleur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'le filet fut rompu, et nous nous échappâmes, Notre secours est dans le nom de l\'Éternel, créateur des Cieux et de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Cantique graduel. Ceux qui se confient dans l\'Éternel, sont comme la montagne de Sion, elle est inébranlable et stable éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Des montagnes entourent Jérusalem: ainsi l\'Éternel entoure son peuple dès maintenant à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Car le sceptre de l\'impie ne restera pas sur le lot des justes, afin que les justes ne portent pas leurs mains au mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Éternel, fais du bien aux hommes de bien, et à ceux qui sont droits en leurs cœurs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Pour ceux qui dévient et prennent des voies tortueuses, que l\'Éternel les perde avec les artisans du crime! Paix soit à Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Cantique graduel. Quand l\'Éternel ramenait les captifs de Sion, c\'était pour nous comme un songe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Alors nos bouches se remplirent de cris de joie, et notre langue, de chants d\'allégresse. On disait parmi les nations: « L\'Éternel a fait de grandes choses pour eux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Oui, l\'Éternel a fait de grandes choses pour nous, c\'est ce qui nous rend joyeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Éternel, ramène nos captifs, comme des ruisseaux dans la terre du midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Ceux qui sèment avec larmes, moissonneront avec des cris de joie:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'le semeur s\'avance en pleurant, portant la semence qu\'il jette; il revient tout joyeux chargé de ses gerbes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Cantique graduel. De Salomon. Si l\'Éternel ne bâtit la maison, vainement y travaillent ceux qui l\'édifient; si l\'Éternel ne garde la ville, vainement la sentinelle veille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Vainement vous êtes matineux, restez tard à l\'œuvre, mangez un pain de labeur: Il en donne tout autant à son bien-aimé durant le sommeil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Voici, des fils sont un don de l\'Éternel, et le fruit du sein maternel est une récompense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Tels les traits dans la main d\'un guerrier, tels sont les fils de notre jeune âge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Heureux l\'homme qui en a son carquois rempli! il ne sera point confondu, quand aux Portes il plaidera contre sa partie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Cantique graduel. Heureux l\'homme qui craint l\'Éternel, qui marche dans ses voies!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Oui, tu jouiras du fruit de tes travaux; à toi félicité et bonheur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Ta femme est comme une vigne féconde dans l\'intérieur de ta maison; tes fils, comme des tiges d\'olivier, entourent ta table.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Voyez, ainsi est béni qui craint l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'De Sion l\'Éternel t\'enverra ses bénédictions, et le bonheur de Jérusalem réjouira ton regard tout le temps de ta vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'Tu verras les enfants de tes enfants. Paix soit à Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Cantique graduel. Dès mon jeune âge ils m\'ont beaucoup opprimé, (qu\'ainsi parle Israël!)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'dès mon jeune âge ils m\'ont beaucoup opprimé, mais ils n\'ont pu l\'emporter sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Ils ont déchiré mon dos, comme ceux qui labourent, ils y ont tracé de longs sillons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'L\'Éternel est juste, Il a rompu les fers où me retenaient des impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Qu\'ils soient confondus, et fassent retraite tous ceux qui haïssent Sion!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Qu\'ils soient comme l\'herbe des toits, qui sèche, avant d\'être arrachée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'dont le moissonneur ne remplit point sa main, dont le lieur ne charge point son bras;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'et les passants ne disent pas: « Que l\'Éternel vous bénisse! Nous vous bénissons au nom de l\'Éternel! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Cantique graduel. Du fond des abîmes je t\'implore, Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Seigneur, entends ma voix! Que ton oreille soit attentive à ma prière!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Si tu gardes la mémoire des transgressions, Éternel, Seigneur, qui est-ce qui subsistera?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Mais non, le pardon est par devers toi, afin qu\'on te craigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'J\'espère dans l\'Éternel, mon âme espère, et je compte sur sa promesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Mon âme attend l\'Éternel, plus que la sentinelle n\'attend le matin, que la sentinelle n\'attend le matin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Israël, espère dans l\'Éternel! car la miséricorde est par devers l\'Éternel, et Il a par devers lui un trésor de rédemption.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Et Il rachètera Israël de toutes ses transgressions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Cantique graduel. De David. Éternel, mon cœur est sans orgueil, et mes yeux sans fierté; je ne m\'engage point dans les choses trop grandes ou trop relevées pour moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Oui, je maintiens mon âme tranquille et calme: tel auprès de la mamelle est un enfant sevré, tel un enfant sevré, telle est mon âme en moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Israël, espère dans l\'Éternel dès maintenant à l\'éternité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Cantique graduel. Éternel, souviens-toi de David, et de toutes ses tribulations!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Il fit à l\'Éternel ce serment, ce vœu au Dieu puissant de Jacob:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, '« Je ne rentre point sous le toit de ma maison, et je ne monte point vers le lit où je repose;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'je n\'accorde ni le dormir à mes yeux, ni le sommeil à mes paupières,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'que je n\'aie trouvé un séjour pour l\'Éternel, une demeure pour le Dieu puissant de Jacob. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Voici, nous apprenions qu\'elle était à Ephrata, puis nous la trouvions dans les champs de Jahar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Rendons-nous à Sa demeure, prosternons-nous devant Son marchepied!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Lève-toi, Éternel, viens à ton lieu de repos, toi, et l\'arche de ta majesté!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Que tes prêtres soient vêtus de la grâce, et que tes saints poussent des cris de joie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Pour l\'amour de David, ton serviteur, ne rebute pas ton Oint!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'L\'Éternel fit à David un serment véridique, Il n\'en reviendra point: « Je mettrai sur ton trône un fruit de tes entrailles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Si tes fils gardent mon alliance et les lois que je leur enseigne, leurs enfants aussi à jamais seront assis sur ton trône. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Oui, l\'Éternel a fait choix de Sion, Il veut y fixer sa demeure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, '« C\'est ici pour jamais le lieu de mon repos, je veux y demeurer, car je l\'ai choisie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Je veux bénir sa nourriture, et rassasier de pain ses indigents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Et je revêtirai ses prêtres de salut, et ses saints pousseront des cris de joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Là j\'élèverai la puissance de David, et je tiendrai devant mon Oint un flambeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Je revêtirai ses ennemis d\'opprobre, et sur sa tête son diadème brillera. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Cantique graduel. De David. Voyez! qu\'il est beau, qu\'il est doux que des frères vivent ainsi dans l\'union!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Telle l\'huile exquise, qui de la tête descend sur la barbe, sur la barbe d\'Aaron, qui descend jusqu\'au bord de son vêtement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'telle la rosée de l\'Hermon, et celle qui descend sur les montagnes de Sion! Car c\'est là que l\'Éternel envoie bénédiction et vie pour l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Cantique graduel. Sus! bénissez l\'Éternel, vous tous les serviteurs de l\'Éternel, qui pendant les nuits êtes debout dans sa maison!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Elevez vos mains vers son Sanctuaire, et bénissez l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Et de Sion l\'Éternel te bénira, Lui qui a créé les Cieux et la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Alléluia! Louez le nom de l\'Éternel, louez-le, serviteurs de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'qui vous tenez dans la maison de l\'Éternel, dans les parvis de la maison de notre Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Louez Dieu! car l\'Éternel est bon; célébrez son nom! car Il est clément.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Car l\'Éternel s\'est choisi Jacob, Israël, pour son héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Car je sais que l\'Éternel est grand, et notre Seigneur, plus grand que tous les dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Tout ce qu\'il veut, l\'Éternel le fait, dans les Cieux et sur la terre, dans les mers et dans tous les abîmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'C\'est lui qui fait lever les nuages des bouts de la terre, succéder la pluie à la foudre, et sortir les vents de ses arsenaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'qui frappa les premiers-nés de l\'Egypte, depuis les hommes jusqu\'aux animaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'produisit dans ton sein, ô Egypte, des signes et des miracles contre Pharaon et tous ses serviteurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Qui défit des peuples nombreux, et ôta la vie à des rois puissants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'à Sihon, roi de l\'Amoréen, et à Og, roi de Basan, et à tous les rois de Canaan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'et donna leur pays en héritage, en héritage à Israël, son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Seigneur, ton nom est éternel, et ta mémoire se transmet d\'âge en âge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Car l\'Etemel est le défenseur de son peuple, et Il prend pitié de ses serviteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Les idoles des nations sont de l\'argent et de l\'or, c\'est l\'ouvrage de mains d\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Elles ont une bouche, et ne parlent point; des yeux, et ne voient point;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'des oreilles, et n\'entendent point; et même leur bouche ne respire point;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'semblables à elles sont ceux qui les fabriquent, tous ceux qui mettent en elles leur confiance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Maison d\'Israël, bénissez l\'Éternel! Maison d\'Aaron, bénissez l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Maison de Lévi, bénissez l\'Éternel! Adorateurs de l\'Éternel, bénissez l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Que de Sion l\'Éternel soit béni, lui qui réside en Jérusalem! Alléluia!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Louez l\'Éternel! car Il est bon, car sa miséricorde est éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Louez le Dieu des dieux! car sa miséricorde est éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Louez le Seigneur des Seigneurs! car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'qui seul fait de grandes merveilles, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'qui a fait les Cieux avec intelligence, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'qui a étendu la terre sous les eaux, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'qui a créé les grands luminaires, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'le soleil, pour régner sur le jour, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'la lune et les étoiles, pour régner sur la nuit, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'qui frappa l\'Egypte dans ses premiers-nés, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'et en fit sortir Israël, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'd\'une main forte, et d\'un bras étendu, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'qui divisa la mer des algues en deux parts, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'et fit passer Israël au milieu d\'elle, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'et poussa Pharaon et son armée dans la mer des algues, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'qui conduisit son peuple à travers le désert, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'qui frappa de grands rois, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'et fit mourir des rois puissants, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Sihon, roi de l\'Amoréen, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'et Og, roi de Basan, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'et donna leur pays en héritage, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'en héritage à Israël, son serviteur, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'qui dans notre abaissement eut souvenir de nous, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'et nous délivra de nos oppresseurs, car sa miséricorde est éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'qui donne une nourriture à toute chair, car sa miséricorde est éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Louez le Dieu des Cieux! car sa miséricorde est éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Sur les bords des fleuves de Babel nous étions assis, et nous pleurions en pensant à Sion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Aux saules de la contrée nous suspendîmes nos harpes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'car là nos vainqueurs nous demandaient des chants, et nos oppresseurs, de joyeux, cantiques: « Chantez-nous {[} disaient-ils {]} des hymnes de Sion! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Comment chanter les hymnes de l\'Éternel sur une terre étrangère?...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Si je t\'oublie, Jérusalem, que ma droite m\'oublie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Que ma langue s\'attache à mon palais, si de toi, Jérusalem, je perds le souvenir si je ne mets pas Jérusalem au-dessus de la première de mes joies!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Éternel, garde aux enfants d\'Edom la mémoire de la journée de Jérusalem! Alors ils disaient: « Rasez! rasez jusqu\'à ses fondements! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Fille de Babel, qui nous as saccagés, heureux qui te rendra tout ce que tu nous as fait!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Heureux qui saisira, et écrasera tes enfants sur le roc!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'De David. Je veux Te louer de tout mon cœur, et te célébrer en la présence de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'me prosterner dans ton saint temple, et louer ton nom, car tu es bon et fidèle! Tu as donné à ta promesse des effets qui dépassent toute ta renommée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Quand je criai, tu m\'exauças, tu m\'enhardis, donnant force à mon âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Éternel, tous les rois de la terre te loueront, à l\'ouïe des promesses sorties de ta bouche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'et ils célébreront les voies de l\'Etemel, car la gloire de l\'Éternel est grande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'L\'Éternel est élevé, Il découvre l\'humble, et de loin Il reconnaît le superbe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Si je chemine au milieu des angoisses, tu me redonnes la vie, tu opposes ta main à la fureur de mes ennemis, et ta droite me délivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'L\'Éternel agira pour moi jusques au bout. Seigneur, ta miséricorde est éternelle, ne laisse pas tomber les œuvres de tes mains!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Au maître chantre. Cantique de David. Éternel, tu me pénètres et me connais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Tu sais quand je m\'assieds et quand je me lève, de loin tu découvres ma pensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Tu me vois marcher et me reposer, et tu as connaissance de toutes mes voies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Car la parole n\'est pas encore sur ma langue, que déjà, Éternel, tu la connais tout entière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Tu m\'enserres par devant et par derrière, et tu tiens ta main sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Cette science est une merveille pour moi; elle est trop élevée, je ne puis la saisir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Où irai-je loin de ton Esprit, et où fuirai-je loin de ta face?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Si je monte aux Cieux, tu y es; si je prends les Enfers pour ma couche, tu es là!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Si, me soulevant sur les ailes de l\'aurore, j\'allais me loger au bout de la mer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'là aussi ta main me conduirait, et ta droite me saisirait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Et si je dis: Qu\'autour de moi il n\'y ait que ténèbres et que la clarté qui m\'entoure se change en nuit!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'les ténèbres mêmes ne seront pas sombres pour toi, et la nuit sera claire comme le jour, les ténèbres seront ce qu\'est la lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'C\'est toi en effet qui as formé mes reins, m\'as tissé dans le sein maternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'je te loue de la merveille de ma structure. Tes œuvres sont merveilleuses, et mon âme le reconnaît profondément.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Mon corps n\'était point caché à tes yeux, quand j\'étais formé mystérieusement dans les entrailles de la terre, comme des fils qui s\'entrelacent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Quand je n\'étais qu\'une matière informe, tes yeux me voyaient; et dans ton livre étaient marqués tous ensemble mes jours déjà déterminés, lorsque aucun d\'eux n\'existait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Que tes pensées, ô Dieu, sont incompréhensibles pour moi! que la somme en est immense!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Veux-je les compter, les grains de sable sont moins nombreux; je m\'éveille, et je suis encore avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'O Dieu, puisses-tu faire mourir l\'impie! Hommes de sang, éloignez-vous de moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Eux, qui parlent de toi en commettant le crime, disent ton nom pour mentir, ce sont tes ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Ne haïrais-je pas, Éternel, ceux qui te haïssent, et n\'aurais-je pas de l\'horreur pour tes adversaires?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Je les hais d\'une haine sans réserve; ils sont des ennemis pour moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Sonde-moi, ô Dieu, et pénètre mon cœur; éprouve-moi, et connais mes pensées!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Et vois si le chemin que je suis, est celui du crime, et conduis-moi sur la voie des anciens temps!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Au maître chantre. Cantique de David. Éternel, délivre-moi des hommes malfaisants! Garde-moi contre les hommes violents,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'qui complotent le mal dans leur cœur, et toujours sont occupés de guerres!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Ils dardent leur langue, tels que des serpents, et le venin de l\'aspic est sous leurs lèvres. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Garantis-moi, Éternel, contre le bras de l\'impie, et préserve-moi des hommes violents, qui méditent de faire broncher mes pieds!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Des superbes cachent sous mes pas des pièges et des lacs, ils tendent des rets au bord de la voie, et me dressent des embûches. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Je dis à l\'Éternel: Tu es mon Dieu! Éternel, prête l\'oreille à ma voix suppliante!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'L\'Éternel, le Seigneur, est mon puissant secours; tu abrites ma tête au jour de la mêlée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Éternel, n\'accomplis pas les souhaits de l\'impie! Ne laisse pas leur plan réussir; ils en seraient fiers! (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Que sur la tête de ceux qui me cernent, retombent les menaces que prononcent leurs lèvres!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Que sur eux des charbons soient secoués, et qu\'il les précipite dans les flammes, et dans les flots, pour qu\'ils ne se relèvent pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'L\'homme à la langue {[}méchante{]} ne dure pas sur la terre; et le violent, le malheur le poursuit à coups redoublés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Je sais que l\'Éternel fait droit à l\'affligé, et justice aux indigents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Oui, les justes célébreront ton nom; les hommes droits demeurent en ta présence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Au maître chantre. De David. Éternel, je t\'invoque: accours à mon aide! Entends ma voix, quand je t\'invoque!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Que ma prière, comme l\'encens, arrive jusqu\'à toi, et l\'élévation de mes mains, comme l\'offrande du soir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Mets, ô Éternel, une garde devant ma bouche, et surveille la porte de mes lèvres!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Ne laisse pas mon cœur pencher vers le mal, pour commettre des forfaits par impiété, avec les hommes artisans de crime, et pour que je ne goûte pas leurs friandises!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Que le Juste me frappe, c\'est amour; qu\'il me châtie, c\'est de l\'huile sur ma tête; que ma tête ne se refuse pas, si ses coups se répètent! Mais par mes prières je m\'élève contre leur malice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Si du rocher leurs princes sont précipités, alors on ouïra comme mes paroles seront douces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Tels les éclats et les copeaux qui jonchent le sol, ainsi nos os furent semés à la bouche des Enfers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Oui, Éternel, Seigneur, mes yeux se lèvent vers toi; j\'ai recours à toi: ne laisse pas ma vie se perdre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Préserve-moi des pièges qu\'ils me tendent, et des filets des méchants!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Fais tomber les méchants dans leurs propres filets, et qu\'en même temps j\'échappe!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Hymne de David, quand il était dans la caverne. Prière. De ma voix suppliante je crie à l\'Éternel; je prie l\'Éternel de ma voix suppliante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'J\'épanche ma plainte devant lui, je lui expose ma perplexité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Quand en moi mon cœur s\'alarme, tu connais mon sentier. Sur la route où je marche, ils me tendent des pièges,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Regarde à droite, et considère: je n\'ai personne qui me connaisse; tout refuge m\'est ôté, personne ne s\'enquiert de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'J\'élève à toi mes cris, Éternel! Je dis: Tu es mon refuge, mon partage sur la terre des vivants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Ecoute ma plainte, car je suis fort misérable; délivre-moi de mes persécuteurs! car ils l\'emportent sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Tire mon âme de la prison, afin que je célèbre ton nom! Les justes viendront m\'entourer, quand tu auras été mon bienfaiteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Cantique de David. Éternel, entends ma prière, écoute ma supplication! Au nom de ta fidélité, exauce-moi! au nom de ta justice!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'et n\'appelle point en jugement ton serviteur! car aucun des vivants n\'est juste devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Car l\'ennemi poursuit mon âme, foule ma vie contre terre, me pousse dans le lieu ténébreux, vers ceux qui sont morts dès longtemps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Et mon esprit s\'alarme en moi, et mon cœur frissonne au dedans de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Je me rappelle les jours d\'autrefois, je pense à tout ce que tu as fait; je médite tout ce qu\'ont opéré tes mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Je tends mes mains vers toi; comme une terre altérée, mon âme te {[}désire{]}. (Pause)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Hâte-toi, réponds-moi, Éternel! mon esprit se consume; ne me cache pas ta face! sinon, je ressemble aux hommes descendus au tombeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Fais-moi bientôt ressentir ta grâce! car je me confie en toi. Indique-moi la voie qu\'il me faut suivre! car j\'élève mon âme à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Délivre-moi de mes ennemis, Éternel! car auprès de toi je me mets à couvert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Enseigne-moi à faire ta volonté! car tu es mon Dieu. Que ton bon esprit me conduise sur la voie droite!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Pour l\'amour de ton nom, Éternel, tu me sauveras, par l\'effet de ta justice, tu me dégageras de l\'angoisse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'et, dans ta grâce, tu détruiras mes ennemis, et tu feras périr tous ceux qui sont hostiles à mon âme parce que je suis ton serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'De David. Béni soit l\'Éternel, mon rocher, qui forme mes mains au combat, et mes doigts à la bataille,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'lui, mon bienfaiteur et ma citadelle, ma forteresse, et mon libérateur, mon bouclier, mon refuge, lui qui m\'assujettit des peuples!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Éternel, qu\'est-ce que l\'homme, pour que tu le connaisses? l\'enfant d\'Adam, pour que tu t\'occupes de lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'L\'homme est semblable au souffle, et ses jours, à une ombre qui passe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Éternel, incline tes Cieux, et descends! Touche les montagnes, et qu\'elles fument!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Darde la foudre, et disperse-les! Lance tes flèches, et les mets en déroute!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'D\'en haut étends ta main! Délivre-moi, et me tire des grandes eaux, de la main des enfants de l\'étranger,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'dont la bouche profère le mensonge, et dont la droite est une droite parjure!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'O Dieu, je veux te chanter un cantique nouveau, sur le luth à dix cordes je veux te célébrer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'toi, qui accordes au Roi la victoire, toi, qui sauvas ton serviteur David de la funeste épée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Délivre-moi, et me tire de la main des enfants de l\'étranger, dont la bouche profère le mensonge, et dont la droite est une droite parjure!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Afin que nos fils soient comme des plantes grandissant dans leur jeunesse, et nos filles comme des colonnes angulaires sculptées en figures dans les palais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Que nos greniers soient remplis, fournissant toutes sortes de biens! Que nos brebis multiplient par milliers, qu\'elles soient par myriades dans nos champs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Que nos chefs soient élevés! qu\'il n\'y ait ni brèche, ni attaque, ni clameurs dans nos rues!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Heureux le peuple dont il en est ainsi! Heureux le peuple dont l\'Éternel est le Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Cantique de louanges. De David. Je l\'exalterai, ô mon Dieu, ô mon Roi! et je bénirai ton nom toujours, à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Chaque jour je te bénirai, et je louerai ton nom éternellement, à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'L\'Éternel est grand et très glorieux, et sa grandeur est incommensurable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Qu\'un âge à l\'autre âge annonce tes œuvres, et publie tes exploits!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'C\'est la glorieuse majesté de ta magnificence, ce sont tes merveilles que je veux méditer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Qu\'on redise la puissance de tes exploits terribles, et je veux raconter ta grandeur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Que l\'on proclame la mémoire de ta grande bonté, et que l\'on chante ta justice!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'L\'Éternel est miséricordieux et clément, lent à s\'irriter, et riche en grâce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'L\'Éternel est bon envers tous, et sa miséricorde s\'étend à toutes ses œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Éternel, toutes tes œuvres te célèbrent, et tes saints te bénissent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'ils disent la gloire de ton empire, et publient ta puissance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'pour annoncer ta puissance aux enfants des hommes, et le glorieux éclat de ton règne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Ton régne est un règne de tous les siècles, et ton empire se perpétue d\'âge en âge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'L\'Éternel soutient tous ceux qui tombent, et Il redresse ceux qui sont affaissés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Les yeux de tous s\'attendent à toi, et tu leur donnes leur nourriture en son temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Tu ouvres ta main, et tu rassasies de faveurs tous les vivants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'L\'Éternel est juste en toutes ses voies, et miséricordieux en tout ce qu\'il fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'L\'Éternel est près de tous ceux qui l\'invoquent, de tous ceux qui l\'invoquent avec sincérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Il accomplit les vœux de ceux qui le craignent, Il entend leur cri, et leur est secourable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'L\'Éternel garde tous ceux qui l\'aiment, et Il détruit tous les impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Que ma bouche redise la louange de l\'Éternel, et que toute chair bénisse son saint nom, éternellement, à jamais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Alléluia! Mon âme, loue l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Je louerai l\'Éternel, tant que je vivrai; je chanterai mon Dieu, tant que je serai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Ne vous confiez pas dans les princes, dans les enfants des hommes, qui ne peuvent secourir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Leur souffle s\'exhale, ils rentrent dans leur poudre: ce jour-là, c\'en est fait de leurs plans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Heureux celui à qui le Dieu de Jacob est en aide, et dont l\'espoir repose sur l\'Éternel son Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Il a fait les Cieux et la terre, la mer et tout ce qu\'elle contient; Il garde fidélité éternellement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Il rend justice aux opprimés, donne du pain à ceux qui ont faim; l\'Éternel délivre les captifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'L\'Éternel ouvre les yeux aux aveugles, l\'Éternel relève ceux qui sont affaissés; l\'Éternel aime les justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'L\'Éternel prend les étrangers sous sa garde; Il restaure la veuve et l\'orphelin; mais Il fait dévier la voie de l\'impie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'L\'Éternel règne éternellement. Ton Dieu, ô Sion, subsiste dans tous les âges. Alléluia!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Louez l\'Etemel! car il est beau de chanter notre Dieu; c\'est une douceur, la louange est séante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'L\'Éternel relève Jérusalem; Il rassemble les bannis d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Il guérit ceux dont le cœur est blessé, et Il adoucit leurs douleurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Il fixe le nombre des étoiles, et à toutes Il donne leur nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Notre Seigneur est grand, sa puissance est immense, et son intelligence sans mesure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'L\'Éternel restaure les affligés, et Il humilie les impies jusques à terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Chantez l\'Éternel en lui rendant grâces, célébrez notre Dieu avec la harpe!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Il couvre le ciel de nuages, prépare la pluie pour la terre, fait croître l\'herbe sur les montagnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Il donne aux animaux leur pâture, aux petits du corbeau qui appellent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Ce n\'est pas la force du coursier qui lui plaît, ni les jambes du piéton qui lui sont agréables;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'l\'Éternel se complaît dans ceux qui le craignent, dans ceux qui espèrent en sa grâce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Jérusalem, loue l\'Éternel! Célèbre ton Dieu, ô Sion!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Car Il affermit les verroux de tes Portes, et bénit tes fils dans ton enceinte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Il met la paix à tes frontières, Il te rassasie de la moelle du froment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Il envoie ses ordres à la terre, sa parole court avec célérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Il fait tomber la pluie, comme de la laine, et Il répand le givre, comme de la cendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Il précipite sa glace en parcelles menues; qui pourra tenir devant ses frimas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Il émet sa parole, et Il les fait fondre, Il fait souffler le vent, et les eaux sont fluides.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Il a révélé sa parole à Jacob, ses statuts et ses lois à Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Il ne l\'a pas fait pour tous les peuples, qui de ses lois n\'ont point connaissance. Louez l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Alléluia! Des Cieux louez l\'Éternel! Louez-le dans les lieux très-hauts!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Louez-le, vous tous ses anges! Louez-le, vous toutes ses armées!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Louez-le, soleil et lune! Louez-le, vous toutes les étoiles brillantes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Louez-le, Cieux des Cieux, et vous les eaux, qui êtes au-dessus des Cieux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Qu\'ils louent le nom de l\'Éternel! Car Il commanda, et ils furent créés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'et Il les établit pour jamais, pour l\'éternité; Il leur donna des lois, et ils ne les transgressent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'De la terre louez l\'Éternel! bêtes de la mer, et vous tous les abîmes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'feu et grêle, neige et brouillard, vent des tempêtes, qui exécutez ses ordres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'montagnes et toutes les collines, arbres à fruit, et vous tous les cèdres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'animaux, et vous tous les bestiaux, reptiles et oiseaux ailés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'rois de la terre, et vous tous les peuples, princes, et vous tous les juges de la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'jeunes hommes et vierges, vieillards de concert avec les enfants!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Qu\'ils louent le nom de l\'Éternel! Car son nom seul est éminent, sa magnificence est plus haute que la terre et les Cieux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'et Il relève la tête de son peuple, la gloire de tous ses saints, des enfants d\'Israël, du peuple qui Lui tient de près. Alléluia!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Alléluia! Chantez à l\'Éternel un cantique nouveau, ses louanges dans l\'assemblée des saints!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Qu\'Israël se réjouisse de son créateur, que les fils de Sion tressaillent pour leur Roi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Qu\'ils célèbrent son nom par des chœurs, et qu\'ils Le chantent au son des cymbales et des harpes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Car l\'Éternel se complaît dans son peuple, Il donne aux affligés la parure du salut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Que les saints se réjouissent de la gloire, que sur leurs lits ils poussent des cris d\'allégresse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Que les louanges de Dieu soient dans leur bouche, et l\'épée à deux tranchants dans leurs mains,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'pour exercer des vengeances sur les nations, et des châtiments sur les peuples;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'pour lier leurs rois de chaînes, et leurs princes avec des ceps de fer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'pour exécuter sur eux la loi écrite! C\'est une gloire pour tous Ses saints. Alléluia!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Alléluia! Louez Dieu dans son Sanctuaire! Louez-le dans son glorieux firmament!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Louez-le pour ses hauts faits! Louez-le à proportion de sa grandeur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Louez-le au son de la trompette! Louez-le avec le luth et la harpe!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Louez-le avec les cymbales et en chœur! Louez-le au son des cordes et du chalumeau!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Louez-le avec les cymbales sonores! Louez-le avec les cymbales bruyantes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Que tout ce qui respire loue l\'Éternel! Alléluia!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Proverbes de Salomon, fils de David, roi d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'pour connaître la sagesse et la discipline, pour acquérir le sens des paroles de sens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'pour recevoir les leçons de la prudence, de l\'équité et de la justice et de la droiture,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'pour donner la raison aux simples, et au jeune homme la connaissance et la pensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Que le sage écoute, et il augmentera sa conception, et l\'expert gagnera de prudents conseils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'pour comprendre les sentences et les discours voilés, les propos des sages et leurs énigmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'La crainte de l\'Éternel est le principe de la connaissance, les insensés méprisent la sagesse et la discipline.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Ecoute, mon fils, la leçon de ton père, et ne néglige point la remontrance de ta mère!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Car elles sont à ta tête une couronne gracieuse, et des joyaux à ton col.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Mon fils, si des pécheurs veulent t\'entraîner, n\'y donne pas ton consentement!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'S\'ils disent: « Viens avec nous, épions le sang, dressons des pièges à l\'innocent, qui l\'est en vain;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'engloutissons-les, comme les Enfers font des vivants, les innocents, comme ceux qui descendent dans la fosse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'nous gagnerons tous les trésors de prix, nous remplirons nos maisons de dépouilles');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'tu tireras au sort ton lot avec nous, nous ferons tous bourse commune, » –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'mon fils, ne fais pas route avec eux; tiens ton pied loin de leur voie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Car leurs pieds courent à ce qui est mal. ils se hâtent pour aller répandre le sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Mais en vain le filet se déploie aux yeux de l\'oiseau:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'eux, c\'est leur propre sang qu\'ils épient, et c\'est à leur vie même qu\'ils dressent des pièges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Tel est le chemin de tous les hommes avides du gain, lequel ôte la vie à celui qui l\'obtient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'La sagesse crie dans les rues, et sur les places fait entendre sa voix;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'à l\'angle des rues bruyantes elle fait son appel; à l\'avenue des Portes, dans la ville, elle dit ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, '« Jusques à quand, faibles, aimerez-vous la faiblesse, et les moqueurs se plairont-ils dans la moquerie, et les présomptueux haïront-ils la connaissance?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Revenez à ma discipline! Voici, je verserai sur vous mon esprit, et vous ferai connaître mes paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Or, puisque j\'appelai, et que vous fûtes rénitents, que j\'étendis la main, et que nul n\'y prit garde,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'et que vous avez dédaigné tous mes conseils, et n\'avez point aimé ma discipline;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'à mon tour je me rirai de vos maux; je me moquerai, quand l\'alarme vous surviendra,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'lorsque, comme l\'ouragan, l\'alarme vous surviendra et que votre ruine s\'avancera comme la tempête; lorsque vous surviendront la détresse et l\'angoisse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Alors ils m\'invoqueront, mais je ne répondrai pas, ils me chercheront, mais ne me trouveront pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Parce qu\'ils ont haï la science, et n\'ont pas fait choix de la crainte de l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'qu\'ils n\'ont point voulu de mes conseils, et qu\'ils ont méprisé toutes mes leçons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'ils se repaîtront du fruit de leurs voies, et se rassasieront de leurs propres conseils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Car les faibles trouvent la mort dans leur défection, et les présomptueux, leur perte dans leur sécurité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'mais qui m\'écoute habitera sûrement, il sera tranquille, sans crainte de revers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'O mon fils, si tu accueillais mes paroles, et serrais mes commandements en ton cœur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'prêtant l\'oreille à la sagesse, et pliant ton cœur à la prudence!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Car, si tu invoques la sagesse, si vers la prudence tu fais monter ta voix;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'si tu la cherches comme l\'argent, si comme un trésor caché tu veux la découvrir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'alors tu comprendras la crainte de l\'Éternel, et tu trouveras la connaissance de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Car l\'Éternel donne la sagesse; de sa bouche sortent connaissance et prudence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Il tient pour les hommes droits le salut en réserve Il est un bouclier pour ceux qui vivent innocents,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'protégeant les sentiers de la justice, et veillant sur la voie de ses adorateurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Alors tu comprendras la justice et la loi et la droiture, et toute bonne voie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Si la sagesse entre en ton cœur, et si la science a de l\'attrait pour ton âme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'la circonspection veillera sur toi, et la prudence te gardera,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'pour te sauver de la voie du méchant, de l\'homme qui parle par détours,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'de ceux qui quittent le droit chemin, pour suivre des voies ténébreuses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'qui trouvent de la joie à faire le mal, du bonheur aux détours de la malice;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'dont les voies sont détournées, et les sentiers tortueux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'pour te sauver de la femme d\'autrui, de l\'étrangère qui prend une langue flatteuse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'abandonne l\'ami de sa jeunesse, et oublie l\'alliance de son Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'car sa maison s\'abîme dans la mort, et ses voies mènent chez les ombres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'tous ceux qui y vont, n\'en reviennent point, et ne retrouvent plus le chemin de la vie. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Ainsi, marche dans la voie des gens de bien, et suis le chemin des justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Car les justes habiteront le pays, et les innocents y seront laissés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'mais les impies seront arrachés du pays, et les traîtres en seront bannis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Mon fils, n\'oublie pas mes leçons, et que ton cœur garde mes préceptes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Car ils prolongeront tes jours et tes années de vie, et te donneront la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Que l\'amour et la vérité ne te quittent pas; lie-les à ton col, écris-les sur les tablettes de ton cœur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Alors tu trouveras grâce et bon succès devant Dieu et devant les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Confie-toi en Dieu de tout ton cœur, et ne t\'appuie pas sur ton propre sens!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'En toutes tes voies regarde vers Lui, et Il aplanira tes sentiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Ne sois point sage à tes propres yeux; crains l\'Éternel, et fuis le mal!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'ce sera la santé de ton corps, et le rafraîchissement de tes os.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Honore Dieu avec ta richesse, et avec les prémices de tout ton revenu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'et tes greniers se rempliront d\'abondance, et de moût tes cuves regorgeront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Ne méprise pas, mon fils, la correction de l\'Éternel, et ne t\'irrite point de ses châtiments!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Car c\'est celui qu\'il aime que l\'Éternel châtie, comme un père l\'enfant auquel il prend plaisir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Heureux l\'homme qui trouve la sagesse, et l\'homme qui obtient la prudence!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Car son acquisition vaut mieux que celle de l\'argent, et ce qu\'elle rapporte, est meilleur que l\'or fin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'elle a plus de prix que les perles, et tout ce que tu as de précieux ne lui équivaut pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Longue vie est dans sa main droite; dans sa gauche, richesse et honneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Ses voies sont des voies de délices, et tous ses sentiers sont des sentiers de paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Elle est un arbre de vie pour ceux qui la saisissent, et qui la tient ferme en est rendu heureux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Par la sagesse l\'Éternel a fondé la terre, et élevé les Cieux par son intelligence;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'par sa science Il ouvrit les abîmes, et fit des nues distiller la rosée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Mon fils, ne les perds pas de vue, garde la sagesse et la réflexion!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'Elles donneront vie à ton âme, et parure gracieuse à ton col.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Alors d\'un pas sûr tu marcheras dans ta voie, et ton pied ne heurtera point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'En te couchant tu seras sans peur, et couché tu auras un doux sommeil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Ne redoute pas l\'alarme soudaine, ni l\'attaque des méchants qui surviendrait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'car l\'Éternel sera ton assurance, et Il empêchera ton pied d\'être pris dans le piège.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Ne refuse pas un bienfait à celui qui y a droit, quand tu as le pouvoir de l\'accorder.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Ne dis pas à ton prochain: « Va-t\'en et reviens, demain je te donnerai! » quand tu as de quoi donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Ne machine pas du mal contre ton prochain, qui habite en confiance auprès de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'N\'entre avec personne en procès sans cause, quand tu n\'as pas été provoqué par un tort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Ne porte pas envie à l\'homme violent, et ne choisis aucune de ses voies,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'car l\'homme faux est l\'abomination de l\'Éternel, mais aux hommes droits Il donne son amitié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'La malédiction de l\'Éternel est sur la maison de l\'impie, mais Il bénit la demeure des justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'S\'il se moque des moqueurs, aux humbles Il accorde sa grâce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Les sages ont l\'honneur pour héritage, mais les insensés recueillent la honte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Ecoutez, mes fils, la leçon d\'un père, et soyez attentifs, pour apprendre la sagesse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Car je vous donne une doctrine excellente; n\'abandonnez pas mes préceptes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Car je fus un fils pour mon père, tendre et unique enfant sous les yeux de ma mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Et il m\'instruisit et me dit: Que ton cœur retienne fermement mes paroles, observe mes préceptes, et tu auras la vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Acquiers la sagesse, acquiers la prudence, ne l\'oublie pas, et ne t\'écarte pas des paroles de ma bouche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Ne l\'abandonne pas, et elle te gardera; aime-la; et elle te protégera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Voici le commencement de la sagesse « Acquiers la sagesse, et au prix de tout ton bien acquiers la prudence. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Exalte-la, et elle l\'élèvera; elle t\'honorera, si tu l\'embrasses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'elle posera sur ta tête une couronne gracieuse, et te présentera un brillant diadème.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Ecoute, mon fils, et accueille mon discours, et pour toi les années de vie se multiplieront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'C\'est la voie de la sagesse que je te montre, et je te conduis au droit sentier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Si tu marches, tes pas ne seront pas gênés; et si tu cours, tu ne trébucheras point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Tiens ferme l\'instruction, ne t\'en dessaisis point; garde-la, car elle est ta vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Ne t\'engage pas dans la route des impies, et ne t\'avance pas sur la voie des méchants!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Quitte-la, n\'y passe pas; fuis-la et passe outre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Car ils ne sauraient dormir, s\'ils n\'ont fait le mal, et le sommeil se dérobe à eux, s\'ils n\'ont causé des chutes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Oui, l\'impiété est le pain qu\'ils prennent, et l\'iniquité, le vin qu\'ils boivent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Mais la voie des justes est comme l\'éclat du soleil, dont la lumière croît jusqu\'au plus haut point du jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'La voie des impies est comme les ténèbres; ils ne savent où ils iront heurter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Mon fils, sois attentif à mes paroles, et prête l\'oreille à mes discours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Ne les perds pas de vue; garde-les dans le fond de ton cœur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Car ils sont une vie pour ceux qui les trouvent, et un remède pour leur corps tout entier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Plus que tout ce qui se garde, garde ton cœur! car de lui jaillissent les sources de la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Eloigne de ta bouche la fausseté, et de tes lèvres les détours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Que tes yeux regardent en avant, et que tes paupières dirigent ta vue devant toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Examine le chemin où tu mets le pied, et que toutes tes voies soient fermes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'ne fléchis ni à droite, ni à gauche, et retiens ton pied loin du mal!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Mon fils, fais attention à ma sagesse, et prête l\'oreille à ma prudence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'pour garder les bonnes pensées, et conserver le jugement sur tes lèvres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Car les lèvres de l\'étrangère distillent du miel, et son palais est plus onctueux que l\'huile;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'mais sa fin est plus amère que l\'absinthe, elle est aiguë comme l\'épée à deux tranchants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Ses pieds descendent au séjour de la mort, et ses pas aboutissent aux Enfers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Pour que tu ne prennes point garde au chemin de la vie, ses voies s\'égarent, et tu ne le sais pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Et maintenant, mes fils, écoutez-moi, et ne vous écartez pas des paroles de ma bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Prends ta route loin d\'elle, et ne t\'approche pas de la porte de sa maison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'pour que tu ne livres pas à d\'autres la fleur de tes jours, ni tes années à l\'homme cruel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'pour que des étrangers ne se rassasient pas de ton bien, et que le fruit de ton labeur n\'aille pas en maison étrangère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'pour que tu n\'aies pas à gémir sur ta fin, quand ta chair et ton corps auront dépéri,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'disant: Comment ai-je pu haïr la discipline? comment mon cœur a-t-il repoussé la correction?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'et n\'écoutai-je point la voix de mes maîtres, et ne prêtai-je point l\'oreille à mes instituteurs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Peu s\'en faut que je ne sois tombé dans tous les maux au milieu du peuple et de l\'assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Bois l\'eau de ta citerne, et celle qui coule de ta fontaine:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'sinon tes sources se répandront au dehors, et comme des ruisseaux couleront sur les places;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'ils seront pour toi seul, et non pour des étrangers en même temps que pour toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Que ta source soit bénie, et fais ton bonheur de la femme de ta jeunesse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'biche aimable, gazelle gracieuse: que son sein t\'enivre toujours, et de son amour sois constamment épris!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Et pourquoi t\'éprendrais-tu, mon fils, d\'une étrangère, et embrasserais-tu le sein d\'une inconnue?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Car les voies de l\'homme sont découvertes devant Dieu, et Il observe tous ses sentiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'L\'impie se prend dans ses propres péchés, et il est retenu par les lacs de son iniquité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Il mourra faute de discipline, et sa grande folie lui donnera le vertige.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Mon fils, si tu as cautionné ton prochain, si pour un autre tu as donné ta main,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'si tu es engagé par les paroles de ta bouche, lié par les paroles de ta bouche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'ah! fais ceci, mon fils, dégage-toi, car tu es tombé entre les mains de ton prochain! Va et te jette à ses pieds, et presse instamment ton prochain!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'N\'accorde ni sommeil à tes yeux, ni assoupissement à les paupières!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Dégage-toi, comme la gazelle, de la main, comme l\'oiseau, de la main de l\'oiseleur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Va vers la fourmi, paresseux! observe ses voies, et deviens sage!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Elle n\'a ni prince, ni chef, ni souverain;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'cependant elle fait en été ses provisions, et durant la moisson recueille sa nourriture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Jusques à quand, paresseux, seras-tu couché? quand te lèveras-tu secouant ton sommeil?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, '« Un peu dormir, un peu sommeiller, un peu croiser les bras en étant couché! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'Ainsi, la pauvreté fondra sur toi, comme un larron, et l\'indigence, comme un homme portant le bouclier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Il est un indigne l\'homme faux, dont la bouche s\'écarte de la droiture,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'qui cligne les yeux, parle du pied, et fait entendre du doigt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Les détours sont dans son cœur, il trame le mal en tout temps, et excite les rixes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Aussi sa ruine arrivera tout-à-coup, soudain il sera brisé, et sans remède.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Il y a six choses que hait l\'Éternel, et sept qui sont l\'abomination de son âme:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'les yeux hautains, la langue menteuse, et les mains qui répandent le sang innocent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'un cœur qui médite des projets pernicieux, des pieds empressés à courir au mal;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'celui qui, faux témoin, profère des mensonges, et celui qui excite des querelles entre les frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Garde, mon fils, le précepte de ton père, et ne néglige pas les leçons de ta mère!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Tiens-les toujours attachés à ton cœur, et liés à ton col!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Si tu chemines, ils te garderont; si tu es couché, ils veilleront sur toi; à ton réveil ils t\'entretiendront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Car le précepte est un flambeau, et la leçon une lumière, et les remontrances de la sagesse sont la voie de la vie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'pour te préserver de la femme mauvaise, du doux parler de la langue étrangère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Ne convoite point sa beauté dans ton cœur, et que ses paupières ne te captivent pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Car pour une impudique on se réduit à un morceau de pain, mais la femme mariée tend un piège à la vie qui est chère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Met-on du feu dans son sein, sans que les vêtements en soient embrasés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Marche-t-on sur des charbons ardents, sans que les pieds en soient brûlés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'De même pour celui qui va vers la femme de son prochain: qui la touchera, ne restera pas impuni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'On ne néglige pas le voleur, quand il vole pour satisfaire son désir, parce qu\'il a faim;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'mais surpris, il restitue sept fois, et livre tout le bien de sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Qui commet adultère avec une femme, n\'a point la raison qui veut se perdre, le fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Il trouve des coups et de la honte, et son opprobre ne s\'efface point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Car la jalousie est une fureur pour l\'homme; il sera sans pitié au jour de la vengeance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'il n\'aura égard à aucune rançon, et n\'acceptera pas, quand tu multiplierais les dons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Mon fils, conserve mes paroles, et serre mes préceptes dans ton cœur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Conserve mes préceptes, pour avoir la vie, et mes leçons, comme la prunelle de tes yeux:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'attache-les à tes doigts, écris-les sur les tablettes de ton cœur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Dis à la sagesse: Tu es ma sœur! et appelle la prudence ton amie intime!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'pour qu\'elle te garde de la femme d\'autrui, de l\'étrangère dont la langue est flatteuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Car, étant à la fenêtre de ma maison, je regardais à travers mes jalousies:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'et je vis parmi les inconsidérés, je remarquai entre les fils un jeune homme sans raison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Il passait dans la rue près de l\'angle où elle se tenait. et il prenait le chemin de sa demeure:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'c\'était au crépuscule, au déclin du jour, quand la nuit est noire et obscure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Et voici, une femme vint au devant de lui ayant la mise d\'une courtisane, et possédant son cœur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'elle était agitée, et sans frein; ses pieds ne se tenaient point dans sa maison;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'tantôt dans la rue, tantôt dans les places, elle était aux aguets près de tous les angles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Et elle le saisit et l\'embrassa, et d\'un air effronté lui dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, '« Je devais un sacrifice d\'actions de grâces, aujourd\'hui j\'ai acquitté mon vœu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'C\'est pourquoi je suis sortie au devant de toi, pour chercher ton visage, et je t\'ai trouvé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Sur mon lit j\'ai étendu des couvertures, des tapis diaprés de lin d\'Egypte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'j\'ai répandu sur ma couche la myrrhe, l\'aloès et le cinnamome.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Viens, enivrons-nous d\'amour jusqu\'au matin, et délectons-nous par des caresses!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Car mon mari n\'est pas au logis, il voyage au loin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'il a pris avec lui la bourse de l\'argent; il revient à la maison le jour de la pleine lune! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Elle le séduisit par tous ses discours, et l\'entraîna par le doux langage de ses lèvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Il la suit soudain, comme le bœuf va à la tuerie, comme les chaînes {[}que traîne{]} le fou qu\'on châtie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'jusqu\'à ce qu\'une flèche lui perce le foie; comme l\'oiseau qui se précipite dans les lacs, ignorant qu\'ils menacent sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Or maintenant, mes fils, écoutez-moi, et soyez attentifs aux paroles de ma bouche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Ne laisse pas ton cœur incliner vers sa voie, et ne t\'égare pas dans ses sentiers!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Car elle en a percé et fait tomber plusieurs, et ils sont nombreux tous ceux qu\'elle a tués.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Sa maison est la route des Enfers, elle fait descendre au séjour de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'La sagesse n\'appelle-t-elle pas, et la prudence ne fait-elle pas entendre sa voix?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Elle se tient au sommet des éminences, sur le chemin, dans les carrefours;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'à côté des Portes, à l\'entrée de la ville, aux avenues des Portes, elle dit à haute voix:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, '« C\'est vous, ô hommes, que j\'appelle, et ma voix s\'adresse aux enfants des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Hommes sans raison, apprenez la prudence, et vous, insensés, apprenez la sagesse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Ecoutez! car je dis des choses relevées, et mes lèvres s\'ouvrent pour énoncer la droiture:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'car ma bouche exprime la vérité, et mes lèvres abhorrent l\'impiété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'La rectitude est dans tous les mots de ma bouche; ils n\'ont rien de tortueux, ni de détourné;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'ils sont évidents pour le sage, et justes pour ceux qui ont trouvé la science.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Prenez mes leçons, et non pas de l\'argent, et la science plutôt que l\'or de choix;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'car la sagesse vaut mieux que les perles, et nulle chose de prix n\'est son équivalent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Moi, la sagesse, j\'habite avec la prudence, et je trouve la science des bonnes mesures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'La crainte de l\'Éternel est la haine du mal, de l\'orgueil, de la hauteur, et des mauvaises voies; et je hais la bouche trompeuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'J\'ai le conseil et le succès, je suis l\'intelligence, je possède la force.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Par moi les rois règnent, et les princes font de justes lois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'par moi les puissants exercent le pouvoir, ainsi que les grands, tous juges de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'J\'aime ceux qui m\'aiment, et ceux qui me cherchent, me trouvent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'La richesse et l\'honneur m\'accompagnent, l\'opulence solide et la bonté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'mes fruits sont meilleurs que l\'or, que l\'or pur, et ce que je rapporte est plus que de l\'argent de choix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Je marche dans le chemin de la justice, et dans les sentiers de l\'équité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'pour rendre ceux qui m\'aiment possesseurs d\'un avoir, et remplir leurs greniers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, '« L\'Éternel me créa, prémices de ses œuvres, avant ses ouvrages, antérieurement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Dès l\'éternité je reçus l\'onction, avant le commencement, l\'origine de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'quand je naquis, les mers n\'étaient pas encore, il n\'y avait point de sources abondantes en eau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'avant que les montagnes fussent plantées, avant les collines j\'étais enfantée:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Il n\'avait encore créé ni la terre, ni les déserts, ni le chef de la poudre de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Quand Il disposait le ciel, j\'étais là; quand Il traçait un cercle sur la face de l\'abîme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'quand d\'en haut Il condensait les nues, et faisait bouillonner les sources de l\'abîme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'quand Il donnait à la mer ses limites, pour que les eaux ne franchissent pas ses bords, quand Il fixait les bases de la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'j\'étais à ses côtés, fidèle ouvrière, je faisais ses délices tous les jours, me jouant devant lui continuellement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'jouant sur le disque de sa terre, et faisant mes délices des enfants des hommes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Maintenant donc, mes fils, écoutez-moi! et heureux ceux qui se tiennent dans mes voies!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Recevez la correction, et devenez sages, et ne la repoussez pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Heureux l\'homme qui m\'écoute, veillant à ma porte journellement, et gardant les jambages de mon portail!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Car, quiconque me trouve, a trouvé la vie, et il obtient la faveur de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Mais celui qui me manque, fait tort à son âme; tous ceux qui me haïssent, aiment la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'La sagesse a édifié sa maison, et en a taillé les sept colonnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'elle a égorgé ses victimes, mêlé son vin, et dressé sa table.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Envoyant ses suivantes elle invite, du faîte des hauteurs de la ville:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '« Quiconque est faible, qu\'il entre ici! » Et elle dit à qui manque de sens:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '« Venez, mangez de mon pain, et buvez du vin que j\'ai mêlé!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Renoncez à la faiblesse, et vous aurez la vie, et suivez la voie de la raison!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Qui corrige le moqueur, s\'attire un affront, et qui reprend l\'impie, un outrage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Ne corrige pas le moqueur, de peur qu\'il ne te haïsse! Corrige le sage, et il t\'aimera!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Donne au sage, il devient plus sage encore; instruis le juste, il augmente sa science.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Le principe de la sagesse, c\'est la crainte de l\'Éternel; et la connaissance du Très-haut, c\'est l\'intelligence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Oui, je multiplie le nombre de tes jours, et j\'augmente celui de tes années de vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Es-tu sage, c\'est pour toi que tu es sage; et, si tu es un moqueur, seul tu en subiras la peine. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Il est encore une femme, la folie; elle est agitée, irréfléchie et ignorante de toutes choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Elle se place à la porte de sa maison, sur un siège au haut de la ville,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'pour inviter les passants, qui marchent droit dans leur voie:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, '« Que les faibles entrent ici! » Et elle dit à celui qui manque de sens:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '« L\'eau dérobée est douce, et le pain mangé en cachette est agréable. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Et il ne sait pas que là sont les ombres, et que ses invités sont dans les vallées des Enfers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Maximes de Salomon. Un fils sage est la joie d\'un père; et un fils insensé, le chagrin de sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Les gains iniques ne profitent pas; mais la justice sauve de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'L\'Éternel ne laisse pas le juste souffrir de la faim; mais Il repousse la convoitise des impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Celui qui travaille d\'une main lâche, s\'appauvrit; mais la main des diligents enrichit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Qui recueille en été, est un fils sensé; qui dort pendant la moisson, est un fils qui fait honte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Il y a des bénédictions pour la tête du juste; mais l\'iniquité recouvre la bouche de l\'impie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'La mémoire du juste demeure en bénédiction; mais le nom des impies tombe en pourriture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Celui qui a la sagesse dans le cœur, accueille les préceptes; mais celui qui a la folie sur les lèvres, court à sa perte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Qui suit la voie de l\'innocence, suit une voie sûre; mais qui prend des voies tortueuses, sera démasqué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Celui qui cligne les yeux, est une cause de chagrin; et l\'insensé parleur court à sa ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'C\'est une source de vie que la bouche du juste; mais l\'injustice couvre la bouche des impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'La haine provoque les querelles; mais sur tous les manquements l\'amour met un voile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Sur les lèvres de l\'homme de sens se trouve la sagesse; mais la verge va au dos de qui manque de raison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Les sages tiennent la science en réserve; mais la bouche de l\'impie est une ruine qui menace.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'L\'avoir du riche est sa forteresse; la ruine du pauvre, c\'est sa pauvreté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Le gain du juste est une cause de vie; le revenu de l\'impie, une cause de péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Celui-là est le chemin de la vie qui garde la discipline, mais celui qui néglige la correction, induit en erreur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Dissimuler la haine, c\'est avoir des lèvres qui mentent; publier la calomnie, c\'est être méchant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'En parlant beaucoup, on ne manque pas de pécher; mais qui réfrène ses lèvres, agit prudemment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'La langue du juste est un argent de choix; le cœur des impies est bien peu de chose.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Les lèvres du juste donnent la pâture à plusieurs; mais les insensés périssent par défaut de raison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'La bénédiction de Dieu, c\'est elle qui enrichit, et le pénible labeur n\'y peut rien ajouter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'C\'est une joie pour l\'insensé de commettre le crime; et d\'être sage, pour l\'homme de sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Ce que redoute l\'impie, c\'est ce qui lui arrive; mais {[}Dieu{]} accomplit les vœux des justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Comme passe l\'ouragan, ainsi disparaît l\'impie, mais le juste est une fondation éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Ce que le vinaigre est au dents, et la fumée aux yeux, tel est le paresseux pour celui qui l\'envoie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'La crainte de l\'Éternel prolonge les jours; mais les années des impies sont abrégées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'L\'attente des justes devient joie; et l\'espoir des impies, désastre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Pour l\'innocence la voie de l\'Éternel est un fort; mais une ruine pour les méchants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Le juste est à jamais inébranlable; mais les impies n\'habiteront pas le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'La bouche du juste pousse des jets de sagesse; mais la langue dépravée est arrachée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Les lèvres du juste connaissent la grâce; et la bouche de l\'impie, la perversité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'La balance fausse est l\'abomination de l\'Éternel; mais le poids juste lui est agréable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Quand vient l\'orgueil, vient aussi l\'ignominie; mais dans les humbles il y a sagesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'L\'intégrité des hommes droits les guide; mais les détours des perfides les perdent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'La richesse ne sert de rien au jour de la colère; mais la justice sauve de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'La justice de l\'homme de bien aplanit sa voie; mais par sa méchanceté le méchant tombera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'La justice des hommes droits les sauve; mais les méchants se prennent dans leur méchanceté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'A la mort du méchant son espoir s\'évanouit, et l\'attente des impies s\'évanouit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Le juste est sauvé de la détresse, et l\'impie vient l\'y remplacer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Par ses discours le profane perd son prochain, mais par la sagesse des justes il est sauvé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'La ville se réjouit du bonheur du juste; et quand les méchants périssent, c\'est chant de joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'La bénédiction du juste élève une cité, mais les propos des impies causent sa décadence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Qui parle avec mépris de son prochain, manque de sens; mais l\'homme qui a la prudence, se tait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Qui va calomniant, dévoile les secrets; mais l\'homme sûr tient la chose cachée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Faute de directions un peuple tombe; mais il y a salut où les conseillers sont en nombre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Mal en arrive à qui cautionne autrui; mais quand on hait ceux qui s\'engagent de la main, on est en sûreté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'La femme qui a la grâce, est en possession de l\'honneur, comme ceux qui ont la force, le sont des richesses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Celui qui en use bien avec lui-même, a de la bonté; mais celui qui se maltraite, est impitoyable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'L\'impie fait un gain qui le trompe; et celui qui sème la justice, un gain assuré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'L\'homme ferme en la justice parvient à la vie; et celui qui poursuit le mal, à la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'L\'Éternel abhorre les hommes pervertis en leur cœur; Il a pour agréables ceux qui suivent le droit chemin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Qu\'ils se donnent la main, les méchants ne seront point impunis; mais la race des justes est sauvée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Un anneau d\'or au groin d\'un pourceau, c\'est dans une femme beauté et déraison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Le souhait du juste n\'a pour fin que le bien; mais la perspective des méchants, c\'est la peine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Il en est qui répandent, et reçoivent plus encore; il en est qui épargnent plus qu\'il n\'est juste, et c\'est pour s\'appauvrir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Une âme bienfaisante obtiendra l\'abondance, et celui qui restaure, sera restauré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Qui garde son blé, par le peuple est maudit; mais la bénédiction est sur la tête de celui qui le vend.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Qui s\'applique au bien, cherche la bienveillance; mais le mal survient à qui cherche le mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Qui s\'appuie sur sa richesse, tombera; mais comme le feuillage les justes verdiront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Celui qui met le désordre dans sa maison, n\'hérite que du vent, et l\'insensé devient le serviteur du sage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Le fruit du juste est un fruit de l\'arbre de vie, et le sage captive les cœurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Vois! sur la terre le juste reçoit son salaire; combien plus le méchant et le pécheur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Qui aime la correction, aime la science; qui hait la réprimande, reste stupide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'L\'homme de bien obtient la faveur de l\'Éternel; mais Il châtie l\'homme d\'intrigue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Point de stabilité pour l\'homme dans l\'impiété; mais la racine des justes n\'est point vacillante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'La femme forte est la couronne de son mari; mais celle qui est sa honte, est comme une carie dans ses os.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Dans leurs plans les justes n\'ont en vue que le droit; les moyens des impies, c\'est la fraude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Ce dont parlent les impies, c\'est de guetter des victimes; mais la bouche du juste les délivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Une fois renversés les méchants cessent d\'être; mais la maison des justes demeure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'L\'homme est estimé à proportion de son sens; et qui n\'a pas le sens droit, tombe dans le mépris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Mieux vaut celui dont l\'état est humble, et qui a un serviteur, que le glorieux qui manque de pain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Le juste connaît les besoins de son bétail; les entrailles des impies sont impitoyables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Celui qui cultive son champ, a du pain en abondance; mais celui qui recherche les fainéants, manque de sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'L\'impie désire l\'appui des méchants; la racine qu\'ont les justes, leur donne {[}un appui{]}.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Les péchés de la langue couvrent un piège funeste; mais le juste échappe à l\'angoisse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Par les fruits de sa bouche l\'homme est rassasié de biens; et ce que fait sa main, est rendu à l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'La voie de l\'insensé est droite à ses yeux; mais celui qui écoute un conseil, est sage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Le chagrin du méchant se montre au moment même; mais celui qui dissimule un affront, est prudent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Celui qu\'anime la vérité, exprime ce qui est juste; et le témoin menteur, ce qui trompe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Il en est dont le babil est comme des coups d\'épée; mais le parler du sage restaure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'La parole vraie subsiste éternellement; il n\'y a qu\'un instant pour le langage du mensonge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'La fraude est dans le cœur de ceux qui machinent le mal; mais la joie est à ceux qui conseillent la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Les peines n\'atteignent jamais le juste; mais les impies ont plénitude de maux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'L\'Éternel abhorre les lèvres qui mentent; mais ceux qui pratiquent la vérité, sont ses délices.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'L\'homme prudent cache ce qu\'il sait; mais le cœur des insensés proclame sa folie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'La main des diligents commandera; mais la main lâche sera corvéable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Le chagrin qui est dans le cœur, l\'abat; mais une bonne parole le réjouit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Le juste indique la voie à son prochain; mais la voie des impies les fourvoie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'L\'indolent ne chasse pas son gibier; le précieux trésor de l\'homme, c\'est la diligence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Sur le sentier de la justice il y a vie, et sur la bonne voie, immortalité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'L\'enfant sage écoute l\'avis de son père: mais le moqueur n\'écoute pas la réprimande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Par les fruits de sa bouche l\'homme est rassasié de biens; mais la convoitise des infidèles [recueille] l\'injure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Qui surveille sa bouche, met en sûreté sa vie; pour qui tient ses lèvres ouvertes, la ruine est là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'L\'appétit des paresseux est avide, et ne le mène à rien; mais l\'appétit des diligents est entièrement satisfait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Le juste a le langage menteur en aversion; mais le méchant diffame et outrage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'La justice préserve l\'innocence, mais l\'impiété cause la ruine du pécheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Tel fait le riche, qui n\'a rien du tout; tel fait le pauvre, qui a beaucoup de bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Avec des richesses on rachète sa vie; mais le pauvre n\'a pas de menaces à entendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'La lumière des justes a toujours un riant éclat; mais la lampe des impies s\'éteint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Par l\'orgueil on ne fait naître que des rixes; mais ceux qui accueillent un conseil, possèdent la sagesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'La richesse se dissipe plus vite qu\'un souffle; mais celui qui amasse dans sa main, l\'accroît.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'L\'espoir différé rend le cœur malade; mais le souhait accompli est un arbre de vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Qui méprise la Parole, se perd; mais qui respecte la Loi, sera récompensé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'La doctrine du sage est une source de vie, faisant échapper aux lacs de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Un bon esprit concilie la faveur; mais la voie des perfides est pénible.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Tout homme prudent agit avec jugement; mais l\'insensé déploie de la folie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Un messager infidèle tombe dans le malheur; mais un envoyé sûr fait du bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Indigence et honte pour qui déserte la discipline; mais qui a égard à la correction, parvient à la gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Un souhait accompli est doux au cœur; et ce que les fous abhorrent, c\'est de fuir le mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Hante les sages, et sage tu seras; mais qui se plaît avec les fous, se déprave.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Le malheur poursuit les pécheurs, mais le bonheur est la rétribution des justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'L\'homme de bien laisse son héritage aux enfants de ses enfants, mais l\'opulence du pécheur est réservée pour le juste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Le défrichement du pauvre donne abondance de denrées; mais tel se ruine, faute de justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Epargner la verge, c\'est haïr son enfant; mais c\'est l\'aimer que de veiller à sa correction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Le juste mange à satisfaire sa faim; mais le ventre des impies ressent la disette.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Sage, une femme élève sa maison; insensée, de ses propres mains elle la démolit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'L\'homme qui marche dans la droiture, craint l\'Éternel; mais, si ses voies se détournent, il Le méprise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'L\'insensé a dans sa bouche même la verge de son orgueil; mais par leurs lèvres les sages sont garantis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Où il n\'y a pas de bœufs, le grenier est vide; mais la vigueur du taureau donne un gros revenu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Le témoin véridique ne ment point; mais le faux témoin profère le mensonge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Le moqueur cherche la sagesse sans la trouver; mais pour l\'intelligent la science est chose facile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Va te placer en face de l\'insensé; tu ne pourras découvrir la sagesse sur ses lèvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'La sagesse du prudent, c\'est de faire attention à sa voie; mais la folie des insensés est une duperie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Les insensés se font un jeu du crime; mais parmi les hommes de bien il y a bienveillance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Le cœur connaît son propre chagrin; et autrui ne saurait entrer en part de sa joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'La maison des impies est détruite, et la tente des gens de bien, florissante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Telle voie paraît droite à l\'homme, mais elle aboutit au chemin de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'L\'on peut, quand on rit, avoir le chagrin dans le cœur; et la joie peut finir en tristesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Des fruits de sa conduite il sera rassasié celui dont le cœur s\'égare, et l\'homme de bien, de ce qui lui revient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'L\'inconsidéré ajoute foi à toute parole; le prudent est attentif à ses pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Le sage est timide, et fuit le mal; mais l\'insensé est présomptueux, et plein de sécurité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'L\'homme prompt à s\'irriter agit follement; mais l\'homme d\'intrigue se fait haïr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Les insensés sont en possession de la folie; mais les justes ont pour couronne la science.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Les méchants s\'inclinent devant les bons, et les impies, à la porte du juste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'A son prochain même le pauvre est odieux; mais ceux qui aiment le riche, sont nombreux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Qui méprise son prochain, pèche: mais heureux qui a pitié des misérables!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Ceux qui font le mal, ne se fourvoient-ils pas? Mais ceux qui font le bien, trouvent amour et confiance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Tout labeur donne abondance; mais les discours des lèvres ne mènent qu\'à l\'indigence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'La couronne des sages est leur richesse; la folie des insensés, c\'est la folie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Le témoin véridique est le libérateur des âmes; mais celui qui trompe, souffle le mensonge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'La crainte de l\'Éternel donne une confiance ferme; et pour Ses enfants Il sera un refuge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'La crainte de l\'Éternel est une source de vie, pour échapper aux lacs de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Un peuple nombreux donne au roi sa splendeur; mais le manque d\'hommes est la ruine du prince.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'L\'homme lent à s\'irriter a un grand sens; l\'irascible met en vue sa folie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Un cœur sain est la vie du corps; mais l\'envie est la carie des os.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Qui opprime les petits, outrage son créateur; mais celui-là l\'honore, qui prend pitié des pauvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Par ses revers l\'impie est renversé; mais dans la mort même le juste est plein d\'assurance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'Dans le cœur sensé la sagesse repose; mais au milieu des fous elle se manifeste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'La justice élève une nation, mais le péché est l\'opprobre des peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Le roi donne sa faveur au serviteur entendu, mais au méchant serviteur son courroux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Une douce réponse calme le courroux; mais une parole dure excite la colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'La langue des sages rend la science aimable; la bouche des insensés épanche la folie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Les yeux de l\'Éternel sont en tous lieux, observant les méchants et les bons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'La langue qui calme, est un arbre de vie; mais celle qui trouble, brise l\'âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'L\'insensé dédaigne les leçons de son père; mais qui garde la correction, agit prudemment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Grande abondance dans la maison du juste, désordre dans le revenu de l\'impie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Les lèvres du sage sèment la science, et le cœur des fous, des choses vaines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Le sacrifice des impies est l\'abomination de l\'Éternel; mais la prière des hommes droits lui est agréable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'La voie de l\'impie est l\'abomination de l\'Éternel; mais Il aime celui qui s\'attache à la justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Sévère leçon à qui s\'écarte de la voie; qui n\'aime pas à être repris, périra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Les Enfers et l\'abîme sont à découvert pour l\'Éternel, et plus encore les cœurs des enfants des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Le moqueur n\'aime pas à être repris; il ne s\'approche point des sages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Un cœur joyeux rend le visage serein; mais quand le cœur souffre, l\'esprit est abattu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Le cœur de l\'homme sensé cherche la science; et le regard de l\'insensé se repaît de folie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Tous les jours sont mauvais pour le malheureux; mais le cœur content est un festin perpétuel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Mieux vaut avoir peu, et la crainte de Dieu, que de grands trésors, et le trouble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Mieux vaut un plat d\'herbes, et de la cordialité, qu\'un bœuf gras, et de la haine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'L\'homme colère excite des querelles, le patient apaise les rixes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'La voie du paresseux est comme une haie d\'épines; le chemin des gens de bien est uni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Un fils sage réjouit son père; mais un homme insensé méprise sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'La folie est le bonheur de qui manque de sens; mais l\'homme raisonnable suit le droit chemin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Inutiles sont les avis là où l\'on ne délibère pas; mais où il y a plusieurs conseillers, ils sont efficaces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'C\'est un plaisir pour l\'homme quand sa bouche sait répondre; et qu\'un mot dit à propos va bien!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Le chemin de la vie est montant pour le sage, afin qu\'il évite celui des Enfers qui descend.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'L\'Éternel renverse la maison des superbes; mais Il rend stable la borne de la veuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Les plans de la malice sont l\'abomination de l\'Éternel; mais les paroles de bonté sont pures devant lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Celui-là ruine sa maison, qui est avide de gain; mais celui qui n\'aime pas les présents, vivra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Le cœur du juste médite sa réponse; mais la bouche des impies vomit la malice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'L\'Éternel s\'éloigne des impies, mais Il prête l\'oreille à la prière des justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Un regard affectueux réjouit le cœur; une bonne nouvelle verse de la moelle dans les os.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Celui dont l\'oreille écoute les leçons de la vie, se trouve toujours au milieu des sages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Qui repousse les leçons, se condamne soi-même; mais qui écoute les avis, gagne du sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'La crainte de l\'Éternel est l\'école de la sagesse; et l\'humilité précède la gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'A l\'homme de former des plans en son cœur; mais à Dieu d\'exaucer ce qu\'exprime la langue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Toutes les voies d\'un homme sont pures à ses yeux; mais l\'Éternel pèse les cœurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Repose-toi sur Dieu de tes affaires, et tes plans seront assurés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'L\'Éternel a fait toutes choses pour leur fin; ainsi, l\'impie pour le jour du malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Tout orgueilleux est pour l\'Éternel une abomination; en aucun temps il ne demeure impuni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'L\'amour et la fidélité expient la faute, et la crainte de l\'Éternel fait fuir le mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Si l\'Éternel est favorable à la voie d\'un homme, Il réconcilie même ses ennemis avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Mieux vaut peu avec la justice, qu\'un gros revenu avec l\'iniquité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'L\'homme en son cœur se trace sa voie; c\'est l\'Éternel qui dirige sa marche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Les lèvres du roi prononcent des oracles; et, quand il juge, sa bouche n\'est point inique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Le poids et la balance justes viennent de l\'Éternel; Il a fait toutes les pierres qu\'on a dans sa bourse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Les rois auront horreur de faire le mal; car par la justice un trône est affermi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Les bonnes grâces du roi seront pour les lèvres vraies, et celui qui parle sincèrement, aura son amour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Colère de roi, messages de mort: aussi le sage la calmera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'Un regard riant du roi donne la vie, et sa faveur est comme un nuage pluvieux du printemps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Combien la possession de la sagesse vaut mieux que l\'or! et que la possession de la sagesse est préférable à l\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'La voie des gens de bien, c\'est de fuir le mal; il préserve sa vie celui qui surveille ses voies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'L\'orgueil précède la ruine, et la présomption, la chute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Mieux vaut vivre humble avec les pauvres, que de partager le butin avec les superbes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Qui dans les affaires agit sensément, trouve le bonheur; et heureux qui se confie dans l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'L\'homme au cœur sage est appelé sensé, et l\'aménité des paroles avance l\'instruction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'La prudence pour qui l\'a est une source de vie; les insensés sont punis par leur propre folie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Le cœur du sage rend sa bouche sensée, et par ses discours avance l\'instruction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Les discours gracieux sont des rayons de miel, doux au cœur, restaurants pour le corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Telle voie semble droite à l\'homme; mais elle aboutit au chemin de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'La faim du travailleur travaille pour lui, car sa bouche lui en impose la charge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'L\'homme dangereux prépare le malheur, et sur ses lèvres il y a comme un feu qui brûle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'L\'homme tortueux excite les divisions; et le rapporteur désunit les intimes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'L\'homme qui veut nuire, séduit son prochain, et l\'engage dans une voie qui n\'est pas la bonne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'il ferme les yeux pour méditer la fraude, il serre les lèvres... il a consommé le crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Les cheveux blancs sont une couronne d\'honneur; c\'est sur le chemin de la justice qu\'on la trouve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'L\'homme patient est supérieur au héros, et celui qui a l\'empire de son âme, au preneur de villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'On jette le sort dans le pan de la robe; mais sa décision vient de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Mieux vaut un morceau de pain sec avec la paix, qu\'une maison dans laquelle se multiplient les festins où l\'on se querelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Le sage serviteur commande au fils qui fait honte, et avec les frères il partagera l\'héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Le creuset est pour l\'argent, et la fournaise pour l\'or; mais c\'est l\'Éternel qui éprouve les cœurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Le méchant est attentif aux discours nuisibles, le menteur prête l\'oreille aux paroles funestes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Qui se moque du pauvre, outrage son créateur; qui jouit du malheur, ne reste pas impuni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Les enfants de leurs enfants sont la couronne des vieillards et la gloire des enfants, ce sont leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Le langage digne ne sied pas à l\'insensé; combien moins à l\'homme bien né le langage du mensonge!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Le don est une pierre de prix aux yeux de qui le reçoit; partout où il s\'adresse, il réussit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Qui tait la faute, cherche l\'affection; mais qui la reproduit par la parole, désunit des intimes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Le blâme frappe plus l\'homme de sens, que cent coups, l\'insensé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'La révolte ne cherche que le mal, mais un cruel messager lui est député.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Soyez rencontrés par une ourse qui a perdu ses petits, mais non par un insensé pendant sa démence!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'De quiconque rend le mal pour le bien, les maux ne quittent point la demeure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Commencer une querelle, c\'est rompre une digue; cède avant que le débat s\'échauffe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Qui absout le coupable, et qui condamne l\'innocent, sont l\'un autant que l\'autre l\'abomination de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'A quoi sert à l\'insensé d\'avoir en main des richesses? A acheter la sagesse? Il manque de sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'L\'ami aime dans tous les temps; mais dans le malheur il devient un frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'L\'homme privé de sens touche dans la main, et se lie comme caution envers autrui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Celui-là aime à pécher qui aime à se quereller; et qui élève trop sa porte, cherche sa chute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Avec un cœur tortueux on ne trouve pas le bonheur; et avec une langue perverse on tombe dans le malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Qui donne le jour à un fou, en aura du chagrin; et point de joie pour le père de l\'insensé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Un cœur joyeux est un bon remède; mais un esprit abattu dessèche les os.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'L\'impie accepte le présent caché sous le manteau, pour détourner le cours de la justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'La sagesse est à la portée du sage; mais les yeux de l\'insensé cherchent au bout de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Le fils insensé est un chagrin pour son père, et une amertume pour celle qui lui donna naissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Condamner le juste, même à une amende, est mauvais; mais frapper l\'homme bien né passe les bornes du droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Qui épargne ses paroles, possède la science, et qui a du sang-froid est homme de sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Même l\'insensé, quand il se tait, passe pour sage; celui qui tient fermées ses lèvres, a du sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Celui qui s\'isole, suit sa fantaisie, il s\'irrite contre tout ce qui est raisonnable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Ce n\'est pas la raison qu\'aime l\'insensé, mais il aime à montrer son sentiment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Quand vient l\'impiété vient aussi le mépris, et avec l\'infamie, l\'opprobre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Les paroles qui sortent de la bouche de l\'homme, sont des eaux profondes; la source de la sagesse est une rivière abondante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Il est mal de prendre parti pour l\'impie, afin de débouter le juste dans le jugement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Les lèvres de l\'insensé apportent les querelles, et sa bouche excite aux coups.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'La bouche de l\'impie est pour lui une cause de ruine, et ses lèvres, un piège à sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Les propos du rapporteur sont comme des friandises; ils se glissent jusqu\'au fond des entrailles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Celui-là aussi qui travaille lâchement, est frère du dissipateur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Le nom de l\'Éternel est une forte tour, le juste y accourt, et se trouve en lieu sûr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'L\'opulence du riche est sa forteresse, et comme une haute muraille, dans son opinion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Avant la chute le cœur de l\'homme s\'élève; et l\'humilité précède la gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Qui répond avant d\'écouter, manque de sens, et sera confus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'L\'âme de l\'homme supporte ses souffrances; mais une âme abattue, qui la relèvera?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Le cœur de l\'homme de sens acquiert la science, et l\'oreille des sages est à la recherche de la science.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Par des présents l\'homme se fait jour; et ils l\'introduisent chez les grands.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Il [paraît] juste celui qui dans sa cause parle le premier; mais que vienne sa partie, et alors examine-le.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Le sort met fin aux contestations; et entre les puissants il décide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Un frère est plus rebelle qu\'une ville forte; et les querelles {[}des frères{]} sont comme les verrous d\'un palais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Des fruits de sa bouche chacun est nourri, il est nourri de ce que ses lèvres lui rapportent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'La mort et la vie dépendent de la langue; celui qui en aime l\'usage, en goûtera les fruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Trouver une femme c\'est trouver le bonheur, et obtenir une faveur de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Le pauvre parle en suppliant; mais le riche répond durement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Tel a beaucoup de relations à son détriment; mais, ayez un ami, il s\'attache plus qu\'un frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Meilleur est un pauvre qui marche dans son intégrité, qu\'un homme aux lèvres fausses, qui est un insensé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'A manquer de prudence il n\'y a point d\'avantage; et qui précipite ses pas, bronche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'C\'est la folie de l\'homme qui gâte sa carrière; mais c\'est contre l\'Éternel que s\'irrite son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'La richesse procure beaucoup d\'amis, mais le pauvre est abandonné par son ami.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Un faux témoin ne demeure pas impuni, et celui qui émet des mensonges, n\'échappera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Il y a beaucoup de flatteurs pour l\'homme libéral, et tous les amis sont pour celui qui donne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Tous les frères du pauvre ont de l\'aversion pour lui; combien plus ses amis le quitteront-ils! Il se réclame de leurs promesses,... elles sont évanouies!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Acquérir du sens, c\'est aimer son âme; garder la prudence fait trouver le bonheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Le faux témoin ne reste pas impuni; et qui profère le mensonge, se perd.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Une vie de délices ne va pas à l\'insensé; il va moins encore à l\'esclave de commander aux princes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'La raison de l\'homme le rend patient, et sa gloire est de passer une faute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'La colère d\'un roi est le rugissement du lion; mais sa faveur est comme la rosée sur la verdure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Le malheur d\'un père, c\'est un fils insensé; et l\'eau qui dégoutte d\'un toit sans interruption, c\'est une femme querelleuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'On hérite de ses pères une maison et des biens; mais une femme sensée, est un don de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'La paresse plonge dans le sommeil, et l\'âme indolente sentira la faim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Qui garde le commandement, garde sa vie; qui néglige sa voie, subira la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Celui qui donne au pauvre, prête à l\'Éternel, et Il lui rendra son bienfait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Châtie ton fils, pendant qu\'il y a espoir; mais jusqu\'à le tuer ne te laisse pas emporter!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Que l\'emporté subisse la peine; car si tu l\'en exemptes, tu devras y revenir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Ecoute un conseil, et reçois les leçons, afin que tu sois sage dans la suite de ta vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Les projets du cœur de l\'homme sont nombreux; mais le décret de l\'Éternel, c\'est ce qui s\'exécute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'La bonté de l\'homme fait sa gloire; et le pauvre vaut mieux que le menteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'La crainte de l\'Éternel mène à la vie; on repose rassasié, sans être atteint de malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Le paresseux plonge sa main dans le plat; mais à sa bouche il ne la ramènera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Frappe le moqueur, le faible deviendra sage; avertis l\'homme de sens, il entend raison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Il ruine son père, fait fuir sa mère, le fils impudent, et qui fait honte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Cesse, mon fils, d\'écouter des doctrines qui te détourneraient des paroles de la sagesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Un témoin pervers se rit de la justice; et la bouche des impies se repaît d\'iniquité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Les châtiments sont prêts pour les moqueurs; et les coups, pour le dos de l\'insensé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Le vin est moqueur, la cervoise tumultueuse; qui par eux se laisse étourdir, n\'est pas sage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Tel le rugissement d\'un lion, telle est l\'épouvante que répand un roi. Qui s\'emporte contre lui, pèche contre soi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'C\'est une gloire pour l\'homme de cesser une querelle: mais tout insensé s\'exaspère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Parce qu\'il fait froid, le paresseux ne laboure pas; à la moisson il mendiera, et n\'obtiendra rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Le projet dans le cœur de l\'homme est sous une eau profonde; mais l\'intelligent va l\'y puiser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Plusieurs hommes proclament chacun leur bonté; mais un homme fidèle, qui le trouvera?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Le juste marche dans son innocence; heureux les enfants qu\'il laisse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Le roi qui siège sur son tribunal, par son regard met tout mal en fuite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Qui dira: J\'ai gardé mon cœur pur, et de péché je ne me suis point souillé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Double poids, double mesure, sont l\'un et l\'autre l\'abomination de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Déjà dans ce qu\'il fait, l\'enfant montre ce qu\'il est, si sa conduite sera pure et droite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'L\'oreille qui entend, et l\'œil qui voit, par l\'Éternel furent formés l\'un et l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'N\'aime pas le dormir, afin de ne pas perdre ce que tu as! Aie les yeux ouverts, et tu auras abondance de pain!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'Mauvais! mauvais! dit l\'acheteur; mais en s\'en allant il se félicite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Il y a de l\'or et beaucoup de perles; mais des lèvres sensées sont une vaisselle de prix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Prends-lui son manteau, car il a cautionné autrui; et nantis-loi de lui plutôt que de l\'étranger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Le pain du mensonge est doux à l\'homme; mais sa bouche finit par se trouver pleine de gravier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'C\'est la réflexion qui donne à un plan de la consistance; et sans circonspection ne fais point la guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Il révèle les secrets celui qui va médisant; et de celui qui tient ses lèvres ouvertes, ne fais pas ta société.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'De quiconque maudit son père et sa mère, le flambeau s\'éteint au sein des ténèbres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Un héritage abominable à son origine ne finira point par être béni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Ne dis pas: Je rendrai le mal pour le mal! Compte sur l\'Éternel, c\'est lui qui t\'aidera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Le double poids est l\'abomination de l\'Éternel; et la balance fausse n\'est pas une chose bonne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'C\'est l\'Éternel qui règle la marche des humains; l\'homme! comment découvrirait-il sa voie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Il y a péril pour l\'homme à précipiter les choses saintes, et à ne réfléchir qu\'après le vœu prononcé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Un roi sage fait avec le van le triage des méchants, et fait passer sur eux la roue qui foule le blé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Un flambeau allumé par l\'Éternel, telle est l\'âme de l\'homme, qui sonde les profondeurs de son intérieur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'L\'amour et la fidélité sont la garde du roi, et par l\'amour il donne un étai à son trône.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'La parure des jeunes hommes, c\'est leur vigueur; et la gloire des vieillards, leurs cheveux blancs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Les meurtrissures purifient le méchant, les coups qui pénètrent au fond des entrailles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Le cœur d\'un roi est un ruisseau dans la main de Dieu, qui l\'incline partout où Il veut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Les voies de l\'homme sont toutes droites à ses yeux; mais l\'Éternel pèse les cœurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Faire ce qui est droit et juste, est plus agréable à l\'Éternel que les sacrifices.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Le regard hautain, et le cœur qui s\'enfle, ce flambeau des impies, est un péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'La circonspection du diligent ne mène qu\'à l\'abondance: mais celui qui précipite, n\'arrive qu\'à l\'indigence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Les trésors acquis par les mensonges de la langue, sont un souffle qui se dissipe: ils tendent à la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'La violence des impies les emporte eux-mêmes, car ils refusent de faire ce qui est juste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'L\'homme dont la voie est tortueuse, dévie; mais de l\'homme pur la conduite est droite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Mieux vaut habiter un coin du toit, que près d\'une femme querelleuse, et un logis commun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Ce que veut l\'impie, c\'est le mal; à ses yeux son ami ne saurait trouver grâce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Le moqueur est-il puni, le faible en devient sage; qu\'on instruise le sage, il accueille la science.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Le Juste a l\'œil sur la maison de l\'impie; Il précipite les impies dans le malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Celui qui ferme son oreille au cri du pauvre, criera aussi, et restera sans réponse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Un don fait en secret fléchit la colère, et un présent glissé dans le sein, un courroux violent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'C\'est une joie pour le juste de pratiquer la droiture; mais cela fait peur au méchant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'L\'homme qui s\'écarte de la voie de la raison, ira reposer dans la société des Ombres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'L\'amateur du plaisir tombe dans l\'indigence; et celui qui aime le vin et les parfums, ne s\'enrichira pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'L\'impie devient une rançon pour le juste; et l\'infidèle, pour les hommes droits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Mieux vaut habiter un désert, que d\'avoir une femme querelleuse et chagrine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Il y a trésors précieux et huile dans la maison du sage; mais l\'insensé absorbe ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Qui cherche justice et bonté, trouve vie, justice et gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Le sage escalade la ville des héros, et abat le fort auquel ils s\'assuraient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Qui veille sur sa bouche et sa langue, préserve son âme de la détresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Moqueur est le nom du superbe, du hautain; il agit dans l\'excès de son orgueil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Les désirs du lâche le tuent, car ses mains refusent d\'agir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'tout le jour il désire avidement; mais le juste donne, et sans parcimonie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Le sacrifice des impies est abominable; combien plus s\'ils l\'offrent en pensant au crime!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Le témoin menteur périt; mais l\'homme qui écoute, pourra toujours parler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'L\'impie prend un air effronté; mais l\'homme droit règle sa marche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Il n\'y a ni sagesse, ni prudence ni conseil, devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Le cheval est équipé pour le jour de la bataille; mais c\'est de l\'Éternel que vient la victoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Mieux vaut bonne réputation que grande richesse, et bienveillance, qu\'argent et or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Le riche et le pauvre se rencontrent; leur créateur à tous, c\'est l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Le prudent voit la calamité, et se cache; les inconsidérés vont en avant, et sont punis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Le prix de l\'humilité, de la crainte de l\'Éternel, c\'est richesse, honneur et vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Des ronces et des pièges sont sur la route du pervers; qui veut préserver sa vie, s\'en éloigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Forme le jeune homme selon la voie qu\'il doit suivre; même s\'il vieillit, il n\'en déviera point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Le riche commande aux pauvres; et le débiteur est l\'esclave du créancier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Qui sème le vice, récoltera le malheur; et la verge pour le punir est prête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Le compatissant sera béni, car il donne de son pain au pauvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Expulse le moqueur, et les querelles fuiront, et les rixes et les insultes cesseront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'L\'homme qui aime la pureté de cœur, et possède la grâce du langage, a pour ami le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Le regard de l\'Éternel protège la sagesse, mais Il déjoue les propos du perfide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Le lâche dit: « Un lion est là dehors, au milieu de la rue; je serais égorgé! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Bouche des étrangères, fosse profonde, où tombe celui contre qui l\'Éternel s\'irrite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Quelqu\'adhérente que soit la folie au cœur de l\'enfant, la verge correctrice l\'en détache.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Tel opprime le pauvre qui le fait devenir riche; donnez au riche, il n\'arrive qu\'à l\'indigence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Prête l\'oreille et écoute les discours des sages, et sois attentif à mes leçons!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Car il est beau que tu les gardes en ton cœur, et que sur tes lèvres tu les aies toujours prêtes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'C\'est à mettre ta confiance dans l\'Éternel, que je veux te former aujourd\'hui, oui, toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Voici, dès longtemps j\'ai écrit pour toi sur les conseils et la prudence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'pour t\'inculquer des préceptes vrais et sûrs, afin que tu répondes fidèlement à celui qui te donnera une mission.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Ne dépouille pas le faible, parce qu\'il est faible, et ne foule pas le misérable à la Porte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'car l\'Éternel soutient sa cause, et à ses ravisseurs Il ôte la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Ne vis pas en société avec l\'homme colère, n\'aie aucune relation avec l\'homme qui s\'échauffe,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'de peur que tu ne t\'habitues à suivre sa voie, et que tu n\'en remportes un piège contre ton âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Ne te trouve pas entre ceux qui frappent dans la main, qui cautionnent pour des dettes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Si tu n\'as pas de quoi payer, pourquoi ferais-tu qu\'on vienne prendre ton lit sous toi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Ne déplace pas la borne antique, que tes pères ont posée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Vois-tu cet homme actif dans ce qu\'il fait? Il sera le ministre des rois, et non le ministre des gens obscurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Si tu t\'assieds à table avec un prince, considère bien qui tu as devant toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'et mets un couteau à ton gosier, si tu as un appétit trop grand!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Ne convoite point ses friandises, car c\'est un mets trompeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Ne t\'efforce pas de l\'enrichir, renonce à être si prudent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Tes regards voltigeront-ils vers ce qui va n\'être plus? car il prendra des ailes, comme l\'aigle et les oiseaux du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Ne mange pas le pain de l\'avare, et ne convoite pas ses friandises!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Car il est ce qu\'il est en son cœur, calculateur. Mange et bois! te dira-t-il; mais son cœur n\'est pas avec toi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'tu rejetteras le morceau que tu auras mangé, et tu auras tenu en pure perte d\'agréables propos.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Aux oreilles de l\'insensé ne parle pas, car il méprise la sagesse de tes discours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Ne déplace point la borne antique, et n\'envahis point le champ de l\'orphelin!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Car son vengeur est puissant, et Il prendra son parti contre toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Présente ton cœur à la correction, et tes oreilles aux discours de la sagesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'N\'épargne pas la correction au jeune enfant! Si tu le frappes de la verge, il ne mourra point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'En le frappant de la verge tu sauves son âme des Enfers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Mon fils, si ton cœur est sage, mon cœur, oui, mon cœur sera dans la joie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'l\'allégresse pénétrera mes entrailles, si tes lèvres parlent avec rectitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Que ton cœur n\'envie pas les pécheurs, mais qu\'il garde toujours la crainte de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Non! car il est un avenir, et ton espoir ne sera pas mis à néant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Ecoute, mon fils, et sois sage, et dirige ton cœur dans le droit chemin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Ne sois point parmi les buveurs de vin, et ceux qui sont prodigues de leur corps;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'car le buveur et le prodigue s\'appauvrissent, et l\'assoupissement revêt de haillons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Obéis à ton père, il t\'a engendré, et ne méprise point ta mère devenue vieille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Achète la vérité, et ne la vends pas, la sagesse, la discipline et le sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Le père du juste est dans l\'allégresse, et celui qui a engendré un sage, en recueille de la joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Puisses-tu réjouir ton père et ta mère, et être l\'allégresse de celle qui te donna naissance!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Donne-moi ton cœur, mon fils, et que mes voies plaisent à tes yeux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Car la courtisane est une fosse profonde, et l\'étrangère, un puits étroit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'elle épie, comme un ravisseur, et augmente parmi les hommes le nombre des infidèles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Pour qui sont les ah? pour qui les hélas? pour qui les rixes? pour qui le chagrin? pour qui les coups non provoqués? pour qui les yeux troubles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Pour ceux qui boivent longuement, qui viennent déguster le vin parfumé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Ne regarde pas le vin, quand il est vermeil, quand dans la coupe il élève ses bulles, et que sa liqueur est flatteuse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Il finit par blesser comme le serpent, et par piquer, comme la vipère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Tes yeux alors se porteront sur les étrangères, et ton cœur tiendra un langage pervers;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'et tu seras comme celui qui dort en pleine mer, comme celui qui dort à la cime du mât.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, '« Ils me battent; cela ne fait pas mal: ils me frappent; je ne sens rien. Quand me réveillerai-je? J\'y veux retourner. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Ne porte pas envie aux hommes méchants, et ne désire pas leur société!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Car leur cœur médite la ruine, et leurs lèvres ont un langage funeste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Par la sagesse une maison s\'élève, et par l\'intelligence elle se consolide;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'et par la science les chambres se remplissent de tous les biens de prix et d\'agrément.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'L\'homme sage a de la force, et l\'homme qui sait, gagne en vigueur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Car tu feras la guerre ayant pris tes mesures, et c\'est le nombre des conseillers qui donne la victoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Pour l\'insensé la sagesse est chose trop haute; aux Portes il n\'ouvre pas la bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Celui qui médite de faire du mal, reçoit le nom d\'homme d\'intrigue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'La pensée de la folie, c\'est le péché; et le moqueur est l\'abomination des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Si tu faiblis au jour de la détresse, tes forces s\'affaibliront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Sauve ceux qu\'on traîne à la mort; retiens ceux qui vont tomber sous les coups meurtriers!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Si tu dis: « Nous ne le connaissons point! » Celui qui pèse les cœurs, ne l\'entendra-t-Il pas? et le Gardien de ton âme ne le saura-t-il pas? et ne rend-Il pas à chacun selon ses œuvres?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Mon fils, mange le miel, car il est bon, et le rayon de miel, qui est doux à ton palais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Sache que telle sera la sagesse à ton âme. Si tu la trouves, il est un avenir; et ton espoir ne sera pas mis à néant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Impie, ne dresse point d\'embûches à la demeure du juste, et ne dévaste point son gîte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Car sept fois le juste tombe, et il se relève; mais les impies périssent dans le malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Ne te réjouis pas de la chute de ton ennemi, et que ton cœur ne se délecte pas de sa ruine,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'de peur que l\'Éternel ne le voie, et n\'en ait déplaisir, et qu\'il ne détourne sa colère de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Ne t\'irrite point à la vue des méchants, et ne sois point jaloux des impies,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'car le méchant n\'a point d\'avenir, le flambeau des impies s\'éteint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Crains l\'Éternel, mon fils, et le roi, et ne t\'associe point aux novateurs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'car leur ruine surgit tout-à-coup, et le temps du châtiment des uns et des autres, qui le sait?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Encore paroles de sages. Etre partial, quand on juge, n\'est pas bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Quiconque dit au coupable: Tu es innocent! encourt la malédiction des peuples, et le courroux des nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Mais ceux qui osent punir, s\'en trouvent bien, et obtiennent le bonheur comme bénédiction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Il donne un baiser sur les lèvres, celui qui répond pertinemment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Soigne au dehors tes affaires, et mets en bon état ton champ; alors tu peux bâtir ta maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Ne témoigne pas à la légère contre ton prochain; et de tes lèvres voudrais-tu tromper?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Ne dis pas: Ce qu\'il m\'a fait, je le lui ferai, je rendrai à chacun selon ses œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Près du champ du paresseux je passais, et près de la vigne de l\'homme privé de sens;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'et voici, le chardon y poussait partout, et des orties en couvraient le sol, et son mur de pierres s\'était écroulé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Et je regardai, et fis attention; je vis, et en tirai une leçon:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, '« Un peu dormir, un peu sommeiller, un peu croiser les bras en étant couché! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'Ainsi, la pauvreté fondra sur toi, comme un larron, et l\'indigence, comme un homme portant le bouclier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Ce sont aussi des Proverbes de Salomon, que recueillirent les hommes d\'Ezéchias, roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'La gloire de Dieu, c\'est de cacher ses desseins, et la gloire des rois, de les pénétrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Comme les Cieux en hauteur, la terre en profondeur, que le cœur du roi soit insondable!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'De l\'argent enlève les scories, et il en sort pour l\'orfèvre un vase;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'ôte l\'impie des alentours du roi, et par la justice son trône s\'affermira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Ne fais pas le glorieux devant un roi, et ne te mets pas au rang des Grands;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'car mieux vaut qu\'on te dise: Monte ici! que d\'être humilié devant le prince que tes yeux voient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Ne te hâte pas d\'entrer en procès, de peur de ce qu\'à la fin tu pourrais faire, si ta partie t\'outrage!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Plaide ton procès contre ta partie, mais ne révèle pas le secret d\'autrui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'de peur que celui qui t\'entendrait, ne te fasse honte, et que ton infamie ne s\'efface pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Des pommes d\'or sur une ciselure d\'argent, tel est un mot dit à propos.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Anneau d\'or, collier d\'or fin, tel est le sage moniteur pour l\'oreille docile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Le frais de la neige au temps de la moisson, tel est le messager sûr pour celui qui le dépêche: il restaure l\'âme de son maître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Nuage et vent, mais point de pluie, c\'est l\'homme qui se vante en mentant de donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'A la patience un prince se laisse gagner, et la langue, toute molle qu\'elle est, brise des os.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Si tu trouves du miel, manges-en ce qui t\'est suffisant, de peur d\'en avoir à satiété, et de le rejeter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Mets rarement le pied dans la maison de ton ami, de peur qu\'il ne se lasse de toi, et ne te prenne en aversion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Un marteau, une épée, une flèche aiguë, c\'est l\'homme qui dépose contre son frère en faux témoin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Une dent cassée, un pied vacillant, c\'est au jour de détresse le perfide en qui l\'on se lie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Oter son manteau au jour de la froidure, verser du vinaigre sur du natron, c\'est chanter des chansons à un cœur triste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Si ton ennemi a faim, donne-lui du pain à manger, s\'il a soif, donne-lui de l\'eau à boire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'car ainsi tu lui mets sur la tête des charbons ardents, et l\'Éternel te récompensera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Le vent du nord produit la pluie, et la calomnie sourde, le visage irrité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Mieux vaut habiter le coin d\'un toit, que près d\'une femme querelleuse, et le même logis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Une eau fraîche pour un homme fatigué, c\'est une bonne nouvelle venant d\'un pays lointain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Une source troublée, et un puits gâté, c\'est le juste succombant sous l\'impie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Il n\'est pas bon de manger trop de miel, et sonder les choses difficiles est trop difficile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Une ville forcée et sans murs, tel est l\'homme qui n\'a pas l\'empire de son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Comme la neige en été, et la pluie à la moisson, ainsi l\'honneur ne va pas à l\'insensé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Comme le passereau va voltigeant, et l\'hirondelle volant ainsi la malédiction non méritée n\'atteint pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Au cheval le fouet, à l\'âne le mors, et au dos de l\'insensé le bâton.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Ne réponds pas à l\'insensé selon sa folie, de peur de lui ressembler toi-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Réponds à l\'insensé selon sa folie. afin qu\'il ne s\'imagine pas être sage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Il se coupe les pieds, s\'abreuve de peines celui qui charge un fou d\'une mission.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Les jambes d\'un perclus sont pendantes; telle est une sentence dans la bouche des fous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Lancer une pierre avec la fronde, c\'est accorder des honneurs à un insensé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Une épine que tient levée un homme ivre, c\'est une sentence dans la bouche des fous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Tel un archer qui blesse chacun, tel est celui qui soudoie des fous, et soudoie tout venant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Comme le chien retourne à ce qu\'il a vomi, ainsi l\'insensé réitère sa folie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Vois cet homme qui s\'imagine être sage! Il y a plus à espérer d\'un insensé que de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Le lâche dit: « J\'entends sur le chemin le rugissant, il y a un lion dans la rue! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'La porte tourne sur ses gonds, et le lâche dans son lit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Le lâche plonge sa main dans le plat, il a peine à la ramener à sa bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Le lâche se trouve plus sage que sept hommes qui répondent avec jugement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Il prend un chien par les oreilles, celui qui en passant s\'échauffe pour une querelle qui n\'est pas la sienne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Tel un furieux qui décoche des traits, et des dards mortels,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'tel est l\'homme qui trompe son prochain, puis dit: « N\'ai-je pas badiné? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Faute de bois le feu s\'éteint; ôtez le médisant, la querelle cesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Le charbon donne de la braise, et le bois des flammes, et l\'homme querelleur allume la dispute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Les propos du rapporteur sont comme des friandises; ils s\'insinuent jusqu\'au fond des entrailles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'De l\'argent brut appliqué sur un têt, c\'est le feu sur les lèvres, et la malice dans le cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Dans ses discours l\'ennemi dissimule, mais dans son âme il s\'apprête à tromper.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Prend-il un ton gracieux, ne te fie pas à lui, car sept abominations sont dans son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'La haine se cache sous un faux semblant, mais sa malice se découvre dans l\'assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Qui creuse une fosse, y tombe, et la pierre revient sur celui qui la roule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'La langue fausse hait ceux qu\'elle va perdre, et la bouche flatteuse prépare la ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Ne te vante pas du lendemain, car tu ignores ce qu\'un jour enfante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Qu\'un autre te loue, et non ta propre bouche, un étranger, et non tes propres lèvres!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'La pierre est lourde, et le sable pesant; mais l\'humeur de l\'insensé pèse plus que tous deux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'La fureur est cruelle, et la colère impétueuse; mais qui pourra tenir devant la jalousie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Mieux vaut un reproche franc, qu\'une affection dissimulée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Les coups d\'un ami viennent de fidélité; mais un ennemi prodigue les baisers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'L\'homme rassasié foule le miel aux pieds; mais pour l\'affamé tout ce qui est amer, est doux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Tel l\'oiseau qui erre loin de son nid, tel est l\'homme qui erre loin de ses lieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'L\'huile et l\'encens réjouissent le cœur, et par un conseil cordial l\'ami est doux à l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Ne quitte pas ton ami, ni l\'ami de ton père, mais ne va pas chez ton frère le jour de ton malheur! Mieux vaut un voisin proche, qu\'un parent éloigné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Sois sage, mon fils, et réjouis mon cœur, et je saurai que répondre à qui m\'outragera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Le sage voit la calamité, et se met à l\'abri; les inconsidérés vont en avant, et sont punis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Prends-lui son manteau, car il a cautionné autrui, et nantis-toi de lui plutôt que de l\'étranger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Quand de grand matin à haute voix on salue son prochain, cela est regardé comme une imprécation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'L\'eau d\'une gouttière tombant sans relâche un jour de pluie, et la femme querelleuse sont choses pareilles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'qui l\'arrêterait, arrêterait le vent, et sa main appellerait [bientôt] l\'huile à son secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Le fer aiguise le fer, et l\'un aiguise la colère de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Qui garde son figuier, en mange le fruit, et qui a des soins pour son maître, obtient de l\'honneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Comme dans les eaux un regard {[}répond{]} à un regard, ainsi le cœur de l\'homme [répond] au cœur de l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Les Enfers et l\'abîme ne sont jamais rassasiés, et les yeux de l\'homme ne sont jamais rassasiés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Ce qu\'est le creuset pour l\'argent, la fournaise pour l\'or, que chacun le soit pour la bouche qui le loue!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Quand tu pilerais le fou dans le mortier, parmi les gruaux avec le pilon, sa folie ne le quittera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Examine l\'aspect de ton bétail, et sois attentif à tes troupeaux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Car l\'opulence n\'est pas éternelle; et une couronne se transmet-elle dans tous les âges?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'L\'herbe disparaît, et la tendre verdure se montre, et l\'on recueille les herbes des montagnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'les agneaux te donnent des vêtements, et les boucs, le prix d\'un champ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'le lait des chèvres suffit à ta nourriture, à la nourriture de ta maison, et à l\'entretien de tes servantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Sans qu\'on le poursuive, l\'impie prend la fuite, mais le juste a l\'assurance du jeune lion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Par la révolte d\'un pays, ses princes deviennent nombreux, mais si les hommes sont sages, et connaissent la droiture, {[}le prince{]} règne longtemps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Un homme qui est pauvre, et opprime les petits, est une pluie qui balaie et ne laisse point de pain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Ceux qui négligent la Loi, louent l\'impie, mais ceux qui gardent la Loi, s\'indignent contre lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Les hommes livrés au mal n\'ont pas l\'intelligence du juste, mais ceux qui cherchent l\'Éternel, ont l\'intelligence de tout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Mieux vaut un pauvre qui marche dans son innocence, que celui qui tourne dans une double voie, et qui est riche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Qui garde la Loi, est un fils intelligent, mais qui se plaît avec les prodigues, fait honte à son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Celui qui augmente son bien par l\'usure et l\'intérêt, l\'amasse pour le bienfaiteur du pauvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'De celui qui détourne l\'oreille pour ne pas écouter la Loi, les prières aussi sont une abomination.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Celui qui entraîne le juste dans la mauvaise voie, tombera dans la fosse même qu\'il a faite; mais les innocents auront le bien pour héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'A ses propres yeux le riche est sage, mais le pauvre intelligent le pénètre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Quand les justes triomphent, il y a grande pompe; mais quand les impies s\'élèvent, les hommes se cachent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Celui qui cache ses fautes, ne prospère point; mais qui les confesse et les délaisse, obtient miséricorde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Heureux l\'homme qui vit toujours dans la crainte! mais qui endurcit son cœur, tombe dans le malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Un lion rugissant et un ours affamé, c\'est le prince impie d\'un peuple pauvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Le prince privé de sens est un grand oppresseur; mais celui qui déteste la cupidité, règne longuement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'L\'homme qui est sous le poids d\'un meurtre, fuit jusques dans le tombeau, craignant d\'être saisi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Celui qui suit la voie innocente, sera sauvé; mais l\'homme tortueux qui suit deux voies, tombera dans l\'une.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Qui cultive son champ, sera rassasié de pain; et qui s\'attache aux fainéants, sera rassasié d\'indigence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'L\'homme probe sera comblé de bénédictions, mais qui veut s\'enrichir promptement, ne reste pas impuni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Etre partial n\'est point chose bonne; cependant pour une bouchée de pain, tel se rend criminel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'L\'envieux court après la richesse, et ne voit pas l\'indigence qui fond sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Celui qui reprend les hommes, finit par être mieux vu que le flatteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Celui qui a dépouillé son père ou sa mère, et dit: Ce n\'est pas un crime! est camarade du brigand.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'L\'homme qui s\'enfle, excite les querelles, mais qui se confie dans l\'Éternel, aura l\'abondance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Celui qui se fie en son sens, est un fou; mais qui suit la voie de la sagesse, échappe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Pour qui donne au pauvre, il n\'y a point d\'indigence, mais pour qui ferme ses yeux, grande malédiction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Quand les impies s\'élèvent, les hommes se cachent, mais quand ils périssent, les justes s\'accroissent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'L\'homme répréhensible qui se roidit, sera brisé soudain, et sans remède.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Quand les justes se multiplient, le peuple se réjouit; mais quand règne l\'impie, le peuple gémit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'L\'homme, ami de la sagesse, réjouit son père, mais qui se plaît avec les courtisanes, perd son bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Par la justice un roi consolide son Etat; mais celui qui accepte des dons, le ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Un homme qui flatte son prochain, tend un filet sous ses pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'Un piège gît dans le crime du méchant; mais le juste triomphe, et se réjouit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Le juste sait défendre les petits, mais l\'impie ne comprend pas la science.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Les moqueurs soufflent le feu dans la cité; mais les sages calment l\'irritation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Le juste qui est en dispute avec l\'insensé, ni par la colère, ni par l\'enjouement n\'arrive à la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Les hommes sanguinaires haïssent l\'innocent; mais les justes cherchent à lui sauver la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'L\'insensé produit son âme tout entière; mais le sage la tient en arrière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Qu\'un prince écoute les mensonges, tous ses serviteurs sont méchants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Le pauvre et l\'oppresseur se rencontrent; l\'Éternel fait luire la lumière aux yeux de tous deux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Du roi qui rend au pauvre fidèle justice, le trône subsiste éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'La verge et la correction donnent la sagesse; mais l\'enfant livré à lui-même fait honte à sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Quand les impies croissent, le péché croît; mais leur chute réjouira les regards des justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Corrige ton fils, et il te donnera du repos, et procurera des délices à ton âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Privé de révélation, un peuple est sans frein; heureux, s\'il garde la Loi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Les discours ne corrigent point un serviteur; quand même il comprend, il n\'obéit point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Vois-tu cet homme prompt à parler? Il y a plus à espérer d\'un fou que de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Si l\'on délicate son serviteur dès l\'enfance, il finit par vouloir être fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'L\'homme colère excite les querelles, et celui qui s\'échauffe, fait bien des fautes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'L\'orgueil de l\'homme l\'abaisse; mais l\'humble parvient à la gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Qui entre en part avec le voleur, est son propre ennemi; il a entendu la malédiction, et il ne dénonce pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'La peur des hommes tend un piège; mais qui se confie dans l\'Éternel, est mis à couvert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Plusieurs cherchent les regards du souverain; mais de l\'Éternel émane le jugement des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Le méchant est l\'abomination du juste; et celui qui marche droit, l\'abomination de l\'impie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Paroles d\'Agur, fils de Jaqué, prophétie, oracle donné par l\'Homme à Ithiel, à Ithiel et à Uchal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Oui, je suis plus stupide que personne, et je n\'ai point l\'intelligence d\'un humain;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'et je n\'ai ni appris la sagesse, ni connu la science des saints.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Qui monta au ciel, et en redescendit? Qui enserra le vent dans ses mains? Qui enveloppa les eaux dans sa robe? Qui plaça toutes les bornes de la terre? Quel est son nom et le nom de son fils, si tu le sais?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Toute parole de Dieu est pure. Il est un bouclier pour ceux qui se confient en Lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'N\'ajoute rien à ce qu\'il a dit, de peur qu\'il ne te châtie, et que tu ne sois convaincu de mensonge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Je Te demande deux choses: ne me les refuse pas, avant que je meure!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Eloigne de moi la fausseté et le langage menteur; ne me donne ni pauvreté, ni richesse, nourris-moi du pain qui est pour moi le nécessaire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'de peur que rassasié je ne te renie, et ne dise: « Qui est l\'Éternel? » ou qu\'appauvri je ne dérobe, et ne m\'attaque au nom de mon Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Ne calomnie pas le serviteur auprès de son maître, de peur qu\'il ne te maudisse, et que tu ne sois puni!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Il est une race qui maudit son père, et ne bénit point sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'Il est une race qui est pure à ses propres yeux, tandis que de sa souillure elle n\'est point lavée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Il est une race... que ses yeux sont altiers, et ses paupières hautaines!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Il est une race dont les dents sont des glaives, et les molaires des couteaux, pour dévorer le malheureux sur la terre, et les indigents, parmi les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'L\'Aluca a deux filles: Donne! Donne! Trois choses sont insatiables, il en est quatre qui jamais ne disent: « C\'est assez! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'les Enfers, et la femme stérile, la terre jamais rassasiée d\'eau, et le feu qui jamais ne dit: « C\'est assez! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'L\'œil qui se moque d\'un père, et dédaigne l\'obéissance envers une mère, les corbeaux de la vallée l\'arracheront, et les petits de l\'aigle le mangeront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Trois choses passent ma portée, il en est quatre que je ne pénètre pas:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'la trace de l\'aigle dans les Cieux, la trace du serpent sur le rocher, la trace du navire au sein de la mer, et la trace de l\'homme qui va vers une vierge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Telle est la manière de la femme adultère: elle mange, et s\'essuie la bouche et dit: « Je n\'ai point fait de mal. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Trois choses font trembler un pays, il en est quatre qu\'il ne peut supporter:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'un esclave devenu roi, un insensé dans l\'abondance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'la femme dédaignée devenue épouse, et la servante qui a chassé sa maîtresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Il y a sur la terre quatre animaux très petits, et pourtant sages et bien avisés:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'les fourmis, peuple qui n\'est point fort, et pourtant en été elles font leurs provisions;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'les gerboises, peuple qui n\'est point vigoureux, et pourtant dans les rochers elles pratiquent leur gîte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'les sauterelles n\'ont point de roi, et pourtant elles sortent toutes formées en bataillons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'le lézard saisit avec ses mains, et se trouve dans les palais des rois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Trois ont une belle démarche, et quatre, une belle allure:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'le lion, héros entre les animaux, et qui ne recule devant personne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, '{[}le coursier{]} ceint aux reins du harnais, ou le bélier et le roi à qui l\'on ne peut tenir tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Si tu as été fou par orgueil, et si tu as pensé à mal.... la main sur la bouche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Car la pression du lait produit du beurre, et la pression du nez produit du sang, et la pression de la colère produit la rixe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Discours au roi Lémuel. Maximes que lui enseigna sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Que te dirai-je, mon fils? que te dirai-je, fils de mes entrailles? que te dirai-je, fils qui as mes vœux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Ne livre pas aux femmes ta vigueur, et ne suis pas la voie qui perd les rois!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Ce n\'est pas aux rois, Lémuel, ce n\'est pas aux rois de boire du vin, ni aux princes de boire de la cervoise;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'de peur que, s\'ils boivent, ils n\'oublient la Loi, et n\'attentent aux droits de tous les fils du malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Donnez de la cervoise à qui va périr, et du vin à qui a l\'amertume dans le cœur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'qu\'il boive et oublie sa misère, et de ses peines perde le souvenir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Ouvre la bouche en faveur du muet. et pour défendre tous les enfants délaissés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Ouvre la bouche, et juge avec justice, et défends le misérable et le pauvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Une femme forte! qui pourra la trouver? Elle a plus de valeur que les perles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'En elle s\'assure le cœur de son mari, et les profits ne lui manqueront pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Elle lui fait du bien, et jamais de mal, tous les jours de sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Elle met en œuvre la laine et le lin, et fait avec plaisir le travail de ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Semblable aux navires des marchands, elle fait venir de loin ses denrées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Elle se lève, quand il est nuit encore; et distribue la nourriture à sa maison, et une tâche à ses servantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Elle pense à un champ, et elle l\'acquiert; du fruit de son travail elle plante une vigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Elle met à ses reins une ceinture de force, et fortifie ses bras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Elle goûte les bons effets de son industrie! la nuit sa lampe ne s\'éteint point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Elle porte la main à la quenouille, et ses doigts prennent le fuseau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Elle ouvre sa main au pauvre, et tend la main au misérable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Pour sa maison elle ne redoute point la neige; car toute sa maison est pourvue d\'étoffes précieuses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'elle se fait des couvertures, et le lin et la pourpre l\'habillent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Son mari est considéré aux Portes, quand il siège avec les Anciens du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Elle fait des tuniques, et les vend, et livre des ceintures au Cananéen.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Elle est revêtue de force et de dignité, et elle se rit du lendemain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Elle ouvre la bouche avec sagesse, et sa langue instruit avec grâce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Elle observe le mouvement de sa maison, et ne mange pas le pain d\'oisiveté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Ses fils se lèvent, et la disent heureuse, son mari {[}se lève{]}, et lui donne des louanges:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, '« Plusieurs femmes sont des femmes fortes, mais tu les surpasses toutes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'La grâce est illusion, et la beauté, vanité; c\'est la femme craignant Dieu qu\'on doit louer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Faites-la jouir du fruit de son travail! Qu\'aux Portes ses œuvres la louent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Paroles de l\'Ecclésiaste, fils de David, qui régnait à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Vanité des vanités, dit l\'Ecclésiaste, vanité des vanités! tout est vanité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Que reste-t-il à l\'homme de tout le labeur: dont il se travaille sous le soleil?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Une génération s\'en va, et une génération vient, et la terre est éternellement là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Et le soleil se lève, et le soleil se couche et se hâte vers son gîte, d\'où il se lève [encore].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Le vent souffle au sud, et tourne au nord; il va tournant, tournant, et le vent refait ses mêmes tours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Toutes les rivières se rendent à la mer, et la mer ne se remplit pas; les rivières répètent leur cours vers les lieux où elles coulent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Tout dire lasse, et nul homme ne saurait l\'énoncer; l\'œil ne regarde jamais à être rassasié, et l\'oreille n\'écoute jamais à être remplie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Ce qui a été, c\'est ce qui sera; et ce qui s\'est fait, c\'est ce qui se fera, et il n\'y a rien de nouveau sous le soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Il est telle chose dont on dit: « Eh! voyez! c\'est nouveau! » Elle fut déjà dans les siècles qui nous ont précédés:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'le souvenir du passé ne reste pas; et les choses de l\'avenir qui seront, ne resteront pas davantage dans le souvenir des hommes à venir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Moi, l\'Ecclésiaste, je fus Roi d\'Israël à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Et j\'appliquai mon cœur à faire avec sagesse la recherche l\'investigation de tout ce qui se fait sous le ciel. C\'est là une tâche ingrate que Dieu a imposée aux enfants des hommes pour qu\'ils s\'y exercent. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Je vis tous les actes qui se font sous le soleil; et voici, le tout est vanité et effort stérile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Ce qui est de travers ne peut se redresser, et les lacunes ne peuvent se compter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Je disais en mon cœur: Voici, j\'ai acquis une sagesse plus grande et plus étendue que tous mes prédécesseurs à Jérusalem, et mon cœur a vu beaucoup de sagesse et de science.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Mais ayant appliqué mon cœur à discerner ce qui est sagesse, et à discerner ce qui est folie, je reconnus que cela aussi est un effort stérile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Car beaucoup de sagesse est accompagné de beaucoup de mécontentement, et qui augmente sa science, augmente ses peines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Je dis en mon cœur: Viens, [mon âme!] eh bien! je veux te faire essayer de la joie, et goûte ce qui est bon! Mais voici, cela aussi est une vanité:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'je dis du rire, qu\'il est extravagant, et de la joie: Que procure-t-elle?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Je pris en mon cœur le parti de maintenir ma chair dans le vin, tandis que mon cœur me guiderait avec sagesse, et de m\'attacher à la folie, jusqu\'à ce que je visse ce qu\'il est bon aux enfants des hommes de faire sous le ciel, pendant le petit nombre des jours de leur vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'J\'exécutai de grands ouvrages: je me bâtis des maisons; je me plantai des vignes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'je me fis des jardins et des parcs, et y plantai toutes sortes d\'arbres à fruit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'je me fis des étangs d\'eau, pour en arroser la forêt qui montait en arbres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'j\'achetai des serviteurs et des servantes, et j\'eus des serfs nés dans la maison; j\'eus aussi des troupeaux de gros et de menu bétail, plus que tous mes prédécesseurs à Jérusalem;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'je m\'amassai aussi de l\'argent et de l\'or, et les trésors des rois et des provinces; je me procurai des chanteurs et des chanteuses, et, les délices des enfants des hommes, les plus belles des femmes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'et je devins grand et plus considérable que tous mes prédécesseurs à Jérusalem;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'de plus ma sagesse me resta; et de tout ce que mes yeux demandaient, je ne leur refusai rien; je ne privai mon cœur d\'aucune joie; car mon cœur eut de la joie dans tout mon labeur, et ce fut la part que je retirai de tout mon labeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Mais quand je considérai tous les ouvrages faits par mes mains, et le labeur dont je m\'étais travaillé pour exécuter, je vis que tout est vanité et effort stérile, et que rien ne profite sous le soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Et je me mis à examiner la sagesse et la folie, et l\'extravagance. (Car que fera l\'homme qui succédera au Roi? Ce que jadis on a fait.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Et je vis que la prééminence de la sagesse sur la folie est la même que la prééminence de la lumière sur les ténèbres:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'le sage a ses yeux à la tête, et le fou chemine dans les ténèbres; néanmoins je reconnus aussi que l\'un et l\'autre ils subissent une même destinée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Alors je dis en mon cœur: La destinée de l\'insensé, je la subirai aussi; et pourquoi ai-je été sage de reste? Et je dis en mon cœur: C\'est aussi là une vanité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Car pour le sage, pas plus que pour le fou, il n\'y a de mémoire éternelle, puisque dans les jours à venir ils seront oubliés l\'un et l\'autre depuis longtemps: le sage, hélas! meurt aussi bien que l\'insensé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Alors la vie me fut odieuse, et je me dégoûtai de tout ce qui se passe sous le soleil; car tout est vanité et effort stérile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Et tout le labeur dont je m\'étais travaillé sous le soleil, me fut odieux, car je dois le léguer à l\'homme qui me succédera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Et qui sait si ce sera un sage ou un fou? Et il disposera de tout le travail que j\'ai exécuté sous le soleil avec tant de peine et de sagesse. C\'est aussi là une vanité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Alors j\'en vins à laisser mon cœur désespérer de tout le labeur dont je m\'étais travaillé sous le soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'En effet qu\'il se trouve un homme dont le travail aura été fait sagesse, connaissance et succès, c\'est à l\'homme qui ne se sera point occupé, qu\'il le laissera comme héritage. C\'est aussi là une vanité et un grand mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Car que revient-il à l\'homme pour tout son labeur et la préoccupation de son cœur, dont il s\'est tourmenté sous le soleil?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'En effet tous ses jours sont douloureux, et le chagrin est son affaire; même la nuit son cœur ne repose pas. C\'est aussi là une vanité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Rien de mieux pour l\'homme que de manger et de boire, et de faire goûter du bien-être à son âme, pendant son travail. Je vis que cela aussi est un don de la main de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Qui peut en effet manger et jouir, si ce n\'est moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Car à l\'homme qui Lui plaît, Il donne sagesse et science et joie; mais au pécheur Il donne la tâche d\'amasser et d\'accumuler, pour le donner à celui qui plaît à Dieu. C\'est aussi là une vanité et un effort stérile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Toute chose a son temps, et toute affaire son moment a sous le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Il est un temps pour naître, et un temps pour mourir; il est un temps pour planter, et un temps pour arracher les plants;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'il est un temps pour tuer, et un temps pour guérir; il est un temps pour démolir, et un temps pour édifier;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'il est un temps pour pleurer, et un temps pour rire; il est un temps pour se frapper la poitrine, et un temps pour danser;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'il est un temps pour jeter les pierres, et un temps pour ramasser les pierres; il est un temps pour embrasser, et un temps pour s\'abstenir d\'embrasser;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'il est un temps pour chercher, et un temps pour laisser perdre; il est un temps pour conserver, et un temps pour se défaire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'il est un temps pour déchirer, et un temps pour coudre; il est un temps pour se taire, et un temps pour parler;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'il est un temps pour aimer, et un temps pour haïr; il est un temps de guerre, et un temps de paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Que gagne celui qui agit, à se peiner?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'J\'ai vu la tâche que Dieu a donnée aux enfants des hommes, pour qu\'ils s\'y exercent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Il fait toute chose belle en son temps; quoiqu\'il ait mis dans leur cœur [le sentiment] de l\'éternité, ils ne parviennent cependant pas à comprendre l\'œuvre que Dieu fait, du commencement à la fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Je comprends qu\'ils n\'ont d\'autre bien que de se réjouir, et de s\'accorder du bien-être durant leur vie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'et que, quand tel homme mange et boit et goûte des jouissances tout en travaillant, c\'est aussi là un don de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Je comprends que tout ce que Dieu opère est éternel; il n\'y a rien à y ajouter, et rien à en retrancher, et Dieu opère afin qu\'on le craigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Ce qui est, a été jadis; et ce qui est à venir, a été jadis; et Dieu reproduit ce qui est passé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Et je considérai encore sous le soleil le siège du jugement, il y avait iniquité; et le siège de la justice, il y avait iniquité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Je dis en mon cœur: Dieu jugera le juste et le méchant; car le moment [viendra] pour toute affaire et pour toute œuvre, alors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Je dis en mon cœur, quant aux enfants des hommes, que le but de Dieu a été de leur découvrir et de les mettre à même de voir qu\'il en est d\'eux comme des animaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Car le sort des enfants des hommes est le même que le sort des animaux, et ils ont un même sort. Ils meurent les uns comme les autres; tous ils ont le même esprit de vie, et l\'homme n\'a aucun avantage sur l\'animal; car tout est vanité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Tout marche à un rendez-vous commun. Tout naquit de la poudre, et tout rentre dans la poudre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Qui connaît l\'esprit de vie des enfants des hommes, lequel monte en haut et l\'esprit de vie de l\'animal, lequel descend en bas dans la terre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Je vis donc qu\'il n\'y a rien de mieux sinon que l\'homme ait de la joie de ce qu\'il fait; car c\'est là son lot. Car qui le fera venir pour voir ce qui sera après lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Et je revins à considérer toutes les oppressions qui ont lieu sous le soleil; et je vis les larmes des opprimés, et ils n\'avaient point de consolateurs; et la violence qui venait de la main de leurs oppresseurs, et ils n\'avaient point de consolateurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Alors je déclarai les morts, qui sont morts depuis longtemps, plus heureux que les vivants demeurés vivants jusques ici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Mais plus heureux que les uns et les autres est celui qui n\'est pas arrivé dans cette vie, et n\'a pas été témoin des méchantes actions qui se font sous le soleil. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Et je vis tout le labeur et tout le résultat de l\'activité; c\'était rivalité entre celui-ci et celui-là. Cela aussi est une vanité et un effort stérile. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'L\'insensé tient ses bras croisés, et se consume lui-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Mieux vaut le creux de la main rempli de repos, que deux pleines poignées de labeur et d\'effort stérile. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Et je vis encore une vanité sous le soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Cet homme est seul, et n\'a pas un autre lui-même; il n\'a ni fils, ni frère, et cependant son labeur est sans fin, et ses yeux n\'ont jamais assez des richesses. Pour qui donc est-ce que je me peine, et sèvre mon âme du bonheur? C\'est aussi là une vanité et une tâche ingrate.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Deux valent mieux qu\'un, car ils retirent un bon salaire de leur travail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'En effet, s\'ils tombent, l\'un relève l\'autre; mais malheur à celui qui est seul et qui tombe, et n\'a pas un second pour le relever!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'De même quand deux couchent ensemble, ils ont chaud; mais celui qui est seul, comment aurait-il chaud?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Et si quelqu\'un attaque l\'un des deux, ils seront à deux pour lui tenir tête; et le triple cordon n\'est pas vite rompu. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Un enfant pauvre, mais sage, vaut mieux qu\'un roi vieux et insensé qui ne sait plus être éclairé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Car il sortit de la maison des prisonniers pour être roi, quoique né pauvre dans le royaume qui serait le sien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Je vis tous les vivants qui se promènent sous le soleil escorter l\'enfant, cet autre, qui succéda au trône:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'tout le peuple, tous ceux à la tête desquels il était, ne finissaient pas; eh bien! les après-venants ne seront plus ravis de lui. C\'est que cela aussi est une vanité et un effort stérile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Ne sois point pressé d\'ouvrir la bouche, et que ton cœur ne se hâte point de proférer une parole en la présence de Dieu! Car Dieu est dans le Ciel, et toi sur la terre; c\'est pourquoi use de peu de paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Car si beaucoup d\'affaires donnent lieu à des rêves, beaucoup de paroles donnent lieu à des propos insensés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Quand tu fais à Dieu un vœu, ne tarde pas de l\'accomplir! Car Il ne prend aucun plaisir aux insensés; accomplis ce dont tu as fait vœu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Il vaut mieux ne faire aucun vœu, que de faire un vœu, et ne pas l\'accomplir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Ne permets pas à ta bouche de faire pécher ta chair, et ne dis pas en présence de l\'envoyé [de Dieu]: Ç\'a été une méprise! Pourquoi Dieu devrait-Il s\'irriter pour un propos de ta part, et te faire perdre le travail de tes mains?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Car si dans beaucoup de rêves il y a des vanités, [il y en a aussi] dans beaucoup de paroles; oui crains Dieu! –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Si tu vois dans une province le pauvre opprimé, la justice et le droit déniés, n\'en sois pas éperdu. Car celui qui est élevé, est surveillé par un autre plus élevé encore, et tous ils ont au-dessus d\'eux un être suprême.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Mais un avantage pour un pays à tous égards, c\'est un roi que le pays honore. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Celui qui aime l\'argent, ne sera pas rassasié par l\'argent, et celui qui aime la richesse, n\'en retire pas du profit. C\'est aussi là une vanité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Quand le bien devient plus grand, ceux qui le consomment, deviennent aussi plus nombreux. Et qu\'y gagne son possesseur, qu\'un spectacle pour ses yeux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Le sommeil du travailleur est doux, qu\'il mange peu ou beaucoup; mais le rassasiement du riche ne le laisse pas dormir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Il est un mal douloureux que j\'ai vu sous le soleil: des richesses gardées par leur maître pour son propre malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Car ces richesses se perdent par un événement fâcheux, et le fils qu\'il aura engendré, n\'en aura rien entre les mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Comme il est sorti nu du sein maternel, il s\'en ira tel qu\'il était venu, et pour sa peine il ne prélèvera rien qu\'il emporte dans ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Et c\'est aussi là un mal douloureux. Tout comme il était venu, ainsi il s\'en va. Et que lui reste-t-il après s\'être peiné pour du vent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'De plus, toute sa vie il mange dans les ténèbres, et il a beaucoup de chagrin, et du malaise, et de l\'aigreur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Voici ce que j\'ai vu: c\'est une chose bonne et en même temps belle que de manger et boire, et goûter du bien-être à côté de tout le labeur dont l\'homme se travaille sous le soleil, pendant le petit nombre des jours de vie que Dieu lui a donnés; car c\'est là son lot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'De même, quand Dieu a accordé à quelque homme des biens et des richesses, et lui a permis d\'en jouir, et d\'en prélever sa part, et d\'avoir de la joie de son travail, c\'est là un don de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Et en effet, il ne repasse pas beaucoup sur les jours de sa vie, parce que Dieu le préoccupe de la joie de son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Non, il n\'est sur la terre pas un homme juste qui fasse le bien et ne pèche point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Il est une calamité que j\'ai vue sous le soleil, et qui pèse souvent sur les humains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Il est tel homme auquel Dieu donne des biens, des richesses et de la gloire, et cela, à ce qu\'il ait de quoi ne priver son âme de rien de ce qu\'il désire; et Dieu ne le laisse pas maître d\'en jouir, mais c\'est un étranger qui en jouit. C\'est là une vanité et un mal fâcheux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Si un homme avait cent fils, et s\'il vivait un grand nombre d\'années, et que les jours de ses années se multipliassent, et si son âme ne se rassasiait pas de bien-être, et que de plus il restât sans sépulture, je dirais: Plus heureux que lui est l\'avorton;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'car celui-ci naît vainement, et il s\'en va obscurément, et les ténèbres recouvrent son nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'il n\'a non plus ni vu ni connu le soleil: il a le repos de plus que l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Que s\'il vivait deux fois mille ans, mais sans jouir des biens... tout ne va-t-il pas au même rendez-vous? –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Tout le labeur de l\'homme aboutit à sa bouche; toutefois sa cupidité n\'est jamais assouvie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Quel avantage, en effet, le sage a-t-il sur le fou? Quel avantage, le pauvre qui sait vivre en face des hommes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Mieux vaut ce qui est à la portée de nos yeux, que le mouvement de la cupidité: il est aussi une vanité et un effort stérile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Ce qui existe, a dès longtemps été appelé par son nom; et l\'on sait ce qu\'est l\'homme, et il ne saurait disputer avec Celui qui est plus puissant que lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Car il y a une multitude de choses qui multiplient la vanité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Qu\'est-ce qui reste à l\'homme? Car qui sait ce qui est bien pour l\'homme dans la vie, pendant les quelques jours de sa vie de vanité qu\'il passe comme l\'ombre? Et qui révélera à l\'homme ce qui aura lieu après lui sous le soleil?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Bonne réputation vaut mieux que bon parfum, et le jour de la mort, que le jour de la naissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Mieux vaut aller dans la maison du deuil, que d\'aller dans la maison du festin; car c\'est là la fin de tous les hommes, et le vivant y rentre en lui-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Mieux vaut la tristesse que le rire; car avec un visage triste, le cœur devient bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Le cœur des sages est dans la maison du deuil, mais le cœur des fous est dans la maison de la joie. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Mieux vaut écouter la censure d\'un sage, que d\'être un auditeur des chansons des fous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Car tel le pétillement des épines sous la chaudière, tel est le rire du fou; c\'est aussi là une vanité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Car l\'ambition d\'opprimer rend le sage extravagant, et les présents corrompent le cœur. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Mieux vaut la fin d\'une chose que son commencement; mieux vaut patience que présomption. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Ne sois point en ton âme prompt à t\'indigner! car l\'indignation se dépose dans le sein de l\'insensé. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Ne dis pas: Pourquoi les jours d\'autrefois étaient-ils meilleurs que ceux-ci? Car ce n\'est pas la sagesse qui te dicterait cette question. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'La sagesse est aussi avantageuse qu\'un héritage, et c\'est un profit pour ceux qui voient le soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Car la sagesse offre un abri, l\'argent offre un abri; mais l\'avantage reste à la science: la sagesse donne la vie à ceux qui la possèdent. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Considère l\'action de Dieu; car qui peut rendre droit ce qu\'il a fait courbe? –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Au jour du bonheur, sois heureux, et au jour malheur, ouvre les yeux! Dieu est l\'auteur de celui-ci, aussi bien que de celui-là, et cela, afin que de son avenir l\'homme ne découvre rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'J\'ai vu tout cela durant mes jours de vanité. Il est tel juste qui périt malgré sa justice, et tel impie qui prolonge ses jours malgré sa méchanceté. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Ne sois pas juste à l\'excès, et ne te montre pas trop sage! Pourquoi te détruirais-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Ne sois pas impie à l\'excès, et ne deviens pas un insensé! Pourquoi mourrais-tu avant ton heure?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Il est bon que tu tiennes à ce dernier avis, et que tu ne te départes point du premier; car celui qui craint Dieu, échappe à toutes ces choses. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'La sagesse rend le sage plus fort que dix capitaines qui sont dans une place. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Non, il n\'est sur la terre pas un homme juste qui fasse le bien et ne pèche point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Ne prends non plus pas garde à tous les propos qu\'on tient, afin de ne pas t\'entendre maudire par ton serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Car bien des fois aussi ton cœur te rappelle que de même tu as maudit les autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'J\'ai tenté toutes ces choses avec la sagesse. Je dis: Je veux être sage, mais elle reste à distance de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Ce qui est lointain et profond, profond, qui saurait l\'atteindre? –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Je me suis mis avec mon cœur à faire la ronde, pour connaître et explorer et chercher la sagesse et la raison, et pour connaître l\'impiété, la folie, la déraison et le délire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'Et je trouvai quelque chose de plus amer que la mort, c\'est la femme dont le cœur est un lacs et un filet, et les mains, des chaînes. Celui qui est bon devant Dieu, lui échappe; mais le pécheur est enlacé par elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Voyez! c\'est ici ce que j\'ai trouvé en comparant une chose avec une autre pour trouver la raison;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'voici ce que mon âme cherche encore sans que je l\'aie trouvé: un homme, sur mille je l\'ai trouvé; mais une femme, dans tout ce nombre je ne l\'ai pas trouvée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'La seule chose, prends-y garde, que j\'aie trouvée, c\'est que Dieu créa les hommes droits, mais eux, ils ont cherché beaucoup de détours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Qui est égal au sage? et qui connaît l\'explication des choses? La sagesse de l\'homme rend son visage rayonnant et lui ôte son air farouche. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Je [te le dis]: Observe l\'ordre du roi, et cela, à cause du serment que tu as fait à Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Ne le déserte pas témérairement, et ne persévère pas dans un mauvais parti, car il peut faire tout ce qu\'il lui plaît,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'd\'autant que la parole du roi est efficace; et qui lui dira: Que fais-tu? –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Qui garde le commandement est étranger à tout mauvais parti, et le cœur du sage connaît le moment et la manière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Car pour toute chose il est un moment et une manière: aussi bien les maux qui menacent l\'homme sont nombreux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'nul en effet ne sait ce qui peut arriver, car qui est-ce qui lui indiquera comment les choses se passeront? –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Nul n\'est maître de son souffle de vie, à pouvoir retenir son souffle de vie; et nul n\'est maître du jour de la mort; il n\'y a point d\'exemption pour ce combat, et le crime ne libère pas les siens. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'J\'ai vu toutes ces choses, et j\'ai pris garde à tous les actes qui se font sous le soleil. Il y a des époques où un homme a l\'empire sur les hommes pour leur malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'J\'ai vu alors les impies recevoir une sépulture, et ceux qui avaient fait le bien, étaient venus, et ils partirent du lieu saint, et ils furent oubliés dans la Ville. C\'est aussi là une vanité. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Parce que la sentence prononcée sur les mauvaises actions ne s\'exécute pas promptement, c\'est pourquoi le cœur des enfants des hommes se remplit en eux du désir de faire le mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Mais quand même le pécheur commet cent fois le crime, et prolonge ses jours, je sais pourtant que ceux qui craignent Dieu, se trouveront bien d\'avoir craint en sa présence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'Mais il ne s\'en trouvera pas bien l\'impie, et de même qu\'une ombre, il ne prolongera pas ses jours, lui qui n\'a pas craint en présence de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Il est une vanité qui a lieu sur la terre, c\'est qu\'il y a des justes dont le sort est en rapport avec les œuvres des impies, et qu\'il y a des impies dont le sort est en rapport avec les œuvres des justes. Je dis: C\'est là aussi une vanité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Et je vantai la joie, parce qu\'il n\'y a pas d\'autre bien pour l\'homme sous le soleil que de manger et boire et se réjouir; c\'est là ce qui lui reste pour son labeur, durant les jours de vie que Dieu lui accorde sous le soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Lorsque je pris à cœur de connaître la sagesse, et de considérer les affaires dont on s\'occupe sur la terre, (car ni jour ni nuit on ne laisse ses yeux sentir le sommeil)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'alors je vis toute l\'œuvre de Dieu, l\'impuissance où est l\'homme de saisir l\'œuvre qui s\'accomplit sous le soleil; quelque peine que l\'homme prenne pour chercher, il ne trouve cependant pas, et quand même le sage voudrait connaître, il ne parviendrait pourtant pas à saisir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'En effet, j\'ai appliqué mon cœur à toutes ces choses, et cela pour éclaircir ce fait, que les justes et les sages et leurs travaux sont entre les mains de Dieu, l\'homme ne sachant s\'il est aimé ou haï: ils sont en face de la question tout entière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Tout arrive pareillement à tous; mêmes événements au juste et à l\'impie, à l\'homme bon et pur et à l\'impur, à celui qui sacrifie et à celui qui ne sacrifie pas; il en est de l\'homme de bien comme du pécheur, de celui qui jure, comme de celui qui craint de jurer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'C\'est ici un mal dans tout ce qui arrive sous le soleil, c\'est que tous ont les mêmes destinées: dès lors aussi le cœur des enfants des hommes se remplit de malice, et la folie est dans leur cœur pendant leur vie, et après cela... chez les morts! En effet, qui est excepté?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Tous ceux qui vivent, conservent l\'espérance; un chien vivant vaut mieux qu\'un lion mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Car les vivants savent qu\'ils mourront; mais les morts ne savent absolument rien, et il n\'y a plus de rétribution pour eux, puisque leur mémoire est oubliée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'C\'en est fait dès longtemps et de leur amour, et de leur haine, et de leur ambition; et pour l\'éternité ils n\'entrent plus en part de rien de ce qui se fait sous le soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Va, mange gaiement ton pain, et bois ton vin dans la joie de ton cœur, car dès longtemps Dieu prend plaisir à ce que tu fais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Porte en tout temps des vêtements blancs, et que sur ta tête jamais l\'huile ne manque!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Jouis de la vie avec la femme que tu aimes, durant tous les jours de ta vie de vanité, qu\'il t\'a donnés sous le soleil, durant tous les jours de ta vie de vanité! Car c\'est ta part dans la vie, et dans le labeur dont tu te fatigues sous le soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Emploie ta force à faire tout ce que ta main trouvera à faire! Car il n\'y a plus ni œuvre, ni prudence, ni science, ni sagesse dans les Enfers où tu vas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'J\'ai encore vu sous le soleil que la course n\'est pas pour les agiles, ni la guerre pour les braves, non plus que le pain pour les sages, non plus que les richesses pour les habiles, non plus que la faveur pour ceux qui savent; mais le temps et les événements leur viennent à la traverse à tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Car le mortel ignore son heure, ainsi que les poissons qui se prennent au filet meurtrier, et comme les oiseaux qui se prennent dans les lacs: comme eux les enfants des hommes sont enlacés au jour du malheur, quand il fond sur eux tout-à-coup.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Néanmoins j\'ai vu de la sagesse sous le soleil, et elle m\'apparut grande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Il existait une petite ville, où il ne se trouvait qu\'un petit nombre d\'hommes. Et un grand roi marcha contre elle, et il la cerna et éleva contre elle de grandes redoutes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Et il s\'y trouvait un homme pauvre qui était sage; et ce fut lui qui par sa sagesse sauva la ville; mais personne ne garda le souvenir de cet homme pauvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Et je dis: La sagesse vaut mieux que la bravoure, quoique la sagesse du pauvre soit dédaignée, et que ses discours ne soient pas écoutés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Les discours calmes des sages sont plus écoutés que la clameur du souverain qui est du nombre des fous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'La sagesse vaut mieux que des armes de guerre; mais un seul pécheur gâte beaucoup de bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Des mouches mortes font exhaler une odeur fétide à l\'huile du parfumeur; un peu de folie a la prépondérance sur la sagesse et l\'honneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'La raison du sage est à sa droite; la raison du fou est à sa gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Quelle que soit la voie que suive le fou, il manque de sens, et il dit à chacun qu\'il est un fou.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Si la colère du souverain s\'élève contre toi, ne cède pas la place, car le calme fait céder de grands péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Il est un mal que j\'ai vu sous le soleil, par l\'effet d\'une méprise qui procède du prince:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'la folie est placée en très haut lieu, et des riches sont assis en lieu bas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'J\'ai vu des esclaves montés sur des chevaux, et des princes marchant à pied comme des esclaves. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Celui qui creuse une fosse, y tombera; et celui qui fait une brèche à un mur, sera mordu par un serpent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Celui qui remue des pierres, s\'y fera mal, et celui qui fend du bois, se risque;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'si le fer est émoussé, et qu\'il n\'en affile pas le tranchant, il lui faudra un effort plus grand; mais la sagesse a l\'avantage de donner l\'adresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Si le serpent mord quand il n\'est pas enchanté, l\'enchanteur ne sert à rien. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Les discours de la bouche du sage ont la grâce; mais le fou est la victime de ses propres lèvres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'le début des paroles de sa bouche est folie, et la fin de son discours est un délire malfaisant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Et le fou prodigue les paroles; [cependant] l\'homme ignore l\'avenir, et qui lui découvre ce qui aura lieu après lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Le travail du fou le fatigue, car il ne sait pas trouver le chemin de la ville. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Malheur à toi, pays, qui as pour roi un enfant, et dont les princes se mettent à table dès le matin!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Bonheur à toi, pays, qui as pour roi un fils de noble race, et dont les princes se mettent à table en temps convenable, pour se restaurer, et non pour boire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Quand il y a paresse, la charpente se disloque; et, quand les mains sont lâches, le logis a des voies d\'eau. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'On apprête un festin pour se réjouir, et le vin égaie les vivants; et l\'argent répond à tout. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Même dans ta pensée ne maudis pas le roi; et au fond de la chambre où tu couches, ne maudis pas le riche! Car l\'oiseau du ciel emportera tes propos, et le volatile ailé publiera tes discours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Jette ton pain à la surface des eaux, car longtemps après tu le retrouveras;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'fais-en part à sept et même à huit; car tu ne sais pas quelle calamité il y aura sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Quand les nuages sont pleins de pluie, ils la versent sur la terre; et, que l\'arbre tombe vers le sud ou vers le nord, il reste là, où il est tombé. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Celui qui observe le vent, ne sèmera point; et celui qui regarde les nuages, ne récoltera point. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'De même que tu ignores quelle est la route du vent, et comment les os se forment dans le sein de la femme enceinte de même tu ne saurais connaître l\'œuvre de Dieu qui fait toutes choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Dès le matin sème tes semences, et au soir ne laisse pas ta main oisive! Car tu ne sais si c\'est l\'une ou l\'autre qui réussira, ou si toutes deux elles sont également bonnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'La lumière est douce, et c\'est un bonheur pour les yeux de voir le soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Car, lors même que l\'homme vit un grand nombre d\'années, il trouve de la joie dans toutes; il se souvient d\'ailleurs qu\'il y aura bien des jours sombres, et que tout l\'avenir est une vanité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Réjouis-toi, jeune homme, pendant ton jeune âge, et laisse ton c{\\oe}ur être heureux pendant les jours de ta jeunesse; et suis la voie que te montre ton c{\\oe}ur, et le regard de tes yeux. Sache en même temps que sur toutes ces choses Dieu t\'appellera au jugement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Et bannis le chagrin de ton c{\\oe}ur, et éloigne les maux de ton corps! Car la jeunesse et l\'aurore sont un souffle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Et souviens-toi de ton Créateur pendant les jours de ta jeunesse, avant que les jours des maux arrivent, et que viennent les années dont tu diras: Je n\'y ai point de plaisir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'avant que s\'obscurcissent le soleil et la lumière, et la lune et les étoiles, et que les nuages reparaissent après la pluie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'temps où les gardes de la maison ont le tremblement, et où les hommes robustes se courbent; où les meunières sont oisives, parce que leur nombre est réduit; où celles qui regardent de leurs fenêtres ont des yeux ternes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'où les portes sont fermées du côté du dehors; cependant le moulin rend des sons grêles, et l\'on s\'éveille au chant du passereau et l\'on trouve faibles tous les effets du chant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'alors aussi on redoute les lieux élevés, et l\'on a des terreurs en marchant et l\'on dédaigne l\'amande, et l\'on se dégoûte de la sauterelle et la câpre a perdu sa vertu; car l\'homme s\'avance vers son séjour éternel, et les pleureuses vont parcourir les rues;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'avant que le cordon d\'argent soit détaché, et la lampe d\'or mise en pièces; et avant qu\'à la fontaine le seau se brise et qu\'à la citerne la roue soit rompue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'et que la poudre retourne dans la terre, comme elle y était, et que l\'esprit retourne à Dieu qui l\'a donné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Vanité des vanités, dit l\'Ecclésiaste, tout est vanité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Au reste, comme d\'ailleurs l\'Ecclésiaste était sage, il enseigna aussi la science au peuple, et il fit des investigations et des recherches, et il fut l\'auteur d\'un grand nombre de maximes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'L\'Ecclésiaste s\'appliqua à trouver des propos excellents; et ce qui a été écrit avec droiture, est le langage, de la vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Les paroles des sages sont comme des aiguillons, et les maîtres des assemblées sont comme des clous bien plantés; c\'est un seul Berger qui les donne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'D\'ailleurs, mon fils, c\'est là que tu iras puiser la lumière; la composition de beaucoup de livres n\'a pas de fin, et trop d\'étude est une fatigue pour le corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Ecoutons la conclusion de tout le discours: Crains Dieu et garde ses commandements! car c\'est là le tout pour l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Car Dieu fera venir toutes les œuvres au jugement qu\'il tiendra sur tout ce qui est caché, soit bien, soit mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Cantique des cantiques, de Salomon. Qu\'il m\'embrasse des baisers de sa bouche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'car tes caresses sont plus exquises que le vin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'L\'huile qui te parfume a une odeur suave; ton nom est un parfum qui se répand; aussi les vierges ont pour toi de l\'amour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Entraîne-moi! nous courrons après toi. Le roi m\'introduit dans ses appartements: dans nos transports, de toi nous voulons nous réjouir, célébrer ton amour plutôt que le vin; on a pour toi un véritable amour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Je suis noire, mais gracieuse, filles de Jérusalem, comme les tentes de Cédar, comme les draperies de Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Ne me considérez pas, parce que je suis noire, parce que le soleil a lancé sur moi ses regards; les fils de ma mère, irrités contre moi, m\'ont réduite à garder les vignes, et ma vigne, la mienne, je n\'ai pu la garder. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Dis-moi, ô toi qu\'aime mon âme, où tu pais tes brebis, où tu les fais reposer à midi! car pourquoi errerais-je éperdue autour des troupeaux de les compagnons? – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Si tu l\'ignores, ô la plus belle des femmes, suis seulement les traces des brebis, et mène paître tes chevreaux près des cabanes des bergers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Au coursier du char de Pharaon je te compare, ma bien-aimée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Tes joues sont belles, entre les rangs [de perles], et ton col, au milieu des colliers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Nous le ferons des colliers d\'or semés de points d\'argent.– –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Tandis que le roi est entouré de sa cour, mon nard exhale son parfum.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Mon bien-aimé est pour moi un bouquet de myrrhe, qui toujours est fixé sur mon sein.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Mon bien-aimé est pour moi une grappe de troène des vignobles d\'En-Gueddi. – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Voici, tu es belle, ma bien-aimée, tu es belle! tes yeux sont ceux de la colombe. – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Voici, tu es beau, mon bien-aimé, tu es aimable aussi; et notre lit c\'est la verdure,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'les solives de nos maisons sont les cèdres, et nos lambris, les cyprès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Je suis un narcisse de Saron, un lys des vallées. – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Tel un lys parmi les ronces, telle est ma bien-aimée parmi les jeunes filles. – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Tel un pommier parmi les arbres, tel est mon bien-aimé parmi les jeunes hommes. Mon désir est d\'être assise à son ombre, et son fruit est doux à mon palais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Il m\'a fait entrer dans la maison où le vin coule, et la bannière sous laquelle il me range, c\'est l\'amour...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Pour me soutenir donnez-moi le sirop de raisins, donnez-moi comme cordial la pomme [de Cydon]! car je suis malade d\'amour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Que sa main gauche se place sous ma tête, et que sa droite m\'embrasse! – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Je vous adjure, filles de Jérusalem, par les gazelles et par les biches des champs, n\'éveillez pas, ne réveillez pas mon amour, plus tôt qu\'elle ne voudrait!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'C\'est la voix de mon bien-aimé! Voici, il vient franchissant par sauts et par bonds les monts et les collines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Mon bien-aimé égale la gazelle, ou le faon des biches. Le voilà debout derrière notre mur, avançant ses yeux par la fenêtre, et les faisant briller au travers du treillis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Mon bien-aimé se met à parler, et il me dit: « Lève-toi, ma bien-aimée, ma beauté, et viens!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Car voici, l\'hiver est passé, les pluies ont cessé et ont fui; les fleurs paraissent sur la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'la saison des mélodies est là, et la voix de la tourterelle se fait entendre dans notre contrée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'le figuier embaume ses fruits, et la vigne est en fleur, elle exhale son parfum. Lève-toi, ma bien-aimée, ma beauté, et viens!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Ma colombe! dans les cavités des rochers, dans les retraites des lieux escarpés, fais-moi voir ta figure, fais-moi entendre ta voix! car ta voix est douce, et ta figure gracieuse. » –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Faites pour nous la chasse aux renards, aux petits renards qui ravagent les vignes, quand nos vignes sont en fleur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Mon bien-aimé est à moi, et je suis à lui, il paît son troupeau parmi les lys.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'En attendant le trais du jour, et la fuite des ombres, reviens! toi, mon bien-aimé, égalant la gazelle ou le faon des biches franchis les monts qui nous séparent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Une nuit, étant couchée, je cherchais celui qu\'aime mon âme; je le cherchais et ne le trouvais pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Je veux me lever et parcourir la ville; dans les, rues et dans les places je chercherai celai qu\'aime mon âme. Je le cherchai, et ne le trouvai pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Je fus rencontrée par les gardes qui parcourent la ville. « Avez-vous vu celui qu\'aime mon âme? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'A peine je les avais passés, que je trouvai celui qu\'aime mon âme. Je le saisis et ne le laisse point aller, que je ne l\'aie conduit dans la maison de ma mère, et dans la chambre de celle qui me porta dans son sein. – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Je vous adjure, filles de Jérusalem, par les gazelles ou par les biches des champs; n\'éveillez pas, ne réveillez pas mon amour, plus tôt qu\'elle ne voudrait!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Qui est celle qui monte ici du désert, comme des colonnes de fumée, entourée d\'une vapeur de myrrhe et d\'encens, et de toutes les poudres odorantes des marchands?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Voici, c\'est la litière de Salomon, escortée de soixante guerriers pris parmi les guerriers d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'tous tenant l\'épée, formés au combat, ayant chacun son épée à son flanc, en vue des alarmes nocturnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'C\'est une litière que se fit le roi Salomon, de bois du Liban.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Il en fit les colonnes d\'argent, et le dossier, d\'or, le siège, de pourpre; le fond est un parquet, œuvre d\'amour des filles de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Sortez et voyez, filles de Sion, le roi Salomon portant la couronne dont sa mère le couronna, au jour de ses fiançailles et au jour de la joie de son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Voici tu es belle, ma bien-aimée, voici, tu es belle; tes yeux sont ceux de la Colombe derrière ton voile; la chevelure est comme un troupeau des chèvres qui reposent au penchant du mont de Galaad;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'tes dents sont comme un troupeau de brebis après la tonte, qui remontent du bain, toutes mères de jumeaux, et dont aucune n\'est sans agneaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'tes lèvres sont comme un fil de carmin, ton parler est gracieux; tes joues sont comme des moitiés de grenade, derrière ton voile;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'ton col est comme la tour de David, bâtie pour recevoir les armures; mille boucliers y sont suspendus, tous pavois des héros;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'tes deux mamelles sont comme les deux faons jumeaux d\'une biche, broutant au milieu des lys.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'En attendant le frais du jour, et la fuite des ombres, j\'irai à la montagne de la myrrhe, et au coteau de l\'encens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Tu es d\'une beauté parfaite, ma bien-aimée, et en toi il n\'y a pas un défaut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Avec moi quitte le Liban, ma fiancée! avec moi quitte le Liban! regarde loin de la cime d\'Amana, de la cime de Sénir et d\'Hermon, des repaires des lions, des montagnes des léopards!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Tu m\'ôtes le cœur, ma sœur, ma fiancée, tu m\'ôtes le cœur par un seul regard de tes yeux, par un seul des colliers de ton col.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Quel charme dans ton amour, ma sœur, ma fiancée! Comme ton amour est plus exquis que le vin, et le parfum de tes huiles de senteur, plus exquis que tous les baumes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Tes lèvres distillent du miel, ô ma fiancée; ta langue repose sur le miel et le lait, et le parfum de tes habits égale le parfum du Liban.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Tu es un jardin fermé, ma sœur, ma fiancée, une source fermée, une fontaine scellée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Tes plants sont un bocage de grenadiers, avec des fruits exquis, des troènes unis au nard;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'de nard et de safran, de roseau odorant et de cannelle, avec tous les arbres qui donnent l\'encens; de myrrhe et d\'aloès, avec les premiers des aromates;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'c\'est une source pour des jardins, une fontaine d\'eaux vives, et des ruisseaux qui viennent du Liban. – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Lève-toi, Aquilon, et accours, Autan, souffle dans mon jardin, et que les parfums s\'en exhalent. Que mon bien-aimé pénètre dans son jardin, et en goûte les fruits délicieux. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Je viens dans mon jardin, ma sœur, ma fiancée! Je cueille ma myrrhe avec mon baume; je mange mon miel avec le jus de mes raisins; je bois mon vin avec mon lait. « Mangez, compagnons, buvez et vous enivrez d\'amour! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'J\'étais endormie, mais mon cœur veillait. C\'est la voix de mon bien-aimé! il heurte! « Ouvre-moi, ma sœur, ma bien-aimée; ma colombe, ma pure! Car ma tête est pleine de rosée, et mes tresses, de la bruine de la nuit... »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'J\'ai ôté ma tunique, comment la remettrais-je? j\'ai baigné mes pieds, comment les souillerais-je?...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Mon bien-aimé avança sa main par le soupirail, et mon cœur battit pour lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Je me levai pour ouvrir à mon bien-aimé, et mes mains furent trempées de myrrhe, et mes doigts, d\'une myrrhe onctueuse, en se posant sur les poignées du verrou.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'J\'ouvris à mon bien-aimé; mais mon bien-aimé était parti, disparu. J\'étais hors de moi, quand il me parlait... Je le cherchai, mais ne le trouvai point; je l\'appelai, mais il ne répondit pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Je fus trouvée par les gardes qui parcourent la ville; ils me frappèrent et me meurtrirent; ils m\'ôtèrent mon voile les gardes des murs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Je vous adjure, filles de Jérusalem; si vous trouvez mon bien-aimé..., que pensez-vous à lui dire?... Que je suis malade d\'amour. – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Qu\'a ton bien-aimé de plus qu\'un autre bien-aimé, ô la plus belle des femmes? Qu\'a ton bien-aimé de plus qu\'un autre bien-aimé, pour nous adjurer ainsi? – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Mon bien-aimé est blanc et vermeil, remarquable parmi des milliers;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'sa tête est un or pur, ses tresses sont les rameaux flottants du palmier, noires comme l\'aile du corbeau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'ses yeux, comme ceux des colombes près des ruisseaux, baignés dans le lait, comme enchâssés à leur place,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'ses joues, comme un parterre de baume, une couche de parfums, ses lèvres, des lys qui distillent une myrrhe onctueuse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'ses mains forment des anneaux d\'or garnis de chrysolithe; son corps est un travail d\'ivoire couvert de saphirs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'ses jambes, des colonnes de marbre, posant sur des bases d\'or; son aspect est pareil à celui du Liban, aussi distingué que celui des cèdres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'son palais est la douceur même, et toute sa personne est agréable: tel est mon bien-aimé, tel est mon ami, filles de Jérusalem. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Où est allé ton bien-aimé, ô la plus belle des femmes? où ton ami s\'est-il dirigé? Nous voulons le chercher avec toi. – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Mon bien-aimé est descendu dans son jardin, près des parterres de baume, pour se repaître dans les jardins, et cueillir les lys.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Je suis à mon bien-aimé, et mon bien-aimé est à moi; il se repaît au milieu des lys.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Ma bien-aimée, tu es belle comme Thirza, attrayante comme Jérusalem, mais redoutable comme des phalanges sous le drapeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Détourne de moi tes yeux, car ils me donnent l\'effroi. Ta chevelure est comme un troupeau des chèvres qui reposent sur les flancs de Galaad;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'tes dents, comme un troupeau de brebis qui reviennent du bain, toutes mères de jumeaux. et dont aucune n\'est sans agneaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'telle une moitié de grenade. telles sont les joues derrière ton voile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Il y a soixante reines, quatre-vingts concubines, et des filles sans nombre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'mais une seule est ma colombe, ma pure; elle est l\'enfant unique de sa mère, la favorite de celle qui lui donna naissance. Les filles la voient, et la disent heureuse, les reines et les concubines, et la louent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Qui est celle qui surgit comme l\'aurore, belle comme la lune, pure comme le soleil, mais redoutable comme les phalanges sous le drapeau? – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Je suis descendue au jardin des noyers, pour voir la fraîche verdure de la vallée, pour voir si la vigne montre ses bourgeons, si la grenade fleurit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Je ne sais, mais mon désir m\'a donné la vitesse des chars de mon noble peuple. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'Dès le matin nous irons aux vignes, nous observerons si la vigne pousse, épanouit ses boutons, si les grenadiers sont en fleur. Là je te ferai le don de mon amour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Reviens! reviens! Sulamithe; reviens! reviens! afin que nous te voyions! – – Pourquoi regardez-vous la Sulamithe comme une danse de deux chœurs? – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Que tes pieds sont beaux dans ta chaussure, fille de prince! Les contours de ta hanche sont comme des colliers ouvragés par les mains de l\'artiste;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'ta taille est une coupe arrondie où ne manque jamais le vin parfumé; ton sein, un tas de froment enclos dans des lys,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'tes deux mamelles, comme les deux faons jumeaux d\'une biche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'ton col, comme une tour d\'ivoire, tes yeux, comme les étangs d\'Hesbon à la porte de Beth-Rabbim, ton nez, comme la tour du Liban qui regarde Damas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'ta tête élevée est pareille au Carmel, et tes cheveux, à la pourpre royale, dans les réseaux qui les retiennent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Que tu es belle et que tu es attrayante, ô mon amour, avec tes charmes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Par ce port qui est le tien, tu ressembles au palmier, et ta gorge présente deux grappes du dattier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Je dis: Je veux m\'élancer à la cime du palmier, et saisir ses rameaux! Que ton sein soit comme les grappes de la vigne, et le parfum de ton haleine, comme la pomme [de Cydon],');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'et ta bouche, comme un vin excellent – – qui coule facilement pour mon bien-aimé, glisse sur les lèvres de ceux qui s\'endorment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Je suis à mon bien-aimé, et l\'objet de ses désirs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Viens, mon bien-aimé, allons aux champs, demeurons au village!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Dès le matin nous irons aux vignes, nous observerons si la vigne pousse, épanouit ses boutons, si les grenadiers sont en fleur. Là je te ferai le don de mon amour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'O! que n\'es-tu pour moi, comme un frère allaité à la mamelle de ma mère? Te rencontrant dehors je pourrais l\'embrasser, sans encourir le mépris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Je veux te conduire, l\'amener à la maison de ma mère; tu m\'instruiras: je te donnerai pour breuvage le vin parfumé, le moût de mes grenades.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Que sa main gauche se pose sous ma tête, et que sa droite m\'embrasse! – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Je vous adjure, filles ne Jérusalem, n\'éveillez pas, ne réveillez pas mon amour, plus tôt qu\'elle ne voudrait!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Qui est celle qui monte ici du désert, appuyée sur son bien-aimé? – – C\'est sous le pommier que j\'éveillai ton amour; c\'est là que ta mère te donna naissance, là que te donna naissance celle qui t\'enfanta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Tiens-moi comme un sceau sur ton cœur, comme un sceau sur ta main! Car l\'amour est fort comme la mort, et la jalousie inflexible comme les Enfers; ses ardeurs sont des ardeurs de feu, une flamme de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'De grandes eaux ne sauraient éteindre l\'amour, ni les torrents, le submerger. Quand un homme offrirait tous les trésors de sa maison en échange de l\'amour, on le repousserait avec dédain. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Nous avons une petite sœur, qui n\'a pas encore ses mamelles; que ferons-nous de noire sœur, lorsqu\'il sera question d\'elle?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Si elle est un mur, nous bâtirons sur elle un château d\'argent. Si elle est une porte, nous la garantirons avec des battants de cèdre. – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Je serai un mur, et mes mamelles comme des tours, alors je serai à ses yeux comme celle qui trouve paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Salomon avait une vigne à Baal-Hamon; il remit la vigne à des tenanciers; ils payaient chacun mille sicles pour sa récolte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Je surveille moi-même ma vigne. Que les mille sicles te restent, Salomon, et les deux cents à ceux qui serrent sa récolte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Habitante des jardins! des amis écoutent ta voix; fais-la moi entendre! – –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Fuis, mon bien-aimé, à l\'égal de la gazelle ou du faon de la biche, par dessus les monts des aromates!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Révélation d\'Ésaïe, fils d\'Amots, qui lui fut révélée touchant Juda et Jérusalem, dans le temps d\'Hosias, de Jotham, d\'Achaz, d\'Ézéchias, roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Cieux, écoutez! Terre, prête l\'oreille! car l\'Éternel parle. J\'ai nourri et élevé des enfants, mais ils se sont rebellés contre moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Le bœuf connaît son possesseur, et l\'âne la crèche de son maître:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Israël ne le connaît pas, mon peuple ne le distingue pas. Malheur à la nation pécheresse, à la nation chargée d\'iniquité, à la race méchante, aux enfants dénaturés! Ils ont abandonné l\'Éternel, méprisé le Saint d\'Israël, se sont retirés en arrière!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Où vous frapper encore, si vous ajoutez à vos rébellions?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'La tête entière est malade, et le cœur entier dans le dépérissement. De la plante des pieds jusqu\'à la tête rien n\'y est sain; c\'est blessure, et contusion, et plaie vive, qui ne sont ni pansées, ni bandées, ni adoucies avec l\'huile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Votre pays est désolé, vos villes brûlées au feu, et vos champs, sous vos yeux des étrangers les dévorent; c\'est une dévastation, comme quand des étrangers saccagent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Et la fille de Sion reste comme une hutte dans une vigne, comme une guérite dans un champ de concombres, comme une ville épargnée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Si l\'Éternel des armées ne nous eût laissé un faible reste, nous étions pareils à Sodome, assimilés à Gomorrhe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Entendez la parole de l\'Éternel, princes de Sodome! Écoutez la loi de notre Dieu, peuple de Gomorrhe!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Que me fait le nombre de vos sacrifices? dit l\'Éternel: j\'ai à satiété des holocaustes de béliers et de la graisse des veaux gras; et au sang des taureaux et des agneaux et des boucs je ne prends point de plaisir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Quand vous venez vous présenter devant moi, qui vous demande de fouler mes parvis?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'N\'offrez plus d\'oblations menteuses! J\'ai en horreur l\'encens, les nouvelles lunes et les sabbats, la convocation de l\'assemblée; je ne souffre pas le crime et les fêtes solennelles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Vos nouvelles lunes et vos fêtes, mon âme les a en aversion; elles me sont à charge, je suis las de les supporter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Et quand vous tendez vos mains, je me cache les yeux devant vous; même quand vous multipliez vos prières, je n\'écoute pas: vos mains sont pleines de sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Lavez-vous, purifiez-vous, ôtez de devant mes yeux la malice de vos actions, cessez de mal faire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'apprenez à bien faire, recherchez la droiture, redressez l\'iniquité, faites droit à l\'orphelin, défendez la veuve!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Venez et plaidons, dit l\'Éternel. Si vos péchés sont comme le vermillon, ils deviendront blancs comme la neige; s\'ils sont rouges comme la pourpre, ils deviendront tels que la laine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Si vous avez la volonté et l\'obéissance, vous vous nourrirez des biens du pays;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'mais si vous êtes rénitents et rebelles, de l\'épée vous serez la proie, car la bouche de l\'Éternel a parlé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Comment la cité fidèle s\'est-elle changée en prostituée? Elle était remplie d\'équité, la justice y habitait, et maintenant des meurtriers!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Ton argent s\'est changé en scories, ton vin a été coupé d\'eau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'tes princes sont des rebelles et les compagnons des voleurs; tous ils aiment les dons corrupteurs et recherchent les présents; ils ne font pas droit à l\'orphelin, et la cause de la veuve ne vient pas jusqu\'à eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Aussi, tel est l\'arrêt du Seigneur, de l\'Éternel des armées, du Fort d\'Israël: Oui, je prendrai satisfaction de mes ennemis et me vengerai de mes adversaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Et je porterai la main sur toi, et comme avec la potasse je fondrai tes scories, et ôterai tout le plomb qui est en toi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'et je te rendrai des juges tels que dans l\'origine, et des conseillers tels qu\'au commencement. Alors tu seras appelée Ville de la justice, Cité fidèle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Sion sera sauvée par la droiture, et ses [habitants] convertis par la justice;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'mais ruine sur les rebelles et les pécheurs à la fois! et ceux qui abandonnent l\'Éternel périront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Car ils seront confus à cause des térébinthes que vous aimez, et vous rougirez à cause des jardins que vous chérissez;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'car vous serez comme un térébinthe dont le feuillage est flétri, et comme un jardin privé d\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'Et l\'homme fort sera l\'étoupe, et son œuvre l\'étincelle, et ils brûleront l\'un et l\'autre ensemble, et personne qui éteigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'La parole qui fut révélée à Ésaïe, fils d\'Amots, sur Juda et Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Et il arrivera, dans la suite des temps, que la montagne de la maison de l\'Éternel aura ses fondements sur le sommet des montagnes, et s\'élèvera au-dessus des éminences, et que tous les peuples y afflueront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Et des nations nombreuses s\'achemineront en disant: « Venez, et montons à la montagne de l\'Éternel, à la maison du Dieu de Jacob, et Il nous enseignera ses voies, et nous suivrons ses sentiers! » Car la Loi sortira de Sion, et la parole de l\'Éternel de Jérusalem;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'et Il sera le juge des peuples et l\'arbitre de nations nombreuses: et ils forgeront leurs épées en hoyaux, et leurs lances en serpes; un peuple contre un peuple ne lèvera plus l\'épée, et ils n\'apprendront plus la guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Maison de Jacob, venez, et marchons à la lumière de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Car, [ô Éternel], tu as abandonné ton peuple, la maison de Jacob, parce qu\'ils sont pleins de l\'Orient, et divinateurs comme les Philistins, et qu\'ils donnent la main aux enfants de l\'étranger:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'et son pays est plein d\'argent et d\'or, et ses trésors sont infinis; et son pays est plein de chevaux, et ses chars sont innombrables;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'et son pays est plein d\'idoles; ils se prosternent devant l\'œuvre de leurs mains, devant ce qu\'ont façonné leurs doigts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Mais l\'homme sera abaissé et le personnage humilié, et tu ne saurais leur pardonner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Fuis dans les rochers et te cache dans la poussière, devant les terreurs de l\'Éternel et devant l\'éclat de sa majesté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Le fier regard de l\'homme sera humilié, et l\'orgueil du personnage abaissé, et l\'Éternel en ce jour sera seul élevé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Car il est une journée de par l\'Éternel des armées, contre tout ce qui est altier et élevé, et contre tout ce qui s\'élève, afin qu\'il soit humilié;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'et contre tous les cèdres du Liban hauts et élevés, et contre tous les chênes de Basan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'et contre toutes les montagnes élevées, et contre toutes les collines éminentes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'et contre toutes les hautes tours, et contre toutes les fortes murailles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'et contre tous les navires de Tarsis, et contre tout ce qui est d\'un bel aspect.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Et la fierté des hommes sera humiliée, et l\'orgueil des personnages abaissé; et l\'Éternel en ce jour sera seul élevé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'et les idoles en entier disparaîtront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'On s\'enfoncera dans les cavernes des rochers et dans les grottes de la terre, devant les terreurs de l\'Éternel et devant l\'éclat de sa majesté, quand Il se lèvera pour terrifier la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'En ce jour les hommes jetteront leurs idoles d\'argent et leurs idoles d\'or, qu\'ils s\'étaient faites pour les adorer, aux rats et aux chauves-souris,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'pour s\'enfoncer dans les fentes des rochers et dans les gorges des montagnes, devant les terreurs de l\'Éternel et devant l\'éclat de sa majesté, quand Il se lèvera pour terrifier la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Cessez donc de compter sur l\'homme, dans les narines duquel il n\'y a qu\'un souffle; car quel cas faire de lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Car voici, le Seigneur, l\'Éternel des armées, va ôter de Jérusalem et de Juda tout appui et toute ressource, toute ressource de pain et toute ressource d\'eau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'le héros et le guerrier, le juge et le prophète, et le divinateur et l\'Ancien,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'le chef de cinquante, le notable et le conseiller, et l\'artiste expert et l\'habile enchanteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Et je leur donnerai des adolescents pour chefs et des enfants régneront sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Et le peuple devient oppresseur, l\'homme envers un autre homme, et chacun envers son prochain; il y a insurrection de l\'enfant contre le vieillard, et des petits contre les grands.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Car l\'un saisit son frère dans la maison paternelle: « Tu as des vêtements, viens! sois notre Prince! prends en mains cet état en ruine! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'En ce jour-là celui-ci répondra et dira: « Je ne saurais être le médecin, et dans ma maison il n\'y a ni pain, ni vêtements; ne m\'établissez pas prince du peuple! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Car Jérusalem chancelle et Juda tombe, parce que leurs paroles et leurs œuvres sont contre l\'Éternel, pour braver les regards de sa majesté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'L\'air de leur visage témoigne contre eux, et comme Sodome ils publient leur péché, ne le dissimulent pas. Malheur à leur âme! car ils se préparent des maux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Dites que le juste est heureux, car il goûte les fruits de ses œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Malheur à l\'impie! le malheureux! car ce qu\'il a fait lui sera rendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Des enfants sont les oppresseurs de mon peuple, et des femmes le gouvernent. Mon peuple! tes guides t\'égarent, et ruinent le chemin que tu devrais suivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'L\'Éternel est levé pour faire le procès, et Il est debout pour juger les tribus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'L\'Éternel paraît en jugement avec les anciens de son peuple et ses chefs: « C\'est vous qui avez brouté la vigne! la dépouille du pauvre est dans vos maisons!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Que faites-vous de fouler mon peuple et de meurtrir le visage des misérables? » dit le Seigneur, l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Et l\'Éternel dit: Parce que les filles de Sion sont fières et vont le cou renversé, et lançant des regards, qu\'elles marchent à petits pas et font résonner les boucles de leurs pieds,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'le Seigneur pèlera le crâne des filles de Sion, et l\'Éternel découvrira leur nudité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'En ce jour le Seigneur enlèvera les boucles, parure de leurs pieds, et les filets et les lunules;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'les pendants d\'oreilles et les bracelets et les voiles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'les bandeaux et les chaînettes de pieds, et les ceintures et les flacons de senteur, et les amulettes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'les bagues et les boucles de narines;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'les habits magnifiques et les larges tuniques, et les manteaux et les gibecières;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'les miroirs et les chemises, et les turbans et les crêpes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Et au lieu de parfum, il y aura infection; et au lieu de ceinture, une corde; et au lieu de cheveux bouclés, une tête chauve; et au lieu de la mante, un cilice pour se ceindre; la marque, au lieu de la beauté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Tes hommes périront par l\'épée, et tes héros dans le combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Et ses portes seront gémissantes et dans le deuil, et désolée elle s\'assiéra sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Et sept femmes viendront en ce jour saisir un même homme, et lui diront: « Nous voulons manger notre pain et nous vêtir de nos habits; seulement, que nous portions ton nom! fais cesser notre opprobre! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'En ce jour-là, le Germe de l\'Éternel sera l\'ornement et la gloire, et le fruit de la terre sera l\'orgueil et la parure des restes échappés d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Et quiconque sera laissé en Sion et survivra dans Jérusalem, portera le nom de Saint, quiconque sera inscrit au livre des vivants en Jérusalem;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'quand le Seigneur aura lavé les ordures des filles de Sion, et fait disparaître le sang de Jérusalem de son sein, par l\'Esprit de jugement et par l\'Esprit d\'extermination.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Et sur toute l\'étendue de la montagne de Sion, et sur ses lieux d\'assemblées, l\'Éternel établira pendant le jour un nuage et une fumée, et de nuit l\'éclat d\'un feu allumé; car toute magnificence est mise à couvert;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'et il y aura un abri pour donner de l\'ombrage pendant le jour contre la chaleur, et pour être un refuge et une retraite contre l\'orage et la pluie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Je veux chanter pour mon ami le chant de mon ami sur sa vigne. Mon ami avait une vigne sur un coteau fertile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Et il la défonça, et en ôta les pierres, et y mit un plant généreux, et bâtit une tour au milieu d\'elle, et y creusa aussi un pressoir; et il espérait qu\'elle donnerait de bons raisins, mais elle a donné des fruits sauvages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Et maintenant, habitants de Jérusalem et hommes de Juda, soyez juges entre moi et ma vigne!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Qu\'y avait-il encore à faire pour ma vigne, que je n\'aie fait pour elle? D\'où vient, quand j\'en espérais de bons raisins, qu\'elle a produit des fruits sauvages? –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Et maintenant, je vous annonce ce que je vais faire à ma vigne: enlever sa clôture, pour qu\'elle soit broutée; abattre son mur, pour qu\'elle soit foulée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'et je la ruinerai, et elle ne sera ni taillée, ni sarclée, pour qu\'elle monte en ronces et en épines, et aux nuages je défendrai d\'y laisser descendre la pluie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Mais la vigne de l\'Éternel des armées, c\'est la maison d\'Israël; et les hommes de Juda, son plant favori; Il en attendait des mœurs justes, et voici, il y a des meurtres; de l\'innocence, et voici, l\'on y crie vengeance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Malheur à ceux qui ajoutent maison à maison, joignent champ à champ, jusqu\'à ne plus laisser de terrain, et à être seuls établis dans le pays!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'A mes oreilles l\'Éternel des armées le dit: Oui, leurs maisons nombreuses seront dévastées, et ces grandes et belles maisons, vides d\'habitants!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Car dix arpents de vignes rendront un bath, et un homer de semences rendra un épha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Malheur à ceux qui, debout dès le matin, courent après la cervoise, et veillent bien avant dans la nuit, échauffés par le vin!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Et le luth, et la harpe, la cymbale et la flûte, et le vin entrent dans leurs festins; mais à l\'œuvre de l\'Éternel ils n\'ont point égard, et ne considèrent point l\'ouvrage de ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Aussi mon peuple marche à la captivité sans s\'en douter; et sa noblesse va sentir la faim, et sa multitude brûler de soif.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Aussi l\'Enfer ouvre une bouche avide et une gueule béante sans mesure; et leur magnificence, et leur pompe, et leur tumulte, et toutes leurs joies y tombent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Alors l\'homme sera abaissé et le personnage humilié, et les regards des superbes abaissés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'et l\'Éternel des armées sera élevé par ses jugements, et le Dieu saint sanctifié par sa justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Alors des brebis paîtront comme dans leur pâturage, et des étrangers dévoreront les champs désolés des riches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Malheur à ceux qui tirent à eux le crime avec les cordes du vice, et le péché comme avec les traits d\'un chariot!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'qui disent: « Qu\'il hâte, qu\'il accélère son œuvre, afin que nous voyions! qu\'il arrive, qu\'il s\'exécute le décret du Saint d\'Israël, pour que nous sachions! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Malheur à ceux qui appellent le mal bien et le bien mal, qui changent l\'obscurité en lumière et la lumière en obscurité, qui changent l\'amertume en douceur et la douceur en amertume!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Malheur à ceux qui sont sages à leurs yeux, et qui se croient sensés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Malheur aux héroïques buveurs de vin, et aux hommes braves pour mêler la cervoise,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'qui pour un présent renvoient l\'impie absous, et frustrent le juste de son droit!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Aussi, comme la langue du feu dévore le chaume, et comme l\'herbe sèche s\'affaisse dans les flammes, de même leur racine sera comme une vermoulure, et leur fleur s\'élèvera comme une poussière; car ils méprisent la loi de l\'Éternel des armées, et dédaignent la parole du Saint d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Aussi la colère de l\'Éternel s\'allume contre son peuple, et Il étend sa main contre lui et les frappe; et les montagnes en tremblent, et leurs cadavres comme le fumier jonchent les rues. Cependant sa colère ne se ralentit pas, et sa main est toujours étendue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Et Il dresse un étendard pour appeler les peuples lointains, et Il en siffle un des bouts de la terre; et voici, prompt et rapide, il arrive;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'personne n\'y est las, personne n\'y chancelle; il ne dort ni ne sommeille, et la ceinture de ses reins ne se détache point, et les courroies de sa chaussure ne se rompent point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Ses traits sont acérés et tous ses arcs bandés; le sabot de ses chevaux est comparable au caillou, et ses roues à l\'ouragan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Son rugissement est celui de la lionne; il rugit comme les jeunes lions, il gronde et saisit sa proie et l\'emporte, et personne ne la sauve;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'et en ce jour contre lui il grondera comme gronde la mer. Et si on regarde la terre, voici, ce sont des ténèbres, angoisse et lumière, puis ténèbres dans son ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'L\'année de la mort du roi Hosias, je vis le Seigneur assis sur un trône éminent et élevé, et les pans de son manteau remplissaient le temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Des Séraphins debout l\'entouraient; ils avaient chacun d\'eux six ailes: de deux ils se couvraient le visage, et de deux ils se couvraient les pieds, et de deux ils volaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Et ils s\'entre-répondaient disant: Saint, saint, saint est l\'Éternel des armées! toute la terre est pleine de sa magnificence!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Et les bases des seuils s\'ébranlaient à la voix de ce chœur, et la maison se remplit de fumée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Alors je dis: Malheur à moi! je vais périr! car je suis un homme aux lèvres souillées, et j\'habite au milieu d\'un peuple aux lèvres souillées, et mes yeux ont vu le Roi, l\'Éternel des armées!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Mais l\'un des Séraphins vola jusqu\'à moi, ayant dans sa main une pierre brûlante qu\'avec une pince il avait prise sur l\'autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Et il en toucha ma bouche et dit: Voici, ceci a touché tes lèvres, et ton crime est enlevé, et ton péché expié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Et j\'entendis la voix du Seigneur qui disait: Qui enverrai-je, et qui ira pour nous? Alors je dis: Me voici! envoie-moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Et Il dit: Va, et dis à ce peuple: Écoutez, écoutez! mais vous n\'entendrez pas! regardez! regardez! mais vous ne comprendrez pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Appesantis le cœur de ce peuple, et rends ses oreilles dures, et ses yeux aveugles! de peur qu\'il ne voie de ses yeux et n\'entende de ses oreilles, et que son cœur ne comprenne, et qu\'il ne se convertisse et ne soit guéri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Alors je dis: Jusques à quand?... Seigneur! Et il dit: Jusqu\'à ce que s\'écroulent leurs villes privées d\'habitants, et leurs maisons privées d\'hommes, et que leur pays soit désolé et désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'Car l\'Éternel éloignera les hommes, et grande sera la solitude dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Que s\'il y reste encore la dixième partie, une seconde ruine l\'atteindra. Mais tel un térébinthe ou un chêne auquel, après la coupe, il reste un rejeton, ainsi [il lui restera] une sainte race pour rejeton.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Et il arriva au temps d\'Achaz, fils de Jotham, fils d\'Hosias, roi de Juda, que Retsin, roi de Syrie, et Pékach, fils de Remalia, roi d\'Israël, se mirent en campagne contre Jérusalem pour l\'attaquer; mais ils ne purent l\'attaquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Et l\'on donna cet avis à la maison de David, en ces mots: Le Syrien est campé en Éphraïm. – Alors son cœur et le cœur de son peuple trembla, comme tremblent les arbres de la forêt au souffle du vent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Alors l\'Éternel dit à Ésaïe: Va donc te présenter à Achaz, toi et Schear-jaschoub ton fils, au bout de l\'aqueduc de l\'étang supérieur, vers le sentier du champ du foulon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'et dis-lui: Sois sur tes gardes, mais sois tranquille! ne crains rien! et que ton cœur ne faiblisse pas devant ces deux bouts de tisons fumants, parce que s\'est allumée la colère de Retsin et du Syrien, et du fils de Remalia,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'et que la Syrie médite ta ruine, ainsi que Éphraïm et le fils de Remalia, disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Marchons contre Juda, et donnons-lui l\'alarme, et battons [la ville] en brèche pour y entrer, et établissons-y pour roi le fils de Tabeel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Ainsi parle le Seigneur, l\'Éternel: Cela n\'aura pas lieu et il n\'en sera rien;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'car le chef-lieu de la Syrie sera encore Damas, et le chef de Damas Retsin (et encore soixante-cinq ans, et Éphraïm sera mis en pièces et cessera d\'être un peuple);');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'et le chef-lieu d\'Éphraïm sera encore Samarie, et le chef de Samarie le fils de Remalia. Que si vous ne croyez pas, vous ne vous soutiendrez pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Et l\'Éternel parla encore à Achaz et lui dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Demande à l\'Éternel ton Dieu qu\'un signe te soit donné; demande qu\'il paraisse dans les lieux bas, ou en haut dans les lieux élevés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Et Achaz dit: Je ne veux ni demander, ni tenter l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Alors il dit: Eh bien! écoutez, maison de David! Est-ce trop peu pour vous de lasser les hommes, que vous lassez aussi mon Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'C\'est pourquoi l\'Éternel lui-même vous donnera un signe: Voici, la vierge concevra, et elle enfantera un fils, et l\'appellera Immanuel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Il mangera du lait et du miel, jusqu\'à ce qu\'il sache rejeter le mal et choisir le bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Car avant que l\'enfant sache rejeter le mal et choisir le bien, le pays dont les deux rois t\'alarment, sera désolé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'L\'Éternel amènera pour toi et pour ton peuple, et pour la maison de ton père, des jours tels qu\'il n\'en est point venu depuis le jour où Éphraïm s\'est détaché de Juda, (le roi d\'Assyrie).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Et en ce jour-là l\'Éternel fera arriver les mouches qui sont à l\'extrémité des fleuves de l\'Egypte, et les abeilles qui sont dans le pays d\'Assur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'et elles viendront, et se poseront toutes dans les vallées escarpées, et dans les fentes des rochers, et dans tous les buissons, et dans tous les pâturages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'En ce jour-là, le Seigneur rasera avec un rasoir loué au-delà du fleuve (le roi d\'Assyrie) la tête et le poil des jambes, et Il enlèvera aussi la barbe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'Et dans ce même temps, un homme entretiendra une petite vache et deux brebis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'et obtenant beaucoup de lait il en mangera la crème, car c\'est de la crème et du miel que mangeront tous ceux qui seront laissés de reste dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Et en ce même temps, tout lieu qui contiendra mille ceps de mille sicles d\'argent, deviendra épines et ronces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Avec la flèche et l\'arc on y viendra; car tout le pays sera épines et ronces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Et sur toutes les montagnes que l\'on bêchait avec la bêche, tu n\'iras plus, par crainte des épines et des ronces: et ce sera un pâturage pour le bétail et un sol foulé par les moutons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Et l\'Éternel me dit: Trouve-toi une grande table et y écris en caractères vulgaires: « Pillage prompt, proie subite. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Je dus aussi me trouver des témoins dignes de foi, Urie le sacrificateur, et Zacharie, fils de Barachie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Et je m\'approchai de la prophétesse, et elle conçut et enfanta un fils; et l\'Éternel me dit: Donne-lui pour nom Pillage-prompt-proie-subite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Car, avant que l\'enfant sache dire: Mon père et ma mère, on portera les richesses de Damas et le pillage de Samarie devant le roi d\'Assyrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Et l\'Éternel me parla encore et me dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Parce que ce peuple dédaigne les eaux de Siloë dont le courant est doux, et se réjouit à la vue de Retsin et du fils de Remalia,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'pour cela, voici, le Seigneur fera avancer contre vous les puissantes et grandes eaux du fleuve (le roi d\'Assyrie et toute sa magnificence), et il s\'élèvera au-dessus de son lit, et passera par-dessus toutes ses rives,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'et il pénétrera en Juda, il débordera et inondera, à hauteur d\'homme il atteindra, et le déploiement de ses ailes remplira dans toute son étendue ton pays, ô Immanuel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Peuples, grondez! mais soyez effrayés! entendez-le, vous tous, habitants des terres reculées, équipez-vous! mais soyez effrayés! équipez-vous! mais soyez effrayés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Formez un plan! et il sera déjoué; annoncez un projet! et il sera sans effet, car Dieu est avec nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Car ainsi me parla l\'Éternel, quand sa main me saisit, et qu\'il m\'avertit de ne pas m\'engager dans la voie de ce peuple, en me disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'N\'appelez pas ligue tout ce que ce peuple appelle ligue, et ne craignez pas ce qu\'il craint, et ne répandez pas l\'effroi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'L\'Éternel des armées, lui, honorez-le comme Saint! qu\'il soit l\'objet de votre crainte, et soit celui de votre frayeur:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'et Il sera un sanctuaire, et une pierre de scandale, et une roche d\'achoppement pour les deux maisons d\'Israël, un lacs et un piège pour les habitants de Jérusalem;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'et plusieurs y trébucheront et tomberont, et seront écrasés, et enlacés et pris. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Plie la déclaration, scelle la révélation avec l\'aide de mes disciples!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Et je compte sur l\'Éternel, qui cache sa face à la maison de Jacob, et j\'espère en lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Voici, moi et les enfants que m\'a donnés l\'Éternel, nous sommes des signes et des figures en Israël de par l\'Éternel des armées, qui réside sur la montagne de Sion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Et si l\'on vous dit: Consultez les évocateurs et les devins qui marmottent et murmurent! [dites:] Un peuple ne consulterait-il pas son Dieu? en faveur des vivants [s\'adressera-t-il] aux morts?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, '« A la loi et au témoignage! » S\'ils ne tiennent pas ce langage, pour eux il n\'y aura pas d\'aurore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Et ils erreront dans le pays, accablés et affamés; et ayant faim ils s\'irriteront et maudiront leur Roi et leur Dieu; et ils tourneront leurs yeux en haut');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'et ils regarderont sur la terre, et voici, c\'est détresse et obscurité, ténèbres angoissantes; et dans la nuit ils sont refoulés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Mais il ne fera pas [toujours] sombre là où il y a [maintenant] angoisse. Si les premiers temps ont couvert d\'opprobre le pays de Zabulon et le pays de Nephthali, les temps qui suivront couvriront de gloire la côte de la mer, au-delà du Jourdain, la contrée des Gentils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Le peuple qui marche dans les ténèbres, voit une grande lumière: sur ceux qui sont assis au pays de l\'ombre de mort, resplendit une lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Tu rends le peuple nombreux, tu augmentes sa joie; ils se réjouissent devant toi, comme on se réjouit à la moisson, comme on s\'égaie au partage du butin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Car le joug qui lui pèse, la verge qui bat son épaule, et le bâton de son oppresseur, tu le brises comme à la journée de Madian.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Car toute chaussure qu\'on chausse dans la mêlée, et tout habit de guerre roulé dans le sang, seront brûlés, seront la proie des flammes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Car un enfant nous est né, un Fils nous est donné, et l\'empire repose sur son épaule, et on lui donne pour nom Merveille, Conseiller, Dieu Fort, Père éternel, Prince de paix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'pour l\'accroissement de l\'empire, et pour une paix sans fin sur le trône de David et sur son royaume, afin de l\'affermir et de le soutenir par le droit et la justice, dès maintenant à l\'éternité. C\'est ce qu\'opérera le zèle de l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Le Seigneur dirige contre Jacob une parole, qui va frapper Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'et elle se fera sentir à tout le peuple, à Éphraïm et aux habitants de Samarie qui, dans l\'orgueil et la fierté du cœur, disent:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, '« Des briques se sont écroulées, et en pierres de taille nous rebâtirons; des sycomores ont été coupés, et par des cèdres nous les remplacerons. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Car l\'Éternel rendra les ennemis de Retsin supérieurs à eux, et Il armera leurs ennemis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'les Syriens par devant et les Philistins par derrière, pour qu\'ils mangent Israël à pleine bouche. Malgré tout cela, sa colère ne cesse point, et sa droite est encore étendue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Mais le peuple ne revient pas à Celui qui le frappe, et de l\'Éternel des armées ils ne s\'enquièrent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Aussi l\'Éternel arrachera d\'Israël la tête et la queue, le rameau de palmier et le jonc, en un même jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, '(L\'ancien et le noble, c\'est la tête; et le prophète docteur de mensonge, c\'est la queue.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Car les guides de ce peuple l\'égarent, et ceux qui se laissent guider se perdent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'C\'est pourquoi le Seigneur n\'aura point de joie à voir ses jeunes hommes, et de ses orphelins et de ses veuves; Il n\'aura point de pitié, car tous ils sont sacrilèges et méchants, et toutes les bouches parlent follement. Malgré tout cela, sa colère ne cesse point, et sa main est encore étendue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Car la méchanceté brûle comme un feu qui dévore les ronces et les épines, et embrase le fort de la forêt, et s\'élève en colonnes de fumée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Par la colère de l\'Éternel des armées le pays est incendié, et le peuple devient la proie des flammes; nul n\'épargne son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'On dévore à droite, et l\'on est affamé; on mange à gauche, et l\'on n\'est pas rassasié: chacun mange la chair de ses proches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Manassé [dévore] Éphraïm, et Éphraïm Manassé, et les deux ensemble fondent sur Juda. Malgré tout cela, sa colère ne cesse pas, et sa main est toujours étendue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Malheur à ceux qui prononcent des sentences iniques, et aux écrivains qui transcrivent l\'injustice,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'pour débouter du jugement les pauvres, et ravir leur droit aux malheureux de mon peuple, pour faire des veuves leur proie, et des orphelins leur pillage!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Et que ferez-vous au jour du châtiment et du ravage qui arrive du lointain? Vers qui fuirez-vous pour trouver secours, et où laisserez-vous votre magnificence?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Celui qui ne fléchira pas sous le faix parmi les captifs, tombera parmi les morts. Malgré tout cela, sa colère ne cesse pas, et sa main est toujours étendue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Malheur à l\'Assyrien! Il est la verge et le bâton de ma colère, et mes vengeances sont entre ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Contre une nation sacrilège je l\'ai envoyé, et contre le peuple objet de mon courroux je lui ai donné mission, pour faire du pillage et enlever du butin, et pour le fouler aux pieds comme la boue des rues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Mais telle n\'est point son idée, telle n\'est point la pensée de son cœur; mais en son âme il veut détruire et exterminer les peuples en foule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Car il dit: « Mes princes ne sont-ils pas tous autant de rois?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'N\'en fut-il pas de Calno comme de Carchemis, de Hamath comme d\'Arpad, de Samarie comme de Damas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'De même que ma main a atteint les empires des idoles, dont les images étaient supérieures à celles de Jérusalem et de Samarie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'ne saurai-je pas traiter Jérusalem et ses images, comme j\'ai traité Samarie et ses idoles? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Mais, quand le Seigneur aura achevé toute son œuvre sur la montagne de Sion et à Jérusalem, je sévirai contre le fruit du cœur orgueilleux du Roi d\'Assyrie, et contre l\'arrogance de ses yeux hautains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Car il dit: « Par la force de mon bras je l\'ai fait, et par ma sagesse, car je suis intelligent; j\'ai déplacé les bornes des peuples, et pillé leurs trésors, et comme un héros j\'en ai précipité de leurs trônes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'et ma main s\'empara des biens des peuples, comme d\'un nid; comme on ramasse des œufs abandonnés, moi j\'ai ramassé toute la terre, et il n\'y en eut pas un qui remuât l\'aile, et ouvrît la bouche et jetât un cri! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'La cognée est-elle insolente envers le bûcheron qui se sert d\'elle, et la scie, superbe envers celui qui la manie, comme si la verge faisait mouvoir celui qui la lève, comme si le bâton soulevait le bras?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'C\'est pourquoi le Seigneur, le Seigneur des armées, parmi ses guerriers bien nourris enverra le dépérissement, et au milieu de sa magnificence s\'allumera un incendie, comme un incendie de feu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'et la Lumière d\'Israël deviendra un feu, et son Saint, une flamme qui embrasera et dévorera ses ronces et ses épines en un jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Et il détruira la magnificence de sa forêt et de ses campagnes, corps et âme, et il en sera comme d\'un malade qui dépérit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'et le reste des arbres de sa forêt pourra être compté, et un enfant en écrirait le nombre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'Et en ce jour-là, le reste d\'Israël et les survivants de la maison de Jacob cesseront de prendre pour appui leur oppresseur, et ils s\'appuieront sur l\'Éternel, le Saint d\'Israël, avec confiance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Le reste reviendra, le reste de Jacob, au Dieu tout-puissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Car ton peuple, ô Israël, fût-il comme le sable de la mer, un reste [seulement] reviendra à lui; l\'extermination est décidée, qui amènera les flots de la justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Car le Seigneur, l\'Éternel des armées, exécutera la destruction et le décret dans le sein de tout le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'C\'est pourquoi, ainsi parle le Seigneur, l\'Éternel des armées: O mon peuple, qui habites en Sion, ne crains point l\'Assyrien! De la verge il t\'a battu, et il a levé son bâton sur toi à l\'instar de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Car, encore quelque temps, et le courroux cessera, et ma colère entreprendra leur ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Alors l\'Éternel des armées brandira sur lui le fouet, comme Il battit Madian au rocher d\'Horeb, et comme de son bâton Il frappa la mer; et Il le lèvera ainsi qu\'en Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'Et en ce jour-là son fardeau sera ôté de ton épaule, et son joug de ton col; et la graisse fera sauter le joug.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Il arrive à Ajath, traverse Migron, à Michmas il laisse ses bagages;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'ils passent le défilé; Géba est l\'étape où ils couchent; Rama tremble; Gibea, ville de Saül, est en fuite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Pousse des cris aigus, fille de Gallim! prête l\'oreille du côté de Laïs, pauvre Anathoth!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmène est en fuite, et les habitants de Gébim fugitifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Encore ce jour d\'arrêt à Nob, et il agite sa main contre la montagne de la fille de Sion, la colline de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Et voici, le Seigneur, l\'Éternel des armées, abat les rameaux avec épouvante; et ceux qui s\'élèvent en hauteur sont coupés, et les superbes humiliés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'et l\'épaisseur de la forêt est frappée avec le fer, et le Liban succombe sous le Puissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Mais il sort un rameau de la souche d\'Isaï, et un rejeton naît de ses racines;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'et l\'Esprit de l\'Éternel repose sur lui, l\'esprit de sagesse et d\'intelligence, l\'esprit de conseil et de force, l\'esprit de connaissance et de crainte de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Il prend son plaisir dans la crainte de l\'Éternel, et ne juge point d\'après le regard de ses yeux, ni ne décide d\'après l\'ouïe de ses oreilles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'et il juge avec justice les petits, et il est un arbitre équitable pour les malheureux de la terre, et il frappe la terre de la verge de sa bouche, et du souffle de ses lèvres donne la mort à l\'impie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'et la justice est la ceinture de ses reins, et la fidélité la ceinture de ses flancs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Alors le loup gîtera avec l\'agneau, et la panthère se couchera près du chevreau; le veau, le lionceau et le gras bétail vivront ensemble, et un petit garçon sera leur conducteur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'et la génisse et l\'ourse brouteront ensemble, leurs petits seront couchés ensemble, et le lion comme le bœuf mangera du fourrage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'et l\'enfant qu\'on allaite se jouera près du trou de la vipère, et celui qu\'on sèvre présentera sa main au gîte du basilic.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Il n\'y aura plus ni mal ni corruption sur toute ma sainte montagne, car la connaissance de l\'Éternel remplira la terre, comme les eaux couvrent le fond de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Et dans ce même temps, le rejeton d\'Isaï sera là comme un étendard pour les peuples; les nations s\'adresseront à lui, et sa demeure est glorieuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Et dans ce même jour, le Seigneur étendra une seconde fois sa main pour racheter le reste de son peuple, qui sera échappé de l\'Assyrie et de l\'Egypte, et de Pathros et de l\'Ethiopie, et d\'Élam et de Sinear, et de Hamath et des îles de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Et Il dressera un étendard pour les peuples, et des quatre bouts de la terre Il recueillera ceux d\'Israël qui furent expulsés, et Il rassemblera ceux de Juda qui furent dispersés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Alors la jalousie d\'Éphraïm disparaîtra, et les hommes hostiles de Juda seront exterminés; Éphraïm ne sera plus jaloux de Juda, et Juda ne sera plus hostile à Ephraïm:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'et ils voleront sur l\'épaule des Philistins à l\'occident, ensemble ils pilleront les enfants de l\'orient, sur Édom et Moab ils porteront la main, et les enfants d\'Ammon leur seront assujettis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Alors l\'Éternel desséchera le bras de la mer d\'Egypte, et agitera sa main sur le Fleuve avec son souffle terrible, et le partagera en sept canaux, afin qu\'on le passe avec une chaussure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Et il y aura une chaussée pour le reste de mon peuple, qui sera échappé de l\'Assyrie, comme il y en eut une pour Israël, au jour de la sortie du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Et tu diras en ce jour-là: « Je te loue, Éternel, car tu fus irrité contre moi, et ta colère cessa, et tu pris pitié de moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Voici, Dieu m\'est en aide; j\'ai de l\'assurance et je suis sans peur; car l\'Éternel, l\'Éternel est ma force et ma louange; Il me fut en aide. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Et vous puiserez de l\'eau avec allégresse aux sources du salut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'et vous direz en ce jour-là: « Louez l\'Éternel! invoquez son nom! publiez parmi les peuples ses exploits, rappelez que son nom est souverain!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Célébrez l\'Éternel, car Il a fait des choses magnifiques; qu\'elles soient connues par toute la terre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Crie de joie et chante, habitante de Sion, car il est grand au milieu de toi, le Saint d\'Israël! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Oracle contre Babylone, qui fut révélé à Ésaïe, fils d\'Amots.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Sur une montagne nue dressez un étendard, élevez la voix pour les appeler, agitez la main pour qu\'ils envahissent les portes des tyrans!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Moi-même j\'ai donné l\'ordre à ma sainte milice, et j\'ai appelé mes héros pour exécuter mes vengeances, ceux qui tressaillent fièrement pour moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'On entend une rumeur sur les montagnes, comme celle d\'un peuple nombreux; on entend le tumulte de royaumes, de peuples rassemblés: l\'Éternel des armées fait la revue de sa milice guerrière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Ils arrivent d\'un pays lointain, de l\'extrémité des Cieux, l\'Éternel et les instruments de sa vengeance, pour dévaster toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Gémissez! car la journée de l\'Éternel est proche; comme une ruine de par le Tout-Puissant elle arrive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Aussi toutes les mains sont lâches, et le cœur de tout homme se fond.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'Ils sont dans l\'épouvante, saisis de douleurs et d\'angoisses, ils souffrent les maux de la femme en travail; stupéfaits ils se regardent l\'un l\'autre, leur visage a l\'aspect de la flamme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Voici, la journée de l\'Éternel arrive cruelle, avec la fureur et l\'ardente colère, pour faire de la terre une solitude, et Il en exterminera les pécheurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Car les étoiles du Ciel et ses astres ne font plus briller leur lumière, le soleil s\'obscurcit à son lever, et la lune ne fait plus luire sa lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Et je punirai le monde de sa méchanceté, et les impies de leurs crimes; et je mettrai fin à l\'orgueil des superbes, et j\'humilierai la hauteur des tyrans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Je rendrai les hommes plus rares que l\'or fin, et les humains que les trésors d\'Ophir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'C\'est pourquoi je ferai trembler les Cieux, et la terre sera ébranlée sur sa base, lors du courroux de l\'Éternel des armées, et au jour de son ardente colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Alors, tel qu\'une gazelle effarouchée et qu\'une brebis que nul ne recueille, chacun se dirigera vers son peuple, et chacun fuira dans son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Quiconque sera trouvé, sera percé, et quiconque sera saisi, périra par l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Et leurs enfants seront écrasés sous leurs yeux, leurs maisons seront pillées et leurs femmes violées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Voici, je fais lever contre eux les Mèdes qui ne tiennent pas compte de l\'argent, et n\'ont nul penchant pour l\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Et leurs arcs mettront les jeunes gens en pièces, pour le fruit porté dans le sein ils seront sans pitié, et pour les enfants ils ne s\'attendriront point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Et Babel, l\'ornement des empires, la pompe orgueilleuse des Chaldéens, sera comme Sodome et Gomorrhe que Dieu bouleversa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Elle ne sera plus jamais habitée, plus peuplée d\'âge en âge; l\'Arabe n\'y placera plus sa tente, ni les bergers leur parc.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Et elle sera le parc des bêtes du désert, et les hiboux rempliront ses maisons, et les autruches y prendront leur gîte, et les satyres y danseront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'Et dans leurs palais les hyènes s\'entre-répondront, et les chacals dans leurs maisons de plaisance. Et son temps est proche, et le délai ne sera pas prolongé pour elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Car l\'Éternel prend pitié de Jacob et fait de nouveau choix d\'Israël, et Il les rétablira dans leur pays. Et les étrangers se joindront à eux, et se rattacheront à la maison de Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Et les peuples les prendront et les ramèneront dans leur séjour, et la maison d\'Israël se les appropriera dans le pays de l\'Éternel, comme serviteurs et servantes, et ils feront prisonniers ceux qui les firent prisonniers, et ils domineront sur leurs oppresseurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Et quand l\'Éternel aura fait succéder pour toi le repos à ta peine, à ton tourment et à la dure servitude à laquelle tu fus asservi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'alors tu diras cette chanson sur le roi de Babel, en ces mots: « Comment a fini le tyran, a cessé l\'oppression?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'L\'Éternel a brisé le bâton des impies, la verge des dominateurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'qui frappait les peuples avec emportement de coups sans relâche, et faisait subir aux peuples avec fureur un empire sans frein.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Toute la terre est en repos et en paix; on éclate en cris d\'allégresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Les cyprès aussi, les cèdres du Liban disent, pleins de joie: Depuis que tu es gisant, personne ne monte pour nous abattre. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Dans les régions inférieures l\'Enfer s\'émeut pour t\'accueillir à ton approche, il fait avancer au-devant de toi les ombres, tous les puissants de la terre, et lever de leurs trônes tous les rois des nations;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'tous ils prennent la parole et te disent: Te voilà débile ainsi que nous, tu nous es assimilé!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Dans l\'Enfer ta pompe est descendue, avec le bruissement de tes harpes; sous toi des vers forment ta litière, et la pourriture est ta couverture. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Comme tu es précipité du ciel, astre brillant, fils de l\'aurore! comme tu es abattu par terre, toi qui écrasais les peuples!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Et toi, tu disais en ton cœur: Je veux monter aux Cieux, par delà les étoiles de Dieu élever mon trône, et siéger sur la Montagne de l\'Assemblée au fond du septentrion:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'je monterai sur les sommités des nues, j\'irai de pair avec le Très-Haut. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Mais dans les Enfers tu es précipité, au fond de la fosse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Ceux qui te voient, te contemplent, te considèrent: Est-ce là l\'homme qui faisait trembler la terre, ébranlait les empires,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'changeait le monde en désert, et rasait ses villes, et ne relâchait pas ses captifs? –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Tous les rois des nations reposent tous avec honneur, chacun dans sa tombe;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'mais toi, tu es jeté loin de ton tombeau, comme un rameau méprisé, recouvert de morts percés par l\'épée, précipités sur les pierres de la fosse, comme un cadavre foulé aux pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Tu n\'es pas réuni à eux dans la tombe; car tu as ruiné ton pays, massacré ton peuple; la race des méchants ne sera plus nommée à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Préparez une boucherie à ses fils pour le crime de leurs pères, afin qu\'ils ne s\'élèvent pas, et n\'occupent pas la terre, et ne remplissent pas le monde d\'ennemis! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Ainsi je me lèverai contre eux, dit l\'Éternel des armées, et j\'exterminerai de Babel et le nom, et le reste, et le rejeton, et la tige, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'Et j\'en ferai le gîte du hérisson, et un marécage, et je la balaierai avec le balai de la dévastation, dit l\'Éternel des armées. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'L\'Éternel des armées le jure, en disant: Oui, comme je l\'ai conçu, ainsi sera-t-il fait; et comme je l\'ai arrêté, ainsi arrivera-t-il!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'J\'écraserai l\'Assyrien dans mon pays, et sur mes montagnes je le foulerai, afin qu\'ils soient déchargés de son joug, et leurs épaules déchargées de son poids.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Telle est la décision arrêtée contre toute la terre, et c\'est là la main étendue sur toutes les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Car l\'Éternel des armées a pris une décision; qui la déjouerait? et sa main est étendue; qui la ramènerait en arrière?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'L\'année de la mort du Roi Achaz cet oracle fut prononcé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Ne te réjouis pas, Philistie tout entière, de ce qu\'a été brisée la verge qui te frappait! Car de la racine du serpent sort une vipère, et son fruit est un dragon volant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Alors les enfants des malheureux paîtront paisiblement, et les indigents reposeront en sécurité, et par la faim je ferai périr ta racine, et tes restes seront massacrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Porte, gémis! Ville, lamente-toi! Philistie tout entière, tu es consternée, car du nord arrive une fumée, et nul ne se détache de ses bataillons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Et que répond-on aux messagers du peuple? Que l\'Éternel est le soutien de Sion, et que les malheureux de son peuple y trouvent un refuge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Oracle contre Moab. Oui, de nuit Ar-Moab est saccagée, détruite: oui, de nuit Kir-Moab est saccagée, détruite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'On monte au temple, et Dibon en pleurs se rend sur les hauts lieux; sur Nebo et sur Médeba Moab gémit; toutes les têtes sont rasées, toutes les barbes coupées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Dans ses rues on ceint le cilice; sur ses toits et dans ses places tout gémit, fond en larmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Hesbon et Élealé se lamentent, jusqu\'à Jahats leurs cris se font entendre; c\'est pourquoi les braves de Moab crient; il a l\'âme attristée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Mon cœur gémit sur Moab, dont les fugitifs s\'en vont jusqu\'à Tsoar, jusqu\'à Églath-Schelischia, car on monte en pleurant la pente de Luchith, car le long du chemin de Choronaïm ils élèvent des cris déchirants;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'car les eaux de Nimrim sont désolées, car le gazon est séché et l\'herbe disparue; il n\'y a plus de verdure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Aussi transportent-ils au-delà du torrent du désert l\'épargne qu\'ils ont faite, et leurs trésors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Car des cris font le tour des frontières de Moab; ses gémissements [retentissent] jusqu\'à Eglaïm, ses gémissements jusqu\'à Beer-Elim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Car les eaux de Dimon sont pleines de sang; car j\'infligerai à Dimon de nouveaux malheurs; contre les réchappés de Moab j\'enverrai un lion, contre ceux qui seront demeurés dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Envoyez les agneaux du chef du pays de Séla par le désert à la montagne de la fille de Sion!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Car les filles de Moab, les riverains de l\'Arnon, seront telles qu\'un oiseau fugitif, qu\'une couvée effarouchée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, '« Donnez conseil, intercédez! abrite-nous de ton ombre comme de la nuit, dans le milieu du jour; cache des bannis, ne trahis pas le fugitif!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Que mes bannis, les bannis de Moab, puissent séjourner chez toi! sois pour eux un asile contre le dévastateur! car l\'oppression aura une fin, le ravage cessera, l\'oppresseur se retirera du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Ainsi la bonté affermira le trône, où siégera fidèlement dans la tente de David un juge attaché aux lois, versé dans la justice. » –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, '« Nous savons quel est l\'orgueil de Moab orgueilleux à l\'excès, sa hauteur et son orgueil, et son insolence, et son vain parler. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Aussi, que Moab gémisse sur Moab! que tous gémissent! sur les ruines de Kir-Charéseth lamentez-vous, tout abattus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'car les campagnes de Hesbon languissent, elle languit la vigne de Sibma dont les nobles ceps enivraient les maîtres des nations, atteignaient à Jaëser, erraient dans le désert; dont les pampres s\'étendaient, traversaient la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Aussi je pleure, comme Jaëser pleure la vigne de Sibma; je t\'arrose de mes larmes, Hesbon et Élealé, parce que l\'alarme fond sur ta vendange et sur tes récoltes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'La joie et l\'allégresse est chassée des vergers, et dans les vignes plus de gais chants! plus de cris éclatants! plus de pressureur qui foule le vin dans les cuves! j\'ai fait cesser les chansons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Aussi ma poitrine soupire sur Moab, comme le luth, et mon cœur sur Kir-Charès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Et que Moab se présente, se fatigue sur les hauts lieux, et entre dans son sanctuaire pour prier! il n\'obtiendra rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Telle est la parole qu\'a prononcée jadis l\'Éternel sur Moab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Mais maintenant l\'Éternel parle et dit: Dans trois ans, comme des années de mercenaires, la gloire de Moab tombera dans le mépris avec toute cette grande multitude, et le reste en sera très petit, bien peu considérable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Oracle contre Damas. Voici, Damas cesse d\'être au nombre des villes, elle devient un monceau de ruines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Les villes d\'Aroër sont abandonnées, livrées aux troupeaux qui s\'y couchent, et que personne n\'effarouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'C\'en est fait de la forteresse d\'Éphraïm, et de l\'empire de Damas, et du reste de la Syrie: il en sera d\'eux, comme de la gloire des enfants d\'Israël, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'Et dans ce jour s\'évanouira la gloire de Jacob, et l\'embonpoint de son corps se changera en maigreur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Et il en sera comme quand le moissonneur récolte les blés, et que sa main tranche les épis, et comme quand on ramasse les épis dans la vallée de Rephaïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Et il y restera une glanure comme à l\'abattis des olives, deux, trois fruits au haut de la cime, quatre, cinq sur les rameaux de l\'arbre fruitier, dit l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'En ce même jour, l\'homme tournera ses regards vers son Créateur, et ses yeux regarderont vers le Saint d\'Israël:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'et il ne tournera plus ses regards vers les autels, œuvre de ses mains, et il ne regardera plus ce que ses doigts ont façonné, ni les Aschères, ni les colonnes solaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'En ce jour, ses villes fortes seront comme les débris des forêts et des montagnes, que laissa l\'ennemi en s\'éloignant des enfants d\'Israël: et ce sera un désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Car tu oublias ton Dieu sauveur, et ne pensas point à ton rocher de refuge: c\'est pourquoi tu fis de belles plantations, et tu les plantas de boutures étrangères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'En les plantant tu y mis une clôture, et bientôt tu fis fleurir tes rejetons; [mais] la récolte t\'échappe au moment d\'en jouir, et la douleur est mortelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Ho! Une rumeur de peuples nombreux! ils grondent comme gronde la mer! Et un fracas de nations! c\'est un tumulte pareil au tumulte des eaux puissantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Les peuples grondent comme grondent les grosses eaux. Mais Il les tance, et ils fuient au loin, chassés, comme la balle des montagnes au souffle du vent, et comme le tourbillon devant la tempête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'C\'est le soir, et voici, ruine soudaine! et avant le matin ils ne sont plus. Tel est le lot de nos spoliateurs, et le sort de nos ravisseurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Ho! Terre aux navires ailés qui es au delà des fleuves d\'Ethiopie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'toi qui envoies des messagers sur la mer dans des nefs de roseau sur la surface des eaux! Allez, émissaires légers, vers la nation robuste et agile, vers le peuple dès son origine et toujours formidable, nation qui nivelle et écrase, dont des fleuves coupent le pays!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Vous tous, habitants du monde et habitants de la terre, quand on dressera l\'étendard sur les montagnes, regardez! et quand on sonnera de la trompette, écoutez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Car, ainsi me parle l\'Éternel: Tranquille, je regarde de ma demeure, pendant la chaleur sereine aux rayons du soleil, et à la vapeur de rosée durant la chaleur de la moisson.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Car avant la moisson, quand la crue sera complète, et que la fleur aura passé en raisin mûr, alors il tranchera les sarments avec la serpe, et enlèvera les pampres, et les coupera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Ils seront tous livrés aux oiseaux de proie des montagnes et aux bêtes des champs, et les oiseaux de proie y passeront un été, et toutes les bêtes des champs un hiver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'En ce même temps, des offrandes seront apportées à l\'Éternel des armées par le peuple robuste et agile, et par le peuple dès son origine et toujours formidable, nation qui nivelle et écrase, dont des fleuves coupent le pays, dans la résidence de l\'Éternel des armées, sur la montagne de Sion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Oracle contre l\'Egypte. Voici, l\'Éternel est monté sur un nuage léger, et s\'avance contre l\'Egypte; et les idoles de l\'Egypte tremblent à son aspect, et le cœur des Égyptiens se fond au dedans d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Et j\'arme Égyptien contre Égyptien, afin qu\'ils se battent frère contre frère, ami contre ami, ville contre ville, royaume contre royaume.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Et l\'esprit disparaîtra du cœur des Égyptiens, et j\'anéantirai leur prudence; alors ils s\'adresseront aux idoles et aux devins, aux nécromans et aux habiles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'et je livrerai l\'Egypte à un maître rigide, et un roi dur les assujettira, dit le Seigneur, l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Et l\'eau du fleuve sera tarie, et la rivière mise à sec et aride,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'et les ruisseaux seront infects, et les canaux d\'Egypte chétifs et desséchés, et les roseaux et les joncs malades.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Les prairies du fleuve, des bords du fleuve, et tous les guérets du fleuve seront desséchés, dépouillés et détruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Alors gémiront les pêcheurs, et tous ceux qui jettent l\'hameçon dans le fleuve seront en deuil, et ceux qui étendent le filet sur les eaux seront dans la stupeur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'et ceux qui travaillent le lin sérancé et tissent de blanches étoffes, dans la confusion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Et les colonnes du pays sont brisées, et tous les mercenaires ont l\'âme attristée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Les Princes de Tsoan ne sont que des insensés, et des sages conseillers de Pharaon la prudence devient stupidité. Comment diriez-vous à Pharaon: « Je suis un fils des sages, un fils des anciens rois »?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Où sont-ils donc tes sages? Eh! qu\'ils t\'annoncent, afin qu\'on le sache, ce qu\'a arrêté l\'Éternel des armées contre l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Les Princes de Tsoan sont aliénés, les Princes de Noph abusés, et l\'Egypte égarée par les chefs de ses tribus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'L\'Éternel a versé en eux un esprit d\'erreur, afin qu\'ils égarent les Égyptiens dans tous leurs actes, comme un homme ivre tourne et s\'égare dans son vomissement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'et il ne sort de l\'Egypte pas un fait exécuté par la tête ni la queue, la branche de palmier ni le jonc.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'En ce jour-là, les Égyptiens seront comme des femmes, et craintifs et tremblants, en voyant s\'agiter la main que l\'Éternel des armées agitera sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Alors le pays de Juda sera la terreur de l\'Egypte, et tous ceux qu\'on fera penser à lui prendront l\'alarme, à cause de l\'arrêt de l\'Éternel prononcé contre elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'En ce même temps il y aura cinq villes au pays d\'Egypte, parlant la langue de Canaan et assermentées à l\'Éternel des armées: Ville de salut sera le nom de l\'une d\'elles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'En ce même temps, il y aura un autel de l\'Éternel au sein du pays d\'Egypte, et sur sa frontière un cippe consacré à l\'Éternel:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'ce qui sera pour l\'Éternel des armées un signe et un témoignage dans le pays d\'Egypte; car ils crieront à l\'Éternel contre les oppresseurs, et Il leur enverra un sauveur et un vengeur, afin de les délivrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Et l\'Éternel se manifestera aux Égyptiens, et les Égyptiens apprendront à connaître l\'Éternel en ce temps-là, et offriront des victimes et des oblations, et feront des vœux à l\'Éternel, et les accompliront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Ainsi l\'Éternel frappe l\'Egypte, frappant mais guérissant, et eux se convertissent à l\'Éternel, qui se laisse fléchir par eux et les guérit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'En ce même temps, il y aura une route d\'Egypte en Assyrie, et l\'Assyrien viendra en Egypte, et l\'Égyptien ira en Assyrie, et l\'Égyptien avec l\'Assyrien servira [l\'Éternel].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'En ce même temps, Israël sera, lui troisième, uni à l\'Egypte et à l\'Assyrie, bénédiction au milieu de la terre');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'que bénira l\'Éternel des armées en disant: Bénie soit l\'Egypte, ma nation, et l\'Assyrie, œuvre de mes mains, et Israël, mon héritage!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'L\'année où Tartan s\'avança sur Asdod, envoyé par Sargon, roi d\'Assyrie, et où il assiégea et prit Asdod,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'en ce temps-là l\'Éternel parla par l\'intermédiaire d\'Ésaïe, fils d\'Amots, et dit: Va, et détache le cilice de tes reins, et ôte tes souliers de tes pieds. Et il fit ainsi, et alla sans manteau et nu-pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Alors l\'Éternel dit: De même que mon serviteur Ésaïe va sans manteau et nu-pieds, pendant trois ans signe et présage pour l\'Egypte et pour l\'Éthiopie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'de même le roi d\'Assyrie emmènera les captifs de l\'Egypte et les captifs de l\'Ethiopie, jeunes hommes et vieillards, sans manteau et nu-pieds et le dos découvert, opprobre pour l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Alors ils seront consternés, et auront honte de l\'Ethiopie qui avait leur confiance, et de l\'Egypte dont ils se glorifiaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Et les habitants de cette côte diront en ce jour: Voilà où en sont ceux qui avaient notre confiance, vers qui nous fuyions, pour être secourus, pour être délivrés du roi d\'Assyrie! et nous, comment pourrions-nous échapper?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Oracle contre le désert de la mer. Comme l\'ouragan du midi s\'avance, ainsi il arrive du désert, de la terre redoutable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Une vision menaçante m\'a été révélée: le pillard pille et le dévastateur dévaste. « Avance, Elam! Assiège, Mède! A tous les soupirs je vais mettre un terme. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'C\'est pourquoi mes reins sont remplis d\'angoisses, des douleurs me saisissent pareilles aux douleurs de la femme en travail; le tourment m\'ôte l\'ouïe, et les angoisses la vue;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'mon cœur s\'égare; l\'horreur m\'assaille; de ma nuit de réjouissances on a fait une nuit de terreur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'On dresse la table, la sentinelle veille, on mange, on boit: « Debout! chefs, oignez le bouclier! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Car ainsi m\'a parlé le Seigneur: Va, place la sentinelle: ce qu\'elle verra, elle te le rapportera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Elle vit de la cavalerie, des cavaliers sur des chevaux, deux à deux, des cavaliers sur des ânes, des cavaliers sur des chameaux, et elle écouta, écoutant avec grande attention.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Et elle cria comme un lion: Avec constance, Seigneur, je me tenais le jour dans la vedette et j\'étais à mon poste toutes les nuits:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'et voici venir de la cavalerie, des cavaliers sur des chevaux deux à deux. Puis reprenant la parole, elle dit: Babel tombe, tombe, et toutes ses idoles brisées jonchent la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'O toi, mon peuple qu\'on triture, mon grain qui est sur l\'aire! Ce que j\'ai ouï de l\'Éternel des armées, Dieu d\'Israël, je vous l\'ai déclaré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Oracle contre Duma. De Séïr on me crie: Sentinelle, que reste-t-il de la nuit, que reste-t-il de la nuit?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'La sentinelle dit: Le matin vient, puis aussi la nuit. Si vous voulez interroger, interrogez! Revenez-y!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Oracle contre l\'Arabie. Dans les steppes d\'Arabie vous passez la nuit, caravanes de Dedan!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Au-devant de ces hommes altérés viennent avec de l\'eau les habitants du pays de Théma: ils présentent du pain aux fugitifs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'car ils fuient devant les épées, devant l\'épée nue, et devant l\'arc bandé, et devant le poids de la guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Car ainsi me parla le Seigneur: Encore une année, telle que les années du mercenaire, et c\'en est fait de toute la gloire de Cédar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'Et le nombre restant des vaillants archers des enfants de Cédar, sera petit, car l\'Éternel, Dieu d\'Israël, l\'a prononcé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Oracle contre la vallée des visions. Que t\'arrive-t-il donc, que tous tes habitants sont montés sur les toits,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'ville pleine de tumulte, cité bruyante et joyeuse? Tes morts ne seront pas percés par l\'épée, ni tués dans le combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Tous tes généraux fuient ensemble, sont pris par les archers, tous ceux qui se trouvent en ton sein sont pris à la fois, ils fuient au loin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Aussi dis-je: Détournez les yeux de moi; j\'ai à pleurer amèrement: n\'insistez pas pour me consoler de la ruine de la fille de mon peuple!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Car c\'est une journée de commotion et d\'écrasement et de confusion que tient le Seigneur, l\'Éternel des armées, dans la vallée des visions; on sape les murs, et les cris de détresse vont frapper les montagnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Elam porte le carquois sur des chars pleins d\'hommes et de cavaliers, et Kir tire le bouclier du fourreau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Et tes plus belles vallées sont remplies de chars, et les cavaliers prennent position entre tes portes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Et le voile de Juda est levé, et en ce jour tu portes tes regards vers les munitions de la maison de cèdre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'Et vous apercevez les brèches de la ville de David, qui sont nombreuses, et vous recueillez les eaux de l\'étang inférieur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'et vous comptez les maisons de Jérusalem, et vous en abattez pour fortifier les murs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'et vous faites un réservoir entre les deux murs pour les eaux de l\'antique étang. Mais vous ne regardez pas vers l\'auteur de ces choses, et ne tournez pas les yeux vers Celui qui de loin en a formé le plan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Et en ce jour le Seigneur, l\'Éternel des armées, vous convie à pleurer, à gémir, à couper vos cheveux et à ceindre le cilice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Mais voici, plaisir et joie; on tue des taureaux, on égorge des brebis, on mange de la chair, et on boit du vin: « Mangeons et buvons, car demain nous mourrons! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Cependant l\'Éternel des armées s\'est révélé à mes oreilles: Non, ce crime ne sera pas expié que vous ne soyez morts, dit le Seigneur, l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Ainsi parle le Seigneur, l\'Éternel des armées: Va, rends-toi vers ce courtisan, vers Sebna préposé au palais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, '« Qu\'as-tu à faire ici? et qui as-tu ici, que tu te creuses ici un tombeau, creusant un tombeau sur la hauteur, te taillant dans le roc une demeure?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Voici, l\'Éternel te jettera bas d\'un coup vigoureux, et te saisira;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Il te fera rouler, rouler, comme une balle sur une terre vaste et spacieuse; là tu mourras, et là seront tes chars magnifiques, toi l\'opprobre de la maison de ton maître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Et je te culbuterai de ton poste, et Il te débusquera de ta place. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Et en ce jour même j\'adresserai vocation à mon serviteur Eliacim, fils de Hilkia;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'et je le revêtirai de ton manteau et le ceindrai de ta ceinture, et je mettrai ton pouvoir en sa main, et il sera un père pour les habitants de Jérusalem et pour la maison de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Et je mettrai la clef de la maison de David sur son épaule, et il ouvrira, et personne ne fermera; il fermera, et personne n\'ouvrira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Et je l\'enfoncerai comme un clou en lieu sûr, et il sera un trône glorieux pour la maison de son père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'et il sera le soutien de tout ce qui est la gloire de la maison de son père, des rejetons et des surgeons, de tous les petits vases depuis les bassins jusqu\'à toutes les coupes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'En ce même jour, dit l\'Éternel des armées, sera ôté le clou enfoncé en lieu sûr; il sera abattu et tombera, et le fardeau qu\'il portait croulera, car l\'Éternel l\'a prononcé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Oracle contre Tyr. Gémissez, navires de Tarsis! car elle est détruite: plus de maisons! personne n\'y entre: la nouvelle leur en vient du pays de Cittim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Frissonnez, habitants de la côte que remplissaient les marchands de Sidon, qui parcourent les mers!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Sur les vastes eaux flottait le blé du fleuve noir, les moissons du Nil, son revenu; et elle était le marché des nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Sois honteuse, Sidon! car la mer, le fort de la mer, tient ce langage: « Je n\'eus point les douleurs, et n\'enfantai point, je ne nourris point de jeunes hommes et n\'élevai point de vierges. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Quand la nouvelle en viendra en Egypte, ils trembleront aux nouvelles de Tyr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Passez à Tarsis, gémissez, habitants de la côte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Est-ce là votre ville joyeuse, dont l\'origine remontait à l\'antiquité? Ses pieds la mènent demeurer au loin comme étrangère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Qui a porté cet arrêt contre Tyr, la distributrice des couronnes, dont les marchands étaient des princes, et les trafiquants les notables de la terre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'L\'Éternel des armées a porté cet arrêt, pour profaner toute grandeur brillante, et couvrir de mépris tous les notables de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Parcours librement ton pays, pareille au Nil, fille de Tarsis! Il n\'y a plus de chaînes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Il étendit sa main sur la mer, ébranla les royaumes; l\'Éternel commanda à Canaan de détruire ses forts, et');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'Il dit: Désormais tu ne te réjouiras plus, vierge déshonorée, fille de Sidon! Lève-toi! passe chez les Cittiens! là non plus nul repos pour toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Vois le pays des Chaldéens! Ce peuple [naguère] n\'était pas; l\'Assyrien assigna ce pays aux habitants du désert: ils élèvent leurs vedettes, détruisent ses palais et les mettent en ruines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Gémissez, navires de Tarsis, car votre boulevard est détruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'Et en ce temps-là Tyr sera oubliée soixante-dix ans, le temps de la vie d\'un roi; mais au bout de soixante-dix ans, il en arrivera à Tyr selon la chanson de la courtisane:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, '« Prends le luth, parcours la ville, courtisane oubliée, tire de beaux sons de la lyre, redouble tes chants, pour qu\'on se souvienne de toi! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Et au bout de soixante-dix ans, l\'Éternel jettera les yeux sur Tyr, et ses gains impurs lui reviendront, et elle aura commerce avec tous les royaumes du monde sur la face de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Mais ses profits et ses gains impurs seront consacrés à l\'Éternel; ils ne seront ni accumulés ni mis en réserve, mais ses profits seront la part de ceux qui habitent devant l\'Éternel, pour les nourrir abondamment, et pour les vêtir avec magnificence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Voici, l\'Éternel vide le pays et le dévaste, et il en bouleverse la surface et en disperse les habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Et il en sera du sacrificateur comme du peuple, du maître comme du serviteur, de la maîtresse comme de la servante, du vendeur comme de l\'acheteur, du prêteur comme de l\'emprunteur, du créancier comme du débiteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Le pays sera vidé, et il sera mis au pillage, car l\'Éternel a prononcé cette parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Le pays gémit et languit, le monde est dans la langueur et dans le deuil, les sommités du peuple du pays languissent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Or le pays était profané par ses habitants; car ils violaient les lois, transgressaient les ordonnances, rompaient l\'alliance éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Aussi, la malédiction dévore le pays et les habitants en portent la peine; c\'est pourquoi les habitants du pays sont consumés, et il n\'en survit qu\'un petit nombre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Le moût est triste, et la vigne dépérit; tous ceux qui avaient le cœur joyeux, soupirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Les joies des cymbales ont cessé, et le bruit de la gaieté a fini, les joies de la harpe ont cessé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'On ne boit plus de vin en chantant, la cervoise est amère aux buveurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'La ville en ruine est une cité déserte; toute maison est fermée, on n\'y entre plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Sur le vin on se lamente dans les rues, toute joie est disparue, et la gaieté du pays est bannie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Ce qui reste dans la ville, c\'est la désolation, et les portes brisées sont en ruines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Car il en est dans le pays, au milieu des peuples, comme à l\'abattis des olives, comme au grappillage quand la vendange est finie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Les autres élèvent leurs voix, poussent des cris d\'allégresse; depuis la mer ils célèbrent la majesté de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Aussi glorifiez l\'Éternel dans l\'orient, dans les îles de la mer le nom de l\'Éternel, Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Des bouts de la terre nous entendons des chants: « Gloire au juste! » Mais moi je dis: Ruine sur moi! ruine sur moi! malheur à moi! Les pillards pillent, et les pillards enlèvent du pillage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Effroi, et fosse, et filet devant toi, habitant du pays!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Qui fuit l\'effroi, tombe dans la fosse, et qui se tire de la fosse, se prend au filet, car les écluses des lieux très-hauts s\'ouvrent, et les fondements de la terre branlent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'La terre se brise, la terre se rompt, la terre est ébranlée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'La terre chancelle comme un homme ivre, elle se balance comme un hamac, et son péché pèse sur elle, et elle tombe pour ne pas se relever.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'Et en ce même jour, l\'Éternel châtiera l\'armée des lieux très-hauts dans les lieux très-hauts, et les rois de la terre sur la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'et ils seront réunis captifs dans la prison, et enfermés dans le cachot, et après un long temps ils seront châtiés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Alors la lune sera honteuse et le soleil confus; car l\'Éternel des armées règne sur la montagne de Sion et à Jérusalem, et devant ses anciens resplendira la gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Éternel, tu es mon Dieu, je t\'exalte, je célèbre ton nom, car tu as opéré des prodiges, tes plans conçus de loin furent vérité et fidélité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Car tu as fait de la ville une masure et de la forte cité une ruine; les palais des étrangers ne forment plus de ville, jamais ils ne seront relevés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Aussi des peuples puissants te louent, et les cités des nations fortes te révèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Car tu fus le refuge du faible, le refuge du misérable dans sa détresse, un abri contre la tempête, un ombrage contre la chaleur, quand le souffle des tyrans était comme l\'ouragan qui bat la muraille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Ainsi que la chaleur dans une terre brûlante, tu abats les menaces des étrangers, ainsi que la chaleur par l\'ombre d\'un nuage, ainsi sont étouffés les chants de triomphe des tyrans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Et l\'Éternel des armées apprête à tous les peuples, sur cette montagne, un festin de mets succulents, un festin de vin pris sur sa lie, de mets succulents et de moelle, de vin pris sur sa lie et limpide,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'et sur cette montagne Il anéantit le voile qui voile tous les peuples, et la mante qui couvre toutes les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Il anéantit la mort pour toujours, et le Seigneur Éternel essuie les larmes de tout visage, et fait disparaître de toute la terre l\'opprobre de son peuple, car l\'Éternel l\'a prononcé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Et dans ce jour l\'on dira: « Voici, c\'est notre Dieu en qui nous avons eu confiance qu\'il nous sauverait; c\'est notre Dieu en qui nous avons eu confiance: soyons dans l\'allégresse et réjouissons-nous de son secours! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Car la main de l\'Éternel repose sur cette montagne, et Moab sera trituré sur place, comme la paille est triturée dans le bain de fumier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Là dedans il allongera les bras, comme le nageur les étend en nageant; mais [l\'Éternel] refoulera son orgueil, et l\'effort de ses bras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Et Il abattra le rempart élevé de tes murs, Il le fera crouler, joncher la terre dans la poussière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'En ce même jour, on chantera cet hymne dans le pays de Juda: « Nous avons une ville forte; le secours qu\'il donne, nous est un rempart et un fossé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Ouvrez les portes, afin qu\'entre un peuple juste, gardien de la fidélité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Au cœur affermi tu réserves la paix, la paix, parce qu\'il se confie en toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Confiez-vous en l\'Éternel perpétuellement, car l\'Éternel est l\'Éternel, un rocher pour tous les siècles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Car Il précipita les habitants du lieu élevé, de la ville éminente, Il l\'étendit, l\'étendit par terre, la coucha dans la poussière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Elle est foulée par les pieds, les pieds des malheureux, sous les pas des petits. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, '« Le sentier du juste est une voie unie; du juste tu nivelles et aplanis l\'ornière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Sur la voie de tes jugements nous t\'attendons aussi, Éternel, et ton nom et ton souvenir sont les vœux de notre âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Mon âme te désire la nuit, et en moi mon esprit te cherche; car dès que [tu révèles] tes jugements à la terre, les habitants du monde sont instruits de la justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Quand l\'impie obtient grâce, il n\'apprend pas la justice; il est pervers dans le pays de la droiture, et ne considère point la grandeur de l\'Éternel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, '« Éternel, ta main fut levée: ils ne l\'ont pas vu! ils verront, et en seront confus, ton zèle pour le peuple, et le feu dévorera tes adversaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Éternel, tu nous donnes la paix, car c\'est toi qui opères pour nous tout ce que nous faisons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Éternel, notre Dieu, nous fûmes asservis à d\'autres maîtres qu\'à toi; mais à toi seul nous devons d\'invoquer ton nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Des morts ne ressusciteront pas, des ombres ne se relèveront pas; car tu les as châtiés et tu les as détruits, et tu as anéanti toute leur mémoire. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, '« Tu accrois le peuple, Éternel, tu accrois le peuple, tu te montres glorieux, tu recules toutes les limites du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Éternel, dans l\'angoisse ils regardèrent vers toi, se répandirent en prières, quand ils sentirent tes châtiments.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Comme la femme enceinte près de son terme ressent des douleurs et crie pendant son tourment, tels étions-nous loin de toi, Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Nous eûmes le poids d\'une grossesse, et les angoisses, et l\'enfantement ne donna que du vent; le salut du pays n\'est pas produit et les habitants du monde ne sont pas nés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Que tes morts revivent, et que mes cadavres ressuscitent! Réveillez-vous et chantez, habitants de la poudre, car ta rosée est une rosée de végétation, et la terre rendra le jour aux ombres! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Allons! mon peuple, entre dans tes chambres et ferme les portes derrière toi! cache-toi pour un court instant, jusqu\'à ce que le courroux soit passé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Car voici, l\'Éternel sort de son séjour pour infliger aux habitants de la terre la peine de leurs crimes, et la terre laissera voir leur sang, et ne recèlera plus ses morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'En ce même jour, l\'Éternel châtiera avec sa dure, grande et forte épée le léviathan, serpent fuyard, et le léviathan, serpent tortueux, et tuera le dragon de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'En ce même jour, chantez ainsi sur la vigne:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, '« Moi, l\'Éternel, je suis son gardien, je l\'arrose en tout temps, contre les attaques nuit et jour je la garderai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Je suis sans colère! Qu\'on m\'oppose des ronces et des épines! en combattant je fondrai sur eux et les consumerai en entier;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'à moins qu\'ils ne saisissent mon appui, et ne fassent leur paix avec moi, ne fassent leur paix avec moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'A l\'avenir Jacob poussera des racines, et Israël des bourgeons et des fleurs, et de leurs fruits ils rempliront le monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Frappa-t-Il [Israël] des coups dont Il frappa ceux qui l\'ont frappé? ou fut-il égorgé comme furent égorgés ceux qui l\'ont égorgé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Ce fut modérément, en le répudiant, que tu le punis, qu\'il fut emporté par ton souffle violent au jour du vent d\'Orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'C\'est aussi par là que fut expié le crime de Jacob; et c\'est là justement le fruit de l\'abandon qu\'il fit de son péché, quand Il rendit toutes les pierres des autels pareilles à des pierres calcinées, concassées, pour qu\'il ne s\'élève plus d\'aschères ni de colonnes solaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Car la cité [jadis] forte est dévastée; c\'est un séjour abandonné et désolé comme le désert, le veau y pâture, il s\'y couche et broute ses rameaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Quand ses branches sèchent, elles sont brisées, des femmes viennent et y mettent le feu. Car il ne fut pas un peuple sage; aussi son créateur n\'eut pas pitié de lui, et son formateur ne lui fut pas propice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Mais en ce même jour, l\'Éternel secouera des fruits depuis les flots du Fleuve jusqu\'au torrent d\'Egypte, et vous serez ramassés un à un, enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Et en ce même jour la grande trompette sonnera, et ceux qui étaient perdus au pays d\'Assyrie et bannis au pays d\'Egypte, viendront et adoreront l\'Éternel sur la montagne sainte à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Malheur à la couronne superbe des ivrognes d\'Éphraïm, fleur qui passe, leur brillante parure, sise sur une cime dans la vallée fertile de ceux qu\'étourdit le vin!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Voici venir de par le Seigneur, un fort et puissant ennemi, comme un orage de grêle, un ouragan destructeur, comme une trombe de grosses eaux qui inondent; il va la faire tomber en terre sous ses coups.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Sous les pieds elle va être foulée, la couronne superbe des ivrognes d\'Éphraïm;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'et la fleur qui passe, leur parure brillante, sise sur une cime dans la vallée fertile, sera comme avant la récolte la figue primeur; on l\'aperçoit; à peine dans la main, elle est avalée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'En ce même jour, l\'Éternel des armées sera une couronne de parure et un diadème brillant pour les restes de son peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'et un esprit de jugement pour le juge qui siège, et une force pour ceux qui font rentrer les agresseurs dans leurs portes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Mais ceux-ci aussi sont troublés par le vin, et la cervoise les fait chanceler; prêtres et prophètes sont troublés par la cervoise, subjugués par le vin, la cervoise les fait chanceler; ils sont troublés quand ils prophétisent, égarés quand ils jugent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Car toutes les tables sont pleines de vomissements et d\'ordures; il n\'y a plus de place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, '« A qui veut-il enseigner la sagesse et à qui donner des leçons? A des enfants sevrés, ôtés à la mamelle?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Car c\'est loi sur loi, loi sur loi, règle sur règle, règle sur règle; un peu ici, un peu là! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Oui, c\'est par des hommes aux lèvres balbutiantes, et en langue étrangère, qu\'il parlera à ce peuple');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'auquel Il disait: « C\'est ici le lieu du repos; procurez du repos au peuple fatigué; c\'est ici le lieu du relâche; » mais ils ne voulurent point écouter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Et pour eux la parole de l\'Éternel sera: « Loi sur loi, loi sur loi, règle sur règle, règle sur règle, un peu ici, un peu là, » afin qu\'ils aillent et qu\'ils tombent à la renverse, et qu\'ils se brisent, et qu\'ils s\'enlacent, et qu\'ils se prennent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Aussi, écoutez la parole de l\'Éternel, moqueurs, dominateurs de ce peuple qui est dans Jérusalem!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Parce que vous dites: « Nous avons fait un pacte avec la mort, et avec l\'Enfer un compromis, la verge de l\'inondation à son passage ne nous atteindra pas, car nous prenons le mensonge pour asile et la fraude pour abri; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'c\'est pourquoi, ainsi parle le Seigneur, l\'Éternel: C\'est moi qui ai mis en Sion pour fondement une pierre, pierre éprouvée, pierre angulaire de prix, fondement bien fondé; qui s\'y fie, n\'aura pas à fuir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'et je ferai du bon droit le cordeau et de la justice la balance, et la grêle détruira l\'asile du mensonge, et l\'abri sera submergé par les eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Et votre pacte avec la mort sera déjoué, et votre compromis avec l\'Enfer sera sans effet, par la verge de l\'inondation à son passage vous serez écrasés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Toujours à son passage elle vous saisira; car chaque matin elle passera, le jour et la nuit, c\'est une terreur seulement d\'en entendre le bruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Oui, le lit sera trop court pour s\'y étendre, et la couverture trop étroite pour s\'en envelopper.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Car, comme au mont Peratsim, l\'Éternel se lèvera, comme dans la vallée de Gabaon Il se courroucera, pour exécuter son œuvre, son œuvre étrange, et pour faire son travail, son travail inouï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Et maintenant, ne vous moquez point, de peur que vos chaînes ne se serrent! car j\'ai appris de l\'Éternel des armées que la ruine de toute la terre est décidée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Prêtez l\'oreille et entendez ma voix! écoutez et entendez ma parole!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Le laboureur laboure-t-il sans cesser pour semer? il ouvre aussi et herse son sol:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'en a-t-il aplani la surface, il y sème de l\'anet et y répand du cumin; il plante le froment par rangées, et l\'orge à une place fixe, et l\'épeautre sur ses bords.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Son Dieu lui enseigna la manière, et Il l\'instruisit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Car ce n\'est pas non plus avec le traîneau qu\'on foule l\'anet, et le madrier avec ses roues ne passe pas sur le cumin; mais l\'anet est battu avec le bâton, et le cumin avec la perche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Le blé est battu, mais il ne le bat pas sans fin; il y fait passer les roues de son chariot et ses chevaux, il ne l\'écrase pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Cela aussi procède de l\'Éternel des armées: admirable est son conseil, et grande sa sagesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Ha! Ariel! Ariel! cité où campa David! ajoutez année à année, que les fêtes fassent leur révolution,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'et je serrerai Ariel de près, et il y aura des soupirs et des cris; mais alors j\'aurai en elle une Ariel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'et je te cernerai comme un cercle, et te serrerai de près avec des bataillons, et j\'élèverai contre toi des forts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'et du sol où tu tomberas, ta parole sortira, et de la poudre s\'élèveront sourdement tes discours, et ta voix sera celle d\'un spectre sortant de terre, et de la poussière tu murmureras tes discours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Mais telle la poussière menue, telle sera la foule de tes ennemis, et telle la balle qui s\'envole, telle sera la foule des furieux, et cela soudain, tout à coup.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'De par l\'Éternel des armées il y aura châtiment avec grondement et fracas et grand bruissement, orage et tempête et flamme d\'un feu dévorant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Et comme d\'un songe, d\'une vision nocturne, ainsi il en sera de la foule de tous les peuples agresseurs d\'Ariel, et de tous ceux qui l\'assaillent, elle et sa citadelle, et qui la pressent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Et ce sera comme quand l\'affamé songe qu\'il mange, et il s\'éveille, et il a l\'estomac vide; et comme quand l\'homme altéré songe qu\'il boit, et il s\'éveille, et voici, il a soif, et son âme languit: ainsi en sera-t-il de la foule des peuples agresseurs de la montagne de Sion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Soyez stupéfaits et étonnés! Aveuglez-vous et soyez aveuglés! ils sont ivres, mais non de vin; ils chancellent, mais non troublés par la cervoise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Car l\'Éternel versa sur vous un esprit d\'assoupissement et ferma vos yeux, les Prophètes, et voilà vos têtes, les Voyants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Et ainsi toute la révélation vous est comme les paroles du livre scellé que l\'on donne à un homme sachant lire, en disant: « Lis-le donc! » Mais il répond: « Je ne puis, car il est scellé; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'et que l\'on donne le livre à qui ne sait pas lire, en disant: « Lis-le donc! » Mais il répond: « Je ne sais pas lire. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Et le Seigneur dit: Parce que ce peuple s\'approche de moi de la bouche, et qu\'il m\'honore des lèvres, tandis que son cœur est éloigné de moi, et que la crainte qu\'il a de moi n\'est que commandement d\'hommes appris,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'pour cela, voici, je signalerai ce peuple par des actes insignes et merveilleux, afin que la sagesse de ses sages périsse, et que l\'intelligence de ses hommes entendus disparaisse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Malheur à ceux qui se cachent pour dérober leurs plans à l\'Éternel, afin que leurs œuvres soient dans les ténèbres! et qui disent: Qui nous voit? et qui prend garde à nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'O perversité à vous! l\'argile sera-t-elle estimée à l\'égal du potier, pour que l\'ouvrage dise de l\'ouvrier: Il ne m\'a pas fait! et que la sculpture dise du sculpteur: Il n\'est pas entendu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Voici, encore très peu de temps, et le Liban se transformera en verger, et le verger sera estimé à l\'égal de la forêt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Et en ce même jour les sourds entendront les paroles du Livre, et, perçant la nuit et l\'obscurité, les yeux des aveugles verront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Alors de plus en plus les misérables se réjouiront de l\'Éternel, et les indigents se glorifieront du Saint d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'parce que le furieux aura fini, que le moqueur sera détruit, et que tous les hommes vigilants pour le crime seront exterminés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'eux qui condamnaient un homme en cause, tendaient des pièges à celui qui se défendait aux Portes, et déboutaient le juste par la fraude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Aussi, ainsi parle à la maison de Jacob l\'Éternel, qui sauva Abraham: Maintenant Jacob ne sera plus confus, et son visage ne pâlira plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Car lorsqu\'il verra ses enfants devenus l\'œuvre de mes mains dans son sein, ils sanctifieront mon nom; oui, ils sanctifieront le Saint de Jacob et ils révéreront le Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Et ceux dont l\'esprit était égaré apprendront la sagesse, et les murmurateurs recevront l\'instruction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Malheur aux enfants réfractaires, dit l\'Éternel, qui prennent des mesures, mais non de par moi, et font des alliances, mais non d\'après mon esprit, pour accumuler péché sur péché,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'qui se mettent en chemin pour l\'Egypte sans me consulter, pour s\'étayer de l\'appui de Pharaon et se réfugier sous l\'ombrage de l\'Egypte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Car pour eux l\'appui de Pharaon tournera en ignominie, et le refuge sous l\'ombrage de l\'Egypte en confusion,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'quoique leurs Princes soient à Tsoan, et que leurs députés aient atteint Chanès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Tous ont honte d\'un peuple qui leur est inutile, dont ils ne tirent ni secours, ni profit, mais honte et confusion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Les bêtes de somme sont chargées pour le Midi; par un pays de détresse et d\'angoisse d\'où viennent la lionne et le lion, la vipère et le serpent volant, ils portent sur la croupe des ânes leurs richesses, et sur le dos des chameaux leurs trésors, à un peuple dont ils n\'auront nul profit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Car l\'aide de l\'Egypte est néant et vanité; c\'est pourquoi je l\'appelle Grand tumulte pour ne point agir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Maintenant va, écris ces choses sur une table devant eux, et marque-les dans un livre, afin qu\'elles se conservent pour l\'avenir, en témoignage pour l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Car c\'est un peuple rebelle, des enfants menteurs, des enfants qui ne veulent pas écouter la loi de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'qui disent aux Voyants: « Ne voyez pas! » et aux prophètes: « Ne nous prophétisez pas la vérité, dites-nous des choses flatteuses, prophétisez l\'illusion!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Sortez de la voie, quittez le sentier, débarrassez notre vue du Saint d\'Israël! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Aussi, ainsi parle le Saint d\'Israël: Puisque vous méprisez cette parole, et que vous vous confiez dans ce qui est inique et pervers, et que vous vous y appuyez,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'à cause de cela ce crime vous sera comme une lézarde ruineuse qui fait saillie sur un mur élevé et en amène soudain tout à coup la chute,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'et il se brise comme se brise le vase du potier cassé sans pitié, dont les débris n\'offrent pas un têt à prendre du feu au foyer, ou à puiser de l\'eau à la fontaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Car ainsi a parlé le Seigneur, l\'Éternel, le Saint d\'Israël: Dans le retour et le repos sera votre salut, dans la tranquillité et dans la confiance sera votre force; mais vous n\'avez pas voulu:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'vous avez dit: « Non! mais sur des chevaux nous voulons nous mettre en course. » – C\'est pourquoi vous serez mis en fuite! – « Nous voulons monter des coursiers! » – C\'est pourquoi ils courront à votre poursuite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Mille fuiront à la menace d\'un seul, et à la menace de cinq vous fuirez, jusqu\'à ce que votre reste soit comme le signal au haut de la montagne, et comme l\'étendard sur la colline.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Aussi tarde-t-il à l\'Éternel de vous être propice: aussi se lèverait-Il pour vous prendre en pitié, car l\'Éternel est un Dieu juste: heureux tous ceux qui se confient en lui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Oui, peuple de Sion qui habites Jérusalem, tu n\'as plus à pleurer! Il veut t\'être propice à ton cri d\'alarme, et t\'exaucer, dès qu\'il l\'ouïra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Et le Seigneur vous donnera du pain dans l\'angoisse, et de l\'eau dans la détresse, et tes docteurs ne devront plus se cacher, mais tes yeux regarderont tes docteurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'et tes oreilles écouteront la parole que derrière toi ils disent: « Voici le chemin! marchez-y! » quand vous allez à droite, et que vous allez à gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Alors vous souillerez le revêtement de vos idoles d\'argent et les draperies de vos images d\'or; vous les jetterez comme de l\'ordure; hors d\'ici! leur direz-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'C\'est pourquoi Il vous donnera les pluies des semailles, quand vous ensemencez le sol, et le pain, produit du sol, sera savoureux et nourrissant, et en ce même temps les troupeaux brouteront dans des pacages spacieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Et les bœufs et les ânes qui travaillent la terre, mangeront un fourrage salé qu\'on vannera avec le van et la pelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Et sur tout mont élevé et sur toute colline éminente il y aura des ruisseaux, des courants d\'eau, au jour du grand massacre, de la chute des tours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Et la lumière de la lune sera comme l\'éclat du soleil, et l\'éclat du soleil sera sept fois plus grand, comme l\'éclat de sept jours, quand l\'Éternel bandera la plaie de son peuple et guérira les meurtrissures de ses coups.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Voici venir de loin le nom de l\'Éternel avec le feu de la colère et le terrible incendie; ses lèvres sont pleines de fureur, et sa langue est comme une flamme dévorante,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'et son souffle comme un torrent débordé qui s\'élève à hauteur d\'homme, pour vanner les nations dans le van de la ruine, et mettre la bride de l\'égarement entre les mâchoires des nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Vous chanterez comme dans la nuit de la fête solennelle, et votre cœur aura la joie du pèlerin qui au son de la flûte se rend à la montagne de l\'Éternel, au rocher d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Et l\'Éternel fera entendre les éclats de sa voix, et voir le mouvement de son bras avec la fureur de la colère, le feu de la flamme dévorante, l\'inondation et la tempête et les pierres de la grêle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Oui, à la voix de l\'Éternel l\'Assyrien tremblera, de sa verge Il le frappera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Et partout où passera la verge qu\'il lui destine, et dont l\'Éternel le battra, les cymbales et les harpes retentiront, et Il lui livrera des assauts impétueux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Oui, dès longtemps une Topheth est prête, même pour le roi elle est préparée, profonde et large: son bûcher a du feu et du bois en abondance, le souffle de l\'Éternel comme un torrent de soufre l\'allume.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Malheur à ceux qui vont en Egypte chercher du secours, et qui se fient dans les chevaux, et se confient dans les chars, parce qu\'ils sont nombreux, et dans la cavalerie, parce qu\'elle est très forte, mais ne regardent pas vers le Saint d\'Israël, et ne s\'adressent pas à l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Cependant Il est sage aussi, et Il amène les maux et ne retire pas ses paroles, et Il se lève contre la maison des méchants et contre le secours des artisans d\'iniquité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Eh! l\'Égyptien est homme et non dieu, et ses chevaux sont chair et non esprit. Or, l\'Éternel va étendre la main, et le protecteur trébuchera, et le protégé tombera, et ensemble ils périront tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Car ainsi me parle l\'Éternel: De même que gronde sur sa proie le lion, et le lionceau contre lequel on a réuni des bergers en foule, et qui à leur voix ne tremble pas, et devant leur nombre ne plie pas; ainsi l\'Éternel des armées descendra pour combattre sur la montagne de Sion, et sur sa sommité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Tels des oiseaux déployant leurs ailes, tel l\'Éternel des armées couvrira Jérusalem, couvrant et sauvant, épargnant et délivrant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Revenez à Celui de qui il y eut profond abandon, enfants d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Oui, en ce jour chacun répudiera ses idoles d\'argent et ses idoles d\'or, que vos mains vous fabriquèrent pour pécher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Et Assur périra par une épée non humaine, et une épée non humaine en fera sa proie, et il fuira devant l\'épée, et ses jeunes hommes seront esclaves.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Dans son effroi il passe outre devant sa propre forteresse, et la peur chasse ses chefs loin des drapeaux, dit l\'Éternel dont le feu est sur Sion et le foyer en Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Puis, voici, le Roi régnera selon la justice, et quant aux princes, ils gouverneront selon le bon droit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'et chacun d\'eux sera comme un abri contre le vent, et un couvert contre l\'orage, comme des ruisseaux dans la sécheresse, comme l\'ombre d\'un grand rocher dans une contrée aride;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'et les yeux des Voyants ne seront plus aveugles, et les oreilles des auditeurs seront attentives;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'et le cœur des hommes légers sera avisé pour comprendre, et la langue des bègues habile à parler nettement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'L\'impie ne sera plus appelé noble, ni le fourbe nommé magnanime;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'car l\'impie profère l\'impiété et son cœur pratique le mal pour commettre l\'impiété, et pour tenir contre l\'Éternel le langage de l\'erreur, pour laisser à vide l\'âme de l\'affamé, et manquer de breuvage celui qui est altéré;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'et les armes du fourbe sont funestes, il médite la fraude pour perdre le misérable par des discours menteurs, quand bien même l\'indigent expose son droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Mais le noble pense à ce qui est noble, et dans ce qui est noble il se maintient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Femmes insouciantes, debout! entendez ma voix! filles qui vous rassurez, écoutez mes discours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Dans l\'an et jours vous tremblerez, vous qui vous rassurez; car c\'en est fait de la vendange, et la récolte des fruits n\'arrivera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Ayez de l\'effroi, insouciantes! tremblez, vous qui vous rassurez! déshabille-toi, ôte tes vêtements et ceins tes reins [du cilice]!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'On gémit, en se frappant le sein, sur les campagnes délicieuses et sur la vigne féconde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Sur le sol de mon peuple poussent les ronces et les épines, oui, dans toutes les maisons où est la joie, dans la ville où est la gaieté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'car le palais est abandonné et la cité bruyante est solitaire; la colline et la tour seront pour longtemps parmi les cavernes, la joie des onagres, le pacage des troupeaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'jusqu\'à ce que sur nous l\'esprit soit répandu d\'en haut, et que le désert devienne un verger, et que le verger soit estimé à l\'égal de la forêt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Alors dans le désert habitera la justice, et l\'équité dans le verger aura son séjour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'et l\'effet de la justice sera la paix, le fruit de la justice le repos et la sécurité éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Et mon peuple habitera une demeure de paix, et des domiciles assurés, et des lieux tranquilles et sûrs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Mais il grêlera à la chute de la forêt, et la ville ennemie s\'abîmant croulera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Heureux vous qui semez dans un sol arrosé, et laissez sans entraves le pied du bœuf et de l\'âne!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Malheur à toi, dévastateur, qui n\'as pas encore été dévasté, et spoliateur, qu\'on n\'a pas dépouillé! Quand tu auras achevé tes ravages, tu seras ravagé; quand tu auras fini de dépouiller, on te dépouillera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Éternel, sois-nous propice, nous nous attendons à toi! sois notre bras chaque matin, et notre aide au temps de la détresse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'A ta voix tonnante les peuples fuient, à ton lever les nations se dissipent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'On ramasse votre butin, comme ramasse la sauterelle; on s\'y précipite, comme la locuste se précipite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'L\'Éternel est élevé, car Il habite les lieux très-hauts, Il remplit Sion de justice et d\'équité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Et ce sera la sécurité de tes jours; la sagesse et la science sont une riche source de salut; et la crainte de l\'Éternel, c\'est là son trésor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Voici, leurs guerriers poussent des cris au dehors; les messagers de paix pleurent amèrement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Les chemins sont désolés; on cesse de pratiquer les sentiers. Il rompt l\'alliance, méprise les villes, et ne fait aucun cas des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Le pays est en deuil et languit; le Liban est confus, dans la douleur; Saron ressemble au désert, Basan et le Carmel perdent leurs feuilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Maintenant je vais me lever, dit l\'Éternel, maintenant me dresser, maintenant m\'élever.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Dans vos flancs vous portez du foin, et vous enfanterez de la balle; votre souffle est un feu qui vous consumera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Et les peuples seront embrasés, calcinés; ronces coupées, ils brûleront au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Écoutez, peuples lointains, ce que j\'ai fait, et vous qui êtes près, connaissez ma puissance!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'En Sion les pécheurs tremblent, le frisson saisit les impies. « Qui de nous tiendra devant le feu consumant? qui de nous tiendra devant les flammes éternelles? » –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Celui qui est dans la voie de la justice, et qui parle selon la droiture, qui méprise les gains extorqués, qui secoue sa main pour ne point recevoir de dons corrupteurs, qui se bouche les oreilles pour n\'être point complice de meurtres et qui ferme ses yeux pour ne point voir le mal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'celui-là habitera un séjour éminent, des rochers fortifiés seront sa citadelle, son pain lui sera donné et son eau ne tarira pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Tes yeux contempleront le Roi dans sa beauté, ils verront des pays lointains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Ton cœur se rappellera le temps de la terreur. « Où est celui qui tenait le registre? où, celui qui tenait la balance? où, celui qui inspectait les tours? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Tu ne verras plus le peuple cruel, le peuple au langage obscur que l\'on n\'entend pas, à la langue bégayante que l\'on ne comprend pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Contemple Sion, la ville de nos fêtes! Tes yeux verront Jérusalem un séjour tranquille, une tente qu\'on ne lève plus, dont les pieux ne sont plus arrachés, dont nulle corde n\'est détachée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Car là l\'Éternel dans sa magnificence nous tient lieu de rivières, de larges fleuves; un vaisseau à rames n\'oserait y passer, un navire puissant n\'oserait y voguer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Car l\'Éternel notre juge, l\'Éternel notre législateur, l\'Éternel notre Roi est celui qui nous sauve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Tes cordes sont lâches, ne tiennent point leur mât ferme, ni les voiles tendues. Alors le butin et les dépouilles en abondance sont partagés, [même] les boiteux prennent part au pillage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'et aucun habitant ne dit: « Je suis malade! » Au peuple qui y habite, le péché est pardonné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Approchez, peuples, pour entendre, et vous, nations, écoutez! Que la terre écoute et tout ce qu\'elle enserre, le monde et toutes ses productions!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Car l\'Éternel est irrité contre toutes les nations, et courroucé contre toute leur armée; Il les dévoue et Il les livre au carnage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Leurs morts sont jetés, et de leurs cadavres s\'exhale la puanteur, et les montagnes ruissellent de leur sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Toute l\'armée des Cieux se dissout, et comme un volume les Cieux sont roulés, et toute leur armée tombe, comme du cep la feuille flétrie, comme du figuier la dépouille flétrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Car mon épée s\'est enivrée dans les Cieux: voici, elle va fondre sur Edom et sur le peuple que j\'ai dévoué, pour le jugement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'L\'épée de l\'Éternel est pleine de sang, engraissée de la graisse du sang des agneaux et des boucs, de la graisse du dos des béliers. Car il y a en Botsra un sacrifice de l\'Éternel, et une grande boucherie dans le pays d\'Edom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Et avec eux y tombent les buffles et les taureaux avec les bœufs, et leur pays s\'abreuve de sang, et leur sol aura la graisse pour engrais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Car l\'Éternel aura une journée de vengeance, une année de représailles pour venger Sion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Et ses rivières seront changées en poix, et son sol en soufre, et son pays deviendra une poix brûlante:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'ni nuit ni jour elle ne s\'éteindra, éternellement sa fumée montera; d\'âge en âge elle sera désolée; jamais dans aucun temps il n\'y aura de passants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Elle sera occupée par le pélican et le hérisson, le héron et le corbeau l\'habiteront; on y étendra le cordeau du ravage et le niveau de la désolation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Ses grands! il n\'y en a plus pour proclamer un roi, et c\'en est fait de tous ses princes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Et les épines grimpent dans ses palais, les orties et les ronces dans ses forts; et elle est un gîte pour les chacals, un parc pour les autruches:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'c\'est le rendez-vous des bêtes du désert et des loups, et les satyres y viennent au-devant l\'un de l\'autre, elle n\'est le séjour que du spectre de la nuit qui y trouve son lieu de repos.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Là niche le serpent-dard, et il y pond: il fait éclore et couve ses petits à son ombre; des vautours seuls s\'y réunissent l\'un avec l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Cherchez dans le livre de l\'Éternel et lisez! aucun d\'eux n\'y manquera, l\'un ne regrettera point l\'absence de l\'autre; car c\'est ma bouche qui l\'ordonne et mon esprit qui les réunira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Et Il tire au sort pour eux, et sa main leur partage ce pays au cordeau; éternellement ils l\'occuperont et d\'âge en âge y feront leur séjour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Le désert et la terre aride sont dans la joie, et la steppe dans l\'allégresse, et elle fleurit comme le narcisse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'elle se couvre de fleurs et se réjouit heureuse et triomphante; la gloire du Liban lui est donnée, la magnificence du Carmel et de Saron; ils voient la gloire de l\'Éternel, la magnificence de notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Fortifiez les mains lâches, et affermissez les genoux chancelants!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Dites aux cœurs alarmés: « Courage! soyez sans peur! voici votre Dieu, la vengeance approche, représaille de Dieu; Il vient et vous sauvera. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Alors s\'ouvriront les yeux des aveugles, et les oreilles des sourds seront ouvertes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'alors comme un cerf le perclus bondira, et la langue du muet chantera, car les eaux jaillissent dans le désert et des ruisseaux dans la plaine aride.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Le mirage des sables devient un vrai lac, et la terre desséchée des sources d\'eaux: dans le gîte des chacals où est leur repaire, sera un parc pour le jonc et le roseau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Et il y aura une route et une chaussée, et elle s\'appellera la Voie sainte; nul impur n\'y passera; elle sera pour eux seuls; qui suivra cette route, même un insensé, ne pourra s\'égarer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Là point de lion; nulle bête féroce n\'y mettra le pied; il ne s\'y en trouvera point; les délivrés y marcheront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Et les rachetés de l\'Éternel reviendront et s\'avanceront vers Sion avec chant de triomphe, et une joie éternelle couronnant leur tête: le bonheur et la joie viendront au-devant d\'eux, et le chagrin et les soupirs fuiront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Et il arriva, la quatorzième année du roi Ézéchias, que Sanchérib, roi d\'Assyrie, s\'avança sur toutes les villes fortes de Juda et s\'en empara.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Et le roi d\'Assyrie envoya Rabsaké de Lachis à Jérusalem contre le roi Ézéchias avec de grandes forces: et il fit halte à l\'aqueduc de l\'étang supérieur sur le chemin du champ du foulon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Alors vinrent à lui Eliacim, fils de Hilkia, préfet du palais, et Sebna le secrétaire, et Joach, fils d\'Asaph, le chancelier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Et Rabsaké leur dit: Dites à Ézéchias: Ainsi parle le Grand Roi, le roi d\'Assyrie: Qu\'est-ce que cette confiance que tu montres?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Je te le dis, purs vains discours que de parler de tes moyens et de tes forces pour la guerre. Eh bien! dans qui te confies-tu, pour t\'être révolté contre moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Voici, tu te confies dans l\'appui de ce roseau cassé, dans l\'Egypte, qui pénètre et perce la main de quiconque s\'y appuie; tel est Pharaon, roi d\'Egypte, pour tous ceux qui se confient en lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Et si tu me dis: C\'est dans l\'Éternel notre Dieu que nous nous confions! N\'est-ce pas lui, [te répondrai-je], dont Ézéchias a détruit les hauts lieux et les autels, et a dit à Juda et à Jérusalem: C\'est devant cet autel que vous adorerez?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Et maintenant, fais donc un défi à mon maître, le roi d\'Assyrie, et je te donnerai deux mille chevaux, si tu peux te donner les cavaliers pour les monter!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Et comment repousserais-tu un seul général, l\'un des moindres serviteurs de mon maître?... Ainsi tu mets ta confiance dans l\'Egypte pour les chars et la cavalerie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Et puis, est-ce malgré l\'Éternel que j\'ai marché contre ce pays afin de le ravager? L\'Éternel m\'a dit: Marche contre ce pays et ravage-le!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Et Eliacim et Sebna et Joach dirent à Rabsaké: Parle donc à tes serviteurs en syriaque, car nous le comprenons, et ne nous parle pas en hébreu aux oreilles du peuple qui est sur la muraille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Et Rabsaké dit: Est-ce à ton Seigneur et à toi que mon Seigneur m\'a envoyé pour dire ces paroles? N\'est-ce pas plutôt à ces hommes assis sur la muraille, pour se nourrir de leurs excréments et s\'abreuver de leur urine avec vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Alors Rabsaké s\'approcha, et criant à haute voix il dit en hébreu: Écoutez les paroles du Grand Roi, du roi d\'Assyrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Ainsi parle le Roi: Ne vous laissez pas abuser par Ezéchias, car il est incapable de vous sauver,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'et ne vous laissez pas inspirer par Ézéchias de la confiance en l\'Éternel, quand il dit: L\'Éternel nous sauvera! cette ville ne sera pas livrée aux mains du roi d\'Assyrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'N\'écoutez pas Ézéchias! Car ainsi parle le roi d\'Assyrie: Faites la paix avec moi, et rendez-vous à moi et vous vous nourrirez chacun de sa vigne et chacun de son figuier, et vous boirez chacun l\'eau de sa citerne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'jusqu\'à ce que je vienne et vous emmène dans un pays pareil à votre pays, pays de blé et de moût, pays de pain et de vignoble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Ne vous laissez pas séduire par Ézéchias, quand il vous dit: L\'Éternel nous sauvera! Les dieux des nations ont-ils chacun d\'eux sauvé son pays de la main du roi d\'Assyrie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Où sont les dieux de Hamath et d\'Arpad? Où les dieux de Sepharvaïm?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'et est-ce qu\'ils ont sauvé Samarie de ma main? De tous les dieux de ces pays lequel est-ce qui a sauvé son pays de ma main, que l\'Éternel doive sauver Jérusalem de ma main? –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Alors ils se turent et ne lui répondirent mot: car c\'était l\'ordre du Roi qui avait dit: Vous ne lui répondrez pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Et Eliacim, fils de Hilkia, préfet du palais, et Sebna le secrétaire, et Joach, fils d\'Asaph, le chancelier, vinrent auprès d\'Ézéchias, les habits déchirés, et lui rapportèrent les discours de Rabsaké.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Et quand le roi Ézéchias ouït ces choses, il déchira ses vêtements et se couvrit du cilice, et se rendit à la maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Et il envoya Eliacim, préfet du palais, et Sebna le secrétaire, et les plus anciens des sacrificateurs, couverts de cilices, auprès d\'Ésaïe le prophète, fils d\'Amots.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Et ils lui dirent: Ainsi parle Ézéchias: Ce jour est un jour de détresse et de châtiment et d\'opprobre, car les enfants sont venus jusqu\'au moment de naître, et il n\'y a pas de force pour enfanter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Peut-être l\'Éternel ton Dieu prendra-t-il garde aux paroles de Rabsaké envoyé par le roi d\'Assyrie, son maître, pour insulter au Dieu vivant, et tirera-t-Il vengeance des paroles qu\'a entendues l\'Éternel ton Dieu. Élève donc tes prières en faveur des restes encore existants du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'C\'est ainsi que les serviteurs du roi Ézéchias vinrent auprès d\'Ésaïe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Et Ésaïe leur dit: Ainsi parlez à votre Seigneur: Ainsi parle l\'Éternel: N\'aie point peur des paroles que tu as entendues, par lesquelles m\'ont insulté les valets du roi d\'Assyrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Voici, je lui communiquerai un esprit, et à l\'ouïe d\'une nouvelle il retournera dans son pays, et je l\'abattrai par l\'épée dans son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Et Rabsaké s\'en retourna, et il trouva le roi d\'Assyrie assaillant Libna; car il avait appris qu\'il avait quitté son campement de Lachis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Alors il ouït dire de Thiraca, roi d\'Ethiopie: Il s\'est mis en campagne pour te combattre. A cette nouvelle il envoya des députés à Ézéchias, leur disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Ainsi vous parlerez à Ézéchias, roi de Juda, disant: Ne sois pas la dupe de ton Dieu, en qui tu te confies, disant: Jérusalem ne sera point livrée aux mains du roi d\'Assyrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Voici, tu as appris ce que les rois d\'Assyrie ont fait à tous les pays, comment ils les ont exterminés; et toi, tu resterais sain et sauf?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Les dieux des nations que mes pères ont détruites, les ont-ils sauvées, Gozan et Haran, et Retseph et les enfants d\'Eden en Thelassar?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Où est le roi de Hamath, et le roi d\'Arpad, et le roi de la ville de Sepharvaïm, Héna et Ivva?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Et Ézéchias prit la lettre de la main des députés, et la lut, et monta à la maison de l\'Éternel; et Ézéchias la déploya devant l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Et Ézéchias invoqua l\'Éternel et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Éternel des armées, Dieu d\'Israël, dont le trône est sur les Chérubins, seul tu es le Dieu de tous les empires de la terre, c\'est toi qui as fait les Cieux et la terre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Éternel, incline ton oreille et écoute! Éternel, ouvre ton œil et vois! et entends toutes les paroles que Sanchérib nous adresse pour insulter au Dieu vivant!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Il est vrai, Éternel! les rois d\'Assyrie ont dévasté tous les pays et leur propre pays,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'et ils ont jeté leurs dieux au feu, car ils ne sont pas dieux, mais l\'œuvre des mains de l\'homme, du bois et de la pierre; et ils les ont anéantis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Mais maintenant, Éternel notre Dieu, sauve-nous de sa main, afin que tous les empires de la terre reconnaissent que seul tu es l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Alors Ésaïe, fils d\'Amots, envoya à Ézéchias pour lui dire: Ainsi parle l\'Éternel, Dieu d\'Israël: Sur la prière que tu m\'as faite au sujet de Sanchérib, roi d\'Assyrie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'voici la parole que prononce l\'Éternel sur lui: « La vierge fille de Sion te méprise et te raille, et la fille de Jérusalem hoche la tête derrière toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Qui as-tu insulté et outragé? et contre qui as-tu élevé la voix? Tu as porté avec hauteur tes yeux sur le Saint d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Par tes serviteurs tu as insulté le Seigneur et tu as dit: Avec mes chars nombreux je gravirai les sommets des montagnes, les retraites du Liban, et je couperai ses cèdres élevés, l\'élite de ses cyprès, et j\'atteindrai le haut de sa dernière cime, les bois de son bocage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Je ferai des puits et en boirai l\'eau, et sous les pas de mes pieds je dessécherai tous les fleuves de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'N\'as-tu pas appris que dès les temps reculés j\'opère ces choses, et qu\'aux jours d\'autrefois j\'en ai formé le plan? Et maintenant, j\'ai fait arriver que tu fusses un destructeur, qui réduit les villes fortes en ruines désolées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'et leurs habitants débiles sont épouvantés et confondus, ils sont comme l\'herbe des champs, comme la verdure de la plante, comme le gazon des toits, comme un blé encore sans tige.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Mais je te suis, quand tu t\'assieds, et quand tu te mets en marche, et quand tu arrives, et quand tu t\'emportes contre moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Parce que tu t\'emportes contre moi, et que ton insolence est venue à mon oreille, je mettrai mon anneau dans ta narine, et mon mors entre tes lèvres, et je te ramènerai par le chemin par lequel tu es venu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Et que ceci soit un signe pour toi: Une année vous mangerez le recru du blé, et la seconde année un grain spontané, et la troisième année vous sèmerez et moissonnerez, vous planterez des vignes et en mangerez le fruit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'et dès lors les réchappés de la maison de Juda, les survivants pousseront des racines en bas et porteront du fruit en haut;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'car de Jérusalem il sortira un reste, et de la montagne de Sion des réchappes; le zèle de l\'Éternel des armées opérera ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Aussi, ainsi prononce l\'Éternel sur le roi d\'Assyrie: Il ne pénétrera point dans cette ville, et n\'y décochera point de flèches, et il ne lui présentera aucun bouclier, et n\'élèvera point de terrasse contre elle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'le chemin qu\'il a pris, il le reprendra, et dans cette ville il ne pénétrera point, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Car je protège cette ville, afin de la sauver pour l\'amour de moi, et pour l\'amour de David, mon serviteur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Et l\'ange de l\'Éternel sortit et frappa dans le camp des Assyriens cent quatre-vingt-cinq mille hommes; et au lever, le matin, tous ils étaient des cadavres sans vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Alors Sanchérib, roi d\'Assyrie, se mit en marche et partit, et il s\'en revint et demeura à Ninive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Et comme il était prosterné dans le temple de Nisroch, son Dieu, Adrammélech et Scharetser, ses fils, le frappèrent de l\'épée; puis ils s\'enfuirent au pays d\'Ararat. Et Asarhaddon son fils le remplaça comme roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'En ce temps-là Ézéchias fut malade à mourir. Alors Ésaïe le prophète, fils d\'Amots, vint auprès de lui, et lui dit: Ainsi parle l\'Éternel: Donne tes ordres à ta maison, car tu vas mourir et tu ne vivras plus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Alors Ézéchias tourna son visage contre la paroi, et fit sa prière à l\'Éternel, et il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'Ah! Éternel! souviens-toi-donc que j\'ai marché devant toi avec fidélité et avec l\'intégrité du cœur, et que j\'ai fait ce qui est bien à tes yeux. Et Ézéchias pleura beaucoup.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Alors la parole de l\'Éternel fut adressée à Ésaïe en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Va, et dis à Ézéchias: Ainsi parle l\'Éternel, Dieu de David ton père: J\'ai entendu ta prière, j\'ai vu tes larmes; voici, j\'ajoute à tes jours encore quinze années;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'et je te sauverai, ainsi que cette ville, de la main du roi d\'Assyrie, et je protégerai cette ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Et que ceci te soit un signe de par l\'Éternel que l\'Éternel fera ce qu\'il a dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Voici, je ferai rétrograder, de dix degrés en arrière, l\'ombre des degrés descendue sur les degrés d\'Achaz par l\'effet du soleil. – Et le soleil rétrograda de dix degrés dont il était descendu sur les degrés d\'Achaz.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Hymne d\'Ézéchias, Roi de Juda, quand ayant été malade il guérit de sa maladie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, '« Je disais: Quand mes jours sont tranquilles, je descends donc aux portes des Enfers, privé du reste de ma vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Je disais: Je ne verrai plus l\'Éternel, l\'Éternel sur la terre des vivants, je ne verrai plus les hommes, désormais réuni aux habitants du séjour silencieux:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'ma loge est enlevée et emportée loin de moi comme la tente du berger, je tranche ma vie comme un tisserand, des lisses Il me détache, du jour à la nuit tu en finis avec moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'J\'attendis jusqu\'au matin; pareil au lion, Il brisa tous mes os; du jour à la nuit tu en finis avec moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Comme l\'hirondelle ou la grue je gémissais, je me lamentais comme la tourterelle, mes yeux s\'épuisaient à regarder en haut: « Éternel, je suis dans l\'angoisse, sauve-moi!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Que dirai-je? Il m\'a promis, et Il a exécuté. Humblement je marcherai durant toutes mes années, après ce tourment de mon âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Seigneur, c\'est par là qu\'on vit! c\'est tout cela qui fait la vie de mon esprit; tu me fortifieras! et accorde-moi la vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Voici, en salut mes tourments sont changés! dans ton amour tu tiras mon âme de la fosse du néant, car tu jetas derrière toi tous mes péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Car l\'Enfer ne te loue pas, la mort ne te célèbre pas, les hommes descendus dans la fosse n\'espèrent pas dans ta fidélité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'C\'est le vivant, le vivant qui te loue, comme moi en ce jour; le père aux enfants redit ta fidélité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'L\'Éternel me sauve, et nous ferons résonner les cordes de nos lyres tous les jours de notre vie dans la maison de l\'Éternel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Et Ésaïe dit qu\'on apportât un gâteau de figues, et qu\'on les appliquât pressées sur la plaie, pour qu\'il guérît.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Et Ézéchias dit: A quel signe saurai-je que je monterai à la maison de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'En ce même temps Mérodach Baladan, fils de Baladan, roi de Babel, envoya une lettre et des présents à Ézéchias, ayant appris qu\'il avait été malade et qu\'il était guéri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Et Ézéchias se réjouit de les voir, et il leur montra son trésor, l\'argent et l\'or, et les parfums, et l\'huile fine, et tout son arsenal, et tout ce qui se trouvait dans ses trésors; il n\'y eut rien qu\'Ézéchias ne leur montrât dans sa maison et dans tout son royaume.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Alors Ésaïe le prophète vint vers le roi Ézéchias et lui dit: Qu\'ont dit ces hommes, et d\'où sont-ils venus chez toi? Et Ézéchias dit: Ils sont venus chez moi d\'un pays lointain, de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Et il dit: Qu\'ont-ils vu dans ta maison? Et Ézéchias dit: Tout ce qui est dans ma maison, ils l\'ont vu, il n\'y a rien dans mes trésors que je ne leur aie montré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Alors Ésaïe dit à Ézéchias: Écoute la parole de l\'Éternel des armées:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Voici, des jours viennent où sera emmené à Babel tout ce qui est dans ta maison, et ce que tes pères ont amassé jusqu\'à ce jour: il ne restera rien, dit l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'et d\'entre les fils qui naîtront de toi et que tu engendreras, ils en prendront pour être eunuques dans le palais du roi de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Et Ézéchias dit à Esaïe: Il y a de la bonté dans la parole de l\'Éternel, que tu m\'annonces. Car, dit-il, il y aura prospérité et permanence durant ma vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Consolez, consolez mon peuple! dit votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Parlez au cœur de Jérusalem, et criez-lui que son service est fini, que son crime est acquitté, qu\'elle a reçu de la main de l\'Éternel au double de tous ses péchés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Une voix crie: Dans le désert préparez le chemin de l\'Éternel, aplanissez dans la steppe aride une route pour notre Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Que toute vallée soit exhaussée, et que toute montagne et toute colline soient abaissées! que le sol raboteux devienne un sol uni, et toute aspérité un terrain aplani!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Et la gloire de l\'Éternel se révélera, et toute chair dans le même instant verra que la bouche de l\'Éternel a parlé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Une voix dit: « Proclame! » Et l\'on dit: « Que proclamerai-je? » – « Toute chair est une herbe, et toute sa grâce comme la fleur des champs:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'l\'herbe sèche, la fleur se fane, quand du souffle de l\'Éternel elle est atteinte, (oui, le peuple est une herbe!)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'l\'herbe sèche, la fleur se fane, mais la parole de notre Dieu demeure éternellement. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Monte sur une haute montagne, Sion, messagère de paix! élève avec force ta voix, Jérusalem, messagère de paix! élève-la, ne crains pas! dis aux villes de Juda:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, '« Voici votre Dieu! » Voici, le Seigneur, l\'Éternel arrive en héros, et son bras commande pour lui; voici, ses récompenses l\'accompagnent, et ses rétributions le précèdent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Comme un berger Il fera paître son troupeau, dans ses bras Il recueillera les agneaux, et dans son sein les portera; Il conduira les mères qui allaitent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Qui mesura les eaux dans le creux de sa main, et de l\'empan prit les dimensions des Cieux, et ramassa dans un setier la poudre de la terre, et pesa les montagnes à la balance et les collines dans les bassins?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Qui a dirigé l\'esprit de l\'Éternel, et qui fut son conseiller pour l\'enseigner?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Qui consulta-t-Il pour en être éclairé? et qui L\'instruisit dans la voie de ce qui est juste, et L\'instruisit dans la science, et Lui montra le chemin de l\'intelligence?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Voici, des peuples sont comparables à une goutte qui pend à un seau, et à une poussière sur une balance, et Il soulève des îles comme la menue poussière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Et le Liban ne suffit pas au feu, ni son gibier aux holocaustes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Tous les peuples sont devant Lui comme s\'ils n\'étaient pas, Il les regarde comme un néant et une vanité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Et à qui pourriez-vous assimiler Dieu? et quelle image feriez- vous son égale?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Un ouvrier fond une idole, et un orfèvre la plaque d\'or, et y soude des chaînettes d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Le pauvre borné dans ses dons choisit un bois qui ne pourrisse pas, il se procure un habile ouvrier pour fabriquer une image qui ne branle pas. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Ne le savez-vous pas? ne l\'avez-vous pas appris? Cela ne vous fut-il pas annoncé dès l\'origine? Ne prîtes-vous jamais garde à la fondation de la terre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'C\'est Lui qui a son trône au-dessus du disque de la terre, dont les habitants sont comme des sauterelles; qui déroule les Cieux comme une tenture, et les déploie comme un pavillon pour y loger;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'qui réduit les princes au néant, et fait des juges de la terre une vanité:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'à peine sont-ils plantés, à peine sont-ils semés, à peine leur tige a-t-elle pris racine en terre, qu\'il souffle sur eux, et ils sèchent, et une tempête les emporte comme la balle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'Et à qui m\'assimilerez-vous, pour que je lui ressemble? dit le Saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Levez vos yeux en haut, et regardez! Qui les a créés? Il fait avancer leur armée tout entière, les appelle tous par leur nom; si grand est son pouvoir, et si puissante est sa force, que pas un ne fait défaut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Pourquoi dis-tu, Jacob, et parles-tu ainsi, Israël: « Mes destinées échappent à l\'Éternel, et mon droit passe inaperçu devant mon Dieu! » Ne le sais-tu pas? ou ne l\'as-tu pas appris?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Il est un Dieu pour tous les temps, l\'Éternel, créateur des extrémités delà terre; Il ne se fatigue, ni ne s\'épuise; on ne saurait sonder son intelligence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Il redonne des forces à celui qui est fatigué, et Il redouble la vigueur de celui qui est défaillant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'La jeunesse se fatigue et s\'épuise, et les guerriers d\'élite chancellent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'mais ceux qui se confient en l\'Éternel, reçoivent de nouvelles forces, ils prennent leur vol comme l\'aigle; ils courent et ne se fatiguent point, ils vont et ne s\'épuisent point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'En silence, Îles, écoutez-moi! et que les peuples raniment leur force! qu\'ils s\'approchent et parlent! ensemble nous allons engager le débat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Qui de l\'Orient a fait surgir celui dont la justice accompagne les pas? qui lui a livré les nations et assujetti des rois, de leur épée a fait comme une poussière, et de leur arc comme une balle emportée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Il les poursuit et parcourt sain et sauf le chemin où son pied n\'avait jamais marché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Qui l\'a fait et exécuté? Celui qui dès l\'origine appela les générations, moi l\'Éternel, qui suis le premier et qui demeure le même dans les derniers âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Les Îles le voient, et sont craintives, les extrémités de la terre tremblent: ils s\'approchent, ils viennent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Ils s\'aident l\'un l\'autre; chacun dit à son frère: « Courage! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Le forgeron encourage le fondeur, l\'ouvrier qui polit au marteau celui qui bat l\'enclume; il dit de la soudure: « Elle est bonne! » et il le fixe avec des clous, de peur qu\'il ne bouge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Mais toi, Israël, mon serviteur, Jacob dont j\'ai fait choix, race d\'Abraham mon ami,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'toi que j\'ai été prendre au bout de la terre, et que j\'ai appelé de son extrémité, à qui j\'ai dit: Tu es mon serviteur; je te choisis, et ne te rejette point!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Ne crains point, car je suis avec toi! ne t\'épouvante point, car je suis ton Dieu, je te fortifie, je te suis en aide, et te soutiens de mon bras sauveur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Voici, ils seront confus et honteux, tous tes furieux ennemis; ils seront comme n\'étant pas; ils périront, les hommes animés contre toi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'tu les chercheras et ne les trouveras plus, ceux qui te cherchaient querelle; ils seront comme rien et comme le néant, les hommes qui te livraient la guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Car c\'est moi, l\'Éternel, ton Dieu, qui te prends par la main, qui te dis: Ne crains point, je suis ton aide!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Ne crains point, vermisseau de Jacob, petit reste d\'Israël! je suis ton aide, dit l\'Éternel, et le Saint d\'Israël est ton vengeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Voici, je fais de toi un traîneau tranchant et neuf, armé de doubles lames; tu tritureras, pulvériseras les montagnes, et réduiras les collines en paille menue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Tu les vanneras et le vent les emportera, et l\'ouragan les dissipera; mais l\'Éternel sera ta joie, et le Saint d\'Israël ta gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Les malheureux et les indigents cherchent de l\'eau, et il n\'y en a pas; leur langue est desséchée par la soif; moi, l\'Éternel, je les exaucerai, Dieu d\'Israël je ne les abandonnerai pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Sur les coteaux nus je ferai jaillir des fleuves, et des sources au milieu des vallons, je changerai le désert en un lac et la terre aride en sources d\'eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Je mettrai au désert le cèdre, l\'acacia, et le myrte et l\'olivier; je planterai dans les lieux incultes le cyprès, le platane et le mélèze réunis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'afin qu\'ils voient, et qu\'ils sachent, et qu\'ils remarquent, et qu\'ils sentent tous que la main de l\'Éternel a fait ces choses, et que le Saint d\'Israël en est l\'auteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Alléguez vos moyens, dit l\'Éternel! produisez vos arguments, dit le Roi de Jacob!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Qu\'ils les produisent et nous disent ce qui doit arriver! Les premières prédictions, que furent-elles? Dites-le, afin que nous y prenions garde, et que nous en observions l\'issue; ou, annoncez-nous l\'avenir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Dites les événements des temps futurs, afin que nous reconnaissions que vous êtes des dieux! Faites quelque chose en bien ou en mal, afin que nous nous en étonnions ensemble et que nous le voyions!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Voici, vous n\'êtes rien, et votre œuvre est le néant: abominable est quiconque fait choix de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Je le fis surgir du nord, et il vint de l\'orient, celui qui invoquera mon nom, et il marche sur les princes comme sur l\'argile, comme un potier foule la glaise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Qui l\'a annoncé dès le commencement, pour que nous le sachions? et dès longtemps, pour que nous disions: « C\'est vrai »? Personne ne l\'a annoncé, personne ne l\'a prédit, personne n\'a entendu vos paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Le premier à Sion j\'ai dit: Voilà, les voilà! et à Jérusalem j\'ai donné un message de paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Je regarde, et personne n\'est là; parmi eux, pas un conseiller que je puisse interroger et qui puisse répondre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Voici, tous ils ne sont rien, leurs œuvres sont un néant et leurs idoles un souffle vain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Voici mon serviteur que je soutiens, mon élu en qui mon âme prend plaisir: je mets mon esprit sur lui; il montrera la justice aux nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Il ne crie point, il n\'élève point la voix, et ne la fait point retentir dans les rues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Il ne brise point le roseau cassé, et n\'éteint point le lumignon qui fume encore, selon la vérité il montrera la justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Il ne se ralentit ni ne se précipite, jusqu\'à ce qu\'il ait établi la justice sur la terre, et les îles sont dans l\'attente de sa loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Ainsi parle le Dieu, l\'Éternel, qui créa les Cieux et les déploya, qui étendit la terre avec ses productions, qui mit un souffle dans le peuple qu\'elle porte et un esprit dans ceux qui y marchent:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Moi, l\'Éternel, je t\'appelle en ma grâce, et te prends par la main, je veux te garder, et te faire le médiateur de l\'alliance de mon peuple et la lumière des nations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'pour ouvrir les yeux aveugles, pour tirer de prison les captifs, et du cachot les habitants des ténèbres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Je suis l\'Éternel, c\'est là mon nom, et je ne donne ma gloire à nul autre, ni mon honneur aux idoles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Voici, les premiers oracles se sont accomplis, et j\'annonce des choses nouvelles; avant qu\'elles germent, je vous les indique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Chantez à l\'Éternel un cantique nouveau, et sa louange au bout de la terre, vous qui voguez sur la mer, et vous, les êtres qu\'elle enserre, îles et hommes qui les habitez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Que le désert et ses villes, et les campements habités par Cédar élèvent la voix! qu\'ils chantent, les habitants des rochers, et que de la cime des montagnes partent des acclamations!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Qu\'on rende gloire à l\'Éternel, et que dans les îles on publie ses louanges!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'L\'Éternel s\'avance comme un héros, comme un homme de guerre ïl excite son ardeur, Il pousse un cri, et élève la clameur du combat, et contre ses ennemis Il montre sa force.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Dès longtemps je me suis tu, je me suis tenu en repos, je me suis contenu; comme la femme en travail je vais crier, pousser mon souffle et aspirer l\'air à la fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Je vais dévaster monts et coteaux, et sécher toute leur verdure; je changerai les fleuves en terre ferme, et mettrai les lacs à sec.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Et je ferai marcher des aveugles dans un chemin inconnu, et sur des sentiers inconnus je les mènerai, devant eux je changerai les ténèbres en clarté et les aspérités en plaine: ces choses je les ferai, et n\'y manquerai point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Alors reculeront et seront confus ceux qui se confient aux idoles, et disent aux images: Vous êtes nos dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Sourds, entendez! et vous, aveugles, regardez et voyez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Qui est aveugle, sinon mon serviteur, et sourd comme mon envoyé que je délègue? Qui est aveugle comme l\'ami de Dieu, et aveugle comme le serviteur de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Tu as vu beaucoup de choses, mais tu n\'y as pas pris garde; les oreilles étaient ouvertes, mais on n\'écoutait pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'L\'Éternel trouva bon, pour l\'amour de sa justice, de donner une loi grande et magnifique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Et cependant, c\'est un peuple pillé et dépouillé! on les a tous mis aux fers dans des fosses, et dans des cachots ils sont cachés, ils ont été livrés en proie, et point de Sauveur! au pillage, et personne qui dise: Restitue!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Qui parmi vous prêtera l\'oreille à ceci, pour entendre et écouter à l\'avenir?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Qui est-ce qui a livré Jacob au pillage et Israël aux spoliateurs? N\'est-ce pas l\'Éternel contre qui nous péchâmes, et dont ils ne voulurent ni suivre la voie, ni écouter la loi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Aussi a-t-il versé sur lui le feu de sa colère, et le poids de la guerre; elle l\'embrasa de toutes parts, et il ne comprit pas; elle le consuma, et il ne rentra point en lui-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Mais maintenant, ainsi parle l\'Éternel ton créateur, Jacob, et ton formateur, Israël: Ne crains point, car je te rachète, je t\'appelle par ton nom; tu es à moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Si tu traverses les eaux, je serai avec toi; et les fleuves, ils ne te submergeront pas; quand tu passeras par le feu, tu ne t\'y brûleras pas, et la flamme ne te consumera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Car je suis l\'Éternel, ton Dieu; le Saint d\'Israël est ton libérateur; je livre pour ta rançon l\'Egypte, l\'Ethiopie et Saba à ta place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Parce que tu as du prix à mes yeux, que je t\'estime et que je t\'aime, je livre des hommes à ta place, et des peuples en échange de ta vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Ne crains point, car je suis avec toi! du Levant je ramènerai ta race, et du Couchant je te recueillerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Je dis au septentrion: « Restitue! » et au midi: « Ne recèle pas! Ramène mes fils des pays lointains, et mes filles des bouts de la terre:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'tous ceux qui s\'appellent de mon nom, pour ma gloire je les ai créés, je les ai faits et les ai formés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'élargis le peuple aveugle qui a des yeux, et les sourds qui ont des oreilles! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Que toutes les nations s\'assemblent à la fois, et que les peuples se réunissent! Lequel d\'entre eux annoncerait ces choses? Qu\'ils nous fassent entendre les premières prédictions! qu\'ils produisent leurs témoins pour avoir gain de cause! sinon, qu\'ils écoutent, et qu\'ils disent: « C\'est vrai! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Vous êtes mes témoins, dit l\'Éternel, ainsi que le serviteur dont j\'ai fait choix, afin que vous soyez persuadés et me croyiez, et que vous sentiez que c\'est moi. Avant moi aucun Dieu ne fut formé, et après moi il n\'y en aura point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'C\'est moi, moi qui suis l\'Éternel, et hors moi il n\'y a point de Sauveur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'C\'est moi qui ai prédit et sauvé, et qui ai annoncé; et il n\'y avait parmi vous aucun [dieu] étranger! vous êtes donc mes témoins, dit l\'Éternel, et je suis Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Depuis qu\'il y a un temps, déjà je le suis, et personne ne sauve de ma main: ce que je fais, qui le retirera?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Ainsi parle l\'Éternel, votre rédempteur, le Saint d\'Israël: Pour l\'amour de vous j\'envoyai contre Babel, et je ferai embarquer tous les fugitifs et les Chaldéens sur les vaisseaux où ils chantent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Moi l\'Éternel, je suis votre Saint, le Créateur d\'Israël, votre Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Ainsi parle l\'Éternel, qui fraya dans la mer un chemin, et dans les eaux puissantes un sentier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'qui mit en campagne chars et chevaux, armée et héros (tous ensemble ils sont gisants, pour ne pas se relever; ils sont éteints, comme une mèche ils finirent):');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Ne pensez pas aux premiers temps, et à ce qui précéda n\'ayez point égard!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Voici, je vais faire des choses nouvelles; déjà elles germent: ne les connaîtrez-vous pas? Oui, je ferai passer une route dans le désert, et des fleuves dans la terre aride.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Les bêtes des champs, les chacals et les autruches me loueront, parce que j\'aurai mis des eaux dans le désert, et des fleuves dans la terre aride, pour abreuver mon peuple élu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Que le peuple que je me suis formé, redise mes louanges!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Et cependant, Jacob, tu ne m\'as pas invoqué, car tu t\'es lassé de moi, Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Tu ne m\'as pas offert tes agneaux en holocaustes, et par tes sacrifices tu ne m\'as pas glorifié; je ne t\'ai point tourmenté par les offrandes, ni fatigué par l\'encens;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'tu ne m\'as point à prix d\'argent acheté de roseau odorant, et de la graisse de tes victimes tu ne m\'as point rassasié; mais tu m\'as tourmenté par tes péchés, tu m\'as fatigué par tes crimes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Je veux, je veux effacer tes forfaits pour l\'amour de moi, et de tes péchés ne plus me souvenir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Aide ma mémoire! Engageons le débat! parle, afin que tu sois justifié!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Ton premier père pécha, et tes interprètes se rebellèrent contre moi:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'c\'est pourquoi j\'ai avili les princes du sanctuaire, et livré Jacob à la malédiction, et Israël aux outrages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Mais maintenant, écoute, O Jacob mon serviteur, et Israël dont j\'ai fait choix!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Ainsi parle l\'Éternel, ton créateur et ton formateur dès l\'origine de ta naissance, ton aide: Ne crains point, Jacob mon serviteur, et mon Israël dont j\'ai fait choix!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'car je répandrai des eaux sur le sol altéré, et des ruisseaux sur la terre sèche; je répandrai mon esprit sur ta race, et ma bénédiction sur tes rejetons,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'afin qu\'ils poussent parmi la verdure, comme des saules auprès des courants d\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'L\'un dira: « J\'appartiens à l\'Éternel! » et l\'autre se réclamera du nom de Jacob, et un autre mettra sur sa main la marque de l\'Éternel, et dira avec amour le nom d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Ainsi parle l\'Éternel, Roi d\'Israël et son Rédempteur, l\'Éternel des armées: Je suis le premier et le dernier, et hors moi il n\'y a point de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Et qui comme moi a fait des prophéties (qu\'on le dise et me le mette en avant!) depuis que je fondai le peuple éternel? Et qu\'ils annoncent l\'avenir et ce qui doit arriver!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Soyez sans crainte et sans peur! dès longtemps ne te l\'ai-je pas annoncé et déclaré? aussi bien vous êtes mes témoins! Y a-t-il un Dieu hors moi? Il n\'y a point de rocher, je n\'en connais aucun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Les faiseurs d\'idoles sont tous une vanité et leurs chefs-d\'œuvre ne servent à rien, ils sont leurs propres témoins: ils ne voient pas et n\'ont pas la connaissance, afin qu\'ils soient honteux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Qui forgerait un Dieu, ou fondrait une image, pour n\'en rien retirer?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Voici tous ceux qui y coopèrent, auront à rougir; et les ouvriers ne sont que des hommes: ils sont là réunis, debout, tremblants et confus tous ensemble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Le forgeron forge une hache et travaille au feu des charbons, et la façonne avec le marteau, et la travaille à force de bras; il a faim aussi, et n\'a plus de forces, il ne boit point d\'eau, et il est épuisé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Le charpentier étend un cordeau; et en fait le dessin avec le style, et la façonne avec le rabot, et en fait le tracé avec le compas; il lui donne ainsi une forme humaine, une belle figure d\'homme, digne d\'habiter un temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Il va se couper des cèdres, et prend un rouvre et un chêne, et fait un choix parmi les arbres de la forêt: il plante un pin, et la pluie le fait croître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Et l\'homme a de quoi brûler, et il en prend et se chauffe, et il en allume, et il cuit du pain. Il en fabrique aussi un Dieu, et il l\'adore, et en taille une image, et il s\'incline devant elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Il en brûle la moitié au feu, avec une moitié il apprête sa viande, rôtit son rôt, et se rassasie; il se chauffe aussi et dit: « Ah! ah! je me réchauffe! et je vois du feu! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Et avec le reste il fait un dieu, son idole, et il s\'incline devant elle, et il l\'adore, et lui adresse sa prière, et dit: « Sauve-moi, car tu es mon Dieu! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Ils n\'ont ni connaissance, ni intelligence; car leurs yeux sont bouchés et ils ne voient pas, et leur cœur fermé et ils ne sentent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Il ne réfléchit pas, il n\'a ni connaissance, ni intelligence pour dire: J\'en ai brûlé la moitié au feu, et sur ses charbons j\'ai aussi cuit mon pain, rôti ma viande, et l\'ai mangée, et avec le reste ferais-je une abomination, devant une souche de bois me prosternerais-je?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Il se repaît de cendres, un cœur abusé le détourne de sauver son âme et de dire: N\'est-ce pas un mensonge que je tiens dans ma main?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Souviens-t\'en, Jacob, et Israël! car tu es mon serviteur, je t\'ai formé; pour moi tu es un serviteur, Israël; tu ne seras pas oublié de moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Je balaie comme un nuage tes crimes, et comme une nuée tes péchés: reviens à moi, car je te rachète!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Cieux, retentissez de cantiques! car l\'Éternel a agi; et vous, profondeurs de la terre, éclatez en acclamations! poussez des cris de joie, montagnes, avec les forêts et tous les arbres qui y sont! car l\'Éternel rachète Jacob, et Il manifeste sa gloire sur Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Ainsi parle l\'Éternel qui te rachète, et te forma dès l\'origine de ta naissance: Je suis l\'Éternel qui a tout créé, qui seul déploya les Cieux, et qui de moi-même étendis la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'qui déjoue les présages des prophètes menteurs, et fais délirer les devins, qui fais reculer les sages, et change leur science en folie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'qui donne effet à la parole de mon serviteur, et accomplis les arrêts de mes envoyés, qui dis de Jérusalem: « Elle sera habitée, » et des villes de Juda: « Elles seront rebâties, et je relèverai leurs ruines! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'qui dis à l\'abîme: « Sèche, et je tarirai tes fleuves! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'qui dis de Coresch: « Il est mon berger, et il exécutera toute ma volonté! » et qui dis de Jérusalem: « Qu\'elle soit rebâtie! » et du Temple: « Qu\'il soit fondé »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Ainsi parle l\'Éternel à son Oint, à Coresch,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'que je tiens par sa droite pour terrasser les nations devant lui, et afin que je déceigne les reins des rois; pour ouvrir devant lui les portes, et afin que les entrées ne lui soient pas fermées: Je veux marcher devant toi et aplanir les aspérités, briser les portes d\'airain, et abattre les verrous de fer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'et je te livrerai les trésors des lieux sombres, et ce qui est enfoui dans l\'obscurité, afin que tu reconnaisses que je suis l\'Éternel qui t\'appelai par ton nom, le Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Pour l\'amour de mon serviteur Jacob et d\'Israël mon élu, je t\'appelai par ton nom, je te parlai avec bonté, et tu ne me connaissais pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Je suis l\'Éternel, et il n\'en est pas d\'autre; hors moi il n\'y a point de Dieu: je te ceignis moi-même et tu ne me connaissais pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'C\'est afin que du Levant et du Couchant on reconnaisse que hors moi il n\'y en a aucun: je suis l\'Éternel, et il n\'en est pas d\'autre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'celui qui produit la lumière et crée les ténèbres, qui fait le bonheur et crée le malheur; moi, l\'Éternel, je suis l\'auteur de tout cela.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Cieux, distillez d\'en haut, et que les nuées épanchent la grâce! que la terre s\'ouvre et produise le salut, et fasse germer la justice en même temps! c\'est moi, l\'Éternel, qui crée ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Malheur à qui dispute contre son créateur, têt parmi des têts de terre! L\'argile dit-elle à celui qui la façonne: « Que fais-tu » et ton œuvre dit-elle de toi: « Il n\'a point de mains »?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Malheur à qui dit à son père: « Pourquoi engendres-tu? » et à la femme: « Pourquoi enfantes-tu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Ainsi parle l\'Éternel, le Saint d\'Israël, et son créateur: Sur l\'avenir interrogez-moi! De mes enfants et de l\'œuvre de mes mains remettez-moi le-soin!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'C\'est moi qui ai fait la terre, et sur elle ai créé des hommes. C\'est par moi, par mes mains que furent étendus les Cieux, et j\'ordonnai toute leur armée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Je l\'ai suscité dans ma justice, et j\'aplanirai toutes ses voies; il relèvera ma cité et élargira mes captifs, non pas pour un prix ni pour une rançon, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Ainsi parle l\'Éternel: Les gains de l\'Égypte et les profits de l\'Ethiopie, et les Sabéens, hommes de haute taille, passeront chez toi et seront tiens! ils marcheront à ta suite, et s\'avanceront enchaînés, et ils s\'inclineront devant toi et te diront en suppliant: « Dieu ne se trouve que chez toi; il n\'y en a pas d\'autre; hors lui point de Dieu! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Certainement tu es un Dieu qui te caches, Dieu d\'Israël, qui sauves!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Ils sont tous confus et honteux, ensemble ils s\'en vont confondus, les fabricateurs d\'idoles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'L\'Éternel sauve Israël d\'un salut éternel; vous n\'aurez ni honte ni confusion dans tous les âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Car ainsi parle l\'Éternel, créateur des Cieux (Il est le Dieu formateur de la terre et son auteur, Il l\'a consolidée; Il ne la créa pas pour rien, Il la forma pour être habitée): Je suis l\'Éternel, et il n\'en est pas d\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Ce n\'est pas en cachette que j\'ai parlé, ni dans un lieu obscur de la terre! je ne dis pas à la race de Jacob: Cherchez-moi vainement! Moi, l\'Éternel, je dis la vérité, et parle avec droiture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Assemblez-vous et venez! approchez tous ensemble, réchappés des nations! Ils n\'ont pas de sens ceux qui vont portant ce bois, leur idole, et prient un Dieu qui ne peut secourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Exposez et alléguez! et qu\'ensemble ils se consultent! Qui est-ce qui annonça ces choses dès les temps anciens, en fit dès longtemps la prédiction? N\'est-ce pas moi, l\'Éternel? Et hors moi il n\'est point de Dieu, de Dieu juste et sauveur il n\'en est point d\'autre que moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Tournez-vous vers moi, et recevez le salut, vous toutes les extrémités de la terre! Car je suis Dieu et il n\'en est pas d\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Je le jure par moi-même, et de ma bouche sort la vérité, une parole qui ne sera point retirée, c\'est que tout genou fléchira devant moi, et toute langue me prêtera serment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Auprès de l\'Éternel seul, me dira-t-on, se trouvent justice et puissance; à lui viendront en rougissant tous ceux qui s\'irritaient contre lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'Toute la race d\'Israël par l\'Éternel sera justifiée, et mettra sa gloire en lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Bel est culbuté, Nebo précipité; on met leurs images sur des animaux et des bêtes; ceux que vous portiez chargent de leur poids des bestiaux fatigués!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Ils sont culbutés, précipités ensemble, et ne peuvent sauver le fardeau, et eux-mêmes ils s\'en vont captifs. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Écoutez-moi, maison de Jacob, et vous, tous les restes de la maison d\'Israël! je me suis chargé de vous dès votre origine, je vous ai portés dès votre naissance, et jusqu\'à vos vieux jours je serai le même,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'et jusqu\'à la blanche vieillesse je vous soutiendrai; je l\'ai fait et je vous porterai encore, je veux soutenir et sauver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'A qui pourriez-vous m\'assimiler? de qui me faire l\'égal? à qui me comparer, pour que nous nous ressemblions?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Ceux qui laissent couler l\'or de leur bourse et pèsent l\'argent à la balance, prennent à gages un orfèvre pour qu\'il leur fasse un Dieu: ils se prosternent et l\'adorent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Ils le lèvent, en chargent leur épaule, et le mettent sur pied pour qu\'il se tienne; et de sa place il ne bouge; on a beau lui crier, il ne répond pas; de leur détresse il ne les sauve pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Souvenez-vous-en et pensez en hommes! rebelles, réfléchissez-y!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Rappelez-vous les premiers événements de jadis; car je suis Dieu, et il n\'en est point d\'autre; je suis Seigneur, et n\'ai pas mon pareil;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'c\'est moi qui dès l\'origine annonce l\'avenir, et dans le passé ce qui n\'était pas encore; qui dis: « Ce que j\'arrête, se fera, et j\'accomplirai toute ma volonté! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'qui du Levant ai appelé un aigle, et d\'une terre lointaine l\'exécuteur de mon décret. Je l\'ai dit, et je le réalise; je l\'ai projeté, et je l\'exécuterai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Écoutez-moi, vous qui êtes endurcis de cœur et loin de la justice!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Je fais approcher ma justice; elle n\'est pas loin, et mon salut ne tardera pas. Je mettrai mon salut en Sion, et sur Israël ma gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Descends, et assieds-toi dans la poudre, Vierge, fille de Babel! Assieds-toi sur la terre, sans trône, fille des Chaldéens!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Car désormais on ne t\'appellera plus molle et délicate! Prends le moulin, et mouds de la farine! ôte ton voile! relève les pans de ta robe! découvre tes jambes! passe à gué les fleuves! Découvre ta nudité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'oui, ta nudité sera vue; je veux tirer vengeance, et ne donner de trêve à personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Notre rédempteur (l\'Éternel des armées est son nom), le Saint d\'Israël [le dit]:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Assieds-toi muette, et fuis dans les ténèbres, fille des Chaldéens, car on ne t\'appellera plus désormais la maîtresse des empires!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Je fus irrité contre mon peuple, je profanai mon héritage, et les livrai à ton bras; tu n\'eus pour eux nulle pitié! sur un vieillard tu appesantis ton joug avec excès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'Et tu disais: « A jamais je serai maîtresse! » tu allais jusqu\'à ne pas réfléchir à ces choses, et à ne point considérer la fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Et maintenant, entends-le, voluptueuse, sur ton trône pleine de sécurité, qui dis en ton cœur: « Moi et nulle autre que moi! je ne serai point dans le veuvage, et je n\'éprouverai point la privation d\'enfants. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Eh bien! l\'un et l\'autre t\'arrivera soudain le même jour, la privation d\'enfants et le veuvage, ils t\'arriveront complets, malgré le nombre de tes enchantements et la multitude excessive de tes charmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Tu te fiais en ta malice, tu disais: « Personne ne me voit! » Ta sagesse et ta prudence! ce sont elles qui t\'égarent; et tu dis dans ton cœur: « Moi et nulle autre que moi! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Aussi t\'arrivera-t-il un malheur que tu ne sauras conjurer, et une calamité fondra sur toi que tu ne pourras expier, et la ruine fondra sur toi soudain, avant que tu t\'en doutes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Poursuis donc tes conjurations, et tes nombreux enchantements dont tu t\'es occupée depuis ta jeunesse! peut-être pourras-tu trouver des ressources, peut-être inspirer la terreur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Tu es fatiguée du nombre de tes consultations! qu\'ils se lèvent donc pour te secourir, ceux qui découpent le ciel en régions, qui inspectent les astres, indiquent aux nouvelles lunes ce qui doit t\'arriver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Voici, ils sont comme le chaume; le feu les brûle, ils ne sauveront pas leur vie des flammes: il n\'en restera pas un charbon pour se chauffer, ni un feu pour s\'asseoir auprès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Tels seront pour toi ceux envers qui tu te donnes tant de peine, ceux avec qui tu eus affaire dès ta jeunesse, ils s\'égarent chacun de son côté, et personne ne te sauve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Entendez-le, maison de Jacob, vous qui prenez le nom d\'Israël, et émanez de la source de Juda, qui jurez par le nom de l\'Éternel et célébrez le Dieu d\'Israël, mais non avec vérité ni avec droiture!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, '(Car de la ville sainte ils prennent leur nom, et ils s\'appuient sur le Dieu d\'Israël, dont le nom est l\'Éternel des armées.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Dès longtemps je fis les premières prédictions; elles sortirent de ma bouche et je les publiai: soudain j\'agis, et elles s\'accomplirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Sachant que tu es endurci, et que ton col est une barre de fer, et que tu as un front d\'airain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'je t\'indiquai ces choses à l\'avance, avant l\'événement je te les annonçai, afin que tu ne disses pas: « Mon idole en est l\'auteur, et l\'effigie que j\'ai sculptée, ou celle que j\'ai fondue, leur a commandé d\'être. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Vous avez entendu... Tout s\'accomplit, et vous, ne l\'avouerez-vous pas? Dès ce moment je t\'annonce des faits nouveaux et réservés, dont tu n\'as pas eu connaissance:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'ils apparaissent maintenant et ne se virent pas jadis; plus tôt tu n\'en ouïs pas parler, afin que tu ne dises pas: « Voici, j\'en avais connaissance. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Tu n\'en as rien entendu, ni rien su, et jadis ton oreille n\'y fut pas ouverte; car je savais que tu es infidèle, et que Rebelle fut ton nom déjà dans le sein maternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Pour l\'amour de mon nom je suspends ma vengeance, pour l\'amour de ma gloire je me contiens envers toi, pour ne pas te détruire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Voici, je t\'ai mis au creuset, mais je n\'ai point obtenu d\'argent; je t\'ai éprouvé dans la fournaise du malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'C\'est pour l\'amour de moi-même, de moi-même, que j\'ai agis: car, comment [mon nom] serait-il profané? et je ne céderai point ma gloire à un autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Écoute-moi, Jacob, et Israël que j\'ai appelé: Je suis, moi, le premier, et aussi le dernier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Ma main de même a fondé la terre, et ma droite a déployé les Cieux: je les appelle, et ils se présentent ensemble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Vous tous, assemblez-vous et écoutez! Lequel d\'entre eux a annoncé ces choses, [annoncé] celui que l\'Éternel aime, qui exécutera sa volonté contre Babel, et sera son bras contre les Chaldéens?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Moi, moi, j\'ai parlé et l\'ai appelé, je l\'ai amené, et il trouvera le succès sur sa route.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Approchez-vous de moi et écoutez: Dès l\'origine je n\'ai point parlé en secret, dès la naissance de ces événements j\'y assiste. Et maintenant le Seigneur, l\'Éternel, m\'a envoyé avec son esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Ainsi parle l\'Éternel, ton Rédempteur, le Saint d\'Israël: Moi, l\'Éternel, ton Dieu, je t\'enseigne ce qui t\'est profitable, je te guide dans la route où tu dois marcher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Ah! si tu eusses pris garde à mes commandements! Alors ta paix serait comme le Fleuve, et ta justice comme les flots de la mer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'ta race serait comme ses sables, et les enfants de ton sang, comme ses graviers, ton nom ne serait ni retranché, ni anéanti devant moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Sortez de Babel! fuyez loin des Chaldéens! d\'une voix d\'allégresse annoncez, publiez-le, proclamez-le jusqu\'au bout de la terre, dites: « L\'Éternel a racheté son serviteur Jacob! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Et ils ne seront point altérés dans le désert qu\'ils ont à traverser; Il fera pour eux couler des eaux du rocher, Il fendra le rocher et les eaux jailliront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Point de paix, dit l\'Éternel, pour les impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Îles, écoutez-moi, et prêtez attention, peuples reculés! L\'Éternel m\'appela dès le sein maternel; j\'étais encore dans les flancs de ma mère, qu\'il nommait mon nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Il donna à ma bouche le tranchant de l\'épée, de l\'ombre de sa main Il me couvrit, Il fit de moi un trait acéré, et Il me cacha dans son carquois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'Et Il me dit: Tu es mon serviteur, Israël en qui je ferai éclater ma gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Mais je dis: En vain j\'ai travaillé, vainement et pour rien j\'ai consumé mes forces; mais mon bon droit est par devers l\'Éternel, et mon salaire par devers mon Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Or maintenant l\'Éternel parle, lui qui me forma dès le sein maternel, pour être son serviteur, pour ramener à lui Jacob, et Israël qui n\'est pas recueilli; et aux yeux de l\'Éternel je suis honoré, et mon Dieu est ma force...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Il dit: C\'est trop peu que tu sois mon serviteur, pour relever les tribus de Jacob et ramener les restes conservés d\'Israël; je t\'établis lumière des nations, pour que tu portes mon salut jusqu\'au bout de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Ainsi parle l\'Éternel, rédempteur d\'Israël, son Saint, à celui que tous méprisent, qui inspire l\'horreur au peuple, au serviteur des dominateurs: Des rois le verront et se lèveront, et des princes s\'inclineront devant lui, pour l\'amour de l\'Éternel qui est fidèle, du Saint d\'Israël qui t\'a choisi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Ainsi parle l\'Éternel: Au temps de la grâce je t\'exaucerai, et au jour du salut je te serai en aide: je te garderai et te ferai médiateur de l\'alliance de mon peuple, pour relever le pays et répartir les héritages désolés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'pour dire aux prisonniers: « Sortez! » et à ceux qui sont dans les ténèbres: « Paraissez au jour! » Sur les chemins ils trouveront une pâture, et sur les coteaux nus leur pâturage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Ils ne seront point affamés, et point altérés; le hâle ni le soleil ne les accablera; car Celui qui a pitié d\'eux les mène, et Il les conduit aux eaux jaillissantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Et je changerai tous mes monts en chaussées, et mes chemins seront élevés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Voici, les uns arrivent des lointains pays, et voici, les autres du septentrion et de l\'occident, et d\'autres du pays de Sinim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Cieux, soyez dans l\'allégresse! terre, réjouis-toi! et vous montagnes, éclatez en acclamations! car l\'Éternel console son peuple et de ses malheureux Il prend pitié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Sion dit: « L\'Éternel m\'abandonne et le Seigneur m\'oublie. » –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Une femme oublie-t-elle son nourrisson, perdant sa tendresse pour le fruit de ses entrailles? Quand elle pourrait l\'oublier, moi je ne t\'oublierai pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Voici, je t\'ai gravée sur mes mains; tes murs me sont toujours présents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Tes fils accourent, tes destructeurs et tes désolateurs s\'enfuient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Porte les yeux de toutes parts et regarde! tous ils s\'assemblent et s\'acheminent vers toi. Par ma vie, dit l\'Éternel, oui, tu les porteras tous comme une parure, tu t\'en ceindras comme une fiancée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Quant à tes ruines et à ton sol désolé, et à ton pays ravagé, tu seras trop étroite pour tant d\'habitants, et tes exterminateurs se sont éloignés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Les fils dont tu fus privée, de ces mots frapperont encore tes oreilles: La place est pour moi trop étroite, serre-toi contre moi, pour que je puisse me loger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Et tu diras en ton cœur: Qui me les a engendrés? car j\'étais sans enfants et stérile, chassée et répudiée! et ceux-ci, qui les a élevés? Voici, j\'étais restée seule! ceux-ci, où étaient-ils? –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Ainsi parle le Seigneur, l\'Éternel: Voici, je lèverai ma main en signe aux nations, et pour les peuples je dresserai mon étendard, afin qu\'ils rapportent tes fils sur leurs bras, et que sur leurs épaules ils ramènent tes filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Et des rois seront tes nourriciers, et leurs princesses tes nourrices; la face contre terre ils tomberont devant toi, et baiseront la poussière de tes pieds, et tu reconnaîtras que je suis l\'Éternel, qui ne confonds point ceux qui se confient en moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, '« Au puissant, arracherait-on une proie, et les captifs d\'un juste échapperaient-ils? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Oui, dit l\'Éternel, même les captifs du puissant seront arrachés, et la proie d\'un furieux, échappera, et avec tes ennemis j\'engagerai le combat, et je délivrerai tes fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Et je ferai à tes oppresseurs manger leur propre chair, et comme de vin ils s\'enivreront de leur sang, et toute chair reconnaîtra que je suis l\'Éternel, ton sauveur et ton rédempteur, le héros de Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Ainsi parle l\'Éternel: Où est la lettre de divorce de votre mère, avec laquelle je la renvoyai? Ou auquel de mes créanciers vous ai-je vendus? Voici, c\'est pour vos péchés que vous fûtes vendus, et pour vos crimes que votre mère fut répudiée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Pourquoi suis-je venu, et personne n\'était là? ai-je appelé, et personne n\'a répondu? Eh! ma main serait-elle trop courte pour délivrer, ou suis-je sans force pour sauver? Voici, par ma menace je dessèche la mer, change les fleuves en désert; faute d\'eau, leurs poissons sont fétides, et périssent de soif.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Je revêts les Cieux d\'obscurité, et du cilice je fais leur couverture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Le Seigneur, l\'Éternel, m\'a donné la langue des savants, pour que par la parole je sache soulager l\'homme las: Il donne l\'éveil chaque matin, chaque matin Il donne l\'éveil à mon oreille, afin que j\'écoute comme ceux qu\'on enseigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Le Seigneur, l\'Éternel, m\'a ouvert les oreilles, et je n\'ai point résisté, ni reculé:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'j\'ai livré mon dos aux coups et mes joues aux épilateurs, et je n\'ai dérobé mon visage ni aux outrages, ni aux crachements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Mais le Seigneur, l\'Éternel, est mon aide; c\'est pourquoi je n\'eus point honte, c\'est pourquoi je pris un visage pareil au caillou, sachant que je ne serais point confondu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Celui qui me justifie est près: qui disputerait contre moi? Comparaissons ensemble! Qui est ma partie? qu\'il s\'approche de moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Voici, le Seigneur, l\'Éternel est mon aide, qui est-ce qui me condamnera? Voici, tous ils tombent en lambeaux comme un vêtement, la teigne les ronge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Quiconque parmi vous craint l\'Éternel, qu\'il soit docile à la voix de son serviteur! Quiconque marche dans l\'obscurité, sans clarté, qu\'il se confie dans le nom de l\'Éternel, et s\'appuie sur son Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Voici, vous tous qui allumez un feu, et vous armez de torches, tombez dans les flammes de votre feu et parmi les torches que vous avez allumées! C\'est de ma main que vous recevrez ces choses; vous serez gisants dans la douleur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Écoutez-moi, vous qui poursuivez la justice, qui cherchez l\'Éternel! Portez vos regards sur le rocher d\'où vous fûtes détachés, sur la carrière d\'où vous fûtes tirés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Portez vos regards sur Abraham, votre père, et sur Sara qui vous donna naissance! Car je l\'appelai lui seul, et le bénis et le multipliai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Oui, l\'Éternel prend pitié de Sion, Il prend pitié de toutes ses ruines, et Il changera son désert en un Éden, et son sol aride en un jardin de l\'Éternel. La joie et l\'allégresse s\'y trouveront, les hymnes et les chants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Prête-moi attention, mon peuple, et ouvre-moi ton oreille, ô ma nation! Car une loi émanera de moi, et je poserai mon droit comme lumière des peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Ma justice est près, mon salut va paraître, et mes bras jugeront les peuples, les îles espéreront en moi et seront dans l\'attente de mon bras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Levez vos yeux au ciel, et portez-les en bas sur la terre! Car les Cieux s\'évanouiront comme une fumée, et la terre s\'usera comme un vêtement, et ses habitants périront comme des mouches, mais mon salut durera éternellement, et ma justice ne cessera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Écoutez-moi, vous qui connaissez la justice, peuple qui a ma loi dans son cœur! Ne redoutez pas les mépris de l\'homme, et de leurs outrages ne vous épouvantez pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Car la teigne les rongera comme un vêtement, et la gerce les rongera comme la laine, mais ma justice dure éternellement, et mon salut d\'âge en âge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Réveille-toi! réveille-toi! arme-toi de vigueur, bras de l\'Éternel! réveille-toi, comme aux jours d\'autrefois, dans les anciens âges! N\'est-ce pas toi qui abattis Rahab, qui perças le dragon?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'N\'est-ce pas toi qui desséchas la mer, les eaux du grand abîme, qui fis du fond de la mer une route pour le trajet des rachetés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Et les rachetés de l\'Éternel reviendront et s\'avanceront vers Sion avec allégresse, portant sur leurs fronts une joie éternelle; le contentement et la joie se rencontrent, la douleur et les soupirs s\'enfuient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'C\'est moi, c\'est moi qui vous console. Qui es-tu pour redouter l\'homme qui meurt, et l\'enfant d\'Adam qu\'on jette comme l\'herbe,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'et pour oublier l\'Éternel ton créateur, qui déploya les Cieux et fonda la terre, et pour trembler incessamment tout le jour devant la furie de l\'oppresseur, quand il ajuste pour faire périr? Et où est maintenant la furie de l\'oppresseur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Bientôt l\'homme courbé sous les fers sera élargi, et il ne mourra pas dans la fosse, et son pain ne lui manquera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Je suis l\'Éternel, ton Dieu, qui soulève la mer, et ses flots bruissent: l\'Éternel des armées est son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Et je mets mes paroles en ta bouche, et de l\'ombre de ma main je te couvre, pour tendre des Cieux [nouveaux] et fonder une terre [nouvelle] et dire à Sion: Tu es mon peuple!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Courage! courage! lève-toi, Jérusalem, qui de la main de l\'Éternel bus le calice de sa fureur, bus et épuisas le vase, la coupe d\'enivrement!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Il n\'y eut pour la conduire aucun de tous les fils qu\'elle avait enfantés, et pour la prendre par la main aucun des fils qu\'elle avait élevés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Deux maux te survinrent: qui saurait te plaindre? le ravage et la ruine, la famine et l\'épée. Comment te consolerais-je?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Tes fils étaient étendus défaillants à tous les carrefours, comme un cerf dans la toile, pleins de la fureur de l\'Éternel et des menaces de ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Aussi entends-le donc, malheureuse, enivrée, mais non pas de vin!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Ainsi parle ton Seigneur, l\'Éternel, et ton Dieu qui venge son peuple: Voici, je reprends de ta main le calice d\'enivrement, le vase, la coupe de ma fureur; désormais tu n\'y boiras plus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'et je le place dans la main de ceux qui t\'attristèrent, qui te dirent: « Incline-toi, afin que nous marchions par dessus! » et tu fis de ton dos comme un sol, et comme un chemin pour les passants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Réveille-toi! réveille-toi! revêts ta parure, ô Sion! revêts tes habits magnifiques, Jérusalem, ville sainte! car désormais ni incirconcis ni impur n\'entrera chez toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Secoue ta poussière, lève-toi, mets-toi sur ton séant, Jérusalem! détache les chaînes de ton col, fille de Sion captive!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Car ainsi parle l\'Éternel: Vous fûtes vendus pour rien et vous ne serez pas rachetés pour de l\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Car ainsi parle le Seigneur, l\'Éternel: Jadis mon peuple descendit en Egypte pour y séjourner, et l\'Assyrien l\'opprima sans cause.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Et maintenant que me fait-on, dit le Seigneur, d\'enlever mon peuple sans cause? Ses tyrans jubilent, dit l\'Éternel, et incessamment tout le jour mon nom est outragé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Aussi faut-il que mon peuple sache ce qu\'est mon nom; il le faut ce jour-là même; c\'est moi qui parle: me voici!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Qu\'ils sont beaux sur les montagnes les pieds de celui qui apporte une bonne nouvelle, qui proclame la paix, qui annonce du bonheur, qui proclame la délivrance, qui dit à Sion: Ton Dieu règne!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Écoute la voix de tes sentinelles! ensemble elles élèvent la voix en acclamations; car face à face elles voient revenir l\'Éternel en Sion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Éclatez ensemble en acclamations, ruines de Jérusalem! car l\'Éternel prend pitié de son peuple, Il rachète Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'L\'Éternel découvre son bras saint aux yeux de toutes les nations, et toutes les extrémités de la terre contemplent le salut de notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Partez, partez! quittez ces lieux! ne touchez nul impur! sortez du milieu d\'eux! purifiez-vous, porteurs des vases de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Car vous ne partirez pas à la précipitée, et votre départ ne sera pas une fuite, car l\'Éternel marche à votre tête, et le Dieu d\'Israël ferme votre marche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Voici, mon serviteur prospère, il monte, il s\'élève, il arrive à une grande hauteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Autant plusieurs furent interdits à sa vue, tellement son visage était défiguré plus que celui d\'aucun homme, et son aspect, plus qu\'aucun enfant des hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'autant il transportera de joie plusieurs peuples; devant lui des rois se fermeront la bouche, car ils verront ce qui ne leur fut jamais raconté, et ils contempleront ce qui pour eux était inouï.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Qui ajoute foi à ce que nous annonçons, et pour qui le bras de l\'Éternel a-t-il été manifeste?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Il croît devant Lui comme un rejeton, et comme une racine, d\'un sol aride. Il n\'a ni beauté, ni éclat pour attirer nos regards, ni apparence, pour exciter nos désirs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Il est méprisé et délaissé des hommes, homme de douleurs, et familiarisé avec la maladie, et méprisé comme celui qui se cache le visage devant nous, et nous ne fîmes aucun cas de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Cependant il porta nos maladies, et se chargea de nos douleurs, et nous le crûmes puni, frappé de Dieu et humilié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Mais il était percé pour nos péchés, brisé pour nos crimes, le châtiment qui nous sauve tombait sur lui, et c\'est par ses plaies que nous sommes guéris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Tous nous errions comme des brebis, nous suivions chacun notre voie, mais l\'Éternel fit peser sur lui le crime de nous tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Il fut maltraité et il fut humilié, et n\'ouvrit pas la bouche, tel que l\'agneau mené à la boucherie et telle qu\'une brebis muette devant ceux qui la tondent, et il n\'ouvrit pas la bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'A l\'angoisse et au jugement il est arraché: et qui dira sa durée? car il est retranché de la terre des vivants, pour le crime de mon peuple il a été frappé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'On lui assigna son tombeau à côté des impies, mais dans sa mort il fut avec le riche, car il ne commit point de violences et dans sa bouche il n\'y eut point de fraude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Et il plut à Dieu de le briser par la maladie. Mais après avoir donné sa vie en expiation, il verra une postérité et prolongera ses jours, et l\'œuvre de l\'Éternel prospérera entre ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Délivré des peines de son âme, il pourra rassasier ses regards; par sa connaissance mon serviteur juste en justifiera plusieurs, et de leurs crimes il se chargera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Aussi je lui donnerai son lot parmi les puissants, et avec les braves il partagera le butin, parce qu\'il dévoua son âme à la mort, et qu\'il fut mis au nombre des malfaiteurs, pour avoir pris sur lui les péchés de plusieurs, et intercédé pour les criminels.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Réjouis-toi, stérile qui n\'enfantais pas, éclate en acclamations et en cris de joie, toi qui ne devins point mère! Car les fils de la délaissée sont plus nombreux que les fils de celle qui était mariée, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Agrandis l\'espace de ta tente, et fais déployer les tentures de ta demeure! ne l\'empêche pas! allonge tes cordes et affermis tes pieux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'car tu t\'étendras à droite et à gauche, et ta race dépossédera des peuples, et peuplera des villes désertes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Ne crains point! car tu ne seras point confondue; et n\'aie point honte! car tu seras sans opprobre; car tu oublieras l\'ignominie de ta jeunesse, et tu ne penseras plus à l\'opprobre de ton veuvage!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Car ton créateur est ton époux; l\'Éternel des armées est son nom; et ton rédempteur, c\'est le Saint d\'Israël; Il s\'appelle le Dieu de toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Car l\'Éternel te rappelle comme une femme délaissée et qui a le chagrin dans le cœur, comme une épouse de la jeunesse, qui a été répudiée, dit ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Un court instant je te délaissai, mais avec une grande affection je veux te reprendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'Dans l\'effusion de ma colère je te dérobai un instant ma face, mais par une grâce éternelle j\'aurai pitié de toi, dit ton Rédempteur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Car il en est de même pour moi que lors des eaux de Noé: de même que je jurai que les eaux de Noé n\'envahiraient plus la terre, de même je jure de n\'être plus courroucé contre toi, et de ne plus être menaçant pour toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Que les montagnes se déplacent, et que les collines s\'ébranlent, ma grâce ne te sera pas ôtée, et mon alliance de paix ne sera point ébranlée, dit l\'Éternel qui a pitié de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Malheureuse, battue de la tempête, toi que nul ne console! voici, je vais enchâsser tes pierres dans la galène, et te donner des fondements de saphir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'Je ferai tes créneaux de rubis et tes portes d\'escarboucles, et toute ton enceinte de pierres précieuses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Et tous tes fils seront disciples de l\'Éternel, et grand sera le bonheur de tes fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Par la justice tu seras consolidée; ne donne pas accès à l\'angoisse, car tu n\'as rien à craindre; ni à la terreur, car elle ne t\'approchera pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Si on se ligue contre toi, ce n\'est pas de par moi; qui se liguera contre toi, passera dans tes rangs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Voici, je crée le forgeron qui souffle le feu du brasier et produit une arme conforme à son plan, et je crée aussi le dévastateur pour détruire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Toute arme forgée contre toi sera sans effet, et toute langue qui s\'élèvera contre toi pour contester, tu la condamneras. Tel est l\'héritage des serviteurs de l\'Éternel, et leur justice de par moi, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Ho! vous tous qui avez soif, venez aux eaux! et vous qui n\'avez pas d\'argent, venez, achetez et mangez! Venez, achetez sans argent et sans frais du vin et du lait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Pourquoi pesez-vous de l\'argent pour ce qui n\'est pas du pain, et vos gains pour ce qui ne rassasie pas? Écoutez, écoutez-moi et goûtez les biens, et que votre âme se restaure par des mets succulents!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Prêtez l\'oreille et venez à moi! écoutez, afin que votre âme vive! Je veux vous accorder une alliance éternelle, les grâces permanentes de David.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Voici, je l\'établis législateur des peuples, prince et ordonnateur des peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Voici, tu convieras un peuple que tu ne connais pas, et un peuple qui ne te connaît pas accourra près de toi, pour l\'amour de l\'Éternel ton Dieu, et à cause du Saint d\'Israël, car Il te glorifie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Cherchez l\'Éternel, pendant qu\'il se trouve, invoquez-le, tandis qu\'il est près!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Que l\'impie abandonne sa voie, et le méchant ses pensées, et qu\'il vienne à l\'Éternel qui aura pitié de lui, et à notre Dieu, car Il pardonne abondamment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Car mes pensées ne sont pas vos pensées, et vos voies ne sont pas mes voies, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Mais autant le ciel s\'élève au-dessus de la terre, autant mes voies s\'élèvent au-dessus de vos voies, et mes pensées au-dessus de vos pensées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Car telles la pluie et la neige descendent du ciel, et n\'y retournent pas, mais abreuvent la terre et la fécondent, et la font végéter, et donnent la semence au semeur, et du pain à celui qui mange;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'telle est ma parole sortie de ma bouche; elle ne revient pas à moi sans effet, mais elle exécute ma volonté, et accomplit ce pour quoi je l\'émets.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Oui, vous partirez avec allégresse, et vous serez conduits en paix; les monts et les collines éclateront au-devant de vous en acclamations, et tous les arbres des campagnes applaudiront en battant des mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Au lieu de la ronce s\'élèvera le cyprès, et au lieu de la bruyère croîtra le myrte; et ce sera pour l\'Éternel une gloire et un monument éternel qu\'on ne détruira pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Ainsi parle l\'Éternel: Gardez la loi et pratiquez la justice, car mon salut est près d\'arriver, et ma justice de se manifester.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Heureux l\'homme qui le fait, et l\'enfant d\'Adam qui y tient fortement, gardant le sabbat pour ne le point profaner, et gardant sa main pour ne faire aucun mal!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Et que le fils de l\'étranger qui s\'attache à L\'Éternel, ne tienne pas ce langage: « L\'Éternel m\'exclura de son peuple! » et que l\'eunuque ne dise pas: « Je suis un arbre sec! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Car ainsi parle l\'Éternel touchant les eunuques: Ceux qui gardent mes sabbats, et s\'affectionnent à ce qui m\'est agréable, et adhèrent à mon alliance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'je leur donnerai dans ma maison et dans mes murs une place et un nom meilleur que fils et filles, je leur donnerai un nom éternel qui ne périra pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Et les fils des étrangers qui s\'attachent à l\'Éternel pour le servir et pour aimer le nom de l\'Éternel, afin d\'être ses serviteurs, tous ceux qui gardent le sabbat pour ne le point profaner et qui adhèrent à mon alliance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'je les amènerai à ma sainte montagne et les réjouirai dans ma maison de prière; leurs holocaustes et leurs sacrifices seront bienvenus sur mon autel, car ma maison sera appelée une maison de prière pour tous les peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Le Seigneur, l\'Éternel qui réunit les bannis d\'Israël, le déclare: J\'en réunirai encore à lui et aux siens déjà recueillis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Vous, toutes les bêtes des champs, venez à la pâture, et vous, toutes les bêtes des forêts!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Ses guets sont tous aveugles, ils n\'aperçoivent rien, ils sont tous des chiens muets, incapables d\'aboyer, rêvant couchés, aimant à dormir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Et ces chiens sont voraces, insatiables; et ce sont des bergers qui ne savent pas voir, tous ils prennent leur chemin, chacun après son gain, du premier au dernier:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, '« Venez! je vais chercher du vin! enivrons-nous de cervoise, et, comme aujourd\'hui, demain il y aura quantité et grande abondance! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Le juste périt et nul n\'y prend garde, et les gens de bien sont enlevés, sans que nul remarque que le juste est enlevé par l\'effet de la malice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Il entre dans la paix; ils reposent sur leur couche, ceux qui marchent droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Mais vous, avancez ici, fils d\'enchanteresse, race de l\'adultère et de la prostituée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Aux dépens de qui vous égayez-vous? A qui présentez-vous une bouche élargie, tirez-vous la langue? N\'êtes-vous pas des enfants de la révolte, une race menteuse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'brûlant pour des idoles sous tout arbre vert, immolant des enfants dans les vallées, dans les creux des rochers?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Les pierres des torrents sont ton partage, c\'est elles qui sont ton lot; à elles aussi tu fais des libations, tu présentes des oblations: y puis-je être insensible?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Sur une montagne haute et éminente tu dresses ton lit, et l\'a aussi tu montes pour offrir des victimes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Et derrière la porte et les jambages tu places les objets de ta pensée. Car me désertant, tu découvres ton lit et y montes, et tu l\'as rendu spacieux, et tu leur fais tes conditions, et tu aimes leur commerce: tu te choisis une place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Et tu te présentes au roi avec de l\'huile, ayant sur toi beaucoup de parfums; tu envoies tes messagers au loin, et les fais pénétrer jusqu\'aux Enfers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'A force de voyager tu te fatigues, mais tu ne dis pas: C\'est en vain! Tu trouves encore de la vigueur en ta main; aussi n\'es-tu pas affaiblie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Et qui donc crains-tu et redoutes-tu, que tu dissimules et ne te souviens pas de moi? Tu n\'en as pas tenu compte! N\'est-ce pas? je garde le silence, et même depuis longtemps; c\'est pourquoi tu ne me crains pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Je mettrai ta justice au jour, et tes œuvres qui ne te profiteront pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Quand tu cries, tes bandes de dieux te sauveront-elles? Eh! un coup de vent les enlève tous, un souffle les emporte. Mais qui se confie en moi, héritera le pays et possédera ma montagne sainte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'et il dit: Frayez, frayez, préparez le chemin, ôtez tout achoppement de la route de mon peuple!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Car ainsi parle le Suprême, l\'Éminent dont le trône est éternel, et qui s\'appelle le Saint: J\'habite les lieux très hauts et saints, mais aussi près de l\'affligé et de l\'homme abattu d\'esprit, pour ranimer l\'esprit des hommes abattus, et ranimer le cœur des affligés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Car je ne veux pas contester à toujours, ni garder une colère éternelle, puisqu\'à ma présence l\'esprit et les âmes que j\'ai faites, tombent en défaillance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Pour le crime de son avarice je m\'irritai et le frappai, je me cachai, et m\'irritai: rebelle néanmoins, il suivit la voie que lui montrait son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'J\'ai vu ses voies; mais je veux le guérir, et le conduire, et lui donner des consolations à lui et à ses affligés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'faisant éclater la louange sur ses lèvres. Paix, paix, pour celui qui est loin, et pour celui qui est près, dit l\'Éternel! je veux les guérir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Mais les impies sont comme la mer agitée; car elle ne peut se calmer, et les eaux soulèvent du limon et de la vase.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Point de paix, dit mon Dieu, pour les impies!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Crie à plein gosier, ne te retiens pas! à l\'égal de la trompette élève la voix, et annonce à mon peuple son crime et à la maison de Jacob son péché!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Journellement ils m\'interrogent et désirent savoir mes voies; comme un peuple qui pratiquerait la justice et n\'aurait pas abandonné la loi de son Dieu, ils demandent de moi des arrêts de justice; ils désirent l\'approche de Dieu:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, '« Pourquoi jeûnons-nous [disent-ils], et tu ne le vois pas? pourquoi nous traiter durement, et tu l\'ignores? » Voici, dans votre jour de jeûne vous courez à vos affaires, et exigez toutes vos corvées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Voici, vous jeûnez pour vous quereller, et pour disputer, et frapper d\'un poing sacrilège. Vous ne jeûnez pas aujourd\'hui à faire exaucer vos cris dans les lieux très hauts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Est-ce là le jeûne que j\'aime, le jour où l\'homme se traite durement? Quoi! plier la tête comme un jonc, et se coucher sur le cilice et la cendre, est-ce là ce que tu appelleras un jeûne, un jour approuvé de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Voici le jeûne que j\'aime: c\'est qu\'on délie les chaînes de l\'impiété, qu\'on fasse tomber les courroies du joug, qu\'on affranchisse les opprimés et que vous enleviez toute sorte de joug;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'et encore, que tu distribues ton pain à celui qui a faim, et amènes au logis les pauvres errants, que, si tu vois un homme nu, tu l\'habilles, et que tu ne te dérobes pas à ton frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Alors ta félicité éclora comme l\'aurore, et ta guérison fera de rapides progrès, et ta justice marchera devant toi, et la gloire de l\'Éternel sera ton arrière-garde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Alors tu appelleras et l\'Éternel répondra; tu crieras et Il dira: « Me voici! » si dans ton sein tu cesses de mettre sous le joug, de montrer au doigt et de dire du mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'Si tu fais part de tes aliments à celui qui a faim, et rassasies l\'âme indigente, alors pendant les ténèbres ta lumière se lèvera, et ton obscurité sera comme le midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Et l\'Éternel sera ton guide constant, et dans les lieux brûlés Il rassasiera ton âme, et redonnera de la vigueur à tes os; tu seras comme un jardin arrosé et comme une source dont les eaux ne trompent jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Et les tiens relèveront les ruines anciennes, tu réédifieras des fondements mis à nu depuis plusieurs âges, et on te nommera réparateur des brèches, restaurateur des chemins pour peupler le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Si tu sais empêcher tes pieds de violer le sabbat, et ne pas suivre tes caprices dans mon jour saint, et si tu appelles le sabbat un délice, honoré de la consécration de l\'Éternel, et si tu l\'honores en ne pratiquant point tes voies, ne courant point à tes affaires, et ne tenant point de vains discours,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'alors tu trouveras tes délices dans l\'Éternel, et je te ferai traverser sur un char les sommités du pays, et jouir de l\'héritage de Jacob, ton père, car la bouche de l\'Éternel l\'a prononcé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Voici, la main de l\'Éternel n\'est pas trop courte pour sauver, ni son oreille trop dure pour entendre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'mais ce sont vos crimes qui vous séparent de votre Dieu, et vos péchés qui vous dérobent sa face, et l\'empêchent d\'entendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Car vos mains sont souillées de sang, et vos doigts de crimes, vos lèvres profèrent le mensonge, et votre langue tient des discours pervers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Nul n\'assigne avec le bon droit, et nul ne plaide avec droiture; on se fie sur un vain parler, et l\'on ment; portant la malice dans leur sein, ils enfantent le crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Ils couvent des œufs d\'aspic, et ourdissent des toiles d\'araignée; quiconque mange de leurs œufs, meurt, et en presse-t-on un, il éclôt une vipère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Leurs trames ne servent pas à vêtir, et de leur ouvrage ils ne peuvent se faire un manteau, leurs: œuvres sont œuvres de malice, et la violence est dans leurs mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Leurs pieds courent au mal et se hâtent pour verser le sang innocent, leurs pensées sont des pensées méchantes, le ravage et la ruine sont sur leur route.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Ils ne connaissent pas le chemin de la paix, et il n\'y a point de justice dans leurs voies; ils se font des sentiers obliques; quiconque les foule, ne connaît point la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Aussi la droiture est-elle loin de nous, et la justice ne parvient pas jusqu\'à nous; nous attendons la lumière, et voilà les ténèbres; de jour nous marchons dans l\'obscurité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Comme des aveugles nous tâtonnons le long de la muraille, et nous allons à tâtons comme étant sans yeux; nous trébuchons en plein jour comme dans la nuit; sur de gras pâturages nous ressemblons à des morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Comme les ours nous grondons tous, et nous gémissons comme les tourterelles; nous attendons la justice, et elle ne vient pas; le salut, il s\'éloigne de nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Car nos crimes sont nombreux devant toi, et nos péchés témoignent contre nous, car nous avons la conscience de nos crimes, et nous connaissons nos forfaits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Nous fûmes rebelles et reniâmes l\'Éternel, et nous tirâmes en arrière de notre Dieu; nous tînmes des discours violents et séditieux, nous conçûmes dans le cœur et enfantâmes des discours trompeurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Le bon droit fit retraite, et la justice se tint à l\'écart, car la vérité trébuche dans la place publique et la droiture n\'y peut avoir accès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'La vérité devint rare, et quiconque fuyait le mal, était dépouillé. Et l\'Éternel le vit, et l\'absence d\'équité déplut à ses yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Et Il vit qu\'il n\'y avait pas un homme, et s\'étonna qu\'il n\'y eût point d\'intercesseur; aussi eut-Il recours à son propre bras, et ce fut sur sa justice qu\'il s\'appuya.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Et Il se revêtit de justice comme d\'une cuirasse, posant sur sa tête le casque du salut, Il prit l\'équipement de la vengeance comme vêtement, et se couvrit de jalousie comme d\'un manteau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'A tels actes Il rendra tel retour, la fureur à ses adversaires et la pareille à ses ennemis, et aux îles Il rendra la pareille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Alors depuis le Couchant on craindra le nom de l\'Éternel, et depuis le Levant sa gloire: quand l\'ennemi s\'avancera comme un fleuve, l\'Esprit de l\'Éternel le dissipera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Et il vient un rédempteur pour Sion, pour les pécheurs convertis dans Jacob, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Et quant à moi, voici l\'alliance que je fais avec eux, dit l\'Éternel: mon Esprit qui repose sur toi, et mes paroles que j\'ai mises en ta bouche ne cesseront d\'être dans ta bouche et dans la bouche de tes enfants, et dans la bouche des enfants de tes enfants, dit l\'Éternel, dès maintenant à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Debout! sois illuminée, car ta lumière arrive, et sur toi la gloire de l\'Éternel se lève!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Car voici, les ténèbres couvrent la terre, et l\'obscurité les nations, mais sur toi l\'Éternel se lève, et sa gloire se rend visible sur toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Et des nations viennent à ta lumière, et des rois à la clarté qui se lève pour toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Jette les yeux de toutes parts et regarde! rassemblés ils viennent tous à toi, de loin tes fils arrivent et tes filles sur les bras sont portées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'A ce spectacle tu te réjouis, et ton cœur bat et se dilate, car vers toi se dirigent les richesses de la mer, et l\'opulence des peuples s\'achemine vers toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Tu seras couverte d\'une foule de chameaux, de dromadaires de Madian et d\'Epha; ils viennent tous de Séba, ils portent de l\'or et de l\'encens et publient les louanges de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Tous les troupeaux de Cédar se rassemblent chez toi, les béliers de Nébaïoth sont à ton service et montent à plaisir à mon autel, et je glorifie ma glorieuse maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Qui sont ceux qui volent là comme des nuages et comme des colombes vers leurs gîtes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'C\'est que les îles s\'attendent à moi, et les navires de Tarsis sont en tête pour ramener de loin tes enfants, et leur or et leur argent avec eux, au nom de l\'Éternel ton Dieu, et du Saint d\'Israël, car Il te couvre de gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Et les enfants de l\'étranger relèvent tes murs, et leurs rois sont à ton service, car dans mon courroux je te frappai, mais dans ma grâce je prends pitié de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Et tes portes sont toujours ouvertes, ni jour ni nuit elles ne se ferment, pour introduire chez toi les trésors des peuples et leurs rois avec leur cortège.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Car les peuples et les empires qui refusent de te servir, périront, et les peuples seront détruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'La pompe du Liban arrive chez toi, le cyprès, le platane et le mélèze réunis, pour parer le lieu de mon sanctuaire, afin que je rende glorieuse la place où reposent mes pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Et les fils de tes oppresseurs viennent à toi humiliés, et tous tes contempteurs s\'inclinent jusqu\'à la plante de tes pieds, et t\'appellent cité de l\'Éternel, Sion, sanctuaire d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Tandis que tu étais délaissée et haïe, personne ne te traversant, je te rends glorieuse à perpétuité, heureuse pour tous les âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Tu boiras le lait des peuples, tu seras allaitée aux mamelles royales, et tu sauras que moi, l\'Éternel, je suis ton sauveur et ton rédempteur, le Fort de Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Au lieu de l\'airain j\'amènerai de l\'or, et au lieu du fer j\'amènerai de l\'argent, et au lieu du bois de l\'airain, et au lieu des pierres du fer, et je te donnerai pour gouverneur la paix, et pour magistrats la justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'On n\'ouïra plus parler de violence dans ton pays, de ravage et de ruine dans tes limites: et tu appelleras tes murs un salut, et tes portes une gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Ce ne sera plus le soleil qui le jour te donnera la lumière, ni la lune qui luira pour t\'éclairer, mais l\'Éternel te sera une lumière éternelle, et ton Dieu sera ta parure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Ton soleil ne se couchera plus, et ta lune ne s\'obscurcira plus, car l\'Éternel te sera une lumière éternelle, et ils sont passés tes jours de deuil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Et ton peuple est tout autant de justes, éternellement le pays sera possédé par eux, rejeton que j\'ai planté, œuvre de ma main pour ma gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Le plus petit s\'augmentera jusqu\'à mille, et le plus chétif jusqu\'à être un peuple nombreux. Moi, l\'Éternel, je le ferai promptement en son temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'L\'Esprit du Seigneur, l\'Éternel, est sur moi, parce que l\'Éternel m\'a oint pour porter une bonne nouvelle aux malheureux, qu\'il m\'a envoyé pour guérir les cœurs brisés, pour proclamer la liberté aux captifs et aux prisonniers l\'ouverture des cachots,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'pour annoncer une année des grâces de l\'Éternel, et un jour des vengeances de notre Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'pour consoler tous les affligés, pour présenter aux affligés de Sion et leur donner un diadème au lieu de la cendre, une huile de réjouissance au lieu du deuil, un manteau éclatant au lieu d\'un esprit éteint, afin qu\'on les nomme Térébinthes de la justice, plant de l\'Éternel à sa gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'On bâtit sur les décombres anciens, et on relève les ruines d\'autrefois, on renouvelle les villes ravagées, dévastées depuis des âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Et des étrangers sont à vos ordres et ils font paître vos troupeaux, et des enfants du dehors sont vos laboureurs et vos vignerons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Mais vous, on vous appelle sacrificateurs de l\'Éternel, on vous nomme ministres de notre Dieu. Vous vous nourrissez de l\'opulence des nations, et vous êtes substitués à leur gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Au lieu de votre opprobre vous aurez double part, au lieu d\'ignominie ils exalteront leur sort: aussi dans leur pays leur portion sera double, une éternelle joie leur est assurée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Car moi, l\'Éternel, j\'aime ce qui est juste, et j\'abhorre la rapine coupable, et je leur donnerai fidèlement leur salaire et leur accorderai une alliance éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'et leur race sera illustre parmi les nations et leurs rejetons entre les peuples; et tous ceux qui les verront, les reconnaîtront, car ils sont une race que bénit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, '« L\'Éternel est ma joie, mon Dieu est l\'allégresse de mon âme, car Il me revêt de vêtements de salut, Il m\'enveloppe d\'un manteau de justice, comme le fiancé ajuste une tiare, et comme la fiancée se pare de ses joyaux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Car, ainsi que la terre produit ses bourgeons, et qu\'un jardin fait germer ses semences, ainsi le Seigneur, l\'Éternel, fait germer la justice et la louange à la face de toutes les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Pour l\'amour de Sion je ne garde pas le silence, et pour l\'amour de Jérusalem je ne me donne point de relâche, jusqu\'à ce que sa justice paraisse comme l\'aube, et son salut comme une torche allumée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Alors les nations contempleront ta justice, et tous les rois ta splendeur, et l\'on t\'appellera d\'un nom nouveau fixé par la bouche de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Et tu seras une couronne éclatante dans la main de l\'Éternel, et une mitre royale dans la main de ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'On ne te dira plus délaissée, et ton pays ne sera plus appelé désert; mais on t\'appellera « Mon plaisir est en elle, » et ta terre « une épouse. » Car l\'Éternel trouve son plaisir en toi, et ta terre a un époux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Car de même qu\'un jeune homme se marie à une vierge, tes fils se marieront à toi, et la joie que le fiancé reçoit de sa fiancée, ton Dieu la recevra de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Sur tes murs, Jérusalem, je place des gardes; de tout le jour et de toute la nuit ils ne garderont pas un instant le silence. « Vous qui rappelez le souvenir de l\'Éternel, ne vous donnez point de relâche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Et ne lui donnez point de relâche qu\'il n\'ait fondé Jérusalem et ne l\'ait rendue un objet de louanges sur la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'L\'Éternel l\'a juré par sa droite et par son bras puissant: Je ne donnerai plus ton blé en nourriture à tes ennemis, et les enfants de l\'étranger ne boiront plus ton moût gagné par ton labeur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'mais ceux qui le récolteront le mangeront et loueront l\'Éternel, et ceux qui le cueilleront, le boiront dans mes saints parvis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Rendez-vous, rendez-vous aux portes; préparez le chemin au peuple! frayez, frayez la route, enlevez les pierres, dressez un étendard pour les peuples!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Voici, l\'Éternel fait aux extrémités de la terre cette proclamation: Dites à la fille de Sion: Voici, ton Sauveur arrive; voici, ses récompenses l\'accompagnent et ses rétributions le précèdent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Et on les appelle « peuple saint, rachetés de l\'Éternel, » et toi, on t\'appelle « cité cherchée, non délaissée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Qui vient là d\'Edom, en habits écarlates de Botsra, étalant fièrement son manteau, portant la tête en arrière dans la plénitude de sa force? – « Moi, qui parlai de justice, tout-puissant pour sauver. » –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Pourquoi ton manteau est-il rouge, et tes vêtements comme ceux du pressureur? –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, '« Seul j\'ai foulé au pressoir, et d\'aucun des peuples je ne fus assisté, et je les ai foulés dans ma fureur et écrasés dans ma colère, et le suc en a jailli sur mes vêtements, et j\'ai eu tout mon manteau taché:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'car un jour de vengeance était dans ma pensée, et l\'année de mes rachetés était venue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Et je regardai, et il n\'y avait point d\'aide, et je m\'étonnai, et point de soutien. Alors mon bras fut mon aide, et ma fureur, tel fut mon soutien,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'et je foulai des peuples dans ma colère et les écrasai dans ma fureur, à en faire ruisseler le suc sur la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Je chante les grâces de l\'Éternel, les louanges de l\'Éternel, d\'après tout ce que l\'Éternel a fait pour nous, et la grande bonté pour la maison d\'Israël qu\'il leur a témoignée selon ses compassions et la grandeur de ses grâces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Il dit: « Oui, ils sont mon peuple, des enfants qui ne tromperont pas; » et Il fut pour eux un Sauveur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Dans toutes leurs détresses il n\'y eut point de détresse dont l\'ange de sa face ne les sauvât; dans son amour et sa miséricorde Il les racheta, et les leva, les porta tous les jours d\'autrefois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Mais ils se rebellèrent, et irritèrent son Esprit Saint; alors Il se tourna contre eux en ennemi, lui-même leur livra la guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Puis [Israël] se souvint des jours d\'autrefois, de Moïse et son peuple. « Où est celui qui les tira de la mer avec le berger de son troupeau? où est celui qui mit au milieu d\'eux son esprit saint?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'qui à la droite de Moïse conduisit son bras glorieux, entr\'ouvrant les eaux devant eux pour se faire un nom éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'qui leur fit traverser les flots comme un coursier dans la plaine, sans broncher?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'De même que les bestiaux descendent dans la vallée, l\'Esprit de l\'Éternel les fit arriver au repos. Ainsi tu conduisis ton peuple pour te faire un nom glorieux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Regarde des Cieux, et vois, de ta demeure sainte et glorieuse! Où sont ton zèle et ta puissance, l\'émotion de ton cœur et ta miséricorde, qui se contiennent envers moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Mais tu es notre père, car Abraham ne nous connaît pas, et Israël nous ignore. Toi, Éternel, tu es notre père; ton nom est notre Sauveur, dès l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Pourquoi, Éternel, nous fais-tu dévier de tes voies, endurcis-tu notre cœur contre ta crainte? Reviens, pour l\'amour de tes serviteurs, des tribus de ton héritage!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Pour un peu de temps ton peuple saint posséda le pays; mais nos ennemis foulèrent ton sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Nous sommes devenus comme ceux sur qui tu n\'as jamais régné, qui ne sont pas appelés de ton nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'O! si tu entr\'ouvrais les Cieux et descendais, par ta présence ébranlant les montagnes, pareil au feu qui brûle la ramée, au feu qui fait bouillir l\'eau, pour faire connaître ton nom à tes adversaires, par ta présence ébranlant les nations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'comme lorsque tu fis des prodiges que nous n\'osions attendre, et descendis, par ta présence ébranlant les montagnes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Jamais ni l\'ouïe, ni l\'oreille, ni l\'œil ne découvrit un Dieu sinon toi, qui en agît ainsi envers ceux qui s\'attendent à lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Tu viens au-devant de qui se plaît à faire le bien, et de qui suivant tes voies garde ta mémoire. Voici, tu t\'irritas, car nous avions péché; [nous suivîmes] longtemps cette voie; et nous aurions été sauvés!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Et nous fûmes tous comme un impur et toute notre justice comme une robe immonde, et comme une feuille nous nous flétrîmes tous, et comme un ouragan nos crimes nous emportèrent:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'et personne qui invoque ton nom! qui se réveille pour te saisir! car tu nous as caché ta face et nous laisses périr par l\'effet de nos crimes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Mais maintenant, Éternel, tu es notre père, nous l\'argile et toi notre formateur, et tous nous sommes l\'œuvre de tes mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Ne t\'irrite pas, ô Éternel, à l\'extrême, et ne garde pas à jamais la mémoire du crime! Voici, ah! regarde, nous sommes tous ton peuple!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Tes villes saintes sont un désert, Sion est un désert, Jérusalem une solitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Notre maison sainte et glorieuse où nos pères t\'ont loué, est incendiée, et tout ce que nous aimions est dévasté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'A ces faits peux-tu te contenir, ô Éternel, garder le silence, et nous humilier à l\'excès?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'je vous destine à l\'épée, et vous serez tous jetés à la tuerie, parce que j\'ai appelé et que vous n\'avez pas répondu, j\'ai parlé, et que vous n\'avez pas écouté, et avez fait ce qui est mal à mes yeux, et choisi ce que je n\'approuve pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'J\'étais accessible à ceux qui ne demandaient pas, j\'étais trouvable à ceux qui ne me cherchaient pas; je disais: Me voici! me voici! à un peuple qui ne prend pas mon nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Je tendais mes mains tous les jours au peuple rétif qui, sur une voie mauvaise, suit ses propres pensées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'au peuple qui m\'offense en face constamment, qui offre dans les jardins des sacrifices et de l\'encens sur les briques,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'qui s\'assied dans les tombeaux et passe la nuit dans les antres, qui mange la chair du porc, et couvre ses plats de mets abominables,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'qui dit: « Tiens-toi à distance, ne m\'approche pas, car je suis plus saint que toi! » Ces hommes-là sont une fumée dans mes narines, un feu toujours allumé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Voici, c\'est écrit par devers moi: Je ne me tairai point, que je n\'aie fait retomber, et retomber sur leur sein vos crimes');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'et les crimes de vos pères à la fois, dit l\'Éternel, qui encensèrent sur les montagnes, et sur les collines m\'outragèrent; et je leur mesurerai dans le sein le prix de leurs premiers faits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Ainsi parle l\'Éternel: Comme, quand il se trouve du suc dans le raisin, on dit: Ne le détruis pas, car il y a là une bénédiction! ainsi agirai-je pour l\'amour de mes serviteurs; je ne détruirai pas tout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Et je ferai sortir de Jacob une postérité, et de Juda un héritier de mes montagnes, que mes élus auront pour héritage et mes serviteurs pour habitation:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'et Saron sera un pacage de brebis, et la vallée d\'Achor une reposée du bétail, pour mon peuple qui me cherche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Mais vous qui abandonnez l\'Éternel, qui oubliez ma montagne sainte, dressez une table à la Fortune, et remplissez la coupe du Destin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'je vous destine à l\'épée, et vous serez tous jetés à la tuerie, parce que j\'ai appelé et que vous n\'avez pas répondu, j\'ai parlé, et que vous n\'avez pas écouté, et avez fait ce qui est mal à mes yeux, et choisi ce que je n\'approuve pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Aussi, ainsi parle le Seigneur, l\'Éternel: Voici, mes serviteurs mangeront, mais vous serez affamés; voici, mes serviteurs boiront, mais vous serez altérés; voici, mes serviteurs se réjouiront, mais vous serez confondus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'voici, mes serviteurs chanteront dans la joie du cœur, mais vous crierez dans le chagrin du cœur, et vous vous lamenterez dans l\'abattement de l\'esprit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'et vous léguerez votre nom comme une imprécation à mes élus, et le Seigneur, l\'Éternel, vous donnera la mort et appellera ses serviteurs d\'un autre nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Quiconque dans le pays fera des vœux, les fera au nom du Dieu de vérité, et quiconque dans le pays fera un serment, le fera au nom du Dieu de vérité, car les anciennes tribulations seront oubliées et cachées à mes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Car voici, je crée des Cieux nouveaux et une terre nouvelle, et le passé ne reviendra plus dans la mémoire, et ne reviendra plus dans la pensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Mais vous aurez une joie et une allégresse éternelle de ce que je veux créer; car voici, je crée Jérusalem pour la joie, et son peuple pour le contentement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Et je fais ma joie de Jérusalem et mon bonheur de mon peuple, et l\'on n\'y entendra plus la voix des pleurs, ni la voix de la plainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Là désormais plus d\'enfant né pour quelques jours, plus de vieillard qui n\'achève le nombre de ses jours; car on sera jeune en mourant centenaire, et le pécheur à cent ans subira sa malédiction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Et ils bâtiront des maisons et les habiteront, et ils planteront des vignes et en mangeront le fruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Ils ne bâtiront pas pour qu\'un autre habite, ils ne planteront pas pour qu\'un autre jouisse, car tels les jours de l\'arbre, tels seront les jours de mon peuple, et mes élus useront l\'ouvrage de leurs mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Ils ne se peineront pas pour rien, et n\'auront pas des enfants pour les perdre soudain, car ils sont une race de bénis de l\'Éternel, et leurs enfants [resteront] avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Et ils n\'auront pas encore crié que je répondrai; ils parleront encore que j\'exaucerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Le loup et l\'agneau paîtront ensemble, le lion comme le bœuf mangera le fourrage, et la poussière sera l\'aliment du serpent. Ils ne feront rien de mauvais ni de pernicieux sur toute ma montagne sainte, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Ainsi parle l\'Éternel: Le ciel est mon trône et la terre mon marchepied; où est la maison que vous me bâtiriez, et où le lieu où je m\'établirais?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Eh! tout cela, ma main l\'a fait; et tout cela reçut l\'être, dit l\'Éternel. Mais sur celui-ci je fixe mes regards, sur le pauvre, et sur celui qui a l\'esprit abattu et qui craint ma parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Qui sacrifie un bœuf, tue un homme; qui immole une brebis, égorge un chien; qui présente une offrande, offre du sang de porc; qui brûle de l\'encens, adore des idoles. Si eux ils ont choisi leurs voies, et si leur âme se complaît dans leurs abominations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'moi aussi je choisirai leur ruine, et ferai fondre sur eux ce qu\'ils craignent; car j\'ai appelé et personne ne répondit; j\'ai parlé, et ils n\'écoutèrent point et firent ce qui est mal à mes yeux, et choisirent ce que je n\'approuve pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Entendez la parole de l\'Éternel, vous qui craignez sa parole. Vos frères qui vous haïssent et vous repoussent à cause de mon nom, disent: « Que l\'Éternel se montre dans sa gloire pour que nous voyions votre joie! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Mais ils seront confondus! une voix de tumulte part de la ville, une voix part du temple, la voix de l\'Éternel qui apporte le salaire à ses ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Avant de sentir les douleurs, elle a enfanté; avant que lui viennent les angoisses, elle est délivrée d\'un fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Qui jamais entendit choses pareilles? qui en vit de semblables? Un pays est-il enfanté d\'un jour, ou un peuple naît-il tout d\'un coup, qu\'après une douleur Sion aussitôt mette au jour ses enfants?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Pourrais-je ouvrir les portes de la vie, et ne pas laisser enfanter? dit l\'Éternel; ou, laissant enfanter, les fermerais-je? dit ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Réjouissez-vous avec Jérusalem, et qu\'elle excite votre allégresse, ô vous tous qui l\'aimez! Soyez heureux avec elle de son bonheur, vous tous qui êtes en deuil d\'elle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'afin d\'être allaités et rassasiés du lait qui la console, pour vous abreuver avec délices au flux radieux de sa gloire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Car ainsi parle l\'Éternel: Voici, je dirige vers elle la paix comme un fleuve, et comme un torrent débordé la gloire des nations: et vous serez allaités, sur les bras vous serez portés, et caressés sur les genoux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Tel un homme que console sa mère, ainsi je vous consolerai, et en Jérusalem vous serez consolés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Vous le verrez, et votre cœur en sera joyeux, et vos os d\'un gazon frais auront la vigueur, et la main de l\'Éternel sera manifeste à ses serviteurs; mais Il est irrité contre ses ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Car voici, l\'Éternel arrive dans un feu, et ses chars sont comme l\'ouragan, pour vomir sa colère en fureur et son courroux en flammes de feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Car l\'Éternel châtie par le feu, et toute chair par son épée, et nombreux sont les morts de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Ceux qui dans une enceinte font des lustrations et des purifications pour se rendre dans les bocages à la suite d\'un [prêtre], qui mangent la chair du porc, et des choses abominables et des souris, ensemble ils périront, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Me voici, en présence de leurs œuvres et de leurs pensées!... Le moment est venu de rassembler toutes les nations et toutes les langues, et elles viendront et contempleront ma gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Je mettrai en eux un signe, et du milieu d\'eux j\'enverrai des réchappés aux nations, à Tarsis, à Phul et à Lud qui bandent l\'arc, à Thubal et à Javan, aux îles lointaines qui jamais n\'ouïrent parler de moi et ne virent ma gloire, et ils publieront ma gloire parmi les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Et elles amèneront tous vos frères du milieu de tous les peuples en offrande à l\'Éternel, sur des chevaux, et sur des chars, et en litière, et sur des mulets, et sur des dromadaires, à ma sainte montagne, à Jérusalem, dit l\'Éternel, comme les enfants d\'Israël apportent leurs offrandes dans des vases purs à la maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Et de ceux-ci aussi j\'en prendrai pour Sacrificateurs et Lévites, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Car, de même que les nouveaux Cieux et la nouvelle terre que je crée, subsistent devant moi, dit l\'Éternel, ainsi subsisteront devant moi votre race et votre nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'Et de nouvelle lune en nouvelle lune, et de sabbat en sabbat, toute chair viendra se prosterner devant ma face, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'Et ils sortiront et verront les cadavres des hommes qui se rebellèrent contre moi, car leur ver ne mourra point, et leur feu ne s\'éteindra point, et ils seront en horreur à toute chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Paroles de Jérémie, fils d\'Hilkia, l\'un des sacrificateurs d\'Anathoth au pays de Benjamin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'à qui fut adressée la parole de l\'Éternel dans le temps de Josias, fils d\'Amon, roi de Juda, la treizième année de son règne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'et dans le temps de Jéhojakim, fils de Josias, roi de Juda, jusqu\'à la fin de la onzième année de Sédécias, fils de Josias, roi de Juda, jusqu\'à la déportation de Jérusalem, au cinquième mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'La parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Avant de te former dans les flancs de ta mère, je te connaissais, et avant que tu sortisses de son sein, je te consacrai, et je t\'établis prophète des nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Et je dis: Hélas! Seigneur, Éternel, voici, je ne sais point parler, car je suis un enfant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Et l\'Éternel me dit: Ne dis pas: « Je suis un enfant; » mais va vers quiconque je t\'enverrai, et dis tout ce que je t\'ordonnerai!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'N\'aie point peur devant eux! car je suis avec toi pour te délivrer, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Et l\'Éternel étendit sa main, et toucha ma bouche, et l\'Éternel me dit: Voici, je mets mes paroles en ta bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Vois, je te prépose en ce jour sur les peuples et sur les royaumes, pour arracher et pour abattre, pour perdre et pour détruire, pour édifier et pour planter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Et la parole de l\'Éternel me fut adressée en ces mots: Que vois-tu, Jérémie? Et je dis: Je vois un jet d\'amandier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Et l\'Éternel me dit: Tu as bien vu; car je veille sur ma parole pour y donner effet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Et la parole de l\'Éternel me fut adressée une seconde fois en ces mots: Que vois-tu? Et je dis: Je vois une chaudière qui bout, dans la direction du septentrion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Et l\'Éternel me dit: C\'est du septentrion que la calamité éclatera sur tous les habitants du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Car voici, je vais convoquer toutes les tribus des royaumes au septentrion, dit l\'Éternel, et ils viendront, et placeront chacun leur station à l\'avenue des portes de Jérusalem, et contre ses murailles tout à l\'entour, et contre toutes les villes de Juda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'et je prononcerai ma sentence contre eux à cause de toute leur méchanceté, parce qu\'ils m\'ont abandonné, et qu\'ils ont encensé d\'autres dieux, et adoré l\'ouvrage de leurs mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Mais toi, ceins tes reins, et te lève, et leur dis tout ce que je t\'ordonnerai; ne sois point timide devant eux, afin que je ne t\'intimide pas devant eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Et voici, je fais de toi en ce jour une ville forte, et une colonne de fer, et un mur d\'airain contre tout le pays, les rois de Juda, ses princes, ses sacrificateurs, et contre le peuple du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Et ils te feront la guerre, mais ils ne pourront rien contre toi; car je suis avec toi, dit l\'Éternel, pour te protéger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Va, et proclame aux oreilles de Jérusalem ces paroles: Ainsi parle l\'Éternel: Je me rappelle la piété de ta jeunesse, l\'amour de ton temps de fiancée, quand tu me suivais au désert, dans la terre qui n\'est pas ensemencée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'consacré à l\'Éternel, Israël était les prémices de son revenu; quiconque en mangeait, devenait coupable, et le malheur fondait sur lui, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Écoutez la parole de l\'Éternel, maison de Jacob, et toutes les familles de la maison d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Ainsi parle l\'Éternel: Qu\'est-ce que vos pères ont trouvé d\'injuste en moi, pour s\'éloigner de moi, et s\'en aller après les vaines idoles, et vivre dans la vanité?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Et ils n\'ont pas dit: Où est l\'Éternel qui nous ramena de la terre d\'Égypte, qui nous guida dans le désert, dans la terre aride et crevassée, dans la terre de la sécheresse et de l\'ombre de la mort, dans la terre où nul homme ne passe et où personne n\'habite?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Et je vous ai fait venir dans un pays de vergers, pour vous nourrir de ses fruits et de ses biens; mais vous êtes venus et avez souillé mon pays, et de mon héritage vous avez fait une abomination.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Les sacrificateurs n\'ont pas dit: « Où est l\'Éternel? » et les dépositaires de la Loi ne m\'ont point connu, et les pasteurs ont rompu avec moi, et les prophètes ont prophétisé au nom de Baal, et sont allés après ceux qui ne sont d\'aucun secours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'C\'est pourquoi je veux encore vous faire le procès, dit l\'Éternel, et faire le procès aux enfants de vos enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Passez en effet dans les îles de Cittim, et voyez! députez à Cédar, et observez bien, et voyez si là il y a rien de pareil!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Une nation change-t-elle de dieux? et pourtant ce ne sont pas des dieux. Et mon peuple a changé sa gloire contre ce qui est impuissant!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Cieux, étonnez-vous-en; frémissez et soyez stupéfaits! dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Car mon peuple a commis deux crimes: ils m\'ont abandonné, moi, la source des eaux vives, pour se creuser des citernes, des citernes percées qui ne gardent point les eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Israël est-il un esclave? ou un serf-né de la maison? Pourquoi en a-t-on fait une proie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Contre lui les lions rugissent, ils poussent leur cri, et ils désolent son pays; ses villes sont incendiées, il n\'y a plus d\'habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Même les enfants de Noph et de Tachphanès lui brouteront le crâne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Cela ne te vient-il pas de ce que tu abandonnas l\'Éternel, ton Dieu, lorsqu\'il voulait te guider dans la voie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Et maintenant, que fais-tu d\'aller en Egypte boire l\'eau du Nil? et que fais-tu d\'aller en Assyrie boire l\'eau du Fleuve?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Ta méchanceté te châtiera, et ta rébellion te punira, et tu sauras, tu verras que c\'est un mal et une amertume d\'abandonner l\'Éternel, ton Dieu, et de n\'avoir aucune crainte de moi, dit le Seigneur, l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Car dès longtemps tu as brisé ton joug, tu as rompu tes liens, et tu as dit: « Je ne veux pas servir! » Car sur toutes les collines élevées, et sous tous les arbres verts, tu t\'es livrée comme une prostituée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Et moi, je t\'avais plantée d\'une vigne excellente, d\'un plant tout pur; comment donc t\'es-tu changée en jets de vigne étrangère?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Oui, quand tu te laverais avec la lessive, et que tu prendrais beaucoup de savon, ton iniquité est toujours une tache devant moi, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Comment dirais-tu: « Je ne me suis pas souillée, je ne suis point allée après les Baals? » Regarde tes pas dans la vallée! Reconnais ce que tu as fait, jeune et légère chamelle, vagabonde en ses allures,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'onagre habituée au désert; dans l\'ardeur de ses désirs elle aspire l\'air.... qui calmera ses feux? Tous ceux qui la cherchent, n\'ont pas à se fatiguer; ils la trouvent pendant son mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Empêche ton pied de perdre sa chaussure, et ton gosier d\'être altéré! Mais tu dis: C\'en est fait! non! car j\'aime les étrangers, et je vais après eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Telle la honte du larron surpris, telle sera la honte de la maison d\'Israël, d\'eux, de leurs rois, de leurs princes, et de leurs sacrificateurs et de leurs prophètes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'qui disent au bois: « Tu es mon père! » et à la pierre: « Tu m\'as fait naître. » Car ils m\'ont tourné le dos, et non pas le visage; et au temps de leur détresse ils disent: « Lève-toi, et sauve-nous! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Et où sont tes dieux que tu t\'es faits? Qu\'ils se lèvent s\'ils peuvent te sauver, au temps de ta détresse! Car le nombre de tes villes est celui de tes dieux, Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Pourquoi me prenez-vous à partie? Tous, vous vous êtes détachés de moi, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'En vain j\'ai frappé vos fils; ils n\'ont point reçu la correction; votre épée s\'est assouvie sur vos prophètes, comme un lion destructeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Hommes de cet âge, considérez la parole de l\'Éternel! Ai-je été un désert pour Israël, ou un pays ténébreux? Pourquoi mon peuple dit-il: « Nous voulons errer à notre gré, et ne plus revenir à toi? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'La jeune fille oublie-t-elle sa parure, et la fiancée sa ceinture? Et mon peuple m\'oublie depuis des jours sans nombre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Que tu sais bien trouver ta route pour chercher des amours! Aussi, même aux crimes accoutumes-tu ta vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Jusque sur les pans de ta robe se trouve le sang des pauvres innocents; tu ne les as pas surpris faisant effraction, et malgré cela...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Cependant tu dis: « Comme je suis innocent, sa colère se détournera de moi. » Voici, je te ferai le procès, parce que tu dis: « Je n\'ai point péché. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Pourquoi tant de courses pour changer de route? De l\'Egypte aussi tu auras un affront, comme tu eus un affront de l\'Assyrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'De là aussi tu sortiras les mains sur la tête; car l\'Éternel réprouve ceux en qui tu te fies; et il ne te réussira pas de t\'unir à eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Il dit: Quand un homme répudie sa femme, et qu\'elle le quitte, et devient la femme d\'un autre, peut-il revenir à elle? le pays ne serait-il pas profané? Et toi, tu t\'es livrée à nombre d\'amants, et tu reviendrais auprès de moi? dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Lève les yeux vers les hauteurs, et vois! Où n\'as-tu pas été impudique? Sur les chemins tu les attendais, telle que l\'Arabe dans le désert, et tu souillas le pays par tes prostitutions et ta méchanceté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Aussi les rosées furent-elles supprimées, et les dernières pluies ne vinrent-elles pas; mais tu as eu un front de prostituée, et tu as refusé de rougir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Maintenant, n\'est-ce pas? tu me dis: « Mon père! tu fus l\'ami de ma jeunesse. Sera-t-Il toujours irrité?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'gardera-t-Il sa colère à jamais? » Voilà ce que tu dis, et tu commets le crime, et le consommes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Et l\'Éternel me parla dans le temps du roi Josias: Vois-tu ce qu\'a fait la rebelle Israël? Elle est allée sur toutes les hautes montagnes et sous tous les arbres verts, et elle s\'est prostituée là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Et je disais: Après avoir fait toutes ces choses elle reviendra à moi; mais elle n\'est point revenue. Et sa perfide sœur Juda l\'a vu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Et quoique pour cette raison, à cause de l\'adultère de la rebelle Israël, je l\'eusse répudiée, lui donnant sa lettre de divorce, j\'ai vu que cependant la perfide Juda, sa sœur, n\'a point eu de crainte, et est allée se prostituer elle aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Or cela était arrivé à cause de sa criante impudicité, car elle avait souillé le pays, et commis adultère avec la pierre et avec le bois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Malgré tout cela, sa perfide sœur Juda n\'est point revenue à moi de tout son cœur, mais avec hypocrisie, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Et l\'Éternel me dit: La rebelle Israël est innocente auprès de la perfide Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Va, et proclame ces paroles vers le nord et dis: Reviens, rebelle Israël! dit l\'Éternel; je ne prendrai point pour vous un air sombre, car je suis clément, dit l\'Éternel, et mon ressentiment n\'est pas éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Seulement reconnais ta faute, car tu t\'es détachée de l\'Éternel, ton Dieu, et tu as fais errer tes pas vers les étrangers sous tous les arbres verts, et vous n\'avez point obéi à ma voix, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Revenez, enfants rebelles, dit l\'Éternel; car je suis votre Souverain, et je veux vous reprendre, un par ville, et deux par famille, et vous ramener à Sion;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'et je vous donnerai des bergers selon mon cœur, qui vous paîtront avec sagesse et intelligence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Et quand un jour vous serez nombreux et multipliés dans le pays, dit l\'Éternel, alors on ne parlera plus de l\'arche de l\'alliance de l\'Éternel, elle ne viendra dans l\'esprit de personne, et on n\'y pensera plus; et on ne la regrettera plus, et on n\'en fera pas une autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Dans ce temps-là on appellera Jérusalem le trône de l\'Éternel, et tous les peuples s\'y rallieront au nom de l\'Éternel à Jérusalem, et ils ne marcheront plus d\'après la dureté de leur cœur mauvais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'En ces jours, la maison de Juda cheminera avec la maison d\'Israël, et elles viendront ensemble du pays du septentrion dans le pays dont je mis en possession vos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Je disais alors: Quel rang tu auras entre les fils! et je te donnerai un pays délicieux, le plus magnifique héritage parmi les armées des nations. Je disais aussi: Vous m\'appellerez « Mon père, » et vous ne vous détacherez pas de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Mais, comme une femme est infidèle à son amant, ainsi vous me fûtes infidèles, maison d\'Israël, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Sur les hauteurs une voix se fait entendre: ce sont les pleurs des enfants d\'Israël gémissant d\'avoir pris des voies détournées, d\'avoir oublié l\'Éternel, leur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Revenez, enfants rebelles, je veux réparer vos égarements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, '« Voici, nous venons à Toi, car tu es l\'Éternel notre Dieu. Oui, c\'est une déception que l\'abondance qui vient des collines, qui vient des montagnes; oui, c\'est dans l\'Éternel, dans notre Dieu, qu\'est la ressource d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Mais l\'infamie a consumé les profits de nos pères dès notre jeunesse, leurs brebis et leurs bœufs, leurs fils et leurs filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Nous sommes gisants dans notre infamie, et notre ignominie nous recouvre, car nous avons péché contre l\'Éternel notre Dieu, nous et nos pères, dès notre jeunesse jusques aujourd\'hui et nous n\'avons point obéi à la voix de l\'Éternel, notre Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Si tu reviens à moi, Israël, dit l\'Éternel, tu reviendras ici; et si tu ôtes tes abominations de devant moi, tu ne seras plus errant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'et si tu jures par « la vie de l\'Éternel, » selon la vérité, la droiture et la justice, les nations se serviront de son nom pour bénir, et se glorifieront de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Car ainsi parle l\'Éternel aux hommes de Juda et de Jérusalem:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Faites-vous des novales et ne semez point parmi les épines! Circoncisez-vous pour l\'Éternel, et enlevez le prépuce de vos cœurs, hommes de Juda, et habitants de Jérusalem, de peur que ma colère n\'éclate comme un feu, et ne consume sans que personne éteigne, à cause de la méchanceté de vos actions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Annoncez en Juda, et publiez à Jérusalem, et parlez, et sonnez de la trompette dans le pays, criez à pleine voix et dites: Rassemblez-vous, et allons dans les villes fortes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Tournez l\'étendard vers Sion, fuyez, ne vous arrêtez pas! Car du nord J\'amène la calamité et un grand désastre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Le lion sort de son fourré, et le destructeur des peuples part, il sort de son lieu, pour faire de ton pays un désert; tes villes seront détruites, dépeuplées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Aussi, ceignez le cilice, gémissez, et lamentez-vous, car l\'ardente colère de l\'Éternel ne s\'éloigne pas de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Et dans ce jour-là, dit l\'Éternel, le cœur manquera au roi et aux princes, et les sacrificateurs seront atterrés, et les prophètes seront stupéfaits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Alors je dis: Ah! Seigneur, Éternel, en vérité tu as trompé ce peuple et Jérusalem en disant: Vous serez sains et saufs! et cependant l\'épée pénètre jusqu\'à son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Dans ce temps-là, il sera dit à ce peuple et à Jérusalem: Un vent brûlant vient des collines du désert dans la direction de la fille de mon peuple, non point pour nettoyer, ni pour émonder,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'un vent plus fort que pour cela viendra de par moi; et alors à mon tour je prononcerai ma sentence contre eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Voici, Il s\'avance comme les nuées, et ses chars sont comme l\'ouragan, et ses chevaux plus légers que les aigles. « Malheur à nous, car nous sommes dévastés! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Purge de méchanceté ton cœur, Jérusalem, afin que tu sois sauvée! Jusques à quand séjourneront dans ton cœur tes pensées désastreuses?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Car une voix publie depuis Dan, et annonce un désastre depuis la montagne d\'Éphraïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Annoncez-le aux nations! Voici, publiez-le dans Jérusalem: des assiégeants arrivent d\'une terre lointaine, et ils poussent leur voix contre les villes de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Comme les gardes d\'un champ ils te cerneront; car elle s\'est révoltée contre moi, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Ta conduite et tes œuvres ont attiré ces choses sur toi; c\'est l\'effet de ta méchanceté; oui, cela est amer, oui, cela pénètre jusqu\'à ton cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, '« Mes entrailles! mes entrailles! je souffre dans les cellules de mon cœur; mon cœur bouillonne, je ne puis me taire; car tu entends, mon âme, le son de la trompette, le cri de guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Ruine sur ruine est annoncée, car tout le pays est désolé; tout à coup mes tentes sont détruites, en un instant mes pavillons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Jusques à quand verrai-je l\'étendard, ouïrai-je le son de la trompette? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, '– « C\'est que Mon peuple est en délire, il ne Me connaît pas; ce sont des fils insensés, destitués d\'intelligence; ce sont des sages pour faire le mal; mais pour faire le bien, ce sont des ignorants. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Je regarde la terre, et voici, elle est déserte et vide; et les Cieux, ils n\'ont plus leur lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Je regarde les montagnes, et voici, elles tremblent, et toutes les collines s\'ébranlent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Je regarde, et voici, il n\'y a point d\'homme, et tous les oiseaux des Cieux ont fui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Je regarde, et voici, le Carmel est un désert, et toutes ses villes sont détruites par l\'Éternel et par le feu de sa colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Car ainsi parle l\'Éternel: La dévastation couvrira le pays; mais je ne la ferai pas totale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Pour cela le pays est en deuil, et le ciel s\'obscurcit, parce que je l\'ai dit, je l\'ai arrêté, et je ne m\'en repens point, et n\'en reviendrai point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Au bruit des cavaliers et des archers toute ville est en fuite; on gagne les forêts, et on gravit les rochers; toute ville est abandonnée, il n\'y reste personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Et toi, ville désolée, que feras-tu? Quand même tu t\'habilles de pourpre, que tu te pares d\'une parure d\'or, que tu bordes de fard tes yeux, en vain t\'embellis-tu, les amants te dédaignent, ils en veulent à ta vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Car j\'entends comme la voix d\'une femme en travail, un cri d\'angoisse comme au premier enfantement: c\'est la voix de la fille de Sion; elle soupire, étend les bras: « C\'en est fait de moi! mon âme succombe sous les meurtriers! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Parcourez les rues de Jérusalem, et observez, et informez-vous, et cherchez dans ses places, si vous trouvez quelqu\'un, s\'il y a un homme qui fasse le bien, qui cherche la vérité: et elle recevra de moi son pardon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Que s\'ils jurent « par la vie de l\'Éternel, » c\'est encore un faux serment qu\'ils font.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Éternel, tes yeux ne voient-ils pas la vérité? Tu les frappes, et ils ne sentent pas; tu les détruis, ils refusent d\'en tirer instruction; ils ont un front plus dur que le roc, ils refusent de se convertir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Et je disais: Ce ne sont que les petits; ils sont égarés, parce qu\'ils ignorent la voie de l\'Éternel, la loi de leur Dieu:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'je veux aussi aller vers les Grands, et leur parler; car, pour eux, ils connaissent la voie de l\'Éternel, la loi de leur Dieu... Mais eux tous aussi ont brisé le joug, ont rompu les liens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'C\'est pourquoi de la forêt le lion fondra sur eux, le loup du soir les détruira, la panthère épiera leurs villes; quiconque en sortira, sera déchiré; car leurs rébellions sont nombreuses, et leurs révoltes multipliées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Pourquoi te pardonnerais-je? Tes fils m\'ont quitté, et ils jurent par des dieux qui ne sont pas; je reçus leurs serments, mais ils furent adultères, et firent foule dans la maison de la prostituée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Pareils à des étalons bien nourris, ils courent ça et là, ils hennissent, l\'un pour la femme de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Tout cela ne le punirai-je point, dit l\'Éternel, et d\'une nation pareille ne me vengerai-je point?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Escaladez ses murs, et saccagez, mais ne consommez pas la ruine! Arrachez ses sarments! car ce ne sont pas ceux de l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'car la maison d\'Israël et la maison de Juda m\'ont trahi, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Ils ont renié l\'Éternel et ils ont dit: « Il n\'est pas; la calamité ne viendra pas jusqu\'à nous, et nous ne verrons ni épée, ni famine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Les prophètes ne sont que du vent, ce n\'est pas Lui qui inspire leurs discours: ainsi leur soit-il fait! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'C\'est pourquoi, ainsi parle l\'Éternel, le Dieu des armées: Parce que vous avez émis cette parole, voici, je ferai de mes paroles en ta bouche une flamme, et de ce peuple, le bois, et elle les dévorera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Voici, j\'amène contre vous un peuple du lointain, maison d\'Israël, dit l\'Éternel; c\'est un peuple fort, c\'est un peuple antique, un peuple dont tu ignores la langue, et dont tu ne comprendras pas les discours;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'son carquois est comme un tombeau ouvert; tous ils sont des héros.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Ils dévoreront tes moissons et ton pain, ils dévoreront tes fils et tes filles, ils dévoreront tes brebis et tes bœufs, ils dévoreront ta vigne et ton figuier, ils détruiront tes villes fortes où tu mets ta sûreté, avec l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Mais même dans ces jours, dit l\'Éternel, je ne ferai pas de vous extermination.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Et si vous dites: « Pourquoi l\'Éternel, notre Dieu, nous a-t-Il fait tout cela? » dis-leur: « Comme vous m\'avez quitté, et que vous avez servi des dieux étrangers dans votre pays, ainsi vous servirez des étrangers dans un pays qui n\'est pas le vôtre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Publiez ceci dans la maison de Jacob, et annoncez-le en Juda, disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Entends-le, nation folle et dénuée de sens, qui as des yeux et ne vois pas, des oreilles et n\'entends pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Ne me craindrez-vous pas, dit l\'Éternel, ne tremblerez-vous pas devant moi? moi qui mis le sable pour limite de la mer, bornes éternelles qu\'elle ne franchit pas; que ses vagues s\'agitent, elles sont impuissantes; qu\'elles bouillonnent, elles ne les franchissent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Mais ce peuple a un cœur réfractaire et rebelle; ils désertent, ils s\'en vont,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'et ils ne disent point en leur cœur: Ah! craignons l\'Éternel, notre Dieu, qui nous donne les pluies, les premières et les secondes pluies dans leur saison, et qui maintient fixes nos semaines de moisson.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Vos iniquités ont interverti cet ordre, et vos péchés ont éloigné ces biens de vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'car il se trouve dans mon peuple des méchants: ils épient comme l\'oiseleur qui se baisse, ils tendent des pièges, et y prennent des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Comme une cage remplie d\'appâts, leurs maisons sont remplies de fraude; c\'est ainsi qu\'ils croissent et s\'enrichissent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'ils ont un embonpoint brillant, ils outre-passent le mal même; ils ne défendent pas la cause, la cause de l\'orphelin, et ils prospèrent, et au droit des pauvres ils ne font pas droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Tout cela ne le punirai-je point, dit l\'Éternel, et d\'une nation pareille ne me vengerai-je point?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Des atrocités et des horreurs se font dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Les prophètes prophétisent le mensonge, et les prêtres règnent sous leur conduite, et mon peuple l\'aime ainsi. Et que ferez-vous après ceci?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Fuyez, enfants de Benjamin, du milieu de Jérusalem, et en Thécoa sonnez de la trompette, et à Beth-Carem élevez des signaux! Car un malheur nous menace du nord, et un grand désastre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Belle et délicate fille de Sion, je vais te détruire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Sur elle marchent les bergers et leurs troupeaux; ils planteront leurs tentes tout à l\'entour, brouteront chacun leur quartier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, '« Inaugurez son assaut! Debout! attaquons en plein jour! quel contre-temps pour nous! car le jour baisse, et déjà les ombres du soir s\'allongent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Allons! escaladons de nuit, et détruisons ses palais! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Car ainsi parle l\'Éternel des armées: Coupez le bois, et contre Jérusalem élevez les terrasses; c\'est la ville à punir; elle est tout injustice en son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Comme une fontaine fait jaillir les eaux, ainsi fait-elle jaillir le mal; j\'y entends incessamment la violence et la ruine, la douleur et les coups.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Amende-toi, Jérusalem, pour que mon âme ne se détache pas de toi, que je ne te rende pas un désert, un pays inhabité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Ainsi parle l\'Éternel des armées: On grappillera comme une vigne les restes d\'Israël. Mets et remets la main comme le vendangeur à sa corbeille!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'A qui parlerai-je, et qui sommerai-je pour qu\'on écoute? Voici, leur oreille est incirconcise, et ils ne sauraient entendre. Voici, la parole de l\'Éternel a été pour eux une dérision, ils n\'ont aucun goût pour elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Mais la colère de l\'Éternel me pénètre, je suis las de la contenir. Verse-la sur l\'enfant dans la rue et sur le cercle des jeunes gens à la fois; car et l\'homme et la femme seront pris, le vieillard et l\'homme comblé de jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Leurs maisons seront dévolues à d\'autres, et leurs champs et leurs femmes aussi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'car j\'étendrai ma main sur les habitants du pays, dit l\'Éternel; car du petit au grand tous sont avides de gain; et du prophète au sacrificateur tous usent de fraudes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'et ils traitent la plaie de mon peuple comme chose légère, disant: « Salut! salut! » tandis qu\'il n\'y a point de salut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Ils seront dans l\'opprobre, car ils commettent l\'abomination; mais ils ne rougissent pas, et ne connaissent pas la honte. Aussi tomberont-ils avec ceux qui tombent, et au jour de mes châtiments ils seront renversés, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Ainsi parle l\'Éternel: Tenez-vous sur les routes, et regardez, et demandez quels sont les chemins d\'autrefois, quelle est la bonne voie, et marchez-y, et vous trouverez du repos pour votre âme!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Mais ils disent: « Nous n\'y marcherons point. » Et j\'ai mis près de vous des sentinelles [pour vous dire]: Soyez attentifs au son de la trompette! Mais ils disent: « Nous n\'y serons point attentifs. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Aussi, écoutez, nations, apprenez, assemblée des peuples, ce qui en est d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Terre, entends-le! voici, je ferai arriver sur ce peuple les maux, fruits de ses pensées, car ils ne sont point attentifs à mes paroles, et ils méprisent ma loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Que me fait cet encens venu de Séba, et ce roseau odorant apporté d\'un pays lointain? Vos holocaustes ne me plaisent point, et vos sacrifices ne me sont point agréables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Aussi, ainsi parle l\'Éternel: Voici, je mettrai devant ce peuple des achoppements qui feront tomber à la fois les pères et les fils, le voisin et son ami, et ils périront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Ainsi parle l\'Éternel: Voici venir un peuple de la région du Nord, et une grande nation se lève de l\'extrémité de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'ils manient l\'arc et le javelot; ils sont cruels et sans pitié; leur voix, comme la mer, gronde, et sur des chevaux ils sont montés, rangés comme un seul homme en bataille contre toi, fille de Sion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Nous en entendons la rumeur, nos mains défaillent, l\'anxiété nous saisit, l\'angoisse de l\'enfantement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Ne sors point dans les champs, et ne va pas sur les chemins, car l\'épée de l\'ennemi, la terreur est partout!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Fille de mon peuple, ceins le cilice, et roule-toi dans la poussière, prends le deuil comme pour un fils unique, gémis amèrement! car soudain sur nous viendra la destruction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Je t\'avais établi sentinelle de mon peuple dans une vedette, pour voir et examiner leurs voies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Tous ils sont rebelles et réfractaires, calomniateurs, de l\'airain et du fer; tous ils sont dépravés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Le soufflet est brûlant, par le feu le plomb est consumé, vainement on épure, on épure, les méchants ne sont point séparés:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'on les appelle argent réprouvé, car l\'Éternel les a réprouvés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'La parole qui fut adressée à Jérémie de la part de l\'Éternel, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Tiens-toi dans la porte de la maison de l\'Éternel, et proclames-y ces paroles, et dis: Écoutez la parole de l\'Éternel, vous tous les hommes de Juda, qui entrez par ces portes pour adorer l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Amendez votre conduite et vos œuvres, et je vous ferai habiter en ce lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Ne vous fiez pas aux mensonges de ceux qui disent: C\'est ici le Temple de l\'Éternel, le Temple de l\'Éternel, le Temple de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Car, si vous amendez votre conduite et vos œuvres, si vous exercez la justice à l\'égard des uns et des autres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'si vous n\'opprimez pas l\'étranger, la veuve et l\'orphelin, si vous ne répandez pas le sang innocent dans ce lieu, et si vous n\'allez pas après d\'autres dieux à votre détriment,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'alors je vous ferai habiter en ce lieu dans ce pays que je donnai à vos pères, de l\'éternité à l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Voici, vous avez confiance en des mensonges qui ne profitent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Quoi! dérober, tuer, commettre adultère, faire des faux serments, encenser Baal, aller après d\'autres dieux que vous ne connaissez pas!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'et puis vous venez et vous vous présentez devant moi dans cette maison appelée de mon nom, et vous dites: « Nous sommes sauvés!... » avec l\'intention de commettre toutes ces abominations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Est-elle une caverne de voleurs, cette maison appelée de mon nom, à vos yeux? Je le vois moi-même, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Mais allez donc à ma résidence qui fut à Silo, où je faisais habiter mon nom jadis, et voyez comment je l\'ai traitée à cause de la méchanceté de mon peuple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Or maintenant, puisque vous avez fait toutes ces actions, dit l\'Éternel, et que je vous ai parlé dès le matin, et que vous n\'avez pas écouté, et que je vous ai appelés, et que vous n\'avez pas répondu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'je traiterai cette maison appelée de mon nom, sur laquelle vous vous fiez, et le pays que je donnai à vous et à vos pères, comme j\'ai traité Silo,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'et je vous chasserai de ma présence, comme j\'en ai chassé tous vos frères, toute la race d\'Éphraïm.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Mais toi, ne prie pas pour ce peuple, et ne m\'adresse pour eux ni supplique, ni prière, et ne me fais point d\'instances; car je ne t\'écouterai pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Ne vois-tu pas ce qu\'ils font dans les villes de Juda et dans les rues de Jérusalem?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Les enfants ramassent du bois, et les pères allument le feu, et les femmes pétrissent la pâte pour faire des gâteaux à la reine des Cieux, et répandre des libations en l\'honneur des dieux étrangers, afin de me causer du déplaisir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Est-ce à moi qu\'ils causent le déplaisir? dit l\'Éternel; n\'est-ce pas à eux-mêmes, afin d\'avoir la honte sur leurs fronts?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'C\'est pourquoi, ainsi parle le Seigneur, l\'Éternel: Ma colère et ma fureur s\'épancheront sur ce lieu, sur l\'homme et sur le bétail, sur les arbres de la campagne et sur les fruits de la terre: elle brûlera, et ne s\'éteindra point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Ajoutez vos holocaustes à vos sacrifices, et mangez-en la chair!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Car je n\'adressai à vos pères, le jour où je les tirai du pays d\'Egypte, ni parole ni ordre quant à des holocaustes et à des sacrifices.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Mais voici l\'ordre que je leur donnai, et ce que je dis: Obéissez à ma voix, et je serai votre Dieu, et vous serez mon peuple, et suivez en plein la voie que je vous trace, afin d\'avoir le bonheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Mais ils n\'obéirent point, et ne prêtèrent point l\'oreille; et ils marchèrent en suivant les conseils et l\'obstination de leur cœur mauvais, et ils me présentèrent le dos et non pas le visage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Du jour où vos pères sortirent du pays d\'Egypte jusqu\'aujourd\'hui, je vous déléguai tous mes serviteurs, les prophètes, journellement, dès le matin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'mais ils n\'ont ni entendu, ni prêté l\'oreille; ils roidirent leur col, et ils firent pis que leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Dis-leur toutes ces paroles! ils ne t\'écouteront point; et crie-leur! ils ne te répondront pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Alors tu leur diras: C\'est ici le peuple qui n\'a point obéi à la voix de l\'Éternel son Dieu, et n\'a pas reçu la correction; la vérité est disparue, elle est bannie de leur bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Rase ta chevelure, [Jérusalem], et jette-la; et du haut des collines élève ta complainte! car l\'Éternel a rejeté et réprouvé la génération, objet de sa colère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'car les enfants de Juda ont fait ce qui est mal à mes yeux, dit l\'Éternel; ils ont placé leurs infâmes idoles dans la maison appelée de mon nom, pour la souiller;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'et ils ont élevé les tertres de Topheth dans la vallée des fils de Hinnom, pour brûler au feu leurs fils et leurs filles, ce que je n\'avais point commandé, et qui n\'était point venu dans ma pensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Aussi, voici, des jours viennent, dit l\'Éternel, où l\'on ne dira plus Topheth, ni vallée des fils de Hinnom, mais vallée du carnage, et on enterrera à Topheth faute de place,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'et les cadavres de ce peuple seront la pâture des oiseaux des Cieux et des bêtes de la terre, que personne n\'effarouchera,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'et je ferai cesser dans les villes de Juda et dans les rues de Jérusalem les chants de réjouissance et les chants d\'allégresse, les chants du fiancé et les chants de la fiancée; car le pays sera une solitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'Dans le même temps, dit l\'Éternel, on exhumera de leurs tombeaux les os des rois de Juda, et les os de ses princes, et les os des sacrificateurs, et les os des prophètes, et les os des habitants de Jérusalem;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'et on les étendra devant le soleil, et la lune et toute l\'armée des Cieux, qu\'ils ont aimés, et qu\'ils ont servis, et qu\'ils ont suivis, et qu\'ils ont cherchés, et qu\'ils ont adorés; ils ne seront ni recueillis, ni inhumés; ils seront un fumier sur la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'et la mort sera préférée à la vie par tous ceux qui resteront de cette race perverse, dans tous les lieux où j\'aurai disséminé leurs restes, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Dis-leur encore: Ainsi parle l\'Éternel: Si l\'on tombe, ne se relève-t-on pas? Si l\'on dévie, ne revient-on pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Pourquoi ce peuple, Jérusalem, dévie-t-il sans jamais revenir? Ils s\'obstinent dans leur tromperie; ils refusent de se convertir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'J\'observai et j\'écoutai; ils ne parlent pas bien; aucun ne se repent de sa méchanceté, et ne dit: Qu\'ai-je fait? Tous ils s\'écartent dans leur course, comme un cheval élancé dans la mêlée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Même la cigogne dans les airs connaît sa saison; et la tourterelle, l\'hirondelle et la grue observent le temps de leur retour, et mon peuple ne connaît point la loi de l\'Éternel! Comment osez-vous dire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Nous sommes sages, nous savons la loi de l\'Éternel?.... Certes le style menteur des Scribes en fait un mensonge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Ils seront confus les sages, ils seront atterrés, ils seront enveloppés. Voici, ils ont méprisé la parole de l\'Éternel: quelle sagesse est la leur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'C\'est pourquoi je donnerai leurs femmes à d\'autres, et leurs champs à de nouveaux possesseurs; car du petit au grand tous sont désireux du gain, du prophète au sacrificateur tous commettent des fraudes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Et ils traitent la plaie de mon peuple comme chose légère, disant: « Salut! salut! » et il n\'y a point de salut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Ils seront confondus, car ils font des abominations; mais ils ne rougissent point, ils ne connaissent point la honte; aussi tomberont-ils avec ceux qui tombent, au jour des châtiments ils seront renversés, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Je les détruirai, dit l\'Éternel; il n\'y aura plus de raisins au cep, ni de figues au figuier, et la feuille se flétrira; et je leur donnerai qui les envahira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, '« Pourquoi nous arrêter? Rassemblez-vous, et allons dans les villes fortes, et y périssons, puisque l\'Éternel, notre Dieu, veut notre perte, et qu\'il nous abreuve d\'eaux vénéneuses, parce que nous avons péché contre l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Nous attendions le salut, mais il ne vient rien de bon; le temps de la guérison, et voici l\'épouvante. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'De Dan se fait entendre le frémissement de leurs chevaux; au hennissement de leurs coursiers toute la terre tremble; ils arrivent et dévorent le pays et ce qu\'il renferme, les villes et leurs habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Oui, voici, je vous envoie des serpents, des aspics, contre lesquels le charme est nul, et ils vous piqueront, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, '[Où trouver] la sérénité au lieu du chagrin? En moi mon cœur est languissant!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Voici, les cris de détresse de mon peuple d\'une terre lointaine se font entendre: « L\'Éternel n\'est-Il plus en Sion, ou son Roi n\'y est-Il plus? » – « Pourquoi m\'ont-ils irrité par leurs idoles, par les vanités de l\'étranger? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, '– « La moisson est finie, l\'été est passé, et nous ne sommes pas secourus! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'De la meurtrissure de mon peuple je suis meurtri, je mène deuil, l\'horreur m\'a saisi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'N\'y a-t-il point de baume en Galaad? n\'y a-t-il point de médecin? Pourquoi ne bande-t-on pas la plaie de mon peuple?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Oh! que ma tête devienne eau, et mes yeux une fontaine de larmes! et je pleurerai le jour et la nuit le carnage de mon peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Oh! qu\'on me donne au désert l\'étape du voyageur! et je quitterai mon peuple, et m\'en irai loin d\'eux, car ce sont tous des adultères, un amas d\'infidèles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Ils arment leur langue, comme un arc, du mensonge, et ce n\'est pas par la vérité qu\'ils règnent dans le pays, car ils vont de malice en malice, et ils ne me connaissent pas, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Gardez-vous les uns des autres, et ne vous fiez à aucun de vos frères, car tous les frères cherchent à se supplanter, et chaque ami va calomniant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Chacun trompe son ami, et ne parle pas vrai; ils forment leur langue à proférer le mensonge, ils prennent de la peine pour faire le mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Tu habites au sein de la fausseté; c\'est par fausseté qu\'ils refusent de me connaître, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Aussi, ainsi parle l\'Éternel des armées: Je veux les passer par le creuset et les soumettre à l\'épreuve. Et, que faire d\'autre à cause de la fille de mon peuple?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Leur langue est un dard meurtrier, elle profère le mensonge; de leur bouche ils disent paix! à leur prochain, et dans leur cœur ils lui dressent des embûches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Pour toutes ces choses ne les punirai-je pas, dit l\'Éternel, et d\'une telle nation mon âme ne se vengera-t-elle pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Sur les montagnes j\'élève ma plainte et mes pleurs, et sur les pacages du désert, mes lamentations, car ils sont brûlés, personne ne les parcourt plus, on n\'y entend plus la voix des troupeaux, et les oiseaux du ciel et les bêtes ont fui, sont partis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Et je ferai de Jérusalem un monceau de pierres, un gîte des chacals, et des villes de Juda je ferai un désert sans habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'S\'il y a quelque sage, qu\'il comprenne ces choses! s\'il en est un à qui l\'Éternel ait parlé, qu\'il le déclare!... Pourquoi ce pays est-il ruiné, brûlé comme un désert où personne ne passe?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'L\'Éternel a dit: C\'est pour avoir abandonné ma loi que j\'avais mise devant eux, pour n\'avoir pas obéi à ma voix, et ne l\'avoir pas suivie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'et pour avoir marché selon l\'obstination de leur cœur et à la suite des Baals, comme leurs pères le leur ont enseigné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'C\'est pourquoi, ainsi parle l\'Éternel des armées, Dieu d\'Israël: Voici, je nourrirai ce peuple d\'absinthe, et l\'abreuverai d\'eaux vénéneuses,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'et je les disséminerai parmi des peuples inconnus à eux et à leurs pères, et j\'enverrai derrière eux l\'épée, jusqu\'à ce que je les aie exterminés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Ainsi parle l\'Éternel des armées: Cherchez, et appelez les pleureuses, et qu\'elles viennent! et envoyez vers les habiles, et qu\'elles arrivent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'qu\'elles se hâtent et élèvent sur nous leurs complaintes, pour que les larmes tombent de nos yeux, et que l\'eau coule de nos paupières!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Car une voix plaintive part de Sion: « Quelle désolation est la nôtre! Nous sommes au dernier degré de la honte, car il nous faut quitter le pays, car ils ont renversé nos demeures. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Femmes, écoutez la parole de l\'Éternel, et que votre oreille donne accès à la parole de sa bouche! Enseignez à vos filles des lamentations, et que la femme enseigne des complaintes à sa compagne!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Car la mort entre par nos fenêtres, elle monte dans nos palais, et vient arracher les enfants de la rue, et les jeunes gens des places.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Dis: Tel est l\'arrêt de l\'Éternel: les cadavres des hommes tomberont comme du fumier sur un champ, et comme la gerbe derrière le moissonneur, laquelle personne ne relève.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Ainsi parle l\'Éternel: Que le sage ne se glorifie pas de sa sagesse, et que le fort ne se glorifie pas de sa force, et que le riche ne se glorifie pas de sa richesse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'mais si l\'on se glorifie, que ce soit d\'avoir l\'intelligence et de me connaître; car je suis l\'Éternel qui fais grâce, droit et justice dans le pays, car c\'est à cela que je prends plaisir, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Voici, des jours viennent, dit l\'Éternel, où je châtierai tous les circoncis avec les incirconcis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'l\'Egypte et Juda, Edom et les fils d\'Ammon, et Moab, et tous ceux qui se rasent les tempes, et ceux qui habitent le désert, car toutes les nations sont incirconcises, et toute la maison d\'Israël a le cœur incirconcis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Écoutez la parole que vous dit l\'Éternel, à vous, maison d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Ainsi parle l\'Éternel: Ne pratiquez point la voie des nations, et des signes du ciel ne vous épouvantez pas, parce que les nations s\'en épouvantent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Car le culte des nations est une vanité. C\'est du bois coupé dans la forêt, travaillé par la main du sculpteur avec la hache;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'il le pare d\'argent et d\'or, le fixe avec des clous et des marteaux, pour qu\'il ne vacille pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Comme le palmier ils sont arrondis, mais ils ne parlent pas; on les porte; car ils ne marchent pas. N\'ayez point peur d\'eux, car ils ne sauraient nuire, et faire du bien n\'est pas en leur puissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Nul n\'est ton égal, Éternel; tu es grand, et ton nom est grand en puissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Qui ne te craindrait, Roi des nations? car cela t\'appartient; car entre tous les sages des peuples, et dans tous leurs empires personne n\'est ton égal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Et tous ensemble ils sont stupides et insensés: vaine doctrine! c\'est du bois!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'L\'argent battu est amené de Tarsis, et l\'on apporte d\'Uphaz l\'or que travaillent le sculpteur et la main de l\'orfèvre; la pourpre rouge et la pourpre bleue les habillent; ils sont tous un travail de l\'ouvrier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Mais l\'Éternel est un Dieu qui est vérité; Il est un Dieu vivant, et un Roi éternel; à sa colère la terre tremble, et les nations ne soutiennent point son courroux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Vous leur parlerez en ces termes: Les dieux qui n\'ont point fait le ciel et la terre, seront exterminés de la terre et de dessous les Cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Il a fait la terre par sa puissance, fondé le monde par sa sagesse, et déployé les Cieux par son intelligence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Au son de sa voix les eaux s\'amassent dans les Cieux, et Il attire les vapeurs des bouts de la terre, Il envoie les éclairs avant la pluie, et fait sortir les vents de ses magasins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Tout homme est stupide faute de le connaître; pour chaque fondeur ses idoles sont un sujet de honte, car l\'image fondue par lui est un mensonge, et elle ne respire pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'C\'est une vanité, une œuvre de la tromperie; au jour de leur châtiment elles seront détruites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Il ne leur ressemble pas Celui qui est la part de Jacob, car Il a tout formé, et Israël est sa tribu d\'héritage, L\'Éternel des armées est son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Enlève du pays tes bagages, ô toi qui es en état de siège!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Car ainsi parle l\'Éternel: Voici, cette fois je vais lancer avec la fronde les habitants du pays, et je les y serrerai, afin qu\'ils atteignent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, '« Malheureuse! je suis brisée! ma plaie est douloureuse! Toutefois je dis: Oui, ce que j\'ai à souffrir, je le subirai!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Ma tente est détruite, et tous mes cordages sont rompus, mes fils m\'ont quittée, je ne les ai plus; personne ne tendra plus ma tente, et ne relèvera mes pavillons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Car les pasteurs s\'étaient abrutis, et ils n\'ont point cherché l\'Éternel: c\'est pour cela qu\'ils n\'ont point prospéré, et que tout leur troupeau a été dispersé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Une rumeur se fait entendre! le voici, il arrive avec un grand fracas de la région du Nord, pour réduire les villes de Juda en un désert, séjour des chacals.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, '« Je sais, Éternel, que l\'homme n\'est pas maître de sa voie, que l\'homme qui marche n\'a pas le pouvoir de diriger ses pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Châtie-moi, Éternel, mais équitablement, et non en ta colère, afin de ne pas m\'anéantir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Verse ta fureur sur les nations qui ne te connaissent pas, et sur les tribus qui n\'invoquent point ton nom; car elles ont dévoré Jacob, elles l\'ont dévoré et exterminé, et elles ont ravagé son séjour. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'La parole qui fut adressée à Jérémie de par l\'Éternel en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Écoutez les paroles de cette alliance, et dites-les aux hommes de Juda et aux habitants de Jérusalem!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Et tu leur diras: Ainsi parle l\'Éternel, Dieu d\'Israël: Maudit l\'homme qui n\'écoute pas les paroles de cette alliance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'que je prescrivis à vos pères le jour où je les tirai du pays d\'Egypte, du fourneau de fer, en disant: Obéissez à ma voix, et faites tout ce que je vous commanderai, et vous serez mon peuple, et je serai votre Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'pour que j\'accomplisse le serment que je fis à vos pères, de leur donner le pays découlant de lait et de miel, comme [vous le voyez] aujourd\'hui. Et je répondis et dis: Ainsi soit-il, Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Et l\'Éternel me dit: Proclame toutes ces paroles dans les villes de Juda et dans les rues de Jérusalem, disant: Écoutez les paroles de cette alliance, et exécutez-les.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Car je sommai vos pères dès le jour où je les tirai du pays d\'Egypte, jusqu\'aujourd\'hui, les sommant dès le matin et disant: Obéissez à ma voix!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Mais ils n\'ont ni obéi, ni prêté l\'oreille, et ils ont marché chacun suivant l\'obstination de son cœur mauvais; aussi j\'exécuterai sur eux toutes les paroles de cette alliance que je leur commandai d\'observer, et qu\'ils n\'ont point observée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Et l\'Éternel me dit: Il existe une conjuration entre les hommes de Juda et les habitants de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Ils retournent aux péchés de leurs premiers pères qui refusèrent d\'obéir à mes paroles, et suivirent d\'autres dieux pour les servir: la maison d\'Israël et la maison de Juda ont rompu l\'alliance que j\'avais traitée avec leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Aussi, ainsi parle l\'Éternel: Voici, j\'amène sur vous des maux d\'où vous ne pourrez sortir; et ils crieront vers moi, mais je ne les écouterai pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Qu\'elles aillent donc, les villes de Juda, et les habitants de Jérusalem! et qu\'ils crient aux dieux qu\'ils encensent; mais ils ne leur aideront point au moment de leur malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Car tel le nombre de tes villes, tel est le nombre de tes dieux, Juda, et autant il y a de rues à Jérusalem, autant vous avez élevé d\'autels à l\'infamie, d\'autels pour encenser Baal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Mais toi, n\'intercède pas pour ce peuple, et en sa faveur n\'élève ni supplication, ni prière, car je n\'écouterai point quand ils m\'invoqueront à cause de leurs maux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Qu\'y a-t-il pour mon bien-aimé dans ma maison? La foule y fait le crime. La chair sacrée te laissera à découvert, quand tes maux arriveront; c\'est alors que tu seras alarmé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Olivier verdoyant, beau de son fruit aimable, tel est le nom que tu reçus de l\'Éternel. Au bruit d\'un grand fracas Il allume le feu autour de lui, et l\'on brise ses rameaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'et l\'Éternel des armées qui te planta, t\'annonce des calamités à cause de la méchanceté qu\'ont montrée la maison d\'Israël et la maison de Juda, pour m\'irriter en encensant Baal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'L\'Éternel m\'a informé, et j\'ai su..., c\'est alors que Tu as mis pour moi leurs œuvres en évidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Cependant j\'étais comme l\'agneau familier que l\'on mène à la tuerie, et je ne me doutais pas qu\'ils méditassent des plans contre moi: « Détruisons l\'arbre avec son fruit, et extirpons-le de la terre des vivants, et que son nom ne soit plus rappelé! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Mais l\'Éternel des armées est un juste Juge; Il sonde les reins et le cœur. Je serai témoin de la vengeance que tu tireras d\'eux, car c\'est à Toi que je me suis ouvert de mes griefs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Aussi, voici ce que prononce l\'Éternel contre les gens d\'Anathoth qui en veulent à ma vie et disent: « Ne prophétise plus au nom de l\'Éternel, si tu veux ne pas mourir de notre main! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Aussi, voici ce que l\'Éternel des armées prononce: Voici, je vais les châtier: les jeunes hommes périront par l\'épée, et leurs fils et leurs filles périront par la famine;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'et rien ne restera d\'eux; car je vais amener des maux sur les hommes d\'Anathoth, au temps de leur châtiment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Tu as la justice pour toi, Éternel, quand je plaide contre toi, cependant je dois te prendre à partie. Pourquoi la voie des impies est-elle heureuse, pourquoi les perfides infidèles vivent-ils tranquilles?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Tu les as plantés, ils ont pris racine, ils croissent, et portent du fruit. Tu es près de leur bouche, et loin de leur cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Mais, Éternel, tu me connais, tu me vois, et tu éprouves ce que mon cœur est pour toi. Entraîne-les comme des brebis à la tuerie, et dévoue-les pour la journée du carnage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Jusques à quand le pays sera-t-il dans le deuil, et l\'herbe de toute la campagne sera-t-elle desséchée? A cause de la méchanceté des habitants, les quadrupèdes et les oiseaux ont disparu. Car ils disent: Il ne verra pas notre fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, '« Si tu cours avec des piétons et qu\'ils te fatiguent, comment lutteras-tu avec des cavaliers? Et tu as de l\'assurance dans un pays en paix! mais que feras-tu dans [les bois,] l\'orgueil du Jourdain?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Car même tes frères et la maison de ton père, même eux te haïssent, même eux ils crient après toi: Il a assez vécu! Ne les crois pas, quand même ils te diraient de bonnes paroles! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, '« J\'ai quitté ma maison, j\'ai fait abandon de mon héritage; j\'ai livré l\'amour de mon âme aux mains de ses ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Mon héritage a été envers moi comme un lion dans la forêt; il pousse contre moi ses rugissements, c\'est pourquoi je le hais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Mon héritage est pour moi une bête farouche, une hyène; aussi les bêtes farouches le cerneront. Sus! rassemblez toutes les bêtes des champs, amenez-les à la curée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Des bergers nombreux dévastent ma vigne, foulent mon domaine, font de mon délicieux domaine un désert inculte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'On en fait une désolation; désolé, il est en deuil de moi; tout le pays est désolé, parce que personne n\'est rentré en lui-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Franchissant toutes les collines du désert, les dévastateurs arrivent, car l\'épée de l\'Éternel dévore le pays d\'un bout à l\'autre bout; il n\'y a de salut pour rien de ce qui est chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Ils ont semé du froment, et ils moissonnent des ronces: ils se sont épuisés, et ils n\'ont aucun profit. Soyez donc confus de vos récoltes à cause de la colère de l\'Éternel qui s\'est allumée! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Ainsi prononce l\'Éternel sur tous mes méchants voisins, qui se sont attaqués à mon héritage que j\'ai donné en propre à mon peuple d\'Israël. Voici, je vais les arracher de leur pays, et je vais arracher la maison de Juda du milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Mais, après que je les aurai arrachés, je reprendrai pitié d\'eux, et je les ramènerai chacun dans son héritage, et chacun dans son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Et, s\'ils apprennent les voies de mon peuple, de telle sorte qu\'ils jurent par mon nom, « par la vie de l\'Éternel! » de même qu\'ils enseignèrent à mon peuple à jurer par Baal, ils feront partie de l\'édifice de mon peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Mais, s\'ils n\'obéissent pas, j\'extirperai un tel peuple, je l\'extirperai et le détruirai, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Ainsi me parla l\'Éternel: Va, et t\'achète une ceinture de lin, et applique-la à tes reins, mais ne la mets pas dans l\'eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Et j\'achetai la ceinture conformément à la parole de l\'Éternel, et je l\'appliquai à mes reins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Et la parole de l\'Éternel me fut adressée pour la seconde fois, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Prends la ceinture que tu as achetée, et qui est autour de tes reins, et lève-toi, va vers l\'Euphrate, et là, cache-la dans une fente de rocher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Et j\'allai, et je la cachai près de l\'Euphrate, comme me l\'ordonnait l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Et au bout de plusieurs jours, l\'Éternel me dit: Lève-toi, va vers l\'Euphrate, et prends-y la ceinture que je t\'ai ordonné d\'y cacher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Et j\'allai vers l\'Euphrate, et je creusai, et je pris la ceinture de l\'endroit où je l\'avais cachée; et voici, la ceinture était gâtée, et elle n\'était plus bonne à rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Ainsi parle l\'Éternel: C\'est ainsi que je détruirai la magnificence de Juda, et la magnificence de Jérusalem, la grande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Ce peuple méchant, qui refuse d\'écouter mes paroles, qui suit l\'obstination de son cœur, et qui court après d\'autres dieux, pour les servir et les adorer, il sera comme cette ceinture qui n\'est plus bonne à rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Car de même que la ceinture est attachée aux reins d\'un homme, ainsi je m\'étais attaché toute la maison d\'Israël et toute la maison de Juda, dit l\'Éternel, pour qu\'elles fussent mon peuple, et ma renommée, et ma gloire, et mon honneur; mais ils n\'ont pas obéi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Et tu leur diras cette parole: Ainsi parle l\'Éternel, Dieu d\'Israël: Toutes les cruches seront remplies de vin. Mais ils te diront: Ne savons-nous pas que toutes les cruches se remplissent de vin?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Dis-leur alors: Ainsi parle l\'Éternel: Voici, je remplirai tous les habitants de ce pays, et les rois assis sur le trône de David, et les sacrificateurs, et les prophètes, et tous les habitants de Jérusalem, d\'enivrement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Et je les briserai les uns contre les autres, pères et fils ensemble, dit l\'Éternel; je n\'ai ni miséricorde, ni compassion, ni pitié qui m\'empêche de les mettre en pièces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Écoutez et prêtez l\'oreille! dépouillez tout orgueil! car l\'Éternel parle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Rendez gloire à l\'Éternel, votre Dieu, avant qu\'il envoie les ténèbres, et avant que vos pieds heurtent contre les montagnes de la nuit, et qu\'il change la lumière que vous attendez en une ombre de mort, et en une morne obscurité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Et si vous n\'écoutez pas, alors dans le secret je déplorerai votre orgueil, mes yeux pleureront et répandront des larmes, parce que le troupeau de l\'Éternel s\'en ira captif.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Dis au roi et à la reine: Humiliez-vous! asseyez-vous! car de votre tête tombe votre couronne de majesté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Les villes du Midi sont fermées, et personne ne les ouvre; tout Juda est déporté, déporté en totalité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Lève tes yeux, et vois ceux qui viennent du Nord! Où est le troupeau qui te fut donné, le troupeau qui était ta gloire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Que diras-tu, s\'il établit sur toi comme chefs ceux que tu habituas toi-même à te maîtriser? Les douleurs ne te saisiront-elles pas, comme la femme qui enfante?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Et si tu dis en ton cœur: « Pourquoi m\'arrivent ces choses? » C\'est pour le nombre de tes iniquités que tes pans ont été retroussés, et tes talons déshonorés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Un More changerait-il sa peau, et un léopard ses taches? Vous aussi, pourriez-vous faire le bien, étant habitués à faire le mal?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Mais je les disséminerai comme la balle emportée au vent du désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Tel sera ton lot, ta portion mesurée de par moi, dit l\'Éternel, parce que tu m\'as oublié, et que tu as placé ta confiance dans le mensonge;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'moi aussi je veux relever tes pans jusque sur ton visage, et l\'on verra ta honte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Tes adultères et tes hennissements, tes criminelles prostitutions sur les collines dans les campagnes... j\'ai vu tes infamies. Malheur à toi, Jérusalem, tu ne seras pas pure pendant combien de temps encore!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Parole de l\'Éternel qui fut adressée à Jérémie à l\'occasion des sécheresses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Juda est dans le deuil, et ses villes sont tombées en langueur, la tristesse les terrasse, et les cris de Jérusalem s\'élèvent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Et les grands envoient les petits aux eaux: ils arrivent aux citernes, ne trouvent point d\'eau; ils retournent avec des vases vides, confus et honteux ils se couvrent la tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'A la vue du pays consterné parce qu\'il ne tombe point de pluie sur la terre, les laboureurs sont confondus, ils se couvrent la tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Oui, même la biche dans les campagnes met bas, puis déserte, parce qu\'il n\'y a point d\'herbe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Et les onagres sont là sur les collines, aspirant l\'air comme des chacals, leur regard est éteint, parce qu\'il n\'y a point de verdure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Quoique nos péchés témoignent contre nous, agis, ô Éternel, pour l\'amour de ton nom; car nos défections sont nombreuses, nous avons péché contre toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Espoir d\'Israël, toi, son aide au moment de la détresse, pourquoi serais-tu comme un étranger dans le pays, et comme un voyageur qui campe pour une nuit?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Pourquoi serais-tu comme un homme éperdu, comme un héros impuissant pour aider? Cependant tu es au milieu de nous, Éternel, et de ton nom nous sommes appelés; ne nous abandonne pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Ainsi parle l\'Éternel à ce peuple: C\'est ainsi qu\'ils aiment à errer çà et là, sans contenir leurs allures. C\'est pourquoi l\'Éternel ne prend point plaisir à eux; Il se souvient à cette heure de leur crime, et Il châtie leur péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Et l\'Éternel me dit: Ne prie pas en faveur de ce peuple, pour son bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'S\'ils jeûnent, je n\'écouterai pas leurs requêtes, et s\'ils m\'offrent des holocaustes et des oblations, je ne les agréerai point, car je veux les détruire par l\'épée, par la famine et par la peste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Et je dis: Ah! Seigneur, Éternel, voici, ce sont les prophètes qui leur disent: Vous ne verrez point d\'épée, et vous n\'aurez point de famine, mais Je vous donnerai un bonheur assuré dans ce lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Et l\'Éternel me dit: C\'est le mensonge que ces prophètes prophétisent en mon nom, je ne les ai point envoyés, je ne leur ai adressé ni mes ordres, ni ma parole; menteuses visions, et divination, et vanité et illusions de leur cœur, c\'est ce qu\'ils vous prophétisent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Aussi l\'Éternel prononce ainsi sur ces prophètes qui prophétisent en mon nom, sans que je les aie envoyés, et qui disent: Il n\'y aura ni épée, ni famine en ce pays: Par l\'épée et par la famine ces prophètes périront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Et ceux auxquels ils prophétisent seront étendus dans les rues de Jérusalem par la famine et par l\'épée, et personne ne leur donnera la sépulture ni à eux, ni à leurs femmes, ni à leurs fils, ni à leurs filles; et je reverserai sur eux leur méchanceté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Et dis-leur encore cette parole: La nuit et le jour des larmes coulent de mes yeux, et elles ne s\'arrêtent pas, car la vierge, fille de mon peuple, a été frappée d\'un grand coup, d\'une plaie très douloureuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Si je sors dans les champs, ce sont des hommes percés par l\'épée, et si j\'entre dans la ville, ce sont des gens amaigris par la faim, car et prophètes et sacrificateurs circulent dans le pays, et ils ne savent que faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'As-tu donc rejeté Juda, et as-tu pris Sion en dégoût? Pourquoi nous as-tu frappés d\'un coup sans remède? Nous attendions le salut, mais il ne vient rien de bon; le temps de la guérison, et voici l\'épouvante!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Éternel, nous connaissons notre méchanceté, la faute de nos pères; car nous avons péché contre toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Pour l\'amour de ton nom, ne rejette pas, ne profane pas le trône de ta majesté; rappelle-toi, ne romps pas ton alliance avec nous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Parmi les idoles des nations en est-il qui donnent la pluie? ou le ciel a-t-il le pouvoir de répandre la rosée? N\'est-ce pas toi, Éternel, notre Dieu? Et nous espérons en toi, car c\'est toi qui as créé toutes ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Et l\'Éternel me dit: Quand même Moïse et Samuel se présenteraient devant moi, mon cœur ne serait pas pour ce peuple. Chasse-les de ma présence, et qu\'ils sortent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Et s\'ils te disent: Où irons-nous? tu leur diras: Ainsi parle l\'Éternel: A la mort celui qui est pour la mort, à l\'épée celui qui est pour l\'épée, à la famine celui qui est pour la famine, à la captivité celui qui est pour la captivité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Et je les punirai de quatre manières, dit l\'Éternel, par l\'épée pour les tuer, et par les chiens pour les traîner, et par les oiseaux des Cieux et les bêtes de la terre pour les dévorer et les détruire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'et je les exposerai aux avanies de tous les royaumes de la terre, à cause de Manassé, fils d\'Ézéchias, roi de Juda, pour tout ce qu\'il a fait dans Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'En effet, qui aura pitié de toi, Jérusalem? et qui te plaindra, et qui t\'abordera pour s\'informer de ta situation?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Tu m\'as abandonné, dit l\'Éternel, tu t\'es tirée en arrière; aussi j\'étendrai ma main contre toi, et je te détruirai: je suis las de miséricorde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Je les vannerai avec le van aux portes du pays, je leur ôterai leurs enfants, et je ferai périr mon peuple qui ne quitte pas ses voies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'J\'y ferai plus de veuves qu\'il n\'y a de grains de sable dans la mer, j\'amènerai contre eux, sur la mère et le jeune homme, le dévastateur en plein jour, et je ferai tomber sur eux tout à coup la douleur et la peine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'La mère de sept fils gémit, elle rend l\'âme, son soleil s\'est couché avant la fin du jour, elle est dans l\'opprobre et l\'ignominie. Et leur reste, je l\'abandonnerai au glaive de leurs ennemis, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, '« Malheureux que je suis! car, ô ma mère, tu m\'as fait naître homme de contestation et de querelle pour toute la terre. Je n\'ai point emprunté, on n\'a point emprunté de moi; [cependant] tous me maudissent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'L\'Éternel me dit: Non, je te tirerai de là pour te mettre en bon lieu, et je ferai venir à toi suppliants, au temps des revers et au temps de la détresse, tes propres ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Brisera-t-on le fer, le fer qui vient du Nord, et l\'airain?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Je donnerai vos biens et vos trésors en pillage, et sans payement, à cause de tous tes péchés commis dans toutes tes limites,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'et je les ferai passer avec ton ennemi dans un pays que tu ne connais pas; car un feu brûle dans mes narines, sur vous il est allumé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Tu sais [tout], Éternel, souviens-toi de moi, visite-moi, et venge-moi de mes persécuteurs! A force d\'être patient, ne me laisse pas enlever; sache que pour toi je subis l\'ignominie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Dès que tes paroles me furent offertes, je les dévorai; et tes paroles devinrent l\'allégresse et la joie de mon cœur, car je suis appelé de ton nom, Éternel, Dieu des armées!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Je ne m\'assis point dans les cercles des rieurs, je ne m\'y égayai point; étant sous ta main je m\'assis solitaire, car tu me pénétrais de courroux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Pourquoi ma souffrance est-elle permanente, et ma plaie incurable? Elle ne veut pas guérir. Tu es pour moi comme une source perfide, comme une eau inconstante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'C\'est pourquoi, ainsi parle l\'Éternel: Si tu te rétractes, je te rétablirai; tu te tiendras devant moi; et si tu sais démêler le bien d\'avec le mal, tu seras comme ma bouche. C\'est à eux de venir à toi, et non à toi d\'aller à eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Et je t\'oppose à ce peuple comme un mur d\'airain, comme un fort; s\'ils s\'attaquent à toi, ils ne te vaincront pas, car je suis avec toi pour te secourir et te délivrer, dit l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'et je te délivrerai de la main des méchants, et te sauverai du bras des violents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Et ta parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Ne prends point femme et n\'aie ni fils ni filles dans ce lieu-ci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Car ainsi prononce l\'Éternel sur les fils et les filles qui naissent en ce lieu, et sur leurs mères qui les enfantent, et sur leurs pères qui les engendrent dans ce pays-ci:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Ils mourront de maladies douloureuses; on ne leur donnera ni larmes, ni sépulture, ils seront du fumier sur les champs, et ils périront par l\'épée et la famine, et leurs cadavres seront la pâture des oiseaux du ciel et des bêtes de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Car ainsi parle l\'Éternel: N\'entre point dans la maison de deuil et ne va point te lamenter, ni compatir avec eux, car j\'ai ôté mon salut à ce peuple, dit l\'Éternel, mon amour et mes miséricordes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Et ils mourront, grands et petits, dans ce pays; pour eux il n\'y aura point de sépulture, point de deuil, point d\'incisions, point de cheveux coupés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'on ne leur rompra point le pain dans le deuil en consolation du mort, et on ne leur offrira point la coupe de consolation pour leur père et leur mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'N\'entre point non plus dans le lieu du festin pour y prendre place avec eux, pour manger et pour boire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Car ainsi parle l\'Éternel des armées, Dieu d\'Israël: Voici, je ferai cesser en ce lieu, sous vos yeux et de votre vivant, les chants de joie et les chants d\'allégresse, les chants du fiancé et les chants de la fiancée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Et quand tu annonceras à ce peuple toutes ces choses, et qu\'ils te diront: Pourquoi l\'Éternel nous menace-t-Il de tous ces grands maux? quel est notre crime, et quel est le péché que nous avons commis contre l\'Éternel, notre Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'dis-leur: C\'est que vos pères m\'ont abandonné, dit l\'Éternel, et sont allés après d\'autres dieux, et les ont servis, et les ont adorés, et m\'ont abandonné, et n\'ont point gardé ma loi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'et que vous faites pis que vos pères, et que, voici, vous suivez chacun l\'obstination de votre cœur mauvais, pour ne me point écouter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Et je vous chasserai de ce pays dans un pays inconnu à vous et à vos pères, et là vous pourrez servir les autres dieux et le jour et la nuit; car je ne vous accorderai aucune pitié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Aussi, voici, des jours viennent, dit l\'Éternel, que l\'on ne dira plus: « Vive l\'Éternel, qui retira les enfants d\'Israël du pays d\'Egypte! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'mais: « Vive l\'Éternel qui tira les enfants d\'Israël du pays du Nord, et de toutes les contrées où je les aurai dispersés! » et je les ramènerai dans leur pays que j\'avais donné à leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Voici, j\'envoie des pêcheurs en nombre, dit l\'Éternel, et ils les pêcheront; et ensuite j\'enverrai des chasseurs en nombre, et ils les chasseront de toutes les montagnes, et de toutes les collines, et des fentes de rochers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Car j\'ai les yeux sur toutes leurs voies; elles ne me sont point cachées, et leur iniquité ne se dérobe point a ma vue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Et je leur donnerai d\'abord le salaire de leur double iniquité et de leur péché, parce qu\'ils ont profané mon pays par les cadavres de leurs abominables dieux, et que d\'horreurs ils ont rempli mon héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, '« Éternel, ma force et mon boulevard, et mon refuge au jour de la détresse! A toi viendront les peuples des extrémités de la terre, et ils diront: « Nos pères n\'ont hérité que le mensonge, la vanité: il n\'y a là aucune ressource.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'L\'homme se fera-t-il des dieux, qui pourtant ne sont pas des dieux? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, '– C\'est pourquoi je veux leur montrer cette fois, leur montrer mon bras et ma puissance, afin qu\'ils reconnaissent que mon nom est l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Le péché de Juda est écrit avec un style de fer, une pointe de diamant; il est gravé sur la table de leur cœur et aux cornes de leurs autels.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Comme ils pensent à leurs enfants, ainsi pensent-ils à leurs autels, et à leurs Aschères près des arbres verdoyants et sur les collines élevées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'O ma montagne, qui es dans la campagne! je donnerai ton bien, tous tes trésors en pillage, et tes hauts lieux, à cause de tes péchés commis dans toutes tes limites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Et tu auras, et par ta faute, à laisser là ton héritage que je te donnai; et je t\'asservirai à tes ennemis dans un pays que tu ne connais pas, car vous avez allumé le feu de ma colère, et il brûlera toujours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Ainsi parle l\'Éternel: Maudit soit l\'homme qui se confie dans l\'homme, et qui prend la chair pour son appui, et dont le cœur déserte l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Il est comme un homme nu dans un désert, et ne voit point le bonheur arriver; il habite les lieux brûlés du désert, une terre salée et inhabitée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Béni soit l\'homme qui se confie dans l\'Éternel, et dont l\'Éternel est la confiance!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Il est comme un arbre planté près des eaux; il pousse ses racines vers le courant, et ne craint pas quand la chaleur vient, et son feuillage est vert, et dans l\'année de sécheresse il n\'est point inquiet, et il ne cesse de porter du fruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Rien n\'est plus tortueux que le cœur, et il est méchant; qui peut le connaître?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Moi, l\'Éternel, je sonde le cœur, j\'éprouve les reins, et cela pour rendre à chacun selon ses voies, selon le fruit de ses œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Une perdrix qui couve des œufs qu\'elle n\'a point pondus, tel est l\'homme qui se crée une richesse sans la droiture: à la moitié de ses jours il devra la quitter, et à sa fin il se trouvera être un insensé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Le lieu de mon Sanctuaire est un trône de gloire et de majesté dès le commencement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Espoir d\'Israël, ô Éternel, quiconque t\'abandonne, sera confondu. – « Ceux qui me quittent, seront inscrits sur la poussière, car ils abandonnent la source des eaux vives, l\'Éternel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Guéris-moi, Éternel, et je serai guéri; sauve-moi, et je serai sauvé, car tu es ma gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Voici, ils me disent: Où est la parole de l\'Éternel? qu\'elle se réalise donc!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Et moi, je n\'ai point évité de te suivre comme pasteur, et je n\'ai point désiré le jour du malheur, tu le sais; ce qui est sorti de mes lèvres, est découvert à tes regards.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Ne sois point mon effroi, toi, mon refuge au jour du malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Confonds mes persécuteurs, mais ne me confonds pas; atterre-les, mais ne m\'atterre pas! Fais venir sur eux le jour du malheur, brise-les à coups redoublés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Ainsi me parla l\'Éternel: Va, et te place à la porte des fils du peuple, par laquelle entrent et sortent les rois de Juda, et à toutes les portes de Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'et dis-leur: Écoutez la parole de l\'Éternel, rois de Juda, et tout Juda, et vous tous les habitants de Jérusalem, qui passez par ces portes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Ainsi parle l\'Éternel: Prenez garde à vous pour l\'amour de vos âmes, et ne portez point de fardeaux le jour du repos, et ne les faites pas passer par les portes de Jérusalem;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'et ne transportez aucun fardeau hors de vos maisons le jour du repos, et ne faites aucune œuvre; mais sanctifiez le jour du repos, ainsi que je le prescrivis à vos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Cependant ils n\'obéirent pas, et ne prêtèrent pas l\'oreille, mais roidirent leur col, pour ne point écouter et ne point recevoir la correction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Mais si vous m\'obéissez, dit l\'Éternel, en ne portant point de fardeaux par les portes de cette ville le jour du repos, et si vous sanctifiez le jour du repos en ne faisant aucune œuvre ce jour-là, alors,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'par les portes de cette ville entreront les rois et les princes assis sur le trône de David, montés sur des chars et des chevaux, eux et leurs princes, les hommes de Juda et les habitants de Jérusalem, et cette ville sera habitée éternellement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'et l\'on viendra des villes de Juda, et des alentours de Jérusalem, et du pays de Benjamin et du Bas-Pays, et de la montagne et du Midi, offrir des holocaustes, des victimes, et des offrandes et de l\'encens, et offrir des actions de grâces dans la maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Mais si vous ne m\'obéissez pas, en sanctifiant le jour du repos, et en ne portant aucun fardeau, et en n\'entrant point dans les portes de Jérusalem le jour du repos, j\'allumerai un feu aux portes de la ville, afin qu\'il dévore les palais de Jérusalem et ne s\'éteigne point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'La parole qui fut adressée à Jérémie par l\'Éternel, quand Il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Lève-toi, et descends à la maison du potier, et là je te ferai entendre mes paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Et je descendis à la maison du potier; et voici, il travaillait au tour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Et le vase qu\'il faisait avec l\'argile qu\'il tenait en sa main, manqua, et il en refit un autre vase tel que le potier trouva bon de le faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Alors la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Ne pourrai-je pas en agir avec vous, maison d\'Israël, comme ce potier-là? dit l\'Éternel. Voici, telle l\'argile dans la main du potier, tels vous êtes dans ma main, maison d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Une fois je parle, touchant un peuple et un royaume, d\'extirper, de détruire et de perdre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Mais que ce peuple, touchant lequel j\'avais parlé, revienne de sa méchanceté, je me repens du mal que j\'avais pensé à lui faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Et une autre fois je parle, touchant un peuple et un royaume, d\'édifier et de planter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Mais qu\'il fasse ce qui est mal à mes yeux, n\'obéissant pas à ma voix, je me repens du bien que j\'avais dit vouloir lui faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Et maintenant parle aux hommes de Juda, et aux habitants de Jérusalem, et dis: Ainsi parle l\'Éternel: Voici, je vous prépare des maux, et je médite un plan contre vous; ah! revenez chacun de votre mauvaise voie, et amendez vos voies et vos œuvres!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Mais ils disent: C\'en est fait! nous suivrons nos pensées, et nous agirons chacun selon l\'obstination de son cœur mauvais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'C\'est pourquoi ainsi parle l\'Éternel: Demandez parmi les nations qui ouït parler de telles choses! La vierge d\'Israël a fait de grandes horreurs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'La neige cesse-t-elle des roches du Liban de venir sur mes champs? Tarissent-elles, les eaux étrangères, fraîches et ruisselantes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Mais mon peuple m\'oublie, il encense le néant; on les a fait broncher dans leurs voies, sentiers d\'autrefois, et ils cheminent dans des routes, dans une voie non frayée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'pour faire de leur pays une désolation et une dérision éternelle: quiconque passera près de là, frissonnera et hochera la tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Pareil à un vent d\'Orient, je les dissiperai devant l\'ennemi; c\'est la tête détournée et non de ma face que je les regarderai au jour de leur peine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Mais ils disent: Venez et formons des complots contre Jérémie, car la loi ne périra point faute de sacrificateurs, ni la prudence faute de sages, ni la parole [de Dieu] faute de prophètes. Venez et tuons-le avec la langue, et n\'ayons égard à aucun de ses propos!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, '« Aie égard à moi, Éternel, et entends la voix de mes adversaires!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Le mal sera-t-il rendu pour le bien, qu\'ils creusent une fosse contre ma vie? Rappelle-toi comme je me suis tenu devant toi, afin de parler pour leur bien, et de détourner d\'eux ton courroux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Aussi, livre leurs fils à la famine, et abandonne-les à l\'épée; que leurs femmes tombent dans l\'orbité et dans le veuvage, et que leurs hommes soient tués par la peste, et leurs jeunes gens frappés par l\'épée dans le combat!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Qu\'on entende des cris sortir de leurs maisons, quand tu feras fondre sur eux des escadrons soudain; car ils ont creusé une fosse pour me prendre, et tendu des lacs devant mes pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Cependant, Éternel, tu sais que ce qu\'ils méditent contre moi c\'est la mort; ne mets pas le voile sur leur crime, et ne mets pas en l\'effaçant leur péché hors de ta vue, qu\'ils trébuchent à ton aspect! au moment de ta colère agis contre eux! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Ainsi parle l\'Éternel: Va, et achète une bouteille d\'un potier, et [prends avec toi] des Anciens du peuple, et des Anciens des Sacrificateurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'et sors, et va dans la vallée des fils de Hinnom qui est en face de la porte orientale, et prononce là les paroles que je te dirai,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'et dis: Écoutez la parole de l\'Éternel, rois de Juda, et habitants de Jérusalem! Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Voici, j\'amène une calamité sur ce lieu; (de quiconque en ouïra parler, les oreilles résonneront;)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'parce qu\'ils m\'ont abandonné, et ont aliéné ce lieu, et y ont encensé d\'autres dieux qu\'ils ne connaissaient ni eux, ni leurs pères, ni les rois de Juda, et qu\'ils ont rempli ce lieu du sang des innocents,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'et élevé des tertres à Baal, pour brûler leurs enfants au feu en holocaustes à Baal; ce que je n\'avais point commandé, et point dit, et qui n\'était point venu dans ma pensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Aussi, voici, des jours viennent, dit l\'Éternel, où ce lieu ne s\'appellera plus Topheth, ni vallée des fils de Hinnom, mais vallée du carnage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'et je viderai le conseil de Juda et de Jérusalem en ce lieu, et je les ferai tomber par l\'épée devant leurs ennemis, et par la main de ceux qui en veulent à leur vie, et je ferai de leurs cadavres la proie des oiseaux du ciel et des bêtes de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Et je rendrai cette ville une désolation et une dérision; quiconque passera près d\'elle frissonnera, et se rira de toutes ses plaies:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'et je leur ferai manger la chair de leurs fils, et la chair de leurs filles, et ils se mangeront l\'un l\'autre, dans la détresse et l\'angoisse dont les angoisseront leurs ennemis et ceux qui en veulent à leur vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Et brise la bouteille sous les yeux des hommes venus avec toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'et dis-leur: Ainsi parle l\'Éternel des armées: Ainsi briserai-je ce peuple et cette ville, comme on brise la poterie, laquelle ne peut plus être remise en état. Et l\'on enterrera à Topheth, faute d\'autre place pour enterrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Ainsi ferai-je à ce lieu, dit l\'Éternel, et à ses habitants, rendant cette ville semblable à Topheth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Et les maisons de Jérusalem, et les maisons des rois de Juda, comme le lieu de Topheth, seront impures, toutes les maisons sur les toits desquelles on offrait de l\'encens à toute l\'armée des Cieux, et des libations aux autres dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Et Jérémie revint de Topheth où l\'Éternel l\'avait envoyé pour prophétiser, et il se plaça dans le parvis de la maison de l\'Éternel, et dit à tout le peuple:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Voici, j\'amène sur cette ville, et sur toutes ses villes, tous les maux dont je l\'ai menacée; car ils roidissent leur col pour ne point écouter mes paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Et Paschur, fils d\'Immer, le sacrificateur, qui était surintendant de la maison de l\'Éternel, entendit Jérémie prononcer ces prophéties,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'et Paschur frappa Jérémie, le prophète, et le mit dans la prison qui était à la porte supérieure de Benjamin, dans la maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Mais, dès le lendemain, Paschur fit sortir Jérémie de prison. Alors Jérémie lui dit: Ce n\'est plus Paschur (entouré de sécurité) que l\'Éternel t\'appelle, mais Magor Missabib (terreur de toute part).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Car ainsi parle l\'Éternel: Voici, je te livre à la terreur, toi et tous tes amis, et ils tomberont par l\'épée de leurs ennemis, et tes yeux le verront; et je livrerai tout Juda aux mains du roi de Babel, pour qu\'il les emmène à Babel, et les frappe de l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Et je livrerai toutes les richesses de cette ville, et tous ses gains, et tout ce qu\'elle a de précieux, et tous les trésors des rois de Juda, je les livrerai aux mains de leurs ennemis qui les pilleront, les emporteront et les emmèneront à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Et toi, Paschur, et tous les habitants de ta maison, vous irez en captivité, et tu arriveras à Babel, et là tu mourras, et là tu seras enterré, toi et tous tes amis pour lesquels tu as été un prophète menteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, '« Tu m\'as persuadé, Éternel, et je me suis laissé persuader; tu m\'as pressé, et tu l\'as emporté. Je suis tous les jours tourné en dérision; tous se moquent de moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'car toutes les fois que je parle, je dois crier, annoncer la violence et la ruine! Aussi la parole de l\'Éternel m\'est-elle à honte et à opprobre chaque jour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'et j\'ai dit: Je ne ferai plus mention de Lui, et ne parlerai plus en son nom; mais j\'ai eu dans mon cœur comme un feu allumé, enfermé dans mes os, et je me fatiguai à le contenir, et je n\'ai pu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Aussi j\'entends les blasphèmes de la foule, terreur de toute part!: « Dénoncez-le, et nous le dénoncerons! » Tous mes amis qui sont à mes côtés, disent: « Peut-être il sera séduit, alors nous serons maîtres de lui, et nous tirerons vengeance de lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Mais l\'Éternel m\'assiste, comme un héros redoutable; c\'est pourquoi mes persécuteurs succomberont, et ne seront pas les maîtres; qu\'ils soient honteux d\'avoir échoué! c\'est un opprobre éternel qui ne sera pas oublié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Car l\'Éternel des armées éprouve le juste, Il pénètre les reins et le cœur; je verrai tes vengeances s\'exercer sur eux, car c\'est à toi que je me suis ouvert de mes griefs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Chantez l\'Éternel! louez l\'Éternel, car Il a retiré l\'âme de l\'affligé de la main des méchants! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, '« Maudit le jour auquel je suis né, le jour auquel ma mère m\'enfanta! qu\'il ne soit pas béni!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Maudit l\'homme qui en porta la nouvelle à mon père, et lui dit: « Il t\'est né un fils! » et le combla de joie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Que cet homme soit assimilé aux villes que l\'Éternel détruit sans regret; qu\'il entende des plaintes le matin, et des cris à midi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'parce qu\'on ne me tua pas avant ma naissance, en sorte que ma mère eût été mon tombeau, et que son sein fût resté dans un état de grossesse éternelle!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Pourquoi sortis-je du sein maternel pour être témoin de la misère et de la peine, et consumer mes jours dans la honte? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'La parole qui fut adressée à Jérémie de la part de l\'Éternel, quand le roi Sédécias envoya vers lui Paschur, fils de Malchija, et Sophonie, fils de Mahaséïa, le sacrificateur, pour lui dire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Consulte donc pour nous l\'Éternel; car Nébucadnézar, roi de Babel, nous livre la guerre: peut-être l\'Éternel fera-t-Il en notre faveur un miracle, tel que sont tous ses miracles, et l\'éloignera-t-Il de nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Alors Jérémie leur dit: Ainsi parlez à Sédécias:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Ainsi parle l\'Éternel, Dieu d\'Israël: Voici, je ramènerai par une conversion les armes de guerre qui sont dans vos mains, et avec lesquelles vous combattez en dehors de vos murs le roi de Babel et les Chaldéens qui vous assiègent, et je les concentrerai dans l\'enceinte de cette ville;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'et je vous combattrai de ma main étendue et d\'un bras puissant, avec colère, et avec courroux, et avec une grande fureur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'et je frapperai les habitants de cette ville, et les hommes et les bêtes; une grande peste les fera mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Et après cela, dit l\'Éternel, je livrerai Sédécias, roi de Juda, et ses serviteurs, et le peuple et ceux qui survivront dans celte ville à la peste, à l\'épée et à la famine, entre les mains de Nébucadnézar, roi de Babel, et entre les mains de leurs ennemis, et entre les mains de ceux qui en veulent à leur vie, pour qu\'il les frappe avec le tranchant de l\'épée, et n\'ait d\'eux ni pitié, ni compassion, ni miséricorde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Puis tu diras à ce peuple: Ainsi parle l\'Éternel: Voici, je vous propose le chemin de la vie, et le chemin de la mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'quiconque restera dans cette ville, mourra par l\'épée, la famine et la peste; mais quiconque sortira pour se rendre aux Chaldéens qui vous assiègent, vivra et aura son âme pour butin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Car je fixe mes regards sur cette ville pour faire du mal, et non pas du bien, dit l\'Éternel; elle va être livrée entre les mains du roi de Babel, pour qu\'il la brûle par le feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Et à la maison du roi de Juda: Écoutez la parole de l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Maison de David! Ainsi parle l\'Éternel: Rendez la justice dès le matin, et sauvez l\'homme dépouillé des mains de l\'oppresseur, de peur que ma colère n\'éclate comme un feu et qu\'elle ne brûle inextinguible, à cause de la méchanceté de vos actions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Voici, c\'est à vous que j\'en veux, habitants de la vallée, du rocher de la plaine, dit l\'Éternel, à vous qui dites: Qui descendrait jusqu\'à nous et qui pénétrerait dans nos maisons?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Mais je vous châtierai conformément au fruit de vos œuvres, dit l\'Éternel, et j\'allumerai un feu dans votre forêt, pour qu\'il dévore tous vos alentours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Ainsi parle l\'Éternel: Descends à la maison du roi de Juda, et là prononce ces paroles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'et dis: Écoute la parole de l\'Éternel, roi de Juda, assis sur le trône de David, toi et tes serviteurs et ton peuple, vous tous qui entrez par ces portes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Ainsi parle l\'Éternel: Faites droit et justice, et retirez l\'homme dépouillé des mains de l\'oppresseur, et n\'opprimez ni l\'étranger, ni l\'orphelin, ni la veuve, n\'usez pas de violence, et ne versez pas le sang innocent dans ce lieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Car si vous vous conformez à cette parole, les rois assis sur le trône de David entreront par les portes de cette maison, montés sur des chars et des chevaux, eux et leurs serviteurs et leur peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Mais, si vous n\'êtes pas dociles à ces paroles, je le jure par moi-même, dit l\'Éternel, cette maison sera mise en ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Car ainsi prononce l\'Éternel touchant la maison du roi de Juda: Tu es pour moi une Galaad, une cime du Liban; mais, je le jure, je te transformerai en désert, en ville inhabitée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Je sacre tes destructeurs, chacun avec ses armes, et ils abattront l\'élite de tes cèdres, et les jetteront au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Et des peuples nombreux passeront près de cette ville, et se diront l\'un à l\'autre: Pourquoi l\'Éternel a-t-Il traité de la sorte cette grande ville?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Et on dira: Parce qu\'ils ont déserté l\'alliance de l\'Éternel, leur Dieu, et qu\'ils ont adoré et servi d\'autres dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Ne pleurez point celui qui est mort, et ne le plaignez pas! pleurez, pleurez celui qui fut emmené! car il ne reviendra plus, et ne reverra plus le pays de sa naissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Car ainsi prononce l\'Éternel touchant Sallum, fils de Josias, roi de Juda, qui succéda à Josias, son père, et qui est sorti de ce lieu: Il n\'y reviendra pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'car il mourra dans le lieu où il a été déporté; il y mourra, et ce pays, il ne le reverra plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Malheur à celui qui élève sa maison par l\'iniquité, et ses appartements par l\'injustice, qui fait travailler son prochain sans salaire, et ne lui paie pas le prix de son labeur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'qui dit: Je me bâtirai des maisons vastes et des salles aérées, et qui y perce des fenêtres, et la lambrisse de cèdre, et la peint de vermillon!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Crois-tu que tu règnes, parce que tu te piques d\'employer du cèdre? Ton père ne mangeait-il pas, ne buvait-il pas?... mais il faisait droit et justice, et il fut heureux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'il jugeait la cause du misérable et du pauvre, et il fut heureux. N\'est-ce pas là me connaître? dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Mais tu n\'as des yeux et un cœur que pour ta cupidité, et pour le sang innocent afin de le répandre, et pour la violence et la concussion, afin de l\'exercer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Aussi, voici ce que l\'Éternel prononce sur Jéhojakim, fils de Josias, roi de Juda: Pour lui on ne s\'écriera pas dans le deuil: « Hélas! mon frère! » ni « Hélas! ma sœur! » pour lui on ne s\'écriera point: « Hélas! Seigneur! hélas! sa majesté! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Il recevra la sépulture qu\'on donne à un âne, il sera traîné, et jeté loin des portes de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, '[Jérusalem], monte sur le Liban, et pousse des cris; et en Basan fais retentir ta voix, et crie du haut d\'Abarim! car tous tes amants sont exterminés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Je t\'ai parlé pendant tes prospérités; tu as dit: Je ne veux pas écouter. Telle a été ta conduite dès ta jeunesse, que tu n\'as pas écouté ma voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Tous tes pasteurs seront la pâture du vent, et tes amants iront en captivité; alors tu seras dans l\'opprobre et dans l\'ignominie à cause de toute ta méchanceté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Toi qui habites le Liban, et bâtis ton aire sur les cèdres, que tu seras à plaindre quand te surviendront les douleurs, les maux comme à la femme en travail!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Par ma vie, dit l\'Éternel, quand Chonia, fils de Jéhojakim, roi de Juda, serait un cachet à ma main droite, d\'ici je t\'arracherais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'Je te livre aux mains de ceux qui en veulent à ta vie, et aux mains de ceux devant lesquels tu as peur, et aux mains de Nébucadnézar, roi de Babel, et aux mains des Chaldéens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Et je te lancerai, toi et ta mère qui t\'a enfanté, dans un autre pays où vous n\'êtes pas nés, et vous mourrez là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Et dans le pays où votre âme aspire à revenir, ils ne reviendront pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, '« Est-il donc un vase de rebut, mis en pièces, cet homme-là, Chonia, ou bien un meuble dont on est dégoûté? Pourquoi sont-ils jetés, lui et sa race, et lancés dans un pays qu\'ils ne connaissent pas? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Terre, terre, terre, écoute la parole de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Ainsi parle l\'Éternel: Inscrivez cet homme comme n\'ayant point d\'enfants, comme un homme qui ne prospère point en ses jours, car aucun des siens ne sera assez heureux pour s\'asseoir au trône de David, et pour régner désormais en Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Malheur aux pasteurs qui égarent et dispersent les brebis de mon pâturage, dit l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Aussi ainsi parle l\'Éternel, Dieu d\'Israël, touchant les pasteurs qui paissent mon peuple: Vous avez dispersé et disséminé mes brebis, et vous n\'avez point veillé sur elles: voici, je vais punir sur vous la méchanceté de vos actions, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Et je rassemblerai les restes de mes brebis de tous les pays où je les aurai dispersées, et je les ramènerai dans leur pâturage, pour qu\'elles y soient fécondes et s\'y multiplient,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'et j\'établirai sur elles des pasteurs qui les conduiront, de sorte qu\'elles n\'auront plus ni crainte, ni alarme, et qu\'on ne devra plus les chercher, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Voici, des jours viennent, dit l\'Éternel, où je susciterai à David un juste rejeton; il régnera en roi, il sera sage, et fera droit et justice dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Pendant ses jours Juda prospérera, et Israël habitera en sécurité, et voici le nom dont on l\'appellera: « L\'Éternel notre justice. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'C\'est pourquoi, voici, des jours viennent, dit l\'Éternel, dans lesquels on ne dira plus: « Vive l\'Éternel qui tira les enfants d\'Israël du pays d\'Egypte, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'mais: « Vive l\'Éternel qui a tiré et ramené la race de la maison d\'Israël de la région du Nord, et de tous les pays où Je les avais dispersés, » et ils habiteront dans leur pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Sur les prophètes. Mon cœur se brise dans ma poitrine, tous mes os s\'ébranlent. Je suis comme un homme enivré, et comme un homme vaincu par le vin, en face de l\'Éternel et de ses paroles saintes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Car le pays est plein d\'adultères; car sous la malédiction le pays est en deuil, les pacages du désert sont desséchés, car leur allure est mauvaise, et leur force est iniquité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Car et prophètes et sacrificateurs sont des profanes; jusque dans ma maison j\'ai rencontré leur malice, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Aussi leur chemin sera comme un sol glissant dans l\'obscurité; ils broncheront et y tomberont; car j\'amènerai sur eux des calamités au temps de leur châtiment, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Dans les prophètes de Samarie j\'ai vu de la démence; ils ont prophétisé au nom de Baal, et égaré mon peuple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Mais dans les prophètes de Jérusalem j\'ai vu des horreurs, l\'adultère et le mensonge; et ils affermissent les méchants, qui ainsi ne reviennent pas de leur méchanceté; ils me sont tous comme Sodome, et ses habitants comme Gomorrhe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'C\'est pourquoi, ainsi prononce l\'Éternel des armées sur les prophètes: Voici, je les nourrirai d\'absinthe, et les abreuverai d\'eaux vénéneuses; car des prophètes de Jérusalem l\'impiété s\'est répandue sur tout le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Ainsi parle l\'Éternel des armées: N\'écoutez pas les propos des prophètes qui vous prophétisent! Ils vous engagent dans la vanité, ils disent les visions de leur cœur, et non ce qui émane de la bouche de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Ils répètent à mes contempteurs: L\'Éternel a dit: Vous aurez la paix! Et à tous ceux qui suivent l\'obstination de leur cœur, ils disent: Il ne vous arrivera aucun mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Mais lequel assista au conseil de l\'Éternel, et vit et entendit sa parole? qui a été attentif à ma parole et l\'a écoutée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Voici, la tempête de l\'Éternel, la colère éclate, et la tempête est dardée, sur la tête des impies elle va fondre:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'le courroux de l\'Éternel ne s\'arrêtera point, qu\'il n\'ait fait et exécuté les pensées de son cœur. Dans la suite, des temps vous le sentirez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Je n\'envoyai point ces prophètes, et ils ont couru; je ne leur parlai point, et ils ont prophétisé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Mais, s\'ils avaient assisté à mon conseil, ils feraient entendre mes paroles à mon peuple, et les retireraient de leur mauvaise voie et de la méchanceté de leurs actions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Ne suis-je un Dieu que de près, dit l\'Éternel, et ne suis-je plus Dieu de loin?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Quand un homme se cacherait dans un lieu caché, ne le verrai-je point, dit l\'Éternel? Est-ce que je ne remplis pas les Cieux et la terre, dit l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'J\'entends ce que disent ces prophètes qui prophétisent en mon nom le mensonge, et disent: J\'ai eu un songe! j\'ai eu un songe! –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Combien de temps encore...? Ont-ils la pensée ces prophètes qui prophétisent le mensonge, et prophétisent les erreurs de leur cœur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'ont-ils le projet de faire oublier mon nom à mon peuple, par ces songes qu\'ils se racontent les uns aux autres, comme leurs pères ont oublié mon nom pour Baal?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Que le prophète qui a eu des songes, raconte des songes! et que celui qui a mes paroles, rapporte mes paroles avec vérité. Pourquoi l\'alliage du froment et de la paille? dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Ma parole n\'est-elle pas comme un feu, dit l\'Éternel, et comme un marteau qui brise le roc?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Aussi, voici, j\'en veux, dit l\'Éternel, aux prophètes qui se dérobent mes paroles l\'un à l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Voici, j\'en veux, dit l\'Éternel, aux prophètes qui prennent le langage des prophètes, et disent: Oracle [de l\'Éternel].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Voici, j\'en veux à ceux qui prophétisent des songes menteurs, dit l\'Éternel, et les racontent, et égarent mon peuple par leurs mensonges et leurs forfanteries, sans avoir reçu de moi ni mission, ni ordre, et qui ne sont d\'aucun profit pour ce peuple, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Que si ce peuple, ou un prophète, ou un sacrificateur t\'interroge, disant: Quelle est la menace de l\'Éternel? dis-leur quelle est cette menace: Je vous rejetterai, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Et le prophète, et le sacrificateur, et tout homme du peuple qui dira: « Menace de l\'Éternel, » je le châtierai, lui et sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Voici les termes dont vous vous servirez l\'un envers l\'autre, chacun envers son prochain: « Qu\'a répondu l\'Éternel? et qu\'a dit l\'Éternel? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Mais « Menace de l\'Éternel » c\'est ce que vous ne prononcerez plus; car pour chacun sa parole deviendra une menace, parce que vous tordez les paroles du Dieu vivant, de l\'Éternel des armées, notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Voici comment tu parleras au prophète: Que t\'a répondu l\'Éternel, et qu\'a dit l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Mais si vous dites: « Menace de l\'Éternel, » alors ainsi parle l\'Éternel: Parce que vous dites ce mot: « Menace de l\'Éternel, » et que j\'envoyai vers vous pour vous dire: Vous ne direz pas: « Menace de l\'Éternel, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'pour cela, voici, je vous oublierai, vous oublierai, et vous bannirai vous et cette ville que j\'avais donnée à vous et à vos pères, loin de ma présence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'et je mettrai sur vous une honte éternelle, et un opprobre éternel, qui ne sera pas oublié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'L\'Éternel me fit voir deux corbeilles de figues placées devant le parvis de l\'Éternel, après que Nébucadnézar, roi de Babel, eut emmené captifs Jéchonias, fils de Jéhojakim, roi de Juda, et les princes de Juda, et les charpentiers et les serruriers, et les eut conduits de Jérusalem à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Dans l\'une des corbeilles étaient de très bonnes figues, comme des figues primeurs, et dans l\'autre corbeille, de très mauvaises figues qu\'on ne pouvait manger à cause de leur mauvaise qualité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Et l\'Éternel me dit: Que vois-tu, Jérémie? Et je dis: Des figues; les bonnes figues sont très bonnes, et les mauvaises, si mauvaises qu\'on ne peut les manger à cause de leur mauvaise qualité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'ainsi parle l\'Éternel, Dieu d\'Israël: Comme [tu regardes] ces bonnes figues, de même je regarderai de bon œil les captifs de Juda, que j\'ai envoyés de ce lieu dans le pays des Chaldéens;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'et je les regarderai de bon œil, et je les ferai revenir dans ce pays et les rétablirai, pour ne plus les détruire, et les planterai, pour ne les plus arracher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Et je leur donnerai un cœur pour reconnaître que je suis l\'Éternel; ils seront mon peuple, et je serai leur Dieu; car ils reviendront à moi de tout leur cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Et comme ces mauvaises figues qu\'on ne mange pas à cause de leur mauvaise qualité, ainsi parle l\'Éternel, je livrerai Sédécias, roi de Juda, et ses princes, et les restes de Jérusalem qui resteront dans ce pays, et ceux qui habitent au pays d\'Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'et je les livrerai pour être tourmentés et maltraités, à tous les royaumes de la terre, et pour devenir un opprobre, et un proverbe, et une dérision, et une exécration dans tous les lieux où je les jetterai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Et j\'enverrai parmi eux l\'épée, la famine et la peste, jusqu\'à ce qu\'ils soient exterminés du pays que j\'avais donné à eux et à leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'La parole qui fut adressée à Jérémie sur tout le peuple de Juda, la quatrième année de Jéhojakim, fils de Josias, roi de Juda, qui est la première année de Nébucadnézar, roi de Babel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'parole que Jérémie, le prophète, adressa à tout le peuple de Juda et à tous les habitants de Jérusalem, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Depuis la treizième année de Josias, fils d\'Amon, roi de Juda, jusqu\'à ce jour, voici vingt-trois années que m\'est adressée la parole de l\'Éternel; et je vous ai parlé, parlé dès le matin, mais vous n\'avez pas écouté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Et l\'Éternel vous a envoyé tous ses serviteurs, les prophètes, dès le matin Il les a envoyés, mais vous n\'avez point écouté, vous n\'avez point prêté l\'oreille pour écouter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Ils vous disaient: Renoncez donc chacun à votre mauvais train, et à la malice de vos actions, et vous resterez dans le pays que l\'Éternel vous a donné à vous et à vos pères, de l\'éternité à l\'éternité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'et n\'allez plus après d\'autres dieux pour les servir et les adorer, et ne m\'irritez plus par les œuvres de vos mains: alors je ne vous ferai aucun mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Mais vous ne m\'écoutâtes point, dit l\'Éternel, afin de m\'irriter par les œuvres de vos mains, à votre détriment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'C\'est pourquoi ainsi parle l\'Éternel des armées: Parce que vous n\'avez point écouté mes paroles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'voici, j\'envoie, et je vais prendre toutes les tribus du nord, dit l\'Éternel, et j\'envoie vers Nébucadnézar, roi de Babel, mon serviteur, et je les ferai marcher sur ce pays, et sur ses habitants et sur tous ces peuples d\'alentour, et je les mets à l\'interdit, et j\'en ferai une désolation, et une dérision, et une ruine éternelle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'et je mettrai fin parmi eux aux chants de la joie et aux chants de l\'allégresse, aux chants du fiancé et aux chants de la fiancée, et au bruit des moulins, et à la lumière des lampes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'et tout ce pays sera une ruine, un désert, et ces peuples seront asservis au roi de Babel durant soixante-dix années.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Mais au terme de ces soixante-dix années, je punirai sur le roi de Babel et sur ce peuple-là, dit l\'Éternel, leur crime, ainsi que sur le pays des Chaldéens, et je le rendrai une solitude éternelle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'et j\'exécuterai sur ce pays toutes les menaces que j\'ai prononcées contre lui, tout ce qui est écrit dans ce livre, ce qu\'a prophétisé Jérémie sur tous les peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Car eux, eux aussi, des peuples nombreux et des rois puissants les asserviront, et je leur rendrai selon leurs faits et selon les œuvres de leurs mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Car ainsi me parla l\'Éternel, Dieu d\'Israël: Reçois de ma main cette coupe remplie du vin de colère, et fais-la boire à tous les peuples auxquels je t\'enverrai;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'et qu\'ils en boivent, et chancellent, et délirent sous l\'épée que j\'envoie parmi eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Et je reçus la coupe de la main de l\'Éternel, et je la fis boire à tous les peuples auxquels l\'Éternel m\'envoyait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'à Jérusalem et aux villes de Juda, et à ses rois et à ses princes, pour en faire un ravage, une désolation, une dérision et une exécration, comme elle l\'est aujourd\'hui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'à Pharaon, roi d\'Egypte, et à ses serviteurs, et à ses princes, et à tout son peuple;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'et à tous les confédérés, et à tous les rois du pays de Uts, et à tous les rois du pays des Philistins; et à Askalon, et à Gaza, et à Hécron, et aux restes d\'Asdod;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'à Édom, et à Moab, et aux fils d\'Ammon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'et à tous les rois de Tyr, et à tous les rois de Sidon, et aux rois des îles qui sont au delà de la mer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'à Dedan, et à Théma, à Buz, et à tous ceux qui se rasent les tempes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'et à tous les rois de l\'Arabie, et à tous les rois des confédérés, habitants du désert,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'et à tous les rois de Zimri, et à tous les rois d\'Élam, et à tous les rois de Médie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'et à tous les rois du Septentrion rapprochés et éloignés, à l\'un comme à l\'autre, et à tous les royaumes du monde qui sont sur la surface de la terre; et le roi de Sésach boira après eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Dis-leur aussi: Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Buvez et enivrez-vous, et vomissez, et tombez, pour ne pas vous relever, sous l\'épée que j\'envoie parmi vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Que s\'ils se refusent à recevoir la coupe de ta main pour la boire, dis-leur: Ainsi parle l\'Éternel des armées: Vous la boirez! vous la boirez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'car voici, par la ville appelée de mon nom je commence à punir, et vous, vous seriez quittes! Vous ne serez point quittes; car j\'appelle l\'épée sur tous les habitants de la terre, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Mais toi, prophétise-leur toutes ces choses, et dis-leur: Des lieux très-hauts l\'Éternel rugit, et de sa résidence sainte Il fait éclater sa voix, Il rugit contre sa demeure, Il pousse une clameur, comme ceux qui foulent au pressoir, contre tous les habitants de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'les éclats en pénètrent jusqu\'au bout de la terre, car l\'Éternel fait le procès aux nations, Il prend tous les mortels à partie, et les méchants, Il les livre à l\'épée, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Ainsi parle l\'Éternel des armées: Voici, le dévastateur marche de peuple à peuple, et une grande tempête surgit des extrémités de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Et les hommes tués de par l\'Éternel dans ce jour-là sont gisants d\'un bout de la terre à l\'autre bout de la terre; ils ne sont ni pleurés, ni ramassés, ni inhumés, ils restent comme du fumier sur les campagnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Gémissez, pasteurs, et lamentez-vous, et roulez-vous dans la poussière, chefs du troupeau; car pour vous le temps d\'être égorgés est accompli, et je vous disséminerai et vous tomberez comme une vaisselle de prix;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'et la retraite est coupée aux pasteurs, et aux chefs du troupeau, le moyen d\'échapper.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'On entend les cris des pasteurs, et les gémissements des chefs du troupeau; car l\'Éternel dévaste leur pâturage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'et les champs de la paix sont ravagés par le feu de la colère de l\'Éternel:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Il a quitté [sa demeure] comme un lion son fourré; car leur pays se change en désert sous la fureur de la terrible [épée] et sous le feu de sa colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Au commencement du règne de Jéhojakim, fils de Josias, roi de Juda, cette parole fut prononcée de la part de l\'Éternel, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Ainsi parle l\'Éternel: Tiens-toi dans le parvis de la maison de l\'Éternel, et dis à ceux qui de toutes les villes de Juda viennent adorer dans la maison de l\'Éternel, toutes les choses que je t\'ai ordonné de leur dire; n\'en retranche pas un mot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Peut-être écouteront-ils, et renonceront-ils chacun à leur mauvais train; alors je me repentirai du mal que j\'avais pensé à leur faire à cause de la méchanceté de leurs actions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Et dis-leur: Ainsi parle l\'Éternel: Si vous ne m\'obéissez pas, en suivant ma loi que j\'ai mise sous vos yeux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'en écoutant les paroles de mes serviteurs, les prophètes, que je vous ai envoyés dès le matin, sans que vous écoutiez,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'je réduirai cette maison à l\'état de Silo, et je livrerai cette ville à l\'exécration de tous les peuples de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Et les sacrificateurs, et les prophètes, et tout le peuple, entendirent Jérémie prononcer ces paroles dans la maison de l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'et quand Jérémie eut achevé de dire tout ce que l\'Éternel lui avait ordonné de dire à tout le peuple, les sacrificateurs, et les prophètes, et tout le peuple saisirent Jérémie, en disant: Tu mourras! tu mourras!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Pourquoi prophétises-tu au nom de l\'Éternel en disant: Cette maison sera réduite à l\'état de Silo, et cette ville dévastée, dépeuplée? Et tout le peuple s\'attroupa contre Jérémie dans la maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Et les princes de Juda entendant ces choses, montèrent de la maison du roi à la maison de l\'Éternel, et se placèrent à l\'avenue de la porte neuve de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Et les sacrificateurs et les prophètes parlèrent aux princes et tout le peuple en ces termes: Cet homme mérite la mort, car il a prophétisé contre cette ville, ainsi que vous l\'avez entendu de vos oreilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Alors Jérémie s\'adressa à tous les princes et à tout le peuple en ces termes: L\'Éternel m\'a donné la mission de prophétiser, contre cette maison et contre cette ville, toutes les choses que vous avez entendues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Or maintenant, amendez vos voies et vos œuvres, et écoutez la voix de l\'Éternel votre Dieu; et l\'Éternel se repentira des menaces qu\'il a prononcées contre vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Quant à moi, me voici entre vos mains; traitez-moi comme il vous semblera bon et convenable;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'seulement sachez que si vous me faites mourir, vous faites peser le sang innocent sur vous, et sur cette ville, et sur ses habitants, car il est vrai que l\'Éternel m\'a délégué auprès de vous pour prononcer à vos oreilles toutes ces paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Alors les princes et tout le peuple dirent aux sacrificateurs et aux prophètes: Cet homme ne mérite point la mort; car c\'est au nom de l\'Éternel notre Dieu qu\'il nous a parlé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Et des hommes d\'entre les Anciens du pays se levèrent, et parlèrent à toute l\'assemblée du peuple en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Michée, de Moréseth, prophétisait du temps d\'Ézéchias, roi de Juda, et il parla à tout le peuple de Juda, disant: Ainsi parle l\'Éternel des armées: Sion sera labourée comme un champ, et Jérusalem sera changée en un monceau de ruines, et la montagne de la Maison en une croupe boisée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Est-ce que Ézéchias, roi de Juda, et tout Juda l\'ont fait mourir? ne craignit-il pas l\'Éternel? et ne supplia-t-il pas l\'Éternel? Et l\'Éternel se repentit des menaces qu\'il avait prononcées contre eux; et nous, nous commettrions un si grand crime au péril de nos âmes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Il y eut aussi un homme qui prophétisait au nom de l\'Éternel, Urie, fils de Sémaïa, de Kiriath-Jeharim, et il prophétisa contre cette ville et contre ce pays les mêmes choses que Jérémie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Et quand le roi Jéhojakim, et tous ses guerriers, et tous ses généraux entendirent ses discours, le roi chercha à le faire mourir. Mais quand Urie l\'apprit, il craignit, et il s\'enfuit, et vint en Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Alors le roi Jéhojakim envoya des hommes en Egypte, Elnathan, fils de Hachbor, et des gens avec lui en Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'et ils ramenèrent Urie d\'Egypte, et le conduisirent au roi Jéhojakim, qui le fit périr par l\'épée, et jeta son cadavre dans les tombeaux de la populace. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Cependant la main d\'Achikam, fils de Schaphan, fut avec Jérémie, en sorte qu\'on ne le livra pas aux mains du peuple pour le faire mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Au commencement du règne de Jéhojakim, fils de Josias, roi de Juda, cette parole fut adressée à Jérémie par l\'Éternel, disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Ainsi m\'a parlé l\'Éternel: Fais-toi des chaînes et des jougs, et mets-les à ton col;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'puis envoie-les au roi d\'Édom, et au roi de Moab, et au roi des fils d\'Ammon, et au roi de Tyr, et au roi de Sidon, par l\'intermédiaire des députés venus à Jérusalem auprès de Sédécias, roi de Juda;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'et donne-leur mes ordres pour leurs maîtres en ces termes: Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Ainsi parlerez-vous à vos maîtres:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'C\'est moi qui ai fait la terre, et l\'homme et les animaux qui sont sur la terre, par ma grande puissance et par mon bras étendu, et je les donne à qui bon me semble;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'et maintenant je remets tous ces pays entre les mains de Nébucadnézar, roi de Babel, mon serviteur; et je lui donne aussi les bêtes des champs pour lui être assujetties,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'et tous les peuples lui seront assujettis, à lui et à son fils, et au fils de son fils, jusqu\'à ce que le temps de son pays arrive aussi, et que des peuples nombreux et de grands rois l\'asservissent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Et le peuple et le royaume qui ne se soumettra pas à lui, à Nébucadnézar, roi de Babel, et celui qui ne présentera pas son col au joug du roi de Babel, ce peuple-là, je le châtierai de l\'épée, et de la famine, et de la peste, dit l\'Éternel, jusqu\'à ce que je l\'aie exterminé par sa main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Et vous, n\'écoutez pas vos prophètes, ni vos devins, ni vos songes, ni vos magiciens, ni vos enchanteurs qui en vous parlant vous disent: Vous ne serez pas asservis au roi de Babel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'car c\'est le mensonge qu\'ils vous prophétisent, afin de vous bannir de votre pays, et afin que je vous chasse et que vous périssiez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Mais le peuple qui passera son col dans le joug du roi de Babel, et se soumettra à lui, je le laisserai sur son sol, dit l\'Éternel, pour qu\'il le cultive et y demeure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Et je parlai à Sédécias, roi de Juda, en ces mêmes termes, disant: Passez vos cols dans le joug du roi de Babel, et soumettez-vous à lui et à son peuple, afin que vous viviez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Pourquoi voudriez-vous, toi et ton peuple, mourir par l\'épée, la famine et la peste, comme l\'Éternel en a menacé le peuple qui ne se soumettra pas au roi de Babel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Et n\'écoutez pas les discours des prophètes qui vous disent: Vous ne serez pas asservis au roi de Babel; car c\'est le mensonge qu\'ils vous prophétisent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Car je ne les ai pas envoyés, dit l\'Éternel, et ils prophétisent en mon nom le mensonge, pour que je vous chasse, et que vous périssiez, vous et les prophètes qui vous prophétisent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Et je parlai aux sacrificateurs et à tout ce peuple, disant: Ainsi parle l\'Éternel: N\'écoutez pas les discours de vos prophètes qui vous prophétisent disant: Voici, maintenant les meubles de la maison de l\'Éternel seront bientôt rapportés de Babel! car c\'est un mensonge qu\'ils vous prophétisent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Ne les écoutez pas, soumettez-vous au roi de Babel, et vous vivrez; pourquoi cette ville serait-elle dévastée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Que s\'ils sont des prophètes, et si la parole de l\'Éternel est avec eux, qu\'ils demandent à l\'Éternel des armées, que les meubles restés dans la maison de l\'Éternel, et dans la maison du roi de Juda, et à Jérusalem, n\'aillent point à Babel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'car ainsi prononce l\'Éternel des armées sur les colonnes, et sur la mer, et sur les piédestaux, et sur les meubles restés dans cette ville,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'que n\'a point enlevés Nébucadnézar, roi de Babel, en emmenant captifs de Jérusalem à Babel Jéchonias, fils de Jéhojakim, roi de Juda, et tous les Grands de Juda et de Jérusalem –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'car ainsi prononce l\'Éternel des armées, Dieu d\'Israël, sur les meubles qui restent dans la maison de l\'Éternel, et dans la maison du roi de Juda et à Jérusalem:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'ils iront à Babel, et y demeureront, jusqu\'au jour où je m\'aviserai d\'eux, dit l\'Éternel, et où je les ferai remonter et revenir en ce lieu-ci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Et cette même année, au commencement du règne de Sédécias, roi de Juda, la quatrième année, le cinquième mois, Ananias, fils de Hazzur, prophète, de Gabaon, me dit dans la maison de l\'Éternel, en présence des sacrificateurs et de tout le peuple, ces paroles:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Je brise le joug du roi de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Encore deux années, et je ramène en ce lieu tous les meubles de la maison de l\'Éternel, que Nébucadnézar, roi de Babel, a enlevés de ce lieu, et qu\'il a transportés à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Et Jéchonias, fils de Jéhojakim, roi de Juda, et tous les captifs de Juda, qui sont allés à Babel, je les ramènerai en ce lieu, dit l\'Éternel, car je briserai le joug du roi de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Alors Jérémie, le prophète, parla à Ananias, le prophète, en présence des sacrificateurs et en présence de tout le peuple qui se tenait dans la maison de l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'et Jérémie, le prophète, dit: Ainsi soit-il! ainsi fasse l\'Éternel! que l\'Éternel donne effet aux paroles que tu as prophétisées, en ramenant les meubles de la maison de l\'Éternel et tous les captifs de Babel en ce lieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Seulement écoute cette parole que je prononce à tes oreilles, et aux oreilles de tout le peuple!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Les prophètes qui parurent avant moi et avant toi dès les anciens temps, ont dans leurs prophéties menacé beaucoup de pays, et de grands royaumes, de la guerre, et du désastre et de la peste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Le prophète qui prophétise le salut, est, quand la parole de ce prophète se réalise, reconnu comme le prophète que l\'Éternel envoie véritablement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Alors Ananias, le prophète, ôta le joug du col de Jérémie, le prophète, et le brisa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Et Ananias parla en présence de tout le peuple en disant: Ainsi parle l\'Éternel: De même je briserai le joug de Nébucadnézar, roi de Babel, dans deux ans, l\'ôtant du col de tous les peuples. Et le prophète Jérémie alla son chemin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Et la parole de l\'Éternel fut adressée à Jérémie, après que Ananias, le prophète, eut brisé le joug qu\'il avait ôté du col de Jérémie, le prophète, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Va, et parle à Ananias, et lui dis: Ainsi parle l\'Éternel: Tu as brisé un joug de bois, et tu l\'as remplacé par un joug de fer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Car ainsi parle l\'Éternel des armées, Dieu d\'Israël: Je mets un joug de fer sur le col de tous ces peuples, pour qu\'ils soient asservis à Nébucadnézar, roi de Babel; et ils lui seront asservis; et les bêtes des champs, je les lui donne aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Et Jérémie, le prophète, dit à Ananias, le prophète: Écoute, Ananias! l\'Éternel ne t\'a point envoyé, et tu as fait que ce peuple se fie au mensonge;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'c\'est pourquoi ainsi parle l\'Éternel: Voici, je t\'ôterai de la terre; cette année tu mourras; car tu as prêché la révolte contre l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Et Ananias, le prophète, mourut cette année-là, dans le septième mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Et ce sont ici les termes de la lettre qu\'envoya Jérémie, le prophète, de Jérusalem au reste des Anciens d\'entre les captifs, et aux sacrificateurs, et aux prophètes, et à tout le peuple qu\'avait transporté Nébucadnézar de Jérusalem à Babel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'après que furent sortis de Jérusalem le roi Jéchonias, et la reine, et les eunuques, les princes de Juda et de Jérusalem, et les charpentiers et les serruriers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'par l\'entremise d\'Éléasa, fils de Schaphan, et de Gémaria, fils d\'Hilkia, que Sédécias, roi de Juda, envoyait à Nébucadnézar, roi de Babel. Elle portait:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Ainsi parle l\'Éternel des années, Dieu d\'Israël, à tous les déportés que J\'ai déportés de Jérusalem à Babel:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Bâtissez des maisons, et habitez-les, et plantez des jardins et mangez-en les fruits;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'mariez-vous et ayez des fils et des filles, et prenez des femmes pour vos fils, et donnez vos filles à des maris pour qu\'elles enfantent des fils et des filles, et multipliez-vous là; et ne diminuez pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Et cherchez le bien-être de la ville où je vous ai déportés, et pour elle priez l\'Éternel, car dans son bien-être sera votre bien-être.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Car ainsi parle l\'Éternel des armées, Dieu d\'Israël: Ne vous laissez pas abuser par vos prophètes qui sont au milieu de vous, ni par vos devins, et n\'écoutez pas les songes que vous songez;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'car c\'est le mensonge qu\'ils vous prophétisent en mon nom; je ne les ai point envoyés, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Car ainsi parle l\'Éternel: Dès que soixante-dix ans seront révolus pour Babel, je vous visiterai, et j\'accomplirai sur vous mes excellentes promesses, en vous ramenant dans ce lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Car moi, je connais les pensées que j\'ai à votre égard, dit l\'Éternel, pensées qui ont pour but de sauver et non point de nuire, et tendent à vous donner un avenir et une espérance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Et vous m\'invoquerez, et vous vous en irez [satisfaits]; et vous me prierez, et je vous exaucerai;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'et vous me chercherez et vous me trouverez; car vous vous tournerez vers moi de tout votre cœur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'et je me laisserai trouver par vous, dit l\'Éternel; et je ramènerai vos captifs et je vous recueillerai d\'entre tous les peuples et de tous les lieux où je vous ai dispersés, dit l\'Éternel, et je vous ramènerai en ce lieu d\'où je vous ai emmenés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'parce que vous dites: Dieu nous a suscité des prophètes à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Car ainsi prononce l\'Éternel sur le roi assis au trône de David, et sur tout le peuple habitant cette ville, sur vos frères qui n\'allèrent point avec vous en captivité, ainsi prononce l\'Éternel des armées:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Voici, j\'envoie contre eux l\'épée, la famine et la peste, et je les rendrai pareils à ces figues hideuses qu\'on ne mange pas, tant elles sont mauvaises;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'et je les poursuivrai de l\'épée, de la famine et de la peste, et je les exposerai aux avanies de tous les royaumes de la terre, à l\'exécration, et à la désolation, et à la dérision, et à l\'opprobre, parmi tous les peuples où je les disséminerai,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'parce qu\'ils n\'ont pas écouté ma parole, dit l\'Éternel, quand Je leur envoyai mes serviteurs, les prophètes, dès le matin, et que vous n\'avez point écouté, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Mais vous, écoutez la parole de l\'Éternel, vous tous les captifs que j\'ai envoyés de Jérusalem à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Ainsi prononce l\'Éternel des armées, Dieu d\'Israël, touchant Achab, fils de Colaïa, et sur Sédécias, fils de Mahaséïa, qui vous prophétisent en mon nom le mensonge: Voici, je les livre aux mains de Nébucadnézar, roi de Babel, afin qu\'il les frappe sous vos yeux:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'et ils fourniront une imprécation à tous les captifs de Juda qui sont à Babel et qui diront: « Que l\'Éternel te traite comme Sédécias et comme Achab, qu\'a fait rôtir au feu Nébucadnézar, roi de Babel! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'parce qu\'ils ont fait des abominations en Israël, et commis adultère avec les femmes de leurs prochains, et qu\'ils se sont servis de mon nom pour mentir; ce que je ne leur avais point commandé. Mais moi, je le sais, et j\'en suis témoin, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Et tu parleras à Sémaïa de Néchélam, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Parce que tu as adressé en ton nom une lettre à tout le peuple à Jérusalem, et à Sophonie, fils de Mahaséïa, le sacrificateur, et à tous les sacrificateurs, ainsi conçue:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'L\'Éternel t\'a établi sacrificateur en remplacement de Jéhojadah, le sacrificateur, pour qu\'il y ait dans la maison de l\'Éternel des inspecteurs, qui s\'opposent à tous les fanatiques et à ceux qui prophétisent, et que tu les mettes en prison et aux fers;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'et maintenant, pourquoi n\'as-tu pas réprimé Jérémie d\'Anathoth, qui vous prophétise?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Car c\'est pour cela qu\'il nous a écrit à Babel en ces mots: Ceci sera long! bâtissez des maisons, et habitez-les, et plantez des jardins, et mangez-en les fruits. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Et Sophonie, le sacrificateur, lut cette lettre devant Jérémie, le prophète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Et la parole de l\'Éternel fut adressée à Jérémie, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Écris à tous les captifs en ces termes: Ainsi prononce l\'Éternel sur Sémaïa de Néchélam: Parce que Sémaïa vous prophétise sans mission de ma part, et qu\'il est cause que vous vous fiez au mensonge,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'c\'est pourquoi l\'Éternel parle ainsi: Voici, je vais châtier Sémaïa de Néchélam, et sa race: il n\'en demeurera aucun homme parmi ce peuple, et il ne verra point le bien que je ferai à mon peuple, dit l\'Éternel, car il a prêché la révolte contre l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'La parole qui fut adressée à Jérémie par l\'Éternel en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Ainsi parle l\'Éternel, Dieu d\'Israël: Écris toutes les paroles que je t\'ai dites dans un livre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Car voici, des jours viennent, dit l\'Éternel, où je ramènerai les captifs de mon peuple d\'Israël et de Juda, dit l\'Éternel, et les ferai rentrer dans le pays que j\'ai donné à leurs pères pour le posséder.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Et ce sont ici les paroles prononcées par l\'Éternel sur Israël et sur Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Car ainsi parle l\'Éternel: Nous entendons, [disent-ils,] la voix de la terreur; c\'est l\'épouvante, et non pas la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Informez-vous, observez si un mâle enfante!... pourquoi vois-je tous les hommes les mains sur les reins, comme la femme en travail, et tous les visages changés et pâlis?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'O malheur! c\'est une grande journée! elle n\'a pas sa pareille, et c\'est un temps d\'angoisse pour Jacob, mais il en sera délivré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Et dans ce jour-là, dit l\'Éternel des armées, je briserai le joug de dessus ton col, et je romprai tes fers, et des étrangers ne t\'asserviront plus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'mais ils serviront l\'Éternel, leur Dieu, et David, leur roi, que je leur susciterai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Toi donc, mon serviteur Jacob, ne crains point, dit l\'Éternel, et ne t\'effraie point, Israël; car voici, je te retirerai des pays lointains, et ta race de la contrée où elle est exilée; et Jacob reviendra, et il sera tranquille et plein de sécurité, et nul ne lui donnera de l\'effroi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Car je suis avec toi, dit l\'Éternel, pour te sauver; car je ferai extermination de tous les peuples où je t\'ai disséminé; de toi seul je ne ferai pas extermination. Et je te châtierai équitablement; mais je ne puis te laisser impuni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Car ainsi parle l\'Éternel: Ta blessure est incurable, et ta plaie sans espoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Nul ne prend ton parti pour y porter remède; il n\'y a ni guérison, ni traitement pour toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Tous tes amants t\'oublient, et ne s\'enquièrent pas de toi; car c\'est d\'un coup d\'ennemi que je t\'ai frappé, d\'un châtiment cruel, pour le nombre de tes péchés, la multitude de tes iniquités.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Pourquoi ta blessure te fait-elle crier? ta souffrance est mortelle: c\'est pour le nombre de tes péchés et la multitude de tes iniquités que je te traite ainsi. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'C\'est pourquoi tous ceux qui t\'ont dévoré, seront dévorés, et tous tes oppresseurs s\'en iront tous en captivité, et tes spoliateurs deviendront une dépouille, et tous ceux qui te pillent, je les livrerai au pillage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Car je veux te mettre un bandage et te guérir de tes plaies, dit l\'Éternel. Car on t\'appelait Sion la repoussée, celle que personne ne cherche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Ainsi parle l\'Éternel: Voici, je ramène les captifs des tentes de Jacob, et je prends pitié de ses demeures; et la ville sera rebâtie sur ses ruines, et le pays habité selon l\'usage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'il en sortira des louanges et des chants de réjouissance; je les multiplierai, et ils ne seront pas amoindris; je les honorerai, et ils ne seront pas ravalés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Et ses fils seront comme jadis, et leur nation sera affermie devant moi, et je châtierai tous ses oppresseurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Et son chef sera l\'un des siens, et son souverain sortira de son sein; et je leur donnerai accès auprès de moi, et ils s\'approcheront de moi. Car qui est-ce qui cautionnerait son propre cœur pour oser s\'approcher de moi? dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Ainsi, vous serez mon peuple, et je serai votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Voici, la tempête de l\'Éternel, la colère éclate, une tempête impétueuse fondra sur la tête des impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'L\'ardente colère de l\'Éternel ne cessera point qu\'il n\'ait agi et exécuté les pensées de son cœur. Dans la suite des temps vous le sentirez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'Dans ce temps-là, dit l\'Éternel, je serai le Dieu de toutes les tribus d\'Israël, et eux ils seront mon peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Ainsi parle l\'Éternel: Il a trouvé grâce dans le désert, le peuple de ceux qui échappèrent à l\'épée; je marche pour le conduire au repos, lui Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, '« De loin [dira-t-il] l\'Éternel se montre à moi. » Je t\'aimai d\'un amour éternel; c\'est pourquoi je t\'ai conservé ma faveur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Je te relèverai encore, et tu seras relevée, Vierge d\'Israël; tu te pareras encore de tes cymbales, et tu t\'avanceras dans les chœurs des danseurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'tu planteras encore des vignes sur les coteaux de Samarie; les planteurs les planteront et en jouiront;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'car il y aura un jour auquel les sentinelles s\'écrieront sur les montagnes d\'Éphraïm: Allons! montons à Sion, vers l\'Éternel, notre Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Car ainsi parle l\'Éternel: Élevez sur Jacob des chants de triomphe, et des acclamations sur le chef des peuples! proclamez, exaltez et dites: Éternel, sauve ton peuple, le reste d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Voici, Je les ramène de la région du Nord, et les recueille des extrémités de la terre; l\'aveugle et le boiteux, la femme enceinte et l\'accouchée y seront avec eux; en grande foule ils reviendront ici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Ils arrivent pleurant [de joie], et je les ramène élevant leurs prières; je les conduis aux courants des eaux par un chemin uni où ils ne trébucheront pas; car je suis pour Israël un père, et Éphraïm est mon premier-né.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Nations, écoutez la parole de l\'Éternel, et publiez-la dans les îles lointaines, et dites: Celui qui dispersa Israël le recueille, et Il le garde, comme un berger son troupeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Car l\'Éternel a racheté Jacob, et l\'a retiré des mains d\'un plus fort que lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Et ils viendront, et feront éclater leur joie sur les hauteurs de Sion, et ils accourront vers les biens de l\'Éternel, vers le blé et le vin, et l\'huile, et le menu bétail, et le gros bétail; et leur âme sera comme un jardin arrosé, et désormais ils n\'auront plus de soucis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Alors la jeune fille se plaira aux danses, et les jeunes et les vieux tous ensemble; je changerai leur deuil en allégresse, et je les consolerai, et je les réjouirai après leur chagrin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'j\'inonderai de moelle le cœur des sacrificateurs, et mon peuple aura de mes biens à rassasiement, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Ainsi parle l\'Éternel: Une voix retentit en Rama, c\'est une complainte, ce sont des larmes amères; Rachel pleure ses fils, elle ne veut pas être consolée de ses fils, parce qu\'ils ne sont plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Ainsi parle l\'Éternel: Cesse de mêler des pleurs à ta voix, et de baigner tes yeux de larmes; car il est un salaire pour ton labeur, dit l\'Éternel, et ils reviennent du pays de l\'ennemi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'et il est un espoir pour ton avenir, dit l\'Éternel, et tes fils rentreront dans leurs frontières.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'J\'entends, j\'entends gémir Éphraïm: « Tu m\'as châtié, et je fus châtié, comme le jeune taureau indocile; convertis-moi, et je serai converti, car, ô Éternel, c\'est toi qui es mon Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Car après m\'être converti, je fais pénitence, et après m\'être reconnu, je me frappe les flancs; je suis confus et honteux, car je porte l\'opprobre de ma jeunesse. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Éphraïm est-il donc pour moi un fils si cher, un enfant si tendrement aimé? Car dès que je parle de lui, son souvenir se renouvelle toujours en moi. C\'est ainsi que mon cœur s\'émeut pour lui: oui, j\'aurai compassion de lui, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Dresse des cippes, élève des poteaux-guides; observe la route, le chemin par où tu t\'en vas!.... reviens, Vierge d\'Israël, reviens dans ces villes qui sont les tiennes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Jusques à quand seras-tu vagabonde, fille rebelle? Car l\'Éternel va faire une nouveauté dans le pays; c\'est la femme qui veillera à la sûreté de l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Voici le langage qu\'on tiendra désormais dans le pays de Juda et dans ses villes, quand j\'aurai ramené leurs captifs: « Que l\'Éternel te bénisse, résidence de la justice, montagne sainte! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Et là sera le séjour de Juda avec toutes ses villes, des laboureurs et de ceux qui voyagent avec leurs troupeaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'car Je restaurerai les cœurs épuisés, et aux cœurs inquiets Je donnerai l\'abondance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Puis je me réveillerai, et je regarderai, et mon sommeil aura été doux pour moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Voici, des jours viennent, dit l\'Éternel, où j\'ensemencerai la maison d\'Israël et la maison de Juda d\'une semence d\'hommes et d\'une semence de bestiaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Et comme j\'ai veillé sur eux pour extirper, et pour ruiner, et pour détruire, et pour perdre, et pour nuire, de même je veillerai sur eux, pour édifier et pour planter, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'Dans ces jours-là on ne dira plus: « Les pères ont mangé du verjus, et les dents de leurs fils en furent attaquées; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'mais chacun mourra pour son propre péché, et c\'est celui qui mangera du verjus, dont les dents seront attaquées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Voici, des jours viennent, dit l\'Éternel, où je ferai avec la maison d\'Israël et la maison de Juda une alliance nouvelle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'non comme l\'alliance que je fis avec leurs pères le jour où je les pris par la main pour les tirer du pays d\'Egypte: ils rompirent mon alliance, et j\'étais leur Souverain, dit l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'mais voici l\'alliance que je ferai avec la maison d\'Israël après ces jours-là, dit l\'Éternel: Je mettrai ma loi au dedans d\'eux, et je l\'écrirai dans leur cœur; et je serai leur Dieu, et ils seront mon peuple;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'et l\'on n\'aura plus à enseigner son prochain ou son frère en disant: Apprenez à connaître l\'Éternel! Car tous ils me connaîtront, du petit au grand, dit l\'Éternel; car je pardonnerai leur iniquité, et ne me souviendrai plus de leur péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Ainsi parle l\'Éternel qui a fait le soleil pour être la lumière du jour, les phases de la lune et des astres pour éclairer la nuit, qui soulève la mer, et ses vagues grondent; l\'Éternel des armées est son nom:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Si toutes ces lois font défaut devant moi, dit l\'Éternel, la race d\'Israël cessera aussi d\'être un peuple devant moi à perpétuité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Ainsi parle l\'Éternel: Quand on mesurera la hauteur du ciel, et qu\'on sondera la profondeur des bases de la terre, alors aussi je rejetterai toute la race d\'Israël pour tout ce qu\'ils ont fait, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Voici, des jours viennent, dit l\'Éternel, où la ville sera relevée à la gloire de l\'Éternel, depuis la tour de Hananéel jusqu\'à la Porte de l\'Angle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'et le cordeau s\'étendra encore vis-à-vis jusqu\'à la colline de Gareb, puis tournera vers Goath.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Et toute la vallée des cadavres et de la cendre, et tous les champs jusqu\'au torrent de Cédron, jusqu\'à l\'angle de la Porte des chevaux à l\'orient, seront consacrés à l\'Éternel, et ne seront plus jamais ni dévastés, ni détruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'La parole qui fut adressée à Jérémie par l\'Éternel, la dixième année de Sédécias, roi de Juda: c\'était la dix-huitième année de Nébucadnézar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Or l\'armée du roi de Babel assiégeait alors Jérusalem, et Jérémie, le prophète, était enfermé dans le vestibule de la prison qui était dans la maison du roi de Juda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'où l\'avait enfermé Sédécias, roi de Juda, en disant: Pourquoi prophétises-tu disant: « Ainsi parle l\'Éternel: Voici, je vais livrer cette ville aux mains du roi de Babel, pour qu\'il s\'en empare,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'et Sédécias, roi de Juda, n\'échappera pas aux mains des Chaldéens, mais il sera livré aux mains du roi de Babel, et il lui parlera bouche à bouche, et ses yeux rencontreront ses yeux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'et il conduira Sédécias à Babel, où il demeurera jusqu\'à ce que je le visite, dit l\'Éternel. Si vous vous battez contre les Chaldéens, vous n\'aurez point de succès »?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Alors Jérémie dit: La parole de l\'Éternel m\'a été adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Voici, Hanaméel, fils de Sallum ton oncle, s\'approchera de toi pour te dire: Achète mon champ qui est à Anathoth, car tu as le droit de retrait pour le rachat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Et Hanaméel, fils de mon oncle, s\'approcha de moi selon la parole de l\'Éternel, dans le vestibule de la prison, et me dit: Achète mon champ qui est à Anathoth, dans le pays de Benjamin, car tu as le droit de succession et de retrait; achète-le! Et je reconnus que c\'était là la parole de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Et j\'achetai le champ de Hanaméel, fils de mon oncle, à Anathoth, et je lui pesai le prix, sept sicles [d\'or], et dix sicles d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Et je consignai cela dans une lettre que je scellai; et je pris des témoins, et je pesai l\'argent à la balance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Puis je pris la lettre d\'achat, celle qui était scellée selon l\'ordonnance et les statuts, et celle qui était ouverte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'et je remis la lettre d\'achat à Baruch, fils de Nérija, fils de Mahaséïa, en présence de Hanaméel, mon parent, et en présence des témoins signataires de la lettre d\'achat, et en présence de tous les Juifs assis dans le vestibule de la prison;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'et en leur présence je donnai cet ordre à Baruch:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Prends ces lettres, cette lettre d\'achat scellée, et cette lettre ouverte, et mets-les dans un vase de terre, afin qu\'elles se conservent longtemps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Car ainsi parle l\'Éternel des armées, Dieu d\'Israël: Il sera encore acheté des maisons, et des champs, et des vignes dans ce pays-ci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Et je priai l\'Éternel, après avoir remis la lettre d\'achat à Baruch, fils de Nérija, disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Ah! Seigneur Éternel, voici, tu as formé les Cieux et la terre par ta grande force et ton bras étendu: rien n\'est trop difficile pour toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Tu fais grâce à mille [générations] et tu fais retomber la peine du péché des pères dans le sein de leurs enfants après eux. Dieu grand et puissant, dont le nom est l\'Éternel des armées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'toi qui es grand en conseil et puissant en action, toi dont les yeux sont ouverts sur toutes les voies des enfants des hommes, pour rendre à chacun selon ses voies et selon le fruit de ses œuvres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'toi qui fis des signes et des miracles au pays d\'Egypte jusqu\'à ce jour, et pour Israël, et pour d\'autres hommes, et qui t\'es fait un nom tel qu\'[il est] aujourd\'hui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'et qui tiras du pays d\'Egypte ton peuple d\'Israël, avec des signes et des miracles, et d\'une main forte et d\'un bras étendu, et avec une grande terreur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'et qui leur donnas ce pays que tu avais juré à leurs pères de leur donner, pays découlant de lait et de miel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'et ils sont venus et en ont pris possession; mais ils n\'ont point obéi à ta voix, ni suivi ta loi, ne pratiquant point tout ce que tu leur avais commandé de faire; et tu as fait fondre sur eux toutes ces calamités!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Voici, les terrasses atteignent déjà cette ville, en sorte qu\'elle sera prise, puis livrée aux mains des Chaldéens qui lui sont hostiles, par l\'épée et la famine et la peste; et ce que tu as dit arrive, et voici, tu en es témoin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Et néanmoins tu m\'as dit, Seigneur, Éternel: « Achète-toi un champ pour de l\'argent, et prends des témoins; » et cette ville est livrée aux mains des Chaldéens!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Et la parole de l\'Éternel fut adressée à Jérémie en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Voici, moi l\'Éternel, je suis le Dieu de toute chair; y a-t-il rien de trop difficile pour moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Aussi, ainsi parle l\'Éternel: Voici, je livre cette ville aux mains des Chaldéens, et aux mains de Nébucadnézar, roi de Babel, pour qu\'il s\'en empare.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Et les Chaldéens qui font la guerre à cette ville, vont arriver, et mettre le feu à cette ville, et la brûler, ainsi que les maisons sur les toits desquelles ils ont encensé Baal, et offert des libations à d\'autres dieux, afin de me provoquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Car les enfants d\'Israël et les enfants de Juda n\'ont fait que ce qui est mal à mes yeux dès leur jeunesse; car les enfants d\'Israël n\'ont fait que me provoquer par l\'œuvre de leurs mains, dit l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'car dans la colère et le courroux que cette ville me donne depuis le jour où elle fut bâtie, jusques aujourd\'hui, j\'ai résolu de l\'ôter de ma vue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'à cause de tout le mal qu\'ont fait les enfants d\'Israël et les enfants de Juda pour me provoquer, eux, leurs rois, leurs princes, leurs sacrificateurs et leurs prophètes, et les hommes de Juda et les habitants de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Et ils m\'ont présenté le dos et non point le visage; dès le matin je les ai instruits et instruits; mais ils ne furent point dociles à recevoir la remontrance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'et ils ont placé leurs abominations dans la maison appelée de mon nom pour la souiller,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'et ils ont élevé des tertres à Baal dans la vallée des fils de Hinnom, pour offrir leurs fils et leurs filles à Moloch; ce que je n\'avais point ordonné et qui ne m\'était point venu dans la pensée, qu\'on fît de telles horreurs pour porter Juda à pécher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Et maintenant, ainsi prononce cependant l\'Éternel, Dieu d\'Israël, sur cette ville dont vous dites: Elle sera livrée aux mains du roi de Babel par l\'épée et la famine et la peste:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Voici, je les recueillerai de tous les pays où je les aurai dispersés dans ma colère, et dans ma fureur, et dans mon grand courroux, et je les ferai revenir en ce lieu et habiter en sécurité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'et ils seront mon peuple, et je serai leur Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'et je leur donnerai un seul cœur et une seule voie pour me craindre toujours, afin d\'être heureux, eux et leurs enfants après eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Et je leur donne cette alliance éternelle, que je ne cesserai de leur faire du bien, et je mettrai ma crainte dans leurs cœurs, afin qu\'ils ne s\'éloignent pas de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Et ma joie à leur égard sera de leur faire du bien, et je les planterai dans ce pays, véritablement, de tout mon cœur et de toute mon âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Car ainsi parle l\'Éternel: De même que j\'ai fait venir sur ce peuple tous ces grands maux, de même je ferai venir sur eux tous les biens que je leur ai promis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'et des champs seront achetés dans ce pays duquel vous dites: « C\'est un désert sans hommes ni bestiaux, il est livré aux mains des Chaldéens; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'on achètera des champs pour de l\'argent, les lettres en seront écrites et scellées, munies du témoignage des témoins, dans le pays de Benjamin, et dans les alentours de Jérusalem, et dans les villes de Juda, et dans les villes de la montagne, et dans les villes du bas-pays, et dans les villes du Midi; car je ramènerai leurs captifs, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Et la parole de l\'Éternel fut adressée à Jérémie une seconde fois (or il était encore détenu dans le vestibule de la prison) en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Ainsi parle l\'Éternel qui fait ces choses, l\'Éternel qui les conçoit pour les préparer; l\'Éternel est son nom:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Invoque-moi, et je te répondrai, et je te révélerai des choses grandes et impénétrables que tu ne connais pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Car ainsi prononce l\'Éternel, Dieu d\'Israël, sur les maisons de cette ville, et sur les maisons des rois de Juda, qui seront détruites par les terrasses et les machines,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'les Chaldéens venant pour assiéger, et pour les remplir des cadavres des hommes que je frapperai dans ma colère et ma fureur, quand je cacherai ma face à cette ville à cause de toute leur malice:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Voici, je lui appliquerai des bandages et des remèdes, et je la guérirai, et je leur ouvrirai un trésor de salut permanent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Et je ramènerai les captifs de Juda et les captifs d\'Israël, et je les restaurerai comme autrefois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'et je les purifierai de toute l\'iniquité dont ils furent coupables envers moi; et je leur pardonnerai toutes les iniquités qui les rendaient coupables envers moi, et rebelles contre moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Et [Jérusalem] m\'acquerra un nom d\'allégresse, de louange et de gloire auprès de tous les peuples de la terre, qui apprendront tout le bien que je leur fais, et trembleront, et craindront à la vue de tout le bien et de tout le bonheur que je lui accorderai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Ainsi parle l\'Éternel: On entendra de nouveau dans ce lieu duquel vous dites: « C\'est un désert sans hommes ni bestiaux, » dans les villes de Juda et dans les rues de Jérusalem, désolées, privées d\'hommes et d\'habitants et de bestiaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'les chants de joie et les chants d\'allégresse, les chants du fiancé et les chants de la fiancée, la voix de gens qui disent: « Louez l\'Éternel des armées, car l\'Éternel est bon, sa grâce est éternelle! » et qui apportent leurs actions de grâces à la maison de l\'Éternel. Car je ramènerai les captifs du pays comme autrefois, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Ainsi parle l\'Éternel des armées: Il y aura de nouveau dans ce lieu désolé, privé d\'hommes et de bestiaux, et dans toutes ses villes, des stations de bergers faisant reposer leurs troupeaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'dans les villes de la montagne, dans les villes du bas-pays, et dans les villes du Midi, et dans le pays de Benjamin, et dans les alentours de Jérusalem, et dans les villes de Juda, les brebis passeront encore sous la main de celui qui les compte, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Voici, des jours viennent, dit l\'Éternel, où je réaliserai les promesses que j\'ai faites à la maison d\'Israël et à la maison de Juda:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'dans ces jours et ces temps-là, je ferai germer à David un juste rejeton qui fera droit et justice dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'En ces jours-là Juda sera sauvée, et Jérusalem habitera en sécurité, et voici le nom dont elle sera appelée: L\'Éternel notre justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Car ainsi parle l\'Éternel: Il ne manquera pas à David d\'un homme assis sur le trône de la maison d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'et aux sacrificateurs et aux lévites il ne manquera pas d\'un homme qui se tienne devant moi, qui offre les holocaustes, et brûle les victimes, et fasse le sacrifice tous les jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Et la parole de l\'Éternel fut adressée à Jérémie en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Ainsi parle l\'Éternel: Si vous rompez le pacte que j\'ai fait avec le jour, et le pacte que j\'ai fait avec la nuit, de sorte qu\'il ne soit plus ni jour, ni nuit en son temps,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'alors aussi sera rompu le pacte que j\'ai fait avec David, mon serviteur, de sorte qu\'il n\'aura pas de fils régnant sur son trône et avec les lévites, les sacrificateurs qui me servent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'De même que l\'armée des Cieux ne peut se compter, ni le sable de la mer se mesurer, de même je multiplierai la race de David, mon serviteur, et les lévites qui sont mes ministres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Et la parole de l\'Éternel fut adressée à Jérémie en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Ne vois-tu pas ce que ce peuple dit: « Les deux familles que l\'Éternel avait choisies, Il les rejette, » et ils ont une idée si méprisante de mon peuple, qu\'il n\'est plus un peuple à leurs yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Ainsi parle l\'Éternel: Si je n\'ai pas fait mon pacte avec le jour et avec la nuit, ni les lois des Cieux et de la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'alors je rejette la race de Jacob et de David, mon serviteur, pour ne plus prendre dans sa race de dominateurs qui règnent sur la race d\'Abraham, d\'Isaac et de Jacob. Car je ramènerai leurs captifs et j\'aurai compassion d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'La parole qui fut adressée à Jérémie par l\'Éternel, lorsque Nébucadnézar, roi de Babel, et toute son armée, et tous les royaumes des pays de sa domination, et tous les peuples faisaient la guerre à Jérusalem et à toutes ses villes. Il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Ainsi parle l\'Éternel, Dieu d\'Israël: Va, et parle à Sédécias, roi de Juda, et lui dis: Ainsi parle l\'Éternel: Voici, je livre cette ville aux mains du roi de Babel, pour qu\'il la brûle par le feu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'et toi, tu n\'échapperas pas non plus à sa main, mais tu seras pris et livré à sa main, et tes yeux rencontreront les yeux du roi de Babel, et tu lui parleras bouche à bouche, et tu iras à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Cependant, écoute la parole de l\'Éternel, Sédécias, roi de Juda! Ainsi prononce l\'Éternel sur toi: Tu ne mourras point par l\'épée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'tu mourras en paix, et comme on brûla des parfums pour tes pères, les rois précédents qui furent avant toi, de même on en brûlera pour toi, et l\'on élèvera pour toi la complainte: « Hélas! Seigneur! » Car j\'ai prononcé cette parole, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Et Jérémie, le prophète, dit à Sédécias, roi de Juda, toutes ces paroles à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'Or, l\'armée du roi de Babel faisait la guerre à Jérusalem et à toutes les villes de Juda qui étaient restées, et à Lachis et à Aséka; car elles étaient restées d\'entre les villes de Juda, étant des villes fortes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'La parole qui fut adressée à Jérémie par l\'Éternel, après que le roi Sédécias eut fait une alliance avec tout le peuple de Jérusalem, dans le but de promulguer entre eux un affranchissement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'en vertu duquel chacun rendrait la liberté à son serviteur, et chacun à sa servante, homme et femme de la race des Hébreux, et personne ne prendrait pour esclave le Juif, son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Et tous les princes et tout le peuple qui étaient entrés dans l\'alliance, consentirent à affranchir chacun son serviteur, et chacun sa servante, pour ne plus les tenir en esclavage: ils consentirent et les affranchirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Mais ils changèrent ensuite, et reprirent les serviteurs et les servantes qu\'ils avaient affranchis, et se les assujettirent comme serviteurs et servantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Alors la parole de l\'Éternel fut adressée à Jérémie par l\'Éternel en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Ainsi parle l\'Éternel, Dieu d\'Israël: Je fis une alliance avec vos pères, le jour où je les tirai du pays d\'Egypte, de la maison de servitude, disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Au terme de sept années vous affranchirez chacun votre frère, l\'Hébreu qui se sera vendu à vous; il te servira six années, puis tu lui rendras sa liberté. Mais vos pères ne m\'écoutèrent point et ne prêtèrent point l\'oreille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Mais vous, vous êtes revenus en ce jour, et avez fait ce qui est droit à mes yeux, en promulguant chacun la liberté pour son prochain, et vous avez fait une alliance devant moi dans la maison appelée de mon nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'mais vous êtes revenus en arrière, et vous avez profané mon nom, en reprenant chacun son serviteur et chacun sa servante à qui vous aviez rendu la liberté, et vous les avez assujettis à être vos serviteurs et vos servantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'C\'est pourquoi ainsi parle l\'Éternel: Vous ne m\'avez point obéi jusqu\'à promulguer la liberté chacun pour son frère, et chacun pour son prochain. Voici, je promulgue votre liberté, dit l\'Éternel, et vous serez à l\'épée, à la peste et à la famine, et je vous abandonne aux avanies de tous les royaumes de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Et j\'assimilerai les hommes transgresseurs de mon alliance, qui n\'ont pas accompli les articles de l\'alliance qu\'ils ont conclue devant moi, au taureau qu\'ils ont coupé en deux, et entre les quartiers duquel ils ont passé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'les princes de Juda, et les princes de Jérusalem, les eunuques et les Sacrificateurs, et tout le peuple du pays, qui ont passé entre les quartiers de la victime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Et je les livrerai aux mains de leurs ennemis, et aux mains de ceux qui en veulent à leur vie, et leurs cadavres seront la pâture des oiseaux des Cieux et des bêtes de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Et Sédécias aussi, roi de Juda, et. ses princes, je les livrerai aux mains de leurs ennemis, et aux mains de ceux qui en veulent à leur vie, et aux mains de l\'armée du roi de Babel, qui [pour le moment] s\'est éloigné de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Voici, j\'en donne l\'ordre, dit l\'Éternel, et je les ramènerai contre cette ville, pour qu\'ils l\'assiègent et s\'en emparent, et la brûlent par le feu, et des villes de Juda je ferai un désert sans habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'La parole qui fut adressée à Jérémie par l\'Éternel, dans le temps de Jéhojakim, fils de Josias, roi de Juda, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Rends-toi auprès de la maison des Réchabites, et parle-leur, et amène-les dans la maison de l\'Éternel, dans l\'une des chambres, et offre-leur du vin à boire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Et je pris Jaasénia, fils de Jérémie, fils de Habazinia, et ses frères et tous ses fils, et toute la maison des Réchabites,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'et je les amenai à la maison de l\'Éternel, dans la chambre des fils de Hanan, fils de Gédalia, homme de Dieu, laquelle est à côté de la chambre des princes, au-dessus de la chambre de Mahaséïa, fils de Sallum, garde du seuil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Et je plaçai devant les fils de la maison des Réchabites des coupes pleines de vin, et des calices, et je leur dis: « Buvez du vin! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Mais ils dirent: Nous ne buvons pas de vin; car Jonadab, fils de Réchab, notre père, nous a donné ce commandement: Vous ne boirez point de vin, ni vous, ni vos fils, à perpétuité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'et vous ne bâtirez point de maisons, et ne sèmerez aucune semence, et ne planterez ni ne posséderez des vignes; mais vous habiterez sous des tentes toute votre vie, afin que vous viviez longtemps dans le pays où vous séjournez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Et nous sommes dociles à la voix de Jonadab, fils de Réchab, notre père, en tout ce qu\'il nous a prescrit, de sorte que nous ne buvons pas de vin durant toute notre vie, ni nous, ni nos femmes, ni nos fils, ni nos filles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'et que nous ne bâtissons pas de maisons pour nous loger, et que nous ne possédons ni vignes, ni champs, ni terre ensemencée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'et nous habitons sous des tentes, et nous écoutons et nous pratiquons tout ce que nous a prescrit Jonadab, notre père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Et, quand Nébucadnézar, roi de Babel, s\'avança dans le pays, nous dîmes: Venez, et fuyons à Jérusalem devant l\'armée des Chaldéens et devant l\'armée de Syrie; c\'est ainsi que nous habitons dans Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Alors la parole de l\'Éternel fut adressée à Jérémie en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Va et dis aux hommes de Juda et aux habitants de Jérusalem: De là ne tirerez-vous pas cette leçon, qu\'il vous faut obéir à mes paroles? dît l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'On accomplit les préceptes de Jonadab, fils de Réchab, lesquels il a donnés comme règle à ses fils, de ne point boire de vin, et ils n\'en ont pas bu jusques aujourd\'hui, car ils sont dociles à l\'ordre de leur père; et moi je vous ai parlé dès le matin, et vous ne m\'obéissez pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Et je vous ai envoyé tous mes serviteurs, les prophètes, dès le matin, pour vous dire: Renoncez donc chacun à votre mauvaise voie, et amendez votre conduite, et n\'allez plus après d\'autres dieux pour les servir; alors vous resterez dans le pays que j\'ai donné à vous et à vos pères; mais vous n\'avez point prêté l\'oreille, et ne m\'avez point obéi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Oui, les fils de Jonadab, fils de Réchab, observent la règle que leur donna leur père, et ce peuple ne m\'obéit pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'C\'est pourquoi, ainsi parle l\'Éternel, Dieu des armées, Dieu d\'Israël: Voici, j\'amène sur Juda et sur tous les habitants de Jérusalem tous les maux dont je les ai menacés, parce que je leur ai parlé, et qu\'ils n\'ont point écouté; et que je les ai appelés, et qu\'ils n\'ont point répondu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Et Jérémie dit à la maison des Réchabites: Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Parce que vous êtes dociles au commandement de Jonadab votre père, et que vous observez tous ses commandements et que vous faites selon tout ce qu\'il vous a commandé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'à cause de cela, ainsi prononce l\'Éternel des armées, Dieu d\'Israël: Il ne manquera point à Jonadab, fils de Réchab, d\'un homme qui se tienne en ma présence, dans tous les âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Et la quatrième année de Jéhojakim, fils de Josias, roi de Juda, cette parole fut adressée à Jérémie par l\'Éternel, qui dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Prends un volume, et y écris toutes les paroles que je t\'ai dites touchant Israël et Juda, et touchant tous les peuples, depuis le jour où je te parlai dans le temps de Josias jusques aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Peut-être la maison de Juda entendant parler de tout le mal que je pense à leur faire, chacun abandonnera sa voie mauvaise, et je pardonnerai leur iniquité et leur péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Alors Jérémie fit venir Baruch, fils de Nérija, et Baruch écrivit sous la dictée de Jérémie, dans un volume, toutes les paroles que l\'Éternel lui avait dites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Et Jérémie donna cet ordre à Baruch, et lui dit: Je suis retenu ici, et je ne puis me rendre à la maison de l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'va donc, et lis dans le volume ce que tu as écrit sous ma dictée, les paroles de l\'Éternel, aux oreilles du peuple, dans la maison de l\'Éternel, le jour du jeûne, et lis-les aussi aux oreilles de tous les Juifs venus de leurs villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Peut-être supplieront-ils humblement l\'Éternel, et quitteront-ils chacun leur mauvaise voie; car grande est la colère et l\'indignation dont l\'Éternel menace ce peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Et Baruch, fils de Nérija, exécuta dans son entier l\'ordre que lui avait donné Jérémie, le prophète, de lire dans le livre les paroles de l\'Éternel dans la maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Et la cinquième année de Jéhojakim, fils de Josias, roi de Juda, le neuvième mois, on publia un jeûne devant l\'Éternel; tout le peuple de Jérusalem, et tout le peuple vint des villes de Juda à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Alors Baruch lut dans le livre les paroles de Jérémie dans la maison de l\'Éternel, dans la chambre de Gémaria, fils de Schaphan, le scribe, dans le vestibule supérieur, à l\'entrée de la Porte neuve de la maison de l\'Éternel, aux oreilles de tout le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Et Michée, fils de Gémaria, fils de Schaphan, ayant entendu toutes les paroles de l\'Éternel lues dans le livre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'descendit à la maison du roi, dans la chambre du scribe; et voici, tous les princes y étaient assis, Elisama, le scribe, et Délaïa, fils de Sémaïa, et Elnathan, fils de Hachbor, et Gémaria, fils de Schaphan, et Sédécias, fils d\'Ananias, et tous les princes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Et Michée leur rapporta toutes les paroles qu\'il avait entendues, quand Baruch lisait dans le livre aux oreilles du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Alors tous les princes députèrent à Baruch Jehoudi, fils de Néthania, fils de Sélémia, fils de Couschi, pour lui dire: Prends en ta main le livre dans lequel tu as lu aux oreilles du peuple, et viens! Et Baruch, fils de Nérija, prit en sa main le livre, et vint auprès d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Et ils lui dirent: Assieds-toi, et lis-le à nos oreilles. Et Baruch lut à leurs oreilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Et à l\'ouïe de toutes ces paroles, effrayés ils s\'entre-regardèrent, et dirent à Baruch: Nous rapporterons au roi toutes ces paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Et ils interrogèrent Baruch, et dirent: Dis-nous donc comment tu as écrit toutes ces paroles sous sa dictée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Et Baruch leur dit: De sa bouche il me dictait toutes ces paroles, et je les écrivais dans ce livre avec de l\'encre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Alors les princes dirent à Baruch: Va, et te cache, ainsi que Jérémie, et que personne ne sache où vous êtes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Puis ils se rendirent auprès du roi dans la cour, et ils déposèrent le livre dans la chambre d\'Elisama, le scribe, et ils exposèrent toutes ces choses aux oreilles du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Alors le roi envoya Jehoudi pour prendre le volume; et il le prit dans la chambre d\'Elisama, le scribe; et Jehoudi le lut aux oreilles du roi, et aux oreilles de tous les princes qui entouraient le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Or le roi habitait la maison d\'hiver au neuvième mois, et le brasier brûlait devant lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Et lorsque Jehoudi en eut lu trois ou quatre colonnes, le roi le coupa avec un canif de scribe, et le jeta dans le feu du brasier, jusqu\'à ce que le volume fût consumé en entier par le feu dans le brasier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Et ils ne furent point effrayés, et ne déchirèrent point leurs habits, ni le roi, ni aucun de ses serviteurs, à l\'ouïe de toutes ces paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Bien plus, Elnathan, et Délaïa, et Gémaria intercédèrent auprès du roi, pour qu\'il ne brûlât pas le volume; mais il ne les écouta point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Et le roi ordonna à Jéraméel, fils de Hammélech, et à Séraïa, fils d\'Asriel, et à Sélémia, fils d\'Abdiel, de saisir Baruch le scribe, et Jérémie le prophète; mais l\'Éternel les cacha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Et la parole de l\'Éternel fut adressée à Jérémie, après que le roi eut brûlé le volume et les paroles que Baruch avait écrites sous la dictée de Jérémie, et Il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Prends encore un autre volume, et y écris toutes les premières paroles qui étaient dans le premier volume qu\'a brûlé Jéhojakim, roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Et quant à Jéhojakim, roi de Juda, tu lui diras: Ainsi parle l\'Éternel: Tu as brûlé ce volume en disant: Pourquoi y as-tu écrit ces paroles: Le roi de Babel viendra détruire ce pays et en exterminer les hommes et les bestiaux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'C\'est pourquoi, ainsi prononce l\'Éternel sur Jéhojakim, roi de Juda: Il n\'aura point de fils assis sur le trône de David, et son cadavre sera jeté pour être exposé à l\'ardeur du jour et au froid de la nuit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'et je punirai sur lui, et sur sa race, et sur ses serviteurs leur crime, et je ferai venir sur eux, et sur les habitants de Jérusalem, et sur les hommes de Juda, tous les maux dont je les ai menacés, sans qu\'ils aient écouté. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Et Jérémie prit un autre volume et le donna à Baruch, fils de Nérija, le scribe, lequel y écrivit sous la dictée de Jérémie toutes les paroles du livre qu\'avait brûlé au feu Jéhojakim, roi de Juda; et il fut ajouté beaucoup d\'autres paroles semblables à celles-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Et Sédécias, fils de Josias, succéda comme roi à Chonia, fils de Jéhojakim: Nébucadnézar, roi de Babel, l\'avait fait roi du pays de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Et il n\'obéit, non plus que ses serviteurs, ni le peuple du pays, aux paroles que l\'Éternel prononça par l\'entremise de Jérémie, le prophète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Et le roi Sédécias envoya Jouchal, fils de Sélémia, et Sophonie, fils de Mahaséïa, le sacrificateur, à Jérémie, le prophète, pour lui dire: Prie pour nous l\'Éternel, notre Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Or Jérémie entrait et sortait encore librement parmi le peuple, et on ne l\'avait pas encore incarcéré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Et l\'armée de Pharaon était sortie de l\'Egypte, et les Chaldéens qui assiégeaient Jérusalem, en ayant appris la nouvelle, s\'étaient retirés de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Alors la parole de l\'Éternel fut adressée à Jérémie, le prophète, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Ainsi parle l\'Éternel, Dieu d\'Israël: Ainsi parlez au roi de Juda qui vous envoie vers moi pour me consulter: Voici, l\'armée de Pharaon qui s\'avance à votre secours, retournera dans son pays, en Egypte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'et les Chaldéens reviendront assiéger cette ville, et ils la prendront, et la brûleront par le feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Ainsi parle l\'Éternel: Ne vous abusez pas vous-mêmes en disant: Les Chaldéens vont s\'éloigner de nous! car ils ne s\'en iront point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Car eussiez-vous défait toute l\'armée des Chaldéens qui vous assiègent, et ne restât-il d\'eux que des hommes percés, ils se lèveront chacun de leur tente, et brûleront cette ville par le feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Et lorsque l\'armée des Chaldéens se retirait de Jérusalem devant l\'armée de Pharaon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'Jérémie sortit de Jérusalem, pour se rendre dans le pays de Benjamin, afin d\'y recueillir un héritage, au milieu du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Et il se trouvait dans la porte de Benjamin, et là celui qui en avait l\'inspection et dont le nom était Jérija, fils de Sélémia, fils d\'Ananias, arrêta Jérémie, le prophète, en disant: Tu passes aux Chaldéens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Et Jérémie dit: C\'est une fausseté! je ne passe point aux Chaldéens. Mais Jérija, sans l\'écouter, arrêta Jérémie et le conduisit aux princes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Et les princes s\'irritèrent contre Jérémie, et le frappèrent, et le mirent en prison dans la maison de Jonathan, le scribe; car ils en avaient fait une prison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Et lorsque Jérémie fut venu dans le cachot, et dans les cellules, et qu\'il y fut resté longtemps,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'le roi Sédécias envoya et le fit chercher. Et le roi l\'interrogea dans sa maison en secret et lui dit: Y a-t-il une parole de par l\'Éternel? Et Jérémie dit: Il y en a une. Et il dit: Tu seras livré entre les mains du roi de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Et Jérémie dit au roi Sédécias: En quoi ai-je péché contre toi ou tes serviteurs ou ce peuple, que vous m\'avez mis en prison?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Et où sont vos prophètes qui vous prophétisaient disant: Le roi de Babel ne marchera pas contre vous, ni contre ce pays?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Et maintenant, écoute, ô roi, mon Seigneur, je t\'en prie, reçois mon humble prière, et ne me fais pas rentrer dans la maison de Jonathan, le scribe, pour que je n\'y meure pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Alors le roi Sédécias ordonna qu\'on déposât Jérémie dans le vestibule de la prison, et qu\'on lui donnât chaque jour un pain de la rue des boulangers, jusqu\'à ce que tout le pain fût consommé dans la ville. Ainsi Jérémie demeura dans le vestibule de la prison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Et Sephatia, fils de Mathan, et Gédalia, fils de Paschur, et Jouchal, fils de Sélémia, et Paschur, fils de Malchija, entendirent les discours que Jérémie tenait à tout le peuple, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Ainsi parle l\'Éternel: Qui restera dans cette ville, mourra par l\'épée, par la famine et par la peste, et qui se rendra aux Chaldéens vivra, et il aura sa vie pour butin, de sorte qu\'il vivra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Ainsi parle l\'Éternel: Cette ville sera livrée aux mains de l\'armée du roi de Babel qui s\'en emparera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Alors les princes dirent au roi: Que cet homme soit donc mis à mort! car ainsi, il énerve les mains des hommes de guerre, restés dans cette ville, et les mains de tout le peuple, quand il leur parle de la sorte; car cet homme ne cherche point le bien de ce peuple, mais son mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Et le roi Sédécias dit: Voici, il est entre vos mains, car le roi ne peut rien contre vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Alors ils prirent Jérémie, et le jetèrent dans la fosse de Malchija, fils de Hammélech, laquelle se trouve dans le vestibule de la prison, et ils y dévalèrent Jérémie avec des cordes, et dans la fosse il n\'y avait point d\'eau, mais de la fange, et Jérémie enfonçait dans la fange.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Et Ebedmélech, l\'Éthiopien, eunuque qui était dans la maison du roi, apprit qu\'on avait jeté Jérémie dans la fosse. Or le roi était assis à la porte de Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Alors Ebedmélech sortit de la maison du roi, et vint parler au roi en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Seigneur roi, ces hommes ont mal agi dans tout ce qu\'ils ont fait à Jérémie, le prophète, qu\'ils ont jeté dans la fosse, et il se meurt de faim sur la place, car il n\'y a plus de pain dans la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Et le roi donna cet ordre à Ebedmélech, l\'Éthiopien: Prends avec toi d\'ici trente hommes, et retire Jérémie, le prophète, de la fosse, avant qu\'il meure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Et Ebedmélech prit les hommes avec lui, et vint à la maison du roi sous le Trésor, et y prit des lambeaux d\'habits usés, et des haillons de vieilles hardes, et les dévala à Jérémie dans la fosse avec des cordes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Et Ebedmélech, l\'Éthiopien, dit à Jérémie: Mets ces haillons et ces lambeaux sous les articulations de tes mains, sous les cordes. Et Jérémie fit ainsi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Et ils tirèrent Jérémie avec des cordes en haut hors de la fosse; et Jérémie resta dans le vestibule de la prison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Puis le roi Sédécias envoya, chercher Jérémie, le prophète, et le fit venir auprès de lui dans la troisième avenue de la maison de l\'Éternel, et le roi dit à Jérémie: Je vais te demander une chose: ne me cèle rien!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Et Jérémie dit à Sédécias: Si je te la dis, ne me feras-tu pas mourir? Et si je te donne un conseil, tu ne m\'écouteras pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Alors le roi Sédécias fit en secret ce serment à Jérémie: Par la vie de l\'Éternel qui nous a créé cette âme, je ne te ferai point mourir, et ne te livrerai point entre les mains de ces hommes qui en veulent à ta vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Et Jérémie dit à Sédécias: Ainsi parle l\'Éternel, Dieu des armées, Dieu d\'Israël: Si tu sors, et te rends auprès des généraux du roi de Babel, tu auras la vie sauve, et cette ville ne sera point brûlée par le feu, et tu vivras, toi et ta maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Mais si tu ne te rends pas auprès des généraux du roi de Babel, cette ville sera livrée aux mains des Chaldéens qui la brûleront par le feu, et toi, tu n\'échapperas pas de leurs mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Et le roi Sédécias dit à Jérémie: J\'ai peur des Juifs qui ont passé aux Chaldéens, je crains qu\'on ne me livre à eux, et qu\'ils ne me maltraitent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Et Jérémie dit: Tu ne seras pas livré. Obéis donc à la voix de l\'Éternel en tout ce que je te dis, et tout ira bien pour toi, et tu auras la vie sauve;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'mais si tu refuses d\'aller, entends ce que l\'Éternel me révèle:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Voici, toutes les femmes qui restent dans la maison du roi de Juda seront menées aux généraux du roi de Babel, et elles diront: « Tes amis t\'ont trompé, et sur toi ils ont eu le dessus; tes pieds ont enfoncé dans la fange, eux s\'étant tirés en arrière. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Et toutes tes femmes et tes enfants, on les mènera aux Chaldéens, et toi, tu n\'échapperas pas de leurs mains, mais par la main du roi de Babel tu seras saisi, et tu seras la cause de l\'incendie de cette ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Et Sédécias dit à Jérémie: Que personne ne sache rien de tous ces discours, afin que tu ne meures pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Que si les princes apprennent que je t\'ai parlé, et s\'ils viennent à toi, et te disent: Eh bien! rapporte-nous ce que tu as dit au roi, et ce que le roi t\'a dit; ne nous cèle rien, et nous ne te ferons pas mourir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'dis-leur: J\'ai humblement supplié le roi de ne pas me faire rentrer dans la maison de Jonathan pour y mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, '– Et tous les princes vinrent auprès de Jérémie, et l\'interrogèrent, et il leur répondit dans les termes que le roi lui avait prescrits. Alors ils se turent et le quittèrent; car rien n\'avait transpiré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Et Jérémie demeura dans le vestibule de la prison jusqu\'au jour de la prise de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Et lorsque Jérusalem fut prise, (la neuvième année de Sédécias, roi de Juda, le dixième mois, Nébucadnézar, roi de Babel, avec toute son armée, vint devant Jérusalem, et l\'assiégea;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'la onzième année de Sédécias, le quatrième mois, le neuvième jour du mois, la ville fut forcée;)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'alors vinrent tous les généraux du roi de Babel, et ils se placèrent à la Porte du milieu; c\'étaient Nergal-Scharétser, Samgar-Nébo, Sareskim, chef des eunuques, Nergal-Scharétser, chef des mages, et tous les autres chefs du roi de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Et lorsque Sédécias, roi de Juda, et tous les gens de guerre les virent, ils s\'enfuirent, et sortirent nuitamment de la ville par le chemin des jardins du roi, et passant la porte entre les deux murailles, ils sortirent du côté de la plaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Alors l\'armée des Chaldéens se mit à leur poursuite, et ils atteignirent Sédécias dans les campagnes de Jéricho, et ils le prirent, et le menèrent à Nébucadnézar, roi de Babel, à Ribla dans le pays de Hamath, lequel prononça son jugement sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Et le roi de Babel égorgea les fils de Sédécias à Ribla sous ses yeux; et le roi de Babel égorgea aussi tous les nobles de Juda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'et il creva les yeux à Sédécias, et le lia de chaînes pour le mener à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Et les Chaldéens brûlèrent par le feu la maison du roi et les maisons du peuple, et abattirent les murs de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Et le reste du peuple demeuré dans la ville, et les transfuges qui avaient passé à lui, le reste du peuple, Nébuzaradan, chef des satellites, les déporta à Babel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'mais Nébuzaradan, chef des satellites, laissa dans le pays de Juda les petits d\'entre le peuple qui ne possédaient rien, et il leur donna des vignes et des champs dans ce temps-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Et Nébucadnézar, roi de Babel, donna ses ordres quant à Jérémie par Nébuzaradan, chef des satellites, et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Prends-le, et aie soin de lui, et ne lui fais aucun mal, et traite-le, ainsi qu\'il te le dira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Alors Nébuzaradan, chef des satellites, et Nébuschasban, chef des eunuques, et Nergal-Scharétser, chef des mages, et tous les chefs du roi de Babel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'envoyèrent chercher Jérémie du vestibule de la prison, et le remirent à Gédalia, fils d\'Achikam, fils de Schaphan, pour le conduire dans sa maison. Et ainsi il demeura au milieu du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Et la parole de l\'Éternel fut adressée à Jérémie, pendant qu\'il était détenu dans le vestibule de la prison, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Va, et parle à Ebedmélech, l\'Éthiopien, et lui dis: Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Vois, je vais faire arriver ce que j\'ai prononcé sur cette ville, du mal et non du bien, et tu seras témoin de ces événements en ce temps-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Mais je te délivrerai en ce jour-là, dit l\'Éternel, et tu ne seras point livré aux mains des hommes que tu redoutes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'car je veux te sauver, et tu ne tomberas point sous le glaive, tu auras ta vie pour ton butin, parce que tu as eu confiance en moi, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'La parole qui fut adressée à Jérémie par l\'Éternel, après que Nébuzaradan, chef des satellites, l\'eut élargi à Rama. Quand il le fit chercher, il était lié de chaînes parmi tous les prisonniers de Jérusalem et de Juda qu\'on déportait à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Et le chef des satellites prit Jérémie et lui dit: L\'Éternel, ton Dieu, avait annoncé tous ces malheurs à ce lieu-ci,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'et l\'Éternel a fait arriver, et a exécuté ainsi qu\'il l\'avait dit, car vous aviez péché contre l\'Éternel, et vous n\'aviez point obéi à sa voix, et ces choses vous sont arrivées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Et maintenant, voici, je te délivre aujourd\'hui des fers que tu portes aux mains: s\'il t\'agrée de venir avec moi à Babel, viens, j\'aurai soin de toi; mais s\'il te répugne de venir avec moi à Babel, cesse d\'y penser; regarde, tu as tout le pays devant toi, va où il te plaira, et où il t\'agréera d\'aller.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, '– Et comme il ne s\'en allait point encore: Rends-toi donc [ajouta-t-il] auprès de Gédalia, fils d\'Achikam, fils de Schaphan, que le roi de Babel a préposé sur les villes de Juda, et reste auprès de lui parmi le peuple; ou bien, va partout où il te conviendra d\'aller. Et le chef des satellites lui donna son entretien et un présent, et le congédia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Et Jérémie se rendit auprès de Gédalia, fils d\'Achikam, à Mitspa, et il demeura auprès de lui parmi le peuple laissé dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Et quand tous les chefs de l\'armée qui étaient dans les campagnes apprirent, eux et leurs hommes, que le roi de Babel avait préposé Gédalia, fils d\'Achikam, sur le pays, et qu\'il lui avait commis les hommes et les femmes, et les enfants et ceux d\'entre les petits du pays qui n\'avaient pas été déportés à Babel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'alors arrivèrent auprès de Gédalia, à Mitspa, Ismaël, fils de Néthania, et Jochanan et Jonathan, fils de Karéah, et Séraïa, fils de Tanchumeth, et les fils de Ephaï de Nétopha, et Jésanias, fils de Maachati, eux et leurs hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Et Gédalia, fils d\'Achikam, fils de Schaphan, leur fit ce serment à eux et à leurs hommes, disant: Ne redoutez point d\'être soumis aux Chaldéens! demeurez dans le pays, et soyez soumis au roi de Babel, et vous vous en trouverez bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Pour moi, voici, je reste à Mitspa, au service des Chaldéens qui viendront auprès de nous; mais vous, faites vos récoltes de vin, de fruits et d\'huile, et serrez-les dans vos vases, et habitez vos villes que vous occupez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Et tous les Juifs aussi qui étaient chez les Moabites, et chez les Ammonites, et en Édom, et ceux qui étaient dans tous les autres pays apprirent que le roi de Babel avait laissé un reste des Juifs, et préposé sur eux Gédalia, fils d\'Achikam, fils de Schaphan;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'et tous les Juifs revinrent de tous les lieux où ils étaient disséminés, et arrivèrent dans le pays de Juda auprès de Gédalia à Mitspa, et ils firent d\'abondantes récoltes de vin et de fruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Cependant Jochanan, fils de Karéah, et tous les chefs de l\'armée qui étaient dans les campagnes, vinrent auprès de Gédalia, à Mitspa,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'et lui dirent: Sais-tu bien que Bahalis, roi des Ammonites, a envoyé Ismaël, fils de Néthania, pour t\'ôter la vie? Mais Gédalia, fils d\'Achikam, ne les crut pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Et Jochanan, fils de Karéah, parla secrètement à Gédalia à Mitspa, et lui dit: Je veux aller tuer Ismaël, fils de Néthania, et personne ne le saura. Pourquoi t\'ôterait-il la vie, et tous les Juifs rassemblés autour de toi seraient-ils dispersés, et le reste de Juda perdu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Mais Gédalia, fils d\'Achikam, dit à Jochanan, fils de Karéah: N\'en fais rien! car ce que tu me dis d\'Ismaël, est faux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Et il arriva au septième mois que Ismaël, fils de Néthania, fils d\'Élisama, de la famille royale, et l\'un des Grands du roi, ayant dix hommes avec lui, vint auprès de Gédalia, fils d\'Achikam, à Mitspa, et là ils mangèrent ensemble à Mitspa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Alors Ismaël, fils de Néthania, se leva avec les dix hommes qui l\'accompagnaient, et ils frappèrent Gédalia, fils d\'Achikam, fils de Schaphan, avec l\'épée et le tuèrent, lui que le roi de Babel avait préposé sur le pays;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'et Ismaël frappa aussi tous les Juifs qui étaient avec Gédalia à Mitspa, et les Chaldéens, hommes de guerre, qui s\'y trouvaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Et deux jours après le meurtre de Gédalia, tandis que chacun l\'ignorait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'il vint des hommes de Sichem, de Silo et de Samarie, au nombre de quatre-vingts, ayant la barbe coupée, et les habits déchirés, et des incisions sur le corps, et des offrandes, et de l\'encens en leurs mains, pour les porter à la maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Alors Ismaël, fils de Néthania, sortit de Mitspa à leur rencontre; et en marchant il pleurait; et les ayant atteints il leur dit: Venez auprès de Gédalia, fils d\'Achikam!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Et quand ils furent parvenus au milieu de la ville, Ismaël, fils de Néthania, les massacra, et les jeta dans une fosse, aidé des hommes qui l\'accompagnaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Cependant parmi eux il se trouva dix hommes qui dirent à Ismaël. Ne nous fais pas mourir, car nous avons du blé, de l\'orge, de l\'huile et du miel enfouis sous terre dans les champs. Alors il les laissa, et ne les fit point mourir avec leurs frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Or la fosse où Ismaël avait jeté tous les cadavres des hommes qu\'il avait tués en même temps que Gédalia, était celle qu\'avait faite le roi Asa en vue de Baësa, roi d\'Israël: c\'est celle-là qu\'Ismaël, fils de Néthania, remplit de cadavres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Et Ismaël emmena tout le reste du peuple de Mitspa, les filles du roi et tout le peuple resté à Mitspa, que Nébuzaradan, chef des satellites, avait commis à Gédalia, fils d\'Achikam, Ismaël, fils de Néthania, les emmena captifs, et il se mit en marche pour passer chez les Ammonites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Cependant Jochanan, fils de Karéah, et tous les chefs de l\'armée qui étaient avec lui, à l\'ouïe de tous les crimes qu\'avait commis Ismaël, fils de Néthania,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'prirent tous leurs hommes, et se mirent en marche pour attaquer Ismaël, fils de Néthania, et ils l\'atteignirent aux grandes eaux de Gabaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Et quand tout le peuple qui était avec Ismaël, aperçut Jochanan, fils de Karéah, et tous les chefs de l\'armée avec lui, ils se réjouirent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'et tout le peuple qu\'Ismaël avait emmené de Mitspa, fit volte-face, et revint, et joignit Jochanan, fils de Karéah;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'mais Ismaël, fils de Néthania, échappa avec huit hommes à Jochanan, et se rendit chez les Ammonites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Alors Jochanan, fils de Karéah, et tous les chefs de l\'armée qui étaient avec lui prirent tout le reste du peuple qu\'il avait recouvré sur Ismaël, fils de Néthania, depuis Mitspa, après que celui-ci eut tué Gédalia, fils d\'Achikam, hommes et gens de guerre, et femmes, et enfants, et eunuques, qu\'il ramena de Gabaon;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'et ils se mirent en marche, et prirent leur étape à l\'hôtellerie de Chimham près de Bethléhem, afin d\'aller en Egypte');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'pour fuir les Chaldéens; car ils les redoutaient, parce que Ismaël, fils de Néthania, avait tué Gédalia, fils d\'Achikam, que le roi de Babel avait préposé sur le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Et tous les chefs de l\'armée, et Jochanan, fils de Karéah, et Jésanias, fils d\'Osée, et tout le peuple, tant les petits que les grands, s\'approchèrent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'et dirent à Jérémie, le prophète: Accueille notre humble requête, et prie pour nous l\'Éternel, ton Dieu, pour tous ces survivants, car de beaucoup nous ne restons plus qu\'un petit nombre, ainsi que tu nous vois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'afin que l\'Éternel, ton Dieu, nous indique le chemin où nous devons marcher, et la chose que nous avons à faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Et Jérémie, le prophète, leur dit: J\'obéis; voici, je vais prier l\'Éternel, votre Dieu, conformément à ce que vous avez dit; et tout ce que l\'Éternel vous répondra, je vous le rapporterai, je ne vous en déroberai rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Et ils dirent à Jérémie: Que l\'Éternel nous soit un témoin fidèle et sûr, que nous ferons tout ce dont l\'Éternel ton Dieu te chargera pour nous:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'que ce soit du bien ou du mal, nous serons dociles à la voix de l\'Éternel notre Dieu, vers qui nous t\'envoyons, afin que bien nous en arrive, si nous sommes dociles à la voix de l\'Éternel, notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Et au bout de dix jours, la parole de l\'Éternel fut adressée à Jérémie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'et il appela Jochanan, fils de Karéah, et tous les chefs de l\'armée qui étaient avec lui, et tout le peuple, tant les petits que les grands,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'et il leur dit: Ainsi parle l\'Éternel, Dieu d\'Israël, auprès de qui vous m\'avez envoyé pour lui présenter votre humble requête:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Si de nouveau vous vous fixez dans ce pays, je vous édifierai, et ne vous détruirai point; et je vous planterai, et ne vous arracherai point, car je me repens du mal que je vous ai fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Ne redoutez point le roi de Babel que vous redoutez! ne le redoutez point, dit l\'Éternel, car je suis avec vous pour vous sauver et vous délivrer de sa main,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'et je lui inspirerai de la compassion pour vous, afin qu\'il ait compassion de vous, et vous fasse rentrer dans votre pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Mais si vous dites: Nous ne resterons point dans ce pays, n\'obéissant point à la voix de l\'Éternel, votre Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'et disant: Non, car nous irons au pays d\'Egypte, où nous ne verrons point, de guerre, et n\'entendrons point le son de la trompette, et n\'aurons point faute de pain, et là nous nous fixerons... eh bien!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'alors, entendez la parole de l\'Éternel, restes de Juda! Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Si vous vous mettez en tête d\'aller en Egypte, et si vous vous y rendez pour vous y fixer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'l\'épée dont vous avez peur, vous atteindra là, dans le pays d\'Egypte, et la faim dont vous avez souci, s\'attachera à vous là, en Egypte, et là vous mourrez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Et tous ceux qui se mettront en tête d\'aller en Egypte pour s\'y fixer, périront par l\'épée, par la famine et par la peste, et il n\'en restera, n\'en réchappera pas un des calamités que j\'enverrai contre eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Car ainsi parle l\'Éternel des armées, Dieu d\'Israël: De même que ma colère et ma fureur s\'est répandue sur les habitants de Jérusalem, de même ma fureur se répandra sur vous, si vous allez en Egypte, et vous serez en exécration, et en horreur, et en malédiction et en dérision, et vous ne reverrez plus ce lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'L\'Éternel vous dit, restes de Juda: N\'allez point en Egypte! sachez que je vous en adresse la sommation aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Car vous vous abusez au péril de vos vies; car vous m\'avez envoyé auprès de l\'Éternel, votre Dieu, disant: Prie pour nous l\'Éternel, notre Dieu, et rapporte-nous tout ce que l\'Éternel, notre Dieu, dira, et nous le ferons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Et je vous l\'ai rapporté aujourd\'hui; mais vous n\'êtes point dociles à la voix de l\'Éternel, votre Dieu, ni à tout ce dont Il m\'a chargé pour vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Eh bien! sachez que vous périrez par l\'épée, par la famine et par la peste, dans le lieu où vous avez envie d\'aller vous fixer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Et lorsque Jérémie eut achevé de dire à tout le peuple toutes les paroles de l\'Éternel, leur Dieu, dont l\'avait chargé l\'Éternel, leur Dieu, pour eux, toutes ces paroles-là,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'alors prirent la parole Azarias, fils d\'Osée, et Jochanan, fils de Karéah, et tous les hommes orgueilleux, lesquels dirent à Jérémie: Tu dis un mensonge; l\'Éternel, notre Dieu, ne t\'a point chargé de nous dire: N\'allez point en Egypte pour vous y fixer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'mais c\'est Baruch, fils de Nérija, qui t\'excite contre nous pour nous livrer aux mains des Chaldéens, afin qu\'ils nous fassent mourir et nous déportent à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Et Jochanan, fils de Karéah, et tous les chefs de l\'armée, et tout le peuple n\'obéirent point à l\'ordre de l\'Éternel, de rester dans le pays de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Et Jochanan, fils de Karéah, et tous les chefs de l\'armée prirent tous les survivants de Juda, qui étaient revenus du milieu de toutes les nations où ils étaient dispersés habiter le pays de Juda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'les hommes, et les femmes, et les enfants, et les filles du roi, et toutes les personnes que Nébuzaradan, chef des satellites, avait laissées avec Gédalia, fils d\'Achikam, fils de Schaphan, et Jérémie, le prophète, et Baruch, fils de Nérija;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'et ils émigrèrent au pays d\'Egypte, car ils n\'obéirent pas à la voix de l\'Éternel, et ils s\'avancèrent jusqu\'à Tachphanès.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Et la parole de l\'Éternel fut adressée à Jérémie, à Tachphanès, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Prends en ta main de grandes pierres, et les enfonce dans de l\'argile à la tuilerie qui se trouve à la porte de la maison de Pharaon à Tachphanès, sous les yeux des Juifs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'et dis-leur: Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Voici, j\'envoie chercher Nébucadnézar, roi de Babel, mon serviteur, et je place son trône sur ces pierres, que j\'ai enfoncées, et il étendra son brillant tapis sur elles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'et il viendra et frappera le pays d\'Egypte; et à la mort, celui qui est à la mort, et à la captivité celui qui est à la captivité, et à l\'épée celui qui est à l\'épée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Et j\'allumerai un feu dans les maisons des dieux de l\'Egypte; et il les incendiera, et les emmènera, et il s\'enveloppera du pays d\'Egypte, comme le berger s\'enveloppe de son manteau, et il en sortira sain et sauf.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Et il brisera les colonnes de Bethsémès au pays d\'Egypte, et brûlera au feu les maisons des dieux de l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'La parole qui fut adressée à Jérémie pour tous les Juifs établis au pays d\'Egypte, habitant à Migdol, et à Tachphanès, et à Noph, et au pays de Pathros, en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Vous avez vu tous les maux que j\'ai fait venir sur Jérusalem et sur toutes les villes de Juda, et les voilà en ruine aujourd\'hui, et dépeuplées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'à cause du mal qu\'ils ont commis, afin de m\'irriter, en allant encenser et servir d\'autres dieux inconnus à eux, à vous et à vos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Et je vous envoyai tous mes serviteurs, les prophètes, dès le matin, pour vous dire: « Ne faites donc pas ces choses abominables que je hais! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'mais ils n\'écoutèrent point et ne prêtèrent point l\'oreille pour renoncer à leur méchanceté, en n\'encensant plus d\'autres dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Alors ma fureur et ma colère s\'épancha, et consuma les villes de Juda et les rues de Jérusalem, qui devinrent des ruines et un désert, comme elles le sont aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Et maintenant, ainsi parle l\'Éternel, Dieu des armées, Dieu d\'Israël: Pourquoi faites-vous un si grand mal pour vous perdre, que d\'être cause du retranchement de vos hommes et de vos femmes, de vos enfants et de vos nourrissons, du milieu de Juda, de sorte qu\'il ne survive aucun d\'entre vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'que de m\'irriter par l\'œuvre de vos mains, en encensant d\'autres dieux au pays d\'Egypte, où vous êtes allés demeurer, pour être exterminés, et pour devenir une malédiction et un opprobre parmi tous les peuples de la terre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Avez-vous oublié les crimes de vos pères, et les crimes des rois de Juda, et les crimes de leurs femmes, et vos crimes, et les crimes de vos femmes, commis dans le pays de Juda et dans les rues de Jérusalem?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Ils ne se sont point humiliés jusques aujourd\'hui; ils n\'ont eu aucune crainte, et n\'ont point suivi ma loi, ni mes commandements que j\'avais mis sous vos yeux et sous les yeux de vos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'C\'est pourquoi ainsi parle l\'Éternel des armées, Dieu d\'Israël: Voici, je tourne les yeux contre vous, pour maltraiter et pour exterminer tout Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Et je veux enlever les survivants de Juda qui ont pris le parti d\'aller au pays d\'Egypte pour s\'y fixer, et ils seront tous consumés; ils tomberont dans le pays d\'Egypte; l\'épée et la famine les dévoreront du petit au grand; ils périront par l\'épée et la famine, et ils seront en exécration, et en horreur, et en malédiction et en opprobre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Et je châtierai ceux qui habitent au pays d\'Egypte, comme j\'ai châtié Jérusalem, par l\'épée, la famine et la peste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'et nul ne se sauvera, ni n\'échappera parmi les survivants de Juda venus pour s\'y fixer, dans le pays d\'Egypte, et pour retourner au pays de Juda où leur âme languit de revenir habiter, car ils n\'y reviendront pas, sinon des réchappés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Et tous les hommes, qui savaient que leurs femmes avaient encensé d\'autres dieux, et toutes les femmes qui se trouvaient là en grand nombre, et tout le peuple qui habitait au pays d\'Egypte et à Pathros, répondirent à Jérémie, et dirent:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Nous n\'obéirons à rien de ce que tu nous as dit au nom de l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'mais nous voulons faire tout ce que notre bouche a exprimé, encenser la reine des Cieux, et lui offrir des libations, comme nous l\'avons fait, nous et nos pères, nos rois et nos princes, dans les villes de Juda, et dans les rues de Jérusalem, pour que nous ayons du pain en abondance, et que nous soyons heureux et que nous ne voyions pas la calamité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Car, depuis que nous avons cessé d\'encenser la reine des Cieux et de lui offrir des libations, nous manquons de tout, et nous sommes détruits par l\'épée et la famine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Et, [dirent les femmes], si nous encensons la reine des Cieux, et lui offrons des libations, est-ce à l\'insu de nos maris que nous faisons pour elle des gâteaux portant son effigie, et que nous lui offrons des libations?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Alors Jérémie s\'adressa à tout le peuple, aux hommes et aux femmes, et à tout le peuple qui lui avait répliqué, et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'L\'encens que vous avez brûlé dans les villes de Juda et les rues de Jérusalem, vous et vos pères, vos rois et vos princes, et le peuple du pays, l\'Éternel ne se le rappelle-t-Il pas, ne lui revient-il pas dans la pensée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Et l\'Éternel n\'a pu le supporter davantage, à cause de la malice de vos actions, à cause des abominations que vous avez faites, et votre pays est devenu un désert, et une désolation, et une malédiction, il a été dépeuplé, comme il l\'est aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Parce que vous avez brûlé de l\'encens, et que vous avez péché contre l\'Éternel, et que vous n\'avez point obéi à la voix de l\'Éternel, ni suivi sa loi, et ses ordonnances et ses commandements, c\'est pour cela que vous sont survenus ces maux, tels qu\'ils sont aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Et Jérémie dit à tout le peuple et à toutes les femmes: Écoutez la parole de l\'Éternel, vous tous les hommes de Juda, qui êtes au pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Vous et vos femmes, vous parlez de vos bouches, et de vos mains vous accomplissez vos paroles; vous dites: Nous accomplirons les vœux que nous avons faits, d\'encenser la reine des Cieux, et de lui offrir des libations; oui, tenez, tenez vos vœux! accomplissez, accomplissez vos vœux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Aussi, écoutez la parole de l\'Éternel, vous tous les Juifs qui habitez au pays d\'Egypte: Voici, je le jure par mon grand nom, dit l\'Éternel, mon nom ne sera plus nommé par la bouche d\'aucun des Juifs qui disent: « Vive notre Seigneur, l\'Éternel! » dans tout le pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Voici, je veille sur eux pour leur faire du mal et non pas du bien; et tous les hommes de Juda qui sont au pays d\'Egypte, périront par l\'épée et par la famine, jusqu\'à ce qu\'ils soient anéantis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Et ceux qui échapperont à l\'épée reviendront du pays d\'Egypte au pays de Juda, en petit nombre, et tous les survivants de Juda venus au pays d\'Egypte pour s\'y fixer, sauront quelle parole aura son effet, la mienne ou la leur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Et que ce soit ici, dit l\'Éternel, le signe que je vous châtierai en ce lieu, afin que vous sachiez qu\'elles auront leur effet, les menaces que je prononce contre vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'ainsi parle l\'Éternel: Voici, je livre Pharaon Hophra, roi d\'Egypte, aux mains de ses ennemis, et aux mains de ceux qui en veulent à sa vie, comme j\'ai livré Sédécias, roi de Juda, aux mains de Nébucadnézar, roi de Babel, son ennemi, qui en voulait à sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'La parole qu\'adressa Jérémie, le prophète, à Baruch, fils de Nérija, quand celui-ci écrivit toutes ces paroles dans un livre, sous la dictée de Jérémie, la quatrième année de Jéhojakim, fils de Josias, roi de Juda; il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Ainsi parle l\'Éternel, Dieu d\'Israël, à toi, Baruch:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Tu dis: Que je suis malheureux! car l\'Éternel a ajouté pour moi le chagrin à la douleur; je suis fatigué par mes soupirs, et je ne trouve aucun repos.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Parle-lui ainsi: Ainsi parle l\'Éternel: Voici, ce que j\'ai bâti, je le démolirai, et ce que j\'ai planté, je l\'arracherai, c\'est-à-dire, tout ce pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Et toi, tu demanderais pour toi de grandes choses! Ne les demande pas! car voici, je fais fondre le malheur sur toute chair, dit l\'Éternel, mais je te donnerai ta vie pour butin dans tous les lieux où tu iras.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'La parole de l\'Éternel qui fut adressée à Jérémie, le prophète, touchant les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Sur l\'Egypte, sur l\'armée de Pharaon Néco, roi d\'Egypte, qui était près du fleuve de l\'Euphrate à Carchémis, et que battit Nébucadnézar, roi de Babel, la quatrième année de Jéhojakim, fils de Josias, roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Apprêtez le bouclier et le pavois, et marchez au combat!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Attelez les chevaux! et montez-y, cavaliers! prenez vos rangs avec vos casques! nettoyez les lances! endossez la cuirasse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Pourquoi les vois-je reculer épouvantés? Leurs héros sont battus, ils fuient sans tourner la tête: terreur de toute part! dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Point de fuite pour les agiles, point de salut pour les forts; au nord, près de l\'Euphrate, ils trébuchent et tombent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Qui est celui qui s\'avance pareil au Nil? comme les torrents ses eaux se meuvent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'L\'Égyptien s\'avance pareil au Nil, et comme les torrents ses eaux se meuvent, et il dit: Je m\'avance, je vais couvrir le pays, ruiner des villes et leurs habitants!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Coursiers, en avant! chars, roulez avec furie! et que les guerriers paraissent, Éthiopiens et Libyens portant le bouclier, et Lydiens portant et bandant les arcs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Cette journée est au Seigneur, à l\'Éternel des armées, c\'est une journée de vengeance pour Le venger de ses ennemis; et l\'épée dévore et s\'assouvit, et s\'enivre de leur sang, car il se fait un sacrifice au Seigneur, à l\'Éternel des armées, dans le pays du nord près de l\'Euphrate.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Monte à Galaad, et y prends du baume, Vierge, fille de l\'Egypte! En vain multiplies-tu les remèdes; pour toi il n\'y a point de pansement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Les nations entendent parler de ton opprobre, et la terre se remplit de tes cris, car le guerrier sur le guerrier trébuche, et ensemble ils tombent tous les deux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'La parole qu\'adressa l\'Éternel à Jérémie, le prophète, sur ce que Nébucadnézar, roi de Babel, viendrait pour frapper le pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Publiez en Egypte, et proclamez à Migdol, et proclamez à Noph, et à Tachphanès! dites: Debout! équipe-toi, car l\'épée sévit autour de toi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Pourquoi tes chefs sont-ils terrassés? Ils n\'ont pas tenu tête; car l\'Éternel les a renversés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'en foule ils trébuchent et tombent l\'un sur l\'autre, et disent: Levez-vous, et retournons dans notre peuple, et au pays de notre naissance, fuyant la cruelle épée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Là on s\'écrie: Pharaon, roi d\'Egypte, est perdu! il a laissé passer le moment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Par ma vie, dit le Roi dont l\'Éternel des armées est le nom, semblable au Thabor entre les montagnes, et semblable au Carmel au-dessus de la mer, il arrive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Prépare-toi pour la captivité, toi qui habites en ces lieux, fille de l\'Egypte; car Noph sera saccagée et brûlée, dépeuplée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'L\'Egypte est une génisse superbe; un aiguillon vient du nord, il arrive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Même les mercenaires qui sont au milieu d\'elle, tels que des veaux engraissés, oui, eux aussi, ils tournent le dos; ils fuient de concert, ils ne s\'arrêtent pas, car sur eux fond le jour de leur supplice, le temps de leur châtiment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Sa voix sortira perçante comme celle du serpent, quand en force ils arriveront, et qu\'ils marcheront sur elle armés de haches, pareils à des bûcherons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Ils vont couper sa forêt, dit l\'Éternel, car elle est impénétrable, car ils sont plus nombreux que des sauterelles, et on ne peut les compter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'La fille de l\'Egypte est honteuse; elle est livrée aux mains d\'un peuple du septentrion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'L\'Éternel des armées, Dieu d\'Israël, a dit: Voici, je vais châtier Amon de No, et Pharaon, et l\'Egypte, et ses dieux et ses rois, Pharaon et ceux qui s\'appuient sur lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'et les livrer aux mains de ceux qui en veulent à leur vie, et aux mains de Nébucadnézar, roi de Babel, et aux mains de ses serviteurs; mais dans la suite [l\'Egypte] sera habitée comme aux jours d\'autrefois, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Pour toi, ne crains point, ô mon serviteur Jacob! et ne t\'effraie point, Israël! car voici, je te retirerai des pays lointains, et ta race de la contrée où elle est prisonnière; et Jacob reviendra, et il sera tranquille et heureux, sans alarmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Toi, ô mon serviteur Jacob, sois sans peur, dit l\'Éternel! car je suis avec toi! quand j\'exterminerai toutes les nations où je t\'ai disséminé, toi, je ne t\'exterminerai point; et je te châtierai, mais avec mesure; car je ne puis te laisser impuni.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'La parole de l\'Éternel qui fut adressée à Jérémie, le prophète, touchant les Philistins, avant que Pharaon forçât Gaza.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Ainsi parle l\'Éternel: Voici, des eaux s\'avancent du septentrion, et elles deviennent un torrent débordé et inondent le pays et ce qu\'il enserre, la ville et ses habitants; et les hommes crient, et tous les habitants du pays se lamentent:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'au retentissement des pas du sabot de leurs puissants coursiers, du fracas de leurs chars, du roulement de leurs roues, les pères ne tournent point la tête vers leurs fils, tant les mains faiblissent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'à cause de la journée qui s\'approche pour détruire tous les Philistins, et pour ôter à Tyr et à Sidon tous les auxiliaires qui leur restent: car l\'Éternel va détruire les Philistins, débris de l\'île de Caphthor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Gaza est rasée, c\'en est fait d\'Askalon, et du reste de leur plaine. Jusques à quand te feras-tu des incisions?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Malheur! Épée de l\'Éternel, jusques à quand ne feras-tu point de quartier? Retire-toi dans ton fourreau! sois inactive et tranquille!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Mais comment te reposerais-tu? l\'Éternel te commande. C\'est contre Askalon, et contre la côte de la mer qu\'il t\'a donné mission.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Contre Moab. Ainsi parle l\'Éternel des armées, Dieu d\'Israël: Malheur à Nébo, car elle est ravagée! Kiriathaïm est honteuse et conquise; Misgab est honteuse et atterrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Elle n\'est plus, la gloire de Moab; à Hesbon on forme contre elle des plans funestes: « Venez, et retranchons-la du nombre des nations! » Toi aussi, Madmène, tu seras détruite; derrière toi l\'épée marche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Une voix plaintive part de Choronaïm: il y a ruine et grand désastre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Moab est écrasée; les petits y font retentir leurs cris;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'car sur la montée de Luchith les pleurs montent avec les pleurs, et sur la pente de Choronaïm on entend les cris angoissés de la détresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Fuyez, sauvez votre vie, et soyez comme un homme nu dans le désert!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Car, à cause de ta confiance en tes gains et tes trésors, toi aussi, tu seras conquise, et Camos s\'en ira captif, et ses prêtres et ses princes avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Et le dévastateur fond sur toutes les villes, et aucune ville n\'échappe; la vallée est ruinée, et la plaine dévastée, comme l\'Éternel l\'a prononcé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Donnez des ailes à Moab, qu\'elle parte au vol! et ses villes seront désolées, dépeuplées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Malédiction à celui qui exécute l\'œuvre de l\'Éternel infidèlement, et malédiction à celui qui du sang sèvre son glaive!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Dès sa jeunesse Moab fut tranquille, et elle reposait sur ses lies, et ne fut pas transvasée de vase en vase, et elle ne fut point emmenée captive; aussi conserva-t-elle son goût, et son parfum ne fut point altéré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'C\'est pourquoi, voici, des jours viennent, dit l\'Éternel, où je lui enverrai des brasseurs qui remueront et videront ses vases, et briseront ses cruches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Et Moab sera confuse à cause de Camos, comme la maison d\'Israël fut confuse à cause de Béthel, l\'objet de sa confiance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Comment diriez-vous: Nou sommes des héros, et de vaillants guerriers?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Moab est saccagée, et ses villes montent [en fumée], et l\'élite de ses jeunes hommes descend à la tuerie, dit le Roi dont l\'Éternel des armées est le nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'La ruine de Moab est près d\'arriver, et son désastre vient en grande hâte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Plaignez-la, vous tous ses voisins, et vous tous qui connaissez son nom, dites: Comment a été brisé le bâton de la puissance, le sceptre de la majesté?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Descends de ta gloire, et t\'assieds sur la terre aride, habitante, fille de Dibon! car le dévastateur de Moab monte contre toi, pour détruire tes forteresses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Tiens-toi sur le chemin, et regarde, habitante d\'Aroër! interroge le fugitif et celle qui s\'échappe, et dis: Qu\'est-il arrivé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Moab est dans la honte, car elle est atterrée; gémissez et criez, publiez sur l\'Arnon que Moab est détruite!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Et le jugement est venu sur le pays de la plaine, sur Holon, et sur Jahtsa, et sur Méphaath,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'et sur Dibon, et sur Nébo, et sur Beth-Diblathaïm,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'et sur Kiriathaïm, et sur Beth-Gamoul, et sur Beth-Maon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'et sur Kérioth, et sur Botsra, et sur toutes les villes du pays de Moab éloignées et proches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'La corne de Moab est abattue, et son bras est brisé, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Frappez-la d\'enivrement, car elle s\'éleva contre l\'Éternel! et que Moab s\'agite dans son vomissement, et soit, elle aussi, livrée à la risée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Et Israël ne fut-il pas ta risée? Parmi les voleurs avait-il été surpris, que, parlant de lui, tu hoches incessamment la tête?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Abandonnez les villes, et logez-vous sur les rochers, habitants de Moab, et soyez comme la colombe qui niche à l\'entrée de la caverne!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Nous avons ouï parler de l\'orgueil de Moab, qui est très altière, et de sa hauteur, et de son orgueil, et de sa fierté, et de son cœur superbe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Je connais, dit l\'Éternel, son arrogance et son vain parler; ils ont vécu dans la vanité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Aussi je me lamente sur Moab, et pour tout Moab je soupire; sur les hommes de Kir-Charès on gémit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Vigne de Sibma, je verse sur toi plus de larmes que sur Jaëser; tes pampres ont traversé la mer, et pénétré jusqu\'à la mer de Jaëser; le dévastateur fond sur ta moisson et sur ta vendange.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'La joie et la gaieté sont bannies des vergers et de la terre de Moab; je fais tarir le vin dans les pressoirs; on ne foule plus le raisin au milieu des cris d\'allégresse; c\'est cri de guerre, et non plus cri de joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Depuis Hesbon qui gémit jusqu\'à Elealé, à Jahats ils font retentir leurs voix; de Tsoar à Choronaïm, à Eglath-Schelischia; car les eaux de Nimrim sont aussi désolées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Je retrancherai en Moab, dit l\'Éternel, ceux qui sacrifient sur les hauteurs et encensent ses dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'C\'est pourquoi mon cœur, comme la flûte, gémit sur Moab; et sur les hommes de Kir-Charès, mon cœur, comme la flûte, gémit; c\'est pourquoi les trésors qu\'ils ont acquis, périront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Car toute tête devient chauve, et toute barbe est coupée, toutes les mains portent des incisions, et tous les reins le cilice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Sur tous les toits de Moab et dans toutes ses rues, tout mène deuil, parce que j\'ai brisé Moab comme un vase qui déplaît, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Comme elle est abattue! Gémissez! Comme Moab tourne le dos dans son opprobre! Et Moab devient la risée et l\'épouvante de tous ses alentours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Car ainsi parle l\'Éternel: Voici, comme l\'aigle, il vole et déploie ses ailes sur Moab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Kérioth est conquise, et ses forts sont pris; et le cœur des héros de Moab en ce jour sera comme le cœur de la femme en travail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Et Moab sera exterminée du milieu des nations, car elle s\'est insurgée contre l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Terreur, et fosse, et filet devant toi, habitant de Moab! dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Échappé à la terreur, on tombera dans la fosse, et si l\'on se tire de la fosse, on sera pris dans le filet. Car je fais venir sur elle, sur Moab, le temps de son châtiment, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'A l\'ombre de Hesbon les fuyards se tiennent languissants; car un feu sort de Hesbon, et une flamme du milieu de Sihon, et elle dévore la contrée de Moab, et le crâne des fils du tumulte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Malheur à toi, Moab! c\'en est fait du peuple de Camos! car tes fils sont emmenés captifs, et tes filles captives.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Mais je ramènerai les captifs de Moab dans la suite des temps, dit l\'Éternel. Tel est le jugement de Moab.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Contre les fils d\'Ammon. Ainsi parle l\'Éternel: Israël n\'a-t-il donc point de fils, ou est-il sans héritier?.... Pourquoi Malcam est-il maître de Gad, et son peuple habite-t-il ses cités?...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'C\'est pourquoi, voici, des jours viennent, dit l\'Éternel, où je ferai retentir contre Rabbath des fils d\'Ammon le cri de guerre, et elle deviendra un monceau de décombres, et ses filles seront brûlées par le feu, et Israël sera maître de ses maîtres, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Gémis, Hesbon, car Aï est désolée. Criez, filles de Rabbath, ceignez le cilice, lamentez-vous, et courez çà et là entre les enclos; car Malcam part pour la captivité, et ses prêtres et ses princes avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Pourquoi te glorifies-tu de tes vallées? [Le sang] coulera dans ta vallée, fille rebelle qui te confiais dans tes trésors [disant]: « Qui est-ce qui m\'envahirait? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Voici, je te ferai envahir par la terreur, dit le Seigneur, l\'Éternel des armées, de tous tes alentours, et vous serez chassés chacun devant soi, sans que personne recueille les fugitifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Mais après cela, je ramènerai les captifs des fils d\'Ammon, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Contre Édom. Ainsi parle l\'Éternel des armées: N\'y a-t-il plus de sagesse à Théman? Les prudents conseillers ont-ils péri? la sagesse leur a-t-elle échappé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Fuyez, tournez le dos, cachez-vous dans les fonds, habitants de Dedan! Car je fais venir la peine d\'Ésaü sur lui, le temps de son châtiment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Si des vendangeurs t\'envahissaient, ne laisseraient-ils pas à grappiller? Et si c\'étaient des voleurs de nuit, ils ne feraient que le dégât nécessaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, '[Il n\'en sera pas ainsi!] car moi, je vais dépouiller Ésaü, découvrir ce qu\'il enfouit; il voudra se cacher, et il ne pourra. Sa race est détruite, ses frères et ses voisins aussi, et ils ne sont plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Abandonne tes orphelins, je les ferai vivre, et que tes veuves se reposent sur moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Car ainsi parle l\'Éternel: Voici, ceux qui ne devaient pas boire le calice, le boivent; et toi, tu serais exemptée! Tu ne seras pas exemptée, car tu auras à le boire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Car je le jure par moi-même, dit l\'Éternel, Botsra sera livrée à la désolation, à l\'opprobre, au ravage et à la malédiction, et toutes ses villes deviendront des solitudes éternelles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'J\'ai reçu un avis de l\'Éternel, et un messager a été envoyé parmi les nations: « Rassemblez-vous, et envahissez-la, et levez-vous pour le combat! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Car voici, je te rendrai petit parmi les peuples, méprisé parmi les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'La terreur que tu inspirais, t\'a séduite, l\'orgueil de ton cœur, parce que tu habites les asiles des rochers, et que tu es maîtresse de la cime des montagnes. Quand même tu places ton aire aussi haut que l\'aigle, de là je te précipiterai, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Et l\'Idumée sera dévastée; quiconque passera près d\'elle, frissonnera et se rira de toutes ses plaies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Comme au bouleversement de Sodome et de Gomorrhe et des villes voisines, dit l\'Éternel, de même il n\'y habitera personne, elle ne sera le séjour d\'aucun homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Voici, tel qu\'un lion il s\'avancera des [bois], ornement du Jourdain, contre le pacage toujours vert; car soudain je vais t\'en chasser, et y préposer celui que je choisirai. Car qui est égal à moi? qui m\'assignera? et quel est le berger qui me résisterait?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Aussi, entendez le décret décrété par l\'Éternel contre Édom, et les pensées qu\'il médite contre les habitants de Théman! En vérité, ils les traîneront comme de faibles agneaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'en vérité, il ravagera leur pâturage. Au bruit de leur chute la terre tremble, et leurs cris, jusqu\'à la Mer des algues on les entend retentir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Voici, tel qu\'un aigle, il s\'avance, il vole et déploie ses ailes sur Botsra, et le cœur des héros d\'Édom en ce jour sera comme le cœur de la femme en travail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Contre Damas. Hamath et Arpad sont dans la confusion; car elles ont reçu une nouvelle funeste; elles tremblent; près de la mer règne l\'angoisse, il ne peut y avoir de repos.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damas est défaillante; elle se retourne pour fuir, et l\'effroi la saisit; l\'angoisse et les douleurs s\'emparent d\'elle, comme de la femme en travail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, '« Dans quel abandonnement n\'est-elle pas, la cité glorieuse, la ville de mes délices! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Aussi, ses jeunes hommes tomberont dans ses rues, et tous ses guerriers périront en ce jour, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Et j\'allumerai un feu sur le mur de Damas, et il dévorera les palais de Benhadad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Contre Cédar et les royaumes de Hatsor, que défit Nébucadnézar, roi de Babel. Ainsi parle l\'Éternel: Debout! avancez-vous contre Cédar, et détruisez les enfants de l\'Orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Que leurs tentes et leurs troupeaux soient pris! Que leurs pavillons, et tous leurs meubles, et leurs chameaux leur soient enlevés, et qu\'on leur crie: Terreur de toute part!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Partez, fuyez en hâte, cachez-vous dans les fonds, habitants de Hatsor! dit l\'Éternel. Car Nébucadnézar, roi de Babel, a rendu contre vous un décret, et il médite contre vous une pensée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Debout! avancez-vous contre un peuple tranquille, qui habite en sécurité, dit l\'Éternel; il n\'a ni portes, ni verrous; il habite solitaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Et ses chameaux seront un pillage, et la multitude de ses troupeaux, une proie; et je les disperserai à tous les vents, ceux qui se rasent les tempes; et je ferai de toute part fondre sur eux la ruine, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Et Hatsor sera le gîte des chacals, une solitude éternelle, personne n\'y fixera son séjour, et aucun homme sa demeure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'La parole de l\'Éternel qui fut adressée à Jérémie, le prophète, contre Elam, au commencement du règne de Sédécias, roi de Juda, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Ainsi parle l\'Éternel des armées: Voici, je vais briser l\'arc d\'Élam, source de sa force,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'et amener sur Élam quatre vents des quatre extrémités du ciel, et les faire disperser par tous ces vents, et il n\'y aura point de peuple où ne se rendent les fugitifs d\'Élam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Et j\'intimiderai Élam devant ses ennemis et ceux qui en veulent à leur vie, et j\'amènerai sur eux une calamité, le feu de ma colère, dit l\'Éternel, et j\'enverrai après eux l\'épée, jusqu\'à ce que je les aie exterminés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Et je placerai mon trône en Élam, et j\'y détruirai rois et princes, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Mais dans la suite des temps, je ramènerai les captifs d\'Élam, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'La parole que prononça l\'Éternel sur Babel et sur le pays des Chaldéens, par Jérémie, le prophète:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Annoncez-le parmi les peuples, et publiez-le, et dressez une bannière! Publiez, ne taisez rien, dites: Babel est prise, Bel confus, Mérodach atterré, ses idoles sont confondues, et ses faux dieux consternés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Car du nord un peuple marche sur elle: il fera de son pays un désert, où il n\'y aura plus d\'habitants; les hommes et les bêtes ont fui, sont partis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'Dans ces jours et dans ce temps-là, dit l\'Éternel, les enfants d\'Israël et les enfants de Juda reviendront tous ensemble; ils chemineront en pleurant [de joie], et ils chercheront l\'Éternel, leur Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'ils s\'informeront de la route de Sion; là se tournent leurs regards: ils arrivent et s\'attachent à l\'Éternel par une alliance éternelle qui ne sera pas mise en oubli.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Mon peuple était un troupeau de brebis perdues; leurs bergers les avaient égarées et laissées errer dans les montagnes; elles couraient de montagne à colline, oubliant leur bercail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Quiconque les trouvait, les dévorait, et leurs ennemis disaient: Nous ne sommes point coupables! parce qu\'ils avaient péché contre l\'Éternel, le refuge fidèle, et l\'espoir de leurs pères, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Fuyez de Babel, et sortez du pays des Chaldéens, et soyez comme des béliers à la tête du troupeau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'car voici, je fais lever et s\'avancer contre Babel une masse de grands peuples du pays du nord; et ils se rangent en bataille contre elle; et c\'est ainsi qu\'elle sera prise. Leurs flèches sont celles d\'un adroit guerrier; elles ne reviennent pas sans effet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'La Chaldée devient un pillage, et tous ses spoliateurs seront rassasiés, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Car vous fûtes joyeux, car vous fûtes contents, spoliateurs de mon héritage! car vous vous êtes égayés comme le taureau qui foule le grain, et vous avez henni comme les étalons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Votre mère rougit fort, celle qui vous enfanta est toute confuse; voici la fin des nations, ravage, sécheresse et solitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Par l\'effet de la colère de l\'Éternel, elle ne sera plus habitée, elle sera toute déserte; quiconque passera devant Babel, hochera la tête, et se rira de toutes ses plaies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Postez-vous tout autour de Babel, vous tous qui bandez l\'arc; tirez contre elle, n\'épargnez pas les flèches; car elle a péché contre l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'De tous les côtés poussez contre elle le cri de guerre. Elle tend les mains; ses fondements s\'écroulent, ses murs tombent; car ce sont là les vengeances de l\'Éternel. Vengez-vous sur elle! faites-lui ce qu\'elle a fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Exterminez de Babel le semeur, et celui qui manie la faucille au temps de la moisson. Devant la terrible épée chacun retournera vers son peuple, et chacun fuira dans son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Israël était une brebis égarée que le lion avait effarouchée. D\'abord le roi d\'Assyrie l\'avait dévorée, et enfin Nébucadnézar, roi de Babel, lui rongea les os.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'C\'est pourquoi, ainsi parle l\'Éternel des armées, Dieu d\'Israël: Voici, je châtierai le roi de Babel et son pays, comme je châtiai le roi d\'Assyrie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'et je ramènerai Israël dans son pâturage pour qu\'il paisse sur le Carmel et à Basan, et que sur les montagnes d\'Éphraïm et en Galaad il rassasie son âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'Dans ces jours et dans ce temps-là, dit l\'Éternel, on cherchera le péché d\'Israël, et il n\'existera plus; et le crime de Juda, et il ne se trouvera plus; car je pardonnerai à ceux que je laisserai survivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Monte contre le pays doublement rebelle, et contre les habitants à punir! Massacre et extermine-les, dit l\'Éternel, et exécute tout ce que je t\'ai commandé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Cri de guerre dans le pays et grand désastre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Comme il est mis en pièces et brisé, le marteau de toute la terre! Quelle solitude Babel est devenue au milieu des nations!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Je tendis le filet contre toi, et tu t\'y es prise, Babel, à l\'improviste. Tu es atteinte et conquise, parce que tu as livré la guerre à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'L\'Éternel ouvrit son arsenal, et en tira les armes de sa colère, car le Seigneur, l\'Éternel des armées, a une œuvre à faire dans le pays des Chaldéens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Marchez sur elle de toutes parts, ouvrez ses greniers, entassez-y comme des monceaux de blé, et mettez-la au ban, et qu\'il n\'y reste rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Égorgez tous ses taureaux, qu\'ils descendent à la tuerie! Malheur à eux, car leur jour est arrivé, le temps de leur châtiment!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Les cris des fugitifs et de ceux qui se sauvent du pays de Babel, vont annoncer en Sion la vengeance de l\'Éternel, notre Dieu, la vengeance de son temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Appelez contre Babel les archers; vous tous qui bandez l\'arc, campez autour d\'elle; que personne n\'échappe; rendez-lui selon ses œuvres, et tout ce qu\'elle a fait, faites-le-lui; car elle résista orgueilleusement à l\'Éternel, au Saint d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Aussi ses jeunes hommes tomberont dans ses rues, et tous ses guerriers seront détruits en ce jour, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Me voici, à mon tour! j\'en veux à toi, orgueilleuse, dit le Seigneur, l\'Éternel des armées; car ton jour est arrivé, le temps de ton châtiment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'L\'orgueilleuse trébuchera et tombera, et personne ne la relèvera, et j\'allumerai un feu dans ses villes, qui dévorera tous ses alentours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Ainsi parle l\'Éternel des armées: Les enfants d\'Israël et les enfants de Juda subissent l\'oppression tous ensemble, et tous ceux qui les emmenèrent captifs, les retiennent, et refusent de les relâcher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Mais leur vengeur est puissant, l\'Éternel des armées est son nom; Il défendra leur cause, pour donner le repos au pays, et troubler les habitants de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'L\'épée fond sur les Chaldéens, dit l\'Éternel, et sur les habitants de Babel, et sur ses princes et sur ses sages;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'l\'épée fond sur les vains parleurs, et ils délirent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'l\'épée fond sur ses guerriers, et ils sont atterrés; l\'épée fond sur ses chevaux et sur ses chars, et sur tous les alliés qui sont chez elle, et ils deviennent des femmes; l\'épée fond sur ses trésors, et ils sont pillés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'la sécheresse envahit ses eaux, et elles tarissent; car c\'est un pays d\'idoles, ils font gloire de leurs faux dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'C\'est pourquoi il deviendra le gîte des bêtes du désert et des chacals, le gîte de l\'autruche; jamais personne n\'y habitera plus, et elle sera déserte dans tous les âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'De même que Dieu renversa Sodome et Gomorrhe et les villes voisines, dit l\'Éternel, de même personne n\'y fixera son séjour, ni aucun homme sa demeure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Voici, un peuple arrive du nord, et une grande nation et beaucoup de rois se lèvent des bouts de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'ils manient l\'arc et le javelot; ils sont cruels et sans pitié; leur voix comme la mer gronde, et sur des chevaux ils sont montés, rangés comme un seul homme en bataille contre toi, fille de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Le roi de Babel en entend la rumeur, et ses mains faiblissent; les douleurs le prennent, les maux, comme la femme en travail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Voici, tel qu\'un lion, il monte des [bois], ornement du Jourdain, dans le pacage toujours vert; tout à coup Je les en chasserai, et J\'y établirai comme chef celui que Je choisirai. Car qui est égal à moi? et qui m\'assignera? et quel est le berger qui me résisterait?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Aussi, entendez l\'arrêt que l\'Éternel arrête contre Babel, et les pensées qu\'il médite contre le pays des Chaldéens: En vérité ils les traîneront comme de faibles agneaux, et dévasteront leur pâturage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'A ce cri: « Babel est prise! » la terre tremble, et un gémissement retentit parmi les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Ainsi parle l\'Éternel: Voici, Je fais lever contre Babel et contre ceux qui habitent au milieu de mes adversaires, un souffle destructeur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'et J\'envoie contre Babel des étrangers qui les vanneront et videront leur pays; car ils s\'avanceront contre elle de toutes parts au jour du désastre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Que celui qui bande l\'arc, bande son arc contre celui qui le bande, et contre celui qui s\'avance fièrement avec sa cuirasse; n\'épargnez pas les jeunes hommes, exterminez toute son armée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'qu\'ils tombent percés de coups dans le pays des Chaldéens, et blessés dans ses rues!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Car Israël n\'est point dans le veuvage, ni Juda sans son Dieu, l\'Éternel des armées; car leur pays est rempli de crimes commis contre le Saint d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Fuyez du sein de Babel, et sauvez chacun votre vie, afin que vous ne périssiez pas par l\'effet de son crime; car c\'est le temps de la vengeance de l\'Éternel; Il va lui payer son salaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Babel était une coupe d\'or dans la main de l\'Éternel; elle enivrait toute la terre: les peuples burent de son vin, et ils entrèrent en délire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Tout à coup Babel tombe, et se brise: « Gémissez sur elle, apportez du baume pour ses plaies; peut-être guérira-t-elle. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, '– Nous voulûmes guérir Babel, mais elle n\'a pas guéri; laissons-la et retournons chacun dans notre pays, car sa condamnation atteint jusqu\'aux Cieux, et s\'élève jusques aux nues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, '– « L\'Éternel produit au jour notre innocence; venez et racontons en Sion l\'œuvre de l\'Éternel, notre Dieu! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Aiguisez les flèches, emplissez les carquois! L\'Éternel a donné l\'éveil à l\'esprit du roi des Mèdes; car sa pensée à l\'égard de Babel est de la détruire; car c\'est la vengeance de l\'Éternel, la vengeance de son temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Contre les murailles de Babel élevez un étendard, renforcez les gardes, placez des sentinelles, dressez des embuscades; car l\'Éternel l\'a dans la pensée, et Il exécute ce qu\'il a prononcé contre les habitants de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Toi qui habites auprès des grandes eaux, et qui es riche en trésors, ta fin arrive! la mesure de ta cupidité est pleine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'L\'Éternel des armées le jure par son âme: Je te remplirai d\'hommes comme de sauterelles, et ils pousseront contre toi le cri de guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Il a fait la terre par sa puissance, et fondé le monde par sa sagesse, et étendu les Cieux par son intelligence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Au son de sa voix les eaux s\'amassent dans les Cieux, et Il attire les nuées des extrémités de la terre; Il lance l\'éclair avant la pluie, et Il tire les vents de ses magasins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Tout homme est stupide faute de le connaître; pour chaque fondeur son idole est un sujet de honte, car l\'image fondue par lui est un mensonge, et elle ne respire pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'C\'est une vanité, une œuvre de la tromperie; au jour de leur châtiment elles seront détruites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Il ne leur ressemble pas, Celui qui est la part de Jacob, car Il a tout formé, et [Israël] est sa tribu d\'héritage. L\'Éternel des armées est son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Tu étais pour moi un marteau, une arme de guerre; par toi je brisais les peuples, et par toi je détruisais les empires;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'et par toi je brisais le cheval et son cavalier, et par toi je brisais le char et son conducteur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'par toi je brisais l\'homme et la femme; et par toi je brisais le vieillard et le jeune homme, et par toi je brisais l\'adolescent et la vierge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Par toi je brisais le berger et son troupeau, et par toi je brisais le laboureur et son attelage, et par toi je brisais les princes et les gouverneurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Mais je rendrai à Babel et à tous les habitants de la Chaldée tout le mal qu\'ils ont fait à Sion, sous vos yeux, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Me voici, à mon tour! J\'en veux à toi, mont destructeur, dit l\'Éternel, destructeur de toute la terre. J\'étends ma main contre toi, et je te roulerai du haut des rochers, et je ferai de toi une montagne brûlée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'de sorte qu\'on ne tire plus de toi ni pierres angulaires, ni pierres de fondements, parce que tu seras un désert à jamais, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Dressez une bannière dans le pays; sonnez de la trompette parmi les nations; enrôlez contre elle les nations, appelez contre elle les royaumes d\'Ararat, de Minni, et d\'Aschkénaz; établissez contre elle des commandants, faites avancer des chevaux comme les sauterelles velues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Enrôlez contre elle des peuples, les rois des Mèdes, leurs gouverneurs et tous leurs satrapes, et tous les pays de leur domination.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'La terre tremble et elle est en travail; car les pensées de l\'Éternel contre Babel s\'exécutent, pour faire du pays de Babel un désert sans habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Les guerriers de Babel abandonnent le combat, ils se tiennent assis dans les forts; leur bravoure est tarie; ils ne sont plus que des femmes; on a incendié leurs demeures, et leurs verrous sont brisés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Le coureur accourt au-devant du coureur, et le messager au-devant du messager, pour annoncer au roi de Babel que sa ville est prise de tous les côtés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'et les gués sont occupés, et les lacs embrasés par le feu, et les guerriers épouvantés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Car ainsi parle l\'Éternel des armées, Dieu d\'Israël: La fille de Babel est comme une aire dans le temps où on la foule; un instant encore, et le temps de la moisson vient pour elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Nébucadnézar, roi de Babel, nous a dévorés, nous a consumés; de nous il a fait un vase vide, et comme un dragon il nous a engloutis; il a rempli son ventre de nos meilleurs biens; il nous a chassés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Que la violence qui m\'est faite et ma chair déchirée retombent sur Babel, dit l\'habitante de Sion, et mon sang sur les habitants de la Chaldée, dit Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'C\'est pourquoi ainsi parle l\'Éternel: Voici, je soutiendrai ta cause, et me chargerai de ta vengeance, et je dessécherai sa mer, et tarirai sa source.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Et Babel sera un monceau de pierres, le gîte des chacals, une désolation, une dérision; elle n\'aura point d\'habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Ensemble ils rugissent comme des lions, et ils crient comme des lionceaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Quand ils seront échauffés, je leur présenterai ce qu\'ils auront à boire, et je les enivrerai, pour qu\'ils s\'égaient, puis s\'endorment d\'un sommeil éternel, et ne se réveillent plus, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Comme des agneaux je les ferai descendre à la tuerie, comme des béliers avec des boucs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Comme Sésach est prise! et la gloire de toute la terre conquise! Comme Babel excite l\'horreur parmi les nations!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'La mer est montée par-dessus Babel, et elle est couverte de la masse de ses flots.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Ses villes sont une solitude, une contrée sèche et aride, une contrée où personne n\'habite, où nul homme ne passe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Et je châtierai Bel à Babel, et je lui ôterai de la bouche ce qu\'il engloutit; et vers lui les peuples n\'afflueront plus; la muraille même de Babel tombe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Sortez-en, mon peuple, et que chacun sauve sa vie, en face du feu de la colère de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Et que votre cœur ne faiblisse pas, et n\'ayez point peur du bruit qui se répand sur la terre, quand dans cette année viendra ce bruit, puis une autre année un autre bruit, et violence sur la terre, dominateur contre dominateur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Aussi, voici, des jours viennent où je châtierai les idoles de Babel, et tout son territoire sera dans l\'opprobre, et tous ses blessés tomberont au milieu d\'elle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'et Babel excitera les transports des Cieux et de la terre, et de tout ce qu\'ils enserrent, quand du nord les dévastateurs fondront sur elle, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Comme Babel fit tomber les morts d\'Israël, de même tomberont à Babel les morts de tout le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Vous qui échappez à l\'épée, partez, ne vous arrêtez pas! De loin pensez à l\'Éternel, et que Jérusalem se présente à vos cœurs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Nous fûmes confondus, quand nous apprîmes l\'outrage; la honte couvrit nos visages, quand des étrangers pénétrèrent dans les sanctuaires de la maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Aussi, voici, des jours viennent, dit l\'Éternel, où je châtierai ses idoles, et dans tout son pays les blessés gémiront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Quoique Babel s\'élevât jusqu\'aux Cieux, et quoiqu\'elle fortifiât le siège élevé de sa puissance, de par moi les dévastateurs l\'envahiront, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Des cris plaintifs partent de Babel, et un grand déchirement du pays des Chaldéens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'C\'est que l\'Éternel dévaste Babel, et y fait périr cette foule bruyante dont les flots grondent, comme les grandes eaux, quand retentit le fracas de leurs voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'C\'est que sur elle, sur Babel, arrive le destructeur, et ses guerriers sont pris, ses arcs brisés; car l\'Éternel est un Dieu de rétribution, Il paiera, Il paiera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'J\'enivre ses princes et ses sages, ses gouverneurs, et ses satrapes, et ses guerriers, qui s\'endormiront d\'un sommeil éternel pour ne plus se réveiller, dit le Roi dont l\'Éternel des armées est le nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Ainsi parle l\'Éternel des armées: Les murailles de Babel, ses larges murailles seront rasées, et ses portes, ses hautes portes, brûlées par le feu, de sorte que les peuples auront travaillé pour rien, et que les nations se seront fatiguées au profit du feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Ordre que donna Jérémie, le prophète, à Séraïa, fils de Nérija, fils de Mahaséïa, quand il partit avec Sédécias, roi de Juda, pour Babel, la quatrième année de son règne. Or Séraïa était premier chambellan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Et Jérémie écrivit dans un livre tous les maux qui devaient arriver à Babel, toutes ces paroles écrites contre Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Et Jérémie dit à Séraïa: Quand tu seras arrivé à Babel, aie soin de faire lecture de toutes ces paroles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'et dis: Éternel, tu as dit de ce lieu que tu le détruiras, de telle sorte qu\'il n\'y ait plus d\'habitants, ni hommes, ni bestiaux, mais qu\'il devienne une solitude éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Et quand tu auras terminé la lecture de ce livre, tu y attacheras une pierre, et tu le jetteras dans l\'Euphrate,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'et tu diras: Ainsi s\'abîmera Babel, et elle ne se relèvera pas du désastre que je fais fondre sur elle; et ils seront étendus sans force. Ce sont là les paroles de Jérémie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Sédécias était âgé de vingt-un ans, quand il devint roi, et il régna onze ans à Jérusalem; et le nom de sa mère était Hamital, fille de Jérémie de Libna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Et il fit ce qui est mal aux yeux de l\'Éternel, tout comme avait fait Jéhojakim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'A cause de cela l\'Éternel fut tellement irrité contre Jérusalem et contre Juda, qu\'il les bannit de sa présence. Or Sédécias s\'était révolté contre le roi de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Et la neuvième année de son règne, le dixième mois, le dixième jour du mois, Nébucadnézar, roi de Babel, arriva avec toute son armée devant Jérusalem; et ils l\'assiégèrent, et élevèrent des terrasses tout à l\'entour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Et la ville fut bloquée jusqu\'à la onzième année du roi Sédécias.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Au quatrième mois, le neuvième jour du mois, la famine s\'empara de la ville, et il n\'y avait point de pain pour le peuple du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Et la brèche fut faite, et tous les hommes de guerre prirent la fuite, et sortirent de la ville pendant la nuit par la porte qui est entre les deux murs près du jardin du roi: cependant les Chaldéens cernaient la ville, et ils prirent le chemin de la plaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Mais l\'armée des Chaldéens poursuivit le roi, et ils atteignirent Sédécias dans les plaines de Jéricho, et toute son armée se débanda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Et ils se saisirent du roi, et le conduisirent au roi de Babel à Ribla, dans le pays de Hamath; et celui-ci prononça son jugement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Et le roi de Babel égorgea les fils de Sédécias sous ses yeux, et il égorgea aussi tous les princes de Juda à Ribla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Et il creva les yeux à Sédécias, et le lia avec des chaînes, et le roi de Babel le fit conduire à Babel, où il le tint en prison jusqu\'à sa mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Et le cinquième mois, le dixième jour du mois, (c\'était la dix-neuvième année du roi Nébucadnézar, roi de Babel) Nébuzaradan, chef des satellites, ministre du roi à Babel, vint à Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'et brûla la maison de l\'Éternel et la maison du roi et toutes les maisons de Jérusalem; il brûla par le feu toutes les grandes maisons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Et toute l\'armée des Chaldéens qui était avec le chef des satellites, démolit tous les murs de Jérusalem dans toute sa circonférence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Et Nébuzaradan, chef des satellites, emmena [plusieurs] d\'entre les petits du peuple, et le reste du peuple laissé dans la ville, et les transfuges qui avaient passé du côté du roi de Babel, et le reste de la multitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Mais Nébuzaradan, chef des satellites, en laissa d\'entre les petits du pays pour être vignerons et laboureurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Et les Chaldéens brisèrent les colonnes d\'airain qui étaient dans la maison de l\'Éternel, et les piédestaux et la mer d\'airain qui étaient dans la maison de l\'Éternel, et ils en transportèrent tout l\'airain à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Et les chaudières, et les pelles, et les couteaux, et les fioles, et les coupes, et tous les ustensiles d\'airain employés au service, ils les prirent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'et les bassins, et les brasiers, et les plats, et les pots, et les chandeliers, et les coupes et les calices, tout ce qui était d\'or et d\'argent, le chef des satellites le prit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Les deux colonnes, l\'une des mers et les douze taureaux d\'airain qui tenaient lieu de piédestal, et qu\'avait faits le roi Salomon pour la maison de l\'Éternel; le poids de l\'airain de tous ces meubles était immense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Quant aux colonnes; chaque colonne avait dix-huit coudées de haut, et un cordon de douze coudées l\'entourait, et leur épaisseur était de quatre doigts, car elles étaient creuses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'et elles étaient surmontées d\'un chapiteau d\'airain, et la hauteur d\'un chapiteau était de cinq coudées; il y avait aussi un réseau et des grenades tout autour du chapiteau, le tout d\'airain; il y avait les mêmes choses à l\'autre colonne, et les grenades aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Et les grenades étaient au nombre de quatre-vingt-seize du côté visible, et toutes les grenades étaient au nombre de cent tout autour du réseau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Et le chef des satellites prit Séraïa, souverain sacrificateur, et Sophonie, sacrificateur en second, et les trois gardes du seuil;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'et de la ville il prit un eunuque qui était préposé sur les hommes de guerre, et sept hommes parmi ceux qui voyaient le visage du roi, et qui furent trouvés dans la ville, et le secrétaire, général de l\'armée, qui enrôlait le peuple du pays pour l\'armée, et soixante hommes du peuple du pays, qui furent trouvés dans la ville;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Nébuzaradan, chef des satellites, les prit et les conduisit au roi de Babel à Ribla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Et le roi de Babel les frappa et les mit à mort à Ribla, dans le pays de Hamath. Et c\'est ainsi que Juda fut emmené loin de son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'C\'est ici le peuple que Nébucadnézar emmena: la septième année, trois mille et vingt-trois Juifs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'la dix-huitième année de Nébucadnézar, de Jérusalem, huit cent trente-deux âmes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'la vingt-troisième année de Nébucadnézar, Nébuzaradan, chef des satellites, emmena sept cent quarante-cinq Juifs; en tout quatre mille six cents âmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Et la trente-septième année après la déportation de Jéhojachin, roi de Juda, dans le douzième mois, le vingt-cinquième jour du mois, Evilmérodach, roi de Babel, l\'année où il devint roi, releva la tête de Jéhojachin, roi de Juda, et le fit sortir de prison;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'et il lui dit des paroles de bonté, et plaça son siège au-dessus du siège des rois qui étaient avec lui à Babel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'et il lui fit changer ses habits de prisonnier; et il mangea constamment en sa présence pendant tout le temps de sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Et son entretien lui fut toujours fourni par le roi de Babel, jour par jour, jusqu\'au jour de sa mort, tout le temps de sa vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Comme elle est assise solitaire, la ville [jadis] grande et peuplée! Elle est comme une veuve, celle qui fut grande parmi les nations, elle primait entre les États, et la voilà tributaire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Elle pleure, elle pleure durant la nuit, et les larmes couvrent ses joues; de tous ceux qu\'elle aimait, aucun ne la console; tous ses alliés l\'ont trahie, et lui sont devenus hostiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Juda émigré, fuyant l\'oppression et un profond esclavage; il va séjourner au milieu des nations, il n\'y trouve aucun repos; tous ses persécuteurs l\'atteignent aux défilés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Les chemins de Sion sont dans le deuil, car personne ne se rend plus aux fêtes solennelles; toutes ses Portes sont désertes; ses sacrificateurs gémissent, ses vierges sont désolées, et elle est remplie d\'amertume.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Ses adversaires ont le dessus, ses ennemis sont heureux et tranquilles, car l\'Éternel l\'afflige à cause de ses nombreux forfaits; ses enfants marchent prisonniers en tête des ennemis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'et la fille de Sion a perdu toute sa splendeur; ses princes sont comme des cerfs qui ne trouvent point de pâture, et ils marchent débiles devant celui qui les chasse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Pendant ses jours de misère et de tribulation, Jérusalem repasse sur toutes ses prospérités qui aux jours d\'autrefois étaient son partage, pendant que son peuple tombe sous la main de l\'ennemi, et que personne ne lui est en aide; les ennemis la regardent, et rient de ce qu\'elle a cessé d\'être.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jérusalem fut grandement coupable; de là l\'état hideux où elle est réduite; tous ceux qui l\'honoraient, la ravalent, parce qu\'ils voient sa nudité; et elle soupire aussi, et se détourne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Ses souillures sont [attachées] aux pans de sa robe. Elle n\'a pas considéré sa fin; c\'est pourquoi elle est extraordinairement abaissée, personne ne la console! « O Éternel, vois ma misère, comme l\'ennemi est triomphant! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'L\'ennemi porte la main sur tout ce qui lui est cher; car elle voit pénétrer dans son sanctuaire des nations auxquelles Tu avais interdit d\'entrer dans l\'assemblée des tiens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Tout son peuple soupire, il cherche du pain; il donne ses choses précieuses pour des aliments qui le rappellent à la vie. « O Éternel, vois, et regarde l\'abjection où je suis descendue! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, '« N\'êtes-vous pas touchés, vous tous qui passez? Regardez! et voyez s\'il est des douleurs égales aux douleurs qui me sont infligées, dont l\'Éternel m\'afflige au jour de son ardente colère!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'D\'en haut Il a envoyé un feu dans mes os, et il s\'en est rendu maître; Il a tendu un filet devant mes pieds, m\'a fait tomber à la renverse; Il m\'a réduite à la solitude, à une langueur de tous les jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'C\'est sa main qui a serré le joug formé par mes crimes; ils s\'entrelacent, ils pèsent sur mon col; Il a fait fléchir ma vigueur; le Seigneur m\'a livrée aux mains de ceux à qui je ne puis tenir tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Dans mon sein le Seigneur a dégradé mes héros; Il a publié une coalition contre moi, afin de tailler en pièces mes jeunes hommes; le Seigneur a foulé sous le pressoir la vierge, fille de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'C\'est sur cela que je pleure, que mes yeux, mes yeux fondent en larmes; car ils sont loin de moi ceux qui me consoleraient, me rappelleraient à la vie; mes fils sont exterminés, car l\'ennemi l\'emporte. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Sion tend les mains, il n\'y a personne pour la consoler; l\'Éternel a fait marcher contre Jacob ses ennemis de toutes parts, et parmi eux Jérusalem fut comme une femme pendant sa souillure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, '« L\'Éternel est juste, car je fus rebelle à ses ordres. O écoutez, vous tous les peuples, et voyez mes douleurs! Mes vierges et mes jeunes hommes sont partis pour la captivité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'J\'implorai mes amis, ils m\'ont trompée. Mes sacrificateurs et mes Anciens expirent dans la ville; car en vain ils ont cherché un aliment pour ranimer leur vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'O Éternel, vois comme je suis angoissée! Mes entrailles bouillonnent; mon cœur est bouleversé au dedans de moi, car je me suis rebellée. Au dehors l\'épée ravage, comme la mort au dedans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Ils m\'entendent gémir, et aucun ne me console; tous mes ennemis entendent parler de mes maux; ils se réjouissent, parce que Tu as agi. [Mais] tu amènes le jour que tu as annoncé, et ils me seront assimilés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Que toute leur méchanceté comparaisse devant toi! et traite-les comme tu m\'as traitée pour tous mes forfaits! Car je pousse beaucoup de soupirs, et mon cœur est dans la langueur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Quel nuage le Seigneur irrité répand autour de la fille de Sion! Il a précipité des Cieux sur la terre la splendeur d\'Israël, et au jour de sa colère Il ne s\'est plus souvenu du lieu où ses pieds reposaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Le Seigneur a ruiné sans pitié toutes les demeures de Jacob, Il a détruit dans sa fureur les forts de la fille de Juda, les a fait crouler sur le sol, a profané sa royauté et ses princes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Dans l\'ardeur de son courroux, Il a abattu toutes les cornes d\'Israël; en face de l\'ennemi, Il a retiré sa main, et a incendié Jacob, tel qu\'un feu enflammé qui dévore de tous côtés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Il banda son arc comme un ennemi; Il prit avec sa droite l\'attitude d\'un champion, et fit périr tout ce qui plaît à la vue; sur la tente de la fille de Sion Il versa comme un feu sa colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Le Seigneur était comme un ennemi, Il ruina Israël, ruina tous ses palais, démolit ses forts; et Il accumula sur la fille de Juda les tourments et les tortures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Et Il saccagea comme un jardin sa clôture, Il dévasta son lieu d\'assemblée; l\'Éternel fit oublier en Sion et fête et sabbat, et rejeta dans l\'ardeur de sa colère le roi et le sacrificateur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Le Seigneur prit son autel en dégoût, son sanctuaire en horreur; Il livra à la merci des mains des ennemis les murs de ses palais; ils firent retentir leur voix dans la maison de l\'Éternel, comme aux jours solennels.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'L\'Éternel décréta la ruine des murs de la fille de Sion, étendit le cordeau, ne retira point sa main pour cesser de détruire; et Il mit en deuil le boulevard et le mur, qui l\'un et l\'autre languissent attristés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Ses portes jonchent la terre, Il a détruit et rompu ses barres. Son roi et ses princes sont parmi les nations; il n\'est plus question de la Loi; ses prophètes aussi n\'obtiennent point de vision de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Les Anciens de la fille de Sion sont assis sur la terre taciturnes, ils font voler la poussière au-dessus de leurs têtes, ils sont ceints de cilices; les vierges de Jérusalem laissent retomber leurs têtes vers la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Mes yeux s\'éteignent à force de larmes, mes entrailles bouillonnent; au désastre de la fille de mon peuple ma bile s\'épanche sur la terre, lorsque dans les rues de la ville tombent inanimés les enfants et ceux qu\'on allaite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'ils disent à leurs mères: « Où [avez-vous] du pain et du vin? » tandis qu\'ils défaillent comme des blessés dans les rues de la ville, et qu\'ils rendent l\'âme sur le sein de leurs mères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Que te dire? à quoi te comparer, fille de Jérusalem? A quoi t\'assimiler pour que je te console, Vierge, fille de Sion? Car ta plaie est grande comme la mer: qui saurait te guérir?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Tes prophètes t\'ont donné comme visions le mensonge et la fausseté, et ils ne t\'ont point dévoilé ton crime, pour détourner de toi la captivité; ils t\'ont donné comme visions les oracles de la vanité et de l\'erreur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Tous les passants t\'adressent des battements de mains; ils sifflent et hochent la tête à propos de la fille de Jérusalem: « Est-ce là cette ville qu\'on appelait perfection de beauté, délices de toute la terre? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Contre toi tous tes ennemis ouvrent une large bouche; ils sifflent et grincent des dents, ils disent: « Nous avons saccagé! Oui, c\'est la journée que nous attendions! nous l\'avons atteinte, nous la voyons! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'L\'Éternel a exécuté ce qu\'il avait résolu, accompli la parole qu\'il avait arrêtée dès les jours d\'autrefois, Il a détruit sans miséricorde; et Il t\'a fait réjouir ton ennemi, Il a élevé la corne de tes adversaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Leur cœur pousse ses cris vers le Seigneur. O muraille de la fille de Sion! laisse tomber tes larmes comme un torrent le jour et la nuit, ne t\'accorde aucun relâche, que ta paupière ne se repose pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Lève-toi, gémis la nuit à l\'entrée des veilles, répands ton cœur comme des eaux devant la face du Seigneur; lève tes mains vers Lui pour [demander] la vie de tes jeunes enfants, qui dans tous les carrefours sont exténués par la faim!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Vois, Éternel, et regarde! Qui est-ce que tu as ainsi traité? Faut-il que des femmes dévorent leur fruit, les enfants portés entre leurs bras? Faut-il que dans le Sanctuaire du Seigneur le sacrificateur et le prophète soient égorgés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Sur le sol des rues l\'adolescent et le vieillard sont étendus; mes vierges et mes jeunes hommes sont tombés sous le glaive; Tu as égorgé au jour de ta colère, immolé sans miséricorde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Tu as convoqué contre moi, comme dans une fête solennelle, mes terreurs de toutes parts; et au jour de la colère de l\'Éternel, nul n\'a échappé, ni survécu; ceux que je portais entre mes bras, que j\'élevais, mon ennemi les a massacrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Je suis l\'homme qui a senti le malheur sous la verge de sa colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Il m\'a poussé, engagé dans les ténèbres, et non dans la lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Oui, tous les jours Il revient à la charge, et tourne sa a main contre moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Il a usé ma chair et ma peau, Il a brisé mes os.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Il m\'a cerné, et m\'a enveloppé d\'amertume et de malaise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Il m\'a fait entrer dans les lieux sombres, comme ceux qui dès longtemps sont morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Il m\'a parqué, pour que je n\'aie point d\'issue, Il a fait peser sur moi les fers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Que je crie, que j\'appelle du secours, Il ne donne pas accès à ma prière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Il a muré mes voies de pierres massives, et ruiné mes sentiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Il est pour moi l\'ourse qui se tient aux aguets, le lion posté en embuscade.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Il a fait dévier mes voies, et Il m\'a déchiré, Il m\'a ravagé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Il a bandé son arc, et m\'a placé comme un but à ses traits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Il a percé mes reins des flèches de son carquois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Je suis la risée de tout mon peuple, et leur chanson tout le long du jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Il m\'a rassasié d\'amertume, Il m\'a abreuvé d\'absinthe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Il a broyé mes dents avec le caillou, Il m\'a plongé dans la cendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Tu as fait déchoir mon âme du salut, j\'ai oublié le bonheur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'et je dis: C\'en est fait de la confiance et de l\'espérance que j\'avais dans l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Souviens-toi de ma misère et de mon tourment, des herbes amères et vénéneuses!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'A ces souvenirs, mon âme s\'abat au dedans de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Voici ce dont je pénètre mon cœur, et par là je garderai l\'espérance:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, '« C\'est à la grâce de l\'Éternel que [nous devons] de n\'être pas anéantis; car ses miséricordes ne s\'épuisent pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'elles sont tous les jours nouvelles, ta fidélité est immense. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'L\'Éternel est mon lot, ainsi parle mon âme; aussi j\'espère en Lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'L\'Éternel est plein de bonté pour ceux qui l\'attendent, pour l\'âme qui le cherche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Il est bon d\'attendre avec calme le secours de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Il est bon à l\'homme de porter le joug dès sa jeunesse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'de s\'asseoir solitaire et silencieux, quand Il lui impose un fardeau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'de baiser de sa bouche la poussière [en disant:] Peut-être y a-t-il de l\'espoir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'de présenter la joue à qui veut le frapper, de se laisser abreuver d\'outrages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Car le Seigneur ne rejette pas pour jamais;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'car s\'il afflige, Il prend pitié dans sa grande miséricorde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'car ce n\'est pas volontiers qu\'il humilie et afflige les enfants des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Quand on foule aux pieds tous les captifs de la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'quand on prévarique dans le jugement d\'un homme la face du Très-Haut;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'quand on fait tort à un humain dans sa cause, le Seigneur ne le voit-Il pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'A la parole de qui une chose paraît-elle, sans l\'ordre du Seigneur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Le malheur et le bonheur ne viennent-ils pas de la bouche du Très-Haut?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Pourquoi l\'homme accuse-t-il la vie? que chacun s\'en prenne à ses propres péchés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Examinons nos voies et les sondons, et retournons à l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Élevons nos cœurs en même temps que nos mains vers Dieu qui est dans le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Nous avons péché, et nous fûmes rebelles; tu ne pardonnas pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Irrité, tu te cachas, et tu nous poursuivis, tu massacras, et tu fus impitoyable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Tu t\'enveloppas dans la nue pour être inaccessible à notre prière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Tu nous as mis comme des balayures et un opprobre au milieu des nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Tous nos ennemis ouvrent contre nous une large bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Nous avons eu pour nous la terreur et la fosse, le ravage et la ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Des torrents d\'eau tombent de mes yeux à cause de la ruine de la fille de mon peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Mes yeux ruissellent sans trêve ni relâche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'jusqu\'à ce que des Cieux l\'Éternel regarde et voie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'mes yeux me font souffrir à cause de toutes les filles de ma cité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Ceux qui me sont gratuitement hostiles, m\'ont donné la chasse comme à l\'oiseau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'ils ont voulu m\'arracher la vie dans la fosse, et ils m\'ont lapidé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'les eaux m\'ont submergé jusqu\'au-dessus de la tête; je disais: C\'en est fait de moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'J\'invoquai ton nom, Éternel, du fond de la fosse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'tu entendis ma voix: ne dérobe pas ton oreille à mes cris, afin de me délivrer!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Tu t\'approches, quand je t\'implore, tu m\'as dit: Sois sans peur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Seigneur, tu soutiens ma querelle, tu rachètes ma vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Tu vois, Éternel, le tort qu\'on me fait: sois juge de ma cause!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Tu vois toutes leurs vengeances, tous les plans qu\'ils forment contre moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Tu entends leurs outrages, Éternel, et les plans qu\'ils forment contre moi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'les propos de mes adversaires, et les pensées qu\'ils nourrissent contre moi tout le jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Suis-les, quand ils sont assis, et quand ils se lèvent! je suis leur chanson.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Paie-leur, Éternel, un salaire conforme aux actes de leurs mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Donne-leur l\'endurcissement du cœur: que ta malédiction soit pour eux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Poursuis-les dans la colère, et fais-les disparaître de dessous les Cieux de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Comme l\'or s\'est terni, comme les superbes joyaux se sont altérés! Les pierres sacrées jonchent tous les carrefours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Les fils de Sion, ses enfants chéris, qui avaient le prix de l\'or fin, comme les voilà mis au taux de la vaisselle d\'argile, ouvrage des mains du potier!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Les chacals mêmes présentent la mamelle à leurs petits qu\'ils allaitent; la fille de mon peuple est barbare, comme l\'autruche de la steppe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'La langue du nourrisson est collée par la soif à son palais; les enfants demandent du pain, personne ne leur en distribue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Ceux qui mangeaient des mets délicats, souffrent le dénuement dans les rues; ceux qui étaient portés sur la pourpre, prennent le fumier pour leur couche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Le châtiment de la fille de mon peuple est plus grand que la peine de Sodome qui fut bouleversée en un moment, sans être assaillie par des mains humaines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Ses princes avaient un éclat plus pur que la neige, plus brillant que le lait; ils avaient un corps vermeil comme le corail, et la beauté du saphir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'leur aspect est devenu plus sombre que le noir; ils ne sont plus reconnus dans les rues, leur peau s\'attache à leurs os, elle a la sécheresse du bois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Les victimes de l\'épée ont un meilleur sort que les victimes de la faim, qui dépérissent minées par la disette de ce que rendent les champs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Les mains de femmes aimantes font cuire leurs propres enfants; ils servent à les nourrir dans le désastre de la fille de mon peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'L\'Éternel a achevé ses vengeances, versé le feu de sa colère; dans Sion Il alluma un feu qui dévora ses fondements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Les rois de la terre, ni aucun des habitants du monde ne croyaient que l\'ennemi et l\'adversaire pénétrassent dans les portes de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Ce fut à cause des péchés de leurs prophètes, des crimes de leurs sacrificateurs qui dans son enceinte répandirent le sang des justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Ils erraient dans les rues comme aveugles, souillés de sang, personne ne pouvant toucher leurs vêtements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, '« Loin de nous, impurs! » leur criait-on, « loin de nous! loin de nous, ne nous touchez pas! » Ils sont maintenant en fuite, ils errent aussi; on dit parmi les nations: « Ils n\'auront plus leur demeure! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'L\'aspect de l\'Éternel les a dissipés, Il ne tourne plus ses regards vers eux; on n\'a point égard aux sacrificateurs; on ne prend point pitié des vieillards.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Nos yeux languissent encore après notre délivrance; vanité! De nos vedettes nous cherchons à découvrir un peuple; il ne nous délivre pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Ils enlacent nos pas, pour nous empêcher de marcher dans nos rues; notre fin approche, nos temps sont accomplis, oui, notre fin arrive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Ceux qui nous poursuivent, sont plus légers que les aigles du ciel; sur les montagnes ils nous serrent de près, et en embuscade dans le désert ils nous épient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'L\'âme de notre vie, l\'Oint de l\'Éternel, a été pris dans leurs fosses, lui dont nous disions: Nous vivrons à son ombre au milieu des nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Livre-toi à la joie et aux transports, fille d\'Édom, habitante du pays de Uts! Mais le calice te sera aussi passé; tu seras enivrée et mise à nu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Fille de Sion, ta peine est achevée; Il ne t\'emmènera plus captive; mais Il châtiera ton crime, fille d\'Édom, Il mettra tes péchés à découvert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Songe, Éternel, à ce qui nous arrive! regarde et vois notre opprobre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Notre héritage est dévolu à des étrangers, nos maisons à des inconnus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Nous sommes orphelins, sans père; et nos mères sont comme des veuves.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'C\'est à prix d\'argent que nous buvons notre eau, contre un paiement que nous obtenons notre bois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'C\'est portant le joug sur nos têtes que nous sommes chassés; nous sommes épuisés, nous n\'avons aucun répit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'C\'est à l\'Egypte que nous tendons la main, à l\'Assyrie, pour avoir du pain à rassasiement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Nos pères ont péché; ils ne sont plus; c\'est nous qui pâtissons de leurs crimes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Des esclaves nous gouvernent, personne ne nous arrache de leurs mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Au péril de nos vies nous affrontons l\'épée du désert pour nous procurer notre pain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Notre peau s\'enflamme comme une fournaise aux feux de la faim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Dans Sion ils déshonorent les femmes, les vierges dans les villes de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'De leurs mains ils pendent les princes, la personne des Anciens n\'est pas respectée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'De jeunes hommes ont à porter les meules, et des enfants chancellent sous [des fardeaux] de bois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Les Anciens ont abandonné la Porte, et les jeunes gens leurs lyres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'La joie de nos cœurs a cessé, le deuil a remplacé nos danses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'La couronne est tombée de nos têtes; ah! malheureux que nous sommes d\'avoir péché!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'C\'est là ce qui rend nos cœurs malades, c\'est là ce qui assombrit nos regards;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'c\'est le ravage de la montagne de Sion que parcourent maintenant les renards.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Pour toi, Éternel, tu règnes éternellement, ton trône demeure pour tous les âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Pourquoi nous oublies-tu à toujours, nous délaisses-tu si longtemps?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Convertis-nous à toi, Éternel, et nous serons convertis; rends-nous des jours nouveaux, tels que ceux d\'autrefois!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Est-ce donc que tu nous as entièrement rejetés, que ta colère contre nous est si extrême?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'La trentième année, le quatrième mois, le cinquième jour du mois, comme j\'étais parmi les captifs près du fleuve Chébar, les Cieux s\'ouvrirent, et je vis des visions de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Le cinquième jour du mois (c\'était la cinquième année de la captivité du roi Jéhojachin),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'la parole de l\'Éternel fut adressée à Ézéchiel, fils de Buzi, le sacrificateur, dans le pays des Chaldéens, près du fleuve Chébar; et là, la main de l\'Éternel fut sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Et je regardai, et voici, du nord arrivait un tourbillon, une grande nuée et un globe de feu; et une splendeur l\'environnait, et de son centre, du centre du feu, sortait comme l\'éclat de l\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Et de son centre sortait une forme de quatre animaux; et tel était leur aspect: ils avaient une figure humaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Et chacun d\'eux avait quatre faces, et chacun d\'eux avait quatre ailes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Et leurs pieds étaient droits, et la plante de leurs pieds avait la forme du pied d\'un veau, et ils brillaient comme l\'éclat de l\'airain poli.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Et ils avaient par-dessous leurs ailes des mains d\'homme, à chacun de leurs quatre côtés; et tous quatre ils avaient leurs visages et leurs ailes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Leurs ailes étaient attachées l\'une à l\'autre; ils ne se tournaient point en se mettant en marche, mais ils suivaient chacun la direction de leurs faces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, '[Par devant] leurs faces avaient la figure de la face d\'un homme, et à droite la figure de celle d\'un lion pour tous les quatre, et à gauche la figure de celle d\'un bœuf pour tous les quatre, et [par derrière] celle d\'un aigle pour tous les quatre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Et en haut leurs faces et leurs ailes étaient séparées; deux ailes des uns étaient attachées aux ailes des autres, et deux couvraient leurs corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Or ils allaient chacun dans la direction de leurs faces; ils allaient où l\'esprit les poussait à aller, et ne se tournaient point dans leur marche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Et l\'aspect de ces animaux ressemblait à des charbons de feu brûlants; c\'était comme l\'aspect des flambeaux, et ce feu circulait entre les animaux, et répandait de l\'éclat, et du feu sortaient des éclairs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Et les animaux couraient et revenaient tels qu\'on voit la foudre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Comme je regardais les animaux, voici, il y avait une roue sur la terre près des animaux à leurs quatre côtés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'L\'aspect des roues et leur structure étaient ceux de la pierre de Tarsis; et la forme de l\'une était celle des quatre; et leur aspect et leur structure étaient comme si une roue passait par le milieu de l\'autre roue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Dans leur marche elles cheminaient de leurs quatre côtés, et ne se tournaient point dans leur marche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Et leurs jantes étaient hautes et formidables, et leurs jantes étaient remplies d\'yeux de toutes parts à toutes quatre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Quand les animaux marchaient, les roues cheminaient aussi à côté d\'eux, et quand les animaux s\'élevaient de terre, les roues s\'élevaient aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Au lieu où l\'esprit les poussait à aller, ils y allaient, là où l\'esprit les poussait à aller; et les roues s\'élevaient avec eux, car l\'esprit des animaux était dans les roues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Quand ils allaient, elles allaient; et quand ils s\'arrêtaient, elles s\'arrêtaient; et quand ils s\'élevaient de terre, les roues s\'élevaient aussi avec eux, car l\'esprit des animaux était dans les roues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Et au-dessus des têtes des animaux était comme un firmament qui avait l\'air d\'un cristal merveilleux, étendu sur leurs têtes dans le haut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Et sous le firmament étaient leurs ailes dirigées l\'une contre l\'autre; chacun en avait deux qui de chaque côté couvraient leur corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Et j\'entendis le bruit de leurs ailes pareil au bruit de grandes eaux, pareil à la voix du Tout-Puissant, quand ils marchaient, tumulte pareil au bruit d\'un camp; quand ils s\'arrêtaient, ils laissaient retomber leurs ailes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Et une voix retentissait au-dessus du firmament qui était sur leur tête; quand ils s\'arrêtaient, ils laissaient retomber leurs ailes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Et au-dessus du firmament posé sur leur tête était une forme de trône, qui avait l\'aspect du saphir, et sur la forme de trône était une figure ayant l\'air d\'un homme placé dessus en haut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Et au dedans et autour je vis comme le brillant de l\'airain, comme l\'aspect du feu; en regardant de ses reins en haut et en regardant de ses reins en bas, je vis comme l\'aspect du feu, et une splendeur l\'environnait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Tel l\'aspect de l\'arc qui est dans la nue au jour de la pluie, tel était l\'aspect de la splendeur qui l\'environnait. C\'était l\'aspect de l\'image de la gloire de l\'Éternel. Et je regardai et tombai sur ma face, et j\'entendis la voix de quelqu\'un qui parlait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Et Il me dit: Fils de l\'homme, dresse-toi sur tes pieds, et je te parlerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Et comme Il me parlait, l\'Esprit me pénétra et me fit tenir sur mes pieds, et je l\'entendis me parler;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'et Il me dit: Fils de l\'homme, je t\'envoie aux enfants d\'Israël, à cette race rebelle qui s\'est rebellée contre moi: eux et leurs pères se sont révoltés contre moi, jusqu\'au jour même où nous sommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Ce sont des fils au visage dur, au cœur endurci, auprès de qui je t\'envoie. Dis-leur: « Ainsi parle le Seigneur, l\'Éternel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Qu\'ils t\'écoutent, ou qu\'ils s\'y refusent (car ils sont une race réfractaire), il faut qu\'ils sachent qu\'un prophète est au milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Et toi, fils de l\'homme, n\'aie nulle peur d\'eux, et de leurs discours n\'aie nulle peur, quand même ils sont des orties et des épines pour toi, et que tu habites avec des scorpions; de leurs discours n\'aie nulle peur, et ne tremble point en leur présence, car ils sont une race réfractaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Et tu leur diras mes paroles, qu\'ils écoutent, ou qu\'ils s\'y refusent, car ils sont réfractaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Mais toi, fils de l\'homme, écoute ce que je vais te dire! Ne sois pas réfractaire, comme cette race réfractaire! Ouvre la bouche et mange ce que je te présente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Et je regardai, et voici, une main était tendue vers moi, et voici, elle tenait un volume en rouleau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Et Il le déploya devant moi, et il était écrit en dedans et en dehors; et des chants lugubres, et des complaintes, et des lamentations y étaient écrits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Et Il me dit: Fils de l\'homme, mange ce que tu trouves devant toi; mange ce volume, et t\'en va parler à la maison d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Et j\'ouvris la bouche, et Il me donna ce volume à manger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Et Il me dit: Fils de l\'homme, nourris ton ventre et remplis tes entrailles de ce volume que je te présente. Et je le mangeai, et il avait dans ma bouche la douceur du miel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Et Il me dit: Fils de l\'homme, marche et va vers la maison d\'Israël, et parle-leur en prenant mes paroles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Car ce n\'est point vers un peuple au langage obscur, à la langue inintelligible, que tu es envoyé, c\'est à la maison d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'ce n\'est pas à des peuples nombreux au langage obscur, à la langue inintelligible, dont tu ne comprends pas les discours: assurément si je t\'envoyais à eux, ils t\'écouteraient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Mais la maison d\'Israël ne voudra pas t\'écouter, car ils n\'ont pas la volonté de m\'écouter. Car toute la maison d\'Israël a le front insensible et le cœur endurci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Voici, j\'ai endurci ton visage, pour faire face à leur visage, et j\'ai endurci ton front, pour faire face à leur front.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'J\'ai rendu ton front comme le diamant, plus dur que le roc. N\'aie point peur d\'eux, et ne tremble point devant eux, car ils sont une race réfractaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Et Il me dit: Fils de l\'homme, reçois dans ton cœur toutes mes paroles que je t\'adresse, et écoute-les de tes oreilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Ainsi, marche et va vers les captifs, vers les enfants de ton peuple, parle-leur et dis-leur: « Ainsi parle le Seigneur, l\'Éternel: » qu\'ils écoutent ou qu\'ils s\'y refusent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Et l\'Esprit me souleva, et j\'entendis derrière moi le bruit d\'une grande rumeur: « Bénie soit la majesté de l\'Éternel depuis sa demeure! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'et le bruit des ailes des animaux qui s\'entre-heurtaient, et le bruit des roues à leurs côtés, et le bruit d\'une grande rumeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Et l\'Esprit me souleva et m\'emporta. Et je m\'en allai irrité dans l\'amertume de mon âme; mais la main de l\'Éternel agissait sur moi avec puissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Et j\'arrivai auprès des captifs à Thel-Abib, habitant près du fleuve Chébar, et je m\'arrêtai où ils demeuraient, et je demeurai là sept jours, éperdu au milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Et au bout des sept jours, la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Fils de l\'homme, je t\'ai établi sentinelle sur la maison d\'Israël, et de ma bouche tu entendras la parole, et tu les avertiras de par moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Quand j\'aurai dit à l\'impie: Tu mourras! et que tu ne l\'avertisses pas, et ne parles pas pour détourner l\'impie de sa voie impie, afin qu\'il vive, cet impie mourra de son péché; mais je te redemanderai son sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Mais si tu as averti l\'impie, et qu\'il ne revienne pas de son impiété et de sa voie impie, il mourra de son péché: mais toi tu auras sauvé ton âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Que si un juste se détourne de sa justice et fait le mal, alors je mettrai devant lui un piège qui le fera tomber, et il mourra. Si tu ne l\'as pas averti, il mourra de son péché, et il ne sera tenu aucun compte de la justice qu\'il a pratiquée; mais je te redemanderai son sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Mais si tu as averti le juste de ne pas pécher, et que ce juste ne pèche pas, il aura la vie, parce qu\'il se sera laissé avertir, et toi, tu auras sauvé ton âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Là encore la main de l\'Éternel se posa sur moi et Il me dit: Lève-toi, sors et va dans la vallée, et là je te parlerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Et m\'étant levé je sortis et allai dans la vallée, et voici, la gloire de l\'Éternel m\'y apparut, telle que la gloire que j\'avais vue près du fleuve Chébar, et je tombai la face contre terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Et l\'Esprit me pénétra et me dressa sur mes pieds. Puis Il me parla et me dit: Va et te renferme dans ta maison!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Quant à toi, fils de l\'homme, voici, on te mettra des chaînes, et on t\'en liera, et tu ne pourras te montrer parmi eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Et j\'attacherai ta langue à ton palais, et tu seras muet et ne seras point pour eux un censeur, car ils sont une race réfractaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Mais quand je t\'adresserai la parole, je t\'ouvrirai la bouche, pour que tu leur dises: Ainsi parle le Seigneur, l\'Éternel. Que celui qui voudra écouter, écoute, et que celui qui n\'en voudra rien faire, n\'en fasse rien; car ils sont une race réfractaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Et toi, fils de l\'homme, prends une brique et la place devant toi, et y dessine une ville, Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Et mets autour d\'elle un siège, et élève autour d\'elle des tours, et forme autour d\'elle des terrasses, et mets autour d\'elle un camp, et place à l\'entour des béliers dirigés contre elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Puis prends une chaudière de fer, et mets-la comme un mur de fer entre toi et la ville, et fixe tes regards du côté d\'elle, et qu\'ainsi elle soit en état de siège, et fais-en le siège. Que ce soit là un signe pour la maison d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Puis couche-toi sur ton côté gauche, et tu y appliqueras l\'iniquité de la maison d\'Israël. Tu seras chargé de leur iniquité autant de jours que tu seras ainsi couché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Et moi, je te fixe pour le nombre des jours les années de leur iniquité, [savoir] trois cent quatre-vingt-dix jours: ainsi tu porteras l\'iniquité de la maison d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Et quand tu seras à leur terme, recouche-toi sur ton côté droit, et sois chargé de l\'iniquité de la maison de Juda, pendant quarante jours: je te fixe chaque jour pour une année.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Et tourne vers le siège de Jérusalem tes regards et ton bras nu, et prophétise contre elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Et voici, je te mets des chaînes, afin que tu ne te tournes pas d\'un côté sur l\'autre, jusqu\'à ce que tu aies achevé les jours de ton siège.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Et prends du froment, et de l\'orge, et des fèves, et des lentilles, et du millet, et de l\'épeautre, et mets-les dans un vase, et fais-en ton pain autant de jours que tu seras couché sur ton côté: tu en mangeras trois cent quatre-vingt-dix jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Et la nourriture que tu mangeras, devra avoir un poids, celui de vingt sicles par jour: tu la mangeras d\'un terme à l\'autre terme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Et tu boiras de l\'eau, selon une mesure, un sixième de hin: tu boiras d\'un terme à l\'autre terme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Et tu mangeras des galettes d\'orge que tu feras cuire avec des excréments humains sous leurs yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Et l\'Éternel dit: Ainsi les enfants d\'Israël mangeront leur pain souillé, parmi les nations où je les exilerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Alors je dis: Ah! Seigneur Éternel, voici, mon âme ne s\'est point souillée, et depuis ma jeunesse à maintenant je n\'ai mangé ni corps mort, ni corps déchiré, et jamais viande impure n\'entra dans ma bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Et Il me dit: Voici, je te permets du fumier de vache, au lieu d\'excréments humains, et tu apprêteras ton pain là-dessus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Et Il me dit: Fils de l\'homme, voici, je vais détruire en Jérusalem le pain qui sustente, et ils mangeront un pain pesé, et dans le chagrin, et boiront une eau mesurée, et dans la stupeur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'afin qu\'ils manquent de pain et d\'eau, et soient éperdus les uns et les autres, et se consument par leur iniquité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Et toi, fils de l\'homme, prends une épée tranchante, prends un rasoir de barbier, et passe-le sur ta tête et sur ta barbe, et prends une balance à peser et partage les [cheveux].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Brûles-en un tiers au feu dans le milieu de la ville, quand les jours du siège seront accomplis; puis prends-en un tiers et le coupe avec l\'épée tout autour d\'elle, et jettes-en un tiers au vent, et je tirerai l\'épée derrière eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Puis prends-en une petite quantité, et les serre dans le bord de ton manteau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'et parmi ceux-ci prends-en encore quelques-uns et les jette au feu, et les brûle au feu. De là sortira un incendie sur toute la maison d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Ainsi parle le Seigneur, l\'Éternel: C\'est Jérusalem; je l\'avais placée au milieu des peuples, entourée des contrées de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Mais dans son impiété elle a plus résisté à mes lois que les nations, et à mes décrets plus que les pays d\'alentour; car ils ont méprisé mes lois, et n\'ont point suivi mes décrets.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Aussi, ainsi parle le Seigneur, l\'Éternel: Parce que vous avez murmuré plus haut que les peuples qui vous entourent, n\'avez pas suivi mes décrets, ni pratiqué mes lois, et que même vous n\'avez pas pratiqué les lois des peuples qui vous entourent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'pour cela, ainsi parle le Seigneur, l\'Éternel: Me voici aussi contre toi, et j\'exécuterai mes jugements dans ton sein aux yeux des nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Et je te ferai ce que je n\'ai point encore fait, et ne ferai plus désormais, à cause de toutes tes abominations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'C\'est pourquoi des pères mangeront leurs fils dans ton sein, et des fils mangeront leurs pères. Et exerçant sur toi mes jugements, je disperserai tous tes restes à tous les vents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Aussi, par ma vie, dit le Seigneur, l\'Éternel, puisque tu as souillé mon sanctuaire par toutes tes horreurs et toutes tes abominations, moi aussi je te retirerai mes regards, moi aussi je serai sans miséricorde et sans pitié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Un tiers des tiens mourra par la peste et périra par la famine dans ton sein; et un tiers tombera par l\'épée autour de toi, et j\'en disperserai un tiers à tous les vents, et je tirerai l\'épée derrière eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Ainsi s\'assouvira ma colère, et je ferai tomber ma fureur sur eux et je me vengerai. Alors ils reconnaîtront que c\'est moi, l\'Éternel, qui ai parlé dans mon courroux, quand j\'ai assouvi ma fureur sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Et je te rendrai un désert et un opprobre parmi les peuples qui t\'entourent, aux yeux de tous les passants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Et tu seras en opprobre et en dérision, en exemple et en horreur aux peuples qui t\'entourent, quand j\'exécuterai sur toi des jugements avec colère et courroux, et avec la fureur de la vengeance; (c\'est moi, l\'Éternel qui parle)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'quand j\'enverrai sur eux les flèches funestes de la famine, qui seront un fléau, que j\'enverrai pour vous détruire, ajoutant encore à vos maux la famine, et vous ôtant le pain qui sustente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Et j\'enverrai contre vous la famine et les bêtes féroces qui vous priveront d\'enfants; et la peste et le sang passeront au milieu de toi; et je ferai venir l\'épée sur toi. C\'est moi, l\'Éternel, qui parle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Fils de l\'homme, tourne tes regards vers les montagnes d\'Israël, et prophétise contre elles');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'et dis: Montagnes d\'Israël, écoutez la parole du Seigneur, de l\'Éternel. Ainsi parle le Seigneur, l\'Éternel, aux montagnes et aux collines, aux vallées et aux vallons: Voici, je fais venir contre vous l\'épée, et je détruirai vos hauts lieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'et vos autels seront dévastés, et vos statues du soleil brisées, et je ferai tomber vos hommes tués devant vos idoles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'et je placerai les cadavres des enfants d\'Israël devant leurs idoles, et je répandrai vos ossements autour de vos autels.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Dans tous vos établissements les villes seront désolées, et les hauteurs dévastées, afin que vos autels soient désolés et dévastés, et que vos idoles soient brisées et anéanties, et que vos statues du soleil soient mutilées, et que tous vos ouvrages soient détruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'Et les hommes tués tomberont parmi vous, et vous saurez que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Mais j\'en laisserai un reste, puisqu\'il en est d\'entre vous qui échapperont à l\'épée parmi les nations, quand vous serez dispersés dans leurs pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Et les vôtres qui échapperont, se souviendront de moi parmi les nations où ils seront menés captifs, quand j\'aurai brisé leur cœur adultère qui s\'était détaché de moi, et leurs yeux adultères qui suivaient leurs idoles, et quand ils auront eux-mêmes en dégoût les crimes qu\'ils commirent par toutes leurs abominations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Alors ils reconnaîtront que je suis l\'Éternel: ce n\'est pas vainement que j\'ai parlé de leur faire tous ces maux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Ainsi parle le Seigneur, l\'Éternel: Bats des mains et frappe du pied, et dis un hélas! sur toutes les méchantes abominations de la maison d\'Israël, car par l\'épée, la famine et la peste ils tomberont.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Éloigné, par la peste on mourra; et rapproché, sous l\'épée on tombera; laissé de reste et conservé, de la famine on mourra;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'ainsi assouvirai-je ma colère sur eux. Alors vous reconnaîtrez que je suis l\'Éternel, quand leurs blessés seront gisants au milieu de leurs idoles, autour de leurs autels, sur toute colline élevée, sur tous les sommets des montagnes, et sous tous les arbres verts, et sous tous les chênes touffus, lieux où ils ont offert de doux parfums à toutes leurs idoles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Et j\'étendrai ma main contre eux, et ferai du pays un ravage et une désolation, plus grande que le désert de Dibla, dans tous les lieux où ils habitent. Alors ils reconnaîtront que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Et toi, fils de l\'homme, ainsi prononce le Seigneur, l\'Éternel, sur le pays d\'Israël: Une fin, il vient une fin pour les quatre extrémités du pays!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Maintenant la fin arrive pour toi, je vais lancer ma fureur contre toi, et te juger d\'après tes voies, et faire retomber sur toi toutes tes abominations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Mes yeux seront sans pitié pour toi, et je n\'aurai point de compassion; mais je ferai retomber sur toi ta conduite, et tes abominations demeureront en toi, afin que vous reconnaissiez que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Ainsi parle le Seigneur, l\'Éternel: Un malheur! malheur unique! voici, il arrive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'La fin arrive; elle arrive la fin: c\'en est fait de toi! voici, elle arrive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Ton tour vient, habitant du pays! Le temps arrive, le jour est proche; c\'est une rumeur, et non les cris joyeux des montagnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Je vais incessamment verser ma colère sur toi, et assouvir ma fureur sur toi, et te juger selon tes voies, et faire retomber sur toi toutes tes abominations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Mes yeux seront sans pitié, et je n\'aurai point de compassion; selon tes œuvres je te rendrai, et tes abominations seront dans ton sein, afin que vous reconnaissiez que c\'est moi l\'Éternel, qui frappe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Voici le jour! voici, il arrive! le tour vient! la verge fleurit, l\'orgueil germe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'La violence s\'élève comme la verge de l\'impiété. D\'eux il ne restera rien, ni de leur foule, ni de leur multitude, et ils n\'auront plus de magnificence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Le temps arrive, le jour est imminent. Que l\'acheteur ne se réjouisse pas, et que le vendeur ne s\'afflige pas; car il y a courroux contre toute leur multitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Car le vendeur ne recouvrera pas ce qu\'il a vendu, fût-il encore parmi les vivants; car la prophétie faite contre toute leur multitude ne sera pas retirée, et quiconque vit dans son impiété, ne pourra subsister.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'On sonne la trompette, et l\'on prépare tout; mais personne ne marche au combat; car ma colère est contre toute leur multitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Au dehors l\'épée, et au dedans la peste et la famine. Qui sera dans les champs, mourra par l\'épée, et qui sera dans la ville, par la famine et la peste sera dévoré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Et s\'il en échappe, ils seront sur les montagnes, comme les colombes des vallées, tous gémissant, chacun pour son crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Toutes les mains sont défaillantes, et tous les genoux se fondent en eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Ils se ceignent du cilice, et l\'effroi les enveloppe: la honte est sur tous les visages, et toutes les têtes sont devenues chauves.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Ils jetteront leur argent dans les rues, et leur or sera pour eux de l\'ordure. Leur argent ni leur or ne pourra les sauver au jour de la colère de l\'Éternel; ils ne pourront en assouvir leurs désirs, ni en remplir leurs entrailles; car c\'est ce qui les fit tomber dans le crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'L\'éclat qui les pare, excita leur orgueil, et ils en ont fabriqué leurs abominations et leurs infamies; c\'est pourquoi je le rendrai pour eux de l\'ordure,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'et j\'en ferai la proie des étrangers, et le butin des impies de la terre, afin qu\'ils le souillent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Et je détournerai d\'eux mon visage; et l\'on profanera mon secret [sanctuaire]: des furieux y pénétreront et le profaneront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Prépare les chaînes! Car le pays est rempli du crime de sang versé, et la ville est remplie de violence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Et je ferai venir les plus méchants d\'entre les peuples, pour qu\'ils s\'emparent de leurs maisons; et je mettrai un terme à l\'orgueil des puissants, et leurs sanctuaires seront profanés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'La ruine arrive, et ils cherchent le salut, mais il n\'y en a point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Il arrive désastre sur désastre; on entend nouvelle sur nouvelle; ils demandent des oracles aux prophètes, mais la loi échappe aux sacrificateurs, et la prudence aux vieillards.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Le roi est dans le deuil, et le prince est enveloppé d\'épouvante, et les mains du peuple du pays sont tremblantes. D\'après leur conduite je veux les traiter, et selon leurs mérites je les jugerai, afin qu\'ils reconnaissent que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'La sixième année, le sixième mois, le cinquième jour du mois, comme j\'étais assis dans ma maison, et que les Anciens de Juda étaient assis devant moi, alors la main du Seigneur Éternel descendit sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Et je regardai, et voici, c\'était une figure ayant l\'aspect du feu; depuis ce qui paraissait être ses reins en bas, c\'était du feu, et de ses reins en haut, c\'était une espèce de splendeur, comme celle de l\'airain brillant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Et elle étendit la forme d\'une main, et me saisit aux boucles de ma chevelure. Puis l\'Esprit me souleva entre la terre et le ciel, et me conduisit à Jérusalem, en vision divine, à l\'entrée de la porte intérieure, qui donne vers le nord, et où était placée la statue de la jalousie qui provoquait la jalousie [de l\'Éternel].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Et voici, là se trouvait la gloire du Dieu d\'Israël, pareille à la vision que j\'en avais eue dans la vallée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Et Il me dit: Fils de l\'homme, lève donc les yeux vers le nord! Et je levai les yeux vers le nord, et voici, au nord de la porte de l\'autel, était cette statue de la jalousie, à l\'entrée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Et Il me dit: Fils de l\'homme, vois-tu ce qu\'ils font? Ce sont de grandes abominations que la maison d\'Israël fait ici, tellement que je vais m\'éloigner de mon sanctuaire. Et tu reverras encore de grandes abominations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Puis Il me conduisit à l\'entrée du parvis, et je regardai, et voici, il y avait un trou dans le mur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Et Il me dit: Fils de l\'homme, perce donc la muraille! Et je perçai la muraille et voici, il y avait une porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Et Il me dit: Entre, et vois les abominations odieuses qu\'ils font là!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Alors j\'entrai et je regardai, et voici, c\'étaient toutes sortes d\'images de reptiles et d\'animaux immondes, et toutes les espèces d\'idoles de la maison d\'Israël, dessinées sur la muraille tout à l\'entour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Et soixante-dix hommes d\'entre les Anciens de la maison d\'Israël, entre autres Jaasénia, fils de Schaphan, debout au milieu d\'eux, se tenaient devant elles, chacun son encensoir à la main, et le parfum d\'un nuage d\'encens s\'élevait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Et Il me dit: Vois-tu, fils de l\'homme, ce que les Anciens de la maison d\'Israël font dans les ténèbres, chacun dans leurs chambres couvertes de peintures! Car ils disent: L\'Éternel ne nous voit pas! l\'Éternel a abandonné le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Et Il me dit: Tu reverras encore les grandes abominations qu\'ils commettent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Puis Il me conduisit à l\'entrée de la porte de la maison de l\'Éternel, qui est du côté du nord, et voici, là se trouvaient assises les femmes, pleurant Thammuz.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Et Il me dit: As-tu vu, fils de l\'homme? Tu reverras encore des abominations plus grandes que celles-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Alors Il me conduisit dans le parvis intérieur de la maison de l\'Éternel, et voici, à l\'entrée du temple de l\'Éternel, entre le portique et l\'autel, étaient environ vingt-cinq hommes, tournant le dos au temple de l\'Éternel, et le visage du côté de l\'orient: et ils adoraient à l\'orient le Soleil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Et Il me dit: As-tu vu, fils de l\'homme? Est-ce trop peu pour la maison de Juda de faire les abominations qu\'ils font ici, qu\'ils remplissent encore le pays de violences, et qu\'ils reviennent toujours à m\'irriter? Et voici, ils tiennent le rameau contre leur nez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Mais moi aussi j\'agirai dans ma colère; je serai sans pitié et sans miséricorde; et quand ils crieront à mes oreilles à haute voix, je ne les entendrai pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Ensuite Il prononça à mes oreilles d\'une voix forte ces paroles: Faites avancer les châtiments de cette ville, chacun avec son instrument de destruction à la main!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Et voici, six hommes arrivèrent par le chemin de la porte supérieure qui donne au nord, ayant chacun à la main un instrument pour frapper; et au milieu d\'eux il y avait un homme vêtu de lin, qui portait une écritoire à sa ceinture. Et ils vinrent se placer à côté de l\'autel d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Et la gloire du Dieu d\'Israël, s\'élevant du Chérubin sur lequel elle était, se porta au seuil de la maison et appela l\'homme vêtu de lin, qui avait une écritoire à sa ceinture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'Et l\'Éternel lui dit: Passe au milieu de la ville, au milieu de Jérusalem, et marque d\'un signe le front des hommes qui soupirent et gémissent de toutes les abominations commises au milieu d\'elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Et Il dit aux autres à mes oreilles: Traversez la ville après lui, et frappez, soyez sans pitié et sans miséricorde!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Vieillards, jeunes hommes, et vierges, et petits enfants, et femmes, tuez-les jusqu\'à extermination; mais pour quiconque portera le signe, ne le touchez pas; et commencez par mon sanctuaire. Et ils commencèrent par les vieillards qui étaient devant la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Puis Il leur dit: Souillez la maison et remplissez les parvis de morts: sortez! Et étant sortis, ils portèrent leurs coups dans la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Et comme ils frappaient, et que seul j\'étais resté, je tombai sur ma face et je m\'écriai, et dis: Ah! Seigneur Éternel, veux-tu donc détruire tous les restes d\'Israël en versant ta colère sur Jérusalem?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Et Il me dit: Le crime de la maison d\'Israël et de Juda passe toute mesure, et le pays est rempli de meurtres, et la ville est remplie de prévarications. Car ils disent: L\'Éternel a abandonné le pays, et l\'Éternel ne voit rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Mais moi aussi je serai sans pitié et sans compassion; je ferai retomber leurs œuvres sur leurs têtes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Et voici, l\'homme vêtu de lin, qui avait une écritoire à sa ceinture, fit la réponse et dit: J\'ai fait comme tu m\'as commandé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Puis je regardai, et voici, sur le firmament qui était au-dessus de la tête des Chérubins, il y avait comme une pierre de saphir, et au-dessus d\'elle on voyait une forme qui avait l\'air d\'un trône.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Et [l\'Éternel] parla à l\'homme vêtu de lin et lui dit: Va dans l\'intervalle des roues sous les Chérubins, et remplis tes mains des charbons ardents qui sont entre les Chérubins, et répands-les sur la ville. Et il y alla sous mes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Or les Chérubins se trouvaient à droite de la maison, quand l\'homme alla, et la nuée remplit le parvis intérieur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Alors la gloire de l\'Éternel s\'élevant de dessus les Chérubins, se porta vers le seuil de la maison, et la maison fut remplie de la nuée, et le parvis fut rempli de la splendeur de la gloire de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Et le bruit des ailes des Chérubins se fit entendre jusqu\'au parvis extérieur, tel que la voix du Dieu tout-puissant, quand Il parle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Et quand Il eut donné cet ordre à l\'homme vêtu de lin: Prends du feu dans l\'intervalle des roues entre les Chérubins! il vint et se plaça près des roues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Alors un Chérubin étendit sa main entre les Chérubins vers le feu qui était entre les Chérubins, et il en prit, et le mit dans les mains de l\'homme vêtu de lin, qui le prit, et sortit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Et on voyait aux Chérubins une forme de main d\'homme sous leurs ailes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Puis je regardai, et voici, il y avait quatre roues à côté des Chérubins, une roue à côté de chaque Chérubin, et l\'aspect des roues était celui d\'une pierre de Tarsis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Et à les voir, c\'était une seule forme pour les quatre, comme si une roue traversait l\'autre roue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Dans leur marche elles suivaient la direction de leurs quatre côtés, elles ne se tournaient point dans leur marche, mais elles allaient du côté où la tête était tournée; elles ne se tournaient pas dans leur marche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Et tout leur corps, et leur dos, et leurs mains, et leurs ailes, et les roues étaient pleins d\'yeux tout autour, à chacun des quatre, et leurs roues aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Quant aux roues, elles furent appelées tourbillon à mes oreilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Et ils avaient chacun quatre faces; la face du premier était une face de Chérubin, et la face du second une face d\'homme, et celle du troisième une face de lion, et celle du quatrième une face d\'aigle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Et les Chérubins s\'élevèrent. C\'étaient les animaux que j\'avais vus près du fleuve Chébar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Et quand les Chérubins allaient, les roues allaient à côté d\'eux, et quand les Chérubins soulevaient leurs ailes pour s\'élever de terre, les roues aussi ne s\'écartaient point d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Quand ils s\'arrêtaient, elles s\'arrêtaient, et quand ils s\'élevaient, elles s\'élevaient avec eux; car l\'esprit des animaux était en elles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Or la gloire de l\'Éternel ayant quitté le seuil de la maison, s\'arrêta sur les Chérubins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Et les Chérubins soulevèrent leurs ailes, et s\'élevèrent de terre sous mes yeux; à leur sortie les roues les accompagnaient. Et ils s\'arrêtèrent à l\'ouverture de la porte de la maison de l\'Éternel à l\'orient, et la gloire du Dieu d\'Israël reposait sur eux d\'en haut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'C\'étaient les animaux que j\'avais vus au-dessous du Dieu d\'Israël, près du fleuve Chébar, et je reconnus que c\'étaient des Chérubins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Chacun d\'eux avait quatre faces, et chacun d\'eux avait quatre ailes, et une forme de mains d\'homme sous leurs ailes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Et la figure de leurs faces était celle des faces que j\'avais vues près du fleuve Chébar, c\'était leur air et c\'était eux-mêmes. Ils marchaient chacun dans la direction de leurs faces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Puis l\'Esprit me souleva, et m\'amena à la porte antérieure de la maison de l\'Éternel, qui donne à l\'orient, et voici, à l\'entrée de la porte il y avait vingt-cinq hommes, et je vis parmi eux Jaasénia, fils de Hazzur, et Platéia, fils de Bénaïa, princes du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Et Il me dit: Fils de l\'homme, ce sont là les hommes qui méditent le crime, et conseillent le mal dans cette ville;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'ils disent: Ce n\'est pas le moment de bâtir des maisons; cette [ville] est la chaudière et nous sommes les viandes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'C\'est pourquoi prophétise contre eux, prophétise, fils de l\'homme!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Et l\'Esprit de l\'Éternel tomba sur moi, et me dit: Dis: Ainsi parle l\'Éternel: C\'est ainsi que vous parlez, maison d\'Israël! et ce que vous avez dans l\'esprit, je le sais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Vous avez multiplié les meurtres dans cette ville et rempli ses rues de morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'C\'est pourquoi ainsi parle le Seigneur, l\'Éternel: Vos morts que vous avez étendus au milieu d\'elle, ce sont les viandes et elle est la chaudière; mais vous, on vous en fera sortir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Vous craignez l\'épée, et c\'est l\'épée que je ferai venir sur vous, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Et je vous ferai sortir du milieu d\'elle, et vous livrerai aux mains des étrangers, et j\'exécuterai sur vous mes jugements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Sous l\'épée vous tomberez, à la frontière d\'Israël je vous jugerai, afin que vous reconnaissiez que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Elle ne sera pas pour vous une chaudière, et vous n\'y serez pas comme des viandes; c\'est à la frontière d\'Israël que je vous jugerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Et vous reconnaîtrez que je suis l\'Éternel, dont vous n\'avez point suivi les décrets, ni pratiqué les lois; mais vous avez suivi les lois des peuples de vos alentours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Et comme je prophétisais, Platéia, fils de Bénaïa, mourut; et je tombai sur ma face, et je m\'écriai à haute voix et dis: Ah! Seigneur Éternel, veux-tu faire extermination du reste d\'Israël?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Fils de l\'homme, ce sont tes frères, tes frères, les gens de ta parenté, c\'est la maison d\'Israël tout entière à qui les habitants de Jérusalem disent: Demeurez loin de l\'Éternel, c\'est à nous que le pays a été donné en propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Dis donc: Ainsi parle le Seigneur, l\'Éternel: Quand même je les tiens éloignés parmi les nations, et quand même je les ai dispersés dans les pays divers, je veux être pour eux un saint asile, pendant quelque temps, dans les pays où ils sont venus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Dis donc: Ainsi parle le Seigneur, l\'Éternel: Je vous recueillerai du milieu des peuples, et vous réunirai en vous tirant des pays où vous êtes épars, et je vous donnerai le pays d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Et ils y viendront et en ôteront toutes ses infamies et toutes ses abominations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Et je leur donnerai un seul et même cœur, et je mettrai en eux un esprit nouveau, et j\'ôterai de leur corps leur cœur de pierre, et leur donnerai un cœur de chair,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'afin qu\'ils suivent mes ordonnances et qu\'ils observent et pratiquent mes lois; et ils seront mon peuple, et moi je serai leur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Pour ceux dont le cœur marche au gré de leurs infamies et de leurs abominations, je ferai retomber leur conduite sur leur tête, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Et les Chérubins soulevèrent leurs ailes, et les roues cheminaient à côté d\'eux, et la gloire du Dieu d\'Israël était en haut au-dessus d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Et la gloire de l\'Éternel s\'éleva du milieu de la ville, et vint s\'arrêter sur la montagne qui est à l\'orient de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Puis l\'Esprit m\'enleva et me ramena en Chaldée auprès des captifs, en vision par l\'Esprit de Dieu. Et la vision que j\'avais eue, s\'évanouit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'et je redis aux captifs toutes les paroles de l\'Éternel qu\'Il m\'avait révélées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Fils de l\'homme, tu résides au milieu d\'une race rebelle, qui a des yeux pour voir, mais ne voit pas, des oreilles pour entendre, mais n\'entend pas, car c\'est une race rebelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Mais toi, fils de l\'homme, fais-toi un attirail d\'émigrant, et émigre de jour sous leurs yeux, et émigre du lieu où tu es, en un autre lieu, sous leurs yeux. Peut-être verront-ils qu\'ils sont une race rebelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Et tu feras partir ton attirail, comme un attirail d\'émigrant, de jour sous leurs yeux, et toi, tu partiras le soir sous leurs yeux, comme on part pour émigrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Sous leurs yeux fais une brèche au mur de ta maison, et fais sortir ton attirail parla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Sous leurs yeux mets-le sur ton épaule, emporte-le de nuit, tu te voileras le visage pour ne pas voir le pays; car je t\'ai mis comme signe prophétique devant la maison d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Et j\'exécutai l\'ordre que j\'avais reçu. Je fis sortir mon attirail comme un attirail d\'émigrant, de jour; et le soir je fis une brèche au mur de ma maison avec la main, et le fis sortir de nuit, le prenant sur l\'épaule sous leurs yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Et le matin, la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Fils de l\'homme, la maison d\'Israël, cette race rebelle, ne t\'a-t-elle pas dit: Que fais-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Dis-leur: Ainsi parle le Seigneur, l\'Éternel: C\'est le prince qui est à Jérusalem que désigne cette prophétie, ainsi que toute la maison d\'Israël qui s\'y trouve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Dis: Je suis votre signe prophétique. La chose que j\'ai faite, est celle qui leur arrivera: ils émigreront et iront en captivité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Et le prince qui est parmi eux portera sur son épaule un fardeau, de nuit, et partira; à la muraille on fera une brèche pour l\'y faire passer; il se voilera le visage pour ne pas voir de ses yeux le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Et j\'étendrai mon réseau sur lui, afin qu\'il se prenne dans mon filet, et je l\'amènerai à Babel, au pays des Chaldéens, mais il ne le verra pas et il y mourra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Et tous ceux qui l\'entourent, ses auxiliaires, et tous ses bataillons, je les disséminerai à tous les vents, et tirerai l\'épée derrière eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Alors ils reconnaîtront que je suis l\'Éternel, quand je les aurai dispersés parmi les nations, et disséminés dans les pays divers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Cependant j\'en laisserai un petit nombre survivre à l\'épée, à la famine et à la peste, afin qu\'ils racontent toutes leurs abominations aux nations chez lesquelles ils viendront, et qu\'ils reconnaissent que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Fils de l\'homme, mange ton pain dans le trouble, et bois ton eau dans l\'anxiété et les alarmes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'Et dis au peuple du pays: Ainsi prononce le Seigneur, l\'Éternel, sur les habitants de Jérusalem dans le pays d\'Israël: Ils mangeront leur pain dans les alarmes, et boiront leur eau dans la stupeur, parce que leur pays sera désolé, dépouillé de tout ce qui y est, à cause de l\'injustice de tous ceux qui l\'habitent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'et les villes peuplées deviendront désertes, et le pays sera désolé, afin que vous sachiez que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Fils de l\'homme, qu\'est-ce que ces discours moqueurs dans le pays d\'Israël? vous dites: Les jours se prolongent, et toutes les visions sont perdues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Pour cela dis-leur: Ainsi parle le Seigneur, l\'Éternel: Je ferai cesser ces discours moqueurs, et on ne les tiendra plus en Israël. Dis-leur au contraire: Le temps approche, et toutes les visions s\'accompliront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Car désormais il n\'y aura plus de visions vaines, ni d\'oracles trompeurs dans la maison d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'car je suis l\'Éternel; je parle, et ce que je dis s\'exécutera, sans plus long délai: oui, c\'est durant vos jours, race rebelle, que je parle et que j\'exécuterai ma parole, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Fils de l\'homme, voici, les hommes d\'Israël disent: La vision qu\'il a, est à long terme, et c\'est pour des temps éloignés qu\'il prophétise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'C\'est pourquoi dis-leur: Ainsi parle le Seigneur, l\'Éternel: Tout ce que j\'ai prononcé, ne sera plus ajourné, et mes paroles seront exécutées, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Fils de l\'homme, prophétise contre les prophètes d\'Israël qui prophétisent, et dis à ceux qui prophétisent d\'après leurs sentiments propres: Écoutez la parole de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Ainsi parle le Seigneur, l\'Éternel: Malheur aux prophètes insensés qui suivent leur esprit propre, et ne voient rien!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Tels des renards dans des ruines, tels sont tes prophètes, Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Vous ne montez pas à la brèche, et n\'élevez point de mur autour de la maison d\'Israël, afin de tenir ferme dans le combat à la journée de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Ils ont des visions trompeuses, et des présages menteurs, ceux qui disent: « L\'Éternel a dit, » tandis que l\'Éternel ne les a point envoyés; et qui font espérer les effets de leur parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Vos visions ne sont-elles pas trompeuses, et vos présages menteurs, quand vous dites: « L\'Éternel a dit, » tandis que je n\'ai point parlé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Aussi, ainsi parle le Seigneur, l\'Éternel: Parce que vos discours sont trompeurs et vos visions des mensonges, pour cela, c\'est à vous que j\'en veux, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Et je ferai sentir ma main aux prophètes dont les visions sont trompeuses et les présages menteurs. Ils ne seront point associés à mon peuple, ni inscrits au rôle de la maison d\'Israël, ni introduits au pays d\'Israël, afin que vous sachiez que je suis le Seigneur, l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'eparce que, oui, parce qu\'ils égarent mon peuple en disant: Salut! tandis qu\'il n\'y a point de salut, et que, s\'il élève un mur, eux ils le recouvrent de plâtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Dis à ceux qui replâtrent, qu\'il s\'écroulera: il pleuvra par torrents, et vous, pierres de la grêle, vous tomberez et le vent des tempêtes éclatera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'Et voici, le mur croulera. Ne vous dira-t-on pas: Où est le plâtre dont vous l\'avez recouvert?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Aussi, ainsi parle le Seigneur, l\'Éternel: Dans ma fureur je ferai éclater le vent des tempêtes, et dans ma colère la pluie viendra par torrents, avec les pierres de la grêle dans mon courroux, afin de détruire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Et je ferai crouler le mur que vous recouvrîtes de plâtre, et je le coucherai par terre, et ses fondements seront mis à nu; il est tombé et vous périssez sous ses ruines, afin que vous sachiez que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Et ainsi j\'assouvirai ma fureur sur ce mur et sur ceux qui le recouvrent de plâtre; puis je vous dirai: Le mur n\'est plus; ils ne sont plus ceux qui le replâtraient,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'les prophètes d\'Israël, qui prophétisent à Jérusalem, et dont les visions lui présagent le salut, tandis qu\'il n\'y a pas de salut, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Et toi, fils de l\'homme, tourne tes regards du côté des filles de ton peuple qui prophétisent d\'après leur sentiment propre, et prophétise contre elles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'et dis: Ainsi parle le Seigneur, l\'Éternel: Malheur à vous qui cousez des coussinets pour toutes les jointures de la main, et faites des oreillers pour les têtes de toutes les tailles, pour prendre les âmes au piège! Penseriez-vous prendre au piège les âmes de mon peuple, et conserver la vie aux vôtres?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Vous me déshonorez auprès de mon peuple pour quelques poignées d\'orge et pour quelques bouchées de pain, en annonçant la mort aux âmes qui ne doivent pas mourir, et la vie aux âmes qui ne doivent pas vivre; en trompant mon peuple qui prête l\'oreille au mensonge. Aussi, ainsi parle le Seigneur, l\'Éternel:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Voici, je m\'attaque à vos oreillers où vous prenez les âmes au piège, afin qu\'elles s\'envolent, et je les arracherai de vos bras, et je dégagerai les âmes que vous prenez au piège, afin qu\'elles s\'envolent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Et je mettrai vos oreillers en pièces, et je tirerai mon peuple de vos mains, afin qu\'il ne soit plus une proie entre vos mains et que vous sachiez que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Parce que vous affligez le cœur du juste par le mensonge, quand moi-même je ne l\'ai pas affligé, et parce que vous fortifiez le méchant dans ce qu\'il fait, en sorte qu\'il ne quitte pas sa mauvaise voie pour obtenir la vie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'à cause de cela, vous n\'aurez plus vos visions mensongères et vous ne ferez plus de prédictions, et je tirerai mon peuple de vos mains, afin que vous sachiez que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Et des hommes d\'entre les Anciens d\'Israël vinrent auprès de moi et s\'assirent devant moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Alors la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Fils de l\'homme, ces gens-là se sont affectionnés à leurs idoles, et mettent devant leurs yeux ce qui les pousse au crime; leur donnerais-je accès auprès de moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Aussi parle et dis-leur: Ainsi parle le Seigneur, l\'Éternel: Si quelqu\'un des hommes de la maison d\'Israël, qui s\'est affectionné à ses idoles, et met devant ses yeux ce qui le pousse au crime, vient néanmoins trouver un prophète, moi qui suis l\'Éternel, je lui ferai sur cela une réponse conforme au grand nombre de ses idoles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'de manière à prendre sur le fait dans son propre cœur la maison d\'Israël que toutes ses idoles ont détachée de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Aussi dis à la maison d\'Israël: Ainsi parle le Seigneur, l\'Éternel: Revenez et détournez-vous de vos idoles, et de toutes vos abominations détournez vos regards.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Car à tout homme de la maison d\'Israël, et à tout étranger domicilié en Israël, qui s\'est éloigné de moi, et affectionné à ses idoles, et qui met devant ses yeux ce qui le pousse au crime, s\'il vient trouver un prophète pour me consulter par lui, moi, l\'Éternel, je lui ferai une réponse digne de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Et je tournerai ma face contre cet homme-là, pour le perdre et faire de lui un signe et un proverbe, et je l\'extirperai du milieu de mon peuple, afin que vous sachiez que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Que si un prophète se laisse entraîner à parler, c\'est moi l\'Éternel qui laisserai entraîner ce prophète, et je lèverai ma main sur lui, et l\'exterminerai du milieu de mon peuple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'C\'est ainsi qu\'ils porteront la peine de leur crime; la peine de celui qui consulte sera la même que la peine du prophète,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'afin que la maison d\'Israël ne s\'éloigne plus de moi, et ne se souille plus désormais par tous ses crimes, mais qu\'ils soient mon peuple et que je sois leur Dieu, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Fils de l\'homme, si un pays péchait contre moi et se rendait coupable, et que, portant la main sur lui, je lui ôtasse le pain qui sustente, lui envoyant encore la famine, et en exterminant les hommes et les bêtes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'et qu\'il y eût dans son sein ces trois hommes, Noé, Daniel et Job; ces hommes par leur justice sauveraient leurs âmes, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Si je faisais parcourir le pays par des animaux féroces qui le dépeupleraient et en feraient un désert où personne ne passerait plus à cause de ces animaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'par ma vie, dit le Seigneur, l\'Éternel, ces trois hommes qui s\'y trouveraient, ne sauveraient ni fils, ni filles; eux seuls seraient sauvés; mais le pays serait dévasté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Ou bien si je faisais envahir ce pays-là par l\'épée, et que je disse: Que l\'épée parcoure le pays et y frappe les hommes et les bêtes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'par ma vie, dit le Seigneur, l\'Éternel, ces trois hommes qui s\'y trouveraient, ne sauveraient ni fils, ni filles, mais eux seuls seraient sauvés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Ou bien si j\'envoyais la peste dans ce pays-là, et que je versasse sur lui ma colère en faisant couler le sang, pour y exterminer les hommes et les bêtes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'et que Noé, Daniel et Job fussent dans son sein, par ma vie, dit le Seigneur, l\'Éternel, ils ne sauveraient ni fils, ni fille, mais eux par leur justice ils sauveraient leurs âmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Cependant, ainsi parle le Seigneur, l\'Éternel: Quand même j\'envoie contre Jérusalem mes quatre châtiments désastreux, l\'épée, et la famine, et les animaux féroces, et la peste, pour en exterminer les hommes et les bêtes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'cependant il restera des gens qui échapperont, et seront tirés de là, des fils et des filles. Voici, ils se rendront auprès de vous, et à la vue de leur conduite et de leurs forfaits, vous vous consolerez des maux que j\'aurai fait tomber sur Jérusalem, de tout ce que je vais faire tomber sur elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'Et ils vous consoleront, quand vous connaîtrez leur conduite et leurs forfaits, et vous comprendrez que ce n\'est pas à tort que je lui aurai fait tout ce que je vais lui faire, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Fils de l\'homme, qu\'aurait de plus que tout autre bois la vigne, le sarment, quand il est parmi les bois coupés dans la forêt?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'En tirera-t-on du bois pour en faire un ouvrage? En tirera-t-on un piquet pour y suspendre toutes sortes de meubles?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Voici, on le met au feu pour l\'alimenter. Quand le feu en a dévoré les deux bouts et consumé le milieu, est-il alors bon à être travaillé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Voici, quand il était entier, on ne pouvait en faire aucun ouvrage; combien moins, quand le feu l\'a dévoré et consumé, pourra-t-on en faire un ouvrage!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Aussi, ainsi parle le Seigneur, l\'Éternel: Tel le bois de la vigne que je mets au feu avec le bois de la forêt, pour l\'alimenter, ainsi je livrerai les habitants de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Et je tournerai ma face contre eux; s\'ils se tirent d\'un feu, un autre feu les dévorera, afin que vous reconnaissiez que je suis l\'Éternel, quand je tournerai ma face contre eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Et je ferai du pays un désert, parce qu\'ils se sont rendus coupables, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Et la parole de-l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Fils de l\'homme, montre à Jérusalem ses abominations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'et dis: Ainsi parle le Seigneur, l\'Éternel, à Jérusalem: Par ton origine et ta naissance tu es du pays de Canaan; ton père fut un Amoréen, et ta mère une Héthienne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Et à ta naissance, au jour où tu naquis, ton nombril ne fut point coupé, et tu ne fus point baignée dans l\'eau pour être nettoyée, et on ne répandit point de sel sur toi, et tu ne fus point enveloppée dans des langes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Personne ne t\'accorda un regard de pitié pour te faire, par compassion pour toi, une seule de ces choses; mais tu fus jetée dans les champs, dégoûtée de toi-même, le jour de ta naissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Alors, passant près de toi, je te vis dans ton sang près d\'être foulée, et je te dis, toi étant dans ton sang: Vis! Je te dis, toi étant dans ton sang: Vis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Je te multipliai comme les plantes des campagnes; et tu pris de l\'accroissement et tu grandis, et tu fus parée de tous les charmes; tes mamelles s\'affermirent, et ta chevelure se développa; mais tu étais nue et découverte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Et passant près de toi, je te vis, et voici, ton temps était venu, le temps des amours. Et j\'étendis sur toi le pan de ma robe et couvris ta nu-ditéj et tu reçus mes serments, et je m\'engageai dans une alliance avec toi, dit le Seigneur, l\'Éternel, et tu fus à moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Puis je te baignai dans l\'eau, je lavai le sang qui était sur toi, et je t\'oignis avec de l\'huile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Et je te revêtis d\'étoffes brochées, et te mis une chaussure de peau de veau marin, et je t\'enveloppai de lin et te couvris de soie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Et je te donnai une parure, mettant des bracelets à tes mains, et des chaînettes à ton cou,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'et je mis un anneau à tes narines, et des boucles à tes oreilles, et un superbe diadème sur ta tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Tu fus ainsi parée d\'or et d\'argent, et le lin, et la soie, et les étoffes brochées étaient ton vêtement; la fleur de farine, et le miel et l\'huile ta nourriture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Et tu parvins à la plus grande beauté, et tu t\'élevas jusqu\'à la royauté. Et ton nom se répandit parmi les peuples à cause de ta beauté; car elle devint accomplie par la magnificence dont je te couvris, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Mais, te confiant en ta beauté, tu fus impudique, malgré le nom que tu portais, et tu prodiguas ton amour adultère à tous les passants: il était pour eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Et prenant de tes habits tu te fis sur des hauteurs des pavillons de toutes couleurs, et tu t\'y prostituas; c\'est ce qu\'on n\'avait pas encore vu et qu\'on ne verra plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Et prenant tes superbes atours, faits de mon or et de mon argent, que je t\'avais donnés, tu t\'en fis des images d\'hommes, et tu fus impudique avec elles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Et prenant tes vêtements brochés, tu les en recouvris et tu leur offris mon huile et mon encens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Et ma nourriture que je t\'avais donnée, la fleur de farine, et l\'huile, et le miel dont je te nourrissais, tu les leur offris en parfum odorant; et il en est ainsi, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Et prenant tes fils et tes filles que tu avais enfantés pour moi, tu les leur sacrifias pour les faire dévorer par eux. Était-ce trop peu de ton impudicité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'que tu aies aussi immolé mes fils, et que tu les aies donnés, en les leur consacrant?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Et au milieu de toutes tes abominations et de tes impudicités, tu as perdu le souvenir du temps de ta jeunesse, quand tu étais nue et découverte, et gisante dans ton sang près d\'être foulée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Puis après tous tes méfaits (malheur! malheur à toi! dit le Seigneur, l\'Éternel),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'tu t\'es bâti des voûtes, et élevé des tertres dans toutes les places,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'dans tous les carrefours tu as élevé tes tertres et profané ta beauté, et ouvert tes pieds à chaque passant, et commis nombre d\'impudicités.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Tu fus impudique avec les enfants de l\'Egypte, tes voisins aux membres puissants, et commis nombre d\'impudicités pour m\'irriter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Et voici, levant ma main sur toi, je retranchai de ce que je t\'avais assigné, et te livrai à la discrétion de tes ennemies, les filles des Philistins, qui rougissaient de ta conduite criminelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Et tu fus impudique avec les enfants de l\'Assyrie, parce que tu ne pouvais être rassasiée; et tu fus impudique avec eux, et tu ne fus pas encore rassasiée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Et tu commis de grandes impudicités avec le pays de Canaan jusqu\'en Chaldée, et même par là tu ne fus pas rassasiée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Que ton cœur est malade! dit le Seigneur, l\'Éternel, puisque tu as fait toutes ces choses, actes d\'une impudente prostituée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'que tu as bâti tes voûtes dans tous les carrefours, et élevé tes tertres dans toutes les places! Et tu ne fus point la prostituée qui fait la dégoûtée pour le prix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'la femme adultère qui au lieu de son mari reçoit des étrangers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'A toutes les prostituées on fait des présents, mais toi, tu as donné tes présents à tous tes amants, et tu les as payés, pour qu\'ils vinssent à toi de toutes parts commettre l\'impudicité avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Et tu fus le contraire des autres femmes dans ton impudicité, en ce que tu n\'étais pas recherchée, et en ce que tu faisais des présents, et qu\'on ne t\'en faisait point. C\'est ainsi que tu as été le contraire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'C\'est pourquoi, écoute, impudique, la parole de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Ainsi parle le Seigneur, l\'Éternel: Pour avoir prodigué tes trésors et dans ton impudicité découvert ta nudité à tes amants et à toutes tes abominables idoles, et à cause du sang de tes enfants que tu leur as donnés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'pour cela, voici, je rassemblerai tous tes amants auxquels tu as su plaire, et tous ceux que tu as aimés, avec tous ceux que tu haïssais, je les rassemblerai contre toi de toutes parts, et leur découvrirai ta nudité, afin qu\'ils voient toute ta nudité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Et je te jugerai selon la loi des adultères et des meurtriers, et te livrerai à la sanguinaire vengeance de la fureur et de la jalousie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Et je t\'abandonnerai à leurs mains, et ils démoliront tes voûtes, et abattront tes tertres, et te dépouilleront de tes habits, et t\'ôteront tes superbes atours, et te laisseront là nue et découverte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Et ils amèneront une foule contre toi, et te lapideront et te mettront en pièces avec leurs épées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'Et ils brûleront tes maisons au feu, et te feront ce que tu mérites, sous les yeux de beaucoup de femmes. Et je mettrai fin à ton impudicité, et le prix aussi tu ne le paieras plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Et j\'assouvirai ma fureur sur toi, et et tu ne seras plus l\'objet de ma jalousie, et je serai calme et nullement irritable désormais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Parce que tu ne t\'es pas rappelé le temps de ta jeunesse, et que tu t\'es élevée contre moi par toutes ces choses, voici, moi aussi, je ferai retomber sur ta tête tout ce que tu as fait, dit le Seigneur, l\'Éternel; car tu n\'as pas réfléchi à toutes tes abominations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Voici, tous ceux qui emploient des proverbes, t\'appliqueront le proverbe: Telle mère, telle fille!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Tu es la fille de ta mère, qui répudia son mari et ses enfants, et tu es la sœur de tes sœurs, qui répudièrent leurs maris et leurs enfants. Votre mère est une Héthienne, et votre père un Amoréen.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Et la sœur aînée est Samarie, avec ses filles, qui habite à ta gauche, et ta sœur cadette, qui demeure à ta droite, est Sodome avec ses filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Mais non seulement tu as suivi leurs errements, agi d\'après leurs abominations; bientôt ce fut trop peu pour toi; tu fus pire qu\'elles, dans toute ta conduite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Par ma vie, dit le Seigneur, l\'Éternel, Sodome ta sœur, avec ses filles, n\'en a pas fait autant que toi avec tes filles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Voici quel a été le crime de Sodome, ta sœur: orgueil, abondance, sécurité tranquille, telle était sa vie et celle de ses filles; elles n\'ont point soutenu par la main le misérable et l\'indigent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'et elles étaient hautaines et commettaient des abominations devant moi, aussi les ai-je détruites, quand je l\'ai vu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Et Samarie n\'a pas commis la moitié de tes péchés, et tu as commis un plus grand nombre d\'abominations qu\'elles, et justifié tes sœurs par toutes les abominations que tu as commises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Subis donc aussi toi-même l\'opprobre que tu adjuges à tes sœurs! Par tes péchés qui ont été plus abominables que les leurs, elles se trouvent plus justes que toi. Soit donc aussi confondue, et subis ton opprobre, puisque tu as justifié tes sœurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Et je ramènerai leurs captifs, les captifs de Sodome et de ses filles, et les captifs parmi les leurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'afin qu\'ainsi tu subisses ton opprobre, et que tu aies honte de tout ce que tu as fait, tant pour eux une consolation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Et ta sœur Sodome et ses filles, reviendront à leur premier état, et Samarie et ses filles reviendront à leur premier état, et toi et tes filles vous reviendrez à votre premier état.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Et cependant on n\'entendait point sortir de ta bouche le nom de Sodome ta sœur, dans le temps de ta hauteur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'avant que ta méchanceté fût manifestée, comme cela eut lieu, quand tu fus outragée par les filles de la Syrie et tous ceux qui les entourent, par les filles des Philistins qui tout autour de toi te méprisaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Tes crimes et tes abominations, tu les subis maintenant, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Car ainsi parle le Seigneur, l\'Éternel: J\'agirai envers toi comme tu en as agi, toi qui as méprisé le serment en rompant l\'alliance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Cependant je me rappellerai l\'alliance que j\'ai faite avec toi au temps de ta jeunesse, et je veux établir avec toi une alliance éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Et tu te rappelleras ta conduite, et tu en auras honte, quand tu recevras tes sœurs, les aînées et les cadettes, et que je te les donnerai pour filles, mais non en vertu de ton alliance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Et j\'établirai mon alliance avec toi, et tu reconnaîtras que je suis l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'afin que tu te rappelles, et que tu aies honte et que tu n\'ouvres pas la bouche de confusion, quand je te pardonnerai tout ce que tu as fait, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Fils de l\'homme, propose une énigme et une parabole à la maison d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'et dis: Ainsi parle le Seigneur, l\'Éternel: Un grand aigle, ayant de grandes ailes et de longues pennes, couvert de plumes de toutes couleurs, vint sur le Liban et prit la cime des cèdres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Il cueillit la tête des tendres rameaux, et l\'apportant dans un pays marchand, il la déposa dans une ville de commerce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Et il prit un des rejetons du pays, et le déposa dans un sol fertile, le mit près d\'une eau abondante, et dans un lit de terre il le planta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Et il poussa, et devint une vigne développée, dont la tige était basse, et les rameaux tournés vers l\'aigle, et dont les racines demeuraient sous lui: il devint une vigne qui jeta des rameaux et produisit des pampres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Et il y avait un autre grand aigle, qui avait de grandes ailes et un épais plumage. Et voici, cette vigne portait avidement ses racines de son côté, et du lit de terre où elle était plantée, elle étendait ses sarments vers lui, afin d\'être arrosée par lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, '[Cependant] elle avait été plantée dans un bon sol, près d\'abondantes eaux, pour pousser des rameaux et porter du fruit, pour devenir une vigne superbe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Dis: Ainsi parle le Seigneur, l\'Éternel: Prospérera-t-elle? [L\'autre aigle] n\'arrachera-t-il pas ses racines, et n\'enlèvera-t-il pas ses fruits, afin qu\'elle sèche, et que le feuillage qu\'elle a poussé, sèche? Et ce ne sera ni avec toute la force de son bras, ni avec un peuple nombreux, qu\'il l\'enlèvera de sa racine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Voici, elle est plantée, mais prospérera-t-elle! Si le vent d\'Orient l\'atteint, ne séchera-t-elle pas? Sur le lit de terre où elle pousse, elle séchera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Et la parole de l\'Éternel me fut adressée en ces mots: Dis à la race rebelle: Ignorez-vous ce que cela signifie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Dis: Voici, le roi de Babel est venu à Jérusalem, et s\'est saisi de son roi et de ses princes, et les a amenés auprès de lui à Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Et il a pris un rejeton de la race royale, et traité alliance avec lui, et lui a fait prêter un serment, et a emmené les principaux du pays,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'voulant que le royaume fût humilié, afin qu\'il ne s\'enorgueillît pas, qu\'il gardât son alliance, et qu\'elle fût maintenue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Mais il lui fut rebelle en envoyant ses députés en Egypte pour en obtenir des chevaux et dès hommes en grand nombre. Pourra-t-il réussir, échapper, celui qui fait de telles choses? Il a rompu l\'alliance, et il échapperait!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Par ma vie, dit le Seigneur, l\'Éternel, c\'est dans la résidence même du roi qui l\'a fait roi, dont il a méprisé le serment et rompu l\'alliance, c\'est auprès de lui, à Babel, qu\'il mourra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Et avec une grande armée et un peuple nombreux, Pharaon ne fera rien pour lui durant la guerre, quand on élève des terrasses et bâtit des tours pour ôter bien des vies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Il a méprisé le serment et rompu l\'alliance, et quoiqu\'il eût promis de sa propre main, il a cependant fait tout cela; il n\'échappera pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'C\'est pourquoi, ainsi parle le Seigneur, l\'Éternel: Par ma vie, oui, c\'est mon serment qu\'il a méprisé, et mon alliance qu\'il a rompue, et je ferai retomber cela sur sa tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Et j\'étendrai mon réseau sur lui, afin qu\'il se prenne dans mon filet, et je l\'amènerai à Babel, et là j\'entrerai en débat avec lui sur le crime dont il s\'est rendu coupable envers moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Et toute l\'élite de tous ses bataillons tombera sous l\'épée, et les survivants seront dispersés à tous les vents, et ainsi vous saurez que c\'est moi, l\'Éternel, qui ai parlé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Ainsi parle le Seigneur, l\'Éternel: Moi aussi je prendrai une cime des cèdres élevés, et je la placerai; au sommet de leurs rameaux je cueillerai un tendre rameau et le planterai moi-même sur une montagne haute et éminente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'C\'est sur une haute montagne d\'Israël que je le planterai, et il poussera des branches et portera du fruit, et deviendra un superbe cèdre, et toutes les espèces d\'oiseaux et de volatiles viendront y faire leur demeure, ils feront leur demeure à l\'ombre de ses rameaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Et tous les arbres des campagnes connaîtront que c\'est moi, l\'Éternel, qui aurai humilié l\'arbre élevé et élevé l\'arbre humble, que j\'aurai fait sécher l\'arbre vert et verdir l\'arbre sec. Moi, l\'Éternel, je l\'ai dit et je le ferai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Que faites-vous de répéter ce proverbe dans le pays d\'Israël, en disant: Les pères mangent le verjus, et ce sont les fils qui en ont les dents attaquées?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Par ma vie, dit le Seigneur, l\'Éternel, vous n\'aurez plus lieu de dire ce proverbe en Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Voici, toutes les âmes sont à moi; et l\'âme du père et l\'âme du fils, toutes deux sont à moi; c\'est l\'âme qui pèche qui mourra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Si un homme est juste et pratique les lois et la justice,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'si sur les montagnes il n\'assiste point aux banquets, et ne lève point les yeux vers les idoles de la maison d\'Israël, et ne déshonore point la femme de son prochain, et ne s\'approche point d\'une femme pendant sa souillure;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 's\'il n\'opprime personne, rend au débiteur son gage, n\'exerce point de rapines, donne son pain à celui qui a faim, et couvre de vêtements celui qui est nu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 's\'il ne prête point à usure et ne reçoit point d\'intérêt, et s\'abstient de faire tort, et prononce selon la vérité entre un homme et un autre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 's\'il suit mes ordonnances et garde mes lois en agissant avec droiture, un tel homme est juste; il vivra, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Que s\'il engendre un fils effréné qui répande le sang et fasse seulement l\'une de ces choses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'et s\'il ne fait pas toutes celles [que j\'ai commandées], mais si sur les montagnes il assiste aux banquets, et déshonore la femme de son prochain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'opprime le pauvre et le malheureux, exerce des rapines, ne rend pas le gage, et lève les yeux vers les idoles, et commet des abominations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'prête à usure et reçoit un intérêt, vivrait-il? Il ne vivra pas; il a fait toutes ces abominations, il doit être mis à mort; que son sang soit sur lui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Cependant voici, s\'il engendre un fils, qui voie tous les péchés que commet son père, les voie et ne les imite pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'sur les montagnes n\'assiste point aux banquets, et ne lève pas les yeux vers les idoles de la maison d\'Israël, ne déshonore point la femme de son prochain;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'et n\'opprime personne, ne reçoive point de gage, et n\'exerce point de rapines, donne son pain à celui qui a faim, et couvre de vêtements celui qui est nu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'ne porte point la main sur le pauvre, n\'accepte ni usure, ni intérêt, mette mes lois en pratique et suive mes ordonnances; un tel homme ne mourra point pour le crime de son père; il vivra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Son père qui a été oppresseur, et a exercé quelque rapine et fait ce qui n\'est pas bien au milieu de son peuple, voici, c\'est lui qui mourra pour son crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Vous demandez: Pourquoi le fils ne pâtit-il pas de l\'iniquité de son père? C\'est que le fils a agi selon les lois et la justice, observé et mis en pratique toutes mes ordonnances: il vivra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'C\'est l\'âme qui pèche qui mourra. Un fils ne pâtira point de l\'iniquité du père, et un père ne pâtira point de l\'iniquité du fils; le juste éprouvera les effets de sa justice, et l\'impie éprouvera les effets de son impiété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Que si l\'impie revient de tous les péchés qu\'il a commis, et observe toutes mes ordonnances, et fait ce qui est droit et juste, il vivra, ne mourra point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'De toutes les transgressions qu\'il aura commises, il ne lui sera pas tenu compte, mais grâce à la justice qu\'il aura pratiquée, il vivra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Est-ce en effet que je prends plaisir à la mort du pécheur? dit le Seigneur, l\'Éternel; n\'est-ce pas plutôt à ce qu\'il revienne de sa [mauvaise] voie et qu\'il vive?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Que si le juste abandonne sa justice et fait le mal, et commet toutes les abominations que commet l\'impie, vivrait-il? [Non!] de toute la justice qu\'il aura pratiquée, il ne lui sera pas tenu compte, à cause du crime dont il s\'est rendu coupable, et du péché qu\'il a commis; c\'est pour cela qu\'il mourra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Mais vous dites: La voie du Seigneur n\'est pas droite. Écoutez donc, maison d\'Israël! Ma voie n\'est-elle pas droite? N\'est-ce pas plutôt votre voie qui n\'est pas droite?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Si le juste abandonne sa justice et fait le mal, et meurt pour cela, c\'est pour le mal qu\'il a fait qu\'il meurt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Mais si l\'impie abandonne son impiété à laquelle il s\'adonnait et fait ce qui est droit et juste, il conservera la vie à son âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Parce qu\'il a ouvert les yeux, et abandonné tous les péchés qu\'il commettait, il vivra et ne mourra point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Mais la maison d\'Israël dit: La voie du Seigneur n\'est pas droite. Ma voie n\'est-elle pas droite, maison d\'Israël? N\'est-ce pas plutôt votre voie qui n\'est pas droite?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'C\'est pourquoi je vous jugerai chacun d\'après sa voie. Maison d\'Israël, dit le Seigneur, l\'Éternel, convertissez-vous et abandonnez tous vos péchés, afin que pour vous le crime n\'amène pas la ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Défaites-vous de tous les péchés dont vous vous êtes rendus coupables, et prenez un cœur nouveau et un nouvel esprit. Pourquoi voudriez-vous la mort, maison d\'Israël?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Car je ne prends point plaisir à la mort de celui qui meurt, dit le Seigneur, l\'Éternel. Convertissez-vous donc, afin que vous viviez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Mais toi, élève une complainte sur les princes d\'Israël');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'et dis: Quelle lionne était ta mère! au milieu des lions elle était couchée, parmi les lionceaux elle éleva ses petits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Et elle éleva l\'un de ses petits, il devint un jeune lion et apprit à saisir une proie, il dévora des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Et les peuples entendirent parler de lui, il se trouva pris dans leur fosse, et lui ayant passé une boucle dans les naseaux, ils le menèrent au pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Et quand elle vit qu\'elle attendait [vainement], qu\'elle n\'avait plus d\'espoir, alors elle prit un autre de ses petits, et en fit un jeune lion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Et il vécut au milieu des lions, devint un jeune lion et apprit à saisir une proie; il dévora des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Il jouit de leurs veuves, et dévasta leurs villes, et le pays avec ce qu\'il contient fut désolé à sa voix rugissante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Aussi les peuples des contrées d\'alentour contre lui dressèrent et tendirent leurs filets, et il se trouva pris dans leur fosse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Et lui ayant passé une boucle dans les naseaux, ils le mirent dans une cage et le menèrent au roi de Babel. Puis on le mit dans un fort, afin que sa voix ne se fit plus entendre aux montagnes d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Ta mère était pareille à une vigne, comme toi plantée près des eaux; l\'abondance des eaux la rendait féconde et touffue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Elle avait des sarments assez forts pour être des sceptres de souverains, et sa tige s\'élevait au milieu de pampres épais, et elle se faisait remarquer par sa hauteur et le nombre de ses rameaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Mais elle fut arrachée avec fureur, jetée sur la terre, et le vent d\'orient dessécha ses fruits, ses robustes sarments furent déchirés et desséchés, le feu les dévora.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Et maintenant elle est transplantée au désert, dans un sol sec et aride.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Et le feu sortant de l\'un des rameaux de ses branches, dévora ses fruits, et il ne s\'y trouva plus de sarment assez fort pour être un sceptre de souverain. C\'est là une complainte qui est devenue complainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Et il arriva, la septième année, le cinquième mois, le dixième jour du mois, que des hommes d\'entre les Anciens d\'Israël vinrent consulter l\'Éternel, et s\'assirent devant moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Fils de l\'homme, parle aux Anciens d\'Israël et dis-leur: Ainsi parle le Seigneur, l\'Éternel: Est-ce pour me consulter que vous êtes venus? par ma vie, si je me laisse consulter par vous! dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Les puniras-tu? les puniras-tu, fils de l\'homme? fais-leur connaître les abominations de leurs pères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'et dis-leur: Ainsi parle le Seigneur, l\'Éternel: Le jour où je fis choix d\'Israël, de ma main levée je fis un serment à la race de la maison de Jacob, et je me manifestai à eux dans le pays d\'Egypte, et levant ma main je leur dis: Je suis l\'Éternel votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'Dans ce même jour, de ma main levée je leur fis serment de les conduire du pays d\'Egypte dans un pays dont j\'avais fait moi-même la reconnaissance, d\'où coulent le lait et le miel; c\'est la gloire de toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Et je leur dis: Jetez chacun loin de vous les infâmes objets de vos regards, et des idoles de l\'Egypte ne vous souillez pas! Je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Mais ils me furent rebelles, et ne voulurent point m\'écouter; aucun d\'eux ne jeta les infâmes objets de leurs regards, et ils ne quittèrent point les idoles de l\'Egypte. Alors j\'eus la pensée de verser ma colère sur eux, d\'achever mes vengeances sur eux au pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Mais j\'agis en vue de mon nom, afin de ne le pas déshonorer aux yeux des peuples au milieu desquels ils étaient, et sous les yeux desquels je m\'étais manifesté à eux, pour les tirer du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Et je les tirai du pays d\'Egypte, et les menai au désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Et je leur donnai mes ordonnances, et leur fis connaître mes lois, que l\'homme doit accomplir, afin de vivre par elles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Je leur donnai aussi mes sabbats pour qu\'ils fussent un signe entre moi et eux, qu\'ils reconnaissaient que c\'est moi, l\'Éternel, qui les sanctifie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Mais la maison d\'Israël me fut rebelle dans le désert; ils ne suivirent point mes ordonnances, et ils méprisèrent mes lois que l\'homme doit accomplir afin de vivre par elles, et ils profanèrent beaucoup mes sabbats. Alors j\'eus la pensée de verser ma colère sur eux dans le désert, de les détruire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Mais j\'agis en vue de mon nom, pour ne le pas déshonorer aux yeux des peuples sous les yeux desquels je les avais délivrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Dans le désert aussi, de ma main levée je leur fis serment de ne pas les amener dans le pays que je leur avais donné, d\'où coulent le lait et le miel; il est la gloire de toute la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'parce qu\'ils avaient méprisé mes lois, et n\'avaient point suivi mes ordonnances, et avaient profané mes sabbats; car c\'est vers leurs idoles que leur cœur se tournait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Mais par pitié pour eux je ne les détruisis point, et ne fis point d\'eux extermination dans le désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Et je dis à leurs fils dans le désert: Ne suivez pas les préceptes: de vos pères, et ne gardez pas leurs lois, et de leurs idoles ne vous souillez pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Je suis l\'Éternel, votre Dieu. Suivez mes préceptes et gardez mes lois, et exécutez-les,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'et sanctifiez mes sabbats, afin qu\'ils soient un signe entre moi et vous, que vous reconnaissez que je suis l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Mais les fils me furent rebelles; ils ne suivirent pas mes préceptes et ne gardèrent pas, pour les exécuter, mes lois que l\'homme doit exécuter pour vivre par elles; ils profanèrent mes sabbats. J\'eus alors la pensée de verser ma colère sur eux, et d\'achever mes vengeances sur eux dans le désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Mais j\'arrêtai ma main, et j\'agis en vue de mon nom, afin de ne le pas déshonorer aux yeux des peuples, sous les yeux desquels je les avais délivrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'De ma main levée je leur fis aussi serment dans le désert de les disperser parmi les peuples et de les disséminer dans les pays divers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'parce qu\'ils n\'exécutaient point mes lois, et méprisaient mes préceptes, et profanaient mes sabbats, et que leurs yeux se tournaient vers les idoles de leurs pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Je leur imposai aussi des ordonnances qui n\'étaient pas bonnes, et des lois qui ne les faisaient pas vivre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'et je les souillai par leurs offrandes, quand ils consacraient leur primogéniture, afin de les détruire, pour qu\'ils reconnussent que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Aussi, parle à la maison d\'Israël, fils de l\'homme, et dis-leur: Ainsi parle le Seigneur, l\'Éternel: C\'est encore en ceci que vos pères m\'ont outragé par leur désobéissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Quand je les amenai au pays que de ma main levée j\'avais juré de leur donner, ils jetèrent les yeux sur toutes les collines élevées et sur tous les arbres touffus, et y firent leurs sacrifices, et y déposèrent leurs insultantes offrandes, et y apportèrent leurs doux parfums, et y répandirent leurs libations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Et je leur dis: Qu\'est-ce, que ces hauts lieux où vous vous rendez? Et ce nom de haut lieu leur est donné jusqu\'aujourd\'hui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Aussi dis à la maison d\'Israël: Ainsi parle le Seigneur, l\'Éternel: Quoi! vous vous souillez encore en suivant la voie de vos pères, et leurs objets infâmes excitent encore votre impudicité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'et en présentant vos offrandes, en consacrant, vos enfants par le feu, vous vous souillez par toutes vos idoles jusqu\'à ce jour: et je me laisserais consulter par vous, maison d\'Israël! non, par ma vie, dit le Seigneur, l\'Éternel, si je me laisse consulter par vous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Et ce que vous vous mettez dans l\'esprit, n\'aura pas lieu, quoique vous disiez: Nous voulons être comme les nations, comme les familles des autres pays, et servir le bois et la pierre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Non, par ma vie, dit le Seigneur, l\'Éternel! mais c\'est d\'une main forte, et, le bras levé, et en versant ma colère, que je veux régner sur vous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'Et je vous tirerai d\'entre les peuples et vous rassemblerai des pays où vous serez dispersés, d\'une main forte, et d\'un bras étendu et avec effusion de colère,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'et je vous amènerai dans le désert des peuples, et là je vous jugerai face à face.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'De même que j\'ai prononcé mon jugement sur vos pères dans le désert du pays d\'Egypte, ainsi prononcerai-je mon jugement sur vous, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'Et je vous ferai passer sous la verge et vous engagerai dans les liens de l\'alliance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'et j\'exterminerai du milieu de vous les rebelles et ceux qui se détachent de moi; je les tirerai du pays où ils séjournent, mais ils ne viendront point au pays d\'Israël, afin que vous sachiez que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Vous donc, maison d\'Israël! ainsi parle le Seigneur, l\'Éternel: Allez, servez chacun vos idoles, mais à l\'avenir, ne voulez-vous pas m\'écouter? ne profanez plus mon saint nom par vos offrandes, et votre idolâtrie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'En effet, sur ma montagne sainte, sur la haute montagne d\'Israël, dit le Seigneur, l\'Éternel, là je serai servi par toute la maison d\'Israël, par tout ce qu\'il y en aura dans le pays, là je les recevrai favorablement, et là je réclamerai vos oblations et les prémices de vos dons dans tout ce que vous me consacrerez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Ainsi qu\'un doux parfum je vous recevrai, quand je vous aurai tirés du milieu des peuples, et rassemblés des pays où vous serez dispersés, et par vous je serai sanctifié devant les peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Et vous saurez que je suis l\'Éternel, quand je vous ramènerai au pays d\'Israël, au pays que de ma main levée j\'avais juré de donner à vos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Et là vous vous rappellerez votre conduite et tous les crimes dont vous vous êtes souillés, et en vous-mêmes vous aurez du dégoût pour toutes les actions mauvaises que vous avez faites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Et vous reconnaîtrez que je suis l\'Éternel, quand j\'agirai avec vous pour l\'amour de mon nom, et non selon vos œuvres mauvaises et votre conduite corrompue, maison d\'Israël, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, 'Fils de l\'homme, tourne ton visage du côté du sud, et parle contre le midi, et prophétise contre la forêt des campagnes du midi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'et dis à la forêt du midi: Écoutde la parole de l\'Éternel! Ainsi parle le Seigneur, l\'Éternel: Voici, je vais allumer en toi un feu qui dévorera tous les arbres verts, et tous les arbres secs, et la flamme allumée ne s\'éteindra point, et toute la surface du pays en sera brûlée du midi au nord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'Et toute chair verra que c\'est moi, l\'Éternel, qui l\'aurai allumée; elle ne s\'éteindra point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'Mais je dis: Hélas! Seigneur Éternel, ils disent de moi: Ne parle-t-il pas en paraboles?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Alors la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Fils de l\'homme, tourne ton visage contre Jérusalem, et parle contre les lieux saints, et prophétise contre le pays d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'et dis au pays d\'Israël: Ainsi parle l\'Éternel: Voici, c\'est à toi que j\'en veux, et je tirerai mon épée du fourreau et du milieu de toi j\'exterminerai justes et impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Parce que du milieu de toi je veux exterminer justes et impies, c\'est pourquoi mon épée sortira de son fourreau pour frapper toute chair, du midi au nord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Et toute chair reconnaîtra que c\'est moi, l\'Éternel, qui aurai tiré mon épée de son fourreau; elle n\'y rentrera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Pour toi, fils de l\'homme, soupire jusqu\'à te rompre les reins, et pousse devant eux des gémissements avec une douleur amère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'Que s\'ils te disent: Pourquoi soupires-tu? réponds: Parce que la nouvelle est venue que [les maux] arrivent, et tous les cœurs seront alarmés, et toutes les mains défaillantes, et tout courage éteint, et tous les genoux fondus en eau: voici, ils arrivent, ils sont là, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Fils de l\'homme, prophétise et dis: Ainsi parle l\'Éternel. Dis: L\'épée! l\'épée! elle est aiguisée et fourbie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'C\'est pour massacrer qu\'elle est aiguisée, pour lancer l\'éclair qu\'elle est fourbie; ou le sceptre de mon fils qui méprise tout autre bois ferait-il le superbe?...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Et Il l\'a donnée à fourbir, pour la prendre en sa main; elle est aiguisée, l\'épée, et fourbie, pour être mise dans la main de l\'exterminateur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Crie, et gémis, fils de l\'homme! car elle frappe mon peuple, tous les princes d\'Israël; ils sont abandonnés à l\'épée avec mon peuple; aussi frappe-toi les flancs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'L\'épreuve est faite; eh quoi! lors même que ce sceptre est si dédaigneux, il cessera d\'être, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Mais toi, fils de l\'homme, prophétise et frappe dans tes deux mains! et que l\'épée frappe à doubles, à triples coups; cette épée qui tue, c\'est une épée qui tue les Grands, qui les presse de toutes parts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Pour porter l\'alarme dans les cœurs et multiplier les morts, j\'ai mis l\'épée menaçante à toutes leurs portes. Hélas! elle est faite pour lancer l\'éclair, elle est aiguisée pour égorger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Ramasse-toi! frappe à droite! attention! frappe à gauche, partout où tu feras face!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Moi aussi, je frapperai dans mes deux mains, et j\'assouvirai ma fureur; c\'est moi, l\'Éternel, qui ai parlé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'Or, fils de l\'homme, représente-toi deux chemins par où arrive l\'épée du roi de Babel; il faut qu\'ils partent tous deux d\'un seul et même pays; et imagine un lieu; imagine-le au carrefour des chemins des villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Trace l\'un des chemins, de telle sorte que l\'épée arrive à Rabbah des enfants d\'Ammon, et l\'autre en Juda, à Jérusalem, la ville forte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Car le roi de Babel s\'arrête à la croix des chemins, au carrefour de deux routes, pour tirer un présage; il remue les flèches, interroge les Téraphims, examine le foie de la victime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'De sa droite il a tiré le présage: c\'est Jérusalem! pour dresser les béliers, commander le massacre, élever la voix jusqu\'au cri de guerre, dresser les béliers contre les portes, tasser une terrasse, bâtir des tours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Mais ils n\'y voient qu\'un présage trompeur; ils font serments sur serments, mais il se rappelle leur crime; en sorte qu\'ils seront pris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Aussi, ainsi parle le Seigneur, l\'Éternel: Puisque vous faites ressouvenir de votre crime, vos méfaits étant tellement manifestes qu\'ils paraissent dans toutes vos actions, parce que vous faites ressouvenir de vous, vous serez saisis par sa main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Et toi, profane sacrilège, Prince d\'Israël dont le jour arrive au moment de ton crime, cause de ta fin!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'ainsi parle le Seigneur, l\'Éternel: Ôte ton diadème, et enlève ta couronne; elle n\'est plus elle-même; ce qui est humble sera élevé, et ce qui est élevé sera humilié:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'en pièces, en pièces, en pièces je la mettrai; elle aussi cessera d\'être jusqu\'à la venue de celui à qui appartient le jugement et à qui je le remets.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Et toi, fils de l\'homme, prophétise et dis: Ainsi prononce le Seigneur, l\'Éternel, sur les enfants d\'Ammon et sur leurs outrages, et dis: L\'épée, l\'épée est tirée, fourbie, pour massacrer, afin de dévorer et de lancer l\'éclair,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'pendant qu\'on te fait de vaines prédictions, qu\'on te donne des présages menteurs, afin de te joindre aux corps décollés des impies déjà morts dont le jour arrive au moment du crime, cause de leur fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Remets ton épée dans le fourreau! Dans le lieu même où tu fus formé, dans le pays de ta naissance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'je veux te juger et répandre ma colère sur toi, souffler contre toi le feu de mon courroux, et te livrer au bras d\'hommes furieux, destructeurs experts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Du feu tu seras la proie, ton sang coulera au sein du pays, ta mémoire périra, car c\'est moi, l\'Éternel, qui ai parlé.>');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'Et toi, fils de l\'homme, jugeras-tu, jugeras-tu la ville sanguinaire? et fais-lui connaître toutes ses abominations');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'et dis: Ainsi parle le Seigneur, l\'Éternel: Ville, qui verses le sang dans ton sein, pour que ton moment arrive, et qui fais, des idoles pour te souiller!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Par le sang que tu as versé, tu t\'es rendue coupable, et par les idoles que tu as faites, tu t\'es souillée, et as fait avancer le terme de tes jours, et tu es parvenue au terme de tes années. C\'est pourquoi je te livre aux outrages des nations, et à la dérision de tous les pays;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'lointains et rapprochés ils te tourneront en dérision, comme portant un nom souillé, comme pleine de trouble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Voici, les princes d\'Israël sont au dedans de toi, chacun selon son pouvoir occupés à répandre le sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Pour père et pour mère ils montrent du mépris au dedans de toi; à l\'étranger ils font sentir l\'oppression dans ton sein; envers l\'orphelin et la veuve ils sont violents au milieu de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Tu méprises mes sanctuaires, et profanes mes sabbats.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Il se trouve en toi des calomniateurs pour répandre le sang; et sur les montagnes ils prennent part aux banquets au milieu de toi; ils commettent le crime dans ton sein.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'On découvre au milieu de toi la nudité d\'un père, ils jouissent des femmes pendant leur souillure au milieu de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Chacun commet des infamies avec la femme de son prochain, et chacun souille sa bru par l\'inceste, et chacun jouit de sa sœur, fille de son père, au milieu de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Dans ton sein ils reçoivent des présents, pour répandre le sang; tu reçois une usure et un intérêt, et portes dommage à ton prochain par des exactions, et moi tu m\'oublies, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Voici, je frappe dans mes mains à cause de la cupidité à laquelle tu te livres, et du sang versé qui est dans ton sein.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Ton cœur tiendra-t-il? tes mains resteront-elles fermes dans les jours où j\'agirai contre toi? Moi, l\'Éternel, je le dis et le ferai:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'je te disperserai parmi les peuples et te disséminerai dans les pays divers, et du milieu de toi j\'exterminerai ta souillure,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'et ce sera par toi que tu seras souillée aux yeux des peuples, et tu sauras que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Fils de l\'homme, la maison d\'Israël est devenue pour moi une scorie; tous ils sont de l\'airain, et de l\'étain, et du fer, et du plomb dans le fourneau; ils sont une scorie d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Aussi ainsi parle le Seigneur, l\'Éternel: Parce que vous êtes tous devenus scories, pour cela, voici, je vous ramasserai au milieu de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'De même qu\'on rassemble l\'argent, et l\'airain, et le fer, et le plomb, et l\'étain dans le fourneau, pour y souffler le feu afin d\'en faire la fusion; ainsi je vous rassemblerai dans ma colère et dans mon courroux, et je vous y mettrai pour vous fondre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Oui, je vous ramasserai, et soufflerai contre vous le feu de ma fureur, afin que vous y fondiez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Comme on fond l\'argent au fourneau, ainsi vous serez fondus au milieu d\'elle, afin que vous sachiez que c\'est moi, l\'Éternel, qui verse ma fureur sur vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Fils de l\'homme, dis à la ville: Tu es une terre qui n\'est pas nettoyée, et n\'aura pas ses pluies au jour de la colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Il y a conspiration de ses prophètes au milieu d\'elle; pareils au lion rugissant déchirant une proie, ils dévorent des âmes, prennent ce qui est riche et précieux, et font au milieu d\'elle un grand nombre de veuves.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Ses prêtres violent ma loi et profanent mes sanctuaires; entre ce qui est sacré et ce qui est profane, ils ne font nulle différence, et n\'enseignent pas la différence qui est entre le pur et l\'immonde, et sur mes sabbats ils ferment les yeux, et je suis déshonoré au milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Ses princes sont au milieu d\'elle comme des loups ravissants, ils versent le sang, perdent les âmes, par l\'avidité du gain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Et ses prophètes les recouvrent de plâtre, ont de fausses visions et leur donnent des présages menteurs, disant: « Ainsi parle le Seigneur, l\'Éternel! » tandis que l\'Éternel ne leur a point parlé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Le peuple du pays commet des violences, exerce des rapines, opprime l\'affligé et l\'indigent, et sur l\'étranger commet des violences injustement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'J\'ai cherché parmi eux un homme qui élevât une muraille, et montât à la brèche au-devant de moi en faveur du pays, pour que je ne le détruise pas, mais je ne l\'ai pas trouvé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Aussi vais-je verser ma colère sur eux, les consumer par le feu de mon courroux, et faire retomber leurs œuvres sur leur tête, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Fils de l\'homme, il y avait deux femmes, filles d\'une même mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Et elles furent impudiques en Egypte, dans leur jeunesse elles furent impudiques; là leurs mamelles furent pressées, et là on porta la main à leur sein virginal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Or voici leurs noms: Ohola c\'est l\'aînée, et Oholiba sa sœur. Et elles furent unies à moi, et elles enfantèrent des fils et des filles. Or voici leurs noms: Samarie est Ohola, et Jérusalem Oholiba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Et Ohola me désertant fut impudique, et s\'éprit de ses amants, des Assyriens, ses voisins,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'revêtus de pourpre violette, gouverneurs et satrapes, tous beaux jeunes hommes, cavaliers, montés sur des coursiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Et elle leur prostitua son amour adultère, à toute l\'élite des enfants de l\'Assyrie, et elle se souilla avec tous ceux dont elle s\'éprit, avec toutes leurs idoles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Cependant elle ne renonça point à ses impudicités avec l\'Egypte; car ils avaient habité avec elle dans sa jeunesse, et porté la main à son sein virginal, et s\'étaient livrés à des débordements d\'impudicité avec elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Aussi l\'ai-je livrée aux mains de ses amants, aux mains des enfants de l\'Assyrie dont elle était éprise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Ils découvrirent sa nudité, enlevèrent ses fils et ses filles et la firent périr elle-même par l\'épée; et elle devint la fable des femmes, quand ils eurent exécuté sur elle les jugements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'C\'est ce dont fut témoin Oholiba sa sœur; mais elle fut pire qu\'elle dans ses débordements, et son impudicité fut pire que l\'impudicité de sa sœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Elle s\'éprit des enfants de l\'Assyrie, gouverneurs et. satrapes, ses voisins, vêtus magnifiquement, cavaliers, montés sur des coursiers, tous beaux jeunes hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Et je vis qu\'elle se souillait; elles suivaient l\'une et l\'autre la même voie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Mais elle ajouta encore à son impudicité, et à la vue d\'hommes dessinés sur la muraille, images des Chaldéens, dessinés au vermillon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'portant une ceinture autour de leurs reins, sur leurs têtes des tiares tombantes, tous ayant l\'air des guerriers montés sur les chars, pareils aux enfants de Babel, de la Chaldée, leur pays natal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'elle s\'éprit d\'eux au premier coup d\'œil, et leur envoya des messagers en Chaldée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Et les enfants de Babel vinrent partager avec elle le lit des amours, et la souillèrent par leur impudicité, et elle se souilla avec eux, puis son cœur se détacha d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Et quand elle montra son impudicité, et montra sa nudité, alors mon cœur se détacha d\'elle, comme mon cœur s\'était détaché de sa sœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Cependant elle ajouta encore à son impudicité, en se reportant aux jours de sa jeunesse, quand elle avait été impudique au pays d\'Égypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'et elle s\'éprit de ses concubinaires qui avaient des membres comme des ânes, et étaient lascifs comme des étalons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Tu regrettas ta jeunesse criminelle, quand des Égyptiens pressaient tes mamelles, à cause de ton sein virginal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Aussi, Oholiba, ainsi parle le Seigneur, l\'Éternel: Voici, je vais exciter contre toi tes amants, dont tu t\'es détachée, et je les amènerai contre toi de toutes parts:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'les enfants de Babel et tous les Chaldéens, chefs, riches et Grands, tous les enfants de l\'Assyrie avec eux, beaux jeunes hommes, tous gouverneurs et satrapes, combattant sur des chars, hommes d\'élite, montés sur des coursiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Et ils s\'avancent contre toi avec des armes, des chars et des roues, et des troupes nombreuses; et avec le pavois, le bouclier et le casque ils se portent sur toi de toutes parts; et je leur remets le jugement, afin qu\'ils te jugent selon leurs lois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'et je donne cours à mon indignation contre toi, afin qu\'ils te traitent avec fureur; ils te couperont le nez et les oreilles, et ta postérité périra par l\'épée: ils enlèveront tes fils et tes filles, et ta postérité sera dévorée par le feu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'et ils te dépouilleront de tes habits et prendront tes superbes atours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Et ainsi je mettrai fin à ton crime et à ton impudicité d\'Egypte, pour que tu ne lèves plus les yeux vers eux, et que tu ne portes plus tes pensées vers l\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Car ainsi parle le Seigneur, l\'Éternel: Voici, je vais te livrer aux mains de ceux que tu hais, aux mains de ceux de qui ton cœur s\'est détaché;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'et ils te traiteront avec haine, et prendront tous tes gains, et te laisseront nue et découverte, afin de mettre à découvert ta nudité que tu as prostituée, et ton crime, et ton impudicité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Je te ferai ces choses parce que tu es allée te prostituant après les nations, et parce que tu t\'es souillée de leurs idoles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Tu as suivi le même chemin que ta sœur, aussi mettrai-je sa coupe en ta main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Ainsi parle le Seigneur, l\'Éternel: Tu boiras la coupe de ta sœur, coupe profonde et large; elle excitera contre toi la risée et la moquerie; grande est sa capacité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Tu seras chargée d\'ivresse et de chagrin; c\'est une coupe de stupeur et d\'effroi que la coupe de ta sœur Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Et tu la boiras, la videras, tu en lécheras les têts, dont tu te déchireras les mamelles; car je l\'ai prononcé, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Aussi, ainsi parle le Seigneur, l\'Éternel: Parce que tu m\'as oublié, et que tu m\'as jeté derrière toi, toi aussi subis les suites de ton crime et de ton impudicité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Et l\'Éternel me dit: Fils de l\'homme, jugeras-tu Ohola et Oholiba? et montre-leur leurs abominations:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'qu\'elles furent adultères, qu\'il y a du sang à leurs mains, et qu\'elles ont commis adultère avec leurs idoles, et que même leurs enfants qu\'elles avaient enfantés pour moi, elles les leur ont consacrés comme nourriture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Voici ce qu\'elles m\'ont encore fait: elles ont souillé mon sanctuaire en ce jour-là, et profané mes sabbats.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Car après avoir immolé leurs enfants à leurs idoles, elles sont venues dans mon sanctuaire ce jour-là pour le profaner, et voici, cela, elles l\'ont fait au sein de ma maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Bien plus, elles envoyèrent chercher des hommes qui devaient venir de loin, et auxquels des messagers furent expédiés, et voici, ils vinrent: pour eux tu te baignas, peignis tes yeux, et te paras-de tes parures;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'et tu te plaças sur un lit magnifique: au devant était dressée une table sur laquelle tu mis mon encens et mon huile;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'et de ce lieu on entendait sortir les cris joyeux d\'une multitude en sécurité; et outre les hommes de la multitude on avait fait venir des buveurs du désert, qui leur mirent des bracelets aux mains et de superbes diadèmes sur la tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Alors je dis de celle qu\'ont usée les adultères: Maintenant aura-t-on commerce avec elle? avec elle!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Et l\'on vint à elle, comme on vient à une prostituée; c\'est ainsi qu\'on vint à Ohola et à Oholiba, femmes criminelles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Mais des hommes justes les jugeront selon la loi des adultères, et selon la loi des meurtriers; car elles sont adultères, et ont du sang à leurs mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Car ainsi parle le Seigneur, l\'Éternel: Je vais faire avancer contre elles un rassemblement, et les livrer aux tourments et au pillage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'et elles seront lapidées par eux, et taillées en pièces par leurs épées, leurs fils et leurs filles seront égorgés, et leurs maisons brûlées au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Ainsi mettrai-je fin au crime dans le pays, afin que toutes les femmes en reçoivent instruction, et ne deviennent pas criminelles comme elles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Et ils feront retomber leur crime sur vous, et vous subirez le, péché de votre idolâtrie, afin que vous sachiez que je suis le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'La neuvième année, le dixième mois, le dixième jour du mois, la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Fils de l\'homme, note le nom de ce jour, de ce jour-ci! Le roi de Babel s\'avance sur Jérusalem en ce jour même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Et propose à la race rebelle une parabole et dis-leur: Ainsi parle le Seigneur, l\'Éternel: Place, place la chaudière et verses-y aussi de l\'eau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'réunis et mets-y ses morceaux, toute espèce de bons morceaux, les cuisses et les épaules; remplis-la des meilleurs os.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Prends l\'élite du troupeau, et aussi une pile de bois à proportion de ses os, et mets-la dessous; fais-la bouillir, de sorte que les os y cuisent aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'C\'est pourquoi ainsi parle le Seigneur, l\'Éternel: Malheur à la ville meurtrière, chaudière rouillée, dont la rouille ne se détache pas! Tires-en morceau après morceau, et qu\'on ne les choisisse pas au sort!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Car c\'est chez elle qu\'elle a versé le sang: elle l\'a versé sur le roc nu, et ne l\'a point répandu sur la terre, où on aurait pu le couvrir de poussière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'C\'est afin d\'exciter ma colère et pour tirer vengeance que j\'ai permis qu\'elle répandît le sang sur le roc nu, pour qu\'il ne pût être couvert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Aussi ainsi parle le Seigneur, l\'Éternel: Malheur à la ville meurtrière! Moi aussi j\'élèverai une pile de bois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Entasse le bois, allume le feu, cuis les viandes, et mets-y l\'assaisonnement, et que les os soient brûlés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Et place-la vide sur les charbons, afin que son airain s\'échauffe et devienne brûlant, et que sa souillure y fonde, et que sa rouille soit consumée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Je m\'y fatigue et m\'y peine, mais son épaisse rouille ne s\'en détache pas, la rouille résiste au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Dans ta souillure il y a du crime, parce que je voulais te purifier, et que tu ne devins pas pure. Tu ne seras plus purifiée de la souillure, que je n\'aie assouvi ma colère sur toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Moi l\'Éternel, je l\'ai dit: le temps en vient, et je l\'exécuterai; je ne veux ni m\'en désister, ni avoir pitié ou repentir. On te jugera selon ta conduite et tes forfaits, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Et la parole de l\'Éternel me-fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Fils de l\'homme, voici, je vais t\'enlever par un coup le délice de tes yeux, et tu ne gémiras ni ne pleureras, et que les larmes ne te viennent pas aux yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Soupire en silence, ne prends pas le deuil des morts, attache ta tiare à ta tête, et mets tes souliers à tes pieds, ne te voile pas la barbe et ne mange pas le pain de condoléance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Et comme j\'avais parlé au peuple le matin, ma femme mourut le soir; et le matin j\'exécutai l\'ordre que j\'avais reçu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Alors le peuple me dit: Ne nous expliqueras-tu point quel sens a pour nous ce que tu fais là?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Et je leur dis: La parole de l\'Éternel m\'a été adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Dis à la maison d\'Israël: Ainsi parle le Seigneur, l Éternel: Voici, je vais profaner mon sanctuaire, votre orgueil et votre assurance, le délice de vos yeux et l\'amour de vos âmes; et vos fils et vos filles que vous avez laissés, périront par l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Et vous ferez comme je viens de faire: vous ne vous voilerez point la barbe, ne mangerez point le pain de condoléance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'et vous aurez vos tiares à vos têtes, et vos souliers à vos pieds; vous ne gémirez ni ne pleurerez, mais vous dépérirez par l\'effet de vos crimes et vous soupirerez vis-à-vis l\'un de l\'autre. Et ainsi Ézéchiel sera pour vous un signe prophétique;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'tout ce qu\'il a fait, vous le ferez, quand le temps sera venu, et vous saurez que je suis le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Pour toi, fils de l\'homme, le jour où je leur ôterai ce qui fait leur assurance, leur joie et leur gloire, le délice de leurs yeux, et l\'affection de leurs âmes, leurs fils et leurs filles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'ce jour-là même un homme qui s\'échappera, viendra faire entendre cela à tes oreilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'En ce jour-là même, ta bouche s\'ouvrira de concert avec cet homme échappé, et tu parleras et ne seras plus muet. Et tu seras pour eux un signe prophétique, et ils sauront que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Fils de l\'homme, tourne ton visage contre les enfants d\'Ammon et prophétise contre eux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'et dis aux enfants d\'Ammon: Écoutez la parole du Seigneur, l\'Éternel! Ainsi parle le Seigneur, l\'Éternel: Parce que tu as dit: « Ah! ah! » à la vue de mon sanctuaire profané et du pays d\'Israël désolé, et de la maison de Juda menée en captivité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'pour cela, voici, je te donne aux enfants de l\'Orient en propriété, pour qu\'ils établissent leurs parcs au milieu de toi, et y fixent leurs demeures; ils mangeront tes fruits et boiront ton lait:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'et je ferai de Rabbah un pâturage pour les chameaux, et [du pays] des enfants d\'Ammon une bergerie pour les brebis, et vous saurez que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Car ainsi parle le Seigneur, l\'Éternel: Parce que tu as battu des mains et frappé du pied, et qu\'avec tout ton orgueil tu t\'es réjouie de cœur à la vue du pays d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'pour cela, voici, j\'étends ma main contre toi, et te livre en proie aux nations, et te retranche du nombre des peuples, et t\'extermine du milieu des pays; je t\'anéantis, afin que tu saches que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Ainsi parle le Seigneur, l\'Éternel: Parce que Moab et Séir disent: Voici, la maison de Juda est comme tous les autres peuples!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'pour cela, voici j\'ouvre le flanc de Moab, depuis les villes, depuis toutes ses villes, ornement du pays, Beth-Jésimoth, Baal-Meon et jusqu\'à Kiriathaïm,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'aux enfants de l\'Orient, en même temps que le pays des enfants d\'Ammon, et je le leur donnerai en propriété, afin qu\'il ne soit plus fait mention des enfants d\'Ammon parmi les peuples;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'et sur Moab j\'exécuterai mes jugements, afin qu\'ils sachent que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Ainsi parle le Seigneur, l\'Éternel: Parce que Édom s\'est conduit envers la maison de Juda par un esprit de vengeance, et s\'est rendu coupable, et a tiré vengeance d\'elle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'pour cela, ainsi parle le Seigneur, l\'Éternel: J\'étendrai ma main contre Édom, et en exterminerai les hommes et les bêtes, et j\'en ferai un désert de Théman à Dedan; ils périront par l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Et j\'exécuterai mes vengeances sur Édom par le bras de mon peuple d\'Israël, et il traitera Édom selon ma colère et mon courroux, et ils ressentiront mes vengeances, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Ainsi parle le Seigneur, l\'Éternel: Parce que les Philistins ont agi par vengeance et qu\'ils se sont vengés orgueilleusement et de cœur, avec la volonté de détruire, par suite d\'une haine éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'pour cela, ainsi parle le Seigneur, l\'Éternel: Voici, j\'étends ma main contre les Philistins, et j\'extirperai les Crétites, et détruirai ce qui reste sur la côte de la mer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'et j\'exercerai sur eux de grandes vengeances en châtiant avec fureur, afin qu\'ils sachent que je suis l\'Éternel, quand j\'exercerai mes vengeances sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'La onzième année, le premier jour du mois, la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Fils de l\'homme, parce que Tyr a dit sur Jérusalem: « Ah! ah! elle est brisée la porte des peuples, c\'est vers moi qu\'on afflue, je me remplirai, elle est déserte! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'pour cela, ainsi parle le Seigneur, l\'Éternel: Voici, j\'en veux à toi, Tyr, et je fais avancer contre toi des peuples nombreux, comme la mer fait avancer ses vagues;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'et ils détruiront les murs de Tyr, et démoliront ses tours, et j\'en balaierai sa terre, et en ferai un roc nu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Elle deviendra un lieu à étendre les filets, au sein de la mer; car c\'est moi qui parle, dit le Seigneur, l\'Éternel; et elle sera la proie des peuples,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'et ses filles qui sont sur la terre seront tuées par l\'épée; et ils sauront que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Car ainsi parle le Seigneur, l\'Éternel: Voici, j\'amène contre Tyr Nébucadnézar, roi de Babel, depuis le septentrion roi des rois, avec des chevaux et des chars, et des cavaliers, et une multitude, et un peuple nombreux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Il tuera par l\'épée tes filles qui sont sur la terre, et il dressera contre toi des tours, et construira contre toi des terrasses, et lèvera contre toi le bouclier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'Et il portera ses coups devant lui contre tes murs, et démolira tes tours avec ses machines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Il te couvrira de la poussière soulevée par ses nombreux chevaux; au bruit de la cavalerie et des roues et des chars, tes murs seront ébranlés, quand il pénétrera dans tes portes, comme on pénètre dans une ville par la brèche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Du sabot de ses chevaux il foulera toutes tes rues; il massacrera ton peuple avec l\'épée, et tes statues tutélaires tomberont sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Et ils feront leur proie de tes richesses, et pilleront tes marchandises, et démoliront tes murailles, et abattront tes maisons de plaisance, et jetteront au sein des eaux tes pierres, et tes bois, et ta terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Et je ferai cesser le bruissement de tes chants, et le son de tes luths ne sera plus entendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Je ferai de toi un roc nu, et tu deviendras un lieu à étendre les filets. Tu ne seras plus relevée, car c\'est moi, l\'Éternel, qui ai parlé, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Ainsi parle à Tyr le Seigneur, l\'Éternel: Voici, au fracas de ta chute, aux gémissements des blessés, au massacre qui sera fait dans ton sein, les îles sont tremblantes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'et tous les princes de la mer descendent de leurs trônes, et jettent leurs manteaux, et se dépouillent de leurs vêtements brochés; d\'épouvante ils s\'enveloppent et s\'assoient sur la terre; ils sont consternés de ta ruine et dans la stupeur à ta vue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'et ils élèvent sur toi une complainte et te disent: Comment as-tu péri, toi le rendez-vous des mers, ville illustre, qui étais puissante sur la mer, toi et tes habitants, qui inspiraient la terreur à tous tes voisins!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Maintenant au jour de ta chute les îles tremblent, et les îles de la mer sont consternées de ta fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Car ainsi parle le Seigneur, l\'Éternel: Quand je ferai de toi une ville en ruines, pareille aux villes qui ne sont plus habitées, quand je soulèverai contre toi les flots afin que les grandes eaux te recouvrent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'alors je te précipiterai vers ceux qui sont descendus dans la fosse, vers le peuple de jadis, et te placerai dans les régions souterraines, dans une solitude éternelle, près de ceux qui sont descendus dans la fosse, afin que tu ne sois plus habitée; tandis que je mettrai de la gloire sur la terre des vivants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Je ferai de toi un terrible exemple de destruction; c\'en est fait de toi! on te cherchera, mais on ne te retrouvera jamais, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Et toi, fils de l\'homme, élève sur Tyr une complainte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'et dis à Tyr: Toi qui es établie aux abords de la mer, qui portes le commerce des peuples dans les îles nombreuses! ainsi parle le Seigneur, l\'Éternel: Tyr, tu dis: Je suis parfaite en beauté!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Ton territoire est au sein des mers; tes architectes rendirent ta beauté accomplie:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'des cyprès de Sénir ils ont fait tous tes lambris; ils ont pris des cèdres du Liban pour t\'en faire un mât;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'des chênes de Basan ils ont fait tes rames, et tes bancs d\'ivoire enchâssé dans le buis des îles de Cittim;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'tu déployais pour voiles le lin broché de l\'Egypte, la pourpre violette et écarlate des îles d\'Élisa formait tes tentures;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'les habitants de Sidon et d\'Arvad étaient tes rameurs; tu avais, ô Tyr, des hommes experts, ils étaient tes marins;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'tu avais chez toi les anciens de Gébal et ses habiles pour réparer tes lézardes; tu avais chez toi tous les vaisseaux de la mer, et leurs marins pour faire l\'échange de tes marchandises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Persans, et Lydiens, et Libyens étaient dans tes armées, c\'étaient tes hommes de guerre; ils suspendaient chez toi le bouclier et le casque, ils te donnaient de la splendeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Les enfants d\'Arvad et tes propres soldats se tenaient sur tes murs de toutes parts, et des braves étaient sur tes tours; ils suspendaient leurs pavois à tes murs de toutes parts, ils rendaient ta beauté accomplie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Tarsis trafiquait avec toi, car tu avais en nombre toutes sortes de biens; d\'argent, de fer, d\'étain et de plomb ils fournissaient tes marchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javan, Thubal et Mésech étaient tes trafiquants; ils échangeaient avec toi des âmes d\'hommes et des meubles d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Les hommes de la maison de Thogarma de chevaux, de cavaliers et de mulets fournissaient tes marchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Les enfants de Dedan étaient tes trafiquants; de nombreuses îles trafiquaient par tes mains; elles te donnaient des cornes d\'ivoire et de l\'ébène en paiement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'La Syrie trafiquait avec toi à cause du nombre de tes objets d\'art; d\'escarboucles, de pourpre et de tissus brochés, et de lin, et de coraux, et de grenat ils fournissaient tes marchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juda et le pays d\'Israël trafiquaient avec toi; ils échangeaient avec toi le froment de Minnith, et les gâteaux, et le miel, et l\'huile et le baume.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damas, à cause du nombre de tes objets d\'art, et de toutes sortes de biens que tu avais en abondance, faisait avec toi le commerce du vin de Helbon, et d\'une laine d\'une éclatante blancheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Vedan et Javan apportaient des tissus à tes marchés: le fer travaillé, la casse et le calamus étaient échangés avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan faisait avec toi le commerce des housses pour monter à cheval.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'L\'Arabie et tous les princes de Cédar trafiquaient par tes mains; c\'est d\'agneaux et de béliers et de boucs qu\'ils faisaient commerce avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Les marchands de Séba et de Raéma trafiquaient avec toi; de tous les aromates exquis, de toutes les pierreries et d\'or ils fournissaient tes marchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Haran et Canna et Éden, les marchands de Séba, Assur, Kilmad trafiquaient avec toi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'sur ton marché ils faisaient avec toi commerce de riches étoffes, de manteaux de pourpre violette et brochés, et de coffres pleins de tissus damassés, faits de cèdre et liés avec des cordes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Les navires de Tarsis étaient tes caravanes dans ton commerce; et ainsi tu te remplis et devins très puissante au sein des mers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Tes rameurs te font voguer sur les grandes eaux... le vent d\'Orient vient te briser au sein des mers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Ton opulence et ton marché et ton trafic, tes marins et tes matelots, les réparateurs de tes lézardes et ceux qui échangent tes marchandises, et tous tes hommes de guerre qui sont chez toi, avec toute la multitude qui est au milieu de toi, tomberont dans le sein des mers au jour de ta chute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Au bruit des cris de tes matelots les places trembleront,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'et de leurs vaisseaux descendront tous ceux qui manient la rame, les marins, tous les matelots de la mer; ils gagneront la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'et de leurs voix ils pousseront à ton sujet des cris et des gémissements amers, et jetteront de la poussière sur leurs têtes, et se rouleront dans la cendre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'pour toi ils se raseront la tête, et ceindront le cilice et pleureront dans la douleur de leur âme, dans l\'amertume de leur deuil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Dans leur chagrin ils élèveront un chant funèbre sur toi et diront en se lamentant sur toi: Qui est comme Tyr, cette [ville] en ruines au sein de la mer?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Par ton commerce qui embrassait toutes les mers, tu donnais l\'abondance à nombre de peuples; par le nombre de tes trésors et de tes marchandises tu enrichissais les rois de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Maintenant que tu as été brisée par les flots sur les abîmes des eaux, ton trafic et toute ta multitude ont péri avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Tous les habitants des îles te regardent avec stupeur, et leurs rois frissonnent, leur visage est tremblant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Les marchands des peuples te sifflent; tu es un terrible exemple de ruine, et c\'en est fait de toi à jamais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Fils de l\'homme, dis au prince de Tyr: Ainsi parle le Seigneur, l\'Éternel: Parce que ton cœur s\'élève et que tu dis: « Je suis un Dieu, sur le trône d\'un Dieu je suis assis au sein des mers! » tandis que tu es un homme et non pas un Dieu, quoique dans ton cœur tu te croies un Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, '– voici, tu es plus sage que Daniel, aucun mystère n\'a rien de caché pour toi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'par ta sagesse et ton intelligence tu t\'es créé des richesses, et tu as fait entrer dans tes trésors de l\'or et de l\'argent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'par ta grande sagesse et ton trafic tu as accru ton opulence, et ton cœur s\'enorgueillit de ton opulence;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, '– pour cela, ainsi parle le Seigneur, l\'Éternel: Parce que dans ton cœur tu te crois un Dieu, pour cela,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'voici, je vais amener contre toi des étrangers, les plus violents des peuples: ils tireront l\'épée contre la magnificence de ta sagesse, et ils profaneront ta beauté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'ils te précipiteront dans la fosse, afin que tu meures de la mort des blessés, au sein de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Diras-tu bien: « Je suis un Dieu! » en face de ton meurtrier, quand tu es un homme et non pas un Dieu sous la main de celui qui te perce?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Tu mourras de la mort des incirconcis par la main d\'étrangers, car c\'est moi qui prononce ainsi, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Fils de l\'homme, élève une complainte sur le roi de Tyr, et dis-lui: Ainsi parle le Seigneur, l\'Éternel: Tu avais mis le sceau à ta perfection, tu étais plein de sagesse et d\'une beauté accomplie:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'tu habitais en Éden dans le jardin de Dieu; toutes les pierres précieuses te couvraient, le rubis, la topaze et le diamant, le chrysolithe, l\'onyx et le jaspe, le saphir, l\'escarboucle et l\'émeraude, et l\'or. Le service de tes cymbales et de tes flûtes était préparé pour toi dès le jour de ta naissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Tu étais un Chérubin protecteur, aux ailes déployées; ainsi je t\'établis, tu étais sur une sainte montagne de Dieu; tu marchais au milieu des pierres étincelantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Tu suivais ta voie sain et sauf dès le jour de ta naissance, jusqu\'à ce que ton crime ait été surpris en toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Par la grandeur de ton trafic, ton sein se remplit d\'iniquité, et tu devins criminel; aussi je te repousse loin de la montagne de Dieu, et t\'arrache, pour te perdre, Chérubin protecteur, à ces pierres étincelantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Ton cœur s\'enorgueillissait de ta beauté. Tu as corrompu toute ta sagesse pour l\'amour de ta beauté: je te précipite sur la terre, et aux rois je t\'offre en spectacle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Par le nombre de tes crimes, par l\'iniquité de ton trafic, tu as profané tes sanctuaires: aussi ferai-je sortir de ton sein un feu qui te consumera, et je te réduirai en cendres par terre sous les yeux de tous tes spectateurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Tous ceux qui parmi les peuples te connaissent, te contempleront avec stupeur; tu seras un terrible exemple de ruine et c\'en est fait de toi à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Fils de l\'homme, tourne ton visage du côté de Sidon, et prophétise contre elle');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'et dis: Ainsi parle le Seigneur, l\'Éternel: Voici, j\'en veux à toi, Sidon, et je veux être glorifié au milieu de toi, afin qu\'ils sachent que je suis l\'Éternel, quand j\'exercerai sur elle mes jugements, et que j\'aurai montré sur elle que je suis saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'J\'envoie la peste en elle, et l\'effusion du sang dans ses rues, et des morts périssent dans son sein par l\'épée de toutes parts tirée contre elle; et ils sauront que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Alors il n\'y aura plus pour la maison d\'Israël d\'épine piquante, ni de ronce déchirante, d\'entre tous ses alentours qui la méprisent, et ils sauront que je suis le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Ainsi parle le Seigneur, l\'Éternel: Quand je rassemblerai la maison d\'Israël du milieu des peuples où elle est dispersée, alors je donnerai en eux une preuve de ma sainteté sous les yeux des peuples,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'et ils habiteront leur pays que j\'ai donné à mon serviteur Jacob, et ils y habiteront en sécurité, et bâtiront des maisons et planteront des vignes, et habiteront en sécurité, quand j\'exécuterai mes jugements sur tous leurs alentours qui les méprisaient, et ils reconnaîtront que je suis l\'Éternel, leur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'La dixième année, le dixième mois, le douzième jour du mois, la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Fils de l\'homme, tourne ton visage contre Pharaon, roi d\'Egypte, et prophétise contre lui et contre toute l\'Egypte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'parle et dis: Ainsi parle le Seigneur, l\'Éternel: J\'en veux à toi, Pharaon, roi d\'Egypte, à toi le grand dragon couché au sein de ses fleuves, qui dis: « Mon fleuve est à moi, et je l\'ai fait pour moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Je mettrai une boucle à ta mâchoire; et j\'attacherai les poissons de tes fleuves à tes écailles, et te tirerai du sein de tes fleuves, avec tous les poissons de tes fleuves attachés à tes écailles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Puis je te jetterai au désert, toi et tous les poissons de tes fleuves, tu tomberas sur la face de la terre, et ne seras ni ramassé ni recueilli: aux bêtes de la terre et aux oiseaux des Cieux je te donne en proie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Et tous les habitants de l\'Egypte comprendront que je suis l\'Éternel. Parce qu\'ils furent un appui de roseau pour la maison d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'quand ils te prirent par ta poignée, tu te brisas y et leur fendis toute l\'épaule, et quand ils s\'appuyèrent sur toi, tu te cassas et ébranlas leurs reins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Aussi ainsi parle le Seigneur, l\'Éternel: Voici je ferai fondre l\'épée sur toi, et du milieu de toi j\'exterminerai hommes et bêtes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'et l\'Egypte deviendra un désert et une solitude, et ils sauront que je suis l\'Éternel. Parce que [Pharaon] dit: « Le fleuve est à moi et je l\'ai fait! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'pour cela, j\'en veux à toi et à tes fleuves, et je ferai du pays d\'Egypte une solitude et un vaste désert de Migdol à Siène, et jusques aux confins de l\'Ethiopie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'le pied de l\'homme ne le parcourra point, et le pied de l\'animal ne le traversera point, et il ne sera plus habité pendant quarante ans;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'et je ferai du pays d\'Egypte un désert entre les pays déserts, et entre les villes dévastées ses villes seront désertes pendant quarante ans, et je disperserai les Égyptiens parmi les nations et les disséminerai dans les pays divers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Cependant ainsi parle le Seigneur, l\'Éternel: Au terme de quarante ans je rassemblerai les Égyptiens du milieu des peuples où ils auront été dispersés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'et je ramènerai les captifs de l\'Egypte, et les ferai revenir au pays de Pathros dans leur pays d\'origine, et là ils formeront un humble royaume:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'il sera plus humble que les royaumes, et ne s\'élèvera plus au-dessus des peuples, et je les diminuerai, afin qu\'ils ne dominent plus les peuples:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'et ils ne donneront plus à la maison d\'Israël une confiance qui la faisait penser au crime, quand elle pouvait s\'adresser à eux, et ils sauront que je suis le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Et la vingt-septième année, le premier mois, le premier jour du mois, la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Fils de l\'homme, Nébucadnézar, roi de Babel, a fait faire à son armée un service pénible contre Tyr; toutes les têtes sont chauves, et toutes les épaules pelées, et Tyr ne le paie ni lui, ni son armée, du service qu\'il a fait contre elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Aussi, ainsi parle le Seigneur, l\'Éternel: Voici, je donne à Nébucadnézar, roi de Babel, le pays d\'Egypte, pour qu\'il emmène son peuple, et emporte sa dépouille, et pille. son butin, et ce sera là le salaire de son armée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Pour prix du service qu\'il a fait, je lui donne le pays d\'Egypte, car ils ont travaillé pour moi, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'Dans ce même temps je ferai croître une corne à la maison d\'Israël, et je t\'ouvrirai la bouche au milieu d\'eux, et ils sauront que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Fils de l\'homme, prophétise et dis: Ainsi parle le Seigneur, l\'Éternel: Gémissez! malheur pour le jour!...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'car le jour approche, il approche le jour de l\'Éternel! le moment des nations sera une sombre journée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'L\'épée fond sur l\'Egypte, et l\'angoisse est en Ethiopie, quand les blessés tombent en Egypte, et qu\'on emmène son peuple, et que ses fondements sont démolis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Éthiopiens et Libyens, et Lydiens, et tous les confédérés, et Chub et les fils des pays alliés, avec eux succomberont sous l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Ainsi parle l\'Éternel: Ils succombent les appuis de l\'Egypte, et elle est abattue son orgueilleuse puissance; de Migdol à Siène ils y périront par l\'épée, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Ils seront dévastés entre les terres dévastées, et ses villes seront au nombre des villes en ruines;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'et ils comprendront que je suis l\'Éternel, quand je mettrai le feu à l\'Egypte et que tous ses auxiliaires seront taillés en pièces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'Dans ce jour-là des messagers s\'en iront de par moi sur des navires porter l\'épouvante dans l\'Ethiopie en sécurité, et il y aura parmi eux de l\'angoisse, comme à la journée de l\'Egypte, car voici, elle arrive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Ainsi parle le Seigneur, l\'Éternel: Je mettrai fin au peuple de l\'Egypte par le bras de Nébucadnézar, roi de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Lui et son peuple avec lui, les plus violents des hommes, s\'avancent pour ravager le pays, et ils tireront leurs épées contre l\'Egypte, et rempliront le pays de morts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'et je mettrai les canaux à sec, et livrerai le pays aux mains d\'hommes méchants, et je dévasterai le pays et ce qu\'il contient par les bras d\'étrangers. Moi, l\'Éternel, je l\'ai dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Ainsi parle le Seigneur, l\'Éternel: Je détruirai les idoles, et anéantirai les faux dieux de Noph, et il n\'y aura plus de princes du pays d\'Egypte, et je répandrai la terreur sur le pays d\'Egypte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'et je dévasterai Pathros, et porterai le feu en Tsoan, et exercerai mes jugements sur No;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'et je verserai ma colère sur Sin, le boulevard de l\'Egypte, et j\'exterminerai le peuple de No;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'et je porterai le feu en Egypte: Sin sera tremblante, et No forcée, et Noph en plein jour prise par l\'ennemi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'les jeunes hommes de On et de Bubaste périront par l\'épée, et les femmes seront emmenées captives.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'A Tachphanès le jour s\'obscurcira, quand j\'y briserai le joug de l\'Egypte, et qu\'il y sera mis fin à son orgueilleuse puissance: un noir nuage la couvrira, et ses filles seront emmenées captives.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Ainsi j\'exécuterai mes jugements sur l\'Egypte et ils sauront que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Et la onzième année, le premier mois, le septième jour du mois, la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Fils de l\'homme, j\'ai rompu le bras de Pharaon, roi d\'Egypte, et voici, il n\'est point bandé, pour qu\'on y applique des remèdes, y mette un bandage pour le serrer, afin qu\'il ait la force de saisir une épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'C\'est pourquoi ainsi parle le Seigneur, l\'Éternel: Voici, j\'en veux à Pharaon, roi d\'Egypte, et je lui romprai les deux bras, celui qui est fort et celui qui est cassé, et je ferai tomber l\'épée de sa main;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'et je disperserai les Égyptiens parmi les nations et les disséminerai dans les pays divers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Mais je donnerai force aux bras du roi de Babel et mettrai mon épée en sa main, et je briserai les bras de Pharaon, afin qu\'il pousse devant lui les soupirs des blessés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Oui, je donnerai force aux bras du roi de Babel, mais les bras de Pharaon tomberont, afin qu\'ils reconnaissent que je suis l\'Éternel, quand je mettrai mon épée en la main du roi de Babel, afin qu\'il l\'étende sur le pays d\'Egypte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'et je disperserai les Égyptiens parmi les nations, et les disséminerai dans les pays divers, afin qu\'ils reconnaissent que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Et la onzième année, le troisième mois, le premier jour du mois, la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Fils de l\'homme, dis à Pharaon, roi d\'Egypte, et à son peuple: A qui ressembles-tu dans ta grandeur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Vois, Assur était un cèdre sur le Liban, beau par sa ramure, arbre touffu donnant un ombrage, et d\'une tige élevée, et sa cime était entourée de feuillage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Les eaux le faisaient grandir, et les flots croître en hauteur, dans leurs courants elles embrassaient son sol, et envoyaient leurs canaux à tous les arbres de la campagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Aussi sa taille était-elle plus élevée que celle de tous les arbres de la campagne, et dans son développement, ses branches grossirent et ses rameaux s\'allongèrent par l\'abondance des eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Sur ses branches nichaient tous les oiseaux des Cieux, et sous ses rameaux toutes les bêtes des champs venaient mettre bas, et tous les grands peuples habitaient à son ombre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Il était beau dans sa grandeur, dans la longueur de ses branches, car ses racines touchaient aux abondantes eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Les autres cèdres ne l\'effaçaient point dans le jardin de Dieu; les cyprès n\'égalaient point ses rameaux, ni les platanes ses branches; nul arbre dans le jardin de Dieu n\'était son pareil en beauté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Je l\'avais embelli par le nombre de ses rameaux, et tous les arbres d\'Éden, dans le jardin de Dieu, lui portaient envie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Aussi ainsi parle le Seigneur, l\'Éternel: Parce qu\'il avait une taille élevée, et qu\'il portait sa cime au milieu d\'un épais feuillage, et que son cœur s\'est enorgueilli de son élévation;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'je l\'ai livré aux mains du héros des nations pour qu\'il le traite [à son gré]: c\'est pour son impiété que je l\'ai expulsé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'et il a été arraché par des étrangers les plus violents des peuples, qui l\'ont jeté; sur les montagnes et dans toutes les vallées ses rameaux sont tombés, et ses branches ont été mises en pièces dans tous les vallons du pays, et tous les peuples de la terre se sont retirés de son ombrage, et l\'ont laissé là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Sur son tronc mutilé se posent tous les oiseaux des Cieux, et toutes les bêtes des champs sont sur ses branches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'Et c\'est afin que tous les arbres voisins des eaux ne s\'enorgueillissent pas de leur taille élevée, et ne dressent pas leur cime au milieu d\'un épais feuillage, afin que tous les chênes voisins des eaux ne persistent pas dans leur orgueil, car tous ils sont livrés à la mort pour rejoindre sous la terre parmi les enfants d\'Adam ceux qui sont descendus dans la fosse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Ainsi parle le Seigneur, l\'Éternel: Le jour où il descendit dans les Enfers, je mis l\'abîme en deuil, et le couvris d\'un voile, et j\'arrêtai les fleuves, et le cours des grandes eaux fut suspendu; pour lui je fis prendre le deuil au Liban, et tous les arbres des campagnes à cause de lui furent dans l\'abattement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Du fracas de sa chute j\'épouvantai les peuples, quand je le précipitai dans les Enfers vers ceux qui sont descendus dans la fosse; et ce fut sous la terre une consolation pour tous les arbres d\'Éden, les plus excellents et les meilleurs du Liban, tous abreuvés par les eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Eux aussi descendirent avec lui dans les Enfers près de ceux que l\'épée a percés; ils étaient son bras et demeuraient sous son ombre parmi les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'A qui, [Pharaon,] ressembles-tu ainsi en gloire et en grandeur parmi les arbres d\'Éden? Ainsi tu seras précipité avec les arbres d\'Éden sous la terre, tu seras gisant au milieu des incirconcis avec ceux que l\'épée a percés. Ainsi en sera-t-il de Pharaon et de tout son peuple, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Et la douzième année, le douzième mois, le premier jour du mois, la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Fils de l\'homme, élève une complainte sur Pharaon, roi d\'Egypte, et dis-lui: Tu ressemblais à un jeune lion parmi les peuples, et tu étais comme un dragon dans la mer. Tu t\'élanças dans tes fleuves, et troublas les eaux avec tes pieds, et foulas leurs flots.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Ainsi parle le Seigneur, l\'Éternel: J\'étendrai sur toi mon réseau devant une foule de peuples réunis, et ils te tireront dans mon filet,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'et je te jetterai sur la terre, et t\'étendrai sur la surface du sol, et ferai que tous les oiseaux des Cieux se posent sur toi, et te rendrai la pâture des bêtes de toute la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'et je jetterai ta chair sur les montagnes, et remplirai les vallées de tes débris,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'et j\'abreuverai de ton sang jusques aux montagnes le pays où tu nages, et les vallées seront remplies de toi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'et, quand je te détruirai, je voilerai le ciel, et ternirai ses étoiles, de nuages je voilerai le soleil, et la lune ne donnera plus sa lumière;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'j\'obscurcirai à cause de toi tous les brillants luminaires du ciel, et répandrai les ténèbres sur ton pays, dit le Seigneur, l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'et je porterai le chagrin dans le cœur de beaucoup de peuples, quand j\'annoncerai ta chute parmi les nations, dans des pays que tu ne connais pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'et je frapperai de stupeur à ton sujet nombre de peuples, et à cause de toi le frisson saisira leurs rois, quand je brandirai mon épée à leur visage; et ils trembleront incessamment chacun pour sa vie, au jour de ta chute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Car ainsi parle le Seigneur, l\'Éternel: L\'épée du roi de Babel fondra sur toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Par les épées des héros je ferai tomber ton peuple; ils sont tous les plus violents des hommes; ils abattront l\'orgueil de l\'Egypte, et tout son peuple sera anéanti.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Et j\'exterminerai tous ses animaux du milieu des grandes eaux; et le pied de l\'homme ne les troublera plus, et le sabot des animaux ne les troublera plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Alors je rendrai leurs eaux limpides, et ferai couler leurs fleuves comme de l\'huile, dit le Seigneur, l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'quand je désolerai le pays d\'Egypte, et que le pays sera dépouillé de tout ce qu\'il contient, quand je frapperai tous ses habitants, afin qu\'ils sachent que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'C\'est là une complainte, et on la dira comme complainte, les filles des peuples la diront comme complainte; elles élèveront cette complainte sur l\'Egypte et sur tout son peuple, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Et la douzième année, le quinzième jour du mois, la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Fils de l\'homme, gémis sur le peuple de l\'Egypte, et annonce qu\'ils descendront, eux et les filles des peuples puissants, sous la terre vers ceux qui sont descendus dans la fosse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Qui surpasses-tu en beauté? Descends et te couche à côté des incirconcis!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Ils tomberont parmi ceux que l\'épée a percés. [Déjà] l\'épée est remise. Entraînez-la, ainsi que tout son peuple!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Les plus puissants héros avec ses auxiliaires lui parleront du sein des Enfers où sont descendus, où sont couchés les incirconcis percés par l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Là est Assur et toute sa multitude; il est entouré de leurs tombeaux; tous ont été percés, ont péri par l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Son tombeau est pratiqué dans la fosse la plus enfoncée, et sa multitude entoure son tombeau; tous ont été percés, ont péri par l\'épée, eux qui répandaient la terreur sur la terre des vivants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Là est Élam et toute sa multitude; il est entouré de ses tombeaux; tous ils ont été percés, ont péri par l\'épée, sont descendus incirconcis sous la terre, eux qui répandaient la terreur sur la terre des vivants, et ils subissent leur opprobre auprès de ceux qui sont descendus dans la fosse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'parmi les morts on lui a donné sa place avec toute sa multitude; il est entouré de ses tombeaux, tous incirconcis ils ont été percés par l\'épée; parce qu\'ils répandaient la terreur sur la terre des vivants, ils subissent leur opprobre avec ceux qui sont descendus dans la fosse; parmi les morts ils sont couchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Là sont Mésech et Thubal et toute leur multitude; ils sont entourés de ses tombeaux; tous incirconcis, ils ont été percés par l\'épée, parce qu\'ils répandaient la terreur sur la terre des vivants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Et ils ne seraient pas couchés avec les héros morts des incirconcis qui sont descendus dans les Enfers avec leurs armes de guerre, sous la tête desquels on met leurs épées, et dont le crime repose sur leurs ossements, parce qu\'ils furent la terreur des héros sur la terre des vivants?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'De même tu seras mis en pièces au milieu des incirconcis, et couché avec ceux que l\'épée a percés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Là est Édom, ses rois et tous ses princes, qui malgré leur bravoure ont été mis avec ceux que l\'épée a percés; ils sont couchés au milieu des incirconcis, de ceux qui sont descendus dans la fosse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Là sont les princes du Nord, eux tous, et tous les Sidoniens qui sont descendus vers les morts, malgré la terreur qu\'ils répandaient par leur bravoure, ils sont confondus et couchés, incirconcis, avec ceux que l\'épée a percés, et subissent leur opprobre près de ceux qui sont descendus dans la fosse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Tels sont ceux que verra Pharaon: il sera consolé de toute sa multitude. L\'épée percera Pharaon et toute son armée, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Je le laissai répandre la terreur sur la terre des vivants; mais il est couché au milieu des incirconcis, avec ceux que l\'épée a percés, Pharaon et toute sa multitude, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Fils de l\'homme, parle aux enfants de ton peuple et dis-leur: Si je faisais venir l\'épée sur un pays, et que le peuple du pays prît dans son sein un homme dont ils fissent leur sentinelle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'et qui, voyant venir l\'épée sur le pays, sonnât de la trompette, pour avertir le peuple;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'si quelqu\'un, entendant le son de la trompette, ne recevait pas l\'avertissement, et que l\'épée vînt et le surprît, son sang pèserait sur sa tête:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'il a ouï le son de la trompette, et n\'a pas reçu l\'avertissement, son sang pèse sur sa tête. Mais s\'il reçoit l\'avertissement, il sauvera son âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Que si la sentinelle voyant venir l\'épée, ne sonne pas de la trompette, et que, sans que le peuple soit averti, l\'épée arrive et ôte la vie à un seul homme, cet homme périra par suite de son crime, mais je redemanderai son sang à la sentinelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Or, fils de l\'homme, je t\'ai établi sentinelle pour la maison d\'Israël, afin que de ma bouche tu entendes la parole, et que tu les avertisses de ma part.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Si je dis à l\'impie: Impie, tu mourras! et que tu ne parles pas pour détourner par tes avis l\'impie de sa voie, cet impie mourra par suite de son crime, mais je te redemanderai son sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Mais si par tes avis tu as cherché à détourner l\'impie de sa voie, pour qu\'il la quitte, s\'il ne la quitte pas, il mourra par suite de son crime; mais toi, tu auras sauvé ton âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Donc, fils de l\'homme, dis à la maison d\'Israël: Vous dites: « Nous sommes sous le poids de nos péchés et de nos crimes, et c\'est par eux que nous périssons; comment donc pourrions-nous vivre? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Dis-leur: Par ma vie, dit le Seigneur, l\'Éternel, je ne prends point plaisir à la mort de l\'impie, mais à ce que l\'impie renonce à sa voie, et qu\'il vive. Quittez, quittez vos mauvaises voies! Pourquoi voudriez-vous la mort, maison d\'Israël?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Et toi, fils de l\'homme, dis aux enfants de ton peuple: La justice du juste ne le sauvera pas au jour qu\'il péchera; et l\'impiété de l\'impie ne sera pas pour lui une cause de ruine, au jour qu\'il abandonnera son impiété, de même que le juste n\'aura pas dans sa justice une cause de vie, le jour qu\'il deviendra pécheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Si je dis du juste: Qu\'il ait la vie! et que, se confiant en sa justice, il fasse le mal, il ne lui sera point tenu compte de toute sa justice, et il mourra par suite du mal qu\'il a fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Mais si je dis de l\'impie: Qu\'il meure! et que, renonçant à ses péchés, il agisse selon le droit et la justice,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'rendant le gage, restituant ce qu\'il a pris, se conduisant selon les commandements qui donnent la vie, sans faire rien qui soit mal; il vivra, ne mourra point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'De tous les péchés qu\'il aura commis, il ne sera point tenu compte contre lui: il a fait ce qui est droit et juste; il vivra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Cependant les enfants de ton peuple disent: « La voie du Seigneur n\'est pas droite; » mais c\'est votre voie qui n\'est pas droite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Quand le juste renonce à sa justice et fait le mal, il en meurt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Et quand l\'impie renonce à son impiété et fait ce qui est droit et juste, par là il obtient la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Et vous dites: « La voie du Seigneur n\'est pas droite! » Je vous jugerai chacun de vous selon la voie que vous suivez, maison d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'Et la douzième année, le dixième mois, le cinquième jour du mois, depuis notre déportation, un homme qui s\'était échappé de Jérusalem, arriva auprès de moi et dit: La ville est prise!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Or la main de l\'Éternel s\'était fait sentir à moi la veille de l\'arrivée de ce fugitif, et m\'avait ouvert la bouche quand il arriva auprès de moi le matin; et ainsi, ma bouche s\'ouvrit, et je ne fus plus muet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Fils de l\'homme, les habitants de ces ruines dans le pays d\'Israël disent: « Abraham était un seul homme, et il a obtenu la propriété du pays; or nous sommes nombreux; la propriété du pays nous est dévolue. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'C\'est pourquoi, dis-leur: Ainsi parle le Seigneur, l\'Éternel: Vous mettez du sang dans ce que vous mangez, et vous levez les yeux vers vos idoles, et vous répandez le sang; et vous posséderiez le pays!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Vous vous appuyez sur votre épée; vous, femmes, vous commettez des abominations; vous déshonorez la femme l\'un de l\'autre; et vous posséderiez le pays!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Parle-leur ainsi: Ainsi parle le Seigneur, l\'Éternel: Oui, par ma vie, ceux qui sont dans les ruines périront par l\'épée, et ceux qui sont dans les champs, je les livrerai en proie aux bêtes féroces, et ceux qui sont dans les forts et dans les cavernes, mourront de la peste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Et du pays je ferai un désert et une solitude, et leur insolent orgueil prendra fin, et les montagnes d\'Israël deviendront un désert que personne ne traverse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Alors ils sauront que je suis l\'Éternel, quand je ferai du pays un désert et une solitude à cause de toutes les abominations qu\'ils ont commises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Quant à toi, fils de l\'homme, les enfants de ton peuple s\'entretiennent de toi entre les murs et dans les portes de leurs maisons, et ils se parlent l\'un à l\'autre, chacun à son frère, et disent: « Venez donc, et écoutez quelle parole émane de l\'Éternel! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Et ils viennent à toi, comme un concours de peuple, et s\'assoient devant toi, comme étant mon peuple, et ils écoutent tes paroles, mais ils ne les mettent point en pratique: mais ils font ce qui leur plaît, et leur cœur s\'attache à leur cupidité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Et voici, tu es pour eux comme un chant agréable par la beauté de la voix et l\'harmonie de la musique; ils écoutent tes paroles, mais ne les mettent point en pratique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Mais quand viendront [les maux], et voici, ils arrivent! ils comprendront qu\'il y avait un prophète au milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Fils de l\'homme, prophétise contre les pasteurs d\'Israël! prophétise et dis-leur, aux pasteurs: Ainsi parle le Seigneur, l\'Éternel: Malheur aux pasteurs d\'Israël, qui sont pasteurs d\'eux-mêmes! Les pasteurs ne devraient-ils pas être pasteurs du troupeau?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Vous mangez la graisse et vous vous habillez de la laine, vous tuez ce qu\'on a engraissé; mais vous ne paissez point les brebis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'vous ne fortifiez point celles qui sont faibles, et ne guérissez point les malades, et ne mettez point de bandage aux blessées, et ne ramenez point celles qui s\'égarent, et ne cherchez point celles qui se perdent, et vous exercez sur elles une domination violente et tyrannique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Et ainsi elles se sont dispersées faute de pasteur, et sont devenues la proie de toutes les bêtes des champs, et elles ont été dispersées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Mes brebis sont errantes sur toutes les montagnes et sur toutes les hautes collines, et mes brebis sont éparses sur tout le pays; et personne qui s\'en occupe et personne qui les cherche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Aussi, pasteurs, écoutez la parole de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Par ma vie, dit le Seigneur, l\'Éternel, parce que mes brebis sont devenues la proie, devenues la pâture de toutes les bêtes des champs, faute de pasteurs, et parce que mes pasteurs ne se sont point occupés de mes brebis, et n\'ont été pasteurs que d\'eux-mêmes, mais n\'ont point été pasteurs de mes brebis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'pour cela, pasteurs, écoutez la parole de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Ainsi parle le Seigneur, l\'Éternel: J\'en veux aux pasteurs, et je leur redemanderai mes brebis, et les ferai cesser de paître mes brebis, et ils ne seront plus pasteurs d\'eux-mêmes, et je retirerai mes brebis de leur bouche, afin qu\'elles ne soient plus leur pâture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Car ainsi parle le Seigneur, l\'Éternel: Voici, je veux moi-même m\'enquérir de mes brebis et m\'occuper d\'elles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Comme un pasteur s\'occupe de son troupeau, quand il est au milieu de ses brebis éparses, ainsi je veux m\'occuper de mon troupeau, et les retirer de tous les lieux où ils auront été dispersés au jour nébuleux et sombre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'et les faire revenir du milieu des peuples, et les recueillir des pays divers et les ramener dans leur pays, et les paître sur les montagnes d\'Israël, dans les vallées et dans tous les lieux habités du pays:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'je les ferai paître sur un bon pâturage, et leur pacage sera sur les hautes montagnes d\'Israël; là elles reposeront dans un bon pacage, et auront de gras pâturages sur les montagnes d\'Israël:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'je serai moi-même le pasteur de mes brebis, et moi-même je les parquerai, dit le Seigneur, l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'je veux chercher les brebis perdues, et ramener celles qui sont égarées, et mettre un bandage aux blessées, et fortifier les malades; mais les brebis grasses et vigoureuses, je veux les détruire, et les paître comme la justice le veut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Vous donc, mes brebis! ainsi parle le Seigneur, l\'Éternel: Voici, je serai juge entre brebis et brebis, entre béliers et boucs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Est-ce trop peu pour vous, [brebis vigoureuses]? Vous broutez le meilleur pâturage, et ce qui reste de votre pâture, vous le foulez sous vos pieds; vous buvez une eau pure, et le reste vous le troublez avec vos pieds;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'et mes brebis sont réduites à brouter ce que vos pieds ont foulé, et à boire ce que vos pieds ont troublé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Aussi, ainsi leur parle le Seigneur, l\'Éternel: Voici, moi-même je serai juge entre la brebis grasse et la brebis maigre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Parce que du flanc et de l\'épaule vous heurtez, et que de vos cornes vous frappez toutes les brebis malades, jusqu\'à ce que vous les ayez poussées dehors,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'je porterai secours à mes brebis, afin qu\'elles ne soient plus une proie, et je serai juge entre brebis et brebis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Et j\'établirai sur elles un seul pasteur qui les fera paître, mon serviteur David; c\'est lui qui les fera paître et sera leur pasteur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'et moi, l\'Éternel, je serai leur Dieu, et mon serviteur David sera prince au milieu d\'eux: c\'est moi, l\'Éternel, qui le dis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Et je leur donnerai une alliance de paix, et j\'exterminerai les bêtes sauvages du pays, afin qu\'en sécurité ils habitent dans le désert, et dorment dans les forêts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'et je répandrai ma bénédiction sur eux et sur les alentours de ma colline, et ferai descendre la pluie en son temps, et ce seront des pluies fertilisantes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'et l\'arbre des campagnes donnera son fruit et la terre donnera ses productions; et ils seront en sécurité dans leur pays, et ils sauront que je suis l\'Éternel, quand j\'aurai brisé les barres de leur joug, et les aurai tirés des mains de ceux qui les asservirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Et ils ne seront plus en proie aux nations, ni la pâture des bêtes de la terre, et ils auront la sécurité dans leurs demeures, et nul ne leur inspirera de la terreur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'et j\'établirai pour eux une plantation qui aura du renom, et ils ne seront plus enlevés par la famine dans le pays, et ne subiront plus l\'opprobre des nations;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'et ils reconnaîtront que moi, l\'Éternel, leur Dieu, je suis près d\'eux, et que, eux, maison d\'Israël, ils sont mon peuple, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Pour vous, mon troupeau, troupeau dont je suis le Pasteur, vous êtes des hommes, mais je suis votre Dieu, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Fils de l\'homme, tourne ton visage du côté de la montagne de Séir, et prophétise contre elle');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'et dis-lui: Ainsi parle le Seigneur, l\'Éternel: Voici, j\'en veux à toi, montagne de Séir; je vais étendre ma main contre toi et faire de toi un désert et une solitude;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'je mettrai tes villes en ruines, et toi tu seras changée en désert, afin que tu saches que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Parce que tu avais une haine éternelle, et que tu as livré les enfants d\'Israël à l\'épée, au temps de leurs revers, au temps du crime qui amène la fin, pour cela,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'par ma vie, dit le Seigneur, l\'Éternel, je verserai ton sang, et tu seras poursuivie par le sang; parce que tu n\'as pas eu en haine l\'effusion du sang, tu seras poursuivie par le sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Et je ferai de la montagne de Séir un désert et une solitude, et j\'en exterminerai tous les passants et les voyageurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'et je remplirai ses montagnes de morts; sur tes collines, et dans tes vallées et dans tous tes vallons les hommes tomberont percés par l\'épée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'je ferai de toi un désert éternel, et tes villes ne seront plus habitées, afin que vous sachiez que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Parce que tu as dit: « Ces deux peuples et ces deux pays seront à moi, et nous les occuperons: » tandis que l\'Éternel y était; c\'est pourquoi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'par ma vie, dit le Seigneur, l\'Éternel, j\'agirai avec la colère et la fureur que tu leur as montrée par l\'effet de ta haine, et je me manifesterai au milieu d\'eux, quand je te jugerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Et tu sauras que je suis l\'Éternel, et que j\'ai entendu tous les outrages que tu as prononcés contre les montagnes d\'Israël en disant: « Elles sont dévastées, nous sont livrées en proie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Vous avez ouvert contre moi une bouche insolente, et accumulé contre moi des discours altiers; j\'ai entendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Ainsi parle le Seigneur, l\'Éternel: A la joie de toute la terre, je ferai de toi un désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Comme l\'héritage de la maison d\'Israël a excité ta joie, parce qu\'il était ravagé, je te traiterai de même; la montagne de Séir, et Édom tout entier, sera un désert, afin qu\'ils sachent que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Or, fils de l\'homme, prophétise pour les montagnes d\'Israël et dis: Montagnes d\'Israël, écoutez la parole de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Ainsi parle le Seigneur, l\'Éternel: Parce que l\'ennemi dit de vous: « Ah! ah! ces hauteurs éternelles sont devenues notre propriété! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'pour cela, prophétise et dis: Ainsi parle le Seigneur, l\'Éternel: Précisément parce qu\'on vous dévaste et vous dévore de toutes parts, pour faire de vous la propriété des autres peuples, et vous exposer aux discours de la langue et aux mauvais propos des hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'pour cela, montagnes d\'Israël, écoutez la parole du Seigneur, l\'Éternel! Ainsi parle le Seigneur, l\'Éternel, aux montagnes et aux collines, aux vallées et aux vallons, et aux ruines désertes et aux villes abandonnées, qui sont devenues la proie et la risée des autres peuples d\'alentour:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'pour cela, ainsi parle le Seigneur, l\'Éternel: Oui, dans le feu de ma jalousie je menace les autres peuples et Édom tout entier, qui se sont adjugé la propriété de mon pays, dans toute la joie de leur cœur et l\'orgueil de leur âme, pour le dépouiller et en faire une proie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Aussi, adresse la prophétie au pays d\'Israël, et dis aux montagnes et aux collines, aux vallées et aux vallons: Ainsi parle le Seigneur, l\'Éternel: Voici, c\'est dans ma jalousie et ma fureur que je parle, parce que vous subissez l\'opprobre des nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Aussi, ainsi parle le Seigneur, l\'Éternel: De ma main levée je jure que ce sont les peuples qui vous entourent, eux, qui subiront leur opprobre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Mais vous, montagnes d\'Israël, vous pousserez vos rameaux, et porterez vos fruits pour mon peuple d\'Israël; car ces choses sont près d\'arriver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Car c\'est vous que j\'ai en vue, je me tournerai vers vous, afin que vous soyez cultivées et ensemencées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'et je mettrai sur vous des hommes en grand nombre, la maison d\'Israël tout entière; et les villes seront habitées, et les ruines relevées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'et je vous peuplerai d\'hommes et d\'animaux en grand nombre; ils se multiplieront et seront féconds; et je vous ferai habiter comme dans vos anciens temps, et vous montrerai plus de bonté que dans vos premiers jours, afin que vous sachiez que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Et je ferai marcher sur vous des hommes, mon peuple d\'Israël, et ils te posséderont, et tu seras leur héritage, et tu ne leur ôteras plus leurs enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Ainsi parle le Seigneur, l\'Éternel: Parce qu\'ils vous disent: « Tu as dévoré des hommes et privé ton peuple de ses enfants »,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'à cause de cela tu ne dévoreras plus d\'hommes, et ne priveras plus ton peuple de ses enfants, dit le Seigneur, l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'et je ne te ferai plus entendre les outrages des nations, et tu ne subiras plus l\'opprobre des peuples, et tu ne priveras plus ton peuple de ses enfants, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Fils de l\'homme, la maison d\'Israël habitait son pays, et elle l\'a souillé par sa conduite et par ses crimes, et sa conduite fut à mes yeux comme la souillure d\'une femme souillée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'et je versai ma colère sur eux à cause du sang qu\'ils avaient répandu dans le pays, et parce qu\'ils l\'avaient souillé par leurs idoles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Et je les dispersai parmi les peuples, et ils furent disséminés dans les pays divers; je les jugeai selon leur conduite et leurs crimes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Et ils arrivèrent chez les nations; mais partout où ils vinrent, ils y profanèrent, mon saint nom, en faisant dire d\'eux: « C\'est là le peuple de l\'Éternel, et il a quitté son pays. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Mais je sauverai l\'honneur de mon saint nom, qu\'a profané la maison d\'Israël parmi les peuples chez lesquels ils sont venus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Aussi, dis à la maison d\'Israël: Ainsi parle le Seigneur, l\'Éternel: Ce n\'est pas en vue de vous que je le ferai, maison d\'Israël, mais en vue de mon saint nom, que vous avez déshonoré parmi les peuples chez lesquels vous êtes venus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'et je sanctifierai mon grand nom qui a été déshonoré parmi les nations, que vous avez déshonoré au milieu d\'elles, afin que les nations sachent que je suis l\'Éternel, dit le Seigneur, l\'Éternel, quand je me montrerai saint envers vous sous vos yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Et je vous retirerai du milieu des nations, et vous rassemblerai de tous les pays, et vous ramènerai dans votre pays;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'et je répandrai sur vous une eau pure, afin que vous soyez purifiés; de toutes vos souillures et de toutes vos infamies je vous purifierai;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'et je vous donnerai un cœur nouveau, et mettrai un esprit nouveau au dedans de vous, et j\'ôterai de votre corps le cœur de pierre et vous donnerai un cœur de chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Et je mettrai mon Esprit au dedans de vous, et ferai que vous suiviez mes ordonnances, et gardiez et pratiquiez mes lois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'et vous habiterez le pays que j\'ai donné à vos pères, et vous serez mon peuple et je serai votre Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'et je vous délivrerai de toutes vos souillures, et ferai venir le blé, et le multiplierai, et ne vous enverrai point de famine,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'et je multiplierai les fruits des arbres et les productions de la terre, afin que pour cause de famine vous ne receviez plus d\'outrages parmi les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Alors vous vous rappellerez votre conduite mauvaise et vos œuvres qui n\'étaient pas bonnes, et vous aurez en vous-mêmes le dégoût de vos crimes et de vos infamies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Ce n\'est pas en vue de vous que je fais ces choses, dit le Seigneur, l\'Éternel. Sachez-le! Ayez honte et confusion de votre conduite, maison d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Ainsi parle le Seigneur, l\'Éternel: Quand je vous purifierai de tous vos crimes, alors je peuplerai vos villes, et les ruines se relèveront;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'et le pays désolé sera cultivé, au lieu d\'être un désert à la vue de tous les passants;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'et l\'on dira: Ce pays désolé est devenu comme le jardin d\'Éden, et ces villes ruinées et dévastées et détruites sont fortifiées et habitées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Et les peuples qui survivront autour de vous reconnaîtront que c\'est moi, l\'Éternel, qui aurai rebâti ce qui était démoli, et planté ce qui était dévasté. Moi, l\'Éternel, je l\'ai dit et je le ferai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Ainsi parle le Seigneur, l\'Éternel: Encore en ceci j\'exaucerai la maison d\'Israël, pour le leur faire: je les multiplierai comme un troupeau d\'hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Tel le troupeau des brebis consacrées, tel le troupeau de Jérusalem pendant ses solennités, ainsi leurs villes ruinées seront remplies de troupeaux d\'hommes, afin qu\'ils sachent que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'La main de l\'Éternel se fit sentir à moi, et l\'Éternel m\'emmena en esprit, et me déposa dans le milieu de la vallée. Or elle était remplie d\'ossements;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'et Il m\'en fit faire le tour, tout le tour, et voici, il y en avait beaucoup sur le sol de la vallée, et voici, ils étaient extrêmement secs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Et Il me dit: Fils de l\'homme, ces ossements reprendront-ils vie? Et je dis: Seigneur Éternel, c\'est toi qui le sais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Et Il me dit: Prophétise sur ces ossements et dis-leur: Ossements desséchés, entendez la parole de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Ainsi parle le Seigneur, l\'Éternel, à ces ossements: Voici, j\'introduirai en vous un esprit, afin que vous repreniez vie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'et je vous donnerai des nerfs, et ferai croître sur vous de la chair, et vous recouvrirai de peau, et je mettrai en vous un esprit, afin que vous repreniez vie, et que vous sachiez que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Et je prophétisai suivant l\'ordre qui m\'en était donné. Et pendant que je prophétisais, voici, il se fit un bruissement et une rumeur, et les os s\'assemblèrent, os avec os.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Et je regardai, et voici, il leur vint des nerfs, la chair crût, et une peau les recouvrit par dessus, mais un esprit ne les pénétrait pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Et Il me dit: Adresse la prophétie à l\'esprit; prophétise, fils de l\'homme, et dis à l\'esprit: Ainsi parle le Seigneur, l\'Éternel: Esprit, arrive des quatre vents, et pénètre ces morts, afin qu\'ils reprennent vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Et je prophétisai selon l\'ordre qui m\'était donné, et l\'esprit les pénétra et ils reprirent vie, et ils se tinrent sur leurs pieds; c\'était une grande, très grande multitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Et Il me dit: Fils de l\'homme, ces ossements, c\'est toute la maison d\'Israël. Voici, ils disent: « Nos ossements sont desséchés, et notre espoir s\'est évanoui, nous sommes anéantis! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Prophétise donc et dis-leur: Ainsi parle le Seigneur, l\'Éternel: Voici, j\'ouvrirai vos tombeaux et vous ferai sortir de vos tombeaux, ô mon peuple, et je vous ramènerai au pays d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'et vous reconnaîtrez que je suis l\'Éternel, quand j\'ouvrirai vos tombeaux, et que je vous ferai, ô mon peuple, sortir de vos tombeaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'et je mettrai mon esprit en vous, afin que vous repreniez vie, et je vous établirai dans votre pays, afin que vous reconnaissiez que c\'est moi, l\'Éternel, qui l\'aurai dit et fait, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'Toi, fils de l\'homme, prends une pièce de bois, et inscris-y: « Pour Juda et les enfants d\'Israël qui lui sont associés. » Prends encore une pièce de bois, et inscris-y: « Pour Joseph, bois d\'Éphraïm et de toute la maison d\'Israël qui lui est associée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Et rapproche-les l\'une de l\'autre pour en former une seule pièce, afin qu\'elles ne fassent qu\'un en ta main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Et quand les enfants de ton peuple te diront: « Ne nous expliqueras-tu pas ce que cela signifie? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'disleur: Ainsi parle le Seigneur, l\'Éternel: Voici, je prendrai le bois de Joseph qui est entre les mains d\'Éphraïm, et les tribus d\'Israël qui lui sont associées, et je l\'assemblerai avec lui, avec le bois de Juda, et j\'en formerai une seule pièce, afin qu\'ils ne fassent qu\'un en ma main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Et tu tiendras en ta main sous leurs yeux les pièces de bois où tu auras mis l\'inscription,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'et tu leur diras: Ainsi parle le Seigneur, l\'Éternel: Voici, je retirerai les enfants d\'Israël d\'entre les peuples au milieu desquels ils vivent, et je les rassemblerai de toutes parts, et les ramènerai dans leur pays;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'et je ferai d\'eux un seul peuple dans le pays, sur les montagnes d\'Israël; et un seul roi sera le roi d\'eux tous; et ils ne formeront plus deux peuples, et ne se diviseront plus en deux royaumes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'et ils ne se souilleront plus par leurs abominations, et leurs infamies, et tous leurs péchés; et je les délivrerai de toutes les demeures où ils ont péché, et je les purifierai; et ils seront mon peuple, et je serai leur Dieu:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'et mon serviteur David sera leur roi, et leur seul pasteur pour eux tous; et ils suivront mes lois et garderont mes commandements, et les pratiqueront;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'et ils habiteront le pays que j\'ai donné à mon serviteur Jacob, où vos pères ont habité, et où ils habiteront, eux et leurs enfants, et les enfants de leurs enfants, éternellement; et David mon serviteur sera leur prince éternellement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'et je leur donnerai une alliance de paix; c\'est une alliance éternelle qu\'ils auront; et je les établirai, et les ferai se multiplier, et fixerai mon sanctuaire au milieu d\'eux pour l\'éternité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'et je demeurerai avec eux, et je serai leur Dieu, et ils seront mon peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Et les nations reconnaîtront que je suis l\'Éternel qui sanctifie Israël, quand mon sanctuaire sera au milieu d\'eux pour l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Fils de l\'homme, tourne ton visage du côté de Gog, au pays de Magog, prince de Rosch, Mésech et Thubal, et prophétise contre lui');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'et dis: Ainsi parle le Seigneur, l\'Éternel: J\'en veux à toi, Gog, prince de Rosch, Mésech et Thubal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Je te détournerai, et mettrai un anneau à tes mâchoires, et t\'emmènerai, toi et toute ton armée, chevaux et cavaliers, tous vêtus magnifiquement, foule immense portant le pavois et le bouclier, tous maniant l\'épée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Perses, Éthiopiens et Libyens, avec eux, ayant tous le bouclier et le casque;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomer et tous ses bataillons, la maison de Thogarma venue du fond du nord avec tous ses bataillons, tout autant de peuples qui t\'accompagnent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Tiens-toi prêt et t\'équipe, toi et toutes les troupes qui sont attroupées autour de toi, et sois leur général!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Pendant un longtemps tu seras désiré; mais dans la suite des années tu viendras dans le pays, soustrait à l\'épée, où ses habitants auront été rassemblés du milieu de peuples nombreux, sur les montagnes d\'Israël longtemps désertes, dans le pays où les habitants auront été ramenés du milieu des peuples et dans lequel ils habiteront tous en sécurité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Et tu arriveras, tu fondras comme un ouragan, pareil à une nuée, pour couvrir le pays, toi et tous tes bataillons, et les peuples nombreux qui sont avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Ainsi parle le Seigneur, l\'Éternel: Dans ce temps-là, des pensées s\'élèveront dans ton cœur, et tu formeras de funestes projets');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'et tu diras: J\'envahirai le pays ouvert, je fondrai sur ces hommes paisibles, vivant tous dans la sécurité, habitant sans murailles, et n\'ayant ni verrous ni portes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'pour enlever du butin, et emporter des dépouilles, pour porter ta main sur des ruines de nouveau habitées, sur un peuple recueilli du milieu des peuples, qui s\'est remis au soin des troupeaux et au négoce, et habite les hauteurs du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Séba et Dedan et les marchands de Tarsis, et tous leurs hommes puissants te diront: « Est-ce pour enlever du butin que tu arrives? pour emporter des dépouilles que tu as réuni tes troupes? pour prendre de l\'argent et de l\'or, des troupeaux et des biens, pour faire un grand butin? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Aussi prophétise, fils de l\'homme, et dis à Gog: Ainsi parle le Seigneur, l\'Éternel: Voici, en ce jour-là, tandis que mon peuple d\'Israël vivra en sécurité, tu l\'auras vu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'et tu viendras de ta demeure, du fond du nord, toi et beaucoup de peuples avec toi, tous montés sur des chevaux, troupe nombreuse, armée immense,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'et tu t\'avanceras contre mon peuple d\'Israël comme une nuée pour couvrir le pays. Dans la suite des temps il arrivera que je t\'amènerai contre mon pays, afin que les nations me reconnaissent quand je donnerai sur toi une preuve de ma sainteté sous leurs yeux, ô Gog!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Ainsi parle le Seigneur, l\'Éternel: Est-ce toi dont j\'ai parlé aux jours d\'autrefois par mes serviteurs, les prophètes d\'Israël, qui dans ces temps ont prophétisé pendant des années que je t\'amènerai contre eux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Et il arrivera en ce jour-là, au jour que Gog fondra sur la terre d\'Israël, dit le Seigneur, l\'Éternel, que la colère me montera dans les narines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Et je le dis avec indignation et une ardente colère; dans ce jour il y aura un grand tremblement dans le pays d\'Israël:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'à ma présence trembleront les poissons de la mer, et les oiseaux des Cieux, et les bêtes des champs, et tous les reptiles qui rampent sur la terre, et tous les hommes qui seront dans le pays; et les montagnes s\'ébouleront, et les pics des rochers s\'écrouleront, et toutes les murailles s\'écrouleront jusqu\'en terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'et contre lui sur toutes mes montagnes j\'appellerai l\'épée, dit le Seigneur, l\'Éternel; ils croiseront l\'épée l\'un contre l\'autre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'et j\'exécuterai mes jugements sur lui par la peste et le carnage; et d\'une pluie d\'inondation et des pierres de la grêle, de feu et de soufre, je le couvrirai, lui et tous ses bataillons, et les peuples nombreux qui seront avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Et ainsi je manifesterai ma majesté et ma sainteté, et me révélerai aux yeux de beaucoup de nations, afin qu\'elles sachent que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Toi donc, fils de l\'homme, prophétise contre Gog et dis: Ainsi parle le Seigneur, l\'Éternel: J\'en veux à toi, Gog, prince de Rosch, Mésech et Thubal!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Je te détournerai et t\'entraînerai, et te tirerai du fond du nord, et t\'amènerai sur les montagnes d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Et j\'arracherai ton arc de ta main gauche, et ferai tomber tes flèches de ta main droite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'sur les montagnes d\'Israël tu succomberas, toi et tous tes bataillons, et les peuples qui sont avec toi; des vautours, de tous les oiseaux et des bêtes des champs je te ferai la pâture;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'sur la face de la terre tu tomberas, car j\'ai parlé, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Et je darderai un feu en Magog et sur ceux qui habitent les îles en sécurité, afin qu\'ils sachent que je suis l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Et je manifesterai mon saint nom au milieu de mon peuple d\'Israël, et n\'exposerai plus mon saint nom au déshonneur; mais les nations reconnaîtront que je suis l\'Éternel, le Saint d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Voici, il vient, il arrive, dit le Seigneur, l\'Éternel, ce jour que j\'ai dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Alors les habitants des villes d\'Israël sortiront et allumeront et brûleront les armes et les boucliers et les pavois, les arcs et les flèches, les épieux et les lances, et s\'en feront du feu pendant sept années.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Ils n\'iront point chercher du bois dans la campagne, ni en couper dans les forêts, car c\'est avec les armes qu\'ils nourriront leur feu: et ils dépouilleront ceux qui les auront dépouillés, et pilleront ceux qui les auront pillés, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'Et dans ce même jour je donnerai là à Gog un lieu pour son tombeau en Israël, la vallée des voyageurs, à l\'orient de la mer; et cela fermera le passage aux voyageurs; c\'est là qu\'on enterrera Gog et toute sa multitude, et on la nommera Vallée de la multitude de Gog.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Et la maison d\'Israël les enterrera, afin de purifier le pays, durant sept mois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'et tout le peuple du pays enterrera; et cela lui donnera un nom au jour où je me glorifierai, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Et ils choisiront des hommes en permanence dont les uns parcourront le pays, et les autres à leur suite enterreront les corps restés sur la face du pays, afin de le purifier; pendant sept mois entiers ils feront cette recherche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Et les premiers parcourront le pays; et si l\'un d\'eux aperçoit les ossements d\'un homme, il élèvera à côté un cippe, en attendant que les fossoyeurs l\'enterrent dans la vallée de la multitude de Gog.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Hamona sera aussi le nom d\'une ville. Et c\'est ainsi qu\'ils purifieront le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Or, fils de l\'homme, ainsi parle le Seigneur, l\'Éternel: Dis aux oiseaux, à tous les volatiles et à toutes les bêtes des champs: Rassemblez-vous et venez, réunissez-vous de toutes parts pour le sacrifice où je vais égorger des victimes pour vous, grand sacrifice sur les montagnes d\'Israël, et repaissez-vous de chair et abreuvez-vous de sang!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'C\'est de la chair des héros que vous y serez nourris, et du sang des princes de la terre que vous boirez; ce sont tout autant de béliers, d\'agneaux et de boucs, de taureaux engraissés en Basan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Et vous mangerez de la graisse, à vous rassasier, et vous boirez du sang, à vous enivrer, au sacrifice où pour vous j\'égorgerai des victimes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'et à ma table vous vous rassasierez de chevaux et de cavaliers, de héros et de toutes sortes d\'hommes de guerre, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Et je manifesterai ma gloire parmi les nations, et toutes les nations seront témoins du jugement que j\'exercerai, et des coups dont les frappera ma main;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'et toute la maison d\'Israël comprendra que moi, l\'Éternel, je suis son Dieu, dès ce jour-là et à l\'avenir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'et les nations comprendront que c\'est par suite de son crime que la maison d\'Israël a été déportée, parce qu\'ils furent coupables envers moi, et que je leur cachai ma face, et que je les livrai à la main de leurs ennemis, afin que par l\'épée ils périssent tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Je les ai traités selon leur souillure et leur désobéissance, et je leur ai caché ma face.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Aussi, ainsi parle le Seigneur, l\'Éternel: Maintenant je veux ramener les captifs de Jacob, et prendre pitié de toute la maison d\'Israël, et être jaloux de mon saint nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Alors ils comprendront quel fut leur opprobre et tout le crime qu\'ils ont commis contre moi, lorsqu\'ils habiteront leur pays en sécurité, sans terreur aucune,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'lorsque je les ramènerai du milieu des peuples, et les recueillerai des pays de leurs ennemis, et que je manifesterai ma sainteté sur eux au milieu de peuples nombreux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Alors ils reconnaîtront que moi, l\'Éternel, je suis leur Dieu, quand, après les avoir envoyés captifs aux nations, je les réunirai dans leur pays, sans laisser aucun d\'eux là au milieu d\'elles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'et je ne leur cacherai plus ma face, parce que j\'aurai répandu mon Esprit sur la maison d\'Israël, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'La vingt-cinquième année de notre déportation, au commencement de l\'année, le dixième jour du mois, quatorze ans après la ruine de la ville, en ce jour-là, la main de l\'Éternel se fit sentir à moi, et m\'y transporta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'Ce fut en vision divine qu\'il me transporta au pays d\'Israël, et me plaça sur une montagne très élevée, de laquelle [on voyait] comme une ville construite au midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Il m\'y transporta, et voici, il s\'y trouvait un homme dont l\'aspect était comme l\'aspect de l\'airain, et il avait en sa main un cordeau de lin et une perche à mesurer, et il se tenait à la porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Et l\'homme me dit: Fils de l\'homme, considère de tes yeux, et écoute de tes oreilles, et observe attentivement tout ce que je vais te montrer; car c\'est pour qu\'on te le montre, que tu as été transporté ici. Rapporte tout ce que tu verras à la maison d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Et voici, un mur régnait extérieurement autour de la maison, tout à l\'entour. Or l\'homme tenait en sa main une perche de six coudées, dont chacune était d\'une coudée et une palme. Et il mesura la largeur de cette construction; elle était d\'une perche, et la hauteur d\'une perche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Puis il vint à la porte qui donne à l\'orient, et en monta les degrés et mesura le seuil de la porte; il avait une perche en largeur; c\'était là l\'un des seuils; sa largeur était d\'une perche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'et chaque appartement avait une perche en longueur, et une perche en largeur; et entre les appartements il y avait cinq coudées; et le seuil intérieur de la porte à côté du vestibule de la porte avait une perche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Et il mesura le vestibule de la porte intérieurement; il avait une perche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Et il mesura le vestibule de la porte; il avait huit coudées, et ses piliers deux coudées; c\'était le vestibule de la porte en dedans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Quant aux appartements de la porte qui donnait à l\'orient, il y en avait trois d\'un côté et trois de l\'autre: ils étaient tous trois de la même dimension, et les piliers de l\'un et de l\'autre côté avaient la même dimension.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Puis il mesura la largeur de l\'ouverture de la porte; elle était de dix coudées; la longueur de la voie de la porte était de treize coudées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'et il y avait devant les appartements un bord d\'une coudée, et un bord d\'une coudée de l\'autre côté; et chaque appartement avait six coudées d\'un côté et six coudées de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Puis il mesura toute la porte depuis le toit d\'un appartement jusqu\'au toit de l\'autre, c\'était une largeur de vingt-cinq coudées entre les deux ouvertures opposées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'et il trouva pour les piliers soixante coudées; et près des piliers il y avait une cour, la porte étant tout autour;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'et depuis le devant de la porte d\'entrée jusqu\'au devant du vestibule de la porte intérieure il y avait cinquante coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Et il y avait aux appartements des fenêtres fermées, et à leurs piliers en dedans de la porte tout autour; et de même au vestibule il y avait des fenêtres tout autour intérieurement, et sur les piliers étaient [sculptés] des palmiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Alors il m\'introduisit dans le parvis extérieur; et voici, il y avait des chambres, et un pavé fait dans le parvis tout autour; il y avait trente chambres sur le pavé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Or le pavé était à côté des portes, parallèle à la longueur des portes, c\'était le pavé inférieur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Et il mesura extérieurement la largeur, depuis le devant de la porte inférieure jusqu\'au devant du parvis intérieur; c\'étaient cent coudées à l\'orient et au nord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Il mesura aussi en longueur et en largeur la porte qui donnait au nord, dans le parvis extérieur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'et ses appartements dont il y avait trois d\'un côté et trois de l\'autre. Et ses piliers et ses vestibules avaient la dimension de la première porte; sa longueur cinquante coudées, et sa largeur vingt-cinq coudées:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'et ses fenêtres, et son vestibule, et ses palmiers avaient les mêmes dimensions qu\'à la porte de l\'orient; et on y montait par sept degrés, et son vestibule était en dedans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Et il y avait une porte au parvis intérieur, vis-à-vis de la porte du nord et de l\'orient; et il mesura d\'une porte à l\'autre porte cent coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Ensuite il me conduisit au midi; et voici, il y avait une porte au midi: et il mesura ses piliers et ses vestibules; c\'étaient les mêmes dimensions;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'et elle avait, ainsi que son vestibule, des fenêtres de tous côtés, pareilles aux autres fenêtres; la longueur était de cinquante coudées, et la largeur de vingt-cinq coudées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'et sept marches formaient son escalier, et son vestibule était en dedans; il y avait aussi des palmiers, un d\'un côté et un de l\'autre, à ses piliers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Et le parvis intérieur avait une porte du côté du midi. Et il mesura d\'une porte à l\'autre porte au côté du midi cent coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Ensuite il m\'introduisit dans le parvis intérieur par la porte du midi; et il trouva à la porte du midi les mêmes dimensions,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'et à ses appartements et à ses piliers et à ses vestibules les mêmes dimensions. Elle avait, ainsi que son vestibule, des fenêtres tout autour; la longueur était de cinquante coudées et la largeur de vingt-cinq coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, '(Et il y avait tout autour un vestibule de vingt-cinq coudées en longueur et de cinq de largeur.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Or son vestibule était du côté du parvis extérieur, et ses piliers avaient des palmiers, et huit marches formaient son escalier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Alors il m\'introduisit dans le parvis intérieur du côté de l\'orient, et il trouva à cette porte les mêmes dimensions,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'et à ses appartements et à ses piliers et à ses vestibules les mêmes dimensions; et elle avait, ainsi que son vestibule, des fenêtres tout autour; la longueur était de cinquante coudées, et la largeur de vingt-cinq coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Or son vestibule était du côté du parvis extérieur, et il y avait des palmiers sur ses piliers d\'un côté et de l\'autre, et huit marches formaient son escalier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Puis il m\'introduisit dans la porte du nord, et il trouva les mêmes dimensions,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'à ses appartements, à ses piliers et à ses vestibules, et elle avait des fenêtres de tous côtés; la longueur était de cinquante coudées, et la largeur de vingt-cinq coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Or son vestibule était du côté du parvis extérieur, et il y avait des palmiers à ses piliers d\'un côté et de l\'autre, et huit marches formaient son escalier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Or il y avait une chambre avec sa porte entre les piliers aux portes; c\'est là qu\'on devait laver les holocaustes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'Et dans le vestibule de la porte se trouvaient deux tables d\'un côté, et deux tables de l\'autre, pour y égorger l\'holocauste et les victimes pour le péché et pour le délit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'De plus, au côté extérieur, près de l\'escalier qui montait à l\'ouverture de la porte du nord, il y avait deux tables, et à l\'autre côté qui appartenait au vestibule de la porte, il y avait deux tables:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'quatre tables de ci et quatre tables de là, à côté de la porte; en tout huit tables, où l\'on devait égorger les victimes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Il y avait aussi quatre tables à l\'escalier, de pierre de taille, longues d\'une coudée et demie, et larges d\'une coudée et demie, et hautes d\'une coudée: on y devait déposer les instruments avec lesquels on égorge les holocaustes et les autres victimes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'et des crochets larges d\'une palme étaient fixés au dedans de la maison de toutes parts; et les tables devaient recevoir la chair des sacrifices.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Et en dehors de la porte intérieure il y avait des chambres pour les chantres dans le parvis intérieur, elles étaient à côté de la porte du nord, ayant leur façade au midi, et une autre à côté de la porte de l\'orient, ayant sa façade au nord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Alors il me dit: « Cette chambre dont la façade est au midi, est pour les prêtres chargés du service de la maison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'et la chambre dont la façade est au nord, est pour les prêtres chargés du service de l\'autel. Ce sont les enfants de Tsadok qui entre les enfants de Lévi auront accès auprès de l\'Éternel pour le servir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, '– Alors il mesura le parvis qui avait en longueur cent coudées et en largeur cent coudées, en carré. Or l\'autel était devant la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Alors il me conduisit au vestibule de la maison, et il mesura les piliers de ce vestibule: il y avait cinq coudées d\'un côté et cinq coudées de l\'autre. Et la largeur de la porte était de trois coudées d\'un côté et trois coudées de l\'autre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'la longueur du vestibule était de vingt coudées, et la largeur de onze coudées, et on y montait par des degrés; et il y avait des colonnes près des piliers, l\'une d\'un côté, l\'autre de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Alors il m\'introduisit dans le temple même, et il mesura les piliers; il y avait six coudées de largeur d\'un côté, et six coudées de largeur de l\'autre, largeur du tabernacle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Et la largeur de la porte était de dix coudées, et entre les panneaux de la porte il y avait cinq coudées d\'un côté, et cinq coudées de l\'autre. Et il mesura sa longueur qui était de quarante coudées, et la largeur de vingt coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Puis il entra dans l\'intérieur, et il mesura les piliers de la porte, deux coudées, et l\'ouverture six coudées, et la largeur de la porte sept coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Et il mesura vingt coudées en longueur et vingt coudées en largeur, devant le temple, et il me dit: C\'est ici le lieu très saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Alors il mesura le mur de la maison; il avait six coudées, et la largeur des chambres latérales régnant tout autour de la maison était de quatre coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Quant aux chambres latérales, elles étaient à côté les unes des autres; il y en avait trente, et trois étages, et elles entraient dans un mur construit intérieurement pour ces chambres, afin qu\'elles fussent adhérentes et non inhérentes au mur de la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Or l\'espace qui régnait tout autour s\'élargissait de plus en plus en s\'élevant avec les chambres, car un escalier tournant s\'élevait en suivant les contours intérieurs de la maison, de manière que la maison allait s\'élargissant à mesure qu\'on s\'élevait; et ainsi, de l\'étage inférieur on montait à l\'étage supérieur par celui du milieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Puis je considérai la hauteur intérieure tout autour; les fondements des chambres latérales avaient une perche entière, six coudées jusqu\'à la jonction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'La largeur du mur extérieur aux chambres latérales était de cinq coudées, et le vide entre les chambres latérales de la maison');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'et les chambres, avait vingt coudées de largeur tout autour de la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Or la porte des chambres latérales s\'ouvrait sur l\'espace libre: il y avait une porte au nord et une porte au midi, et la largeur de l\'espace libre était de cinq coudées tout autour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Ainsi l\'édifice placé sur le devant de l\'aire fermée avait, du côté de l\'occident, une largeur de soixante-dix coudées, et le mur de l\'édifice avait tout autour une largeur de cinq coudées, et sa longueur était de quatre-vingt-dix coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Et il mesura la maison: sa longueur était de cent coudées, et l\'aire fermée, avec ses constructions et ses murailles, avait cent coudées de longueur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'et la largeur du front de la maison et de l\'aire fermée était, du côté de l\'orient, de cent coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Et il mesura la longueur de l\'édifice devant l\'aire fermée, ce qui était sur son côté de derrière, et les chambres latérales de l\'un et de l\'autre côté; elle était de cent coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'Et le temple intérieur et son vestibule extérieur, les seuils et les fenêtres fermées, et les appartements latéraux du pourtour, à tous les trois étages, parallèlement au seuil, étaient recouverts de bois tout autour. Et du sol jusqu\'aux fenêtres, savoir aux fenêtres cachées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'au-dessus de la porte et jusque dans l\'intérieur de la maison, et en dehors, et à toutes les parois tout autour, à l\'intérieur et à l\'extérieur, les dimensions étaient exactes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Et on y avait sculpté des Chérubins et des palmiers, un palmier entre deux Chérubins, et chaque Chérubin avait deux faces,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'c\'est-à-dire une face d\'homme tournée vers l\'un des palmiers d\'un côté, et une face de lion tournée vers l\'autre palmier de l\'autre côté; c\'est ce qui avait été fait tout autour de la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Du sol jusqu\'au-dessus de la porte, des Chérubins et des palmiers avaient été faits au mur du temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Les jambages du temple étaient de forme carrée, et la façade du sanctuaire avait l\'aspect qu\'elle avait eu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'L\'autel était de bois, de trois coudées en hauteur et de deux coudées en longueur, et ses angles, son piédestal, et ses parois étaient de bois; et il me dit: « C\'est la table dressée devant l\'Éternel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Et le temple et le sanctuaire avaient deux portes; et');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'ces deux portes avaient deux battants mobiles; une porte avait deux battants, et l\'autre aussi deux battants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Et on y avait fait, aux portes du temple, des Chérubins et des palmiers, tels que ceux qui avaient été faits au mur, et un seuil en bois était devant le vestibule en dehors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Et il y avait des fenêtres fermées et des palmiers d\'un côté et de l\'autre aux parois latérales du vestibule, et aux chambres latérales de la maison et à leurs poutres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Alors il m\'emmena au parvis extérieur par le chemin du nord, et me conduisit aux chambres qui étaient vis-à-vis de l\'aire fermée et vis-à-vis de l\'édifice, au nord,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'là où à la porte du nord il y avait une longueur de cent coudées, et une largeur de cinquante coudées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'vis-à-vis des vingt du parvis intérieur, et vis-à-vis du pavé du parvis extérieur, où les appartements étaient contigus en trois étages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Or, devant les chambres, il y avait une allée de dix coudées de largeur, et une voie d\'une coudée menait à l\'intérieur, et leurs portes donnaient au nord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Et les chambres supérieures étaient plus étroites (car les appartements latéraux leur enlevaient de la place) que les inférieures et celles du milieu de l\'édifice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Car elles avaient bien trois étages, mais elles n\'avaient point de colonnes, comme les colonnes des parvis; aussi elles auraient occupé sur le sol un espace moins grand que celles du bas et du milieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Et le mur qui régnait extérieurement le long des chambres, du côté du parvis extérieur au devant des chambres, avait cinquante coudées de longueur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'car la longueur de ces chambres tournées vers le parvis extérieur était de cinquante coudées, mais du côté du temple, elle était de cent coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Et au-dessous de ces chambres était l\'entrée de l\'orient, quand on y venait du parvis extérieur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Dans la largeur du mur du parvis du côté de l\'orient, devant l\'aire fermée, et au front de l\'édifice, il y avait aussi des chambres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Et devant elles il y avait une allée. Elles étaient semblables aux chambres qui donnaient au nord; c\'était la même longueur, la même largeur; et toutes leurs issues, et leur disposition et leurs portes étaient semblables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Telles étaient aussi les portes des chambres situées au midi; il y avait une porte à l\'entrée de l\'allée, une allée en face du mur construit du côté de l\'orient, par où on y entrait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Et il me dit: « Les chambres du nord, les chambres du midi, qui sont devant l\'aire fermée, sont des loges saintes où les prêtres mangeront les choses très saintes, quand ils s\'approcheront de l\'Éternel; là ils déposeront les choses très saintes, savoir les offrandes et les victimes pour le péché et pour le délit, car le lieu est saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Quand les prêtres entreront, ils ne devront pas passer du sanctuaire dans le parvis extérieur, mais déposer là les vêtements avec lesquels ils feront le service, car ils sont saints; ils devront revêtir d\'autres habits et ainsi s\'approcher de ce qui est du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Après avoir terminé la mesure de la maison intérieure, il m\'emmena par le chemin de la porte qui donne à l\'orient, et mesura le pourtour de la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Il mesura le côté oriental avec la perche, il y avait cinq cents perches à l\'entour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Il mesura à la perche le côté du nord, il y avait cinq cents perches à l\'entour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Il mesura aussi le côté du midi, il y avait cinq cents perches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Il se tourna du côté de l\'occident, et mesura à la perche cinq cents perches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Il mesura la maison aux quatre vents; elle était entourée d\'un mur long de cinq cents, et large de cinq cents, pour séparer le sacré du profane.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Et il me conduisit à la porte, à la porte qui donnait à l\'orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Et voici, la gloire du Dieu d\'Israël s\'avançait de l\'orient, et son retentissement était comme le retentissement des grandes eaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'et la terre était éclairée de sa splendeur. Et c\'était un aspect comme celui de la vision que j\'avais eue, comme la vision que j\'avais eue, lorsque je vins annoncer la ruine de la ville, et c\'était une vision pareille à celle que j\'avais eue près du fleuve Chébar. Et je tombai sur mon visage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Et la gloire de l\'Éternel entra dans la maison par la porte qui donnait à l\'orient,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'et l\'Esprit me souleva et me transporta dans le parvis intérieur, et voici, la gloire de l\'Éternel remplissait la maison;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'et j\'entendis quelqu\'un qui me parlait depuis la maison, et un homme se tenait à côté de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Et Il me dit: Fils de l\'homme, c\'est ici la place de mon trône, et la place de la plante de mes pieds, où je résiderai parmi les enfants d\'Israël, éternellement. Et la maison d\'Israël ne déshonorera plus mon saint nom, ni eux, ni leurs rois, par leur impudicité, et par les cadavres de leurs rois sur leurs tertres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'quand ils mettaient leurs seuils à côté de mon seuil et leurs portes près de mes portes, tandis qu\'il y a un mur entre moi et eux; et ainsi, ils souillèrent mon saint nom par les abominations qu\'ils commirent; c\'est pourquoi je les ai détruits dans ma colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Maintenant leur impudicité et les cadavres de leurs rois demeureront loin de moi, et j\'habiterai au milieu d\'eux éternellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Or toi, fils de l\'homme, montre à la maison d\'Israël cette maison, afin qu\'ils rougissent de leurs crimes, et qu\'ils mesurent l\'édifice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Et s\'ils rougissent de tout ce qu\'ils ont fait, expose-leur le plan de cette maison, et sa disposition, et ses issues et ses entrées, et toute sa disposition et toutes ses règles, et toute sa disposition et toutes ses lois, et mets-en sous leurs yeux la description, afin qu\'ils retiennent son plan dans son entier, et toutes ses règles, et qu\'ils s\'y conforment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Telle est la loi de la maison. Sur le sommet de la montagne, dans toute l\'étendue de son enceinte, que tout soit un lieu très saint. Voici, c\'est là la loi de la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Et voici les mesures de l\'autel en coudées, la coudée d\'une coudée et une palme: le foyer une coudée, et une coudée de largeur; et le rebord qui terminait son contour avait un empan de largeur; tel est le support de l\'autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Et depuis la base de terre jusqu\'à la première partie rentrante il y aura deux coudées, et une coudée de largeur; et depuis cette partie rentrante qui est plus petite, jusqu\'à la plus grande, il y aura quatre coudées, et en largeur une coudée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Et le harel aura quatre coudées, et au-dessus de l\'ariel seront les quatre cornes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'et l\'ariel aura douze coudées de longueur sur douze coudées de largeur, en carré, et à ses quatre côtés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Et la partie rentrante [supérieure] aura quatorze coudées de longueur sur quatorze coudées de largeur à ses quatre côtés, et le rebord qui terminera son contour aura une demi-coudée, et sa base sera d\'une coudée tout autour, et son escalier tourné à l\'orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Et il me dit: Fils de l\'homme, ainsi parle le Seigneur, l\'Éternel: Ce sont les règlements de l\'autel pour le temps où on le fera, afin d\'y sacrifier les holocaustes, et d\'y répandre le sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Aux prêtres, aux lévites de la race de Tsadok, qui s\'approchent de moi pour me servir, dit le Seigneur, l\'Éternel, tu donneras un jeune taureau comme victime pour le péché,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'et tu prendras de son sang, et tu l\'en teindras à ses quatre cornes, et aux quatre angles de la partie rentrante, et au rebord qui l\'entoure, et ainsi tu en feras la purification et l\'expiation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Et tu prendras le taureau expiatoire, et le brûleras dans un lieu déterminé de la maison en dehors du sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Et le second jour, tu offriras un bouc sans défaut en expiation du péché, et on fera l\'expiation de l\'autel, comme on l\'aura faite avec le taureau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Et quand tu auras terminé l\'expiation, tu offriras un jeune taureau sans défaut, et un bélier du troupeau, sans défaut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'et tu les offriras à l\'Éternel; et les prêtres répandront du sel sur eux et les offriront en holocauste à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Pendant sept jours tu sacrifieras journellement un bouc comme victime expiatoire; et ils sacrifieront un jeune taureau et un bélier du troupeau sans défaut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Pendant sept jours ils feront l\'expiation de l\'autel, et sa purification et sa consécration:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'et ces jours étant accomplis, le huitième jour et dès lors les prêtres offriront sur l\'autel vos holocaustes et vos offrandes, et je vous recevrai favorablement, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Ensuite il me ramena vers la porte extérieure du sanctuaire, qui donne à l\'orient;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'or, elle était fermée. Et l\'Éternel me dit: Cette porte doit demeurer fermée, et ne point s\'ouvrir, et personne ne doit entrer par là, car l\'Éternel, le Dieu d\'Israël, est entré par là; c\'est pourquoi elle doit être fermée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Le prince, parce qu\'il est prince, s\'y placera pour manger le pain devant l\'Éternel; il entrera par la porte qui conduit au vestibule, et sortira par le même chemin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Alors il me conduisit par le chemin de la porte du nord, devant la maison, et je regardai, et voici, la gloire de l\'Éternel remplissait la maison de l\'Éternel, et je tombai sur mon visage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Et l\'Éternel me dit: Fils de l\'homme, sois attentif, et regarde de tes yeux et écoute de tes oreilles tout ce que je te dirai sur toutes les règles de la maison de l\'Éternel, et sur toutes ses lois; et sois attentif à l\'entrée de la maison et à toutes les issues du sanctuaire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'et dis à la rebelle maison d\'Israël: Ainsi parle le Seigneur, l\'Éternel: Qu\'il vous suffise de toutes vos abominations, maison d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'vous qui avez laissé pénétrer dans mon sanctuaire des étrangers incirconcis de cœur et incirconcis de corps, pour la profaner, ma maison; vous qui avez offert mon pain, la graisse et le sang, rompant ainsi mon alliance, à toutes vos abominations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Et vous n\'avez pas fait vous-mêmes le service de mes sanctuaires, mais vous vous en êtes substitué d\'autres pour faire le service dans mon sanctuaire à votre place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Ainsi parle le Seigneur, l\'Éternel: Aucun étranger incirconcis de cœur et incirconcis de chair, ne doit entrer dans mon sanctuaire, de tous les étrangers qui sont au milieu des enfants d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'bien plus, les lévites qui m\'ont déserté, quand s\'égarait Israël qui s\'éloigna de moi pour suivre ses idoles, porteront la peine de leur crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Ils serviront dans mon sanctuaire comme gardes aux portes de la maison, et serviront dans la maison même: ils égorgeront pour le peuple les holocaustes et les autres victimes, et seront à leur disposition pour les servir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Parce qu\'ils les ont servis devant leurs idoles, et qu\'ils ont été pour la maison d\'Israël une occasion de tomber dans le crime, c\'est pourquoi je lève ma main sur eux, dit le Seigneur, l\'Éternel, afin qu\'ils portent la peine de leur crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Et ils n\'auront point accès auprès de moi pour être mes prêtres et s\'approcher de mes sanctuaires, de mes lieux très saints; mais ils subiront leur opprobre et la peine des abominations qu\'ils ont commises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'C\'est ainsi que je les destine à être gardes de la maison, et à faire tout son service et tout ce qui doit y être fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Mais les prêtres, les lévites, enfants de Tsadok, qui ont fait le service de mon sanctuaire, quand les enfants d\'Israël me désertèrent, eux ils auront accès auprès de moi, pour me servir, et ils se tiendront devant moi pour m\'offrir la graisse et le sang, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Eux, ils entreront dans mon sanctuaire, eux ils s\'approcheront de ma table pour me servir, et s\'occuper de mon service.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Et quand ils passeront les portes du parvis intérieur, ils prendront des habits de lin; et il ne devra point y avoir de laine sur eux, pendant qu\'ils feront le service dans les portes du parvis intérieur et dans la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Ils auront sur la tête des tiares de lin, et à la ceinture des caleçons de lin; ils ne se ceindront point étant en sueur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Et quand ils passeront dans le parvis extérieur, dans le parvis extérieur qui est pour le peuple, ils se dépouilleront des vêtements qu\'ils portaient pendant leur service, et les déposeront dans les chambres du sanctuaire, et ils prendront d\'autres vêtements, afin qu\'ils ne sanctifient pas le peuple par leurs vêtements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Ils ne devront ni se raser la tête, ni laisser croître leur chevelure, ils porteront les cheveux coupés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Et aucun prêtre ne boira de vin quand il devra entrer dans le parvis intérieur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'ils ne prendront pour femme ni une veuve, ni une femme répudiée, mais des vierges de la race de la maison d\'Israël; mais ils pourront prendre la veuve qui est veuve d\'un prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Et ils instruiront mon peuple, lui montreront la différence du sacré et du profane, et de ce qui est immonde et de ce qui est pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Et dans les procès ils seront juges; ils jugeront d\'après mes lois. Et ils observeront mes commandements et mes ordonnances à toutes mes fêtes, et sanctifieront mes sabbats.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Et ils ne s\'approcheront d\'aucun mort pour se souiller; ce ne sera que pour un père et une mère, et un fils et une fille, et un frère et une sœur qui n\'a pas encore de mari, qu\'ils pourront se souiller.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Et après sa purification on lui comptera encore sept jours,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'et le jour où il entrera dans le sanctuaire, dans le parvis intérieur pour servir dans le sanctuaire, il offrira son sacrifice pour le péché, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Leur propriété consistera en ce que je suis leur propriété; vous ne leur donnerez aucune possession en Israël: je suis leur possession.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Ils mangeront l\'offrande et la victime pour le péché, et la victime pour le délit, et tout ce qu\'on aura sacré en Israël leur appartiendra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Et les prémices de toutes les primeurs, et tout ce qu\'on élève comme offrande, de quoi que ce soit, appartiendront aux prêtres, et vous donnerez au prêtre les prémices de votre farine, afin que la bénédiction repose sur ta maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Les prêtres ne mangeront ni oiseau ni animal morts ou déchirés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Et quand vous partagerez au sort le pays par héritages, vous prélèverez sur le pays pour l\'Éternel une portion qui sera sainte, et qui aura en longueur vingt-cinq mille [perches] et en largeur dix mille; elle sera sainte dans toute son étendue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'De ce nombre il sera pris pour le sanctuaire cinq cents sur cinq cents en carré, et on y ajoutera tout autour un espace libre de cinquante coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Et sur cette mesure tu mesureras en longueur vingt-cinq mille et en largeur dix mille, et ce sera le sanctuaire, le lieu très saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'C\'est la portion sainte du pays: elle appartiendra aux prêtres, serviteurs du sanctuaire, qui s\'approchent pour servir l\'Éternel; et ce sera l\'emplacement pour leurs maisons, et un sanctuaire pour le sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Et vingt-cinq mille [perches] en longueur et dix mille en largeur appartiendront en propriété aux lévites, serviteurs de la maison, avec vingt chambres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Et vous donnerez en propriété à la ville cinq mille en largeur, et vingt-cinq mille en longueur, parallèlement à la portion sainte; cela appartiendra à toute la maison d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Et au prince vous donnerez en deçà et en delà de la portion sainte et de la propriété de la ville, le long de la portion sainte et le long de la propriété de la ville, au côté de l\'occident vers l\'occident, et au côté de l\'orient vers l\'orient, la longueur d\'une portion de tribu, depuis la limite de l\'occident jusqu\'à la limite de l\'orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Ce sera son domaine, sa propriété en Israël, afin que mes princes n\'oppriment plus mon peuple, mais laissent le pays à la maison d\'Israël selon ses tribus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Ainsi parle le Seigneur, l\'Éternel: C\'est assez, princes d\'Israël! renoncez à la violence et à l\'oppression, faites droit et justice, et délivrez mon peuple de vos exactions, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Ayez une balance juste, un épha juste, et un bath juste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'L\'épha et le bath seront une seule et même mesure, de sorte que le bath contiendra la dixième partie du homer, et l\'épha la dixième partie du homer; la mesure en sera réglée d\'après le homer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Et le sicle sera de vingt géras. Vingt sicles, vingt-cinq sicles, quinze sicles formeront chez vous la mine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Voici la part que vous, prélèverez [pour le prince]: la sixième partie de l\'épha sur un homer de froment, et la sixième partie de l\'épha sur un homer d\'orge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'La redevance sur l\'huile, sur le bath d\'huile, est d\'un dixième de bath sur le cor, à dix baths pour un homer, car dix baths font un homer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Et une brebis du troupeau, prise sur deux cents dans les pâturages bien arrosés d\'Israël, sera l\'offrande, et l\'holocauste, et le sacrifice d\'actions de grâces, et leur expiation, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Tout le peuple du pays sera tenu à cette offrande envers le prince d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Et le prince sera chargé des holocaustes, des offrandes et des libations aux fêtes, et aux nouvelles lunes, et aux jours de sabbat, à toutes les solennités de la maison d\'Israël: il offrira la victime pour le péché, et l\'offrande, et l\'holocauste, et le sacrifice d\'actions de grâces, pour faire l\'expiation en faveur de la maison d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Ainsi parle le Seigneur, l\'Éternel: Au premier mois, le premier jour du mois, tu prendras un jeune taureau sans défaut, afin de faire l\'expiation pour le sanctuaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Et le sacrificateur prendra du sang de la victime pour le péché, et en mettra aux jambages de la maison, et aux quatre angles de la partie rentrante de l\'autel, et aux jambages de la porte du parvis intérieur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Et tu en feras autant le septième jour du mois, à cause de ceux qui auront péché par méprise ou par ignorance: et c\'est ainsi que vous ferez l\'expiation pour la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Le premier mois, le quatorzième jour du mois, vous célébrerez la Pâque, la fête des sept jours; vous mangerez des pains sans levain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Et ce jour-là, le prince offrira pour lui et pour tout le peuple du pays un taureau en sacrifice pour le péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Et durant les sept jours de la fête il offrira à l\'Éternel un holocauste, sept taureaux et sept béliers sans défaut, chacun des sept jours, et une victime pour le péché, un bouc, chaque jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Et pour offrande il présentera un épha pour chaque taureau et un épha pour chaque bélier, et un hin d\'huile par épha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Au septième mois, le quinzième jour du mois, à la fête, il offrira les mêmes sacrifices durant sept jours, tant pour le sacrifice pour le péché que pour l\'holocauste et l\'offrande et l\'huile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Ainsi parle le Seigneur, l\'Éternel: La porte du parvis intérieur qui donne à l\'orient, demeurera fermée pendant les six jours ouvrables; mais au jour du sabbat elle s\'ouvrira, et au jour de la nouvelle lune, elle s\'ouvrira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Et le prince entrera de dehors par le vestibule de la porte, et s\'arrêtera devant les jambages de la porte; et les prêtres offriront son holocauste, et son sacrifice d\'actions de grâces; et il adorera sur le seuil de la porte, puis il se retirera. Cependant la porte ne sera pas fermée avant le soir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'et le peuple du pays adorera à l\'entrée de la même porte aux jours de sabbat et de nouvelles lunes en présence de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Et l\'holocauste que le prince aura à offrir à l\'Éternel sera, le jour du sabbat, six brebis sans défaut, et un bélier sans défaut;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'et son offrande, un épha par bélier, et par brebis une offrande telle qu\'il pourra la donner, et en huile un hin par épha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Et au jour de la nouvelle lune, un jeune taureau sans défaut, et six brebis et un bélier qui devront être sans défaut;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'et un épha par taureau, et un épha par bélier; c\'est ce qu\'il présentera comme offrande; et par brebis ce qu\'il pourra donner, et en huile un hin par épha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Et quand le prince entrera, il entrera par le chemin du vestibule de la porte, et il sortira par le même chemin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Et quand le peuple du pays se présentera devant l\'Éternel aux solennités, celui qui entrera par la porte du nord pour adorer, sortira par la porte du midi, et celui qui entrera par la porte du midi, sortira par la porte du nord. L\'on ne doit point se retirer par la porte par laquelle on est entré, mais on sortira en marchant toujours devant soi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Et le prince entrera parmi eux, quand ils entreront, et en sortant ils sortiront ensemble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Et aux fêtes et aux solennités l\'offrande sera un épha par taureau et un épha par bélier, et par brebis ce qu\'il pourra donner, et en huile un hin par épha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Que si le prince offre à l\'Éternel un holocauste volontaire ou un sacrifice volontaire d\'actions de grâces, on lui ouvrira la porte qui donne à l\'orient, et il présentera son holocauste et son sacrifice d\'actions de grâces comme il le fera au jour du sabbat. Et quand il sera sorti, on fermera la porte après sa sortie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Journellement tu offriras à l\'Éternel en holocauste un agneau d\'un an sans défaut; tu l\'offriras tous les matins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Et tu y ajouteras tous les matins une offrande, la sixième partie d\'un épha, et en huile le tiers d\'un hin pour humecter la farine, en offrande à l\'Éternel: que ce soit une règle éternelle et constante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Et offrez la brebis et l\'offrande et l\'huile tous les matins, comme holocauste perpétuel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Ainsi parle le Seigneur, l\'Éternel: Si le prince fait à l\'un de ses fils un don, c\'est sa propriété, il appartiendra à ses fils; ce sera leur propriété héréditaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Mais si de son patrimoine il fait un don à l\'un de ses serviteurs, ce don appartiendra à celui-ci jusqu\'à l\'année d\'affranchissement, puis il reviendra au prince: à ses fils seuls appartient son patrimoine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Et le prince ne prendra rien de l\'héritage du peuple, de manière à l\'exproprier; mais c\'est de son propre patrimoine qu\'il pourra faire des legs à ses fils, afin qu\'aucun homme de mon peuple ne soit expulsé de sa propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Alors il m\'introduisit par l\'entrée latérale de la porte dans les chambres saintes réservées aux prêtres et donnant au nord, et voici, il y avait au fond un lieu du côté de l\'occident.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Et il me dit: C\'est ici le lieu où les prêtres feront cuire les victimes pour le délit et pour le péché, et où ils boulangeront les offrandes, de peur qu\'en portant ces choses dans le parvis extérieur, ils ne sanctifient le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Puis il m\'emmena dans le parvis extérieur et me fit passer aux quatre angles du parvis, et voici, il y avait une cour à chaque angle du parvis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Aux quatre angles du parvis étaient des cours découvertes, de quarante coudées de longueur et de trente de largeur; toutes quatre elles avaient les mêmes dimensions aux angles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Et toutes quatre elles avaient un mur d\'enceinte, et au pied du mur tout autour on avait pratiqué des âtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Et il me dit: C\'est là la cuisine où les servants de la maison feront cuire les victimes du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Ensuite il me ramena à la porte de la maison: et voici, de l\'eau jaillissait sous le seuil de la maison du côté de l\'orient, car la façade de la maison était tournée à l\'orient; et l\'eau descendait par dessous le côté droit de la maison au midi de l\'autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Et il m\'emmena par la porte du nord, et il me fit traverser en dehors jusqu\'à la porte extérieure par le chemin qui avait la direction de l\'orient, et voici, l\'eau jaillissait du côté droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Quand l\'homme sortit du côté de l\'orient, il avait un cordeau en sa main, et il mesura mille coudées, et il me fit traverser l\'eau, et l\'eau me mouillait les extrémités.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Puis il mesura mille coudées et me fit traverser l\'eau, et j\'avais de l\'eau jusqu\'aux genoux. Ensuite il mesura mille coudées, et me fit traverser, et j\'avais de l\'eau jusqu\'aux reins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Et il mesura encore mille coudées; c\'était une rivière que je ne pouvais traverser, car l\'eau était profonde; c\'était une eau où l\'on pouvait nager, un torrent que l\'on ne pouvait passer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Et il me dit: As-tu vu, fils de l\'homme? et il me ramena au bord de la rivière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Y étant revenu, je vis sur le bord de la rivière des arbres en très grand nombre d\'un côté et de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Et il me dit: Cette eau s\'écoulera du côté du canton oriental, descendra dans la plaine et se jettera dans la mer: c\'est dans la mer qu\'elle se jettera, et les eaux de la mer seront rendues saines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Et toutes les espèces des êtres animés qui se meuvent, vivront partout où coulera la rivière; et il y aura des poissons en très grand nombre; car si cette eau arrive quelque part, tout sera sain et vivant partout où pénétrera la rivière:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'et des pêcheurs s\'y tiendront, d\'En-Gueddi à En-Eglaïm étendant leurs filets; il y aura des poissons d\'espèces diverses, pareils aux poissons de la grande mer et en très grand nombre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Ses marais et ses lagunes ne seront point assainis; ils sont abandonnés au sel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Et sur la rivière, sur ses bords de part et d\'autre, croîtront toutes sortes d\'arbres fruitiers; leur feuillage ne se flétrira point, et leurs fruits ne s\'épuiseront point; tous les mois ils mûriront, parce que leurs eaux sortiront du sanctuaire; et leurs fruits seront une nourriture, et leurs feuilles un médicament.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Ainsi parle le Seigneur, l\'Éternel: Voici les limites d\'après lesquelles vous partagerez le pays entre les douze tribus d\'Israël: pour Joseph, deux parts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'd\'ailleurs vos lots seront égaux pour l\'un comme pour l\'autre. Car de ma main levée j\'ai juré de le donner à vos pères, et ce pays vous est dévolu en héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Or, voici la frontière du pays: Au nord, depuis la grande mer, le chemin de Hethlon jusqu\'à Tsédad,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Hamath, Bérotha, Sibraïm située entre la frontière de Damas et la frontière de Hamath, et Hatser-Hattikon située aux confins de l\'Hauran.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Et la frontière sera depuis la mer à Hatsar-Enon, frontière de Damas, et le nord, au nord, et la frontière de Hamath. C\'est là le côté du nord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Et le côté oriental est entre l\'Hauran et Damas; et le Jourdain entre Galaad et le pays d\'Israël: de la frontière vous mesurerez jusqu\'à la mer orientale. C\'est là le côté de l\'orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Le côté méridional sera depuis Thamar, jusques aux Eaux de querelle, Kadès, jusqu\'au torrent d\'Egypte vers la grande mer. C\'est le côté du midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Et le côté occidental sera la grande mer, depuis la frontière jusque vis-à-vis de Hamath. C\'est le côté occidental.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'C\'est ce pays que vous diviserez entre vous selon les tribus d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'et vous le partagerez au sort par héritages entre vous et les étrangers domiciliés parmi vous, qui auront engendré des fils parmi vous, et vous les regarderez comme indigènes, comme enfants d\'Israël; ils partageront au sort avec vous parmi les tribus d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'C\'est dans la tribu où l\'étranger sera domicilié, que vous lui donnerez son lot, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Or, voici les noms des tribus. Depuis l\'extrémité au nord, à côté du chemin de Hethlon, jusqu\'à Hamath, Hatsar-Enon, frontière de Damas, vers le nord près de Hamath, que cela lui appartienne de l\'orient à l\'occident: Dan, une tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Et aux confins de Dan, de l\'orient à l\'occident: Asser, une tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Et aux confins d\'Asser, de l\'orient à l\'occident: Nephthali, une tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Et aux confins de Nephthali, de l\'orient à l\'occident: Manassé, une tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Et aux confins de Manassé, de l\'orient à l\'occident: Éphraïm, une tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Et aux confins d\'Éphraïm, de l\'orient à l\'occident: Ruben, une tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Et aux confins de Ruben, de l\'orient à l\'occident: Juda, une tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Et à la frontière de Juda, de l\'orient à l\'occident, sera la portion que vous prélèverez, de vingt-cinq mille perches en largeur et en longueur, comme les autres lots, de l\'orient à l\'occident, et le sanctuaire sera à son centre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'La portion que vous prélèverez pour l\'Éternel aura vingt-cinq mille perches en longueur et dix mille en largeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Et c\'est aux prêtres qu\'appartiendra cette portion sainte ayant au nord vingt-cinq mille perches, et à l\'occident dix mille en largeur, et à l\'orient dix mille en largeur, et au midi vingt-cinq mille en longueur. Et le sanctuaire de l\'Éternel sera à son centre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Elle appartiendra aux prêtres consacrés, enfants de Tsadok, qui ont maintenu mon service, n\'ont pas déserté, quand les enfants d\'Israël désertèrent, comme les lévites ont déserté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Sur la portion du pays ils auront une portion très sainte, aux confins des lévites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Et les lévites recevront parallèlement à la limite des prêtres vingt-cinq mille perches en longueur, et dix mille en largeur; totalité de la longueur, vingt-cinq mille, et de la largeur, dix mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Ils n\'en vendront et n\'en échangeront rien; et les prémices du pays ne seront point aliénées, car elles sont consacrées à l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Et cinq mille perches qui restent en largeur, sur vingt-cinq mille [de longueur], formeront le terrain commun de la ville, pour les habitations et la banlieue, et la ville sera au centre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Et voici ses dimensions: le côté du nord quatre mille cinq cents, et le côté du midi quatre mille cinq cents, et le côté de l\'orient quatre mille cinq cents, et le côté de l\'occident quatre mille cinq cents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Et la ville aura une banlieue: au nord deux cent cinquante, et au midi deux cent cinquante, et à l\'orient deux cent cinquante, et à l\'occident deux cent cinquante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Et de ce qui restera en longueur, parallèlement à la portion sainte, dix mille perches à l\'orient et dix mille à l\'occident parallèlement à la portion sainte, son produit sera pour l\'entretien des ouvriers de la ville;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'et il sera cultivé par les ouvriers de la ville, pris de toutes les tribus d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Toute la portion prélevée est de vingt-cinq mille [perches en longueur] sur vingt-cinq mille [en largeur]; vous ferez de la portion sainte un carré séparé où sera comprise la propriété de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Et au prince appartiendra ce qui reste des deux côtés de la portion sainte et de la propriété de la ville, le long des vingt-cinq mille perches de la portion sainte jusqu\'à la limite orientale, et à l\'occident le long des vingt-cinq mille sur la limite occidentale; [cet espace] parallèle aux lots [des tribus] appartiendra au prince, et la portion sainte et le sanctuaire de la maison seront au milieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Or, de la part des lévites et de la propriété de la ville (qui coupent la propriété du prince) ce qui est entre la limite de Juda et la limite de Benjamin, appartiendra au prince.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Les autres tribus sont, de l\'orient à l\'occident: Benjamin, une tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Et aux confins de Benjamin, de l\'orient à l\'occident: Siméon, une tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Et aux confins de Siméon, de l\'orient à l\'occident: Issaschar, une tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Et aux confins d\'Issaschar, de l\'orient à l\'occident: Zabulon, une tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Et aux confins de Zabulon, de l\'orient à l\'occident: Gad, une tribu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Et aux confins de Gad, du côté du midi, la frontière sera depuis Thamar aux Eaux de querelle, de Kadès jusqu\'au fleuve, à la grande mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Tel est le pays que vous devez partager au sort par héritages aux tribus d\'Israël, et ce sont là leurs portions, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Et voici les issues de la ville: Du côté du nord, sa dimension sera de quatre mille cinq cents [perches],');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'et les portes de la ville auront le nom des tribus d\'Israël; il y en aura trois au nord: la porte de Ruben, une porte; la porte de Juda, une porte; la porte de Lévi, une porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Et du côté de l\'orient quatre mille cinq cents perches, et trois portes: la porte de Joseph, une porte; la porte de Benjamin, une porte; la porte de Dan, une porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Et au midi quatre mille cinq cents perches de dimension, et trois portes: la porte de Siméon, une porte; la porte d\'Issaschar, une porte; la porte de Zabulon, une porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'A l\'occident, quatre mille cinq cents perches, leurs portes au nombre de trois: la porte de Gad, une porte; la porte d\'Asser, une porte; la porte de Nephthali, une porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Circonférence, dix-huit mille perches: et le nom de la ville sera désormais « l\'Éternel est ici. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'La troisième année du règne de Jéhojakim, roi de Juda, Nébucadnézar, roi de Babel, arriva devant Jérusalem, et l\'assiégea.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Et le Seigneur mit entre ses mains Jéhojakim, roi de Juda, et une partie des meubles de la maison de Dieu; et il les amena au pays de Sinear, à la maison de son dieu; et il fit entrer les meubles dans le Trésor de son dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Et le roi ordonna à Aspenas, chef de ses eunuques, d\'amener des enfants d\'Israël et de race royale et de noble extraction,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'des jeunes garçons sans défaut et sans tache, beaux de figure, et versés dans toute la sagesse, et connaissant la science, et doués d\'instruction, qui fussent propres à faire le service dans le palais du roi, et à apprendre la langue et les lettres des Chaldéens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Et le roi leur assigna un ordinaire quotidien sur les mets délicats du roi et sur le vin qu\'il buvait, et fixa pour leur éducation trois années au bout desquelles ils entreraient au service de la personne du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Et de ce nombre il y avait de la race de Juda Daniel, Hananias, Misaël et Azarias.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Et le chef des eunuques leur donna des noms, et donna à Daniel le nom de Beltsazar, et à Hananias celui de Sadrach, et à Misaël celui de Mésach, et à Azarias celui de Abednégo.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Or, Daniel prit la résolution de ne pas contracter la souillure des mets délicats du roi ni du vin qu\'il buvait, et il sollicita du chef des eunuques la permission de ne pas se souiller.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Et Dieu mit Daniel en faveur et en grâce auprès du chef des eunuques;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'et le chef des eunuques dit à Daniel: Je crains le roi, mon maître, qui lui-même a fixé ce que vous mangerez et boirez; car pourquoi vous verrait-il un visage plus défait qu\'aux enfants de votre âge? Ainsi, vous exposeriez ma tête auprès du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Alors Daniel s\'adressa au maître d\'hôtel auquel le chef des eunuques avait commis Daniel, Hananias, Misaël et Azarias:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Fais donc un essai de dix jours sur tes serviteurs, et qu\'on nous donne des légumes pour nourriture, et de l\'eau pour boisson.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Puis tu examineras notre visage et le visage des enfants nourris des mets délicats du roi; et traite alors tes serviteurs d\'après ce que tu auras vu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Et il leur déféra en cela, et fit sur eux un essai de dix jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Et au bout de dix jours on leur vit meilleur visage et plus d\'embonpoint qu\'à tous les enfants nourris des mets délicats du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Alors le maître d\'hôtel supprima leurs mets délicats, et le vin qu\'ils avaient pour boisson, et leur servit des légumes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Et à ces jeunes gens, aux quatre, Dieu accorda la connaissance et l\'intelligence de toutes les lettres, et de toute la sagesse; et Daniel avait l\'entente de toutes les visions et des songes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Et après l\'expiration du temps fixé par le roi pour leur admission, le chef des eunuques les amena et les présenta à Nébucadnézar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Et le roi s\'entretint avec eux, et entre eux tous aucun ne fut trouvé égal à Daniel, à Hananias, à Misaël et à Azarias; ils furent donc placés auprès de la personne du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Et sur tous les points de sagesse et d\'intelligence sur lesquels le roi les interrogeait, il les trouvait dix fois supérieurs à tous les devins et enchanteurs qui étaient dans tout son empire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Ainsi fut Daniel jusqu\'à la première année du roi Coresch.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Et la seconde année du règne de Nébucadnézar, Nébucadnézar eut des songes. Et son esprit était agité, et il avait perdu le sommeil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Et le roi ordonna de convoquer les devins et les enchanteurs, et les mages et les Chaldéens pour qu\'ils exposassent au roi ses songes; et ils vinrent et se présentèrent devant le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Et le roi leur dit: J\'ai eu un songe, et mon esprit s\'agite pour avoir la connaissance de ce songe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Et les Chaldéens dirent au roi en langue araméenne: O roi, puisses-tu vivre éternellement! dis le songe à tes serviteurs, et nous t\'en découvrirons le sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Le roi répondit et dit aux Chaldéens: La parole est émanée de moi! Si vous ne me faites connaître le songe et sa signification, vous serez coupés par morceaux, et vos maisons seront changées en tas de fumier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Mais si vous m\'exposez le songe et sa signification, vous recevrez de moi des dons et des largesses, et de grands honneurs; indiquez-moi donc quel est le songe, et quel en est le sens!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Ils répondirent de nouveau, et dirent: Que le roi dise le songe à ses serviteurs, et nous en découvrirons le sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Le roi répondit et dit: Je comprends, à en être certain, que c\'est du temps que vous voulez gagner, par la raison que vous voyez que la parole est émanée de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Si donc vous ne me faites pas connaître le songe, c\'est là votre unique but, et vous vous êtes entendus pour me débiter des mensonges et des faussetés, jusqu\'à ce que le moment ait changé: ainsi, racontez-moi le songe, et je saurai que vous êtes capables de m\'en donner l\'explication.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Les Chaldéens répliquèrent devant le roi, et dirent: Sur la terre sèche il n\'est personne qui soit en état d\'exposer la chose énoncée par le roi: aussi, jamais roi, quelque grand et puissant qu\'il fût, n\'a exigé chose pareille d\'aucun devin, enchanteur et Chaldéen.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'La chose qu\'exige le roi est trop difficile, et pour la découvrir au roi il n\'y en a pas d\'autre que les dieux qui n\'habitent pas au milieu des mortels.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'A cause de cela le roi se mit en colère, et fut fort courroucé, et il ordonna de faire périr tous les sages de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Et l\'édit fut promulgué, et les sages devaient être mis à mort; et l\'on cherchait Daniel et ses compagnons pour les mettre à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Alors Daniel fit une réponse sage et prudente à Arioch, chef des satellites du roi, qui était sorti pour mettre à mort les sages de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Prenant la parole il dit à Arioch, général du roi: Pourquoi cet édit sévère de par le roi? Alors Arioch fit connaître à Daniel ce qui en était.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Et Daniel entra, et pria le roi de lui accorder un délai et la permission de donner au roi l\'explication.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Puis Daniel se rendit dans sa maison, et informa Hananias, Misaël, et Azarias, ses compagnons, de l\'état des choses:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'qu\'il leur fallait implorer la miséricorde du Dieu du ciel au sujet de ce mystère, afin que Daniel et ses compagnons ne périssent pas avec les autres sages de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Après cela, dans une vision nocturne le mystère fut dévoilé à Daniel; puis Daniel bénit le Dieu du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Daniel prit la parole et dit: Béni soit le nom de Dieu de l\'éternité à l\'éternité! car Il a, oui, Il a sagesse et puissance!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'C\'est lui qui opère les vicissitudes des temps et des époques, qui dépose des rois, et élève des rois, qui accorde la sagesse aux sages, et l\'intelligence à ceux qui savent comprendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Il met à nu les profondeurs et les secrets, Il pénètre ce qui est ténébreux, et la lumière demeure auprès de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'A toi, Dieu de mes pères, j\'élève mes actions de grâces et mes louanges, parce que tu m\'as accordé la sagesse et la force, et que tu m\'as révélé ce que je te demandais; car tu nous as révélé la pensée du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Ensuite de cela Daniel entra chez Arioch, à qui le roi avait donné l\'office de faire périr les sages de Babel; il alla et lui parla ainsi: Ne fais point périr les sages de Babel! Introduis-moi auprès du roi, et j\'exposerai au roi l\'explication.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Alors Arioch en hâte introduisit Daniel auprès du roi, auquel il parla en ces termes: J\'ai trouvé un homme parmi les captifs de Juda, qui présentera au roi l\'explication.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Le roi répondit et dit à Daniel dont le nom était Beltsazar: Es-tu à même de me dire quel songe j\'ai eu, et quel en est le sens?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel répondit en présence du roi et dit: « Le mystère qui est l\'objet de la demande du roi, ni sages, ni enchanteurs, ni devins, ni mages ne sont capables de le dévoiler au roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Mais il est dans le ciel un Dieu qui dévoile les mystères, et Il révèle au roi Nébucadnézar ce qui aura lieu dans la suite des temps. Voici le songe et la vision qui se sont présentés à ton esprit, pendant que tu étais couché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'O roi, tes pensées se sont élevées en toi pendant que tu étais couché, et se sont portées sur ce qui arrivera après ce temps-ci; et Celui qui dévoile les mystères, t\'a révélé l\'avenir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Quant à moi, ce n\'est point par une sagesse que j\'aurais de plus que tous les vivants, que ce mystère m\'a été dévoilé, mais c\'est afin que le sens en soit découvert au roi, et que tu comprennes les pensées de ton cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'O roi, tu avais une vision, et voici, [tu voyais] une grande figure; cette figure était immense, et elle avait un éclat extraordinaire; elle était debout devant toi, et son aspect était formidable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'La figure était ainsi composée: elle avait la tête d\'or fin, la poitrine et les bras d\'argent, le ventre et les hanches d\'airain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'les jambes de fer, les pieds en partie de fer, et en partie d\'argile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Tu regardais, regardais, quand sans l\'aide de mains se détacha une pierre qui frappa la figure à ses pieds qui étaient de fer et d\'argile, et les mit en pièces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Alors, à ce seul coup, fer, argile, airain, argent et or furent pulvérisés, et devinrent comme la balle qui s\'élève de l\'aire au blé, et le vent les emporta, et on n\'en retrouva point de traces; et la pierre qui avait frappé la figure, devint une grande montagne, et remplit toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Tel est le songe, et nous allons en exposer le sens devant le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Tu es, ô roi, le roi des rois, à qui le Dieu du ciel a donné l\'empire, la puissance et la force et la gloire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'et partout où habitent des enfants des hommes, des bêtes des champs et des oiseaux du ciel, Il les a remis entre tes mains, et t\'a fait le souverain d\'eux tous; c\'est toi qui es la tête d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Et après toi s\'élèvera un autre empire, moindre que toi, puis un troisième et autre empire d\'airain qui dominera sur toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Et un quatrième empire aura la force du fer; de même que le fer brise et fracasse tout, oui, comme un fer qui met en pièces, il fracassera et pulvérisera le tout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Quant à ce que tu as vu les pieds et les orteils être en partie d\'argile de potier, en partie de fer, c\'est que ce sera un empire divisé; mais il y aura en lui quelque chose de la force du fer; car tu as vu le fer allié avec l\'argile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Quant aux orteils qui étaient en partie de fer et en partie d\'argile, c\'est que cet empire en partie sera fort, et en partie fragile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Quant à ce que tu as vu le fer mêlé à l\'argile, c\'est qu\'ils s\'allieront entre eux par le mélange de races d\'hommes, mais ils ne seront pas adhérents entre eux, voici, ce sera comme le fer qui ne s\'allie pas avec l\'argile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Mais dans les temps de ces mêmes rois, le Dieu du ciel élèvera un empire éternellement indestructible, et dont la souveraineté ne sera dévolue à aucun autre peuple; il pulvérisera et anéantira tous ces empires; mais lui-même il subsistera éternellement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'comme tu as vu une pierre sans l\'aide de mains se détacher de la montagne, et mettre en pièces le fer, l\'airain, l\'argile, l\'argent et l\'or. Le grand Dieu a fait connaître au roi ce qui arrivera après ce temps-ci; et le songe est véridique, et l\'explication en est fidèle. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Alors le roi Nébucadnézar tomba sur sa face, et se prosterna devant Daniel, et commanda de répandre devant lui des offrandes et des parfums.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Le roi répondit à Daniel, et dit: Il est vrai! votre Dieu est le Dieu des dieux, et le Souverain des rois, et c\'est lui qui dévoile les mystères, puisque tu as été capable de me dévoiler ce mystère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Alors le roi éleva Daniel, et lui fit des dons nombreux et considérables, et il l\'établit gouverneur de toute la province de Babel, et chef de tous les sages de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Mais sur la prière de Daniel le roi préposa à l\'administration de la province de Babel, Sadrach, Mésach et Abednégo; et Daniel fut dans la Porte du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Le roi Nébucadnézar fit une statue d\'or, qui avait soixante coudées de hauteur, et six coudées d\'épaisseur; il l\'éleva dans la plaine de Doura, dans la province de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Et le roi Nébucadnézar envoya l\'ordre de convoquer les satrapes, les préfets et les gouverneurs, les grands-juges, les trésoriers, les légistes, les jurisconsultes, et tous les magistrats des provinces, afin qu\'ils vinssent à l\'inauguration de la statue qu\'avait élevée le roi Nébucadnézar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Alors se rassemblèrent les satrapes, les préfets et les gouverneurs, les grands-juges, les trésoriers, les légistes, les jurisconsultes, et tous les magistrats des provinces, pour l\'inauguration de la statue qu\'avait élevée le roi Nébucadnézar, et ils se placèrent debout devant la statue qu\'avait élevée Nébucadnézar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Et le héraut cria avec force: Avis vous est donné, peuples, nations et hommes de toutes langues!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Au moment où vous entendrez le son de la trompette, du chalumeau, de la lyre, de la sambuque, du psaltérion, de la cornemuse et de toutes les sortes d\'instruments, vous aurez à vous prosterner et à adorer la statue d\'or qu\'a élevée le roi Nébucadnézar:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'et quiconque ne se prosternera pas et n\'adorera pas, sera au même instant jeté dans la fournaise ardente qui est allumée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'En conséquence, à l\'instant où tous les peuples entendirent le son de la trompette, du chalumeau, de la lyre, de la sambuque, du psaltérion et de toutes les sortes d\'instruments, tous les peuples, les nations et les hommes de toutes langues se prosternèrent devant la statue d\'or qu\'avait élevée le roi Nébucadnézar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Ensuite de cela, au moment même des hommes Chaldéens s\'approchèrent, et accusèrent les Juifs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'en prenant la parole, et en disant au roi Nébucadnézar: O roi, puisses-tu vivre éternellement!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'O roi, tu as émis un décret portant que chacun, à l\'ouïe du son de la trompette, du chalumeau, de la lyre, de la sambuque, du psaltérion et de la cornemuse, et de toutes les sortes d\'instruments, eût à se prosterner et à adorer la statue d\'or;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'et que quiconque ne se prosternerait pas et n\'adorerait pas, serait jeté dans la fournaise ardente qui est allumée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Or, il y a des hommes Juifs que tu as préposés à l\'administration de la province de Babel, Sadrach, Mésach et Abednégo, ces hommes ne tiennent aucun compte de toi, ô roi; ils ne rendent aucun culte à tes dieux, et ils n\'adorent point la statue d\'or que tu as élevée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Alors Nébucadnézar irrité et courroucé dit qu\'on amenât Sadrach, Mésach et Abednégo. En conséquence, ces hommes furent amenés devant le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Nébucadnézar prit la parole et leur dit: Était-ce dessein prémédité, Sadrach, Mésach et Abednégo? Vous ne rendez pas un culte à mon dieu, et vous n\'adorez pas la statue d\'or que j\'ai élevée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Maintenant donc, si au moment où vous entendrez le son de la trompette, du chalumeau, de la lyre, de la sambuque, du psaltérion, et de la cornemuse et de toutes les sortes d\'instruments, vous vous prosternez et adorez la statue que j\'ai faite, [c\'est bien]; mais si vous n\'adorez pas, vous serez au moment même jetés dans la fournaise ardente qui est allumée; et quel est le Dieu qui vous délivrera de ma main?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Sadrach, Mésach et Abednégo répondirent et dirent au roi Nébucadnézar: Il n\'est pas besoin que nous te répondions rien là-dessus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Si notre Dieu que nous servons a le pouvoir de nous délivrer de la fournaise ardente qui est allumée, Il nous délivrera aussi de ta main, ô roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Sinon, sache néanmoins, ô roi, que nous ne servons point tes dieux et que nous n\'adorons point la statue d\'or que tu as élevée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Alors Nébucadnézar fut rempli de colère, et tourna vers Sadrach, Mésach et Abednégo un visage altéré. Puis prenant la parole il commanda de chauffer la fournaise sept fois plus qu\'on n\'avait trouvé bon de la chauffer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Et il ordonna à des hommes, aux hommes les plus vigoureux de son armée, de lier Sadrach, Mésach et Abednégo, et de les jeter dans la fournaise ardente qui était allumée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Alors ces hommes furent attachés dans leurs caleçons, leurs tuniques et leurs manteaux et leurs vêtements, puis jetés dans la fournaise ardente qui était allumée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Ensuite de ce que l\'ordre du roi avait été sévère, et que la fournaise était extraordinairement chauffée, les hommes qui avaient hissé Sadrach, Mésach et Abednégo, périrent par l\'effet du feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Cependant ces trois hommes, Sadrach, Mésach et Abednégo, tombèrent tout liés dans la fournaise ardente qui brûlait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Alors le roi Nébucadnézar fut stupéfait, et se leva précipitamment. Il prit la parole et dit à ses conseillers: N\'avons-nous pas jeté trois hommes liés dans les flammes? Ils répondirent et dirent au roi: Certainement, ô roi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Il répliqua et dit: Voici, je vois quatre hommes marcher sans liens au milieu du feu, et on ne voit sur eux aucune lésion, et le quatrième par son air ressemble à un fils des dieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Alors Nébucadnézar s\'approcha de la porte de la fournaise ardente qui était allumée. Il prit la parole et dit: Sadrach, Mésach et Abednégo, serviteurs du Dieu suprême, sortez et venez! Alors Sadrach, Mésach et Abednégo sortirent du milieu des flammes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Et les satrapes, les préfets et les gouverneurs et les conseillers du roi se rassemblèrent; ils virent sur ces hommes que le feu n\'avait eu aucune prise sur leurs corps, et que les cheveux de leurs têtes n\'avaient pas été brûlés, et que même la partie inférieure de leur habillement n\'avait éprouvé aucune altération, et que l\'odeur du feu ne les avait point pénétrés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Nébucadnézar prit la parole et dit: Béni soit le Dieu de Sadrach, Mésach et Abednégo, lequel a envoyé son ange, et sauvé ses serviteurs qui se confiaient en lui, et qui ont transgressé l\'ordre du roi et livré leurs corps, pour ne point servir et ne point adorer un autre Dieu que leur Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Et de par moi ordre est donné que tout peuple, toute nation et homme de toute langue qui blasphémera le Dieu de Sadrach, Mésach et Abednégo, soit coupé par morceaux, et que sa maison soit changée en un tas de fumier, parce qu\'il n\'y a pas d\'autre Dieu qui puisse délivrer de la sorte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Dès lors le roi rendit Sadrach, Mésach et Abednégo puissants dans la province de Babel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Le roi Nébucadnézar à tous les peuples, aux nations et aux hommes de toute langue qui habitent sur toute la terre. A vous grande prospérité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'J\'ai trouvé bon de publier les signes et les miracles que le Dieu suprême a opérés sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Ses signes! qu\'ils sont grands! et ses miracles! qu\'ils sont puissants! Son empire est un empire éternel, et sa domination se perpétue à travers tous les âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Moi, Nébucadnézar, je vivais tranquille dans ma maison, et heureux dans mon palais:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'j\'eus un songe qui m\'effraya, et les pensées que j\'avais sur ma couche, et les visions de mon esprit me troublaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Et de par moi ordre fut donné d\'amener devant moi tous les sages de Babel, afin qu\'ils m\'expliquassent le sens du songe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Alors furent introduits les devins, les enchanteurs, les Chaldéens et les mages, et je leur dis le songe, mais ils ne m\'en expliquèrent point le sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Et enfin parut devant moi Daniel, nommé Beltsazar du nom de mon Dieu, et en qui est l\'esprit des dieux saints, et je lui dis le songe:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Beltsazar, chef des mages, en qui je sais que se trouve l\'esprit des dieux saints, et pour qui aucun mystère n\'est embarrassant, dis-moi les visions que j\'ai vues en songe, et leur signification.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Or voici les visions [qui se sont présentées] à mon esprit, pendant que j\'étais couché: Je regardais, et voici, il y avait au milieu de la terre un grand arbre qui était très élevé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'l\'arbre était grand et vigoureux, et sa hauteur atteignait au ciel, et il était aperçu jusqu\'au bout de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Son feuillage était beau, et ses fruits abondants, et il offrait une nourriture à tous: sous lui les bêtes des champs venaient chercher l\'ombre, et les oiseaux du ciel habitaient ses branches, et il y avait une nourriture pour toute chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Je contemplais durant les visions qui sur ma couche s\'offraient à mon esprit, et voici, l\'un des Saints qui veillent descendit du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Il cria avec force, et parla ainsi: Coupez l\'arbre, et tronçonnez ses branches, détachez ses feuilles, et dispersez ses fruits, que les animaux fuient son abri, et les oiseaux ses branches!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Cependant laissez en terre la souche de ses racines, mais dans des chaînes de fer et d\'airain, au milieu de la verdure des campagnes, et qu\'il soit trempé de la rosée du ciel, et qu\'avec les animaux il entre en part de l\'herbe de la terre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Son cœur sera autre que celui d\'un humain, et le cœur d\'une brute lui sera donné, et le temps passera sept fois sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'L\'arrêt en est délibéré par ceux qui veillent, et l\'événement est dans la sentence des Saints, afin que les vivants sachent que le Très-Haut a la domination sur la royauté de l\'homme, et qu\'il la confère à qui Il veut, et qu\'il y élève le plus abject des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Tel est le songe que j\'eus, moi, le roi Nébucadnézar; et toi, Beltsazar, donnes-en l\'interprétation, puisque tous les sages de mon empire sont incapables de m\'en faire connaître le sens; mais toi, tu le peux, car l\'esprit des dieux saints est en toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Alors Daniel, nommé Beltsazar, demeura un moment interdit, et ses pensées le troublaient. Le roi prit la parole et dit: Beltsazar, que le songe et l\'interprétation ne te troublent pas! Beltsazar répondit et dit: Mon Seigneur, que le songe s\'applique à tes ennemis, et son interprétation à tes adversaires!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'L\'arbre que tu as vu, qui était grand et vigoureux, et dont la hauteur atteignait au ciel, et qui était vu sur toute la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'et dont le feuillage était beau et les fruits abondants, et qui avait une nourriture pour tous, sous lequel s\'abritaient les animaux des campagnes, et dont les oiseaux du ciel habitaient les branches,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'c\'est toi, ô roi qui es grand et puissant, et dont la grandeur est immense et atteint au ciel, et dont l\'empire s\'étend jusqu\'au bout de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Et si le roi a vu l\'un des Saints vigilants descendu du ciel et disant: Coupez l\'arbre, et abîmez-le, cependant laissez en terre la souche de ses racines, mais dans des chaînes de fer et d\'airain, au milieu de la verdure des campagnes, et qu\'il soit trempé de la rosée du ciel, et qu\'il entre en part avec les bêtes des champs, jusqu\'à ce que le temps ait passé sept fois sur lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'voici ce que cela signifie, ô roi, et c\'est ici l\'arrêt du Très-Haut qui s\'adresse au roi, mon Seigneur:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'On te chassera du milieu des hommes, et tu demeureras avec les bêtes des champs, et on te donnera, comme au bœuf, de l\'herbe à manger, et tu seras trempé de la rosée du ciel, et le temps passera sept fois sur toi, jusqu\'à ce que tu reconnaisses que le Très-Haut a la domination sur la royauté de l\'homme, et qu\'il la confère à qui Il veut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Ce qui a été dit de laisser la souche des racines de l\'arbre, c\'est que ta royauté te sera restituée dès que tu auras reconnu qu\'il règne dans le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Aussi, ô roi, que mon conseil soit agréé de toi, et rachète tes péchés par la justice, et ton iniquité par la compassion envers les pauvres, si peut-être ta prospérité se prolonge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Tout cela est arrivé au roi Nébucadnézar.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Au bout de douze mois il se promenait dans son palais royal à Babel:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'le roi prit la parole et dit: N\'est-ce pas là cette vaste Babel que j\'ai bâtie, pour être une résidence royale, par ma grande puissance, et à la gloire de ma majesté?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Le mot était encore dans la bouche du roi, qu\'une voix descendit du ciel: Il t\'est dit, ô roi Nébucadnézar: La royauté t\'est ôtée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'et on te chassera du milieu des hommes, et tu demeureras avec les bêtes des champs, on te donnera, comme au bœuf, de l\'herbe à manger, et le temps passera sept fois sur toi, jusqu\'à ce que tu reconnaisses que le Très-Haut a la domination sur la royauté de l\'homme, et qu\'il la confère à qui Il veut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Au même instant la parole s\'accomplit sur Nébucadnézar, et il fut chassé du milieu des hommes, et on lui donna, comme au bœuf, de l\'herbe à manger, et son corps fut trempé de la rosée du ciel, jusqu\'à ce que ses cheveux crussent, comme aux aigles, et ses ongles, comme aux oiseaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Mais à l\'expiration du temps, moi Nébucadnézar, j\'élevai mes yeux vers le ciel, et la connaissance me revint, et je bénis le Très-Haut, et je louai et magnifiai Celui qui vit éternellement, dont l\'empire est un empire éternel, et dont la royauté dure à travers tous les âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'Auprès de lui tous les habitants de la terre sont réputés néant, et Il en agit à son gré avec l\'armée du ciel et les habitants de la terre, et il n\'en est aucun qui puisse retenir sa main et lui dire: Que fais-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'Dans ce temps-là, la connaissance me revint, et à la gloire de mon empire, de ma majesté et de ma splendeur elle me revint, et mes conseillers et mes grands vinrent me chercher, et je fus rétabli sur mon trône, et j\'obtins un grand accroissement de grandeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'Maintenant, moi Nébucadnézar, je loue et j\'exalte et je magnifie le Roi du ciel, car toute son action est vérité, et ses voies, justice, et Il peut abaisser ceux qui suivent la voie de l\'orgueil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Le roi Belschazar donna un grand festin à ses mille grands, et il but du vin en présence de ces mille personnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Belschazar, animé par le vin, dit qu\'on apportât les vases d\'or et d\'argent que Nébucadnézar, son père, avait enlevés du temple de Jérusalem, pour que le roi et ses grands, ses femmes et ses concubines bussent dans ces vases.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Alors on apporta les vases d\'or qui avaient été enlevés du temple de la maison de Dieu à Jérusalem, et le roi et ses grands, ses femmes et ses concubines burent dans ces vases.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Ils burent du vin et chantèrent des louanges à leurs dieux d\'or et d\'argent, d\'airain, de fer, de bois et de pierre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Dans ce moment même les doigts d\'une main d\'homme s\'avancèrent, et écrivirent, vis-à-vis du lustre, sur la chaux de la muraille du palais du roi, et le roi vit la main qui écrivait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Aussitôt le roi changea de couleur, et ses pensées le troublèrent, et les nerfs de ses reins se détendirent, et ses genoux s\'entre-heurtèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Le roi s\'écria avec force qu\'on mandât les devins, les Chaldéens et les mages. Le roi prit la parole et dit aux sages de Babel: Tout homme qui lira ces caractères, et m\'en expliquera la signification, sera revêtu de la pourpre, et d\'une chaîne d\'or à son cou, et occupera la troisième place dans le gouvernement de mon empire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Puis tous les sages du roi furent introduits; mais ils ne purent ni lire les caractères, ni en indiquer au roi la signification.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Alors le roi Belschazar fut extrêmement troublé, et il changea de couleur, et ses grands furent interdits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Dans cette situation du roi et des grands, la reine parut dans la salle du festin. La reine prit la parole et dit: O roi! puisses-tu vivre éternellement! que tes pensées ne te troublent pas, et ne change pas de couleur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Il est dans ton royaume un homme en qui est l\'esprit des dieux saints, et du temps de ton père en lui s\'est trouvée une lumière, une intelligence, une sagesse pareille à la sagesse des dieux; et le roi Nébucadnézar, ton père, ton père, ô roi, l\'a établi chef des devins, des enchanteurs, des Chaldéens, des mages,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'parce qu\'un esprit éminent, et la connaissance et l\'entente de l\'interprétation des songes, et de l\'explication des énigmes et de la solution des questions difficiles s\'étaient rencontrées en lui, savoir, en Daniel, dont le roi avait changé le nom en celui de Beltsazar; que Daniel soit donc mandé, et il te donnera l\'explication.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Alors Daniel fut introduit devant le roi. Le roi prit la parole et dit à Daniel: Es-tu ce Daniel, l\'un des captifs Juifs que le roi, mon père, a amenés de Juda?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'J\'ai ouï dire de toi que l\'esprit des dieux est en toi, et qu\'on trouve en toi et lumière, et intelligence, et sagesse éminente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Or les sages et les devins ont été amenés devant moi pour lire ces caractères et m\'en découvrir le sens, mais ils ne peuvent m\'expliquer le sens de la chose.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Mais j\'ai ouï dire de toi que tu sais donner les explications, et résoudre les questions difficiles; si donc tu peux lire ces caractères, et m\'en faire connaître le sens, tu seras revêtu de la pourpre, et tu auras une chaîne d\'or à ton cou, et tu occuperas la troisième place dans mon empire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Alors Daniel répondit et dit en présence du roi: Garde tes dons, et fais tes largesses à un autre! Cependant je lirai les caractères au roi, et je lui en indiquerai le sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'O roi, le Dieu très haut accorda à Nébucadnézar, ton père, royauté et grandeur, et gloire et magnificence;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'et à cause de la grandeur qu\'il lui avait donnée, les peuples, les nations et les hommes de toute langue étaient tous craintifs et tremblants devant lui; il faisait mourir qui il voulait, et donnait la vie à qui il voulait, et il élevait qui il voulait, et il abaissait qui il voulait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Mais comme son cœur s\'éleva, et que son esprit s\'enorgueillit jusqu\'à l\'insolence, il fut précipité de son trône royal, et sa gloire lui fut ôtée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'et il fut chassé du milieu des enfants des hommes, et son cœur devint semblable à la brute, et il demeura avec les onagres, comme le bœuf il mangea de l\'herbe, et son corps fut trempé de la rosée du ciel, jusqu\'à ce qu\'il eût reconnu que le Dieu très haut a la domination sur la royauté de l\'homme, et qu\'il y élève qui Il veut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Mais toi, son fils Belschazar, tu n\'as pas humilié ton cœur, quoique tu saches toutes ces choses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'et tu t\'es élevé contre le Maître du ciel, et les vases de sa maison ont été apportés devant toi, et toi et tes grands, tes femmes et tes concubines, vous avez bu du vin dans ces vases, et tu as chanté des louanges aux dieux d\'argent et d\'or, d\'airain, de fer, de bois et de pierre, qui ne voient, ni n\'entendent, ni ne savent rien, et le Dieu qui tient ton souffle dans sa main et qui préside à toutes tes destinées, tu ne l\'as pas honoré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'En conséquence, c\'est de par lui qu\'a été envoyée cette main qui a tracé ces caractères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Et voici les caractères qui ont été tracés: Compté! Compté! Pesé! et Partage!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Voici le sens du mot Compté: Dieu a fait le compte de ton règne et y met fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Pesé: Tu as été pesé à la balance et trouvé trop léger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Partage: Ton empire sera partagé et donné aux Mèdes et aux Perses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Alors, sur l\'ordre de Belschazar on revêtit Daniel de la pourpre, et on lui mit au cou une chaîne d\'or, et l\'on publia devant lui qu\'il occuperait la troisième place dans l\'empire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Cette nuit même, Belschazar, roi des Chaldéens, fut tué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'Et Darius le Mède reçut l\'empire, étant âgé de soixante-deux ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Il parut convenable à Darius de préposer à l\'empire cent vingt satrapes répartis dans tout l\'empire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'et à ceux-ci trois princes dont Daniel fut l\'un, et auxquels ces satrapes devaient rendre compte, afin que le roi ne souffrît aucun dommage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Bientôt ce Daniel l\'emporta sur les princes et sur les satrapes, parce qu\'il avait un esprit éminent, et le roi pensait à le préposer à tout l\'empire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Alors les princes et les satrapes cherchèrent à trouver contre Daniel un prétexte dans l\'exercice de sa charge; mais ils ne purent trouver ni prétexte, ni malversation, parce qu\'il était fidèle, et qu\'on ne découvrit en lui ni délit, ni malversation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Alors ces hommes dirent: Nous ne trouverons aucun prétexte contre ce Daniel, à moins que nous n\'en trouvions un contre lui dans sa piété envers son Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Alors ces princes et ces satrapes accoururent tumultuairement auprès du roi, et lui parlèrent ainsi: Roi Darius, puisses-tu vivre éternellement!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Tous les princes de l\'empire, les préfets et les satrapes, les conseillers et les gouverneurs sont d\'avis qu\'un statut royal soit dressé et une défense sanctionnée, portant que quiconque dans l\'espace de trente jours adressera une requête à un dieu, ou à un homme quelconque autre que toi, ô roi, sera jeté dans la fosse aux lions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Maintenant, ô roi, sanctionne la défense, et rends par écrit un édit, irrévocable selon la loi des Mèdes et des Perses laquelle ne s\'abroge point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Ensuite de cela le roi Darius rendit par écrit l\'édit et la défense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Or Daniel, apprenant la rédaction de l\'édit, se retira dans sa maison (il avait les fenêtres ouvertes dans son appartement supérieur dans la direction de Jérusalem), et trois fois le jour il s\'agenouilla et pria, et loua son Dieu, comme il le faisait auparavant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Alors ces hommes accoururent chez lui tumultuairement, et trouvèrent Daniel en prières et en oraison devant son Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Puis ils s\'approchèrent du roi, et devant lui ils parlèrent de la défense faite par le roi: N\'as-tu pas dit dans une défense écrite que quiconque dans l\'espace de trente jours adresserait une requête à un dieu, ou à un homme quelconque autre que toi, ô roi, serait jeté dans la fosse aux lions? Le roi répondit et dit: Cela est arrêté d\'après la loi des Mèdes et des Perses qui ne s\'abroge pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Alors ils répondirent et dirent au roi: Daniel, l\'un des captifs de Juda, n\'a tenu aucun compte de toi, ô roi, ni de la défense écrite émise par toi, et trois fois le jour il fait sa prière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'A l\'ouïe de ce discours le roi éprouva un grand chagrin, et il prit à cœur de sauver Daniel, et jusqu\'au coucher du soleil il travailla à le délivrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Alors ces hommes accoururent tumultuairement chez le roi, et dirent au roi: Sache, ô roi, que les Mèdes et les Perses ont une loi en vertu de laquelle aucune défense ni aucun statut dressé par le roi ne peut être révoqué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Alors, sur l\'ordre du roi, Daniel fut amené et jeté dans la fosse aux lions. Le roi prit la parole, et dit à Daniel: Puisse ton Dieu que tu sers avec constance, te délivrer!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Et une pierre fut apportée et posée sur l\'ouverture de la fosse, et le roi y apposa le sceau de son anneau et de l\'anneau de ses grands, afin que rien ne fût changé par rapport à Daniel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Là-dessus le roi se retira dans son palais, et il passa la nuit en jeûne, et n\'admit point ses concubines auprès de lui, et son sommeil s\'enfuit loin de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Puis le roi se leva avec l\'aurore, avec le jour, et se rendit en hâte à la fosse aux lions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Et en s\'approchant de la fosse, il appelait Daniel d\'une voix douloureuse; le roi prit la parole et dit à Daniel: Daniel, serviteur du Dieu vivant, ton Dieu que tu sers avec constance, a-t-Il pu te délivrer des lions?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Alors Daniel adressa au roi ces paroles: O roi, puisses-tu vivre éternellement!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Mon Dieu a envoyé son ange, et fermé la gueule des lions qui ne m\'ont fait aucun mal, parce que devant Lui j\'ai été trouvé innocent, et que devant toi aussi, ô roi, je n\'ai commis aucun crime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Alors le roi éprouva une grande joie, et il fit retirer Daniel de la fosse; et Daniel fut retiré de la fosse, et il ne se trouva sur lui pas une blessure, parce qu\'il s\'était confié dans son Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Et sur l\'ordre du roi on amena ces hommes qui avaient accusé Daniel, et on les jeta dans la fosse aux lions, eux, leurs fils et leurs femmes; et ils n\'avaient pas encore atteint le fond de la fosse, que les lions s\'emparèrent d\'eux, et brisèrent tous leurs os.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Alors le roi Darius écrivit à tous les peuples, aux nations et aux hommes de toute langue qui habitaient sur toute la terre: Que votre prospérité s\'augmente!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'De par moi, ordre est donné que dans tout l\'empire de ma domination l\'on craigne et révère le Dieu de Daniel; car Il est le Dieu vivant, qui subsiste éternellement, et dont l\'empire est indestructible, et la domination infinie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'qui sauve et délivre et opère des signes et des miracles au ciel et sur la terre, qui a sauvé Daniel de la griffe des lions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Ce Daniel fut donc puissant sous le règne de Darius et sous le règne de Coresch, le Perse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'La première année de Belschazar, roi de Babel, Daniel étant couché eut un songe et des visions en son esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Ensuite il mit le songe par écrit, il raconta le sommaire de la chose. Daniel prit la parole et dit: Pendant ma vision nocturne je regardais, et voici, les quatre vents du ciel, firent irruption sur la grande mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Et quatre grands animaux surgirent de la mer, différents l\'un de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Le premier était comme un lion, et avait les ailes d\'un aigle; je regardais, jusqu\'à ce que les ailes lui furent arrachées, et il fut soulevé de terre, et mis debout sur ses pieds comme un homme, et un cœur humain lui fut donné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Et voici, un autre animal, le second, ressemblait à un ours, il se tenait debout sur un seul côté, et il avait trois côtes dans, sa gueule entre ses dents, et on lui disait: Allons! dévore force chair!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Après celui-ci, je regardais toujours, et voici un autre animal tel qu\'une panthère, et il portait quatre ailes d\'oiseau sur sa croupe, et l\'animal avait quatre têtes, et l\'empire lui fut donné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Après celui-ci, je regardais toujours durant les visions nocturnes, et voici un quatrième animal terrible et formidable et extraordinairement fort, et il avait de grosses dents de fer, il dévorait et brisait, et il foulait les restes avec ses pieds, et il différait de tous les animaux qui l\'avaient précédé, et il avait dix cornes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'J\'observai les cornes, et voici, une autre petite corne surgit au milieu d\'elles, et trois des premières cornes furent arrachées par celle-ci; et voici, cette corne avait des yeux comme des yeux d\'homme, et une bouche qui parlait avec orgueil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Je regardais toujours, jusqu\'à ce que des sièges furent placés, et l\'Ancien des jours prit séance; son manteau était blanc comme la neige, et les cheveux de sa tête comme une laine pure, des flammes de feu formaient son trône dont les roues étaient un feu allumé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Un fleuve de feu coula et jaillit de lui; mille milliers le servaient, et des myriades de myriades se tenaient devant lui; le tribunal prit séance, et les livres furent ouverts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Je regardais toujours, alors, à cause des discours orgueilleux que prononçait la corne, et comme je regardais, l\'animal fut tué, et son corps périt et il fut jeté dans le feu ardent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Quant aux autres animaux, leur empire leur fut aussi ôté, car la longueur de leur vie avait été limitée pour eux à un temps et à une époque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Je regardais durant les visions nocturnes, et voici, sur les nuées du ciel arrivait quelqu\'un qui ressemblait à un fils de l\'homme, et il parvint jusqu\'à l\'Ancien des jours, et ils le firent approcher de Lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Et à lui fut donné l\'empire, l\'honneur et la royauté, afin que tous les peuples, les nations, et les hommes de toute langue le servent; son empire est un empire éternel qui ne passera point, et sa royauté est impérissable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Moi Daniel, je sentais dans mon intérieur mon cœur attristé, et mes visions m\'effrayaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'J\'abordai l\'un de ceux qui étaient là debout, et je le priai de me faire avoir une certitude sur toutes ces choses; et il me parla et me découvrit le sens de toutes ces choses:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, '« Ces grands animaux, qui sont au nombre de quatre, c\'est quatre rois qui s\'élèveront de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Mais les saints du Très-Haut recevront l\'empire et posséderont l\'empire éternellement et dans toute l\'éternité. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Alors je désirai d\'avoir une certitude sur le quatrième animal, qui était différent d\'eux tous, singulièrement terrible, et qui avait des dents de fer, et des griffes d\'airain, qui dévorait, et brisait, et foulait les restes avec ses pieds;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'et sur les dix cornes qui étaient à sa tête, et sur l\'autre qui surgit, et devant laquelle il y en eut trois qui tombèrent, et cette corne avait et des yeux et une bouche qui parlait avec orgueil, et elle avait une plus grande apparence que ses compagnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Je regardais comme cette corne faisait la guerre aux saints, et remportait la victoire sur eux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'jusqu\'à ce que l\'Ancien des jours vint, et qu\'il fut fait droit aux saints du Très-Haut, et que le temps arriva où les saints devaient posséder l\'empire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Il me parla ainsi: Le quatrième animal, c\'est un quatrième empire qui existera sur la terre, qui sera différent de tous les empires, et qui dévorera toute la terre, et la foulera, et la pulvérisera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Et les dix cornes, ce sont dix rois qui naîtront de cet empire, et il s\'en élèvera après eux un autre qui sera différent des trois précédents et humiliera trois rois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Et il tiendra des discours contre le Très-Haut, et il froissera les saints du Très-Haut, et il aura la pensée de changer les temps de fête et la Loi; et ils seront livrés entre ses mains un temps, et [deux] temps, et la moitié d\'un temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Mais le tribunal prendra séance, et on lui ôtera la domination afin de le détruire et de l\'anéantir pour jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Et la royauté, et la domination et la puissance de tous les empires qui sont sous le ciel entier, seront données au peuple des saints du Très-Haut; son empire est un empire éternel, et toutes les dominations le serviront et lui obéiront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Ici finit le récit. Moi Daniel, je fus fort effrayé de mes visions, et je changeai de couleur; mais je gardai la chose dans mon cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'La troisième, année du règne du roi Belschazar, une vision m\'apparut, à moi Daniel, après celle qui m\'était précédemment apparue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'J\'étais absorbé dans la contemplation, et il arriva, comme je contemplais, que je me trouvai dans la résidence de Suse située dans la province d\'Élam, et j\'étais absorbé dans la vision, et je me trouvais près du fleuve Eulée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Et je levai les yeux, et je regardai, et voici, un bélier se tenait en face du fleuve, et il avait deux cornes, et les deux cornes étaient hautes, et l\'une était plus haute que l\'autre, et la plus haute fut la dernière à s\'élever.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Je voyais le bélier frappant à l\'occident, et au nord, et au midi, et aucun animal ne lui tenait tête, et personne ne délivrait de sa main, et il agissait à son gré, et il montrait de la fierté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Et j\'observai, et voici, un bouc s\'avançait du couchant parcourant toute la terre, sans toucher le sol, et le bouc avait une corne saillante entre ses deux yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Et il vint jusqu\'au bélier armé des deux cornes que je voyais se tenant en face du fleuve, et il fondit sur lui dans sa puissante colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Et je le vis comme il atteignait le bélier; et il était exaspéré contre lui, et il heurta le bélier et lui brisa les deux cornes, et le bélier fut sans force pour lui résister; et il le terrassa et le foula, et personne ne sauva le bélier de sa main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Et le bouc montrait un grand excès d\'orgueil; mais quand il était dans sa force, la grande corne se cassa, et il crût à sa place quatre cornes saillantes dans la direction des quatre vents du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Et de l\'une d\'elles surgit une petite corne qui s\'agrandit considérablement du côté du midi et du levant et de l\'ornement [de la terre].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Et elle prit une grandeur qui atteignit jusqu\'à l\'armée des Cieux, et elle fit tomber à terre des portions de cette armée et des étoiles, et les foula;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'et elle s\'éleva même jusqu\'au chef de l\'armée, et lui enleva le sacrifice perpétuel, et la résidence de son sanctuaire fut abattue;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'et l\'armée est livrée en même temps que le sacrifice perpétuel à cause du péché, et elle jette la vérité par terre, et elle le fait, et elle réussit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Et j\'entendis parler l\'un des Saints; et un autre Saint parla à celui qui parlait: Quel est le temps fixé par la vision qui a trait au sacrifice perpétuel et au péché dévastateur, et annonce que le sanctuaire et l\'armée seront livrés pour être foulés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Et il me dit: Deux mille et trois cents fois soir et matin, et le sanctuaire sera purifié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Et pendant que moi, Daniel, je regardais la vision, je cherchais à comprendre, et voici, comme une figure d\'homme se trouva debout devant moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Et j\'entendis une voix d\'homme en dedans de l\'Eulée, et il s\'écria et dit: Gabriel, explique-lui la vision!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Et il vint près du lieu où je me tenais, et à son approche je fus saisi d\'effroi, et je tombai sur ma face; et il me dit: Attention! fils d\'homme, car c\'est au temps final que la vision a trait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Et comme il me parlait, je tombai tout étourdi la face contre terre; mais il me toucha et me remit debout à ma place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Et il me dit: Voici, je vais te montrer ce qui arrivera dans la dernière époque de la colère, car [la vision a trait] au temps final.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Le bélier que tu as vu, armé de deux cornes, ce sont les rois des Mèdes et des Perses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Et le bouc est un roi de la Grèce, et la grande corne qui est entre ses deux yeux, c\'est le premier roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Et la corne brisée et remplacée par quatre cornes, marque que quatre royaumes naîtront de ce peuple dont ils n\'auront cependant pas la puissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Et à la fin de leur empire, quand les pécheurs auront comblé la mesure, il s\'élèvera un roi au front dur, et expert dans l\'artifice,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'et sa force recevra de la vigueur mais non pas de sa propre force, et il exercera des ravages extraordinaires, et il réussira, et il exécutera, et il causera la ruine de plusieurs et du peuple des saints.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Et vu son habileté l\'artifice réussira entre ses mains, et en son cœur il s\'enorgueillira, et à l\'improviste il en ruinera plusieurs, et il s\'insurgera contre le prince des princes, et sans l\'aide d\'une main [humaine] il sera brisé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Et la vision des soirs et des matins, de laquelle il s\'agit, est une vérité; cependant toi, scelle la vision, car elle porte à une époque très lointaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Et moi Daniel, je tombai en défaillance, et fus malade pendant un certain temps; puis je me levai, et je m\'occupai des affaires du roi, et j\'étais éperdu à cause de la vision qui n\'était intelligible pour personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'La première année de Darius, fils d\'Assuérus, de la race Mède, qui devint roi du royaume des Chaldéens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'la première année de son règne, moi Daniel, je fixai mon attention dans les livres [saints] sur le nombre des années que l\'Éternel avait dit à Jérémie, le prophète, devoir s\'accomplir pour les ruines de Jérusalem, [savoir] soixante-dix années.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Et je tournai mes regards vers le Seigneur, mon Dieu, afin de chercher la prière et l\'oraison dans le jeûne, dans le cilice et la cendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Et je fis à l\'Éternel, mon Dieu, ma prière et ma confession, et je dis: O Seigneur, qui es le Dieu grand et redoutable, qui garde l\'alliance et la miséricorde pour ceux qui l\'aiment et gardent ses commandements!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Nous avons été pécheurs et pervers, et nous avons été transgresseurs et rebelles, et nous nous sommes écartés de tes commandements et de tes lois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Et nous n\'avons point écouté tes serviteurs, les prophètes, qui parlèrent en ton nom à nos rois, à nos princes et à nos pères et à tout le peuple du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Seigneur, à toi la justice, et à nous la confusion du visage en ce jour, aux hommes de Juda, et aux habitants de Jérusalem et à tout Israël, et à ceux qui sont près, et à ceux qui sont au loin dans toutes les contrées où tu les as chassés à cause du crime par lequel ils se sont rendus criminels envers toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Seigneur, à nous la confusion du visage, à nos rois, à nos princes et à nos pères, pour avoir péché contre toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Mais par devers le Seigneur, notre Dieu, il y a miséricorde et pardon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'Car nous nous sommes rebellés contre lui, et nous n\'avons point été dociles à la voix de l\'Éternel, notre Dieu, pour suivre ses lois qu\'il avait mises devant nos yeux par le ministère de ses serviteurs, les prophètes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Et tout Israël a transgressé ta loi, et s\'est détourné pour ne point écouter ta voix; et sur nous a été versée la malédiction et l\'exécration consignée dans la loi de Moïse, serviteur de Dieu, parce que nous avons péché contre Lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Et Il a réalisé sa menace prononcée par Lui contre nous et contre nos juges qui nous jugeaient, amenant sur nous une grande calamité, tellement que ce qui est arrivé à Jérusalem, n\'était jamais arrivé sous le ciel entier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Conformément à ce qui est écrit dans la Loi de Moïse, toute cette calamité nous est survenue. Mais nous n\'avons point imploré la grâce de l\'Éternel, notre Dieu, pour renoncer à nos iniquités, et nous rendre attentifs à ta vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'C\'est pourquoi l\'Éternel ne perdit pas de vue la calamité et la fit fondre sur nous; car l\'Éternel, notre Dieu, est juste dans tous les actes qu\'il opère; mais nous ne fûmes point dociles à sa voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Et maintenant, Seigneur, notre Dieu, qui as tiré ton peuple du pays d\'Egypte d\'une main forte, et qui t\'es fait un nom aujourd\'hui: nous avons péché, nous avons été des impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Seigneur! conformément à tous tes actes d\'équité, ah! que ta colère et ta fureur se détournent de ta ville de Jérusalem, ta sainte montagne! Car nos péchés et les crimes de nos pères ont rendu Jérusalem et ton peuple l\'opprobre de tous nos alentours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Écoute donc, ô notre Dieu, la prière de ton serviteur et sa requête, et fais luire ta face sur ton sanctuaire qui est dévasté, pour l\'amour du Seigneur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Incline, ô mon Dieu, ton oreille et écoute! ouvre les yeux et regarde nos ruines et la ville appelée de ton nom! et quand nous déposons nos requêtes devant toi, nous comptons non sur notre justice, mais sur tes compassions immenses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Seigneur, écoute! Seigneur, pardonne! Seigneur, aie égard et agis! ne tarde pas, au nom de toi-même, O mon Dieu! Car c\'est de ton nom que cette ville et ce peuple sont appelés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Et je parlais et priais encore, et confessais mon péché et le péché de mon peuple d\'Israël, et je laissais tomber mes prières devant l\'Éternel, mon Dieu, en faveur de la sainte montagne de mon Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'je parlais encore en oraison, quand l\'homme, Gabriel, que j\'avais vu dans la précédente vision, vint en hâte auprès de moi, vers le temps de l\'oblation du soir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Et il m\'éclaira et s\'entretint avec moi, et me dit: Daniel, je parais maintenant pour te faire pénétrer dans l\'intelligence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Comme tu commençais à prier, la parole est émanée, et je viens te l\'exposer; car tu es le désiré. Fais donc attention à la parole, et comprends la vision!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Soixante-dix semaines sont dispensées sur ton peuple et sur ta ville sainte, pour que le crime soit consommé, et la mesure du péché comblée, et l\'iniquité expiée, et pour amener une justice éternelle, et sceller la vision et le prophète, et oindre le Saint des saints.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Sache-le donc, et sois attentif: Depuis l\'émission de la parole annonçant que Jérusalem sera restaurée et rebâtie jusqu\'à un Oint, un prince, il y a sept semaines; et dans l\'espace de soixante-deux semaines elle sera restaurée et rebâtie, avec places et fossés, mais au milieu des perplexités des temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Et après les soixante-deux semaines un Oint sera retranché, et il n\'aura personne, et là ville et le sanctuaire seront ravagés par le peuple d\'un prince arrivant, et sa fin sera, amenée par une inondation, et jusqu\'à la fin il y aura guerre, arrêt de dévastations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'et il donnera une alliance forte à plusieurs pendant une semaine, et à la moitié de la semaine il fera cesser le sacrifice et l\'oblation, et sur le faîte des abominations sera le dévastateur, et cela jusqu\'à ce que l\'extermination et le décret fondent sur le dévastateur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'La troisième année de Coresch, roi de Perse, une parole fut révélée à Daniel qui portait le nom de Beltsazar; et cette parole est une vérité, et a une grande calamité pour objet. Et il fut attentif à cette révélation, et il eut l\'intelligence de la vision.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'En ce même temps, moi Daniel, je fus dans le deuil pendant trois semaines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Je ne mangeai point de pain délicat, et ni viande ni vin n\'entra dans ma bouche, et je ne m\'oignis point jusqu\'à l\'expiration des trois semaines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Et le vingt-quatrième jour du premier mois, j\'étais sur le rivage du grand fleuve Hiddékel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Et je levai les yeux, et je regardai, et voici, il y avait là un homme vêtu de lin, et ayant aux reins une ceinture d\'or d\'Uphaz.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Et son corps était comme le chrysolithe, et son visage avait l\'aspect de l\'éclair, et ses yeux étaient comme des flambeaux allumés, et ses bras et la région de ses pieds avaient l\'aspect de l\'airain poli, et le son de ses paroles était comme la voix d\'une foule en rumeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Et moi Daniel, j\'étais seul à voir la vision, et les hommes qui m\'accompagnaient, n\'apercevaient point la vision; mais un grand effroi les saisit, et ils fuirent en se dérobant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Et je restai seul, et je vis cette grande vision; mais il ne me resta point de force, et je changeai de couleur à être défiguré, et je ne conservai aucune force.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Et j\'entendis le son de ses paroles, et à l\'ouïe du son de ses paroles je tombai tout étourdi sur mon visage, et mon visage toucha la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Mais voici, une main me toucha, et soutint mes genoux vacillants et mes mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Et il me dit: Daniel, homme chéri, sois attentif aux paroles que je vais te dire, et demeure debout à ta place; car je suis maintenant envoyé vers toi. Et pendant qu\'il me parlait ainsi, j\'étais là debout tremblant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Et il me dit: Ne crains point, Daniel! Car dès le premier jour où tu as pris a cœur de comprendre, et de t\'humilier en la présence de ton Dieu, tes paroles ont été écoutées, et je viens ensuite de tes paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Et celui qui préside au royaume de Perse, m\'a tenu tête pendant vingt-un jours, et voici, Michel, l\'un de ceux qui président au premier rang, est venu à mon aide, et ainsi je l\'ai emporté auprès des rois de Perse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Et je suis venu pour t\'instruire de ce qui arrivera à ton peuple dans la suite des temps; car la vision a trait encore à l\'avenir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Et comme il m\'adressait de tels discours, je baissai mon visage contre terre, et demeurai muet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Et voici, un personnage qui ressemblait à un fils des hommes, toucha mes lèvres; puis j\'ouvris la bouche, et je parlai, et je dis à celui qui se tenait devant moi: « Mon Seigneur, par l\'effet de la vision les terreurs m\'ont saisi, et je n\'ai point conservé de force.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Et comment un serviteur de mon Seigneur que voilà pourrait-il parler avec mon Seigneur que voilà? » Et dès lors il ne me resta plus de force, et je ne respirais plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Alors je fus de nouveau touché par un personnage qui avait l\'air d\'un homme, et il me fortifia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Et il dit: Ne crains point, homme chéri! Salut pour toi! courage! courage! Et pendant qu\'il me parlait, je me sentais fortifié, et je dis: Que mon Seigneur parle, car tu m\'as fortifié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Et il dit: Sais-tu pourquoi je suis venu vers toi? Et maintenant je vais m\'en retourner pour combattre celui qui préside à la Perse, et je pars; mais voici, celui qui préside à la Grèce arrive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Toutefois je veux te découvrir ce qui est consigné dans le livre de la vérité. Et aucun ne me soutient contre ceux-là, sinon Michel qui préside sur vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Mais moi aussi, la première année de Darius, le Mède, je l\'assistai pour le soutenir et le fortifier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Maintenant donc je vais te découvrir la vérité. Voici, il s\'élèvera encore trois rois pour les Perses, et le quatrième s\'enrichira d\'une plus grande richesse que tous; et quand il sera affermi dans sa richesse, il soulèvera contre lui tout, le royaume de la Grèce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Mais il s\'élèvera un roi vaillant, et il régnera avec une grande puissance, et il agira selon son bon plaisir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Et quand il aura sa consistance, son royaume sera morcelé, et donné en part aux quatre vents des Cieux, mais non pas à ses descendants, ni avec la domination qu\'il exerçait quand il dominait; car son empire sera déchiré et dévolu à d\'autres à l\'exclusion de ceux-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Et le roi du midi se consolidera, et parmi ses généraux l\'un deviendra plus fort que lui, et régnera; et son règne aura une grande puissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Et au bout de plusieurs années ils s\'allieront, et la fille du roi du midi entrera dans la maison du roi du septentrion, pour opérer un raccommodement. Mais elle ne soutiendra pas l\'efficace de l\'expédient, et il ne tiendra pas ni lui, ni son expédient; et elle sera livrée, elle et ceux qui l\'auront introduite, et celui qui l\'aura engendrée, et celui qui la possédera dans ces temps-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Mais de la souche des racines de celle-ci surgira pour le remplacer un [prince] qui rejoindra l\'armée, et pénétrera dans les forteresses du roi du septentrion, et il les traitera à discrétion, et il sera puissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Et leurs dieux avec leurs images de fonte, avec leur vaisselle précieuse d\'argent et d\'or, seront emmenés par lui captifs en Egypte, puis pendant des années il n\'inquiétera plus le roi du septentrion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Et celui-ci marchera contre le royaume du roi du midi, mais il reviendra dans son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Mais ses fils engageront les hostilités, et réuniront une quantité de forces considérables, et l\'un fera une invasion, et inondera, et submergera, puis opérera sa retraite, et ils pousseront les hostilités jusqu\'à sa place forte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Alors le roi du midi s\'exaspérera, et se mettra en campagne, et lui livrera bataille, au roi du septentrion, et il mettra sur pied de grandes troupes, et les troupes seront placées sous sa conduite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Et ces troupes s\'enorgueilliront, et son cœur deviendra superbe, et il mettra en déroute des myriades; cependant il ne prévaudra pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Puis, le roi du septentrion reviendra à la charge, et mettra de grandes troupes sur pied, plus nombreuses que les premières, et au bout de quelques années il viendra, arrivera avec une grande armée et beaucoup de bagages.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Et dans ces temps-là il y aura une grande levée contre le roi du midi, et des factieux de ton peuple se soulèveront, en accomplissement de la vision, et ils succomberont.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Et le roi du septentrion s\'avancera, et il élèvera des terrasses, et s\'emparera d\'une ville forte; et les bataillons du midi ne tiendront pas, et sa troupe d\'élite, elle ne sera pas de force à résister.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Et celui qui aura marché contre lui, agira selon son bon plaisir, et personne ne lui tiendra tête; et il s\'établira dans le pays qui est l\'ornement [de la terre]; et il sera maître de consommer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Et il aura en vue d\'arriver à la suprématie sur tout son royaume, et à un accommodement avec lui, et il en viendra à bout; et il lui donnera la fille de la femme, dans le but de le perdre; mais ceci ne se réalisera pas, et ne lui réussira point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Et il ramènera ses regards sur les îles dont il prendra un grand nombre; mais un capitaine mettra fin à son propre opprobre, et fera en outre retomber sur lui l\'opprobre qu\'il avait reçu de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Et il tournera ses regards du côté des forteresses de ses États, et il chancellera, et tombera, et ne sera plus trouvé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Et à sa place s\'élèvera un [prince] qui fera parcourir par l\'exacteur l\'ornement de l\'empire, et quelque temps après il sera brisé, mais ce ne sera ni dans l\'ardeur de la mêlée, ni dans le combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Et à sa place s\'élèvera quelqu\'un d\'abject, et on ne lui aura point conféré la dignité royale, et il paraîtra inopinément, et s\'emparera de la royauté au moyen d\'adulations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Et les bataillons qui viendront submergeant, seront submergés par lui, et rompus, de même qu\'un prince confédéré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Car dès le moment de sa jonction avec lui, il mettra l\'artifice en œuvre, et il entrera en campagne, et il aura le dessus avec un petit nombre d\'hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'A l\'improviste il envahira, et même les portions les plus fertiles de la province, et il fera ce qui n\'avait été fait ni par ses pères, ni par les pères de ses pères; il leur distribuera du butin et des dépouilles et des biens, et il formera aussi des projets contre les places fortes, et cela jusqu\'à une certaine époque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Et il donnera essor à sa puissance et à son ambition contre le roi du midi avec de grandes forces, et le roi du midi s\'engagera dans la guerre avec une armée considérable et extrêmement forte, mais il ne tiendra pas tête; car on formera contre lui des complots.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Ceux-là même qui seront nourris de ses mets délicats, le feront tomber sous leurs coups. Et son armée se débandera, et il tombera beaucoup de morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Et quant à ces deux rois, en leur cœur ils ne penseront qu\'à se nuire; et à la même table ils parleront en mentant. Mais cela ne réussira pas, car la fin est remise à un terme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Et il reviendra dans ses États avec de grands biens, et son cœur sera hostile à l\'Alliance Sainte, et il agira, et il reviendra dans ses États.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'A une époque fixe il marchera de nouveau contre le midi, mais à la fin il n\'en sera pas comme au commencement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Car des navires de Cittim s\'avanceront contre lui, et il aura peur, puis il tournera sa rage contre l\'Alliance Sainte, et il agira, et derechef il s\'entendra avec les déserteurs de l\'Alliance Sainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Et de par lui seront levés des bataillons qui profaneront le sanctuaire, la citadelle, et aboliront le sacrifice perpétuel, et mettront en place l\'abomination du dévastateur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Et par des flatteries il entraînera à la défection les impies [opposés] à l\'Alliance; mais le peuple de ceux qui connaissent leur Dieu, prendra courage et agira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Et ceux qui dans le peuple ont de l\'intelligence, en éclaireront plusieurs, mais ils succomberont à l\'épée et aux flammes, à la captivité et au rapt pendant quelque temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Et pendant qu\'ils succomberont, ils seront aidés d\'un faible secours, et plusieurs se joindront à eux par hypocrisie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Et parmi les intelligents quelques-uns succomberont, afin qu\'il se fasse parmi eux une épuration, et un triage, et une purification jusqu\'au temps de la fin; car ceci encore est pour l\'époque fixée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Et le roi agira selon son bon plaisir, et il s\'insurgera et se soulèvera contre toute divinité, et il proférera des choses monstrueuses contre le Dieu des dieux, et il aura du succès jusqu\'à l\'achèvement des vengeances; car l\'arrêt recevra son exécution.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Il ne reconnaîtra pas même les dieux de ses pères, ni la Désirée des femmes, et il ne reconnaîtra aucun dieu quelconque, mais il les bravera tous:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'cependant il honorera le dieu des forteresses sur son piédestal, et au dieu inconnu de ses pères il rendra ses hommages avec de l\'or et de l\'argent, et des pierres précieuses et des joyaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'C\'est ainsi qu\'il procédera contre les citadelles fortifiées, avec le dieu étranger; à quiconque le reconnaîtra, il accordera de grands honneurs, et il les établira souverains de plusieurs, et leur distribuera des terres en récompense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Et au temps de la fin, le roi du midi se heurtera avec lui, et le roi du septentrion reviendra l\'assaillir avec des chars, et de la cavalerie, et une flotte nombreuse, et il s\'avancera dans les terres, et submergera et inondera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Il viendra aussi dans le pays qui est l\'ornement [de la terre], et des multitudes succomberont; mais ceux-ci s\'échapperont de ses mains, Edom et Moab, et l\'élite des enfants d\'Ammon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Et il portera la main sur les pays divers, et le pays d\'Egypte n\'échappera pas non plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Et il s\'emparera des trésors d\'or et d\'argent, et de tout ce que l\'Egypte a de précieux; et les Libyens et les Éthiopiens suivront ses pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Mais du levant et du nord des bruits viendront l\'effrayer, et il se mettra en campagne avec un grand courroux, pour en massacrer et en détruire plusieurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Et il dressera ses tentes pareilles à des palais entre la mer et le mont du saint ornement, mais il marche à sa fin, et nul ne l\'assiste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Et dans ce temps-là Michel, le grand prince, qui tient le parti des fils de ton peuple, se lèvera, et il y aura un temps d\'angoisse, tel qu\'il n\'y en a pas eu depuis l\'existence d\'un peuple jusqu\'à cette époque-là; mais dans le même temps ton peuple sera délivré, tous ceux qui sont inscrits dans le livre [de la vie].');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Et plusieurs de ceux qui dorment dans la poussière de la terre, se réveilleront, les uns pour une vie éternelle, et les autres pour l\'opprobre et une ignominie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Mais les intelligents brilleront de l\'éclat du firmament, et ceux qui auront conduit à la justice cette multitude, [brilleront] comme les étoiles éternellement, à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Mais toi, Daniel, serre les paroles et scelle le livre jusqu\'à l\'époque de la fin. Plusieurs le parcourront, et la connaissance augmentera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Et moi Daniel, je regardai, et voici, deux autres personnages étaient là, l\'un en deçà de la rive du fleuve, et l\'autre au delà de la rive du fleuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Et l\'un dit à l\'homme vêtu de lin qui se tenait en dessus des ondes du fleuve: A quand la fin de ces faits singuliers?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Et j\'entendis l\'homme vêtu de lin qui se tenait en dessus des ondes du fleuve, et levant la main droite et la main gauche vers le ciel, il fit ce serment par Celui dont la vie est éternelle: Encore un temps, [deux] temps et demi, et lorsque la dispersion d\'une partie du peuple saint sera consommée, tout cela s\'accomplira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Et j\'entendais, mais je ne comprenais pas, et je dis: Mon Seigneur, quelle issue auront ces choses?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Et il me dit: Va, Daniel; car les paroles resteront serrées et scellées jusqu\'à l\'époque de la fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Plusieurs seront triés, blanchis et épurés, et les impies pratiqueront l\'impiété, et aucun des impies n\'y prendra garde, mais les intelligents y prendront garde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Cependant, depuis le temps de l\'abolition du sacrifice perpétuel et du placement de l\'abomination du dévastateur, il y a mille deux cent quatre-vingt-dix jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Heureux celui qui attend, et atteint mille trois cent trente-cinq jours!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Mais toi, marche vers la fin, et tu te reposeras, et tu seras debout pour ton lot à la fin des jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'La parole de l\'Éternel qui fut adressée à Osée, fils de Beéri, dans le temps de Hosias, de Jotham, d\'Achaz, d\'Ézéchias, rois de Juda, et dans le temps de Jéroboam, fils de Joas, roi d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Quand l\'Éternel commença à parler à Osée, l\'Éternel dit à Osée: Va, prends-toi une femme impure et des enfants impurs, car le pays pour se livrer à l\'impureté quitte l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Et il alla, et prit Gomer, fille de Diblaïm; et elle devint enceinte et lui enfanta un fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Et l\'Éternel lui dit: Appelle-le du nom de Jizréel, car encore un peu de temps et je vengerai sur la maison de Jéhu le sang versé à Jizréel, et je mettrai fin au royaume de la maison d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'Et il arrivera dans ce jour-là que je briserai l\'arc d\'Israël dans la vallée de Jizréel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Et elle devint encore enceinte, et enfanta une fille. Et Il lui dit: Appelle-la du nom de Disgraciée, car désormais je ne donnerai plus ma grâce à la maison d\'Israël, pour lui pardonner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Mais à la maison de Juda je veux donner ma grâce, et la sauver par l\'Éternel, son Dieu, et je ne la sauverai ni par l\'arc, ni par l\'épée, ni par la guerre, ni par les chevaux, ni par la cavalerie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Et elle sevra Disgraciée, et elle conçut et enfanta un fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Et Il dit: Appelle-le du nom de Tu-n\'es-pas-mon-peuple; car vous n\'êtes pas mon peuple, et moi je ne suis plus à vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Mais elle ne reconnaît pas que c\'est moi qui lui ai donné le blé et le moût et l\'huile, et en abondance l\'argent et l\'or dont ils ont fait un Baal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'Aussi je retirerai mon blé dans sa saison et mon moût à son époque, et reprendrai ma laine et mon lin, couverture de sa nudité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Cependant le nombre des enfants d\'Israël sera comme le sable de la mer qui n\'est ni mesuré, ni compté; et dans le lieu même où il leur est dit: Vous n\'êtes pas mon peuple! il leur sera dit: Fils du Dieu vivant!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Et les enfants de Juda et les enfants d\'Israël seront rassemblés et réunis, et ils se donneront un seul chef, et ils reviendront de la terre étrangère; car grande sera la journée de Jisréel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Dites à vos frères: Mon-peuple! et à vos sœurs: Rentrée-en-grâce!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Faites le procès, le procès à votre mère! car elle n\'est point mon épouse et je ne suis point son époux; afin que de sa figure elle ôte son impudicité, et de ses mamelles ses adultères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'de peur que je ne la déshabille à nu et ne la rende telle qu\'au jour de sa naissance, et pareille au désert, pareille à une terre aride, et que je ne la fasse périr de soif:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'de ses fils non plus je n\'aurai pas pitié, car ils sont impudiques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'C\'est qu\'elle est impudique votre mère, infâme celle qui vous enfanta, car elle dit: Je veux suivre mes amants qui me donnent mon pain et mon eau, ma laine et mon lin, mon huile et mon breuvage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Aussi voici, je vais barrer son chemin avec des ronces et y élever un mur, afin qu\'elle ne trouve plus ses sentiers;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'et elle poursuivra ses amants, et ne les atteindra pas; elle les cherchera, mais ne les trouvera pas, et elle dira: Je veux aller et retourner à mon premier époux, car j\'étais mieux alors que maintenant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Mais elle ne reconnaît pas que c\'est moi qui lui ai donné le blé et le moût et l\'huile, et en abondance l\'argent et l\'or dont ils ont fait un Baal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Aussi je retirerai mon blé dans sa saison et mon moût à son époque, et reprendrai ma laine et mon lin, couverture de sa nudité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Et maintenant je dévoilerai sa honte aux yeux de ses amants, et nul ne la dégagera de ma main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Et je mettrai fin à toute sa joie, à ses fêtes, à ses nouvelles lunes et à ses sabbats, et à toutes ses solennités.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Et je dévasterai ses vignes et ses figuiers dont elle dit: C\'est un don que m\'ont fait mes amants! Et je les changerai en forêts, afin que les bêtes des champs les dévorent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Et je vengerai sur elle les jours des Baals, où elle les encensait, et se parait de son anneau et de son collier, et suivait ses amants, et m\'oubliait, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Aussi voici, je veux la gagner et la mener au désert et parler à son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Et dès lors je lui rendrai ses vignes et la vallée d\'Achor comme porte d\'espérance; et là elle chantera comme aux jours de sa jeunesse, et au jour qu\'elle sortit du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Et en ce jour-là, dit l\'Éternel, tu m\'appelleras: Mon époux! et tu ne m\'appelleras plus: Monseigneur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Et j\'ôterai de leur bouche les noms des Baals, afin qu\'on ne les rappelle plus par leurs noms.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Et pour eux je ferai en ce temps-là un pacte avec les bêtes des champs et avec les oiseaux des Cieux et avec les reptiles de la terre, et je briserai l\'arc et l\'épée et la guerre que je bannirai du pays, et je leur donnerai une demeure assurée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Et je te fiancerai à moi pour l\'éternité, et je te fiancerai à moi avec justice et droit, et avec grâce et miséricorde,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'et je te fiancerai à moi avec fidélité, et tu connaîtras l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Et en ce temps-là j\'exaucerai, dit l\'Éternel, j\'exaucerai les Cieux, et ils exauceront la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Et l\'Éternel me dit: Va encore, et aime une femme aimée d\'un amant et adultère, de l\'amour qu\'a l\'Éternel pour les enfants d\'Israël, qui eux aussi s\'adressent à d\'autres dieux et aiment les gâteaux de raisins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Et je me l\'achetai pour quinze pièces d\'argent et un homer d\'orge et un léthech d\'orge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Et je lui dis: Longtemps tu seras assise dans l\'attente de moi; tu ne te prostitueras point, et ne te livreras à aucun homme, et moi aussi j\'agirai de même envers toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Car longtemps les enfants d\'Israël resteront sans roi et sans prince, et sans sacrifice, et sans statue et sans éphod ni Théraphims.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Après cela les enfants d\'Israël reviendront et ils chercheront l\'Éternel leur Dieu, et David leur roi, et ils précipiteront leurs pas vers l\'Éternel et vers sa grâce, dans la suite des temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Écoutez la parole de l\'Éternel, enfants d\'Israël! car l\'Éternel fait le procès aux habitants du pays; car il n\'y a ni vérité, ni amour, ni connaissance de Dieu dans le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'On jure et l\'on ment, l\'on est homicide, et voleur et adultère; ils font des violences; au meurtre succède le meurtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Aussi, le pays est en deuil, et tous ses habitants dans la langueur, et les bêtes des champs et les oiseaux des Cieux, même les poissons de la mer disparaissent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Mais que nul ne conteste, et que nul ne reprenne! car ton peuple est comme ceux qui contestent contre les sacrificateurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Ainsi tu tomberas de jour, et avec toi le prophète aussi tombera de nuit, et je détruirai ta mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Mon peuple est détruit faute d\'avoir la connaissance... Et toi, puisque tu dédaignes la connaissance, je te dédaignerai aussi, et tu ne seras plus mon sacrificateur, et puisque tu oublies la loi de ton Dieu, j\'oublierai aussi tes enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Plus ils s\'accroissent, plus ils pèchent contre moi: je changerai leur gloire en ignominie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Du péché de mon peuple ils tirent leur subsistance, et de son crime ils sont avides.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Aussi en sera-t-il du peuple comme du sacrificateur, et je les châtierai de leur conduite et je leur rendrai ce qu\'ils ont fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Ils mangeront et ne seront point rassasiés; ils seront impudiques et ne se multiplieront pas, car ils abandonnent le culte de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'L\'impudicité et le vin et le moût ôtent le sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Mon peuple interroge son bois, et c\'est son bâton qui l\'avise, car l\'esprit d\'impudicité les a séduits; adultères, ils désertent leur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Sur les cimes des montagnes ils sacrifient, et sur les collines ils encensent, sous le chêne et le peuplier et le térébinthe, parce que l\'ombrage en est beau; c\'est pourquoi vos filles sont impudiques et vos brus adultères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Je ne saurais punir vos filles de s\'être prostituées, ni vos brus d\'avoir commis adultère; car eux-mêmes vont à l\'écart avec des prostituées et sacrifient avec des courtisanes, et le peuple insensé court à sa perte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Si tu es impudique, ô Israël, que Juda ne se rende pas coupable! ne venez point à Guilgal! et ne montez point à Bethaven, et ne jurez point par la vie de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Car telle une génisse indocile, telle Israël est indocile; maintenant l\'Éternel les laissera paître comme des agneaux dans un pays ouvert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Éphraïm s\'est alliée aux idoles: laisse-la faire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'sitôt qu\'est enlevée la table où ils boivent, ils se livrent aux impudicités; leurs princes ont pour l\'infamie un amour singulier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Le vent l\'emporte de ses ailes, et ils sont confus de leurs sacrifices.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Entendez-le, sacrificateurs, écoute-le, maison d\'Israël! et maison du roi, sois-y attentive! car pour vous il s\'agit du jugement; car vous fûtes un filet à Mitspa, et une toile tendue sur le Thabor.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Ils accumulent les sacrifices coupables; mais moi [j\'accumulerai] les châtiments sur eux tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Je connais Éphraïm, et Israël ne m\'est point caché; car maintenant tu te prostitues, Éphraïm, et Israël se souille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Ils ne font point leur œuvre de revenir à leur Dieu, car l\'esprit d\'impudicité est en eux, et de l\'Éternel ils n\'ont nulle connaissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Ainsi l\'orgueil d\'Israël s\'exprime sur son visage, et Israël et Éphraïm tomberont par l\'effet de leur péché; avec eux tombera aussi Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Avec leurs brebis et leurs taureaux ils viendront chercher l\'Éternel et ne le trouveront pas; Il se dérobe à eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'A l\'Éternel ils furent infidèles; car ils donnèrent naissance à des enfants bâtards; maintenant il ne faudra qu\'une nouvelle lune pour les dévorer, eux et leurs possessions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Sonnez de la trompette en Guibha, et du clairon à Rama! pousse des cris, Bethaven! on est à ta poursuite, Benjamin!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Éphraïm sera un désert au jour du châtiment; parmi les tribus d\'Israël j\'annonce une chose certaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Les princes de Juda sont comme ceux qui déplacent les bornes; sur eux je verserai comme les eaux ma colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Éphraïm est accablé, écrasé par le jugement, car il se plaît à suivre la voie qu\'il se trace.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Et je suis comme une teigne pour Éphraïm, comme une carie pour la maison de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Et Éphraïm voit sa maladie, et Juda sa blessure, et Éphraïm se rend auprès d\'Assur, et députe vers un roi qui le venge; mais il ne pourra vous guérir, ni enlever votre plaie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Car je suis comme un lion pour Éphraïm, et comme un jeune lion pour la maison de Juda; moi, moi je déchire, puis je m\'en vais, j\'emporte, et personne qui sauve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Je m\'en vais et retourne à ma demeure, jusqu\'à ce qu\'ils se reconnaissent et cherchent ma face; dans leur angoisse ils voudront me trouver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, '« Venez, retournons à l\'Éternel, car Il a déchiré et Il nous guérira, Il a frappé et Il bandera nos plaies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Il nous rendra la vie dans deux jours, et le troisième Il nous mettra debout, afin que nous vivions devant lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Apprenons donc à connaître, appliquons-nous à connaître l\'Éternel! Tel que celui de l\'aurore, son lever est certain; Il viendra à nous comme la rosée, comme la seconde pluie qui arrose la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Que te ferai-je, Éphraïm, que te ferai-je, Juda? Car votre piété est comme les vapeurs du matin, et comme la rosée qui bientôt s\'évanouit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Pour cela je les frappe par mes prophètes, je les tue par les paroles de ma bouche, et tes châtiments apparaîtront comme la lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Car j\'aime la piété et non les sacrifices, et la connaissance de Dieu plus que les victimes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Mais eux, comme Adam, violent l\'alliance; ici même ils me sont infidèles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Galaad est une ville de malfaiteurs, elle porte des traces de sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Telle une bande de brigands aux aguets, telle est la confrérie des sacrificateurs; ils tuent sur le chemin de Sichem, oui, ils commettent des crimes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Dans la maison d\'Israël je vois des horreurs; c\'est la prostitution d\'Éphraïm; Israël est souillé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'A toi aussi, Juda, est préparée une moisson, quand je ramènerai les captifs de mon peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Quand je voulus guérir Israël, alors se révélèrent le crime d\'Éphraïm et les méfaits de Samarie. Car ils font des fraudes et les voleurs s\'insinuent, et des bandes de pillards se répandent au dehors.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Et ils ne se disent pas en leur cœur que de tous leurs crimes je garde la mémoire: or, leurs forfaits les entourent, ils sont présents à mes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Par leur méchanceté ils font la joie du roi, et par leurs mensonges celle des princes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Tous ils sont adultères, comme un four chauffé par le boulanger: il cesse de le chauffer depuis qu\'il pétrit la pâte jusqu\'à ce qu\'elle fermente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Au jour de notre roi les princes se rendent malades dans l\'ardeur de l\'ivresse; il tend la main aux moqueurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Car leur cœur est comme un four, quand ils l\'appliquent à leurs embûches; toute la nuit dort leur boulanger; le matin le four brûle comme un feu allumé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Tous ils sont ardents comme le four, et ils dévorent leurs juges; tous leurs rois tombent, aucun d\'eux ne m\'invoque!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Éphraïm aux peuples se mêle, Éphraïm est une galette qui n\'est pas retournée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'des étrangers consument sa force et il ne le sent pas; les cheveux blancs sont aussi semés sur sa tête, et il ne le sent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Ainsi l\'orgueil d\'Israël, s\'exprime sur son visage, cependant ils ne reviennent point à l\'Éternel leur Dieu, et ne le cherchent point malgré tout cela.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Et Éphraïm est comme la colombe facile à tromper, sans intelligence, ils implorent l\'Egypte, vont en Assyrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Puisqu\'ils y vont, j\'étends sur eux mon filet, comme les oiseaux des Cieux je les précipite, les châtie comme je l\'ai annoncé à leur assemblée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Malheur à eux! car ils me fuient; ruine sur eux! car ils se rebellent contre moi. Moi je tente de les sauver, et eux ils se montrent menteurs pour moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'ce n\'est pas à moi qu\'ils crient du fond de leur cœur, quand ils se lamentent sur leurs lits pour le blé et le moût; ils se détournent, s\'éloignent de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Je formai, fortifiai leurs bras, et contre moi ils méditent le mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Ils se retournent, mais non pas vers les lieux très hauts; ils sont comme un arc trompeur; leurs princes périront par l\'épée à cause des bravades de leur langue; c\'est ce qui en fera la risée du pays d\'Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Embouche la trompette! Comme un aigle, [il fond] sur la maison de l\'Éternel, parce qu\'ils ont violé mon alliance et déserté ma loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Ils me crieront: Mon Dieu! nous, Israël, nous te reconnaissons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Israël a répudié le bien; l\'ennemi le poursuivra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Ils ont élu des rois, mais non pas de par moi, et des princes, mais à mon insu. De leur argent et de leur or ils se sont fait des idoles, pour être détruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Odieux est ton veau, Samarie! Ma colère s\'allume contre eux; combien de temps seront-ils incapables d\'innocence?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Car c\'est d\'Israël qu\'il vient aussi; un sculpteur l\'a fait, et ce n\'est pas un Dieu. Car il sera mis en pièces, le veau de Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Car ils sèment du vent, et moissonnent la tempête: ils n\'ont point de blé, et le grain ne donne point de farine; en donnât-il, des étrangers la consumeraient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Israël est consumé; maintenant ils sont parmi les peuples comme un vase dont personne ne fait cas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Car ils vont en Assyrie: l\'onagre se suffit seul à lui-même, Éphraïm se fait par des dons gagner des amants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Puisqu\'ils font répandre leurs dons parmi les peuples, je rassemblerai ceux-ci, qui dans peu les délivreront du fardeau d\'être roi, d\'être princes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Car Éphraïm a multiplié ses autels pour pécher, et ces autels sont devenus un péché pour lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'J\'avais écrit pour lui mes lois par milliers; elles sont estimées comme choses étrangères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Ils font des sacrifices de mes offrandes, ils sacrifient la chair et en mangent; l\'Éternel n\'y prend point de plaisir. Maintenant Il se rappelle leur crime et punit leurs péchés; ils retourneront en Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Et Israël a oublié son créateur et bâti des palais, et Juda a élevé nombre de villes fortes; mais j\'enverrai le feu dans leurs villes, et il dévorera leurs palais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Ne te réjouis pas, Israël, jusqu\'à l\'allégresse, comme les autres peuples; car tu es adultère, tu désertes ton Dieu; car tu aimes à recevoir le salaire de l\'impudicité sur toutes les aires à blé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Ni aire, ni pressoir ne les nourrira, et le moût trompera leur attente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Ils ne resteront pas dans le pays de l\'Éternel; Éphraïm doit retourner en Egypte, et manger en Assyrie des aliments immondes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Ils ne feront plus à l\'Éternel des libations de vin, et leurs victimes ne lui seront plus agréables; elles seront pour eux comme le pain du deuil: quiconque en mange se souille; car leur pain ne sera que pour eux, et n\'entrera point dans la maison de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Que ferez-vous aux jours solennels, et aux jours des fêtes de l\'Éternel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Car voici, ils vont émigrer de leur pays dévasté, l\'Egypte les recueillera, Memphis leur donnera la sépulture. De tout ce qu\'ils ont de précieux en argent les orties s\'empareront, et les ronces seront dans leurs cabanes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Ils arrivent les jours du châtiment, ils arrivent les jours de la rétribution! Israël le saura! Le prophète est en démence, [dites-vous,] l\'homme inspiré en délire! C\'est à cause de la grandeur de ton crime et de tous les actes odieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Éphraïm est aux aguets contre mon Dieu; le prophète rencontre un filet d\'oiseleur sur toutes ses voies, la haine [le poursuit] dans la maison de son Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Profonde est leur corruption; comme aux jours de Guibha. Il se souviendra de leur crime, châtiera leurs péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Je trouvai Israël comme des raisins dans le désert, je vis vos pères de l\'œil dont on regarde des primeurs sur un figuier qui donne ses premiers fruits; mais eux ils allèrent à Baal-Péhor, et se vouèrent à l\'infamie et devinrent abominables comme leurs amours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Comme un oiseau s\'envolera la gloire d\'Éphraïm; plus de naissances, plus de grossesses, plus de conception.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Quand même ils élèveraient des fils, je les ferai être sans enfants, pour qu\'il n\'y ait plus d\'hommes. Oui, malheur à eux-mêmes, quand je m\'éloignerai d\'eux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Éphraïm, aussi loin que porte ma vue jusqu\'à Tyr, est planté dans une campagne fertile, et les fils d\'Éphraïm en seront tirés et livrés au meurtrier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Donne-leur, ô Éternel!... que leur donneras-tu?... donne-leur un sein qui avorte et des mamelles arides.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Toute leur méchanceté [se montre] à Guilgal; oui, là, ils me sont odieux par la malice de leurs actions; de ma maison je les chasserai, et n\'aurai plus d\'amour pour eux; tous leurs chefs sont réfractaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Éphraïm est frappé; sa racine sèche; ils ne porteront plus de fruit; quand même ils auront des enfants, je ferai périr le doux fruit de leur sein.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Mon Dieu les rejettera, parce qu\'ils ne lui sont pas obéissants, et ils seront fugitifs parmi les peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Israël est une vigne développée qui se charge de fruits: plus il a de fruits, plus il bâtit d\'autels; plus son pays est beau, plus il élève de belles statues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Leur cœur s\'est partagé; ils vont en être punis; Il renversera leurs autels, ravagera leurs statues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Car ils seront réduits à dire: Nous sommes sans roi, car nous n\'avons pas craint l\'Éternel; et le roi que peut-il faire pour nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Ils prononcent des mots, font des faux serments, concluent des alliances; aussi leur peine surgira, comme un pavot, dans les sillons des champs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Pour le veau de Bethaven l\'habitant de Samarie est dans la crainte; oui, son peuple prend le deuil pour lui, et ses prêtres tremblent pour lui, à cause de sa gloire, parce qu\'elle le quitte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Car en Assyrie on le portera lui-même, comme une offrande au Roi vengeur; la honte saisira Éphraïm, et Israël rougira du parti qu\'il a pris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'C\'en est fait de Samarie, de son roi, comme d\'un ais flottant sur les eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Et les hauts lieux de Bethaven, péché d\'Israël, seront dévastés; la ronce et le chardon croîtront sur leurs autels, et ils diront aux montagnes: Recouvrez-nous! et aux collines: Croulez sur nous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Dès le temps de Guibha tu as péché, Israël! Là ils restèrent debout; la guerre faite à Guibha contre les méchants ne les atteignit pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'A mon gré je les châtierai (et des peuples s\'uniront contre eux) les enchaînant à leurs deux crimes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Éphraïm est une génisse dressée, qui aime à fouler le grain; mais je marcherai sur son beau cou; j\'attellerai Éphraïm, Juda labourera, Jacob hersera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Semez en vue de la justice, et vous aurez une moisson conforme à la piété! Faites-vous des novales! Et c\'est le temps de chercher l\'Éternel, jusqu\'à ce qu\'il vienne et vous donne une rosée de justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Vous avez cultivé l\'impiété, récolté le mal, mangé le fruit du mensonge; car tu as eu confiance dans ta voie, dans le nombre de tes guerriers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Aussi un tumulte s\'élèvera contre tes peuples, et tous tes forts seront ravagés, comme Betharbel fut ravagée par Salman au jour de la bataille, quand la mère avec ses enfants fut écrasée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Voilà ce que vous produit Béthel à cause de votre extrême méchanceté. Une aurore, et c\'en est fait du roi d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Quand Israël était enfant, je l\'aimai, et de l\'Egypte j\'appelai mon fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Quand [mes serviteurs] leur faisaient des appels, ils se détournaient d\'eux, aux Baals ils sacrifiaient et aux idoles ils offraient de l\'encens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Cependant je menai Éphraïm à la lisière, le soutenant par ses bras; mais ils ne reconnurent point que je voulais les guérir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Je les tirai avec des liens d\'humanité, avec des cordages d\'amour, je fus pour eux comme quelqu\'un qui desserre le joug près de leur bouche, j\'étendis la main et leur donnai à manger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Ils ne retourneront pas en Egypte, mais c\'est l\'Assyrien qui sera leur roi, puisqu\'ils ne veulent pas revenir à moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Et l\'épée fondra sur leurs villes, et détruira leurs verrous, et dévorera à cause du parti qu\'ils ont pris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Mon peuple s\'applique à s\'éloigner de moi; c\'est aux lieux très hauts qu\'on les convie, mais nul ne s\'y élève.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Comment dois-je te traiter, Éphraïm? en agir avec toi, Israël? Quoi! dois-je te traiter comme Adma, t\'assimiler à Tséboïm? Mon cœur se retourne en moi, toutes mes compassions s\'allument;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'je ne donnerai pas suite à l\'ardeur de mon courroux; je ne détruirai pas de nouveau Éphraïm. car je suis Dieu et non pas un homme! je suis le Saint au milieu de toi, et je ne viens point avec colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'A la fin ils suivront l\'Éternel; comme un lion Il rugira; car Il rugira, et de l\'occident les fils accourront,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'ils accourront comme des oiseaux de l\'Egypte, et comme la colombe du pays d\'Assyrie, et je les ferai habiter dans leurs maisons, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, 'Éphraïm m\'entoure de mensonge, et la maison d\'Israël de fraude, et Juda court encore de côtés et d\'autres, quoiqu\'il ait Dieu, qu\'il ait le Saint fidèle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Éphraïm se repaît de vent, et poursuit le vent d\'est, toujours il entasse mensonge et violence, avec l\'Assyrie ils font alliance et l\'huile est portée en Egypte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Aussi l\'Éternel est en procès avec Juda, et va punir Jacob de sa conduite, selon ses œuvres Il le rétribuera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Dans le sein maternel Jacob saisit son frère au talon, et par sa force il lutta avec Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'il lutta avec l\'ange, et eut l\'avantage; il pleura et le supplia, à Béthel il le trouva, et là il nous parla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Et l\'Éternel est le Dieu des armées, son nom est l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Toi donc, reviens à ton Dieu, garde la piété et la justice, et espère dans ton Dieu constamment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Cananéen, dans sa main il a une balance fausse; il aime à frauder.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Ainsi parle Éphraïm: Oui, je me suis enrichi, j\'ai acquis de l\'opulence! dans tous mes gains on ne trouvera rien d\'inique, rien qui soit un péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Mais moi, l\'Éternel, ton Dieu depuis le pays d\'Egypte, je te laisse encore habiter sous tes tentes comme aux jours de tes fêtes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'et je parle aux prophètes et je multiplie les révélations, et par les prophètes je propose des paraboles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'A Galaad règne l\'idolâtrie; c\'est méchanceté pure; à Guilgal ils sacrifient des taureaux; eux aussi ont autant d\'autels qu\'il y a de monceaux de pierres sur les sillons des champs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Et Jacob s\'enfuit aux campagnes d\'Aram, et Israël fut serviteur pour une femme, et pour une femme il fut gardien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Et par un prophète l\'Éternel ramena Israël de l\'Egypte, et par un prophète il fut gardé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Mais Éphraïm a fait [à l\'Éternel] une offense amère; aussi laissera-t-Il ses meurtres peser sur lui, et son Seigneur lui rendra l\'opprobre qu\'il a reçu de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Quand Éphraïm parla, ce fut une terreur; il s\'éleva en Israël; mais il fut coupable en servant Baal et périt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Et maintenant ils continuent à pécher et ils se font des statues, et de leur argent, à leur idée, des images, le tout œuvre d\'artisan. D\'elles ils disent: Que quiconque sacrifie, embrasse les veaux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Aussi seront-ils comme la nuée du matin, comme la rosée aussitôt évanouie, comme la balle emportée de l\'aire, et comme la fumée hors de la cheminée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Mais je suis l\'Éternel, ton Dieu, dès le pays d\'Egypte, et tu ne dois connaître d\'autre Dieu que moi, et il n\'y a de sauveur que moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Je pris soin de toi dans le désert, dans la terre aride.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Comme je les faisais paître, ils furent rassasiés, et leur cœur s\'éleva: c\'est pourquoi ils m\'oublièrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Aussi serai-je pour eux comme un lion, comme la panthère sur la route je serai aux aguets;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'je fondrai sur eux comme une ourse qui a perdu ses petits, et je déchirerai la clôture de leur cœur, et les dévorerai là, comme une lionne; les bêtes des champs les dépeceront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Ce qui te perd, Israël, c\'est d\'être contre moi, contre ton aide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Où est donc ton roi? qu\'il te délivre dans toutes tes villes! et tes juges? Cependant tu disais: Donne-moi un roi et des princes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Je te donne un roi dans ma colère, et te l\'enlève dans mon courroux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Le crime d\'Éphraïm est serré, et son péché mis en réserve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Les douleurs de l\'enfantement lui viendront; c\'est un enfant stupide, car au bon moment il ne paraît pas aux portes de la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'De l\'Enfer je veux les sauver, et de la mort les délivrer. Mort, où est ton fléau? Enfer, où est ta peste? Le repentir se dérobe à ma vue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Sans doute il est fertile au milieu de ses frères; mais le vent d\'est arrive; le vent de l\'Éternel monte du désert; sa source sera tarie et sa fontaine mise à sec. Il saccagera le trésor de toute sa vaisselle précieuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Samarie sera punie, car elle fut rebelle à son Dieu; ils périront par l\'épée; ses enfants seront écrasés, et ses femmes enceintes éventrées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Reviens, Israël, à l\'Éternel ton Dieu! car par ton crime tu préparas ta chute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Prenez avec vous des paroles [pour offrande] et revenez à l\'Éternel! Dites-lui: « Pardonne tous les crimes, et agrée que nous t\'offrions pour victimes nos promesses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'L\'Assyrie ne sera plus notre aide; nous ne monterons plus les chevaux et nous n\'appellerons plus l\'œuvre de nos mains notre Dieu, puisque auprès de toi l\'orphelin trouve compassion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Je réparerai leur révolte; je les aimerai spontanément, car ma colère se détourne d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Je serai pour Israël comme la rosée, il fleurira comme un lis, et prendra racine comme le Liban;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'ses jets pousseront, sa magnificence sera égale à l\'olivier, et il aura un parfum comme le Liban.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'On reviendra habiter à son ombre, ranimer les blés, et verdir comme la vigne, et son renom sera comme celui du vin du Liban.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Éphraïm, qu\'ai-je encore à faire avec les idoles? Je veux l\'exaucer et avoir les yeux sur lui, et être pour lui comme un cyprès verdoyant; de moi tu recevras tes fruits. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Que celui qui est sage, comprenne ces choses! intelligent, qu\'il les connaisse! car les voies de l\'Éternel sont droites, et les justes y marchent, mais les pécheurs y trébuchent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'La parole de l\'Éternel qui fut adressée à Joël, fils de Péthuel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Entendez-le, vieillards, et prêtez l\'oreille, vous tous habitants du pays! Arriva-t-il rien de pareil en vos jours, ou aux jours de vos pères?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Faites-en le récit à vos enfants, et vos enfants à leurs enfants, et leurs enfants à l\'âge qui suivra!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Ce qu\'a laissé le bruche, la locuste le dévore, et ce qu\'a laissé la locuste, l\'attelabe le dévore, et ce qu\'a laissé l\'attelabe, la sauterelle le dévore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Réveillez-vous, vous qui êtes dans l\'ivresse, et pleurez! et vous tous, buveurs de vin, gémissez sur le moût, de ce qu\'il vous est ôté de la bouche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Car un peuple envahit mon pays, puissant et innombrable; ses dents sont des dents de lion, et il a la denture de la lionne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'il ravage ma vigne et ronge mon figuier; il l\'écorce et en jonche la terre; ses jets restent blancs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Gémis, [terre!] comme la vierge qui revêt le cilice pour l\'époux de sa jeunesse!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Offrandes et libations sont ôtées à la maison de l\'Éternel; les sacrificateurs, ministres de l\'Éternel, sont dans le deuil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Les campagnes sont dévastées, le pays est en deuil, car les blés sont dévastés, la vigne séchée, l\'olivier flétri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Les laboureurs sont confus, et les vignerons gémissent, à cause du froment et de l\'orge, parce que la moisson des champs a péri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'La vigne est séchée et le figuier flétri; le grenadier, le palmier et le pommier aussi, tous les arbres de la campagne ont séché; oui, la joie est tarie pour les enfants d\'Adam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Ceignez [le cilice] et gémissez, ô prêtres! lamentez-vous, ministres de l\'autel! Venez, passez la nuit sous le cilice, ministres de mon Dieu! Car les offrandes et les libations sont retranchées à la maison de votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Consacrez un jeûne! convoquez l\'assemblée! réunissez les anciens, tous les habitants du pays dans la maison de l\'Éternel votre Dieu, et criez à l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Jour funeste! car le jour de l\'Éternel est proche, et comme un ravage de par le Tout-Puissant il arrive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Sous nos yeux les subsistances ne sont-elles pas enlevées? de la maison de notre Dieu la joie et l\'allégresse n\'ont-elles pas disparu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Les grains semés pourrissent sous leurs glèbes, les magasins sont déserts et les greniers détruits, car les blés ont séché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Comme le bétail soupire! les troupeaux de bœufs sont angoissés, car ils n\'ont point de pâturages; même les troupeaux de brebis en pâtissent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Éternel, je t\'invoque, car un feu dévore les pacages de la plaine, et une flamme brûle tous les arbres des campagnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'les bêtes des champs aussi languissent après toi, car l\'eau des ruisseaux est tarie, et un feu dévore les pacages de la plaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Sonnez de la trompette en Sion, et donnez l\'alarme sur ma sainte montagne! que tous les habitants du pays tremblent! car le jour de l\'Éternel arrive, car il est proche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'jour ténébreux et sombre, jour de nuées et d\'obscurité. Telle s\'étend l\'aurore sur les montagnes, tel [s\'avance] un peuple nombreux et fort, comme il n\'y en eut point dès les temps éternels et il n\'y en aura plus après lui dans les années des âges et des âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Devant lui le feu dévore, et derrière lui la flamme embrase; le pays avant lui était comme un jardin d\'Éden, et après lui c\'est la désolation d\'un désert, et rien ne lui échappe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Tel l\'aspect des chevaux, tel est son aspect, et ils courent comme des cavaliers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Avec le fracas des chars sur les cimes des montagnes ils bondissent; c\'est le bruissement de la flamme du feu consumant le chaume; c\'est une forte armée rangée en bataille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Devant eux les peuples tremblent, et tous les visages pâlissent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Ils courent comme des héros, comme des guerriers ils escaladent les murs; chacun d\'eux suit sa route, et ils ne changent point l\'ordre de leur marche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'ils ne se poussent point l\'un l\'autre, chacun suit sa voie, ils se précipitent à travers les traits, et ne rompent point leurs rangs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'ils parcourent la ville, grimpent aux murailles, envahissent les maisons, et entrent par les fenêtres comme le larron.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Devant eux la terre tremble, les Cieux s\'ébranlent, le soleil et la lune s\'assombrissent, et les étoiles retirent leur éclat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Et l\'Éternel fait entendre sa voix devant son armée, car son camp est immense, et l\'exécuteur de sa parole puissant; car grande est la journée de l\'Éternel, et très redoutable: qui la soutiendrait?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Mais, encore à présent, dit l\'Éternel, revenez à moi de tout votre cœur, et avec jeûne et avec larmes et gémissements!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Déchirez vos cœurs et non vos vêtements, et revenez à l\'Éternel votre Dieu, car Il est clément et pitoyable, patient et plein d\'amour, et Il envoie les maux à regret.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Qui sait? Il reviendra peut-être et aura du regret, et laissera après lui des bénédictions, des offrandes et des libations pour l\'Éternel votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Sonnez de la trompette en Sion! consacrez un jeûne! convoquez une assemblée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'réunissez le peuple, formez une sainte convocation! assemblez les vieillards, réunissez les enfants et les nourrissons à la mamelle! que l\'époux quitte sa chambre, et l\'épouse son lit nuptial!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'qu\'entre le vestibule et l\'autel pleurent les sacrificateurs, ministres de l\'Éternel, et qu\'ils disent: Éternel, épargne ton peuple, et ne livre pas ton patrimoine à l\'opprobre, pour qu\'il devienne la fable des peuples! pourquoi dirait-on parmi les nations: Où est leur Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Alors l\'Éternel prendra de l\'intérêt pour son pays et épargnera son peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'et l\'Éternel répondra et dira à son peuple: Voici, je vous enverrai le blé et le moût et l\'huile, et vous vous en rassasierez, et je ne vous livrerai plus à l\'opprobre parmi les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'J\'éloignerai de vous cet ennemi du nord et le repousserai dans une terre aride et déserte, son avant-garde dans la mer d\'orient, et son arrière-garde dans la mer d\'occident, afin que son infection s\'élève, et que sa puanteur s\'élève, parce qu\'ils se sont montrés si glorieux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'N\'aie point de peur, ô pays! sois dans l\'allégresse et la joie! car l\'Éternel se montrera glorieux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'N\'ayez point de peur, bêtes des champs, car les pacages de la plaine verdiront, car les arbres donneront leurs fruits, le figuier et la vigne donneront leurs richesses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Et vous, enfants de Sion, réjouissez-vous, félicitez-vous de l\'Éternel votre Dieu! car Il vous donnera un maître de justice, et Il vous enverra les flots de la pluie d\'automne et de la pluie du printemps, à l\'entrée de la saison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'Et les aires se rempliront de blé, et les cuves regorgeront de moût et d\'huile;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'et je compenserai pour vous les années dévorées par la locuste, l\'attelabe, la sauterelle et le bruche, ma grande armée envoyée par moi contre vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Et vous mangerez et serez rassasiés, et vous louerez le nom de l\'Éternel votre Dieu, qui aura fait pour vous des choses merveilleuses, et mon peuple ne sera plus confus, jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Et vous reconnaîtrez que je suis au milieu d\'Israël, et que moi, l\'Éternel, je suis votre Dieu, et qu\'il n\'y en a point d\'autre, et mon peuple. ne sera plus confus, jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'Et dans la suite il arrivera que je verserai mon Esprit sur toute chair, et vos fils et vos filles prophétiseront, et vos vieillards auront des songes et vos jeunes gens des visions;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'et aussi sur les serviteurs et les servantes en ces jours-là je verserai mon Esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'Et je ferai paraître des prodiges dans les Cieux et sur la terre; il y aura du sang et du feu et des colonnes de fumée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'le soleil sera changé en ténèbres et la lune en sang, avant que vienne la journée de l\'Éternel, la grande et redoutable journée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'Alors quiconque invoquera le nom de l\'Éternel sera sauvé; car sur la montagne de Sion et à Jérusalem il y aura des réchappés, comme l\'a dit l\'Éternel, et parmi les survivants sera celui qui invoquera l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Car voici, dans ces jours et ces temps-là, alors je ramènerai les captifs de Juda et de Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'et je rassemblerai tous les peuples et les ferai descendre dans la vallée de Josaphat, et je leur ferai là leur procès au sujet d\'Israël, mon peuple et mon héritage, qu\'ils ont disséminé parmi les peuples;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'et ils se sont partagé mon pays et ont tiré mon peuple au sort, et ils ont donné l\'enfant comme salaire à la prostituée, et vendu la jeune fille pour du vin, et ils l\'ont bu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Et vous aussi, que me voulez-vous, Tyr et Sidon, et tous les cantons de la Philistie? Voulez-vous user de représailles envers moi? Si vous usez de représailles envers moi, vite, aussitôt, je ferai retomber sur vous ce que vous m\'aurez fait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'vous qui avez pris mon argent et mon or, et transporté dans vos temples mes joyaux précieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'et vendu aux Grecs les enfants de Juda et de Jérusalem pour les éloigner de leurs frontières.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Voici, je les ferai se lever du lieu où vous les avez vendus, et je ferai retomber sur vos têtes ce que vous avez fait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'et je vendrai vos fils et vos filles entre les mains des enfants de Juda, qui les vendront aux Sabéens, peuple reculé, car l\'Éternel a prononcé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Publiez ceci parmi les peuples: Préparez la guerre! faites lever les héros! qu\'ils approchent, qu\'ils montent, tous les hommes de guerre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Forgez vos faucilles en épées et vos serpes en javelots! que le débile dise: Je suis un héros!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Hâtez-vous et venez, tous il les peuples d\'alentour! et qu\'ils s\'assemblent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Éternel, fais descendre là tes héros! que les peuples se lèvent et s\'avancent dans la vallée de Josaphat! car là je siégerai pour juger tous les peuples d\'alentour!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Mettez la faucille aux blés, car la moisson est mûre. Venez! foulez! car le pressoir est plein, les cuves regorgent; car grande fut leur méchanceté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Il y a foule, foule dans la vallée du jugement! car la journée de l\'Éternel est proche dans la vallée du jugement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Le soleil et la lune s\'obscurcissent, et les étoiles retirent leur éclat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'Et l\'Éternel rugit de Sion, et de Jérusalem Il fait entendre sa voix, et les Cieux et la terre tremblent. Mais l\'Éternel est un refuge pour son peuple et un boulevard pour les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'Et vous reconnaîtrez que moi, l\'Éternel, je suis votre Dieu habitant en Sion, ma sainte montagne; et Jérusalem sera un sanctuaire, et des étrangers n\'y pénétreront plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'Et dans ce temps-là les montagnes ruisselleront de moût et les collines seront découlantes de lait, et tous les ruisseaux de Juda auront des eaux courantes, et une source sortira de la maison de l\'Éternel, et abreuvera la vallée de Sittim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'L\'Egypte deviendra un désert, et Édom une terre désolée, à cause des violences faites aux enfants de Juda dans le pays desquels ils ont versé le sang innocent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Mais Juda sera habité éternellement et Jérusalem dans tous les âges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'Et je vengerai leur sang que je n\'ai point encore vengé, et l\'Éternel habitera en Sion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Discours d\'Amos, qui était parmi les bergers de Thékoa, lesquels lui furent révélés en vision sur Israël, au temps de Hosias, roi de Juda, et au temps de Jéroboam, fils de Joas, roi d\'Israël, deux ans avant le tremblement de terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Et il dit: L\'Éternel de Sion pousse un rugissement, et de Jérusalem fait entendre sa voix, et le deuil est sur les pacages des bergers, et la sécheresse sur la cime du Carmel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Ainsi parle l\'Éternel: A cause de trois, de quatre crimes de Damas, je ne m\'en rétracte point, parce qu\'ils ont foulé Galaad sous des traîneaux de fer:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'je lancerai donc un feu dans la maison d\'Hazaël, pour qu\'il dévore les palais de Benhadad,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'et je briserai les verrous de Damas, et exterminerai de la vallée des idoles les habitants, et de Beth-Eden celui qui tient le sceptre, et le peuple d\'Aram s\'en ira captif à Kir, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Ainsi parle l\'Éternel: A cause de trois, de quatre crimes de Gaza, je ne m\'en rétracte point, parce qu\'ils ont emmené des captifs en grand nombre pour les livrer à Édom:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Je lancerai donc un feu dans les murs de Gaza, pour qu\'il dévore ses palais,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'et d\'Asdod j\'exterminerai les habitants, et d\'Askalon celui qui tient le sceptre, et je tournerai ma main contre Hécron, afin que périsse le reste des Philistins, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Ainsi parle l\'Éternel: A cause de trois, de quatre crimes de Tyr, je ne m\'en rétracte point, parce qu\'ils ont livré des captifs en grand nombre à Édom, et n\'ont point pensé à leur alliance avec des frères:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'j\'enverrai donc un feu dans les murs de Tyr, afin qu\'il dévore ses palais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Ainsi parle l\'Éternel: A cause de trois, de quatre crimes d\'Édom, je ne m\'en rétracte point, parce qu\'avec l\'épée il a poursuivi ses frères et qu\'il a étouffé son affection, et que sa fureur est toujours acharnée, et qu\'il garde sa colère à jamais:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'je lancerai donc un feu en Théman, afin qu\'il dévore les palais de Botsra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Ainsi parle l\'Éternel: A cause de trois, de quatre crimes des enfants d\'Ammon, je ne m\'en rétracte point, parce qu\'ils ont éventré les femmes enceintes de Galaad, pour étendre leurs frontières:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'j\'allumerai donc un feu dans les murs de Rabbah, pour qu\'il dévore ses palais au milieu des cris de guerre au jour de la bataille, au bruit de l\'ouragan, au jour de la tempête;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'et leur roi s\'en ira captif, lui et ses grands tous ensemble, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Ainsi parle l\'Éternel: A cause de trois, de quatre crimes de Moab, je ne m\'en rétracte point, parce qu\'ils ont calciné au feu les os du roi d\'Édom:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'j\'enverrai donc un feu en Moab, pour qu\'il dévore les palais de Kérioth, et Moab périra dans le tumulte, au bruit des cris de guerre, au son de la trompette,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'et j\'exterminerai le juge de son sein, et ferai mourir tous ses princes avec lui, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Ainsi parle l\'Éternel: A cause de trois, de quatre crimes de Juda, je ne m\'en rétracte point, parce qu\'ils méprisent la loi de l\'Éternel, et n\'observent point ses commandements, se laissant séduire par les idoles mensongères, à la suite desquelles leurs pères ont marché:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'j\'enverrai donc un feu en Juda, afin qu\'il dévore les palais de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Ainsi parle l\'Éternel: A cause de trois, de quatre crimes d\'Israël, je ne m\'en rétracte point, parce qu\'ils vendent le juste pour de l\'argent, et le pauvre pour une paire de sandales.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Leur ardent désir est de voir la poudre de la terre sur la tête des petits, et dans la cause des misérables ils prévariquent, et le fils et le père s\'approchent de la même femme, afin de déshonorer mon saint nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Ils s\'étendent sur des vêtements engagés, a côté de toutes sortes d\'autels, et ils boivent dans la maison de leurs dieux un vin extorqué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Et pourtant j\'anéantis devant eux les Amoréens qui avaient la taille des cèdres et la force des chênes, et je les anéantis dans leurs fruits et leurs racines de fond en comble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Et pourtant je vous ramenai du pays d\'Egypte, et vous conduisis à travers le désert pendant quarante années, pour vous rendre maîtres du pays des Amoréens;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'et de vos fils je fis surgir des prophètes, et de vos jeunes hommes des Nazaréens. N\'en est-il pas ainsi, enfants d\'Israël? dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Cependant vous avez fait boire du vin aux Nazaréens, et aux prophètes vous avez fait cette défense: Ne prophétisez point!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Voici, je vous ferai plier, comme plie le chariot rempli de gerbes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'la retraite est coupée à l\'homme agile, et le vigoureux ne pourra déployer sa force, ni le guerrier sauver sa vie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'et l\'archer ne tiendra pas, l\'homme aux pieds agiles ne pourra se sauver, ni le cavalier sauver sa vie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'et le plus vaillant des héros s\'enfuira nu en ce jour-là, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Écoutez cette parole que l\'Éternel adresse à vous, enfants d\'Israël, à toute la race que j\'ai retirée du pays d\'Egypte! Il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'C\'est vous seuls que j\'ai voulu connaître de toutes les races de la terre, c\'est pourquoi je vous ferai subir le châtiment de toutes vos transgressions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Deux hommes arrivent-ils au même lieu, sans être convenus du rendez-vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Le lion rugit-il dans la forêt, sans qu\'il y ait une proie pour lui? Le lionceau pousse-t-il sa voix de son repaire, sans avoir rien pris?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'L\'oiseau tombe-t-il dans le piège sur le sol, sans qu\'un filet lui ait été tendu? Le trébuchet se relève-t-il de terre sans que rien y ait été pris?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Sonne-t-on de la trompette dans une ville, sans que le peuple prenne l\'alarme? Arrive-t-il une calamité dans une ville, sans que l\'Éternel en soit l\'auteur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Car le Seigneur, l\'Éternel, ne fait rien sans avoir découvert son secret à ses serviteurs les prophètes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Le lion rugit, qui sera sans peur? Le Seigneur, l\'Éternel parle, qui pourrait ne pas prophétiser?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Faites-vous entendre dans les palais d\'Asdod, et dans les palais du pays d\'Egypte, et dites: Rassemblez-vous sur les montagnes de Samarie, et voyez la confusion qui y est-et l\'oppression qui s\'y trouve!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Et ils ne savent point faire le bien, dit l\'Éternel, eux qui entassent les rapines et les violences dans leurs palais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Aussi, ainsi parle le Seigneur, l\'Éternel: L\'ennemi! et il cerne le pays, et il va t\'ôter, faire crouler ta puissance, et tes palais seront pillés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Ainsi parle l\'Éternel: De même que le berger n\'arrache de la gueule du lion que deux jambes [de la brebis] ou le bout d\'une oreille, ainsi échapperont les enfants d\'Israël qui dans Samarie reposent à l\'angle du divan et sur les damas de leurs sofas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Écoutez et soyez témoins contre la maison de Jacob, dit le Seigneur, l\'Éternel, le Dieu des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Car au jour où je ferai subir à Israël le châtiment de ses crimes, je ferai tomber le châtiment sur les autels de Béthel, et les cornes de l\'autel seront brisées et tomberont sur la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'et j\'abattrai la maison d\'hiver avec la maison d\'été, et les palais d\'ivoire seront détruits, et les nombreux palais disparaîtront, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Écoutez cette parole génisses de Basan qui êtes sur la montagne de Samarie, qui opprimez les petits, froissez les indigents, dites à votre seigneur: Donne, afin que nous puissions boire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Le Seigneur, l\'Éternel, le jure par sa sainteté: Voici, il vient pour vous un temps où l\'on vous enlèvera avec l\'hameçon, et votre postérité avec le harpon du pêcheur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'et par les brèches vous sortirez, chacune en avant, pour aller vous jeter dans les montagnes, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Allez à Béthel! et commettez le crime à Guilgal, nombre de crimes, et tous les matins offrez vos victimes, tous les trois jours vos dîmes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Encensez avec du levain en actions de grâces, et proclamez, publiez des offrandes volontaires! car ainsi vous aimez à faire, enfants d\'Israël, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Je vous envoyai aussi la famine dans toutes vos villes, et la disette de pain dans tous vos lieux, mais vous ne revîntes pas à moi, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Je vous refusai aussi la pluie durant trois mois jusqu\'à la moisson; et je fis tomber la pluie sur une ville, mais sur l\'autre je ne la fis point tomber; un champ fut arrosé, mais le champ où il ne plut pas devint aride;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'et deux, trois villes se portèrent sur une ville pour y trouver de l\'eau à boire, et ne se désaltérèrent point; mais vous ne revîntes point à moi, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Je frappai vos blés du charbon et de la carie; vos nombreux jardins et vos vignes et vos figuiers et vos oliviers furent dévorés par les sauterelles; mais vous ne revîntes point à moi, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'J\'envoyai parmi vous une peste, telle que celle d\'Egypte, je tuai par l\'épée vos jeunes gens, laissant emmener vos chevaux; et je fis monter l\'infection de vos camps et jusque dans vos narines; mais vous ne revîntes point à moi, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Je fis parmi vous un bouleversement tel que celui que Dieu fit de Sodome et de Gomorrhe, et vous fûtes comme un tison sauvé de l\'incendie; mais vous ne revîntes point à moi, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Aussi te ferai-je ces choses, Israël! Or, puisque je veux te faire ces choses, apprête-toi à venir au-devant de ton Dieu, Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Car voici, Il forma les montagnes, et Il crée le vent, Il révèle à l\'homme ses propres pensées, Il change l\'aurore en ténèbres et marche sur les hauteurs de la terre; l\'Éternel, Dieu des armées, tel est son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Écoutez cette parole que je dis en complainte sur vous, maison d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Elle est tombée, ne se relèvera pas, la vierge d\'Israël; elle est jetée par terre, personne ne la remet debout!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Car ainsi parle le Seigneur, l\'Éternel: La ville qui mettait en campagne mille hommes, n\'en conserve que cent, et celle qui mettait en campagne cent hommes, n\'en conserve que dix à la maison d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Car ainsi parle l\'Éternel à la maison d\'Israël: Venez me chercher et vous aurez la vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'et n\'allez point chercher Béthel, et ne vous rendez point à Guilgal, et ne passez point à Béerséba! Car Guilgal va s\'en aller captive, et Béthel cesser d\'être.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Venez chercher l\'Éternel, et vous aurez la vie, afin qu\'il n\'envahisse pas la maison de Joseph, comme un feu qui dévore sans que pour éteindre il y ait personne à Béthel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'vous qui en absinthe transformez le droit, et foulez la justice contre terre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Il a fait les Pléiades et Orion, et change en lumière du matin l\'obscurité de la mort, et le jour en nuit ténébreuse; Il appelle les eaux de la mer et les répand sur la face de la terre; l\'Éternel est son nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Il fait surgir soudain la ruine sur la tête du puissant, et la ruine fond sur les lieux forts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Ils prennent en haine celui qui aux Portes fournit sa preuve, et celui qui soutient le droit en abomination.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Aussi puisque vous foulez les petits, et prenez d\'eux du blé en présent, vous avez bâti des maisons de pierres équarries, mais vous ne les habiterez point, vous avez planté des vignes délicieuses, mais vous n\'en boirez pas le vin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'car je connais vos nombreux crimes et vos péchés multipliés, vous qui opprimez le juste, acceptez des présents et aux Portes déboutez l\'indigent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Aussi dans ces temps-ci le sage se tait, parce que ces temps sont mauvais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Poursuivez le bien et non le mal, afin que vous ayez la vie, et qu\'ainsi l\'Éternel, Dieu des armées, soit avec vous, selon votre langage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Haïssez le mal et aimez le bien, et aux Portes donnez force au droit; peut-être l\'Éternel, Dieu des armées, prendra pitié des restes de Joseph.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Aussi ainsi parle l\'Éternel, Dieu des armées, le Seigneur: Dans toutes les places le deuil! et dans toutes les rues on crie: Malheur! Malheur! on appelle le laboureur pour gémir, et les experts en complaintes pour se lamenter;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'et dans toutes les vignes le deuil! car je passerai au travers de toi, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Malheur à ceux qui appellent de leurs vœux la journée de l\'Éternel! Que faites-vous de désirer la journée de l\'Éternel? Elle sera ténèbres et non point lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Ainsi tel fuit devant le lion, et l\'ours l\'atteint; il gagne la maison, appuie sa main au mur, et le serpent le pique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'La journée de l\'Éternel n\'est-elle pas obscurité et non lumière? n\'est-elle pas sombre et sans clarté?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Je hais, je dédaigne vos fêtes, et n\'ai point égard à vos solennités.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Car, lorsque vous me présentez des holocaustes et vos offrandes, je ne les agrée pas et ne regarde pas vos grasses victimes d\'actions de grâces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Écartez loin de moi le bruit de vos chants, je ne veux pas entendre le son de vos harpes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Mais que la droiture prenne son cours comme les eaux, et la justice comme un fleuve qui ne cesse pas de couler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Vous m\'avez présenté des sacrifices et des offrandes dans le désert, pendant quarante années, maison d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'mais vous portiez aussi la tente de votre roi, le piédestal de vos idoles, l\'étoile de votre dieu que vous vous étiez fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Aussi je vous mènerai captifs au delà de Damas, dit l\'Éternel, dont le nom est Dieu des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Malheur à ces insouciants de Sion, à ces présomptueux de la montagne de Samarie, nobles du premier des peuples, à qui vient la maison d\'Israël!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Passez à Calné et voyez; de là allez à Hamath la grande, puis descendez à Gath dans la Philistie! Ces États sont-ils plus prospères que ces royaumes, ou leur territoire est-il plus grand que votre territoire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Vous croyez éloigné le jour du malheur, et vous mettez la violence sur le trône;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'ils sont couchés sur des lits d\'ivoire et étendus sur leurs divans, et ils mangent les agneaux du troupeau et les veaux attachés dans l\'étable;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'ils poussent des éclats de voix au son du luth, et comme David composent des modulations;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'ils boivent dans des cratères à vin, et s\'oignent de la meilleure huile, et ils sont insensibles à la plaie de Joseph.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Aussi maintenant ils s\'en iront captifs à la tête des captifs; leurs bruyants propos de table cesseront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Le Seigneur, l\'Éternel, le jure par lui-même; c\'est l\'arrêt de l\'Éternel, Dieu des armées: J\'abhorre l\'orgueil de Jacob, et ses palais me sont odieux, et je livre la ville et ce qu\'elle renferme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Que s\'il reste dix hommes dans une maison, ils mourront aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'L\'un d\'eux est emporté par son parent, et celui qui doit brûler les corps enlève ses os de la maison, et dit à celui qui est au dedans de la maison: Y a-t-il encore quelqu\'un avec toi? Celui-ci lui répond: Personne!... Et il reprend: Silence! ce n\'est pas le lieu de louer le nom de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Car voici, l\'Éternel l\'a décidé, Il fait tomber en ruines la grande maison, et la petite en débris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Fait-on courir des chevaux sur un rocher, ou y laboure-t-on avec le bœuf, que vous transformez le droit en poison et le fruit de la justice en absinthe?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Vous qui faites votre joie du néant et qui dites: N\'est-ce pas par notre force que nous conquîmes la puissance?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Car voici, je vais faire lever contre vous, maison d\'Israël, dit l\'Éternel, Dieu des armées, un peuple qui vous accablera depuis Hamath jusqu\'à la rivière de la plaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Telle fut la vision qu\'offrit à ma vue le Seigneur, l\'Éternel: Voici, Il fit naître des sauterelles au commencement de la crue du regain, et voici, le regain poussait après les fenaisons du roi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'et quand elles eurent entièrement dévoré l\'herbe de la terre, je dis: Ah! pardonne, Seigneur Éternel! Comment Jacob tiendra-t-il? car il est chétif.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'L\'Éternel se repentit de cela. Cela n\'arrivera pas, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Telle fut la vision qu\'offrit à ma vue le Seigneur, l\'Éternel. Voici, le Seigneur, l\'Éternel appela le feu pour punir, et le feu dévora le grand abîme, et dévora le champ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Alors je dis: Ah! Seigneur, Éternel, arrête! Comment Jacob tiendra-t-il? car il est chétif.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'L\'Éternel se repentit de cela. Cela non plus n\'arrivera pas, dit le Seigneur, l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Telle fut la vision qu\'il offrit à ma vue. Voici, le Seigneur était debout sur une muraille tombant à plomb, et dans sa main Il avait un plomb.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Et l\'Éternel me dit: Que vois-tu, Amos? Et je dis: Un plomb. Et le Seigneur dit: Voici, je ferai passer un plomb par-dessus mon peuple d\'Israël; désormais je ne lui pardonnerai plus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'et les hauteurs d\'Isaac seront ravagées, et les sanctuaires d\'Israël dévastés, et je me lèverai contre la maison de Jéroboam avec l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Alors Amatsia, prêtre de Béthel, fit dire à Jéroboam, roi d\'Israël: Amos conspire contre toi au sein de la maison d\'Israël; le pays ne peut supporter tous ses discours;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'car ainsi a parlé Amos: Jéroboam périra par l\'épée, et Israël sera emmené captif loin de son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Cependant Amatsia dit à Amos: Voyant, va-t\'en, fuis au pays de Juda, et manges-y ton pain et y prophétise!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Mais à Béthel ne prophétise pas davantage, car c\'est un sanctuaire royal, et une résidence royale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Alors Amos répondit et dit à Amatsia: Je ne suis point prophète, ni fils de prophète, mais un berger, et je cultive des sycomores;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'et l\'Éternel m\'a fait quitter les troupeaux, et l\'Éternel m\'a dit: Va prophétiser contre mon peuple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Or maintenant, écoute la parole de l\'Éternel. Tu dis: « Ne prophétise plus contre Israël, et ne parle plus contre la maison d\'Isaac! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'c\'est pourquoi ainsi parle l\'Éternel: Ta femme sera violée dans la ville, et tes fils et tes filles périront par l\'épée, et ton pays sera partagé au cordeau, et toi tu mourras sur une terre impure, et Israël sera emmené captif loin de son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Telle fut la vision qu\'offrit à ma vue le Seigneur, l\'Éternel; et voici, c\'était une corbeille de fruits mûrs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Et il dit: Que vois-tu, Amos? Et je dis: Une corbeille de fruits mûrs. Alors l\'Éternel me dit: La fin vient pour mon peuple d\'Israël, je ne lui pardonnerai plus désormais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Et en ce jour-là, dit le Seigneur, l\'Éternel, les chants des palais seront des gémissements; il y aura nombre de cadavres, et partout on les jettera en silence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Entendez-le, vous qui vous acharnez contre l\'indigent pour anéantir les pauvres dans le pays,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'qui dites: Quand sera passée la nouvelle lune, pour que nous vendions du blé? et le sabbat, pour que nous ouvrions les greniers, mesurant avec un épha réduit, pesant avec un sicle plus fort et faussant la balance pour frauder?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'que nous achetions les petits à prix d\'argent, et les pauvres pour une paire de sandales, et vendions les criblures du blé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'L\'Éternel le jure par la gloire de Jacob: Jamais je n\'oublierai tout ce que vous avez fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Le pays n\'en tremblera-t-il pas, et chacun de ses habitants n\'en sera-t-il pas attristé? Ne se soulèvera-t-il pas tout entier comme un fleuve? ne se gonflera-t-il pas pour s\'affaisser comme le fleuve d\'Egypte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Et en ce jour-là, dit le Seigneur, l\'Éternel, je ferai coucher le soleil à midi, et j\'obscurcirai le pays en plein jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Et je changerai vos fêtes en deuil, et tous vos chants en complaintes, et je mettrai sur tous les reins le cilice, et je rendrai chauves toutes les têtes, et je couvrirai [le pays] du deuil qu\'on prend pour un fils unique, et sa fin sera comme un jour d\'amertume.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Voici, des jours viennent, dit le Seigneur, l\'Éternel, où j\'enverrai une disette dans le pays, non point une disette de pain, ni une soif d\'eau, mais celle d\'ouïr les paroles de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Alors ils seront errants d\'une mer à l\'autre mer, et vers le nord et vers l\'orient ils se précipiteront pour aller en quête de la parole de l\'Éternel, mais ils ne la trouveront pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'Dans ce temps-là les belles vierges et les jeunes hommes languiront altérés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Ceux qui jurent par le délit de Samarie et disent: « Par la vie de ton Dieu, Dan! et vive la voie de Béerséba! » tomberont pour ne plus se relever.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Je vis le Seigneur debout sur l\'autel; et Il dit: Frappe le chapiteau à faire trembler les seuils, et fais-en tomber les pièces sur la tête d\'eux tous! et par l\'épée je tuerai les survivants; aucun d\'eux ne pourra échapper par la fuite, ni aucun d\'eux se sauver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'S\'ils forcent les Enfers, de là ma main les tirera; et s\'ils montent dans les Cieux, je les en précipiterai;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 's\'ils se cachent à la cime du Carmel, je saurai les y surprendre et les y saisir, et s\'ils vont se dérober à mes regards au fond de la mer, de là j\'ordonnerai au serpent de les blesser;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'et s\'ils marchent captifs en avant de leurs ennemis, de là j\'ordonnerai à l\'épée de les tuer, et je tournerai mes regards sur eux, non pour leur bien, mais pour leur malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'C\'est le Seigneur, l\'Éternel des armées, qui touche la terre et elle se dissout, et tous ses habitants sont dans le deuil, et elle se soulève tout entière comme le fleuve, et s\'affaisse comme le fleuve d\'Egypte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'c\'est lui qui élève dans les Cieux ses hautes salles et fait poser ses voûtes sur la terre, qui appelle les eaux de la mer et les verse sur la face de la terre. L\'Éternel est son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'N\'êtes-vous pas pour moi ce que me sont les Éthiopiens, enfants d\'Israël? dit l\'Éternel. N\'ai-je pas tiré Israël de la terre d\'Égypte, et les Philistins de Caphthor, et les Syriens de Kir?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Voici, les yeux du Seigneur Éternel sont sur le royaume criminel, et je le ferai disparaître de la surface de la terre; seulement ne détruirai-je pas toute la maison de Jacob, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Car voici, je vais en donner l\'ordre et agiter la maison d\'Israël entre toutes les nations, comme on agite avec le crible; mais le grain ne tombera pas à terre. Ils mourront par l\'épée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'tous les pécheurs de mon peuple qui disent: La calamité ne nous atteindra pas et ne nous assaillira pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'Je veux dans ce même temps relever la hutte déchue de David, refermer ses brèches, et réparer ses ruines, et l\'édifier comme aux jours d\'autrefois,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'afin qu\'ils fassent la conquête des restes d\'Édom et de tous les peuples qui porteront mon nom; ainsi parle l\'Éternel qui le fera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Voici viennent des jours, dit l\'Éternel, où le laboureur se rapprochera du moissonneur, et celui qui foule le raisin de celui qui répand la semence; et les montagnes seront découlantes de moût et toutes les collines ruisselantes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Et je ramènerai les captifs de mon peuple d\'Israël, et ils rebâtiront les villes dévastées et les habiteront, et ils planteront des vignes et en boiront le vin, et ils établiront des jardins et en mangeront les fruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Et je les replanterai dans leur sol, afin qu\'ils ne soient plus arrachés de leur sol que je leur ai donné, dit l\'Éternel, ton Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Vision d\'Abdias. Ainsi parle le Seigneur, l\'Éternel, sur l\'Idumée: Nous avons ouï un message de par l\'Éternel, et un héraut parmi les peuples est envoyé: « Debout! Faisons une levée contre elle pour l\'attaquer! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Voici, je te rendrai chétive parmi les nations, tu seras livrée à un mépris extrême.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'L\'orgueil de ton cœur t\'a séduite, parce que tu habites les gorges des rochers, ta haute demeure; elle dit en son cœur: Qui me jetterait par terre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Quand pareille à l\'aigle tu élèverais ton aire, quand parmi les étoiles tu la placerais, de là je te précipiterai, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Des voleurs t\'ont-ils envahie, ou bien des pillards nocturnes? Comme tu es ruinée! Mais enlèvent-ils plus que ce qui leur suffit? Des vendangeurs t\'ont-ils envahie? Mais ne laissent-ils rien à grappiller?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Comme Ésaü est fouillé, et ses trésors visités!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Jusqu\'à la frontière tu es repoussée par tous tes alliés, tu es trompée, dupée par tes amis, tes commensaux; ils tendent un piège sous tes pas; il n\'y a plus d\'intelligence en toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'En ce même jour, dit l\'Éternel, n\'ôterai-je pas de l\'Idumée les sages, et des montagnes d\'Ésaü l\'intelligence?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Et tes héros, Théman, seront dans l\'épouvante, pour que tous ils soient exterminés de la montagne d\'Ésaü à cause du carnage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'A cause de l\'outrage que tu fis à ton frère Jacob tu seras couvert d\'ignominie, et exterminé à jamais!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Le jour où tu te tenais en face de lui, le jour où des étrangers emmenèrent captifs ses bataillons, et où des inconnus entrèrent dans ses portes, et tirèrent Jérusalem au sort; toi aussi tu fus comme l\'un d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Ne repais pas ta vue de la journée de ton frère, de sa journée de misère, et que les enfants de Juda ne te réjouissent pas au jour de leur ruine, et ne dilate pas ta bouche au jour du désastre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'N\'entre pas dans les portes de mon peuple au jour de sa défaite, toi non plus ne repais pas ta vue de son malheur au jour de sa défaite, et ne porte pas la main sur ses richesses au jour de sa défaite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Et ne te tiens pas au carrefour pour massacrer ses fugitifs, et ne livre pas ses réchappés au jour du désastre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Car elle est proche la journée de l\'Éternel sur tous les peuples: ce que tu as fait, te sera fait; tes actes retomberont sur ta tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'En effet, comme vous avez bu le calice sur ma montagne sainte, ainsi le boiront tous les peuples à perpétuité; ils le boiront, épuiseront, et ils seront comme s\'ils n\'eussent pas été.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Mais sur la montagne de Sion il y aura un refuge, et elle sera sainte, et la maison de Jacob reprendra ses possessions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Et la maison de Jacob sera un feu, et la maison de Joseph une flamme, et la maison d\'Ésaü le chaume, et ils l\'embraseront et la consumeront, et il n\'y aura point de survivants de la maison d\'Ésaü, car l\'Éternel a prononcé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Et ceux du midi posséderont la montagne d\'Ésaü, et ceux de Séphéla la Philistie, et ils posséderont la campagne d\'Éphraïm et la campagne de Samarie, et Benjamin Galaad.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Et les captifs de cette armée des enfants d\'Israël, emmenés par les Cananéens jusqu\'à Tsarpath, et les captifs de Jérusalem en état de dispersion soumettront les villes du midi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'et il montera des sauveurs sur la montagne de Sion pour juger la montagne d\'Ésaü, et à l\'Éternel sera l\'empire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Et:la parole de l\'Éternel fut adressée à Jonas, fils d\'Amitthaï, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Lève-toi, va à Ninive la grande ville, et prêche-lui, car sa méchanceté est parvenue jusqu\'à moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Mais Jonas se leva pour s\'enfuir à Tarsis de devant la face de l\'Éternel. Et il descendit à Joppe, et il trouva un navire partant pour Tarsis, et il paya son naulage, et s\'embarqua pour aller avec eux à Tarsis, loin de la face de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Mais l\'Éternel envoya un grand vent sur la mer, et il s\'éleva une grande tempête sur la mer, et le navire risquait de naufrager.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Alors les mariniers eurent peur, et ils invoquèrent chacun leur dieu, et ils jetèrent l\'attirail qui était sur le vaisseau à la mer, pour l\'alléger. Mais Jonas était descendu dans l\'intérieur du vaisseau, et s\'étant couché il s\'était endormi');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Alors le maître du vaisseau s\'approcha, de lui et lui dit: Que fais-tu de dormir? lève-toi! invoque ton Dieu! peut-être Dieu se ressouviendra de nous, et nous ne périrons pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Et ils se dirent l\'un à l\'autre: Venez et tirons au sort pour connaître lequel nous attire ce malheur! Et ils tirèrent au sort, et le sort désigna Jonas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Alors ils lui dirent: Dis-nous qui nous attire ce malheur? Quelles sont tes affaires et d\'où viens-tu? quel est ton pays et de quelle nation es-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Et il leur dit: Je suis hébreu, et c\'est l\'Éternel, le Dieu des Cieux, que j\'adore, Celui qui a fait la mer et la terre ferme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Et ces hommes furent saisis d\'une grande crainte, et ils lui dirent: Pourquoi as-tu fait cela? Car ces hommes savaient qu\'il fuyait de devant la face de l\'Éternel, parce qu\'il le leur avait avoué.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Et ils lui dirent: Que te ferons-nous pour que la mer se calme envers nous? Car la mer devenait toujours plus orageuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Et il leur dit: Prenez-moi, et jetez-moi à la mer, et la mer se calmera envers vous; car je sais que c\'est moi qui vous attire cette grande tempête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Et ces hommes ramèrent pour revenir à terre; mais ils ne pouvaient, car la mer allait s\'agitant toujours plus contre eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Alors ils invoquèrent l\'Éternel et dirent: Éternel, oh! ne nous fais pas: périr à cause de l\'âme de cet homme, et ne nous charge pas du sang innocent; car tu es l\'Éternel; ce que tu trouves bon, tu le fais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Et ils prirent Jonas et le jetèrent à la mer, et la mer cessa d\'être furieuse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Et ces hommes furent saisis d\'une grande crainte envers l\'Éternel, et ils sacrifièrent à l\'Éternel des victimes, et ils vouèrent des vœux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, 'Et l\'Éternel envoya un grand poisson pour engloutir Jonas, et Jonas fut dans le corps du poisson trois jours et trois nuits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Alors Jonas fit une prière à l\'Éternel son Dieu, dans le corps du poisson, et il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Dans mon angoisse j\'invoque l\'Éternel et Il m\'exauce; du sein des Enfers je crie, tu, entends ma voix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Tu me jettes dans l\'abîme, au cœur de la mer, et les flots m\'environnent, toutes tes vagues et tes ondes passent sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Mais je dis: Je suis repoussé loin de ton regard! Cependant je reverrai ton saint temple!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Les eaux pénètrent jusques à mon âme, l\'abîme m\'enserre, l\'algue s\'attache à ma tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Jusqu\'à la base des montagnes je suis descendu, les barrières de la terre se sont fermées derrière moi pour toujours; et tu retires ma vie du tombeau, Éternel, mon Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Quand en moi-même mon âme est défaillante, je me souviens de l\'Éternel, et ma, prière parvient jusqu\'à toi, jusqu\'à ton saint temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Les adorateurs des vanités, du néant, abandonnent leur bienfaiteur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'mais moi, je veux avec chants de louanges t\'offrir des sacrifices et accomplir les vœux que j\'ai faits. Le salut vient de l\'Éternel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Et l\'Éternel commanda au poisson, et il vomit Jonas sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Et la parole de l\'Éternel fut adressée pour la seconde fois à Jonas en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Lève-toi, va à Ninive la grande ville, et proclames-y la proclamation que je vais te dire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Alors Jonas se leva et alla à Ninive, selon la parole de l\'Éternel. Or Ninive était une grande ville devant Dieu, ayant trois jours de marche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Et Jonas commença à faire dans la ville une journée de marche, et fit la proclamation en ces mots: Encore quarante jours et Ninive est détruite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Et les gens de Ninive crurent Dieu, et ils publièrent un jeûne, et ils se revêtirent tous du cilice et les grands et les petits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Et lorsque le bruit en parvint au roi de Ninive, il se leva de son trône et déposa son manteau, et se couvrit du cilice, et s\'assit sur la cendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Et il fit crier et dire dans Ninive, de par le roi et ses grands, ces paroles: Que les hommes et les animaux, le bétail et les troupeaux ne goûtent de rien, ne paissent point et ne boivent point d\'eau!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'et que les hommes et les bestiaux soient recouverts du cilice! que l\'on crie à Dieu avec force! et que chacun revienne de sa mauvaise voie et de l\'injustice de ses mains!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Qui sait? Dieu se repentira de nouveau! Il reviendra de l\'ardeur de sa colère, et nous ne périrons pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Et Dieu voyant qu\'ils en agissaient ainsi et qu\'ils revenaient de leur mauvaise voie, Dieu se repentit du mal qu\'il avait parlé de leur faire, et Il ne le leur fit pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Et cela fut pour Jonas un très grand déplaisir, et il se dépita.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Et il pria l\'Éternel et dit: Ah! Éternel, n\'est-ce pas ce que je disais, quand j\'étais encore dans mon pays? Aussi me suis-je hâté de fuir à Tarsis; car je savais que tu es un Dieu clément et miséricordieux, plein de longanimité et d\'amour et regrettant de punir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Et maintenant, Éternel, ôte-moi donc ma vie, car mieux vaut pour moi mourir que de vivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Mais l\'Éternel dit: Fais-tu bien de te dépiter?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Alors Jonas sortit de la ville, et s\'assit à l\'orient de la ville et il se fit là une cabane, et s\'y assit à l\'ombre, jusqu\'à ce qu\'il vît ce qui arriverait dans la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Alors l\'Éternel Dieu fit croître un ricin qui s\'éleva au-dessus de Jonas pour qu\'il y eût de l\'ombre sur sa fête et pour le délivrer de son mal. Et Jonas se réjouit à cause du ricin, et sa joie fut grande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Et Dieu fit venir à l\'arrivée de l\'aurore le lendemain un ver qui piqua le ricin, de sorte qu\'il sécha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Et il arriva au lever du soleil que Dieu fit venir un vent d\'orient sourd, et le soleil frappa la tête de Jonas, de sorte qu\'il défaillait. Alors il demanda sa mort et il dit: Mieux vaut pour moi mourir que de vivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Mais Dieu dit à Jonas: Fais-tu bien de te dépiter à cause du ricin? Et il dit: Je fais bien de me dépiter jusqu\'à la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Et l\'Éternel dit: Tu as pitié d\'un ricin pour lequel tu n\'as pris aucune peine et que tu n\'as pas élevé, qui enfant d\'une nuit a crû et enfant d\'une nuit a péri:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'et moi je n\'aurais point pitié de Ninive la grande ville, dans laquelle il y a plus de cent vingt mille hommes qui ne savent pas distinguer leur droite de leur gauche, et des animaux en grand nombre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'La parole de l\'Éternel qui fut adressée à Michée, de Moréseth, dans les temps de Jotham, d\'Achaz et d\'Ézéchias, rois de Juda, laquelle lui fut révélée touchant Samarie et Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Écoutez, vous tous les peuples! sois attentive, ô terre avec tout ce qui y est! et que le Seigneur, l\'Éternel, soit témoin contre vous, qu\'il soit témoin, le Seigneur, de son saint temple!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Car voici, l\'Éternel va sortir de son séjour et descendre et s\'avancer sur les hauteurs de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'et les montagnes se dissoudront sous ses pas, et les vallées se fondront, comme la cire en présence du feu, comme des eaux versées sur une pente:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'tout cela, pour le crime de Jacob et le péché de la maison d\'Israël! D\'où vient le crime de Jacob? n\'est-ce pas de Samarie? et d\'où les hauts lieux de Juda? n\'est-ce pas de Jérusalem?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Aussi ferai-je de Samarie un tas de pierres dans un champ, une plantation de vigne, et précipiterai-je ses pierres dans la vallée, et mettrai-je ses fondements à nu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'et toutes ses images seront brisées, et tout le salaire de ses prostitutions brûlé au feu; et je saccagerai toutes ses idoles; car avec le salaire de ses prostitutions elle les a rassemblées et elles redeviendront salaire de prostitution.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'C\'est pourquoi je gémis et me lamente, je vais sans chaussure ni vêtement; je me lamente comme le chacal et suis lugubre comme l\'autruche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Mortel, en effet, est le coup qui la frappe, car il atteint jusques à Juda, pénètre jusqu\'aux portes de mon peuple, à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'A Gath n\'en dites rien! et à Acco ne pleurez pas! à Beth-léaphra je me roule dans la poudre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Émigre, habitante de Saphir, nue et honteuse! L\'habitante de Tsaanan n\'ose sortir; le deuil de Bethetsel vous prive de son abri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Car l\'habitante de Maroth est inquiète de son salut, car de par l\'Éternel la calamité est parvenue aux portes de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Attelle ton char aux coursiers, habitante de Lachis! tu fus un principe de péché pour la fille de Sion, car en toi se sont trouvées les défections d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Tu devras pour cela renoncer à Moréseth-Gath; les maisons d\'Achsib seront une déception pour les rois d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Je ramènerai contre toi le conquérant, habitante de Marésa, la gloire d\'Israël fuira jusques à Adullam.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Rase ta tête, coupe ta chevelure à cause de tes enfants chéris! rends-toi aussi chauve que le vautour; car ils s\'en vont loin de toi captifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Malheur à ceux qui méditent le crime et machinent le mal sur leur couche! Dès l\'aube du matin ils l\'exécutent, car leur bras est pour eux un dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Ils convoitent des champs et s\'en emparent, et des maisons, et ils les saisissent, et ils font violence a l\'homme et à sa maison, au maître et à sa propriété.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Aussi ainsi parle l\'Éternel: Voici, je médite contre cette race un désastre auquel vous ne soustrairez pas vos cols, et vous ne marcherez pas la tête levée, car ce sera un temps malheureux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'En ce jour-là on chantera sur vous des chansons, et on élèvera une plaintive complainte, disant: « Nous sommes désolés, désolés. Il aliène la part de mon peuple! Comme Il me l\'enlève! A l\'infidèle Il distribue nos champs! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'C\'est pourquoi tu n\'auras personne qui étende le cordeau sur un lot dans l\'assemblée de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, '« Ne déclamez pas! » déclament-ils. « Qu\'ils ne déclament pas contre ces choses! leurs avanies ne cessent pas! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'O toi qui t\'appelles maison de Jacob, l\'Éternel est-Il prompt à s\'irriter? est-ce sa façon d\'agir? « N\'ai-je pas des paroles de bonté pour qui suit la droiture? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Dès longtemps mon peuple en ennemi s\'insurge; de dessus la tunique vous détachez le manteau à ceux qui passent en sécurité revenant du combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Vous expulsez les femmes de mon peuple de leurs maisons chéries, et à leurs enfants vous ôtez pour toujours ce dont je les parai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Debout! et partez! car ce n\'est pas ici pour vous un lieu de repos, parce que la souillure vous perd, parce que votre ruine est profonde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Si un homme venait vous parler en l\'air et mentir en disant: « Je te prophétise sur le vin et la cervoise! » cet homme serait le prophète de ce peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Cependant je veux te recueillir, te recueillir, Jacob, tout entier, rassembler les restes d\'Israël, les réunir comme les brebis d\'un parc, comme le troupeau dans un pâturage; ils bruiront, tant il y aura d\'hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Il se met en marche à leur tête Celui qui sait se faire jour; ils se font jour, ils traversent la porte, et en sortent de nouveau, et leur Roi les précède, et l\'Éternel est à leur tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Et je dis: Entendez donc, chefs de Jacob, et princes de la maison d\'Israël! N\'est-ce pas à vous de connaître le droit?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Vous qui haïssez le bien et aimez le mal, dépouillez les hommes de leur peau et leurs os de leur chair,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'et qui dévorez la chair de mon peuple et l\'écorchez et brisez ses os, et en mettez les pièces comme dans la marmite, et comme de la viande dans la chaudière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Alors ils crieront à l\'Éternel, mais Il ne les exaucera point et Il leur cachera sa face dans ce temps-là, parce qu\'ils ont agi méchamment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Ainsi parle l\'Éternel contre les prophètes qui séduisent mon peuple, qui, quand leurs dents ont à mâcher, crient: La paix! et à quiconque ne leur met rien dans la bouche, ils déclarent la guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Aussi, nuit pour vous, et plus de visions! ténèbres pour vous, et plus de divination! et le soleil se couchera sur ces prophètes, et le jour s\'assombrira sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Et ces voyants seront confus, et ces divinateurs rougiront, et tous ils se voileront la barbe; car il n\'y aura point de réponse de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Mais je suis, au contraire, rempli de force, de l\'esprit de l\'Éternel, et de justice et d\'intrépidité pour révéler à Jacob sa défection, et à Israël son péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Entendez donc ceci, chefs de la maison de Jacob et princes de la maison d\'Israël, qui abhorrez la justice et pervertissez tout ce qui est droit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'qui édifiez Sion par des meurtres, et Jérusalem par des forfaits!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Ses chefs jugent pour des présents, et ses sacrificateurs enseignent pour un salaire, et ses prophètes prédisent pour de l\'argent; et néanmoins ils comptent sur l\'Éternel, disant: « L\'Éternel n\'est-Il pas au milieu de nous? Aucun mal ne peut nous survenir! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Aussi, à cause de vous, Sion sera un champ qu\'on laboure, et Jérusalem un monceau de ruines, et la montagne de la Maison une cime boisée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Et dans la suite des temps la montagne de la maison de l\'Éternel se trouvera établie sur la cime des montagnes et élevée au-dessus des collines, et les peuples y afflueront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Et des peuples nombreux viendront et diront: « Allons, montons à la montagne de l\'Éternel et à la maison du Dieu de Jacob, et qu\'il nous instruise de ses voies-et nous marcherons sur ses sentiers! » car de Sion émanera la loi, et la parole de l\'Éternel de Jérusalem!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Et Il sera le juge de beaucoup de peuples et l\'arbitre de nations nombreuses au loin, et ils forgeront leurs épées en faucilles et leurs lances en serpes, et un peuple contre un peuple ne lèvera plus l\'épée, et ils n\'apprendront plus la guerre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Alors ils habiteront chacun sous sa vigne et sous son figuier, sans être troublés, car la bouche de l\'Éternel des armées a prononcé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Comme tous les peuples marchent chacun au nom de son Dieu, nous, nous marcherons au nom de l\'Éternel, notre Dieu, à jamais, perpétuellement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'En ce jour-là, dit l\'Éternel, je recueillerai les boiteux, et rassemblerai les expulsés et ceux que j\'aurai maltraités,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'et je ferai des boiteux une réserve, et des disséminés un peuple nombreux, et l\'Éternel sera leur Roi sur la montagne de Sion, dès lors à jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Et toi, vedette du troupeau, colline de la fille de Sion, à toi parviendra, reviendra l\'empire de jadis, la royauté de la fille de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Eh bien! pourquoi pousses-tu des cris? Es-tu sans roi, ou ton conseiller est-il mort, que la douleur te saisit comme la femme en travail?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Sois tremblante et angoissée, fille de Sion, comme la femme en travail! Car maintenant tu vas sortir de la ville, et séjourner dans les champs, puis gagner Babel; mais là tu seras délivrée, là l\'Éternel te rachètera de la main de tes ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Maintenant s\'unissent contre toi des peuples nombreux qui disent: « Qu\'elle soit profanée! et que le spectacle de Sion réjouisse nos regards! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Mais ils ne connaissent pas les pensées de l\'Éternel, et ne comprennent pas son conseil, car Il les ramassera comme les gerbes sur l\'aire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Sus! triture, fille de Sion! car je fais ta corne de fer et ton sabot d\'airain, pour que tu écrases nombre de peuples, et que tu consacres à l\'Éternel leur butin, et leurs richesses au Seigneur de toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Pour le moment vous formez vos bataillons, hommes des bataillons; on met le siège devant nous: ils frappent de la verge la joue du juge d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Mais toi, Bethléhem Ephrata, trop petite pour être l\'une des souches de Juda, de toi me sortira Celui qui sera dominateur en Israël, et dont l\'origine remonte à l\'antiquité et aux temps éternels.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'C\'est pourquoi il les mettra à merci, jusqu\'au temps où celle qui doit enfanter, enfante, et les restes de ses frères rejoindront les enfants d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Et il se tiendra là et sera pasteur avec la vertu de l\'Éternel et avec la majesté du nom de l\'Éternel son Dieu, et ils seront en sécurité, car dès lors il sera grand jusqu\'aux bouts de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Et il sera lui-même la Paix. Si l\'Assyrien envahit notre pays et porte ses pas dans nos palais, nous lui opposerons sept pasteurs et huit princes du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Et ils paîtront la terre d\'Assyrie avec l\'épée, et la terre de Nemrod au dedans de ses portes; et il délivrera de l\'Assyrien, s\'il envahit notre pays et porte ses pas dans nos frontières.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Et les restes de Jacob seront au milieu de peuples nombreux comme une rosée qui vient de l\'Éternel, comme sur l\'herbe les gouttes de la pluie qui n\'attendent rien de l\'homme, et n\'espèrent rien des enfants des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Et les restes de Jacob seront au milieu des peuples, parmi les nations nombreuses, comme le lion parmi les bêtes de la forêt, comme le lionceau dans un troupeau de brebis, où ayant pénétré il foule et déchire, et personne pour sauver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Que ta main soit levée sur tes adversaires, et que tous tes ennemis soient exterminés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'Et en ce jour-là, dit l\'Éternel, j\'exterminerai du milieu de toi tes chevaux, et détruirai tes chars,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'et j\'exterminerai les villes de ton pays et démolirai tous tes forts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'et j\'exterminerai de ta main les enchantements, et tu n\'auras plus de divinateurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'et j\'exterminerai tes idoles et tes statues du milieu de toi, et tu n\'adoreras plus l\'ouvrage de tes mains;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'et j\'arracherai tes Aschères du milieu de toi, et détruirai tes villes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'et dans ma colère et mon courroux j\'exercerai mes vengeances sur les nations qui ne veulent pas écouter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Écoutez donc ce que dit l\'Éternel! « Lève-toi, plaide devant les montagnes, et que les collines entendent ta voix! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Écoutez, montagnes, le procès de l\'Éternel, et vous, immobiles fondements de la terre! car l\'Éternel fait un procès à son peuple, et avec Israël Il entre en débat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, '« Mon peuple, que t\'ai-je fait? et en quoi t\'ai-je peiné? Réponds-moi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Car je te tirai du pays d\'Egypte, et de la maison de servitude je te rachetai, et j\'envoyai devant toi Moïse, Aaron et Marie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Mon peuple! rappelle-toi donc ce que projetait Balak, roi de Moab, et ce que lui répondit Balaam, fils de Béor, de Sittim à Guilgal, afin que tu reconnaisses les bontés de l\'Éternel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, '« Avec quoi-me présenterai-je devant l\'Éternel, rendrai-je mon hommage au Dieu suprême! Me présenterai-je avec des holocaustes, avec des veaux d\'un an?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'L\'Éternel agréera-t-Il des milliers de béliers, des myriades de torrents d\'huile? Offrirai-je mon premier-né pour expier mon crime, le fruit de mes entrailles pour expier le péché de mon âme? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'O homme, Il t\'a révélé ce qui est bien; et que requiert de toi l\'Éternel, sinon de pratiquer la justice, et d\'aimer la piété, et de marcher humblement avec ton Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'La voix de l\'Éternel fait appel à la Ville; et salut à qui prend garde à ton nom! Entendez la verge et qui l\'envoie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Y a-t-il encore dans la maison de l\'impie des trésors iniques et un épha réduit, abominable?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Puis-je être pur pour qui a une balance inique et une bourse avec de faux poids?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Parce que ses riches sont pleins de violence, et que ses habitants profèrent le mensonge, et ont dans la bouche une langue trompeuse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'moi aussi je te frapperai à mort, exerçant des ravages à cause de tes péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Tu mangeras et ne te rassasieras pas, et l\'inanition sera dans ton corps; tu mettras à part, mais ne sauveras pas, et ce que tu sauveras, je le livrerai à l\'épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Tu sèmeras et ne moissonneras pas; tu pressureras l\'olive et ne t\'oindras point d\'huile; le moût, et ne boiras point de vin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Et l\'on observe les règles d\'Omri et toute la manière de la maison d\'Achab, et vous suivez leurs conseils, afin que je fasse de toi un objet d\'horreur et de ses habitants un objet de dérision, et vous porterez l\'opprobre de mon peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Malheureux! je suis comme quand les fruits sont cueillis, que l\'on grappille après la vendange! Point de raisin à manger, de ces figues hâtives que désire mon âme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Les bons sont disparus du pays; parmi les hommes plus de gens de bien,! ils épient tous le sang à verser; chacun cherche à prendre son frère au piège.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Pour le mal on a des mains pour le bien faire; le magistrat demande et le juge est vénal, et le grand exprime le désir de son âme, et eux prévariquent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Le meilleur d\'entre eux est comme un buisson d\'épines, le plus droit pire qu\'une haie. Le jour de tes sentinelles, ton châtiment viendra; alors ils seront dans la perplexité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Ne vous fiez pas à l\'ami, ne comptez pas sur l\'intime, contre la femme couchée dans ton sein garde les portes de ta bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Car le fils méprise son père, la fille s\'insurge contre sa mère, la bru contre sa belle-mère; l\'homme a pour ennemis les gens de sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, '« Mais moi de mes yeux je cherche l\'Éternel, j\'attends mon Dieu sauveur; mon Dieu m\'entendra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Ne te réjouis pas, mon ennemie, à mon sujet! Si je suis tombée, je me relèverai; si je suis assise dans les ténèbres, l\'Éternel sera ma lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Je me soumets au courroux de l\'Éternel, parce que j\'ai péché contre lui, jusqu\'à ce qu\'il soutienne ma querelle, et défende ma cause, et me produise à la lumière, et que sa justice réjouisse mes regards.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Et mon ennemie le verra, et la honte couvrira celle qui me disait: Où est l\'Éternel, ton Dieu? Elle réjouira mes regards; alors elle sera foulée comme la boue dés rues. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Le jour de la restauration de tes murs, ce jour-là tes limites seront reculées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'C\'est le jour où vers toi on accourra, de l\'Assyrie aux villes d\'Egypte, et de l\'Egypte au fleuve, de la mer à la mer, et des montagnes aux montagnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Et la terre sera ravagée à cause de ses habitants, à cause des fruits de leurs œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, '« Fais paître ton peuple avec ta houlette, le troupeau qui t\'appartient et doit habiter solitaire, dans la forêt au milieu du Carmel. Qu\'ils paissent en Basan et Galaad, comme aux jours d\'autrefois. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, '« Comme aux jours de ta sortie du pays d\'Egypte je te ferai voir des merveilles! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Les peuples le verront et auront honte de toute leur puissance, ils mettront la main sur la bouche, leurs oreilles seront assourdies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Ils mordront la poussière comme le serpent, comme les reptiles de la terre; ils quitteront éperdus leurs forts; à l\'Éternel notre Dieu ils viendront tout tremblants, et seront craintifs devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Qui est un Dieu, comme toi, pardonnant le crime et passant le péché au reste de ton héritage? Il ne garde pas sa colère à jamais, car Il se plaît à la clémence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'De nouveau Il prendra pitié de nous, Il mettra nos crimes sous ses pieds, et Tu jetteras au fond de la mer tous nos péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Tu montreras à Jacob ta fidélité, et à Abraham la grâce que tu as jurée à nos pères dès les jours d\'autrefois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Oracle contre Ninive. Livre de la vision de Nahum d\'Elkosch.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'L\'Éternel est un Dieu jaloux et vengeur; l\'Éternel est vengeur et plein de courroux; l\'Éternel se venge de ses ennemis et garde du ressentiment à ses adversaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'L\'Éternel est lent à s\'irriter et grand en force, et Il ne laisse point impuni. L\'Éternel marche dans l\'ouragan et la tempête, et les nuées sont la poussière de ses pieds;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Il gourmande la mer et la dessèche, et tarit tous les fleuves; Basan et le Carmel se fanent, et la verdure du Liban se flétrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Les montagnes s\'ébranlent devant lui et les collines se décomposent; à son aspect la terre se soulève, le monde et tous ses habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Qui tiendrait devant son courroux, et qui resterait debout au feu de sa colère? Sa fureur s\'épanche comme des flammes, et les rochers s\'éboulent devant lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'L\'Éternel est bon, Il est un refuge au jour de la détresse, et Il connaît ceux qui se confient en lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Mais par des flots envahissants Il portera la ruine dans le lieu où elle est sise, et les ténèbres poursuivront ses ennemis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Que tramez-vous contre l\'Éternel? c\'est lui qui détruit! le désastre ne s\'exécutera pas en deux fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Car tels que des ronces entrelacées, et comme ivres de leur vin, ils seront dévorés, ainsi que le chaume sec, totalement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'De toi, [Ninive,] sortit celui qui machinait le mal contre l\'Éternel, celui qui médita la ruine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Ainsi parle l\'Éternel: Quand même ils sont au complet et si nombreux, cependant ils seront moissonnés, et c\'en est fait. Et si je t\'ai humilié, [Juda,] je ne t\'humilierai plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Et maintenant je veux briser son joug de dessus ta tête et rompre tes fers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Quant à toi, [Assyrien,] voici ce qu\'ordonne l\'Éternel: A l\'avenir il n\'y aura plus de rejeton de ton nom; de la maison de ton Dieu j\'arracherai les idoles de taille et de fonte, je te prépare ton tombeau, car tu fus trop léger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Là le feu te dévorera, l\'épée te détruira, te dévorera comme l\'attelabe, quand tu serais nombreuse comme l\'attelabe, nombreuse comme la sauterelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Voyez! sur les montagnes les pieds du messager qui annonce la paix! Juda, célèbre tes fêtes, accomplis tes vœux! Car le destructeur ne t\'envahira plus, il est totalement détruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Le ravageur marche sur toi, [Ninive!] Garde la place, aie l\'œil sur le chemin, ceins tes reins, fais les plus grands efforts!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Car l\'Éternel relève la grandeur de Jacob, aussi bien que la grandeur d\'Israël, parce que les dévastateurs les ont dévastés, et ont détruit leurs plants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Les boucliers de ses héros sont rouges, les guerriers sont vêtus d\'écarlate; les faux étincellent sur les chars au jour de son armement, et les lances sont brandies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Dans les rues avec furie les chars sont lancés, ils se croisent dans les places; leur aspect est celui des torches, ils courent comme des éclairs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Il se souvient de ses braves; ils trébuchent dans leur marche: on se précipite contre ses murs et la tortue est dressée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Les portes des fleuves sont ouvertes, et le palais s\'écroule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'C\'est arrêté: elle est mise à nu, emmenée, et ses suivantes gémissent comme des colombes, en se frappant la poitrine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Ninive était comme un réservoir plein d\'eau, depuis qu\'elle était; mais ils fuient! « Arrêtez! Arrêtez! » mais personne ne se retourné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Pillez l\'argent! pillez. l\'or! ce sont des trésors sans fin, des richesses, toutes sortes de meubles de prix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Désastre et dévastation! et abandonnement! les cœurs se fondent, les genoux chancellent, tous les reins souffrent, tous les visages pâlissent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Qu\'est devenu le repaire des lions, où les lionceaux trouvaient leur pâture, où se promenaient le lion, la lionne, le petit du lion, sans être troublés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Le lion dépeçait pour ses petits, et déchirait pour ses lionnes; il remplissait de proie ses antres, et ses repaires de dépouilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Malheur à la cité sanguinaire, toute pleine de fraude, de violence, qui ne renonce pas à la rapine!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Entendez les fouets, et entendez le roulement des roues et les chevaux galopant et les chars bondissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'La cavalerie est en course, l\'épée jette des flammes et la lance l\'éclair; c\'est une masse de tués et une foule de morts et une infinité de cadavres, on heurte contre des cadavres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'C\'est à cause des nombreuses prostitutions de la prostituée attrayante, enchanteresse, qui vendait les peuples par ses prostitutions et les familles par ses enchantements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Voici, j\'en veux à toi, dit l\'Éternel des armées, je retrousserai les pans de ta robe par-dessus ton visage, et ferai voir aux peuples ta nudité et aux royaumes ton ignominie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'et je jetterai sur toi des ordures et te ferai honte et t\'exposerai en spectacle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Et qui te verra, te fuira et dira: « Ninive est détruite; qui la plaindrait? Où te chercherai-je des consolateurs? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Es-tu meilleure que No-Ammon qui était assise sur le fleuve, que les eaux entouraient, dont une mer était le fossé et une mer la muraille?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'L\'Ethiopie était sa force, avec les innombrables Égyptiens; les Phytes et les Libyens étaient tes auxiliaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Elle aussi s\'en est allée captive en exil; ses enfants aussi furent écrasés à tous les carrefours; et on tira ses nobles au sort, et tous ses grands furent liés de chaînes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Toi aussi tu boiras ton soûl [du calice], tu. te cacheras, toi aussi tu chercheras un abri contre l\'ennemi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Tous tes remparts sont des figuiers portant des primeurs; les secoue-t-on, elles tombent dans la bouche de qui veut en manger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Voici, tes armées seront des femmes au milieu de toi, à tes ennemis s\'ouvrent les portes de ton pays, et le feu dévore tes verrous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Fais ta provision d\'eau pour le siège, fortifie tes remparts, broie la glaise et foule l\'argile, répare les fours à briques!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Là le feu te dévorera, l\'épée te détruira, te dévorera comme l\'attelabe, quand tu serais nombreuse comme l\'attelabe, nombreuse comme la sauterelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Tu as plus de marchands qu\'il n\'y a d\'étoiles au ciel; l\'attelabe déploie ses ailes et prend son vol.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Tes princes sont nombreux comme les sauterelles, et tes chefs comme les locustes qui se posent sur les murailles au temps froid: le soleil se lève-t-il, elles fuient, et on ignore le lieu où elles sont.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Tes bergers sommeillent, roi d\'Assur, tes généraux reposent; ton peuple est disséminé sur les montagnes, et nul ne le rassemble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Point de remède à ta blessure! ta plaie est incurable. Tous ceux qui ouïront parler de toi, battront des mains sur toi; car sur qui ne s\'est pas étendue ta méchanceté incessamment?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Oracle révélé à Habacuc, le prophète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Que de temps j\'ai crié, Éternel, et tu n\'écoutes pas! je crie à toi: violence! et tu ne secours pas!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Pourquoi me rends-tu témoin du crime? et tu es spectateur de nos peines! Et l\'oppression et la violence sont devant moi; il y a des débats et la discorde s\'élève.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Aussi la loi est sans vie, et jamais justice n\'est rendue, car l\'impie cerne le juste, aussi rend-on une justice pervertie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, '« Regardez parmi les nations et voyez! et étonnez-vous, soyez étonnés! car je vais faire une œuvre en vos jours! vous n\'y croirez pas, si elle vous est annoncée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Car voici, je fais lever les Chaldéens, peuple rude et impétueux, qui s\'avance au large sur la terre pour occuper des demeures qui ne sont pas à lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Il est terrible et, formidable; de lui seul émanent son droit et sa fierté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Et plus agiles que des panthères sont ses chevaux, plus rapides que les loups du soir, et ses chevaux fièrement bondissent, et ses cavaliers arrivent de loin; ils volent comme un aigle qui fond sur sa proie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Tous ils viennent pour sévir; un désir est sur leur visage: en avant! et il entraîne comme du sable les captifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Et il se moque des rois, et les princes sont sa risée; de tout rempart il se moque; il élève une terrasse et s\'en empare.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Puis son audace s\'accroît, et il passe outre, et devient criminel, car sa force est son Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Ne fus-tu pas de tout temps l\'Éternel, mon Dieu, mon Saint? Nous ne périrons pas! Éternel, tu l\'as commis au jugement! » ô rocher, tu l\'as assigné pour punir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Toi dont les yeux sont trop purs pourvoir le crime, et qui ne peux être spectateur des maux, pourquoi verrais-tu des impies, te tairais-tu quand le méchant dévore un plus juste que lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Tu assimiles donc l\'homme aux poissons de la mer, aux reptiles qui n\'ont point de souverain!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Il tire tout avec l\'hameçon, l\'enlève avec son filet, et l\'emporte dans sa nasse, et il en est joyeux et allègre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Pour cela il sacrifie à sa nasse et encense son filet, car par eux sa capture est riche et sa chère succulente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Faut-il pour cela qu\'il vide son filet et toujours égorge les peuples sans pitié?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Je veux me tenir dans mon donjon et me placer sur la tour et observer pour voir ce qu\'il me dira et ce que je répliquerai en sus de mon grief.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Et l\'Éternel me répondit et dit: Écris la vision et la grave sur des tables, afin que couramment on la lise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Car la vision a trait à un temps à venir, mais elle aspire au but, et ne mentira pas; si elle tarde, attends-la, car elle arrivera, elle n\'y manquera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Voici, son âme s\'est enflée, elle n\'est pas droite en lui, mais le juste par sa foi vivra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Oui, le vin est insolent, l\'homme qu\'il enorgueillit n\'a point de repos; pareil à l\'Enfer, il ouvre une large bouche, et il est comme la mort, et insatiable, et il s\'empare de tous les peuples et accapare toutes les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Toutes ne diront-elles pas sur lui une chanson et des railleries et des sarcasmes, parlant ainsi: Malheur à qui accumulait ce qui n\'était pas à lui! jusques à quand?... et à qui se chargeait d\'emprunts à gages!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Ne se lèveront-ils pas soudain, tes créanciers, et ne s\'éveilleront-ils pas, tes oppresseurs? Et tu seras leur proie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Parce que tu pillas des peuples nombreux, tous les autres peuples te pilleront, à cause du meurtre des hommes et de l\'outrage fait au pays, aux villes et à tous leurs habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Malheur à qui fait un gain inique pour sa maison, afin de placer son nid sur la hauteur pour se dérober au bras du malheur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Tu décidas l\'opprobre de ta maison, la destruction des peuples nombreux, et tu as péché contre toi-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Car de la muraille la pierre crie, et de la charpente la poutre lui répond.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Malheur à qui bâtit une ville avec le sang, et fonde une ville avec l\'iniquité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Voici, n\'est-ce pas de par l\'Éternel des armées que les peuples se fatiguent pour un feu, et les nations se peinent pour le néant?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Car la terre se remplira de la connaissance de la gloire de l\'Éternel, de même que les eaux recouvrent la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Malheur à qui fait boire son prochain! à toi qui lui verses le feu de ton vin et l\'enivres pour voir sa nudité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Tu seras rassasié d\'opprobre au lieu de gloire; bois aussi toi-même et découvre ton prépuce! qu\'elle arrive à toi la coupe de la droite de l\'Éternel, et que l\'ignominie couvre ta gloire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Car la violence faite au Liban retombera sur toi, ainsi que la ruine des bêtes qu\'elle épouvanta, à cause du meurtre des hommes et de la violence faite au pays, à la ville et a tous ses habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'A quoi sert l\'idole, pour que le sculpteur la taille? la statue et le docteur de mensonges, pour que le sculpteur se confie en sa sculpture en faisant des idoles muettes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Malheur à qui dit au bois: « Éveille-toi! » « Lève-toi! » à la pierre muette, « qu\'elle enseigne! » Voici, elle est plaquée d\'or et d\'argent, et il n\'y a point d\'esprit au dedans d\'elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Mais l\'Éternel est dans son temple saint! Que toute la terre se taise devant lui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Prière d\'Habacuc, le prophète, sur le mode des chants plaintifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Éternel, j\'ai entendu ton annonce et je suis craintif. Éternel, réalise ton œuvre durant ces années, durant ces années manifeste-la! Dans la colère souviens-toi de la pitié!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Dieu arrive de Théman, et le Saint du mont de Paran. (Pause.) Sa magnificence couvre les Cieux, et la terre se remplit de ses louanges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Et c\'est un éclat pareil au jour, des rayons jaillissent de sa main; là s\'enveloppe sa majesté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Devant lui marche la peste, et la contagion paraît sur ses traces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Il s\'arrête et mesure la terre; Il regarde et fait trembler les peuples; les monts éternels éclatent, les collines antiques s\'affaissent; Il [suit] les voies anciennes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Je vois dans la détresse les tentes de l\'Ethiopie, et trembler les pavillons du pays de Madian.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Est-ce contre les fleuves que s\'irrite l\'Éternel? est-ce contre les fleuves qu\'il se courrouce? est-ce à la mer qu\'en veut ta fureur, que tu t\'avances avec tes chevaux sur ton char de victoire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Ton arc est tiré, les malédictions sont les traits de ta parole!... (Pause.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'La terre vomit des fleuves. Les montagnes te voient, elles tremblent, des torrents d\'eau se précipitent, l\'abîme fait retentir sa voix, il soulève ses bras en haut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Le soleil, la lune demeurent dans leur gîte à la lumière de tes flèches qui volent, à la splendeur de l\'éclair de ta lance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Dans ton courroux tu marches sur la terre, dans ta colère tu écrases les peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Tu sors pour sauver ton peuple, pour sauver ton Oint. Tu fracasses le faîte de la maison des impies, jusques au comble tu en mets à nu les bases. (Pause.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Tu perces de tes traits la tête de ses chefs qui s\'élancent pour me disperser, se réjouissent comme pour dévorer le malheureux dans l\'embuscade.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Tu foules la mer avec tes chevaux, l\'écume des grandes eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'J\'ai entendu et mon corps tremble; à cette voix mes lèvres s\'entre-choquent, la carie pénètre mes os, mes genoux tremblent sous moi qui dois être impassible au jour de la détresse, quand mon peuple est assailli par notre oppresseur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Car le figuier ne fleurit pas et la vigne ne donne pas de récolte, le jet de l\'olivier est trompeur, et les guérets ne donnent point de pain, dans le bercail il y a faute de brebis et plus de bœufs dans les étables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Toutefois je mets ma joie en l\'Éternel, et mon allégresse en Dieu mon sauveur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'L\'Éternel, le Seigneur est ma force, Il me donne les pieds de la biche pour me faire atteindre mes hauteurs. Au maître chantre sur le mode de mon luth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'La parole de l\'Éternel qui fut adressée à Sophonie, fils de Cusi, fils de Gédalia, fils d\'Amaria, fils d\'Ézéchias, au temps de Josias, fils d\'Amon, roi de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Je vais tout enlever de la surface de la terre, dit l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'enlever hommes et bêtes, enlever les oiseaux des Cieux et les poissons de la mer, et les scandales avec les impies, et j\'exterminerai les hommes de la surface du sol, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Et j\'étendrai ma main sur Juda, et sur tous les habitants de Jérusalem, et j\'exterminerai de ce lieu les restes de Baal, le nom des prêtres avec les sacrificateurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'et ceux qui adorent sur les toits l\'armée des Cieux, et ceux qui adorent l\'Éternel, lui prêtent serment et jurent par leur roi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'et ceux qui ont déserté l\'Éternel et qui ne cherchent point l\'Éternel, et ne se soucient pas de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Silence devant le Seigneur, l\'Éternel! car la journée de l\'Éternel est proche; car l\'Éternel a préparé un sacrifice, Il a sanctifié ses conviés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Et il arrivera au jour du sacrifice de l\'Éternel que je châtierai les princes et les fils du roi et tous ceux qui revêtent les vêtements de l\'étranger;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'et je châtierai tous ceux qui franchissent le seuil, en cette journée-là, et remplissent les maisons de leurs maîtres de rapine et de fraude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'En cette journée-là, dit l\'Éternel, des cris retentiront de la porte des poissons, et des gémissements de la ville basse et un grand fracas des collines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Gémissez, habitants du mortier! Car c\'en est fait de tout le peuple des Cananéens, et tous les hommes chargés d\'argent seront exterminés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Et dans ce temps-là je fouillerai Jérusalem aux lanternes et châtierai tous ces hommes assis sur leurs lies, qui disent en leur cœur: « L\'Éternel ne fait point de bien et point de mal. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Et leur opulence sera une proie, et leurs maisons une ruine; et ils ont bâti des maisons, mais ils ne les habiteront pas, et planté des vignes, mais ils n\'en boiront pas le vin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'La journée de l\'Éternel, la grande journée est proche, elle est proche, et s\'avance rapidement; on entend la journée de l\'Éternel; alors le héros poussera des cris amers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Ce jour-là est un jour de colère, un jour de détresse et d\'angoisse, un jour de dévastation et de désolation, un jour de ténèbres et d\'obscurité, un jour nuageux et sombre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'un jour de bruit de trompettes et de cris de guerre contre les villes fortes et les tours élevées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Et je mettrai les hommes à la gêne, et ils iront comme des aveugles, car ils péchèrent contre l\'Éternel, et leur sang sera répandu comme de la poussière, et leur chair comme de l\'ordure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Ni leur argent, ni leur or ne pourra les sauver au jour de la colère de l\'Éternel, et par le feu de son courroux tout le pays sera consumé; car c\'est d\'une ruine, oui, d\'une ruine soudaine, qu\'il frappera tous les habitants du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Recueillez, recueillez-vous, race qui ne pâlit plus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'avant que le décret enfante (comme la balle le temps passe), avant que fonde sur vous le feu de la colère de l\'Éternel, avant que fonde sur vous le jour de la colère de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Cherchez l\'Éternel, vous tous les humbles du pays, qui pratiquez sa loi, recherchez la justice, recherchez l\'humilité! Peut-être serez-vous mis à l\'abri au jour de la colère de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Car Gaza sera abandonnée, et Askalon désolée; Asdod en plein jour sera expulsée, et Hécron déracinée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Malheur aux habitants de la côte de la mer, au peuple des Crétites! La parole de l\'Éternel est prononcée contre toi, Canaan, terre des Philistins! et je te détruirai, t\'ôterai tes habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Et la côte de la mer sera des pâturages, un régal pour les bergers, et des parcs pour les troupeaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'et ce sera une côte pour les restes de la maison de Juda, et ils y paîtront; dans les maisons d\'Askalon le soir ils reposeront, car l\'Éternel, leur Dieu, tournera ses regards sur eux et ramènera leurs captifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'J\'ai ouï les outrages de Moab, et les insultes des enfants d\'Ammon, qui outragèrent mon peuple et fièrement s\'élevèrent contre ses frontières.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Aussi, par ma vie, dit l\'Éternel des armées, Dieu d\'Israël, Moab sera comme Sodome, et les enfants d\'Ammon comme Gomorrhe, la propriété des ronces et une mine de sel, et un désert éternel; les survivants de mon peuple les pilleront, et les restes de ma nation les posséderont.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Cela leur arrivera pour leur orgueil, parce qu\'ils furent insultants et superbes contre le peuple de l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Sur eux l\'Éternel sera terrible, car Il anéantit tous les dieux de la terre, et tous lui rendront hommage, chacun du lieu où il est, toutes les îles des nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Vous aussi, Éthiopiens, vous serez percés par mon épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Et Il étendra sa main vers le nord, et détruira l\'Assyrie et fera de Ninive une solitude aride comme le désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Et dans son enceinte se coucheront les troupeaux, tous les animaux par bandes; le pélican aussi et le hérisson logeront dans ses chapiteaux; un ramage retentira aux fenêtres; des ruines seront sur le seuil, car les lambris de cèdre auront été mis à nu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'La voilà cette ville dont la joie est insolente, qui habite en sécurité, qui dit en son cœur: Moi, et hors moi rien! Comment est-elle devenue un désert, un repaire pour les bêtes? Quiconque passera devant elle, sifflera et agitera la main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Malheur à la réfractaire et souillée, à la cité qui opprime!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Elle n\'est docile à aucune voix, ne reçoit pas instruction, en l\'Éternel elle ne se confie pas, de son Dieu elle ne s\'approche pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Ses princes dans son sein sont des lions rugissants, ses juges des loups du soir, ils ne réservent rien pour le lendemain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Ses prophètes sont des fanfarons, des hommes perfides, ses sacrificateurs profanent le sanctuaire, violent la loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'L\'Éternel est juste au milieu d\'elle, Il ne fait rien d\'injuste, chaque matin Il produit au jour ses lois, Il n\'y manque point; mais le méchant ne connaît point de pudeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'J\'ai exterminé des peuples; leurs tours ont été dévastées; j\'ai désolé leurs rues, tellement qu\'il n\'y a plus de passants; leurs villes ont été détruites, dépeuplées, privées d\'habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'J\'ai dit: « Pourvu que tu me craignes, que tu reçoives instruction, » la ruine de sa demeure n\'arriverait pas, tout le châtiment que je lui avais destiné. Mais dès le matin ils ont perverti toutes leurs œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Aussi attendez-moi, dit l\'Éternel, pour le jour où je me lèverai pour faire du butin; car j\'ai arrêté de rassembler les peuples, de réunir les royaumes pour verser sur eux ma fureur, toute l\'ardeur de ma colère, car au feu de mon courroux toute la terre sera consumée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Car alors je donnerai aux peuples des lèvres nouvelles, afin qu\'ils invoquent tous le nom de l\'Éternel et le servent unanimement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'De par-delà les fleuves de l\'Ethiopie mes adorateurs, les enfants de mes dispersés, apporteront mes offrandes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'En ce temps-là tu n\'auras plus à rougir de tous les faits dont tu t\'es rendue coupable envers moi, car alors j\'éloignerai de toi tes insolents triomphants, et désormais tu ne t\'enorgueilliras plus sur ma sainte montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Et je laisserai au milieu de toi un peuple pauvre et chétif, qui se confie dans le nom de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Les restes d\'Israël ne commettront pas l\'iniquité ni ne proféreront le mensonge, et il ne se trouvera dans leur bouche point de langue trompeuse, mais on les fera paître, et ils reposeront sans être troublés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Jubile, fille de Sion! chante victoire, Israël! livre à la joie et à l\'allégresse ton cœur tout entier, fille de Jérusalem!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'L\'Éternel retire la sentence portée contre toi, Il éloigne ton ennemi: le Roi d\'Israël au milieu de toi, c\'est l\'Éternel; désormais tu ne connaîtras plus les maux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'En ce jour on dira à Jérusalem: Ne crains point! Sion, que tes bras ne défaillent point!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'L\'Éternel, ton Dieu, est au milieu de toi, héros sauveur; tu feras sa joie et ses délices; dans son amour Il gardera le silence, tu feras son allégresse et son ravissement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Je recueille ceux qui s\'attristent éloignés de l\'assemblée; ils t\'appartiennent, ils sont sous le poids de l\'opprobre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Voici, j\'aurai affaire à tous tes oppresseurs en ce temps-là, et je sauverai ce qui boite et recueillerai ce qui sera dispersé, et leur ferai obtenir de la louange et de la gloire dans tous les pays où ils subissent l\'opprobre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'Dans ce temps-là je vous ramènerai, et en ce même temps je vous recueillerai, car je vous rendrai célèbres et illustres auprès de tous les peuples de la terre, en ramenant vos captifs, sous vos yeux, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'La seconde année du roi Darius, le sixième mois, le premier jour du mois, la parole de l\'Éternel fut adressée par Aggée, le prophète, à Zorobabel, fils de Salathiel, gouverneur de Juda, et à Josué, fils de Jéhotsadak, grand sacrificateur, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Ainsi parle l\'Éternel des armées: Ce peuple dit: Le moment n\'est pas encore venu, le moment où la maison de l\'Éternel doit être rebâtie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'C\'est pourquoi la parole de l\'Éternel fut adressée par Aggée, le prophète, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Est-ce le moment pour vous-mêmes de vous loger dans vos maisons lambrissées, tandis que cette maison est en ruine?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Or ainsi parle l\'Éternel des armées: Soyez attentifs à la voie où vous êtes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Vous semez beaucoup et récoltez peu, vous mangez, mais non pas jusqu\'à rassasiement, vous buvez, mais non pas votre soûl; vous avez des habits, mais non jusqu\'à avoir chaud, et celui qui sert pour un gage, met ses gains dans une bourse trouée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Ainsi parle l\'Éternel des armées: Soyez attentifs à la voie où vous êtes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Montez à la montagne et en amenez du bois, et bâtissez la maison, afin que j\'en aie du plaisir et que gloire me soit rendue, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Vous comptiez sur beaucoup, et voici, vous avez peu; et si vous l\'amenez à la maison, je le dissipe. Pourquoi? dit l\'Éternel des armées. A cause de ma maison qui est en ruine, tandis que vous êtes empressés chacun pour sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'C\'est pourquoi au-dessus de vous les Cieux retiennent la rosée, et la terre retient son produit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'et j\'ai appelé la sécheresse sur le pays et sur les montagnes, et sur le blé, et sur le moût, et sur l\'huile, et sur tout ce que produit le sol, et sur l\'homme, et sur le bétail, et sur tout le travail des mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Et Zorobabel, fils de Salathiel, et Josué, fils de Jéhotsadak, grand sacrificateur, et tous les restes du peuple furent dociles à la voix de l\'Éternel, leur Dieu, et aux paroles d\'Aggée, le prophète, parce que l\'Éternel, leur Dieu, l\'avait envoyé, et le peuple eut crainte de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Et Aggée, envoyé de l\'Éternel, parla en vertu de la mission de l\'Éternel au peuple en ces mots: Je suis avec vous, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Et l\'Éternel donna l\'éveil à l\'esprit de Zorobabel, fils de Salathiel, gouverneur de Juda, et à l\'esprit de Josué, fils de Jéhotsadak, grand sacrificateur, et à l\'esprit de tous les restes du peuple, et ils vinrent et se mirent à l\'œuvre dans la maison de l\'Éternel des armées, leur Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'le vingt-quatrième jour du sixième mois, la seconde année du roi Darius.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Le septième mois, le vingt-unième jour du mois, la parole de l\'Éternel fut adressée par Aggée, le prophète, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Parle donc à Zorobabel, fils de Salathiel, gouverneur de Juda, et à Josué, fils de Jéhotsadak, grand sacrificateur, et aux restes du peuple, et dis:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Qui d\'entre vous a assez vécu pour avoir vu cette maison dans sa splendeur première? Et dans quel état! la voyez-vous maintenant? n\'est-ce pas, une telle maison est comme rien à vos yeux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Mais maintenant, courage, Zorobabel! dit l\'Éternel, courage, Josué, fils de Jéhotsadak, grand sacrificateur! et courage, vous, tout le peuple du pays! dit l\'Éternel, et travaillez! car je suis avec vous, dit l\'Éternel des armées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'aux termes de l\'alliance que je conclus avec vous à votre sortie de l\'Egypte, et mon Esprit demeure au milieu de vous; soyez sans crainte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Car ainsi parle l\'Éternel des armées: Encore un peu de temps, et j\'ébranlerai les Cieux et la terre, et la mer et la terre sèche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'et j\'ébranlerai toutes les nations, et les objets précieux de tous les peuples afflueront, et je remplirai cette maison de splendeur, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'A moi est l\'argent, et à moi l\'or, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'La gloire à venir de cette maison sera plus grande que la première, dit l\'Éternel des armées, et dans ce lieu-ci j\'établirai la paix, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Le vingt-quatrième jour du neuvième mois, la seconde année de Darius, la parole de l\'Éternel fut adressée par Aggée, le prophète, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Ainsi parle l\'Éternel des armées: Propose aux sacrificateurs une question de loi, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Si quelqu\'un porte de la chair sacrée dans la bordure de son manteau, et que de cette bordure il touche du pain ou du légume ou du vin et de l\'huile et un aliment quelconque, ces choses en deviendront-elles sacrées? Et les sacrificateurs répondirent et dirent: Non!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Et Aggée dit: Si un homme souillé par un cadavre touche à toutes ces choses, seront-elles souillées? Et les sacrificateurs répondirent et dirent: Elles seront souillées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Alors Aggée prit la parole et dit: Il en est de même de ce peuple et de toute cette nation à mes yeux, dit l\'Éternel, et ainsi de toute l\'œuvre de leurs mains, et toutes les offrandes qu\'ils font là, sont souillées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Et maintenant soyez attentifs [au temps écoulé] depuis aujourd\'hui en remontant au jour où l\'on ne mettait pas encore pierre sur pierre dans le temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Dès ce moment on venait à un tas de blé pour trouver vingt, et il n\'y avait que dix; on venait à la cuve pour puiser cinquante au pressoir, et il n\'y avait que vingt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Je vous frappai par le charbon et la nielle et la grêle dans les travaux de vos mains, mais vous ne revîntes pas à moi, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Soyez attentifs [au temps écoulé] depuis aujourd\'hui en remontant, depuis le vingt-quatrième jour du neuvième mois au jour où fut fondé le temple de l\'Éternel, soyez attentifs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Y a-t-il encore du grain dans les greniers? et de plus, la vigne et le figuier et le grenadier et l\'olivier n\'ont rien produit. Mais dès ce jour je vous bénirai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Et la parole de l\'Éternel fut adressée pour la seconde fois à Aggée, le vingt-quatrième jour du mois, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Parle à Zorobabel, gouverneur de Juda, et dis:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'J\'ébranlerai les Cieux et la terre, et je renverserai les trônes des rois, et je détruirai la puissance des empires des peuples, et je renverserai les chars et ceux qui les montent, et les chevaux et leurs cavaliers seront culbutés, par l\'épée les uns des autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'Dans ce même temps, dit l\'Éternel des armées, je te prendrai, Zorobabel, fils de Salathiel, mon serviteur, dit l\'Éternel, et te garderai comme un sceau; car je t\'ai choisi, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Le huitième mois, la seconde année de Darius, la parole de l\'Éternel fut adressée à Zacharie, fils de Barachie, fils de Iddo, le prophète, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'L\'Éternel a été irrité, irrité contre vos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Dis-leur donc: Ainsi parle l\'Éternel des armées: Revenez à moi, dit l\'Éternel des armées, et je reviendrai à vous, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Ne soyez pas comme vos pères à qui les premiers prophètes criaient et disaient: « Ainsi parle l\'Éternel des armées: Quittez donc vos voies mauvaises et vos mauvaises œuvres! » mais ils n\'écoutèrent point et ne tinrent nul compte de moi, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Vos pères, où sont-ils? et les prophètes vivent-ils éternellement?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Cependant mes paroles et mes décrets dont j\'avais chargé mes serviteurs, les prophètes, n\'ont-ils pas atteint vos pères? Et ils se convertirent et dirent: Comme l\'Éternel des armées avait résolu de nous traiter selon nos voies et nos œuvres, ainsi nous a-t-Il traités.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Le vingt-quatrième jour du onzième mois (c\'est le mois de Sébat), la seconde année de Darius, la parole de l\'Éternel fut adressée à Zacharie, fils de Barachie, fils de Iddo, le prophète, en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'J\'eus une vision pendant la nuit, et voici, c\'était un homme monté sur un cheval rouge, et il se tenait parmi les myrtes qui étaient dans un fond, et derrière lui étaient des chevaux rouges, fauves et blancs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Et je dis: Qui sont-ils, mon Seigneur? Et l\'ange qui parlait avec moi, me dit: Je te ferai voir qui ils sont.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Et l\'homme qui se tenait parmi les myrtes, prit la parole et dit: Ce sont ceux que l\'Éternel a envoyés parcourir la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Et ils répondirent à l\'ange de l\'Éternel qui se tenait parmi les myrtes, et dirent: Nous avons parcouru la terre, et voici, toute la terre est calme et tranquille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Et l\'ange de l\'Éternel répondit et dit: Éternel des armées, jusques à quand seras-tu sans pitié pour Jérusalem et les villes de Juda contre lesquelles tu fus irrité ces soixante-dix ans?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Et l\'Éternel répondit à l\'ange qui parlait avec moi, des paroles de bonté, des paroles de consolation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Et l\'ange qui parlait avec moi, me dit: Proclame ces paroles: Ainsi parle l\'Éternel des armées: J\'ai pour Jérusalem et Sion une vive passion;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'aussi suis-je ému d\'un grand courroux contre les nations [maintenant] en sécurité: quand j\'étais un peu irrité [contre Juda], elles contribuèrent à son malheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Aussi ainsi parle l\'Éternel: Je reviens à Jérusalem avec des miséricordes; ma maison y sera bâtie, dit l\'Éternel des armées, et le cordeau sera tendu sur Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Proclame encore ces paroles: Ainsi parle l\'Éternel des armées: Mes villes regorgeront encore de biens et l\'Éternel consolera encore Sion et fera encore choix de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Et je levai les yeux et regardai, et voici quatre cornes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'Et je dis à l\'ange qui parlait avec moi: Qu\'est-ce? Et il me dit: Ce sont les cornes qui ont dispersé Juda, Israël et Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Et l\'Éternel me fit voir quatre forgerons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'Et je dis: Que viennent-ils faire? Et Il dit: Ce sont les cornes qui ont dispersé Juda de telle sorte que nul homme ne releva la tête; et ceux-ci viennent pour les épouvanter, pour abattre les cornes des nations qui ont levé la corne contre le pays de Juda pour le disperser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Et je levai les yeux et regardai, et voici un homme ayant dans sa main un cordeau à mesurer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Et je dis: Où vas-tu? Et il me dit: Prendre la mesure de Jérusalem, voir quelle en sera la largeur, et quelle en sera la longueur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Et voici, l\'ange qui parlait avec moi s\'avança, et un autre ange s\'avança au-devant de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'Et il dit à celui-ci: Cours! et parle ainsi à ce jeune homme-là: Jérusalem sera habitée comme ville ouverte, tant il y aura d\'hommes et de bestiaux en son sein;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'et moi je serai pour elle, dit l\'Éternel, un mur de feu qui l\'entoure, et je serai une gloire au milieu d\'elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Sus! sus! fuyez du pays du nord, dit l\'Éternel, car je vous ai disséminés aux quatre vents des Cieux, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Sus, ô Sion! sauve-toi, toi qui habites chez la fille de Babel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Car ainsi parle l\'Éternel des armées: C\'est après la gloire qu\'il m\'a envoyé chez les peuples qui vous ont dépouillés (car qui vous touche, touche à la prunelle de son œil).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'En effet voici, je brandis ma main sur eux et ils seront la proie de ceux qui leur furent asservis, et vous saurez que l\'Éternel des armées m\'a envoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Sois dans la joie et l\'allégresse, fille de Sion! car voici, je viens et j\'habiterai dans ton sein, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Et beaucoup de peuples s\'attacheront à l\'Éternel en ce jour-là, et deviendront mon peuple, et j\'habiterai dans ton sein et tu sauras que l\'Éternel des armées m\'a envoyé auprès de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Et l\'Éternel possédera Juda comme son lot dans la terre sainte, et fera encore choix de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Silence, vous tous qui êtes chair, en présence de l\'Éternel! car II se lève de sa demeure sainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Et Il me fit voir Josué, le grand sacrificateur, debout devant l\'ange de l\'Éternel, et Satan debout à sa droite pour l\'attaquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Et l\'Éternel dit à Satan: Que l\'Éternel te tance, Satan, que l\'Éternel te tance, lui qui a choisi Jérusalem! Celui-ci n\'est-il pas un tison sauvé du feu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Et Josué était vêtu d\'habits sales, et se tenait debout devant l\'ange;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'lequel prit la parole et dit à ceux qui étaient debout devant lui: Otez-lui ses habits sales! et lui dit: Voici! je te décharge de ton crime, et te revêts de superbes habits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Et je dis: Qu\'on pose une tiare pure sur sa tête! Et ils posèrent une tiare pure sur sa tête et lui mirent des habits. Et l\'ange de l\'Éternel y présidait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Et l\'ange de l\'Éternel lit à Josué cette déclaration solennelle:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Ainsi parle l\'Éternel des armées: Si tu suis mes voies et observes mes ordonnances, tu jugeras aussi ma maison, et garderas mes parvis, et je te donnerai des guides parmi ceux qui sont ici présents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Écoute donc, Josué, grand sacrificateur, toi et tes collègues siégeant devant toi! (Car ce sont des hommes figuratifs; car, voici, je fais arriver mon serviteur, le Germe.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Car, voici, la pierre que j\'ai placée devant Josué, sur cette seule pierre sept yeux sont fixés et j\'en graverai les traits, dit l\'Éternel des armées, et j\'enlèverai le crime de ce pays en un jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'En ce jour-là, dit l\'Éternel des armées, vous vous crierez l\'un à l\'autre: Sous la vigne et sous le figuier!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Et l\'ange qui parlait avec moi revint, et me réveilla comme un homme que l\'on réveille de son sommeil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Et il me dit: Que vois- tu? Et je dis: Je vois! et voici un chandelier tout d\'or, ayant son réservoir à son sommet et portant sept lampes, et sept tuyaux pour chacune des lampes qui sont à son sommet;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'et auprès, deux oliviers, un à droite du réservoir et un à sa gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Et je pris la parole et dis à l\'ange qui parlait avec moi: Qu\'est-ce que cela, mon Seigneur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Et l\'ange qui parlait avec moi, répondit et me dit: Ne sais-tu pas ce que c\'est? Et je dis: Non! mon Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Et il répondit et me dit: C\'est ici la parole de l\'Éternel adressée à Zorobabel: Ni par la force, ni par la puissance, mais par mon Esprit, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Qui es-tu, grosse montagne? Devant Zorobabel aplanis-toi! Il fait saillir la pierre du faîte aux cris de: La grâce! la grâce pour elle!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Et la parole de l\'Éternel me fut adressée en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Les mains de Zorobabel ont fondé cette maison, et ses mains l\'achèveront, et tu sauras que l\'Éternel des armées m\'a envoyé à vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Car qui pourrait mépriser le jour des faibles commencements? Avec joie ils contempleront le plomb dans la main de Zorobabel, ces sept, les yeux de l\'Éternel qui parcourent toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Et je répondis et lui dis: Que sont ces deux oliviers à la droite du chandelier et à sa gauche?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Et reprenant une seconde fois la parole je lui dis: Que sont ces deux rameaux d\'olivier qui touchent aux deux conduits d\'or d\'où découle la liqueur dorée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Et il me dit: Ne sais-tu pas ce que c\'est? Et je dis: Non! mon Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Et il dit: Ce sont les deux oints qui se tiennent debout auprès du Seigneur de toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Et de nouveau je levai les yeux et regardai, et voici un volume qui volait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Et il me dit: Que vois-tu? Et je dis: Je vois un volume qui vole; sa longueur est de vingt coudées, et sa largeur de dix coudées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Et il me dit: C\'est la malédiction qui se promène sur tout le pays, et ensuite de laquelle, d\'une part, tout voleur sera exterminé, et d\'autre part, tout parjure sera exterminé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Je l\'ai lancée, dit l\'Éternel des armées, afin qu\'elle entre dans la maison du voleur, et dans la maison de qui fait par mon nom de faux serments, qu\'elle séjourne dans sa maison et la détruise toute, et son bois et ses pierres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Et l\'ange qui parlait avec moi, parut et me dit: Lève donc les yeux et regarde! qu\'est-ce qui sort là? Et je dis: Qu\'est-ce?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Et il dit: C\'est l\'épha sortant. Et il dit: C\'est à cela qu\'ils visent dans tout le pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Et voici, une masse de plomb fut soulevée, et il y avait dans l\'épha une femme assise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Et il dit: C\'est l\'Impiété. Et il la repoussa au dedans de l\'épha dont il referma l\'ouverture avec la masse de plomb.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Et je levai les yeux et regardai, et voici, deux femmes parurent: le vent était dans leurs ailes, et elles avaient des ailes comme des ailes de cigogne, et elles enlevèrent l\'épha entre la terre et le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Et je dis à l\'ange qui parlait avec moi: Où emportent-elles l\'épha?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Et il me dit: Elles vont lui établir une demeure dans le pays de Sinear, et une fois consolidée, il y sera posé sur son piédestal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Et de nouveau je levai les yeux et je regardai, et voici quatre chars qui partaient d\'entre deux montagnes, et les montagnes étaient des montagnes d\'airain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Au premier char étaient des chevaux rouges, et au second char des chevaux noirs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'et au troisième char des chevaux blancs, et au quatrième char des chevaux tachetés, vigoureux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Et je pris la parole et dis à l\'ange qui parlait avec moi:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Qu\'est-ce, mon Seigneur? Et l\'ange répondit et me dit: Ce sont les quatre vents des Cieux qui sortent après avoir pris les ordres du Seigneur de toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Les chevaux noirs attelés à l\'un partirent pour le pays du nord, et les blancs partirent après eux, et les tachetés partirent pour le pays du midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Et les rouges partirent et demandèrent à parcourir la terre. Et il dit: Allez, parcourez la terre! Et ils parcoururent la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Et il m\'interpella et me parla en disant: Vois, ceux qui partent pour le pays du nord, font reposer ma colère sur le pays du nord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Et la parole de l\'Éternel me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Accepte de la part des captifs, Heldaï, Tobie et Jédaïa (et en ce même jour va, va dans la maison de Josias, fils de Sophonie, où ils sont descendus en arrivant de Babel)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'accepte, [dis-je], de l\'argent et de l\'or et en fais des couronnes, et pose-les sur la tête de Josué, fils de Jéhotsadak, grand sacrificateur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'et dis-lui: Ainsi parle l\'Éternel des armées: Voici, un homme dont le nom est Germe et qui croîtra sur son lieu même, bâtira le temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Et c\'est lui qui bâtira le temple de l\'Éternel, et il portera les insignes de la majesté et siégera, et exercera la royauté sur son trône et la sacrificature sur son trône, et le conseil de la paix sera entre elles deux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Et les couronnes seront pour Hélem et pour Tobie, et pour Jédaïa, et pour Hen fils de Sophonie, un mémorial dans le temple de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Et des [peuples] lointains viendront et travailleront au temple de l\'Éternel, et vous saurez que l\'Éternel des armées m\'a envoyé à vous. Et cela arrivera, si vous écoutez la voix de l\'Éternel, votre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Et la quatrième année du roi Darius, la parole de l\'Éternel fut adressée à Zacharie, le quatrième jour du neuvième mois, celui de Cisleu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Et la maison de Dieu envoya Scharetser et Régem-Mélech et leurs gens pour implorer l\'Éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'et dire aux sacrificateurs de la maison de l\'Éternel des armées et aux prophètes: « Continuerai-je à prendre le deuil au cinquième mois, avec abstinence, ainsi que je le fais depuis combien d\'années? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Et la parole de l\'Éternel des armées me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Dis à tout le peuple du pays et aux sacrificateurs: Quand vous avez jeûné et pris le deuil au cinquième et au septième mois, et cela pendant ces soixante-dix ans, est-ce pour moi que vous avez jeûné?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Et quand vous mangez et buvez, n\'est-ce pas vous qui mangez, et vous qui buvez?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'N\'avez-vous pas les paroles que proclama l\'Éternel par les premiers prophètes, quand Jérusalem était habitée et tranquille avec les villes de ses alentours, et que le midi et le bas pays étaient habités?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Et la parole de l\'Éternel fut adressée à Zacharie en ces mots: Ainsi a dit l\'Éternel des armées:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Rendez la justice en vérité, et traitez-vous l\'un l\'autre avec bonté et miséricorde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'et n\'opprimez ni la veuve, ni l\'orphelin, ni l\'étranger, ni le pauvre, et ne pensez pas à mal l\'un contre l\'autre dans vos cœurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Mais ils refusèrent d\'être attentifs, et opposèrent une épaule rénitente, et se bouchèrent les oreilles pour ne point entendre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'et ils endurcirent leurs cœurs comme le diamant, pour ne pas entendre la loi et les paroles qu\'envoyait l\'Éternel des armées par son Esprit, par les premiers prophètes; et ainsi survint une grande colère de l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Et il arriva que, comme Il appela et qu\'ils n\'écoutèrent pas, de même ils appelèrent, et je n\'écoutai pas, dit l\'Éternel des armées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'et je les disséminai parmi tous les peuples qu\'ils ne connaissaient pas; et le pays demeura désert derrière eux; il n\'y avait ni allant ni venant, et ils firent ainsi d\'un pays de délices une solitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Et la parole de l\'Éternel des armées fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Ainsi parle l\'Éternel des armées: Pour Sion un grand zèle m\'anime, et par un grand courroux je lui montre mon zèle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Ainsi parle l\'Éternel: Je reviens en Sion et fixe ma demeure au sein de Jérusalem; et Jérusalem sera nommée Cité fidèle, et la montagne de l\'Éternel des armées Montagne sainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Ainsi parle l\'Éternel des armées: Des vieillards et des femmes âgées s\'assiéront encore dans les rues de Jérusalem, ayant chacun son bâton à la main à cause de leur grand âge;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'et les rues de la ville seront remplies de jeunes garçons et de jeunes filles jouant dans ses rues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Ainsi parle l\'Éternel des armées: Si la chose est impossible aux yeux des restes de ce peuple dans ces jours-là, sera-t-elle aussi impossible à mes yeux, dit l\'Éternel des armées?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Ainsi parle l\'Éternel des armées: Voici, je sauverai mon peuple du pays du lever et du pays du coucher du soleil;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'et je les ramènerai, et ils habiteront au sein de Jérusalem, et ils seront mon peuple, et moi je serai leur Dieu en vérité et en justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Ainsi parle l\'Éternel des armées: Que vos mains reprennent force, à vous tous qui en ces jours entendîtes ces paroles de la bouche des prophètes, qui parurent au temps où fût fondée la maison de l\'Éternel des armées, le temple pour être relevé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Car avant ces jours-là l\'homme ne retirait point le prix de sa peine, ni le bétail le prix de sa peine, et à ceux qui entraient et sortaient l\'ennemi ne laissait point de paix, et je mettais aux prises les hommes les uns avec les autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Mais maintenant je ne serai pas envers les restes de ce peuple, comme j\'ai été dans les premiers jours, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Car les semailles se feront en paix, la vigne donnera son fruit et la terre donnera son produit, et les Cieux donneront leur rosée, et je donnerai au reste de ce peuple la propriété de toutes ces choses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'et de même que vous fûtes parmi les peuples en malédiction, maison de Juda et maison d\'Israël, de même je veux vous sauver, et vous serez en bénédiction. N\'ayez point de peur, que vos mains se raffermissent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Car ainsi parle l\'Éternel des armées: De même que je pensai à vous faire du mal, quand vos pères m\'irritèrent, dit l\'Éternel des armées, et que je n\'en eus point de repentir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'ainsi je pense de nouveau en ces jours à faire du bien à Jérusalem et à la maison de Juda. N\'ayez point de peur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Voici les choses que vous devez faire: parlez-vous vrai l\'un à l\'autre, rendez vos jugements dans vos Portes selon la vérité et en vue de la paix;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'que nul ne pense à mal contre son prochain dans son cœur, et n\'aimez pas le faux serment, car ce sont tout autant de choses que je hais, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Et la parole de l\'Éternel des armées me fut adressée en ces mots:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Ainsi parle l\'Éternel des armées: Le jeûne du quatrième mois et le jeûne du cinquième, et le jeûne du septième et le jeûne du dixième se changeront pour la maison de Juda en joie et en allégresse, et en fêtes de bonheur... Mais aimez la vérité et la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Ainsi parle l\'Éternel des armées: Un jour encore viendront des peuples et les habitants de beaucoup de villes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'et les habitants d\'une ville aborderont ceux de l\'autre en disant: Allons implorer l\'Éternel et chercher l\'Éternel des armées! Je veux aller aussi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Et beaucoup de peuples et de nombreuses nations viendront chercher l\'Éternel des armées à Jérusalem et implorer l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Ainsi parle l\'Éternel des armées: En ces jours-là dix hommes de toutes les langues des nations saisiront le pan du manteau d\'un Juif et diront: Nous voulons aller avec vous, car nous avons appris que Dieu est avec vous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Prononcé de la parole de l\'Éternel contre le pays de Hadrach, et sur Damas elle vient s\'arrêter, (car l\'Éternel a l\'œil sur les hommes et sur toutes les tribus d\'Israël)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'et sur Hamath aussi qui touche à ses confins, sur Tyr et Sidon qui a tant de sagesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Tyr se bâtit des remparts et entassa l\'argent comme la poussière, et l\'or comme la boue des rues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Voici, le Seigneur s\'en rend maître et abat dans la mer ses fortifications, et elle est dévorée par le feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Askalon le voit et s\'effraie, et Gaza qui en tremble fort, ainsi que Hécron; car son espoir est déjoué, et le roi est exterminé de Gaza, et Askalon est sans habitants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Et une race étrangère habite en Asdod, et je détruis l\'orgueil des Philistins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Et je lui ôte le sang de la bouche, et les abominations d\'entre les lèvres, et celui-ci aussi reste pour notre Dieu, et il est comme un chef en Juda, et Hécron comme un Jébusien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Et par un camp je défends ma maison contre l\'agresseur, et contre ceux qui passent et repassent, et l\'oppresseur ne les envahira plus; car maintenant j\'y regarde de mes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Sois transportée de joie, fille de Sion! pousse des cris, fille de Jérusalem! Voici, ton Roi vient à toi, il est juste et rendu vainqueur, pauvre et ayant pour monture un âne, un poulain, le petit d\'une ânesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Et j\'exterminerai les chars d\'Éphraïm et les chevaux de Jérusalem, et les arcs de guerre seront exterminés: et il parlera de paix aux peuples, et son empire ira d\'une mer à l\'autre mer, et du Fleuve aux extrémités de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Et je veux aussi, en vertu de ton alliance scellée par le sang, retirer pour toi tes captifs de la fosse qui est sans eau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Revenez au fort, captifs qui espérez! Aujourd\'hui encore je le déclare, je te rendrai au double.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Car je me bande Juda comme un arc, et je l\'arme d\'Éphraïm, et je fais lever tes enfants, ô Sion, contre tes enfants, ô Javan, et je te rends pareille à l\'épée d\'un héros.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Et l\'Éternel sur eux apparaîtra, et sa flèche partira comme l\'éclair, et le Seigneur, l\'Éternel, sonnera de la trompette, et s\'avancera dans les tempêtes du midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'L\'Éternel des armées les protégera, et ils dévoreront [leurs ennemis] et les fouleront comme des pierres de fronde, et boiront [leur sang] et feront vacarme comme dans le vin, et seront remplis comme les coupes des sacrifices, comme les angles de l\'autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Et l\'Éternel, leur Dieu, les sauvera en ce jour-là, comme un troupeau, son peuple, car ils seront les pierreries d\'un diadème, saillantes dans son pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'En effet, quelle sera leur beauté! quel sera leur éclat! Le blé donnera croissance à de jeunes hommes, et le moût à des vierges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Demandez à l\'Éternel la pluie au temps de l\'arrière-saison; l\'Éternel fera éclater la foudre et Il leur donnera la pluie par torrents, à chacun de l\'herbe dans son champ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Car les Théraphims ont un langage vain, et les devins des visions menteuses, les songes expriment ce qui n\'est pas, c\'est par le néant qu\'ils consolent; c\'est pourquoi ils sont emmenés comme des brebis, ils sont misérables, parce qu\'il n\'y a point de pasteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Contre les pasteurs ma colère s\'enflamme et des boucs je veux tirer vengeance, car l\'Éternel des armées vengera son troupeau, la maison de Juda, et Il en fait son superbe cheval de bataille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'De son sein sortira la pierre angulaire, de son sein ses soutiens, de son sein les arcs de guerre, de son sein tous les chefs ensemble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Et ils seront comme des héros qui foulent aux pieds la boue des rues dans le combat, et ils combattront, parce que l\'Éternel sera avec eux, et les cavaliers sur leurs chevaux seront couverts de honte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Et je donnerai force à la maison de Juda et salut à la maison de Joseph, et leur rendrai leurs demeures, car je prends pitié d\'eux, et ils seront comme n\'ayant pas été rejetés de moi, car je suis l\'Éternel, leur Dieu, et je les exaucerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Et Éphraïm sera comme un héros, et leur cœur aura la joie que donne le vin, et leurs enfants le verront et en seront joyeux, et leur cœur se réjouira en l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'D\'un cri je les appellerai et les recueillerai, car je les ai rachetés, et ils seront nombreux comme ils furent nombreux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Je les dissémine parmi les peuples, mais dans les pays lointains ils se souviendront de moi: aussi vivront-ils avec leurs enfants, et il y aura pour eux un retour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Et je les tirerai du pays d\'Egypte, et les recueillerai de l\'Assyrie et les conduirai au pays de Galaad et au Liban, où l\'espace ne leur suffira pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Et [l\'Éternel] passera la mer étroite et frappera les flots dans la mer, et toutes les profondeurs du Nil seront desséchées, et l\'orgueil d\'Assur abaissé, et le sceptre de l\'Egypte disparu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Et je les fortifierai dans l\'Éternel; et en son nom ils marcheront, dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Liban, ouvre tes portes, et que le feu dévore tes cèdres!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Cyprès, gémis, car le cèdre tombe, ceux qui s\'élèvent sont dévastés; gémissez, chênes de Basan, car la forêt inaccessible tombe!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Écoutez! les bergers gémissent, car leur gloire est anéantie. Écoutez! les lions rugissent, car la parure du Jourdain est anéantie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Ainsi parle l\'Éternel, mon Dieu: Sois le pasteur des brebis à tuer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'que leurs acheteurs égorgent sans être coupables, et dont les vendeurs disent: « Loué soit l\'Éternel, car je me suis enrichi! » et que les pasteurs n\'épargnent point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Car je n\'épargnerai plus les habitants du pays, dit l\'Éternel; et voici, je vais livrer les hommes aux mains les uns des autres, et aux mains de leur Roi, et ils extermineront le pays, et je ne délivrerai pas de leurs mains. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Et je fus le pasteur des brebis à tuer, à cause de leur misère extrême. Et je pris deux houlettes: à l\'une je donnai le nom de Grâce, et à l\'autre le nom d\'Union, et je fis paître les brebis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Et je détruisis les trois pasteurs en un mois; et j\'étais las d\'eux, et ils avaient aussi de l\'aversion pour moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Alors je dis: Je ne veux pas être votre pasteur. Meure qui doit mourir, et périsse qui doit périr, et que les survivantes dévorent la chair l\'une de l\'autre!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Et je pris ma houlette Grâce et la brisai, pour rompre mon alliance conclue par moi avec tous les peuples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Et elle fut rompue en ce jour-là, et par là les plus malheureuses brebis qui regardèrent vers moi, comprirent que c\'était la parole de l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Et je leur dis: S\'il vous semble bon, donnez-moi mon salaire; sinon, n\'en faites rien! Et ils me pesèrent mon salaire, trente sicles d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Et l\'Éternel me dit: Jette-le au potier, ce prix magnifique auquel ils m\'évaluent. Et je pris les trente sicles d\'argent et les jetai dans la maison de l\'Éternel pour le potier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Et je brisai ma seconde houlette Union, pour rompre la fraternité entre Juda et Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Et l\'Éternel me dit: Prends encore l\'équipement d\'un pasteur insensé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'car voici, je susciterai un pasteur dans le pays, qui ne s\'inquiétera pas des brebis perdues, n\'ira pas à la recherche de celles qui s\'égarent, et ne guérira pas les blessées, et ne sustentera pas les saines, et mangera la chair des grasses, et entr\'ouvrira leur sabot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Malheur au méchant pasteur qui abandonne ses brebis! que l\'épée fonde sur son bras et sur son œil droit! que son bras sèche, et que son œil droit s\'éteigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Prononcé de la parole de l\'Éternel sur Israël. Ainsi parle l\'Éternel, qui déploya les Cieux et fonda la terre, et forma l\'esprit de l\'homme au dedans de lui:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Voici, je ferai de Jérusalem un seuil qui branle pour tous les peuples d\'alentour, et Juda sera aussi compris dans le siège de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Et en ce jour-là je ferai de Jérusalem une pierre à soulever pour tous les peuples; tous ceux qui la soulèveront, s\'y déchireront, et tous les peuples de la terre s\'assembleront contre elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'En ce jour-là, dit l\'Éternel, je frapperai tous les chevaux d\'épouvante, et leurs cavaliers du délire, mais j\'aurai l\'œil ouvert sur la maison de Juda, et je frapperai tous les chevaux des peuples de cécité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Alors les chefs de Juda diront en leurs cœurs: Notre force est dans les habitants de Jérusalem, par l\'Éternel des armées, leur Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'En ce jour-là je rendrai les chefs de Juda pareils à un fourneau ardent parmi des arbres, et à une torche ardente parmi des gerbes, et ils dévoreront à droite et à gauche tous les peuples d\'alentour, et Jérusalem demeurera assise sur son sol à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Et l\'Éternel sera d\'abord en aide aux tentes de Juda, afin que la gloire de la maison de David et la gloire des habitants de Jérusalem ne s\'élève pas au-dessus de Juda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'En ce jour-là, l\'Éternel protégera les habitants de Jérusalem, et le faible parmi eux en ce jour-là sera comme David, et la maison de David semblable à Dieu, à l\'ange de l\'Éternel à leur tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'Et en ce jour je me mettrai à détruire toutes les nations qui auront marché contre Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Alors je verserai sur la maison de David et sur les habitants de Jérusalem l\'esprit de grâce et de supplication, et ils regarderont vers moi, celui qu\'ils ont transpercé, et le pleureront comme on pleure un unique, et s\'affligeront à son sujet, comme on s\'afflige au sujet d\'un premier-né.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'En ce jour-là grand sera le deuil à Jérusalem, tel que fut le deuil à Hadadrimmon dans la vallée de Mégiddo.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Et tout le pays sera en deuil, chaque famille de son côté: la race de la maison de David de son côté, et leurs femmes de leur côté; la race de la maison de Nathan de son côté, et leurs femmes de leur côté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'la race de la maison de Lévi de son côté, et leurs femmes de leur côté; la race de Siméi de son côté, et leurs femmes de leur côté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'toutes les familles restées, chaque race de son côté, et leurs femmes de leur côté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'En ce jour-là il y aura une source ouverte pour la maison de David et pour les habitants de Jérusalem, pour le péché et la souillure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'Et en ce jour-là, dit l\'Éternel des armées, j\'exterminerai du pays les noms des idoles, pour que leur mémoire se perde, et je bannirai aussi du pays les prophètes et l\'esprit impur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Que si quelqu\'un prophétise encore, son père et sa mère, ses parents lui diront: « Tu ne dois pas vivre, car tu as proféré le mensonge au nom de l\'Éternel; » et son père et sa mère, ses parents, le transperceront lui prophétisant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'Et en ce jour-là les prophètes auront tous honte de leur vision eux prophétisant, et ils ne revêtiront plus le manteau velu pour tromper.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Et chacun d\'eux dira: Je ne suis point prophète, je suis laboureur, car quelqu\'un me vendit dès ma jeunesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Et si on lui dit: Qu\'est-ce donc que ces blessures que tu as aux mains? il dira: J\'ai reçu ces coups dans la maison de mes amants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Épée, réveille-toi! [fonds] sur mon pasteur et sur un homme qui est mon proche! dit l\'Éternel des armées; frappe le pasteur, et le troupeau se dispersera, mais je reporterai ma main sur les petits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Et il arrivera dans tout le pays, dit l\'Éternel, que les deux tiers en seront exterminés, périront, et que le tiers y survivra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Et je mettrai le tiers au feu et les purifierai, comme on purifie l\'argent, et les éprouverai, comme on éprouve l\'or. Et ce tiers invoquera mon nom, et moi je l\'exaucerai; je dirai: C\'est mon peuple; et ils diront: L\'Éternel est mon Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Voici, un jour arrive pour l\'Éternel, et tes dépouilles seront partagées dans ton sein;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'et je rassemblerai toutes les nations contre Jérusalem pour y porter la guerre, et la ville sera prise, et les maisons pillées, et les femmes déshonorées; et la moitié delà ville s\'en ira captive, mais le reste du peuple ne sera point exterminé de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Alors l\'Éternel s\'avancera, et livrera bataille à ces nations-là, comme à la journée où Il livra bataille le jour de la mêlée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Et en ce jour-là ses pieds poseront sur la montagne des Oliviers, située en face de Jérusalem à l\'orient; et la montagne des Oliviers se fendra par le milieu, de l\'orient à l\'occident, pour former une vallée très grande, et une moitié de la montagne reculera vers le nord, et une moitié vers le midi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Et vous fuirez par la vallée de mes montagnes, car la vallée des montagnes s\'étendra jusqu\'à Atsal, et vous fuirez comme vous avez fui devant le tremblement de terre, au temps de Hosias, roi de Juda. Et l\'Éternel, mon Dieu, viendra, et tous ses Saints avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'Et en ce jour-là il n\'y aura point de lumière, les splendeurs s\'éclipseront:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'et ce sera un seul jour; (l\'Éternel sait ce qu\'il sera) il ne fera ni jour ni nuit, mais au temps du soir la clarté paraîtra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Et en ce jour-là des eaux vives jailliront de Jérusalem, et une moitié ira à la mer orientale et une moitié à la mer occidentale, et cela été et hiver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Et l\'Éternel régnera sur tout le pays; en ce jour-là il n\'y aura qu\'un seul Éternel; et il n\'y aura que son nom seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Tout le pays sera transformé, assimilé à la plaine, de Géba à Rimmon au midi de Jérusalem, qui sera éminente et assise sur son sol, de la porte de Benjamin jusqu\'au lieu de la première porte, jusqu\'à la porte de l\'angle, et de la tour de Hananéel aux pressoirs du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'Et ils y habiteront, et il n\'y aura plus d\'interdit, et Jérusalem siégera en sécurité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Or, voici la plaie qu\'infligera l\'Éternel à tous les peuples qui auront marché contre Jérusalem: Il fera tomber en pourriture la chair de chacun tandis qu\'il est debout sur ses pieds, et leurs yeux tomberont en pourriture dans leurs cavités, et leur langue tombera en pourriture dans leur bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'Et en ce jour-là il y aura un grand trouble de par l\'Éternel parmi eux, l\'un saisira la main de l\'autre, et l\'un lèvera la main sur la main de l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Et Juda combattra aussi dans Jérusalem, et les richesses de toutes les nations d\'alentour, or et argent et vêtements en grande abondance, seront ramassées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Et pareille sera la plaie infligée aux chevaux, aux mulets, aux chameaux et aux ânes, et à tous les bestiaux qui seront dans ces camps, pareille a cette plaie-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Et tous ceux qui survivront, de toutes les nations qui auront marché contre Jérusalem, monteront chaque année pour adorer le Roi, l\'Éternel des armées, et célébrer la fête des Tabernacles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Et si des familles de la terre il en est qui ne montent pas à Jérusalem pour adorer le Roi, l\'Éternel des armées, sur elles la pluie ne tombera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'Et si la famille d\'Egypte ne monte pas et ne vient pas, [la pluie ne tombera pas] non plus sur elle, mais ce sera la plaie que l\'Éternel infligera aux nations qui ne monteront pas pour célébrer la fête des Tabernacles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Ce sera le péché de l\'Egypte et le péché de tous les peuples qui ne monteront pas pour célébrer la fête des Tabernacles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'En ce jour-là les clochettes des chevaux porteront: « Sainteté à l\'Éternel! » Et les chaudières dans la maison de l\'Éternel seront comme les vases des sacrifices devant l\'autel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Et toute chaudière en Jérusalem et en Juda sera « sainteté à l\'Éternel des armées, » et tous ceux qui sacrifieront, viendront et en prendront et y cuiront [les viandes], et il n\'y aura plus de Cananéen dans la maison de l\'Éternel des armées en ce jour-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Prononcé de la parole de l\'Éternel à Israël par Malachie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Je vous ai aimés, dit l\'Éternel. Et vous dites: « Où paraît ton amour pour nous? » Ésaü n\'est-il pas frère de Jacob? dit l\'Éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'cependant j\'ai aimé Jacob, et j\'ai haï Ésaü et changé ses monts en désert, et son héritage en demeures de solitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Qu\'Édom dise: Nous sommes détruits, mais nous relèverons les ruines! Ainsi dit l\'Éternel des armées: Qu\'ils bâtissent, je démolirai, et leur nom sera Région de l\'impiété, et Peuple livré au courroux de l\'Éternel pour l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Et vos yeux le verront et vous direz: Grand est l\'Éternel par delà les confins d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Un fils honore son père et un serviteur son seigneur. Or, si je suis père, où est l\'honneur qui me vient, et si je suis Seigneur, où est la crainte qu\'on a de moi? dit l\'Éternel des armées à vous, sacrificateurs, contempteurs de mon nom! Vous dites: « En quoi sommes-nous contempteurs de ton nom? » –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'En apportant sur mon autel un aliment profane. Et vous dites: « En quoi te profanons-nous? » – En disant: « La table de l\'Éternel est à mépriser! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Et quand vous apportez pour victime un animal aveugle, il n\'y a point de mal à cela! Et quand vous en apportez un boiteux ou malade, il n\'y a point de mal à cela! Offrez-le donc à votre gouverneur! vous agréera-t-il, ou aura-t-il égard à vous? dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Et puis implorez donc Dieu, pour qu\'il ait pitié de nous! Tels sont vos faits, et Il aurait égard à l\'un de vous dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Que n\'y a-t-il parmi vous quelqu\'un qui ferme les portes, pour que vous n\'allumiez plus le feu sur mon autel vainement! Je ne prends point plaisir à vous, dit l\'Éternel des armées, et n\'agrée aucune offrande de vos mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Car du levant au couchant mon nom est grand parmi les nations, et en tout lieu l\'encens est offert à mon nom, ainsi que des oblations pures; car grand est mon nom parmi les nations, dit l\'Éternel désarmées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Mais vous, vous le profanez, quand vous dites: La table de l\'Éternel est souillée, et quant à son produit, la chère en est méprisable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Et vous dites: Voici, comme elle nous fatigue! et vous la dédaignez, dit l\'Éternel des armées; et pourtant vous apportez de la rapine et des [victimes] boiteuses ou malades; telles sont les offrandes que vous apportez: les agréerai-je de vos mains? dit l\'Éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Maudit le fourbe qui ayant dans son troupeau un mâle, voue et sacrifie au Seigneur une femelle défectueuse! car je suis un grand Roi, dit l\'Éternel des armées, et mon nom est craint parmi les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'A présent donc, à vous cet ordre, sacrificateurs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Si vous n\'obéissez pas et n\'avez pas à cœur de donner gloire à mon nom, dit l\'Éternel des armées, j\'enverrai parmi vous la malédiction, et maudirai vos bénédictions; oui, je les maudirai, parce que vous ne l\'avez pas à cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Voici, j\'interdirai vos semences et vous jetterai du fumier au visage, le fumier de vos victimes solennelles dans lequel on vous poussera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Et vous saurez que je vous ai adressé cet ordre, afin que mon alliance avec Lévi subsistât, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Mon alliance avec lui fut vie et paix, et je les lui accordai pour qu\'il eût. la crainte; et il me craignit et à mon nom il trembla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'La loi de vérité fut dans sa bouche, et l\'iniquité ne s\'est point trouvée sur ses lèvres; en paix et en droiture il marcha avec moi, et en retira beaucoup du péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Car les lèvres du sacrificateur doivent garder la science, et c\'est à sa bouche qu\'on doit demander la loi, car il est le messager de l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Mais vous, vous vous êtes écartés de la voie, vous avez été par la loi même cause de la chute de plusieurs, et vous avez anéanti l\'alliance de Lévi, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'De même aussi moi je vous rendrai méprisables et abjects pour tout le peuple, parce que vous ne gardez pas mes voies et que vous faites acception des personnes devant la loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'N\'avons-nous pas tous un même père? un même Dieu ne nous a-t-Il pas créés? Pourquoi nous sommes-nous infidèles l\'un à l\'autre, afin de violer l\'alliance de nos pères?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Juda a été infidèle, et une abomination est commise en Israël et à Jérusalem; car Juda a profané ce qui est consacré à l\'Éternel, ce qu\'il aime, et il a épousé des filles de dieux étrangers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'A l\'homme qui le fait, l\'Éternel retranchera des tentes de Jacob et le guet vigilant et celui qui répond et celui qui offre des oblations à l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Et en second lieu, voici ce que vous faites: Vous couvrez de larmes l\'autel de l\'Éternel, de pleurs et de sanglots, tellement qu\'il n\'a plus égard aux sacrifices et ne reçoit plus de vos mains de dons qui lui plaisent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Et vous dites: Pourquoi? Parce que l\'Éternel intervint comme témoin entre toi et la femme de ta jeunesse à qui tu es infidèle et qui est ta compagne et ta femme d\'alliance. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, '« Mais un homme ne l\'a-t-il pas fait? Et cependant il a conservé sa vie. » – Et pourquoi cet homme unique l\'a-t-il fait? Il cherchait la postérité que Dieu [lui avait promise]. C\'est pourquoi, au nom de votre vie, prenez garde, et que nul ne soit infidèle à la femme de sa jeunesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Car je hais la répudiation, dit l\'Éternel, Dieu d\'Israël, et celui qui couvre d\'ignominie son vêtement, dit l\'Éternel des armées. Aussi, au nom de votre vie, prenez garde et ne soyez point infidèles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Vous fatiguez l\'Éternel par vos discours, et vous dites: « En quoi le fatiguons-nous? » En disant: Quiconque fait le mal, plaît à l\'Éternel, et c\'est à de tels hommes qu\'il prend plaisir; ou bien: Où est le Dieu de la justice?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Voici, j\'enverrai mon ange, et il préparera le chemin devant moi, et soudain arrivera dans son temple le Seigneur que vous cherchez et l\'ange de l\'alliance que vous désirez: le voici venir, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Mais qui soutiendra le jour de sa venue? et qui restera debout, quand il paraîtra? Car il est pareil au feu du fondeur et à la lessive des foulons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Et il sera assis fondant et purifiant l\'argent, et il purifiera les enfants de Lévi et les mettra au creuset comme l\'or et l\'argent, et ils appartiendront à l\'Éternel, lui apportant des offrandes avec justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Alors l\'offrande de Juda et de Jérusalem sera agréée de l\'Éternel, comme aux jours d\'autrefois et dans les années de jadis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Et je m\'approcherai de vous pour le jugement, et je viendrai promptement témoigner contré les enchanteurs et les adultères et les parjures, et contre ceux qui dépouillent le mercenaire de son salaire et la veuve et l\'orphelin et déboutent les étrangers et ne me craignent point, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Car je suis l\'Éternel, je ne change point, et vous, enfants de Jacob, vous ne périrez point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Dès les jours de vos pères vous vous êtes écartés de mes ordonnances et ne les avez point gardées: revenez à moi et je reviendrai à vous, dit l\'Éternel des armées. Et vous dites: « A quel égard reviendrons-nous? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Un homme peut-il donc être fourbe envers Dieu, que vous soyez fourbes envers moi? Et vous dites: « En quoi fûmes-nous fourbes envers toi? » Dans les dîmes et les oblations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'La malédiction vous est infligée, parce que vous fûtes fourbes envers moi, le peuple tout entier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Apportez toutes les dîmes dans le magasin, afin qu\'il y ait des vivres dans ma maison, et mettez-moi donc à l\'épreuve par là, dit l\'Éternel des armées: [vous verrez] si je n\'ouvre pas pour vous les écluses des Cieux, et ne répands pas sur vous la bénédiction au delà de vos besoins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Et je vous préserverai du dévoreur, afin qu\'il ne détruise pas le fruit du sol, et que dans les campagnes la vigne ne vous avorte pas, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'Et toutes les nations vous diront heureux, car vous serez un pays de délices, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Vos discours envers moi ont été audacieux, dit l\'Éternel. Et vous dites: Qu\'avons-nous concerté contre toi? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Vous avez dit: « Inutile de servir Dieu! et quel profit eûmes-nous d\'observer ses ordonnances et d\'aller menant deuil devant l\'Éternel des armées?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Et maintenant, nous proclamons heureux les orgueilleux; ceux qui pratiquent l\'impiété prospèrent; ils tentent Dieu, et échappent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Alors ceux qui craignent Dieu se sont concertés l\'un avec l\'autre, et l\'Éternel fut attentif et écouta, et un mémoire fut écrit devant lui pour ceux qui craignent l\'Éternel et pensent à son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Et ils seront à moi, dit l\'Éternel des armées, au jour que je prépare, ma propriété; et j\'userai envers eux delà clémence dont use un homme envers son fils qui le sert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Alors de nouveau vous verrez quelle différence il y a entre le juste et l\'impie, entre celui qui sert Dieu et celui qui ne le sert pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Car voici, le jour vient, brûlant comme la fournaise; alors tous les orgueilleux et tous ceux qui pratiquent l\'impiété, seront un chaume, et le jour qui arrive les embrasera, dit l\'Éternel des armées, qui ne leur laissera ni racine, ni rameau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Et pour vous qui craignez mon nom se lèvera le soleil de la justice qui a la guérison sous ses ailes; et vous sortirez libres et bondirez comme les veaux tenus à l\'étable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'Et vous foulerez les impies, car ils seront une cendre sous la plante de vos pieds, au jour que je prépare, dit l\'Éternel des armées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Souvenez-vous de la loi de Moïse, mon serviteur, que je lui prescrivis en Horeb pour tout Israël, des ordonnances et des statuts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Voici, je vous enverrai Élie, le prophète, avant que vienne le jour de l\'Éternel, jour grand et redoutable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'Et il ramènera le cœur des pères vers les enfants, et le cœur des enfants vers leurs pères, afin que je ne vienne pas, et ne frappe pas le pays d\'interdit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Table généalogique de Jésus-Christ, fils de David, fils d\'Abraham:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham engendra Isaac; Isaac engendra Jacob; Jacob engendra Juda et ses frères;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Juda engendra de Thamar Pharès et Zaré; Pharès engendra Esrom; Esrom engendra Aram;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Aram engendra Aminadab; Aminadab engendra Naasson; Naasson engendra Salmon;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Salmon engendra Boes de Rachab; Boes engendra Jobed de Ruth; Jobed engendra Jessé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Jessé engendra le roi David. David engendra Salomon de la femme d\'Urie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Salomon engendra Roboam; Roboam engendra Abia;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Abia engendra Asaph; Asaph engendra Josaphat; Josaphat engendra Joram; Joram engendra Ozias;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Ozias engendra Joatham; Joatham engendra Achaz; Achaz engendra Ézéchias;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Ézéchias engendra Manassé; Manassé engendra Amos; Amos engendra Josias;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Josias engendra Jéchonias et ses frères, lors de la déportation de Babylone.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Après la déportation de Babylone Jéchonias engendre Sélathiel; Sélathiel engendre Zorobabel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Zorobabel engendre Abioud; Abioud engendra Éliacim; Éliacim engendra Azor;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Azor engendra Sadoc; Sadoc engendra Achim; Achim engendra Élioud;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Élioud engendra Éléazar; Éléazar engendra Matthan; Matthan engendra Jacob;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Jacob engendra Joseph, le mari de Marie, de laquelle naquit Jésus qui est appelé Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Toutes les générations forment donc d\'Abraham jusques à David, quatorze générations, et de David jusques à la déportation de Babylone, quatorze générations, et de la déportation de Babylone jusques au Christ, quatorze générations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Or, voici quelle fut la naissance du Christ Jésus: Sa mère Marie ayant été fiancée à Joseph, avant qu\'ils eussent vécu ensemble elle se trouva enceinte par l\'action de l\'Esprit Saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Mais, comme Joseph son mari était un homme juste et qui ne voulait pas la déceler, il se résolut à la répudier secrètement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Or, après qu\'il eut formé ce projet, voici, un ange du Seigneur lui apparut en songe, disant: « Joseph, fils de David, ne crains point de garder Marie pour ta femme, car ce qui a été engendré en elle vient de l\'Esprit Saint;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'or elle mettra au monde un fils, et tu lui donneras le nom de Jésus, car c\'est lui qui sauvera son peuple de leurs péchés. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Or tout cela est advenu afin que fût accompli ce dont le Seigneur a parlé par l\'entremise du prophète lorsqu\'il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '« Voici, la vierge sera enceinte, et elle mettra au monde un fils, et ils lui donneront le nom d\' Emmanouel; » ce qui signifie, étant traduit: Avec nous Dieu. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Or Joseph s\'étant éveillé de son sommeil agit comme le lui avait prescrit l\'ange du Seigneur, et il garda sa femme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'et il ne la connaissait point jusqu\'à ce qu\'elle eût mis au monde un fils, et il lui donna le nom de Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Or, après que Jésus fut né à Bethléem de Judée, au temps du roi Hérode, voici, des mages d\'Orient arrivèrent à Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'disant: « Où est le roi des Juifs qui vient d\'être mis au monde? Car nous avons vu son astre en Orient, et nous sommes venus pour l\'adorer. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Mais le roi Hérode l\'ayant appris, fut troublé et tout Jérusalem avec lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'et, après avoir rassemblé tous les grands prêtres et les scribes du peuple, il s\'informait d\'eux où devait naître le Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Et ils lui dirent: « A Bethléem de Judée; c\'est ainsi en effet qu\'il a été écrit par l\'entremise du prophète:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'Et toi Bethléem, terre de Juda, tu n\'es certes point la moindre parmi les chefs de Juda, car c\'est de toi que sortira un souverain qui paîtra mon peuple d\'Israël. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Alors Hérode, ayant secrètement mandé les mages, s\'enquit avec soin auprès d\'eux du temps depuis lequel l\'astre se montrait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'et les envoyant à Bethléem, il dit: « Allez, et prenez d\'exactes informations sur le petit enfant; mais, quand vous l\'aurez découvert, faites-le-moi savoir, afin que moi aussi j\'aille l\'adorer. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Pour eux, après avoir ouï le roi, ils se mirent en route; et voici, l\'astre qu\'ils avaient vu en Orient les précédait, jusqu\'à ce qu\'il s\'arrêta dans sa marche au-dessus du lieu où était le petit enfant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Or à la vue de l\'astre ils furent remplis d\'une très grande joie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'et, étant entrés dans la maison, ils virent le petit enfant avec Marie sa mère, et s\'étant prosternés ils l\'adorèrent, et ayant ouvert leurs trésors ils lui offrirent en présent de l\'or, et de l\'encens et de la myrrhe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Et ayant été avertis dans un songe de ne point retourner vers Hérode, ils regagnèrent leur pays par un autre chemin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Or, après qu\'ils eurent regagné leur pays, voici, un ange du Seigneur apparut en songe à Joseph, disant: Éveille-toi, prends avec toi le petit enfant et sa mère, et fuis en Egypte, et demeures-y jusques à ce que je te le dise; car Hérode va se mettre en quête du petit enfant pour le faire périr. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Or, s\'étant éveillé, il prit avec lui le petit enfant et sa mère pendant la nuit, et il gagna l\'Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'et il y séjourna jusqu\'au trépas d\'Hérode; — afin que fût accompli ce dont le Seigneur a parlé par l\'entremise du prophète lorsqu\'il dit: « De l\'Egypte j\'ai rappelé Mon fils. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Alors Hérode, voyant qu\'il avait été joué par les mages, entra dans un grand courroux, et il envoya mettre à mort tous les enfants qui étaient à Bethléem et dans tout son territoire, âgés de deux ans et au-dessous, conformément à la date dont il s\'était enquis avec soin auprès des mages. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Alors fut accompli ce dont il a été parlé par l\'entremise de Jérémie le prophète, lorsqu\'il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '« Une voix a été entendue dans Rama, des pleurs et de nombreux gémissements; c\'est Rachel qui pleure ses enfants, et elle ne voulait pas être consolée, parce qu\'ils ne sont plus. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Or, après qu\'Hérode fut trépassé, voici, un ange du Seigneur apparaît en songe à Joseph en Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'disant: « Éveille-toi, prends avec toi le petit enfant et sa mère, et mets-toi en route pour le pays d\'Israël; car ceux qui en voulaient à la vie du petit enfant sont morts. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Or, s\'étant éveillé, il prit avec lui le petit enfant et sa mère, et il rentra dans le pays d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Mais, ayant appris qu\'Archélaüs régnait sur la Judée à la place de son père Hérode, il craignit de s\'y rendre, et ayant été averti dans un songe il gagna le territoire de la Galilée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'et, après y être arrivé, il s\'établit dans une ville appelée Nazaret; — afin que fût accompli ce qui a été dit par l\'entremise des prophètes: « Il sera appelé Nazoréen. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Or, en ce temps-là survient Jean le baptiste, prêchant dans le désert de Judée');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'en disant: « Repentez-vous, car le royaume des cieux s\'approche. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Il est, en effet, celui dont il a été parlé par l\'entremise d\'Ésaïe le prophète lorsqu\'il dit: « Voix d\'un crieur dans le désert: Préparez le chemin du Seigneur, redressez Ses sentiers. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Quant à Jean lui-même, il avait son vêtement fait de poils de chameau, et une ceinture de cuir autour de ses reins, tandis que sa nourriture consistait en sauterelles et en miel sauvage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Alors Jérusalem, ainsi que toute la Judée et toute la contrée voisine du Jourdain, se portait vers lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'et ils se faisaient baptiser par lui dans le fleuve du Jourdain, en confessant leurs péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Mais ayant vu plusieurs des pharisiens et des sadducéens qui venaient au baptême, il leur dit: « Engeance de vipères, qui vous a appris à fuir la colère à venir?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Produisez donc un fruit digne de la repentance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'et n\'imaginez pas de dire en vous-mêmes: Nous avons Abraham pour père! Car je vous déclare que Dieu peut, de ces pierres-ci, susciter des enfants à Abraham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Mais déjà la hache est mise à la racine des arbres; tout arbre donc qui ne produit pas de bon fruit doit être coupé et jeté au feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Pour moi, je vous baptise d\'eau, en vue de la repentance, mais celui qui vient après moi est plus puissant que moi, et je ne suis pas digne de porter ses sandales; c\'est lui qui vous baptisera d\'esprit saint et de feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Il tient son van dans sa main, et il nettoiera son aire, et il serrera son blé dans son grenier, mais il brûlera la paille dans un feu inextinguible. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Alors Jésus vient de Galilée vers le Jourdain auprès de Jean, pour se faire baptiser par lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'mais il l\'en empêchait, en disant: « C\'est moi qui ai besoin de me faire baptiser par toi, et c\'est toi qui viens à moi! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Mais Jésus lui répliqua: « Pour le moment laisse faire, car c\'est ainsi qu\'il nous sied d\'accomplir tout ce qui est juste. » Alors il le laisse faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Or, après avoir été baptisé, Jésus sortit aussitôt de l\'eau; et voici, les cieux s\'ouvrirent, et il vit l\'esprit de Dieu, descendant comme une colombe, venir sur lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'et voici, une voix sortant des cieux disait: « Celui-ci est Mon fils bien-aimé, dans lequel J\'ai pris plaisir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Alors Jésus fut emmené dans le désert par l\'Esprit pour être tenté par le diable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Et après qu\'il eut jeûné pendant quarante jours et quarante nuits, il finit par avoir faim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Et, s\'étant approché, le tentateur lui dit: « Si tu es fils de Dieu, dis que ces pierres-ci deviennent des pains. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Mais il répliqua: « Il est écrit: Ce n\'est pas de pain seulement que l\'homme vivra, mais de toute parole sortie de la bouche de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Alors le diable le transporte dans la ville sainte, et il le posa sur l\'aile du temple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'et il lui dit: « Si tu es fils de Dieu, jette-toi en bas; en effet, il est écrit: Car Il donnera pour toi des ordres à Ses anges, et ils te porteront sur leurs mains, de peur que tu ne heurtes ton pied contre une pierre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Jésus lui dit: « Il est aussi écrit: Tu ne tenteras point le Seigneur ton Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Le diable le transporte derechef sur une montagne fort élevée, et il lui montre tous les royaumes du monde et leur gloire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'et il lui dit: « Je te donnerai tout cela, si, te prosternant, tu m\'adores. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Alors Jésus lui dit: « Va-t-en, Satan, car il est écrit: C\'est le Seigneur ton Dieu que tu adoreras, et c\'est à Lui seul que tu rendras un culte. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Alors le diable le quitte, et voici, des anges s\'approchèrent, et ils le servaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Or, ayant appris que Jean avait été livré, il regagna la Galilée');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'et, ayant quitté Nazara, il vint s\'établir à Capharnaoum, qui est située au bord de la mer, sur les confins de Zabulon et de Nephthalim; —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'afin que fût accompli ce dont il a été parlé par l\'entremise d\'Ésaïe le prophète lorsqu\'il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '« Terre de Zabulon, et terre de Nephthalim, sur le chemin de la mer, au delà du Jourdain, dans la Galilée des Gentils!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'Le peuple qui était assis dans les ténèbres a vu une grande lumière, et pour ceux qui étaient assis dans le pays et l\'ombre de la mort, une lumière s\'est levée pour eux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'C\'est de ce moment que Jésus commença à prêcher, et à dire: « Repentez-vous, car le royaume des cieux s\'approche. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Or, en se promenant le long de la mer de Galilée, il vit deux frères, Simon appelé Pierre, et André son frère, qui jetaient un filet dans la mer, car ils étaient pêcheurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'et il leur dit: « Venez après moi, et je ferai de vous des pêcheurs d\'hommes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Et eux, ayant aussitôt quitté les filets, le suivirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Et ayant de là continué sa route, il vit deux autres frères, Jacques fils de Zébédée et Jean son frère, qui, dans leur barque avec Zébédée leur père, arrangeaient leurs filets, et il les appela.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Et eux, ayant aussitôt quitté la barque et leur père, le suivirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Et il parcourait toute la Galilée, enseignant dans leurs synagogues, et prêchant l\'évangile du royaume, et guérissant toute espèce de maladies et d\'infirmités parmi le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Et sa renommée se répandit dans toute la Syrie; et on lui amena tous les infirmes, atteints de diverses maladies et de diverses souffrances, démoniaques, et lunatiques, et paralytiques; et il les guérit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Et une foule nombreuse, venue de la Galilée, et de la Décapole, et de Jérusalem, et de Judée, et de par delà le Jourdain, le suivit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Or, lorsqu\'il vit cette foule, il monta sur la montagne, et, après qu\'il se fut assis, ses disciples s\'approchèrent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'et ayant ouvert la bouche, il les instruisait en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, '« Heureux les pauvres d\'esprit, car c\'est à eux qu\'appartient le royaume des cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Heureux les affligés, car c\'est eux qui seront consolés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Heureux ceux qui sont doux, car c\'est eux qui hériteront la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, '« Heureux ceux qui sont affamés et altérés de la justice, car c\'est eux qui seront rassasiés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Heureux les miséricordieux, car c\'est à eux qu\'il sera fait miséricorde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Heureux ceux qui sont purs de cœur, car c\'est eux qui verront Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Heureux ceux qui procurent la paix, car c\'est eux qui seront appelés fils de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Heureux ceux qui sont persécutés à cause de la justice, car c\'est à eux qu\'appartient le royaume des cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Vous êtes heureux quand on vous aura injuriés et persécutés, et qu\'on aura dit faussement toute sorte de mal contre vous, à cause de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Réjouissez-vous et tressaillez de joie, parce que votre récompense est considérable dans les cieux; car c\'est ainsi qu\'on a persécuté les prophètes qui ont vécu avant vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, '« Vous êtes le sel de la terre; mais si le sel s\'est affadi, avec quoi le salera-t-on? Il ne sert plus à rien, sinon, après avoir été jeté dehors, qu\'à être foulé aux pieds par les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Vous êtes la lumière du monde: une ville située sur une montagne ne peut être cachée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'on n\'allume pas non plus une lampe pour la placer sous le boisseau, mais sur son support, et elle brille pour tous ceux qui sont dans la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Que de même votre lumière brille devant les hommes, afin qu\'ils voient vos bonnes œuvres, et qu\'ils glorifient votre Père qui est dans les cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, '« Ne pensez pas que je sois venu pour abolir la loi ou les prophètes: je ne suis pas venu pour abolir, mais pour accomplir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'car en vérité je vous le déclare, jusqu\'à ce que le ciel et la terre aient disparu, un seul i ou un seul jambage ne disparaîtra point de la loi avant que tout n\'ait été réalisé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'En conséquence, celui qui aura enfreint un seul de ces moindres commandements et enseigné aux hommes à faire de même, sera renommé l\'un des moindres dans le royaume des cieux; mais celui qui les aura observés et enseignés, celui-là sera renommé grand dans le royaume des cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Car je vous déclare que si votre justice n\'a pas surpassé de beaucoup celle des scribes et des pharisiens, vous n\'entrerez certainement pas dans le royaume des cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, '« Vous avez appris qu\'il a été dit par ceux d\'autrefois: « Tu ne tueras point; mais celui qui aura tué sera justiciable du tribunal. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Eh bien, moi, je vous déclare que quiconque s\'irrite contre son frère, sera justiciable du tribunal; et que celui qui aura dit à son frère: Raca, sera justiciable du sanhédrin; et que celui qui lui aura dit: Insensé, sera justicié dans la géhénne du feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, '« Si donc tu viens présenter ton offrande à l\'autel, et que là tu te souviennes que ton frère a quelque grief contre toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'laisse là ton offrande devant l\'autel, et va-t-en d\'abord te réconcilier avec ton frère, et alors reviens présenter ton offrande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Mets-toi promptement d\'accord avec ton adversaire pendant que tu es en chemin avec lui, de peur que ton adversaire ne te livre au juge, et le juge à l\'huissier, et que tu ne sois jeté en prison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'En vérité je te déclare, tu ne sortiras certainement pas de là, que tu n\'aies payé le dernier quadrant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, '« Vous avez appris qu\'il a été dit: « Tu ne commettras point d\'adultère. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Eh bien, moi, je vous déclare que quiconque regarde une femme pour la convoiter a déjà commis un adultère avec elle en son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Mais si ton œil droit te fait trébucher, arrache-le et jette-le loin de toi; car il est de ton intérêt qu\'un seul de tes membres périsse et que ton corps entier ne soit pas jeté dans la géhenne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Et si ta main droite te fait trébucher, coupe-la et jette-la loin de toi; car il est de ton intérêt qu\'un seul de tes membres périsse et que ton corps entier n\'aille pas dans la géhenne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Il a encore été dit: « Que celui qui aura répudié sa femme lui remette un acte de divorce. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Eh bien, moi, je vous déclare que quiconque répudie sa femme, sauf pour cause d\'impudicité, la pousse à commettre un adultère, et que celui qui aura épousé une femme répudiée commet un adultère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, '« Vous avez encore appris qu\'il a été dit par ceux d\'autrefois: « Tu ne te parjureras point, mais tu t\'acquitteras envers le Seigneur de tes serments. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Eh bien, moi, je vous dis de ne point jurer du tout, ni par le ciel parce que c\'est le trône de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'ni par la terre parce que c\'est le marchepied de Ses pieds, ni par Jérusalem parce que c\'est la ville du Grand Roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Tu ne jureras pas non plus sur ta tête, car tu ne peux rendre blanc ou noir un seul cheveu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Mais votre parole sera: oui, oui! non, non! Ce qu\'on y ajoute vient du malin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, '« Vous avez appris qu\'il a été dit: « œil pour œil et dent pour dent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Eh bien, moi, je vous dis de ne point résister au méchant; mais quiconque te soufflette sur la joue droite, présente-lui aussi l\'autre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'à celui qui veut t\'intenter un procès et prendre ta tunique, abandonne-lui aussi le manteau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'et quiconque te mettra en réquisition pour un mille, fais-en deux avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Donne à qui te demande, et ne repousse pas celui qui veut emprunter de toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, '« Vous avez appris qu\'il a été dit: « Tu aimeras ton prochain, et tu haïras ton ennemi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Eh bien, moi, je vous dis: aimez vos ennemis et priez pour vos persécuteurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'afin que vous soyez fils de votre Père qui est dans les cieux, car Il fait lever Son soleil sur les méchants et sur les bons, et Il fait pleuvoir sur les justes et sur les injustes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'En effet, si vous aimez ceux qui vous aiment, quelle récompense en avez-vous? Est-ce que les publicains aussi ne font pas la même chose?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Et si vous ne saluez que vos frères, que faites-vous d\'extraordinaire? Est-ce que les païens aussi ne font pas la même chose?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Pour vous donc, vous serez parfaits comme votre Père céleste est parfait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, '« Prenez garde à ne pas exercer votre justice devant les hommes afin d\'être vus par eux; autrement il n\'y a pas pour vous de récompense auprès de votre Père qui est dans les cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Ainsi donc quand tu feras l\'aumône ne fais pas sonner la trompette devant toi, comme font les hypocrites dans les synagogues et dans les rues, afin d\'être glorifiés par les hommes. En vérité je vous le déclare, ils y trouvent toute leur récompense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Mais toi, lorsque tu fais l\'aumône, que ta gauche ne sache pas ce que fait ta droite,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'afin que ton aumône se fasse dans le secret, et ton Père, qui voit dans le secret, te rétribuera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Et quand vous priez, vous ne serez pas comme les hypocrites, car ils aiment à prier en se tenant debout dans les synagogues et dans les angles des grandes rues, afin de se faire voir aux hommes. En vérité, je vous le déclare, ils y trouvent toute leur récompense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Mais toi, quand tu prieras, entre dans ta chambre, et après avoir fermé ta porte, prie ton Père qui est présent en secret, et ton Père, qui voit dans le secret, te rétribuera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Or, quand vous priez, ne bavardez pas comme les hypocrites, car ils s\'imaginent que grâce à leurs redites ils seront exaucés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Ne les imitez donc pas, car Dieu votre Père sait ce dont vous avez besoin avant que vous le Lui demandiez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Pour vous, priez donc ainsi: Notre Père qui es dans les cieux, que Ton nom soit sanctifié;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'que Ton royaume vienne; que Ta volonté se fasse aussi sur la terre comme dans le ciel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'donne-nous aujourd\'hui le pain de notre subsistance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'et remets-nous nos dettes, comme nous aussi nous les avons remises à nos débiteurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'et ne nous expose pas à la tentation, mais délivre-nous du malin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'En effet, si vous pardonnez aux hommes leurs fautes, votre Père céleste vous pardonnera aussi à vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Mais si vous ne pardonnez pas aux hommes leurs fautes, votre Père ne pardonnera pas non plus vos propres fautes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Or, quand vous jeûnez, ne prenez pas, comme les hypocrites, un air sombre; car ils altèrent leur visage afin de faire voir aux hommes qu\'ils jeûnent. En vérité, je vous le déclare, ils y trouvent toute leur récompense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Mais toi, lorsque tu jeûnes, parfume ta tête et lave ton visage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'afin de ne pas faire voir aux hommes que tu jeûnes, mais à ton Père qui est présent en secret, et ton Père, qui voit dans le secret, te rétribuera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, '« Ne vous amassez pas des trésors sur la terre, où la teigne et la vermoulure détruisent, et où les voleurs font effraction et dérobent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'mais amassez-vous des trésors dans le ciel, ou ni la teigne ni la vermoulure ne détruisent, et où les voleurs ne font effraction ni ne dérobent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'car là où est ton trésor, là sera ton cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, '« Ton œil est la lampe du corps; si donc ton œil est sain, ton corps entier sera illuminé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'mais si ton œil est en mauvais état, ton corps entier sera ténébreux. Si donc la lumière qui est en toi est ténèbres, les ténèbres quelles sont-elles?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, '« Nul ne peut servir deux maîtres; car, ou bien il haïra l\'un et aimera l\'autre, ou bien il s\'attachera à l\'un et méprisera l\'autre; vous ne pouvez servir Dieu et Mamôna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'C\'est pourquoi je vous le déclare: ne vous inquiétez point pour votre vie de ce que vous mangerez ou de ce que vous boirez, ni pour votre corps de quoi vous serez vêtus. Est-ce que la vie n\'est pas plus que la nourriture et le corps plus que le vêtement?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Regardez les oiseaux du ciel: car ils ne sèment, ni ne moissonnent, ni ne serrent dans des greniers, et votre Père céleste les nourrit. Est-ce que vous, vous ne valez pas bien plus qu\'eux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Mais lequel d\'entre vous peut par ses inquiétudes ajouter à sa taille une seule coudée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Et quant au vêtement, pourquoi vous en inquiétez-vous? Observez les lis de la campagne: comment croissent-ils? Ils ne travaillent ni ne filent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'cependant je vous déclare que même Salomon dans toute sa gloire ne se vêtait pas comme l\'un d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Or, si Dieu revêt ainsi l\'herbe de la campagne qui vit aujourd\'hui et qui demain est jetée dans un four, ne le fera-t-Il pas à bien plus forte raison pour vous, gens de peu de foi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Ne dites donc pas dans votre inquiétude: Que mangerons-nous, ou que boirons-nous, ou de quoi nous vêtirons-nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Car ce sont toutes ces choses-là que recherchent les gentils; en effet votre Père céleste sait que vous avez besoin de tout cela.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Mais cherchez premièrement la justice et Son royaume, et toutes ces choses-là vous seront données par surcroît.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Ne vous inquiétez donc pas du lendemain; car le lendemain s\'inquiétera de lui-même; au jour suffit sa peine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, '« Ne jugez point, afin que vous ne soyez point jugés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'car par le jugement que vous portez vous serez jugés, et avec la mesure dont vous mesurez, il vous sera mesuré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Mais pourquoi regardes-tu le fétu qui est dans l\'œil de ton frère, tandis que tu ne t\'aperçois pas de la poutre qui est dans ton œil?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Ou bien comment diras-tu à ton frère: « Permets que j\'ôte le fétu de ton œil, » et voici, la poutre est dans le tien?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Hypocrite, ôte premièrement de ton œil la poutre, et tu verras alors à ôter le fétu de l\'œil de ton frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, '« Ne donnez pas ce qui est saint aux chiens, et ne jetez pas non plus vos perles devant les pourceaux, de peur qu\'ils ne les foulent avec leurs pieds et que, se retournant, ils ne vous déchirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, '« Demandez, et il vous sera donné; cherchez, et vous trouverez; heurtez, et l\'on vous ouvrira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Car quiconque demande reçoit; et celui qui cherche trouve, et à celui qui heurte on ouvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Ou bien quel est l\'homme d\'entre vous, auquel son fils demandera du pain, et qui lui donnera une pierre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Ou bien encore, il lui demandera un poisson, est-ce qu\'il lui donnera un serpent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Si donc vous, tout méchants que vous êtes, vous savez donner de bons présents à vos enfants, à combien plus forte raison votre Père qui est dans les cieux donnera-t-Il des biens à ceux qui les Lui demandent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Ainsi donc, tout ce que vous voulez que les hommes fassent pour vous, faites-le pareillement vous aussi pour eux, car c\'est là la loi et les prophètes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, '« Entrez par la porte étroite; car large est la porte, et spacieux le chemin qui mène à la perdition, et nombreux sont ceux qui entrent par là,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'tandis que la porte est étroite et le chemin resserré qui mène à la vie, et peu nombreux sont ceux qui le trouvent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Soyez en garde contre les faux prophètes qui viennent à vous sous des peaux de brebis, tandis qu\'ils sont au dedans des loups rapaces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Vous les reconnaîtrez à leurs fruits: Est-ce que l\'on récolte des raisins sur des épines, ou des figues sur des chardons?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Ainsi tout bon arbre produit de bons fruits, mais l\'arbre pourri produit de mauvais fruits;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'un bon arbre ne peut pas porter de mauvais fruits, ni un arbre pourri produire de bons fruits;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'tout arbre qui ne produit pas de bon fruit est coupé, puis il est jeté dans le feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Par conséquent, vous les reconnaîtrez à leurs fruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Ce n\'est pas quiconque me dit: « Seigneur, Seigneur! » qui entrera dans le royaume des cieux, mais celui qui fait la volonté, de mon Père qui est dans les cieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Plusieurs me diront en ce jour-là: « Seigneur, Seigneur, n\'est-ce pas en ton nom que nous avons prophétisé, et en ton nom que nous avons chassé des démons, et en ton nom que nous avons fait plusieurs miracles? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Et alors je leur ferai cette déclaration: Je ne vous ai jamais connus, éloignez-vous de moi, vous qui commettez l\'iniquité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Ainsi donc, quiconque entend ces miennes paroles et les pratique sera semblable à un homme prudent qui a bâti sa maison sur le roc;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'et la pluie est tombée, et les fleuves sont venus, et les vents ont soufflé et se sont déchaînés contre cette maison; et elle n\'est pas tombée, car elle avait été fondée sur le roc.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Et quiconque entend ces miennes paroles et ne les pratique pas sera semblable à un homme étourdi qui a bâti sa maison sur le sable;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'et la pluie est tombée, et les fleuves sont venus, et les vents ont soufflé et ont battu cette maison, et elle est tombée, et sa chute a été grande. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Et il advint, lorsque Jésus eut terminé ces discours, que la foule était stupéfaite de son enseignement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'car il les enseignait comme ayant autorité, et non pas comme leurs scribes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Or, lorsqu\'il fut descendu de la montagne, une foule nombreuse le suivit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'et voici, un lépreux s\'étant approché l\'adorait en disant: « Seigneur, si tu le veux tu peux me guérir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Et ayant étendu la main, il le toucha en disant: « Je le veux, sois guéri. » Et aussitôt sa lèpre fut guérie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Et Jésus lui dit: « Garde-toi d\'en parler à personne; mais va, montre-toi au prêtre et présente l\'offrande qu\'a prescrite Moïse, pour leur servir d\'attestation. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Or, lorsqu\'il fut entré à Capharnaoum, un centurion s\'approcha de lui, en le sollicitant');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'et en disant: « Seigneur, mon serviteur est au lit à la maison, atteint de paralysie et cruellement souffrant. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Il lui dit: « J\'irai le guérir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Mais le centurion répliqua: « Seigneur, je ne suis pas digne que tu entres sous mon toit; mais dis seulement un mot, et mon serviteur sera guéri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Car moi aussi je suis un homme placé sous autorité, ayant des soldats sous mes ordres, et je dis à celui-ci: « Va, » et il va; et à un autre: « Viens » et il vient; et à mon esclave: « Fais cela » et il le fait. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Or, en l\'entendant, Jésus fut émerveillé, et il dit à ceux qui suivaient: « En vérité je vous le déclare, je n\'ai trouvé chez personne en Israël une si grande foi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'mais je vous déclare que plusieurs viendront de l\'orient et du couchant et s\'attableront avec Abraham et Isaac et Jacob dans le royaume des cieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'tandis que les fils du royaume seront jetés dans les ténèbres extérieures; là sera le pleur et le grincement de dents. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Et Jésus dit au centurion: « Va, qu\'il te soit fait comme tu as cru. » Et en ce moment-là le serviteur fut guéri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Et Jésus étant entré dans la maison de Pierre, vit sa belle-mère qui était au lit et avait la fièvre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'et il toucha sa main et la fièvre la quitta, et elle se leva, et elle le servait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Mais quand le soir fut venu on lui amena plusieurs démoniaques, et d\'un mot il chassa les esprits et il guérit tous les malades; —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'afin que fût accompli ce dont il a été parlé par l\'entremise d\'Ésaïe le prophète lorsqu\'il dit: « C\'est lui qui a pris nos infirmités et qui a porté nos maladies. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Or, Jésus se voyant entouré de la foule ordonna de passer sur l\'autre rive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Et un scribe s\'étant approché lui dit: « Maître, je te suivrai où que ce soit que tu ailles. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Et Jésus lui dit: « Les renards ont des terriers et les oiseaux du ciel des abris; mais le Fils de l\'homme n\'a pas où reposer sa tête. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Mais un autre des disciples lui dit: « Seigneur, permets-moi de m\'en aller d\'abord, et d\'enterrer mon père. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Mais Jésus lui dit: « Suis-moi, et laisse les morts enterrer leurs morts. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Et lorsqu\'il fut monté sur une barque, ses disciples le suivirent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'et voici une grande tourmente s\'éleva sur la mer, en sorte que la barque était couverte par les vagues; mais lui s\'était endormi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Et s\'étant approchés ils l\'éveillèrent en disant: « Seigneur, au secours, nous sommes perdus. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Et il leur dit: « Pourquoi êtes-vous effrayés, gens de peu de foi? » Alors s\'étant levé, il gourmanda les vents et la mer, et il se fit un grand calme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Or les gens émerveillés disaient: « Quel est celui-ci, que même les vents et la mer lui obéissent? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Et quand il fut arrivé sur l\'autre rive, dans le pays des Gadaréniens, vinrent à sa rencontre deux démoniaques sortis des tombeaux, et qui étaient si furieux que personne ne pouvait passer par ce chemin-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Et voici, ils s\'écrièrent: « Qu\'y a-t-il de commun entre nous et toi, fils de Dieu? Es-tu venu ici avant le temps pour nous torturer? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Or, loin d\'eux paissait un troupeau de nombreux pourceaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Mais les démons le sollicitaient en disant: « Si tu nous chasses, envoie-nous dans le troupeau des pourceaux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Et il leur dit: « Allez! » Or étant sortis ils s\'en allèrent dans les pourceaux, et voici, tout le troupeau se rua en bas du précipice dans la mer, et ils périrent dans les eaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Mais les pâtres s\'enfuirent, et s\'en étant allés à la ville ils rapportèrent tout ce qui s\'était passé et ce qui était advenu aux démoniaques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Et voici, toute la ville sortit à la rencontre de Jésus, et l\'ayant vu ils le sollicitèrent de s\'éloigner de leur territoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Et étant monté dans une barque, il passa sur l\'autre rive, et il vint dans sa propre ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Et voici, on lui amenait un paralytique couché sur un lit, et Jésus ayant vu leur foi dit au paralytique: « Courage! mon enfant, tes péchés sont pardonnes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Et voici, quelques-uns des scribes dirent en eux-mêmes: « Cet homme blasphème. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Et Jésus connaissant leurs pensées dit: « Pourquoi avez-vous de mauvaises pensées dans vos cœurs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Car lequel est le plus facile, de dire: Tes péchés sont pardonnés; ou de dire: Lève-toi et marche?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Or, pour que vous sachiez que le fils de l\'homme a sur la terre l\'autorité de pardonner les péchés.... Lève-toi, » dit-il alors au paralytique, « prends ton lit et va-t-en dans ta maison. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Et s\'étant levé, il s\'en alla dans sa maison;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'ce que la foule ayant vu elle fut effrayée, et elle glorifia Dieu qui avait donné une telle autorité aux hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Et s\'éloignant de là Jésus vit un homme assis au bureau des péages, appelé Matthieu, et il lui dit: « Suis-moi! » Et s\'étant levé il le suivit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Et il advint, comme il était à table dans la maison, que, voici, beaucoup de publicains et de pécheurs survinrent, qui s\'attablaient avec Jésus et ses disciples;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'ce que les pharisiens ayant vu, ils disaient à ses disciples: « Pourquoi est-ce avec les publicains et les pécheurs, que mange votre maître? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Ce que lui ayant ouï, il dit: « Ce ne sont pas les valides qui ont besoin du médecin, mais les mal portants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Mais allez apprendre ce que signifie: Je veux la miséricorde et non le sacrifice; car je ne suis pas venu appeler des justes, mais des pécheurs. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Alors les disciples de Jean s\'approchent de lui, en disant: « Pourquoi nous et les pharisiens jeûnons-nous, tandis que tes disciples ne jeûnent point? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Et Jésus leur dit: « Est-ce que les fils de la chambre nuptiale peuvent être dans le deuil tant que l\'époux est avec eux? Mais des jours viendront où l\'époux leur sera enlevé, et alors ils jeûneront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Personne ne met une pièce d\'étoffe écrue à un vieil habit, car ce rapiécetage enlève une partie de l\'habit, et il en résulte une déchirure pire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'On ne met pas non plus du vin nouveau dans des outres vieilles, autrement les outres se rompent, et le vin se répand, et les outres sont perdues; mais on met du vin nouveau dans des outres neuves, et ils se conservent réciproquement. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Pendant qu\'il leur parlait ainsi, voici, un chef s\'étant approché l\'adorait, en disant: « Ma fille vient de trépasser, mais viens poser ta main sur elle, et elle vivra. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Et Jésus s\'étant levé le suivit, ainsi que ses disciples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Et voici, une femme, atteinte d\'une perte de sang depuis douze ans, s\'étant approchée par derrière toucha la frange de son manteau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'car elle disait en elle-même: « Si seulement je touche son manteau, je serai guérie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Mais Jésus s\'étant retourné et l\'ayant vue, dit: « Courage! ma fille, ta foi t\'a guérie. » Et dès ce moment-là cette femme fut guérie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Et Jésus étant arrivé dans la maison du chef, et ayant vu les joueurs de flûte et la foule bruyante, disait:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, '« Retirez-vous, car la petite fille n\'est pas morte, mais elle dort. » Et ils se moquaient de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Mais, lorsque la foule eut été chassée, il entra, prit sa main, et la petite fille se leva.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Et cette nouvelle se répandit dans toute cette contrée-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Et comme Jésus s\'éloignait de là, deux aveugles le suivirent, qui s\'écriaient: « Aie pitié de nous, fils de David! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Et lorsqu\'il fut arrivé dans la maison, les aveugles s\'approchèrent de lui, et Jésus leur dit: « Croyez-vous que je puisse faire cela? » Ils lui disent: « Oui, Seigneur! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Alors il toucha leurs yeux, en disant: « Qu\'il vous soit fait selon votre foi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Et leurs yeux furent ouverts, et Jésus les tança vertement en disant: « Prenez garde que personne ne le sache. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Mais, après qu\'ils furent sortis, ils répandirent sa renommée dans toute cette contrée-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Or, comme ils sortaient, voici, on lui amena un démoniaque muet;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'et le démon ayant été chassé, le muet parla, et la foule étonnée disait: « Jamais chose semblable ne s\'est vue en Israël. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Mais les pharisiens disaient: « C\'est par le chef des démons qu\'il chasse les démons. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Et Jésus parcourait toutes les villes et les villages, enseignant dans leurs synagogues, et prêchant l\'évangile du royaume, et guérissant toute espèce de maladies et d\'infirmités.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Or, en voyant la foule, il fut ému de compassion envers elle, parce qu\'elle était lasse et abattue, comme des brebis qui n\'ont pas de berger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Alors il dit à ses disciples: « La moisson est considérable, il est vrai, mais les ouvriers sont en petit nombre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'priez donc le maître de la moisson, afin qu\'il envoie des ouvriers dans Sa moisson. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Et ayant appelé à lui ses douze disciples, il leur donna autorité sur les esprits impurs, de manière à les chasser et à guérir toute espèce de maladies et d\'infirmités.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Or, voici les noms des douze apôtres: le premier est Simon appelé Pierre, et André son frère; et Jacques fils de Zébédée et Jean son frère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Philippe et Barthélémy; Thomas et Matthieu le publicain; Jacques fils d\'Alphée et Thaddée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon le Cananéen et Judas l\'Iscariote, celui-là même qui le livra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Ce sont ces douze que Jésus envoya après leur avoir donné ses ordres, en disant: « N\'allez pas du côté des gentils, et n\'entrez pas dans une ville de Samaritains;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'mais dirigez-vous plutôt vers les brebis perdues de la maison d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Or, une fois en route, prêchez en disant: Le royaume des cieux s\'approche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Guérissez les malades, ressuscitez les morts, guérissez les lépreux, chassez les démons. C\'est gratuitement que vous avez reçu, donnez gratuitement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Ne prenez ni or, ni argent, ni cuivre dans vos ceintures,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'ni besace pour le chemin, ni deux tuniques, ni sandales, ni bâton; car l\'ouvrier mérite sa nourriture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Mais dans quelque ville ou village que vous entriez, enquérez-vous qui il s\'y trouve de digne, et demeurez là jusques à ce que vous partiez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Or, en entrant dans la maison saluez-la,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'et si la maison en est digne, que votre paix vienne sur elle; mais si elle n\'en est pas digne, que votre paix retourne à vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Et celui qui ne vous aura pas reçu et n\'aura pas écouté vos paroles, sortez de cette maison ou de cette ville-là et secouez la poussière de vos pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'En vérité je vous le déclare: le sort du pays de Sodome et de Gomorrhe sera, au jour du jugement, plus supportable que le sort de cette ville-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Voici, je vous envoie comme des brebis parmi des loups. Devenez donc prudents comme les serpents et purs comme les colombes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'mais soyez en garde contre les hommes; car ils vous livreront aux tribunaux et ils vous fustigeront dans leurs synagogues;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'et même vous serez conduits devant des gouverneurs et devant des rois à cause de moi, pour servir de témoignage à eux et aux gentils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Mais quand ils vous auront livrés, ne vous inquiétez ni de la manière ni des choses dont vous devrez parler; car à cette heure-là ce que vous aurez à dire vous sera donné;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'en effet, ce n\'est pas vous qui parlez, mais l\'esprit de votre Père qui parle en vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Or un frère livrera son frère à la mort, et un père son enfant, et des enfants se soulèveront contre leurs parents et les feront mourir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'et vous serez haïs de tous à cause de mon nom. Mais celui qui aura persévéré jusqu\'à la fin, celui-là sera sauvé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Or, quand ils vous persécuteront dans cette ville-ci, fuyez dans la suivante. Car, en vérité je vous le déclare: Vous n\'en n\'aurez pas fini avec les villes d\'Israël jusques à ce que le fils de l\'homme soit venu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Un disciple n\'est pas au-dessus de son maître, ni un esclave au-dessus de son seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'il suffit au disciple qu\'il devienne comme son maître, et l\'esclave comme son seigneur. S\'ils ont surnommé Béézéboul le chef de famille, à combien plus forte raison les membres de sa famille?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Ne les craignez donc pas; car rien n\'est couvert qui ne doive être révélé, ni caché qui ne doive être connu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'ce que je vous dis dans les ténèbres, dites-le en pleine lumière, et ce que vous entendez à l\'oreille, prêchez-le sur les toits;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'et ne craignez rien de ceux qui tuent le corps, mais qui ne peuvent tuer l\'âme; mais craignez plutôt Celui qui peut faire périr dans la géhenne et l\'âme et le corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Est-ce qu\'on ne vend pas deux passereaux pour un as? Eh bien, un seul d\'entre eux ne tombera pas à terre sans que votre Père le veuille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Mais pour vous, les cheveux même de votre tête sont tous comptés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Ne craignez donc point; vous valez mieux que beaucoup de passereaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Ainsi donc quiconque se déclarera pour moi devant les hommes, moi aussi je me déclarerai pour lui devant mon Père qui est dans les cieux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'mais quiconque m\'aura renié devant les hommes, moi aussi je le renierai devant mon Père qui est dans les cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Ne pensez pas que je sois venu apporter la paix sur la terre, je ne suis pas venu apporter la paix, mais l\'épée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'car je suis venu désunir un homme d\'avec son père, et une fille d\'avec sa mère, et une bru d\'avec sa belle-mère,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'et l\'homme aura pour ennemis les membres de sa famille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Celui qui aime son père ou sa mère plus que moi n\'est pas digne de moi; et celui qui aime son fils ou sa fille plus que moi n\'est pas digne de moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'et celui qui ne prend pas sa croix et ne me suit pas n\'est pas digne de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Celui qui aura trouvé sa vie la perdra, et celui qui aura perdu sa vie à cause de moi la trouvera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Celui qui vous reçoit me reçoit, et celui qui me reçoit reçoit Celui qui m\'a envoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Celui qui reçoit un prophète à titre de prophète recevra une récompense de prophète, et celui qui reçoit un juste à titre de juste recevra une récompense de juste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Et celui qui aura donné à boire à l\'un de ces petits un seul verre d\'eau froide à titre de disciple, en vérité je vous le déclare, il ne perdra certainement pas sa récompense. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Et il advint, quand Jésus eut achevé de donner ses ordres à ses douze disciples, qu\'il partit de là pour enseigner et prêcher dans leurs villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Or, Jean, ayant ouï parler dans la prison des œuvres de Christ, députa ses disciples');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'pour lui dire: « Es-tu celui qui doit venir, ou bien avons-nous à en attendre un autre? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Et Jésus leur répliqua: « Allez rapporter à Jean ce que vous entendez et ce que vous voyez:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'des aveugles recouvrent la vue, et des boiteux marchent; des lépreux sont guéris, et des sourds entendent, et des morts ressuscitent, et une bonne nouvelle est annoncée aux pauvres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'et il est heureux celui qui n\'aura pas trébuché à propos de moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Or, comme ils se mettaient en route, Jésus se mit à dire à la foule, au sujet de Jean: « Qu\'êtes-vous allés contempler au désert? Un roseau agité par le vent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Mais qu\'êtes-vous allés voir? Un homme vêtu avec luxe? Voici, ceux qui portent les vêtements de luxe habitent dans les demeures des rois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Mais pourquoi y êtes-vous allés? Pour voir un prophète? Oui, je vous le déclare, et bien plus qu\'un prophète;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'c\'est celui dont il est écrit: « Voici, J\'envoie Mon messager devant toi, lequel frayera ton chemin devant toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'En vérité je vous le déclare, il ne s\'est élevé parmi les enfants des femmes personne qui fût plus grand que Jean le baptiste; cependant le moindre dans le royaume des cieux est plus grand que lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Or, depuis le temps de Jean le baptiste jusques à aujourd\'hui le royaume des cieux est pris par violence et ce sont des violents qui s\'en emparent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'car tous les prophètes et la loi ont prophétisé jusques à Jean;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'et, si vous voulez l\'apprendre, c\'est lui qui est l\'Élie qui doit venir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Que celui qui a des oreilles entende.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Mais à qui comparerai-je cette génération? Elle est semblable à de petits enfants assis dans les places publiques, qui, apostrophant les autres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'disent: « Nous vous avons joué de la flûte et vous n\'avez pas dansé; nous avons chanté des complaintes et vous n\'avez donné nul signe de tristesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'En effet, Jean est venu, qui ne mangeait ni ne buvait, et ils disent: il a un démon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Le fils de l\'homme est venu, qui mange et boit, et ils disent: Voici un glouton et un ivrogne, un ami des publicains et des pécheurs. Eh bien! la sagesse a été justifiée par ses propres œuvres! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Alors il se mit à censurer les villes où avaient été faits la plupart de ses miracles, de ce qu\'elles ne s\'étaient pas repenties:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, '« Malheur à toi, Chorazin! malheur à toi Bethsaïdan! Car si c\'était dans Tyr et dans Sidon qu\'eussent été faits les miracles qui ont été faits parmi vous, dès longtemps elles se seraient repenties en prenant le sac et la cendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'En attendant je vous le déclare, le sort de Tyr et de Sidon sera, au jour du jugement, plus supportable que le vôtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Et toi, Capharnaoum! Seras-tu élevée jusques au ciel? Tu descendras jusques dans le séjour des morts, car si c\'était dans Sodome qu\'eussent été faits les miracles qui ont été faits chez toi, elle aurait subsisté jusques à aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'En attendant je vous déclare que le sort du pays de Sodome sera, au jour du jugement, plus supportable que le tien. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'En ce moment-là Jésus reprenant la parole dit: « Je Te rends grâces, ô Père, Seigneur du ciel et de la terre, de ce que Tu as caché ces choses aux sages et aux intelligents, et de ce que Tu les as révélées aux simples,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'oui, Père, de ce que cela s\'est ainsi trouvé bon à Tes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Tout m\'a été remis par mon Père, et personne ne connaît le Fils, si ce n\'est le Père, et personne non plus ne connaît le Père, si ce n\'est le Fils, et celui auquel le Fils veut le révéler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Venez à moi, vous tous qui êtes fatigués et surchargés, et c\'est moi qui vous soulagerai;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'prenez mon joug sur vous et instruisez-vous à mon école, car je suis doux et humble de cœur; et vous trouverez du soulagement pour vos âmes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'car mon joug est bienfaisant et mon fardeau est léger. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'En ce temps-là Jésus fit route le jour du sabbat à travers les champs de blé. Or ses disciples eurent faim, et ils se mirent à arracher des épis et à manger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Mais les pharisiens l\'ayant vu lui dirent: « Voici, tes disciples font ce qu\'il n\'est pas permis de faire un jour de sabbat. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Mais il leur dit: « N\'avez-vous pas lu ce que fit David, quand il eut faim, ainsi que ceux qui étaient avec lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Comment il entra dans la maison de Dieu, et comment ils mangèrent les pains de proposition qu\'il ne lui était pas permis de manger, non plus qu\'à ceux qui étaient avec lui, mais aux prêtres seuls?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Ou bien n\'avez-vous pas lu dans la loi que, le jour du sabbat, les prêtres dans le temple profanent le sabbat sans se rendre coupables?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Or je vous déclare qu\'il y a ici quelque chose de plus grand que le temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Mais si vous saviez ce que signifie: Je veux la miséricorde et non le sacrifice, vous n\'auriez pas condamné ceux qui ne sont pas coupables;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'car le fils de l\'homme est maître du sabbat. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Et, s\'étant éloigné de là, il vint dans leur synagogue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Et voici, il s\'y trouvait un homme qui avait une main sèche. Et ils lui demandèrent: « Est-il permis d\'opérer une guérison le jour du sabbat? » C\'était afin de pouvoir l\'accuser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Mais il leur dit: « Quel sera l\'homme d\'entre vous qui possédera une seule brebis, et si celle-ci vient à tomber le jour du sabbat dans un fossé, est-ce qu\'il ne la saisira pas et ne l\'en retirera pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Combien donc un homme ne vaut-il pas plus qu\'une brebis! En sorte qu\'il est permis de bien faire le jour du sabbat. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Alors il dit à cet homme: « Étends ta main; » et il l\'étendit, et elle redevint saine comme l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Or les pharisiens étant sortis tinrent conseil contre lui afin de le faire périr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Mais Jésus l\'ayant su s\'éloigna de là, et beaucoup de gens le suivirent, et ils les guérit tous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'et il leur adressa des remontrances pour qu\'ils ne le fissent pas connaître; —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'afin que fût accompli ce dont il a été parlé par l\'entremise d\'Ésaïe le prophète lorsqu\'il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, '« Voici Mon serviteur que J\'ai choisi, Mon bien-aimé en qui Mon âme a pris plaisir. Je mettrai Mon esprit sur lui, et il dénoncera le jugement aux nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Il ne contestera ni ne criera point, et personne n\'entendra sa voix dans les rues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Il ne brisera point le roseau froissé, et il n\'éteindra point le lumignon fumant, jusques à ce qu\'il ait fait triompher le jugement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'et les nations espéreront en son nom. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Alors on lui amena un démoniaque aveugle et muet, et il le guérit, en sorte que ce muet parlait et voyait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'et toute la foule fut stupéfaite, et elle disait: « Cet homme n\'est-il point le fils de David? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Mais les pharisiens l\'ayant entendu dirent: « Cet homme ne chasse les démons que grâce à Béézéboul, chef des démons. » Mais connaissant leurs pensées, il leur dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, '« Tout royaume divisé contre lui-même est dévasté, et toute ville ou toute famille divisée contre elle-même ne subsistera pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Et si Satan chasse Satan, il a été divisé contre lui-même; comment donc son royaume subsistera-t-il?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Et si, moi, c\'est grâce à Béézéboul que je chasse les démons, vos fils, grâce à qui les chassent ils? C\'est pourquoi ce sont eux qui seront vos juges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Mais, si c\'est grâce à l\'esprit de Dieu que moi je chasse les démons, le royaume de Dieu est donc parvenu jusques à vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Ou bien, comment quelqu\'un peut-il entrer dans la maison de l\'homme fort et piller ses biens, s\'il n\'a pas premièrement garrotté l\'homme fort, et alors il pillera sa maison?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Celui qui n\'est pas avec moi est contre moi, et celui qui ne rassemble pas avec moi disperse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'C\'est pourquoi je vous le déclare: tout péché et tout blasphème vous sera pardonné à vous autres hommes, mais le blasphème contre l\'esprit ne sera point pardonné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Et celui qui aura parlé contre le fils de l\'homme, il lui sera pardonné, mais celui qui aura parlé contre l\'esprit saint, il ne lui sera certainement pas pardonné, ni dans ce temps-ci, ni dans le temps à venir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Ou bien admettez que l\'arbre est bon et que son fruit est bon, ou bien admettez que l\'arbre est pourri et que son fruit est pourri; car c\'est au fruit que se connaît l\'arbre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Engeance de vipères, comment pouvez-vous, méchants comme vous êtes, dire de bonnes choses? Car c\'est par ce qui déborde du cœur, que la bouche parle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'L\'homme bon tire de son bon trésor de bonnes choses, et l\'homme mauvais tire de son mauvais trésor de mauvaises choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Mais je vous déclare que toute parole oiseuse que diront les hommes, ils en rendront compte au jour du jugement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'car par tes paroles tu seras justifié, et par tes paroles tu seras condamné. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Alors quelques-uns des scribes s\'adressèrent à lui, en disant: « Maître, nous voulons voir un signe dont tu sois l\'auteur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Mais il leur répliqua: « Une génération méchante et adultère réclame un signe, et il ne lui sera donné d\'autre signe que le signe de Jonas le prophète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Car de même que Jonas fut dans le ventre de la baleine trois jours et trois nuits, de même le fils de l\'homme sera dans le cœur de la terre trois jours et trois nuits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Les hommes de Ninive ressusciteront lors du jugement avec cette génération, et ils la condamneront, car ils se repentirent à la prédication de Jonas; et voici, il y a ici plus que Jonas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'La reine du Midi ressuscitera lors du jugement avec cette génération, et elle la condamnera, car elle vint des extrémités de la terre pour entendre la sagesse de Salomon; et voici, il y a ici plus que Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Mais, quand l\'esprit impur est sorti de l\'homme, il parcourt les lieux arides, cherchant du repos, et il n\'en trouve point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Alors il dit: « Je retournerai dans ma maison d\'où je suis sorti. » Et y revenant, il la trouve en paix, balayée et ornée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Alors il va et prend avec lui sept autres esprits plus méchants que lui-même, et, après être entrés, ils y habitent; et la nouvelle condition de cet homme devient pire que la première. Il en sera aussi de même pour cette méchante génération. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Pendant qu\'il parlait encore à la foule, voici, sa mère et ses frères se tenaient dehors, cherchant à lui parler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, '[Or, quelqu\'un lui dit: voici, ta mère et tes frères sont là dehors qui cherchent à te parler.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Mais Jésus répliqua à celui qui le lui disait: « Qui est ma mère, et qui sont mes frères? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Et ayant étendu la main vers ses disciples, il dit: « Voilà ma mère et mes frères!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Car quiconque aura fait la volonté de mon Père qui est dans les cieux, c\'est lui qui est mon frère, et ma sœur, et ma mère. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Ce jour-là Jésus, après être sorti de la maison, se tenait assis près de la mer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'et une foule nombreuse se rassembla auprès de lui, en sorte qu\'étant monté sur une barque il s\'y assit, et toute la foule se tenait debout sur le rivage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Et il leur parla de beaucoup de choses sous forme de paraboles, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, '« Voici, le semeur sortit pour semer, et pendant qu\'il semait, une partie tomba le long du chemin, et les oiseaux étant venus la mangèrent toute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Mais une autre partie tomba sur les endroits rocailleux où elle n\'avait pas beaucoup de terre, et aussitôt elle leva parce qu\'elle n\'avait pas un sol profond;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'mais, le soleil s\'étant levé, elle fut brûlée, et, comme elle n\'avait pas de racine, elle sécha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Mais une autre partie tomba sur les épines, et les épines montèrent et l\'étouffèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Mais une autre partie tomba sur la bonne terre, et elle donnait du fruit à raison de cent, et de soixante, et de trente pour un.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Que celui qui a des oreilles entende! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Et les disciples s\'étant approchés lui dirent: « Pourquoi leur parles-tu en paraboles? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Mais il leur répliqua: « C\'est qu\'il vous a été donné de connaître les mystères du royaume des cieux, tandis qu\'à eux cela ne leur a pas été donné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Car quiconque a, il lui sera donné et il regorgera; mais quiconque n\'a pas, même ce qu\'il a lui sera enlevé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Voici pourquoi je leur parle en paraboles; c\'est qu\'en voyant ils ne voient pas, et qu\'en entendant ils n\'entendent ni ne comprennent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'et c\'est pour eux que s\'accomplit la prophétie d\'Ésaïe, qui dit: Oyez par l\'ouïe, et vous ne comprendrez certainement pas; et en voyant vous verrez et vous n\'apercevrez certainement pas:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'car le cœur de ce peuple s\'est épaissi, et ils ont difficilement ouï avec les oreilles, et ils ont fermé leurs yeux, de peur qu\'ils ne voient avec les yeux, et qu\'ils n\'entendent avec les oreilles, et qu\'ils ne comprennent avec le cœur, et qu\'ils ne se convertissent; et Je les guérirai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Mais pour vous, vos yeux sont heureux parce qu\'ils voient, et vos oreilles, parce qu\'elles entendent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Car en vérité je vous déclare que beaucoup de prophètes et de justes ont désiré voir ce que vous voyez et ne l\'ont pas vu, et entendre ce que vous entendez et ne l\'ont pas entendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Pour vous donc, écoutez la parabole du semeur:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Quiconque entend la parole du royaume et ne la comprend pas, le malin survient et enlève ce qui a été semé dans son cœur; c\'est celui qui a été semé le long du chemin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Quant à celui qui a été semé sur les endroits rocailleux, c\'est celui qui entend la parole et la reçoit aussitôt avec joie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'mais il n\'a pas de racine en lui-même, au contraire il est sans persistance, et s\'il survient une tribulation ou une persécution à cause de la parole, il trébuche aussitôt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Quant à celui qui a été semé dans les épines, c\'est celui qui entend la parole, et les soucis du siècle et le faux attrait de la richesse se réunissent pour étouffer la parole et elle devient stérile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Mais celui qui a été semé sur la bonne terre, c\'est celui qui entend et comprend la parole; qui, par conséquent, donne du fruit et rapporte à raison de cent, de soixante et de trente pour un. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Il leur proposa une autre parabole en disant: « Le royaume des cieux ressemble à un homme qui a semé une bonne semence dans son champ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'mais, pendant que les gens dormaient, son ennemi est venu, et il a encore semé de l\'ivraie parmi le blé, et il s\'en est allé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Or, quand l\'herbe eut poussé et fructifié, alors apparut aussi l\'ivraie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Mais les esclaves du chef de famille étant venus lui dirent: « Seigneur, n\'est-ce pas une bonne semence que tu as semée dans ton champ? D\'où vient donc qu\'il a de l\'ivraie? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Mais il leur dit: « C\'est un ennemi qui a fait cela. » Sur quoi ils lui disent: « Veux-tu donc que nous allions la cueillir? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Mais il dit: « Non, de peur qu\'en cueillant l\'ivraie vous n\'arrachiez le blé avec elle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'laissez-les l\'un et l\'autre croître ensemble jusqu\'à la moisson; et au moment de la moisson je dirai aux moissonneurs: Cueillez premièrement l\'ivraie et la liez en gerbes pour la brûler toute, mais, quant au blé, serrez-le dans mon grenier. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Il leur proposa une autre parabole en disant: « Le royaume des cieux est semblable à un grain de moutarde, qu\'un homme a pris et semé dans son champ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'cette semence est, il est vrai, plus petite que toutes les autres, mais quand elle a crû, elle est plus grande que les plantes potagères et elle devient un arbre, en sorte que les oiseaux du ciel viennent s\'abriter dans ses branches. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Il leur dit une autre parabole: « Le royaume des cieux est semblable à du levain qu\'une femme a pris et pétri dans trois mesures de farine, jusques à ce que le tout fût levé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Jésus dit toutes ces choses en paraboles à la foule, et il ne leur disait rien sans parabole; —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'afin que fût accompli ce dont il a été parlé par l\'entremise du prophète lorsqu\'il dit: « J\'ouvrirai ma bouche par des paraboles, je proférerai des choses cachées dès la création. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Alors ayant congédié la foule, il entra dans la maison, et ses disciples s\'approchèrent de lui en disant: « Éclaircis-nous la parabole de l\'ivraie du champ. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Or il répliqua: « Celui qui sème la bonne semence, c\'est le fils de l\'homme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'le champ, c\'est le monde; la bonne semence, ce sont les fils du royaume; l\'ivraie, ce sont les fils du malin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'l\'ennemi, c\'est le diable qui l\'a semée; la moisson, c\'est la consommation du temps, et les moissonneurs, ce sont les anges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'De même donc que l\'on cueille l\'ivraie et qu\'on la brûle toute dans le feu, de même en sera-t-il lors de la consommation du temps;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'le fils de l\'homme enverra ses anges, et ils recueilleront, pour les ôter de son royaume, tous les scandales et ceux qui commettent l\'iniquité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'et ils les jetteront dans la fournaise du feu; c\'est là que sera le pleur et le grincement des dents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Alors les justes resplendiront comme le soleil dans le royaume de leur Père. Que celui qui a des oreilles entende!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, '« Le royaume des cieux est semblable à un trésor caché dans le champ, qu\'un homme, après l\'avoir trouvé, a caché, et dans sa joie il s\'en va, et vend tout ce qu\'il possède et achète ce champ-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Le royaume des cieux est encore semblable à un marchand qui cherche de belles perles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'or, ayant trouvé une perle de grand prix, il est allé vendre tout ce qu\'il possédait, et il l\'a achetée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Le royaume des cieux est encore semblable à un filet jeté dans la mer, et qui a ramené des poissons de toute espèce;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'lorsqu\'il a été rempli, après l\'avoir tiré sur le rivage, et s\'être assis, on a recueilli les bons dans des vases, et on a jeté dehors les pourris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Il en sera de même lors de la consommation du temps; les anges sortiront et sépareront les méchants du milieu des justes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'et ils les jetteront dans la fournaise du feu; c\'est là que sera le pleur et le grincement des dents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Avez-vous compris toutes ces choses? » Ils lui dirent: « Oui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Et lui leur dit: « C\'est pour cela que tout scribe qui a été instruit pour le royaume des cieux est semblable à un chef de famille, qui tire de son trésor du neuf et du vieux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Et il advint, lorsque Jésus eut terminé ces paraboles, qu\'il s\'éloigna de là,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'et s\'étant rendu dans sa patrie, il les enseignait dans leur synagogue, en sorte qu\'ils étaient stupéfaits, et qu\'ils disaient: « D\'où viennent à celui-ci cette sagesse et ces miracles?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Celui-ci n\'est-il pas le fils du charpentier? Est-ce que sa mère ne s\'appelle pas Marie, et ses frères, Jacques et Joseph et Simon et Judas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Et ses sœurs ne vivent-elles pas toutes parmi nous? D\'où lui viennent donc toutes ces choses? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Et il était pour eux une pierre d\'achoppement. Mais Jésus leur dit: « Ce n\'est que dans sa patrie et dans sa famille, qu\'un prophète est méprisé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Et il ne fit pas là beaucoup de miracles, à cause de leur incrédulité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'En ce temps-là Hérode le tétrarque ouït parler de la renommée de Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'et il dit à ses serviteurs: « Cet homme est Jean le baptiste; il est ressuscité des morts, et c\'est pourquoi les miracles s\'opèrent par lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Hérode, en effet, après avoir fait dans le temps arrêter Jean, l\'avait fait enchaîner et mettre en prison, à cause d\'Hérodias, femme de Philippe son frère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'car Jean lui disait: « Il ne t\'est pas permis de la posséder. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Et quoiqu\'il eût désiré le faire mourir, il avait craint la foule, car on le regardait comme un prophète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Mais lors de la fête anniversaire de la naissance d\'Hérode, la fille d\'Hérodias dansa devant tout le monde, et elle plut à Hérode,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'en sorte qu\'il s\'engagea par serment à lui donner quoi que ce fût qu\'elle demanderait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Or, ayant été endoctrinée par sa mère: « Donne-moi, » dit-elle, « ici, sur un plat, la tête de Jean le baptiste. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Et le roi attristé ordonna, à cause de son serment et des convives, qu\'on la donnât,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'et il envoya décapiter Jean dans la prison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Et sa tête fut apportée sur un plat, et donnée à la jeune fille, et elle la porta à sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Et ses disciples vinrent enlever le cadavre, et ils l\'enterrèrent, et ils allèrent en informer Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Or, Jésus l\'ayant appris, partit de là sur une barque, pour se retirer à l\'écart dans un lieu désert, et la foule l\'ayant su le suivit à pied des différentes villes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Et étant sorti, il vit une foule nombreuse, et il fut ému de compassion envers elle, et il guérit leurs malades.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Mais, le soir étant venu, les disciples s\'approchèrent de lui en disant: « Ce lieu est désert, et l\'heure est déjà avancée, renvoie la foule, afin qu\'elle se rende dans les villages pour s\'y acheter des vivres, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Or Jésus leur dit: « Ils n\'ont pas besoin de s\'en aller, donnez-leur vous-mêmes à manger. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Mais ils lui disent: « Nous n\'avons ici que cinq pains et deux poissons. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Et il dit: « Apportez-les-moi ici,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'et ordonnez à la foule de s\'asseoir sur l\'herbe. » Après avoir pris les cinq pains et les deux poissons, il prononça, en levant les yeux vers le ciel, une bénédiction; et après les avoir rompus, il donna les pains à ses disciples et les disciples à la foule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Et tous mangèrent et furent rassasiés; et on emporta le surplus des morceaux dans douze corbeilles pleines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Or, ceux qui mangèrent étaient environ cinq mille hommes, sans compter les femmes et les petits enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Et aussitôt il contraignit ses disciples à monter dans une barque et à passer avant lui sur l\'autre rive, jusques à ce qu\'il eût renvoyé la foule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Et, après avoir renvoyé la foule, il monta sur la montagne pour prier à l\'écart. Mais, le soir étant venu, il se trouva seul en cet endroit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Or, la barque était déjà éloignée de plusieurs stades de la terre, et elle était battue par les flots, car le vent était contraire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Mais à la quatrième veille de la nuit, il vint vers eux en marchant sur la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Or les disciples, en le voyant marcher sur la mer, furent tout troublés, et ils se disaient: « C\'est un fantôme, » et dans leur peur ils se mirent à crier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Mais Jésus leur parla aussitôt, en disant: « Courage, c\'est moi; n\'ayez pas peur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Et Pierre lui répliqua: « Seigneur, si c\'est toi, ordonne-moi de venir vers toi sur les eaux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Et il lui dit: « Viens. » Et Pierre, étant descendu de la barque, marcha sur les eaux et vint vers Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'mais en voyant la violence du vent, il eut peur, et ayant commencé à s\'enfoncer, il s\'écria: « Seigneur, sauve-moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Et aussitôt Jésus ayant étendu la main le saisit et lui dit: « Homme de peu de foi, pourquoi as-tu douté? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Et lorsqu\'ils furent montés dans la barque, le vent tomba.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Mais ceux qui étaient dans la barque l\'adorèrent, en disant: « Tu es vraiment le fils de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Et ayant achevé leur traversée, ils touchèrent terre à Gennèsaret,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'et les gens de ce lieu-là l\'ayant reconnu envoyèrent dans tout le pays circonvoisin, et on lui amena tous les malades,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'et ils le suppliaient de les laisser toucher seulement la frange de son manteau, et tous ceux qui la touchèrent furent guéris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Alors arrivent de Jérusalem vers Jésus des pharisiens et des scribes disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, '« Pourquoi tes disciples transgressent-ils la tradition des anciens? Car ils ne se lavent pas les mains, quand ils prennent leurs repas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Jésus leur répliqua: « Pourquoi vous-mêmes transgressez-vous aussi le commandement de Dieu, en faveur de votre propre tradition?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Car Dieu a dit: Honore ton père et ta mère, et: Que celui qui maudit père ou mère soit mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Mais vous, vous dites: « Celui qui aura dit à son père ou à sa mère: Offrande est faite de ce dont je pourrais t\'assister, n\'honorera-t-il pas son père? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'Et vous avez abrogé la parole de Dieu en faveur de votre tradition.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Hypocrites! Comme Ésaïe a bien prophétisé sur votre compte, lorsqu\'il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, 'Ce peuple-ci M\'honore des lèvres, tandis que leur cœur est bien éloigné de Moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'mais c\'est vainement qu\'ils Me révèrent, en enseignant des doctrines qui sont des commandements d\'hommes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Et ayant appelé la foule à lui, il leur dit: « Écoutez et comprenez:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Ce n\'est pas ce qui entre dans la bouche qui souille l\'homme; mais ce qui sort de la bouche, voilà ce qui souille l\'homme. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Alors ses disciples s\'étant approchés lui disent « Sais-tu que les pharisiens, en entendant cette parole, ont été scandalisés? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Mais il répliqua: « Toute plante que n\'a point plantée mon Père céleste sera déracinée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Laissez-les: ce sont des guides aveugles; or, si un aveugle sert de guide à un aveugle, ils tomberont tous deux dans un fossé, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Mais Pierre lui répliqua: « Explique-nous la parabole. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Sur quoi il dit: « Et vous aussi, êtes-vous encore sans intelligence?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Ne comprenez-vous pas que tout ce qui entre dans la bouche s\'en va dans le ventre, et est rejeté dans le retrait?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Mais ce qui sort de la bouche vient du cœur, et c\'est là ce qui souille l\'homme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'car c\'est du cœur que sortent les mauvaises pensées, les meurtres, les adultères, les impudicités, les larcins, les faux témoignages, les calomnies;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'ce sont ces choses-là qui souillent l\'homme; mais manger sans s\'être lavé les mains ne souille pas l\'homme. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Et Jésus étant parti de là gagna le territoire de Tyr et de Sidon;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'et voici, une femme chananéenne venue de cette contrée-là s\'écriait: « Aie pitié de moi, Seigneur, fils de David, ma fille est cruellement possédée du démon. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Mais il ne lui répondit pas un mot, et ses disciples étant survenus le pressaient en disant: « Renvoie-la, car elle nous poursuit de ses cris. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Or il répliqua: « Je n\'ai été envoyé qu\'aux brebis perdues de la maison d\'Israël. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Elle cependant, revenant à la charge, l\'adorait en disant: « Seigneur, secours-moi! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Mais il répliqua: « Il n\'est pas bien de prendre le pain des enfants, et de le jeter aux petits chiens. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Sur quoi elle dit: « Assurément, Seigneur! Les petits chiens aussi mangent une partie des miettes qui tombent de la table de leurs maîtres. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Alors Jésus lui répliqua: « O femme! ta foi est grande, qu\'il te soit fait comme tu désires. » Et dès ce moment-là sa fille fut guérie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Et Jésus s\'étant éloigné de là vint vers la mer de Galilée, et après être monté sur la montagne, il s\'y tenait assis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'et une foule nombreuse s\'approcha de lui, ayant avec elle des boiteux, des estropiés, des aveugles, des sourds, et bien d\'autres malades, et on les jeta à ses pieds, et il les guérit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'en sorte que la foule fut émerveillée de voir des sourds entendre, des estropiés guérir, et des boiteux marcher, et des aveugles recouvrer la vue; et elle glorifia le Dieu d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Mais Jésus ayant appelé à lui ses disciples dit: « J\'ai compassion de cette foule, car voici trois jours qu\'ils restent auprès de moi, et ils n\'ont rien à manger; cependant je ne veux pas les renvoyer à jeun de peur qu\'ils ne défaillent en chemin: »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Et les disciples lui disent: « Où nous procurerons-nous dans un désert assez de pains pour rassasier une si grande foule? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Et Jésus leur dit: « Combien de pains avez-vous? » Ils dirent: « Sept, et quelques petits poissons. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Et ayant invité la foule à s\'asseoir sur la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'il prit les sept pains et les poissons, et après avoir rendu grâces il les rompit, et il les donnait aux disciples, et les disciples à la foule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Et tous mangèrent et furent rassasiés, et on emporta le surplus des morceaux dans sept paniers pleins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Or, ceux qui mangèrent étaient au nombre d\'environ quatre mille hommes, sans compter les femmes et les petits enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Après avoir renvoyé la foule il monta dans la barque, et il vint dans le territoire de Magadan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Et les pharisiens et les sadducéens étant survenus, lui demandèrent, pour le mettre à l\'épreuve, de leur montrer un signe qui vînt du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Mais il leur répliqua: [« Quand le soir est venu, vous dites: Beau temps, car le ciel est rouge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'Et, le lendemain: Aujourd\'hui, de l\'orage, car le ciel est d\'un rouge sombre. Vous savez bien discerner l\'aspect du ciel, mais vous ne pouvez pas discerner les signes des temps.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Une génération méchante et adultère demande un signe; et il ne lui sera point donné d\'autre signe que le signe de Jonas. » Et les ayant quittés, il s\'en alla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Et en passant sur l\'autre rive les disciples oublièrent de prendre des pains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Or, Jésus leur dit: « Ayez soin de vous tenir en garde contre le levain des pharisiens et des sadducéens. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Mais ils réfléchissaient en eux-mêmes et se disaient: « C\'est parce que nous n\'avons pas pris de pains. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Mais Jésus s\'en étant aperçu dit: « Pourquoi réfléchissez-vous en vous-mêmes, gens de peu de foi, sur ce que vous n\'avez pas des pains?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Ne comprenez-vous pas encore, et ne vous rappelez-vous plus les cinq pains des cinq mille, et combien de corbeilles vous emportâtes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'ni les sept pains des quatre mille, et combien de paniers vous emportâtes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Comment ne comprenez-vous pas que ce n\'est pas à propos de pains que je vous ai parlé? Mais tenez-vous en garde contre le levain des pharisiens et des sadducéens. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Alors ils comprirent qu\'il ne leur avait pas dit de se tenir en garde contre le levain des pains, mais contre l\'enseignement des sadducéens et des pharisiens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Or, lorsque Jésus fut arrivé sur le territoire de Césarée de Philippe, il interrogeait ses disciples, en disant: « Qui disent les gens qu\'est le fils de l\'homme? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Et ils lui dirent: « Ceux-ci, Jean le baptiste; ceux-là, Élie; et d\'autres, Jérémie ou l\'un des prophètes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Il leur dit: « Mais vous, qui dites-vous que je suis? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Or Simon Pierre répliqua: « Tu es le Christ, le fils du Dieu vivant. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Et Jésus lui répliqua: « Heureux es-tu, Simon Barjona, car ce n\'est pas la chair ni le sang qui te l\'ont révélé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'mais mon Père qui est dans les cieux. Pour moi, je te déclare de mon côté que tu es Pierre, et que sur ce roc-là je bâtirai mon église, et que les portes de l\'enfer ne prévaudront point contre elle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'je te donnerai les clefs du royaume des cieux, et tout ce que tu auras lié sur la terre sera lié dans les cieux, et tout ce que tu auras délié sur la terre sera délié dans les cieux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Alors il fit des remontrances aux disciples, afin qu\'ils ne dissent à personne: « C\'est lui qui est le Christ. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Dès lors Jésus-Christ commença à montrer à ses disciples qu\'il lui fallait se rendre à Jérusalem, et beaucoup souffrir du fait des anciens et des grands prêtres et des scribes, et être mis à mort, et ressusciter le troisième jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Et Pierre, l\'ayant pris à part, lui dit en lui faisant des remontrances: « Miséricorde te soit faite, Seigneur, certainement cela ne t\'arrivera point! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Mais lui s\'étant retourné dit à Pierre: « Va-t-en arrière de moi, Satan, tu m\'es une pierre d\'achoppement, car tu ne penses pas aux choses de Dieu, mais à celles des hommes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Alors Jésus dit à ses disciples: « Si quelqu\'un veut venir après moi, qu\'il renonce à lui-même et qu\'il prenne sa croix, et qu\'il me suive;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'car celui qui voudra sauver sa vie la perdra, mais celui qui aura perdu sa vie à cause de moi, la trouvera;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'en effet, que servira-t-il à un homme d\'avoir gagné le monde entier, mais perdu sa vie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Ou bien que donnera un homme pour racheter sa vie? Car le fils de l\'homme doit venir entouré de la gloire de son Père, avec ses anges, et c\'est alors qu\'il rendra à chacun selon sa conduite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'En vérité je vous déclare qu\'il y a quelques-uns de ceux qui sont ici présents qui ne goûteront certainement point la mort jusques à ce qu\'ils aient vu le fils de l\'homme venir avec son royaume. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Et, six jours après, Jésus prend avec lui Pierre, et Jacques, et Jean son frère, et il les conduit à l\'écart sur une haute montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Et il fut transfiguré en leur présence, et son visage brilla comme le soleil, tandis que ses vêtements devinrent blancs comme la lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Et voici, Moïse et Élie leur apparurent, qui conversaient avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Mais Pierre prenant la parole dit à Jésus: « Seigneur, c\'est une bonne chose pour nous que d\'être ici; si tu le veux, je ferai ici trois tentes, une pour toi, et une pour Moïse, et une pour Élie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Comme il parlait encore, voici, une nuée lumineuse les couvrit, et voici, une voix sortant de la nuée dit: « Celui-ci est Mon fils bien-aimé en qui J\'ai pris plaisir. Écoutez-le. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Ce que les disciples ayant ouï, ils tombèrent sur leur visage et furent saisis d\'une grande peur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Et Jésus s\'approcha d\'eux, et après les avoir touchés, il dit: « Levez-vous, et n\'ayez point peur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Or, ayant levé les yeux, ils ne virent personne que Jésus lui-même seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Et pendant qu\'ils descendaient de la montagne, Jésus leur donna ses ordres en disant: « Ne parlez à personne de cette vision, jusques à ce que le fils de l\'homme soit ressuscité des morts. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Et ses disciples lui demandèrent: « Pourquoi donc les scribes disent-ils qu\'il faut qu\'Élie vienne premièrement? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Mais il répliqua: « Il est vrai qu\'Élie doit venir, et il rétablira toutes choses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'mais je vous déclare qu\'Élie est déjà venu, et qu\'ils ne l\'ont pas reconnu, mais qu\'ils ont fait de lui tout ce qu\'ils ont voulu; c\'est de la même manière que le fils de l\'homme aussi doit souffrir par eux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Alors les disciples comprirent que c\'était de Jean le baptiste, qu\'il leur avait parlé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Et, quand ils furent arrivés près de la foule, un homme s\'approcha de lui, en tombant à ses genoux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'et en disant: « Seigneur, aie pitié de mon fils, car il est lunatique et très malade; en effet, il tombe souvent dans le feu et souvent dans l\'eau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'je l\'ai amené à tes disciples, et ils n\'ont pu le guérir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Et Jésus prenant la parole dit: « O génération incrédule et pervertie! Jusques à quand serai-je avec vous? Jusques à quand vous supporterai-je? Amenez-le-moi ici. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Et Jésus lui fit des remontrances, et le démon sortit de lui, et dès ce moment l\'enfant fut guéri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Alors les disciples s\'étant approchés de Jésus à l\'écart lui dirent: « Pourquoi n\'avons-nous pas pu le chasser nous-mêmes? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Et il leur dit: « A cause de votre peu de foi; car en vérité je vous le déclare, si vous aviez de la foi comme un grain de moutarde, vous diriez à cette montagne: transporte-toi d\'ici là, et elle se transporterait, et rien ne vous serait impossible. [');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Mais cette espèce-là ne sort que par la prière et le jeûne »]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Or, pendant qu\'ils se trouvaient réunis en Galilée, Jésus leur dit: « Le fils de l\'homme va être livré aux mains des hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'et ils le feront mourir, et le troisième jour il ressuscitera. » Et ils furent dans une grande tristesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Or, lorsqu\'ils furent arrivés à Capharnaoum, les percepteurs des deux drachmes s\'approchèrent de Pierre et lui dirent: « Votre maître ne paie-t-il pas les deux drachmes? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Il dit: « Oui, » et dès qu\'il fut entré dans la maison Jésus le prévint en disant: « Que t\'en semble, Simon? Sur qui les rois de la terre lèvent-ils des impôts ou une capitation? Sur leurs fils, ou sur les étrangers?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Et lorsqu\'il eut dit: « Sur les étrangers, » Jésus lui dit: « Ainsi donc les fils en sont exempts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'mais afin de ne pas les scandaliser, va-t-en à la mer, jette un hameçon et prends le premier poisson venu, et, après lui avoir ouvert la bouche, tu trouveras un statère. Prends-le, et donne-le-leur pour moi et pour toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'Or, en ce moment-là, les disciples s\'approchèrent de Jésus en disant: « Quel est donc le plus grand dans le royaume des cieux? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Et ayant appelé un petit enfant, il le plaça au milieu d\'eux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'et dit: « En vérité, je vous le déclare, si vous ne vous convertissez, et si vous ne devenez comme les petits enfants, vous n\'entrerez certainement pas dans le royaume des cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Quiconque donc s\'humiliera comme ce petit enfant, celui-là est le plus grand dans le royaume des cieux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'et celui qui aura reçu en mon nom un seul petit enfant comme celui-là, il me reçoit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'mais celui qui aura scandalisé un seul de ces petits qui croient en moi, mieux vaudrait pour lui qu\'on suspendît autour de son col une meule de moulin à âne, et qu\'on le précipitât dans les profondeurs de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Malheur au monde à cause des scandales; car il est nécessaire que les scandales arrivent; néanmoins malheur à l\'homme par qui le scandale arrive!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Mais si ta main ou ton pied sont pour toi une occasion de scandale, coupe-le et jette-le loin de toi; il t\'est bon d\'entrer dans la vie estropié ou boiteux, plutôt que d\'être jeté, en ayant deux mains ou deux pieds, dans le feu éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Et si ton œil est pour toi une occasion de scandale, arrache-le, et jette-le loin de toi; il t\'est bon d\'entrer borgne dans la vie plutôt que d\'être jeté, en ayant deux yeux, dans la géhenne du feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Prenez garde de ne pas mépriser un seul de ces petits; car je vous déclare que leurs anges contemplent constamment dans le ciel la face de mon Père qui est dans les cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, '[Car le fils de l\'homme est venu chercher et sauver ce qui était perdu.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Que vous en semble? Si un homme avait cent brebis et qu\'une d\'elles se fût égarée, est-ce qu\'il ne laissera pas les quatre-vingt-dix-neuf brebis sur les montagnes pour aller chercher celle qui s\'est égarée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Et s\'il arrive qu\'il la trouve, en vérité je vous déclare qu\'il éprouve à son sujet plus de joie que pour les quatre-vingt-dix-neuf qui ne se sont pas égarées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'De même, ce n\'est pas la volonté de mon Père qui est dans les cieux, qu\'un seul de ces petits se perde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Mais si ton frère vient à pécher, va, reprends-le entre toi et lui seul; s\'il t\'écoute, tu as gagné ton frère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'mais s\'il ne t\'écoute pas, prends encore une ou deux personnes avec toi, afin que sur une déclaration de deux ou trois témoins toute affaire soit décidée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Mais, s\'il refuse de les écouter, adresse-toi à l\'église, et s\'il refuse aussi d\'écouter l\'église, qu\'il soit pour toi comme le païen et le publicain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'En vérité je vous le déclare, tout ce que vous aurez lié sur la terre, sera lié dans le ciel, et tout ce que vous aurez délié sur la terre sera délié dans le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'En vérité je vous déclare encore que, si deux d\'entre vous s\'accordent sur la terre pour quoi que ce soit qu\'ils aient à demander, cela leur sera accordé par mon Père qui est dans les cieux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'car là où deux ou trois sont réunis en mon nom, je suis là au milieu d\'eux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Alors Pierre s\'étant approché, lui dit: « Seigneur, combien de fois mon frère péchera-t-il contre moi et lui pardonnerai-je? Sera-ce jusques à sept fois? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jésus lui dit: « Je ne te dis pas jusques à sept fois, mais jusques à soixante-dix fois sept.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'C\'est pourquoi le royaume des cieux ressemble à un roi qui voulut faire rendre compte à ses esclaves.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Or, après qu\'il eut commencé à faire rendre compte, on lui amena un débiteur de dix mille talents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Mais comme il n\'avait pas de quoi payer, le maître ordonna qu\'il fût vendu, ainsi que sa femme, ses enfants et tout son avoir, et que la dette fût payée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'L\'esclave s\'étant donc prosterné l\'adorait en disant: « Prends patience à mon égard, et je te paierai tout. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Et le maître de l\'esclave ayant été touché de compassion, le relâcha et lui remit le prêt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Mais l\'esclave, après qu\'il fut sorti, trouva un autre esclave qui servait avec lui, et qui lui devait cent deniers, et l\'ayant saisi il l\'étranglait en disant: « Paie, puisque tu dois. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'L\'esclave qui servait avec lui s\'étant donc prosterné, le sollicitait en disant: « Prends patience à mon égard, et je te paierai; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'mais lui ne voulait pas, et tout au contraire il s\'en alla le faire jeter en prison jusques à ce qu\'il eût payé ce qu\'il devait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Les esclaves qui servaient avec lui, ayant donc vu ce qui s\'était passé, furent dans une grande tristesse, et ils vinrent informer leur maître de tout ce qui s\'était passé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Alors son maître l\'ayant fait venir lui dit: « Méchant esclave, je t\'ai remis toute cette dette-là parce que tu m\'en as sollicité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'ne fallait-il pas que, toi aussi, tu eusses pitié de l\'esclave qui sert avec toi, comme moi de mon côté j\'ai eu pitié de toi? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Et son maître irrité le livra aux bourreaux jusques à ce qu\'il eût payé tout ce qu\'il devait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'C\'est ainsi que mon Père céleste agira aussi envers vous, si vous ne pardonnez pas, chacun à son frère, du fond de vos cœurs. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Et il advint, lorsque Jésus eut terminé ces discours, qu\'il s\'éloigna de la Galilée et passa dans le territoire de la Judée, par l\'autre côté du Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'Et une foule nombreuse le suivit, et il les guérit en cet endroit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Et des pharisiens s\'approchèrent de lui pour le mettre à l\'épreuve, en disant: « Est-il permis de répudier sa femme pour quelque motif que ce soit? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Et il répliqua: « N\'avez-vous pas lu que Celui qui les créa à l\'origine les fit mâle et femelle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'et qu\'il dit: « à cause de cela l\'homme quittera son père et sa mère, et il s\'unira étroitement à sa femme, et les deux deviendront une seule chair? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'En sorte qu\'ils ne sont plus deux, mais une seule chair. Ainsi donc que ce que Dieu à conjoint, l\'homme ne le sépare pas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Ils lui disent: « Pourquoi donc Moïse a-t-il commandé de donner un acte de divorce et de la répudier? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Il leur dit: « C\'est à cause de votre dureté de cœur que Moïse vous a permis de répudier vos femmes; mais à l\'origine cela ne s\'est pas passé ainsi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Pour moi, je vous le déclare: celui qui aura répudié sa femme, sauf pour cause d\'impudicité, la pousse à commettre un adultère, et celui qui aura épousé une femme répudiée commet un adultère. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Les disciples lui disent: « Si telle est la relation de l\'homme avec la la femme, il ne convient pas de se marier. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Mais il leur dit: « Tous n\'acquiescent pas à cette parole, mais seulement ceux auxquels cela est accordé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'en effet, il y a des eunuques qui sont sortis tels du ventre de leur mère, et il y a des eunuques qui ont été mutilés par les hommes, et il y a des eunuques qui se sont mutilés eux-mêmes à cause du royaume des cieux. Que celui qui peut acquiescer, acquiesce. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Alors on lui amena de petits enfants, afin qu\'il leur imposât les mains et qu\'il priât; mais les disciples leur en firent des remontrances.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Or Jésus dit: « Laissez ces petits enfants, et ne les empêchez pas de venir à moi, car c\'est à ceux qui leur ressemblent qu\'appartient le royaume des cieux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Puis, après leur avoir imposé les mains, il partit de là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Et voici, quelqu\'un s\'étant approché de lui, dit: « Maître que dois-je faire de bon pour posséder la vie éternelle? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Mais il lui dit: « Pourquoi m\'interroges-tu sur ce qui est bon? Un seul est Le Bon; mais si tu veux entrer dans la vie, garde les commandements. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Il lui dit: « Lesquels? » Or Jésus dit: « Ceux-ci: tu ne tueras point; tu ne commettras point d\'adultère; tu ne déroberas point; tu ne feras point de faux témoignage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'honore ton père et ta mère; tu aimeras ton prochain comme toi-même. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Le jeune homme lui dit: « J\'ai observé toutes ces choses; que me manque-t-il encore? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jésus lui dit: « Si tu veux être parfait, va, vends tes biens, et donne-les aux pauvres, et tu auras un trésor dans les cieux, puis viens, suis-moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Mais le jeune homme, après avoir entendu ce discours, s\'en alla tout triste; car il avait de grandes richesses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Or Jésus dit à ses disciples: « En vérité, je vous déclare qu\'un riche entrera difficilement dans le royaume des cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Or je vous le déclare encore, il est plus facile qu\'un chameau passe par un trou d\'aiguille, qu\'un riche n\'entre dans le royaume de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Ce que les disciples ayant ouï, ils étaient dans une grande stupéfaction, et ils disaient: « Qui donc peut être sauvé? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Mais Jésus, ayant fixé sur eux ses regards, dit: « Quant aux hommes cela est impossible, mais quant à Dieu tout est possible. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Alors Pierre reprenant la parole lui dit: « Voici, pour nous, nous avons tout abandonné, et nous t\'avons suivi; qu\'avons-nous donc à attendre? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Et Jésus leur dit: « En vérité, je vous déclare que vous qui m\'avez suivi, lors du renouvellement, quand le fils de l\'homme se sera assis sur le trône de sa gloire, vous aussi vous serez assis sur douze trônes pour juger les douze tribus d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Et quiconque a abandonné maisons, ou frères, ou sœurs, ou père, ou mère, ou enfants, ou champs, à cause de mon nom, recevra infiniment davantage, et il héritera la vie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Mais plusieurs, quoique des derniers, seront des premiers, et des derniers, quoique des premiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'En effet, le royaume des cieux est semblable à un chef de famille qui sortit de grand matin afin de louer des ouvriers pour les envoyer à sa vigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Or, après avoir fait accord avec les ouvriers à raison de un denier par jour, il les envoya à sa vigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Et étant sorti vers la troisième heure, il en vit d\'autres qui se tenaient sur la place du marché sans rien faire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'et il leur dit: « Allez aussi à la vigne, et ce qui sera juste je vous le donnerai. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Et ils y allèrent. Étant de nouveau sorti vers la sixième et vers la neuvième heure, il fit encore de même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Puis étant sorti à la onzième, il en trouva d\'autres qui se tenaient là, et il leur dit: « Pourquoi vous tenez-vous ici le jour entier sans rien faire? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Ils lui disent: « C\'est que personne ne nous a loués. » Il leur dit: « Vous aussi allez à la vigne. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Or, quand le soir fut venu, le maître de la vigne, dit à son intendant: « Appelle les ouvriers, et paie-leur leur salaire, en allant des derniers aux premiers. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Or, ceux de la onzième heure étant venus reçurent chacun un denier;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'et les premiers étant venus crurent qu\'ils recevraient davantage, et ils reçurent eux aussi un denier par tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'Mais après l\'avoir reçu, ils murmuraient contre le chef de famille,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'en disant: « Ceux-ci venus les derniers ont travaillé une seule heure, et tu les as égalés à nous, qui avons supporté le poids du jour et l\'ardente chaleur! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Mais il répliqua à l\'un d\'eux: « Camarade, je ne te fais aucun tort; n\'as-tu pas fait accord avec moi à raison d\'un denier?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Prends ce qui est à toi, et t\'en vas. Pour moi, je veux donner à celui-ci qui est venu le dernier autant qu\'à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Ne m\'est-il pas permis de faire ce que je veux de ce qui est à moi? Ou bien vois-tu de mauvais œil que je sois bon? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Ainsi les derniers seront des premiers et les premiers des derniers. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Or, comme Jésus allait monter à Jérusalem, il prit à part les douze disciples et leur dit en chemin:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, '« Voici, nous montons à Jérusalem, et le fils de l\'homme sera livré aux grands prêtres et aux scribes, et ils le condamneront,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'et ils le livreront aux gentils pour qu\'ils le bafouent, le fustigent et le crucifient, et le troisième jour il ressuscitera. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Alors la mère des fils de Zébédée s\'approcha de lui avec ses fils, l\'adorant et sollicitant quelque chose de lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'mais il lui dit: « Que veux-tu? » Or elle dit: « Ordonne que mes deux fils, que voici, soient assis, l\'un à ta droite et l\'autre à ta gauche, dans ton royaume. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Mais Jésus répliqua: « Vous ne savez ce que vous demandez. Pouvez-vous boire la coupe que moi je dois boire? » Ils lui disent: « Nous le pouvons. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Il leur dit: « Vous boirez il est vrai ma coupe, mais pour ce qui est d\'être assis à ma droite ou à ma gauche, il ne dépend pas de moi de l\'accorder, sauf à ceux pour lesquels cela a été préparé par mon Père. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Ce que les dix ayant ouï, ils furent indignés contre les deux frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Mais Jésus les ayant appelés à lui, dit: « Vous savez que les chefs des nations les tyranniseront et que les grands les oppriment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Il n\'en est pas de même parmi vous. Mais celui qui voudra devenir grand parmi vous sera votre serviteur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'et que celui qui voudra être le premier de vous soit votre esclave.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'C\'est ainsi que le fils de l\'homme n\'est pas venu pour être servi, mais pour servir, et pour donner sa vie comme une rançon pour plusieurs. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Et, comme ils sortaient de Jéricho, une foule nombreuse le suivit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'et voici, deux aveugles assis sur le bord du chemin ayant appris que Jésus passait, s\'écrièrent: « Seigneur, aie pitié de nous, fils de David! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Or la foule leur fit des remontrances afin qu\'ils se tussent, mais ils s\'écrièrent de plus belle: « Seigneur, aie pitié de nous, fils de David! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Et Jésus s\'étant arrêté les appela et dit: « Que voulez-vous que je fasse pour vous? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Ils lui disent: « Seigneur, que nos yeux s\'ouvrent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Or Jésus, ému de compassion, toucha leurs yeux, et aussitôt ils recouvrèrent la vue et ils le suivirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Et quand ils approchèrent de Jérusalem, et qu\'ils furent arrivés à Bethphagé, sur la montagne des Oliviers, alors Jésus dépêcha deux disciples,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'en leur disant: « Allez dans le village qui est en face de vous, et vous trouverez aussitôt une ânesse attachée et un ânon avec elle; détachez-les et amenez-les-moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Et si quelqu\'un vous dit quelque chose, vous direz: Le Seigneur en a besoin; et aussitôt il les enverra. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Or, tout cela est advenu, afin que fût accompli ce dont il a été parlé par l\'entremise du prophète, lorsqu\'il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '« Dites à la fille de Sion: Voici, ton roi vient à toi, doux et monté sur un âne et sur un ânon, fils d\'une bête de somme. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Or, les disciples s\'en étant allés et ayant exécuté les ordres de Jésus');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'ramenèrent l\'ânesse et l\'ânon, et ils placèrent sur eux leurs manteaux, et il s\'assit dessus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Or, la plus grande partie de la foule étendit ses manteaux sur le chemin, tandis que d\'autres coupaient des branches aux arbres et les étendaient sur le chemin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Mais la foule qui le précédait et celle qui le suivait s\'écriait: « Hosanna au fils de David! Béni soit celui qui vient au nom du Seigneur! Hosanna dans les lieux très-hauts! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Et lorsqu\'il fut entré dans Jérusalem toute la ville fut en émoi, et elle disait: « Qui est celui-ci? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Or la foule disait: « Celui-ci, c\'est le prophète Jésus, qui est de Nazareth en Galilée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Et Jésus entra dans le temple, et il expulsa tous ceux qui vendaient et qui achetaient dans le temple, et il renversa les tables des changeurs, et les sièges de ceux qui vendaient les colombes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'et il leur dit: « Il est écrit: Ma maison sera appelée une maison de prière, mais vous, vous en faites une caverne de brigands. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Et des aveugles et des boiteux s\'approchèrent de lui dans le temple, et il les guérit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Mais les grands prêtres et les scribes, voyant les merveilles qu\'il avait faites et les enfants qui criaient dans le temple: « Hosanna au fils de David! » en furent indignés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'et ils lui dirent: « Entends-tu ce qu\'ils disent? » Mais Jésus leur dit: « Oui. N\'avez-vous jamais lu: De la bouche des petits enfants et des nourrissons Tu T\'es préparé une louange? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Et les ayant quittés, il sortit de la ville pour aller à Béthanie, et il y passa la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Or, le matin, comme il avait repris le chemin de la ville, il eut faim,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'et ayant vu un figuier sur le chemin il s\'en approcha et il n\'y trouva rien que des feuilles, et il lui dit: « Qu\'il ne provienne plus jamais de toi aucun fruit! » Et subitement le figuier sécha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Ce que les disciples ayant vu, ils s\'en étonnèrent en disant: « Comment ce figuier a-t-il subitement séché? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Mais Jésus leur répliqua: « En vérité je vous déclare que si vous aviez de la foi et que vous ne doutiez point, non seulement vous feriez ce qui a été fait au figuier, mais encore si vous disiez à cette montagne: « Déplace-toi et te jette dans la mer, » cela se ferait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Et tout ce que vous aurez demandé avec foi par la prière, vous le recevrez. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Et, lorsqu\'il fut arrivé dans le temple, les grands prêtres et les anciens du peuple s\'approchèrent de lui pendant qu\'il enseignait, en disant: « En vertu de quelle autorité-fais-tu ces choses, et qui est-ce qui t\'a donné cette autorité? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Mais Jésus leur répliqua: « Je vous adresserai de mon côté une seule question, et si vous y répondez, je vous répondrai à mon tour en vertu de quelle autorité je fais ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Le baptême de Jean d\'où venait-il? Du ciel ou des hommes? » Mais ils réfléchissaient en eux-mêmes et disaient:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, '« Si nous répondons: du ciel, il nous dira: Pourquoi donc ne l\'avez-vous pas cru? Tandis que si nous répondons: des hommes, nous avons à craindre la foule; car tous tiennent Jean pour un prophète. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Et ils répliquèrent à Jésus: « Nous ne savons. » Lui de son côté leur dit: « Moi non plus je ne vous dis pas en vertu de quelle autorité je fais ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Mais que vous en semble? Un homme avait deux enfants, et s\'étant approché du premier, il lui dit: « Mon enfant, va travailler aujourd\'hui dans ma vigne. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Or celui-ci répliqua: « Oui, Seigneur, » et il n\'y alla pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Puis s\'étant approché du second, il lui parla de même; or celui-ci répliqua: « Je ne veux pas, » mais plus tard, s\'étant repenti, il y alla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Lequel des deux a fait la volonté de son père? » Ils disent: « Le dernier. » Jésus leur dit: « En vérité, je vous déclare que les publicains et les prostituées entrent avant vous dans le royaume de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'car Jean est venu à vous, enseignant la justice, et vous ne l\'avez pas cru, tandis que les publicains et les prostituées l\'ont cru. Mais vous, qui avez vu cela, vous ne vous êtes pas même repentis plus tard pour le croire!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Écoutez une autre parabole: Il y avait un chef de famille qui planta une vigne, et qui l\'entoura d\'une clôture, et qui y creusa un pressoir, et qui construisit une tour; et il l\'afferma à des vignerons, et il s\'en alla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Mais, lorsque le moment de la récolte approcha, il dépêcha ses esclaves auprès des vignerons pour prendre sa récolte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Et les vignerons s\'étant saisis de ses esclaves battirent l\'un, tuèrent l\'autre, et lapidèrent le troisième.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Il dépêcha derechef d\'autres esclaves en plus grand nombre que les premiers, et ils les traitèrent de même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Mais à la fin, il leur dépêcha son fils, en se disant: Ils respecteront mon fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Mais les vignerons, à la vue du fils, se dirent: Celui-ci est l\'héritier, venez, tuons-le, et mettons-nous en possession de son héritage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Et s\'étant saisis de lui, ils le jetèrent hors de la vigne et le tuèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Eh bien! quand le propriétaire de la vigne sera venu, que fera-t-il à ces vignerons-là? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Ils lui dirent: « Il fera misérablement périr ces misérables, et il affermera la vigne à d\'autres vignerons, qui lui en remettront la récolte en sa saison. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Jésus leur dit: « N\'avez-vous jamais lu dans les écritures: La pierre que les constructeurs ont rejetée est celle qui est devenue le sommet de l\'angle; c\'est par la volonté du Seigneur qu\'elle l\'est devenue, et il est admirable nos yeux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'C\'est pourquoi je vous déclare que le royaume de Dieu vous sera enlevé et sera donné à une nation qui en produise les fruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Et celui qui sera tombé sur cette pierre-là sera fracassé, tandis que celui sur lequel elle sera tombée, elle le fera voler en éclats. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Et après avoir entendu ses paraboles, les grands prêtres et les pharisiens comprirent que c\'était d\'eux qu\'il parlait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'et, malgré leur désir de le faire arrêter, ils craignirent la foule, car on le tenait pour un prophète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Et reprenant la parole, Jésus leur parla derechef en paraboles, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, '« Le royaume des cieux ressemble à un roi qui fit des noces à son fils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'et il dépêcha ses esclaves pour mander ceux qui avaient été invités aux noces, et ils ne voulaient pas venir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Il dépêcha derechef d\'autres esclaves, en disant: « Dites aux invités: Voici, j\'ai préparé mon festin; mes taureaux et mes bêtes grasses sont tués, et tout est prêt; venez aux noces. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Mais eux n\'en ayant tenu compte s\'en allèrent, qui à son champ, et qui à son négoce,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'tandis que les autres ayant saisi les esclaves les maltraitèrent et les mirent à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Mais le roi en fut irrité, et ayant expédié ses armées il fit périr ces meurtriers et brûla leur ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Alors il dit à ses esclaves: « Les noces sont bien prêtes, mais les invités n\'en étaient pas dignes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'allez donc dans les carrefours des chemins, et tous ceux que vous trouverez, invitez-les aux noces. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Et ces esclaves s\'en étant allés sur les chemins réunirent tous ceux qu\'ils trouvèrent, méchants et bons, et la salle nuptiale fut remplie de convives.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Mais le roi étant entré pour voir les convives aperçut là un homme qui n\'était pas revêtu d\'un habit de noce,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'et il lui dit: « Camarade, comment es-tu entré ici, sans avoir un habit de noce? » Et l\'autre resta bouche close.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Alors le roi dit à ses serviteurs: « Après lui avoir lié les pieds et les mains, jetez-le dans les ténèbres extérieures. » Là sera le pleur et le grincement des dents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Il y a en effet beaucoup d\'appelés, mais peu d\'élus. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Alors les pharisiens s\'en étant allés tinrent conseil afin de le faire tomber dans le piège par un mot,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'et ils lui députent leurs disciples avec les Hérodiens pour lui dire: « Maître, nous savons que tu es véridique, et que tu enseignes avec vérité la voie et que tu ne fais pas acceptions de personnes, car tu ne regardes pas à l\'apparence des hommes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'dis-nous donc, que t\'en semble? Est-il permis ou non de payer l\'impôt à l\'empereur? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Mais Jésus, connaissant leur méchanceté, dit: « Pourquoi me mettez-vous à l\'épreuve? Hypocrites!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Montrez-moi la monnaie de l\'impôt. » Et ils lui présentèrent un denier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Et il leur dit: « De qui est cette effigie et cette légende? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Ils disent: « De l\'empereur. » Alors il leur dit: « Rendez donc à l\'empereur ce qui est à l\'empereur, et à Dieu ce qui est à Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Ce qu\'ayant ouï, ils furent émerveillés, et l\'ayant quitté ils s\'en allèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Ce jour-là vinrent à lui des sadducéens disant qu\'il n\'y a pas de résurrection, et ils l\'interrogèrent');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'en disant: « Maître, Moïse a dit: Si quelqu\'un vient à mourir sans avoir d\'enfants, son frère épousera sa femme à titre de beau-frère et il suscitera une postérité à son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Or, il y avait parmi nous sept frères: et le premier, après s\'être marié, mourut, et n\'ayant pas de postérité il laissa sa femme à son frère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'il en fut de même du second, et du troisième, et de tous les sept;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'après eux tous la femme mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Eh bien! lors de la résurrection, duquel des sept sera-t-elle femme? Car ils l\'ont tous possédée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Mais Jésus leur répliqua: « Vous vous égarez, parce que vous ne connaissez ni les écritures, ni la puissance de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'car, lors de la résurrection, ni les hommes ne prennent des femmes, ni les femmes des maris, mais ils sont comme des anges dans le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Or, quant à la résurrection des morts, n\'avez-vous pas lu ce dont Dieu vous a parlé lorsqu\'il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'Je suis le Dieu d\'Abraham, et le Dieu d\'Isaac, et le Dieu de Jacob? Il n\'est pas le Dieu des morts, mais des vivants. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Ce que la foule ayant ouï, elle était stupéfaite de son enseignement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Mais les pharisiens, ayant appris qu\'il avait fermé la bouche aux sadducéens, se réunirent au même lieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'et l\'un d\'entre eux, un légiste, lui demanda pour le mettre à l\'épreuve:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, '« Maître, quel est le grand commandement dans la loi? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Et il lui dit: « Tu aimeras le Seigneur ton Dieu de tout ton cœur, et de toute ton âme, et de toute ta pensée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'celui-ci est le grand et le premier commandement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'le second, semblablement: tu aimeras ton prochain comme toi-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'De ces deux commandements dépend la loi tout entière, ainsi que les prophètes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Mais les pharisiens se trouvant réunis, Jésus leur demanda:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, '« Que vous semble-t-il du Christ? De qui est-il fils? » Il lui disent: « De David. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Il leur dit: « Comment donc David étant inspiré l\'appelle-t-il seigneur, lorsqu\'il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '« le Seigneur a dit à mon seigneur: Assieds-toi à Ma droite, jusques à ce que J\'aie mis tes ennemis sous tes pieds?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Si donc David l\'appelle seigneur, comment est-il son fils? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Et personne ne pouvait lui répondre un mot, et dès ce jour-là nul n\'osa l\'interroger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Alors Jésus parla à la foule et à ses disciples,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'en disant: « Les scribes et les pharisiens sont assis sur la chaire de Moïse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'faites donc et observez toutes les choses qu\'ils vous disent, mais n\'agissez pas selon leurs propres œuvres; car ils disent et ne font pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'mais ils lient de lourds et intolérables fardeaux, et ils les placent sur les épaules des hommes, tandis qu\'eux-mêmes ne veulent pas les remuer du doigt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Mais ils font toutes leurs œuvres pour être vus des hommes; ils élargissent en effet leurs phylactères et agrandissent leurs franges;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'et ils aiment la première place dans les repas, et les premiers sièges dans les synagogues,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'et les salutations dans les places publiques, et à être appelés Rabbi par les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Mais pour vous, ne vous faites pas appeler Rabbi, car vous n\'avez qu\'un seul maître, tandis que tous vous êtes frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'Et n\'appelez personne sur la terre notre père, car vous n\'avez qu\'un seul Père, Celui du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Ne vous faites pas non plus appeler directeurs, car vous n\'avez qu\'un seul directeur, Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Mais le plus grand de vous sera votre serviteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Or, celui qui s\'élèvera sera abaissé, et celui qui s\'abaissera sera élevé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, '« Mais malheur à vous, scribes et pharisiens hypocrites, parce que vous fermez aux hommes le royaume des cieux; car vous n\'y entrez pas vous-mêmes, et vous n\'y laissez pas non plus entrer ceux qui veulent entrer. [');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Malheur à vous, scribes et pharisiens hypocrites, parce que vous dévorez les maisons des veuves, et que vous faites par dissimulation de longues prières; aussi recevrez-vous une punition d\'autant plus sévère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Malheur à vous, scribes et pharisiens hypocrites, parce que vous parcourez la mer et la terre pour faire un seul prosélyte, et lorsqu\'il l\'est devenu, vous en faites un fils de la géhenne deux fois plus que vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Malheur à vous, guides aveugles qui dites: « Celui qui aura juré par le sanctuaire, ce n\'est rien; mais celui qui aura juré par l\'or du sanctuaire est engagé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Insensés et aveugles! Qu\'est-ce qui est en effet le plus grand, l\'or, ou le sanctuaire qui a sanctifié l\'or?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Et: « Celui qui aura juré par l\'autel, ce n\'est rien; mais celui qui aura juré par l\'offrande qui est dessus est engagé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Insensés et aveugles! Qu\'est-ce qui est en effet le plus grand, l\'offrande, ou l\'autel qui sanctifie l\'offrande?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Celui donc qui a juré par l\'autel jure par lui et par tout ce qui est dessus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'et celui qui a juré par le sanctuaire jure par lui et par Celui qui l\'habite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'et celui qui a juré par le ciel jure par le trône de Dieu et par Celui qui est assis dessus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Malheur à vous, scribes et pharisiens hypocrites, parce que vous payez la dîme de la menthe, et de l\'aneth, et du cumin, et que vous avez laissé de côté ce qui a plus de poids dans la loi: la justice, et la miséricorde, et la fidélité; tandis que c\'est ces choses-ci qu\'il fallait pratiquer, sans toutefois laisser de côté celles-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Guides aveugles, qui filtrez le moucheron, mais qui avalez le chameau!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Malheur à vous, scribes et pharisiens hypocrites, parce que vous nettoyez le dehors de la coupe et du plat, tandis qu\'au dedans ils sont remplis de rapine et de crapule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Pharisien aveugle, nettoie premièrement l\'intérieur de la coupe et du plat, afin que le dehors aussi en devienne net.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Malheur à vous, scribes et pharisiens hypocrites, parce que vous ressemblez à des tombeaux recrépis, qui au dehors ont une belle apparence, tandis qu\'au dedans ils sont remplis des ossements des morts et de toute espèce d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'De même vous aussi vous paraissez extérieurement justes aux yeux des hommes, tandis qu\'au dedans vous êtes pleins d\'hypocrisie et d\'iniquité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Malheur à vous, scribes et pharisiens hypocrites, parce que vous bâtissez les tombeaux des prophètes, et que vous ornez les sépulcres des justes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'et que vous dites: « Si nous avions vécu à l\'époque de nos pères, nous n\'aurions pas versé avec eux le sang des prophètes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'En sorte que vous portez contre vous-mêmes le témoignage d\'être fils de ceux qui ont tué les prophètes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'et c\'est vous qui comblerez la mesure de vos pères!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, '« Serpents, engeance de vipères, comment échapperez-vous à la condamnation de la géhenne?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'C\'est pourquoi, voici, moi j\'envoie vers vous des prophètes et des sages et des scribes; il en est que vous tuerez et que vous crucifierez, et il en est que vous fouetterez dans vos synagogues et que vous poursuivrez de ville en ville;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'afin que retombe sur vous tout le sang juste répandu sur la terre, depuis le sang d\'Abel le juste jusques au sang de Zacharie fils de Barachie, que vous tuâtes entre le sanctuaire et l\'autel');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'En vérité je vous le déclare: tout cela retombera sur cette génération.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jérusalem, Jérusalem, qui tue les prophètes et qui lapide ceux qui lui sont envoyés, que de fois j\'ai voulu rassembler tes enfants, comme une poule rassemble ses poussins sous ses ailes, et vous ne l\'avez pas voulu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Voici, votre demeure vous est laissée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'car je vous le déclare: dès ce moment vous ne me verrez certainement plus jusques à ce que vous disiez: Béni soit celui qui vient au nom du Seigneur! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Et après être sorti du temple Jésus se remettait en chemin, et ses disciples s\'approchèrent pour lui montrer les édifices du temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Mais il leur répliqua: « Ne voyez-vous pas tout cela? En vérité je vous le déclare: il ne sera certainement pas laissé ici pierre sur pierre qui ne soit démolie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Or, pendant qu\'il était assis sur la montagne des Oliviers, les disciples s\'approchèrent de lui en particulier en disant: « Dis-nous, quand cela aura-t-il lieu? Et quel sera le signe de ton avènement et de la consommation du temps? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Et Jésus leur répliqua: « Prenez garde que personne ne vous égare;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'car beaucoup viendront en mon nom, disant: C\'est moi qui suis le Christ, et ils en égareront plusieurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Mais vous entendrez bientôt parler de guerres et de bruits de guerres; n\'ayez garde de vous en laisser troubler, car il faut que cela arrive; mais ce n\'est pas encore la fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'En effet, une nation s\'élèvera contre une nation, et un royaume contre un royaume, et il y aura ici et là des famines et des tremblements de terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Or tout cela est le commencement des douleurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Alors ils vous livreront pour être persécutés, et ils vous feront mourir, et vous serez haïs de toutes les nations à cause de mon nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'et alors plusieurs trébucheront, et ils se livreront les uns les autres, et ils se haïront les uns les autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Et beaucoup de faux prophètes surgiront, et ils en égareront plusieurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'Et à cause de l\'accroissement de l\'iniquité, la charité du plus grand nombre se refroidira;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'mais celui qui aura persévéré jusques à la fin, celui-là sera sauvé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Et cet évangile du royaume sera prêché dans la terre entière, pour servir de témoignage à toutes les nations, et alors viendra la fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, '« Ainsi donc, quand vous aurez vu « l\'œuvre abominable de la dévastation, » dont il a été parlé par l\'entremise de Daniel le prophète, établie dans un lieu saint (que le lecteur y réfléchisse),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'alors que ceux qui sont en Judée s\'enfuient dans les montagnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'que celui qui est sur le toit ne descende pas pour sortir quoi que ce soit de sa maison;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'et que celui qui est aux champs ne revienne pas en arrière pour prendre son manteau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Mais malheur à celles qui sont enceintes, et à celles qui allaitent en ces jours-la!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Or priez afin que votre fuite n\'ait pas lieu en hiver, ni un jour de sabbat;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'car il y aura alors une grande tribulation, telle qu\'il n\'y en a pas eu encore depuis le commencement du monde jusques à maintenant, et qu\'il n\'y en aura certainement jamais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'Et si ces jours-là n\'avaient été raccourcis, qui que ce soit n\'eut été sauvé; mais à cause des élus ces jours-là seront raccourcis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Alors si quelqu\'un vous dit: Voici, le Christ est ici, ou ici, ne le croyez pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'car il surgira de faux Christs et de faux prophètes, et ils feront de grands miracles et des prodiges, de manière à égarer, s\'il est possible, même les élus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Voici, je vous l\'ai prédit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Si donc ils vous disent: « voici, il est au désert, » ne vous y rendez pas; « voici, il est dans les chambres, » ne le croyez pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'car, tel l\'éclair sort de l\'orient et brille jusques au couchant, tel sera l\'avènement du fils de l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, '0ù que soit le cadavre, c\'est là que se rassembleront les aigles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Or, immédiatement après la tribulation de ces jours-là, le soleil s\'obscurcira, et la lune ne donnera pas sa lumière, et les astres tomberont du ciel, et les puissances des cieux seront ébranlées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Et alors paraîtra le signe du fils de l\'homme dans le ciel, et alors se lamenteront toutes les tribus de la terre, et elles verront le fils de l\'homme venant sur les nuées du ciel avec beaucoup de puissance et de gloire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'et il enverra ses anges avec un grand bruit de trompette, et ils rassembleront ses élus des quatre vents, d\'une extrémité des cieux jusqu\'à leur autre extrémité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Or, instruisez-vous par cette comparaison tirée du figuier: Lorsque ses branches commencent à se ramollir et qu\'il pousse ses feuilles, vous savez que l\'été est proche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'De même vous aussi, lorsque vous aurez vu toutes ces choses, sachez qu\'il est proche, qu\'il est à la porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'En vérité je vous déclare que cette génération ne disparaîtra certainement point jusqu\'à ce que toutes ces choses se soient réalisées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Le ciel et la terre passeront, mais mes paroles ne passeront certainement point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Or, quant à ce jour-là et à l\'heure, personne n\'en sait rien, ni les anges des cieux, ni le Fils, mais le Père seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Car telle fut l\'époque de Noé, tel sera l\'avènement du fils de l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'En effet, de même qu\'en ces jours-là qui précédèrent le déluge on mangeait et on buvait, que les hommes prenaient des femmes et les femmes des maris, jusques au jour où Noé entra dans l\'arche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'et qu\'ils ne s\'avisèrent de rien, jusques à ce que survint le déluge qui les enleva tous, tel sera l\'avènement du fils de l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Alors deux hommes seront dans les champs, l\'un est pris et l\'autre laissé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'deux femmes moudront à la meule, l\'une est prise et l\'autre laissée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Veillez donc, car vous ne savez pas quel jour votre maître doit venir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Or, sachez ceci, c\'est ce que, si le chef de famille avait su à quelle veille devait venir le voleur, il aurait veillé et n\'aurait pas laissé forcer sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'C\'est pourquoi vous aussi tenez-vous prêts, car le Fils de l\'homme doit venir à l\'heure dont vous ne vous doutez pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Quel est, je vous prie, l\'esclave fidèle et prudent que le maître a mis à la tête de ses gens, pour leur donner leur nourriture à propos?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Heureux cet esclave que son maître, à son arrivée, trouvera agissant de la sorte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'en vérité je vous déclare qu\'il le mettra à la tête de tous ses biens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Mais si ce mauvais esclave se dit en son cœur: « Mon maître tarde, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'et qu\'il se mette à battre les esclaves qui servent avec lui, tandis qu\'il mange et boit avec les ivrognes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'le maître de cet esclave arrivera le jour où il ne s\'y attend pas, et à l\'heure qu\'il ne connaît pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'et il le pourfendra et lui assignera son lot parmi les hypocrites; c\'est là que sera le pleur et le grincement des dents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Alors le royaume des cieux ressemblera à dix vierges qui, après avoir pris leurs lampes, sortirent à la rencontre de l\'époux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Or cinq d\'entre elles étaient étourdies, et cinq étaient prudentes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'En effet les étourdies, après avoir pris leurs lampes, ne prirent pas d\'huile avec elles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'tandis que les prudentes prirent de l\'huile dans leurs burettes avec leurs lampes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Mais comme l\'époux tardait, toutes s\'assoupirent, et elles dormaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Or, au milieu de la nuit, un cri se fit entendre: « Voici l\'époux! sortez à sa rencontre! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Alors toutes ces vierges s\'éveillèrent et arrangèrent leurs lampes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Or les étourdies dirent aux prudentes: « Donnez-nous de votre huile, car nos lampes sont éteintes; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'mais les prudentes répliquèrent: « Jamais il n\'y en aura assez pour nous et pour vous; allez plutôt chez ceux qui en vendent et achetez-en pour vous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Or, pendant qu\'elles allaient en acheter, survint l\'époux, et celles qui étaient prêtes entrèrent avec lui à la noce, et la porte fut fermée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Mais plus tard surviennent aussi les autres vierges disant: « Seigneur, Seigneur, ouvre-nous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Mais il leur répliqua: « En vérité je vous le déclare, je ne vous connais point. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Veillez donc, car vous ne connaissez ni le jour, ni l\'heure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'De même en effet qu\'un homme partant pour un voyage appela ses esclaves, et leur remit ses biens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'et qu\'à l\'un il donna cinq talents, et à un autre deux, et à un troisième un, à chacun selon sa capacité particulière, et qu\'il partit pour son voyage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'aussitôt celui qui avait reçu les cinq talents alla les faire valoir, et il en gagna cinq autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'De même aussi celui qui avait reçu les deux en gagna deux autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Mais celui qui n\'en avait reçu qu\'un s\'en alla faire un creux en terre, et y cacha l\'argent de son maître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Or, après un long espace de temps, le maître de ces esclaves revient et leur fait rendre compte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Et celui qui avait reçu les cinq talents s\'étant approché apporta cinq autres talents, en disant: « Seigneur, tu m\'as remis cinq talents, regarde, j\'ai gagné cinq autres talents. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Son maître lui dit: « Bien, bon et fidèle esclave, tu as été fidèle pour peu de chose, je te mettrai à la tête de beaucoup. Entre dans la joie de ton maître. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Celui qui avait reçu les deux talents s\'étant aussi approché dit: « Seigneur, tu m\'as remis deux talents, regarde, j\'ai gagné deux autres talents. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Son maître lui dit: « Bien, bon et fidèle esclave, tu as été fidèle pour peu de chose, je te mettrai à la tête de beaucoup. Entre dans la joie de ton maître. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Mais celui qui avait reçu le seul talent s\'étant aussi approché dit: « Seigneur, je te connaissais pour être un homme dur, moissonnant où tu n\'as pas semé, et serrant le grain de là où tu n\'as pas vanné,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'et tout craintif j\'ai été cacher ton talent dans la terre, regarde, tu récupères ce qui est à toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Mais son maître lui répliqua: « Méchant et paresseux esclave, tu savais que je moissonne où je n\'ai pas semé et que je serre le grain de là où je n\'ai pas vanné?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Il te fallait donc porter mon argent aux banquiers, et à mon retour j\'aurais retiré ce qui était à moi avec l\'intérêt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Enlevez-lui donc le talent et donnez-le à celui; qui a les dix talents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Car à quiconque a il sera donné, et il regorgera; mais quant à celui qui n\'a pas, même ce qu\'il a lui sera enlevé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Et jetez cet esclave inutile dans les ténèbres extérieures; c\'est là que sera le pleur et le grincement des dents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Or, quand le fils de l\'homme viendra dans sa gloire, et tous les anges avec lui, alors il s\'assiéra sur le trône de sa gloire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'et toutes les nations seront rassemblées devant lui, et il les séparera les unes d\'avec les autres, comme le berger sépare les brebis d\'avec les chevreaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'et il placera les brebis à sa droite et les chevreaux à sa gauche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Alors le roi dira à ceux qui seront à sa droite: « Venez, vous qui êtes bénis de mon Père, prenez possession du royaume qui vous a été préparé dès la fondation du monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Car j\'ai eu faim, et vous m\'avez donné à manger; j\'ai eu soif, et vous m\'avez donné à boire; j\'étais étranger, et vous m\'avez recueilli;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'nu, et vous m\'avez vêtu; j\'ai été malade, et vous m\'avez visité; j\'étais en prison, et vous êtes venus auprès de moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Alors les justes lui répliqueront: « Seigneur, quand t\'avons-nous vu avoir faim, et t\'avons-nous nourri? Ou avoir soif, et t\'avons-nous donné à boire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Mais quand t\'avons-nous vu étranger, et t\'avons-nous recueilli? Ou nu, et t\'avons-nous vêtu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Et quand t\'avons-nous vu malade ou en prison, et sommes-nous venus auprès de toi? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Et le roi leur répliquera: « En vérité je vous le déclare: en tant que vous l\'avez fait pour un seul de ces tout petits, vous l\'avez fait pour moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Alors il dira aussi à ceux qui seront à gauche: « Allez loin de moi, maudits, dans le feu éternel qui a été préparé pour le diable et pour ses anges!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Car j\'ai eu faim et vous ne m\'avez pas donné à manger; et j\'ai eu soif, et vous ne m\'avez pas donné à boire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'j\'étais étranger, et vous ne m\'avez pas recueilli; nu, et vous ne m\'avez pas vêtu; malade et en prison, et vous ne m\'avez pas visité. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Alors eux aussi répliqueront: « Seigneur, quand t\'avons-nous vu avoir faim ou avoir soif, ou étranger, ou nu, ou malade, ou en prison, et ne t\'avons-nous pas servi? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Alors il leur répliquera: « En vérité je vous le déclare: en tant que vous ne l\'avez pas fait pour un seul de ces tout petits, vous ne l\'avez pas non plus fait pour moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Et ceux-ci s\'en iront au châtiment éternel, mais les justes à la vie éternelle. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Et il advint, lorsque Jésus eut terminé tous ces discours, qu\'il dit à ses disciples:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, '« Vous savez que dans deux jours a lieu la Pâque, et que le fils de l\'homme doit être livré pour être crucifié. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Alors les grands prêtres et les anciens du peuple se rassemblèrent dans la cour du grand prêtre appelé Caiaphas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'et ils délibérèrent en commun, afin de se saisir par ruse de Jésus et de le mettre à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Mais ils disaient: « Que ce ne soit pas pendant la fête, afin qu\'il n\'y ait pas d\'émeute parmi le peuple. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Or Jésus s\'étant trouvé à Béthanie dans la maison de Simon le lépreux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'une femme s\'approcha de lui tenant une fiole d\'albâtre qui renfermait un parfum de grand prix, et elle le versait sur sa tête pendant qu\'il était à table.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Ce que les disciples ayant vu ils s\'en indignèrent en disant: « Pourquoi cette profusion?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Car il pouvait être vendu très cher, et être donné aux pauvres. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Mais Jésus l\'ayant su, leur dit: « Pourquoi faites-vous de la peine à cette femme? Car elle a accompli une bonne œuvre envers moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'en effet vous devez toujours avoir les pauvres avec vous, mais moi, vous ne devez pas m\'avoir toujours;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'car celle-ci, en jetant ce parfum sur mon corps, l\'a fait en vue de mes funérailles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Mais en vérité je vous le déclare: où que cet évangile soit prêché dans le monde entier, on parlera aussi de ce qu\'elle a fait, en mémoire d\'elle. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Alors un des douze, appelé Judas Iscariote, s\'étant rendu auprès des grands prêtres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'leur dit: « Que voulez-vous me donner, et de mon côté je vous le livrerai? » Et ils lui pesèrent trente pièces d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Et dès lors il cherchait une bonne occasion pour le livrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Or le premier jour de la fête des pains sans levain les disciples vinrent à Jésus en disant: « Où veux-tu que nous fassions les préparatifs pour que tu manges la pâque? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Et il dit: « Allez dans la ville auprès d\'un tel, et dites-lui: « Le maître dit: Mon temps est proche; je vais faire chez toi la pâque avec mes disciples. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Et les disciples firent ce que Jésus leur avait prescrit, et ils préparèrent la pâque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Or, quand le soir fut venu, il était à table avec les douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'et pendant qu\'ils mangeaient, il dit: « En vérité je vous déclare que l\'un d\'entre vous me livrera. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Et vivement attristés ils se mirent chacun à lui dire: « Est-ce que c\'est moi, Seigneur? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Mais il répliqua: « Celui qui a trempé avec moi la main dans le plat, celui-là me livrera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Le Fils de l\'homme s\'en va, il est vrai, selon ce qui a été écrit de lui, mais malheur à cet homme par qui le Fils de l\'homme est livré; il eût été bon pour lui que cet homme-là ne fût pas né. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Et Judas qui le livrait répliqua: « Est-ce que c\'est moi, Rabbi? » Il lui dit: « Tu l\'as dit. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Or, pendant qu\'ils mangeaient, Jésus, ayant pris du pain et prononcé une bénédiction, le rompit, et après l\'avoir donné aux disciples, il dit: « Prenez, mangez; ceci est mon corps. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Et, ayant pris une coupe et rendu grâces, il la leur donna, en disant: « Buvez-en tous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'car ceci est mon sang, celui de l\'alliance, qui est versé pour plusieurs, en vue de la rémission des péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Mais je vous le déclare: désormais je ne boirai certainement plus de ce produit de la vigne, jusqu\'à ce jour où j\'en boirai du nouveau avec vous dans le royaume de mon Père. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Et après avoir chanté, ils sortirent pour se rendre à la montagne des Oliviers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Alors Jésus leur dit: « Vous trébucherez tous à cause de moi cette nuit-ci; car il est écrit: Je frapperai le berger et les brebis du troupeau seront dispersées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Mais après être ressuscité, je vous précéderai en Galilée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Or Pierre lui répliqua: « Si tous viennent à trébucher à cause de toi, pour moi je ne trébucherai jamais. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jésus lui dit: « En vérité je te déclare que cette nuit-ci, avant que le coq ait chanté, tu me renieras trois fois. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Pierre lui dit: « Quand il me faudrait mourir avec toi, je ne te renierai certainement pas. » Tous les disciples aussi parlèrent de même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Alors Jésus arrive avec eux dans un lieu appelé Gethsémani, et il dit aux disciples: « Asseyez-vous ici, jusques à ce que, après m\'être rendu là, j\'aie prié. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Et ayant pris avec lui Pierre, et les deux fils de Zébédée, il commença à être triste et abattu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Alors il leur dit: « Mon âme est triste jusqu\'à la mort; demeurez ici, et veillez avec moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Et s\'étant un peu avancé il se prosterna le visage contre terre, priant et disant: « Mon Père, s\'il est possible, que cette coupe s\'éloigne de moi. Toutefois non pas comme moi je veux, mais comme Toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Et il vient vers les disciples, et il les trouve endormis, et il dit à Pierre: « Ainsi vous n\'avez pas pu veiller une seule heure avec moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Veillez et priez, afin que vous n\'entriez pas en tentation; l\'esprit, il est vrai, est plein d\'élan, mais la chair est faible. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'S\'étant retiré derechef une seconde fois, il fit cette prière: « Mon Père, si elle ne peut pas s\'éloigner sans que je la boive, que Ta volonté se fasse. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Et étant revenu, il les retrouva endormis; leurs yeux en effet s\'étaient appesantis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Et les ayant laissés, il s\'en alla derechef, et pria une troisième fois, en répétant encore les mêmes paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Alors il revient vers les disciples et leur dit: « Dormez désormais et reposez-vous; car voici, l\'heure s\'approche, et le fils de l\'homme va être livré aux mains des pécheurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Levez-vous, allons; voici, celui qui me livre s\'approche. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Et pendant qu\'il parlait encore, voici, Judas l\'un des douze survint, et avec lui une foule nombreuse armée d\'épées et de bâtons, envoyée par les grands prêtres et les anciens du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Or, celui qui le livrait leur avait donné une indication en disant: « Celui que j\'embrasserai, c\'est lui; saisissez-le. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Et s\'étant aussitôt approché de Jésus il dit: « Salut, Rabbi, » et il lui donna un tendre baiser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Mais Jésus lui dit: « Camarade, sois à ce qui t\'amène! » Alors s\'étant approchés ils mirent la main sur Jésus et se saisirent de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Et voici, l\'un de ceux qui étaient avec lui ayant étendu la main tira son épée, et ayant frappé l\'esclave du grand prêtre, il lui enleva l\'oreille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Alors Jésus lui dit: « Remets ton épée à sa place; car tous ceux qui auront pris l\'épée périront par l\'épée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'ou bien t\'imagines-tu que je ne puis invoquer mon Père, et Il me fournira tout de suite plus de douze légions d\'anges?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Mais dans ce cas comment les écritures se fussent-elles accomplies? Car il faut qu\'il en advienne ainsi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'En ce moment-là Jésus dit à la foule: « Vous êtes sortis comme contre un brigand, avec des épées et des bâtons, pour me prendre; tous les jours j\'étais assis dans le temple, occupé à enseigner, et vous ne vous êtes pas saisis de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Mais tout cela est advenu, afin que les écritures des prophètes fussent accomplies. » Alors tous ses disciples l\'ayant abandonné s\'enfuirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Mais ceux qui s\'étaient saisis de Jésus l\'amenèrent chez Caiaphas le grand prêtre, où les scribes et les anciens étaient rassemblés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Or Pierre le suivait de loin jusqu\'à la cour du grand prêtre, et y étant entré, il se tenait assis avec les valets pour voir la fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Mais les grands prêtres et le sanhédrin tout entier cherchaient un faux témoignage contre Jésus, afin de le faire mourir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'et ils n\'en trouvèrent pas, quoiqu\'il se fût présenté beaucoup de faux témoins. Mais à la fin il se présenta deux faux témoins');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'qui dirent: « Celui-ci a dit: « Je peux détruire le sanctuaire de Dieu, et le rebâtir en trois jours. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Et le grand prêtre s\'étant levé, lui dit: « Est-ce que tu ne réponds rien à ce dont ceux-ci témoignent contre toi? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Mais Jésus gardait le silence. Et le grand prêtre lui dit: « Je t\'adjure, au nom du Dieu vivant, de nous dire si tu es le Christ, le fils de Dieu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jésus lui dit: « C\'est toi qui l\'as dit. D\'ailleurs je vous le déclare: dès à présent vous verrez le fils de l\'homme assis à la droite de la Puissance, et venant sur les nuées du ciel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Alors le grand prêtre déchira ses vêtements en disant: « Il a blasphémé. Qu\'avons-nous encore besoin de témoins? Voyez; maintenant vous venez d\'entendre le blasphème.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Que vous en semble? » Et eux répliquèrent: « Il mérite la mort. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Alors ils lui crachèrent au visage, et ils le souffletèrent, et il y en eut qui le fustigèrent');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'en disant: « Prophétise-nous, Christ, qui est celui qui t\'a frappé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Cependant Pierre se tenait assis dehors dans la cour, et une servante s\'approcha de lui en disant: Toi aussi, tu étais avec Jésus le Galiléen. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Mais il le nia devant tous en disant: « J\'ignore de quoi tu parles. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Et une autre le vit comme il se retirait sous le porche, et elle dit à ceux qui étaient là: « Celui-ci était avec Jésus le Nazoréen. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Et il nia derechef en disant avec serment: « Je ne connais pas cet homme. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Et peu de temps après, ceux qui étaient là s\'étant approchés dirent à Pierre: « Vraiment, tu es aussi des leurs, car ton langage encore te fait reconnaître. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Alors il se mit à proférer des imprécations et à dire: « Je jure que je ne connais pas cet homme. » Et aussitôt un coq chanta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Et Pierre se souvint de la parole que Jésus avait dite: « Avant que le coq ait chanté tu m\'auras renié trois fois. » Et étant sorti, il pleura amèrement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Mais lorsque le matin fut venu, tous les grands prêtres et les anciens du peuple tinrent conseil contre Jésus, sur la manière de le faire mourir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'et, après l\'avoir enchaîné, ils l\'emmenèrent, et ils le livrèrent à Pilate, le gouverneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Alors Judas qui l\'avait livré, voyant qu\'il était condamné, fut saisi de repentir, et il rapporta les trente pièces d\'argent aux grands prêtres et aux anciens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'en disant: « J\'ai péché en livrant un sang innocent. » Mais eux lui dirent: « Qu\'est-ce que cela nous fait? Cela te regarde. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Et ayant lancé les pièces d\'argent dans le sanctuaire, il se retira et alla se pendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Mais les grands prêtres ayant pris les pièces d\'argent dirent: « Il n\'est pas permis de les jeter dans le corban, puisqu\'elles sont le prix du sang. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Or ayant tenu conseil, ils achetèrent avec cet argent le champ du potier, pour servir de sépulture aux étrangers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'C\'est pourquoi ce champ-là a été appelé, jusques à aujourd\'hui, champ du sang. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Alors fut accompli ce dont il a été parlé par l\'entremise de Jérémie le prophète, lorsqu\'il dit: « Et ils ont pris les trente pièces d\'argent, la valeur de celui qui a été évalué, qu\'ils ont évalué d\'entre les fils d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'et ils les ont données pour le champ du potier, comme le Seigneur me l\'avait prescrit. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Cependant Jésus comparut devant le gouverneur, et le gouverneur l\'interrogea en disant: « Es-tu le roi des Juifs? » Or Jésus lui dit: « C\'est toi qui le dis. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Et pendant qu\'il était accusé par les grands prêtres et les anciens, il ne répondait rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Alors Pilate lui dit: « N\'entends-tu pas tout ce dont ils témoignent contre toi? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Et il ne lui répondit pas même un seul mot, en sorte que le gouverneur était tout émerveillé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Or le gouverneur avait coutume, lors d\'une fête, d\'accorder à la foule l\'élargissement d\'un prisonnier, celui qu\'elle préférait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Or ils détenaient alors un prisonnier fameux, appelé Barabbas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Lors donc qu\'ils furent rassemblés, Pilate leur dit: « Lequel voulez-vous que je vous élargisse, Barabbas ou Jésus qui est appelé Christ? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Car il savait que c\'était par jalousie qu\'ils l\'avaient livré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Or pendant qu\'il siégeait sur le tribunal, sa femme lui fit dire: « Qu\'il ne se passe rien entre toi et ce juste; car j\'ai beaucoup souffert aujourd\'hui dans un rêve à son sujet. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Cependant les grands prêtres et les anciens gagnèrent la foule, afin qu\'elle réclamât Barabbas et sacrifiât Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Or le gouverneur, reprenant la parole, leur dit: « Lequel des deux voulez-vous que je vous élargisse? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Et ils dirent: « Barabbas. » Pilate leur dit: « Que ferai-je donc de Jésus qui est appelé Christ? » Ils dirent tous: « Qu\'il soit crucifié! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Mais il dit: « Eh! quel mal a-t-il fait? » Mais eux s\'écriaient de plus belle: « Qu\'il soit crucifié! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Or Pilate, ayant vu qu\'il n\'obtenait rien, mais que le tumulte allait croissant, prit de l\'eau et se lava les mains en présence de la foule, en disant: « Je suis innocent de ce sang; cela vous regarde. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Et tout le peuple répliqua: « Son sang soit sur nous et sur nos enfants! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Alors il leur accorda l\'élargissement de Barabbas, et après avoir fait flageller Jésus, il le livra afin qu\'il fût crucifié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Alors les soldats du gouverneur, ayant conduit Jésus dans le prétoire, réunirent autour de lui toute la cohorte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Et après l\'avoir rhabillé, ils le revêtirent d\'un manteau militaire, de couleur écarlate;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'et ayant tressé une couronne avec des épines ils lui en ceignirent la tête, et ils lui mirent un roseau dans la main droite; et s\'étant agenouillés devant lui, ils le bafouèrent en disant: « Salut, roi des Juifs! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'Et après avoir craché sur lui, ils prirent le roseau et ils le frappaient à la tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Et quand ils l\'eurent bafoué, ils le dépouillèrent du manteau militaire et le revêtirent de ses propres vêtements, et ils l\'emmenèrent pour le crucifier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Or, comme ils sortaient, ils rencontrèrent un homme de Cyrène, nommé Simon; ils le mirent en réquisition pour porter sa croix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Et lorsqu\'ils furent arrivés à l\'endroit qui est appelé Golgotha (ce qui signifie endroit dit du crâne),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'ils lui donnèrent à boire du vin mêlé de fiel; et après l\'avoir goûté, il ne voulut pas le boire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Or, quand ils l\'eurent crucifié, ils se partagèrent ses vêtements, après avoir tiré au sort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'et se tenant assis, ils le surveillaient là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Et ils placèrent au-dessus de sa tête sa sentence où était écrit: « Celui-ci est Jésus, le roi des juifs. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Alors sont crucifiés avec lui deux brigands, un à droite et un à gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Cependant les passants l\'injuriaient, en branlant la tête,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'et en disant: « Ô toi qui détruis le sanctuaire, et qui le rebâtis en trois jours, sauve-toi toi-même! Si tu es fils de Dieu, descends de la croix. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'De même aussi les grands prêtres, le bafouant avec les scribes et les anciens, disaient:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, '« Il en a sauvé d\'autres, il ne peut se sauver lui-même! Il est roi d\'Israël! Qu\'il descende maintenant de la croix, et nous croirons en lui!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Il s\'est confié en Dieu! Qu\'il le délivre maintenant, s\'il veut; car il a dit: Je suis Fils de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Et les brigands qui avaient été crucifiés avec lui l\'insultaient aussi de la même manière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, '« Cependant depuis la sixième heure, des ténèbres survinrent sur toute la terre jusques à la neuvième heure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Mais vers la neuvième heure Jésus s\'écria en jetant un grand cri: « Éloï! Éloï! Lema sabactani? » Ce qui signifie: « Mon Dieu, mon Dieu, pourquoi m\'as-Tu abandonné? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Mais quelques-uns des assistants l\'ayant entendu, disaient: « Il appelle Élie, celui-ci! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Et aussitôt l\'un d\'entre eux, étant accouru, prit une éponge, et après l\'avoir remplie de vinaigre et fixée à un roseau, il lui donnait à boire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Mais les autres dirent: « Laisse-nous voir si Élie vient le sauver! » Et un autre ayant pris une lance lui perça le flanc, et il en sortit de l\'eau et du sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Mais Jésus, après avoir derechef jeté un grand cri, rendit l\'esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'Et voici, le rideau du sanctuaire se déchira en deux du haut en bas, et la terre trembla, et les rochers se fendirent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'et les sépulcres s\'ouvrirent, et beaucoup de corps des saints qui étaient morts ressuscitèrent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'et étant sortis de leurs sépulcres après sa résurrection ils entrèrent dans la ville sainte, et apparurent à plusieurs personnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Cependant le centurion, et ceux qui avec lui surveillaient Jésus, ayant vu le tremblement de terre et ce qui se passait, furent dans une grande crainte, et ils disaient: « Vraiment, celui-ci était fils de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Or il y avait là plusieurs femmes qui regardaient de loin, lesquelles avaient suivi Jésus depuis la Galilée en le servant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Parmi elles se trouvait Marie la Magdalène, et Marie la mère de Jacques et de José, et la mère des fils de Zébédée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Or, quand le soir fut venu, arriva un homme riche d\'Arimathée nommé Joseph, lequel avait été aussi disciple de Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Cet homme s\'étant rendu auprès de Pilate, réclama le corps de Jésus; alors Pilate ordonna de le remettre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Et Joseph ayant pris le corps, l\'enveloppa dans un linceul blanc,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'et il le plaça dans son propre sépulcre neuf, qu\'il avait fait tailler dans le roc, et après avoir roulé une grande pierre contre l\'entrée du sépulcre, il s\'en alla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Or il y avait là Marie la Magdalène et l\'autre Marie, assises en face du tombeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Mais le lendemain, qui suit la préparation, les grands prêtres et les pharisiens se réunirent auprès de Pilate,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'en disant: « Seigneur, nous nous sommes souvenus que cet imposteur a dit, pendant qu\'il vivait encore: « Au bout de trois jours je dois ressusciter. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Ordonne donc que le tombeau soit protégé jusques au troisième jour, de peur que les disciples ne viennent le dérober, et ne disent au peuple: Il est ressuscité des morts; et cette nouvelle imposture sera pire que la première. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilate leur dit: « Prenez une garde; allez, protégez-le comme vous l\'entendez. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Or s\'en étant allés, ils mirent le tombeau, après avoir scellé la pierre, sous la protection de la garde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Or, après le sabbat, comme le premier jour de la semaine commençait à poindre, Marie la Magdalène et l\'autre Marie vinrent voir le tombeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Et voici, il se fit un grand tremblement de terre; car un ange du Seigneur, étant descendu du ciel et s\'étant approché, fit rouler la pierre, et il se tenait assis dessus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'or son aspect était semblable à un éclair, et son vêtement était blanc comme neige.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Mais de la crainte qu\'ils en eurent les surveillants devinrent tout tremblants et comme morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Mais prenant la parole l\'ange dit aux femmes: « Pour vous, ne craignez point, car je sais que vous cherchez Jésus qui a été crucifié;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'il n\'est pas ici, car il est ressuscité comme il l\'a dit. Venez voir l\'endroit où il était couché;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'puis allez promptement dire à ses disciples: Il est ressuscité des morts; et voici, il vous devance en Galilée, c\'est là que vous le verrez. Voici, je vous l\'ai dit. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Et s\'étant promptement éloignées du sépulcre avec crainte et grande joie, elles coururent porter cette nouvelle à ses disciples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Et voici, Jésus vint à leur rencontre en disant: « Salut. » Or s\'étant approchées, elles saisirent ses pieds et l\'adorèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Alors Jésus leur dit: « Ne craignez point. Allez porter cette nouvelle à mes frères, afin qu\'ils partent pour la Galilée, et c\'est là qu\'ils me verront. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Or, pendant qu\'elles étaient en chemin, voici, quelques hommes de la garde s\'étant rendus à la ville racontèrent aux grands prêtres tout ce qui s\'était passé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Et s\'étant réunis avec les anciens et ayant tenu conseil, ils donnèrent beaucoup d\'argent aux soldats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'en disant: « Dites: ses disciples étant venus de nuit l\'ont dérobé pendant que nous dormions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'Et si le gouverneur en entend parler, nous le gagnerons, et nous vous épargnerons tout souci. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Or ayant pris l\'argent ils firent comme ils avaient été endoctrinés, et ce bruit s\'est répandu parmi les Juifs jusques à aujourd\'hui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Cependant les onze disciples se rendirent en Galilée sur la montagne, à l\'endroit que Jésus leur avait fixé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'et l\'ayant vu ils l\'adorèrent; mais il y en eut qui doutèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Et Jésus s\'étant approché s\'adressa à eux en disant: « Toute autorité m\'a été donnée au ciel et sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Allez donc instruire toutes les nations, après les avoir baptisées au nom du Père et du Fils et du Saint-Esprit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'en leur enseignant à observer tout ce que je vous ai prescrit. Et voici, moi, je suis avec vous tous les jours, jusques à la consommation du temps. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Commencement de l\'évangile de Jésus-Christ fils de Dieu:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Selon qu\'il est écrit dans le prophète: « Voici, J\'envoie devant toi Mon messager, lequel frayera ton chemin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Voix d\'un crieur dans le désert: Préparez le chemin du Seigneur, redressez Ses sentiers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Jean le baptiseur apparut dans le désert, prêchant un baptême de repentance pour la rémission des péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Et tout le pays de Judée et tous les Hiérosolymitains se portaient vers lui, et ils se faisaient baptiser par lui dans le fleuve du Jourdain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Et Jean était vêtu de poils de chameau, et d\'une ceinture de cuir autour des reins, et il se nourrissait de sauterelles et de miel sauvage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Et il prêchait en disant: « Il vient après moi, celui qui est plus puissant que moi, et je ne suis pas digne de délier en me baissant la courroie de ses sandales;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'pour moi je vous ai baptisés d\'eau, mais lui vous baptisera d\'esprit saint. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Il advint en ce temps-là que Jésus vint de Nazaret de Galilée, et se fit baptiser dans le Jourdain par Jean.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Et au moment où il sortait de l\'eau il vit les cieux s\'entr\'ouvrir et l\'esprit comme une colombe descendre vers lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'et une voix vint des cieux: « Tu es Mon fils bien-aimé, en toi J\'ai pris plaisir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Et aussitôt l\'esprit le pousse au désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Et il était dans le désert pendant quarante jours tenté par Satan, et il était avec les bêtes, et les anges le servaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Et après que Jean eut été livré, Jésus vint en Galilée, prêchant l\'évangile de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'et disant: « Le temps est accompli, et le royaume de Dieu s\'approche; repentez-vous et croyez à l\'évangile. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Et en passant le long de la mer de Galilée il vit Simon, et André le frère de Simon, qui pêchaient au filet dans la mer, car ils étaient pêcheurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'et Jésus leur dit: « Marchez après moi, et je vous ferai devenir des pêcheurs d\'hommes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Et ayant aussitôt quitté leurs filets, ils le suivaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Et ayant un peu continué sa route, il vit Jacques le fils de Zébédée et Jean son frère, qui, eux aussi arrangeaient, leurs filets dans leur barque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'Et aussitôt il les appela; et ayant laissé leur père Zébédée dans la barque avec les mercenaires, ils s\'en allèrent après, lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Et il entrait à Capharnaoum, et étant aussitôt entré le jour du sabbat dans la synagogue; il enseignait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'et ils étaient stupéfaits de son enseignement, car il les enseignait comme ayant autorité, et non pas comme les scribes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Et il se trouvait aussitôt dans leur synagogue un homme possédé d\'un esprit impur, et il s\'écria:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, '« Que nous veux-tu, toi aussi, Jésus Nazarénien? Es-tu venu pour nous faire périr? Je sais qui tu es: le saint de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Et Jésus le réprimanda, en-disant: « Tais-toi, et sors de lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Et l\'impur, après l\'avoir jeté en de violentes convulsions et avoir poussé de grands cris, sortit de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Et ils étaient tous dans l\'épouvante, en sorte qu\'ils discutaient en disant: « Qu\'est-ce que ceci? Enseignement étrange! Il commande avec autorité même aux esprits impurs, et ils lui obéissent! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Et sa renommée se répandit aussitôt de tous côtés, dans toute la contrée voisine de la Galilée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Et aussitôt étant sorti de la synagogue, il entra dans la maison de Simon et d\'André avec Jacques et Jean.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Or la belle-mère de Simon était couchée ayant la fièvre; et aussitôt ils lui parlent d\'elle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'et s\'étant approché il la fit lever en la prenant par la main; et la fièvre la quitta, et elle les servait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Or, quand le soir fut venu, lorsque le soleil fut couché, on lui apportait tous les malades et les démoniaques;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'et la ville entière était rassemblée devant la porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Et il guérit plusieurs malades atteints de diverses maladies, et il chassa plusieurs démons, et il ne permettait pas aux démons de parler, parce qu\'ils savaient qu\'il était le Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Et sur le matin, pendant qu\'il faisait très sombre, il sortit, après s\'être levé, pour se rendre dans un lieu désert, et là il priait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Et Simon et ceux qui étaient avec lui se mirent à sa poursuite,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'et ils le trouvèrent, et ils lui disent: « Tous te cherchent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Et il leur dit: « Allons ailleurs dans les bourgades suivantes, afin que j\'y prêche aussi, car c\'est pour cela que je suis sorti. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Et il parcourut toute la Galilée, prêchant dans leurs synagogues, et expulsant les démons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Et un lépreux vient à lui, qui le sollicitait en lui disant: « Seigneur!... car, si tu le veux, tu peux me guérir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Et étant ému de compassion, il le toucha en étendant la main, et il lui dit: « Je le veux, soit guéri. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Et aussitôt la lèpre le quitta et il fut guéri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Et l\'ayant vertement tancé, il le renvoya immédiatement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'et il lui dit: « Garde-toi d\'en rien dire à personne; mais va, montre-toi au prêtre et présente pour ta purification ce qu\'a prescrit Moïse pour leur servir d\'attestation. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Mais, quand l\'autre fut sorti, il se mit à beaucoup parler et à divulguer l\'affaire, en sorte qu\'il ne pouvait plus entrer publiquement dans aucune ville, mais il se tenait au dehors dans des lieux déserts, et on venait à lui de partout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Et étant, quelques jours après, rentré à Capharnaoum, on ouït dire: « Il est à la maison. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Et il se fit un nombreux rassemblement, en sorte que les environs de la porte n\'y suffisaient même plus, et il leur annonçait la parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Et des gens surviennent lui amenant un paralytique porté par quatre hommes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'et comme ils ne pouvaient, à cause de la foule, le transporter vers lui, ils découvrirent le toit, là où il était; et après avoir fait une ouverture, ils dévalent la couchette où le paralytique était couché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Et Jésus, ayant vu leur foi, dit au paralytique: « Mon enfant, tes péchés sont pardonnés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Or il y avait là quelques scribes qui étaient assis et qui se disaient dans leurs cœurs:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, '« En parlant ainsi, cet homme blasphème; qui est-ce qui peut pardonner les péchés, si ce n\'est Dieu seul? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Et aussitôt Jésus, ayant connu en son esprit ce qu\'ils pensaient en eux-mêmes, leur dit: « Pourquoi pensez-vous ces choses-là dans vos cœurs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Quel est le plus facile, de dire au paralytique: Tes péchés sont pardonnés; ou de dire: Lève-toi, et prends ta couchette, et marche?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Or, pour que vous sachiez que fils de l\'homme a l\'autorité de pardonner les péchés sur la terre... »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'il dit au paralytique: « Je te le dis, lève-toi, prends ton lit, et va-t-en dans ta maison. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Et il se leva, et aussitôt ayant pris sa couchette il sortit en présence de tous, en sorte que tous étaient dans l\'étonnement, et glorifiaient Dieu: « car jamais nous n\'avons rien vu de semblable. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Et il sortit de nouveau pour se rendre auprès de la mer, et toute la foule vint vers lui, et il les enseignait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Et en passant il vit Lévi fils d\'Alphée assis au bureau des péages, et il lui dit: « Suis-moi. » Et s\'étant levé il le suivit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Et il advient qu\'il se met à table dans sa maison; et beaucoup de publicains et de pécheurs s\'attablaient avec Jésus et ses disciples; car ils étaient nombreux, et ils le suivaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Et les scribes du parti des pharisiens, ayant vu qu\'il mangeait avec les pécheurs et les publicains, disaient à ses disciples: « Eh quoi! il mange avec les publicains et les pécheurs! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Ce que Jésus ayant ouï, il leur dit: « Ce ne sont pas les valides qui ont besoin du médecin, mais les mal portants; je ne suis pas venu appeler des justes, mais des pécheurs. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Et les disciples de Jean et les pharisiens jeûnaient. Et ils viennent et ils lui disent: « Pourquoi les disciples de Jean et les disciples des pharisiens jeûnent-ils, tandis que les tiens ne jeûnent point. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Et Jésus leur dit: « Est-ce que les fils de la chambre nuptiale pendant que l\'époux est avec eux peuvent jeûner? Tant qu\'ils ont l\'époux avec eux, ils ne peuvent pas jeûner;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'mais des jours viendront où l\'époux leur sera enlevé, et alors ils jeûneront en ce jour-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Personne ne coud une pièce d\'étoffe écrue à un vieil habit; autrement le rapiécetage neuf du vieux s\'emporte lui-même, et il en résulte une déchirure pire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Et personne ne met du vin nouveau dans des outres vieilles; autrement le vin rompra les outres, et le vin est perdu ainsi que les outres; mais on met du vin nouveau dans des outres neuves. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Et il advint que le jour du sabbat il traversait les champs de blé, et ses disciples se mirent, tout en marchant, à arracher les épis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Et les pharisiens lui disaient: « Regarde! pourquoi font-ils le jour du sabbat ce qui n\'est pas permis? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Et il leur disait: « N\'avez-vous jamais lu ce que fit David, quand il sentit le besoin, et qu\'il eut faim, lui et ceux qui étaient avec lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Il entra dans la maison de Dieu, du temps du grand prêtre Abiathar, et il mangea les pains de proposition, qu\'il n\'est pas permis de manger, sauf aux prêtres, et il en donna aussi à ceux qui étaient avec lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Et il leur disait: « Le sabbat a été fait pour l\'homme, et non pas l\'homme pour le sabbat;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'en sorte que le fils de l\'homme est maître, même du sabbat. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Et il entra de nouveau dans une synagogue, et il se trouvait là un homme ayant la main desséchée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Et ils l\'observaient pour voir si, le jour du sabbat, il le guérirait, afin de pouvoir l\'accuser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Et il dit à l\'homme qui avait la main sèche: « Lève-toi, et viens ici au milieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Et il leur dit: « Est-il permis le jour du sabbat de faire du bien ou de faire du mal, de sauver une vie ou de la détruire? » Mais eux se taisaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Et ayant porté tout autour de lui ses regards sur eux avec colère, étant vivement attristé de l\'endurcissement de leur cœur, il dit à l\'homme: « Étends la main. » Et il l\'étendit et sa main fut guérie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Et les pharisiens étant sortis tenaient aussitôt conseil contre lui avec les Hérodiens, afin de le faire mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Et Jésus se retira, avec ses disciples vers la mer, et une multitude nombreuse venue de la Galilée le suivit. Et de la Judée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'et de Jérusalem, et de l\'Idumée, et d\'au delà le Jourdain, et des environs de Tyr et de Sidon, une multitude nombreuse entendant parler de tout ce qu\'il faisait, vint à lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Et il dit à ses disciples de faire tenir près de lui des barques, à cause de la foule, afin qu\'on ne se pressât pas contre lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'en effet il avait guéri beaucoup de monde, en sorte que tous ceux qui avaient des infirmités se jetaient sur lui, afin de le toucher.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Et les esprits impurs, quand ils le voyaient, se jetaient à ses pieds et s\'écriaient: « Tu es le fils de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Et il leur adressait beaucoup de remontrances, pour qu\'ils ne le fissent pas connaître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Et il monte sur la montagne, et il appelle à lui ceux qu\'il voulait; et ils vinrent vers lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Et il en désigna douze, qu\'il nomma aussi apôtres, afin qu\'ils fussent avec lui, et afin de les envoyer prêcher,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'en ayant l\'autorité de chasser les démons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Et il désigna les douze, et il donna à Simon le nom de Pierre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'et Jacques fils de Zébédée et Jean le frère de Jacques, et il leur donna le nom de Boanerges, qui signifie fils du tonnerre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'et André, et Philippe, et Barthélémy, et Matthieu, et Thomas, et Jacques le fils d\'Alphée, et Thaddée, et Simon le Cananéen,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'et Judas Iscarioth, lequel aussi le livra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Et il se rend à la maison, et la foule se réunit de nouveau, en sorte qu\'ils ne pouvaient pas même prendre leur repas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Et ceux qui lui tenaient de près l\'ayant appris sortirent pour se saisir de lui, car ils disaient: « Il a perdu l\'esprit. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Et les scribes descendus de Jérusalem disaient: « Il a Béézéboul, » et: « C\'est par le chef des démons qu\'il chasse les démons. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Et les ayant appelés à lui, il leur disait sous forme de paraboles: « Comment Satan peut-il chasser Satan?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Et si un royaume est divisé contre lui-même, ce royaume-là ne peut pas subsister;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'et si une maison est divisée contre elle-même, cette maison-là ne pourra pas subsister;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'et si Satan s\'est soulevé contre lui-même et est divisé, il ne peut pas subsister, mais il prend fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Mais personne ne peut, après être entré dans la maison de l\'homme fort, piller ses biens, s\'il n\'a pas premièrement garrotté l\'homme fort, et alors il pillera sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'En vérité je vous déclare que tous les péchés et les blasphèmes, qu\'ils auront pu proférer, seront pardonnés aux fils des hommes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'mais celui qui aura blasphémé contre l\'esprit saint n\'a point de pardon à attendre pour l\'éternité, mais il est coupable d\'un péché éternel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'C\'est qu\'ils disaient: « Il a un esprit impur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Et sa mère et ses frères viennent, et se tenant debout dehors ils envoyèrent vers lui pour l\'appeler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Et la foule était-assise autour de lui, et on lui dit: « Voici, ta mère et tes frères sont dehors qui te cherchent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Et il leur réplique: « Qui est ma mère et mes frères? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Ayant porté ses regards tout alentour sur ceux qui étaient assis en cercle autour de lui, il dit: « Voilà ma mère et mes frères;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'quiconque aura fait les volontés de Dieu, celui-là est mon frère, et ma sœur, et ma mère. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Et il commença à enseigner près de la mer. Et une foule très nombreuse se rassemble autour de lui, en sorte qu\'étant monté sur une barque il s\'assit dans la mer, et toute la foule se tenait près de la mer sur le rivage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Et il leur enseignait beaucoup de choses sous forme de paraboles, et il leur disait dans son enseignement:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, '« Écoutez, voici, le semeur sortit pour semer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'et il advint, pendant qu\'il semait, qu\'une partie tomba le long du chemin, et les oiseaux vinrent et la mangèrent toute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Et une autre partie tomba sur le sol rocailleux et là où elle n\'avait pas beaucoup de terre, et aussitôt elle leva parce qu\'elle n\'avait pas un sol profond;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'et, quand le soleil se fut levé, elle fut brûlée, et, comme elle n\'avait pas de racine, elle sécha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Et une autre partie tomba dans les épines, les épines montèrent et l\'étouffèrent, et elle ne donna pas de fruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Et une autre partie tomba dans la bonne terre, et elle donnait du fruit qui montait et grandissait, et elle rapportait à raison de trente, et à raison de soixante, et à raison de cent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Et il disait: « Que celui qui a des oreilles pour entendre entende! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Et lorsqu\'il fut seul, ceux qui l\'entouraient avec les douze l\'interrogeaient sur les paraboles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'et il leur disait: « C\'est à vous qu\'a été donné le mystère du royaume de Dieu, mais pour ceux-là, qui sont du dehors, tout se passe en parabole,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'afin qu\'en voyant ils voient et n\'aperçoivent point, et qu\'en entendant ils entendent et ne comprennent point, de peur qu\'ils ne se convertissent et qu\'il ne leur soit pardonné. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Et il leur dit: « Vous ignorez le sens de cette parabole, et comment comprendrez-vous toutes les paraboles?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Le semeur sème la parole;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'mais ceux qui se trouvent le long du chemin là où la parole est semée, sont ceux qui, lorsqu\'ils l\'ont entendue, aussitôt survient Satan, et il enlève la parole qui a été semée en eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Et de même ceux qui sont semés sur les endroits rocailleux, sont ceux qui, lorsqu\'ils ont entendu la parole, aussitôt la reçoivent avec joie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'et ils n\'ont pas de racine en eux-mêmes, mais ils sont sans persistance; ensuite s\'il est survenu une tribulation ou une persécution à cause de la parole, ils trébuchent aussitôt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Et d\'autres sont ceux qui sont semés dans les épines; ce sont ceux qui ont écouté la parole,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'et les soucis du siècle et le faux attrait de la richesse et les autres genres de convoitises s\'introduisent et se réunissent pour étouffer là parole, et elle devient stérile,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Et ceux qui ont été semés sur la bonne terre, sont ceux qui entendent la parole et la reçoivent; et ils donnent du fruit à raison de trente, et de soixante, et de cent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Et il leur disait: « Est-ce que la lampe vient pour être placée sous le boisseau ou sous le lit? N\'est-ce pas pour être placée sous son support?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Car rien n\'est caché, si ce n\'est afin d\'être manifesté, et rien n\'a été tenu secret, qu\'afin d\'être manifesté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Si quelqu\'un a des oreilles pour entendre, qu\'il entende. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Et il leur disait: « Prenez garde à ce que vous entendez; avec la mesure dont vous mesurez il vous sera mesuré, et on vous ajoutera du surcroît;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'car celui qui a, on lui donnera, et celui qui n\'a pas, même ce qu\'il a lui sera enlevé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Et il disait: « Il en est du royaume de Dieu, comme d\'un homme qui aurait jeté la semence sur la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'et, soit qu\'il dorme, soit qu\'il veille, nuit et jour, la semence germe et se développe, sans que lui-même sache comment;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'd\'elle-même la terre produit, d\'abord de l\'herbe, puis un épi; puis il y a dans l\'épi plénitude de blé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'or quand le fruit s\'est montré, aussitôt on envoie la faucille, car la moisson est venue. Et il disait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, '« Comment comparerons-nous le royaume de Dieu, ou dans quelle parabole le placerons-nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Il est comme un grain de moutarde, qui, lorsqu\'il a été semé sur la terre, quoiqu\'il soit plus petit que toutes les semences qui sont sur la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'lors, dis-je, qu\'il a été semé, monte et devient plus grand que toutes les plantes potagères, et pousse de grandes branches, en sorte que les oiseaux du ciel peuvent s\'abriter sous son ombre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'Et c\'était par beaucoup de paraboles de ce genre qu\'il leur annonçait la parole, selon ce qu\'ils pouvaient entendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Et il ne leur parlait point sans parabole; mais dans le particulier il expliquait tout à ses propres disciples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Et ce même jour le soir étant venu il leur dit: « Passons sur l\'autre rive. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Et ayant quitté la foule, ils le prennent avec eux, tel qu\'il était dans la barque; et d\'autres barques étaient avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Et il se leva un grand tourbillon de vent, et les flots se jetaient dans la barque, en sorte que la barque en était déjà remplie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Quant à lui, il dormait à la poupe sur le coussin, et ils le réveillent et lui disent: « Maître, ne te soucies-tu point de ce que nous périssons? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Et s\'étant réveillé, il gourmanda le vent et dit à la mer: « Tais-toi, fais silence. » Et le vent tomba, et il se fit un grand calme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Et il leur dit: « Pourquoi êtes-vous effrayés? N\'avez-vous pas encore foi? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Et ils furent saisis d\'une grande terreur, et ils se disaient les uns aux autres: « Qui est donc celui-ci, que même le vent et la mer lui obéissent? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Et ils arrivèrent sur l\'autre rive de la mer, dans le pays des Géraséniens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Et lorsqu\'il fut sorti de la barque, vint à lui de l\'intérieur des tombeaux un homme possédé d\'un esprit impur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'lequel avait son habitation dans les tombeaux, et personne ne pouvait plus le garrotter même avec une chaîne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'car souvent il avait été garrotté avec des entraves et des chaînes, et il avait mis en pièces les chaînes et broyé les entraves, et personne n\'avait la force de le dompter;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'et constamment, nuit et jour, il se tenait dans les tombeaux et dans les montagnes, poussant des cris et se frappant lui-même à coups de pierres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Et ayant vu Jésus de loin, il accourut et l\'adora,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'et ayant jeté un grand cri, il dit: « Qu\'y a-t-il de commun entre moi et toi, Jésus, fils du Dieu très haut? Je t\'en adjure au nom de Dieu, ne me torture pas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'En effet il lui disait: « Esprit impur, sors de cet homme; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'et il lui demandait: « Quel est ton nom? » Et il lui dit: « Mon nom est légion, car nous sommes plusieurs. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Et il lui adressait beaucoup de sollicitations afin qu\'il ne les envoyât pas hors du pays.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Or il y avait là près de la montagne un grand troupeau de pourceaux au pâturage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'et ils le sollicitèrent en disant: « Envoie-nous dans ces pourceaux, afin que nous entrions en eux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Et il le leur permit, et les esprits impurs étant sortis entrèrent dans les pourceaux, et le troupeau se rua en bas du précipice dans la mer, au nombre d\'environ deux mille, et ils furent submergés dans la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Et ceux qui les faisaient paître s\'enfuirent, et ils portèrent la nouvelle dans la ville et dans les campagnes, et on vint voir ce qui en était de l\'événement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Et ils viennent vers Jésus, et ils voient le démoniaque assis, vêtu, et raisonnable, lui qui avait eu la légion, et ils furent saisis de terreur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Et les témoins leur racontèrent comment les choses s\'étaient passées pour le démoniaque et les pourceaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'et ils se mirent à le solliciter de sortir de leur territoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Et comme il montait dans la barque, celui qui avait été démoniaque le sollicitait afin de rester avec lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'et il ne le lui permit pas, mais il lui dit: « Va-t-en dans ta maison auprès des tiens, et rapporte leur tout ce que le Seigneur a fait pour toi, et combien Il a eu compassion de toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Et il s\'en alla, et il commença à proclamer dans la Décapole tout ce que Jésus avait fait pour lui; et tous étaient émerveillés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Et quand Jésus eut de nouveau traversé sur l\'autre rive dans une barque, une foule nombreuse se rassembla près de lui, et il se tenait auprès la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Alors survient un des chefs de synagogue, nommé Jaïrus; et l\'ayant vu, il tombe à ses pieds,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'et il lui adressait beaucoup de sollicitations, en disant: « Ma fille est à l\'extrémité, viens poser les mains sur elle, afin qu\'elle soit guérie et qu\'elle vive. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Et il s\'en alla avec lui, et une foule nombreuse le suivait, et elle le pressait fortement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Et une femme, qui depuis douze ans avait une perte de sang,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'et qui avait beaucoup souffert entre les mains de nombreux médecins, et qui avait dépensé tout son bien et n\'y avait rien gagné, mais avait été plutôt de mal en pis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'ayant ouï ce qu\'on disait de Jésus, vint dans la foule toucher par derrière son manteau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'car elle disait: « Si je puis toucher ses vêtements, je serai guérie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Et aussitôt l\'écoulement de son sang se dessécha, et elle sentit en son corps qu\'elle était guérie de son infirmité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'et aussitôt Jésus ayant senti en lui-même la force qui était sortie de lui, s\'étant retourné au milieu de la foule, disait: « Qui est-ce qui a touché mes vêtements? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Et ses disciples lui disaient: « Tu vois la foule qui te presse, et tu dis: Qui est-ce qui m\'a touché? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Et il portait autour de lui ses regards pour voir celle qui avait fait cela.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Mais la femme effrayée et tremblante, sachant ce qui lui était arrivé, vint, et se jeta à ses pieds, et lui dit toute la vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Mais il lui dit: « Ma fille, ta foi t\'a guérie; va-t-en en paix et sois rétablie de ton infirmité. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Comme il parlait encore surviennent de chez le chef de synagogue des gens qui disent: « Ta fille est morte, pourquoi importunes-tu encore le maître? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Mais Jésus, sans faire attention à ce qu\'on venait de dire, dit au chef de synagogue: « Ne crains point, crois seulement. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Et il ne permit pas que personne l\'accompagnât, sinon Pierre, et Jacques, et Jean le frère de Jacques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Et ils arrivent à la maison du chef de synagogue, et il voit du bruit et des gens qui pleuraient et lamentaient beaucoup;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'et étant entré il leur dit: « Pourquoi faites-vous du bruit et pleurez-vous? L\'enfant n\'est pas morte, mais elle dort. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Et ils se moquaient de lui. Mais les ayant chassés, il prend avec lui le père de l\'enfant et sa mère et ceux qui étaient avec lui, et il entra là où était l\'enfant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'et ayant pris la main de l\'enfant, il lui dit: Talitha koum, ce qui signifie étant traduit: « Petite fille, je te le dis, lève-toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Et aussitôt la petite fille se leva, et elle marchait; en effet elle avait douze ans. Et ils furent aussitôt saisis d\'un grand étonnement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'et il leur enjoignit fortement que personne ne le sût, et il dit qu\'on lui donnât à manger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Et il sortit de là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Et le sabbat étant venu, il commença à enseigner dans la synagogue, et le plus grand nombre étaient stupéfaits en l\'entendant, et ils disaient: « D\'où viennent à celui-ci ces choses? » et: « Qu\'est-ce que cette sagesse qui lui a été donnée, et les miracles de cette espèce qui se font par ses mains?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Celui-ci n\'est-il pas le charpentier, le fils de Marie, et le frère de Jacques et de Josès et de Judas et de Simon? Et ses sœurs ne sont-elles pas ici parmi nous? » Et il était pour eux une pierre d\'achoppement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Et Jésus leur dit: « Ce n\'est que dans sa patrie, et parmi ses parents, et dans sa famille, qu\'un prophète est méprisé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Et il ne pouvait faire là aucun miracle, sauf qu\'ayant imposé les mains à quelques infirmes, il les guérit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'et il s\'émerveilla de leur incrédulité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Et il appelle à lui les douze, et il commença à les envoyer deux par deux, et il leur donnait autorité sur les esprits impurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'et il leur ordonna de ne rien prendre pour la route, sauf un bâton seulement, point de pain, ni de besace, ni de monnaie dans la ceinture,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'mais de chausser des sandales, et de ne pas revêtir deux tuniques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Et il leur disait: « Partout où vous serez entrés dans une maison, restez-y jusques à ce que vous sortiez de là;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'et l\'endroit qui ne vous aura pas reçus, et où l\'on ne vous aura pas écoutés, secouez en sortant de là la poussière qui est sous vos pieds pour leur servir de témoignage. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Et étant partis ils prêchèrent qu\'on eût à se repentir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'et ils chassaient plusieurs démons, et ils oignaient d\'huile plusieurs malades, et ils les guérissaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Et le roi Hérode ouït parler de lui, car son nom était devenu célèbre, et on disait: « Jean le baptiseur est ressuscité des morts, et c\'est pourquoi les miracles s\'opèrent par lui; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'mais d\'autres disaient: « C\'est Élie; » tandis que d\'autres disaient: « C\'est un prophète comme l\'un des prophètes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Mais Hérode en ayant ouï parler, disait: « Ce Jean que j\'ai fait décapiter, c\'est lui qui est ressuscité. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'En effet Hérode lui-même avait envoyé saisir Jean, et l\'avait fait enchaîner en prison à cause d\'Hérodias femme de Philippe son frère; car il l\'avait épousée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'et Jean disait à Hérode: « Il ne t\'est pas permis de posséder la femme de ton frère. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Mais Hérodias lui en gardait rancune, et elle voulait le faire mourir, et elle ne le pouvait pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'car Hérode craignait Jean; sachant que c\'était un homme juste et saint, il le protégeait; et après l\'avoir entendu, il était souvent inquiet, et il l\'écoutait volontiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Et un jour propice étant survenu, auquel Hérode, pour la fête anniversaire de sa naissance, donna un festin à ses grands et aux généraux, et aux principaux de la Galilée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'et sa fille Hérodias étant entrée et ayant dansé, elle plut à Hérode et aux convives. Or le roi dit à la jeune fille: « Demande-moi ce que tu voudras, et je te le donnerai. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Et il lui dit avec serment: « Quoi que ce soit que tu me demandes, je te le donnerai, fût-ce la moitié de mon royaume. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Et étant sortie, elle dit à sa mère: « Que demanderai-je? » Et elle lui dit: « La tête de Jean le baptiseur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Et étant aussitôt rentrée avec empressement auprès du roi, elle lui adressa sa demande en disant: « Je veux que tu me donnes immédiatement sur un plat la tête de Jean le baptiseur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Et le roi devenu tout triste, ne voulut pas, à cause de ses serments et des convives, lui manquer de parole;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'et aussitôt le roi expédia un de ses gardes, avec l\'ordre de rapporter sa tête;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'et étant parti il le décapita dans la prison, et rapporta sa tête sur un plat, et il la donna à la jeune fille, et la jeune fille la donna à sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Et ses disciples l\'ayant appris vinrent et enlevèrent son cadavre, et ils le placèrent dans un tombeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Et les apôtres se réunirent auprès de Jésus, et ils lui racontèrent tout ce qu\'ils avaient fait et tout ce qu\'ils avaient enseigné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Et il leur dit: « Venez, vous seuls, dans un lieu désert à l\'écart, et reposez-vous un peu. » En effet les allants et venants étaient nombreux, et ils n\'avaient pas même le loisir de manger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Et ils s\'en allèrent sur la barque dans un lieu désert à l\'écart.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Et on les vit partir, et plusieurs les reconnurent, et ils accoururent là à pied de toutes les villes, et ils les devancèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Et lorsqu\'il aborda, il vit une foule nombreuse, et il fut ému de compassion envers eux, car ils étaient comme des brebis qui n\'ont point de berger; et il se mit à leur enseigner beaucoup de choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Et comme l\'heure était déjà fort avancée, ses disciples s\'étant approchés de lui disaient: « Ce lieu est désert, et l\'heure est déjà fort avancée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'renvoie-les, afin qu\'ils aillent dans les campagnes et les villages d\'alentour s\'acheter de quoi manger. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Mais il leur répliqua: « Donnez-leur vous-mêmes à manger. » Et ils lui disent: « Allons acheter pour deux cents deniers de pains, et donnons-leur à manger! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Mais il leur dit: « Combien avez-vous de pains? Allez le voir. » Et après s\'en être assurés, ils disent: « Cinq, et deux poissons. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Et il leur ordonna que tout le monde s\'assît, groupes par groupes, sur l\'herbe verte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'et ils s\'étendirent bandes par bandes de cent et de cinquante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Et après avoir pris les cinq pains et les deux poissons, il prononça, en levant les yeux vers le ciel, une bénédiction; puis il rompit les pains, et il les donnait aux disciples, afin qu\'ils les leur offrissent; et il distribua à tous les deux poissons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Et tous mangèrent et furent rassasiés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'et on emporta des morceaux de quoi remplir douze corbeilles, ainsi que des poissons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Et ceux qui avaient mangé les pains étaient cinq mille hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Et aussitôt il contraignit ses disciples à monter dans la barque et à passer les premiers sur l\'autre rive, vers Bethsaïda, jusques à ce que lui-même eût renvoyé la foule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Et après les avoir congédiés, il s\'en alla sur la montagne pour prier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Et le soir étant venu, la barque se trouvait au milieu de la mer, et lui-même était seul à terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Et les ayant vus battus par les flots, pendant qu\'ils ramaient, car le vent leur était contraire, il vient vers eux à la quatrième veille de la nuit, en marchant sur la mer, et il voulait les dépasser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Mais eux, en le voyant marcher sur la mer, s\'imaginèrent que c\'était un fantôme, et ils poussèrent des cris;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'car tous le virent et furent troublés; mais aussitôt il leur parla et leur dit: « Courage, c\'est moi, n\'ayez pas peur? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Et il monta auprès d\'eux dans la barque, et le vent tomba. Et ils ressentirent en eux-mêmes une grande stupéfaction;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'car ils n\'avaient pas compris l\'affaire des pains, mais leur cœur était endurci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Et ayant achevé leur traversée, ils touchèrent terre à Gennèsareth, et ils abordèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Et lorsqu\'ils furent sortis de la barque, aussitôt qu\'on l\'eut reconnu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'on parcourut toute cette contrée-là, et on se mit à transporter les malades sur leurs couchettes, partout où on entendait dire qu\'il se trouvait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Et partout où il entrait dans les villages, ou dans les villes, ou dans les campagnes, on déposait les malades dans les places publiques, et on le sollicitait afin qu\'ils pussent toucher, ne fût-ce que la frange de son manteau, et tous ceux qui le touchèrent étaient guéris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Et auprès de lui se réunissent les pharisiens et quelques-uns des scribes venus de Jérusalem;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'et ayant vu que quelques-uns de ses disciples prenaient leur repas avec des mains souillées, c\'est-à-dire non lavées...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, '(car les pharisiens et tous les Juifs ne mangent point qu\'ils ne se soient lavé les mains à poing fermé, conformément à la tradition des anciens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'et lorsqu\'ils viennent de la place publique ils ne mangent point, qu\'ils ne se soient purifiés, et il est plusieurs autres observances qui leur ont été transmises, comme les lavages des coupes, et des brocs, et des vases d\'airain)...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Et les pharisiens et les scribes lui demandent: « Pourquoi tes disciples ne se conforment-ils pas à la tradition des anciens, mais prennent-ils leurs repas avec des mains souillées? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Mais il leur dit: « Comme Ésaïe a bien prophétisé sur vous autres hypocrites, selon qu\'il est écrit: Ce peuple-ci M\'honore des lèvres, tandis que leur cœur est bien éloigné de Moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Mais c\'est vainement qu\'ils Me révèrent, en enseignant des doctrines qui sont des commandements d\'hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Mettant de côté le commandement de Dieu, vous retenez la tradition des hommes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Et il leur disait: « Comme vous savez bien abroger le commandement de Dieu, afin d\'observer votre tradition;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'car Moïse a dit: Honore ton père et ta mère, et: Que celui qui maudit père ou mère soit mis à mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'mais vous, vous dites: « Si un homme dit à son père ou à sa mère: Corban (c\'est-à-dire offrande) est fait de ce dont je pourrais t\'assister, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'vous ne lui permettez plus de rien faire pour son père ou sa mère,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'abrogeant la parole de Dieu par la tradition que vous avez transmise. Et vous faites beaucoup de choses semblables à celles-là. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Et ayant de nouveau appelé à lui la foule, il leur dit: « Écoutez-moi tous, et comprenez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Rien de ce qui du dehors de l\'homme entre en lui ne le souille, mais c\'est ce qui sort de l\'homme qui souille l\'homme. [');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Si quelqu\'un a des oreilles pour entendre, qu\'il entende.] »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Et lorsqu\'il fut rentré au logis loin de la foule, les disciples l\'interrogeaient sur cette parabole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Et il leur dit: « Ainsi, vous aussi, vous êtes sans intelligence! Ne comprenez-vous pas que tout ce qui du dehors entre dans l\'homme ne peut pas le souiller,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'car cela n\'entre pas dans son cœur; mais dans son ventre, et de là va au retrait, lequel purifie tous les aliments. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Mais il disait: « Ce qui sort de l\'homme? voilà ce qui souille l\'homme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'car c\'est du dedans, c\'est du cœur des hommes, que sortent les mauvaises pensées, les impudicités,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'les larcins, les meurtres, les adultères, les cupidités, les méchancetés, la ruse, la débauche, l\'envie, la calomnie, l\'orgueil, la déraison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Toutes ces mauvaises choses sortent du dedans et souillent l\'homme. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Or s\'étant éloigné de là, il s\'en alla dans le territoire de Tyr et de Sidon, et étant entré dans une maison, il voulait que personne ne le sût. Et il ne put demeurer caché,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'mais aussitôt une femme dont la fille avait un esprit impur ayant ouï parler de lui, vint se jeter à ses pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Or cette femme était grecque, syrienne, phénicienne d\'origine, et elle l\'implorait afin qu\'il chassât le démon hors de sa fille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Et il lui disait: « Laisse d\'abord les enfants se rassasier; car il n\'est pas bien de prendre le pain des enfants et de le jeter aux petits chiens. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Mais elle répliqua et lui dit: « Assurément, Seigneur! Les petits chiens aussi sous la table mangent une partie des miettes des petits enfants. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Et il lui dit: « A cause de cette parole, va, le démon est sorti de ta fille. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Et s\'en étant allée dans sa maison, elle trouva la petite fille couchée sur son lit, et le démon sorti.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Et étant ressorti du territoire de Tyr, il vint, en traversant Sidon, vers la mer de Galilée, par le milieu du territoire de la Décapole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Et on lui amène un sourd dont la voix était confuse, et on le sollicite afin qu\'il pose la main sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Et l\'ayant emmené à l\'écart loin de la foule, il mit ses doigts dans ses oreilles, et ayant craché, il toucha sa langue;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'puis, ayant levé les yeux vers le ciel, il soupira, et lui dit: « Ephphatha, » ce qui signifie: « Ouvre-toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Et ses oreilles s\'ouvrirent, et le lien de sa langue se délia, et il parlait régulièrement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Et il leur enjoignit de n\'en parler à personne; mais plus il le leur interdisait, d\'autant plus s\'empressaient-ils de le proclamer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'et ils étaient dans une stupéfaction extrême, et disaient: « Il a tout fait d\'une manière admirable, puisqu\'il fait même ouïr les sourds et parler ceux qui sont sans voix. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'En ces jours-là une foule nombreuse se trouvant de nouveau réunie, et n\'ayant rien à manger, il appela à lui ses disciples et leur dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'J\'ai compassion de cette foule, car voilà déjà trois jours qu\'ils persistent, et ils n\'ont rien à manger;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'et si je les renvoie à jeun dans leurs demeures, ils défailleront en chemin; et quelques-uns d\'entre eux sont venus de loin. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Et ses disciples lui répliquèrent: « Comment quelqu\'un pourra-t-il les rassasier de pains, ici, dans un désert? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Et il leur demandait: « Combien avez-vous de pains? » Et ils disent: « Sept. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Et il invite la foule à s\'asseoir sur la terre, et ayant pris les sept pains, après avoir rendu grâces il les rompit, et il les donnait à ses disciples afin qu\'ils les offrissent, et ils les offrirent à la foule;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'et ils avaient quelques petits poissons, et après les avoir bénis, il dit qu\'on les offrît aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Et ils mangèrent et ils furent rassasiés, et on emporta les restes des morceaux dans sept paniers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Or ils étaient environ quatre mille; et il les congédia.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Et aussitôt étant monté lui-même dans la barque avec ses disciples il vint dans le territoire de Dalmanountha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Et les pharisiens sortirent, et se mirent à discuter avec lui, réclamant de lui un signe qui vînt du ciel, afin de le mettre à l\'épreuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Et ayant profondément gémi en son esprit, il dit: « Pourquoi cette génération réclame-t-elle un signe? En vérité je déclare qu\'aucun signe ne sera donné à cette génération. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Et les ayant quittés, il se rembarqua et passa sur l\'autre rive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Et ils oublièrent de prendre des pains, et ils n\'avaient qu\'un seul pain avec eux dans la barque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Et il les exhortait fortement en disant: « Ayez soin d\'être en garde contre le levain des pharisiens et contre le levain d\'Hérode. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Et ils réfléchissaient entre eux sur ce qu\'ils n\'avaient pas de pains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Et s\'en étant aperçu, il leur dit: « Pourquoi réfléchissez-vous sur ce que vous n\'avez pas de pains? Ne comprenez-vous pas encore, et êtes-vous sans intelligence? Avez-vous le cœur endurci?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Ayant des yeux ne voyez-vous pas? Et ayant des oreilles n\'entendez-vous pas? Et ne vous souvenez-vous pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Quand je rompis les cinq pains pour les cinq mille, combien de corbeilles pleines de morceaux emportâtes-vous? » Ils lui disent: « Douze. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, '« Quand les sept pour les quatre mille, combien de paniers remplis de morceaux emportâtes-vous? » Et ils lui disent: « Sept. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Et il leur disait: « Comment ne comprenez-vous pas? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Et ils arrivent à Bethsaïda. Et on lui amène un aveugle, et on le sollicitait afin qu\'il le touchât.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Et ayant pris la main de l\'aveugle, il l\'emmena hors du village, et ayant craché sur ses yeux, il lui demandait, après lui avoir imposé les mains, s\'il voyait quelque chose.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Et ayant regardé, il disait: « Je vois les hommes; car je vois comme des arbres qui marchent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Ensuite il plaça derechef les mains sur ses yeux, et il vit clair, et il fut guéri et il apercevait nettement toutes choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Et il le renvoya chez lui en disant: « Ne rentre pas même dans le village. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Et Jésus sortit pour se rendre, ainsi que ses disciples, dans les villages de Césarée de Philippe, et chemin faisant il interrogeait ses disciples, en leur disant: « Qui disent les gens que je suis? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Et eux lui dirent: « Jean le baptiste, et d\'autres, Elie, et d\'autres, l\'un des prophètes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Et il leur demandait: « Mais vous, qui dites-vous que je suis? » Pierre lui réplique: « Tu es le Christ. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Et il leur fit des remontrances, afin qu\'ils ne parlassent de lui à personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Et il commença à leur enseigner qu\'il fallait que le fils de l\'homme souffrît beaucoup, et qu\'il fût réprouvé par les anciens et les grands prêtres et les scribes, et qu\'il fût mis à mort, et qu\'au bout de trois jours il ressuscitât.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Et il proférait ce discours avec assurance. Et Pierre, l\'ayant pris à part, se mit à lui faire des remontrances.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Mais lui, s\'étant retourné, et ayant vu ses disciples, adressa des remontrances à Pierre, et dit: « Va-t-en arrière de moi, Satan, car tu ne penses pas aux choses de Dieu, mais à celles des hommes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Et ayant appelé à lui la foule avec ses disciples, il leur dit: « Si quelqu\'un veut venir après moi, qu\'il renonce à lui-même et qu\'il prenne sa croix, et qu\'il me suive;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'car celui qui voudra sauver sa vie la perdra, mais celui qui perdra sa vie à cause de moi et de l\'Évangile la sauvera;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'en effet, que sert-il à un homme d\'avoir gagné le monde entier et perdu sa vie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Car que donnerait l\'homme pour racheter sa vie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'En effet, celui qui aura eu honte de moi et de mes paroles parmi cette génération adultère et pécheresse, le fils de l\'homme aura aussi honte de lui, quand il sera venu entouré de la gloire de son Père avec les saints anges. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Et il leur disait: « En vérité je vous déclare qu\'il y a quelques-uns de ceux qui sont ici présents, qui ne goûteront certainement point la mort jusques à ce qu\'ils aient vu le royaume de Dieu inauguré avec puissance. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Et six jours après Jésus prend avec lui Pierre et Jacques et Jean, et il les conduit seuls à l\'écart sur une haute montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'Et il fut transfiguré en leur présence, et ses vêtements devinrent éblouissants; si blancs qu\'il n\'est pas sur la terre de foulon qui puisse ainsi blanchir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Et Élie leur apparut avec Moïse, et ils conversaient avec Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'et Pierre prenant la parole dit à Jésus: « Rabbi, c\'est une bonne chose pour nous que d\'être ici; faisons trois tentes, une pour toi, et une pour Moïse, et une pour Élie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Il ne savait pas en effet ce qu\'il devait dire, car ils avaient été saisis d\'effroi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Et une nuée survint qui les couvrit, et de la nuée sortit une voix: « Celui-ci est Mon Fils bien-aimé! Écoutez-le. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Et ayant sur-le-champ regardé autour d\'eux, ils ne virent plus personne avec eux, sauf Jésus seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Et pendant qu\'ils descendaient de la montagne, il leur donna des ordres, afin qu\'ils ne racontassent à personne ce qu\'ils avaient vu, si ce n\'est lorsque le fils de l\'homme serait ressuscité des morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Et ils s\'attachèrent à cette parole se demandant entre eux: Que signifie: « ressusciter des morts? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Et ils l\'interrogeaient en disant: « Pourquoi les scribes disent-ils qu\'il faut qu\'Élie vienne premièrement? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Mais il leur dit: « Il est vrai qu\'Élie, après être premièrement venu, doit rétablir toutes choses. Et comment est-il écrit à propos du Fils de l\'homme qu\'il doit souffrir beaucoup et être compté pour rien?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Mais je vous déclare qu\'Élie aussi est venu, et qu\'ils lui ont fait tout ce qu\'ils voulaient, selon qu\'il est écrit à propos de lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Et quand ils furent arrivés vers les disciples ils virent autour d\'eux une foule nombreuse et des scribes qui discutaient avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Et aussitôt toute la foule l\'ayant vu fut dans l\'épouvante, et elle accourait pour le saluer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Et il leur demanda: « Sur quoi discutez-vous avec eux? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Et quelqu\'un de la foule lui répliqua: « Maître, je t\'ai amené mon fils qui a un esprit muet;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'et où que ce soit qu\'il s\'empare de lui, il le terrasse; et il écume et grince les dents et devient tout roide; et j\'ai parlé à tes disciples afin qu\'ils le chassassent, et ils n\'ont pas pu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Et lui leur réplique: « O génération incrédule, jusques à quand serai-je avec vous? Amenez-le moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Et on le lui amena. Et quand il l\'eut vu, l\'esprit le jeta aussitôt en convulsion, et étant tombé à terre, il se roulait en écumant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Et il demanda au père: « Combien de temps y a-t-il que cela lui arrive? » Et il dit: « Depuis son enfance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'et souvent il l\'a jeté soit dans le feu soit dans les eaux, afin de le faire périr; mais, si tu peux quelque chose, viens à notre secours par compassion pour nous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Or Jésus lui dit: « Quant à ton: « Si tu peux, » toutes choses sont possibles pour celui qui croit. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Aussitôt le père du jeune enfant de s\'écrier: « Je crois; viens au secours de mon incrédulité. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Mais Jésus ayant vu accourir la multitude réprimanda l\'esprit impur, en lui disant: « Esprit muet et sourd, c\'est moi, c\'est moi qui te l\'ordonne, sors de lui et ne rentre plus en lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Et ayant poussé des cris et l\'ayant jeté en de violentes convulsions, il sortit; et il devint comme un cadavre, en sorte que la plupart disaient: « Il est mort. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Mais Jésus lui ayant pris les mains le fit lever, et il se tint debout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Et lorsqu\'il fut rentré au logis, ses disciples lui demandaient en particulier: « Pourquoi n\'avons-nous pas pu le chasser nous-mêmes? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Et il leur dit: « Cette espèce-là ne peut sortir par aucun autre moyen que par la prière. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'Et étant sortis de là ils cheminaient au travers de la Galilée, et il ne voulait pas que personne le sût;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'car il instruisait ses disciples et disait: « Le fils de l\'homme va être livré aux mains des hommes, et ils le feront mourir, et, quand il aura été mis à mort, au bout de trois jours il ressuscitera. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Mais eux ne comprenaient pas cette parole, et ils craignaient de l\'interroger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Et ils arrivèrent à Capharnaoum. Et lorsqu\'il fut dans la maison, il leur demandait: « Sur quoi discutiez-vous en chemin? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Mais ils se taisaient; car ils avaient discuté entre eux en chemin quel était le plus grand.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Et s\'étant assis, il appela les douze, et il leur dit: « Si quelqu\'un veut être le premier, il sera le dernier de tous et le serviteur de tous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'Et ayant pris un petit enfant, il le plaça au milieu d\'eux, et l\'ayant serré dans ses bras, il leur dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, '« Celui qui aura reçu en mon nom l\'un de ces petits enfants-là, me reçoit, et celui qui me reçoit, ce n\'est pas moi qu\'il reçoit, mais Celui qui m\'a envoyé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Jean lui dit: « Maître, nous avons vu quelqu\'un qui chassait des démons en ton nom, et nous l\'en empêchions parce qu\'il ne nous suivait pas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Mais Jésus dit: « Ne l\'en empêchez pas; car il n\'est personne qui fasse un miracle en mon nom, et qui puisse aussitôt après dire du mal de moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'car quiconque n\'est pas contre nous est pour nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'En effet celui qui vous aura donné à boire un verre d\'eau, par la raison que vous êtes à Christ, en vérité je vous déclare qu\'il ne perdra certainement pas sa récompense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Et celui qui aura scandalisé un seul de ces petits qui croient en moi, beaucoup mieux vaudrait pour lui qu\'on passât autour de son col une meule de moulin à âne, et qu\'on le jetât dans la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Et si ta main a été pour toi une occasion de scandale, coupe-la; il est bon que tu entres estropié dans la vie, plutôt que d\'aller, en ayant tes deux mains, dans la géhenne, dans le feu inextinguible; [');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'là où leur ver ne meurt point, et où le feu ne s\'éteint point.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Et si ton pied est pour toi une occasion de scandale, coupe-le; il est bon que tu entres boiteux dans la vie, plutôt que d\'être jeté, en ayant tes deux pieds, dans la géhenne; [');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'là où leur ver ne meurt point, et où le feu ne s\'éteint point.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Et si ton œil est pour toi une occasion de scandale, arrache-le; il est bon que tu entres borgne dans le royaume de Dieu, plutôt que d\'être jeté, en ayant deux yeux, dans la géhenne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'là où leur ver ne meurt point, et où le feu ne s\'éteint point;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'car chacun sera salé de feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Le sel est bon; mais si le sel devient insipide, avec quoi l\'assaisonnerez-vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Et s\'étant éloigné de là, il vient dans le territoire de la Judée et au delà du Jourdain, et une foule accourt de nouveau vers lui, et selon sa coutume il les enseignait de nouveau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Et des pharisiens s\'étant approchés lui demandaient: « Est-il permis à un homme de répudier sa femme? » voulant ainsi le mettre à l\'épreuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Mais il leur répliqua: « Que vous a prescrit Moïse? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Et ils lui dirent: « Moïse a permis de rédiger un acte de divorce, et de répudier. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Mais Jésus leur dit: « C\'est à cause de votre dureté de cœur qu\'il vous a donné ce commandement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'mais à l\'origine de la création Il les fit mâle et femelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'à cause de cela l\'homme quittera son père et sa mère,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'et les deux deviendront une seule chair; en sorte qu\'ils ne sont plus deux, mais une seule chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Ainsi donc que ce que Dieu a conjoint, l\'homme ne le sépare pas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Et de retour à la maison les disciples l\'interrogeaient sur ce sujet;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'et il leur dit: « Celui qui aura répudié sa femme, et en aura épousé une autre, est coupable d\'adultère envers elle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'et si elle-même, après avoir répudié son mari, en épouse un autre, elle commet un adultère. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Et on lui amenait de petits enfants afin qu\'ils les touchât; mais les disciples leur en firent des remontrances.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Or Jésus l\'ayant vu en fut indigné, et leur dit: « Laissez les petits enfants venir à moi; ne les en empêchez pas, car c\'est à ceux qui leur ressemblent qu\'appartient le royaume de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'en vérité je vous le déclare, celui qui n\'aura pas reçu le royaume de Dieu comme un petit enfant n\'y entrera certainement point. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Et, les ayant serrés dans ses bras, il les bénit en posant les mains sur eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Et au moment où il se remettait en chemin, quelqu\'un accourut, et se jetant à ses genoux il lui demandait: « Bon maître, que ferai-je pour hériter la vie éternelle? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Mais Jésus lui dit: « Pourquoi m\'appelles-tu bon? Nul n\'est bon, si ce n\'est un seul, Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Tu connais les commandements: Ne tue point; ne commets point d\'adultère; ne dérobe point; ne fais point de faux témoignage; honore ton père et ta mère. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Et l\'autre lui dit: « Maître, j\'ai observé toutes ces choses dès ma jeunesse. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Or Jésus l\'ayant regardé l\'aima, et lui dit; « Une seule chose te manque: va, vends tout ce que tu possèdes, et donne-le aux pauvres, et tu auras un trésor dans le ciel, puis viens, suis-moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Mais-lui, chagriné de cette parole, s\'en alla tout triste, car il avait de nombreuses propriétés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Et Jésus, ayant porté autour de lui ses regards, dit à ses disciples: « Avec quelle difficulté ceux qui possèdent les richesses entreront-ils dans le royaume de Dieu! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Mais les disciples étaient terrifiés de son langage; sur quoi Jésus, prenant derechef la parole leur dit: « Mes enfants, qu\'il est difficile d\'entrer dans le royaume de Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Il est plus facile qu\'un chameau entre par le trou de l\'aiguille, qu\'un riche n\'entre dans le royaume de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Mais ils étaient encore plus stupéfaits, et ils lui disaient: « Et qui peut être sauvé? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Jésus, ayant fixé sur eux ses regards, leur dit: « Quant aux hommes, cela est impossible, mais non quant à Dieu; car tout est possible quant à Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Pierre se mit à lui dire: « Voici, pour nous, nous avons tout abandonné, et nous t\'avons suivi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Jésus lui dit: « En vérité je vous le déclare, il n\'est personne qui, ayant abandonné maison, ou frères, ou sœurs, ou mère, ou père, ou enfants, ou champs, à cause de moi et de l\'évangile,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'ne reçoive au centuple maintenant dans ce temps-ci maisons, et frères et sœurs, et mères, et enfants, et champs, avec des persécutions, et dans le siècle à venir la vie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Mais plusieurs seront des premiers, quoique des derniers, et les derniers, quoique des premiers. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Or ils étaient en chemin pour monter à Jérusalem, et Jésus les précédait, et ils étaient terrifiés; mais il y en eut qui le suivaient avec effroi. Et ayant derechef pris à lui les douze, il se mit à leur annoncer ce qui allait lui arriver:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, '« Voici, nous montons à Jérusalem, et le fils de l\'homme sera livré aux grands prêtres et aux scribes, et ils le condamneront à mort, et ils le livreront aux Gentils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'et ils le bafoueront, et ils cracheront sur lui, et ils le fustigeront, et ils le mettront à mort, et au bout de trois jours il ressuscitera. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Et Jacques et Jean, les deux fils de Zébédée, s\'approchent de lui, en lui disant: « Maître, nous désirons que tu fasses pour nous tout ce que nous te demanderons. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Et il leur dit: « Que désirez-vous que je fasse pour vous? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Et ils lui dirent: « Accorde-nous d\'être assis l\'un à ta droite et l\'autre à ta gauche dans ta gloire. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Mais Jésus leur dit: « Vous ne savez ce que vous demandez. Pouvez-vous boire la coupe que moi je dois boire, ou être baptisés du baptême dont moi je dois être baptisé? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Et ils lui dirent: « Nous le pouvons. » Mais Jésus leur dit: « Vous boirez la coupe que moi je dois boire, et vous serez baptisés du baptême dont moi je dois être baptisé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'mais pour ce qui est d\'être assis à ma droite ou à ma gauche, il ne dépend pas de moi de l\'accorder, sauf à ceux pour-lesquels cela a été préparé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Ce que les dix ayant entendu, ils commencèrent à s\'indigner contre Jacques et Jean;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'et Jésus les ayant appelés à lui leur dit: « Vous savez que ceux qui s\'imaginent commander aux peuples les tyrannisent, et que leurs grands les oppriment;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'mais il n\'en est pas de même parmi vous; au contraire, celui qui voudra devenir grand parmi vous sera votre serviteur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'et celui qui voudra être le premier parmi vous sera l\'esclave de tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'En effet le fils de l\'homme non plus n\'est pas venu pour être servi, mais pour servir et pour donner sa vie comme une rançon pour plusieurs. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Et ils arrivent à Jéricho, et comme il sortait de Jéricho avec ses disciples et une foule considérable, le fils de Timée, Bartimée, mendiant aveugle, se trouvait assis sur le bord du chemin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Et ayant ouï que c\'était Jésus le Nazarénien, il se mit à s\'écrier: « Fils de David, Jésus, aie pitié de moi! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Et plusieurs lui faisaient des remontrances, afin de le faire taire, mais il criait beaucoup plus fort: « Fils de David, aie pitié de moi! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Et Jésus s\'étant arrêté, dit: « Appelez-le. » Et ils appellent l\'aveugle, en lui disant: « Prends courage, lève-toi, il t\'appelle. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Et lui, ayant jeté son manteau, vint en sautant auprès de Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Et Jésus prenant la parole lui dit: « Que veux-tu que je fasse pour toi? » Et l\'aveugle lui dit: « Rabbouni, que je recouvre la vue? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Et Jésus lui dit: « Va, ta foi t\'a guéri. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Et quand ils arrivent près de Jérusalem, à Bedphagé et à Béthanie, vers la montagne des Oliviers, il dépêche deux de ses disciples,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'et leur dit: « Allez dans le village, qui est en face de vous, et dès que vous y serez entrés vous trouverez un ânon attaché, sur lequel aucun homme ne s\'est encore assis; détachez-le et amenez-le;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'et si quelqu\'un vous dit: Pourquoi faites-vous cela? dites: Le Seigneur en a besoin, et il le renvoie aussitôt ici. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Et ils s\'en allèrent, et ils trouvèrent un ânon attaché près d\'une porte, au dehors, sur la place, et ils le détachèrent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'et quelques-uns de ceux qui se trouvaient là leur disaient: « Pourquoi détachez-vous cet ânon? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Et eux leur répondirent comme Jésus l\'avait dit; et ils les laissèrent faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Et ils amènent l\'ânon à Jésus, et ils jettent sur lui leurs manteaux, et il s\'assit sur lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'et plusieurs étendirent leurs manteaux sur le chemin, et d\'autres des rameaux qu\'ils avaient coupés dans les champs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'et ceux qui précédaient et ceux qui suivaient s\'écriaient: « Hosanna! Béni soit celui qui vient au nom du Seigneur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Béni soit le royaume qui arrive de notre père David! Hosanna dans les lieux très hauts! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Et il entra à Jérusalem dans le temple; et après avoir porté ses regards sur tout ce qui l\'entourait, comme le soir était déjà venu, il repartit pour Béthanie avec les douze.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Et le lendemain, après qu\'ils furent sortis de Béthanie, il eut faim;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'et ayant vu de loin un figuier couvert de feuilles, il s\'approcha pour voir si peut-être il y trouverait quelque chose; et après s\'en être approché il n\'y trouva rien que des feuilles, car ce n\'était pas le moment des figues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Et prenant la parole, il lui dit: « Que personne ne mange plus jamais de toi aucun fruit. » Et ses disciples l\'entendaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Et ils arrivent à Jérusalem. Et lorsqu\'il fut entré dans le temple, il se mit à expulser ceux qui vendaient et ceux qui achetaient dans le temple, et il renversa les tables des changeurs, et les sièges de ceux qui vendaient les colombes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'et il ne permettait pas que personne transportât aucun ustensile au travers du temple;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'et il enseignait et disait: « N\'est-il pas écrit: Ma maison sera appelée une maison de prière par toutes les nations; mais vous, vous en avez fait une caverne de brigands? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Et les grands prêtres et les scribes l\'entendirent, et ils cherchaient comment ils pourraient le faire périr; car ils le craignaient, parce que toute la foule était stupéfaite de son enseignement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Et lorsque le soir fut venu, ils sortaient de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Et en repassant le matin, ils virent le figuier séché jusques aux racines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Et Pierre s\'étant ressouvenu lui dit: « Rabbi, regarde, le figuier que tu as maudit a séché. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Et Jésus leur réplique: « Ayez foi en Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'En vérité je vous déclare que celui qui aura dit à cette montagne: Déplace-toi et te jette dans la mer; et qui n\'aura point douté en son cœur, mais qui croit que ce qu\'il dit se fait, cela se réalisera pour lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'C\'est pourquoi je vous le déclare: tout ce que vous implorez et demandez, croyez que vous l\'avez reçu, et cela se réalisera pour vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Et lorsque vous serez debout pour prier, pardonnez si vous avez quelque chose contre quelqu\'un, afin que votre Père aussi qui est dans les cieux vous pardonne vos fautes. » [');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Mais si vous ne pardonnez pas, votre Père qui est dans le cieux, ne vous pardonnera pas non plus vos fautes.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'Et ils arrivent derechef à Jérusalem, et pendant qu\'il se promenait lui-même dans le temple les grands prêtres et les scribes et les anciens viennent à lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'et ils lui disaient: « En vertu de quelle autorité fais-tu ces choses? Ou qui est-ce qui t\'a donné cette autorité pour faire ces choses? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Mais Jésus leur dit: « Je vous adresserai une seule question; et répondez-moi, et je vous dirai en vertu de quelle autorité je fais ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Le baptême de Jean venait-il du ciel ou des hommes? Répondez-moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Et ils réfléchissaient entre eux, en disant: « Si nous disons: du ciel, il dira: Pourquoi donc ne l\'avez-vous pas cru?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Au contraire, disons-nous: des hommes?... » Ils craignaient la foule, car tous tenaient Jean pour avoir été réellement un prophète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Et ils répliquent à Jésus: « Nous ne savons. » Et Jésus leur dit: « Moi non plus je ne vous dis pas en vertu de quelle autorité je fais ces choses. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Et il commença à leur parler en paraboles: « Un homme planta une vigne, et il l\'entoura d\'une clôture, et il creusa un pressoir, et il construisit une tour; et il l\'afferma à des vignerons, et il s\'en alla.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Et il dépêcha auprès des vignerons au temps voulu un esclave, afin qu\'il reçût des vignerons une part de la récolte de la vigne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'et s\'étant saisis de lui ils le battirent, et le renvoyèrent les mains vides.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Et il dépêcha derechef auprès d\'eux un autre esclave, et celui-là ils le frappèrent à la tête et l\'outragèrent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'et il en dépêcha un autre, et celui-là ils le tuèrent; et plusieurs autres, dont ils battirent ceux-ci et tuèrent ceux-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Il avait encore un seul fils bien-aimé. Il le dépêcha le dernier auprès d\'eux, en se disant: Ils respecteront mon fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Mais ces vignerons se dirent entre eux: « Celui-ci est l\'héritier, venez, tuons-le, et l\'héritage nous appartiendra. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Et s\'étant saisis de lui, ils le tuèrent, et le jetèrent hors de la vigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Que fera le propriétaire de la vigne? Il viendra et fera périr les vignerons, et il donnera la vigne à d\'autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Vous n\'avez pas lu non plus ce passage de l\'écriture: La pierre que les constructeurs ont rejetée est celle qui est devenue le sommet de l\'angle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'c\'est par la volonté du Seigneur qu\'elle l\'est devenue, et il est admirable à nos yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Et ils cherchaient à s\'emparer de lui, et ils craignirent la foule, (ils avaient en effet compris que c\'était contre eux qu\'il avait prononcé la parabole), et l\'ayant quitté, ils s\'en allèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Et ils députent auprès de lui quelques-uns des pharisiens et des Hérodiens, afin de le prendre par un mot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Et étant venus ils lui disent: « Maître, nous savons que tu es véridique, et que tu ne fais pas acception de personnes, car tu ne regardes pas à l\'apparence des hommes, mais tu enseignes avec vérité la voie de Dieu. Est-il permis ou non de payer l\'impôt à l\'empereur? Payerons-nous, ou ne payerons-nous pas? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Mais lui, connaissant leur hypocrisie, leur dit: « Pourquoi me mettez-vous à l\'épreuve? Apportez-moi un denier, afin que je le voie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Et ils le lui apportèrent. Et il leur dit: « De qui est cette effigie et cette légende? » Et ils lui dirent: « De l\'empereur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Et Jésus dit: « Rendez à l\'empereur ce qui est à l\'empereur, et à Dieu ce qui est à Dieu. » Et ils s\'émerveillaient à son sujet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Surviennent auprès de lui des sadducéens, gens qui disent qu\'il n\'y a pas de résurrection, et ils l\'interrogeaient en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, '« Maître, Moïse nous a prescrit que, si le frère de quelqu\'un vient à mourir et laisse une femme et ne laisse pas d\'enfant, son frère prenne sa femme et suscite une postérité à son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Il y avait sept frères; et le premier prit une femme, et en mourant ne laissa point de postérité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'et le second la prit, et il mourut sans laisser de postérité; et le troisième de même;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'et les sept n\'ont point laissé de postérité; après eux tous la femme mourut aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Lors de la résurrection, duquel d\'entre eux sera-t-elle femme? Car les sept l\'ont eue pour femme? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Jésus leur dit: « Ne vous égarez-vous point parce que vous ne connaissez ni les écritures, ni la puissance de Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Car lorsqu\'ils seront ressuscités des morts, ni les hommes ne prennent des femmes, ni les femmes des maris, mais ils sont comme les anges qui sont dans les cieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Or, quant à ce que les morts ressuscitent, n\'avez-vous pas lu dans le livre de Moïse, à l\'endroit du buisson, comment Dieu lui dit: Je suis le Dieu d\'Abraham, et le Dieu d\'Isaac, et le Dieu de Jacob?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Il n\'est pas le Dieu des morts, mais des vivants; vous êtes dans un grand égarement. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Et l\'un des scribes, qui, ayant entendu leur discussion, avait reconnu qu\'il leur avait bien répliqué, s\'approcha et lui demanda: « Quel commandement est le premier de tous? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Jésus lui répliqua: « Le premier est: Ecoute Israël, le Seigneur notre Dieu est seul Seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'et, tu aimeras le Seigneur ton Dieu de tout ton cœur, et de toute ton âme, et de toute ta pensée, et de toute ta force.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Voici le second: Tu aimeras ton prochain comme toi-même. Il n\'y a pas d\'autre commandement plus grand que ceux-là. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Le scribe lui dit: « Bien, maître; tu as dit avec vérité qu\'il l\'est seul, et qu\'il n\'y en a point d\'autre que Lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'et que L\'aimer de tout son cœur, et de. tout son esprit, et de toute sa force, et aimer le prochain comme soi-même, l\'emporte de beaucoup sur tous les holocaustes et les sacrifices. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Et Jésus, voyant qu\'il avait répliqué avec sagacité, lui dit: « Tu n\'es pas loin du royaume de Dieu. » Et personne n\'osait plus l\'interroger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Et Jésus ayant repris la parole, disait en enseignant dans le temple: « Comment les scribes disent-ils que le Christ est fils de David?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'David lui-même a dit par l\'esprit saint: Le Seigneur a dit à mon seigneur: Assieds-toi à Ma droite, jusques à ce que J\'aie mis tes ennemis sous tes pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'David lui-même l\'appelle seigneur; eh bien, d\'où vient qu\'il est son fils? » Et la foule nombreuse l\'écoutait avec plaisir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Et il disait dans son enseignement: « Soyez en garde contre les scribes qui aiment à se promener en robes, et les salutations dans les places publiques,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'et les premiers sièges dans les synagogues, et les premières places dans les repas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'Ceux qui dévorent les maisons des veuves et qui par dissimulation font de longues prières, ceux-là recevront une punition d\'autant plus sévère. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Et s\'étant assis en face du trésor, il regardait comment la foule jetait de la monnaie dans le trésor, et plusieurs riches en jetaient beaucoup;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'et une veuve pauvre étant venue jeta deux pites, ce qui fait un quadrant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Et ayant appelé à lui ses disciples, il leur dit: « En vérité je vous déclare que cette veuve pauvre a jeté plus que tous ceux qui jetaient dans le trésor;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'car tous ont jeté de leur superflu, tandis que cette femme a jeté, de son dénuement, tout ce qu\'elle avait, toute sa subsistance. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Et comme il sortait du temple un de ses disciples lui dit: « Maître, regarde; quelles pierres! et quels édifices! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Et Jésus lui dit: « Vois-tu ces grands édifices? Il ne sera certainement pas laissé ici pierre sur pierre qui ne soit certainement démolie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Et pendant qu\'il était assis sur la montagne des Oliviers, en face du temple, Pierre, et Jacques, et Jean, et André lui demandèrent en particulier:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, '« Dis-nous, quand cela aura-t-il lieu? Et quel sera le signe que toutes ces choses seront sur le point de s\'accomplir? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Or Jésus commença à leur dire: « Prenez garde que personne ne vous égare;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'beaucoup viendront en mon nom, disant c\'est moi qui le suis, et ils en égareront plusieurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Mais quand vous entendrez parler de guerres et de bruits de guerres, ne vous en laissez pas troubler; il faut que cela arrive, mais ce n\'est pas encore la fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'En effet une nation s\'élèvera contre une nation, et un royaume contre un royaume; il y aura ici et là des tremblements de terre; il y aura des famines; ces choses-là sont le commencement des douleurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Mais prenez garde à vous-mêmes: ils vous livreront aux tribunaux, et vous serez battus de verges dans les synagogues, et vous comparaîtrez devant des gouverneurs et des rois à cause de moi, pour leur servir de témoignage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'et il faut premièrement que l\'évangile soit prêché à toutes les nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Et lorsqu\'ils vous entraîneront pour vous livrer, ne vous inquiétez pas d\'avance de ce que vous aurez à dire, mais dites ce qui vous sera donné en ce moment-là; en effet ce n\'est pas vous qui parlez, mais l\'esprit saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Et un frère livrera son frère à la mort, et un père son enfant, et des enfants se soulèveront contre leurs parents et les feront mourir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'et vous serez haïs de tous, à cause de mon nom. Mais celui qui aura persévéré jusqu\'à la fin, celui-là sera sauvé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Or, quand vous aurez vu l\'œuvre abominable de la dévastation établie où il ne faut pas (que le lecteur y réfléchisse), alors que ceux qui sont en Judée s\'enfuient dans les montagnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'que celui qui est sur le toit ne descende pas, et n\'entre pas pour sortir quoi que ce soit de sa maison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'et que celui qui est aux champs ne revienne pas en arrière pour prendre son manteau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Mais malheur à celles qui sont enceintes, et à celles qui allaitent en ces jours-là!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Priez, afin que cela n\'ait pas lieu en hiver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Car ces jours-là seront une tribulation telle, qu\'il n\'y en a pas eu de semblable depuis le commencement de la création que Dieu a créée jusques à maintenant, et qu\'il n\'y en aura certainement jamais;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'et si le Seigneur n\'eût raccourci ces jours-là, qui que ce soit n\'eût été sauvé; mais à cause des élus qu\'il s\'est choisis Il a raccourci ces jours-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Et alors si quelqu\'un vous dit: « Regardez, le Christ est ici, et regardez, il est là, » ne le croyez pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'car il surgira de faux christs, et de faux prophètes, et ils feront des miracles et des prodiges, afin d\'égarer, s\'il est possible, les élus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Pour vous, soyez sur vos gardes; je vous ai tout prédit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, '« Mais en ces jours-là, après cette tribulation, le soleil s\'obscurcira, et la lune ne donnera pas sa lumière,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'et les astres tomberont du ciel, et les puissances qui sont dans les cieux seront ébranlées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Et alors ils verront le fils de l\'homme venant dans des nuées avec beaucoup de puissance et de gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Et alors il enverra les anges, et il rassemblera ses élus des quatre vents, de l\'extrémité de la terre jusqu\'à l\'extrémité du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Or, instruisez-vous par cette comparaison tirée du figuier: Lorsque ses branches commencent à se ramollir et qu\'il pousse ses feuilles, vous savez que l\'été est proche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'de même vous aussi, lorsque vous aurez vu ces choses arriver, sachez qu\'il est proche, qu\'il est à la porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'En vérité je vous déclare que cette génération-ci ne disparaîtra certainement point jusques à ce que toutes ces choses se soient réalisées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Le ciel et la terre passeront, mais mes paroles ne passeront point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Or, quant à ce jour-là ou à l\'heure personne n\'en sait rien, pas même un ange dans le ciel, pas même le Fils, mais le Père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Soyez sur vos gardes; veillez; car vous ne savez pas quand c\'est le moment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Comme un voyageur, après avoir quitté sa maison et remis l\'autorité à ses esclaves, à chacun selon sa besogne, à aussi donné des ordres au portier afin qu\'il veille,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'veillez donc; car vous ignorez quand doit venir le maître de la maison, si c\'est le soir, ou à minuit, ou au chant du coq, ou le matin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'de peur qu\'arrivant à l\'improviste, il ne vous trouve endormis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Or ce que je vous dis à vous, je le dis à tous: Veillez. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Or la Pâque et la fête des pains sans levain devait avoir lieu dans deux jours, et les grands prêtres et les scribes cherchaient de quelle manière ils pourraient par ruse s\'emparer de lui et le mettre à mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'car ils disaient: « Que ce ne soit pas pendant la fête, de peur qu\'il n\'y ait une émeute du peuple. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Et comme il se trouvait, à Béthanie dans la maison de Simon le lépreux, pendant qu\'il était à table survient une femme tenant une fiole d\'albâtre qui renfermait un parfum de véritable nard, très précieux; ayant brisé la fiole, elle la lui versa sur la tête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Mais il y avait là des gens qui s\'indignaient entre eux: « Pourquoi cette profusion de parfum s\'est-elle faite?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Car ce parfum pouvait être vendu plus de trois cents deniers, et être donné aux pauvres; » et ils le tançaient vertement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Mais Jésus dit: « Laissez-la faire; pourquoi lui faites-vous de la peine? Elle a accompli une bonne œuvre en ma personne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'en effet vous devez toujours avoir les pauvres avec vous, et quand vous le voudrez vous pouvez toujours leur faire du bien; mais moi vous ne devez pas m\'avoir toujours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Ce qu\'elle a pu, elle l\'a fait; elle s\'est occupée d\'avance de parfumer mon corps pour ma sépulture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Or, en vérité je vous déclare que où que l\'évangile soit prêché dans le monde entier, on parlera aussi de ce qu\'elle a fait, en mémoire d\'elle. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Et Judas Iscarioth, l\'un des douze, se rendit auprès des grands prêtres pour le leur livrer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'ce qu\'ayant ouï ils furent dans la joie, et ils promirent de lui donner de l\'argent; et il cherchait comment il aurait une bonne occasion de le livrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Et le premier jour de la fête des pains sans levain, époque où l\'on immolait la pâque, ses disciples lui disent: « Où veux-tu que nous allions faire les préparatifs pour que tu manges la pâque? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Et il dépêcha deux de ses disciples, et leur dit: « Allez à la ville, et vous rencontrerez un homme portant une cruche d\'eau, suivez-le,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'et où que ce soit qu\'il entre, dites au chef de famille: « Le maître dit: Où est la chambre où je dois manger la pâque avec mes disciples? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Et lui-même vous montrera une grande salle à manger garnie de lits, toute prête; faites-y les préparatifs pour nous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Et les disciples partirent et vinrent à la ville; et ils trouvèrent tout comme il le leur avait dit, et ils préparèrent la pâque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Et quand le soir fut venu, il arrive avec les douze.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Et pendant qu\'ils étaient à table et qu\'ils mangeaient, Jésus dit: « En vérité je vous déclare que l\'un d\'entre vous qui mangez avec moi me livrera. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Ils commencèrent à être saisis de tristesse et à lui dire l\'un après l\'autre: « Est-ce moi? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Mais il leur dit: « C\'est un des douze, celui qui trempe avec moi dans le plat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'En effet le fils de l\'homme s\'en va, il est vrai, selon ce qui est écrit de lui; mais malheur à cet homme par qui le fils de l\'homme est livré; il eût été bon pour lui que cet homme-là ne fût pas né. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Et pendant qu\'ils mangeaient, ayant pris du pain, il le rompit après avoir, prononcé une bénédiction, et il le leur donna et dit: « Prenez; ceci est mon corps. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Et ayant pris une coupe, il la leur donna après avoir rendu grâces, et ils en burent tous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'et il dit: « Ceci est mon sang, celui de l\'alliance, qui est versé pour plusieurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'En vérité je vous déclare que je ne boirai certainement plus du produit de la vigne, jusques à ce jour où j\'en boirai du nouveau dans le royaume de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Et après avoir chanté, ils sortirent pour se rendre à la montagne des Oliviers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Et Jésus leur dit: « Vous trébucherez tous, car il est écrit: Je frapperai le berger et les brebis seront dispersées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Mais après être ressuscité, je vous précéderai en Galilée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Or Pierre lui dit: « Quand même tous trébucheraient, non pas moi! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Et Jésus lui dit: « En vérité je te déclare que toi, aujourd\'hui, cette nuit même, avant que le coq ait chanté deux fois, tu m\'auras renié trois fois. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Mais il disait de plus belle: « S\'il me fallait mourir avec toi, je ne te renierai certainement pas; » et tous aussi disaient la même chose.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'Et ils arrivent dans un lieu dont le nom était Gétsémani, et il dit à ses disciples: « Asseyez-vous-jusques à ce que j\'aie prié. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Et il prend avec lui Pierre et Jacques et Jean; et il commença à être épouvanté et abattu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'et il leur dit: « Mon âme est triste jusques à la mort; demeurez ici et veillez. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Et s\'étant un peu avancé, il tombait à terre, et il priait afin que, s\'il était possible, le moment s\'éloignât de lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'et il disait: Abba, père, tout T\'est possible; fais passer cette coupe loin de moi; mais non pas ce que moi je veux, mais ce que Toi! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Et il vient, et il les trouve endormis, et il dit à Pierre: « Simon, dors-tu? Tu n\'as pas pu veiller une seule heure?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Veillez et priez, afin que vous n\'entriez pas en tentation; l\'esprit, il est vrai, est plein d\'élan, mais la chair est faible. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Et s\'étant retiré derechef, il pria en répétant les mêmes paroles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'et étant revenu de nouveau, il les trouva endormis; leurs yeux en effet étaient fort appesantis, et ils ne savaient que lui répondre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Et il revient pour la troisième fois, et il leur dit: « Dormez désormais et reposez-vous; il suffit; l\'heure est venue; voici, le fils de l\'homme va être livré aux mains des pécheurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'levez -vous, allons; voici, celui qui me livre s\'approche. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Et aussitôt, pendant qu\'il parlait, survient Judas, un des douze, et avec lui une foule armée d\'épées et de bâtons, envoyée par les grands prêtres et les scribes et les anciens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Or celui qui le livrait leur avait donné un signe convenu, en disant: « Celui que j\'embrasserai, c\'est lui; saisissez-le, et emmenez-le sous bonne garde. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Et s\'étant aussitôt approché de lui, il dit: « Rabbi, » et il lui donna un tendre baiser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Quant à eux, ils mirent la main sur lui, et se saisirent de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Mais l\'un des assistants ayant tiré l\'épée frappa l\'esclave du grand prêtre et lui enleva l\'oreille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Et Jésus prenant la parole leur dit: « Vous êtes sortis comme contre un brigand, avec des épées et des bâtons, pour me prendre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'tous les jours j\'étais près de vous dans le temple occupé à enseigner, et il ne se saisissait pas de moi; mais c\'est afin que les écritures fussent accomplies, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Et l\'ayant abandonné ils s\'enfuirent tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Et un certain jeune homme le suivait, enveloppé d\'un drap sur son corps nu, et on se saisit de lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'mais ayant abandonné son drap, il s\'enfuit tout nu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Et ils amenèrent Jésus auprès du grand prêtre; et chez lui se réunissent tous les grands prêtres et les anciens et les scribes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Et Pierre l\'avait suivi de loin jusques dans l\'intérieur de la cour du grand prêtre, et il se tenait assis avec les valets, et il se chauffait auprès du feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Or, les grands prêtres et le sanhédrin tout entier cherchaient un témoignage contre Jésus pour le faire mourir, et ils n\'en trouvaient point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Car plusieurs rendaient contre lui de faux témoignages, et les témoignages n\'étaient pas d\'accord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Et quelques individus s\'étant présentés rendaient contre lui un faux témoignage, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, '« Nous l\'avons entendu dire: Je détruirai ce sanctuaire fait de main d\'homme, et en trois jours j\'en rebâtirai un autre qui ne sera pas fait de main d\'homme. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Et même sur ce point-là leur témoignage n\'était pas d\'accord.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Et le grand prêtre s\'étant levé au milieu de l\'assemblée, interrogea Jésus en disant: « Ne réponds-tu rien? Car ceux-ci témoignent contre toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Mais il gardait le silence et ne répondait rien. Le grand prêtre l\'interrogeait derechef et lui dit: « Es-tu le Christ, le fils de Celui qui est béni? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Et Jésus dit: « Je le suis, et vous verrez le fils de l\'homme assis à la droite de la Puissance, et venant avec les nuées du ciel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Mais le grand prêtre ayant déchiré ses tuniques, dit: « Qu\'avons-nous encore besoin de témoins?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Vous avez ouï le blasphème. Que vous en semble? » Et ils jugèrent tous qu\'il méritait la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Et quelques-uns se mirent à cracher sur lui, et à lui voiler le visage, et à le souffleter, et à lui dire: « Prophétise; » et les valets le reçurent à coups de verges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Et pendant que Pierre était en bas dans la cour arrive une des servantes du grand prêtre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'et ayant vu Pierre qui se chauffait, elle lui dit, après l\'avoir regardé: « Toi aussi, tu étais avec le Nazarénien Jésus. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Mais il le nia en disant: « Je ne sais, ni ne comprends ce dont tu parles. » Et il se retira au dehors dans le vestibule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Et la servante l\'ayant vu dit aux assistants: « Celui-ci est des leurs. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Mais il le niait de nouveau. Et un instant après les assistants disaient derechef à Pierre: « Vraiment tu es des leurs, car tu es aussi Galiléen. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Mais il se mit à proférer des anathèmes et à dire avec serment: « Je ne connais point cet homme dont vous parlez, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Et aussitôt le coq chanta pour la seconde fois, et Pierre se souvint de la parole que Jésus lui avait dite: « Avant que le coq ait chanté deux fois, tu m\'auras renié trois fois. » Et cette pensée le faisait pleurer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Et dès le matin, les grands prêtres ayant tenu conseil avec les anciens et les scribes, et le sanhédrin tout entier, après avoir enchaîné Jésus, l\'emmenèrent et le livrèrent à Pilate.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Et Pilate lui demanda: « Es-tu le roi des Juifs? » Et il lui répliqua: « C\'est toi qui le dis. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Et les grands prêtres portaient contre lui de nombreuses accusations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Mais Pilate l\'interrogeait de nouveau, en disant: « Est-ce que tu ne réponds pas? Vois de combien de choses ils t\'accusent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Cependant Jésus ne répliqua plus rien, en sorte que Pilate était tout émerveillé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Or il leur accordait lors d\'une fête l\'élargissement d\'un prisonnier, celui qu\'ils demandaient;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'or le nommé Barabbas se trouvait enchaîné avec les séditieux qui, dans la sédition, avaient commis un meurtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Et la foule étant montée, commença à réclamer ce qu\'il faisait ordinairement pour eux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'et Pilate leur répliqua: « Voulez-vous que je vous élargisse le roi des Juifs? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Car il savait que c\'était par jalousie qu\'ils l\'avaient livré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Mais les grands prêtres soulevèrent la foule, afin qu\'il leur élargît plutôt Barabbas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Or Pilate prenant de nouveau la parole leur disait: « Que ferai-je donc, dites-moi, du roi des Juifs? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Et ils crièrent derechef: « Crucifie-le. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Mais Pilate leur disait: « Eh! quel mal a-t-il fait? » Mais eux crièrent de plus belle: « Crucifie-le. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Or Pilate, voulant satisfaire la foule, leur, accorda l\'élargissement de Barabbas, et livra Jésus après l\'avoir fait flageller, afin qu\'il fût crucifié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Cependant les soldats l\'emmenèrent dans l\'intérieur de la cour (c\'est le prétoire), et ils convoquent toute la cohorte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'Et ils le revêtent de pourpre; et ils le ceignent, après l\'avoir tressée, d\'une couronne d\'épines;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'et ils se mirent à le saluer: « Salut, roi des Juifs; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'et ils lui frappaient la tête avec un roseau, et ils crachaient sur lui, et se mettant à genoux ils l\'adoraient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Et lorsqu\'ils l\'eurent bafoué, ils le dépouillèrent de la pourpre et le revêtirent de ses vêtements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Et ils l\'emmenèrent pour le crucifier; et ils mettent en réquisition, comme il passait, un certain Simon de Cyrène qui revenait des champs (le père d\'Alexandre et de Rufus), afin qu\'il portât sa croix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Et ils le conduisent à l\'endroit de Golgotha (qui signifie, étant traduit, endroit du crâne).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Et ils lui donnaient du vin parfumé, mais lui ne le prit pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Et ils le crucifient, et ils partagent ses vêtements, en les tirant au sort pour savoir ce que chacun prendrait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Or c\'était la troisième heure, et ils le crucifièrent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'et l\'inscription de sa sentence portait les mots: Le roi des Juifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Et avec lui ils crucifièrent deux brigands, un à sa droite et un à sa gauche. [');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'Et ce passage de l\'Écriture a été accompli, qui dit: « Et il a été compté parmi les criminels »]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Et les passants l\'injuriaient, en branlant la tête et en disant: « Ohé! toi qui détruis le temple et qui le rebâtis en trois jours,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'sauve-toi toi-même en descendant de la croix! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'De même aussi les grands prêtres, le bafouant entre eux avec les scribes, disaient: « Il en a sauvé d\'autres, il ne peut se sauver lui-même!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Que le Christ, le roi d\'Israël, descende maintenant de la croix, afin que nous voyions et que nous croyions! » Et ceux qui étaient crucifiés avec lui l\'insultaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Et quand la sixième heure fut venue, des ténèbres survinrent sur la terre entière jusques à la neuvième heure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'Et à la neuvième heure, Jésus s\'écria en jetant un grand cri: « Eloi! Eloi! Lama sabaphthani? » ce qui signifie, étant traduit: « Mon Dieu, pourquoi m\'as-Tu abandonné? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Et quelques-uns des assistants l\'ayant entendu, disaient: « Voyez, il appelle Élie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Mais quelqu\'un étant accouru, et ayant rempli une éponge de vinaigre et l\'ayant fixée à un roseau, lui donnait à boire, en disant: « Laissez, voyons si Élie vient le descendre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Mais Jésus ayant poussé un grand cri expira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Et le rideau du sanctuaire se déchira en deux du haut en bas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Mais le centurion, qui se tenait en face de lui, ayant vu qu\'il avait expiré de la sorte, dit: « Vraiment cet homme était fils de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Or il y avait aussi des femmes qui regardaient de loin, parmi lesquelles aussi Marie la Magdalène, et Marie mère de Jacques le petit, et la mère de Josès, et Salomé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'lesquelles, lorsqu\'il était en Galilée, le suivaient et le servaient, et beaucoup d\'autres qui étaient montées avec lui à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Et comme le soir était déjà venu (parce que c\'était la préparation, c\'est-à-dire l\'avant-sabbat),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'arriva Joseph d\'Arimathée, sénateur de distinction, qui lui aussi attendait le royaume de Dieu, et il s\'introduisit hardiment auprès de Pilate, et réclama le corps de Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Mais Pilate s\'étonna qu\'il fût déjà mort, et ayant fait appeler le centurion, il lui demanda si déjà il était mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'et l\'ayant appris du centurion, il fit don du cadavre à Joseph.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Et ayant acheté un linceul, il l\'enveloppa dans le linceul après l\'avoir descendu, et il le déposa dans un sépulcre, qui avait été taillé dans le roc, et il roula une pierre contre l\'entrée du sépulcre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Or Marie la Magdalène et Marie mère de Josès regardaient où on le mettait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Et quand le sabbat fut passé Marie la Magdalène, et Marie mère de Jacques, et Salomé, achetèrent des aromates, afin de venir l\'embaumer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Et de très grand matin, le premier jour de la semaine, elles viennent au sépulcre, comme le soleil venait de se lever.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Et elles se disaient entre elles: « Qui est-ce qui nous roulera la pierre de devant l\'entrée du sépulcre? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Et ayant levé les yeux, elles voient que la pierre avait été roulée; car elle était très grande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Et étant arrivées au sépulcre, elles voient un jeune homme assis sur la droite, vêtu d\'une robe blanche, et elles furent dans l\'épouvante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Mais il leur dit: « Ne vous épouvantez point; vous cherchez Jésus le Nazarénien qui a été crucifié; il est ressuscité, il n\'est pas ici; voici la place où ils l\'avaient mis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Mais allez, dites à ses disciples et à Pierre: « Il vous devance en Galilée; c\'est là que vous le verrez, comme il vous l\'a dit. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Et étant sorties, elles s\'enfuirent du sépulcre, car la terreur et l\'effroi les avaient saisies. Et elles ne dirent rien à personne, car elles avaient peur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Or étant ressuscité sur le matin, le premier jour de la semaine, il apparut d\'abord à Marie la Magdalène, de laquelle il avait chassé sept démons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Celle-ci s\'en alla en informer ceux qui, ayant été avec lui, se trouvaient dans le deuil et les larmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Et ceux-ci, en entendant dire qu\'il vivait et qu\'il avait été vu par elles, furent incrédules.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Mais après cela il se manifesta sous une autre forme à deux d\'entre eux qui étaient en marche pour se rendre aux champs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'et ceux-ci s\'en allèrent en informer les autres, mais ils ne crurent pas non plus ceux-ci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Mais enfin il se manifesta aux onze eux-mêmes pendant qu\'ils étaient à table, et il leur fit honte de leur incrédulité et de leur dureté de cœur, pour n\'avoir pas cru ceux qui l\'avaient contemplé ressuscité des morts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'et il leur dit: « Allez dans le monde entier prêcher l\'évangile à toute la création;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'celui qui aura cru et qui aura été baptisé sera sauvé; mais celui qui n\'aura pas cru sera condamné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Or voici les signes qui accompagneront ceux qui auront cru: en mon nom ils chasseront les démons; ils parleront en langues nouvelles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'ils prendront des serpents; lors même qu\'ils boiraient quelque breuvage mortel, il ne leur nuira certainement pas; ils imposeront les mains aux malades, et ils guériront. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Ainsi donc, tandis que le Seigneur, après leur avoir parlé, fut enlevé dans le ciel et s\'assit à la droite de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'ceux-ci de leur côté s\'en allèrent prêcher partout; le Seigneur coopérant avec eux et confirmant la parole par les signes qui l\'accompagnaient.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Comme plusieurs ont entrepris de composer un récit des choses qui sont reçues parmi nous avec une entière assurance');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'conformément à ce que nous ont transmis ceux qui, dès le commencement, ont été témoins oculaires et ministres de la parole,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'il m\'a aussi semblé bon à moi, qui me suis mis au courant de tout dès le début avec exactitude, d\'écrire pour toi une narration suivie, excellent Théophile,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'afin que tu connaisses la certitude des enseignements que tu as reçus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Il y eut du temps d\'Hérode, roi de Judée, un certain prêtre, nommé Zacharie, appartenant à la classe d\'Abia; et il avait une femme qui appartenait aux filles d\'Aaron, et son nom était Élisabeth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Or ils étaient l\'un et l\'autre justes devant Dieu, observant d\'une manière irréprochable tous les commandements et décrets du Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Et ils n\'avaient pas d\'enfant, vu qu\'Élisabeth était stérile, et ils étaient l\'un et l\'autre avancés en âge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Or, il advint, pendant qu\'il remplissait, lors du tour de sa classe, sa charge de prêtre devant Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'que le sort l\'appela, selon l\'usage de la prêtrise, à offrir l\'encens en entrant dans le sanctuaire du Seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'et toute la multitude du peuple était en prière au dehors à l\'heure de l\'encens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Or un ange du Seigneur, qui se tenait à droite de l\'autel de l\'encens, lui apparut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'et Zacharie fut troublé en le voyant, et la crainte s\'empara de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Mais l\'ange lui dit: « Ne crains point, Zacharie, car ta prière a été entendue, et ta femme Élisabeth t\'enfantera un fils, et tu lui donneras le nom de Jean;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'et il sera pour toi une cause de joie et d\'allégresse, et plusieurs se réjouiront de sa naissance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'car il sera grand devant le Seigneur, et il ne boira absolument point de vin ni de cervoise, et il sera rempli de l\'esprit saint pendant qu\'il sera encore dans le ventre de sa mère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'et il ramènera plusieurs des fils d\'Israël au Seigneur leur Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'et lui-même marchera devant Lui avec l\'esprit et la puissance d\'Élie, pour ramener vers les enfants les cœurs des pères, et les rebelles aux sentiments des justes, afin de préparer pour le Seigneur un peuple bien disposé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Et Zacharie dit à l\'ange: « A quoi reconnaîtrai-je cela? Car je suis un vieillard, et ma femme est avancée en âge? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Et l\'ange lui répliqua: « Je suis Gabriel, qui me tiens devant Dieu, et j\'ai été envoyé pour te parler et t\'annoncer cette bonne nouvelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Et voici, tu seras muet et sans pouvoir parler jusques au jour où cela se réalisera, parce que tu n\'as pas cru à mes paroles, qui s\'accompliront en leur temps. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Et le peuple attendait Zacharie, et l\'on s\'étonnait de ce qu\'il s\'arrêtait dans le sanctuaire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'mais lorsqu\'il fut sorti il ne pouvait leur parler, et ils comprirent qu\'il avait eu une vision dans le sanctuaire; et lui-même leur faisait des signes, et il demeura muet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Et il advint, lorsque le temps de son service fut terminé, qu\'il retourna dans sa demeure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Or après ce temps-là Élisabeth sa femme conçut, et elle se cacha durant cinq mois,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, '« parce que, » disait-elle, « le Seigneur a ainsi agi envers moi au moment où Il a daigné effacer mon opprobre parmi les hommes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Or, au sixième mois l\'ange Gabriel fut envoyé de Dieu dans une ville de Galilée, nommée Nazareth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'auprès d\'une vierge fiancée à un homme nommé Joseph, qui appartenait à la famille de David, et le nom de la vierge était Marie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'Et étant entré auprès d\'elle, il lui dit: « Salut, toi qui es comblée de grâces, le Seigneur est avec toi! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Mais elle fut troublée de cette parole, et elle réfléchissait sur ce que pouvait signifier une telle salutation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Et l\'ange lui dit: « Ne crains point, Marie; car tu as trouvé grâce auprès de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'et voici, tu concevras en ton sein et tu mettras au monde un fils, et tu lui donneras le nom de Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Il sera grand, et il sera appelé Fils du Très-Haut, et le Seigneur Dieu lui donnera le trône de David son père,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'et il régnera sur la maison de Jacob pour les siècles, et son règne n\'aura point de fin. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Mais Marie dit à l\'ange: « Comment cela se fera-t-il, puisque je ne connais point d\'homme? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'Et l\'ange lui répliqua: « L\'Esprit saint descendra sur toi, et une puissance du Très-Haut te couvrira; c\'est pourquoi aussi l\'être saint qui sera engendré sera appelé Fils de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Et voici, Élisabeth ta parente a, elle aussi, conçu un fils en sa vieillesse, et elle est maintenant dans son sixième mois, elle qui était appelée stérile;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'car rien de ce qui vient de Dieu ne sera frappé d\'impuissance. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Or Marie dit: « Voici la servante du Seigneur; qu\'il me soit fait selon ta parole. » Et l\'ange s\'éloigna d\'elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Or Marie s\'étant mise en route en ces jours-là se rendit en toute hâte dans la montagne, dans une ville de Juda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'et elle entra dans la maison de Zacharie et salua Élisabeth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Et il advint, lorsque Élisabeth entendit la salutation de Marie, que l\'enfant bondit dans son sein, et Élisabeth fut remplie de l\'Esprit saint,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'et elle poussa un grand cri, et dit: « Tu es bénie entre les femmes, et le fruit de ton sein est béni!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Et comment m\'est-il accordé que la mère de mon Seigneur vienne à moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Car voici, lorsque la voix de ta salutation est parvenue à mes oreilles, l\'enfant a bondi d\'allégresse dans mon sein.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Et bienheureuse celle qui a cru à l\'accomplissement de ce qui lui a été dit par le Seigneur! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Et Marie dit: « Mon âme exalte le Seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'et mon esprit s\'est réjoui en Dieu mon sauveur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'parce qu\'il a jeté les yeux sur la bassesse de Sa servante. Car voici, dès maintenant toutes les générations m\'appelleront bienheureuse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'parce que le Tout-puissant a fait pour moi de grandes choses. Et Son nom est saint,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'et Sa miséricorde repose de générations en générations sur ceux qui Le craignent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Il a exercé la force avec Son bras; Il a dispersé ceux qui s\'enorgueillissaient dans les pensées de leur cœur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Il a renversé du trône les potentats et Il a élevé les humbles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Il a rassasié de biens les affamés, et Il a renvoyé les riches dénués de tout;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Il s\'est intéressé à Israël Son serviteur, et Il a eu souvenance de Sa miséricorde,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'comme Il l\'avait dit à nos pères, envers Abraham et sa postérité pour l\'éternité. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Or Marie demeura avec elle environ trois mois, puis elle revint en sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Or, le moment où Élisabeth devait accoucher arriva, et elle mit au monde un fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Et ses voisins et ses parents apprirent que le Seigneur avait fait éclater envers elle Sa miséricorde, et ils se réjouissaient avec elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Et il arriva qu\'on vint au huitième jour circoncire l\'enfant; et on lui donnait le nom de son père, Zacharie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'mais sa mère prenant la parole dit: « Non, mais il sera appelé Jean. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Et on lui dit: « Il n\'est personne de ta parenté qui porte ce nom-là! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'Mais on demanda par signes à son père quel nom il voulait qu\'on lui donnât.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Et ayant demandé des tablettes il écrivit ces mots: « Jean est son nom. » Et ils furent tous émerveillés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Or sa bouche s\'ouvrit aussitôt et sa langue se délia et il proférait les louanges de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Et la crainte s\'empara de tous leurs voisins, et dans toute la montagne de Judée on se répétait tous ces récits,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'et tous ceux qui les avaient entendus les serraient dans leur cœur, en disant: « Que sera donc ce petit enfant? » Et en effet la main du Seigneur était avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Et Zacharie son père fut rempli de l\'Esprit saint, et prophétisa en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, '« Béni soit le Seigneur Dieu d\'Israël, de ce qu\'il a visité et racheté Son peuple;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'de ce qu\'il nous a suscité une victorieuse délivrance dans la maison de David Son serviteur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'selon ce qu\'il avait dit de tout temps par la bouche de Ses saints prophètes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'délivrance de nos ennemis et de la main de tous ceux qui nous haïssent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'voulant faire miséricorde à nos pères et se souvenir de Sa sainte alliance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'du serment qu\'il avait fait à Abraham notre père');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'de nous permettre, après avoir été délivrés de la main des ennemis, de Lui rendre un culte sans crainte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'en suivant la piété et la justice devant Lui, durant toute notre vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Mais toi aussi, petit enfant, tu seras appelé prophète du Très-Haut, car tu marcheras devant le Seigneur pour préparer Ses voies,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'afin de donner à Son peuple la connaissance du salut par la rémission de leurs péchés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'à cause des entrailles de miséricorde de notre Dieu, grâces auxquelles une aurore d\'en haut nous visitera');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'pour éclairer ceux qui sont assis dans les ténèbres et dans l\'ombre de la mort, afin de diriger nos pieds dans le chemin de la paix. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Or le petit enfant grandissait et se fortifiait en esprit, et il se tenait dans les déserts jusques au jour de sa manifestation à Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Or il advint en ce temps-là qu\'un décret fut promulgué par l\'empereur Auguste pour le recensement de toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Ce fut un premier recensement qui eut lieu pendant que Quirinius gouvernait la Syrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Et tous allaient se faire enregistrer, chacun dans sa propre ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Joseph aussi monta de Galilée, de la ville de Nazareth, en Judée, dans la ville de David qui est appelée Bethléem, parce qu\'il était de la famille et de la branche de David,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'afin de se faire enregistrer avec Marie qui lui avait été fiancée, laquelle était enceinte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Or il advint, pendant qu\'ils étaient là, que le moment où elle devait accoucher arriva,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'et elle mit au monde son fils premier-né, et elle l\'emmaillota, et elle le coucha dans une crèche, parce qu\'ils n\'avaient pas de place dans l\'hôtellerie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Et il y avait aux champs dans la même contrée des bergers qui passaient les veilles de la nuit à garder leur troupeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Et un ange du Seigneur apparut au-dessus d\'eux, et la gloire du Seigneur les enveloppa de lumière, et ils furent saisis d\'une très grande crainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Et l\'ange leur dit: « Ne craignez point; car, voici, je vous apporte une bonne nouvelle qui sera pour tout le peuple le sujet d\'une grande joie:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'c\'est qu\'aujourd\'hui vous est né, dans la ville de David, un sauveur, qui est Christ le Seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'et ce qui en sera pour vous un signe, c\'est que vous trouverez un enfant emmailloté et couché dans une crèche. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Et aussitôt se joignit à l\'ange une multitude de l\'armée du ciel, louant Dieu et disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, '« Gloire à Dieu dans les lieux très-hauts! Et paix sur la terre parmi les hommes de prédilection! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Et il advint, lorsque les anges les eurent quittés pour regagner le ciel, que les bergers se disaient les uns aux autres: « Eh bien! allons jusques à Bethléem, et voyons l\'accomplissement de cette parole que le Seigneur nous a fait connaître. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Et ils vinrent en toute hâte, et ils trouvèrent Marie et Joseph, et le petit enfant couché dans la crèche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Or, après l\'avoir vu, ils firent connaître ce qui leur avait été dit touchant ce petit enfant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Et tous les auditeurs furent émerveillés de ce que leur disaient les bergers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Mais Marie retenait toutes ces paroles, en les méditant dans son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Et les bergers s\'en retournèrent, glorifiant et louant Dieu de tout ce qu\'ils avaient ouï et vu conformément à ce qui leur avait été dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Et, lorsque les huit jours au bout desquels on devait le circoncire furent accomplis, on lui donna aussi le nom de Jésus, qu\'avait indiqué l\'ange avant qu\'il eût été conçu dans le sein de sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Et, lorsque le temps de leur purification fut accompli selon la loi de Moïse, ils le conduisirent à Jérusalem, pour le présenter au Seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, 'conformément à ce qui est écrit dans la loi du Seigneur, que tout mâle premier-né sera consacré au Seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'et pour offrir en sacrifice, selon ce qui est prescrit dans la loi du Seigneur, un couple de tourterelles ou deux jeunes colombes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'Et voici, il y avait à Jérusalem un homme dont le nom était Siméon; et cet homme était juste et pieux, vivant dans l\'attente de la consolation d\'Israël; et l\'Esprit saint reposait sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Et il avait été informé par l\'Esprit saint qu\'il ne verrait pas la mort avant d\'avoir vu le Christ du Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Et il vint dans le temple par l\'inspiration de l\'Esprit; et lorsque les parents amenèrent le petit enfant Jésus, pour accomplir à son égard les usages de la loi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'ce fut lui qui le reçut dans ses bras, et il bénit Dieu et dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, '« Maintenant, ô Souverain, Tu renvoies Ton esclave en paix, selon Ta parole;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'car mes yeux ont vu Ton salut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'que Tu as préparé à la face de tous les peuples,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'comme une lumière qui doit être révélée aux gentils, et comme la gloire de Ton peuple d\'Israël. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Et son père et sa mère étaient émerveillés de ce qu\'on disait de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Et Siméon les bénit, et dit à Marie sa mère: « Voici, celui-ci est destiné à amener la chute et le relèvement de plusieurs en Israël, et à être un signe qui sera contredit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '(et une épée transpercera ta propre âme), afin que du fond de plusieurs cœurs des pensées soient mises au jour. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Et là se trouvait Anne, prophétesse, fille de Phanouel de la tribu d\'Aser. Cette femme (fort avancée en âge, puisqu\'après avoir vécu avec un mari sept ans depuis sa virginité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'elle avait atteint dans son veuvage l\'âge de quatre-vingt-quatre ans), cette femme qui ne bougeait du temple, où elle rendait à Dieu nuit et jour un culte par des jeûnes et des prières,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'et qui était survenue en ce moment même, adressait des actions de grâces à Dieu et parlait de Lui à tous ceux qui attendaient la rédemption de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Et lorsqu\'ils eurent accompli tout ce qui était prescrit par la loi du Seigneur, ils retournèrent en Galilée dans leur ville de Nazareth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Cependant le petit enfant grandissait et se fortifiait, étant rempli de sagesse; et la grâce de Dieu était sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Et ses parents se rendaient, chaque année à Jérusalem lors de la fête de Pâque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Et quand il eut douze ans, comme ils étaient montés selon la coutume de la fête,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'et qu\'après en avoir célébré les divers jours, ils s\'en retournaient, le jeune Jésus resta à Jérusalem, et ses parents ne s\'en aperçurent point;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'mais croyant qu\'il était dans la caravane, ils firent une journée de chemin et ils le cherchaient parmi leurs parents et connaissances;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'et ne l\'ayant pas trouvé, ils retournèrent à Jérusalem à sa recherche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Et il advint qu\'au bout de trois jours ils le trouvèrent dans le temple assis au milieu des docteurs, les écoutant et les interrogeant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'Et tous étaient stupéfaits de son intelligence et de ses réponses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Et l\'ayant vu, ils furent consternés, et sa mère lui dit: « Mon enfant, pourquoi as-tu agi ainsi envers nous? Voici, ton père et moi nous te cherchons avec angoisse. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Et il leur dit: « Pourquoi me cherchiez-vous? Ne saviez-vous pas qu\'il faut que je m\'occupe des affaires de mon Père? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Et ils ne comprirent pas ce qu\'il leur avait dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Puis il descendit avec eux et vint à Nazareth; et il leur était soumis. Et sa mère retenait toutes choses en son cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Et Jésus progressait en sagesse, et en stature, et en grâce, devant Dieu et devant les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Or, la quinzième année du règne de l\'empereur Tibère, Ponce Pilate étant gouverneur de Judée, et Hérode le tétraque de Galilée, tandis que Philippe son frère était tétraque de l\'Iturée et de la Trachonite et Lysanias, tétrarque de l\'Abilène,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'sous le pontificat d\'Annas et de Caïaphas, la parole de Dieu fut adressée à Jean fils de Zacharie dans le désert,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'et il parcourut toute la contrée voisine du Jourdain en prêchant un baptême de repentance pour la rémission des péchés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'comme il est écrit dans le livre des discours d\'Ésaïe le prophète: « Voix d\'un crieur dans le désert: Préparez le chemin du Seigneur, redressez Ses sentiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Toute vallée sera comblée, et toute montagne et toute colline seront abaissées; et ce qui est tortueux sera redressé, et les chemins raboteux deviendront unis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'Et toute chair verra le salut de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Il disait donc à la foule qui venait se faire baptiser par lui: « Engeance de vipères, qui vous a appris à fuir la colère à venir?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Produisez donc des fruits dignes de la repentance, et ne vous mettez pas à dire en vous-mêmes: Nous avons Abraham pour père! Car je vous déclare que Dieu peut de ces pierres-ci susciter des enfants à Abraham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Mais déjà la hache même est mise à la racine des arbres; tout arbre donc qui ne produit pas de bon fruit doit être coupé et jeté au feu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Et la foule lui demandait: « Qu\'avons-nous donc à faire? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Mais il leur répliquait: « Que celui qui a deux tuniques partage avec celui qui n\'en a point, et que celui qui a des vivres fasse de même. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Or il vint aussi des publicains pour se faire baptiser, et ils lui dirent: « Maître, qu\'avons-nous à faire? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Mais il leur dit: « N\'exigez rien au delà de ce qui vous est prescrit. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Des soldats aussi lui demandaient: « Et nous de notre côté que ferons-nous? » Et il leur dit: « N\'opprimez ni ne vexez personne, et contentez-vous de votre paie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Mais comme le peuple était dans l\'attente, et que tous se demandaient en leurs cœurs relativement à Jean, s\'il ne serait point lui-même le Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Jean s\'adressant à tous leur dit: « Pour moi, je vous baptise d\'eau; mais il vient, celui qui est plus puissant que moi, et je ne suis pas digne de délier la courroie de ses sandales; c\'est lui qui vous baptisera d\'Esprit saint et de feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Il tient son van dans sa main pour nettoyer son aire et serrer le blé dans son grenier; mais il brûlera la paille dans un feu inextinguible. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Tandis donc qu\'il évangélisait le peuple, en lui adressant encore plusieurs autres exhortations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Hérode le tétrarque, réprimandé par lui à propos d\'Hérodiade la femme de son frère et à propos de toutes les mauvaises actions que lui, Hérode, avait faites,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'ajouta encore celle-ci à toutes les autres: il fit mettre Jean en prison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Or il advint, pendant que tout le peuple se faisait baptiser, qu\'après que Jésus eut aussi été baptisé, et tandis qu\'il priait, le ciel s\'ouvrit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'et que l\'Esprit saint descendit sur lui sous forme corporelle, comme une colombe, et qu\'une voix vint du ciel: « Tu es Mon Fils bien-aimé, en toi J\'ai pris plaisir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Et Jésus lui-même avait, lorsqu\'il commença, environ trente ans, étant fils, comme on le pensait, de Joseph fils d\'Héli,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'fils de Matthat, fils de Lévi, fils de Melchi, fils de Jannaï, fils de Joseph,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'fils de Matthathias, fils d\'Amos, fils de Nahoum, fils d\'Esli, fils de Naggaï,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'fils de Maath, fils de Matthathias, fils de Sémin, fils de Josech, fils de Joda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'fils de Joanam, fils de Résa, fils de Zorobabel, fils de Salathiel, fils de Néri,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'fils de Melchi, fils d\'Addi, fils de Kosam, fils d\'Elmadam, fils de Er,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'fils de Josué, fils d\'Élièzer, fils de Jorim, fils de Matthat, fils de Lévi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'fils de Siméon, fils de Juda, fils de Joseph, fils de Jonam, fils d\'Éliakim,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'fils de Méléa, fils de Menna, fils de Metthatha, fils de Natham, fils de David,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'fils de Jessaï, fils de Jobel, fils de Boos, fils de Sala, fils de Naasson,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'fils d\'Admin, fils d\'Arni, fils d\'Esron, fils de Pharès, fils de Juda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'fils de Jacob, fils d\'Isaac, fils d\'Abraham, fils de Thara, fils de Nachor,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'fils de Serouch, fils de Ragau, fils de Phalek, fils d\'Eber, fils de Sala,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'fils de Kaïnam, fils d\'Arphaxad, fils de Sem, fils de Noë, fils de Lamech,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'fils de Matthousala, fils d\'Enoch, fils de Jared, fils de Maléléel, fils de Kaïnan,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'fils d\'Enos, fils de Seth, fils d\'Adam, fils de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Or Jésus rempli de l\'Esprit saint revint d\'auprès du Jourdain, et il était conduit par l\'esprit dans le désert,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'étant pendant quarante jours tenté par le diable. Et il ne mangeait rien durant ces jours-là, et lorsqu\'ils furent terminés il eut faim.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Mais le diable lui dit: « Si tu es fils de Dieu, dis à cette pierre-ci qu\'elle devienne du pain. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Et Jésus lui répliqua: « Il est écrit que ce n\'est pas de pain seulement que l\'homme vivra. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Et l\'ayant emmené, il lui montra tous les royaumes de la terre en un seul instant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'et le diable lui dit: « Je te donnerai toute cette puissance et leur gloire, car elle m\'a été remise, et je la donne à qui je veux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'si donc tu te prosternes devant moi, elle sera toute à toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Et Jésus lui répliqua: « Il est écrit: C\'est le Seigneur ton Dieu que tu adoreras, et c\'est à Lui seul que tu rendras un culte. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Et il le conduisit à Jérusalem et il le posa sur l\'aile du temple, et il lui dit: « Si tu es fils de Dieu, jette-toi d\'ici en bas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'car il est écrit que Il donnera pour toi des ordres à Ses anges, afin qu\'ils te protègent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'et que ils te porteront sur leurs mains, de peur que tu ne heurtes ton pied contre une pierre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Et Jésus lui répliqua: « Il a été dit: Tu ne tenteras point le Seigneur ton Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Et le diable ayant épuisé toute espèce de tentation s\'éloigna de lui jusques à une autre occasion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Et Jésus, animé de la puissance de l\'Esprit, revint en Galilée, et sa renommée se répandit dans toute la contrée voisine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Et lui-même enseignait dans leurs synagogues, et il était loué de tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Et il vint à Nazareth, où il avait été élevé, et il entra selon sa coutume le jour du sabbat dans la synagogue, et il se leva pour faire la lecture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Et on lui remit le livre du prophète Ésaïe, et ayant ouvert le livre il trouva le passage où il était écrit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '« L\'esprit du Seigneur est sur moi; c\'est pourquoi Il m\'a oint afin d\'annoncer une bonne nouvelle aux pauvres; Il m\'a envoyé pour proclamer aux captifs l\'élargissement, et aux aveugles le recouvrement de la vue, pour renvoyer les blessés soulagés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'pour proclamer une favorable année du Seigneur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Et ayant replié le livre, il le rendit à l\'employé, et s\'assit; et les regards de tous ceux qui se trouvaient dans la synagogue étaient fixés sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Et il commença à leur parler en ces termes: « Aujourd\'hui ce passage s\'est accompli à vos oreilles. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Et tous témoignaient en sa faveur, et s\'émerveillaient des paroles pleines de grâce qui sortaient de sa bouche, et ils disaient: « Celui-ci n\'est-il pas le fils de Joseph? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Mais il leur dit: « Sans doute vous m\'appliquerez ce proverbe: Médecin, guéris-toi toi-même; fais aussi ici dans ta patrie tout ce que nous avons appris qui s\'est fait à Capharnaoum. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Mais il ajouta: « En vérité je vous déclare qu\'aucun prophète n\'est bien reçu dans sa patrie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'mais c\'est avec vérité que je vous dis que du temps d\'Élie il y avait beaucoup de veuves en Israël, lorsque le ciel fut fermé pendant trois ans et six mois, en sorte qu\'une grande famine eut lieu sur toute la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'et Élie ne fut envoyé vers aucune d\'elles, sauf auprès d\'une veuve de Sarepta dans le pays de Sidon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Et il y avait beaucoup de lépreux en Israël du temps d\'Elisée le prophète, et aucun d\'eux ne fut nettoyé, sauf Naaman le syrien. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Et ils furent tous remplis de courroux dans la synagogue en entendant ces paroles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'et s\'étant levés, ils l\'expulsèrent de la ville, et ils l\'emmenèrent jusques au bord de la montagne sur laquelle leur ville était bâtie, de manière à le précipiter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Mais lui, étant passé au milieu d\'eux, poursuivait sa route.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Et il descendit à Capharnaoum, ville de Galilée, et il les enseignait le jour du sabbat;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'et ils étaient stupéfaits de son enseignement, parce que sa parole était pleine d\'autorité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Et dans la synagogue se trouvait un homme possédé de l\'esprit d\'un démon impur, et il s\'écria à voix haute:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, '« Ah! qu\'y a-t-il de commun entre nous et toi, Jésus Nazarénien? Es-tu venu pour nous faire périr? Je sais qui tu es: le saint de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Et Jésus le réprimanda en disant: « Tais-toi, et sors de lui! » Et le démon l\'ayant jeté tout au milieu sortit de lui, sans lui avoir fait aucun mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Et tous furent saisis d\'épouvante, et ils se disaient les uns aux autres: « Quelle est cette parole? Car il commande avec autorité et puissance aux esprits impurs, et ils sortent? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Et le bruit de sa renommée se répandait dans tous les lieux d\'alentour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Mais ayant quitté la synagogue il entra dans la maison de Simon; or la belle-mère de Simon était prise d\'une grosse fièvre, et ils le consultèrent à son sujet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Et s\'étant placé au-dessus d\'elle, il réprimanda la fièvre et elle la quitta; or aussitôt s\'étant levée, elle les servait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Or, comme le soleil se couchait, tous ceux qui avaient des malades atteints de diverses maladies les lui amenèrent; et imposant les mains à chacun d\'eux, il les guérit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Mais des démons sortaient aussi de plusieurs d\'entre eux, en criant et en disant: « Tu es le fils de Dieu. » Et les réprimandant, il ne leur permettait pas de parler, parce qu\'ils savaient qu\'il était le Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Mais quand le jour eut paru, il sortit pour se rendre dans un lieu désert, et la foule le cherchait, et elle vint jusques à lui, et elle le retenait pour qu\'il ne s\'éloignât pas d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Mais il leur dit: « Il faut que j\'annonce aussi à d\'autres villes la bonne nouvelle du royaume de Dieu, car c\'est pour cela que j\'ai été envoyé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Et il prêchait dans les synagogues de la Judée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Or il advint, pendant que la foule se pressait autour de lui et écoutait la parole de Dieu, et que lui-même se tenait debout auprès du lac de Gennèsareth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'qu\'il vit deux barques qui stationnaient au bord du lac; mais les pêcheurs en étaient descendus et lavaient leurs filets.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Or étant monté dans l\'une des barques, qui appartenait à Simon, il le pria de s\'éloigner un peu de la terre, et s\'étant assis, il enseignait la foule de dedans la barque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Mais, lorsqu\'il eut cessé de parler, il dit à Simon: « Pousse au large, et jetez vos filets pour pêcher. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Et Simon lui répliqua: « Maître, nous avons travaillé toute la nuit sans rien prendre; mais sur ta parole je jetterai les filets. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Et l\'ayant fait, ils ramenèrent une grande quantité de poissons; mais leurs filets se déchiraient,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'et ils firent signe à leurs camarades dans l\'autre barque de venir les aider; et ils vinrent, et les deux barques furent tellement remplies, qu\'elles enfonçaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Ce que Simon Pierre ayant vu, il se jeta aux genoux de Jésus en disant: « Éloigne-toi de moi, car je suis un homme pécheur, seigneur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Il était en effet saisi d\'épouvante, ainsi que tous ceux qui étaient avec lui, à cause de la capture des poissons qu\'ils avaient pris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'Or, il en était aussi de même de Jacques et de Jean fils de Zébédée, qui étaient associés de Simon. Et Jésus dit à Simon: « Ne crains point; désormais tu seras un preneur d\'hommes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Et ayant ramené les barques vers la terre, ils quittèrent tout et ils le suivirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Et il advint, pendant qu\'il se trouvait dans une des villes, que, voici, un homme couvert de lèpre ayant vu Jésus tomba la face contre terre, et le supplia en disant: « Seigneur, si tu le veux, tu peux me guérir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Et ayant étendu la main, il le toucha en disant: « Je le veux, sois guéri! » Et aussitôt la lèpre le quitta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Et il lui enjoignit de n\'en parler à personne; « mais va, » lui dit-il, « te montrer au sacrificateur, et présente l\'offrande pour ta purification conformément à ce qu\'a prescrit Moïse pour leur servir d\'attestation. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Or le bruit de sa renommée ne faisait que se répandre de plus en plus, et une foule nombreuse accourait pour l\'entendre, et pour être guérie de ses infirmités.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Quant à lui, il se retirait dans les déserts et priait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Et il advint un jour, pendant que lui-même enseignait et que les pharisiens et les docteurs de la loi, qui étaient venus de tous les villages de Galilée et de Judée et de Jérusalem, se trouvaient présents, et qu\'une puissance du Seigneur se montrait dans ses guérisons,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'que, voici, des hommes apportent sur un lit un homme qui était paralytique, et ils cherchaient à l\'introduire et à le placer devant lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Et n\'ayant pas trouvé le moyen de l\'introduire, à cause de la foule, ils montèrent sur le toit, et ils le descendirent au travers des tuiles avec son petit lit, tout au milieu en présence de tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Et ayant vu leur foi, il dit: « O homme, tes péchés t\'ont été pardonnés! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Et les scribes et les pharisiens se mirent à se demander: « Qui est celui-ci, qui profère des blasphèmes? Qui est-ce qui peut pardonner les péchés, si ce n\'est Dieu seul? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Mais Jésus connaissant leurs pensées, leur répliqua: « A quoi pensez-vous dans vos cœurs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Quel est le plus facile, de dire: Tes péchés t\'ont été pardonnés, ou de dire: Lève-toi et marche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Or, pour que vous sachiez que le fils de l\'homme a sur la terre l\'autorité de pardonner les péchés... » il dit au paralytique: « Je te le dis, lève-toi, prends ton petit lit, et va-t-en dans ta maison. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Et aussitôt s\'étant levé devant eux, il prit sa couche, et s\'en alla dans sa maison en glorifiant Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Et tous furent saisis de surprise, et ils glorifiaient Dieu, et ils furent remplis de crainte, « car, » disaient-ils, « nous avons vu aujourd\'hui des choses étranges. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Et après cela il sortit, et vit un publicain, nommé Lévis, assis au bureau des péages, et il lui dit: « Suis-moi! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Et ayant tout quitté, il se leva, et il le suivait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Et Lévis lui donna un grand festin dans sa maison; et il y avait une grande foule de publicains et d\'autres personnes qui étaient attablés avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Et les pharisiens et leurs scribes s\'en plaignaient à ses disciples, en disant: « Pourquoi mangez-vous et buvez-vous avec les publicains et les pécheurs? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Et Jésus leur répliqua: « Ce ne sont pas ceux qui sont en bonne santé qui ont besoin du médecin, mais les mal portants;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'je ne suis pas venu appeler des justes mais des pécheurs à la repentance. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Mais ils lui dirent: « Les disciples de Jean jeûnent souvent, et ils font des prières; il en est aussi de même de ceux des pharisiens, mais les tiens mangent et boivent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Mais Jésus leur dit: « Pouvez-vous faire jeûner les fils de la chambre nuptiale pendant que l\'époux est avec eux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Mais des jours viendront... et quand l\'époux leur sera enlevé, alors ils jeûneront en ces jours-là. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Mais il leur adressait encore une parabole: « Personne n\'arrache une pièce à un habit neuf pour la mettre à un vieil habit; autrement d\'un côté on déchirera le neuf, et de l\'autre la pièce du neuf ne s\'accordera pas avec le vieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'Et personne ne met du vin nouveau dans des outres vieilles, autrement le vin nouveau rompra les outres, et lui-même se répandra, et les outres seront perdues;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'mais on doit mettre du vin nouveau dans des outres neuves.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Personne en buvant du vieux ne désire du nouveau, car il dit: le vieux est bon. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Or il advint un jour de sabbat qu\'il traversait des champs de blé, et ses disciples arrachaient et mangeaient les épis, en les frottant dans leurs mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Mais quelques pharisiens dirent: « Pourquoi faites-vous ce qui n\'est pas permis le jour du sabbat? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Et Jésus leur répliqua: « N\'avez-vous pas même lu ce que fit David quand il eut faim, lui et ceux qui étaient avec lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Il entra dans la maison de Dieu, et ayant pris les pains de proposition, il en mangea, et il en donna à ceux qui étaient avec lui, quoiqu\'il ne soit permis d\'en manger qu\'aux prêtres seuls. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Et il leur disait: « Le fils de l\'homme est maître du sabbat. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Or, il advint encore dans un autre sabbat qu\'il entra dans la synagogue, et qu\'il enseignait. Et il y avait là un homme dont la main droite était sèche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Et les scribes et les pharisiens l\'épiaient pour voir s\'il ferait une guérison le jour du sabbat, afin de trouver à l\'accuser;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'mais il connaissait leurs pensées. Or il dit à l\'homme qui avait la main sèche: « Lève-toi et tiens-toi là au milieu. » Et s\'étant levé il se tint debout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Or Jésus leur dit: « Je vous demande s\'il est permis le jour du sabbat de faire du bien, ou de faire du mal, de sauver une vie ou de la perdre? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Et ayant porté tout autour de lui ses regards sur eux tous, il lui dit: « Étends ta main. » Et il le fit, et sa main fut guérie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Mais ils furent remplis de frénésie, et ils discutaient entre eux ce qu\'ils feraient à Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Or il advint en ces jours-là qu\'il sortit pour aller prier sur la montagne; et il passait toute la nuit à prier Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Et lorsque le jour eut paru, il appela ses disciples, et après en avoir choisi douze parmi eux, qu\'il nomma aussi apôtres: —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Simon, qu\'il nomma aussi Pierre, et André son frère, et Jacques et Jean, et Philippe et Barthélemi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'et Matthieu et Thomas, Jacques fils d\'Alphée, et Simon appelé zélote,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'et Judas fils de Jacques, et Judas Iscarioth qui devint traître —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'et après être descendu avec eux, il s\'arrêta dans une plaine; et là se trouvait une foule nombreuse de ses disciples et une grande multitude de peuple, lesquels étaient venus de toute la Judée, et de Jérusalem, et des côtes de Tyr et de Sidon, pour l\'entendre et pour être guéris de leurs maladies;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'et ceux qui étaient obsédés par des esprits impurs étaient guéris,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'et toute la foule cherchait à le toucher, car une force sortait de lui et les guérissait tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Et lui-même ayant levé les yeux sur ses disciples disait: « Heureux vous qui êtes pauvres, car c\'est à vous qu\'appartient le royaume de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Heureux vous qui êtes maintenant affamés, car vous serez rassasiés. Heureux vous qui pleurez maintenant, car vous rirez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Vous êtes heureux quand les hommes vous auront haïs, et quand ils vous auront exclus et outragés, et qu\'ils auront rejeté votre nom comme pervers, à cause du fils de l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Réjouissez-vous en ce jour-là et bondissez de joie; car, voici, votre récompense est grande dans les cieux; c\'est de la même manière en effet que leurs pères agissaient envers les prophètes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Au contraire, malheur à vous riches, car vous possédez déjà votre consolation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Malheur à vous qui êtes maintenant saturés, car vous aurez faim. Malheur à vous qui riez maintenant, car vous serez dans le deuil et les larmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Malheur quand tous les hommes disent du bien de vous; c\'est de la même manière en effet qu\'ils agissaient envers les faux prophètes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Mais je vous dis à vous qui m\'écoutez: aimez vos ennemis, faites du bien à ceux qui vous haïssent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'bénissez ceux qui vous maudissent, priez pour ceux qui vous maltraitent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'A celui qui te frappe sur la joue, présente encore l\'autre, et à celui qui t\'enlève ton manteau, ne soustrais pas non plus ta tunique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Donne à quiconque te demande, et ne réclame rien de celui qui enlève ce qui est à toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Et conformément à la manière dont vous voulez que les hommes agissent envers vous, agissez de même envers eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Et si vous aimez ceux qui vous aiment, quelle gratitude vous en revient-il? Car les pécheurs aussi aiment ceux qui les aiment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Et en effet si vous faites du bien à ceux qui vous font du bien, quelle gratitude vous en revient-il? Les pécheurs aussi font la même chose.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Et si vous prêtez à ceux dont vous espérez recevoir, quelle gratitude vous en revient-il? Les pécheurs aussi prêtent aux pécheurs, afin de recevoir la pareille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Au contraire, aimez vos ennemis, et faites du bien, et prêtez, sans espérer du retour; et votre récompense sera considérable, et vous serez fils du Très-Haut, car Il est bon envers les ingrats et les méchants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Soyez miséricordieux comme votre Père est miséricordieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Et ne jugez point, et vous ne serez certainement pas jugés; et ne condamnez point, et vous ne serez certainement, pas condamnés. Absolvez, et vous serez absous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Donnez, et il vous sera donné; on versera dans votre sein une bonne mesure, tassée, secouée, débordante; car avec la mesure dont vous mesurerez, il vous sera mesuré. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Or il leur dit encore une parabole: « Est-ce qu\'un aveugle peut guider un aveugle? Ne tomberont-ils pas l\'un et l\'autre dans un fossé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Un disciple n\'est pas au-dessus de son maître; mais chacun sera façonné comme son maître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Mais pourquoi regardes-tu le fétu qui est dans l\'œil de ton frère, tandis que tu ne t\'aperçois pas de la poutre qui est dans ton propre œil?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Comment peux-tu dire à ton frère: Frère, permets que j\'ôte le fétu qui est dans ton œil; toi qui ne vois pas la poutre qui est dans ton œil? Hypocrite, ôte premièrement la poutre de ton œil, et tu verras alors à ôter le fétu qui est dans l\'œil de ton frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Il n\'y a pas en effet de bon arbre qui produise du fruit pourri, ni, d\'un autre côté, d\'arbre pourri qui produise du bon fruit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'car chaque arbre se connaît à son propre fruit; en effet ce n\'est pas sur des épines qu\'on recueille des figues, ni sur un buisson qu\'on vendange du raisin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'L\'homme bon du bon trésor de son cœur tire le bien, et le méchant du mauvais tire le mal; car c\'est par ce qui déborde du cœur que sa bouche parle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Mais pourquoi m\'appelez-vous: « Seigneur, Seigneur! » et ne faites-vous pas ce que je dis?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Quiconque vient à moi, et écoute mes paroles, et les met en pratique, je vous montrerai à qui il ressemble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Il ressemble à un homme qui bâtit une maison, lequel a foui et profondément creusé, et placé la fondation sur le roc; mais une inondation étant survenue, le fleuve a fait irruption contre cette maison-là, et il n\'a pu l\'ébranler parce qu\'elle était bien bâtie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Mais celui qui a écouté et n\'a pas mis en pratique ressemble à un homme qui a bâti une maison sur la terre sans fondation; le fleuve a fait irruption contre elle, et aussitôt elle est tombée, et l\'écroulement de cette maison-là a été grand. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Lorsqu\'il eut fini de faire entendre au peuple toutes ces siennes paroles, il entra à Capharnaoum.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Or un certain centurion avait un esclave malade et sur le point de mourir, qui lui était très précieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Mais ayant ouï parler de Jésus, il lui dépêcha des anciens des Juifs, en le suppliant de venir pour tirer d\'affaire son esclave.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Ceux-ci étant arrivés auprès de Jésus le sollicitaient avec instances en disant: « Il mérite que tu lui accordes cela;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'car il aime notre nation, et c\'est lui qui nous a bâti notre synagogue. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Or Jésus s\'était mis en route avec eux, et il n\'était plus qu\'à peu de distance de la maison, lorsque le centurion envoya des amis pour lui dire: « Seigneur, ne te dérange pas; car je ne suis pas digne que tu entres sous mon toit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'c\'est pourquoi je ne me suis pas même permis d\'aller moi-même à toi; mais dis un mot, et que mon serviteur soit guéri;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'car moi aussi je suis un homme placé sous autorité, ayant des soldats sous mes ordres, et je dis à celui-ci: « Va, » et il va, et à un autre: « Viens, » et il vient, et à mon esclave: « Fais cela, » et il le fait. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Or en entendant cela Jésus fut émerveillé de lui, et s\'étant tourné vers la foule qui le suivait, il dit: « Je vous déclare que même en Israël je n\'ai pas trouvé une si grande foi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Et ceux qui avaient été envoyés étant retournés à la maison trouvèrent l\'esclave en bonne santé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Et il advint ensuite qu\'il se rendit dans une ville appelée Naïn, et ses disciples et une foule nombreuse faisaient route avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Mais quand il approcha de la porte de la ville, voici, on emportait un mort, fils unique de sa mère; et celle-ci était veuve, et une foule considérable de la ville était avec elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Et le Seigneur l\'ayant vue fut ému de compassion envers elle, et lui dit: « Ne pleure pas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Et s\'étant approché, il toucha le cercueil; or les porteurs s\'arrêtèrent, et il dit: « Jeune homme, je te dis: lève-toi! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Et le mort s\'assit, et commença à parler; et il le rendit à sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Mais tous furent saisis de crainte, et ils glorifiaient Dieu en disant: « Un grand prophète s\'est élevé parmi nous, » et: « Dieu a visité Son peuple. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Et cette nouvelle répandit sa renommée dans toute la Judée, et dans tout le pays d\'alentour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Et Jean fut informé par ses disciples de tout cela;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'et ayant appelé à lui deux de ses disciples, Jean les envoya auprès du Seigneur, pour lui dire: « Es-tu celui qui doit venir, ou bien devons-nous en attendre un autre? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Or quand ces hommes furent arrivés vers lui, ils dirent: « Jean le baptiste nous a dépêchés vers toi pour te dire: « Es-tu celui qui doit venir, ou bien devons-nous en attendre un autre? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'En ce moment-là il guérit beaucoup de gens de maladies, de plaies, et d\'esprits malins, et il rendit la vue à beaucoup d\'aveugles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'et il leur répliqua: « Allez rapporter à Jean ce que vous avez vu et entendu: des aveugles recouvrent la vue, des boiteux marchent, des lépreux sont guéris et des sourds entendent, des morts ressuscitent, une bonne nouvelle est annoncée aux pauvres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'et il est heureux celui qui n\'aura pas trébuché à propos de moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Quand les messagers de Jean furent partis, il commença à dire à la foule au sujet de Jean: « Qu\'êtes-vous allés contempler au désert? Un roseau agité par le vent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Mais qu\'êtes-vous allés voir? Un homme vêtu avec luxe? Voici, ceux qui portent des vêtements somptueux et qui vivent dans la mollesse habitent les palais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Mais qu\'est-ce que vous y êtes allés voir? Un prophète? Oui, je vous le déclare, et bien plus qu\'un prophète;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'c\'est celui dont il est écrit: Voici, J\'envoie Mon messager devant toi, lequel frayera ton chemin devant toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Je vous le déclare: parmi les enfants des femmes personne n\'est plus grand que Jean; cependant le moindre dans le royaume de Dieu est plus grand que lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'et après l\'avoir entendu, tout le peuple et les publicains ont justifié Dieu en se faisant baptiser du baptême de Jean,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'tandis que les pharisiens et les légistes ont anéanti le dessein de Dieu quant à eux-mêmes en ne se faisant pas baptiser par lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'A qui donc comparerai-je les hommes de cette génération et à qui ressemblent-ils?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Ils ressemblent à de petits enfants assis dans une place publique et s\'apostrophant les uns les autres, qui disent: « Nous vous avons joué de la flûte, et vous n\'avez pas dansé; nous avons chanté des complaintes, et vous n\'avez pas pleuré. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'En effet Jean le baptiste est venu, ne mangeant point de pain et ne buvant point de vin, et vous dites: « Il a un démon. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Le fils de l\'homme est venu, qui mange et boit, et vous dites: « Voici un glouton et un ivrogne, un ami des publicains et des pécheurs. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Eh bien! la sagesse a été justifiée par tous ses enfants! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Or un des pharisiens l\'invitait à manger avec lui, et étant entré dans la maison du pharisien, il se mit à table.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Et voici, il y avait une femme qui menait dans la ville une mauvaise vie, et ayant appris qu\'il était à table dans la maison du pharisien, elle apporta une fiole d\'albâtre pleine de parfum,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'et se tenant derrière lui et à ses pieds, tout en pleurs, elle se mit à mouiller ses pieds de ses larmes, et elle les essuyait avec les cheveux de sa tête, et elle baisait tendrement ses pieds, et elle les oignait de son parfum.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Mais le pharisien qui l\'avait invité s\'en étant aperçu, il se dit en lui-même: « Si celui-ci était le prophète, il saurait qui, et de quelle espèce, est la femme qui le touche, et que c\'est une personne de mauvaise vie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Et Jésus s\'adressant à lui, lui dit: « Simon, j\'ai quelque chose à te dire. » Et l\'autre reprit: « Maître, parle. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, '« Un certain créancier avait deux débiteurs: L\'un lui devait cinq cents deniers, et l\'autre cinquante;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'comme ils n\'avaient pas de quoi payer, il remit la dette à l\'un et à l\'autre. Lequel donc d\'entre eux l\'aimera davantage? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Simon répliqua: « Je pense que c\'est celui auquel il a remis davantage. » Or il lui dit: « Tu as bien jugé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Et s\'étant tourné vers la femme, il dit à Simon: « Vois-tu cette femme? Je suis entré dans ta maison; tu n\'as pas versé d\'eau sur mes pieds, tandis que celle-ci a mouillé mes pieds de ses larmes et les a essuyés avec ses cheveux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'tu ne m\'as point donné de baiser, tandis que celle-ci depuis que je suis entré n\'a pas cessé de me baiser tendrement les pieds;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'tu n\'as pas oint ma tête d\'huile, tandis que celle-ci a oint mes pieds de parfum.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'C\'est pourquoi je te le déclare, ses péchés qui étaient nombreux ont été pardonnés, car elle a beaucoup aimé, tandis que celui à qui on pardonne peu, aime peu aussi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Mais il lui dit à elle: « Tes péchés ont été pardonnés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Et les convives commencèrent à dire en eux-mêmes: « Qui est celui-ci qui même pardonne les péchés? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Mais il dit à la femme: « Ta foi t\'a sauvée, va-t-en en paix. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Et il advint plus tard que lui-même s\'en allait de ville en ville et de village en village, prêchant et annonçant la bonne nouvelle du royaume de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'et avec lui étaient les douze, ainsi que quelques femmes qui avaient été délivrées d\'esprits malins et d\'infirmités: c\'étaient Marie qui était appelée Magdalène, de laquelle étaient sortis sept démons,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'et Jeanne femme de Chouza intendant d\'Hérode, et Susanne, et plusieurs autres qui les assistaient de leurs biens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Cependant une foule nombreuse, où se trouvaient aussi ceux qui de ville en ville étaient venus à lui, s\'étant rassemblée, il dit sous forme de parabole:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, '« Le semeur sortit pour semer sa semence; et pendant qu\'il la semait, une partie tomba le long du chemin, et elle fut foulée aux pieds, et les oiseaux du ciel la mangèrent toute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Et une autre tomba sur du roc, et ayant poussé elle sécha, parce qu\'elle n\'avait pas d\'humidité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Et une autre tomba au milieu des épines, et les épines ayant poussé avec elle, l\'étouffèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Et une autre tomba dans la bonne terre, et ayant poussé elle produisit du fruit au centuple. » En disant cela, il s\'écriait: « Que celui qui a des oreilles pour entendre, entende! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Mais ses disciples lui demandaient ce que signifiait cette parabole?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Or il dit: « Il vous a été donné de connaître les mystères du royaume de Dieu; mais pour les autres c\'est en paraboles, afin qu\'en voyant ils ne voient pas, et qu\'en entendant ils ne comprennent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Or voici ce que signifie cette parabole: La semence, c\'est la parole de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Mais ceux qui sont le long du chemin sont ceux qui ont entendu, puis survient le diable et il enlève la parole de leur cœur, afin qu\'ils ne soient pas sauvés après avoir cru.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Quant à ceux qui sont sur le roc, ce sont ceux qui, lorsqu\'ils ont entendu, reçoivent avec joie la parole; et ceux-ci n\'ont pas de racine, ils croient temporairement, et au moment de la tentation ils font défection.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Quant à ce qui est tombé sur les épines, ce sont ceux qui ont entendu, et qui en avançant sont étouffés par les soucis et la richesse et les plaisirs de la vie et ne produisent rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Mais ce qui est tombé dans la bonne terre, ce sont ceux qui, ayant entendu la parole avec un cœur noble et bon, retiennent la parole, et portent du fruit avec persévérance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Or personne, après avoir allumé une lampe, ne la cache sous un meuble, ou ne la place sous un lit, mais il la place sur un support.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Car il n\'y a rien de caché qui ne doive être manifesté, ni rien de secret qui ne doive être connu et mis en évidence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Prenez donc garde de quelle manière vous écoutez; car celui qui a, on lui donnera, et celui qui n\'a pas, même ce qu\'il s\'imagine avoir lui sera enlevé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Or sa mère et ses frères se rendirent auprès de lui, et ils ne pouvaient l\'atteindre à cause de la foule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'Et il lui fut dit: « Ta mère et tes frères sont là dehors, qui veulent te voir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Mais il leur répliqua: « Ma mère et mes frères, ce sont ceux qui écoutent la parole de Dieu et qui la pratiquent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Or il advint un jour qu\'il monta dans une barque, ainsi que ses disciples, et il leur dit: « Passons sur l\'autre rive du lac; » et ils partirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Mais pendant la traversée il s\'endormit, et un tourbillon de vent se précipita sur le lac, et ils étaient submergés et en péril.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Mais s\'étant approchés ils l\'éveillèrent en disant: « Maître, Maître, nous périssons. » Et lui s\'étant réveillé, gourmanda le vent et l\'agitation de l\'eau; et ils cessèrent, et il survint du calme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Mais il leur dit: « Où est votre foi? » Et tout effrayés ils s\'émerveillèrent en disant: « Quel est donc celui-ci, qu\'il commande même aux vents et à l\'eau? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'Et ils abordèrent au pays des Géraséniens, qui est en face de la Galilée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Et lorsqu\'il fut descendu à terre, vint à sa rencontre de l\'intérieur de la ville un certain homme que possédaient des démons, et depuis longtemps il n\'avait pas porté de vêtement, et il ne demeurait point dans une maison, mais dans les tombeaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Or ayant aperçu Jésus, après avoir poussé un cri, il tomba à ses pieds, et dit à haute voix: « Qu\'y a-t-il de commun entre moi et toi, Jésus, fils du Dieu Très-Haut? Je t\'en prie, ne me torture pas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'En effet il avait enjoint à l\'esprit impur de sortir de cet homme; car pendant longtemps il l\'avait entraîné avec lui; et il était chargé de chaînes et d\'entraves pour être bien gardé, et rompant ses liens il était emmené par le démon dans les déserts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Or Jésus lui demanda: « Quel est ton nom? » Et il dit: « Légion, » parce que plusieurs démons étaient entrés en lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Et ils le sollicitaient de ne pas leur ordonner d\'aller dans l\'abîme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Or il y avait là un troupeau de nombreux pourceaux qui paissait dans la montagne; et ils le sollicitèrent de leur permettre d\'entrer dans ces pourceaux; et il le leur permit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Or les démons étant sortis de cet homme entrèrent dans les pourceaux, et le troupeau se rua au bas du précipice dans le lac et se noya.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Or ceux qui le faisaient paître, ayant vu ce qui était arrivé s\'enfuirent et portèrent la nouvelle dans la ville et dans les campagnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Or les gens sortaient pour voir ce qui était arrivé, et ils vinrent auprès de Jésus, et ils trouvèrent assis aux pieds de Jésus, vêtu, et raisonnable, l\'homme duquel étaient sortis les démons; et ils furent saisis de terreur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Or les témoins leur rapportèrent de quelle manière le démoniaque avait été guéri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Et toute la population de la contrée voisine des Géraséniens le pria de s\'éloigner d\'eux, car ils étaient saisis d\'une grande crainte. Et étant remonté dans une barque, il s\'en retourna.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Cependant l\'homme duquel étaient sortis les démons le priait de le prendre avec lui, mais il le renvoya en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, '« Retourne dans ta maison, et raconte tout ce que Dieu a fait pour toi. » Et il s\'en alla proclamant dans toute la ville tout ce que Jésus avait fait pour lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Or comme Jésus revenait en arrière, il fut accueilli par la foule, car ils étaient tous à l\'attendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Et voici, survint un homme, dont le nom était Jaïrus, et c\'était lui qui était chef de la synagogue; et étant tombé aux pieds de Jésus, il le sollicitait d\'entrer dans sa maison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'parce qu\'il avait une fille unique âgée d\'environ douze ans, et qu\'elle se mourait. Or, comme il s\'y rendait, la foule l\'étouffait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'et une femme malade depuis douze ans d\'un flux de sang, laquelle n\'avait pu être guérie par personne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 's\'étant approchée toucha par derrière la frange de son manteau, et tout à coup son flux de sang s\'arrêta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Et Jésus dit: « Qui est-ce qui m\'a touché? » Mais tous s\'en défendant, Pierre dit: « Maître, la foule t\'entoure et te presse! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Mais Jésus dit: « Quelqu\'un m\'a touché; car j\'ai senti qu\'une force est sortie de moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Et la femme, voyant qu\'elle était découverte, s\'approcha en tremblant, et s\'étant jetée à ses pieds, elle déclara devant tout le peuple pour quel motif elle l\'avait touché, et comment elle avait été tout à coup guérie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Mais il lui dit: « Ma fille, ta foi t\'a sauvée, va-t-en en paix. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Comme il parlait encore, survint quelqu\'un de chez le chef de synagogue, disant: « Ta fille est morte, n\'importune plus le maître! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Ce que Jésus ayant ouï, il lui répliqua: « Ne crains point, crois seulement, et elle sera sauvée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Or, étant entré dans la maison, il ne permit pas que personne entrât avec lui, sauf Pierre, et Jean et Jacques et le père de l\'enfant et sa mère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Or tous pleuraient et se lamentaient sur elle, mais il leur dit: « Ne pleurez pas; car elle n\'est pas morte, mais elle dort. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Et ils se moquaient de lui, sachant qu\'elle était morte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Mais lui, ayant pris sa main, s\'écria: « Enfant, lève-toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Et son esprit revint, et elle se leva immédiatement; et il commanda qu\'on lui donnât à manger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Et ses parents furent stupéfaits; mais il leur enjoignit de ne parler à personne de ce qui était arrivé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Or ayant appelé les douze, il leur donna pouvoir et autorité sur tous les démons, et pour guérir des maladies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'Et il les envoya prêcher le royaume de Dieu et opérer des guérisons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'et il leur dit: « Ne prenez rien pour la route, ni bâton, ni besace, ni pain, ni argent, et n\'ayez pas deux tuniques;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'et dans quelque maison que vous entriez, c\'est là que vous devez rester et de là que vous devez sortir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Et tous ceux qui ne vous recevront pas... étant sortis de cette ville-là, secouez la poussière de vos pieds en témoignage contre eux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Or, étant partis, ils parcouraient les villages en annonçant la bonne nouvelle et en opérant partout des guérisons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Cependant Hérode le tétrarque apprit tout ce qui s\'était passé, et il était très perplexe, parce que quelques-uns disaient que Jean était ressuscité des morts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'quelques-uns qu\'Élie était apparu, d\'autres que l\'un des anciens prophètes avait surgi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Mais Hérode dit: « Quant à Jean je l\'ai fait décapiter; mais quel est celui-ci dont j\'entends ainsi parler? » Et il cherchait à le voir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Et les apôtres étant revenus lui racontèrent tout ce qu\'ils avaient fait. Et les prenant avec lui il se retira à l\'écart dans une ville appelée Bethsaïda.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Mais la foule l\'ayant su le suivit, et les ayant accueillis il leur parlait du royaume de Dieu, et il guérissait ceux qui avaient besoin de guérison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Or, le jour commençait à baisser, mais les douze s\'étant approchés lui dirent: « Renvoie la foule, afin qu\'ils aillent dans les villages et dans les campagnes d\'alentour pour s\'héberger et trouver de la nourriture, car nous sommes ici dans un lieu désert. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Mais il leur dit: « Donnez-leur vous-mêmes à manger. » Et ils dirent: « Nous n\'avons pas plus de cinq pains et de deux poissons, à moins que nous n\'allions nous-mêmes acheter des vivres pour tout ce peuple. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Ils étaient en effet environ cinq mille hommes. Mais il dit à ses disciples: « Faites-les asseoir par rangs d\'environ cinquante. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'C\'est ce qu\'ils firent, et ils les firent tous asseoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Or, après avoir pris les cinq pains et les deux poissons, ayant levé les yeux vers le ciel, il les bénit et les rompit, et il les donnait à ses disciples pour les offrir à la foule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Et ils mangèrent et furent tous rassasiés, et on emporta les morceaux qu\'ils avaient eu de trop dans douze corbeilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Et il advint, pendant qu\'il priait à l\'écart, que les disciples se réunirent à lui, et il les interrogea en disant: « Qui dit la foule que je suis? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Et ils répliquèrent: « Jean le baptiste; d\'autres Élie; et d\'autres qu\'un des anciens prophètes a surgi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Mais il leur dit: « Mais vous, qui dites-vous que je suis? » Or Pierre lui répliqua: « Le Christ de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Mais, après leur avoir adressé des remontrances, il leur défendit de dire cela à personne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'disant: « Il faut que le fils de l\'homme souffre beaucoup, et qu\'il soit réprouvé par les anciens et les grands prêtres et les scribes, et qu\'il soit mis à mort, et qu\'il ressuscite le troisième jour. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Mais il disait à tous: « Si quelqu\'un veut venir après moi, qu\'il renonce à lui-même, et qu\'il prenne sa croix chaque jour, et qu\'il me suive;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'car celui qui voudra sauver sa vie la perdra, mais celui qui aura perdu sa vie à cause de moi, celui-là la sauvera;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'en effet que sert-il à un homme d\'avoir gagné le monde entier, mais de s\'être lui-même perdu ou ruiné?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Quiconque en effet aura eu honte de moi et de mes paroles, le fils de l\'homme aura honte de lui, quand il sera venu entouré de sa gloire et de celle de son Père et des saints anges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Or je vous déclare en vérité qu\'il y a quelques-uns de ceux qui sont ici présents qui ne goûteront certainement pas la mort jusques à ce qu\'ils aient vu le royaume de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Or il advint, après ces discours, qu\'au bout d\'environ huit jours, prenant avec lui Pierre et Jean et Jacques, il monta sur la montagne pour prier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Et pendant qu\'il priait, l\'apparence de son visage changea et son vêtement devint de la blancheur de l\'éclair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Et voici, deux hommes conversaient avec lui; c\'étaient Moïse et Élie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'qui apparaissant entourés de gloire parlaient de sa fin, qu\'il allait accomplir à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Or Pierre et ses compagnons étaient appesantis par le sommeil; mais quand ils se furent réveillés ils virent sa gloire et les deux hommes qui se tenaient avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Et il advint, pendant qu\'ils se séparaient de lui, que Pierre dit à Jésus: « Maître, c\'est une bonne chose pour nous que d\'être ici; faisons trois tentes, une pour toi, et une pour Moïse, et une pour Élie, » ne sachant ce qu\'il disait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Mais pendant qu\'il parlait ainsi, une nuée survint, et elle les couvrait, et ils furent effrayés au moment où ils entrèrent dans la nuée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Et une voix sortit de la nuée disant: « Celui-ci est Mon Fils élu, écoutez-le. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Et après que la voix se fut fait entendre, Jésus se trouva seul. Et eux se turent et ne rapportèrent à personne, en ce temps-là, rien de ce qu\'ils avaient vu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Or il advint le jour suivant, après qu\'ils furent descendus de la montagne, qu\'une foule nombreuse vint à sa rencontre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'et voici, un homme s\'écria du sein de la foule: « Maître, je te prie, jette un regard sur mon fils, car c\'est mon fils unique,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'et voici, un esprit le saisit et aussitôt il crie; et il le jette en convulsion en le faisant écumer, et à peine cesse-t-il un moment de le maltraiter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'Et j\'ai prié tes disciples de le chasser et ils n\'ont pas pu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Mais Jésus répliqua: « O génération incrédule et pervertie! Jusques à quand serai-je avec vous, et vous supporterai-je? Amène ici ton fils. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Et comme il s\'approchait, le démon le terrassa et le jeta en convulsion. Mais Jésus réprimanda l\'esprit impur, et guérit l\'enfant, et le rendit à son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Et tous étaient stupéfaits de la grandeur de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Mais, pendant que tous s\'émerveillaient de tout ce qu\'il faisait, il dit à ses disciples: « Pour vous, mettez-vous dans les oreilles ces paroles, c\'est que le fils de l\'homme va être livré aux mains des hommes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Mais ils ne comprenaient pas cette parole, et elle leur demeurait cachée afin qu\'ils ne la comprissent pas, et ils craignaient de l\'interroger là-dessus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Or une pensée s\'empara d\'eux, à savoir lequel d\'entre eux était le plus grand?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Mais Jésus, connaissant la pensée de leur cœur, prit un petit enfant et le plaça auprès de lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'et il leur dit: « Quiconque aura reçu ce petit enfant en mon nom, me reçoit, et quiconque m\'aura reçu, reçoit Celui qui m\'a envoyé. Celui, en effet, qui parmi vous tous est le plus petit, c\'est celui-là qui est grand. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Or Jean répliqua: « Maître, nous avons vu quelqu\'un qui chassait des démons en ton nom, et nous l\'en empêchions parce qu\'il ne nous suit pas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Mais Jésus lui dit: « Ne l\'en empêchez pas; car celui qui n\'est pas contre vous est pour vous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Or il advint, lorsque l\'époque de son enlèvement approchait de son terme, que lui-même prit la résolution de se rendre à Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'et il dépêcha des messagers devant lui. Et étant partis ils entrèrent dans un village des Samaritains pour lui préparer un logement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'et on ne le reçut point, parce qu\'il se dirigeait de sa personne vers Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Or les disciples Jacques et Jean l\'ayant vu, dirent: « Seigneur, veux-tu que nous disions qu\'un feu descende du ciel et les consume? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Mais s\'étant retourné vers eux, il les réprimanda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'et ils se rendirent dans un autre village.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Et pendant qu\'ils étaient en chemin quelqu\'un lui dit: « Je te suivrai où que ce soit que tu t\'en ailles. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Et Jésus lui dit: « Les renards ont des terriers et les oiseaux du ciel des abris, mais le fils de l\'homme n\'a pas où reposer sa tête. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Or il dit à un autre: « Suis-moi; » mais celui-ci dit: « Seigneur, permets-moi de m\'en aller d\'abord enterrer mon père. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Mais il lui dit: « Laisse les morts enterrer leurs morts, mais, pour toi, va-t-en annoncer le royaume de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Or un autre encore dit: « Je te suivrai, Seigneur; mais permets-moi d\'abord de prendre congé des gens de ma maison. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Mais Jésus dit: « Celui qui, après avoir mis la main à la charrue, regarde en arrière, n\'est pas fait pour le royaume de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Or après cela le seigneur désigna soixante et douze autres personnes, qu\'il envoya deux par deux devant lui dans chaque ville et dans chaque lieu où il devait lui-même passer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Or il leur disait: « La moisson est considérable, il est vrai, mais les ouvriers sont en petit nombre. Priez donc le Maître de la moisson afin qu\'il envoie des ouvriers dans Sa moisson.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Allez! Voici, je vous envoie comme des agneaux parmi des loups.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Ne portez point de bourse, ni de besace, ni de sandales, et ne saluez personne sur la route;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'mais dans quelque maison que vous entriez, dites d\'abord: « Paix pour cette maison! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Et s\'il se trouve là un enfant de paix, votre paix reposera sur lui, autrement, elle reviendra à vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Mais demeurez dans cette maison-là en mangeant et buvant ce qui s\'y trouve, car l\'ouvrier mérite son salaire; ne passez point de maison en maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Et dans quelque ville que vous entriez, si l\'on vous reçoit, mangez ce qui vous est servi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'et guérissez les malades qui s\'y trouvent, et dites-leur: « Le royaume de Dieu s\'approche de vous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Mais dans quelque ville que vous entriez, si l\'on ne vous reçoit pas, parcourez ses rues et dites:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, '« La poussière même de votre ville, qui s\'est attachée à nos pieds, nous l\'essuyons pour vous la rendre; sachez cependant ceci, c\'est que le royaume de Dieu s\'approche. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Je vous déclare qu\'en ce jour-là le sort de Sodome sera plus supportable que celui de cette ville-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Malheur à toi, Chorazin! malheur à toi, Bedsaïda! Car si c\'était dans Tyr et dans Sidon qu\'eussent été faits les miracles qui ont été faits parmi vous, dès longtemps elles se seraient repenties en s\'asseyant dans le sac et la cendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Aussi le sort de Tyr et de Sidon sera-t-il plus supportable que le vôtre lors du jugement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Et toi Capharnaoum! Seras-tu élevée jusques au ciel? Tu descendras jusques dans le séjour des morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Celui qui vous écoute, m\'écoute, et celui qui vous rejette, me rejette; mais celui qui me rejette rejette Celui qui m\'a envoyé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Or les soixante-douze revinrent tout joyeux disant: « Seigneur, les démons mêmes se soumettent à nous en ton nom. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Mais il leur dit: « Je voyais Satan tomber du ciel comme un éclair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Voici, je vous ai donné l\'autorité de marcher sur les serpents et les scorpions, et sur toute la puissance de l\'ennemi, et rien absolument ne vous pourra nuire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Ne vous réjouissez pas de ce que vous vous soumettez les esprits, mais réjouissez-vous de ce que vos noms sont inscrits dans les cieux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'En ce moment même il fut rempli d\'allégresse par l\'Esprit saint, et il dit: « Je Te rends grâce, ô Père, Seigneur du ciel et de la terre, de ce que Tu as caché ces choses aux sages et aux intelligents et de ce que Tu les a révélées aux simples; oui, ô Père, de ce que cela s\'est ainsi trouvé bon à Tes yeux!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Tout m\'a été remis par mon Père, et personne ne connaît ce qu\'est le Fils, si ce n\'est le Père, et ce qu\'est le Père, si ce n\'est le Fils, et celui auquel le Fils veut le révéler. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Et s\'étant tourné à part vers les disciples, il dit: « Heureux les yeux qui voient ce que vous voyez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Car je vous déclare que plusieurs prophètes et plusieurs rois ont désiré voir ce que vous voyez, et ne l\'ont pas vu, et entendre de moi ce que vous entendez, et ne l\'ont pas entendu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Et voici, un certain légiste se leva pour le mettre à l\'épreuve, en disant: « Maître, que ferai-je pour hériter la vie éternelle? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Mais il lui dit: « Qu\'est-il écrit dans la loi? Comment lis-tu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'L\'autre répliqua: « Tu aimeras le Seigneur ton Dieu de tout ton cœur, de toute ton âme, et de toute ta force, et de toute ta pensée, et ton prochain comme toi-même. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Or il lui dit: « Tu as bien répondu; fais cela et tu vivras. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Mais l\'autre voulant se justifier, dit à Jésus: « Eh bien, qui est mon prochain? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Jésus répliqua: « Un homme descendit de Jérusalem à Jéricho, et il tomba parmi des brigands, qui, après l\'avoir non seulement dépouillé mais roué de coups, s\'en allèrent, le laissant à demi-mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Or un prêtre, qui d\'aventure descendait par ce chemin, l\'ayant aperçu passa devant lui sans s\'arrêter;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'de même aussi un lévite étant venu en cet endroit et l\'ayant aperçu passa devant lui sans s\'arrêter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Mais un Samaritain que sa route conduisit vers lui l\'ayant aperçu fut ému de compassion,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'et s\'étant approché il banda ses blessures en y versant de l\'huile et du vin, puis l\'ayant fait monter sur sa propre bête, il le conduisit dans une hôtellerie et prit soin de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Et le lendemain ayant déboursé deux deniers, il les donna à l\'hôtelier et lui dit: « Aie soin de lui, et ce que tu dépenseras de plus, c\'est moi qui te le rembourserai à mon retour. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Lequel de ces trois-là te semble avoir été le prochain de celui qui était tombé parmi les brigands? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Or l\'autre dit: « Celui qui lui a donné des preuves de sa compassion. » Et Jésus lui dit: « Va, et toi aussi fais de même. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Pendant qu\'ils poursuivaient leur route, il entra lui-même dans un village. Or une femme nommée Marthe le reçut;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'et elle avait une sœur appelée Marie, qui, se tenant aussi assise aux pieds du seigneur, écoutait ses paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Mais Marthe se laissait distraire par beaucoup d\'occupations, et elle vint dire à Jésus: « Seigneur, cela ne te fait-il rien que ma sœur me laisse toute l\'occupation? Dis-lui donc de me seconder. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Mais Jésus lui répliqua: « Marthe, Marthe, tu te fais des soucis et tu t\'agites pour beaucoup de choses,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'mais il n\'est besoin que de peu de choses, ou plutôt d\'une seule; en effet, Marie a choisi la bonne part, qui ne lui sera point ôtée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Et il advint, pendant qu\'il était lui-même en prière en quelque endroit, que, lorsqu\'il eut fini, l\'un de ses disciples lui dit: « Seigneur, enseigne-nous à prier, comme Jean aussi l\'a enseigné à ses disciples. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Or il leur dit: « Quand vous priez, dites: « Père, que Ton nom soit sanctifié; que Ton royaume vienne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'donne-nous chaque jour le pain de notre subsistance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'et remets-nous nos péchés, car nous aussi nous remettons à tous ceux qui nous doivent; et ne nous expose pas à la tentation. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Et il leur dit: « Lequel de vous, ayant un ami et s\'étant rendu auprès de lui sur le minuit pour lui dire: « Ami, prête-moi trois pains,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'parce qu\'un mien ami venant de voyage est arrivé chez moi, et je n\'ai rien à lui offrir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'et l\'autre lui ayant répondu de l\'intérieur: « Ne me dérange pas, ma porte est déjà fermée, et mes petits enfants sont au lit avec moi, je ne puis pas me lever pour t\'en donner... »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Je vous déclare que, quoiqu\'il ne se lève pas pour lui en donner comme étant son ami, du moins à cause de son indiscrétion il se lèvera pour lui en donner autant qu\'il en demande.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Eh bien, moi je vous dis, demandez et on vous donnera; cherchez et vous trouverez; heurtez et on vous ouvrira;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'car quiconque demande reçoit, et qui cherche trouve, et à celui qui heurte, on ouvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Quel est parmi vous le père auquel son fils demandera un poisson, et qui, à la place d\'un poisson, lui donnera un serpent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Ou encore, qui, s\'il lui demande un œuf, lui donnera un scorpion?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Si donc vous, tout méchants que vous êtes, savez donner de bons présents à vos enfants, à combien plus forte raison le Père céleste donnera-t-Il l\'Esprit saint à ceux qui le Lui demandent? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Et il chassait un démon muet; or il advint, lorsque le démon fut sorti, que le muet parla; et la foule fut émerveillée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Mais quelques-uns d\'entre eux dirent: « C\'est grâce à Béézéboul, le chef des démons, qu\'il chasse les démons. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Mais d\'autres, pour le mettre à l\'épreuve, lui demandaient un signe qui vînt du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Mais lui, connaissant leurs pensées, leur dit: « Tout royaume divisé contre lui-même est dévasté, et on y voit tomber maison sur maison;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'or si Satan aussi s\'est divisé contre lui-même, comment son royaume subsistera-t-il? Car vous dites que c\'est grâce à Béézéboul que je chasse les démons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'mais si moi c\'est grâce à Béézéboul que je chasse les démons, vos fils, grâce à qui les chassent-ils? C\'est pourquoi ce sont eux qui seront vos juges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Mais si c\'est par le doigt de Dieu que moi je chasse les démons, le royaume de Dieu est donc parvenu jusqu\'à vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Lorsque l\'homme fort, bien armé, garde sa propre cour, ce qu\'il possède est en sûreté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'mais s\'il arrive qu\'un plus fort que lui survienne et le vainque, il s\'empare de toutes les armes auxquelles il se confiait, et il distribue ses dépouilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Celui qui n\'est pas avec moi est contre moi, et celui qui ne rassemble pas avec moi disperse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Quand l\'esprit impur est sorti de l\'homme, il parcourt les lieux arides, cherchant du repos, et n\'en trouvant pas, il dit alors: « Je retournerai dans ma maison, d\'où je suis sorti. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Et y revenant, il la trouve en paix, balayée et ornée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Alors il va et prend sept autres esprits plus méchants que lui-même, et après être entrés, ils y habitent; et la nouvelle condition de cet homme devient pire que la première. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Or il advint, pendant qu\'il disait ces choses, qu\'une femme, élevant sa voix du milieu de la foule, lui dit: « Heureux le sein qui t\'a porté et les mamelles qui t\'ont allaité! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Mais il dit: « Heureux bien plutôt ceux qui écoutent la parole de Dieu et qui l\'observent! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Or comme la foule grossissait, il se mit à dire: « Cette génération est méchante; elle réclame un signe, et il ne lui sera donné d\'autre signe que le signe de Jonas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'car, de même que Jonas fut un signe pour les Ninévites, de même le fils de l\'homme en sera aussi un pour cette génération.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'La reine du Midi ressuscitera lors du jugement avec les hommes de cette génération, et elle les condamnera; car elle vint des extrémités de la terre pour entendre la sagesse de Salomon, et voici, il y a ici plus que Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Les hommes de Ninive ressusciteront lors du jugement avec cette génération, et ils la condamneront; car ils se sont repentis à la prédication de Jonas, et voici, il y a ici plus que Jonas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Personne, après avoir allumé une lampe, ne la place dans un souterrain, ni sous le boisseau, mais sur son support, afin que ceux qui entrent en voient la lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Ton œil est la lampe du corps; quand ton œil est sain, tout ton corps aussi est illuminé, mais quand il est malade, ton corps aussi est ténébreux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Prends donc garde que la lumière qui est en toi ne soit ténèbres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Si donc tout ton corps est illuminé, n\'ayant rien de ténébreux, il sera entièrement illuminé, comme lorsque la lampe t\'éclaire par son rayonnement. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Or, pendant qu\'il parlait, un pharisien le sollicite de faire collation chez lui; et y étant entré il se mit à table.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Ce que le pharisien ayant vu, il fut étonné de ce qu\'il ne s\'était pas d\'abord lavé avant la collation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Mais le seigneur lui dit: « Maintenant vous autres pharisiens vous nettoyez le dehors de la coupe et du plat, mais votre dedans est rempli de rapine et de méchanceté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Insensés! Est-ce que Celui qui a fait le dehors n\'a pas fait aussi le dedans?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Eh bien, donnez-en le contenu en aumônes, et voici, tout est net pour vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Mais malheur à vous, pharisiens, car vous payez la dîme de la menthe, et de la rue, et de toutes les plantes potagères, et vous méprisez le jugement et l\'amour de Dieu. Mais ce sont ces choses-ci qu\'il fallait pratiquer, sans toutefois négliger celles-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Malheur à vous, pharisiens, car vous aimez le premier siège dans les synagogues et les salutations dans les places publiques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Malheur à vous, car vous êtes comme les sépulcres masqués, et les hommes en marchant dessus ne s\'en doutent pas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Or un des légistes prenant la parole, lui dit: « Maître, en parlant de la sorte tu nous insultes aussi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Mais il dit: « Malheur aussi à vous autres légistes, car vous chargez les hommes de fardeaux intolérables, et vous-mêmes vous ne touchez pas ces fardeaux d\'un seul de vos doigts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Malheur à vous, car vous bâtissez les tombeaux des prophètes, et ce sont vos pères qui les ont fait mourir!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Vous donnez donc votre témoignage et votre approbation aux œuvres de vos pères, car, tandis que de leur côté ils les ont fait mourir, du vôtre vous bâtissez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'C\'est pourquoi aussi la sagesse de Dieu a dit: Je leur enverrai des prophètes et des apôtres, dont ils tueront les uns et poursuivront les autres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'afin qu\'on redemande compte à cette génération du sang de tous les prophètes, versé dès la fondation du monde,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'depuis le sang d\'Abel jusques au sang de Zacharie qui fut mis à mort entre l\'autel et la maison. Oui, je vous le déclare, on en demandera compte à cette génération.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Malheur à vous légistes, car vous avez enlevé la clef de la connaissance; vous-mêmes n\'êtes pas entrés et vous avez empêché ceux qui voulaient entrer. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Et après qu\'il fut sorti de là, les scribes et les pharisiens se mirent à l\'obséder d\'une manière terrible, et à le presser de questions,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'en lui dressant des pièges, pour attraper quelque parole sortie de sa bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Sur ces entrefaites les myriades de la multitude s\'étant agglomérées de manière à se fouler réciproquement, il se mit à dire à ses disciples: « Avant tout tenez-vous en garde contre le levain, je veux dire l\'hypocrisie, des pharisiens;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'mais il n\'est rien de couvert qui ne doive être manifesté, ni rien de caché qui ne doive être connu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'C\'est pourquoi tout ce que vous avez dit dans les ténèbres sera entendu dans la lumière, et ce dont vous avez parlé à l\'oreille dans les chambres sera proclamé sur les toits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Mais je vous dis, à vous qui êtes mes amis: Ne craignez pas ceux qui tuent le corps, et qui, après cela, ne peuvent rien faire de plus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'mais je vous montrerai qui vous avez à craindre. Craignez Celui qui, après avoir tué, a le pouvoir de jeter dans la géhenne. Oui, je vous le dis, craignez Celui-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Ne vend-on pas cinq passereaux pour deux as? Eh bien, pas un seul d\'entre eux n\'est oublié devant Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'mais les cheveux même de votre tête ont tous été comptés. Ne craignez point; vous valez mieux que beaucoup de passereaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Or je vous déclare que quiconque se déclarera pour moi devant les hommes, le fils de l\'homme se déclarera aussi pour lui devant les anges de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'mais celui qui m\'aura renié devant les hommes sera renié devant les anges de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Et quiconque proférera une parole contre le fils de l\'homme, il lui sera pardonné, mais à celui qui aura blasphémé contre le Saint-Esprit, il ne sera pas pardonné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Mais quand ils vous entraîneront devant les synagogues et les magistrats et les autorités, ne vous inquiétez point de la forme ni des moyens de votre défense, ni de ce que vous pourrez dire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'car le Saint-Esprit vous enseignera à cette heure même ce qu\'il faut dire. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Or quelqu\'un de la foule lui dit: « Maître, dis à mon frère de partager avec moi notre héritage. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Mais il lui dit: « O homme! qui est-ce qui m\'a établi sur vous juge ou arbitre? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Puis il leur dit: « Prenez garde, et préservez-vous de toute espèce de cupidité; car ce n\'est pas parce qu\'il a du superflu, que la vie de quelqu\'un dépend de ce qu\'il possède. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Or il leur adressa une parabole, en disant: « La terre d\'un homme riche avait porté une abondante récolte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'et il délibérait en lui-même, disant: « Que ferai-je? car je n\'ai pas de place pour serrer mes fruits? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Et il dit: « Voici ce que je ferai; j\'abattrai mes greniers et j\'en bâtirai de plus grands, et j\'y serrerai tout mon blé et mes biens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'et je dirai à mon âme: Mon âme, tu as beaucoup de biens amassés pour beaucoup d\'années, repose-toi, mange, bois, réjouis-toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Mais Dieu lui dit: « Insensé, cette nuit-ci on doit te redemander ton âme, mais ce que tu as mis en réserve, à qui sera-t-il? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Il en est ainsi de celui qui thésaurise pour lui-même et qui ne s\'enrichit pas pour Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Puis il dit aux disciples: « C\'est pourquoi je vous le déclare: ne vous inquiétez point pour votre vie de ce que vous mangerez, ni pour votre corps de quoi vous serez vêtus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'car la vie est plus que la nourriture, et le corps plus que le vêtement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Observez les corbeaux: car ils ne sèment, ni ne moissonnent, ils n\'ont ni cellier ni grenier, et Dieu les nourrit. Combien ne valez-vous pas mieux que les oiseaux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Mais lequel de vous peut, par ses inquiétudes, ajouter une coudée à sa taille?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Si donc vous ne pouvez pas même la moindre chose, pourquoi vous inquiétez-vous du reste?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Observez les lys: comment croissent-ils? Ils ne travaillent ni ne filent; cependant je vous le déclare, Salomon dans toute sa gloire ne s\'est pas même vêtu comme l\'un d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Or, si Dieu revêt ainsi dans là campagne l\'herbe qui vit aujourd\'hui et qui demain est jetée dans un four, à combien plus forte raison le fera-t-Il pour vous, gens de peu de foi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Ne cherchez pas non plus ce que vous mangerez et ce que vous boirez, et soyez sans inquiétude;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'car ce sont les nations de ce monde qui recherchent toutes ces choses, tandis que votre Père sait que vous en avez besoin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Eh bien cherchez Son royaume, et ces choses-là vous seront données par-dessus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Ne craignez point, petit troupeau; car votre Père a trouvé bon de vous donner le royaume;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'vendez ce que vous possédez et donnez-le en aumônes, faites-vous des bourses qui ne vieillissent point, un trésor inépuisable dans les cieux, là où le voleur n\'approche point, et où la teigne ne détruit point;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'car là où est votre trésor, là aussi sera votre cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, '« Que vos reins soient ceints, et vos lampes allumées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'et soyez vous-mêmes semblables à des hommes qui attendent le moment où leur maître reviendra des noces, afin que, lorsqu\'il sera arrivé et qu\'il aura heurté, ils lui ouvrent aussitôt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Heureux ces esclaves-là que le maître à son arrivée trouvera veillant! En vérité je vous déclare qu\'il se ceindra, et les fera mettre à table, et qu\'il viendra les servir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Et, soit qu\'il vienne à la deuxième ou à la troisième veille, et qu\'il les trouve en cet état, bien heureux sont-ils!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Mais sachez ceci, c\'est que si le chef de famille savait à quelle heure le voleur devait venir, il aurait veillé, et n\'aurait pas laissé forcer sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Vous aussi soyez prêts, car le fils de l\'homme doit venir à l\'heure dont vous ne vous doutez pas. ».');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Mais Pierre dit: « Seigneur, est-ce à nous que tu adresses cette parabole, ou aussi à tous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Et le seigneur dit: « Quel est donc l\'économe fidèle et prudent que le maître établira sur ses gens pour donner la ration à propos?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Heureux cet esclave que son maître, à son arrivée, trouvera agissant de la sorte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'En vérité je vous déclare qu\'il le mettra à la tête de tous ses biens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Mais si cet esclave-là se dit en son cœur: Mon maître tarde à venir, et qu\'il se mette à battre les serviteurs et les servantes, à manger, à boire et à s\'enivrer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'le maître de cet esclave arrivera le jour où il ne s\'y attend pas, et à l\'heure qu\'il ne connaît pas, et il le pourfendra, et il lui assignera son lot parmi les infidèles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Mais cet esclave qui, ayant connu la volonté de son maître, ne s\'est pas tenu prêt ou n\'a pas agi selon sa volonté, sera battu de plusieurs coups;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'tandis que celui qui, ne l\'ayant pas connue, a fait néanmoins des choses dignes de châtiment, sera battu de peu de coups. Or, à quiconque il a été beaucoup donné, il lui sera beaucoup redemandé, et à qui on a beaucoup confié, on lui demandera encore davantage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Je suis venu apporter du feu sur la terre, et qu\'ai-je à désirer si déjà il est allumé?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Mais il est un baptême dont je dois être baptisé; et dans quelle angoisse ne suis-je pas, jusques à ce qu\'il ait été accompli!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Vous imaginez-vous que je suis venu pour mettre la paix sur la terre? Non, vous dis-je, mais plutôt la discorde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'car désormais il y en aura cinq dans une maison qui seront en discorde, trois contre deux, et deux contre trois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'le père sera en discorde avec le fils et le fils avec le père, la mère avec la fille, et la fille avec la mère, la belle-mère avec sa bru, et la bru avec la belle-mère. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Or il disait aussi à la foule: « Quand vous voyez un nuage qui se lève au couchant, vous dites aussitôt: « la pluie va venir, » et c\'est ce qui arrive;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'et quand vous voyez souffler le vent du midi, vous dites: « il y aura une grande chaleur, » et c\'est ce qui arrive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Hypocrites! vous savez discerner l\'aspect de la terre et du ciel, mais comment ne savez-vous pas discerner le temps actuel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Mais pourquoi ne jugez-vous pas non plus par vous-mêmes de ce qui est juste?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Car lorsque tu vas avec ton adversaire devant un magistrat, fais tes efforts pendant la route pour te réconcilier avec lui, de peur qu\'il ne te traîne devant le juge; et le juge te livrera au recors et le recors te jettera en prison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Je te déclare que tu ne sortiras certainement pas de là, que tu n\'aies payé jusqu\'à la dernière pite. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Or, en ce moment même, quelques personnes vinrent lui faire un rapport sur ces Galiléens, dont Pilate avait mêlé le sang avec celui de leurs victimes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Et il leur répliqua: « Vous imaginez-vous que ces Galiléens fussent plus pécheurs que tout le reste des Galiléens, parce qu\'ils ont souffert de la sorte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Non, vous dis-je, mais si vous ne vous repentez, vous périrez tous de même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Ou bien, ces dix-huit individus sur lesquels est tombée la tour dans les environs de Siloam, et qui en sont morts, vous imaginez-vous qu\'ils fussent plus coupables que tous les hommes qui habitent Jérusalem?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Non, vous dis-je, mais si vous ne vous repentez, vous périrez tous de la même manière. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Or il disait cette parabole: « Quelqu\'un possédait un figuier planté dans sa vigne, et il vint y chercher du fruit et n\'en trouva pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'or il dit au vigneron: « Voici trois ans que je viens chercher du fruit sur ce figuier et que je n\'en trouve point; coupe-le; pourquoi occupe-t-il encore inutilement la place? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Mais l\'autre lui répliqua: « Seigneur, laisse-le encore cette année, jusques à ce que j\'aie creusé alentour et que j\'y aie mis du fumier;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'peut-être portera-t-il du fruit l\'an qui vient; autrement tu le feras couper. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Or il enseignait dans une des synagogues le jour du sabbat;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'et voici une femme possédée depuis dix-huit ans d\'un esprit qui la rendait infirme, en sorte qu\'elle se tenait courbée sans pouvoir se redresser du tout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Mais Jésus l\'ayant vue, l\'appela et lui dit: « Femme, sois délivrée de ton infirmité! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'Et il lui imposa les mains, et immédiatement elle se redressa, et elle glorifiait Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Mais le chef de la synagogue indigné de ce que Jésus avait opéré une guérison le jour du sabbat, disait à la foule: « Il y a six jours pendant lesquels il faut travailler, venez donc vous faire guérir ces jours-là, et non pas le jour du sabbat. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Mais le Seigneur lui répliqua: « Hypocrites, est-ce que chacun de vous ne détache pas de la crèche son bœuf ou son âne le jour du sabbat, pour le mener boire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Et celle-ci, qui est une fille d\'Abraham, et que Satan tenait liée voici dix-huit ans, il ne fallait pas la détacher de cette chaîne le jour du sabbat! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Et pendant qu\'il parlait ainsi tous ses adversaires étaient couverts de confusion, et toute la foule se réjouissait de toutes les merveilles opérées par lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Il disait donc: « A quoi ressemble le royaume de Dieu, et à quoi le comparerai-je?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Il est semblable à un grain de moutarde, qu\'un homme a pris et jeté dans son jardin, et il a crû et il est devenu un arbre, et les oiseaux du ciel se sont abrités dans ses branches. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Et il dit derechef: « A quoi comparerai-je le royaume de Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Il est semblable à du levain qu\'une femme a pris et pétri dans trois mesures de farine, jusques à ce que le tout fût levé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'Et il traversait villes et villages, enseignant et faisant route vers Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Or quelqu\'un lui dit: « Seigneur, ceux qui sont sauvés, sont-ils en petit nombre? » Mais il leur dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, '« Efforcez-vous d\'entrer par la porte étroite, car beaucoup, je vous le déclare, chercheront à entrer et ne le pourront pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Dès que le chef, de famille se sera levé et aura fermé la porte, et que vous commencerez à vous tenir dehors et à heurter à la porte, en disant: « Seigneur, ouvre-nous, » et qu\'il vous répliquera: « Je ne sais pas d\'où vous êtes, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'alors vous vous mettrez à dire: « Nous mangions et nous buvions en ta présence, et c\'est dans nos rues que tu as enseigné. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Et il vous dira: « Je ne sais d\'où vous êtes; éloignez-vous de moi, vous tous qui êtes des ouvriers d\'iniquité. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Là sera le pleur et le grincement des dents, lorsque vous verrez Abraham et Isaac et Jacob et tous les prophètes dans le royaume de Dieu, tandis que vous serez, exclus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Et il en viendra d\'orient et d\'occident, et du nord et du midi, et ils se mettront à table dans le royaume de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Et voici, il y en a des derniers qui seront des premiers, et il y en a des premiers qui seront des derniers. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'Au même moment quelques pharisiens survinrent qui lui dirent: « Sors, et éloigne-toi d\'ici, car Hérode veut te faire périr. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Et il leur dit: « Allez dire à ce renard: Voici, je chasse les démons, et j\'opérerai des guérisons aujourd\'hui et demain; et le troisième jour j\'ai fini;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'néanmoins il faut que je continue ma route aujourd\'hui, demain, et le jour suivant, car il n\'est pas reçu qu\'un prophète meure hors de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jérusalem, Jérusalem, qui tue les prophètes et qui lapide ceux qui lui sont envoyés, que de fois j\'ai voulu rassembler tes enfants comme une poule rassemble sa couvée sous ses ailes, et vous ne l\'avez pas voulu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Voici, votre demeure vous est laissée; mais, je vous le déclare, vous ne me verrez certainement plus jusques à ce que vous disiez: « Béni soit celui qui vient au nom du Seigneur! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Et il advint, qu\'étant entré dans la maison de l\'un des chefs des pharisiens, un jour de sabbat, pour prendre un repas, ils étaient occupés à l\'épier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Et voici, il y avait devant lui un homme hydropique;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'et Jésus prenant la parole dit aux légistes et aux pharisiens: « Est-il permis, oui ou non, d\'opérer une guérison le jour du sabbat? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Mais ils se turent; et l\'ayant pris à lui, il le guérit et le congédia;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'et il leur dit: « Lequel de vous, si son fils ou son bœuf tombe dans un puits, ne l\'en retirera aussitôt le jour du sabbat? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Et ils ne purent de leur côté répondre à cela.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Or il adressait aux conviés une parabole, après avoir remarqué comment ils choisissaient les premières places, en leur disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, '« Lorsque tu auras été convié par quelqu\'un à des noces, ne t\'installe pas à la première place, de peur qu\'un plus noble que toi n\'ait été convié par lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'et que celui qui vous a conviés l\'un et l\'autre ne te dise: « Fais place à celui-ci, » et alors tu te mettras avec honte à occuper la dernière place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Mais quand tu auras été convié, va t\'établir à la dernière place, afin que, lorsque celui qui t\'a convié sera venu, il te dise: « Ami, monte plus haut. » Alors tu seras honoré en présence de tous ceux qui sont à table avec toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Car quiconque s\'élève lui-même sera abaissé et celui qui s\'abaisse lui-même sera élevé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Or il disait aussi à celui qui l\'avait convié: « Quand tu donnes une collation ou un repas, n\'invite ni tes amis, ni tes frères, ni tes parents, ni de riches voisins, de peur qu\'eux aussi ne t\'invitent à leur tour, et qu\'on ne te rende la pareille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Mais quand tu donnes un festin, invite les pauvres, les estropiés les boiteux, les aveugles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'et tu seras heureux de ce qu\'ils ne peuvent te rendre la pareille, car elle te sera rendue lors de la résurrection des justes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Mais après avoir entendu cela l\'un des conviés lui dit: « Heureux quiconque prendra un repas dans le royaume de Dieu! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Mais il lui dit: « Un homme donnait un grand repas, et il invita plusieurs personnes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'et il envoya son esclave à l\'heure du repas dire aux conviés: « Venez, car c\'est déjà prêt. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Et tous, d\'un même accord, se mirent à s\'excuser. Le premier lui dit: « J\'ai acheté un champ, et je suis obligé d\'aller le visiter; je te prie, veuille m\'excuser. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Et un autre dit: « J\'ai acheté cinq paires de bœufs, et je vais les essayer; je te prie, veuille m\'excuser. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Et un autre dit: « J\'ai pris femme, et à cause de cela je ne puis pas aller. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Et l\'esclave vint rapporter cela à son maître. Alors le chef de famille irrité dit à son esclave: « Va promptement dans les rues et les ruelles de la ville, et amène ici les pauvres, et les estropiés, et les aveugles et les boiteux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Et l\'esclave dit: « Seigneur, ce que tu as ordonné est fait, et il y a encore de la place. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Et le maître dit à l\'esclave: « Va le long des chemins et des clôtures, et contrains d\'entrer afin que la maison soit pleine;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'je vous déclare en effet qu\'aucun de ces hommes que j\'avais conviés ne goûtera de mon repas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Or une foule nombreuse cheminait avec lui, et s\'étant retourné il leur dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, '« Si quelqu\'un vient à moi et ne hait pas son propre père, et sa mère, et sa femme, et ses enfants, et ses frères, et ses sœurs, et en outre encore sa propre vie, il ne peut pas être mon disciple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Quiconque donc ne porte pas sa propre croix et ne marche pas derrière moi ne peut pas être mon disciple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Quel est en effet celui d\'entre vous qui, voulant bâtir une tour, ne s\'asseye d\'abord pour calculer la dépense et voir s\'il a de quoi en venir à bout?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'De peur que, si, après avoir posé la fondation, il ne peut achever, tous les spectateurs ne se mettent à le bafouer, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, '« Cet homme a commencé à bâtir et il n\'a pu achever! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Ou bien quel est le roi qui, se mettant en marche pour faire la guerre à un autre roi, ne s\'asseye d\'abord afin de délibérer s\'il peut avec dix mille hommes affronter celui qui s\'avance contre lui avec vingt mille?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Autrement, pendant que l\'autre est encore éloigné, il lui envoie une ambassade pour demander la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Ainsi donc quiconque d\'entre vous ne renonce pas à tout ce qu\'il possède ne peut être mon disciple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Le sel est donc bon; mais si le sel même s\'est affadi, avec quoi l\'assaisonnera-t-on?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Il n\'est bon ni pour la terre ni pour le fumier; on le jettera dehors. Que celui qui a des oreilles pour entendre entende.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Or tous les publicains et les pécheurs s\'approchaient de lui pour l\'entendre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'et les pharisiens et les scribes murmuraient en disant: « Celui-ci accueille des pécheurs et mange avec eux! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Mais il leur adressa cette parabole-ci, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, '« Quel est parmi vous l\'homme qui, possédant cent brebis, s\'il vient à en perdre une, ne laisse les quatre-vingt-dix-neuf autres dans le désert, et n\'aille après celle qui est perdue jusques à ce qu\'il l\'ait retrouvée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Et, quand il l\'a retrouvée, il la place tout joyeux sur ses épaules,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'et, de retour chez lui, il appelle ses amis et ses voisins, en leur disant: « Réjouissez-vous avec moi, car j\'ai retrouvé ma brebis qui était perdue. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Je vous déclare que, de même, il y aura plus de joie dans le ciel pour un seul pécheur qui se repent, que pour quatre-vingt-dix-neuf justes qui n\'ont pas besoin de repentance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Ou bien, quelle est la femme qui, possédant dix drachmes, si elle vient à en perdre une, n\'allume une lampe, et ne balaye sa maison, et ne cherche soigneusement jusques à ce qu\'elle la retrouve?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Et, après l\'avoir trouvée, elle appelle ses amies et ses voisines, en disant: « Réjouissez-vous avec moi, car j\'ai retrouvé la drachme que j\'avais perdue. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'De même, je vous le déclare, il y a de la joie devant les anges de Dieu pour un seul pécheur qui se repent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Or il dit: « Un homme avait deux fils;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'le plus jeune d\'entre eux dit à son père: « Père, donne-moi la part de fortune qui me revient. » Et il leur partagea le bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Et, au bout de quelques jours, le plus jeune fils, ayant tout réalisé, partit pour un lointain pays, et là il dissipa sa fortune en vivant dans la débauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Mais quand il eut tout dépensé, une grande famine survint dans ce pays-là, et lui-même commença à se trouver dans le dénuement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'et il s\'en alla se mettre au service de l\'un des citoyens de ce pays-là, et celui-ci l\'envoya dans ses champs pour faire paître des pourceaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Et il désirait se rassasier des gousses que mangeaient les pourceaux, et personne ne lui en donnait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Mais rentrant en lui-même il dit: Combien de mercenaires de mon père ont plus de pain qu\'il ne leur en faut, tandis que moi je meurs ici de faim;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'je m\'en irai vers mon père et je lui dirai: « Père, j\'ai péché contre le ciel et devant toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'je ne suis plus digne d\'être appelé ton fils; traite-moi comme l\'un de tes mercenaires. » Et il s\'en alla vers son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Or, comme il était encore à distance, son père l\'aperçut et fut touché de compassion, et étant accouru il se jeta à son col et lui donna un tendre baiser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Mais le fils lui dit: « Père, j\'ai péché contre le ciel et devant toi, je ne suis plus digne d\'être appelé ton fils; traite-moi comme l\'un de tes mercenaires. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Mais le père dit à ses esclaves: « Apportez vite une robe, la plus belle, et revêtez-le, et mettez un anneau à sa main, et des sandales à ses pieds,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'et amenez le veau gras; tuez-le, et que nous nous réjouissions en le mangeant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'car mon fils que voici était mort et il a vécu; il était perdu et il a été retrouvé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Et ils se mirent à se réjouir. Or son fils aîné était aux champs, et lorsqu\'à son retour il approcha de la maison, il entendit de la musique et des danses,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'et ayant appelé un des serviteurs il s\'informait de ce que c\'était.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'L\'autre lui dit: « Ton frère est arrivé, et ton père a fait tuer le veau gras, parce qu\'il l\'a retrouvé en bonne santé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Mais il se mit en colère et ne voulait pas entrer. Cependant son père étant sorti le sollicitait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'mais il répliqua à son père: « Voici, il y a un si grand nombre d\'années que je te sers, et je n\'ai jamais transgressé aucun de tes ordres, et tu ne m\'as jamais donné un chevreau, pour que je me réjouisse avec mes amis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'mais quand ton fils que voici, qui a mangé ton bien avec des courtisanes, est arrivé, tu as fait tuer pour lui le veau gras! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Mais il lui dit: « Mon enfant, tu es toujours avec moi, et tout ce qui est à moi t\'appartient;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'mais il fallait se réjouir et s\'égayer, parce que ton frère que voici était mort et il a vécu, il était perdu et il a été retrouvé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Or il disait aussi aux disciples: « Il y avait un homme riche, qui avait un économe; et celui-ci lui fut dénoncé comme dilapidant ce qui lui appartenait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Et l\'ayant appelé il lui dit: « Qu\'est-ce que j\'apprends là sur toi? Rends compte de ta gestion, car tu ne peux plus l\'exercer. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Mais l\'économe se dit en lui-même: Que ferai-je, puisque mon maître m\'enlève la gestion? Je ne puis pas labourer, et j\'ai honte de mendier;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'je sais ce que je ferai, afin que, lorsque j\'aurai été destitué de la gestion, il y ait des gens qui me reçoivent dans leurs maisons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Et ayant fait venir chacun des débiteurs de son maître, il disait au premier: « Combien dois-tu à mon maître? » Et l\'autre dit: « Cent tonneaux d\'huile. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Mais il lui dit: « Tiens ton obligation, assieds-toi, et écris immédiatement cinquante. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Ensuite il dit à un autre: « Et toi, combien dois-tu? » Et l\'autre dit: « Cent mesures de blé. » Il lui dit: « Tiens ton obligation, et écris quatre-vingts. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Et le maître loua l\'économe inique, parce qu\'il avait prudemment agi; car les fils de ce siècle-ci sont plus prudents envers leur propre génération que les fils de la lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Moi aussi je vous dis: Faites-vous des amis au moyen du Mamôna d\'iniquité, afin que, lorsqu\'il vous manquera, ils vous reçoivent dans les tabernacles éternels.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Celui qui est fidèle pour très peu de chose est aussi fidèle pour beaucoup; et celui qui est inique en très peu de chose est aussi inique dans beaucoup.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Si donc vous ne vous êtes pas montrés fidèles pour la richesse inique, qui est-ce qui vous confiera la véritable?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Et si vous ne vous êtes pas montrés fidèles pour le bien d\'autrui, qui est-ce qui vous donnera le nôtre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Nul serviteur ne peut servir deux maîtres, car, ou bien il haïra l\'un et aimera l\'autre, ou bien il s\'attachera à l\'un et méprisera l\'autre; vous ne pouvez servir Dieu et Mamôna. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Or les pharisiens, qui étaient amis de l\'argent, entendirent toutes ces choses, et ils se moquaient de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Et il leur dit: « Vous êtes de ceux qui se justifient eux-mêmes devant les hommes, mais Dieu connaît vos cœurs; car l\'arrogance chez l\'homme est une abomination devant le Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'La loi et les prophètes ont subsisté jusques à Jean; dès lors est annoncée la bonne nouvelle du royaume de Dieu, et chacun s\'y introduit par violence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Or il est plus facile que le ciel et la terre disparaissent, qu\'il ne l\'est qu\'un seul jambage de la loi soit anéanti.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Quiconque répudie sa femme et en épouse une autre commet un adultère, et celui qui épouse une femme répudiée par son mari commet un adultère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, '« Or il y avait un homme riche, lequel s\'habillait de pourpre et de soie, menant chaque jour avec éclat une joyeuse vie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'mais un pauvre, nommé Lazare, avait été jeté près de sa porte, tout couvert d\'ulcères');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'et désireux de se rassasier de ce qui tombait de la table du riche; mais les chiens même venaient lécher ses ulcères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Or il advint que ce pauvre mourut, et qu\'il fut emporté par les anges dans le sein d\'Abraham; mais le riche mourut aussi, et il fut enterré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Et dans le séjour des morts, ayant levé les yeux du milieu des tourments, il voit de loin Abraham et Lazare dans son sein;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'et il s\'écria: « Père Abraham, aie pitié de moi, et envoie Lazare afin qu\'il trempe dans l\'eau le bout de son doigt, et qu\'il rafraîchisse ma langue, car je suis à la torture dans cette flamme. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Mais Abraham dit: « Mon enfant, rappelle-toi que tu as reçu tes biens pendant ta vie, et de même Lazare ses maux; mais maintenant il est ici consolé, tandis que toi, tu es à la torture;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'et d\'ailleurs, entre nous et vous s\'ouvre un vaste abîme, afin que ceux qui veulent passer d\'ici vers vous ne le puissent pas, et que de là-bas ils ne traversent pas non plus vers nous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Mais il dit: « Je te supplie donc, Père, de l\'envoyer dans la maison de mon père,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'car j\'ai cinq frères, afin qu\'il les avertisse, de peur qu\'eux aussi ne viennent dans ce lieu de tourment. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Mais Abraham dit: « Ils ont Moïse et les prophètes, qu\'ils les écoutent!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Mais l\'autre dit: « Non, Père Abraham, mais si quelqu\'un vient de chez les morts auprès d\'eux, ils se repentiront. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Mais il lui dit: « S\'ils n\'écoutent ni Moïse ni les prophètes, ils ne se laisseront pas non plus persuader quand même quelqu\'un ressusciterait des morts. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Or il dit à ses disciples: « Il est inévitable qu\'il arrive des scandales, néanmoins malheur à celui par lequel ils arrivent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'il lui est plus avantageux qu\'on lui mette au col une pierre meulière, et qu\'on le précipite dans la mer, que de scandaliser un seul de ces petits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Prenez garde à vous-mêmes: Si ton frère a péché, reprends-le, et s\'il se repent, pardonne-lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'et si, sept fois le jour, il a péché contre toi, et que sept fois il revienne vers toi, en disant: « Je me repens, » tu lui pardonneras. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Et les apôtres dirent au seigneur: « Mets en nous plus de foi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Mais le seigneur dit: « Si vous aviez de la foi, gros comme un grain de moutarde, vous diriez à ce mûrier-ci: « Déracine-toi, et plante-toi dans la mer; » et il vous obéirait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Mais lequel de vous, ayant un esclave qui conduit la charrue ou paît les troupeaux, lui dira, à son retour des champs: « Viens vite te mettre à table? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Est-ce qu\'au contraire il ne lui dira pas: « Prépare-moi à manger, et ceins-toi pour me servir jusques à ce que j\'aie mangé et bu, et après cela, toi, tu mangeras et tu boiras? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Est-ce qu\'il sait gré à l\'esclave de ce qu\'il a fait ce qui lui était prescrit?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'De même vous aussi, quand vous aurez fait tout ce qui vous a été prescrit, dites: Nous sommes des esclaves inutiles, c\'est ce que nous devions faire que nous avons fait. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Et il advint, pendant le voyage vers Jérusalem, qu\'il passait entre la Samarie et la Galilée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Et comme il entrait dans un village, vinrent à sa rencontre dix hommes lépreux, qui se levèrent de loin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'et ils haussèrent la voix en disant: « Jésus, maître, aie pitié de nous! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Ce que voyant, il leur dit: « Allez vous montrer aux prêtres. » Et il advint, pendant qu\'ils s\'y rendaient, qu\'ils furent guéris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Or l\'un d\'entre eux voyant qu\'il avait été guéri revint glorifiant Dieu à haute voix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'et il tomba la face contre terre à ses pieds en lui rendant grâces; et c\'était un Samaritain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Mais Jésus prenant la parole dit: « Les dix n\'ont-ils pas été guéris? Mais les neuf où sont-ils?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'On ne les a pas vus revenir pour donner gloire à Dieu, sauf cet étranger. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'Et il lui dit: « Lève-toi, va-t-en. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Or ayant été interrogé par les pharisiens sur l\'époque de la venue du royaume de Dieu, il leur répliqua: « Le royaume de Dieu ne vient pas de manière à être épié,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'et l\'on ne dira point: « Le voici ici, ou là. » Car voici, le royaume de Dieu est au milieu de vous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Mais il dit aux disciples: « Des jours viendront, où vous désirerez voir un des jours du fils de l\'homme, et vous ne le verrez pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'et on vous dira: « Le voici ici, ou le voilà là; » n\'y courez pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'car, comme l\'éclair flamboyant brille de l\'une des extrémités du ciel jusques à l\'autre extrémité du ciel, il en sera de même du fils de l\'homme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'mais il faut d\'abord qu\'il souffre beaucoup, et qu\'il soit rejeté par cette génération.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Et comme il est advenu du temps de Noé, de même adviendra-t-il aussi du temps du fils de l\'homme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'on mangeait, on buvait, les hommes prenaient des femmes et on donnait aux femmes des maris, jusques au jour où Noé entra dans l\'arche; et le déluge survint et les fit tous périr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'De même, comme il advint du temps de Lot, on mangeait, on buvait, on achetait, on vendait, on plantait, on bâtissait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'mais le jour où Lot sortit de Sodome, il tomba du ciel une pluie de feu et de soufre et elle les fit tous périr,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'de même en sera-t-il le jour où le fils de l\'homme sera révélé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'En ce jour-là, que celui qui sera sur le toit, et dont les ustensiles sont dans la maison, ne descende point pour les prendre, et que celui qui est aux champs ne revienne pas non plus en arrière:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'souvenez-vous de la femme de Lot.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Mais celui qui aura cherché à rester en possession de sa vie la perdra, tandis que celui qui l\'aura perdue la conservera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Je vous le déclare, cette nuit-là deux personnes seront sur un lit, l\'une sera prise et l\'autre sera laissée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Deux femmes moudront ensemble, l\'une sera prise, mais l\'autre sera laissée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, '[Deux hommes seront dans la campagne, l\'un sera pris et l\'autre sera laissé.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'Et prenant la parole ils lui dirent: « Où, Seigneur? » Mais il leur dit: « Là où est le corps, c\'est là aussi que se rassembleront les aigles. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Or, pour leur montrer qu\'il fallait toujours prier et ne pas perdre courage, il leur adressait une parabole');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'en ces termes: « Il y avait dans une ville un certain juge qui ne craignait point Dieu et n\'avait d\'égards pour personne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'or dans cette ville-là était une veuve, et elle venait lui dire: « Fais-moi justice de mon adversaire. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Et pendant longtemps il ne le voulait pas; mais ensuite il se dit en lui-même: Quoique je ne craigne point Dieu et que je n\'aie non plus d\'égards pour personne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'cependant comme cette veuve me cause du tracas, je lui ferai justice, de peur qu\'elle ne finisse par venir me donner des coups. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Or le seigneur dit: « Écoutez ce que dit le juge inique;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'mais Dieu ne fera-t-Il pas justice à Ses élus qui crient à Lui jour et nuit, et tarde-t-Il à leur égard?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Je vous déclare qu\'il leur fera justice au plus tôt. Toutefois le fils de l\'homme, quand il viendra, trouvera-t-il la foi sur la terre? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Or il dit aussi à quelques personnes qui possédaient pour elles-mêmes l\'assurance d\'être justes et qui méprisaient les autres, la parabole suivante:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, '« Deux hommes montèrent au temple pour prier, l\'un était pharisien, et l\'autre publicain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Le pharisien, se tenant debout, faisait en lui-même cette prière: « O Dieu! Je Te rends grâce de ce que je ne suis pas comme les autres hommes qui sont spoliateurs, injustes, adultères, ou même comme ce publicain:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'je jeûne deux fois la semaine, je donne la dîme de tout ce que j\'acquiers. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Mais le publicain se tenant à distance ne se permettait pas même de lever les yeux vers le ciel, mais il se frappait la poitrine en disant: « O Dieu, aie compassion de moi qui suis pécheur! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Je vous le déclare, celui-ci redescendit justifié dans sa maison à l\'inverse de l\'autre, car quiconque s\'élève lui-même sera abaissé, tandis que celui qui s\'abaisse lui-même sera élevé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Or on lui apportait aussi les petits enfants, afin qu\'il les touchât; ce que les disciples ayant vu ils les réprimandaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Mais Jésus les appela à lui, en disant: « Laissez les petits enfants venir à moi, et ne les en empêchez pas, car c\'est à ceux qui leur ressemblent qu\'appartient le royaume de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'En vérité je vous le déclare, celui qui n\'aura pas reçu le royaume de Dieu comme un petit enfant n\'y entrera certainement point. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Et un chef l\'interrogea en disant: « Bon Maître, par quelle conduite hériterai-je la vie éternelle? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Mais Jésus lui dit: « Pourquoi m\'appelles-tu bon? Nul n\'est bon, si ce n\'est un seul, Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Tu connais les commandements: « Ne commets point d\'adultère; ne tue point; ne dérobe point; ne fais point de faux témoignage; honore ton père et ta mère. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'L\'autre dit: « J\'ai observé toutes ces choses dès ma jeunesse. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Ce que Jésus ayant ouï, il lui dit: « Il te manque encore une chose: vends tout ce que tu possèdes, et distribue-le aux pauvres, et tu auras un trésor dans les cieux; puis viens, suis-moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Mais l\'autre en entendant cela devint tout triste, car il était très riche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Or Jésus l\'ayant regardé dit: « Avec quelle difficulté ceux qui possèdent les richesses entrent-ils dans le royaume de Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Il est en effet plus facile qu\'un chameau entre par un trou d\'aiguille, qu\'un riche n\'entre dans le royaume de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Mais les auditeurs dirent: « Et qui peut être sauvé? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Or il dit: « Ce qui est impossible quant aux hommes est possible quant à Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Or Pierre lui dit: « Voici, pour nous, après avoir abandonné nos propres biens, nous t\'avons suivi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Et il leur dit: « En vérité je vous déclare qu\'il n\'est personne qui, ayant abandonné maison, ou femme, ou frères, ou parents, ou enfants, à cause du royaume de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'ne reçoive infiniment davantage dans ce temps-ci, et dans le siècle à venir la vie éternelle. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Et ayant pris les douze à part, il leur dit: « Voici, nous montons à Jérusalem, et tout ce qui a été écrit par les prophètes relativement au fils de l\'homme s\'accomplira;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'car il sera livré aux Gentils, et il sera bafoué et injurié, et on crachera sur lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'et après l\'avoir fouetté ils le mettront à mort, et le troisième jour il ressuscitera. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Et pour eux ils ne comprenaient rien à cela, et cette parole leur était cachée, et ils ne saisissaient pas ce qui avait été dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Or il advint, au moment où il approchait de Jéricho, qu\'un aveugle se trouvait assis près du chemin pour mendier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Mais ayant entendu la foule qui passait devant lui, il s\'informait de ce que c\'était.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'On lui dit: « C\'est Jésus le Nazaréen qui passe. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Et il s\'écria: « Jésus, fils de David, aie pitié de moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Et ceux qui marchaient les premiers le réprimandaient pour le faire taire; mais lui criait de plus belle: « Fils de David, aie pitié de moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Et Jésus s\'étant arrêté ordonna qu\'on le lui amenât; et quand il se fut approché, il lui demanda: « Que veux-tu que je fasse pour toi? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Et l\'autre dit: « Seigneur, que je recouvre la vue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Et Jésus lui dit: « Recouvre la vue; ta foi t\'a guéri. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Et immédiatement il recouvra la vue, et il le suivait en glorifiant Dieu. Et tout le peuple voyant cela rendit louange à Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Puis étant entré, il traversait Jéricho,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'et voici, un homme nommé Zachée, qui lui-même était chef des publicains et qui était riche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'cherchait à voir quel était Jésus, et il ne pouvait y parvenir à cause de la multitude, car il était de petite taille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Et ayant couru en avant il monta sur un sycomore, afin de le voir, parce qu\'il devait passer par là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Et lorsqu\'il fut arrivé à cet endroit, Jésus levant les yeux lui dit: « Zachée, hâte-toi de descendre; car il faut que je demeure aujourd\'hui dans ta maison. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Et il se hâta de descendre, et il le reçut avec joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Et tous à cette vue murmuraient, en disant: « Il est allé se loger chez un pécheur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Cependant Zachée, se tenant debout, dit au seigneur: « Voici, seigneur, je donne aux pauvres la moitié de ce qui m\'appartient, et si j\'ai extorqué quelque chose à quelqu\'un, je l\'en dédommage au quadruple. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Or Jésus lui dit: « Aujourd\'hui le salut s\'est réalisé pour cette maison, parce que lui aussi est un fils d\'Abraham;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'car le fils de l\'homme est venu chercher et sauver ce qui était perdu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Pendant qu\'ils écoutaient ces choses, il prononça une nouvelle parabole, parce qu\'il approchait de Jérusalem et qu\'eux-mêmes s\'imaginaient que le royaume de Dieu allait être immédiatement inauguré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Il dit donc: « Un homme de grande naissance se rendit dans un pays éloigné, pour s\'y mettre en possession d\'un royaume et pour revenir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Or ayant appelé dix de ses esclaves, il leur donna dix mines, et leur dit: « Faites-les valoir jusques à ce que je revienne. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Mais ses concitoyens le haïssaient, et ils envoyèrent une ambassade après lui pour dire: « Nous ne voulons pas que celui-ci règne sur nous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Et il advint, lorsqu\'il fut de retour, après s\'être mis en possession du royaume, qu\'il manda auprès de lui ces esclaves auxquels il avait donné l\'argent, afin de savoir comment ils l\'avaient fait valoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Or le premier se présenta en disant: « Seigneur, ta mine a rapporté dix mines. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Et il lui dit: « C\'est bien, bon esclave, comme tu as été fidèle en peu de chose, aie autorité sur dix villes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Et le second vint en disant: « Seigneur, ta mine a produit cinq mines, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Et il dit aussi à celui-ci: « Toi aussi, préside sur cinq villes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'Et l\'autre vint en disant: « Seigneur, voici ta mine que j\'avais mise dans un linge;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'car je te craignais, parce que tu es un homme sévère, tu retires ce que tu n\'as pas déposé, et tu moissonnes ce que tu n\'as pas semé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Mais il lui dit: « C\'est sur ta propre déclaration que je te juge, mauvais esclave; tu savais que je suis un homme sévère, retirant ce que je n\'ai pas déposé et moissonnant ce que je n\'ai pas semé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'et pourquoi n\'as-tu pas placé mon argent dans une banque, et à mon retour je l\'aurais retiré avec intérêt? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Puis il dit à ceux qui étaient là: « Enlevez-lui la mine et donnez-la à celui qui a les dix mines. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'Et ils lui dirent: « Seigneur, il a dix mines. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Je vous déclare qu\'à quiconque a, il sera donné, mais à celui qui n\'a pas, même ce qu\'il a lui sera enlevé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Cependant amenez ici ces ennemis de ma personne, qui n\'ont pas voulu que je régnasse sur eux, et égorgez-les en ma présence. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Et après avoir dit ces choses, il continuait à marcher en avant, montant vers Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Et il advint, lorsqu\'il approcha du Bethsphagé et de Béthanie, vers la montagne appelée le Bois d\'oliviers qu\'il dépêcha deux des disciples, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, '« Allez dans le village qui est en face; en y entrant vous trouverez un ânon attaché, sur lequel aucun homme ne s\'est jamais assis; et après l\'avoir détaché amenez-le;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'et si quelqu\'un vous demande: « Pourquoi le détachez-vous? » vous répondrez ainsi: « C\'est parce que le seigneur en a besoin. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Or ceux qui étaient dépêchés étant partis, trouvèrent les choses comme il les leur avait dites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Mais, pendant qu\'ils détachaient l\'ânon, les propriétaires de celui-ci leur dirent: « Pourquoi détachez-vous cet ânon? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Or ils dirent: « C\'est parce que le seigneur en a besoin. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'Et ils l\'amenèrent à Jésus, et après avoir jeté leurs manteaux sur l\'ânon, ils firent monter Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Or pendant qu\'il s\'acheminait, ils étendaient leurs manteaux sur le chemin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'mais comme déjà il approchait, à la descente du mont des Oliviers, toute la multitude des disciples dans la joie se mit à louer Dieu à voix haute pour tous les miracles qu\'ils avaient vus, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, '« Béni soit le roi qui vient au nom du Seigneur! « Paix dans le ciel et gloire dans les lieux très-hauts! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Et quelques-uns des pharisiens de la foule lui dirent: « Maître, réprimande tes disciples! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Et il répliqua: « Je vous déclare que si ceux-ci viennent à se taire, les pierres crieront. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Et lorsqu\'il fut proche, voyant la ville il pleura sur elle, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, '« Que n\'as-tu, toi aussi, connu, en ce jour-ci, ce qui procure la paix! Mais maintenant cela a été caché à tes yeux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'car des jours viendront pour ta ruine, et tes ennemis élèveront un retranchement autour de toi, et ils te bloqueront, et ils te presseront de toutes parts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'et ils te détruiront ainsi que tes enfants au dedans de toi, et ils ne laisseront pas en toi pierre sur pierre, parce que tu n\'as pas connu le moment où tu as été visitée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Et étant entré dans le temple il commença par chasser les trafiquants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'en leur disant: « Il est écrit: Et Ma maison sera Une maison de prière, mais vous, vous en avez fait une caverne de brigands. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Et il enseignait chaque jour dans le temple; mais les grands prêtres et les scribes cherchaient à le perdre, ainsi que les principaux du peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'et ils ne savaient pas quel parti prendre, car tout le peuple s\'attachait à lui pour l\'entendre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Et il advint, l\'un des jours où il enseignait le peuple dans le temple et où il annonçait la bonne nouvelle, que les grands prêtres et les scribes survinrent avec les anciens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'et lui dirent: « Dis-nous en vertu de quelle autorité tu fais ces choses, ou bien quel est celui qui t\'a donné cette autorité? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Mais il leur répliqua: « Je vous adresserai de mon côté une question; dites-moi:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Le baptême de Jean venait-il du ciel ou des hommes? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Mais ils conférèrent entre eux en disant: « Si nous disons: Du ciel, il nous dira: Pourquoi n\'y avez-vous pas cru?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Mais si nous disons: Des hommes, tout le peuple nous lapidera, car il est convaincu que Jean était un prophète. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'Et ils répondirent ne pas savoir d\'où.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Et Jésus leur dit: « Moi non plus je ne vous dis pas en vertu de quelle autorité je fais ces choses. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Mais il se mit à adresser au peuple cette parabole: « Un homme planta une vigne, et il l\'afferma à des vignerons, et il s\'absenta pendant longtemps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'Et au temps voulu il dépêcha un esclave aux vignerons, afin qu\'ils lui donnassent une part de la récolte de la vigne; mais les vignerons, après l\'avoir battu, le renvoyèrent les mains vides.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Et il continua d\'envoyer un autre esclave, mais eux, après l\'avoir aussi battu et outragé, le renvoyèrent les mains vides.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Et il continua d\'en envoyer un troisième; mais eux, après l\'avoir aussi blessé, l\'expulsèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Or le propriétaire de la vigne dit: Que ferai-je? J\'enverrai mon fils bien-aimé, peut-être le respecteront-ils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Mais les vignerons l\'ayant vu délibéraient entre eux, en disant: « Celui-ci est l\'héritier, tuons-le, afin que l\'héritage nous appartienne. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Et l\'ayant jeté hors de la vigne, ils le tuèrent. Que leur fera donc le propriétaire de la vigne?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Il viendra, et fera périr ces vignerons, et il donnera la vigne à d\'autres. » Ce qu\'ayant ouï, ils dirent: « Qu\'il n\'en soit pas ainsi! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Mais lui, les ayant regardés, leur dit: « Que signifie donc ce passage de l\'écriture: La pierre que les constructeurs ont rejetée est celle qui est devenue le sommet de l\'angle? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Quiconque sera tombé sur cette pierre sera fracassé, tandis que celui sur lequel elle sera tombée, elle le fera voler en éclats.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Et les scribes et les grands prêtres cherchèrent à mettre les mains sur lui en ce moment même; et ils craignirent le peuple. Ils avaient compris en effet que c\'était contre eux qu\'il avait prononcé cette parabole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Et s\'étant mis à l\'épier, ils dépêchèrent des gens subornés qui feignaient d\'être justes, afin de surprendre une parole de lui, de manière à le livrer au magistrat et à l\'autorité du gouverneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Et ils l\'interrogèrent en disant: « Maître, nous savons que tu parles et que tu enseignes comme il convient, et que tu ne fais point acception de personnes, mais que tu enseignes avec vérité la voie de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Nous est-il permis ou non de payer le tribut à l\'empereur? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Mais ayant démêlé leur fourberie, il leur dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, '« Montrez-moi un denier: de qui porte-t-il l\'effigie et la légende? » Ils dirent: « De l\'empereur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Or il leur dit: « Eh bien, rendez à l\'empereur ce qui est à l\'empereur, et à Dieu ce qui est à Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Et ils ne purent rien reprendre à cette parole en présence du peuple, et émerveillés de sa réponse ils se turent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Or quelques-uns des sadducéens, qui disent qu\'il n\'y a pas de résurrection, s\'étant approchés, l\'interrogeaient en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, '« Maître, Moïse nous a prescrit que, si le frère de quelqu\'un vient à mourir en ayant une femme, et qu\'il soit sans enfant, son frère prenne la femme et suscite une postérité à son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Il y avait donc sept frères; et le premier ayant pris une femme est mort sans enfant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'et le second');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'et le troisième la prirent; mais de même aussi les sept n\'ont point laissé d\'enfants, et ils sont morts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'enfin la femme aussi mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Cette femme donc, lors de la résurrection, duquel d\'entre eux doit-elle devenir la femme? Car les sept l\'ont eue pour femme. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Et Jésus leur dit: « Les fils de ce siècle-ci prennent des femmes et les femmes des maris,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'mais ceux qui auront été jugés dignes d\'avoir part à ce siècle-là et à la résurrection d\'entre les morts ne prennent point de femmes ni les femmes de maris,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'en effet ils ne peuvent plus mourir, car ils sont égaux aux anges, et ils sont fils de Dieu en étant fils de la résurrection.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Mais, que les morts ressuscitent, c\'est ce que Moïse même a indiqué dans le passage du buisson, lorsqu\'il parle du Seigneur qui est le Dieu d\'Abraham, et le Dieu d\'Isaac, et le Dieu de Jacob.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Or Il n\'est pas le Dieu des morts, mais des vivants, car pour Lui tous sont vivants. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Or quelques-uns des scribes prenant la parole dirent: « Maître, tu as bien parlé! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Car ils n\'osaient plus lui adresser aucune question.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Mais il leur dit: « Comment dit-on que le Christ est fils de David,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'car David lui-même a dit dans le livre des Psaumes: Le Seigneur a dit à mon seigneur: Assieds-toi à Ma droite,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'jusques à ce que J\'aie mis tes ennemis comme un marchepied sous tes pieds?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'David l\'appelle donc seigneur; eh bien, comment est-il son fils? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Or, comme tout le peuple l\'écoutait, il dit aux disciples:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, '« Soyez en garde contre les scribes qui aiment à se promener en robes, et les salutations dans les places publiques, et les premiers sièges dans les synagogues, et les premières places dans les repas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'Ceux qui dévorent les maisons des veuves, et qui, par dissimulation, font de longues prières, ceux-là recevront une punition d\'autant plus sévère. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Et ayant levé les yeux, il vit les riches qui jetaient dans le trésor leurs offrandes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'mais il vit une certaine veuve indigente qui y jetait deux pites,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'et il dit: « En vérité je vous déclare que cette veuve pauvre a jeté plus que personne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'car tous ceux-là ont jeté de leur superflu dans les offrandes, tandis que cette femme a jeté, de son dénuement, tout ce qu\'elle avait pour sa subsistance. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Et quelques personnes disant à propos du temple, qu\'il était orné de belles pierres et d\'offrandes, il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, '« Ces choses que vous voyez..., des jours viendront où il ne sera laissé ici pierre sur pierre qui ne soit démolie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Mais ils l\'interrogèrent, en disant: « Maître, quand donc cela aura-t-il lieu? Et quel sera le signe qui indiquera que ces choses sont sur le point d\'arriver? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Or il dit: « Prenez garde de ne pas vous laisser égarer; car plusieurs viendront en mon nom, disant: « C\'est moi qui le suis, et le moment approche; » ne vous mettez pas à leur suite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Mais quand vous entendrez parler de guerres et de révolutions, ne vous en effrayez pas, car il faut que cela arrive premièrement, mais ce n\'est pas tout aussitôt la fin. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Alors il leur disait: « Une nation s\'élèvera contre une nation, et un royaume contre un royaume;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'et il y aura de grands tremblements de terre, et place par place des pestes et des famines; et il y aura des phénomènes effrayants et de grands signes qui viendront du ciel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'mais avant toutes ces choses ils mettront les mains sur vous, et ils vous persécuteront, vous livrant aux synagogues et vous jetant en prison, vous traînant devant des rois et des gouverneurs à cause de mon nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Cela sera pour vous l\'occasion d\'un témoignage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'mettez donc en vos cœurs de ne pas songer d\'avance à votre défense,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'car c\'est moi qui vous donnerai une bouche et une sagesse, à laquelle tous vos adversaires ne pourront résister ni répliquer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Mais vous serez livrés même par vos parents, et par vos frères, et par des membres de votre famille, et par des amis, et ils en mettront à mort d\'entre vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'et vous serez haïs de tous à cause de mon nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'et pas un cheveu de votre tête ne sera certainement perdu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'c\'est par votre patience que vous vous mettrez en possession de vos âmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, '« Mais quand vous aurez vu Jérusalem investie par les armées, alors sachez que sa dévastation est proche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Alors que ceux qui sont en Judée s\'enfuient dans les montagnes, et que ceux qui sont au milieu de la ville se retirent, et que ceux qui sont dans les campagnes n\'y rentrent pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'car ce sont là des jours de châtiment, afin que tout ce qui a été écrit s\'accomplisse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Malheur à celles qui sont enceintes et à celles qui allaitent en ces jours-là! Car il y aura une grande calamité sur la terre et de la colère contre ce peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'et ils tomberont par le fil de l\'épée, et ils seront emmenés captifs chez toutes les nations, et Jérusalem sera foulée aux pieds par les Gentils, tant que dureront les temps des Gentils et jusques à ce qu\'ils soient accomplis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, '« Et il y aura des signes dans le soleil, la lune et les astres, et sur la terre de l\'angoisse parmi les nations inquiètes du fracas de la mer et des flots,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'les hommes expirant de frayeur à l\'attente de ce qui menace la terre, car les puissances des cieux seront ébranlées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Et alors ils verront le fils de l\'homme venant dans une nuée avec beaucoup de puissance et de gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Mais quand ces choses commenceront à se réaliser, redressez-vous et levez la tête, car votre délivrance approche. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Et il leur dit une parabole: « Voyez le figuier et tous les arbres:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'quand ils ont commencé à pousser, vous savez d\'après eux en les regardant que déjà l\'été est proche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'De même, vous aussi, quand vous aurez vu ces choses se réaliser, sachez que le royaume de Dieu est proche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'En vérité je vous déclare que cette génération-ci ne disparaîtra certainement point, jusques à ce que tout se soit réalisé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Le ciel et la terre passeront, mais mes paroles ne passeront certainement point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Mais prenez garde à vous-mêmes, de peur que vos cœurs ne s\'appesantissent dans les excès, dans l\'ivresse, et dans les soucis de la vie, et que ce jour-là ne vous surprenne tout à coup');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'comme un filet; car il surprendra tous ceux qui habitent la surface de toute la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'mais veillez, priant en tout temps, afin que vous puissiez échapper à toutes ces choses qui doivent survenir, et vous trouver debout en présence du fils de l\'homme. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Or, pendant le jour, il enseignait dans le temple, mais tous les soirs il sortait pour passer la nuit sur la montagne appelée Bois d\'oliviers;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'et tout le peuple venait de bon matin vers lui dans le temple pour l\'entendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Or la fête des pains sans levain, dite la Pâque, approchait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'et les grands prêtres et les scribes cherchaient comment ils pourraient se défaire de lui, car ils craignaient le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Or Satan entra dans Judas, nommé Iscariote, qui était du nombre des douze,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'et il vint conférer avec les grands prêtres et les chefs des gardes sur la manière de le leur livrer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Et ils furent dans la joie, et ils convinrent de lui donner de l\'argent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'et il s\'engagea. Et il cherchait une bonne occasion pour le leur livrer à l\'insu de la foule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Cependant le jour des pains sans levain arriva, dans lequel il fallait immoler la pâque;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'et il dépêcha Pierre et Jean en disant: « Allez nous faire les préparatifs nécessaires pour que nous mangions la pâque. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Mais ils lui dirent: « Où veux-tu que nous fassions les préparatifs pour que tu manges la pâque? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Et il leur dit: « Voici, quand vous serez entrés dans la ville, vous rencontrerez un homme portant une cruche d\'eau; suivez-le dans la maison où il entrera,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'et dites au chef de famille: « Le maître te fait dire: Où est la chambre où je dois manger la pâque avec mes disciples? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Et cet homme vous montrera une grande salle à manger garnie de lits; faites-y les préparatifs. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Or s\'en étant allés ils trouvèrent tout comme il le leur avait dit, et ils préparèrent la pâque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Et lorsque l\'heure fut arrivée, il se mit à table et les apôtres avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Et il leur dit: « J\'ai ardemment désiré manger cette pâque avec vous avant ma passion;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'car je vous déclare que je ne la mangerai certainement plus, jusques à ce qu\'elle soit accomplie dans le royaume de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Puis, ayant pris une coupe, il dit, après avoir rendu grâces: « Prenez ceci, et distribuez-le entre vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'car je vous déclare que je ne boirai certainement plus désormais du produit de la vigne, jusques à ce que le royaume de Dieu soit venu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Puis ayant pris du pain, il le rompit, après avoir rendu grâces, et il le leur donna en disant: « Ceci est mon corps, qui est donné pour vous; faites ceci en mémoire de moi; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'puis de même la coupe après le repas, en disant: « Cette coupe est la nouvelle alliance en mon sang, qui est versé pour vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Néanmoins, voici, la main de celui qui me livre est avec moi sur la table;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'car le fils de l\'homme s\'en va, il est vrai, selon ce qui a été fixé, néanmoins malheur à cet homme par qui il est livré. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Et ils se mirent à rechercher entre eux quel était donc celui d\'entre eux qui devait faire cela.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Et il s\'éleva encore parmi eux une discussion pour savoir lequel d\'entre eux passait pour le plus grand;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'mais il leur dit: « Les rois des nations les dominent, et leurs potentats sont appelés bienfaiteurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'mais pour vous ne faites pas de même; au contraire, que le plus grand parmi vous devienne comme le plus jeune, et celui qui commande comme celui qui sert;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'car qui est le plus grand, celui qui est à table ou celui qui sert? N\'est-ce pas celui qui est à table? Mais moi je suis au milieu de vous comme celui qui sert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Quant à vous, vous êtes ceux qui sont toujours demeurés avec moi dans mes tentations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'et moi, de mon côté, je dispose en votre faveur du royaume, comme mon Père en a disposé en ma faveur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'afin que vous mangiez et que vous buviez à ma table dans mon royaume, et que vous soyez assis sur des trônes, pour juger les douze tribus d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Simon, Simon, voici, Satan vous a réclamés pour vous cribler comme le blé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'mais moi j\'ai prié pour toi, afin que ta foi ne défaille point, et toi, après être une fois revenu, affermis tes frères. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'Or il lui dit: « Seigneur, je suis prêt à aller avec toi et en prison et à la mort. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Mais il lui dit: « Pierre, je te le déclare, aujourd\'hui le coq ne chantera pas, jusqu\'à ce que, par trois fois, tu aies nié que tu me connais. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Et il leur dit: « Quand je vous ai envoyés sans bourse, ni besace, ni sandales, avez-vous manqué de quelque chose? » Et ils dirent: « De rien. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Mais il leur dit: « Maintenant, au contraire, que celui qui a une bourse la prenne, et de même aussi sa besace, et que celui qui n\'en a pas vende son manteau et s\'achète une épée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'car je vous le déclare, il faut que ce passage de l\'écriture s\'accomplisse en ma personne: « Et c\'est parmi des criminels qu\'il a été compté; en effet ce qui me concerne va prendre fin. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Mais ils dirent: « Seigneur, voici, il y a ici deux épées. » Or il leur dit: « Cela suffit. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Et étant sorti il s\'achemina, selon sa coutume, vers la montagne des Oliviers; or les disciples aussi le suivaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Mais lorsqu\'il fut arrivé en cet endroit, il leur dit: « Priez pour ne pas entrer en tentation. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Et lui-même s\'éloigna d\'eux à la distance d\'environ un jet de pierre, et s\'étant mis à genoux, il priait');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'en disant: « Père, si Tu le veux, fais passer cette coupe loin de moi! Toutefois que ce ne soit pas ma volonté, mais la tienne, qui se fasse. » [');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Or un ange venu du ciel lui apparut pour le fortifier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'et étant entré en agonie, il priait avec plus d\'instance; mais sa sueur devint comme des gouttes de sang, qui tombaient sur la terre.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Et s\'étant levé après sa prière, il vint vers ses disciples qu\'il trouva endormis de tristesse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'et il leur dit: « Pourquoi dormez-vous? Levez-vous et priez afin que vous n\'entriez pas en tentation. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Pendant qu\'il parlait encore, voici venir une foule, et le nommé Judas, un des douze, la précédait, et il s\'approcha de Jésus pour l\'embrasser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Mais Jésus lui dit: « Judas, c\'est par un baiser que tu livres le fils de l\'homme! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Et ceux qui étaient avec lui voyant ce qui allait arriver dirent: « Seigneur, si nous frappions de l\'épée? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Et l\'un d\'entre eux frappa l\'esclave du grand prêtre et lui enleva l\'oreille droite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Mais Jésus prenant la parole dit: « Attendez que ceci soit fait, » et lui ayant touché l\'oreille, il le guérit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Or Jésus dit aux grands prêtres et aux chefs des gardes du temple et aux anciens qui s\'étaient portés contre lui: « Vous êtes sortis, comme contre un brigand, avec des épées et des bâtons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Pendant que j\'étais chaque jour avec vous dans le temple, vous n\'avez pas mis les mains sur moi; mais c\'est ici votre heure, et le règne des ténèbres. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Or l\'ayant saisi, ils l\'emmenèrent, et ils le conduisirent dans la maison du grand, prêtre. Mais Pierre le suivait de loin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Or après qu\'ils eurent allumé un feu au milieu de la cour et qu\'ils se furent assis ensemble, Pierre se trouvait assis au milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Mais une servante l\'ayant vu assis à la lueur du feu et l\'ayant regardé fixement, dit: « Celui-ci aussi était avec lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Mais lui le nia en disant: « Je ne le connais point, femme! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Et peu après un autre l\'ayant vu, dit: « Toi aussi, tu en es. » Mais Pierre dit: « O homme, je n\'en suis point! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Et au bout d\'environ une heure un autre insistait en disant: « Certainement celui-ci aussi était avec lui; car il est aussi Galiléen. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Mais Pierre dit: « O homme, j\'ignore ce dont tu parles. » Et tout à coup, comme il parlait encore, un coq chanta,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'et le seigneur s\'étant retourné regarda Pierre, et Pierre se souvint de la parole du seigneur, qui lui avait dit: « Avant que le coq ait chanté aujourd\'hui tu m\'auras renié trois fois. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Et étant sorti il pleura amèrement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Et les hommes qui le tenaient le bafouaient après l\'avoir frappé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'et l\'ayant couvert d\'un voile, ils l\'interrogeaient en disant: « Prophétise! Quel est celui qui t\'a frappé? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Et ils disaient contre lui beaucoup d\'autres injures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Et lorsque le jour fut venu, le corps des anciens du peuple se réunit ainsi que les grands prêtres et les scribes, et ils l\'amenèrent devant leur propre tribunal, en disant: « Si tu es le Christ, dis-le nous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Mais il leur dit: « Si je vous le disais, vous ne le croiriez certainement pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'si, d\'un autre côté, je vous interrogeais, vous ne répondriez certainement pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Mais désormais le fils de l\'homme sera assis à la droite de la puissance de Dieu. «');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Or ils dirent tous: « Tu es donc le fils de Dieu? » Or il leur dit: « C\'est vous-mêmes qui dites que je le suis. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Mais ils dirent: « Qu\'avons-nous encore besoin de témoignage, puisque c\'est nous-mêmes qui l\'avons entendu de sa bouche? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Et s\'étant soulevés en foule ils le conduisirent devant Pilate.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'Or ils se mirent à l\'accuser en disant: « Nous avons trouvé celui-ci occupé à soulever notre nation, et empêchant de payer des impôts à l\'empereur, et disant qu\'il est lui-même Christ roi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Or Pilate l\'interrogea en disant: « Tu es le roi de Juifs? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Et il lui répliqua: « C\'est toi qui le dis. » Or Pilate dit aux grands prêtres et à la foule: « Je ne trouve rien de coupable chez cet homme. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Mais ils insistaient, en disant: « Il agite le peuple, en enseignant dans toute la Judée, ayant même commencé par la Galilée jusques ici. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'A ces mots Pilate demanda: « L\'homme est-il Galiléen? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Et ayant appris qu\'il était de la juridiction d\'Hérode, il le renvoya devant Hérode, qui se trouvait aussi à Jérusalem en ces jours-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Or Hérode en voyant Jésus fut dans une grande joie, car dès longtemps il désirait le voir, à cause de ce qu\'il avait ouï dire sur son compte, et il espérait voir quelque miracle opéré par lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Or il lui faisait subir un long interrogatoire, mais il ne répondait rien,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'tandis que les grands prêtres et les scribes étaient là qui l\'accusaient sans relâche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Or, après qu\'Hérode l\'eut insulté et bafoué avec ses soldats, il le revêtit d\'un brillant costume et le renvoya à Pilate.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Or Hérode et Pilate devinrent ce jour même mutuellement amis, car auparavant il existait entre eux une inimitié réciproque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Cependant Pilate, ayant convoqué les grands prêtres et les chefs, et le peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'leur dit: « Vous m\'avez amené cet homme comme soulevant le peuple, et voici, après l\'avoir examiné en votre présence, je ne l\'ai, pour mon compte, trouvé coupable d\'aucune des choses dont vous l\'accusez;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'mais Hérode non plus, car il nous l\'a renvoyé; et voici, il n\'a rien fait qui soit digne de mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Après l\'avoir donc fait châtier je le relâcherai. » [');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Il était obligé de leur relâcher lors d\'une fête un prisonnier.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Mais ils s\'écriaient en foule: « Fais périr celui-ci, mais relâche-nous Barabbas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Cet homme avait été mis en prison à cause d\'une sédition survenue dans la ville et d\'un meurtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Mais Pilate s\'adressa derechef à eux, parce qu\'il désirait relâcher Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'mais ils répondaient par des cris en disant: « Crucifie, crucifie-le. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Or il leur dit pour la troisième fois: « Eh! quel mal a fait cet homme? Je n\'ai rien trouvé en lui qui mérite la mort; après l\'avoir donc fait châtier je le relâcherai. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Mais ils insistaient en demandant à grands cris qu\'il le crucifiât, et leurs cris prenaient le dessus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'et Pilate prononça que leur requête était accordée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'et il leur relâcha celui qui avait été mis en prison pour sédition et pour meurtre, lequel ils réclamaient, tandis qu\'il leur livra Jésus pour en faire ce qu\'ils voulaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Et comme ils l\'emmenaient, ils se saisirent d\'un certain Simon de Cyrène qui venait des champs, et ils le chargèrent de la croix pour la porter derrière Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Or une nombreuse multitude de peuple le suivait, ainsi que beaucoup de femmes qui s\'affligeaient et se lamentaient sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Mais s\'étant retourné vers elles, Jésus dit: « Filles, de Jérusalem, ne pleurez pas sur moi; mais pleurez sur vous et sur vos enfants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'car voici, des jours viennent où l\'on dira: Heureuses les stériles, et les ventres qui n\'ont point enfanté, et les mamelles qui n\'ont point nourri!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Alors on commencera à dire aux montagnes: Tombez sur nous! et aux coteaux: Cachez-nous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Car si on fait ces choses à du bois vert, qu\'adviendra-t-il à celui qui est sec? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Or on emmenait aussi deux autres malfaiteurs pour être mis à mort avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Et lorsqu\'ils furent arrivés à l\'endroit appelé Crâne, ils le crucifièrent là avec les malfaiteurs, l\'un à droite et l\'autre à gauche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Or se partageant ses vêtements, ils tirèrent au sort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Et le peuple se tenait là à regarder; mais les chefs aussi se moquaient en disant: « Il en a sauvé d\'autres, qu\'il se sauve lui-même, s\'il est le Fils, le Christ élu de Dieu! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Les soldats s\'avançant le bafouèrent aussi, en lui offrant du vinaigre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'et en disant: « Si tu es le roi des Juifs, sauve-toi toi-même. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Et il y avait encore au-dessus de lui pour inscription: Celui-ci est le roi des Juifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Or l\'un des malfaiteurs pendus l\'injuriait, en disant: « N\'est-ce pas toi qui es le Christ? Sauve-toi toi-même et nous aussi! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Mais l\'autre prenant la parole le réprimandait en disant: « Ne crains-tu point Dieu, car tu subis la même condamnation?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Et quant à nous, ce n\'est que justice, car nous recevons ce que méritent les choses que nous avons faites, tandis que celui-ci n\'a rien fait de criminel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Et il disait à Jésus: « Souviens-toi de moi quand tu seras entré dans ton royaume. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Et il lui dit: « En vérité je te le déclare, aujourd\'hui tu seras avec moi dans le paradis. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Et il était déjà environ la sixième heure, et des ténèbres survinrent sur toute la terre jusques à la neuvième heure,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'car le soleil s\'éclipsait; et le rideau du sanctuaire se déchira par le milieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Et Jésus parlant à haute voix, dit: « Père, c\'est en Tes mains que je remets mon esprit! » Or en disant cela, il expira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Mais le centurion, voyant ce qui était advenu, glorifiait Dieu en disant: « Cet homme-ci était réellement juste. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Et toute la foule qui était venue là pour ce spectacle, ayant vu ce qui s\'était passé, s\'en retournait en se frappant la poitrine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Mais tous ceux de sa connaissance se tenaient dans l\'éloignement, ainsi que les femmes qui l\'accompagnaient depuis la Galilée, et elles contemplaient ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Et voici, un homme nommé Joseph, qui était sénateur, homme bon et juste,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'lequel n\'avait point connivé à leur décision et à leur conduite, originaire d\'Arimathée, ville des Juifs, qui attendait le royaume de Dieu...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'cet homme s\'étant rendu auprès de Pilate réclama le corps de Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'et l\'ayant descendu il l\'enveloppa d\'un linceul et le déposa dans un sépulcre taillé dans le roc, où personne n\'avait encore été mis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Et c\'était le jour de la préparation, et le sabbat allait commencer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Or les femmes qui étaient venues avec lui de Galilée s\'approchèrent pour regarder le sépulcre et la manière dont son corps y avait été déposé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'et s\'en étant retournées elles préparèrent des aromates et des parfums. Et pendant le sabbat elles demeurèrent en repos, selon la loi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'mais le premier jour de la semaine, dès l\'aube, elles vinrent au sépulcre portant les aromates qu\'elles avaient préparés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Mais elles trouvèrent la pierre déplacée de devant le sépulcre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'et étant entrées elles ne trouvèrent pas le corps du seigneur Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Et il advint, pendant qu\'elles ne savaient qu\'en penser, que voici, deux hommes se présentèrent à elles, vêtus d\'un habit étincelant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'et, comme elles étaient saisies de crainte et abaissaient leurs visages vers la terre, ils leur dirent: « Pourquoi cherchez-vous parmi les morts celui qui est vivant?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Il n\'est pas ici, mais il est ressuscité; souvenez-vous de la manière dont il vous a parlé lorsqu\'il était encore en Galilée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'disant du fils de l\'homme: il faut qu\'il soit livré aux mains des hommes pécheurs, et qu\'il soit crucifié, et qu\'il ressuscite le troisième jour. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Et elles se souvinrent de ses paroles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'et s\'étant éloignées du sépulcre elles rapportèrent toutes ces choses aux onze et aux autres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'or c\'étaient la Magdalène Marie, et Jeanne, et Marie mère de Jacques; et les autres qui étaient avec elles disaient les mêmes choses aux apôtres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'et ces paroles leur parurent du radotage, et ils ne les en croyaient pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Mais Pierre s\'étant levé courut au sépulcre, et s\'étant courbé il vit les linges seuls; et il s\'en retourna, émerveillé en lui-même de ce qui était advenu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Et voici, deux d\'entre eux se rendaient le même jour dans un village éloigné de soixante stades de Jérusalem, et nommé Emmaous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'et ils causaient ensemble de tous ces événements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Et il advint, pendant qu\'ils causaient et discutaient, que Jésus s\'étant approché cheminait avec eux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'mais leurs yeux étaient offusqués de manière à ne le pas reconnaître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Mais il leur dit: « Quels sont ces discours que vous échangez entre vous, tout en marchant? » Et ils demeurèrent tout chagrins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Mais l\'un d\'eux, nommé Cléopas, lui répliqua: « Séjournes-tu seul à Jérusalem, que tu n\'aies pas eu connaissance des choses qui s\'y sont passées ces jours-ci? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Et il leur dit: « Lesquelles? » Or ils lui dirent: « Celles qui concernent Jésus le Nazarénien, qui fut un prophète puissant en œuvres et en paroles devant Dieu et devant tout le peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'et comme quoi nos grands prêtres et nos chefs l\'ont livré pour être condamné à mort, et l\'ont crucifié,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'tandis que nous, nous espérions qu\'il était celui qui doit racheter Israël. Mais avec tout cela, voici le troisième jour depuis que ces choses ont eu lieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'et de plus quelques femmes d\'entre nous nous ont mis hors de nous-mêmes, car, s\'étant rendues de grand matin au sépulcre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'et n\'ayant pas trouvé le corps, elles sont venues nous dire en outre qu\'elles avaient vu une apparition d\'anges qui disent qu\'il est vivant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'et quelques-uns de nos compagnons sont allés au sépulcre, et ont trouvé les choses telles que les femmes les avaient dites, mais quant à lui ils ne l\'ont point vu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Et lui-même leur dit: « O hommes sans intelligence, et dont le cœur est lent à croire tout ce dont ont parlé les prophètes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Ne fallait-il pas que le Christ soutînt ces choses, et qu\'il entrât dans sa gloire? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Et ayant commencé depuis Moïse et depuis tous les prophètes, il leur interpréta dans toutes les écritures ce qui le concernait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Et ils approchèrent du village où ils se rendaient, et lui-même feignit de se rendre plus loin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'et ils le retinrent de force, en disant: « Reste avec nous; car voici le soir, et le jour a déjà baissé. » Et il entra pour rester avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Et il advint, au moment où il se mit à table avec eux, qu\'ayant pris le pain il prononça une bénédiction, et après l\'avoir rompu il le leur distribuait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Mais leurs yeux s\'ouvrirent et ils le reconnurent, et lui-même devint invisible pour eux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'et ils se dirent l\'un à l\'autre: « Est-ce que notre cœur ne brûlait pas quand il nous parlait en chemin, quand il nous expliquait les écritures? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Et s\'étant levés sur l\'heure même, ils retournèrent à Jérusalem, et trouvèrent réunis les onze et leurs compagnons,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'qui disaient: « Le Seigneur est réellement ressuscité, et il s\'est fait voir à Simon. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Et eux-mêmes racontaient ce qui leur était arrivé en chemin, et comment il avait été reconnu par eux à la fraction du pain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Or, pendant qu\'ils parlaient ainsi, lui-même se présenta au milieu d\'eux, et leur dit: « Paix pour vous! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Mais saisis d\'épouvante et de crainte ils s\'imaginaient voir un esprit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'et il leur dit: « Pourquoi êtes-vous troublés, et pourquoi des pensées montent-elles dans votre cœur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Voyez mes mains et mes pieds, car c\'est bien moi-même; touchez-moi et voyez; car un esprit n\'a ni chair ni os comme vous voyez que je les ai. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Et en disant cela il leur montra ses mains et ses pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Mais, comme dans leur joie ils doutaient encore et étaient émerveillés, il leur dit: « Avez–vous ici quelque chose à manger? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Or ils lui servirent une portion de poisson rôti;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'et l\'ayant prise, il mangea devant eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Mais il leur dit: « Ce sont ici les paroles que je vous ai adressées pendant que j\'étais encore avec vous, vous disant qu\'il fallait que fussent accomplies toutes les choses écrites à mon sujet dans la loi de Moïse, et dans les prophètes, et dans les psaumes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Alors il leur ouvrit l\'esprit pour comprendre les écritures,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'et il leur dit: « C\'est ainsi qu\'il a été écrit que le Christ souffrirait, et qu\'il ressusciterait des morts le troisième jour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'et que la repentance en vue de la rémission des péchés serait prêchée en son nom à toutes les nations, en commençant par Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'C\'est vous qui êtes témoins de ces choses,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'et voici, moi, j\'envoie sur vous la promesse de mon Père, mais, pour vous, demeurez dans la ville jusques à ce que vous ayez été revêtus d\'une puissance venue d\'en haut. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Et il les conduisit hors de la ville jusques à Béthanie, et ayant élevé ses mains il les bénit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Et il advint, pendant qu\'il les bénissait, qu\'il se sépara d\'eux; et il était enlevé au ciel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'et eux, après l\'avoir adoré, retournèrent à Jérusalem avec joie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'et\'ils étaient constamment dans le temple occupés à bénir Dieu. Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Au commencement était la Parole, et la Parole était auprès de Dieu, et la Parole était Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'c\'est elle qui était au commencement auprès de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Toutes choses ont été faites par elle, et sans elle pas même une seule des choses qui ont été faites n\'a été faite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'En elle était la vie, et la vie était la lumière des hommes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'et la lumière luit dans les ténèbres, et les ténèbres ne l\'ont pas reçue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Il y eut un homme, envoyé de Dieu, dont le nom était Jean;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'cet homme vint pour servir de témoin, afin de rendre témoignage à la lumière, afin que tous crussent par son moyen.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Ce n\'est pas lui qui était la lumière, mais il devait rendre témoignage à la lumière;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'la lumière véritable qui illumine tous les hommes était venue dans le monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'La Parole était dans le monde, et le monde a été fait par elle, et le monde ne l\'a point connue;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'elle est venue chez elle, et les siens ne l\'ont pas accueillie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'mais à tous ceux qui l\'ont reçue, elle a donné, parce qu\'ils croient en son nom, le droit de devenir enfants de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'eux qui ne sont nés ni du sang, ni de la volonté de la chair, ni de la volonté de l\'homme, mais de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Et la Parole a été faite chair, et elle a habité parmi nous, pleine de grâce et de vérité; et nous avons contemplé sa gloire, une gloire telle que doit être celle du Fils unique qui est né du Père; —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Jean lui rend témoignage, et il s\'écrie: « C\'était de lui que j\'ai dit: Celui qui vient après moi a été avant moi, car il existait plus tôt que moi; » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'c\'est en effet de sa plénitude que tous nous avons reçu grâce après grâce;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'car la loi a été donnée par Moïse, la grâce et la vérité sont venues par Jésus-Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Personne n\'a jamais vu Dieu; le Dieu Fils unique, qui est dans le sein du Père, est celui qui L\'a révélé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Et voici quel fut le témoignage de Jean, lorsque les Juifs lui envoyèrent de Jérusalem des prêtres et des lévites, afin de lui demander: « Toi, qui es-tu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'et qu\'il déclara, (et il ne nia point) et qu\'il déclara: « Pour moi, je ne suis point le Christ. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Et ils lui demandèrent: « Toi donc, qu\'es-tu? Es-tu Élie? » Et il dit: « Je ne le suis point. — Es-tu le prophète? » — Et il répliqua: « Non. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Ils lui dirent donc: « Qui es-tu? afin que nous donnions une réponse à ceux qui nous ont envoyés. Que dis-tu sur toi-même? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Il dit: « Je suis la voix de quelqu\'un qui crie dans le désert: Redressez le chemin du Seigneur, comme a dit Ésaïe le prophète. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Et on avait envoyé des gens pris parmi les pharisiens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'et ils l\'interrogèrent et lui dirent: « Pourquoi donc baptises-tu, si tu n\'es pas le Christ, ni Élie, ni le prophète? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Il leur répliqua: « Pour moi, je baptise avec de l\'eau; au milieu de vous se trouve quelqu\'un que vous ne connaissez pas, qui vient après moi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'de la sandale duquel je ne suis pas digne de délier la courroie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Ces choses se passèrent à Béthanie au delà du Jourdain, là où Jean baptisait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Le lendemain il voit Jésus venant à lui, et il dit: « Voilà l\'agneau de Dieu qui enlève le péché du monde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'c\'est à propos de lui que j\'ai dit: Après moi vient un homme qui a été avant moi, car il existait plus tôt que moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'et pour moi je ne le connaissais point, mais c\'est afin qu\'il fût manifesté à Israël que je suis venu, baptisant avec de l\'eau. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Et Jean rendit témoignage en disant: « J\'ai vu l\'Esprit descendant du ciel comme une colombe, et il est demeuré sur lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'et pour moi je ne le connaissais point, mais Celui qui m\'a envoyé pour baptiser avec de l\'eau, Celui-là même m\'a dit: Celui sur lequel tu auras vu l\'Esprit descendre et demeurer, c\'est celui qui baptise avec l\'esprit saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Et moi j\'ai vu; et j\'ai rendu ce témoignage: Celui-ci est le fils de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Le lendemain Jean se trouvait là derechef, ainsi que deux de ses disciples,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'et ayant fixé ses regards sur Jésus qui passait, il dit: « Voilà l\'agneau de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Et les deux disciples l\'entendirent pendant qu\'il parlait, et ils suivirent Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'or Jésus s\'étant retourné et les ayant vus qui le suivaient, il leur dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, '« Que cherchez-vous? » Mais ils lui dirent: « Rabbi (ce qui étant traduit veut dire Maître), où demeures-tu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Il leur dit: « Venez, et vous verrez. » Ils allèrent donc et ils virent où il demeurait, et ils demeurèrent ce jour-là auprès de lui; c\'était environ la dixième heure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'André, le frère de Simon Pierre, était l\'un des deux disciples qui avaient entendu les paroles de Jean et qui l\'avaient suivi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'c\'est lui qui trouve d\'abord son propre frère Simon et qui lui dit: « Nous avons trouvé le Messie » (ce qui étant traduit signifie Christ). Il le conduisit auprès de Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, '« Jésus ayant fixé sur lui ses regards dit: « Tu es Simon fils de Jean, tu seras appelé Céphas » (ce qui se traduit par Pierre).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, '« Le lendemain il voulut se rendre en Galilée, et il trouve Philippe, et Jésus lui dit: « Suis-moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Or Philippe était de Bethsaïda, de la ville d\'André et de Pierre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Philippe trouve Nathanaël et lui dit: « Celui dont Moïse a écrit dans la loi, ainsi que les prophètes, nous l\'avons trouvé, c\'est Jésus fils de Joseph, qui est de Nazareth. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, '« Nathanaël lui dit: « Est-ce que de Nazareth il peut venir quelque chose de bon? » Philippe lui dit: « Viens et vois, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Jésus vit Nathanaël venant à lui, et il dit de lui: « Voilà vraiment un Israélite dans lequel il n\'y a pas de fraude. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Nathanaël lui dit: « D\'où me connais-tu? » Jésus lui répliqua: « Avant que Philippe t\'appelât, pendant que tu étais sous le figuier je t\'ai vu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Nathanaël répliqua: « Rabbi, tu es le fils de Dieu, tu es le roi d\'Israël. » Jésus lui répliqua: « Est-ce parce que je t\'ai dit que je t\'avais vu sous le figuier, que tu crois? Tu verras de plus grandes choses que celles-ci. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Et il lui dit: « En vérité, en vérité, je vous le dis: vous verrez le ciel ouvert et les anges de Dieu monter et redescendre sur le fils de l\'homme. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Et le troisième jour il y eut une noce à Cana de Galilée et la mère de Jésus s\'y trouvait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Or Jésus avait aussi été invité à la noce ainsi que ses disciples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Et le vin ayant manqué, la mère de Jésus lui dit: « Ils n\'ont plus de vin; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'et Jésus lui dit: « Qu\'y a-t-il de commun entre moi et toi, femme? Mon heure n\'est pas encore venue. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Sa mère dit aux serviteurs: « Quoique ce soit qu\'il vous dise, faites-le. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Or il y avait là six vases de pierre destinés aux ablutions en usage chez les Juifs, contenant chacun deux ou trois métrètes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Jésus leur dit: « Remplissez ces vases d\'eau. » Et ils les remplirent jusques en haut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Et il leur dit: « Puisez maintenant, et portez au chef de la salle à manger. » Et ils portèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Mais quand le chef de la salle à manger eut goûté l\'eau devenue du vin, (et il ne savait d\'où il venait, mais les serviteurs le savaient, eux qui avaient puisé l\'eau), le chef de la salle à manger appelle l\'époux et lui dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, '« Tout le monde sert d\'abord le bon vin, et quand on est ivre, le moins bon; toi, tu as gardé le bon vin jusques à présent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Jésus fit ainsi son premier miracle à Cana de Galilée, et il manifesta sa gloire, et ses disciples crurent en lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'après cela il descendit à Capharnaoum, lui, et sa mère, et ses frères, et ses disciples, et ils y demeurèrent un petit nombre de jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Et la Pâque des Juifs était proche; et Jésus monta à Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'et il trouva dans le temple ceux qui vendaient des bœufs et des brebis et des colombes, ainsi que des changeurs sur leurs sièges;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'et ayant fait un petit fouet avec des cordes, il les expulsa tous du temple ainsi que les brebis et les bœufs, et il dispersa la monnaie des changeurs et renversa leurs tables,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'et il dit à ceux qui vendaient les colombes: « Emportez cela d\'ici, ne faites pas de la maison de mon Père une maison de trafic! » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Ses disciples se souvinrent qu\'il est écrit: « Le zèle pour Ta maison me dévore. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Les Juifs donc prirent la parole et lui dirent:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, '« Quel signe nous montres-tu pour agir de la sorte? » Jésus leur répliqua: « Détruisez ce sanctuaire, et en trois jours je le relèverai. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Les Juifs dirent donc: « Il a fallu quarante-six ans pour que ce sanctuaire fût construit et toi, tu le relèveras en trois jours! » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Mais lui parlait du sanctuaire de son corps;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'lors donc qu\'il fut ressuscité des morts, ses disciples se souvinrent qu\'il avait dit cela, et ils crurent à l\'Écriture et à la parole qu\'avait dite Jésus. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Or, pendant qu\'il était à Jérusalem, durant la fête de Pâque, plusieurs crurent en son nom, en voyant les miracles qu\'il opérait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'mais, quant à Jésus, il ne se fiait pas à eux, parce qu\'il connaissait tout le monde,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'et qu\'il n\'avait pas besoin que personne rendît témoignage sur tel ou tel homme; car lui-même savait ce qui était dans l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Or il y avait un homme d\'entre les pharisiens, dont le nom était Nicodème, et qui était un chef des Juifs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'il vint vers lui de nuit et lui dit: « Rabbi, nous savons que tu es venu de Dieu comme docteur, car personne ne peut opérer les miracles que tu opères, si Dieu n\'est avec lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jésus lui répliqua: « En vérité, en vérité je te le déclare: si quelqu\'un n\'est né d\'en haut, il ne peut voir le royaume de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nicodème lui dit: « Comment un homme peut-il naître, quand il est vieux? Est-ce qu\'il peut entrer une seconde fois dans le sein de sa mère et naître? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jésus répliqua: « En vérité, en vérité je te le déclare: si quelqu\'un n\'est né d\'eau et d\'esprit, il ne peut entrer dans le royaume de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'ce qui est né de la chair est chair, et ce qui est né de l\'Esprit est esprit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'ne t\'étonne pas de ce que je t\'ai dit: il vous faut naître d\'en haut;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'le vent souffle où il veut, et tu en entends le son, mais tu ne sais d\'où il vient et où il va; il en est de même pour quiconque est né de l\'Esprit. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nicodème lui répliqua: « Comment ces choses se peuvent-elles faire? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jésus lui répliqua: « Tu es le docteur d\'Israël, et tu ne connais pas ces choses!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'En vérité, en vérité je te déclare que ce que nous savons, nous le disons, et que ce que nous avons vu, nous en rendons témoignage, et vous ne recevez pas notre témoignage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'si je vous ai parlé des choses terrestres, et que vous ne croyez pas, comment croirez-vous, si je vous parle des choses célestes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Et personne n\'est monté au ciel, si ce n\'est celui qui est descendu du ciel, le fils de l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Et de même que Moïse a élevé le serpent dans le désert, ainsi faut-il que le fils de l\'homme soit élevé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'afin que quiconque croit en lui ait la vie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'En effet Dieu a tant aimé le monde qu\'il a donné Son Fils unique, afin que quiconque croit en lui ne périsse point, mais ait la vie éternelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'car Dieu n\'a pas envoyé Son Fils dans le monde afin qu\'il jugeât le monde, mais afin que le monde fût sauvé par lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Celui qui croit en lui n\'est point jugé; celui qui ne croit pas a déjà été jugé parce qu\'il n\'a pas cru au nom du Fils unique de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Or voici en quoi consiste ce jugement, c\'est que la lumière est venue dans le monde, et que les hommes ont aimé les ténèbres plus que la lumière, parce que leurs œuvres étaient mauvaises;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'car quiconque fait le mal hait la lumière et ne vient pas vers la lumière, afin que ses œuvres ne soient pas dévoilées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'mais celui qui pratique la vérité vient vers la lumière, afin que ses œuvres soient manifestées parce qu\'elles sont faites en Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Après cela Jésus vient, ainsi que ses disciples, dans le pays de Judée et il y séjournait avec eux, et il baptisait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Or Jean baptisait aussi à Énon près de Salim, parce qu\'il y avait là beaucoup d\'eau; et on venait, et on se faisait baptiser;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'car Jean n\'avait pas encore été jeté en prison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Il y eut donc de la part des disciples de Jean une dispute avec un Juif au sujet de l\'ablution.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Et ils vinrent vers Jean et lui dirent: « Rabbi, celui qui était avec toi au delà du Jourdain, auquel tu as rendu témoignage, c\'est lui qui baptise, et tous viennent vers lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Jean répliqua: « Un homme ne peut pas s\'attribuer la moindre chose, si cela ne lui a été donné du ciel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'vous-mêmes vous m\'êtes témoins que j\'ai dit: Ce n\'est pas moi qui suis le Christ, mais j\'ai été envoyé devant lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Celui qui possède l\'épouse est l\'époux; mais l\'ami de l\'époux, qui est présent et qui l\'entend, est plein de joie à cause de la voix de l\'époux; cette joie donc, qui est la mienne, a été accomplie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'il faut qu\'il croisse, mais que moi je diminue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Celui qui vient d\'en haut est au-dessus de tous; celui qui est de la terre est de la terre et parle de la terre; celui qui vient du ciel, est au-dessus de tous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'ce qu\'il a vu et entendu, c\'est ce dont il rend témoignage, et personne ne reçoit son témoignage!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Celui qui a reçu son témoignage a scellé que Dieu est vrai;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'en effet celui que Dieu a envoyé profère les paroles de Dieu, car ce n\'est pas avec mesure qu\'il donne l\'Esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Le Père aime le Fils, et Il a tout mis dans sa main;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'celui qui croit au Fils a la vie éternelle, mais celui qui désobéit au Fils ne verra point la vie, mais la colère de Dieu demeure sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Lors donc que le Seigneur sut que les pharisiens avaient appris que Jésus faisait et baptisait plus de disciples que Jean,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(toutefois ce n\'était pas Jésus lui-même qui baptisait, mais ses disciples),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'il quitta la Judée, et se rendit en Galilée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Or il fallait qu\'il traversât la Samarie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Il arriva donc dans une ville de Samarie nommée Sichar, près du champ que Jacob avait donné à Joseph son fils;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'or là se trouvait la source de Jacob. Jésus donc fatigué du voyage s\'était tout simplement assis près de la source; c\'était environ la sixième heure;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'survient une femme samaritaine pour puiser de l\'eau; Jésus lui dit: « Donne-moi à boire. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Car ses disciples étaient allés à la ville afin d\'acheter des vivres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'La femme samaritaine lui dit donc: « Comment toi, qui es Juif, me demandes-tu à boire, à moi qui suis une femme samaritaine? » — Les Juifs en effet ne frayent pas avec les Samaritains. Jésus lui répliqua:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, '« Si tu connaissais le don de Dieu, et quel est celui qui te dit: Donne-moi à boire, c\'est toi qui l\'aurais sollicité, et il t\'aurait donné de l\'eau vive. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Elle lui dit: « Seigneur, tu n\'as rien pour puiser, et le puits est profond; d\'où as-tu donc cette eau vive?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Es-tu plus grand que notre père Jacob qui nous a donné ce puits, et qui lui-même en a bu, ainsi que ses fils et ses troupeaux? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jésus lui répliqua: « Quiconque boit de cette eau-là aura de nouveau soif;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'tandis que celui qui aura bu de l\'eau que je lui donnerai n\'aura certainement plus jamais soif, mais l\'eau que je lui donnerai deviendra en lui une source d\'eau jaillissante jusque dans la vie éternelle. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'La femme lui dit: « Seigneur, donne-moi cette eau-là, afin que je n\'aie plus soif, et que je ne vienne plus puiser ici. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Il lui dit: « Va, appelle ton mari, et reviens ici. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'La femme lui répliqua: « Je n\'ai pas de mari. » Jésus lui dit: « Tu as eu raison de dire: je n\'ai pas de mari;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'car tu as eu cinq maris, et celui que tu as maintenant n\'est pas ton mari; en cela tu as dit vrai. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'La femme lui dit: « Seigneur, je vois que tu es un prophète;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'nos pères ont adoré sur cette montagne, et vous, vous dites que c\'est à Jérusalem qu\'est le lieu où il faut adorer. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jésus lui dit: « Crois-moi, femme, l\'heure vient où vous n\'adorerez le Père, ni sur cette montagne, ni à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Pour vous, vous adorez ce que vous ne connaissez pas; nous, nous adorons ce que nous connaissons, car le salut vient des Juifs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'mais l\'heure vient, et elle est maintenant arrivée, où les véritables adorateurs adoreront le Père en esprit et en vérité; ce sont en effet de tels adorateurs que demande aussi le Père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Dieu est Esprit, et il faut que ses adorateurs L\'adorent en esprit et en vérité. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'La femme lui dit: « Je sais que le Messie doit venir, celui qui est appelé Christ; lorsque celui-là sera venu, il nous apprendra toutes choses. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, '« Jésus lui dit: « C\'est moi qui le suis, moi qui te parle. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Et là-dessus survinrent ses disciples, et ils s\'étonnaient de ce qu\'il parlait avec une femme. Nul cependant ne dit: « Que demandes-tu? » ou, « Pourquoi parles-tu avec elle? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'La femme laissa donc sa cruche et s\'en fut à la ville, et elle dit aux gens:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, '« Venez voir un homme qui m\'a dit tout ce que j\'ai fait; n\'est-ce point lui qui est le Christ? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Ils sortirent de la ville, et ils venaient vers lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Dans l\'intervalle les disciples le sollicitaient en disant: « Rabbi, mange. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Mais il leur dit: « J\'ai à manger un aliment que vous ne connaissez pas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Les disciples se disaient donc les uns aux autres: « Est-ce que quelqu\'un lui a apporté à manger? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jésus leur dit: « Ma nourriture est de faire la volonté de Celui qui m\'a envoyé et d\'achever Son œuvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Ne dites-vous pas vous-mêmes: Encore quatre mois et la moisson arrive? Voici, je vous dis: Levez vos yeux, et voyez comme les campagnes blanchissent déjà pour la moisson.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Le moissonneur reçoit un salaire, et il serre sa récolte pour la vie éternelle, afin que le semeur se réjouisse aussi bien que le moissonneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'car c\'est ici que s\'applique avec vérité la parole qui dit: « Autre est le semeur, et autre le moissonneur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'C\'est moi qui vous ai envoyés moissonner ce que vous n\'avez pas travaillé; d\'autres ont travaillé, et vous, vous êtes entrés dans leur travail. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Or de cette ville-là il y eut plusieurs Samaritains qui crurent en lui, à cause de cette déclaration de la femme: « Il m\'a dit tout ce que j\'ai fait. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Lors donc que les Samaritains furent venus vers lui, ils le sollicitaient de demeurer auprès d\'eux; et il demeura là deux jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Et un beaucoup plus grand nombre crurent à cause de sa prédication,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'et ils disaient à la femme: « Ce n\'est plus à cause de tes discours, que nous croyons, car nous avons ouï nous-mêmes, et nous savons que celui-ci est vraiment le sauveur du monde, le Christ. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Au bout de ces deux jours il sortit de là pour se rendre en Galilée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'En effet Jésus lui-même avait déclaré qu\'un prophète n\'est point honoré dans sa propre patrie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'lors donc qu\'il arriva en Galilée, les Galiléens l\'accueillirent parce qu\'ils avaient vu tout ce qu\'il avait fait à Jérusalem pendant la fête; car eux-mêmes aussi étaient venus à la fête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Il vint donc derechef à Cana de Galilée, où il avait de l\'eau fait du vin. Et il y avait à Capharnaoum un officier royal, dont le fils était malade;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'cet homme, ayant appris que Jésus était arrivé de Judée en Galilée, se rendit auprès de lui, et il le sollicitait de venir guérir son fils; car il était sur le point de mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Jésus lui dit donc: « Si vous ne voyez des miracles et des prodiges, vous ne croyez absolument point. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'L\'officier royal lui dit: « Seigneur, descend avant que mon enfant ne meure. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Jésus lui dit: « Va, ton fils vit. » L\'homme crut la parole que Jésus lui avait dite, et il s\'acheminait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'mais comme déjà il descendait, ses esclaves vinrent à sa rencontre en disant que son enfant vivait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Il s\'informa donc de l\'heure précise à laquelle il s\'était trouvé mieux; ils lui dirent donc: « C\'est hier, à la septième heure, que la fièvre l\'a quitté. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Le père reconnut donc que c\'était à cette heure-là que Jésus lui avait dit: « Ton fils vit; » et il crut, lui, et toute sa famille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Or ce fut là le second miracle que fit encore Jésus lorsqu\'il fut venu de Judée en Galilée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Après cela eut lieu une fête des Juifs, et Jésus monta à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Or il existe à Jérusalem, près de la porte des brebis, une piscine, celle qui est nommée en hébreu Bethsaïda; elle est entourée de cinq portiques,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'dans lesquels était couchée une multitude de malades, aveugles, boiteux, paralysés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, '[Car un ange du Seigneur descendait de temps en temps dans la piscine et agitait l\'eau; celui donc qui entrait le premier dans la piscine après l\'agitation de l\'eau était guéri, de quelque maladie qu\'il fût atteint.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Or il se trouvait là un homme qui était depuis trente-huit ans en état de maladie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Jésus l\'ayant vu couché, et ayant su qu\'il l\'était déjà depuis longtemps, lui dit: « Veux-tu être guéri? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Le malade lui répliqua: « Seigneur, je n\'ai personne pour me jeter dans la piscine quand l\'eau a été agitée; mais pendant que j\'y vais moi-même un autre descend avant moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jésus lui dit: « Lève-toi, emporte ta couchette, et marche. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Et aussitôt l\'homme fut guéri, et il emporta sa couchette, et il marchait; or ce jour-là était un jour de sabbat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Les Juifs disaient donc au guéri: « C\'est un jour de sabbat, il ne t\'est pas permis d\'emporter ta couchette. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Mais il leur répliqua: « Celui qui m\'a guéri m\'a dit lui-même: Emporte ta couchette, et marche. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Ils lui demandèrent: « Qui est l\'homme qui t\'a dit: Emporte, et marche? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Mais le guéri ne savait qui c\'était, car Jésus s\'était esquivé grâce à la foule qui se trouvait en cet endroit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Ensuite Jésus le trouve dans le temple et il lui dit: « Voici, tu as été guéri, ne pèche plus, afin qu\'il ne t\'arrive pas pire. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'L\'homme s\'en alla, et il informa les Juifs que c\'était Jésus qui l\'avait guéri;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'c\'est pourquoi les Juifs poursuivaient Jésus, parce qu\'il avait fait cela un jour de sabbat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Mais Jésus leur répliqua: « Mon Père travaille jusques à maintenant, et moi aussi je travaille. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'A cause de cela les Juifs cherchaient donc encore plus à le faire mourir, parce que non seulement il anéantissait le sabbat, mais encore parce qu\'il appelait Dieu son propre père, se faisant lui-même égal à Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Il reprit donc la parole et il leur disait: « En vérité, en vérité je vous le déclare: le Fils ne peut rien faire de lui-même, s\'il ne le voit faire au Père; car quoi que fasse Celui-ci, le Fils aussi le fait pareillement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'car le Père aime le Fils, et Il lui montre tout ce qu\'il fait lui-même, et Il lui montrera des œuvres plus grandes que celles-ci, afin que vous soyez émerveillés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'car comme le Père ressuscite et vivifie les morts, de même aussi le Fils vivifie qui il veut;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'le Père non plus ne juge personne, mais Il a remis au Fils le jugement tout entier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'afin que tous honorent le Fils comme ils honorent le Père; celui qui n\'honore point le Fils n\'honore pas le Père qui l\'a envoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'En vérité, en vérité je vous déclare que celui qui écoute ma parole, et qui croit en Celui qui m\'a envoyé possède la vie éternelle, et il ne subit pas de jugement, mais il est passé de la mort à la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'En vérité, en vérité je vous déclare que l\'heure vient, et elle est maintenant arrivée, où les morts entendront la voix du fils de Dieu, et ceux qui l\'auront entendue vivront;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'car, comme le Père a la vie en Lui-même, ainsi Il a donné aussi au Fils d\'avoir la vie en lui-même,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'et Il lui a donné pouvoir de juger, parce que c\'est un fils d\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Ne vous en étonnez pas, car l\'heure vient où tous ceux qui sont dans les sépulcres entendront sa voix, et en sortiront,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'ceux qui auront fait le bien, pour une résurrection de vie, ceux qui auront fait le mal, pour une résurrection de jugement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Je ne puis, quant à moi, rien faire de moi-même; comme j\'entends je juge, et mon jugement est juste, parce que je ne recherche pas ma propre volonté, mais la volonté de Celui qui m\'a envoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Si c\'est moi qui témoigne en ma faveur, mon témoignage n\'est pas véridique;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'c\'est un autre qui témoigne pour moi, et je sais que le témoignage qu\'il porte en ma faveur est véridique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Pour vous, vous avez envoyé auprès de Jean, et il a rendu témoignage à la vérité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'mais moi, ce n\'est pas d\'un homme que je reçois le témoignage qui m\'est rendu; si j\'en parle, c\'est afin que vous soyez sauvés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'il était la lampe qui brûle et qui luit, mais vous, vous avez voulu vous égayer un instant à sa lumière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Quant à moi, j\'ai un témoignage qui est plus grand que celui de Jean, car les œuvres que le Père m\'a données afin que je les accomplisse, ces œuvres mêmes que je fais témoignent pour moi que le Père m\'a envoyé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'et le Père qui m\'a envoyé, c\'est Lui qui a témoigné pour moi. Jamais vous n\'avez entendu Sa voix, ni vous n\'avez vu Sa figure,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'et vous n\'avez pas Sa parole demeurant en vous, car vous ne croyez pas en celui que Lui-même a envoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Vous scrutez les Écritures, parce que vous pensez posséder en elles la vie éternelle, et ce sont elles qui témoignent pour moi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'et vous ne voulez pas venir à moi pour avoir la vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Ce n\'est pas que j\'accepte une gloire dispensée par les hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'mais j\'ai connu que vous n\'avez pas en vous l\'amour de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'moi, je suis venu au nom de mon Père, et vous ne me recevez pas; si un autre vient en son propre nom, celui-là, vous le recevrez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Comment pouvez-vous croire, vous qui acceptez une gloire que vous vous dispensez mutuellement, et qui ne cherchez pas la gloire qui vient de l\'Unique?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Ne pensez pas que ce soit moi qui vous accuserai auprès du Père; votre accusateur auprès du Père, c\'est Moïse en qui vous avez espéré;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'car si vous croyiez Moïse, vous me croiriez aussi, car il a écrit sur moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'mais si vous ne croyez pas à ses écrits, comment pouvez-vous croire à mes paroles? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Après cela Jésus s\'en alla de l\'autre côté de la mer de Galilée, de Tibériade.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Or une foule nombreuse suivait, parce qu\'elle voyait les miracles qu\'il opérait sur les malades;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'mais Jésus monta sur la montagne, et il s\'y tenait assis avec ses disciples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Or la Pâque était proche, la fête des Juifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Jésus ayant donc levé les yeux et ayant vu qu\'une foule nombreuse venait vers lui, il dit à Philippe: « Où pourrons-nous acheter des pains afin que ces gens-là se nourrissent? » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Or il parlait ainsi afin de l\'éprouver, car pour lui il savait ce qu\'il allait faire. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Philippe lui répliqua; « Deux cents deniers de pains ne leur suffisent pas pour que chacun en reçoive un peu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Un de ses disciples, André, frère de Simon Pierre, lui dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, '« Il y a ici un jeune enfant qui a cinq pains d\'orge et deux poissons; mais qu\'est-ce que cela pour tant de monde? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Jésus dit: « Faites étendre les gens. » Or il y avait beaucoup d\'herbe en cet endroit. Les hommes au nombre d\'environ cinq mille s\'étendirent donc.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Jésus prit donc les pains; et après avoir rendu grâces, il les distribua à ceux qui étaient couchés, de même fit-il aussi avec les poissons, tant qu\'ils en voulaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Mais lorsqu\'ils furent repus, il dit à ses disciples: « Rassemblez les morceaux qui restent, afin que rien ne soit perdu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Ils les rassemblèrent donc, et remplirent douze corbeilles avec les morceaux des cinq pains d\'orge, que laissèrent ceux qui avaient mangé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Les gens ayant donc vu les miracles qu\'il avait faits disaient: « Celui-ci est vraiment le prophète qui doit venir dans le monde. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Jésus donc, ayant su qu\'ils devaient venir et l\'enlever afin de le faire roi, se retira derechef seul sur la montagne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Mais, quand le soir fut venu, ses disciples descendirent vers la mer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'et étant montés dans une barque ils se dirigeaient de l\'autre côté de la mer vers Capharnaoum; et l\'obscurité était déjà survenue, et Jésus n\'était pas encore venu à eux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'et la mer, sur laquelle soufflait un grand vent, était agitée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Après donc qu\'ils eurent ramé pendant environ vingt-cinq ou trente stades, ils voient Jésus marchant sur la mer et arrivé près de la barque, et ils eurent peur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Mais il leur dit: « C\'est moi, n\'ayez pas peur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Ils voulaient donc le prendre dans la barque, et aussitôt la barque aborda sur le rivage vers lequel ils se rendaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Le lendemain, la foule qui se trouvait de l\'autre côté de la mer vit qu\'il n\'y avait eu là de barque qu\'une seule, et que Jésus n\'était point entré dans la barque avec ses disciples, mais que ses disciples seuls étaient partis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'd\'autres barques étaient venues de Tibériade près de l\'endroit où ils avaient mangé le pain après que le Seigneur eut rendu grâces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Lors donc que la foule vit que Jésus n\'était pas là non plus que ses disciples, ils montèrent eux-mêmes dans les barques et vinrent à Capharnaoum à la recherche de Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'et l\'ayant trouvé de l\'autre côté de la mer, ils lui dirent: « Rabbi, quand es-tu venu ici? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jésus leur répliqua: « En vérité, en vérité je vous le déclare, vous me recherchez, non parce que vous avez vu des miracles, mais parce que vous avez mangé des pains et que vous avez été rassasiés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'travaillez à vous procurer, non la nourriture qui périt, mais la nourriture qui subsiste pour la vie éternelle, laquelle le fils de l\'homme vous donnera; car c\'est lui que le Père, je veux dire Dieu, a marqué de Son sceau. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Ils lui dirent donc: « Qu\'avons-nous à faire pour accomplir l\'œuvre de Dieu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jésus leur répliqua: « C\'est ici l\'œuvre de Dieu, que vous croyiez en celui qu\'il a envoyé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Ils lui dirent donc: « Quel miracle fais-tu donc, toi, afin que nous le voyions et que nous te croyions? Que travailles-tu à nous procurer?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Nos pères ont mangé la manne dans le désert, comme il est écrit: Il leur a donné à manger du pain venu du ciel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Jésus leur dit donc: « En vérité, en vérité je vous le déclare, ce n\'est pas Moïse qui vous a donné le pain venu du ciel, mais mon Père vous donne le véritable pain venu du ciel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'car le pain de Dieu est celui qui descend du ciel et qui donne la vie au monde. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Ils lui dirent donc: « Seigneur, donne-nous toujours ce pain-là. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Jésus leur dit: « C\'est moi qui suis le pain de la vie; celui qui vient à moi n\'aura certainement jamais faim, et celui qui croit en moi n\'aura certainement jamais soif;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'mais je vous ai dit que, quoique vous m\'ayez vu, vous ne croyez cependant pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Tout ce que le Père me donne viendra à moi, et je ne me mettrai certainement pas dehors celui qui vient à moi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'car je suis descendu du ciel, non pour faire ma propre volonté, mais la volonté de Celui qui m\'a envoyé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'or c\'est ici la volonté de Celui qui m\'a envoyé, que je ne perde rien de tout ce qu\'il m\'a donné, mais que je le ressuscite au dernier jour;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'car c\'est ici la volonté de mon Père, que quiconque contemple le Fils et croit en lui possède la vie éternelle, et c\'est moi qui le ressusciterai au dernier jour. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Les Juifs murmuraient donc à son sujet, parce qu\'il avait dit: « Je suis le pain qui est descendu du ciel, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'et ils disaient: « Est-ce que celui-ci n\'est pas Jésus, le fils de Joseph, dont nous connaissons le père et la mère? Comment maintenant dit-il: je suis descendu du ciel? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Jésus leur répliqua: « Ne murmurez pas entre vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'personne ne peut venir à moi, à moins que le Père qui m\'a envoyé ne l\'attire, et c\'est moi qui le ressusciterai au dernier jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Il est écrit dans les prophètes: « Et ils seront tous enseignés de Dieu; » quiconque a écouté le Père et a été instruit par Lui vient à moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'ce n\'est pas que personne ait vu le Père, si ce n\'est celui qui est auprès de Dieu; celui-là a vu le Père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'En vérité, en vérité je vous le déclare, celui qui croit possède la vie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'C\'est moi qui suis le pain de la vie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'vos pères ont mangé la manne dans le désert, et ils sont morts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'le pain qui descend du ciel est tel, qu\'on doit en manger et ne point mourir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'c\'est moi qui suis le pain vivant qui est descendu du ciel; si quelqu\'un mange de ce pain, il vivra pour l\'éternité; mais le pain aussi que je donnerai, c\'est ma chair pour la vie du monde. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Les Juifs discutaient donc entre eux en disant: « Comment celui-ci peut-il nous donner sa chair à manger? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Jésus donc leur dit: « En vérité, en vérité je vous le déclare, si vous ne mangez la chair du fils de l\'homme, et si vous ne buvez son sang, vous n\'avez pas la vie en vous-mêmes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'celui qui mange ma chair et qui boit mon sang possède la vie éternelle, et je le ressusciterai au dernier jour;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'car ma chair est une vraie nourriture, et mon sang est un vrai breuvage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Celui qui mange ma chair et qui boit mon sang demeure en moi et moi en lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'de même que le Père qui est vivant m\'a envoyé et que moi aussi je vis à cause du Père, de même aussi celui qui me mange vivra à cause de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Tel est le pain qui est descendu du ciel; ce n\'est pas comme les pères qui ont mangé et qui sont morts, celui qui mange ce pain-là vivra pour l\'éternité. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Il dit ces choses en enseignant dans la synagogue à Capharnaoum.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Plusieurs donc de ses disciples l\'ayant ouï dirent: « Ce discours est choquant, qui peut l\'écouter? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Mais Jésus, connaissant en lui-même que ses disciples murmuraient là-dessus, leur dit: « Cela vous scandalise-t-il?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Si donc vous voyez le fils de l\'homme remonter là où il était premièrement...?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'C\'est l\'esprit qui vivifie, la chair ne sert de rien; les paroles que je vous ai adressées sont esprit et sont vie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'mais il y en a quelques-uns parmi vous qui ne croient pas. » Jésus en effet savait dès le commencement quels étaient ceux qui ne croyaient pas et quel était celui qui le livrerait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'et il dit: « C\'est à cause de cela que je vous ai dit que personne ne peut venir à moi, si cela ne lui a été donné par le Père. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'En conséquence plusieurs de ses disciples se retirèrent, et ne marchaient plus avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Jésus donc dit aux Douze: « Et vous aussi, ne voulez-vous point vous en aller? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Simon Pierre lui répliqua: « Seigneur, vers qui irions-nous? Tu possèdes les paroles de la vie éternelle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'et nous, nous avons cru et nous avons connu que c\'est toi qui es le saint de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Jésus leur répliqua: « N\'est-ce pas moi qui vous ai choisis, vous les Douze? Et pourtant l\'un d\'entre vous est un traître! » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Or il parlait de Judas, fils de Simon Iscariote; car c\'était lui qui devait le livrer, lui, un des Douze. –');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Et après cela Jésus parcourait la Galilée, car il ne voulait pas parcourir la Judée parce que les Juifs cherchaient à le faire mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Or la fête des Juifs, celle des tabernacles, était proche:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'ses frères donc lui dirent: « Sors d\'ici, et viens en Judée, afin que tes disciples aussi voient les œuvres que tu fais;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'car personne ne fait en cachette ce qu\'il cherche en même temps à rendre public; puisque tu fais ces choses, manifeste-toi toi-même au monde. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'En effet pas même ses frères ne croyaient en lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Jésus leur dit donc: « Mon temps n\'est pas encore venu, mais votre temps est toujours venu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'le monde ne peut vous haïr, mais il me hait parce que je témoigne contre lui que ses œuvres sont mauvaises;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'pour vous, montez à la fête; quant à moi, je ne monte pas encore à cette fête, parce que mon temps n\'est pas encore accompli. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Or, après leur avoir ainsi parlé, il restait en Galilée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Mais, lorsque ses frères furent montés à la fête, alors lui-même y monta aussi, non pas ouvertement, mais comme en cachette.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Les Juifs donc le cherchaient dans la fête et disaient: « Où est-il? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Et il y avait parmi la foule un grand murmure à son sujet; tandis que les uns disaient: « Il est homme de bien, d\'autres disaient: « Non; mais il égare la foule. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Cependant personne ne parlait librement de lui par crainte des Juifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Or, comme on était déjà vers le milieu de la fête, Jésus monta au temple, et il enseignait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Les Juifs donc s\'en émerveillaient, et disaient: « Comment celui-ci connaît-il les lettres, sans les avoir étudiées? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Jésus leur répliqua donc: « Ma doctrine n\'est pas la mienne, mais celle de Celui qui m\'a envoyé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'si quelqu\'un veut faire Sa volonté, il connaîtra, quant à ma doctrine, si elle vient de Dieu, ou si je parle de mon chef.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Celui qui parle de son chef recherche sa propre gloire; mais celui qui recherche la gloire de celui qui l\'a envoyé, celui-là est véridique, et il n\'y a pas d\'injustice en lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Moïse ne vous a-t-il pas donné la loi? Et pourtant nul d\'entre vous ne pratique la loi! Pourquoi cherchez-vous à me faire mourir? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'La foule lui répliqua: « Tu as un démon; qui est-ce qui cherche à te faire mourir? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jésus leur répliqua: « J\'ai fait une seule œuvre, et vous êtes tous dans l\'étonnement à cause de cela.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Moïse vous a donné la circoncision (non qu\'elle vienne de Moïse, mais des pères), et vous circoncisez un homme un jour de sabbat;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'si l\'homme subit la circoncision un jour de sabbat, afin que la loi de Moïse ne soit pas violée, pourquoi m\'en voulez-vous de ce que j\'ai guéri un homme tout entier un jour de sabbat?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Ne jugez pas selon l\'apparence, mais portez le juste jugement. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Quelques-uns des Hiérosolymitains disaient donc: « N\'est-ce pas celui qu\'ils cherchent à faire mourir?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Et voici, il parle librement et ils ne lui disent rien; est-ce que par hasard les chefs ont vraiment reconnu que c\'est lui qui est le Christ?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Mais nous savons d\'où sort celui-ci, tandis que lorsque le Christ vient personne ne sait d\'où il sort. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Jésus éleva donc la voix dans le temple en enseignant et en disant: « Vous me connaissez et vous savez aussi d\'où je sors; et ce n\'est pas de mon chef que je suis venu, mais Celui qui m\'a envoyé est véritable, lequel vous ne connaissez pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'moi, je Le connais, parce que je viens de Lui, et que c\'est Lui qui m\'a envoyé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Ils cherchaient donc à le saisir, et personne ne mit la main sur lui, parce que son heure n\'était pas encore venue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Mais plusieurs de la foule crurent en lui, et ils disaient: « Le Christ, quand il sera venu, fera-t-il plus de miracles que celui n\'en a fait? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Les pharisiens entendirent la foule qui murmurait ces paroles à son sujet, et les grands-prêtres et les pharisiens envoyèrent des huissiers afin de le saisir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Jésus dit donc: « Je suis encore avec vous pour un peu de temps, puis je m\'en vais vers Celui qui m\'a envoyé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'vous me chercherez et vous ne me trouverez pas, et là où moi je suis, vous, vous n\'y pouvez venir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Les Juifs se dirent donc entre eux: « Où doit-il se rendre, que nous ne pourrons pas le trouver? Est-ce qu\'il doit se rendre parmi ceux qui sont dispersés chez les Grecs, et enseigner les Grecs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Que signifie cette parole qu\'il a proférée: Vous me chercherez et vous ne me trouverez pas, et là où moi je suis, vous, vous n\'y pouvez black venir? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Or le dernier jour de la fête, qui était le grand, Jésus s\'avança et éleva la voix en disant: « Si quelqu\'un a soif, qu\'il vienne à moi et qu\'il boive;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'celui qui croit en moi, comme a dit l\'Écriture, des fleuves d\'eau vive découleront de son ventre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Or il dit cela relativement à l\'Esprit que ceux qui ont cru en lui devaient recevoir; car l\'esprit saint n\'avait pas encore été donné, parce que Jésus n\'avait pas encore été glorifié. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Des gens de la foule ayant donc entendu ces paroles, disaient: « Celui-ci est vraiment le prophète. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'D\'autres disaient: « Il est le Christ. » Mais les premiers disaient: « Est-ce qu\'en effet le Christ doit venir de Galilée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'L\'Écriture n\'a-t-elle pas dit que c\'est de la race de David et de Bethléem, le village où était David, que doit sortir le Christ? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Il y eut donc dissentiment parmi la foule à son sujet;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'mais quelques-uns d\'entre eux voulaient le saisir, toutefois personne ne mit la main sur lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Les huissiers revinrent donc auprès des grands prêtres et des pharisiens, et ceux-ci leur dirent: « Pourquoi ne l\'avez-vous pas amené? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Les huissiers répondirent: « Jamais homme n\'a parlé de la sorte. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Les pharisiens répliquèrent: « Est-ce que, vous aussi, vous vous êtes laissés séduire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Est-ce que l\'un des chefs ou des pharisiens a cru en lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Mais cette foule qui ne connaît pas la loi est maudite. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Nicodème (celui qui était venu auprès de lui antérieurement et qui était l\'un d\'entre eux), leur dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, '« Est-ce que notre loi juge l\'homme sans l\'avoir d\'abord interrogé, et sans avoir constaté ce qu\'il fait? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Ils lui répliquèrent: « Est-ce que toi aussi, tu sors de la Galilée? Examine, et vois qu\'un prophète ne saurait surgir de la Galilée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, '[Et chacun s\'en alla dans sa maison.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, '[Or Jésus se rendit sur la montagne des Oliviers;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'mais à l\'aube il vint de nouveau dans le temple, et tout le peuple venait à lui, et s\'étant assis il les enseignait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Les scribes et les pharisiens lui amènent une femme prise en flagrant délit d\'adultère, et l\'ayant placée au milieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'ils lui disent: « Maître, cette femme a été prise en flagrant délit d\'adultère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'or, dans la loi, Moïse nous a ordonné de lapider ces femmes-là; toi donc que prononces-tu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Or ils parlaient ainsi pour l\'éprouver, afin de pouvoir l\'accuser. Mais Jésus, s\'étant baissé, écrivait avec le doigt sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Mais comme ils persistaient à l\'interroger, s\'étant relevé il leur dit: « Que celui de vous qui est sans péché lui jette le premier la pierre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Et s\'étant baissé de nouveau il écrivait avec le doigt sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Mais eux, l\'ayant entendu, et étant repris par leur conscience, ils sortirent l\'un après l\'autre, à commencer par les anciens jusques aux derniers, et Jésus fut laissé seul avec la femme qui était au milieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Or Jésus s\'étant relevé et n\'ayant vu personne que la femme lui dit: « Femme, où sont-ils ces gens qui se sont faits tes accusateurs? Personne ne t\'a-t-il condamnée? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Or elle dit: « Personne, Seigneur. » Et Jésus lui dit: « Moi non plus je ne te condamne pas, va, et ne pèche plus. »]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Jésus s\'adressa donc derechef à eux en disant: « Je suis la lumière du monde, celui qui me suit ne marchera certainement point dans les ténèbres, mais il possédera la lumière de la vie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Les pharisiens lui dirent donc: « Tu portes témoignage en ta faveur; ton témoignage n\'est pas véridique. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jésus leur répliqua: « Lors même que je porte témoignage en ma faveur, mon témoignage est véridique, parce que je sais d\'où je suis venu et où je vais, mais vous, vous ne savez d\'où je viens et où je vais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Pour vous, vous jugez selon la chair, pour moi je ne juge personne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'mais d\'ailleurs si je juge, mon jugement est véritable, parce que je ne suis pas seul, mais qu\'avec moi est aussi le Père qui m\'a envoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Et en outre dans votre loi il est écrit que le témoignage de deux hommes est véridique;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'c\'est moi qui porte témoignage en ma faveur, et le Père qui m\'a envoyé porte aussi témoignage en ma faveur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Ils lui disaient donc: « Où est ton Père? » Jésus répliqua: « Vous ne connaissez ni moi, ni mon Père; si vous me connaissiez, vous connaîtriez aussi mon Père. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Il prononça ces paroles près du trésor, pendant qu\'il enseignait dans le temple; et personne ne le saisit, parce que son heure n\'était pas encore venue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Il leur dit donc derechef: « Je m\'en vais, et vous me chercherez, et vous mourrez dans votre péché; là où moi je vais, vous, vous ne pouvez venir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Les Juifs disaient donc: « Est-ce qu\'il se tuera, qu\'il dit: Là où moi je vais, vous, vous ne pouvez venir? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Et il leur disait: « Pour vous, vous êtes d\'en bas, mais je suis d\'en haut; vous, vous êtes de ce monde, moi, je ne suis pas de ce monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Je vous ai donc dit que vous mourrez dans vos péchés; car si vous ne croyez pas que c\'est moi qui le suis, vous mourrez dans vos péchés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Ils lui disaient donc: « Toi, qui es-tu? » Jésus leur dit: « Cela même dont je vous parle dès le commencement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'J\'ai beaucoup à dire et à juger à votre égard, mais Celui qui m\'a envoyé est véridique, et quant à moi, ce que j\'ai entendu de Lui, c\'est ce dont je parle dans le monde. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Ils ne comprirent pas qu\'il leur parlait du Père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Jésus dit donc: « Quand vous aurez élevé le fils de l\'homme, alors vous connaîtrez que c\'est moi qui le suis, et que je ne fais rien de mon chef, mais que je parle comme mon Père m\'a enseigné,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'et que Celui qui m\'a envoyé est avec moi; Il ne m\'a pas laissé seul, parce que je fais toujours ce qui Lui plaît. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Pendant qu\'il parlait ainsi, plusieurs crurent en lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Jésus disait donc aux Juifs qui avaient cru en lui: « Si vous demeurez dans ma parole, vous êtes vraiment mes disciples,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'et vous connaîtrez la vérité, et la vérité vous rendra libres. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Ils lui répliquèrent: « Nous sommes la postérité d\'Abraham, et jamais nous ne fûmes esclaves de personne; comment peux-tu dire: vous deviendrez libres? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jésus leur répliqua: « En vérité, en vérité je vous déclare que quiconque pratique le péché est esclave du péché;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'or l\'esclave ne demeure pas éternellement dans la famille; le fils y demeure éternellement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'si donc le fils vous délivre, vous serez réellement libres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Je sais que vous êtes la postérité d\'Abraham, mais vous cherchez à me faire mourir, parce que ma parole ne trouve pas accès parmi vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Pour moi, je parle de ce que j\'ai vu auprès de mon Père; vous donc aussi, vous faites ce que vous avez appris de votre père. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Ils lui répliquèrent: « Notre père est Abraham. » Jésus leur dit: « Si vous étiez enfants d\'Abraham, vous feriez les œuvres d\'Abraham;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'mais maintenant vous cherchez à me faire mourir, moi, un homme qui vous ai annoncé la vérité que j\'ai entendue de Dieu; c\'est ce que n\'a point fait Abraham;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'vous faites les œuvres de votre père. » Ils lui dirent: « Nous ne sommes point nés d\'un commerce impudique, nous n\'avons qu\'un seul et unique père, qui est Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jésus leur dit: « Si Dieu était votre père, vous m\'aimeriez; en effet je suis issu de Dieu et je viens de Lui, car je ne suis point venu de mon chef, mais c\'est Lui qui m\'a envoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Pourquoi ne comprenez-vous pas mon langage? Parce que vous ne pouvez écouter ma parole;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'pour vous, vous êtes issus du père qui est le diable, et vous voulez accomplir les désirs de votre père; il a été homicide dès le commencement, et il ne se tient pas dans la vérité, parce qu\'il n\'y a pas de vérité en lui; lorsqu\'il profère le mensonge, il parle de son propre fonds, car il est menteur et en est le père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Mais moi, parce que je vous dis la vérité, vous ne me croyez pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Qui d\'entre vous me convainc de péché? Si je dis la vérité, pourquoi ne me croyez-vous pas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Celui qui est issu de Dieu écoute les paroles de Dieu; vous, vous ne les écoutez pas, parce que vous n\'êtes pas issus de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Les Juifs lui répliquèrent: « N\'avons-nous pas raison de dire que tu es un Samaritain, et que tu as un démon? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jésus répliqua: « Pour moi, je n\'ai pas de démon, mais j\'honore mon Père, et vous, vous me déshonorez;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'mais je ne recherche pas ma propre gloire; il y en a Un qui la recherche et qui juge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'En vérité, en vérité je vous déclare que si quelqu\'un a observé ma parole, il ne verra certainement jamais la mort. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Les Juifs lui dirent: « Maintenant nous reconnaissons que tu as un démon; Abraham est mort ainsi que les prophètes, et toi tu dis: Si quelqu\'un a observé ma parole, il ne verra certainement jamais la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Est-ce que tu es plus grand que notre père Abraham, lequel est pourtant mort? Les prophètes aussi sont morts. Qui prétends-tu être? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jésus répliqua: « Si c\'est moi qui me glorifie moi-même, ma gloire n\'est rien; c\'est mon Père qui me glorifie, Lui que vous dites être votre Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'et cependant vous ne Le connaissez pas, mais moi je Le connais; et si je disais que je ne Le connais pas, je serais un menteur comme vous, mais je Le connais et j\'observe Sa parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham votre père a tressailli de joie de ce qu\'il verrait ma journée, et il l\'a vue, et il s\'est réjoui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Les Juifs lui dirent donc: « Tu n\'as pas encore cinquante ans, et tu as vu Abraham! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jésus leur dit: « En vérité, en vérité je vous le déclare, avant qu\'Abraham existât, je suis. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Ils prirent donc des pierres pour les lui jeter; Jésus se cacha et sortit du temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Et en passant il vit un homme aveugle de naissance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'et ses disciples l\'interrogèrent en disant: « Rabbi, qui est-ce qui a péché, celui-ci ou ses parents, pour qu\'il naquît aveugle? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jésus répliqua: « Ni celui-ci ni ses parents n\'ont péché, mais c\'est afin que les œuvres de Dieu fussent manifestées en lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'il nous faut travailler aux œuvres de Celui qui m\'a envoyé, pendant qu\'il est jour; la nuit vient où personne ne peut travailler;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'pendant que je suis dans le monde, je suis la lumière du monde. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Après avoir dit cela, il cracha à terre et fit de la boue avec cette salive, et il lui appliqua la boue qu\'il avait faite sur les yeux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'et il lui dit: « Va te laver dans la piscine de Siloam », (ce qui se traduit par envoyé). Il s\'en alla voyant clair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Les voisins donc et ceux qui le voyaient auparavant faire le métier de mendiant, disaient: « N\'est-ce pas celui qui était assis et qui mendiait? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'D\'autres disaient: « C\'est lui. » D\'autres disaient: « Non, mais il lui ressemble. » Pour lui il disait: « C\'est bien moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Ils lui dirent donc: « Comment tes yeux se sont-ils ouverts? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Il répliqua: « L\'homme qui est appelé Jésus a fait de la boue, et il a oint mes yeux, et il m\'a dit: Va à Siloam, et lave-toi. M\'en étant donc allé, après m\'être lavé j\'ai recouvré la vue. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Et ils lui dirent: « Où est-il? » Il dit: « Je ne sais pas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Ils le conduisent auprès des pharisiens, lui qui naguère était aveugle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Or c\'était un jour de sabbat que celui où Jésus avait fait la boue et lui avait ouvert les yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Les pharisiens aussi lui demandaient donc derechef comment il avait recouvré la vue; et il leur dit: « Il m\'a appliqué de la boue sur les yeux, et je me suis lavé, et je vois. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Quelques-uns des pharisiens disaient donc: « Ce n\'est pas de la part de Dieu que vient cet homme, car il n\'observe pas le sabbat. » D\'autres disaient: « Comment un homme pécheur peut-il faire de tels miracles? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Et il y eut dissentiment parmi eux. Ils disent donc derechef à l\'aveugle: « Toi, que dis-tu de lui, pour t\'avoir ouvert les yeux? » Et il dit: « C\'est un prophète. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Les Juifs donc ne crurent pas qu\'il eût été aveugle et qu\'il eût recouvré la vue, jusques à ce qu\'ils eussent appelé les parents de celui-là même qui avait recouvré la vue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'et ils leur demandèrent: « Celui-ci est-il votre fils que vous dites être né aveugle? Comment donc voit-il maintenant? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Ses parents répliquèrent donc: « Nous savons que celui-ci est notre fils, et qu\'il est né aveugle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'mais comment il voit maintenant, nous ne le savons pas; ou bien qui est-ce qui lui a ouvert les yeux, c\'est quant à nous ce que nous ne savons pas; interrogez-le lui-même, il a de l\'âge, il parlera lui-même de ce qui le concerne. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Ses parents s\'exprimèrent ainsi parce qu\'ils craignaient les Juifs; car déjà les Juifs s\'étaient entendus afin que si quelqu\'un le reconnaissait pour le Christ, il fût mis au ban de la synagogue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'C\'est pour cela que ses parents dirent: « il a de l\'âge, interrogez-le lui-même. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Ils appelèrent donc une seconde fois l\'homme qui avait été aveugle, et ils lui dirent: « Rends gloire à Dieu; nous savons que cet homme-là est un pécheur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'L\'autre répliqua donc: « Si c\'est un pécheur, je n\'en sais rien; je sais une seule chose, c\'est qu\'ayant été aveugle, maintenant je vois. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Ils lui dirent donc: « Que t\'a-t-il fait? Comment t\'a-t-il ouvert les yeux? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Il leur répliqua: « Je vous l\'ai déjà dit, et vous ne l\'avez pas écouté; pourquoi donc voulez-vous l\'entendre derechef? Est-ce que vous aussi vous voulez devenir ses disciples? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Et ils l\'injurièrent et dirent: « C\'est toi qui es le disciple de cet homme-là; mais pour nous c\'est de Moïse que nous sommes les disciples;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'nous savons que Dieu a parlé à Moïse, mais pour celui-là nous ne savons d\'où il vient. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'L\'homme leur répliqua: « Après ce qui s\'est passé il est en effet étrange que vous ne sachiez d\'où il vient, et cependant il a ouvert mes yeux:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'nous savons que Dieu n\'écoute point les pécheurs, mais si quelqu\'un est pieux et fait sa volonté, c\'est celui-là qu\'il écoute;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'jamais on n\'a ouï dire que personne eût ouvert les yeux d\'un aveugle-né.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Si celui-ci n\'était pas venu de la part de Dieu, il ne pouvait rien faire. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Ils lui répliquèrent: « Tu es né tout rempli de péchés, et tu nous fais la leçon! » Et ils l\'expulsèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jésus apprit qu\'ils l\'avaient expulsé, et l\'ayant rencontré il dit: « Est-ce que tu crois au fils de l\'homme? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, '« Et qui est-il, » dit-il, « Seigneur, afin que je croie en lui? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Jésus lui dit: « Non seulement tu l\'as vu, mais celui-là même qui parle avec toi, c\'est lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'L\'autre dit: « Je crois, Seigneur, » et il l\'adora.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Et Jésus dit: « C\'est pour rendre un jugement que je suis venu dans ce monde, afin que ceux qui ne voient pas voient, et que ceux qui voient deviennent aveugles. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Ceux des pharisiens qui étaient avec lui ouïrent ces paroles, et ils lui dirent: « Est-ce que nous aussi nous sommes aveugles? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jésus leur dit: « Si vous étiez aveugles, vous n\'auriez point de péché; mais maintenant vous dites: nous voyons! votre péché demeure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'En vérité, en vérité je vous le déclare, celui qui n\'entre pas par la porte dans l\'enclos des brebis, mais qui l\'escalade par un autre endroit, celui-là est un voleur et un brigand;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'mais celui qui entre par la porte est le berger des brebis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'c\'est à lui qu\'ouvre le portier, et les brebis entendent sa voix, et il appelle ses propres brebis par leur nom, et il les fait sortir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'lorsqu\'il les a toutes fait sortir, il marche devant elles, et ses brebis le suivent, parce qu\'elles connaissent sa voie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'mais elles ne suivront certainement pas un étranger, elles le fuiront au contraire, parce qu\'elles ne connaissent pas la voix des étrangers. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Jésus leur adressa cette similitude, mais pour eux ils ne comprirent pas ce dont il leur parlait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Jésus dit donc derechef: « En vérité, en vérité je vous le déclare, c\'est moi qui suis la porte des brebis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'tous ceux qui sont venus avant moi sont des voleurs et des brigands; mais les brebis ne les ont point écoutés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'c\'est moi qui suis la porte; si quelqu\'un est entré par moi, il sera sauvé, et il entrera et il sortira et il trouvera un pâturage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Le voleur ne vient que pour dérober, pour égorger et pour détruire; moi, je suis venu afin qu\'elles aient la vie, et qu\'elles l\'aient surabondamment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'C\'est moi qui suis le bon berger; le bon berger sacrifie sa propre vie pour ses brebis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'le mercenaire, qui n\'est pas un berger et auquel les brebis n\'appartiennent pas en propre, voit le loup venir, et il abandonne les brebis, et il s\'enfuit, et le loup les enlève et les disperse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'car c\'est un mercenaire, et il n\'a cure des brebis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'C\'est moi qui suis le bon berger, et je connais celles qui sont à moi, et celles qui sont à moi me connaissent');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'comme mon Père me connaît et que moi je connais mon Père; et je sacrifie ma propre vie pour mes brebis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Je possède encore d\'autres brebis, qui ne sont pas de cet enclos; il faut que je les amène aussi, et elles entendront ma voix, et il y aura un seul troupeau, un seul berger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Mon Père m\'aime, parce que moi je sacrifie ma vie, afin de la reprendre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'personne ne me l\'a enlevée, mais je la sacrifie de moi-même; j\'ai le pouvoir de la sacrifier, et j\'ai le pouvoir de la reprendre; j\'ai reçu cet ordre de mon Père. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Il y eut derechef dissentiment parmi les Juifs à cause de ces paroles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'plusieurs d\'entre eux disaient: « Il a un démon, et il est fou; pourquoi l\'écoutez-vous? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'D\'autres disaient: « Ces paroles ne sont pas d\'un démoniaque; est-ce qu\'un démon peut ouvrir les yeux des aveugles? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Alors eut lieu à Jérusalem la fête de la Dédicace; c\'était en hiver,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'et Jésus se promenait dans le temple, sous le portique de Salomon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Les Juifs l\'entourèrent donc et ils lui disaient: « Jusques à quand tiens-tu notre âme en suspens? Si c\'est toi qui es le Christ, dis-le-nous ouvertement. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jésus leur répliqua: « Je vous l\'ai dit, et vous ne l\'avez pas cru. Les œuvres que je fais au nom de mon Père, voilà ce qui témoigne en faveur de moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'mais vous, vous ne croyez pas, car vous n\'êtes pas de mes brebis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'mes brebis entendent ma voix, et moi je les connais, et elles me suivent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'et je leur donne la vie éternelle, et elles ne périront certainement jamais, et personne ne les arrachera de ma main;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'ce que mon Père m\'a donné est plus grand que toutes choses, et personne ne peut l\'arracher de la main du Père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Moi et le Père nous sommes un. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Les Juifs apportèrent derechef des pierres, afin de le lapider.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Jésus leur répliqua: « Je vous ai fait voir beaucoup de belles œuvres qui venaient du Père; pour laquelle de ces œuvres-là me lapidez-vous? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Les Juifs lui répliquèrent: « Ce n\'est pas pour une belle œuvre que nous te lapidons, mais à cause d\'un blasphème, et parce que, étant un homme, tu te fais Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jésus leur répliqua: « N\'est-il pas écrit dans votre loi: « J\'ai dit: Vous êtes des Dieux? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Si elle a appelé Dieux ceux auxquels la parole de Dieu fut adressée (et l\'Écriture ne peut être abolie),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'celui que le Père a consacré et envoyé dans le monde, vous lui dites: tu blasphèmes, parce que j\'ai dit: Je suis fils de Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Si je ne fais pas les œuvres de mon Père, ne me croyez pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'mais si je les fais, quand même vous ne me croiriez pas, croyez à ces œuvres, afin que vous appreniez et que vous sachiez que le Père est en moi, et que moi je suis dans le Père. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Ils cherchaient derechef à le saisir, et il échappa de leur main,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'et il s\'en alla de nouveau au delà du Jourdain, dans l\'endroit où se tenait Jean lorsqu\'il commença à baptiser, et il demeurait là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Et plusieurs vinrent à lui, et ils disaient: « Il est vrai que Jean n\'a fait aucun miracle, mais tout ce que Jean a dit de celui-ci était vrai. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Et plusieurs crurent en lui en ce lieu-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Or il y avait un malade, Lazare de Béthanie, du village de Marie et de Marthe sa sœur. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Or Marie était celle qui oignit le Seigneur de parfum et qui essuya ses pieds avec ses cheveux; c\'était son frère Lazare qui était malade. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Les sœurs envoyèrent donc auprès de lui en lui faisant dire: « Seigneur, voici, celui que tu aimes est malade. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Ce que Jésus ayant ouï, il dit: « Cette maladie ne doit pas entraîner la mort, mais servir à la gloire de Dieu, afin que le fils de Dieu soit glorifié par elle. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Or Jésus aimait Marthe, et sa sœur, et Lazare.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Lors donc qu\'il eut appris qu\'il était malade, il demeura, il est vrai, pour le moment pendant deux jours dans l\'endroit où il se trouvait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'puis ensuite il dit aux disciples: « Retournons en Judée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Les disciples lui disent: Rabbi, naguère les Juifs cherchaient à te lapider, et tu retournes là derechef! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jésus répliqua: « Est-ce qu\'il n\'y a pas douze heures au jour? Si quelqu\'un marche pendant le jour, il ne bronche point, parce qu\'il voit la lumière de ce monde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'mais si quelqu\'un marche pendant la nuit, il bronche, parce que la lumière n\'est pas en lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Il parla ainsi, et après il leur dit: « Lazare notre ami s\'est endormi, mais je vais pour l\'éveiller. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Les disciples lui dirent donc: « Seigneur, s\'il s\'est endormi, il sera sauvé. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Mais Jésus avait parlé de sa mort; tandis qu\'eux s\'imaginèrent qu\'il parlait de l\'assoupissement du sommeil. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Alors donc Jésus leur dit ouvertement: « Lazare est mort,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'et je me réjouis à cause de vous, afin que vous croyiez, de ce que je n\'étais pas là; mais allons vers lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Thomas, qui est appelé Didymos, dit donc aux autres disciples: « Allons-y, nous aussi, afin que nous mourrions avec lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Jésus étant donc arrivé trouva qu\'il était depuis déjà quatre jours dans le sépulcre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Or Béthanie était rapprochée de Jérusalem d\'environ quinze stades,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'et plusieurs d\'entre les Juifs étaient venus auprès de Marthe et de Marie, afin de les consoler au sujet de leur frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Marthe donc, lorsqu\'elle apprit que Jésus arrivait, vint à sa rencontre, tandis que Marie demeurait assise dans la maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Marthe dit donc à Jésus: « Si tu avais été ici, mon frère ne serait point mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'et maintenant je sais que tout ce que tu demanderas à Dieu, Dieu te le donnera. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jésus lui dit: « Ton frère ressuscitera. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Marthe lui dit: « Je sais qu\'il ressuscitera lors de la résurrection au dernier jour. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Jésus lui dit: « C\'est moi qui suis la résurrection et la vie; celui qui croit en moi vivra, quand même il serait mort');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'et tout vivant qui croit en moi ne mourra certainement jamais. Crois-tu cela? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Elle lui dit: « Oui, Seigneur, pour moi je crois que c\'est toi qui es le Christ, le fils de Dieu, celui qui doit venir dans le monde. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Et après avoir dit cela elle s\'en alla, et elle appela Marie sa sœur en lui disant en secret: « Le maître est ici et il t\'appelle. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Celle-ci, dès qu\'elle eut entendu, se leva en toute hâte et vint vers lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Or Jésus n\'était pas encore entré dans le village, mais il était encore à l\'endroit où l\'avait rencontré Marthe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Les Juifs donc qui étaient avec elle dans la maison et qui la consolaient, voyant que Marie s\'était levée en toute hâte et était sortie, la suivirent en pensant qu\'elle allait au sépulcre afin d\'y pleurer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Marie donc, lorsqu\'elle fut arrivée là où était Jésus, l\'ayant vu tomba à ses pieds, en lui disant: « Seigneur, si tu avais été ici, mon frère ne serait pas mort. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Jésus donc, lorsqu\'il la vit pleurer, et les Juifs venus avec elle pleurer aussi, fut irrité en son esprit, et il tressaillit');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'et dit: « Où l\'avez-vous mis? » On lui dit: « Seigneur, viens et vois. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Jésus pleura.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Les Juifs donc disaient: « Voyez comme il l\'aimait. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Mais quelques-uns d\'entre eux dirent: « Est-ce que celui-ci qui a ouvert les yeux de l\'aveugle ne pouvait pas faire que celui-ci aussi ne mourût point? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Jésus donc, derechef irrité en lui-même, se rend au sépulcre; or c\'était une grotte, et une pierre était placée dessus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Jésus dit: « Enlevez la pierre. » La sœur du mort, Marthe, lui dit: « Seigneur, il donne déjà de l\'odeur; car voici quatre jours qu\'il y est. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jésus lui dit: « Ne t\'ai-je pas dit que, si tu crois, tu verras la gloire de Dieu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Ils enlevèrent donc la pierre. Et Jésus leva les yeux en haut et dit: « Père, je Te rends grâce de ce que Tu m\'as écouté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'pour moi je savais bien que Tu m\'écoutes toujours, mais c\'est à cause de la foule qui m\'entoure que j\'ai parlé, afin qu\'ils croient que c\'est Toi qui m\'as envoyé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Et après avoir dit cela il s\'écria à haute voix: « Lazare, viens dehors! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Le mort sortit, avec les pieds et les mains attachés par des bandelettes, et son visage était enveloppé d\'un suaire. Jésus leur dit: « Déliez-le, et laissez-le aller. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Plusieurs donc d\'entre les Juifs, qui étaient venus auprès de Marie, et qui avaient vu ce qu\'il avait fait, crurent en lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'mais quelques-uns d\'entre eux s\'en allèrent vers les pharisiens et leur dirent ce qu\'avait fait Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Les grands prêtres et les pharisiens rassemblèrent donc le Sanhédrin et ils disaient: « Qu\'y a-t-il à faire, car cet homme opère beaucoup de miracles?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Si nous le laissons libre d\'agir ainsi, tous croiront en lui, et les Romains viendront, et ils nous enlèveront et le lieu et la nation. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Or l\'un d\'entre eux, Caïaphas, qui était grand prêtre cette année-là, leur dit: « Vous n\'y entendez rien,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'et vous ne réfléchissez pas qu\'il vous convient mieux qu\'un seul homme meure pour le peuple, et que la nation entière ne périsse pas. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Or il ne dit point cela de lui-même, mais étant grand prêtre cette année-là il prophétisa que Jésus devait mourir pour la nation,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'et non pas seulement pour la nation, mais aussi afin de réunir en un seul corps les enfants de Dieu dispersés. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'A partir donc de ce jour-là ils délibérèrent afin de le faire mourir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Jésus donc ne se montrait plus ouvertement parmi les Juifs, mais de là il s\'en alla dans la contrée voisine du désert, dans la ville appelée Ephraïm. Et il y demeura avec les disciples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Or la Pâque des Juifs était proche, et plusieurs montèrent du reste du pays à Jérusalem avant la Pâque, afin de se purifier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Ils cherchaient donc Jésus et se disaient entre eux en se tenant dans le temple: « Que vous en semble? Ne viendra-t-il point du tout à la fête? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Cependant les grands prêtres et les pharisiens avaient donné des ordres, afin que si quelqu\'un savait où il était, il en avertît, pour qu\'ils le fissent saisir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Jésus donc, six jours avant la Pâque, vint à Béthanie, où était Lazare que Jésus avait ressuscité des morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Ils lui préparèrent donc là un repas, et Marthe servait, tandis que Lazare était l\'un de ceux qui étaient à table avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Marie donc, ayant pris une livre d\'un parfum de véritable nard, très précieux, oignit les pieds de Jésus, et elle essuya ses pieds avec ses cheveux; et toute la maison fut remplie de l\'odeur du parfum.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Mais Judas l\'Iscariote, l\'un de ses disciples, celui qui devait le livrer, dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, '« Pourquoi ce parfum n\'a-t-il pas été vendu trois cents deniers, et donné aux pauvres? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Or il dit cela, non pas qu\'il eût souci des pauvres, mais parce qu\'il était voleur, et que tenant la bourse il portait ce qu\'on y mettait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Jésus dit donc: « Laisse-la en paix, afin qu\'elle le garde pour le jour de ma sépulture;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'car vous devez toujours avoir les pauvres avec vous, mais vous ne devez pas m\'avoir toujours. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'La foule nombreuse des Juifs apprit donc qu\'il était là, et ils vinrent, non à cause de Jésus seulement, mais afin de voir aussi Lazare qu\'il avait ressuscité des morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Mais les grands prêtres délibérèrent aussi afin de faire mourir aussi Lazare,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'parce que, à cause de lui, plusieurs des Juifs s\'y rendaient, et croyaient en Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Le lendemain, la nombreuse foule qui était venue à la fête, ayant appris que Jésus arrivait à Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'prit les rameaux des palmiers et sortit à sa rencontre; et ils criaient: « Hosanna, béni soit celui qui vient au nom du Seigneur, et le roi d\'Israël! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Or Jésus ayant trouvé un ânon s\'assit dessus, selon qu\'il est écrit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, '« Ne crains point, fille de Sion, voici ton roi vient, assis sur le petit d\'une ânesse. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Ses disciples ne comprirent pas cela d\'abord, mais, lorsque Jésus eut été glorifié, alors ils se rappelèrent que cela avait été écrit de lui, et qu\'on le lui avait fait. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'La foule, qui était avec lui quand il avait évoqué Lazare du sépulcre et qu\'il l\'avait ressuscité des morts, rendait donc témoignage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'La foule s\'était portée à sa rencontre, parce qu\'elle avait appris qu\'il avait fait ce miracle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Les pharisiens se dirent donc les uns aux autres: « Vous voyez que vous n\'avez rien gagné; voici, le monde s\'en est allé après lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Or il y avait là quelques Grecs du nombre de ceux qui montaient pour adorer pendant la fête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Ils abordèrent donc Philippe qui était de Bethsaïda en Galilée, et ils le sollicitaient en disant: « Seigneur, nous désirons voir Jésus. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Philippe vient le dire à André, André et Philippe viennent le dire à Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'mais Jésus leur réplique: « L\'heure est venue où le fils de l\'homme doit être glorifié;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'en vérité, en vérité je vous le déclare, si le grain de blé ne meurt après être tombé dans la terre, il demeure seul; mais s\'il meurt, il porte beaucoup de fruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Celui qui aime sa vie la perd, et celui qui hait sa vie en ce monde la conservera pour la vie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Si quelqu\'un veut me servir qu\'il me suive, et là où je suis, là aussi sera mon serviteur; si quelqu\'un veut me servir, le Père l\'honorera...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Maintenant mon âme est troublée... Et que dirai-je?... Père, délivre-moi de cette heure!... Mais c\'est pour ceci que je suis parvenu jusqu\'à cette heure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Père, glorifie mon nom! » Une voix vint donc du ciel: « Déjà Je l\'ai glorifié, et Je le glorifierai encore. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'La foule qui était présente et qui avait ouï disait que c\'était un tonnerre; d\'autres disaient: « Un ange lui a parlé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jésus répliqua: « Ce n\'est pas à cause de moi que cette voix s\'est fait entendre, mais à cause de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Maintenant il y a jugement sur ce monde; maintenant le chef de ce monde sera jeté dehors,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'et moi, si je suis élevé de dessus la terre j\'attirerai tous les hommes à moi. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Or il parlait ainsi pour indiquer par quel genre de mort il devait mourir. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'La foule lui répliqua donc: « Nous avons appris par la loi que le Christ demeure éternellement, et comment, toi, dis-tu qu\'il faut que le fils de l\'homme soit élevé? Qui est ce fils de l\'homme? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Jésus leur dit donc: « Pour peu de temps encore la lumière est parmi vous; marchez comme possédant la lumière, afin que les ténèbres ne vous surprennent point; celui qui marche dans les ténèbres ne sait où il va.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Comme vous possédez la lumière, croyez en la lumière, afin que vous deveniez fils de la lumière. » Après avoir ainsi parlé, Jésus s\'en alla et se cacha à eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Mais quoiqu\'il eût fait tant de miracles devant eux, ils ne croyaient pas en lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'afm que fût accomplie la parole qu\'a proférée Ésaïe le prophète: « Seigneur, qui est-ce qui a cru à ce qu\'il entend de nous? Et le nom du Seigneur, à qui a-t-il été manifesté? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Aussi ne pouvaient-ils croire, parce que Ésaïe a dit encore:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '« Il a aveuglé leurs yeux et endurci leur cœur, afin qu\'ils ne vissent point avec les yeux et ne comprissent point avec le cœur, et qu\'ils ne se convertissent point, et que Je ne les guérisse point. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Ésaïe a dit cela lorsqu\'il vit sa gloire, et il a parlé de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Néanmoins il y en eut plusieurs, même d\'entre les chefs, qui crurent en lui, mais à cause des pharisiens ils ne l\'avouaient pas, afin de n\'être pas mis au ban de la synagogue;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'car ils aimèrent la gloire des hommes plus que la gloire de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Jésus pourtant cria et dit: « Celui qui croit en moi ne croit pas en moi, mais en Celui qui m\'a envoyé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'et celui qui me voit voit Celui qui m\'a envoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Je suis venu dans le monde comme une lumière, afin que celui qui croit en moi ne demeure point dans les ténèbres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Et si quelqu\'un a entendu mes paroles et ne les a point gardées, ce n\'est pas moi qui le juge; car je ne suis pas venu afin de juger le monde, mais afin de sauver le monde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'celui qui me rejette et qui ne reçoit pas mes paroles a son juge, la parole que j\'ai prêchée, voilà ce qui le jugera au dernier jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Car pour moi je n\'ai point parlé de mon chef, mais le Père qui m\'a envoyé m\'a lui-même prescrit ce que je devais dire et ce dont je devais parler;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'et je sais que ce qu\'il prescrit est la vie éternelle. Ainsi les choses que je dis, je les dis comme mon Père me les a dites. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Or, avant la fête de Pâque, Jésus, sachant que son heure était venue pour passer de ce monde à son Père, après avoir aimé les siens qui étaient dans le monde, les aima jusques à la fin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'et, pendant le repas (le diable ayant déjà mis en son cœur que Judas Iscariote fils de Simon le livrât),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'quoiqu\'il sût que le Père lui a tout remis dans les mains, et qu\'il est issu de Dieu, et qu\'il s\'en va vers Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'il se lève du repas et se dépouille de son manteau, et ayant pris un linge il s\'en ceignit lui-même;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'puis il verse de l\'eau dans le bassin, et il se mit à laver les pieds des disciples et à les essuyer avec le linge dont il s\'était ceint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Il vient donc vers Simon Pierre, lequel lui dit: « Seigneur, est-ce à toi de me laver les pieds? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jésus lui répliqua: « Ce que je fais, tu ne le sais pas maintenant, mais tu le connaîtras ensuite. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Pierre lui dit: « Tu ne me laveras certainement jamais les pieds! » Jésus lui répondit: « Si je ne te lave, tu n\'as rien de commun avec moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Pierre Simon lui dit: « Seigneur, non seulement mes pieds, mais encore les mains et la tête! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jésus lui dit: « Celui qui s\'est baigné n\'a pas besoin d\'autre chose que de se laver les pieds, mais il est entièrement net; et vous, vous êtes nets, mais pas tous. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Il connaissait en effet celui qui le livrait; c\'est pourquoi il dit: « vous n\'êtes pas tous nets. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Lors donc qu\'il eut lavé leurs pieds, et qu\'il eut repris son manteau, et qu\'il se fut de nouveau mis à table, il leur dit: « Savez-vous ce que je vous ai fait?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Vous m\'appelez Maître et Seigneur, et vous dites bien, car je le suis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'si donc je vous ai lavé les pieds, moi qui suis votre Maître et votre Seigneur, vous aussi, vous devez vous laver les pieds les uns aux autres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'car je vous ai donné un exemple, afin que comme j\'ai fait pour vous, vous fassiez aussi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'en vérité, en vérité je vous le déclare, un esclave n\'est pas plus grand que son seigneur, ni un apôtre plus grand que celui qui l\'a envoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Si vous savez ces choses vous êtes heureux, à condition que vous les pratiquiez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Je ne parle pas de vous tous; je sais quels sont ceux que j\'ai choisis; mais il faut que ce passage de l\'Écriture s\'accomplisse: « Celui qui mange mon pain a levé son talon contre moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Je vous le dis dès à présent avant que cela ait eu lieu, afin que, lorsque cela aura eu lieu, vous croyiez que je le suis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'En vérité, en vérité je vous déclare que celui qui reçoit celui que j\'aurai envoyé me reçoit, et que celui qui me reçoit reçoit Celui qui m\'a envoyé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Après avoir ainsi parlé Jésus fut troublé en son esprit, et il porta témoignage et dit: « En vérité, en vérité je vous déclare que l\'un de vous me livrera! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Les disciples se regardaient les uns les autres, ne sachant duquel il parlait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'L\'un de ses disciples était couché sur le sein de Jésus, c\'était celui qu\'aimait Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Simon Pierre lui fait donc signe et lui dit: « Dis quel est celui dont il parle. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'L\'autre, qui était ainsi appuyé contre la poitrine de Jésus, lui dit: « Seigneur, lequel est-ce? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jésus donc répond: « C\'est celui pour lequel je tremperai le morceau et auquel je le donnerai. » Ayant donc trempé un morceau, il le prend et le donne à Judas fils de Simon Iscariote.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Et le morceau pris, Satan entra alors en lui. Jésus donc lui dit: « Fais au plus tôt ce que tu as à faire. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Aucun des convives ne comprit à propos de quoi il lui disait cela;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'car quelques-uns pensaient, parce que Judas tenait la bourse, que Jésus lui disait: « Achète ce dont nous avons besoin pour la fête, » ou bien qu\'il voulait qu\'il donnât quelque chose aux pauvres. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Ayant donc pris le morceau, Judas sortit immédiatement; or il faisait nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Lors donc qu\'il fut sorti, Jésus dit: « Maintenant le fils de l\'homme a été glorifié, et Dieu a été glorifié en lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'et Dieu le glorifiera en Lui-même, et Il le glorifiera bientôt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Petits enfants, je suis encore pour peu de temps avec vous; vous me chercherez, et, comme j\'ai dit aux Juifs: là où je vais, vous ne pouvez venir, je vous le dis aussi à vous maintenant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Je vous donne un commandement nouveau, qui est de vous aimer les uns les autres, comme je vous ai aimés pour que, vous aussi, vous vous aimiez les uns les autres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'c\'est par là que tous connaîtront que vous êtes mes disciples, si vous avez de l\'amour entre vous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Simon Pierre lui dit: « Seigneur, où vas-tu? » Jésus répondit: « Là où je vais, tu ne peux maintenant me suivre, mais tu me suivras plus tard. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Pierre lui dit: « Seigneur, pourquoi ne puis-je te suivre maintenant? Je sacrifierai ma vie pour toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jésus répond: « Tu sacrifieras ta vie pour moi! En vérité, en vérité je te le déclare, certainement le coq ne chantera pas avant que tu m\'aies renié trois fois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, '« Que votre cœur ne se trouble point: croyez en Dieu, croyez aussi en moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Dans la maison de mon Père il y a plusieurs demeures; sinon, vous dirais-je que je vais vous préparer une place?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Et si je vais et que je vous prépare une place, je reviendrai, et je vous prendrai auprès de moi, afin que là où je suis vous y soyez aussi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'et là où je vais, vous en savez le chemin. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Thomas lui dit: « Seigneur, nous ne savons où tu vas, comment en savons-nous le chemin? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jésus lui dit: « Je suis le chemin, et la vérité, et la vie; personne ne vient au Père que par moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'si vous m\'aviez connu, vous auriez aussi connu mon Père; dès maintenant vous Le connaissez et vous L\'avez vu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Philippe lui dit: « Seigneur, montre-nous le Père, et cela nous suffit. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jésus lui dit: « Depuis si longtemps je suis avec vous, et tu ne m\'as pas connu, Philippe! Celui qui m\'a vu a vu le Père; comment dis-tu: Montre-nous le Père?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Ne croiras-tu point que je suis dans le Père, et que le Père est en moi? Les paroles que je vous adresse, je ne les profère pas de mon chef; mais le Père qui demeure en moi fait Ses propres œuvres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'croyez-moi, quand je dis que je suis dans le Père et que le Père est en moi; sinon, croyez-moi à cause de Ses œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'En vérité, en vérité je vous le déclare, celui qui croit en moi, les œuvres que je fais, lui aussi les fera, et il en fera de plus grandes, parce que je m\'en vais vers le Père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'et, quoi que ce soit qu\'on demande en mon nom, je le ferai, afin que le Père soit glorifié dans le Fils;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'si vous me demandez quelque chose en mon nom, je le ferai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Si vous m\'aimez, vous garderez mes commandements,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'et moi je prierai le Père, et Il vous donnera un autre défenseur, pour être éternellement avec vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'l\'Esprit de vérité, que le monde ne peut recevoir, car il ne le voit point, ni ne le connaît point; pour vous, vous le connaissez, car il demeure près de vous, et il est en vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Je ne vous laisserai point orphelins, je viens à vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'encore un peu de temps, et le monde ne me voit plus, mais vous, vous me verrez, parce que je vis, et que vous aussi vous vivrez;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'en ce jour-là vous connaîtrez que je suis en mon Père, et que vous êtes en moi, et que je suis en vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Celui qui possède mes commandements et qui les garde, c\'est celui-là qui m\'aime; celui qui m\'aime sera aimé par mon Père, et moi aussi je l\'aimerai et je me manifesterai moi-même à lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Judas, non pas l\'Iscariote, lui dit: « Seigneur, que s\'est-il passé pour que tu doives te manifester à nous, et non pas au monde? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jésus lui répliqua: « Si quelqu\'un m\'aime il gardera ma parole, et mon Père l\'aimera, et nous viendrons vers lui et nous ferons un séjour chez lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'celui qui ne m\'aime pas ne garde point mes paroles; et la parole que vous entendez n\'est pas de moi, mais du Père qui m\'a envoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Je vous ai dit ces choses pendant que je demeurais près de vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'mais le défenseur, l\'Esprit Saint qu\'enverra le Père en mon nom, celui-là vous instruira de tout, et vous remettra en mémoire tout ce que je vous ai dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Pour moi, je vous laisse la paix, je vous donne ma paix; ce n\'est pas comme donne le monde, que je vous donne. Que votre cœur ne se trouble point et qu\'il ne s\'effarouche point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Vous avez entendu que je vous ai dit: Je m\'en vais, et, je viens à vous; si vous m\'aimiez, vous vous réjouiriez de ce que je vais vers le Père, parce que le Père est plus grand que moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Et maintenant, je vous l\'ai dit avant que cela ait eu lieu, afin que, lorsque cela aura eu lieu, vous croyiez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Je ne parlerai plus de beaucoup de choses avec vous, car le chef du monde vient, et il ne me peut rien,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'mais, afin que le monde sache que j\'aime le Père, et que j\'agis conformément à l\'ordre que le Père m\'a donné, levez-vous, sortons d\'ici. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, '« Je suis le véritable cep, et mon Père est le vigneron;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'tout sarment en moi qui ne porte point de fruit, Il le retranche, et tout sarment qui porte son fruit, Il le nettoie, afin qu\'il porte plus de fruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Déjà vous êtes nets, à cause de la parole que je vous ai adressée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Demeurez en moi, et moi en vous; comme le sarment ne peut porter du fruit de lui-même, s\'il ne demeure au cep, vous non plus, si vous ne demeurez en moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Moi, je suis le cep, vous, les sarments; celui qui demeure en moi et moi en lui, celui-là porte beaucoup de fruit; car, séparés de moi, vous ne pouvez pas faire la moindre chose.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Si quelqu\'un ne demeure pas en moi, il est jeté dehors comme le sarment, et il sèche; puis on les rassemble, et on les jette dans le feu, et ils brûlent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Si vous demeurez en moi, et que mes paroles demeurent en vous, demandez ce que vous voudrez, et cela vous sera accordé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Pour que mon Père soit glorifié, il faut que vous portiez beaucoup de fruit, et que vous deveniez mes disciples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Comme mon Père m\'a aimé, moi aussi je vous ai aimés; demeurez dans mon amour;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'si vous gardez mes commandements, vous demeurerez dans mon amour, comme moi j\'ai gardé les commandements du Père, et je demeure dans son amour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Je vous ai dit ces choses afin que ma joie soit en vous, et que votre joie soit complète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Voici quel est mon commandement: c\'est que vous vous aimiez les uns les autres comme je vous ai aimés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'il n\'est personne qui ait un plus grand amour que celui qui porte quelqu\'un à sacrifier sa propre vie pour ses amis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'vous êtes mes amis, si vous faites ce que je vous commande;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'je ne vous appelle plus esclaves, parce que l\'esclave ne sait pas ce que fait son seigneur; mais je vous ai appelés amis, parce que je vous ai fait connaître tout ce que j\'ai appris de mon Père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Ce n\'est pas vous qui m\'avez choisi, mais c\'est moi qui vous ai choisis, et qui vous ai établis, afin que vous alliez, et que vous portiez du fruit, et que votre fruit demeure, afin que tout ce que vous demanderez au Père en mon nom, Il vous le donne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Voici ce que je vous commande: c\'est que vous vous aimiez les uns les autres. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, '« Si le monde vous hait, sachez qu\'il m\'a haï avant vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'si vous étiez du monde, le monde aimerait ce qui est sien; mais comme vous n\'êtes pas du monde, mais que c\'est moi qui vous ai choisis du milieu du monde, voilà pourquoi le monde vous hait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Souvenez-vous de la parole que je vous ai dite: L\'esclave n\'est pas plus grand que son seigneur; s\'ils m\'ont poursuivi, ils vous poursuivront aussi; s\'ils ont gardé ma parole, ils garderont aussi la vôtre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'mais ils feront tout cela contre vous à cause de mon nom, parce qu\'ils ne connaissent pas Celui qui m\'a envoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Si je n\'étais pas venu, et si je ne leur avais pas parlé, ils n\'auraient pas de péché; mais maintenant ils n\'ont pas d\'excuse pour leur péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Celui qui me hait hait aussi mon Père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'si je n\'avais pas fait parmi eux les œuvres que nul autre n\'a faites, ils n\'auraient pas de péché; mais maintenant, quoiqu\'ils les aient vues, ils ont haï, et moi, et mon Père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Mais il fallait que fût accomplie la parole qui est écrite dans leur loi: « Ils m\'ont haï gratuitement. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Quand sera venu le défenseur que je vous enverrai d\'auprès du Père, l\'Esprit de la vérité qui sort d\'auprès du Père, c\'est lui qui témoignera en ma faveur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'mais, vous aussi, vous témoignerez, parce que vous êtes dès le commencement avec moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, '« Je vous ai dit ces choses, afin que vous ne trébuchiez pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'On vous mettra au ban de la synagogue; et même l\'heure vient où quiconque vous fera mourir s\'imaginera rendre un culte à Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'et ils agiront ainsi, parce qu\'ils n\'ont connu ni le Père, ni moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Mais je vous ai dit ces choses, afin que, lorsque l\'heure en sera venue, vous vous souveniez que je vous en ai parlé; si je ne vous en ai pas parlé dès le commencement, c\'est que j\'étais avec vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'mais maintenant je m\'en vais vers Celui qui m\'a envoyé, et nul de vous ne me demande: Où vas-tu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Mais parce que je vous ai dit ces choses, la tristesse a rempli votre cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Mais je vous dis la vérité: il vous convient que je parte; car si je ne pars pas, le défenseur ne viendra certainement pas à vous, mais si je m\'en vais, je vous l\'enverrai;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'et, quand il sera venu, il convaincra le monde de péché, de justice, et de jugement:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'de péché, parce qu\'ils ne croient pas en moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'de justice, parce que je m\'en vais vers le Père et que vous ne me verrez plus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'de jugement, parce que le chef de ce monde a été jugé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'J\'ai encore beaucoup de choses à vous dire, mais vous ne pouvez les porter maintenant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'mais quand celui-là, l\'Esprit de vérité, sera venu, il vous introduira dans la vérité tout entière; car il ne parlera pas de son chef, mais il parlera de tout ce qu\'il entendra et il vous annoncera les choses qui doivent arriver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'C\'est lui qui me glorifiera, car il prendra du mien et vous l\'annoncera;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'tout ce que le Père possède est mien; c\'est pourquoi j\'ai dit qu\'il prend du mien, et qu\'il vous l\'annoncera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Encore un peu de temps et vous ne me verrez plus, puis, derechef un peu de temps, et vous me verrez. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Quelques-uns de ses disciples se dirent donc les uns aux autres: « Que signifie ce qu\'il nous dit: Encore un peu de temps et vous ne me verrez pas, puis, derechef un peu de temps, et vous me verrez, et: Je m\'en vais vers mon Père? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Ils disaient donc: « Nous ne savons ce que signifie ce qu\'il dit: encore un peu de temps. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Jésus connut qu\'ils voulaient l\'interroger, et il leur dit: « Vous discutez entre vous sur ce que j\'ai dit: Encore un peu de temps, et vous ne me verrez pas, puis, derechef peu de temps, et vous me verrez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'En vérité, en vérité, je vous déclare que pour vous, vous pleurerez et vous vous lamenterez, mais que le monde se réjouira; vous serez dans la tristesse, mais votre tristesse se transformera en joie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'la femme, quand elle est près d\'enfanter, éprouve de la tristesse parce que son heure est venue, mais, quand elle a mis le petit enfant au monde, elle ne se souvient plus de sa tribulation, à cause de sa joie, parce qu\'un humain est né dans le monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Vous donc aussi, vous avez maintenant, il est vrai, de la tristesse, mais je vous reverrai et votre cœur se réjouira, et nul ne vous enlèvera votre joie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'et en ce jour-là vous ne m\'interrogerez sur rien. En vérité, en vérité, je vous le déclare, si vous demandez quelque chose au Père, Il vous le donnera en mon nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'jusques à présent vous n\'avez rien demandé en mon nom; demandez, et vous recevrez, afin que votre joie soit complète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Je vous ai parlé de ces choses par figures; l\'heure vient où je ne vous parlerai plus par figures, mais où je vous entretiendrai ouvertement du Père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'en ce jour-là vous demanderez en mon nom, et je ne vous dis pas que c\'est moi qui solliciterai le Père pour vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'car le Père Lui-même vous aime parce que vous m\'avez aimé, et que vous avez cru que je suis issu du Père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Je suis issu du Père et je suis venu dans le monde; je quitte derechef le monde et je vais vers le Père. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Ses disciples disent: « Voici, maintenant tu parles ouvertement et tu n\'emploies aucune figure;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'maintenant nous savons que tu sais tout, et que tu n\'as pas besoin que personne t\'interroge; c\'est pourquoi nous croyons que tu es issu de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Jésus leur répondit: « Maintenant vous croyez;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'voici, l\'heure vient, et elle est venue, où vous serez dispersés, chacun chez soi, et où vous me laisserez seul; toutefois je ne suis pas seul, car le Père est avec moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Je vous ai dit ces choses afin qu\'en moi vous ayez la paix; vous devez avoir des tribulations dans le monde, mais ayez courage, c\'est moi qui ai vaincu le monde. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Jésus proféra ces paroles, puis, après avoir levé les yeux vers le ciel, il dit: « Père, l\'heure est venue! Glorifie Ton Fils, afin que Ton fils Te glorifie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'selon que Tu lui as donné autorité sur toute chair, afin qu\'à tous ceux que Tu lui as donnés, il donne la vie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Or voici ce qu\'est la vie éternelle, c\'est qu\'ils Te connaissent comme le seul véritable Dieu, et, comme Christ, Jésus que Tu as envoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Pour moi, je T\'ai glorifié sur la terre, en achevant l\'œuvre que Tu m\'as donnée à faire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'et maintenant, à Ton tour, glorifie-moi, Père, auprès de Toi, par la gloire que je possédais auprès de Toi avant que le monde existât.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'J\'ai manifesté Ton nom aux hommes que Tu m\'as donnés du milieu du monde; ils étaient tiens, et Tu me les as donnés, et ils ont gardé Ta parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Maintenant ils ont connu que tout ce que Tu m\'as donné vient de Toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'car je leur ai donné les paroles que Tu m\'as données, et ils les ont reçues, et ils ont vraiment connu que je suis issu d\'auprès de Toi, et ils ont cru que c\'est Toi qui m\'as envoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'C\'est moi qui prie pour eux; je ne prie point pour le monde, mais pour ceux que Tu m\'as donnés, parce qu\'ils sont tiens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, '(et tout ce qui est mien est tien, et ce qui est tien est mien), et que j\'ai été glorifié en eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Et je ne suis plus dans le monde, et eux sont dans le monde, et moi je vais vers Toi. Père saint! maintiens-les fidèles à Ton nom que Tu m\'as donné, afin qu\'ils soient un comme nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Lorsque j\'étais avec eux, je les maintenais fidèles à Ton nom que Tu m\'as donné, et je les ai gardés, et nul d\'entre eux ne s\'est perdu, sauf le fils de perdition, afin que l\'Écriture fût accomplie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Mais maintenant je vais à Toi, et je dis ces choses dans le monde, afin qu\'ils possèdent en eux-mêmes ma joie complète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'C\'est moi qui leur ai donné Ta parole, et le monde les a haïs, parce qu\'ils ne sont pas du monde, comme moi-même je ne suis pas du monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Je ne prie point pour que Tu les enlèves du monde, mais pour que Tu les garantisses du malin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Ils ne sont pas du monde, comme moi-même je ne suis pas du monde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'consacre-les à la vérité; Ta parole est la vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'De même que Tu m\'as envoyé dans le monde, moi, de mon côté, je les ai envoyés dans le monde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'et c\'est pour eux que je me consacre moi-même, afin qu\'eux aussi soient consacrés à la vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Mais ce n\'est pas seulement pour ceux-là que je prie, mais encore pour ceux qui, par leur parole, croient en moi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'afin que tous soient un, comme Toi, Père, Tu es en moi, et moi en Toi, afin qu\'eux aussi soient en nous, pour que le monde croie que c\'est Toi qui m\'as envoyé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Pour moi, je leur ai donné la gloire que Tu m\'as donnée, afin qu\'ils soient un comme nous sommes un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'je suis en eux, et Tu es en moi, afin qu\'ils arrivent à une parfaite unité, pour que le monde connaisse que c\'est Toi qui m\'as envoyé, et que Tu les a aimés comme Tu m\'as aimé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Père, ceux que Tu m\'as donnés, je veux que là où je suis eux aussi y soient avec moi, afin qu\'ils voient ma gloire, que Tu m\'as donnée parce que Tu m\'as aimé avant la création du monde,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Père juste! Et le monde ne T\'a pas connu, mais moi je T\'ai connu, et ceux-ci ont connu que c\'est Toi qui m\'as envoyé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'et je leur ai fait connaître Ton nom, et je le leur ferai connaître, afin que l\'amour dont Tu m\'as aimé soit en eux, et moi en eux! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Après avoir dit ces choses Jésus sortit avec ses disciples pour se rendre, au delà du torrent des cèdres, en un lieu où se trouvait un jardin dans lequel il entra, lui et ses disciples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Or Judas, qui le livrait, connaissait aussi l\'endroit, parce que souvent Jésus s\'y était réuni à ses disciples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Judas donc, ayant pris la cohorte et des satellites que lui avaient donnés les grands prêtres et les pharisiens, arrive en ce lieu avec des torches, des lanternes et des armes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Jésus donc, qui savait tout ce qui allait lui arriver, sortit et leur dit: « Qui cherchez-vous? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Ils lui répondirent: « Jésus le Nazoréen. » Il leur dit: « C\'est moi qui suis Jésus. » Or Judas qui le livrait était aussi avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Lors donc qu\'il leur eut dit: « C\'est moi qui le suis, » ils reculèrent en arrière et tombèrent par terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Il leur demanda donc derechef: « Qui cherchez-vous? » Et ils dirent: « Jésus le Nazoréen. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jésus répondit: « Je vous ai dit que c\'est moi qui le suis, si donc vous me cherchez, laissez aller ceux-ci. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Afin que fût accomplie la parole qu\'il avait dite: ceux que tu m\'as donnés, je n\'en ai perdu aucun. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Simon Pierre qui avait une épée la tira donc et frappa l\'esclave du grand prêtre et lui coupa l\'oreille droite; or le nom de l\'esclave était Malchus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Jésus dit donc à Pierre: « Remets l\'épée dans le fourreau; la coupe que le Père m\'a donnée, ne la boirai-je pas? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'La cohorte, et le commandant, et les satellites des Juifs se saisirent donc de Jésus et le garrottèrent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'et ils le conduisirent d\'abord chez Annas; il était en effet beau-père de Caïaphas, qui était grand prêtre cette année-là. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Or Caïaphas était celui qui avait donné aux Juifs le conseil: il convient qu\'un seul homme meure pour le peuple. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Cependant Simon Pierre suivait Jésus, avec un autre disciple; or ce disciple-ci était connu du grand prêtre, et il entra avec Jésus dans la cour du grand prêtre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'mais Pierre se tenait dehors près de la porte. L\'autre disciple, celui qui était connu du grand prêtre, sortit donc, et parla à la portière, et il fit entrer Pierre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'La servante qui faisait office de portière dit donc à Pierre: « N\'es-tu pas, toi aussi, des disciples de cet homme-là? » Il lui dit: « Je n\'en suis point. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Cependant les esclaves et les satellites se tenaient auprès d\'un brasier qu\'ils avaient allumé, car il faisait froid, et ils se chauffaient; or Pierre se tenait aussi avec eux et se chauffait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Le grand prêtre interrogea donc Jésus sur ses disciples et sur sa doctrine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jésus lui répondit: « Pour moi, c\'est publiquement que j\'ai parlé au monde; j\'ai constamment enseigné dans une synagogue et dans le temple où tous les Juifs se rassemblent, et je n\'ai rien dit en cachette.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Pourquoi m\'interroges-tu? Interroge ceux qui ont entendu ce dont je leur ai parlé; voici, ce sont eux qui savent ce que j\'ai dit. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Or quand il eut dit cela, un des satellites qui se trouvait là donna un soufflet à Jésus, en disant: « C\'est ainsi que tu réponds au grand prêtre! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jésus lui répondit: « Si j\'ai mal parlé, porte témoignage du mal que j\'ai dit, mais si c\'est bien, pourquoi me frappes-tu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Annas l\'envoya donc garrotté à Caïaphas le grand prêtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Cependant Simon Pierre était à se chauffer; ils lui dirent donc: « N\'es-tu pas, toi aussi, de ses disciples? » Il le nia et dit: « Je n\'en suis point. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Un des esclaves du grand prêtre, qui était parent de celui dont Pierre avait coupé l\'oreille, dit: « Est-ce que je ne t\'ai pas vu dans le jardin avec lui? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Pierre donc nia derechef, et aussitôt un coq chanta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Ils conduisent donc Jésus de chez Caïaphas au prétoire; or c\'était le matin, et eux-mêmes n\'entrèrent pas dans le prétoire, afin de ne pas se souiller, et de pouvoir manger la pâque.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Pilate donc sortit pour se rendre auprès d\'eux et dit: « Quelle accusation portez-vous contre cet homme? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Ils lui répliquèrent: « Si celui-ci n\'était pas un malfaiteur, nous ne te l\'aurions pas livré. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Pilate leur dit donc: « Prenez-le vous-mêmes, et jugez-le selon votre loi. » Les Juifs lui dirent: « Il ne nous est pas permis de mettre personne à mort. » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Afin que fût accomplie la parole par laquelle Jésus avait indiqué de quelle mort il devait mourir. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Pilate entra donc derechef dans le prétoire, et il appela Jésus, et lui dit: « Es-tu le roi des Juifs? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jésus répondit: « Est-ce de toi-même que tu dis cela, ou bien d\'autres te l\'ont-ils dit de moi? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilate répondit: « Est-ce que je suis Juif? C\'est ta nation et les grands prêtres qui t\'ont livré à moi; qu\'as-tu fait? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jésus répondit: « Mon royaume n\'est pas de ce monde; si mon royaume était de ce monde, mes satellites auraient combattu afin que je ne fusse pas livré aux Juifs; mais maintenant mon royaume n\'est pas d\'ici. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Pilate lui dit donc: « Tu es donc roi? » Jésus répondit: « Tu le dis; en effet je suis roi. C\'est pour rendre témoignage à la vérité que je suis né et que je suis venu dans le monde; quiconque est de la vérité écoute ma voix. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Pilate lui dit: « Qu\'est-ce que la vérité? » Et en disant cela il sortit derechef pour se rendre auprès des Juifs, et il leur dit: « Pour moi, je ne trouve en lui aucun crime;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'mais c\'est votre coutume que je vous relâche quelqu\'un à Pâque, voulez-vous donc que je vous relâche le roi des Juifs? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Ils s\'écrièrent donc derechef: « Non pas celui-ci, mais Barabbas! » Or Barabbas était un brigand.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Alors donc Pilate fit prendre et fustiger Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Et les soldats, ayant tressé une couronne avec des épines, la posèrent sur sa tête, et ils le revêtirent d\'un manteau de pourpre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'et ils venaient vers lui et disaient: « Salut, roi des Juifs! » Et ils lui donnèrent des soufflets.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Et Pilate sortit derechef et leur dit: « Voici, je vous l\'amène, afin que vous sachiez que je ne trouve en lui aucun crime. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Jésus sortit donc, portant la couronne d\'épines et le manteau de pourpre. Et il leur dit: « Voici l\'homme. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Lors donc que les grands prêtres et leurs satellites le virent, ils s\'écrièrent: « Crucifie, crucifie! » Pilate leur dit: « Prenez-le vous-mêmes, et crucifiez-le; car pour moi je ne trouve pas de crime en lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Les Juifs lui répondirent: « Nous avons une loi, et selon la loi il doit mourir, parce qu\'il s\'est fait fils de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Lors donc que Pilate eut ouï cette parole, il craignit davantage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'et il rentra dans le prétoire et dit à Jésus: « D\'où es-tu? » Mais Jésus-ne lui fit pas de réponse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Pilate donc lui dit: « Tu ne me parles pas! Ne sais-tu pas que j\'ai l\'autorité de te relâcher, et que j\'ai l\'autorité de te crucifier? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jésus lui répondit: « Tu n\'aurais nulle autorité sur moi, si elle ne t\'avait été donnée d\'en haut; c\'est pourquoi celui qui m\'a livré à toi commet un plus grand péché. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Dès lors Pilate cherchait à le relâcher; mais les Juifs s\'écrièrent: « Si tu relâches celui-ci, tu n\'es pas ami de l\'empereur; quiconque se fait roi se déclare contre l\'empereur! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Pilate donc, quand il eut ouï ces paroles, fit sortir Jésus, et s\'assit sur un tribunal dans un endroit appelé Pavé, mais en hébreu Gabbatha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Or c\'était la préparation de la pâque; c\'était environ la sixième heure, et il dit aux Juifs: « Voilà votre roi! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Ceux-ci s\'écrièrent donc: « Fais-le mourir! Fais-le mourir! Crucifie-le! » Pilate leur dit: « Crucifierai-je votre roi? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Les grands prêtres lui répondirent: « Nous n\'avons d\'autre roi que l\'empereur. » Alors donc il le leur livra pour être crucifié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'et, portant lui-même sa croix, il sortit pour se rendre à l\'endroit appelé du crâne, qui en hébreu est appelé Golgoth,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'où ils le crucifièrent, et avec lui deux autres, de droite et de gauche, et Jésus au milieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Cependant Pilate composa aussi une inscription et la fit placer sur la croix; or elle était ainsi conçue: Jésus le nazoréen, le roi des juifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Plusieurs des Juifs lurent donc cette inscription, parce que l\'endroit où fut crucifié Jésus était près de la ville, et qu\'elle était écrite en hébreu, en latin et en grec.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Les grands prêtres des Juifs disaient donc à Pilate: « N\'écris pas: Le roi des Juifs, mais qu\'il a dit: Je suis roi des Juifs. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilate répondit: « Ce que j\'ai écris, je l\'ai écrit. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Les soldats donc, lorsqu\'ils eurent crucifié Jésus, prirent ses vêtements, et ils en firent quatre parts, une part pour chaque soldat; ils prirent aussi la tunique. Or la tunique était sans couture, entièrement tissée du haut en bas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'ils se dirent donc entre eux: « Ne la déchirons pas, mais tirons-la au sort, à qui l\'aura. » — Afin que fût accompli le passage de l\'Écriture: « Ils se sont partagé mes vêtements, et ils ont tiré mon habit au sort. » — Les soldats firent donc ces choses,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'tandis que, près de la croix de Jésus, se tenaient sa mère et la sœur de sa mère, Marie femme de Clopas et Marie la Magdalène.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Jésus donc, voyant sa mère, et près d\'elle le disciple qu\'il aimait, dit à sa mère: « Femme, voici ton fils. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Ensuite il dit au disciple: « Voici ta mère. » Et dès ce moment le disciple la prit chez lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Après cela Jésus, qui savait que tout était déjà accompli, — afin que l\'Écriture fût accomplie, — dit: « J\'ai soif. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Il y avait là un vase plein de vinaigre; on attacha donc une éponge pleine de ce vinaigre à une branche d\'hysope et on l\'approcha de sa bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Lors donc que Jésus eut pris le vinaigre, il dit: « C\'est accompli, » et ayant penché la tête, il rendit l\'esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Les Juifs donc (parce que c\'était la préparation), afin que les corps ne demeurassent pas sur la croix pendant le sabbat (car le jour de ce sabbat était grand), les Juifs demandèrent à Pilate qu\'on leur rompît les jambes et qu\'on les enlevât.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Les soldats vinrent donc, et rompirent les jambes du premier, et celles de l\'autre crucifié avec lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'mais en venant à Jésus, comme ils virent qu\'il était déjà mort, ils ne lui rompirent pas les jambes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'mais l\'un des soldats lui perça le flanc avec une lance, et il en sortit aussitôt du sang et de l\'eau. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Et c\'est celui qui l\'a vu qui en a porté témoignage, et son témoignage est véritable, et il sait qu\'il dit vrai, afin que vous croyiez;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'car cela est advenu afin que ce passage de l\'Écriture fût accompli: « Aucun de ses os ne sera brisé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Et un autre passage de l\'Écriture dit encore: « Ils verront celui qu\'ils ont transpercé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Or, après cela, Joseph d\'Arimathée, qui était disciple de Jésus, mais en cachette par crainte des Juifs, demanda à Pilate de pouvoir enlever le corps de Jésus. Et Pilate le permit. Il vint donc et enleva son corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Or Nicodème, qui était venu vers lui de nuit la première fois, vint aussi portant un rouleau de myrrhe et d\'aloès, pesant environ cent livres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Ils prirent donc le corps de Jésus, et l\'enveloppèrent de bandelettes avec les parfums, selon la coutume suivie par les Juifs pour la sépulture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Or il y avait dans l\'endroit où il avait été crucifié un jardin, et dans le jardin un sépulcre neuf, dans lequel personne n\'avait encore été déposé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'ce fut donc là, à cause de la préparation des Juifs, parce que le sépulcre était proche, qu\'ils déposèrent Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Or le premier jour de la semaine, Marie la Magdalène vient de bon matin, pendant qu\'il faisait encore obscur, vers le sépulcre, et elle voit la pierre enlevée du sépulcre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Elle court donc et vient vers Simon Pierre et vers l\'autre disciple que Jésus aimait, et elle leur dit: « Ils ont enlevé le Seigneur du sépulcre, et nous ne savons où ils l\'ont mis. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Pierre sortit donc, ainsi que l\'autre disciple; et ils se rendaient vers le sépulcre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'or ils couraient tous deux ensemble, et l\'autre disciple courut plus vite que Pierre et arriva le premier au sépulcre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'et s\'étant baissé il voit les bandelettes par terre; cependant il n\'entra pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Arrive donc aussi Simon Pierre qui le suivait, et il entra dans le sépulcre. Et il voit les bandelettes par terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'et le linge qui avait été sur sa tête, non point par terre avec les bandelettes, mais roulé à part dans un coin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Alors donc entra aussi l\'autre disciple qui, le premier, était arrivé au sépulcre, et il vit et il crut;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'car ils n\'avaient pas encore compris que, d\'après l\'Écriture, il fallait qu\'il ressuscitât des morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Les disciples s\'en retournèrent donc chez eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Mais Marie se tenait dehors près du sépulcre en pleurant; comme donc elle pleurait, elle se baissa pour regarder dans le sépulcre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'et elle voit deux anges vêtus de blanc, assis, l\'un à la tête, et l\'autre aux pieds, là où avait été couché le corps de Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'et ils lui disent: « Femme, pourquoi pleures-tu? » Et elle leur dit: « Parce qu\'ils ont enlevé mon Seigneur, et que je ne sais où ils l\'ont mis. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Après avoir dit cela elle se retourna en arrière, et elle voit Jésus debout, et elle ne savait pas que ce fût Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Jésus lui dit: « Femme, pourquoi pleures-tu? Qui cherches-tu? » Elle, s\'imaginant que c\'est le jardinier, lui dit: « Seigneur, si c\'est toi qui l\'as emporté, dis-moi où tu l\'as mis, et moi je l\'irai prendre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jésus lui dit: « Marie! » S\'étant retournée, elle lui dit en hébreu: « Rabbouni », ce qui signifie, Maître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Jésus lui dit: « Ne me touche pas; car je ne suis pas encore monté vers mon Père; mais va vers mes frères et dis-leur: Je monte vers mon Père et votre Père, et vers mon Dieu et votre Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Marie la Magdalène vient annoncer aux disciples qu\'elle a vu le Seigneur, et qu\'il lui a dit ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Le soir donc de ce premier jour de la semaine, et les portes de l\'endroit où étaient les disciples étant closes par crainte des Juifs, Jésus vint et se tint au milieu d\'eux, et il leur dit: « Paix pour vous! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Et après avoir dit cela, il leur montra et ses mains et son flanc. Les disciples furent donc dans la joie en voyant le Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Jésus leur dit donc derechef: « Paix pour vous! Comme le Père m\'a envoyé, moi aussi je vous envoie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Et après avoir dit cela il souffla et leur dit: « Recevez l\'esprit saint;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'à tous ceux dont vous aurez pardonné les péchés, ils leur sont pardonnés; à tous ceux dont vous les retenez, ils sont retenus. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Cependant Thomas, l\'un des Douze, celui qui est appelé Didymos, n\'était pas avec eux quand Jésus vint;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'les autres disciples lui disaient donc: « Nous avons vu le Seigneur. » Mais il leur dit: « Si je ne vois dans ses mains la marque des clous, et si je ne mets mon doigt dans la marque des clous, et si je ne mets ma main dans son flanc, je ne croirai point. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Et huit jours après, ses disciples étaient de nouveau renfermés, et Thomas avec eux. Jésus vient, les portes étant closes, et il se tint au milieu d\'eux, et dit: « Paix pour vous! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Ensuite il dit à Thomas: « Avance ton doigt ici, et regarde mes mains, et avance ta main, et mets-la dans mon flanc, et ne deviens pas incrédule, mais croyant. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Thomas lui répliqua: « Mon Seigneur, et mon Dieu! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jésus lui dit: « Parce que tu m\'as vu, tu as cru; heureux ceux qui n\'ont pas vu, et qui ont cru! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Jésus fit donc, en présence des disciples, encore beaucoup d\'autres miracles, qui n\'ont pas été écrits dans ce livre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'mais ceux-ci ont été écrits afin que vous croyiez que Jésus est le Christ, le fils de Dieu, et afin qu\'en croyant vous ayez la vie en son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Après cela Jésus se manifesta lui-même aux disciples près de la mer de Tibériade; or voici comment il se manifesta:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Ensemble étaient Simon Pierre, et Thomas qui est appelé Didymos, et Nathanaël de Cana en Galilée, et les fils de Zébédée, et deux autres de ses disciples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Simon Pierre leur dit: « Je vais pêcher. » Ils lui disent: « Nous allons aussi avec toi. » Ils sortirent et montèrent dans la barque, et cette nuit-là ils ne prirent rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Or, quand le matin fut venu, Jésus se trouva debout sur le rivage; cependant les disciples ne savaient pas que ce fût Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Jésus leur dit donc: « Enfants! N\'avez-vous rien à manger? » Ils lui répondirent: « Non. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Mais il leur dit: « Jetez le filet sur la droite de la barque, et vous trouverez. » Ils le jetèrent donc, et ils ne purent plus le retirer à cause de la quantité des poissons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Le disciple que Jésus aimait dit donc à Pierre: « C\'est le Seigneur. » Simon Pierre, ayant donc appris que c\'était le Seigneur, ceignit son sarrau, car il était nu, et il se jeta dans la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Mais les autres disciples vinrent avec la barque, (car ils n\'étaient éloignés de la terre que d\'environ deux cents coudées), en entraînant le filet des poissons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Lors donc qu\'ils furent descendus à terre, ils voient un brasier établi, et du poisson posé dessus, et du pain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Jésus leur dit: « Apportez quelques-uns des poissons que vous venez de prendre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Simon Pierre monta donc, et il tira à terre le filet plein de cent cinquante-trois gros poissons; et, malgré ce grand nombre, le filet ne se déchira pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Jésus leur dit: « Venez, faites collation. » Aucun des disciples n\'osait lui demander: « Qui es-tu? » sachant bien que c\'était le Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Jésus vient et prend le pain et le leur donne, et il fait de même des poissons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Ce fut là la troisième fois que Jésus apparut aux disciples, depuis qu\'il fut ressuscité des morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Lors donc qu\'ils eurent fait collation, Jésus dit à Simon Pierre: « Simon, fils de Jean, m\'aimes-tu plus que ceux-ci? Il lui dit: « Oui, Seigneur; tu sais que je t\'aime. » Il lui dit: « Pais mes agneaux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Il lui redit une seconde fois: « Simon, fils de Jean, m\'aimes-tu? » Il lui dit: « Oui, Seigneur, tu sais que je t\'aime. » Il lui dit: « Fais paître mes brebis. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Il lui dit pour la troisième fois: « Simon, fils de Jean, m\'aimes-tu? » Pierre fut attristé de ce qu\'il lui avait dit pour la troisième fois: « M\'aimes-tu? » et il dit: « Seigneur, tu sais toutes choses, tu connais que je t\'aime. » Jésus lui dit: « Pais mes brebis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'En vérité, en vérité je te le déclare, lorsque tu étais plus jeune, tu te ceignais toi-même, et tu allais où tu voulais; mais quand tu seras devenu vieux, tu étendras les mains, et un autre te ceindra et te portera là où tu ne veux pas. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Or il dit cela pour indiquer par quel genre de mort il glorifierait Dieu, et après avoir dit cela, il dit: « Suis-moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Pierre, s\'étant retourné, se voit suivi par le disciple que Jésus aimait, et qui, pendant le repas, s\'était appuyé contre sa poitrine, et qui avait dit: « Seigneur, quel est celui qui doit te livrer? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Pierre donc l\'ayant vu dit à Jésus: « Seigneur, mais celui-ci, qu\'en sera-t-il? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jésus lui dit: « Si je veux qu\'il demeure jusques à ce que je vienne, que t\'importe? Quant à toi, suis-moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Le bruit se répandit donc parmi les frères, que ce disciple ne devait pas mourir; mais Jésus ne lui dit pas: « Il ne doit point mourir, » mais: « Si je veux qu\'il demeure jusques à ce que je vienne, que t\'importe? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'C\'est lui qui est le disciple qui atteste ces choses, et qui a aussi écrit ces choses, et nous savons que son témoignage est véridique;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'mais il y a encore beaucoup d\'autres choses qu\'a faites Jésus, lesquelles, si on les écrivait en détail, je ne pense pas que le monde même pût contenir les livres où elles seraient écrites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'J\'ai consigné dans mon premier écrit, ô Théophile, tout ce que Jésus avait commencé de faire et d\'enseigner');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'jusques au jour où, après avoir donné par l\'esprit saint ses ordres aux apôtres qu\'il avait choisis, il fut enlevé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Déjà, après sa passion, il leur avait fait voir par plusieurs indices qu\'il était vivant, leur apparaissant pendant quarante jours, et leur parlant de ce qui concerne le royaume de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Et, pendant qu\'il se trouvait avec eux, il leur ordonna de ne point s\'éloigner de Jérusalem, mais d\'y attendre la promesse du Père, « dont vous m\'avez entendu parler;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'car, si Jean a baptisé avec de l\'eau, pour vous, vous serez baptisés avec l\'esprit saint, dans peu de jours d\'ici. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Se trouvant donc réunis, ils l\'interrogèrent en disant: « Seigneur, est-ce en ce temps-là que tu dois rétablir le royaume d\'Israël? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Il leur dit: « Il ne vous appartient pas de connaître les temps ou les époques que le Père a fixés de Sa propre autorité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'mais, quand le saint esprit sera venu sur vous, vous serez revêtus de puissance, et vous serez mes témoins, soit à Jérusalem, soit dans la Judée et la Samarie, et jusques à l\'extrémité de la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Et, après avoir ainsi parlé, il fut enlevé pendant qu\'eux-mêmes regardaient, et une nuée le déroba à leurs yeux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'et, comme leurs regards étaient fixés sur le ciel pendant qu\'il s\'éloignait, voici, deux hommes vêtus d\'habits blancs s\'étaient approchés d\'eux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'et leur dirent: « Galiléens, pourquoi vous tenez-vous là à regarder le ciel? Ce Jésus, qui vient d\'être enlevé du milieu de vous dans le ciel, reviendra de la même manière dont vous l\'avez vu monter au ciel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Alors ils retournèrent à Jérusalem en quittant la montagne appelée le Bois d\'oliviers, qui est près de Jérusalem, à la distance d\'un chemin de sabbat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Et, lorsqu\'ils furent entrés, ils montèrent dans la chambre haute où ils demeuraient, à savoir Pierre et Jean et Jacques et André, Philippe et Thomas, Barthélemi et Matthieu, Jacques fils d\'Alphée et Simon le zélote et Judas fils de Jacques.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Tous ceux-là étaient ensemble assidus à la prière, avec des femmes et Marie la mère de Jésus, et avec ses frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Et ce fut en ces jours-là que Pierre, s\'étant levé au milieu des frères, dit (et le nombre des personnes réunies était d\'environ cent vingt):');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, '« Frères, il fallait que fût accomplie la parole de l\'Écriture qu\'a d\'avance proférée l\'esprit saint par la bouche de David, relativement à Judas qui a été le guide de ceux qui ont saisi Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'car il était compté parmi nous, et il a eu sa part de ce ministère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'c\'est lui qui a acheté un champ avec le prix de son crime; puis, étant tombé sur le visage, il a éclaté par le milieu et toutes ses entrailles se sont répandues;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'ceci a été su de tous les habitants de Jérusalem, en sorte qu\'on a appelé ce champ dans leur idiome Akeldamach, ce qui signifie champ du sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'En effet il est écrit dans le livre des Psaumes: « Que son gîte devienne désert, et qu\'il n\'y ait personne qui l\'habite! et: « Qu\'un autre reçoive sa charge de surveillant! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Il faut donc que l\'un des hommes qui ont été avec nous pendant tout le temps où le seigneur Jésus a été en rapport avec nous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'à partir du baptême de Jean jusques au jour où il a été enlevé du milieu de nous, devienne avec nous un témoin de sa résurrection. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Et ils en proposèrent deux: Josès appelé Barsabbas, qui était surnommé Justus, et Matthias;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'et ils firent cette prière: « O Toi, Seigneur, qui connais tous les cœurs, montre-nous lequel de ces deux hommes Tu as choisi');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'pour occuper, dans ce ministère et cet apostolat, la place dont Judas est sorti pour aller dans la place qui lui appartient. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Et ils leur donnèrent des bulletins, et le sort tomba sur Matthias, et il fut agrégé aux onze apôtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Et, quand vint le jour de la Pentecôte, ils étaient tous ensemble dans le même lieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'et il survint tout à coup du ciel un bruit semblable à celui d\'un violent coup de vent, et il remplit toute la maison où ils étaient assis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'et des langues séparées, qui semblaient de feu, leur apparurent, et il s\'en posa une sur chacun d\'eux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'et ils furent tous remplis d\'esprit saint, et ils commencèrent à parler en d\'autres langues, selon que l\'esprit leur donnait de s\'exprimer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Or, se trouvaient établis à Jérusalem des Juifs pieux venus de chez toutes les nations qui habitent sous le ciel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'et, quand ce bruit eut eu lieu, la multitude accourut, et elle fut confondue parce que chacun les entendait parler dans son propre idiome.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Or tous étaient stupéfaits et ils disaient dans leur étonnement: « Voici, tous ces gens-là qui parlent ne sont-ils pas des Galiléens?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Et comment chacun de nous entend-il dans son idiome natal —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Parthes et Mèdes et Élamites, et ceux qui habitent la Mésopotamie, la Judée et la Cappadoce, le Pont et l\'Asie, la Phrygie et la Pamphylie, l\'Egypte');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'et les régions de la Libye voisine de Cyrène, et les voyageurs venus de Rome, Juifs et prosélytes, Crétois et Arabes, —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'comment les entendons-nous parler dans nos propres langues des hauts faits de Dieu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Or tous étaient stupéfaits et incertains, se disant l\'un à l\'autre: « Que veut dire ceci? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'tandis que d\'autres raillaient et disaient: « C\'est qu\'ils sont pleins de vin doux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Mais Pierre s\'étant avancé avec les onze éleva la voix et leur dit: « Juifs, et vous tous qui habitez Jérusalem, comprenez bien ceci et prêtez l\'oreille à mes paroles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'car ces gens ne sont pas ivres, comme vous le supposez, puisque c\'est la troisième heure du jour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'mais ce qui se passe est ce qui a été prédit par l\'entremise du prophète Joël:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '« Et il arrivera après cela, dit Dieu, que Je répandrai de Mon esprit sur toute chair, et vos fils et vos filles prophétiseront, et vos jeunes gens verront des visions, et vos vieillards auront des songes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'et certes en ces jours-là Je répandrai de Mon esprit sur Mes serviteurs et sur Mes servantes, et ils prophétiseront;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'et J\'opérerai des prodiges en haut dans le ciel, et des miracles en bas sur la terre, du sang et du feu et de la vapeur de fumée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'le soleil sera changé en ténèbres et la lune en sang, avant qu\'arrive la grande et éclatante journée du Seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'et il arrivera que quiconque aura invoqué le nom du Seigneur sera sauvé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Israélites, écoutez mes paroles que voici: Jésus le Nazoréen, cet homme accrédité de Dieu auprès de vous par des miracles, des prodiges et des signes que Dieu a opérés par son moyen au milieu de vous, comme vous le savez vous-mêmes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'c\'est lui que vous avez fait périr en le crucifiant par la main des impies, après qu\'il eut été livré selon le dessein arrêté et la prescience de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'et c\'est lui que Dieu a ressuscité en dissipant les douleurs de la mort, en la puissance de laquelle il n\'était, en effet, pas possible qu\'il fût retenu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'car David dit à propos de lui: « J\'ai toujours vu le Seigneur devant moi, parce qu\'il se tient à ma droite, afin que je ne sois point ébranlé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'c\'est pourquoi mon cœur a été dans la joie et ma langue dans l\'allégresse; ma chair aussi se reposera encore avec espérance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'parce que Tu n\'abandonneras pas mon âme dans le séjour des morts et que Tu ne permettras point que celui qui T\'est consacré voie la corruption.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Tu m\'as fais connaître les routes de la vie, Tu me combleras de joie par Ta présence. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Frères, il est permis de vous dire avec assurance, quant au patriarche David, qu\'il est mort et qu\'il a été enterré; aussi bien son sépulcre subsiste-t-il parmi nous jusques à ce jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Étant donc prophète, et sachant que Dieu lui avait juré avec serment qu\'il ferait asseoir un fruit de ses reins sur son trône,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'c\'est par prévision qu\'il a parlé de la résurrection du Christ, car celui-ci n\'a pas été abandonné dans le séjour des morts et sa chair n\'a pas vu la corruption;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'c\'est ce Jésus que Dieu a ressuscité, ce dont, nous tous, nous sommes témoins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Ayant donc été élevé à la droite de Dieu, et ayant reçu du Père l\'esprit saint qui avait été promis, il a répandu celui-ci comme vous-mêmes aussi vous le voyez et vous l\'entendez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'David, en effet, n\'est point monté dans les cieux, mais il dit lui-même: « Le Seigneur a dit à mon seigneur: Assieds-toi à Ma droite,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'jusqu\'à ce que J\'aie fait de tes ennemis un marchepied pour tes pieds. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Que toute la maison d\'Israël sache donc avec certitude que Dieu l\'a fait et seigneur, et Christ, ce Jésus que vous, vous avez crucifié. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Ce qu\'ayant ouï, ils furent piqués au cœur, et ils dirent à Pierre et aux autres apôtres: « Frères, qu\'avons-nous à faire? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Sur quoi Pierre s\'adressant à eux: « Repentez-vous, et que chacun de vous se fasse baptiser au nom de Jésus-Christ, pour la rémission de ses péchés, et vous recevrez le don du saint esprit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'car c\'est pour vous qu\'est la promesse, et pour vos enfants, et pour tous ceux au loin qu\'aura appelés à Lui le Seigneur notre Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Et il rendait témoignage par plusieurs autres paroles, et il les exhortait en disant: « Sauvez-vous en quittant cette génération pervertie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Ceux donc qui eurent à gré ses paroles se firent baptiser, et il y eut ce jour-là environ trois mille personnes qui furent agrégées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Cependant ils étaient assidus à l\'enseignement des apôtres et aux réunions communes, à la fraction du pain et aux prières.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Or chacun était dans la crainte; mais il se faisait beaucoup de prodiges et de miracles par les apôtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Et tous ceux qui avaient cru avaient en un même lieu toutes choses en commun,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'et ils vendaient leurs propriétés et leurs biens, et ils les distribuaient à tous selon les besoins de chacun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Tous les jours ils étaient ensemble assidus dans le temple, et, rompant le pain dans les maisons, ils prenaient leur nourriture avec allégresse et simplicité de cœur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'louant Dieu, et trouvant faveur auprès de tout le peuple. Cependant le Seigneur agrégeait journellement au même corps ceux qui étaient sauvés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Or Pierre et Jean montaient au temple pour la prière de la neuvième heure,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'et l\'on transportait un homme qui était boiteux de naissance et que l\'on plaçait chaque jour près de la porte du temple dite la Belle, pour demander l\'aumône à ceux qui entraient dans le temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Cet homme, ayant vu Pierre et Jean sur le point d\'entrer dans le temple, s\'adressa à eux pour recevoir une aumône.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Mais Pierre, après avoir fixé sur lui ses regards, ainsi que Jean, dit: « Regarde-nous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Et il les regardait attentivement s\'attendant à recevoir d\'eux quelque chose.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Mais Pierre dit: « Je n\'ai ni argent ni or, mais ce que j\'ai, je te le donne: au nom de Jésus-Christ le Nazoréen, marche! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Et l\'ayant pris par la main droite, il le fit lever; aussitôt la plante de ses pieds et ses chevilles se consolidèrent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'et il se tenait debout en sautant, et il marchait, et il entra avec eux dans le temple, marchant et sautant, et louant Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Et tout le peuple le vit marcher et louer Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'mais ils le reconnurent pour celui qui était assis, pour demander l\'aumône, près de la belle porte du temple, et ils furent remplis de stupeur et de surprise à propos de ce qui lui était arrivé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Or, comme il s\'attachait à Pierre et à Jean, le peuple entier accourut vers eux tout stupéfait dans le portique dit de Salomon;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'ce que Pierre ayant vu, il répliqua au peuple: « Israélites, pourquoi vous étonnez-vous au sujet de cet homme? Ou pourquoi nous regardez-vous fixement, comme si, par notre propre puissance ou notre piété, nous l\'avions fait marcher?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Le Dieu d\'Abraham, et d\'Isaac, et de Jacob, le Dieu de nos pères, a glorifié Son serviteur Jésus, que vous, vous avez livré et renié devant Pilate, lorsque celui-ci résolut de le relâcher;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'mais c\'est vous qui avez renié le saint et le juste, et qui avez demandé qu\'on vous accordât la grâce d\'un meurtrier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'tandis que vous avez fait mourir le prince de la vie que Dieu a ressuscité des morts, ce dont nous sommes témoins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Eh bien, c\'est par la foi en son nom que son nom a rétabli cet homme que vous voyez et connaissez, et c\'est la foi qui vient de lui qui lui a procuré cette complète guérison en présence de vous tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Et maintenant, frères, je sais que vous avez agi par ignorance, comme aussi vos chefs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'mais Dieu a accompli de la sorte ce qu\'il avait prédit par la bouche de tous les prophètes, à savoir que Son Christ devait souffrir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Repentez-vous donc et convertissez-vous, pour que vos péchés soient effacés, afin qu\'arrivent des époques de rafraîchissement de la part du Seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'et qu\'il envoie celui qui vous a été destiné, Christ Jésus');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'que le ciel doit retenir jusques aux temps de restauration universelle, dont Dieu a parlé par la bouche de Ses saints prophètes, de toute ancienneté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'D\'un côté Moïse a dit: « Le Seigneur Dieu vous suscitera d\'entre vos frères un prophète comme moi; vous l\'écouterez dans tout ce qu\'il pourra vous dire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'mais il arrivera que quiconque n\'écoutera pas ce prophète-là sera exterminé du milieu du peuple. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Et, d\'un autre côté, tous les prophètes qui ont parlé, depuis Samuel et ceux qui l\'ont suivi, ont aussi annoncé ces jours-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Pour vous, vous êtes les fils des prophètes et de l\'alliance que Dieu a conclue avec vos pères, en disant à Abraham: « Et dans ta postérité seront bénies toutes les lignées de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'C\'est à vous, d\'abord que Dieu, après avoir suscité Son serviteur Jésus, l\'a envoyé pour vous bénir en détournant chacun de ses méfaits. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Cependant, tandis qu\'ils parlaient au peuple, survinrent contre eux les grands prêtres et le chef des gardes du temple, ainsi que les sadducéens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'vexés de ce qu\'ils enseignaient le peuple et lui annonçaient en la personne de Jésus la résurrection d\'entre les morts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'et ils mirent les mains sur eux, et ils les jetèrent en prison jusques au lendemain; car c\'était déjà le soir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Mais plusieurs de ceux qui avaient entendu le discours crurent, et le nombre des hommes arriva à environ cinq mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Or il advint le lendemain que leurs magistrats, leurs anciens, et leurs scribes se rassemblèrent à Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'ainsi que Annas le grand prêtre, et Caïaphas, et Jean, et Alexandre, et tous ceux qui étaient de la race des grands prêtres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'et les ayant fait comparaître au milieu d\'eux, ils leur demandaient: « En vertu de quelle puissance ou de quel nom avez-vous agi ainsi; vous autres? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Alors Pierre, rempli de l\'esprit saint, leur dit: « Chefs du peuple et anciens,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'puisque nous avons à répondre aujourd\'hui, à propos de la guérison d\'un homme infirme, sur la manière dont il a été guéri,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'qu\'il soit notoire à vous tous et à tout le peuple d\'Israël, que c\'est au nom de Jésus-Christ le Nazoréen, lui que vous avez crucifié, lui que Dieu a ressuscité d\'entre les morts; c\'est grâce à lui que cet homme se présente bien portant devant vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'C\'est lui qui est la pierre qui, méprisée par vous; les constructeurs, est devenue le sommet de l\'angle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'et le salut ne se trouve en aucun autre; car il n\'y a pas un autre nom sous le ciel, qui ait été donné parmi les hommes, par lequel vous deviez être sauvés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Voyant l\'assurance de Pierre et de Jean, et ayant appris que c\'étaient des hommes sans instruction et du commun, ils étaient dans l\'étonnement, et ils les reconnaissaient pour avoir été avec Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'et, comme ils voyaient debout à côté d\'eux l\'homme qui avait été guéri, ils n\'avaient rien à objecter,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Mais, leur ayant ordonné de sortir du sanhédrin, ils consultaient entre eux');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'en disant: « Que pouvons-nous faire à ces hommes-là? Car un miracle notoire a été opéré par eux, il est évident pour tous les habitants de Jérusalem, et nous ne pouvons le nier;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'mais, afin qu\'il ne se divulgue pas davantage parmi le peuple, ordonnons-leur avec menaces de ne plus parler en ce nom-là à personne. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Et les ayant rappelés, ils leur interdirent absolument de parler et d\'enseigner au nom de Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Mais Pierre et Jean leur répliquèrent: « Jugez s\'il est juste devant Dieu de vous écouter plutôt que Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Car, pour nous, nous ne pouvons pas ne point parler de ce que nous savons et de ce que nous avons entendu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Mais ils les renvoyèrent avec de nouvelles menaces, ne trouvant aucun moyen de les punir à cause du peuple, parce que tout le monde glorifiait Dieu de ce qui était arrivé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'car l\'homme sur lequel s\'était opéré le miracle de cette guérison avait plus de quarante ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Or, quand ils eurent été renvoyés, ils vinrent auprès des leurs et racontèrent tout ce que les grands prêtres et les anciens leur avaient dit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Et les autres, après l\'avoir ouï, élevèrent unanimement la voix vers Dieu, et dirent: « O Souverain, Toi, qui as créé le ciel et la terre et la mer et tout ce qui s\'y trouve,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'qui, par l\'esprit saint dans la bouche de notre père David Ton serviteur, as dit: « Pourquoi des nations ont-elles frémi de colère, et des peuples ont-ils formé de vains projets?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Les rois de la terre se sont insurgés, et les magistrats se sont coalisés contre le Seigneur et contre Son oint; » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'car Hérode et Ponce Pilate se sont effectivement coalisés dans cette ville-ci contre Ton saint serviteur Jésus que Tu as oint, avec des Gentils et avec les peuples d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'pour exécuter tout ce que Ta main et Ton conseil avaient prédéterminé. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Et maintenant, Seigneur, surveille leurs menaces, et donne à Tes esclaves d\'annoncer Ta parole avec toute assurance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'en étendant Ta main pour qu\'il s\'opère des guérisons, et pour qu\'il se fasse, par le nom de Ton saint serviteur Jésus, des miracles et des prodiges. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Et, après qu\'ils eurent prié, le lieu où ils étaient réunis trembla, et ils furent tous remplis du saint esprit et ils annonçaient la parole de Dieu avec assurance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Or, la multitude de ceux qui avaient cru était un seul cœur et une seule âme, et pas même un seul d\'entre eux ne disait que quoi que ce fût qu\'il possédât lui appartînt en propre, mais tout leur était commun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Et les apôtres du seigneur Jésus rendaient avec une grande puissance témoignage de sa résurrection; et une grande grâce reposait sur eux tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'En effet, personne parmi eux n\'était dans le besoin; car tous ceux qui possédaient des fonds de terre ou des maisons les vendaient et apportaient le prix de leurs ventes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'et ils le déposaient aux pieds des apôtres; et l\'on répartissait à chacun selon ses besoins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Or Joseph, surnommé par les apôtres Barnabas, ce qui signifie, étant traduit, fils d\'exhortation, lévite, Cypriote d\'origine,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'ayant vendu un champ qu\'il possédait, apporta l\'argent et le déposa aux pieds des apôtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Mais un homme nommé Ananias, avec Sapphira sa femme, vendit une propriété,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'et il retint le prix de complicité avec sa femme, et, en ayant apporté une partie, il la déposa aux pieds des apôtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Mais Pierre dit: « Ananias, pourquoi Satan a-t-il rempli ton cœur, pour que tu mentisses à l\'esprit saint en retenant le prix du fonds de terre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Est-ce qu\'invendu, il ne te demeurait pas, et vendu, n\'était-il pas à ta disposition? Pourquoi as-tu pris ce parti en ton cœur? Ce n\'est pas aux hommes que tu as menti, mais à Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Or, en entendant ces paroles, Ananias tomba et expira. Et une grande crainte se répandit parmi tous les auditeurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Cependant les plus jeunes s\'étant levés l\'enveloppèrent d\'un linceul, et, l\'ayant emporté, ils l\'enterrèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Or il arriva, après un intervalle d\'environ trois heures, que sa femme, ignorant ce qui était advenu, entra;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'et Pierre s\'adressant à elle: « Dis-moi si c\'est pour ce prix-là que vous avez vendu le fonds de terre? » Et elle dit: « Oui, c\'est pour ce prix-là. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Sur quoi Pierre dit: « Pourquoi vous êtes-vous concertés pour tenter l\'esprit du Seigneur? Voici, les pieds de ceux qui ont enterré ton mari sont à la porte, et ils t\'emporteront aussi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Or elle tomba aussitôt à ses pieds, et elle expira; mais les jeunes gens étant entrés la trouvèrent morte, et, l\'ayant emportée, ils l\'enterrèrent auprès de son mari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Et une grande crainte se répandit dans toute l\'église, et parmi tous ceux qui entendaient parler de ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Or il se faisait par les apôtres de nombreux miracles et de nombreux prodiges parmi le peuple; et ils se tenaient tous ensemble dans le portique de Salomon;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'toutefois aucun des autres n\'osait s\'attacher à eux, mais le peuple les exaltait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Cependant il s\'agrégeait toujours plus de gens qui croyaient au Seigneur, des multitudes d\'hommes et de femmes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'en sorte que l\'on apportait les malades même dans les rues, et qu\'on les plaçait sur des couchettes et des grabats, afin que, au passage de Pierre, son ombre tout au moins couvrît quelqu\'un d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Or la multitude des villes voisines accourait aussi à Jérusalem, apportant des malades et des gens tourmentés par des esprits impurs, qui tous étaient guéris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Mais le grand prêtre s\'étant levé, ainsi que tous les adhérents qui formaient le parti des sadducéens, ils furent remplis de jalousie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'et ils mirent les mains sur les apôtres, et ils les jetèrent dans une prison publique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Mais un ange du Seigneur ouvrit de nuit les portes de la prison, et, les en ayant tirés, il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, '« Allez, et, vous tenant dans le temple, annoncez au temple toutes les paroles de cette vie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Ce qu\'ayant ouï, ils entrèrent au point du jour dans le temple, et ils enseignaient. Cependant le grand prêtre et ses adhérents s\'étant réunis convoquèrent le sanhédrin et toute l\'assemblée sénatorienne des fils d\'Israël, et ils envoyèrent à la prison, pour qu\'on les amenât.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Mais, quand les satellites furent arrivés à la prison, ils ne les y trouvèrent point, et ils revinrent faire leur rapport, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, '« Nous avons trouvé la prison fermée avec le plus grand soin, et les gardes debout devant les portes, mais, après avoir ouvert, nous n\'avons trouvé dedans personne, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Quand le chef des gardes du temple et les grands prêtres eurent ouï ces paroles, ils étaient incertains, par rapport à eux, de ce que cela deviendrait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Mais quelqu\'un étant survenu leur fit ce rapport: « Voici, les hommes que vous avez mis en prison sont dans le temple et ils enseignent le peuple. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Alors le chef des gardes étant parti avec ses satellites les ramena toutefois sans violence, car ils craignaient d\'être lapidés par le peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'et, les ayant amenés, ils les firent comparaître devant le sanhédrin. Et le grand prêtre les interrogea en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, '« Nous vous avons formellement défendu d\'enseigner en ce nom-là, et voici, vous avez rempli Jérusalem de votre enseignement, et vous voulez faire retomber sur nous le sang de cet homme-là. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Mais Pierre et les apôtres répliquèrent: « Il faut obéir à Dieu plutôt qu\'aux hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Le Dieu de nos pères a ressuscité Jésus que vous aviez tué en le pendant au bois;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'c\'est lui que Dieu a élevé à Sa droite comme prince et sauveur, pour donner à Israël la repentance et la rémission des péchés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'et c\'est en sa personne que nous avons été témoins de ce que nous venons de dire, et Dieu a donné l\'esprit saint à ceux qui lui obéissent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Ce qu\'ayant ouï, ils en étaient furieux, et ils voulaient les faire périr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Mais un certain pharisien, nommé Gamaliel, docteur de la loi fort estimé de tout le peuple, se leva dans le sanhédrin et demanda qu\'on fit sortir pour un instant ces hommes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'puis il leur dit: « Israélites, prenez garde à ce que vous allez faire relativement à ces hommes-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'En effet, il y a quelque temps qu\'a surgi Theudas, qui se donnait pour un personnage important et auquel s\'étaient ralliés environ quatre cents hommes; il a été tué, et tous ceux qui l\'avaient suivi ont été mis en déroute et se sont réduits à rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Après celui-là a surgi Judas le Galiléen, à l\'époque du recensement, et il a entraîné du monde après lui; lui aussi a péri, et tous ceux qui l\'avaient suivi ont été dispersés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Et maintenant je vous dis: Renoncez à vous occuper de ces hommes-là, et laissez-les aller, — car si cette entreprise ou cette œuvre vient des hommes, elle sera détruite,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'mais si elle vient de Dieu, vous ne pourrez les détruire, — de peur de vous montrer aussi les adversaires de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Or ils se laissèrent persuader par lui, et ayant rappelé les apôtres, ils leur ordonnèrent, après les avoir fait fustiger, de ne point parler au nom de Jésus et ils les relâchèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Pour eux donc, ils se retiraient joyeux de devant le sanhédrin, parce qu\'ils avaient été jugés dignes d\'être traités avec ignominie pour le nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'et ils ne cessaient, chaque jour, d\'enseigner et d\'annoncer la bonne nouvelle de Christ Jésus, dans le temple et dans les maisons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'Or en ce temps-là, comme le nombre des disciples s\'augmentait, il y eut des plaintes des Hellénistes contre les Hébreux, parce que leurs veuves étaient négligées dans le service journalier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Et les douze, ayant convoqué la multitude des disciples, dirent: « Il ne convient pas que nous abandonnions la parole de Dieu pour servir aux tables;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'mais recherchons, frères, sept hommes d\'entre vous, qui aient l\'approbation générale et soient remplis d\'esprit et de sagesse, auxquels nous remettrons cette besogne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'pour nous, nous vaquerons à la prière et au service de la parole. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Et la proposition trouva faveur auprès de toute la multitude, et ils élurent Etienne, homme rempli de foi et d\'esprit saint, et Philippe, et Prochore, et Nicanor, et Timon, et Parménas, et Nicolas prosélyte d\'Antioche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'qu\'ils présentèrent aux apôtres; et, après avoir prié, ils leur imposèrent les mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Et la parole de Dieu prospérait, et le nombre des disciples s\'accroissait beaucoup à Jérusalem, et une grande foule de prêtres embrassaient la foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Cependant Etienne, rempli de grâce et de puissance, faisait de grands prodiges et de grands miracles parmi le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Mais quelques membres de la synagogue dite des Affranchis, et de celles des Cyrénéens et des Alexandrins, et de Cilicie et d\'Asie, entamèrent une discussion avec Etienne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'et ils ne pouvaient résister à la sagesse et à l\'esprit avec lesquels il parlait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Alors ils subornèrent des hommes qui dirent: « Nous l\'avons entendu proférer des paroles blasphématoires contre Moïse et contre Dieu; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'et ils émurent le peuple, ainsi que les anciens et les scribes, et s\'étant jetés sur lui, ils l\'entraînèrent et l\'amenèrent dans le sanhédrin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'et ils produisirent de faux témoins qui dirent: « Cet homme-ci ne cesse de proférer des paroles contre ce lieu saint et contre la loi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'car nous l\'avons entendu dire que ce Jésus le Nazoréen détruira ce lieu, et changera les coutumes que nous a transmises Moïse. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Et ayant fixé leurs regards sur lui, tous ceux qui étaient assis dans le sanhédrin virent que son visage ressemblait au visage d\'un ange.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Mais le grand prêtre dit: « Ces choses sont-elles exactes? » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Et il dit: « Frères et pères, écoutez: Le Dieu de la gloire est apparu à notre père Abraham, pendant qu\'il se trouvait en Mésopotamie, avant de s\'établir à Charran,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'et Il lui a dit: « Sors de ton pays et de ta famille, et rends-toi dans le pays que Je t\'indiquerai. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Alors étant sorti du pays des Chaldéens il s\'établit à Charran. De là, après que son père fut mort, il se transféra dans ce pays-ci que vous habitez maintenant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'et Il ne lui y donna point d\'héritage, pas même de quoi poser son pied; et Il lui promit qu\'il l\'en mettrait en possession, ainsi que sa postérité après lui, quoiqu\'il n\'eût pas d\'enfant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Or voici comment Dieu s\'exprima: « Sa postérité vivra en étrangère dans un pays étranger, et on l\'asservira et on la maltraitera pendant quatre cents ans;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'et la nation par laquelle ils auront été asservis, c\'est Moi qui la jugerai, dit Dieu; et après cela ils sortiront et Me rendront un culte dans ce lieu-ci. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Et Il lui donna l\'alliance de la circoncision; et c\'est ainsi qu\'il engendra Isaac et qu\'il le circoncit le huitième jour, et Isaac Jacob, et Jacob les douze patriarches.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Et les patriarches, jaloux de Joseph, le vendirent pour être emmené en Egypte; et Dieu était avec lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'et Il le tira de toutes ses tribulations, et Il le dota de grâce et de sagesse en présence de Pharaon roi d\'Egypte, et Il le plaça à la tête de l\'Egypte et de toute cette maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Or il survint une famine dans toute l\'Egypte et dans Chanaan, et une grande tribulation, et nos pères ne trouvaient pas de quoi subsister.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Mais Jacob, ayant appris qu\'il y avait des vivres en Egypte, y envoya nos pères une première fois,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'et, au second voyage, Joseph fut reconnu par ses frères, et la race de Joseph devint manifeste pour Pharaon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Puis Joseph envoya chercher son père Jacob et toute sa famille, composée de soixante et quinze personnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Or Jacob descendit, puis il mourut, lui et nos pères, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'et ils furent transportés à Sichem, et déposés dans le sépulcre qu\'Abraham avait acquis à prix d\'argent des fils d\'Emmor à Sichem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Mais, à mesure que s\'approcha le temps de la promesse dont Dieu était convenu avec Abraham, le peuple s\'accrut et se multiplia en Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'jusques à ce que surgit pour régner sur l\'Egypte un autre roi qui ne savait rien de Joseph;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'ce roi, usant de ruse avec notre race, maltraita nos pères, afin de leur faire exposer leurs enfants pour qu\'ils ne restassent pas en vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'Ce fut alors que naquit Moïse, et il était beau aux yeux de Dieu; il fut élevé pendant trois mois dans la maison de son père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'mais ayant été exposé, la fille de Pharaon s\'en chargea et l\'éleva pour elle-même comme un fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Et Moïse fut instruit dans toutes les branches de la sagesse des Égyptiens, et il était puissant par ses paroles et par ses œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Mais, quand il eut atteint l\'âge de quarante ans, il lui vint dans le cœur de visiter ses frères, fils d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'et en ayant vu un qui était maltraité, il prit sa défense, et vengea celui qui était terrassé, en frappant l\'Égyptien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Or il pensait que ses frères comprendraient que Dieu, par son moyen, leur procurait une délivrance; mais ils ne le comprirent pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Et le jour suivant il se montra à eux comme ils se battaient, et il cherchait à les réconcilier pour qu\'ils fissent la paix, en disant: « Vous êtes frères, pourquoi vous maltraitez-vous réciproquement? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Mais celui qui maltraitait son prochain le repoussa en disant: « Qui est-ce qui t\'a établi chef et juge sur nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Veux-tu me tuer comme tu as tué hier l\'Égyptien? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Mais Moïse s\'enfuit à ces mots et il vécut en étranger dans le pays de Madiam, où il engendra deux fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Et, au bout de quarante ans, un ange lui apparut dans le désert du mont Sina dans la flamme d\'un buisson en feu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Et Moïse l\'ayant vu fut étonné de cette apparition, et comme il s\'approchait pour examiner, une voix du Seigneur se fit entendre:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, '« C\'est Moi qui suis le Dieu de tes pères, le Dieu d\'Abraham, et d\'Isaac, et de Jacob! » Mais Moïse, saisi d\'effroi, n\'osait plus examiner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Et le Seigneur lui dit: « Détache la chaussure de tes pieds, car le lieu où tu te trouves est une terre sainte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'J\'ai vu de Mes yeux l\'oppression de Mon peuple en Egypte, et J\'ai entendu ses gémissements, et Je suis descendu pour le délivrer; et maintenant va, Je t\'enverrai en Egypte. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Ce Moïse, qu\'ils avaient renié en disant: « Qui est-ce qui t\'a établi chef et juge? » c\'est lui que Dieu envoya comme chef et comme libérateur avec l\'assistance de l\'ange qui lui était apparu dans le buisson;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'c\'est lui qui les fit sortir, en opérant des prodiges et des miracles en Egypte, et dans la mer Rouge, et dans le désert, pendant quarante ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'C\'est ce Moïse qui a dit aux fils d\'Israël: « Dieu vous suscitera d\'entre vos frères un prophète comme moi; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'c\'est lui qui, dans l\'assemblée au désert, a eu affaire avec l\'ange qui lui parlait sur le mont Sina, et avec nos pères, lui qui avait été choisi pour vous donner de vivants oracles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'c\'est à lui que nos pères refusèrent d\'obéir, mais ils le repoussèrent et ils tournèrent leurs cœurs vers l\'Egypte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'en disant à Aaron: « Fais-nous des dieux qui marcheront devant nous; car ce Moïse qui nous a fait sortir du pays d\'Egypte, nous ne savons ce qui lui est advenu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'Et ce fut alors qu\'ils fabriquèrent un veau, et qu\'ils offrirent un sacrifice à l\'idole, et qu\'ils se réjouissaient des œuvres de leurs mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Mais Dieu se détourna, et Il les livra au culte de l\'armée du ciel, comme il est écrit dans le livre des prophètes: « Ne M\'avez-vous pas offert des sacrifices et des offrandes dans le désert pendant quarante ans, ô maison d\'\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'en même temps que vous transportiez le tabernacle de Moloch et l\'étoile du dieu Rompha, ces images que vous aviez faites pour les adorer? Eh bien, Je vous déporterai par delà Babylone. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Le tabernacle du témoignage était, pour nos pères dans le désert, tel que Celui qui parlait à Moïse lui avait prescrit de le construire, d\'après le modèle qu\'il avait vu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'nos pères, auxquels il fut transmis, l\'introduisirent aussi avec Josué dans le pays conquis sur les nations que Dieu chassa de devant nos pères, jusques à l\'époque de David,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'qui obtint grâce devant Dieu et demanda de trouver une demeure pour la maison de Jacob;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'mais ce fut Salomon qui Lui bâtit une maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Toutefois le Très-Haut n\'habite point dans des édifices faits de main d\'homme, comme dit le prophète:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '« Le ciel est Mon trône, et la terre le marchepied de Mes pieds; quelle maison M\'avez-vous bâtie, dit le Seigneur, ou quel est le lieu de Mon repos?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'N\'est-ce pas Ma main qui a fait toutes ces choses? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Hommes de col roide, et incirconcis du cœur et des oreilles, vous aussi vous résistez toujours à l\'esprit saint, comme vos pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Quel prophète vos pères n\'ont-ils pas persécuté? Et ils ont fait mourir ceux qui d\'avance annonçaient la venue de ce juste envers lequel vous vous êtes montrés naguère traîtres et meurtriers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'vous qui avez reçu la loi comme des commandements d\'anges, et qui ne l\'avez pas observée! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'En entendant ces paroles ils devenaient furieux en leurs cœurs et grinçaient des dents contre lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Mais, étant lui-même rempli d\'esprit saint et fixant ses regards sur le ciel, il vit la gloire de Dieu et Jésus debout à la droite de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'et il dit: « Voici, je vois les cieux ouverts et le fils de l\'homme debout à la droite de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Poussant alors de grands cris ils se bouchèrent les oreilles, puis ils se précipitèrent tous ensemble sur lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'et, l\'ayant jeté hors de la ville, ils le lapidaient. Et les témoins déposèrent leurs manteaux aux pieds d\'un jeune homme appelé Saul,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'et ils lapidaient Etienne, qui disait dans son invocation: « Seigneur Jésus, reçois mon esprit! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Puis, s\'étant mis à genoux, il s\'écria à haute voix: « Seigneur, ne leur impute point ce péché! » Et après ces mots il mourut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Or Saul avait pris plaisir à son supplice. Or, ce jour-là, une grande persécution fut dirigée contre l\'église qui était à Jérusalem; mais tous se dispersèrent dans les contrées de la Judée et de la Samarie, sauf les apôtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Toutefois des hommes pieux enterrèrent Etienne et le pleurèrent bruyamment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Saul, de son côté, ravageait l\'église; envahissant les maisons, il en arrachait hommes et femmes et les livrait pour être jetés en prison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Ceux donc qui s\'étaient dispersés s\'en allèrent de côté et d\'autre annonçant la bonne nouvelle de la parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Or Philippe, étant venu dans la ville de Samarie, leur prêchait le Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'La foule s\'accordait à prêter attention à ce que disait Philippe, parce qu\'elle entendait parler et était témoin des miracles qu\'il faisait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'en effet les esprits impurs sortirent de plusieurs de ceux qui en étaient possédés, en poussant de grands cris, tandis que plusieurs paralytiques et impotents furent guéris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Et ce fut une grande joie dans cette ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Mais un homme nommé Simon, qui déjà auparavant habitait la ville, y exerçait la magie et tenait sous le charme la nation des Samaritains, en se disant un grand personnage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Tous, du petit au grand, lui prêtaient attention, et disaient: « Celui-ci est la puissance de Dieu, qui est appelée grande. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Et ils lui prêtaient attention, parce que pendant longtemps il les avait tenus sous le charme par ses sortilèges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Mais quand ils eurent cru Philippe, qui leur annonçait la bonne nouvelle du royaume de Dieu et du nom de Jésus-Christ, hommes et femmes se faisaient baptiser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Or Simon lui-même crut aussi, et après avoir été baptisé il s\'attacha à Philippe; la vue des miracles et des grands prodiges qui s\'opéraient le tenait sous le charme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Or, les apôtres qui étaient à Jérusalem, ayant appris que la Samarie accueillait la parole de Dieu, leur envoyèrent Pierre et Jean,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'qui, lorsqu\'ils furent arrivés, prièrent pour eux, afin qu\'ils reçussent l\'esprit saint;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'car il n\'était encore tombé sur aucun d\'eux, mais ils avaient seulement été baptisés au nom du seigneur Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'alors ils leur imposèrent les mains et ils recevaient l\'esprit saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Or Simon, ayant vu que l\'esprit était donné par l\'imposition des mains des apôtres, leur offrit de l\'argent en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, '« Octroyez-moi aussi cette autorité, afin que celui à qui j\'aurai imposé les mains reçoive l\'esprit saint. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Mais Pierre lui dit: « Que ton argent périsse avec toi, puisque tu as cru acquérir le don de Dieu avec de l\'argent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'il n\'y a pour toi ni portion ni lot dans cette affaire, car ton cœur n\'est pas droit devant Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'repens-toi donc de ta méchanceté dont tu viens de faire preuve, et prie le Seigneur, pour voir si le projet de ton cœur te sera pardonné;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'car je vois que tu te trouves dans du fiel amer et dans les nœuds de l\'injustice. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Et Simon répliqua: « Priez vous-mêmes pour moi le Seigneur, afin que rien de ce dont vous avez parlé ne m\'arrive. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Pour eux donc, après avoir rendu témoignage et proclamé la parole du Seigneur, ils revinrent à Jérusalem, et ils annoncèrent la bonne nouvelle dans plusieurs villages des Samaritains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Or, un ange du Seigneur s\'adressa à Philippe en disant: « Lève-toi, et va du côté du midi sur la route qui descend de Jérusalem à Gaza; elle est déserte. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Et s\'étant levé il se mit en chemin; et voici, un Éthiopien, principal eunuque de Candace, reine des Éthiopiens, et qui était son trésorier général, était venu à Jérusalem pour adorer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'Or il s\'en retournait, et, assis sur son char, il lisait le prophète Ésaïe;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'or l\'Esprit dit à Philippe: « Approche-toi et tiens-toi collé à ce char. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Et Philippe étant accouru l\'entendit qui lisait Ésaïe le prophète, et il dit: « Est-ce que tu comprends bien ce que tu lis? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Mais l\'autre dit: « Eh, comment le pourrais-je, si personne ne me guide? » Et il invita Philippe à monter et à s\'asseoir à côté de lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Or voici quel était le contenu du texte qu\'il lisait: « C\'est comme une brebis qu\'il a été conduit à la tuerie; et, de même qu\'un agneau est muet devant celui qui le tond, de même il n\'ouvre point la bouche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'c\'est dans l\'humiliation que s\'est consommé son jugement. Qui dépeindra les hommes de sa génération? Car sa vie est enlevée de dessus la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'L\'eunuque s\'adressant à Philippe: « Je te prie, dit-il, de qui le prophète parle-t-il ainsi? Est-ce de lui-même, ou de quelque autre? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Là-dessus Philippe, ouvrant la bouche et commençant par ce texte-là, lui annonça la bonne nouvelle de Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Or, comme ils cheminaient le long de la route, ils arrivèrent vers de l\'eau, et l\'eunuque dit: « Voici de l\'eau; qu\'est-ce qui empêche que je ne sois baptisé? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'Et il fit arrêter son char, et ils descendirent l\'un et l\'autre dans l\'eau, Philippe et l\'eunuque, et il le baptisa.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Mais, quand ils furent ressortis de l\'eau, l\'esprit du Seigneur enleva Philippe, et l\'eunuque ne le vit plus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'car tandis qu\'il continuait sa route plein de joie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Philippe se trouva dans Azot. Et il s\'en allait de côté et d\'autre, évangélisant toutes les villes jusques à ce qu\'il arrivât à Césarée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Or Saul, respirant encore la menace et le meurtre contre les disciples du Seigneur, vint trouver le grand prêtre');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'et lui demanda des lettres pour les synagogues de Damas, afin que, s\'il trouvait quelques adhérents de la doctrine, hommes et femmes, il les ramenât chargés de chaînes à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Et, comme il était en chemin, il advint, lorsqu\'il approchait de Damas, que, tout à coup, une lumière venue du ciel l\'enveloppa comme un éclair,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'et qu\'étant tombé à terre il entendit une voix qui lui disait: « Saul, Saul, pourquoi me persécutes-tu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Mais il dit: « Qui es-tu, Seigneur? » Et lui: « Je suis Jésus que tu persécutes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'mais lève-toi, et entre dans la ville, et l\'on te dira ce qu\'il faut que tu fasses. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Or les hommes qui faisaient route avec lui étaient demeurés muets; ils entendaient bien la voix, mais ils ne voyaient personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Cependant Paul se releva de terre, mais, les yeux ouverts, il ne voyait rien, et ce fut en le conduisant par la main qu\'on le fit entrer à Damas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Il resta trois jours sans voir clair, et il ne mangeait ni ne buvait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Or il y avait à Damas un disciple nommé Ananias, et le seigneur lui dit, dans une vision: « Ananias! » et il dit: « Me voici, Seigneur! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Mais le Seigneur lui dit: « Lève-toi, et va dans la rue appelée droite et cherche, dans la maison de Judas, un nommé Saul de Tarse; car, voici, il est en prière,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'et il a vu en vision un homme nommé Ananias, qui entrait et lui imposait les mains, afin qu\'il recouvrât la vue. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Mais Ananias répliqua: « Seigneur, j\'ai ouï parler à bien des gens de tous les maux que cet homme a fait souffrir à tes saints dans Jérusalem;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'et il apporte ici une autorisation des grands prêtres pour charger de chaînes tous ceux qui invoquent ton nom. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Mais le seigneur lui dit: « Va, parce que cet homme est pour moi un instrument de choix destiné à porter mon nom devant les Gentils et devant des rois, et devant les fils d\'Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'car je lui montrerai tout ce qu\'il faut qu\'il souffre pour mon nom. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Là-dessus Ananias s\'en vint et entra dans la maison, et, lui ayant imposé les mains, il dit: « Saul, mon frère, c\'est le Seigneur qui m\'a envoyé, — Jésus qui t\'est apparu sur la route par laquelle tu venais, — afin que tu recouvres la vue et que tu sois rempli d\'esprit saint. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Et aussitôt il tomba de ses yeux comme des écailles, et il recouvra la vue, et s\'étant levé il fut baptisé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'et ayant pris de la nourriture il se fortifia. Or il demeura quelques jours avec les disciples qui étaient à Damas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'et il prêchait immédiatement Jésus dans les synagogues en disant: « C\'est lui qui est le fils de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Mais tous ceux qui l\'entendaient étaient dans l\'étonnement, et ils disaient: « N\'est-ce pas cet homme qui maltraitait dans Jérusalem ceux qui invoquent ce nom, et qui était venu ici dans le but de les amener chargés de chaînes devant les grands prêtres? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Quant à Saul, il prenait toujours plus de puissance, et il confondait les Juifs qui habitaient Damas en démontrant cette vérité: « C\'est lui qui est le Christ. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Mais, au bout d\'un certain temps, les Juifs complotèrent de le faire périr;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'mais leur projet vint à la connaissance de Saul. Or on faisait même la garde aux portes, jour et nuit, afin de le faire périr;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'mais ses disciples le prirent de nuit, et le firent descendre par la muraille en le dévalant dans une corbeille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Cependant, quand il fut arrivé à Jérusalem, il tâchait de frayer avec les disciples, et tous le craignaient, ne croyant pas qu\'il fût disciple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Mais Barnabas s\'étant emparé de lui le conduisit auprès des apôtres, et il leur raconta comment sur la route il avait vu le seigneur, et que celui-ci lui avait parlé, et comment à Damas il avait prêché avec assurance au nom de Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'Et il était en rapport avec eux dans Jérusalem, prêchant avec assurance au nom du seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'et il parlait et discutait avec les Hellénistes; mais ceux-ci tâchaient de le faire périr.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Ce que les frères ayant su, ils le conduisirent à Césarée, et l\'envoyèrent à Tarse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'Tandis que l\'Église était donc en paix dans toute la Judée, la Galilée et la Samarie, s\'édifiant et marchant dans la crainte du Seigneur, et qu\'elle s\'accroissait par l\'assistance du Saint Esprit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'il advint que Pierre, qui faisait une tournée, arriva aussi auprès des frères qui habitaient Lydda,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'et il y trouva un homme nommé Énée couché depuis huit ans sur un grabat, et qui était paralytique;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'et Pierre lui dit: « Énée, Jésus-Christ te guérit; lève-toi, et fais-toi toi-même ton lit. » Et aussitôt il se leva,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'et tous ceux qui habitaient Lydda et la plaine de Saron le virent, lesquels se convertirent au seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Or il y avait à Joppé, parmi les disciples, une femme nommée Tabitha, ce qui, étant traduit, signifie Gazelle; elle était riche des bonnes œuvres et des aumônes qu\'elle faisait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'mais il advint qu\'en ce temps-là elle tomba malade et mourut; après l\'avoir lavée on la déposa dans une chambre haute;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'mais, comme Lydda est près de Joppé, les disciples ayant appris que Pierre était dans cette ville, dépêchèrent auprès de lui deux hommes pour lui dire avec instances: « Ne tarde pas à venir jusques à nous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Or Pierre s\'étant levé revint avec eux. Dès qu\'il fut arrivé, on le conduisit dans la chambre haute, et là se présentèrent à lui toutes les veuves en larmes, qui lui montraient toutes les tuniques et les manteaux auxquels Gazelle travaillait pendant qu\'elle était avec elles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Mais Pierre fit sortir tout le monde, et, s\'étant mis à genoux, il fit une prière, puis, s\'étant tourné vers le corps, il dit: « Tabitha, lève-toi! » Celle-ci ouvrit les yeux, et ayant vu Pierre, elle s\'assit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'mais il lui donna la main, et la fit mettre debout, et, ayant appelé les saints et les veuves, il la leur présenta vivante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Cela fut connu de tout Joppé, et plusieurs crurent au seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Or il resta plusieurs jours à Joppé chez un certain Simon corroyeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Cependant, à Césarée, un homme nommé Cornélius, centurion de la cohorte qui est appelé Italienne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'pieux et craignant Dieu ainsi que toute sa famille, lequel faisait de nombreuses aumônes au peuple et adressait à Dieu de constantes prières,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'vit clairement, dans une vision, environ vers la neuvième heure du jour, un ange de Dieu qui entrait vers lui et lui disait: « Cornélius! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'mais ce dernier, ayant fixé sur lui ses regards, et étant saisi de crainte, dit: « Qu\'est-ce, Seigneur? » Et il lui dit: « Tes prières et tes aumônes sont montées en témoignage devant Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'et maintenant envoie des gens à Joppé et fais-en venir un certain Simon, qui est surnommé Pierre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'il loge chez un certain Simon corroyeur, dont la maison est proche de la mer. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Quand l\'ange qui lui parlait fut parti, il appela deux de ses serviteurs et un soldat pieux d\'entre ceux qui étaient attachés à sa personne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'et, après leur avoir tout raconté, il les dépêcha à Joppé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Or, le lendemain, comme ils étaient en route et s\'approchaient de la ville, Pierre monta sur le toit, vers la sixième heure, pour prier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Mais il eut faim, et il voulait manger; or, pendant qu\'on préparait le repas, il tomba en extase,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'et il vit le ciel s\'ouvrir, et descendre un objet semblable à une grande toile, lequel par quatre coins était abaissé vers la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'et où se trouvaient tous les quadrupèdes et les reptiles de la terre et les oiseaux du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Et une voix lui dit: « Lève-toi, Pierre, tue et mange. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Mais Pierre dit: « Point du tout, Seigneur, car jamais je n\'ai mangé quoi que ce soit de souillé, ni d\'impur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Et derechef la voix s\'adressant à lui pour la seconde fois: « Ce que Dieu a purifié, ce n\'est pas à toi de le déclarer souillé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Or ceci se répéta trois fois, et aussitôt l\'objet fut remonté dans le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Mais, comme Pierre était incertain en lui-même sur ce que pouvait signifier la vision qu\'il avait vue, voici, les hommes dépêchés par Cornélius, après s\'être enquis où était la maison de Simon, se présentèrent devant le porche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'et, après avoir appelé, ils demandèrent: « Est-ce que Simon, surnommé Pierre, loge ici? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Or, pendant que Pierre réfléchissait sur la vision, l\'Esprit dit: « Voici, deux hommes te cherchent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'mais lève-toi, descends, et pars avec eux sans hésiter, car c\'est moi qui les ai envoyés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Or, Pierre étant descendu dit à ces hommes: « Voici, c\'est moi qui suis celui que vous cherchez; quel est le motif qui vous amène? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Et ils dirent: « Cornélius, centurion, homme juste et craignant Dieu, et auquel toute la nation des Juifs rend un bon témoignage, a été averti par un saint ange de te faire venir dans sa maison et d\'écouter ce que tu diras. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Les ayant donc priés d\'entrer, il les hébergea; mais le lendemain, il se leva pour partir avec eux; et quelques-uns des frères de Joppé l\'accompagnèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Le lendemain il entra dans Césarée. Or Cornélius, qui les attendait, avait invité ses parents et ses intimes amis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Et, quand Pierre fut sur le point d\'entrer, Cornélius allant à sa rencontre se jeta à ses pieds pour l\'adorer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'mais Pierre le releva en disant: « Lève-toi; moi-même aussi je suis un homme; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'et il entra en s\'entretenant avec lui, et il trouva beaucoup de gens rassemblés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'et il leur dit: « Vous savez à quel point il est interdit à un Juif de frayer ou de s\'aboucher avec un étranger, eh bien, quant à moi, Dieu m\'a appris à n\'appeler aucun homme souillé ou impur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'c\'est pourquoi je suis venu, sans même faire d\'objections, sur l\'invitation que j\'ai reçue; informez-moi donc du motif pour lequel vous m\'avez fait venir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Et Cornélius dit: « Il y a quatre jours, à cette heure-ci, que je faisais dans ma maison la prière de la neuvième heure, et voici, un homme se présenta devant moi en habit blanc,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'et dit: « Cornélius! ta prière a été exaucée, et tes aumônes ont été remémorées devant Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'envoie donc à Joppé, et fais-en venir Simon qui est surnommé Pierre; il loge dans la maison de Simon corroyeur proche de la mer. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Aussitôt donc j\'ai envoyé vers toi, et tu as bien fait de venir; maintenant donc nous sommes tous présents devant Dieu, pour entendre tout ce qui t\'est prescrit par le Seigneur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Et Pierre, ouvrant la bouche, dit: « Je comprends véritablement que Dieu ne fait pas acception de personnes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'mais qu\'en toute nation celui qui le craint et qui pratique la justice Lui est agréable;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Il a envoyé la parole aux fils d\'Israël en leur annonçant la bonne nouvelle de la paix par Jésus-Christ; celui-ci est seigneur de tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Vous savez ce qui s\'est passé dans toute la Judée, à commencer par la Galilée après le baptême que Jean a prêché;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'vous savez, en ce qui concerne Jésus de Nazareth, comment Dieu l\'a oint d\'esprit saint et de force, lui qui s\'en est allé de côté et d\'autre faisant du bien, et guérissant tous ceux qui étaient tyrannisés par le diable, car Dieu était avec lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'et c\'est nous qui sommes les témoins de tout ce qu\'il a fait, soit dans le pays des Juifs, soit à Jérusalem; c\'est lui qu\'ils ont été jusqu\'à mettre à mort en le pendant à une croix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'et que Dieu a ressuscité au bout de trois jours; et Il a permis qu\'il apparût,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'non pas à tout le peuple, mais aux témoins que Dieu avait élus d\'avance, à nous qui avons mangé et bu avec lui, après qu\'il fut ressuscité des morts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'et il nous a ordonné de prêcher au peuple et d\'attester que c\'est lui qui a été désigné par Dieu comme juge des vivants et des morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'C\'est de lui que tous les prophètes attestent que quiconque croit en lui reçoit par son nom la rémission des péchés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Pendant que Pierre prononçait encore ces mots, l\'esprit saint tomba sur tous ceux qui écoutaient la parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Et les fidèles circoncis qui avaient accompagné Pierre étaient surpris que le don de l\'esprit saint fût également répandu sur les Gentils;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'car ils les entendaient parler en langues et magnifier Dieu. Alors Pierre reprit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, '« Est-ce que quelqu\'un peut retenir l\'eau, afin que le baptême ne soit pas administré à ces hommes qui ont reçu l\'esprit saint aussi bien que nous? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'Et il ordonna qu\'ils fussent baptisés au nom de Jésus-Christ. Alors ils le prièrent de séjourner quelques jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Cependant les apôtres et les frères qui étaient en Judée apprirent que les Gentils avaient aussi reçu la parole de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'et, quand Pierre fut revenu à Jérusalem, les circoncis le querellaient');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'en disant: « Tu es entré chez des hommes incirconcis, et tu as mangé avec eux! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Pierre, reprenant dès le début, leur fit un exposé suivi, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, '« J\'étais en prière dans la ville de Joppé, et je vis en extase une vision, un objet qui descendait comme une grande toile, laquelle était abaissée du ciel par quatre coins, et elle vint jusques à moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'y ayant jeté les yeux je regardais avec attention, et je vis les quadrupèdes de la terre, et les bêtes féroces, et les reptiles, et les oiseaux du ciel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'j\'entendis aussi une voix qui me disait: « Lève-toi, Pierre, tue et mange. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Mais je dis: « Point du tout, Seigneur, car rien de ce qui est souillé ou impur n\'est jamais entré dans ma bouche. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Mais une voix du ciel reprit pour la seconde fois: « Ce que Dieu a purifié, ce n\'est pas à toi de le tenir pour souillé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Et ceci se répéta trois fois, et tout fut de nouveau hissé dans le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Et voici, aussitôt trois hommes se présentèrent devant la maison où nous étions, lesquels étaient envoyés de Césarée vers moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'or l\'Esprit me dit de m\'aboucher avec eux sans hésiter. Ils repartirent donc avec moi et les six frères que voici, et nous arrivâmes dans la maison du personnage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Il nous informa comment il avait vu dans sa maison l\'ange qui s\'était présenté à lui et lui avait dit: « Envoie à Joppé, et fais-en venir Simon qui est surnommé Pierre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'il t\'adressera des paroles par lesquelles tu seras sauvé, toi et toute ta famille. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Or, comme je commençais à parler, l\'esprit saint tomba sur eux, ainsi qu\'il était aussi tombé sur nous au commencement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'et je me rappelai le mot du seigneur, lorsqu\'il disait: « Jean a baptisé avec de l\'eau, tandis que vous, vous serez baptisés avec l\'esprit saint, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Puis donc que Dieu leur a fait le même don qu\'à nous, pour avoir cru au seigneur Jésus-Christ, comment, moi, eussé-je été capable de m\'opposer à Dieu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Après avoir entendu cela, ils se calmèrent, et ils glorifièrent Dieu en disant: « Ainsi donc, Dieu a aussi donné aux Gentils la repentance pour les amener à la vie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Ceux donc qui s\'étaient dispersés par suite de la persécution survenue à propos d\'Etienne, passèrent jusques en Phénicie, dans l\'île de Chypre et à Antioche, n\'annonçant la parole à personne qu\'aux seuls Juifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Toutefois quelques-uns d\'entre eux étaient des Cypriotes et des Cyrénéens qui, arrivés à Antioche, s\'adressèrent aussi aux Hellénistes en leur annonçant la bonne nouvelle du seigneur Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'Et la main du Seigneur était avec eux, et un grand nombre de croyants se convertit au Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Le bruit en vint aux oreilles de l\'Église qui était à Jérusalem, et ils envoyèrent Barnabas jusques à Antioche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Lorsqu\'il y fut arrivé et qu\'il eut vu la grâce de Dieu, il fut réjoui, et il les exhortait tous à demeurer fidèles, dans le seigneur, à la résolution qu\'ils avaient prise en leur cœur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'car c\'était un homme de bien, et rempli d\'esprit saint et de foi. Et une foule considérable fut agrégée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Or il s\'en fut à Tarse pour en tirer Saul, et, l\'ayant trouvé, il le ramena à Antioche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'et il leur arriva de passer jusques à une année tout entière ensemble dans l\'église et d\'enseigner une foule considérable; et ce fut à Antioche que, pour la première fois, on donna aux disciples le nom de chrétiens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'Or, à la même époque des prophètes descendirent de Jérusalem à Antioche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'et l\'un d\'eux, nommé Agabus, s\'étant levé, il dévoilait par l\'Esprit qu\'une grande famine devait avoir lieu sur toute la terre, (laquelle eut lieu sous Claude).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Or, les disciples résolurent d\'adresser, chacun selon ses moyens, un secours aux frères qui habitaient la Judée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'ce qu\'ils firent en l\'envoyant aux anciens par l\'entremise de Barnabas et de Saul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Or, ce fut en ce temps-là que le roi Hérode prit des mesures pour maltraiter quelques-uns des membres de l\'Église.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Il fit périr Jacques, le frère de Jean, par l\'épée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'et, voyant que cela plaisait aux Juifs, il fit en outre arrêter Pierre; (or c\'étaient les jours des pains sans levain);');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'l\'ayant aussi fait saisir il le jeta en prison, en chargeant de le garder quatre escouades de quatre soldats, avec l\'intention de le faire comparaître après la Pâque devant le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Pierre donc était gardé dans la prison, tandis que l\'Église adressait pour lui d\'incessantes prières.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Mais, lorsque Hérode allait le faire comparaître, Pierre se trouvait, cette nuit-là, endormi entre deux soldats; il avait été chargé d\'une double chaîne, et des gardes placés devant la porte veillaient sur la prison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Et voici, un ange du Seigneur survint, et une lumière brilla dans le cachot, et ayant frappé Pierre sur le flanc il l\'éveilla en disant: « Lève-toi promptement, » et les chaînes tombèrent de ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Mais l\'ange lui dit: « Ceins ta ceinture et chausse tes sandales; » c\'est ce qu\'il fît; puis il lui dit: « Enveloppe-toi de ton manteau, et suis-moi, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'et étant sorti il le suivit. Et il ignorait que ce qui s\'était fait par l\'ange fût vrai, mais il s\'imaginait avoir une vision.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Après qu\'ils eurent traversé la première et la seconde porte, ils arrivèrent à la porte de fer qui conduisait dans la ville; elle s\'ouvrit d\'elle-même devant eux, et étant sortis, ils s\'avancèrent dans une rue, et aussitôt l\'ange le quitta.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Et Pierre étant revenu à lui, dit: « Maintenant je sais certainement que le Seigneur a envoyé Son ange, et qu\'il m\'a délivré des mains d\'Hérode et de tout ce qu\'attendait le peuple juif. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Après s\'être reconnu, il vint à la maison de Marie mère de Jean surnommé Marc, où beaucoup de gens se trouvaient réunis en prière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Lorsqu\'il eut heurté à la porte du porche, une servante, nommé Rhode, s\'avança pour écouter,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'et, ayant reconnu la voix de Pierre, de la joie qu\'elle en eut elle n\'ouvrit pas le porche, et s\'en vint tout courant raconter que Pierre était devant le porche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Mais on lui dit: « Tu es folle. » Mais elle affirmait qu\'il en était ainsi, et on dit: « C\'est son ange. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Cependant Pierre continuait à heurter, et ayant ouvert ils le virent et furent tout hors d\'eux-mêmes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'mais lui, leur ayant de la main fait signe de se taire, leur raconta comment le Seigneur l\'avait tiré de la prison et il dit: « Informez-en Jacques et les frères. » Puis étant sorti, il se rendit dans un autre lieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Cependant, quand le jour fut venu, une grande agitation s\'empara des soldats qui ne savaient ce que Pierre était devenu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Quant à Hérode, après l\'avoir fait quérir sans pouvoir le trouver, il fit faire aux gardes leur procès et ordonna qu\'on les suppliciât; puis, ayant quitté la Judée, il séjournait à Césarée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Or, il se trouvait en hostilité avec les Tyriens et les Sidoniens; ceux-ci se rendirent ensemble auprès de lui, et, ayant gagné Blastus le chambellan du roi, ils sollicitaient la paix parce que leur pays tirait sa subsistance de celui du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Or, au jour fixé, Hérode, revêtu de ses habits royaux, les haranguait assis dans sa tribune,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'et le peuple s\'écriait: « Voix de dieu et non d\'homme! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Mais aussitôt un ange du Seigneur le frappa, pour n\'avoir pas rapporté la gloire à Dieu, et il expira rongé des vers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Cependant la parole du seigneur croissait et grandissait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Et Barnabas et Saul revinrent à Jérusalem, après avoir rempli leur mission, et pris avec eux Jean surnommé Marc.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Or, il y avait à Antioche, dans l\'église qui s\'y trouvait, des prophètes et des docteurs, à savoir Barnabas et Siméon appelé Niger, et Lucius le Cyrénéen, et Manahen compagnon d\'enfance d\'Hérode le tétrarque, et Saul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Et, pendant qu\'ils étaient occupés au culte du Seigneur et qu\'ils jeûnaient, l\'esprit saint dit: « Mettez immédiatement à part pour moi Barnabas et Saul, en vue de l\'œuvre à laquelle je les ai appelés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Alors, après avoir jeûné et prié et leur avoir imposé les mains, ils les congédièrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Eux donc, ayant été députés par le saint esprit, descendirent à Séleucie, et de là naviguèrent vers l\'île de Chypre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'arrivés à Salamine, ils annonçaient la parole de Dieu dans les synagogues des Juifs; or ils avaient aussi Jean comme auxiliaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Ayant ensuite traversé toute l\'île jusques à Paphos, ils rencontrèrent un certain personnage, magicien et faux prophète, Juif, nommé Barjésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'lequel vivait auprès du proconsul Sergius Paulus, qui était un homme intelligent. Celui-ci, ayant fait venir Barnabas et Saul, témoigna le désir d\'entendre la parole de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Mais Élymas, (le magicien, car c\'est ainsi que se traduit son nom) s\'opposait à eux, en cherchant à détourner le proconsul de la foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Mais Saul, qui est aussi appelé Paul, rempli d\'esprit saint, ayant fixé sur lui ses regards, dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, '« O toi, qui es plein de toute espèce de ruse et de malice, fils du diable, ennemi de toute justice, ne cesseras-tu point de pervertir les voies droites du Seigneur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Et maintenant, voici, la main du Seigneur est sur toi, et tu seras aveugle et tu ne verras point le soleil pour un certain temps. » Aussitôt il fut enveloppé d\'un brouillard et de ténèbres, et, allant ici et là, il cherchait des guides.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Alors le proconsul, ayant vu ce qui s\'était passé, crut, et il était tout rempli de stupéfaction de la doctrine du seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Après s\'être embarqués à Paphos, Paul et ses compagnons vinrent à Perge de Pamphylie. Mais Jean, s\'étant séparé d\'eux, retourna à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Pour eux, ayant, depuis Perge, poursuivi leur route, ils vinrent à Antioche de Pisidie, et, étant entrés dans la synagogue le jour du sabbat, ils s\'assirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Après la lecture de la loi et des prophètes, les chefs de la synagogue leur firent faire ce message: « Frères, si vous avez quelque parole d\'exhortation à adresser au peuple, parlez. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Et Paul, s\'étant levé et ayant fait signe de la main, dit: « Israélites, et vous qui craignez Dieu, écoutez:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Le Dieu du peuple d\'Israël S\'est choisi nos pères, et Il a relevé le peuple pendant qu\'il vivait en étranger dans le pays d\'Egypte, et Il l\'en a fait sortir à bras élevé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'et, pendant environ quarante ans, Il s\'est accommodé à eux dans le désert;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'après avoir anéanti sept nations dans le pays de Chanaan, Il les a mis en possession de leur territoire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'pendant environ quatre cent cinquante ans; et, après cela, Il leur donna des juges jusques à Samuel le prophète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Ce fut alors qu\'ils demandèrent un roi, et Dieu leur donna Saül, fil de Kis, membre de la tribu de Benjamin, pendant quarante ans;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'puis, l\'ayant détrôné, Il leur suscita David pour roi, auquel Il a rendu témoignage en disant: « J\'ai trouvé David fils de Jessé selon Mon cœur, il fera toute Ma volonté. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'C\'est de la postérité de celui-ci que Dieu, selon Sa promesse, a fait sortir Jésus pour être le sauveur d\'Israël,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'après que Jean eut prêché, avant son avènement, un baptême de repentance à tout le peuple d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Et, comme Jean achevait sa course, il disait: « Ce que vous croyez que je suis, je ne le suis pas; mais, voici, il en vient un après moi, des pieds duquel je ne suis pas digne de délier la chaussure. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Frères, fils de la race d\'Abraham, vous qui parmi eux craignez Dieu, c\'est à nous que la parole de ce salut a été envoyée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'car ceux qui habitent Jérusalem et leurs chefs l\'ayant méconnu, ils ont aussi, en le condamnant, accompli les déclarations des prophètes qui se lisent chaque sabbat,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'et, sans avoir trouvé aucun motif de mort, ils ont prié Pilate de le faire périr;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'puis, quand ils eurent accompli tout ce qui a été écrit de lui, ils le placèrent, après l\'avoir ôté de la croix, dans un sépulcre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'mais Dieu l\'a ressuscité des morts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'et il est apparu pendant plusieurs jours à ceux qui étaient montés avec lui de Galilée à Jérusalem, lesquels sont ses témoins auprès du peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Et nous vous annonçons comme une bonne nouvelle, que la promesse faite à nos pères, Dieu l\'a réalisée pour nos enfants, en ressuscitant Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'comme il est aussi écrit dans le second Psaume: « Tu es Mon fils, c\'est Moi qui t\'ai engendré aujourd\'hui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Mais, qu\'il l\'ait ressuscité des morts sans qu\'il doive retomber encore dans la corruption, c\'est ce qu\'il dit en ces termes: « Je vous donnerai les choses saintes de David, qui sont certaines; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'c\'est pourquoi dans un autre encore il dit: « Tu ne permettras pas que Ton saint voie la corruption. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'En effet, quant à David, après avoir, par la volonté de Dieu, servi sa propre génération, il est mort et a été réuni à ses pères, et il a vu la corruption,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'tandis que celui que Dieu a ressuscité n\'a pas vu la corruption.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Qu\'il vous soit donc notoire, frères, que c\'est à cause de cela que la rémission des péchés vous est annoncée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'et que c\'est en lui que tout croyant est justifié de tout ce dont vous ne pouviez être justifiés sous la loi de Moïse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Prenez donc garde que ne survienne pas ce qui a été dit dans les prophètes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '« Voyez, ô contempteurs, et soyez étonnés et disparaissez, parce que, de votre temps, s\'opère une œuvre, une œuvre à laquelle vous ne croiriez certainement pas, si quelqu\'un vous la racontait. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Or, comme ils sortaient, on leur demanda de répéter le sabbat suivant les mêmes choses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'puis, quand la congrégation se fut dispersée, plusieurs Juifs et prosélytes pieux suivirent Paul et Barnabas, qui, s\'adressant à eux, les persuadaient de s\'attacher à la grâce de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Et le sabbat suivant presque toute la ville se réunit pour entendre la parole de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Mais les Juifs, ayant vu cette foule, furent remplis de jalousie, et ils contredisaient les paroles de Paul en l\'injuriant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Paul et Barnabas, tout remplis d\'assurance, dirent: « C\'est à vous qu\'il fallait d\'abord annoncer la parole de Dieu; puisque vous la repoussez, et que vous ne vous jugez pas dignes de la vie éternelle, voici, nous nous tournons vers les Gentils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Car, voici ce que nous a prescrit le Seigneur: « Je t\'ai établi pour être la lumière des Gentils, afin que tu serves à répandre le salut jusques à l\'extrémité de la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'En entendant cela les Gentils étaient dans la joie, et ils glorifiaient la parole de Dieu, et tous ceux qui étaient destinés à la vie éternelle crurent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'Cependant la parole du seigneur se répandait dans tout le pays;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'mais les Juifs excitèrent les grandes dames dévotes et les principaux de la ville, et provoquèrent une persécution contre Paul et Barnabas, et ils les chassèrent de leur territoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Mais ceux-ci, ayant secoué contre eux la poussière de leurs pieds, se rendirent à Icone,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'et les disciples étaient remplis de joie et d\'esprit saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Or, il advint qu\'à Icône ils entrèrent ensemble dans la synagogue des Juifs, et qu\'ils parlèrent de manière qu\'une grande multitude de Juifs et de Grecs crurent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'mais ceux des Juifs qui refusèrent de croire soulevèrent et aigrirent l\'esprit des Gentils contre les frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Aussi, après que, pendant un long espace de temps, ils eurent agi avec une pleine assurance, grâce au Seigneur qui rendait témoignage à la parole de Sa grâce en permettant que des miracles et des prodiges s\'opérassent par leurs mains,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'la multitude de l\'endroit se divisa, les uns tenant pour les Juifs et les autres pour les apôtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Mais, s\'étant aperçus que les Gentils et les Juifs avec leurs chefs étaient prêts à les outrager et à les lapider,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'ils se réfugièrent dans les villes de Lycaonie, Lystre et Derbe, et dans le pays circonvoisin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'et ils y prêchaient la bonne nouvelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Et, à Lystre, se tenait assis un certain homme impotent des pieds, estropié de naissance qui jamais n\'avait marché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Cet individu entendait parler Paul qui, ayant fixé ses regards sur lui, et ayant vu qu\'il avait foi en sa guérison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'lui dit à voix haute: « Lève-toi tout droit sur tes pieds; » et il sauta, et il marchait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Et la foule, ayant vu ce que Paul avait fait, éleva la voix en disant en lycaonien: « Les dieux, ayant pris la ressemblance des hommes, sont descendus vers nous; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'et ils appelaient Barnabas Jupiter, et Paul Mercure, parce qu\'il portait la parole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Et le prêtre du Jupiter qui est devant l\'entrée de la ville, ayant amené vers les portes des taureaux avec des bandelettes, voulait offrir un sacrifice avec la foule;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'mais les apôtres Barnabas et Paul l\'ayant appris déchirèrent leurs vêtements et se jetèrent au milieu de la foule, en s\'écriant: «');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'O hommes, pourquoi agissez-vous ainsi? Nous aussi, nous sommes des hommes de même espèce que vous, qui vous annonçons une bonne nouvelle pour que vous vous détourniez de toutes ces vanités, et que vous vous convertissiez au Dieu vivant, qui a fait le ciel et la terre, et la mer et tout ce qui s\'y trouve;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'qui, dans les générations passées, a laissé tous les Gentils suivre leurs propres voies,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'quoiqu\'il ne se soit pas laissé sans témoignage par Ses bienfaits, vous donnant du ciel des pluies et des saisons fertiles, remplissant vos cœurs d\'aliments et de joie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Et, tout en parlant ainsi, ils eurent grand peine à empêcher la foule de leur offrir un sacrifice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Mais il survint d\'Antioche et d\'Icône des Juifs qui gagnèrent la foule, et qui, après avoir lapidé Paul, le traînèrent hors de la ville, croyant qu\'il était mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'mais, les disciples s\'étant rangés en cercle autour de lui, il se leva et entra dans la ville, et le lendemain il partit avec Barnabas pour Derbe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Et, après avoir évangélisé dans cette ville et y avoir fait de nombreux disciples, ils revinrent à Lystre, et à Icône, et à Antioche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'fortifiant l\'âme des disciples, les exhortant à persister dans la foi, et leur apprenant que c\'est par beaucoup de tribulations qu\'il faut que nous entrions dans le royaume de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Puis, après avoir élu dans chaque église des anciens, ils les recommandèrent, par des prières accompagnées de jeûnes, au Seigneur en qui ils avaient cru.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Et, ayant traversé la Pisidie, ils vinrent en Pamphylie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'et, après avoir prêché la parole à Perge, ils descendirent à Attalie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'et de là ils firent voile pour Antioche, d\'où ils avaient été recommandés à la grâce de Dieu pour l\'œuvre qu\'ils venaient d\'accomplir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Puis, après qu\'ils furent arrivés et qu\'ils eurent réuni l\'église, ils racontaient tout ce que Dieu avait fait avec eux, et comment Il avait ouvert aux Gentils la porte de la foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Or, pendant qu\'ils faisaient un séjour assez prolongé auprès des disciples,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'quelques individus venus de Judée endoctrinaient les frères, en disant: « Si vous ne vous faites circoncire selon le rite de Moïse, vous ne pouvez être sauvés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Mais, comme il en résulta une querelle et une discussion assez vive entre Paul et Barnabas et eux, les frères résolurent que Paul, Barnabas et quelques autres d\'entre les leurs monteraient à Jérusalem auprès des apôtres et des anciens pour traiter cette question.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Après avoir donc été accompagnés par l\'église, ils traversèrent la Phénicie et la Samarie en racontant la conversion des Gentils et ils causèrent une grande joie à tous les frères;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'arrivés à Jérusalem, ils furent reçus par l\'église, les apôtres et les anciens, et ils racontèrent tout ce que Dieu avait fait avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Mais quelques membres du parti des pharisiens qui avaient embrassé la foi protestèrent, en disant: « Il faut les circoncire et exiger l\'observation de la loi de Moïse. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Et les apôtres et les anciens se réunirent pour examiner ce sujet;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'mais une vive discussion s\'étant engagée, Pierre se leva et leur dit: « Frères, vous savez que dès longtemps Dieu a fait Son choix parmi vous, pour que ce fût par ma bouche que les Gentils entendissent la parole de l\'Évangile et qu\'ils crussent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Et Dieu, qui connaît les cœurs, a témoigné pour eux en leur donnant l\'esprit saint comme à nous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'et Il n\'a fait aucune différence entre nous et eux, ayant purifié leurs cœurs par la foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Maintenant donc, pourquoi tentez-vous Dieu, dans le but de placer sur le col des disciples un joug que ni nos pères ni nous n\'avons pu porter?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Mais c\'est par la grâce du seigneur Jésus que nous croyons être sauvés, de la même manière qu\'eux, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Or toute l\'assemblée garda le silence; et ils entendaient Barnabas et Paul raconter tous les miracles et les prodiges que Dieu avait opérés par leur moyen au milieu des Gentils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Mais, après qu\'ils se furent tus, Jacques prit la parole, en disant: « Frères, écoutez-moi:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simon vous a raconté comment Dieu a d\'abord pris soin de tirer du milieu des Gentils un peuple qui portât Son nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'et avec ce fait s\'accordent les paroles des prophètes, selon qu\'il est écrit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '« Après cela Je reviendrai et Je rebâtirai le tabernacle de Dieu qui est tombé, et Je rebâtirai ses ruines et Je le relèverai,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'afin que le reste des hommes recherche le Seigneur, ainsi que toute les nations auxquelles est donné Mon nom, dit le Seigneur, qui fait ces choses, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'lesquelles sont connues dès longtemps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'C\'est pourquoi j\'estime qu\'il ne faut point importuner ceux des Gentils qui se convertissent à Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'mais leur écrire pour qu\'ils s\'abstiennent des souillures des idoles, et de l\'impudicité, et de tout animal étouffé, et du sang;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'car, dès les temps anciens, Moïse a, dans chaque ville, ses prédicateurs, puisqu\'on le lit chaque sabbat dans les synagogues. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Alors il parut bon aux apôtres et aux anciens, avec toute l\'église, de choisir parmi eux, pour les envoyer à Antioche avec Paul et Barnabas, Judas appelé Barsabbas, et Silas, hommes considérés parmi les frères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'après avoir écrit, pour être remis par eux: « Les apôtres et les anciens, frères, aux frères d\'entre les Gentils qui sont à Antioche, et en Syrie, et en Cilicie, salut!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Ayant appris que quelques-uns des nôtres vous ont troublés en vous tenant des discours qui ont bouleversé vos âmes, sans avoir reçu de nous aucun mandat,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'il nous a paru bon, après nous être réunis tous ensemble, de choisir des représentants pour vous les envoyer avec nos bien-aimés Barnabas et Paul,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'ces hommes qui exposent leurs vies pour le nom de notre seigneur Jésus-Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Nous avons donc envoyé Judas et Silas, qui vous diront aussi de bouche les mêmes choses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'car il a paru bon à l\'esprit saint et à nous de ne vous imposer aucune charge nouvelle, sauf sur ces points-ci, qui sont indispensables:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'c\'est que vous vous absteniez des viandes sacrifiées aux idoles, et de sang, et d\'animaux étouffés, et d\'impudicité, toutes choses contre lesquelles vous vous trouverez bien de vous tenir en garde. Portez-vous bien! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Eux donc, ayant pris congé, descendirent à Antioche, et, après avoir réuni la multitude, ils remirent la lettre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Or, après l\'avoir lue, ils furent réjouis de l\'encouragement qu\'elle renfermait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Judas et Silas, qui étaient aussi prophètes, parlèrent longuement aux frères pour les encourager et les fortifier;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'puis, après être demeurés un certain temps, ils prirent en paix congé des frères pour revenir auprès de ceux qui les avaient envoyés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, '[Or il parut bon à Silas de demeurer là, et Judas seul partit.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Mais Paul et Barnabas restèrent à Antioche, enseignant et annonçant, avec beaucoup d\'autres, la bonne nouvelle de la parole du Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Or, au bout de quelques jours, Paul dit à Barnabas: « Retournons visiter les frères dans toutes les villes où nous avons annoncé la parole du seigneur, pour voir dans quel état ils se trouvent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Or Barnabas voulait prendre aussi avec eux Jean qui est appelé Marc,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'mais Paul croyait convenable de ne point prendre avec eux celui qui s\'était détaché d\'eux en Pamphylie, et qui ne les avait pas secondés dans leur œuvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Or, il en résulta de l\'irritation, en sorte qu\'ils se séparèrent l\'un de l\'autre, et que Barnabas, prenant Marc avec lui, s\'embarqua pour l\'île de Chypre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Paul, de son côté, ayant fait choix de Silas, partit, après avoir été recommandé à la grâce du Seigneur par les frères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'et il parcourait la Syrie et la Cilicie, en fortifiant les églises;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'puis il se rendit aussi à Derbe, et à Lystre. Et voici, là se trouvait un disciple nommé Timothée, fils d\'une femme juive croyante, mais d\'un père grec,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'et auquel les frères de Lystre et d\'Icône rendaient un bon témoignage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Paul voulut l\'emmener avec lui, et, se l\'étant attaché, il le circoncit à cause des Juifs qui étaient dans ces lieux-là, car tous savaient que son père était grec.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Or, dans les villes qu\'ils traversaient, ils transmirent, pour qu\'on les observât, les décrets rendus par les apôtres et les anciens de Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Quant aux églises, elles s\'affermissaient donc dans la foi et croissaient en nombre de jour en jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Cependant ils traversèrent la Phrygie et le pays de Galatie, après avoir été empêchés par le saint esprit d\'annoncer la parole en Asie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'mais, étant arrivés près de la Mysie, ils se préparaient à entrer en Bithynie, et l\'esprit de Jésus ne le leur permit pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'alors, franchissant la Mysie, ils descendirent à Troas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'et une vision apparut de nuit à Paul: un Macédonien se tenait debout et le sollicitait en disant: « Passe en Macédoine pour nous secourir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Or, quand il eut vu la vision, nous cherchâmes aussitôt à parvenir en Macédoine, concluant que Dieu nous avait appelés à leur annoncer la bonne nouvelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Étant donc partis de Troas, nous cinglâmes rapidement vers la Samothrace, et le lendemain nous arrivâmes à Néapolis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'et de là à Philippes, qui est la première ville d\'un district de Macédoine, et une colonie. Nous restâmes quelques jours dans cette ville,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'et le jour du sabbat nous vînmes, hors de la porte, près d\'une rivière où nous pensions que se trouvait un lieu de prière, et nous étant assis nous parlions aux femmes qui y étaient rassemblées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Et une femme, nommée Lydie, marchande de pourpre de la ville de Thyatire, révérant Dieu, nous écoutait, et le Seigneur ouvrit son cœur pour qu\'elle prêtât attention à ce que disait Paul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Or, dès qu\'elle eut été baptisée ainsi que sa famille, elle nous sollicitait en disant: « Puisque vous avez jugé que j\'avais foi au Seigneur, venez demeurer chez moi; » et elle nous y contraignit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Or, il advint, pendant que nous nous acheminions vers le lieu de prière, qu\'une certaine servante possédée d\'un esprit ventriloque, laquelle procurait à ses maîtres un profit considérable par ses divinations, nous rencontra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Cette femme, se mettant à suivre Paul et nous, s\'écriait: « Ces hommes-là sont des serviteurs du Dieu très haut, qui vous annoncent le chemin du salut. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Or elle fit cela pendant plusieurs jours; mais Paul, importuné, se retourna et dit à l\'esprit: « Je t\'ordonne, au nom de Jésus-Christ, de sortir d\'elle; » et il sortit au moment même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Et ses maîtres, ayant vu que l\'espoir de leur profit s\'en était allé, se saisirent de Paul et de Silas, les traînèrent sur la place publique devant les magistrats,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'et, après les avoir amenés aux préteurs, ils dirent: « Ces hommes-là troublent notre ville; ce sont des Juifs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'et ils proclament des coutumes qu\'il ne nous est permis, ni de recevoir, ni de suivre, nous qui sommes Romains. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Et la foule se souleva aussi contre eux, et les préteurs, leur ayant fait arracher leurs vêtements, ordonnèrent qu\'on les battît de verges;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'puis, après leur avoir fait infliger plusieurs coups, ils les jetèrent en prison, en enjoignant au geôlier de les tenir sous bonne garde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'celui-ci, après avoir reçu cette injonction, les jeta dans la prison intérieure et fixa leurs pieds dans les ceps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Or, sur le minuit, Paul et Silas étant en prière, chantaient des hymnes à Dieu, et les prisonniers les entendaient;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'mais, tout à coup, il se fit un grand tremblement de terre, en sorte que les fondements de la prison en furent ébranlés; puis toutes les portes s\'ouvrirent et les chaînes de tous se détachèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Et le geôlier s\'étant éveillé, et ayant vu les portes de la prison ouvertes, tira son épée, et il était sur le point de se tuer, croyant que les prisonniers s\'étaient enfuis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'mais Paul l\'appela à haute voix en disant: « Ne te fais aucun mal; car nous sommes tous ici. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Et ayant demandé de la lumière, il s\'élança et se jeta tout tremblant aux pieds de Paul et de Silas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'et, les ayant fait sortir, il dit: « Seigneurs, que faut-il que je fasse pour être sauvé? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Et ils lui dirent: « Crois au seigneur Jésus, et tu seras sauvé, toi et ta famille; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'et ils lui annoncèrent la parole de Dieu, ainsi qu\'à tous ceux qui étaient dans sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'Et, les ayant pris avec lui à ce moment même de la nuit, il lava leurs plaies, et lui-même fut baptisé immédiatement ainsi que tous les siens;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'puis, les ayant conduits chez lui, il leur servit un repas, et il fut tout réjoui d\'avoir cru en Dieu avec toute sa famille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Cependant, quand le jour fut venu, les préteurs dépêchèrent leurs licteurs, en disant: « Élargis ces hommes-là. «');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Or le geôlier transmit le message à Paul, en disant: « Les préteurs ont envoyé l\'ordre de vous élargir; maintenant donc sortez, et allez en paix. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Mais Paul leur dit: « Après nous avoir fait battre de verges en public, sans jugement, nous qui sommes des Romains, ils nous ont jetés en prison, et maintenant ils nous font sortir secrètement! Non certes! Mais qu\'ils viennent eux-mêmes nous mettre en liberté. «');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Les licteurs rapportèrent ces paroles aux préteurs, et ils furent effrayés en apprenant qu\'ils étaient Romains,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'et ils vinrent les apaiser, et, après les avoir fait sortir, ils les prièrent de quitter la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Mais, quand ils furent sortis de la prison, ils entrèrent chez Lydie, et, après avoir vu et exhorté les frères, ils partirent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Or, après avoir traversé Amphipolis et Appollonie, ils arrivèrent à Thessalonique, où les Juifs avaient une synagogue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Or, selon l\'habitude de Paul, il se rendit auprès d\'eux, et, pendant trois sabbats, il discuta avec eux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'démontrant et établissant d\'après les Écritures qu\'il fallait que le Christ souffrît et ressuscitât des morts, et disant: « Ce Christ, c\'est le Jésus que je vous annonce. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Et quelques-uns d\'entre eux furent persuadés et se rallièrent à Paul et à Silas, ainsi qu\'une grande quantité des Grecs dévots, et bon nombre des premières dames de la ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Mais les Juifs, émus de jalousie, ayant recruté quelques mauvais sujets parmi les batteurs de pavé, et ayant provoqué un rassemblement, répandirent l\'agitation dans la ville, et, s\'étant portés vers la maison de Jason, ils cherchèrent à les amener devant le peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Mais, ne les ayant pas trouvés, ils traînèrent Jason et quelques frères devant les magistrats municipaux en criant: « Ceux qui ont bouleversé le monde sont aussi venus ici,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'et Jason les héberge; et tous ils agissent contre les édits de l\'empereur en disant qu\'ils ont un autre roi, qui est Jésus. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Or ils émurent la foule ainsi que les magistrats municipaux qui entendaient ces paroles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'et, après avoir exigé de Jason et des autres la caution nécessaire, ils les laissèrent aller.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Mais les frères se hâtèrent de faire partir de nuit pour Bérée Paul et Silas, qui, à leur arrivée, se rendirent dans la synagogue des Juifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Or, ces derniers étaient d\'un plus noble caractère que ceux de Thessalonique, et ils accueillirent la parole avec beaucoup d\'ardeur, examinant chaque jour les Écritures, pour voir si ce qu\'on leur disait était exact;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'plusieurs donc d\'entre eux crurent, ainsi que des femmes grecques de distinction et bon nombre d\'hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Mais, dès que les Juifs de Thessalonique surent que Paul prêchait également à Bérée la parole de Dieu, ils s\'y rendirent pour y soulever et y agiter aussi la foule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Alors les frères firent immédiatement partir Paul, pour qu\'il gagnât la mer; Silas et Timothée restèrent à Bérée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Or ceux qui escortaient Paul le conduisirent jusques à Athènes, et, après avoir reçu, pour Silas et Timothée, l\'ordre qu\'ils eussent à venir le rejoindre le plus tôt possible, ils s\'en retournèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Mais, pendant que Paul les attendait à Athènes, son esprit s\'irritait au dedans de lui, à la vue de cette ville toute remplie d\'idoles. En conséquence, tandis que, d\'un côté,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'il discutait dans la synagogue avec les Juifs et les dévots, et chaque jour, dans la place publique, avec les gens qu\'il y rencontrait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'd\'un autre côté, quelques philosophes, tant épicuriens que stoïciens, conféraient aussi avec lui, et quelques-uns disaient: « Que veut donc dire ce bavard? » et d\'autres: « Il paraît que c\'est un prédicateur de divinités étrangères; » parce qu\'il annonçait Jésus et la résurrection.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Et s\'étant saisis de lui, ils le conduisirent sur l\'Aréopage, en disant: « Pouvons-nous savoir quelle est cette nouvelle doctrine que tu prêches?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Car tu nous fais entendre des choses étranges; nous désirons donc savoir ce que cela peut être. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Or tous les Athéniens, et les étrangers qui résident parmi eux, ne passaient leur temps à autre chose qu\'à raconter ou à ouïr ce qu\'il y avait de plus nouveau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Paul s\'étant placé au milieu de l\'Aréopage dit: « Athéniens, je sais que vous êtes à tous égards on ne peut plus religieux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'car, en faisant la revue et l\'examen de vos objets sacrés, j\'ai même découvert un autel sur lequel on avait inscrit: au dieu inconnu. Ce que vous révérez donc sans le connaître, c\'est là ce que je vous annonce:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Le Dieu qui a créé le monde et tout ce qui s\'y trouve, Lui qui est le Maître du ciel et de la terre, n\'habite point dans des sanctuaires construits de main d\'homme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'et Il n\'est point non plus servi par des mains humaines, comme s\'il avait besoin de rien, Lui qui donne à tous la vie, la respiration et toutes choses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'Il a fait aussi que, sorties d\'un seul, toutes les nations des hommes, habitassent sur toute la surface de la terre, ayant fixé, selon des périodes déterminées, les bornes mêmes de leur habitation,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'afin qu\'elles cherchassent Dieu, pour voir si, en Le cherchant à tâtons, elles Le trouveraient, quoiqu\'il ne soit pas loin de chacun de nous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'car c\'est en Lui que nous vivons, que nous nous mouvons et que nous sommes, comme l\'ont dit aussi quelques-uns de nos poètes: « Car c\'est de Lui que nous sommes aussi la race; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'étant ainsi la race de Dieu, nous ne devons pas croire que la Divinité soit semblable à de l\'or, ou à de l\'argent, ou à de la pierre, sculptés par l\'art et l\'invention de l\'homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Dieu, ne tenant donc pas compte des temps d\'ignorance, fait maintenant savoir aux hommes que tous, en tous lieux, aient à se repentir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'puisqu\'Il a fixé un jour dans lequel Il doit juger la terre avec justice par l\'homme qu\'il a désigné; ce dont Il a donné à tous une garantie en le ressuscitant des morts... »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Mais, lorsqu\'ils entendirent parler d\'une résurrection des morts, les uns raillaient, tandis que les autres dirent: « Nous t\'entendrons sur ce sujet encore une autre fois. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'Ce fut ainsi que Paul sortit du milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Mais quelques hommes s\'étant attachés à lui crurent; parmi eux se trouvait Denys l\'Aréopagite ainsi qu\'une femme nommée Damaris, et d\'autres avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'S\'étant après cela éloigné d\'Athènes, il vint à Corinthe,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'et y ayant trouvé un certain Juif, nommé Aquilas, originaire du Pont, récemment arrivé d\'Italie avec Priscilla sa femme, à cause de l\'injonction faite à tous les Juifs de quitter Rome, il s\'associa à eux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'et, comme ils exerçaient le même métier, il habita avec eux et ils travaillaient ensemble; ils étaient en effet faiseurs de tentes de leur métier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Cependant il discourait dans la synagogue chaque sabbat, et il persuadait Juifs et Grecs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Or, quand Silas et Timothée arrivèrent de Macédoine, Paul était tout occupé de la parole, et attestait aux Juifs que Jésus était le Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'mais comme ceux-ci lui résistaient et l\'injuriaient, il secoua ses vêtements et leur dit: « Que votre sang retombe sur votre tête; pour moi j\'en suis net; dès ce moment j\'irai auprès des Gentils. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Et, sortant de là, il se rendit dans la maison d\'un nommé Titius Justus, adorateur de Dieu, dont la maison était contiguë à la synagogue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Cependant Crispus, le chef de la synagogue, crut au seigneur avec toute sa famille; et plusieurs Corinthiens qui aimaient l\'entendre croyaient et recevaient le baptême.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Or le Seigneur, dans une vision nocturne, dit à Paul: « Ne crains point, mais parle et ne te tais point,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'parce que je suis avec toi, et que personne ne se jettera sur toi pour te maltraiter, car je possède un peuple nombreux dans cette ville-ci. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Et il fit un séjour d\'un an et six mois en enseignant parmi eux la parole de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Or, pendant que Gallion était proconsul de l\'Achaïe, les Juifs se soulevèrent unanimement contre Paul, et ils l\'amenèrent devant le tribunal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'en disant: « Celui-ci persuade les hommes d\'adorer Dieu contrairement à la loi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Mais, au moment où Paul allait ouvrir la bouche, Gallion dit aux Juifs: « S\'il s\'agissait d\'un crime ou d\'un délit, ô Juifs, j\'aurais naturellement accueilli votre plainte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'mais, puisqu\'il s\'agit de questions relatives à une doctrine, à des noms propres, et à votre loi, vous aviserez vous-mêmes; pour moi, je ne veux pas me constituer juge de ces choses-là. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Et il les chassa du tribunal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Mais, s\'étant tous saisis de Sosthène le chef de la synagogue, ils le frappaient devant le tribunal; et de tout cela Gallion ne prenait aucun souci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Cependant Paul, après avoir encore fait un long séjour, prit congé des frères, et s\'embarqua pour la Syrie, et avec lui Priscilla et Aquilas, après s\'être fait raser la tête à Cenchrées, car il avait fait un vœu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Or, quand ils furent arrivés à Éphèse, il les y laissa, tandis qu\'étant entré lui-même dans la synagogue, il discuta avec les Juifs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'et, comme ils lui demandaient de prolonger son séjour, il n\'y consentit pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'mais, après avoir pris congé d\'eux en disant: « Je reviendrai derechef auprès de vous, si Dieu le veut, » il partit d\'Éphèse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'et, étant débarqué à Césarée, il monta saluer l\'église et redescendit ensuite à Antioche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Au bout d\'un certain temps, il partit, et parcourut successivement le pays de Galatie et la Phrygie, fortifiant tous les disciples.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Cependant un Juif, nommé Apollos, originaire d\'Alexandrie, homme éloquent et très versé dans les Écritures, arriva à Éphèse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Il avait été instruit de la doctrine du seigneur, et était d\'un esprit plein de ferveur; aussi prêchait-il et enseignait-il exactement ce qui concernait Jésus, quoiqu\'il ne connût que le baptême de Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'et il se mit à parler librement dans la synagogue. Mais Priscilla et Aquilas l\'ayant entendu le prirent avec eux et lui exposèrent plus exactement la doctrine de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Cependant, comme il voulait passer en Achaïe, les frères, après l\'y avoir encouragé, écrivirent aux disciples de lui faire un bon accueil. Une fois arrivé il se rendit très utile par la grâce de Dieu à ceux qui avaient cru,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'car il réfutait vigoureusement les Juifs en public, en démontrant par les Écritures que Jésus était le Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Or il advint, pendant qu\'Apollos était à Corinthe, que Paul, après avoir parcouru le haut pays, arriva à Éphèse et y trouva quelques disciples auxquels il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, '« Avez-vous reçu le saint esprit, après avoir cru? » Mais ils lui dirent: « Nous n\'avons pas même ouï dire qu\'il existât un esprit saint. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Et il dit: « De quel baptême avez-vous donc été baptisés? » Et ils dirent: « Du baptême de Jean. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Mais Paul dit: « Jean a baptisé d\'un baptême de repentance, en disant au peuple de croire en celui qui venait après lui, c\'est-à-dire en Jésus. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Ce qu\'ayant ouï, ils furent baptisés au nom du seigneur Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'et, après que Paul leur eut imposé les mains, l\'esprit saint vint sur eux, et ils parlaient en langues, et ils prophétisaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Or ils étaient en tout environ douze hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Cependant, après être entré dans la synagogue, il y parla librement durant trois mois, discutant avec persuasion sur le royaume de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'mais comme quelques-uns se montraient endurcis et incrédules, et calomniaient la doctrine en présence de la multitude, il s\'éloigna d\'eux, sépara les disciples, et discourait chaque jour dans l\'école de Tyrannus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Or ceci dura deux ans, en sorte que tous ceux qui habitaient l\'Asie entendirent la parole du seigneur, tant Juifs que Grecs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Et Dieu faisait par l\'entremise de Paul des miracles qui n\'étaient pas ordinaires;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'c\'est ainsi qu\'on plaçait sur les malades des linges ou des mouchoirs qui avaient touché sa peau, et les maladies les quittaient et les esprits malins sortaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Mais quelques-uns aussi des exorcistes juifs ambulants essayèrent d\'invoquer sur ceux qui avaient des esprits malins le nom du seigneur Jésus en disant: « Je vous conjure par Jésus que Paul prêche! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, '(Ceux qui faisaient cela étaient sept fils d\'un certain Scévas grand prêtre juif.)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Mais l\'esprit malin leur répliqua: » Je connais bien Jésus, et je sais qui est Paul; mais vous, qui êtes-vous? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Et l\'homme dans lequel se trouvait l\'esprit malin, sautant sur eux, s\'empara de l\'un et de l\'autre, et les maltraita de telle sorte qu\'ils s\'enfuirent de cette maison-là nus et blessés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Or, ce fait vint à la connaissance de tous les Juifs et Grecs qui habitaient Ephèse, et tous furent saisis de crainte, et le nom du seigneur Jésus était magnifié,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'et plusieurs de ceux qui avaient cru venaient confesser et dénoncer leurs actions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Or, un très grand nombre de ceux qui avaient pratiqué les arts curieux ayant apporté leurs livres, les brûlaient en présence de tous; et ils en supputèrent le prix, et ils trouvèrent qu\'il se montait à cinquante mille drachmes d\'argent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'C\'est ainsi que, par la puissance du Seigneur, la parole croissait et prévalait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Mais, après que ces choses eurent eu lieu, Paul mit dans son esprit de se rendre à Jérusalem, après avoir traversé la Macédoine et l\'Achaïe, disant: « Après que j\'aurai été là, il faut aussi que je voie Rome. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Or, ayant dépêché en Macédoine deux de ses auxiliaires, Timothée et Éraste, il prolongea lui-même son séjour en Asie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Ce fut à cette époque que survint un tumulte assez grave à propos de la doctrine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'En effet un nommé Démétrius, orfèvre, procurait aux artistes, par la fabrication de sanctuaires de Diane, un profit considérable;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'les ayant rassemblés, ainsi que les ouvriers employés dans ce genre d\'industrie, il dit: « O hommes, vous savez que de ce profit découle notre bien-être,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'et vous voyez et entendez que non seulement à Éphèse, mais dans presque toute l\'Asie, ce Paul a débauché par persuasion une foule considérable, en disant: « Ce ne sont pas des dieux, ceux qui se font à la main. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Or, ce n\'est pas seulement cette branche de travail que nous sommes menacés de voir tomber en discrédit, mais c\'est encore le temple de la grande déesse Diane qui risque d\'être tenu pour rien, et d\'être bientôt dépouillé de la majesté de celle que vénère toute l\'Asie et la terre entière. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'En entendant ces paroles, ils furent remplis de courroux, et ils s\'écriaient: « Grande est la Diane des Éphésiens! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Et la ville fut remplie de confusion, et ils se portèrent tous ensemble vers le théâtre, en entraînant Gaïus et Aristarque, Macédoniens, compagnons de voyage de Paul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Mais, comme Paul voulait se présenter devant le peuple, les disciples ne le lui permirent pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'et quelques-uns des Asiarques, qui étaient de ses amis, le firent aussi prier de ne pas se rendre dans le théâtre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Cependant, tandis que les uns criaient une chose et les autres une autre, (car l\'assemblée était en confusion, et la plupart ne savaient pas pourquoi ils s\'étaient réunis),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'on tira du milieu de la foule Alexandre que les Juifs mettaient en avant; et Alexandre ayant fait signe de la main voulait adresser au peuple une apologie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'mais, lorsqu\'on eut appris qu\'il était Juif, tous, d\'une seule voix, crièrent pendant environ deux heures: « Grande est la Diane des Éphésiens! Grande est la Diane des Éphésiens! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Cependant le secrétaire ayant apaisé la multitude, dit: « Éphésiens! quel est l\'homme qui ignore que la ville des Éphésiens est la néocore de la grande Diane et de son simulacre tombé du ciel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Puis donc que ces choses sont incontestables, il faut que vous vous apaisiez et que vous n\'agissiez pas à l\'étourdie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'car vous avez traduit ici ces hommes qui ne sont coupables, ni d\'avoir pillé le temple, ni d\'avoir blasphémé notre déesse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'si donc Démétrius et les artistes qu\'il emploie ont quelque plainte à faire contre quelqu\'un, les assises se tiennent et des proconsuls sont présents; qu\'ils débattent contradictoirement leur accusation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Mais, s\'il s\'agit pour vous d\'une question d\'un autre ordre, elle se résoudra dans l\'assemblée légale;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'nous risquons en effet d\'être accusés de sédition pour ce qui se passe aujourd\'hui, car il n\'existe aucun motif qui nous permette de rendre compte de ce rassemblement. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, 'Après avoir ainsi parlé il congédia l\'assemblée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Mais, lorsque le tumulte eut cessé, Paul, ayant fait appeler les disciples, leur adressa des exhortations, et, après leur avoir dit adieu, il partit pour se rendre en Macédoine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Quand il eut parcouru ce pays-là, et qu\'il leur eut adressé de nombreuses exhortations, il passa en Grèce,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'et, après trois mois de séjour, une embûche que lui tendirent les Juifs au moment où il allait s\'embarquer pour la Syrie, lui fit prendre le parti de revenir par la Macédoine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Il était accompagné par Sopatros fils de Pyrrhus de Bérée, par les Thessaloniciens Aristarque et Secundus, par Gaïus de Derbe et Timothée, et par les Asiates Tychique et Trophime.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Ceux-ci ayant pris les devants nous attendirent à Troas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Pour nous, nous nous embarquâmes à Philippes, après les jours des pains sans levain, et nous vînmes les rejoindre au bout de cinq jours à Troas, où nous séjournâmes sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Or, le premier jour de la semaine, comme nous nous étions réunis pour rompre le pain, Paul discourait avec eux, comme devant partir le lendemain, et il prolongea son discours jusques à minuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Or il y avait de nombreuses lampes dans la chambre haute où nous étions réunis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'et un jeune homme, nommé Eutyche, qui était assis sur la fenêtre, fut saisi d\'un profond sommeil pendant que Paul prolongeait son discours, et, entraîné par le sommeil, il tomba du troisième étage en bas, et il fut relevé mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Mais Paul étant descendu se jeta sur lui, et l\'ayant pris à bras-le-corps, il dit: « Ne vous troublez pas; car son âme est en lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Puis, étant remonté et ayant rompu le pain et pris part au repas, il conversa longtemps encore jusques à l\'aube, après quoi il partit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Cependant on avait ramené l\'enfant vivant, ce qui ne fut pas une médiocre consolation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Pour nous, ayant pris les devants avec le navire, nous nous embarquâmes pour Assos, où nous devions reprendre Paul; car cela avait été ainsi décidé, lui-même devant faire la route à pied.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Or, lorsqu\'il nous eut rejoints à Assos, nous touchâmes, après l\'avoir pris, à Mitylène,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'et, après en être partis, nous arrivâmes le lendemain en face de Chios, le soir nous abordâmes à Samos, et le jour suivant nous parvînmes à Milet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Paul avait en effet résolu de passer devant Éphèse sans s\'y arrêter, afin de ne pas perdre de temps en Asie; car il faisait diligence, afin de se trouver, si cela lui était possible, à Jérusalem le jour de la Pentecôte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Cependant de Milet il envoya à Éphèse, pour faire venir auprès de lui les anciens de l\'église,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'et, lorsqu\'ils furent arrivés auprès de lui, il leur dit: « Vous savez comment, dès le premier jour où je suis arrivé en Asie, je me suis, pendant tout le temps, comporté avec vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'm\'asservissant au seigneur en toute humilité, au milieu des larmes et des épreuves qui me sont advenues par les embûches des Juifs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'vous savez comment je n\'ai rien supprimé de ce qui était utile, pour me dispenser de vous prêcher et de vous enseigner en public et de maison en maison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'annonçant, soit aux Juifs, soit aux Grecs, la repentance envers Dieu et la foi en notre seigneur Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Et maintenant, voici, me trouvant, quant à moi, contraint par l\'Esprit, je me rends à Jérusalem, sans savoir ce qui m\'y adviendra,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'si ce n\'est que, de ville en ville, l\'esprit saint m\'atteste que des chaînes et des tribulations m\'attendent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Mais je n\'estime pas que ma vie vaille pour moi-même la peine d\'en parler, pourvu que je puisse accomplir ma course et le ministère que j\'ai reçu du seigneur Jésus d\'annoncer la bonne nouvelle de la grâce de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Et maintenant, voici, je sais que vous ne verrez plus mon visage, vous tous parmi lesquels j\'ai vécu en prêchant le royaume;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'c\'est pourquoi je vous déclare aujourd\'hui, que je suis net du sang de tous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'car je ne me suis point soustrait à l\'obligation de vous annoncer tout le conseil de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Veillez sur vous-mêmes et sur tout le troupeau, au milieu duquel l\'esprit saint vous a établis évêques, pour paître l\'Église de Dieu, qu\'il S\'est acquise par Son propre sang,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'car je sais qu\'après mon départ s\'introduiront parmi vous des loups dangereux, qui n\'épargneront pas le troupeau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'et que, du milieu de vous, surgiront des hommes qui prêcheront des doctrines perverses pour entraîner les disciples après eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'C\'est pourquoi veillez, vous rappelant que, pendant trois ans, je n\'ai pas cessé, nuit et jour, d\'exhorter avec larmes chacun de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Et maintenant je vous remets au Seigneur et à la parole de Sa grâce, lui qui peut édifier et donner une part d\'héritage parmi tous ceux qui ont été sanctifiés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Je n\'ai convoité ni l\'argent, ni l\'or, ni le vêtement de personne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'vous savez vous-mêmes que ce sont les mains que voilà qui ont pourvu à mes besoins et à ceux des personnes qui étaient avec moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'je vous ai montré qu\'il faut, en travaillant ainsi, ménager les faibles et se rappeler les paroles du seigneur Jésus, car il a dit lui-même: « Il y a plus de bonheur à donner qu\'à recevoir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Après avoir ainsi parlé, il se jeta à genoux et pria avec eux tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Et ils versèrent tous d\'abondantes larmes, et, s\'étant jetés au cou de Paul, ils l\'embrassaient tendrement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 's\'affligeant surtout de ce qu\'il avait dit qu\'ils ne verraient plus son visage, et ils l\'accompagnèrent jusques au navire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Et, lorsque nous eûmes levé l\'ancre, après nous être arrachés d\'auprès d\'eux, nous cinglâmes droit vers Cos, et le jour suivant vers Rhodes, et de là vers Patara.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Et ayant trouvé un navire en partance pour la Phénicie, nous nous y embarquâmes, et nous partîmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Ayant ensuite passé en vue de l\'île de Chypre et l\'ayant laissée sur notre gauche, nous poursuivîmes notre route vers la Syrie et nous abordâmes à Tyr; car c\'était en ce lieu-là que le navire devait décharger sa cargaison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Or nous demeurâmes là sept jours après avoir découvert les disciples, qui dirent à Paul, au nom de l\'Esprit, de ne pas monter à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Mais, quand nous eûmes atteint le terme de notre séjour, nous partîmes pour nous mettre en route, accompagnés d\'eux tous avec femmes et enfants, jusques au dehors de la ville, et, après nous être jetés à genoux sur le rivage et avoir prié,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'nous prîmes congé les uns des autres, et nous montâmes sur le navire, tandis qu\'eux-mêmes retournèrent chez eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Pour nous, après avoir achevé la traversée, nous arrivâmes de Tyr à Ptolemaïs, et, ayant salué les frères, nous demeurâmes un jour auprès d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Le lendemain nous partîmes pour Césarée, et, étant entrés dans la maison de Philippe l\'évangéliste, qui était un des sept, nous demeurâmes chez lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'or il avait quatre filles vierges qui prophétisaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Après que nous y fûmes demeurés plusieurs jours, un certain prophète, nommé Agabus, vint de Judée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'et, s\'étant rendu auprès de nous et ayant pris la ceinture de Paul, il s\'en lia les pieds et les mains, et dit: « Voici ce que dit l\'esprit saint: L\'homme auquel appartient cette ceinture, les Juifs de Jérusalem le lieront de la même manière et le livreront aux mains des Gentils. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Or, lorsque nous eûmes entendu ces paroles, nous et les gens de l\'endroit nous l\'exhortâmes à ne pas monter à Jérusalem.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Alors Paul répliqua: « A quoi bon verser des larmes et me briser le cœur? Car, pour moi, je suis tout prêt, non seulement à être enchaîné, mais encore à mourir à Jérusalem pour le nom du seigneur Jésus. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Et, comme il ne se laissait pas persuader, nous nous tînmes tranquilles, en disant: « Que la volonté du Seigneur se fasse! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Or, au bout de ce temps-là, après avoir fait nos préparatifs, nous montâmes à Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'et quelques disciples de Césarée nous accompagnèrent et nous conduisirent chez un certain Mnasos de Chypre, ancien disciple, chez lequel nous devions loger.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Or, quand nous fûmes arrivés à Jérusalem, les frères nous accueillirent avec joie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'et le lendemain Paul se rendit avec nous auprès de Jacques, et tous les anciens s\'y trouvèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Et, après les avoir salués, il racontait en détail ce que Dieu avait fait au milieu des Gentils par son ministère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Quant à eux, après l\'avoir entendu, ils glorifiaient Dieu, et ils lui dirent: « Tu vois, frère, combien il y a parmi les Juifs de myriades de gens qui ont cru, et tous ils sont zélateurs de la loi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'or, ils ont été informés, en ce qui te concerne, que tu enseignes à tous les Juifs qui se trouvent parmi les Gentils à se détacher de Moïse, leur disant de ne point circoncire leurs enfants et de ne point se conformer aux coutumes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Quel parti faut-il donc prendre? On apprendra certainement que tu es arrivé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Fais donc ce que nous allons te dire. Nous avons quatre hommes qui se sont imposé un vœu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'prends-les avec toi et associe-toi à leur vœu, puis subviens à leur dépense, afin qu\'ils puissent se faire raser la tête; et tous connaîtront que ce dont ils ont été informés à ton sujet ne signifie rien, mais que, toi aussi, tu te comportes en observateur de la loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Quant aux Gentils qui ont cru, nous avons fait savoir par des députés que nous avions décidé qu\'ils devaient s\'abstenir de viandes sacrifiées aux idoles, de sang, d\'animaux étouffés et d\'impudicité. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Alors Paul, ayant pris ces hommes avec lui, et s\'étant associé à leur vœu, se rendit dès le lendemain avec eux au temple, pour dénoncer la durée des jours du vœu, au bout desquels l\'offrande serait offerte pour chacun d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Or, lorsque les sept jours étaient sur le point d\'expirer, les Juifs venus d\'Asie, l\'ayant vu dans le temple, soulevèrent toute la foule et mirent les mains sur lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'en criant: « Israélites, au secours! Voici l\'homme qui, non content de prêcher partout et devant tous contre le peuple, la loi et ce lieu-ci, vient encore d\'introduire des Grecs dans le temple et de souiller ce saint lieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'En effet, ils avaient vu auparavant Trophime d\'Éphèse dans la ville avec lui et ils croyaient que Paul l\'avait fait entrer dans le temple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Et toute la ville fut en émoi, et il y eut un rassemblement populaire, et, s\'étant saisis de Paul, ils le traînèrent hors du temple, dont les portes furent aussitôt fermées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Pendant qu\'ils cherchaient à le mettre à mort, la nouvelle que toute la ville de Jérusalem était en confusion, parvint au commandant de la cohorte');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'qui, prenant aussitôt des soldats et des centurions, descendit précipitamment vers eux; mais, dès qu\'ils virent le commandant et ses soldats, ils cessèrent de frapper Paul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Alors le commandant s\'étant approché le fit saisir et ordonna qu\'on le chargeât d\'une double chaîne, puis il demandait qui il était et ce qu\'il avait fait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'mais dans la foule les uns criaient une chose et les autres une autre, et, comme il ne pouvait rien apprendre de certain à cause du tumulte, il ordonna qu\'on le conduisît au quartier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Mais, quand il fut sur les escaliers, il dut être porté par les soldats à cause de la violence delà foule,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'car la multitude du peuple suivait en criant: « A mort! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Quand Paul fut sur le point d\'entrer au quartier, il dit au commandant: « M\'est-il permis de te dire quelque chose? » L\'autre lui dit: « Tu sais le grec?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Tu n\'es donc pas cet Égyptien qui naguère s\'est révolté et a conduit au désert les quatre mille sicaires. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Mais Paul dit: « Pour moi, je suis un Juif de Tarse, citoyen d\'une ville de Cilicie qui n\'est pas sans renom; cependant, je te prie, permets-moi de parler au peuple. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Cette permission accordée, Paul, se levant debout sur les escaliers, fit signe de la main au peuple, et un profond silence s\'étant établi, il prit la parole en langue hébraïque, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, '« Frères et pères, écoutez la justification que je viens vous présenter. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Quand ils entendirent qu\'il les haranguait en hébreu, ils redoublèrent de tranquillité, et il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, '« Je suis Juif, né à Tarse en Cilicie, mais élevé dans cette ville-ci, où j\'ai été exactement instruit aux pieds de Gamaliel dans la loi de nos pères, et où je me suis montré zélateur de Dieu comme tous vous l\'êtes aujourd\'hui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'aussi ai-je persécuté cette doctrine à mort, enchaînant et jetant en prison hommes et femmes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'comme le grand prêtre et tout le corps des anciens m\'en rendaient aussi le témoignage. En outre, ayant reçu d\'eux des lettres pour les frères, je m\'en allais à Damas, afin de ramener aussi à Jérusalem, chargés de chaînes, ceux qui se trouvaient là, pour qu\'ils fussent punis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'mais, pendant que j\'étais en route, et comme j\'approchais de Damas, tout à coup, vers midi, une grande lumière rayonna du ciel tout autour de moi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'et je tombai sur le sol, et j\'entendis une voix qui me disait: « Saul, Saul, pourquoi me persécutes-tu? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Et je répliquai: « Qui es-tu, Seigneur? » Et il me dit: « Je suis Jésus le Nazoréen que tu persécutes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Or ceux qui étaient avec moi virent bien la lumière, mais ils n\'entendirent pas la voix de celui qui me parlait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Et je dis: « Que dois-je faire, Seigneur? » Et le Seigneur me dit: « Lève-toi, et rends-toi à Damas, et là on te parlera de tout ce qu\'il t\'est ordonné de faire. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Or, comme je ne voyais rien à cause de l\'éclat de cette lumière, ce fut en me conduisant par la main que mes compagnons me firent entrer à Damas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Cependant un certain Ananias, homme pieux selon la loi et auquel tous les Juifs de l\'endroit rendaient un bon témoignage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'vint auprès de moi, et, s\'étant approché, il me dit: « Saul, mon frère, regarde. » Et à ce moment même je le regardai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Puis il me dit: « Le Dieu de nos pères t\'a élu d\'avance pour que tu connusses Sa volonté, que tu visses le juste, et que tu entendisses les paroles de sa bouche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'parce que tu lui serviras de témoin auprès de tous les hommes pour ce que tu as vu et entendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Et maintenant pourquoi tardes-tu? Lève-toi pour recevoir dans le baptême l\'ablution de tes péchés, en invoquant son nom. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Or, lorsque je fus retourné à Jérusalem, il m\'advint, comme je priais dans le temple, de me trouver en extase,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'et de le voir qui me disait: « Hâte-toi, et sors promptement de Jérusalem, parce qu\'ils ne recevront pas ton témoignage sur moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Et je dis: « Seigneur, ils savent que je faisais emprisonner et battre de verges dans les synagogues ceux qui croient en toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'et, lorsque fut versé le sang d\'Etienne ton témoin, moi-même j\'étais aussi présent, applaudissant avec les autres et gardant les vêtements de ceux qui le faisaient mourir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Et il me dit: « Va, car je t\'enverrai au loin vers les Gentils... »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Mais, après l\'avoir écouté jusques à cette parole, ils élevèrent la voix en disant: « Ôte cet individu de dessus la terre, car il ne devrait pas vivre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Et comme ils poussaient des cris, et se débarrassaient de leurs vêtements, et lançaient de la poussière en l\'air,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'le commandant ordonna qu\'on le fît entrer au quartier, après avoir enjoint qu\'on lui donnât la question à coups de fouet, afin d\'apprendre pour quel motif ils criaient ainsi contre lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Mais, lorsqu\'on l\'eut exposé aux lanières, Paul dit au centurion qui se trouvait présent: « Est-ce qu\'il vous est permis de flageller un citoyen romain, et encore sans jugement? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Ce que le centurion ayant ouï, il vint au commandant lui en faire rapport en disant: « Que vas-tu faire? Car cet homme est Romain. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Et le commandant étant venu lui dit: « Dis-moi, es-tu Romain? » Et il dit: « Oui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Sur quoi le commandant reprit: « Pour moi, c\'est au prix d\'une grosse somme que j\'ai acquis ce titre de citoyen. » Et Paul dit: « Quant à moi, je le possède par ma naissance. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'En conséquence ceux qui devaient lui donner la question s\'éloignèrent immédiatement de lui, et le commandant fut effrayé en réfléchissant qu\'il était Romain, et qu\'il l\'avait fait charger de chaînes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Mais le lendemain, voulant savoir exactement à quoi s\'en tenir sur ce dont il était accusé par les Juifs, il lui fit ôter ses chaînes, et ordonna que les grands prêtres et tout le sanhédrin se rassemblassent, et, ayant fait descendre Paul avec lui, il le plaça au milieu d\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Et Paul, fixant ses regards sur le sanhédrin, dit: « Frères, j\'ai, jusques à ce jour, servi Dieu en toute bonne conscience... »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Mais le grand prêtre Ananias ordonna à ceux qui se trouvaient près de lui de le frapper sur la bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Alors Paul lui dit: « C\'est toi que Dieu frappera, muraille recrépie! Eh quoi! Tu sièges pour me juger selon la loi, et tu la transgresses en ordonnant que l\'on me frappe! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Or les assistants dirent: « C\'est le grand prêtre de Dieu que tu insultes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Et Paul dit: « J\'ignorais, frères, que ce fût le grand prêtre, car il est écrit: Tu ne diras pas de mal contre un chef de ton peuple. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Cependant, comme Paul savait que l\'un des partis tenait pour les sadducéens, et l\'autre pour les pharisiens, il s\'écria au milieu du sanhédrin: « Frères, je suis pharisien, fils de pharisiens, c\'est à cause de l\'espérance et de la résurrection des morts que je suis mis en jugement. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Or, dès qu\'il eut dit cela, il s\'éleva une altercation entre les pharisiens et les sadducéens, et la multitude fut divisée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'En effet, les sadducéens disent qu\'il n\'y a point de résurrection, ni d\'ange, ni d\'esprit, tandis que les pharisiens admettent les deux choses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'or il se fit une violente clameur, et quelques scribes du parti des pharisiens s\'étant levés prenaient sa défense en disant: « Nous ne trouvons rien qui soit mal chez cet homme-là. Qui sait si ce n\'est point un esprit qui lui a parlé, ou un ange? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Mais, comme il s\'engageait une vive altercation, le commandant, craignant qu\'ils ne missent Paul en pièces, ordonna à sa troupe de descendre et de l\'arracher du milieu d\'eux, pour le ramener au quartier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'La nuit suivante, le Seigneur étant venu à lui, dit: « Prends courage; car de la même manière que tu as, dans Jérusalem, rendu témoignage à ma cause, de même il faut que tu rendes aussi témoignage dans Rome. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Lorsque le jour eut paru, les Juifs ayant formé un complot s\'engagèrent, sous peine d\'anathème, à ne manger ni ne boire jusques à ce qu\'ils eussent mis Paul à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Or, ceux qui formèrent cette conjuration étaient plus de quarante,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'lesquels, s\'étant rendus auprès des grands prêtres et des anciens, dirent: « Nous nous sommes engagés, sous peine d\'anathème, à ne prendre aucune nourriture jusques à ce que nous ayons mis Paul à mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'maintenant donc adressez-vous avec le sanhédrin au commandant, afin qu\'il l\'amène devant vous, sous prétexte que vous voulez examiner plus à fond son affaire; quant à nous, nous sommes prêts à le tuer avant qu\'il approche. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Mais le fils de la sœur de Paul, ayant eu connaissance de ce guet-apens, se rendit au quartier et en informa Paul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Et Paul ayant appelé un des centurions dit: « Conduis ce jeune homme auprès du commandant, car il a un rapport à lui faire. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'L\'autre l\'ayant donc pris avec lui le conduisit auprès du commandant et dit: « Le prisonnier Paul m\'a fait venir pour me prier de t\'amener ce jeune homme qui a quelque chose à te dire. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Le commandant l\'ayant pris par la main et tiré à part lui demanda: « Quel rapport as-tu à me faire? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Et il dit: « Les Juifs ont comploté de s\'adresser à toi, afin que demain tu amènes Paul devant le sanhédrin, comme devant te livrer, en ce qui le concerne, à une enquête plus approfondie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'n\'acquiesce donc pas à leur demande, car plus de quarante d\'entre eux lui dressent un guet-apens, lesquels se sont engagés, sous peine d\'anathème, à ne manger ni ne boire jusques à ce qu\'ils l\'aient fait périr, et maintenant ils sont tout prêts, attendant ta réponse. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Le commandant renvoya donc le jeune homme, après lui avoir défendu de divulguer à personne qu\'il lui avait fait cette déclaration;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'et ayant fait venir deux des centurions, il dit: « Tenez deux cents soldats prêts à partir pour Césarée, à la troisième heure de nuit, ainsi que soixante et dix cavaliers et deux cents hommes de troupes légères, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'ajoutant qu\'ils eussent aussi à préparer des bêtes de somme, afin de pouvoir transporter Paul en sûreté auprès de Félix le gouverneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'auquel il avait écrit une lettre dont voici le texte:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, '« Claudius Lysias au très excellent gouverneur Félix, salut!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Comme cet homme, qui avait été saisi par les Juifs, était sur le point d\'être mis à mort par eux, je suis intervenu avec ma troupe pour le délivrer, parce que j\'avais appris qu\'il était Romain;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'et voulant connaître le motif pour lequel ils l\'accusaient, je l\'ai conduit devant leur sanhédrin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'et j\'ai reconnu qu\'il était accusé sur des points relatifs à leur loi, mais qu\'il n\'était l\'objet d\'aucune imputation qui méritât la mort ou les chaînes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Mais, ayant été averti qu\'un guet-apens devait lui être tendu, je te l\'ai immédiatement envoyé, après avoir aussi ordonné à ses accusateurs de prendre la parole contre lui devant toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Les soldats ayant donc pris Paul avec eux, selon l\'ordre qu\'ils en avaient reçu, le conduisirent de nuit à Antipatris,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'et le lendemain, ayant laissé les cavaliers poursuivre la route avec lui, ils rentrèrent au quartier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Lorsque ceux-là furent arrivés à Césarée et eurent remis la lettre au gouverneur, ils lui présentèrent aussi Paul;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'et après avoir lu et l\'avoir interrogé sur la province à laquelle il appartenait, ayant appris qu\'il était de Cilicie:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, '« Je t\'entendrai plus à fond, dit-il, lorsque tes accusateurs seront aussi venus; » et il ordonna qu\'on le tînt en prison dans le prétoire d\'Hérode.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Or, au bout de cinq jours, arrivèrent le grand prêtre Ananias avec quelques anciens et un certain Tertullus, avocat, lesquels adressèrent au gouverneur leur plainte contre Paul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Celui-ci ayant été appelé, Tertullus entama l\'accusation en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, '« Nous reconnaissons, excellent Félix, en tout temps et en tous lieux, avec toute sorte de gratitude, que c\'est à toi et aux réformes que ta prudence t\'a dictées en faveur de cette nation, que nous devons la paix profonde dont nous jouissons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'mais, pour ne pas te retenir plus longtemps, je te prie de nous prêter, avec ta bonté ordinaire, un instant d\'attention.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Voici le fait: nous avons constaté que cet homme était une peste, qu\'il provoquait des divisions parmi tous les Juifs de l\'empire, et qu\'il était le chef de la secte des Nazoréens;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'il a même tenté de profaner le temple, c\'est pourquoi nous l\'avons arrêté, [et nous avons voulu le juger d\'après notre loi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'mais le commandant Lysias étant survenu, l\'a violemment arraché de nos mains et te l\'a envoyé.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'Tu pourras toi-même apprendre de lui, en l\'interrogeant, tout ce dont nous l\'accusons. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Les Juifs de leur côté se joignirent à l\'accusation, prétendant qu\'en effet les choses étaient ainsi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Paul, après que le gouverneur lui eut fait signe de prendre la parole, répliqua: « Sachant que tu es, depuis plusieurs années, juge de cette nation, j\'entreprends avec confiance ma propre justification;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'tu peux d\'ailleurs t\'assurer qu\'il n\'y a pas plus de douze jours que je suis arrivé pour adorer à Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'et ils ne m\'ont point surpris discourant avec quelqu\'un, ou cherchant à ameuter la foule dans le temple, ni dans les synagogues, ni dans la ville,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'et ils ne peuvent pas même établir devant toi ce dont ils m\'accusent maintenant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Mais je te confesse que, conformément à la doctrine qu\'ils appellent secte, je rends un culte au Dieu de mes pères, croyant ce qui est écrit dans la loi et dans les prophètes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'et ayant en Dieu cette espérance, qu\'eux-mêmes partagent aussi, qu\'il y aura une résurrection, tant des justes que des injustes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'en conséquence, je m\'applique aussi moi-même à avoir constamment une conscience irréprochable devant Dieu et devant les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'C\'est, lorsqu\'au bout de plusieurs années, j\'étais venu pour faire dans ma nation des aumônes et des offrandes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'qu\'on m\'a trouvé dans le temple occupé de cette manière à accomplir un vœu, sans avoir occasionné ni rassemblement ni bruit; c\'étaient quelques Juifs d\'Asie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'ils auraient dû se présenter devant toi et m\'accuser s\'ils avaient eu de quoi le faire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Ou bien, que ceux qui sont ici disent eux-mêmes de quel crime ils m\'ont trouvé coupable, lorsque j\'ai comparu devant le sanhédrin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'si ce n\'est de cette seule parole que j\'ai proférée pendant que je comparaissais au milieu d\'eux: « C\'est à propos de la résurrection des morts que je suis aujourd\'hui mis en jugement devant vous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Mais Félix les ajourna, parce qu\'il savait mieux à quoi s\'en tenir sur ce qui concernait la doctrine, après avoir dit: « Quand le commandant Lysias sera venu, j\'examinerai plus à fond votre affaire. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Puis il ordonna au centurion qu\'il fût tenu en prison, en jouissant d\'une certaine liberté, et qu\'on n\'empêchât aucun des siens de lui rendre quelque service.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Cependant au bout de quelques jours il vint avec sa femme Drusille, qui était juive, et il fit appeler Paul, et il l\'écouta parler de la foi en Christ-Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Mais, comme il discourait sur la justice, la tempérance et le jugement à venir, Félix s\'en effraya et dit: « Pour le moment va-t-en, mais, quand j\'en trouverai l\'occasion, je te rappellerai. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'En même temps il espérait aussi qu\'il recevrait de l\'argent de Paul; aussi le faisait-il appeler à plus d\'une reprise pour s\'entretenir avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Cependant, après que deux ans se furent écoulés, Félix reçut pour successeur Porcius Festus, et, voulant s\'assurer de la gratitude des Juifs, Félix laissa Paul dans les chaînes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Lors donc que Festus fut arrivé dans sa province, il monta, au bout de trois jours, de Césarée à Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'et les grands prêtres et les principaux des Juifs lui adressèrent une plainte contre Paul, et ils le sollicitaient,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'en demandant contre celui-ci qu\'il leur accordât la grâce de le faire venir à Jérusalem, parce qu\'ils avaient dressé un guet-apens pour le tuer sur la route.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Mais Festus répliqua que Paul était en prison à Césarée et que lui-même allait bientôt repartir:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, '« Que les principaux d\'entre vous, ajouta-t-il, descendent donc avec moi, et, s\'il y a quelque crime à la charge de cet homme, qu\'ils l\'accusent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Puis, après être demeuré parmi eux pas plus de huit à dix jours, il revint à Césarée, et, s\'étant, dès le lendemain, assis sur son tribunal, il ordonna qu\'on amenât Paul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Quand il fut arrivé, les Juifs, qui étaient venus de Jérusalem, l\'entourèrent en l\'accablant de nombreuses et graves inculpations qu\'ils ne pouvaient prouver,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'parce que Paul se justifiait de tout méfait, soit contre la loi des Juifs, soit contre le temple, soit contre l\'empereur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Mais Festus, voulant s\'assurer la gratitude des Juifs, répliqua à Paul: « Veux-tu monter à Jérusalem pour y être jugé là-dessus, en ma présence? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Mais Paul dit: « C\'est devant le tribunal de l\'empereur que je comparais, c\'est là que je dois être jugé; je n\'ai commis nulle offense contre les Juifs, comme toi-même aussi tu le sais mieux que personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Si donc je suis coupable, et si j\'ai fait quelque chose qui mérite la mort, je ne refuse point de mourir; mais, si rien de ce dont ceux-ci m\'accusent n\'est vrai, personne ne peut me livrer à eux. J\'en appelle à l\'empereur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Alors Festus, après avoir conféré avec son conseil, répliqua: « Tu en as appelé à l\'empereur, tu iras devant l\'empereur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Cependant, au bout de quelques jours, le roi Agrippa et Bérénice vinrent à Césarée pour saluer Festus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Et, comme ils faisaient un assez long séjour, Festus exposa au roi l\'affaire de Paul en disant: « Il y a un certain personnage que Félix a laissé prisonnier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'et contre lequel, lorsque je suis allé à Jérusalem, les grands prêtres et les anciens des Juifs m\'ont adressé une plainte, en demandant sa condamnation;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'je leur ai répondu que ce n\'est pas l\'usage des Romains de livrer un homme, avant que l\'accusé ait été mis en présence de ses accusateurs et qu\'il ait obtenu la faculté de se justifier de l\'accusation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Eux donc s\'étant réunis ici je ne perdis pas un moment, et, dès le jour suivant, m\'étant assis sur mon tribunal, j\'ordonnai qu\'on amenât cet homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Les accusateurs ayant comparu n\'articulèrent contre lui aucun des crimes auxquels je m\'attendais,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'mais ils l\'attaquaient sur des questions relatives à leur propre religion, et à un certain Jésus mort que Paul prétendait être vivant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Pour moi, comme j\'étais fort embarrassé pour faire une enquête sur ces questions, je lui demandai s\'il voulait aller à Jérusalem pour y être jugé là-dessus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'mais Paul ayant interjeté un appel qui le constitue prisonnier en réservant sa cause à la connaissance de Sa Majesté, j\'ai ordonné qu\'il demeurât en prison jusques à ce que je l\'envoyasse à l\'empereur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Et Agrippa dit à Festus: « Je désirerais pour ma part entendre aussi cet homme. » — « Demain, dit-il, tu l\'entendras. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Le lendemain donc, Agrippa et Bérénice étant arrivés en grande pompe, et s\'étant rendus dans la salle d\'audience avec les commandants militaires et les principaux personnages de la ville, Paul fut introduit sur l\'ordre de Festus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Et Festus dit: « Roi Aprippa, et vous tous qui êtes présents, vous voyez cet homme au sujet duquel toute la multitude des Juifs m\'a sollicité, soit à Jérusalem, soit ici, en criant qu\'il ne devait plus rester en vie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'mais, pour moi, j\'ai compris qu\'il n\'avait rien fait qui méritât la mort; cependant, comme Paul lui-même en a appelé à Sa Majesté, j\'ai résolu de le faire partir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Je ne sais pas trop qu\'écrire de positif sur son compte à notre maître; c\'est pourquoi je l\'ai fait comparaître devant vous, et principalement devant toi, roi Agrippa, afin que, lorsqu\'il aura été examiné, je puisse écrire quelque chose;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'car il me paraît absurde, en expédiant un prisonnier, de ne pas indiquer en même temps les crimes dont on l\'accuse. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Agrippa dit à Paul: « Il t\'est permis de parler pour te défendre. » Alors Paul, ayant étendu la main, se justifiait en ces termes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, '« Je m\'estime heureux, roi Agrippa, d\'avoir à me justifier aujourd\'hui devant toi sur tout ce dont je suis accusé par les Juifs, parce que tu connais à fond toutes les coutumes et toutes les discussions qui existent parmi les Juifs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'C\'est pourquoi je te prie de m\'écouter avec patience:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Que j\'aie, dès mon enfance, passé la première partie de ma vie au milieu de ma nation à Jérusalem, c\'est ce que savent tous les Juifs');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'qui, me connaissant dès l\'origine, peuvent témoigner, s\'ils le veulent, que j\'ai vécu en pharisien, selon les principes de la secte la plus austère de notre religion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Et maintenant je suis mis en jugement pour avoir espéré en la promesse que Dieu a faite à nos pères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'et dont nos douze tribus, qui rendent nuit et jour un culte fervent, attendent la réalisation. C\'est pour cette espérance, ô roi, que je suis accusé par des Juifs!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Pourquoi regarde-t-on parmi vous comme incroyable que Dieu ressuscite des morts?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Pour en revenir à moi, j\'ai cru devoir me livrer à toutes sortes d\'attaques contre le nom de Jésus le Nazoréen;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'c\'est pourquoi j\'ai agi en conséquence à Jérusalem, et j\'ai jeté plusieurs des saints dans les prisons, après en avoir reçu l\'autorisation des grands prêtres, et, quand on les mettait à mort, j\'y ai joint mon suffrage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'et, dans toutes les synagogues, sévissant souvent contre eux, je les forçais de blasphémer; dans ma fureur envers eux je les ai même poursuivis jusques dans les villes étrangères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'C\'est en me rendant pour ce motif à Damas, muni de l\'autorisation et de la permission des grands prêtres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'qu\'au milieu du jour je vis sur la route, ô roi, une lumière venant du ciel, d\'un éclat plus vif que celui du soleil, et qui m\'enveloppa ainsi que ceux qui voyageaient avec moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Et, étant tous tombés à terre, j\'entendis une voix qui me disait en hébreu: « Saul, Saul, pourquoi me persécutes-tu? Il t\'est dangereux de regimber contre des coups d\'aiguillon. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Mais je dis: « Qui es-tu, Seigneur? » Et le seigneur dit: « Je suis Jésus que tu persécutes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'mais lève-toi sur tes pieds; car je te suis apparu afin de te choisir pour ministre, et pour témoin tant de ce que tu as vu de moi, que de ce que je te ferai voir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'en te protégeant contre le peuple et contre les Gentils, vers lesquels je t\'envoie');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'pour leur ouvrir les yeux, afin qu\'ils passent des ténèbres à la lumière, et de l\'autorité de Satan à Dieu, pour recevoir, par la foi en moi, la rémission des péchés et un lot parmi ceux qui ont été sanctifiés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'En conséquence, roi Agrippa, je ne résistai point à la céleste vision,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'mais, m\'adressant d\'abord à ceux qui étaient à Damas et à Jérusalem, et dans toute la Judée, puis aux Gentils, je les exhortai à se repentir et à se convertir à Dieu, en faisant des œuvres conformes à la repentance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'c\'est à cause de cela que des Juifs m\'ayant surpris dans le temple voulaient se défaire de moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'C\'est donc grâce à la protection de Dieu que j\'ai subsisté jusques à ce jour, rendant témoignage devant petits et grands, sans rien dire qui fût contraire à ce qu\'ont dit soit les prophètes, soit Moïse, sur ce qui devait arriver,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'à savoir si le Messie devait souffrir, si, ressuscité le premier d\'entre les morts, il devait proclamer la lumière au peuple et aux Gentils... »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'A cet endroit de la justification, Festus s\'écrie d\'une voix forte: « Paul, tu es fou, ton grand savoir te jette dans le délire. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Mais Paul: « Je ne suis point fou, excellent Festus, mais je prononce des paroles vraies et réfléchies;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'car le roi est instruit sur ces sujets, et c\'est à lui que je m\'adresse avec assurance parce que je suis convaincu qu\'il n\'ignore rien de tout cela; car ce n\'est pas une chose qui se soit passée dans un coin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Crois-tu aux prophètes, roi Agrippa?... Je sais que tu y crois. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Mais Agrippa dit à Paul: « C\'est à peu de frais que tu veux me persuader de me faire chrétien. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Et Paul: « Plût à Dieu, qu\'avec peu ou beaucoup de frais, non seulement toi, mais tous ceux qui m\'écoutent aujourd\'hui, vous devinssiez tels que je suis moi-même, sauf ces chaînes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Et le roi, le gouverneur et Bérénice se levèrent, ainsi que ceux qui étaient assis avec eux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'et s\'étant retirés, ils se disaient entre eux: « Cet homme n\'a rien fait qui mérite la mort ou les chaînes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Et Agrippa dit à Festus: « Cet homme pouvait être relâché, s\'il n\'en avait appelé à l\'empereur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Or, quand il eut été décidé que nous nous rendrions par mer en Italie, on remit Paul et quelques autres prisonniers à un centurion nommé Julius, de la cohorte Auguste;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'puis nous étant embarqués sur un vaisseau d\'Adramytte, qui devait faire escale dans les ports d\'Asie, nous partîmes, ayant avec nous Aristarque, Macédonien de Thessalonique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Le jour suivant nous touchâmes à Sidon, et Julius, par bienveillance pour Paul, lui permit de se rendre auprès des amis pour profiter de leurs bons soins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Partis de là, nous rangeâmes la côte de Chypre parce que les vents étaient contraires,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'et, traversant la mer qui baigne la Cilicie et la Pamphylie, nous abordâmes à Myrrha en Lycie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Et là, le centurion ayant trouvé un vaisseau d\'Alexandrie en partance pour l\'Italie, il nous y embarqua.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Mais, après plusieurs jours d\'une lente navigation, nous arrivâmes à grand\'peine à la hauteur de Cnide, et le vent ne nous ayant pas permis d\'y aborder nous rangeâmes la côte de la Crète du côté de Salmone;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'et, après l\'avoir côtoyée avec peine, nous arrivâmes à un endroit appelé Beauxports, près duquel était la ville de Lasée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Cependant, un temps considérable s\'étant écoulé et la navigation étant devenue dangereuse, car l\'époque même du jeûne était déjà passée, Paul leur adressait des représentations en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, '« Je prévois que c\'est au péril et au grand détriment, non seulement de la cargaison et du navire, mais encore de nos vies, que se fera la navigation. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Mais le centurion se fia au pilote et au patron plutôt qu\'à ce que disait Paul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'D\'ailleurs le port étant impropre pour un hivernage, la plupart émirent l\'avis de s\'en éloigner et de chercher à atteindre, pour passer l\'hiver, Phénix, port de Crète qui regardait le sud-ouest et le nord-ouest.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Le vent du sud s\'étant légèrement levé, ils s\'imaginèrent réussir dans leur projet, et, ayant levé l\'ancre, ils côtoyèrent la Crète de plus près.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Mais bientôt, un vent impétueux, nommé Euraquilon, se déchaîna contre le rivage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'et, comme le navire était entraîné sans pouvoir tenir contre le vent, nous nous voyions aller à la dérive.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Et, ayant dépassé une petite île nommé Cauda, nous réussîmes avec peine à nous rendre maîtres du canot;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'après l\'avoir hissé, ils se servirent d\'engins pour ceindre le navire. Puis, craignant d\'être jetés sur la Syrte, ils descendirent les agrès et ils voguaient ainsi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'mais, comme nous étions violemment battus par la tempête, ils lancèrent le lendemain la cargaison à la mer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'et le jour suivant ils y jetèrent de leurs propres mains le mobilier du navire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Privés, pendant plusieurs jours, de la vue du soleil et des étoiles, et constamment en butte à une violente tempête, tout espoir de salut nous était ravi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Et, comme on se livrait à une grande abstinence, Paul, s\'étant alors levé au milieu d\'eux, dit: « Il aurait fallu, sans doute, suivre le conseil que je vous avais donné de ne point quitter la Crète, et éviter ainsi cette détresse et cette perte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'toutefois, dans l\'état des choses, je vous invite à prendre courage, car aucune de nos vies ne sera perdue, mais seulement le navire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'En effet, cette nuit même, un ange du Dieu auquel j\'appartiens et à qui je rends un culte, m\'est apparu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'en disant: « Ne crains point, Paul, il faut que tu comparaisses devant l\'empereur, et voici, Dieu t\'a octroyé tous ceux qui naviguent avec toi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'C\'est pourquoi prenez courage, car j\'ai cette foi en Dieu qu\'il en sera comme il m\'a été dit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'c\'est sur quelque île que nous devons être jetés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Or, la quatorzième nuit, comme nous étions ballottés sur l\'Adriatique, vers le milieu de la nuit, les matelots se crurent dans le voisinage d\'une terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'et, ayant jeté la sonde, ils trouvèrent vingt brasses, puis, s\'étant un peu éloignés et l\'ayant jetée de nouveau, ils trouvèrent quinze brasses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Craignant alors que nous ne fussions jetés sur des récifs, ils jetèrent quatre ancres de la poupe et implorèrent l\'arrivée du jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Mais, comme les matelots cherchaient à s\'enfuir du navire, et qu\'ils avaient mis le canot à la mer, sous prétexte de porter en avant des ancres de la proue,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Paul dit au centurion et aux soldats: « Si ces gens-là ne restent pas dans le navire, vous ne pouvez être sauvés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Alors les soldats coupèrent les cordes du canot et le laissèrent s\'éloigner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Cependant, en attendant le jour, Paul exhortait tout le monde à prendre de la nourriture, en disant: « Voici aujourd\'hui le quatorzième jour d\'attente que vous passez dans l\'abstinence sans rien prendre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'c\'est pourquoi je vous invite aussi à prendre de la nourriture, car votre salut en dépend; en effet il ne se perdra pas un cheveu de la tête d\'aucun de vous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Après avoir ainsi parlé, il prit du pain, et ayant rendu grâces à Dieu devant tous, il le rompit et se mit à manger;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'et tous, reprenant courage, prirent aussi de la nourriture.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Nous étions en tout dans le navire environ soixante-seize personnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Quand ils se furent rassasiés de nourriture, ils allégèrent le navire en jetant les provisions à la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Mais, lorsque le jour fut venu, ils ne reconnaissaient pas la terre; cependant ils aperçurent un golfe avec une plage sur laquelle ils résolurent, si cela leur était possible, de mettre le navire à l\'abri;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'puis, ayant coupé les ancres, ils les abandonnèrent à la mer; en même temps, relâchant les attaches des gouvernails, et mettant la voile au vent, ils se dirigèrent vers la plage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Mais, ayant touché sur une langue de terre, ils firent échouer le navire, et, tandis que, d\'un côté, la proue soulevée demeurait hors de l\'eau, de l\'autre, la poupe était fracassée par la violence du choc.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Alors les soldats formèrent le projet de tuer les prisonniers, de peur que l\'un d\'eux ne s\'échappât à la nage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'mais le centurion, qui voulait sauver Paul, les empêcha d\'exécuter ce dessein, et il ordonna que ceux qui savaient nager se jetassent les premiers dans l\'eau pour parvenir à terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'et, quant aux autres, qu\'ils s\'aidassent, ceux-ci de planches, et ceux-là de quelque pièce du navire. Et de cette manière il advint que tous arrivèrent à terre sains et saufs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Et, quand nous nous fûmes tirés d\'affaire, nous reconnûmes que l\'île s\'appelait Malte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'et les barbares nous montrèrent une humanité plus qu\'ordinaire; car, ayant allumé un feu, ils nous en firent tous approcher à cause de la pluie qui était tout à coup survenue, et à cause du froid.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Or Paul ayant saisi un paquet de broussailles et l\'ayant mis dans le feu, la chaleur en fit sortir une vipère qui s\'attacha à sa main;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'mais, lorsque les barbares virent l\'animal suspendu à sa main, ils se dirent entre eux: « Certainement cet homme est un meurtrier que la Justice n\'a pas voulu laissé vivre, après qu\'il est sorti de la mer sain et sauf. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Quant à lui, ayant secoué l\'animal dans le feu, il ne ressentait aucun mal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'tandis que ces gens s\'attendaient à ce qu\'il enflerait ou tomberait mort incontinent. Mais, après avoir longtemps attendu, voyant qu\'il ne lui arrivait aucun mal, ils changèrent d\'opinion et dirent que c\'était un dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Or, dans les environs de ce lieu-là se trouvaient des propriétés appartenant au premier personnage de l\'île, appelé Poplius, qui nous fit un bon accueil et nous hébergea amicalement pendant trois jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Or il advint que le père de Poplius était retenu au lit par des accès de fièvre et par une dyssenterie; Paul, s\'étant rendu auprès de lui, lui imposa les mains après avoir prié et le guérit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'là-dessus tous ceux qui, dans l\'île, avaient des infirmités accoururent, et ils étaient guéris;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'ils nous rendirent aussi toute sorte d\'honneurs, et, quand nous partîmes, ils nous fournirent ce dont nous avions besoin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Ce fut au bout de trois mois que nous partîmes sur un navire d\'Alexandrie qui avait hiverné dans l\'île et qui portait le signe des Dioscures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Arrivés à Syracuse, nous y restâmes trois jours;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'et de là, rangeant la côte, nous vînmes à Rhegio. Le lendemain, un vent du sud s\'étant levé, nous arrivâmes en deux jours à Pouzzoles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'où nous trouvâmes des frères qui nous pressèrent de rester avec eux sept jours, et c\'est ainsi que nous arrivâmes à Rome.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'De cette dernière ville vinrent à notre rencontre, jusques au Forum d\'Appius et aux Trois-Tavernes, des frères qui avaient entendu parler de nous; leur vue fut pour Paul une occasion de rendre grâces à Dieu et de prendre courage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Lorsque nous fûmes entrés dans Rome, on permit à Paul de demeurer seul avec le soldat qui le gardait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Cependant, au bout de trois jours, il convoqua les principaux des Juifs, et, quand ils furent réunis, il leur dit: « Frères, moi qui n\'avais commis aucun crime, ni contre le peuple, ni contre les coutumes de nos pères, on m\'a, de Jérusalem, livré comme prisonnier entre les mains des Romains,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'qui, après m\'avoir interrogé, voulaient m\'élargir parce qu\'il n\'y avait rien en moi qui méritât la mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'mais, les Juifs s\'y étant opposés, j\'ai été forcé d\'en appeler à l\'empereur, sans avoir toutefois l\'intention de porter aucune plainte contre ma nation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'C\'est pourquoi donc je vous ai mandés afin de vous voir et de vous parler, car c\'est à cause de l\'espérance d\'Israël que je porte cette chaîne. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Mais ils lui dirent: « Nous n\'avons reçu à ton sujet aucune lettre de Judée, et il n\'est venu aucun frère qui ait transmis sur ton compte un rapport ou un bruit défavorable;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'mais nous désirons apprendre de toi quelles sont tes opinions, car, quant à cette secte, nous savons qu\'elle est partout contredite. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Ayant pris jour avec lui, ils se rendirent en plus grand nombre auprès de lui dans la maison de son hôte, et, du matin jusqu\'au soir, il leur exposait, en rendant témoignage, le royaume de Dieu, cherchant à les persuader, d\'après la loi de Moïse et les prophètes, de ce qui concerne Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Et les uns se laissaient convaincre par ses paroles, tandis que les autres demeuraient incrédules.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Comme ils étaient en désaccord entre eux, ils se séparèrent, après que Paul eut cité une seule autorité: « L\'esprit saint a admirablement parlé par Ésaïe le prophète à vos pères, lorsqu\'il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'Va vers ce peuple, et dis: Vous entendrez par l\'ouïe et vous ne comprendrez certainement pas, et en voyant vous verrez et vous n\'apercevrez certainement pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'car le cœur de ce peuple s\'est épaissi, et ils ont difficilement ouï avec les oreilles, et ils ont fermé leurs yeux; de peur qu\'ils ne voient avec les yeux et qu\'ils n\'entendent avec les oreilles, et qu\'ils ne comprennent avec le cœur, et qu\'ils ne se convertissent, et Je les guérirai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Sachez donc que ce salut de Dieu a été envoyé aux Gentils; pour eux, certes, ils l\'écouteront. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, '[Et quand il eut ainsi parlé, les Juifs s\'en allèrent en ayant entre eux une vive discussion.]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Or, il resta deux années entières dans son logement à lui, et il recevait tous ceux qui venaient le voir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'prêchant le royaume de Dieu et enseignant, avec une pleine assurance, ce qui concernait le seigneur Jésus-Christ, sans qu\'on l\'en empêchât.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paul, — esclave de Jésus-Christ, appelé à être apôtre, mis à part pour l\'évangile de Dieu');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'que d\'avance Il avait promis par Ses prophètes dans les écritures saintes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'concernant Son Fils, qui est né de la postérité de David, selon la chair,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'qui a été déclaré Fils de Dieu, avec puissance selon l\'Esprit de sainteté, par la résurrection des morts, Jésus-Christ notre Seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'par lequel nous avons reçu la grâce et l\'apostolat, pour prêcher en son nom l\'obéissance de la foi parmi tous les Gentils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'parmi lesquels vous êtes aussi, vous qu\'a appelés Jésus-Christ, —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'à tous les bien-aimés de Dieu, appelés à être saints, qui sont à Rome: que la grâce et la paix vous soient données par Dieu notre Père et par le Seigneur Jésus-Christ!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Je rends d\'abord grâces à mon Dieu par Jésus-Christ, au sujet de vous tous, parce que votre foi est proclamée dans le monde entier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Car Dieu, auquel je rends un culte dans mon esprit en prêchant l\'évangile de Son Fils, m\'est témoin que je fais incessamment mention de vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'demandant constamment dans mes prières si je n\'aurai point enfin le bonheur, par la volonté de Dieu, de venir jusques à vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Car je désire ardemment vous voir, afin de vous communiquer quelque don spirituel pour vous affermir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'ou plutôt pour trouver de l\'encouragement au milieu de vous par la foi qui nous est commune à vous et à moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Je ne veux pas toutefois que vous ignoriez, frères, que j\'ai souvent formé le projet d\'aller jusques à vous (et j\'en ai été empêché jusques à présent), afin de recueillir quelque fruit parmi vous, aussi bien que parmi les autres Gentils:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'je me dois aux Grecs et aux Barbares, aux sages et aux ignorants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Ainsi, pour ce qui me concerne, je suis impatient de vous porter aussi la bonne nouvelle, à vous qui êtes à Rome.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Je n\'ai point honte, en effet, de l\'évangile, car c\'est une puissance de Dieu qui produit le salut pour tout croyant, Juif et Grec;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'parce que la justice de Dieu y est révélée par la foi pour la foi, selon qu\'il est écrit: « Or celui qui est juste par la foi vivra. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'En effet, la colère de Dieu est révélée du ciel contre toute impiété et toute injustice des hommes qui asservissent injustement la vérité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'parce que ce que l\'on connaît de Dieu leur est intérieurement manifesté, car Dieu le leur manifeste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'En effet, ce qui en Lui est invisible, tant Sa puissance éternelle que Sa divinité, se fait voir depuis la création du monde par Ses œuvres, quand on y réfléchit; en sorte qu\'ils sont inexcusables,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'parce qu\'ayant connu Dieu, ils ne L\'ont point glorifié comme Dieu, ni ne Lui ont rendu grâces, mais ils se sont égarés dans leurs pensées, et leur cœur dépourvu d\'intelligence s\'est obscurci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Se donnant pour sages ils ont été atteints de folie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'et ils ont échangé la gloire du Dieu incorruptible contre des simulacres faits à l\'image de l\'homme corruptible et des oiseaux et des quadrupèdes et des reptiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'C\'est pourquoi Dieu les a livrés, dans les convoitises de leurs cœurs, à une impureté telle que leurs corps sont déshonorés parmi eux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'eux qui ont changé la vérité de Dieu en mensonge, et rendu des hommages et un culte à la créature à l\'exclusion du Créateur, qui est béni pour les siècles! Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'C\'est pourquoi Dieu les a livrés à des passions infâmes: d\'un côté, en effet, leurs femmes ont changé l\'usage naturel en celui qui est contre nature,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'et de l\'autre, les hommes, ayant aussi abandonné l\'usage naturel de la femme, se sont enflammés dans leur passion les uns pour les autres en perpétrant l\'infamie d\'hommes à hommes et recevant en eux-mêmes la rétribution qui était due à leur égarement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Et comme ils n\'ont pas daigné retenir la connaissance de Dieu, Dieu les a livrés à leur sens réprouvé, de sorte qu\'ils font ce qui est indigne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'étant remplis de toute espèce d\'injustice, de méchanceté, de cupidité, de perversité; pleins d\'envie, de meurtre, de querelle, de ruse, de malveillance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'délateurs, médisants, ennemis de Dieu, insulteurs, superbes, fanfarons, ingénieux au mal, rebelles à leurs parents,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'dépourvus d\'intelligence, insensibles, impitoyables,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'lesquels, quoiqu\'ils connaissent le décret de Dieu qui déclare dignes de mort ceux qui commettent de telles choses, non seulement les pratiquent, mais encore approuvent ceux qui les commettent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'C\'est pourquoi tu es inexcusable, ô homme, qui que tu sois, qui t\'ériges en juge, car en jugeant les autres tu te condamnes toi-même; puisque toi qui juges, tu fais les mêmes choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Or nous savons que le jugement de Dieu atteint infailliblement ceux qui commettent de telles choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Mais penses-tu, ô homme, toi qui juges ceux qui commettent de telles choses et qui toi-même les pratiques, que tu échapperas pour ton compte au jugement de Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Ou bien méprises-tu la richesse de Sa bonté, et Sa patience, et Sa longanimité, ignorant que la bonté de Dieu te pousse à la repentance?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Mais, avec ton endurcissement et ton cœur impénitent, tu t\'amasses une provision de colère pour le jour de la colère et de la révélation du juste jugement de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'qui rendra à chacun selon ses œuvres:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'd\'un côté, la vie éternelle, à ceux qui cherchent, en persévérant dans les bonnes œuvres, la gloire, l\'honneur et l\'incorruptibilité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'mais pour les hommes d\'intrigue, et qui, désobéissant à la vérité, obéissent à l\'injustice, la colère et le courroux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Angoisse et tribulation pour l\'âme de tout homme qui perpètre le mal, du Juif premièrement, puis du Grec!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Mais gloire, honneur et paix pour quiconque accomplit le bien, pour le Juif d\'abord, puis pour le Grec!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Car il n\'y a pas devant Dieu d\'acception de personnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'En effet, tous ceux qui ont péché sans la loi, périront aussi sans la loi, et tous ceux qui ont péché sous la loi, seront jugés par la loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'Car ce ne sont pas ceux qui écoutent la loi qui sont justes devant Dieu, mais ce sont ceux qui pratiquent la loi qui seront justifiés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'En effet, quand les Gentils, qui n\'ont pas la loi, font naturellement ce que prescrit la loi, ces hommes-là qui n\'ont pas la loi se servent de loi à eux-mêmes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'et montrent ainsi que l\'œuvre de la loi est écrite dans leurs cœurs; leur propre conscience joignant son témoignage, et leurs pensées les accusant ou les excusant aussi tour à tour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'dans la journée où, selon mon évangile, Dieu doit juger par Christ-Jésus ce que cachent les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Mais si toi, tu portes le nom de Juif; si tu te reposes sur la loi; si tu t\'enorgueillis de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'si tu connais Sa volonté; si, instruit par la loi, tu approuves ce qui est excellent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'si tu as la confiance d\'être le guide des aveugles, la lumière de ceux qui sont dans les ténèbres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'l\'instituteur des insensés, le docteur des ignorants, possédant dans la loi le type de la science et de la vérité...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'toi donc qui instruis les autres, comment ne t\'instruis-tu pas toi-même? Toi qui prêches qu\'on ne doit pas dérober, tu dérobes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Toi qui dis qu\'on ne doit pas commettre d\'adultère, tu commets l\'adultère! Toi qui as en abomination les idoles, tu pilles les temples!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Toi qui t\'enorgueillis de la loi, tu déshonores Dieu par la transgression de la loi!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Car « le nom de Dieu est blasphémé à cause de vous parmi les Gentils, » comme il est écrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'En effet, si la circoncision est utile dans le cas où tu pratiques la loi, au contraire quand tu transgresses la loi, ta circoncision devient incirconcision.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Si donc l\'incirconcis observe les décrets de la loi, son incirconcision ne sera-t-elle pas comptée comme circoncision?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Et l\'incirconcision naturelle qui accomplit la loi ne te jugera-t-elle pas, toi qui, tout en possédant la lettre et la circoncision, transgresses la loi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Car ce n\'est pas celui qui se montre tel extérieurement, qui est Juif, et ce n\'est pas non plus la circoncision extérieure dans la chair, qui est la circoncision;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'mais c\'est celui qui l\'est intérieurement, qui est Juif, et la circoncision du cœur se fait par l\'esprit et non selon la lettre; ce qui mérite une louange qui ne vient pas des hommes, mais de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Quelle est donc la prérogative du Juif? Ou quelle est l\'utilité de la circoncision?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Elle est grande de toute manière. Et d\'abord, parce que les oracles de Dieu leur ont été confiés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Qu\'importe en effet que quelques-uns aient été infidèles? Est-ce que leur infidélité anéantira la fidélité de Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Loin de nous cette pensée! Mais au contraire; que Dieu soit tenu pour véridique et tout homme pour menteur selon qu\'il est écrit: « Afin que Tu sois justifié dans Tes paroles, et que Tu triomphes quand on Te juge. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Mais si notre injustice établit la justice de Dieu, que dirons-nous? Est-ce qu\'en laissant agir Sa colère Dieu est injuste? Je parle d\'une manière tout humaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Loin de nous cette pensée! Car en ce cas comment Dieu juge-t-Il le monde,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'puisque, si la vérité de Dieu a par mon mensonge surabondé pour Sa gloire, pourquoi suis-je moi-même encore condamné comme pécheur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Et que n\'agissons-nous comme nous en sommes calomnieusement accusés, puisque quelques personnes prétendent que nous disons: Faisons le mal afin qu\'il en résulte le bien; ce qui est digne de condamnation?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Eh bien! Avons-nous quelque chose à alléguer? Absolument rien; car nous avons déjà convaincu les Juifs et les Grecs d\'être tous sous l\'empire du péché,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'selon qu\'il est écrit: « Il n\'existe point de juste, pas même un seul;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'il n\'existe point de sage, il n\'existe personne qui cherche Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'tous, ils se sont dévoyés, ils se sont tous ensemble pervertis; il n\'en existe point qui fasse le bien, fût-ce même un seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'C\'est un sépulcre béant que leur gosier; avec leurs langues ils ont rusé; un venin d\'aspics est sous leurs lèvres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'leur bouche est pleine de malédiction et d\'amertume;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'leurs pieds sont rapides pour verser le sang;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'l\'oppression et la misère sont sur leur route,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'et ils n\'ont pas connu le chemin de la paix;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'la crainte de Dieu n\'est pas devant leurs yeux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Or nous savons que tout ce que dit la loi, elle l\'adresse à ceux qui sont sous la loi, afin que toute bouche soit fermée, et que le monde entier tombe sous le châtiment de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'parce que personne ne sera justifié devant Lui par les œuvres de la loi; car c\'est par la loi que vient la connaissance du péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Or, maintenant c\'est sans la loi qu\'est manifestée la justice de Dieu, à laquelle rendent témoignage la loi et les prophètes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'mais c\'est la justice de Dieu par la foi en Christ pour tous ceux qui croient. En effet il n\'y a point de différence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'car tous ont péché et sont privés de la gloire de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'étant gratuitement justifiés par Sa grâce, par le moyen de la rédemption accomplie en Christ-Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'dont Dieu a fait une victime expiatoire, par la foi en son propre sang, afin de manifester Sa justice, parce qu\'il n\'avait pas été tenu compte des péchés antérieurs');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'à cause de l\'indulgence de Dieu, afin de manifester, dis-je, Sa justice dans les circonstances présentes, pour se montrer Lui-même juste et justifiant celui qui croit en Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Que devient donc la raison de s\'enorgueillir? Elle a été exclue. Par quelle loi? Celle des œuvres? Non, mais par la loi de la foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Nous pensons donc que l\'homme est justifié par la foi, sans les œuvres de la loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Ou bien Dieu ne l\'est-Il que des seuls Juifs? Ne l\'est-Il pas aussi des Gentils? Oui, aussi des Gentils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'puisqu\'il n\'y a qu\'un seul Dieu qui justifiera la circoncision en conséquence de la foi, et l\'incirconcision par le moyen de la foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Anéantissons-nous donc la loi par la foi? Loin de nous cette pensée, au contraire nous établissons la loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Que dirons-nous donc d\'Abraham notre ancêtre selon la chair?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Car si Abraham a été justifié en conséquence des œuvres, il a de quoi s\'enorgueillir, mais non pas relativement à Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'En effet que dit l\'écriture? « Or Abraham crut à Dieu, et cela lui fut compté pour justice. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Mais pour celui qui accomplit des œuvres, son salaire ne lui est pas compté à titre de grâce, mais de dette,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'tandis que pour celui qui n\'accomplit pas d\'œuvres, mais qui croit en Celui qui justifie l\'impie, sa foi lui est comptée pour justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'C\'est de même aussi que David parle de la béatitude de l\'homme auquel Dieu attribue la justice sans les œuvres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, '« Heureux ceux dont les crimes ont été pardonnés et dont les péchés ont été couverts!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Heureux l\'homme auquel le Seigneur n\'imputera certainement pas son péché! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Est-ce que cette béatitude n\'a donc trait qu\'à la circoncision, ou bien également à l\'incirconcision? Nous disons en effet: La foi a été comptée à Abraham pour justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Comment donc lui a-t-elle été comptée pour telle? Est-ce quand il était circoncis ou incirconcis? Ce n\'est pas quand il eut été circoncis, mais lorsqu\'il était incirconcis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Et il reçut le signe de la circoncision comme un sceau de la justice de la foi qu\'il avait eue quand il était incirconcis, afin d\'être le père de tous ceux qui croient, quoiqu\'incirconcis, de sorte que la justice leur est attribuée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'et afin d\'être aussi le père de la circoncision, pour ceux qui non seulement sont circoncis, mais qui marchent sur les traces de la foi qu\'a eue, quand il était incirconcis, notre père Abraham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'En effet, ce n\'est pas par la loi qu\'a été faite à Abraham ou à sa postérité, la promesse qu\'il serait héritier du monde, mais c\'est par la justice de la foi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'car, si ce sont ceux qui relèvent de la loi qui sont héritiers, la foi est mise à néant et la promesse abolie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'en effet la loi produit la colère, mais là où n\'est pas là loi il n\'y a pas non plus de transgression;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'c\'est pourquoi cela vient de la foi, afin que ce soit à titre de grâce, en sorte que la promesse est irréfragable pour toute la postérité, non seulement pour celle qui relève de la loi, mais encore pour celle qui se rattache à la foi d\'Abraham qui est notre père à tous');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '(selon qu\'il est écrit: « Car J\'ai fait de toi le père de plusieurs nations »), devant Celui auquel il a cru, le Dieu qui vivifie les morts, et qui évoque comme si elles existaient les choses qui n\'existent point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Il a, contre toute espérance, cru avec espérance, en sorte qu\'il est devenu le père de plusieurs nations, selon cette parole: Telle sera ta postérité, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'et il a vu, sans faiblir dans sa foi, la caducité de son propre corps, âgé qu\'il était d\'environ cent ans, et celle des organes de Sarra;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'mais, relativement à la promesse de Dieu, il n\'hésita point par incrédulité; il fut au contraire fortifié par la foi, rendant gloire à Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'et étant convaincu que ce qu\'il promet, Il peut aussi l\'accomplir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'C\'est pourquoi cela lui a été compté pour justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Or ce n\'est pas à cause de lui seul qu\'il est écrit que « cela lui a été compté, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'mais c\'est aussi à cause de nous, auxquels cela doit être compté, pour autant que nous croyons en Celui qui a ressuscité d\'entre les morts Jésus notre Seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'lequel a été livré pour nos fautes, et qui est ressuscité pour notre justification.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Ayant donc été justifiés par la foi, soyons en paix avec Dieu par notre Seigneur Jésus-Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'par lequel nous avons aussi obtenu l\'accès à cette grâce dans laquelle nous sommes établis; et nous nous enorgueillissons à cause de l\'espérance de la gloire de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'et non seulement à cause de cela, mais encore nous nous enorgueillissons des tribulations, sachant que la tribulation produit la patience,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'et la patience le mérite, et le mérite l\'espérance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'Or l\'espérance ne trompe pas, parce que l\'amour de Dieu a été versé dans nos cœurs par l\'Esprit saint qui nous a été donné,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 's\'il est vrai que Christ, alors que nous étions encore faibles, est mort au moment voulu pour des impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'C\'est à grand\'peine, en effet, que quelqu\'un mourra pour un juste, car il se peut bien faire que quelqu\'un se décide à mourir pour l\'homme de bien;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'mais Il prouve Son amour envers nous, par ce fait-ci, que, lorsque nous étions encore pécheurs, Christ est mort pour nous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'à combien plus forte raison par conséquent, maintenant que nous avons été justifiés par son sang, serons-nous préservés par lui de la colère?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Car, si, lorsque nous étions ennemis, nous avons été réconciliés avec Dieu par la mort de Son Fils, à combien plus forte raison, une fois que nous avons été réconciliés, serons-nous sauvés par sa vie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Non seulement nous le serons, mais ce sera encore en nous enorgueillissant en Dieu par notre Seigneur Jésus-Christ, par lequel nous avons maintenant obtenu la réconciliation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'C\'est pourquoi, comme par un seul homme le péché est entré dans le monde et par le péché la mort, et qu\'ainsi la mort s\'est étendue à tous les hommes, parce que tous ont péché,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'car jusques à la loi le péché a été dans le monde; ... mais le péché n\'est pas imputé là où n\'est pas la loi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'et cependant la mort a régné depuis Adam jusques à Moïse, même sur ceux qui n\'ont pas commis de péchés semblables à la transgression d\'Adam, lequel est l\'image de celui qui devait venir...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Mais il n\'en est pas du pardon gratuit comme de la faute; car si par la faute d\'un seul tous les autres sont morts, à combien plus forte raison la grâce de Dieu et Son don gratuit se sont-ils abondamment répandus par la grâce d\'un seul homme, Jésus-Christ, sur tous les autres!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Et il n\'en est pas de ce don comme de ce qui est advenu par le fait d\'un seul qui a péché; car tandis que c\'est par une seule faute que le jugement est devenu condamnation, c\'est en revanche par plusieurs fautes que le pardon gratuit est devenu acquittement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'En effet, si, par la faute d\'un seul, la mort a régné par lui seul, à combien plus forte raison ceux qui reçoivent en abondance la grâce et la justice, régneront-ils dans la vie par le seul Christ-Jésus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Ainsi donc, comme une seule faute a valu à tous les hommes la condamnation, de même aussi un seul acquittement a valu à tous les hommes la justification qui donne la vie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'car, comme par la désobéissance d\'un seul homme tous les autres ont été constitués pécheurs, de même aussi par l\'obéissance d\'un seul tous les autres seront constitués justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Or la loi est intervenue afin que la faute abondât, mais là où le péché a abondé, la grâce a surabondé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'afin que, comme le péché a régné dans la mort, de même aussi la grâce régnât par la justice pour la vie éternelle par Christ-Jésus notre Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Que dirons-nous donc? Demeurons dans le péché, afin que la grâce abonde?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Loin de nous cette pensée! Nous qui sommes morts au péché, comment vivrions-nous encore dans le péché?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Ou bien, ignorez-vous que nous tous qui avons été baptisés en Christ, c\'est en sa mort que nous avons été baptisés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Nous avons donc été ensevelis avec lui par le baptême en sa mort, afin que, de même que Christ est ressuscité des morts par la gloire du Père, de même nous aussi nous entrions dans un renouvellement de vie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'car si nous nous sommes par ressemblance identifiés à sa mort, nous nous identifierons plus encore à sa résurrection.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'Sachant en outre que notre vieil homme a été crucifié avec lui, afin que le corps où règne le péché fût détruit, pour que nous ne fussions plus asservis au péché;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'car celui qui est mort est soustrait à la juridiction du péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Mais si nous sommes morts avec Christ, nous croyons que nous vivrons aussi avec lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'sachant que Christ, une fois ressuscité des morts, ne meurt plus; la mort n\'a plus de puissance sur lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'car la mort qu\'il a soufferte, c\'est pour le péché qu\'il l\'a soufferte une fois pour toutes, tandis que la vie dont il vit, il en vit pour Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'De même, vous aussi, regardez-vous comme étant morts pour le péché, mais comme vivant pour Dieu en Christ-Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Que le péché ne règne donc plus dans votre corps mortel, pour que vous obéissiez aux convoitises de celui-ci,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'et ne mettez pas non plus vos membres à la disposition du péché comme des instruments d\'iniquité, mais mettez-vous vous-mêmes à la disposition de Dieu, comme de morts étant devenus vivants, et mettez aussi vos membres à la disposition de Dieu comme des instruments de justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Car le péché n\'aura pas de puissance sur vous, parce que vous n\'êtes pas sous la loi, mais sous la grâce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Quoi donc? Péchons, parce que nous ne sommes pas sous la loi mais sous la grâce? Loin de nous cette pensée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Ne savez-vous pas qu\'en vous mettant comme esclaves à la disposition de quelqu\'un pour lui obéir, vous êtes esclaves de celui auquel vous obéissez, soit du péché qui conduit à la mort, soit de l\'obéissance qui conduit à la justice?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Mais grâces soient rendues à Dieu de ce que vous, qui étiez esclaves du péché, vous avez obéi de cœur au modèle d\'enseignement qui vous a été transmis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'et de ce qu\'après avoir été affranchis du péché vous avez été asservis à la justice;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'je parle d\'une manière humaine à cause de la faiblesse de votre chair. Eh bien, de même que vous avez mis vos membres comme esclaves à la disposition de l\'impureté et du désordre, de même mettez maintenant vos membres comme esclaves à la disposition de la justice pour parvenir à la sanctification.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Car lorsque vous étiez esclaves du péché, vous étiez libres quant à la justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Quel fruit retiriez-vous donc alors des choses dont vous rougissez maintenant? Elles n\'ont en effet d\'autre résultat que la mort,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'tandis que maintenant que vous avez été affranchis du péché et asservis à Dieu, le fruit que vous retirez a pour effet la sanctification et pour résultat la vie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Car le salaire que paie le péché, c\'est la mort, mais le don gratuit de Dieu, c\'est la vie éternelle en Christ-Jésus notre Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Ou bien ignorez-vous, frères (car je parle à des gens qui connaissent la loi), que la loi n\'a puissance sur l\'homme que pendant qu\'il vit?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'En effet la femme mariée est liée par la loi à son mari tant qu\'il vit, mais si le mari vient à mourir, elle est dégagée de la loi qui la liait au mari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'C\'est pourquoi, pendant la vie du mari, elle méritera le nom d\'adultère si elle se donne à un autre mari; mais si son mari vient à mourir, elle est affranchie de la loi, en sorte qu\'elle n\'est pas adultère en se donnant à un autre mari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Ainsi donc, vous aussi, mes frères, vous avez été mis à mort en ce qui concerne la loi par le moyen du corps de Christ, pour que vous vous donniez à un autre, à celui qui est ressuscité d\'entre les morts afin que nous portions des fruits pour Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'car lorsque nous vivions dans la chair, les passions des péchés provoquées par la loi agissaient dans nos membres, de manière à porter des fruits pour la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Mais maintenant nous avons été dégagés de la loi, en mourant à ce qui nous retenait captifs, en sorte que nous servons sous le régime nouveau de l\'Esprit et non sous le régime ancien de la lettre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Que dirons-nous donc? Que la loi est un principe de péché? Loin de nous cette pensée! Cependant je n\'aurais pas connu le péché sans l\'entremise de la loi; et en effet je ne connaîtrais pas la convoitise, si la loi ne disait: « Tu ne convoiteras point. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Mais le péché saisissant l\'occasion a développé en moi, grâce à ce commandement, toute sorte de convoitise; car sans la loi le péché est mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Pour moi, je vivais une fois sans la loi; mais quand le commandement est survenu, le péché a repris vie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'et moi je suis mort, et le commandement qui conduit à la vie s\'est précisément trouvé pour moi conduire à la mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'car le péché saisissant l\'occasion m\'a trompé par le moyen du commandement, et m\'a fait mourir par son moyen.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Ainsi, la loi, il est vrai, est sainte, et le commandement est saint, juste et bon...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Ce qui est bon est-il donc devenu pour moi une cause de mort? Loin de nous cette pensée! Mais c\'est le péché; afin qu\'il se manifestât comme péché en se servant de ce qui est bon pour me donner la mort, et qu\'ainsi le péché devînt, par le moyen du commandement, excessivement pécheur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Nous savons en effet que la loi est spirituelle, mais, pour moi, je suis charnel, vendu au péché;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'en effet je ne sais pas ce que je fais, car je n\'exécute point ce que je veux, mais c\'est ce que je hais que je pratique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Or, si c\'est ce que je ne veux pas que je pratique, je conviens avec la loi qu\'elle est bonne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Mais maintenant ce n\'est plus moi qui fais cela, mais c\'est le péché qui habite en moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'car je sais qu\'en moi, c\'est-à-dire, en ma chair, il n\'habite pas de bien; en effet, vouloir le bien m\'est naturel, mais ce qui ne l\'est pas, c\'est de le faire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'car le bien que je veux, je ne le pratique pas, mais c\'est le mal que je ne veux pas, que j\'exécute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Or, si c\'est ce que je ne veux pas, que je pratique, ce n\'est plus moi qui le fais, mais c\'est le péché qui habite en moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Je trouve donc en moi cette loi: que, lorsque je veux pratiquer le bien, c\'est le mal qui m\'est naturel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'en effet j\'acquiesce avec joie, à la loi de l\'intelligence, selon l\'homme intérieur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'mais je vois une loi différente dans mes membres, laquelle lutte contre la loi de mon intelligence et me rend captif de la loi du péché qui est dans mes membres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Malheureux homme que je suis! Qui me délivrera du corps sujet à cette mort?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Grâces soient rendues à Dieu par Jésus-Christ notre Seigneur! Ainsi donc, laissé à moi-même, je m\'asservis, il est vrai par l\'intelligence, à la loi de Dieu, mais par la chair à la loi du péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Il n\'y a donc maintenant aucune condamnation pour ceux qui sont en Christ-Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'car la loi de l\'Esprit de vie t\'a affranchi en Christ-Jésus de la loi du péché et de la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'En effet, ce qui était impossible à la loi, parce que la chair la rendait impuissante, Dieu, en envoyant Son propre fils avec une chair semblable à celle du péché, et à cause du péché, a condamné le péché dans la chair,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'afin que ce qu\'a décrété la loi s\'accomplit en nous, qui ne nous conduisons pas selon la chair, mais selon l\'Esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Car ceux qui vivent selon la chair s\'intéressent aux choses de la chair, tandis que ceux qui vivent selon l\'Esprit s\'intéressent aux choses de l\'Esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'En effet l\'affection de la chair donne la mort, tandis que l\'affection de l\'Esprit donne la vie et la paix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'parce que l\'affection de la chair est inimitié contre Dieu; en effet elle ne se soumet pas à la loi de Dieu; car aussi bien ne le peut-elle pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Or ceux qui vivent dans la chair ne peuvent plaire à Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'mais pour vous, vous ne vivez pas dans la chair, mais dans l\'Esprit, si du moins l\'Esprit de Dieu habite en vous; mais si quelqu\'un ne possède pas l\'Esprit de Christ, celui-là ne lui appartient point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Au contraire, si Christ est en vous, votre corps est mort, il est vrai, à cause du péché, mais votre esprit est vie, à cause de la justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Or, si l\'Esprit de Celui qui a ressuscité Jésus d\'entre les morts habite en vous, Celui qui a ressuscité Christ d\'entre les morts donnera aussi la vie à vos corps mortels, à cause de Son Esprit qui habite en vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Ainsi donc, frères, nous avons contracté une obligation, non pas envers la chair pour vivre selon la chair,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'car si vous vivez selon la chair, vous devez mourir, tandis que, si par l\'esprit vous faites mourir les actes du corps, vous vivrez;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'car tous ceux qui sont conduits par l\'Esprit de Dieu, ce sont ceux-là qui sont fils de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'En effet vous n\'avez pas reçu un esprit d\'esclavage pour derechef vivre sous la crainte, mais vous avez reçu un esprit d\'adoption, dans lequel nous nous écrions: Abba! Père!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'L\'Esprit lui-même atteste avec notre esprit que nous sommes enfants de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Or, si nous sommes enfants, nous sommes aussi héritiers; héritiers de Dieu et cohéritiers de Christ, si du moins nous souffrons avec lui, afin d\'être aussi glorifiés avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Car je pense que les souffrances du temps actuel ne méritent pas d\'être mises en balance avec la gloire qui va nous être révélée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'car la création, dans une inquiète expectative, attend avec impatience la révélation des fils de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'La création a en effet été soumise à la vanité, non de son gré mais à cause de Celui qui l\'y a soumise,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'avec l\'espoir que la création, elle aussi, sera affranchie de l\'esclavage de la corruption pour jouir de la liberté de la gloire des enfants de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'car nous savons que la création tout entière est jusques à présent dans les gémissements et les douleurs de l\'enfantement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Or, ce n\'est pas elle seulement; mais nous-mêmes aussi, qui possédons les prémices de l\'esprit; nous-mêmes aussi nous gémissons au dedans de nous en attendant avec impatience l\'adoption, la rédemption de notre corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'En effet, c\'est en espérance que nous avons été sauvés. Or, une espérance que l\'on voit n\'est pas une espérance, car ce que voit quelqu\'un, qu\'a-t-il affaire de l\'espérer?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Mais si c\'est ce que nous ne voyons pas que nous espérons, nous l\'attendons avec patience.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'De même, l\'Esprit s\'unit aussi à nous pour subvenir à notre faiblesse; car nous ne savons pas comment nous devons prier selon le besoin, mais c\'est l\'Esprit lui-même qui intercède par des soupirs inexprimables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Or, Celui qui sonde les cœurs sait quelle est la pensée de l\'Esprit, parce que c\'est selon Dieu qu\'il intercède en faveur des saints.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Or, nous savons que, pour ceux qui aiment Dieu, Dieu mène tout à bien, pour ceux, dis-je, qui sont appelés en vertu de Son décret;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'car ceux que d\'avance Il a connus, Il les a aussi d\'avance destinés à reproduire l\'image de Son Fils, afin qu\'il fût le premier-né parmi plusieurs frères;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'mais ceux qu\'il a prédestinés, Il les a aussi appelés, et ceux qu\'il a appelés, Il les a aussi justifiés, et ceux qu\'il a justifiés, Il les a aussi glorifiés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Que dirons-nous donc de plus? Si Dieu est pour nous, qui est-ce qui est contre nous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Celui même qui n\'a pas épargné Son propre Fils, mais qui l\'a livré pour nous tous, comment ne nous donnera-t-Il pas encore gratuitement toutes choses avec lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Qui est-ce qui accusera les élus de Dieu? C\'est Dieu qui justifie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Qui les condamnera? C\'est Christ qui est mort, bien plus, qui est aussi ressuscité; c\'est lui qui se tient aussi à la droite de Dieu; c\'est lui qui intercède aussi pour nous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Qui est-ce qui nous séparera de l\'amour de Dieu manifesté en Christ-Jésus? Sera-ce la tribulation, ou l\'angoisse, ou la persécution, ou la faim, ou la nudité, ou le péril, ou l\'épée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'selon qu\'il est écrit: « Car c\'est à cause de Toi que nous sommes mis à mort tout le long du jour; nous avons été regardés comme des brebis de tuerie? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Mais au contraire en tout cela nous sommes plus que vainqueurs grâce à Celui qui nous a aimés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'car je suis convaincu que ni la mort ni la vie, ni anges ni dominations, ni choses présentes ni choses à venir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'ni puissances, ni hauteur ni profondeur, ni aucune autre créature ne pourra nous séparer de l\'amour de Dieu manifesté en Christ-Jésus notre Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Je dis la vérité en Christ, je ne mens point, car ma conscience m\'en rend témoignage par l\'esprit saint:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'j\'éprouve un profond chagrin, et il y a dans mon cœur une douleur continuelle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'car je voudrais être moi-même anathème et séparé de Christ pour mes frères qui sont de ma race selon la chair;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'lesquels sont Israélites, auxquels appartiennent l\'adoption, et la gloire, et l\'alliance, et la promulgation de la loi, et le culte, et les promesses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'auxquels se rattachent les pères, et desquels est issu Christ, en ce qui concerne la chair, lui qui est au-dessus de toutes choses Dieu béni pour les siècles! Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Or, ce n\'est pas que la parole de Dieu ait été privée d\'effet, car tous ceux qui descendent d\'Israël ne sont pas Israël;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'et pour être la postérité d\'Abraham, tous ne sont pas non plus ses enfants, mais: c\'est en Isaac que se réalisera pour toi le nom de postérité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'ce qui signifie que ce ne sont pas les enfants de la chair qui sont enfants de Dieu, mais que ce sont les enfants de la promesse qui sont regardés comme une postérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'C\'est en effet une parole de promesse que celle-ci: « Vers cette époque-ci Je viendrai, et Sarra aura un fils. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Et non seulement cela, mais il en fut aussi de même pour Rebecca, qui n\'avait commerce qu\'avec un seul homme, Isaac notre père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'car ses fils n\'étaient pas encore nés et ils n\'avaient fait ni bien ni mal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'qu\'il lui fût dit, (afin que le décret d\'élection de Dieu eût tout son effet non par le fait des œuvres mais par le fait de Celui qui appelle): « Le plus grand sera asservi au moindre; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'conformément à ce qui est écrit: « J\'ai aimé Jacob, mais j\'ai haï Ésaü. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Que dirons-nous donc? Est-ce qu\'il y a de l\'injustice en Dieu? Loin de nous cette pensée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Il dit en effet à Moïse: « Je ferai miséricorde à qui Je veux faire miséricorde, et J\'aurai pitié de qui Je veux avoir pitié. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Ainsi donc cela ne dépend ni de la volonté ni de l\'activité de l\'homme, mais de Dieu qui fait miséricorde,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'car l\'écriture dit à Pharaon: « C\'est précisément pour manifester en toi Ma puissance, que Je t\'ai suscité, et pour que Mon nom fût proclamé sur toute la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Ainsi donc Il fait miséricorde à qui Il veut, mais Il endurcit qui Il veut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Tu me diras donc: « Pourquoi donc se montre-t-Il encore sévère? Car qui est-ce qui résiste à Sa volonté? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'O homme, toi, qui es-tu donc pour contester avec Dieu? Est-ce que la poterie dira à celui qui l\'a façonnée: Pourquoi m\'as-tu faite ainsi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Ou bien le potier n\'est-il pas le maître de sa glaise, pour, de la même masse, faire tel ustensile en vue d\'un noble usage, et tel autre en vue d\'un usage ignoble?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Eh bien! que dire, si Dieu, voulant manifester Sa colère et faire connaître Sa puissance, a supporté avec beaucoup de longanimité des ustensiles de colère fabriqués pour la perdition,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'afin de faire connaître la richesse de Sa gloire à l\'égard d\'ustensiles de miséricorde, qu\'il a d\'avance préparés pour la gloire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'C\'est de nous que je parle, nous qu\'il a encore appelés non seulement du milieu des Juifs, mais encore du milieu des Gentils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'comme il le dit aussi à Osée: « J\'appellerai Mon peuple celui qui n\'est pas Mon peuple, et bien-aimée celle qui n\'a pas été bien-aimée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'et il arrivera que dans le lieu même où il a été dit: Vous n\'êtes pas Mon peuple, ils seront appelés fils du Dieu vivant. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Mais Ésaïe s\'écrie au sujet d\'Israël: « Quand le nombre des fils d\'Israël égalerait le sable de la mer, le moindre reste en sera sauvé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'car le Seigneur exécutera pleinement et promptement Sa sentence sur la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Et comme l\'a prédit Ésaïe: « Si le Seigneur Sabaoth ne nous avait laissé une postérité, nous serions devenus comme Sodome et nous aurions été semblables à Gomorrhe. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Que dirons-nous donc? Nous dirons que les Gentils, qui n\'aspiraient pas à la justice, ont obtenu la justice, j\'entends la justice qui vient de la foi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'tandis qu\'Israël, qui aspirait à une loi qui donnât la justice, n\'y est pas parvenu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Pourquoi? Parce que ce n\'est pas de la foi qu\'il l\'a attendue; mais c\'est en quelque sorte par les œuvres qu\'ils ont heurté contre la pierre d\'achoppement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'selon qu\'il est écrit: « Voici, je place en Sion une pierre d\'achoppement et un roc de scandale, et celui qui fonde sa confiance sur elle n\'aura pas à en rougir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Frères, l\'affection de mon cœur et mes prières à Dieu sont tournées vers leur salut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'car je leur rends le témoignage qu\'ils ont du zèle pour Dieu, mais non pas avec discernement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'méconnaissant en effet la justice de Dieu, et cherchant à établir la leur propre, ils ne se sont pas soumis à la justice de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'car Christ met fin à la loi, pour donner la justice à celui qui croit, quel qu\'il soit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Moïse en effet définit la justice qui vient de la loi, en disant que « l\'homme qui les aura pratiqués vivra par elle, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'tandis que la justice qui vient de la foi parle ainsi: « Ne dis pas en ton cœur: Qui est-ce qui montera au ciel? » (ce qui revient à en faire descendre Christ);');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'ou bien: « Qui est-ce qui descendra dans l\'abîme? » (ce qui revient à ramener Christ du milieu des morts).');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Mais que dit-elle? « La parole est près de toi, dans ta bouche et dans ton cœur; » c\'est-à-dire la parole de la foi que nous prêchons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Car si tu professes de ta bouche la déclaration que Jésus est Seigneur, et si tu crois dans ton cœur que Dieu l\'a ressuscité d\'entre les morts, tu seras sauvé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'parce que c\'est du cœur que l\'on croit à la justice, et que c\'est de la bouche que l\'on fait profession pour le salut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'L\'écriture dit en effet: « Quiconque fonde sa confiance sur elle n\'aura pas à en rougir; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'car il n\'y a aucune différence entre le Juif et le Grec, vu que tous ont le même Seigneur, qui est riche pour tous ceux qui L\'invoquent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'car quiconque aura invoqué le nom du Seigneur sera sauvé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Comment donc invoqueront-ils Celui auquel ils n\'ont pas cru? Et comment croiront-ils en Celui dont ils n\'ont pas ouï parler? Et comment en ouïront-ils parler sans prédicateur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Et comment y aura-t-il des prédicateurs, s\'ils ne sont envoyés, conformément à ce qui est écrit: « Comme ils sont beaux les pieds de ceux qui annoncent la bonne nouvelle de bonnes choses? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Mais tous n\'ont pas obéi à la bonne nouvelle, car Ésaïe dit: « Seigneur, qui est-ce qui a cru à ce qu\'il a entendu de nous? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Ainsi donc la foi provient de ce que l\'on entend, et ce que l\'on entend résulte de la parole de Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Mais je me dis: peut-être n\'en ont-ils pas ouï parler? Bien au contraire: c\'est à toute la terre qu\'est parvenue leur voix, et c\'est jusqu\'aux extrémités du monde habité que sont allées leurs paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Mais je me dis: peut-être qu\'Israël ne l\'a pas su? Moïse le premier dit: « J\'exciterai votre jalousie envers une nation qui ne l\'est pas; Je provoquerai votre colère contre une nation sans intelligence. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Ésaïe de son côté s\'enhardit jusqu\'à dire: « J\'ai été trouvé parmi ceux qui ne Me cherchaient point; J\'ai apparu parmi ceux qui ne Me réclamaient point; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'tandis que, relativement à Israël, il dit: « Tout le long du jour J\'ai étendu Mes mains vers un peuple désobéissant et récalcitrant. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Je me dis donc: Dieu n\'a-t-il point rejeté Son peuple? Loin de nous cette pensée! Car moi aussi je suis Israélite, de la postérité d\'Abraham, de la tribu de Benjamin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Dieu n\'a point rejeté Son peuple que d\'avance Il avait élu. Ou bien ignorez-vous ce que dit l\'Écriture dans le passage où Élie implore Dieu contre Israël?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '« Seigneur, ils ont tué Tes prophètes, ils ont renversé Tes autels; et moi je suis demeuré seul, et ils en veulent à ma vie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Mais que lui dit la réponse divine? « J\'ai laissé subsister pour Moi sept mille hommes, qui n\'ont pas fléchi le genou devant la déesse Baal. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'De même donc, il y a eu aussi dans les circonstances actuelles un restant selon l\'élection de la grâce;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'mais si c\'est par grâce, cela ne vient plus des œuvres; puisque dans ce cas la grâce ne serait plus grâce. Si, au contraire, cela vient des œuvres, il n\'y a plus de grâce; puisque l\'œuvre n\'est plus une grâce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Qu\'y a-t-il donc à dire? C\'est que ce qu\'Israël recherche, il ne l\'a pas obtenu; mais les élus l\'ont obtenu, tandis que les autres ont été endurcis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'conformément à ce qui est écrit: « Dieu leur a donné un esprit d\'étourdissement, des yeux pour ne point voir et des oreilles pour ne point entendre, jusques au jour d\'aujourd\'hui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Et David dit: « Que leur table devienne pour eux un piège, une chasse, une pierre d\'achoppement, et une rétribution;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'que leurs yeux soient plongés dans des ténèbres qui les empêchent de voir; et tiens leur dos constamment courbé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Je me dis donc: n\'ont-ils point trébuché, afin qu\'ils tombassent? Loin de nous cette pensée! Mais c\'est à leur faute qu\'est dû le salut des Gentils, afin d\'exciter leur jalousie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Or, si leur faute fait la richesse du monde, et si leur défaite fait la richesse des Gentils, à combien plus forte raison leur pleine restauration!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Or, c\'est pour vous, Gentils, que je parle. En tant que je suis donc l\'apôtre des Gentils, je glorifie mon ministère en cherchant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 's\'il est possible, à exciter la jalousie de ma race et à en sauver quelques-uns.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Car si leur rejet fut la réconciliation du monde, que sera leur réhabilitation, sinon une vie surgissant d\'entre les morts?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Or, si les prémices sont saintes, la pâte l\'est aussi; et si la racine est sainte, les rameaux le sont aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Mais si quelques-uns des rameaux ont été arrachés, et si toi, qui es un olivier sauvage, tu as été greffé à leur place, et si tu as été mis en communication avec la racine d\'où l\'olivier tire son suc,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'ne prends pas les rameaux en pitié. Mais si tu le fais, sache que ce n\'est pas toi qui portes la racine, mais que c\'est la racine qui te porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Tu diras donc: « Les rameaux ont été arrachés, afin que moi je fusse greffé. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Sans-doute; mais c\'est pour cause d\'incrédulité qu\'ils ont été arrachés, et toi, c\'est par la foi que tu subsistes; n\'en conçois pas d\'orgueil, mais sois dans la crainte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'car si Dieu n\'a pas épargné les rameaux naturels, Il ne t\'épargnera pas non plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Considère donc la bonté et la sévérité de Dieu; d\'un côté la sévérité envers ceux qui sont tombés; de l\'autre envers toi la bonté de Dieu, si tu persistes à t\'en montrer digne; autrement, toi aussi, tu seras retranché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Et eux de même, s\'ils ne persistent pas dans l\'incrédulité, seront greffés; car Dieu est puissant pour les greffer de nouveau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'En effet, si toi, tu as été retranché de l\'olivier naturellement sauvage, et as été greffé contre nature sur un olivier franc, à combien plus forte raison, ceux-ci, qui sont les rameaux naturels, seront-ils greffés sur leur propre olivier?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Car je ne veux pas que vous ignoriez, frères, le mystère que voici, afin que vous ne vous complaisiez pas dans vos propres pensées: c\'est que l\'endurcissement s\'est partiellement emparé d\'Israël, jusques à ce que tout l\'ensemble des Gentils soit entré;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'et c\'est ainsi que tout Israël sera sauvé, selon qu\'il est écrit: « Le libérateur viendra de Sion, il éloignera les impiétés de Jacob;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'et telle est l\'alliance que Je leur octroierai, quand J\'aurai enlevé leurs péchés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'D\'un côté, en ce qui concerne l\'évangile, ils sont ennemis à cause de vous; de l\'autre, en ce qui concerne les promesses, ils sont aimés à cause de leurs pères;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'car les dons et l\'appel de Dieu sont irrévocables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'En effet, de même que vous avez jadis désobéi à Dieu, tandis que maintenant vous avez obtenu miséricorde à cause de leur désobéissance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'de même ceux-ci ont aussi désobéi maintenant à cause de la miséricorde qui vous est faite, afin qu\'eux aussi obtiennent maintenant miséricorde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'car Dieu a renfermé tous les hommes sous la désobéissance, afin de faire miséricorde à tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'O profondeur de la richesse, et de la sagesse, et de la science de Dieu! Que Ses jugements sont incompréhensibles et Ses voies impénétrables!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Car qui est-ce qui a connu la pensée du Seigneur; ou bien, qui est-ce qui a été Son conseiller;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'ou bien, qui est-ce qui d\'avance Lui a rien donné, et on l\'en dédommagera!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Car c\'est de Lui que procèdent, c\'est par Lui et pour Lui que sont toutes choses. A lui soit rendue la gloire pour les siècles! Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Je vous invite donc, frères, par les compassions de Dieu, à offrir vos corps comme un sacrifice vivant, saint et agréable à Dieu; c\'est là le culte que vous devez raisonnablement rendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Et ne vous modelez pas sur le siècle présent, mais soyez transfigurés par le renouvellement de votre intelligence, afin d\'apprécier ce qu\'est la volonté de Dieu, qui est bonne, agréable, et parfaite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Car, par la grâce qui m\'a été donnée, j\'invite chacun de vous à ne point nourrir des sentiments qui dépassent ceux qu\'il faut avoir, mais à être animé de sentiments convenables, proportionnés à la mesure de foi que Dieu a départie à chacun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'En effet, de même que, dans un seul corps, nous avons plusieurs membres, mais que tous les membres n\'ont pas la même fonction,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'de même nous sommes, quoique plusieurs, un seul corps en Christ, tandis que nous sommes, chacun pris à part, les membres les uns des autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Ayant ainsi des dons différents selon la grâce qui nous a été donnée, soit de prophétie, exerçons-le selon la proportion de la foi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'soit de ministère, exerçons-le dans le ministère; soit qu\'il s\'agisse de celui qui enseigne, qu\'il se livre à l\'enseignement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'ou de celui qui exhorte, qu\'il se livre à l\'exhortation; que celui qui distribue le fasse avec simplicité; que celui qui préside le fasse avec zèle; que celui qui compatit le fasse avec aménité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Que la charité soit sans hypocrisie. Ayez en haine le mal, attachez-vous fortement au bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Quant à l\'amour fraternel, soyez pleins d\'affection les uns pour les autres; quant aux égards, devancez-vous réciproquement; quant au zèle, ne soyez pas indolents. Soyez bouillants d\'esprit, asservis au Seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'joyeux par l\'espérance, fermes dans la tribulation,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'persévérants dans la prière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Prenez part aux besoins des saints, exercez l\'hospitalité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Bénissez les persécuteurs, bénissez et ne maudissez pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Réjouissez-vous avec ceux qui se réjouissent; pleurez avec ceux qui pleurent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Ayez, les uns pour les autres, des sentiments semblables. Ne visez pas aux grandeurs, mais laissez-vous attirer par ce qui est humble. Ne vous complaisez pas dans vos propres pensées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Ne rendez à personne mal pour mal; ayez à cœur ce qui est bon en présence de tous les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'S\'il est possible, pour autant que cela dépend de vous, soyez en paix avec tous les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Ne vous vengez point vous-mêmes, bien-aimés, mais laissez agir la colère; car il est écrit: « A Moi la vengeance; c\'est Moi qui rétribuerai, dit le Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Mais si ton ennemi a faim, donne-lui à manger; s\'il a soif donne-lui à boire; car en agissant ainsi tu entasseras des charbons de feu sur sa tête. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Ne sois pas subjugué par le mal, mais subjugue le mal par le bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Que toute personne soit soumise aux autorités supérieures; car il n\'existe d\'autorité que par la volonté de Dieu, et celles qui existent sont instituées de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'en sorte que celui qui s\'oppose à l\'autorité résiste à l\'institution de Dieu. Or, ceux qui résistent attireront sur eux-mêmes une condamnation,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'car les magistrats ne sont pas une cause d\'effroi pour la bonne conduite, mais pour la mauvaise. Veux-tu donc n\'avoir pas à craindre l\'autorité? Fais le bien, et tu recevras d\'elle des éloges;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'car celui qui l\'exerce est un serviteur de Dieu pour ton bien; mais si tu fais le mal, crains, car ce n\'est pas pour rien qu\'il porte l\'épée; il est en effet un serviteur de Dieu chargé de punir, pour satisfaire la colère, celui qui pratique le mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'C\'est pourquoi il y a nécessité de se soumettre, non seulement à cause de la colère, mais encore à cause de la conscience;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'c\'est pour cela en effet que vous payez aussi des impôts, car c\'est précisément en s\'occupant de cet objet qu\'ils sont ministres de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Rendez à tous ce qui leur est dû; l\'impôt, à qui est dû l\'impôt; le tribut, à qui est dû le tribut; la crainte, à qui est due la crainte; l\'honneur, à qui est dû l\'honneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Vous ne devez rien à personne, si ce n\'est de vous aimer les uns les autres; car celui qui aime autrui a accompli la loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'En effet les commandements: « Tu ne commettras point d\'adultère, tu ne tueras point, tu ne déroberas point, tu ne convoiteras point, » et tout autre qu\'on pourrait citer, se résument dans cette parole: « Tu aimeras ton prochain comme toi-même. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'La charité ne pratique pas le mal envers le prochain; la charité est donc l\'accomplissement de la loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Cela importe d\'autant plus que, connaissant les circonstances, vous savez que c\'est le moment de vous réveiller enfin du sommeil; car maintenant le salut est plus près de nous que quand nous avons cru,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'la nuit s\'avance et le jour s\'approche. Dépouillons-nous donc des œuvres des ténèbres, et revêtons les armes de la lumière;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'conduisons-nous convenablement, comme en plein jour, fuyant les excès et les orgies, le libertinage et les débauches, les disputes et les jalousies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Revêtez-vous au contraire de Christ-Jésus, et ne soignez pas la chair de manière à éveiller ses convoitises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Quant à celui qui est faible en sa persuasion, accueillez-le sans en venir à des querelles d\'opinion:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'l\'un croit pouvoir manger de tout, tandis que celui qui est faible ne mange que des légumes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Que celui qui mange ne méprise pas celui qui ne mange pas; mais que celui qui ne mange pas ne condamne pas celui qui mange, car Dieu l\'a pris à Son service.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Qui es-tu, toi qui condamnes un serviteur étranger? Qu\'il reste debout ou qu\'il tombe, cela regarde son propre maître; mais il restera debout, car son maître a le pouvoir de le faire tenir droit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'L\'un distingue un jour d\'un autre jour, tandis que l\'autre tient tous les jours pour égaux; que chacun soit dans sa propre intelligence pleinement persuadé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Celui qui met de l\'importance à tel ou tel jour le fait pour le Seigneur; et celui qui mange mange pour le Seigneur, car il rend grâces à Dieu; et celui qui ne mange pas le fait en vue du Seigneur, et il rend grâces à Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'En effet nul de nous ne vit pour lui-même, et nul ne meurt pour lui-même;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'car, soit que nous vivions, nous vivons pour le Seigneur; soit que nous mourions, nous mourons pour le Seigneur; soit donc que nous vivions, soit que nous mourions, nous appartenons au Seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'car Christ est mort et il a vécu afin de régner et sur les morts et sur les vivants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Mais toi, pourquoi condamnes-tu ton frère? Et toi, de ton côté, pourquoi méprises-tu ton frère? En effet nous comparaîtrons tous devant le tribunal de Dieu:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'car il est écrit: « J\'atteste sur Ma vie, dit le Seigneur, que devant Moi fléchira tout genou et que toute langue célébrera Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Ainsi chacun de nous rendra compte pour lui-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Ne nous condamnons donc plus les uns les autres; mais prenez plutôt la résolution de ne pas mettre devant votre frère une pierre de scandale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Je sais, et j\'ai dans le Seigneur Jésus la conviction, qu\'en soi rien n\'est souillé; ce n\'est que pour celui qui pense qu\'une chose est souillée, que cette chose-là est souillée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Eh bien! si, pour un aliment, ton frère est contristé, tu ne te conduis plus selon la charité; ne jette pas dans la perdition par ton aliment celui pour lequel Christ est mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Que votre privilège ne soit donc pas calomnié;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'car ce qui constitue le royaume de Dieu, ce n\'est pas le manger et le boire, mais la justice, et la paix, et la joie que donne l\'Esprit Saint;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'car celui qui s\'asservit ainsi à Christ est agréable à Dieu et aux hommes d\'un mérite éprouvé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'C\'est ainsi donc que nous poursuivons ce qui procure la paix et l\'édification mutuelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Ne détruis pas pour un aliment l\'œuvre de Dieu. Toutes choses sont pures il est vrai; mais c\'est un mal pour l\'homme qui en mange avec scandale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Il convient de ne point manger de viandes, de ne point boire de vin, et de s\'abstenir de ce qui fait trébucher ou scandalise ou fait faiblir ton frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Pour toi, conserve en toi-même devant Dieu la persuasion que tu as; heureux celui qui ne se juge pas lui-même dans le parti qu\'il adopte!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Mais celui qui hésite s\'il doit ou non manger est condamné, parce qu\'il n\'agit pas par persuasion; or tout ce qui ne se fait pas par persuasion est un péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Mais nous devons, nous qui sommes forts, supporter les faiblesses des faibles et ne pas nous complaire en nous-mêmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Que chacun de nous complaise à son prochain, pour lui être utile en contribuant à son édification.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Car ce n\'est pas non plus en lui-même que Christ s\'est complu, mais, selon qu\'il est écrit: « Les outrages de ceux qui T\'outragent sont retombés sur moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'En effet tout ce qui a été écrit, a tout été écrit pour notre instruction, afin que, par la persévérance et par la consolation qui viennent des Écritures, nous possédions l\'espérance qui procure la consolation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Cependant, que Dieu, qui accorde la persévérance et la consolation, vous donne d\'être animés entre vous de sentiments semblables, selon Christ-Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'afin que tous ensemble, d\'une seule bouche, vous glorifiez Dieu, qui est aussi le Père de notre Seigneur Jésus-Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'C\'est pourquoi occupez-vous les uns des autres, comme Christ s\'est aussi occupé de nous pour la gloire de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Je déclare en effet que Christ est devenu ministre de la circoncision pour maintenir la véracité de Dieu en confirmant les promesses faites à nos pères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'tandis que c\'est pour avoir reçu miséricorde que les Gentils glorifient Dieu, selon qu\'il est écrit: « C\'est pourquoi je Te célébrerai parmi les nations et je chanterai Ton nom. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Et elle dit derechef: « Nations, réjouissez-vous avec Son peuple. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Et elle dit encore: « Vous, toutes les nations, louez le Seigneur, et que tous les peuples célèbrent Ses louanges. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'Et Ésaïe dit encore: « La racine de Jessé apparaîtra; et celui qui se lève pour commander aux nations, c\'est en lui que les nations espéreront. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Eh bien, que Dieu, qui donne l\'espérance, vous fasse trouver une pleine certitude, avec une joie et une paix complètes, dans la foi en cette espérance, par la puissance de l\'Esprit saint!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Quoique je sois de mon côté convaincu, mes frères, en ce qui vous concerne, que vous êtes du vôtre remplis de bonnes dispositions, pleins de la connaissance parfaite, capables aussi de vous avertir les uns les autres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'je vous ai cependant écrit sur certains points avec moins de ménagements, dans l\'intention de réveiller vos souvenirs, à cause de la grâce que Dieu m\'a donnée');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'pour être le ministre de Christ-Jésus, faisant fonction de sacrificateur pour l\'évangile de Dieu, afin que l\'offrande des Gentils fût bien reçue, étant sanctifiée par l\'Esprit saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'C\'est donc en Christ que je m\'enorgueillis de ce qui regarde le service de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'car je n\'ai pas l\'audace de parler de choses que Christ n\'ait pas opérées par ma prédication aux Gentils, soit en paroles soit en œuvres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'grâce à la puissance des miracles et des prodiges par la puissance de l\'Esprit; en sorte que, depuis Jérusalem et tout alentour jusques en Illyrie, j\'ai pleinement répandu l\'évangile de Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'Mais je me fais un point d\'honneur de prêcher la bonne nouvelle de telle sorte, que ce ne soit pas là où le nom de Christ a été proclamé, afin de ne pas bâtir sur un fondement étranger,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'mais, selon qu\'il est écrit: « Ils verront, ceux auxquels on n\'en a pas parlé, et ceux qui n\'en n\'ont rien ouï dire comprendront. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'C\'est pourquoi aussi j\'ai souvent rencontré des obstacles qui m\'ont empêché d\'aller jusques à vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'mais maintenant n\'ayant plus affaire dans ces pays-ci, et ayant depuis bien des années un vif désir d\'aller jusques à vous');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'lorsque je me rendrai en Espagne... J\'espère en effet que je vous visiterai en passant, et que, après que je me serai imparfaitement rassasié de vous, vous me ferez faire escorte jusque-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Mais pour le moment je me rends à Jérusalem pour le service des saints,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'parce que la Macédoine a bien voulu, ainsi que l\'Achaïe, faire une collecte pour les pauvres d\'entre les saints qui sont à Jérusalem;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'ils l\'ont bien voulu en effet, comme étant leurs débiteurs, car, puisque les Gentils ont partagé leurs biens spirituels, ils doivent aussi les assister avec les biens charnels.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Après donc que j\'aurai terminé cette affaire et que je me serai déchargé de cette recette, je partirai pour l\'Espagne en passant par chez vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Or, je sais qu\'en venant à vous j\'y viendrai avec une pleine et entière bénédiction de Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'En attendant je vous invite, par notre seigneur Jésus-Christ et par la charité qu\'inspire l\'Esprit, à combattre avec moi dans les prières qui s\'adressent pour moi à Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'afin que je sois délivré des récalcitrants qui sont en Judée, et que le don que je porte à Jérusalem soit bien reçu par les saints,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'afin que ce soit dans la joie que je vienne à vous par la volonté du Seigneur Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Or, que le Dieu de paix soit avec vous tous! Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Or, je vous recommande Phébé notre sœur, qui est aussi diaconesse de l\'Église qui est à Cenchrées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'afin que vous la receviez selon le Seigneur comme il convient aux saints, et que vous l\'assistiez dans toute affaire où elle aura besoin de vous; car elle-même a été de son côté la protectrice de bien des gens, et la mienne en particulier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Saluez Prisca et Aquilas, mes coopérateurs en Christ-Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'qui ont offert leur propre tête pour sauver ma vie; ce n\'est pas moi seul qui leur en rends grâces, mais encore toutes les églises des Gentils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Saluez aussi l\'église qui se réunit dans leur maison. Saluez mon bien-aimé Epaïnetus, qui a été pour Christ les prémices de l\'Asie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Saluez Marie qui s\'est donnée beaucoup de peine pour vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Saluez Andronicus et Junie, mes parents et mes compagnons de captivité, qui sont avantageusement connus parmi les apôtres, et qui se sont aussi avant moi attachés à Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Saluez Amplias, qui est aimé dans le Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Saluez Urbanus notre coopérateur en Christ, et mon bien-aimé Stachys.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Saluez Apelles qui a fait ses preuves en Christ. Saluez ceux de la maison d\'Aristobule.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Saluez Hérodion mon parent. Saluez ceux de la maison de Narcisse qui sont amis du Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Saluez Tryphène et Tryphose qui travaillent pour le Seigneur. Saluez la chère Perside, qui a beaucoup travaillé pour le Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Saluez Rufus l\'élu dans le Seigneur, ainsi que sa mère qui est aussi la mienne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Saluez Asyncritos, Phlégon, Hermès, Patrobas, Hermas, et les frères qui sont avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Saluez Philologus et Julie, Nérée et sa sœur, et Olympas, et tous les saints qui sont avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Saluez-vous les uns les autres par un saint baiser. Toutes les églises de Christ vous saluent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Je vous invite cependant, frères, à avoir l\'œil sur ceux qui font naître les divisions et les occasions de chute, en s\'opposant à l\'enseignement que vous avez reçu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Éloignez-vous d\'eux; car de tels hommes ne s\'asservissent point à Christ notre Seigneur, mais à leur propre ventre; et, grâce à leurs beaux discours et à leurs bonnes paroles, ils trompent les cœurs des innocents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Car pour vous, votre obéissance est connue de tout le monde; j\'ai donc de quoi me réjouir à votre sujet, mais je désire que vous soyez sages relativement à ce qui est bien et purs relativement à ce qui est mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Or, le Dieu de paix broiera bientôt Satan sous vos pieds. Que la grâce de notre seigneur Jésus soit avec vous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Timothée mon coopérateur vous salue, ainsi que Lucius, Jason et Sosipatros mes parents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Moi, Tertius, qui ai écrit la lettre, je vous salue dans le Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Gaïus, mon hôte et celui de toute l\'église, vous salue. Eraste le trésorier de la ville vous salue, ainsi que Quartus son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, '[Que la grâce de notre Seigneur Jésus-Christ soit avec vous tous. Amen!]');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'A Celui qui peut vous affermir dans l\'attachement à mon évangile et à la prédication de Christ-Jésus, conformément à la révélation d\'un mystère de tout temps tenu secret,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'mais manifesté maintenant, et porté à la connaissance de tous les Gentils par des écrits prophétiques, selon l\'ordre du Dieu éternel et pour produire l\'obéissance de la foi, —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'à Dieu seul sage, soit rendue la gloire par Christ-Jésus, pour les siècles! Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paul, appelé à être apôtre de Christ Jésus par la volonté de Dieu, et le frère Sosthène,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'à l\'église de Dieu qui est dans Corinthe, et dont les membres sanctifiés en Christ Jésus sont appelés à être saints, ainsi qu\'à tous ceux qui invoquent le nom de notre seigneur Jésus-Christ en tous lieux, les leurs et les nôtres:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'que la grâce et la paix vous soient données par Dieu notre Père et par le seigneur Jésus-Christ!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Je rends perpétuellement des actions de grâces à Dieu pour vous, à cause de la grâce de Dieu qui vous a été donnée en Christ Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'car vous avez été enrichis en lui de toute manière en tout ce qui concerne le discours et la connaissance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'à proportion de ce que le témoignage de Christ s\'est affermi en vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'en sorte que vous n\'êtes dépourvus d\'aucun don, vous qui attendez la révélation de notre seigneur Jésus-Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'qui, de son côté, vous affermira jusques à la fin, de sorte que vous serez irrépréhensibles dans la journée de notre seigneur Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Il est fidèle, Dieu par qui vous avez été appelés à être associés à Son fils Jésus notre Seigneur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Mais je vous exhorte, frères, au nom de notre Seigneur Jésus-Christ, à tenir tous le même langage, et à ce qu\'il n\'y ait pas de divisions parmi vous, mais que vous soyez parfaitement unis d\'intelligence et d\'opinion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Car j\'ai été informé en ce qui vous concerne, mes frères, par les gens de Chloé, qu\'il y a des querelles parmi vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'je veux dire, que chacun de vous s\'exprime ainsi: « Quant à moi je tiens pour Paul » — « Moi, c\'est pour Apollos. » — « Moi, c\'est pour Céphas. » — « Moi, c\'est pour Christ. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Christ est-il partagé? Est-ce que Paul a été crucifié pour vous, ou bien est-ce au nom de Paul que vous avez été baptisés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Je rends grâces de ce que je n\'ai baptisé aucun de vous, sauf Crispus et Gaïus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'afin que personne ne dise que vous avez été baptisés en mon nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'j\'ai bien encore baptisé la famille de Stéphanas; du reste je ne sache pas que j\'aie baptisé quelque autre personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'En effet Christ ne m\'a pas envoyé pour baptiser, mais pour annoncer la bonne nouvelle; mais non pas avec une sagesse éloquente, afin que la croix de Christ ne fût pas rendue vaine;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'car, tandis que la prédication de la croix est une folie pour ceux qui périssent, pour nous qui sommes sauvés elle est une puissance de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'en effet il est écrit: « Je détruirai la sagesse des sages, J\'anéantirai l\'intelligence des intelligents. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Où y a-t-il un sage? Où un scribe? Où un disputeur de ce siècle? Dieu n\'a-t-Il pas frappé de folie la sagesse du monde? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Car, comme dans la sagesse de Dieu le monde n\'a pas reconnu Dieu par la sagesse, Dieu a jugé bon de sauver les croyants par la folie de la prédication,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'puisque, tandis que les Juifs demandent des miracles et que les Grecs de leur côté recherchent la sagesse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'du nôtre nous prêchons Christ crucifié, pour les Juifs un scandale, et pour les Gentils une folie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'mais pour eux-mêmes, quand ils ont été appelés, soit Juifs soit Grecs, Christ puissance de Dieu et sagesse de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'car la folie de Dieu est plus sage que les hommes, et la faiblesse de Dieu est plus forte que les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Considérez en effet, frères, que l\'appel qui vous a été adressé ne concerne ni beaucoup de sages selon la chair, ni beaucoup de puissants, ni beaucoup de nobles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'mais Dieu a choisi les choses folles du monde afin de confondre les sages, et Dieu a choisi les choses faibles du monde, afin de confondre les fortes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'et Dieu a choisi les choses basses du monde et celles qui sont méprisées et celles qui ne sont rien, pour renverser celles qui sont,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'afin que personne ne s\'enorgueillisse devant Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Or c\'est à Lui que vous devez d\'être unis à Christ Jésus qui, par la volonté de Dieu, est devenu notre sagesse, notre justice, notre sanctification et notre rédemption,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'afin que, comme il est écrit: « Que celui qui s\'enorgueillit s\'enorgueillisse dans le Seigneur! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Et moi-même aussi, frères, quand je suis arrivé parmi vous, je suis venu sans vous annoncer avec une grande supériorité de langage ou de sagesse le témoignage de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'car je ne me suis pas proposé de savoir quoi que ce soit parmi vous sauf Jésus-Christ, et Jésus-Christ crucifié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Et pour moi, c\'est dans un état de faiblesse et de crainte et de grande perplexité, que j\'ai vécu au milieu de vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'et mon langage et ma prédication n\'ont point consisté en discours persuasifs dictés par la sagesse, mais en une démonstration d\'esprit et de puissance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'afin que votre foi ne reposât pas sur la sagesse des hommes, mais sur la puissance de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'C\'est une sagesse, toutefois, que nous prêchons parmi les parfaits, mais une sagesse qui ne relève ni de ce siècle, ni des chefs de ce siècle qui sont anéantis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'nous prêchons au contraire la sagesse secrète de Dieu, la sagesse cachée que Dieu a prédestinée avant les siècles pour notre gloire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'qu\'aucun des chefs de ce siècle n\'a connue (car, s\'ils l\'eussent connue, ils n\'auraient pas crucifié le Seigneur de la gloire),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'mais, comme il est écrit, « les choses qu\'aucun œil n\'a vues, et aucune oreille entendues, et qui ne sont montées dans le cœur d\'aucun homme, toutes les choses que Dieu a préparées pour ceux qui L\'aiment. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'C\'est à nous, en effet, que Dieu les a révélées par l\'Esprit, car l\'Esprit scrute tout, et même les profondeurs de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'En effet, quel est parmi les hommes celui qui connaît ce qui se passe dans un homme, si ce n\'est l\'esprit de cet homme, qui est en lui? De même aussi personne n\'a connu ce qui se passe en Dieu, si ce n\'est l\'esprit de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Or, quant à nous, nous n\'avons pas reçu l\'esprit du monde, mais l\'esprit qui vient de Dieu, afin que nous connaissions ce que, par Sa grâce, Dieu nous a donné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'Et nous en parlons aussi, non avec des paroles enseignées par une sagesse humaine, mais enseignées par l\'Esprit, rapprochant spirituellement les choses spirituelles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'mais l\'homme animal n\'accepte pas ce qui vient de l\'esprit de Dieu, car c\'est pour lui une folie et il ne peut le comprendre, parce que c\'est spirituellement qu\'on en juge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Or, le spirituel juge toutes choses, tandis qu\'il n\'est lui-même jugé par personne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'car « qui est-ce qui a connu la pensée du Seigneur, pour pouvoir L\'instruire? » Mais nous, nous possédons la pensée du Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Pour moi, frères, je n\'ai pas pu vous parler comme à des spirituels, mais comme à des charnels, comme à des petits enfants. en Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'je vous ai abreuvés de lait et non d\'aliments solides, car vous n\'en étiez pas encore capables; mais vous ne l\'êtes pas même maintenant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'car vous êtes encore charnels. En effet, tant qu\'il y a parmi vous de la jalousie et des querelles, n\'êtes-vous pas charnels, et ne vous conduisez-vous pas d\'une manière tout humaine?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Car, lorsque l\'un dit: « Quant, à moi je tiens pour Paul; » et un autre: « Moi pour Apollos; » n\'êtes-vous pas des hommes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Qu\'est-ce donc qu\'Apollos? Et qu\'est-ce que Paul? Des ministres, par le moyen desquels vous avez cru, et cela, selon que le Seigneur a accordé à chacun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'C\'est moi qui ai planté, c\'est Apollos qui a arrosé, mais c\'est Dieu qui a fait croître,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'en sorte que celui qui plante n\'est rien, non plus que celui qui arrose, mais Dieu qui fait croître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Or celui qui plante et celui qui arrose sont égaux; mais chacun recevra sa propre rémunération, en raison de son propre travail;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'car c\'est de Dieu que nous sommes coopérateurs; c\'est de Dieu que vous êtes le champ, c\'est de Dieu que vous êtes l\'édifice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Selon la grâce de Dieu qui m\'a été donnée, j\'ai, comme un sage architecte, posé un fondement, mais un autre bâtit dessus; or c\'est à chacun de voir comment il bâtit dessus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'En effet personne ne peut poser un autre fondement que celui qui est posé, lequel est Jésus-Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'mais si quelqu\'un élève sur le fondement de l\'or et de l\'argent, des pierres précieuses, du bois, de l\'herbe, du chaume,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'l\'ouvrage de chacun sera mis en évidence, car la journée le manifestera, parce qu\'elle se révèle par le feu; et le feu fera voir de quelle nature est l\'ouvrage de chacun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Si l\'ouvrage bâti par quelqu\'un sur le fondement subsiste, il recevra sa récompense;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'si l\'ouvrage de quelqu\'un vient à être consumé, il le perdra, mais lui-même sera sauvé, toutefois comme au travers du feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Ne savez-vous pas que vous êtes le sanctuaire de Dieu, et que l\'esprit de Dieu habite en vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Si quelqu\'un détruit le sanctuaire de Dieu, Dieu le détruira lui-même, car le sanctuaire de Dieu est saint, ce que vous êtes vous-mêmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Que personne ne s\'abuse lui-même; si quelqu\'un pense être sage parmi vous au jugement de ce siècle-ci, qu\'il devienne fou pour devenir sage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'en effet la sagesse de ce monde est une folie devant Dieu, car il est écrit: « C\'est Lui qui prend les sages dans leur propre finesse, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'et: « Le Seigneur sait que les pensées des sages sont vaines. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Que personne donc ne mette son orgueil dans des hommes, car tout est à vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'soit Paul, soit Apollos, soit Céphas, soit le monde, soit la vie, soit la mort, soit les choses présentes, soit les choses à venir, tout est à nous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'mais nous, nous sommes à Christ, et Christ est à Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Ainsi l\'on doit nous regarder comme des employés de Christ et des administrateurs des mystères de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Ici, du reste, ce que l\'on demande des administrateurs, c\'est que chacun soit trouvé fidèle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'mais il est pour moi tout à fait indifférent d\'être jugé par vous ou par un tribunal humain, bien plus, je ne me juge pas même moi-même,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'car je ne me reproche rien, quoique ce ne soit pas par là que je suis justifié; mais celui qui me juge, c\'est le Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Ainsi ne portez aucun jugement avant le temps, jusques à ce que le Seigneur soit venu, qui mettra aussi en lumière ce que cachent les ténèbres et qui manifestera les desseins du cœur; et alors la louange sera accordée à chacun de la part de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'J\'ai figurément rapporté ce qui précède à moi-même et à Apollos, à cause de vous, pour que, d\'après nous, vous appreniez le précepte: « Pas au-dessus de ce qui est écrit; » afin que vous ne vous éleviez pas par orgueil en faveur de l\'un contre l\'autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Car qui est-ce qui te distingue? Et que possèdes-tu, que tu n\'aies reçu? Mais si, en effet, tu l\'as reçu, pourquoi t\'enorgueillis-tu, comme si tu ne l\'avais pas reçu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Vous êtes déjà rassasiés; vous êtes déjà enrichis; c\'est sans nous que vous avez été mis en possession du royaume; et puissiez-vous réellement avoir été mis en possession du royaume, afin que nous-mêmes aussi nous le soyons avec vous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Car il me semble que Dieu nous a placés, nous autres apôtres, au dernier rang des hommes, comme des condamnés à mort, car nous sommes devenus un spectacle pour le monde, pour les anges et les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Quant à nous, nous sommes fous à cause de Christ, mais vous, vous êtes prudents en Christ; nous sommes faibles, mais vous êtes forts; vous êtes couverts de gloire, mais nous d\'ignominie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'jusques à l\'heure présente nous souffrons et de la faim, et de la soif, et de la nudité; et nous sommes frappés de coups; et nous menons une vie errante;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'et nous nous fatiguons à travailler de nos propres mains; insultés, nous bénissons; persécutés, nous supportons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'calomniés, nous intercédons; nous sommes devenus comme les immondices du monde, le rebut de tous jusques à présent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Ce n\'est pas pour vous faire honte que j\'écris ces choses; mais je vous avertis comme mes chers enfants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Car, quand vous auriez en Christ dix mille précepteurs, vous n\'avez cependant pas plusieurs pères, puisque c\'est moi qui vous ai fait naître en Christ par l\'Évangile;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'je vous en conjure donc: devenez mes imitateurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'C\'est pourquoi je vous ai envoyé Timothée, mon enfant bien-aimé, et qui est fidèle dans le seigneur; il vous rappellera quelle est la route que je suis en Christ, quant à la manière dont j\'enseigne partout dans chaque église.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Or quelques-uns se sont enflés d\'orgueil, comme si je ne devais pas venir chez vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'mais je viendrai bientôt chez vous, si le Seigneur le veut, et je connaîtrai alors, non les discours, mais la puissance de ceux qui se sont enflés d\'orgueil,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'car le royaume de Dieu ne consiste pas en paroles, mais en puissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Que voulez-vous? Que ce soit avec une verge que je vienne chez vous, ou bien avec charité et un esprit de douceur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Le bruit est généralement répandu qu\'il y a parmi vous de l\'impudicité, et une impudicité telle qu\'elle n\'existe pas même chez les Gentils, car elle va jusques au point que l\'un de vous possède la femme de son père!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Et vous êtes enflés d\'orgueil! Et vous n\'êtes pas plutôt dans le deuil, afin que celui qui a commis cette action soit ôté du milieu de vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Car, pour moi, qui suis absent de corps, mais présent par l\'esprit, j\'ai déjà décidé, comme si j\'étais présent, de livrer celui qui a commis cette action,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'après que mon esprit et vos personnes ont été rassemblés au nom de notre seigneur Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'de livrer, dis-je, un tel homme à Satan, par la puissance de notre Seigneur Jésus, pour détruire sa chair, afin que l\'esprit soit sauvé dans la journée du seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Votre orgueil est bien mal placé! Ne savez-vous pas qu\'un peu de levain fait lever la pâte tout entière?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Faites disparaître le vieux levain, afin que vous soyez une pâte nouvelle; aussi bien êtes-vous sans levain, car notre pâque aussi a été immolée, je veux dire Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Célébrons donc la fête, non avec du vieux levain, non avec un levain de perversité et de méchanceté, mais avec les pains sans levain de la pureté et de la vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Je vous ai écrit dans ma lettre de ne pas avoir commerce avec les impudiques,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'non pas absolument avec les impudiques de ce monde, ou les cupides et les ravisseurs, ou les idolâtres, puisque, dans ce cas, vous devriez sortir du monde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'mais, en fait, je vous ai écrit de ne pas avoir de commerce avec celui qui, portant le titre de frère, serait impudique, ou cupide, ou idolâtre, ou outrageux, ou ivrogne, ou ravisseur, et de ne pas même manger avec un tel homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Car en quoi cela me regarde-t-il de juger ceux du dehors? N\'est-ce pas vous qui jugez ceux du dedans; tandis que ceux du dehors, c\'est Dieu qui les jugera?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Otez le méchant du milieu de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Quelqu\'un de vous ose-t-il, quand il est en procès avec un autre, se faire juger par les injustes, et non par les saints?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Ou bien ignorez-vous que ce sont les saints qui doivent juger le monde? Et, puisque c\'est par vous que doit être jugé le monde, êtes-vous indignes de jugements bien moins importants?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Ne savez-vous pas que nous jugerons les anges? Et nous ne jugerions pas les affaires civiles?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'S\'il s\'agit donc pour vous de jugements civils, ce sont ceux qui sont méprisés dans l\'Église que vous en chargez!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'C\'est pour vous faire rougir que je le dis. Ainsi il n\'existe parmi vous aucun prud\'homme qui puisse prononcer sur la plainte de son frère!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Mais un frère est en procès avec un frère, et cela devant des infidèles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Certes, c\'est déjà un grand dommage pour vous que d\'avoir entre vous des procès. Pourquoi ne souffrez-vous pas plutôt une injustice? Pourquoi ne vous laissez-vous pas plutôt spolier?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Mais c\'est vous, au contraire, qui commettez l\'injustice et qui pratiquez la spoliation, et cela, à l\'égard de vos frères!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Ou bien ignorez-vous que les injustes n\'hériteront point le royaume de Dieu? Ne vous y trompez pas: Ni les impudiques, ni les idolâtres, ni les adultères, ni les efféminés, ni les infâmes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'ni les voleurs, ni les cupides, ni les ivrognes, ni les outrageux, ni les ravisseurs n\'hériteront le royaume de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Et voilà ce que vous étiez, quelques-uns de vous. Mais vous avez été lavés, mais vous avez été sanctifiés, mais vous avez été justifiés par le nom de notre seigneur Jésus-Christ, et par l\'esprit de notre Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Tout m\'est permis, mais tout ne convient pas; tout m\'est permis, mais ce n\'est pas moi qui me laisserai dominer par rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Les aliments sont faits pour le ventre, et le ventre pour les aliments, mais Dieu détruira soit l\'un, soit les autres; tandis que le corps n\'est pas fait pour l\'impudicité, mais pour le Seigneur, et le Seigneur pour le corps;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'or Dieu qui a ressuscité le seigneur nous a aussi ressuscités par Sa puissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Ne savez-vous pas que vos corps sont des membres de Christ? Supprimerai-je donc les membres de Christ, pour en faire les membres d\'une prostituée? Loin de moi cette pensée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Ou bien ignorez-vous que celui qui s\'unit à la prostituée forme avec elle un seul et même corps? « Car les deux, est-il dit, deviendront une seule chair. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Mais celui qui est uni au seigneur est un seul et même esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Fuyez l\'impudicité: quelque péché qu\'un homme puisse commettre, il a lieu hors du corps, mais l\'impudique pèche contre son propre corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Ou bien ignorez-vous que votre corps est le sanctuaire de l\'esprit saint qui est en vous et que vous tenez de Dieu, et que vous ne vous appartenez pas à vous-mêmes?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Vous avez en effet été chèrement achetés; glorifiez donc Dieu dans votre corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Quant aux points sur lesquels vous m\'avez écrit, je réponds qu\'il est bon pour un homme de s\'abstenir de femme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'toutefois que chacun, à cause des impudicités, ait sa propre femme, et que chacune ait son propre mari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Que le mari paie sa dette à sa femme, et la femme de même à son mari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'La femme n\'a pas autorité sur son propre corps, mais c\'est le mari; de même aussi le mari n\'a pas autorité sur son propre corps, mais c\'est la femme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'ne vous privez pas l\'un de l\'autre, si ce n\'est momentanément d\'un commun accord, afin de vaquer à la prière et de vous rapprocher de nouveau, afin que Satan ne vous séduise pas à la faveur de votre incontinence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Toutefois c\'est par condescendance, et non comme un ordre, que je dis cela,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'car je voudrais que tous les hommes fussent comme moi; mais chacun tient de Dieu une grâce particulière, l\'un d\'une façon, et l\'autre d\'une autre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Or, je déclare à ceux qui ne sont pas mariés, et aux veuves, qu\'il leur est bon de demeurer dans l\'état où je suis aussi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'mais s\'ils manquent de continence, qu\'ils se marient, car il vaut mieux se marier que de brûler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Quant à ceux qui sont mariés, je leur prescris (non pas moi toutefois, mais le Seigneur), que la femme ne se sépare pas de son mari;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, '(si toutefois elle s\'en sépare, qu\'elle demeure hors mariage, ou se réconcilie avec son mari); et que le mari ne répudie pas sa femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Quant aux autres, c\'est moi, et non le Seigneur, qui leur dis: si un frère a une femme incrédule, et que celle-ci consente à habiter avec lui, qu\'il ne la répudie pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'et qu\'une femme qui a un mari incrédule, si celui-ci consent à habiter avec elle, qu\'elle ne répudie pas son mari;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'car le mari incrédule a été sanctifié par sa femme, et la femme incrédule a été sanctifiée par le frère, puisque autrement vos enfants seraient impurs, tandis qu\'en fait ils sont saints.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Mais si l\'incrédule se sépare, qu\'on le laisse faire; le frère ou la sœur ne sont pas asservis dans des cas pareils, mais c\'est pour vivre dans la paix que Dieu nous a appelés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'En effet que sais-tu, ô femme, si tu sauveras ton mari? Ou que sais-tu, ô homme, si tu sauveras ta femme?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Seulement, que chacun se conduise selon le lot que le Seigneur lui a départi, selon l\'appel que Dieu lui a adressé; et c\'est ainsi que j\'ordonne dans toutes les églises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Quelqu\'un a été appelé étant circoncis, qu\'il ne simule pas l\'incirconcision. Quelqu\'un a été appelé étant incirconcis, qu\'il ne se fasse pas circoncire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'La circoncision n\'est rien, et l\'incirconcision n\'est rien, mais ce qui est tout, c\'est d\'observer les commandements de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Que chacun demeure en l\'état où il était quand il a été appelé:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'as-tu été appelé étant esclave, ne t\'en fais point de souci, mais, quand même tu peux devenir libre, reste plutôt ce que tu es,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'car l\'esclave qui a été appelé dans le seigneur est un affranchi du seigneur; de même aussi l\'homme libre qui a été appelé est un esclave de Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Vous avez été chèrement achetés; ne devenez pas esclaves des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Frères, que chacun demeure devant Dieu dans l\'état où il était lorsqu\'il a été appelé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Quant à ceux qui sont vierges, je ne possède aucun ordre du seigneur, mais je donne un avis, comme ayant reçu de la miséricorde du Seigneur la grâce d\'être fidèle:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'je pense donc qu\'il est bon, vu l\'imminente crise, qu\'il est bon, dis-je, à un homme d\'être en cet état.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Es-tu lié à une femme? Ne cherche pas à t\'en détacher. N\'as-tu plus de femme? Ne recherche pas de femme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Toutefois, quand même tu t\'es marié, tu n\'as pas péché, et si quelqu\'un qui est vierge s\'est marié, il n\'a pas péché; mais ceux qui agissent ainsi auront des tribulations en leur chair, tandis que moi je vous ménage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Or ce que je dis, frères, c\'est que le temps qui reste est court, afin que ceux aussi qui ont des femmes soient comme n\'en ayant pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'et ceux qui pleurent comme ne pleurant pas, et ceux qui se réjouissent comme ne se réjouissant pas, et ceux qui achètent comme ne possédant pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'et ceux qui usent du monde comme n\'en abusant pas; car la figure de ce monde passe;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'or je voudrais que vous fussiez libres de toute inquiétude. Celui qui n\'est pas marié s\'inquiète des choses du Seigneur, et de la manière dont il plaira au Seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'tandis que celui qui est marié s\'inquiète des choses du monde, et de la manière dont il plaira à sa femme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'et il est partagé. La femme non mariée et la vierge s\'inquiètent aussi des choses du Seigneur, afin d\'être saintes, et de corps, et d\'esprit, tandis que celle qui est mariée s\'inquiète de la manière dont elle plaira à son mari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'C\'est dans votre intérêt que je vous parle ainsi, non pour vous prendre dans un filet, mais en vue de ce qui convient et de ce qui affermit dans le Seigneur sans distraction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Toutefois, si quelqu\'un pense qu\'il est inconvenant pour sa fille de la laisser dépasser la fleur de l\'âge, et qu\'il faut que cela se fasse ainsi, qu\'il agisse comme il l\'entend; il ne pèche pas; qu\'ils se marient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Mais celui qui est parfaitement décidé en son cœur, qui, loin de subir aucune nécessité, possède le plein exercice de sa propre volonté, et qui a résolu en son cœur de conserver sa fille vierge, celui-là fera bien;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'en sorte que celui qui marie sa fille vierge fera bien, et celui qui ne la marie pas fera mieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Une femme est liée pendant tout le temps que vit son mari; mais si son mari est venu à mourir, elle est libre de se marier à qui elle veut; seulement, que ce soit dans le seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'toutefois, si elle demeure comme elle est, elle est plus heureuse à mon avis, car je m\'imagine que moi aussi je possède l\'esprit de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Quant aux viandes sacrifiées aux idoles, nous savons que tous nous possédons la connaissance. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'La connaissance inspire l\'orgueil, tandis que la charité édifie; si quelqu\'un s\'imagine avoir connu quelque chose, il n\'a pas encore connu comme il faut connaître;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'mais si quelqu\'un aime Dieu, il est connu de Lui. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'En ce qui concerne donc la manducation des viandes sacrifiées aux idoles, nous savons qu\'il n\'existe point d\'idoles dans le monde, et qu\'il n\'existe point de Dieu, qu\'Un Seul.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Et, en effet, quand bien même il existe de soi-disant dieux, soit au ciel, soit sur la terre, comme effectivement il existe plusieurs dieux et plusieurs seigneurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'pour nous, nous n\'avons qu\'un seul Dieu, le Père par lequel existent toutes choses, et nous-mêmes pour Lui, et un seul seigneur, Jésus-Christ, à cause duquel toutes choses existent, et nous-mêmes par lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Or la connaissance n\'est pas le partage de tous, mais quelques-uns, par l\'habitude qu\'ils ont encore de l\'idole, croient manger une viande sacrifiée à une idole, et leur conscience qui est faible en est souillée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Mais ce n\'est pas un aliment qui déterminera notre place devant Dieu: si nous ne mangeons pas, nous n\'avons nul désavantage, et, si nous mangeons, nous n\'avons nulle supériorité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Toutefois, prenez garde que cette liberté qui vous appartient ne devienne pas une cause d\'achoppement pour ceux qui sont faibles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'En effet, si l\'un d\'eux voit celui qui possède la connaissance à table dans un temple idolâtre, est-ce que sa conscience, puisqu\'il est faible, n\'en sera pas édifiée au point de lui faire manger les viandes sacrifiées aux idoles?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'C\'est en effet par la connaissance que périt celui qui est faible, le frère pour lequel Christ est mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Mais en péchant ainsi contre vos frères, et en blessant leur conscience faible, vous péchez contre Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'C\'est pourquoi, si un aliment scandalise mon frère, je ne mangerai certainement jamais de viande, afin de ne pas scandaliser mon frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Ne suis-je pas libre? Ne suis-je pas apôtre? Est-ce que je n\'ai pas vu Jésus notre seigneur? N\'êtes-vous pas vous-mêmes mon œuvre dans le seigneur?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Si, pour d\'autres, je ne suis pas un apôtre, en revanche du moins je le suis pour vous, car vous êtes le sceau de mon apostolat dans le seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Voilà la justification que j\'oppose à ceux qui me critiquent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Est-ce que nous n\'avons pas le droit de manger et de boire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Est-ce que nous n\'avons pas le droit de mener avec nous une sœur qui soit notre femme, comme le font aussi les autres apôtres, et les frères du seigneur, et Céphas?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Ou bien, moi seul et Barnabas n\'avons-nous pas le droit de ne point travailler?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Qui est-ce qui fait le service militaire à ses propres dépens? Qui est-ce qui plante une vigne, et n\'en mange pas le fruit? Qui est-ce qui fait paître un troupeau, et ne se nourrit pas du lait de ce troupeau?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Est-ce d\'un point de vue humain que je parle ainsi, ou bien la loi aussi ne dit-elle pas les mêmes choses?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'En effet il est écrit dans la loi de Moïse: « Tu n\'emmusèleras pas le bœuf qui foule le grain. » Est-ce que Dieu prend souci des bœufs?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Ou bien parle-t-Il uniquement à cause de nous? C\'est à cause de nous en effet que cela a été écrit, car celui qui laboure doit labourer avec espérance, et celui qui foule le grain avec l\'espérance d\'en avoir sa part.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Si, pour vous nous avons semé les choses spirituelles, est-il extraordinaire que nous moissonnions vos biens charnels?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Si d\'autres possèdent des droits sur vous, n\'en possédons-nous pas nous-mêmes à plus forte raison? Mais nous n\'avons pas usé de ces droits; au contraire nous endurons tout pour ne pas créer d\'obstacle à l\'évangile de Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Ne savez-vous pas que ceux qui vaquent aux sacrifices tirent leur nourriture du temple, et que ceux qui sont employés au service de l\'autel entrent en partage avec l\'autel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'De même aussi le Seigneur a prescrit à ceux qui annoncent l\'Évangile de vivre de l\'Évangile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Pour moi je n\'ai fait usage d\'aucun de ces droits. Mais je n\'écris pas ainsi afin que cela me soit appliqué, car mieux me vaudrait mourir; ou plutôt, ce qui est pour moi un motif de m\'enorgueillir, personne ne le détruira.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'En effet, ce n\'est pas de prêcher la bonne nouvelle, qui est pour moi un motif de m\'enorgueillir, car c\'est une nécessité qui m\'est imposée; en effet, malheur à moi si je n\'annonçais pas la bonne nouvelle!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Car, si c\'est volontairement que j\'agis ainsi, je reçois une récompense, mais si c\'est involontairement, c\'est une administration qui m\'est confiée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Quelle est donc ma récompense? C\'est, en prêchant la bonne nouvelle, d\'offrir gratuitement l\'Évangile, afin de ne pas user de mes droits dans la prédication de l\'Évangile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Car moi, qui suis indépendant de tous, je me suis asservi à tous, afin d\'en gagner le plus grand nombre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'et j\'ai été pour les Juifs comme un Juif, afin de gagner les Juifs; pour ceux qui sont sous la loi comme étant moi-même sous la loi (quoique je ne sois point sous la loi), afin de gagner ceux qui sont sous la loi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'pour ceux qui sont sans loi, comme étant moi-même sans loi (quoique je ne sois point sans la loi de Dieu et que je vive au contraire dans la loi de Christ), afin de gagner ceux qui sont sans loi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'j\'ai été faible pour les faibles, afin de gagner les faibles; j\'ai été tout pour tous, afin d\'en sauver sûrement quelques-uns.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Or je fais tout à cause de l\'Évangile, afin d\'en prendre aussi ma part.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Ne savez-vous pas que ceux qui courent dans le stade courent tous, il est vrai, mais qu\'un seul remporte le prix? Courez de manière à l\'obtenir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Or tout athlète use d\'une complète abstinence: ceux-là donc afin de remporter une couronne périssable, mais nous, une impérissable;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'je cours donc, mais non sans savoir où je vais; je lutte, mais de manière à ne pas battre l\'air de mes coups;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'mais je frappe mon propre corps et je le traite en esclave, de peur qu\'après avoir servi de héraut pour les autres, je ne sois moi-même mis de côté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'En effet je ne veux pas que vous ignoriez, frères, que nos pères étaient tous sous la nuée et que tous ils ont traversé la mer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'et que tous ils ont été baptisés en Moïse dans la nuée et dans la mer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'et que tous ils ont mangé le même aliment spirituel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'et que tous ils ont bu le même breuvage spirituel, car ils s\'abreuvaient à un rocher spirituel qui les suivait, or ce rocher était Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Toutefois ce ne fut pas au plus grand nombre d\'entre eux que Dieu prit plaisir, car ils demeurèrent gisants dans le désert.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Or toutes ces choses ont eu lieu pour nous servir d\'exemples, afin que nous ne convoitions point de mauvaises choses, comme eux-mêmes l\'ont fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Ne devenez pas non plus idolâtres, comme quelques-uns d\'entre eux, selon qu\'il est écrit: « Le peuple s\'assit pour manger et boire, et ils se levèrent pour jouer. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Ne nous livrons pas non plus à l\'impudicité, comme s\'y livrèrent quelques-uns d\'entre eux, et ils périrent en un seul jour au nombre de vingt-trois mille.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Ne tentons pas non plus le Seigneur, comme le tentèrent quelques-uns d\'entre eux, et ils étaient tués par les serpents.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Ne murmurez pas non plus, comme murmurèrent quelques-uns d\'entre eux, et ils furent tués par l\'exterminateur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Or ces choses leur arrivaient figurément, mais elles ont été écrites pour notre instruction, pour nous, auxquels a abouti la fin des siècles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'ainsi donc que celui qui s\'imagine rester debout prenne garde qu\'il ne tombe!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Vous n\'avez pas été exposés à des tentations surhumaines, et, Dieu, qui est fidèle, ne permettra pas que vous soyez tentés au delà de vos forces; au contraire, avec la tentation Il vous donnera le moyen d\'en sortir, afin que vous puissiez la supporter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'C\'est pourquoi, mes bien-aimés, fuyez l\'idolâtrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Je vous parle comme à des gens sensés; jugez vous-mêmes de ce que je dis:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'La coupe de la bénédiction que nous bénissons, n\'est-elle pas une participation au sang de Christ? Le pain que nous rompons, n\'est-il pas une participation au corps de Christ?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Car, comme il y a un seul pain, de même notre pluralité ne forme qu\'un seul corps, car tous nous participons à ce seul pain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Voyez l\'Israël selon la chair: est-ce que ceux qui se nourrissent des sacrifices n\'entrent pas en partage avec l\'autel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Que dis-je donc? Que la viande sacrifiée aux idoles est quelque chose, ou bien qu\'une idole est quelque chose? Non,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'mais que ce qu\'ils sacrifient, c\'est à des démons, et non à Dieu, qu\'ils le sacrifient; or je ne veux pas que vous entriez en partage avec les démons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'vous ne pouvez boire la coupe du seigneur et la coupe des démons; vous ne pouvez prendre part à la table du seigneur et à la table des démons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Ou bien, voulons-nous provoquer le Seigneur? Est-ce que nous sommes plus forts que Lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Tout est permis, mais tout ne convient pas; tout est permis, mais tout n\'édifie pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Que personne ne recherche son propre intérêt, mais celui d\'autrui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Mangez de tout ce qui se vend au marché, sans vous enquérir de rien par motif de conscience,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'car c\'est au Seigneur qu\'appartient la terre et tout ce qui la remplit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Si un incrédule vous invite et que vous vouliez y aller, mangez de tout ce qui est servi, sans vous enquérir de rien par motif de conscience;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'mais si quelqu\'un vous dit: « Ceci a été offert en sacrifice, » n\'en mangez pas à cause de celui qui vous en a averti, et de la conscience,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'non que ce soit de votre conscience que je parle, mais de celle de l\'autre. En effet, pourquoi ma liberté serait-elle jugée par une conscience étrangère?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Si moi-même je prends part au repas avec action de grâces, pourquoi serais-je calomnié à propos de ce dont je rends grâces?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Ainsi donc, soit que vous mangiez, soit que vous buviez, soit que vous fassiez quelque chose, faites tout pour la gloire de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Ne soyez en scandale ni aux Juifs, ni aux Grecs, ni à l\'église de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'comme moi-même je m\'applique en toutes choses à plaire à tous, ne recherchant point mon avantage particulier, mais celui du plus grand nombre, afin qu\'ils soient sauvés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Soyez mes imitateurs, comme je suis moi-même celui de Christ!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Je vous loue de ce que vous vous souvenez de moi à tous égards, et de ce que vous retenez les traditions, telles que je vous les ai transmises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Je veux cependant que vous sachiez que la tête de tout homme c\'est Christ, tandis que la tête d\'une femme, c\'est son mari, et que la tête de Christ, c\'est Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Tout homme qui prie ou qui prophétise en ayant la tête recouverte, déshonore sa tête,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'tandis que toute femme qui prie ou qui prophétise sans avoir la tête voilée, déshonore sa propre tête; car elle est une seule et même chose que la femme qui est rasée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'En effet, si la femme n\'est pas voilée, il faut qu\'elle se fasse tondre ou qu\'elle se fasse raser; mais s\'il est honteux pour une femme d\'être tondue ou rasée, il faut qu\'elle soit voilée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'En effet, si l\'homme ne doit pas, parce qu\'il est l\'image et la gloire de Dieu, avoir la tête voilée, la femme en revanche est la gloire de l\'homme; —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'en effet l\'homme n\'est pas issu de la femme, mais la femme de l\'homme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'car l\'homme n\'a pas été créé à cause de la femme, mais la femme à cause de l\'homme; —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'c\'est pourquoi la femme doit avoir une suprématie sur la tête à cause des anges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Néanmoins, ni la femme n\'existe séparément de l\'homme, ni l\'homme séparément de la femme, dans le seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'car, de même que la femme est issue de l\'homme, de même aussi l\'homme naît par l\'entremise de la femme, mais le tout procède de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Jugez-en par vous-mêmes: est-il convenable qu\'une femme prie Dieu sans être voilée?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'La nature elle-même ne vous enseigne-t-elle pas que si l\'homme porte une longue chevelure, c\'est une honte pour lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'tandis que si la femme porte une longue chevelure, c\'est une gloire pour elle, parce que la chevelure lui a été donnée en guise de voile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Mais si quelqu\'un paraît disposé à contester, pour nous, telle n\'est pas notre habitude, non plus que celle des églises de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Or ce sont ici des ordres, et non des éloges, que j\'ai à vous donner, car vous faites tourner vos réunions, non à votre amélioration, mais à votre détriment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'J\'apprends en effet, en premier lieu, que, lorsque vous vous réunissez en assemblée d\'église, il existe des divisions parmi vous, — et je le crois en partie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'car il faut qu\'il y ait aussi des schismes parmi vous, afin que l\'on reconnaisse aussi ceux qui chez vous ont tenu bon; —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'lors donc que vous vous réunissez ensemble, on ne peut pas manger un repas dominical,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'car, en mangeant, chacun prend pour lui-même son propre repas, en sorte que l\'un est affamé, tandis que l\'autre est ivre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Est-ce que vous n\'avez pas des maisons pour y manger et boire? Ou bien méprisez-vous l\'église de Dieu, et voulez-vous outrager les indigents? Que vous dirai-je? Est-ce que je vous loue? Sur ce point, je ne vous loue pas,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'car j\'ai moi-même reçu du seigneur ce que je vous ai aussi transmis, c\'est que le seigneur, dans la nuit où il fut livré, prit un pain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'et après avoir rendu grâces, il le rompit et dit: « Ceci est mon corps, qui est pour vous, faites ceci en mémoire de moi; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'de même aussi la coupe après le repas, en disant: « Cette coupe est la nouvelle alliance en mon sang, faites ceci, toutes les fois que vous en buvez, en mémoire de moi. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Toutes les fois, en effet, que vous mangez ce pain et que vous buvez cette coupe, vous annoncez la mort du seigneur, jusques à ce qu\'il soit venu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'en sorte que quiconque aura mangé le pain, ou bu la coupe du seigneur indignement, sera coupable envers le corps et le sang du seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Mais que chacun s\'examine lui-même, et qu\'en conséquence il mange le pain et boive la coupe,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'car celui qui mange et boit mange et boit pour lui-même une condamnation, s\'il ne reconnaît pas ce qu\'est le corps;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'c\'est pourquoi il y en a plusieurs parmi vous qui sont infirmes et malades, et qu\'un grand nombre sont morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Mais si nous nous examinions nous-mêmes, nous ne serions pas jugés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'toutefois en étant jugés, nous sommes châtiés par le Seigneur afin de n\'être pas condamnés avec le monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Ainsi, mes frères, lorsque vous vous réunissez pour le repas, attendez-vous les uns les autres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'si quelqu\'un a faim qu\'il mange chez lui, afin que vous ne vous réunissiez pas pour votre condamnation. Quant au reste, dès que je serai arrivé, je le réglerai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Mais en ce qui concerne les dons spirituels, je ne veux pas, frères, que vous soyez dans l\'ignorance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Vous savez comment, lorsque vous étiez des gentils, vous vous laissiez entraîner vers les idoles muettes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'c\'est pourquoi je vous informe que personne, quand il parle par l\'esprit de Dieu, ne dit: « Maudit est Jésus, » et que personne ne peut dire: « Jésus est seigneur, » que par l\'esprit saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Il y a cependant des diversités dans les dons, mais c\'est le même Esprit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Il y a aussi des diversités dans les emplois, et le même seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'il y a aussi des diversités dans les opérations, et c\'est le même Dieu qui les opère toutes en tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Mais la manifestation de l\'Esprit est donnée à chacun, en vue de ce qui est utile:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'en effet, à l\'un est donnée par l\'Esprit un discours de sagesse, tandis qu\'à un autre c\'est un discours de connaissance, conformément au même Esprit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'à un autre est donnée la foi, grâce au même Esprit, tandis qu\'à un autre ce sont des dons de guérisons, grâce au seul et unique Esprit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'mais à un autre ce sont des opérations miraculeuses, à un autre une prophétie, à un autre des jugements d\'esprits, à un autre des variétés de langues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Mais c\'est le seul et même Esprit qui opère toutes ces choses, les dispensant en particulier à chacun comme il veut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'En effet, de même que le corps forme un seul tout et possède plusieurs membres, mais que tous les membres du corps, bien qu\'ils soient plusieurs, forment un seul corps, de même en est-il aussi de Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'car c\'est dans un seul Esprit que tous nous avons été baptisés pour ne former qu\'un seul corps, soit Juifs, soit Grecs, soit esclaves, soit libres, et tous nous avons été abreuvés d\'un seul Esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'En effet le corps aussi n\'est pas formé d\'un seul membre, mais de plusieurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Si le pied disait: « Parce que je ne suis pas une main, je ne fais pas partie du corps; il ne cesse pas pour cela de faire partie du corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'Et si l\'oreille disait: « Parce que je ne suis pas un œil, je ne fais pas partie du corps; » elle ne cesse pas pour cela de faire partie du corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Si le corps entier n\'était qu\'un œil, où serait l\'ouïe? S\'il n\'était tout entier qu\'ouïe, où serait l\'odorat?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Mais maintenant Dieu a disposé chacun des membres dans le corps comme Il l\'a voulu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'or si tous ils ne formaient qu\'un seul membre, où serait le corps?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Mais maintenant il y a plusieurs membres, tandis qu\'il n\'y a qu\'un seul corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Or l\'œil ne peut pas dire à la main: « Je n\'ai pas besoin de toi; » ou bien encore la tête dire aux pieds: « Je n\'ai pas besoin de vous. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Combien plus au contraire les membres du corps qui semblent être plus faibles sont-ils nécessaires;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'et ceux qui nous semblent être les moins honorables du corps, ce sont ceux-là que nous entourons d\'un plus grand honneur, et nos membres indécents sont couverts avec plus de décence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'tandis que ceux qui sont décents n\'en ont pas besoin. Or Dieu a composé le corps en donnant davantage à la partie qui a été privée de quelque chose,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'afin qu\'il n\'y eût pas de division dans le corps, mais que les membres eussent le même intérêt les uns pour les autres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'et si un seul membre souffre de quoi que ce soit, tous les membres souffrent avec lui, et si un membre est honoré, tous les membres s\'en réjouissent avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Or, pour vous, vous êtes le corps de Christ, et partiellement ses membres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'et Dieu a établi les uns dans l\'église, d\'abord comme apôtres, secondement comme prophètes, troisièmement comme docteurs, ensuite des miracles, ensuite des dons de guérisons, des emplois d\'assistance, des fonctions de gouvernement, des variétés de langues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Est-ce que tous sont apôtres? Est-ce que tous sont prophètes? Est-ce que tous sont docteurs? Est-ce que tous font des miracles?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Est-ce que tous possèdent des dons de guérisons? Est-ce que tous parlent en langues? Est-ce que tous interprètent?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Ambitionnez cependant les dons les plus grands, et je vais encore vous indiquer une route excellente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Quand je parlerais les langues des hommes et des anges, si je n\'ai pas de charité, je suis un airain retentissant, ou une cymbale bruyante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Et quand j\'aurais un don de prophétie, et que je connaîtrais tous les mystères et toute la connaissance, et quand j\'aurais toute la foi qui déplace les montagnes, si je n\'ai pas de charité, je ne suis rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Et quand j\'emploierais en libéralités tout ce que je possède, et quand je livrerais mon corps afin d\'en tirer gloire, si je n\'ai pas de charité, cela ne me sert de rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'La charité est patiente, la charité est bienveillante; elle n\'est pas jalouse, elle ne s\'en croit point, elle ne s\'enfle point d\'orgueil,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'elle n\'agit point avec indécence, elle ne recherche point ce qui ne lui appartient pas, elle ne s\'irrite point, elle ne tient pas compte du mal,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'elle ne se réjouit point de l\'injustice, mais elle se réjouit avec la vérité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'elle supporte tout, elle croit tout, elle espère tout, elle surmonte tout.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'La charité ne périt jamais; mais quant à la prophétie, elle sera détruite; quant aux langues, elles cesseront; quant à la connaissance, elle sera détruite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'car c\'est partiellement que nous connaissons, et c\'est partiellement que nous prophétisons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'mais quand ce qui est parfait sera venu, ce qui est partiel sera détruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Lorsque j\'étais enfant, je parlais comme un enfant, je pensais comme un enfant, je raisonnais comme un enfant; lorsque je suis devenu un homme, j\'ai détruit ce qui était de l\'enfant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Maintenant en effet nous voyons au moyen d\'un miroir, d\'une manière obscure, mais alors ce sera face à face; maintenant je connais partiellement, mais alors je connaîtrai comme j\'ai été connu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Mais pour le moment ces trois choses demeurent: la foi, l\'espérance, la charité; or la plus grande d\'entre elles est la charité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Poursuivez la charité, tout en ambitionnant les dons spirituels, mais surtout celui de prophétie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'En effet celui qui parle en langue ne parle pas pour les hommes mais pour Dieu, car personne ne l\'entend, mais c\'est en esprit qu\'il profère des mystères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'tandis que celui qui prophétise parle aux hommes pour les édifier, et les exhorter, et les consoler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Celui qui parle en langue s\'édifie lui-même, tandis que celui qui prophétise édifie l\'église.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Je veux bien que tous vous parliez en langues, mais plus encore que vous prophétisiez. Or celui qui prophétise l\'emporte sur celui qui parle en langues, à moins qu\'il n\'interprète afin que l\'église en reçoive de l\'édification.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Et maintenant, frères, si je venais auprès de vous pour vous parler en langues, en quoi vous serais-je utile, à moins que je ne vous parlasse sous forme de révélation, ou de connaissance, ou de prophétie, ou d\'instruction?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Ainsi les objets inanimés qui rendent un son, une flûte par exemple, ou une harpe, s\'ils n\'expriment une diversité de ton, comment reconnaître ce que joue la flûte, ou ce que joue la harpe?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Et en effet, si une trompette rend un son indistinct, qui est-ce qui se prépare au combat?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'De même aussi, si vous ne faites pas entendre avec la langue des paroles bien distinctes, comment reconnaîtra-t-on ce que vous dites, car vous parlerez en l\'air?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Combien ne peut-il pas y avoir de variétés d\'idiomes dans le monde? et chacun est un langage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'si donc je ne connais pas la valeur de l\'idiome, je serai un barbare aux yeux de celui qui le parle, et celui-ci sera un barbare à mes yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Ainsi, vous aussi, puisque vous êtes ambitieux des esprits, cherchez, pour l\'édification de l\'église, à en posséder le plus qu\'il est possible;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'c\'est pourquoi, que celui qui parle en langue demande la grâce d\'interpréter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Si je prie en langue, mon esprit prie, mais mon intelligence demeure stérile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Qu\'y a-t-il donc à faire? Je prierai par l\'esprit, mais je prierai aussi avec l\'intelligence; je chanterai par l\'esprit, je chanterai aussi avec l\'intelligence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Autrement, si tu rends grâces par l\'esprit, comment celui qui occupe la place du simple fidèle dira-t-il l\'Amen après ton action de grâces, puisqu\'il ne sait ce que tu dis?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'En effet, tu rends, il est vrai, d\'excellentes actions de grâces, mais l\'autre n\'est pas édifié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'J\'en rends grâces à Dieu: je parle en langues plus que vous tous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'mais j\'aimerais mieux proférer dans une assemblée d\'église cinq paroles avec mon intelligence, afin d\'instruire aussi d\'autres personnes, que dix mille paroles en langue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Frères, ne devenez pas de petits enfants pour le jugement, mais pour la malice restez en bas âge, tandis que pour le jugement il vous faut devenir des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Il est écrit dans la loi: « C\'est avec des gens d\'une autre langue et avec les lèvres d\'autres nations que Je parlerai à ce peuple, et même sous cette forme ils ne M\'écouteront pas, dit le Seigneur. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Ainsi donc les langues sont destinées à être un signe, non pour ceux qui croient, mais pour les incrédules, tandis que la prophétie s\'adresse, non aux incrédules, mais à ceux qui croient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Si donc l\'église se réunissait tout entière, et que tous parlassent en langues, les simples fidèles qui pourraient survenir ne diront-ils pas que vous êtes en délire?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Au contraire, si tous prophétisent, et qu\'il survienne quelque incrédule ou un simple fidèle, il est censuré par tous, il est jugé par tous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'les secrets de son cœur sont mis en lumière, de telle sorte que, tombant la face contre terre, il adorera Dieu, en proclamant que Dieu est réellement au milieu de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Qu\'y a-t-il donc à faire, frères? Quand vous vous assemblez, chacun a un psaume, a une instruction, a une révélation, a une langue, a une interprétation; que tout se fasse en vue de l\'édification.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Quelqu\'un parle-t-il en langue, qu\'il n\'y en ait que deux, ou tout au plus trois, qui le fassent, chacun à son tour, et qu\'un seul interprète;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'mais s\'il ne se trouve pas d\'interprète, qu\'il se taise dans l\'assemblée d\'église et qu\'il parle pour lui-même et pour Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Quant aux prophètes, que deux ou trois prennent la parole et que les autres en jugent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'mais si l\'un de ceux qui sont assis reçoit une révélation, que le premier se taise;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'car vous pouvez tous prophétiser l\'un après l\'autre, afin que tous soient instruits, et que tous soient encouragés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'et les esprits des prophètes sont soumis aux prophètes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'car Dieu ne veut pas le désordre, mais la paix. Comme dans toutes les églises des saints,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'que les femmes se taisent dans les assemblées d\'église; car il ne leur est pas permis de parler; mais qu\'elles demeurent soumises, comme le dit aussi la loi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'mais si elles veulent s\'instruire sur quelque point, qu\'elles interrogent chez elles leurs propres maris, car il est malséant pour une femme de parler dans une assemblée d\'église.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Ou bien est-ce de chez vous qu\'est sortie la parole de Dieu? Est-ce à vous seul qu\'elle est parvenue?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Si quelqu\'un s\'imagine être prophète ou être en possession des dons spirituels, qu\'il sache que ce que je vous écris est un commandement du seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'mais si quelqu\'un l\'ignore, qu\'il l\'ignore!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Ainsi donc, mes frères, recherchez avec ardeur le don de prophétie, et n\'empêchez pas qu\'on parle en langues,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'mais que tout se fasse avec décence et avec ordre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Frères, j\'attire votre attention sur l\'évangile que je vous ai annoncé, que de votre côté vous avez reçu, auquel en outre vous êtes fermement attachés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'et par lequel aussi vous êtes sauvés, si vous vous tenez aux paroles par lesquelles je vous l\'ai annoncé, à moins que ce ne soit inutilement que vous avez cru!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Je vous ai en effet transmis, avant tout, ce que de mon côté j\'avais reçu, c\'est que Christ est mort pour nos péchés, selon les écritures,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'et qu\'il a été enseveli, et qu\'il est ressuscité le troisième jour, selon les écritures,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'et qu\'il a été vu par Céphas, puis par les douze;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'ensuite il a été vu par plus de cinq cents frères à la fois, dont la plupart vivent encore maintenant, mais dont quelques-uns sont morts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'ensuite il a été vu par Jacques, puis par tous les apôtres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'enfin, après eux tous, il a été vu aussi par moi, qui suis comme l\'avorton,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'car je suis le moindre des apôtres, moi qui ne mérite pas de porter le nom d\'apôtre, parce que j\'ai persécuté l\'église de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Mais c\'est par la grâce de Dieu que je suis ce que je suis, et la grâce qu\'il m\'a faite n\'a pas été vaine, mais j\'ai travaillé plus qu\'eux tous, non pas moi, toutefois, mais la grâce de Dieu avec moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Ainsi donc, que ce soit moi, que ce soit eux, voilà ce que nous prêchons, et voilà ce que vous avez cru.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Mais, si l\'on prêche que Christ est ressuscité des morts, comment y a-t-il parmi vous des gens qui disent qu\'il n\'y a pas de résurrection des morts?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Mais, s\'il n\'y a pas de résurrection des morts, Christ non plus n\'est pas ressuscité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'or, si Christ n\'est pas ressuscité, notre prédication est donc vaine, vaine aussi est votre foi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'et il se trouve en outre que nous sommes de faux témoins à l\'égard de Dieu, car nous avons témoigné contre Dieu qu\'il a ressuscité Christ; tandis qu\'il ne l\'a pas ressuscité, si, en effet, les morts ne ressuscitent pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'car si les morts ne ressuscitent pas, Christ non plus n\'est pas ressuscité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'or si Christ n\'est pas ressuscité, votre foi est chimérique, vous êtes encore dans vos péchés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'et par conséquent aussi ceux qui sont morts en Christ ont péri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Si c\'est seulement pendant cette vie-ci, que nous espérons en Christ, nous sommes plus à plaindre que tout le reste des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Mais maintenant Christ est ressuscité des morts, comme prémices de ceux qui sont morts!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'En effet, comme la mort vient d\'un homme, c\'est d\'un homme aussi que vient la résurrection des morts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'car, de même que c\'est en Adam que meurent tous les hommes, de même aussi c\'est en Christ que tous ils reprendront vie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'mais chacun dans son propre rang: les prémices, c\'est Christ, puis ceux qui appartiennent à Christ, lors de son avènement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'ensuite viendra la fin, quand il remettra le royaume à Dieu son Père, après avoir détruit toute domination, toute autorité, et toute puissance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'car il faut qu\'il règne jusques à ce qu\'il ait mis tous les ennemis sous ses pieds;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'comme dernier ennemi est détruite la mort,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'car Il a tout placé sous ses pieds. Or quand il aura dit: « tout est soumis, » il est évident que c\'est sauf Celui qui lui a soumis toutes choses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'mais quand toutes choses lui auront été soumises, alors le Fils même sera soumis à Celui qui lui a soumis toutes choses, afin que Dieu soit tout en tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Ou bien que feront ceux qui se font baptiser pour les morts? Si les morts ne ressuscitent absolument pas, pourquoi se font-ils encore baptiser pour eux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Pourquoi nous-mêmes, de notre côté, bravons-nous le péril à toute heure?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Je meurs tous les jours; j\'en atteste, frères, le droit de m\'enorgueillir de vous, que je possède en Christ Jésus notre seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Si c\'est humainement que j\'ai combattu contre les bêtes à Éphèse, quel avantage m\'en revient-il? Si les morts ne ressuscitent point, mangeons et buvons, car demain nous mourrons.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Ne vous laissez pas séduire: « mauvaises compagnies gâtent bonnes mœurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'soyez sobres, comme il convient, et ne péchez pas; car quelques-uns de vous ne connaissent pas Dieu; c\'est à votre honte que je le dis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Mais, dira quelqu\'un: « Comment ressuscitent les morts? Et avec quelle espèce de corps viennent-ils? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Insensé! Ce que, toi, tu sèmes ne reprend pas vie s\'il ne meurt,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'et, quant à ce que tu sèmes, ce n\'est pas le corps qui renaîtra, que tu sèmes, mais un simple grain, de blé peut-être, ou de toute autre semence;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'mais c\'est Dieu qui lui donne un corps, selon qu\'il Lui a plu, et à chaque semence un corps qui lui est propre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Toute chair n\'est pas la même chair, mais autre est celle des hommes, autre la chair des quadrupèdes, autre la chair des volatiles, autre celle des poissons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'et il y a des corps célestes et des corps terrestres; mais différente est la gloire des célestes et différente celle des terrestres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'autre est l\'éclat du soleil, et autre l\'éclat de la lune, autre l\'éclat des étoiles, car une étoile diffère en éclat d\'une autre étoile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Il en est de même pour la résurrection des morts: il est semé dans la corruption, il ressuscite dans l\'incorruptibilité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'il est semé dans le déshonneur, il ressuscite dans la gloire; il est semé dans la faiblesse, il ressuscite dans la force;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'il est semé corps animal, il ressuscite corps spirituel; s\'il existe un corps animal, il en existe aussi un spirituel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'aussi est-il écrit: « Le premier Adam fut fait pour devenir une âme vivante, » le dernier Adam pour devenir un esprit vivifiant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Or ce qui est spirituel ne précède pas ce qui est animal, mais vient après;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'le premier homme tiré de la terre est terrestre, le second homme vient du ciel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'tel qu\'est le terrestre, tels aussi sont les terrestres; et tel qu\'est le céleste, tels aussi sont les célestes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'et de même que nous avons porté l\'image du terrestre, nous porterons aussi l\'image du céleste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Or je vous déclare ceci, frères, c\'est que la chair et le sang ne peuvent hériter le royaume de Dieu, et que la corruption n\'héritera pas non plus l\'incorruptibilité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Voici, je vous annonce un mystère: nous tous, nous ne mourrons pas, mais tous nous serons changés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'en un instant, en un clin d\'œil, à la dernière trompette, car on sonnera de la trompette, et les morts ressusciteront incorruptibles, et nous, nous serons changés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'car il faut que ce corps corruptible revête l\'incorruptibilité, et que ce corps mortel revête l\'immortalité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'mais, quand ce corps corruptible aura revêtu l\'incorruptibilité, et que ce corps mortel aura revêtu l\'immortalité, alors s\'accomplira la parole de l\'écriture: « La mort a été engloutie dans la victoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Où est, ô mort, ta victoire? Où est, ô mort, ton aiguillon? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Or l\'aiguillon de la mort, c\'est le péché, tandis que la puissance du péché, c\'est la loi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'mais grâces soient rendues à Dieu qui nous donne la victoire par notre seigneur Jésus-Christ!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Ainsi donc, mes frères bien-aimés, soyez fermes, inébranlables, travaillant toujours davantage à l\'œuvre du Seigneur, sachant que votre travail n\'est pas inutile dans le Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Quant à la collecte destinée aux saints, suivez, de votre côté, les prescriptions que j\'ai données aux églises de la Galatie:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Que le premier jour de la semaine chacun de vous mette à part chez lui les épargnes qu\'il lui plaît de faire, afin qu\'on n\'attende pas que je sois arrivé pour commencer les collectes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Mais quand je serai arrivé, ceux que vous aurez choisis, je les enverrai avec une lettre porter votre offrande à Jérusalem,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'et s\'il convenait que je m\'y rendisse aussi, ils feront route avec moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Je viendrai chez vous quand j\'aurai traversé la Macédoine; car je dois traverser la Macédoine,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'tandis que je séjournerai peut-être chez vous, ou même que j\'y passerai l\'hiver, afin que ce soit vous qui m\'escortiez là où je me rendrai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Je ne veux pas en effet vous visiter maintenant en passant, car j\'espère séjourner quelque temps parmi vous, si le Seigneur le permet;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'mais je séjournerai à Éphèse, jusques à la Pentecôte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'car une grande et puissante porte m\'a été ouverte, et les adversaires sont nombreux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Cependant si Timothée arrive, veillez à ce qu\'il soit sans inquiétude parmi vous, car il travaille à l\'œuvre du seigneur comme moi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'que personne donc ne le méprise, mais escortez-le pacifiquement afin qu\'il revienne vers moi, car je l\'attends.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Quant au frère Apollos, je l\'ai souvent exhorté à se rendre auprès de vous avec les frères, mais la volonté de s\'y rendre maintenant n\'y était décidément pas; cependant il partira dès qu\'il en aura l\'occasion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Veillez, soyez fermes dans la foi, comportez-vous virilement, fortifiez-vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'que toutes vos affaires se fassent avec charité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Or je vous exhorte, frères,... vous savez que la famille de Stéphanas forme les prémices de l\'Achaïe et qu\'elle s\'est elle-même consacrée au service des saints,...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'je vous exhorte, dis-je, à vous soumettre de votre côté à de tels ministres et à tous ceux qui agissent et travaillent avec eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Pour moi, je me suis réjoui de l\'arrivée de Stéphanas, de Fortounatus et d\'Achaïcus, parce qu\'ils ont suppléé à votre absence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'car ils ont tranquillisé mon esprit et le vôtre; reconnaissez donc le mérite de tels hommes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Les églises d\'Asie vous saluent. Aquilas et Prisca vous adressent de nombreuses salutations dans le seigneur, ainsi que l\'église qui se trouve dans leur maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Tous les frères vous saluent. Saluez-vous les uns les autres par un saint baiser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'La salutation de la main de moi Paul:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Si quelqu\'un n\'aime pas le seigneur, qu\'il soit anathème! Maranatha.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Que la grâce du seigneur Jésus soit avec vous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Ma charité est avec vous tous en Christ Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paul, apôtre de Christ Jésus par la volonté de Dieu, et le frère Timothée, à l\'église de Dieu qui est à Corinthe, ainsi qu\'à tous les saints qui sont dans toute l\'Achaïe:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'que la grâce et la paix vous soient données par Dieu notre Père, et par le seigneur Jésus-Christ!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Béni soit Dieu, qui est aussi le Père de notre Seigneur Jésus-Christ, le Père des compassions et le Dieu de toute consolation,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'qui nous console de toute notre tribulation, afin que nous puissions consoler ceux qui se trouvent dans toute espèce de tribulation par la consolation dont nous sommes nous-mêmes consolés par Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'car, de même que les souffrances de Christ surabondent en nous, c\'est de même par Christ que surabonde aussi notre consolation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Mais, si nous sommes exposés à la tribulation, c\'est pour votre consolation, laquelle résulte de votre patience à supporter les mêmes souffrances que nous souffrons nous-mêmes, et votre espérance demeure ferme en vous; si nous sommes consolés, c\'est pour votre consolation et votre salut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'sachant que, de même que vous participez aux souffrances, vous participez aussi à la consolation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Nous ne voulons pas en effet que vous ignoriez, frères, quant à ce qui concerne la tribulation à laquelle nous avons été exposés en Asie, que nous avons eu à supporter un fardeau entièrement au-dessus de nos forces, de telle sorte que nous avons désespéré même de conserver la vie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'ou plutôt, nous portions en nous-mêmes la sentence de mort, afin de ne point placer notre confiance en nous, mais en Dieu qui ressuscite les morts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'c\'est Lui qui nous a délivrés et qui nous délivrera d\'une mort semblable, Lui de qui nous espérons qu\'il nous en délivrera encore,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'vous-mêmes aussi coopérant pour nous par la prière, afin que la grâce, obtenue pour nous par plusieurs personnes, fournisse à plusieurs l\'occasion de rendre à votre sujet des actions de grâces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'En effet voici ce qui nous donne le droit de nous enorgueillir: Notre conscience rend témoignage que c\'est avec une sainteté et une pureté qui viennent de Dieu, et non avec une sagesse charnelle, mais selon la grâce de Dieu, que nous nous sommes conduits dans le monde, et plus encore parmi vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'car nous ne vous écrivons pas autre chose que ce que vous lisez. Mais j\'espère que vous reconnaîtrez jusques à la fin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'comme déjà vous l\'avez fait pour nous en partie, que vous avez sujet de vous enorgueillir de nous, comme nous aussi de vous, dans la journée de notre Seigneur Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Et c\'était avec cette persuasion, que je voulais me rendre premièrement auprès de vous, afin que vous eussiez à deux reprises de la joie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'et de chez vous passer en Macédoine, puis de Macédoine revenir auprès de vous, et être escorté par vous en Judée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Est-ce qu\'en ayant cette volonté, j\'ai réellement fait preuve de légèreté d\'esprit? Ou bien, les projets que je forme, est-ce que je les forme selon la chair, afin d\'avoir à ma disposition le oui, oui, et le non, non?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Mais, grâce à la fidélité de Dieu, les paroles que nous vous adressons ne sont pas oui et non;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'car le fils de Dieu, Jésus-Christ, qui a été prêché par nous au milieu de vous, par moi, dis-je, et par Silvanus et par Timothée, n\'a pas été oui et non, mais c\'est oui qui est en lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'car toutes les promesses de Dieu ont en lui leur oui; c\'est pourquoi c\'est aussi par lui que l\'Amen est prononcé par nous à la gloire de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'mais celui qui nous affermit ainsi que vous en Christ, et qui vous a oints,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'c\'est Dieu, qui nous a aussi scellés et qui a mis dans nos cœurs le gage de son esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Pour moi, j\'atteste Dieu sur mon âme, que c\'est afin de vous épargner que je ne suis pas encore revenu à Corinthe;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'non pas que nous dominions sur votre foi, mais nous devons coopérer à votre joie, car quant à la foi vous êtes fermes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'J\'ai, en effet, résolu pour moi-même, de ne pas revenir auprès de vous chargé de tristesse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'car si moi je vous attriste, quel est alors celui qui me réjouit, sinon celui-là même qui est attristé par moi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Et j\'ai écrit comme je l\'ai fait, afin de n\'avoir pas à mon arrivée à m\'attrister sur ceux dont je devais attendre de la joie, ayant en vous tous cette confiance que ma joie est celle de vous tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Car c\'est sous l\'influence d\'une grande tribulation et angoisse de cœur, que je vous ai écrit au milieu de beaucoup de larmes, non pas afin que vous fussiez attristés, mais afin que vous connussiez l\'excessive charité que j\'ai pour vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Or, si quelqu\'un a été une cause de tristesse, ce n\'est pas moi qu\'il a attristé, mais jusques à un certain point, afin de ne rien exagérer, c\'est vous tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Il suffit pour un tel homme de cette réprimande qui lui a été infligée par la majorité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'en sorte que vous devez au contraire lui faire grâce et l\'encourager, de peur qu\'il ne se laisse engloutir par l\'excès de sa tristesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'C\'est pourquoi je vous exhorte à rendre en sa faveur un décret de charité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'car j\'avais aussi écrit dans le but de connaître, en vous mettant à l\'épreuve, que vous obéissez à tous égards;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'mais à qui vous faites grâce, moi de même; car pour moi la grâce que j\'accorde, si j\'en accorde quelqu\'une, c\'est à cause de vous en présence de Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'afin que nous ne soyons pas dupés par Satan; car nous n\'ignorons pas ses desseins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Eh bien, lorsque je fus arrivé à Troas pour l\'évangile de Christ, quoiqu\'une porte m\'y fût ouverte dans le seigneur, je n\'éprouvai aucun repos d\'esprit parce que je n\'y trouvai point Tite mon frère,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'mais, ayant pris congé d\'eux, je partis pour venir en Macédoine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Or, qu\'à Dieu soient rendues grâces, Lui qui nous fait constamment triompher en Christ, et qui manifeste par nous en tous lieux le parfum de sa connaissance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'car nous sommes pour Dieu la bonne odeur de Christ, soit parmi ceux qui sont sauvés, soit parmi ceux qui sont perdus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'pour les uns un parfum qui de la mort va à la mort, pour les autres un parfum qui de la vie va à la vie. Et pour cela qui est-ce qui suffit?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Nous ne sommes pas en effet, comme le plus grand nombre, des falsificateurs de la parole de Dieu, mais c\'est vraiment avec sincérité, mais c\'est vraiment par l\'action de Dieu, que nous parlons devant Dieu en Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Recommençons-nous à nous recommander nous-mêmes? Ou bien avons-nous peut-être besoin, comme quelques personnes, de lettres de recommandation qui vous soient adressées, ou qui viennent de vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Notre lettre c\'est vous, elle est écrite dans nos cœurs, connue et lue par tous les hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'vous en qui l\'on voit avec évidence que vous êtes une lettre de Christ remise à nos soins, et écrite, non avec de l\'encre, mais avec l\'esprit du Dieu vivant, non sur des tablettes de pierre, mais sur des tablettes qui sont des cœurs de chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Or cette confiance-là, c\'est par Christ que nous l\'avons relativement à Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'non pas que par nous-mêmes nous soyons capables de penser comme de nous-mêmes, mais notre capacité vient de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'qui nous a aussi rendus capables d\'être ministres d\'une nouvelle alliance, non de la lettre mais de l\'esprit; car la lettre tue, tandis que l\'esprit vivifie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Or, si le ministère de la mort, gravé avec des lettres sur des pierres, a été accompagné d\'une gloire telle que les fils d\'Israël ne pouvaient fixer leurs regards sur le visage de Moïse, à cause de la gloire de son visage, toute périssable qu\'elle était,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'le ministère de l\'esprit sera entouré de bien plus de gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Car, si le ministère de la condamnation a été glorieux, le ministère de la justice l\'emporte bien davantage en gloire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'car même ce qui a été glorieux est, à cet égard, privé de gloire, à cause de la gloire supérieure;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'en effet, si ce qui est périssable est accompagné de gloire, ce qui est permanent est bien plus glorieux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Ayant donc un tel espoir, nous sommes animés d\'une grande assurance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'et nous ne faisons pas comme Moïse qui plaçait un voile sur son visage, pour que les fils d\'Israël ne fixassent pas leurs regards sur la disparition de ce qui était périssable;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'mais leurs esprits ont été endurcis, car jusques au jour d\'aujourd\'hui le même voile recouvre la lecture de l\'ancienne alliance, sans qu\'il soit dévoilé que c\'est par Christ qu\'elle est abolie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'mais jusques à aujourd\'hui, lorsqu\'on lit Moïse, un voile reste étendu sur leur cœur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'mais lorsqu\'il s\'est tourné vers le seigneur ce voile est enlevé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'or le seigneur c\'est l\'esprit, et là où est l\'esprit du seigneur, il y a liberté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Or nous tous qui, le visage découvert, contemplons dans un miroir la gloire du seigneur, nous sommes transformés en la même image, de gloire en gloire, comme cela doit se faire par le seigneur de l\'esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'C\'est pourquoi, revêtus de ce ministère selon la miséricorde qui nous a été faite, nous ne perdons point courage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'mais nous avons rejeté les secrètes manœuvres qui font rougir, ne nous conduisant point avec astuce, et ne falsifiant pas non plus la parole de Dieu, mais nous rendant nous-mêmes recommandables, par la manifestation de la vérité, à toute conscience humaine devant Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Or si notre évangile est encore voilé, c\'est parmi ceux qui périssent qu\'il est voilé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'parmi lesquels le dieu de ce siècle a aveuglé les esprits des incrédules, afin que pour, eux ne brillât point la lumière de l\'évangile de la gloire de Christ, qui est l\'image de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Car ce n\'est pas nous-mêmes, mais c\'est Christ Jésus que nous proclamons comme seigneur, et nous-mêmes au contraire comme vos esclaves à cause de Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'parce que Dieu qui a dit: « La lumière brillera du sein des ténèbres, » est Celui qui l\'a fait briller dans nos cœurs pour que nous enseignions à reconnaître la gloire de Dieu sur le visage de Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Mais nous portons ce trésor dans des vases de terre, afin que la grandeur de la puissance soit attribuée à Dieu, et ne paraisse pas venir de nous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'nous, qui de toutes manières sommes pressés, mais non pas réduits à l\'extrémité; embarrassés, mais non pas désespérés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'persécutés, mais non pas délaissés; renversés, mais non pas tués;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'portant constamment en notre corps la mort de Jésus, afin que la vie de Jésus soit aussi manifestée dans notre corps;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'car nous qui vivons nous sommes toujours livrés à la mort à cause de Jésus, afin que la vie de Jésus soit aussi manifestée dans notre chair mortelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'en sorte que c\'est la mort qui agit en nous, tandis que c\'est la vie qui agit en vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Mais ayant le même esprit de foi, selon qu\'il est écrit: « J\'ai cru, c\'est pourquoi j\'ai parlé, » nous aussi nous croyons; et c\'est aussi pour cela que nous parlons,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'sachant que Celui qui a ressuscité Jésus nous ressuscitera aussi avec Jésus et nous fera comparaître avec vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'car tout cela arrive à cause de vous, afin que la grâce, en se multipliant, fasse abonder, par la bouche du plus grand nombre, pour la gloire de Dieu, les actions de grâces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'C\'est pourquoi nous ne perdons point courage, mais, lors même que notre homme extérieur dépérit, notre homme intérieur au contraire se renouvelle de jour en jour;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'car la légère tribulation d\'un moment nous procure avec abondance et surabondamment un poids éternel de gloire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'si du moins nous n\'arrêtons pas nos regards sur les choses visibles, mais sur les invisibles; car les choses visibles sont passagères, tandis que les invisibles sont éternelles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Nous savons en effet que, si la tente qui forme notre demeure terrestre vient à être détruite, nous possédons dans les cieux un édifice qui procède de Dieu, une demeure éternelle qui n\'a pas été construite de main d\'homme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'car nous gémissons déjà dans celle-ci, désireux que nous sommes de revêtir le domicile qui nous vient du ciel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'si toutefois nous sommes effectivement trouvés vêtus et non pas nus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'car, dis-je, nous qui sommes dans cette tente, nous gémissons déjà dans l\'angoisse, parce que nous ne voulons pas être dépouillés, mais être revêtus, afin que ce qui est mortel soit englouti par la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Or, celui qui nous a préparés pour cela même, c\'est Dieu, qui nous en a donné l\'Esprit pour gage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Étant donc toujours pleins de confiance, et sachant qu\'en demeurant dans le corps nous habitons loin du seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'car c\'est par la foi que nous marchons, non par la vue...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'nous sommes, dis-je, pleins de confiance, et nous préférons émigrer du corps et demeurer auprès du seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'C\'est pourquoi nous nous appliquons aussi, soit que nous demeurions, soit que nous émigrions, à lui être agréables,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'car il faut que tous nous apparaissions tels que nous sommes devant le tribunal de Christ, afin que chacun reçoive la rétribution de ce qu\'il a fait en son corps, selon le bien ou le mal qu\'il a commis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Sachant donc quelle est la crainte qu\'on doit avoir du seigneur, nous cherchons à convaincre les hommes, mais aux yeux de Dieu nous apparaissons tels que nous sommes; j\'espère toutefois que, tels aussi, nous apparaissons dans vos consciences.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Nous ne nous recommandons pas derechef à vous, mais nous voulons nous donner une occasion de nous enorgueillir de vous, afin que vous vous en serviez contre ceux qui s\'enorgueillissent des apparences et non du cœur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'En effet, si nous sommes hors de sens, c\'est pour Dieu; si nous sommes de bon sens, c\'est pour vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'car l\'amour de Christ nous subjugue, depuis que nous avons compris que, si un seul est mort pour tous, tous donc sont morts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'et qu\'il est mort pour tous, afin que les vivants ne vivent plus pour eux-mêmes, mais pour celui qui est mort et qui est ressuscité pour eux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'en sorte que, quant à nous, désormais nous ne connaissons personne selon la chair; quoique nous ayons connu Christ selon la chair, maintenant nous ne le connaissons plus ainsi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Ainsi donc, si quelqu\'un est en Christ, c\'est une nouvelle création; les choses anciennes sont passées, voici, il s\'en est fait de nouvelles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Or tout cela vient de Dieu qui nous a réconciliés avec Lui-même par Christ, et qui nous a donné le ministère de la réconciliation;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'parce qu\'en effet Dieu réconciliait en Christ le monde avec Lui-même, en ne leur imputant point leurs fautes, et Il a mis en nous la parole de la réconciliation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'C\'est donc pour Christ que nous faisons fonction d\'ambassadeurs; c\'est comme si Dieu exhortait par notre moyen; nous vous en conjurons pour Christ: Soyez réconciliés avec Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'celui qui ne connut pas le péché, c\'est pour nous qu\'il l\'a traité comme un pécheur, afin qu\'en lui nous, possédions la justice de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Mais, puisque nous sommes ses coopérateurs, nous vous exhortons aussi à ne pas recevoir inutilement la grâce de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, '(car il est dit: « Au temps favorable Je t\'ai exaucé, et au jour du salut Je t\'ai secouru; » voici, c\'est maintenant le temps particulièrement favorable; voici, c\'est maintenant le jour du salut),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'nous qui ne donnons prise sur aucun point, afin que le ministère ne soit pas critiqué,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'mais qui nous rendons recommandables à tous égards, comme il convient à des serviteurs de Dieu, par beaucoup de patience au milieu des tribulations, au milieu des calamités, au milieu des détresses,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'au milieu des coups, au milieu des prisons, au milieu des troubles, au milieu des fatigues, au milieu des veilles, au milieu des jeûnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'par la pureté, par la connaissance, par la longanimité, par la bienveillance, par un esprit saint, par une charité sincère,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'par la parole de la vérité, par la puissance de Dieu; employant les armes offensives et défensives de la justice,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'tirant parti de la gloire et de l\'infamie, de la mauvaise et de la bonne renommée; tenus pour fourbes, quoiqu\'étant véridiques;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'tenus pour inconnus, quoiqu\'étant bien connus; tenus pour mourants, et voici, nous vivons; tenus pour châtiés, quoique n\'étant point mis à mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'tenus pour désolés, mais étant toujours joyeux; tenus pour pauvres, mais rendant riches bien des hommes; tenus, pour ne rien avoir, quoique possédant toutes choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Notre bouche s\'est ouverte pour vous, Corinthiens, notre cœur s\'est élargi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'vous n\'êtes point à l\'étroit au dedans de nous, tandis que vous êtes à l\'étroit dans vos propres entrailles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'mais rendez-nous la pareille (je vous parle comme à mes enfants) en vous élargissant aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Ne portez pas, en vous unissant aux infidèles, un joug étranger; car quel rapport y a-t-il entre la justice et l\'impiété, ou quelle communauté entre la lumière et les ténèbres?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Mais encore quelle harmonie y a-t-il entre Christ et Béliar, ou quelle relation entre un fidèle et un infidèle?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Mais enfin quel accord y a-t-il entre le sanctuaire de Dieu et les idoles? Car c\'est nous qui sommes le sanctuaire du Dieu vivant, selon que Dieu a dit: « J\'habiterai et Je marcherai parmi eux, et Je serai leur Dieu, et eux seront Mon peuple;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'c\'est pourquoi sortez du milieu d\'eux et tenez-vous à part, dit le Seigneur, et ne touchez pas à ce qui est impur, et c\'est Moi qui vous accueillerai,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'et Je serai pour vous un père, et vous, vous serez pour Moi des fils et des filles, dit le Seigneur tout-puissant. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Ayant donc de telles promesses, bien-aimés, purifions-nous nous-mêmes de toute souillure de la chair et de l\'esprit, en achevant notre sanctification dans la crainte de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Faites-nous une place: nous n\'avons fait tort à personne, nous n\'avons ruiné personne, nous n\'avons dupé personne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'je ne parle pas dans un esprit de reproche, car je vous ai déjà dit que vous êtes dans nos cœurs pour mourir ou pour vivre avec nous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'j\'ai une grande confiance en vous, j\'ai grand sujet de m\'enorgueillir de vous; je suis rempli de consolation, je suis plus que comblé de joie au milieu de toute notre tribulation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'En effet, lorsque nous fûmes arrivés en Macédoine, notre chair n\'eut aucun repos, mais nous étions pressés de toutes parts: au dehors des combats, au dedans des terreurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'mais Celui qui console les humbles, Dieu nous a consolés par l\'arrivée de Tite,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'et non seulement par son arrivée, mais encore par la consolation qu\'il ressentait lui-même à votre sujet, en nous racontant votre vive impatience, votre chagrin, votre zèle pour moi, en sorte que j\'en ai éprouvé encore plus de joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Car, lors même que je vous ai attristés par ma lettre, je ne le regrette point; mais quoique j\'aie eu du regret, (je vois que cette lettre vous a attristés, bien que ce ne fût qu\'un instant),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'maintenant je me réjouis, non de ce que vous avez été attristés, mais de ce que vous avez été attristés de manière à vous repentir; en effet vous avez été attristés selon Dieu, afin que sur aucun point vous n\'éprouviez quelque dommage de notre part;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'car la tristesse selon Dieu produit une repentance qui conduit à un salut qu\'on ne regrette pas, tandis que la tristesse du monde produit la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Car, voici, le fait même d\'avoir été attristés selon Dieu vous a inspiré, non seulement de l\'empressement, mais une justification, mais de l\'indignation, mais de la crainte, mais une vive impatience, mais du zèle, mais une vengeance; à tous égards vous avez montré que vous étiez vous-mêmes innocents dans l\'affaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Aussi, quoique je vous aie écrit, ce n\'était pas à cause de l\'offenseur, et pas davantage à cause de l\'offensé, mais c\'était pour que votre empressement pour nous fût manifesté parmi vous devant Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'C\'est pourquoi nous avons été consolés. Mais, outre notre consolation, nous avons été encore beaucoup plus réjouis par la joie de Tite, dont l\'esprit a été tranquillisé par vous tous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'car, si je me suis un peu enorgueilli devant lui à propos de vous, je n\'ai pas eu à en rougir; mais, de même que nous vous avons parlé de tout avec vérité, de même aussi l\'orgueil que nous avons témoigné à votre sujet devant Tite est devenu une vérité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'et son cœur redouble d\'affection pour vous, quand il se rappelle votre universelle obéissance, car c\'est avec crainte et tremblement que vous l\'avez reçu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Je me réjouis d\'être à tous égards rassuré sur vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Nous vous informons cependant, frères, de la grâce de Dieu qui s\'est manifestée parmi les églises de Macédoine,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'en sorte que, au milieu des nombreuses épreuves de la tribulation, l\'excès de leur joie et leur profonde pauvreté ont abondé dans la richesse de leur libéralité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'car c\'est selon leur pouvoir, je l\'atteste, et même au-dessus de leur pouvoir, que d\'un mouvement spontané,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'nous priant avec de grandes instances de leur accorder la faveur de prendre part au secours destiné aux saints,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'et dépassant nos espérances, ils se sont donnés eux-mêmes tout d\'abord au seigneur et à nous, par la volonté de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'en sorte que nous avons invité Tite à achever aussi parmi vous, comme il avait commencé, cette œuvre de bienfaisance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'afin que, de même que vous l\'emportez à tous égards en ce qui concerne la foi, et le discours, et la connaissance, et l\'empressement à tout faire, et la charité que nous vous avons inspirée, vous l\'emportiez aussi dans cette œuvre de bienfaisance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Ce que j\'en dis n\'est pas pour vous donner un ordre, mais pour éprouver, par l\'empressement des autres, ce que vaut à son tour votre charité; —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'car vous connaissez la grâce que vous a faite notre seigneur Jésus, et comment c\'est à cause de vous qu\'il s\'est appauvri lorsqu\'il était riche, afin que vous-mêmes par sa pauvreté vous devinssiez riches; —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'et c\'est une opinion que je vous donne sur ce sujet, car cela vous est utile, à vous qui, dès l\'an dernier, avez les premiers commencé non seulement à agir, mais encore à vouloir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Eh bien, maintenant, achevez aussi d\'agir, afin que, comme il y a eu de votre part bonne volonté, il y ait aussi achèvement selon vos moyens;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'car, si la bonne volonté existe, elle plaît selon ce qu\'elle a, et non selon ce qu\'elle n\'a pas, à sa disposition;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'car il ne s\'agit point, pour soulager les autres, de vous écraser vous-mêmes, mais d\'établir l\'égalité; dans les circonstances actuelles votre superflu doit suppléer à leur dénuement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'afin qu\'à son tour leur superflu supplée à votre dénuement, pour que l\'égalité s\'établisse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'selon qu\'il est écrit: « Qui recueillait beaucoup n\'avait pas plus, et qui recueillait peu n\'avait pas moins. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Mais qu\'à Dieu soient rendus grâces, Lui qui met dans le cœur de Tite le même empressement pour vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'car s\'il a accédé à mon invitation, c\'est pourtant à cause de l\'empressement plus grand encore dont il est animé, qu\'il va de son plein gré auprès de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Mais avec lui nous envoyons le frère, dont l\'éloge, en ce qui concerne l\'Évangile, est répandu dans toutes les églises,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'et qui, en outre, a été choisi par les églises comme notre compagnon de voyage dans cette œuvre de bienfaisance, à laquelle nous donnons nos soins pour la gloire du seigneur et pour montrer notre bonne volonté,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'désirant éviter que personne ne nous critique à propos de cette grosse somme que nous sommes chargés de recueillir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'car nous recherchons ce qui est bien, non seulement devant le Seigneur, mais encore devant les hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Or avec eux nous vous envoyons notre frère, dont nous avons souvent reconnu l\'empressement dans plusieurs occasions, mais que nous trouvons maintenant encore beaucoup plus empressé. Cependant la grande confiance que j\'ai en vous me rassure,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'soit qu\'il s\'agisse de Tite, lui qui est mon compagnon et mon coopérateur auprès de vous, soit qu\'il s\'agisse de nos frères, eux qui sont envoyés des églises et la gloire de Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'donnez-leur donc, à la face des églises, la preuve de votre charité, et du motif que nous avons eu de nous enorgueillir de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'En effet, quant à ce qui concerne le secours destiné aux saints, il est superflu que je vous en écrive;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'car je connais votre bonne volonté qui me donne l\'occasion de m\'enorgueillir pour vous auprès des Macédoniens, de ce que l\'Achaïe est prête depuis l\'an dernier, et de ce que votre zèle a stimulé le plus grand nombre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'mais j\'ai envoyé les frères, afin que notre droit de nous enorgueillir de vous ne soit pas, sur ce point, mis à néant, et pour que, comme je l\'ai dit, vous soyez prêts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'de peur que des Macédoniens ne viennent avec moi et ne trouvent que vous n\'êtes pas prêts, et que nous-mêmes (pour ne pas dire vous), nous n\'ayons à rougir dans cette affaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'J\'ai donc jugé nécessaire d\'inviter les frères à me précéder auprès de vous, et à prendre au préalable, en ce qui concerne le bienfait promis d\'avance de votre part, des mesures telles qu\'on le trouve disponible comme un témoignage de bienfaisance et non de cupidité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Or c\'est ici que celui qui sème chichement moissonnera aussi chichement, et que celui qui sème largement moissonnera aussi largement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Que chacun donne selon ce qu\'il a d\'avance résolu dans son cœur, non avec tristesse ou par contrainte, car Dieu aime un donateur joyeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Or Dieu est puissant pour faire abonder sur vous toute espèce de grâces, afin que, possédant toujours en toutes choses une entière suffisance, vous subveniez abondamment à toute bonne œuvre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'selon qu\'il est écrit: « Il a répandu, il a donné aux pauvres, sa justice demeure pour l\'éternité. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Or Celui qui fournit au semeur de la semence et du pain pour sa nourriture vous fournira et vous multipliera la semence, et Il fera croître les produits de votre justice,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'en sorte que vous serez riches à tous égards pour toutes les libéralités qui sont de nature à faire offrir, par notre moyen, des actions de grâces à Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'car le secours de cette contribution non seulement subvient aux besoins des saints, mais encore il surabonde par de nombreuses actions de grâces adressées à Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Et c\'est pour ce méritoire secours qu\'ils glorifient Dieu, à cause de votre obéissance dans la profession de l\'évangile de Christ, et de la libéralité que vous inspire votre attachement pour eux et pour tous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'tandis que, de leur côté, dans les prières qu\'ils font pour vous, ils soupirent après vous à cause de la grâce de Dieu qui déborde sur vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Grâces soient rendues à Dieu pour Son inénarrable bienfait!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Or c\'est moi-même Paul, qui vous exhorte, au nom de la mansuétude et de la clémence de Christ, moi qui parmi vous me montre sous d\'humbles apparences, il est vrai, tandis qu\'absent je prends envers vous un ton d\'assurance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'mais je vous prie que je n\'aie pas, en étant présent, à prendre ce même ton avec la hardiesse dont je me propose d\'user contre certaines gens qui nous regardent comme marchant selon la chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'En effet, si nous marchons dans la chair, nous ne combattons pas selon la chair;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'car les armes de notre guerre ne sont pas charnelles, mais puissantes, grâces à Dieu, pour la destruction des ouvrages ennemis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'en sorte que nous détruisons toute conception et tout rempart qui s\'élève contre la connaissance de Dieu, et que nous rendons toute pensée prisonnière de l\'obéissance de Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'et que nous sommes prêts à punir toute espèce de désobéissance, quand votre obéissance sera devenue parfaite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Est-ce aux apparences que vous vous arrêtez? Si quelqu\'un croit posséder l\'assurance d\'appartenir à Christ, qu\'il réfléchisse aussi en lui-même que, de même qu\'il appartient à Christ, nous aussi, nous lui appartenons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'car, quand même je me serais enorgueilli, un peu plus qu\'il ne faut, de l\'autorité que le Seigneur nous a donnée pour votre édification et non pour votre destruction, je n\'aurai point à en rougir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'afin que je ne paraisse pas chercher à vous effrayer par mes lettres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'On dit en effet: « ses lettres sont, il est vrai, sévères et fortes, mais, quand il est présent, sa personne est faible et sa parole méprisée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Que celui qui parle delà sorte réfléchisse que, tels nous sommes en paroles par nos lettres lorsque nous sommes absents, tels aussi nous sommes par le fait quand nous sommes présents;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'car je n\'ose point nous confondre ou nous comparer avec quelques-uns de ceux qui se recommandent eux-mêmes; mais, en se mesurant eux-mêmes à eux-mêmes, et en se comparant eux-mêmes à eux-mêmes, ils se montrent sans intelligence;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'mais, pour nous, nous ne nous enorgueillirons point hors de toute mesure, ce sera au contraire selon la mesure des limites au dedans desquelles Dieu nous a assigné notre lot, de manière à venir aussi jusques à vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Est-ce qu\'en effet, comme si nous ne venions pas à vous, nous dépassons nos limites? Mais c\'est bien aussi jusques à vous que nous sommes parvenus en prêchant l\'évangile de Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'loin de nous enorgueillir, hors de toute mesure, de travaux étrangers, mais ayant l\'espérance, notre foi allant croissant, de grandir de plus en plus à vos yeux, sans sortir de nos limites,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'en portant la bonne nouvelle plus loin que vous, non en nous enorgueillissant, dans des limites étrangères, d\'un travail déjà fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Du reste, que celui qui s\'enorgueillit s\'enorgueillisse dans le Seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'car ce n\'est pas celui qui se recommande lui-même dont on reconnaît le mérite, mais celui que recommande le Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Puissiez-vous tolérer en moi un peu de déraison; mais, au fait, vous me tolérez,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'car j\'ai pour vous une jalousie semblable à celle de Dieu; je vous ai en effet fiancés à un seul mari, qui est Christ, pour lui présenter une vierge chaste;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'mais je crains que, de même que le serpent trompa Ève par son astuce, vos pensées ne soient corrompues et détournées de la fidélité et de la chasteté qui sont dues à Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'car si le premier venu prêche un autre Jésus que celui que nous avons prêché, ou si vous recevez un esprit différent de celui que vous avez reçu, ou un Évangile différent de celui que vous avez accepté, vous vous y prêtez admirablement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Or j\'estime que je n\'ai été inférieur en rien aux, apôtres de la plus haute volée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'mais, quoique je sois étranger à l\'éloquence, je ne le suis pas à la connaissance, au contraire nous l\'avons mise en évidence parmi vous en tous points sur toutes choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Ou bien ai-je commis un péché, m\'abaissant moi-même afin que vous fussiez élevés, parce que je vous ai gratuitement annoncé l\'évangile de Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'J\'ai dépouillé d\'autres églises en recevant d\'elles un salaire pour vous servir, et pendant ma présence parmi vous, quoique dans le dénuement, je n\'ai été à charge à personne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'car ce sont les frères venus de Macédoine qui ont subvenu à mon dénuement, et sous tous les rapports je me suis gardé et je me garderai de vous être à charge.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Une vérité dont Christ m\'assure, c\'est que ce motif de m\'enorgueillir ne me sera point interdit dans les contrées de l\'Achaïe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Pourquoi? Est-ce que je ne vous aime point? Dieu le sait!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Mais ce que je fais, je continuerai de le faire, pour ôter ce prétexte à ceux qui veulent un prétexte, afin que ce soit sur ce dont ils s\'enorgueillissent qu\'on les juge, comme nous-mêmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Ces gens-là, en effet, sont de faux apôtres, des ouvriers mensongers, déguisés en apôtres de Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'et cela n\'a rien d\'étonnant; car Satan lui-même se déguise en ange de lumière;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'il n\'y a donc rien d\'étrange à ce que ses ministres aussi se déguisent en ministres de justice, eux dont la fin sera conforme à leurs œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Je le répète: que personne ne s\'imagine que j\'ai perdu la raison, ou bien, s\'il en est autrement, acceptez-moi néanmoins comme dépourvu de raison, afin que moi aussi je m\'enorgueillisse un peu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Ce que je dis, quand je parle de m\'enorgueillir, je ne le dis pas selon le seigneur, mais comme dans un état de déraison:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'puisque plusieurs s\'enorgueillissent selon la chair, moi aussi je m\'enorgueillirai;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'car vous tolérez volontiers ceux qui manquent de raison, vous qui êtes raisonnables!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'En effet, si quelqu\'un vous asservit, si quelqu\'un vous dévore, si quelqu\'un s\'empare de vous, si quelqu\'un vous domine, si quelqu\'un vous frappe au visage, vous le tolérez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Je dis à notre honte que, pour nous, nous avons été faibles; toutefois tout ce que quelqu\'un ose (je parle avec déraison) moi je l\'ose aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Ils sont Hébreux? Moi aussi. Ils sont Israélites? Moi aussi. Ils sont la postérité d\'Abraham? Moi aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Ils sont ministres de Christ (je parle en insensé)? Moi je le suis plus encore, par des travaux plus grands, par des emprisonnements plus nombreux, par des souffrances excessives, par de fréquents dangers de mort,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, '(j\'ai reçu cinq fois des Juifs quarante coups, moins un;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'j\'ai été trois fois battu de verges; une fois j\'ai été lapidé; trois fois j\'ai fait naufrage; j\'ai passé un jour et une nuit dans l\'abîme),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'par de fréquents voyages, par des périls sur les fleuves, par des périls venus des brigands, par des périls venus de ma nation, par des périls venus des païens, par des périls dans les villes, par des périls dans les déserts, par des périls en mer, par des périls au milieu des faux frères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'par le travail et la fatigue, par de fréquentes veilles, par la faim et la soif, par de fréquents jeûnes, par le froid et la nudité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Sans parler du reste, ma préoccupation journalière c\'est le soin qu\'il faut prendre de toutes les églises:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Qui est faible, que je ne sois faible? Qui succombe à la tentation, que ce ne soit moi qui me consume?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'S\'il faut s\'enorgueillir, je m\'enorgueillirai de ce qui fait ma faiblesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Dieu, qui est aussi le Père du seigneur Jésus, sait, Lui qui est béni à jamais, que je ne mens point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'A Damas, le gouverneur pour le roi Arétas faisait garder la ville des Damascéniens, afin de se saisir de moi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'et je fus dévalé par une fenêtre dans une manne le long du mur, et j\'échappai à ses mains.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Faut-il s\'enorgueillir? Il est vrai que cela n\'est pas utile, néanmoins j\'en viendrai même aux visions et aux révélations du Seigneur:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'je connais un homme en Christ qui, il y a quatorze ans, que ce fût avec son corps, je l\'ignore, que ce fût sans son corps, je l\'ignore, Dieu le sait, un homme, dis-je, qui fut enlevé jusqu\'au troisième ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'Et je sais que ce même homme, que ce fût avec son corps, que ce fût sans son corps, Dieu le sait,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'fut enlevé dans le paradis, et entendit d\'ineffables paroles qu\'il n\'est pas permis à un homme de proférer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'C\'est pour cet homme-là que je m\'enorgueillirai, mais pour moi-même je ne m\'enorgueillirai point, si ce n\'est de mes faiblesses,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, '(ce n\'est pas que, si je voulais m\'enorgueillir, j\'eusse perdu la raison, car je dirais la vérité, mais je m\'en abstiens, afin que personne ne m\'attribue plus que ce qu\'il me voit faire ou m\'entend dire)');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'et si ce n\'est de l\'excès de mes révélations. C\'est pourquoi, afin que je ne m\'exalte point, il m\'a été donné, comme une épreuve pour la chair, un ange de Satan, afin qu\'il me soufflette pour que je ne m\'exalte point;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'trois fois j\'ai prié à son sujet le seigneur, afin qu\'il s\'éloignât de moi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'et il m\'a dit: « Ma grâce te suffit, car la puissance déploie tous ses effets dans la faiblesse. » Je m\'enorgueillirai donc beaucoup plus volontiers de mes faiblesses, afin que la puissance de Christ repose sur moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'C\'est pourquoi je prends plaisir aux faiblesses, aux injures, aux calamités, aux persécutions et aux détresses, à cause de Christ; car quand je suis faible, alors je suis puissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Je me suis laissé aller à déraisonner; c\'est vous qui m\'y avez contraint, car quant à moi j\'aurais dû être recommandé par vous; je n\'ai en effet été inférieur en quoi que ce soit aux apôtres de la plus haute volée, quoique je ne sois rien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Les marques de l\'apôtre se sont fait reconnaître parmi vous avec une pleine persévérance par des signes et des prodiges et des miracles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Car en quoi avez-vous été lésés par comparaison avec les autres églises, sauf en ce que moi-même je ne vous ai pas été à charge? Pardonnez-moi cette injustice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Voici, pour la troisième fois je suis prêt à me rendre auprès de vous, et je ne vous serai pas à charge, car ce n\'est pas ce qui est à vous que je recherche, mais c\'est vous; ce ne sont pas en effet les enfants qui doivent thésauriser pour leurs parents, mais les parents pour leurs enfants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Quant à moi, je dépenserai très volontiers, et je me dépenserai moi-même entièrement pour vos âmes, dussé-je, en vous aimant toujours plus, être toujours moins aimé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Eh bien! soit; je ne vous ai pas été personnellement à charge, mais, étant plein d\'astuce, je me suis emparé de vous par ruse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Est-ce qu\'aucun de ceux que je vous ai envoyés m\'a servi à vous duper?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'J\'ai encouragé Tite, et avec lui j\'ai envoyé le frère; est-ce que Tite vous a dupés? N\'avons-nous pas marché dans le même esprit et suivi les mêmes traces?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Vous vous imaginez depuis longtemps que nous nous justifions devant vous; c\'est devant Dieu que nous parlons en Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'mais tout ce que nous disons, mes bien-aimés, c\'est pour votre édification; car je crains qu\'à mon arrivée je ne vous trouve pas tels que je désirerais, et que moi-même je ne sois pas trouvé par vous tel que vous désireriez; je crains de trouver des querelles, de la jalousie, des emportements, des intrigues, des calomnies, des délations, des vanteries, des révoltes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Est-ce qu\'à mon arrivée mon Dieu m\'humiliera de nouveau par rapport à vous, et aurai-je à pleurer sur beaucoup de ceux qui ont ci-devant péché, et qui ne se seront pas repentis de l\'impureté, de l\'impudicité, du débordement auxquels ils se sont livrés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'C\'est la troisième fois que je viens chez vous; sur la déclaration de deux ou de trois témoins toute affaire sera décidée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'J\'ai prévenu et je préviens, comme je l\'ai fait lorsque j\'étais présent pour la seconde fois, et maintenant que je suis absent, ceux qui ont ci-devant péché et tous les autres, que si j\'arrive de nouveau je n\'userai d\'aucun ménagement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'puisque vous cherchez à avoir la preuve que c\'est Christ qui parle en moi, lequel n\'est pas faible relativement à vous, mais il est puissant parmi vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'En effet, il a été crucifié à cause de sa faiblesse, mais il vit par la puissance de Dieu; eh bien, nous-mêmes aussi nous sommes faibles en lui, mais nous vivrons avec lui par la puissance de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Mettez-vous vous-mêmes à l\'épreuve pour voir si vous êtes dans la foi; examinez-vous vous-mêmes. Ou bien est-ce que vous ne reconnaissez pas que Jésus-Christ est en vous? A moins peut-être que vous ne soyez réprouvés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Mais j\'espère que vous connaîtrez que nous, nous ne sommes pas réprouvés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Cependant nous demandons à Dieu que vous ne fassiez rien de mal, non pas que notre propre mérite soit mis en évidence, mais que vous pratiquiez ce qui est bien, et que nous-mêmes nous soyons en quelque sorte tenus pour réprouvés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'car nous ne pouvons rien contre la vérité, mais pour la vérité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'nous nous réjouissons en effet quand nous, nous sommes faibles, et quand vous-mêmes, vous êtes forts; et ce que nous demandons dans nos prières, c\'est votre perfectionnement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'C\'est pourquoi je vous écris ces choses pendant que je suis absent, afin que, quand je serai présent, je n\'aie pas à agir avec rigueur selon l\'autorité que le Seigneur m\'a donnée pour édifier et non pour détruire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Du reste, frères, réjouissez-vous, perfectionnez-vous, consolez-vous, soyez animés des mêmes sentiments, vivez en paix, et le Dieu de la charité et de la paix sera avec vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Saluez-vous les uns les autres par un saint baiser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Tous les saints vous saluent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, 'Que la grâce du seigneur Jésus, et la charité de Dieu, et la communication du saint esprit soient avec vous tous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paul, apôtre, non par le fait des hommes, ou par l\'entremise d\'un homme, mais par Jésus-Christ et Dieu le Père qui l\'a ressuscité des morts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'et tous les frères qui sont avec moi, aux églises de Galatie:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Que la grâce et la paix vous soient données par Dieu le Père et par notre seigneur Jésus-Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'qui s\'est lui-même donné pour nos péchés, afin de nous arracher du présent siècle mauvais, selon la volonté de notre Dieu et Père,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'auquel gloire soit rendue pour les siècles des siècles. Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Je m\'étonne que vous désertiez si vite Celui qui vous a appelés par la grâce de Christ, pour passer à un autre évangile;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'ce qui ne vient d\'autre chose que de ce qu\'il y a quelques personnes qui vous troublent, et qui veulent renverser l\'évangile de Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Mais, à supposer que nous-mêmes, ou un ange venu du ciel vous prêchât un évangile différent de celui que nous vous avons prêché, qu\'il soit anathème!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Comme nous vous l\'avons déjà dit, et comme je vous le redis maintenant: si quelqu\'un vous prêche un évangile différent de celui que vous avez reçu, qu\'il soit anathème!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Eh bien, maintenant, est-ce la faveur des hommes que j\'ambitionne, ou celle de Dieu? Ou bien, est-ce que je cherche à plaire aux hommes? Si je plaisais encore aux hommes, je ne serais pas un esclave de Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'car je vous fais savoir, frères, que l\'évangile qui a été prêché par moi n\'a rien d\'humain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'car, moi non plus, ce n\'est pas par un homme que je l\'ai reçu, ou que j\'ai été instruit, mais par une révélation de Jésus-Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Vous avez en effet ouï parler de la conduite que j\'ai tenue jadis dans le judaïsme, comment je poursuivais à outrance l\'église de Dieu, et comment je la dévastais,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'et comment j\'étais plus avancé dans le judaïsme que plusieurs de mes compatriotes de mon âge, étant animé d\'un beaucoup plus grand zèle pour les traditions de mes pères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Mais, quand Celui qui m\'a mis à part dès le sein de ma mère, et qui m\'a appelé par Sa grâce,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'jugea bon de me révéler intérieurement Son fils, afin que j\'en annonçasse la bonne nouvelle parmi les Gentils, aussitôt, sans prendre conseil de la chair et du sang,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'sans me rendre non plus à Jérusalem auprès des apôtres qui m\'ont précédé, je me rendis au contraire en Arabie, puis je revins à Damas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Ensuite, au bout de trois ans, je retournai à Jérusalem pour faire la connaissance de Céphas, et je restai quinze jours auprès de lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'mais je ne vis aucun autre des apôtres, sauf Jacques le frère du Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Ce que je vous écris là, voici, devant Dieu, je ne mens point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Ensuite je me rendis en Syrie et en Cilicie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Cependant j\'étais inconnu de visage aux églises de la Judée qui sont en Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'seulement elles entendaient dire: « Notre ancien persécuteur prêche maintenant la bonne nouvelle de la foi que jadis il dévastait; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'et elles glorifiaient Dieu à mon sujet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Ensuite, après quatorze ans d\'intervalle, je montai de nouveau à Jérusalem avec Barnabas, en prenant aussi Tite avec moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Mais j\'y montai par suite d\'une révélation, et je leur exposai l\'évangile que je prêche parmi les Gentils, mais je m\'entretins séparément avec les plus considérés, afin de ne pas courir ou de n\'avoir pas couru inutilement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Mais Tite qui m\'accompagnait, et qui était Grec, ne put pas même être contraint de se faire circoncire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'et ce fut à cause des faux frères intrus qui s\'étaient furtivement introduits pour espionner la liberté que nous possédons en Christ Jésus, afin de nous asservir complètement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'auxquels nous n\'accordâmes, pas même un instant, la soumission qu\'ils demandaient, afin que la vérité de l\'évangile vous fût maintenue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Mais, de la part de ceux qui étaient tenus en haute considération... quels qu\'ils aient été, cela ne me fait rien; Dieu ne fait pas acception de personnes... quant à moi en effet, les plus considérés ne me suggérèrent rien,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'mais au contraire, voyant que l\'évangile de l\'incirconcision m\'a été confié, comme à Pierre celui de la circoncision,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(en effet Celui qui a agi en faveur de Pierre pour l\'apostolat de la circoncision a aussi agi en ma faveur parmi les Gentils),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'et reconnaissant la grâce qui m\'a été donnée, Jacques, et Céphas, et Jean, qui sont tenus pour les colonnes, me donnèrent leurs mains droites ainsi qu\'à Barnabas, en signe d\'union, afin que, nous, nous allassions vers les Gentils, et eux vers les circoncis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'demandant seulement que nous nous souvinssions des pauvres, ce que je me suis aussi appliqué à faire, précisément à cause de cela.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Mais, lorsque Céphas vint à Antioche, je lui résistai en face, parce qu\'il avait été condamné;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'en effet, avant l\'arrivée de quelques personnes qui venaient d\'auprès de Jacques, il mangeait en commun avec les Gentils, mais quand il fut venu, il s\'esquivait et se tenait à l\'écart par crainte des circoncis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'et les autres Juifs s\'associèrent à sa dissimulation, en sorte que Barnabas aussi fut entraîné par leur hypocrisie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Mais, lorsque je vis qu\'ils ne marchaient pas droit selon la vérité de l\'évangile, je dis à Céphas en présence de tous: « Si toi, qui es Juif, tu vis en Gentil et non en Juif, comment contrains-tu les Gentils à judaïser?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Pour nous, nous sommes Juifs de naissance, et non pas des pécheurs d\'entre les Gentils;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'néanmoins, sachant que l\'homme n\'est point justifié par les œuvres de la loi, mais par la foi en Christ Jésus, nous aussi, nous avons cru en Jésus-Christ, afin d\'être justifiés par la foi en Christ et non par les œuvres de la loi; car, par les œuvres de la loi personne ne sera justifié.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Mais, si, en cherchant à être justifiés par Christ, nous-mêmes aussi nous étions trouvés pécheurs, Christ ne devient-il pas un ministre du péché? Loin de nous cette pensée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'En effet, si ce que j\'ai détruit, je le construis derechef, je me déclare moi-même un transgresseur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'car, pour moi, c\'est par la loi que je suis mort quant à la loi, afin de vivre pour Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'j\'ai été crucifié avec Christ; si je vis, ce n\'est plus moi, mais c\'est Christ qui vit en moi; quant à la vie dont je vis maintenant dans ma chair, je vis dans la foi en Dieu et en Christ qui m\'a aimé et qui s\'est livré lui-même pour moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Je ne rejette pas la grâce de Dieu; car, si c\'est par la loi que s\'obtient la justice, c\'est donc pour rien que Christ est mort! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'O Galates inintelligents! Qui est-ce qui vous a fascinés, vous, devant les yeux desquels a été clairement peint Jésus-Christ crucifié?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Voici seulement ce que je veux apprendre de vous: est-ce par les œuvres de la loi que vous avez reçu l\'Esprit, ou par la prédication de la foi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Etes-vous tellement inintelligents? Ayant commencé par l\'esprit, finirez-vous maintenant par la chair?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Avez-vous fait de si grandes expériences inutilement? Si ce n\'était encore qu\'inutilement!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Celui donc qui vous dispense l\'Esprit et qui développe en vous des forces miraculeuses, le fait-Il par les œuvres de la loi, ou par la prédication de la foi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'C\'est comme pour Abraham qui crut en Dieu, et auquel cela fut compté pour justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Reconnaissez donc que ceux qui croient, ceux-là sont fils d\'Abraham.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Or l\'Écriture, prévoyant que c\'est par la foi que Dieu justifie les Gentils, a d\'avance annoncé à Abraham cette bonne nouvelle: « Toutes les nations seront bénies en toi; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'en sorte que ceux qui croient sont bénis avec Abraham le croyant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'car tous ceux qui s\'en tiennent aux œuvres de la loi, sont placés sous une malédiction, parce qu\'il est écrit: « Maudit soit quiconque n\'adhère pas à toutes les choses qui sont écrites dans le livre de la loi, pour les pratiquer. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Mais, que, sous la loi, personne ne soit justifié devant Dieu, c\'est ce qui est évident, car c\'est celui qui est juste par la foi qui vivra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Or la loi n\'est pas de même nature que la foi, mais, au contraire, c\'est celui qui les aura pratiqués qui vivra par eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Christ nous a rachetés de la malédiction de la loi, en étant devenu malédiction pour nous (car il est écrit: « Maudit est quiconque est pendu au bois »),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'afin que la bénédiction donnée à Abraham se réalisât en Jésus-Christ pour les Gentils, afin que nous reçussions par la foi l\'Esprit qui a été promis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Frères, je dis, pour parler humainement, que personne n\'annule ou n\'altère une convention dûment sanctionnée, quoiqu\'elle ne soit que l\'œuvre d\'un homme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'or, c\'est à Abraham que les promesses ont été faites, et à sa postérité; il n\'est pas dit: « et aux postérités, » comme s\'il y en avait plusieurs, mais comme n\'y en ayant qu\'une seule: « et à ta postérité, » qui est Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Or, voici ce que je dis: une convention que Dieu a antérieurement sanctionnée, la loi, survenue quatre cent trente ans plus tard, ne l\'abroge pas de manière que la promesse soit mise à néant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'car, si l\'héritage provient de la loi, ce n\'est plus de la promesse: or, c\'est par une promesse que Dieu en a gratuitement fait don à Abraham. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Qu\'est-ce donc que la loi? — C\'est à cause des transgressions qu\'elle a été ensuite instituée, (jusques à ce que fut venue la postérité à laquelle ont été faites les promesses), ayant été mise en vigueur par des anges au moyen d\'un médiateur. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Mais le médiateur ne représente pas une seule partie, tandis que Dieu est un seul. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'La loi est-elle donc contre les promesses? Loin de nous cette pensée! En effet, si une loi eut été donnée, qui fût capable de procurer la vie, c\'est réellement dans la loi qu\'existerait la justice;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'mais, au contraire, l\'Écriture a tout renfermé sous le péché, afin que la promesse se réalisât, par la foi en Jésus-Christ, pour ceux qui croient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Or, avant que vînt la foi, nous étions tous enfermés sous la garde de la loi, en attendant la foi qui devait être révélée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'en sorte que la loi a été le pédagogue qui nous a conduits à Christ, afin que nous fussions justifiés par la foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Mais une fois la foi venue, nous ne sommes plus sous un pédagogue;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'car, tous, vous êtes fils de Dieu par la foi en Christ Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Vous tous, en effet, qui avez été baptisés en Christ, vous avez revêtu Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'il n\'y a ici ni Juif, ni Grec; il n\'y a ni esclave, ni homme libre; il n\'y a point de mâle et point de femme, car tous vous êtes un seul être en Christ Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Mais, si vous appartenez à Christ, vous êtes donc de la postérité d\'Abraham, héritiers selon la promesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Or je dis que l\'héritier, pendant tout le temps où il est encore un enfant, ne l\'emporte en rien sur un esclave, quoiqu\'il soit propriétaire universel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'mais il est placé sous des tuteurs et des gérants jusques à l\'époque fixée par son père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Nous aussi de même, quand nous étions des enfants, nous étions tenus en esclavage sous les rudiments du monde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'mais, lorsque est arrivé l\'accomplissement du temps, Dieu a envoyé Son fils, né d\'une femme, né sous la loi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'afin qu\'il rachetât ceux qui sont sous la loi pour que nous reçussions l\'adoption filiale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Or c\'est parce que vous êtes des fils, qu\'il a envoyé l\'esprit de Son fils dans nos cœurs, lequel s\'écrie: Abba! Père!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'En sorte que tu n\'es plus un esclave, mais un fils; or, si tu es fils, tu es aussi héritier par la grâce de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Mais, tandis qu\'alors, ne connaissant point Dieu, vous étiez esclaves de ceux qui, par leur nature, ne sont pas des Dieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'maintenant, que vous avez connu Dieu, ou plutôt que vous avez été connus par Lui, comment vous tournez-vous derechef vers les faibles et pauvres rudiments, auxquels vous voulez recommencer à vous asservir tout de nouveau?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Vous observez les jours, et les mois, et les temps, et les années!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Je crains pour vous d\'avoir inutilement travaillé parmi vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Devenez comme moi, je vous en prie, frères, car moi-même je suis devenu comme vous. Vous ne m\'avez point offensé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'mais vous savez que ce fut à cause d\'une faiblesse de la chair que je vous ai pour la première fois annoncé la bonne nouvelle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'et que vous n\'avez alors ni méprisé, ni rejeté avec dégoût l\'épreuve où vous avez été mis par ma chair, mais que vous m\'avez reçu au contraire comme un ange de Dieu, comme Christ Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Qu\'est-ce donc qui faisait votre béatitude? Car je vous atteste que, si cela eût été possible, vous vous seriez arraché les yeux pour me les donner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'En sorte que je suis devenu votre ennemi en vous disant la vérité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Ce n\'est pas avec un zèle louable qu\'ils s\'attachent à vous, mais ils veulent nous séparer, afin que vous vous attachiez avec zèle à eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Mais c\'est à ce qui est bien que vous devez vous attacher avec un zèle louable, en tout temps, et non pas seulement pendant que je me trouve parmi vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Mes enfants, vous, pour qui je souffre derechef les douleurs de l\'enfantement jusques à ce que Christ ait été formé en vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'je voudrais bien me trouver maintenant parmi vous et changer de ton, car je suis inquiet à votre sujet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Dites-moi, vous qui voulez être sous la loi, ne prêtez-vous point l\'oreille à la loi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Car il est écrit qu\'Abraham eut deux fils, un de la servante, et un de la femme libre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'mais celui de la servante naquit selon la chair, tandis que celui de la femme libre naquit par l\'effet de la promesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Ce sont là des allégories; car ces femmes représentent deux alliances: l\'une qui vient de la montagne de Sina, et qui engendré pour la servitude, c\'est Agar,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, '(or le mot Agar désigne en Arabie le mont Sina); mais elle correspond à la Jérusalem actuelle, car celle-ci est dans la servitude avec ses enfants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'tandis que la Jérusalem d\'en haut est libre; c\'est elle qui est notre mère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'car il est écrit: « Réjouis-toi stérile, qui n\'enfantes point; éclate et crie, toi qui ne ressens pas les douleurs de l\'enfantement! Car les enfants de la délaissée seront plus nombreux que ceux de la femme qui a le mari. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Pour vous, frères, comme Isaac, vous êtes enfants de la promesse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'mais, de même qu\'alors celui qui était né selon la chair persécutait celui qui était né selon l\'esprit, il en est encore ainsi maintenant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Mais que dit l\'Écriture? « Chasse la servante et son fils; car le fils de la servante n\'héritera certainement pas avec le fils de la femme libre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'C\'est pourquoi, frères, nous ne sommes pas enfants d\'une servante, mais de la femme libre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'c\'est pour la liberté que Christ nous a rendus libres; demeurez donc fermes, et ne vous soumettez pas derechef au joug de la servitude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Voici, moi Paul, je vous déclare que, si vous vous faites circoncire, Christ ne vous servira à rien;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'mais je proteste derechef à tout homme qui se fait circoncire, qu\'il est tenu de pratiquer la loi tout entière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Vous avez complètement rompu avec Christ, vous tous qui êtes justifiés par la loi; vous êtes déchus de la grâce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'En effet, quant à nous, c\'est en esprit que nous saisissons par la foi l\'espoir de la justice;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'car, en Christ, ni la circoncision n\'a quelque valeur, ni l\'incirconcision, mais la foi qui montre son efficace par la charité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Vous couriez bien; qui est-ce qui vous a empêchés d\'obéir à la vérité?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Cette influence ne vient pas de Celui qui vous appelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'un peu de levain fait lever la pâte tout entière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Pour moi, j\'ai la confiance que vous ne penserez pas différemment, mais que celui qui vous trouble en portera la peine, quel qu\'il soit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Quant à moi, frères, si je prêche encore la circoncision, pourquoi suis-je encore persécuté, puisque le scandale, de la croix a disparu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Puissent ceux qui vous bouleversent en venir à se mutiler tout à fait!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Pour vous, frères, c\'est bien à la liberté que vous avez été appelés; seulement ne faites pas de cette liberté une instigation pour la chair, mais asservissez-vous les uns aux autres par Sa charité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'car toute la loi est accomplie dans une seule parole, qui est celle-ci: « Tu aimeras ton prochain comme toi-même; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'tandis que si vous vous mordez et vous dévorez les uns les autres, prenez garde que vous ne soyez détruits les uns par les autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Mais je dis: conduisez-vous selon l\'esprit et ne satisfaites pas la convoitise de la chair;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'en effet la chair convoite contre l\'esprit, et l\'esprit contre la chair, car ils sont opposés l\'un à l\'autre, afin que vous ne fassiez pas ce que vous voudriez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Mais, si vous êtes conduits pur l\'esprit, vous n\'êtes pas sous la loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Or les œuvres de la chair sont bien connues: ce sont l\'impudicité, l\'impureté, la débauche,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'l\'idolâtrie, la magie, les inimitiés, les querelles, la jalousie, les emportements, les intrigues, les divisions, les sectes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'les haines, les excès, les orgies, et tout ce qui leur ressemble; dont je vous dis d\'avance, comme je vous l\'ai déjà dit, que ceux qui commettent de telles choses n\'hériteront point le royaume de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Mais le fruit de l\'esprit est la charité, la joie, la paix, la longanimité, la bonté, la probité, la fidélité, la douceur, la tempérance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'Ce n\'est pas à de telles choses que s\'oppose la loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Or, ceux qui appartiennent à Christ Jésus ont crucifié la chair avec ses passions et ses convoitises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Si nous vivons par l\'esprit, marchons aussi selon l\'esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Ne devenons pas glorieux, nous provoquant les uns les autres, nous enviant les uns les autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Frères, quand même un homme est ouvertement surpris dans quelque faute, vous qui êtes spirituels, corrigez-le avec un esprit de douceur; prenant garde à toi-même, de peur que, toi aussi, tu ne sois tenté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Portez les fardeaux les uns des autres, et ainsi vous accomplirez la loi de Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'car si quelqu\'un s\'imagine être quelque chose, quoiqu\'il ne soit rien, il se déçoit lui-même;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'mais qu\'il examine ses propres œuvres, et alors c\'est par rapport à lui-même seulement qu\'il aura de quoi s\'enorgueillir, et non par rapport à autrui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'car chacun portera sa propre charge;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'toutefois que celui auquel est enseignée la parole s\'unisse à celui qui la lui enseigne pour tout ce qui est bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Ne vous y trompez pas: on ne se moque pas de Dieu; car ce qu\'un homme sème, c\'est aussi ce qu\'il moissonnera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'En effet, celui qui sème pour sa propre chair moissonnera de la chair la perdition, tandis que celui qui sème pour l\'esprit moissonnera de l\'esprit la vie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Mais ne nous décourageons point de faire le bien, car nous moissonnerons au temps voulu, si nous ne nous relâchons point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Ainsi donc, tant que nous en aurons l\'occasion, faisons ce qui est bien envers tous, mais surtout envers ceux qui composent la famille de la foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Voyez avec quelles grandes lettres je vous ai écrit de ma propre main:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Tous ceux, qui veulent se faire bien voir en ce qui tient à la chair, ce sont ceux-là qui vous contraignent de vous faire circoncire, uniquement afin de n\'être pas persécutés pour la croix de Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'car ces circoncis eux-mêmes n\'observent pas davantage la loi, mais ils veulent que vous vous fassiez circoncire, afin de trouver en votre propre chair un motif de s\'enorgueillir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Pour moi, qu\'il ne m\'arrive pas de m\'enorgueillir d\'autre chose que de la croix de notre seigneur Jésus-Christ, par qui le monde est crucifié pour moi, et moi pour le monde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'car ce n\'est ni d\'être circoncis, ni d\'être incirconcis, qui fait rien, mais d\'être une nouvelle créature.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Et tous ceux qui marcheront en suivant cette règle, que la paix et la miséricorde reposent sur eux et sur l\'Israël de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Qu\'à l\'avenir personne ne me cause plus de soucis, car je porte sur mon corps les marques de Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Frères, que la grâce du seigneur Jésus-Christ soit avec votre esprit. Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paul, apôtre de Christ Jésus par la volonté de Dieu, aux saints qui sont aussi fidèles en Christ Jésus:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Que la grâce et la paix vous soient données par Dieu notre Père et par le seigneur Jésus-Christ!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Béni soit le Dieu de notre seigneur Jésus-Christ, qui nous a bénis par toute; espèce de bénédiction spirituelle dans les lieux célestes en Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'selon qu\'il nous a élus en lui avant la fondation du monde, pour que nous fussions saints et irrépréhensibles devant Lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'nous ayant prédestinés, dans Sa charité, à devenir, par Christ Jésus, Ses enfants d\'adoption, suivant le bon plaisir de Sa volonté,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'à la louange de la gloire de Sa grâce, qu\'il nous a gratuitement accordée par le bien-aimé');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'en qui nous possédons la rédemption par son sang, le pardon de nos fautes, selon la richesse de Sa grâce,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'qu\'Il a répandue abondamment sur nous par toute espèce de sagesse et d\'intelligence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'en nous faisant connaître le mystère de Sa volonté, selon le libre dessein qu\'il avait d\'avance formé en Lui-même,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'pour l\'exécuter lors de l\'accomplissement des temps, de rassembler toutes choses en Christ, tant celles qui sont aux cieux, que celles qui sont sur la terre, en lui, dis-je,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'en qui nous avons aussi été mis en possession de l\'héritage, selon que nous y avions été prédestinés d\'après le décret de Celui qui opère toutes choses suivant le dessein de Sa volonté,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'pour que nous servions à la louange de Sa gloire, nous, qui d\'avance avons espéré en Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'en qui, vous-mêmes aussi, depuis que vous avez ouï la parole de la vérité, la bonne nouvelle de votre salut, en qui, dis-je, vous-mêmes aussi ayant cru, vous avez été scellés par l\'esprit saint qui avait été promis,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'lequel est un gage de notre héritage, pour avoir part à la rédemption de ceux que Dieu s\'est acquis, à la louange de Sa gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'C\'est pourquoi, moi aussi, ayant appris quelle est votre foi au Seigneur Jésus et votre fidélité envers tous les saints,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'je ne cesse de rendre des actions de grâces pour vous, faisant mention de vous dans mes prières,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'afin que le Dieu de notre seigneur Jésus-Christ, le Père de gloire, vous donne un esprit de sagesse et de révélation;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'les yeux de votre cœur étant illuminés par sa connaissance, de telle sorte que vous sachiez quelle est l\'espérance attachée à Son appel, quelle est la richesse de la gloire de Son héritage parmi les saints,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'et quelle est, envers nous qui croyons, l\'excessive grandeur de Son pouvoir, qui se montre dans l\'efficace puissante de Sa force,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'qu\'il a déployée en Christ, en le ressuscitant des morts et en le faisant asseoir à Sa droite dans les cieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'au-dessus de toute espèce d\'autorité, et de domination, et de puissance, et de seigneurie, et de tout nom donné, non seulement dans le siècle présent, mais encore dans celui qui est à venir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'et Il a tout placé sous ses pieds, et Il l\'a donné comme chef universel à l\'Église');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'qui est son corps, la plénitude de Celui qui, de toutes manières, remplit toutes choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Et vous, qui étiez morts par vos fautes et vos convoitises,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'dans lesquelles vous avez marché jadis selon le train de ce monde, selon le chef de la puissance de l\'air, de l\'esprit qui agit maintenant dans les fils de la désobéissance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'parmi lesquels, nous aussi, nous nous livrions tous jadis aux convoitises de notre chair, accomplissant les volontés de la chair et de nos pensées, et nous étions, par nature, des enfants de colère comme les autres...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'mais Dieu, qui est riche en miséricorde, à cause de la grande charité dont Il nous a aimés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'nous aussi, qui étions morts par nos fautes et nos convoitises, Il nous a rendus à la vie avec vous en Christ, (c\'est par grâce que vous avez été sauvés),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'et Il nous a ensemble ressuscités et fait asseoir dans les lieux célestes en Christ Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'afin de montrer, dans les siècles à venir, l\'excessive richesse de Sa grâce par Sa bonté, dont nous sommes les objets en Christ Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Car c\'est par la grâce que vous êtes sauvés, au moyen de la foi, et cela ne vient pas de vous, c\'est le don de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'ce n\'est point par les œuvres, afin que personne ne s\'enorgueillisse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'car nous sommes Son ouvrage, ayant été créés en Christ Jésus pour de bonnes œuvres, que Dieu a d\'avance préparées, afin que ce soit en elles que nous marchions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'C\'est pourquoi souvenez-vous que, naguère, vous, les païens par la chair, qui étiez appelés l\'incirconcision par ce qui s\'appelle la circoncision faite manuellement en la chair,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'que vous étiez, dis-je, en ce temps-là, sans Christ, étant en dehors de la société d\'Israël et étrangers aux alliances de la promesse, n\'ayant point d\'espérance, et étant sans Dieu dans le monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Mais maintenant, en Christ Jésus, vous qui étiez naguère éloignés, vous avez été rapprochés par le sang de Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'car c\'est lui qui est notre paix, lui, qui de l\'un et de l\'autre a fait un seul, et qui a détruit le mur qui formait la séparation,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'je veux dire la haine, en anéantissant par sa propre chair la loi des commandements donnés sous forme de décrets, afin de créer en lui, de tous les deux, un seul homme nouveau, en faisant la paix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'et de les réconcilier l\'un et l\'autre, en un seul et même corps, avec Dieu par la croix, en détruisant la haine par elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Et il est venu annoncer la bonne nouvelle de la paix à vous qui étiez éloignés, et à ceux qui sont près,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'car c\'est par lui que nous avons, les uns et les autres, en un seul et même esprit, l\'accès auprès du Père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Ainsi donc vous n\'êtes plus étrangers et sans droit de cité, mais vous êtes concitoyens des saints et membres de la famille de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'ayant été édifiés sur le fondement des apôtres et des prophètes, la pierre angulaire étant Christ Jésus même,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'en qui tout édifice, ayant ses parties bien ajustées, s\'élève comme un sanctuaire sacré dans le seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'en qui, vous aussi, vous êtes tous édifiés ensemble pour devenir une habitation de Christ en esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'C\'est pour cela que, moi Paul, je suis le prisonnier de Christ Jésus pour vous, les Gentils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'si, en effet, vous avez ouï parler de la manière dont m\'a été dispensée la grâce de Dieu qui m\'a été donnée pour vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'c\'est par révélation que m\'a été communiqué le mystère, tel que je l\'ai ci-devant écrit en peu de mots;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'd\'après quoi vous pouvez, en me lisant, comprendre que je suis versé dans le mystère de Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'lequel n\'a pas été communiqué en d\'autres générations aux fils des hommes, comme il a été maintenant révélé à Ses saints et à Ses prophètes par l\'Esprit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'c\'est à savoir, que les Gentils sont cohéritiers, et membres du même corps, et coparticipants de la promesse en Christ Jésus, par l\'Évangile');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'dont j\'ai été fait ministre selon le don de la grâce de Dieu qui m\'a été donnée, et selon l\'efficace de Sa puissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'C\'est à moi, le moindre de tous les saints, qu\'a été donnée cette grâce d\'annoncer aux Gentils la bonne nouvelle de la richesse impénétrable de Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'et de les éclairer tous sur la dispensation du mystère caché de tout temps en Dieu qui a créé toutes choses,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'afin que, maintenant, la sagesse infiniment diverse de Dieu fût portée par l\'Église à la connaissance des dominations et des autorités dans les lieux célestes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'selon le dessein formé de tout temps qu\'il a accompli en Christ Jésus notre seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'en qui nous possédons avec confiance la liberté et l\'accès par la foi que nous avons en lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Aussi je vous demande de ne point vous laisser décourager par les tribulations que je souffre pour vous, ce qui est votre gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'C\'est à cause de cela que je ploie les genoux devant le Père,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'duquel tire son nom toute lignée dans les cieux et sur la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'afin qu\'il vous donne, selon la richesse de Sa gloire, d\'être puissamment fortifiés par Son esprit dans l\'homme intérieur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'en sorte que Christ habite par la foi dans vos cœurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'afin que, étant enracinés et fondés dans la charité, vous puissiez pleinement comprendre avec tous les saints quelle est la largeur et la longueur, et la profondeur et la hauteur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'et connaître la charité de Christ qui surpasse la connaissance, afin que toute la plénitude de Dieu s\'accomplisse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Or, qu\'à Celui qui peut plus que tout faire, bien au delà de ce que nous demandons ou de ce que nous pensons, selon la puissance qui se déploie en nous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'qu\'à Lui soit rendue la gloire dans l\'Église et en Christ Jésus, durant toutes les générations du siècle des siècles. Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Je vous exhorte donc, moi, le prisonnier dans le seigneur, à vous conduire d\'une manière digne de l\'appel qui vous a été adressé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'avec toute espèce d\'humilité et de mansuétude, avec longanimité, vous supportant les uns les autres avec charité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'vous efforçant de conserver l\'unité de l\'esprit par le lien de la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Il y a un seul corps et un seul Esprit, comme c\'est à une seule espérance que se rapporte l\'appel que vous avez reçu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'il y a un seul Seigneur, une seule foi, un seul baptême;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'il y a un seul Dieu, Père de tous, qui est au-dessus de tous, et, par tous, en tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Or à chacun de vous a été donnée la grâce selon la mesure du don de Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'c\'est pourquoi il est dit: « Après être monté en haut il a capturé des captifs, et il a donné des dons aux hommes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Or l\'expression « il est monté, » qu\'emporte-t-elle, sinon qu\'il est aussi descendu premièrement dans les parties plus basses de la terre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Celui qui est descendu, c\'est lui aussi qui est monté au-dessus de tous les deux, afin de remplir toutes choses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'et c\'est lui qui a établi les uns comme apôtres, les autres comme prophètes, ceux-ci comme évangélistes, ceux-là comme pasteurs et docteurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'afin d\'accomplir, pour le perfectionnement des saints, l\'œuvre du ministère, l\'édification du corps de Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'jusques à ce que, tous, nous soyons parvenus à l\'unité de la foi et de la connaissance du fils de Dieu, à l\'état d\'homme fait, à la mesure de l\'âge de la plénitude de Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'afin que nous ne soyons plus des enfants, ballottés par les flots et emportés çà et là par tous les souffles de l\'enseignement, grâce à la tricherie des hommes, à la fourberie qui favorise les manœuvres de l\'erreur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'mais que, proclamant la vérité avec charité, nous croissions à tous égards en celui qui est le chef, Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'par l\'assistance duquel le corps entier, bien uni et bien compact, travaille à sa propre croissance, sous l\'action multiple de cette assistance, avec une efficace proportionnée à chacune de ses parties, pour s\'édifier lui-même dans la charité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Je dis donc, et j\'en atteste le seigneur, que vous ne devez plus vous conduire comme les Gentils se conduisent dans l\'inanité de leur intelligence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'ayant l\'entendement offusqué de ténèbres, étant étrangers à la vie de Dieu à cause de l\'ignorance qui est en eux, à cause de l\'endurcissement de leur cœur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'en sorte que, devenus insensibles, ils se sont livrés à la débauche, pour commettre avec excès toute espèce d\'impureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Mais, pour vous, ce n\'est pas ainsi que vous avez appris Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'si, en effet, vous avez ouï parler de lui, et si c\'est en lui que vous avez été instruits, selon que la vérité existe en Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'à dépouiller, en opposition à votre précédente conduite, le vieil homme qui se corrompt sous l\'influence des convoitises que produit l\'erreur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'et à être renouvelés par l\'Esprit dans votre intelligence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'et à revêtir le nouvel homme, qui a été créé à l\'image de Dieu avec la justice et la sainteté que produit la vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'C\'est pourquoi, ayant dépouillé, le mensonge, parlez avec vérité, chacun à votre prochain, car nous sommes membres les uns des autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Soyez en colère, et toutefois ne péchez pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'que le soleil ne se couche pas sur votre courroux, et ne donnez pas non plus de prise au diable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Que le larron ne dérobe plus, mais que plutôt il prenne de la peine en travaillant de ses mains à ce qui est bien, afin qu\'il ait de quoi donner à celui qui est dans le besoin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Qu\'aucune mauvaise parole ne sorte de votre bouche, mais seulement celle qui peut être bonne pour l\'édification selon le besoin, afin qu\'elle soit un bienfait pour les auditeurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'n\'attristez point l\'esprit saint de Dieu, par lequel vous avez été scellés pour le jour de la rédemption.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Que toute espèce d\'aigreur, et d\'irritation, et de colère, et de cris, et de calomnie, soit enlevée du milieu de vous, ainsi que toute espèce de méchanceté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Devenez bons les uns pour les autres, compatissants, vous pardonnant réciproquement comme Dieu aussi nous a pardonné en Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'devenez donc des imitateurs de Dieu, comme Ses enfants bien-aimés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'et marchez dans la charité, comme Christ aussi vous a aimés et s\'est livré lui-même pour vous à Dieu en offrande et en sacrifice, comme un parfum d\'agréable odeur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Mais que l\'impudicité et toute espèce d\'impureté, ou la cupidité, ne soient pas même nommées parmi vous, comme il convient à des saints,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'non plus que l\'impudeur et le bavardage, ou la bouffonnerie, qui sont choses inconvenantes, mais qu\'on y entende plutôt l\'action de grâce;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'car sachez et connaissez ceci, c\'est que tout impudique, ou impur, ou cupide, ce qui veut dire un idolâtre, ne possède pas d\'héritage dans le royaume de Christ et de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Que personne ne vous trompe par de vains discours: c\'est bien à cause de ces choses que la colère de Dieu vient sur les fils de la désobéissance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'ne vous associez donc pas à eux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'car, si vous étiez autrefois ténèbres, vous êtes maintenant lumière dans le seigneur; conduisez-vous comme des enfants de lumière,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(car le fruit de la lumière consiste en toute espèce de bonté, de justice et de vérité),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'examinant ce qui plaît au seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'et ne prenez point de part aux œuvres infructueuses des ténèbres, mais bien plutôt blâmez-les;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'il est vrai que ce qu\'ils font en secret, il est honteux même d\'en parler,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'mais quand toutes ces choses sont blâmées, c\'est par la lumière qu\'elles sont dévoilées, car tout ce qui est dévoilé est lumière;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'c\'est pourquoi il est dit: « Réveille-toi, dormeur, et relève-toi d\'entre les morts, et le Christ t\'illuminera. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Prenez donc scrupuleusement garde à la manière dont vous vous conduisez, non pas comme des gens dépourvus de sagesse, mais comme des sages,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'mettant bien le temps à profit, car les jours sont mauvais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'C\'est pourquoi ne devenez pas déraisonnables, mais comprenez quelle est la volonté de notre seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'et ne vous enivrez pas de vin, ce qui entraîne avec soi le dérèglement; mais soyez remplis de l\'Esprit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'vous parlant les uns aux autres par des psaumes, et des hymnes, et des chants, chantant et célébrant en votre cœur le seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'rendant grâces constamment pour toutes choses, au nom de notre seigneur Christ Jésus, à Dieu le Père,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'nous soumettant les uns aux autres dans la crainte de Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Que les femmes le soient à leurs propres maris, comme au Seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'parce que le mari est chef de la femme, comme Christ aussi est chef de l\'Église, lui sauveur du corps;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'mais, si l\'Église est soumise à Christ, que, de même aussi, les femmes le soient à leurs maris en toute chose.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Pour vous, maris, aimez vos femmes, comme Christ aussi a aimé l\'Église et s\'est lui-même livré pour elle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'afin de la sanctifier par la parole, après l\'avoir purifiée par l\'ablution de l\'eau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'pour se présenter à lui-même l\'Église glorieuse, n\'ayant ni tache, ni ride, ni rien de semblable, mais afin qu\'elle soit sainte et irrépréhensible.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'De même les maris aussi doivent aimer leurs femmes comme leurs propres corps; celui qui aime sa femme s\'aime lui-même,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'car personne n\'a jamais haï sa propre chair, mais il l\'entretient et en prend soin comme Christ aussi le fait pour l\'Église,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'parce que nous sommes membres de son corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'C\'est pour cela que l\'homme quittera père et mère, et il s\'unira étroitement à sa femme, et les deux deviendront une seule chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Ce mystère est grand, mais j\'en parle relativement à Christ et à l\'Église;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'néanmoins que, parmi vous aussi, chacun aime sa femme comme lui-même; quant à la femme, qu\'elle craigne son mari.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Enfants, obéissez à vos parents; car cela est juste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, '« Honore ton père et ta mère; » c\'est le premier commandement qui soit accompagné d\'une promesse:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, '« afin que tu sois heureux, et que tu vives longtemps sur la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Et vous, pères, n\'irritez pas vos. enfants, mais élevez-les dans la discipline et l\'admonition du Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Esclaves, obéissez à vos maîtres selon la chair, avec crainte et tremblement, dans la simplicité de votre cœur, comme à Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'non point avec une soumission extérieure comme pour plaire aux hommes, mais comme des esclaves de Christ qui font de cœur la volonté de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'vous asservissant avec empressement, comme au seigneur et non à un homme,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'sachant que ce que chacun aura fait de bon, il en recevra la rétribution de la part du Seigneur, que ce soit un esclave ou un homme libre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Et vous, maîtres, agissez de même envers eux, mettant de côté la menace, sachant que leur Maître et le vôtre est dans les cieux, et qu\'il n\'y a pas devant Lui acception de personnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Au reste, fortifiez-vous dans le seigneur et par la puissance de sa force;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'revêtez-vous de toutes les armes de Dieu afin de pouvoir résister aux manœuvres du diable;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'car ce n\'est pas contre le sang et la chair que vous avez à lutter, mais contre les dominations, contre les autorités, contre les souverains de ce monde de ténèbres, contre les esprits méchants dans les lieux célestes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'C\'est pourquoi saisissez toutes les armes de Dieu, afin que vous puissiez résister dans le jour mauvais, et, après avoir tout mis en œuvre, tenir ferme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Tenez donc ferme, ayant ceint vos reins de la vérité, et ayant revêtu la cuirasse de la justice,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'et ayant pris pour chaussure de vos pieds le zèle qu\'inspire l\'Évangile de paix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'saisissant en toute circonstance le bouclier de la foi, au moyen duquel vous pourrez éteindre tous les dards enflammés du malin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'et munissez-vous du casque du salut et de l\'épée de l\'esprit, qui est la parole de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'adressant en toute occasion toute sorte de prières et d\'intercessions par l\'esprit, et veillant à cela avec une entière persévérance, priant pour tous les saints');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'et pour moi, afin qu\'il me soit donné, en ouvrant la bouche, de parler avec liberté, pour faire connaître le mystère');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'pour lequel je suis ambassadeur dans les chaînes, afin que je l\'expose avec la liberté avec laquelle je dois parler.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Mais, afin que, vous aussi, vous sachiez ce qui me concerne, et l\'état où je suis, vous serez informés de tout par Tychique, le frère bien-aimé et le fidèle ministre dans le seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'que je vous ai envoyé, précisément afin que vous fussiez instruits de l\'état de nos affaires, et qu\'il consolât vos cœurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Que la paix soit avec les frères, ainsi que la charité unie à la foi, de la part de Dieu le Père et du seigneur Jésus-Christ!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Que la grâce soit avec tous ceux qui aiment notre seigneur Jésus-Christ d\'une manière incorruptible!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paul et Timothée, esclaves de Christ Jésus, à tous les saints en Christ Jésus qui sont à Philippes, avec les évêques et les diacres:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Que la grâce et la paix vous soient données par Dieu notre Père, et par le Seigneur Jésus-Christ!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Je rends de constantes actions de grâces à mon Dieu');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'dans chacune de mes prières pour tout le souvenir que je conserve de vous; Lui adressant avec joie ma prière pour vous tous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'à cause de votre commun accord pour l\'Évangile');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'dès le premier jour jusques à maintenant, ayant la confiance positive que Celui qui a commencé en vous une œuvre excellente la consommera d\'ici à la journée de Christ Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Il est juste en effet que je pense ainsi sur vous tous, car je vous porte dans mon cœur, vous, qui tous, soit dans mes chaînes, soit dans la défense et la confirmation de l\'Évangile, partagez avec moi la grâce qui m\'est faite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'car Dieu m\'est témoin, que je vous chéris tous avec la tendresse de Christ Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Et, ce que je demande dans mes prières, c\'est que votre charité abonde encore plus en connaissance et en toute espèce de discernement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'pour que vous appréciiez ce qui est excellent, afin d\'être purs et irréprochables pour la journée de Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'possédant pleinement par Jésus-Christ le fruit de la justice, à la gloire et à la louange de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Je veux cependant que vous sachiez, frères, que ma position a plutôt contribué aux progrès de l\'Évangile,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'en sorte que, dans tout le prétoire et partout ailleurs, il est devenu manifeste que c\'est pour Christ que je suis dans les chaînes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'et la plupart des frères, prenant, grâce au Seigneur, confiance en mes chaînes, se sentent beaucoup plus enhardis à annoncer sans crainte la parole de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Quelques-uns, il est vrai, prêchent aussi Christ par un esprit d\'envie et de dispute, tandis que quelques autres le font aussi par bienveillance:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'les uns agissent par charité, sachant que je suis chargé de la défense de l\'Évangile;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'les autres, agissant par intrigue, annoncent Christ sans pureté, avec l\'intention de provoquer une tribulation pour mes chaînes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Qu\'importe? Car, de manière ou d\'autre, avec ou sans arrière-pensée, Christ est annoncé, et c\'est là ce dont je me réjouis, et ce dont je me réjouirai encore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Je sais d\'ailleurs que cela me tournera à salut, grâce à vos prières et à l\'assistance de l\'Esprit de Jésus-Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'selon ma vive attente et l\'espoir où je suis que je n\'aurai à rougir sur aucun point, mais que, maintenant comme toujours, Christ sera magnifié en mon corps avec une pleine franchise, soit par ma vie, soit par ma mort;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'car pour moi la vie est Christ, et la mort est un gain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Mais si la vie dans la chair était utile pour mon œuvre? En ce cas, je ne sais ce que je dois préférer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'mais je suis pressé de part et d\'autre, ayant le désir de partir et d\'être avec Christ, car cela est de beaucoup le meilleur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'mais toutefois le séjour en la chair est plus nécessaire à cause de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Et c\'est parce que j\'ai cette confiance, que je sais que je demeurerai, et que je resterai auprès de vous tous pour l\'avancement et la joie de votre foi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'afin que le motif de m\'enorgueillir à votre sujet s\'accroisse pour moi en Christ Jésus lors de mon retour parmi vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Seulement, comportez-vous d\'une manière digne de l\'évangile de Christ, afin que, soit que je vienne et que je vous voie, soit que je sois absent, j\'apprenne, en ce qui vous concerne, que vous demeurez fermes dans un seul et même esprit, luttant ensemble d\'une seule et même âme pour la foi de l\'Évangile,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'et ne vous laissant sur aucun point effrayer par les adversaires; ce qui est pour eux une démonstration de leur perdition, mais de votre salut; et cela vient de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'car il vous a été fait la grâce, quant à Christ, non seulement de croire en lui, mais encore de souffrir pour lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'en soutenant le même combat que vous m\'avez vu soutenir, et que vous apprenez maintenant que je soutiens encore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Si donc il existe quelque consolation en Christ, s\'il existe quelque soulagement de la charité, s\'il existe quelque union d\'esprit, s\'il existe quelque tendresse et quelques compassions,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'rendez ma joie parfaite, afin d\'être animés du même sentiment, ayant la même charité, formant une seule âme, étant animés d\'un seul et même sentiment,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'et d\'aucun de ceux qu\'inspirent l\'intrigue et la vaine gloire, mais regardant réciproquement les autres par humilité comme supérieurs à vous-mêmes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'ne songeant point chacun à vos propres intérêts, mais chacun aussi à ceux des autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Soyez animés au dedans de vous des sentiments dont fut aussi animé Christ Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'lequel, existant en forme de Dieu, n\'a pas considéré comme une proie l\'égalité avec Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'mais s\'est dépouillé lui-même, en prenant une forme d\'esclave, en naissant d\'une manière semblable aux hommes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'et, après avoir été trouvé, quant à l\'apparence, semblable à un homme, il s\'est humilié lui-même en se montrant obéissant jusques à mourir, à mourir même sur une croix;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'c\'est pourquoi aussi Dieu l\'a haut élevé, et lui a octroyé le nom qui est au-dessus de toute espèce de nom,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'afin qu\'au nom de Jésus tout genou fléchisse dans les cieux, sur la terre, et sous la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'et que toute langue confesse que Jésus-Christ est Seigneur, à la gloire de Dieu le Père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Ainsi, mes bien-aimés, comme vous avez toujours obéi, que ce ne soit pas seulement en ma présence, mais bien plus encore maintenant en mon absence, que vous travailliez à votre propre salut avec crainte et tremblement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'car c\'est Dieu qui effectue en vous, et la volonté, et l\'action, d\'après Son bon plaisir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Faites toutes choses sans murmures ni hésitations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'afin de devenir irréprochables et purs, des enfants de Dieu irrépréhensibles au milieu d\'une génération pervertie et corrompue, parmi laquelle vous brillez comme des luminaires dans le monde,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'en portant avec vous la parole de vie, ce qui sera pour moi un motif de m\'enorgueillir, lors de la journée de Christ, de n\'avoir ni couru en vain, ni travaillé en vain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Mais, dussé-je servir de libation en officiant dans le sacrifice de votre foi, je m\'en réjouis, et je suis dans la joie avec vous tous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'vous aussi, réjouissez-vous de même, et soyez avec moi dans la joie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Or, j\'espère dans le Seigneur Jésus vous envoyer incessamment Timothée, afin que, moi aussi, je reprenne courage en apprenant ce qui vous concerne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'car je n\'ai ici personne qui, sentant de même, puisse prendre véritablement souci de ce qui vous concerne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'tous, en effet, ils recherchent leurs propres intérêts, et non ceux de Christ Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'mais, quant à lui, vous savez qu\'il a été mis à l\'épreuve, en s\'assujettissant avec moi, comme un enfant sous son père, au service de l\'Évangile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'C\'est donc lui que j\'espère vous envoyer, aussitôt que j\'aurai pu juger de la tournure de mes affaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Or, j\'ai la confiance dans le Seigneur que, de mon côté aussi, j\'arriverai incessamment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'En attendant, j\'ai cru nécessaire de vous expédier Épaphrodite, mon frère, mon compagnon d\'œuvre et de combat, que vous aviez député pour pourvoir à mes besoins,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'car il soupirait après vous tous, et il se désespérait de ce que vous aviez ouï dire qu\'il avait été malade;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'et en effet il a été malade à la mort; mais Dieu a eu compassion de lui, et non seulement de lui, mais aussi de moi, afin que je n\'eusse pas tristesse sur tristesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'J\'ai donc mis d\'autant plus d\'empressement à l\'envoyer; afin que, en le voyant, vous redeveniez joyeux, et que, moi-même, je sois moins triste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Accueillez-le donc dans le Seigneur avec une joie entière, et honorez ceux qui lui ressemblent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'car c\'est pour l\'œuvre de Christ qu\'il a été à la mort, en exposant sa vie afin de suppléer à votre absence dans le service qui m\'était rendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Au reste, mes frères, réjouissez-vous dans le Seigneur. Je ne me lasse point, quant à moi, de vous écrire les mêmes choses, et, quant à vous, cela importe à votre sûreté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Prenez garde aux chiens, prenez garde aux mauvais ouvriers, prenez garde à l\'incision,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'car c\'est nous qui sommes la circoncision, nous qui, par l\'Esprit de Dieu, rendons un culte, et qui nous glorifions en Christ Jésus, et qui ne mettons point notre confiance en la chair,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'quoique, pour moi, je puisse mettre aussi ma confiance en la chair; si quelque autre s\'imagine mettre sa confiance en la chair, moi, je le puis davantage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'moi, qui ai été circoncis le huitième jour, qui suis de la race d\'Israël, de la tribu de Benjamin, Hébreu né d\'Hébreux, quant à la loi, pharisien,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'quant au zèle, persécuteur de l\'Église, quant à la justice qui gît dans la loi, demeuré irréprochable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Mais toutes les choses qui, pour moi, étaient des gains, je les ai regardées, à cause de Christ, comme une perte;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'mais il y a plus: je regarde même toutes choses comme une perte, à cause de l\'excellence de la connaissance de Christ Jésus mon Seigneur, à cause duquel je les ai toutes perdues, et je les regarde comme des ordures, afin de gagner Christ');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'et d\'être trouvé uni à lui, ne possédant point pour ma justice celle qui vient de la loi, mais celle qui s\'obtient par la foi en Christ, la justice qui vient de Dieu en conséquence de la foi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'afin de le connaître, et de connaître aussi la puissance de sa résurrection et l\'union avec ses souffrances, en m\'assimilant à sa mort,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'pour tâcher de parvenir à la résurrection d\'entre les morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Non que j\'aie déjà remporté le prix, ou que je sois déjà arrivé à la perfection, mais je me hâte pour tâcher de le saisir, car c\'est pour cela que j\'ai été aussi saisi par Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Frères, pour moi, je ne crois point l\'avoir moi-même saisi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'mais, occupé d\'une seule chose, oubliant ce qui est derrière moi et me portant vers ce qui est devant moi, je me hâte pour atteindre au but, et pour remporter le prix de l\'appel que, d\'en haut, Dieu nous adresse en Christ Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Nous tous donc, qui sommes parfaits, soyons animés de ce sentiment, et, s\'il est quelque point sur lequel vous soyez animés de sentiments contraires, Dieu vous le révélera aussi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'En attendant, au point où nous sommes parvenus, marchez du même pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Devenez tous ensemble mes imitateurs, et portez vos regards sur ceux qui se conduisent selon le modèle que vous avez en nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Il en est en effet plusieurs qui se conduisent... eux dont je vous parlais souvent, et dont maintenant je parle encore avec larmes, les ennemis de la croix de Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'qui n\'ont à attendre que la perdition, qui ont pour dieu leur ventre, et qui mettent leur gloire dans leur infamie, les amateurs des choses de la terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'car, pour nous, notre société est dans les cieux, d\'où nous attendons aussi, comme sauveur, le Seigneur Jésus-Christ');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'qui transformera le corps de notre humiliation à la ressemblance du corps de sa gloire, selon l\'efficace du pouvoir qu\'il possède de s\'assujettir même toutes choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Ainsi donc, mes frères bien-aimés, après lesquels je soupire, vous qui êtes ma joie et ma couronne, demeurez ainsi fermes dans le Seigneur, mes bien-aimés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'J\'exhorte Évodie, et j\'exhorte Syntyche à être animées des mêmes sentiments dans le Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Et même je t\'en prie aussi, toi, digne collègue, intéresse-toi à elles, car elles ont combattu avec moi pour l\'Evangile, ainsi que Clément et mes autres coopérateurs, dont les noms se trouvent dans le livre de vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Réjouissez-vous toujours dans le Seigneur; je vous le répète: Réjouissez-vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Que votre mansuétude se fasse connaître à tous les hommes. Le Seigneur est proche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Ne vous inquiétez de rien, mais, qu\'en toute chose, vos demandes se fassent connaître à Dieu par la prière et l\'intercession, avec actions de grâces,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'et la paix de Dieu, qui surpasse toute intelligence, tiendra sous sa garde en Christ Jésus vos cœurs et vos pensées.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Au reste, frères, que toutes les choses qui sont vraies, toutes celles qui sont honorables, toutes celles qui sont justes, toutes celles qui sont pures, toutes celles qui sont aimables, toutes celles qui sont approuvées, qu\'en un mot toute vertu et toute louange fassent l\'objet de vos pensées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'et ce que vous avez appris et reçu, ouï et vu de moi, pratiquez-le; et le Dieu de paix sera avec vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Quant à moi, je me suis grandement réjoui dans le Seigneur de ce que vous avez enfin repris de l\'intérêt pour moi; vous y pensiez bien, mais l\'occasion vous manquait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Ce n\'est pas que je parle par motif de dénuement; car j\'ai appris à me suffire à moi-même dans la position où je me trouve;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'je sais vivre dans l\'humiliation, et je sais aussi vivre dans l\'abondance; en toutes choses et en toutes circonstances, je suis initié, soit à être rassasié, soit à avoir faim, soit à vivre dans l\'abondance, soit à vivre dans la disette;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'je peux tout en Celui qui me rend fort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Néanmoins, vous avez bien fait de prendre part à ma tribulation;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'd\'ailleurs, vous aussi, Philippiens, vous savez que, au commencement de la prédication de l\'Évangile, quand je quittai la Macédoine, aucune église n\'ouvrit avec moi un compte réciproque de don et de recette, si ce n\'est vous seuls,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'car, déjà à Thessalonique, vous m\'avez envoyé, à deux reprises, de quoi subvenir à mes besoins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Ce n\'est pas que je recherche les cadeaux, mais je recherche le fruit qui surabonde pour votre compte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'D\'ailleurs j\'ai reçu tout ce qu\'il me faut, et je suis dans l\'abondance; je suis comblé, depuis que j\'ai reçu par Épaphrodite ce qui vient de vous, parfum d\'agréable odeur, sacrifice agréé et approuvé de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Mais c\'est mon Dieu qui, selon Sa richesse, satisfera pleinement tous vos besoins avec gloire en Christ Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Qu\'à Dieu notre Père soit rendue la gloire pour les siècles des siècles. Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Saluez en Christ Jésus tous les saints. Les frères qui sont avec moi vous saluent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Tous les saints vous saluent, et principalement ceux de la maison de l\'empereur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Que la grâce du Seigneur Jésus-Christ soit avec votre esprit!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paul, apôtre de Christ Jésus par la volonté de Dieu, et le frère Timothée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'aux saints et fidèles frères en Christ, qui sont à Colosses: Que la grâce et la paix vous soient données par Dieu notre Père!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Nous rendons de constantes actions de grâces à Dieu, le Père de notre seigneur Jésus, dans les prières que nous faisons pour vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'car nous avons appris quelle est votre foi en Christ Jésus et votre charité pour tous les saints,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'à cause de l\'espérance qui vous est réservée dans les cieux, laquelle vous a déjà été annoncée par la parole de la vérité de l\'Évangile');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'qui est parvenu jusques à vous, de même qu\'il fructifie et croît dans le monde entier comme parmi vous, depuis le jour où vous avez ouï et reconnu la grâce de Dieu dans la vérité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'selon que vous l\'avez apprise d\'Épaphras, notre bien-aimé compagnon d\'esclavage, qui est, pour nous, un fidèle ministre de Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'et qui nous a aussi fait connaître la charité que l\'Esprit vous inspire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'C\'est pourquoi, nous aussi, depuis le jour où nous en avons été informés, nous ne cessons point de prier pour vous, afin que vous soyez remplis de la connaissance de Sa volonté, avec toute sorte de sagesse et d\'intelligence spirituelle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'pour vous conduire d\'une manière digne du Seigneur en vue de lui plaire parfaitement par toute espèce de bonnes œuvres: fructifiant et croissant par la connaissance de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'étant puissamment fortifiés de toute manière, selon la force de Sa gloire, pour tout endurer et supporter,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'rendant en même temps avec joie des actions de grâces au Père, qui vous a appelés et qui vous a rendus capables d\'avoir part au lot des saints dans la lumière;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Lui, qui nous a délivrés de la puissance des ténèbres, et qui nous a transportés dans le royaume du fils de Son amour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'en qui nous possédons la rédemption, le pardon de nos péchés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'qui est une image du Dieu invisible, premier-né de toute création,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'car c\'est par lui qu\'ont été créés toutes choses dans les cieux et sur la terre, les choses visibles et les choses invisibles, soit les trônes, soit les seigneuries, soit les dominations, soit les autorités; toutes choses ont été créées par lui et pour lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'et lui-même existe avant toutes choses, et toutes choses subsistent en lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'et lui-même est le chef du corps, de l\'Église, lui qui en est le principe, comme premier-né d\'entre les morts, afin qu\'en toutes choses il occupe la première place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'En effet Il a jugé bon que toute Sa plénitude habitât en lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'et de réconcilier par lui, en faisant la paix par le sang de sa croix, toutes choses avec Lui-même, soit les choses qui sont sur la terre, soit les choses qui sont dans les cieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'et vous aussi, qui, étrangers et ennemis par vos sentiments, viviez naguère dans vos mauvaises œuvres. Mais maintenant vous avez été réconciliés');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'dans le corps de sa chair par la mort, pour vous présenter saints, irrépréhensibles et irréprochables devant lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'si, du moins, vous restez fondés et fermes dans la foi, sans vous écarter de l\'espérance de l\'Évangile que vous avez ouï, lequel a été prêché à toute la création qui est sous le ciel, et dont moi, Paul, j\'ai été fait ministre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Maintenant je me réjouis de mes souffrances pour vous, et je supplée, dans ma chair, à ce qui manque aux souffrances de Christ pour son corps, qui est l\'église,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'dont j\'ai été fait ministre selon l\'administration que Dieu m\'a confiée par rapport à vous, afin d\'accomplir la parole de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'le mystère, qui, caché de tout temps et à toute génération, a été maintenant manifesté à Ses saints,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'auxquels Dieu a voulu faire connaître quelle est la richesse de la gloire de ce mystère parmi les Gentils, je veux dire: Christ en vous, l\'espérance de la gloire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'lui que nous annonçons en exhortant tous les hommes, et en les instruisant tous en toute sagesse, afin que nous présentions tous les hommes devenus parfaits en Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'C\'est à cela aussi que je travaille, luttant selon sa force qui déploie en moi son efficace avec puissance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'car je veux que vous sachiez quelle grande lutte je soutiens pour vous, et ceux de Laodicée, et tous ceux qui n\'ont pas vu mon visage en la chair,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'afin que leurs cœurs soient consolés, étant fortement unis dans la charité, et mis en possession de toutes les richesses de la certitude de l\'intelligence, afin de connaître le mystère du Dieu de Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'dans lequel sont cachés tous les trésors de la sagesse et de la connaissance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Je parle ainsi afin que personne ne vous égare par de beaux discours;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'car, tout en étant encore absent quant à la chair, je suis néanmoins avec vous par l\'esprit, me réjouissant à la vue de votre bon ordre et de la solidité de votre foi en Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Ainsi donc, conformément à la manière dont vous avez reçu Christ Jésus le seigneur, conduisez-vous comme étant unis à lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'enracinés et édifiés en lui, et affermis par la foi selon l\'enseignement que vous avez reçu, la possédant en abondance avec des actions de grâces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Prenez garde qu\'il n\'y ait personne qui fasse de vous sa proie par le moyen de la philosophie et d\'une vaine erreur, selon la tradition des hommes, selon les rudiments du monde, et non selon Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'car c\'est en lui qu\'habite corporellement toute la plénitude de la Divinité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'et vous êtes par lui pleinement remplis, lui qui est le chef de toute domination et de toute autorité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'lui, en qui aussi vous avez été circoncis par une circoncision qui n\'a pas été faite manuellement, par le dépouillement du corps de la chair, par la circoncision de Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'ayant été ensevelis avec lui dans le baptême; c\'est encore en lui, et avec lui, que vous êtes ressuscités par la foi en la puissance de Dieu qui l\'a ressuscité des morts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'ainsi que vous, qui étiez morts par vos fautes et par l\'incirconcision de votre chair. Il nous a vivifiés avec lui, en nous faisant grâce pour toutes nos fautes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'après avoir effacé l\'obligation qui nous rendait débiteurs des commandements, laquelle subsistait contre nous, et Il l\'a fait disparaître en la clouant à la croix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'après avoir dépouillé les dominations et les autorités; et Il les a données en spectacle en triomphant ouvertement d\'elles par ce moyen.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Que personne donc ne vous juge en ce qui concerne le manger et le boire, ou au sujet d\'une fête, ou d\'une néoménie, ou d\'un sabbat,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'ce qui est une ombre des choses futures, tandis que le corps est à Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Que personne ne vous frustre à son gré du prix, au nom de l\'humilité et du culte des anges, tandis que, se livrant à ses visions, il est enflé d\'un vain orgueil par ses dispositions charnelles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'et ne s\'attache pas au chef, duquel tout le corps, rendu bien compact par l\'assistance des nerfs et des muscles, tire l\'accroissement que Dieu donne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Si vous êtes morts avec Christ aux rudiments du monde, pourquoi, comme si vous viviez encore dans le monde, vous impose-t-on les prescriptions suivantes:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, '« Ne prends point, ne goûte point, ne touche point, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'lesquelles tendent toutes à corrompre, quand on les pratique selon les commandements et les enseignements humains,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'qui, possédant, il est vrai, un renom de sagesse, en raison d\'un culte arbitraire et d\'une humilité dus au mépris du corps, non en raison d\'aucun mérite, ne servent qu\'à satisfaire la chair?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Si donc vous êtes ressuscités avec Christ, cherchez les choses d\'en haut, là où Christ est assis à la droite de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'intéressez-vous aux choses d\'en haut, non à celles qui sont sur la terre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'car vous êtes morts, et votre vie est cachée avec Christ en Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'lorsque Christ aura été manifesté, lui qui est notre vie, alors, vous aussi, vous serez manifestés avec lui dans la gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Faites donc mourir les membres qui sont sur la terre: l\'impudicité, l\'impureté, la luxure, la mauvaise convoitise, et la cupidité qui est une idolâtrie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'toutes choses, à cause desquelles survient la colère de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'C\'est en elles que, vous aussi, vous avez marché naguère, lorsque vous viviez au milieu de ces choses;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'mais, maintenant, vous aussi, vous avez rejeté toutes ces choses: colère, emportement, malice, calomnie, langage grossier, les éloignant de votre bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'N\'usez pas de mensonge les uns envers les autres, ayant dépouillé le vieil homme avec ses actions,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'et vous étant revêtus du nouveau qui est renouvelé, quant à la connaissance, selon l\'image de Celui qui l\'a créé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'et où il n\'y a ni Grec ni Juif, ni circoncision ni incirconcision, ni Barbare ni Scythe, ni esclave ni libre, mais où Christ est tout et en tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Revêtez-vous donc, comme des élus de Dieu, des saints, des bien-aimés, d\'entrailles compatissantes, de bonté, d\'humilité, de mansuétude, de longanimité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'vous supportant les uns les autres, et vous pardonnant réciproquement, si l\'un a quelque motif de se plaindre de l\'autre; de même que le seigneur vous a pardonné, faites-en autant vous-mêmes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'mais par-dessus tout cela revêtez-vous de la charité, ce qui est le lien de la perfection.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Et que la paix de Christ, à laquelle vous avez été aussi appelés en corps, règne dans vos cœurs; et devenez reconnaissants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Que la parole de Christ habite richement en vous; vous instruisant et vous exhortant les uns les autres en toute sagesse, par des psaumes, des hymnes et des chants spirituels, chantant en vos cœurs à Dieu sous l\'influence de la grâce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Et, quoi que ce soit que vous fassiez, en parole ou en œuvre, faites tout au nom du seigneur Jésus, en rendant par lui à Dieu le Père des actions de grâces.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Femmes, soyez soumises à vos maris, comme il convient dans le seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Maris, aimez vos femmes, et ne vous aigrissez pas contre elles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Enfants, obéissez à vos parents en tous points, car cela est bienséant dans le seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Pères, ne tourmentez pas vos enfants, afin qu\'ils ne se découragent point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Esclaves, obéissez en tous points à vos maîtres selon la chair, non avec une soumission extérieure comme pour plaire aux hommes, mais avec simplicité de cœur, craignant le seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'quoi que ce soit que vous fassiez, travaillez de cœur, comme pour le Seigneur, non pour des hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'sachant que c\'est du seigneur que vous recevrez la rétribution de l\'héritage; asservissez-vous à Christ le Seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'car celui qui commet l\'injustice en portera la peine, et il n\'y a pas d\'acception de personnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Maîtres, accordez à vos esclaves ce qui est juste et équitable, sachant que, vous aussi, vous avez un Maître dans le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Persévérez dans la prière, y veillant avec actions de grâces,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'priant en même temps aussi pour nous, afin que Dieu nous ouvre une porte pour notre parole, afin d\'annoncer le mystère de Dieu, (à cause de qui je suis aussi dans les chaînes),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'afin que je le manifeste comme il faut que je parle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Conduisez-vous avec sagesse envers ceux du dehors, mettant bien le temps à profit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Que votre parole soit toujours accompagnée de grâce, assaisonnée de sel, pour savoir comment il faut répondre à chacun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Vous serez informés de ce qui me concerne par Tychique, le frère bien-aimé, mon fidèle agent, et mon compagnon d\'esclavage dans l\'œuvre du seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'que je vous ai envoyé, précisément afin que vous fussiez instruits de l\'état de nos affaires, et qu\'il consolât vos cœurs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'avec Onésime, le fidèle et bien-aimé frère, qui est des vôtres. Ils vous informeront de tout ce qui se passe ici.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Aristarque, mon compagnon de captivité, vous salue, ainsi que Marc le cousin de Barnabas, au sujet duquel vous avez reçu des ordres, (s\'il vient chez vous, accueillez-le),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'et aussi Jésus, surnommé Justus; ce sont les seuls d\'entre les circoncis qui ont travaillé avec moi pour le royaume de Dieu, et ils ont été pour moi un réconfort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Épaphras, l\'esclave de Christ Jésus, qui est des vôtres, vous salue; il lutte constamment pour vous dans ses prières, afin qu\'étant parfaits et pleinement persuadés, vous demeuriez soumis à toute volonté de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'car je lui rends le témoignage qu\'il a de grands soucis pour vous, ainsi que pour ceux qui sont à Laodicée, et à Hiérapolis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Lucas, le médecin bien-aimé, vous salue, ainsi que Démas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Saluez les frères qui sont à Laodicée, et Nympha, et l\'assemblée qui se tient chez elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Puis, quand cette lettre aura été lue chez vous, faites en sorte qu\'elle soit aussi lue dans l\'église des Laodicéens, et que, de votre côté, vous lisiez celle de Laodicée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'et dites à Archippe: « Fais attention au ministère que tu as reçu dans le Seigneur, afin de le bien remplir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'La salutation de la main de moi, Paul: Souvenez-vous de mes chaînes. Que la grâce soit avec vous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paul, et Silvanus, et Timothée, à l\'église des Thessaloniciens en Dieu le Père et dans le seigneur Jésus-Christ: Que la grâce et la paix vous soient données!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Nous rendons à Dieu de constantes actions de grâces pour vous tous, faisant mention de vous dans nos prières,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'nous rappelant sans cesse l\'œuvre de votre foi, et le travail de votre charité, et la persévérance de votre espérance en notre seigneur Jésus-Christ, devant Dieu notre Père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'connaissant, frères bien-aimés de Dieu, votre élection,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'car notre Évangile ne vous a pas été prêché seulement en paroles, mais aussi avec puissance, et avec l\'esprit saint, et avec une pleine persuasion, comme vous savez quels nous avons été parmi vous à cause de vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'et vous-mêmes vous avez été nos imitateurs et ceux du seigneur, ayant reçu la parole, au milieu d\'une grande tribulation, avec joie et avec l\'esprit saint,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'en sorte que vous avez été un modèle pour tous les fidèles de Macédoine et d\'Achaïe.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Car c\'est de chez vous que la parole du Seigneur a retenti, non seulement en Macédoine et en Achaïe, mais qu\'en tout lieu la foi que vous avez en Dieu s\'est fait connaître, en sorte qu\'il n\'est pas nécessaire que vous en disiez rien;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'car eux-mêmes racontent, en ce qui vous concerne, ce qu\'a été notre arrivée parmi vous, et comment vous vous êtes détournés des idoles vers Dieu, pour servir le Dieu vivant et véritable,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'et pour attendre des cieux Son fils qu\'il a ressuscité des morts, Jésus qui nous délivre de la colère à venir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Vous-mêmes, en effet, vous savez, mes frères, que notre arrivée parmi vous n\'a pas été sans efficace;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'mais, après avoir auparavant souffert et avoir été maltraités à Philippes, comme vous le savez, nous avons pris assurance en notre Dieu pour vous annoncer, au milieu d\'une grande lutte, l\'évangile de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Notre prédication n\'a, en effet, ni l\'erreur ni l\'impureté pour origine, ni la ruse pour objet,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'mais, comme Dieu nous a jugés dignes de nous confier l\'Evangile, nous parlons en conséquence, non pour plaire aux hommes, mais à Dieu qui juge nos cœurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Jamais, en effet, comme vous le savez, nous n\'avons usé de paroles flatteuses, ni de prétextes intéressés, Dieu en est témoin;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'nous n\'avons pas davantage recherché une gloire d\'origine humaine, ni auprès de vous, ni auprès de personne, quoique nous eussions pu nous imposer comme apôtres de Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'mais, au contraire, nous avons vécu en toute simplicité au milieu de vous. Comme une nourrice prend soin de ses propres enfants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'de même, dans notre tendresse pour vous, nous voulions vous faire part non seulement de l\'évangile de Dieu, mais encore de nos propres vies, parce que vous nous étiez devenus chers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Vous vous rappelez, en effet, frères, notre labeur et notre peine; c\'est en travaillant jour et nuit, afin de n\'être à charge à aucun de vous, que nous avons prêché parmi vous l\'évangile de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Vous êtes témoins, ainsi que Dieu, de la manière pieuse, juste, et irréprochable, dont nous avons agi envers vous qui croyez,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'puisque vous savez que, comme un père le fait pour ses propres enfants, nous avons exhorté, et encouragé, et conjuré chacun de vous');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'de se conduire d\'une manière digne de Dieu, qui vous appelle à entrer dans Son propre royaume et dans Sa gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Et c\'est pourquoi, nous aussi, nous rendons sans cesse des actions de grâces à Dieu, de ce qu\'ayant accueilli la parole de Dieu que nous vous avons fait entendre, vous l\'avez reçue, non comme une parole d\'hommes, mais, ainsi qu\'elle l\'est vraiment, comme une parole de Dieu, laquelle aussi déploie son efficace en vous qui croyez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'En effet, frères, vous êtes devenus les imitateurs des églises de Dieu qui sont en Christ Jésus dans la Judée, car, vous aussi, vous avez eu à souffrir, de la part de vos propres compatriotes, les mêmes souffrances qu\'elles ont elles-mêmes endurées de la part des Juifs,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'qui, ayant aussi fait mourir le seigneur Jésus et les prophètes, et nous ayant persécutés, et déplaisant à Dieu, et étant hostiles à tous les hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'nous empêchent de parler aux Gentils afin qu\'ils soient sauvés, en sorte qu\'ils mettent constamment le comble à leurs péchés. Mais la colère a fini par les atteindre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Pour nous, frères, après avoir été séparés un instant de vous, de visage et non de cœur, nous avons cherché, avec d\'autant plus d\'ardeur, à satisfaire notre vif désir de voir votre visage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'c\'est pourquoi nous avons voulu, je parle de moi, Paul, nous rendre à deux reprises auprès de vous, et Satan nous en a empêché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Qui sera en effet notre espérance, ou notre joie, ou notre couronne de glorification, si vous ne l\'êtes aussi devant notre seigneur Jésus lors de son avènement?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Car c\'est vous qui êtes notre gloire et notre joie!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'C\'est pourquoi, n\'y tenant plus, nous avons jugé bon d\'être laissé seul à Athènes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'et nous avons envoyé Timothée, notre frère et notre coopérateur dans l\'évangile de Christ, pour qu\'il vous fortifiât, et qu\'il vous exhortât dans l\'intérêt de votre foi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'afin qu\'aucun de vous ne se laisse troubler par les tribulations présentes; car vous savez vous-mêmes que c\'est à cela que nous sommes destinés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Et en effet, lorsque nous étions auprès de vous, nous vous prédisions que nous aurions à souffrir la tribulation, comme cela a eu lieu, et comme vous le savez.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'C\'est pourquoi, moi aussi n\'y tenant plus, j\'ai envoyé afin de savoir ce qui en était de votre foi, craignant que le tentateur ne vous eût tentés et que notre travail ne fût devenu inutile.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Mais, Timothée étant récemment revenu vers nous d\'auprès de vous, et nous ayant donné de bonnes nouvelles sur votre foi et votre charité, et sur ce que vous conservez un bon et constant souvenir de nous, désirant nous voir comme nous désirons aussi vous voir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'nous avons ainsi, frères, été consolés en ce qui vous concerne, au milieu de toute notre épreuve et de toute notre tribulation, grâce à votre foi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'car maintenant nous vivons, si vous demeurez fermes dans le Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Car comment pouvons-nous rendre à Dieu assez d\'actions de grâces pour nous-mêmes, à cause de toute la joie que nous éprouvons à votre sujet devant notre Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'priant jour et nuit outre mesure, afin de voir votre visage et de réparer les imperfections de votre foi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Mais que Dieu Lui-même notre Père, et notre Seigneur Jésus, aplanissent notre route pour aller à vous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Quant à vous, que le Seigneur vous fasse multiplier et abonder en charité les uns envers les autres, et envers tous, comme nous-mêmes envers vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'pour affermir vos cœurs, et les rendre irréprochables en sainteté, devant Dieu notre Père, lors de l\'avènement de notre seigneur Jésus avec tous ses saints.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Au reste, frères, nous vous prions et nous vous exhortons dans le Seigneur Jésus, que, conformément à ce que vous avez appris de nous sur la manière dont il faut vous conduire et plaire à Dieu, comme en effet vous le faites, nous vous exhortons, dis-je, que vous le fassiez toujours plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Vous savez en effet quels ordres nous vous avons donnés au nom du Seigneur Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'car ce que Dieu veut, c\'est votre sanctification; c\'est que vous vous absteniez de l\'impudicité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'c\'est que chacun de vous sache jouir de son propre vase dans la sanctification et l\'honnêteté,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'et non avec une convoitise passionnée, comme les Gentils qui ne connaissent pas Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'c\'est qu\'il ne commette point de transgressions, ni ne fasse tort à son frère sur ce point; car le Seigneur punit toutes ces choses, comme nous vous en avons aussi prévenus, et comme nous vous l\'avons attesté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'En effet, ce n\'est pas à l\'impureté que Dieu nous a appelés, mais à la sanctification;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'par conséquent celui qui rejette ceci ne rejette pas un homme, mais Dieu qui vous donne Son esprit saint.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Quant à l\'amour fraternel, nous n\'avions pas besoin de vous en écrire; car vous êtes vous-mêmes instruits de Dieu à vous aimer les uns les autres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'et c\'est en effet ce que vous faites aussi pour tous les frères qui sont dans la Macédoine entière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'Mais nous vous exhortons, frères, à le faire toujours plus, et à mettre votre amour-propre à demeurer en paix, et à faire vos propres affaires, et à travailler de vos mains comme nous vous l\'avons commandé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'afin que vous vous conduisiez convenablement à l\'égard de ceux du dehors, et que vous n\'ayez besoin de personne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Or nous ne voulons pas, frères, que vous soyez dans l\'ignorance en ce qui concerne ceux qui sont morts, afin que vous ne vous affligiez pas comme les autres qui n\'ont pas d\'espérance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'car, si nous croyons que Jésus est mort et qu\'il est ressuscité, de même Dieu ramènera aussi par Jésus, pour être avec Lui, ceux qui sont morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Nous vous déclarons en effet, selon une parole du seigneur, que, nous autres vivants, qui sommes laissés pour l\'avènement de Jésus, nous ne devancerons certainement pas ceux qui sont morts,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'car le Seigneur lui-même, à un cri de commandement, à la voix d\'un archange, et au son de la trompette de Dieu, descendra du ciel, et les morts qui sont en Christ ressusciteront d\'abord;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'ensuite nous autres vivants, qui sommes laissés, nous serons tous enlevés avec eux sur des nuées, à la rencontre du seigneur dans l\'air, et nous serons ainsi toujours avec le seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Consolez-vous donc, les uns les autres, par ces paroles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Quant à ce qui concerne les temps et les époques, frères, vous n\'avez pas besoin qu\'on vous en écrive;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'car vous savez parfaitement vous-mêmes que le jour du seigneur doit venir, comme un voleur pendant la nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Or, quand ils diront: « Paix et sûreté! » alors une perdition subite les surprendra, comme le mal d\'enfant la femme enceinte, et ils n\'échapperont certainement pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Mais, pour vous, frères, vous n\'êtes pas dans les ténèbres, pour que ce jour vous surprenne comme des voleurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'car vous êtes tous fils de la lumière et fils du jour. Nous n\'appartenons ni à la nuit, ni aux ténèbres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'ainsi donc ne sommeillons pas comme les autres, mais veillons et soyons sobres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'car ceux qui sommeillent sommeillent la nuit, et ceux qui s\'enivrent s\'enivrent la nuit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'mais nous, qui appartenons au jour, soyons sobres, ayant revêtu la cuirasse de la foi et de la charité, et, pour casque, l\'espérance du salut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'car Dieu ne nous a pas destinés à la colère, mais à l\'acquisition du salut, par notre seigneur Jésus');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'qui est mort pour nous, afin que, soit que nous veillions, soit que nous sommeillions, nous vivions tous avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'C\'est pourquoi consolez-vous les uns les autres, et édifiez-vous l\'un l\'autre, comme effectivement vous le faites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Toutefois nous vous prions, frères, de distinguer ceux qui travaillent parmi vous, et qui président sur vous dans le Seigneur, et qui vous avertissent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'et d\'avoir pour eux une charité sans bornes à cause de leur œuvre. Gardez la paix entre vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'toutefois nous vous y exhortons, frères: avertissez ceux qui vivent dans le désordre, consolez ceux qui sont découragés, supportez les faibles, soyez patients envers tous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'prenez garde que personne ne rende à personne mal pour mal, mais poursuivez toujours le bien, soit entre vous, soit à l\'égard de tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Réjouissez-vous toujours;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'priez sans cesse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'rendez pour toutes choses des actions de grâces; car telle est la volonté de Dieu en Christ Jésus à votre égard.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'N\'éteignez pas l\'Esprit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'ne méprisez pas les prophéties,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'mais examinez toutes choses, retenez ce qui est bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Abstenez-vous de toute espèce de mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Or, que le Dieu de paix Lui-même vous sanctifie tout entiers, et que tout votre être, l\'esprit, l\'âme, et le corps, soient conservés sans reproche lors de l\'avènement de notre seigneur Jésus-Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Celui qui vous appelle est fidèle, et c\'est Lui aussi qui le fera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Frères, priez aussi pour nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Saluez tous les frères par un saint baiser.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Je vous en adjure au nom du Seigneur: que cette lettre soit lue à tous les frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Que la grâce de notre Seigneur Jésus-Christ soit avec vous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paul, et Sylvanus, et Timothée, à l\'église des Thessaloniciens, en Dieu notre Père et dans le seigneur Jésus-Christ:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'que la grâce et la paix vous soient données par Dieu le Père et par le seigneur Jésus-Christ!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Nous devons rendre de constantes actions de grâces à Dieu à votre sujet, frères, comme il est juste, parce que votre foi prend un grand accroissement, et que la charité de chacun de vous tous, les uns pour les autres, s\'augmente toujours plus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'en sorte que nous-mêmes nous nous glorifions à propos de vous parmi les églises de Dieu, à cause de votre persévérance et de votre foi au milieu de toutes vos persécutions et des tribulations auxquelles vous êtes en butte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'ce qui est un présage du juste jugement de Dieu qui vous déclarera dignes de Son royaume, pour lequel, vous aussi, vous souffrez;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'si du moins il est juste, de la part de Dieu, de rétribuer par la persécution ceux qui vous persécutent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'et par la délivrance vous, qui êtes persécutés, et nous-mêmes aussi, lors de la révélation du Seigneur Jésus, venant du ciel avec les anges de sa puissance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'entouré d\'une flamme de feu, pour punir ceux qui ne connaissent pas Dieu, et ceux qui n\'obéissent pas à l\'évangile de notre Seigneur Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'lesquels subiront comme châtiment une perdition éternelle, loin de la face du seigneur et de la gloire de sa force,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'lorsqu\'il sera venu pour être, en ce jour-là, glorifié dans ses saints et admiré dans tous ceux qui auront cru, car le témoignage que nous avons porté devant vous a été cru.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'C\'est en vue de cela aussi que nous adressons pour vous de constantes prières, afin que notre Dieu vous juge dignes de Son appel, et qu\'il accomplisse avec puissance toute disposition de bien faire, et l\'œuvre de la foi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'afin que le nom de notre seigneur Jésus soit glorifié en vous, et vous en lui, selon la grâce de notre Dieu et du Seigneur Jésus-Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Mais nous vous prions, frères, en ce qui concerne l\'avènement du seigneur Jésus-Christ, et notre réunion à lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'de ne pas vous laisser tout aussitôt jeter hors de votre bon sens, ni effrayer, soit par une inspiration, soit par des paroles ou une lettre qui nous seraient attribuées, comme si le jour du Seigneur était arrivé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Que personne ne vous égare d\'aucune manière, car, tant que la défection n\'aura pas eu lieu, et que n\'aura pas été révélé l\'homme de l\'iniquité, le fils de la perdition,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'l\'adversaire et celui qui s\'élève au-dessus de tout ce qui est appelé Dieu ou adoré, en sorte qu\'il s\'assied dans le sanctuaire de Dieu, se proclamant lui-même Dieu...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Ne vous souvenez-vous pas que, lorsque j\'étais encore parmi vous, je vous disais ces choses?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Et maintenant vous connaissez ce qui fait obstacle, afin qu\'il ne soit révélé qu\'en son temps;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'car le mystère de l\'iniquité déploie déjà son efficace, attendant seulement qu\'ait disparu celui qui fait obstacle pour le moment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Et alors sera révélé l\'inique, que le Seigneur détruira par le souffle de sa bouche, et qu\'il anéantira par l\'apparition de son avènement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'lui, dont l\'avènement est accompagné, par la puissance de Satan, de toute espèce de miracles, et de signes, et de prodiges mensongers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'et de toute espèce d\'erreur née de l\'injustice, pour ceux qui périssent parce qu\'ils n\'ont pas reçu l\'amour de la vérité pour être sauvés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Et c\'est pour cela que Dieu leur envoie une efficace d\'égarement, afin qu\'ils croient au mensonge,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'pour que tous ceux qui n\'ont pas cru à la vérité, mais qui ont pris plaisir à l\'injustice, soient jugés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Mais, pour nous, nous devons rendre de constantes actions de grâces à Dieu à votre sujet, frères bien-aimés du seigneur, parce que Dieu vous a choisis comme prémices pour le salut, par la sanctification de l\'esprit et la foi en la vérité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'ce à quoi Il vous a appelés par notre Évangile, afin que vous entriez en possession de la gloire de notre seigneur Jésus-Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Ainsi donc, frères, demeurez fermes, et retenez les traditions que nous vous avons enseignées, soit de bouche, soit par lettre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Cependant, que notre Seigneur Christ Jésus, et Dieu notre Père, qui nous a aimés et qui nous a donné par Sa grâce une consolation éternelle et une bonne espérance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'consolent vos cœurs, et vous affermissent en tout bonne œuvre et en toute bonne parole!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Au reste, frères, priez pour nous, afin que la parole du seigneur coure, et soit glorifiée comme elle l\'est parmi vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'et afin que nous soyons préservés des hommes déréglés et pervers, car tous n\'ont pas la foi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'mais le Seigneur, qui est fidèle, vous affermira et vous garantira du mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Cependant nous avons, en ce qui vous concerne, la confiance dans le seigneur, que vous avez fait, et que vous faites, et que vous ferez ce que nous ordonnons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'mais que le Seigneur dirige vos cœurs vers l\'amour de Dieu et vers la persévérance de Christ!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Or, nous vous ordonnons, frères, au nom du Seigneur Jésus-Christ, de vous éloigner de tout frère qui vit dans le désordre, et non selon la tradition que vous avez reçue de nous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'vous-mêmes vous savez, en effet, comment il faut nous imiter, car nous n\'avons pas vécu parmi vous dans le désordre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'et ce n\'est pas gratuitement que nous avons mangé le pain de personne, mais au prix de fatigues et de labeurs, en travaillant nuit et jour, afin de n\'être à charge à aucun de vous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'non, parce que nous n\'en avons pas le droit, mais afin de nous donner nous-mêmes en exemple à vous, pour que vous nous imitiez;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'car, lorsque nous étions parmi vous, nous vous donnions aussi cet ordre: si quelqu\'un ne veut pas travailler, qu\'il ne mange pas non plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Nous apprenons, en effet, qu\'il en est parmi vous qui vivent dans le désordre, qui ne travaillent point, mais qui s\'occupent de choses inutiles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'c\'est à ceux de cette espèce, que nous ordonnons et que nous recommandons, au nom du Seigneur Jésus-Christ, de travailler avec tranquillité pour manger leur propre pain.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Quant à vous, frères, ne vous découragez pas de bien faire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'mais si quelqu\'un n\'obéit pas à votre injonction, signalez-le par votre lettre; n\'ayez aucun rapport avec lui, afin qu\'il se réforme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'et ne le traitez pas en ennemi, mais avertissez-le comme un frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Or, que le Seigneur de la paix vous donne lui-même la paix en tout temps, de toute manière! Que le Seigneur soit avec vous tous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'La salutation est de la main de moi, Paul, ce qui sert de signe dans toute lettre; c\'est ainsi que j\'écris.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Que la grâce de notre Seigneur Jésus-Christ soit avec vous tous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paul, apôtre de Jésus-Christ, selon le mandat de Dieu notre sauveur, et de Christ Jésus notre espérance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'à Timothée, mon enfant légitime en la foi: Grâce, miséricorde, paix, de par Dieu le Père, et Christ Jésus notre seigneur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Conformément à l\'exhortation que, en partant pour la Macédoine, je t\'ai adressée de demeurer à Éphèse, afin d\'enjoindre à certains hommes de ne pas enseigner d\'autres doctrines,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'et de ne point s\'attacher à des fables et à des généalogies sans fin, lesquelles favorisent les discussions plutôt que le plan de Dieu qui fait l\'objet de la foi...');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Mais le but de cette injonction, c\'est une charité issue d\'un cœur pur, d\'une bonne conscience et d\'une foi sincère,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'toutes choses dont se sont éloignés, pour se jeter dans des chimères, certains hommes');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'qui ont la prétention d\'être des docteurs de la loi, bien qu\'ils ne comprennent ni ce qu\'ils disent, ni de quoi ils se tiennent pour assurés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Or nous savons que la loi est bonne, pourvu qu\'on l\'observe légalement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'en sachant bien que ce n\'est pas pour le juste qu\'elle est faite, mais pour les criminels et les rebelles, les impies et les pécheurs, les sacrilèges et les profanes, les parricides, les meurtriers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'les impudiques, les infâmes, les marchands d\'hommes, les menteurs, les parjures, et pour toute autre infraction au salutaire enseignement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'selon la bonne nouvelle de la gloire du Dieu bienheureux, que je suis chargé d\'annoncer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Je rends grâce à celui qui m\'a fortifié, Christ Jésus notre seigneur, de ce qu\'il m\'a jugé fidèle, puisqu\'il m\'a appelé au ministère,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'moi, qui auparavant étais un calomniateur, un persécuteur, et un oppresseur; mais il m\'a été fait miséricorde, parce que, dans mon incrédulité, j\'avais agi par ignorance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'et la grâce de notre seigneur a surabondé avec la foi et la charité qui sont en Christ Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'C\'est une vérité certaine et digne de toute créance, que Christ Jésus est venu dans le monde pour sauver les pécheurs, dont je suis le premier;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'mais si, néanmoins, il m\'a été fait miséricorde, c\'est afin qu\'en moi le premier Christ Jésus manifestât toute sa patience, pour que je servisse d\'exemple à ceux qui devaient croire en lui pour la vie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Or, qu\'au Roi des siècles, incorruptible, invisible, seul Dieu, soient rendus l\'honneur et la gloire pour les siècles des siècles! Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'L\'injonction que je t\'adresse, Timothée, mon enfant, conformément aux prophéties antérieurement faites à ton sujet, c\'est de combattre, d\'après elles, le bon combat,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'en retenant la foi et une bonne conscience, dont certains hommes s\'étant débarrassés, ils ont fait naufrage quant à la foi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'du nombre desquels sont Hyménée et Alexandre que j\'ai livrés à Satan, afin qu\'ils apprennent à ne plus blasphémer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'J\'exhorte donc avant tout, que l\'on adresse des oraisons, des prières, des supplications, et des actions de grâces pour tous les hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'pour les rois, et pour tous ceux qui exercent le commandement, afin que nous menions une vie paisible et tranquille en toute piété et en toute honnêteté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'C\'est là une chose bonne et agréable aux yeux de Dieu notre sauveur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'qui veut que tous les hommes soient sauvés et qu\'ils parviennent à la connaissance de la vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Car il n\'y a qu\'un seul Dieu, et il n\'y a aussi entre Dieu et les hommes qu\'un seul médiateur, l\'homme Christ Jésus');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'qui s\'est donné lui-même comme une rançon pour tous, au temps convenable,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'ce que j\'ai été chargé d\'annoncer, moi, qui suis prédicateur et apôtre (je dis la vérité, je ne mens point), et docteur des Gentils en esprit et en vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Je veux donc que les hommes prient en tout lieu, en élevant des mains pures, sans colère ni dispute,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'et que, de même, les femmes se parent avec pudeur et modestie d\'un costume décent, non de tresses et d\'or, ou de perles, ou de vêtements précieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'mais comme il sied à des femmes qui font profession de piété par de bonnes œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Que la femme se laisse tranquillement instruire avec une parfaite soumission;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'mais je ne permets à une femme ni d\'enseigner, ni de dominer sur l\'homme, je veux, au contraire, qu\'elle demeure tranquille,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'car Adam a été formé le premier, puis ensuite Ève;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'et ce n\'est pas Adam qui a été séduit, mais c\'est la femme qui, séduite, s\'est rendue coupable de transgression;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'toutefois elle sera sauvée par l\'enfantement, à condition de persévérer avec sagesse dans la foi, la charité et la sanctification.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'C\'est une vérité certaine que, si quelqu\'un aspire à l\'épiscopat, il désire une œuvre excellente;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'il faut donc que l\'évêque soit irréprochable, mari d\'une seule femme, sobre, modéré, rangé, hospitalier, capable d\'enseigner,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'ni buveur, ni emporté, mais doux, n\'aimant ni les querelles ni l\'argent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'gouvernant bien sa propre maison, tenant ses enfants dans la soumission avec un parfait respect;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '(mais si quelqu\'un ne sait pas gouverner sa propre maison, comment prendra-t-il soin de l\'église de Dieu?),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'n\'étant pas un nouveau converti, de peur qu\'enflé d\'orgueil il ne donne prise au jugement du Diable,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'mais il faut qu\'il reçoive aussi un bon témoignage de ceux du dehors, afin qu\'il ne donne prise ni aux invectives, ni aux pièges du Diable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'De même il faut que les diacres soient honnêtes, sans duplicité, point adonnés aux excès du vin, ni désireux d\'un gain sordide,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'adhérant, avec une conscience pure, au mystère de la foi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'mais il faut qu\'eux aussi soient examinés d\'abord; ensuite qu\'on les admette comme diacres, s\'ils sont irrépréhensibles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'De même, il faut que les femmes soient honnêtes, point médisantes, sobres, et fidèles en toutes choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Que les diacres soient maris d\'une seule femme, qu\'ils gouvernent bien leurs enfants et leurs propres maisons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'car ceux qui ont bien rempli cet office acquièrent pour eux-mêmes une bonne place, et une grande assurance fondée sur la foi en Christ Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Je t\'écris ces choses, tout en espérant te rejoindre avant peu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'mais, si je tarde, afin que tu saches comment il faut se comporter dans la maison de Dieu, qui est l\'église du Dieu vivant, la colonne et le fondement de la vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Et, de l\'aveu général, grand est le mystère de la piété: Celui qui a été manifesté en chair, a été justifié par l\'esprit, il s\'est montré aux anges, il a été prêché parmi les nations, on a cru en lui dans le monde, il a été enlevé dans la gloire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'mais l\'Esprit dit expressément que, dans les derniers temps, certains hommes se détacheront de la foi, pour s\'attacher à des esprits séducteurs et à des doctrines de démons,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'grâce à l\'hypocrisie de faux docteurs, qui portent dans leur propre conscience la marque de la flétrissure,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'qui interdisent le mariage, prescrivent de s\'abstenir d\'aliments que Dieu a créés afin qu\'ils fussent pris avec actions de grâces par les fidèles et ceux qui connaissent la vérité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'car tout ce que Dieu a créé est bon, et rien ne doit être rejeté quand on le prend avec actions de grâces,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'puisque tout est sanctifié par la parole de Dieu et par la prière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'En rappelant ces choses aux frères tu seras un bon ministre de Christ Jésus, nourri des paroles de la foi et du bon enseignement que tu t\'es attaché à suivre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'mais repousse les fables profanes et extravagantes, et exerce-toi à la piété;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'en effet, l\'exercice corporel n\'est utile qu\'à peu de chose, tandis que la piété est utile pour toutes choses, puisqu\'elle possède la promesse de la vie présente et de celle qui est à venir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'c\'est là une vérité certaine et digne de toute créance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'car c\'est pour cela que nous travaillons et que nous luttons, parce que nous avons mis notre espérance dans le Dieu vivant qui est le sauveur de tous les hommes, et principalement des fidèles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Voilà ce que tu dois prescrire et enseigner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Que personne ne méprise ta jeunesse, mais deviens un modèle pour les fidèles, en paroles, en conduite, en charité, en foi, en pureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Jusques à ce que j\'arrive, applique-toi à la lecture, à l\'exhortation, à l\'enseignement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Ne néglige point le don spirituel qui est en toi, lequel t\'a été donné par une prophétie avec l\'imposition des mains du collège des anciens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Occupe-toi de ces choses, donne-t\'y tout entier, afin que tes progrès soient manifestes pour tout le monde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'veille sur toi-même et sur l\'enseignement; persévères-y; car en agissant ainsi tu te sauveras toi-même ainsi que ceux qui t\'écoutent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'N\'accable pas de reproches le vieillard, mais parle-lui comme à un père, aux jeunes gens comme à des frères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'aux femmes âgées comme à des mères, aux jeunes femmes comme à des sœurs en toute pureté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Aie des égards pour les veuves, véritables veuves;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'mais si une veuve a des enfants ou des descendants, qu\'ils apprennent avant tout à exercer la piété envers leur propre maison, et à reconnaître les soins de leurs ascendants, car cela est agréable aux yeux de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Mais celle qui est véritablement veuve, et isolée, a mis son espérance en Dieu, et elle persévère dans les oraisons et les prières nuit et jour,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'tandis que celle qui s\'adonne aux plaisirs est morte, quoique vivante;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'voilà ce que tu dois aussi prescrire, afin qu\'elles soient irréprochables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Mais si quelqu\'un néglige les siens, et surtout ceux de sa famille, il a renié la foi et il est pire qu\'un infidèle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Qu\'une veuve ne soit portée sur le rôle, que si elle n\'a pas moins de soixante ans, si elle n\'a eu qu\'un seul mari,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'si elle se recommande par de bonnes œuvres, comme d\'avoir élevé ses enfants, exercé l\'hospitalité, lavé les pieds des saints, assisté les malheureux, pratiqué toute bonne œuvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Mais repousse les veuves plus jeunes, car, quand la volupté les détache de Christ, elles veulent se marier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'et elles encourent ainsi le blâme d\'avoir rompu leur premier engagement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'mais en outre elles apprennent encore, dans leur fainéantise, à courir les maisons, et elles ne sont pas seulement fainéantes, mais de plus bavardes et intrigantes, disant ce qui ne convient pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Je veux donc que les plus jeunes se marient, aient des enfants, gouvernent leur maison, ne donnent point à l\'adversaire l\'occasion de les calomnier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'car quelques-unes déjà ont déserté pour suivre Satan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Si une fidèle a des veuves, qu\'elle les assiste, et que l\'église n\'en ait pas la charge afin qu\'elle puisse assister les véritables veuves.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Que les anciens qui président bien soient honorés d\'une double rémunération, surtout ceux qui s\'appliquent à la prédication et à l\'enseignement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'car l\'Écriture dit: « Tu n\'emmusèleras point le bœuf qui foule le grain, » et l\'ouvrier est digne de son salaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Ne reçois pas d\'accusation contre un ancien, à moins qu\'elle ne repose sur le témoignage de deux ou trois personnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'mais ceux qui pèchent, réprimande-les devant tous les autres, afin que ces derniers aussi en conçoivent de la crainte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Je t\'adjure devant Dieu, devant Christ Jésus, et devant les anges élus, d\'observer cette règle sans prévention, et de ne rien faire par suggestion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'N\'impose précipitamment les mains à personne, et ne te rends pas complice des péchés des autres. Conserve-toi toi-même pur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'ne continue plus à ne boire que de l\'eau, mais use d\'un peu de vin, à cause de ton estomac et de tes fréquentes incommodités.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Les péchés de certains hommes sont évidents, avant même tout jugement, tandis que chez d\'autres ils ne se manifestent qu\'ensuite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'de même aussi les bonnes actions sont évidentes, celles qui ne le sont pas d\'abord ne peuvent rester secrètes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Que tous les esclaves qui sont sous le joug envisagent leurs propres maîtres comme dignes de tout respect, afin que le nom de Dieu et l\'enseignement ne soient l\'objet d\'aucune calomnie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'et, d\'un autre côté, que ceux qui ont des fidèles pour maîtres ne les méprisent pas parce que ce sont des frères, mais qu\'ils les servent d\'autant mieux que ceux qui profitent de leur bonne conduite sont des fidèles et des bien-aimés. Voilà ce que tu dois enseigner et prescrire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Si quelqu\'un enseigne une autre doctrine, et n\'adhère pas aux saines paroles de notre seigneur Jésus-Christ et à l\'enseignement conforme à la piété,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'il est enflé d\'orgueil, ne sachant rien, mais étant maladivement épris de disputes et de querelles de mots, d\'où résultent l\'envie, les querelles, les calomnies, les mauvais soupçons,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'les vaines discussions d\'hommes dont l\'intelligence est corrompue, et qui sont privés de la vérité, parce qu\'ils envisagent la piété comme une source de revenu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Il est vrai que la piété, accompagnée de contentement, est une grande source de revenu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'car nous n\'avons rien apporté en ce monde, parce que nous n\'en pouvons non plus rien emporter;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'mais si nous avons de quoi vivre et nous couvrir, cela nous suffira;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'tandis que ceux qui veulent s\'enrichir tombent dans la tentation, et dans des pièges, et dans une foule de convoitises insensées et funestes qui précipitent les hommes dans la ruine et la perdition;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'car l\'amour de l\'argent est la racine de tous les maux; possédés de cette passion, certains hommes se sont détournés de la foi et se sont transpercés eux-mêmes de douleurs infinies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Mais, pour toi, ô homme de Dieu, fuis ces choses, mais recherche la justice, la piété, la foi, la charité, le support, la douceur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'combats le bon combat de la foi; saisis la vie éternelle à laquelle tu as été appelé, et pour laquelle tu as fait cette belle confession devant de nombreux témoins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Je t\'enjoins, devant Dieu qui appelle toutes choses à l\'existence, et devant Christ Jésus qui a prononcé devant Ponce Pilate cette belle confession,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'd\'observer le commandement qui t\'est fait, sans tache et sans reproche, jusques à l\'apparition de notre seigneur Jésus-Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'que manifestera, au temps convenable, le bienheureux et unique Souverain, le roi de ceux qui règnent, et le seigneur de ceux qui commandent,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'le seul qui possède l\'immortalité, qui habite une lumière inaccessible, que nul homme n\'a vu ni ne peut voir, auquel appartiennent l\'honneur et la puissance éternelle. Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Enjoins aux riches dans le présent siècle de ne point s\'enorgueillir, et de ne pas non plus fonder leur espoir sur l\'incertitude de la richesse, mais sur Dieu qui nous procure richement toutes choses pour notre usage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'enjoins-leur de faire de bonnes actions, d\'être riches en bonnes œuvres, d\'être généreux, libéraux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 's\'amassant, pour l\'avenir, un trésor établi sur un fondement solide, afin d\'entrer en possession de la véritable vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'O Timothée, garde le dépôt, en évitant les bavardages profanes et la polémique de la fausse science,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'dont font profession certains hommes qui se sont ainsi éloignés de la foi. Que la grâce soit avec vous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paul, apôtre de Jésus-Christ par la volonté de Dieu, pour annoncer la promesse de la vie qui est en Christ Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'à Timothée, mon enfant bien-aimé: Grâce, miséricorde, paix, de par Dieu le Père et Christ Jésus notre seigneur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'J\'offre des actions de grâces à Dieu, auquel je rends un culte héréditaire avec une conscience pure, de ce que je conserve de toi un perpétuel souvenir, dans mes prières nuit et jour;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'désirant te revoir quand je me rappelle tes larmes, afin d\'être rempli de joie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'me souvenant de la foi sincère qui est en toi, et qui habita d\'abord dans ton aïeule Lois, puis dans ta mère Eunice, et qui, j\'en suis persuadé, habite aussi en toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'C\'est pourquoi je t\'invite à ranimer le don de Christ, qui est en toi par l\'imposition de mes mains;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'car Dieu ne nous a pas donné un esprit de timidité, mais de puissance, de charité et de sagesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Ne rougis donc point du témoignage de notre seigneur, ni de moi son prisonnier, mais prends ta part des souffrances pour l\'Évangile, selon la puissance de Dieu');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'qui nous a sauvés, et qui nous a adressé un saint appel, non en raison de nos œuvres, mais suivant Son propre décret, et selon la grâce qui nous a été donnée en Christ Jésus avant les temps éternels,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'mais qui a été maintenant manifestée par l\'apparition de notre sauveur Christ Jésus, qui, d\'un côté, a détruit la mort, et qui, de l\'autre, a mis en lumière la vie et l\'immortalité par l\'Évangile,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'pour lequel j\'ai été établi prédicateur, apôtre et docteur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'ce qui est cause que j\'endure aussi ces souffrances; mais je n\'en rougis point, car je sais en Qui j\'ai cru, et je suis persuadé qu\'il peut, par Sa puissance, garder mon dépôt pour ce jour-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Retiens avec foi, et avec la charité qui est en Christ Jésus, ce modèle des vérités salutaires que tu m\'as entendu prêcher;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'garde le bon dépôt par l\'esprit saint qui habite en nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Tu sais que tous ceux qui sont en Asie m\'ont abandonné; parmi eux se trouvent Phygelle et Hermogène.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Que le seigneur se montre miséricordieux envers la famille d\'Onésiphore; car il m\'a souvent réconforté, et il n\'a point rougi de mes chaînes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'mais, au contraire, dès son arrivée à Rome, il m\'a cherché avec plus d\'empressement que je ne pensais, et il m\'a trouvé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'que le seigneur lui accorde d\'obtenir miséricorde de la part du seigneur en ce jour-là; d\'ailleurs tu sais mieux que personne tous les services qu\'il a rendus dans Éphèse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Toi donc, mon enfant, fortifie-toi dans la grâce qui est en Christ Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'et, ce que tu m\'as entendu dire devant plusieurs témoins, confie-le à des hommes fidèles, qui soient capables d\'en instruire aussi d\'autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Prends ta part des souffrances comme un bon soldat de Christ Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'aucun homme qui porte les armes ne se laisse entraver par les occupations de la vie ordinaire, afin de plaire à celui qui a rassemblé l\'armée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'de même encore nul athlète n\'est couronné, s\'il n\'a lutté selon les règles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'c\'est le laboureur qui travaille, qui, le premier, doit avoir sa part des fruits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Réfléchis à ce que je dis; car le seigneur te donnera l\'intelligence de toutes choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Rappelle-toi Jésus-Christ ressuscité des morts, issu de la postérité de David, selon mon évangile,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'dans la prédication duquel je souffre jusques à être chargé de chaînes comme un malfaiteur; mais la parole de Dieu n\'est point enchaînée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'c\'est pourquoi je supporte tout à cause des élus, afin qu\'eux aussi obtiennent le salut qui est en Christ Jésus, avec une gloire éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'C\'est une vérité certaine. En effet, si nous mourons avec lui, nous vivrons aussi avec lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'si nous persévérons, nous régnerons aussi avec lui; si nous le renions, lui aussi, il nous reniera;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'si nous sommes infidèles, lui, il demeure fidèle, car il ne peut se renier lui-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Voilà ce que tu dois remémorer, en prenant le seigneur à témoin. Abstiens-toi des disputes de mots; cela ne sert de rien, c\'est la ruine des auditeurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Empresse-toi de te mettre à la disposition de Christ, comme un ouvrier qui n\'a point à rougir et qui se conforme fidèlement à la parole de la vérité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'mais évite les bavardages profanes, car ceux qui s\'y livrent avanceront de plus en plus dans l\'impiété,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'et leur parole rongera comme une gangrène; parmi eux se trouvent Hyménée et Philète,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'qui se sont éloignés de la vérité, prétendant que la résurrection a déjà eu lieu; et ils détruisent la foi de quelques personnes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Néanmoins le fondement que Dieu a posé demeure ferme, portant pour sceau ces paroles: « Le Seigneur connaît ceux qui Lui appartiennent, » et: Que quiconque prononce le nom du seigneur se détourne de l\'injustice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Or, dans une grande maison, il n\'y a pas seulement des ustensiles d\'or et d\'argent, mais aussi de bois et de terre; tandis que les uns sont destinés à un noble emploi, les autres le sont à un emploi ignoble.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Si donc quelqu\'un se purifie lui-même pour n\'être pas de ceux-ci, il sera un ustensile destiné à un noble emploi, sanctifié, utile à son possesseur, préparé pour tout bon usage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Eh bien, fuis les convoitises juvéniles, mais recherche la justice, la foi, la charité, et la paix avec tous ceux qui aiment le Seigneur d\'un cœur pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Repousse, au contraire, les discussions folles et déréglées, sachant qu\'elles engendrent des querelles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'or, il ne faut point que l\'esclave du Seigneur se querelle, mais qu\'il soit doux avec tout le monde, capable d\'enseigner, patient,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'redressant avec mansuétude les opposants, afin de voir si Dieu ne leur donnera peut-être point de se repentir, pour arriver à la connaissance de la vérité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'et s\'ils ne redeviendront point sages, en se dégageant des pièges du diable, par qui ils ont été capturés pour faire sa volonté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Or, sachez que, dans les derniers temps, surgiront des circonstances difficiles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'car les hommes seront égoïstes, épris de l\'argent, fanfarons, superbes, blasphémateurs, rebelles à leurs parents, ingrats, impies,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'insensibles, déloyaux, calomniateurs, intempérants, impitoyables, ennemis des gens de bien,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'traîtres, emportés, enflés d\'orgueil, plus amis du plaisir que de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'ayant l\'apparence de la piété, mais en ayant renié la puissance. Ceux-là aussi, repousse-les;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'car c\'est de leurs rangs que sortent ceux qui se glissent dans les familles et captivent des femmelettes chargées de péchés, entraînées par des convoitises et des voluptés de tout genre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'toujours occupées à apprendre, et ne pouvant jamais arriver à la connaissance de la vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Mais, comme Jannès et Jambrès résistèrent à Moïse, de même aussi ces hommes résistent à la vérité, corrompus qu\'ils sont dans leur intelligence et réprouvés quant à la foi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'mais ils ne feront pas de plus grands progrès, car leur pensée deviendra évidente pour tout le monde, comme le fut aussi celle des premiers.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Quant à toi, tu t\'es attaché à suivre mon enseignement, ma conduite, ma résolution, ma foi, ma constance, ma patience,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'mes persécutions, mes souffrances, telles que je les ai endurées à Antioche, à Icône, à Lystres. A quelles persécutions n\'ai-je pas été en butte? Et le Seigneur m\'a délivré de toutes!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Mais tous ceux qui veulent vivre pieusement en Christ Jésus, seront aussi persécutés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Quant aux hommes méchants et aux imposteurs, ils iront de mal en pis, eux qui sont tout à la fois séducteurs et séduits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Pour toi, persévère dans ce que tu as appris et admis avec certitude, sachant de qui tu l\'as appris,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'et que, dès l\'enfance, tu connais les lettres sacrées qui peuvent te perfectionner pour le salut par la foi en Christ Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'toute écriture inspirée de Dieu étant utile pour instruire, pour reprendre, pour redresser, pour corriger selon la justice,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'afin que l\'homme de Dieu soit accompli et propre à toute bonne œuvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Je t\'en adjure devant Dieu, et devant Christ Jésus qui doit juger les vivants et les morts, tant au nom de son apparition qu\'au nom de son royaume:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'prêche la parole, insiste à propos et hors de propos, reprends, tance, exhorte avec toute sorte de patience et d\'instruction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Car il y aura un moment où ils ne souffriront plus l\'enseignement salutaire, mais où, selon leurs propres convoitises, ils se donneront une masse de docteurs, parce que leurs oreilles aiment à être flattées;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'et, tandis que, d\'un côté, ils les fermeront à la vérité, de l\'autre, ils se jetteront dans les fables.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Quant à toi, sois modéré à tous égards, endure les souffrances comme un bon soldat de Christ Jésus, fais l\'œuvre d\'un évangéliste, acquitte-toi parfaitement de ton ministère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Car, pour moi, je sers déjà de libation, et le moment de mon départ approche;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'j\'ai combattu le bon combat; j\'ai achevé la course; j\'ai gardé la foi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'du reste, la couronne de justice m\'est réservée; le seigneur, le juste juge, me l\'accordera en ce jour-là, et non seulement à moi, mais encore à tous ceux qui désirent son apparition.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Tâche de me rejoindre promptement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'car Démas m\'a abandonné par préférence pour le présent siècle, et il est parti pour Thessalonique, Crescens pour la Galatie, Tite pour la Dalmatie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Lucas est seul avec moi. Prends Marc pour l\'amener avec toi, car il m\'est utile pour le ministère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Quant à Tychique, je l\'ai envoyé à Éphèse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Apporte, quand tu viendras, le manteau que j\'ai laissé à Troas chez Carpus, ainsi que les livres, surtout les parchemins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Alexandre le fondeur m\'a témoigné beaucoup de malveillance (le seigneur lui rendra selon ses œuvres);');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'tiens-toi aussi en garde contre lui, car il s\'est fortement opposé à notre prédication.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Dans ma première défense personne ne m\'a assisté, mais tous m\'ont abandonné; que cela ne leur soit pas imputé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Mais c\'est le Seigneur qui m\'a assisté et qui m\'a fortifié, afin que par moi la prédication eût une pleine efficace, que tous les Gentils l\'entendissent, et que je fusse tiré de la gueule du lion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Le seigneur me garantira de toute mauvaise action, et il me sauvera pour m\'introduire dans son céleste royaume. A lui soit la gloire aux siècles des siècles! Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Salue Prisca et Aquilas, et la famille d\'Onésiphore;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Eraste est resté à Corinthe; quant à Trophime, ils l\'ont laissé malade à Milet.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Tâche de venir avant l\'hiver. Euboulos te salue, ainsi que Pudens, et Linus, et Claudia, et tous les frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Que le seigneur Jésus soit avec ton esprit! Que la grâce soit avec vous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paul, — esclave de Dieu, et apôtre de Christ Jésus pour la foi des élus de Dieu, et pour la connaissance de la vérité qui s\'accorde avec la piété,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'lesquelles se fondent sur l\'espérance de la vie éternelle, que Dieu, qui ne ment point, nous a promise avant les temps éternels,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'tandis qu\'à l\'époque convenable Il a manifesté Sa parole, par la prédication qui m\'a été confiée selon le mandat de Dieu notre sauveur, —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'à Tite, mon enfant légitime par une foi commune: Grâce, miséricorde, paix de par Dieu le Père, et Christ Jésus notre sauveur!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Si je t\'ai laissé eu Crète, c\'est afin que tu presses les réformes qui restent à faire et que, dans chaque ville, tu établisses des anciens, aux conditions que je t\'ai prescrites:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'être irréprochable, mari d\'une seule femme, avoir des enfants croyants qui ne puissent être accusés de vivre dans la débauche, ou qui soient indisciplinés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'car il faut que l\'évêque soit irréprochable, comme économe de Dieu, qu\'il ne soit ni insolent, ni colère, ni buveur, ni emporté, ni désireux d\'un gain sordide,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'mais hospitalier, ami des gens de bien, sage, juste, pieux, tempérant,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'attaché à la parole qui est fidèlement conforme à la doctrine, afin qu\'il soit capable, soit de consoler ceux qui sont en butte aux tribulations, soit de réfuter les objectants.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'En effet il y a beaucoup de gens indisciplinés, de discoureurs frivoles, et de séducteurs (surtout ceux de la circoncision),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'auxquels il faut fermer la bouche; ce sont eux qui bouleversent des familles entières en enseignant ce qui ne convient pas, en vue d\'un gain sordide.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'L\'un d\'entre eux, qui a été leur propre prophète, a dit: « Les Crétois sont toujours menteurs, de méchantes bêles, des ventres paresseux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Ce témoignage est vrai. C\'est pourquoi reprends-les vertement, afin qu\'ils aient une foi saine,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'et qu\'ils ne s\'attachent point à des fables juives et à des commandements d\'hommes qui se détournent de la vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Tout est pur pour ceux qui sont purs, mais, pour ceux qui sont souillés et infidèles, rien n\'est pur; or, leur intelligence et leur conscience sont souillées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'ils professent de connaître Dieu, mais par leurs œuvres ils Le renient, étant abominables, rebelles, et incapables d\'aucune bonne œuvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Quant à toi, proclame ce qui est conforme à l\'enseignement salutaire:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Que les vieillards doivent être sobres, dignes, sages, attachés à une foi saine, à la charité, à la patience:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Que les femmes âgées doivent de même avoir la tenue qui convient à des saints, n\'être ni médisantes, ni asservies par les excès du vin; qu\'elles doivent enseigner ce qui est bien,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'afin d\'apprendre aux jeunes femmes à aimer leurs maris et leurs enfants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'à être sages, chastes, bonnes ménagères, soumises à leurs propres maris, afin que la parole de Dieu ne soit point calomniée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Exhorte de même les jeunes gens à être sages,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'te montrant toi-même en toutes choses comme un modèle de bonnes œuvres, et faisant preuve dans l\'enseignement de pureté, de dignité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'd\'une doctrine saine et irrépréhensible, afin que l\'adversaire ait la confusion de ne pouvoir dire aucun mal de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Que les esclaves soient soumis à leurs propres maîtres, qu\'ils leurs plaisent en toutes choses, qu\'ils ne soient point récalcitrants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'qu\'ils ne détournent rien, mais qu\'ils se montrent à tous égards honnêtes et fidèles, afin de faire honneur, sous tous les rapports, à l\'enseignement de Dieu notre sauveur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Elle a été en effet manifestée, la grâce de Dieu, source du salut pour tous les hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'et elle nous apprend, après que nous avons renoncé à l\'impiété et aux convoitises mondaines, à vivre dans le présent siècle sagement, justement et pieusement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'en attendant la réalisation de notre bienheureuse espérance et l\'apparition de la gloire de notre grand Dieu et sauveur Jésus-Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'qui s\'est donné lui-même pour nous, afin de nous racheter de toute iniquité, et de s\'acquérir, en le purifiant, un peuple qui lui appartînt, zélé pour les bonnes œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Enseigne ces choses, exhorte, et reprends avec tout pouvoir; que personne ne te dédaigne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Mais invite-les à être soumis envers les puissances et les autorités, obéissants et prêts à toute bonne œuvre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'à ne calomnier personne, à n\'être point querelleurs, à se montrer équitables, à témoigner toute espèce de mansuétude à tous les hommes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'car nous aussi, nous étions naguère insensés, rebelles, égarés, asservis à des convoitises et à des voluptés de tout genre, vivant dans la malice et dans l\'envie, dignes de haine et nous haïssant les uns les autres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'mais, quand la bonté et l\'humanité de Dieu notre sauveur a été manifestée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'ce n\'est point en conséquence d\'œuvres conformes à la justice que nous eussions faites nous-mêmes, mais en vertu de Sa propre miséricorde, qu\'il nous a sauvés par l\'ablution régénératrice, et par un renouvellement de l\'esprit saint');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'qu\'il a richement répandu sur nous par Jésus-Christ notre sauveur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'afin que, après avoir été justifiés par Sa grâce, nous devenions, en espérance, héritiers de sa vie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'C\'est une vérité certaine, et je veux que tu donnes ces choses pour assurées, afin que ceux qui ont cru en Dieu s\'occupent à pratiquer de bonnes œuvres; voilà ce qui est bon et utile aux hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'tandis que tu dois éviter les discussions folles, les généalogies, les querelles, et les disputes relatives à la loi; car elles sont inutiles et vaines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Abandonne l\'homme hérétique après une ou deux admonestations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'sachant que les gens de cette espèce sont pervertis, et qu\'ils pèchent tout en se condamnant eux-mêmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Lorsque je t\'aurai envoyé Artémas ou Tychique, empresse toi de venir me rejoindre à Nicopolis, car c\'est là que j\'ai décidé de passer l\'hiver.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Préside avec soin au départ de Zénas le docteur de la loi, et d\'Apollos, afin qu\'il ne leur manque rien;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'mais il faut que les nôtres aussi apprennent à pratiquer de bonnes œuvres, lorsqu\'il s\'agit de besoins pressants, afin de n\'être pas sans porter de fruits. Tous ceux qui sont avec moi te saluent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Saluez ceux qui nous aiment dans la foi. Que la grâce soit avec vous tous!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paul, prisonnier de Christ Jésus, et le frère Timothée, au bien-aimé Philémon, notre coopérateur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'et à la sœur Apphia, et à Archippe notre compagnon de combat, et à l\'église qui se réunit dans ta maison:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'que la grâce et la paix vous soient données par Dieu notre Père et par le Seigneur Jésus-Christ!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'J\'adresse à mon Dieu de constantes actions de grâces, en faisant mention de toi dans mes prières,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'étant instruit de la charité et de la foi que tu témoignes envers le Seigneur Jésus, et envers tous les saints,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'afin que la communication de ta foi devienne efficace pour Christ, en faisant reconnaître en nous toute espèce de bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'J\'ai, en effet, éprouvé une grande joie et une grande consolation à cause de ta charité, car grâce à toi, frère, le cœur des saints a été tranquillisé.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'C\'est pourquoi, quoique j\'aie en Christ une assurance assez grande pour t\'enjoindre ce qui est convenable');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'au nom de la nécessité, je préfère l\'exhortation. C\'est dans cet esprit que, comme Paul, âgé, et maintenant en outre prisonnier de Christ Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'je t\'adresse une exhortation à propos de l\'enfant que j\'ai engendré dans les chaînes, Onésime,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'qui t\'a été naguère nuisible, mais qui maintenant t\'est utile ainsi qu\'à moi, et que je t\'ai renvoyé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'lui, mes propres entrailles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'que je voulais retenir auprès de moi, afin que, à ta place, il me rendît service dans les chaînes que je porte pour l\'évangile,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'mais je n\'ai rien voulu faire sans ton avis, afin que le bien que tu fais ne paraisse point le résultat de la nécessité, mais d\'une volonté libre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Peut-être, en effet, n\'a-t-il été momentanément séparé de toi, qu\'afin que tu le retrouves pour l\'éternité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'non plus comme un esclave, mais, bien plus qu\'un esclave, comme un frère bien-aimé, de moi surtout, et à bien plus forte raison de toi, soit dans la chair, soit dans le seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Si donc tu me regardes comme étant étroitement uni à toi, accueille-le comme moi-même,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'et s\'il t\'a fait quelque tort, ou s\'il a contracté envers toi quelque dette, mets-les à mon compte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'C\'est moi, Paul, qui ai écrit de ma propre main; c\'est moi qui te rembourserai; pour ne pas te rappeler que c\'est aussi de ta propre personne que tu es encore mon débiteur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Oui, frère, c\'est moi qui voudrais tirer de toi ce profit dans le Seigneur; tranquillise mon cœur en Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'C\'est parce que je compte sur ton obéissance, que je t\'ai écrit, sachant que tu feras encore au delà de ce que je demande;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'mais en outre prépare-moi un logement, car j\'espère que, grâce à vos prières, je vous serai rendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Epaphras, mon compagnon de captivité, te salue en Christ Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'ainsi que Marc, Aristarque, Démas et Luc, mes coopérateurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Que la grâce de notre Seigneur Jésus-Christ soit avec votre esprit!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Après avoir autrefois, à plusieurs reprises et de plusieurs manières, parlé à nos pères par les prophètes, Dieu, dans la période finale des jours actuels, nous a parlé par le Fils,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'qu\'il a fait héritier de toutes choses, par lequel Il a aussi créé l\'univers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'et qui, étant un rayonnement de Sa gloire et une empreinte de Sa substance, et soutenant toutes choses par la parole de sa puissance, s\'est assis, après avoir fait une purification des péchés, à la droite de la Majesté dans les hauts lieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'étant devenu d\'autant supérieur aux anges, qu\'il avait hérité un nom plus excellent qu\'eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Car auquel des anges a-t-Il jamais dit: « Tu es Mon fils, c\'est Moi qui t\'ai engendré aujourd\'hui? » Et derechef: « Moi, Je serai pour lui un père, et lui sera pour Moi un fils? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Puis encore, quand Il introduit le premier-né dans le monde, Il dit: « Et que tous les anges de Dieu l\'adorent! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Et, tandis qu\'il dit aux anges: « Celui qui fait de Ses anges des vents et de Ses ministres une flamme de feu, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Il dit au contraire au Fils: « Ton trône, ô Dieu, subsiste pour l\'éternité; » et: « C\'est le sceptre de rectitude que le sceptre de son royaume;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'tu as aimé la justice, et tu as haï l\'iniquité; c\'est pourquoi, ô Dieu, ton Dieu t\'a oint, plus que tes pairs, d\'une huile d\'allégresse; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'et: « C\'est Toi, Seigneur, qui, au commencement, as fondé la terre, et les cieux sont des œuvres de Tes mains;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'pour eux ils périront, tandis que Toi, Tu subsistes; et tous ils vieilliront comme un vêtement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'et Tu les replieras comme une couverture, comme un vêtement, et ils seront changés; mais Toi, Tu es le même, et Tes années ne finiront point. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Enfin, auquel des anges a-t-Il jamais dit: « Assieds-toi à Ma droite, jusques à ce que J\'aie fait de tes ennemis un marchepied pour tes pieds? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Est-ce qu\'ils ne sont pas tous des esprits au service de Dieu, chargés de remplir un ministère pour ceux qui doivent hériter du salut?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'C\'est pourquoi nous devons faire d\'autant plus attention à ce que nous avons entendu, de peur que nous ne périssions;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'car, si la parole proclamée par des anges a été irréfragable, et si toute transgression et toute désobéissance ont reçu une juste rétribution,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'comment nous-mêmes échapperons-nous, si nous négligeons un si grand salut? Un salut qui, d\'abord proclamé par le seigneur, nous a été annoncé d\'une manière irréfragable par ceux qui l\'ont entendu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Dieu y joignant Son témoignage par des signes, et des prodiges, et des miracles divers, et des communications de l\'esprit saint, selon Sa volonté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'En effet ce n\'est point à des anges qu\'il a soumis le monde nouveau dont nous parlons;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'mais quelqu\'un a quelque part rendu ce témoignage: « Qu\'est-ce que l\'homme, pour que Tu te souviennes de lui? Ou le fils de l\'homme, pour que Tu en prennes soin?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Tu l\'as un peu rabaissé au-dessous des anges; Tu l\'as couronné de gloire et d\'honneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Tu lui as soumis toutes choses, les mettant sous ses pieds, » En effet, en soumettant toutes choses, Il n\'a rien laissé qui ne lui fût soumis, et toutefois nous ne voyons pas encore maintenant que toutes choses lui soient soumises.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Mais, celui qui a été un peu rabaissé au-dessous des anges, Jésus, nous le contemplons couronné de gloire et d\'honneur à cause de la mort qu\'il a soufferte, lui qui a dû, par la grâce de Dieu, goûter la mort pour tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Car il était digne de Celui, à cause de qui et par qui toutes choses subsistent, puisqu\'il voulait conduire à la gloire des fils nombreux, d\'amener à la perfection par des souffrances le prince de leur salut.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'En effet celui qui sanctifie et ceux qui sont sanctifiés relèvent tous d\'un Seul, c\'est pourquoi il ne rougit pas de les appeler frères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'lorsqu\'il dit: « J\'annoncerai Ton nom à mes frères, je Te célébrerai au milieu de l\'assemblée; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'et derechef: « Pour moi je me confierai en Lui; » et encore: « Me voici, moi, et les enfants que Dieu m\'a donnés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Ainsi donc, puisque les enfants ont en partage le sang et la chair, lui aussi y a de même participé, afin que, par la mort, il anéantît celui qui possède la puissance de la mort, c\'est-à-dire le diable,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'et qu\'il délivrât tous ceux qui, par crainte de la mort, étaient, durant toute leur vie, tenus en esclavage;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'car ce n\'est certes point à des anges qu\'il porte secours, mais c\'est à la postérité d\'Abraham;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'en sorte qu\'il devait être rendu semblable en toutes choses à ses frères, afin de pouvoir être compatissant, et de devenir, dans le service de Dieu, un grand prêtre pour faire l\'expiation des péchés du peuple;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'car c\'est pour avoir été lui-même tenté dans ce qu\'il a souffert, qu\'il peut secourir ceux qui sont tentés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Ainsi donc, frères saints, vous auxquels est adressé un appel céleste, portez vos regards sur l\'envoyé et le grand prêtre de notre confession, Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'qui est fidèle à Celui qui l\'a créé, comme l\'a été aussi Moïse, dans Sa maison.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'En effet il a été jugé d\'autant plus digne d\'une plus grande gloire que Moïse, que celui qui s\'est construit une maison possède une plus grande gloire que la maison même;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'car toute maison est construite par quelqu\'un, mais celui qui a construit toutes choses, c\'est Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'et, tandis que Moïse a été fidèle dans toute Sa maison, comme un serviteur chargé de rendre témoignage à ce qui devait être proclamé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Christ l\'est comme un fils à la tête de sa propre maison. C\'est nous qui sommes sa maison, si nous persistons à être assurés et glorieux de notre espérance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'C\'est pourquoi, — selon ce que dit l\'esprit saint: « Aujourd\'hui, si vous entendez Sa voix');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'n\'endurcissez pas vos cœurs, comme lors de la rébellion, le jour de la tentation dans le désert,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'où vos pères l\'ont essayé par manière d\'épreuve, et ils avaient vu Mes œuvres pendant quarante ans!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'C\'est pourquoi J\'ai été courroucé contre cette génération, et J\'ai dit: Toujours leur cœur s\'égare. Mais ils n\'ont point connu Mes voies!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Voici le serment que J\'ai fait dans Ma colère: Jamais ils n\'entreront dans Mon repos! —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Prenez garde, frères, qu\'il n\'y ait peut-être chez quelqu\'un de vous un cœur gâté par l\'incrédulité jusques à abandonner le Dieu vivant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'mais exhortez-vous réciproquement tous les jours, tant que l\'on peut dire « aujourd\'hui, » afin qu\'aucun de vous ne soit endurci par la fourberie du péché;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'car nous sommes devenus participants de Christ, si du moins nous persistons fermement jusques à la fin dans notre conviction première,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'selon qu\'il est dit: « Aujourd\'hui, si vous entendez Sa voix, n\'endurcissez pas vos cœurs, comme lors de la rébellion. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Car quels sont ceux qui, après avoir entendu, se sont rebellés? Est-ce que ce ne sont pas tous ceux que Moïse avait fait sortir d\'Egypte?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Et contre lesquels fut-Il courroucé pendant quarante ans? N\'est-ce pas contre ceux qui avaient péché, et dont les membres jonchèrent le désert?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Et contre lesquels fit-Il le serment qu\'ils n\'entreraient jamais dans Son repos, si ce n\'est contre ceux qui avaient désobéi?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Et nous voyons qu\'ils ne purent y entrer à cause de leur incrédulité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Craignons donc, puisque la promesse d\'entrer dans Son repos subsiste encore, que quelqu\'un de vous ne paraisse y avoir renoncé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'car, nous aussi, nous avons reçu cette bonne nouvelle comme ceux-là, mais la parole qu\'ils ont ouïe ne leur a servi de rien, parce qu\'ils ne se sont pas intimement unis par la foi à ceux qui l\'ont écoutée:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'En effet, nous qui avons cru, nous entrons dans le repos, selon qu\'il dit: « Voici le serment que J\'ai fait dans Ma colère: Jamais ils n\'entreront dans Mon repos, » quoique Ses œuvres fussent accomplies depuis la fondation du monde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'car, touchant le septième jour, Il s\'exprime quelque part ainsi: « Et Dieu se reposa le septième jour de toutes Ses œuvres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'et Il dit, d\'un autre côté, dans ce passage-là: « Jamais ils n\'entreront dans Mon repos. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Puis donc qu\'on doit encore s\'attendre à ce que quelques-uns y entrent, et puisque ceux qui avaient, les premiers, reçu la bonne nouvelle n\'y sont pas entrés à cause de leur désobéissance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Il fixe derechef un certain jour, « aujourd\'hui, » en disant dans la personne de David, après un si long espace de temps, comme Il l\'a dit ci-dessus: « Aujourd\'hui, si vous entendez Sa voix, n\'endurcissez pas vos cœurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'en effet, si Josué leur avait donné le repos, Il n\'aurait certes pas, après cela, parlé d\'un autre jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Ainsi un repos sabbatique attend encore le peuple de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'car celui qui entre dans Son repos, se repose, lui aussi, de ses œuvres, comme Dieu s\'est reposé des siennes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Appliquons-nous donc à entrer dans ce repos, afin que personne ne donne, en tombant, le même exemple de désobéissance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'car la parole de Dieu est vivante, et évidente, et plus tranchante que toute épée à deux tranchants, et si pénétrante qu\'elle divise l\'âme et l\'esprit, jusques dans les jointures et les moelles, et elle juge les pensées et les dispositions du cœur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'et aucune créature ne lui est cachée; mais toutes choses sont nues et découvertes aux yeux de Celui avec qui nous avons affaire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Ayant donc un grand prêtre suprême qui a traversé les cieux, Jésus le fils de Dieu, restons fermement attachés à notre confession;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'car nous n\'avons pas un grand prêtre qui ne peut pas compatir à nos faiblesses, mais il a au contraire été tenté en toutes choses d\'une manière semblable, sans pécher;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'approchons-nous donc, avec une ferme assurance, du trône de la grâce, afin de recevoir, par la miséricorde et la grâce, un secours opportun.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'En effet, tout grand prêtre, pris du milieu des hommes, est chargé pour les hommes du service de Dieu, afin de présenter des offrandes et des sacrifices pour les péchés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'lui, qui peut montrer de l\'indulgence pour ceux qui sont ignorants et égarés, puisqu\'il est lui-même aussi enveloppé de faiblesse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'et c\'est à cause de cette faiblesse qu\'il doit offrir pour lui-même, aussi bien que pour le peuple, des oblations pour les péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Et personne ne s\'approprie de lui-même cette dignité, mais il y est appelé de Dieu, comme le fut aussi Aaron;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'de même aussi, ce n\'est pas à lui-même que Christ a attribué la gloire d\'avoir été fait grand prêtre, mais à Celui qui lui a dit: « Tu es Mon fils, c\'est Moi qui t\'ai engendré aujourd\'hui; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'comme Il dit encore dans un autre passage: « Tu es prêtre pour l\'éternité selon le rang de Melchisédec; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'lui, qui, dans les jours de sa chair, après avoir présenté, avec de grands cris et avec larmes, des prières et des supplications à Celui qui pouvait le sauver de la mort, et après avoir été exaucé à cause de sa piété,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'a appris, quoiqu\'il fût fils, l\'obéissance par ce qu\'il a souffert,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'et qui, après avoir été amené à la perfection, est devenu, pour tous ceux qui lui obéissent, l\'auteur d\'un salut éternel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'ayant reçu de Dieu le titre de grand prêtre selon le rang de Melchisédec.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Nous avons là-dessus beaucoup de choses à vous dire, et elles sont difficiles à expliquer, parce que vous êtes devenus paresseux pour entendre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Et, en effet, vous, qui, depuis le temps, devriez, être des maîtres, vous avez derechef besoin que quelqu\'un vous enseigne les rudiments des oracles de Dieu, et vous êtes devenus tels, que vous avez besoin de lait et non de nourriture solide;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'car quiconque en est encore au lait est sans expérience de la parole de justice; car il est un enfant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'tandis que la nourriture solide est pour les hommes faits, pour ceux qui, grâce à la capacité qu\'ils ont acquise, ont les sens exercés à discerner ce qui est bien et ce qui est mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'C\'est pourquoi, laissant, de côté les éléments de la parole de Christ, aspirons à l\'état d\'homme fait, sans jeter de nouveau, comme fondement de la renonciation aux œuvres mortes et de la foi en Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'la doctrine des ablutions, de l\'imposition des mains, de la résurrection des morts et du jugement éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Et c\'est là ce que nous ferons, si du moins Dieu le permet;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'car il est impossible que ceux qui ont été une fois illuminés, et qui ont goûté le don céleste, et qui sont devenus participants de l\'esprit saint,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'et qui ont goûté la bonne parole de Dieu et les puissances de l\'âge nouveau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'et qui, ensuite, sont tombés, soient une seconde fois renouvelés pour éprouver de la repentance, eux qui crucifient de nouveau, à leur préjudice, et qui livrent à l\'ignominie le fils de Dieu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'En effet une terre qui a bu la pluie souvent tombée sur elle, et qui produit une herbe utile à ceux pour lesquels elle est aussi cultivée, participe à la bénédiction de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'tandis que si elle porte des épines et des chardons, elle est réprouvée, et elle est près de recevoir la malédiction qui a pour terme la destruction par le feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Mais, quoique nous parlions ainsi, nous comptons, bien-aimés, en ce qui vous concerne, sur quelque chose de mieux et qui aboutisse au salut;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'car Dieu est trop juste pour oublier votre travail, et l\'affection que vous avez témoignée pour Son nom, par les services que vous avez rendus et que vous rendez aux saints.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Nous désirons toutefois que chacun de vous montre jusques à la fin le même zèle pour arriver à la plénitude de l\'espérance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'afin que vous ne deveniez pas paresseux, mais qu\'au contraire vous deveniez les imitateurs de ceux qui, par la foi et la persévérance, héritent des promesses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'En effet, lorsqu\'il fit Sa promesse à Abraham, Dieu, qui ne pouvait prêter serment en prenant à témoin personne de plus grand, jura en se prenant lui-même à témoin,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'en disant: « Certes Je te bénirai abondamment, et en te donnant l\'accroissement Je te ferai prospérer abondamment. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Et ce fut ainsi, qu\'ayant persévéré, la promesse se réalisa pour lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Les hommes, en effet, prêtent serment en prenant à témoin Celui qui est plus grand qu\'eux, et le serment met fin pour eux à toute contradiction en confirmant leur déclaration.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Il en résulte que Dieu, voulant montrer avec plus d\'évidence aux héritiers de Sa promesse l\'immutabilité de Son décret, intervint par un serment,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'afin que, par deux faits immuables dans lesquels il est impossible que Dieu ait menti, nous ayons, nous qui nous sommes mis à l\'abri, un puissant encouragement à retenir ferme l\'espérance qui nous est offerte');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'et que nous possédons comme une ancre de l\'âme, sûre et solide, et qui pénètre au dedans du voile,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'là où Jésus est entré pour nous comme un précurseur, étant devenu pour l\'éternité grand prêtre selon le rang de Melchisédec.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'En effet, ce Melchisédec, roi de Salem, prêtre du Dieu très haut, — lui, qui, après qu\'il fut allé au-devant d\'Abraham lorsque celui-ci revenait de la défaite des rois, et qu\'il l\'eut béni,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'reçut aussi d\'Abraham une dîme prélevée sur tout, — lui, qui premièrement, d\'après l\'interprétation de son nom, est roi de justice, et ensuite, de plus, roi de Salem, c\'est-à-dire roi de paix, —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'lui, qui est sans père, sans mère, sans généalogie, — lui, qui n\'a ni commencement de temps, ni fin de vie, mais qui a été rendu semblable au fils de Dieu, — il demeure prêtre à perpétuité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Or considérez combien est grand ce personnage, auquel Abraham donna une dîme prise sur les prémices du butin, lui, le patriarche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Tandis que ceux des fils de Lévi qui exercent la prêtrise ont, d\'après la loi, l\'ordre de lever une dîme sur le peuple, c\'est-à-dire sur leurs frères, quoique ceux-ci soient issus des reins d\'Abraham,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'lui, qui ne tire point d\'eux sa généalogie, il a levé la dîme sur Abraham, et il a béni celui qui possédait les promesses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Or, il est absolument incontestable que c\'est l\'inférieur qui est béni par le supérieur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Et, tandis qu\'ici ce sont des hommes mortels qui perçoivent les dîmes, là, au contraire, c\'est quelqu\'un dont il est attesté qu\'il est vivant;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'et c\'est aussi, pour ainsi dire, sur Lévi, lui qui perçoit les dîmes, que, par l\'intermédiaire d\'Abraham, est levée la dîme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'car il était encore dans les reins de son père, quand Melchisédec vint au-devant de celui-ci.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Si donc la perfection eût été réalisée par la prêtrise lévitique, (car c\'est à celle-ci que se rapporte la loi donnée au peuple), il n\'eût pas encore été nécessaire que ce fût selon le rang de Melchisédec que s\'installât un autre prêtre, et qu\'il ne fût pas désigné selon le rang d\'Aaron;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'car, une fois la prêtrise changée, il en résulte nécessairement aussi un changement de loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Celui auquel s\'appliquent ces paroles appartient, en effet, à une autre tribu, dont aucun membre n\'a jamais fait le service de l\'autel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'car il est notoire que c\'est de Juda qu\'a surgi notre seigneur, tribu pour laquelle Moïse n\'a rien dit qui concernât les prêtres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Et cela devient encore plus évident, si l\'on remarque que c\'est à la ressemblance de Melchisédec que s\'installe un autre prêtre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'qui l\'est devenu, non pas selon la loi d\'un commandement charnel, mais selon la puissance d\'une vie impérissable;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'car voici le témoignage qui lui est rendu: « Tu es prêtre pour l\'éternité selon le rang de Melchisédec. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'En effet, tandis qu\'un commandement antérieur est abrogé, à cause de son impuissance et de son inefficacité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, '(car la loi n\'a rien amené à la perfection), il s\'introduit en revanche une espérance meilleure, grâce à laquelle nous nous approchons de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Et, en tant que cela n\'a pas eu lieu sans serment, — (');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'car, tandis que les autres sont devenus prêtres sans qu\'il y ait eu de serment, pour lui, il l\'est devenu avec un serment prêté par Celui qui lui dit: « Le Seigneur en a fait le serment, et Il ne s\'en repentira pas: Tu es prêtre pour l\'éternité »), —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Jésus est, par cela même, devenu le garant d\'une alliance d\'autant plus excellente.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Et, tandis que les autres ont formé une pluralité de prêtres, parce que la mort empêche la permanence,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'pour lui, comme il demeure pour l\'éternité, il possède la prêtrise indéfectible,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'en sorte qu\'il peut aussi sauver parfaitement ceux qui s\'approchent de Dieu par lui, car il est toujours vivant pour intercéder pour eux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'C\'est bien, en effet, un tel grand prêtre qui nous convenait: saint, innocent, sans souillure, séparé des pécheurs, et qui est devenu plus élevé que les cieux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'il n\'a pas journellement besoin, comme les grands prêtres, d\'offrir des sacrifices, d\'abord pour ses propres péchés, puis pour ceux du peuple; car ceci il l\'a fait une fois pour toutes en s\'offrant lui-même en sacrifice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'En effet, tandis que la loi institue, pour grands prêtres, des hommes pleins de faiblesse, la parole du serment, prêté après la loi, institue un Fils qui est parvenu à la perfection pour l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Mais le point capital de ce que nous disons, c\'est que nous possédons un grand prêtre tel, qu\'il s\'est assis à la droite du trône de la Majesté dans les cieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'comme ministre du sanctuaire et du véritable tabernacle qui a été dressé par le Seigneur, non par un homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'En effet tout grand prêtre est institué pour présenter des offrandes et des sacrifices, en sorte qu\'il était nécessaire que celui-ci eût aussi quelque chose à présenter.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Si donc il était sur la terre, il ne serait pas même prêtre, — puisque là se trouvent ceux qui présentent les offrandes selon la loi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'lesquels rendent un culte à une copie et à une ombre des choses qui sont dans le ciel, selon l\'oracle par lequel il fut répondu à Moïse, qui allait, construire le tabernacle: « Aie soin, dit-Il en effet, de tout exécuter selon le modèle qui t\'a été montré sur la montagne; » —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'mais maintenant il a obtenu un ministère bien supérieur, d\'autant plus qu\'il est médiateur d\'une alliance encore plus excellente, et dont la loi repose sur de bien meilleures promesses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'En effet, si cette première loi était irréprochable, il n\'y avait pas à chercher la place d\'une autre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'tandis que c\'est d\'un ton de reproche qu\'il leur dit: « Voici, des jours viennent, dit le Seigneur, où Je conclurai avec la maison d\'Israël et avec la maison de Juda une alliance nouvelle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'non plus comme l\'alliance que J\'ai faite avec leurs pères dans le temps où Je les pris par la main pour les faire sortir de la terre d\'Egypte, parce qu\'ils n\'ont pas persévéré dans Mon alliance, et que, de Mon côté, Je les ai négligés, dit le Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Car voici l\'alliance que Je ferai avec la maison d\'Israël, après ce temps-là, dit le Seigneur: Je mettrai Mes lois dans leur pensée, et Je les écrirai sur leurs cœurs, et Je serai leur Dieu, et ils seront Mon peuple;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'et ils n\'enseigneront plus chacun son concitoyen, et chacun son frère, en disant: Apprends à connaître le Seigneur, car tous Me connaîtront parmi eux, depuis le petit jusqu\'au grand,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'parce que Je me montrerai miséricordieux pour leurs injustices, et que Je ne me souviendrai absolument plus de leurs péchés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'En disant: « une nouvelle, » Il a frappé la première de décrépitude; or ce qui est décrépit et vieilli est près de disparaître.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Sans doute la première possédait un culte légitime et le sanctuaire terrestre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'En effet, un tabernacle avait été construit, (je parle du premier), dans lequel se trouvaient le candélabre, et la table, et le dépôt des pains, et l\'autel d\'or pour l\'encens; et qui est appelé le lieu saint;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'puis, au delà du second voile, un tabernacle qui est appelé le lieu très saint,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'renfermant l\'arche de l\'alliance entièrement recouverte d\'or, dans laquelle se trouvaient une cruche d\'or contenant la manne, la verge d\'Aaron qui avait bourgeonné, et les tables de l\'alliance;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'puis, au-dessus d\'elle, sont les chérubins de gloire qui ombragent le propitiatoire; autant d\'objets sur lesquels il n\'y a pas lieu de parler maintenant en détail.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Les choses étant ainsi disposées, les prêtres qui desservent le culte entrent en tout temps dans le premier tabernacle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'tandis que, dans le second, n\'entre qu\'une fois par an le grand prêtre seul, avec le sang dont il fait offrande pour lui-même et pour les transgressions du peuple;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'l\'Esprit Saint montrant par là que la route du sanctuaire n\'a pas encore été manifestée, tant que subsiste le premier tabernacle,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'qui est un symbole de l\'époque actuelle, d\'après lequel des offrandes et des sacrifices sont présentés qui ne peuvent point conduire à la perfection, en ce qui concerne la conscience, celui qui rend le culte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'mais qui, avec les aliments, les boissons et les diverses ablutions, sont seulement aussi des institutions charnelles imposées jusques à une époque de réformation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Mais Christ est survenu comme grand prêtre des biens accomplis, et c\'est en traversant le plus grand et le plus parfait tabernacle, qui n\'est pas fait de main d\'homme (c\'est-à-dire qui n\'appartient pas à cette création-ci),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'et en offrant, non pas le sang des boucs et des veaux, mais son propre sang, qu\'il est entré une fois pour toutes dans le sanctuaire, après avoir obtenu une rédemption éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'En effet, si le sang des boucs et des taureaux, et si la cendre d\'une vache dont on asperge ceux qui sont souillés, sanctifie suffisamment pour la purification de la chair,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'à combien plus forte raison le sang de Christ, qui, par un esprit éternel, s\'est offert lui-même à Dieu comme une victime immaculée, purifiera-t-il notre conscience des œuvres mortes, pour que vous rendiez un culte au Dieu vivant et vrai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Et c\'est pour cela qu\'il est médiateur d\'une nouvelle alliance, afin que, une mort ayant eu lieu pour la rédemption des transgressions commises sous la première alliance, ceux qui sont appelés voient se réaliser pour eux la promesse de l\'héritage éternel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'en effet, là où il y a un testament, il est nécessaire de constater la mort du testateur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'car, pour être valable, un testament suppose la mort, puisqu\'il n\'a aucune force tant que vit le testateur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'En sorte que, même la première alliance, n\'a pas été inaugurée sans effusion de sang;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'car, après que Moïse eut proclamé devant tout le peuple chaque commandement selon la teneur de la loi, il prit le sang des veaux et des boucs, avec de l\'eau, de la laine rouge et de l\'hysope, et il aspergea le livre et tout le peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'en disant: « Ceci est le sang de l\'alliance que Dieu vous a imposée; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'puis il aspergea également avec le sang le tabernacle et tous les ustensiles du culte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Et, d\'après la loi, presque tout est purifié par du sang, et sans effusion de sang il n\'y a pas de pardon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Il était donc nécessaire, puisque les copies des choses qui sont dans les cieux sont purifiées de cette manière, que les choses célestes elles-mêmes le fussent par des sacrifices bien supérieurs à ceux-là.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'En effet, ce n\'est pas dans un sanctuaire fait de main d\'homme, en imitation du véritable, que Christ est entré, mais dans le ciel même, afin de comparaître maintenant devant la face de Dieu pour nous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'et il n\'y est pas entré non plus pour s\'offrir lui-même souvent en sacrifice, comme le grand prêtre entre chaque année dans le sanctuaire avec un sang étranger;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'autrement il aurait fallu qu\'il souffrît souvent depuis la fondation du monde, tandis que maintenant, à l\'époque de la consommation des siècles, il a été manifesté une seule fois pour anéantir le péché par son sacrifice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Et, en tant qu\'il est imposé aux hommes de mourir une seule fois, puis après cela d\'être jugés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'de même aussi Christ, qui s\'est une seule fois offert en sacrifice pour enlever les péchés de plusieurs, se montrera une seconde fois, sans péché, à ceux qui l\'attendent avec foi pour être sauvés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'En effet, la loi ne possédant que l\'ombre des biens à venir, et non l\'image même des choses, ils ne peuvent jamais, par les mêmes sacrifices qu\'ils offrent perpétuellement chaque année, amener à la perfection ceux qui y prennent part;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'autrement, n\'aurait-on pas cessé de les offrir, puisque ceux qui rendent ce culte, une fois purifiés, n\'auraient plus eu aucune conscience de leurs péchés?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Mais, au contraire, ces sacrifices ramènent chaque année le ressouvenir des péchés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'car il est impossible que le sang des taureaux et des boucs enlève les péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'C\'est pourquoi, en entrant dans le monde, il dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, '« Tu n\'as voulu ni sacrifice ni offrande, mais Tu m\'as préparé un corps; Tu n\'as eu à gré ni les holocaustes ni les oblations pour le péché;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'alors j\'ai dit: Voici, je viens (dans le rouleau du livre il est question de moi) pour faire, ô Dieu, Ta volonté. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Il commence par dire: « Tu n\'as pas voulu et Tu n\'as point eu à gré les sacrifices, ni les offrandes, ni les holocaustes, ni les oblations pour le péché, » toutes choses qui se font selon la loi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'puis il ajoute: « Voici, je viens pour faire Ta volonté; » il abolit l\'un pour établir l\'autre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'c\'est grâce à cette volonté que nous avons été sanctifiés, par l\'offrande du corps de Jésus-Christ, une fois pour toutes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Et, tandis que tout grand prêtre officie chaque jour et offre souvent les mêmes sacrifices, qui ne peuvent jamais enlever les péchés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'celui-ci, au contraire, après avoir offert pour les péchés un seul sacrifice, s\'est assis pour toujours à la droite de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'où il continue d\'attendre que ses ennemis aient été mis comme un marchepied sous ses pieds.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'En effet, par une seule offrande, il a amené à la perfection pour toujours ceux qui sont sanctifiés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'C\'est d\'ailleurs ce que l\'Esprit Saint aussi nous atteste, car, après avoir dit:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, '« Voici l\'alliance que Je ferai avec eux après ce temps-là, » le Seigneur dit: « en mettant Mes lois dans leurs cœur; et Je les graverai dans leurs pensées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'et Je ne me souviendrai absolument plus de leurs péchés, ni de leurs iniquités; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'or, là où il y a pardon pour ces choses, il n\'y a plus d\'offrande à offrir pour le péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Pouvant donc, frères, grâce au sang de Jésus, compter avec une ferme assurance sur l\'entrée dans le sanctuaire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'qu\'il nous a ouverte, comme une route nouvelle et vivante au travers du voile, qui est sa chair,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'et ayant un prêtre suprême établi sur la maison de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'approchons-nous avec un cœur sincère, dans la plénitude de la foi, nous qui avons reçu sur nos cœurs l\'aspersion qui purifie d\'une mauvaise conscience,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'et qui avons eu notre corps lavé d\'une eau pure. Retenons, sans fléchir, la confession de notre espérance, car Celui qui a fait la promesse est fidèle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'et étudions-nous les uns les autres pour rivaliser de charité et de bonnes œuvres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'ne désertant point notre association, comme c\'est la coutume de quelques-uns, mais nous exhortant réciproquement, et cela d\'autant plus, que vous voyez s\'approcher le jour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'En effet, si nous péchons volontairement après avoir reçu la connaissance de la vérité, il ne reste plus de sacrifice pour les péchés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'mais, au contraire, une redoutable attente du jugement, et l\'ardeur d\'un feu qui doit dévorer les adversaires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Celui qui a violé la loi de Moïse meurt, sans miséricorde, sur la déclaration de deux ou trois témoins;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'combien, (pensez-y), sera jugé digne d\'un pire châtiment celui qui aura foulé aux pieds le fils de Dieu, regardé comme impur le sang de l\'alliance, et insulté l\'esprit de la grâce?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Car nous connaissons Celui qui a dit: « A Moi la vengeance, c\'est Moi qui rétribuerai, dit le Seigneur; » et derechef: « Car le Seigneur jugera Son peuple.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Il est effrayant de tomber dans les mains du Dieu vivant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Mais souvenez-vous de ces premiers temps où, après avoir été illuminés, vous avez supporté une grande lutte de souffrances,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'étant, d\'un côté, donnés en spectacle par des outrages et des tribulations, et vous associant, de l\'autre, à ceux qui se trouvaient dans la même position.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'En effet, vous avez tour à tour compati aux souffrances des prisonniers, et accepté avec joie le rapt de vos biens, sachant que vous possédez une meilleure fortune, et qu\'elle subsiste à toujours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Ne vous dépouillez donc point de votre ferme assurance, à laquelle est attachée une grande rémunération.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'C\'est de patience, en effet, que vous avez besoin, afin que, après avoir accompli la volonté de Dieu, vous voyiez la promesse se réaliser pour vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Car, encore très peu, très peu de temps: « Celui qui doit venir viendra, et il ne se fera certainement pas attendre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'mais Mon juste vivra par la foi, et s\'il fait défection, Mon âme ne prend pas plaisir en lui. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Pour nous, nous ne sommes pas sous l\'empire de la défection pour périr, mais sous celui de la foi pour acquérir la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Or, la foi est une persuasion de ce qu\'on espère, une conviction de choses qu\'on ne voit point.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'C\'est parce qu\'ils possédaient une telle foi que les anciens ont reçu un bon témoignage.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'C\'est par la foi que nous reconnaissons que l\'univers a été formé par la parole de Dieu, en sorte que ce n\'est pas de choses visibles que ce qu\'on voit a été fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'C\'est par la foi qu\'Abel offrit à Dieu un sacrifice préférable à celui de Caïn; c\'est par elle qu\'il reçut le témoignage d\'être juste, lui-même rendant témoignage à Dieu par ses offrandes; c\'est par elle que, quoique trépassé, il parle encore.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'C\'est par la foi qu\'Enoch fut enlevé afin qu\'il ne vît pas la mort, et on ne le trouva plus parce que Dieu l\'avait enlevé; en effet, avant cet enlèvement, il lui est rendu le témoignage d\'avoir plu à Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'or, sans la foi, il est impossible de Lui plaire, car il faut que celui qui s\'approche de Dieu croie qu\'il existe, et qu\'il devient le rémunérateur de ceux qui Le cherchent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'C\'est par la foi que Noé, instruit par un oracle des choses qu\'on ne voyait point encore, construisit avec une pieuse prévoyance une arche pour sauver sa famille; c\'est par elle qu\'il condamna le monde, et qu\'il devint héritier de la justice que procure la foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'C\'est par la foi que celui qui est appelé Abraham se soumit à émigrer dans le pays qu\'il devait recevoir en héritage, et il émigra sans savoir où il allait;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'c\'est par la foi qu\'il s\'établit dans la terre qui lui était promise comme dans une terre étrangère, habitant sous des tentes, ainsi qu\'Isaac et Jacob, les cohéritiers de la même promesse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'car il attendait avec impatience la ville qui a les fondements, celle dont Dieu est l\'architecte et le fabricateur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'C\'est par la foi que Sara elle-même reçut, même au delà de l\'âge ordinaire, la capacité de créer une postérité, parce qu\'elle avait cru à la fidélité de Celui qui avait fait la promesse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'De là vient encore que c\'est d\'un seul homme, et même d\'un homme décrépit, qu\'ils sont nés aussi nombreux que les étoiles du ciel et que le sable qui est sur le bord de la mer, lequel est innombrable.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'C\'est dans la foi qu\'ils sont tous morts, sans avoir vu se réaliser pour eux les promesses, mais après en avoir de loin aperçu et salué la réalisation, et avoir confessé qu\'ils étaient étrangers et voyageurs sur la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Car ceux qui parlent ainsi montrent clairement qu\'ils soupirent après leur patrie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Et, si c\'eût été de celle qu\'ils avaient quittée qu\'ils faisaient mention, ils auraient eu le temps d\'y retourner;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'mais on voit bien que c\'en est une meilleure qu\'ils désirent, je veux dire la patrie céleste; c\'est pourquoi Dieu n\'a point honte, en ce qui les concerne, d\'être appelé « leur Dieu », car Il leur a préparé une ville.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'C\'est par la foi qu\'Abraham, mis à l\'épreuve, a offert Isaac en sacrifice, et qu\'il offrit son fils unique;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'lui, qui avait accepté les promesses, et auquel il avait été dit: « C\'est en Isaac que se réalisera pour toi le nom de postérité; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'mais il pensa que Dieu peut relever, même d\'entre les morts; d\'entre lesquels (figurément, il est vrai,) il recouvra son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'C\'est par la foi, et en vue de l\'avenir, qu\'Isaac bénit Jacob et Ésaü.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'C\'est par la foi que Jacob, en mourant, bénit chacun des fils de Joseph, et qu\'il adora, en s\'appuyant sur l\'extrémité de son bâton. —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'C\'est par la foi que Joseph, en mourant, fit mention de la sortie des fils d\'Israël, et donna des ordres relatifs à ses propres ossements.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'C\'est par la foi que Moïse, après sa naissance, fut, pendant trois mois, tenu caché par ses parents (car ils voyaient la beauté de l\'enfant), et qu\'ils ne craignirent point le décret du roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'C\'est par la foi que Moïse, étant devenu grand, se refusa à être appelé le fils d\'une fille de Pharaon,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'aimant mieux être maltraité avec le peuple de Dieu, que de goûter momentanément une jouissance coupable,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'et regardant comme une richesse plus grande que les trésors de l\'Egypte l\'opprobre de Christ, car il avait les yeux fixés sur la rémunération.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'C\'est par la foi qu\'il quitta l\'Egypte, sans redouter le courroux du roi, car il tint ferme comme s\'il voyait l\'Invisible.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'C\'est par la foi qu\'il institua la pâque et l\'aspersion du sang, afin que l\'exterminateur ne touchât pas leurs premiers-nés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'C\'est par la foi qu\'ils traversèrent la mer Rouge comme une terre sèche, tandis que les Égyptiens qui s\'y risquèrent furent engloutis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'C\'est par la foi que les murs de Jéricho tombèrent, après avoir été investis pendant sept jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'C\'est par la foi que Rahab l\'impudique ne périt pas avec les rebelles, parce qu\'elle avait pacifiquement reçu les espions.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Et que dire encore? Car le temps me manquera si je parle de Gédéon, de Barac, de Samson, de Jephté, de David, et de Samuel, et des prophètes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'qui, par la foi, ont conquis des royaumes, exercé la justice, obtenu des promesses, fermé la gueule des lions,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'éteint la puissance du feu, échappé au fil de l\'épée, recouvré les forces perdues, montré leur vaillance dans la guerre et fait décamper l\'ennemi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Des femmes entrepris, par une résurrection, possession de leurs morts; d\'autres ont été torturés, après s\'être refusés au rachat, afin d\'obtenir une meilleure résurrection;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'd\'autres ont eu à subir des outrages et des coups, et même des chaînes et la prison;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'ils ont été lapidés, sciés, tentés; ils sont morts par l\'épée; ils ont erré, vêtus de peaux de mouton, de peaux de chèvre, dénués de tout, persécutés, maltraités;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, 'ils ont été, eux dont le monde n\'était pas digne, errants dans les déserts, les montagnes, les cavernes, et les crevasses de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Et tous ceux-là, quoiqu\'ils eussent reçu, à cause de leur foi, un bon témoignage, n\'ont point vu se réaliser pour eux les promesses,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'car Dieu avait d\'avance arrêté pour nous quelque chose de meilleur, afin qu\'ils ne fussent pas amenés à la perfection sans nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Ainsi donc, nous aussi, puisque nous avons autour de nous une si grande nuée de témoins, après nous être débarrassés de tout ce qui nous alourdit et du péché qui nous enlace si aisément, courons avec persévérance dans la carrière qui nous est ouverte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'ayant les yeux fixés sur Jésus le chef et le consommateur de la foi, lui qui, à cause de la joie qui lui était offerte, a supporté la croix, méprisé l\'ignominie, et s\'est assis à la droite du trône de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Considérez en effet celui qui a supporté une telle opposition des pécheurs contre lui-même, afin que vous ne perdiez pas courage en laissant défaillir vos âmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Vous n\'avez pas encore résisté jusques au sang en luttant contre le péché;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'et avez-vous oublié l\'exhortation qui vous est adressée comme à des fils: « Mon fils, ne méprise pas le châtiment du Seigneur, et ne te laisse pas non plus défaillir quand tu es repris par Lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'car celui que le Seigneur aime, Il le châtie, et Il fouette même tout fils qu\'il reconnaît pour sien »?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Attendez-vous au châtiment; c\'est comme des fils que Dieu vous traite; car quel est le fils que son père ne châtie point?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Mais, si vous demeurez exempts du châtiment dont tous ont eu leur part, vous êtes donc des bâtards et non pas des fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'D\'ailleurs, nous qui avons pour nous châtier les pères de notre chair, et qui les avons respectés, ne nous soumettrons-nous pas à bien plus forte raison au Père des esprits pour avoir la vie?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Les premiers, en effet, nous châtiaient pendant peu de temps comme bon leur semblait, tandis que Lui le fait pour notre bien, afin que nous participions à Sa sainteté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Il est vrai que tout châtiment ne paraît pas, au premier moment, être un sujet de joie, mais de tristesse, tandis que plus tard il rapporte à ceux qui ont été ainsi exercés un fruit paisible de justice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'C\'est pourquoi restaurez, les mains fatiguées et les genoux défaillants,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'et faites de droites ornières avec vos pieds, afin que ce qui est boiteux ne se détraque pas, mais bien plutôt se guérisse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Recherchez la paix avec tous et la sanctification sans laquelle nul ne verra le Seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'veillant à ce que personne ne se prive de la grâce de Dieu, à ce qu\'aucune racine d\'amertume, poussant des rejetons, ne produise du trouble, et que par elle le plus grand nombre ne soit souillé;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'à ce que personne ne soit impudique, ou profane comme Ésaü qui vendit pour un simple aliment ses droits de premier-né;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'vous savez en effet que, plus tard, lorsqu\'il voulut recevoir la bénédiction, il fut rejeté, quoiqu\'il la sollicitât avec larmes, car il ne trouva plus l\'occasion de se repentir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Ce n\'est pas, en effet, d\'un feu tangible et brûlant que vous vous êtes approchés, ni de l\'obscurité, ni des ténèbres, ni de la tempête,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'ni du retentissement de la trompette, ni du bruit des paroles qui fît refuser par ceux qui l\'entendirent qu\'on leur en adressât une de plus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'car ils ne supportaient pas cette déclaration: « Si même un animal touche la montagne, il sera lapidé; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'et l\'apparition était si effrayante que Moïse dit: « Je suis effrayé et tout tremblant. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Ne vous êtes-vous pas, en effet, approchés de la montagne de Sion et de la ville du Dieu vivant qui est la Jérusalem céleste, et des myriades dont se compose le grand chœur des anges,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'de l\'assemblée des premiers-nés inscrits dans les cieux, et du juge qui est le Dieu de tous, et des esprits des justes qui ont été amenés à la perfection,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'et de Jésus qui est le médiateur d\'une nouvelle alliance, et du sang de l\'aspersion qui parle mieux qu\'Abel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Prenez garde de ne pas refuser d\'écouter Celui qui parle; car si ceux-là n\'échappèrent pas, pour avoir refusé d\'écouter Celui qui, sur la terre, rendait des oracles, à combien plus forte raison n\'échapperons-nous pas si nous nous détournons de Celui qui en rend du haut des cieux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Lui, dont la voix ébranla alors la terre, tandis que maintenant Il a fait cette promesse: « Une fois encore Je ferai trembler non seulement la terre, mais aussi le ciel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Or les mots « une fois encore » indiquent le changement des choses qui peuvent être ébranlées parce qu\'elles ont été faites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'C\'est pourquoi, comme nous sommes mis en possession d\'un royaume inébranlable, soyons pénétrés d\'une reconnaissance qui nous fasse rendre à Dieu un culte qui lui soit agréable, avec vénération et avec crainte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'car notre Dieu est aussi un feu dévorant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Que l\'amour fraternel subsiste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'N\'oubliez pas l\'hospitalité, car c\'est par elle que quelques-uns, sans s\'en douter, ont hébergé des anges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Souvenez-vous des prisonniers, comme si vous partagiez leurs chaînes, et de ceux qu\'on maltraite, comme étant aussi vous-mêmes en possession d\'un corps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Que le mariage soit respecté à tous égards, et la couche nuptiale exempte de souillure, car Dieu jugera les impudiques et les adultères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Que l\'amour de l\'argent vous soit étranger, vous contentant de ce que vous possédez, car Lui-même a dit: « Je ne t\'abandonnerai certainement point, et Je ne te délaisserai certainement point non plus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'en sorte que, pleins de confiance, nous disons: « Le Seigneur est mon aide, et je ne craindrai point; que me fera l\'homme? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Souvenez-vous de vos conducteurs qui vous ont prêché la parole de Dieu, et, puisque vous avez été témoins de l\'issue de leur carrière, imitez leur foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jésus-Christ est le même hier et aujourd\'hui et pour l\'éternité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'ne vous laissez pas entraîner par des doctrines diverses et étrangères, car il convient que ce soit par la grâce que le cœur soit affermi, et non par des aliments qui n\'ont servi de rien à ceux qui s\'y attachent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'pour nous, nous avons un autel dont ceux qui rendent un culte dans le tabernacle n\'ont point le droit de se nourrir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'car les animaux, dont le sang est porté dans le sanctuaire par le grand prêtre, ont leur corps brûlé hors du camp;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'c\'est pourquoi aussi Jésus, afin de sanctifier le peuple par son propre sang, a souffert la mort hors de la porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Ainsi donc sortons pour aller à lui hors du camp, en portant son opprobre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'car nous n\'avons point ici de ville permanente, mais nous aspirons à celle qui est à venir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Offrons donc continuellement à Dieu par lui un sacrifice de louanges, c\'est-à-dire le fruit des lèvres qui confessent Son nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'toutefois n\'oubliez ni la bienfaisance, ni les libéralités, car ce sont à de tels sacrifices que Dieu prend plaisir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Soyez obéissants et soumis à vos conducteurs, car ce sont eux qui veillent comme devant rendre compte de vos âmes, afin qu\'ils le fassent avec joie et sans gémir; car cela vous serait désavantageux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Priez pour nous; car nous sommes sûrs d\'avoir une bonne conscience, voulant en toutes choses nous bien conduire;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'mais je vous exhorte d\'autant plus vivement à le faire, que d\'autant plus vite je vous serai rendu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Or, que le Dieu de la paix, qui a retiré du milieu des morts le grand berger des brebis, avec le sang d\'une alliance éternelle, notre Seigneur Jésus,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'vous rende capables de toute bonne œuvre et de toute bonne parole afin que vous fassiez Sa volonté, en faisant pour Lui-même en vous ce qui est agréable à Ses yeux, par Jésus-Christ, auquel soit rendue la gloire pour les siècles des siècles! Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Je vous exhorte, frères, à bien accueillir ces paroles d\'exhortation, car c\'est brièvement que je vous ai écrit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Vous savez que notre frère Timothée a été relâché; c\'est avec lui, s\'il vient assez tôt, que je vous visiterai.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Saluez tous vos conducteurs et tous les saints. Ceux d\'Italie vous saluent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'La grâce soit avec vous tous! Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jacques, esclave de Dieu et du seigneur Jésus-Christ, aux douze tribus qui sont dans la dispersion: Salut!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Estimez, mes frères, que vous avez toute raison de vous réjouir quand vous vous trouverez en butte à des tentations de diverse nature,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'sachant que l\'épreuve à laquelle est mise votre foi produit la constance.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Mais que cette constance ait une efficace parfaite, afin que vous soyez parfaits et entièrement accomplis, ne laissant rien à désirer sous aucun rapport.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Toutefois si l\'un de vous manque de sagesse, qu\'il la demande à Dieu qui donne à tous simplement et sans reproches, et elle lui sera donnée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'mais qu\'il la demande avec foi, sans douter, car celui qui doute est semblable au flot de la mer soulevé et agité par le vent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Que cet homme-là ne pense pas en effet qu\'il obtiendra quoi que ce soit du Seigneur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'homme irrésolu, inconstant dans toutes ses voies!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Or, que le frère d\'humble condition se glorifie de son élévation,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'et le riche au contraire de son humiliation, car il passera comme la fleur de l\'herbe;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'en effet le soleil s\'est levé avec son ardente chaleur et il a desséché l\'herbe, et sa fleur est tombée, et la beauté de son aspect a disparu; de la même manière aussi le riche se flétrira au milieu de ses poursuites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Heureux l\'homme qui résiste avec constance à la tentation, car, lorsqu\'il aura fait ses preuves, il recevra la couronne de vie qu\'il a promise à ceux qui L\'aiment.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Que personne, lorsqu\'il est tenté, ne dise: « C\'est par Dieu que je suis tenté; » car Dieu ne peut être tenté par le mal, et Il ne tente Lui-même personne;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'mais chacun est tenté en se laissant entraîner et amorcer par sa propre convoitise;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'puis, la convoitise ayant conçu, met au monde le péché, et le péché arrivé à son terme, enfante la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Ne vous y trompez pas, mes frères bien-aimés:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'toute bonne libéralité et tout don parfait descendent d\'en haut, du Père des lumières, chez Lequel il n\'y a aucune variation, ni aucune ombre produite par quelque changement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'C\'est volontairement qu\'il nous a enfantés par la parole de vérité, afin que nous soyons en quelque sorte les prémices de Ses créatures;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'vous le savez, mes frères bien-aimés!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'car la colère de l\'homme n\'accomplit point la justice de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'C\'est pourquoi vous étant dépouillés de toute souillure, et de tout excès de malice, accueillez avec douceur la parole implantée qui peut sauver vos âmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Mais soyez de ceux qui pratiquent, et non pas de ceux qui écoutent seulement la parole, en vous trompant vous-mêmes par de faux raisonnements;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'car si quelqu\'un écoute et ne pratique pas la parole, il ressemble à un homme qui étudie dans un miroir le visage qu\'il tient de la nature;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'en effet, après s\'être étudié, il s\'en est allé et aussitôt il a oublié quel il était;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'tandis que celui qui aura plongé ses regards dans la loi parfaite, qui est celle de la liberté, et qui aura persévéré, en se montrant, non un auditeur oublieux, mais un observateur actif, celui-là sera heureux dans son activité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Si quelqu\'un s\'imagine être religieux, sans tenir sa langue en bride, mais en trompant son propre cœur, la religion de cet homme-là est vaine.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'La religion pure et immaculée aux yeux de Dieu notre Père, la voici: c\'est de visiter les orphelins et les veuves dans leur tribulation, c\'est de se conserver soi-même sans tache, en se préservant du monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Mes frères, ne mêlez pas aux acceptions de personnes la foi en notre glorieux seigneur Jésus-Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'En effet, s\'il vient à entrer dans une de vos synagogues un homme à bagues d\'or, en habit somptueux, tandis qu\'il vient à entrer aussi un pauvre en méchant habit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'mais que vous dirigiez vos regards sur celui qui porte l\'habit somptueux et que vous disiez: « Toi, assieds-toi ici à ton aise, » et que vous disiez au pauvre: « Toi, tiens-toi debout, ou assieds-toi là sous mon marchepied, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'vous avez douté en vous-mêmes, et vous êtes devenus des juges mal inspirés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Écoutez, mes frères bien-aimés: Dieu n\'a-t-Il pas choisi ceux qui sont pauvres aux yeux du monde pour être riches dans la foi et héritiers du royaume qu\'il a promis à ceux qui L\'aiment?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Mais vous, vous avez avili le pauvre! Est-ce que ce ne sont pas les riches qui vous oppriment, et n\'est-ce pas eux qui vous traînent devant les tribunaux?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'N\'est-ce pas eux qui calomnient le beau nom qui a été invoqué sur vous?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Cependant si vous accomplissez la loi royale, selon le texte de l\'écriture: « Tu aimeras ton prochain comme toi-même, » vous faites bien;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'mais si vous faites acception de personnes, vous commettez un péché, la loi vous convainquant d\'être des transgresseurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'car quiconque aura observé la loi tout entière, mais aura failli sur un seul point, devient coupable sur tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'En effet Celui qui a dit: « Ne commets point d\'adultère, » a dit aussi: « Ne commets point d\'homicide. » Or, si tu ne commets pas d\'adultère, mais que tu commettes un homicide, tu deviens un transgresseur de la loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Parlez et agissez comme devant être jugés par une loi de liberté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'car le jugement est sans miséricorde pour qui n\'a pas fait miséricorde. La miséricorde brave le jugement!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'A quoi sert, mes frères, que quelqu\'un dise qu\'il a de la foi, tandis qu\'il n\'a pas d\'œuvres? Est-ce que la foi peut le sauver?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Si un frère ou une sœur se trouvent nus et privés de leur nourriture quotidienne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'et que l\'un d\'entre vous leur dise: « Allez en paix, réchauffez-vous et vous rassasiez, » mais que vous ne leur donniez point ce dont le corps a besoin, à quoi cela sert-il?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'De même aussi la foi, si elle n\'a pas d\'œuvres, est morte en elle-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Autrement quelqu\'un dira: « Toi, tu as de la foi, et moi de mon côté j\'ai des œuvres; montre-moi ta foi sans les œuvres, et moi de mon côté c\'est par les œuvres que je te montrerai ma foi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'tu crois qu\'il existe un seul Dieu, tu fais bien; les démons aussi le croient, et ils en frémissent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'mais veux-tu apprendre, ô homme frivole, que la foi sans les œuvres est inutile?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Abraham notre père n\'a-t-il pas été justifié par les œuvres pour avoir offert Isaac son fils sur l\'autel?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Tu vois que la foi coopérait avec ses œuvres; et c\'est par les œuvres que la foi a été parfaite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'et ce texte de l\'écriture a été accompli qui dit: Or, Abraham crut à Dieu, et cela lui fut compté pour justice; et il a été appelé ami de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Vous voyez que c\'est par les œuvres que l\'homme est justifié, et non par la foi seulement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Or, n\'est-ce pas aussi de la même manière que Rahab l\'impudique a été justifiée par les œuvres, pour avoir reçu les messagers et les avoir fait sortir par un autre chemin?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'De même que le corps sans souffle est mort, de même aussi la foi sans œuvres est morte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Ne soyez pas un grand nombre à vous ériger en docteurs, mes frères, car vous savez que nous encourrons ainsi une plus grande condamnation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'En effet, nous faillissons tous beaucoup; si quelqu\'un ne faillit pas en parole, c\'est un homme parfait, capable de tenir aussi en bride le corps tout entier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Or, si nous plaçons les mors des chevaux dans leurs bouches pour qu\'il nous obéissent, nous dirigeons aussi leur corps tout entier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Voici, les vaisseaux même, qui sont si grands, quoique chassés par des vents violents, sont dirigés par un tout petit gouvernail là où veut les porter l\'impulsion du pilote.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'De même aussi la langue est un petit membre, et elle a de quoi se targuer. Voici! quel grand feu embrase une si grande forêt!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'La langue aussi est un feu! C\'est le monde de l\'iniquité! La langue se montre parmi nos membres comme souillant le corps tout entier, et mettant en feu la roue de la vie, et étant mise en feu par la géhenne!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'En effet, toute espèce de bêtes et d\'oiseaux, de reptiles et d\'animaux marins sont domptés et ont été domptés par l\'espèce humaine,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'mais nul homme ne peut dompter sa langue; fléau désordonné, pleine d\'un venin mortel!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Par elle nous bénissons le Seigneur notre Père, et par elle nous maudissons les hommes qui ont été faits à la ressemblance de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'de la même bouche sort la bénédiction et la malédiction! Il ne faut pas, mes frères, que ces choses se passent ainsi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Est-ce que la source fait jaillir par la même ouverture l\'eau douce et l\'eau saumâtre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Est-ce qu\'un figuier, mes frères, peut produire des olives, ou une vigne des figues? De l\'eau salée ne peut pas non plus produire de l\'eau douce.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Qui est-ce qui est parmi vous sage et sensé? Qu\'il montre ses œuvres par sa bonne conduite avec la douceur de la sagesse;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'mais si vous avez une envie amère et de l\'intrigue dans votre cœur, ne vous glorifiez pas en bravant la vérité et ne mentez pas contre elle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Ce n\'est pas là la sagesse qui descend d\'en haut, mais une sagesse terrestre, animale, diabolique;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'car là où il y a de l\'envie et de l\'intrigue, il y a du désordre et toute espèce de mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Au contraire la sagesse d\'en haut est d\'abord pure, puis pacifique, modérée, conciliante, pleine de miséricorde et de bons fruits, sans duplicité, sans hypocrisie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Or le fruit de la justice est semé dans la paix pour ceux qui procurent la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'D\'où viennent les querelles et d\'où viennent les luttes parmi vous? N\'est-ce pas de vos plaisirs qui guerroient dans vos membres?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Vous convoitez, et vous ne possédez pas; vous êtes homicides et envieux, et vous ne pouvez pas obtenir; vous luttez et vous vous querellez. Vous ne possédez pas, parce que vous ne priez pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'vous priez et vous ne recevez pas, parce que vous priez à mauvaise intention, afin de dépenser pour vos plaisirs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Épouses adultères, ne savez-vous pas que l\'amour pour le monde est ennemi de Dieu? Celui donc qui voudra être ami du monde, se montre ennemi de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Ou bien vous imaginez-vous que ce soit en vain que parle l\'écriture? C\'est avec jalousie qu\'il chérit l\'esprit qu\'il a fait habiter en nous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'mais aussi Il accorde une plus grande grâce; c\'est pourquoi elle dit: « Dieu résiste aux orgueilleux, mais aux humbles Il accorde grâce. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Soumettez-vous donc à Dieu, mais résistez au diable, et il fuira loin de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Approchez-vous de Dieu, et Il s\'approchera de vous. Nettoyez vos mains, pécheurs, et purifiez votre cœur, vous qui êtes irrésolus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Sentez votre malheur, et prenez le deuil et pleurez; que votre rire se change en deuil, et votre joie en abattement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Humiliez-vous devant le Seigneur, et Il vous élèvera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Ne dites pas de mal les uns des autres, frères; celui qui dit du mal d\'un frère ou qui juge son frère, dit du mal de la loi et juge la loi; or, si tu juges la loi, tu n\'es pas l\'observateur, mais le juge de la loi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Un seul est législateur et juge, c\'est Celui qui peut sauver et perdre; mais toi, qui es-tu, qui juges le prochain?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Allons maintenant, vous qui dites: « Aujourd\'hui ou demain nous irons dans telle ville, et nous y passerons une année, et nous trafiquerons, et nous gagnerons; »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'vous qui ne savez pas ce qui en sera de votre vie de demain! Car vous êtes une vapeur qui apparaît pour un peu de temps et qui ensuite disparaît.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Au lieu de dire: « Si le Seigneur le veut, alors nous vivrons et nous ferons ceci ou cela. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Mais maintenant vous vous glorifiez dans vos forfanteries; toute gloriole de ce genre est mauvaise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Celui donc qui sait faire ce qui est bien et ne le fait pas est coupable de péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Allons maintenant, les riches! Pleurez en poussant des cris à cause des malheurs qui vont survenir:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'vos richesses sont putréfiées, et vos vêtements ont été rongés par les vers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'votre or et votre argent sont rouillés, et leur rouille portera témoignage contre vous, et elle dévorera vos chairs comme le feu. C\'est au moment des derniers jours que vous avez thésaurisé!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Voici, le salaire des ouvriers qui ont moissonné vos campagnes, retenu par vous crie, et les clameurs des moissonneurs sont entrées dans les oreilles du Seigneur Sabaoth.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Vous avez vécu sur la terre dans les délices et dans la débauche, vous avez repu vos cœurs en un jour de tuerie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Vous avez condamné, vous avez fait mourir le juste, il ne vous résiste pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Prenez donc patience, frères, jusques à l\'avènement du seigneur. Voici, l\'agriculteur sait attendre le précieux fruit de la terre, prenant patience à son égard jusques à ce qu\'il ait recueilli le précoce et le tardif.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Vous aussi prenez patience, fortifiez vos cœurs, car l\'avènement du Seigneur s\'approche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Ne murmurez pas, frères, les uns contre les autres, afin que vous ne soyez pas jugés; voici, le juge est à la porte.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Frères, prenez pour modèle de souffrance et de patience les prophètes qui ont parlé au nom du Seigneur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Voici, nous proclamons bienheureux ceux qui ont tenu ferme; vous avez ouï parler de la constance de Job, et vous avez vu l\'issue donnée par le Seigneur, car le Seigneur a beaucoup d\'entrailles, et Il est compatissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Mais avant toutes choses, mes frères, ne jurez point, ni par le ciel, ni par la terre, ni par aucun autre serment; mais que votre oui soit oui, et votre non, non, afin que vous ne tombiez pas sous le jugement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Quelqu\'un souffre-t-il parmi vous? qu\'il prie! Quelqu\'un est-il content? qu\'il chante des cantiques!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Quelqu\'un est-il malade parmi vous? qu\'il fasse venir les anciens de l\'église, et qu\'ils prient sur lui après avoir fait une onction d\'huile en invoquant le nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'et la prière de la foi sauvera le malade, et le Seigneur le relèvera, et quand même il aurait commis des péchés, il lui sera pardonné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Confessez-vous donc réciproquement vos péchés, et priez les uns pour les autres, afin que vous soyez guéris; la prière active d\'un juste peut beaucoup.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Élie était un homme de même nature que vous, et il fit une prière pour qu\'il ne plût pas, et il ne plut pas sur la terre pendant trois ans et six mois,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'puis il pria derechef, et le ciel donna de la pluie, et la terre produisit son fruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Mes frères, si quelqu\'un parmi vous s\'est laissé égarer loin de la vérité, et que quelqu\'un l\'y ait ramené,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'sachez que celui qui aura ramené un pécheur du chemin où il s\'égarait sauvera une âme de la mort même, et couvrira une multitude de péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Pierre, apôtre de Jésus-Christ, aux voyageurs de la dispersion dans le Pont, la Galatie, la Cappadoce, l\'Asie, qui sont élus');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'selon la prescience de Dieu le Père, par la sanctification de l\'esprit, pour obéir, et pour recevoir l\'aspersion du sang de Jésus-Christ: Que la grâce et la paix vous soient multipliées!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Béni soit Dieu, qui est aussi le Père de notre seigneur Jésus-Christ, Lui qui, selon sa grande miséricorde, nous a fait renaître par la résurrection de Jésus-Christ d\'entre les morts pour une espérance vivante,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'pour un héritage incorruptible, immaculé, inaltérable, lequel est réservé dans les cieux pour vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'qui, grâce à la puissance de Dieu, êtes gardés par la foi, en vue du salut prêt à être révélé dans l\'époque dernière,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'dans laquelle vous devez tressaillir d\'allégresse, après avoir été, pendant peu de temps encore, s\'il le faut, attristés par des tentations de diverse nature,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'afin que l\'épreuve à laquelle est mise votre foi, plus précieuse que l\'or qui, tout périssable qu\'il est, est cependant éprouvé par le feu, se tourne en louange, en gloire, et en honneur, lors de la révélation de Jésus-Christ,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'que vous aimez sans l\'avoir vu, à l\'égard duquel, sans le voir encore, mais en croyant, vous êtes transportés d\'une joie inexprimable et glorieuse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'parce que vous obtenez, ce qui est le terme de la foi, le salut des âmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'C\'est de ce salut que se sont informés et enquis les prophètes qui ont prophétisé touchant la grâce qui vous était destinée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'recherchant à quel moment ou à quelles circonstances faisait allusion l\'esprit qui, en eux, attestait d\'avance les souffrances à endurer pour Christ et les gloires dont elles seraient suivies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Il leur fut révélé que ce n\'était pas pour eux-mêmes, mais pour vous, qu\'ils étaient chargés des choses qui vous sont maintenant annoncées par l\'entremise de ceux qui vous ont prêché la bonne nouvelle par l\'esprit saint envoyé du ciel, et dans lesquelles les anges désirent plonger leurs regards.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'C\'est pourquoi, ayant ceint les reins de votre pensée en étant sobres, fondez pleinement vos espérances sur la grâce qui doit vous être apportée lors de la révélation de Jésus-Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Comme des enfants obéissants, loin de vous conformer aux convoitises auxquelles, dans votre ignorance, vous vous êtes auparavant livrés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'devenez au contraire, selon que Celui qui vous a appelés est saint, saints aussi dans toute espèce de genre de vie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'en effet il est écrit: « Vous serez saints, car Moi Je suis saint. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Et si vous invoquez comme Père Celui qui, sans acception de personnes, juge selon l\'œuvre de chacun, comportez-vous avec crainte pendant le temps de votre voyage,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'sachant que ce n\'est pas par des choses corruptibles, à prix d\'argent ou d\'or, que vous avez été rachetés de la vaine conduite que vous aviez héritée de vos pères,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'mais par le sang précieux de Christ, comme agneau irréprochable et sans tache,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'déjà prédestiné avant la fondation du monde, mais manifesté dans le dernier des temps à cause de vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'qui, par lui, avez cru en Dieu qui l\'a ressuscité des morts, et qui lui a donné la gloire, en sorte que votre foi et votre espérance se rapportent à Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Ayant sanctifié vos âmes en obéissant à la vérité pour éprouver un amour fraternel sans hypocrisie, aimez-vous ardemment les uns les autres du fond du cœur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'vous qui avez été régénérés, non par une semence corruptible mais incorruptible, par la vivante et permanente parole de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'en effet toute chair est comme l\'herbe, et toute sa gloire comme la fleur de l\'herbe; l\'herbe s\'est séchée, et la fleur est tombée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'mais la parole du Seigneur demeure pour l\'éternité. Or cette parole, c\'est celle de la bonne nouvelle qui vous a été prêchée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Vous étant donc dépouillés de toute malice et de toute ruse, et de l\'hypocrisie, et des meurtres, et de toute calomnie,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'comme des enfants nouveau-nés désirez avec ardeur le lait pur de la parole, afin que par son moyen vous croissiez pour le salut,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'si vous avez goûté que le seigneur est bon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'C\'est en vous approchant de lui, la pierre vivante, que les hommes ont, il est vrai, rejetée, mais qui est devant Dieu choisie et honorée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'que vous-mêmes aussi, comme des pierres vivantes, vous êtes édifiés, maison spirituelle, pour former une prêtrise sainte, afin d\'offrir des sacrifices spirituels agréables à Dieu par Jésus-Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'en effet on trouve dans l\'écriture: « Voici, Je place en Sion une pierre choisie, angulaire, honorée, et celui qui croit en elle n\'aura certainement pas à en rougir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'C\'est donc à vous qui croyez, qu\'appartient l\'honneur, tandis que pour les incrédules la pierre que les constructeurs ont rejetée, est celle qui est devenue le sommet de l\'angle, et une pierre d\'achoppement, et un roc de scandale,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'eux qui, par leur incrédulité, heurtent contre la parole; ce à quoi aussi ils ont été destinés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'tandis que vous, vous êtes une race élue, une prêtrise royale, une nation sainte, un peuple acquis, afin que vous proclamiez les vertus de Celui qui, des ténèbres, vous a appelés à Son admirable lumière;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'vous qui autrefois n\'étiez pas un peuple, mais qui êtes maintenant le peuple de Dieu, vous auxquels il n\'avait pas été fait miséricorde, mais à qui maintenant il a été fait miséricorde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Bien-aimés! Je vous exhorte comme des étrangers et des voyageurs, à préserver des convoitises charnelles qui font la guerre à l\'âme');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'votre bonne conduite parmi les Gentils, afin que, sur les points où ils vous accusent calomnieusement de mal faire, ils glorifient Dieu, au jour de la visitation, à cause de vos bonnes œuvres, en y regardant de plus près.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Soyez soumis à toute institution humaine à cause du Seigneur, soit au roi, comme au souverain,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'soit aux gouverneurs, comme à ceux qui sont délégués par lui pour châtier les malfaiteurs et pour approuver les gens de bien;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'car c\'est ici la volonté de Dieu, qu\'en faisant bien vous fermiez la bouche à l\'ignorance des hommes dépourvus de sens.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'C\'est comme étant libres, et non pas comme faisant de votre liberté un manteau pour votre malice, mais comme esclaves de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'que vous devez honorer tous les hommes, aimer les frères, craindre Dieu, honorer le roi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Serviteurs, soyez soumis en toute crainte à vos maîtres, non seulement à ceux qui sont bons et indulgents, mais encore à ceux de difficile humeur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'car c\'est une grâce, que d\'endurer des afflictions par motif de conscience envers Dieu, en souffrant injustement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Quelle gloire en effet vous reviendrait-il de supporter patiemment les coups que vous attirent vos péchés? Mais si vous supportez patiemment les souffrances que vous attirent vos bonnes actions, ceci est une grâce devant Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'car c\'est à cela que vous avez été appelés, puisque Christ aussi a souffert pour vous, vous laissant un modèle afin que vous suiviez ses traces,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'lui, qui n\'a point commis de péché, et dans la bouche duquel il ne s\'est point trouvé de fraude;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'lui qui, insulté, ne rendait pas l\'insulte, qui, maltraité, ne menaçait pas, mais s\'en remettait à Celui qui juge avec justice;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'lui, qui a porté lui-même vos péchés en son corps sur le bois, afin qu\'ayant rompu avec les péchés, nous vivions pour la justice; lui, par la meurtrissure duquel vous avez été guéris;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'vous erriez comme des brebis, mais maintenant vous vous êtes retournés vers le pasteur et le gardien de vos âmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Femmes, soyez de même soumises à vos propres maris, afin que, si quelques-uns d\'entre eux sont rebelles à la parole, ils soient gagnés sans paroles par la conduite de leurs femmes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'lorsqu\'ils auront vu de plus près votre chaste et scrupuleuse conduite;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'vous, dont la préoccupation doit être, non la parure extérieure qui consiste à se tresser les cheveux, et à se couvrir d\'or, ou à revêtir de beaux vêtements,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'mais l\'homme caché dans le cœur, avec les dispositions incorruptibles de l\'esprit tranquille et doux qui est de grand prix devant Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'car c\'est aussi de la sorte que jadis les saintes femmes qui espéraient en Dieu se paraient elles-mêmes, en restant soumises à leurs propres maris,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'comme Sara fut obéissante à Abraham qu\'elle appelait son seigneur; c\'est d\'elle que vous êtes devenues les enfants, en faisant bien et en ne vous laissant pas effrayer par la moindre intimidation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Maris, de même comportez-vous avec discernement envers le sexe féminin, comme envers une créature plus faible, en lui rendant honneur, comme à qui est aussi héritier avec vous de la grâce de la vie, afin de n\'être pas entravés dans vos prières.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Enfin soyez tous animés des mêmes pensées et des mêmes sentiments, soyez remplis d\'amour fraternel, de tendresse, d\'humilité,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'ne rendant point mal pour mal, ou insulte pour insulte, mais au contraire, bénissant, car c\'est à cela que vous avez été appelés, afin d\'hériter la bénédiction.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'En effet, que celui qui veut aimer la vie et voir des jours favorables empêche sa langue de dire du mal et ses lèvres de proférer la fraude;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'mais qu\'il s\'éloigne du mal et fasse le bien, qu\'il recherche la paix et la poursuive;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'car les yeux du Seigneur sont ouverts sur les justes et Ses oreilles à leur prière, mais la face du Seigneur est contre ceux qui font de mauvaises choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Et qui est-ce qui vous maltraitera, si vous devenez zélés pour le bien?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Mais alors même que vous souffririez à cause de la justice, bienheureux êtes-vous? Toutefois n\'ayez d\'eux nulle crainte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'mais sanctifiez en vos cœurs Christ le seigneur, étant toujours prêts à rendre compte à quiconque vous demande raison de l\'espérance qui est en vous; toutefois avec douceur et crainte,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'ayant une bonne conscience, afin que sur les points où vous êtes calomniés, ceux qui diffament votre bonne conduite en Christ, soient couverts de confusion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Car il vaut mieux que ce soit pour avoir bien fait que vous souffriez, si telle est la volonté de Dieu, que pour avoir mal fait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'En effet Christ aussi a souffert pour les péchés une fois pour toutes, lui juste pour des injustes, afin de vous donner accès, ayant été il est vrai mis à mort quant à la chair, mais ayant été vivifié quant à l\'esprit,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'par lequel aussi il est allé prêcher aux esprits qui sont en prison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'lesquels s\'étaient rebellés autrefois, quand la patience de Dieu temporisait lors de l\'époque de Noé, pendant que se construisait l\'arche, dans laquelle un petit nombre de personnes, c\'est-à-dire huit, se sauvèrent au travers de l\'eau,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'ce symbole qui vous sauve aussi maintenant dans le baptême (lequel n\'est pas un nettoiement des souillures de la chair, mais l\'engagement d\'une bonne conscience envers Dieu), grâce à la résurrection de Jésus-Christ');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'qui est à la droite de Dieu, étant entré dans le ciel après que les anges, et les autorités, et les puissances lui ont été soumis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Christ ayant donc souffert quant à la chair, armez-vous aussi des mêmes dispositions, car celui qui a souffert quant à la chair a été délivré quant aux péchés,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'en sorte que ce n\'est plus sur les convoitises humaines, mais sur la volonté de Dieu, qu\'il doit régler le temps qui lui reste à vivre en la chair;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'c\'est assez, en effet, d\'avoir pendant le temps passé accompli la volonté des Gentils en vivant dans la débauche, les convoitises, l\'ivrognerie, les excès, les orgies et les idolâtries criminelles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'aussi sont-ils étonnés de ce que vous ne vous précipitez pas avec eux dans le même débordement de dissolution, et ils vous calomnient,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'eux qui rendront compte à Celui qui va juger les vivants et les morts;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'car la bonne nouvelle a été annoncée aussi aux morts, afin que d\'un côté ils fussent jugés comme les hommes, quant à la chair, et que de l\'autre côté ils vécussent comme Dieu, quant à l\'esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Or la fin de toutes choses approche; soyez donc sages et sobres pour vaquer aux prières;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'ayant avant tout, les uns pour les autres, une ardente charité, car la charité couvre une multitude de péchés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'exerçant sans murmure l\'hospitalité réciproque;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'chacun selon le don qu\'il a reçu, le mettant au service des autres, comme de bons administrateurs des diverses grâces de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'si quelqu\'un parle, que ce soit comme il convient aux oracles de Dieu; si quelqu\'un exerce un ministère, que ce soit comme usant de la force que Dieu dispense, afin qu\'en toutes choses Dieu soit glorifié par Jésus-Christ, auquel appartiennent la gloire et le pouvoir aux siècles des siècles. Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Bien-aimés! Ne vous étonnez pas du feu allumé au milieu de vous pour vous induire en tentation, comme s\'il vous advenait quelque chose d\'étrange;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'mais, selon que vous prenez part aux souffrances de Christ, réjouissez-vous, afin que, lors de la révélation de sa gloire, vous vous réjouissiez aussi avec allégresse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Si vous êtes insultés à cause du nom de Christ, bienheureux êtes-vous, car l\'esprit de gloire, qui est aussi l\'esprit de Dieu, repose sur vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Que nul de vous, en effet, ne souffre comme meurtrier ou voleur ou malfaiteur, ou comme s\'immisçant dans les affaires d\'autrui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'mais, si c\'est comme chrétien, qu\'il n\'en rougisse pas, mais que plutôt il glorifie Dieu de ce nom même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Le moment est en effet venu de commencer le jugement par la maison de Dieu, mais si d\'abord c\'est par vous, quelle sera la fin de ceux qui sont rebelles à l\'évangile de Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Et si c\'est à grand\'peine que le juste est sauvé, eh bien! l\'impie et le pécheur où le verra-t-on?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Ainsi donc, que ceux aussi qui souffrent selon la volonté de Dieu remettent leurs âmes au fidèle Créateur, en pratiquant ce qui est bien.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'J\'exhorte donc les anciens qui sont parmi vous, moi qui suis ancien comme eux, et témoin des souffrances de Christ, et qui ai part aussi à la gloire qui va être révélée:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Paissez le troupeau de Dieu qui vous est remis, non par contrainte, mais de bon gré, non en vue d\'un gain honteux, mais avec dévouement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, '[non comme tyrannisant ceux qui vous sont échus, mais en devenant les modèles du troupeau];');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'et, lorsque le pasteur suprême aura été manifesté, vous obtiendrez la couronne inaltérable de la gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'De même, jeunes gens, soyez soumis aux anciens, et tous, les uns aux autres; enveloppez-vous d\'humilité, car Dieu résiste aux orgueilleux, mais aux humbles Il accorde grâce;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'humiliez-vous donc sous la main puissante de Dieu, afin qu\'il vous élève au moment convenable,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'ayant rejeté sur Lui tous vos soucis, car c\'est Lui qui prend soin de vous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Soyez sobres, veillez: votre adversaire le diable, semblable à un lion rugissant, se promène en cherchant à dévorer;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'résistez-lui en étant fermes dans la foi, sachant que les mêmes souffrances sont imposées à ceux de vos frères qui sont dans le monde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'mais le Dieu de toute grâce, qui vous a appelés en Christ à posséder Sa gloire éternelle, après que vous aurez souffert pour un peu de temps, vous perfectionnera Lui-même, vous affermira, vous fortifiera.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'A Lui soit le pouvoir, pour les siècles. Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'C\'est par l\'entremise de Sylvanus, le fidèle frère à mon avis, que je vous ai brièvement écrit, affirmant et protestant que c\'est bien à la véritable grâce de Dieu que vous êtes attachés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'La réunion d\'élus qui est à Babylone vous salue, ainsi que Marc mon fils;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'saluez-vous les uns les autres par le baiser de charité. La paix soit avec vous tous qui êtes en Christ!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simon Pierre, esclave et apôtre de Jésus-Christ, à ceux auxquels est échue une foi de même prix qu\'à nous, grâce à la justice de notre Dieu et sauveur Jésus-Christ:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'que la grâce et la paix vous soient multipliées par la connaissance de Dieu et de Jésus notre seigneur,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'dont la divine puissance nous donne gratuitement tout ce qui est nécessaire à la vie et à la piété, grâce à la connaissance de Celui qui nous a appelés par Sa gloire et Sa vertu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'par lesquelles Il accomplit gratuitement pour nous les précieuses et suprêmes promesses, afin que par celles-ci vous deveniez participants de la nature divine, en fuyant la corruption qui existe dans le monde par la convoitise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Or, c\'est aussi précisément pour cela que vous devez, en y mettant tout votre zèle, ajouter à votre foi la vertu, à la vertu la science,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'à la science la tempérance, à la tempérance la constance, à la constance la piété,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'à la piété l\'amour fraternel, à l\'amour fraternel la charité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'car la possession et l\'abondance de ces choses ne vous rend ni paresseux ni stériles pour la connaissance de notre Seigneur Jésus-Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Celui, en effet, qui ne les possède point, est un aveugle, un myope qui a oublié la purification de ses anciens péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'C\'est pourquoi, frères, faites d\'autant plus d\'efforts pour consolider votre vocation et votre élection, car en agissant ainsi vous ne broncherez certainement jamais;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'c\'est ainsi, en effet, que vous sera richement accordée l\'entrée dans le royaume éternel de notre seigneur et sauveur Jésus-Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'C\'est pourquoi je devrai toujours vous remémorer ces choses, quoique vous les connaissiez, et que vous soyez affermis dans la vérité actuelle;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'mais je crois de mon devoir, tant que je suis dans cette tente, de vous tenir en éveil par le ressouvenir,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'sachant que pour moi le dépouillement de cette tente doit être subit, selon que notre seigneur Jésus-Christ me l\'a aussi fait savoir.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Mais je ferai encore mes efforts pour qu\'en tout temps vous puissiez, après mon départ, vous ressouvenir de ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Car ce n\'est pas en suivant des fables ingénieusement conçues, que nous vous avons fait connaître la puissance et l\'avènement de notre seigneur Jésus-Christ; mais c\'est pour avoir été témoins oculaires de sa majesté;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'car, lorsqu\'il reçut de Dieu son Père l\'honneur et la gloire, une voix lui fut adressée en ces termes par la Gloire suprême: « Mon fils, Mon bien-aimé, c\'est celui-ci en qui J\'ai pris plaisir. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Et cette voix nous l\'avons entendue venant du ciel, quand nous étions avec lui sur la sainte montagne,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'et nous en tenons pour plus certaine la parole prophétique, à laquelle vous faites bien de prêter attention, comme à une lampe qui brille dans un lieu obscur, jusques à ce que le jour luise, et que l\'étoile du matin se lève dans vos cœurs;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'sachant avant tout qu\'aucune prophétie de l\'écriture n\'est le résultat d\'une interprétation privée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'car ce n\'est pas de la volonté d\'un homme qu\'une prophétie est jamais sortie, mais c\'est poussés par l\'Esprit Saint, que des hommes ont parlé de la part de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Sans doute, il y a eu aussi de faux prophètes parmi le peuple, de même que parmi vous aussi il y aura de faux docteurs qui introduiront des hérésies pernicieuses, et qui, reniant le maître qui les a rachetés, attireront sur eux-mêmes une subite perdition;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'et leurs débauches trouveront de nombreux sectateurs, à cause desquels la voie de la vérité sera calomniée;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'et dans leur cupidité ils vous exploiteront au moyen de discours fallacieux; mais il y a longtemps que pour eux la sentence est prête, et que leur perdition ne sommeille plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Car, si Dieu n\'a pas épargné les anges qui ont péché, mais les a plongés dans les fosses obscures de l\'enfer, où ils sont gardés pour le jugement;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'et s\'il n\'a pas épargné l\'ancien monde, mais si, lorsqu\'il a déchaîné le déluge sur le monde des impies, Il a préservé Noé, lui huitième, comme prédicateur de la justice;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'et s\'il a condamné, en les réduisant en cendres, les villes de Sodome et de Gomorrhe, dont Il a fait pour les impies une préfiguration de l\'avenir;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'et s\'il a protégé le juste Loth, victime de la conduite débordée des hommes pervers,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '(car ce juste, qui habitait parmi eux, avait journellement son âme juste mise à la torture par les œuvres criminelles dont ses yeux et ses oreilles le rendaient témoin);');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'le Seigneur sait délivrer de la tentation ceux qui sont pieux, et réserver les injustes pour être punis au jour du jugement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'surtout ceux qui s\'adonnent charnellement à une convoitise impure, et qui méprisent la Seigneurie. Audacieux, insolents, ils ne craignent pas de calomnier les gloires,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'tandis que les anges, qui sont plus grands en force et en puissance, ne portent pas contre elles devant le Seigneur un jugement calomniateur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Mais pour ceux-ci, comme des animaux privés de raison dont la nature est de naître pour être pris et tués, calomniant ce qu\'ils ignorent, ils seront victimes de leur propre corruption,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'en recevant la rétribution due à l\'injustice, eux qui mettent leur plaisir dans les délices du jour, hommes tarés et flétris qui se livrent aux excès dans leurs agapes en faisant bonne chère avec vous,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'qui ont les yeux fixés sur la femme adultère et insatiables de péché, qui prennent par leurs amorces les âmes mal affermies, qui ont un cœur exercé à la cupidité, enfants de malédiction!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Après avoir abandonné le droit chemin, ils se sont égarés; ayant suivi le chemin de Balaam, fils de Béor, ils ont préféré la rétribution due à l\'injustice;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'mais reçut une leçon pour sa propre prévarication: une bête de somme muette, s\'étant exprimée par la voix au milieu des hommes, s\'opposa à la démence du prophète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Ces gens-là sont des sources sans eau et des nuées chassées par un tourbillon; c\'est à eux qu\'est réservée l\'obscurité des ténèbres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'car, en proférant d\'orgueilleux discours pleins d\'inanité, ils prennent à l\'amorce de la débauche, au sein des convoitises de la chair, les hommes qui viennent à peine d\'échapper, qui vivent dans l\'égarement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'leur promettant la liberté, eux qui sont eux-mêmes esclaves de la corruption; car on est esclave de qui vous subjugue.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Or, si, après avoir abandonné les souillures du monde, grâce à la connaissance du seigneur et sauveur Jésus-Christ, ils sont de nouveau enlacés et subjugués par elles, leur nouvelle condition est pire que la première;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'car il leur valait mieux n\'avoir point connu la voie de la justice, que de se détourner, une fois qu\'ils l\'avaient connue, du saint commandement qui leur avait été transmis;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'en eux s\'est réalisée la vérité du proverbe: « C\'est un chien retourné à son propre vomissement, et c\'est une truie lavée allant se vautrer dans la boue. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Je vous écris déjà, bien-aimés, cette seconde lettre, dans laquelle, comme dans l\'autre, je ranime par le ressouvenir la pureté de vos pensées,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'afin que vous vous rappeliez les paroles ci-devant proférées par les saints prophètes et le commandement du seigneur et sauveur transmis par vos apôtres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'sachant avant tout que dans les derniers jours des railleurs viendront armés de raillerie, qui suivront leurs propres convoitises,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'et qui diront: « Que devient la promesse de son avènement? Car depuis que les pères sont morts tout continue à subsister comme dès le commencement de la création. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'En effet ils oublient volontairement que jadis ont existé des cieux, et une terre tirée de l\'eau et formée au moyen de l\'eau par la parole de Dieu');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'et qu\'en cet état le monde d\'alors, submergé par l\'eau, a été détruit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'tandis que les cieux actuels et la terre sont conservés par la même parole, tenus en réserve pour le feu, étant gardés pour le jour du jugement et de la perdition des hommes impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Mais il est une chose que vous ne devez pas oublier, bien-aimés: c\'est que, devant le Seigneur, un jour est comme mille ans, et mille ans comme un jour;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'le Seigneur ne tarde point dans l\'accomplissement de la promesse, comme le pensent certaines gens, mais Il use de patience envers vous, ne voulant point que quelques-uns périssent, mais que tous viennent à résipiscence.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Or, le jour du Seigneur viendra comme un voleur, et alors les cieux disparaîtront avec fracas, tandis que les éléments embrasés se dissoudront ainsi que la terre, et les œuvres qu\'elle renferme seront découvertes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Puisque toutes ces choses doivent ainsi se dissoudre, quels ne faut-il pas être par la sainteté de la conduite et par la piété,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'attendant et hâtant l\'avènement de la journée de Dieu, à cause de laquelle les cieux enflammés se dissoudront, et les éléments embrasés doivent se fondre?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Mais selon Sa promesse nous attendons de nouveaux cieux et une nouvelle terre, où la justice habite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'C\'est pourquoi, bien-aimés, efforcez-vous, dans cette attente, d\'être trouvés par Lui sans tache et sans reproche dans la paix.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Regardez aussi comme une occasion de salut la patience de notre Seigneur, selon que notre bien-aimé frère Paul, suivant la sagesse qui lui a été donnée, vous l\'a aussi écrit comme dans toutes les autres lettres');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'où il parle de ces choses, et où il se trouve quelques points difficiles à comprendre, que les ignorants et ceux qui ne sont pas affermis pervertissent pour leur propre perdition, comme le reste des écritures.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Pour vous donc, bien-aimés, que vos prévisions vous mettent sur vos gardes, de peur qu\'entraînés par l\'égarement des pervers vous ne perdiez votre ferme assiette;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'mais croissez dans la grâce et dans la connaissance de notre seigneur et sauveur Jésus-Christ. Qu\'à lui soit la gloire, et maintenant, et pour le jour d\'éternité!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Ce qui était dès le commencement, ce que nous avons entendu, ce que nous avons vu de nos yeux, ce que nous avons contemplé et que nos mains ont touché, relativement à la parole de vie, —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'et la vie a été manifestée, et ce que nous avons vu, nous vous l\'attestons et nous vous l\'annonçons, à savoir la vie éternelle qui était auprès du Père et qui nous a été manifestée, —');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'ce que nous avons vu et entendu, nous vous l\'annonçons à vous aussi, afin que vous aussi vous soyez en communion avec nous; or notre communion est avec le Père et avec Son fils Jésus-Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Et nous écrivons ces choses, afin que notre joie soit parfaite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Et voici la nouvelle que nous avons apprise de lui et que nous vous annonçons: c\'est que Dieu est lumière, et qu\'il n\'y a en Lui aucunes ténèbres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Si nous disons que nous sommes en communion avec Lui, et que nous marchions dans les ténèbres, nous mentons et nous ne pratiquons pas la vérité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'mais si nous marchons dans la lumière comme Il est Lui-même dans la lumière, nous sommes en communion les uns avec les autres, et le sang de Jésus, Son fils, nous purifie de tout péché.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Si nous disons que nous n\'avons pas de péché, nous nous séduisons nous-mêmes, et la vérité n\'est point en nous;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'si nous confessons nos péchés, Il est fidèle et juste pour nous pardonner nos péchés, et pour nous purifier de toute injustice.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Si nous disons que nous n\'avons pas péché, nous faisons de Lui un menteur, et Sa parole n\'est point en nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Mes petits enfants, je vous écris ces choses, afin que vous ne péchiez point; et si quelqu\'un a péché, nous avons pour défenseur auprès du Père Jésus-Christ le juste;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'et il est lui-même une victime expiatoire pour nos péchés, non pas pour les nôtres seuls, mais encore pour le monde entier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Et voici à quoi nous connaissons que nous L\'avons connu: c\'est si nous observons Ses commandements;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'celui qui dit: « Je L\'ai connu, » et qui n\'observe pas Ses commandements, est un menteur, et la vérité n\'est point en lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'tandis que celui qui observe Sa parole, l\'amour de Dieu est véritablement accompli en lui; c\'est ainsi que nous connaissons que nous sommes en Lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Celui qui dit demeurer en Lui doit, comme celui-là s\'est conduit, se conduire aussi lui-même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Bien-aimés, ce n\'est point un commandement nouveau que je vous adresse, mais un commandement ancien que vous aviez dès le commencement; le commandement ancien, c\'est la parole que vous avez entendue;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'pourtant c\'est un commandement nouveau que je vous adresse, ce qui est vrai, soit quant à lui, soit quant à vous; car les ténèbres passent et la lumière véritable apparaît déjà;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'celui qui dit être dans la lumière et qui hait son frère continue à être dans les ténèbres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'celui qui aime son frère, demeure dans la lumière, et il n\'y a point de cause de chute en lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'tandis que celui qui hait son frère est dans les ténèbres, et il marche dans les ténèbres, et il ne sait où il va, parce que les ténèbres ont aveuglé ses yeux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Je vous écris, petits enfants, parce que vos péchés vous ont été pardonnés à cause de son nom;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'je vous écris, pères, parce que vous avez connu Celui qui est dès le commencement; je vous écris, jeunes gens, parce que vous avez vaincu le malin. Je vous ai écrit, petits enfants, parce que vous avez connu le Père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'je vous ai écrit, pères, parce que vous avez connu ce qui est dès le commencement; je vous ai écrit, jeunes gens, parce que vous êtes forts, et que la parole demeure en vous, et que vous avez vaincu le malin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'N\'aimez point le monde, ni les choses qui sont dans le monde; si quelqu\'un aime le monde, l\'amour du Père n\'est point en lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'parce que tout ce qui est dans le monde, la convoitise de la chair, et la convoitise des yeux, et la gloriole de la vie, ne relève point du Père, mais relève du monde;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'et le monde passe, ainsi que sa convoitise; tandis que celui qui fait la volonté de Dieu demeure pour l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Petits enfants, voici l\'heure dernière; et comme vous avez appris qu\'un antechrist doit venir, maintenant aussi plusieurs antechrists se sont produits; c\'est à quoi nous connaissons que voici l\'heure dernière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Ils sont sortis du milieu de nous, mais ils n\'étaient pas des nôtres, car s\'ils eussent été des nôtres ils seraient demeurés avec nous; mais c\'est afin de rendre manifeste que tous ne sont pas des nôtres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'et quant à vous, vous possédez une onction qui vient de Celui qui est saint; vous le savez tous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Je ne vous ai pas écrit parce que vous ne connaissez point la vérité, mais parce que vous la connaissez, et que vous savez qu\'aucun mensonge ne provient de la vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Qui est le menteur, sinon celui qui nie que Jésus soit le Christ? Celui-là est l\'antechrist; il nie le Père et le Fils;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'quiconque nie le Fils ne possède pas non plus le Père; celui qui confesse le Fils possède aussi le Père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Pour vous, que ce que vous avez ouï dès le commencement demeure en vous! Si ce que vous avez ouï dès le commencement demeure en vous, vous aussi vous demeurerez dans le Fils et dans le Père;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'et la promesse que lui-même vous a faite, c\'est la vie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Je vous ai écrit ces choses relativement à ceux qui vous.égarent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'et quant à vous, la grâce que vous avez reçue de lui demeure en vous, et vous n\'avez pas besoin que personne vous instruise, mais la même onction vous instruit sur toutes choses, et elle est véritable et ce n\'est pas un mensonge, et selon qu\'elle vous a instruits, vous demeurez en lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Et maintenant, petits enfants, demeurez en lui, afin que, lorsqu\'il aura été manifesté, nous ayons une ferme assurance, et que nous n\'ayons pas à nous éloigner de lui en rougissant, lors de son avènement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Si vous savez qu\'il est juste, reconnaissez que quiconque pratique la justice est né de Lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Voyez quel amour le Père vous a témoigné, pour que nous soyons appelés enfants de Dieu, et nous le sommes. Si le monde ne nous connaît pas, c\'est qu\'il ne L\'a pas connu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Bien-aimés, maintenant nous sommes enfants de Dieu, et ce que nous serons n\'a pas encore été manifesté; nous savons que, lorsque cela aura été manifesté, nous Lui serons semblables, parce que nous Le verrons tel qu\'il est;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'et quiconque fonde cette espérance sur Lui se purifie lui-même, comme celui-là est pur.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Quiconque pratique le péché pratique aussi la violation de la loi, et le péché est la violation de la loi;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'et vous savez que celui-là a été manifesté afin d\'enlever les péchés, et il n\'y a pas de péché en lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'quiconque demeure en lui ne pèche point; quiconque pèche ne l\'a point vu, ni ne l\'a point connu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Petits enfants, que personne ne vous séduise! Celui qui pratique la justice est juste, comme celui-là est juste;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'celui qui pratique le péché relève du diable, car dès le commencement le diable pèche. C\'est pour détruire les œuvres du diable, que le fils de Dieu a été manifesté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Quiconque est né de Dieu ne commet point de péché, parce que Sa semence demeure en lui, et il ne peut pas pécher, parce que c\'est de Dieu qu\'il est né.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'C\'est à cela que se reconnaissent les enfants de Dieu et les enfants du diable. Quiconque ne pratique pas la justice n\'est pas de Dieu, non plus que celui qui n\'aime pas son frère;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'car voici le message que vous avez ouï dès le commencement: c\'est que nous nous aimions les uns les autres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'n\'étant pas comme Caïn qui relevait du malin et qui égorgea son frère. Et pourquoi l\'égorgea-t-il? Parce que ses œuvres à lui étaient mauvaises, tandis que celles de son frère étaient justes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Ne vous étonnez pas, frères, si le monde vous hait.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Pour nous, nous savons que nous sommes passés de la mort à la vie, parce que nous aimons les frères; celui qui n\'aime pas demeure dans la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Quiconque hait son frère est un homicide, et vous savez que nul homicide n\'a en lui d\'une manière durable la vie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Voici à quoi nous avons connu l\'amour, c\'est que celui-là a donné sa vie pour nous, et nous aussi nous devons donner notre vie pour nos frères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Aussi, celui qui possédant de quoi vivre en ce monde voit son frère dans le besoin, et lui aura fermé ses entrailles, comment l\'amour de Dieu demeure-t-il en lui?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Petits enfants, n\'aimons pas en paroles ni avec la langue, mais en fait et en vérité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'c\'est ainsi que nous connaîtrons que nous relevons de la vérité, et nous rassurerons notre cœur devant Lui,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'quelque condamnation que porte contre nous notre cœur, parce que Dieu est plus grand que notre cœur, et qu\'il connaît toutes choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Bien-aimés, si notre cœur ne nous condamne pas, nous possédons une ferme assurance devant Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'et, quoi que ce soit que nous demandions, nous le recevons de Lui, parce que nous observons Ses commandements, et que nous faisons ce qui est agréable à Ses yeux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'et voici quel est Son commandement: c\'est que nous croyions au nom de Son fils Jésus-Christ, et que nous nous aimions les uns les autres selon le commandement qu\'Il nous a donné.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Et celui qui observe Ses commandements demeure en Lui, et Lui en lui; et c\'est grâce à l\'Esprit qu\'il nous a donné que nous connaissons qu\'il demeure en nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Bien-aimés, ne croyez pas à tout esprit; mais examinez les esprits pour voir s\'ils sont de Dieu, car beaucoup de faux prophètes ont fait irruption dans le monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Voici à quoi vous reconnaissez l\'Esprit de Dieu: tout esprit qui confesse que Jésus-Christ est venu en chair est de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'et tout esprit qui ne confesse pas Jésus n\'est pas de Dieu, et tel est celui de l\'antechrist, dont vous avez ouï dire qu\'il doit venir, et maintenant il est déjà dans le monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Pour vous, petits enfants, vous êtes de Dieu, et vous les avez vaincus, parce que Celui qui est en vous est plus grand que celui qui est dans le monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Pour eux, ils sont du monde; c\'est pourquoi ils parlent d\'après le monde, et le monde les écoute.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Pour nous, nous sommes de Dieu; celui qui connaît Dieu nous écoute; celui qui n\'est pas de Dieu ne nous écoute point: c\'est à cela que nous reconnaissons l\'esprit de vérité et l\'esprit d\'égarement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Bien-aimés, aimons-nous les uns les autres, parce que l\'amour vient de Dieu, et quiconque aime est né de Dieu et connaît Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, '« celui qui n\'aime pas n\'a pas connu Dieu, car Dieu est amour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Voici comment l\'amour de Dieu a été manifesté envers nous: c\'est que Dieu a envoyé Son fils unique dans le monde, afin que nous vivions par lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Voici en quoi consiste cet amour: c\'est que ce n\'est pas nous qui avons aimé Dieu, mais que c\'est Lui qui nous a aimés et qui a envoyé son fils comme victime expiatoire pour nos péchés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Bien-aimés, si Dieu nous a ainsi aimés, nous aussi nous devons nous aimer les uns les autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Personne n\'a jamais contemplé Dieu; si nous nous aimons les uns les autres, Dieu demeure en nous et Son amour est accompli en nous.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Voici à quoi nous connaissons que nous demeurons en Lui et Lui en nous: c\'est qu\'il nous a donné de Son Esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Et nous-mêmes nous avons vu, et nous l\'attestons, que le Père a envoyé Son fils comme sauveur du monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Quiconque aura confessé que Jésus-Christ est le fils de Dieu, Dieu demeure en lui, et lui en Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Et nous-mêmes nous avons connu l\'amour que Dieu a pour nous et nous y avons cru; Dieu est amour, et celui qui demeure dans l\'amour demeure en Dieu, et Dieu demeure en lui. Voici comment l\'amour est accompli en nous, afin que nous ayons une ferme assurance lors du jour du jugement:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'c\'est que tel qu\'est celui-là, tels nous sommes aussi dans ce monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Il n\'y a pas de crainte dans l\'amour, mais l\'amour accompli chasse la crainte; car la crainte suppose le châtiment, et celui qui craint n\'est pas accompli dans l\'amour.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Pour nous, nous devons aimer, parce qu\'il nous a aimés le premier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Si quelqu\'un dit: J\'aime Dieu, et qu\'il haïsse son frère, c\'est un menteur; car celui qui n\'aime pas son frère qu\'il voit, ne peut pas aimer Dieu qu\'il ne voit pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Et voici le commandement que nous tenons de Lui: c\'est que celui qui aime Dieu aime aussi son frère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Quiconque croit que Jésus est le Christ est né de Dieu, et quiconque aime Celui qui l\'a fait naître, aime celui qui est né de Lui;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'voici à quoi nous reconnaissons que nous aimons les enfants de Dieu: c\'est lorsque nous aimons Dieu et que nous pratiquons Ses commandements;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'car voici en quoi consiste l\'amour de Dieu: c\'est que nous observions Ses commandements; et Ses commandements ne sont point pénibles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'car tout ce qui est né de Dieu remporte la victoire sur le monde; et la victoire qui a vaincu le monde, c\'est notre foi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Or, quel est celui qui remporte la victoire sur le monde, sinon celui qui croit que Jésus est le fils de Dieu?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'C\'est ce Jésus-Christ qui est venu avec de l\'eau et du sang, non pas avec l\'eau seule, mais avec l\'eau et avec le sang; et l\'Esprit est celui qui témoigne, parce que l\'Esprit est la vérité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'car ils sont trois ceux qui témoignent:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'l\'Esprit, et l\'eau, et le sang, et les trois s\'accordent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Si nous recevons le témoignage des hommes, le témoignage de Dieu est plus grand; car c\'est le témoignage de Dieu, puisqu\'il a rendu témoignage à Son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Celui qui croit au fils de Dieu possède en lui-même ce témoignage; celui qui ne croit pas Dieu en fait un menteur, puisqu\'il ne croit pas au témoignage que Dieu a rendu à Son fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Et voici en quoi consiste ce témoignage: c\'est que Dieu nous a donné la vie éternelle, et cette vie est en Son fils;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'celui qui possède le Fils possède la vie; celui qui ne possède pas le fils de Dieu ne possède point la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Je vous ai écrit ces choses, afin que vous sachiez que vous possédez la vie éternelle, vous qui croyez au nom du fils de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Et voici la ferme assurance que nous avons en Lui: c\'est que, si nous demandons quelque chose selon Sa volonté, Il nous écoute;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'et si nous savons qu\'il nous écoute, quoi que ce soit que nous demandions, nous savons que c\'est de Lui que nous obtenons les demandes que nous avons faites.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Si quelqu\'un voit son frère commettre un péché qui n\'entraîne pas la mort, il priera, et Il lui donnera la vie, s\'il s\'agit de péchés qui n\'entraînent pas la mort; il y a un péché qui entraîne la mort, ce n\'est point pour celui-là que je dis qu\'il intercède;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'toute injustice est un péché, et il y a un péché qui n\'entraîne pas la mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Nous savons que quiconque est né de Dieu ne pèche point, mais celui qui est né de Dieu se garde lui-même, et le malin ne le trouve pas.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Nous savons que nous sommes de Dieu, et que le monde entier est sous la puissance du malin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Nous savons aussi que le fils de Dieu est venu, et qu\'il nous a donné l\'intelligence nécessaire pour connaître le Véritable, et nous sommes dans le Véritable, en étant dans Son fils Jésus-Christ. Celui-ci est le véritable Dieu et la vie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Petits enfants, préservez-vous des idoles!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'L\'ancien, à Kyria l\'élue et à ses enfants que j\'aime véritablement (et non pas moi seul, mais encore tous ceux qui ont connu la vérité),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'à cause de la vérité qui demeure en nous et qui sera avec nous pour l\'éternité:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'avec nous sera la grâce, la miséricorde et la paix de la part de Dieu le Père et de la part de Jésus-Christ le fils du Père, dans la vérité et dans l\'amour!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'J\'ai été très fort réjoui de trouver de tes enfants qui marchent dans la vérité, comme nous en avons reçu le commandement du Père.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Et maintenant je te prie, Kyria (non point comme si je t\'adressais un commandement nouveau, mais c\'est celui que nous avions dès le commencement), que nous nous aimions les uns les autres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Et voici en quoi consiste l\'amour: c\'est que nous marchions selon Ses commandements; ce commandement existe, comme vous l\'avez ouï dès le commencement, afin que vous y conformiez votre conduite.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Comme plusieurs séducteurs ont fait irruption dans le monde, lesquels ne confessent point Jésus-Christ venu en chair (c\'est là le séducteur et l\'antechrist),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'prenez garde à vous-mêmes, afin que vous ne perdiez pas le fruit de notre travail, mais que vous receviez une pleine récompense.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Quiconque va en avant et ne demeure pas attaché à l\'enseignement de Christ ne possède point Dieu; celui qui demeure attaché à cet enseignement, celui-là possède et le Père et le Fils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Si quelqu\'un vient à vous et n\'apporte pas cet enseignement, ne le recevez pas dans votre maison et ne lui dites pas: salut;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'car celui qui lui dit: salut, participe à ses mauvaises œuvres,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Quoique j\'eusse beaucoup de choses à vous écrire, je n\'ai pas voulu recourir au papier et à l\'encre, mais j\'espère me rendre auprès de vous et vous parler bouche à bouche, afin que votre joie soit complète.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Les enfants de ta sœur l\'élue te saluent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'L\'ancien, à Gaïus le bien-aimé que j\'aime véritablement!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Bien-aimé, je te souhaite qu\'à tous égards tu prospères et sois en bonne santé, comme prospère ton âme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'car j\'ai été très fort réjoui de l\'arrivée des frères qui ont rendu témoignage à ta vérité, à la manière, dis-je, dont tu marches dans la vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Je n\'ai pas de plus grande grâce que d\'apprendre que mes enfants marchent dans la vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Bien-aimé, tu accomplis fidèlement tout ce que tu as à faire pour les frères, bien qu\'ils soient étrangers;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'lesquels ont rendu témoignage à ta charité à la face de l\'église, et au voyage desquels tu feras bien de pourvoir d\'une manière digne de Dieu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'car c\'est pour le nom qu\'ils sont partis sans rien recevoir des Gentils.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Nous devons donc nous intéresser à eux, afin de coopérer avec eux pour la vérité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Tu as écrit quelques mots à l\'église; mais Diotrèphe, qui s\'arroge parmi eux le premier rang, ne nous admet pas;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'c\'est pourquoi, si je viens, je signalerai les actes auxquels il se livre, lui qui se répand contre nous en de méchants propos et qui non content de cela, non seulement n\'accueille pas lui-même les frères, mais s\'oppose à ceux qui veulent le faire et les chasse de l\'église.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Bien-aimé, n\'imite pas le mal, mais le bien; celui qui fait le bien est de Dieu; celui qui fait le mal n\'a point vu Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Démétrius a pour lui le témoignage de tous et de la vérité elle-même; et nous aussi nous lui rendons témoignage, et tu sais que notre témoignage est véridique.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'J\'aurais beaucoup de choses à t\'écrire, mais je ne veux pas t\'écrire avec l\'encre et le roseau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'mais j\'espère te voir bientôt, et nous parlerons bouche à bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Judas, esclave de Jésus-Christ, et frère de Jacques, à ceux qui ont été appelés, qui sont aimés en Dieu le Père et gardés par Jésus-Christ:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'que la miséricorde, et la paix, et la charité vous soient multipliées!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Bien-aimés, comme j\'étais tout occupé du désir de vous écrire sur notre salut commun, j\'ai été forcé de vous écrire afin de vous exhorter à combattre pour la foi, qui a été une fois pour toutes transmise aux saints.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'En effet certains hommes se sont glissés, qui d\'avance ont été jadis désignés pour ce jugement: des impies, qui transforment en débauche la grâce de notre Dieu, et qui renient notre seul maître et seigneur, Jésus-Christ.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Mais je veux vous rappeler, à vous qui savez tout une fois pour toutes, que Jésus, après avoir tiré le peuple hors du pays d\'Egypte, fit, en second lieu, périr ceux qui n\'avaient pas cru;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'et qu\'il retient dans l\'obscurité, par des chaînes éternelles, pour le jugement du grand jour, les anges qui n\'ont pas conservé leur propre puissance, mais qui ont abandonné leur séjour naturel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'que Sodome et Gomorrhe et les villes circonvoisines, qui, de la même manière, s\'étaient livrées à l\'impudicité et charnellement adonnées à des unions contre nature, subsistent sous le coup de leur châtiment comme une image du feu éternel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Néanmoins, ces hommes aussi, frappés d\'hallucination, d\'un côté souillent également la chair, de l\'autre méprisent la Seigneurie et calomnient les gloires.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Lorsque Michel l\'archange, discutant jadis avec le diable, lui disputait le corps de Moïse, il n\'osa pas porter contre lui un jugement calomniateur, mais il dit: « Que le Seigneur te réprimande! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Mais, pour eux, ils calomnient tout ce qu\'ils ignorent, tandis que tout ce qu\'ils connaissent naturellement comme les animaux privés de raison, c\'est par là qu\'ils se perdent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Malheur à eux, car ils ont suivi le chemin de Caïn, et ils se sont jetés en vue du gain, dans l\'égarement de Balaam, et ils se sont perdus par la rébellion de Coré.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Ce sont eux qui sont les écueils dans vos agapes, y faisant effrontément bonne chère, se paissant eux-mêmes: nuages sans eau poussés par les vents; arbres d\'automne privés de fruits, deux fois morts, déracinés;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'flots de la mer furieux, rejetant l\'écume de leurs propres infamies; astres errants, auxquels l\'obscurité des ténèbres est réservée pour l\'éternité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Or, c\'est aussi pour eux qu\'a prophétisé Enoch, le septième depuis Adam, en disant: « Voici, le Seigneur est venu avec Ses saintes myriades');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'pour porter un jugement contre tous les hommes et pour faire rendre compte à tous les impies de toutes les œuvres d\'impiété qu\'ils ont commises, et de toutes les paroles insultantes qu\'ont proférées contre Lui des pécheurs impies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Ce sont des mécontents qui murmurent sur leur sort; ils suivent leurs propres convoitises, et leur bouche profère d\'orgueilleux, discours; ils admirent les gens par motif d\'utilité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Mais, pour vous, bien-aimés, souvenez-vous des paroles qu\'ont prononcées d\'avance les apôtres de notre Seigneur Jésus-Christ;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'car ils vous disaient: « Dans l\'époque dernière il y aura des railleurs, qui suivront leurs propres convoitises pleines d\'impiété. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Ce sont ceux qui se séparent, hommes animaux qui n\'ont pas l\'esprit;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'mais, pour vous, bien-aimés, vous établissant vous-mêmes sur la base de votre très sainte foi, priant par l\'esprit saint,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'maintenons-nous nous-mêmes dans la charité de Dieu, attendant la miséricorde de notre seigneur Jésus-Christ pour la vie éternelle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Et quant aux uns, ayez-en pitié; s\'ils hésitent, sauvez-les, en les arrachant du feu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'mais quant aux autres, ayez en pitié avec crainte, vous qui devez haïr, même la tunique souillée par la chair.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Or, c\'est à Celui qui peut vous préserver de tout faux pas, et vous faire paraître devant Sa gloire irrépréhensibles et pleins d\'allégresse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'au seul Dieu, notre Sauveur par Jésus-Christ notre seigneur, qu\'appartiennent la gloire, la majesté, la force et l\'autorité, dès avant toute la durée du temps, et maintenant, et pour tous les siècles. Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Révélation de Jésus-Christ, que Dieu lui a donnée pour montrer à Ses esclaves ce qui doit arriver au plus tôt, et qu\'il a fait connaître en l\'envoyant, par Son ange Son esclave, à Jean');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'qui a rendu témoignage à la parole de Dieu et au témoignage de Jésus-Christ en tout ce qu\'il a vu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Heureux celui qui lit et ceux qui entendent les paroles de la prophétie et qui observent ce qui y est écrit, car le moment est proche!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Jean aux sept Églises qui sont en Asie: La grâce et la paix vous soient données par Celui qui est et qui était et qui doit venir, et par les sept esprits qui sont devant Son trône,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'et par Jésus-Christ, lui qui est le témoin fidèle, le premier-né des morts et le chef des rois de la terre! A celui qui nous aime et qui nous a délivrés de nos péchés par son sang,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'et il a fait pour nous un royaume, des prêtres pour Dieu son Père, à lui soit la gloire et la puissance pour les siècles. Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Voici, il vient avec les nuées, Et tout œil le verra, Et ceux entre autres qui l\'ont transpercé. Et toutes les tribus de la terre se lamenteront à cause de lui. Oui! Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, '« Je suis l\'alpha et l\'oméga », dit le Seigneur Dieu, Qui est et qui était et qui doit venir, Le Tout-Puissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Moi, Jean, votre frère, qui ai part avec vous à la tribulation et au royaume et à la constance en Christ, je me suis trouvé dans l\'île appelée Patmos, à cause de la parole de Dieu et du témoignage de Jésus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Je me trouvai inspiré dans la journée dominicale, et j\'entendis derrière moi une voix forte comme d\'une trompette');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'qui disait: « Ce que tu vois, écris-le dans un livre et envoie-le aux sept Églises, à Éphèse, et à Smyrne, et à Pergame, et à Thyatire, et à Sardes, et à Philadelphie, et à Laodicée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Et je me retournai pour voir la voix qui me parle, et après m\'être retourné, je vis sept candélabres d\'or,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'et au milieu des candélabres un être semblable à un fils d\'homme, revêtu d\'une longue robe, et ceint sur ses mamelles d\'une ceinture d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Mais sa tête et ses cheveux étaient blancs comme de la laine blanche comme neige; et ses yeux étaient comme une flamme de feu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'et ses pieds étaient semblables à de l\'airain brillant, comme dans le foyer d\'une fournaise; et sa voix était comme un bruit de grosses eaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'et il y avait dans sa main droite sept étoiles; et de sa bouche sortait un glaive acéré à deux tranchants; et son visage était comme le soleil quand il brille dans sa force.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Et lorsque je le vis, je tombai à ses pieds comme mort, et il posa sa main droite sur moi, en disant: « Ne crains point; c\'est moi qui suis le premier-né et le dernier,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'et le vivant; et j\'ai été mort, et voici, je suis vivant aux siècles des siècles; et je tiens les clefs de la mort et du séjour des morts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Mets donc par écrit les choses que tu as vues et ce qu\'elles sont, et celles qui doivent avoir lieu après celles-là,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'le mystère des sept étoiles que tu as vues dans ma main droite, et les sept candélabres d\'or: les sept étoiles sont les anges des sept Églises, et les sept candélabres sont les sept Églises. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, '« Écris à l\'ange de l\'Église qui est dans Éphèse: Voici ce que dit celui qui tient les sept étoiles dans sa main droite, celui qui marche au milieu des sept candélabres d\'or:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Je connais tes œuvres et ta peine et ta constance, car tu ne peux supporter les méchants; et tu as mis à l\'épreuve ceux qui se disent apôtres et qui ne le sont point, et tu les as trouvés menteurs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Et tu as de la constance, et tu as eu à souffrir à cause de mon nom, et tu n\'as pas faibli.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Mais je te reproche d\'avoir abandonné ta charité première.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Souviens-toi donc d\'où tu es tombé, repens-toi, et pratique tes premières œuvres; sinon, je vais venir à toi, et j\'ôterai ton candélabre de sa place, à moins que tu ne te repentes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Mais tu as en ta faveur de haïr les œuvres des Nicolaïtes, et moi aussi je les hais.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Que celui qui a une oreille entende ce que l\'Esprit dit aux sept Églises: Au vainqueur je donnerai à manger de l\'arbre de la vie, qui est dans le paradis de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, '« Écris aussi à l\'ange de l\'Église qui est dans Smyrne: Voici ce que dit le premier-né et le dernier, qui a été mort et il a vécu:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Je connais ta tribulation et ton indigence (pourtant tu es riche), et les calomnies de ceux qui disent qu\'ils sont Juifs, et ils ne le sont point, mais ils sont une synagogue de Satan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Ne crains point les souffrances que tu vas endurer. Voici, le diable va jeter quelques-uns de vous en prison, afin que vous soyez mis à l\'épreuve, et que vous souffriez une persécution de dix jours. Sois fidèle jusques à la mort, et je te donnerai la couronne de vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Que celui qui a une oreille entende ce que l\'Esprit dit aux Églises: Le vainqueur ne sera certainement point atteint par la seconde mort. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, '« Écris aussi à l\'ange de l\'Église qui est dans Pergame: Voici ce que dit celui qui tient le glaive acéré à deux tranchants:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Je sais où tu habites, et que là se trouve le trône de Satan; cependant tu retiens mon nom, et tu n\'as pas renié ma foi, même dans le temps d\'Antipas, mon témoin, mon fidèle, qui a été mis à mort chez vous, là où habite Satan.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Mais j\'ai quelques reproches à te faire, car tu as là des gens qui retiennent la doctrine de Balaam, lequel enseignait au roi Balak, comme pierre d\'achoppement devant les fils d\'Israël, à manger des viandes offertes aux idoles, et à se livrer à l\'impudicité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'De même toi aussi tu as des gens qui retiennent d\'une manière semblable la doctrine des Nicolaïtes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Repens-toi donc, sinon je vais promptement venir à toi, et je combattrai contre eux avec le glaive qui sort de ma bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Que celui qui a une oreille entende ce que l\'Esprit dit aux Églises: Au vainqueur je donnerai de la manne cachée, et je lui donnerai un caillou blanc, et sur ce caillou est écrit un nouveau nom, que personne ne connaît, sinon celui qui le reçoit. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, '« Écris aussi à l\'ange qui est dans Thyatire: Voici ce que dit le fils de Dieu, celui qui a les yeux comme une flamme de feu, et dont les pieds sont semblables à de l\'airain brillant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Je connais tes œuvres et ta charité et ta foi et ton service et ta constance, et tes dernières œuvres plus nombreuses que les premières.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Mais je te reproche de laisser faire ta femme, la Jésabel qui se dit prophétesse, et elle instruit et entraîne mes esclaves à se livrer à l\'impudicité et à manger des viandes offertes aux idoles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Et je lui ai donné du temps afin qu\'elle se repentît, et elle n\'a pas voulu se repentir de son impudicité.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Voici, je vais la jeter en prison, et ses complices adultères dans une grande tribulation, à moins qu\'ils ne se repentent de leurs œuvres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'je ferai mourir de mort ses enfants, et toutes les Églises sauront que c\'est moi qui suis celui qui sonde les reins et les cœurs, et je vous rendrai à chacun selon vos œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Mais je vous le déclare, à vous tous autres de Thyatire qui ne suivez pas cette doctrine, étant de ceux qui n\'ont pas connu ce qu\'ils appellent les profondeurs de Satan: je ne vous impose point d\'autre fardeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Seulement ce que vous avez, retenez-le jusques à ce que je vienne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Et le vainqueur, et celui qui observe jusques à la fin mes œuvres, je lui donnerai autorité sur les nations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'et il les paîtra avec une verge de fer, comme sont brisés les vases d\'argile. De même que moi de mon côté je l\'ai reçue de mon Père,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'je lui donnerai l\'étoile matinale.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Que celui qui a une oreille entende ce que l\'Esprit dit aux Églises. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, '« Écris aussi à l\'ange de l\'Église qui est dans Sardes: Voici ce que dit celui qui possède les sept esprits de Dieu et a les sept étoiles: Je connais tes œuvres; je sais que tu passes pour être vivant, tandis que tu es mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Deviens vigilant et fortifie le reste qui s\'en allait mourir, car je n\'ai pas trouvé tes œuvres parfaites devant mon Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Souviens-toi donc comment tu as reçu et entendu, et observe, et repens-toi. Si tu ne veilles donc pas, j\'arriverai comme un voleur, et tu ne sauras point à quelle heure j\'arriverai sur toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Cependant tu as à Sardes un petit nombre de personnes qui n\'ont pas souillé leurs vêtements, et qui marcheront avec moi dans des vêtements blancs, car elles en sont dignes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Le vainqueur sera ainsi revêtu de vêtements blancs, et je n\'effacerai certainement point son nom du livre de la vie, et je confesserai son nom devant mon Père et devant Ses anges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Que celui qui a une oreille entende ce que l\'Esprit dit aux Églises. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, '« Écris aussi à l\'ange de l\'Église qui est dans Philadelphie: Voici ce que dit le véritable, le saint, celui qui tient la clef de David, celui qui ouvre et personne ne fermera, qui ferme et personne n\'ouvre:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Je connais tes œuvres; voici, j\'ai mis devant toi une porte ouverte que personne ne peut fermer; car tu as une faible puissance, et tu as observé ma parole, et tu n\'as pas renié mon nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Voici, je permets que de la synagogue de Satan, de ceux qui se disent eux-mêmes Juifs, et ils ne le sont pas, mais ils mentent.... voici, je ferai qu\'ils viennent adorer à tes pieds, et qu\'ils sachent que moi je t\'ai aimé,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'et que tu as observé la leçon de constance que je t\'ai donnée; et moi de mon côté je te préserverai de l\'heure de la tentation, qui va venir sur l\'univers entier afin de mettre à l\'épreuve les habitants de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Je vais venir promptement; retiens ce que tu as, afin que personne n\'enlève ta couronne.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Le vainqueur, j\'en ferai une colonne dans le sanctuaire de mon Dieu, et il n\'en sortira certainement plus, et j\'écrirai dessus le nom de mon Dieu et le nom de la ville de mon Dieu, de la nouvelle Jérusalem, laquelle descend du ciel d\'auprès de mon Dieu, et mon nouveau nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Que celui qui a une oreille entende ce que l\'Esprit dit aux Églises. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, '« Écris aussi à l\'ange de l\'Église qui est dans Laodicée: Voici ce que dit l\' amen, le témoin qui est fidèle et véritable, le commencement de la création de Dieu:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Je connais tes œuvres; je sais que tu n\'es ni froid, ni bouillant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Ainsi parce que tu es tiède, et non pas froid ni bouillant, je vais te vomir de ma bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'En effet tu dis: je suis riche et je me suis enrichi, et je n\'ai besoin de rien; et tu ne sais pas que toi tu es le malheureux et le misérable, et pauvre, et aveugle, et nu!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Je te conseille d\'acheter de moi de l\'or affiné au feu afin de t\'enrichir, et des vêtements blancs afin de te vêtir et de ne pas laisser paraître la honte de ta nudité, et un collyre pour enduire tes yeux afin que tu voies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Pour moi, tous ceux que j\'aime, je les reprends et je les châtie; sois donc zélé, et repens-toi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Voici, je me tiens auprès de la porte et je heurte: si quelqu\'un entend ma voix et qu\'il ouvre la porte, j\'entrerai chez lui, et je souperai avec lui, et lui avec moi.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Le vainqueur, je le ferai asseoir avec moi sur mon trône, comme moi de mon côté j\'ai vaincu et me suis assis avec mon Père sur Son trône.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Que celui qui a une oreille entende ce que l\'Esprit dit aux Églises. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Après cela je vis, et voici, une porte était ouverte dans le ciel, et la première voix que j\'avais entendue, comme d\'une trompette qui me parlait, disait: « Monte ici, et je te montrerai tout ce qui doit arriver après cela. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Aussitôt je me trouvai inspiré; et voici, un trône était dressé dans le ciel, et sur ce trône Quelqu\'un était assis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Et Celui qui était assis était semblable par Son aspect à une pierre de jaspe et de cornaline, et il y avait autour du trône un arc-en-ciel semblable par son aspect à une émeraude.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Et autour du trône je vis vingt-quatre trônes, et sur les vingt-quatre trônes des anciens assis, revêtus de vêtements blancs, et sur leurs têtes des couronnes d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Et du trône sortent des éclairs, et des voix, et des tonnerres; et sept lampes de feu brûlent devant le trône, qui sont les sept esprits de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Et devant le trône il y a comme une mer vitreuse semblable à du cristal; et au milieu du trône et autour du trône il y a quatre animaux pleins d\'yeux par devant et par derrière.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Et le premier animal est semblable à un lion, et le second animal est semblable à un veau, et le troisième animal a le visage comme d\'un homme, et le quatrième animal est semblable à un aigle qui vole.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Et les quatre animaux, chacun d\'eux ayant six ailes, sont remplis d\'yeux tout autour et intérieurement; et ils ne cessent jour et nuit de dire: « Saint, saint, saint, le Seigneur Dieu, Le Tout-Puissant, Qui était et qui est et qui doit venir! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Et tant que les animaux rendront gloire, honneur et actions de grâces à Celui qui est assis sur le trône, à Celui qui vit aux siècles des siècles,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'les vingt-quatre anciens se prosterneront devant Celui qui est assis sur le trône et adoreront Celui qui vit aux siècles des siècles, et jetteront leurs couronnes devant le trône en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, '« Tu es digne, notre Seigneur et notre Dieu, De recevoir la gloire, et l\'honneur, et la puissance; Car Tu as créé toutes choses, Et c\'est par Ta volonté qu\'elles ont eu l\'être. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Puis je vis dans la main droite de Celui qui était assis sur le trône un livre écrit intérieurement et sur le revers, scellé de sept sceaux.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Et je vis un ange puissant criant d\'une voix forte: « Qui est-ce qui est digne d\'ouvrir le livre, et d\'en rompre les sceaux? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Et personne dans le ciel, ni sur la terre, ni sous la terre, ne pouvait ouvrir le livre ni le regarder.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Et moi je pleurais abondamment, en voyant qu\'il ne se trouvait personne qui fût digne d\'ouvrir le livre ni de le regarder.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Et l\'un des anciens me dit: « Ne pleure pas. Voici, il a réussi, le lion de la tribu de Juda, la racine de David, à ouvrir le livre et ses sept sceaux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Et voici, au milieu du trône et des quatre animaux et au milieu des anciens, était un agneau qui paraissait immolé: il avait sept cornes, et sept yeux qui sont les esprits de Dieu envoyés sur toute la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Et il vint, et il prît de la main droite de Celui qui était assis sur le trône,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'et lorsqu\'il eut pris le livre, les quatre animaux et les vingt-quatre anciens se prosternèrent devant l\'agneau, tenant chacun une harpe et des coupes d\'or pleines de parfums, qui sont les prières des saints, et ils chantent un chant nouveau, en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, '« Tu es digne de prendre le livre et d\'en ouvrir les sceaux, Car tu as été immolé, Et tu as racheté pour Dieu, par ton sang, Des gens de toute tribu, langue, peuple et nation,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Et tu en as fait un royaume et des prêtres, Et ils règnent sur la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Et je vis, et j\'entendis la voix d\'anges nombreux autour du trône et des animaux et des anciens; et leur nombre se comptait par myriades de myriades et par milliers de milliers. Ils disaient d\'une voix forte:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, '« L\'agneau qui a été immolé est digne de recevoir la puissance, et la richesse, et la sagesse, et la force, et l\'honneur, et la gloire, et la bénédiction! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Et tous les êtres créés qui sont dans le ciel et sur la terre et sous la terre et sur la mer, et toutes les choses qui s\'y trouvent, je les entendis qui disaient: « A l\'agneau qui est assis sur le trône appartiennent la bénédiction, l\'honneur, la gloire, et la puissance, aux siècles des siècles! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Et les quatre animaux disaient: « Amen! » Et les anciens se prosternèrent et adorèrent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Et je vis lorsque l\'agneau ouvrit un des sept sceaux, et j\'entendis l\'un des quatre animaux qui disait comme une voix de tonnerre: « Viens. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Et je vis, et voici venir un cheval blanc; et celui qui était assis dessus tenait un arc, et on lui donna une couronne, et il sortit en vainqueur, et pour remporter la victoire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Et lorsqu\'il ouvrit le second sceau, j\'entendis le second animal qui disait: « Viens. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Et il sortit un autre cheval de feu; et à celui qui était assis dessus il fut donné d\'enlever la paix de la terre, et de les faire s\'entr\'égorger; et on lui donna une grande épée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Et lorsqu\'il ouvrit le troisième sceau, j\'entendis le troisième animal qui disait: Viens. » Et je vis, et voici venir un cheval noir, et celui qui était assis dessus tenait une balance dans sa main;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'et j\'entendis comme une voix au milieu des quatre animaux, qui disait: « Une mesure de blé pour un denier, et trois mesures d\'orge pour un denier, et ne fais de mal ni à l\'huile ni au vin. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Et lorsqu\'il ouvrit le quatrième sceau, j\'entendis la voix du quatrième animal qui disait: « Viens. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Et je vis, et voici venir un cheval livide; et celui qui était assis dessus s\'appelait l\'immortel, et le séjour des morts l\'accompagnait, et il leur fut donné autorité sur le quart de la terre pourn faire périr par l\'épée et par la famine et par la mortalité, même le quart des bêtes de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Et lorsqu\'il ouvrit le cinquième sceau, je vis sous l\'autel les âmes de ceux qui ont été immolés à cause de la parole de Dieu, et du témoignage qu\'ils avaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Et ils crièrent d\'une voix forte: « Jusques à quand, ô Souverain, Toi qui es saint et véritable, diffères-tu Ton jugement et la vengeance de notre sang sur les habitants de la terre? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Et il leur fut donné à chacun une robe blanche, et il leur fut dit de demeurer en repos encore pour un peu de temps, jusques à ce que fussent au complet et leurs compagnons de service et leurs frères, qui vont être mis à mort comme eux-mêmes l\'ont été.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Et je vis lorsqu\'il ouvrit le sixième sceau, et voici, il se fit un grand tremblement de terre, et le soleil devint noir comme un sac de crin, et la lune entière devint comme du sang,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'et les étoiles de Dieu tombèrent sur la terre, comme un figuier laisse tomber ses figues tardives, quand il est secoué par un grand vent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'le ciel se replia comme un livre qu\'on enroule, et toutes les montagnes et toutes les îles furent déplacées des lieux qu\'elles occupaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Et les rois de la terre, et les grands, les généraux, et les riches, et les puissants, et tout esclave, et tout homme libre se cachèrent dans les cavernes et dans les rochers des montagnes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'et ils disent aux montagnes et aux rochers: « Tombez sur nous, et cachez-nous aux regards de Celui qui est assis sur le trône, et à la colère de l\'agneau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'car il est arrivé le grand jour de sa colère. Et qui est-ce qui peut subsister? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Après cela je vis quatre anges debout aux quatre coins de la terre, retenant les quatre vents de la terre, afin qu\'aucun vent ne soufflât, ni sur la mer, ni sur aucun arbre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Puis je vis un autre ange qui montait du côté où se lève le soleil, et qui tenait le sceau du Dieu vivant. Et il criait d\'une voix forte aux quatre anges auxquels il avait été donné de faire du mal à la terre et à la mer,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'en disant: « Ne faites point de mal à la terre et à la mer, ni aux arbres, jusques à ce qu\'avec le sceau nous ayons marqué au front les esclaves de notre Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Il y eut cent quarante-quatre mille marqués, pris de chaque tribu des fils d\'Israël:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'De la tribu de Juda, douze mille marqués; de la tribu de Ruben, douze mille; de la tribu de Gad, douze mille;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'de la tribu d\'Aser, douze mille; de la tribu de Nephthalim, douze mille; de la tribu de Manassé, douze mille;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'de la tribu de Siméon, douze mille; de la tribu de Lévi, douze mille; de la tribu d\'Issachar, douze mille;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'de la tribu de Zabulon, douze mille; de la tribu de Joseph, douze mille; de la tribu de Benjamin, douze mille marqués.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Après cela je vis une foule nombreuse, et personne ne pouvait la compter, tirée de chaque nation, et des tribus, des peuples, et des langues; ils se tenaient debout sur le trône et devant l\'agneau, revêtus de robes blanches, et des palmes dans leurs mains; et ils s\'écrient d\'une voix forte:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, '« Le salut de notre Dieu appartient à Celui qui est assis sur le trône et à l\'agneau. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Et tous les anges se tenaient debout autour du trône et des anciens et des quatre animaux, et ils se prosternèrent devant le trône sur leurs visages et ils adorèrent Dieu en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, '« Amen! La bénédiction, et la gloire, et l\'action de grâces, et l\'honneur, et la puissance, et la force appartiennent à notre Dieu, aux siècles des siècles. » Amen!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Et l\'un des anciens, s\'adressant à moi, reprit: « Ceux-là qui sont revêtus de robes blanches, qui sont-ils, et d\'où sont-ils venus? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Et je lui répliquai: Seigneur, tu le sais. » Et il me dit: « Ceux-là sont ceux qui viennent d\'une grande tribulation; et ils ont lavé leurs robes et ils les ont blanchies dans le sang de l\'agneau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'c\'est pourquoi ils se tiennent devant le trône de Dieu, et L\'adorent nuit et jour dans Son sanctuaire. Et Celui qui est assis sur le trône dressera au-dessus d\'eux Sa tente;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'ils n\'auront plus faim, ils n\'auront plus soif; ni le soleil, ni aucune chaleur ne les frappera;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'parce que l\'agneau qui est au milieu du trône les paîtra, et les conduira vers des sources d\'eaux vivifiantes; et Dieu essuiera toute larme de leurs yeux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Et, lorsqu\'il ouvrit le septième sceau, il y eut dans le ciel un silence d\'environ une demi-heure.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Et je vis les sept anges qui se tiennent debout devant Dieu, et on leur donna sept trompettes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Et un autre ange vint, et il se tint debout sur l\'autel, tenant un encensoir d\'or, et on lui donna beaucoup de parfums, afin qu\'il les offrît, pour les prières de tous les saints, sur l\'autel d\'or qui est devant le trône,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'et la fumée des parfums monta, pour les prières des saints, de la main de l\'ange devant Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Et l\'ange prit l\'encensoir, et il le remplit du feu de l\'autel, et ils le prirent pour le porter sur la terre; et il y eut des tonnerres et des éclairs et des voix et un tremblement de terre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'et les sept anges qui tenaient les sept trompettes se préparèrent à sonner.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Et le premier sonna de la trompette, et il y eut de la grêle et du feu, mêlés de sang, et ils furent jetés sur la terre; et le tiers de la terre fut brûlé, et le tiers des arbres fut brûlé, et toute herbe verte fut brûlée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Et le second ange sonna de la trompette, et une masse semblable à une grande montagne embrasée par le feu fut jetée dans la mer; et le tiers de la mer devint du sang,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'et le tiers des créatures habitant dans la mer qui ont vie mourut, et le tiers des navires fut détruit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Et le troisième ange sonna de la trompette, et une grande étoile, brûlant comme une lampe, tomba du ciel, et elle tomba sur le tiers des fleuves;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'et le nom de cette étoile est l\'absinthe, et le tiers des eaux fut changé en absinthe, et la plupart des hommes moururent sur les eaux, parce qu\'elles étaient devenues amères.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Le quatrième ange sonna de la trompette; et le tiers du soleil fut frappé, ainsi que le tiers de la lune et le tiers des étoiles, afin que le tiers d\'iceux fût dans les ténèbres, et que le jour ne donnât pas le quart de sa lumière, et la nuit de même.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Et je vis, et j\'entendis un aigle, qui volait dans le milieu du ciel, dire d\'une voix forte: « Malheur, malheur, malheur aux habitants de la terre, à cause des autres voix de la trompette des trois anges qui vont sonner! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Et le cinquième ange sonna de la trompette, et je vis une étoile tomber du ciel sur la terre. Et on lui donna la clef du puits de l\'abîme;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'et il ouvrit le puits de l\'abîme; et une fumée monta du puits, fumée d\'une grande fournaise, et le soleil et l\'air furent obscurcis par la fumée du puits.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'Et de la fumée sortirent des sauterelles qui se répandirent sur la terre, et il leur fut donné une puissance semblable à la puissance que possèdent les scorpions de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'Et il leur fut dit de ne faire aucun mal à l\'herbe de la terre, ni à aucune verdure, ni à aucun arbre, mais à ceux des hommes qui n\'ont pas le sceau de Dieu sur leurs fronts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Et il leur fut donné, non pas de les faire périr, mais qu\'ils fussent tourmentés pendant cinq mois; et le tourment qu\'elles causent est semblable à celui que cause le scorpion lorsqu\'il frappe un homme.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Et en ces jours-là les hommes chercheront la mort, et ils ne la trouveront certainement pas, et ils désireront mourir, et la mort les fuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Et les sauterelles ressemblaient à des chevaux harnachés pour la guerre; et sur leurs têtes il y avait comme des couronnes qui semblaient d\'or, et leurs visages étaient comme des visages d\'hommes,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'et elles avaient des cheveux comme des cheveux de femmes, et leurs dents étaient comme celles des lions;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'et elles portaient des cuirasses, qui semblaient des cuirasses de fer, et le bruit de leurs ailes était comme le bruit de chars à plusieurs chevaux courant au combat;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'et elles ont des queues semblables aux scorpions et des aiguillons; et c\'est dans leurs queues que gît leur puissance de faire du mal aux hommes pendant cinq mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Elles ont à leur tête, comme roi, le chef de l\'abîme, l\'ange dont le nom est en hébreu Abaddon, et en grec il porte le nom d\'Apollyon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Le premier malheur est passé. Voici, il vient encore deux malheurs après cela.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Et le sixième ange sonna de la trompette, et j\'entendis une voix, sortant des cornes de l\'autel d\'or qui est devant Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'disant à l\'ange: « Toi qui tiens la trompette, délie les quatre anges qui sont liés auprès du grand fleuve d\'Euphrate. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Et les quatre anges, qui s\'étaient tenus prêts pour l\'heure et le jour et le mois et l\'année, furent déliés afin de faire périr le tiers des hommes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Et le nombre des armées de la cavalerie est de deux myriades de myriades; j\'en entendis le nombre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Et ainsi je vis les chevaux dans la vision, et ceux qui étaient assis dessus portant des cuirasses couleur de feu, d\'hyacinthe et de soufre; et les têtes des chevaux sont comme des têtes de lions; et de leurs bouches sort du feu, et de la fumée, et du soufre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Par ces trois fléaux périt le tiers des hommes, grâce au feu et à la fumée et au soufre qui sortent de leurs bouches;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'car les lieux où gît leur puissance sont leurs bouches et leurs queues; leurs queues en effet sont semblables à des serpents, elles ont des têtes, et c\'est par leur moyen qu\'ils font du mal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Et les autres hommes, qui n\'avaient pas péri par ces fléaux, ne se repentirent pas non plus des œuvres de leurs mains, pour ne plus adorer les démons, et les idoles d\'or, et d\'argent, et d\'airain, et de pierre, et de bois, qui ne peuvent ni regarder, ni entendre, ni marcher,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'et ils ne se repentirent ni de leurs meurtres, ni de leurs sortilèges, ni de leur méchanceté, ni de leurs larcins.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Et je vis un autre ange puissant, descendant du ciel, enveloppé d\'un nuage, et l\'arc-en-ciel était sur sa tête, et son visage était comme le soleil, et ses pieds comme des colonnes de feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'Et il tenait dans sa main un petit livre, et il mit son pied droit sur la mer, et le gauche sur la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'Et il cria d\'une voix forte comme rugit un lion, et lorsqu\'il cria les sept tonnerres firent retentir leurs voix,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'et lorsque les sept tonnerres parlèrent j\'allais écrire, et j\'entendis une voix venant du ciel, qui disait: « Scelle ce dont ont parlé les sept tonnerres et ne l\'écris point. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Et l\'ange, que j\'avais vu se tenir debout sur la mer et sur la terre, éleva sa main vers le ciel,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'et il jura par Celui qui vit aux siècles des siècles, qui a créé le ciel et les choses qui y sont: « Il n\'y aura plus de délai,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'mais dans les jours de la voix du septième ange, quand il sera sur le point de sonner, alors aura été accompli le mystère de Dieu, selon la bonne nouvelle qu\'il a donnée à Ses esclaves les prophètes. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Et la voix, que j\'avais entendue venant du ciel, je l\'entendis me parler derechef et me dire: « Va, prends le livre qui est ouvert dans la main de l\'ange qui se tient debout sur la mer et sur la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Et j\'allai vers l\'ange, lui disant de me donner le petit livre, et il me dit: « Prends-le et avale-le, et il aigrira ton cœur, mais dans ta bouche il sera doux comme du miel. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Alors je pris le petit livre de la main de l\'ange, et je l\'avalai, et il fut dans ma bouche doux comme du miel; et quand je l\'eus mangé, mon estomac en fut aigri.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Et ils me disent: « Il faut que tu prophétises derechef sur des peuples, et des nations, et des langues, et des rois nombreux. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Et l\'on me donna un roseau semblable à un bâton, en disant: « Lève-toi, et mesure le sanctuaire de Dieu, et l\'autel, et les adorateurs qui s\'y trouvent;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'et laisse en dehors le parvis qui est en dehors du sanctuaire et ne le mesure point, car il a été donné aux nations, et elles mesureront la ville sainte pendant quarante-deux mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Et je chargerai mes deux témoins de prophétiser pendant mille deux cent soixante jours, revêtus de sacs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Ce sont eux qui sont les deux oliviers et les deux candélabres qui se tiennent debout devant le Seigneur de la terre. Je lui dis: Que sont ces deux oliviers, à droite et à gauche du candélabre?.... Et il me dit: Ce sont les deux fils de l\'huile (oints) qui se tiennent debout auprès du Seigneur de toute la terre »;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'et si quelqu\'un veut leur faire du mal, du feu sort de leur bouche et dévore leurs ennemis, et si quelqu\'un a voulu leur faire du mal, il faut qu\'il périsse.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Ils ont l\'autorité de fermer le ciel, afin que la pluie ne tombe pas pendant les jours de leur prédication; et ils ont autorité sur les eaux, de manière à les tourner en sang, et ils peuvent frapper la terre de toute espèce de fléau, aussi souvent qu\'ils le voudront.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Et, lorsqu\'ils auront terminé leur témoignage, la quatrième bête qui monte de l\'abîme leur fera la guerre, et les vaincra, et les fera périr;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'et leur cadavre sera gisant sur la rue de la grande ville (qui est appelée dans un sens spirituel Sodome et Egypte), là où leur Seigneur aussi a été crucifié. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Et d\'entre les peuples, et les tribus, et les langues, et les nations, il y en a qui regardent leur cadavre durant trois jours et demi, et ils ne permettent pas qu\'on mette leurs cadavres dans un sépulcre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'et les habitants de la terre se réjouissent à leur sujet, et ils sont dans la joie, et ils s\'enverront les uns aux autres des présents, car ces deux prophètes ont tourmenté les habitants de la terre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Et, au bout des trois jours et demi, un esprit de vie venu de Dieu entra en eux, et ils se tinrent debout sur leurs pieds, et une grande frayeur s\'empara de ceux qui les contemplaient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Et ils entendirent une voix forte sortant du ciel, qui disait: « Montez ici, » et ils montèrent au ciel dans la nuée, et leurs ennemis les ont contemplés.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'Et à cette heure-là il se fit un grand tremblement de terre, et la dixième partie de la ville croula, et sept mille personnes périrent par le tremblement de terre, et les autres furent remplis de crainte, et ils donnèrent gloire au Dieu du ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Le second malheur est passé. Voici, le troisième malheur va venir promptement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Et le septième ange sonna de la trompette, et il y eut dans le ciel de fortes voix qui disaient: « Le royaume du monde a été remis à notre Seigneur et à Son Christ, et Il régnera aux siècles des siècles. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Et vingt-quatre anciens, assis devant Dieu, sur leurs trônes, se prosternèrent sur leurs visages et adorèrent Dieu en disant:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'Nous Te rendons grâces, Seigneur Dieu tout-puissant, qui es et qui étais, De ce que Tu as pris Ta grande puissance, Et de ce que Tu as régné!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Et les nations se sont irritées, Et Ta colère est survenue, Et aussi le moment pour que les morts soient jugés, Et pour que Tu récompenses Tes esclaves les prophètes, Et pour que les saints, et ceux qui craignent Ton nom, Petits et grands, Détruisent ceux qui détruisent la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Alors le sanctuaire de Dieu qui est dans le ciel s\'ouvrit, et l\'on vit l\'arche de Son alliance dans Son sanctuaire, et il y eut des éclairs, et des voix, et des tonnerres, et un tremblement de terre, et une forte grêle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Et un grand prodige apparut dans le ciel: Une femme enveloppée du soleil, et la lune sous ses pieds, et sur sa tête une couronne de douze étoiles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Et se trouvant enceinte, elle pousse des cris étant au mal d\'enfant et dans les souffrances de l\'enfantement.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Et un autre prodige apparut dans le ciel, et voici, un grand dragon rouge, ayant sept têtes et dix cornes, et sur ses têtes sept diadèmes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'Et sa queue entraîne le tiers des étoiles du ciel, et elle les a précipitées sur la terre; et le dragon se tint debout devant la femme qui allait enfanter, afin de dévorer son enfant quand elle aurait enfanté.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Et elle enfanta un fils mâle, qui doit paître toutes les nations avec une verge de fer; et son enfant fut enlevé auprès de Dieu et auprès de Son trône;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'et la femme s\'enfuit au désert, où elle possède une place que Dieu a préparée, afin qu\'on l\'y nourrisse pendant mille deux cent soixante jours.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Et il y eut guerre dans le ciel: Michel et ses anges pour combattre le dragon, et le dragon combattit ainsi que ses anges,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'et il ne fut pas le plus fort et l\'on ne trouva même plus leur place dans le ciel.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Et il fut précipité, le grand dragon, l\'ancien serpent, celui qui est appelé le diable et Satan, celui qui séduit l\'univers entier, il fut précipité sur la terre, et ses anges furent précipités avec lui.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Et j\'entendis dans le ciel une voix forte qui disait: « Maintenant il est arrivé, le salut, Et la puissance et le royaume de notre Dieu, Et l\'autorité de Son Christ! Car il a été précipité, l\'accusateur de nos frères, Celui qui les accusait devant notre Dieu jour et nuit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Et c\'est eux qui l\'ont vaincu, A cause du sang de l\'agneau, Et de la parole de leur témoignage; Et ils n\'ont pas préféré leur vie à la mort,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'C\'est pourquoi réjouissez-vous, ô cieux, Et vous qui les habitez! Malheur à la terre et à la mer! Car le diable est descendu vers vous, Plein d\'une grande fureur, Sachant qu\'il a peu de temps. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Et quand le dragon vit qu\'il avait été précipité sur la terre, il se mit à la poursuite de la femme qui avait enfanté l\'enfant mâle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Et les deux ailes du grand aigle furent données à la femme, afin qu\'elle s\'envolât vers le désert dans la place qui lui est destinée, où elle doit être nourrie pendant un temps et des temps et la moitié d\'un temps, loin de la présence du serpent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Et le serpent lança de sa bouche derrière la femme une eau comme un fleuve, afin de l\'entraîner dans le fleuve.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Et la terre vint au secours de la femme, et la terre ouvrit sa bouche et engloutit l\'eau que le dragon avait lancée de sa bouche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Et le dragon fut irrité contre la femme, et il s\'en alla faire la guerre aux restes de sa progéniture, à ceux qui observent les commandements de Dieu et qui ont le témoignage de Jésus;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Et je vis monter de la mer une bête qui avait dix cornes et sept têtes, et sur ses cornes dix diadèmes, et sur ses têtes des noms de blasphème.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Et la bête que je vis était semblable à un léopard; et ses pieds étaient comme ceux d\'un ours, et sa gueule comme une gueule de lion.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Et le dragon lui donna sa puissance et son trône, et une grande autorité. Et je vis une de ses têtes comme frappée à mort, mais sa blessure mortelle fut guérie, et la terre entière fut dans l\'admiration derrière la bête;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'et ils adorèrent le dragon parce qu\'il avait donné l\'autorité à la bête; et ils adorèrent la bête en disant: « Qui est-ce qui est semblable à la bête, et qui est-ce qui peut combattre avec elle? »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Et il lui fut donné une bouche qui profère des paroles arrogantes et blasphématoires; et il lui fut donné autorité d\'agir pendant quarante-deux mois.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Et elle ouvrit sa bouche en blasphèmes contre Dieu, pour blasphémer Son nom et ceux qui, dans le ciel, dressent Son tabernacle.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Et il lui fut donné autorité sur toute tribu, et peuple, et langue, et nation.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Et tous les habitants de la terre l\'adoreront, ceux dont le nom n\'a pas été écrit dans le livre de vie de l\'agneau immolé dès la fondation du monde.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Si quelqu\'un a une oreille, qu\'il entende:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Quiconque mène en captivité, en captivité s\'en va; quiconque met à mort par l\'épée, il faut qu\'il soit mis à mort par l\'épée. Ici se trouve la constance et la foi des saints.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Et je vis une autre bête qui montait de la terre, et elle avait deux cornes semblables à celles d\'un agneau, et elle parlait comme un dragon;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'et elle exerce toute l\'autorité de la première bête sous ses yeux; et elle agit pour que la terre et tous ses habitants adorent la première bête, dont la blessure mortelle a été guérie;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'et elle opère de grands prodiges, jusques à faire même descendre du ciel du feu sur la terre en présence des hommes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'et elle égare les habitants de la terre grâce aux prodiges qu\'il lui a été donné d\'opérer sous les yeux de la bête, disant aux habitants de la terre de faire une image à la bête qui a reçu la blessure de l\'épée, et qui a repris vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Et il lui fut donné d\'animer l\'image de la bête, afin que l\'image de la bête parlât même et qu\'elle agît pour que tous ceux qui n\'adoreraient pas l\'image de la bête fussent mis à mort.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Et elle agit pour qu\'à tous, aux petits et aux grands, et aux riches et aux pauvres, et aux libres et aux esclaves, on leur imprime une marque sur leur main droite ou sur leur front,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'et pour que personne ne puisse acheter ou vendre, sinon celui qui a la marque, le nom de la bête, ou le nombre de son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'C\'est ici que se montre la sagesse: que celui qui a de l\'intelligence calcule le nombre de la bête; car c\'est le nombre d\'un homme, et son nombre est six cent soixante-six.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Et je vis, et voici, l\'agneau se tenait debout sur la montagne de Sion, et avec lui cent quarante-quatre mille personnes ayant son nom et le nom de son Père écrits sur leurs fronts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Et j\'entendis une voix venant du ciel, comme un bruit de grosses eaux et comme le bruit d\'un grand tonnerre, et la voix que j\'entendis était comme celle de musiciens qui jouent sur leurs harpes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'et ils chantent comme un hymne nouveau devant le trône, et devant les quatre animaux et les anciens. Et personne ne pouvait apprendre l\'hymne, sinon les cent quarante-quatre mille, les rachetés de la terre');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'qui ne se sont point souillés avec des femmes, car ils sont vierges. Ceux-ci, qui suivent l\'agneau partout où il va, ceux-ci ont été rachetés d\'entre les hommes, comme des prémices pour Dieu et pour l\'agneau;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'et dans leur bouche il ne s\'est point trouvé de mensonge; ils sont irrépréhensibles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Et je vis un autre ange volant dans le milieu du ciel, portant un évangile éternel pour annoncer une bonne nouvelle aux habitants de la terre, et à toute nation, et tribu, et langue, et peuple,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'en disant d\'une voix forte: « Craignez Dieu et Lui donnez gloire, Car l\'heure de Son jugement est arrivée, Et adorez Celui qui a fait le ciel et la terre, Et la mer et les sources d\'eau, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Et un autre, un second ange suivit, qui disait: « Elle est tombée, elle est tombée, Babylone la grande, Qui, du vin capiteux de son impudicité, A abreuvé toutes les nations, »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Et un autre, un troisième ange le suivit, qui disait, d\'une voix forte:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, '« Quiconque adore la bête et son image, et reçoit une marque sur son front ou sur sa main,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'lui aussi boira du vin capiteux de Dieu qui a été préparé sans mélange dans la coupe de Sa colère. Et ils seront tourmentés dans le feu et le soufre en présence des anges, et en présence de l\'agneau; et la fumée de leur tourment monte aux siècles des siècles, et ils n\'ont de repos, ni jour ni nuit, ceux qui adorent la bête et son image, et quiconque reçoit la marque de son nom.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Ici se trouve la constance des saints, qui observent les commandements de Dieu et la foi de Jésus. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Et j\'entendis une voix venant du ciel qui disait: « Écris: Heureux les morts qui meurent dans le Seigneur, dès maintenant! Oui, dit l\'Esprit; c\'est pour qu\'ils se reposent de leurs peines, car leurs œuvres les suivent. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Et je vis, et voici, un nuage blanc, et sur ce nuage était assis quelqu\'un de semblable à un fils d\'homme; il avait sur la tête une couronne et dans la main une faucille tranchante.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Et un autre ange sortit du sanctuaire, criant d\'une voix forte à celui qui était assis sur le nuage: « Lance ta faucille, et moissonne, car le moment de moissonner est venu, car la moisson de la terre est desséchée. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Et celui qui était assis sur le nuage jeta sa faucille sur la terre, et la terre fut moissonnée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Et un autre ange sortit du sanctuaire qui est dans le ciel, tenant aussi une faucille tranchante,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'et un autre ange d\'auprès de l\'autel (c\'est celui qui a autorité sur le feu) s\'adressa d\'une voix forte à celui qui tenait la faucille tranchante, en disant: « Lance ta faucille tranchante, et vendange les grappes de la vigne de la terre, car ses raisins ont mûri. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Et l\'ange jeta sa faucille sur la terre, et il vendangea la vigne de la terre; et il jeta la vendange dans le grand pressoir du courroux de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'Et le pressoir fut foulé hors de la ville, et il sortit du sang du pressoir jusques aux mors des chevaux, sur un espace de mille six cent stades.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Et je vis dans le ciel un autre prodige grand et merveilleux: sept anges tenant les sept fléaux, qui sont les derniers, parce qu\'en eux est consommé le courroux de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Et je vis comme une mer vitreuse mêlée de feu, et les vainqueurs de la bête, et de son image, et du nombre de son nom, debout sur la mer vitreuse, ayant les harpes de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'et ils chantent l\'hymne de Moïse l\'esclave de Dieu, et l\'hymne de l\'agneau, en disant: « Grandes et merveilleuses sont Tes œuvres, Seigneur Dieu tout-puissant! Justes et véritables sont Tes voies, O Roi des nations!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Qui ne craindrait, Seigneur, et ne glorifiera Ton nom? Car seul Tu es saint. C\'est pourquoi toutes les nations viendront, Et elles se prosterneront devant Toi, Seigneur, Parce que Tes décrets ont été manifestés. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Et après cela je vis, et le sanctuaire du tabernacle du témoignage s\'ouvrit dans le ciel;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'et les sept anges qui tenaient les sept fléaux, sortirent du sanctuaire vêtus d\'une pierre d\'un pur éclat, et ceints autour de leurs poitrines de ceintures d\'or.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Et l\'un des quatre animaux donna aux sept anges sept coupes d\'or pleines du courroux de Dieu qui est vivant aux siècles des siècles;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'et le sanctuaire fut rempli de fumée à cause de la gloire de Dieu et de Sa puissance, et personne ne pouvait entrer dans le sanctuaire, jusques à ce que les sept fléaux des sept anges eussent été accomplis.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Et j\'entendis une voix forte, sortant du sanctuaire, qui disait aux sept anges: « Allez et versez sur la terre les sept coupes du courroux de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Et le premier sortit et versa sa coupe sur la terre, et il y eut un ulcère, et il fut malfaisant pour les hommes qui portaient la marque de la bête et qui adoraient son image.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Et le second versa sa coupe dans la mer, et elle devint comme le sang d\'un mort, et tout être vivant mourut, ceux qui sont dans la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Et le troisième versa sa coupe dans les fleuves et les sources d\'eau, et ils devinrent du sang.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Et j\'entendis l\'ange des eaux qui disait: « Tu es juste, Toi qui es et qui étais saint, d\'avoir rendu ce jugement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'car ils ont versé le sang des saints et des prophètes. Et Tu leur as donné du sang à boire; ils en sont dignes! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Et j\'entendis l\'autel dire: « Oui, Seigneur Dieu tout-puissant, véritables et justes sont Tes jugements! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Et le quatrième versa sa coupe sur le soleil, et il lui fut donné de brûler les hommes par le feu;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'et les hommes furent brûlés d\'une grande brûlure, et ils blasphémèrent en présence de Dieu, qui a autorité sur ces fléaux, et ils ne se repentirent point pour Lui rendre gloire.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Et le cinquième versa sa coupe sur le trône de la bête; et son royaume fut plongé dans les ténèbres; de douleur ils mâchaient leurs langues;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'et ils blasphémèrent le Dieu du ciel à cause de leurs douleurs et de leurs ulcères; et ils ne se repentirent point de leurs œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Et le sixième versa sa coupe sur le grand fleuve, l\'Euphrate, et son eau tarit, afin que fût prête la route des rois qui viennent de l\'Orient.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Et je vis sortir de la bouche du dragon, et de la bouche de la bête, et de la bouche du faux prophète, trois esprits impurs comme des grenouilles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Ce sont en effet des esprits de démons qui font des prodiges. Ils se rendent auprès des rois de l\'univers entier afin de les rassembler pour la bataille du grand jour du Dieu tout-puissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, 'Voici, je viens comme un voleur; heureux celui qui veille et conserve ses vêtements, afin de ne pas marcher nu, et de ne pas laisser voir son indécence. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Et ils les rassemblèrent vers le fleuve qui est appelé en hébreu Harmagédon.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Et le septième versa sa coupe dans les airs, et une voix sortit du sanctuaire d\'auprès du trône, disant: « C\'en est fait! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Et il y eut des éclairs, et des voix, et des tonnerres, et il se fit un grand tremblement de terre, tel qu\'il ne s\'est jamais fait, depuis que l\'homme est sur la terre, un semblable tremblement de terre aussi grand.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'Et la grande ville fut séparée en trois parties, et les villes des nations croulèrent, et il fut fait commémoration de Babylone la grande devant Dieu, pour lui faire boire le calice du vin capiteux de Sa colère.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Et toutes les îles s\'enfuirent, et on ne trouva plus de montagnes;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'et une grêle grosse à peser un talent, descend du ciel sur les hommes, et les hommes blasphémèrent Dieu à cause du fléau de la grêle; car le fléau qu\'elle cause est très grand.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Et un des sept anges qui tiennent les sept coupes sortit, et il s\'adressa à moi en disant: Viens, je te montrerai la condamnation de la grande impudique, qui est assise sur de nombreuses eaux,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'avec laquelle les rois la terre se sont livrés à l\'impudicité; et les habitants de la terre se sont enivrés du vin de son impudicité. » Et il me transporta dans un désert en esprit.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Et je vis une femme assise sur une bête écarlate pleine des noms de blasphème, et ayant sept têtes et dix cornes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Et la femme était revêtue de pourpre et d\'écarlate, et couverte d\'or, de pierres précieuses, et de perles, tenant dans sa main un calice d\'or rempli d\'abominations, et les souillures de son impudicité;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'et sur son front un nom était écrit, mystère: « Babylone la grande, la mère des impudiques et des abominations de la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Et je vis la femme enivrée du sang des saints et du sang des témoins de Jésus, et je fus saisi en la voyant d\'un grand étonnement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'et l\'ange me dit: Pourquoi t\'es-tu étonné? Je te dirai, moi, le mystère de la femme et de la bête qui la porte, qui a sept têtes et dix cornes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, '« La bête que tu as vue était, et elle n\'est plus, et elle va remonter de l\'abîme, et elle s\'en va à la perdition; et les habitants de la terre, dont le nom n\'a pas été écrit dans le livre de vie dès la fondation du monde, seront étonnés en voyant la bête, parce qu\'elle était, et qu\'elle n\'est plus, et qu\'elle reparaîtra.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'C\'est ici que se montre l\'intelligence douée de sagesse: les sept têtes sont sept montagnes sur lesquelles la femme est assise.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'Ce sont aussi sept rois; les cinq premiers sont tombés, l\'un subsiste, l\'autre n\'est pas encore venu, et quand il sera venu, il faut qu\'il dure peu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Et la bête, qui était et qui n\'est plus, est aussi elle-même le huitième, et elle est l\'un des sept, et elle s\'en va à la perdition.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Et les dix cornes que tu as vues sont dix rois qui n\'ont pas reçu de royaume, mais pendant une heure ils reçoivent autorité comme des rois avec la bête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Ils n\'ont qu\'une seule et même pensée, et ils donnent leur puissance et leur autorité à la bête.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Ils combattront contre l\'agneau, et l\'agneau les vaincra, parce qu\'il est Seigneur des seigneurs et Roi des rois, ainsi que ceux qui sont avec lui, les appelés, les élus et les fidèles. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Et il me dit: Les eaux que tu as vues, où l\'impudique est assise, sont des peuples, et des foules, et des nations, et des langues.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Et les dix cornes que tu as vues et la bête, elles haïront l\'impudique, et elles la dévasteront et la mettront à nu, et elles mangeront ses chairs, et elles la consumeront par le feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Car Dieu a mis dans leurs cœurs d\'exécuter Sa pensée, et de donner la royauté à la bête même, jusques à ce que les paroles de Dieu soient accomplies.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Et la femme que tu as vue est la grande ville, qui possède la royauté sur les rois de la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Après cela je vis un autre ange, descendant du ciel, ayant une grande autorité, et la terre fut illuminée de sa gloire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'et il s\'écria d\'une voix puissante: Elle est tombée, elle est tombée, Babylone la grande! Elle est devenue un habitacle de démons, et une prison pour tout esprit impur et odieux, et une prison pour toute bête impure et odieuse,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'parce que, grâce à l\'ardeur de son impudicité, toutes les nations sont tombées, et que les rois de la terre se sont livrés avec elle à l\'impudicité, et que les marchands de la terre se sont enrichis par la puissance de son luxe. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Et j\'entendis une autre voix venant du ciel qui disait: « Sortez du milieu d\'elle, mon peuple, afin que vous ne preniez point part à ses péchés, et que vous n\'ayez point à souffrir de ses fléaux;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'car ses péchés se sont accumulés jusques au ciel, et Dieu s\'est souvenu de ses iniquités!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Payez la comme elle-même a payé, et doublez deux fois en raison de ses propres œuvres; dans le calice qu\'elle a préparé, préparez-lui une double rasade;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'autant elle s\'est glorifiée et plongée dans le luxe, autant donnez-lui de tourment et de deuil; car elle dit en son cœur: Je trône en reine et je ne suis point veuve, et je ne connaîtrai certainement pas le deuil.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'C\'est pour cela qu\'en un seul jour ses fléaux fondront sur elle: la mort, le deuil et la famine, et elle sera consumée par le feu; car Il est puissant le Dieu qui l\'a jugée!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Et les rois de la terre, qui se sont livrés avec elle à l\'impudicité et au luxe, pleureront et se lamenteront sur elle, quand ils verront la fumée de son embrasement,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'se tenant à distance par crainte de son tourment, en disant: Malheur, malheur, ô la grande ville, ô Babylone, la ville puissante; car en une seule heure est survenue ta condamnation!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Et les marchands de la terre pleurent et sont dans le deuil au milieu d\'elle, parce que personne n\'achète plus leur cargaison:');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'cargaison d\'or, et d\'argent, et de pierres précieuses, et de perles, et de fin lin, et de soie, et d\'écarlate; et toute espèce d\'ustensiles en thuya, et toute espèce d\'ustensiles en ivoire, et toute espèce d\'ustensiles en pierre très précieuse, et en airain, et en fer, et en marbre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'et l\'encens, et les épices, et les parfums, et la myrrhe, et l\'essence, et le vin, et l\'huile, et la fine farine, et le blé, et le gros et le menu bétail; et cargaison de chevaux, et de chars, et de corps; et des vies humaines.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Et le fruit que convoitait ton âme s\'est éloigné de toi; et toutes les magnificences et les splendeurs t\'ont été ravies, et ils ne les retrouveront certainement plus.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Les marchands de ces choses, qui se sont enrichis grâce à elle, se tiendront à distance, par crainte de son tourment, dans les larmes et dans le deuil,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'en disant: Malheur, malheur, ô la grande ville revêtue d\'écarlate, et de pourpre et de fin lin, et couverte d\'or, et de pierres précieuses et de perles; car en une seule heure toute cette grande richesse a été détruite!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'Et tous les pilotes et tous ceux qui naviguent dans cette direction, et les matelots, et tous ceux qui exploitent la mer se tinrent à distance,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'et ils s\'écrièrent en voyant la place de son embrasement: Laquelle est semblable à la grande cité?');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Et ils jetèrent de la poussière sur leurs têtes, et ils s\'écrièrent: Malheur, malheur, ô la grande ville, où se sont enrichis, grâce à son opulence, tous ceux qui possèdent les vaisseaux sur la mer; car en une seule heure elle a été détruite!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Réjouis-toi à son sujet, ô ciel, et vous les saints, et les apôtres, et les prophètes! Car, en la jugeant, Dieu vous a fait justice. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Alors un ange souleva une pierre semblable à une grande meule de moulin, et il la jeta dans la mer, en disant: « C\'est ainsi qu\'avec violence sera précipitée Babylone, la grande ville; on ne la trouvera certainement plus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'Et la voix des joueurs de harpes, et des musiciens, et des joueurs de flûte et de trompette, ne sera certainement plus ouïe au milieu de toi; et aucun artisan ne sera certainement plus trouvé chez toi; et le bruit du moulin ne sera certainement plus ouï chez toi,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'et la voix de l\'époux et de l\'épouse ne sera certainement plus ouïe chez toi. C\'est que les grands de la terre étaient tes marchands, c\'est que toutes les nations ont été égarées par tes sortilèges.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'Et l\'on a trouvé chez elle le sang des prophètes et des saints, et de tous ceux qui ont été égorgés sur la terre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Après cela j\'entendis comme une forte voix d\'une foule nombreuse dans le ciel, de gens qui disaient: « Allélouia! Le salut et la gloire, et la force appartiennent à notre Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Parce que Ses jugements sont justes et véritables; Car Il a jugé la grande impudique Qui a corrompu la terre par son impudicité, Et Il a vengé sur elle le sang de Ses esclaves. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Et ils dirent une seconde fois: « Allélouia! » Et sa fumée monte aux siècles des siècles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Et les vingt-quatre anciens se prosternèrent, ainsi que les quatre animaux, et ils adorèrent Dieu assis sur le trône, en disant: « Amen, Allélouia! »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Et une voix sortit du trône, disant: « Louez notre Dieu, vous tous qui êtes Ses esclaves et qui Le craignez, petits et grands. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Et j\'entendis comme la voix d\'une foule nombreuse, et la voix de nombreuses eaux, et comme la voix de forts tonnerres, disant: « Allélouia! Car Il a régné le Seigneur Dieu, le Tout-Puissant!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Réjouissons-nous et soyons dans l\'allégresse, Et nous Lui donnerons gloire; Car les noces de l\'agneau sont survenues, Et son épouse s\'est préparée,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'Et il lui a été donné de revêtir un fin lin d\'une éclatante pureté; Car le fin lin, c\'est la justification des saints. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'Et il me dit: « Écris: Heureux ceux qui ont été appelés au festin de noces de l\'agneau. » Et il me dit: « Ces paroles sont les véritables paroles de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Et je tombai à ses pieds pour l\'adorer, et il me dit: « Garde-toi de le faire; je suis ton compagnon de service et celui de tes frères qui possèdent le témoignage de Jésus. Adore Dieu; car le témoignage de Jésus est l\'Esprit de la prophétie. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Et je vis le ciel ouvert, et voici, un cheval blanc, et celui qui était assis dessus est fidèle et véritable, et c\'est avec justice qu\'il juge et qu\'il combat.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Or ses yeux étaient comme une flamme de feu, et sur sa tête il y avait plusieurs diadèmes; il avait un nom écrit que personne ne connaît que lui-même,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'et il était revêtu d\'un vêtement teint de sang, et le nom dont il a été appelé est: « La Parole de Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Et les armées qui sont dans le ciel le suivaient sur des chevaux blancs, revêtues de fin lin d\'une pure blancheur;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'et de sa bouche sort un glaive acéré, afin qu\'il en frappe les nations; et lui-même les paîtra avec une verge de fer; et c\'est lui qui foule le pressoir du vin capiteux de la colère du Dieu tout-puissant.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Et il porte sur sa cuisse un nom écrit: « Roi des rois et Seigneur des seigneurs. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Et je vis un ange qui se tenait debout dans le soleil, et il cria d\'une voix forte, en s\'adressant à tous les oiseaux qui volent dans le milieu du ciel: « Venez, rassemblez-vous pour le grand festin de Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'afin de manger les chairs des rois, et les chairs des généraux, et les chairs des hommes vaillants, et les chairs des chevaux et de ceux qui sont assis dessus, et les chairs de tous les hommes, soit libres soit esclaves, soit petits soit grands. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Et je vis la bête, et les rois de la terre, et ses armées rassemblées pour faire la guerre contre celui qui était assis sur le cheval et contre son armée.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Et la bête fut prise ainsi que ceux qui étaient avec elle, le faux prophète qui a opéré en sa présence les prodiges, par lesquels il a égaré ceux qui ont reçu la marque de la bête et qui adorent son image. Ils furent tous les deux jetés vivants dans l\'étang de feu tout brûlant de soufre;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'et les autres furent mis à mort par le glaive de celui qui était assis sur le cheval, le glaive qui sort de sa bouche; et tous les oiseaux s\'assouvirent de leurs chairs.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Et je vis un ange descendre du ciel, tenant la clef de l\'abîme et une grande chaîne dans sa main.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Et il se saisit du dragon, l\'ancien serpent, qui est le diable et Satan, et il le lia pour mille ans;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'et il le jeta dans l\'abîme, et il l\'enferma et le scella d\'une manière permanente, afin qu\'il n\'égarât plus les nations, jusques à ce que les mille ans eussent été accomplis: après cela il faut qu\'il soit délié pour un peu de temps.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Et je vis des trônes; et ils s\'assirent dessus, et il leur fut donné d\'exercer le jugement; et je vis aussi les âmes de ceux auxquels on a fait la guerre à cause du témoignage de Jésus et de la parole de Dieu, et ceux entre autres qui n\'ont point adoré la bête ni son image, et qui n\'ont pas reçu sa marque sur leur front ni sur leur main; et ils vécurent et ils régnèrent avec le Christ pendant mille ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Les autres morts ne vécurent point jusques à ce que les mille ans eussent été accomplis. C\'est là la première résurrection.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Heureux et saint celui qui a part à la première résurrection! La seconde mort n\'a aucune autorité sur eux, mais ils seront prêtres de Dieu et du Christ, et ils règnent avec lui pendant mille ans.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Et, quand les mille ans auront été accomplis, Satan sera élargi de sa prison,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'et il sortira pour égarer les nations qui sont aux quatre coins de la terre, Gog et Magog, pour les rassembler pour la guerre, eux dont le nombre est comme le sable de la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Et ils montèrent sur la largeur de la terre, et ils investirent le camp des saints et la ville bien-aimée, et du feu descendit du ciel et il les consuma;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'et le diable qui les égare fut jeté dans l\'étang de feu et de soufre, où sont aussi la bête et le faux prophète, et ils seront tourmentés jour et nuit aux siècles des siècles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Et je vis un grand trône blanc et Celui qui y était assis; de devant la face duquel s\'enfuirent la terre et le ciel, et pour eux on ne trouva pas de place.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Et je vis les morts, les grands et les petits, se tenant debout devant le trône, et des livres furent ouverts; et un autre livre fut ouvert, qui est le livre de vie, et les morts furent jugés selon leurs œuvres d\'après ce qui est écrit dans les livres;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'et la mer rendit les morts qu\'elle renferme, et la mort et le séjour des morts rendirent les morts qu\'ils renferment, et ils furent jugés chacun selon leurs œuvres.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Et la mort et le séjour des morts furent jetés dans l\'étang de feu. C\'est là la seconde mort, l\'étang de feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Et quiconque ne fut pas trouvé inscrit dans le livre de vie fut jeté dans l\'étang de feu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Et je vis un nouveau ciel et une nouvelle terre, car le premier ciel et la première terre ont disparu, et je ne vis plus la mer.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Et je vis la ville sainte, Jérusalem nouvelle, descendant du ciel d\'auprès de Dieu, préparée comme une épouse qui s\'est faite belle pour son mari,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'et j\'entendis sortir du trône une voix forte qui disait: « Voici le tabernacle de Dieu dressé parmi les hommes, Et Il habitera avec eux, et ils seront Ses peuples, Et Dieu Lui-même sera avec eux comme leur Dieu,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Et Dieu essuiera toute larme de leurs yeux. Et la mort ne sera plus; Il n\'y aura plus ni deuil, ni cris, ni peine. Les premières choses ont disparu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Et Celui qui est assis sur le trône dit: « Eh bien, voici, Je renouvelle toutes choses. » Et il dit: Écris, car ces paroles sont dignes de foi et véritables. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Et Il me dit: « C\'est fait. C\'est Moi qui suis l\'alpha et l\'oméga, le commencement et la fin; à celui qui a soif Je donnerai gratuitement de l\'eau de la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Le vainqueur possédera ces choses, et Je serai leur Dieu et il sera pour Moi un fils;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'mais quant aux lâches, et aux infidèles, et aux abominables, et aux meurtriers, et aux impudiques, et aux magiciens, et aux idolâtres et à tous les menteurs, ils auront en partage l\'étang tout brûlant de feu et de soufre: ce qui est la seconde mort. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Et l\'un d\'entre les sept anges qui tiennent les sept coupes qui sont remplies des sept derniers fléaux survint, et s\'adressant à moi il me dit: « Viens, je te montrerai l\'épouse, la femme de l\'agneau. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Et il me transporta en esprit sur une grande et haute montagne, et il me montra la ville sainte, Jérusalem, descendant du ciel d\'auprès de Dieu.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'Son luminaire était semblable à une pierre de très grand prix, comme à une pierre de jaspe cristallin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Elle avait une grande et haute muraille; elle avait douze portes, et des noms écrits, qui sont les noms des douze tribus des fils d\'Israël.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Du côté de l\'orient trois portes, et du côté du nord trois portes, et du côté de l\'occident trois portes, et du côté du midi trois portes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'Et la muraille de la ville a douze bases et sur elles les douze noms des douze apôtres de l\'agneau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Et celui qui me parlait avait pour mesure un roseau d\'or, afin de mesurer la ville, et ses portes, et sa muraille;');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'et la ville forme un carré, et sa longueur égale sa largeur; et il mesura la ville avec son roseau, ce qui donna douze mille stades. La longueur et la largeur et la hauteur en sont égales.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Et il mesura sa muraille, ce qui donna cent quarante-quatre coudées, mesure d\'homme, qui est celle de l\'ange.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Et les matériaux de sa muraille étaient de jaspe, et la ville était d\'or pur, semblable à du pur cristal.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Les bases de la muraille de la ville étaient ornées de toute espèce de pierres précieuses: la première base était de jaspe, la seconde de saphir, la troisième de chalcédoine, la quatrième d\'émeraude,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'la cinquième de sardonyx, la dixième de sardoine, la septième de chrysolithe, la huitième de bérylle, la neuvième de topaze, la dixième de chrysopras, la onzième de hyacinthe, la douzième d\'améthyste.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Et les douze portes étaient douze perles; chaque porte prise à part était d\'une seule perle; et la grande rue de la ville était d\'or pur, comme du cristal transparent.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Et je n\'y vis point de sanctuaire; car le Seigneur Dieu, le Tout-Puissant, est son sanctuaire, ainsi que l\'agneau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'Et la ville n\'a besoin ni du soleil ni de la lune, pour qu\'ils l\'éclairent; car la gloire de Dieu l\'a illuminée et l\'agneau est son flambeau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Et les nations marcheront à sa lumière, et les rois transportent chez elle leur gloire,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'et ses portes ne seront point fermées de jour (car il n\'y aura là pas de nuit),');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'et ils apporteront chez elle la gloire et l\'honneur des nations.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'Et il n\'entrera certainement chez elle rien de souillé, ni personne qui pratique l\'abomination et le mensonge, mais seulement ceux qui sont inscrits dans le livre de vie de l\'agneau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Et il me montra un fleuve d\'eau vive, clair comme du cristal, qui sortait du trône de Dieu et de l\'agneau.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Entre sa grande rue et le fleuve, d\'ici et de là, est un arbre de vie qui porte douze récoltes, donnant chaque mois sa récolte, et les feuilles de l\'arbre servent à la guérison des nations,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'et il n\'y aura plus de malédiction. Et le trône de Dieu et de l\'agneau sera au milieu d\'elle; et Ses esclaves L\'adoreront');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'et contempleront Sa face; et Son nom sera sur leurs fronts.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Et il n\'y aura plus de nuit; et ils n\'auront besoin ni de la lumière de la lampe, ni de la lumière du soleil, parce que le Seigneur Dieu les illuminera, et ils régneront aux siècles des siècles.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Et il me dit: « Ces paroles sont dignes de foi et véritables, et le Seigneur, qui est le Dieu des esprits des prophètes, a envoyé Son ange pour montrer à Ses esclaves ce qui doit arriver au plus tôt.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Et voici, je viens bientôt. Heureux celui qui observe les paroles de la prophétie de ce livre. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Et c\'est moi, Jean, qui entendais et regardais ces choses; et lorsque j\'eus entendu et que j\'eus vu, je me prosternai, pour adorer, aux pieds de l\'ange qui me montrait ces choses.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Et il me dit: « Garde-toi de le faire! Je suis ton compagnon de service et celui de tes frères les prophètes et de ceux qui observent les paroles de ce livre: Adore Dieu. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Et il me dit: « Ne scelle point les paroles de la prophétie de ce livre; car le moment est proche.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Que celui qui commet l\'injustice continue à la commettre, et que le juste continue à pratiquer la justice, et que celui qui est saint continue à se sanctifier.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Voici, je viens bientôt, et ma rétribution est avec moi pour rendre à chacun selon ce qu\'est son œuvre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'C\'est moi qui suis l\'alpha et l\'oméga, le premier et le dernier, le commencement et la fin.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Heureux ceux qui blanchissent leurs robes, afin d\'avoir droit sur l\'arbre de vie et d\'entrer dans la ville par les portes.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Dehors les chiens, et les magiciens, et les impudiques, et les meurtriers, et les idolâtres, et tous ceux qui aiment et qui pratiquent le mensonge!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'C\'est moi, Jésus, qui ai envoyé mon ange pour vous attester ces choses dans les Églises. Je suis la racine et la race de David, l\'étoile brillante et matinale. »');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'Et l\'Esprit et l\'épouse disent: « Viens. » Et que celui qui entend dise: « Viens. » Et que celui qui a soif vienne. Que celui qui le veut prenne gratuitement de l\'eau de la vie.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Pour moi j\'atteste à tous ceux qui entendent les paroles de la prophétie de ce livre, que si quelqu\'un y ajoute, Dieu lui ajoutera les fléaux décrits dans ce livre,');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'et que si quelqu\'un retranche quelque chose des paroles du livre de cette prophétie, Dieu retranchera sa part de l\'arbre de vie et de la ville sainte, qui sont décrits dans ce livre.');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Celui qui atteste ces choses dit: « Oui, je viens bientôt. » Amen! Viens, Seigneur Jésus!');
INSERT INTO `FrePGR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'La grâce du Seigneur Jésus soit avec tous!');
