            CREATE TABLE IF NOT EXISTS `translations` (
                `translation` VARCHAR(255) PRIMARY KEY,
                `title` VARCHAR(255),
                `license` TEXT
            );
            

            VALUES ('FrePGR', '# FrePGR: Bible Perret-Gentil et Rilliet', 'Public Domain')
            ON DUPLICATE KEY UPDATE
                `title` = VALUES(`title`),
                `license` = VALUES(`license`);
            

            CREATE TABLE `FrePGR_books` (
                `id` INT AUTO_INCREMENT PRIMARY KEY,
                `name` VARCHAR(255)
            );
            

            CREATE TABLE `FrePGR_verses` (
                `id` INT AUTO_INCREMENT PRIMARY KEY,
                `book_id` INT,
                `chapter` INT,
                `verse` INT,
                `text` TEXT,
                FOREIGN KEY (book_id) REFERENCES `FrePGR_books`(id)
